FUNCTION_BLOCK FB_BESS_Microgrid_Manager
TITLE = 'Utility-Scale BESS Microgrid Controller'
VERSION : '1.1'

VAR_INPUT
    bGridAvailable      : BOOL;   (* Main grid voltage and frequency within nominal limits *)
    bBlackStartCmd      : BOOL;   (* Operator or automated command to initiate black start *)
    bPccBreakerStatus   : BOOL;   (* Point of Common Coupling breaker closed feedback *)
    fGridVoltage        : REAL;   (* Grid voltage magnitude (pu) *)
    fGridPhaseAngle     : REAL;   (* Grid phase angle from PLL (rad) *)
    fMicrogridVoltage   : REAL;   (* Microgrid voltage magnitude (pu) *)
    fMicrogridPhase     : REAL;   (* Microgrid phase angle (rad) *)
    fTotalLoadkW        : REAL;   (* Total microgrid load demand *)
    aStringSOC          : ARRAY[1..8] OF REAL; (* State of Charge for 8 BESS strings 0-100% *)
    aStringAvailable    : ARRAY[1..8] OF BOOL; (* Availability of BESS strings *)
END_VAR

VAR_OUTPUT
    bCmdPccBreaker      : BOOL;   (* Command to close PCC breaker *)
    bInverterModeGridForm : BOOL; (* TRUE = Grid-Forming (V/f), FALSE = Grid-Following (PQ) *)
    fPrefTotal          : REAL;   (* Total Active Power Reference (kW) *)
    fQrefTotal          : REAL;   (* Total Reactive Power Reference (kVAR) *)
    aStringPLimits      : ARRAY[1..8] OF REAL; (* Power limit per string based on SOC *)
    aLoadShedRelays     : ARRAY[1..4] OF BOOL; (* TRUE = Shed Load (Disconnect) *)
    nSystemState        : INT;    (* Current operational state *)
END_VAR

VAR
    (* State Machine Constants *)
    ST_INIT          : INT := 0;
    ST_GRID_CONN     : INT := 1;
    ST_ISLANDING     : INT := 2;
    ST_ISLANDED      : INT := 3;
    ST_BLACK_START   : INT := 4;
    ST_RESYNC        : INT := 5;

    (* Internal Variables *)
    i                : INT;
    fAvgSOC          : REAL;
    nActiveStrings   : INT;
    fPhaseError      : REAL;
    fVoltageError    : REAL;

    (* Timers *)
    tIslandingDelay  : TON;
    tResyncTimer     : TON;
    tLoadStepTimer   : TON;
    nLoadStepCounter : INT;
END_VAR

(* 1. SOC Balancing Algorithm *)
fAvgSOC := 0.0;
nActiveStrings := 0;
FOR i := 1 TO 8 DO
    IF aStringAvailable[i] THEN
        fAvgSOC := fAvgSOC + aStringSOC[i];
        nActiveStrings := nActiveStrings + 1;
    END_IF;
END_FOR;

IF nActiveStrings > 0 THEN
    fAvgSOC := fAvgSOC / INT_TO_REAL(nActiveStrings);
END_IF;

FOR i := 1 TO 8 DO
    IF aStringAvailable[i] THEN
        (* Dynamic power limit scaling based on SOC deviation *)
        IF bInverterModeGridForm THEN
            (* In grid-forming, balance discharge based on SOC *)
            aStringPLimits[i] := 1.0 + ((aStringSOC[i] - fAvgSOC) * 0.05); 
        ELSE
            aStringPLimits[i] := 1.0; 
        END_IF;

        (* Hard limits *)
        IF aStringPLimits[i] > 1.2 THEN aStringPLimits[i] := 1.2; END_IF;
        IF aStringPLimits[i] < 0.1 THEN aStringPLimits[i] := 0.1; END_IF;
    ELSE
        aStringPLimits[i] := 0.0;
    END_IF;
END_FOR;

(* 2. Main State Machine *)
CASE nSystemState OF
    ST_INIT:
        bCmdPccBreaker := FALSE;
        bInverterModeGridForm := FALSE;
        aLoadShedRelays[1] := TRUE; 
        aLoadShedRelays[2] := TRUE;
        aLoadShedRelays[3] := TRUE;
        aLoadShedRelays[4] := TRUE;

        IF bGridAvailable AND bPccBreakerStatus THEN
            nSystemState := ST_GRID_CONN;
        ELSIF bBlackStartCmd THEN
            nSystemState := ST_BLACK_START;
        END_IF;

    ST_GRID_CONN:
        bInverterModeGridForm := FALSE;
        aLoadShedRelays[1] := FALSE;
        aLoadShedRelays[2] := FALSE;

        IF NOT bGridAvailable THEN
            tIslandingDelay(IN:= TRUE, PT:= T#50MS);
            IF tIslandingDelay.Q THEN
                bCmdPccBreaker := FALSE;
                nSystemState := ST_ISLANDING;
            END_IF;
        ELSE
            tIslandingDelay(IN:= FALSE, PT:= T#50MS);
        END_IF;

    ST_ISLANDING:
        IF NOT bPccBreakerStatus THEN
            bInverterModeGridForm := TRUE; (* Seamless transition to V/f *)
            nSystemState := ST_ISLANDED;
        END_IF;

    ST_ISLANDED:
        (* Critical load management during islanded mode *)
        IF fAvgSOC < 20.0 THEN
            aLoadShedRelays[3] := TRUE; (* Shed medium priority *)
        END_IF;
        IF fAvgSOC < 10.0 THEN
            aLoadShedRelays[2] := TRUE; (* Shed high priority *)
        END_IF;

        IF bGridAvailable THEN
            nSystemState := ST_RESYNC;
        END_IF;

    ST_BLACK_START:
        bInverterModeGridForm := TRUE;
        bCmdPccBreaker := FALSE;

        (* Sequenced Load Restoration *)
        tLoadStepTimer(IN:= TRUE, PT:= T#5S);
        IF tLoadStepTimer.Q THEN
            tLoadStepTimer(IN:= FALSE, PT:= T#5S);
            nLoadStepCounter := nLoadStepCounter + 1;
        END_IF;

        IF nLoadStepCounter = 1 THEN aLoadShedRelays[1] := FALSE; END_IF;
        IF nLoadStepCounter = 2 THEN aLoadShedRelays[2] := FALSE; END_IF;
        IF nLoadStepCounter = 3 THEN
            nSystemState := ST_ISLANDED; 
        END_IF;

    ST_RESYNC:
        (* Phase and Voltage Matching for seamless reconnection *)
        fPhaseError := fGridPhaseAngle - fMicrogridPhase;
        fVoltageError := fGridVoltage - fMicrogridVoltage;

        IF ABS(fPhaseError) < 0.05 AND ABS(fVoltageError) < 0.05 THEN
            tResyncTimer(IN:= TRUE, PT:= T#2S);
            IF tResyncTimer.Q THEN
                bCmdPccBreaker := TRUE;
                IF bPccBreakerStatus THEN
                    nSystemState := ST_GRID_CONN;
                END_IF;
            END_IF;
        ELSE
            tResyncTimer(IN:= FALSE, PT:= T#2S);
        END_IF;

        IF NOT bGridAvailable THEN
            nSystemState := ST_ISLANDED;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
