FUNCTION_BLOCK "HVDC_Control_Thermal"
VERSION : 1.0
VAR_INPUT
    SetAlpha : REAL; 
    GridVolt : REAL; 
    GridFreq : REAL; 
    CoolantTemp : REAL; // Coolant temperature in Celsius
    CoolantFlow : REAL; // Coolant flow rate in L/s
END_VAR
VAR_OUTPUT
    AlphaOut : REAL; 
    FilterSync : BOOL; 
    DeratingActive : BOOL;
    DeratingFactor : REAL;
    CoolingAlarm : BOOL;
END_VAR
VAR
    AlphaFiltered : REAL;
END_VAR
BEGIN
    // Thermal Management & Derating
    IF CoolantTemp > 85.0 OR CoolantFlow < 10.0 THEN
        CoolingAlarm := TRUE;
        DeratingActive := TRUE;
        DeratingFactor := 0.5; // 50% capacity
    ELSIF CoolantTemp > 75.0 THEN
        CoolingAlarm := FALSE;
        DeratingActive := TRUE;
        DeratingFactor := 0.8; // 80% capacity
    ELSE
        CoolingAlarm := FALSE;
        DeratingActive := FALSE;
        DeratingFactor := 1.0; // 100% capacity
    END_IF;

    // Firing Angle Control with Derating constraint
    AlphaFiltered := (AlphaFiltered * 0.9) + (SetAlpha * 0.1);
    // Adjust alpha based on derating (simplified: increase angle to reduce power)
    IF DeratingActive THEN
        AlphaOut := MAX(IN1 := AlphaFiltered, IN2 := 90.0); // Example limitation
    ELSE
        AlphaOut := AlphaFiltered;
    END_IF;

    // Harmonics filter synchronization logic
    IF GridFreq > 49.8 AND GridFreq < 50.2 THEN
        FilterSync := TRUE;
    ELSE
        FilterSync := FALSE;
    END_IF;
END_FUNCTION_BLOCK
