FUNCTION_BLOCK FB_KraftRecoveryBoiler_Optimization
VAR_INPUT
    (* Required physical inputs *)
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyTrip          : BOOL;     (* Safety instrumented system trip OK signal (TRUE = OK) *)
    rBlackLiquorDensity     : REAL;     (* Cascade evaporator density measurement (kg/m3) *)
    rSmeltSpoutAcoustic     : REAL;     (* Smelt spout dissolving tank acoustic level (dB) *)
    rTertiaryAirFlow        : REAL;     (* Tertiary air flow rate measurement (kg/s) *)
    rFurnaceTemperature     : REAL;     (* Lower furnace temperature (deg C) *)
    rSootBlowerSteamPress   : REAL;     (* Header pressure for sootblowers (bar) *)
    bManualOverride         : BOOL;     (* Manual control override *)
END_VAR
VAR_OUTPUT
    (* Required physical outputs *)
    bSystemReady            : BOOL;     (* Advanced control system ready status *)
    rTertiaryAirDamperSetpt : REAL;     (* Output to tertiary air damper actuator (0-100%) *)
    rBlackLiquorFlowSetpt   : REAL;     (* Output to black liquor feed pump (kg/s) *)
    bSootblowerStartTrigger : BOOL;     (* Trigger for sequential sootblowing *)
    bSmeltSpoutShatterSteam : BOOL;     (* Trigger for shatter steam on smelt spout *)
    bAlarmCritical          : BOOL;     (* Critical fault alarm output *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tSootBlowerInterval     : TON;
    tAcousticFilterTimer    : TON;
    rFilteredAcoustic       : REAL := 0.0;
    rDensityError           : REAL := 0.0;
    rAirFlowError           : REAL := 0.0;
    iSequenceStep           : INT := 0;

    (* Constants for control limits *)
    C_DENSITY_TARGET        : REAL := 1350.0;
    C_ACOUSTIC_HIGH_LIMIT   : REAL := 85.0;
    C_TEMP_OPTIMAL          : REAL := 1050.0;
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlocks *)
IF NOT bEmergencyTrip THEN
    bSystemReady            := FALSE;
    bAlarmCritical          := TRUE;
    rTertiaryAirDamperSetpt := 100.0; (* Fail safe: fully open tertiary air to burn out *)
    rBlackLiquorFlowSetpt   := 0.0;   (* Cut off black liquor feed *)
    bSootblowerStartTrigger := FALSE;
    bSmeltSpoutShatterSteam := TRUE;  (* Max shatter steam during trip to prevent explosion *)
    iState                  := 99;    (* Trip state *)
    RETURN;
END_IF;

(* Clear Critical Alarm if Trip is reset *)
bAlarmCritical := FALSE;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rTertiaryAirDamperSetpt := 50.0;
        rBlackLiquorFlowSetpt := 0.0;
        bSmeltSpoutShatterSteam := FALSE;
        IF bEnable AND NOT bManualOverride THEN
            iState := 10;
        END_IF;

    10: (* RAMPING & STABILIZATION *)
        bSystemReady := TRUE;
        (* Basic PI density trim simulation *)
        rDensityError := C_DENSITY_TARGET - rBlackLiquorDensity;
        rBlackLiquorFlowSetpt := 15.0 - (rDensityError * 0.05);

        (* Transition to advanced control once temperature reaches threshold *)
        IF rFurnaceTemperature > 900.0 THEN
            iState := 20;
        END_IF;

    20: (* ADVANCED OPTIMIZATION - KRAFT RECOVERY ACTIVE *)
        bSystemReady := TRUE;

        (* Cascade Evaporator Density Trim & Feed Control *)
        IF rBlackLiquorDensity < (C_DENSITY_TARGET - 50.0) THEN
            rBlackLiquorFlowSetpt := rBlackLiquorFlowSetpt * 0.98;
        ELSIF rBlackLiquorDensity > (C_DENSITY_TARGET + 50.0) THEN
            rBlackLiquorFlowSetpt := rBlackLiquorFlowSetpt * 1.02;
        END_IF;

        (* Tertiary Air Damper Cascading Logic *)
        rAirFlowError := rFurnaceTemperature - C_TEMP_OPTIMAL;
        IF rAirFlowError > 20.0 THEN
            rTertiaryAirDamperSetpt := rTertiaryAirDamperSetpt + 1.5;
        ELSIF rAirFlowError < -20.0 THEN
            rTertiaryAirDamperSetpt := rTertiaryAirDamperSetpt - 1.5;
        END_IF;

        (* Clamp air damper output 0-100% *)
        IF rTertiaryAirDamperSetpt > 100.0 THEN
            rTertiaryAirDamperSetpt := 100.0;
        ELSIF rTertiaryAirDamperSetpt < 0.0 THEN
            rTertiaryAirDamperSetpt := 0.0;
        END_IF;

        (* Acoustic Monitoring of Smelt Spout Dissolving Tank *)
        (* High acoustic energy indicates heavy smelt runoff, requiring shatter steam *)
        rFilteredAcoustic := (rFilteredAcoustic * 0.9) + (rSmeltSpoutAcoustic * 0.1);
        tAcousticFilterTimer(IN := (rFilteredAcoustic > C_ACOUSTIC_HIGH_LIMIT), PT := T#2S);

        IF tAcousticFilterTimer.Q THEN
            bSmeltSpoutShatterSteam := TRUE;
        ELSE
            bSmeltSpoutShatterSteam := FALSE;
        END_IF;

        (* Cascading Sootblower Logic Triggering based on Header Pressure and Time *)
        tSootBlowerInterval(IN := NOT bSootblowerStartTrigger, PT := T#120M);
        IF tSootBlowerInterval.Q AND rSootBlowerSteamPress > 35.0 THEN
            bSootblowerStartTrigger := TRUE;
        END_IF;

        (* Reset sootblower trigger logic (assumes external reset or time-based pulse) *)
        IF bSootblowerStartTrigger AND (rSootBlowerSteamPress < 25.0) THEN
            bSootblowerStartTrigger := FALSE;
        END_IF;

        (* Return to idle if disabled *)
        IF NOT bEnable OR bManualOverride THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        (* Require manual reset of trip before allowing restart *)
        IF bEmergencyTrip AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
