    ====================================================================
    High-Speed Multi-Layer Blown Film Extrusion - Master Control Logic
    ====================================================================
*)

IF NOT bEnableSystem THEN
    iState := 0;
    rIBCBlowerSpeedCmd := 0.0;
    rIBCExhaustSpeedCmd := 0.0;
    rNipHaulOffSpeed := 0.0;
    rOscillatorSpeed := 0.0;
