(* Anti-windup *)
IF rPressureIntegral > 100.0 THEN rPressureIntegral := 100.0; END_IF;
IF rPressureIntegral < -100.0 THEN rPressureIntegral := -100.0; END_IF;

rPressureDerivative := (rPressureError - rLastPressureError) / rTimeDelta;

rIBCBlowerSpeedCmd := (rKp_IBC * rPressureError) + (rKi_IBC * rPressureIntegral) + (rKd_IBC * rPressureDerivative);
rLastPressureError := rPressureError;

(* Exhaust coupling - exhaust follows blower with a trim based on temp *)
rIBCExhaustSpeedCmd := rIBCBlowerSpeedCmd * 1.05 + (rIBCAirTempActual - 25.0) * 0.2;

IF rIBCBlowerSpeedCmd > 100.0 THEN rIBCBlowerSpeedCmd := 100.0; END_IF;
IF rIBCBlowerSpeedCmd < 0.0 THEN rIBCBlowerSpeedCmd := 0.0; END_IF;
IF rIBCExhaustSpeedCmd > 100.0 THEN rIBCExhaustSpeedCmd := 100.0; END_IF;
IF rIBCExhaustSpeedCmd < 0.0 THEN rIBCExhaustSpeedCmd := 0.0; END_IF;

