FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Polyurethane Foam Slabstock Continuous Pouring Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    bStartPouring : BOOL; // Start pouring command
    bStopPouring : BOOL; // Stop pouring command
    bEmergencyStop : BOOL; // E-Stop
    rTargetDensity : REAL; // Target foam density (kg/m3)
    rLineSpeedCmd : REAL; // Conveyor line speed command (m/min)
    rPolyolTempActual : REAL; // Actual polyol temperature (degC)
    rIsoTempActual : REAL; // Actual isocyanate temperature (degC)
    rExothermTemp : REAL; // Exothermic reaction temperature monitoring (degC)
    rMixerPressureAct : REAL; // Impingement mixer pressure actual (bar)
    rTroughLevelAct : REAL; // Trough level actual (%)
END_VAR

VAR_OUTPUT
    bPouringActive : BOOL; // Pouring sequence active
    bSystemReady : BOOL; // System is ready to pour
    rPolyolPumpSpeed : REAL; // Polyol dosing pump speed reference (%)
    rIsoPumpSpeed : REAL; // Isocyanate dosing pump speed reference (%)
    rCatalystPumpSpeed : REAL; // Catalyst dosing pump speed reference (%)
    rMixerSpeedCmd : REAL; // Mixer motor speed reference (rpm)
    rTraverseSpeed : REAL; // Laydown trough traverse speed (m/s)
    bExothermWarning : BOOL; // Exotherm temperature runaway warning
    bExothermAlarm : BOOL; // Exotherm temperature runaway alarm
    bFault : BOOL; // System fault active
    iFaultCode : INT; // Fault code
END_VAR

VAR
    iState : INT := 0; // State machine step
    tonStartDelay : TON; // Start delay timer
    tonStopDelay : TON; // Stop delay timer
    rRatioPolyol : REAL := 100.0; // Polyol base ratio (pbw)
    rRatioIso : REAL := 45.0; // Isocyanate ratio (pbw)
    rRatioCatalyst : REAL := 2.5; // Catalyst ratio (pbw)
    rTotalOutputReq : REAL; // Total requested output (kg/min)
    rBaseViscosity : REAL := 1200.0; // Base viscosity assumption for polyol
END_VAR

// Logic Implementation
IF bEmergencyStop THEN
    bPouringActive := FALSE;
    bSystemReady := FALSE;
    rPolyolPumpSpeed := 0.0;
    rIsoPumpSpeed := 0.0;
    rCatalystPumpSpeed := 0.0;
    rMixerSpeedCmd := 0.0;
    rTraverseSpeed := 0.0;
    bFault := TRUE;
    iFaultCode := 999;
    iState := 0;
    RETURN;
END_IF;

// Temperature and Pressure Monitoring
IF rExothermTemp > 165.0 THEN
    bExothermAlarm := TRUE;
    bFault := TRUE;
    iFaultCode := 101;
ELSIF rExothermTemp > 140.0 THEN
    bExothermWarning := TRUE;
ELSE
    bExothermWarning := FALSE;
    bExothermAlarm := FALSE;
END_IF;

IF rMixerPressureAct > 200.0 THEN // Overpressure
    bFault := TRUE;
    iFaultCode := 102;
END_IF;

IF bFault THEN
    bPouringActive := FALSE;
    rPolyolPumpSpeed := 0.0;
    rIsoPumpSpeed := 0.0;
    rCatalystPumpSpeed := 0.0;
    rMixerSpeedCmd := 0.0;
    iState := 0;
    RETURN;
END_IF;

// Check readiness
IF NOT bPouringActive AND NOT bFault THEN
    bSystemReady := (rPolyolTempActual > 20.0 AND rPolyolTempActual < 25.0) AND 
                    (rIsoTempActual > 20.0 AND rIsoTempActual < 25.0);
ELSE
    bSystemReady := FALSE;
END_IF;

CASE iState OF
    0: // Idle state
        bPouringActive := FALSE;
        rPolyolPumpSpeed := 0.0;
        rIsoPumpSpeed := 0.0;
        rCatalystPumpSpeed := 0.0;
        rMixerSpeedCmd := 0.0;
        IF bStartPouring AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: // Pre-mix sequence
        rMixerSpeedCmd := 3500.0; // Start mixer at 3500 RPM
        tonStartDelay(IN:= TRUE, PT:= T#2S);
        IF tonStartDelay.Q THEN
            tonStartDelay(IN:= FALSE);
            iState := 20;
        END_IF;

    20: // Start pouring
        bPouringActive := TRUE;
        rTotalOutputReq := rLineSpeedCmd * rTargetDensity * 1.5; // Example profile calc

        // Calculate dosing speeds based on ratios
        rPolyolPumpSpeed := (rRatioPolyol / (rRatioPolyol + rRatioIso + rRatioCatalyst)) * rTotalOutputReq;
        rIsoPumpSpeed := (rRatioIso / (rRatioPolyol + rRatioIso + rRatioCatalyst)) * rTotalOutputReq;
        rCatalystPumpSpeed := (rRatioCatalyst / (rRatioPolyol + rRatioIso + rRatioCatalyst)) * rTotalOutputReq;

        // Traverse kinematics based on line speed and trough level
        rTraverseSpeed := 0.5 + (rLineSpeedCmd * 0.1) - (rTroughLevelAct * 0.005);
        IF rTraverseSpeed < 0.1 THEN rTraverseSpeed := 0.1; END_IF;
        IF rTraverseSpeed > 1.5 THEN rTraverseSpeed := 1.5; END_IF;

        IF bStopPouring THEN
            iState := 30;
        END_IF;

    30: // Stop sequence
        rPolyolPumpSpeed := 0.0;
        rIsoPumpSpeed := 0.0;
        rCatalystPumpSpeed := 0.0;

        tonStopDelay(IN:= TRUE, PT:= T#3S);
        IF tonStopDelay.Q THEN
            tonStopDelay(IN:= FALSE);
            rMixerSpeedCmd := 0.0;
            bPouringActive := FALSE;
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
