FUNCTION_BLOCK FB_HVDC_SubseaConverter
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal for the HVDC converter *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (TRUE = safe, FALSE = stop) *)
    rGridVoltageKV          : REAL;     (* Measured AC grid voltage in kV *)
    rActivePowerRefMW       : REAL;     (* Active power reference from grid operator in MW *)
    rReactivePowerRefMVAR   : REAL;     (* Reactive power reference for voltage support in MVAR *)
    rDC_BusVoltageKV        : REAL;     (* Measured DC bus voltage in kV *)
    aSubModuleVcap          : ARRAY[0..255] OF REAL; (* Sub-module capacitor voltages *)
    bFaultRideThroughTrig   : BOOL;     (* Trigger for Low Voltage Fault Ride Through (LVRT) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* Converter ready status for power transmission *)
    rValveControlSignal     : REAL;     (* Aggregate control signal for IGBT valve firing *)
    bAlarm                  : BOOL;     (* System fault or warning alarm *)
    rActivePowerOutMW       : REAL;     (* Actual active power being transferred *)
    rReactivePowerOutMVAR   : REAL;     (* Actual reactive power being injected/absorbed *)
    iActiveSubModules       : INT;      (* Number of actively inserted sub-modules *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0; (* Internal state machine state *)
    tStartupDelay           : TON;      (* Timer for converter pre-charging sequence *)
    tFaultTimer             : TON;      (* Timer for fault ride-through duration limits *)
    rCapVoltageSum          : REAL := 0.0;
    rCapVoltageAvg          : REAL := 0.0;
    i                       : INT;
    rVoltageError           : REAL;
    rIntegralTerm           : REAL := 0.0;
    rProportionalGain       : REAL := 2.5;
    rIntegralGain           : REAL := 0.1;
    bPrechargeComplete      : BOOL := FALSE;
    bBalanceActive          : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
(* Multi-layered safety interlock check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rValveControlSignal := 0.0;
    iActiveSubModules := 0;
    rActivePowerOutMW := 0.0;
    rReactivePowerOutMVAR := 0.0;
    iState := 0; (* Force to IDLE *)
    RETURN;
END_IF;

(* Sub-module Capacitor Balancing Algorithm (Simplified sorting/averaging logic) *)
rCapVoltageSum := 0.0;
FOR i := 0 TO 255 DO
    rCapVoltageSum := rCapVoltageSum + aSubModuleVcap[i];
END_FOR;
rCapVoltageAvg := rCapVoltageSum / 256.0;

IF rCapVoltageAvg < 2.0 THEN (* Assuming 2kV nominal per cap *)
    bBalanceActive := TRUE;
ELSE
    bBalanceActive := FALSE;
END_IF;

(* Advanced State Machine for MMC Converter Operation *)
CASE iState OF
    0: (* IDLE / OFF *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rValveControlSignal := 0.0;
        iActiveSubModules := 0;
        tStartupDelay(IN := FALSE);

        IF bEnable AND rDC_BusVoltageKV > 10.0 THEN (* Check minimum DC link voltage *)
            iState := 10;
        END_IF;

    10: (* PRE-CHARGE SEQUENCE *)
        tStartupDelay(IN := TRUE, PT := T#15S);
        (* Slowly insert sub-modules to prevent inrush *)
        iActiveSubModules := REAL_TO_INT((TIME_TO_REAL(tStartupDelay.ET) / 15000.0) * 128.0);

        IF tStartupDelay.Q AND rCapVoltageAvg > 1.8 THEN
            bPrechargeComplete := TRUE;
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* NORMAL OPERATION / ACTIVE POWER CONTROL *)
        bSystemReady := TRUE;

        (* Fault Ride-Through (FRT) check *)
        IF bFaultRideThroughTrig THEN
            iState := 30;
        END_IF;

        (* PI Control for Active Power Tracking *)
        rVoltageError := rActivePowerRefMW - rActivePowerOutMW;
        rIntegralTerm := rIntegralTerm + (rVoltageError * rIntegralGain * 0.001); (* 1ms scan assumption *)

        (* Anti-windup limit *)
        IF rIntegralTerm > 1000.0 THEN rIntegralTerm := 1000.0; END_IF;
        IF rIntegralTerm < -1000.0 THEN rIntegralTerm := -1000.0; END_IF;

        rValveControlSignal := (rVoltageError * rProportionalGain) + rIntegralTerm;

        (* Simulate power output tracking the reference for demonstration *)
        rActivePowerOutMW := rActivePowerRefMW * 0.99 + (rCapVoltageAvg * 0.01);
        rReactivePowerOutMVAR := rReactivePowerRefMVAR;
        iActiveSubModules := 250; (* Nominal active modules during full operation *)

        IF NOT bEnable THEN
            iState := 40; (* SHUTDOWN SEQUENCE *)
        END_IF;

    30: (* FAULT RIDE-THROUGH (FRT) INJECTION *)
        (* Inject maximum reactive power to support grid voltage during dip *)
        rValveControlSignal := 100.0; (* Max firing angle for VAr generation *)
        rReactivePowerOutMVAR := 1500.0; (* e.g., 1500 MVAr injection *)
        rActivePowerOutMW := 0.0; (* Curtail active power *)

        tFaultTimer(IN := TRUE, PT := T#3S); (* Max 3 seconds FRT *)
        IF NOT bFaultRideThroughTrig THEN
            tFaultTimer(IN := FALSE);
            iState := 20; (* Return to normal *)
        ELSIF tFaultTimer.Q THEN
            (* Fault persisted too long, trip converter *)
            bAlarm := TRUE;
            iState := 40;
        END_IF;

    40: (* SHUTDOWN *)
        bSystemReady := FALSE;
        rValveControlSignal := 0.0;
        iActiveSubModules := 0;
        rActivePowerOutMW := 0.0;
        rReactivePowerOutMVAR := 0.0;
        IF rDC_BusVoltageKV < 5.0 THEN
            iState := 0;
        END_IF;

    ELSE
        (* Failsafe catch-all *)
        iState := 0;
        bAlarm := TRUE;
END_CASE;

END_FUNCTION_BLOCK
