    IF (SQRT(fPelletPosition_M[0]*fPelletPosition_M[0] + fPelletPosition_M[1]*fPelletPosition_M[1]) > MAX_PLASMA_RAD) THEN
        bSIL4_ContainmentTripped := TRUE;
