        (* Calculate Magnetic Tensor Field based on Target Thrust and Vector Angles *)
        (* Using simplified Biot-Savart discretization for the 6 primary coils *)
        FOR i := 0 TO 5 DO
            FOR j := 0 TO 5 DO
                fMagneticTensorSetpoints[i,j] := (MU_0 * fTargetThrust_MN * 1000.0) / (2.0 * 3.14159 * (INT_TO_LREAL(i+1)*0.5));
                (* Apply Thrust Vectoring rotation matrix coefficients *)
                IF i = j THEN
                    fMagneticTensorSetpoints[i,j] := fMagneticTensorSetpoints[i,j] * COS(fVectorAngles_RAD[0]);
                END_IF;
            END_FOR;
        END_FOR;

        (* Set Primary Coil Currents to establish detachment field *)
        fCoilCurrentSetpoints_KA[0] := 550.0 + (fTargetThrust_MN * 2.1);
        fCoilCurrentSetpoints_KA[1] := 420.0 + (fTargetThrust_MN * 1.8);
        fCoilCurrentSetpoints_KA[2] := 380.0 + (fTargetThrust_MN * 1.5);
        fCoilCurrentSetpoints_KA[3] := 200.0; (* Expansion zone *)
        fCoilCurrentSetpoints_KA[4] := 150.0; (* Expansion zone *)
        fCoilCurrentSetpoints_KA[5] := 100.0; (* Exhaust detachment *)

        IF bInitiatePulseSequence AND (fTrapChargeState > 1.0E-9) THEN
            eState := SYNCHRONIZING;
            sSystemStatusMessage := 'SYNCHRONIZING Pellet and Antimatter.';
        END_IF;
        IF NOT bEnableDrive THEN
            eState := INIT;
        END_IF;

    SYNCHRONIZING:
        (* Nanosecond Precision Synchronization *)
        (* Calculate time for pellet to reach PELLET_FOCAL_Z given current Z velocity *)
        (* Assuming velocity is constant for this tick window (dt = 1ms system tick) *)

        (* Mock calculation for extraction trigger based on distance to focus *)
        IF (fPelletPosition_M[2] >= (PELLET_FOCAL_Z - 0.005)) AND (fPelletPosition_M[2] <= PELLET_FOCAL_Z) THEN
