            fTrapExtractionVoltage_KV := 150.5; (* Highly precise kV to shape antiproton beam *)
            bPulseActive := TRUE;

            tPulseTimer(IN:=FALSE); (* Reset timer *)
            eState := FIRING;
            sSystemStatusMessage := 'FIRING: Microfission Initiated.';
        END_IF;

        IF NOT bInitiatePulseSequence THEN
            eState := CHARGING;
        END_IF;

    FIRING:
        tPulseTimer(IN:=TRUE, PT:=T#50MS); (* Plasma exhaust phase lasts ~50ms *)
        bEjectAntiprotonPulse := FALSE; (* Turn off trap gate *)

        IF tPulseTimer.Q THEN
            tPulseTimer(IN:=FALSE);
            bPulseActive := FALSE;
            eState := COOLING;
            sSystemStatusMessage := 'COOLING: Exhaust expanding.';
