FUNCTION_BLOCK FB_Greenhouse_CHP_Control
TITLE = 'Greenhouse Cogeneration Plant Controller'
// ---------------------------------------------------------------------------
// Description: Advanced CHP control for greenhouse applications, including
// electrical grid synchronization, heat recovery, and CO2 dosing.
// ---------------------------------------------------------------------------

VAR_INPUT
    bEnable                 : BOOL;   // System enable signal
    bGridAvailable          : BOOL;   // Mains grid present and stable
    rGridFreq               : REAL;   // Grid frequency (Hz)
    rGridVoltage            : REAL;   // Grid voltage (V)

    rBufferTankTempTop      : REAL;   // Heat buffer tank top temp (deg C)
    rBufferTankTempBot      : REAL;   // Heat buffer tank bottom temp (deg C)
    rGreenhouseTemp         : REAL;   // Current greenhouse temperature (deg C)
    rGreenhouseCO2          : REAL;   // Current greenhouse CO2 level (ppm)

    rEngineSpeed            : REAL;   // Gas engine speed (RPM)
    rEngineExhaustTemp      : REAL;   // Engine exhaust temperature (deg C)

    rTargetCO2              : REAL := 800.0; // Target CO2 concentration (ppm)
    rTargetHeat             : REAL := 65.0;  // Target heating temp (deg C)
END_VAR

VAR_OUTPUT
    bEngineStart            : BOOL;   // Command to start gas engine
    bSyncBreakerClose       : BOOL;   // Command to close sync breaker

    rThrottleCmd            : REAL;   // Engine throttle command (0-100%)
    rExcitationCmd          : REAL;   // Generator excitation command (0-100%)

    rExhaustBypassValve     : REAL;   // Exhaust gas bypass valve (0-100%)
    rCO2DosingValve         : REAL;   // CO2 extraction to greenhouse (0-100%)

    bAlarm                  : BOOL;   // General alarm
    iErrorCode              : INT;    // Specific error code
END_VAR

VAR
    fbPID_Speed             : PID_Controller;
    fbPID_Voltage           : PID_Controller;
    fbPID_Heat              : PID_Controller;
    fbPID_CO2               : PID_Controller;

    nState                  : INT := 0; // State machine
    tSyncDelay              : TON;
    tCooldown               : TON;

    rHeatDemand             : REAL;
    rCO2Demand              : REAL;
    bHeatRequired           : BOOL;
    bCO2Required            : BOOL;
END_VAR

// ---------------------------------------------------------------------------
// Control Logic Implementation
// ---------------------------------------------------------------------------
// 1. Demand Calculation
bHeatRequired := (rBufferTankTempTop < rTargetHeat) OR (rGreenhouseTemp < (rTargetHeat - 10.0));
bCO2Required := (rGreenhouseCO2 < rTargetCO2);

rHeatDemand := rTargetHeat - rBufferTankTempTop;
IF rHeatDemand < 0.0 THEN rHeatDemand := 0.0; END_IF;

rCO2Demand := rTargetCO2 - rGreenhouseCO2;
IF rCO2Demand < 0.0 THEN rCO2Demand := 0.0; END_IF;

// 2. State Machine
CASE nState OF
    0: // OFF
        bEngineStart := FALSE;
        bSyncBreakerClose := FALSE;
        rThrottleCmd := 0.0;
        rExcitationCmd := 0.0;
        rExhaustBypassValve := 100.0; // Full bypass
        rCO2DosingValve := 0.0;

        IF bEnable AND (bHeatRequired OR bCO2Required) THEN
            nState := 10; // Init start
        END_IF;

    10: // ENGINE START
        bEngineStart := TRUE;
        rThrottleCmd := 10.0; // Idle throttle
        IF rEngineSpeed > 1000.0 THEN
            nState := 20; // Warmup
        END_IF;

        // Timeout logic omitted for brevity

    20: // SYNCHRONIZATION
        // Speed control to match grid frequency (assuming 50Hz -> 1500 RPM)
        fbPID_Speed(SetPoint := 1500.0, Actual := rEngineSpeed, Kp := 2.5, Ti := 1.0, Out => rThrottleCmd);

        // Voltage control to match grid voltage
        fbPID_Voltage(SetPoint := rGridVoltage, Actual := 400.0, Kp := 1.5, Ti := 0.5, Out => rExcitationCmd);

        IF ABS(rEngineSpeed - 1500.0) < 5.0 AND ABS(rGridVoltage - 400.0) < 10.0 AND bGridAvailable THEN
            tSyncDelay(IN := TRUE, PT := T#3S);
            IF tSyncDelay.Q THEN
                bSyncBreakerClose := TRUE;
                nState := 30; // Grid Parallel Operation
                tSyncDelay(IN := FALSE);
            END_IF;
        ELSE
            tSyncDelay(IN := FALSE);
        END_IF;

    30: // GRID PARALLEL (POWER / HEAT / CO2 PRODUCTION)
        // Maintain base load or thermal-following load
        IF bHeatRequired THEN
            fbPID_Heat(SetPoint := rTargetHeat, Actual := rBufferTankTempTop, Kp := 5.0, Ti := 10.0, Out => rThrottleCmd);
            rExhaustBypassValve := 100.0 - (rThrottleCmd); // Direct exhaust to heat exchanger
        ELSE
            rExhaustBypassValve := 100.0; // Bypass heat exchanger
            rThrottleCmd := 50.0; // Minimum load
        END_IF;

        // CO2 Dosing Control
        IF bCO2Required AND (rEngineExhaustTemp > 300.0) THEN
            // Ensure exhaust is hot enough (catalytic converter active) before dosing
            fbPID_CO2(SetPoint := rTargetCO2, Actual := rGreenhouseCO2, Kp := 2.0, Ti := 5.0, Out => rCO2DosingValve);
        ELSE
            rCO2DosingValve := 0.0;
        END_IF;

        // Shutdown condition
        IF NOT bEnable OR (NOT bHeatRequired AND NOT bCO2Required) THEN
            bSyncBreakerClose := FALSE;
            nState := 40; // Cooldown
        END_IF;

        // Grid failure
        IF NOT bGridAvailable THEN
            bSyncBreakerClose := FALSE;
            bAlarm := TRUE;
            iErrorCode := 101; // Islanding not supported in this version
            nState := 40;
        END_IF;

    40: // COOLDOWN
        bEngineStart := TRUE;
        rThrottleCmd := 10.0; // Idle
        rExhaustBypassValve := 100.0;
        rCO2DosingValve := 0.0;

        tCooldown(IN := TRUE, PT := T#3M);
        IF tCooldown.Q THEN
            tCooldown(IN := FALSE);
            nState := 0; // Back to OFF
        END_IF;

    ELSE
        // Fault state
        bEngineStart := FALSE;
        bSyncBreakerClose := FALSE;
        bAlarm := TRUE;
        rThrottleCmd := 0.0;
        rExcitationCmd := 0.0;
        rExhaustBypassValve := 100.0;
        rCO2DosingValve := 0.0;
END_CASE;

END_FUNCTION_BLOCK
