FUNCTION_BLOCK FB_IonEngineGridAlignment
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnableSystem      : BOOL;   (* Main enable for grid alignment mechanism *)
    bEmergencyStop     : BOOL;   (* Safety interlock for high voltage cutoff *)
    rGridTempCore      : REAL;   (* Core temperature of the molybdenum grid [K] *)
    rGridTempEdge      : REAL;   (* Edge temperature of the molybdenum grid [K] *)
    rArcDetectionV     : REAL;   (* High-speed differential voltage for arc detection [V] *)
    rXenonFlowRate     : REAL;   (* Xenon mass flow rate [mg/s] *)
    rTargetVectorAngle : REAL;   (* Target thrust vector deflection angle [urad] *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady       : BOOL;   (* Alignment mechanism active and in tolerance *)
    bArcFaultActive    : BOOL;   (* Arc fault quenching sequence active *)
    rActuatorXCmd      : REAL;   (* Commanded X-axis piezoelectric extension [nm] *)
    rActuatorYCmd      : REAL;   (* Commanded Y-axis piezoelectric extension [nm] *)
    rActuatorZCmd      : REAL;   (* Commanded Z-axis grid gap spacing [nm] *)
    iGridState         : INT;    (* Current state of the alignment sequence *)
END_VAR
VAR
    (* Internal state variables *)
    iState             : INT := 0; 
    tArcQuenchTimer    : TON;
    tThermalDelay      : TON;
    rThermalExpCoeff   : REAL := 4.8E-6; (* Mo thermal expansion coeff [1/K] *)
    rNominalGap        : REAL := 500000.0; (* Nominal screen-accel gap [nm] *)
    rCurrentGap        : REAL;
    rDeltaTemp         : REAL;
    rArcThresh         : REAL := 1500.0; (* Arc detection threshold [V/us] *)
    bArcDetected       : BOOL;
END_VAR

(* === MAIN LOGIC === *)
IF bEmergencyStop THEN
    bSystemReady    := FALSE;
    bArcFaultActive := FALSE;
    rActuatorXCmd   := 0.0;
    rActuatorYCmd   := 0.0;
    rActuatorZCmd   := rNominalGap;
    iState          := 999; (* SAFE STATE *)
    iGridState      := iState;
    RETURN;
END_IF;

(* Arc Fault Detection Logic *)
IF (rArcDetectionV > rArcThresh) AND (iState < 100) THEN
    bArcDetected := TRUE;
    iState := 100; (* Jump to Arc Quench Sequence *)
END_IF;

CASE iState OF
    0: (* IDLE - Await Enable *)
        bSystemReady := FALSE;
        IF bEnableSystem THEN
            iState := 10;
        END_IF;

    10: (* THERMAL EQUILIBRATION *)
        rDeltaTemp := rGridTempCore - rGridTempEdge;
        (* Wait for thermal gradient to stabilize before alignment *)
        tThermalDelay(IN := (ABS(rDeltaTemp) < 50.0), PT := T#10S);
        IF tThermalDelay.Q THEN
            tThermalDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* ACTIVE ALIGNMENT AND VECTORING *)
        (* Calculate base thermal expansion offset *)
        rCurrentGap := rNominalGap + (rGridTempCore * rThermalExpCoeff * 1000.0);

        (* Apply Xenon plasma density compensation *)
        rCurrentGap := rCurrentGap - (rXenonFlowRate * 2.5);

        (* Calculate vectoring offsets *)
        rActuatorXCmd := rCurrentGap * SIN(rTargetVectorAngle * 0.000001);
        rActuatorYCmd := rCurrentGap * COS(rTargetVectorAngle * 0.000001);
        rActuatorZCmd := rCurrentGap;

        bSystemReady := TRUE;

        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    100: (* ARC QUENCH INIT *)
        bSystemReady := FALSE;
        bArcFaultActive := TRUE;
        rActuatorZCmd := rNominalGap * 2.0; (* Maximize gap to quench arc *)
        rActuatorXCmd := 0.0;
        rActuatorYCmd := 0.0;
        tArcQuenchTimer(IN := TRUE, PT := T#2S);
        IF tArcQuenchTimer.Q THEN
            tArcQuenchTimer(IN := FALSE);
            iState := 110;
        END_IF;

    110: (* ARC QUENCH RECOVERY *)
        bArcFaultActive := FALSE;
        bArcDetected := FALSE;
        iState := 10; (* Return to thermal equilibration *)

    999: (* SAFE STATE HOLD *)
        IF NOT bEmergencyStop THEN
            iState := 0;
        END_IF;

END_CASE;

iGridState := iState;

END_FUNCTION_BLOCK
