FUNCTION_BLOCK FB_SpaceStation_ECLSS_Core
TITLE = 'Commercial Space Station Life Support - Core ECLSS Controller'
VERSION : '1.0'

(*
    Domain: Commercial Space Station Life Support
    Subsystems Controlled:
    1. Regenerative Sabatier Reactor (CO2 + H2 -> H2O + CH4)
    2. Trace Contaminant Control System (TCCS) - Catalytic Oxidation
    3. Active Thermal Control System (ATCS) - Sublimator Heat Rejection
*)

VAR_INPUT
    // Sabatier Reactor Inputs
    rCO2_FlowRate        : REAL; (* kg/h *)
    rH2_FlowRate         : REAL; (* kg/h *)
    rReactorTemp_PV      : REAL; (* °C *)
    rReactorPressure_PV  : REAL; (* kPa *)
    xEnableSabatier      : BOOL;

    // TCCS Inputs
    rCabinAirFlow_PV     : REAL; (* m3/h *)
    rCatalystBedTemp_PV  : REAL; (* °C *)
    rVOC_Concentration   : REAL; (* ppm *)
    xEnableTCCS          : BOOL;

    // Sublimator Inputs
    rCoolantInletTemp    : REAL; (* °C *)
    rCoolantFlowRate     : REAL; (* kg/h *)
    rFeedWaterPress_PV   : REAL; (* kPa *)
    xEnableSublimator    : BOOL;

    // Global Safety
    xEmergencyEstop      : BOOL;
    rVacuumPressure      : REAL; (* Space vacuum reference, kPa *)
END_VAR

VAR_OUTPUT
    // Sabatier Reactor Outputs
    rCO2_ValvePosition   : REAL; (* 0-100% *)
    rH2_ValvePosition    : REAL; (* 0-100% *)
    rReactorHeaterPower  : REAL; (* 0-100% *)
    rMethaneVentValve    : REAL; (* 0-100% *)
    rWaterPumpSpeed      : REAL; (* 0-100% *)
    xSabatierActive      : BOOL;

    // TCCS Outputs
    rBlowerSpeed         : REAL; (* 0-100% *)
    rCatalystHeaterPower : REAL; (* 0-100% *)
    xTCCSActive          : BOOL;

    // Sublimator Outputs
    rFeedWaterValvePos   : REAL; (* 0-100% *)
    rSteamVentValvePos   : REAL; (* 0-100% *)
    xSublimatorActive    : BOOL;

    // System Status
    wAlarmWord           : WORD; (* Bitmask for system alarms *)
    xSystemReady         : BOOL;
END_VAR

VAR
    // Internal States and PID Controllers
    rTargetReactorTemp   : REAL := 400.0; (* °C optimal Sabatier temp *)
    rTargetCatalystTemp  : REAL := 350.0; (* °C optimal VOC oxidation *)
    rTargetCoolantOut    : REAL := 4.0;   (* °C *)

    // State machines
    iSabatierState       : INT := 0; 
    iTCCSState           : INT := 0;
    iSublimatorState     : INT := 0;

    // Timers
    tonSabatierWarmup    : TON;
    tonTCCSWarmup        : TON;
    tonCoolDown          : TON;

    // Internal calculations
    rStoichiometricRatio : REAL := 0.0;
    rHeatLoad            : REAL := 0.0;
END_VAR

(* --- Global Safety Interlock --- *)
IF xEmergencyEstop THEN
    rCO2_ValvePosition   := 0.0;
    rH2_ValvePosition    := 0.0;
    rReactorHeaterPower  := 0.0;
    rMethaneVentValve    := 100.0; (* Fail safe vent *)
    rWaterPumpSpeed      := 0.0;

    rBlowerSpeed         := 0.0;
    rCatalystHeaterPower := 0.0;

    rFeedWaterValvePos   := 0.0;
    rSteamVentValvePos   := 100.0; (* Fail safe vent to vacuum *)

    wAlarmWord := wAlarmWord OR 16#0001; (* E-Stop active *)
    xSystemReady := FALSE;
    RETURN;
ELSE
    wAlarmWord := wAlarmWord AND 16#FFFE;
    xSystemReady := TRUE;
END_IF;

(* --- 1. Sabatier Reactor Control (CO2 + 4H2 -> CH4 + 2H2O) --- *)
CASE iSabatierState OF
    0: (* Off / Standby *)
        xSabatierActive := FALSE;
        rCO2_ValvePosition := 0.0;
        rH2_ValvePosition := 0.0;
        rReactorHeaterPower := 0.0;
        rMethaneVentValve := 0.0;
        IF xEnableSabatier THEN
            iSabatierState := 10;
        END_IF;

    10: (* Warmup Phase *)
        xSabatierActive := TRUE;
        rReactorHeaterPower := 100.0; (* Full heat *)
        tonSabatierWarmup(IN := (rReactorTemp_PV >= rTargetReactorTemp * 0.95), PT := T#5S);
        IF tonSabatierWarmup.Q THEN
            iSabatierState := 20;
        ELSIF NOT xEnableSabatier THEN
            iSabatierState := 99; (* Cooldown *)
        END_IF;

    20: (* Steady State Operation *)
        (* Temperature Control via Heater Proportional Control *)
        IF rReactorTemp_PV < rTargetReactorTemp THEN
            rReactorHeaterPower := (rTargetReactorTemp - rReactorTemp_PV) * 2.5; 
            IF rReactorHeaterPower > 100.0 THEN rReactorHeaterPower := 100.0; END_IF;
        ELSE
            rReactorHeaterPower := 0.0; (* Exothermic reaction provides heat *)
        END_IF;

        (* Flow Control - Maintain Stoichiometry *)
        IF rCO2_FlowRate > 0.0 THEN
            // Theoretical ratio is ~0.18 kg H2 per kg CO2, we use 0.2 for margin
            rStoichiometricRatio := (rH2_FlowRate / rCO2_FlowRate);
            IF rStoichiometricRatio < 0.18 THEN
                rH2_ValvePosition := rH2_ValvePosition + 1.0; 
            ELSIF rStoichiometricRatio > 0.22 THEN
                rH2_ValvePosition := rH2_ValvePosition - 1.0;
            END_IF;
            // Basic CO2 demand
            rCO2_ValvePosition := 50.0; 
        ELSE
            rCO2_ValvePosition := 10.0; 
            rH2_ValvePosition := 5.0; 
        END_IF;

        // Venting and Pumping
        IF rReactorPressure_PV > 150.0 THEN
            rMethaneVentValve := (rReactorPressure_PV - 150.0) * 2.0;
        ELSE
            rMethaneVentValve := 0.0;
        END_IF;
        rWaterPumpSpeed := 50.0; 

        IF NOT xEnableSabatier THEN
            iSabatierState := 99;
        END_IF;

    99: (* Cooldown *)
        rCO2_ValvePosition := 0.0;
        rH2_ValvePosition := 0.0;
        rReactorHeaterPower := 0.0;
        tonCoolDown(IN := TRUE, PT := T#60S);
        IF tonCoolDown.Q THEN
            tonCoolDown(IN := FALSE);
            iSabatierState := 0;
        END_IF;
END_CASE;

(* --- 2. Trace Contaminant Control System (TCCS) --- *)
IF xEnableTCCS THEN
    xTCCSActive := TRUE;
    // Blower speed proportional to VOC concentration, min 20%
    rBlowerSpeed := 20.0 + (rVOC_Concentration * 1.5);
    IF rBlowerSpeed > 100.0 THEN rBlowerSpeed := 100.0; END_IF;

    // Catalyst Bed Temperature Control
    IF rCatalystBedTemp_PV < rTargetCatalystTemp THEN
        rCatalystHeaterPower := 100.0;
    ELSIF rCatalystBedTemp_PV > (rTargetCatalystTemp + 10.0) THEN
        rCatalystHeaterPower := 0.0;
    ELSE
        rCatalystHeaterPower := 50.0; // Maintenance
    END_IF;

    IF rVOC_Concentration > 50.0 THEN
        wAlarmWord := wAlarmWord OR 16#0002; (* High VOC Warning *)
    ELSE
        wAlarmWord := wAlarmWord AND 16#FFFD;
    END_IF;
ELSE
    xTCCSActive := FALSE;
    rBlowerSpeed := 0.0;
    rCatalystHeaterPower := 0.0;
END_IF;

(* --- 3. Sublimator Heat Rejection System --- *)
IF xEnableSublimator THEN
    xSublimatorActive := TRUE;
    // Calculate heat load based on coolant Delta T and flow (simplified)
    rHeatLoad := rCoolantFlowRate * (rCoolantInletTemp - rTargetCoolantOut);

    IF rHeatLoad > 0.0 THEN
        // Regulate Feed Water to porous plate based on heat load
        // Sublimation of 1 kg water removes ~2.5 MJ
        rFeedWaterValvePos := rHeatLoad * 0.05; 
        IF rFeedWaterValvePos > 100.0 THEN rFeedWaterValvePos := 100.0; END_IF;

        // Steam vent exposes ice layer to vacuum
        IF rVacuumPressure < 0.1 THEN (* Must be hard vacuum *)
            rSteamVentValvePos := 100.0;
            wAlarmWord := wAlarmWord AND 16#FFFB;
        ELSE
            // Poor vacuum - sublimation stalls
            rSteamVentValvePos := 0.0;
            wAlarmWord := wAlarmWord OR 16#0004; (* Loss of Vacuum Alarm *)
        END_IF;
    ELSE
        rFeedWaterValvePos := 0.0;
        rSteamVentValvePos := 0.0;
    END_IF;
ELSE
    xSublimatorActive := FALSE;
    rFeedWaterValvePos := 0.0;
    rSteamVentValvePos := 0.0;
END_IF;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_FPV_ArrayController
(* 
   =============================================================================
   Lumina AI Cloud Swarm - Elite Automation Code
   Domain: Next-Gen Utility-Scale Offshore Floating Solar Photovoltaic (FPV) Array
   Description: Advanced active structural tension compensation, multi-inverter 
                MPPT coordination, and automated saline mist washing control.
                Incorporates robust noise filtering (EMA), layered safety interlocks, 
                and comprehensive state-machine resilience for harsh marine environments.
   =============================================================================
*)

VAR_INPUT
    bEnable                 : BOOL;     (* System global enable command *)
    bEmergencyStop          : BOOL;     (* E-Stop safety loop (Normally Closed, True = OK) *)
    bGridFault              : BOOL;     (* Main grid fault indication from substation *)
    rWaveAmplitude_m        : REAL;     (* Sea state monitoring: Wave amplitude in meters (Lidar/Sonar) *)
    rWaveFrequency_Hz       : REAL;     (* Sea state monitoring: Wave frequency in Hz *)
    rStructuralTension_kN   : REAL;     (* Strain gauge reading: Anchor line tension in kilonewtons *)
    rSolarIrradiance_Wm2    : REAL;     (* Pyranometer reading: W/m^2 *)
    rInverterTemp_C         : REAL;     (* Critical inverter average temperature in deg C *)
    rSalinitySensor_ppm     : REAL;     (* Insulator surface saline accumulation in ppm *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is initialized, safe, and ready for power generation *)
    bActiveCompensation     : BOOL;     (* Dynamic tension compensation mechanism is active *)
    rTensionWinchCmd_Pct    : REAL;     (* Command to anchor tensioning winches (0.0 to 100.0%) *)
    rInverterPowerLimit_Pct : REAL;     (* Curtailed power setpoint for multi-inverter MPPT smoothing *)
    bWashSystemActive       : BOOL;     (* Trigger for fresh-water spray to clean saline mist *)
    bCriticalAlarm          : BOOL;     (* Critical structural or electrical fault - requires intervention *)
END_VAR

VAR
    (* State Machine *)
    iState                  : INT := 0; (* 0: INIT, 10: IDLE, 20: PRE-CHARGE, 30: GENERATING, 40: WASHING, 99: FAULT *)

    (* Internal Timers *)
    tWashTimer              : TON;
    tTensionSettleTimer     : TON;
    tFaultFilter            : TON;

    (* Filter Variables *)
    rFilteredTension        : REAL := 0.0;
    rFilteredIrradiance     : REAL := 0.0;

    (* Constants *)
    TENSION_MAX_KN          : REAL := 2500.0;
    TENSION_TARGET_KN       : REAL := 1200.0;
    WASH_THRESHOLD_PPM      : REAL := 1500.0;
    TEMP_DERATE_START_C     : REAL := 65.0;
    TEMP_MAX_C              : REAL := 85.0;
    ALPHA_FILTER            : REAL := 0.1; (* Exponential Moving Average filter coefficient *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Essential Safety Interlocks *)
IF NOT bEmergencyStop OR bGridFault THEN
    iState := 99; (* Force immediate transition to FAULT state *)
END_IF;

(* 2. Sensor Signal Filtering (EMA for noise rejection) *)
rFilteredTension := (ALPHA_FILTER * rStructuralTension_kN) + ((1.0 - ALPHA_FILTER) * rFilteredTension);
rFilteredIrradiance := (ALPHA_FILTER * rSolarIrradiance_Wm2) + ((1.0 - ALPHA_FILTER) * rFilteredIrradiance);

(* 3. Critical Alarm Evaluation (Structural Integrity) *)
tFaultFilter(IN := (rFilteredTension > TENSION_MAX_KN) OR (rInverterTemp_C > TEMP_MAX_C), PT := T#2S);
IF tFaultFilter.Q THEN
    bCriticalAlarm := TRUE;
    iState := 99;
ELSE
    bCriticalAlarm := FALSE;
END_IF;

(* 4. State Machine Operation *)
CASE iState OF
    0: (* INIT - System startup and sensor baseline calibration *)
        bSystemReady := FALSE;
        bActiveCompensation := FALSE;
        rTensionWinchCmd_Pct := 0.0;
        rInverterPowerLimit_Pct := 0.0;
        bWashSystemActive := FALSE;

        IF bEnable AND bEmergencyStop THEN
            iState := 10;
        END_IF;

    10: (* IDLE - Waiting for solar irradiance or wave action *)
        bSystemReady := TRUE;
        rInverterPowerLimit_Pct := 0.0;

        IF rFilteredIrradiance > 150.0 THEN
            iState := 20;
        END_IF;

        IF rSalinitySensor_ppm > WASH_THRESHOLD_PPM THEN
            iState := 40;
        END_IF;

    20: (* PRE-CHARGE - Soft start inverters *)
        rInverterPowerLimit_Pct := 20.0; (* Limit to 20% during synchronization *)
        tTensionSettleTimer(IN := TRUE, PT := T#10S);
        IF tTensionSettleTimer.Q THEN
            tTensionSettleTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* GENERATING - Active MPPT and Dynamic Tension Control *)
        (* Power smoothing and thermal derating *)
        IF rInverterTemp_C > TEMP_DERATE_START_C THEN
            rInverterPowerLimit_Pct := 100.0 - ((rInverterTemp_C - TEMP_DERATE_START_C) * 5.0);
            IF rInverterPowerLimit_Pct < 10.0 THEN
                rInverterPowerLimit_Pct := 10.0;
            END_IF;
        ELSE
            rInverterPowerLimit_Pct := 100.0;
        END_IF;

        (* Dynamic Wave Tension Compensation (Proportional response) *)
        IF rWaveAmplitude_m > 1.5 THEN
            bActiveCompensation := TRUE;
            rTensionWinchCmd_Pct := (rFilteredTension - TENSION_TARGET_KN) * 0.05;
            (* Clamp command *)
            IF rTensionWinchCmd_Pct > 100.0 THEN rTensionWinchCmd_Pct := 100.0; END_IF;
            IF rTensionWinchCmd_Pct < 0.0 THEN rTensionWinchCmd_Pct := 0.0; END_IF;
        ELSE
            bActiveCompensation := FALSE;
            rTensionWinchCmd_Pct := 0.0;
        END_IF;

        (* Check wash condition *)
        IF rSalinitySensor_ppm > WASH_THRESHOLD_PPM THEN
            iState := 40;
        END_IF;

        (* Check low irradiance *)
        IF rFilteredIrradiance < 50.0 THEN
            iState := 10;
        END_IF;

    40: (* WASHING - Active Insulator Cleaning Sequence *)
        bWashSystemActive := TRUE;
        rInverterPowerLimit_Pct := 50.0; (* Derate during washing to prevent arcing *)

        tWashTimer(IN := TRUE, PT := T#5M); (* Wash for 5 minutes *)
        IF tWashTimer.Q THEN
            tWashTimer(IN := FALSE);
            bWashSystemActive := FALSE;
            IF rFilteredIrradiance > 150.0 THEN
                iState := 20;
            ELSE
                iState := 10;
            END_IF;
        END_IF;

    99: (* FAULT - Safe state lock-in *)
        bSystemReady := FALSE;
        rInverterPowerLimit_Pct := 0.0;
        rTensionWinchCmd_Pct := 100.0; (* Full tension release / slack to prevent structural failure *)
        bActiveCompensation := FALSE;
        bWashSystemActive := FALSE;

        IF NOT bCriticalAlarm AND bEnable AND bEmergencyStop AND NOT bGridFault THEN
            iState := 0; (* Manual reset logic could go here *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

