FUNCTION_BLOCK FB_Corrugator_MasterControl
VAR_INPUT
    bEnable : BOOL; // Enable master control
    rLineSpeedCmd : REAL; // Commanded line speed (m/min)
    rActualLineSpeed : REAL; // Actual line speed from encoder
    rSingleFacerGapPV : REAL; // Present value of glue gap (mm)
    rPreCondWrapPV : REAL; // Present wrap angle (degrees)
    rPaperTensionPV : REAL; // Paper web tension (N)
    aThermalPlateTemps : ARRAY[1..12] OF REAL; // Zone temperatures
    bEStop : BOOL; // Emergency stop
    bSpliceActive : BOOL; // Splicer sequence active
END_VAR
VAR_OUTPUT
    rSingleFacerGapCV : REAL; // Control output for glue gap actuator
    rPreCondWrapCV : REAL; // Control output for wrap angle motor
    aThermalPlateHeatersCV : ARRAY[1..12] OF REAL; // Control outputs for thermal plates (0-100%)
    bMachineFault : BOOL; // Fault flag
    nFaultCode : INT; // Diagnostic code
    rCalculatedMoisture : REAL; // Estimated moisture content (%)
    bSystemReady : BOOL;
END_VAR
VAR
    // Internal PIDs and states
    fbGapPID : FB_PID; // Assuming a standard PID FB exists
    fbWrapPID : FB_PID;
    afbThermalPIDs : ARRAY[1..12] OF FB_PID;

    rGapSP : REAL; // Gap setpoint, speed dependent
    rWrapSP : REAL; // Wrap setpoint, speed dependent
    rSpeedRatio : REAL;

    i : INT;
    rAvgTemp : REAL;
    rTempSum : REAL;

    // Timers
    tEStopDelay : TON;
    tSpliceComp : TON;

    eState : INT := 0; // 0=INIT, 1=RUNNING, 2=SPLICING, 3=FAULT
END_VAR

// Main State Machine
CASE eState OF
    0: // INIT
        bMachineFault := FALSE;
        nFaultCode := 0;
        IF bEStop THEN
            eState := 3;
            nFaultCode := 100;
        ELSIF bEnable THEN
            bSystemReady := TRUE;
            eState := 1;
        END_IF;

    1: // RUNNING
        IF bEStop THEN
            eState := 3;
            nFaultCode := 100;
        END_IF;

        IF bSpliceActive THEN
            eState := 2;
        END_IF;

        // Speed Ratio Calculation
        IF rLineSpeedCmd > 0.0 THEN
            rSpeedRatio := rActualLineSpeed / rLineSpeedCmd;
        ELSE
            rSpeedRatio := 0.0;
        END_IF;

        // Dynamic Setpoint Generation
        // Glue gap decreases at higher speeds to maintain coat weight
        rGapSP := 0.15 + (150.0 - rActualLineSpeed) * 0.001;
        IF rGapSP < 0.05 THEN
            rGapSP := 0.05;
        END_IF;

        // Wrap angle increases at higher speeds for heat transfer
        rWrapSP := 90.0 + (rActualLineSpeed * 0.5);
        IF rWrapSP > 270.0 THEN
            rWrapSP := 270.0;
        END_IF;

    2: // SPLICING
        IF NOT bSpliceActive THEN
            eState := 1;
        END_IF;
        // Hold current gap during splice to prevent tearing
        // Adjust wrap angle for tail out
        rWrapSP := 45.0;

    3: // FAULT
        rSingleFacerGapCV := 2.0; // Open gap fully
        rPreCondWrapCV := 0.0; // Unwind completely
        FOR i := 1 TO 12 DO
            aThermalPlateHeatersCV[i] := 0.0;
        END_FOR;
        bSystemReady := FALSE;
        IF NOT bEStop AND NOT bEnable THEN
            eState := 0;
        END_IF;
END_CASE;

// PID Execution (Only active if not in fault)
IF eState <> 3 THEN
    // Gap Control
    fbGapPID.EN := TRUE;
    fbGapPID.SP := rGapSP;
    fbGapPID.PV := rSingleFacerGapPV;
    fbGapPID.Kp := 2.5;
    fbGapPID.Ki := 0.1;
    fbGapPID.Kd := 0.05;
    fbGapPID();
    rSingleFacerGapCV := fbGapPID.CV;

    // Wrap Control
    fbWrapPID.EN := TRUE;
    fbWrapPID.SP := rWrapSP;
    fbWrapPID.PV := rPreCondWrapPV;
    fbWrapPID.Kp := 1.2;
    fbWrapPID.Ki := 0.05;
    fbWrapPID.Kd := 0.01;
    fbWrapPID();
    rPreCondWrapCV := fbWrapPID.CV;

    // Thermal Plate Tracking Control
    rTempSum := 0.0;
    FOR i := 1 TO 12 DO
        afbThermalPIDs[i].EN := TRUE;
        // Thermal setpoint cascades based on zone and line speed
        afbThermalPIDs[i].SP := 180.0 + (i * 2.0) + (rActualLineSpeed * 0.1); 
        afbThermalPIDs[i].PV := aThermalPlateTemps[i];
        afbThermalPIDs[i].Kp := 5.0;
        afbThermalPIDs[i].Ki := 0.2;
        afbThermalPIDs[i]();
        aThermalPlateHeatersCV[i] := afbThermalPIDs[i].CV;

        rTempSum := rTempSum + aThermalPlateTemps[i];
    END_FOR;

    rAvgTemp := rTempSum / 12.0;

    // Moisture Estimation Model (Empirical)
    rCalculatedMoisture := 8.5 - (rAvgTemp * 0.02) - (rPreCondWrapPV * 0.005) + (rActualLineSpeed * 0.01);
    IF rCalculatedMoisture < 4.0 THEN
        rCalculatedMoisture := 4.0;
    ELSIF rCalculatedMoisture > 12.0 THEN
        rCalculatedMoisture := 12.0;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
