FUNCTION_BLOCK FB_FlexoFolderGluer_Control
VAR_INPUT
    bEnable                 : BOOL;   (* Master enable for the FFG line *)
    bEStop                  : BOOL;   (* Emergency Stop - Active Low *)
    bReset                  : BOOL;   (* Fault Reset *)
    rLineSpeedCmd           : REAL;   (* Desired line speed in boards/min *)

    (* Anilox Print Unit Feedback *)
    rAniloxPosFeedback      : REAL;   (* Actual position of print cylinder (Degrees) *)
    rAniloxSpeedFeedback    : REAL;   (* Actual speed of print cylinder (Degrees/sec) *)

    (* Rotary Slotting Head Feedback *)
    rSlotterPosFeedback     : REAL;   (* Actual position of slotter head (Degrees) *)
    bBoardDetectSensor      : BOOL;   (* Photoeye detecting leading edge of board *)

    (* Folding Section Feedback *)
    bFolderArmHome          : BOOL;   (* Folding arm at home position *)
    rGlueFlowRateFb         : REAL;   (* Actual glue application rate (ml/s) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;   (* System is ready to run *)
    bSystemRunning          : BOOL;   (* System is currently running *)
    bFaultActive            : BOOL;   (* Global fault indicator *)
    iFaultCode              : INT;    (* Specific fault code for HMI *)

    (* Anilox Print Unit Commands *)
    rAniloxTorqueCmd        : REAL;   (* Torque command to Anilox servo (Nm) *)
    rAniloxSpeedCmd         : REAL;   (* Speed command to Anilox servo *)

    (* Rotary Slotting Head Commands *)
    rSlotterPosCmd          : REAL;   (* Position command for slotting head *)

    (* Folding & Gluing Commands *)
    bFolderArmExtendCmd     : BOOL;   (* Pneumatic valve command to extend folding arm *)
    rGluePumpSpeedCmd       : REAL;   (* Speed command for glue applicator pump *)
END_VAR

VAR
    (* Internal State Machine *)
    eState                  : INT := 0; (* 0: Init, 1: Ready, 2: Run, 3: Fault, 4: Stopping *)

    (* PID Controllers for Registration *)
    rAniloxPosError         : REAL;
    rAniloxPosIntegral      : REAL;
    rAniloxPosDerivative    : REAL;
    rAniloxPosPrevError     : REAL;
    rAniloxKp               : REAL := 1.5;
    rAniloxKi               : REAL := 0.2;
    rAniloxKd               : REAL := 0.05;

    (* Tracking & Phasing *)
    rVirtualMasterPos       : REAL;   (* Internal virtual master axis *)
    rBoardLength            : REAL := 1200.0; (* Length of the cardboard (mm) *)
    rCutOffLength           : REAL := 1500.0; (* Repeat length of the machine *)

    (* Timers & Filters *)
    tGlueDelay              : TON;
    tFolderExtend           : TON;
    tEStopDelay             : TON;
    rFilteredLineSpeed      : REAL;

    (* Fault Management *)
    bAniloxTrackingFault    : BOOL;
    bSlotterSyncFault       : BOOL;
    bGlueFlowFault          : BOOL;
END_VAR

(* Implementation *)

(* Emergency Stop Handling *)
IF NOT bEStop THEN
    eState := 3;
    iFaultCode := 99; (* E-Stop Active *)
    bSystemReady := FALSE;
    bSystemRunning := FALSE;

    (* Safe State Outputs *)
    rAniloxTorqueCmd := 0.0;
    rAniloxSpeedCmd := 0.0;
    rSlotterPosCmd := rSlotterPosFeedback; (* Hold position *)
    bFolderArmExtendCmd := FALSE;
    rGluePumpSpeedCmd := 0.0;
    RETURN;
END_IF

(* Fault Reset *)
IF bReset AND eState = 3 THEN
    IF bEStop AND NOT bAniloxTrackingFault AND NOT bSlotterSyncFault AND NOT bGlueFlowFault THEN
        eState := 0;
        iFaultCode := 0;
        bFaultActive := FALSE;
    END_IF
END_IF

(* State Machine Execution *)
CASE eState OF
    0: (* INIT *)
        bSystemReady := FALSE;
        bSystemRunning := FALSE;
        rVirtualMasterPos := 0.0;

        IF bFolderArmHome THEN
            eState := 1;
        ELSE
            bFolderArmExtendCmd := FALSE; (* Retract arm to home *)
        END_IF

    1: (* READY *)
        bSystemReady := TRUE;
        bSystemRunning := FALSE;

        IF bEnable AND rLineSpeedCmd > 0.0 THEN
            eState := 2;
        END_IF

    2: (* RUN *)
        bSystemReady := TRUE;
        bSystemRunning := TRUE;

        (* Ramp virtual master based on line speed command *)
        (* Assume 1 cycle of execution is 1ms for simplification *)
        rFilteredLineSpeed := rFilteredLineSpeed + (rLineSpeedCmd - rFilteredLineSpeed) * 0.01;
        rVirtualMasterPos := rVirtualMasterPos + (rFilteredLineSpeed / 60.0) * 360.0 * 0.001; 

        IF rVirtualMasterPos >= 360.0 THEN
            rVirtualMasterPos := rVirtualMasterPos - 360.0;
        END_IF

        (* -----------------------------------------------------
           Anilox Print Cylinder Registration Control
           Calculate PID torque command to keep Anilox in phase
           with virtual master.
           ----------------------------------------------------- *)
        rAniloxPosError := rVirtualMasterPos - rAniloxPosFeedback;

        (* Handle wrap-around error *)
        IF rAniloxPosError > 180.0 THEN
            rAniloxPosError := rAniloxPosError - 360.0;
        ELSIF rAniloxPosError < -180.0 THEN
            rAniloxPosError := rAniloxPosError + 360.0;
        END_IF

        rAniloxPosIntegral := rAniloxPosIntegral + (rAniloxPosError * 0.001);
        rAniloxPosDerivative := (rAniloxPosError - rAniloxPosPrevError) / 0.001;
        rAniloxPosPrevError := rAniloxPosError;

        rAniloxTorqueCmd := (rAniloxPosError * rAniloxKp) + (rAniloxPosIntegral * rAniloxKi) + (rAniloxPosDerivative * rAniloxKd);

        (* Feedforward speed command based on line speed *)
        rAniloxSpeedCmd := rFilteredLineSpeed * 6.0; (* Degrees per second mapping *)

        (* Tracking Fault Detection *)
        IF ABS(rAniloxPosError) > 5.0 THEN
            bAniloxTrackingFault := TRUE;
            eState := 3;
            iFaultCode := 10;
        END_IF

        (* -----------------------------------------------------
           Rotary Slotting Head Tracking
           Electronic Camming logic to sync slotter blades with board
           ----------------------------------------------------- *)
        IF bBoardDetectSensor THEN
            (* Re-reference slotter phase to physical board edge *)
            rSlotterPosCmd := 0.0; 
        ELSE
            (* Phase advance based on speed to compensate for mechanical delays *)
            rSlotterPosCmd := rVirtualMasterPos + (rFilteredLineSpeed * 0.05);
        END_IF

        IF rSlotterPosCmd > 360.0 THEN rSlotterPosCmd := rSlotterPosCmd - 360.0; END_IF

        (* Slotter sync fault *)
        IF ABS(rSlotterPosCmd - rSlotterPosFeedback) > 10.0 THEN
            bSlotterSyncFault := TRUE;
            eState := 3;
            iFaultCode := 20;
        END_IF

        (* -----------------------------------------------------
           Folding Arm Pneumatics & Glue Application
           Fire pneumatics based on virtual axis window
           ----------------------------------------------------- *)
        IF rVirtualMasterPos > 120.0 AND rVirtualMasterPos < 180.0 THEN
            bFolderArmExtendCmd := TRUE;
        ELSE
            bFolderArmExtendCmd := FALSE;
        END_IF

        (* Glue pump proportional to line speed *)
        rGluePumpSpeedCmd := rFilteredLineSpeed * 2.5;

        (* Check Glue Flow Fault *)
        IF (rGluePumpSpeedCmd > 10.0) AND (rGlueFlowRateFb < (rGluePumpSpeedCmd * 0.1)) THEN
            bGlueFlowFault := TRUE;
            eState := 3;
            iFaultCode := 30;
        END_IF

        IF NOT bEnable THEN
            eState := 4; (* Stopping *)
        END_IF

    3: (* FAULT *)
        bSystemReady := FALSE;
        bSystemRunning := FALSE;
        bFaultActive := TRUE;

        rAniloxTorqueCmd := 0.0;
        rAniloxSpeedCmd := 0.0;
        rSlotterPosCmd := rSlotterPosFeedback;
        bFolderArmExtendCmd := FALSE;
        rGluePumpSpeedCmd := 0.0;

    4: (* STOPPING *)
        bSystemReady := TRUE;
        bSystemRunning := FALSE;
        rFilteredLineSpeed := rFilteredLineSpeed * 0.95; (* Fast deceleration *)

        rAniloxTorqueCmd := 0.0;
        rAniloxSpeedCmd := rFilteredLineSpeed * 6.0;

        IF rFilteredLineSpeed < 1.0 THEN
            rFilteredLineSpeed := 0.0;
            eState := 1;
        END_IF

END_CASE

END_FUNCTION_BLOCK
```

