FUNCTION_BLOCK FB_ContinuousMiner_Hydraulics
TITLE = 'Continuous Miner with Hydraulics'
VERSION : '1.1'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    rShearerTargetElevation : REAL;
    rConveyorTargetSpeed : REAL;
    rShearerActualElevation : REAL;
    rConveyorActualSpeed : REAL;
    rHydraulicPressure : REAL; // Current hydraulic pressure in bar
    rMaxSafePressure : REAL := 250.0; // Max safe pressure in bar
    bEstop : BOOL; // External emergency stop
END_VAR

VAR_OUTPUT
    rShearerLiftCmd : REAL;
    rConveyorSpeedCmd : REAL;
    bSystemRunning : BOOL;
    bPressureFault : BOOL; // Indicates hydraulic overpressure
END_VAR

VAR
    bActive : BOOL := FALSE;
    rElevationError : REAL;
    Kp_Elev : REAL := 0.5;
END_VAR

BEGIN
    // Safety and Fault Monitoring
    IF rHydraulicPressure > rMaxSafePressure THEN
        bPressureFault := TRUE;
    ELSE
        bPressureFault := FALSE;
    END_IF;

    // Start/Stop/Fault Logic
    IF bEstop OR bPressureFault THEN
        bActive := FALSE;
    ELSIF bStart AND NOT bStop THEN
        bActive := TRUE;
    ELSIF bStop THEN
        bActive := FALSE;
    END_IF;

    bSystemRunning := bActive;

    IF bActive THEN
        // Shearer Drum Elevation Control
        rElevationError := rShearerTargetElevation - rShearerActualElevation;
        rShearerLiftCmd := rElevationError * Kp_Elev;

        // Clamp lift command
        IF rShearerLiftCmd > 100.0 THEN rShearerLiftCmd := 100.0; END_IF;
        IF rShearerLiftCmd < -100.0 THEN rShearerLiftCmd := -100.0; END_IF;

        // Conveyor Tram Control
        rConveyorSpeedCmd := rConveyorTargetSpeed;
    ELSE
        rShearerLiftCmd := 0.0;
        rConveyorSpeedCmd := 0.0;
    END_IF;

END_FUNCTION_BLOCK
