FUNCTION_BLOCK FB_LH2_Transfer_Control
VAR_INPUT
    bStartTransfer : BOOL; // Initiate LH2 transfer sequence
    bEmergencyStop : BOOL; // Emergency Shutdown (ESD)
    rPipeTemp_K : REAL; // Current temperature of vacuum-jacketed pipe in Kelvin
    rBOG_Pressure_barg : REAL; // Boil-off gas pressure in barg
    bValveA_Closed_Limit : BOOL; // Cryo Valve A physical limit switch (Closed)
    bValveA_Open_Limit : BOOL; // Cryo Valve A physical limit switch (Open)
    rValveA_Upstream_Press : REAL; // Pressure upstream of Valve A
    rValveA_Downstream_Press : REAL; // Pressure downstream of Valve A
    rFlowRate_kg_s : REAL; // LH2 Flow Rate
    rTankLevel_Pct : REAL; // Destination tank level
END_VAR
VAR_OUTPUT
    bCoolDownActive : BOOL; // Pipe cool-down sequence is running
    bTransferActive : BOOL; // Active liquid transfer
    bBOG_Reliquefaction_On : BOOL; // Reliquefaction plant running
    bValveA_Cmd : BOOL; // Command to open Valve A
    bValveLeakAlarm : BOOL; // Cryo valve leak detected
    bESDTripped : BOOL; // Emergency stop active
    iState : INT; // Current state of the sequence
    sStatusMsg : STRING[50]; // Status message
END_VAR
VAR
    tonCoolDown : TON;
    tonLeakCheck : TON;
    rTargetCoolDownTemp : REAL := 25.0; // Target cool-down temp (K)
    rMaxBOGPressure : REAL := 1.5; // Max BOG pressure before reliquefaction
    rLeakDP_Threshold : REAL := 0.2; // Delta P threshold for leak detection
END_VAR

// Emergency Stop Handling
IF bEmergencyStop THEN
    bCoolDownActive := FALSE;
    bTransferActive := FALSE;
    bValveA_Cmd := FALSE;
    bBOG_Reliquefaction_On := FALSE;
    bESDTripped := TRUE;
    iState := 99;
    sStatusMsg := 'EMERGENCY STOP TRIPPED';
    RETURN;
ELSE
    bESDTripped := FALSE;
END_IF;

// Boil-Off Gas (BOG) Management
IF rBOG_Pressure_barg > rMaxBOGPressure THEN
    bBOG_Reliquefaction_On := TRUE;
ELSIF rBOG_Pressure_barg < (rMaxBOGPressure - 0.3) THEN
    bBOG_Reliquefaction_On := FALSE;
END_IF;

// Valve Leak Detection (When valve is commanded closed but DP drops unexpectedly)
IF NOT bValveA_Cmd AND bValveA_Closed_Limit THEN
    tonLeakCheck(IN := (rValveA_Upstream_Press - rValveA_Downstream_Press) < rLeakDP_Threshold, PT := T#5s);
    IF tonLeakCheck.Q AND rValveA_Upstream_Press > 2.0 THEN
        bValveLeakAlarm := TRUE;
    END_IF;
ELSE
    tonLeakCheck(IN := FALSE);
    // Latch alarm until reset
END_IF;

// State Machine for Transfer Sequence
CASE iState OF
    0: // Idle
        bCoolDownActive := FALSE;
        bTransferActive := FALSE;
        bValveA_Cmd := FALSE;
        sStatusMsg := 'IDLE - READY FOR START';
        IF bStartTransfer AND rTankLevel_Pct < 95.0 THEN
            iState := 10;
        END_IF;

    10: // Initiate Cool-Down
        bCoolDownActive := TRUE;
        sStatusMsg := 'COOL-DOWN SEQUENCE ACTIVE';
        // Pulse valve to slowly introduce LH2
        tonCoolDown(IN := NOT tonCoolDown.Q, PT := T#2s);
        IF tonCoolDown.Q THEN
            bValveA_Cmd := NOT bValveA_Cmd; // Pulsing
        END_IF;

        IF rPipeTemp_K <= rTargetCoolDownTemp THEN
            iState := 20;
            bValveA_Cmd := FALSE;
        END_IF;

    20: // Stabilize Temp
        bCoolDownActive := FALSE;
        sStatusMsg := 'TEMPERATURE STABILIZED';
        tonCoolDown(IN := TRUE, PT := T#10s);
        IF tonCoolDown.Q THEN
            tonCoolDown(IN := FALSE);
            iState := 30;
        END_IF;

    30: // Full Transfer
        bTransferActive := TRUE;
        bValveA_Cmd := TRUE;
        sStatusMsg := 'ACTIVE TRANSFER';

        IF rTankLevel_Pct >= 95.0 OR NOT bStartTransfer THEN
            iState := 40;
        END_IF;

    40: // Shutdown Sequence
        bTransferActive := FALSE;
        bValveA_Cmd := FALSE;
        sStatusMsg := 'TRANSFER COMPLETE - DRAINING';
        IF bValveA_Closed_Limit THEN
            iState := 0;
        END_IF;

    99: // Fault state
        sStatusMsg := 'FAULT - RESET REQUIRED';
        IF NOT bEmergencyStop THEN
            iState := 0; // simplistic reset
        END_IF;

    ELSE
        iState := 0;
END_CASE;
END_FUNCTION_BLOCK
```

