FUNCTION_BLOCK FB_AFP_TapeLayingHead
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable for AFP head *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (Dual Channel SIL3) *)
