FUNCTION_BLOCK FB_EAF_ElectrodeImpedanceRegulator
VAR_INPUT
    bEnable                : BOOL;     (* System enable signal *)
    bEmergencyStop         : BOOL;     (* Safety relay OK signal - active high *)
    rPhaseVoltage          : REAL;     (* Phase voltage from PT [V] *)
    rPhaseCurrent          : REAL;     (* Phase current from CT [A] *)
    rImpedanceSetpoint     : REAL;     (* Target impedance for operating point [mOhm] *)
    rTransformerTapVolts   : REAL;     (* Current furnace transformer tap voltage [V] *)
    bFurnaceRoofClosed     : BOOL;     (* Interlock: Roof closed and locked *)
    bCoolingWaterOK        : BOOL;     (* Interlock: Panel and roof cooling water flows OK *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;     (* System ready status *)
    rElectrodePosCmd       : REAL;     (* Control signal to actuator [mm] *)
    bAlarm                 : BOOL;     (* Fault alarm output *)
    rCalculatedImpedance   : REAL;     (* Actual calculated phase impedance [mOhm] *)
    rFlickerCompSignal     : REAL;     (* SVC / STATCOM flicker compensation signal [kVAR] *)
    bElectrodeSlip         : BOOL;     (* Warning: Suspected electrode slip or breakage *)
END_VAR
VAR
    iState                 : INT := 0; (* Internal state machine *)
    tTimer                 : TON;      (* State transition timer *)
    tArcLossTimer          : TON;      (* Arc loss detection timer *)
    rVoltageFiltered       : REAL;
    rCurrentFiltered       : REAL;
    rImpedanceError        : REAL;
    rIntegralAccumulator   : REAL := 0.0;
    rProportionalGain      : REAL := 2.5;
    rIntegralGain          : REAL := 0.15;
    rMaxHoistSpeed         : REAL := 150.0; (* mm/s *)
END_VAR

(* === MAIN LOGIC === *)
(* Safety and Interlocks check *)
IF NOT bEmergencyStop OR NOT bFurnaceRoofClosed OR NOT bCoolingWaterOK THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rElectrodePosCmd := 0.0; (* Stop electrode movement *)
    iState := 0;
    RETURN;
END_IF;

(* Signal filtering (first order lag) *)
rVoltageFiltered := rVoltageFiltered + 0.1 * (rPhaseVoltage - rVoltageFiltered);
rCurrentFiltered := rCurrentFiltered + 0.1 * (rPhaseCurrent - rCurrentFiltered);

(* Safe Impedance Calculation (prevent division by zero) *)
IF rCurrentFiltered > 10.0 THEN
    rCalculatedImpedance := (rVoltageFiltered / rCurrentFiltered) * 1000.0; (* Convert to mOhm *)
ELSE
    rCalculatedImpedance := 9999.0; (* Infinite/Open circuit impedance *)
END_IF;

(* PI Regulator for Impedance Control *)
rImpedanceError := rImpedanceSetpoint - rCalculatedImpedance;

(* Anti-windup for integral accumulator *)
rIntegralAccumulator := rIntegralAccumulator + (rImpedanceError * rIntegralGain);
IF rIntegralAccumulator > rMaxHoistSpeed THEN rIntegralAccumulator := rMaxHoistSpeed; END_IF;
IF rIntegralAccumulator < -rMaxHoistSpeed THEN rIntegralAccumulator := -rMaxHoistSpeed; END_IF;

(* Harmonic Flicker Active Compensation Estimation (Simplified based on V variance) *)
rFlickerCompSignal := ABS(rPhaseVoltage - rVoltageFiltered) * 50.0; 

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rElectrodePosCmd := 0.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* BORE DOWN - Initial Arc Strike *)
        rElectrodePosCmd := -50.0; (* Lower electrodes slowly *)
        IF rCurrentFiltered > 5000.0 THEN
            (* Arc established *)
            iState := 20;
        END_IF;

    20: (* MELT DOWN - Main regulation loop *)
        rElectrodePosCmd := (rImpedanceError * rProportionalGain) + rIntegralAccumulator;

        (* Limit max velocity commands *)
        IF rElectrodePosCmd > rMaxHoistSpeed THEN rElectrodePosCmd := rMaxHoistSpeed; END_IF;
        IF rElectrodePosCmd < -rMaxHoistSpeed THEN rElectrodePosCmd := -rMaxHoistSpeed; END_IF;

        (* Arc Loss Detection *)
        tArcLossTimer(IN := (rCurrentFiltered < 1000.0), PT := T#2S);
        IF tArcLossTimer.Q THEN
            (* Arc lost for 2 seconds, attempt re-strike *)
            tArcLossTimer(IN := FALSE);
            iState := 10;
        END_IF;

        (* Complete condition (normally dictated by total kWh injected, simplified here) *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

