FUNCTION_BLOCK "FrancisTurbine_GuideVane_Mut2"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Enable_Control : Bool;
      Target_Gate_Position : Real; 
      Actual_Gate_Position : Real; 
      Hydraulic_Pressure : Real; 
      Emergency_Stop : Bool;
      Profinet_Status : Word;
   END_VAR

   VAR_OUTPUT 
      Servo_Control_Signal : Real; 
      Gate_Sync_Achieved : Bool;
      Hydraulic_Fault : Bool;
      ESD_Active : Bool;
      Profinet_Comms_Fault : Bool;
