    // Profinet Communication Check
    IF #Profinet_Status <> 16#0000 THEN
        #Profinet_Comms_Fault := TRUE;
        #Diagnostic_Code := 16#F001;
    ELSE
        #Profinet_Comms_Fault := FALSE;
    END_IF;

    IF #Hydraulic_Pressure < #Min_Pressure THEN
        #Hydraulic_Fault := TRUE;
        #Diagnostic_Code := 16#E001;
