        IF #Emergency_Stop THEN #Diagnostic_Code := 16#E999; END_IF;
        RETURN;
    ELSE
        #ESD_Active := FALSE;
        IF NOT #Hydraulic_Fault AND NOT #Profinet_Comms_Fault THEN
            #Diagnostic_Code := 16#0000;
        END_IF;
    END_IF;

    IF NOT #Enable_Control THEN
        #Servo_Control_Signal := 0.0;
        #Gate_Sync_Achieved := FALSE;
        RETURN;
