FUNCTION_BLOCK FB_PET_Blow_Molding_Control
(*
    Highly complex control scenario for a PET Bottle Blow Molding Machine.
    Handles preform infrared oven thermal profiling, stretch rod servo kinematics,
    and high-pressure blow air cascades (P1, P2, P3).
*)
VAR_INPUT
    bEnable                 : BOOL; // System enable
    bEstop                  : BOOL; // Emergency stop (Active Low)
    rMasterVelocity         : REAL; // Machine speed (Bottles per hour)

    // Thermal Profiling (Infrared Oven)
    arPreformTempSensors    : ARRAY[1..10] OF REAL; // Actual temperature of preform zones
    arOvenZoneSetpoints     : ARRAY[1..10] OF REAL; // Setpoints for oven zones
    rOvenAmbientTemp        : REAL;

    // Stretch Rod Servo Kinematics
    rStretchRodActualPos    : REAL; // Actual position of the stretch rod (mm)
    rStretchRodActualVel    : REAL; // Actual velocity of the stretch rod (mm/s)

    // Pressure Sensors
    rPreBlowPressure        : REAL; // P1 actual
    rMainBlowPressure       : REAL; // P2 actual
    rRecoveryPressure       : REAL; // P3 actual
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;
    bFault                  : BOOL;
    iFaultCode              : INT;

    // Oven Control
    arOvenHeaterOutputs     : ARRAY[1..10] OF REAL; // PWM output to IR heaters (0-100%)

    // Servo Control
    rStretchRodTargetPos    : REAL;
    rStretchRodTargetVel    : REAL;
    bStretchRodEnable       : BOOL;

    // Valve Control
    bValvePreBlow           : BOOL; // Activate P1
    bValveMainBlow          : BOOL; // Activate P2
    bValveExhaust           : BOOL; // Activate Exhaust
    bValveRecovery          : BOOL; // Activate Air Recovery
END_VAR

VAR
    // State Machine
    eState                  : (INIT, HEATING, READY, STRETCH_BLOW, RECOVERY, FAULT);
    eBlowState              : (IDLE, PRE_BLOW, MAIN_BLOW, EXHAUSTING);

    // PID Controllers for Oven
    arHeaterPID_Kp          : ARRAY[1..10] OF REAL := [10(2.5)];
    arHeaterPID_Ki          : ARRAY[1..10] OF REAL := [10(0.1)];
    arHeaterPID_Kd          : ARRAY[1..10] OF REAL := [10(0.05)];
    arHeaterError           : ARRAY[1..10] OF REAL;
    arHeaterIntegral        : ARRAY[1..10] OF REAL;
    arHeaterPrevError       : ARRAY[1..10] OF REAL;

    i                       : INT;
    rDeltaTime              : REAL := 0.01; // 10ms task cycle

    // Kinematic Profile Parameters
    rStretchStrokeLength    : REAL := 350.0; // mm
    rStretchMaxVel          : REAL := 1500.0; // mm/s
    rStretchAcceleration    : REAL := 5000.0; // mm/s^2
    rTimeInBlowCycle        : REAL;

    // Blow Timers
    tPreBlowDuration        : TIME := T#150MS;
    tMainBlowDuration       : TIME := T#400MS;
    tExhaustDuration        : TIME := T#100MS;
    fbPreBlowTimer          : TON;
    fbMainBlowTimer         : TON;
    fbExhaustTimer          : TON;
END_VAR

// Emergency Stop Check
IF NOT bEstop THEN
    eState := FAULT;
    iFaultCode := 999; // E-Stop pressed
END_IF;

// Main State Machine
CASE eState OF
    INIT:
        bSystemReady := FALSE;
        bFault := FALSE;
        iFaultCode := 0;
        bStretchRodEnable := FALSE;
        bValvePreBlow := FALSE;
        bValveMainBlow := FALSE;
        bValveExhaust := FALSE;
        bValveRecovery := FALSE;
        rTimeInBlowCycle := 0.0;

        FOR i := 1 TO 10 DO
            arHeaterIntegral[i] := 0.0;
            arOvenHeaterOutputs[i] := 0.0;
        END_FOR;

        IF bEnable AND bEstop THEN
            eState := HEATING;
        END_IF;

    HEATING:
        bSystemReady := FALSE;
        // Thermal PID Control for IR Oven Zones
        FOR i := 1 TO 10 DO
            arHeaterError[i] := arOvenZoneSetpoints[i] - arPreformTempSensors[i];
            arHeaterIntegral[i] := arHeaterIntegral[i] + (arHeaterError[i] * rDeltaTime);

            // Anti-windup
            IF arHeaterIntegral[i] > 100.0 THEN arHeaterIntegral[i] := 100.0; END_IF;
            IF arHeaterIntegral[i] < 0.0 THEN arHeaterIntegral[i] := 0.0; END_IF;

            arOvenHeaterOutputs[i] := (arHeaterPID_Kp[i] * arHeaterError[i]) + 
                                      (arHeaterPID_Ki[i] * arHeaterIntegral[i]) + 
                                      (arHeaterPID_Kd[i] * (arHeaterError[i] - arHeaterPrevError[i]) / rDeltaTime);

            // Clamp Output
            IF arOvenHeaterOutputs[i] > 100.0 THEN arOvenHeaterOutputs[i] := 100.0; END_IF;
            IF arOvenHeaterOutputs[i] < 0.0 THEN arOvenHeaterOutputs[i] := 0.0; END_IF;

            arHeaterPrevError[i] := arHeaterError[i];
        END_FOR;

        // Check if all zones are within tolerance (e.g., +/- 2 degrees)
        // Simplified check here for brevity
        IF (arPreformTempSensors[5] >= arOvenZoneSetpoints[5] - 2.0) THEN
            eState := READY;
        END_IF;

    READY:
        bSystemReady := TRUE;
        bStretchRodEnable := TRUE;

        // Start Blow Cycle Trigger (Simulated by external fast cycle)
        IF bEnable THEN
            eState := STRETCH_BLOW;
            eBlowState := PRE_BLOW;
            rTimeInBlowCycle := 0.0;
        END_IF;

    STRETCH_BLOW:
        rTimeInBlowCycle := rTimeInBlowCycle + rDeltaTime;

        // Stretch Rod Kinematics - Generation of S-Curve or Trapezoidal Profile
        // Simplified Trapezoidal Profile for Stretch Rod
        IF rStretchRodActualPos < rStretchStrokeLength THEN
            rStretchRodTargetVel := rStretchMaxVel;
            rStretchRodTargetPos := rStretchRodActualPos + (rStretchRodTargetVel * rDeltaTime);
        ELSE
            rStretchRodTargetVel := 0.0;
        END_IF;

        // Blow Air Cascades
        CASE eBlowState OF
            PRE_BLOW:
                bValvePreBlow := TRUE;
                bValveMainBlow := FALSE;
                bValveExhaust := FALSE;
                fbPreBlowTimer(IN:= TRUE, PT:= tPreBlowDuration);

                IF fbPreBlowTimer.Q THEN
                    fbPreBlowTimer(IN:= FALSE);
                    eBlowState := MAIN_BLOW;
                END_IF;

            MAIN_BLOW:
                bValvePreBlow := FALSE;
                bValveMainBlow := TRUE;
                fbMainBlowTimer(IN:= TRUE, PT:= tMainBlowDuration);

                IF fbMainBlowTimer.Q THEN
                    fbMainBlowTimer(IN:= FALSE);
                    eBlowState := EXHAUSTING;
                    eState := RECOVERY;
                END_IF;
        END_CASE;

    RECOVERY:
        // Air Recovery Phase (P3)
        bValveMainBlow := FALSE;
        bValveRecovery := TRUE; // Route high pressure air to recovery tank

        IF rMainBlowPressure < (rRecoveryPressure + 1.0) THEN // When pressures equalize
            bValveRecovery := FALSE;
            bValveExhaust := TRUE;
            fbExhaustTimer(IN:= TRUE, PT:= tExhaustDuration);

            IF fbExhaustTimer.Q THEN
                fbExhaustTimer(IN:= FALSE);
                bValveExhaust := FALSE;

                // Reset Stretch Rod
                rStretchRodTargetPos := 0.0;

                IF rStretchRodActualPos <= 1.0 THEN
                    eState := READY; // Ready for next bottle
                END_IF;
            END_IF;
        END_IF;

    FAULT:
        bSystemReady := FALSE;
        bFault := TRUE;
        bStretchRodEnable := FALSE;
        bValvePreBlow := FALSE;
        bValveMainBlow := FALSE;
        bValveExhaust := TRUE; // Safe state: exhaust pressure
        bValveRecovery := FALSE;

        FOR i := 1 TO 10 DO
            arOvenHeaterOutputs[i] := 0.0;
        END_FOR;

        IF bEstop AND bEnable THEN
            eState := INIT; // Reset fault
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
