FUNCTION_BLOCK FB_ProteinAChromatography_MCC
VAR_INPUT
    (* System & Safety Inputs *)
    bEnable            : BOOL;     (* System enable signal *)
    bEmergencyStop     : BOOL;     (* Safety relay OK signal, False = E-Stop active *)

    (* Process Variable Inputs *)
    rUV_Absorbance     : REAL;     (* UV absorbance at 280 nm in AU for product detection *)
    rFlowRate          : REAL;     (* Column flow rate in L/min *)
    rColumnPressure    : REAL;     (* Pre-column pressure in bar *)
    rpH_Value          : REAL;     (* pH of the column effluent *)
    rConductivity      : REAL;     (* Conductivity of the column effluent in mS/cm *)
    rBindingCapacity   : REAL;     (* Dynamic binding capacity prediction base in g/L *)
    rVolAccumulated    : REAL;     (* Volume processed in current step in Liters *)
END_VAR
VAR_OUTPUT
    (* System Status Outputs *)
    bSystemReady       : BOOL;     (* System ready for operation *)
    bAlarm             : BOOL;     (* Fault alarm output (e.g. overpressure) *)

    (* Control Signals Outputs *)
    rPumpSpeedCtrl     : REAL;     (* 0-100% control signal to main feed pump *)
    bValveLoadOpen     : BOOL;     (* Open load/feed valve *)
    bValveWashOpen     : BOOL;     (* Open wash buffer valve *)
    bValveEluteOpen    : BOOL;     (* Open elution buffer valve *)
    bProductPoolOpen   : BOOL;     (* Open product collection pooling valve *)
    bWasteValveOpen    : BOOL;     (* Open waste diversion valve *)
    iCurrentStep       : INT;      (* Active process step identifier *)
END_VAR
VAR
    (* Internal State & Timers *)
    iState             : INT := 0; 
    tStepTimer         : TON;
    tDebounceTimer     : TON;

    (* Product Pooling Logic Variables *)
    rUV_ThresholdStart : REAL := 0.05;  (* Threshold to start pooling (AU) *)
    rUV_ThresholdStop  : REAL := 0.02;  (* Threshold to stop pooling (AU) *)
    rMaxPressure       : REAL := 3.5;   (* Max column pressure limit (bar) *)
    bBreakthrough      : BOOL := FALSE;
    rEstimatedMass     : REAL := 0.0;

    (* Phase constants *)
    STATE_IDLE         : INT := 0;
    STATE_EQUILIBRATE  : INT := 10;
    STATE_LOAD         : INT := 20;
    STATE_WASH         : INT := 30;
    STATE_ELUTION      : INT := 40;
    STATE_STRIP        : INT := 50;
    STATE_CIP          : INT := 60;
    STATE_FAULT        : INT := 99;
END_VAR

(* === MAIN LOGIC === *)
(* Critical Safety Interlock: E-Stop or Overpressure *)
IF NOT bEmergencyStop OR rColumnPressure > rMaxPressure THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    iState := STATE_FAULT;

    (* Fail-safe valve configuration *)
    rPumpSpeedCtrl := 0.0;
    bValveLoadOpen := FALSE;
    bValveWashOpen := FALSE;
    bValveEluteOpen := FALSE;
    bProductPoolOpen := FALSE;
    bWasteValveOpen := TRUE; 
    RETURN;
END_IF;

(* Normal Operation Step Sequencing *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        bWasteValveOpen := TRUE;

        IF bEnable THEN
            iState := STATE_EQUILIBRATE;
            bSystemReady := FALSE;
        END_IF;

    10: (* EQUILIBRATE *)
        (* Establish baseline pH and conductivity *)
        bValveWashOpen := TRUE;
        bWasteValveOpen := TRUE;
        rPumpSpeedCtrl := 50.0;

        (* Check criteria: target pH ~7.2, Cond ~15 mS/cm *)
        IF (rpH_Value > 7.1 AND rpH_Value < 7.3) AND (rConductivity > 14.0 AND rConductivity < 16.0) THEN
            tStepTimer(IN := TRUE, PT := T#30S); (* Hold for stability *)
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                bValveWashOpen := FALSE;
                iState := STATE_LOAD;
            END_IF;
        ELSE
            tStepTimer(IN := FALSE);
        END_IF;

    20: (* LOAD *)
        (* Bind mAb to Protein A resin until breakthrough *)
        bValveLoadOpen := TRUE;
        bWasteValveOpen := TRUE;
        rPumpSpeedCtrl := 35.0; 

        (* Breakthrough detection via UV absorbance or capacity limit *)
        rEstimatedMass := rEstimatedMass + (rFlowRate * 0.05); (* simplified mass integration *)
        IF rUV_Absorbance > 0.1 OR rEstimatedMass >= rBindingCapacity THEN
            bBreakthrough := TRUE;
            bValveLoadOpen := FALSE;
            iState := STATE_WASH;
        END_IF;

    30: (* WASH *)
        (* Wash away host cell proteins and DNA *)
        bValveWashOpen := TRUE;
        bWasteValveOpen := TRUE;
        rPumpSpeedCtrl := 60.0;

        tStepTimer(IN := TRUE, PT := T#5M);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            bValveWashOpen := FALSE;
            iState := STATE_ELUTION;
        END_IF;

    40: (* ELUTION (Product Collection) *)
        (* Lower pH to elute product, collect based on UV peak *)
        bValveEluteOpen := TRUE;
        rPumpSpeedCtrl := 25.0;

        (* Peak Collection Logic *)
        IF rUV_Absorbance >= rUV_ThresholdStart THEN
            bProductPoolOpen := TRUE;
            bWasteValveOpen := FALSE;
        ELSIF rUV_Absorbance <= rUV_ThresholdStop AND bProductPoolOpen THEN
            bProductPoolOpen := FALSE;
            bWasteValveOpen := TRUE;
            bValveEluteOpen := FALSE;
            iState := STATE_STRIP;
        END_IF;

    50: (* STRIP *)
        (* Remove strongly bound impurities *)
        bValveEluteOpen := TRUE;
        bWasteValveOpen := TRUE;
        rPumpSpeedCtrl := 80.0;

        tStepTimer(IN := TRUE, PT := T#2M);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            bValveEluteOpen := FALSE;
            iState := STATE_CIP;
        END_IF;

    60: (* CIP (Cleaning in Place) *)
        (* Sanitize column with NaOH *)
        bWasteValveOpen := TRUE;
        rPumpSpeedCtrl := 50.0;

        tStepTimer(IN := TRUE, PT := T#10M);
        IF tStepTimer.Q THEN
            tStepTimer(IN := FALSE);
            iState := 0; (* Return to IDLE *)
        END_IF;

    99: (* FAULT *)
        (* System in fault, waiting for manual intervention/disable *)
        IF NOT bEnable AND NOT bEmergencyStop THEN
            iState := 0;
        END_IF;

END_CASE;

iCurrentStep := iState;

END_FUNCTION_BLOCK
