```iec-st
(*
================================================================================
MICRO-TUNNELING PIPE JACKING CONTROLLER (MT-PJC)
================================================================================
Platform: IEC 61131-3 (Structured Text)
Engineer: Lead Mechanical Engineer, TBM Division
Description:
Master sequence controller for closed-face microtunneling boring machine.
Handles the simultaneous operation of 8 thrust cylinders, closed-loop steering 
via laser target surveying, and bentonite slurry lubrication.
================================================================================
*)

FUNCTION_BLOCK FB_MicrotunnelingJackingController
VAR_INPUT
    bSystemEnable : BOOL;           // Master enable switch
    bStartJack : BOOL;              // Start pipe jacking sequence
    bStopJack : BOOL;               // Emergency stop or normal stop

    // Laser Surveying Inputs
    rLaserTargetX : REAL;           // X-axis deviation from laser target (mm)
    rLaserTargetY : REAL;           // Y-axis deviation from laser target (mm)
    rPitchAngle : REAL;             // Current pitch angle (degrees)
    rYawAngle : REAL;               // Current yaw angle (degrees)

    // Hydraulic System
    rSystemPressure : REAL;         // Main hydraulic pressure (bar)
    rThrustCylindersPos : ARRAY[1..8] OF REAL; // Position of 8 cylinders (mm)
    rThrustCylindersPress : ARRAY[1..8] OF REAL; // Pressure of 8 cylinders (bar)

    // Slurry Lubrication
    rBentoniteFlowRate : REAL;      // Current flow rate (L/min)
    rBentonitePressure : REAL;      // Slurry line pressure (bar)
    rCutterheadTorque : REAL;       // Cutterhead torque feedback (kNm)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bJackingActive : BOOL;
    bAlarmActive : BOOL;

    // Hydraulic Control
    rCylForceCmd : ARRAY[1..8] OF REAL; // Commanded force for each cylinder (kN)
    bCylExtendCmd : ARRAY[1..8] OF BOOL;
    bCylRetractCmd : ARRAY[1..8] OF BOOL;

    // Slurry System
    rBentonitePumpSpeedCmd : REAL;  // Commanded speed for bentonite pump (0-100%)
    bBentoniteValveOpen : BOOL;     // Slurry injection valve

    // Diagnostics
    sCurrentState : STRING(32);
END_VAR

VAR
    // State Machine
    eState : (INIT, IDLE, PRE_LUBE, JACKING, STEERING_CORRECT, PAUSED, ERROR);

    // PID Controllers for Steering
    fbSteeringPID_X : PID_CONTROLLER;
    fbSteeringPID_Y : PID_CONTROLLER;

    // Slurry Control
    fbSlurryPressurePID : PID_CONTROLLER;

    // Internal Variables
    i : INT;
    rAvgPosition : REAL;
    rBaseThrustCmd : REAL := 1500.0; // Base thrust per cylinder (kN)
    rMaxThrust : REAL := 3000.0;     // Max allowable thrust (kN)
    rSteeringBiasX : REAL;
    rSteeringBiasY : REAL;

    tonPreLube : TON;
END_VAR

// =============================================================================
// MAIN STATE MACHINE
// =============================================================================
CASE eState OF
    INIT:
        sCurrentState := 'INITIALIZING';
        // Reset commands
        FOR i := 1 TO 8 DO
            rCylForceCmd[i] := 0.0;
            bCylExtendCmd[i] := FALSE;
            bCylRetractCmd[i] := FALSE;
        END_FOR;
        bBentoniteValveOpen := FALSE;
        rBentonitePumpSpeedCmd := 0.0;
        bAlarmActive := FALSE;

        IF bSystemEnable THEN
            eState := IDLE;
        END_IF;

    IDLE:
        sCurrentState := 'IDLE';
        bSystemReady := TRUE;
        bJackingActive := FALSE;

        IF bStartJack AND NOT bStopJack THEN
            bSystemReady := FALSE;
            eState := PRE_LUBE;
        ELSIF NOT bSystemEnable THEN
            eState := INIT;
        END_IF;

    PRE_LUBE:
        sCurrentState := 'PRE-LUBRICATION';
        bBentoniteValveOpen := TRUE;

        // Bentonite Pressure Control (Set Point 3.5 bar)
        fbSlurryPressurePID(
            SetPoint := 3.5,
            ProcessValue := rBentonitePressure,
            Kp := 2.5, Ki := 0.8, Kd := 0.1,
            ControlOutput => rBentonitePumpSpeedCmd
        );

        tonPreLube(IN := TRUE, PT := T#15S);

        IF tonPreLube.Q THEN
            tonPreLube(IN := FALSE);
            eState := JACKING;
        END_IF;

        IF bStopJack THEN eState := IDLE; END_IF;

    JACKING:
        sCurrentState := 'JACKING ACTIVE';
        bJackingActive := TRUE;

        // Maintain Bentonite Lubrication based on Cutterhead Torque
        // Increase lubrication if torque spikes
        IF rCutterheadTorque > 150.0 THEN
            fbSlurryPressurePID.SetPoint := 5.0; // Boost pressure
        ELSE
            fbSlurryPressurePID.SetPoint := 3.5; // Normal pressure
        END_IF;

        fbSlurryPressurePID(
            ProcessValue := rBentonitePressure,
            ControlOutput => rBentonitePumpSpeedCmd
        );

        // Steering Closed-Loop Surveying
        // Using Laser Targets to calculate Bias for Cylinders
        // Left/Right cylinders for X-axis (Yaw)
        fbSteeringPID_X(
            SetPoint := 0.0,
            ProcessValue := rLaserTargetX,
            Kp := 15.0, Ki := 2.0, Kd := 5.0,
            ControlOutput => rSteeringBiasX
        );

        // Top/Bottom cylinders for Y-axis (Pitch)
        fbSteeringPID_Y(
            SetPoint := 0.0,
            ProcessValue := rLaserTargetY,
            Kp := 15.0, Ki := 2.0, Kd := 5.0,
            ControlOutput => rSteeringBiasY
        );

        // Hydraulic Jacking Force Distribution (8 Cylinders)
        // Cylinders 1, 8 (Top), 4, 5 (Bottom), 2, 3 (Right), 6, 7 (Left)
        FOR i := 1 TO 8 DO
            bCylExtendCmd[i] := TRUE;
            bCylRetractCmd[i] := FALSE;
            rCylForceCmd[i] := rBaseThrustCmd;
        END_FOR;

        // Apply Steering Bias
        // Pitch Control
        rCylForceCmd[1] := LIMIT(0.0, rBaseThrustCmd - rSteeringBiasY, rMaxThrust);
        rCylForceCmd[8] := LIMIT(0.0, rBaseThrustCmd - rSteeringBiasY, rMaxThrust);
        rCylForceCmd[4] := LIMIT(0.0, rBaseThrustCmd + rSteeringBiasY, rMaxThrust);
        rCylForceCmd[5] := LIMIT(0.0, rBaseThrustCmd + rSteeringBiasY, rMaxThrust);

        // Yaw Control
        rCylForceCmd[2] := LIMIT(0.0, rBaseThrustCmd - rSteeringBiasX, rMaxThrust);
        rCylForceCmd[3] := LIMIT(0.0, rBaseThrustCmd - rSteeringBiasX, rMaxThrust);
        rCylForceCmd[6] := LIMIT(0.0, rBaseThrustCmd + rSteeringBiasX, rMaxThrust);
        rCylForceCmd[7] := LIMIT(0.0, rBaseThrustCmd + rSteeringBiasX, rMaxThrust);

        // Safety / Limit check
        rAvgPosition := 0.0;
        FOR i := 1 TO 8 DO
            rAvgPosition := rAvgPosition + rThrustCylindersPos[i];
            IF rThrustCylindersPress[i] > 320.0 THEN // Overpressure alarm
                bAlarmActive := TRUE;
                eState := ERROR;
            END_IF;
        END_FOR;
        rAvgPosition := rAvgPosition / 8.0;

        IF bStopJack THEN
            eState := IDLE;
        END_IF;

    ERROR:
        sCurrentState := 'SYSTEM ERROR';
        bJackingActive := FALSE;
        bAlarmActive := TRUE;
        bBentoniteValveOpen := FALSE;
        rBentonitePumpSpeedCmd := 0.0;

        FOR i := 1 TO 8 DO
            rCylForceCmd[i] := 0.0;
            bCylExtendCmd[i] := FALSE;
            bCylRetractCmd[i] := FALSE;
        END_FOR;

        IF NOT bSystemEnable THEN
            eState := INIT;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

