FUNCTION_BLOCK FB_Quantum_QubitController
VAR_INPUT
    bEnable                 : BOOL;         (* Enable Qubit Controller *)
    eState                  : DINT := 0;    (* Current PackML State (0=Stopped, 1=Starting, 2=Execute) *)
    fTargetFrequency        : LREAL;        (* Qubit operating frequency [GHz], e.g., 5.0 *)
    fDetuningDelta          : LREAL;        (* Anharmonicity detuning [GHz], e.g., -0.3 for transmon *)
    fPiPulseDuration        : LREAL;        (* Duration of Pi pulse [ns] *)
    fDRAGAlpha              : LREAL;        (* DRAG scaling coefficient *)
    bTriggerXGate           : BOOL;         (* Trigger X gate (Pi rotation about X) *)
    bTriggerZGate           : BOOL;         (* Trigger fast flux Z-gate *)
    fZGateDetuning          : LREAL;        (* Target Z-gate detuning [MHz] *)
    fHEMTOptimalVoltage     : LREAL;        (* HEMT optimal bias voltage [V] *)
    fHEMTOptimalCurrent     : LREAL;        (* HEMT optimal bias current [mA] *)
END_VAR

VAR_OUTPUT
    bReady                  : BOOL;         (* System ready for operations *)
    fPulseI                 : LREAL;        (* I-channel baseband output *)
    fPulseQ                 : LREAL;        (* Q-channel baseband output *)
    fFluxBiasVoltage        : LREAL;        (* Fast flux bias DAC output [V] *)
    fHEMTBiasVoltageOut     : LREAL;        (* HEMT bias DAC output [V] *)
    bError                  : BOOL;         (* Error active flag *)
    nErrorID                : UDINT;        (* Error Code *)
    fReadoutFidelity        : LREAL;        (* Estimated Readout Fidelity *)
END_VAR

VAR
    (* State Machine & Timing *)
    fbStateTimer            : TON;
    fClockTimer             : LREAL := 0.0;
    dtSampleTime            : LREAL := 0.1; (* DAC sample period [ns] (10 GS/s) *)

    (* DRAG Pulse Variables *)
    fSigma                  : LREAL;
    fGaussianEnv            : LREAL;
    fDerivativeEnv          : LREAL;
    tNormal                 : LREAL;

    (* HEMT PID Controller *)
    fHEMT_Kp                : LREAL := 0.15;
    fHEMT_Ki                : LREAL := 0.05;
    fHEMT_Kd                : LREAL := 0.005;
    fHEMTIntegral           : LREAL := 0.0;
    fHEMTPrevError          : LREAL := 0.0;
    fActualHEMTCurrent      : LREAL; (* Sensed current feedback *)

    (* Internal State *)
    bPulseActive            : BOOL := FALSE;
    bFluxActive             : BOOL := FALSE;
    nGateCycles             : UDINT := 0;
    fError_PID              : LREAL;
    fDerivative_PID         : LREAL;
END_VAR

(* --- Main State Machine (PackML inspired) --- *)
CASE eState OF
    0: (* Stopped *)
        bReady := FALSE;
        fPulseI := 0.0;
        fPulseQ := 0.0;
        fFluxBiasVoltage := 0.0;
        fHEMTBiasVoltageOut := 0.0;
        bPulseActive := FALSE;

        IF bEnable THEN
            eState := 1; (* Starting *)
        END_IF

    1: (* Starting *)
        (* Initialize HEMT biasing carefully to avoid thermal shock at 4K *)
        fHEMTBiasVoltageOut := fHEMTBiasVoltageOut + 0.001; (* Ramp up slowly *)

        IF fHEMTBiasVoltageOut >= fHEMTOptimalVoltage THEN
            fHEMTBiasVoltageOut := fHEMTOptimalVoltage;
            bReady := TRUE;
            eState := 2; (* Execute *)
        END_IF

    2: (* Execute *)
        IF NOT bEnable THEN
            eState := 3; (* Stopping *)
        END_IF

        (* 1. Closed-loop HEMT Amplifier Biasing *)
        (* Simulate sensed current for demonstration *)
        fActualHEMTCurrent := fHEMTOptimalCurrent * 0.995; 

        (* PID Loop for HEMT Bias *)
        fError_PID := fHEMTOptimalCurrent - fActualHEMTCurrent;
        fHEMTIntegral := fHEMTIntegral + (fError_PID * dtSampleTime);
        fDerivative_PID := (fError_PID - fHEMTPrevError) / dtSampleTime;

        fHEMTBiasVoltageOut := (fHEMT_Kp * fError_PID) + (fHEMT_Ki * fHEMTIntegral) + (fHEMT_Kd * fDerivative_PID) + fHEMTOptimalVoltage;
        fHEMTPrevError := fError_PID;

        (* 2. Microwave Pulse Shaping: DRAG (Derivative Removal by Adiabatic Gate) *)
        IF bTriggerXGate AND NOT bPulseActive THEN
            bPulseActive := TRUE;
            fClockTimer := 0.0;
        END_IF

        IF bPulseActive THEN
            (* Gaussian Pulse with DRAG for leakage suppression *)
            fSigma := fPiPulseDuration / 4.0; 
            tNormal := fClockTimer - (fPiPulseDuration / 2.0);

            (* Base Gaussian Envelope *)
            fGaussianEnv := EXP(-0.5 * EXPT(tNormal / fSigma, 2));

            (* Derivative for Q-channel to counteract AC-Stark shift and $|2\rangle$ leakage *)
            fDerivativeEnv := - (tNormal / EXPT(fSigma, 2)) * fGaussianEnv;

            (* I and Q outputs for arbitrary waveform generator (AWG) *)
            fPulseI := fGaussianEnv;

            IF fDetuningDelta <> 0.0 THEN
                fPulseQ := -1.0 * fDRAGAlpha * fDerivativeEnv / fDetuningDelta;
            ELSE
                fPulseQ := 0.0;
            END_IF;

            fClockTimer := fClockTimer + dtSampleTime;

            IF fClockTimer > fPiPulseDuration THEN
                bPulseActive := FALSE;
                fPulseI := 0.0;
                fPulseQ := 0.0;
                nGateCycles := nGateCycles + 1;
            END_IF
        END_IF

        (* 3. Fast Z-Gate Flux Bias Modulation *)
        IF bTriggerZGate THEN
            (* Fast adiabatic flux pulse to sweep into CZ interaction frame *)
            (* Voltage calculation based on mutual inductance and SQUID loop Phi0 periodicity *)
            fFluxBiasVoltage := fZGateDetuning * 0.0152; (* Transfer function assumed 15.2 mV / MHz *)
        ELSE
            fFluxBiasVoltage := 0.0;
        END_IF

    3: (* Stopping *)
        (* Safely ramp down HEMT bias *)
        fHEMTBiasVoltageOut := fHEMTBiasVoltageOut - 0.01;
        IF fHEMTBiasVoltageOut <= 0.0 THEN
            fHEMTBiasVoltageOut := 0.0;
            eState := 0; (* Stopped *)
        END_IF

    4: (* Aborted *)
        (* Immediate shut down due to error or emergency *)
        fPulseI := 0.0;
        fPulseQ := 0.0;
        fFluxBiasVoltage := 0.0;
        fHEMTBiasVoltageOut := 0.0;
        bReady := FALSE;

END_CASE;
END_FUNCTION_BLOCK
