FUNCTION_BLOCK FB_HydroponicControl
VAR_INPUT
    bEnable : BOOL; (* System Enable *)
    rTempAir : REAL; (* Air Temperature in C *)
    rRH : REAL; (* Relative Humidity % *)
    rWaterLevel : REAL; (* Nutrient tank water level cm *)
    rEC_Sensor : REAL; (* Electrical Conductivity mS/cm *)
    rPH_Sensor : REAL; (* pH sensor reading *)
    rLightLevel : REAL; (* Current PPFD reading umol/m2/s *)
    rTargetVPD : REAL := 1.0; (* Target Vapor Pressure Deficit in kPa *)
    rTargetEC : REAL := 1.8; (* Target EC *)
    rTargetPH : REAL := 5.8; (* Target pH *)
    rTargetPPFD : REAL := 400.0; (* Target PPFD *)
END_VAR
VAR_OUTPUT
    bPumpMain : BOOL; (* Main irrigation pump *)
    rValveNutrientA : REAL; (* 0-100% dosing valve for Nutrient A *)
    rValveNutrientB : REAL; (* 0-100% dosing valve for Nutrient B *)
    rValveAcid : REAL; (* 0-100% dosing valve for pH down *)
    rValveBase : REAL; (* 0-100% dosing valve for pH up *)
    rFanSpeed : REAL; (* 0-100% Exhaust fan speed *)
    rHumidifier : REAL; (* 0-100% Humidifier output *)
    rLEDIntensity : REAL; (* 0-100% LED dimming signal *)
    bAlarm : BOOL;
    iErrorCode : INT;
END_VAR
VAR
    rSatVaporPress : REAL;
    rActualVaporPress : REAL;
    rCurrentVPD : REAL;
    rVpdError : REAL;
    rEcError : REAL;
    rPhError : REAL;
    rLightError : REAL;
    fbTimer : TON;
END_VAR

(* Calculate Vapor Pressure Deficit (VPD) *)
(* Saturation Vapor Pressure (SVP) in kPa approx formula: 0.6108 * exp(17.27 * T / (T + 237.3)) *)
rSatVaporPress := 0.6108 * EXP((17.27 * rTempAir) / (rTempAir + 237.3));
rActualVaporPress := rSatVaporPress * (rRH / 100.0);
rCurrentVPD := rSatVaporPress - rActualVaporPress;

rVpdError := rTargetVPD - rCurrentVPD;

IF bEnable THEN
    (* VPD Regulation *)
    IF rVpdError > 0.2 THEN
        rHumidifier := 50.0 + (rVpdError * 20.0);
        rFanSpeed := 30.0;
    ELSIF rVpdError < -0.2 THEN
        rHumidifier := 0.0;
        rFanSpeed := 50.0 + (ABS(rVpdError) * 30.0);
    ELSE
        rHumidifier := 10.0;
        rFanSpeed := 20.0;
    END_IF;

    (* Bound fan and humidifier *)
    IF rHumidifier > 100.0 THEN rHumidifier := 100.0; END_IF;
    IF rHumidifier < 0.0 THEN rHumidifier := 0.0; END_IF;
    IF rFanSpeed > 100.0 THEN rFanSpeed := 100.0; END_IF;
    IF rFanSpeed < 0.0 THEN rFanSpeed := 0.0; END_IF;

    (* EC and pH Dosing Cascades *)
    rEcError := rTargetEC - rEC_Sensor;
    IF rEcError > 0.1 AND rWaterLevel > 20.0 THEN
        rValveNutrientA := 10.0 + (rEcError * 50.0);
        rValveNutrientB := 10.0 + (rEcError * 50.0);
    ELSE
        rValveNutrientA := 0.0;
        rValveNutrientB := 0.0;
    END_IF;

    rPhError := rTargetPH - rPH_Sensor;
    IF rPhError < -0.2 THEN
        rValveAcid := 5.0 + (ABS(rPhError) * 20.0);
        rValveBase := 0.0;
    ELSIF rPhError > 0.2 THEN
        rValveBase := 5.0 + (rPhError * 20.0);
        rValveAcid := 0.0;
    ELSE
        rValveAcid := 0.0;
        rValveBase := 0.0;
    END_IF;

    (* Light Level PPFD Ramping *)
    rLightError := rTargetPPFD - rLightLevel;
    IF rLightError > 10.0 THEN
        rLEDIntensity := rLEDIntensity + 0.5;
    ELSIF rLightError < -10.0 THEN
        rLEDIntensity := rLEDIntensity - 0.5;
    END_IF;

    IF rLEDIntensity > 100.0 THEN rLEDIntensity := 100.0; END_IF;
    IF rLEDIntensity < 0.0 THEN rLEDIntensity := 0.0; END_IF;

    (* Safety / Water level *)
    IF rWaterLevel < 10.0 THEN
        bPumpMain := FALSE;
        bAlarm := TRUE;
        iErrorCode := 1; (* Low water *)
    ELSE
        bPumpMain := TRUE;
        bAlarm := FALSE;
        iErrorCode := 0;
    END_IF;
ELSE
    bPumpMain := FALSE;
    rValveNutrientA := 0.0;
    rValveNutrientB := 0.0;
    rValveAcid := 0.0;
    rValveBase := 0.0;
    rFanSpeed := 0.0;
    rHumidifier := 0.0;
    rLEDIntensity := 0.0;
    bAlarm := FALSE;
    iErrorCode := 0;
END_IF;
END_FUNCTION_BLOCK
```

