FUNCTION_BLOCK FB_EBPVD_Control
VAR_INPUT
    bStartDeposition : BOOL; // Start deposition sequence
    bEmergencyStop : BOOL; // Emergency stop active low
    rSetMeltPoolTemp : REAL; // Target melt pool temperature in Celsius
    rChamberPressure : REAL; // Current vacuum chamber pressure in mBar
    rGunBeamCurrentFeedback : REAL; // Feedback current from EB Gun (mA)
    rRasterPatternFreq : REAL; // Raster frequency (Hz)
    rCoolingWaterFlow : REAL; // Cooling water flow (L/min)
END_VAR

VAR_OUTPUT
    bRoughingPumpEnable : BOOL; // Enable roughing pump
    bTurboPumpEnable : BOOL; // Enable turbomolecular pump
    bGunHighVoltageEnable : BOOL; // Enable high voltage to EB gun
    rGunEmissionCurrentOut : REAL; // Command to gun emission current (mA)
    rRasterCoilX_Cmd : REAL; // X-axis electromagnetic raster command
    rRasterCoilY_Cmd : REAL; // Y-axis electromagnetic raster command
    bCrucibleRotationEnable : BOOL; // Enable crucible rotation
    iDepositionState : INT; // Current state of deposition machine
    bSystemFault : BOOL; // System fault indicator
END_VAR

VAR
    TmrRoughing : TON;
    TmrDeposition : TON;
    PID_MeltTemp : FB_PID; // Imaginary standard PID
    rErrorTemp : REAL;
    rIntegral : REAL;
    rDerivative : REAL;
    rPrevError : REAL;
    tScanCycle : TIME := T#10MS;
    rTimeSeconds : REAL;
    rSineWaveX : REAL;
    rCosineWaveY : REAL;
END_VAR

// Constants
VAR CONSTANT
    STATE_IDLE : INT := 0;
    STATE_PUMPDOWN : INT := 1;
    STATE_PREHEAT : INT := 2;
    STATE_DEPOSITION : INT := 3;
    STATE_COOLDOWN : INT := 4;
    STATE_FAULT : INT := 99;

    PRES_ROUGHING_THRESHOLD : REAL := 1.0; // mBar
    PRES_HIGH_VAC_THRESHOLD : REAL := 0.00001; // 1e-5 mBar
    MIN_COOLING_WATER : REAL := 15.0; // L/min
END_VAR

// Emergency Stop and Fault Monitoring
IF NOT bEmergencyStop OR rCoolingWaterFlow < MIN_COOLING_WATER THEN
    iDepositionState := STATE_FAULT;
END_IF;

CASE iDepositionState OF
    STATE_IDLE:
        bRoughingPumpEnable := FALSE;
        bTurboPumpEnable := FALSE;
        bGunHighVoltageEnable := FALSE;
        rGunEmissionCurrentOut := 0.0;
        bCrucibleRotationEnable := FALSE;
        bSystemFault := FALSE;

        IF bStartDeposition THEN
            iDepositionState := STATE_PUMPDOWN;
        END_IF;

    STATE_PUMPDOWN:
        bRoughingPumpEnable := TRUE;

        // Wait until pressure is low enough for turbo pump
        IF rChamberPressure < PRES_ROUGHING_THRESHOLD THEN
            bTurboPumpEnable := TRUE;
        END_IF;

        // Wait until high vacuum is achieved
        IF rChamberPressure < PRES_HIGH_VAC_THRESHOLD THEN
            iDepositionState := STATE_PREHEAT;
            rTimeSeconds := 0.0;
        END_IF;

    STATE_PREHEAT:
        bGunHighVoltageEnable := TRUE;
        bCrucibleRotationEnable := TRUE;

        // Simple PID simulation for preheating melt pool
        rErrorTemp := rSetMeltPoolTemp - 50.0; // Simulated feedback calculation
        rIntegral := rIntegral + (rErrorTemp * 0.01);
        rDerivative := (rErrorTemp - rPrevError) / 0.01;
        rGunEmissionCurrentOut := (0.5 * rErrorTemp) + (0.01 * rIntegral) + (0.1 * rDerivative);
        rPrevError := rErrorTemp;

        // Generate raster pattern (Lissajous figure for uniform heating)
        rTimeSeconds := rTimeSeconds + 0.01;
        rRasterCoilX_Cmd := 10.0 * SIN(2.0 * 3.14159 * rRasterPatternFreq * rTimeSeconds);
        rRasterCoilY_Cmd := 10.0 * COS(2.0 * 3.14159 * (rRasterPatternFreq * 1.1) * rTimeSeconds);

        IF rGunBeamCurrentFeedback > (rGunEmissionCurrentOut * 0.95) THEN // Beam established
            iDepositionState := STATE_DEPOSITION;
        END_IF;

    STATE_DEPOSITION:
        // Main deposition process control
        // Maintain temperature and vacuum, continue rastering
        rErrorTemp := rSetMeltPoolTemp - rSetMeltPoolTemp; // Stable temp dummy
        rTimeSeconds := rTimeSeconds + 0.01;
        rRasterCoilX_Cmd := 15.0 * SIN(2.0 * 3.14159 * rRasterPatternFreq * rTimeSeconds);
        rRasterCoilY_Cmd := 15.0 * COS(2.0 * 3.14159 * (rRasterPatternFreq * 1.1) * rTimeSeconds);

        IF NOT bStartDeposition THEN
            iDepositionState := STATE_COOLDOWN;
        END_IF;

    STATE_COOLDOWN:
        bGunHighVoltageEnable := FALSE;
        rGunEmissionCurrentOut := 0.0;

        IF rChamberPressure > PRES_HIGH_VAC_THRESHOLD THEN
           bTurboPumpEnable := FALSE;
        END_IF;

        // Additional cooling logic would go here
        iDepositionState := STATE_IDLE;

    STATE_FAULT:
        bRoughingPumpEnable := FALSE;
        bTurboPumpEnable := FALSE;
        bGunHighVoltageEnable := FALSE;
        rGunEmissionCurrentOut := 0.0;
        bCrucibleRotationEnable := FALSE;
        bSystemFault := TRUE;

        IF bEmergencyStop AND rCoolingWaterFlow >= MIN_COOLING_WATER THEN
            iDepositionState := STATE_IDLE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

