FUNCTION_BLOCK FB_TitaniumEBAM_Control
VAR_INPUT
    (* Required physical inputs with types and comments *)
    bEnableSys              : BOOL;     (* Main system enable for EBAM process *)
    bVacuumInterlockOK      : BOOL;     (* Chamber vacuum level is within acceptable threshold (< 10^-5 Torr) *)
    rChamberPressure        : REAL;     (* Current vacuum chamber pressure in Torr *)
    rTargetBeamPower        : REAL;     (* Desired electron beam power setpoint in kW *)
    rWireFeedRate           : REAL;     (* Actual titanium wire feed rate in mm/s *)
    rBeamFocusCurrent       : REAL;     (* Focus coil current feedback in mA *)
    bBackscatterDefectDet   : BOOL;     (* In-situ backscattered electron sensor - TRUE if defect detected *)
    bEStop                  : BOOL;     (* Emergency stop circuit OK *)
END_VAR
VAR_OUTPUT
    (* Required physical outputs with types and comments *)
    bSystemReady            : BOOL;     (* EBAM system is ready for melt pool generation *)
    rBeamPowerCmd           : REAL;     (* Output command to high voltage beam power supply in kW *)
    rWireFeedCmd            : REAL;     (* Output command to wire feeder servo in mm/s *)
    bVacuumPumpEngage       : BOOL;     (* Command to engage turbomolecular vacuum pump *)
    bDefectAlarm            : BOOL;     (* Alarm indicating backscatter defect exceeds threshold *)
    bProcessFault           : BOOL;     (* General fault indicator for process deviations *)
END_VAR
VAR
    (* Internal state variables *)
    iProcessState           : INT := 0; (* Process state machine index *)
    tOutgassingTimer        : TON;      (* Timer for vacuum outgassing stabilization *)
    tDefectFilterTimer      : TON;      (* Timer to filter transient defect signals *)
    rSpecificEnergy         : REAL;     (* Calculated specific energy input (kJ/mm) *)
    rEnergyDeviation        : REAL;     (* Deviation from nominal specific energy *)
    rNominalEnergy          : REAL := 12.5; (* Target specific energy for aviation grade Ti-6Al-4V *)
    rKp_WireFeed            : REAL := 0.25; (* Proportional gain for wire feed PID *)
    rKi_WireFeed            : REAL := 0.05; (* Integral gain for wire feed PID *)
    rIntegralError          : REAL := 0.0;  (* Integral error accumulator for wire feed *)
END_VAR

(* === MAIN LOGIC === *)
(* Handle critical safety interlocks first *)
IF NOT bEStop THEN
    bSystemReady := FALSE;
    bProcessFault := TRUE;
    rBeamPowerCmd := 0.0;
    rWireFeedCmd := 0.0;
    iProcessState := 999; (* Fault state *)
    RETURN;
END_IF;

(* Continuous Specific Energy Calculation *)
(* Ensure no division by zero on wire feed rate *)
IF rWireFeedRate > 0.001 THEN
    rSpecificEnergy := rTargetBeamPower / rWireFeedRate;
ELSE
    rSpecificEnergy := 0.0;
END_IF;

(* Filter backscattered electron defect detection *)
tDefectFilterTimer(IN := bBackscatterDefectDet, PT := T#50MS);
IF tDefectFilterTimer.Q THEN
    bDefectAlarm := TRUE;
ELSE
    bDefectAlarm := FALSE;
END_IF;

(* State Machine for EBAM Control *)
CASE iProcessState OF
    0: (* IDLE - Wait for System Enable and Vacuum check *)
        bSystemReady := FALSE;
        rBeamPowerCmd := 0.0;
        rWireFeedCmd := 0.0;
        bVacuumPumpEngage := TRUE; (* Always maintain vacuum *)
        bProcessFault := FALSE;

        IF bEnableSys AND bVacuumInterlockOK THEN
            (* Move to vacuum stabilization outgassing check *)
            iProcessState := 10;
        END_IF;

    10: (* OUTGASSING STABILIZATION *)
        (* Ensure pressure stays below 1.0e-5 Torr for a sustained period *)
        IF rChamberPressure < 0.00001 THEN
            tOutgassingTimer(IN := TRUE, PT := T#10S);
        ELSE
            tOutgassingTimer(IN := FALSE, PT := T#10S);
        END_IF;

        IF tOutgassingTimer.Q THEN
            tOutgassingTimer(IN := FALSE);
            iProcessState := 20;
        END_IF;

        IF NOT bVacuumInterlockOK THEN
            iProcessState := 0; (* Fall back to idle if vacuum lost *)
        END_IF;

    20: (* READY TO DEPOSIT *)
        bSystemReady := TRUE;

        IF bEnableSys AND NOT bDefectAlarm THEN
            iProcessState := 30; (* Start process *)
        END_IF;

    30: (* ACTIVE MELT POOL CONTROL *)
        bSystemReady := TRUE;

        (* Apply beam power command *)
        rBeamPowerCmd := rTargetBeamPower;

        (* Wire feed PID control based on specific energy regulation *)
        rEnergyDeviation := rNominalEnergy - rSpecificEnergy;
        rIntegralError := rIntegralError + (rEnergyDeviation * 0.1); (* Assuming 100ms task cycle *)

        (* Anti-windup for integral term *)
        IF rIntegralError > 5.0 THEN
            rIntegralError := 5.0;
        ELSIF rIntegralError < -5.0 THEN
            rIntegralError := -5.0;
        END_IF;

        (* Calculate wire feed command with PI loop *)
        rWireFeedCmd := rWireFeedRate + (rKp_WireFeed * rEnergyDeviation) + (rKi_WireFeed * rIntegralError);

        (* Monitor for fault conditions during active deposit *)
        IF NOT bVacuumInterlockOK OR bDefectAlarm OR rChamberPressure > 0.00005 THEN
            iProcessState := 999; (* Abort to fault state *)
        END_IF;

        IF NOT bEnableSys THEN
            iProcessState := 40; (* Normal cooldown *)
        END_IF;

    40: (* COOLDOWN AND BEAM RAMP DOWN *)
        rBeamPowerCmd := 0.0;
        rWireFeedCmd := 0.0;
        bSystemReady := FALSE;

        (* Simplistic transition to idle, could involve thermal monitoring in reality *)
        iProcessState := 0;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bProcessFault := TRUE;
        rBeamPowerCmd := 0.0;
        rWireFeedCmd := 0.0;

        (* Acknowledge fault to clear *)
        IF NOT bEnableSys AND bVacuumInterlockOK AND NOT bDefectAlarm THEN
            iProcessState := 0;
            bProcessFault := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
