    Vision_Target_Y : Real;
    Vision_Target_R : Real;
    Vision_Ready : Bool;
    Vacuum_Pressure : Real;
    Vacuum_Threshold : Real;
    Feeder_Ready : Bool;
    Feeder_Sync_Pulse : Bool;
END_VAR

VAR_OUTPUT
    Move_Axis_X : Real;
    Move_Axis_Y : Real;
    Move_Axis_Z : Real;
    Move_Axis_R : Real;
    Vacuum_Enable : Bool;
    Feeder_Advance : Bool;
    Machine_State : Int;
    Error_Code : Int;
END_VAR

VAR
    State : Int := 0;
    Component_Present : Bool;
END_VAR

BEGIN
    CASE State OF
        0: // Idle
            Vacuum_Enable := FALSE;
            Feeder_Advance := FALSE;
            IF Start_Sequence AND Feeder_Ready THEN
                State := 1;
            END_IF;
        1: // Sync Feeder
            IF Feeder_Sync_Pulse THEN
                Move_Axis_X := 10.0;
                Move_Axis_Y := 20.0;
                State := 2;
            END_IF;
        2: // Pick
            Move_Axis_Z := 5.0;
            Vacuum_Enable := TRUE;
            IF Vacuum_Pressure <= Vacuum_Threshold THEN
                Component_Present := TRUE;
                Move_Axis_Z := 0.0;
                State := 3;
            ELSIF Vacuum_Pressure > 0.0 AND NOT Vacuum_Enable THEN
                Error_Code := 1;
            END_IF;
        3: // Vision Target
            IF Component_Present AND Vision_Ready THEN
                Move_Axis_X := Vision_Target_X;
                Move_Axis_Y := Vision_Target_Y;
                Move_Axis_R := Vision_Target_R;
                State := 4;
            END_IF;
        4: // Place
            Move_Axis_Z := 5.0;
            Vacuum_Enable := FALSE;
            IF Vacuum_Pressure > (Vacuum_Threshold + 0.2) THEN
                Move_Axis_Z := 0.0;
                State := 0;
            END_IF;
        5: // Error state
            Vacuum_Enable := FALSE;
            Machine_State := 5;
    END_CASE;

    Machine_State := State;
END_FUNCTION_BLOCK
