FUNCTION_BLOCK FB_BreadSlicerBagger
TITLE = 'Bakery Bread Slicer and Bagger Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    bSystemEnable : BOOL; // Main system run enable
    bEmergencyStop : BOOL; // E-Stop NC contact (FALSE = stopped)
    bOpticalLoafDetect : BOOL; // Optical sensor for incoming loaf
    bBagMagazineLow : BOOL; // Sensor for bag magazine level
    rConveyorSpeedRef : REAL; // Reference speed for infeed conveyor [mm/s]
    rTargetSliceThickness : REAL; // Target thickness [mm]
    iRequestedLoafCount : INT; // Production run target
    bAirSupplyOK : BOOL; // Pneumatic system pressure switch
END_VAR

VAR_OUTPUT
    bInfeedConveyorRun : BOOL; // Command to start infeed conveyor
    rInfeedConveyorSpeedCmd : REAL; // Speed command to infeed VFD
    bBladeMotorRun : BOOL; // Command to run slicing blades
    rBladePitchSpeedCmd : REAL; // Blade speed synchronization
    bAirJetBagOpen : BOOL; // Solenoid valve for air-jet bag opener
    bPusherExtend : BOOL; // Pneumatic cylinder to push sliced loaf into bag
    bBagSealerActivate : BOOL; // Activate heat sealer
    bSystemFault : BOOL; // General fault indicator
    iCurrentLoafCount : INT; // Number of loaves bagged
    sMachineStatus : STRING[32]; // Current state description
END_VAR

VAR
    iState : INT := 0; // State machine step
    tLoafDetectTimer : TON; // Timer for loaf present stability
    tAirJetTimer : TON; // Duration for air-jet blast
    tPusherTimer : TON; // Pusher extend duration
    tSealerTimer : TON; // Heat sealing duration
    bProcessingLoaf : BOOL := FALSE;
    rActualPitchSpeed : REAL := 0.0;
END_VAR

VAR_CONSTANT
    STATE_IDLE : INT := 0;
    STATE_START_CONVEYOR : INT := 10;
    STATE_WAIT_LOAF : INT := 20;
    STATE_SYNC_BLADES : INT := 30;
    STATE_SLICE_LOAF : INT := 40;
    STATE_OPEN_BAG : INT := 50;
    STATE_PUSH_LOAF : INT := 60;
    STATE_SEAL_BAG : INT := 70;
    STATE_FAULT : INT := 999;
END_VAR

// Control Logic Implementation
IF NOT bEmergencyStop OR NOT bAirSupplyOK THEN
    iState := STATE_FAULT;
END_IF;

CASE iState OF
    STATE_IDLE:
        bInfeedConveyorRun := FALSE;
        bBladeMotorRun := FALSE;
        bAirJetBagOpen := FALSE;
        bPusherExtend := FALSE;
        bBagSealerActivate := FALSE;
        sMachineStatus := 'Idle';

        IF bSystemEnable AND NOT bSystemFault AND (iCurrentLoafCount < iRequestedLoafCount) THEN
            iState := STATE_START_CONVEYOR;
        END_IF;

    STATE_START_CONVEYOR:
        bInfeedConveyorRun := TRUE;
        rInfeedConveyorSpeedCmd := rConveyorSpeedRef;
        sMachineStatus := 'Conveyor Running';
        iState := STATE_WAIT_LOAF;

    STATE_WAIT_LOAF:
        tLoafDetectTimer(IN := bOpticalLoafDetect, PT := T#200ms);
        IF tLoafDetectTimer.Q THEN
            bProcessingLoaf := TRUE;
            iState := STATE_SYNC_BLADES;
        END_IF;

    STATE_SYNC_BLADES:
        sMachineStatus := 'Syncing Blades';
        bBladeMotorRun := TRUE;
        // Calculate blade pitch speed based on conveyor speed and target thickness
        // rBladePitchSpeedCmd = F(ConveyorSpeed, TargetThickness)
        IF rTargetSliceThickness > 0.0 THEN
            rBladePitchSpeedCmd := (rConveyorSpeedRef / rTargetSliceThickness) * 60.0; // RPM approximation
        ELSE
            rBladePitchSpeedCmd := 0.0;
        END_IF;

        // Simulate synchronization delay
        iState := STATE_SLICE_LOAF;

    STATE_SLICE_LOAF:
        sMachineStatus := 'Slicing';
        // Assume slicing takes a fixed time or is monitored via encoder (simplified here)
        IF NOT bOpticalLoafDetect THEN
            // Loaf has passed sensor
            bBladeMotorRun := FALSE;
            iState := STATE_OPEN_BAG;
        END_IF;

    STATE_OPEN_BAG:
        sMachineStatus := 'Opening Bag';
        IF NOT bBagMagazineLow THEN
            bAirJetBagOpen := TRUE;
            tAirJetTimer(IN := TRUE, PT := T#500ms);
            IF tAirJetTimer.Q THEN
                tAirJetTimer(IN := FALSE);
                iState := STATE_PUSH_LOAF;
            END_IF;
        ELSE
            iState := STATE_FAULT;
            sMachineStatus := 'Fault: Bag Mag Low';
        END_IF;

    STATE_PUSH_LOAF:
        sMachineStatus := 'Pushing Loaf';
        bPusherExtend := TRUE;
        tPusherTimer(IN := TRUE, PT := T#1s);
        IF tPusherTimer.Q THEN
            bPusherExtend := FALSE;
            tPusherTimer(IN := FALSE);
            iState := STATE_SEAL_BAG;
        END_IF;

    STATE_SEAL_BAG:
        sMachineStatus := 'Sealing Bag';
        bAirJetBagOpen := FALSE;
        bBagSealerActivate := TRUE;
        tSealerTimer(IN := TRUE, PT := T#800ms);
        IF tSealerTimer.Q THEN
            bBagSealerActivate := FALSE;
            tSealerTimer(IN := FALSE);
            iCurrentLoafCount := iCurrentLoafCount + 1;
            bProcessingLoaf := FALSE;

            IF iCurrentLoafCount >= iRequestedLoafCount THEN
                iState := STATE_IDLE;
            ELSE
                iState := STATE_WAIT_LOAF;
            END_IF;
        END_IF;

    STATE_FAULT:
        bInfeedConveyorRun := FALSE;
        bBladeMotorRun := FALSE;
        bAirJetBagOpen := FALSE;
        bPusherExtend := FALSE;
        bBagSealerActivate := FALSE;
        bSystemFault := TRUE;
        IF sMachineStatus = 'Idle' THEN
           sMachineStatus := 'E-Stop or Air Fault';
        END_IF;

        IF bEmergencyStop AND bAirSupplyOK AND NOT bSystemEnable THEN
            bSystemFault := FALSE;
            iState := STATE_IDLE;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
