FUNCTION_BLOCK FB_TelescopeMountController

VAR_INPUT
    bEnable                 : BOOL;   // Master enable
    bEstop                  : BOOL;   // Emergency Stop (NC, TRUE = Safe)
    bReset                  : BOOL;   // Fault reset

    // Environmental & Target Data
    fTargetRA               : LREAL;  // Target Right Ascension (hours)
