```iec-st
(* ==============================================================================
   FB_Spaceplane_Reentry 
   ------------------------------------------------------------------------------
   AUTHOR: Principal Reentry Dynamics Engineer
   VERSION: 2.1.0 (Production / Flight Candidate)

   DESCRIPTION:
   Hypersonic Reentry Aerothermodynamics & Flight Surface / RCS Blending Controller.
   Designed for Sub-Orbital Spaceplane autonomous reentry sequence.

   CORE ALGORITHMS:
   1. Aerothermodynamic Heat Flux Estimation (Stagnation Point Convective Heating)
   2. Skip-Reentry Trajectory Control via AoA Modulation
   3. Authority Blending: Cold-gas RCS <-> Hydraulic Elevons/Body Flaps based on Dynamic Pressure (q-bar)
   4. PackML State Machine for Autonomous Sequence Control
   5. Quaternion to Euler kinematics integration hook
============================================================================== *)

FUNCTION_BLOCK FB_Spaceplane_Reentry
VAR_INPUT
    // Master Control & PackML States
    bEnable                 : BOOL;                 // System enable
    bExecute                : BOOL;                 // Initiate reentry sequence
    bAbort                  : BOOL;                 // Abort/Bailout sequence

    // Navigation & State Vector Inputs (LREAL for precision)
    fAltitude_m             : LREAL;                // Current altitude (meters)
    fVelocity_ms            : LREAL;                // Velocity relative to atmosphere (m/s)
    fPitch_rad              : LREAL;                // Current Pitch Angle
    fRoll_rad               : LREAL;                // Current Roll Angle
    fYaw_rad                : LREAL;                // Current Yaw Angle
    fPitchRate_rads         : LREAL;                // Pitch Rate (rad/s)

    // Sensor Inputs
    fLeadingEdgeTemp_C      : LREAL;                // Carbon-Carbon Leading Edge Temperature (Celsius)
    fNoseStagnationTemp_C   : LREAL;                // Nose Cone Temperature (Celsius)

    // Target Trajectory
    fTargetAoA_rad          : LREAL := 1.047197;    // Default 60 deg high-alpha target
END_VAR

VAR_OUTPUT
    // PackML State Outputs
    eCurrentState           : E_PackML_State;       // e.g. IDLE, STARTING, EXECUTE, HOLDING, ABORTED
    bActive                 : BOOL;
    bReentryComplete        : BOOL;
    bError                  : BOOL;
    nErrorID                : UDINT;

    // Control Actuation Outputs
    fElevonLeft_Cmd_rad     : LREAL;                // Left Elevon command (-0.5 to 0.5 rad)
    fElevonRight_Cmd_rad    : LREAL;                // Right Elevon command (-0.5 to 0.5 rad)
    fBodyFlap_Cmd_rad       : LREAL;                // Body Flap command for pitch trim

    // RCS (Reaction Control System) PWM Commands (0.0 to 1.0)
    fRCS_PitchUp_Cmd        : LREAL;
    fRCS_PitchDown_Cmd      : LREAL;
    fRCS_RollLeft_Cmd       : LREAL;
    fRCS_RollRight_Cmd      : LREAL;
    fRCS_YawLeft_Cmd        : LREAL;
    fRCS_YawRight_Cmd       : LREAL;

    // Telemetry & Diagnostics
    fDynamicPressure_Pa     : LREAL;                // q-bar
    fConvectiveHeatFlux     : LREAL;                // Estimated q_s
    fControlAuthorityBlend  : LREAL;                // 0.0 = 100% RCS, 1.0 = 100% Aero
END_VAR

VAR
    // Internal State
    eState                  : E_PackML_State := E_PackML_State.IDLE;

    // Atmosphere Model Constants (U.S. Standard Atmosphere 1976 Simplified)
    fDensity_kgm3           : LREAL;

    // PID Controllers for Aero Surfaces
    fbPitchPID              : FB_PID_LREAL;
    fbRollPID               : FB_PID_LREAL;

    // PID Controllers for RCS
    fbRCSPitchPID           : FB_PID_LREAL;

    // Thermal Limits
    MAX_LE_TEMP_C           : LREAL := 1650.0;      // 1650 C strict limit
    HEAT_FLUX_COEFF         : LREAL := 1.83E-4;     // Empirical Sutton-Graves coefficient (approx for Earth)

    // Blending Parameters
    Q_BAR_MIN_PA            : LREAL := 10.0;        // Min dynamic pressure to start aero blending
    Q_BAR_MAX_PA            : LREAL := 500.0;       // Dynamic pressure for full aero authority

    // Internal Control Signals
    fPitchError_rad         : LREAL;
    fPitchCmd_Total         : LREAL;
    fRollCmd_Total          : LREAL;
    fThermalAoA_Mod_rad     : LREAL;
END_VAR

(* ========================================================================= *
   IMPLEMENTATION
 * ========================================================================= *)

// ---------------------------------------------------------
// 1. PackML State Machine Handling
// ---------------------------------------------------------
CASE eState OF
    E_PackML_State.IDLE:
        bActive := FALSE;
        bReentryComplete := FALSE;
        IF bEnable AND bExecute THEN
            eState := E_PackML_State.STARTING;
        END_IF;

    E_PackML_State.STARTING:
        // Initialize PIDs and Filters
        fbPitchPID.Kp := 2.5;
        fbPitchPID.Ki := 0.1;
        fbPitchPID.Kd := 1.2;

        fbRCSPitchPID.Kp := 1.0;
        fbRCSPitchPID.Ki := 0.0;
        fbRCSPitchPID.Kd := 0.5;

        eState := E_PackML_State.EXECUTE;
        bActive := TRUE;

    E_PackML_State.EXECUTE:
        IF bAbort THEN
            eState := E_PackML_State.ABORTING;
        ELSIF fAltitude_m < 30000.0 AND fVelocity_ms < 1000.0 THEN
            // Reentry phase ends, TAEM (Terminal Area Energy Management) begins
            eState := E_PackML_State.COMPLETING;
        END_IF;

    E_PackML_State.COMPLETING:
        eState := E_PackML_State.COMPLETE;

    E_PackML_State.COMPLETE:
        bActive := FALSE;
        bReentryComplete := TRUE;
        IF NOT bExecute THEN
            eState := E_PackML_State.IDLE;
        END_IF;

    E_PackML_State.ABORTING:
        // Implement ballistic bailout or emergency RCS stabilization
        fRCS_PitchUp_Cmd := 1.0; // Hard pitch up to bleed energy aggressively
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        bError := TRUE;
        nErrorID := 9999;
        IF NOT bAbort AND NOT bExecute THEN
            eState := E_PackML_State.IDLE;
            bError := FALSE;
        END_IF;
END_CASE;

eCurrentState := eState;

// If not in EXECUTE state, bypass the main control loop
IF eState <> E_PackML_State.EXECUTE THEN
    RETURN;
END_IF;

// ---------------------------------------------------------
// 2. Atmospheric & Aerothermodynamic Model
// ---------------------------------------------------------
// Extremely simplified exponential atmosphere density model for upper mesosphere/stratosphere
// rho = rho0 * exp(-h/H)
fDensity_kgm3 := 1.225 * EXP(-fAltitude_m / 7200.0);

// Dynamic Pressure (q-bar = 0.5 * rho * v^2)
fDynamicPressure_Pa := 0.5 * fDensity_kgm3 * fVelocity_ms * fVelocity_ms;

// Stagnation Point Convective Heating Rate Estimation (Sutton-Graves)
// q_s = k * sqrt(rho / R_nose) * v^3 
// (assuming R_nose is lumped into HEAT_FLUX_COEFF)
fConvectiveHeatFlux := HEAT_FLUX_COEFF * SQRT(fDensity_kgm3) * EXPT(fVelocity_ms, 3.0);

// Thermal Protection System (TPS) Active Management
// If Leading Edge Temp is approaching 1650C, we must shallow the flight path by reducing AoA
IF fLeadingEdgeTemp_C > (MAX_LE_TEMP_C - 100.0) THEN
    // Proportional reduction in AoA based on thermal margin
    fThermalAoA_Mod_rad := (fLeadingEdgeTemp_C - (MAX_LE_TEMP_C - 100.0)) * 0.005;
    // Limit modification to prevent loss of control
    IF fThermalAoA_Mod_rad > 0.261799 THEN // max 15 deg reduction
        fThermalAoA_Mod_rad := 0.261799;
    END_IF;
ELSE
    fThermalAoA_Mod_rad := 0.0;
END_IF;

// ---------------------------------------------------------
// 3. Control Authority Blending (RCS vs Aero)
// ---------------------------------------------------------
// Calculate blending factor (0.0 = Pure RCS, 1.0 = Pure Aero Surfaces)
IF fDynamicPressure_Pa <= Q_BAR_MIN_PA THEN
    fControlAuthorityBlend := 0.0;
ELSIF fDynamicPressure_Pa >= Q_BAR_MAX_PA THEN
    fControlAuthorityBlend := 1.0;
ELSE
    // Linear blending between Q_BAR_MIN_PA and Q_BAR_MAX_PA
    fControlAuthorityBlend := (fDynamicPressure_Pa - Q_BAR_MIN_PA) / (Q_BAR_MAX_PA - Q_BAR_MIN_PA);
END_IF;

// ---------------------------------------------------------
// 4. Flight Control & Trajectory Tracking
// ---------------------------------------------------------
// Pitch Error based on nominal AoA minus thermal modulation
fPitchError_rad := (fTargetAoA_rad - fThermalAoA_Mod_rad) - fPitch_rad;

// Evaluate PID for Aerodynamic Pitch Control
fbPitchPID(
    fSetpoint := (fTargetAoA_rad - fThermalAoA_Mod_rad),
    fActualValue := fPitch_rad,
    fDerivative := fPitchRate_rads,
    fOutput => fPitchCmd_Total
);

// Evaluate PID for RCS Pitch Control (tuned differently for discrete thrusters)
fbRCSPitchPID(
    fSetpoint := (fTargetAoA_rad - fThermalAoA_Mod_rad),
    fActualValue := fPitch_rad,
    fDerivative := fPitchRate_rads,
    fOutput => fPitchCmd_Total
);

// Distribute Commands based on Control Authority Blend
// --- Aerodynamic Surfaces ---
fBodyFlap_Cmd_rad := LIMIT(-0.5, fPitchCmd_Total * fControlAuthorityBlend, 0.5);
fElevonLeft_Cmd_rad := LIMIT(-0.3, fPitchCmd_Total * fControlAuthorityBlend * 0.5, 0.3);
fElevonRight_Cmd_rad := LIMIT(-0.3, fPitchCmd_Total * fControlAuthorityBlend * 0.5, 0.3);

// --- RCS Thrusters ---
VAR
    fRCS_Pitch_Demand : LREAL;
END_VAR

// Calculate RCS Demand
fRCS_Pitch_Demand := fbRCSPitchPID.fOutput * (1.0 - fControlAuthorityBlend);

// Map demand to PWM commands for discrete cold-gas thrusters
IF fRCS_Pitch_Demand > 0.0 THEN
    fRCS_PitchUp_Cmd := LIMIT(0.0, fRCS_Pitch_Demand, 1.0);
    fRCS_PitchDown_Cmd := 0.0;
ELSE
    fRCS_PitchUp_Cmd := 0.0;
    fRCS_PitchDown_Cmd := LIMIT(0.0, ABS(fRCS_Pitch_Demand), 1.0);
END_IF;

// Maintain zero roll and yaw during skip reentry (simplified)
fRCS_RollLeft_Cmd := 0.0;
fRCS_RollRight_Cmd := 0.0;
fRCS_YawLeft_Cmd := 0.0;
fRCS_YawRight_Cmd := 0.0;

END_FUNCTION_BLOCK
```

