FUNCTION_BLOCK FB_ImmersionCooling_Optimizer
VAR_INPUT
    rSysPressure        : REAL; // Boiler tank pressure (kPa)
    rFluidTemp          : REAL; // Dielectric fluid temp (C)
    rServerLoad         : REAL; // Aggregate thermal load from HFT servers (MW)
    bSystemEnable       : BOOL; // Master enable
    rVaporCoilTemp      : REAL; // Condensation coil surface temp (C)
    rPrimaryCoolantFlow : REAL; // Cooling tower water flow rate (L/s)
END_VAR
VAR_OUTPUT
    rPumpSpeedCmd       : REAL; // 0-100% dielectric fluid pump speed
    rValvePosCmd        : REAL; // 0-100% primary coolant valve position
    bPressureAlarm      : BOOL; // High pressure alarm
    bFluidTempAlarm     : BOOL; // Fluid overtemp alarm
    bCondensationWarning: BOOL; // Warning if coil temp too high
END_VAR
VAR
    rTargetPressure     : REAL;
    rTargetFlow         : REAL;
    rErrorP             : REAL;
    rIntegralP          : REAL;
    rDerivativeP        : REAL;
    rLastErrorP         : REAL;
    rKp_P               : REAL := 2.5;
    rKi_P               : REAL := 0.1;
    rKd_P               : REAL := 0.5;

    rErrorT             : REAL;
    rIntegralT          : REAL;
    rDerivativeT        : REAL;
    rLastErrorT         : REAL;
    rKp_T               : REAL := 3.0;
    rKi_T               : REAL := 0.15;
    rKd_T               : REAL := 0.8;

    dtCycleTime         : REAL := 0.01; // 10ms cycle
    rMaxPressure        : REAL := 150.0; // kPa
    rBoilingPoint       : REAL := 50.0; // C
END_VAR

// Two-Phase Immersion Cooling Control Logic
// Dynamic adjustment based on HFT Server Load

IF NOT bSystemEnable THEN
    rPumpSpeedCmd := 0.0;
    rValvePosCmd := 0.0;
    bPressureAlarm := FALSE;
    bFluidTempAlarm := FALSE;
    bCondensationWarning := FALSE;
    RETURN;
END_IF;

// Feed-forward target calculations based on thermal load
rTargetPressure := 101.325 + (rServerLoad * 1.5); 
IF rTargetPressure > rMaxPressure THEN
    rTargetPressure := rMaxPressure - 5.0; // Keep a safety margin
END_IF;

// Pressure PID (Controls condensation loop valve)
rErrorP := rTargetPressure - rSysPressure;
rIntegralP := rIntegralP + (rErrorP * dtCycleTime);
// Anti-windup
IF rIntegralP > 100.0 THEN rIntegralP := 100.0; ELSIF rIntegralP < -100.0 THEN rIntegralP := -100.0; END_IF;
rDerivativeP := (rErrorP - rLastErrorP) / dtCycleTime;
rLastErrorP := rErrorP;

rValvePosCmd := (rKp_P * rErrorP) + (rKi_P * rIntegralP) + (rKd_P * rDerivativeP);
// Valve position saturation
IF rValvePosCmd > 100.0 THEN rValvePosCmd := 100.0; ELSIF rValvePosCmd < 0.0 THEN rValvePosCmd := 0.0; END_IF;

// Fluid Temperature PID (Controls dielectric fluid distribution pump)
rErrorT := rFluidTemp - (rBoilingPoint - 2.0); // Target subcooled by 2C
rIntegralT := rIntegralT + (rErrorT * dtCycleTime);
// Anti-windup
IF rIntegralT > 100.0 THEN rIntegralT := 100.0; ELSIF rIntegralT < -100.0 THEN rIntegralT := -100.0; END_IF;
rDerivativeT := (rErrorT - rLastErrorT) / dtCycleTime;
rLastErrorT := rErrorT;

rPumpSpeedCmd := 50.0 + (rServerLoad * 2.0) + (rKp_T * rErrorT) + (rKi_T * rIntegralT) + (rKd_T * rDerivativeT); // Base + feed-forward + PID
IF rPumpSpeedCmd > 100.0 THEN rPumpSpeedCmd := 100.0; ELSIF rPumpSpeedCmd < 20.0 THEN rPumpSpeedCmd := 20.0; END_IF;

// Diagnostics and Alarms
bPressureAlarm := (rSysPressure > rMaxPressure);
bFluidTempAlarm := (rFluidTemp > (rBoilingPoint + 5.0));
bCondensationWarning := (rVaporCoilTemp > (rBoilingPoint - 15.0));

END_FUNCTION_BLOCK
