Here is the SCL program with added depth. It includes dynamic thermal derating to protect the IGBTs by scaling down the PWM duty cycle when the temperature exceeds limits.

FUNCTION_BLOCK "Solar_Inverter_Depth"
VAR_INPUT
    PV_Voltage : REAL;
    PV_Current : REAL;
    Grid_Voltage : REAL;
    Grid_Freq : REAL;
    IGBT_Temp : REAL;
    Ambient_Temp : REAL;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : REAL;
    Sync_OK : BOOL;
    Power_Limit : REAL;
END_VAR
VAR
    Prev_Power : REAL;
    Prev_Voltage : REAL;
    Step_Size : REAL := 0.01;
    Max_Temp : REAL := 85.0;
END_VAR
BEGIN
    // Thermal Derating
    IF IGBT_Temp > Max_Temp THEN
        Power_Limit := 1.0 - ((IGBT_Temp - Max_Temp) * 0.05); // Reduce power by 5% per degree
        IF Power_Limit < 0.0 THEN Power_Limit := 0.0; END_IF;
    ELSE
        Power_Limit := 1.0;
    END_IF;

    // MPPT (Perturb and Observe)
    VAR Current_Power : REAL := PV_Voltage * PV_Current;
    VAR deltaP : REAL := Current_Power - Prev_Power;
    VAR deltaV : REAL := PV_Voltage - Prev_Voltage;

    IF deltaP > 0.0 THEN
        IF deltaV > 0.0 THEN PWM_Duty_Cycle := PWM_Duty_Cycle - Step_Size;
        ELSE PWM_Duty_Cycle := PWM_Duty_Cycle + Step_Size; END_IF;
    ELSIF deltaP < 0.0 THEN
        IF deltaV > 0.0 THEN PWM_Duty_Cycle := PWM_Duty_Cycle + Step_Size;
        ELSE PWM_Duty_Cycle := PWM_Duty_Cycle - Step_Size; END_IF;
    END_IF;

    // Apply Thermal Limit to PWM
    PWM_Duty_Cycle := PWM_Duty_Cycle * Power_Limit;
    Prev_Power := Current_Power;
    Prev_Voltage := PV_Voltage;

    // Grid Sync
    IF (Grid_Voltage > 210.0 AND Grid_Voltage < 250.0) AND (Grid_Freq > 49.5 AND Grid_Freq < 50.5) THEN
        Sync_OK := TRUE;
    ELSE
        Sync_OK := FALSE;
    END_IF;
END_FUNCTION_BLOCK
