FUNCTION_BLOCK "fb_ATC_Matrix_Shinkansen"
TITLE = Automatic Train Control Matrix
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : Lead_Rail_Eng
FAMILY : ATC
VERSION : 2.0
   VAR_INPUT 
      ir_TrainVelocity_Kmph : Real; // Current train velocity in km/h
      ir_TrackCircuitImpedance_Ohms : Real; // Impedance from track circuit to calculate preceding train distance
      ir_CatenaryVoltage_kV : Real; // Overhead line voltage in kV
      ir_TrackCurvature_Rad : Real; // Track curvature (1/Radius) in radians/meter
      ir_TrainMass_Tons : Real; // Current mass of the train in metric tons
      ib_EmergencyStop : Bool; // Emergency stop signal
   END_VAR

   VAR_OUTPUT 
      or_TractionPowerDemand_kW : Real; // Traction power command in kW
      or_RegenerativeBraking_kW : Real; // Regenerative braking demand in kW
      or_PneumaticBrakePressure_Bar : Real; // Pneumatic brake application in Bar
      or_SuspensionTiltAngle_Deg : Real; // Active tilt angle in degrees
      ob_ATP_Intervention : Bool; // Automatic Train Protection active
   END_VAR

   VAR 
      stat_PrecedingTrainDist_m : Real; // Calculated moving block distance
      stat_TargetVelocity_Kmph : Real; // Target speed based on moving block
      stat_SpeedError : Real; // Speed deviation
      stat_AccelDemand_ms2 : Real; // Acceleration/Deceleration demand
      temp_Velocity_ms : Real; // Local temp variable for velocity in m/s
      temp_CentrifugalAccel : Real; // Local temp variable for centrifugal accel
      temp_TiltRad : Real; // Local temp variable for tilt
   END_VAR

   VAR CONSTANT 
      MAX_CATENARY_VOLTAGE_KV : Real := 27.5; // Max regenerative voltage threshold
      MAX_TILT_ANGLE_DEG : Real := 8.0; // Max active tilt angle
      GRAVITY : Real := 9.81; // m/s^2
      IMPEDANCE_FACTOR_OHM_PER_M : Real := 0.0015; // Track impedance constant
      BASE_SAFE_BRAKING_DIST_M : Real := 500.0;
   END_VAR

BEGIN
	// 1. Moving-block signaling calculation based on track circuit impedance
	// Distance to preceding train = Impedance / (Impedance per meter)
	IF #ir_TrackCircuitImpedance_Ohms > 0.0 THEN
	    #stat_PrecedingTrainDist_m := #ir_TrackCircuitImpedance_Ohms / #IMPEDANCE_FACTOR_OHM_PER_M;
	ELSE
	    #stat_PrecedingTrainDist_m := 0.0; // Fail-safe: assume 0 distance
	END_IF;

	// Calculate dynamic safe target velocity based on distance
	// V_target = sqrt(2 * a_brake * Distance), scaled for safety margin
	IF #stat_PrecedingTrainDist_m <= #BASE_SAFE_BRAKING_DIST_M THEN
	    #stat_TargetVelocity_Kmph := 0.0;
	    #ob_ATP_Intervention := TRUE;
	ELSE
	    #stat_TargetVelocity_Kmph := SQRT(2.0 * 1.5 * (#stat_PrecedingTrainDist_m - #BASE_SAFE_BRAKING_DIST_M)) * 3.6;
	    #ob_ATP_Intervention := FALSE;
	END_IF;

	// Emergency Overrides
	IF #ib_EmergencyStop THEN
	    #stat_TargetVelocity_Kmph := 0.0;
	    #ob_ATP_Intervention := TRUE;
	END_IF;

	// Speed Error Calculation
	#stat_SpeedError := #stat_TargetVelocity_Kmph - #ir_TrainVelocity_Kmph;

	// Convert speed error to acceleration/deceleration demand
	#stat_AccelDemand_ms2 := #stat_SpeedError * 0.15;

	// 2. Regenerative braking cascaded into pneumatic friction brakes
	IF #stat_AccelDemand_ms2 >= 0.0 THEN
	    // Motoring mode
	    #or_TractionPowerDemand_kW := #stat_AccelDemand_ms2 * #ir_TrainMass_Tons * 10.0;
	    #or_RegenerativeBraking_kW := 0.0;
	    #or_PneumaticBrakePressure_Bar := 0.0;
	ELSE
	    // Braking mode
	    #or_TractionPowerDemand_kW := 0.0;

	    // Check catenary voltage for regen capacity
	    IF #ir_CatenaryVoltage_kV <= #MAX_CATENARY_VOLTAGE_KV THEN
	        // Regenerative braking is safe to apply
	        #or_RegenerativeBraking_kW := ABS(#stat_AccelDemand_ms2) * #ir_TrainMass_Tons * 8.0;
	        #or_PneumaticBrakePressure_Bar := 0.0;
	    ELSE
	        // Catenary overvoltage: cascaded to pneumatic friction brakes
	        #or_RegenerativeBraking_kW := 0.0;
	        #or_PneumaticBrakePressure_Bar := ABS(#stat_AccelDemand_ms2) * 2.5;
	    END_IF;
	END_IF;

	// 3. Active lateral suspension tilt to counteract centrifugal forces on curves
	// Centrifugal acceleration a_c = V^2 / R = V^2 * Curvature
	// Required tilt angle theta = arctan(a_c / g)
	#temp_Velocity_ms := #ir_TrainVelocity_Kmph / 3.6;
	#temp_CentrifugalAccel := (#temp_Velocity_ms * #temp_Velocity_ms) * #ir_TrackCurvature_Rad;

	// Calculate required tilt in radians and convert to degrees
	#temp_TiltRad := ATAN(#temp_CentrifugalAccel / #GRAVITY);
	#or_SuspensionTiltAngle_Deg := #temp_TiltRad * (180.0 / 3.14159265);

	// Limit to max tilt angle
	IF #or_SuspensionTiltAngle_Deg > #MAX_TILT_ANGLE_DEG THEN
	    #or_SuspensionTiltAngle_Deg := #MAX_TILT_ANGLE_DEG;
	ELSIF #or_SuspensionTiltAngle_Deg < -#MAX_TILT_ANGLE_DEG THEN
	    #or_SuspensionTiltAngle_Deg := -#MAX_TILT_ANGLE_DEG;
	END_IF;

END_FUNCTION_BLOCK
