FUNCTION_BLOCK FB_SnowGunController
TITLE = 'Commercial Artificial Snowmaking System Controller'
VERSION : '1.1'

VAR_INPUT
    bEnable            : BOOL; // Master enable signal
    bStartCmd          : BOOL; // Command to start snowmaking
    bStopCmd           : BOOL; // Command to stop snowmaking
    rAmbientTemp       : REAL; // Ambient Temperature (Celsius)
    rRelativeHumidity  : REAL; // Relative Humidity (0.0 to 100.0 %)
    rWaterPressure     : REAL; // Supply water pressure (Bar)
    rAirPressure       : REAL; // Supply compressed air pressure (Bar)
    rTargetRatio       : REAL; // Desired Air/Water Ratio
    rWindSpeed         : REAL; // Wind speed (m/s)
END_VAR

VAR_OUTPUT
    bWaterValveCmd     : BOOL; // Main water valve isolation
    bAirValveCmd       : BOOL; // Main air valve isolation
    rWaterValvePos     : REAL; // 0-100% position for water flow
    rAirValvePos       : REAL; // 0-100% position for air flow
    bNucleatorHeater   : BOOL; // Prevent nucleator freezing
    iCurrentStage      : INT;  // 0=Off, 1=Warmup, 2=Air Purge, 3=Nucleation, 4=Full Snow, 5=Shutdown
    rCalculatedWetBulb : REAL; // Calculated wet-bulb temperature
    bSystemFault       : BOOL; // Fault flag
    sStatusMsg         : STRING[50];
END_VAR

VAR
    iState             : INT := 0; // Internal state machine
    tStateTimer        : TON;
    rTw                : REAL; // Wet bulb temp
    bLowPressureFault  : BOOL;
    bTempTooHigh       : BOOL;
END_VAR

// --- WET BULB TEMPERATURE CALCULATION (Stull Approximation) ---
// Tw = T * atan(0.151977 * sqrt(RH + 8.313659)) + atan(T + RH) - atan(RH - 1.676331) + 0.00391838 * (RH)^1.5 * atan(0.023101 * RH) - 4.686035
rTw := rAmbientTemp * ATAN(0.151977 * SQRT(rRelativeHumidity + 8.313659)) 
       + ATAN(rAmbientTemp + rRelativeHumidity) 
       - ATAN(rRelativeHumidity - 1.676331) 
       + 0.00391838 * EXPT(rRelativeHumidity, 1.5) * ATAN(0.023101 * rRelativeHumidity) 
       - 4.686035;
rCalculatedWetBulb := rTw;

// --- FAULT MONITORING ---
IF bEnable AND (rWaterPressure < 10.0 OR rAirPressure < 5.0) THEN
    bLowPressureFault := TRUE;
ELSE
    bLowPressureFault := FALSE;
END_IF;

IF rTw > -2.0 THEN
    bTempTooHigh := TRUE; // Marginal snowmaking conditions (> -2C Wet Bulb)
ELSE
    bTempTooHigh := FALSE;
END_IF;

bSystemFault := bLowPressureFault;

// --- STATE MACHINE ---
CASE iState OF
    0: // OFF
        bWaterValveCmd := FALSE;
        bAirValveCmd := FALSE;
        rWaterValvePos := 0.0;
        rAirValvePos := 0.0;
        bNucleatorHeater := FALSE;
        iCurrentStage := 0;
        sStatusMsg := 'System Standby';

        IF bStartCmd AND bEnable AND NOT bSystemFault AND NOT bTempTooHigh THEN
            iState := 10;
        END_IF;

    10: // WARMUP & HEATER PREP
        bNucleatorHeater := TRUE;
        iCurrentStage := 1;
        sStatusMsg := 'Heater Warmup Phase';
        tStateTimer(IN := TRUE, PT := T#30s);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: // AIR PURGE & NUCLEATOR PREP
        bAirValveCmd := TRUE;
        rAirValvePos := 100.0;
        iCurrentStage := 2;
        sStatusMsg := 'Air Purging Nucleators';
        tStateTimer(IN := TRUE, PT := T#15s);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: // NUCLEATION & WATER INTRO
        bWaterValveCmd := TRUE;
        // Start water at a low flow to ensure proper atomization and freezing before bulk flow
        rWaterValvePos := 15.0; 
        iCurrentStage := 3;
        sStatusMsg := 'Establishing Nucleation';
        tStateTimer(IN := TRUE, PT := T#20s);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: // FULL SNOW PRODUCTION (WET-BULB TRACKING & VALVE STAGING)
        iCurrentStage := 4;
        sStatusMsg := 'Full Snow Production';

        // Dynamically adjust water flow based on wet bulb temperature
        // Colder wet bulb -> higher water flow can be sustained
        IF rTw < -10.0 THEN
            rWaterValvePos := 100.0; // Stage 4: Max flow
        ELSIF rTw < -7.5 THEN
            rWaterValvePos := 80.0;  // Stage 3
        ELSIF rTw < -5.0 THEN
            rWaterValvePos := 50.0;  // Stage 2
        ELSE
            rWaterValvePos := 25.0;  // Stage 1: Marginal flow
        END_IF;

        // Regulate air valve to maintain target air/water ratio
        // Simple proportional mapping for simulation
        rAirValvePos := rWaterValvePos * rTargetRatio;
        IF rAirValvePos > 100.0 THEN rAirValvePos := 100.0; END_IF;
        IF rAirValvePos < 20.0 THEN rAirValvePos := 20.0; END_IF;

        IF bStopCmd OR bTempTooHigh OR bSystemFault THEN
            iState := 50;
        END_IF;

    50: // SHUTDOWN & LINE DRAIN
        bWaterValveCmd := FALSE;
        rWaterValvePos := 0.0;
        iCurrentStage := 5;
        sStatusMsg := 'Shutdown & Purging Water';
        // Keep air on to blow out water lines and prevent freezing
        bAirValveCmd := TRUE;
        rAirValvePos := 100.0;

        tStateTimer(IN := TRUE, PT := T#45s);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 0; // Return to Off
        END_IF;

    ELSE
        iState := 0;
END_CASE;

// Handle Heater Timer separately if needed, but it stays on during production
IF iState > 0 AND iState < 50 THEN
    bNucleatorHeater := TRUE;
ELSE
    bNucleatorHeater := FALSE;
END_IF;

END_FUNCTION_BLOCK
