FUNCTION_BLOCK FB_VLM_ExtractorControl
TITLE = 'VLM Extractor Tray High-Speed Indexing and Load Compensation'
VERSION : '1.0'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    bEnable : BOOL; // Enable module
    bStartIndexing : BOOL; // Start indexing to target shelf
    rTargetHeight_mm : REAL; // Target height in mm
    rCurrentHeight_mm : REAL; // Current actual height from laser measurement
    rLoadWeight_kg : REAL; // Measured tray weight from load cells
    rLoadCenterOffset_mm : REAL; // Calculated CoG offset from center
    bLaserCurtainClear : BOOL; // True if safety laser curtain is clear
    bSafetyDoorLocked : BOOL; // True if external access door is secure
    bTrayPresent : BOOL; // True if tray is detected on extractor
END_VAR

VAR_OUTPUT
    bReady : BOOL; // System is ready to move
    bMoving : BOOL; // Extractor is in motion
    bInPosition : BOOL; // Extractor has reached target height within tolerance
    bError : BOOL; // Error active
    iErrorCode : INT; // Active error code
    rServoVelocityCmd_m_s : REAL; // Velocity command to lift servo
    rServoTorqueFeedforward_Nm : REAL; // Feedforward torque for load compensation
    rTrayTiltCorrection_deg : REAL; // Commanded tilt to compensate for load imbalance
END_VAR

VAR
    iState : INT := 0; // State machine step
    rPositionError_mm : REAL;
    rVelocitySetpoint : REAL;
    rDecelDistance_mm : REAL;
    rMaxVelocity_m_s : REAL := 2.5;
    rMaxAccel_m_s2 : REAL := 3.0;
    rJerkLimit_m_s3 : REAL := 15.0;

    // Compensation constants
    rGravity_m_s2 : REAL := 9.81;
    rDrumRadius_m : REAL := 0.15;
    rExtractorMass_kg : REAL := 250.0;
    rTiltGain : REAL := 0.05; // Degrees per Nm of imbalance torque

    // Timers
    tSettleDelay : TON;
    tSafetyWatchdog : TON;

    // Internal Flags
    bSafetyOK : BOOL;
END_VAR

(* 
    Vertical Lift Module - Extractor Kinematics and Safety Control
    Implements jerk-limited positioning with dynamic load torque compensation
    and asymmetric load tilt correction.
*)

// Evaluate Safety Conditions
bSafetyOK := bEnable AND bLaserCurtainClear AND bSafetyDoorLocked;

IF NOT bSafetyOK THEN
    iState := 999; // Jump to error state
END_IF;

// Main State Machine
CASE iState OF
    0: // INIT / IDLE
        bReady := bSafetyOK;
        bMoving := FALSE;
        bInPosition := FALSE;
        rServoVelocityCmd_m_s := 0.0;
        rServoTorqueFeedforward_Nm := ((rExtractorMass_kg + rLoadWeight_kg) * rGravity_m_s2) * rDrumRadius_m;
        rTrayTiltCorrection_deg := 0.0;

        IF bReady AND bStartIndexing THEN
            iState := 10;
        END_IF;

    10: // CALCULATE PROFILE AND DYNAMIC COMPENSATION
        bReady := FALSE;
        bMoving := TRUE;
        bInPosition := FALSE;

        // Calculate required torque to hold load and compensate for imbalance
        rServoTorqueFeedforward_Nm := ((rExtractorMass_kg + rLoadWeight_kg) * rGravity_m_s2) * rDrumRadius_m;

        // Apply tilt correction if load is heavily imbalanced to prevent tray jamming
        rTrayTiltCorrection_deg := LIMIT(MN:=-2.0, IN:=(rLoadWeight_kg * rLoadCenterOffset_mm * rTiltGain / 1000.0), MX:=2.0);

        iState := 20;

    20: // KINEMATIC MOTION (Simplified S-Curve approximation)
        rPositionError_mm := rTargetHeight_mm - rCurrentHeight_mm;
        rDecelDistance_mm := (rMaxVelocity_m_s * rMaxVelocity_m_s) / (2.0 * rMaxAccel_m_s2) * 1000.0;

        IF ABS(rPositionError_mm) <= 1.0 THEN
            // Within 1mm, switch to settling phase
            rServoVelocityCmd_m_s := 0.0;
            iState := 30;
        ELSIF ABS(rPositionError_mm) <= rDecelDistance_mm THEN
            // Deceleration phase
            rVelocitySetpoint := SQRT(2.0 * rMaxAccel_m_s2 * (ABS(rPositionError_mm)/1000.0));
            IF rPositionError_mm < 0.0 THEN
                rServoVelocityCmd_m_s := -rVelocitySetpoint;
            ELSE
                rServoVelocityCmd_m_s := rVelocitySetpoint;
            END_IF;
        ELSE
            // Constant velocity phase
            IF rPositionError_mm < 0.0 THEN
                rServoVelocityCmd_m_s := -rMaxVelocity_m_s;
            ELSE
                rServoVelocityCmd_m_s := rMaxVelocity_m_s;
            END_IF;
        END_IF;

    30: // SETTLING
        tSettleDelay(IN:=TRUE, PT:=T#250ms);
        IF tSettleDelay.Q THEN
            tSettleDelay(IN:=FALSE);
            bMoving := FALSE;
            bInPosition := TRUE;
            iState := 0; // Return to idle
        END_IF;

    999: // ERROR STATE
        bReady := FALSE;
        bMoving := FALSE;
        rServoVelocityCmd_m_s := 0.0;
        bError := TRUE;

        IF NOT bLaserCurtainClear THEN
            iErrorCode := 101; // Laser curtain breached
        ELSIF NOT bSafetyDoorLocked THEN
            iErrorCode := 102; // Door unlocked
        ELSIF NOT bEnable THEN
            iErrorCode := 100; // System disabled
        ELSE
            iErrorCode := 999; // Unknown error
        END_IF;

        // Error recovery logic requires manual reset in this implementation
        IF bSafetyOK AND NOT bStartIndexing THEN
            bError := FALSE;
            iErrorCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
