FUNCTION_BLOCK FB_TireCuringPressControl
TITLE = 'Tire Curing Press Control System'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

(* 
   This function block controls a highly complex Tire Curing Press.
   It handles bladder shaping (steam/nitrogen), segmented mold hydraulic locking, 
   and curing profiles based on dynamic cycle times and thermal setpoints.
*)

VAR_INPUT
    xEnable                  : BOOL;   // System enable signal
    xStartCycle              : BOOL;   // Start curing cycle
    xEmergencyStop           : BOOL;   // Emergency stop
    rTargetTemperature       : REAL;   // Target curing temperature (°C)
    rTargetPressure          : REAL;   // Target shaping pressure (bar)
    rCuringTime              : REAL;   // Total curing time (s)
    xMoldClosedLimit         : BOOL;   // Sensor: Mold fully closed
    xMoldLockedLimit         : BOOL;   // Sensor: Mold fully locked
    rCurrentMoldTemp         : REAL;   // Sensor: Current mold temperature
    rCurrentBladderPressure  : REAL;   // Sensor: Current bladder pressure
    xNitrogenReady           : BOOL;   // Supply: Nitrogen available
    xSteamReady              : BOOL;   // Supply: Steam available
END_VAR

VAR_OUTPUT
    xSystemReady             : BOOL;   // System is ready to start
    xCuringActive            : BOOL;   // Curing cycle in progress
    xCycleComplete           : BOOL;   // Curing cycle complete
    xError                   : BOOL;   // Error active
    wErrorID                 : WORD;   // Error code
    xHydraulicPumpCmd        : BOOL;   // Command: Hydraulic pump start
    xMoldCloseCmd            : BOOL;   // Command: Close mold
    xMoldLockCmd             : BOOL;   // Command: Lock mold
    xSteamValveCmd           : BOOL;   // Command: Open steam valve
    xNitrogenValveCmd        : BOOL;   // Command: Open nitrogen valve
    xExhaustValveCmd         : BOOL;   // Command: Open exhaust valve
    rRemainingTime           : REAL;   // Remaining curing time
END_VAR

VAR
    iState                   : INT;    // State machine step
    tCycleTimer              : TON;    // Timer for curing phases
    tLockingTimer            : TON;    // Timer for hydraulic locking
    tHeatingTimer            : TON;    // Timer for steam pre-heating
    rInternalTimer           : REAL;   // Internal accumulator for cycle time
    bShapingComplete         : BOOL;
    bCuringPhaseComplete     : BOOL;
END_VAR

(* State Machine Constants *)
VAR CONSTANT
    STATE_IDLE               : INT := 0;
    STATE_MOLD_CLOSING       : INT := 10;
    STATE_MOLD_LOCKING       : INT := 20;
    STATE_BLADDER_SHAPING    : INT := 30;
    STATE_STEAM_HEATING      : INT := 40;
    STATE_NITROGEN_CURING    : INT := 50;
    STATE_EXHAUST            : INT := 60;
    STATE_MOLD_UNLOCKING     : INT := 70;
    STATE_MOLD_OPENING       : INT := 80;
    STATE_COMPLETE           : INT := 90;
    STATE_ERROR              : INT := 999;
END_VAR

BEGIN
    // Handle Emergency Stop
    IF xEmergencyStop THEN
        iState := STATE_ERROR;
        wErrorID := 16#E001; // E-Stop pressed
    END_IF;

    // Reset logic
    IF NOT xEnable AND NOT xEmergencyStop THEN
        iState := STATE_IDLE;
        xError := FALSE;
        wErrorID := 0;
    END_IF;

    // Timer Instances Update
    tCycleTimer(IN := (iState = STATE_STEAM_HEATING) OR (iState = STATE_NITROGEN_CURING), PT := REAL_TO_TIME(rCuringTime * 1000.0));
    tLockingTimer(IN := (iState = STATE_MOLD_LOCKING), PT := T#5S);
    tHeatingTimer(IN := (iState = STATE_STEAM_HEATING), PT := T#15S);

    // Main State Machine
    CASE iState OF
        STATE_IDLE:
            xSystemReady := TRUE;
            xCuringActive := FALSE;
            xCycleComplete := FALSE;
            xHydraulicPumpCmd := FALSE;
            xMoldCloseCmd := FALSE;
            xMoldLockCmd := FALSE;
            xSteamValveCmd := FALSE;
            xNitrogenValveCmd := FALSE;
            xExhaustValveCmd := FALSE;
            rRemainingTime := rCuringTime;

            IF xStartCycle AND xEnable AND NOT xError THEN
                xSystemReady := FALSE;
                xCuringActive := TRUE;
                iState := STATE_MOLD_CLOSING;
            END_IF;

        STATE_MOLD_CLOSING:
            xHydraulicPumpCmd := TRUE;
            xMoldCloseCmd := TRUE;

            IF xMoldClosedLimit THEN
                iState := STATE_MOLD_LOCKING;
            END_IF;

        STATE_MOLD_LOCKING:
            xMoldLockCmd := TRUE;

            IF xMoldLockedLimit AND tLockingTimer.Q THEN
                iState := STATE_BLADDER_SHAPING;
            END_IF;

        STATE_BLADDER_SHAPING:
            // Low pressure steam or nitrogen to shape the bladder
            IF rCurrentBladderPressure < (rTargetPressure * 0.2) THEN
                xSteamValveCmd := TRUE;
            ELSE
                xSteamValveCmd := FALSE;
                bShapingComplete := TRUE;
                iState := STATE_STEAM_HEATING;
            END_IF;

        STATE_STEAM_HEATING:
            // Full steam to reach target temperature
            xSteamValveCmd := TRUE;

            IF rCurrentMoldTemp >= rTargetTemperature AND tHeatingTimer.Q THEN
                xSteamValveCmd := FALSE;
                iState := STATE_NITROGEN_CURING;
            END_IF;

        STATE_NITROGEN_CURING:
            // High pressure nitrogen to hold pressure during cure
            xNitrogenValveCmd := TRUE;
            rRemainingTime := TIME_TO_REAL(REAL_TO_TIME(rCuringTime * 1000.0) - tCycleTimer.ET) / 1000.0;

            IF tCycleTimer.Q THEN
                xNitrogenValveCmd := FALSE;
                iState := STATE_EXHAUST;
            END_IF;

        STATE_EXHAUST:
            xExhaustValveCmd := TRUE;

            IF rCurrentBladderPressure < 0.1 THEN // 0.1 bar threshold for safe opening
                xExhaustValveCmd := FALSE;
                iState := STATE_MOLD_UNLOCKING;
            END_IF;

        STATE_MOLD_UNLOCKING:
            xMoldLockCmd := FALSE;
            // Delay or sensor feedback required here for real application
            IF NOT xMoldLockedLimit THEN
                iState := STATE_MOLD_OPENING;
            END_IF;

        STATE_MOLD_OPENING:
            xMoldCloseCmd := FALSE;

            IF NOT xMoldClosedLimit THEN
                iState := STATE_COMPLETE;
            END_IF;

        STATE_COMPLETE:
            xCuringActive := FALSE;
            xCycleComplete := TRUE;
            xHydraulicPumpCmd := FALSE;

            IF NOT xStartCycle THEN
                iState := STATE_IDLE;
            END_IF;

        STATE_ERROR:
            xError := TRUE;
            xCuringActive := FALSE;
            xHydraulicPumpCmd := FALSE;
            xMoldCloseCmd := FALSE;
            xMoldLockCmd := FALSE;
            xSteamValveCmd := FALSE;
            xNitrogenValveCmd := FALSE;
            xExhaustValveCmd := TRUE; // Fail safe: exhaust pressure

    END_CASE;

END_FUNCTION_BLOCK
