FUNCTION_BLOCK FB_IndustrialControl
TITLE = '6-DOF Stewart Platform Motion Controller'
VERSION : '2.1'

VAR_INPUT
    Enable : BOOL;
    EmergencyStop : BOOL;
    Set_Surge : LREAL; 
    Set_Sway : LREAL; 
    Set_Heave : LREAL; 
    Set_Roll : LREAL; 
    Set_Pitch : LREAL; 
    Set_Yaw : LREAL; 
    Actuator_Pos_1 : LREAL; 
    Actuator_Pos_2 : LREAL;
    Actuator_Pos_3 : LREAL;
    Actuator_Pos_4 : LREAL;
    Actuator_Pos_5 : LREAL;
    Actuator_Pos_6 : LREAL;
    Sys_Pressure : LREAL;
END_VAR

VAR_OUTPUT
    System_Ready : BOOL;
    Fault_Active : BOOL;
    Fault_Code : INT;
    Valve_Cmd_1 : LREAL;
    Valve_Cmd_2 : LREAL;
    Valve_Cmd_3 : LREAL;
    Valve_Cmd_4 : LREAL;
    Valve_Cmd_5 : LREAL;
    Valve_Cmd_6 : LREAL;
    Load_Buffer_Active : BOOL;
END_VAR

VAR
    Filtered_Surge, Filtered_Sway, Filtered_Heave, Filtered_Roll, Filtered_Pitch, Filtered_Yaw : LREAL;
    Prev_Surge, Prev_Sway, Prev_Heave : LREAL;
    HPF_Omega : LREAL := 1.5; LPF_Omega : LREAL := 0.5; dt : LREAL := 0.001;
    Base_Radius : LREAL := 2.5; Platform_Radius : LREAL := 1.8;
    Leg_Min_Len : LREAL := 2.0; Leg_Max_Len : LREAL := 3.5;
    Bx, By, Bz, Px, Py, Pz : ARRAY[1..6] OF LREAL;
    Target_Lengths : ARRAY[1..6] OF LREAL;
    Kp : LREAL := 50.0; Ki : LREAL := 10.0; Kd : LREAL := 2.5;
    Integral_Errors, Prev_Errors : ARRAY[1..6] OF LREAL;
    i : INT;
    cR, sR, cP, sP, cY, sY : LREAL;
    R11, R12, R13, R21, R22, R23, R31, R32, R33 : LREAL;
    Init_Done : BOOL := FALSE;
    Pressure_Drop_Rate, Prev_Pressure : LREAL; Buffer_Threshold : LREAL := 15.0;
    Qx, Qy, Qz, Error, Derivative, Cmd : LREAL;
END_VAR

IF NOT Init_Done THEN
    Bx[1] := 2.165; By[1] := 1.25; Bz[1] := 0.0;
    Bx[2] := -2.165; By[2] := 1.25; Bz[2] := 0.0;
    Bx[3] := -2.165; By[3] := -1.25; Bz[3] := 0.0;
    Bx[4] := 2.165; By[4] := -1.25; Bz[4] := 0.0;
    Bx[5] := -2.5; By[5] := 0.0; Bz[5] := 0.0;
    Bx[6] := -2.5; By[6] := 0.0; Bz[6] := 0.0;
    Px[1] := 1.74; Py[1] := 0.46; Pz[1] := 0.0;
    Px[2] := -1.74; Py[2] := 0.46; Pz[2] := 0.0;
    Px[3] := -1.74; Py[3] := -0.46; Pz[3] := 0.0;
    Px[4] := 1.74; Py[4] := -0.46; Pz[4] := 0.0;
    Px[5] := -1.8; Py[5] := 0.0; Pz[5] := 0.0;
    Px[6] := -1.8; Py[6] := 0.0; Pz[6] := 0.0;
    Init_Done := TRUE;
END_IF;

IF EmergencyStop THEN
    Fault_Active := TRUE; Fault_Code := 100; System_Ready := FALSE;
    Valve_Cmd_1 := 0.0; Valve_Cmd_2 := 0.0; Valve_Cmd_3 := 0.0;
    Valve_Cmd_4 := 0.0; Valve_Cmd_5 := 0.0; Valve_Cmd_6 := 0.0;
    RETURN;
END_IF;

IF Sys_Pressure < 150.0 THEN
    Fault_Active := TRUE; Fault_Code := 200; System_Ready := FALSE; RETURN;
END_IF;

Pressure_Drop_Rate := Prev_Pressure - Sys_Pressure;
IF Pressure_Drop_Rate > Buffer_Threshold THEN
    Load_Buffer_Active := TRUE;
    Filtered_Surge := Prev_Surge * 0.9; Filtered_Sway := Prev_Sway * 0.9; Filtered_Heave := Prev_Heave * 0.9;
ELSE
    Load_Buffer_Active := FALSE;
    Filtered_Surge := (Prev_Surge + Set_Surge - Prev_Surge) * (1.0 / (1.0 + HPF_Omega * dt));
    Filtered_Sway := (Prev_Sway + Set_Sway - Prev_Sway) * (1.0 / (1.0 + HPF_Omega * dt));
    Filtered_Heave := (Prev_Heave + Set_Heave - Prev_Heave) * (1.0 / (1.0 + HPF_Omega * dt));
    Filtered_Roll := Set_Roll; Filtered_Pitch := Set_Pitch; Filtered_Yaw := Set_Yaw;
END_IF;

Prev_Surge := Filtered_Surge; Prev_Sway := Filtered_Sway; Prev_Heave := Filtered_Heave;
Prev_Pressure := Sys_Pressure;

cR := COS(Filtered_Roll); sR := SIN(Filtered_Roll);
cP := COS(Filtered_Pitch); sP := SIN(Filtered_Pitch);
cY := COS(Filtered_Yaw); sY := SIN(Filtered_Yaw);

R11 := cP * cY; R12 := cY * sP * sR - cR * sY; R13 := sR * sY + cR * cY * sP;
R21 := cP * sY; R22 := cR * cY + sP * sR * sY; R23 := cR * sP * sY - cY * sR;
R31 := -sP; R32 := cP * sR; R33 := cP * cR;

FOR i := 1 TO 6 DO
    Qx := Filtered_Surge + (R11 * Px[i] + R12 * Py[i] + R13 * Pz[i]) - Bx[i];
    Qy := Filtered_Sway + (R21 * Px[i] + R22 * Py[i] + R23 * Pz[i]) - By[i];
    Qz := Filtered_Heave + (R31 * Px[i] + R32 * Py[i] + R33 * Pz[i]) - Bz[i] + 2.5;

    Target_Lengths[i] := SQRT(Qx*Qx + Qy*Qy + Qz*Qz);
    IF Target_Lengths[i] > Leg_Max_Len THEN Target_Lengths[i] := Leg_Max_Len; END_IF;
    IF Target_Lengths[i] < Leg_Min_Len THEN Target_Lengths[i] := Leg_Min_Len; END_IF;

    CASE i OF
        1: Error := Target_Lengths[1] - Actuator_Pos_1;
        2: Error := Target_Lengths[2] - Actuator_Pos_2;
        3: Error := Target_Lengths[3] - Actuator_Pos_3;
        4: Error := Target_Lengths[4] - Actuator_Pos_4;
        5: Error := Target_Lengths[5] - Actuator_Pos_5;
        6: Error := Target_Lengths[6] - Actuator_Pos_6;
    END_CASE;

    Integral_Errors[i] := Integral_Errors[i] + Error * dt;
    Derivative := (Error - Prev_Errors[i]) / dt;
    Cmd := Kp * Error + Ki * Integral_Errors[i] + Kd * Derivative;

    IF Cmd > 100.0 THEN Cmd := 100.0; END_IF;
    IF Cmd < -100.0 THEN Cmd := -100.0; END_IF;

    CASE i OF
        1: Valve_Cmd_1 := Cmd;
        2: Valve_Cmd_2 := Cmd;
        3: Valve_Cmd_3 := Cmd;
        4: Valve_Cmd_4 := Cmd;
        5: Valve_Cmd_5 := Cmd;
        6: Valve_Cmd_6 := Cmd;
    END_CASE;

    Prev_Errors[i] := Error;
END_FOR;
System_Ready := TRUE; Fault_Active := FALSE; Fault_Code := 0;
END_FUNCTION_BLOCK
