FUNCTION_BLOCK FB_UltraMaglev_EDS_LSM_Controller
TITLE = 'Ultra-High-Speed EDS Maglev Master Controller'
VERSION : '3.1'
AUTHOR : 'Lumina AI Swarm'

VAR_INPUT
    Enable_System : BOOL; // Master enable switch
    Velocity_Actual_kmh : LREAL; // Actual train velocity in km/h
    Target_Velocity_kmh : LREAL; // Target train velocity in km/h
    Guideway_Clearance_mm : LREAL; // Air gap distance
    Levitation_Height_mm : LREAL; // Suspension height from EDS
    Track_Curvature_Radius_m : LREAL; // Turning radius
    Superconducting_Coil_Temp_K : LREAL; // Cryostat temperature
    Emergency_Brake_Trigger : BOOL; // E-Stop
    Wind_Speed_ms : LREAL; // Ambient wind speed
END_VAR

VAR_OUTPUT
    LSM_Thrust_Force_kN : LREAL; // Commanded propulsion force
    LSM_Phase_Angle_deg : LREAL; // Propulsion phase angle
    EDS_Coil_Active : ARRAY[0..15] OF BOOL; // 16-zone levitation activation matrix
    Aerodynamic_Brake_Angle_deg : LREAL; // Deployment angle of aero brakes
    Cryo_Cooling_Pump_Speed : LREAL; // Cryo maintenance
    System_Status : STRING[32]; // Operational state
    Alarm_Emergency : BOOL; // Fault condition flag
END_VAR

VAR
    State : INT := 0; // State machine index
    Integral_Error : LREAL := 0.0;
    Previous_Error : LREAL := 0.0;
    Kp : LREAL := 15.5; // Proportional gain
    Ki : LREAL := 2.1; // Integral gain
    Kd : LREAL := 0.8; // Derivative gain
    PID_Output : LREAL;
    i : INT;
    Quench_Risk : BOOL;
    Levitation_Stable : BOOL;
    Deceleration_Required : LREAL;
END_VAR

// Constants
VAR CONSTANT
    MAX_VELOCITY : LREAL := 600.0;
    MIN_LEVITATION : LREAL := 95.0; // minimum safe height in mm
    MAX_LEVITATION : LREAL := 115.0;
    CRIT_TEMP_K : LREAL := 5.2; // Quench temperature limit
    AERO_BRAKE_MAX_DEG : LREAL := 65.0;
END_VAR

BEGIN
    // Safety Interlocks
    Quench_Risk := Superconducting_Coil_Temp_K >= CRIT_TEMP_K;
    Levitation_Stable := (Guideway_Clearance_mm >= MIN_LEVITATION) AND (Guideway_Clearance_mm <= MAX_LEVITATION);

    IF Emergency_Brake_Trigger OR Quench_Risk THEN
        State := 99; // Emergency state
    ELSIF NOT Enable_System THEN
        State := 0; // Idle
    ELSE
        IF Velocity_Actual_kmh < 150.0 THEN
            State := 1; // Acceleration, wheels still deployed
        ELSIF Velocity_Actual_kmh >= 150.0 AND NOT Levitation_Stable THEN
            State := 2; // Transition to EDS levitation
        ELSE
            State := 3; // Cruise and High-Speed Maglev
        END_IF;
    END_IF;

    // State Machine
    CASE State OF
        0: // Idle
            LSM_Thrust_Force_kN := 0.0;
            Aerodynamic_Brake_Angle_deg := 0.0;
            System_Status := 'IDLE / SAFE';
            FOR i := 0 TO 15 DO
                EDS_Coil_Active[i] := FALSE;
            END_FOR;
            Alarm_Emergency := FALSE;

        1: // Low-speed acceleration (Rubber tires)
            PID_Output := (Target_Velocity_kmh - Velocity_Actual_kmh) * Kp;
            LSM_Thrust_Force_kN := LIMIT(MN:= 0.0, IN:= PID_Output, MX:= 500.0);
            System_Status := 'LOW SPEED ACCEL';
            FOR i := 0 TO 15 DO
                EDS_Coil_Active[i] := FALSE; // EDS not active yet
            END_FOR;

        2: // Transition to EDS
            System_Status := 'LEVITATION TRANSITION';
            FOR i := 0 TO 15 DO
                EDS_Coil_Active[i] := TRUE; // Energize null-flux coils
            END_FOR;
            // Maintain thrust
            LSM_Thrust_Force_kN := 300.0; 

        3: // High-Speed EDS Cruising
            System_Status := 'EDS HIGH SPEED CRUISE';
            // PID velocity control
            Integral_Error := Integral_Error + (Target_Velocity_kmh - Velocity_Actual_kmh);
            PID_Output := (Target_Velocity_kmh - Velocity_Actual_kmh) * Kp + (Integral_Error * Ki) + ((Target_Velocity_kmh - Velocity_Actual_kmh - Previous_Error) * Kd);
            Previous_Error := Target_Velocity_kmh - Velocity_Actual_kmh;

            LSM_Thrust_Force_kN := LIMIT(MN:= -200.0, IN:= PID_Output, MX:= 1200.0);

            // Turn handling
            IF Track_Curvature_Radius_m < 5000.0 THEN
                LSM_Phase_Angle_deg := 15.0; // Shift LSM phase to assist centripetal force
            ELSE
                LSM_Phase_Angle_deg := 0.0;
            END_IF;

            // Deceleration logic for aero brakes
            Deceleration_Required := Velocity_Actual_kmh - Target_Velocity_kmh;
            IF Deceleration_Required > 50.0 THEN
                Aerodynamic_Brake_Angle_deg := LIMIT(MN:=0.0, IN:= (Deceleration_Required * 0.5), MX:=AERO_BRAKE_MAX_DEG);
            ELSE
                Aerodynamic_Brake_Angle_deg := 0.0;
            END_IF;

        99: // Emergency Stop
            System_Status := 'EMERGENCY STOP';
            Alarm_Emergency := TRUE;
            LSM_Thrust_Force_kN := -1500.0; // Max reverse thrust
            Aerodynamic_Brake_Angle_deg := AERO_BRAKE_MAX_DEG; // Deploy air brakes
            FOR i := 0 TO 15 DO
                EDS_Coil_Active[i] := FALSE; // Drop to skids/wheels
            END_FOR;
    END_CASE;

    // Cryocooler management
    IF Superconducting_Coil_Temp_K > 4.5 THEN
        Cryo_Cooling_Pump_Speed := 100.0; // Max flow
    ELSIF Superconducting_Coil_Temp_K < 4.2 THEN
        Cryo_Cooling_Pump_Speed := 30.0; // Idle flow
    ELSE
        Cryo_Cooling_Pump_Speed := 60.0; // Nominal flow
    END_IF;

END_FUNCTION_BLOCK
