FUNCTION_BLOCK FB_HVDC_Subsea_VSC_Control
TITLE = \'HVDC Subsea Converter Station Control\'
VERSION : \'2.1\'
AUTHOR : \'Lumina Elite Data Architect\'

VAR_INPUT
    bEnable                 : BOOL; // Enable Converter
    fDC_Voltage_Ref         : REAL; // DC Voltage Reference (kV)
    fActivePower_Ref        : REAL; // Active Power Reference (MW)
    fReactivePower_Ref      : REAL; // Reactive Power Reference (MVAr)
    fGrid_Freq_Meas         : REAL; // Grid Frequency Measurement (Hz)
    fGrid_Voltage_Meas      : REAL; // Grid AC Voltage Measurement (kV)
    fDC_Voltage_Meas        : REAL; // DC Link Voltage Measurement (kV)
    fSubModule_Cap_Voltages : ARRAY[1..400] OF REAL; // Sub-module Capacitor Voltages
    iFault_Code             : INT; // Fault code from lower level protections
END_VAR

VAR_OUTPUT
    bConverterActive        : BOOL; // Converter is pulsing
    fId_Ref                 : REAL; // Active current reference (pu)
    fIq_Ref                 : REAL; // Reactive current reference (pu)
    bDC_Chopper_Activate    : BOOL; // DC Chopper braking activation
    iInserted_SubModules_U  : INT; // Number of inserted sub-modules upper arm
    iInserted_SubModules_L  : INT; // Number of inserted sub-modules lower arm
    bAlarm                  : BOOL;
END_VAR

VAR
    fError_Vdc              : REAL;
    fError_P                : REAL;
    fError_Q                : REAL;
    fKp_Vdc                 : REAL := 1.5;
    fKi_Vdc                 : REAL := 10.0;
    fKp_P                   : REAL := 1.2;
    fKi_P                   : REAL := 8.0;
    fKp_Q                   : REAL := 1.0;
    fKi_Q                   : REAL := 5.0;
    fVdc_Int                : REAL;
    fP_Int                  : REAL;
    fQ_Int                  : REAL;
    fId_Ref_Limit           : REAL := 1.2; // 1.2 pu max
    fIq_Ref_Limit           : REAL := 1.2;

    // Sub-module sorting
    i                       : INT;
    j                       : INT;
    fTempVolt               : REAL;
    iSorted_Indices         : ARRAY[1..400] OF INT;
    fSorted_Voltages        : ARRAY[1..400] OF REAL;

    bInit                   : BOOL := FALSE;
END_VAR

// Initialization
IF NOT bInit THEN
    FOR i := 1 TO 400 DO
        iSorted_Indices[i] := i;
        fSorted_Voltages[i] := 0.0;
    END_FOR;
    bInit := TRUE;
END_IF;

// Main Control Logic
IF bEnable AND iFault_Code = 0 THEN
    bConverterActive := TRUE;
    bAlarm := FALSE;

    // DC Chopper Logic for Overvoltage Protection
    IF fDC_Voltage_Meas > 1.15 * fDC_Voltage_Ref THEN
        bDC_Chopper_Activate := TRUE;
    ELSIF fDC_Voltage_Meas < 1.05 * fDC_Voltage_Ref THEN
        bDC_Chopper_Activate := FALSE;
    END_IF;

    // Active / Reactive Power Decoupling and PI Control
    // Vdc Control
    fError_Vdc := fDC_Voltage_Ref - fDC_Voltage_Meas;
    fVdc_Int := fVdc_Int + (fError_Vdc * fKi_Vdc * 0.001); // Assuming 1ms task

    // Power Control
    fError_P := fActivePower_Ref - (fDC_Voltage_Meas * fId_Ref); // Simplified feedback
    fP_Int := fP_Int + (fError_P * fKi_P * 0.001);

    fError_Q := fReactivePower_Ref - (fGrid_Voltage_Meas * fIq_Ref);
    fQ_Int := fQ_Int + (fError_Q * fKi_Q * 0.001);

    // Combine Vdc and P control for Id ref
    fId_Ref := (fError_Vdc * fKp_Vdc + fVdc_Int) + (fError_P * fKp_P + fP_Int);

    // Limit Id Ref
    IF fId_Ref > fId_Ref_Limit THEN fId_Ref := fId_Ref_Limit; END_IF;
    IF fId_Ref < -fId_Ref_Limit THEN fId_Ref := -fId_Ref_Limit; END_IF;

    // Calculate Iq Ref
    fIq_Ref := (fError_Q * fKp_Q + fQ_Int);

    // Limit Iq Ref
    IF fIq_Ref > fIq_Ref_Limit THEN fIq_Ref := fIq_Ref_Limit; END_IF;
    IF fIq_Ref < -fIq_Ref_Limit THEN fIq_Ref := -fIq_Ref_Limit; END_IF;

    // Sub-Module Sorting Algorithm
    FOR i := 1 TO 400 DO
        fSorted_Voltages[i] := fSubModule_Cap_Voltages[i];
        iSorted_Indices[i] := i;
    END_FOR;

    FOR i := 1 TO 399 DO
        FOR j := 1 TO 400 - i DO
            IF fSorted_Voltages[j] < fSorted_Voltages[j+1] THEN
                fTempVolt := fSorted_Voltages[j];
                fSorted_Voltages[j] := fSorted_Voltages[j+1];
                fSorted_Voltages[j+1] := fTempVolt;
            END_IF;
        END_FOR;
    END_FOR;

    iInserted_SubModules_U := REAL_TO_INT((fDC_Voltage_Ref / 400.0) * 200.0);
    iInserted_SubModules_L := REAL_TO_INT((fDC_Voltage_Ref / 400.0) * 200.0);

ELSE
    bConverterActive := FALSE;
    bDC_Chopper_Activate := FALSE;
    fId_Ref := 0.0;
    fIq_Ref := 0.0;
    fVdc_Int := 0.0;
    fP_Int := 0.0;
    fQ_Int := 0.0;
    iInserted_SubModules_U := 0;
    iInserted_SubModules_L := 0;

    IF iFault_Code <> 0 THEN
        bAlarm := TRUE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
```

