FUNCTION_BLOCK FB_HVDC_CableLayingVessel_Control
VAR_INPUT
    bEnableSys : BOOL; // Master enable

    // Dynamic Positioning (DP) Inputs
    rVesselHeadingRef : REAL; // Target heading [deg]
    rVesselHeadingAct : REAL; // Actual heading [deg]
    rPosErrorX : REAL; // Position error surge [m]
    rPosErrorY : REAL; // Position error sway [m]
    rWindSpeed : REAL; // [m/s]
    rWindDir : REAL; // [deg]
    rSeaCurrentSpeed : REAL; // [m/s]

    // Cable Carousel & Tensioner Inputs
    rCableTensionSetpoint : REAL; // [kN]
    rCableTensionAct : REAL; // [kN]
    rPayoutSpeedRef : REAL; // [m/min]
    rPayoutSpeedAct : REAL; // [m/min]
    rCarouselBrakePressure : REAL; // [bar]
    rChuteAngleAct : REAL; // [deg]

    // Touch-Down Monitoring (TDM) ROV Inputs
    rROV_DepthAct : REAL; // [m]
    rROV_PitchAct : REAL; // [deg]
    rROV_TDP_Distance : REAL; // Distance to Touch Down Point [m]
    rWaterDepth : REAL; // [m]
END_VAR

VAR_OUTPUT
    // DP Thruster Allocation Commands
    rThruster1_PitchCmd : REAL; // Bow Tunnel 1 Pitch [%]
    rThruster2_PitchCmd : REAL; // Bow Tunnel 2 Pitch [%]
    rThruster3_AzimuthAngleCmd : REAL; // Stern Azimuth 1 Angle [deg]
    rThruster3_PitchCmd : REAL; // Stern Azimuth 1 Pitch [%]
    rThruster4_AzimuthAngleCmd : REAL; // Stern Azimuth 2 Angle [deg]
    rThruster4_PitchCmd : REAL; // Stern Azimuth 2 Pitch [%]

    // Cable Equipment Commands
    rTensionerMotorTorqueCmd : REAL; // [%]
    rCarouselDriveSpeedCmd : REAL; // [rpm]
    bCarouselBrakeRelease : BOOL;

    // ROV Assistance Commands
    rROV_WinchSpeedCmd : REAL; // [m/min]

    // System Status
    bDP_Ready : BOOL;
    bCableLayingActive : BOOL;
    bTDM_Warning : BOOL; // Touch down point out of tolerance
    iErrorCode : INT;
END_VAR

VAR
    // PID Controllers for DP
    rKp_Surge : REAL := 15.0;
    rKi_Surge : REAL := 0.5;
    rKd_Surge : REAL := 5.0;
    rInt_Surge : REAL;

    rKp_Sway : REAL := 20.0;
    rKi_Sway : REAL := 0.8;
    rKd_Sway : REAL := 8.0;
    rInt_Sway : REAL;

    rKp_Yaw : REAL := 12.0;
    rKi_Yaw : REAL := 0.2;
    rKd_Yaw : REAL := 4.0;
    rInt_Yaw : REAL;
    rYawError : REAL;

    // Forces required
    rForceSurgeReq : REAL;
    rForceSwayReq : REAL;
    rMomentYawReq : REAL;

    // Tension cascade
    rTensionError : REAL;
    rTensionInt : REAL;
    rKp_Tension : REAL := 2.5;
    rKi_Tension : REAL := 0.1;

    // Environmental Feedforward
    rWindForceX : REAL;
    rWindForceY : REAL;

    // Internal flags
    bInitDone : BOOL := FALSE;
    tScanTime : TIME := T#10MS;
    rDt : REAL := 0.01;
END_VAR

// -----------------------------------------------------------------------------
// IMPLEMENTATION
// -----------------------------------------------------------------------------

IF NOT bEnableSys THEN
    rThruster1_PitchCmd := 0.0;
    rThruster2_PitchCmd := 0.0;
    rThruster3_PitchCmd := 0.0;
    rThruster4_PitchCmd := 0.0;
    rTensionerMotorTorqueCmd := 0.0;
    rCarouselDriveSpeedCmd := 0.0;
    bCarouselBrakeRelease := FALSE;
    bDP_Ready := FALSE;
    bCableLayingActive := FALSE;
    iErrorCode := 0;
    RETURN;
END_IF;

// 1. Dynamic Positioning (DP) - PID & Feedforward
// Calculate Yaw Error with shortest path
rYawError := rVesselHeadingRef - rVesselHeadingAct;
IF rYawError > 180.0 THEN
    rYawError := rYawError - 360.0;
ELSIF rYawError < -180.0 THEN
    rYawError := rYawError + 360.0;
END_IF;

// Integrators
rInt_Surge := rInt_Surge + (rPosErrorX * rDt);
rInt_Sway := rInt_Sway + (rPosErrorY * rDt);
rInt_Yaw := rInt_Yaw + (rYawError * rDt);

// Wind Feedforward (Simplified Drag Model)
rWindForceX := 0.5 * 1.225 * rWindSpeed * rWindSpeed * 500.0 * COS(rWindDir * 3.14159 / 180.0);
rWindForceY := 0.5 * 1.225 * rWindSpeed * rWindSpeed * 1200.0 * SIN(rWindDir * 3.14159 / 180.0);

// Total Required Forces & Moments
rForceSurgeReq := (rKp_Surge * rPosErrorX) + (rKi_Surge * rInt_Surge) - rWindForceX * 0.001; // kN
rForceSwayReq := (rKp_Sway * rPosErrorY) + (rKi_Sway * rInt_Sway) - rWindForceY * 0.001; // kN
rMomentYawReq := (rKp_Yaw * rYawError) + (rKi_Yaw * rInt_Yaw); // kNm

// Thruster Allocation (Simplified Pseudo-Inverse logic for 2 Bow Tunnels, 2 Stern Azimuths)
// Bow Tunnels primarily handle Sway and Yaw
rThruster1_PitchCmd := LIMIT(-100.0, (rForceSwayReq * 0.3 + rMomentYawReq * 0.01), 100.0);
rThruster2_PitchCmd := LIMIT(-100.0, (rForceSwayReq * 0.3 + rMomentYawReq * 0.01), 100.0);

// Stern Azimuths handle Surge, Sway, and Yaw
rThruster3_AzimuthAngleCmd := 45.0; // Fixed biased angle for active control
rThruster4_AzimuthAngleCmd := -45.0;

rThruster3_PitchCmd := LIMIT(-100.0, (rForceSurgeReq * 0.5 + rForceSwayReq * 0.2 - rMomentYawReq * 0.005), 100.0);
rThruster4_PitchCmd := LIMIT(-100.0, (rForceSurgeReq * 0.5 - rForceSwayReq * 0.2 + rMomentYawReq * 0.005), 100.0);

bDP_Ready := TRUE;

// 2. Cable Carousel & Tensioner Cascade Control
// Primary Loop: Payout Speed
// Secondary Loop: Tension control based on water depth and payout speed
rTensionError := rCableTensionSetpoint - rCableTensionAct;
rTensionInt := rTensionInt + (rTensionError * rDt);

IF rPayoutSpeedAct > 0.5 THEN
    bCarouselBrakeRelease := TRUE;
    // Tensioner Torque Command
    rTensionerMotorTorqueCmd := LIMIT(0.0, (rKp_Tension * rTensionError) + (rKi_Tension * rTensionInt) + (rPayoutSpeedRef * 2.0), 100.0);

    // Carousel matches payout speed to avoid slack
    rCarouselDriveSpeedCmd := rPayoutSpeedRef * 0.15; // Gear ratio assumed
    bCableLayingActive := TRUE;
ELSE
    bCarouselBrakeRelease := FALSE;
    rTensionerMotorTorqueCmd := LIMIT(0.0, (rKp_Tension * rTensionError), 100.0); // Hold tension
    rCarouselDriveSpeedCmd := 0.0;
    bCableLayingActive := FALSE;
END_IF;

// 3. Touch-Down Monitoring (TDM) ROV Assistance
// Maintain ROV distance from TDP based on depth and catenary equation approximation
IF rROV_DepthAct > (rWaterDepth - 10.0) THEN
    IF rROV_TDP_Distance > 25.0 THEN
        rROV_WinchSpeedCmd := 5.0; // Retrieve slightly
    ELSIF rROV_TDP_Distance < 15.0 THEN
        rROV_WinchSpeedCmd := -5.0; // Payout slightly
    ELSE
        rROV_WinchSpeedCmd := 0.0;
    END_IF;
ELSE
    rROV_WinchSpeedCmd := 0.0;
END_IF;

// TDM Warning Logic
IF (rROV_PitchAct > 15.0 OR rROV_PitchAct < -15.0) AND rWaterDepth > 50.0 THEN
    bTDM_Warning := TRUE;
    iErrorCode := 1001; // Suspicious TDP geometry
ELSE
    bTDM_Warning := FALSE;
    iErrorCode := 0;
END_IF;

END_FUNCTION_BLOCK
```

