FUNCTION_BLOCK FB_CryoPropellantLoad
VAR_INPUT
    bEnableFlow             : BOOL;     (* Main sequence enable command *)
    bEstop                  : BOOL;     (* Emergency Stop signal, fail safe *)
    rTankPressure           : REAL;     (* Current propellant tank pressure (kPa) *)
    rSubCoolTemp            : REAL;     (* Sub-cooled liquid temperature (K) *)
    rLineFlowRate           : REAL;     (* Cryogenic line flow rate (kg/s) *)
    rVentStackPressure      : REAL;     (* Vent stack pressure (kPa) *)
    bGeyserDetect           : BOOL;     (* Early anti-geyser detection sensor *)
    bVehicleReady           : BOOL;     (* Launch vehicle ready for propellant load *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Launch pad cryogenic system ready *)
    bFlowValveOpen          : BOOL;     (* Command to open main cryogenic flow valve *)
    rVentValvePos           : REAL;     (* Proportional vent valve position (0-100%) *)
    bGeyserSuppression      : BOOL;     (* Command to activate anti-geyser chilldown pumps *)
    bCriticalAlarm          : BOOL;     (* Critical fault alarm requiring immediate abort *)
    iCurrentState           : INT;      (* Current loading sequence state *)
END_VAR
VAR
    iState                  : INT := 0;
    tChilldownTimer         : TON;
    tStabilizationTimer     : TON;
    tGeyserSuppressionTimer : TON;
    rTargetTankPressure     : REAL := 310.5; (* Nominal pad pressure limit *)
    rTargetTempLimit        : REAL := 90.1;  (* Max allowable LOX/LH2 temp threshold *)
    rPressureError          : REAL;
    rKp                     : REAL := 0.45;
    rKi                     : REAL := 0.12;
    rIntegralSum            : REAL := 0.0;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEstop OR bCriticalAlarm THEN
    bFlowValveOpen := FALSE;
    bGeyserSuppression := FALSE;
    rVentValvePos := 100.0; (* Fail safe: open vent stack fully *)
    bSystemReady := FALSE;
    iState := 999; (* FAULT STATE *)
    iCurrentState := iState;
    RETURN;
END_IF;

(* Proportional-Integral Control for Vent Valve Position based on Tank Pressure *)
rPressureError := rTankPressure - rTargetTankPressure;
IF rPressureError > 0.0 THEN
    rIntegralSum := rIntegralSum + (rPressureError * 0.1); 
    IF rIntegralSum > 50.0 THEN rIntegralSum := 50.0; END_IF;
ELSE
    rIntegralSum := 0.0; (* Reset windup if pressure drops below target *)
END_IF;

rVentValvePos := (rKp * rPressureError) + (rKi * rIntegralSum);
IF rVentValvePos < 0.0 THEN rVentValvePos := 0.0; END_IF;
IF rVentValvePos > 100.0 THEN rVentValvePos := 100.0; END_IF;

(* Anti-Geyser active overriding control *)
IF bGeyserDetect AND iState > 0 AND iState < 999 THEN
    bGeyserSuppression := TRUE;
    tGeyserSuppressionTimer(IN := TRUE, PT := T#15S);
    IF tGeyserSuppressionTimer.Q THEN
        (* If geyser detection persists beyond timer, trigger critical alarm *)
        bCriticalAlarm := TRUE;
    END_IF;
ELSE
    bGeyserSuppression := FALSE;
    tGeyserSuppressionTimer(IN := FALSE);
END_IF;

(* === STATE MACHINE FOR CRYOGENIC LOADING === *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bFlowValveOpen := FALSE;
        IF bEnableFlow AND bVehicleReady AND rSubCoolTemp < rTargetTempLimit THEN
            iState := 10;
        END_IF;

    10: (* CHILLDOWN PHASE *)
        bSystemReady := TRUE;
        bFlowValveOpen := FALSE; (* Keep main valve closed, circulate for chilldown *)
        tChilldownTimer(IN := TRUE, PT := T#45S);
        IF tChilldownTimer.Q THEN
            tChilldownTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* SLOW FILL PHASE *)
        bFlowValveOpen := TRUE; (* Command main valve open at restricted rate via downstream control *)
        IF rLineFlowRate > 15.5 AND rTankPressure > 100.0 THEN
            iState := 30;
        END_IF;

    30: (* FAST FILL PHASE *)
        bFlowValveOpen := TRUE;
        tStabilizationTimer(IN := TRUE, PT := T#120S);
        IF tStabilizationTimer.Q AND rTankPressure >= (rTargetTankPressure * 0.95) THEN
            tStabilizationTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* TOPPING AND REPLENISH PHASE *)
        bFlowValveOpen := TRUE;
        (* Continuous topping until launch command overrides bEnableFlow *)
        IF NOT bEnableFlow THEN
            iState := 50;
        END_IF;

    50: (* SECURE SYSTEM *)
        bFlowValveOpen := FALSE;
        bSystemReady := FALSE;
        IF rLineFlowRate < 0.5 THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        (* Needs manual reset when bEstop is restored and Alarm cleared *)
        IF bEstop AND NOT bCriticalAlarm THEN
            iState := 0;
        END_IF;

END_CASE;

iCurrentState := iState;

END_FUNCTION_BLOCK
```

