FUNCTION_BLOCK FB_Terminal_Crane_AGV_Coordination
(*
    Complex STS Crane Sway Dampening and AGV Synchronization
    Handles non-linear sway reduction, trolley positioning, hoist control, and handoff synchronization with Automated Guided Vehicles.
*)
VAR_INPUT
    // Operator and Mode commands
    bEnableAuto           : BOOL;   (* Auto mode enable *)
    bEmergencyStopReq     : BOOL;   (* E-stop from operator *)

    // Crane Physical Sensors
    rTrolleyPos           : REAL;   (* Current trolley position [m] *)
    rTrolleySpeed         : REAL;   (* Current trolley speed [m/s] *)
    rHoistPos             : REAL;   (* Current hoist position [m] *)
    rSwayAngle            : REAL;   (* Spreader sway angle [rad] *)
    rWindSpeed            : REAL;   (* Environmental wind speed [m/s] *)
    bSpreaderLanded       : BOOL;   (* Spreader landed on container/AGV *)
    bTwistlocksEngaged    : BOOL;   (* Twistlock status *)

    // AGV Interface
    rAGV_TargetPos        : REAL;   (* Target position of AGV at interchange [m] *)
    rAGV_CurrentPos       : REAL;   (* Actual position of AGV [m] *)
    bAGV_InPosition       : BOOL;   (* AGV reporting ready for transfer *)
    bAGV_Locked           : BOOL;   (* AGV brakes applied *)
END_VAR

VAR_OUTPUT
    // Crane Drive Commands
    rTrolleyCommandSpeed  : REAL;   (* Speed setpoint for Trolley Drive [m/s] *)
    rHoistCommandSpeed    : REAL;   (* Speed setpoint for Hoist Drive [m/s] *)
    bTwistlockCommand     : BOOL;   (* Command to lock/unlock twistlocks *)

    // AGV and System Flags
    bAGV_MovePermit       : BOOL;   (* Permission for AGV to leave interchange *)
    bSystemFault          : BOOL;   (* General fault indicator *)
    iSystemState          : INT;    (* 0=IDLE, 1=MOVING_TO_SHIP, 2=PICKING, 3=MOVING_TO_AGV, 4=DROPPING, 5=ERROR *)
END_VAR

VAR
    // PID Parameters for Trolley
    rKp_Trolley           : REAL := 1.85;
    rKi_Trolley           : REAL := 0.25;
    rKd_Trolley           : REAL := 0.60;

    // State variables for Trolley PID
    rErrorTrolley         : REAL;
    rPrevErrorTrolley     : REAL;
    rIntegralTrolley      : REAL;
    rDerivativeTrolley    : REAL;
    rTargetTrolleyPos     : REAL;

    // Anti-sway Parameters
    rKp_Sway              : REAL := -3.50;
    rKd_Sway              : REAL := -1.20;
    rSwayDerivative       : REAL;
    rPrevSwayAngle        : REAL;

    // Timing and sequencing
    tonSettleTime         : TON;
    tonDropDelay          : TON;
    tonLockDelay          : TON;

    // Safety thresholds
    rMaxWindSpeed         : REAL := 22.0; (* m/s *)
    rMaxSwayTolerance     : REAL := 0.05; (* rad *)
    rMaxTrolleySpeed      : REAL := 3.0;  (* m/s *)
    rMaxHoistSpeed        : REAL := 1.5;  (* m/s *)
END_VAR

// -----------------------------------------------------------------------------
// Safety and Interlock Checks
// -----------------------------------------------------------------------------
IF bEmergencyStopReq OR (rWindSpeed > rMaxWindSpeed) THEN
    rTrolleyCommandSpeed := 0.0;
    rHoistCommandSpeed := 0.0;
    bSystemFault := TRUE;
    iSystemState := 5; // ERROR
    RETURN;
END_IF;

IF NOT bEnableAuto THEN
    iSystemState := 0; // IDLE
    rTrolleyCommandSpeed := 0.0;
    rHoistCommandSpeed := 0.0;
    bAGV_MovePermit := FALSE;
    RETURN;
END_IF;

// -----------------------------------------------------------------------------
// State Machine Implementation
// -----------------------------------------------------------------------------
CASE iSystemState OF

    0: // IDLE
        bAGV_MovePermit := FALSE;
        IF bEnableAuto AND NOT bSystemFault THEN
            rTargetTrolleyPos := 105.0; // Assume ship cell position for demo
            iSystemState := 1;
        END_IF;

    1: // MOVING_TO_SHIP
        // Trolley position PID calculation
        rErrorTrolley := rTargetTrolleyPos - rTrolleyPos;
        rIntegralTrolley := rIntegralTrolley + (rErrorTrolley * 0.01); // Assuming 10ms cycle
        rDerivativeTrolley := (rErrorTrolley - rPrevErrorTrolley) / 0.01;
        rPrevErrorTrolley := rErrorTrolley;

        // Anti-Sway calculation (State-feedback approximation)
        rSwayDerivative := (rSwayAngle - rPrevSwayAngle) / 0.01;
        rPrevSwayAngle := rSwayAngle;

        // Combined control law: Position tracking + Sway dampening
        rTrolleyCommandSpeed := (rKp_Trolley * rErrorTrolley) + 
                                (rKi_Trolley * rIntegralTrolley) + 
                                (rKd_Trolley * rDerivativeTrolley) +
                                (rKp_Sway * rSwayAngle) + 
                                (rKd_Sway * rSwayDerivative);

        // Saturation limits
        IF rTrolleyCommandSpeed > rMaxTrolleySpeed THEN rTrolleyCommandSpeed := rMaxTrolleySpeed; END_IF;
        IF rTrolleyCommandSpeed < -rMaxTrolleySpeed THEN rTrolleyCommandSpeed := -rMaxTrolleySpeed; END_IF;

        // Check if trolley reached target and sway is minimized
        IF ABS(rErrorTrolley) < 0.1 AND ABS(rSwayAngle) < rMaxSwayTolerance THEN
            tonSettleTime(IN:=TRUE, PT:=T#2S);
            IF tonSettleTime.Q THEN
                rTrolleyCommandSpeed := 0.0;
                iSystemState := 2;
                tonSettleTime(IN:=FALSE);
            END_IF;
        ELSE
            tonSettleTime(IN:=FALSE);
        END_IF;

    2: // PICKING
        // Lower hoist to container
        IF NOT bSpreaderLanded THEN
            rHoistCommandSpeed := -0.5; // Lowering speed
        ELSE
            rHoistCommandSpeed := 0.0;
            bTwistlockCommand := TRUE; // Engage twistlocks

            tonLockDelay(IN:=TRUE, PT:=T#1.5S);
            IF tonLockDelay.Q AND bTwistlocksEngaged THEN
                // Hoist up safely
                rHoistCommandSpeed := 1.0; 
                IF rHoistPos > 25.0 THEN // Safe clearance height
                    iSystemState := 3;
                    tonLockDelay(IN:=FALSE);
                END_IF;
            END_IF;
        END_IF;

    3: // MOVING_TO_AGV
        rTargetTrolleyPos := rAGV_TargetPos;

        // Re-calculate trolley control and sway dampening
        rErrorTrolley := rTargetTrolleyPos - rTrolleyPos;
        rIntegralTrolley := rIntegralTrolley + (rErrorTrolley * 0.01);
        rDerivativeTrolley := (rErrorTrolley - rPrevErrorTrolley) / 0.01;
        rPrevErrorTrolley := rErrorTrolley;

        rSwayDerivative := (rSwayAngle - rPrevSwayAngle) / 0.01;
        rPrevSwayAngle := rSwayAngle;

        rTrolleyCommandSpeed := (rKp_Trolley * rErrorTrolley) + 
                                (rKi_Trolley * rIntegralTrolley) + 
                                (rKd_Trolley * rDerivativeTrolley) +
                                (rKp_Sway * rSwayAngle) + 
                                (rKd_Sway * rSwayDerivative);

        // Clamp speed
        IF rTrolleyCommandSpeed > rMaxTrolleySpeed THEN rTrolleyCommandSpeed := rMaxTrolleySpeed; END_IF;
        IF rTrolleyCommandSpeed < -rMaxTrolleySpeed THEN rTrolleyCommandSpeed := -rMaxTrolleySpeed; END_IF;

        // Wait for AGV to be locked in position
        IF ABS(rErrorTrolley) < 0.1 AND ABS(rSwayAngle) < rMaxSwayTolerance AND bAGV_InPosition AND bAGV_Locked THEN
            tonSettleTime(IN:=TRUE, PT:=T#2S);
            IF tonSettleTime.Q THEN
                rTrolleyCommandSpeed := 0.0;
                iSystemState := 4;
                tonSettleTime(IN:=FALSE);
            END_IF;
        ELSE
            tonSettleTime(IN:=FALSE);
        END_IF;

    4: // DROPPING
        // Lower hoist to AGV
        IF NOT bSpreaderLanded THEN
            rHoistCommandSpeed := -0.3; // Slower drop for AGV safety
        ELSE
            rHoistCommandSpeed := 0.0;
            bTwistlockCommand := FALSE; // Disengage twistlocks

            tonDropDelay(IN:=TRUE, PT:=T#1.5S);
            IF tonDropDelay.Q AND NOT bTwistlocksEngaged THEN
                rHoistCommandSpeed := 1.0; // Hoist up
                IF rHoistPos > 25.0 THEN
                    bAGV_MovePermit := TRUE; // Release AGV
                    iSystemState := 1; // Loop back to ship
                    tonDropDelay(IN:=FALSE);
                END_IF;
            END_IF;
        END_IF;

    5: // ERROR STATE
        rTrolleyCommandSpeed := 0.0;
        rHoistCommandSpeed := 0.0;
        bAGV_MovePermit := FALSE;
        // Require manual reset of bEnableAuto to clear
        IF NOT bEnableAuto THEN
            bSystemFault := FALSE;
            iSystemState := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
