FUNCTION_BLOCK FB_CoilColorCoatingLineControl
(*
    =============================================================================
    Lumina AI Cloud Swarm - Elite Synthetic Data Architecture
    Domain: Coil Color Coating Line Control System
    Description: Advanced control algorithm integrating strip accumulator carriage 
                 tension, chemical coater roll speed ratio profiling, and catenary 
                 curing oven loop control.
    =============================================================================
*)
VAR_INPUT
    // Master Line Parameters
    rLineSpeedCmd        : REAL; (* Master line speed command [m/min] *)
    bSystemRun           : BOOL; (* Master Run Command *)
    bEmergencyStop       : BOOL; (* E-Stop, Active Low *)

    // Accumulator Carriage Variables
    rAccPosition         : REAL; (* Current carriage position [m] *)
    rAccMaxPosition      : REAL; (* Maximum carriage stroke [m] *)
    rEntryTensionFbk     : REAL; (* Entry side tension feedback [N] *)
    rTensionSetpoint     : REAL; (* Target accumulator tension [N] *)

    // Coater Variables
    rApplicatorRollSpeed : REAL; (* Feedback speed of applicator roll [m/min] *)
    rPickUpRollSpeed     : REAL; (* Feedback speed of pickup roll [m/min] *)
    rViscosityFbk        : REAL; (* Coating fluid viscosity [cP] *)
    rTargetCoatWeight    : REAL; (* Desired dry film thickness [microns] *)

    // Catenary Oven Variables
    rOvenTempZone1       : REAL; (* Temperature feedback Zone 1 [degC] *)
    rOvenTempZone2       : REAL; (* Temperature feedback Zone 2 [degC] *)
    rCatenaryDepthFbk    : REAL; (* Laser feedback of catenary lowest point [m] *)
    rCatenaryDepthSp     : REAL; (* Setpoint for catenary loop depth [m] *)
END_VAR

VAR_OUTPUT
    // Accumulator Outputs
    rAccWinchSpeedRef    : REAL; (* Reference to accumulator winch drive [rpm] *)
    rEntryBridleSpeedRef : REAL; (* Speed reference to entry bridle [m/min] *)
    bAccWarning          : BOOL; (* Carriage near limit warning *)

    // Coater Outputs
    rAppRollSpeedRef     : REAL; (* Applicator roll target speed [m/min] *)
    rPickUpRollSpeedRef  : REAL; (* Pickup roll target speed [m/min] *)
    rRatioAppToStrip     : REAL; (* Calculated ratio applicator/strip *)
    rRatioPickToApp      : REAL; (* Calculated ratio pickup/applicator *)

    // Oven Outputs
    rOvenFanSpeedRef     : REAL; (* Convection fan speed reference [%] *)
    rExitBridleSpeedRef  : REAL; (* Exit bridle master speed [m/min] *)
    bOvenTempAlarm       : BOOL; (* Oven temperature deviation alarm *)
END_VAR

VAR
    // Internal Control PID & States
    Kp_Tension           : REAL := 2.5;
    Ki_Tension           : REAL := 0.8;
    Kd_Tension           : REAL := 0.1;
    rTensionError        : REAL;
    rTensionInteg        : REAL;
    rTensionDeriv        : REAL;
    rPrevTensionError    : REAL;

    Kp_Catenary          : REAL := 5.0;
    Ki_Catenary          : REAL := 1.2;
    rCatenaryError       : REAL;
    rCatenaryInteg       : REAL;

    // Coater Profiling Profile
    rBaseRatio           : REAL := 1.2; 
    rViscosityComp       : REAL;

    // Timers
    TMR_AlarmDelay       : TON;
END_VAR

(* 
    =============================================================================
    1. ACCUMULATOR CARRIAGE & TENSION CONTROL
    =============================================================================
*)
IF NOT bEmergencyStop THEN
    // Reset Integrators
    rTensionInteg := 0.0;
    rCatenaryInteg := 0.0;
    rAccWinchSpeedRef := 0.0;
    rEntryBridleSpeedRef := 0.0;
ELSE
    // Calculate Tension Error
    rTensionError := rTensionSetpoint - rEntryTensionFbk;

    // Anti-windup integration
    IF (rTensionInteg < 1000.0) AND (rTensionInteg > -1000.0) THEN
        rTensionInteg := rTensionInteg + (rTensionError * 0.05); // Assume 50ms cycle
    END_IF;

    rTensionDeriv := (rTensionError - rPrevTensionError) / 0.05;
    rPrevTensionError := rTensionError;

    // Winch torque/speed correction based on tension PID
    rAccWinchSpeedRef := (Kp_Tension * rTensionError) + (Ki_Tension * rTensionInteg) + (Kd_Tension * rTensionDeriv);

    // Entry Bridle speed based on Line speed and accumulator fill status
    IF rAccPosition < (rAccMaxPosition * 0.1) THEN
        rEntryBridleSpeedRef := rLineSpeedCmd * 1.1; // Fill accumulator
        bAccWarning := TRUE;
    ELSIF rAccPosition > (rAccMaxPosition * 0.9) THEN
        rEntryBridleSpeedRef := rLineSpeedCmd * 0.9; // Empty accumulator
        bAccWarning := TRUE;
    ELSE
        rEntryBridleSpeedRef := rLineSpeedCmd;
        bAccWarning := FALSE;
    END_IF;

    (* 
        =============================================================================
        2. CHEMICAL COATER ROLL SPEED RATIO PROFILING
        =============================================================================
    *)
    // Compensate applicator ratio based on fluid viscosity changes
    // Nominal viscosity ~ 100 cP. If higher, increase ratio slightly to drag more paint
    rViscosityComp := (rViscosityFbk - 100.0) * 0.005;

    rRatioAppToStrip := rBaseRatio + rViscosityComp;
    rRatioPickToApp  := 0.8; // Forward roll coating typical pickup ratio

    rAppRollSpeedRef := rLineSpeedCmd * rRatioAppToStrip;
    rPickUpRollSpeedRef := rAppRollSpeedRef * rRatioPickToApp;

    (* 
        =============================================================================
        3. CATENARY CURING OVEN LOOP CONTROL
        =============================================================================
    *)
    // The Catenary depth is controlled by slightly trimming the exit bridle speed
    rCatenaryError := rCatenaryDepthSp - rCatenaryDepthFbk;

    rCatenaryInteg := rCatenaryInteg + (rCatenaryError * 0.05);

    // Exit Bridle Trim
    rExitBridleSpeedRef := rLineSpeedCmd + (Kp_Catenary * rCatenaryError) + (Ki_Catenary * rCatenaryInteg);

    // Oven temperature fan speed logic (simulate heat transfer adjustment)
    IF rOvenTempZone1 < 250.0 OR rOvenTempZone2 < 280.0 THEN
        rOvenFanSpeedRef := 95.0; // Max convection
    ELSE
        rOvenFanSpeedRef := 60.0; // Maintenance mode
    END_IF;

    // Alarm logic
    IF (ABS(rOvenTempZone2 - 280.0) > 15.0) THEN
        bOvenTempAlarm := TRUE;
    ELSE
        bOvenTempAlarm := FALSE;
    END_IF;

END_IF;

END_FUNCTION_BLOCK
