FUNCTION_BLOCK FB_TVAC_Control
TITLE = 'Spacecraft Thermal Vacuum Chamber Controller'
VERSION : '2.1'

VAR_INPUT
    bStartSequence : BOOL; // Initiate pump down and thermal cycle
    bEmergencyStop : BOOL; // Abort all operations, vent chamber
    rChamberPressure : REAL; // Current chamber pressure in Torr
    rShroudTemp1 : REAL; // Shroud Zone 1 temperature (K)
    rShroudTemp2 : REAL; // Shroud Zone 2 temperature (K)
    rPayloadTemp : REAL; // DUT temperature (K)
    rTargetVacuum : REAL := 1.0E-6; // Target high vacuum level (Torr)
    rTargetCryoTemp : REAL := 77.0; // Target shroud temperature (K)
    rTargetSolarFlux : REAL := 1361.0; // Target solar constant W/m2
END_VAR

VAR_OUTPUT
    bRoughingPumpCmd : BOOL;
    bTurboPump1Cmd : BOOL;
    bTurboPump2Cmd : BOOL;
    bCryopumpCmd : BOOL;
    bLN2SupplyValve : BOOL;
    bGN2VentValve : BOOL;
    rSolarLampIntensity : REAL; // 0.0 to 100.0 %
    bSystemReady : BOOL;
    iStateCode : INT;
END_VAR

VAR
    iStep : INT := 0;
    tonRoughing : TON;
    tonTurboSequence : TON;
    tonThermalSoak : TON;
    pidCryo1 : PID;
    pidCryo2 : PID;
    rLampRampRate : REAL := 0.5; // % per second
    rCurrentLampPower : REAL := 0.0;
    bVacuumAchieved : BOOL;
    bThermalStabilized : BOOL;
END_VAR

(* Main State Machine for TVAC Sequence *)
IF bEmergencyStop THEN
    iStep := 999;
END_IF;

CASE iStep OF
    0: (* Standby *)
        bRoughingPumpCmd := FALSE;
        bTurboPump1Cmd := FALSE;
        bTurboPump2Cmd := FALSE;
        bCryopumpCmd := FALSE;
        bLN2SupplyValve := FALSE;
        bGN2VentValve := FALSE;
        rSolarLampIntensity := 0.0;
        bSystemReady := TRUE;
        iStateCode := 0;

        IF bStartSequence THEN
            iStep := 10;
            bSystemReady := FALSE;
        END_IF;

    10: (* Roughing Phase *)
        iStateCode := 10;
        bRoughingPumpCmd := TRUE;
        IF rChamberPressure < 1.0E-2 THEN (* 10 milliTorr threshold *)
            iStep := 20;
        END_IF;

    20: (* High Vacuum Phase - Turbo Cascade *)
        iStateCode := 20;
        bTurboPump1Cmd := TRUE;
        tonTurboSequence(IN := TRUE, PT := T#30s);

        IF tonTurboSequence.Q THEN
            bTurboPump2Cmd := TRUE;
        END_IF;

        IF rChamberPressure < 1.0E-5 THEN
            bCryopumpCmd := TRUE;
        END_IF;

        IF rChamberPressure <= rTargetVacuum THEN
            bVacuumAchieved := TRUE;
            iStep := 30;
        END_IF;

    30: (* Thermal Cycle - LN2 Shroud Cooling & Solar Simulation *)
        iStateCode := 30;

        (* Cryogenic Shroud PID Control *)
        pidCryo1(
            EN := TRUE,
            SP := rTargetCryoTemp,
            PV := rShroudTemp1,
            KP := 2.5,
            TN := T#60s,
            TV := T#10s
        );
        pidCryo2(
            EN := TRUE,
            SP := rTargetCryoTemp,
            PV := rShroudTemp2,
            KP := 2.5,
            TN := T#60s,
            TV := T#10s
        );

        (* Bang-bang / PWM hybrid for LN2 Valves based on PID output *)
        IF (pidCryo1.Y > 50.0) OR (pidCryo2.Y > 50.0) THEN
            bLN2SupplyValve := TRUE;
            bGN2VentValve := TRUE;
        ELSE
            bLN2SupplyValve := FALSE;
            bGN2VentValve := FALSE;
        END_IF;

        (* Solar Simulator Dimming Control *)
        IF rPayloadTemp < 293.0 THEN
            rCurrentLampPower := rCurrentLampPower + rLampRampRate;
        ELSIF rPayloadTemp > 300.0 THEN
            rCurrentLampPower := rCurrentLampPower - rLampRampRate;
        END_IF;

        IF rCurrentLampPower > 100.0 THEN
            rCurrentLampPower := 100.0;
        ELSIF rCurrentLampPower < 0.0 THEN
            rCurrentLampPower := 0.0;
        END_IF;

        rSolarLampIntensity := rCurrentLampPower;

        IF ABS(rShroudTemp1 - rTargetCryoTemp) < 5.0 AND ABS(rPayloadTemp - 298.0) < 2.0 THEN
            tonThermalSoak(IN := TRUE, PT := T#2h);
        ELSE
            tonThermalSoak(IN := FALSE);
        END_IF;

        IF tonThermalSoak.Q THEN
            iStep := 40;
        END_IF;

    40: (* Sequence Complete *)
        iStateCode := 40;
        bSystemReady := TRUE;

    999: (* Emergency Abort *)
        iStateCode := 999;
        bRoughingPumpCmd := FALSE;
        bTurboPump1Cmd := FALSE;
        bTurboPump2Cmd := FALSE;
        bCryopumpCmd := FALSE;
        bLN2SupplyValve := FALSE;
        bGN2VentValve := TRUE;
        rSolarLampIntensity := 0.0;
        bSystemReady := FALSE;

END_CASE;

END_FUNCTION_BLOCK
