FUNCTION_BLOCK "HydroTurbine_M1"
VERSION : 0.1
   VAR_INPUT 
      start_cmd : Bool;
      stop_cmd : Bool;
      grid_voltage : Real;
      grid_freq : Real;
      gen_voltage : Real;
      gen_freq : Real;
      vibration_level : Real;
      vibration_limit : Real := 7.0;
      speed_setpoint : Real;
      actual_speed : Real;
      penstock_pressure : Real; // bar
      penstock_pressure_limit : Real := 15.0; // bar
   END_VAR

   VAR_OUTPUT 
      wicket_gate_pos : Real;
      breaker_close_cmd : Bool;
      alarm_vibration : Bool;
      alarm_water_hammer : Bool;
      turbine_running : Bool;
      emergency_shutdown : Bool;
   END_VAR

   VAR 
      pid_wicket : "PID_Compact";
      sync_ok : Bool;
      vibration_timer : TON;
      prev_pressure : Real;
      roc_pressure : Real;
      sample_timer : TON;
   END_VAR

BEGIN
    // Wicket Gate PID Control
    #pid_wicket(Setpoint := #speed_setpoint,
                Input := #actual_speed,
                Output => #wicket_gate_pos);

    // Bearing Vibration Monitoring
    #vibration_timer(IN := (#vibration_level > #vibration_limit), PT := T#2S);
    #alarm_vibration := #vibration_timer.Q;

    // Penstock Pressure & Water Hammer Protection (Rate of Change)
    #sample_timer(IN := NOT #sample_timer.Q, PT := T#100MS);
    IF #sample_timer.Q THEN
        #roc_pressure := (#penstock_pressure - #prev_pressure) / 0.1; // bar/s
        #prev_pressure := #penstock_pressure;
    END_IF;

    #alarm_water_hammer := (#penstock_pressure > #penstock_pressure_limit) OR (#roc_pressure > 5.0);

    // Grid Synchronization
    #sync_ok := (ABS(#grid_voltage - #gen_voltage) < 5.0) AND (ABS(#grid_freq - #gen_freq) < 0.1);

    // Start/Stop & Emergency Logic
    #emergency_shutdown := #alarm_vibration OR #alarm_water_hammer;
    IF #emergency_shutdown THEN
        #turbine_running := FALSE;
    ELSIF #start_cmd THEN
        #turbine_running := TRUE;
    ELSIF #stop_cmd THEN
        #turbine_running := FALSE;
    END_IF;

    #breaker_close_cmd := #turbine_running AND #sync_ok AND NOT #emergency_shutdown;
END_FUNCTION_BLOCK
