FUNCTION_BLOCK FB_CheeseVatControl_Extended
VAR_INPUT
    bStartProcess : BOOL; // Start the vat processing cycle
    bEmergencyStop : BOOL; // Emergency stop override
    bAcknowledgeAlarm : BOOL; // Acknowledge active alarms
    rVatTemperature_C : REAL; // Current temperature from RTD
    rAgitatorTorque_Nm : REAL; // Current torque from agitator drive
    rLevelSensor_m : REAL; // Level of milk/whey in vat
    rTargetPH : REAL; // Target pH for coagulation
    rCurrentPH : REAL; // Current pH reading
    rCuttingGridSpeed_Req : REAL; // Requested cutting grid kinematics speed
    rWheyDrainSetPoint_m : REAL; // Setpoint for whey drainage
END_VAR

VAR_OUTPUT
    bHeatingValve : BOOL; // Control for heating jacket valve
    bCoolingValve : BOOL; // Control for cooling jacket valve
    rAgitatorSpeed_RPM : REAL; // Speed setpoint for agitator
    bCuttingGridActivate : BOOL; // Activate the wire cutting grid
    bWheyDrainValve : BOOL; // Open the whey drainage valve
    bCurdPumpActivate : BOOL; // Activate pump for curd transfer
    eCurrentState : INT; // State machine output
    bProcessComplete : BOOL; // Indicates batch is finished
    bAlarm : BOOL; // General alarm flag
    sAlarmMessage : STRING[50]; // Detailed alarm message
END_VAR

VAR
    Step : INT := 0; // State machine step
    tTimer : TON; // Process timer
    tCoagulationTimer : TON; // Timer for coagulation max time
    rTargetTemp : REAL := 32.0; // Coagulation temperature
    rTorqueLimit : REAL := 150.0; // Max torque during stirring
    rCutSpeed : REAL := 5.0; // Grid cutting speed
    rAgitateSpeed_Slow : REAL := 10.0; // Slow agitation speed
    rAgitateSpeed_Fast : REAL := 25.0; // Fast agitation speed

    // Internal flags
    bCoagulated : BOOL := FALSE;
    bWheyDrained : BOOL := FALSE;
    bCuttingComplete : BOOL := FALSE;

    // Limits and tolerances
    rTempTolerance : REAL := 0.5;
    tMaxCoagulationTime : TIME := T#120M;
END_VAR

// Alarm handling and emergency stop
IF bEmergencyStop THEN
    bHeatingValve := FALSE;
    bCoolingValve := FALSE;
    rAgitatorSpeed_RPM := 0.0;
    bCuttingGridActivate := FALSE;
    bWheyDrainValve := FALSE;
    bCurdPumpActivate := FALSE;
    bAlarm := TRUE;
    sAlarmMessage := 'EMERGENCY STOP ACTIVATED';
    Step := 999;
    RETURN;
END_IF;

// Main State Machine
CASE Step OF
    0: // Idle state
        bProcessComplete := FALSE;
        bAlarm := FALSE;
        sAlarmMessage := '';
        IF bStartProcess THEN
            Step := 10;
        END_IF;

    10: // Fill and Heat to Target Temperature
        rAgitatorSpeed_RPM := rAgitateSpeed_Slow;
        IF rVatTemperature_C < (rTargetTemp - rTempTolerance) THEN
            bHeatingValve := TRUE;
            bCoolingValve := FALSE;
        ELSIF rVatTemperature_C > (rTargetTemp + rTempTolerance) THEN
            bHeatingValve := FALSE;
            bCoolingValve := TRUE;
        ELSE
            bHeatingValve := FALSE;
            bCoolingValve := FALSE;
            Step := 20; // Reached temperature
        END_IF;

    20: // Coagulation Wait (pH drop monitoring)
        rAgitatorSpeed_RPM := 0.0; // Stop agitation to allow curd to set
        tCoagulationTimer(IN:=TRUE, PT:=tMaxCoagulationTime);

        IF rCurrentPH <= rTargetPH THEN
            bCoagulated := TRUE;
            tCoagulationTimer(IN:=FALSE);
            tTimer(IN:=FALSE); // Reset step timer
            Step := 30;
        ELSIF tCoagulationTimer.Q THEN
            // Timeout reaching target pH
            bAlarm := TRUE;
            sAlarmMessage := 'COAGULATION TIMEOUT';
            tCoagulationTimer(IN:=FALSE);
            Step := 999;
        END_IF;

    30: // Cutting the Curd with Grid Kinematics
        bCuttingGridActivate := TRUE;
        // Assume cutting speed is managed by an external drive using rCutSpeed
        tTimer(IN:=TRUE, PT:=T#5M);
        IF tTimer.Q THEN
            bCuttingGridActivate := FALSE;
            bCuttingComplete := TRUE;
            tTimer(IN:=FALSE);
            Step := 40;
        END_IF;

    40: // Healing and Stirring (Syneresis)
        rAgitatorSpeed_RPM := rAgitateSpeed_Fast;
        tTimer(IN:=TRUE, PT:=T#20M);

        // Dynamic Torque monitoring to prevent curd damage
        IF rAgitatorTorque_Nm > rTorqueLimit THEN
            rAgitatorSpeed_RPM := rAgitateSpeed_Slow; // Reduce speed to lower torque
        ELSIF rAgitatorTorque_Nm < (rTorqueLimit * 0.8) THEN
            rAgitatorSpeed_RPM := rAgitateSpeed_Fast; // Restore speed if torque is safe
        END_IF;

        IF tTimer.Q THEN
            tTimer(IN:=FALSE);
            Step := 50;
        END_IF;

    50: // Whey Drainage Sequencing
        rAgitatorSpeed_RPM := rAgitateSpeed_Slow; // Keep curd suspended slightly
        bWheyDrainValve := TRUE;
        IF rLevelSensor_m <= rWheyDrainSetPoint_m THEN // Drainage complete threshold reached
            bWheyDrainValve := FALSE;
            bWheyDrained := TRUE;
            Step := 60;
        END_IF;

    60: // Curd Transfer via Pump
        bCurdPumpActivate := TRUE;
        rAgitatorSpeed_RPM := rAgitateSpeed_Fast; // Keep curd moving into the pump intake
        IF rLevelSensor_m <= 0.05 THEN // Vat is considered empty
            bCurdPumpActivate := FALSE;
            rAgitatorSpeed_RPM := 0.0;
            Step := 70;
        END_IF;

    70: // Process Complete
        bProcessComplete := TRUE;
        IF NOT bStartProcess THEN
            Step := 0; // Reset for next batch
        END_IF;

    999: // Error State - requires manual intervention
        bHeatingValve := FALSE;
        bCoolingValve := FALSE;
        rAgitatorSpeed_RPM := 0.0;
        bCuttingGridActivate := FALSE;
        bWheyDrainValve := FALSE;
        bCurdPumpActivate := FALSE;

        // Wait for operator acknowledgment to reset
        IF bAcknowledgeAlarm AND NOT bEmergencyStop THEN
            bAlarm := FALSE;
            sAlarmMessage := '';
            Step := 0;
        END_IF;
END_CASE;

eCurrentState := Step;
END_FUNCTION_BLOCK
