    rActualTension : REAL; // Measured tension from dancer/load cell

    // Spark Tester Inputs
    bSparkFaultDetected : BOOL; // High voltage spark test failure
    rFaultDistance : REAL; // Current length measurement at spark location
END_VAR

VAR_OUTPUT
    // Drive Commands
    rExtruderSpeedCmd : REAL; // Extruder screw speed command (RPM)
    rCapstan1SpeedCmd : REAL; // Speed command for capstan 1 (m/min)
    rCapstan2SpeedCmd : REAL; // Speed command for capstan 2 (m/min)

    // Heating/Cooling Commands
    rZone1Power : REAL; // Heating power output 0-100%
    rZone2Power : REAL; // Heating power output 0-100%
    rZone3Power : REAL; // Heating power output 0-100%
    rCoolingValveCmd : REAL; // Cooling valve open 0-100%

    // System Status
    bProcessRunning : BOOL;
    bTensionOk : BOOL;
    bAlarmActive : BOOL;
    iSparkFaultCount : INT;
    rLastFaultLocation : REAL;
END_VAR

VAR
    // PID Controllers for Tension and Temp
    fbTensionPID : FB_PID_Controller;
    fbZone1PID : FB_PID_Controller;
    fbZone2PID : FB_PID_Controller;
    fbZone3PID : FB_PID_Controller;

    // State machine
    eState : INT := 0; // 0=Stop, 1=RampUp, 2=Run, 3=Fault, 4=Stopping

    // Timers
    tSparkDebounce : TON;
    tRampTimer : TON;

    // Internal calculations
    rSpeedRamp : REAL := 0.0;
    rTensionTrim : REAL := 0.0;

    // Target temps for XLPE
    rZ1Set : REAL := 180.0;
    rZ2Set : REAL := 195.0;
    rZ3Set : REAL := 210.0;
END_VAR

// Constants
VAR CONSTANT
    MAX_SPEED : REAL := 150.0;
    RAMP_RATE : REAL := 1.5; // m/min per second
END_VAR

// Emergency Stop Handling
IF bEmergencyStop THEN
    eState := 3; // Fault state
    rExtruderSpeedCmd := 0.0;
    rCapstan1SpeedCmd := 0.0;
    rCapstan2SpeedCmd := 0.0;
    rZone1Power := 0.0;
    rZone2Power := 0.0;
    rZone3Power := 0.0;
    rCoolingValveCmd := 100.0; // Max cooling on estop
    bProcessRunning := FALSE;
    bAlarmActive := TRUE;
    RETURN;
END_IF;

// Spark Fault Tracking
tSparkDebounce(IN:=bSparkFaultDetected, PT:=T#100MS);
IF tSparkDebounce.Q THEN
    iSparkFaultCount := iSparkFaultCount + 1;
    rLastFaultLocation := rFaultDistance;
    bAlarmActive := TRUE;
END_IF;

// Main State Machine
CASE eState OF
    0: // Stopped
        bProcessRunning := FALSE;
        rSpeedRamp := 0.0;
        IF bStartProcess AND NOT bAlarmActive THEN
            eState := 1;
        END_IF;

    1: // Ramp Up
        bProcessRunning := TRUE;
        rSpeedRamp := rSpeedRamp + (RAMP_RATE * 0.01); // Assuming 10ms task
        IF rSpeedRamp >= rLineSpeedSetpoint THEN
            rSpeedRamp := rLineSpeedSetpoint;
            eState := 2;
        END_IF;

    2: // Running
        rSpeedRamp := rLineSpeedSetpoint;
        IF NOT bStartProcess THEN
            eState := 4; // Stopping
        END_IF;

    3: // Fault
        // Needs manual reset to return to 0

    4: // Stopping
        rSpeedRamp := rSpeedRamp - (RAMP_RATE * 0.01);
        IF rSpeedRamp <= 0.0 THEN
            rSpeedRamp := 0.0;
            eState := 0;
        END_IF;
END_CASE;

// Temperature Control (Curing Tube)
// In a real system these would call PID FB instances
fbZone1PID(rSetpoint:=rZ1Set, rActual:=rZone1Temp, rOutput=>rZone1Power);
fbZone2PID(rSetpoint:=rZ2Set, rActual:=rZone2Temp, rOutput=>rZone2Power);
fbZone3PID(rSetpoint:=rZ3Set, rActual:=rZone3Temp, rOutput=>rZone3Power);

// Tension Synchronization
// Master capstan follows line speed, slave is trimmed by tension PID
rCapstan2SpeedCmd := rSpeedRamp; // Master

fbTensionPID(
    rSetpoint := rTargetTension, 
    rActual := rActualTension, 
    rOutput => rTensionTrim);

// Apply tension trim to capstan 1 (Slave)
IF bProcessRunning THEN
    rCapstan1SpeedCmd := rSpeedRamp + rTensionTrim;
    bTensionOk := (ABS(rTargetTension - rActualTension) < 5.0);
ELSE
    rCapstan1SpeedCmd := 0.0;
    bTensionOk := FALSE;
END_IF;

// Basic Extruder Control linked to line speed
rExtruderSpeedCmd := (rSpeedRamp / MAX_SPEED) * 100.0; 

END_FUNCTION_BLOCK
