FUNCTION_BLOCK FB_WEC_PointAbsorber
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (E-Stop loop) *)
    rWaveElevation          : REAL;     (* Measured wave surface elevation [m] from ADCP/LiDAR *)
    rFloatPosition          : REAL;     (* Measured float vertical position [m] *)
    rFloatVelocity          : REAL;     (* Measured float vertical velocity [m/s] *)
    rPTOForceFeedback       : REAL;     (* Feedback from Power Take-Off (PTO) linear generator [N] *)
    rGridVoltage            : REAL;     (* Local AC bus grid voltage [V] *)
    bStormCondition         : BOOL;     (* External weather trigger for survival mode *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready status *)
    rPTOForceCommand        : REAL;     (* Optimal commanded damping force to PTO [N] *)
    bStormSubmergeMode      : BOOL;     (* Command to active buoyancy control to submerge WEC *)
    bGridSyncOK             : BOOL;     (* Grid synchronization interlock *)
    bAlarm                  : BOOL;     (* Fault alarm output *)
    iStateOut               : INT;      (* Current state machine step for HMI *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tStormTimer             : TON;
    tDampingTimer           : TON;
    rFilteredVelocity       : REAL := 0.0;
    rOptimalDamping         : REAL := 25000.0; (* Base damping coefficient [Ns/m] *)
    rResonancePhaseError    : REAL := 0.0;
    rLatchThreshold         : REAL := 0.05;    (* Latching velocity threshold [m/s] *)
    rPeakForceLimit         : REAL := 500000.0;(* Safety limit [N] *)

    (* Filter variables *)
    rAlpha                  : REAL := 0.1;     (* Low pass filter coefficient for velocity *)
END_VAR

(* === MAIN LOGIC === *)
(* Multi-layered safety interlock *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rPTOForceCommand := 0.0;
    bStormSubmergeMode := FALSE;
    bAlarm := TRUE;
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* First-order low pass filter on float velocity to remove high-frequency sensor noise *)
rFilteredVelocity := rAlpha * rFloatVelocity + (1.0 - rAlpha) * rFilteredVelocity;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        rPTOForceCommand := 0.0;
        bStormSubmergeMode := FALSE;
        bGridSyncOK := FALSE;
        bSystemReady := TRUE;
        bAlarm := FALSE;

        IF bEnable AND (rGridVoltage > 380.0) AND (rGridVoltage < 420.0) THEN
            iState := 10;
        END_IF;

    10: (* GRID SYNC & WARMUP *)
        bGridSyncOK := TRUE;
        tDampingTimer(IN := TRUE, PT := T#2S);
        IF tDampingTimer.Q THEN
            tDampingTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* NORMAL OPERATION - LATCHING CONTROL & RESONANCE TUNING *)
        (* Phase control: Latching logic when velocity is near zero *)
        IF ABS(rFilteredVelocity) < rLatchThreshold THEN
            (* Lock the float in place to build excitation force *)
            rPTOForceCommand := rPeakForceLimit;
        ELSE
            (* Release and apply optimal reactive damping for power extraction *)
            rPTOForceCommand := -rOptimalDamping * rFilteredVelocity;
        END_IF;

        (* Force limit check *)
        IF rPTOForceCommand > rPeakForceLimit THEN
            rPTOForceCommand := rPeakForceLimit;
        ELSIF rPTOForceCommand < -rPeakForceLimit THEN
            rPTOForceCommand := -rPeakForceLimit;
        END_IF;

        (* Check storm conditions *)
        IF bStormCondition THEN
            iState := 30;
        END_IF;

        (* Normal shutdown *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* SURVIVAL MODE - ACTIVE SUBMERGENCE *)
        (* Disengage PTO, trigger buoyancy modification *)
        rPTOForceCommand := 0.0;
        bStormSubmergeMode := TRUE;
        bGridSyncOK := FALSE;

        tStormTimer(IN := TRUE, PT := T#60S); (* Wait for storm to pass confirmation *)

        IF NOT bStormCondition AND tStormTimer.Q THEN
            tStormTimer(IN := FALSE);
            bStormSubmergeMode := FALSE;
            iState := 0;
        ELSIF NOT bStormCondition THEN
            (* Timer still ticking, reset if storm condition returns quickly *)
        ELSE
            tStormTimer(IN := FALSE); (* Storm is active, reset timer *)
        END_IF;

    999: (* FAULT STATE *)
        (* Requires E-Stop reset and enable toggle *)
        IF bEmergencyStop AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* HMI Output mapping *)
iStateOut := iState;

END_FUNCTION_BLOCK
