FUNCTION_BLOCK FB_MoldOscillator_AdvCtrl
VAR_INPUT
    (* Required: at least 4 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal for the oscillator module *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal; MUST BE TRUE TO RUN *)
    rCastingSpeedAct        : REAL;     (* Actual measured casting speed of the strand (m/min) *)
    rMoldFrictionAct        : REAL;     (* Measured hydraulic pressure differential converted to friction (kN) *)
    rTargetStroke           : REAL;     (* Oscillation peak-to-peak stroke length (mm) *)
    rTargetFreq             : REAL;     (* Target oscillation frequency (Hz) or computed from speed *)
    bNonSinusoidalMode      : BOOL;     (* Enable non-sinusoidal (triangular/skewed) waveform *)
    rWaveformSkewFactor     : REAL;     (* Skew factor for negative strip time mapping (0.0 to 1.0) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3 outputs with types and comments *)
    bSystemReady            : BOOL;     (* Oscillator ready status and hydraulic pressure OK *)
    rValveDriveCmd          : REAL;     (* Analog control signal to proportional servo valve (+/- 10V) *)
    bBreakoutAlarm          : BOOL;     (* Imminent breakout predicted based on excessive friction *)
    rNegativeStripTime      : REAL;     (* Calculated Negative Strip Time (NST) in seconds *)
    rNegativeStripRatio     : REAL;     (* Calculated Negative Strip Ratio (%) *)
END_VAR
VAR
    (* Internal state variables and processing matrices *)
    iState                  : INT := 0; 
    tCycleTimer             : TON;
    tBreakoutDebounce       : TON;
    rPhaseAngle             : REAL := 0.0;
    rOmega                  : REAL := 0.0;
    rAmplitude              : REAL := 0.0;
    rVelocityMold           : REAL := 0.0;
    rVelocityStrand         : REAL := 0.0;
    rCycleTimeSec           : REAL := 0.005; (* Assuming 5ms PLC cycle time *)
    rFrictionFilter         : REAL := 0.0;
    rFrictionLimitDyn       : REAL := 0.0;
    rBreakoutFrictionThreshold : REAL := 25.0; (* Base threshold in kN *)

    (* Math constants *)
    PI                      : REAL := 3.14159265359;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency stop check - Highest Priority Interlock *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bBreakoutAlarm := FALSE;
    rValveDriveCmd := 0.0;
    iState := 99; (* FAULT STATE *)
    RETURN;
END_IF;

(* Convert casting speed from m/min to mm/s for synchronized physics calculations *)
rVelocityStrand := (rCastingSpeedAct * 1000.0) / 60.0;

(* Calculate Dynamic Friction Limit dependent on speed *)
rFrictionLimitDyn := rBreakoutFrictionThreshold + (rVelocityStrand * 0.15);

(* Simple Low-Pass Filter on Friction *)
rFrictionFilter := rFrictionFilter + 0.1 * (rMoldFrictionAct - rFrictionFilter);

CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rValveDriveCmd := 0.0;
        IF bEnable AND rCastingSpeedAct > 0.1 THEN
            iState := 10;
        END_IF;

    10: (* RAMP_UP / INIT *)
        (* Calculate initial waveform parameters *)
        rAmplitude := rTargetStroke / 2.0;
        rOmega := 2.0 * PI * rTargetFreq;
        rPhaseAngle := 0.0;
        iState := 20;

    20: (* RUNNING SYNCHRONIZED *)
        bSystemReady := TRUE;

        (* Advance Phase Angle *)
        rPhaseAngle := rPhaseAngle + (rOmega * rCycleTimeSec);
        IF rPhaseAngle >= (2.0 * PI) THEN
            rPhaseAngle := rPhaseAngle - (2.0 * PI);
        END_IF;

        (* Waveform Generation *)
        IF bNonSinusoidalMode THEN
            (* Non-Sinusoidal Skewed Profile for advanced metallurgical strip *)
            IF rPhaseAngle < (PI + (rWaveformSkewFactor * PI)) THEN
                rVelocityMold := rAmplitude * rOmega * COS(rPhaseAngle * (1.0 - (rWaveformSkewFactor * 0.5)));
            ELSE
                rVelocityMold := rAmplitude * rOmega * COS(rPhaseAngle * (1.0 + (rWaveformSkewFactor * 0.5)));
            END_IF;
        ELSE
            (* Standard Sinusoidal Oscillator *)
            rVelocityMold := rAmplitude * rOmega * COS(rPhaseAngle);
        END_IF;

        (* Map to Valve Drive Cmd with simulated PID Feed-Forward *)
        rValveDriveCmd := rVelocityMold * 0.05; 

        (* Negative Strip Time (NST) and Ratio (NSR) Calculus *)
        IF rVelocityStrand > 0.0 THEN
            (* NST is the time where mold moves downward faster than the strand *)
            (* Formula: NST = (1 / Freq) * (1 / PI) * arccos( Vc / (PI * Freq * Stroke) ) *)
            IF (PI * rTargetFreq * rTargetStroke) > rVelocityStrand THEN
                rNegativeStripTime := (1.0 / (PI * rTargetFreq)) * ACOS(rVelocityStrand / (PI * rTargetFreq * rTargetStroke));
                rNegativeStripRatio := (rNegativeStripTime * rTargetFreq) * 100.0;
            ELSE
                rNegativeStripTime := 0.0;
                rNegativeStripRatio := 0.0;
            END_IF;
        END_IF;

        (* Friction & Breakout Monitoring Sub-Routine *)
        IF rFrictionFilter > rFrictionLimitDyn THEN
            tBreakoutDebounce(IN := TRUE, PT := T#50MS);
            IF tBreakoutDebounce.Q THEN
                bBreakoutAlarm := TRUE;
                iState := 99; (* GO TO FAULT TO PROTECT MACHINE *)
            END_IF;
        ELSE
            tBreakoutDebounce(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rValveDriveCmd := 0.0; (* Null position for servo spool *)
        IF NOT bBreakoutAlarm AND bEnable AND bEmergencyStop THEN
            iState := 0; (* Reset sequence *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
