FUNCTION_BLOCK FB_DeepSeaHyperbaricSystem
VAR_INPUT
    bEnableSystem          : BOOL;  (* System enable switch from master control panel *)
    bEmergStop             : BOOL;  (* Hardwired SIL3 E-Stop relay status, normally true *)
    rChamberPressure       : REAL;  (* Current chamber pressure in Bar *)
    rHeO2PartialPress      : REAL;  (* Mixed gas Helium/Oxygen partial pressure ratio *)
    rChamberTemp           : REAL;  (* Internal chamber temperature in degrees Celsius *)
    rCO2LevelPPM           : REAL;  (* Carbon Dioxide concentration in Parts Per Million *)
    bScrubberFault         : BOOL;  (* Primary CO2 scrubber operational fault status *)
    rCompressRateSetpt     : REAL;  (* Commanded adiabatic compression rate in Bar/min *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;  (* Indicates all safety interlocks are cleared and ready *)
    rHeO2ValveCmd          : REAL;  (* 0-100% command for HeO2 mix cascade valve *)
    bBypassScrubberCmd     : BOOL;  (* Engage emergency secondary scrubber loop bypass *)
    rTempControlCmd        : REAL;  (* Chiller/Heater demand for thermal spike mitigation (-100 to 100%) *)
    bCriticalAlarm         : BOOL;  (* Critical life-safety alarm active *)
    iStateCode             : INT;   (* Current active state machine phase code *)
END_VAR
VAR
    iMainState             : INT := 0; (* Main control sequence state *)
    rFilteredCO2           : REAL := 0.0; (* First-order low pass filtered CO2 level *)
    rFilteredTemp          : REAL := 0.0; (* Filtered chamber temperature *)
    rTempDeriv             : REAL := 0.0; (* Derivative of temperature for thermal spike detection *)
    rPrevTemp              : REAL := 0.0; (* Previous scan temperature for derivative calculation *)
    tAdiabaticTimer        : TON; (* Timer for adiabatic compression profile tracking *)
    tBypassDelay           : TON; (* Debounce timer for scrubber bypass engagement *)
    rThermalPID_Integral   : REAL := 0.0; (* PID Integral term accumulator *)
    rThermalPID_PrevError  : REAL := 0.0; (* PID Previous error *)
    rHeO2Error             : REAL := 0.0; (* Mix error *)
    bCompressionActive     : BOOL := FALSE;
END_VAR
VAR CONSTANT
    rCO2_MAX_LIMIT_PPM     : REAL := 5000.0; (* Critical CO2 threshold *)
    rCO2_FILTER_ALPHA      : REAL := 0.1; (* Low pass filter coefficient *)
    rTEMP_SPIKE_THRESH     : REAL := 2.5; (* Deg C per scan limit for adiabatic spikes *)
    rHeO2_TARGET           : REAL := 0.12; (* Target He/O2 ratio for saturation depth *)
    rKp_Thermal            : REAL := 2.5; (* Thermal PID Proportional Gain *)
    rKi_Thermal            : REAL := 0.1; (* Thermal PID Integral Gain *)
    rKd_Thermal            : REAL := 0.5; (* Thermal PID Derivative Gain *)
END_VAR

(* === SENSOR NOISE FILTERING & SIGNAL CONDITIONING === *)
(* First order discrete low-pass filter for CO2 sensor *)
rFilteredCO2 := (rCO2_FILTER_ALPHA * rCO2LevelPPM) + ((1.0 - rCO2_FILTER_ALPHA) * rFilteredCO2);

(* Temperature filtering and rate-of-change (derivative) calculation *)
rFilteredTemp := (0.2 * rChamberTemp) + (0.8 * rFilteredTemp);
rTempDeriv := rFilteredTemp - rPrevTemp;
rPrevTemp := rFilteredTemp;

(* === MULTI-LAYERED SAFETY INTERLOCKS === *)
IF NOT bEmergStop THEN
    (* SIL3 E-Stop breaks all operations *)
    bSystemReady := FALSE;
    rHeO2ValveCmd := 0.0;
    rTempControlCmd := 0.0;
    bBypassScrubberCmd := TRUE; (* Fail-safe to redundant scrubber *)
    bCriticalAlarm := TRUE;
    iMainState := 999; (* E-STOP STATE *)
    iStateCode := iMainState;
    RETURN;
END_IF;

(* Hypercapnia CO2 Scrubber Interlock *)
IF rFilteredCO2 > rCO2_MAX_LIMIT_PPM OR bScrubberFault THEN
    tBypassDelay(IN := TRUE, PT := T#2S);
    IF tBypassDelay.Q THEN
        bBypassScrubberCmd := TRUE;
        bCriticalAlarm := TRUE;
    END_IF;
ELSE
    tBypassDelay(IN := FALSE);
    bBypassScrubberCmd := FALSE;
END_IF;

(* === MAIN CASCADE & COMPRESSION STATE MACHINE === *)
CASE iMainState OF
    0: (* SYSTEM INITIALIZATION & DIAGNOSTICS *)
        bSystemReady := FALSE;
        rHeO2ValveCmd := 0.0;
        rTempControlCmd := 0.0;
        bCompressionActive := FALSE;
        IF bEnableSystem AND NOT bCriticalAlarm THEN
            iMainState := 10;
        END_IF;

    10: (* STANDBY / LIFE SUPPORT MONITORING *)
        bSystemReady := TRUE;

        (* Maintain steady-state temperature (22 C target) *)
        rHeO2Error := rHeO2_TARGET - rHeO2PartialPress;
        rHeO2ValveCmd := LIMIT(0.0, rHeO2Error * 50.0, 100.0);

        IF rCompressRateSetpt > 0.0 THEN
            iMainState := 20;
        END_IF;

    20: (* RAPID ADIABATIC COMPRESSION PHASE *)
        bCompressionActive := TRUE;
        bSystemReady := TRUE;

        (* Advanced PID Thermal Spike Mitigation during compression *)
        rThermalPID_PrevError := 22.0 - rFilteredTemp; (* Assuming 22C setpoint *)
        rThermalPID_Integral := rThermalPID_Integral + (rThermalPID_PrevError * 0.1); (* 100ms sample approx *)

        (* Anti-windup clamping *)
        rThermalPID_Integral := LIMIT(-50.0, rThermalPID_Integral, 50.0);

        (* Calculate PID Output with derivative kick suppression from raw rate *)
        rTempControlCmd := (rKp_Thermal * rThermalPID_PrevError) + (rKi_Thermal * rThermalPID_Integral) - (rKd_Thermal * rTempDeriv);
        rTempControlCmd := LIMIT(-100.0, rTempControlCmd, 100.0);

        (* HeO2 Cascading Profile - Dynamic partial pressure tracking based on depth (pressure) *)
        rHeO2Error := (rHeO2_TARGET * (rChamberPressure / 10.0)) - rHeO2PartialPress;
        rHeO2ValveCmd := LIMIT(0.0, rHeO2Error * 100.0, 100.0);

        IF rCompressRateSetpt <= 0.0 THEN
            bCompressionActive := FALSE;
            iMainState := 10;
        END_IF;

    999: (* FAULT / E-STOP *)
        bSystemReady := FALSE;
        IF bEmergStop AND NOT bCriticalAlarm THEN
            iMainState := 0; (* Reset sequence once faults clear *)
        END_IF;

    ELSE
        iMainState := 0; (* Fallback *)
END_CASE;

iStateCode := iMainState;

END_FUNCTION_BLOCK
