FUNCTION_BLOCK FB_SupercriticalCO2Extraction
VAR_INPUT
    bEnable : BOOL;                     (* Master enable flag *)
    bStartProcess : BOOL;               (* Trigger to start the extraction cycle *)
    bEmergencyStop : BOOL;              (* E-Stop condition *)
    rTargetPressure_Bar : REAL := 350.0;(* Target extraction vessel pressure *)
    rRampRate_BarPerSec : REAL := 0.5;  (* Pressure ramp rate *)
    rTargetTemp_C : REAL := 45.0;       (* Target extraction temperature *)
    rMassFlowTarget_KgHr : REAL := 50.0;(* Supercritical CO2 mass flow target *)
    tExtractionTime : TIME := T#120M;   (* Duration of active extraction *)
    rSep1TargetPress_Bar : REAL := 120.0;(* Separator 1 target pressure *)
    rSep2TargetPress_Bar : REAL := 50.0; (* Separator 2 target pressure *)
    rActualExtPressure_Bar : REAL;      (* Sensor: Actual extraction pressure *)
    rActualExtTemp_C : REAL;            (* Sensor: Actual extraction temperature *)
    rActualMassFlow_KgHr : REAL;        (* Sensor: Actual mass flow rate *)
    rActualSep1Press_Bar : REAL;        (* Sensor: Actual Separator 1 pressure *)
    rActualSep2Press_Bar : REAL;        (* Sensor: Actual Separator 2 pressure *)
END_VAR

VAR_OUTPUT
    bProcessRunning : BOOL;             (* True while extraction is active *)
    bProcessComplete : BOOL;            (* True when extraction finishes successfully *)
    bError : BOOL;                      (* Error flag *)
    iErrorCode : INT;                   (* Detailed error code *)
    rCO2PumpSpeedCmd_RPM : REAL;        (* Command: CO2 pump speed *)
    rExtHeaterOutput_Pct : REAL;        (* Command: Extraction heater PWM/analog out *)
    rSep1ValveCmd_Pct : REAL;           (* Command: Separator 1 backpressure valve *)
    rSep2ValveCmd_Pct : REAL;           (* Command: Separator 2 backpressure valve *)
    eCurrentState : INT;                (* Current state machine step *)
END_VAR

VAR
    eState : (IDLE, SYSTEM_CHECK, RAMP_PRESSURE, HEAT_VESSEL, STEADY_EXTRACTION, BLOWDOWN, COMPLETE, FAULT) := IDLE;
    timerExtraction : TON;
    rCurrentPressureSetpoint : REAL;
    rPressureError : REAL;
    rPressureIntegral : REAL;
    rFlowError : REAL;
    rFlowIntegral : REAL;

    // PID tuning parameters for pump
    Kp_Pump : REAL := 2.5;
    Ki_Pump : REAL := 0.1;

    // PID tuning for heater
    Kp_Heater : REAL := 5.0;
    Ki_Heater : REAL := 0.2;
    rTempError : REAL;
    rTempIntegral : REAL;

    // PID tuning for Separator Valves
    Kp_Valve : REAL := 1.5;
    Ki_Valve : REAL := 0.05;

    rSep1PressError : REAL;
    rSep1PressIntegral : REAL;
    rSep2PressError : REAL;
    rSep2PressIntegral : REAL;

    rCycleTime_Sec : REAL := 0.1; (* 100ms task cycle time assumed *)
END_VAR

(* EMERGENCY STOP HANDLING *)
IF bEmergencyStop THEN
    eState := FAULT;
    iErrorCode := 999;
END_IF;

IF NOT bEnable THEN
    eState := IDLE;
    bProcessRunning := FALSE;
    bProcessComplete := FALSE;
    rCO2PumpSpeedCmd_RPM := 0.0;
    rExtHeaterOutput_Pct := 0.0;
    rSep1ValveCmd_Pct := 0.0;
    rSep2ValveCmd_Pct := 0.0;
    bError := FALSE;
    iErrorCode := 0;
    RETURN;
END_IF;

CASE eState OF
    IDLE:
        bProcessRunning := FALSE;
        bProcessComplete := FALSE;
        bError := FALSE;
        iErrorCode := 0;
        rCO2PumpSpeedCmd_RPM := 0.0;
        rExtHeaterOutput_Pct := 0.0;
        rSep1ValveCmd_Pct := 0.0;
        rSep2ValveCmd_Pct := 0.0;
        rCurrentPressureSetpoint := 0.0;
        rPressureIntegral := 0.0;
        rFlowIntegral := 0.0;
        rTempIntegral := 0.0;
        rSep1PressIntegral := 0.0;
        rSep2PressIntegral := 0.0;
        timerExtraction(IN := FALSE);

        IF bStartProcess THEN
            eState := SYSTEM_CHECK;
        END_IF;

    SYSTEM_CHECK:
        bProcessRunning := TRUE;
        (* Verify sensor health and initial conditions *)
        IF rActualExtPressure_Bar > 10.0 OR rActualExtTemp_C > 50.0 THEN
            eState := FAULT;
            iErrorCode := 101; (* Residual pressure/temp too high *)
        ELSE
            eState := RAMP_PRESSURE;
            rCurrentPressureSetpoint := rActualExtPressure_Bar;
        END_IF;

    RAMP_PRESSURE:
        (* Slowly ramp up pressure setpoint to avoid shock *)
        rCurrentPressureSetpoint := rCurrentPressureSetpoint + (rRampRate_BarPerSec * rCycleTime_Sec);
        IF rCurrentPressureSetpoint > rTargetPressure_Bar THEN
            rCurrentPressureSetpoint := rTargetPressure_Bar;
        END_IF;

        (* Cascade PI control for Pump (Pressure outer, Flow inner loop simplified) *)
        rPressureError := rCurrentPressureSetpoint - rActualExtPressure_Bar;
        rPressureIntegral := rPressureIntegral + (rPressureError * rCycleTime_Sec);
        rCO2PumpSpeedCmd_RPM := (Kp_Pump * rPressureError) + (Ki_Pump * rPressureIntegral);

        IF rCO2PumpSpeedCmd_RPM > 1500.0 THEN rCO2PumpSpeedCmd_RPM := 1500.0; END_IF;
        IF rCO2PumpSpeedCmd_RPM < 0.0 THEN rCO2PumpSpeedCmd_RPM := 0.0; END_IF;

        IF rActualExtPressure_Bar >= (rTargetPressure_Bar * 0.98) THEN
            eState := HEAT_VESSEL;
        END_IF;

    HEAT_VESSEL:
        (* Maintain pressure *)
        rPressureError := rTargetPressure_Bar - rActualExtPressure_Bar;
        rPressureIntegral := rPressureIntegral + (rPressureError * rCycleTime_Sec);
        rCO2PumpSpeedCmd_RPM := (Kp_Pump * rPressureError) + (Ki_Pump * rPressureIntegral);

        (* PI control for Heater *)
        rTempError := rTargetTemp_C - rActualExtTemp_C;
        rTempIntegral := rTempIntegral + (rTempError * rCycleTime_Sec);
        rExtHeaterOutput_Pct := (Kp_Heater * rTempError) + (Ki_Heater * rTempIntegral);

        IF rExtHeaterOutput_Pct > 100.0 THEN rExtHeaterOutput_Pct := 100.0; END_IF;
        IF rExtHeaterOutput_Pct < 0.0 THEN rExtHeaterOutput_Pct := 0.0; END_IF;

        IF rActualExtTemp_C >= (rTargetTemp_C * 0.95) THEN
            eState := STEADY_EXTRACTION;
        END_IF;

    STEADY_EXTRACTION:
        (* Active mass flow metering *)
        rFlowError := rMassFlowTarget_KgHr - rActualMassFlow_KgHr;
        rFlowIntegral := rFlowIntegral + (rFlowError * rCycleTime_Sec);
        rCO2PumpSpeedCmd_RPM := (Kp_Pump * rFlowError) + (Ki_Pump * rFlowIntegral);

        IF rCO2PumpSpeedCmd_RPM > 2000.0 THEN rCO2PumpSpeedCmd_RPM := 2000.0; END_IF;
        IF rCO2PumpSpeedCmd_RPM < 0.0 THEN rCO2PumpSpeedCmd_RPM := 0.0; END_IF;

        (* Maintain Temp *)
        rTempError := rTargetTemp_C - rActualExtTemp_C;
        rTempIntegral := rTempIntegral + (rTempError * rCycleTime_Sec);
        rExtHeaterOutput_Pct := (Kp_Heater * rTempError) + (Ki_Heater * rTempIntegral);
        IF rExtHeaterOutput_Pct > 100.0 THEN rExtHeaterOutput_Pct := 100.0; END_IF;
        IF rExtHeaterOutput_Pct < 0.0 THEN rExtHeaterOutput_Pct := 0.0; END_IF;

        (* Separator Pressure Control *)
        rSep1PressError := rSep1TargetPress_Bar - rActualSep1Press_Bar;
        rSep1PressIntegral := rSep1PressIntegral + (rSep1PressError * rCycleTime_Sec);
        rSep1ValveCmd_Pct := (Kp_Valve * rSep1PressError) + (Ki_Valve * rSep1PressIntegral);

        rSep2PressError := rSep2TargetPress_Bar - rActualSep2Press_Bar;
        rSep2PressIntegral := rSep2PressIntegral + (rSep2PressError * rCycleTime_Sec);
        rSep2ValveCmd_Pct := (Kp_Valve * rSep2PressError) + (Ki_Valve * rSep2PressIntegral);

        timerExtraction(IN := TRUE, PT := tExtractionTime);
        IF timerExtraction.Q THEN
            eState := BLOWDOWN;
            timerExtraction(IN := FALSE);
        END_IF;

    BLOWDOWN:
        (* Controlled depressurization *)
        rCO2PumpSpeedCmd_RPM := 0.0;
        rExtHeaterOutput_Pct := 0.0;

        (* Open valves to vent *)
        rSep1ValveCmd_Pct := 100.0;
        rSep2ValveCmd_Pct := 100.0;

        IF rActualExtPressure_Bar < 5.0 THEN
            eState := COMPLETE;
        END_IF;

    COMPLETE:
        bProcessRunning := FALSE;
        bProcessComplete := TRUE;
        rSep1ValveCmd_Pct := 0.0;
        rSep2ValveCmd_Pct := 0.0;

        IF NOT bStartProcess THEN
            eState := IDLE;
        END_IF;

    FAULT:
        bError := TRUE;
        bProcessRunning := FALSE;
        rCO2PumpSpeedCmd_RPM := 0.0;
        rExtHeaterOutput_Pct := 0.0;
        (* Fallback safe valve states *)
        rSep1ValveCmd_Pct := 0.0;
        rSep2ValveCmd_Pct := 0.0;

        IF NOT bEmergencyStop AND NOT bStartProcess THEN
            eState := IDLE;
        END_IF;

END_CASE;

// State Enum output map
IF eState = IDLE THEN eCurrentState := 0; END_IF;
IF eState = SYSTEM_CHECK THEN eCurrentState := 1; END_IF;
IF eState = RAMP_PRESSURE THEN eCurrentState := 2; END_IF;
IF eState = HEAT_VESSEL THEN eCurrentState := 3; END_IF;
IF eState = STEADY_EXTRACTION THEN eCurrentState := 4; END_IF;
IF eState = BLOWDOWN THEN eCurrentState := 5; END_IF;
IF eState = COMPLETE THEN eCurrentState := 6; END_IF;
IF eState = FAULT THEN eCurrentState := 7; END_IF;
``END_FUNCTION_BLOCK
`
```

