FUNCTION_BLOCK FB_AerospaceEHA_FlightControl
VAR_INPUT
    (* Commanded flight surface position from flight control computers *)
    rCmdPosition        : REAL;    (* Commanded stroke position in mm, Range: -150.0 to 150.0 *)

    (* Triple-redundant LVDT sensor feedbacks *)
    rPosFbk_ChanA       : REAL;    (* LVDT Channel A position feedback in mm *)
    rPosFbk_ChanB       : REAL;    (* LVDT Channel B position feedback in mm *)
    rPosFbk_ChanC       : REAL;    (* LVDT Channel C position feedback in mm *)

    (* EHA systemic parameters *)
    rSupplyPress        : REAL;    (* Pump discharge pressure in Bar *)
    rReturnPress        : REAL;    (* Pump suction pressure in Bar *)
    rFluidTemp          : REAL;    (* Hydraulic fluid temperature in deg C *)

    (* Flight state and safety signals *)
    bFlightModeActive   : BOOL;    (* True when primary flight mode active *)
    bEmergencyBypass    : BOOL;    (* Direct bypass valve override for free-trailing *)
END_VAR
VAR_OUTPUT
    (* Drive signals *)
    rPumpTorqueCmd      : REAL;    (* Command to variable displacement pump torque motor, +/- 100.0% *)
    bBypassValveEngage  : BOOL;    (* Bypass valve discrete actuation command, TRUE = engaged (active) *)

    (* State monitoring *)
    rVotedPosition      : REAL;    (* Consolidated LVDT position signal *)
    bChannelFaultA      : BOOL;    (* Fault indicator for Channel A LVDT *)
    bChannelFaultB      : BOOL;    (* Fault indicator for Channel B LVDT *)
    bChannelFaultC      : BOOL;    (* Fault indicator for Channel C LVDT *)
    bSystemDegraded     : BOOL;    (* EHA operates in degraded capacity mode *)
    bCriticalFailure    : BOOL;    (* Complete loss of active EHA authority *)
END_VAR
VAR
    (* State Management *)
    iState              : INT := 0; (* 0: INIT, 10: STANDBY, 20: ACTIVE_FULL, 30: ACTIVE_DEGRADED, 99: FAILED_BYPASS *)

    (* Redundancy Management Variables *)
    rPosDiffAB          : REAL;
    rPosDiffBC          : REAL;
    rPosDiffCA          : REAL;
    rTolerance          : REAL := 2.5; (* Tolerance in mm for LVDT mismatch *)
    iValidChannels      : INT;

    (* Control Loop Variables *)
    rPosError           : REAL;
    rPosErrorPrev       : REAL;
    rErrorIntegral      : REAL;
    rErrorDerivative    : REAL;

    (* Control Gains (Scheduled by Fluid Temp / Dynamics) *)
    rKp                 : REAL := 12.5;
    rKi                 : REAL := 0.4;
    rKd                 : REAL := 2.1;

    (* Asymmetrical volume compensation factors *)
    rAreaRatio          : REAL := 1.25; (* Actuator cap end vs rod end area ratio *)

    (* Internal Timers *)
    tFaultTimerA        : TON;
    tFaultTimerB        : TON;
    tFaultTimerC        : TON;
    tInitDelay          : TON;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Override Evaluation *)
IF bEmergencyBypass THEN
    iState := 99; (* Force to FAILED_BYPASS *)
END_IF;

(* Redundancy Management and Sensor Voting (Mid-Value Select) *)
rPosDiffAB := ABS(rPosFbk_ChanA - rPosFbk_ChanB);
rPosDiffBC := ABS(rPosFbk_ChanB - rPosFbk_ChanC);
rPosDiffCA := ABS(rPosFbk_ChanC - rPosFbk_ChanA);

(* Debounce faults *)
tFaultTimerA(IN := (rPosDiffAB > rTolerance) AND (rPosDiffCA > rTolerance), PT := T#50MS);
tFaultTimerB(IN := (rPosDiffAB > rTolerance) AND (rPosDiffBC > rTolerance), PT := T#50MS);
tFaultTimerC(IN := (rPosDiffBC > rTolerance) AND (rPosDiffCA > rTolerance), PT := T#50MS);

IF tFaultTimerA.Q THEN bChannelFaultA := TRUE; END_IF;
IF tFaultTimerB.Q THEN bChannelFaultB := TRUE; END_IF;
IF tFaultTimerC.Q THEN bChannelFaultC := TRUE; END_IF;

iValidChannels := 3;
IF bChannelFaultA THEN iValidChannels := iValidChannels - 1; END_IF;
IF bChannelFaultB THEN iValidChannels := iValidChannels - 1; END_IF;
IF bChannelFaultC THEN iValidChannels := iValidChannels - 1; END_IF;

(* Vote position based on remaining valid channels *)
IF iValidChannels = 3 THEN
    (* Mid-value select for 3 valid channels *)
    IF (rPosFbk_ChanA > rPosFbk_ChanB AND rPosFbk_ChanA < rPosFbk_ChanC) OR (rPosFbk_ChanA < rPosFbk_ChanB AND rPosFbk_ChanA > rPosFbk_ChanC) THEN
        rVotedPosition := rPosFbk_ChanA;
    ELSIF (rPosFbk_ChanB > rPosFbk_ChanA AND rPosFbk_ChanB < rPosFbk_ChanC) OR (rPosFbk_ChanB < rPosFbk_ChanA AND rPosFbk_ChanB > rPosFbk_ChanC) THEN
        rVotedPosition := rPosFbk_ChanB;
    ELSE
        rVotedPosition := rPosFbk_ChanC;
    END_IF;
ELSIF iValidChannels = 2 THEN
    bSystemDegraded := TRUE;
    (* Average the two remaining valid channels *)
    IF NOT bChannelFaultA AND NOT bChannelFaultB THEN rVotedPosition := (rPosFbk_ChanA + rPosFbk_ChanB) / 2.0; END_IF;
    IF NOT bChannelFaultB AND NOT bChannelFaultC THEN rVotedPosition := (rPosFbk_ChanB + rPosFbk_ChanC) / 2.0; END_IF;
    IF NOT bChannelFaultC AND NOT bChannelFaultA THEN rVotedPosition := (rPosFbk_ChanC + rPosFbk_ChanA) / 2.0; END_IF;
ELSIF iValidChannels = 1 THEN
    bSystemDegraded := TRUE;
    IF NOT bChannelFaultA THEN rVotedPosition := rPosFbk_ChanA; END_IF;
    IF NOT bChannelFaultB THEN rVotedPosition := rPosFbk_ChanB; END_IF;
    IF NOT bChannelFaultC THEN rVotedPosition := rPosFbk_ChanC; END_IF;
ELSE
    bCriticalFailure := TRUE;
    iState := 99; (* Transition to fail-safe free-trailing mode *)
END_IF;

(* State Machine Execution *)
CASE iState OF
    0: (* INIT *)
        bBypassValveEngage := FALSE;
        rPumpTorqueCmd := 0.0;
        tInitDelay(IN := TRUE, PT := T#2S);
        IF tInitDelay.Q AND NOT bCriticalFailure THEN
            tInitDelay(IN := FALSE);
            iState := 10;
        END_IF;

    10: (* STANDBY *)
        bBypassValveEngage := TRUE; (* Lock actuator dynamically or bypass *)
        rPumpTorqueCmd := 0.0;
        IF bFlightModeActive AND NOT bCriticalFailure THEN
            iState := 20;
        END_IF;

    20: (* ACTIVE FULL *)
        bBypassValveEngage := TRUE;

        (* Evaluate degradation *)
        IF bSystemDegraded THEN
            iState := 30;
        END_IF;

        (* PID Controller *)
        rPosError := rCmdPosition - rVotedPosition;
        rErrorIntegral := rErrorIntegral + (rPosError * 0.01); (* Assuming 10ms task cycle *)
        rErrorDerivative := (rPosError - rPosErrorPrev) / 0.01;
        rPosErrorPrev := rPosError;

        (* Anti-windup limit for integral *)
        IF rErrorIntegral > 50.0 THEN rErrorIntegral := 50.0; END_IF;
        IF rErrorIntegral < -50.0 THEN rErrorIntegral := -50.0; END_IF;

        (* Asymmetrical Actuator Volume Compensation Mapping *)
        IF rPosError > 0.0 THEN
            rPumpTorqueCmd := (rKp * rPosError) + (rKi * rErrorIntegral) + (rKd * rErrorDerivative);
        ELSE
            (* Modify gain based on cylinder area ratio for retraction *)
            rPumpTorqueCmd := ((rKp * rPosError) + (rKi * rErrorIntegral) + (rKd * rErrorDerivative)) * rAreaRatio;
        END_IF;

        (* Torque saturation limits *)
        IF rPumpTorqueCmd > 100.0 THEN rPumpTorqueCmd := 100.0; END_IF;
        IF rPumpTorqueCmd < -100.0 THEN rPumpTorqueCmd := -100.0; END_IF;

    30: (* ACTIVE DEGRADED *)
        bBypassValveEngage := TRUE;

        (* In degraded mode, run softer gains to prevent oscillation on single sensor *)
        rPosError := rCmdPosition - rVotedPosition;
        rPumpTorqueCmd := (rKp * 0.5 * rPosError); (* Pure proportional, half gain *)

        IF rPumpTorqueCmd > 50.0 THEN rPumpTorqueCmd := 50.0; END_IF;
        IF rPumpTorqueCmd < -50.0 THEN rPumpTorqueCmd := -50.0; END_IF;

        IF NOT bSystemDegraded THEN
            iState := 20;
        END_IF;

    99: (* FAILED_BYPASS *)
        (* Disengage bypass valve - allow free trailing *)
        bBypassValveEngage := FALSE;
        rPumpTorqueCmd := 0.0;
        bCriticalFailure := TRUE;

END_CASE;

END_FUNCTION_BLOCK
