FUNCTION_BLOCK FB_DLTS_Cryostat_Controller
VAR_INPUT
    (* Multi-layered safety and physical system inputs *)
    bEnable                 : BOOL;     (* System Enable Signal *)
    bEmergencyStop          : BOOL;     (* E-Stop OK Signal (Active High) *)
    rTargetTemperature_K    : REAL;     (* Target Cryostat Temperature [Kelvin] (e.g. 4.0K for LHe) *)
    rHe_FlowRate_slm        : REAL;     (* Current Liquid Helium Flow Rate [SLM] *)
    rSampleCapacitance_pF   : REAL;     (* Raw Sample Capacitance [pF] from precision capacitance meter *)
    bBiasPulseTrigger       : BOOL;     (* Trigger for Reverse Bias Trap Filling Pulse *)
    rCryostatPressure_mTorr : REAL;     (* Vacuum Pressure inside cryostat [mTorr] *)
END_VAR
VAR_OUTPUT
    (* Actuators, state, and alarms *)
    bSystemReady            : BOOL;     (* Cryostat stabilized and ready for measurement *)
    rHe_ValveControl        : REAL;     (* Helium Flow Control Valve Position [%] (0-100) *)
    rHeaterPower_W          : REAL;     (* Cryostat Heater Power [Watts] *)
    bInjectBiasPulse        : BOOL;     (* Command to inject high-speed reverse bias pulse *)
    bThermalAlarm           : BOOL;     (* Thermal instability or quench alarm *)
    bVacuumAlarm            : BOOL;     (* Loss of high vacuum alarm *)
END_VAR
VAR
    (* Internal State Machine and PID loop parameters *)
    iState                  : INT := 0; (* Internal State Machine *)
    rCurrentTemp_K          : REAL;     (* Filtered current temperature *)
    tStabTimer              : TON;      (* Stabilization Timer *)
    tPulseTimer             : TON;      (* Trap filling pulse timer *)
    rError_K                : REAL;     (* Temperature error *)
    rIntegral               : REAL := 0.0;
    rDerivative             : REAL := 0.0;
    rLastError_K            : REAL := 0.0;
    rKp                     : REAL := 2.5;
    rKi                     : REAL := 0.05;
    rKd                     : REAL := 1.2;
    rPID_Out                : REAL;
    bPulseActive            : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
(* Multi-layered safety interlocks - Check E-Stop and Vacuum *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bThermalAlarm := TRUE;
    rHe_ValveControl := 0.0;
    rHeaterPower_W := 0.0;
    bInjectBiasPulse := FALSE;
    iState := 99; (* Fault State *)
    RETURN;
END_IF;

IF rCryostatPressure_mTorr > 5.0 THEN
    bVacuumAlarm := TRUE;
    bSystemReady := FALSE;
    rHeaterPower_W := 0.0;
    rHe_ValveControl := 0.0;
    iState := 99; (* High Vacuum Loss Fault State *)
    RETURN;
END_IF;

bVacuumAlarm := FALSE;

(* Main Control State Machine for Deep-Level Transient Spectroscopy (DLTS) Cooling and Measurement *)
CASE iState OF
    0: (* IDLE / INITIALIZATION *)
        bSystemReady := FALSE;
        rHe_ValveControl := 0.0;
        rHeaterPower_W := 0.0;
        bThermalAlarm := FALSE;
        bInjectBiasPulse := FALSE;

        IF bEnable AND bEmergencyStop THEN
            iState := 10; (* Proceed to COOL DOWN PHASE *)
        END_IF;

    10: (* COOL DOWN PHASE *)
        (* Open He valve to begin cooling. Typically maximum flow without quenching the transfer line. *)
        rHe_ValveControl := 80.0; 

        (* In a real implementation, this reads from an analog input (e.g. LakeShore controller mapping Cernox sensor) *)
        rCurrentTemp_K := rTargetTemperature_K + 2.0; (* Placeholder simulated drop *)

        IF rCurrentTemp_K <= (rTargetTemperature_K + 1.0) THEN
            iState := 20; (* Switch to PID STABILIZATION *)
        END_IF;

    20: (* PID STABILIZATION PHASE *)
        (* Calculate PID for precise heater and He valve flow control at target temperature (e.g. 4K) *)
        rError_K := rTargetTemperature_K - rCurrentTemp_K;

        (* Integration with anti-windup *)
        rIntegral := rIntegral + (rError_K * 0.1); (* Assuming 100ms task cycle time *)
        IF rIntegral > 50.0 THEN rIntegral := 50.0; END_IF;
        IF rIntegral < -50.0 THEN rIntegral := -50.0; END_IF;

        rDerivative := (rError_K - rLastError_K) / 0.1;
        rPID_Out := (rKp * rError_K) + (rKi * rIntegral) + (rKd * rDerivative);
        rLastError_K := rError_K;

        (* Apply control output, splitting logic between He continuous flow and micro-heater trim *)
        IF rPID_Out > 0.0 THEN
            rHeaterPower_W := rPID_Out;
            rHe_ValveControl := 10.0; (* Minimum flow to maintain cryogen transfer level *)
        ELSE
            rHeaterPower_W := 0.0;
            rHe_ValveControl := 10.0 - rPID_Out; (* Increase flow to cool down further *)
        END_IF;

        (* Limit control outputs to physical constraints *)
        IF rHeaterPower_W > 100.0 THEN rHeaterPower_W := 100.0; END_IF;
        IF rHe_ValveControl > 100.0 THEN rHe_ValveControl := 100.0; END_IF;

        (* Check thermal stability window *)
        IF ABS(rError_K) < 0.05 THEN
            tStabTimer(IN := TRUE, PT := T#30S);
        ELSE
            tStabTimer(IN := FALSE, PT := T#30S);
        END_IF;

        IF tStabTimer.Q THEN
            bSystemReady := TRUE;
            iState := 30; (* System locked in, proceed to MEASUREMENT READY *)
        END_IF;

    30: (* MEASUREMENT READY & TRANSIENT CORRELATION INJECTION *)
        (* Maintain gentle PID control while taking sensitive sub-pF measurements *)
        rError_K := rTargetTemperature_K - rCurrentTemp_K;
        rIntegral := rIntegral + (rError_K * 0.1);
        rPID_Out := (rKp * rError_K) + (rKi * rIntegral);
        rHeaterPower_W := MAX(0.0, MIN(100.0, rPID_Out));
        rHe_ValveControl := 10.0; 

        (* Detect thermal runaway during measurement *)
        IF ABS(rError_K) > 0.5 THEN
            bSystemReady := FALSE;
            bThermalAlarm := TRUE;
            tStabTimer(IN := FALSE);
            iState := 20; (* Return to stabilization phase *)
        END_IF;

        (* Ultra-fast trap filling pulse logic *)
        IF bBiasPulseTrigger AND NOT bPulseActive THEN
            bPulseActive := TRUE;
            bInjectBiasPulse := TRUE;
            tPulseTimer(IN := TRUE, PT := T#10MS); (* 10ms reverse bias pulse for trap filling *)
        END_IF;

        IF bPulseActive THEN
            tPulseTimer(IN := TRUE, PT := T#10MS);
            IF tPulseTimer.Q THEN
                bPulseActive := FALSE;
                bInjectBiasPulse := FALSE;
                tPulseTimer(IN := FALSE);
            END_IF;
        END_IF;

        IF NOT bEnable THEN
            bSystemReady := FALSE;
            iState := 0;
        END_IF;

    99: (* FAULT / SAFE STATE *)
        bSystemReady := FALSE;
        rHeaterPower_W := 0.0;
        rHe_ValveControl := 0.0;
        bInjectBiasPulse := FALSE;

        IF bEmergencyStop AND NOT bVacuumAlarm THEN
            iState := 0; (* Reset only if safety conditions are met *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
