   VAR_INPUT
      bEnableRouteDivergence : Bool;   // Request to pull train onto divergent route
      rTrainSpeedKmH : Real;           // Current train speed (e.g., 500.0 km/h)
      rDistanceToSwitchMeters : Real;  // Distance of incoming train to switch zone

      // Cooling Loop Inputs (Liquid Nitrogen)
      rLN2FlowRate_Lpm : Real;         // Liquid Nitrogen flow rate (Liters per minute)
      rLN2Pressure_Bar : Real;         // Loop pressure
      rGuidewayTemp_Kelvin : Real;     // Temperature of superconducting guideway electromagnets

      // Inductive Power Transfer
      bCabinPowerSyncReady : Bool;     // Cabin confirmed ready for inductive power handover
      rCabinPowerDemand_kW : Real;     // Power requested by the passenger cabin
   END_VAR

   VAR_OUTPUT
      bSwitchReady : Bool;             // Switch is chilled and ready for high-speed operation
      bSwitchEngaged : Bool;           // Switch actively pulling train to divergent route
      bCoolingSystemFault : Bool;      // LN2 cooling failure
      bSequenceFault : Bool;           // Switch timing or sync failure

      // Polarity Switching Outputs
      bPolarityMainLine : Bool;        // True for Main Line retention
      bPolarityDivergentRoute : Bool;  // True for Divergent Route attraction
      rSwitchingFrequency_Hz : Real;   // Pulse frequency for smooth transition

      // Inductive Power outputs
      bActivateInductiveTx : Bool;     // Enable trackside inductive power transfer to cabin
      rInductiveTxPower_kW : Real;     // Power setpoint for inductive transmission
   END_VAR

   VAR
      rtRouteRequest {InstructionName := 'R_TRIG'; LibVersion := '1.0'} : R_TRIG;
      ftRouteRequest {InstructionName := 'F_TRIG'; LibVersion := '1.0'} : F_TRIG;
      tonCoolingStabilization {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
      tonSwitchDuration {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
      tonInductiveHandover {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;

      // Internal States
      iState : Int := 0; 

      rTimeUntilSwitch_ms : Real;
      rEstimatedTimeOfArrival_s : Real;

      // Constraints & Thresholds
      c_rMaxTempKelvin : Real := 77.0;       // Boiling point of LN2, operational limit
      c_rMinFlowRate : Real := 120.0;        // Min required flow for SC electromagnets
      c_rMinPressure : Real := 3.5;          // Min LN2 loop pressure in Bar
      c_rMaxSpeedKmH : Real := 520.0;        // V_max for safe divergence
      c_rDivergeDistanceMeters : Real := 450.0; // Distance required for full shift
   END_VAR

BEGIN
   // 1. Diagnostics and LN2 Cooling System Monitoring
   IF (#rGuidewayTemp_Kelvin > #c_rMaxTempKelvin) OR (#rLN2FlowRate_Lpm < #c_rMinFlowRate) OR (#rLN2Pressure_Bar < #c_rMinPressure) THEN
       #bCoolingSystemFault := TRUE;
   ELSE
       #bCoolingSystemFault := FALSE;
   END_IF;

   // Trigger edge detection
   #rtRouteRequest(CLK := #bEnableRouteDivergence);
   #ftRouteRequest(CLK := #bEnableRouteDivergence);

   // Kinematic Calculation
   IF #rTrainSpeedKmH > 0.0 THEN
       #rEstimatedTimeOfArrival_s := (#rDistanceToSwitchMeters / (#rTrainSpeedKmH / 3.6));
   ELSE
       #rEstimatedTimeOfArrival_s := 9999.0;
   END_IF;

   // State Machine
   CASE #iState OF
       0: // IDLE - Default to Main Line
           #bSwitchReady := NOT #bCoolingSystemFault;
           #bSwitchEngaged := FALSE;
           #bPolarityMainLine := TRUE;
           #bPolarityDivergentRoute := FALSE;
           #bActivateInductiveTx := FALSE;
           #bSequenceFault := FALSE;

           IF #rtRouteRequest.Q AND #bSwitchReady THEN
               #iState := 10;
           END_IF;

       10: // PRE_COOLING - Ensure thermal stability before intense switching
           #tonCoolingStabilization(IN := TRUE, PT := T#500ms);
           IF #tonCoolingStabilization.Q THEN
               #tonCoolingStabilization(IN := FALSE, PT := T#500ms); // Reset
               IF #rTrainSpeedKmH <= #c_rMaxSpeedKmH THEN
                   #iState := 20;
               ELSE
                   #bSequenceFault := TRUE;
                   #iState := 99;
               END_IF;
           END_IF;

       20: // CALCULATING_TIMING - Wait for perfect millisecond entry window
           #rTimeUntilSwitch_ms := #rEstimatedTimeOfArrival_s * 1000.0;

           IF #rTimeUntilSwitch_ms <= 200.0 AND #rTimeUntilSwitch_ms > 0.0 THEN
               #iState := 30; // 200ms before switch zone
           ELSIF #rTimeUntilSwitch_ms <= 0.0 THEN
               #bSequenceFault := TRUE; // Missed the window
               #iState := 99;
           END_IF;

       30: // POLARITY_SYNC - Millisecond-perfect polarity switching
           // De-energize Main Line, ramp up Divergent Route
           #bPolarityMainLine := FALSE;
           #bPolarityDivergentRoute := TRUE;
           #rSwitchingFrequency_Hz := 1200.0; // High frequency for rapid flux change

           IF #rTimeUntilSwitch_ms <= 5.0 THEN // Train is physically entering the switch
               #iState := 40;
           END_IF;

       40: // DIVERGING_ACTIVE - Train is actively crossing the switch
           #bSwitchEngaged := TRUE;

           // Wait until train clears the switch zone
           #tonSwitchDuration(IN := TRUE, PT := DINT_TO_TIME(REAL_TO_DINT((#c_rDivergeDistanceMeters / (#rTrainSpeedKmH / 3.6)) * 1000.0)));
           IF #tonSwitchDuration.Q THEN
               #tonSwitchDuration(IN := FALSE, PT := T#0s);
               #iState := 50;
           END_IF;

       50: // INDUCTIVE_HANDOVER - Power synchronization to passenger cabins
           IF #bCabinPowerSyncReady THEN
               #bActivateInductiveTx := TRUE;
               #rInductiveTxPower_kW := #rCabinPowerDemand_kW * 1.05; // 5% margin for loss
           END_IF;

           #tonInductiveHandover(IN := #bActivateInductiveTx, PT := T#2s);
           IF #tonInductiveHandover.Q THEN
               #tonInductiveHandover(IN := FALSE, PT := T#2s);
               #bActivateInductiveTx := FALSE;
               IF NOT #bEnableRouteDivergence THEN
                   #iState := 0;
               END_IF;
           END_IF;

       99: // FAULT RECOVERY
           #bSwitchEngaged := FALSE;
           #bPolarityMainLine := TRUE; // Fail-safe to straight path
           #bPolarityDivergentRoute := FALSE;
           #bActivateInductiveTx := FALSE;

           IF NOT #bEnableRouteDivergence AND NOT #bCoolingSystemFault THEN
               #iState := 0;
           END_IF;

   END_CASE;

   // Global Fault Override
   IF #bCoolingSystemFault THEN
       #iState := 99;
   END_IF;

END_FUNCTION_BLOCK
