FUNCTION_BLOCK "FB_BatchReactor_Reasoning"
VERSION : 0.1
   VAR_INPUT 
      start_batch : Bool;
      reactor_temp : Real;
      reactor_press : Real;
      catalyst_flow : Real;
      agitator_load : Real;
      setpoint_temp : Real;
      setpoint_dosing : Real;
      pn_io_status : Word;
      user_access_level : Int; // IEC 62443
      cpu_primary_active : Bool; // Redundancy
   END_VAR

   VAR_OUTPUT 
      cooling_valve : Real;
      dosing_pump : Bool;
      agitator_speed_ref : Real;
      alarm_high_press : Bool;
      interlock_rupture : Bool;
      fault_io_module : Bool;
      fault_code : Word;
      scada_interface : "SCADA_Data";
   END_VAR

   VAR 
      pid_cooling : "PID_Compact";
      total_catalyst : Real;
      batch_active : Bool;
      failover_in_progress : Bool;
   END_VAR

BEGIN
   // Redundancy Handling
   IF NOT #cpu_primary_active THEN
       #failover_in_progress := TRUE;
       RETURN; // Hold last state during failover sync
   ELSE
       #failover_in_progress := FALSE;
   END_IF;

   // IEC 62443 Security Check
   IF #user_access_level < 2 AND #start_batch THEN
       #scada_interface.Security_Alert := TRUE;
       RETURN; // Unauthorized operation rejected
   END_IF;

   // Profinet Diagnostics
   IF #pn_io_status <> 16#0000 THEN
       #fault_io_module := TRUE;
       #fault_code := #pn_io_status;
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
       #scada_interface.Fault_Code := #fault_code;
       RETURN;
   ELSE
       #fault_io_module := FALSE;
       #fault_code := 16#0000;
   END_IF;

   // Interlocks
   IF #reactor_press > 10.0 THEN
       #interlock_rupture := TRUE;
       #alarm_high_press := TRUE;
       #batch_active := FALSE;
   END_IF;

   IF #interlock_rupture THEN
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
   ELSIF #start_batch THEN
       #batch_active := TRUE;
   END_IF;

   IF #batch_active THEN
       #pid_cooling(Setpoint := #setpoint_temp, Input := #reactor_temp, Output => #cooling_valve);
       IF #total_catalyst < #setpoint_dosing THEN
           #dosing_pump := TRUE;
           #total_catalyst := #total_catalyst + (#catalyst_flow * 0.1);
       ELSE
           #dosing_pump := FALSE;
       END_IF;
       IF #agitator_load > 85.0 THEN
           #agitator_speed_ref := 40.0;
       ELSE
           #agitator_speed_ref := 100.0;
       END_IF;
   ELSE
       #cooling_valve := 0.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
   END_IF;

   // SCADA Integration Update
   #scada_interface.Active := #batch_active;
   #scada_interface.Temp_PV := #reactor_temp;
   #scada_interface.Press_PV := #reactor_press;
   #scada_interface.Fault_Code := #fault_code;
END_FUNCTION_BLOCK
