FUNCTION_BLOCK FB_EAF_Arc_Impedance_Lancing_Control
TITLE = 'EAF Comprehensive Control - Arc Impedance, Lancing, and Slag Foaming'
VERSION : '1.5'

(* 
   This function block orchestrates the Electric Arc Furnace (EAF) core processes:
   1. Electrode positioning via active impedance control for each phase (A, B, C).
   2. Oxygen lancing flow and lance height positioning based on decarburization kinetics.
   3. Carbon injection for slag foaming regulation to protect furnace walls and optimize heat transfer.
*)

VAR_INPUT
    // Electrical Measurements
    rVoltagePhaseA_kV      : REAL; (* Secondary voltage Phase A [kV] *)
    rVoltagePhaseB_kV      : REAL; (* Secondary voltage Phase B [kV] *)
    rVoltagePhaseC_kV      : REAL; (* Secondary voltage Phase C [kV] *)
    rCurrentPhaseA_kA      : REAL; (* Secondary current Phase A [kA] *)
    rCurrentPhaseB_kA      : REAL; (* Secondary current Phase B [kA] *)
    rCurrentPhaseC_kA      : REAL; (* Secondary current Phase C [kA] *)

    // Process Setpoints
    rTargetImpedance       : REAL; (* Target impedance per phase [mOhm] *)
    rImpedanceDeadband     : REAL; (* Deadband for impedance control [mOhm] *)
    rTargetCarbonPct       : REAL; (* Target bath carbon percentage *)
    rCurrentCarbonPct      : REAL; (* Estimated current bath carbon percentage *)

    // Physical Measurements
    rBathTemperature_C     : REAL; (* Liquid steel bath temperature [deg C] *)
    rSlagLevel_mm          : REAL; (* Estimated slag level/thickness [mm] *)
    bScrapCaveInDetected   : BOOL; (* High-speed current derivative indicates cave-in *)

    // Safety & Interlocks
    bRoofClosed            : BOOL;
    bCoolingWaterOK        : BOOL;
    bEStop                 : BOOL;
END_VAR

VAR_OUTPUT
    // Electrode Regulation Commands (Hydraulic Valve Setpoints)
    rRegulatorValveCmdA    : REAL; (* Valve command Phase A [-100.0 to 100.0 %] *)
    rRegulatorValveCmdB    : REAL; (* Valve command Phase B [-100.0 to 100.0 %] *)
    rRegulatorValveCmdC    : REAL; (* Valve command Phase C [-100.0 to 100.0 %] *)

    // Lancing & Injection Commands
    rOxygenFlowSetpoint    : REAL; (* Oxygen flow rate setpoint [Nm3/min] *)
    rLanceHeightCmd_mm     : REAL; (* Supersonic lance height command [mm] *)
    rCarbonInjectionRate   : REAL; (* Carbon powder injection rate [kg/min] *)

    // System Status
    bArcStable             : BOOL;
    bSlagFoamingOptimal    : BOOL;
    bWarning               : BOOL;
    sStatusMessage         : STRING[50];
END_VAR

VAR
    // Internal calculations
    rImpedanceA            : REAL;
    rImpedanceB            : REAL;
    rImpedanceC            : REAL;

    rImpedanceErrorA       : REAL;
    rImpedanceErrorB       : REAL;
    rImpedanceErrorC       : REAL;

    // Controller gains
    rKp_Impedance          : REAL := 15.0;
    rKi_Impedance          : REAL := 2.5;

    // Integral terms
    rIntA                  : REAL := 0.0;
    rIntB                  : REAL := 0.0;
    rIntC                  : REAL := 0.0;

    // State machine
    eState                 : INT := 0; 
    (* 0: Init, 1: Boring, 2: Melting, 3: Refining (Lancing/Foaming), 4: Safe Mode *)

    // Slag Foaming PID
    rFoamError             : REAL;
    rTargetSlagLevel       : REAL := 450.0; (* Ideal slag thickness for arc envelopment [mm] *)

    // Timers
    tCaveInRecoveryTimer   : TON;
    tProcessStepTimer      : TON;
END_VAR

// -----------------------------------------------------------------------------
// SAFETY & INTERLOCKS
// -----------------------------------------------------------------------------
IF bEStop OR NOT bRoofClosed OR NOT bCoolingWaterOK THEN
    eState := 4; // Safe Mode
    rRegulatorValveCmdA := -100.0; (* Max hoist up *)
    rRegulatorValveCmdB := -100.0;
    rRegulatorValveCmdC := -100.0;
    rOxygenFlowSetpoint := 0.0;
    rLanceHeightCmd_mm  := 5000.0; (* Fully retracted *)
    rCarbonInjectionRate := 0.0;
    bArcStable := FALSE;
    sStatusMessage := 'CRITICAL INTERLOCK TRIGGERED';
    RETURN;
END_IF

// -----------------------------------------------------------------------------
// IMPEDANCE CALCULATION
// -----------------------------------------------------------------------------
// Z = V / I (Avoid division by zero)
IF rCurrentPhaseA_kA > 0.1 THEN rImpedanceA := (rVoltagePhaseA_kV * 1000.0) / rCurrentPhaseA_kA; ELSE rImpedanceA := 9999.0; END_IF;
IF rCurrentPhaseB_kA > 0.1 THEN rImpedanceB := (rVoltagePhaseB_kV * 1000.0) / rCurrentPhaseB_kA; ELSE rImpedanceB := 9999.0; END_IF;
IF rCurrentPhaseC_kA > 0.1 THEN rImpedanceC := (rVoltagePhaseC_kV * 1000.0) / rCurrentPhaseC_kA; ELSE rImpedanceC := 9999.0; END_IF;

// -----------------------------------------------------------------------------
// SCRAP CAVE-IN RECOVERY
// -----------------------------------------------------------------------------
tCaveInRecoveryTimer(IN:= bScrapCaveInDetected, PT:= T#5S);
IF bScrapCaveInDetected THEN
    // Rapid lift to avoid short circuit and electrode breakage
    rRegulatorValveCmdA := -80.0;
    rRegulatorValveCmdB := -80.0;
    rRegulatorValveCmdC := -80.0;
    sStatusMessage := 'CAVE-IN RECOVERY';
    rIntA := 0.0; rIntB := 0.0; rIntC := 0.0; // Reset anti-windup
    RETURN;
END_IF

// -----------------------------------------------------------------------------
// ACTIVE IMPEDANCE CONTROL (PI REGULATION)
// -----------------------------------------------------------------------------
// Calculate Errors
rImpedanceErrorA := rTargetImpedance - rImpedanceA;
rImpedanceErrorB := rTargetImpedance - rImpedanceB;
rImpedanceErrorC := rTargetImpedance - rImpedanceC;

// Deadband application
IF ABS(rImpedanceErrorA) < rImpedanceDeadband THEN rImpedanceErrorA := 0.0; END_IF;
IF ABS(rImpedanceErrorB) < rImpedanceDeadband THEN rImpedanceErrorB := 0.0; END_IF;
IF ABS(rImpedanceErrorC) < rImpedanceDeadband THEN rImpedanceErrorC := 0.0; END_IF;

// Integral accumulation with anti-windup
rIntA := rIntA + (rImpedanceErrorA * rKi_Impedance); IF rIntA > 50.0 THEN rIntA := 50.0; ELSIF rIntA < -50.0 THEN rIntA := -50.0; END_IF;
rIntB := rIntB + (rImpedanceErrorB * rKi_Impedance); IF rIntB > 50.0 THEN rIntB := 50.0; ELSIF rIntB < -50.0 THEN rIntB := -50.0; END_IF;
rIntC := rIntC + (rImpedanceErrorC * rKi_Impedance); IF rIntC > 50.0 THEN rIntC := 50.0; ELSIF rIntC < -50.0 THEN rIntC := -50.0; END_IF;

// PI output generation (Negative output = raise electrode, Positive = lower electrode)
rRegulatorValveCmdA := (rImpedanceErrorA * rKp_Impedance) + rIntA; IF rRegulatorValveCmdA > 100.0 THEN rRegulatorValveCmdA := 100.0; ELSIF rRegulatorValveCmdA < -100.0 THEN rRegulatorValveCmdA := -100.0; END_IF;
rRegulatorValveCmdB := (rImpedanceErrorB * rKp_Impedance) + rIntB; IF rRegulatorValveCmdB > 100.0 THEN rRegulatorValveCmdB := 100.0; ELSIF rRegulatorValveCmdB < -100.0 THEN rRegulatorValveCmdB := -100.0; END_IF;
rRegulatorValveCmdC := (rImpedanceErrorC * rKp_Impedance) + rIntC; IF rRegulatorValveCmdC > 100.0 THEN rRegulatorValveCmdC := 100.0; ELSIF rRegulatorValveCmdC < -100.0 THEN rRegulatorValveCmdC := -100.0; END_IF;

// Arc Stability Check
bArcStable := (ABS(rImpedanceErrorA) < rImpedanceDeadband * 2.0) AND 
              (ABS(rImpedanceErrorB) < rImpedanceDeadband * 2.0) AND 
              (ABS(rImpedanceErrorC) < rImpedanceDeadband * 2.0);

// -----------------------------------------------------------------------------
// METALLURGICAL REFINING: OXYGEN LANCING & SLAG FOAMING
// -----------------------------------------------------------------------------
// State determination based on Bath Temp
IF rBathTemperature_C < 1550.0 THEN
    eState := 2; // Melting
    rOxygenFlowSetpoint := 20.0; // Burner mode mostly
    rLanceHeightCmd_mm := 1200.0;
    rCarbonInjectionRate := 10.0;
ELSIF rBathTemperature_C >= 1550.0 THEN
    eState := 3; // Refining

    // Decarburization Kinetics (O2 blowing proportional to Carbon Error)
    IF rCurrentCarbonPct > rTargetCarbonPct THEN
        rOxygenFlowSetpoint := 50.0 + (rCurrentCarbonPct - rTargetCarbonPct) * 200.0;
        IF rOxygenFlowSetpoint > 120.0 THEN rOxygenFlowSetpoint := 120.0; ELSIF rOxygenFlowSetpoint < 30.0 THEN rOxygenFlowSetpoint := 30.0; END_IF;
        rLanceHeightCmd_mm  := 800.0; // Closer for deeper penetration
    ELSE
        rOxygenFlowSetpoint := 15.0; // Post-combustion only
        rLanceHeightCmd_mm  := 1500.0;
    END_IF

    // Slag Foaming Control (Carbon injection to react with FeO)
    rFoamError := rTargetSlagLevel - rSlagLevel_mm;
    IF rFoamError > 0.0 AND rOxygenFlowSetpoint > 30.0 THEN
        rCarbonInjectionRate := rFoamError * 0.15;
        IF rCarbonInjectionRate > 60.0 THEN rCarbonInjectionRate := 60.0; ELSIF rCarbonInjectionRate < 0.0 THEN rCarbonInjectionRate := 0.0; END_IF;
        bSlagFoamingOptimal := FALSE;
    ELSE
        rCarbonInjectionRate := 5.0; // Maintenance dose
        bSlagFoamingOptimal := TRUE;
    END_IF
END_IF;

sStatusMessage := 'NORMAL OPERATION: ACTIVE CONTROL';
END_FUNCTION_BLOCK
