FUNCTION_BLOCK FB_WindFarmWakeControl
VAR_INPUT
    Enable : BOOL; // Enable active wake control
    GridFreq : REAL; // Grid frequency in Hz
    TargetActivePower : REAL; // Dispatched active power for the farm in MW
    WindSpeed : REAL; // Free-stream wind speed
    WindDirection : REAL; // Free-stream wind direction
    TurbinePowerAvailable : ARRAY[1..50] OF REAL; // Available power of each turbine
    TurbineYawCurrent : ARRAY[1..50] OF REAL; // Current yaw angle of each turbine
END_VAR
VAR_OUTPUT
    TurbinePowerSetpoint : ARRAY[1..50] OF REAL; // Power setpoint for each turbine
    TurbineYawSetpoint : ARRAY[1..50] OF REAL; // Yaw offset for wake steering
    FarmActivePowerTotal : REAL; // Total current active power output
    DroopActive : BOOL; // Frequency droop response is active
END_VAR
VAR
    i : INT;
    FreqError : REAL;
    DroopDeltaP : REAL;
    TotalAvailablePower : REAL;
    WakeDeflectionModel : REAL;
    NominalFreq : REAL := 50.0;
    DroopCoefficient : REAL := 0.04;
    MaxPowerCurtailment : REAL := 10.0; // MW
END_VAR

// Calculate Grid Frequency Droop
FreqError := GridFreq - NominalFreq;
IF ABS(FreqError) > 0.05 THEN
    DroopActive := TRUE;
    DroopDeltaP := - (FreqError / NominalFreq) * (1.0 / DroopCoefficient) * 100.0;
ELSE
    DroopActive := FALSE;
    DroopDeltaP := 0.0;
END_IF;

// Calculate Total Available Power
TotalAvailablePower := 0.0;
FOR i := 1 TO 50 DO
    TotalAvailablePower := TotalAvailablePower + TurbinePowerAvailable[i];
END_FOR;

// Wake Steering Logic
IF Enable AND (WindSpeed > 4.0) AND (WindSpeed < 15.0) THEN
    FOR i := 1 TO 50 DO
        // Simplified wake deflection empirical model
        // Turbines in front row get yaw offset, others get zero
        IF (i <= 10) THEN // Assuming first 10 turbines are front row
            WakeDeflectionModel := 20.0 * EXP(-0.5 * (WindDirection - 270.0) * (WindDirection - 270.0) / 100.0);
            TurbineYawSetpoint[i] := TurbineYawCurrent[i] + WakeDeflectionModel;
        ELSE
            TurbineYawSetpoint[i] := TurbineYawCurrent[i];
        END_IF;
    END_FOR;
ELSE
    FOR i := 1 TO 50 DO
        TurbineYawSetpoint[i] := TurbineYawCurrent[i];
    END_FOR;
END_IF;

// Active Power Curtailment and Dispatch
FarmActivePowerTotal := 0.0;
FOR i := 1 TO 50 DO
    IF TotalAvailablePower > 0.0 THEN
        // Distribute proportionally
        TurbinePowerSetpoint[i] := (TurbinePowerAvailable[i] / TotalAvailablePower) * (TargetActivePower + DroopDeltaP);
    ELSE
        TurbinePowerSetpoint[i] := 0.0;
    END_IF;

    // Limits check
    IF TurbinePowerSetpoint[i] > TurbinePowerAvailable[i] THEN
        TurbinePowerSetpoint[i] := TurbinePowerAvailable[i];
    END_IF;

    FarmActivePowerTotal := FarmActivePowerTotal + TurbinePowerSetpoint[i];
END_FOR;

END_FUNCTION_BLOCK
