    rpH_Measured            : REAL;     (* Current measured pH [pH units] *)
    rDO_Measured            : REAL;     (* Current Dissolved Oxygen [% saturation] *)
    rTemp_Measured          : REAL;     (* Current Temperature [deg C] *)

    rImpeller1_SpeedRPM     : REAL;     (* Bottom Impeller Speed [RPM] *)
    rImpeller2_SpeedRPM     : REAL;     (* Top Impeller Speed [RPM] *)
    rBiomass_ViableDensity  : REAL;     (* Viable cell density [10^6 cells/mL] *)

    rHollowFiber_FeedPress  : REAL;     (* ATF / TFF Feed Pressure [bar] *)
    rHollowFiber_PermPress  : REAL;     (* ATF / TFF Permeate Pressure [bar] *)
    rHollowFiber_RetPress   : REAL;     (* ATF / TFF Retentate Pressure [bar] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for active culture phase *)
    bAlarm                  : BOOL;     (* Critical alarm present *)

    rO2_SpargingFlow        : REAL;     (* Commanded O2 Microsparger flow [L/min] *)
    rCO2_SpargingFlow       : REAL;     (* Commanded CO2 Sparger flow [L/min] *)
    rAgitation_CmdRPM       : REAL;     (* Suggested optimal agitation RPM [RPM] *)
    rFeed_RateOut           : REAL;     (* Continuous Feed Rate Command [mL/min] *)

    rShearStress_Estimated  : REAL;     (* Real-time impeller shear stress estimate [N/m2] *)
    rTMP_Actual             : REAL;     (* Calculated Trans-Membrane Pressure [bar] *)

    iActiveState            : INT;      (* Current operational state *)
END_VAR

VAR
    (* Internal State and Calculation Variables *)
    iState                  : INT := 0;
    tProcessTimer           : TON;
    tSafetyTimer            : TON;

    rError_pH               : REAL;
    rError_DO               : REAL;
    rIntegral_DO            : REAL := 0.0;
    rDerivative_DO          : REAL := 0.0;
    rPrevError_DO           : REAL := 0.0;

    rKp_DO                  : REAL := 0.85;
    rKi_DO                  : REAL := 0.02;
    rKd_DO                  : REAL := 0.15;

    rMaxShearStress         : REAL := 0.18; (* Max allowable shear stress for CHO cells *)
    rGasHoldupFraction      : REAL := 0.0;

    rPowerNumber_Imp1       : REAL := 1.5;
    rPowerNumber_Imp2       : REAL := 1.2;
    rImpellerDiameter       : REAL := 0.65; (* m *)
    rDensityMedia           : REAL := 1025.0; (* kg/m3 *)
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Interlock Processing *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rO2_SpargingFlow := 0.0;
    rCO2_SpargingFlow := 0.0;
    rAgitation_CmdRPM := 0.0;
    rFeed_RateOut := 0.0;
    iState := 999; (* E-STOP STATE *)
    RETURN;
END_IF;

(* Continuous Shear Stress Estimation *)
(* P = Np * rho * N^3 * D^5 *)
rShearStress_Estimated := (rPowerNumber_Imp1 * rDensityMedia * (rImpeller1_SpeedRPM / 60.0) * (rImpeller1_SpeedRPM / 60.0) * (rImpeller1_SpeedRPM / 60.0) * rImpellerDiameter * rImpellerDiameter * rImpellerDiameter * rImpellerDiameter * rImpellerDiameter) * 0.01;

(* Trans-Membrane Pressure (TMP) Calculation *)
rTMP_Actual := ((rHollowFiber_FeedPress + rHollowFiber_RetPress) / 2.0) - rHollowFiber_PermPress;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rO2_SpargingFlow := 0.0;
        rCO2_SpargingFlow := 0.0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* WARM-UP & SENSOR VERIFICATION *)
        (* Simulating a sensor stabilization wait time *)
        tProcessTimer(IN := TRUE, PT := T#30S);
        IF tProcessTimer.Q THEN
            tProcessTimer(IN := FALSE);
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* ACTIVE CULTURE / PERFUSION CONTROL *)

        (* --- DO Cascade Control with Micro-sparger holdup compensation --- *)
        rError_DO := 40.0 - rDO_Measured; (* Target 40% DO *)
        rIntegral_DO := rIntegral_DO + rError_DO;
        rDerivative_DO := rError_DO - rPrevError_DO;

        rO2_SpargingFlow := (rKp_DO * rError_DO) + (rKi_DO * rIntegral_DO) + (rKd_DO * rDerivative_DO);

        IF rO2_SpargingFlow > 20.0 THEN
            rO2_SpargingFlow := 20.0;
        ELSIF rO2_SpargingFlow < 0.0 THEN
            rO2_SpargingFlow := 0.0;
        END_IF;
        rPrevError_DO := rError_DO;

        (* --- pH Control via CO2 Sparging --- *)
        rError_pH := rpH_Measured - 7.10; (* Target pH 7.10 *)
        IF rError_pH > 0.05 THEN
            rCO2_SpargingFlow := rError_pH * 5.0; (* Proportional gain for CO2 *)
        ELSE
            rCO2_SpargingFlow := 0.0;
        END_IF;

        (* --- Nutrient Feed Rate based on Viable Cell Density (VCD) --- *)
        IF rBiomass_ViableDensity > 2.0 THEN
            rFeed_RateOut := rBiomass_ViableDensity * 0.15; (* 0.15 mL/min per 10^6 cells/mL *)
        ELSE
            rFeed_RateOut := 0.5; (* Base feed rate *)
        END_IF;

        (* --- High TMP Alarm Logic --- *)
        IF rTMP_Actual > 1.2 THEN
            bAlarm := TRUE;
            (* Filter fouling potential, scale back feed *)
            rFeed_RateOut := rFeed_RateOut * 0.5;
        ELSE
            bAlarm := FALSE;
        END_IF;

        (* --- Shear Stress Constraint --- *)
        IF rShearStress_Estimated > rMaxShearStress THEN
            rAgitation_CmdRPM := rImpeller1_SpeedRPM - 5.0; (* Demand lower RPM from master drive *)
        ELSE
            rAgitation_CmdRPM := rImpeller1_SpeedRPM;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
            tProcessTimer(IN := FALSE);
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        IF bEmergencyStop AND NOT bEnable THEN
            iState := 0; (* Reset required *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
