FUNCTION_BLOCK FB_JackUpRig_4LegSyncControl
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnableOperation        : BOOL;     (* System master enable, requires safety OK *)
    bEmergencyStop          : BOOL;     (* E-stop string health, TRUE = Healthy *)
    rLeg1PenetrationForce   : REAL;     (* Feedback force for Leg 1 penetration (kN) *)
    rLeg2PenetrationForce   : REAL;     (* Feedback force for Leg 2 penetration (kN) *)
    rLeg3PenetrationForce   : REAL;     (* Feedback force for Leg 3 penetration (kN) *)
    rLeg4PenetrationForce   : REAL;     (* Feedback force for Leg 4 penetration (kN) *)
    rVesselPitch            : REAL;     (* Gyroscopic pitch measurement (Degrees) *)
    rVesselRoll             : REAL;     (* Gyroscopic roll measurement (Degrees) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* System is ready for jacking operations *)
    rLeg1LiftSpeedCmd       : REAL;     (* Command speed for Leg 1 VFD (m/s) *)
    rLeg2LiftSpeedCmd       : REAL;     (* Command speed for Leg 2 VFD (m/s) *)
    rLeg3LiftSpeedCmd       : REAL;     (* Command speed for Leg 3 VFD (m/s) *)
    rLeg4LiftSpeedCmd       : REAL;     (* Command speed for Leg 4 VFD (m/s) *)
    bPunchThroughAlarm      : BOOL;     (* Critical alarm for sudden soil failure *)
END_VAR
VAR
    (* Internal state variables *)
    iOperationState         : INT := 0;
    rAverageForce           : REAL := 0.0;
    rMaxAllowedForceDev     : REAL := 500.0; (* Max allowable force deviation in kN *)
    tLegMonitorTimer        : TON;
    tSafetyDelay            : TON;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bPunchThroughAlarm := TRUE;
    rLeg1LiftSpeedCmd := 0.0;
    rLeg2LiftSpeedCmd := 0.0;
    rLeg3LiftSpeedCmd := 0.0;
    rLeg4LiftSpeedCmd := 0.0;
    RETURN;
END_IF;

CASE iOperationState OF
    0: (* IDLE & SAFETY CHECK *)
        bSystemReady := FALSE;
        bPunchThroughAlarm := FALSE;
        rLeg1LiftSpeedCmd := 0.0;
        rLeg2LiftSpeedCmd := 0.0;
        rLeg3LiftSpeedCmd := 0.0;
        rLeg4LiftSpeedCmd := 0.0;
        IF bEnableOperation THEN
            tSafetyDelay(IN := TRUE, PT := T#2S);
            IF tSafetyDelay.Q THEN
                iOperationState := 10;
                tSafetyDelay(IN := FALSE);
            END_IF;
        ELSE
            tSafetyDelay(IN := FALSE);
        END_IF;

    10: (* SYNCHRONOUS JACKING - NORMAL OPERATION *)
        bSystemReady := TRUE;

        (* Calculate average penetration force *)
        rAverageForce := (rLeg1PenetrationForce + rLeg2PenetrationForce + rLeg3PenetrationForce + rLeg4PenetrationForce) / 4.0;

        (* Dynamic Punch-Through Mitigation: Check for sudden drops in force relative to average *)
        IF (rAverageForce - rLeg1PenetrationForce > rMaxAllowedForceDev) OR 
           (rAverageForce - rLeg2PenetrationForce > rMaxAllowedForceDev) OR
           (rAverageForce - rLeg3PenetrationForce > rMaxAllowedForceDev) OR
           (rAverageForce - rLeg4PenetrationForce > rMaxAllowedForceDev) THEN
            iOperationState := 99; (* Transition to fault state *)
        ELSE
            (* Apply proportional PID adjustments based on vessel Pitch and Roll to maintain level *)
            rLeg1LiftSpeedCmd := 0.02 - (rVesselPitch * 0.005) - (rVesselRoll * 0.005);
            rLeg2LiftSpeedCmd := 0.02 - (rVesselPitch * 0.005) + (rVesselRoll * 0.005);
            rLeg3LiftSpeedCmd := 0.02 + (rVesselPitch * 0.005) - (rVesselRoll * 0.005);
            rLeg4LiftSpeedCmd := 0.02 + (rVesselPitch * 0.005) + (rVesselRoll * 0.005);
        END_IF;

        IF NOT bEnableOperation THEN
            iOperationState := 0;
        END_IF;

    99: (* PUNCH-THROUGH FAULT STATE *)
        bSystemReady := FALSE;
        bPunchThroughAlarm := TRUE;

        (* Immediately halt all jacking drives to prevent structural damage *)
        rLeg1LiftSpeedCmd := 0.0;
        rLeg2LiftSpeedCmd := 0.0;
        rLeg3LiftSpeedCmd := 0.0;
        rLeg4LiftSpeedCmd := 0.0;

        (* Operator must manually reset the system by toggling Enable *)
        IF NOT bEnableOperation THEN
            iOperationState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
