FUNCTION_BLOCK FB_PEM_Electrolyzer_PtG
VAR_INPUT
    bSystemEnable : BOOL;       (* Main start/stop command *)
    bReset : BOOL;              (* Fault reset command *)
    rStackVoltage : REAL;       (* Stack voltage [V] *)
    rStackCurrent : REAL;       (* Stack current [A] *)
    rDIWaterFlowRate : REAL;    (* DI water flow rate [L/min] *)
    rDIWaterInletTemp : REAL;   (* DI water inlet temp [C] *)
    rH2Pressure : REAL;         (* Hydrogen pressure [bar] *)
    rO2Pressure : REAL;         (* Oxygen pressure [bar] *)
    rH2inO2_LEL_Pct : REAL;     (* H2 concentration in O2 [%] *)
    rO2inH2_LEL_Pct : REAL;     (* O2 concentration in H2 [%] *)
    rMembraneTemp_Avg : REAL;   (* Average PEM temperature [C] *)
END_VAR
VAR_OUTPUT
    bRectifierEnable : BOOL;    (* Rectifier active *)
    rRectifierDemand : REAL;    (* Rectifier setpoint 0-100% *)
    rDIWaterPumpSpeed : REAL;   (* Water circulation pump 0-100% *)
    rCoolingValvePos : REAL;    (* Heat exchanger valve 0-100% *)
    bEmergencyStop : BOOL;      (* E-Stop interlock *)
    dwFaultCode : DWORD;        (* Bitfield of faults *)
    uiOperationState : UINT;    (* 0:Off, 10:Purge, 20:Ramp, 30:Run, 40:Cooldown, 99:Fault *)
END_VAR
VAR
    rActiveArea_cm2 : REAL := 150000.0; (* 15m2 stack area *)
    rCurrentDensity : REAL;             (* Calculated A/cm2 *)
    rMaxCurrentDensity : REAL := 3.0;   (* Max safe density *)

    rCrossoverLimit_Alarm : REAL := 1.5; (* 1.5% LEL warning *)
    rCrossoverLimit_Trip : REAL := 2.0;  (* 2.0% LEL trip *)

    rTargetTemp : REAL := 70.0;          (* Optimal PEM temp *)
    rTempError : REAL;
    rTempKp : REAL := 2.5;
    rTempKi : REAL := 0.15;
    rTempIntegral : REAL;
    rMaxTemp : REAL := 85.0;

    tmrStateTransit : TON;
    tmrPurge : TON;
END_VAR

(* 1. Calculate Current Density and check limits *)
IF rActiveArea_cm2 > 0.0 THEN
    rCurrentDensity := rStackCurrent / rActiveArea_cm2;
ELSE
    rCurrentDensity := 0.0;
END_IF;

(* 2. Critical Safety: Gas Crossover Monitoring *)
bEmergencyStop := FALSE;
dwFaultCode.0 := FALSE;
dwFaultCode.1 := FALSE;

IF rH2inO2_LEL_Pct >= rCrossoverLimit_Trip THEN
    dwFaultCode.0 := TRUE; (* H2 in O2 crossover critical *)
    bEmergencyStop := TRUE;
ELSIF rH2inO2_LEL_Pct >= rCrossoverLimit_Alarm THEN
    (* Alarm logic could go here *)
END_IF;

IF rO2inH2_LEL_Pct >= rCrossoverLimit_Trip THEN
    dwFaultCode.1 := TRUE; (* O2 in H2 crossover critical *)
    bEmergencyStop := TRUE;
END_IF;

(* 3. Critical Safety: Membrane Thermal Overload *)
IF rMembraneTemp_Avg > rMaxTemp THEN
    dwFaultCode.2 := TRUE; (* Stack overtemp *)
    bEmergencyStop := TRUE;
END_IF;

IF rCurrentDensity > rMaxCurrentDensity THEN
    dwFaultCode.3 := TRUE; (* Density violation *)
    bEmergencyStop := TRUE;
END_IF;

(* 4. State Machine & PID Control *)
IF bEmergencyStop THEN
    uiOperationState := 99;
    bRectifierEnable := FALSE;
    rRectifierDemand := 0.0;
    rDIWaterPumpSpeed := 100.0; (* Max cooling on fault *)
    rCoolingValvePos := 100.0;
ELSIF NOT bSystemEnable AND uiOperationState <> 99 THEN
    uiOperationState := 0;
    bRectifierEnable := FALSE;
    rRectifierDemand := 0.0;
    rDIWaterPumpSpeed := 0.0;
    rCoolingValvePos := 0.0;
ELSE
    CASE uiOperationState OF
        0: (* Off to Purge *)
            IF bSystemEnable THEN
                uiOperationState := 10;
            END_IF;

        10: (* N2 / DI Water Purge phase *)
            rDIWaterPumpSpeed := 50.0;
            tmrPurge(IN:=TRUE, PT:=T#30S);
            IF tmrPurge.Q THEN
                tmrPurge(IN:=FALSE);
                uiOperationState := 20;
            END_IF;

        20: (* Ramp-Up phase *)
            bRectifierEnable := TRUE;
            rRectifierDemand := rRectifierDemand + 0.1;
            rDIWaterPumpSpeed := 75.0;
            IF rRectifierDemand >= 50.0 THEN
                uiOperationState := 30;
            END_IF;

        30: (* Production Run Phase - Thermal Management *)
            rRectifierDemand := 100.0; 

            (* Thermal PID Loop for DI Water Loop *)
            rTempError := rMembraneTemp_Avg - rTargetTemp;
            rTempIntegral := rTempIntegral + (rTempError * 0.1); (* Assuming 100ms task *)

            (* Anti-windup *)
            IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
            IF rTempIntegral < 0.0 THEN rTempIntegral := 0.0; END_IF;

            rCoolingValvePos := (rTempKp * rTempError) + (rTempKi * rTempIntegral);

            (* Clamp valve output *)
            IF rCoolingValvePos > 100.0 THEN rCoolingValvePos := 100.0; END_IF;
            IF rCoolingValvePos < 0.0 THEN rCoolingValvePos := 0.0; END_IF;

            (* Optimize pump speed based on gradient *)
            rDIWaterPumpSpeed := 80.0 + (rTempError * 2.0);
            IF rDIWaterPumpSpeed > 100.0 THEN rDIWaterPumpSpeed := 100.0; END_IF;
            IF rDIWaterPumpSpeed < 20.0 THEN rDIWaterPumpSpeed := 20.0; END_IF;

        99: (* Faulted - Requires Reset *)
            IF bReset AND NOT bEmergencyStop THEN
                dwFaultCode := 0;
                uiOperationState := 0;
            END_IF;

    END_CASE;
END_IF;
END_FUNCTION_BLOCK
