FUNCTION_BLOCK FB_ICF_CryoTargetSync
TITLE = 'ICF Cryogenic Target Injection and Laser Synchronization'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    Enable : BOOL; // System master enable
    MasterClock_ns : LINT; // Master system clock in nanoseconds
    PelletPosition_X : REAL; // Current target pellet X position (um)
    PelletPosition_Y : REAL; // Current target pellet Y position (um)
    PelletPosition_Z : REAL; // Current target pellet Z position (um)
    PelletVelocity_Z : REAL; // Pellet injection velocity in Z-axis (um/ns)
    CryoTemp_mK : REAL; // Cryogenic pellet temperature in milliKelvin
    TargetChamberVacuum_Torr : REAL; // Chamber vacuum pressure
    LaserBankReady : ARRAY[0..191] OF BOOL; // Readiness state of all 192 laser beams
    CapacitorCharge_kV : ARRAY[0..191] OF REAL; // Energy storage capacitor voltage per beam
END_VAR

VAR_OUTPUT
    SystemState : INT; // 0=Idle, 1=Injection, 2=Tracking, 3=Ignition, 99=Abort
    FireCommand : BOOL; // Master trigger for ignition sequence
    LaserTriggerDelay_ns : ARRAY[0..191] OF INT; // Individual nanosecond delay adjustments for beam synchronization
    TargetingPitch_urad : REAL; // Beam alignment mirror pitch correction
    TargetingYaw_urad : REAL; // Beam alignment mirror yaw correction
    AbortActive : BOOL; // System abort flag
    DiagnosticMsg : STRING[255]; // Human-readable status or error code
END_VAR

VAR
    i : INT;
    TotalReadyBeams : INT;
    EstimatedImpactTime_ns : LINT;
    FlightDistanceRemaining : REAL;
    TargetLocationCenter : REAL := 0.0; // Chamber absolute center is 0,0,0
    MaxTemp_mK : REAL := 18.5; // Maximum allowed DT ice temp
    MinVacuum_Torr : REAL := 1.0E-6;
    RequiredCharge_kV : REAL := 22.0; // Minimum voltage for main amplifier flashlamps
    LaserPathLength_mm : ARRAY[0..191] OF REAL; // Path lengths from master oscillator to chamber center
    SpeedOfLight_um_ns : REAL := 299.792458; // Speed of light in micrometers per nanosecond
    BasePropagationTime_ns : ARRAY[0..191] OF REAL;
    MaxPropagationTime_ns : REAL;
    NominalFlightTime : REAL;
END_VAR

// ==============================================================================
// ICF Target Tracking and Laser Synchronization Algorithm
// ==============================================================================

IF NOT Enable THEN
    SystemState := 0;
    FireCommand := FALSE;
    AbortActive := FALSE;
    DiagnosticMsg := 'System Disabled.';
    RETURN;
END_IF;

// Safety and Environmental Checks
IF CryoTemp_mK > MaxTemp_mK THEN
    SystemState := 99;
    AbortActive := TRUE;
    DiagnosticMsg := 'ABORT: Cryo temperature exceeds DT phase transition limit.';
    RETURN;
END_IF;

IF TargetChamberVacuum_Torr > MinVacuum_Torr THEN
    SystemState := 99;
    AbortActive := TRUE;
    DiagnosticMsg := 'ABORT: Chamber vacuum insufficient for high-energy propagation.';
    RETURN;
END_IF;

// Laser Readiness Aggregation
TotalReadyBeams := 0;
FOR i := 0 TO 191 DO
    IF LaserBankReady[i] AND (CapacitorCharge_kV[i] >= RequiredCharge_kV) THEN
        TotalReadyBeams := TotalReadyBeams + 1;
    END_IF;
END_FOR;

IF TotalReadyBeams < 190 THEN // Allow up to 2 dropped beams out of 192
    SystemState := 99;
    AbortActive := TRUE;
    DiagnosticMsg := 'ABORT: Insufficient laser beams fully charged and ready.';
    RETURN;
END_IF;

// Target Flight Path and Impact Time Calculation
FlightDistanceRemaining := ABS(PelletPosition_Z - TargetLocationCenter);

IF PelletVelocity_Z > 0.0 THEN
    NominalFlightTime := FlightDistanceRemaining / PelletVelocity_Z;
    EstimatedImpactTime_ns := MasterClock_ns + REAL_TO_LINT(NominalFlightTime);
    SystemState := 2; // Tracking
ELSE
    SystemState := 99;
    AbortActive := TRUE;
    DiagnosticMsg := 'ABORT: Invalid pellet velocity (zero or negative).';
    RETURN;
END_IF;

// Real-Time Targeting Correction (Pitch & Yaw)
// Applying proportional correction to mirror alignment based on X/Y deviations from perfect center axis
TargetingPitch_urad := PelletPosition_Y * -0.5; // Arbitrary gain factor for P-control
TargetingYaw_urad := PelletPosition_X * 0.5;

// Determine Base Propagation Times for nanosecond synchronization
MaxPropagationTime_ns := 0.0;
FOR i := 0 TO 191 DO
    // Mocking path length data (in a real system this would be read from EEPROM/Config)
    LaserPathLength_mm[i] := 125000.0 + INT_TO_REAL(i * 10); // Around 125 meters
    BasePropagationTime_ns[i] := (LaserPathLength_mm[i] * 1000.0) / SpeedOfLight_um_ns;

    IF BasePropagationTime_ns[i] > MaxPropagationTime_ns THEN
        MaxPropagationTime_ns := BasePropagationTime_ns[i];
    END_IF;
END_FOR;

// Calculate individual beam trigger delays to ensure simultaneous target impact
FOR i := 0 TO 191 DO
    LaserTriggerDelay_ns[i] := REAL_TO_INT(MaxPropagationTime_ns - BasePropagationTime_ns[i]);
END_FOR;

// Ignition Sequence
// If the target is less than 10ns away from chamber center, execute FIRE sequence
IF NominalFlightTime <= 10.0 THEN
    SystemState := 3; // Ignition
    FireCommand := TRUE;
    DiagnosticMsg := 'IGNITION SEQUENCE TRIGGERED';
ELSE
    FireCommand := FALSE;
    DiagnosticMsg := 'Target in flight, tracking nominal...';
END_IF;

END_FUNCTION_BLOCK
