FUNCTION_BLOCK FB_RTP_AnnealingFurnace
VAR_INPUT
    (* Physical Inputs for Rapid Thermal Processing *)
    bEnable                 : BOOL;     (* System enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal - Active High *)
    rTempPyrometerCenter    : REAL;     (* Center zone pyrometer temperature in DegC *)
    rTempPyrometerEdge      : REAL;     (* Edge zone pyrometer temperature in DegC *)
    rTargetTemp             : REAL;     (* Target soak temperature in DegC (e.g. 1050.0) *)
    rRampRateSec            : REAL;     (* Target ramp rate in DegC per second (e.g. 150.0) *)
    bWaferLoaded            : BOOL;     (* Wafer presence sensor *)
    bChamberVacuumOK        : BOOL;     (* High vacuum pressure OK signal *)
END_VAR
VAR_OUTPUT
    (* Control Outputs for Lamp and System Status *)
    bSystemReady            : BOOL;     (* System ready for RTP process *)
    rLampPowerCenter        : REAL;     (* 0-100% Tungsten-Halogen lamp array center power *)
    rLampPowerEdge          : REAL;     (* 0-100% Tungsten-Halogen lamp array edge power *)
    bProcessComplete        : BOOL;     (* Annealing process finished normally *)
    bAlarm                  : BOOL;     (* Critical fault alarm output *)
    iErrorCode              : INT;      (* Detailed error code for HMI *)
END_VAR
VAR
    (* Internal state variables, timers, and PID loops *)
    iState                  : INT := 0; (* Process state machine *)
    tSoakTimer              : TON;      (* Timer for thermal soak phase *)
    rCurrentSetpoint        : REAL;     (* Dynamically calculated ramp setpoint *)
    rGradient               : REAL;     (* Center to Edge temperature delta *)
    rMaxGradient            : REAL := 15.0; (* Maximum allowed delta to prevent wafer slip *)
    rKp_Center              : REAL := 2.5;  (* PID Proportional Gain - Center *)
    rKp_Edge                : REAL := 2.8;  (* PID Proportional Gain - Edge *)
    rErrorCenter            : REAL;
    rErrorEdge              : REAL;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Hard Stops *)
IF NOT bEmergencyStop OR NOT bChamberVacuumOK THEN
    bSystemReady := FALSE;
    bProcessComplete := FALSE;
    bAlarm := TRUE;
    iErrorCode := 1; (* 1 = Safety Interlock Tripped *)
    rLampPowerCenter := 0.0;
    rLampPowerEdge := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* Calculate dynamic temperature gradient to monitor for thermal slip conditions *)
rGradient := ABS(rTempPyrometerCenter - rTempPyrometerEdge);
IF rGradient > rMaxGradient AND iState > 10 AND iState < 99 THEN
    bAlarm := TRUE;
    iErrorCode := 2; (* 2 = Excessive Thermal Gradient - Wafer Slip Risk *)
    iState := 99; (* Abort Process *)
END_IF;

(* 2. Process State Machine *)
CASE iState OF
    0: (* IDLE *)
        rLampPowerCenter := 0.0;
        rLampPowerEdge := 0.0;
        bProcessComplete := FALSE;
        bAlarm := FALSE;
        iErrorCode := 0;

        IF bWaferLoaded THEN
            bSystemReady := TRUE;
            IF bEnable THEN
                bSystemReady := FALSE;
                rCurrentSetpoint := rTempPyrometerCenter; (* Start from current temp *)
                iState := 10;
            END_IF;
        ELSE
            bSystemReady := FALSE;
        END_IF;

    10: (* ULTRA-FAST RAMP UP - Pyrometric Cascading *)
        (* Simulate an incredibly aggressive ramp rate, adding Delta T per PLC cycle. *)
        (* Assuming 10ms task cycle, increment setpoint by rRampRateSec * 0.01 *)
        rCurrentSetpoint := rCurrentSetpoint + (rRampRateSec * 0.01);

        IF rCurrentSetpoint >= rTargetTemp THEN
            rCurrentSetpoint := rTargetTemp;
            iState := 20;
        END_IF;

        (* P-Only Control (simplified for example) with Edge Compensation *)
        rErrorCenter := rCurrentSetpoint - rTempPyrometerCenter;
        rErrorEdge := rCurrentSetpoint - rTempPyrometerEdge;

        rLampPowerCenter := rErrorCenter * rKp_Center;
        rLampPowerEdge := rErrorEdge * rKp_Edge;

        (* Clamp Outputs *)
        IF rLampPowerCenter > 100.0 THEN rLampPowerCenter := 100.0; END_IF;
        IF rLampPowerCenter < 0.0 THEN rLampPowerCenter := 0.0; END_IF;
        IF rLampPowerEdge > 100.0 THEN rLampPowerEdge := 100.0; END_IF;
        IF rLampPowerEdge < 0.0 THEN rLampPowerEdge := 0.0; END_IF;

    20: (* SOAK / STEADY STATE *)
        rErrorCenter := rTargetTemp - rTempPyrometerCenter;
        rErrorEdge := rTargetTemp - rTempPyrometerEdge;

        (* Lower steady-state gains for precision +/- 0.5C stability *)
        rLampPowerCenter := rErrorCenter * (rKp_Center * 0.5);
        rLampPowerEdge := rErrorEdge * (rKp_Edge * 0.5);

        (* Clamp Outputs *)
        IF rLampPowerCenter > 100.0 THEN rLampPowerCenter := 100.0; END_IF;
        IF rLampPowerCenter < 0.0 THEN rLampPowerCenter := 0.0; END_IF;
        IF rLampPowerEdge > 100.0 THEN rLampPowerEdge := 100.0; END_IF;
        IF rLampPowerEdge < 0.0 THEN rLampPowerEdge := 0.0; END_IF;

        tSoakTimer(IN := TRUE, PT := T#10S); (* Short 10s RTP anneal soak *)
        IF tSoakTimer.Q THEN
            tSoakTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* CONTROLLED RAMP DOWN / COOLING *)
        (* Lamp power cuts off, nitrogen cooling typically takes over, simulated here as 0% power *)
        rLampPowerCenter := 0.0;
        rLampPowerEdge := 0.0;

        IF rTempPyrometerCenter < 200.0 THEN
            bProcessComplete := TRUE;
            IF NOT bEnable THEN
                iState := 0;
            END_IF;
        END_IF;

    99: (* FAULT / ABORT *)
        rLampPowerCenter := 0.0;
        rLampPowerEdge := 0.0;
        IF NOT bEnable THEN
            bAlarm := FALSE;
            iErrorCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
