FUNCTION_BLOCK FB_SST_Core_Controller
TITLE = 'Utility-Scale Solid State Transformer Control'
VERSION : '2.5'
AUTHOR : 'Lumina AI Swarm'

VAR_INPUT
    Enable : BOOL; // System enable command
    MVAC_Voltage_kV : REAL; // Medium Voltage AC input (kV)
    MVAC_Current_A : REAL; // Medium Voltage AC current (A)
    LVDC_Voltage_Ref : REAL; // Low Voltage DC reference setpoint (V)
    LVDC_Voltage_Act : REAL; // Low Voltage DC actual measurement (V)
    DAB_Power_Cmd_kW : REAL; // Dual Active Bridge power command (kW)
    Grid_Freq_Hz : REAL; // Grid frequency measurement (Hz)
    IGBT_Temp_1_C : REAL; // Highest IGBT junction temperature module 1
    IGBT_Temp_2_C : REAL; // Highest IGBT junction temperature module 2
    Coolant_Flow_LPM : REAL; // Coolant flow rate (L/min)
    Fault_Reset : BOOL; // Fault reset command
END_VAR

VAR_OUTPUT
    System_Ready : BOOL;
    DAB_Phase_Shift_Rad : REAL; // Phase shift angle for DAB switching
    Active_Power_kW : REAL; // Delivered active power
    Reactive_Power_kVAR : REAL; // Delivered reactive power
    IGBT_Derating_Factor : REAL; // Active thermal derating multiplier
    Cooling_Pump_Cmd : REAL; // 0-100% cooling pump speed command
    PWM_Enable : BOOL; // Hardware enable for gate drivers
    Fault_Active : BOOL; // Global fault indicator
    Fault_Code : WORD; // Diagnostic fault code
END_VAR

VAR
    State : INT := 0; // State machine state
    Voltage_Error : REAL;
    Voltage_Integral : REAL := 0.0;
    PI_Kp : REAL := 1.25;
    PI_Ki : REAL := 0.05;
    Max_Phase_Shift : REAL := 1.5708; // Pi/2
    Min_Phase_Shift : REAL := -1.5708;
    Temp_Max : REAL;
    Derating_Threshold : REAL := 85.0; // Celsius
    Critical_Temp : REAL := 115.0; // Celsius
    Timer_Precharge : TON;
    Precharge_Time : TIME := T#5S;
    DAB_Power_Limit : REAL;
END_VAR

// Control Logic
IF Fault_Reset THEN
    Fault_Active := FALSE;
    Fault_Code := 16#0000;
    State := 0;
END_IF

// Thermal Management & Derating
Temp_Max := MAX(IGBT_Temp_1_C, IGBT_Temp_2_C);

IF Temp_Max > Critical_Temp THEN
    Fault_Active := TRUE;
    Fault_Code := 16#F001; // Thermal overload critical
    State := 99; // Fault state
ELSIF Temp_Max > Derating_Threshold THEN
    IGBT_Derating_Factor := 1.0 - ((Temp_Max - Derating_Threshold) * 0.025);
    IGBT_Derating_Factor := MAX(IGBT_Derating_Factor, 0.1);
ELSE
    IGBT_Derating_Factor := 1.0;
END_IF

// Cooling control
IF Temp_Max > 50.0 THEN
    Cooling_Pump_Cmd := MIN((Temp_Max - 50.0) * 2.0 + 30.0, 100.0);
ELSE
    Cooling_Pump_Cmd := 20.0; // Idle cooling
END_IF

IF Coolant_Flow_LPM < 5.0 AND PWM_Enable THEN
    Fault_Active := TRUE;
    Fault_Code := 16#F002; // Loss of coolant
    State := 99;
END_IF

// State Machine
CASE State OF
    0: // OFF
        System_Ready := FALSE;
        PWM_Enable := FALSE;
        DAB_Phase_Shift_Rad := 0.0;
        Voltage_Integral := 0.0;
        IF Enable AND NOT Fault_Active THEN
            State := 10;
        END_IF

    10: // PRECHARGE
        Timer_Precharge(IN := TRUE, PT := Precharge_Time);
        IF Timer_Precharge.Q THEN
            Timer_Precharge(IN := FALSE);
            State := 20;
        END_IF

    20: // ACTIVE
        System_Ready := TRUE;
        PWM_Enable := TRUE;

        // Voltage PI Control for DAB
        Voltage_Error := LVDC_Voltage_Ref - LVDC_Voltage_Act;
        Voltage_Integral := Voltage_Integral + (Voltage_Error * PI_Ki);

        // Anti-windup
        IF Voltage_Integral > Max_Phase_Shift THEN
            Voltage_Integral := Max_Phase_Shift;
        ELSIF Voltage_Integral < Min_Phase_Shift THEN
            Voltage_Integral := Min_Phase_Shift;
        END_IF

        // Calculate raw phase shift
        DAB_Phase_Shift_Rad := (Voltage_Error * PI_Kp) + Voltage_Integral;

        // Apply Power Limit and Thermal Derating
        DAB_Power_Limit := DAB_Power_Cmd_kW * IGBT_Derating_Factor;

        // Limit phase shift based on derated power
        IF DAB_Phase_Shift_Rad > Max_Phase_Shift THEN
            DAB_Phase_Shift_Rad := Max_Phase_Shift;
        ELSIF DAB_Phase_Shift_Rad < Min_Phase_Shift THEN
            DAB_Phase_Shift_Rad := Min_Phase_Shift;
        END_IF

        // Simulated output calculation
        Active_Power_kW := DAB_Power_Limit * ABS(SIN(DAB_Phase_Shift_Rad));

        IF NOT Enable THEN
            State := 0;
        END_IF

    99: // FAULT
        System_Ready := FALSE;
        PWM_Enable := FALSE;
        DAB_Phase_Shift_Rad := 0.0;
        Active_Power_kW := 0.0;
END_CASE
END_FUNCTION_BLOCK
