        IF ABS(rClawAxis1_Pos - rTargetX) < 2.0 AND ABS(rClawAxis2_Pos - rTargetY) < 2.0 THEN iState := 3; tEviscerationTimer(IN:=FALSE); END_IF;
    3:
        xClawEngage := TRUE; xVacuumEnable := TRUE; tEviscerationTimer(IN:=TRUE, PT:=T#800MS);
        rClawAxis4_Cmd := 85.0; rClawAxis1_Cmd := rTargetX - 30.0;
        IF tEviscerationTimer.Q THEN xVacuumEnable := FALSE; iState := 4; END_IF;
    4:
        xClawEngage := FALSE; rClawAxis1_Cmd := 0.0; rClawAxis2_Cmd := 0.0; rClawAxis3_Cmd := 0.0; rClawAxis4_Cmd := 0.0;
        IF ABS(rClawAxis1_Pos) < 2.0 AND ABS(rClawAxis2_Pos) < 2.0 THEN iState := 1; END_IF;
    10:
        xHeaterEnable := TRUE; xPumpEnable := FALSE; xValveOpen := FALSE;
        IF rWaterTemp > 80.0 THEN iState := 11; tCIP_PhaseTimer(IN:=FALSE); END_IF;
    11:
        xPumpEnable := TRUE; xValveOpen := TRUE; tCIP_PhaseTimer(IN:=TRUE, PT:=T#5M);
        IF rWaterPressure < 2.5 THEN xFault := TRUE; iFaultCode := 101; END_IF;
        IF tCIP_PhaseTimer.Q THEN iState := 12; tCIP_PhaseTimer(IN:=FALSE); END_IF;
    12:
        xHeaterEnable := FALSE; tCIP_PhaseTimer(IN:=TRUE, PT:=T#2M);
        IF tCIP_PhaseTimer.Q THEN
            xPumpEnable := FALSE; xValveOpen := FALSE;
            IF NOT xCIP_Mode THEN iState := 0; END_IF;
        END_IF;
    ELSE iState := 0;
END_CASE;
END_FUNCTION_BLOCK\n```
