FUNCTION_BLOCK FB_ALD_ChamberControl
VAR_INPUT
    (* System & Safety Interlocks *)
    bEnableSystem       : BOOL;     (* Main sequence enable from fab host *)
    bEmergencyStop      : BOOL;     (* Hardwired E-Stop safety relay OK signal *)
    bVacuumInterlockOK  : BOOL;     (* Foreline and turbo pump status OK *)
    bGasScrubberOK      : BOOL;     (* Abatement system ready for toxic gases *)

    (* Process Variables - Metrology & Sensors *)
    rPlatenTemp_C       : REAL;     (* 300mm wafer platen thermocouple reading (deg C) *)
    rChamberPressure_mT : REAL;     (* Baratron capacitance manometer (mTorr) *)
    rTMAMassFlow_sccm   : REAL;     (* Trimethylaluminum precursor MFC feedback *)
    rH2OMassFlow_sccm   : REAL;     (* Oxidant (Water) precursor MFC feedback *)
    rPurgeN2_sccm       : REAL;     (* Purge nitrogen flow rate (sccm) *)

    (* Recipe Parameters *)
    iTargetCycles       : INT;      (* Number of ALD cycles to execute *)
    rTargetTemp_C       : REAL;     (* Platen setpoint temperature (deg C) *)
END_VAR

VAR_OUTPUT
    (* System Status *)
    bSystemReady        : BOOL;     (* System at base pressure and target temp, ready for recipe *)
    bCycleActive        : BOOL;     (* ALD pulse/purge cycle in progress *)
    iCompletedCycles    : INT;      (* Counter for finished ALD cycles *)
    bProcessComplete    : BOOL;     (* Full recipe completed successfully *)

    (* Actuator Commands *)
    bValveTMA_Open      : BOOL;     (* ALD fast-acting pneumatic valve for TMA *)
    bValveH2O_Open      : BOOL;     (* ALD fast-acting pneumatic valve for H2O *)
    bValveN2Purge_Open  : BOOL;     (* Purge gas isolation valve *)
    rHeaterPower_Pct    : REAL;     (* PID output for platen multi-zone heater *)
    rThrottleValve_Pos  : REAL;     (* Butterfly throttle valve position for conductance/pressure control *)

    (* Alarms & Diagnostics *)
    bAlarm              : BOOL;     (* General fault alarm output *)
    iErrorCode          : INT;      (* 0 = None, 1 = Interlock, 2 = Temp, 3 = Pressure, 4 = Flow *)
END_VAR

VAR
    (* State Machine *)
    iState              : INT := 0; (* Main ALD sequence state *)

    (* Internal Timers (sub-second accuracy required for ALD) *)
    tPulseTimer         : TON;
    tPurgeTimer         : TON;
    tTempStabilize      : TON;

    (* Process Control Variables *)
    rTempError          : REAL;
    rTempIntegral       : REAL;
    rPressureError      : REAL;
    bTempInBand         : BOOL;
    bPressureInBand     : BOOL;

    (* Constants *)
    TMA_PULSE_TIME      : TIME := T#150MS;
    H2O_PULSE_TIME      : TIME := T#200MS;
    PURGE_TIME          : TIME := T#2S;
    TEMP_TOLERANCE      : REAL := 0.5; (* +/- 0.5 deg C *)
    BASE_PRESSURE_MT    : REAL := 50.0; 
END_VAR

(* === MAIN SAFETY & INTERLOCK LOGIC === *)
IF NOT bEmergencyStop OR NOT bVacuumInterlockOK OR NOT bGasScrubberOK THEN
    (* Fail-safe state: close all valves, disable heater, open throttle for max conductance *)
    bValveTMA_Open      := FALSE;
    bValveH2O_Open      := FALSE;
    bValveN2Purge_Open  := TRUE;  (* Flood with N2 to prevent backstreaming *)
    rHeaterPower_Pct    := 0.0;
    rThrottleValve_Pos  := 100.0; (* Full open to pumps *)

    bSystemReady        := FALSE;
    bCycleActive        := FALSE;
    bAlarm              := TRUE;

    IF NOT bEmergencyStop THEN iErrorCode := 101; END_IF;
    IF NOT bVacuumInterlockOK THEN iErrorCode := 102; END_IF;
    IF NOT bGasScrubberOK THEN iErrorCode := 103; END_IF;

    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* Platen Temperature PID Control (Simplified for ST representation) *)
rTempError := rTargetTemp_C - rPlatenTemp_C;
rTempIntegral := rTempIntegral + (rTempError * 0.01);
(* Anti-windup *)
IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
IF rTempIntegral < 0.0 THEN rTempIntegral := 0.0; END_IF;

rHeaterPower_Pct := (rTempError * 5.0) + (rTempIntegral * 0.1);
IF rHeaterPower_Pct > 100.0 THEN rHeaterPower_Pct := 100.0; END_IF;
IF rHeaterPower_Pct < 0.0 THEN rHeaterPower_Pct := 0.0; END_IF;

bTempInBand := ABS(rTempError) <= TEMP_TOLERANCE;

(* Main ALD State Machine *)
CASE iState OF
    0: (* INIT / IDLE *)
        bValveTMA_Open     := FALSE;
        bValveH2O_Open     := FALSE;
        bValveN2Purge_Open := TRUE;
        rThrottleValve_Pos := 10.0; (* Regulate base pressure *)
        bProcessComplete   := FALSE;
        iCompletedCycles   := 0;

        IF bEnableSystem THEN
            iState := 10;
        END_IF;

    10: (* PUMP DOWN & TEMPERATURE STABILIZATION *)
        rThrottleValve_Pos := 100.0; (* Max conductance *)
        bSystemReady := bTempInBand AND (rChamberPressure_mT <= BASE_PRESSURE_MT);

        tTempStabilize(IN := bSystemReady, PT := T#10S);
        IF tTempStabilize.Q THEN
            tTempStabilize(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* ALD RECIPE START *)
        IF iCompletedCycles >= iTargetCycles THEN
            iState := 100; (* Recipe finished *)
        ELSE
            bCycleActive := TRUE;
            iState := 30;
        END_IF;

    30: (* PRECURSOR A PULSE (TMA) *)
        bValveN2Purge_Open := FALSE;
        bValveTMA_Open     := TRUE;
        (* Close throttle slightly to increase precursor residence time *)
        rThrottleValve_Pos := 5.0; 

        tPulseTimer(IN := TRUE, PT := TMA_PULSE_TIME);
        IF tPulseTimer.Q THEN
            bValveTMA_Open := FALSE;
            tPulseTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* PURGE A (N2) *)
        bValveN2Purge_Open := TRUE;
        rThrottleValve_Pos := 100.0; (* Sweep out unreacted TMA and byproducts (CH4) *)

        tPurgeTimer(IN := TRUE, PT := PURGE_TIME);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 50;
        END_IF;

    50: (* PRECURSOR B PULSE (H2O) *)
        bValveN2Purge_Open := FALSE;
        bValveH2O_Open     := TRUE;
        rThrottleValve_Pos := 5.0; 

        tPulseTimer(IN := TRUE, PT := H2O_PULSE_TIME);
        IF tPulseTimer.Q THEN
            bValveH2O_Open := FALSE;
            tPulseTimer(IN := FALSE);
            iState := 60;
        END_IF;

    60: (* PURGE B (N2) *)
        bValveN2Purge_Open := TRUE;
        rThrottleValve_Pos := 100.0; 

        tPurgeTimer(IN := TRUE, PT := PURGE_TIME);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iCompletedCycles := iCompletedCycles + 1;
            iState := 20; (* Loop back for next cycle *)
        END_IF;

    100: (* RECIPE COMPLETE *)
        bCycleActive       := FALSE;
        bProcessComplete   := TRUE;
        bValveN2Purge_Open := TRUE;
        rThrottleValve_Pos := 10.0; (* Return to idle base pressure *)

        IF NOT bEnableSystem THEN
            bProcessComplete := FALSE;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        (* Waiting for fault clear and E-stop reset *)
        IF bEmergencyStop AND bVacuumInterlockOK AND bGasScrubberOK AND NOT bEnableSystem THEN
            bAlarm := FALSE;
            iErrorCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
