FUNCTION_BLOCK FB_IS_Machine_Section_Control
// ==============================================================================
// Function Block: FB_IS_Machine_Section_Control
// Domain: Glass Bottle IS (Individual Section) Machine
// Description: Manages the complex timing, thermal regulation, and kinematics
//              of a single section in an IS machine. This includes gob shearing
//              timing, blank mold cooling, parison transfer, blow mold timing,
//              and take-out to the annealing lehr conveyor.
// ==============================================================================

VAR_INPUT
    bEnable                 : BOOL; // Master enable for the section
    bEmergencyStop          : BOOL; // Emergency stop signal (NC)
    rMachineSpeed           : REAL; // Machine speed in cuts per minute (CPM)
    rGobWeightTarget        : REAL; // Target gob weight (grams)
    rBlankMoldTempTarget    : REAL; // Target temperature for blank mold (C)
    rBlowMoldTempTarget     : REAL; // Target temperature for blow mold (C)

    // Physical I/O Sensors
    bGobArrivalSensor       : BOOL; // Detects gob falling into blank mold
    rBlankMoldTempActual    : REAL; // Actual temperature of blank mold
    rBlowMoldTempActual     : REAL; // Actual temperature of blow mold
    rLehrConveyorSpeedAct   : REAL; // Actual speed of the annealing lehr conveyor
    bTakeOutJawOpenSensor   : BOOL; // Take-out mechanism jaw status
END_VAR

VAR_OUTPUT
    bSectionActive          : BOOL; // Section is running and producing
    bFault                  : BOOL; // Fault present in the section
    wFaultCode              : WORD; // Fault code for diagnostics

    // Physical I/O Actuators
    bShearMechanismCmd      : BOOL; // Command to actuate gob shear
    bBlankMoldCloseCmd      : BOOL; // Command to close blank mold
    bBaffleDownCmd          : BOOL; // Command to bring baffle down
    bPlungerUpCmd           : BOOL; // Command to move plunger up (press)
    bInvertMechanismCmd     : BOOL; // Command to invert parison to blow side
    bBlowMoldCloseCmd       : BOOL; // Command to close blow mold
    bBlowHeadDownCmd        : BOOL; // Command to bring blow head down
    bFinalBlowCmd           : BOOL; // Command to inject final blow air
    bTakeOutArmCmd          : BOOL; // Command to move take-out arm
    bTakeOutJawCloseCmd     : BOOL; // Command to close take-out jaw

    // Proportional Control
    rBlankMoldCoolingValve  : REAL; // 0-100% Cooling air valve for blank mold
    rBlowMoldCoolingValve   : REAL; // 0-100% Cooling air valve for blow mold
    rLehrConveyorSpeedRef   : REAL; // Reference speed for lehr conveyor
END_VAR

VAR
    // State Machine
    eState                  : INT := 0; 
    // 0: Init/Stop, 10: Wait for Gob, 20: Settle, 30: Press, 40: Invert
    // 50: Reheat, 60: Final Blow, 70: Takeout, 99: Fault

    // Timers
    tCycleTimer             : TON;
    tSettleTimer            : TON;
    tPressTimer             : TON;
    tInvertTimer            : TON;
    tReheatTimer            : TON;
    tFinalBlowTimer         : TON;

    // Internal calculations
    rCycleTimeLimit         : REAL; 
    rProportionalGain       : REAL := 2.5;
    rIntegralGain           : REAL := 0.1;

    // Thermal PID variables (simplified)
    rBlankTempError         : REAL;
    rBlankTempIntegral      : REAL;
    rBlowTempError          : REAL;
    rBlowTempIntegral       : REAL;

    // Sync triggers
    rShearCamDegree         : REAL; 
END_VAR

// ------------------------------------------------------------------------------
// Safety and Enable Interlocks
// ------------------------------------------------------------------------------
IF NOT bEnable OR NOT bEmergencyStop THEN
    eState := 0;
    bSectionActive := FALSE;
    bFault := NOT bEmergencyStop;
    IF NOT bEmergencyStop THEN wFaultCode := 16#0001; END_IF;

    // Safe state for all actuators
    bShearMechanismCmd := FALSE;
    bBlankMoldCloseCmd := FALSE;
    bBaffleDownCmd := FALSE;
    bPlungerUpCmd := FALSE;
    bInvertMechanismCmd := FALSE;
    bBlowMoldCloseCmd := FALSE;
    bBlowHeadDownCmd := FALSE;
    bFinalBlowCmd := FALSE;
    bTakeOutArmCmd := FALSE;
    bTakeOutJawCloseCmd := FALSE;
    rBlankMoldCoolingValve := 0.0;
    rBlowMoldCoolingValve := 0.0;
    rLehrConveyorSpeedRef := 0.0;
    RETURN;
END_IF;

// ------------------------------------------------------------------------------
// Cycle Time & Speed Calculation
// ------------------------------------------------------------------------------
IF rMachineSpeed > 0.0 THEN
    rCycleTimeLimit := 60.0 / rMachineSpeed; // Seconds per cycle
ELSE
    rCycleTimeLimit := 5.0; // Default 5 seconds
END_IF;

// Calculate Lehr Conveyor Speed Reference based on machine speed
// To maintain proper spacing on the annealing lehr
rLehrConveyorSpeedRef := rMachineSpeed * 1.5; // Scale factor for belt speed

// ------------------------------------------------------------------------------
// Thermal Regulation (Simplified PID for Mold Cooling)
// ------------------------------------------------------------------------------
// Blank Mold
rBlankTempError := rBlankMoldTempActual - rBlankMoldTempTarget;
IF rBlankTempError > 0.0 THEN
    rBlankTempIntegral := rBlankTempIntegral + (rBlankTempError * 0.1); // Assuming 100ms task
    rBlankMoldCoolingValve := (rBlankTempError * rProportionalGain) + (rBlankTempIntegral * rIntegralGain);
    IF rBlankMoldCoolingValve > 100.0 THEN rBlankMoldCoolingValve := 100.0; END_IF;
ELSE
    rBlankMoldCoolingValve := 0.0;
    rBlankTempIntegral := 0.0;
END_IF;

// Blow Mold
rBlowTempError := rBlowMoldTempActual - rBlowMoldTempTarget;
IF rBlowTempError > 0.0 THEN
    rBlowTempIntegral := rBlowTempIntegral + (rBlowTempError * 0.1);
    rBlowMoldCoolingValve := (rBlowTempError * rProportionalGain) + (rBlowTempIntegral * rIntegralGain);
    IF rBlowMoldCoolingValve > 100.0 THEN rBlowMoldCoolingValve := 100.0; END_IF;
ELSE
    rBlowMoldCoolingValve := 0.0;
    rBlowTempIntegral := 0.0;
END_IF;

// ------------------------------------------------------------------------------
// Main Section Kinematics State Machine
// ------------------------------------------------------------------------------
CASE eState OF
    0: // INIT / STOP
        bSectionActive := FALSE;
        IF bEnable AND bEmergencyStop AND NOT bFault THEN
            eState := 10;
        END_IF;

    10: // WAIT FOR GOB
        bSectionActive := TRUE;
        bBlankMoldCloseCmd := TRUE; // Mold must be closed to receive gob
        bBaffleDownCmd := FALSE;
        bPlungerUpCmd := FALSE;

        // Wait for optical sensor detection of gob
        IF bGobArrivalSensor THEN
            tSettleTimer(IN := FALSE); // Reset timer
            eState := 20;
        END_IF;

    20: // SETTLE
        bBaffleDownCmd := TRUE;
        tSettleTimer(IN := TRUE, PT := T#200ms);
        IF tSettleTimer.Q THEN
            tPressTimer(IN := FALSE);
            eState := 30;
        END_IF;

    30: // PRESS (Forming the Parison)
        bPlungerUpCmd := TRUE; // Press mechanism up
        tPressTimer(IN := TRUE, PT := T#800ms);
        IF tPressTimer.Q THEN
            bPlungerUpCmd := FALSE;
            bBaffleDownCmd := FALSE;
            bBlankMoldCloseCmd := FALSE; // Open blank mold
            tInvertTimer(IN := FALSE);
            eState := 40;
        END_IF;

    40: // INVERT (Transfer Parison to Blow Mold)
        bInvertMechanismCmd := TRUE; // Swing neck ring to blow side
        tInvertTimer(IN := TRUE, PT := T#600ms);
        IF tInvertTimer.Q THEN
            bBlowMoldCloseCmd := TRUE; // Close blow mold around parison
            bInvertMechanismCmd := FALSE; // Return invert mechanism
            tReheatTimer(IN := FALSE);
            eState := 50;
        END_IF;

    50: // REHEAT (Allow skin of parison to reheat from internal core heat)
        tReheatTimer(IN := TRUE, PT := T#500ms);
        IF tReheatTimer.Q THEN
            bBlowHeadDownCmd := TRUE;
            tFinalBlowTimer(IN := FALSE);
            eState := 60;
        END_IF;

    60: // FINAL BLOW (Expand parison to final shape)
        bFinalBlowCmd := TRUE;
        tFinalBlowTimer(IN := TRUE, PT := T#1200ms);
        IF tFinalBlowTimer.Q THEN
            bFinalBlowCmd := FALSE;
            bBlowHeadDownCmd := FALSE;
            bBlowMoldCloseCmd := FALSE; // Open blow mold
            eState := 70;
        END_IF;

    70: // TAKEOUT (Move finished bottle to deadplate / conveyor)
        bTakeOutArmCmd := TRUE;
        bTakeOutJawCloseCmd := TRUE; // Grab bottle
        // Simulated wait for takeout motion
        IF bTakeOutJawOpenSensor THEN
            bTakeOutArmCmd := FALSE;
            eState := 10; // Return to start
        END_IF;

    99: // FAULT STATE
        bSectionActive := FALSE;
        // Fault recovery logic here

    ELSE
        eState := 0;
END_CASE;

END_FUNCTION_BLOCK
