FUNCTION_BLOCK FB_GearHobbingControl
VAR_INPUT
    bEnable : BOOL; // Enable Hobbing Process
    fSpindleSpeed_Set : REAL; // Target spindle speed (RPM)
    fWorktableSpeed_Set : REAL; // Target worktable speed (RPM)
    fHobDiameter : REAL; // Hob diameter (mm)
    fGearModule : REAL; // Gear module
    nNumTeeth : INT; // Number of teeth to cut
    bAcousticSensorActive : BOOL; // Acoustic sensor input
    fAcousticThreshold : REAL; // Threshold for crash detection
    fCurrentAcousticLevel : REAL; // Current acoustic reading
    bCoolantFlowSensor : BOOL; // Flow sensor for cutting fluid
    fTargetCoolantPressure : REAL; // Target coolant pressure (bar)
    fCurrentCoolantPressure : REAL; // Current coolant pressure (bar)
END_VAR
VAR_OUTPUT
    bSpindleDriveEnable : BOOL; // Enable Spindle Drive
    fSpindleSpeed_Cmd : REAL; // Commanded spindle speed
    bWorktableDriveEnable : BOOL; // Enable Worktable Drive
    fWorktableSpeed_Cmd : REAL; // Commanded worktable speed
    bCoolantPumpEnable : BOOL; // Enable High-Pressure Coolant Pump
    fCoolantPumpSpeed_Cmd : REAL; // Commanded pump speed (0-100%)
    bCrashDetected : BOOL; // Crash detected alarm
    bCoolantFault : BOOL; // Coolant pressure/flow fault
    bSystemReady : BOOL; // System is ready and interpolated
END_VAR
VAR
    State : INT := 0; // State machine state
    fInterpolationRatio : REAL; // Ratio between spindle and worktable
    TimerCoolantFault : TON; // Timer for coolant pressure fault
    TimerSpindleRamp : TON; // Timer for spindle speed ramp
    fRampRate : REAL := 50.0; // RPM per second
    fActualSpindleSpeed : REAL; // Internal actual spindle speed estimation
END_VAR

// Calculate Interpolation Ratio
IF fWorktableSpeed_Set > 0.0 THEN
    fInterpolationRatio := fSpindleSpeed_Set / fWorktableSpeed_Set;
ELSE
    fInterpolationRatio := 1.0;
END_IF

// Acoustic Crash Detection
IF bAcousticSensorActive AND (fCurrentAcousticLevel > fAcousticThreshold) THEN
    bCrashDetected := TRUE;
    State := 99; // Error state
END_IF

// Coolant Pressure Control (PI Loop Simplified)
IF bCoolantPumpEnable THEN
    IF fCurrentCoolantPressure < fTargetCoolantPressure THEN
        fCoolantPumpSpeed_Cmd := fCoolantPumpSpeed_Cmd + 0.1;
    ELSIF fCurrentCoolantPressure > fTargetCoolantPressure THEN
        fCoolantPumpSpeed_Cmd := fCoolantPumpSpeed_Cmd - 0.1;
    END_IF
    // Clamp
    IF fCoolantPumpSpeed_Cmd > 100.0 THEN fCoolantPumpSpeed_Cmd := 100.0; END_IF
    IF fCoolantPumpSpeed_Cmd < 0.0 THEN fCoolantPumpSpeed_Cmd := 0.0; END_IF
ELSE
    fCoolantPumpSpeed_Cmd := 0.0;
END_IF

// Coolant Fault Detection
TimerCoolantFault(IN := bCoolantPumpEnable AND NOT bCoolantFlowSensor, PT := T#2S);
IF TimerCoolantFault.Q THEN
    bCoolantFault := TRUE;
    State := 99; // Error state
END_IF

// State Machine
CASE State OF
    0: // Idle
        bSpindleDriveEnable := FALSE;
        bWorktableDriveEnable := FALSE;
        bCoolantPumpEnable := FALSE;
        fSpindleSpeed_Cmd := 0.0;
        fWorktableSpeed_Cmd := 0.0;
        bSystemReady := FALSE;
        IF bEnable AND NOT bCrashDetected AND NOT bCoolantFault THEN
            State := 10;
        END_IF

    10: // Start Coolant
        bCoolantPumpEnable := TRUE;
        IF bCoolantFlowSensor AND (fCurrentCoolantPressure >= fTargetCoolantPressure * 0.9) THEN
            State := 20;
        END_IF

    20: // Spindle and Worktable Synchronous Ramp Up
        bSpindleDriveEnable := TRUE;
        bWorktableDriveEnable := TRUE;

        IF fSpindleSpeed_Cmd < fSpindleSpeed_Set THEN
            fSpindleSpeed_Cmd := fSpindleSpeed_Cmd + 1.0;
        ELSE
            fSpindleSpeed_Cmd := fSpindleSpeed_Set;
        END_IF

        fWorktableSpeed_Cmd := fSpindleSpeed_Cmd / fInterpolationRatio;

        IF fSpindleSpeed_Cmd >= fSpindleSpeed_Set THEN
            bSystemReady := TRUE;
            State := 30;
        END_IF

    30: // Hobbing (Interpolated Running)
        fWorktableSpeed_Cmd := fSpindleSpeed_Cmd / fInterpolationRatio;
        IF NOT bEnable THEN
            State := 40;
        END_IF

    40: // Ramp Down
        bSystemReady := FALSE;
        IF fSpindleSpeed_Cmd > 0.0 THEN
            fSpindleSpeed_Cmd := fSpindleSpeed_Cmd - 1.0;
        ELSE
            fSpindleSpeed_Cmd := 0.0;
        END_IF

        fWorktableSpeed_Cmd := fSpindleSpeed_Cmd / fInterpolationRatio;

        IF fSpindleSpeed_Cmd <= 0.0 THEN
            bSpindleDriveEnable := FALSE;
            bWorktableDriveEnable := FALSE;
            State := 50;
        END_IF

    50: // Stop Coolant
        bCoolantPumpEnable := FALSE;
        State := 0;

    99: // Error State - Emergency Stop
        bSpindleDriveEnable := FALSE;
        bWorktableDriveEnable := FALSE;
        bCoolantPumpEnable := FALSE;
        fSpindleSpeed_Cmd := 0.0;
        fWorktableSpeed_Cmd := 0.0;
        bSystemReady := FALSE;
        IF NOT bEnable AND NOT bCrashDetected AND NOT bCoolantFault THEN
            State := 0;
        END_IF

END_CASE

END_FUNCTION_BLOCK
