(*
   =================================================================================================
   LSM LAUNCH CONTROLLER - ENTERPRISE THEME PARK RIDE SYSTEM
   =================================================================================================
   Version: 5.4.1 (Production)
   Target: SIL-3 / PL-e certified Safety PLC environment
   Description:
   Controls the highly synchronized firing of Linear Synchronous Motor (LSM) stators to 
   achieve a target velocity of 120 mph (53.64 m/s) in 2.0 seconds. Incorporates strict 
   block-zone safety matrices and active magnetic brake fin anti-rollback deployment.

   Maximum Peak Current: 10,000 A
   Acceleration Profile: ~2.73 Gs linear
   =================================================================================================
*)

TYPE E_LSM_State :
(
    LSM_STATE_UNINITIALIZED := 0,
    LSM_STATE_INIT := 10,
    LSM_STATE_IDLE := 20,
    LSM_STATE_TRAIN_DOCKING := 30,
    LSM_STATE_READY_FOR_DISPATCH := 40,
    LSM_STATE_PRE_LAUNCH_SYNC := 50,
    LSM_STATE_CAPACITOR_CHARGE := 60,
    LSM_STATE_LAUNCH_ACTIVE := 70,
    LSM_STATE_POST_LAUNCH_VERIFY := 80,
    LSM_STATE_ROLLBACK_RECOVERY := 90,
    LSM_STATE_FAULT := 999
) DINT;
END_TYPE

TYPE S_BlockZone_Matrix :
STRUCT
    Zone_1_Station       : BOOL;
    Zone_2_Launch        : BOOL;
    Zone_3_TopHat        : BOOL;
    Zone_4_MidBrake      : BOOL;
    Zone_5_FinalBrake    : BOOL;
    Switches_Locked      : BOOL;
    Clear_For_Launch     : BOOL;
END_STRUCT
END_TYPE

TYPE S_Stator_Telemetry :
STRUCT
    Stator_ID            : INT;
    Temperature_C        : REAL;
    Voltage_DC           : REAL;
    Current_A            : REAL;
    Magnetic_Flux        : REAL;
    Fault_Detected       : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_LSMLaunchController
VAR_INPUT
    bEnable                 : BOOL;                 // System enable
    bDispatchButton_Op1     : BOOL;                 // Operator 1 dispatch
    bDispatchButton_Op2     : BOOL;                 // Operator 2 dispatch
    bEStop                  : BOOL;                 // Emergency Stop (NC)

    // Train Telemetry
    rTrainPosition_m        : REAL;                 // Absolute position from launch start
    rTrainVelocity_mps      : REAL;                 // Current velocity in m/s
    rTrainAcceleration_mps2 : REAL;                 // Current acceleration
    rTrainMass_kg           : REAL;                 // Dynamic weight of train + riders

    // Safety & Blocks
    stBlockZones            : S_BlockZone_Matrix;   // Block zone status
    bWindWarning            : BOOL;                 // Environmental wind monitor

    // Energy Storage
    rCapacitorBankVoltage   : REAL;                 // Voltage of supercapacitor banks
END_VAR

VAR_OUTPUT
    eState                  : E_LSM_State;
    bLaunchInProgress       : BOOL;
    bReadyToLaunch          : BOOL;
    bFault                  : BOOL;
    sFaultCode              : STRING(50);

    // Physical Actuation
    aStatorFiringCommand    : ARRAY[1..100] OF REAL; // PWM Current command per stator (0 - 10,000A)
    bDeployAntiRollbackFins : BOOL;                 // Failsafe brake deployment
    bReleaseHoldBrake       : BOOL;                 // Station holding brake release
END_VAR

VAR
    // Internal State
    rLaunchTimer_ms         : REAL;                 // Timer for 2.0s launch window
    rTargetVelocityProfile  : ARRAY[0..200] OF REAL; // Pre-computed ideal velocity curve
    iCurrentStatorZone      : INT;

    // Constants
    c_rMaxVelocity_mps      : REAL := 53.6448;      // 120 mph
    c_rLaunchDuration_s     : REAL := 2.0;          // 2 seconds
    c_rMaxCurrent_A         : REAL := 10000.0;      // 10 kA peak
    c_rMinCapacitorVolts    : REAL := 850.0;        // Minimum VDC to attempt launch

    // PID for Velocity Tracking
    rErrorVelocity          : REAL;
    rIntegral               : REAL;
    rDerivative             : REAL;
    rLastError              : REAL;
    rKp                     : REAL := 5000.0;
    rKi                     : REAL := 1200.0;
    rKd                     : REAL := 800.0;
    rControlOutput          : REAL;

    // Diagnostics
    aStatorData             : ARRAY[1..100] OF S_Stator_Telemetry;
    fbTimer                 : TON;
    bProfileCalculated      : BOOL := FALSE;
    i                       : INT;
END_VAR

// =================================================================================================
// E-STOP & SAFETY OVERRIDES (Highest Priority)
// =================================================================================================
IF NOT bEStop THEN
    eState := LSM_STATE_FAULT;
    sFaultCode := 'E-STOP_ACTIVATED';
    bDeployAntiRollbackFins := TRUE; // Fail-safe
    bReleaseHoldBrake := FALSE;
    FOR i := 1 TO 100 DO aStatorFiringCommand[i] := 0.0; END_FOR;
    RETURN;
END_IF

// =================================================================================================
// BLOCK ZONE SAFETY MATRIX VERIFICATION
// =================================================================================================
// Strict IEC 61131-3 logic: The launch block (Zone 2) cannot fire unless Zone 3 (TopHat) is CLEAR.
stBlockZones.Clear_For_Launch := 
    stBlockZones.Zone_2_Launch AND      // Train is in launch zone
    NOT stBlockZones.Zone_3_TopHat AND  // Next zone is completely clear
    stBlockZones.Switches_Locked;       // All track switches are mechanically locked

// =================================================================================================
// STATE MACHINE
// =================================================================================================
CASE eState OF

    LSM_STATE_UNINITIALIZED:
        bDeployAntiRollbackFins := TRUE; // Default to safe state
        bReleaseHoldBrake := FALSE;
        IF bEnable THEN
            eState := LSM_STATE_INIT;
        END_IF

    LSM_STATE_INIT:
        // Calculate ideal launch profile (S-Curve or Linear)
        IF NOT bProfileCalculated THEN
            FOR i := 0 TO 200 DO
                // Linear velocity profile over 2.0 seconds (represented by 200 * 10ms ticks)
                rTargetVelocityProfile[i] := (c_rMaxVelocity_mps / 200.0) * INT_TO_REAL(i);
            END_FOR
            bProfileCalculated := TRUE;
        END_IF
        eState := LSM_STATE_IDLE;

    LSM_STATE_IDLE:
        bLaunchInProgress := FALSE;
        IF stBlockZones.Zone_2_Launch THEN
            eState := LSM_STATE_TRAIN_DOCKING;
        END_IF

    LSM_STATE_TRAIN_DOCKING:
        // Wait for train to settle on holding brakes
        IF rTrainVelocity_mps < 0.05 THEN
            eState := LSM_STATE_READY_FOR_DISPATCH;
        END_IF

    LSM_STATE_READY_FOR_DISPATCH:
        bReadyToLaunch := stBlockZones.Clear_For_Launch AND (rCapacitorBankVoltage >= c_rMinCapacitorVolts);

        IF bReadyToLaunch AND bDispatchButton_Op1 AND bDispatchButton_Op2 THEN
            IF bWindWarning THEN
                eState := LSM_STATE_FAULT;
                sFaultCode := 'ENVIRONMENTAL_WIND_LOCKOUT';
            ELSE
                eState := LSM_STATE_PRE_LAUNCH_SYNC;
            END_IF
        END_IF

    LSM_STATE_PRE_LAUNCH_SYNC:
        // Energize first stator block for holding, retract mechanical brakes
        aStatorFiringCommand[1] := 500.0; // 500A holding current
        bReleaseHoldBrake := TRUE;
        bDeployAntiRollbackFins := FALSE; // Retract fins for launch

        fbTimer(IN := TRUE, PT := T#500MS);
        IF fbTimer.Q THEN
            fbTimer(IN := FALSE);
            rLaunchTimer_ms := 0.0;
            rIntegral := 0.0;
            eState := LSM_STATE_LAUNCH_ACTIVE;
        END_IF

    LSM_STATE_LAUNCH_ACTIVE:
        bLaunchInProgress := TRUE;
        rLaunchTimer_ms := rLaunchTimer_ms + 10.0; // Assuming 10ms scan cycle

        // --- 1. Anti-Rollback & Velocity Tracking Envelope ---
        // Determine expected velocity at this time step
        IF (rTargetVelocityProfile[REAL_TO_INT(rLaunchTimer_ms / 10.0)] - rTrainVelocity_mps) > 5.0 THEN
            // FAILED TO ACHIEVE TARGET VELOCITY - INITIATE ROLLBACK PROTOCOL
            eState := LSM_STATE_ROLLBACK_RECOVERY;
            sFaultCode := 'LAUNCH_UNDER_SPEED_ROLLBACK';
            RETURN;
        END_IF

        // --- 2. Closed-Loop Stator Firing Algorithm ---
        rErrorVelocity := rTargetVelocityProfile[REAL_TO_INT(rLaunchTimer_ms / 10.0)] - rTrainVelocity_mps;
        rIntegral := rIntegral + (rErrorVelocity * 0.01); 
        rDerivative := (rErrorVelocity - rLastError) / 0.01;
        rLastError := rErrorVelocity;
        rControlOutput := (rKp * rErrorVelocity) + (rKi * rIntegral) + (rKd * rDerivative);

        // --- 3. Synchronous Commutation ---
        // Energize stators immediately ahead of and under the train bogie magnets
        iCurrentStatorZone := REAL_TO_INT(rTrainPosition_m / 2.0);
        FOR i := 1 TO 100 DO aStatorFiringCommand[i] := 0.0; END_FOR;
        IF iCurrentStatorZone >= 1 AND iCurrentStatorZone <= 98 THEN
            aStatorFiringCommand[iCurrentStatorZone]     := c_rMaxCurrent_A * 0.5;
            aStatorFiringCommand[iCurrentStatorZone + 1] := c_rMaxCurrent_A;
        END_IF

        // --- 4. Launch Completion Check ---
        IF rLaunchTimer_ms >= 2000.0 THEN
            IF rTrainVelocity_mps >= (c_rMaxVelocity_mps * 0.95) THEN
                eState := LSM_STATE_POST_LAUNCH_VERIFY;
            ELSE
                eState := LSM_STATE_ROLLBACK_RECOVERY;
            END_IF
        END_IF

    LSM_STATE_POST_LAUNCH_VERIFY:
        FOR i := 1 TO 100 DO aStatorFiringCommand[i] := 0.0; END_FOR;
        bLaunchInProgress := FALSE;
        IF NOT stBlockZones.Zone_2_Launch AND stBlockZones.Zone_3_TopHat THEN
            eState := LSM_STATE_IDLE; 
        END_IF

    LSM_STATE_ROLLBACK_RECOVERY:
        bLaunchInProgress := FALSE;
        bReadyToLaunch := FALSE;
        FOR i := 1 TO 100 DO aStatorFiringCommand[i] := 0.0; END_FOR;
        bDeployAntiRollbackFins := TRUE;
        IF ABS(rTrainVelocity_mps) < 0.01 THEN
            eState := LSM_STATE_FAULT;
            sFaultCode := 'ROLLBACK_SAFE_STOP_ACHIEVED';
        END_IF

    LSM_STATE_FAULT:
        bReadyToLaunch := FALSE;
        bLaunchInProgress := FALSE;
        bDeployAntiRollbackFins := TRUE;
        FOR i := 1 TO 100 DO aStatorFiringCommand[i] := 0.0; END_FOR;
        bFault := TRUE;

END_CASE
END_FUNCTION_BLOCK
