FUNCTION_BLOCK FB_Cyclotron_Depth
TITLE = 'Cyclotron with RF Control'
VERSION : '1.1'

VAR_INPUT
    Req_BeamOn : BOOL;
    Sens_Vacuum : REAL;
    Sens_MagnetTemp : REAL;
    Sens_RFFreqActual : REAL;   // Actual RF Frequency in MHz
    Sens_RFCavityVolt : REAL;   // Actual Cavity Voltage in kV
END_VAR

VAR_OUTPUT
    Cmd_BeamActive : BOOL;
    Cmd_MagnetCurrent : REAL;
    Cmd_RFFreqSetpt : REAL;
    Cmd_RFPwrEnable : BOOL;
    Sts_Interlock : BOOL;
END_VAR

VAR
    Stat_Current : REAL := 0.0;
    Stat_RFState : INT := 0;
END_VAR

CONST
    LIMIT_VACUUM : REAL := 1.0E-6;
    LIMIT_TEMP : REAL := 45.0;
    NOM_CURRENT : REAL := 120.0;
    NOM_RF_FREQ : REAL := 72.5;     // MHz
    MIN_CAVITY_VOLT : REAL := 40.0; // kV
END_CONST

BEGIN
    // 1. Interlocks
    IF (Sens_Vacuum > LIMIT_VACUUM) OR (Sens_MagnetTemp > LIMIT_TEMP) THEN
        Sts_Interlock := TRUE;
        Cmd_BeamActive := FALSE;
        Cmd_RFPwrEnable := FALSE;
        Stat_Current := 0.0;
        Stat_RFState := 0;
    ELSE
        Sts_Interlock := FALSE;
    END_IF;

    // 2. Control Sequence
    IF NOT Sts_Interlock AND Req_BeamOn THEN
        // Magnet Control
        IF Stat_Current < NOM_CURRENT THEN
            Stat_Current := Stat_Current + 0.5;
        END_IF;

        // RF Control
        IF Stat_Current >= NOM_CURRENT THEN
            Cmd_RFPwrEnable := TRUE;
            Cmd_RFFreqSetpt := NOM_RF_FREQ;

            // Tuning logic
            IF ABS(Sens_RFFreqActual - NOM_RF_FREQ) < 0.1 AND Sens_RFCavityVolt >= MIN_CAVITY_VOLT THEN
                Stat_RFState := 1; // RF Ready
            ELSE
                Stat_RFState := 0;
            END_IF;
        END_IF;

        // Beam Activation
        IF Stat_RFState = 1 THEN
            Cmd_BeamActive := TRUE;
        END_IF;
    ELSE
        Cmd_BeamActive := FALSE;
        Cmd_RFPwrEnable := FALSE;
        Stat_RFState := 0;
        IF Stat_Current > 0.0 THEN
            Stat_Current := Stat_Current - 1.0;
        END_IF;
        IF Stat_Current < 0.0 THEN Stat_Current := 0.0; END_IF;
    END_IF;

    Cmd_MagnetCurrent := Stat_Current;
END_FUNCTION_BLOCK
