FUNCTION_BLOCK FB_WakeSteeringController
TITLE = 'Wind Farm Wake Steering and Active Power Controller'
VERSION : '2.1.0'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    bEnableController         : BOOL; // Master enable
    rGridActivePowerSetpoint  : REAL; // Global MW setpoint for the array
    rWindSpeedLidar           : REAL; // Forecasted wind speed from nacelle LIDAR (m/s)
    rWindDirLidar             : REAL; // Forecasted wind direction (deg)
    rTurbulenceIntensity      : REAL; // Forecasted TI from LIDAR (%)
    aUpwindTurbineStatus      : ARRAY[1..10] OF BOOL; // Running status of upwind turbines
    aUpwindPowerOutput        : ARRAY[1..10] OF REAL; // Actual power output (MW)
    aUpwindYawAngles          : ARRAY[1..10] OF REAL; // Actual yaw angles (deg)
    rAirDensity               : REAL; // Measured air density (kg/m^3)
END_VAR

VAR_OUTPUT
    aTargetYawOffsets         : ARRAY[1..10] OF REAL; // Yaw misalignment setpoints (deg)
    aTargetPowerCurtailment   : ARRAY[1..10] OF REAL; // Active power limits (MW)
    bSystemFault              : BOOL; // Fault flag
    nActiveWakeControlMode    : INT; // 0=Off, 1=Yaw Only, 2=Induction Only, 3=Combined
END_VAR

VAR
    iTurbineIdx               : INT;
    rTotalActualPower         : REAL;
    rPowerDeficit             : REAL;
    rDynamicYawGain           : REAL;
    rMaxYawMisalignment       : REAL := 25.0; // Max allowed offset
    aWakeOffsetMatrix         : ARRAY[1..360, 1..25] OF REAL; // Look-up table for baseline offsets based on Dir/Speed
    rFilteredTI               : REAL;
    rFilterAlpha              : REAL := 0.05;
    rTempOffset               : REAL;
    bInitializeLUT            : BOOL := TRUE;
END_VAR

// Initialization of Wake Offset Lookup Table (Simplified for Synthetic context)
IF bInitializeLUT THEN
    FOR iTurbineIdx := 1 TO 360 DO
        aWakeOffsetMatrix[iTurbineIdx, 10] := 5.0; // Dummy baseline
    END_FOR;
    bInitializeLUT := FALSE;
END_VAR;

IF NOT bEnableController THEN
    nActiveWakeControlMode := 0;
    bSystemFault := FALSE;
    FOR iTurbineIdx := 1 TO 10 DO
        aTargetYawOffsets[iTurbineIdx] := 0.0;
        aTargetPowerCurtailment[iTurbineIdx] := 10.0; // Nominal max MW
    END_FOR;
    RETURN;
END_IF;

// Low-pass filter for Turbulence Intensity
rFilteredTI := (rTurbulenceIntensity * rFilterAlpha) + (rFilteredTI * (1.0 - rFilterAlpha));

// Calculate Total Power and Deficit
rTotalActualPower := 0.0;
FOR iTurbineIdx := 1 TO 10 DO
    IF aUpwindTurbineStatus[iTurbineIdx] THEN
        rTotalActualPower := rTotalActualPower + aUpwindPowerOutput[iTurbineIdx];
    END_IF;
END_FOR;

rPowerDeficit := rGridActivePowerSetpoint - rTotalActualPower;

// Wake Steering Logic: Determine Yaw Offsets
IF rFilteredTI < 12.0 AND rWindSpeedLidar > 6.0 AND rWindSpeedLidar < 18.0 THEN
    nActiveWakeControlMode := 3; // Combined mode
    rDynamicYawGain := 1.0 - (rFilteredTI / 20.0);
    IF rDynamicYawGain < 0.0 THEN rDynamicYawGain := 0.0; END_IF;

    FOR iTurbineIdx := 1 TO 10 DO
        IF aUpwindTurbineStatus[iTurbineIdx] THEN
            rTempOffset := aWakeOffsetMatrix[REAL_TO_INT(rWindDirLidar) MOD 360 + 1, REAL_TO_INT(rWindSpeedLidar) MOD 25 + 1];
            aTargetYawOffsets[iTurbineIdx] := rTempOffset * rDynamicYawGain;

            IF aTargetYawOffsets[iTurbineIdx] > rMaxYawMisalignment THEN
                aTargetYawOffsets[iTurbineIdx] := rMaxYawMisalignment;
            ELSIF aTargetYawOffsets[iTurbineIdx] < -rMaxYawMisalignment THEN
                aTargetYawOffsets[iTurbineIdx] := -rMaxYawMisalignment;
            END_IF;
        ELSE
            aTargetYawOffsets[iTurbineIdx] := 0.0;
        END_IF;
    END_FOR;
ELSE
    nActiveWakeControlMode := 1; 
    FOR iTurbineIdx := 1 TO 10 DO
        aTargetYawOffsets[iTurbineIdx] := 0.0;
    END_FOR;
END_IF;

// Active Power Curtailment / Induction Control
IF rPowerDeficit < 0.0 THEN
    FOR iTurbineIdx := 1 TO 10 DO
        IF aUpwindTurbineStatus[iTurbineIdx] THEN
            aTargetPowerCurtailment[iTurbineIdx] := (rGridActivePowerSetpoint / 10.0) * (1.0 + (INT_TO_REAL(iTurbineIdx)*0.02)); 
        END_IF;
    END_FOR;
ELSE
    FOR iTurbineIdx := 1 TO 10 DO
        aTargetPowerCurtailment[iTurbineIdx] := 15.0; // Release limits
    END_FOR;
END_IF;

bSystemFault := (rWindSpeedLidar < 0.0) OR (rWindSpeedLidar > 50.0);

END_FUNCTION_BLOCK
```

