END_VAR

VAR
    // PID Controllers for Tracking
    fKp_Track : REAL := 0.05;
    fKi_Track : REAL := 0.002;
    fKd_Track : REAL := 0.01;

    fIntegralErr_X : REAL := 0.0;
    fIntegralErr_Y : REAL := 0.0;
    fPrevErr_X     : REAL := 0.0;
    fPrevErr_Y     : REAL := 0.0;

    // Adaptive Gate Timing Variables
    fGateDelayBase   : REAL := 1500.0; // Base delay ps
    fGateDelayOffset : REAL := 0.0;
    fJitterCompensation : REAL := 0.0;

    // Polarization Compensation (Faraday Rotator)
    fPolDrift_CompRate : REAL := 0.15;

    // Timers
    tTrackingTimeout : TON;
    tSyncLoss        : TON;

    // Internal State
    eState : (ST_IDLE, ST_ACQUISITION, ST_COARSE_TRACK, ST_FINE_TRACK, ST_QUANTUM_SYNC, ST_FAULT);
END_VAR

//=============================================================================
// State Machine and Control Logic
//=============================================================================
IF NOT bEnable THEN
    eState := ST_IDLE;
    fMountAzimuth_Cmd := 0.0;
    fMountElevation_Cmd := 0.0;
    fBeaconLaserPower_Cmd := 0.0;
    bQuantumLinkActive := FALSE;
    fIntegralErr_X := 0.0;
    fIntegralErr_Y := 0.0;
    RETURN;
END_IF;

CASE eState OF
    ST_IDLE:
        // Await Ephemeris validity
        IF (fSatElevation_Ref > 10.0) THEN
            eState := ST_ACQUISITION;
        END_IF;
        nSystemState := 0;

    ST_ACQUISITION:
        // Open Loop pointing based on Ephemeris
        fMountAzimuth_Cmd := fSatAzimuth_Ref;
        fMountElevation_Cmd := fSatElevation_Ref;

        fBeaconLaserPower_Cmd := 1000.0; // Max power for acquisition

        IF bLOS_Acquired THEN
            eState := ST_COARSE_TRACK;
        END_IF;
        nSystemState := 1;

    ST_COARSE_TRACK:
        // Close the loop with Quad Cell Error - PI Control
        fIntegralErr_X := fIntegralErr_X + fBeaconQuadCell_X;
        fIntegralErr_Y := fIntegralErr_Y + fBeaconQuadCell_Y;

        fMountAzimuth_Cmd := fSatAzimuth_Ref + (fKp_Track * fBeaconQuadCell_X) + (fKi_Track * fIntegralErr_X);
        fMountElevation_Cmd := fSatElevation_Ref + (fKp_Track * fBeaconQuadCell_Y) + (fKi_Track * fIntegralErr_Y);

        // Adjust Beacon Power based on seeing
        fBeaconLaserPower_Cmd := 1000.0 - (fAtmosphericSeeing * 10.0);
        IF fBeaconLaserPower_Cmd < 200.0 THEN fBeaconLaserPower_Cmd := 200.0; END_IF;

        IF (ABS(fBeaconQuadCell_X) < 5.0) AND (ABS(fBeaconQuadCell_Y) < 5.0) THEN
            eState := ST_FINE_TRACK;
        END_IF;
        nSystemState := 2;

    ST_FINE_TRACK:
        // Add Derivative term for fine tracking
        fMountAzimuth_Cmd := fSatAzimuth_Ref + (fKp_Track * fBeaconQuadCell_X) + (fKi_Track * fIntegralErr_X) + (fKd_Track * (fBeaconQuadCell_X - fPrevErr_X));
        fMountElevation_Cmd := fSatElevation_Ref + (fKp_Track * fBeaconQuadCell_Y) + (fKi_Track * fIntegralErr_Y) + (fKd_Track * (fBeaconQuadCell_Y - fPrevErr_Y));

        fPrevErr_X := fBeaconQuadCell_X;
        fPrevErr_Y := fBeaconQuadCell_Y;

        IF nSPDC_CoincidenceCounts > 5000 THEN
            eState := ST_QUANTUM_SYNC;
        END_IF;
        nSystemState := 3;

    ST_QUANTUM_SYNC:
        // Fine pointing maintained
        fMountAzimuth_Cmd := fSatAzimuth_Ref + (fKp_Track * fBeaconQuadCell_X) + (fKi_Track * fIntegralErr_X);
        fMountElevation_Cmd := fSatElevation_Ref + (fKp_Track * fBeaconQuadCell_Y) + (fKi_Track * fIntegralErr_Y);

        // Faraday Rotator Adaptive Polarization Control based on QBER
        // If QBER increases, apply differential rotation to recover basis alignment
        IF fQBER_Estimate > 0.05 THEN
            fFaradayAngle_H := fFaradayAngle_H + (fQBER_Estimate * fPolDrift_CompRate);
            fFaradayAngle_V := fFaradayAngle_V - (fQBER_Estimate * fPolDrift_CompRate);
        END_IF;

        // Adaptive SPAD Gating
        // Shrink gate width in high seeing (poor atmosphere) to reject background noise
        IF fAtmosphericSeeing < 5.0 THEN
            nSPAD_GateWidth_ps := 500; // Narrow gate for high noise
        ELSE
            nSPAD_GateWidth_ps := 1200; // Wide gate for low noise
        END_IF;

        // Adjust Gate Delay offset based on coincidence counts (Peak Search)
        fJitterCompensation := fJitterCompensation + 0.1;
        nSPAD_GateDelay_ps := REAL_TO_DINT(fGateDelayBase + fJitterCompensation);

        bQuantumLinkActive := (fQBER_Estimate < 0.08); // Threshold for secure key generation
        nSystemState := 4;

        // Fallback to tracking if counts drop
        IF nSPDC_CoincidenceCounts < 1000 THEN
            eState := ST_FINE_TRACK;
            bQuantumLinkActive := FALSE;
        END_IF;

    ST_FAULT:
        bQuantumLinkActive := FALSE;
        fBeaconLaserPower_Cmd := 0.0;
        nSystemState := 99;
END_CASE;
END_FUNCTION_BLOCK
