FUNCTION_BLOCK FB_ASU_MainHeatExchanger_Control
VAR_INPUT
    (* Physical Inputs *)
    bEnable                 : BOOL;     (* System Enable Interlock *)
    bEmergencyStop          : BOOL;     (* Safety Relay Status (TRUE = OK) *)
    rFeedGasTemp            : REAL;     (* Warm feed gas inlet temperature [K] *)
    rFeedGasPressure        : REAL;     (* Warm feed gas pressure [bar(a)] *)
    rReturnGasTemp          : REAL;     (* Cold return gas inlet temperature [K] *)
    rExpanderSpeed          : REAL;     (* Turboexpander actual rotational speed [RPM] *)
    rCoolingWaterFlow       : REAL;     (* Cooling water auxiliary flow rate [kg/s] *)
    bSurgeValveStatus       : BOOL;     (* Anti-surge valve limit switch status *)
END_VAR
VAR_OUTPUT
    (* Physical Outputs *)
    bSystemReady            : BOOL;     (* Exchanger cooldown sequence complete *)
    rJTValvePos             : REAL;     (* Joule-Thomson expansion valve target position [%] *)
    rSurgeValvePos          : REAL;     (* Turboexpander active anti-surge valve position [%] *)
    rCoolingWaterValvePos   : REAL;     (* Auxiliary cooling water valve position [%] *)
    bAlarm                  : BOOL;     (* Critical fault active (temperature/pressure/surge) *)
    bShutdownInterlock      : BOOL;     (* Trigger for main plant trip *)
END_VAR
VAR
    (* Internal State and PID Control *)
    iState                  : INT := 0; (* State Machine Index *)
    tCooldownTimer          : TON;      (* Cooldown profile timer *)
    tSurgeTimer             : TON;      (* Surge condition duration timer *)
    rDeltaT                 : REAL;     (* Logarithmic mean temperature difference [K] *)
    rExpanderSurgeMargin    : REAL;     (* Calculated margin to surge line *)
    rJTValveIntegral        : REAL := 0.0;
    rJTError                : REAL;

    (* Constants *)
    c_rTargetDeltaT         : REAL := 3.5;  (* Target delta T [K] *)
    c_rMaxTempDelta       : REAL := 150.0; (* Max allowable thermal stress delta [K] *)
    c_rKp_JT                : REAL := 1.2;
    c_rKi_JT                : REAL := 0.05;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    bShutdownInterlock := TRUE;
    rJTValvePos := 0.0;
    rSurgeValvePos := 100.0; (* Fail safe: open anti-surge valve completely *)
    rCoolingWaterValvePos := 100.0;
    iState := 99; (* FAULT STATE *)
    RETURN;
END_IF;

(* 2. Thermal Stress Protection Calculation *)
rDeltaT := ABS(rFeedGasTemp - rReturnGasTemp);
IF rDeltaT > c_rMaxTempDelta THEN
    bAlarm := TRUE;
    bShutdownInterlock := TRUE;
    iState := 99;
    RETURN;
END_IF;

(* 3. Turboexpander Surge Margin Calculation (Simplified Compressor Map) *)
(* In a real 40-year veteran code, this would be an extensive 2D interpolation block *)
rExpanderSurgeMargin := (rFeedGasPressure * 1000.0) / (rExpanderSpeed + 1.0); 

(* 4. State Machine for Main Heat Exchanger Operations *)
CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        bShutdownInterlock := FALSE;
        rJTValvePos := 0.0;
        rSurgeValvePos := 100.0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* COOLDOWN SEQUENCE *)
        (* Gradually open JT valve to prevent thermal shock *)
        rJTValvePos := rJTValvePos + 0.1;
        IF rJTValvePos > 25.0 THEN
            rJTValvePos := 25.0;
        END_IF;

        tCooldownTimer(IN := TRUE, PT := T#60S);
        IF tCooldownTimer.Q AND (rReturnGasTemp < 100.0) THEN (* Temp below 100K *)
            tCooldownTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* NORMAL OPERATION - CASCADE CONTROL *)
        bSystemReady := TRUE;

        (* PI Control for JT Valve based on Target Delta T *)
        rJTError := c_rTargetDeltaT - (rFeedGasTemp - rReturnGasTemp);
        rJTValveIntegral := rJTValveIntegral + (rJTError * c_rKi_JT);

        (* Anti-windup *)
        IF rJTValveIntegral > 100.0 THEN rJTValveIntegral := 100.0; END_IF;
        IF rJTValveIntegral < 0.0 THEN rJTValveIntegral := 0.0; END_IF;

        rJTValvePos := (rJTError * c_rKp_JT) + rJTValveIntegral;
        IF rJTValvePos > 100.0 THEN rJTValvePos := 100.0; END_IF;
        IF rJTValvePos < 5.0 THEN rJTValvePos := 5.0; END_IF; (* Minimum flow bypass *)

        (* Active Surge Control for Turboexpander *)
        IF rExpanderSurgeMargin < 15.0 THEN
            rSurgeValvePos := rSurgeValvePos + 2.5; (* Fast opening *)
            tSurgeTimer(IN := TRUE, PT := T#5S);
            IF tSurgeTimer.Q THEN
                bAlarm := TRUE; (* Prolonged surge condition *)
            END_IF;
        ELSE
            rSurgeValvePos := rSurgeValvePos - 0.5; (* Slow closing *)
            tSurgeTimer(IN := FALSE);
        END_IF;

        (* Limit Surge Valve *)
        IF rSurgeValvePos > 100.0 THEN rSurgeValvePos := 100.0; END_IF;
        IF rSurgeValvePos < 0.0 THEN rSurgeValvePos := 0.0; END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT / TRIP HANDLING *)
        bSystemReady := FALSE;
        rJTValvePos := 0.0;
        rSurgeValvePos := 100.0;
        IF NOT bEnable AND bEmergencyStop THEN
            iState := 0; (* Reset only if enable is dropped and E-Stop is OK *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
