    bIntercoolerPump_Run := FALSE;
    rTurbineValve_Pct := 0.0;
    bGenBreaker_Close := FALSE;
    wSystemState := 99;
    bAlarm := TRUE;
    sStatusMsg := 'EMERGENCY STOP ACTIVE';
    RETURN;
END_IF;

// Vibration Protection
IF (rCompStage1_Vib_mm > rMaxVibration) OR (rCompStage2_Vib_mm > rMaxVibration) THEN
    bCompMotor1_Run := FALSE;
    bCompMotor2_Run := FALSE;
    wSystemState := 99;
    bAlarm := TRUE;
    sStatusMsg := 'HIGH VIBRATION TRIP';
    RETURN;
END_IF;

// Cavern Pressure Protection
IF (rCavernPressure_Bar > rCavernMaxPress_Bar) AND (wSystemState = 1) THEN
    bCompMotor1_Run := FALSE;
    bCompMotor2_Run := FALSE;
    wSystemState := 0; // Go to standby
    bAlarm := TRUE;
    sStatusMsg := 'CAVERN OVERPRESSURE';
END_IF;

IF (rCavernPressure_Bar < rCavernMinPress_Bar) AND (wSystemState = 2) THEN
    rTurbineValve_Pct := 0.0;
    bGenBreaker_Close := FALSE;
    wSystemState := 0;
    bAlarm := TRUE;
    sStatusMsg := 'CAVERN UNDERPRESSURE';
END_IF;

// -----------------------------------------------------------------------------
// MAIN STATE MACHINE
// -----------------------------------------------------------------------------
CASE iState OF

    0: // STANDBY
        bCompMotor1_Run := FALSE;
        bCompMotor2_Run := FALSE;
        rIGV_Position_Pct := 0.0;
        bIntercoolerPump_Run := FALSE;
        rTurbineValve_Pct := 0.0;
        bGenBreaker_Close := FALSE;
        bAlarm := FALSE;
        wSystemState := 0;
        sStatusMsg := 'STANDBY';

        IF bEnable AND bStartCompression AND NOT bStartExpansion THEN
            IF rCavernPressure_Bar < rCavernMaxPress_Bar THEN
                iState := 10; // Transition to compression start
            END_IF;
        ELSIF bEnable AND bStartExpansion AND NOT bStartCompression THEN
            IF rCavernPressure_Bar > rCavernMinPress_Bar THEN
                iState := 20; // Transition to expansion start
            END_IF;
        END_IF;

    // --- COMPRESSION PHASE ---
    10: // START COMPRESSOR STAGE 1
        wSystemState := 1;
        sStatusMsg := 'COMP START: STAGE 1';
        rIGV_Position_Pct := 20.0; // Minimal load for starting
        bCompMotor1_Run := TRUE;
        tCompInterstageDelay(IN := TRUE, PT := T#15S);

        IF tCompInterstageDelay.Q THEN
            iState := 11;
        END_IF;

    11: // START INTERCOOLER & STAGE 2
        sStatusMsg := 'COMP START: STAGE 2';
        bIntercoolerPump_Run := TRUE;
        bCompMotor2_Run := TRUE;
        tCompInterstageDelay(IN := FALSE);
        iState := 12;

    12: // MODULATE IGV BASED ON PRESSURE
        sStatusMsg := 'COMPRESSING';
        // Simple PI approximation for IGV to fill cavern
        rIGV_Position_Pct := 20.0 + ((rCavernMaxPress_Bar - rCavernPressure_Bar) / rCavernMaxPress_Bar) * 80.0;

        // Stop condition
        IF NOT bStartCompression OR (rCavernPressure_Bar >= rCavernMaxPress_Bar) THEN
            iState := 0;
        END_IF;

    // --- EXPANSION PHASE ---
    20: // TURBINE SPIN UP
        wSystemState := 2;
        sStatusMsg := 'TURBINE SPIN UP';
        tStartupDelay(IN := TRUE, PT := T#30S);

        // Slowly open valve to reach nominal RPM
        IF rTurbineSpeed_RPM < rTurbineNominalSpeed THEN
            rTurbineValve_Pct := rTurbineValve_Pct + 0.1;
        END_IF;

        IF (rTurbineSpeed_RPM >= (rTurbineNominalSpeed * 0.98)) AND tStartupDelay.Q THEN
            iState := 21;
        END_IF;

    21: // GRID SYNCHRONIZATION (SIMULATED)
        sStatusMsg := 'GRID SYNC';
        IF ABS(rGridFreq_Hz - 50.0) < 0.2 THEN
            bGenBreaker_Close := TRUE;
            iState := 22;
        END_IF;

    22: // POWER GENERATION / LOAD CONTROL
        sStatusMsg := 'GENERATING';
        // Map Grid Demand MW to Valve Position (Simplified curve)
        rMassFlowTarget := rGridDemand_MW * 2.5; // Conversion factor MW to kg/s

        // Valve mapping based on available pressure
        rTurbineValve_Pct := (rMassFlowTarget / rCavernPressure_Bar) * 100.0;

        // Limit valve
        IF rTurbineValve_Pct > 100.0 THEN rTurbineValve_Pct := 100.0; END_IF;
        IF rTurbineValve_Pct < 15.0 THEN rTurbineValve_Pct := 15.0; END_IF;

        rOutputPower_MW := (rTurbineValve_Pct / 100.0) * rCavernPressure_Bar * 0.4;

        // Stop condition
        IF NOT bStartExpansion OR (rCavernPressure_Bar <= rCavernMinPress_Bar) THEN
            tStartupDelay(IN := FALSE);
            iState := 0;
        END_IF;

    ELSE
        // FAULT / UNKNOWN STATE
        iState := 0;

END_CASE;

END_FUNCTION_BLOCK
