    iAlarmCode := 101; // Starch over-temp
ELSIF AI_SteamPress1_Bar > 12.0 THEN
    bAlarmActive := TRUE;
    iAlarmCode := 102; // Steam over-pressure
ELSE
    bAlarmActive := FALSE;
    iAlarmCode := 0;
END_IF;

END_FUNCTION_BLOCK
