FUNCTION_BLOCK FB_ChocolateEnroberCoolingTunnel
VAR_INPUT
    bEnable : BOOL; // System enable command
    rSetTempTempering : REAL; // Tempering machine target temperature (C)
    rBeltSpeedSetpoint : REAL; // Target belt speed (m/min)
    rBlowerPressureSet : REAL; // Target blower pressure for curtain thickness (mbar)
    rZone1SetTemp : REAL; // Cooling tunnel Zone 1 target (C)
    rZone2SetTemp : REAL; // Cooling tunnel Zone 2 target (C)
    rZone3SetTemp : REAL; // Cooling tunnel Zone 3 target (C)

    // Physical I/O Feedback
    rActTempTempering : REAL;
    rActBeltSpeed : REAL;
    rActBlowerPressure : REAL;
    rActZone1Temp : REAL;
    rActZone2Temp : REAL;
    rActZone3Temp : REAL;
    bEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bAlarmActive : BOOL;
    iAlarmCode : INT;

    // Physical I/O Control
    rCmdTemperingHeater : REAL; // 0-100% output
    rCmdTemperingCooler : REAL; // 0-100% output
    rCmdBeltMotor : REAL; // 0-100% speed output
    rCmdBlowerMotor : REAL; // 0-100% output
    rCmdZone1Cooling : REAL; // 0-100% output
    rCmdZone2Cooling : REAL; // 0-100% output
    rCmdZone3Cooling : REAL; // 0-100% output
END_VAR

VAR
    // PID Controllers (simulated variables, typically from standard library)
    PID_Tempering : FB_PID_Advanced;
    PID_BeltSpeed : FB_PID_Advanced;
    PID_Blower : FB_PID_Advanced;
    PID_Zone1 : FB_PID_Advanced;
    PID_Zone2 : FB_PID_Advanced;
    PID_Zone3 : FB_PID_Advanced;

    // State machine and Timers
    iState : INT := 0;
    tTimer : TON;
    rBetaCrystalLevel : REAL; // Estimated beta crystal index
    bTemperingReady : BOOL;

    // Tolerances and limits
    MAX_TEMP_ERROR : REAL := 2.0;
    MAX_SPEED_ERROR : REAL := 0.5;
END_VAR

// --- Main Control Logic State Machine ---
IF bEmergencyStop THEN
    iState := 99; // Jump immediately to Fault state
END_IF;

CASE iState OF
    0: // Idle State
        bSystemReady := FALSE;
        rCmdTemperingHeater := 0.0;
        rCmdTemperingCooler := 0.0;
        rCmdBeltMotor := 0.0;
        rCmdBlowerMotor := 0.0;
        rCmdZone1Cooling := 0.0;
        rCmdZone2Cooling := 0.0;
        rCmdZone3Cooling := 0.0;

        IF bEnable THEN
            iState := 10; // Start Tempering Phase
        END_IF;

    10: // Tempering and Beta-Crystal Seeding Phase
        // Complex tempering curve handling with PID
        PID_Tempering(
            rSetpoint := rSetTempTempering,
            rActualValue := rActTempTempering,
            rKp := 2.5, rTi := 10.0, rTd := 0.5,
            rOutputValue => rCmdTemperingHeater
        );
        // Inverse for cooler logic (simplified push-pull logic)
        rCmdTemperingCooler := 100.0 - rCmdTemperingHeater;

        // Check if tempering temperature is stable within tolerance
        IF ABS(rSetTempTempering - rActTempTempering) < MAX_TEMP_ERROR THEN
            tTimer(IN := TRUE, PT := T#5M);
            IF tTimer.Q THEN
                bTemperingReady := TRUE;
                tTimer(IN := FALSE);
                iState := 20; // Proceed to Belt and Blower profiling
            END_IF;
        ELSE
            tTimer(IN := FALSE); // Reset timer if temperature goes out of bounds
        END_IF;

    20: // Enrobing Curtain Blower Profiling and Belt Speed Control
        PID_BeltSpeed(
            rSetpoint := rBeltSpeedSetpoint,
            rActualValue := rActBeltSpeed,
            rKp := 1.0, rTi := 5.0, rTd := 0.1,
            rOutputValue => rCmdBeltMotor
        );

        PID_Blower(
            rSetpoint := rBlowerPressureSet,
            rActualValue := rActBlowerPressure,
            rKp := 1.5, rTi := 3.0, rTd := 0.0,
            rOutputValue => rCmdBlowerMotor
        );

        // Wait for belt speed to stabilize
        IF ABS(rBeltSpeedSetpoint - rActBeltSpeed) < MAX_SPEED_ERROR THEN
            iState := 30; // Start Cooling Tunnels profiling
        END_IF;

    30: // Multi-Zone Radiant Cooling Control
        PID_Zone1(rSetpoint:=rZone1SetTemp, rActualValue:=rActZone1Temp, rKp:=3.0, rTi:=12.0, rTd:=1.0, rOutputValue=>rCmdZone1Cooling);
        PID_Zone2(rSetpoint:=rZone2SetTemp, rActualValue:=rActZone2Temp, rKp:=3.0, rTi:=12.0, rTd:=1.0, rOutputValue=>rCmdZone2Cooling);
        PID_Zone3(rSetpoint:=rZone3SetTemp, rActualValue:=rActZone3Temp, rKp:=3.0, rTi:=12.0, rTd:=1.0, rOutputValue=>rCmdZone3Cooling);

        IF bTemperingReady AND (rCmdBeltMotor > 0.0) THEN
            bSystemReady := TRUE; // System fully operational and producing
        END_IF;

        IF NOT bEnable THEN
            iState := 0; // Shutdown process
        END_IF;

    99: // Fault and Emergency Recovery State
        bSystemReady := FALSE;
        bAlarmActive := TRUE;
        iAlarmCode := 1001; // Code for E-Stop or Critical Fault

        // Safe state outputs
        rCmdTemperingHeater := 0.0;
        rCmdTemperingCooler := 100.0; // Max cooling to solidify and stop flow safely
        rCmdBeltMotor := 0.0;
        rCmdBlowerMotor := 0.0;
        rCmdZone1Cooling := 100.0;
        rCmdZone2Cooling := 100.0;
        rCmdZone3Cooling := 100.0;

        // Recovery logic
        IF NOT bEmergencyStop AND NOT bEnable THEN
            bAlarmActive := FALSE;
            iAlarmCode := 0;
            iState := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
