FUNCTION_BLOCK FB_LNG_Liquefaction_Train
TITLE = 'LNG Mixed Refrigerant Compressor Cascade'
// This function block manages a complex mixed refrigerant (MR) compressor train
// for a cryogenic liquefaction process at an LNG Export Terminal.
// It includes boil-off gas (BOG) handling, surge control, and cascaded temperature loops.

VAR_INPUT
    rFeedGasTemp_C           : REAL;   // Feed gas temperature into main cryogenic heat exchanger (MCHE)
    rFeedGasPress_bar        : REAL;   // Feed gas pressure
    rFeedGasFlow_kg_h        : REAL;   // Feed gas flow rate

    rMR_SuctionPress_bar     : REAL;   // Mixed Refrigerant suction pressure
    rMR_DischargePress_bar   : REAL;   // Mixed Refrigerant discharge pressure
    rMR_Flow_kg_h            : REAL;   // Mixed Refrigerant flow rate

    rBOG_VesselPress_bar     : REAL;   // Boil-off gas vessel pressure
    bBOG_CompressorReady     : BOOL;   // BOG compressor running status
    bTrainStartCommand       : BOOL;   // Command to start the liquefaction train
    bTrainStopCommand        : BOOL;   // Command to stop the liquefaction train
    bEmergencyShutdown       : BOOL;   // ESD Signal
END_VAR

VAR_OUTPUT
    rMCHE_TempSetpoint_C     : REAL;   // Calculated setpoint for MCHE
    rMR_CompressorSpeed_RPM  : REAL;   // Commanded speed for MR compressor
    rMR_SurgeValvePos_Pct    : REAL;   // Anti-surge valve position (0-100%)
    bBOG_CompressorStart     : BOOL;   // Command to start BOG compressor
    bTrainRunning            : BOOL;   // Status indicating train is running
    bAlarmSurgeDetected      : BOOL;   // Alarm for compressor surge condition
    bAlarmHighPress          : BOOL;   // Alarm for excessive discharge pressure
    bESD_Active              : BOOL;   // Indication that ESD is active
END_VAR

VAR
    eState                   : INT := 0; // State machine state
    rSurgeMargin             : REAL;     // Calculated surge margin
    rTargetSpeed             : REAL;     // Internal target speed for ramp
    rActualSpeed             : REAL;     // Internal actual speed simulation/tracking
    TMR_StartDelay           : TON;      // Timer for startup sequence
    TMR_BOG_Start            : TON;      // Timer for BOG stabilization

    // Constants
    cMaxSpeed_RPM            : REAL := 3600.0;
    cMinSpeed_RPM            : REAL := 1200.0;
    cSurgeLimit_Ratio        : REAL := 2.5; // Pressure ratio for surge curve
    cSafeSurgeMargin         : REAL := 10.0; // %
END_VAR

// Implementation
IF bEmergencyShutdown THEN
    eState := 99; // ESD State
END_IF;

CASE eState OF
    0: // OFF State
        bTrainRunning := FALSE;
        rMR_CompressorSpeed_RPM := 0.0;
        rMR_SurgeValvePos_Pct := 100.0; // Fully open for safety
        bBOG_CompressorStart := FALSE;
        rActualSpeed := 0.0;

        IF bTrainStartCommand AND NOT bEmergencyShutdown THEN
            eState := 10;
        END_IF;

    10: // Starting BOG
        bBOG_CompressorStart := TRUE;
        TMR_BOG_Start(IN:= bBOG_CompressorReady, PT:= T#30s);
        IF TMR_BOG_Start.Q THEN
            eState := 20; // BOG running, start MR
        END_IF;

        IF bTrainStopCommand THEN
            eState := 0;
        END_IF;

    20: // Ramping up MR Compressor
        bTrainRunning := TRUE;
        rTargetSpeed := cMinSpeed_RPM;

        // Simple ramp
        IF rActualSpeed < rTargetSpeed THEN
            rActualSpeed := rActualSpeed + 5.0; // Ramp rate
        ELSE
            eState := 30; // Min speed reached
        END_IF;
        rMR_CompressorSpeed_RPM := rActualSpeed;

        // Anti-surge control active during ramp
        rMR_SurgeValvePos_Pct := 50.0; // Partial close

    30: // Normal Operation
        // Control MR speed based on feed gas flow (Simplified feed-forward)
        rTargetSpeed := cMinSpeed_RPM + (rFeedGasFlow_kg_h * 0.1);
        IF rTargetSpeed > cMaxSpeed_RPM THEN
            rTargetSpeed := cMaxSpeed_RPM;
        END_IF;

        // Speed control loop
        IF rActualSpeed < rTargetSpeed THEN
            rActualSpeed := rActualSpeed + 2.0;
        ELSIF rActualSpeed > rTargetSpeed THEN
            rActualSpeed := rActualSpeed - 2.0;
        END_IF;
        rMR_CompressorSpeed_RPM := rActualSpeed;

        // Surge Margin Calculation
        IF rMR_SuctionPress_bar > 0.0 THEN
            rSurgeMargin := ((rMR_DischargePress_bar / rMR_SuctionPress_bar) / cSurgeLimit_Ratio) * 100.0;
        ELSE
            rSurgeMargin := 0.0;
        END_IF;

        // Anti-surge Valve PID (Simplified P-control)
        IF rSurgeMargin < cSafeSurgeMargin THEN
            rMR_SurgeValvePos_Pct := rMR_SurgeValvePos_Pct + 5.0; // Open valve to prevent surge
            bAlarmSurgeDetected := TRUE;
        ELSE
            rMR_SurgeValvePos_Pct := rMR_SurgeValvePos_Pct - 1.0; // Slowly close valve for efficiency
            bAlarmSurgeDetected := FALSE;
        END_IF;

        // Clamp valve pos
        IF rMR_SurgeValvePos_Pct > 100.0 THEN rMR_SurgeValvePos_Pct := 100.0; END_IF;
        IF rMR_SurgeValvePos_Pct < 0.0 THEN rMR_SurgeValvePos_Pct := 0.0; END_IF;

        // Discharge Pressure Monitoring
        IF rMR_DischargePress_bar > 85.0 THEN
            bAlarmHighPress := TRUE;
        ELSE
            bAlarmHighPress := FALSE;
        END_IF;

        IF bTrainStopCommand THEN
            eState := 40; // Shutdown sequence
        END_IF;

    40: // Shutdown Sequence
        rActualSpeed := rActualSpeed - 10.0; // Fast ramp down
        rMR_SurgeValvePos_Pct := 100.0; // Open surge valve
        IF rActualSpeed <= 0.0 THEN
            rActualSpeed := 0.0;
            eState := 0;
        END_IF;
        rMR_CompressorSpeed_RPM := rActualSpeed;

    99: // EMERGENCY SHUTDOWN
        bESD_Active := TRUE;
        bTrainRunning := FALSE;
        bBOG_CompressorStart := FALSE;
        rMR_CompressorSpeed_RPM := 0.0;
        rMR_SurgeValvePos_Pct := 100.0; // Open surge valve fully

        IF NOT bEmergencyShutdown THEN // Reset required
            bESD_Active := FALSE;
            eState := 0;
        END_IF;

    ELSE
        eState := 0;
END_CASE;

// MCHE Setpoint calculation based on pressure
rMCHE_TempSetpoint_C := -160.0 + (rFeedGasPress_bar * 0.05);

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_DRIE_BoschProcess
(* 
   Advanced Semiconductor Deep Reactive Ion Etch (DRIE) - Bosch Process Controller
   Provides deterministic control of SF6 isotropic etch and C4F8 passivation gas 
   switching with strict hysteresis, electrostatic chuck (ESC) backside helium 
   leak monitoring, and RF bias matching network synchronization. 
*)
VAR_INPUT
    (* Critical Safety and Enable Signals *)
    bSystemEnable           : BOOL;     (* Master process enable signal *)
    bEmergencyStopOk        : BOOL;     (* Safety circuit OK (TRUE = Healthy) *)
    bPlasmaStable           : BOOL;     (* RF Generator reports stable plasma ignition *)
    bChamberVacuumOk        : BOOL;     (* Turbo pump indicates base pressure achieved *)

    (* Process Parameters and Sensor Feedback *)
    rChamberPressure        : REAL;     (* Current chamber pressure in mTorr *)
    rESCHeliumFlow          : REAL;     (* Backside He flow rate in sccm *)
    rESCTemperature         : REAL;     (* Electrostatic Chuck temp in deg C *)
    rRFForwardPower         : REAL;     (* Forward RF power in Watts *)
    rRFReflectedPower       : REAL;     (* Reflected RF power in Watts *)

    (* Bosch Process Timing Parameters *)
    tEtchPhaseDuration      : TIME := T#3S; (* Duration for SF6 etch phase *)
    tPassivationPhaseDuration: TIME := T#2S;(* Duration for C4F8 passivation phase *)
    nTargetCycles           : INT := 100;   (* Number of Bosch process cycles to complete *)
END_VAR
VAR_OUTPUT
    (* System Status and Alarms *)
    bProcessActive          : BOOL;     (* DRIE Bosch process is currently running *)
    bProcessComplete        : BOOL;     (* Target cycles reached successfully *)
    bCriticalAlarm          : BOOL;     (* Hard fault, immediate abort required *)
    iAlarmCode              : INT;      (* Diagnostics: 0=None, 1=E-Stop, 2=Vacuum, 3=He Leak, 4=RF Fault *)

    (* Actuator Control Signals *)
    bValveSF6_Open          : BOOL;     (* Control signal for Etch gas MFC isolation valve *)
    bValveC4F8_Open         : BOOL;     (* Control signal for Passivation gas MFC isolation valve *)
    rThrottleValvePosition  : REAL;     (* Pressure control throttle valve (0-100%) *)
    rRFSetPoint             : REAL;     (* RF power setpoint to generator *)
END_VAR
VAR
    (* Internal State Machine and Counters *)
    iState                  : INT := 0; 
    iCurrentCycle           : INT := 0;

    (* Timers and Filters *)
    tPhaseTimer             : TON;
    tHeLeakFilter           : TON;

    (* Moving Averages / Signal Conditioning *)
    rHeLeakRateFiltered     : REAL := 0.0;
    rPressureError          : REAL := 0.0;

    (* Constants *)
    HE_LEAK_LIMIT           : REAL := 5.0;  (* Max allowable He flow in sccm indicating leakage *)
    RF_REFLECT_LIMIT        : REAL := 50.0; (* Max reflected power in Watts *)
END_VAR

(* === SAFETY & INTERLOCK EVALUATION === *)
IF NOT bEmergencyStopOk THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 1;
    bProcessActive := FALSE;
    bValveSF6_Open := FALSE;
    bValveC4F8_Open := FALSE;
    rRFSetPoint := 0.0;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

IF NOT bChamberVacuumOk AND bProcessActive THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 2;
    iState := 999;
END_IF;

(* Backside Helium Leak Detection with Noise Filtering *)
tHeLeakFilter(IN := (rESCHeliumFlow > HE_LEAK_LIMIT), PT := T#500MS);
IF tHeLeakFilter.Q THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 3;
    iState := 999;
END_IF;

(* RF Reflection Monitoring *)
IF bProcessActive AND (rRFReflectedPower > RF_REFLECT_LIMIT) THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 4;
    iState := 999;
END_IF;

(* === MAIN BOSCH PROCESS STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bProcessActive := FALSE;
        bProcessComplete := FALSE;
        bValveSF6_Open := FALSE;
        bValveC4F8_Open := FALSE;
        rRFSetPoint := 0.0;
        iCurrentCycle := 0;

        IF bSystemEnable AND bChamberVacuumOk AND NOT bCriticalAlarm THEN
            iState := 10; (* Transition to Pre-Process Stabilization *)
        END_IF;

    10: (* PRE-PROCESS STABILIZATION *)
        bProcessActive := TRUE;
        (* Set initial pressure throttle position and ignite plasma on low power *)
        rThrottleValvePosition := 15.0;
        rRFSetPoint := 100.0; 

        IF bPlasmaStable THEN
            iState := 20; (* Start Etch Phase *)
        END_IF;

    20: (* ETCH PHASE (SF6 Active) *)
        bValveSF6_Open := TRUE;
        bValveC4F8_Open := FALSE;
        rRFSetPoint := 800.0; (* High bias for anisotropic etch profile *)

        (* Simple Proportional Pressure Control for Etch Step *)
        rPressureError := 45.0 - rChamberPressure; (* Target 45 mTorr *)
        rThrottleValvePosition := LIMIT(0.0, rThrottleValvePosition + (rPressureError * 0.1), 100.0);

        tPhaseTimer(IN := TRUE, PT := tEtchPhaseDuration);
        IF tPhaseTimer.Q THEN
            tPhaseTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* PASSIVATION PHASE (C4F8 Active) *)
        bValveSF6_Open := FALSE;
        bValveC4F8_Open := TRUE;
        rRFSetPoint := 300.0; (* Lower power for conformal polymer deposition *)

        (* Simple Proportional Pressure Control for Passivation Step *)
        rPressureError := 20.0 - rChamberPressure; (* Target 20 mTorr *)
        rThrottleValvePosition := LIMIT(0.0, rThrottleValvePosition + (rPressureError * 0.05), 100.0);

        tPhaseTimer(IN := TRUE, PT := tPassivationPhaseDuration);
        IF tPhaseTimer.Q THEN
            tPhaseTimer(IN := FALSE);
            iCurrentCycle := iCurrentCycle + 1;

            IF iCurrentCycle >= nTargetCycles THEN
                iState := 100; (* Process Complete *)
            ELSE
                iState := 20; (* Loop back to Etch *)
            END_IF;
        END_IF;

    100: (* PROCESS COMPLETE SHUTDOWN *)
        bValveSF6_Open := FALSE;
        bValveC4F8_Open := FALSE;
        rRFSetPoint := 0.0;
        bProcessActive := FALSE;
        bProcessComplete := TRUE;

        IF NOT bSystemEnable THEN
            iState := 0; (* Reset to IDLE when enable is removed *)
        END_IF;

    999: (* FAULT HANDLING *)
        bValveSF6_Open := FALSE;
        bValveC4F8_Open := FALSE;
        rRFSetPoint := 0.0;
        bProcessActive := FALSE;
        (* Wait for manual reset via bSystemEnable toggle and fault clear *)
        IF NOT bSystemEnable AND bEmergencyStopOk THEN
            bCriticalAlarm := FALSE;
            iAlarmCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

