FUNCTION_BLOCK FB_RO_Desalination_Control
TITLE = 'RO Desalination Plant Advanced Control with ERD and CIP Sequencing'
VERSION : '1.2'

VAR_INPUT
    bStartSystem : BOOL; // Main start signal
    bStopSystem : BOOL; // Main stop signal
    bEmergencyStop : BOOL; // Emergency stop, normally high
    bInitiateCIP : BOOL; // Manual CIP sequence trigger
    rFeedWaterConductivity : REAL; // µS/cm
    rFeedWaterTemp : REAL; // Celsius
    rFeedWaterPressure : REAL; // bar, at LP pump discharge
    rHighPressureDischarge : REAL; // bar, HP pump discharge
    rBrinePressure : REAL; // bar, reject stream before ERD
    rPermeateFlow : REAL; // m3/h
    rBrineFlow : REAL; // m3/h
    rMembraneDP : REAL; // Differential pressure across membranes (bar)
    rERDSpeedFeedback : REAL; // rpm of Energy Recovery Device
END_VAR

VAR_OUTPUT
    bHPPumpRun : BOOL; // High Pressure pump run command
    rHPPumpSpeedRef : REAL; // High Pressure pump VFD speed reference (%)
    bLPPumpRun : BOOL; // Low Pressure feed pump run command
    rERDSpeedRef : REAL; // Energy Recovery Device speed reference (%)
    bCIPPumpRun : BOOL; // CIP Pump run command
    bChemicalDosingRun : BOOL; // Antiscalant dosing pump run command
    bPermeateValveOpen : BOOL; // Permeate divert valve (True = to storage)
    rSystemRecovery : REAL; // Calculated recovery rate (%)
    iSystemState : INT; // 0=Off, 1=Startup, 2=Production, 3=CIP, 4=Fault
    bFaultActive : BOOL; // Fault present
    iFaultCode : INT; // Error code
END_VAR

VAR
    TmrStartup : TON;
    TmrShutdown : TON;
    TmrCIPStage : TON;
    rTargetRecovery : REAL := 45.0; // Target recovery %
    rMaxMembraneDP : REAL := 2.5; // Max allowed DP
    iCIPStep : INT := 0;
    bMembraneFoulingDetected : BOOL := FALSE;
    PID_HP_Speed : FB_PID_Controller; // Imaginary PID FB
    PID_ERD_Sync : FB_PID_Controller;
END_VAR

// Implementation
IF NOT bEmergencyStop THEN
    iSystemState := 4;
    iFaultCode := 99; // E-Stop
    bHPPumpRun := FALSE;
    bLPPumpRun := FALSE;
    bCIPPumpRun := FALSE;
    bChemicalDosingRun := FALSE;
    bPermeateValveOpen := FALSE;
    rHPPumpSpeedRef := 0.0;
    rERDSpeedRef := 0.0;
    RETURN;
END_IF;

// Calculate System Recovery
IF (rPermeateFlow + rBrineFlow) > 0.0 THEN
    rSystemRecovery := (rPermeateFlow / (rPermeateFlow + rBrineFlow)) * 100.0;
ELSE
    rSystemRecovery := 0.0;
END_IF;

// Membrane Fouling Check
IF rMembraneDP > rMaxMembraneDP THEN
    bMembraneFoulingDetected := TRUE;
END_IF;

CASE iSystemState OF
    0: // OFF State
        bHPPumpRun := FALSE;
        bLPPumpRun := FALSE;
        bCIPPumpRun := FALSE;
        bChemicalDosingRun := FALSE;
        bPermeateValveOpen := FALSE;
        bFaultActive := FALSE;
        iFaultCode := 0;

        IF bStartSystem AND NOT bMembraneFoulingDetected THEN
            iSystemState := 1;
            TmrStartup(IN:=FALSE);
        ELSIF bInitiateCIP OR bMembraneFoulingDetected THEN
            iSystemState := 3;
            iCIPStep := 1;
        END_IF;

    1: // STARTUP
        bLPPumpRun := TRUE;
        bChemicalDosingRun := TRUE;
        TmrStartup(IN:=TRUE, PT:=T#10s);

        IF TmrStartup.Q THEN
            IF rFeedWaterPressure > 2.0 THEN
                bHPPumpRun := TRUE;
                // Ramp up HP pump
                rHPPumpSpeedRef := 30.0; 
                iSystemState := 2;
            ELSE
                iSystemState := 4; // Fault
                iFaultCode := 10; // Low feed pressure
            END_IF;
        END_IF;
        IF bStopSystem THEN iSystemState := 0; END_IF;

    2: // PRODUCTION
        // Regulate HP pump to maintain permeate flow target
        PID_HP_Speed(
            bEnable := TRUE,
            rSetpoint := 150.0, // example target permeate flow
            rProcessValue := rPermeateFlow,
            rKp := 1.2, rKi := 0.5,
            rOutput => rHPPumpSpeedRef
        );

        // Sync ERD with Brine Pressure to balance energy recovery
        PID_ERD_Sync(
            bEnable := TRUE,
            rSetpoint := rTargetRecovery,
            rProcessValue := rSystemRecovery,
            rKp := 2.0, rKi := 0.8,
            rOutput => rERDSpeedRef
        );

        // Permeate quality check
        IF rFeedWaterConductivity < 500.0 THEN
            bPermeateValveOpen := TRUE; // Good quality, send to storage
        ELSE
            bPermeateValveOpen := FALSE; // Bad quality, dump
        END_IF;

        IF bStopSystem THEN iSystemState := 0; END_IF;
        IF bMembraneFoulingDetected THEN iSystemState := 3; iCIPStep := 1; END_IF;

    3: // CIP (Clean In Place) SEQUENCING
        bHPPumpRun := FALSE;
        bLPPumpRun := FALSE;
        bPermeateValveOpen := FALSE;

        CASE iCIPStep OF
            1: // Flush
                bCIPPumpRun := TRUE;
                TmrCIPStage(IN:=TRUE, PT:=T#5m);
                IF TmrCIPStage.Q THEN
                    TmrCIPStage(IN:=FALSE);
                    iCIPStep := 2;
                END_IF;
            2: // Chemical Soak
                bCIPPumpRun := FALSE; // let it soak
                TmrCIPStage(IN:=TRUE, PT:=T#30m);
                IF TmrCIPStage.Q THEN
                    TmrCIPStage(IN:=FALSE);
                    iCIPStep := 3;
                END_IF;
            3: // Final Rinse
                bCIPPumpRun := TRUE;
                TmrCIPStage(IN:=TRUE, PT:=T#10m);
                IF TmrCIPStage.Q THEN
                    TmrCIPStage(IN:=FALSE);
                    bCIPPumpRun := FALSE;
                    bMembraneFoulingDetected := FALSE;
                    iSystemState := 0; // Return to off state
                    iCIPStep := 0;
                END_IF;
        END_CASE;

    4: // FAULT
        bHPPumpRun := FALSE;
        bLPPumpRun := FALSE;
        bCIPPumpRun := FALSE;
        bChemicalDosingRun := FALSE;
        bPermeateValveOpen := FALSE;
        bFaultActive := TRUE;

        IF NOT bStartSystem THEN // Reset condition
            iSystemState := 0;
            bFaultActive := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

