FUNCTION_BLOCK FB_DeepSpaceOpticalCommTerminal
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bSystemEnable       : BOOL;     (* Main enable signal for optical comm terminal *)
    bEmergencySafe      : BOOL;     (* Hardware interlock safe signal *)
    rLaserTempProcess   : REAL;     (* 1550nm EDFA pump diode temperature [deg C] *)
    rFSM_X_JitterError  : LREAL;    (* Fast steering mirror X-axis microradian error [urad] *)
    rFSM_Y_JitterError  : LREAL;    (* Fast steering mirror Y-axis microradian error [urad] *)
    rAPD_PhotonCount    : DINT;     (* Avalanche photodiode photon count rate [cps] *)
    rDistanceToEarth    : LREAL;    (* Current distance to Earth ground station [AU] *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bTerminalReady      : BOOL;     (* Terminal initialization complete, tracking active *)
    rEDFAPumpCurrent    : REAL;     (* Control signal for EDFA pump diode current [mA] *)
    rFSM_X_Control      : LREAL;    (* Fast steering mirror X-axis actuation command [V] *)
    rFSM_Y_Control      : LREAL;    (* Fast steering mirror Y-axis actuation command [V] *)
    rAPD_BiasVoltage    : REAL;     (* Avalanche photodiode dynamic bias voltage [V] *)
    bCriticalFault      : BOOL;     (* Critical fault requiring immediate safing *)
END_VAR
VAR
    (* Internal state variables *)
    iOpMode             : INT := 0; (* Internal state machine phase *)
    tWarmupTimer        : TON;
    tTrackingTimer      : TON;

    (* PID Controllers state *)
    rIntegralX          : LREAL := 0.0;
    rIntegralY          : LREAL := 0.0;
    rPrevErrorX         : LREAL := 0.0;
    rPrevErrorY         : LREAL := 0.0;
    rKp_FSM             : LREAL := 0.45;
    rKi_FSM             : LREAL := 0.015;
    rKd_FSM             : LREAL := 0.005;

    (* Thermal control constants *)
    rTempSetpoint       : REAL := 22.5; (* Optimal EDFA temperature *)
    rTempDeadband       : REAL := 0.1;

    (* APD Bias constants *)
    rBaseBiasVoltage    : REAL := 180.0;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencySafe THEN
    (* Immediate hardware safing *)
    bTerminalReady := FALSE;
    bCriticalFault := TRUE;
    rEDFAPumpCurrent := 0.0;
    rFSM_X_Control := 0.0;
    rFSM_Y_Control := 0.0;
    rAPD_BiasVoltage := 0.0;
    iOpMode := 0;
    RETURN;
END_IF;

CASE iOpMode OF
    0: (* STANDBY / IDLE *)
        bTerminalReady := FALSE;
        bCriticalFault := FALSE;
        rEDFAPumpCurrent := 0.0;
        rFSM_X_Control := 0.0;
        rFSM_Y_Control := 0.0;
        rAPD_BiasVoltage := 0.0;

        IF bSystemEnable THEN
            iOpMode := 10; (* Transition to Thermal Stabilization *)
        END_IF;

    10: (* THERMAL STABILIZATION *)
        (* Bang-bang control with deadband for EDFA pump *)
        IF rLaserTempProcess < (rTempSetpoint - rTempDeadband) THEN
            rEDFAPumpCurrent := 150.0; (* Heating current *)
        ELSIF rLaserTempProcess > (rTempSetpoint + rTempDeadband) THEN
            rEDFAPumpCurrent := 0.0;   (* Cooling phase *)
        ELSE
            rEDFAPumpCurrent := 75.0;  (* Maintenance current *)
        END_IF;

        tWarmupTimer(IN := TRUE, PT := T#30S);
        IF tWarmupTimer.Q AND (ABS(rLaserTempProcess - rTempSetpoint) <= rTempDeadband) THEN
            tWarmupTimer(IN := FALSE);
            iOpMode := 20; (* Transition to Bias Calibration *)
        END_IF;

    20: (* BIAS CALIBRATION & SENSOR ACTIVATION *)
        (* Distance-dependent bias voltage calculation for optimal SNR *)
        IF rDistanceToEarth > 2.0 THEN
            rAPD_BiasVoltage := rBaseBiasVoltage + 15.0; (* High gain for extreme deep space *)
        ELSE
            rAPD_BiasVoltage := rBaseBiasVoltage + (LREAL_TO_REAL(rDistanceToEarth) * 5.0);
        END_IF;

        IF rAPD_PhotonCount > 10 THEN (* Background threshold met *)
            iOpMode := 30;
        END_IF;

    30: (* PRECISION TRACKING / JITTER REJECTION *)
        bTerminalReady := TRUE;

        (* PID Control for Fast Steering Mirror X-Axis *)
        rIntegralX := rIntegralX + (rFSM_X_JitterError * 0.001);
        rFSM_X_Control := (rKp_FSM * rFSM_X_JitterError) + (rKi_FSM * rIntegralX) + (rKd_FSM * (rFSM_X_JitterError - rPrevErrorX) / 0.001);
        rPrevErrorX := rFSM_X_JitterError;

        (* PID Control for Fast Steering Mirror Y-Axis *)
        rIntegralY := rIntegralY + (rFSM_Y_JitterError * 0.001);
        rFSM_Y_Control := (rKp_FSM * rFSM_Y_JitterError) + (rKi_FSM * rIntegralY) + (rKd_FSM * (rFSM_Y_JitterError - rPrevErrorY) / 0.001);
        rPrevErrorY := rFSM_Y_JitterError;

        (* Monitor for loss of lock or track degradation *)
        IF ABS(rFSM_X_JitterError) > 50.0 OR ABS(rFSM_Y_JitterError) > 50.0 THEN
            bCriticalFault := TRUE;
            iOpMode := 0;
        END_IF;

        IF NOT bSystemEnable THEN
            iOpMode := 0;
        END_IF;

END_CASE;

