FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // Enable centrifuge operation
    rTargetBowlSpeed : REAL; // Target bowl speed in RPM (e.g., 5000.0)
    rDifferentialSpeedTarget : REAL; // Target scroll differential speed (e.g., 5.0 to 40.0 RPM)
    rFeedRate : REAL; // Feed rate of algae slurry (L/min)
    rCurrentVibration : REAL; // Current vibration reading (mm/s)
    rTorqueScroll : REAL; // Current torque on the scroll (Nm)
    rSludgeConcentration : REAL; // Measured sludge density/concentration
    bEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    bRunning : BOOL;
    rBowlSpeedCmd : REAL; // Command to bowl VFD
    rScrollSpeedCmd : REAL; // Command to scroll VFD
    rFeedPumpCmd : REAL; // Command to feed pump
    rVibrationDampenerCmd : REAL; // Command to active magnetic bearings/dampeners
    bSludgeDischargeValve : BOOL; // Control of the sludge discharge ports
    bAlarm : BOOL;
    nState : INT; // State machine state
END_VAR

VAR
    rActualBowlSpeed : REAL := 0.0;
    rActualScrollSpeed : REAL := 0.0;
    rVibrationThreshold1 : REAL := 12.0; // Warning
    rVibrationThreshold2 : REAL := 25.0; // Trip
    rMaxTorque : REAL := 1500.0;

    // PID for differential speed
    rDiffSpeedError : REAL;
    rDiffSpeedIntegral : REAL;
    rKp_Diff : REAL := 0.5;
    rKi_Diff : REAL := 0.1;

    // PID for vibration dampening
    rVibError : REAL;
    rKp_Vib : REAL := 1.2;

    // State machine constants
    STATE_IDLE : INT := 0;
    STATE_SPIN_UP : INT := 1;
    STATE_RUNNING : INT := 2;
    STATE_DISCHARGE : INT := 3;
    STATE_SPIN_DOWN : INT := 4;
    STATE_FAULT : INT := 5;

    tDischargeTimer : TIME;
    bDischargeActive : BOOL;
END_VAR

// Implementation
IF bEmergencyStop THEN
    nState := STATE_FAULT;
    bRunning := FALSE;
    rBowlSpeedCmd := 0.0;
    rScrollSpeedCmd := 0.0;
    rFeedPumpCmd := 0.0;
    rVibrationDampenerCmd := 0.0;
    bSludgeDischargeValve := FALSE;
    bAlarm := TRUE;
    RETURN;
END_IF;

CASE nState OF
    STATE_IDLE:
        bRunning := FALSE;
        rBowlSpeedCmd := 0.0;
        rScrollSpeedCmd := 0.0;
        rFeedPumpCmd := 0.0;
        bSludgeDischargeValve := FALSE;
        IF bEnable THEN
            nState := STATE_SPIN_UP;
        END_IF;

    STATE_SPIN_UP:
        bRunning := TRUE;
        IF rBowlSpeedCmd < rTargetBowlSpeed THEN
            rBowlSpeedCmd := rBowlSpeedCmd + 10.0; 
        ELSE
            rBowlSpeedCmd := rTargetBowlSpeed;
            nState := STATE_RUNNING;
        END_IF;
        rScrollSpeedCmd := rBowlSpeedCmd;

    STATE_RUNNING:
        bRunning := TRUE;
        rBowlSpeedCmd := rTargetBowlSpeed;

        rDiffSpeedError := rDifferentialSpeedTarget - (rBowlSpeedCmd - rScrollSpeedCmd);
        rDiffSpeedIntegral := rDiffSpeedIntegral + rDiffSpeedError * 0.1;
        rScrollSpeedCmd := rBowlSpeedCmd - (rDifferentialSpeedTarget + (rKp_Diff * rDiffSpeedError) + (rKi_Diff * rDiffSpeedIntegral));

        IF rSludgeConcentration < 50.0 THEN
            rFeedPumpCmd := rFeedRate;
        ELSE
            rFeedPumpCmd := rFeedRate * 0.5; 
        END_IF;

        IF rTorqueScroll > rMaxTorque THEN
            rScrollSpeedCmd := rBowlSpeedCmd - (rDifferentialSpeedTarget + 10.0);
            bSludgeDischargeValve := TRUE; 
        ELSE
            bSludgeDischargeValve := FALSE;
        END_IF;

        IF rCurrentVibration > rVibrationThreshold2 THEN
            nState := STATE_FAULT;
        ELSIF rCurrentVibration > rVibrationThreshold1 THEN
            rVibError := rCurrentVibration - rVibrationThreshold1;
            rVibrationDampenerCmd := rKp_Vib * rVibError;
        ELSE
            rVibrationDampenerCmd := 0.0;
        END_IF;

        IF NOT bEnable THEN
            nState := STATE_SPIN_DOWN;
        END_IF;

    STATE_SPIN_DOWN:
        bRunning := TRUE;
        rFeedPumpCmd := 0.0;
        IF rBowlSpeedCmd > 0.0 THEN
            rBowlSpeedCmd := rBowlSpeedCmd - 15.0;
        ELSE
            rBowlSpeedCmd := 0.0;
            nState := STATE_IDLE;
        END_IF;
        rScrollSpeedCmd := rBowlSpeedCmd;

    STATE_FAULT:
        bRunning := FALSE;
        rFeedPumpCmd := 0.0;
        rBowlSpeedCmd := 0.0; 
        rScrollSpeedCmd := 0.0;
        bAlarm := TRUE;
        IF NOT bEmergencyStop AND NOT bEnable THEN
            bAlarm := FALSE;
            nState := STATE_IDLE;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
