FUNCTION_BLOCK "Ozone_Profinet_Diag"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
    Dew_Point : REAL;
    // Profinet Inputs
    VFD_Status_Word : WORD;
    VFD_Actual_Freq : REAL;
END_VAR
VAR_OUTPUT
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    // Profinet Outputs
    VFD_Control_Word : WORD;
    VFD_Freq_Setpoint : REAL;
    // Diagnostics
    Alarm_Critical : BOOL;
    Alarm_Warning : BOOL;
    Alarm_Code : INT;
END_VAR
VAR
    Run_Cmd : BOOL;
    VFD_Ready : BOOL;
    VFD_Fault : BOOL;
END_VAR

BEGIN
    // Decode Profinet VFD Status
    VFD_Ready := (VFD_Status_Word AND 16#0001) > 0;
    VFD_Fault := (VFD_Status_Word AND 16#0008) > 0;

    // Diagnostics & Alarm Prioritization
    Alarm_Critical := FALSE;
    Alarm_Warning := FALSE;
    Alarm_Code := 0;

    IF Dew_Point > -60.0 THEN
        Alarm_Critical := TRUE;
        Alarm_Code := 101;
    ELSIF VFD_Fault THEN
        Alarm_Critical := TRUE;
        Alarm_Code := 102;
    ELSIF O3_Actual > (O3_SetPoint * 1.2) THEN
        Alarm_Warning := TRUE;
        Alarm_Code := 201;
    END_IF;

    // System Control
    IF Start AND NOT Stop AND NOT Alarm_Critical AND VFD_Ready THEN
        Run_Cmd := TRUE;
    ELSIF Stop OR Alarm_Critical THEN
        Run_Cmd := FALSE;
    END_IF;

    // Encode Profinet VFD Control
    IF Run_Cmd THEN
        VFD_Control_Word := 16#047F; // Start and Ready
        VFD_Freq_Setpoint := 50.0; // Fixed nominal for demo
    ELSE
        VFD_Control_Word := 16#047E; // Stop
        VFD_Freq_Setpoint := 0.0;
    END_IF;

    Generator_Enable := Run_Cmd;

    // O3 Power Scaling
    IF Generator_Enable THEN
        Power_Scale_Out := O3_SetPoint - O3_Actual; // Proportional base
        IF Power_Scale_Out > 100.0 THEN Power_Scale_Out := 100.0; END_IF;
        IF Power_Scale_Out < 0.0 THEN Power_Scale_Out := 0.0; END_IF;
    ELSE
        Power_Scale_Out := 0.0;
    END_IF;
END_FUNCTION_BLOCK
