FUNCTION_BLOCK FB_OrbitalRefuelingDepot
(*
  =============================================================================
  MODULE     : Commercial Spaceflight Orbital Refueling Depot
  AUTHOR     : Lumina Elite Synthetic Data Architect (40-year veteran)
  SYSTEM     : Micro-gravity liquid hydrogen/oxygen slosh dynamics damping,
               ullage motor synthetic spin stabilization, and cryogenic
               quick-disconnect orbital coupling.
  =============================================================================
*)
VAR_INPUT
    bSystemEnable        : BOOL;   (* Main activation signal for orbital depot operations *)
    bEmergencyAbort      : BOOL;   (* Safety critical abort / explosive bolt trigger *)
    rLOX_TankLevel       : REAL;   (* Liquid Oxygen Tank fill percentage (0.0 - 100.0) *)
    rLH2_TankLevel       : REAL;   (* Liquid Hydrogen Tank fill percentage (0.0 - 100.0) *)
    rUllageAccel         : REAL;   (* Measured linear acceleration in z-axis (m/s^2) for settling *)
    rSloshRateX          : REAL;   (* Propellant slosh oscillation angular rate X-axis (rad/s) *)
    bQuickDisconnectLock : BOOL;   (* True if cryogenic quick disconnect is mechanically locked *)
END_VAR
VAR_OUTPUT
    bSystemReady         : BOOL;   (* Depot ready to commence active pumping operations *)
    bTransferActive      : BOOL;   (* Cryo pumping sequence is currently underway *)
    rUllageThrustCmd     : REAL;   (* Command for ullage motor thrust level (N) *)
    rSloshDampTorqueX    : REAL;   (* Command for RCS thrusters to damp slosh in X-axis (Nm) *)
    bCryoFault           : BOOL;   (* True if thermal, mechanical, or pressure fault detected *)
    iOperationState      : INT;    (* Current state machine step *)
END_VAR
VAR
    iState               : INT := 0; (* Internal SM state *)
    tUllageTimer         : TON;      (* Timer for propellant settling phase *)
    tTransferTimer       : TON;      (* Timer for transfer duration timeout *)
    rTargetAccel         : REAL := 0.001; (* 1 milli-g required for micro-g fluid settling *)
    rSloshGainP          : REAL := 2500.5; (* Proportional gain for slosh suppression *)
    rSloshGainD          : REAL := 800.2;  (* Derivative gain for slosh suppression *)
    rPrevSloshRateX      : REAL := 0.0;
    rSloshDerivative     : REAL := 0.0;
    cycleTime            : REAL := 0.01; (* 10ms execution cycle *)
END_VAR

(* === MAIN LOGIC === *)
IF bEmergencyAbort THEN
    bSystemReady      := FALSE;
    bTransferActive   := FALSE;
    rUllageThrustCmd  := 0.0;
    rSloshDampTorqueX := 0.0;
    bCryoFault        := TRUE;
    iState            := 999; (* Abort state *)
    RETURN;
END_IF;

(* Active Slosh Damping - PD Controller executed every cycle *)
rSloshDerivative := (rSloshRateX - rPrevSloshRateX) / cycleTime;
rSloshDampTorqueX := -(rSloshGainP * rSloshRateX + rSloshGainD * rSloshDerivative);
rPrevSloshRateX := rSloshRateX;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bTransferActive := FALSE;
        rUllageThrustCmd := 0.0;
        IF bSystemEnable AND bQuickDisconnectLock THEN
            iState := 10;
        END_IF;

    10: (* PROPELLANT SETTLING / ULLAGE MOTOR FIRING *)
        (* Command low thrust to settle cryogenic fluids in microgravity *)
        rUllageThrustCmd := 50.0; (* 50 Newtons settling thrust *)
        tUllageTimer(IN := (rUllageAccel >= rTargetAccel), PT := T#120S);
        IF tUllageTimer.Q THEN
            iState := 20;
        END_IF;

    20: (* READY TO TRANSFER *)
        bSystemReady := TRUE;
        rUllageThrustCmd := 10.0; (* Maintain minimal positive g *)
        IF bSystemEnable AND bQuickDisconnectLock THEN
            iState := 30;
        ELSIF NOT bQuickDisconnectLock THEN
            iState := 999; (* Disconnect fault *)
        END_IF;

    30: (* ACTIVE TRANSFER *)
        bSystemReady := TRUE;
        bTransferActive := TRUE;
        tTransferTimer(IN := TRUE, PT := T#3600S); (* Max transfer time 1 hr *)

        IF (rLOX_TankLevel >= 99.5 AND rLH2_TankLevel >= 99.5) OR tTransferTimer.Q THEN
            bTransferActive := FALSE;
            tTransferTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* POST-TRANSFER SAFING *)
        bSystemReady := FALSE;
        rUllageThrustCmd := 0.0;
        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bTransferActive := FALSE;
        rUllageThrustCmd := 0.0;
        bCryoFault := TRUE;
        (* Wait for explicit reset by operator disabling system enable *)
        IF NOT bSystemEnable THEN
            bCryoFault := FALSE;
            iState := 0;
        END_IF;

END_CASE;

iOperationState := iState;

END_FUNCTION_BLOCK
