    rRunnerBladePitchOut        : REAL;     (* Commanded runner blade pitch angle (Degrees) *)
    bPenstockSurgeAlarm         : BOOL;     (* High pressure surge warning (Water Hammer risk) *)
    bVibrationFlutterAlarm      : BOOL;     (* Detection of structural flutter on wicket gates *)
    iCurrentControlState        : INT;      (* Internal state machine indicator for SCADA display *)
END_VAR

VAR
    iState                      : INT := 0; 
    tSyncTimer                  : TON;
    tDampingTimer               : TON;

    (* Internal process variables for PI/PID loops *)
    rErrorSpeed                 : REAL;
    rIntSpeed                   : REAL := 0.0;
    rWicketGateCmdCalc          : REAL := 0.0;

    (* Water hammer & flutter protection thresholds *)
    rMaxPressureLimit           : REAL := 65.0;     (* Bar *)
    rSurgeDerivativeLimit       : REAL := 15.0;     (* Bar/sec *)
    rPrevPressure               : REAL := 0.0;

    (* Anti-flutter compensation parameters *)
    rDampingGain                : REAL := 0.45;
    rOscillationFilter          : REAL := 0.0;

    rDeltaT                     : REAL := 0.01;     (* Assumed 10ms execution cycle *)
END_VAR

(* === MAIN SAFETY AND OVERRIDE LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReadyToSync := FALSE;
    rWicketGatePositionOut := 0.0; (* Slam gates shut safely *)
    rRunnerBladePitchOut := 0.0;
    bPenstockSurgeAlarm := TRUE;
    iCurrentControlState := 999; (* 999 = FAULT *)
    RETURN;
END_IF;

(* === WATER HAMMER PREDICTION & SURGE PROTECTION === *)
(* Calculate discrete derivative of penstock pressure *)
IF (rPenstockPressure - rPrevPressure) / rDeltaT > rSurgeDerivativeLimit OR rPenstockPressure > rMaxPressureLimit THEN
    bPenstockSurgeAlarm := TRUE;
    (* Force slow gate closure to prevent catastrophic burst *)
    rWicketGatePositionOut := rWicketGatePositionOut - 0.1;
    IF rWicketGatePositionOut < 0.0 THEN rWicketGatePositionOut := 0.0; END_IF;
ELSE
    bPenstockSurgeAlarm := FALSE;
END_IF;
rPrevPressure := rPenstockPressure;

(* === MAIN CONTROL STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & PRE-START CHECKS *)
        iCurrentControlState := 0;
        bSystemReadyToSync := FALSE;
        rWicketGatePositionOut := 0.0;

        IF bEnableSys AND NOT bPenstockSurgeAlarm THEN
            iState := 10;
        END_IF;

    10: (* SPEED-NO-LOAD SPINNING *)
        iCurrentControlState := 10;
        (* Simple PI control for reaching synchronous speed *)
        rErrorSpeed := 300.0 - rTurbineSpeedRPM; (* Assuming 300 RPM sync speed *)
        rIntSpeed := rIntSpeed + (rErrorSpeed * rDeltaT * 0.5);
        rWicketGateCmdCalc := (rErrorSpeed * 2.0) + rIntSpeed;

        (* Clamp output *)
        IF rWicketGateCmdCalc > 25.0 THEN rWicketGateCmdCalc := 25.0; END_IF;
        IF rWicketGateCmdCalc < 0.0 THEN rWicketGateCmdCalc := 0.0; END_IF;

        rWicketGatePositionOut := rWicketGateCmdCalc;

        IF ABS(rErrorSpeed) < 2.0 THEN
            tSyncTimer(IN := TRUE, PT := T#5S);
            IF tSyncTimer.Q THEN
                bSystemReadyToSync := TRUE;
                tSyncTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tSyncTimer(IN := FALSE);
        END_IF;

    20: (* SYNCHRONIZED & ACTIVE POWER CONTROL OR SYNCHRONOUS CONDENSER MODE *)
        iCurrentControlState := 20;
        IF bReqSyncCondenserMode THEN
            (* Transition to synchronous condenser mode (blow down water) *)
            rWicketGatePositionOut := 0.0;
            (* Additional blow-down logic omitted for brevity *)
        ELSE
            (* Normal generation mode *)
            rWicketGatePositionOut := (rActivePowerSetpt / 300.0) * 100.0;

            (* Active Flutter Damping - Injecting anti-phase noise compensation *)
            rOscillationFilter := (rOscillationFilter * 0.9) + (rTurbineSpeedRPM * 0.1);
            IF ABS(rTurbineSpeedRPM - rOscillationFilter) > 1.5 THEN
                bVibrationFlutterAlarm := TRUE;
                rWicketGatePositionOut := rWicketGatePositionOut - (rDampingGain * (rTurbineSpeedRPM - rOscillationFilter));
            ELSE
                bVibrationFlutterAlarm := FALSE;
            END_IF;
        END_IF;

        IF NOT bEnableSys THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
