FUNCTION_BLOCK FB_LISA_DragFreeControl
VAR_INPUT
    (* Sub-picometer metrology inputs from local interferometer *)
    rProofMassPos_X : LREAL; (* Proof mass position X-axis relative to optical bench [m] *)
    rProofMassPos_Y : LREAL; (* Proof mass position Y-axis relative to optical bench [m] *)
    rProofMassPos_Z : LREAL; (* Proof mass position Z-axis relative to optical bench [m] *)

    (* External system state and interlocks *)
    bSystemEnable : BOOL; (* Master control enable for Drag-Free mode *)
    bEmergencySafeMode : BOOL; (* Thruster or payload fault requiring safe mode *)

    (* Thermal stability monitoring *)
    rOpticalBenchTemp : LREAL; (* Optical bench temperature [K] *)

    (* Inter-spacecraft interferometry link status *)
    bLinkLockAcquired : BOOL; (* Phase lock loop locked with distant spacecraft *)
END_VAR
VAR_OUTPUT
    (* Micro-Newton Colloidal Thruster Command Outputs *)
    rThrusterCmd_X : LREAL; (* Commanded thrust X-axis [N] *)
    rThrusterCmd_Y : LREAL; (* Commanded thrust Y-axis [N] *)
    rThrusterCmd_Z : LREAL; (* Commanded thrust Z-axis [N] *)

    (* Status flags *)
    bDragFreeActive : BOOL; (* True when spacecraft is tracking proof mass freely *)
    bThermalAlarm : BOOL; (* True if optical bench temperature instability exceeds limits *)
    iSystemState : INT; (* Telemetry state integer *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState : INT := 0; (* Internal state machine tracker *)
    tModeTransitionDelay : TON;
    tThermalFilterTimer : TON;

    (* PID Controller variables for Drag-Free loop (simplified 3-DOF) *)
    rKp : LREAL := 1.5E-2; (* Proportional gain [N/m] *)
    rKi : LREAL := 1.0E-4; (* Integral gain [N/(m*s)] *)
    rKd : LREAL := 5.0E-2; (* Derivative gain [N*s/m] *)

    rIntegralX : LREAL := 0.0;
    rIntegralY : LREAL := 0.0;
    rIntegralZ : LREAL := 0.0;

    rPrevPosX : LREAL := 0.0;
    rPrevPosY : LREAL := 0.0;
    rPrevPosZ : LREAL := 0.0;

    (* Reference limits *)
    rMaxThrust : LREAL := 30.0E-6; (* 30 micro-Newtons max thrust per axis *)
    rTempNominal : LREAL := 293.15; (* 20 C nominal *)
    rTempTolerance : LREAL := 1.0E-5; (* 10 micro-Kelvin stability requirement *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety and Interlock Check *)
IF bEmergencySafeMode THEN
    (* Immediate suspension of active thruster firing, transition to safe mode *)
    bDragFreeActive := FALSE;
    rThrusterCmd_X := 0.0;
    rThrusterCmd_Y := 0.0;
    rThrusterCmd_Z := 0.0;
    iState := 99; (* Safe Mode State *)
    iSystemState := iState;
    RETURN;
END_IF;

(* 2. Thermal Stability Monitoring *)
IF ABS(rOpticalBenchTemp - rTempNominal) > rTempTolerance THEN
    tThermalFilterTimer(IN := TRUE, PT := T#5S);
    IF tThermalFilterTimer.Q THEN
        bThermalAlarm := TRUE;
    END_IF;
ELSE
    tThermalFilterTimer(IN := FALSE);
    bThermalAlarm := FALSE;
END_IF;

(* 3. Drag-Free State Machine *)
CASE iState OF
    0: (* IDLE - Wait for System Enable *)
        bDragFreeActive := FALSE;
        rThrusterCmd_X := 0.0;
        rThrusterCmd_Y := 0.0;
        rThrusterCmd_Z := 0.0;

        IF bSystemEnable AND bLinkLockAcquired AND NOT bThermalAlarm THEN
            (* Begin transition to Drag-Free Mode *)
            iState := 10;
        END_IF;

    10: (* TRANSITION - Delay for thruster warm-up and calibration *)
        tModeTransitionDelay(IN := TRUE, PT := T#30S);
        IF tModeTransitionDelay.Q THEN
            tModeTransitionDelay(IN := FALSE);
            (* Reset integrators before engaging loop *)
            rIntegralX := 0.0;
            rIntegralY := 0.0;
            rIntegralZ := 0.0;
            rPrevPosX := rProofMassPos_X;
            rPrevPosY := rProofMassPos_Y;
            rPrevPosZ := rProofMassPos_Z;
            iState := 20;
        END_IF;

        IF NOT bSystemEnable THEN
            tModeTransitionDelay(IN := FALSE);
            iState := 0;
        END_IF;

    20: (* DRAG-FREE ACTIVE - Closed loop control of spacecraft around proof mass *)
        bDragFreeActive := TRUE;

        (* X-Axis PID *)
        rIntegralX := rIntegralX + (rProofMassPos_X * 0.1); (* Assuming 10Hz task rate *)
        rThrusterCmd_X := (rProofMassPos_X * rKp) + (rIntegralX * rKi) + ((rProofMassPos_X - rPrevPosX) * rKd);

        (* Y-Axis PID *)
        rIntegralY := rIntegralY + (rProofMassPos_Y * 0.1);
        rThrusterCmd_Y := (rProofMassPos_Y * rKp) + (rIntegralY * rKi) + ((rProofMassPos_Y - rPrevPosY) * rKd);

        (* Z-Axis PID *)
        rIntegralZ := rIntegralZ + (rProofMassPos_Z * 0.1);
        rThrusterCmd_Z := (rProofMassPos_Z * rKp) + (rIntegralZ * rKi) + ((rProofMassPos_Z - rPrevPosZ) * rKd);

        (* Saturation Limits / Anti-windup *)
        IF rThrusterCmd_X > rMaxThrust THEN rThrusterCmd_X := rMaxThrust; END_IF;
        IF rThrusterCmd_X < -rMaxThrust THEN rThrusterCmd_X := -rMaxThrust; END_IF;

        IF rThrusterCmd_Y > rMaxThrust THEN rThrusterCmd_Y := rMaxThrust; END_IF;
        IF rThrusterCmd_Y < -rMaxThrust THEN rThrusterCmd_Y := -rMaxThrust; END_IF;

        IF rThrusterCmd_Z > rMaxThrust THEN rThrusterCmd_Z := rMaxThrust; END_IF;
        IF rThrusterCmd_Z < -rMaxThrust THEN rThrusterCmd_Z := -rMaxThrust; END_IF;

        (* Store previous positions for next derivative calculation *)
        rPrevPosX := rProofMassPos_X;
        rPrevPosY := rProofMassPos_Y;
        rPrevPosZ := rProofMassPos_Z;

        (* Exit conditions *)
        IF NOT bSystemEnable OR bThermalAlarm OR NOT bLinkLockAcquired THEN
            iState := 0;
        END_IF;

    99: (* SAFE MODE - Wait for manual intervention *)
        bDragFreeActive := FALSE;
        rThrusterCmd_X := 0.0;
        rThrusterCmd_Y := 0.0;
        rThrusterCmd_Z := 0.0;

        IF NOT bEmergencySafeMode AND NOT bSystemEnable THEN
            (* Require enable to be toggled off to clear safe mode *)
            iState := 0;
        END_IF;

END_CASE;

(* Update telemetry output *)
iSystemState := iState;

END_FUNCTION_BLOCK
