\nFUNCTION_BLOCK FB_AntiSurgeControl
FUNCTION_BLOCK FB_IndustrialControl
// Advanced Centrifugal Compressor Anti-Surge Control with VIGV Tuning
VAR_INPUT
    rDischargePressure    : REAL; // PT-1002 (kPa)
    rSuctionPressure      : REAL; // PT-1001 (kPa)
    rDischargeTemp        : REAL; // TT-1002 (DegC)
    rSuctionTemp          : REAL; // TT-1001 (DegC)
    rFlowRate             : REAL; // FT-1001 (kg/s)
    rCompressorSpeed      : REAL; // ST-1001 (RPM)
    rGasMolecularWeight   : REAL; // AT-1001 (g/mol)
    rCompressibility      : REAL; // Z-factor
    rVIGV_Position        : REAL; // ZT-1001 (%)
    bEnable               : BOOL; // Master Enable
    rSurgeMarginSetpt     : REAL := 10.0; // Desired Margin (%)
END_VAR

VAR_OUTPUT
    rRecycleValveCmd      : REAL; // CV-1001 Command (0-100%)
    rVIGV_Cmd             : REAL; // CV-1002 Command (0-100%)
    bSurgeAlarm           : BOOL; // Surge proximity alarm
    bTripAlarm            : BOOL; // Compressor trip command
    rCalculatedSurgeFlow  : REAL; // Mapped Surge Line Flow
END_VAR

VAR
    rPressureRatio        : REAL;
    rReducedFlow          : REAL;
    rSurgeLineParamA      : REAL := 0.55;
    rSurgeLineParamB      : REAL := 1.25;
    rSurgeLineParamC      : REAL := 0.005;
    rDeviation            : REAL;
    rPID_Integral         : REAL := 0.0;
    rPID_PrevError        : REAL := 0.0;
    rKp                   : REAL := 2.5;
    rKi                   : REAL := 0.8;
    rKd                   : REAL := 0.1;
    rDt                   : REAL := 0.05; // 50ms scan rate
    rDerivative           : REAL;
    rControlOutput        : REAL;
    rVIGV_Correction      : REAL;
    rError                : REAL;
END_VAR

IF NOT bEnable THEN
    rRecycleValveCmd := 100.0; // Fail-safe open
    rVIGV_Cmd := 0.0; // Fail-safe closed
    bSurgeAlarm := FALSE;
    bTripAlarm := FALSE;
    RETURN;
END_IF;

// Calculate Polytropic Head proxy (Pressure Ratio)
IF rSuctionPressure > 0.0 THEN
    rPressureRatio := rDischargePressure / rSuctionPressure;
ELSE
    rPressureRatio := 1.0;
END_IF;

// Calculate Reduced Flow (Corrected for Temp, MW, Z)
rReducedFlow := rFlowRate * SQRT(rSuctionTemp / (rGasMolecularWeight * rCompressibility)) / rSuctionPressure;

// VIGV position modifies the surge line characteristics
rVIGV_Correction := rVIGV_Position * 0.002;

// Calculate the expected Surge Flow at current Pressure Ratio and VIGV position
// Using a pseudo-quadratic map adjusted by VIGV
rCalculatedSurgeFlow := (rSurgeLineParamA * rPressureRatio * rPressureRatio) 
                      + (rSurgeLineParamB * rPressureRatio) 
                      + rSurgeLineParamC 
                      - rVIGV_Correction;

// Determine Operating Deviation from Surge Line
rDeviation := rReducedFlow - rCalculatedSurgeFlow;

// Alarm Logic
IF rDeviation < (rCalculatedSurgeFlow * (rSurgeMarginSetpt / 100.0)) THEN
    bSurgeAlarm := TRUE;
ELSE
    bSurgeAlarm := FALSE;
END_IF;

IF rDeviation < (rCalculatedSurgeFlow * -0.05) THEN
    bTripAlarm := TRUE; // Immediate trip if inside surge limit
ELSE
    bTripAlarm := FALSE;
END_IF;

// Anti-Surge PID Controller (Fast acting for Recycle Valve)
// Setpoint is SurgeFlow + Margin
rError := (rCalculatedSurgeFlow * (1.0 + rSurgeMarginSetpt / 100.0)) - rReducedFlow;

IF rError > 0.0 THEN
    rPID_Integral := rPID_Integral + (rError * rDt);
    rDerivative := (rError - rPID_PrevError) / rDt;
    rControlOutput := (rKp * rError) + (rKi * rPID_Integral) + (rKd * rDerivative);

    // Asymmetric response - open fast, close slow
    rRecycleValveCmd := rRecycleValveCmd + (rControlOutput * 2.0); 
ELSE
    // Gradually close recycle valve if safely away from surge
    rRecycleValveCmd := rRecycleValveCmd - 0.5;
END_IF;

rPID_PrevError := rError;

// Saturate Valve Command
IF rRecycleValveCmd > 100.0 THEN
    rRecycleValveCmd := 100.0;
ELSIF rRecycleValveCmd < 0.0 THEN
    rRecycleValveCmd := 0.0;
END_IF;

// VIGV Tuning for Capacity Control
// Simplified mapping, normally tied to a master pressure or flow controller
