VAR_INPUT
    PN_Cmd : "udtProfinetCmd";
    bLocalMode : BOOL;
    bLocalStart : BOOL;
    bLocalStop : BOOL;
    rSpeedSetpoint : REAL;
    rActualSpeed : REAL;
    rVibration : REAL;
    rBearingTemp : REAL;
    rLubePressure : REAL;
