\nFUNCTION_BLOCK FB_TurboexpanderControl
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; (* Enable system *)
    rInletPress : REAL; (* Inlet Pressure (bar) *)
    rInletTemp : REAL; (* Inlet Temperature (K) *)
    rOutletPress : REAL; (* Outlet Pressure (bar) *)
    rTargetSpeed : REAL; (* Target Rotor Speed (RPM) *)
    rActualSpeed : REAL; (* Actual Rotor Speed (RPM) *)
    rVibrationX : REAL; (* Shaft Vibration X-axis (um) *)
    rVibrationY : REAL; (* Shaft Vibration Y-axis (um) *)
    bAMB_Ready : BOOL; (* Active Magnetic Bearing Ready status *)
    rBearingTemp : REAL; (* Bearing Temperature (K) *)
END_VAR
VAR_OUTPUT
    rNozzleVanePos : REAL; (* Variable Nozzle Vane Position (%) 0-100 *)
    rJTValvePos : REAL; (* Joule-Thomson Valve Position (%) 0-100 *)
    bAMB_Enable : BOOL; (* Enable Active Magnetic Bearing Levitation *)
    bTripAlarm : BOOL; (* Critical Trip Alarm *)
    bWarningAlarm : BOOL; (* Warning Alarm *)
    iState : INT; (* State Machine Status *)
END_VAR
VAR
    rSpeedError : REAL;
    rKp_Speed : REAL := 0.5;
    rKi_Speed : REAL := 0.1;
    rSpeedIntegral : REAL := 0.0;
    rMaxSpeed : REAL := 95000.0; (* Max allowable RPM *)
    rMinTemp : REAL := 75.0; (* Minimum temperature limit in K *)
    rMaxVibration : REAL := 50.0; (* Max allowable vibration um *)
    tSurgeDelay : TON;
    tStartDelay : TON;
END_VAR

(* Main State Machine Implementation for Cryogenic Air Separation Turboexpander *)

IF NOT bEnable THEN
    iState := 0;
    rNozzleVanePos := 0.0;
    rJTValvePos := 100.0; (* Fail-safe open for JT *)
    bAMB_Enable := FALSE;
    bTripAlarm := FALSE;
    bWarningAlarm := FALSE;
    rSpeedIntegral := 0.0;
ELSE
    CASE iState OF
        0: (* INIT *)
            IF bAMB_Ready THEN
                bAMB_Enable := TRUE;
                tStartDelay(IN := TRUE, PT := T#5S);
                IF tStartDelay.Q THEN
                    iState := 10;
                    tStartDelay(IN := FALSE);
                END_IF
            ELSE
                bWarningAlarm := TRUE;
            END_IF;

        10: (* STANDBY & LEVITATION CONFIRMED *)
            IF bAMB_Ready AND rActualSpeed < 100.0 THEN
                iState := 20; (* Start sequence *)
                rJTValvePos := 50.0; (* Pre-cool bypass *)
            END_IF;

        20: (* RAMP UP & NOZZLE CONTROL *)
            IF rActualSpeed > rMaxSpeed THEN
                bTripAlarm := TRUE;
                iState := 99; (* TRIP *)
            END_IF;

            IF rVibrationX > rMaxVibration OR rVibrationY > rMaxVibration THEN
                bTripAlarm := TRUE;
                iState := 99;
            END_IF;

            (* Speed PI Controller *)
            rSpeedError := rTargetSpeed - rActualSpeed;
            rSpeedIntegral := rSpeedIntegral + (rSpeedError * 0.01); (* Assume 10ms cycle *)

            (* Anti-windup *)
            IF rSpeedIntegral > 100.0 THEN rSpeedIntegral := 100.0; END_IF;
            IF rSpeedIntegral < 0.0 THEN rSpeedIntegral := 0.0; END_IF;

            rNozzleVanePos := (rKp_Speed * rSpeedError) + (rKi_Speed * rSpeedIntegral);

            (* Limit Nozzle Vanes *)
            IF rNozzleVanePos > 100.0 THEN rNozzleVanePos := 100.0; END_IF;
            IF rNozzleVanePos < 0.0 THEN rNozzleVanePos := 0.0; END_IF;

            (* JT Valve Throttling for Temperature Control *)
            IF rInletTemp < rMinTemp THEN
                rJTValvePos := rJTValvePos + 1.0; (* Open bypass to reduce cooling *)
            ELSE
                rJTValvePos := rJTValvePos - 0.5;
            END_IF;

            (* Limit JT Valve *)
            IF rJTValvePos > 100.0 THEN rJTValvePos := 100.0; END_IF;
            IF rJTValvePos < 0.0 THEN rJTValvePos := 0.0; END_IF;

        99: (* FAULT / TRIP *)
            rNozzleVanePos := 0.0; (* Close vanes immediately *)
            rJTValvePos := 100.0; (* Open JT fully *)
            bAMB_Enable := FALSE; (* Drop rotor *)
    END_CASE;
END_IF;
\n``END_FUNCTION_BLOCK
