    rLateralG               : REAL; // Lateral acceleration in G
    rLongitudinalG          : REAL; // Longitudinal acceleration (negative = deceleration) in G
    rWheelSlip_pct          : REAL; // Average driven wheel slip percentage
    bBrakePedalActive       : BOOL; // Brake pedal status
    rBrakePressure_bar      : REAL; // Brake line pressure

    // Actuator Feedback (Hydraulic & Electro-mechanical)
    rWingActuatorPos_mm     : REAL; // Current position of rear wing hydraulic actuator
    rAirbrakeActuatorPos_mm : REAL; // Current position of airbrake hydraulic actuator
    rLeftVenturiPos_deg     : REAL; // Left underbody venturi flap angle
    rRightVenturiPos_deg    : REAL; // Right underbody venturi flap angle
    bHydraulicSysOk         : BOOL; // Hydraulic system pressure/temperature status

    // Driver Inputs
    bDRS_Button             : BOOL; // Driver manual DRS activation request
    bAeroTrackMode          : BOOL; // Track mode setting (aggressive aero profile)
END_VAR

VAR_OUTPUT
    // Control Signals to Actuators
    rCmdRearWingAoA_deg     : REAL; // Commanded Angle of Attack for Rear Wing (0.0 to 45.0)
    rCmdAirbrakeDeploy_pct  : REAL; // Commanded Airbrake Deployment (0.0 to 100.0)
    rCmdLeftVenturi_deg     : REAL; // Commanded Left Venturi Flap (0.0 to 25.0)
    rCmdRightVenturi_deg    : REAL; // Commanded Right Venturi Flap (0.0 to 25.0)

    // System Status
    bDRS_Active             : BOOL; // DRS currently engaged
    bAirbrake_Active        : BOOL; // Airbrake currently deployed
    xAeroSystemFault        : BOOL; // Critical aero system fault
    wErrorCode              : WORD; // Bitmask of specific errors
END_VAR

VAR
    // Internal State Machine
    eAeroState              : E_AeroState := E_AeroState.INIT;

    // Filters
    rFilteredLatG           : REAL;
    rFilteredLongG          : REAL;

    // Calculation Variables
    rCorneringLoad          : REAL;
    rSlipThreshold          : REAL := 12.5; // Max allowed slip % before aero compensation

    // Constants
    c_MaxWingAoA            : REAL := 45.0;
    c_MinWingAoA            : REAL := 2.0;
    c_DRSWingAoA            : REAL := 0.0;
    c_AirbrakeMinDecelG     : REAL := -0.8;
END_VAR

// ==============================================================================
// FILTERING SENSOR DATA
// ==============================================================================
// First-order low-pass filter to prevent actuator chatter
rFilteredLatG := rFilteredLatG + 0.15 * (rLateralG - rFilteredLatG);
rFilteredLongG := rFilteredLongG + 0.15 * (rLongitudinalG - rFilteredLongG);

// ==============================================================================
// FAULT MANAGEMENT & SAFETY INTERLOCKS
// ==============================================================================
IF NOT bHydraulicSysOk THEN
    xAeroSystemFault := TRUE;
    wErrorCode := wErrorCode OR 16#0001; // Hydraulic failure bit
    eAeroState := E_AeroState.FAULT_SAFE_MODE;
ELSE
    xAeroSystemFault := FALSE;
    wErrorCode := wErrorCode AND NOT 16#0001;
END_IF;

// ==============================================================================
// MAIN AERO STATE MACHINE
// ==============================================================================
CASE eAeroState OF
    E_AeroState.INIT:
        // Initialization and calibration sequence
        rCmdRearWingAoA_deg := c_MaxWingAoA; 
        rCmdAirbrakeDeploy_pct := 0.0;

        // Simulated readiness check
        IF (rWingActuatorPos_mm > 90.0) THEN 
            eAeroState := E_AeroState.NORMAL_DRIVE;
        END_IF;

    E_AeroState.NORMAL_DRIVE:
        // Dynamic Cornering Downforce Allocation
        // 1. Rear wing angle-of-attack adjustment based on steering angle and lateral G-force
        rCorneringLoad := ABS(rFilteredLatG) * 15.0 + ABS(rSteeringAngle_deg) * 0.25;

        // 2. Compensate for wheel slip by loading the rear axle
        IF rWheelSlip_pct > rSlipThreshold THEN
            rCorneringLoad := rCorneringLoad + (rWheelSlip_pct - rSlipThreshold) * 3.0;
        END_IF;

        // Assign base wing angle based on track mode or street mode
        IF bAeroTrackMode THEN
            rCmdRearWingAoA_deg := LIMIT(10.0, 15.0 + rCorneringLoad, c_MaxWingAoA);
        ELSE
            rCmdRearWingAoA_deg := LIMIT(c_MinWingAoA, 5.0 + rCorneringLoad, c_MaxWingAoA);
        END_IF;

        // 3. Underbody Venturi Flap Synchronization for Torque Vectoring Aero
        // Asymmetric underbody flow to induce yaw moment during cornering
        IF rSteeringAngle_deg > 15.0 AND rVehicleSpeed_kmh > 60.0 THEN
            // Right turn: open left venturi more to pull the outside chassis down
            rCmdLeftVenturi_deg  := LIMIT(5.0, ABS(rFilteredLatG) * 18.0, 25.0);
            rCmdRightVenturi_deg := 5.0; 
        ELSIF rSteeringAngle_deg < -15.0 AND rVehicleSpeed_kmh > 60.0 THEN
            // Left turn
            rCmdRightVenturi_deg := LIMIT(5.0, ABS(rFilteredLatG) * 18.0, 25.0);
            rCmdLeftVenturi_deg  := 5.0;
        ELSE
            rCmdLeftVenturi_deg  := 10.0;
            rCmdRightVenturi_deg := 10.0;
        END_IF;

        // Transition to Airbrake under heavy deceleration
        IF (rFilteredLongG < c_AirbrakeMinDecelG) AND bBrakePedalActive AND rVehicleSpeed_kmh > 100.0 THEN
            eAeroState := E_AeroState.AIRBRAKE_DEPLOYED;
        END_IF;

        // Transition to DRS
        IF bDRS_Button AND rVehicleSpeed_kmh > 120.0 AND ABS(rFilteredLatG) < 0.2 AND rWheelSlip_pct < 3.0 THEN
            eAeroState := E_AeroState.DRS_ACTIVE;
        END_IF;

    E_AeroState.DRS_ACTIVE:
        // Drag Reduction System (Low Drag Profile)
        bDRS_Active := TRUE;
        rCmdRearWingAoA_deg := c_DRSWingAoA;
        rCmdLeftVenturi_deg := 0.0; // Stall the diffuser for V-MAX
        rCmdRightVenturi_deg := 0.0;

        // Automatic Disengagement interlocks
        IF NOT bDRS_Button OR ABS(rFilteredLatG) > 0.4 OR bBrakePedalActive OR rWheelSlip_pct > 10.0 THEN
            bDRS_Active := FALSE;
            eAeroState := E_AeroState.NORMAL_DRIVE;
        END_IF;

    E_AeroState.AIRBRAKE_DEPLOYED:
        // Maximum Deceleration / Parachute Profile
        bAirbrake_Active := TRUE;

        // Pitch the rear wing to maximum drag position (Airbrake function)
        rCmdRearWingAoA_deg := c_MaxWingAoA;

        // Deploy hydraulic active airbrake panels
        rCmdAirbrakeDeploy_pct := LIMIT(0.0, ABS(rFilteredLongG) * 80.0, 100.0);

        // Open venturi flaps fully to shift aero balance rearward (stabilizes rear axle during heavy braking)
        rCmdLeftVenturi_deg := 25.0;
        rCmdRightVenturi_deg := 25.0;

        // Release airbrake when braking force subsides or low speed is reached
        IF NOT bBrakePedalActive OR rFilteredLongG > -0.3 OR rVehicleSpeed_kmh < 45.0 THEN
            bAirbrake_Active := FALSE;
            rCmdAirbrakeDeploy_pct := 0.0;
            eAeroState := E_AeroState.NORMAL_DRIVE;
        END_IF;

    E_AeroState.FAULT_SAFE_MODE:
        // Hydraulic or sensor failure. Return to mechanically safe high-downforce state
        bDRS_Active := FALSE;
        bAirbrake_Active := FALSE;
        rCmdRearWingAoA_deg := c_MaxWingAoA;
        rCmdAirbrakeDeploy_pct := 0.0;
        rCmdLeftVenturi_deg := 15.0;
        rCmdRightVenturi_deg := 15.0;

        IF bHydraulicSysOk THEN
            eAeroState := E_AeroState.INIT; // Attempt reset
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
