FUNCTION_BLOCK FB_MultiStage_RO_Control
TITLE = 'Multi-Stage RO Control with ERD'
VERSION : '1.0'

VAR_INPUT
    bStart_Sequence : BOOL; (* Initiate start sequence *)
    bStop_Sequence : BOOL; (* Initiate normal shutdown *)
    bEStop : BOOL; (* Emergency stop active low *)
    rInlet_Pressure : REAL; (* Raw water inlet pressure (bar) *)
    rInlet_Temp : REAL; (* Feed water temperature (C) *)
    rFeed_Flow : REAL; (* Main feed flow rate (m3/h) *)
    rHP_Discharge_Press : REAL; (* High pressure pump discharge (bar) *)
    rStage1_DP : REAL; (* Stage 1 Membrane Differential Pressure (bar) *)
    rStage2_DP : REAL; (* Stage 2 Membrane Differential Pressure (bar) *)
    rPermeate_Flow : REAL; (* Total permeate flow (m3/h) *)
    rPermeate_Cond : REAL; (* Permeate conductivity (uS/cm) *)
    rBrine_Flow : REAL; (* Reject brine flow (m3/h) *)
    rERD_Speed_Fbk : REAL; (* Energy Recovery Device speed (rpm) *)
    rERD_Boost_Press : REAL; (* ERD boost pressure (bar) *)
    rTank_Level : REAL; (* Permeate storage tank level (%) *)
END_VAR

VAR_OUTPUT
    bHP_Pump_Run : BOOL; (* High pressure pump start/stop *)
    rHP_Pump_SpeedRef : REAL; (* VFD Speed reference for HP pump (0-100%) *)
    bERD_Run : BOOL; (* ERD booster pump start/stop *)
    rERD_SpeedRef : REAL; (* ERD VFD Speed reference (0-100%) *)
    bFeed_Valve_Open : BOOL; (* Main feed valve control *)
    bBrine_Valve_Open : BOOL; (* Brine reject valve control *)
    bPermeate_Dump_Open : BOOL; (* Dump valve for high conductivity *)
    bAlarm_High_DP : BOOL; (* Membrane fouling alarm *)
    bAlarm_Low_Flow : BOOL; (* Loss of feed flow alarm *)
    bSystem_Ready : BOOL; (* System ready for start *)
    iState : INT; (* State machine status *)
END_VAR

VAR
    TMR_Start_Delay : TON;
    TMR_Stop_Delay : TON;
    TMR_Flush : TON;
    TMR_Alarm_Delay : TON;

    rPID_HP_Error : REAL;
    rPID_HP_Integral : REAL;
    rPID_HP_Kp : REAL := 2.5;
    rPID_HP_Ki : REAL := 0.5;
    rPID_HP_Setpoint : REAL := 65.0; (* bar *)

    rPID_ERD_Error : REAL;
    rPID_ERD_Integral : REAL;
    rPID_ERD_Kp : REAL := 1.2;
    rPID_ERD_Ki : REAL := 0.3;

    bInit : BOOL := FALSE;
    bFlushing : BOOL := FALSE;
END_VAR

(* Implementation *)
IF NOT bEStop THEN
    bHP_Pump_Run := FALSE;
    rHP_Pump_SpeedRef := 0.0;
    bERD_Run := FALSE;
    rERD_SpeedRef := 0.0;
    bFeed_Valve_Open := FALSE;
    bBrine_Valve_Open := TRUE; (* Fail open for safety *)
    bPermeate_Dump_Open := TRUE; (* Prevent bad water to tank *)
    iState := 99; (* Fault state *)
    RETURN;
END_IF;

IF NOT bInit THEN
    iState := 0;
    bInit := TRUE;
END_IF;

(* Membrane Differential Pressure Monitoring *)
IF (rStage1_DP > 4.5) OR (rStage2_DP > 4.5) THEN
    TMR_Alarm_Delay(IN := TRUE, PT := T#5S);
    IF TMR_Alarm_Delay.Q THEN
        bAlarm_High_DP := TRUE;
    END_IF;
ELSE
    TMR_Alarm_Delay(IN := FALSE);
    bAlarm_High_DP := FALSE;
END_IF;

IF rFeed_Flow < 10.0 THEN
    bAlarm_Low_Flow := TRUE;
ELSE
    bAlarm_Low_Flow := FALSE;
END_IF;

bSystem_Ready := (rInlet_Pressure > 2.0) AND (rTank_Level < 90.0) AND NOT bAlarm_High_DP AND NOT bAlarm_Low_Flow;

CASE iState OF
    0: (* Standby *)
        bHP_Pump_Run := FALSE;
        bERD_Run := FALSE;
        bFeed_Valve_Open := FALSE;
        bBrine_Valve_Open := FALSE;
        IF bStart_Sequence AND bSystem_Ready THEN
            iState := 10;
        END_IF;

    10: (* Pre-flush *)
        bFeed_Valve_Open := TRUE;
        bBrine_Valve_Open := TRUE;
        TMR_Flush(IN := TRUE, PT := T#30S);
        IF TMR_Flush.Q THEN
            TMR_Flush(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* Start ERD and Build Pressure *)
        bERD_Run := TRUE;
        rERD_SpeedRef := 20.0; (* Min speed *)
        TMR_Start_Delay(IN := TRUE, PT := T#10S);
        IF TMR_Start_Delay.Q THEN
            TMR_Start_Delay(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* Start HP Pump Ramp *)
        bHP_Pump_Run := TRUE;
        (* Basic PI Control for HP Pump Pressure *)
        rPID_HP_Error := rPID_HP_Setpoint - rHP_Discharge_Press;
        rPID_HP_Integral := rPID_HP_Integral + (rPID_HP_Error * 0.1); (* Assuming 100ms cycle *)

        (* Anti-windup *)
        IF rPID_HP_Integral > 100.0 THEN rPID_HP_Integral := 100.0; END_IF;
        IF rPID_HP_Integral < 0.0 THEN rPID_HP_Integral := 0.0; END_IF;

        rHP_Pump_SpeedRef := (rPID_HP_Error * rPID_HP_Kp) + rPID_HP_Integral;

        IF rHP_Pump_SpeedRef > 100.0 THEN rHP_Pump_SpeedRef := 100.0; END_IF;
        IF rHP_Pump_SpeedRef < 25.0 THEN rHP_Pump_SpeedRef := 25.0; END_IF;

        (* ERD Sync Logic based on Brine Flow and Pressure *)
        rPID_ERD_Error := (rHP_Discharge_Press - rStage1_DP - rStage2_DP) - rERD_Boost_Press;
        rPID_ERD_Integral := rPID_ERD_Integral + (rPID_ERD_Error * 0.1);
        rERD_SpeedRef := (rPID_ERD_Error * rPID_ERD_Kp) + rPID_ERD_Integral + 20.0; (* Feedforward base *)

        IF rERD_SpeedRef > 100.0 THEN rERD_SpeedRef := 100.0; END_IF;
        IF rERD_SpeedRef < 20.0 THEN rERD_SpeedRef := 20.0; END_IF;

        (* Permeate Quality Check *)
        IF rPermeate_Cond > 500.0 THEN
            bPermeate_Dump_Open := TRUE;
        ELSE
            bPermeate_Dump_Open := FALSE;
        END_IF;

        IF bStop_Sequence OR (rTank_Level >= 95.0) THEN
            iState := 40;
        END_IF;

    40: (* Shutdown Ramp Down *)
        rHP_Pump_SpeedRef := rHP_Pump_SpeedRef - 1.0;
        IF rHP_Pump_SpeedRef <= 25.0 THEN
            bHP_Pump_Run := FALSE;
            rHP_Pump_SpeedRef := 0.0;
            iState := 50;
        END_IF;

    50: (* Post-flush and Stop *)
        bERD_Run := FALSE;
        rERD_SpeedRef := 0.0;
        TMR_Stop_Delay(IN := TRUE, PT := T#30S);
        IF TMR_Stop_Delay.Q THEN
            TMR_Stop_Delay(IN := FALSE);
            bFeed_Valve_Open := FALSE;
            bBrine_Valve_Open := FALSE;
            iState := 0;
        END_IF;

    99: (* Fault recovery wait *)
        IF bEStop THEN
            iState := 0; (* Reset if EStop cleared *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
