FUNCTION_BLOCK FB_RotaryTabletPressControl
TITLE = 'Rotary Tablet Press Complex Control Strategy'
// Description: Advanced control for high-speed rotary tablet press including punch compression
// force monitoring, powder feeder dwell control, and high-speed pneumatic air-reject tracking.

VAR_INPUT
    bEnablePress           : BOOL;  // Main run enable
    rTargetSpeedRPM        : REAL;  // Desired turret speed (RPM)
    rMainCompressionSetPt  : REAL;  // Target main compression force (kN)
    rPreCompressionSetPt   : REAL;  // Target pre-compression force (kN)
    rCompressionTolerance  : REAL;  // Allowable force deviation (kN)
    diEncoderCount         : DINT;  // High-speed encoder feedback from turret (pulses)
    iTotalStations         : INT := 36; // Number of punch stations on turret
    rActualMainForce_1     : REAL;  // Analog input from main compression load cell 1 (kN)
    rActualPreForce_1      : REAL;  // Analog input from pre-compression load cell 1 (kN)
    bPowderLevelLow        : BOOL;  // Sensor input for powder hopper level
END_VAR

VAR_OUTPUT
    bTurretDriveRun        : BOOL;  // Command to turret VFD
    rTurretDriveSpeedRef   : REAL;  // Speed reference to turret VFD (0-100%)
    bPowderFeederRun       : BOOL;  // Command to paddle feeder motor
    rPowderFeederSpeedRef  : REAL;  // Speed reference to paddle feeder (0-100%)
    bAirRejectSolenoid     : BOOL;  // High-speed output for bad tablet reject
    bAlarmActive           : BOOL;  // General alarm flag
    iGoodTabletsCount      : DINT;  // Production counter (Good)
    iRejectTabletsCount    : DINT;  // Production counter (Reject)
END_VAR

VAR
    // Internal state variables
    State                  : INT := 0; 
    iCurrentStation        : INT;
    rMainForceDeviation    : REAL;
    rPreForceDeviation     : REAL;
    bRejectCurrentStation  : BOOL;

    // Shift registers for reject tracking
    // Assume 5 stations between main compression and reject chute
    arRejectTracking       : ARRAY[0..4] OF BOOL;
    i                      : INT;

    // PID parameters for feeder control (simplistic representation)
    rFeederKp              : REAL := 2.5;
    rFeederIntegral        : REAL := 0.0;

    // Edge detection
    diLastEncoderCount     : DINT;
    bStationTrigger        : BOOL;
END_VAR

// --- Station Trigger Logic based on Encoder ---
// A simplified station tracking based on fixed encoder pulses per station
IF (diEncoderCount - diLastEncoderCount) >= 1000 THEN // 1000 pulses per station
    bStationTrigger := TRUE;
    diLastEncoderCount := diEncoderCount;
    iCurrentStation := (iCurrentStation + 1) MOD iTotalStations;
ELSE
    bStationTrigger := FALSE;
END_IF;

// --- State Machine ---
CASE State OF
    0: // STOPPED
        bTurretDriveRun := FALSE;
        rTurretDriveSpeedRef := 0.0;
        bPowderFeederRun := FALSE;
        bAirRejectSolenoid := FALSE;
        IF bEnablePress AND NOT bAlarmActive THEN
            State := 10;
        END_IF;

    10: // STARTUP & RAMPING
        bTurretDriveRun := TRUE;
        bPowderFeederRun := TRUE;
        rTurretDriveSpeedRef := rTargetSpeedRPM * 0.1; // Slow ramp
        IF rActualMainForce_1 > 0.0 THEN // Start building force
            State := 20;
        END_IF;
        IF NOT bEnablePress THEN State := 0; END_IF;

    20: // RUNNING PRODUCTION
        rTurretDriveSpeedRef := rTargetSpeedRPM;

        // Dwell Algorithm / Feeder Control based on speed
        // To maintain consistent fill depth, paddle speed must match turret speed dynamically
        rFeederIntegral := rFeederIntegral + (rTargetSpeedRPM - rTurretDriveSpeedRef) * 0.01;
        rPowderFeederSpeedRef := (rTargetSpeedRPM * 0.8) + rFeederIntegral;

        IF bPowderLevelLow THEN
            bAlarmActive := TRUE;
            State := 99; // Fault
        END_IF;

        IF NOT bEnablePress THEN State := 0; END_IF;

    99: // FAULT
        bTurretDriveRun := FALSE;
        bPowderFeederRun := FALSE;
        IF NOT bAlarmActive THEN
            State := 0;
        END_IF;
END_CASE;

// --- Compression Force Monitoring & Reject Tracking ---
IF bStationTrigger AND (State = 20) THEN

    // Evaluate forces for the current station being compressed
    rMainForceDeviation := ABS(rActualMainForce_1 - rMainCompressionSetPt);
    rPreForceDeviation := ABS(rActualPreForce_1 - rPreCompressionSetPt);

    IF (rMainForceDeviation > rCompressionTolerance) OR (rPreForceDeviation > (rCompressionTolerance * 0.5)) THEN
        bRejectCurrentStation := TRUE;
    ELSE
        bRejectCurrentStation := FALSE;
    END_IF;

    // Shift Register for reject tracking (moves tablet from compression to reject station)
    // Shift old values down
    FOR i := 4 TO 1 BY -1 DO
        arRejectTracking[i] := arRejectTracking[i-1];
    END_FOR;

    // Enter new tablet status
    arRejectTracking[0] := bRejectCurrentStation;

    // Trigger Air Reject Solenoid for the tablet at the chute (index 4)
    IF arRejectTracking[4] THEN
        bAirRejectSolenoid := TRUE;
        iRejectTabletsCount := iRejectTabletsCount + 1;
    ELSE
        bAirRejectSolenoid := FALSE;
        iGoodTabletsCount := iGoodTabletsCount + 1;
    END_IF;

END_IF;

// Turn off reject solenoid after a short duration (simplified, normally timer-based)
IF NOT bStationTrigger AND NOT (State = 20) THEN
    bAirRejectSolenoid := FALSE;
END_IF;

END_FUNCTION_BLOCK
