FUNCTION_BLOCK FB_ExoGaitController
TITLE = 'Dynamic Gait Assist and Fall Prevention Controller'
VERSION : '1.0'

(* 
   Advanced Robotic Exoskeleton Rehabilitation Controller
   - Surface EMG myoelectric signal processing
   - Dynamic gait assist torque calculation
   - Fall prevention & balance recovery
*)

VAR_INPUT
    bSystemEnable : BOOL; // System master enable
    rEMG_Quad_Left_Raw : REAL; // Raw sEMG signal Left Quadriceps (mV)
    rEMG_Ham_Left_Raw : REAL; // Raw sEMG signal Left Hamstrings (mV)
    rEMG_Quad_Right_Raw : REAL; // Raw sEMG signal Right Quadriceps (mV)
    rEMG_Ham_Right_Raw : REAL; // Raw sEMG signal Right Hamstrings (mV)
    rInertial_Pitch : REAL; // Torso pitch angle from IMU (rad)
    rInertial_Roll : REAL; // Torso roll angle from IMU (rad)
    rJointAngle_Hip_Left : REAL; // Left Hip Joint Angle (rad)
    rJointAngle_Knee_Left : REAL; // Left Knee Joint Angle (rad)
    rJointAngle_Hip_Right : REAL; // Right Hip Joint Angle (rad)
    rJointAngle_Knee_Right : REAL; // Right Knee Joint Angle (rad)
    rGroundContact_Left : REAL; // Left foot pressure sensor (N)
    rGroundContact_Right : REAL; // Right foot pressure sensor (N)
END_VAR

VAR_OUTPUT
    rTorqueCmd_Hip_Left : REAL; // Torque command for left hip motor (Nm)
    rTorqueCmd_Knee_Left : REAL; // Torque command for left knee motor (Nm)
    rTorqueCmd_Hip_Right : REAL; // Torque command for right hip motor (Nm)
    rTorqueCmd_Knee_Right : REAL; // Torque command for right knee motor (Nm)
    bFallImminent : BOOL; // Fall detection alert
    eSystemState : INT; // 0=IDLE, 1=CALIBRATING, 2=ASSISTING, 3=RECOVERY, 4=FAULT
END_VAR

VAR
    // Signal Processing Variables
    rEMG_Quad_Left_Filt : REAL;
    rEMG_Ham_Left_Filt : REAL;
    rEMG_Quad_Right_Filt : REAL;
    rEMG_Ham_Right_Filt : REAL;
    rAlpha_EMG : REAL := 0.15; // Low-pass filter coefficient

    // Thresholds
    rContactThresh : REAL := 150.0; // Newton
    rFallPitchThresh : REAL := 0.523; // ~30 degrees
    rFallRollThresh : REAL := 0.436; // ~25 degrees

    // Gait Phase Variables
    bStance_Left : BOOL;
    bStance_Right : BOOL;
    rPhase_Left : REAL; // 0 to 1
    rPhase_Right : REAL; // 0 to 1

    // Assist Gains
    rGain_Quad : REAL := 2.5; // Torque per mV of EMG
    rGain_Ham : REAL := 2.0; // Torque per mV of EMG

    // Internal state
    tStateTimer : TIME;
    rLastPitch : REAL;
    rPitchRate : REAL;
END_VAR

// --- IMPLEMENTATION ---
IF NOT bSystemEnable THEN
    rTorqueCmd_Hip_Left := 0.0;
    rTorqueCmd_Knee_Left := 0.0;
    rTorqueCmd_Hip_Right := 0.0;
    rTorqueCmd_Knee_Right := 0.0;
    bFallImminent := FALSE;
    eSystemState := 0;
    RETURN;
END_IF;

// 1. sEMG Signal Processing (Exponential Moving Average Filter)
rEMG_Quad_Left_Filt := rAlpha_EMG * rEMG_Quad_Left_Raw + (1.0 - rAlpha_EMG) * rEMG_Quad_Left_Filt;
rEMG_Ham_Left_Filt := rAlpha_EMG * rEMG_Ham_Left_Raw + (1.0 - rAlpha_EMG) * rEMG_Ham_Left_Filt;
rEMG_Quad_Right_Filt := rAlpha_EMG * rEMG_Quad_Right_Raw + (1.0 - rAlpha_EMG) * rEMG_Quad_Right_Filt;
rEMG_Ham_Right_Filt := rAlpha_EMG * rEMG_Ham_Right_Raw + (1.0 - rAlpha_EMG) * rEMG_Ham_Right_Filt;

// 2. Gait Phase Detection
bStance_Left := (rGroundContact_Left > rContactThresh);
bStance_Right := (rGroundContact_Right > rContactThresh);

// 3. Fall Detection and Balance Recovery
rPitchRate := rInertial_Pitch - rLastPitch;
rLastPitch := rInertial_Pitch;

IF (ABS(rInertial_Pitch) > rFallPitchThresh) OR (ABS(rInertial_Roll) > rFallRollThresh) OR (ABS(rPitchRate) > 0.2) THEN
    bFallImminent := TRUE;
    eSystemState := 3; // RECOVERY
ELSE
    bFallImminent := FALSE;
    eSystemState := 2; // ASSISTING
END_IF;

// 4. Dynamic Torque Calculation
IF eSystemState = 2 THEN
    // Normal assist mode based on myoelectric control

    // Left Leg
    IF bStance_Left THEN
        // Stance phase: provide extension torque to support weight
        rTorqueCmd_Knee_Left := rGain_Quad * rEMG_Quad_Left_Filt;
        rTorqueCmd_Hip_Left := rGain_Ham * rEMG_Ham_Left_Filt * 0.8; 
    ELSE
        // Swing phase: flex hip and knee to clear ground
        rTorqueCmd_Knee_Left := -rGain_Ham * rEMG_Ham_Left_Filt * 0.5;
        rTorqueCmd_Hip_Left := rGain_Quad * rEMG_Quad_Left_Filt * 1.2;
    END_IF;

    // Right Leg
    IF bStance_Right THEN
        rTorqueCmd_Knee_Right := rGain_Quad * rEMG_Quad_Right_Filt;
        rTorqueCmd_Hip_Right := rGain_Ham * rEMG_Ham_Right_Filt * 0.8;
    ELSE
        rTorqueCmd_Knee_Right := -rGain_Ham * rEMG_Ham_Right_Filt * 0.5;
        rTorqueCmd_Hip_Right := rGain_Quad * rEMG_Quad_Right_Filt * 1.2;
    END_IF;

ELSIF eSystemState = 3 THEN
    // Recovery mode: lock joints or step out
    // Simple recovery strategy: lock knees, thrust hips to counter fall direction
    IF rInertial_Pitch > 0.0 THEN
        // Falling forward
        rTorqueCmd_Hip_Left := -20.0;
        rTorqueCmd_Hip_Right := -20.0;
    ELSE
        // Falling backward
        rTorqueCmd_Hip_Left := 20.0;
        rTorqueCmd_Hip_Right := 20.0;
    END_IF;
    rTorqueCmd_Knee_Left := 30.0; // Max extension torque to brace
    rTorqueCmd_Knee_Right := 30.0;
END_IF;

// Saturation to prevent injury
IF rTorqueCmd_Knee_Left > 50.0 THEN rTorqueCmd_Knee_Left := 50.0; END_IF;
IF rTorqueCmd_Knee_Left < -50.0 THEN rTorqueCmd_Knee_Left := -50.0; END_IF;
IF rTorqueCmd_Hip_Left > 60.0 THEN rTorqueCmd_Hip_Left := 60.0; END_IF;
IF rTorqueCmd_Hip_Left < -60.0 THEN rTorqueCmd_Hip_Left := -60.0; END_IF;

IF rTorqueCmd_Knee_Right > 50.0 THEN rTorqueCmd_Knee_Right := 50.0; END_IF;
IF rTorqueCmd_Knee_Right < -50.0 THEN rTorqueCmd_Knee_Right := -50.0; END_IF;
IF rTorqueCmd_Hip_Right > 60.0 THEN rTorqueCmd_Hip_Right := 60.0; END_IF;
IF rTorqueCmd_Hip_Right < -60.0 THEN rTorqueCmd_Hip_Right := -60.0; END_IF;

END_FUNCTION_BLOCK
```

