FUNCTION_BLOCK FB_IsobaricBottleFiller
VAR_INPUT
    bEnable : BOOL; (* Enable the filler operation *)
    bBottlePresent : BOOL; (* Proximity sensor for bottle presence *)
    rBottlePressure : REAL; (* Actual pressure inside the bottle in bar *)
    rTargetPressure : REAL; (* Target CO2 counter-pressure in bar *)
    rFillLevel : REAL; (* Actual fill level from capacitive sensor *)
    rTargetLevel : REAL; (* Target fill level *)
    rBeerTemp : REAL; (* Beer temperature in Celsius *)
    bCrownerReady : BOOL; (* Crowner turret ready signal *)
    rServoPos : LREAL; (* Crowner servo actual position *)
    bEstop : BOOL; (* Emergency stop *)
END_VAR

VAR_OUTPUT
    bPurgeValveCO2 : BOOL; (* Valve to purge air with CO2 *)
    bSniftValve : BOOL; (* Valve to relieve pressure after filling *)
    bLiquidValve : BOOL; (* Beer fill valve *)
    bHPIValve : BOOL; (* High Pressure Injection (HPI) water jet to knock off DO *)
    bCrownerEngage : BOOL; (* Engage crowner mechanism *)
    rServoVelocityCmd : LREAL; (* Velocity command to crowner servo *)
    iState : INT; (* Current state of the filling machine *)
    bFault : BOOL; (* Fault indication *)
    sFaultMsg : STRING; (* Fault description *)
    bWarning : BOOL; (* Warning indication *)
END_VAR

VAR
    TmrPurge : TON;
    TmrSettle : TON;
    TmrHPI : TON;
    TmrSnift : TON;
    TmrTimeout : TON;

    rPressureDeadband : REAL := 0.05;
    rLevelDeadband : REAL := 1.0;

    eFillerState : INT := 0; 
    (* 0:INIT, 1:WAIT_BOTTLE, 2:CO2_PURGE, 3:PRESSURIZE, 4:FILLING, 5:SETTLING, 6:HPI_JET, 7:SNIFTING, 8:CROWNING, 9:DONE, 99:FAULT_STATE *)
END_VAR

(* Implementation *)
IF NOT bEnable OR bEstop THEN
    eFillerState := 0;
    bPurgeValveCO2 := FALSE;
    bSniftValve := FALSE;
    bLiquidValve := FALSE;
    bHPIValve := FALSE;
    bCrownerEngage := FALSE;
    rServoVelocityCmd := 0.0;
    bFault := bEstop;
    IF bEstop THEN
        sFaultMsg := 'Emergency Stop Active';
    ELSE
        sFaultMsg := '';
    END_IF;
    RETURN;
END_IF;

CASE eFillerState OF
    0: (* INIT *)
        bPurgeValveCO2 := FALSE;
        bSniftValve := FALSE;
        bLiquidValve := FALSE;
        bHPIValve := FALSE;
        bCrownerEngage := FALSE;
        rServoVelocityCmd := 0.0;
        iState := 0;
        IF bEnable AND NOT bFault THEN
            eFillerState := 1; (* WAIT_BOTTLE *)
        END_IF;

    1: (* WAIT_BOTTLE *)
        iState := 1;
        IF bBottlePresent THEN
            eFillerState := 2; (* CO2_PURGE *)
            TmrPurge(IN := FALSE);
        END_IF;

    2: (* CO2_PURGE *)
        iState := 2;
        bPurgeValveCO2 := TRUE;
        bSniftValve := TRUE; (* Open snift to allow air out while CO2 goes in *)
        TmrPurge(IN := TRUE, PT := T#500MS);
        IF TmrPurge.Q THEN
            bSniftValve := FALSE;
            eFillerState := 3; (* PRESSURIZE *)
            TmrTimeout(IN := FALSE);
        END_IF;

    3: (* PRESSURIZE *)
        iState := 3;
        TmrTimeout(IN := TRUE, PT := T#3S);
        IF rBottlePressure >= (rTargetPressure - rPressureDeadband) THEN
            bPurgeValveCO2 := FALSE;
            eFillerState := 4; (* FILLING *)
            TmrTimeout(IN := FALSE);
        ELSIF TmrTimeout.Q THEN
            eFillerState := 99; (* FAULT_STATE *)
            sFaultMsg := 'Timeout during pressurization. Check bottle seal.';
        END_IF;

    4: (* FILLING *)
        iState := 4;
        bLiquidValve := TRUE;
        IF rFillLevel >= (rTargetLevel - rLevelDeadband) THEN
            bLiquidValve := FALSE;
            eFillerState := 5; (* SETTLING *)
            TmrSettle(IN := FALSE);
        END_IF;

    5: (* SETTLING *)
        iState := 5;
        TmrSettle(IN := TRUE, PT := T#1S500MS);
        IF TmrSettle.Q THEN
            eFillerState := 6; (* HPI_JET *)
            TmrHPI(IN := FALSE);
        END_IF;

    6: (* HPI_JET *)
        iState := 6;
        (* High pressure jetting to cause foaming, removing O2 from neck *)
        bHPIValve := TRUE;
        TmrHPI(IN := TRUE, PT := T#100MS);
        IF TmrHPI.Q THEN
            bHPIValve := FALSE;
            eFillerState := 7; (* SNIFTING *)
            TmrSnift(IN := FALSE);
        END_IF;

    7: (* SNIFTING *)
        iState := 7;
        bSniftValve := TRUE; (* Release pressure slowly to prevent gushing *)
        TmrSnift(IN := TRUE, PT := T#800MS);
        IF TmrSnift.Q AND rBottlePressure < 0.2 THEN
            bSniftValve := FALSE;
            IF bCrownerReady THEN
                eFillerState := 8; (* CROWNING *)
            ELSE
                eFillerState := 99; (* FAULT_STATE *)
                sFaultMsg := 'Crowner not ready.';
            END_IF;
        END_IF;

    8: (* CROWNING *)
        iState := 8;
        bCrownerEngage := TRUE;
        (* Basic servo cam profile based on position *)
        IF rServoPos >= 0.0 AND rServoPos < 180.0 THEN
            rServoVelocityCmd := 500.0; (* Fast approach *)
        ELSIF rServoPos >= 180.0 AND rServoPos < 300.0 THEN
            rServoVelocityCmd := 100.0; (* Slow pressing *)
        ELSE
            rServoVelocityCmd := 800.0; (* Fast return *)
        END_IF;

        IF rServoPos >= 350.0 THEN
            bCrownerEngage := FALSE;
            rServoVelocityCmd := 0.0;
            eFillerState := 9; (* DONE *)
        END_IF;

    9: (* DONE *)
        iState := 9;
        IF NOT bBottlePresent THEN
            eFillerState := 1; (* WAIT_BOTTLE *)
        END_IF;

    99: (* FAULT_STATE *)
        iState := 99;
        bFault := TRUE;
        bPurgeValveCO2 := FALSE;
        bSniftValve := FALSE;
        bLiquidValve := FALSE;
        bHPIValve := FALSE;
        bCrownerEngage := FALSE;
        rServoVelocityCmd := 0.0;

END_CASE;

(* Call timers unconditionally *)
TmrPurge();
TmrSettle();
TmrHPI();
TmrSnift();
TmrTimeout();

END_FUNCTION_BLOCK
