FUNCTION_BLOCK FB_LH2_ClaudeCycle_Liquefaction
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety instrumented system OK signal *)
    rFeedH2_Pressure        : REAL;     (* H2 feed pressure in bar(a) *)
    rFeedH2_Temp            : REAL;     (* H2 feed temperature in Kelvin *)
    rVacuumJacket_Press     : REAL;     (* Vacuum jacket pressure for leak detection in mbar *)
    bCompInterlockOK        : BOOL;     (* Compressor system interlocks cleared *)
    rOrthoParaRatio         : REAL;     (* Current ortho-to-para conversion ratio (0.0 - 1.0) *)
    rExpanderSpeed          : REAL;     (* Turboexpander RPM *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Claude cycle ready for start sequence *)
    rJT_ValveCmd            : REAL;     (* Joule-Thomson expansion valve command (0-100%) *)
    rCatalystHeaterCmd      : REAL;     (* Ortho-to-para conversion catalyst heater control (0-100%) *)
    bExpanderTrip           : BOOL;     (* Turboexpander trip command *)
    bVacuumLeakAlarm        : BOOL;     (* Vacuum jacket integrity lost alarm *)
    bProcessInterlock       : BOOL;     (* Process interlock active *)
END_VAR

VAR
    iState                  : INT := 0; 
    tStartupDelay           : TON;
    tStabilizationTimer     : TON;
    rEnthalpyEstimate       : REAL;     (* Internal enthalpy tracking *)
    rCooldownRate           : REAL := 0.0;
    rPrevTemp               : REAL := 0.0;
    rDerivativeTemp         : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Stop Evaluation *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bExpanderTrip := TRUE;
    rJT_ValveCmd := 0.0;
    rCatalystHeaterCmd := 0.0;
    bProcessInterlock := TRUE;
    iState := 999; (* FAILSAFE STATE *)
    RETURN;
END_IF;

(* Continuous Vacuum Jacket Integrity Monitoring *)
IF rVacuumJacket_Press > 1.0E-3 THEN
    bVacuumLeakAlarm := TRUE;
    bProcessInterlock := TRUE;
ELSE
    bVacuumLeakAlarm := FALSE;
END_IF;

(* Claude Cycle State Machine *)
CASE iState OF
    0: (* IDLE & PRE-START CHECKS *)
        bSystemReady := FALSE;
        rJT_ValveCmd := 0.0;
        rCatalystHeaterCmd := 0.0;
        bExpanderTrip := FALSE;

        IF bEnable AND bCompInterlockOK AND NOT bVacuumLeakAlarm THEN
            iState := 10;
        END_IF;

    10: (* PURGE & COOLDOWN INITIATION *)
        tStartupDelay(IN := TRUE, PT := T#30S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* TURBOEXPANDER ACCELERATION *)
        (* Target 120,000 RPM on primary expander train *)
        IF rExpanderSpeed > 115000.0 AND rExpanderSpeed < 125000.0 THEN
            iState := 30;
        ELSIF rExpanderSpeed > 130000.0 THEN
            bExpanderTrip := TRUE;
            iState := 999;
        END_IF;

    30: (* JOULE-THOMSON PRE-COOLING *)
        (* Throttling algorithm for isenthalpic expansion *)
        IF rFeedH2_Temp > 80.0 THEN
            rJT_ValveCmd := 25.0;
        ELSIF rFeedH2_Temp > 40.0 THEN
            rJT_ValveCmd := 45.0;
        ELSE
            iState := 40;
        END_IF;

    40: (* ORTHO-TO-PARA CONVERSION OPTIMIZATION *)
        (* Target > 95% para-hydrogen for storage stability *)
        IF rOrthoParaRatio < 0.95 THEN
            rCatalystHeaterCmd := (0.95 - rOrthoParaRatio) * 100.0;
            (* Clamp command to 100% *)
            IF rCatalystHeaterCmd > 100.0 THEN
                rCatalystHeaterCmd := 100.0;
            END_IF;
        ELSE
            rCatalystHeaterCmd := 0.0;
            iState := 50;
        END_IF;

    50: (* STEADY-STATE LIQUEFACTION *)
        bSystemReady := TRUE;
        tStabilizationTimer(IN := TRUE, PT := T#5M);

        (* Advanced temperature derivative control *)
        rDerivativeTemp := rFeedH2_Temp - rPrevTemp;
        rPrevTemp := rFeedH2_Temp;

        IF rFeedH2_Temp <= 20.28 THEN (* LH2 boiling point at 1 atm *)
            rJT_ValveCmd := 75.0 + (rDerivativeTemp * -5.0); 
        ELSE
            rJT_ValveCmd := 100.0; 
        END_IF;

        (* Check disable condition *)
        IF NOT bEnable THEN
            tStabilizationTimer(IN := FALSE);
            iState := 60;
        END_IF;

    60: (* CONTROLLED SHUTDOWN *)
        rJT_ValveCmd := rJT_ValveCmd * 0.95; (* Ramp down valve *)
        rCatalystHeaterCmd := 0.0;
        bSystemReady := FALSE;
        IF rJT_ValveCmd < 1.0 THEN
            rJT_ValveCmd := 0.0;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rJT_ValveCmd := 0.0;
        rCatalystHeaterCmd := 0.0;
        (* Requires manual reset via transition of bEnable after fault cleared *)
        IF NOT bEnable AND NOT bVacuumLeakAlarm AND bCompInterlockOK THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

