FUNCTION_BLOCK FB_ContinuousMiner_Secure
TITLE = 'Continuous Miner with IEC 62443 and SCADA'
VERSION : '1.3'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    rShearerTargetElevation : REAL;
    rConveyorTargetSpeed : REAL;
    rShearerActualElevation : REAL;
    rConveyorActualSpeed : REAL;
    rHydraulicPressure : REAL;
    bProfinetOK : BOOL;

    // Cybersecurity (IEC 62443)
    dwAuthToken : DWORD; // Token from HMI/SCADA
    bSecureModeReq : BOOL; // Request secure operational mode

    // Redundancy
    bPrimaryPLC_Active : BOOL; // Heartbeat from primary
    bIsSecondary : BOOL; // Is this the secondary PLC?
END_VAR

VAR_OUTPUT
    rShearerLiftCmd : REAL;
    rConveyorSpeedCmd : REAL;
    bSystemRunning : BOOL;
    iErrorCode : INT;
    stSCADA : UDT_SCADA_Data; // Structured data for SCADA
END_VAR

VAR
    bActive : BOOL := FALSE;
    bSecureMode : BOOL := FALSE;
    bFailoverActive : BOOL := FALSE;
    rMaxSafePressure : REAL := 250.0;
    dwValidToken : DWORD := 16#A1B2C3D4; // Hardcoded valid token example
END_VAR

BEGIN
    // Cybersecurity check
    IF bSecureModeReq AND (dwAuthToken = dwValidToken) THEN
        bSecureMode := TRUE;
    ELSE
        bSecureMode := FALSE;
    END_IF;

    // Failover handling
    IF bIsSecondary AND NOT bPrimaryPLC_Active THEN
        bFailoverActive := TRUE;
    ELSE
        bFailoverActive := FALSE;
    END_IF;

    // System only runs if it's the active primary, or a failover secondary
    IF NOT bIsSecondary OR bFailoverActive THEN
        // Diagnostics
        IF NOT bProfinetOK THEN
            iErrorCode := 1001; 
            bActive := FALSE;
        ELSIF rHydraulicPressure > rMaxSafePressure THEN
            iErrorCode := 2001; 
            bActive := FALSE;
        ELSIF NOT bSecureMode THEN
            iErrorCode := 4001; // Security token invalid or mode not requested
            bActive := FALSE;
        ELSE
            iErrorCode := 0; 
        END_IF;

        // Start/Stop Logic
        IF iErrorCode = 0 THEN
            IF bStart AND NOT bStop THEN
                bActive := TRUE;
            ELSIF bStop THEN
                bActive := FALSE;
            END_IF;
        END_IF;

        bSystemRunning := bActive;

        IF bActive THEN
            rShearerLiftCmd := (rShearerTargetElevation - rShearerActualElevation) * 0.5;
            IF rShearerLiftCmd > 100.0 THEN rShearerLiftCmd := 100.0; END_IF;
            IF rShearerLiftCmd < -100.0 THEN rShearerLiftCmd := -100.0; END_IF;

            rConveyorSpeedCmd := rConveyorTargetSpeed;
        ELSE
            rShearerLiftCmd := 0.0;
            rConveyorSpeedCmd := 0.0;
        END_IF;
    ELSE
        // Standby mode
        bSystemRunning := FALSE;
        rShearerLiftCmd := 0.0;
        rConveyorSpeedCmd := 0.0;
        iErrorCode := 9999; // Standby
    END_IF;

    // SCADA Integration Mapping
    stSCADA.bRunning := bSystemRunning;
    stSCADA.iErrorCode := iErrorCode;
    stSCADA.rActualElevation := rShearerActualElevation;
    stSCADA.rActualSpeed := rConveyorActualSpeed;
    stSCADA.rHydraulicPressure := rHydraulicPressure;
    stSCADA.bSecureModeActive := bSecureMode;

END_FUNCTION_BLOCK
