FUNCTION_BLOCK "Distillation_Control_Secure_Redundant"
VERSION : 0.1
VAR_INPUT
    Feed_Flow_PV : REAL;
    Bottom_Temp_PV : REAL;
    SCADA_Heartbeat_In : BOOL;
    Active_User_Role : INT; // 1=Operator, 2=Engineer, 3=Admin
    Req_Bottom_Temp_SP : REAL;
