FUNCTION_BLOCK FB_TabletPressControl
VAR_INPUT
    bEnable                 : BOOL; // Enable the tablet press
    bEmergencyStop          : BOOL; // E-Stop
    rMainCompressionSP      : REAL; // Setpoint for main compression force (kN)
    rPreCompressionSP       : REAL; // Setpoint for pre-compression force (kN)
    rTargetTabletWeight     : REAL; // Target weight in mg
    rWeightTolerance        : REAL; // Allowed weight variation in mg
    rTurretSpeedSP          : REAL; // Target speed in RPM
    rActualMainCompression  : REAL; // Actual measured main compression force (kN)
    rActualPreCompression   : REAL; // Actual measured pre-compression force (kN)
    rActualTurretSpeed      : REAL; // Actual turret speed (RPM)
    rIndividualTabletWeight : REAL; // Measured weight from sampling station (mg)
    bLubeLowLevel           : BOOL; // Lubrication tank low level switch
END_VAR
VAR_OUTPUT
    bRunning                : BOOL; // Press is running
    bFault                  : BOOL; // Fault active
    iFaultCode              : INT;  // Specific fault code
    rTurretSpeedOut         : REAL; // Speed command to VFD
    rFillDepthCommand       : REAL; // Command to fill cam servomotor
    bEjectTabletOut         : BOOL; // Command to pneumatic reject gate
    bLubePumpOn             : BOOL; // Command to punch lubrication pump
    rActualYield            : REAL; // Good tablets per minute
END_VAR
VAR
    rFillDepthPos           : REAL := 10.0; // Initial fill depth (mm)
    rWeightError            : REAL;
    rIntegralTerm           : REAL := 0.0;
    rKp                     : REAL := 0.05; // Proportional gain for weight control
    rKi                     : REAL := 0.01; // Integral gain for weight control
    bLubeCycleActive        : BOOL;
    tLubeTimer              : TON;
    tLubeInterval           : TON;
    rCompressionError       : REAL;
    uiGoodCount             : UDINT;
    uiRejectCount           : UDINT;
    tYieldCalcTimer         : TON;
END_VAR

// Reset outputs on E-Stop or not enabled
IF bEmergencyStop OR NOT bEnable THEN
    bRunning := FALSE;
    rTurretSpeedOut := 0.0;
    bEjectTabletOut := FALSE;
    bLubePumpOn := FALSE;
    IF bEmergencyStop THEN
        bFault := TRUE;
        iFaultCode := 999;
    END_IF;
    RETURN;
END_IF;

bRunning := TRUE;
bFault := FALSE;
iFaultCode := 0;

// Turret Speed Control (Simple Ramp-up could be implemented here, passing SP for now)
IF rTurretSpeedSP > 120.0 THEN
    rTurretSpeedOut := 120.0; // Max speed limit
ELSE
    rTurretSpeedOut := rTurretSpeedSP;
END_IF;

// Tablet Weight Control - Closed Loop using Fill Depth Cam
// Weight relates directly to fill volume (depth).
rWeightError := rTargetTabletWeight - rIndividualTabletWeight;
rIntegralTerm := rIntegralTerm + (rWeightError * rKi);

// Anti-windup for integral term
IF rIntegralTerm > 5.0 THEN
    rIntegralTerm := 5.0;
ELSIF rIntegralTerm < -5.0 THEN
    rIntegralTerm := -5.0;
END_IF;

rFillDepthPos := rFillDepthPos + (rWeightError * rKp) + rIntegralTerm;

// Limit fill depth to physical machine limits
IF rFillDepthPos > 20.0 THEN
    rFillDepthPos := 20.0;
ELSIF rFillDepthPos < 2.0 THEN
    rFillDepthPos := 2.0;
END_IF;
rFillDepthCommand := rFillDepthPos;

// Main Compression Force Monitoring & Rejection Tracking
// If compression force is outside tolerance, it usually means bad weight or density
rCompressionError := ABS(rActualMainCompression - rMainCompressionSP);
IF rCompressionError > 5.0 OR ABS(rWeightError) > rWeightTolerance THEN
    bEjectTabletOut := TRUE;
    uiRejectCount := uiRejectCount + 1;
ELSE
    bEjectTabletOut := FALSE;
    uiGoodCount := uiGoodCount + 1;
END_IF;

// Punch Lubrication Logic
// Run lube pump for 2 seconds every 60 seconds
tLubeInterval(IN := bRunning AND NOT bLubeCycleActive, PT := T#60S);
IF tLubeInterval.Q THEN
    bLubeCycleActive := TRUE;
END_IF;

tLubeTimer(IN := bLubeCycleActive, PT := T#2S);
IF tLubeTimer.Q THEN
    bLubeCycleActive := FALSE;
END_IF;

IF bLubeLowLevel THEN
    bFault := TRUE;
    iFaultCode := 101; // Lube Low Fault
    bLubePumpOn := FALSE;
ELSE
    bLubePumpOn := bLubeCycleActive;
END_IF;

// Yield Calculation (Tablets per minute)
tYieldCalcTimer(IN := TRUE, PT := T#60S);
IF tYieldCalcTimer.Q THEN
    rActualYield := UDINT_TO_REAL(uiGoodCount);
    uiGoodCount := 0; // Reset for next minute
    uiRejectCount := 0;
    tYieldCalcTimer(IN := FALSE); // Reset timer
END_IF;

END_FUNCTION_BLOCK
