FUNCTION_BLOCK FB_Synchrotron_Control
TITLE = 'Synchrotron Main Ring Control System'
VERSION : '2.5'

VAR_INPUT
    rBeamCurrent_mA : REAL; (* Measured beam current from current transformer *)
    rRFCavityPhase_deg : REAL; (* Current phase of RF cavity *)
    rTargetBeamEnergy_GeV : REAL; (* Desired beam energy *)
    rQuadrupoleField_T : REAL; (* Measured field strength of quadrupole magnet *)
    bInjectionTrigger : BOOL; (* Trigger to start injection process *)
    bExtractionTrigger : BOOL; (* Trigger to start extraction process *)
    bEmergencyAbort : BOOL; (* Emergency beam abort signal *)
    rCoolingWaterTemp_C : REAL; (* Cooling water temperature for magnets *)
END_VAR

VAR_OUTPUT
    rRFCavityDrivePhase_deg : REAL; (* Command phase to RF cavity amplifier *)
    rQuadrupoleCurrent_A : REAL; (* Command current to quadrupole power supply *)
    bDipoleMagnetEnable : BOOL; (* Enable signal for main dipole magnets *)
    bRFSystemEnable : BOOL; (* Enable signal for RF system *)
    bBeamDumpTrigger : BOOL; (* Trigger to kicker magnets for beam dump *)
    iSystemState : INT; (* State machine status (0=Idle, 1=Injection, 2=Ramp, 3=Flattop, 4=Extraction, 5=Abort) *)
    rCalculatedTune_X : REAL; (* Calculated horizontal tune *)
    rCalculatedTune_Y : REAL; (* Calculated vertical tune *)
    bOverTempAlarm : BOOL; (* Alarm flag for cooling water over temperature *)
END_VAR

VAR
    rBeamCurrentIntegral : REAL := 0.0;
    rPhaseError : REAL := 0.0;
    rPhaseIntegral : REAL := 0.0;
    rPhaseKp : REAL := 1.25;
    rPhaseKi : REAL := 0.45;
    rMaxPhaseCorrection : REAL := 15.0;

    rNominalQuadFocusLength_m : REAL := 2.34;
    rQuadK_Value : REAL := 0.0;
    rReferenceMomentum_GeVc : REAL := 0.0;

    tStateTimer : TON;
    bRampComplete : BOOL := FALSE;
    bCoolingOk : BOOL := TRUE;
END_VAR

VAR CONSTANT
    C_SPEED_OF_LIGHT : REAL := 299792458.0;
    C_MAX_COOLING_TEMP : REAL := 45.0;
    C_MIN_BEAM_CURRENT : REAL := 0.1;
    C_MAX_BEAM_ENERGY : REAL := 7.0;
END_VAR

(* Main Control Logic *)
bCoolingOk := (rCoolingWaterTemp_C < C_MAX_COOLING_TEMP);
bOverTempAlarm := NOT bCoolingOk;

IF bEmergencyAbort OR NOT bCoolingOk THEN
    iSystemState := 5; (* Abort State *)
END_IF;

CASE iSystemState OF
    0: (* Idle State *)
        bDipoleMagnetEnable := FALSE;
        bRFSystemEnable := FALSE;
        bBeamDumpTrigger := FALSE;
        rRFCavityDrivePhase_deg := 0.0;
        rQuadrupoleCurrent_A := 0.0;

        IF bInjectionTrigger AND bCoolingOk THEN
            iSystemState := 1; (* Transition to Injection *)
        END_IF;

    1: (* Injection State *)
        bDipoleMagnetEnable := TRUE;
        bRFSystemEnable := TRUE;
        bBeamDumpTrigger := FALSE;
        rReferenceMomentum_GeVc := 0.450; (* Injection energy *)

        IF rBeamCurrent_mA > C_MIN_BEAM_CURRENT THEN
            iSystemState := 2; (* Transition to Ramp *)
        END_IF;

    2: (* Ramp State *)
        (* PI Control for RF Cavity Phase to maintain acceleration bucket *)
        rPhaseError := 0.0 - rRFCavityPhase_deg; (* Simplified phase error calculation *)
        rPhaseIntegral := rPhaseIntegral + (rPhaseError * 0.01); (* Assuming 10ms cycle time *)

        IF rPhaseIntegral > rMaxPhaseCorrection THEN rPhaseIntegral := rMaxPhaseCorrection; END_IF;
        IF rPhaseIntegral < -rMaxPhaseCorrection THEN rPhaseIntegral := -rMaxPhaseCorrection; END_IF;

        rRFCavityDrivePhase_deg := (rPhaseError * rPhaseKp) + (rPhaseIntegral * rPhaseKi);

        (* Quadrupole field ramping based on momentum *)
        rReferenceMomentum_GeVc := rReferenceMomentum_GeVc + 0.005; (* Ramp rate *)
        rQuadK_Value := 0.29979 * rQuadrupoleField_T / rReferenceMomentum_GeVc;
        rCalculatedTune_X := rQuadK_Value * 1.5; (* Highly simplified tune calculation *)
        rCalculatedTune_Y := rQuadK_Value * 1.4;

        rQuadrupoleCurrent_A := rReferenceMomentum_GeVc * 150.0; (* Current vs Momentum conversion factor *)

        IF rReferenceMomentum_GeVc >= rTargetBeamEnergy_GeV THEN
            bRampComplete := TRUE;
            iSystemState := 3; (* Flattop *)
        END_IF;

    3: (* Flattop State *)
        (* Maintain stable orbit for experiments or extraction *)
        rPhaseError := 0.0 - rRFCavityPhase_deg; 
        rRFCavityDrivePhase_deg := (rPhaseError * rPhaseKp * 0.5) + (rPhaseIntegral * rPhaseKi * 0.1); (* Relaxed gains during flattop *)

        IF bExtractionTrigger THEN
            iSystemState := 4; (* Extraction *)
        END_IF;

    4: (* Extraction State *)
        (* Trigger fast kicker magnets for single-turn extraction *)
        bBeamDumpTrigger := TRUE;

        IF rBeamCurrent_mA < C_MIN_BEAM_CURRENT THEN
            iSystemState := 0; (* Back to Idle after extraction *)
        END_IF;

    5: (* Abort State *)
        bBeamDumpTrigger := TRUE; (* Dump the beam immediately into the absorber block *)
        bRFSystemEnable := FALSE;
        rRFCavityDrivePhase_deg := 0.0;

        (* Keep dipole magnets on briefly to guide beam to dump, then disable *)
        tStateTimer(IN:=TRUE, PT:=T#500ms);
        IF tStateTimer.Q THEN
            bDipoleMagnetEnable := FALSE;
            rQuadrupoleCurrent_A := 0.0;
            IF bCoolingOk AND NOT bEmergencyAbort THEN
                iSystemState := 0; (* Reset if conditions clear *)
            END_IF;
        END_IF;

    ELSE
        iSystemState := 5; (* Fail-safe *)
END_CASE;

END_FUNCTION_BLOCK
