            iDrift_Count := iDrift_Count + 1;
        END_IF;
    END_FOR;
    bDrift_Alarm := (iDrift_Count > 0);

    // HIL Digital Twin Synchronization Check
    IF (iState > 0) AND (ABS(rAvg_Temp - rHIL_Twin_Temp) > 10.0) THEN
        bTwin_Desync_Alarm := TRUE;
        wDiag_Code := 16#A002; // Digital Twin Desync
        iState := 99;
