FUNCTION_BLOCK "Lyophilizer_Profinet_Diag"
VERSION : 0.1
VAR_INPUT
    Start_Cycle : Bool;
    Stop_Cycle : Bool;
    Chamber_Pressure : Real;
    Shelf_Temp : Real;
    Target_Vacuum : Real;
    // Profinet Inputs
    PN_Remote_Status AT %I0.0 : Word;
END_VAR
VAR_OUTPUT
    Vacuum_Pump_Run : Bool;
    Compressor_Run : Bool;
    Heater_Run : Bool;
    Status : Int;
    Fault_Code : Int;
    // Profinet Outputs
    PN_Control_Word AT %Q0.0 : Word;
END_VAR
VAR
    State : Int;
    Vacuum_Timer : TON;
    Temp_Timer : TON;
END_VAR
BEGIN
    IF Stop_Cycle THEN State := 0; Fault_Code := 0; END_IF;

    CASE State OF
        0: // Idle
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
            IF Start_Cycle THEN State := 1; END_IF;
        1: // Freezing
            Compressor_Run := TRUE;
            IF Shelf_Temp <= -40.0 THEN State := 2; END_IF;
        2: // Drying
            Compressor_Run := TRUE;
            Vacuum_Pump_Run := TRUE;

            // Diagnostics: Vacuum Leak Detection
            Vacuum_Timer(IN:= (Chamber_Pressure > Target_Vacuum + 5.0), PT:= t#10m);
            IF Vacuum_Timer.Q THEN
                Fault_Code := 101; // Vacuum Leak Fault
                State := 99;
            END_IF;

            // Diagnostics: Temperature Deviation Detection
            Temp_Timer(IN:= (ABS(Shelf_Temp - 10.0) > 5.0), PT:= t#5m);
            IF Temp_Timer.Q AND Chamber_Pressure <= Target_Vacuum THEN
                Fault_Code := 102; // Temp Deviation Fault
                State := 99;
            END_IF;

            IF Chamber_Pressure <= Target_Vacuum THEN
                Heater_Run := (Shelf_Temp < 10.0);
            END_IF;
        99: // Fault State
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
    END_CASE;

    Status := State;
    // Profinet Mapping
    PN_Control_Word := INT_TO_WORD(Status) OR SHL(IN:=INT_TO_WORD(Fault_Code), N:=8);
END_FUNCTION_BLOCK
