FUNCTION_BLOCK FB_BiomassGasifierControl
VAR_INPUT
    rBedTemperature : REAL; (* Fluidized bed temperature in Celsius *)
    rSyngasTarLevel : REAL; (* Syngas tar concentration mg/Nm3 *)
    rOxygenFlowRate : REAL; (* Oxygen flow rate kg/h *)
    rSteamFlowRate : REAL; (* Steam flow rate kg/h *)
    rAshPressureDrop : REAL; (* Pressure drop across the bed for agglomeration monitoring kPa *)
    bStartProcess : BOOL; (* Start process flag *)
    bEmergencyStop : BOOL; (* Emergency stop flag *)
END_VAR
VAR_OUTPUT
    rO2ValvePosition : REAL; (* Oxygen control valve 0-100% *)
    rSteamValvePosition : REAL; (* Steam control valve 0-100% *)
    bTarReformerActive : BOOL; (* Activate secondary tar reformer *)
    bAshRemovalActive : BOOL; (* Activate ash extraction mechanism *)
    bAlarmAgglomeration : BOOL; (* Bed agglomeration warning *)
    bAlarmHighTar : BOOL; (* High tar concentration warning *)
    rStoichiometricRatio : REAL; (* Current O2/Steam ratio *)
    sSystemState : STRING[32]; (* Current state of the gasification process *)
END_VAR
VAR
    rTargetRatio : REAL := 0.35; (* Optimal stoichiometric ratio *)
    rRatioError : REAL;
    rRatioIntegral : REAL := 0.0;
    rKp : REAL := 1.2;
    rKi : REAL := 0.05;
    rTarThreshold : REAL := 50.0; (* Limit for tar in mg/Nm3 *)
    rAshPressureLimit : REAL := 15.0; (* Max pressure drop for agglomeration warning *)
    tTarTimer : TON;
    tAshTimer : TON;
    iState : INT := 0; (* 0: IDLE, 1: STARTUP, 2: RUNNING, 3: SHUTDOWN, 4: ALARM *)
END_VAR

(* Main State Machine *)
IF bEmergencyStop THEN
    iState := 4;
    sSystemState := 'EMERGENCY_STOP';
    rO2ValvePosition := 0.0;
    rSteamValvePosition := 0.0;
    bTarReformerActive := FALSE;
    bAshRemovalActive := FALSE;
    bAlarmAgglomeration := TRUE;
ELSIF NOT bStartProcess AND iState <> 4 THEN
    iState := 0;
    sSystemState := 'IDLE';
    rO2ValvePosition := 0.0;
    rSteamValvePosition := 0.0;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bTarReformerActive := FALSE;
        bAshRemovalActive := FALSE;
        bAlarmAgglomeration := FALSE;
        bAlarmHighTar := FALSE;
        IF bStartProcess THEN
            iState := 1;
            sSystemState := 'STARTUP';
        END_IF;

    1: (* STARTUP *)
        rO2ValvePosition := 20.0; (* Pre-heating via partial oxidation *)
        rSteamValvePosition := 10.0;
        IF rBedTemperature > 750.0 THEN
            iState := 2;
            sSystemState := 'RUNNING_OPTIMAL';
        END_IF;

    2: (* RUNNING *)
        (* Calculate stoichiometric O2/Steam ratio *)
        IF rSteamFlowRate > 0.0 THEN
            rStoichiometricRatio := rOxygenFlowRate / rSteamFlowRate;
        ELSE
            rStoichiometricRatio := 0.0;
        END_IF;

        (* PI Control for Stoichiometric Ratio *)
        rRatioError := rTargetRatio - rStoichiometricRatio;
        rRatioIntegral := rRatioIntegral + (rRatioError * 0.1); (* Assuming 100ms cycle time *)

        (* Limit integral windup *)
        IF rRatioIntegral > 50.0 THEN rRatioIntegral := 50.0; END_IF;
        IF rRatioIntegral < -50.0 THEN rRatioIntegral := -50.0; END_IF;

        rO2ValvePosition := rO2ValvePosition + (rKp * rRatioError) + (rKi * rRatioIntegral);

        (* Limit outputs *)
        IF rO2ValvePosition > 100.0 THEN rO2ValvePosition := 100.0; END_IF;
        IF rO2ValvePosition < 15.0 THEN rO2ValvePosition := 15.0; END_IF;

        (* Tar Reforming Logic *)
        tTarTimer(IN := rSyngasTarLevel > rTarThreshold, PT := T#5S);
        IF tTarTimer.Q THEN
            bTarReformerActive := TRUE;
            bAlarmHighTar := TRUE;
        ELSIF rSyngasTarLevel < (rTarThreshold * 0.8) THEN
            bTarReformerActive := FALSE;
            bAlarmHighTar := FALSE;
        END_IF;

        (* Ash Agglomeration Monitoring *)
        tAshTimer(IN := rAshPressureDrop > rAshPressureLimit, PT := T#10S);
        IF tAshTimer.Q THEN
            bAlarmAgglomeration := TRUE;
            bAshRemovalActive := TRUE;
            sSystemState := 'AGGLOMERATION_WARNING';
        ELSIF rAshPressureDrop < (rAshPressureLimit - 2.0) THEN
            bAlarmAgglomeration := FALSE;
            bAshRemovalActive := FALSE;
            sSystemState := 'RUNNING_OPTIMAL';
        END_IF;

        (* Safety interlock for high temperature *)
        IF rBedTemperature > 950.0 THEN
            iState := 3;
            sSystemState := 'SHUTDOWN_HIGHTEMP';
        END_IF;

    3: (* SHUTDOWN *)
        rO2ValvePosition := 0.0; (* Cut oxygen to stop gasification *)
        rSteamValvePosition := 100.0; (* Flood with steam to quench bed *)
        IF rBedTemperature < 400.0 THEN
            iState := 0;
            sSystemState := 'IDLE';
        END_IF;

    4: (* ALARM *)
        (* Wait for manual reset *)
        rO2ValvePosition := 0.0;
        rSteamValvePosition := 0.0;
END_CASE;

END_FUNCTION_BLOCK
