      pidCoolant : "PID_Compact";
      conveyorState : Int;
      timerConveyor : TON_TIME;
      atcState : Int;
      currentSlot : Int := 1;
      timerATC : TON_TIME;
   END_VAR

BEGIN
    // Fault Diagnostics Matrix & PROFINET Monitoring
    #alarmWord1 := 16#0000;
    #systemFault := FALSE;

    // Check Profinet nodes
    IF #pnIoDevice1_Status <> 16#0000 THEN
        #alarmWord1.%X0 := TRUE; // Bit 0: PN Node 1 Error
        #systemFault := TRUE;
    END_IF;
    IF #pnIoDevice2_Status <> 16#0000 THEN
        #alarmWord1.%X1 := TRUE; // Bit 1: PN Node 2 Error
        #systemFault := TRUE;
    END_IF;

    // Monitor Tool Wear Limit
    IF #toolWearValue > 0.5 THEN
        #alarmWord1.%X2 := TRUE; // Bit 2: Tool wear critical
        #systemFault := TRUE;
    END_IF;

    // Stop execution on critical fault
    IF #systemFault THEN
        #conveyorMotorFwd := FALSE;
        #conveyorMotorRev := FALSE;
        #carouselIndexFwd := FALSE;
        #armRotate := FALSE;
        #spindleCoolantValve := 0.0;
        RETURN; // Abort further logic
    END_IF;

    // 1. Tool Wear
    IF #toolWearValue > 0.05 THEN
        #toolOffsetActive := #toolWearValue;
    ELSE
        #toolOffsetActive := 0.0;
    END_IF;

    // 2. Coolant PID
    #pidCoolant(
        Setpoint := 22.0,
        Input := #spindleTempSensor,
        Output => #spindleCoolantValve
    );

    // 3. Chip Conveyor
    IF #conveyorStart THEN
        CASE #conveyorState OF
            0: 
                #conveyorState := 1;
            1:
                #conveyorMotorFwd := TRUE;
                #conveyorMotorRev := FALSE;
                #timerConveyor(IN := TRUE, PT := T#15s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 2;
                    #timerConveyor(IN := FALSE, PT := T#15s);
                END_IF;
            2:
                #conveyorMotorFwd := FALSE;
                #conveyorMotorRev := TRUE;
                #timerConveyor(IN := TRUE, PT := T#2s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 1;
                    #timerConveyor(IN := FALSE, PT := T#2s);
                END_IF;
        END_CASE;
    ELSE
        #conveyorState := 0;
        #conveyorMotorFwd := FALSE;
        #conveyorMotorRev := FALSE;
        #timerConveyor(IN := FALSE, PT := T#15s);
    END_IF;

    // 4. ATC Logic
    CASE #atcState OF
        0:
            #atcReady := TRUE;
            #carouselIndexFwd := FALSE;
            #armRotate := FALSE;
            #spindleUnclamp := FALSE;
            IF #reqToolChange AND (#targetToolSlot <> #currentSlot) AND (#targetToolSlot >= 1) AND (#targetToolSlot <= 12) THEN
                #atcReady := FALSE;
                #atcState := 1;
            END_IF;
        1:
            IF NOT #carouselInPosition THEN
                #carouselIndexFwd := TRUE;
            ELSE
                #carouselIndexFwd := FALSE;
                #currentSlot := #targetToolSlot;
                #atcState := 2;
            END_IF;
        2:
            #spindleUnclamp := TRUE;
            #armRotate := TRUE;
            #timerATC(IN := TRUE, PT := T#3s);
            IF #timerATC.Q AND #armAtSpindle AND #armAtCarousel THEN
                #spindleUnclamp := FALSE;
                #armRotate := FALSE;
                #atcState := 0;
                #timerATC(IN := FALSE, PT := T#3s);
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
