      Test_Timer : Int := 0;
   END_VAR

BEGIN
// HIL Digital Twin Sync
#HIL_Sync_Ack := #HIL_Heartbeat;
IF NOT #HIL_Heartbeat THEN
    #Alarm_Word := #Alarm_Word OR 16#00000010; // HIL Disconnected
END_IF;

// IEC 62443 Access
IF #User_Role >= 2 THEN
    #Kp := #SCADA_Param_Kp;
END_IF;

// Pre-Flight Self-Test Routine
IF NOT #Self_Test_Done THEN
    #Test_Timer := #Test_Timer + 1;
    IF #Test_Timer > 100 THEN
        IF NOT #Enc1_Error AND NOT #Enc2_Error THEN
            #Self_Test_Done := TRUE;
            #Spindle_Fault := FALSE;
        ELSE
            #Spindle_Fault := TRUE;
        END_IF;
    END_IF;
    RETURN; // Halt execution until test complete
END_IF;

// Encoder Failover
IF NOT #Enc1_Error THEN
    #Actual_Speed := #Enc1_Speed;
ELSIF NOT #Enc2_Error THEN
    #Actual_Speed := #Enc2_Speed;
ELSE
    #Spindle_Fault := TRUE;
    #Actual_Speed := 0.0;
END_IF;
#SCADA_Actual_Speed := #Actual_Speed;

// Sensor Drift Detection for Vibration Probes
IF ABS(#Vib_Sensor1 - #Vib_Sensor2) > 1.0 THEN
    #Alarm_Word := #Alarm_Word OR 16#00000020; // Drift Detected
    #Vibration_Level := (#Vib_Sensor1 + #Vib_Sensor2) / 2.0; // Average
ELSE
    #Vibration_Level := #Vib_Sensor1;
END_IF;

IF #Vibration_Level > #Vibration_Limit THEN
    #Tool_Wear_Warning := TRUE;
ELSE
    #Tool_Wear_Warning := FALSE;
END_IF;

// ATC State Machine
CASE #State OF
    0: IF #ATC_Request AND ABS(#Actual_Speed) < 5.0 THEN #State := 1; END_IF;
    1: #Spindle_Ready := FALSE; IF #Tool_Unclamp_Sensor THEN #State := 2; END_IF;
    2: IF NOT #ATC_Request AND #Tool_Clamp_Sensor THEN #State := 0; END_IF;
END_CASE;
#ATC_State := #State;

// Speed Control
IF #Enable AND #State = 0 AND NOT #Spindle_Fault THEN
    #Speed_Error := #Setpoint_Speed - #Actual_Speed;
    #Integral_Sum := #Integral_Sum + (#Speed_Error * 0.01); 
    #Drive_Speed_Ref := (#Kp * #Speed_Error) + (#Ki * #Integral_Sum);
    #Spindle_Ready := TRUE;
ELSE
    #Drive_Speed_Ref := 0.0;
    #Integral_Sum := 0.0;
    #Spindle_Ready := FALSE;
END_IF;
END_FUNCTION_BLOCK
