FUNCTION_BLOCK FB_AsphaltBatchingControl
TITLE = 'Asphalt Batching Plant Main Sequencer'
VERSION : '1.1'
AUTHOR : 'Lumina AI'

VAR_INPUT
    bStartProduction : BOOL;      (* Command to start batching sequence *)
    bEmergencyStop : BOOL;        (* E-Stop signal *)
    bResetFault : BOOL;           (* Reset faults *)

    (* Setpoints *)
    rTargetAggWeight : REAL;      (* Target aggregate weight [kg] *)
    rTargetBitWeight : REAL;      (* Target bitumen weight [kg] *)
    rTargetFillerWeight : REAL;   (* Target filler weight [kg] *)
    rTargetAsphaltTemp : REAL;    (* Target asphalt discharge temperature [C] *)
    tDryMixingTime : TIME;        (* Dry mix cycle time *)
    tWetMixingTime : TIME;        (* Wet mix cycle time *)

    (* Sensors and Feedback *)
    rActualAggWeight : REAL;      (* Current aggregate scale weight [kg] *)
    rActualBitWeight : REAL;      (* Current bitumen scale weight [kg] *)
    rActualFillerWeight : REAL;   (* Current filler scale weight [kg] *)
    rDrumTemperature : REAL;      (* Dryer drum temperature sensor [C] *)
    rPugmillTemperature : REAL;   (* Mixer temperature sensor [C] *)
    bMixerDoorClosed : BOOL;      (* Mixer discharge door closed limit switch *)
    bSkipReady : BOOL;            (* Skip hoist is in position for loading *)
    bBurnerFlameDetected : BOOL;  (* Burner flame sensor *)
END_VAR

VAR_OUTPUT
    (* Actuators and Motors *)
    bColdFeedFeeder1 : BOOL;      (* Sand feeder *)
    bColdFeedFeeder2 : BOOL;      (* 10mm feeder *)
    bColdFeedFeeder3 : BOOL;      (* 14mm feeder *)
    bColdFeedFeeder4 : BOOL;      (* 20mm feeder *)

    bDryerDrumMotor : BOOL;       (* Main drum rotation *)
    bBurnerBlower : BOOL;         (* Burner air blower *)
    bBurnerIgniter : BOOL;        (* Burner ignition transformer *)
    rBurnerFuelValve : REAL;      (* Burner fuel modulation 0-100% *)
    bExhaustFan : BOOL;           (* Exhaust and baghouse fan *)

    bAggDischargeGate : BOOL;     (* Dump aggregate into mixer *)
    bBitPumpCommand : BOOL;       (* Pump bitumen to scale *)
    bBitDischargeValve : BOOL;    (* Inject bitumen into mixer *)
    bFillerScrewComm : BOOL;      (* Run filler screw conveyor *)
    bFillerDischargeGate : BOOL;  (* Dump filler into mixer *)

    bPugmillMotor : BOOL;         (* Main mixer motor *)
    bMixerDischargeDoor : BOOL;   (* Open mixer discharge door *)

    (* Status and HMI *)
    iState : INT;                 (* Current sequence state *)
    bProductionActive : BOOL;     (* Production running flag *)
    bFaultActive : BOOL;          (* System fault flag *)
    iFaultCode : INT;             (* Fault code for diagnostics *)
END_VAR

VAR
    tDryMixTimer : TON;
    tWetMixTimer : TON;
    tDischargeTimer : TON;
    tBurnerPurgeTimer : TON;

    rPID_Kp : REAL := 1.85;
    rPID_Ki : REAL := 0.05;
    rPID_Kd : REAL := 0.12;
    rError : REAL;
    rIntegral : REAL;
    rPrevError : REAL;

    bAggReady : BOOL;
    bBitReady : BOOL;
    bFillerReady : BOOL;
END_VAR

(* =========================================================================
   ASPHALT BATCHING PLANT SEQUENCER & PID CONTROL
   ========================================================================= *)

(* Handle Emergency Stop and Faults *)
IF bEmergencyStop THEN
    bColdFeedFeeder1 := FALSE; bColdFeedFeeder2 := FALSE;
    bColdFeedFeeder3 := FALSE; bColdFeedFeeder4 := FALSE;
    bDryerDrumMotor := FALSE; bBurnerBlower := FALSE;
    bBurnerIgniter := FALSE; rBurnerFuelValve := 0.0;
    bExhaustFan := FALSE; bAggDischargeGate := FALSE;
    bBitPumpCommand := FALSE; bBitDischargeValve := FALSE;
    bFillerScrewComm := FALSE; bFillerDischargeGate := FALSE;
    bPugmillMotor := FALSE; bMixerDischargeDoor := FALSE;

    iState := 999;
    bFaultActive := TRUE;
    iFaultCode := 1; (* E-STOP Activated *)
    bProductionActive := FALSE;
    RETURN;
END_IF;

IF bFaultActive AND bResetFault THEN
    bFaultActive := FALSE;
    iFaultCode := 0;
    iState := 0;
END_IF;

IF bFaultActive THEN
    RETURN;
END_IF;

(* Burner PID Control Cascade *)
IF iState >= 20 AND iState <= 50 THEN
    rError := rTargetAsphaltTemp - rDrumTemperature;
    rIntegral := rIntegral + (rError * 0.1); (* 100ms cycle assumption *)

    (* Anti-windup limit *)
    IF rIntegral > 100.0 THEN rIntegral := 100.0; END_IF;
    IF rIntegral < 0.0 THEN rIntegral := 0.0; END_IF;

    rBurnerFuelValve := (rPID_Kp * rError) + (rPID_Ki * rIntegral) + (rPID_Kd * (rError - rPrevError));

    IF rBurnerFuelValve > 100.0 THEN rBurnerFuelValve := 100.0; END_IF;
    IF rBurnerFuelValve < 15.0 THEN rBurnerFuelValve := 15.0; END_IF; (* Minimum fire *)

    rPrevError := rError;
ELSE
    rBurnerFuelValve := 0.0;
    rIntegral := 0.0;
END_IF;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE *)
        bProductionActive := FALSE;
        IF bStartProduction AND bMixerDoorClosed AND bSkipReady THEN
            iState := 10;
            bProductionActive := TRUE;
        END_IF;

    10: (* PLANT STARTUP & PURGE *)
        bExhaustFan := TRUE;
        bDryerDrumMotor := TRUE;
        bBurnerBlower := TRUE;
        tBurnerPurgeTimer(IN:=TRUE, PT:=T#15S);
        IF tBurnerPurgeTimer.Q THEN
            tBurnerPurgeTimer(IN:=FALSE);
            iState := 20;
        END_IF;

    20: (* BURNER IGNITION *)
        bBurnerIgniter := TRUE;
        rBurnerFuelValve := 20.0; (* Light-off position *)
        IF bBurnerFlameDetected THEN
            bBurnerIgniter := FALSE;
            iState := 30;
        END_IF;
        (* Add timeout fault logic here in production *)

    30: (* MATERIAL FEED AND WEIGHING *)
        bColdFeedFeeder1 := TRUE;
        bColdFeedFeeder2 := TRUE;

        (* Aggregate Weighing *)
        IF rActualAggWeight < rTargetAggWeight THEN
            (* Elevators running implied *)
            bAggReady := FALSE;
        ELSE
            bColdFeedFeeder1 := FALSE;
            bColdFeedFeeder2 := FALSE;
            bAggReady := TRUE;
        END_IF;

        (* Bitumen Weighing *)
        IF rActualBitWeight < rTargetBitWeight THEN
            bBitPumpCommand := TRUE;
            bBitReady := FALSE;
        ELSE
            bBitPumpCommand := FALSE;
            bBitReady := TRUE;
        END_IF;

        (* Filler Weighing *)
        IF rActualFillerWeight < rTargetFillerWeight THEN
            bFillerScrewComm := TRUE;
            bFillerReady := FALSE;
        ELSE
            bFillerScrewComm := FALSE;
            bFillerReady := TRUE;
        END_IF;

        IF bAggReady AND bBitReady AND bFillerReady AND (rDrumTemperature >= rTargetAsphaltTemp - 5.0) THEN
            iState := 40;
        END_IF;

    40: (* DRY MIXING CYCLE *)
        bPugmillMotor := TRUE;
        bAggDischargeGate := TRUE;
        tDryMixTimer(IN:=TRUE, PT:=tDryMixingTime);
        IF tDryMixTimer.Q THEN
            bAggDischargeGate := FALSE;
            tDryMixTimer(IN:=FALSE);
            iState := 50;
        END_IF;

    50: (* WET MIXING CYCLE *)
        bBitDischargeValve := TRUE;
        bFillerDischargeGate := TRUE;
        tWetMixTimer(IN:=TRUE, PT:=tWetMixingTime);
        IF tWetMixTimer.Q THEN
            bBitDischargeValve := FALSE;
            bFillerDischargeGate := FALSE;
            tWetMixTimer(IN:=FALSE);
            iState := 60;
        END_IF;

    60: (* DISCHARGE TO SKIP *)
        bMixerDischargeDoor := TRUE;
        tDischargeTimer(IN:=TRUE, PT:=T#10S);
        IF tDischargeTimer.Q THEN
            bMixerDischargeDoor := FALSE;
            tDischargeTimer(IN:=FALSE);
            (* Loop back for next batch or shutdown *)
            IF bStartProduction THEN
                iState := 30;
            ELSE
                iState := 70;
            END_IF;
        END_IF;

    70: (* NORMAL SHUTDOWN *)
        rBurnerFuelValve := 0.0;
        bPugmillMotor := FALSE;
        tBurnerPurgeTimer(IN:=TRUE, PT:=T#30S);
        IF tBurnerPurgeTimer.Q AND NOT bBurnerFlameDetected THEN
            bBurnerBlower := FALSE;
            bDryerDrumMotor := FALSE;
            bExhaustFan := FALSE;
            bProductionActive := FALSE;
            tBurnerPurgeTimer(IN:=FALSE);
            iState := 0;
        END_IF;

    999: (* FAULT STATE *)
        (* Handled at the top of the block *)
        ;

END_CASE;

END_FUNCTION_BLOCK
```

