(*
  HYDROCRACKING REACTOR THERMAL PROFILING CONTROLLER
  --------------------------------------------------
  Author: Lead Process Automation Engineer
  Version: 3.1.0 Enterprise Edition
  Compliance: IEC 61131-3, SIL-3 (IEC 61508)

  DESCRIPTION:
  Advanced Multi-Bed Catalyst Temperature Quench Controller using
  high-pressure hydrogen injection. Includes Rate-of-Change (RoC)
  exothermic runaway prediction and SIL-3 sequenced Emergency
  Depressurization (EDP).
*)

FUNCTION_BLOCK HYDROCRACKING_RX_THERMAL_CTRL

VAR_INPUT
    Enable : BOOL;
    Bed1_Temp : REAL; (* Deg C *)
    Bed2_Temp : REAL; (* Deg C *)
    Bed3_Temp : REAL; (* Deg C *)
    Bed4_Temp : REAL; (* Deg C *)

    Temp_Setpoint : REAL;

    Quench_Hydrogen_Pressure : REAL; (* barg *)
    Runaway_RoC_Limit : REAL := 15.0; (* Deg C / Min *)

    Reset_EDP : BOOL;
END_VAR

VAR_OUTPUT
    Quench_Valve_Bed1 : REAL; (* 0-100% *)
    Quench_Valve_Bed2 : REAL; (* 0-100% *)
    Quench_Valve_Bed3 : REAL; (* 0-100% *)
    Quench_Valve_Bed4 : REAL; (* 0-100% *)

    Runaway_Alarm : BOOL;
    EDP_Valve_1A_SIL3 : BOOL; (* Active Low *)
    EDP_Valve_1B_SIL3 : BOOL; (* Active Low *)
    EDP_Valve_2_SIL3 : BOOL; (* Active Low *)
END_VAR

VAR
    (* PID Controllers for each bed *)
    PID_Bed1 : PID_CONTROLLER;
    PID_Bed2 : PID_CONTROLLER;
    PID_Bed3 : PID_CONTROLLER;
    PID_Bed4 : PID_CONTROLLER;

    (* Derivative / Rate of Change Calculators *)
    RoC_Bed1 : DERIVATIVE;
    RoC_Bed2 : DERIVATIVE;
    RoC_Bed3 : DERIVATIVE;
    RoC_Bed4 : DERIVATIVE;

    (* Timers and internal states for EDP Sequencing *)
    EDP_Active : BOOL;
    EDP_Timer : TON;
    EDP_Step : INT;

    Cycle_Time : REAL := 0.1; (* 100ms task *)
END_VAR

(* 1. EXOTHERMIC RUNAWAY PREDICTION (RoC ALGORITHM) *)
RoC_Bed1(IN := Bed1_Temp, T := Cycle_Time);
RoC_Bed2(IN := Bed2_Temp, T := Cycle_Time);
RoC_Bed3(IN := Bed3_Temp, T := Cycle_Time);
RoC_Bed4(IN := Bed4_Temp, T := Cycle_Time);

IF (RoC_Bed1.OUT > Runaway_RoC_Limit) OR 
   (RoC_Bed2.OUT > Runaway_RoC_Limit) OR 
   (RoC_Bed3.OUT > Runaway_RoC_Limit) OR 
   (RoC_Bed4.OUT > Runaway_RoC_Limit) THEN
    Runaway_Alarm := TRUE;
END_IF;

(* 2. MULTI-BED CATALYST TEMPERATURE QUENCH CONTROL *)
IF Enable AND NOT EDP_Active THEN
    PID_Bed1(SP := Temp_Setpoint, PV := Bed1_Temp, Kp := 1.2, Ti := 120.0, Td := 15.0);
    Quench_Valve_Bed1 := PID_Bed1.CV;

    PID_Bed2(SP := Temp_Setpoint, PV := Bed2_Temp, Kp := 1.2, Ti := 120.0, Td := 15.0);
    Quench_Valve_Bed2 := PID_Bed2.CV;

    PID_Bed3(SP := Temp_Setpoint, PV := Bed3_Temp, Kp := 1.5, Ti := 100.0, Td := 10.0);
    Quench_Valve_Bed3 := PID_Bed3.CV;

    PID_Bed4(SP := Temp_Setpoint, PV := Bed4_Temp, Kp := 1.5, Ti := 100.0, Td := 10.0);
    Quench_Valve_Bed4 := PID_Bed4.CV;
ELSE
    Quench_Valve_Bed1 := 100.0; (* Fail-safe full quench on trip *)
    Quench_Valve_Bed2 := 100.0;
    Quench_Valve_Bed3 := 100.0;
    Quench_Valve_Bed4 := 100.0;
END_IF;

(* 3. SIL-3 EMERGENCY DEPRESSURIZATION (EDP) SEQUENCING *)
IF Runaway_Alarm THEN
    EDP_Active := TRUE;
END_IF;

IF Reset_EDP AND NOT Runaway_Alarm THEN
    EDP_Active := FALSE;
    EDP_Step := 0;
    EDP_Valve_1A_SIL3 := TRUE; (* Energize to Close *)
    EDP_Valve_1B_SIL3 := TRUE;
    EDP_Valve_2_SIL3 := TRUE;
END_IF;

IF EDP_Active THEN
    CASE EDP_Step OF
        0: (* Immediate partial depressurization *)
           EDP_Valve_1A_SIL3 := FALSE; (* De-energize to Open *)
           EDP_Valve_1B_SIL3 := TRUE;
           EDP_Valve_2_SIL3 := TRUE;
           EDP_Timer(IN := TRUE, PT := T#30s);
           IF EDP_Timer.Q THEN
               EDP_Step := 1;
               EDP_Timer(IN := FALSE);
           END_IF;

        1: (* Redundant path opening *)
           EDP_Valve_1B_SIL3 := FALSE;
           EDP_Timer(IN := TRUE, PT := T#60s);
           IF EDP_Timer.Q THEN
               EDP_Step := 2;
               EDP_Timer(IN := FALSE);
           END_IF;

        2: (* Total atmospheric blowdown *)
           EDP_Valve_2_SIL3 := FALSE;
    END_CASE;
ELSE
    EDP_Valve_1A_SIL3 := TRUE;
    EDP_Valve_1B_SIL3 := TRUE;
    EDP_Valve_2_SIL3 := TRUE;
    EDP_Timer(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK
