TYPE "PN_Data_In"
    STRUCT
        MasterEnable : Bool;
        ConveyorPos : Real;
        SetDipAngle : Real;
        Anolyte_pH_Sensor : Real;
        Anolyte_Cond_Sensor : Real;
        EmergencyStop : Bool;
    END_STRUCT;
END_TYPE

TYPE "PN_Data_Out"
    STRUCT
        RectifierVoltage : Real;
        ConveyorAngleCmd : Real;
        SystemFault : Bool;
        FaultCode : Int;
        Heartbeat : Bool;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "ECoat_Breadth"
VAR_INPUT
    PN_IN : "PN_Data_In";
END_VAR
VAR_OUTPUT
    PN_OUT : "PN_Data_Out";
    AcidDosePump : Bool;
    BaseDosePump : Bool;
    DiWaterValve : Bool;
END_VAR
VAR
    VoltageProfileCurve : ARRAY[0..10] OF Real := [0.0, 50.0, 150.0, 300.0, 350.0, 350.0, 350.0, 350.0, 200.0, 50.0, 0.0];
    Index : Int;
    pH_Setpoint : Real := 5.5;
    Cond_Setpoint : Real := 1500.0;
    FaultActive : Bool;
    FaultID : Int;
    Clock_1Hz : Bool;
END_VAR
BEGIN
    PN_OUT.Heartbeat := Clock_1Hz;

    IF PN_IN.EmergencyStop THEN
        FaultActive := TRUE;
        FaultID := 1;
    ELSIF PN_IN.Anolyte_pH_Sensor < 1.0 OR PN_IN.Anolyte_pH_Sensor > 14.0 THEN
        FaultActive := TRUE;
        FaultID := 2;
    ELSE
        FaultActive := FALSE;
        FaultID := 0;
    END_IF;

    PN_OUT.SystemFault := FaultActive;
    PN_OUT.FaultCode := FaultID;

    IF PN_IN.MasterEnable AND NOT FaultActive THEN
        PN_OUT.ConveyorAngleCmd := PN_IN.SetDipAngle;
        IF PN_IN.ConveyorPos >= 0.0 AND PN_IN.ConveyorPos <= 100.0 THEN
            Index := REAL_TO_INT(PN_IN.ConveyorPos / 10.0);
            IF Index > 10 THEN Index := 10; END_IF;
            IF Index < 0 THEN Index := 0; END_IF;
            PN_OUT.RectifierVoltage := VoltageProfileCurve[Index];
        ELSE
            PN_OUT.RectifierVoltage := 0.0;
        END_IF;

        IF PN_IN.Anolyte_pH_Sensor > (pH_Setpoint + 0.2) THEN
            AcidDosePump := TRUE;
            BaseDosePump := FALSE;
        ELSIF PN_IN.Anolyte_pH_Sensor < (pH_Setpoint - 0.2) THEN
            AcidDosePump := FALSE;
            BaseDosePump := TRUE;
        ELSE
            AcidDosePump := FALSE;
            BaseDosePump := FALSE;
        END_IF;

        IF PN_IN.Anolyte_Cond_Sensor > (Cond_Setpoint + 50.0) THEN
            DiWaterValve := TRUE;
        ELSE
            DiWaterValve := FALSE;
        END_IF;
    ELSE
        PN_OUT.RectifierVoltage := 0.0;
        PN_OUT.ConveyorAngleCmd := 0.0;
        AcidDosePump := FALSE;
        BaseDosePump := FALSE;
        DiWaterValve := FALSE;
    END_IF;
END_FUNCTION_BLOCK
