    fPlumeDispersionFactor  : LREAL;  // Calculated optimal dispersion score (0-1)

    // Alarms and Status
    bOverTempAlarm          : BOOL;
    bLowYieldWarning        : BOOL;
    bActive                 : BOOL;
    bError                  : BOOL;
    nErrorID                : UDINT;
END_VAR

VAR
    // Internal Process Variables
    fCurrentSmeltTemp_K     : LREAL;
    fFluorineEfficiency     : LREAL;
    fRemainingFluorine_kg_s : LREAL;

    // PID Controllers
