    // Constants
    c_F_AtomicMass          : LREAL := 18.998;
    c_S_AtomicMass          : LREAL := 32.065;
    c_C_AtomicMass          : LREAL := 12.011;
    c_FaradaysConstant      : LREAL := 96485.332; // C/mol
    c_MaxWindSpeed_Disp     : LREAL := 35.0; // Optimal dispersion max wind
END_VAR

// ==============================================================================
// IMPLEMENTATION
// ==============================================================================

// 1. PackML State Machine (Simplified)
IF bAbort THEN
    eState := E_PackML_State.ABORTING;
ELSIF bStop THEN
    eState := E_PackML_State.STOPPING;
END_IF

CASE eState OF
    E_PackML_State.STOPPED:
        bActive := FALSE;
        IF bReset THEN
            eState := E_PackML_State.IDLE;
            bError := FALSE;
            nErrorID := 0;
        END_IF

    E_PackML_State.IDLE:
        bActive := FALSE;
        IF bStart AND bEnable THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        // Initialize PID controllers and heat up smelt
        fbSmeltTempPID.bEnable := TRUE;
        fbReactorPressPID.bEnable := TRUE;
        tonProcessDelay(IN := TRUE, PT := T#10S);
        IF tonProcessDelay.Q THEN
            eState := E_PackML_State.EXECUTE;
            tonProcessDelay(IN := FALSE);
        END_IF

    E_PackML_State.EXECUTE:
        bActive := TRUE;

        // ---------------------------------------------------------
        // A. Regolith Fluorine Extraction (Electrolytic Smelting)
        // ---------------------------------------------------------
        // Simulate Temp Control
        fbSmeltTempPID(
            fSetpoint := fTargetSmeltTemp_K,
            fActualValue := fCurrentSmeltTemp_K,
            fOutput => (* Heater Control Value *)
        );

        // Faraday's Law for Electrolysis: m = (Q * M) / (z * F)
        // Assume z=1 for F- ions
        IF fCurrentSmeltTemp_K > (fTargetSmeltTemp_K * 0.95) THEN
            fFluorineEfficiency := 0.85; // 85% efficient at temp
            fFluorineYield_kg_s := (fElectrolysisCurrent_A * c_F_AtomicMass * fFluorineEfficiency) / (1.0 * c_FaradaysConstant * 1000.0);
        ELSE
            fFluorineYield_kg_s := 0.0;
        END_IF

        // Cap yield by available regolith content (assume ~0.05% F in raw regolith max)
        IF fFluorineYield_kg_s > (fRegolithFeedRate_kg_s * 0.0005) THEN
            fFluorineYield_kg_s := fRegolithFeedRate_kg_s * 0.0005;
        END_IF

        fRemainingFluorine_kg_s := fFluorineYield_kg_s;

        // ---------------------------------------------------------
        // B. Catalytic Synthesis of Super-Greenhouse Gases
        // ---------------------------------------------------------
        // Priority 1: SF6 (Highest Global Warming Potential, ~23,500x CO2)
        // S + 3F2 -> SF6 (Stoichiometric ratio S:F = 32 : 114)
        fSF6_Synthesized_kg_s := MIN(fSulfurFeedRate_kg_s, fRemainingFluorine_kg_s * (c_S_AtomicMass / (6.0 * c_F_AtomicMass))) * (1.0 + (6.0 * c_F_AtomicMass) / c_S_AtomicMass);
        fRemainingFluorine_kg_s := fRemainingFluorine_kg_s - (fSF6_Synthesized_kg_s * (6.0 * c_F_AtomicMass) / (c_S_AtomicMass + 6.0 * c_F_AtomicMass));

        // Priority 2: CF4 (GWP ~6,500x CO2)
        // C + 2F2 -> CF4 (Stoichiometric ratio C:F = 12 : 76)
        fCF4_Synthesized_kg_s := MIN(fCarbonFeedRate_kg_s, fRemainingFluorine_kg_s * (c_C_AtomicMass / (4.0 * c_F_AtomicMass))) * (1.0 + (4.0 * c_F_AtomicMass) / c_C_AtomicMass);
        fRemainingFluorine_kg_s := fRemainingFluorine_kg_s - (fCF4_Synthesized_kg_s * (4.0 * c_F_AtomicMass) / (c_C_AtomicMass + 4.0 * c_F_AtomicMass));

        // Priority 3: C2F6 (GWP ~11,100x CO2)
        // 2C + 3F2 -> C2F6 (Requires remaining C and F)
        // Simplified fallback for remaining feed
        fC2F6_Synthesized_kg_s := fRemainingFluorine_kg_s; // Assuming excess Carbon is available
        fRemainingFluorine_kg_s := 0.0;

        // ---------------------------------------------------------
        // C. Atmospheric Venting & Dispersion Calculation
        // ---------------------------------------------------------
        fTotalVentingRate_kg_s := fSF6_Synthesized_kg_s + fCF4_Synthesized_kg_s + fC2F6_Synthesized_kg_s;

        // Calculate dispersion factor based on ambient wind (0 to 1)
        IF fAmbientWindSpeed_m_s < 2.0 THEN
            fPlumeDispersionFactor := 0.1; // Poor dispersion, risk of localized pooling
        ELSIF fAmbientWindSpeed_m_s > c_MaxWindSpeed_Disp THEN
            fPlumeDispersionFactor := 0.5; // Too turbulent, potential atmospheric sheer loss
        ELSE
            fPlumeDispersionFactor := 1.0 - (ABS(15.0 - fAmbientWindSpeed_m_s) / 20.0); // Optimal around 15 m/s
        END_IF

        // ---------------------------------------------------------
        // D. Diagnostics & Safety
        // ---------------------------------------------------------
        bOverTempAlarm := (fCurrentSmeltTemp_K > 1800.0);
        bLowYieldWarning := (fFluorineYield_kg_s < 0.001) AND (fRegolithFeedRate_kg_s > 10.0);

        IF bOverTempAlarm THEN
            eState := E_PackML_State.HOLDING;
            bError := TRUE;
            nErrorID := 16#F001; // Over-temperature critical fault
        END_IF

    E_PackML_State.HOLDING:
        // Pause production, maintain safe state
        fbSmeltTempPID.bEnable := FALSE;
        IF NOT bOverTempAlarm AND bStart THEN
            eState := E_PackML_State.UNHOLDING;
        END_IF

    E_PackML_State.UNHOLDING:
        eState := E_PackML_State.EXECUTE;

    E_PackML_State.ABORTING:
        // Emergency stop procedures
        fFluorineYield_kg_s := 0.0;
        fTotalVentingRate_kg_s := 0.0;
        bActive := FALSE;
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF bReset THEN
            eState := E_PackML_State.IDLE;
        END_IF

    E_PackML_State.STOPPING:
        // Normal shutdown
        fFluorineYield_kg_s := 0.0;
        fTotalVentingRate_kg_s := 0.0;
        eState := E_PackML_State.STOPPED;

    ELSE
        eState := E_PackML_State.STOPPED;
END_CASE;

END_FUNCTION_BLOCK
```

