FUNCTION_BLOCK FB_DLE_IonExchange
(* ==============================================================================
   Block Name: FB_DLE_IonExchange
   Description: High-performance controller for Lithium Brine Direct Extraction (DLE)
                using Ion Exchange Resin Columns. Manages continuous adsorption,
                differential pressure-triggered backwashing, and conductivity-based
                desorption/elution phases. Includes strict interlocks and safety
                shutdown sequencing.
   Author: Lumina Elite Automation Architect
   Version: 1.0.0
   ============================================================================== *)
VAR_INPUT
    bEnable                 : BOOL;     (* System enable signal from master sequence *)
    bEmergencyStop_OK       : BOOL;     (* Safety Relay OK signal (Active High) *)
    rFeedFlowRate           : REAL;     (* Brine feed flow rate in m3/h *)
    rBedDiffPressure        : REAL;     (* Pressure drop across resin bed in bar *)
    rEluentConductivity     : REAL;     (* Eluent outflow conductivity in mS/cm *)
    rFeedLiConcentration    : REAL;     (* Real-time Lithium feed conc. in mg/L *)
    rResinCapacityMax       : REAL;     (* Max Lithium load capacity of bed in kg *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is initialized and ready for feed *)
    bBackwashActive         : BOOL;     (* Backwash sequence in progress *)
    bDesorptionActive       : BOOL;     (* Desorption (elution) sequence in progress *)
    rFeedValveCmd           : REAL;     (* 0-100% command for brine feed control valve *)
    rEluentValveCmd         : REAL;     (* 0-100% command for eluent control valve *)
    rRinseValveCmd          : REAL;     (* 0-100% command for DI water rinse valve *)
    bAlarmHighDP            : BOOL;     (* Alarm: High differential pressure detected *)
    bAlarmOverload          : BOOL;     (* Alarm: Resin bed capacity exceeded *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal State Machine Step *)
    rTotalLiAdsorbed        : REAL := 0.0; (* Accumulated Li mass on resin in kg *)

    (* Timers *)
    tCycleTimer             : TON;
    tBackwashTimer          : TON;
    tRinseTimer             : TON;

    (* Configurable Parameters *)
    rMaxDiffPressure        : REAL := 2.5;  (* Bar threshold for auto-backwash *)
    rDesorptionTargetCond   : REAL := 15.0; (* mS/cm threshold for rich eluate *)
    tAdsorptionDuration     : TIME := T#4H; 
    tBackwashDuration       : TIME := T#15M;
    tRinseDuration          : TIME := T#10M;

    (* Internal Status *)
    bRequestBackwash        : BOOL := FALSE;
    bRequestDesorption      : BOOL := FALSE;
END_VAR

(* === MAIN SAFETY INTERLOCK === *)
IF NOT bEmergencyStop_OK THEN
    bSystemReady      := FALSE;
    rFeedValveCmd     := 0.0;
    rEluentValveCmd   := 0.0;
    rRinseValveCmd    := 0.0;
    bBackwashActive   := FALSE;
    bDesorptionActive := FALSE;
    iState            := 999; (* Fault State *)
    RETURN;
END_IF;

(* === DIFFERENTIAL PRESSURE MONITORING === *)
IF rBedDiffPressure >= rMaxDiffPressure THEN
    bAlarmHighDP := TRUE;
    bRequestBackwash := TRUE;
ELSE
    bAlarmHighDP := FALSE;
END_IF;

(* === LITHIUM MASS BALANCE CALCULATION (Simplified integration over scan cycle) === *)
IF iState = 10 AND rFeedFlowRate > 0.0 THEN
    (* Assuming 1s scan time for demonstration. Actual implementation uses proper task dt *)
    rTotalLiAdsorbed := rTotalLiAdsorbed + (rFeedFlowRate * rFeedLiConcentration * 0.001 / 3600.0);
END_IF;

IF rTotalLiAdsorbed >= rResinCapacityMax THEN
    bAlarmOverload := TRUE;
    bRequestDesorption := TRUE;
END_IF;

(* === STATE MACHINE === *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        rFeedValveCmd := 0.0;
        rEluentValveCmd := 0.0;
        rRinseValveCmd := 0.0;
        bBackwashActive := FALSE;
        bDesorptionActive := FALSE;

        IF bEnable THEN
            bSystemReady := FALSE;
            tCycleTimer(IN := FALSE);
            iState := 10;
        END_IF;

    10: (* ADSORPTION (LOADING) PHASE *)
        rFeedValveCmd := 100.0; (* Open feed valve fully *)
        rEluentValveCmd := 0.0;

        tCycleTimer(IN := TRUE, PT := tAdsorptionDuration);

        IF tCycleTimer.Q OR bRequestDesorption THEN
            tCycleTimer(IN := FALSE);
            iState := 20; (* Proceed to Rinse before Desorption *)
        ELSIF bRequestBackwash THEN
            tCycleTimer(IN := FALSE);
            iState := 40; (* Proceed to Backwash *)
        END_IF;

    20: (* PRE-DESORPTION RINSE *)
        rFeedValveCmd := 0.0;
        rRinseValveCmd := 100.0;

        tRinseTimer(IN := TRUE, PT := tRinseDuration);
        IF tRinseTimer.Q THEN
            tRinseTimer(IN := FALSE);
            rRinseValveCmd := 0.0;
            iState := 30;
        END_IF;

    30: (* DESORPTION (ELUTION) PHASE *)
        bDesorptionActive := TRUE;
        rEluentValveCmd := 100.0;

        (* Monitor conductivity to determine elution peak completion *)
        IF rEluentConductivity < (rDesorptionTargetCond * 0.1) THEN
            (* Eluate is lean, desorption complete *)
            bDesorptionActive := FALSE;
            rEluentValveCmd := 0.0;
            rTotalLiAdsorbed := 0.0; (* Reset Li mass balance *)
            bRequestDesorption := FALSE;
            bAlarmOverload := FALSE;
            iState := 50; (* Post-Rinse *)
        END_IF;

    40: (* BACKWASH PHASE *)
        bBackwashActive := TRUE;
        rFeedValveCmd := 0.0;
        (* Additional logic to reverse flow would be here *)

        tBackwashTimer(IN := TRUE, PT := tBackwashDuration);
        IF tBackwashTimer.Q THEN
            tBackwashTimer(IN := FALSE);
            bBackwashActive := FALSE;
            bRequestBackwash := FALSE;
            iState := 0; (* Return to Idle / Setup for next cycle *)
        END_IF;

    50: (* POST-DESORPTION RINSE *)
        rRinseValveCmd := 100.0;
        tRinseTimer(IN := TRUE, PT := tRinseDuration);
        IF tRinseTimer.Q THEN
            tRinseTimer(IN := FALSE);
            rRinseValveCmd := 0.0;
            iState := 0;
        END_IF;

    999: (* FAULT / ESTOP STATE *)
        IF bEmergencyStop_OK AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
