FUNCTION_BLOCK "FB_CentrifugalSeparator_Depth"
TITLE = 'Centrifugal Separator with Lube & Cooling'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    bReset : BOOL;
    rSpeedSetpoint : REAL;
