FUNCTION_BLOCK FB_HTST_Pasteurizer_Control
TITLE = 'High Temperature Short Time (HTST) Pasteurizer Advanced Control'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    // Analog Inputs (Physical)
    AI_Temp_Holding_Tube  : REAL; // PT100 at end of holding tube (Deg C)
    AI_Temp_Regen_In      : REAL; // Temp going into regeneration section
    AI_Temp_Heater_Out    : REAL; // Temp exiting heater section
    AI_Flow_Rate          : REAL; // Magnetic flow meter (L/hr)
    AI_Diff_Pressure      : REAL; // Diff pressure raw unpasteurized vs pasteurized (kPa)

    // Digital Inputs (Physical)
    DI_Start_Process      : BOOL;
    DI_Stop_Process       : BOOL;
    DI_CIP_Mode           : BOOL; // Clean in Place mode selector
    DI_FDV_Pos_Forward    : BOOL; // Flow Diversion Valve forward position switch
    DI_FDV_Pos_Divert     : BOOL; // Flow Diversion Valve divert position switch
    DI_Booster_Pump_Run   : BOOL; // Booster pump running feedback

    // Process Setpoints
    SP_Legal_Pasteurize_Temp : REAL := 72.0; // Minimum legal pasteurization temperature (Deg C)
    SP_Holding_Time_Sec      : REAL := 15.0; // Minimum legal holding time (Seconds)
    SP_Min_Flow_Rate         : REAL := 1000.0; // Minimum flow rate for residence time
    SP_Min_Diff_Pressure     : REAL := 15.0; // Minimum diff pressure pasteurized vs raw (kPa)
END_VAR

VAR_OUTPUT
    // Digital Outputs (Physical)
    DO_FDV_Command_Forward : BOOL; // Command FDV to forward flow
    DO_FDV_Command_Divert  : BOOL; // Command FDV to divert flow
    DO_Booster_Pump_Start  : BOOL; // Command booster pump start
    DO_Heater_Steam_Valve  : REAL; // PID output to steam control valve (0-100%)
    DO_Cooling_Water_Valve : REAL; // PID output to cooling valve (0-100%)
    DO_System_Alarm        : BOOL; // General alarm light/horn
    DO_Legal_Record_Enable : BOOL; // Enable legal chart recorder

    // Status Outputs
    Stat_Current_State     : INT; // 0=Off, 1=Water Start, 2=Sub-Legal, 3=Legal Forward, 4=Divert, 5=CIP
    Stat_Lethality_Value   : REAL; // Calculated F0 / Pasteurization Units (PU)
    Stat_Alarm_Code        : INT; // Active alarm code
END_VAR

VAR
    // Internal State
    State_Machine : INT := 0;
    Legal_Timer : TON;
    Divert_Timer : TON;
    Alarm_Timer : TON;
    PID_Heater : FB_PID_Controller;

    bIsLegalTemp : BOOL;
    bIsLegalFlow : BOOL;
    bIsLegalPressure : BOOL;
    bSystemHealthy : BOOL;

    // Constants for states
    STATE_OFF       : INT := 0;
    STATE_WATER_RUN : INT := 1;
    STATE_SUB_LEGAL : INT := 2;
    STATE_FORWARD   : INT := 3;
    STATE_DIVERT    : INT := 4;
    STATE_CIP       : INT := 5;

    // PU Calculation variables
    PU_Accumulator : REAL := 0.0;
    PU_Rate : REAL := 0.0;
    Ref_Temp : REAL := 70.0;
    Z_Value : REAL := 10.0;
    Scan_Time : REAL := 0.1; // 100ms task
END_VAR

(* --- HTST Pasteurizer Control Logic Execution --- *)

// 1. Condition Monitoring & Safety Interlocks
bIsLegalTemp := (AI_Temp_Holding_Tube >= SP_Legal_Pasteurize_Temp);
bIsLegalFlow := (AI_Flow_Rate >= SP_Min_Flow_Rate) AND (AI_Flow_Rate <= (SP_Min_Flow_Rate * 1.5));
bIsLegalPressure := (AI_Diff_Pressure >= SP_Min_Diff_Pressure);

bSystemHealthy := NOT DI_Stop_Process AND DI_Booster_Pump_Run;

// 2. Legal Timer evaluation (Residence time verification)
// The fluid must be at legal temperature for the legal time before forward flow is permitted.
Legal_Timer(IN:= bIsLegalTemp AND bIsLegalFlow, PT:= REAL_TO_TIME(SP_Holding_Time_Sec * 1000.0));

// 3. Main State Machine
CASE State_Machine OF
    STATE_OFF:
        DO_FDV_Command_Forward := FALSE;
        DO_FDV_Command_Divert := TRUE;
        DO_Booster_Pump_Start := FALSE;
        DO_Heater_Steam_Valve := 0.0;
        Stat_Current_State := STATE_OFF;

        IF DI_Start_Process AND NOT DI_CIP_Mode THEN
            State_Machine := STATE_WATER_RUN;
        ELSIF DI_Start_Process AND DI_CIP_Mode THEN
            State_Machine := STATE_CIP;
        END_IF;

    STATE_WATER_RUN:
        DO_Booster_Pump_Start := TRUE;
        DO_FDV_Command_Forward := FALSE;
        DO_FDV_Command_Divert := TRUE;

        IF bSystemHealthy AND AI_Flow_Rate > 100.0 THEN
            State_Machine := STATE_SUB_LEGAL;
        END_IF;
        IF NOT bSystemHealthy THEN State_Machine := STATE_OFF; END_IF;

    STATE_SUB_LEGAL:
        // Fluid is circulating in divert mode while heating up
        DO_FDV_Command_Forward := FALSE;
        DO_FDV_Command_Divert := TRUE;

        IF Legal_Timer.Q AND bIsLegalPressure THEN
            // Legal conditions met, transition to forward flow
            State_Machine := STATE_FORWARD;
        END_IF;
        IF NOT bSystemHealthy THEN State_Machine := STATE_OFF; END_IF;

    STATE_FORWARD:
        // Legal Pasteurization Mode - Forward Flow to filling/sterile tank
        DO_FDV_Command_Forward := TRUE;
        DO_FDV_Command_Divert := FALSE;
        DO_Legal_Record_Enable := TRUE;

        // Continually monitor critical limits
        IF NOT bIsLegalTemp OR NOT bIsLegalFlow OR NOT bIsLegalPressure THEN
            State_Machine := STATE_DIVERT; // Immediate divert upon loss of legal conditions
            Stat_Alarm_Code := 1001; // Loss of legal condition
        END_IF;
        IF NOT bSystemHealthy THEN State_Machine := STATE_OFF; END_IF;

    STATE_DIVERT:
        // Fault condition - valve diverts product back to balance tank
        DO_FDV_Command_Forward := FALSE;
        DO_FDV_Command_Divert := TRUE;
        DO_Legal_Record_Enable := FALSE;

        Divert_Timer(IN:= TRUE, PT:= T#5S); // Must stay in divert for at least 5s
        IF Divert_Timer.Q AND bIsLegalTemp AND bIsLegalFlow AND bIsLegalPressure THEN
            State_Machine := STATE_SUB_LEGAL; // Attempt to re-establish
            Divert_Timer(IN:= FALSE, PT:= T#5S); // Reset timer
        END_IF;
        IF NOT bSystemHealthy THEN State_Machine := STATE_OFF; END_IF;

    STATE_CIP:
        // Clean In Place Mode - overriding normal temperature interlocks for wash cycles
        DO_Booster_Pump_Start := TRUE;
        DO_FDV_Command_Forward := FALSE; // Usually pulsed by external CIP skid
        DO_FDV_Command_Divert := TRUE;

        IF NOT DI_CIP_Mode THEN
            State_Machine := STATE_OFF;
        END_IF;
END_CASE;

// 4. Pasteurization Unit (PU) Accumulator Calculation
// Calculates accumulated lethality based on real-time holding tube temperature
IF State_Machine = STATE_FORWARD OR State_Machine = STATE_SUB_LEGAL THEN
    IF AI_Temp_Holding_Tube > Ref_Temp THEN
        PU_Rate := 10.0 ** ((AI_Temp_Holding_Tube - Ref_Temp) / Z_Value);
        PU_Accumulator := PU_Accumulator + (PU_Rate * (Scan_Time / 60.0));
    END_IF;
ELSE
    PU_Accumulator := 0.0;
END_IF;
Stat_Lethality_Value := PU_Accumulator;

// 5. PID Control for Steam Heater
// Modulates steam valve to maintain legal pasteurization setpoint
PID_Heater(
    Enable := (State_Machine <> STATE_OFF),
    Setpoint := SP_Legal_Pasteurize_Temp + 1.5, // Add 1.5C buffer above legal limit
    ProcessValue := AI_Temp_Heater_Out,
    Kp := 2.5,
    Ki := 0.05,
    Kd := 0.1,
    Output => DO_Heater_Steam_Valve
);

// 6. Alarming
DO_System_Alarm := (Stat_Alarm_Code > 0) OR (State_Machine = STATE_DIVERT AND NOT DI_CIP_Mode);

END_FUNCTION_BLOCK
