\nFUNCTION_BLOCK FB_WEC_Control
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // System enable
    bStormMode : BOOL; // Storm survivability mode trigger
    fWaveHeight : REAL; // Current wave height in meters
    fWavePeriod : REAL; // Current wave period in seconds
    fWavePhase : REAL; // Current wave phase in radians
    fPTO_Position : REAL; // PTO actuator position in meters
    fPTO_Velocity : REAL; // PTO actuator velocity in m/s
    fPTO_Pressure_HP : REAL; // High pressure accumulator pressure in bar
    fPTO_Pressure_LP : REAL; // Low pressure accumulator pressure in bar
    fGridVoltage : REAL; // Grid voltage in Volts
    fGridFrequency : REAL; // Grid frequency in Hz
END_VAR

VAR_OUTPUT
    fPTO_DampingForce : REAL; // Requested damping force in kN
    fPTO_ValveCommand : REAL; // Proportional valve command 0-100%
    bLatchingEngaged : BOOL; // Latching mechanism status
    bGridDisconnect : BOOL; // Grid disconnection signal
    bStormLatchEngaged : BOOL; // Storm latching mechanism status
    iSystemState : INT; // Current system state
END_VAR

VAR
    fOptimalDamping : REAL; // Calculated optimal damping coefficient
    fPhaseError : REAL; // Phase error between wave and PTO
    fPowerAvailable : REAL; // Estimated available wave power
    fPowerGenerated : REAL; // Current generated power
    tLatchingTimer : TON; // Timer for latching phase control
    tStormTimer : TON; // Timer for storm mode deactivation
    bPhaseAligning : BOOL; // Internal phase alignment state
    fIntegralError : REAL; // Integral error for PI control
    fPrevError : REAL; // Previous error for PI control
END_VAR

VAR CONSTANT
    C_WATER_DENSITY : REAL := 1025.0; // kg/m^3
    C_GRAVITY : REAL := 9.81; // m/s^2
    C_MAX_DAMPING : REAL := 5000.0; // Max allowable damping kN/(m/s)
    C_MAX_WAVE_HEIGHT : REAL := 8.0; // Max wave height before storm mode
    C_LATCHING_THRESHOLD : REAL := 0.1; // Velocity threshold for latching
    PI : REAL := 3.14159265359;
END_VAR

// State Machine Constants
VAR CONSTANT
    STATE_INIT : INT := 0;
    STATE_STANDBY : INT := 1;
    STATE_ACTIVE_CONTROL : INT := 2;
    STATE_STORM_SURVIVABILITY : INT := 3;
    STATE_FAULT : INT := 4;
END_VAR

// WEC Control Logic
IF NOT bEnable THEN
    iSystemState := STATE_INIT;
    fPTO_DampingForce := 0.0;
    fPTO_ValveCommand := 0.0;
    bLatchingEngaged := FALSE;
    bStormLatchEngaged := FALSE;
    bGridDisconnect := TRUE;
    fIntegralError := 0.0;
    RETURN;
END_IF;

// Grid condition check
IF (fGridVoltage < 380.0) OR (fGridVoltage > 440.0) OR (fGridFrequency < 49.0) OR (fGridFrequency > 51.0) THEN
    bGridDisconnect := TRUE;
ELSE
    bGridDisconnect := FALSE;
END_IF;

// Automatic Storm Mode Trigger
IF (fWaveHeight > C_MAX_WAVE_HEIGHT) OR bStormMode THEN
    iSystemState := STATE_STORM_SURVIVABILITY;
END_IF;

CASE iSystemState OF
    STATE_INIT:
        // Initialization procedures
        IF bEnable AND (fPTO_Pressure_HP > 100.0) THEN
            iSystemState := STATE_STANDBY;
        END_IF;

    STATE_STANDBY:
        // Ready for operation
        IF fWaveHeight > 0.5 THEN
            iSystemState := STATE_ACTIVE_CONTROL;
        END_IF;

    STATE_ACTIVE_CONTROL:
        // Active Phase Control and Damping Matrix Calculation
        // Estimate optimal damping based on wave period
        IF fWavePeriod > 0.0 THEN
            fOptimalDamping := (C_WATER_DENSITY * C_GRAVITY * fWaveHeight * fWaveHeight * fWavePeriod) / (32.0 * PI);
        ELSE
            fOptimalDamping := 0.0;
        END_IF;

        // Limit damping to safe values
        IF fOptimalDamping > C_MAX_DAMPING THEN
            fOptimalDamping := C_MAX_DAMPING;
        END_IF;

        // Phase control - Latching strategy
        // Latch when velocity is near zero and phase needs to catch up
        IF ABS(fPTO_Velocity) < C_LATCHING_THRESHOLD THEN
            fPhaseError := fWavePhase - (PI/2.0); // Desired phase shift for resonance
            IF fPhaseError < 0.0 THEN
                fPhaseError := fPhaseError + 2.0 * PI;
            END_IF;

            // Latch if waiting for wave peak
            IF (fPhaseError > 0.1) AND (fPhaseError < PI) THEN
                bLatchingEngaged := TRUE;
                fPTO_DampingForce := C_MAX_DAMPING; // Maximum holding force
            ELSE
                bLatchingEngaged := FALSE;
            END_IF;
        ELSE
            bLatchingEngaged := FALSE;
        END_IF;

        // Normal damping calculation if not latched
        IF NOT bLatchingEngaged THEN
            fPTO_DampingForce := fOptimalDamping * fPTO_Velocity;
        END_IF;

        // PTO Valve command generation (PI Controller)
        fPrevError := fOptimalDamping - (fPTO_Pressure_HP - fPTO_Pressure_LP) / 10.0; // Simplified pressure drop model
        fIntegralError := fIntegralError + fPrevError * 0.01; // Assuming 10ms cycle time

        fPTO_ValveCommand := (0.5 * fPrevError) + (0.1 * fIntegralError);

        // Saturation limit
        IF fPTO_ValveCommand > 100.0 THEN
            fPTO_ValveCommand := 100.0;
            fIntegralError := fIntegralError - fPrevError * 0.01; // Anti-windup
        ELSIF fPTO_ValveCommand < 0.0 THEN
            fPTO_ValveCommand := 0.0;
            fIntegralError := fIntegralError - fPrevError * 0.01; // Anti-windup
        END_IF;

    STATE_STORM_SURVIVABILITY:
        // Lock the device to prevent damage during extreme weather
        fPTO_DampingForce := C_MAX_DAMPING;
        fPTO_ValveCommand := 0.0; // Close valves
        bLatchingEngaged := TRUE;
        bStormLatchEngaged := TRUE;

        // Storm mode recovery timer
        tStormTimer(IN := (fWaveHeight < (C_MAX_WAVE_HEIGHT * 0.8)) AND NOT bStormMode, PT := T#30M);
        IF tStormTimer.Q THEN
            bStormLatchEngaged := FALSE;
            iSystemState := STATE_STANDBY;
        END_IF;

    STATE_FAULT:
        // Fault state handling
        fPTO_DampingForce := 0.0;
        fPTO_ValveCommand := 0.0;
        bLatchingEngaged := FALSE;
        bStormLatchEngaged := TRUE; // mechanical brake
END_CASE;
END_FUNCTION_BLOCK\n```
