FUNCTION_BLOCK FB_JacquardLoomControl
VAR_INPUT
    bEnable : BOOL; // Enable loom control
    rMachineSpeed_RPM : REAL; // Target machine speed in RPM
    rMainShaftAngle_Deg : REAL; // Absolute angle of the main shaft (0-360)
    bWeftInsertionTrigger : BOOL; // Trigger for weft insertion
    rWarpTension_N : REAL; // Measured warp tension in Newtons
    aPatternData : ARRAY[0..1023] OF WORD; // 16-bit word array representing solenoid states for jacquard hooks
END_VAR

VAR_OUTPUT
    bReady : BOOL; // System ready for operation
    rLetOffSpeed_RPM : REAL; // Commanded speed for the let-off beam motor
    rTakeUpSpeed_RPM : REAL; // Commanded speed for the take-up roller motor
    aHookSolenoids : ARRAY[0..16383] OF BOOL; // Outputs to individual jacquard hook solenoids
    bRapierLeftDrive : BOOL; // Command for left rapier drive
    bRapierRightDrive : BOOL; // Command for right rapier drive
    rWeftTension_N : REAL; // Estimated weft tension
    bError : BOOL;
    iErrorCode : INT;
END_VAR

VAR
    // Internal State Machine
    iState : INT := 0;

    // PID Controller for Warp Tension
    rTensionSetpoint : REAL := 1500.0; // Target tension in N
    rTensionError : REAL;
    rTensionIntegral : REAL := 0.0;
    rTensionDerivative : REAL := 0.0;
    rTensionLastError : REAL := 0.0;
    rKp : REAL := 0.05;
    rKi : REAL := 0.01;
    rKd : REAL := 0.005;

    // Kinematics and Timing
    rRapierInsertionAngleStart : REAL := 70.0;
    rRapierInsertionAngleEnd : REAL := 290.0;
    bInInsertionPhase : BOOL;

    // Pattern decoding
    iPatternIndex : INT;
    iBitIndex : INT;
    iHookIndex : INT;

    // Safety and Monitoring
    tStopWatchdog : TON;
END_VAR

// -----------------------------------------------------------------------------
// MAIN CONTROL LOGIC
// -----------------------------------------------------------------------------

// 1. State Management
CASE iState OF
    0: // INIT
        bReady := FALSE;
        bError := FALSE;
        iErrorCode := 0;
        rLetOffSpeed_RPM := 0.0;
        rTakeUpSpeed_RPM := 0.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: // READY
        bReady := TRUE;
        IF rMachineSpeed_RPM > 0.0 THEN
            iState := 20;
        END_IF;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: // RUNNING
        bReady := TRUE;

        // ---------------------------------------------------------------------
        // ACTIVE WARP TENSION CONTROL (LET-OFF / TAKE-UP)
        // ---------------------------------------------------------------------
        rTensionError := rTensionSetpoint - rWarpTension_N;
        rTensionIntegral := rTensionIntegral + (rTensionError * 0.01); // Assuming 10ms task cycle
        rTensionDerivative := (rTensionError - rTensionLastError) / 0.01;

        // Anti-windup
        IF rTensionIntegral > 50.0 THEN rTensionIntegral := 50.0; END_IF;
        IF rTensionIntegral < -50.0 THEN rTensionIntegral := -50.0; END_IF;

        rLetOffSpeed_RPM := (rMachineSpeed_RPM * 0.1) + (rTensionError * rKp) + (rTensionIntegral * rKi) + (rTensionDerivative * rKd);
        rTakeUpSpeed_RPM := (rMachineSpeed_RPM * 0.1); // Proportional to main speed

        rTensionLastError := rTensionError;

        // ---------------------------------------------------------------------
        // JACQUARD HOOK SELECTION (SHEDDING)
        // ---------------------------------------------------------------------
        // Shedding logic is highly dependent on main shaft angle (e.g., 300 to 60 degrees)
        IF (rMainShaftAngle_Deg > 300.0) OR (rMainShaftAngle_Deg < 60.0) THEN
            // Decode pattern data into individual solenoid outputs
            iHookIndex := 0;
            FOR iPatternIndex := 0 TO 1023 DO
                FOR iBitIndex := 0 TO 15 DO
                    aHookSolenoids[iHookIndex] := (aPatternData[iPatternIndex] AND SHL(WORD#1, iBitIndex)) > 0;
                    iHookIndex := iHookIndex + 1;
                END_FOR;
            END_FOR;
        END_IF;

        // ---------------------------------------------------------------------
        // RAPIER WEFT INSERTION KINEMATICS
        // ---------------------------------------------------------------------
        bInInsertionPhase := (rMainShaftAngle_Deg >= rRapierInsertionAngleStart) AND (rMainShaftAngle_Deg <= rRapierInsertionAngleEnd);

        IF bInInsertionPhase AND bWeftInsertionTrigger THEN
            // Left rapier brings the yarn to the center
            IF rMainShaftAngle_Deg < 180.0 THEN
                bRapierLeftDrive := TRUE;
                bRapierRightDrive := FALSE;
            // Right rapier picks up and completes insertion
            ELSE
                bRapierLeftDrive := FALSE;
                bRapierRightDrive := TRUE;
            END_IF;
        ELSE
            bRapierLeftDrive := FALSE;
            bRapierRightDrive := FALSE;
        END_IF;

        // ---------------------------------------------------------------------
        // ERROR HANDLING
        // ---------------------------------------------------------------------
        IF rWarpTension_N > 3000.0 THEN
            bError := TRUE;
            iErrorCode := 101; // Over tension
            iState := 99; // FAULT
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: // FAULT
        bReady := FALSE;
        rLetOffSpeed_RPM := 0.0;
        rTakeUpSpeed_RPM := 0.0;
        bRapierLeftDrive := FALSE;
        bRapierRightDrive := FALSE;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
