FUNCTION_BLOCK FB_DUV_ImmersionStepper_Control
VAR_INPUT
    (* Safety & Enable *)
    bSystemEnable       : BOOL;     (* Main system enable for DUV stepper *)
    bEStop_OK           : BOOL;     (* Safety relay healthy *)

    (* Laser Subsystem *)
    rLaserPulseEnergyFB : REAL;     (* Feedback from ArF excimer laser energy monitor (mJ) *)
    bLaserReady         : BOOL;     (* Laser cooling & gas mixture ready *)

    (* Immersion Fluidics *)
    rMeniscusPressureFB : REAL;     (* UPW meniscus confinement pressure (kPa) *)
    rMeniscusFlowFB     : REAL;     (* UPW flow rate (L/min) *)

    (* Stage Interferometry *)
    rStageX_PosError    : LREAL;    (* Interferometer X-axis positioning error (nm) *)
    rStageY_PosError    : LREAL;    (* Interferometer Y-axis positioning error (nm) *)
    rStageZ_PosError    : LREAL;    (* Interferometer Z-axis focus error (nm) *)
END_VAR
VAR_OUTPUT
    (* Status & Alarms *)
    bSystemReady        : BOOL;     (* Stepper ready for exposure sequence *)
    bCriticalAlarm      : BOOL;     (* Immediate abort condition active *)
    iFaultCode          : INT;      (* Diagnostics fault code *)

    (* Control Signals *)
    rLaserDoseCmd       : REAL;     (* Commanded pulse energy (mJ) *)
    rUPW_PumpSpeedCmd   : REAL;     (* UPW pump drive signal (0-100%) *)
    rStageLevitationCmd : REAL;     (* Magnetic levitation Z-force command (N) *)
END_VAR
VAR
    (* State Management *)
    iState              : INT := 0;

    (* Timers & Filters *)
    tFluidicsStabTimer  : TON;
    tLaserWarmupTimer   : TON;
    rPressureFilt       : REAL := 0.0;

    (* PID & Mathematical constants *)
    rKp_Laser           : REAL := 1.2;
    rKi_Laser           : REAL := 0.5;
    rLaserIntError      : REAL := 0.0;

    rNominalPressure    : REAL := 15.5; (* kPa nominal UPW meniscus pressure *)
END_VAR

(* === MAIN LOGIC: DUV LITHOGRAPHY IMMERSION STEPPER CONTROL === *)

(* 1. Safety Interlocks & E-Stop *)
IF NOT bEStop_OK THEN
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    iFaultCode := 9999; (* E-STOP TRIGGERED *)

    (* Safe state enforcement *)
    rLaserDoseCmd := 0.0;
    rUPW_PumpSpeedCmd := 0.0;
    rStageLevitationCmd := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* 2. Sensor Filtering *)
(* Single pole IIR filter for UPW meniscus pressure to attenuate high-frequency pump ripple *)
rPressureFilt := rPressureFilt + 0.1 * (rMeniscusPressureFB - rPressureFilt);

(* 3. State Machine Control Sequence *)
CASE iState OF
    0: (* INIT: Wait for enable *)
        bSystemReady := FALSE;
        bCriticalAlarm := FALSE;
        iFaultCode := 0;
        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* WARMUP: Laser preparation *)
        tLaserWarmupTimer(IN := TRUE, PT := T#10S);
        IF tLaserWarmupTimer.Q AND bLaserReady THEN
            tLaserWarmupTimer(IN := FALSE);
            iState := 20;
        ELSIF tLaserWarmupTimer.Q AND NOT bLaserReady THEN
            iFaultCode := 101; (* Laser failed to reach ready state *)
            bCriticalAlarm := TRUE;
            iState := 999;
        END_IF;

    20: (* FLUIDICS: Establish UPW Meniscus *)
        (* Basic P-control for meniscus formation *)
        rUPW_PumpSpeedCmd := 50.0 + (rNominalPressure - rPressureFilt) * 2.5;

        (* Clamp pump speed *)
        IF rUPW_PumpSpeedCmd > 100.0 THEN
            rUPW_PumpSpeedCmd := 100.0;
        ELSIF rUPW_PumpSpeedCmd < 20.0 THEN
            rUPW_PumpSpeedCmd := 20.0;
        END_IF;

        tFluidicsStabTimer(IN := (ABS(rNominalPressure - rPressureFilt) < 0.5), PT := T#3S);
        IF tFluidicsStabTimer.Q THEN
            tFluidicsStabTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* EXPOSURE READY: Stage levitation and Laser Control *)
        bSystemReady := TRUE;

        (* Levitation compensation based on Z focus error *)
        rStageLevitationCmd := 98.1 + (LREAL_TO_REAL(rStageZ_PosError) * 0.005);

        (* Active PID control for Laser Dose *)
        rLaserIntError := rLaserIntError + (10.0 - rLaserPulseEnergyFB) * 0.01; 
        IF rLaserIntError > 5.0 THEN rLaserIntError := 5.0; END_IF;
        IF rLaserIntError < -5.0 THEN rLaserIntError := -5.0; END_IF;

        rLaserDoseCmd := (10.0 - rLaserPulseEnergyFB) * rKp_Laser + rLaserIntError * rKi_Laser;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rLaserDoseCmd := 0.0;
        rUPW_PumpSpeedCmd := 0.0;
        IF NOT bSystemEnable THEN
            bCriticalAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
