    Azimuth_Cmd : REAL;                (* Commanded beam azimuth (degrees) *)
    Elevation_Cmd : REAL;              (* Commanded beam elevation (degrees) *)
    Raw_IF_Signal : ARRAY[0..255] OF LREAL; (* Digitized IF returns (Fast-time samples) *)
