    Target_Detected : BOOL;            (* High-confidence track established *)
    Target_Range : LREAL;              (* Meters *)
    Target_Velocity : LREAL;           (* Meters/second *)
    Target_RCS : LREAL;                (* Estimated Radar Cross-Section (m^2) *)
    Spark_Gap_Active : BOOL;           (* True when EMP ground shunt is engaged *)
    System_Fault : BOOL;               (* General fault flag *)
