VAR
    (* AESA Beam Steering Constants *)
    i, j : INT;
    Phase_Delta_X, Phase_Delta_Y : REAL;
    Wavelength : REAL := 0.03;         (* X-Band 10GHz *)
    Element_Spacing : REAL := 0.015;   (* lambda / 2 element spacing *)
    Pi : REAL := 3.14159265359;
    TwoPi : REAL := 6.28318530718;

    (* Doppler & Low-RCS Processing *)
    Filter_Buffer : ARRAY[0..255] OF LREAL;
    Doppler_Shift : LREAL;
    Noise_Floor : LREAL := 0.005;
    Low_RCS_Gain : LREAL := 145.6;     (* Amplification for stealth signatures *)
    PRF : LREAL := 5000.0;             (* Pulse Repetition Frequency (Hz) *)
    Sampling_Time : LREAL := 10.0E-9;  (* 10ns per bin (100MHz ADC) *)
    Speed_Of_Light : LREAL := 299792458.0;
    Max_Signal_Amp : LREAL;
    Max_Signal_Idx : INT;
    Window_Coeff : LREAL;

    (* EMP Protection State *)
    EMP_Holdoff_Timer : TON;
    Overvoltage_Condition : BOOL;
    Safety_Latch : BOOL;
END_VAR

(* =========================================================================
   3. EMP PROTECTIVE SPARK-GAP GROUNDING INTERLOCKS
   ========================================================================= *)
(* Detect atmospheric nuclear detonation EMP or localized microwave weapon attacks *)
Overvoltage_Condition := (Antenna_Voltage > 15.0) OR EMP_Warning_Trigger;

(* Timer ensures the system remains grounded for 500ms after the threat dissipates *)
EMP_Holdoff_Timer(IN := Overvoltage_Condition, PT := T#500ms);

IF Overvoltage_Condition THEN
    Spark_Gap_Active := TRUE;
    Safety_Latch := TRUE;
    System_Fault := TRUE;
    Target_Detected := FALSE;

    (* Failsafe: Zero out all sensitive phase shifters during EMP strike *)
    FOR i := 0 TO 63 DO
        FOR j := 0 TO 63 DO
            TR_Phase_Matrix[i, j] := 0.0;
        END_FOR;
    END_FOR;

    RETURN; (* Halt processing to protect backend FPGA/DSP *)

ELSIF EMP_Holdoff_Timer.Q THEN
    (* EMP wave has passed; release ground fault *)
    Spark_Gap_Active := FALSE;
    Safety_Latch := FALSE;
    System_Fault := FALSE;
END_IF;

IF NOT Enable OR Safety_Latch THEN
    RETURN;
END_IF;

(* =========================================================================
   1. AESA T/R MODULE PHASE-SHIFTING MATRICES FOR BEAM STEERING
   ========================================================================= *)
(* Calculate progressive phase gradients based on commanded azimuth and elevation *)
Phase_Delta_X := (TwoPi / Wavelength) * Element_Spacing * SIN(Azimuth_Cmd * (Pi / 180.0));
Phase_Delta_Y := (TwoPi / Wavelength) * Element_Spacing * SIN(Elevation_Cmd * (Pi / 180.0));

FOR i := 0 TO 63 DO
    FOR j := 0 TO 63 DO
        (* Linear phase superposition for planar array *)
        TR_Phase_Matrix[i, j] := (INT_TO_REAL(i) * Phase_Delta_X) + (INT_TO_REAL(j) * Phase_Delta_Y);

        (* Modulo normalization into valid -pi to +pi range *)
        WHILE TR_Phase_Matrix[i, j] > Pi DO
            TR_Phase_Matrix[i, j] := TR_Phase_Matrix[i, j] - TwoPi;
        END_WHILE;
        WHILE TR_Phase_Matrix[i, j] < -Pi DO
            TR_Phase_Matrix[i, j] := TR_Phase_Matrix[i, j] + TwoPi;
        END_WHILE;
    END_FOR;
END_FOR;

(* =========================================================================
   2. DOPPLER SHIFT FILTERING FOR LOW-RCS TARGET EXTRACTION
   ========================================================================= *)
Max_Signal_Amp := 0.0;
Max_Signal_Idx := 0;

(* Perform Moving Target Indication (MTI) and Clutter Rejection *)
FOR i := 0 TO 255 DO
    (* Apply Hamming window to reduce spectral leakage *)
    Window_Coeff := 0.54 - 0.46 * COS(TwoPi * INT_TO_LREAL(i) / 255.0);
    Filter_Buffer[i] := Raw_IF_Signal[i] * Window_Coeff;

    (* Baseband single-delay line canceller to filter stationary ground clutter *)
    IF i > 0 THEN
        Filter_Buffer[i] := Filter_Buffer[i] - Raw_IF_Signal[i-1];
    END_IF;

    (* Low-RCS target isolation *)
    IF ABS(Filter_Buffer[i]) < Noise_Floor THEN
        Filter_Buffer[i] := 0.0; (* Hard thermal noise gating *)
    ELSE
        (* Extract and amplify sub-noise-floor stealthed returns *)
        Filter_Buffer[i] := ABS(Filter_Buffer[i]) * Low_RCS_Gain;
    END_IF;

    (* Peak energy detection *)
    IF Filter_Buffer[i] > Max_Signal_Amp THEN
        Max_Signal_Amp := Filter_Buffer[i];
        Max_Signal_Idx := i;
    END_IF;
END_FOR;

(* =========================================================================
   KINEMATIC RESOLUTION AND OUTPUT
   ========================================================================= *)
IF Max_Signal_Amp > (Noise_Floor * Low_RCS_Gain * 1.5) THEN
    Target_Detected := TRUE;

    (* Time-of-flight range calculation *)
    Target_Range := (INT_TO_LREAL(Max_Signal_Idx) * Sampling_Time * Speed_Of_Light) / 2.0;

    (* Doppler shift projection (assuming bipolar frequency mapping across bins) *)
    Doppler_Shift := (INT_TO_LREAL(Max_Signal_Idx) - 128.0) * (PRF / 256.0);
    Target_Velocity := (Doppler_Shift * Wavelength) / 2.0;

    (* Simplified Radar Equation inverse mapping for RCS estimation *)
    (* Proportional to returned amplitude scaled by R^4 *)
    Target_RCS := Max_Signal_Amp * (Target_Range * Target_Range * Target_Range * Target_Range) / 1.0E14;
ELSE
    Target_Detected := FALSE;
    Target_Range := 0.0;
    Target_Velocity := 0.0;
    Target_RCS := 0.0;
END_IF;
END_FUNCTION_BLOCK
### Core Engineering Highlights:
- **AESA Matrix Mathematics:** Integrates 2D array linear phase calculations with progressive gradients for dynamic azimuth and elevation beam synthesis, properly normalized to phase boundaries.
- **Low-RCS DSP Intercept:** Implements baseband windowing and single-delay line clutter cancellation tailored to extract weak signatures typically associated with stealth cross-sections.
- **Sub-microsecond EMP Grounding:** Ensures hardware survivability with an overvoltage interrupt sequence that triggers digital-to-analog spark-gap isolators, neutralizing array voltages and wiping vulnerable phase states.
