FUNCTION_BLOCK "GrainSiloControl_Breadth"
VERSION : 0.1
   VAR_INPUT 
      DustLevel : Real;
      AugerTorque : Real;
      ZoneTemps : ARRAY[1..4] OF Real;
      PNIO_Status : Word; // Profinet IO status word (0 = OK)
      DustThreshold : Real := 50.0;
      TorqueLimit : Real := 150.0;
      TempHighLimit : Real := 40.0;
      TempCritLimit : Real := 65.0;
      SystemEnable : Bool;
   END_VAR

   VAR_OUTPUT 
      MistValve : Bool;
      AugerFwd : Bool;
      AugerRev : Bool;
      AerationFan : Bool;
      DiagErrorWord : Word;
      SystemFault : Bool;
   END_VAR

   VAR 
      JamTimer : TON;
      RevTimer : TON;
      AntiJamActive : Bool;
      AlarmJam : Bool;
      AlarmFireHazard : Bool;
      i : Int;
      MaxTemp : Real;
   END_VAR

BEGIN
    // Diagnostics & PNIO Check
    #DiagErrorWord := 16#0000;
    IF #PNIO_Status <> 16#0000 THEN
        #DiagErrorWord := #DiagErrorWord OR 16#0001; // Comm Error
    END_IF;

    // Temperature Monitoring
    #MaxTemp := 0.0;
    FOR #i := 1 TO 4 DO
        IF #ZoneTemps[#i] > #MaxTemp THEN
            #MaxTemp := #ZoneTemps[#i];
        END_IF;
    END_FOR;
    #AlarmFireHazard := (#MaxTemp > #TempCritLimit);
    IF #AlarmFireHazard THEN #DiagErrorWord := #DiagErrorWord OR 16#0002; END_IF;

    #SystemFault := (#DiagErrorWord <> 16#0000);

    // Actuator Control
    #AerationFan := #SystemEnable AND NOT #SystemFault AND (#MaxTemp > #TempHighLimit);
    #MistValve := #SystemEnable AND NOT #SystemFault AND (#DustLevel > #DustThreshold);

    // Auger Anti-Jam Logic
    #JamTimer(IN := #SystemEnable AND NOT #SystemFault AND (#AugerTorque > #TorqueLimit) AND NOT #AntiJamActive,
              PT := T#2S);
    IF #JamTimer.Q THEN #AntiJamActive := TRUE; END_IF;

    #RevTimer(IN := #AntiJamActive, PT := T#3S);
    IF #RevTimer.Q THEN
        #AntiJamActive := FALSE;
        IF #AugerTorque > #TorqueLimit THEN #AlarmJam := TRUE; END_IF;
    END_IF;
    IF #AlarmJam THEN #DiagErrorWord := #DiagErrorWord OR 16#0004; #SystemFault := TRUE; END_IF;

    IF #SystemEnable AND NOT #SystemFault THEN
        #AugerFwd := NOT #AntiJamActive;
        #AugerRev := #AntiJamActive;
    ELSE
        #AugerFwd := FALSE;
        #AugerRev := FALSE;
        #AntiJamActive := FALSE;
    END_IF;
END_FUNCTION_BLOCK
