```iec-st
FUNCTION_BLOCK FB_CCC_Desublimation_Control
VAR_INPUT
    bSystemEnable           : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (Normally Closed loop) *)
    rFlueGasFlowRate        : REAL;     (* Inlet flue gas flow rate (kg/s) *)
    rDesublimatorTemp       : REAL;     (* Desublimator internal temperature (deg C) *)
    rRefrigerantPressure    : REAL;     (* Mixed refrigerant circuit pressure (bar) *)
    rSolidCO2Level          : REAL;     (* Solid CO2 accumulation thickness sensor (mm) *)
    rMeltingLoopTemp        : REAL;     (* Temperature of the melting loop (deg C) *)
    bDefrostRequest         : BOOL;     (* Manual or upstream request to trigger defrost/melt phase *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for active desublimation *)
    rRefrigerantCompressor  : REAL;     (* Compressor speed command (0.0 to 100.0 %) *)
    rFlueGasInletValve      : REAL;     (* Position command for flue gas inlet (0.0 to 100.0 %) *)
    bMeltingHeaterEnable    : BOOL;     (* Enable signal for CO2 melt loop heaters *)
    bAlarmState             : BOOL;     (* General fault alarm output *)
    iOperatingMode          : INT;      (* Current operating mode (0=Off, 1=Cooling, 2=Desublimation, 3=Melting) *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine step *)
    tCoolingTimer           : TON;      (* Timer for cooling phase stabilization *)
    tMeltingTimer           : TON;      (* Timer for melting phase duration *)
    rErrorTemp              : REAL;     (* Temperature error for PI control *)
    rIntegralTemp           : REAL;     (* Integral accumulator for temperature control *)
    rKp                     : REAL := 2.5; (* Proportional gain for compressor *)
    rKi                     : REAL := 0.1; (* Integral gain for compressor *)
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlock: Emergency Stop overrides all operations *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bMeltingHeaterEnable := FALSE;
    rRefrigerantCompressor := 0.0;
    rFlueGasInletValve := 0.0;
    bAlarmState := TRUE;
    iState := 99; (* Fault state *)
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE & SYSTEM CHECKS *)
        bSystemReady := FALSE;
        bMeltingHeaterEnable := FALSE;
        rRefrigerantCompressor := 0.0;
        rFlueGasInletValve := 0.0;
        bAlarmState := FALSE;
        iOperatingMode := 0;
        rIntegralTemp := 0.0;

        IF bSystemEnable THEN
            iState := 10; (* Move to Cooling/Preparation *)
        END_IF;

    10: (* COOLING DOWN DESUBLIMATOR *)
        iOperatingMode := 1;
        (* Start compressor at safe minimum load *)
        rRefrigerantCompressor := 40.0; 

        (* Check if temperature is reaching target cryogenic level (e.g., -120 C) *)
        IF rDesublimatorTemp <= -120.0 THEN
            tCoolingTimer(IN := TRUE, PT := T#30S);
            IF tCoolingTimer.Q THEN
                tCoolingTimer(IN := FALSE);
                bSystemReady := TRUE;
                iState := 20; (* Move to Active Desublimation *)
            END_IF;
        ELSE
            tCoolingTimer(IN := FALSE);
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* ACTIVE DESUBLIMATION / CARBON CAPTURE *)
        iOperatingMode := 2;
        bSystemReady := TRUE;

        (* PI Control for Refrigerant Compressor to maintain -125 C *)
        rErrorTemp := rDesublimatorTemp - (-125.0);
        rIntegralTemp := rIntegralTemp + (rErrorTemp * 0.1); (* Assuming 100ms task rate approx *)

        (* Anti-windup for integral term *)
        IF rIntegralTemp > 50.0 THEN rIntegralTemp := 50.0; END_IF;
        IF rIntegralTemp < -50.0 THEN rIntegralTemp := -50.0; END_IF;

        rRefrigerantCompressor := (rErrorTemp * rKp) + rIntegralTemp + 50.0; (* Base load 50% *)

        (* Clamp compressor output *)
        IF rRefrigerantCompressor > 100.0 THEN rRefrigerantCompressor := 100.0; END_IF;
        IF rRefrigerantCompressor < 20.0 THEN rRefrigerantCompressor := 20.0; END_IF;

        (* Open Flue Gas Valve proportional to flow demand, if safe *)
        IF rRefrigerantPressure < 15.0 THEN
            rFlueGasInletValve := 85.0; (* Optimal opening for capture *)
        ELSE
            rFlueGasInletValve := 30.0; (* Throttle if MR pressure too high *)
        END_IF;

        (* Transition to Melting/Defrost if solid CO2 level is too high or requested *)
        IF (rSolidCO2Level > 150.0) OR bDefrostRequest THEN
            iState := 30;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    30: (* MELTING / DEFROST LOOP (SOLID TO LIQUID CO2) *)
        iOperatingMode := 3;
        bSystemReady := FALSE;
        rFlueGasInletValve := 0.0; (* Isolate flue gas *)
        rRefrigerantCompressor := 10.0; (* Minimum idle speed *)

        bMeltingHeaterEnable := TRUE; (* Activate melt loop *)

        (* Wait for temperature to rise sufficiently to melt CO2 *)
        IF rMeltingLoopTemp > -50.0 THEN
            tMeltingTimer(IN := TRUE, PT := T#2M); (* Melt holding time *)
            IF tMeltingTimer.Q THEN
                tMeltingTimer(IN := FALSE);
                bMeltingHeaterEnable := FALSE;
                IF bSystemEnable THEN
                    iState := 10; (* Return to cooling phase *)
                ELSE
                    iState := 0;
                END_IF;
            END_IF;
        ELSE
            tMeltingTimer(IN := FALSE);
        END_IF;

    99: (* FAULT STATE *)
        (* Wait for emergency stop to be reset, then transition to IDLE *)
        IF bEmergencyStop THEN
            bAlarmState := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
