FUNCTION_BLOCK "MilkPasteurizer_Profinet"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempPastOut : REAL;
    HW_IO_ValveTerminal : HW_DEVICE; // Profinet Hardware ID
END_VAR

VAR_OUTPUT
    HeaterPID_Out : REAL;
    FDV_Forward : BOOL;
    FDV_Divert : BOOL;
    ErrorCode : WORD;
    AlarmActive : BOOL;
END_VAR

VAR
    ProcessActive : BOOL;
    PID_Heater : "PID_Compact";
    TMR_Hold : TON;
    TempOk : BOOL;
    DeviceStatus : DINT;
    PN_Diag : "DeviceStates";
    DeviceFault : BOOL;
END_VAR

BEGIN
    // Profinet Device Diagnostics
    PN_Diag(
        LADDR := HW_IO_ValveTerminal,
        MODE := 2, // Check for faults
        STATE := DeviceStatus
    );
    DeviceFault := (DeviceStatus <> 0);

    // Start/Stop Logic
    IF Start AND NOT Stop AND NOT DeviceFault THEN
        ProcessActive := TRUE;
    ELSIF Stop OR DeviceFault THEN
        ProcessActive := FALSE;
    END_IF;

    // PID Loop
    PID_Heater(
        sMode := 3,
        Setpoint := 72.0,
        Input := TempPastOut,
        Output => HeaterPID_Out
    );

    // Safety Timer
    TempOk := (TempPastOut >= 72.0);
    TMR_Hold(IN := TempOk AND ProcessActive, PT := T#15S);

    // FDV Control with Profinet Safety Interlock
    IF ProcessActive AND TMR_Hold.Q AND NOT DeviceFault THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;

    // Fault Diagnostics
    IF DeviceFault THEN
        ErrorCode := 16#0001; // PN Device Fault
        AlarmActive := TRUE;
    ELSIF ProcessActive AND NOT TempOk THEN
        ErrorCode := 16#0002; // Low Temp Divert
        AlarmActive := TRUE;
    ELSE
        ErrorCode := 16#0000;
        AlarmActive := FALSE;
    END_IF;
END_FUNCTION_BLOCK
