```iec-st
Here is the mutated Siemens SCL code incorporating IEC 62443 cybersecurity, dual pump failover, and OPC UA integration:

FUNCTION_BLOCK "ChemicalDosingSafety_M3"
   VAR_INPUT 
      E_Stop : Bool;
      Tank_Level_OK : Bool;
      Flow_OK : Bool;
      Ack_Fault : Bool;
      Pump_Start_Req : Bool;
      Valve_Suction_Opened : Bool;
      Valve_Discharge_Opened : Bool;
      Profinet_Status_OK : Bool;
      User_Auth_Level : Int; // IEC 62443 Role-based access
      Pump1_Available : Bool;
      Pump2_Available : Bool;
   END_VAR
   VAR_OUTPUT 
      Pump1_Run : Bool;
      Pump2_Run : Bool;
      Fault_Active : Bool;
      Open_Suction_Valve : Bool;
      Open_Discharge_Valve : Bool;
      Diag_Code : Word;
      OPC_UA_Status : DWord; // SCADA integration mapping
   END_VAR
   VAR 
      Fault_Latch : Bool;
      Sequence_Step : Int;
      Active_Pump : Int := 1;
   END_VAR
BEGIN
    // Security check
    IF #User_Auth_Level < 2 THEN
        #Diag_Code := 16#E001; // Unauthorized access
        #Pump_Start_Req := FALSE;
    END_IF;

    // Diagnostics and Faults
    IF NOT #E_Stop THEN #Diag_Code := 16#0001; #Fault_Latch := TRUE;
    ELSIF NOT #Tank_Level_OK THEN #Diag_Code := 16#0002; #Fault_Latch := TRUE;
    ELSIF NOT #Flow_OK THEN #Diag_Code := 16#0003; #Fault_Latch := TRUE;
    ELSIF NOT #Profinet_Status_OK THEN #Diag_Code := 16#0004; #Fault_Latch := TRUE;
    ELSIF NOT #Pump1_Available AND NOT #Pump2_Available THEN #Diag_Code := 16#0005; #Fault_Latch := TRUE;
    ELSIF #Ack_Fault AND #User_Auth_Level >= 2 THEN #Fault_Latch := FALSE; #Diag_Code := 16#0000;
    END_IF;
    #Fault_Active := #Fault_Latch;

    // Redundant Failover
    IF NOT #Pump1_Available AND #Pump2_Available THEN #Active_Pump := 2;
    ELSIF NOT #Pump2_Available AND #Pump1_Available THEN #Active_Pump := 1;
    END_IF;

    IF #Fault_Latch OR NOT #Pump_Start_Req THEN
        #Sequence_Step := 0;
        #Open_Suction_Valve := FALSE;
        #Open_Discharge_Valve := FALSE;
        #Pump1_Run := FALSE;
        #Pump2_Run := FALSE;
    ELSIF #Pump_Start_Req AND NOT #Fault_Latch THEN
        CASE #Sequence_Step OF
            0: 
                #Open_Suction_Valve := TRUE;
                IF #Valve_Suction_Opened THEN #Sequence_Step := 1; END_IF;
            1:
                #Open_Discharge_Valve := TRUE;
                IF #Valve_Discharge_Opened THEN #Sequence_Step := 2; END_IF;
            2:
                IF #Active_Pump = 1 THEN #Pump1_Run := TRUE; ELSE #Pump2_Run := TRUE; END_IF;
        END_CASE;
    END_IF;
    #OPC_UA_Status := INT_TO_DWORD(#Sequence_Step) OR SHL(IN:=WORD_TO_DWORD(#Diag_Code), N:=16);
END_FUNCTION_BLOCK
