FUNCTION_BLOCK FB_ContinuousPotatoChipFryer
VAR_INPUT
    bEnable : BOOL; // Enable fryer system
    bEmergencyStop : BOOL; // E-Stop
    rTargetOilTemp : REAL; // Target oil temperature in Celsius (e.g. 180.0)
    rCurrentOilTemp : REAL; // Current oil temp measured by RTD
    rSliceFeedRate : REAL; // Potatoes feed rate (kg/hr)
    rPaddleTargetSpeed : REAL; // Target speed for paddles (RPM)
    bOpticalSorterReady : BOOL;
    bRejectTrigger : BOOL; // Reject signal from optical sorter
    rThermalFluidTemp : REAL; // Temperature of the primary heating fluid
END_VAR

VAR_OUTPUT
    bSystemRunning : BOOL;
    bHeaterEnable : BOOL;
    rHeaterValvePosition : REAL; // 0-100% position for thermal fluid valve
    rPaddleActualSpeed : REAL; // Commanded paddle speed
    bRejectEjector : BOOL; // Air blast ejector for bad chips
    bAlarmHighTemp : BOOL;
    bAlarmLowTemp : BOOL;
    bAlarmPaddleFault : BOOL;
    iState : INT; // State machine status
END_VAR

VAR
    rKp_Temp : REAL := 2.5;
    rKi_Temp : REAL := 0.1;
    rKd_Temp : REAL := 0.5;
    rIntegralTempError : REAL := 0.0;
    rPrevTempError : REAL := 0.0;
    rTempError : REAL;
    rDerivativeTemp : REAL;
    rPIDOutput : REAL;
    tonRejectDuration : TON;
    MAX_TEMP_DEVIATION : REAL := 15.0;
END_VAR

// Main logic
IF bEmergencyStop THEN
    bSystemRunning := FALSE;
    bHeaterEnable := FALSE;
    rHeaterValvePosition := 0.0;
    rPaddleActualSpeed := 0.0;
    bRejectEjector := FALSE;
    iState := 99;
    RETURN;
END_IF

IF NOT bEnable THEN
    bSystemRunning := FALSE;
    bHeaterEnable := FALSE;
    rHeaterValvePosition := 0.0;
    rPaddleActualSpeed := 0.0;
    bRejectEjector := FALSE;
    iState := 0;
    RETURN;
END_IF

CASE iState OF
    0: 
        IF rCurrentOilTemp < rTargetOilTemp - 5.0 THEN
            iState := 1;
        ELSE
            iState := 2;
        END_IF
    1: 
        bSystemRunning := TRUE;
        bHeaterEnable := TRUE;
        rTempError := rTargetOilTemp - rCurrentOilTemp;
        rIntegralTempError := rIntegralTempError + (rTempError * 0.1);
        rDerivativeTemp := (rTempError - rPrevTempError) / 0.1;
        rPIDOutput := (rKp_Temp * rTempError) + (rKi_Temp * rIntegralTempError) + (rKd_Temp * rDerivativeTemp);
        IF rPIDOutput > 100.0 THEN rPIDOutput := 100.0;
        ELSIF rPIDOutput < 0.0 THEN rPIDOutput := 0.0; END_IF
        rHeaterValvePosition := rPIDOutput;
        rPrevTempError := rTempError;
        rPaddleActualSpeed := 10.0;
        IF rCurrentOilTemp >= rTargetOilTemp THEN
            iState := 2;
        END_IF
    2: 
        bSystemRunning := TRUE;
        bHeaterEnable := TRUE;
        rTempError := rTargetOilTemp - rCurrentOilTemp;
        rIntegralTempError := rIntegralTempError + (rTempError * 0.1);
        IF rIntegralTempError > 1000.0 THEN rIntegralTempError := 1000.0;
        ELSIF rIntegralTempError < -1000.0 THEN rIntegralTempError := -1000.0; END_IF
        rDerivativeTemp := (rTempError - rPrevTempError) / 0.1;
        rPIDOutput := (rKp_Temp * rTempError) + (rKi_Temp * rIntegralTempError) + (rKd_Temp * rDerivativeTemp);
        IF rPIDOutput > 100.0 THEN rPIDOutput := 100.0;
        ELSIF rPIDOutput < 0.0 THEN rPIDOutput := 0.0; END_IF
        rHeaterValvePosition := rPIDOutput;
        rPrevTempError := rTempError;
        IF rSliceFeedRate > 500.0 THEN rPaddleActualSpeed := rPaddleTargetSpeed * 1.1;
        ELSE rPaddleActualSpeed := rPaddleTargetSpeed; END_IF
        IF bRejectTrigger AND bOpticalSorterReady THEN
            tonRejectDuration(IN := TRUE, PT := T#50MS);
            bRejectEjector := TRUE;
            IF tonRejectDuration.Q THEN
                bRejectEjector := FALSE;
                tonRejectDuration(IN := FALSE);
            END_IF
        ELSE
            bRejectEjector := FALSE;
            tonRejectDuration(IN := FALSE);
        END_IF
    99: 
        bSystemRunning := FALSE;
        bHeaterEnable := FALSE;
        rHeaterValvePosition := 0.0;
        rPaddleActualSpeed := 0.0;
END_CASE

bAlarmHighTemp := (rCurrentOilTemp > rTargetOilTemp + MAX_TEMP_DEVIATION);
bAlarmLowTemp := (rCurrentOilTemp < rTargetOilTemp - MAX_TEMP_DEVIATION) AND (iState = 2);
END_FUNCTION_BLOCK
