FUNCTION_BLOCK FB_LH2_StorageTank
(* 
   =============================================================================
   Title:           Utility-Scale Liquefied Hydrogen (LH2) Spherical Storage Tank
   Author:          Lumina AI Cloud Swarm
   Version:         1.0.0
   Description:     Comprehensive control algorithm for cryogenic LH2 storage, 
                    boil-off gas (BOG) zero-loss reliquefaction cascading, 
                    vacuum-jacketed perlite insulation stress monitoring, and 
                    acoustic emission leak detection.
   =============================================================================
*)
VAR_INPUT
    bSystemEnable       : BOOL;     (* Main system enable command *)
    bEmergencyStop      : BOOL;     (* Safety instrumented system (SIS) shutdown signal *)
    rTankPressure       : REAL;     (* Internal tank pressure [kPa] *)
    rTankTempTop        : REAL;     (* Temperature at the top of the tank [K] *)
    rTankTempBottom     : REAL;     (* Temperature at the bottom of the tank [K] *)
    rLiquidLevel        : REAL;     (* LH2 liquid level [%] *)
    rVacuumPressure     : REAL;     (* Vacuum-jacketed insulation pressure [mTorr] *)
    rAcousticEmission   : REAL;     (* Ultrasonic acoustic sensor amplitude for leak detection [dB] *)
END_VAR

VAR_OUTPUT
    bSystemReady        : BOOL;     (* Indicates system is operating normally *)
    bEmergencyShutdown  : BOOL;     (* Trip command to main safety valves *)
    rReliquefactionCmd  : REAL;     (* BOG reliquefaction compressor speed control [0-100%] *)
    bVentValveOpen      : BOOL;     (* BOG atmospheric vent valve command *)
    bLeakDetectedAlarm  : BOOL;     (* High-priority leak detection alarm *)
    bInsulationFault    : BOOL;     (* Vacuum-jacketed insulation failure alarm *)
    rHeatLeakEstimate   : REAL;     (* Estimated heat leak [W] based on BOG generation *)
END_VAR

VAR
    iState              : INT := 0; (* Internal state machine *)
    tBOGTimer           : TON;      (* Timer for BOG stabilization *)
    tLeakTimer          : TON;      (* Timer for acoustic leak confirmation *)
    rDeltaTemp          : REAL;     (* Temperature stratification differential *)
    rMaxPressureLim     : REAL := 250.0; (* Max allowable operating pressure [kPa] *)
    rBOGThreshold       : REAL := 150.0; (* Pressure at which reliquefaction starts [kPa] *)
    rVacuumLimit        : REAL := 10.0;  (* Max allowable vacuum pressure [mTorr] *)
    rAcousticLimit      : REAL := 85.0;  (* Acoustic emission threshold [dB] *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety Interlocks & Emergency Shutdown *)
IF NOT bEmergencyStop OR (rTankPressure > rMaxPressureLim) THEN
    bSystemReady := FALSE;
    bEmergencyShutdown := TRUE;
    bVentValveOpen := (rTankPressure > rMaxPressureLim); (* Force vent if overpressure *)
    rReliquefactionCmd := 0.0;
    iState := 99; (* Transition to fault state *)
    RETURN;
ELSE
    bEmergencyShutdown := FALSE;
END_IF;

(* 2. Insulation & Leak Diagnostics *)
IF rVacuumPressure > rVacuumLimit THEN
    bInsulationFault := TRUE;
ELSE
    bInsulationFault := FALSE;
END_IF;

tLeakTimer(IN := (rAcousticEmission > rAcousticLimit), PT := T#2S);
IF tLeakTimer.Q THEN
    bLeakDetectedAlarm := TRUE;
ELSE
    bLeakDetectedAlarm := FALSE;
END_IF;

(* 3. Core State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rReliquefactionCmd := 0.0;
        bVentValveOpen := FALSE;

        IF bSystemEnable AND NOT bLeakDetectedAlarm AND NOT bInsulationFault THEN
            iState := 10;
        END_IF;

    10: (* ACTIVE MONITORING *)
        bSystemReady := TRUE;
        rDeltaTemp := rTankTempTop - rTankTempBottom;

        (* Heat leak estimation based on thermodynamics *)
        rHeatLeakEstimate := (rDeltaTemp * 1.05) + (rVacuumPressure * 0.5);

        IF rTankPressure > rBOGThreshold THEN
            iState := 20; (* Start BOG Reliquefaction *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* BOG RELIQUEFACTION CASCADING *)
        bSystemReady := TRUE;

        (* Proportional pressure control for compressor speed *)
        rReliquefactionCmd := (rTankPressure - rBOGThreshold) * 2.5;

        IF rReliquefactionCmd > 100.0 THEN
            rReliquefactionCmd := 100.0;
        ELSIF rReliquefactionCmd < 0.0 THEN
            rReliquefactionCmd := 0.0;
        END_IF;

        tBOGTimer(IN := (rTankPressure <= (rBOGThreshold - 10.0)), PT := T#30S);
        IF tBOGTimer.Q THEN
            tBOGTimer(IN := FALSE);
            iState := 10; (* Return to monitoring once stabilized *)
        END_IF;

    99: (* FAULT HANDLING *)
        (* Wait for manual reset via bEmergencyStop cycling *)
        IF bEmergencyStop AND (rTankPressure < rMaxPressureLim) THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
