FUNCTION_BLOCK FB_BHS_Master_Control
TITLE = 'Airport Baggage Handling System Master Control'
VERSION : '2.1'

VAR_INPUT
    xSystemEnable      : BOOL; // Master Start/Stop for the BHS line
    xEmergencyStop     : BOOL; // E-Stop loop status
    iBagBarcodeID      : DINT; // Scanned Baggage ID from primary scanner
    xBagPresentScanner : BOOL; // Photoeye at the scanner induction
    xDCV_Available     : BOOL; // Destination Coded Vehicle available at load station
    rDCV_CurrentPos    : REAL; // Current position of the DCV (meters)
    xEBS_CraneHome     : BOOL; // Early Bag Storage crane at home position
    xFlightMakeupReady : BOOL; // Final chute ready to accept bags
END_VAR

VAR_OUTPUT
    xLIM_Enable        : BOOL; // Linear Induction Motor drive enable
    rLIM_SpeedRef      : REAL; // Linear Induction Motor speed reference (m/s)
    xDiverterActivate  : BOOL; // Pneumatic diverter to route bag
    xEBS_CraneStore    : BOOL; // Command EBS crane to store bag
    iEBS_TargetSlot    : INT;  // Target slot for early bag storage
    xLoadBagToDCV      : BOOL; // Command conveyor to load bag onto DCV
    xSystemFault       : BOOL; // Global fault indicator
    iFaultCode         : INT;  // Specific fault identifier
END_VAR

VAR
    State              : INT := 0; // Main state machine
    LIM_State          : INT := 0; // LIM control state machine
    EBS_State          : INT := 0; // EBS crane state machine
    tScanDelay         : TON;
    tLIM_Accel         : TON;
    bBagRequiresEBS    : BOOL;
    rTargetSpeed       : REAL;
    rCurrentSpeed      : REAL;
END_VAR

VAR CONSTANT
    STATE_IDLE         : INT := 0;
    STATE_SCANNING     : INT := 10;
    STATE_ROUTING      : INT := 20;
    STATE_LOAD_DCV     : INT := 30;
    STATE_STORE_EBS    : INT := 40;
    STATE_FAULT        : INT := 99;

    LIM_SPEED_MAX      : REAL := 5.0; // m/s
    LIM_SPEED_CRAWL    : REAL := 0.5; // m/s
END_VAR

// Main Control Logic
IF xEmergencyStop THEN
    State := STATE_FAULT;
    iFaultCode := 1000; // E-Stop pressed
    xLIM_Enable := FALSE;
    rLIM_SpeedRef := 0.0;
    xSystemFault := TRUE;
ELSIF NOT xSystemEnable THEN
    State := STATE_IDLE;
    xLIM_Enable := FALSE;
    rLIM_SpeedRef := 0.0;
    xSystemFault := FALSE;
END_IF;

CASE State OF
    STATE_IDLE:
        IF xSystemEnable AND xBagPresentScanner THEN
            State := STATE_SCANNING;
            tScanDelay(IN:=FALSE); // Reset timer
        END_IF;

    STATE_SCANNING:
        tScanDelay(IN:=TRUE, PT:=T#500MS);
        IF tScanDelay.Q THEN
            // Simulate Database lookup for routing (EBS or Flight)
            // In actual logic, this would be an external function call
            IF iBagBarcodeID > 500000 THEN
                bBagRequiresEBS := TRUE;
            ELSE
                bBagRequiresEBS := FALSE;
            END_IF;
            State := STATE_ROUTING;
        END_IF;

    STATE_ROUTING:
        IF bBagRequiresEBS THEN
            IF xEBS_CraneHome THEN
                State := STATE_STORE_EBS;
                iEBS_TargetSlot := iEBS_TargetSlot + 1; // Increment slot for demo
            END_IF;
        ELSE
            IF xDCV_Available AND xFlightMakeupReady THEN
                State := STATE_LOAD_DCV;
            END_IF;
        END_IF;

    STATE_LOAD_DCV:
        xLoadBagToDCV := TRUE;
        // Initiate LIM Profile for DCV movement
        xLIM_Enable := TRUE;
        IF rDCV_CurrentPos < 10.0 THEN
            rLIM_SpeedRef := LIM_SPEED_MAX;
        ELSIF rDCV_CurrentPos >= 10.0 AND rDCV_CurrentPos < 15.0 THEN
            rLIM_SpeedRef := LIM_SPEED_CRAWL;
        ELSE
            rLIM_SpeedRef := 0.0;
            xLoadBagToDCV := FALSE;
            State := STATE_IDLE;
        END_IF;

    STATE_STORE_EBS:
        xEBS_CraneStore := TRUE;
        // Additional crane sequence logic would reside here
        IF NOT xEBS_CraneHome THEN
            xEBS_CraneStore := FALSE;
            State := STATE_IDLE;
        END_IF;

    STATE_FAULT:
        // Latch faults until reset
        xLIM_Enable := FALSE;
        rLIM_SpeedRef := 0.0;
        xLoadBagToDCV := FALSE;
        xDiverterActivate := FALSE;
        xEBS_CraneStore := FALSE;
END_CASE;
END_FUNCTION_BLOCK
