    (* Internal State & Memory Variables *)
    iState              : INT := 0;
    tInitDelay          : TON;

    (* Advanced Filter & Kinematics Memory *)
    rLatencyCompDist    : REAL;
    rSafeStoppingDist   : REAL;
    rDecelEnvelope      : REAL;
    tLatencyMs          : DINT;

    (* Calibration Constants - Read-only internal *)
    rMinClearance       : REAL := 2.5;  (* 2.5 meters hard minimum physical clearance buffer *)
    rMaxDeceleration    : REAL := 4.0;  (* 4 m/s^2 nominal max braking threshold for heavy payload *)
    rReactionTime       : REAL := 0.5;  (* System and brake spooling reaction time [s] *)
END_VAR

(* === MAIN LOGIC === *)
(* Multi-layered safety interlock: highest priority override *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bCollisionAlarm := TRUE;
    bEStopTrigger := TRUE;
    rDynamicBrakeCmd := 100.0; (* Full torque stopping force *)
    iState := 0;
    RETURN;
END_IF;

CASE iState OF
    0: (* STATE: IDLE & DIAGNOSTIC SELF-TEST *)
        bSystemReady := FALSE;
        bCollisionAlarm := FALSE;
        bEStopTrigger := FALSE;
        rDynamicBrakeCmd := 0.0;

        IF bEnable THEN
            (* Initialize hardware diagnostics timer *)
            tInitDelay(IN := TRUE, PT := T#2S);
            IF tInitDelay.Q THEN
                tInitDelay(IN := FALSE);
                iState := 10;
            END_IF;
        ELSE
            tInitDelay(IN := FALSE);
        END_IF;

    10: (* STATE: RUNNING & CONTINUOUS ENVELOPE MONITORING *)
        bSystemReady := TRUE;
        bCollisionAlarm := FALSE;

        (* 1. Spatial Filtering & Inter-Vehicle V2X Latency Masking *)
        (* Convert packet latency TIME to ms, compute spatial drift compensation using host velocity *)
        tLatencyMs := TIME_TO_DINT(tV2xLatency);
        rLatencyCompDist := rV2xTargetDist - (rHostVelocity * DINT_TO_REAL(tLatencyMs) / 1000.0);

        (* Clamp latency compensation to physically possible values *)
        IF rLatencyCompDist < 0.0 THEN
            rLatencyCompDist := 0.0;
        END_IF;

        (* 2. Dynamic Braking Deceleration Envelope Calculation *)
        (* Kinematic integration: d = v^2 / (2*a) + (v * t_react) *)
        rSafeStoppingDist := (rHostVelocity * rHostVelocity) / (2.0 * rMaxDeceleration) + (rHostVelocity * rReactionTime);

        (* 3. Evaluated sensor fusion minimum threshold *)
        rDecelEnvelope := rLidarFrontDist;
        IF (rLatencyCompDist < rDecelEnvelope) AND (rLatencyCompDist > 0.0) THEN
            rDecelEnvelope := rLatencyCompDist;
        END_IF;

        (* 4. Envelope Execution & Advanced State Logic *)
        IF rDecelEnvelope <= (rSafeStoppingDist + rMinClearance) THEN
            (* Calculate proportional deceleration braking demand over safety margin *)
            rDynamicBrakeCmd := ((rSafeStoppingDist + rMinClearance - rDecelEnvelope) / rSafeStoppingDist) * 100.0;
            IF rDynamicBrakeCmd > 100.0 THEN
                rDynamicBrakeCmd := 100.0;
            END_IF;
            bCollisionAlarm := TRUE;
        ELSE
            rDynamicBrakeCmd := 0.0;
            bCollisionAlarm := FALSE;
        END_IF;

        (* CRITICAL Imminent Collision Fallback: Absolute boundary breach *)
        IF rDecelEnvelope <= rMinClearance THEN
            bEStopTrigger := TRUE;
            rDynamicBrakeCmd := 100.0;
            iState := 99; (* TRANSITION TO LATCHED FAULT STATE *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* STATE: LATCHED FAULT (ESTOP DEPLOYED) *)
        bSystemReady := FALSE;
        bCollisionAlarm := TRUE;
        bEStopTrigger := TRUE;
        rDynamicBrakeCmd := 100.0;

        (* System requires explicit enable signal cycle to acknowledge fault *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
