FUNCTION_BLOCK FB_Aeroponic_Mist_Controller
TITLE = 'Closed-Loop Aeroponic Mist Controller'
VERSION : '2.0'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

(*
    DESCRIPTION:
    This function block controls a closed-loop aeroponic misting system in an automated vertical farm.
    Key functionalities:
    1. Ultrasonic Fogger Control: Operates via PWM to maintain an optimal 50-micron droplet size 
       (achieved by specific duty cycle and frequency).
    2. Nutrient Dosing: Employs a PI controller driven by real-time sap flow sensor feedback from plant stems.
    3. UV-C Sterilization: Sequences UV-C lamps in the recirculation loop with strict safety interlocks.
*)

VAR_INPUT
    bEnable                 : BOOL;       // System enable signal
    bEmergencyStop          : BOOL;       // Emergency stop (Active LOW)

    // Process Values
    rSapFlowRate_mg_s       : REAL;       // Real-time sap flow from stem sensors (mg/s)
    rTargetSapFlow_mg_s     : REAL;       // Target sap flow for optimal growth (mg/s)
    rReservoirLevel_Pct     : REAL;       // Nutrient reservoir level (0.0 to 100.0 %)
    bFlowSwitchRecirc       : BOOL;       // Verifies water flow in recirculation loop
    rWaterTemperature_C     : REAL;       // Recirculation water temperature (C)

    // Configuration & Tuning
    tMistCycleTime          : TIME := T#5s; // Base PWM cycle time for ultrasonic foggers
    rMistDutyCycle_Pct      : REAL := 60.0; // Duty cycle to maintain 50-micron droplets
    rNutrientKp             : REAL := 2.5;  // Proportional gain for nutrient dosing
    rNutrientKi             : REAL := 0.5;  // Integral gain for nutrient dosing
    tUVC_SterilizationTime  : TIME := T#30m;// Duration for active UV-C sterilization
    tUVC_Interval           : TIME := T#4h; // Time between sterilization cycles
END_VAR

VAR_OUTPUT
    bUltrasonicFoggerRun    : BOOL;       // PWM Output to Ultrasonic Foggers
    rNutrientPumpSpeed_Pct  : REAL;       // 0-100% control signal to precision dosing pump
    bUVC_LampEnable         : BOOL;       // UV-C Lamp contactor output
    bRecirculationPumpRun   : BOOL;       // Recirculation pump control

    // Diagnostics & Alarms
    bAlarm_LowLevel         : BOOL;       // Reservoir level critical
    bAlarm_FlowFault        : BOOL;       // Flow switch failed during recirculation
    bAlarm_OverTemp         : BOOL;       // Water temperature out of bounds
    eSystemState            : INT;        // 0=IDLE, 1=RUNNING, 2=UVC_SEQ, 99=FAULT
END_VAR

VAR
    // Mist PWM Timers
    TMR_MistCycle           : TON;
    TMR_MistOnTime          : TON;
    tOnTime                 : TIME;

    // Nutrient PI Controller
    rErrorSapFlow           : REAL;
    rIntegralTerm           : REAL;
    tCycleTime_Aux          : LREAL; // Used to compute delta T for integration
    rDeltaTime              : REAL;

    // UV-C Sequencer
    TMR_UVC_Interval        : TON;
    TMR_UVC_Duration        : TON;
    bUVC_CycleActive        : BOOL;

    // Internal State
    bSafeToOperate          : BOOL;
END_VAR

VAR CONSTANT
    // Limits
    MIN_LEVEL_PCT           : REAL := 15.0; // Minimum safe reservoir level
    MAX_TEMP_C              : REAL := 28.0; // Maximum safe water temp
    MAX_PUMP_SPEED          : REAL := 100.0;
    MIN_PUMP_SPEED          : REAL := 0.0;
END_VAR

BEGIN
    // -----------------------------------------------------------------------------
    // 1. SAFETY & INTERLOCKS
    // -----------------------------------------------------------------------------
    IF NOT bEmergencyStop THEN
        bSafeToOperate := FALSE;
        eSystemState := 99; // FAULT
        bAlarm_LowLevel := FALSE;
        bAlarm_FlowFault := FALSE;
        bAlarm_OverTemp := FALSE;
    ELSE
        // Check Process Limits
        bAlarm_LowLevel := (rReservoirLevel_Pct < MIN_LEVEL_PCT);
        bAlarm_OverTemp := (rWaterTemperature_C > MAX_TEMP_C);

        bSafeToOperate := bEnable AND NOT bAlarm_LowLevel AND NOT bAlarm_OverTemp;

        IF NOT bSafeToOperate THEN
            eSystemState := 99; // FAULT
        END_IF;
    END_IF;

    // -----------------------------------------------------------------------------
    // 2. STATE MACHINE & OUTPUT ABORT
    // -----------------------------------------------------------------------------
    IF NOT bSafeToOperate THEN
        bUltrasonicFoggerRun   := FALSE;
        rNutrientPumpSpeed_Pct := 0.0;
        bUVC_LampEnable        := FALSE;
        bRecirculationPumpRun  := FALSE;
        bUVC_CycleActive       := FALSE;
        rIntegralTerm          := 0.0; // Reset integrator
        RETURN; // Halt execution
    END_IF;

    // Default state to running if safe
    IF eSystemState = 99 THEN
        eSystemState := 1; // Transition to RUNNING
    END_IF;

    // -----------------------------------------------------------------------------
    // 3. ULTRASONIC FOGGER CONTROL (PWM for 50-micron Droplets)
    // -----------------------------------------------------------------------------
    // Calculate On Time based on frequency requirement (duty cycle)
    tOnTime := REAL_TO_TIME((TIME_TO_REAL(tMistCycleTime) * LIMIT(MN:=0.0, IN:=rMistDutyCycle_Pct, MX:=100.0)) / 100.0);

    TMR_MistCycle(IN := NOT TMR_MistCycle.Q, PT := tMistCycleTime);

    IF TMR_MistCycle.Q THEN
        bUltrasonicFoggerRun := TRUE;
        TMR_MistOnTime(IN := FALSE, PT := tOnTime); // Reset
    END_IF;

    TMR_MistOnTime(IN := bUltrasonicFoggerRun, PT := tOnTime);

    IF TMR_MistOnTime.Q THEN
        bUltrasonicFoggerRun := FALSE;
    END_IF;

    // -----------------------------------------------------------------------------
    // 4. NUTRIENT DOSING (Sap Flow Driven PI Controller)
    // -----------------------------------------------------------------------------
    // Measure delta time (scan cycle time approximation)
    rDeltaTime := LREAL_TO_REAL(RUNTIME(tCycleTime_Aux));

    IF rDeltaTime > 0.0 AND rDeltaTime < 1.0 THEN
        rErrorSapFlow := rTargetSapFlow_mg_s - rSapFlowRate_mg_s;

        // Anti-windup integration
        IF (rNutrientPumpSpeed_Pct < MAX_PUMP_SPEED) AND (rNutrientPumpSpeed_Pct > MIN_PUMP_SPEED) OR 
           (rNutrientPumpSpeed_Pct >= MAX_PUMP_SPEED AND rErrorSapFlow < 0.0) OR
           (rNutrientPumpSpeed_Pct <= MIN_PUMP_SPEED AND rErrorSapFlow > 0.0) THEN
            rIntegralTerm := rIntegralTerm + (rErrorSapFlow * rNutrientKi * rDeltaTime);
        END_IF;

        // Calculate Output
        rNutrientPumpSpeed_Pct := LIMIT(MN := MIN_PUMP_SPEED,
                                        IN := (rErrorSapFlow * rNutrientKp) + rIntegralTerm,
                                        MX := MAX_PUMP_SPEED);
    END_IF;

    // -----------------------------------------------------------------------------
    // 5. UV-C STERILIZATION SEQUENCER
    // -----------------------------------------------------------------------------
    // Recirculation pump runs continuously when enabled
    bRecirculationPumpRun := TRUE;

    // Evaluate Flow Fault 
    IF NOT bFlowSwitchRecirc AND bUVC_CycleActive THEN
        bAlarm_FlowFault := TRUE;
        bUVC_CycleActive := FALSE; // Abort UV-C without flow to prevent overheating
    ELSE
        bAlarm_FlowFault := FALSE;
    END_IF;

    // Interval Timer
    TMR_UVC_Interval(IN := NOT bUVC_CycleActive AND bSafeToOperate AND NOT bAlarm_FlowFault, PT := tUVC_Interval);

    IF TMR_UVC_Interval.Q THEN
        bUVC_CycleActive := TRUE;
        eSystemState := 2; // UVC_SEQ
    END_IF;

    // Duration Timer
    TMR_UVC_Duration(IN := bUVC_CycleActive AND bFlowSwitchRecirc, PT := tUVC_SterilizationTime);

    IF TMR_UVC_Duration.Q THEN
        bUVC_CycleActive := FALSE; // Cycle Complete
        eSystemState := 1; // RUNNING
    END_IF;

    // Lamp Control Interlock
    bUVC_LampEnable := bUVC_CycleActive AND bFlowSwitchRecirc AND bSafeToOperate;

END_FUNCTION_BLOCK
