FUNCTION_BLOCK FB_Aerospace_ECLSS_Control
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main system enable signal *)
    bEmergencyAbend         : BOOL;     (* Emergency abort signal from command module *)
    rCabinPressure          : REAL;     (* Current cabin pressure in kPa *)
    rO2Concentration        : REAL;     (* Current O2 concentration in percentage *)
    rCO2Concentration       : REAL;     (* Current CO2 concentration in percentage *)
    rSabatierTemp           : REAL;     (* Sabatier reactor temperature in Deg C *)
    rCHXCondensateLevel     : REAL;     (* Condensing Heat Exchanger slosh level (0.0 to 1.0) *)
    rMicroGravityState      : REAL;     (* Current measured g-force scalar *)
END_VAR
VAR_OUTPUT
    bECLSSReady             : BOOL;     (* ECLSS system ready for nominal operation *)
    rSabatierHeaterCmd      : REAL;     (* Sabatier reactor heater control output (0-100%) *)
    rO2ValvePosition        : REAL;     (* Oxygen injection valve position (0-100%) *)
    rCO2ScrubberFanSpeed    : REAL;     (* CO2 scrubber centrifugal fan speed (0-100%) *)
    rCHXWaterPumpCmd        : REAL;     (* CHX variable speed water separator pump (0-100%) *)
    bCriticalAlarm          : BOOL;     (* Critical life support alarm *)
    iOperationMode          : INT;      (* Current operating mode state *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine *)
    tStartupDelay           : TON;      (* Sabatier warmup timer *)
    tSloshFilter            : TON;      (* Filter for CHX slosh baffling *)
    rFilteredCHXLevel       : REAL;     (* Low-pass filtered CHX level *)
    rCO2Error               : REAL;     (* CO2 concentration error *)
    rO2Error                : REAL;     (* O2 concentration error *)

    (* PID internal states *)
    rO2Integral             : REAL := 0.0;
    rSabatierIntegral       : REAL := 0.0;

    (* Constants *)
    rO2Setpoint             : REAL := 21.0;
    rCO2MaxSetpoint         : REAL := 0.5;
    rSabatierTargetTemp     : REAL := 450.0;
END_VAR

(* === MAIN LOGIC === *)
(* Multilayer Safety Interlock *)
IF bEmergencyAbend OR rCabinPressure < 70.0 THEN
    bECLSSReady := FALSE;
    bCriticalAlarm := TRUE;
    rSabatierHeaterCmd := 0.0;
    rO2ValvePosition := 100.0; (* Full open on abort for emergency breathing *)
    rCO2ScrubberFanSpeed := 100.0;
    rCHXWaterPumpCmd := 0.0;
    iOperationMode := 99; (* FAULT MODE *)
    iState := 99;
    RETURN;
END_IF;

(* CHX Slosh Filter - Simple EMA for microgravity baffling *)
IF rMicroGravityState < 0.1 THEN
    rFilteredCHXLevel := rFilteredCHXLevel + 0.05 * (rCHXCondensateLevel - rFilteredCHXLevel);
ELSE
    rFilteredCHXLevel := rFilteredCHXLevel + 0.2 * (rCHXCondensateLevel - rFilteredCHXLevel);
END_IF;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE & SELF-TEST *)
        bECLSSReady := FALSE;
        bCriticalAlarm := FALSE;
        rSabatierHeaterCmd := 0.0;
        rO2ValvePosition := 0.0;
        rCO2ScrubberFanSpeed := 0.0;
        rCHXWaterPumpCmd := 0.0;
        iOperationMode := 0;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* WARMUP SABATIER REACTOR *)
        iOperationMode := 1;
        (* PI Control for Sabatier Heater *)
        rSabatierIntegral := rSabatierIntegral + (rSabatierTargetTemp - rSabatierTemp) * 0.01;
        IF rSabatierIntegral > 100.0 THEN rSabatierIntegral := 100.0; END_IF;
        IF rSabatierIntegral < 0.0 THEN rSabatierIntegral := 0.0; END_IF;
        rSabatierHeaterCmd := ((rSabatierTargetTemp - rSabatierTemp) * 2.5) + rSabatierIntegral;

        IF rSabatierHeaterCmd > 100.0 THEN rSabatierHeaterCmd := 100.0; END_IF;
        IF rSabatierHeaterCmd < 0.0 THEN rSabatierHeaterCmd := 0.0; END_IF;

        tStartupDelay(IN := (rSabatierTemp >= rSabatierTargetTemp - 5.0), PT := T#30S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* NOMINAL OPERATION *)
        iOperationMode := 2;
        bECLSSReady := TRUE;
        bCriticalAlarm := FALSE;

        (* O2 Injection Control *)
        rO2Error := rO2Setpoint - rO2Concentration;
        IF rO2Error > 0.0 THEN
            rO2Integral := rO2Integral + rO2Error * 0.05;
            IF rO2Integral > 50.0 THEN rO2Integral := 50.0; END_IF;
            rO2ValvePosition := (rO2Error * 10.0) + rO2Integral;
            IF rO2ValvePosition > 100.0 THEN rO2ValvePosition := 100.0; END_IF;
        ELSE
            rO2ValvePosition := 0.0;
            rO2Integral := 0.0;
        END_IF;

        (* CO2 Scrubber Fan Control *)
        rCO2Error := rCO2Concentration - rCO2MaxSetpoint;
        IF rCO2Error > 0.0 THEN
            rCO2ScrubberFanSpeed := 50.0 + (rCO2Error * 100.0);
            IF rCO2ScrubberFanSpeed > 100.0 THEN rCO2ScrubberFanSpeed := 100.0; END_IF;
        ELSE
            rCO2ScrubberFanSpeed := 20.0; (* Minimum idle speed for circulation *)
        END_IF;

        (* CHX Condensate Pump Control *)
        IF rFilteredCHXLevel > 0.8 THEN
            rCHXWaterPumpCmd := 100.0;
        ELSIF rFilteredCHXLevel > 0.5 THEN
            rCHXWaterPumpCmd := 50.0;
        ELSE
            rCHXWaterPumpCmd := 0.0;
        END_IF;

        (* Sabatier Temperature Maintenance *)
        rSabatierIntegral := rSabatierIntegral + (rSabatierTargetTemp - rSabatierTemp) * 0.01;
        IF rSabatierIntegral > 100.0 THEN rSabatierIntegral := 100.0; END_IF;
        IF rSabatierIntegral < 0.0 THEN rSabatierIntegral := 0.0; END_IF;
        rSabatierHeaterCmd := ((rSabatierTargetTemp - rSabatierTemp) * 2.5) + rSabatierIntegral;
        IF rSabatierHeaterCmd > 100.0 THEN rSabatierHeaterCmd := 100.0; END_IF;
        IF rSabatierHeaterCmd < 0.0 THEN rSabatierHeaterCmd := 0.0; END_IF;

        IF NOT bSystemEnable THEN
            iState := 30;
        END_IF;

    30: (* SHUTDOWN SEQUENCE *)
        iOperationMode := 3;
        rSabatierHeaterCmd := 0.0;
        rO2ValvePosition := 0.0;
        rCO2ScrubberFanSpeed := 100.0; (* Purge *)
        tStartupDelay(IN := TRUE, PT := T#60S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 0;
        END_IF;

    99: (* FAULT RECOVERY WAIT *)
        IF bSystemEnable AND NOT bEmergencyAbend AND rCabinPressure >= 70.0 THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
