FUNCTION_BLOCK FB_VRFB_Core_Controller
TITLE = 'Vanadium Redox Flow Battery Core Controller'
VERSION : '1.0'

VAR_INPUT
    // Physical Analog Inputs
    AI_Anolyte_Tank_Temp : REAL;   (* °C *)
    AI_Catholyte_Tank_Temp : REAL; (* °C *)
    AI_Stack_Temp : REAL;          (* °C *)
    AI_Anolyte_Flow_Rate : REAL;   (* L/min *)
    AI_Catholyte_Flow_Rate : REAL; (* L/min *)
    AI_Anolyte_Pressure : REAL;    (* bar *)
    AI_Catholyte_Pressure : REAL;  (* bar *)
    AI_Stack_Voltage : REAL;       (* V *)
    AI_Stack_Current : REAL;       (* A, positive for charge, negative for discharge *)

    // Cell Voltage Monitoring (Sampled subset)
    AI_Cell_Voltages : ARRAY[1..10] OF REAL; (* V *)

    // Control Commands
    CMD_System_Enable : BOOL;
    CMD_Target_Power : REAL;       (* kW *)
    CMD_Emergency_Stop : BOOL;

    // Setpoints
    SP_Target_SOC : REAL;          (* 0.0 to 100.0 % *)
    SP_Max_Charge_Current : REAL;  (* A *)
    SP_Max_Discharge_Current : REAL; (* A *)
END_VAR

VAR_OUTPUT
    // Physical Analog Outputs
    AO_Anolyte_Pump_Speed : REAL;   (* 0-100% VFD Reference *)
    AO_Catholyte_Pump_Speed : REAL; (* 0-100% VFD Reference *)
    AO_Cooling_Fan_Speed : REAL;    (* 0-100% *)
    AO_Heater_Power : REAL;         (* 0-100% PWM *)

    // System Status
    STS_System_State : INT;         (* 0:OFF, 1:STANDBY, 2:CHARGING, 3:DISCHARGING, 4:FAULT *)
    STS_Estimated_SOC : REAL;       (* % *)
    STS_Active_Power : REAL;        (* kW *)

    // Alarms and Faults
    ALM_General_Fault : BOOL;
    ALM_Over_Pressure : BOOL;
    ALM_Over_Temp : BOOL;
    ALM_Voltage_Imbalance : BOOL;
END_VAR

VAR
    // Internal States
    StateMachine : INT := 0;

    // PI Controller Variables for Anolyte Pump
    Kp_Pump : REAL := 2.5;
    Ki_Pump : REAL := 0.8;
    Anolyte_Error_Integral : REAL := 0.0;
    Catholyte_Error_Integral : REAL := 0.0;
    Flow_Setpoint : REAL := 0.0;

    // Thermal Management
    Target_Temp : REAL := 35.0; (* °C optimal *)
    Max_Temp : REAL := 45.0;    (* °C precipitation limit *)
    Min_Temp : REAL := 15.0;    (* °C crystallization limit *)

    // SOC Calculation
    OCV_Estimated : REAL;
    Faraday_Constant : REAL := 96485.332;
    Internal_Resistance : REAL := 0.015;

    // Cell Balancing
    Max_Cell_V : REAL;
    Min_Cell_V : REAL;
    Avg_Cell_V : REAL;
    i : INT;

    // Timers
    TMR_Fault_Delay : TON;
    Fault_Timer_In : BOOL;
END_VAR

// -----------------------------------------------------------------------------
// 1. Safety and Interlocks
// -----------------------------------------------------------------------------
IF CMD_Emergency_Stop THEN
    StateMachine := 4; // Force Fault State
    ALM_General_Fault := TRUE;
END_IF;

// Overpressure Check
IF AI_Anolyte_Pressure > 3.0 OR AI_Catholyte_Pressure > 3.0 THEN
    Fault_Timer_In := TRUE;
    ALM_Over_Pressure := TRUE;
ELSE
    Fault_Timer_In := FALSE;
    ALM_Over_Pressure := FALSE;
END_IF;

// Overtemperature Check
IF AI_Anolyte_Tank_Temp > Max_Temp OR AI_Catholyte_Tank_Temp > Max_Temp OR AI_Stack_Temp > (Max_Temp + 5.0) THEN
    ALM_Over_Temp := TRUE;
    StateMachine := 4;
ELSE
    ALM_Over_Temp := FALSE;
END_IF;

TMR_Fault_Delay(IN := Fault_Timer_In, PT := T#2S);
IF TMR_Fault_Delay.Q THEN
    StateMachine := 4;
    ALM_General_Fault := TRUE;
END_IF;

// -----------------------------------------------------------------------------
// 2. Cell Voltage Balancing & Diagnostics
// -----------------------------------------------------------------------------
Max_Cell_V := AI_Cell_Voltages[1];
Min_Cell_V := AI_Cell_Voltages[1];
Avg_Cell_V := 0.0;

FOR i := 1 TO 10 DO
    IF AI_Cell_Voltages[i] > Max_Cell_V THEN
        Max_Cell_V := AI_Cell_Voltages[i];
    END_IF;
    IF AI_Cell_Voltages[i] < Min_Cell_V THEN
        Min_Cell_V := AI_Cell_Voltages[i];
    END_IF;
    Avg_Cell_V := Avg_Cell_V + AI_Cell_Voltages[i];
END_FOR;
Avg_Cell_V := Avg_Cell_V / 10.0;

IF (Max_Cell_V - Min_Cell_V) > 0.15 THEN
    ALM_Voltage_Imbalance := TRUE;
ELSE
    ALM_Voltage_Imbalance := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 3. State of Charge (SOC) Estimation (OCV based)
// -----------------------------------------------------------------------------
// V_stack = OCV + I * R_int
OCV_Estimated := AI_Stack_Voltage - (AI_Stack_Current * Internal_Resistance);

// Nernst equation simplified linear approximation for V-SOC curve in Vanadium
STS_Estimated_SOC := (((OCV_Estimated / 40.0) - 1.25) / 0.30) * 100.0;

IF STS_Estimated_SOC > 100.0 THEN STS_Estimated_SOC := 100.0; END_IF;
IF STS_Estimated_SOC < 0.0 THEN STS_Estimated_SOC := 0.0; END_IF;

// -----------------------------------------------------------------------------
// 4. Thermal Management
// -----------------------------------------------------------------------------
IF AI_Anolyte_Tank_Temp > Target_Temp OR AI_Catholyte_Tank_Temp > Target_Temp THEN
    AO_Cooling_Fan_Speed := (MAX(AI_Anolyte_Tank_Temp, AI_Catholyte_Tank_Temp) - Target_Temp) * 10.0;
    AO_Heater_Power := 0.0;
ELSIF AI_Anolyte_Tank_Temp < Min_Temp THEN
    AO_Heater_Power := (Min_Temp - AI_Anolyte_Tank_Temp) * 20.0;
    AO_Cooling_Fan_Speed := 0.0;
ELSE
    AO_Cooling_Fan_Speed := 0.0;
    AO_Heater_Power := 0.0;
END_IF;

// Clamp limits
IF AO_Cooling_Fan_Speed > 100.0 THEN AO_Cooling_Fan_Speed := 100.0; END_IF;
IF AO_Heater_Power > 100.0 THEN AO_Heater_Power := 100.0; END_IF;

// -----------------------------------------------------------------------------
// 5. State Machine & Flow Control
// -----------------------------------------------------------------------------
CASE StateMachine OF
    0: (* OFF *)
        AO_Anolyte_Pump_Speed := 0.0;
        AO_Catholyte_Pump_Speed := 0.0;
        IF CMD_System_Enable AND NOT ALM_General_Fault THEN
            StateMachine := 1;
        END_IF;

    1: (* STANDBY *)
        Flow_Setpoint := 5.0; 
        IF CMD_Target_Power > 1.0 AND STS_Estimated_SOC < SP_Target_SOC THEN
            StateMachine := 2; // CHARGING
        ELSIF CMD_Target_Power < -1.0 AND STS_Estimated_SOC > 0.0 THEN
            StateMachine := 3; // DISCHARGING
        END_IF;
        IF NOT CMD_System_Enable THEN
            StateMachine := 0;
        END_IF;

    2: (* CHARGING *)
        Flow_Setpoint := 10.0 + (CMD_Target_Power * 0.5);
        IF STS_Estimated_SOC >= SP_Target_SOC OR CMD_Target_Power <= 0.0 THEN
            StateMachine := 1;
        END_IF;

    3: (* DISCHARGING *)
        Flow_Setpoint := 10.0 + (ABS(CMD_Target_Power) * 0.5);
        IF STS_Estimated_SOC <= 5.0 OR CMD_Target_Power >= 0.0 THEN
            StateMachine := 1;
        END_IF;

    4: (* FAULT *)
        AO_Anolyte_Pump_Speed := 0.0;
        AO_Catholyte_Pump_Speed := 0.0;
        IF NOT CMD_Emergency_Stop AND NOT ALM_Over_Pressure AND NOT ALM_Over_Temp THEN
            IF NOT CMD_System_Enable THEN
                ALM_General_Fault := FALSE;
                StateMachine := 0;
            END_IF;
        END_IF;
END_CASE;

IF StateMachine > 0 AND StateMachine < 4 THEN
    Anolyte_Error_Integral := Anolyte_Error_Integral + (Flow_Setpoint - AI_Anolyte_Flow_Rate) * 0.1;
    AO_Anolyte_Pump_Speed := (Kp_Pump * (Flow_Setpoint - AI_Anolyte_Flow_Rate)) + (Ki_Pump * Anolyte_Error_Integral);

    Catholyte_Error_Integral := Catholyte_Error_Integral + (Flow_Setpoint - AI_Catholyte_Flow_Rate) * 0.1;
    AO_Catholyte_Pump_Speed := (Kp_Pump * (Flow_Setpoint - AI_Catholyte_Flow_Rate)) + (Ki_Pump * Catholyte_Error_Integral);

    IF AO_Anolyte_Pump_Speed > 100.0 THEN AO_Anolyte_Pump_Speed := 100.0; ELSIF AO_Anolyte_Pump_Speed < 0.0 THEN AO_Anolyte_Pump_Speed := 0.0; END_IF;
    IF AO_Catholyte_Pump_Speed > 100.0 THEN AO_Catholyte_Pump_Speed := 100.0; ELSIF AO_Catholyte_Pump_Speed < 0.0 THEN AO_Catholyte_Pump_Speed := 0.0; END_IF;

    IF AO_Anolyte_Pump_Speed = 100.0 OR AO_Anolyte_Pump_Speed = 0.0 THEN Anolyte_Error_Integral := Anolyte_Error_Integral - (Flow_Setpoint - AI_Anolyte_Flow_Rate) * 0.1; END_IF;
    IF AO_Catholyte_Pump_Speed = 100.0 OR AO_Catholyte_Pump_Speed = 0.0 THEN Catholyte_Error_Integral := Catholyte_Error_Integral - (Flow_Setpoint - AI_Catholyte_Flow_Rate) * 0.1; END_IF;
END_IF;

STS_System_State := StateMachine;
STS_Active_Power := (AI_Stack_Voltage * AI_Stack_Current) / 1000.0;

END_FUNCTION_BLOCK
```

