FUNCTION_BLOCK FB_AeroCarbonFiberRTM_MasterControl
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal / master start *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (TRUE = safe, FALSE = stop) *)
    rVacuumBagPressure      : REAL;     (* Current vacuum pressure in mbar (0-1000) *)
    rResinInletPressure     : REAL;     (* Process measurement: resin line pressure (bar) *)
    rToolZoneTemps          : ARRAY[1..10] OF REAL; (* Physical measurement: temperature in deg C for 10 localized zones *)
    bFlowFrontSensors       : ARRAY[1..50] OF BOOL; (* 50-port resin infusion flow-front tracking optical/capacitive sensors *)
    rResinBatchViscosity    : REAL;     (* Real-time inline viscosity measurement (cP) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* System ready status for SCADA handshake *)
    rVacuumPumpSpeedOut     : REAL;     (* Control signal to vacuum pump VFD (0.0 - 100.0 %) *)
    rResinPumpFlowCmd       : REAL;     (* Control signal to resin injection pump (cc/min) *)
    rToolHeaterCmd          : ARRAY[1..10] OF REAL; (* PWM duty cycle output to 10 SSR heating zones (0.0 - 100.0) *)
    bAlarm                  : BOOL;     (* Fault alarm output / safety interlock trigger *)
    iActiveInfusionStage    : INT;      (* Current stage of the RTM process for operator HMI *)
END_VAR
VAR
    (* Internal state and mathematical variables *)
    iState                  : INT := 0; (* Main state machine step index *)
    tDebulkTimer            : TON;      (* Timer for vacuum debulking hold *)
    tCureTimer              : TON;      (* Timer for resin curing stage *)
    iTempIndex              : INT;      (* Loop counter for multi-zone mapping *)
    rMaxExothermRate        : REAL;     (* Calculated peak exotherm generation rate *)
    iFlowFrontCount         : INT;      (* Counter for how many sensors have tripped *)
    iFlowIndex              : INT;      (* Loop counter for flow sensors *)
    rAverageTemp            : REAL;     (* Average tooling temperature *)
    rTemperatureSetPoint    : ARRAY[1..10] OF REAL; (* Target temp for localized mapping *)
    bHeatingTargetReached   : BOOL;
    tPulseTimer             : TON;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rVacuumPumpSpeedOut := 0.0;
    rResinPumpFlowCmd := 0.0;
    iState := 999; (* Fault state *)
    FOR iTempIndex := 1 TO 10 DO
        rToolHeaterCmd[iTempIndex] := 0.0;
    END_FOR;
    RETURN;
END_IF;

(* 2. Master State Machine for Aviation-Grade RTM *)
CASE iState OF
    0: (* IDLE & SYSTEM CHECK *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rVacuumPumpSpeedOut := 0.0;
        rResinPumpFlowCmd := 0.0;
        iActiveInfusionStage := 0;

        IF bEnable THEN
            bSystemReady := FALSE;
            iState := 10; (* Move to Vacuum Debulking *)
        END_IF;

    10: (* VACUUM DEBULKING PRESSURE PROFILING *)
        iActiveInfusionStage := 1;

        (* Ramp vacuum up to pull air out of the dry carbon fiber preform *)
        IF rVacuumBagPressure > 10.0 THEN
            rVacuumPumpSpeedOut := 100.0; (* Full speed if pressure > 10mbar *)
        ELSE
            rVacuumPumpSpeedOut := 25.0; (* Maintenance speed *)
        END_IF;

        (* Hold vacuum for specified debulk time (e.g., 2 hours simulated here as 10s for test) *)
        tDebulkTimer(IN := (rVacuumBagPressure <= 15.0), PT := T#10S);
        IF tDebulkTimer.Q THEN
            tDebulkTimer(IN := FALSE);
            iState := 20; (* Move to Preheat *)
        END_IF;

    20: (* MULTI-ZONE LOCALIZED PRE-HEATING *)
        iActiveInfusionStage := 2;
        bHeatingTargetReached := TRUE;

        FOR iTempIndex := 1 TO 10 DO
            rTemperatureSetPoint[iTempIndex] := 120.0; (* Aviation epoxy injection temp *)

            (* Simple Proportional Control for heaters *)
            IF rToolZoneTemps[iTempIndex] < rTemperatureSetPoint[iTempIndex] THEN
                rToolHeaterCmd[iTempIndex] := (rTemperatureSetPoint[iTempIndex] - rToolZoneTemps[iTempIndex]) * 5.0;
                IF rToolHeaterCmd[iTempIndex] > 100.0 THEN rToolHeaterCmd[iTempIndex] := 100.0; END_IF;
                bHeatingTargetReached := FALSE;
            ELSE
                rToolHeaterCmd[iTempIndex] := 0.0;
            END_IF;
        END_FOR;

        IF bHeatingTargetReached THEN
            iState := 30; (* Move to Injection *)
        END_IF;

    30: (* RESIN INFUSION & 50-PORT FLOW-FRONT TRACKING *)
        iActiveInfusionStage := 3;

        (* Evaluate flow front progression *)
        iFlowFrontCount := 0;
        FOR iFlowIndex := 1 TO 50 DO
            IF bFlowFrontSensors[iFlowIndex] THEN
                iFlowFrontCount := iFlowFrontCount + 1;
            END_IF;
        END_FOR;

        (* Dynamically adjust injection pressure/flow based on viscosity and progression *)
        (* High initial flow, tapering down as the mold fills to prevent fiber wash (displacement) *)
        rResinPumpFlowCmd := 500.0 - (INT_TO_REAL(iFlowFrontCount) * 8.0) + (rResinBatchViscosity * 0.1);

        IF rResinPumpFlowCmd < 50.0 THEN
            rResinPumpFlowCmd := 50.0;
        END_IF;

        (* Check if mold is completely filled (all sensors TRUE or pressure spikes) *)
        IF iFlowFrontCount >= 50 OR rResinInletPressure > 5.5 THEN
            rResinPumpFlowCmd := 0.0; (* Stop injection *)
            iState := 40; (* Move to Cure Phase *)
        END_IF;

    40: (* CURE PHASE & EXOTHERM THERMAL MAPPING *)
        iActiveInfusionStage := 4;

        (* Ramp to cure temp and manage exothermic reaction heat *)
        FOR iTempIndex := 1 TO 10 DO
            rTemperatureSetPoint[iTempIndex] := 180.0; (* Cure temperature *)

            IF rToolZoneTemps[iTempIndex] < rTemperatureSetPoint[iTempIndex] THEN
                rToolHeaterCmd[iTempIndex] := 50.0; (* Slower heating to prevent overshoot *)
            ELSIF rToolZoneTemps[iTempIndex] > (rTemperatureSetPoint[iTempIndex] + 5.0) THEN
                (* Exotherm detected: temp is spiking above setpoint *)
                rToolHeaterCmd[iTempIndex] := 0.0;
                bAlarm := TRUE; (* Optional alarm if exotherm is too aggressive *)
            ELSE
                rToolHeaterCmd[iTempIndex] := 10.0; (* Maintenance heat *)
            END_IF;
        END_FOR;

        tCureTimer(IN := TRUE, PT := T#30S); (* Simulated cure time *)
        IF tCureTimer.Q THEN
            tCureTimer(IN := FALSE);
            iState := 50; (* Cool down *)
        END_IF;

    50: (* COOLING & DEMOLD *)
        iActiveInfusionStage := 5;
        rVacuumPumpSpeedOut := 0.0;

        FOR iTempIndex := 1 TO 10 DO
            rToolHeaterCmd[iTempIndex] := 0.0; (* Heaters off *)
        END_FOR;

        rAverageTemp := 0.0;
        FOR iTempIndex := 1 TO 10 DO
            rAverageTemp := rAverageTemp + rToolZoneTemps[iTempIndex];
        END_FOR;
        rAverageTemp := rAverageTemp / 10.0;

        IF rAverageTemp < 40.0 THEN
            iState := 60; (* Complete *)
        END_IF;

    60: (* PROCESS COMPLETE *)
        iActiveInfusionStage := 6;
        bSystemReady := TRUE;

        IF NOT bEnable THEN
            iState := 0; (* Reset state machine *)
        END_IF;

    999: (* FAULT RECOVERY *)
        IF NOT bAlarm AND bEnable AND bEmergencyStop THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

