FUNCTION_BLOCK "TractionControl_ProfinetDiag"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      TargetSpeed_kmh : Real;
      ActualSpeed_kmh : Real;
      WheelSpeed_rpm : Real;
      WheelDiameter_m : Real;
      BrakeCommand : Real;
      MotorTemp_C : Real;
      SensorValid_Speed : Bool;
      SensorValid_Temp : Bool;
      InverterFault : Bool;
   END_VAR
   VAR_OUTPUT 
      TorqueCmd_Nm : Real;
      RegenActive : Bool;
      SlipDetected : Bool;
      DeratingActive : Bool;
      SCADA_Telemetry : "Profinet_Telemetry";
   END_VAR
   VAR 
      WheelLinearSpeed_kmh : Real;
      SlipRatio : Real;
      ThermalDeratingFactor : Real;
      FaultActive : Bool;
   END_VAR
   CONST
      MAX_ALLOWABLE_SLIP := 0.15;
      MAX_TORQUE := 10000.0;
      TEMP_WARN := 150.0;
      TEMP_CRIT := 200.0;
      ERR_SPEED_SENS := 101;
      ERR_TEMP_SENS := 102;
      ERR_INVERTER := 103;
      ERR_OVERSPEED := 104;
   END_CONST
BEGIN
    #FaultActive := FALSE;
    #SCADA_Telemetry.FaultCode := 0;
    IF NOT #SensorValid_Speed THEN
        #FaultActive := TRUE;
        #SCADA_Telemetry.FaultCode := #ERR_SPEED_SENS;
    ELSIF NOT #SensorValid_Temp THEN
        #FaultActive := TRUE;
        #SCADA_Telemetry.FaultCode := #ERR_TEMP_SENS;
    ELSIF #InverterFault THEN
        #FaultActive := TRUE;
        #SCADA_Telemetry.FaultCode := #ERR_INVERTER;
    ELSIF #ActualSpeed_kmh > 350.0 THEN
        #FaultActive := TRUE;
        #SCADA_Telemetry.FaultCode := #ERR_OVERSPEED;
    END_IF;
    IF #FaultActive THEN
        #TorqueCmd_Nm := 0.0;
        #RegenActive := FALSE;
        #SCADA_Telemetry.SystemHealthy := FALSE;
        RETURN;
    END_IF;
    #SCADA_Telemetry.SystemHealthy := TRUE;
    IF #MotorTemp_C < #TEMP_WARN THEN
        #ThermalDeratingFactor := 1.0;
        #DeratingActive := FALSE;
    ELSIF #MotorTemp_C > #TEMP_CRIT THEN
        #ThermalDeratingFactor := 0.0;
        #DeratingActive := TRUE;
    ELSE
        #ThermalDeratingFactor := 1.0 - ((#MotorTemp_C - #TEMP_WARN) / (#TEMP_CRIT - #TEMP_WARN));
        #DeratingActive := TRUE;
    END_IF;
    #WheelLinearSpeed_kmh := (#WheelSpeed_rpm * 3.14159 * #WheelDiameter_m * 60.0) / 1000.0;
    IF #ActualSpeed_kmh > 1.0 THEN
        #SlipRatio := ABS(#WheelLinearSpeed_kmh - #ActualSpeed_kmh) / #ActualSpeed_kmh;
    ELSE
        #SlipRatio := 0.0;
    END_IF;
    #SlipDetected := #SlipRatio > #MAX_ALLOWABLE_SLIP;
    IF #BrakeCommand > 0.0 THEN
        #RegenActive := TRUE;
        #TorqueCmd_Nm := - (#BrakeCommand / 100.0 * #MAX_TORQUE);
        IF #SlipDetected THEN #TorqueCmd_Nm := #TorqueCmd_Nm * (1.0 - #SlipRatio); END_IF;
    ELSE
        #RegenActive := FALSE;
        #TorqueCmd_Nm := ((#TargetSpeed_kmh - #ActualSpeed_kmh) * 50.0);
        IF #SlipDetected THEN #TorqueCmd_Nm := #TorqueCmd_Nm * (1.0 - #SlipRatio); END_IF;
        IF #TorqueCmd_Nm > #MAX_TORQUE THEN #TorqueCmd_Nm := #MAX_TORQUE; END_IF;
        IF #TorqueCmd_Nm < 0.0 THEN #TorqueCmd_Nm := 0.0; END_IF;
    END_IF;
    #TorqueCmd_Nm := #TorqueCmd_Nm * #ThermalDeratingFactor;
    #SCADA_Telemetry.SpeedStatus := #ActualSpeed_kmh;
    #SCADA_Telemetry.TorqueActual := #TorqueCmd_Nm;
    #SCADA_Telemetry.MotorTempStatus := #MotorTemp_C;
END_FUNCTION_BLOCK
