FUNCTION_BLOCK FB_Wastewater_Plant_Coordinator
// -----------------------------------------------------------------------------
// Smart City Wastewater Treatment - Advanced Control
// Integrates:
// 1. Activated Sludge Aeration (Dissolved Oxygen PID)
// 2. Anaerobic Digester Biogas Harvesting
// 3. UV Disinfection Dosing Control
// -----------------------------------------------------------------------------

VAR_INPUT
    rInfluentFlow      : REAL;   // [m3/h] Plant influent flow rate
    rDO_Level_Zone1    : REAL;   // [mg/L] Dissolved Oxygen in aeration zone 1
    rDO_Level_Zone2    : REAL;   // [mg/L] Dissolved Oxygen in aeration zone 2
    rDO_Setpoint       : REAL := 2.0; // [mg/L] Target DO
    rDigesterTemp      : REAL;   // [degC] Anaerobic digester temperature
    rBiogasPressure    : REAL;   // [kPa] Biogas storage pressure
    rUVTransmittance   : REAL;   // [%] UV Transmittance of effluent
    rEffluentFlow      : REAL;   // [m3/h] Plant effluent flow rate
    bSystemEnable      : BOOL;   // Global start/stop command
    bEmergencyStop     : BOOL;   // Emergency shutdown
END_VAR

VAR_OUTPUT
    rBlowerSpeedZone1  : REAL;   // [%] VFD command for Aeration Blower 1
    rBlowerSpeedZone2  : REAL;   // [%] VFD command for Aeration Blower 2
    rDigesterHeaterCmd : REAL;   // [%] Digester heating valve command
    bBiogasFlareValve  : BOOL;   // [CMD] Open flare valve if overpressure
    bBiogasEngineValve : BOOL;   // [CMD] Feed biogas to CHP engine
    rUVLampPower       : REAL;   // [%] UV system intensity/power
    bGeneralAlarm      : BOOL;   // Global alarm flag
    iCurrentState      : INT;    // State machine status
END_VAR

VAR
    // Internal PID and Control Variables
    rDO_Error_Z1       : REAL;
    rDO_Error_Z2       : REAL;
    rIntegral_Z1       : REAL;
    rIntegral_Z2       : REAL;
    rKp_DO             : REAL := 15.0;
    rKi_DO             : REAL := 0.5;
    rMaxBlowerSpeed    : REAL := 100.0;
    rMinBlowerSpeed    : REAL := 20.0;

    // Biogas Control
    rMaxBiogasPressure : REAL := 15.0; // kPa
    rFlarePressure     : REAL := 18.0; // kPa
    rMinEnginePressure : REAL := 5.0;  // kPa
    rTargetTemp        : REAL := 35.0; // Mesophilic target
    rTempError         : REAL;

    // UV Control
    rUVBaseDose        : REAL := 30.0; // mJ/cm2
    rCalculatedIntensity: REAL;

    // Timers
    tonStartupDelay    : TON;
    tonAlarmDelay      : TON;
END_VAR

// -----------------------------------------------------------------------------
// MAIN LOGIC
// -----------------------------------------------------------------------------

IF bEmergencyStop THEN
    rBlowerSpeedZone1  := 0.0;
    rBlowerSpeedZone2  := 0.0;
    rDigesterHeaterCmd := 0.0;
    bBiogasFlareValve  := TRUE; // Fail-safe: vent to flare
    bBiogasEngineValve := FALSE;
    rUVLampPower       := 0.0;
    bGeneralAlarm      := TRUE;
    iCurrentState      := 99; // Fault state
    RETURN;
END_IF;

IF NOT bSystemEnable THEN
    rBlowerSpeedZone1  := 0.0;
    rBlowerSpeedZone2  := 0.0;
    rDigesterHeaterCmd := 0.0;
    bBiogasFlareValve  := FALSE;
    bBiogasEngineValve := FALSE;
    rUVLampPower       := 0.0;
    iCurrentState      := 0; // Stopped
    RETURN;
END_IF;

iCurrentState := 1; // Running

// 1. Aeration DO Control (PI Controllers for Blowers)
// Zone 1
rDO_Error_Z1 := rDO_Setpoint - rDO_Level_Zone1;
rIntegral_Z1 := rIntegral_Z1 + (rDO_Error_Z1 * 0.1); // Assuming 100ms cycle
// Anti-windup
IF rIntegral_Z1 > 50.0 THEN rIntegral_Z1 := 50.0; END_IF;
IF rIntegral_Z1 < -50.0 THEN rIntegral_Z1 := -50.0; END_IF;
rBlowerSpeedZone1 := (rKp_DO * rDO_Error_Z1) + (rKi_DO * rIntegral_Z1);

// Zone 2
rDO_Error_Z2 := rDO_Setpoint - rDO_Level_Zone2;
rIntegral_Z2 := rIntegral_Z2 + (rDO_Error_Z2 * 0.1);
IF rIntegral_Z2 > 50.0 THEN rIntegral_Z2 := 50.0; END_IF;
IF rIntegral_Z2 < -50.0 THEN rIntegral_Z2 := -50.0; END_IF;
rBlowerSpeedZone2 := (rKp_DO * rDO_Error_Z2) + (rKi_DO * rIntegral_Z2);

// Clamp Blower Speeds
IF rBlowerSpeedZone1 > rMaxBlowerSpeed THEN rBlowerSpeedZone1 := rMaxBlowerSpeed; END_IF;
IF rBlowerSpeedZone1 < rMinBlowerSpeed THEN rBlowerSpeedZone1 := rMinBlowerSpeed; END_IF;
IF rBlowerSpeedZone2 > rMaxBlowerSpeed THEN rBlowerSpeedZone2 := rMaxBlowerSpeed; END_IF;
IF rBlowerSpeedZone2 < rMinBlowerSpeed THEN rBlowerSpeedZone2 := rMinBlowerSpeed; END_IF;

// 2. Anaerobic Digester & Biogas Harvesting
// Temperature Control (Proportional only for simplicity)
rTempError := rTargetTemp - rDigesterTemp;
IF rTempError > 0.0 THEN
    rDigesterHeaterCmd := rTempError * 10.0; 
    IF rDigesterHeaterCmd > 100.0 THEN rDigesterHeaterCmd := 100.0; END_IF;
ELSE
    rDigesterHeaterCmd := 0.0;
END_IF;

// Biogas Pressure Management
bBiogasFlareValve  := (rBiogasPressure > rFlarePressure);
bBiogasEngineValve := (rBiogasPressure >= rMinEnginePressure) AND (rBiogasPressure <= rFlarePressure);

// 3. UV Disinfection Dosing Control
// Required Intensity inversely proportional to UVT and proportional to Flow
// Dose = (Intensity * Time) -> Intensity = Dose / Time
// Time proportional to Volume / Flow. 
IF rUVTransmittance > 0.0 THEN
    // Simplified empirical calculation for UV power scaling
    rCalculatedIntensity := (rEffluentFlow / 100.0) * (100.0 / rUVTransmittance) * rUVBaseDose;
    rUVLampPower := rCalculatedIntensity;
    IF rUVLampPower > 100.0 THEN rUVLampPower := 100.0; END_IF;
    IF rUVLampPower < 30.0 THEN rUVLampPower := 30.0; END_IF; // Min strike power
ELSE
    rUVLampPower := 100.0; // Fail-safe to max if UVT sensor fails
END_IF;

// Alarm Aggregation
bGeneralAlarm := (rDO_Level_Zone1 < 0.5) OR (rDigesterTemp > 40.0) OR (rBiogasPressure > 20.0);

END_FUNCTION_BLOCK
