FUNCTION_BLOCK FB_EnroberReasoning
VAR_INPUT
    Enable : BOOL;
    UserRole : INT;
    TempPrimary : REAL;
    TempRedundant : REAL;
    BeltSpeed : REAL;
    MotorOverload : BOOL;
END_VAR
VAR_OUTPUT
    HeaterOutput : REAL;
    BlowerVelocity : REAL;
    FaultCode : INT;
