FUNCTION_BLOCK FB_Subsea_HVDC_Breaker_Control
(*
    Advanced Control System for Subsea HVDC Circuit Breaker
    Features: Ultra-fast Thomson coil magnetic actuation,
    liquid dielectric active cooling, and avalanche breakdown 
    preemptive arc extinction logic.
*)
VAR_INPUT
    bSystemEnable       : BOOL;     (* System master enable signal *)
    bEmergencyStop      : BOOL;     (* Safety relay OK signal (Normally Closed) *)
    rDC_LineVoltage_kV  : REAL;     (* Sensed HVDC Line Voltage in kilovolts *)
    rDC_LineCurrent_kA  : REAL;     (* Sensed HVDC Line Current in kiloamperes *)
    rCoolantTemp_C      : REAL;     (* Liquid dielectric coolant temperature in deg C *)
    rCoolantPress_Bar   : REAL;     (* Liquid dielectric pressure in Bar *)
    bTripCommand        : BOOL;     (* Remote or local trip command *)
    bCloseCommand       : BOOL;     (* Remote or local close command *)
END_VAR
VAR_OUTPUT
    bBreakerClosed      : BOOL;     (* Main contact status - TRUE if closed *)
    bSystemReady        : BOOL;     (* System ready for operation *)
    bFireThomsonCoil    : BOOL;     (* Trigger signal for ultra-fast opening *)
    bTriggerArcExt      : BOOL;     (* Preemptive arc extinction trigger (avalanche) *)
    rCoolantPumpSpeed   : REAL;     (* 0-100% command for active cooling pump *)
    bAlarm              : BOOL;     (* General fault alarm output *)
    iFaultCode          : INT;      (* Detailed fault code for diagnostics *)
END_VAR
VAR
    (* Internal state variables *)
    iState              : INT := 0; (* Main State Machine *)
    tTripTimer          : TON;      (* Trip execution timer *)
    tCoolingTimer       : TON;      (* Cooling system startup delay *)
    rFilteredCurrent    : REAL;     (* Low-pass filtered DC current *)
    rCurrentDerivative  : REAL;     (* di/dt for preemptive arc detection *)
    rLastCurrent        : REAL;

    (* Constants *)
    di_dt_Threshold     : REAL := 15.0; (* kA/ms for short-circuit detection *)
    MaxTempLimit        : REAL := 75.0; (* Max coolant temp *)
    MinPressLimit       : REAL := 2.5;  (* Min coolant pressure *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Hardware Checks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bBreakerClosed := FALSE;
    bFireThomsonCoil := FALSE;
    bTriggerArcExt := FALSE;
    rCoolantPumpSpeed := 0.0;
    bAlarm := TRUE;
    iFaultCode := 999; (* Emergency Stop Active *)
    iState := 0;
    RETURN;
END_IF;

(* 2. Signal Processing & Derivative Calculation (1ms Cycle Assumed) *)
rFilteredCurrent := rFilteredCurrent + 0.1 * (rDC_LineCurrent_kA - rFilteredCurrent);
rCurrentDerivative := (rFilteredCurrent - rLastCurrent) / 0.001;
rLastCurrent := rFilteredCurrent;

(* 3. Active Cooling Control *)
IF rCoolantTemp_C > MaxTempLimit OR rCoolantPress_Bar < MinPressLimit THEN
    bAlarm := TRUE;
    iFaultCode := 100; (* Cooling System Fault *)
ELSE
    IF rCoolantTemp_C > 40.0 THEN
        rCoolantPumpSpeed := (rCoolantTemp_C - 40.0) * 5.0; (* Proportional cooling *)
        IF rCoolantPumpSpeed > 100.0 THEN
            rCoolantPumpSpeed := 100.0;
        END_IF;
    ELSE
        rCoolantPumpSpeed := 20.0; (* Idle circulation *)
    END_IF;
END_IF;

(* 4. Main State Machine *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bBreakerClosed := FALSE;
        bFireThomsonCoil := FALSE;
        bTriggerArcExt := FALSE;
        IF bSystemEnable AND NOT bAlarm THEN
            iState := 10;
        END_IF;

    10: (* CHARGING & READY *)
        bSystemReady := TRUE;
        IF bCloseCommand AND NOT bTripCommand THEN
            bBreakerClosed := TRUE;
            iState := 20;
        END_IF;

    20: (* CLOSED & MONITORING *)
        bSystemReady := TRUE;
        bBreakerClosed := TRUE;

        (* Ultra-fast fault detection via di/dt or absolute overcurrent *)
        IF (rCurrentDerivative > di_dt_Threshold) OR (rDC_LineCurrent_kA > 10.0) THEN
            (* Avalanche breakdown preemptive arc extinction *)
            bTriggerArcExt := TRUE; 
            (* Thomson coil magnetic actuation *)
            bFireThomsonCoil := TRUE;
            bBreakerClosed := FALSE;
            iState := 30;
        ELSIF bTripCommand THEN
            bFireThomsonCoil := TRUE;
            bBreakerClosed := FALSE;
            iState := 30;
        END_IF;

    30: (* TRIPPED & RECOVERY *)
        tTripTimer(IN := TRUE, PT := T#2S);
        bSystemReady := FALSE;

        IF tTripTimer.Q THEN
            bFireThomsonCoil := FALSE;
            bTriggerArcExt := FALSE;
            tTripTimer(IN := FALSE);
            iFaultCode := 200; (* Breaker Tripped Successfully *)
            iState := 0; (* Require reset from Idle *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
