FUNCTION_BLOCK "CIP_System_Mut3"
VERSION : 0.1
VAR_INPUT
    User_Role : Int; // 0: Guest, 1: Operator, 2: Admin
    Start_CIP : Bool;
    Pump1_Fault : Bool;
    Pump2_Fault : Bool;
    Conductivity_Raw : Real;
END_VAR
VAR_OUTPUT
    Pump1_Cmd : Bool;
    Pump2_Cmd : Bool;
    SCADA_Data : STRUCT
        State : Int;
        Temp_SP : Real;
        Active_Pump : Int;
        Access_Granted : Bool;
    END_STRUCT;
END_VAR
VAR
    CIP_State : Int := 0;
    Active_Pump : Int := 1;
END_VAR

BEGIN
    IF User_Role < 1 THEN
        SCADA_Data.Access_Granted := FALSE;
        RETURN;
    ELSE
        SCADA_Data.Access_Granted := TRUE;
    END_IF;

    IF Active_Pump = 1 AND Pump1_Fault THEN
        Active_Pump := 2;
    ELSIF Active_Pump = 2 AND Pump2_Fault THEN
        Active_Pump := 1;
    END_IF;

    CASE CIP_State OF
        0: 
            IF Start_CIP AND User_Role >= 1 THEN CIP_State := 1; END_IF;
        1: 
            IF Conductivity_Raw < 0.5 THEN CIP_State := 2; END_IF;
        2:
            IF Conductivity_Raw > 50.0 THEN CIP_State := 3; END_IF;
        3:
            IF Conductivity_Raw > 30.0 THEN CIP_State := 4; END_IF;
        4:
            CIP_State := 5;
        5:
            IF NOT Start_CIP THEN CIP_State := 0; END_IF;
    END_CASE;

    Pump1_Cmd := (CIP_State > 0) AND (Active_Pump = 1) AND NOT Pump1_Fault;
    Pump2_Cmd := (CIP_State > 0) AND (Active_Pump = 2) AND NOT Pump2_Fault;

    SCADA_Data.State := CIP_State;
    SCADA_Data.Temp_SP := 80.0;
    SCADA_Data.Active_Pump := Active_Pump;
END_FUNCTION_BLOCK
