FUNCTION_BLOCK FB_HaberBosch_Synthesis_Control
TITLE = 'Ammonia Synthesis Advanced Control System'
VERSION : '1.0'
AUTHOR : 'Lumina AI Swarm'

// Ammonia Synthesis Control Block - Haber-Bosch Process
// Features: 
// 1. Syngas Compressor Anti-Surge Control (PID with flow/pressure override)
// 2. Catalyst Bed Thermal Runaway Protection (Multi-point temperature monitoring and emergency trip)
// 3. Condenser High-Pressure Liquid Level Control (Cascade control strategy)

VAR_INPUT
    // Compressor I/O
    rCompressorFlow          : REAL; // kg/h
    rCompressorSuctionPress  : REAL; // bar
    rCompressorDischPress    : REAL; // bar
    bCompressorRunning       : BOOL;

    // Reactor / Catalyst Bed I/O
    rBed1Temp                : REAL; // deg C
    rBed2Temp                : REAL; // deg C
    rBed3Temp                : REAL; // deg C
    rBed4Temp                : REAL; // deg C
    rReactorPressure         : REAL; // bar

    // Condenser I/O
    rCondenserLevel          : REAL; // %
    rCondenserPressure       : REAL; // bar

    // System Commands
    bEmergencyStop           : BOOL;
    bSystemReset             : BOOL;
    bStartProcess            : BOOL;
END_VAR

VAR_OUTPUT
    // Compressor Control
    rAntiSurgeValveCmd       : REAL; // % (0-100)
    bCompressorTrip          : BOOL;

    // Reactor Control
    rQuenchValve1Cmd         : REAL; // %
    rQuenchValve2Cmd         : REAL; // %
    bReactorTrip             : BOOL;

    // Condenser Control
    rLevelControlValveCmd    : REAL; // %

    // System Status
    bProcessActive           : BOOL;
    bAlarmActive             : BOOL;
    iErrorCode               : INT;
END_VAR

VAR
    // Internal States & Parameters
    rSurgeLimitLine          : REAL; 
    rSurgeControlLine        : REAL;
    rPressureRatio           : REAL;

    // PID States - Anti-surge
    rAntiSurgeKp             : REAL := 2.5;
    rAntiSurgeKi             : REAL := 1.2;
    rAntiSurgeError          : REAL;
    rAntiSurgeIntegral       : REAL;

    // Thermal Protection Settings
    rMaxBedTempAlarm         : REAL := 520.0; // deg C
    rMaxBedTempTrip          : REAL := 550.0; // deg C

    // Level Control PID States
    rLevelKp                 : REAL := 1.8;
    rLevelKi                 : REAL := 0.5;
    rLevelError              : REAL;
    rLevelIntegral           : REAL;
    rLevelSetpoint           : REAL := 50.0; // %

    // Timers
    tRunawayTimer            : TON;
    tSurgeTimer              : TON;
END_VAR

// --- START OF LOGIC ---

// 1. System State Management
IF bEmergencyStop THEN
    bProcessActive := FALSE;
    bCompressorTrip := TRUE;
    bReactorTrip := TRUE;
    rAntiSurgeValveCmd := 100.0; // Fail open
    rQuenchValve1Cmd := 100.0;   // Fail open for max cooling
    rQuenchValve2Cmd := 100.0;
    rLevelControlValveCmd := 0.0; // Fail closed to prevent blow-through
    iErrorCode := 999;
    bAlarmActive := TRUE;
    RETURN;
END_IF;

IF bSystemReset AND NOT bEmergencyStop THEN
    bCompressorTrip := FALSE;
    bReactorTrip := FALSE;
    iErrorCode := 0;
    bAlarmActive := FALSE;
    rAntiSurgeIntegral := 0.0;
    rLevelIntegral := 0.0;
END_IF;

IF bStartProcess AND NOT bCompressorTrip AND NOT bReactorTrip THEN
    bProcessActive := TRUE;
END_IF;

IF NOT bProcessActive THEN
    RETURN;
END_IF;

// 2. Syngas Compressor Anti-Surge Control
// Calculate Pressure Ratio
IF rCompressorSuctionPress > 0.0 THEN
    rPressureRatio := rCompressorDischPress / rCompressorSuctionPress;
ELSE
    rPressureRatio := 1.0;
END_IF;

// Simplified Surge Line Calculation (Operating Point)
rSurgeLimitLine := 1500.0 * SQRT(rPressureRatio - 1.0); // Example compressor map equation
rSurgeControlLine := rSurgeLimitLine * 1.10; // 10% safety margin

rAntiSurgeError := rSurgeControlLine - rCompressorFlow;

IF rAntiSurgeError > 0.0 THEN
    // We are approaching surge, open anti-surge valve
    rAntiSurgeIntegral := rAntiSurgeIntegral + (rAntiSurgeError * rAntiSurgeKi * 0.1); // Assuming 100ms cycle
    rAntiSurgeValveCmd := (rAntiSurgeKp * rAntiSurgeError) + rAntiSurgeIntegral;

    IF rAntiSurgeValveCmd > 100.0 THEN
        rAntiSurgeValveCmd := 100.0;
        rAntiSurgeIntegral := rAntiSurgeIntegral - (rAntiSurgeError * rAntiSurgeKi * 0.1); // Anti-windup
    END_IF;
ELSE
    // Safe operating zone, close valve slowly
    rAntiSurgeValveCmd := 0.0;
    rAntiSurgeIntegral := 0.0;
END_IF;

// Surge Trip Logic
tSurgeTimer(IN := (rCompressorFlow < rSurgeLimitLine) AND bCompressorRunning, PT := T#2S);
IF tSurgeTimer.Q THEN
    bCompressorTrip := TRUE;
    bProcessActive := FALSE;
    iErrorCode := 101;
    bAlarmActive := TRUE;
END_IF;

// 3. Catalyst Bed Thermal Runaway Protection
// Monitor temperatures for high-high (Trip) conditions
IF (rBed1Temp > rMaxBedTempTrip) OR 
   (rBed2Temp > rMaxBedTempTrip) OR 
   (rBed3Temp > rMaxBedTempTrip) OR 
   (rBed4Temp > rMaxBedTempTrip) THEN

    tRunawayTimer(IN := TRUE, PT := T#1S);
    IF tRunawayTimer.Q THEN
        bReactorTrip := TRUE;
        bCompressorTrip := TRUE;
        bProcessActive := FALSE;
        rQuenchValve1Cmd := 100.0;
        rQuenchValve2Cmd := 100.0;
        iErrorCode := 201;
        bAlarmActive := TRUE;
    END_IF;
ELSE
    tRunawayTimer(IN := FALSE, PT := T#1S);
END_IF;

// Quench Valve Control for Temperature Regulation
// If approaching limit, proportionally open quench valves
IF rBed1Temp > rMaxBedTempAlarm THEN
    rQuenchValve1Cmd := (rBed1Temp - rMaxBedTempAlarm) * 5.0; // P-control logic
ELSE
    rQuenchValve1Cmd := 0.0;
END_IF;

IF rBed3Temp > rMaxBedTempAlarm THEN // Pseudo for downstream beds
    rQuenchValve2Cmd := (rBed3Temp - rMaxBedTempAlarm) * 5.0;
ELSE
    rQuenchValve2Cmd := 0.0;
END_IF;

// Clamp outputs
IF rQuenchValve1Cmd > 100.0 THEN rQuenchValve1Cmd := 100.0; END_IF;
IF rQuenchValve2Cmd > 100.0 THEN rQuenchValve2Cmd := 100.0; END_IF;


// 4. Condenser High-Pressure Liquid Level Control
rLevelError := rLevelSetpoint - rCondenserLevel;

rLevelIntegral := rLevelIntegral + (rLevelError * rLevelKi * 0.1); // 100ms cycle
rLevelControlValveCmd := (rLevelKp * rLevelError * -1.0) - rLevelIntegral; // Direct acting: higher level -> open valve

// Limits & Anti-windup
IF rLevelControlValveCmd > 100.0 THEN
    rLevelControlValveCmd := 100.0;
    rLevelIntegral := rLevelIntegral - (rLevelError * rLevelKi * 0.1);
ELSIF rLevelControlValveCmd < 0.0 THEN
    rLevelControlValveCmd := 0.0;
    rLevelIntegral := rLevelIntegral - (rLevelError * rLevelKi * 0.1);
END_IF;

// Pressure Override (if pressure is too low, close valve to build pressure)
IF rCondenserPressure < 120.0 THEN // Example minimum pressure
    rLevelControlValveCmd := rLevelControlValveCmd * 0.5; // Reduce opening by 50%
END_IF;

END_FUNCTION_BLOCK
```

