FUNCTION_BLOCK FB_HDPCVD_Reactor
VAR_INPUT
    (* System and Safety Signals *)
    bEnable               : BOOL;   (* System enable signal *)
    bEmergencyStop        : BOOL;   (* Safety relay OK signal, active HIGH *)

    (* Microwave Power & ECR *)
    rMicrowaveFwdPwr      : REAL;   (* Forward microwave power (W) *)
    rMicrowaveRevPwr      : REAL;   (* Reflected microwave power (W) *)

    (* Chamber Environment *)
    rChamberPressure      : REAL;   (* Reactor chamber pressure (mTorr) *)

    (* Multi-Zone ESC & Cooling *)
    rEscTempCenter        : REAL;   (* ESC center zone temperature (deg C) *)
    rEscTempEdge          : REAL;   (* ESC edge zone temperature (deg C) *)
    rHeBacksidePress      : REAL;   (* Helium backside cooling pressure (Torr) *)

    (* Gas Precursor Delivery (MFCs) *)
    rSilaneMassFlow       : REAL;   (* SiH4 mass flow rate (sccm) *)
    rOxygenMassFlow       : REAL;   (* O2 mass flow rate (sccm) *)
END_VAR

VAR_OUTPUT
    (* Process Status *)
    bSystemReady          : BOOL;   (* System ready status *)
    bPlasmaIgnited        : BOOL;   (* Plasma ignition confirmed *)
    bDepositionActive     : BOOL;   (* Deposition step active flag *)

    (* Actuator Commands *)
    rMicrowaveTuningPos   : REAL;   (* ECR impedance matching stub position (%) *)
    rEscCoolingValve      : REAL;   (* Helium cooling mass flow valve command (%) *)
    rThrottleValvePos     : REAL;   (* Chamber pressure control butterfly valve (%) *)

    (* Diagnostics & Safety *)
    bAlarm                : BOOL;   (* Fault alarm output *)
    iErrorCode            : INT;    (* Specific fault code integer *)
END_VAR

VAR
    (* Internal state variables *)
    iState                : INT := 0;
    tTimer                : TON;
    tPlasmaTimeout        : TON;

    (* Signal Filtering (EWMA) *)
    rFilteredPress        : REAL := 0.0;
    rFilteredFwdPwr       : REAL := 0.0;
    rFilteredRevPwr       : REAL := 0.0;

    (* Process Constants *)
    ALPHA                 : REAL := 0.2;     (* Low pass filter coefficient *)
    MAX_REFL_RATIO        : REAL := 0.15;    (* 15% max reflected power ratio *)
    TARGET_PRESSURE       : REAL := 10.0;    (* mTorr target *)
    TARGET_HE_PRESS       : REAL := 8.0;     (* Torr target for He cooling *)
    STOICH_RATIO_MIN      : REAL := 1.8;     (* O2/SiH4 ratio min limit *)
    STOICH_RATIO_MAX      : REAL := 2.2;     (* O2/SiH4 ratio max limit *)

    (* Control Variables *)
    rCurrentStoich        : REAL;
    rReflectedRatio       : REAL;
    rPressureError        : REAL;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety Interlocks & Emergency Stop *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bPlasmaIgnited := FALSE;
    bDepositionActive := FALSE;
    rMicrowaveTuningPos := 0.0;
    rEscCoolingValve := 0.0;
    rThrottleValvePos := 100.0; (* Fully open to roughing line on E-Stop *)
    bAlarm := TRUE;
    iErrorCode := 999; (* Critical E-STOP fault *)
    iState := 0;
    RETURN;
END_IF;

(* 2. Sensor Signal Processing (EWMA Filtering) *)
rFilteredPress := (ALPHA * rChamberPressure) + ((1.0 - ALPHA) * rFilteredPress);
rFilteredFwdPwr := (ALPHA * rMicrowaveFwdPwr) + ((1.0 - ALPHA) * rFilteredFwdPwr);
rFilteredRevPwr := (ALPHA * rMicrowaveRevPwr) + ((1.0 - ALPHA) * rFilteredRevPwr);

(* 3. State Machine Control *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bPlasmaIgnited := FALSE;
        bAlarm := FALSE;
        iErrorCode := 0;

        IF bEnable THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PUMP_DOWN & CONDITIONING *)
        (* Proportional control for chamber throttle valve to achieve base pressure *)
        rPressureError := TARGET_PRESSURE - rFilteredPress;
        rThrottleValvePos := rThrottleValvePos + (rPressureError * 0.5); 

        (* Clamp throttle valve *)
        IF rThrottleValvePos > 100.0 THEN rThrottleValvePos := 100.0; END_IF;
        IF rThrottleValvePos < 0.0 THEN rThrottleValvePos := 0.0; END_IF;

        tTimer(IN := (ABS(rPressureError) < 0.5), PT := T#5S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* GAS_STABILIZATION & HE COOLING *)
        (* Engage ESC Helium Backside cooling *)
        IF rHeBacksidePress < TARGET_HE_PRESS THEN
            rEscCoolingValve := rEscCoolingValve + 1.0; (* Ramp up *)
        ELSE
            rEscCoolingValve := rEscCoolingValve - 1.0; (* Ramp down *)
        END_IF;

        (* Verify Stoichiometry *)
        IF rSilaneMassFlow > 0.0 THEN
            rCurrentStoich := rOxygenMassFlow / rSilaneMassFlow;
            IF rCurrentStoich >= STOICH_RATIO_MIN AND rCurrentStoich <= STOICH_RATIO_MAX THEN
                tTimer(IN := TRUE, PT := T#10S);
            ELSE
                tTimer(IN := FALSE);
            END_IF;
        END_IF;

        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* PLASMA_IGNITION (ECR Impedance Matching) *)
        IF rFilteredFwdPwr > 500.0 THEN
            (* Calculate reflected ratio *)
            rReflectedRatio := rFilteredRevPwr / rFilteredFwdPwr;

            (* Dynamic impedance stub tuning (hill-climbing abstraction) *)
            IF rReflectedRatio > 0.05 THEN
                rMicrowaveTuningPos := rMicrowaveTuningPos + (rReflectedRatio * 10.0);
                IF rMicrowaveTuningPos > 100.0 THEN rMicrowaveTuningPos := 100.0; END_IF;
            END_IF;

            (* Ignition confirmation threshold *)
            IF rReflectedRatio < MAX_REFL_RATIO THEN
                bPlasmaIgnited := TRUE;
                iState := 40;
            END_IF;
        END_IF;

        (* Timeout safety *)
        tPlasmaTimeout(IN := TRUE, PT := T#15S);
        IF tPlasmaTimeout.Q AND NOT bPlasmaIgnited THEN
            iErrorCode := 301; (* Ignition failure *)
            iState := 99;
        END_IF;

    40: (* DEPOSITION_ACTIVE *)
        bDepositionActive := TRUE;

        (* Continuous impedance monitoring *)
        IF rFilteredFwdPwr > 0.0 THEN
            rReflectedRatio := rFilteredRevPwr / rFilteredFwdPwr;
            IF rReflectedRatio > MAX_REFL_RATIO THEN
                iErrorCode := 401; (* Plasma instability / Matching lost *)
                iState := 99;
            END_IF;
        END_IF;

        (* Process timer for deposition layer thickness *)
        tTimer(IN := TRUE, PT := T#120S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            bDepositionActive := FALSE;
            iState := 50;
        END_IF;

    50: (* POST_DEPOSITION_PURGE *)
        bPlasmaIgnited := FALSE;
        rMicrowaveTuningPos := 0.0;

        tTimer(IN := TRUE, PT := T#20S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            iState := 0; (* Process complete, return to IDLE *)
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bPlasmaIgnited := FALSE;
        bDepositionActive := FALSE;
        bAlarm := TRUE;

        (* Safe actuator states *)
        rMicrowaveTuningPos := 0.0;
        rEscCoolingValve := 0.0;
        rThrottleValvePos := 100.0; 

        IF NOT bEnable THEN
            bAlarm := FALSE;
            iErrorCode := 0;
            iState := 0; (* Reset fault on disable *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

