    bQuenchActive : BOOL; // Glass is in the quenching section
    bAlarmActive : BOOL; // System fault
    iAlarmCode : INT; // Diagnostics code
    rEstimatedThermalStress : REAL; // Calculated internal stress (MPa)
END_VAR
VAR
    iState : INT := 0; 
    rOscillationPhase : REAL := 0.0;
    rMaxTempDiff : REAL := 0.0;
    iIndex : INT;
    rTempSum : REAL := 0.0;
    rTempAvg : REAL := 0.0;

    // PID internal variables (simplified)
    rError1 : REAL;
    rError2 : REAL;
    rError3 : REAL;
    rIntegral1 : REAL := 0.0;
    rIntegral2 : REAL := 0.0;
    rIntegral3 : REAL := 0.0;
    rKp : REAL := 2.5;
    rKi : REAL := 0.15;
    rMaxPWM : REAL := 100.0;

    // Constants for Thermal Stress
    cThermalExpansionCoef : REAL := 9.0E-6;
    cYoungsModulus : REAL := 72000.0; 
END_VAR

// ---- SAFETY AND INTERLOCKS ----
IF bEmergencyStop THEN
    rHeaterPWM_Zone1 := 0.0;
    rHeaterPWM_Zone2 := 0.0;
    rHeaterPWM_Zone3 := 0.0;
    rRollerDriveVelocity := 0.0;
    rAirKnifeValve_Top := 0.0;
    rAirKnifeValve_Bot := 0.0;
    bAlarmActive := TRUE;
    iAlarmCode := 999; // E-Stop triggered
    iState := 0;
    RETURN;
END_IF

IF NOT bEnable THEN
    iState := 0;
    bSystemReady := FALSE;
    RETURN;
END_IF

// ---- THERMAL CONTROL (PID LOOPS) ----
// Zone 1
rError1 := rSetPoint_TempZone1 - rActual_TempZone1;
rIntegral1 := rIntegral1 + (rError1 * rTimeStep);
rHeaterPWM_Zone1 := (rKp * rError1) + (rKi * rIntegral1);
IF rHeaterPWM_Zone1 > rMaxPWM THEN rHeaterPWM_Zone1 := rMaxPWM; END_IF
IF rHeaterPWM_Zone1 < 0.0 THEN rHeaterPWM_Zone1 := 0.0; END_IF

// Zone 2
rError2 := rSetPoint_TempZone2 - rActual_TempZone2;
rIntegral2 := rIntegral2 + (rError2 * rTimeStep);
rHeaterPWM_Zone2 := (rKp * rError2) + (rKi * rIntegral2);
IF rHeaterPWM_Zone2 > rMaxPWM THEN rHeaterPWM_Zone2 := rMaxPWM; END_IF
IF rHeaterPWM_Zone2 < 0.0 THEN rHeaterPWM_Zone2 := 0.0; END_IF

// Zone 3
rError3 := rSetPoint_TempZone3 - rActual_TempZone3;
rIntegral3 := rIntegral3 + (rError3 * rTimeStep);
rHeaterPWM_Zone3 := (rKp * rError3) + (rKi * rIntegral3);
IF rHeaterPWM_Zone3 > rMaxPWM THEN rHeaterPWM_Zone3 := rMaxPWM; END_IF
IF rHeaterPWM_Zone3 < 0.0 THEN rHeaterPWM_Zone3 := 0.0; END_IF

// Ready Condition Validation
IF (ABS(rError1) < 5.0) AND (ABS(rError2) < 5.0) AND (ABS(rError3) < 5.0) THEN
    bSystemReady := TRUE;
ELSE
    bSystemReady := FALSE;
END_IF

// ---- CERAMIC ROLLER KINEMATICS ----
// Calculate oscillating transport to prevent optical distortion (roller wave)
rOscillationPhase := rOscillationPhase + (2.0 * 3.14159 * rOscillationFrequency * rTimeStep);
IF rOscillationPhase > 6.28318 THEN
    rOscillationPhase := rOscillationPhase - 6.28318;
END_IF
rRollerDriveVelocity := rRollerSpeedBase + (rOscillationAmplitude * rOscillationFrequency * 6.28318 * COS(rOscillationPhase));

// ---- QUENCH COOLING & AIR KNIFE PROFILING ----
// Adjust quenching based on glass thickness and thermal mass
IF iState = 10 THEN // State 10: Glass entering Quench section
    bQuenchActive := TRUE;
    // Non-linear profiling logic based on thickness
    rAirKnifeValve_Top := (rGlassThickness * 10.0) + (rAirKnifePressure_Top * 0.5);
    rAirKnifeValve_Bot := (rGlassThickness * 12.0) + (rAirKnifePressure_Bot * 0.5); // Bottom requires more support pressure

    IF rAirKnifeValve_Top > 100.0 THEN rAirKnifeValve_Top := 100.0; END_IF
    IF rAirKnifeValve_Bot > 100.0 THEN rAirKnifeValve_Bot := 100.0; END_IF
ELSE
    bQuenchActive := FALSE;
    rAirKnifeValve_Top := 0.0;
    rAirKnifeValve_Bot := 0.0;
END_IF

// ---- THERMAL STRESS MAPPING ----
// Map cross-sectional temperature delta to estimate stress (MPa)
rTempSum := 0.0;
rMaxTempDiff := 0.0;
FOR iIndex := 0 TO 99 DO
    rTempSum := rTempSum + aThermalScannerMatrix[iIndex];
END_FOR
rTempAvg := rTempSum / 100.0;

FOR iIndex := 0 TO 99 DO
    IF ABS(aThermalScannerMatrix[iIndex] - rTempAvg) > rMaxTempDiff THEN
        rMaxTempDiff := ABS(aThermalScannerMatrix[iIndex] - rTempAvg);
    END_IF
END_FOR

// Approximate stress = E * alpha * DeltaT
rEstimatedThermalStress := cYoungsModulus * cThermalExpansionCoef * rMaxTempDiff;

// Alarm generation for high stress
IF rEstimatedThermalStress > 15.0 THEN // Threshold 15 MPa
    bAlarmActive := TRUE;
    iAlarmCode := 101; // Optical distortion or shatter risk
ELSE
    bAlarmActive := FALSE;
    iAlarmCode := 0;
END_IF

END_FUNCTION_BLOCK
