FUNCTION_BLOCK FB_ROV_CableTrenchingControl
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety circuit healthy signal (active high) *)
    rJetPressure_Bar        : REAL;     (* Measured high-pressure water jetting sword pressure [Bar] *)
    rSoilAcousticFeedback   : REAL;     (* Processed acoustic feedback estimating soil shear strength [kPa] *)
    rCableTension_kN        : REAL;     (* Measured tension of the inter-array cable being laid [kN] *)
    rROVSpeed_kts           : REAL;     (* Forward trenching speed over ground [knots] *)
    rTargetTension_kN       : REAL;     (* Desired cable slack/tension setpoint [kN] *)
    rTargetDepth_m          : REAL;     (* Commanded sword penetration depth [m] *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Trencher system ready and initialized *)
    bJettingActive          : BOOL;     (* High-pressure water jetting is engaged *)
    rTensionCtrlSignal      : REAL;     (* Output to winch/tensioner drive [0.0 - 100.0 %] *)
    rSwordDepthCtrlSignal   : REAL;     (* Output to sword hydraulic pitch/depth actuators [0.0 - 100.0 %] *)
    bAlarmTensionHigh       : BOOL;     (* Alarm: Cable tension exceeds critical safety limit *)
    bAlarmJetPressureLow    : BOOL;     (* Alarm: Water jetting pressure insufficient for soil type *)
    iOperatingState         : INT;      (* Current control state machine step *)
END_VAR
VAR
    iState                  : INT := 0;
    tStartDelay             : TON;
    tJetPressureFilter      : TON;
    rIntegralErrorTension   : REAL := 0.0;
    rTensionError           : REAL := 0.0;
    Kp_Tension              : REAL := 2.5;
    Ki_Tension              : REAL := 0.15;
    rMaxTensionLimit        : REAL := 150.0; (* 150 kN absolute limit *)
    rMinJetPressureReq      : REAL;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Enable Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bJettingActive := FALSE;
    rTensionCtrlSignal := 0.0;
    rSwordDepthCtrlSignal := 0.0;
    bAlarmTensionHigh := FALSE;
    bAlarmJetPressureLow := FALSE;
    iState := 0;
    iOperatingState := iState;
    RETURN;
END_IF;

(* Critical Tension Monitoring *)
IF rCableTension_kN > rMaxTensionLimit THEN
    bAlarmTensionHigh := TRUE;
    (* Force emergency tension relief *)
    rTensionCtrlSignal := 0.0; 
ELSE
    bAlarmTensionHigh := FALSE;
END_IF;

(* Determine required jetting pressure based on dynamic acoustic soil shear feedback *)
(* Heuristic: Base pressure 50 Bar + 2.5 * Soil Shear Strength (kPa) *)
rMinJetPressureReq := 50.0 + (rSoilAcousticFeedback * 2.5);
IF bJettingActive AND (rJetPressure_Bar < rMinJetPressureReq) THEN
    bAlarmJetPressureLow := TRUE;
ELSE
    bAlarmJetPressureLow := FALSE;
END_IF;

(* Primary State Machine for ROV Trenching Operations *)
CASE iState OF
    0: (* IDLE - Awaiting Start *)
        bSystemReady := TRUE;
        bJettingActive := FALSE;
        rTensionCtrlSignal := 50.0; (* Hold tension steady at neutral *)
        rSwordDepthCtrlSignal := 0.0; (* Retract sword *)

        IF bEnable AND NOT bAlarmTensionHigh THEN
            iState := 10;
        END_IF;

    10: (* INITIALIZE JETTING - Spool up high pressure pumps *)
        bJettingActive := TRUE;
        rSwordDepthCtrlSignal := 0.0;

        tStartDelay(IN := TRUE, PT := T#5S);
        IF tStartDelay.Q THEN
            tStartDelay(IN := FALSE);
            IF NOT bAlarmJetPressureLow THEN
                iState := 20;
            END_IF;
        END_IF;

    20: (* LOWER SWORD AND TRENCH - Main operation phase *)
        (* Closed-loop PI control for dynamic cable slack management *)
        rTensionError := rCableTension_kN - rTargetTension_kN;

        (* Anti-windup for integral term *)
        IF (rTensionCtrlSignal < 100.0 AND rTensionCtrlSignal > 0.0) THEN
            rIntegralErrorTension := rIntegralErrorTension + (rTensionError * 0.1); (* Assuming 100ms cycle time *)
        END_IF;

        rTensionCtrlSignal := (Kp_Tension * rTensionError) + (Ki_Tension * rIntegralErrorTension);

        (* Saturate Tension Control Output between 0% and 100% *)
        IF rTensionCtrlSignal > 100.0 THEN
            rTensionCtrlSignal := 100.0;
        ELSIF rTensionCtrlSignal < 0.0 THEN
            rTensionCtrlSignal := 0.0;
        END_IF;

        (* Sword depth profiling based on ROV speed and target depth *)
        (* Simple proportional deployment based on speed to prevent sword snapping *)
        rSwordDepthCtrlSignal := rTargetDepth_m * 10.0; (* Scale depth command *)
        IF rROVSpeed_kts > 2.5 THEN
            (* Slow down penetration rate if ROV is moving too fast *)
            rSwordDepthCtrlSignal := rSwordDepthCtrlSignal * 0.5;
        END_IF;

        (* Saturate Sword Depth Signal *)
        IF rSwordDepthCtrlSignal > 100.0 THEN
            rSwordDepthCtrlSignal := 100.0;
        END_IF;

        (* Exit condition *)
        IF NOT bEnable THEN
            iState := 30;
        END_IF;

    30: (* SHUTDOWN SEQUENCE *)
        bJettingActive := FALSE;
        rSwordDepthCtrlSignal := 0.0; (* Retract sword immediately *)
        (* Keep tension controller active for safety until ROV stops *)
        IF rROVSpeed_kts < 0.1 THEN
            rTensionCtrlSignal := 50.0; (* Hold neutral tension *)
            iState := 0;
        END_IF;

END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
