FUNCTION_BLOCK FB_AeroAutoClave_Cure_Ctrl
TITLE = 'Aerospace Composite Autoclave Curing Controller'
// -----------------------------------------------------------------------------
// Description:
// Controls thermal gradients, nitrogen pressurization cascades, and 
// resin exothermic reaction active cooling loops for commercial aircraft 
// composite curing cycles.
// -----------------------------------------------------------------------------

VAR_INPUT
    bStartCycle            : BOOL; // Initiate curing cycle
    bEmergencyStop         : BOOL; // E-Stop
    rTargetTemp            : REAL; // Target curing temperature (deg C)
    rTargetPressure        : REAL; // Target curing pressure (Bar)
    rRampRateTemp          : REAL; // Temperature ramp rate (deg C / min)
    rRampRatePress         : REAL; // Pressure ramp rate (Bar / min)
    rDwellTime             : REAL; // Time to hold at target temperature (min)

    // Sensor Inputs
    arPartTemps            : ARRAY[1..12] OF REAL; // Part thermocouples
    arAirTemps             : ARRAY[1..4] OF REAL;  // Autoclave ambient air temps
    rChamberPressure       : REAL; // Current chamber pressure (Bar)
    rCoolingFlow           : REAL; // Active cooling flow rate (L/min)
    bN2SupplyOk            : BOOL; // Nitrogen supply interlock
END_VAR

VAR_OUTPUT
    bHeatingCmd            : BOOL;
    rHeaterOutput          : REAL; // 0-100% PWM
    bCoolingCmd            : BOOL;
    rCoolerOutput          : REAL; // 0-100% valve position
    bPressurizeCmd         : BOOL;
    rN2ValvePos            : REAL; // Nitrogen inlet valve 0-100%
    bDepressurizeCmd       : BOOL;
    rVentValvePos          : REAL; // Vent valve 0-100%

    iCycleState            : INT;  // 0=Idle, 1=RampUp, 2=Dwell, 3=ExothermCooling, 4=RampDown, 5=Complete, 99=Error
    bCycleComplete         : BOOL;
    bAlarmActive           : BOOL;
    iAlarmCode             : INT;
    rMaxTempGradient       : REAL; // Real-time calculation of worst case delta T
END_VAR

VAR
    rtStartEdge            : R_TRIG;
    tDwellTimer            : TON;
    rCurrentSetpoint       : REAL;
    rCurrentPressSetpoint  : REAL;

    // PID Controllers
    TempPID                : FB_PID_Advanced;
    PressPID               : FB_PID_Advanced;

    rHighestPartTemp       : REAL;
    rLowestPartTemp        : REAL;
    rAvgPartTemp           : REAL;
    i                      : INT;

    // Exotherm Management
    rTempDerivative        : REAL;
    rLastAvgTemp           : REAL;
    tSampleTimer           : TON;
    bExothermDetected      : BOOL;

    // State Tracking
    iStateTimer            : DINT; // seconds
END_VAR

// -----------------------------------------------------------------------------
// IMPLEMENTATION
// -----------------------------------------------------------------------------

// Safety & Interlocks
IF bEmergencyStop THEN
    bHeatingCmd := FALSE;
    bPressurizeCmd := FALSE;
    bCoolingCmd := TRUE;
    bDepressurizeCmd := TRUE;
    rHeaterOutput := 0.0;
    rCoolerOutput := 100.0; // Max cooling
    rN2ValvePos := 0.0;
    rVentValvePos := 100.0; // Vent chamber
    iCycleState := 99;
    iAlarmCode := 1000;
    bAlarmActive := TRUE;
    RETURN;
END_IF;

IF NOT bN2SupplyOk AND iCycleState > 0 AND iCycleState < 5 THEN
    iCycleState := 99;
    iAlarmCode := 2001; // Nitrogen loss
    bAlarmActive := TRUE;
END_IF;

rtStartEdge(CLK := bStartCycle);

// Temperature Analysis (Gradients & Exotherm)
rHighestPartTemp := arPartTemps[1];
rLowestPartTemp := arPartTemps[1];
rAvgPartTemp := 0.0;

FOR i := 1 TO 12 DO
    IF arPartTemps[i] > rHighestPartTemp THEN
        rHighestPartTemp := arPartTemps[i];
    END_IF;
    IF arPartTemps[i] < rLowestPartTemp THEN
        rLowestPartTemp := arPartTemps[i];
    END_IF;
    rAvgPartTemp := rAvgPartTemp + arPartTemps[i];
END_FOR;
rAvgPartTemp := rAvgPartTemp / 12.0;
rMaxTempGradient := rHighestPartTemp - rLowestPartTemp;

// Exotherm detection (Rate of rise > normal ramp rate)
tSampleTimer(IN := NOT tSampleTimer.Q, PT := T#1S);
IF tSampleTimer.Q THEN
    rTempDerivative := (rAvgPartTemp - rLastAvgTemp) * 60.0; // deg/min
    rLastAvgTemp := rAvgPartTemp;
    IF iCycleState = 2 AND (rTempDerivative > (rRampRateTemp * 1.5)) THEN
        bExothermDetected := TRUE;
    ELSE
        bExothermDetected := FALSE;
    END_IF;
END_IF;

// State Machine
CASE iCycleState OF
    0: // Idle
        bHeatingCmd := FALSE; bCoolingCmd := FALSE;
        bPressurizeCmd := FALSE; bDepressurizeCmd := FALSE;
        rHeaterOutput := 0.0; rCoolerOutput := 0.0;
        rN2ValvePos := 0.0; rVentValvePos := 0.0;
        IF rtStartEdge.Q AND NOT bAlarmActive THEN
            iCycleState := 1;
            rCurrentSetpoint := arAirTemps[1];
            rCurrentPressSetpoint := rChamberPressure;
        END_IF;

    1: // Ramp Up
        // Calculate new setpoints based on scan cycle time and ramp rates
        rCurrentSetpoint := rCurrentSetpoint + (rRampRateTemp / 600.0); // Assuming 100ms cycle
        IF rCurrentSetpoint >= rTargetTemp THEN
            rCurrentSetpoint := rTargetTemp;
        END_IF;

        rCurrentPressSetpoint := rCurrentPressSetpoint + (rRampRatePress / 600.0);
        IF rCurrentPressSetpoint >= rTargetPressure THEN
            rCurrentPressSetpoint := rTargetPressure;
        END_IF;

        // Check transition to Dwell
        IF (rAvgPartTemp >= (rTargetTemp - 2.0)) AND (rChamberPressure >= (rTargetPressure - 0.2)) THEN
            iCycleState := 2;
        END_IF;

        // Check for gradient violation
        IF rMaxTempGradient > 15.0 THEN
            // Hold ramp
            rCurrentSetpoint := rCurrentSetpoint - (rRampRateTemp / 600.0);
        END_IF;

    2: // Dwell
        rCurrentSetpoint := rTargetTemp;
        rCurrentPressSetpoint := rTargetPressure;

        tDwellTimer(IN := TRUE, PT := REAL_TO_TIME(rDwellTime * 60000.0));

        IF bExothermDetected THEN
            iCycleState := 3;
        ELSIF tDwellTimer.Q THEN
            iCycleState := 4;
            tDwellTimer(IN := FALSE, PT := T#0S);
        END_IF;

    3: // Exotherm Management
        // Aggressive active cooling overrides normal PID
        rCurrentSetpoint := rTargetTemp - 5.0; // Drop ambient air setpoint
        IF rTempDerivative < 0.5 THEN // Reaction stabilized
            iCycleState := 2; // Return to normal dwell
        END_IF;

    4: // Ramp Down
        rCurrentSetpoint := rCurrentSetpoint - (rRampRateTemp / 600.0);
        IF rCurrentSetpoint <= 40.0 THEN // Safe temp to open
            iCycleState := 5;
        END_IF;
        // Maintain pressure until cool
        rCurrentPressSetpoint := rTargetPressure;

    5: // Complete
        bHeatingCmd := FALSE; bCoolingCmd := FALSE;
        bPressurizeCmd := FALSE; bDepressurizeCmd := TRUE; // Vent pressure
        rHeaterOutput := 0.0; rCoolerOutput := 0.0;
        rN2ValvePos := 0.0; rVentValvePos := 100.0;
        bCycleComplete := TRUE;

        IF rChamberPressure < 0.1 THEN
            iCycleState := 0; // Ready for next
        END_IF;

    99: // Error state handled by safety block above
        ;
END_CASE;

// Execute PIDs (if not overridden by manual/safety)
IF iCycleState > 0 AND iCycleState < 5 THEN
    TempPID(
        bEnable := TRUE,
        rSetpoint := rCurrentSetpoint,
        rProcessValue := arAirTemps[1], // Control off air temp
        rKp := 2.5, rTi := 120.0, rTd := 5.0,
        rOutputMin := -100.0, rOutputMax := 100.0
    );

    IF TempPID.rOutput > 0.0 THEN
        bHeatingCmd := TRUE; bCoolingCmd := FALSE;
        rHeaterOutput := TempPID.rOutput;
        rCoolerOutput := 0.0;
    ELSE
        bHeatingCmd := FALSE; bCoolingCmd := TRUE;
        rHeaterOutput := 0.0;
        rCoolerOutput := ABS(TempPID.rOutput);
    END_IF;

    PressPID(
        bEnable := TRUE,
        rSetpoint := rCurrentPressSetpoint,
        rProcessValue := rChamberPressure,
        rKp := 1.2, rTi := 45.0, rTd := 0.0,
        rOutputMin := -100.0, rOutputMax := 100.0
    );

    IF PressPID.rOutput > 0.0 THEN
        bPressurizeCmd := TRUE; bDepressurizeCmd := FALSE;
        rN2ValvePos := PressPID.rOutput;
        rVentValvePos := 0.0;
    ELSE
        bPressurizeCmd := FALSE; bDepressurizeCmd := TRUE;
        rN2ValvePos := 0.0;
        rVentValvePos := ABS(PressPID.rOutput);
    END_IF;
END_IF;

END_FUNCTION_BLOCK
