FUNCTION_BLOCK "Solar_Inverter_Breadth"
VAR_INPUT
    PV_Voltage : REAL;
    PV_Current : REAL;
    Grid_Voltage : REAL;
    Grid_Freq : REAL;
    IGBT_Temp : REAL;
    Reset_Faults : BOOL;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : REAL;
    Sync_OK : BOOL;
    Fault_Word : WORD;
    PN_Status : WORD;
END_VAR
VAR
    Prev_Power : REAL;
    Prev_Voltage : REAL;
    Power_Limit : REAL;
    Max_Temp : REAL := 85.0;
    Step_Size : REAL := 0.01;
END_VAR
BEGIN
    // Fault Diagnostics
    IF Reset_Faults THEN Fault_Word := 16#0000; END_IF;
    IF PV_Voltage > 1000.0 THEN Fault_Word := Fault_Word OR 16#0001; END_IF; // DC Overvoltage
    IF PV_Current > 500.0 THEN Fault_Word := Fault_Word OR 16#0002; END_IF; // DC Overcurrent
    IF Grid_Voltage < 50.0 THEN Fault_Word := Fault_Word OR 16#0004; END_IF; // Grid Loss

    // Thermal Derating
    IF IGBT_Temp > Max_Temp THEN
        Power_Limit := 1.0 - ((IGBT_Temp - Max_Temp) * 0.05);
        IF Power_Limit < 0.0 THEN Power_Limit := 0.0; END_IF;
    ELSE
        Power_Limit := 1.0;
    END_IF;

    // MPPT
    IF Fault_Word = 16#0000 THEN
        VAR Current_Power : REAL := PV_Voltage * PV_Current;
        VAR deltaP : REAL := Current_Power - Prev_Power;
        VAR deltaV : REAL := PV_Voltage - Prev_Voltage;
        IF deltaP <> 0.0 THEN
            IF (deltaP > 0.0 AND deltaV > 0.0) OR (deltaP < 0.0 AND deltaV < 0.0) THEN
                PWM_Duty_Cycle := PWM_Duty_Cycle - Step_Size;
            ELSE
                PWM_Duty_Cycle := PWM_Duty_Cycle + Step_Size;
            END_IF;
        END_IF;
        PWM_Duty_Cycle := PWM_Duty_Cycle * Power_Limit;
        Prev_Power := Current_Power; Prev_Voltage := PV_Voltage;
    ELSE
        PWM_Duty_Cycle := 0.0;
    END_IF;

    // Grid Sync
    Sync_OK := (Grid_Voltage > 210.0 AND Grid_Voltage < 250.0) AND (Grid_Freq > 49.5 AND Grid_Freq < 50.5);

    // Profinet Comm mapping (simulated output to PN interface)
    PN_Status := Fault_Word;
END_FUNCTION_BLOCK
