FUNCTION_BLOCK FB_VeneerPeelingLathe_Advanced
VAR_INPUT
    rBlockDiameterAct   : REAL; (* Current log diameter in mm *)
    rPeelingSpeedTarget : REAL; (* Target veneer sheet velocity mm/s *)
    bKnifeEngaged       : BOOL; (* Start peeling process *)
    bDefectDetected     : BOOL; (* Optical scanner defect flag *)
    rDefectPosition     : REAL; (* Position of defect in mm *)
    rVeneerThickness    : REAL; (* Target thickness of veneer mm *)
    bEmergencyStop      : BOOL;
END_VAR
VAR_OUTPUT
    rSpindleRPM         : REAL; (* Command RPM for spindle motor *)
    rCarriageVelocity   : REAL; (* Command velocity for knife carriage mm/s *)
    bClipKnifeActivate  : BOOL; (* Fire clipping knife for defects *)
    bProcessActive      : BOOL; (* Lathe is actively peeling *)
    rSpindleTorqueLimit : REAL; (* Adaptive torque limit *)
END_VAR
VAR
    rCircumference      : REAL;
    rTargetRPM          : REAL;
    rCarriageAdvance    : REAL;
    bClippingTimer      : TON;
    rDistanceToClip     : REAL;
    rClippingDelay      : TIME;
    rMinDiameter        : REAL := 100.0; (* Minimum core diameter *)
    PI                  : REAL := 3.14159265359;
END_VAR

IF bEmergencyStop THEN
    rSpindleRPM := 0.0;
    rCarriageVelocity := 0.0;
    bClipKnifeActivate := FALSE;
    bProcessActive := FALSE;
    RETURN;
END_IF;

IF NOT bKnifeEngaged OR (rBlockDiameterAct <= rMinDiameter) THEN
    rSpindleRPM := 0.0;
    rCarriageVelocity := 0.0;
    bProcessActive := FALSE;
    RETURN;
END_IF;

bProcessActive := TRUE;

(* 1. Kinematics for Spindle RPM (Constant Surface Speed) *)
rCircumference := rBlockDiameterAct * PI;
IF rCircumference > 0.0 THEN
    rTargetRPM := (rPeelingSpeedTarget * 60.0) / rCircumference;
ELSE
    rTargetRPM := 0.0;
END_IF;

(* Bound RPM *)
IF rTargetRPM > 1500.0 THEN
    rSpindleRPM := 1500.0;
ELSE
    rSpindleRPM := rTargetRPM;
END_IF;

(* 2. Knife Carriage Synchronization *)
(* Advance per revolution must equal desired veneer thickness *)
rCarriageAdvance := rVeneerThickness; (* mm per rev *)
rCarriageVelocity := (rSpindleRPM / 60.0) * rCarriageAdvance; (* mm/s *)

(* 3. Torque Limit based on block size (larger block requires more torque) *)
rSpindleTorqueLimit := rBlockDiameterAct * 1.5;

(* 4. Optical Defect Clipping Logic *)
(* Calculate time until defect reaches the clipping knife *)
(* Distance from optical scanner to clip knife = 2000 mm *)
rDistanceToClip := 2000.0 - rDefectPosition;
IF bDefectDetected AND rDistanceToClip > 0.0 THEN
    rClippingDelay := REAL_TO_TIME(REAL_TO_DINT((rDistanceToClip / rPeelingSpeedTarget) * 1000.0));
END_IF;

bClippingTimer(IN:=bDefectDetected, PT:=rClippingDelay);

IF bClippingTimer.Q THEN
    bClipKnifeActivate := TRUE;
ELSE
    bClipKnifeActivate := FALSE;
END_IF;

END_FUNCTION_BLOCK
