FUNCTION_BLOCK FB_VerticalFarmController
// ==============================================================================
// Block Name  : FB_VerticalFarmController
// Description : Commercial Hydroponic Vertical Farming Controller
//               Handles NFT fertigation mass blending, LED PPFD ramping, 
//               and HVAC dehumidification for high-density vertical racks.
// Standard    : IEC 61131-3 (Structured Text)
// Author      : Lumina AI Cloud Swarm
// ==============================================================================

VAR_INPUT
    bSystemEnable      : BOOL;            // Master system enable flag
    rZoneTempActual    : REAL;            // Current zone temperature [C]
    rZoneHumActual     : REAL;            // Current zone relative humidity [%]
    rReservoirPH       : REAL;            // Nutrient solution pH level
    rReservoirEC       : REAL;            // Nutrient solution Electrical Conductivity [mS/cm]
    rReservoirLevel    : REAL;            // Main reservoir volume level [%]
    tCurrentTime       : TIME_OF_DAY;     // Current RTC time
    tLightStart        : TIME_OF_DAY := TOD#06:00:00; // Photoperiod Start
    tLightEnd          : TIME_OF_DAY := TOD#22:00:00; // Photoperiod End
    rTargetPPFD        : REAL := 800.0;   // Target PPFD [umol/m2/s] during day
    rTargetPH          : REAL := 5.8;     // Target pH setpoint (Optimal for most greens)
    rTargetEC          : REAL := 2.2;     // Target EC setpoint (Aggressive growth)
    rTargetTemp        : REAL := 23.0;    // Target Temperature [C]
    rTargetHumidity    : REAL := 55.0;    // Target Humidity [%]
    rDehumDeadband     : REAL := 2.5;     // Humidity deadband [%]
END_VAR

VAR_OUTPUT
    bPumpNutrientA     : BOOL;            // Nutrient A mass blending pump
    bPumpNutrientB     : BOOL;            // Nutrient B mass blending pump
    bPumpPH_Down       : BOOL;            // pH Down (Acid) dosing pump
    bPumpPH_Up         : BOOL;            // pH Up (Base) dosing pump
    rLEDPWM_Output     : REAL;            // LED dimming control signal (0.0 - 100.0%)
    bHVAC_Cooling      : BOOL;            // HVAC Cooling compressor contactor
    bHVAC_Dehum        : BOOL;            // HVAC Dehumidification mode active
    bMainIrrigationPump: BOOL;            // NFT manifold distribution pump
    iSystemState       : INT;             // Current state machine integer
    bAlarmActive       : BOOL;            // Global alarm aggregate flag
    iAlarmCode         : INT;             // Active alarm code (0 = None)
END_VAR

VAR
    // Internal Timers and state variables
    eFertigationState  : INT := 0;        // 0=IDLE, 1=EVAL, 2=DOSE_PH, 3=DOSE_NUTS, 4=MIX, 5=ERROR
    fbTimerDoseNutrient: TON;
    fbTimerDosePH      : TON;
    fbTimerMix         : TON;
    fbRampLED          : TON;

    rCurrentPPFD       : REAL := 0.0;
    bLightPeriodActive : BOOL;

    rErrorPH           : REAL;
    rErrorEC           : REAL;
    rErrorTemp         : REAL;
    rErrorHum          : REAL;

    // Configurable Timings
    tDoseTimePH        : TIME := T#2S;
    tDoseTimeNutrients : TIME := T#3S;
    tMixTime           : TIME := T#5M;

    // Ramping variables
    rRampRate          : REAL := 5.0;     // PPFD change per cycle
END_VAR

// ==============================================================================
// SYSTEM ENABLE & SAFETY CHECKS
// ==============================================================================
IF NOT bSystemEnable THEN
    bPumpNutrientA := FALSE;
    bPumpNutrientB := FALSE;
    bPumpPH_Down := FALSE;
    bPumpPH_Up := FALSE;
    rLEDPWM_Output := 0.0;
    bHVAC_Cooling := FALSE;
    bHVAC_Dehum := FALSE;
    bMainIrrigationPump := FALSE;
    iSystemState := 0;
    bAlarmActive := FALSE;
    RETURN;
END_IF;

// Check critical alarms (e.g., low reservoir level protects pumps)
IF rReservoirLevel < 10.0 THEN
    bAlarmActive := TRUE;
    iAlarmCode := 101; // Low level alarm
    bMainIrrigationPump := FALSE;
    eFertigationState := 5; // Force Error State
ELSE
    bAlarmActive := FALSE;
    iAlarmCode := 0;
    bMainIrrigationPump := TRUE; // Continuous NFT flow if level is safe
END_IF;

// ==============================================================================
// PHOTOPERIOD & LED PPFD RAMPING
// ==============================================================================
// Determine if we are within the daylight window
IF (tLightStart < tLightEnd) THEN
    bLightPeriodActive := (tCurrentTime >= tLightStart) AND (tCurrentTime <= tLightEnd);
ELSE
    // Handles overnight lighting (e.g., 20:00 to 04:00)
    bLightPeriodActive := (tCurrentTime >= tLightStart) OR (tCurrentTime <= tLightEnd);
END_IF;

IF bLightPeriodActive THEN
    // Sunrise Ramping (Proportional approach towards target)
    IF rCurrentPPFD < rTargetPPFD THEN
        rCurrentPPFD := rCurrentPPFD + rRampRate;
        IF rCurrentPPFD > rTargetPPFD THEN
            rCurrentPPFD := rTargetPPFD;
        END_IF;
    END_IF;
ELSE
    // Sunset Ramping
    IF rCurrentPPFD > 0.0 THEN
        rCurrentPPFD := rCurrentPPFD - rRampRate;
        IF rCurrentPPFD < 0.0 THEN
            rCurrentPPFD := 0.0;
        END_IF;
    END_IF;
END_IF;

// Convert PPFD to PWM % (Assuming linear LED driver 0-100% matches 0-Max PPFD)
rLEDPWM_Output := (rCurrentPPFD / 1000.0) * 100.0; // Scaled to max 1000 PPFD
IF rLEDPWM_Output > 100.0 THEN
    rLEDPWM_Output := 100.0;
END_IF;

// ==============================================================================
// HVAC CLIMATE CONTROL (TEMPERATURE & DEHUMIDIFICATION)
// ==============================================================================
rErrorTemp := rZoneTempActual - rTargetTemp;
rErrorHum := rZoneHumActual - rTargetHumidity;

// Basic On/Off Cooling with 1.0C deadband
IF rErrorTemp > 1.0 THEN
    bHVAC_Cooling := TRUE;
ELSIF rErrorTemp < -0.5 THEN
    bHVAC_Cooling := FALSE;
END_IF;

// Dehumidification Override (VPD management via moisture removal)
IF rErrorHum > rDehumDeadband THEN
    bHVAC_Dehum := TRUE;
ELSIF rErrorHum < (rDehumDeadband * -1.0) THEN
    bHVAC_Dehum := FALSE;
END_IF;

// ==============================================================================
// FERTIGATION MASS BLENDING STATE MACHINE (NFT)
// ==============================================================================
// Calculates dosing needs based on EC and pH deviations
rErrorPH := rReservoirPH - rTargetPH;
rErrorEC := rTargetEC - rReservoirEC; // Positive means we need more nutrients

CASE eFertigationState OF
    0: // IDLE
        bPumpNutrientA := FALSE;
        bPumpNutrientB := FALSE;
        bPumpPH_Down := FALSE;
        bPumpPH_Up := FALSE;
        IF NOT bAlarmActive THEN
            eFertigationState := 1;
        END_IF;

    1: // EVALUATE SENSORS
        IF ABS(rErrorPH) > 0.2 THEN
            eFertigationState := 2; // Priority: correct pH first
        ELSIF rErrorEC > 0.1 THEN
            eFertigationState := 3; // Correct EC next
        ELSE
            eFertigationState := 0; // Everything is balanced
        END_IF;

    2: // DOSE PH
        // Determine Acid or Base
        IF rErrorPH > 0.0 THEN
            bPumpPH_Down := TRUE; // pH is high, add acid
        ELSE
            bPumpPH_Up := TRUE;   // pH is low, add base
        END_IF;

        fbTimerDosePH(IN:=TRUE, PT:=tDoseTimePH);
        IF fbTimerDosePH.Q THEN
            bPumpPH_Down := FALSE;
            bPumpPH_Up := FALSE;
            fbTimerDosePH(IN:=FALSE); // Reset timer
            eFertigationState := 4;   // Go to mixing
        END_IF;

    3: // DOSE NUTRIENTS
        bPumpNutrientA := TRUE;
        bPumpNutrientB := TRUE; // Assume A/B 1:1 ratio mass blending

        fbTimerDoseNutrient(IN:=TRUE, PT:=tDoseTimeNutrients);
        IF fbTimerDoseNutrient.Q THEN
            bPumpNutrientA := FALSE;
            bPumpNutrientB := FALSE;
            fbTimerDoseNutrient(IN:=FALSE);
            eFertigationState := 4; // Go to mixing
        END_IF;

    4: // MIXING DELAY
        // Wait for dosed liquids to circulate through the NFT system and sensors
        fbTimerMix(IN:=TRUE, PT:=tMixTime);
        IF fbTimerMix.Q THEN
            fbTimerMix(IN:=FALSE);
            eFertigationState := 1; // Re-evaluate
        END_IF;

    5: // ERROR STATE
        // Handled globally, wait for manual reset or safe levels
        IF rReservoirLevel >= 15.0 THEN
            eFertigationState := 0;
        END_IF;

END_CASE;

iSystemState := eFertigationState;
END_FUNCTION_BLOCK
