        rTroughAngleCmd := rStowAngle;
        rHTFPumpSpeedCmd := rMinPumpSpeed; 
        IF NOT bAlarmWindStow AND rDNI >= rMinDNI THEN
            nState := 2; 
        ELSIF NOT bAlarmWindStow THEN
            nState := 1;
        END_IF;

    4: // Fault / E-Stop
        rTroughAngleCmd := rStowAngle;
        rHTFPumpSpeedCmd := 0.0; 

