    // Failover
    Is_Primary_PLC : BOOL;
    Partner_PLC_Healthy : BOOL;
    Sync_Data_In : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
        Ride_Ready : BOOL;
    END_STRUCT;

    // SCADA & Security
    SCADA_ControlWord : WORD;
    SCADA_Auth_Token : DWORD;
    Expected_Auth_Token : DWORD; 

    // HIL Digital Twin
    HIL_Predicted_Speed : REAL; // Speed expected by Digital Twin physics engine
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;

    Sync_Data_Out : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
        Ride_Ready : BOOL;
    END_STRUCT;
    SCADA_StatusWord : WORD;

    Self_Test_Active : BOOL;
    Self_Test_Passed : BOOL;
END_VAR

VAR
    Validated_Speed : REAL;
    Speed_Drift : REAL;
    Twin_Deviation : REAL;

    Security_Lockout : BOOL;
    I_Am_Active : BOOL;

    // Self Test State Machine
    Test_Step : INT := 0;
    Test_Timer : INT := 0;
    Ride_Ready : BOOL := FALSE;

    TargetSpeed : REAL := 5.0;
END_VAR

BEGIN
    // --- Security & Adversarial Checks ---
    Security_Lockout := (SCADA_Auth_Token <> Expected_Auth_Token);

    // Sensor Drift Detection (Encoder 1 vs Encoder 2)
    Speed_Drift := ABS(Speed_Encoder_1 - Speed_Encoder_2);
    IF Speed_Drift > 0.5 THEN
        SystemFault := TRUE;
        FaultCode := 50; // Sensor Drift Detected
    END_IF;
    Validated_Speed := (Speed_Encoder_1 + Speed_Encoder_2) / 2.0;

    // HIL Digital Twin Anomaly Detection (Is physical reality matching physics model?)
    Twin_Deviation := ABS(Validated_Speed - HIL_Predicted_Speed);
    IF Twin_Deviation > 2.0 AND Validated_Speed > 1.0 THEN
        SystemFault := TRUE;
        FaultCode := 51; // Physics anomaly (e.g., unexpected friction/wheel bearing failure)
    END_IF;

    // --- Redundancy & Failover ---
    I_Am_Active := Is_Primary_PLC OR (NOT Is_Primary_PLC AND NOT Partner_PLC_Healthy);
    Sync_Data_Out.Active_State := I_Am_Active;
    Sync_Data_Out.Brake_Memory := FrictionBrakeLevel;
    Sync_Data_Out.Ride_Ready := Ride_Ready;

    IF NOT I_Am_Active THEN
        FrictionBrakeLevel := Sync_Data_In.Brake_Memory;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        Ride_Ready := Sync_Data_In.Ride_Ready;
        RETURN;
    END_IF;

    // --- Morning Self-Test Routine ---
    // Initiated via SCADA Bit 8 when train is empty in launch zone
    IF NOT Ride_Ready AND NOT Security_Lockout AND (SCADA_ControlWord AND 16#0100) <> 0 THEN
        Self_Test_Active := TRUE;
        SystemFault := FALSE;
    END_IF;

    IF Self_Test_Active THEN
        Test_Timer := Test_Timer + 1;
        CASE Test_Step OF
            0:  // Test Brakes 100%
                FrictionBrakeLevel := 100.0;
                AntiRollbackDeploy := FALSE;
                IF Test_Timer > 50 THEN Test_Step := 1; Test_Timer := 0; END_IF;
            1:  // Test Anti-Rollback Deployment
                FrictionBrakeLevel := 0.0;
                AntiRollbackDeploy := TRUE;
                IF Test_Timer > 50 THEN Test_Step := 2; Test_Timer := 0; END_IF;
            2:  // Test Brakes 0%
                AntiRollbackDeploy := FALSE;
                FrictionBrakeLevel := 0.0;
                IF Test_Timer > 50 THEN 
                    Self_Test_Active := FALSE;
                    Self_Test_Passed := TRUE;
                    Ride_Ready := TRUE; // Ride is now allowed to operate
                END_IF;
        END_CASE;
        RETURN; // Do not run normal logic during self test
    END_IF;

    // --- Normal Operation (Requires Ride_Ready) ---
    IF NOT E_Stop OR SystemFault OR NOT Ride_Ready THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        AllowProceedToZone2 := FALSE;
        IF NOT Ride_Ready THEN FaultCode := 99; END_IF; // 99 = Not Tested
        SCADA_StatusWord := 16#8000;
        RETURN;
    END_IF;

    // Block Zone & Launch Logic (Simplified for space, assuming mass check passed)
    AllowProceedToZone2 := Zone1_Occupied AND NOT Zone2_Occupied;

    IF Zone1_Occupied THEN
        IF NOT AllowProceedToZone2 THEN
            FrictionBrakeLevel := 100.0;
        ELSIF Validated_Speed > TargetSpeed THEN
            FrictionBrakeLevel := (Validated_Speed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    AntiRollbackDeploy := (TrainDirection = -1 AND Validated_Speed > 0.1);

    // Status update
    SCADA_StatusWord := 0;
    IF Ride_Ready THEN SCADA_StatusWord := SCADA_StatusWord OR 16#0010; END_IF;

END_FUNCTION_BLOCK
