FUNCTION_BLOCK FB_AeroIsothermalForgingPress
VAR_INPUT
    (* High-Tonnage Press Control & Thermal Management *)
    bSystemEnable       : BOOL;     (* Main safety interlock and system enable *)
    bEmergencyStop      : BOOL;     (* SIL-3 compliant emergency stop feedback *)
    rDieUpperTemp       : REAL;     (* Upper Mo-alloy die temperature (deg C), nominal 1150 *)
    rDieLowerTemp       : REAL;     (* Lower Mo-alloy die temperature (deg C), nominal 1150 *)
    rMainRamPosition    : REAL;     (* Cylinder position (mm), absolute encoding *)
    rMainRamVelocity    : REAL;     (* Current pressing velocity (mm/s) *)
    rBilletStrainRate   : REAL;     (* Target strain rate (s^-1) for Ti-Al superalloy *)
    rRamPressureA       : REAL;     (* Hydraulic pressure accumulator A (Bar) *)
    rRamPressureB       : REAL;     (* Hydraulic pressure accumulator B (Bar) *)
END_VAR
VAR_OUTPUT
    (* Actuator and System State Output *)
    bPressReady         : BOOL;     (* Press reached thermal equilibrium and hydraulic pressure *)
    bForgingActive      : BOOL;     (* Active deformation phase indicator *)
    rCmdRamVelocity     : REAL;     (* Commanded servo-valve flow/velocity (mm/s) *)
    rCmdInductionPowerUpper : REAL; (* Upper die induction heating setpoint (kW) *)
    rCmdInductionPowerLower : REAL; (* Lower die induction heating setpoint (kW) *)
    bThermalAlarm       : BOOL;     (* Temperature deviation or gradient alarm *)
    bHydraulicFault     : BOOL;     (* Pressure discrepancy alarm *)
END_VAR
VAR
    (* Internal State and Processing Variables *)
    iSequenceState      : INT := 0;
    tDwellTimer         : TON;
    tHeatSoakTimer      : TON;
    rAvgDieTemp         : REAL;
    rTempDeviation      : REAL;
    rFlowGain           : REAL := 1.25;
    rMaxPressure        : REAL := 350.0; (* Bar *)
    rStrainError        : REAL;
    rKiStrain           : REAL := 0.05;
    rIntegralStrain     : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Interlocks *)
IF NOT bEmergencyStop THEN
    bPressReady := FALSE;
    bForgingActive := FALSE;
    rCmdRamVelocity := 0.0;
    rCmdInductionPowerUpper := 0.0;
    rCmdInductionPowerLower := 0.0;
    bThermalAlarm := TRUE;
    iSequenceState := 999; (* Fault State *)
    RETURN;
END_IF;

(* Thermal Cascading & Gradient Monitoring *)
rAvgDieTemp := (rDieUpperTemp + rDieLowerTemp) / 2.0;
rTempDeviation := ABS(rDieUpperTemp - rDieLowerTemp);

IF rTempDeviation > 15.0 THEN
    bThermalAlarm := TRUE;
    rCmdInductionPowerUpper := 0.0;
    rCmdInductionPowerLower := 0.0;
ELSE
    bThermalAlarm := FALSE;
END_IF;

(* Main Sequence State Machine *)
CASE iSequenceState OF
    0: (* IDLE & PRE-HEAT *)
        bPressReady := FALSE;
        bForgingActive := FALSE;
        rCmdRamVelocity := 0.0;

        (* Proportional heating control to 1100 deg C *)
        IF rDieUpperTemp < 1100.0 THEN
            rCmdInductionPowerUpper := (1100.0 - rDieUpperTemp) * 2.5;
        ELSE
            rCmdInductionPowerUpper := 15.0; (* Maintain *)
        END_IF;

        IF rDieLowerTemp < 1100.0 THEN
            rCmdInductionPowerLower := (1100.0 - rDieLowerTemp) * 2.5;
        ELSE
            rCmdInductionPowerLower := 15.0; (* Maintain *)
        END_IF;

        IF (rAvgDieTemp >= 1090.0) AND (rTempDeviation <= 10.0) THEN
            tHeatSoakTimer(IN := TRUE, PT := T#5M);
            IF tHeatSoakTimer.Q THEN
                tHeatSoakTimer(IN := FALSE);
                iSequenceState := 10;
            END_IF;
        ELSE
            tHeatSoakTimer(IN := FALSE);
        END_IF;

    10: (* READY & WAIT FOR ENABLE *)
        bPressReady := TRUE;
        bForgingActive := FALSE;
        rCmdRamVelocity := 0.0;

        IF bSystemEnable AND (rRamPressureA > 300.0) AND (rRamPressureB > 300.0) THEN
            iSequenceState := 20;
        END_IF;

    20: (* ISOTHERMAL FORGING - STRAIN RATE CONTROL *)
        bPressReady := TRUE;
        bForgingActive := TRUE;

        (* Calculate dynamic velocity to maintain constant strain rate *)
        (* Strain rate e = v / h -> v = e * h *)
        (* Here rMainRamPosition is absolute height h *)
        rStrainError := rBilletStrainRate - (rMainRamVelocity / (rMainRamPosition + 1.0));
        rIntegralStrain := rIntegralStrain + rStrainError;

        rCmdRamVelocity := (rBilletStrainRate * rMainRamPosition) + (rKiStrain * rIntegralStrain);

        (* Limit velocity for safety *)
        IF rCmdRamVelocity > 25.0 THEN
            rCmdRamVelocity := 25.0;
        END_IF;

        IF rMainRamPosition <= 50.0 THEN (* Target final height 50mm *)
            iSequenceState := 30;
        END_IF;

    30: (* DWELL & RELAXATION *)
        rCmdRamVelocity := 0.0;
        tDwellTimer(IN := TRUE, PT := T#30S);
        IF tDwellTimer.Q THEN
            tDwellTimer(IN := FALSE);
            iSequenceState := 40;
        END_IF;

    40: (* RETRACT *)
        bForgingActive := FALSE;
        rCmdRamVelocity := -50.0; (* Fast retract *)
        IF rMainRamPosition >= 500.0 THEN
            rCmdRamVelocity := 0.0;
            iSequenceState := 0;
            bSystemEnable := FALSE; (* Require re-enable *)
        END_IF;

    999: (* FAULT HANDLING *)
        rCmdRamVelocity := 0.0;
        rCmdInductionPowerUpper := 0.0;
        rCmdInductionPowerLower := 0.0;
        bPressReady := FALSE;
        bForgingActive := FALSE;
        IF NOT bThermalAlarm AND bEmergencyStop THEN
            iSequenceState := 0; (* Reset if conditions clear *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

