FUNCTION_BLOCK FB_PEM_FuelCell_Dyno
TITLE = 'PEM Fuel Cell Testing Dynamometer Control'
VERSION : '1.0'

VAR_INPUT
    bEnableSystem       : BOOL;         (* Master enable for the test stand *)
    bEmergencyStop      : BOOL;         (* E-Stop input, active low *)
    bStartTest          : BOOL;         (* Initiate the test profile *)
    rTargetPower_kW     : REAL;         (* Target load power in kilowatts *)
    rStackVoltage       : REAL;         (* Measured stack voltage (V) *)
    rStackCurrent       : REAL;         (* Measured stack current (A) *)
    rCellTemp           : REAL;         (* Average stack temperature (C) *)
    rAnodePressure      : REAL;         (* H2 manifold pressure (bar) *)
    rCathodePressure    : REAL;         (* Air manifold pressure (bar) *)
    rHydrogenFlowIn     : REAL;         (* Measured H2 flow (SLPM) *)
    rAirFlowIn          : REAL;         (* Measured Air flow (SLPM) *)
    rHumidifierTemp     : REAL;         (* Dew point of inlet gases (C) *)
END_VAR

VAR_OUTPUT
    rRegenLoadCmd       : REAL;         (* Electronic load command (A) *)
    rAnodeValveCmd      : REAL;         (* H2 proportional flow valve (0-100%) *)
    rCathodeValveCmd    : REAL;         (* Air proportional flow valve (0-100%) *)
    rCoolantPumpCmd     : REAL;         (* Coolant pump speed command (0-100%) *)
    bHumidifierBypass   : BOOL;         (* Bypass humidifier to dry out membrane *)
    bAnodePurgeValve    : BOOL;         (* H2 dead-end purge valve *)
    iSystemState        : INT;          (* Current step in test sequence *)
    bSystemFault        : BOOL;         (* Critical fault indicator *)
    sFaultCode          : STRING[32];   (* Diagnostic fault description *)
END_VAR

VAR
    rFaradayConst       : REAL := 96485.33; (* Faraday constant (C/mol) *)
    rCellCount          : REAL := 200.0;    (* Number of cells in the PEM stack *)
    rMolarVol           : REAL := 22.414;   (* Molar volume at STP (L/mol) *)
    rMinStoichH2        : REAL := 1.2;      (* Minimum anode stoichiometry *)
    rMinStoichAir       : REAL := 2.0;      (* Minimum cathode stoichiometry *)

    rReqH2Flow_SLPM     : REAL;         (* Theoretical required H2 flow *)
    rReqAirFlow_SLPM    : REAL;         (* Theoretical required Air flow *)
    rActualStoichH2     : REAL;         (* Calculated actual H2 stoichiometry *)

    tPurgeInterval      : TON;          (* Timer for dead-end purge cycle *)
    tPurgeDuration      : TON;          (* Duration of active purge *)
    tHydrationCheck     : TON;          (* Hydration monitoring interval *)

    rMembraneWaterCont  : REAL;         (* Estimated membrane lambda (H2O/SO3H) *)

    iStateIdle          : INT := 0;
    iStatePrePurge      : INT := 10;
    iStateHeating       : INT := 20;
    iStateRunning       : INT := 30;
    iStateShutDown      : INT := 40;
    iStateFault         : INT := 99;
END_VAR

(* --- Safety and E-Stop Handling --- *)
IF NOT bEmergencyStop THEN
    iSystemState := iStateFault;
    bSystemFault := TRUE;
    sFaultCode := 'E-STOP ACTIVATED';
ELSIF rStackVoltage < 10.0 AND iSystemState = iStateRunning THEN
    iSystemState := iStateFault;
    bSystemFault := TRUE;
    sFaultCode := 'UNDERVOLTAGE - CELL REVERSAL RISK';
END_IF;

(* --- Theoretical Consumption Calculations --- *)
(* Rate of H2 consumption (mol/s) = I * N / (2 * F) *)
(* SLPM conversion = (mol/s) * 60 (s/min) * 22.414 (L/mol) *)
rReqH2Flow_SLPM := (rStackCurrent * rCellCount * 60.0 * rMolarVol) / (2.0 * rFaradayConst);
(* Air consumption assumes 21% O2 *)
rReqAirFlow_SLPM := (rStackCurrent * rCellCount * 60.0 * rMolarVol) / (4.0 * rFaradayConst * 0.21);

IF rReqH2Flow_SLPM > 0.0 THEN
    rActualStoichH2 := rHydrogenFlowIn / rReqH2Flow_SLPM;
ELSE
    rActualStoichH2 := 0.0;
END_IF;

(* --- State Machine --- *)
CASE iSystemState OF
    0: (* IDLE *)
        rRegenLoadCmd := 0.0;
        rAnodeValveCmd := 0.0;
        rCathodeValveCmd := 0.0;
        bAnodePurgeValve := FALSE;
        rCoolantPumpCmd := 0.0;
        bHumidifierBypass := FALSE;

        IF bEnableSystem AND bStartTest THEN
            iSystemState := iStatePrePurge;
        END_IF;

    10: (* PRE-PURGE *)
        (* Flush anode with H2 for 5 seconds before drawing current *)
        rAnodeValveCmd := 20.0; 
        rCathodeValveCmd := 30.0;
        bAnodePurgeValve := TRUE;

        tPurgeDuration(IN := TRUE, PT := T#5S);
        IF tPurgeDuration.Q THEN
            tPurgeDuration(IN := FALSE);
            bAnodePurgeValve := FALSE;
            iSystemState := iStateHeating;
        END_IF;

    20: (* HEATING & HYDRATION CALIBRATION *)
        (* Bring stack to 65C operating temp *)
        rAnodeValveCmd := 10.0;
        rCathodeValveCmd := 10.0;
        rCoolantPumpCmd := 10.0; (* Minimum flow *)

        IF rCellTemp >= 65.0 THEN
            iSystemState := iStateRunning;
        END_IF;

    30: (* RUNNING - ACTIVE DYNAMOMETER LOAD *)
        (* 1. Dynamometer Load Control *)
        IF rStackVoltage > 0.0 THEN
            (* I = P / V. Target Power is in kW, voltage in V -> Target Current (A) *)
            rRegenLoadCmd := (rTargetPower_kW * 1000.0) / rStackVoltage;
        ELSE
            rRegenLoadCmd := 0.0;
        END_IF;

        (* 2. Reactant Stoichiometry Control *)
        (* PI loop approximation for valve control based on stoichiometric targets *)
        rAnodeValveCmd := LIMIT(0.0, (rReqH2Flow_SLPM * rMinStoichH2) * 2.5, 100.0);
        rCathodeValveCmd := LIMIT(0.0, (rReqAirFlow_SLPM * rMinStoichAir) * 1.8, 100.0);

        (* 3. Dead-End Purge Management *)
        (* Periodic purging of anode to clear nitrogen crossover and liquid water *)
        tPurgeInterval(IN := NOT bAnodePurgeValve, PT := T#30S);
        IF tPurgeInterval.Q THEN
            bAnodePurgeValve := TRUE;
        END_IF;

        tPurgeDuration(IN := bAnodePurgeValve, PT := T#1S);
        IF tPurgeDuration.Q THEN
            bAnodePurgeValve := FALSE;
        END_IF;

        (* 4. PEM Hydration Curve Optimization *)
        (* Estimate membrane water content (lambda) based on resistance/temp/RH *)
        (* Simplified for PLC logic: High temp + high load = drying risk *)
        rMembraneWaterCont := 14.0 - (0.1 * (rCellTemp - 65.0)) + (0.05 * rStackCurrent);

        tHydrationCheck(IN := TRUE, PT := T#5S);
        IF tHydrationCheck.Q THEN
            tHydrationCheck(IN := FALSE);
            IF rMembraneWaterCont > 16.0 THEN
                (* Flooding risk: Bypass humidifier to supply dry air *)
                bHumidifierBypass := TRUE;
            ELSIF rMembraneWaterCont < 8.0 THEN
                (* Drying out risk: Ensure full humidification *)
                bHumidifierBypass := FALSE;
            END_IF;
        END_IF;

        (* Stop condition *)
        IF NOT bStartTest THEN
            iSystemState := iStateShutDown;
        END_IF;

    40: (* SHUTDOWN *)
        rRegenLoadCmd := 0.0;
        rAnodeValveCmd := 0.0;
        rCathodeValveCmd := 10.0; (* Cool down with air *)
        IF rCellTemp < 40.0 THEN
            iSystemState := iStateIdle;
        END_IF;

    99: (* FAULT STATE *)
        rRegenLoadCmd := 0.0;
        rAnodeValveCmd := 0.0;
        rCathodeValveCmd := 0.0;
        bAnodePurgeValve := FALSE;
        rCoolantPumpCmd := 100.0; (* Max cooling during fault *)

        IF bEnableSystem = FALSE AND bEmergencyStop = TRUE THEN
            bSystemFault := FALSE;
            sFaultCode := 'NONE';
            iSystemState := iStateIdle;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
