FUNCTION_BLOCK "AGV_Traffic_Controller"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      agv_Position : Int;
      agv_BatteryLvl : Real;
      agv_DestNode : Int;
      agv_PayloadWeight : Real;
      node_Occupied : Array[1..20] of Bool;
      pn_CommStatus : Bool;
      scada_AuthToken : DWord;
      plc_IsPrimary : Bool;
      plc_SyncData : Word;
   END_VAR

   VAR_OUTPUT 
      agv_GoToNode : Int;
      agv_SpeedCmd : Real;
      charge_Req : Bool;
      error_Sts : Bool;
      diag_Code : Word;
      pn_StatusWord : Word;
      scada_Metrics : Struct
         throughput : Real;
         uptime : Time;
      END_STRUCT;
   END_VAR

   VAR 
      auth_Valid : Bool;
      failover_Active : Bool;
   END_VAR

   VAR_TEMP 
      max_Speed : Real;
      path_Found : Bool;
      next_Node : Int;
   END_VAR

BEGIN
    // IEC 62443 Cybersecurity Access Control
    #auth_Valid := (#scada_AuthToken = 16#DEADBEEF);
    IF NOT #auth_Valid THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#F001; // Security violation
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // PLC Redundancy Failover
    IF NOT #plc_IsPrimary THEN
        // Standby mode, read sync data, no outputs driven
        #failover_Active := TRUE;
        RETURN;
    END_IF;

    #diag_Code := 16#0000;

    // Profinet Communication
    IF NOT #pn_CommStatus THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#E001; 
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // Speed Limiting
    IF #agv_PayloadWeight > 1000.0 THEN #max_Speed := 0.5;
    ELSIF #agv_PayloadWeight > 500.0 THEN #max_Speed := 1.0;
    ELSE #max_Speed := 2.0; END_IF;

    // Battery
    IF #agv_BatteryLvl < 20.0 THEN
        #charge_Req := TRUE;
        #agv_DestNode := 1; 
    ELSIF #agv_BatteryLvl > 95.0 THEN
        #charge_Req := FALSE;
    END_IF;

    // Routing & Collision Avoidance
    #path_Found := FALSE;
    #next_Node := #agv_Position + 1; 

    IF #next_Node <= 20 THEN
        IF NOT #node_Occupied[#next_Node] THEN
            #agv_GoToNode := #next_Node;
            #agv_SpeedCmd := #max_Speed; 
            #path_Found := TRUE;
        ELSE
            #agv_SpeedCmd := 0.0; 
            #path_Found := FALSE;
            #diag_Code := 16#W001; 
        END_IF;
    END_IF;

    // SCADA Metrics integration
    #scada_Metrics.throughput := 10.0; // Mock data

    #error_Sts := (NOT #path_Found AND #agv_Position <> #agv_DestNode);
    #pn_StatusWord.%X0 := #error_Sts;
    #pn_StatusWord.%X1 := #charge_Req;
END_FUNCTION_BLOCK
