FUNCTION_BLOCK FB_LiIon_ElectrodeCalendering
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable for calendering section *)
    bEmergencyStop          : BOOL;     (* Master Safety relay OK signal (active high) *)
    rWebTensionActual       : REAL;     (* Current web tension from load cell [N] *)
    rWebTensionSetpoint     : REAL;     (* Target web tension [N] *)
    rGapActual_Left         : REAL;     (* Current wedge gap measurement left side [um] *)
    rGapActual_Right        : REAL;     (* Current wedge gap measurement right side [um] *)
    rRollerTemp_Top         : REAL;     (* Surface temperature of top roller [deg C] *)
    rRollerTemp_Bot         : REAL;     (* Surface temperature of bottom roller [deg C] *)
    rLineSpeedActual        : REAL;     (* Actual web speed [m/min] *)
    bInductionHeaterOk      : BOOL;     (* Status of induction heater systems *)
    bHydraulicsOk           : BOOL;     (* Status of high-pressure hydraulics *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Calendering section is ready for run *)
    rGapServoCmd_Left       : REAL;     (* Position command to left gap wedge servo [um] *)
    rGapServoCmd_Right      : REAL;     (* Position command to right gap wedge servo [um] *)
    rTensionMotorTorqueCmd  : REAL;     (* Torque command to dancer/unwind motor [%] *)
    rInductionHeaterCmd     : REAL;     (* Power command to thermal crowning heater [%] *)
    bAlarmActive            : BOOL;     (* General fault alarm output *)
    iErrorCode              : INT;      (* Specific error code for diagnostics *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine state *)
    tStartupDelay           : TON;      (* Timer for hydraulic and thermal stabilization *)
    tTensionFilter          : TON;

    (* PI Controller variables for Web Tension *)
    rTensionKp              : REAL := 2.5;
    rTensionKi              : REAL := 0.8;
    rTensionError           : REAL;
    rTensionErrorSum        : REAL;

    (* Gap Control Variables *)
    rGapTarget              : REAL := 50.0; (* 50 micron nominal target gap *)
    rThermalCrownComp       : REAL;
    rMaxTemp                : REAL := 120.0;

    (* Constants *)
    TENSION_MAX_ERR         : REAL := 15.0; (* N *)
    GAP_MAX_ERR             : REAL := 5.0;  (* um *)

END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarmActive := TRUE;
    iErrorCode := 1; (* ESTOP Pressed *)
    rGapServoCmd_Left := rGapActual_Left; (* Hold position *)
    rGapServoCmd_Right := rGapActual_Right; (* Hold position *)
    rTensionMotorTorqueCmd := 0.0;
    rInductionHeaterCmd := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* Fault Monitoring *)
IF NOT bHydraulicsOk OR NOT bInductionHeaterOk THEN
    bSystemReady := FALSE;
    bAlarmActive := TRUE;
    iErrorCode := 2; (* Subsystem Fault *)
    iState := 99; (* Error State *)
END_IF;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bAlarmActive := FALSE;
        iErrorCode := 0;
        IF bEnable AND bHydraulicsOk AND bInductionHeaterOk THEN
            iState := 10;
        END_IF;

    10: (* THERMAL PRE-CONDITIONING *)
        (* Calculate thermal crowning compensation based on temperature *)
        (* Assuming thermal expansion requires gap adjustment *)
        rThermalCrownComp := (rRollerTemp_Top + rRollerTemp_Bot) * 0.015;
        rInductionHeaterCmd := 50.0; (* Pre-heating power *)

        tStartupDelay(IN := TRUE, PT := T#10S);
        IF tStartupDelay.Q AND (rRollerTemp_Top >= 80.0) AND (rRollerTemp_Bot >= 80.0) THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* GAP SERVO ENGAGEMENT *)
        rInductionHeaterCmd := 65.0; (* Running power *)
        rGapServoCmd_Left := rGapTarget + rThermalCrownComp;
        rGapServoCmd_Right := rGapTarget + rThermalCrownComp;

        IF (ABS(rGapActual_Left - rGapServoCmd_Left) < GAP_MAX_ERR) AND 
           (ABS(rGapActual_Right - rGapServoCmd_Right) < GAP_MAX_ERR) THEN
            iState := 30;
        END_IF;

    30: (* TENSION CONTROL ACTIVE *)
        bSystemReady := TRUE;

        (* PI Control for Web Tension *)
        rTensionError := rWebTensionSetpoint - rWebTensionActual;

        IF ABS(rTensionError) > TENSION_MAX_ERR AND rLineSpeedActual > 5.0 THEN
            bAlarmActive := TRUE;
            iErrorCode := 3; (* Tension Out of Bounds *)
        ELSE
            bAlarmActive := FALSE;
            iErrorCode := 0;
        END_IF;

        (* Anti-windup integration *)
        IF (rTensionMotorTorqueCmd < 100.0) AND (rTensionMotorTorqueCmd > 0.0) THEN
            rTensionErrorSum := rTensionErrorSum + (rTensionError * 0.1); (* Assuming 100ms cycle *)
        END_IF;

        rTensionMotorTorqueCmd := (rTensionKp * rTensionError) + (rTensionKi * rTensionErrorSum);

        (* Clamp torque command *)
        IF rTensionMotorTorqueCmd > 100.0 THEN
            rTensionMotorTorqueCmd := 100.0;
        ELSIF rTensionMotorTorqueCmd < 0.0 THEN
            rTensionMotorTorqueCmd := 0.0;
        END_IF;

        (* Dynamic Thermal Crowning Compensation Update *)
        rThermalCrownComp := ((rRollerTemp_Top + rRollerTemp_Bot) / 2.0) * 0.012;
        rGapServoCmd_Left := rGapTarget + rThermalCrownComp;
        rGapServoCmd_Right := rGapTarget + rThermalCrownComp;

        IF NOT bEnable THEN
            bSystemReady := FALSE;
            rTensionErrorSum := 0.0;
            iState := 0;
        END_IF;

    99: (* ERROR HANDLING *)
        rTensionMotorTorqueCmd := 0.0;
        rInductionHeaterCmd := 0.0;
        bSystemReady := FALSE;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
