FUNCTION_BLOCK FB_SQUID_MCG_ArrayControl
VAR_INPUT
    (* Sub-Kelvin Cryogenics & Thermal Management *)
    bSystemEnable           : BOOL;     (* Main operation enable signal *)
    bEmergencyStop          : BOOL;     (* Safety interlock / Quench detection OK *)
    rHeLevel                : REAL;     (* Liquid Helium reservoir level [%] *)
    rVaporPressure          : REAL;     (* He vapor pressure [mbar] *)
    rThermalStageTemp       : REAL;     (* 4K stage temperature [K] *)

    (* Magnetic Environment & Bias *)
    rAmbientMagNoise        : REAL;     (* External flux detected via reference SQUID [fT] *)
    rJosephsonBiasReq       : REAL;     (* Requested DC bias current [uA] *)
    rSquidVoltageReadout    : REAL;     (* V-Phi curve modulation readout [uV] *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Array ready for magnetocardiogram acquisition *)
    rHelmholtzCoilCurrent   : REAL;     (* Active noise cancellation current [mA] *)
    rHeFlowControlValve     : REAL;     (* Cryostat continuous flow valve position [%] *)
    rActualBiasCurrent      : REAL;     (* Applied Josephson junction bias [uA] *)
    bThermalAlarm           : BOOL;     (* Cryo stability fault *)
    bFluxLockLost           : BOOL;     (* SQUID FLL (Flux-Locked Loop) error *)
END_VAR
VAR
    (* Internal State and Filtering *)
    iState                  : INT := 0; 
    tStabilizationTimer     : TON;
    tHeaterPulse            : TP;

    (* Control Loop Variables *)
    rTempError              : REAL;
    rTempKp                 : REAL := 2.5;
    rTempKi                 : REAL := 0.05;
    rTempIntegral           : REAL := 0.0;

    (* Noise Cancellation Loop *)
    rNoiseIntegral          : REAL := 0.0;
    rFLL_Gain               : REAL := 1.2e-3;
    rPrevNoise              : REAL := 0.0;
    rDerivative             : REAL;

    (* Limits & Thresholds *)
    c_rMaxTemp              : REAL := 4.25; (* Max allowed temp in K *)
    c_rMinHeLevel           : REAL := 15.0; (* Min LHe level % *)

    (* Diagnostics *)
    iFluxUnlockCount        : INT := 0;
END_VAR

(* === MAIN LOGIC: MULTI-LAYERED SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    (* Immediate safe state on quench or estop *)
    bSystemReady := FALSE;
    bThermalAlarm := TRUE;
    rHelmholtzCoilCurrent := 0.0;
    rHeFlowControlValve := 100.0; (* Open valve fully to vent / cool if required, or shut down depending on safety matrix *)
    rActualBiasCurrent := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* === THERMAL MANAGEMENT PID LOOP === *)
(* Regulate liquid helium flow to maintain 4K stage stability *)
rTempError := 4.0 - rThermalStageTemp; (* Setpoint 4.0K *)

IF rThermalStageTemp > c_rMaxTemp OR rHeLevel < c_rMinHeLevel THEN
    bThermalAlarm := TRUE;
    bSystemReady := FALSE;
    iState := 99; (* Fault state *)
ELSE
    bThermalAlarm := FALSE;
    (* PI Control for Continuous Flow Cryostat *)
    rTempIntegral := rTempIntegral + (rTempError * 0.01);
    IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
    IF rTempIntegral < -100.0 THEN rTempIntegral := -100.0; END_IF;

    rHeFlowControlValve := (rTempKp * rTempError) + (rTempKi * rTempIntegral);

    (* Clamp valve output 0-100% *)
    IF rHeFlowControlValve > 100.0 THEN rHeFlowControlValve := 100.0; END_IF;
    IF rHeFlowControlValve < 0.0 THEN rHeFlowControlValve := 0.0; END_IF;
END_IF;

(* === AMBIENT MAGNETIC NOISE ACTIVE CANCELLATION === *)
(* Helmholtz coil drive based on reference SQUID derivative to minimize ambient gradient *)
rDerivative := (rAmbientMagNoise - rPrevNoise) / 0.01; (* Assume 10ms cycle *)
rPrevNoise := rAmbientMagNoise;

rHelmholtzCoilCurrent := rHelmholtzCoilCurrent - (rAmbientMagNoise * rFLL_Gain) - (rDerivative * 0.0001);
(* Limit active shielding coil current to prevent flux trapping *)
IF rHelmholtzCoilCurrent > 500.0 THEN rHelmholtzCoilCurrent := 500.0; END_IF;
IF rHelmholtzCoilCurrent < -500.0 THEN rHelmholtzCoilCurrent := -500.0; END_IF;

(* === SYSTEM STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rActualBiasCurrent := 0.0;
        bFluxLockLost := FALSE;
        IF bSystemEnable AND NOT bThermalAlarm THEN
            iState := 10;
        END_IF;

    10: (* COOLDOWN & STABILIZATION PHASE *)
        (* Wait for temperature to reach stable regime <= 4.1K *)
        IF rThermalStageTemp <= 4.1 THEN
            tStabilizationTimer(IN := TRUE, PT := T#60S);
            IF tStabilizationTimer.Q THEN
                tStabilizationTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tStabilizationTimer(IN := FALSE);
        END_IF;

    20: (* SQUID TUNING & FLUX-LOCKED LOOP ACQUISITION *)
        (* Ramp bias current slowly to prevent junction hysteresis *)
        IF rActualBiasCurrent < rJosephsonBiasReq THEN
            rActualBiasCurrent := rActualBiasCurrent + 0.1;
        ELSIF rActualBiasCurrent > rJosephsonBiasReq THEN
            rActualBiasCurrent := rActualBiasCurrent - 0.1;
        END_IF;

        (* Verify V-Phi modulation depth is sufficient for lock *)
        IF ABS(rSquidVoltageReadout) > 5.0 THEN
            iState := 30; (* FLL Locked *)
            iFluxUnlockCount := 0;
            bFluxLockLost := FALSE;
        ELSE
            iFluxUnlockCount := iFluxUnlockCount + 1;
            IF iFluxUnlockCount > 1000 THEN
                bFluxLockLost := TRUE;
                iState := 0; (* Re-tune required *)
            END_IF;
        END_IF;

    30: (* ACQUISITION READY *)
        bSystemReady := TRUE;

        (* Continuous monitoring of FLL stability *)
        IF ABS(rSquidVoltageReadout) < 1.0 THEN
            bFluxLockLost := TRUE;
            bSystemReady := FALSE;
            iState := 20; (* Attempt relock *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rActualBiasCurrent := 0.0;
        IF NOT bThermalAlarm AND bSystemEnable THEN
            iState := 0; (* Recover from fault once alarm clears *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
