FUNCTION_BLOCK FB_EBMMachineControl
TITLE = 'Extrusion Blow Molding Advanced Control'
VERSION : '2.1'

(* 
  Extrusion Blow Molding Machine Control block
  Features: 
  - 100-point Parison Wall Thickness Programming (WTP)
  - Mold clamp toggle kinematics and positioning 
  - Hot knife cutting synchronization
*)

VAR_INPUT
    bEnable : BOOL; // Enable EBM Machine Control
    bStartCycle : BOOL; // Start automatic cycle
    bEmergencyStop : BOOL; // Emergency stop signal
    rExtruderSpeedCmd : REAL; // Requested extruder speed (rpm)
    rMoldClampPosCmd : REAL; // Target mold clamp position (mm)
    rParisonLength : REAL; // Current parison length measured by laser (mm)
    rMeltPressure : REAL; // Extruder melt pressure (bar)
    rMeltTemperature : REAL; // Extruder melt temp (C)
    bHotKnifeReady : BOOL; // Hot knife is at temperature
    rWtpProfile : ARRAY[0..99] OF REAL; // 100-point thickness profile (0-100%)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bCycleActive : BOOL;
    rServoValveCmd : REAL; // Command to parison WTP servo valve (0-100%)
    rClampVelocityCmd : REAL; // Command to clamp closing velocity (mm/s)
    bClampClosed : BOOL; // Clamp fully closed and locked
    bHotKnifeCutCmd : BOOL; // Command to actuate hot knife
    bBlowPinEngageCmd : BOOL; // Command to engage blow pin
    bAlarm : BOOL; // General alarm
    iAlarmCode : INT; // Alarm code
END_VAR

VAR
    iState : INT := 0; // State machine step
    iWtpIndex : INT := 0; // Current WTP profile index
    rWtpSegmentLength : REAL := 5.0; // mm per WTP point (assuming 500mm max length)
    tDelayTimer : TON; // General delay timer
    tClampSettleTimer : TON; // Clamp lock settling timer
    bKnifeActuated : BOOL := FALSE;
    rCurrentTargetThickness : REAL := 0.0;

    // Kinematics parameters
    rToggleFactor : REAL := 1.0; 
    rClampClosingMaxSpeed : REAL := 150.0; // mm/s
END_VAR

(* --- Main Control Logic --- *)
IF bEmergencyStop THEN
    bSystemReady := FALSE;
    bCycleActive := FALSE;
    rServoValveCmd := 0.0;
    rClampVelocityCmd := 0.0;
    bHotKnifeCutCmd := FALSE;
    bBlowPinEngageCmd := FALSE;
    iState := 999;
    bAlarm := TRUE;
    iAlarmCode := 1000; (* E-STOP Active *)
    RETURN;
END_IF;

bAlarm := FALSE;
iAlarmCode := 0;
bSystemReady := bEnable AND bHotKnifeReady AND (rMeltTemperature > 180.0) AND (rMeltPressure < 300.0);

CASE iState OF
    0: (* Idle / Initialization *)
        bCycleActive := FALSE;
        bHotKnifeCutCmd := FALSE;
        bBlowPinEngageCmd := FALSE;
        bKnifeActuated := FALSE;
        rServoValveCmd := rWtpProfile[0];
        IF bSystemReady AND bStartCycle THEN
            iState := 10;
            bCycleActive := TRUE;
            iWtpIndex := 0;
        END_IF;

    10: (* Parison Extrusion & WTP Control *)
        // Calculate current WTP index based on parison length
        iWtpIndex := REAL_TO_INT(rParisonLength / rWtpSegmentLength);
        IF iWtpIndex < 0 THEN iWtpIndex := 0; END_IF;
        IF iWtpIndex > 99 THEN iWtpIndex := 99; END_IF;

        // Output servo valve command for thickness profile
        rCurrentTargetThickness := rWtpProfile[iWtpIndex];
        // Apply basic P-control for smoothing
        rServoValveCmd := rServoValveCmd + 0.1 * (rCurrentTargetThickness - rServoValveCmd);

        IF rParisonLength >= 500.0 THEN // Max length reached
            iState := 20;
        END_IF;

    20: (* Mold Closing - Toggle Kinematics Profile *)
        // Implement non-linear closing speed due to toggle mechanism
        // Toggle factor slows down the mold as it nears closing (0 position)
        rToggleFactor := (rMoldClampPosCmd / 100.0) * 0.8 + 0.2; 
        IF rToggleFactor > 1.0 THEN rToggleFactor := 1.0; END_IF;
        IF rToggleFactor < 0.1 THEN rToggleFactor := 0.1; END_IF;

        rClampVelocityCmd := rClampClosingMaxSpeed * rToggleFactor;

        IF rMoldClampPosCmd <= 1.0 THEN // Close to zero means locked
            rClampVelocityCmd := 0.0;
            tClampSettleTimer(IN:=TRUE, PT:=T#500MS);
            IF tClampSettleTimer.Q THEN
                tClampSettleTimer(IN:=FALSE);
                bClampClosed := TRUE;
                iState := 30;
            END_IF;
        ELSE
            tClampSettleTimer(IN:=FALSE);
            bClampClosed := FALSE;
        END_IF;

    30: (* Hot Knife Cut *)
        IF NOT bKnifeActuated THEN
            bHotKnifeCutCmd := TRUE;
            tDelayTimer(IN:=TRUE, PT:=T#300MS);
            IF tDelayTimer.Q THEN
                bHotKnifeCutCmd := FALSE;
                bKnifeActuated := TRUE;
                tDelayTimer(IN:=FALSE);
                iState := 40;
            END_IF;
        END_IF;

    40: (* Blow Pin Engage & Blowing (Simplified) *)
        bBlowPinEngageCmd := TRUE;
        tDelayTimer(IN:=TRUE, PT:=T#5S); (* 5 seconds blowing cooling time *)
        IF tDelayTimer.Q THEN
            bBlowPinEngageCmd := FALSE;
            tDelayTimer(IN:=FALSE);
            iState := 50;
        END_IF;

    50: (* Mold Open & Eject *)
        rClampVelocityCmd := -rClampClosingMaxSpeed; (* Negative for opening *)
        IF rMoldClampPosCmd >= 200.0 THEN (* Fully open *)
            rClampVelocityCmd := 0.0;
            bClampClosed := FALSE;
            iState := 0; (* Cycle complete *)
        END_IF;

    999: (* Fault State *)
        // Wait for reset
        IF NOT bEmergencyStop THEN
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
