FUNCTION_BLOCK FB_MOCVD_EpiControl
(* 
    =============================================================================
    BLOCK: FB_MOCVD_EpiControl
    DESC:  Advanced Epitaxial Metal-Organic Chemical Vapor Deposition Control.
           Handles TMGa bubbler thermal mass balancing, UHV susceptor RF 
           induction heating, and laser reflectance in-situ growth rate interferometry.
    AUTHOR: Lumina Elite Automation Architect
    VERSION: 4.2.0 (High-Precision Production Release)
    ============================================================================= 
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System overall enable/run permissive *)
    bEmergencyStop          : BOOL;     (* Hardwired emergency safety stop (Active High = OK) *)
    rSusceptorTempPV        : REAL;     (* RF Induction Susceptor actual temperature [degC] *)
    rTMGaMassFlowPV         : REAL;     (* Actual TMGa Mass Flow via carrier gas [sccm] *)
    rChamberPressurePV      : REAL;     (* UHV Chamber absolute pressure [Torr] *)
    rLaserReflectancePV     : REAL;     (* In-situ laser interferometer raw signal [mV] *)
    rGrowthRateTarget       : REAL;     (* Desired epitaxial layer growth rate [nm/min] *)
    rTargetTemperature      : REAL;     (* Susceptor temperature setpoint [degC] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Indicates system is ready for recipe execution *)
    rRFPIDControlOut        : REAL;     (* Output to RF Induction heater power supply [0-100%] *)
    rTMGaValvePosition      : REAL;     (* Control signal to TMGa electronic mass flow controller [0-100%] *)
    rChamberVacuumValveOut  : REAL;     (* Throttle valve position for closed-loop pressure control [0-100%] *)
    rCalculatedGrowthRate   : REAL;     (* Real-time epitaxial growth rate calculated from reflectance [nm/min] *)
    bProcessInterlockActive : BOOL;     (* Indicates an active interlock preventing growth *)
    bAlarm                  : BOOL;     (* General system fault / alarm active *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine step *)

    (* RF Heater PID Control Variables *)
    rHeaterKp               : REAL := 2.50;
    rHeaterKi               : REAL := 0.15;
    rHeaterKd               : REAL := 0.05;
    rTempError              : REAL;
    rTempErrorPrev          : REAL;
    rTempIntegral           : REAL;
    rTempDerivative         : REAL;

    (* Growth Rate Calculation Variables *)
    rReflectanceMin         : REAL := 9999.0;
    rReflectanceMax         : REAL := 0.0;
    rLaserWavelength        : REAL := 632.8; (* He-Ne Laser wavelength in nm *)
    rRefractiveIndex        : REAL := 3.42;  (* GaAs refractive index at process temp *)
    tGrowthTimer            : TON;
    tSampleTimer            : TON;
    bFringeDetected         : BOOL;
    iFringeCount            : DINT;

    (* General Timers and Filters *)
    tPurgeTimer             : TON;
    rFilteredPressure       : REAL;
    bInterlockLatched       : BOOL;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Processing *)
IF NOT bEmergencyStop THEN
    bSystemReady            := FALSE;
    bProcessInterlockActive := TRUE;
    bAlarm                  := TRUE;
    iState                  := 999; (* Transition to FAULT state *)
    rRFPIDControlOut        := 0.0;
    rTMGaValvePosition      := 0.0;
    rChamberVacuumValveOut  := 0.0;
    RETURN;
END_IF;

(* Continuous low-pass filter for chamber pressure UHV measurement *)
rFilteredPressure := (rFilteredPressure * 0.9) + (rChamberPressurePV * 0.1);

(* 2. Main State Machine for MOCVD Sequencing *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := TRUE;
        bProcessInterlockActive := FALSE;
        rRFPIDControlOut := 0.0;
        rTMGaValvePosition := 0.0;
        rChamberVacuumValveOut := 100.0; (* Full open for max conductance *)

        IF bEnable THEN
            iState := 10; (* Move to pump down / purge *)
            bSystemReady := FALSE;
        END_IF;

    10: (* PUMP DOWN & PURGE *)
        rChamberVacuumValveOut := 80.0; (* Throttle slightly for stability *)
        tPurgeTimer(IN := TRUE, PT := T#30S);

        IF tPurgeTimer.Q AND (rFilteredPressure < 1.0E-3) THEN
            tPurgeTimer(IN := FALSE);
            iState := 20; (* Move to thermal ramp *)
        ELSIF tPurgeTimer.Q THEN
            (* Failed to reach base pressure *)
            bAlarm := TRUE;
            bProcessInterlockActive := TRUE;
            iState := 999;
        END_IF;

    20: (* SUSCEPTOR THERMAL RAMP & PID STABILIZATION *)
        rTempError := rTargetTemperature - rSusceptorTempPV;
        rTempIntegral := rTempIntegral + rTempError;
        rTempDerivative := rTempError - rTempErrorPrev;
        rTempErrorPrev := rTempError;

        (* Calculate PID output with clamp *)
        rRFPIDControlOut := (rHeaterKp * rTempError) + (rHeaterKi * rTempIntegral) + (rHeaterKd * rTempDerivative);
        IF rRFPIDControlOut > 100.0 THEN
            rRFPIDControlOut := 100.0;
        ELSIF rRFPIDControlOut < 0.0 THEN
            rRFPIDControlOut := 0.0;
        END_IF;

        (* Check if temperature is stabilized within deadband *)
        IF ABS(rTempError) < 1.5 THEN
            iState := 30; (* Move to deposition / epi-growth *)
        END_IF;

    30: (* EPITAXIAL GROWTH & IN-SITU INTERFEROMETRY *)
        (* Maintain temperature *)
        rTempError := rTargetTemperature - rSusceptorTempPV;
        rTempIntegral := rTempIntegral + rTempError;
        rRFPIDControlOut := (rHeaterKp * rTempError) + (rHeaterKi * rTempIntegral);
        IF rRFPIDControlOut > 100.0 THEN rRFPIDControlOut := 100.0; END_IF;
        IF rRFPIDControlOut < 0.0 THEN rRFPIDControlOut := 0.0; END_IF;

        (* Regulate TMGa mass flow for growth rate *)
        rTMGaValvePosition := rGrowthRateTarget * 2.15; (* Simplified precursor mapping *)

        (* Laser Reflectance Fringe Counting for Growth Rate calculation *)
        tSampleTimer(IN := TRUE, PT := T#100MS);
        IF tSampleTimer.Q THEN
            tSampleTimer(IN := FALSE);
            IF rLaserReflectancePV > rReflectanceMax THEN
                rReflectanceMax := rLaserReflectancePV;
            END_IF;
            IF rLaserReflectancePV < rReflectanceMin THEN
                rReflectanceMin := rLaserReflectancePV;
            END_IF;

            (* Detect peak/valley transition (fringe) *)
            IF (rLaserReflectancePV > (rReflectanceMax * 0.95)) AND NOT bFringeDetected THEN
                bFringeDetected := TRUE;
                iFringeCount := iFringeCount + 1;
                (* Real-time thickness addition based on half-wavelength in material *)
                rCalculatedGrowthRate := ((iFringeCount * rLaserWavelength) / (2.0 * rRefractiveIndex)) / 1.0; (* simplistically assuming 1 min intervals for demo *)
            ELSIF (rLaserReflectancePV < (rReflectanceMin * 1.05)) THEN
                bFringeDetected := FALSE;
            END_IF;
        END_IF;

        IF NOT bEnable THEN
            iState := 40; (* Move to cool down *)
        END_IF;

    40: (* COOL DOWN & PURGE *)
        rRFPIDControlOut := 0.0;
        rTMGaValvePosition := 0.0;
        rChamberVacuumValveOut := 100.0;

        IF rSusceptorTempPV < 50.0 THEN
