        rTMGaValvePosition := 0.0;
        rChamberVacuumValveOut := 100.0;
        bAlarm := TRUE;
        bProcessInterlockActive := TRUE;

        IF NOT bEmergencyStop THEN
            (* Latch until E-stop is reset and system disabled *)
        ELSIF NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

