FUNCTION_BLOCK FB_CheeseVatMasterControl
TITLE = 'Industrial Cheese Vat Advanced Controller'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    bEnable : BOOL; // Enable vat operations
    bEmergencyStop : BOOL; // Emergency stop active low
    fVatTemperature : REAL; // Current vat temperature (Deg C)
    fAgitatorSpeedFeedback : REAL; // Current agitator speed (RPM)
    fAgitatorTorqueFeedback : REAL; // Current agitator torque (%)
    fWheyLevel : REAL; // Current whey level (Liters)
    fCoagulationSensorVal : REAL; // Light backscatter / optical density sensor

    // Setpoints
    fTargetCutTorque : REAL; // Target torque for optimal curd cutting
    fTargetTempCoagulation : REAL; // Target temperature for rennet activity
    tRennetActionTime : TIME; // Estimated time for coagulation
    fPumpCavitationThreshold : REAL; // Vibration/pressure threshold for cavitation
    fDrainagePumpVibration : REAL; // Feedback from drainage pump
END_VAR

VAR_OUTPUT
    bHeaterEnable : BOOL;
    fHeaterValvePos : REAL; // 0.0 to 100.0 %

    bAgitatorEnable : BOOL;
    fAgitatorSpeedRef : REAL; // Speed reference to VFD

    bDrainagePumpEnable : BOOL;
    fDrainagePumpSpeedRef : REAL;

    iVatState : INT; // Current state of the vat process
    bAlarmActive : BOOL;
    sAlarmMessage : STRING[50];
END_VAR

VAR
    // State Machine
    eState : (INIT, FILLING, HEATING, RENNET_ADDITION, COAGULATION, CUTTING, COOKING, WHEY_DRAINAGE, CLEANING, FAULT);

    // Timers
    tonCoagulation : TON;
    tonCuttingDuration : TON;
    tonPIDUpdate : TON;

    // Internal Variables
    fTempError : REAL;
    fTempIntegral : REAL;
    fTempDerivative : REAL;
    fTempLastErr : REAL;

    fTorqueError : REAL;
    fTorqueIntegral : REAL;

    bCavitationDetected : BOOL;
    iCavitationRetryCount : INT;
END_VAR

// Constants
VAR CONSTANT
    PID_KP_TEMP : REAL := 2.5;
    PID_KI_TEMP : REAL := 0.1;
    PID_KD_TEMP : REAL := 0.5;

    PID_KP_TORQUE : REAL := 1.2;
    PID_KI_TORQUE : REAL := 0.05;

    MAX_HEATER_VALVE : REAL := 100.0;
    MAX_AGITATOR_SPEED : REAL := 1500.0;
END_VAR

BEGIN
    // Emergency Stop Handling
    IF NOT bEmergencyStop THEN
        eState := FAULT;
        bAlarmActive := TRUE;
        sAlarmMessage := 'Emergency Stop Activated';
        bHeaterEnable := FALSE;
        fHeaterValvePos := 0.0;
        bAgitatorEnable := FALSE;
        fAgitatorSpeedRef := 0.0;
        bDrainagePumpEnable := FALSE;
        fDrainagePumpSpeedRef := 0.0;
        RETURN;
    END_IF;

    // State Machine Processing
    CASE eState OF
        INIT:
            IF bEnable THEN
                eState := HEATING;
                bAlarmActive := FALSE;
                sAlarmMessage := 'Ready';
            END_IF;

        HEATING:
            bHeaterEnable := TRUE;

            // PID for Temperature Control
            fTempError := fTargetTempCoagulation - fVatTemperature;
            fTempIntegral := fTempIntegral + (fTempError * 0.1);
            fTempDerivative := (fTempError - fTempLastErr) / 0.1;
            fTempLastErr := fTempError;

            fHeaterValvePos := (PID_KP_TEMP * fTempError) + (PID_KI_TEMP * fTempIntegral) + (PID_KD_TEMP * fTempDerivative);

            IF fHeaterValvePos > MAX_HEATER_VALVE THEN
                fHeaterValvePos := MAX_HEATER_VALVE;
            ELSIF fHeaterValvePos < 0.0 THEN
                fHeaterValvePos := 0.0;
            END_IF;

            IF ABS(fTempError) < 0.5 THEN
                eState := RENNET_ADDITION;
                fHeaterValvePos := 0.0; // Maintain temp
            END_IF;

        RENNET_ADDITION:
            // Placeholder for rennet dosing mechanism
            tonCoagulation(IN := FALSE);
            eState := COAGULATION;

        COAGULATION:
            // Monitor light backscatter sensor for coagulation
            tonCoagulation(IN := TRUE, PT := tRennetActionTime);

            IF fCoagulationSensorVal > 85.0 OR tonCoagulation.Q THEN
                eState := CUTTING;
                fTorqueIntegral := 0.0;
            END_IF;

        CUTTING:
            bAgitatorEnable := TRUE;

            // PI Control for Agitator Torque Profiling
            fTorqueError := fTargetCutTorque - fAgitatorTorqueFeedback;
            fTorqueIntegral := fTorqueIntegral + (fTorqueError * 0.1);

            fAgitatorSpeedRef := (PID_KP_TORQUE * fTorqueError) + (PID_KI_TORQUE * fTorqueIntegral);

            IF fAgitatorSpeedRef > MAX_AGITATOR_SPEED THEN
                fAgitatorSpeedRef := MAX_AGITATOR_SPEED;
            ELSIF fAgitatorSpeedRef < 100.0 THEN
                fAgitatorSpeedRef := 100.0;
            END_IF;

            tonCuttingDuration(IN := TRUE, PT := T#15M);
            IF tonCuttingDuration.Q THEN
                bAgitatorEnable := FALSE;
                eState := WHEY_DRAINAGE;
            END_IF;

        WHEY_DRAINAGE:
            bDrainagePumpEnable := TRUE;

            // Cavitation Suppression Logic
            IF fDrainagePumpVibration > fPumpCavitationThreshold THEN
                bCavitationDetected := TRUE;
                iCavitationRetryCount := iCavitationRetryCount + 1;
                fDrainagePumpSpeedRef := fDrainagePumpSpeedRef * 0.5; // Throttle down
            ELSE
                bCavitationDetected := FALSE;
                IF fDrainagePumpSpeedRef < 1000.0 THEN
                    fDrainagePumpSpeedRef := fDrainagePumpSpeedRef + 10.0; // Ramp up
                END_IF;
            END_IF;

            IF iCavitationRetryCount > 10 THEN
                eState := FAULT;
                sAlarmMessage := 'Drainage Pump Cavitation Fault';
                bAlarmActive := TRUE;
                bDrainagePumpEnable := FALSE;
            END_IF;

            IF fWheyLevel < 5.0 THEN
                bDrainagePumpEnable := FALSE;
                eState := CLEANING;
            END_IF;

        CLEANING:
            // CIP (Clean In Place) sequence placeholder
            IF NOT bEnable THEN
                eState := INIT;
            END_IF;

        FAULT:
            // Wait for reset
            IF NOT bEnable THEN
                bAlarmActive := FALSE;
                eState := INIT;
                iCavitationRetryCount := 0;
            END_IF;

    END_CASE;

    iVatState := eState;

END_FUNCTION_BLOCK
