        (* Basic Proportional Control for IR Heater *)
        rTempError := rMoldTempTarget_C - rActualMoldTemp_C;
        IF rTempError > 0.0 THEN
            rHeaterOutput_Pct := rTempError * 5.0; (* Kp = 5.0 *)
            IF rHeaterOutput_Pct > 100.0 THEN rHeaterOutput_Pct := 100.0; END_IF;
