    rHeaterOutput_Pct := 0.0;
    bTransportMotorRun := FALSE;
    bDepositorServoEnable := FALSE;
    bVibeZone1Run := FALSE;
    bVibeZone2Run := FALSE;
    bVibeZone3Run := FALSE;
END_IF
