FUNCTION_BLOCK "Bottling_RotaryFiller_PN_Diag"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    CIP_Start : Bool;
    Bottle_Present : Bool;
    Cap_Level_Low : Bool;
    Speed_Setpoint : Real;
    PN_Status_Word : Word; // Profinet Status from Drives
END_VAR
VAR_OUTPUT
    Filler_Running : Bool;
