FUNCTION_BLOCK FB_MultiStageForgingPress
VAR_INPUT
    bStartProcess : BOOL; // Start the forging cycle
    bEmergencyStop : BOOL; // E-Stop condition
    rTargetTemperature : REAL; // Target billet temp (C)
    rCurrentTemperature : REAL; // Current billet temp from pyrometer
    iActiveStage : INT; // Current forging stage (1-4)
    rRamPosition : REAL; // Ram position feedback (mm)
    rRamPressure : REAL; // Hydraulic pressure feedback (bar)
    bManipulatorReady : BOOL; // Manipulator holding billet
END_VAR
VAR_OUTPUT
    bHeatingOn : BOOL; // Induction heater control
    rHeatingPower : REAL; // Induction power output (0-100%)
    bRamDown : BOOL; // Drive ram down
    bRamUp : BOOL; // Drive ram up
    rRamForceRef : REAL; // Force reference to hydraulic servo (kN)
    bManipulatorRelease : BOOL; // Release billet
    bProcessComplete : BOOL; // Forging cycle done
    bFault : BOOL; // Fault active
    iErrorCode : INT; // Fault code
END_VAR
VAR
    iState : INT := 0; // State machine state
    rStage1Tonnage : REAL := 5000.0;
    rStage2Tonnage : REAL := 8000.0;
    rStage3Tonnage : REAL := 12000.0;
    rStage4Tonnage : REAL := 15000.0;
    rHeatingIntegral : REAL := 0.0;
    rHeatingError : REAL;
    rHeatingKp : REAL := 2.5;
    rHeatingKi : REAL := 0.1;
    tTimer : TON;
    bTimerRun : BOOL;
END_VAR

// Emergency Stop Handling
IF bEmergencyStop THEN
    iState := 99; // Fault state
END_IF;

// Main State Machine
CASE iState OF
    0: // Idle
        bHeatingOn := FALSE;
        rHeatingPower := 0.0;
        bRamDown := FALSE;
        bRamUp := TRUE;
        rRamForceRef := 0.0;
        bManipulatorRelease := FALSE;
        bProcessComplete := FALSE;
        bFault := FALSE;
        iErrorCode := 0;
        bTimerRun := FALSE;

        IF bStartProcess AND bManipulatorReady THEN
            iState := 10;
        END_IF;

    10: // Billet Heating Phase (PI Control)
        bHeatingOn := TRUE;
        rHeatingError := rTargetTemperature - rCurrentTemperature;
        rHeatingIntegral := rHeatingIntegral + (rHeatingError * 0.1); // Assuming 100ms cycle
        rHeatingPower := (rHeatingError * rHeatingKp) + (rHeatingIntegral * rHeatingKi);

        IF rHeatingPower > 100.0 THEN
            rHeatingPower := 100.0;
        ELSIF rHeatingPower < 0.0 THEN
            rHeatingPower := 0.0;
        END_IF;

        IF rHeatingError < 10.0 THEN // Within 10 degrees
            iState := 20; // Ready for forging
        END_IF;

    20: // Stage Forging Logic
        bHeatingOn := FALSE;
        rHeatingPower := 0.0;
        bRamDown := TRUE;
        bRamUp := FALSE;

        // Tonnage progression based on active stage
        CASE iActiveStage OF
            1: rRamForceRef := rStage1Tonnage;
            2: rRamForceRef := rStage2Tonnage;
            3: rRamForceRef := rStage3Tonnage;
            4: rRamForceRef := rStage4Tonnage;
        ELSE
            iState := 99; // Invalid stage fault
            iErrorCode := 1;
        END_CASE;

        // Dwell timer
        bTimerRun := TRUE;
        tTimer(IN:=bTimerRun, PT:=T#2S); // 2 second dwell

        IF tTimer.Q THEN
            bTimerRun := FALSE;
            iState := 30; // Retract Ram
        END_IF;

    30: // Ram Retraction
        bRamDown := FALSE;
        bRamUp := TRUE;
        rRamForceRef := 0.0;

        IF rRamPosition < 10.0 THEN // Home position threshold
            IF iActiveStage >= 4 THEN
                iState := 40; // Finish
            ELSE
                iState := 0; // Wait for next stage signal
            END_IF;
        END_IF;

    40: // Release and Complete
        bManipulatorRelease := TRUE;
        bProcessComplete := TRUE;
        bRamUp := FALSE;
        IF NOT bStartProcess THEN
            iState := 0; // Reset
        END_IF;

    99: // Fault
        bHeatingOn := FALSE;
        rHeatingPower := 0.0;
        bRamDown := FALSE;
        bRamUp := TRUE;
        rRamForceRef := 0.0;
        bFault := TRUE;
        bTimerRun := FALSE;
        IF NOT bEmergencyStop THEN
            // Requires manual intervention to clear iState
        END_IF;

END_CASE;

tTimer(IN:=bTimerRun, PT:=T#2S); // Call timer instance
``END_FUNCTION_BLOCK
