FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bStartMounting : BOOL; // Initiate the mounting sequence
    bEStop : BOOL; // Emergency stop
    rCameraLeftX : REAL; // Vision system left register mark X position (um)
    rCameraLeftY : REAL; // Vision system left register mark Y position (um)
    rCameraRightX : REAL; // Vision system right register mark X position (um)
    rCameraRightY : REAL; // Vision system right register mark Y position (um)
    rTargetTolerance : REAL := 5.0; // Allowed alignment error (um)
    rCylinderPressureLeft : REAL; // Left cylinder contact pressure (bar)
    rCylinderPressureRight : REAL; // Right cylinder contact pressure (bar)
    bPlateTailDetected : BOOL; // Sensor input for plate tail detection
END_VAR

VAR_OUTPUT
    bSequenceRunning : BOOL; // True while sequence is active
    bMountingComplete : BOOL; // True when mounting is successfully completed
    bError : BOOL; // True if an error occurred
    nErrorID : INT; // Error code

    // Physical I/O commands
    bDriveEnable : BOOL; // Enable cylinder rotation drive
    rTargetVelocity : REAL; // Target rotation velocity (deg/s)
    bVacuumEnable : BOOL; // Enable vacuum table
    bPressureRollersDown : BOOL; // Command pressure rollers to descend
    rLeftActuatorPosition : REAL; // Position command for left micro-actuator (um)
    rRightActuatorPosition : REAL; // Position command for right micro-actuator (um)
END_VAR

VAR
    eState : (IDLE, ALIGN_MARKS, APPLY_PRESSURE, ROTATE_CYLINDER, LAYDOWN_TAIL, COMPLETE, FAULT);
    rErrorLeftX : REAL;
    rErrorLeftY : REAL;
    rErrorRightX : REAL;
    rErrorRightY : REAL;
    bAligned : BOOL;
    tTimer : TON;
END_VAR

// Reset logic
IF bEStop THEN
    eState := FAULT;
    bDriveEnable := FALSE;
    bVacuumEnable := FALSE;
    bPressureRollersDown := FALSE;
    bSequenceRunning := FALSE;
    nErrorID := 999;
END_IF

// State Machine
CASE eState OF
    IDLE:
        bMountingComplete := FALSE;
        bError := FALSE;
        nErrorID := 0;
        bDriveEnable := FALSE;
        bVacuumEnable := TRUE;
        bPressureRollersDown := FALSE;
        rTargetVelocity := 0.0;

        IF bStartMounting AND NOT bEStop THEN
            eState := ALIGN_MARKS;
            bSequenceRunning := TRUE;
        END_IF

    ALIGN_MARKS:
        // Calculate alignment errors
        rErrorLeftX := rCameraLeftX; // Assuming target is 0,0
        rErrorLeftY := rCameraLeftY;
        rErrorRightX := rCameraRightX;
        rErrorRightY := rCameraRightY;

        // Output correction to actuators
        rLeftActuatorPosition := -rErrorLeftX; 
        rRightActuatorPosition := -rErrorRightX;

        bAligned := (ABS(rErrorLeftX) <= rTargetTolerance) AND (ABS(rErrorLeftY) <= rTargetTolerance) AND
                    (ABS(rErrorRightX) <= rTargetTolerance) AND (ABS(rErrorRightY) <= rTargetTolerance);

        IF bAligned THEN
            eState := APPLY_PRESSURE;
        END_IF

    APPLY_PRESSURE:
        bPressureRollersDown := TRUE;

        // Monitor pressure feedback
        IF rCylinderPressureLeft > 4.5 AND rCylinderPressureRight > 4.5 THEN
            eState := ROTATE_CYLINDER;
        END_IF

        // Timeout check
        tTimer(IN := TRUE, PT := T#5s);
        IF tTimer.Q THEN
            eState := FAULT;
            nErrorID := 101; // Pressure timeout
            tTimer(IN := FALSE);
        END_IF

    ROTATE_CYLINDER:
        tTimer(IN := FALSE); // Reset timer
        bDriveEnable := TRUE;
        rTargetVelocity := 10.0; // Slow rotation for laydown

        // Disable vacuum progressively (simulated here)
        bVacuumEnable := FALSE; 

        IF bPlateTailDetected THEN
            eState := LAYDOWN_TAIL;
        END_IF

    LAYDOWN_TAIL:
        rTargetVelocity := 5.0; // Slower for tail

        tTimer(IN := TRUE, PT := T#2s); // Wait for tail to be pressed
        IF tTimer.Q THEN
            eState := COMPLETE;
            tTimer(IN := FALSE);
        END_IF

    COMPLETE:
        bDriveEnable := FALSE;
        bPressureRollersDown := FALSE;
        rTargetVelocity := 0.0;
        bSequenceRunning := FALSE;
        bMountingComplete := TRUE;

        IF NOT bStartMounting THEN
            eState := IDLE;
        END_IF

    FAULT:
        bError := TRUE;
        bSequenceRunning := FALSE;
        bDriveEnable := FALSE;
        bPressureRollersDown := FALSE;

        IF NOT bEStop AND NOT bStartMounting THEN
            eState := IDLE;
        END_IF
END_CASE
