FUNCTION_BLOCK FB_AmpouleFillingSealing
VAR_INPUT
    bStart_Process        : BOOL;   (* Start signal from HMI *)
    bEmergency_Stop       : BOOL;   (* Safety relay OK *)
    bAmpoule_Present      : BOOL;   (* Photoelectric sensor at loading station *)
    rGas_Pressure_N2      : REAL;   (* Nitrogen pressure in bar *)
    rOxyGas_Pressure      : REAL;   (* Oxygen-Gas mixture pressure in bar *)
    bFlame_Detected       : BOOL;   (* UV flame detector *)
    rTarget_Fill_Vol      : REAL;   (* Setpoint for peristaltic pump (mL) *)
    rMachine_Speed        : REAL;   (* VFD speed reference (Ampoules/min) *)
END_VAR

VAR_OUTPUT
    bPump_Drive_Run       : BOOL;   (* Enable peristaltic pump motor *)
    rPump_Speed_Ref       : REAL;   (* Analog speed to pump drive *)
    bValve_N2_Purge       : BOOL;   (* Solenoid valve for Nitrogen *)
    bValve_OxyGas         : BOOL;   (* Solenoid valve for sealing flame *)
    bIgniter_Spark        : BOOL;   (* High voltage spark igniter *)
    bConveyor_Run         : BOOL;   (* Main indexing conveyor *)
    bReject_Gate          : BOOL;   (* Reject non-filled/unsealed ampoules *)
    iMachine_State        : INT;    (* 0=Idle, 1=Purging, 2=Filling, 3=Sealing, 4=Fault *)
    bFault_Alarm          : BOOL;
END_VAR

VAR
    tPurge_Timer          : TON;
    tFill_Timer           : TON;
    tSeal_Timer           : TON;
    tIgnition_Timer       : TON;
    rActual_Fill_Vol      : REAL;
    bGas_Fault            : BOOL;
    bFlame_Fault          : BOOL;
    iStep                 : INT := 0;
END_VAR

(* Main State Machine *)
IF bEmergency_Stop THEN
    iMachine_State := 4;
    iStep := 999;
END_IF;

CASE iStep OF
    0: (* Idle State *)
        bConveyor_Run := FALSE;
        bValve_N2_Purge := FALSE;
        bPump_Drive_Run := FALSE;
        bValve_OxyGas := FALSE;
        bIgniter_Spark := FALSE;
        bFault_Alarm := FALSE;
        iMachine_State := 0;

        IF bStart_Process AND bAmpoule_Present AND (rGas_Pressure_N2 > 1.5) THEN
            iStep := 10;
        END_IF;

    10: (* Indexing Conveyor *)
        bConveyor_Run := TRUE;
        (* Assume mechanical cam switches to stop conveyor at exact position *)
        (* Here simulated by timer for simplicity *)
        tPurge_Timer(IN := TRUE, PT := T#500MS);
        IF tPurge_Timer.Q THEN
            tPurge_Timer(IN := FALSE);
            bConveyor_Run := FALSE;
            iStep := 20;
            iMachine_State := 1;
        END_IF;

    20: (* Nitrogen Pre-Purging *)
        bValve_N2_Purge := TRUE;
        tPurge_Timer(IN := TRUE, PT := T#1S);
        IF tPurge_Timer.Q THEN
            bValve_N2_Purge := FALSE;
            tPurge_Timer(IN := FALSE);
            iStep := 30;
            iMachine_State := 2;
        END_IF;

    30: (* Multi-Head Volumetric Filling *)
        bPump_Drive_Run := TRUE;
        rPump_Speed_Ref := rTarget_Fill_Vol * 10.0; (* Simple scaling *)
        tFill_Timer(IN := TRUE, PT := T#2S);
        IF tFill_Timer.Q THEN
            bPump_Drive_Run := FALSE;
            tFill_Timer(IN := FALSE);
            iStep := 40;
            iMachine_State := 3;
        END_IF;

    40: (* Ignition and Sealing *)
        bValve_OxyGas := TRUE;
        IF NOT bFlame_Detected THEN
            bIgniter_Spark := TRUE;
            tIgnition_Timer(IN := TRUE, PT := T#2S);
            IF tIgnition_Timer.Q AND NOT bFlame_Detected THEN
                bFlame_Fault := TRUE;
                iStep := 999;
            END_IF;
        ELSE
            bIgniter_Spark := FALSE;
            tIgnition_Timer(IN := FALSE);
            tSeal_Timer(IN := TRUE, PT := T#1.5S);
            IF tSeal_Timer.Q THEN
                bValve_OxyGas := FALSE;
                tSeal_Timer(IN := FALSE);
                iStep := 50; (* Go back to indexing *)
            END_IF;
        END_IF;

    50: (* End of Cycle Check *)
        IF NOT bStart_Process THEN
            iStep := 0;
        ELSE
            iStep := 10;
        END_IF;

    999: (* Fault State *)
        bConveyor_Run := FALSE;
        bValve_N2_Purge := FALSE;
        bPump_Drive_Run := FALSE;
        bValve_OxyGas := FALSE;
        bIgniter_Spark := FALSE;
        bFault_Alarm := TRUE;
        iMachine_State := 4;

        IF NOT bEmergency_Stop AND NOT bFlame_Fault AND NOT bGas_Fault THEN
            iStep := 0; (* Reset *)
        END_IF;

END_CASE;

(* Pressure Monitoring *)
IF rGas_Pressure_N2 < 1.0 OR rOxyGas_Pressure < 0.5 THEN
    bGas_Fault := TRUE;
    iStep := 999;
ELSE
    bGas_Fault := FALSE;
END_IF;
END_FUNCTION_BLOCK
```

