FUNCTION_BLOCK "Azipod_Control"
TITLE = 'Azipod Thruster Control'
VERSION : 1.0

VAR_INPUT
    Enable : BOOL; // System enable
    Setpoint_Angle : REAL; // Desired azimuth angle (0.0 to 360.0 degrees)
    Setpoint_Speed : REAL; // Desired thruster speed (RPM)
    Actual_Angle : REAL; // Feedback azimuth angle
    Actual_Speed : REAL; // Feedback thruster speed
    Motor_Current : REAL; // Actual motor current (Amps)
    Max_Allowed_Current : REAL; // Maximum allowed current (Amps)
END_VAR

VAR_OUTPUT
    Angle_Command : REAL; // Output command for azimuth angle
    Speed_Command : REAL; // Output command for thruster speed
    Overload_Active : BOOL; // Overload protection status
    System_Ready : BOOL; // Ready for operation
END_VAR

VAR
    Current_Filter : REAL;
    Filter_Coeff : REAL := 0.1;
    Speed_Limit : REAL;
END_VAR

BEGIN
    // Initialization
    System_Ready := Enable AND NOT Overload_Active;

    IF NOT Enable THEN
        Angle_Command := Actual_Angle;
        Speed_Command := 0.0;
        Overload_Active := FALSE;
        Current_Filter := 0.0;
        RETURN;
    END_IF;

    // Filter motor current
    Current_Filter := Current_Filter + Filter_Coeff * (Motor_Current - Current_Filter);

    // Overload Protection Logic
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    // Speed Control & Synchronization
    IF Overload_Active THEN
        // Reduce speed to prevent trip
        Speed_Limit := Actual_Speed * 0.5;
        IF Setpoint_Speed > Speed_Limit THEN
            Speed_Command := Speed_Limit;
        ELSE
            Speed_Command := Setpoint_Speed;
        END_IF;
    ELSE
        Speed_Command := Setpoint_Speed;
    END_IF;

    // Azimuth Control
    Angle_Command := Setpoint_Angle;

END_FUNCTION_BLOCK
