Here is the master-tier, production-ready IEC 61131-3 Structured Text implementation for the Hyperscale AI GPU Cluster Two-Phase Immersion Cooling & Dynamic Overclocking Controller.

FUNCTION_BLOCK FB_Hyperscale_ImmersionCooling
VAR_INPUT
    bEnable : BOOL; (* System Enable *)
    bStart : BOOL; (* Start command for PackML *)
    bStop : BOOL; (* Stop command for PackML *)
    bAbort : BOOL; (* Abort command for PackML *)

    (* Immersion Tank Sensors *)
    fVaporPressure_atm : LREAL; (* Actual vapor pressure in the tank (atm) *)
    fFluidLevel_mm : LREAL; (* Liquid fluid level (mm) *)
    fCondenserReturnTemp_C : LREAL; (* Temperature of condenser return water *)

    (* IT Load & AI Orchestrator *)
    fTotalClusterPower_kW : LREAL; (* Current IT Power load from GPUs *)
    bGradientSyncPhase : BOOL; (* True if cluster is in deep learning synchronization phase *)
    fMaxOverclockLimit : LREAL := 1.30; (* Max overclocking limit (1.0 = base, 1.30 = +30%) *)

    (* Fluid Properties (e.g. Novec 7100/7000) *)
    fLatentHeatVaporization_kJ_kg : LREAL := 125.0; (* Latent heat of vaporization *)
    fMaxCondenserCapacity_kW : LREAL := 15000.0; (* 15MW max cooling capacity per tank *)
    fSetpointVaporPressure_atm : LREAL := 1.20; (* Target vapor pressure *)
END_VAR

VAR_OUTPUT
    (* PackML State Outputs *)
    nState : INT; (* PackML current state *)
    bSystemReady : BOOL;
    bError : BOOL;

    (* Cooling Actuators *)
    fCondenserWaterValvePos_Pct : LREAL; (* 0-100% valve position for condenser water flow *)
    fCoolantPumpSpeed_Pct : LREAL; (* 0-100% pump speed for fluid circulation *)

    (* AI Cluster Actuators *)
    fAllowedGPUFrequencyMultiplier : LREAL; (* Dynamic DVFS limit sent back to Orchestrator *)

    (* Analytics *)
    fAvailableCoolingHeadroom_kW : LREAL; (* Remaining latent heat removal capacity *)
    fCalculatedBoilingRate_kg_s : LREAL; (* Estimated fluid boiling rate *)
END_VAR

VAR
    (* PackML States Enum Representation *)
    IDLE : INT := 1;
    STARTING : INT := 2;
    EXECUTE : INT := 3;
    STOPPING : INT := 4;
    ABORTING : INT := 5;
    ABORTED : INT := 6;

    (* PID Controllers *)
    fKp_Pressure : LREAL := 45.0;
    fKi_Pressure : LREAL := 2.5;
    fKd_Pressure : LREAL := 10.0;

    fPressureError : LREAL;
    fPressureError_Prev : LREAL;
    fPressureIntegral : LREAL;
    fPressureDerivative : LREAL;

    (* Internal Timers & Variables *)
    tDeltaT : LREAL := 0.1; (* 100ms cycle time assumption *)
    fPowerDissipation_kW : LREAL;
END_VAR

(* 
======================================================================
    PACKML STATE MACHINE
======================================================================
*)
IF bAbort THEN
    nState := ABORTING;
END_IF;

CASE nState OF
    0: (* Uninitialized *)
        IF bEnable THEN
            nState := IDLE;
        END_IF;

    IDLE:
        bSystemReady := TRUE;
        fCondenserWaterValvePos_Pct := 0.0;
        fCoolantPumpSpeed_Pct := 0.0;
        fAllowedGPUFrequencyMultiplier := 1.0;

        IF bStart THEN
            nState := STARTING;
            bSystemReady := FALSE;
        END_IF;

    STARTING:
        (* Pre-circulate cooling fluid and open condenser valves to base levels *)
        fCoolantPumpSpeed_Pct := 30.0;
        fCondenserWaterValvePos_Pct := 15.0;

        IF fFluidLevel_mm > 500.0 THEN (* Check minimum immersion level *)
            nState := EXECUTE;
        ELSE
            nState := ABORTING; (* Fluid level too low, unsafe to start *)
        END_IF;

    EXECUTE:
        (* Main Continuous Control Loop *)

        (* 1. Thermodynamics & Boiling Rate Estimation *)
        (* Convert total power to heat, assuming 99% conversion in GPUs *)
        fPowerDissipation_kW := fTotalClusterPower_kW * 0.99;

        (* m_dot = Q / h_fg *)
        fCalculatedBoilingRate_kg_s := fPowerDissipation_kW / fLatentHeatVaporization_kJ_kg;

        (* 2. Condenser Vapor Pressure PID Control *)
        fPressureError := fVaporPressure_atm - fSetpointVaporPressure_atm;

        (* Anti-windup for integral *)
        IF (fCondenserWaterValvePos_Pct > 0.0 AND fCondenserWaterValvePos_Pct < 100.0) THEN
            fPressureIntegral := fPressureIntegral + (fPressureError * tDeltaT);
        END_IF;

        fPressureDerivative := (fPressureError - fPressureError_Prev) / tDeltaT;
        fPressureError_Prev := fPressureError;

        (* Calculate valve position (0-100%) *)
        fCondenserWaterValvePos_Pct := (fKp_Pressure * fPressureError) + 
                                       (fKi_Pressure * fPressureIntegral) + 
                                       (fKd_Pressure * fPressureDerivative);

        (* Saturation Limits *)
        IF fCondenserWaterValvePos_Pct > 100.0 THEN fCondenserWaterValvePos_Pct := 100.0; END_IF;
        IF fCondenserWaterValvePos_Pct < 0.0 THEN fCondenserWaterValvePos_Pct := 0.0; END_IF;

        (* 3. Thermal-Aware DVFS & Overclocking *)
        (* Calculate remaining capacity in the condenser loop *)
        fAvailableCoolingHeadroom_kW := fMaxCondenserCapacity_kW - (fCondenserWaterValvePos_Pct / 100.0 * fMaxCondenserCapacity_kW);

        (* Dynamic Overclocking logic during Gradient Sync *)
        IF bGradientSyncPhase AND (fAvailableCoolingHeadroom_kW > 2000.0) AND (fVaporPressure_atm < 1.25) THEN
            (* Safely ramp up GPU frequency multiplier based on available headroom, capped at MaxLimit *)
            fAllowedGPUFrequencyMultiplier := 1.0 + ((fAvailableCoolingHeadroom_kW / fMaxCondenserCapacity_kW) * 0.5);
            IF fAllowedGPUFrequencyMultiplier > fMaxOverclockLimit THEN
                fAllowedGPUFrequencyMultiplier := fMaxOverclockLimit;
            END_IF;
        ELSE
            (* Reduce to base frequency if not syncing or limited headroom *)
            fAllowedGPUFrequencyMultiplier := 1.0;
        END_IF;

        (* Pump modulation based on power *)
        fCoolantPumpSpeed_Pct := 30.0 + (fTotalClusterPower_kW / fMaxCondenserCapacity_kW * 70.0);
        IF fCoolantPumpSpeed_Pct > 100.0 THEN fCoolantPumpSpeed_Pct := 100.0; END_IF;

        IF bStop THEN
            nState := STOPPING;
        END_IF;

    STOPPING:
        fAllowedGPUFrequencyMultiplier := 1.0;
        fCoolantPumpSpeed_Pct := fCoolantPumpSpeed_Pct - 1.0;
        fCondenserWaterValvePos_Pct := fCondenserWaterValvePos_Pct - 1.0;

        IF fCoolantPumpSpeed_Pct <= 0.0 AND fCondenserWaterValvePos_Pct <= 0.0 THEN
            fCoolantPumpSpeed_Pct := 0.0;
            fCondenserWaterValvePos_Pct := 0.0;
            nState := IDLE;
        END_IF;

    ABORTING:
        (* Immediate safety shutdown *)
        bError := TRUE;
        fAllowedGPUFrequencyMultiplier := 0.1; (* Force extreme throttling *)
        fCoolantPumpSpeed_Pct := 100.0; (* Max pump to circulate remaining liquid *)
        fCondenserWaterValvePos_Pct := 100.0; (* Max cooling to crash pressure *)
        nState := ABORTED;

    ABORTED:
        IF bStart THEN
            bError := FALSE;
            nState := IDLE;
        END_IF;

ELSE
    nState := IDLE;
END_CASE;
END_FUNCTION_BLOCK
