FUNCTION_BLOCK "FB_Autoclave_Cure_M2"
TITLE = 'Autoclave with Profinet and Diagnostics'
VERSION : '1.2'

VAR_INPUT
    bStart_Cycle : Bool;
    rAct_Temp : Real;
    rAct_Pressure : Real;
    rAct_N2_Level : Real;
    rAct_Vac_Pressure : Real;
    wPN_Device_Status : Word; // Profinet Status Word
END_VAR

VAR_OUTPUT
    bCmd_Heater : Bool;
    bCmd_PressValve : Bool;
    bCmd_N2_Purge : Bool;
    bCmd_Vac_Pump : Bool;
    bAlarm_Abort : Bool;
    wDiag_Code : Word;
    iStep_ID : Int;
END_VAR

VAR
    iState : Int;
    tDwell_Timer : TON_TIME;
    rLast_Vac_Pressure : Real;
    tLeak_Timer : TON_TIME;
END_VAR

BEGIN
    // Diagnostics & Profinet Checks
    IF wPN_Device_Status <> 16#0000 THEN
        wDiag_Code := 16#F001; // Profinet Comm Error
        iState := 99;
    ELSIF rAct_Temp > 200.0 THEN
        wDiag_Code := 16#E001; // Overtemp Fault
        iState := 99;
    ELSE
        wDiag_Code := 16#0000;
    END_IF;

    // Vacuum Leak Detection Subsystem
    tLeak_Timer(IN := (iState > 0 AND iState < 40), PT := T#1S);
    IF tLeak_Timer.Q THEN
        IF (rAct_Vac_Pressure - rLast_Vac_Pressure) > 0.05 THEN
            wDiag_Code := 16#E002; // Vacuum Leak
            iState := 99;
        END_IF;
        rLast_Vac_Pressure := rAct_Vac_Pressure;
        tLeak_Timer(IN := FALSE, PT := T#0S);
    END_IF;

    CASE iState OF
        0: // Idle
            bAlarm_Abort := FALSE;
            IF bStart_Cycle AND (wDiag_Code = 16#0000) THEN iState := 10; END_IF;
        10: // Purge and Vacuum
            bCmd_N2_Purge := TRUE;
            bCmd_Vac_Pump := TRUE;
            IF (rAct_N2_Level > 95.0) AND (rAct_Vac_Pressure < 0.1) THEN
                bCmd_N2_Purge := FALSE;
                iState := 20;
            END_IF;
        20: // Heat & Pressurize
            bCmd_Heater := (rAct_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF (rAct_Temp >= 180.0) AND (rAct_Pressure >= 7.0) THEN iState := 30; END_IF;
        30: // Dwell
            tDwell_Timer(IN := TRUE, PT := T#120M);
            bCmd_Heater := (rAct_Temp < 180.0);
            IF tDwell_Timer.Q THEN
                bCmd_Heater := FALSE;
                bCmd_PressValve := FALSE;
                iState := 40;
            END_IF;
        40: // Cool
            bCmd_Vac_Pump := FALSE;
            IF rAct_Temp < 50.0 THEN iState := 0; tDwell_Timer(IN := FALSE, PT := T#0S); END_IF;
        99: // Abort
            bCmd_Heater := FALSE;
            bCmd_PressValve := FALSE;
            bAlarm_Abort := TRUE;
    END_CASE;
    iStep_ID := iState;
END_FUNCTION_BLOCK
