FUNCTION_BLOCK FB_Lyo_Process_Control
TITLE = 'Pharmaceutical Freeze Drying (Lyophilization) Control'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    bEnableProcess      : BOOL;             // Enable the overall lyophilization process
    eRequestedPhase     : INT;              // 0:Idle, 1:Freezing, 2:Evacuation, 3:PrimaryDrying, 4:SecondaryDrying, 5:Defrost
    rChamberPressure    : REAL;             // Current pressure inside the chamber (mBar)
    rCondenserTemp      : REAL;             // Current condenser coil temperature (Deg C)
    rShelfTempAvg       : REAL;             // Average shelf temperature (Deg C)
    rProductTempAvg     : REAL;             // Average product temperature (Deg C)
    rTargetShelfTemp    : REAL;             // Target setpoint for shelf temperature (Deg C)
    rTargetPressure     : REAL;             // Target setpoint for chamber vacuum (mBar)
    rMaxVacuumTimeMin   : REAL;             // Maximum allowed time to achieve target vacuum
END_VAR

VAR_OUTPUT
    bRoughingPumpCmd    : BOOL;             // Command to start roughing vacuum pump
    bRootsBlowerCmd     : BOOL;             // Command to start Roots blower pump
    bCondenserComp1Cmd  : BOOL;             // Command to start Condenser Compressor 1 (High Stage)
    bCondenserComp2Cmd  : BOOL;             // Command to start Condenser Compressor 2 (Low Stage)
    rShelfHeaterOutput  : REAL;             // Shelf fluid heater output (0.0 to 100.0 %)
    bShelfCoolingValve  : BOOL;             // Open cooling valve to shelf fluid heat exchanger
    bMainVacuumValve    : BOOL;             // Open main butterfly valve between chamber and condenser
    eCurrentState       : INT;              // Current active phase
    bProcessComplete    : BOOL;
    bGeneralAlarm       : BOOL;
    iAlarmCode          : INT;
END_VAR

VAR
    Timer_Evacuation    : TON;
    Timer_CompressorDel : TON;
    rPressureDeadband   : REAL := 0.05;     // 50 microbar deadband
    rTempDeadband       : REAL := 0.5;      // 0.5 deg C deadband
    bCondenserReady     : BOOL;
    bVacuumReady        : BOOL;
END_VAR

// ==============================================================================
// MAIN STATE MACHINE FOR LYOPHILIZATION PHASES
// ==============================================================================
IF NOT bEnableProcess THEN
    eCurrentState := 0;
    bRoughingPumpCmd := FALSE;
    bRootsBlowerCmd := FALSE;
    bCondenserComp1Cmd := FALSE;
    bCondenserComp2Cmd := FALSE;
    rShelfHeaterOutput := 0.0;
    bShelfCoolingValve := FALSE;
    bMainVacuumValve := FALSE;
    bProcessComplete := FALSE;
    bGeneralAlarm := FALSE;
    iAlarmCode := 0;
    RETURN;
END_IF;

eCurrentState := eRequestedPhase;

// Condenser Refrigeration Cascade Control
// To support deep freezing, we cascade two compressors.
bCondenserComp1Cmd := (eCurrentState >= 1) AND (eCurrentState <= 4);
Timer_CompressorDel(IN:=bCondenserComp1Cmd, PT:=T#30S);
bCondenserComp2Cmd := Timer_CompressorDel.Q;

// Condenser Readiness Verification
IF rCondenserTemp <= -60.0 THEN
    bCondenserReady := TRUE;
ELSIF rCondenserTemp > -55.0 THEN
    bCondenserReady := FALSE;
END_IF;

// Vacuum Pump Cascading Logic (Roughing -> Roots)
IF (eCurrentState >= 2) AND (eCurrentState <= 4) AND bCondenserReady THEN
    bRoughingPumpCmd := TRUE;
    // Interlock Roots Blower until roughing pump achieves rough vacuum (< 20 mBar)
    IF rChamberPressure < 20.0 THEN
        bRootsBlowerCmd := TRUE;
    ELSE
        bRootsBlowerCmd := FALSE;
    END_IF;

    // Open Main Vacuum Valve when roughing is established to avoid backstreaming
    IF rChamberPressure < 5.0 THEN
        bMainVacuumValve := TRUE;
    END_IF;
ELSE
    bRoughingPumpCmd := FALSE;
    bRootsBlowerCmd := FALSE;
    bMainVacuumValve := FALSE;
END_IF;

// Evacuation Timeout Monitoring
Timer_Evacuation(IN:=(eCurrentState = 2), PT:=REAL_TO_TIME(rMaxVacuumTimeMin * 60000.0));
IF Timer_Evacuation.Q AND (rChamberPressure > rTargetPressure) THEN
    bGeneralAlarm := TRUE;
    iAlarmCode := 101; // Vacuum Target Timeout
END_IF;

// Shelf Fluid Temperature Regulation (Heating/Cooling profiles)
IF (eCurrentState = 1) THEN // Freezing Phase
    bShelfCoolingValve := TRUE;
    rShelfHeaterOutput := 0.0;
ELSIF (eCurrentState = 3) OR (eCurrentState = 4) THEN // Primary & Secondary Drying (Sublimation & Desorption)
    IF rShelfTempAvg < (rTargetShelfTemp - rTempDeadband) THEN
        rShelfHeaterOutput := 100.0; // Bang-bang or PID output simulation
        bShelfCoolingValve := FALSE;
    ELSIF rShelfTempAvg > (rTargetShelfTemp + rTempDeadband) THEN
        rShelfHeaterOutput := 0.0;
        bShelfCoolingValve := TRUE;
    ELSE
        // Deadband maintenance
        bShelfCoolingValve := FALSE;
    END_IF;
ELSE
    rShelfHeaterOutput := 0.0;
    bShelfCoolingValve := FALSE;
END_IF;

// Process Complete Condition
IF (eCurrentState = 4) AND (rProductTempAvg >= (rTargetShelfTemp - 1.0)) THEN
    bProcessComplete := TRUE;
END_IF;
END_FUNCTION_BLOCK
