FUNCTION_BLOCK "GrainSiloControl_Reasoning"
VERSION : 0.1
   VAR_INPUT 
      DustLevel_A : Real; DustLevel_B : Real;
      AugerTorque : Real;
      ZoneTemps : ARRAY[1..4] OF Real;
      PNIO_Status : Word;
      SystemEnable : Bool;
      // Cybersecurity & SCADA
      UserRoleLevel : Int; // 0=None, 1=Op, 2=Eng, 3=Admin
      ManualOverrideCmd : Bool;
      ManualFwdCmd : Bool; ManualRevCmd : Bool;
      ScadaHeartbeat : Bool;
   END_VAR

   VAR_OUTPUT 
      MistValve : Bool;
      AugerFwd : Bool; AugerRev : Bool;
      AerationFan : Bool;
      DiagErrorWord : Word;
      ScadaDataBlock : Struct
         ActiveState : Int;
         SelectedDustLevel : Real;
      End_Struct;
   END_VAR

   VAR 
      JamTimer : TON; RevTimer : TON; ScadaTimer : TON;
      AntiJamActive, AlarmJam, AlarmFireHazard, ScadaCommLoss : Bool;
      i : Int; MaxTemp, DustVal : Real;
      ManualModeActive : Bool;
   END_VAR

BEGIN
    #DiagErrorWord := 16#0000;
    IF #PNIO_Status <> 16#0000 THEN #DiagErrorWord := #DiagErrorWord OR 16#0001; END_IF;

    // SCADA Heartbeat
    #ScadaTimer(IN := NOT #ScadaHeartbeat, PT := T#5S);
    #ScadaCommLoss := #ScadaTimer.Q;
    IF #ScadaCommLoss THEN #DiagErrorWord := #DiagErrorWord OR 16#0008; END_IF;

    // Redundant Sensor Failover (Dust)
    IF ABS(#DustLevel_A - #DustLevel_B) < 10.0 THEN
        #DustVal := (#DustLevel_A + #DustLevel_B) / 2.0;
    ELSE
        #DustVal := MAX(IN1:=#DustLevel_A, IN2:=#DustLevel_B);
        #DiagErrorWord := #DiagErrorWord OR 16#0010; // Sensor discrepancy
    END_IF;
    #ScadaDataBlock.SelectedDustLevel := #DustVal;

    // Cyber: RBAC Manual Override
    #ManualModeActive := #ManualOverrideCmd AND (#UserRoleLevel >= 2);
    IF #ManualOverrideCmd AND (#UserRoleLevel < 2) THEN
        #DiagErrorWord := #DiagErrorWord OR 16#0020; // Unauthorized Access Attempt
    END_IF;

    // Temperature Monitoring
    #MaxTemp := 0.0;
    FOR #i := 1 TO 4 DO
        IF #ZoneTemps[#i] > #MaxTemp THEN #MaxTemp := #ZoneTemps[#i]; END_IF;
    END_FOR;
    #AlarmFireHazard := (#MaxTemp > 65.0);
    IF #AlarmFireHazard THEN #DiagErrorWord := #DiagErrorWord OR 16#0002; END_IF;

    IF #ManualModeActive THEN
        #AugerFwd := #ManualFwdCmd AND NOT #AlarmFireHazard;
        #AugerRev := #ManualRevCmd AND NOT #AlarmFireHazard;
        #MistValve := FALSE;
        #AerationFan := FALSE;
        #ScadaDataBlock.ActiveState := 99;
    ELSE
        // Auto Logic
        #AerationFan := #SystemEnable AND (#MaxTemp > 40.0) AND NOT #AlarmFireHazard;
        #MistValve := #SystemEnable AND (#DustVal > 50.0) AND NOT #AlarmFireHazard;

        #JamTimer(IN := #SystemEnable AND (#AugerTorque > 150.0) AND NOT #AntiJamActive, PT := T#2S);
        IF #JamTimer.Q THEN #AntiJamActive := TRUE; END_IF;
        #RevTimer(IN := #AntiJamActive, PT := T#3S);
        IF #RevTimer.Q THEN
            #AntiJamActive := FALSE;
            IF #AugerTorque > 150.0 THEN #AlarmJam := TRUE; END_IF;
        END_IF;
        IF #AlarmJam THEN #DiagErrorWord := #DiagErrorWord OR 16#0004; END_IF;

        IF #SystemEnable AND NOT #AlarmJam AND NOT #AlarmFireHazard AND NOT #ScadaCommLoss THEN
            #AugerFwd := NOT #AntiJamActive;
            #AugerRev := #AntiJamActive;
            #ScadaDataBlock.ActiveState := 1;
        ELSE
            #AugerFwd := FALSE; #AugerRev := FALSE;
            #ScadaDataBlock.ActiveState := 0;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
