FUNCTION_BLOCK FB_FlexoPressMasterControl
TITLE = 'High-Speed Web Flexographic Printing Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

(* 
   This function block controls the critical parameters of a high-speed web flexographic printing press.
   It handles:
   1. Cascading web tension control across 4 distinct zones (Unwind, Infeed, Print, Rewind).
   2. Anilox roller doctor blade pressure regulation based on press speed and ink viscosity.
   3. UV curing lamp intensity profiling synchronized with web speed and substrate characteristics.
*)

VAR_INPUT
    bEnablePress           : BOOL;  // Main enable signal for the press
    rMasterSpeedSetPt      : REAL;  // Master speed setpoint (m/min)
    rActualWebSpeed        : REAL;  // Actual measured web speed (m/min)

    // Tension Feedback (Load Cells)
    rTensionUnwindFeedback : REAL;  // N
    rTensionInfeedFeedback : REAL;  // N
    rTensionPrintFeedback  : REAL;  // N
    rTensionRewindFeedback : REAL;  // N

    // Process Variables
    rInkViscosity          : REAL;  // mPa.s
    rSubstrateThickness    : REAL;  // microns
    rSubstrateOpacity      : REAL;  // %

    // Tension Setpoints
    rTensionUnwindSetPt    : REAL;
    rTensionInfeedSetPt    : REAL;
    rTensionPrintSetPt     : REAL;
    rTensionRewindSetPt    : REAL;
END_VAR

VAR_OUTPUT
    // Tension Control Signals (Torque or Speed Trims)
    rUnwindDriveCmd        : REAL;
    rInfeedDriveCmd        : REAL;
    rPrintDriveCmd         : REAL;
    rRewindDriveCmd        : REAL;

    // Doctor Blade Pressure Command
    rDoctorBladePressureCmd: REAL;  // bar

    // UV Curing Control
    rUVLamp1IntensityCmd   : REAL;  // %
    rUVLamp2IntensityCmd   : REAL;  // %
    rUVLamp3IntensityCmd   : REAL;  // %
    rUVLamp4IntensityCmd   : REAL;  // %

    // Status and Alarms
    bSystemReady           : BOOL;
    bWebBreakAlarm         : BOOL;
    bUVFaultAlarm          : BOOL;
END_VAR

VAR
    // Internal PID controllers for tension (Simplified logic for demonstration)
    rUnwindError, rUnwindIntegral, rUnwindDerivative, rUnwindPrevError : REAL;
    rInfeedError, rInfeedIntegral, rInfeedDerivative, rInfeedPrevError : REAL;
    rPrintError,  rPrintIntegral,  rPrintDerivative,  rPrintPrevError  : REAL;
    rRewindError, rRewindIntegral, rRewindDerivative, rRewindPrevError : REAL;

    // PID Gains
    rKp : REAL := 1.5;
    rKi : REAL := 0.2;
    rKd : REAL := 0.05;

    // Timers
    tWebBreakTimer : TON;
    tUVCoolDown    : TOF;

    // Calculation constants
    rBaseBladePressure : REAL := 2.0; // bar
    rMaxWebSpeed       : REAL := 600.0; // m/min

    bInitDone          : BOOL := FALSE;

    // Temp variables
    rBaseUV : REAL;
    rThicknessModifier : REAL;
    rOpacityModifier : REAL;
    rFinalUV : REAL;
END_VAR

// Initialization
IF NOT bInitDone THEN
    rUnwindIntegral := 0.0;
    rInfeedIntegral := 0.0;
    rPrintIntegral := 0.0;
    rRewindIntegral := 0.0;
    bInitDone := TRUE;
END_IF;

IF NOT bEnablePress THEN
    rUnwindDriveCmd := 0.0;
    rInfeedDriveCmd := 0.0;
    rPrintDriveCmd  := 0.0;
    rRewindDriveCmd := 0.0;
    rDoctorBladePressureCmd := 0.0;
    rUVLamp1IntensityCmd := 0.0;
    rUVLamp2IntensityCmd := 0.0;
    rUVLamp3IntensityCmd := 0.0;
    rUVLamp4IntensityCmd := 0.0;
    bSystemReady := FALSE;
    RETURN;
END_IF;

bSystemReady := TRUE;

// --- 1. Cascading Web Tension Zones Control ---
// Unwind Zone (Braking/Regen)
rUnwindError := rTensionUnwindSetPt - rTensionUnwindFeedback;
rUnwindIntegral := rUnwindIntegral + rUnwindError;
rUnwindDerivative := rUnwindError - rUnwindPrevError;
rUnwindDriveCmd := (rKp * rUnwindError) + (rKi * rUnwindIntegral) + (rKd * rUnwindDerivative);
rUnwindPrevError := rUnwindError;

// Infeed Zone (Nip Roller)
rInfeedError := rTensionInfeedSetPt - rTensionInfeedFeedback;
rInfeedIntegral := rInfeedIntegral + rInfeedError;
rInfeedDerivative := rInfeedError - rInfeedPrevError;
rInfeedDriveCmd := rMasterSpeedSetPt + ((rKp * rInfeedError) + (rKi * rInfeedIntegral) + (rKd * rInfeedDerivative));
rInfeedPrevError := rInfeedError;

// Print Zone (Central Impression Cylinder / Unit Drives)
rPrintError := rTensionPrintSetPt - rTensionPrintFeedback;
rPrintIntegral := rPrintIntegral + rPrintError;
rPrintDerivative := rPrintError - rPrintPrevError;
rPrintDriveCmd := rMasterSpeedSetPt + ((rKp * rPrintError) + (rKi * rPrintIntegral) + (rKd * rPrintDerivative));
rPrintPrevError := rPrintError;

// Rewind Zone (Winder)
rRewindError := rTensionRewindSetPt - rTensionRewindFeedback;
rRewindIntegral := rRewindIntegral + rRewindError;
rRewindDerivative := rRewindError - rRewindPrevError;
rRewindDriveCmd := rMasterSpeedSetPt + ((rKp * rRewindError) + (rKi * rRewindIntegral) + (rKd * rRewindDerivative));
rRewindPrevError := rRewindError;

// Web Break Detection
IF (rActualWebSpeed > 50.0) AND 
   (rTensionPrintFeedback < (rTensionPrintSetPt * 0.1)) THEN
    tWebBreakTimer(IN := TRUE, PT := T#500ms);
ELSE
    tWebBreakTimer(IN := FALSE, PT := T#500ms);
END_IF;

bWebBreakAlarm := tWebBreakTimer.Q;

// --- 2. Anilox Roller Doctor Blade Pressure Regulation ---
// Pressure needs to increase slightly with speed to prevent hydroplaning,
// and adjust based on ink viscosity.
rDoctorBladePressureCmd := rBaseBladePressure + 
                           (rActualWebSpeed / rMaxWebSpeed) * 0.5 + 
                           (rInkViscosity - 200.0) * 0.005;

// Clamp pressure
IF rDoctorBladePressureCmd > 4.5 THEN
    rDoctorBladePressureCmd := 4.5;
ELSIF rDoctorBladePressureCmd < 1.0 THEN
    rDoctorBladePressureCmd := 1.0;
END_IF;

// --- 3. UV Curing Lamp Intensity Profiling ---
// Intensity is proportional to line speed and substrate thickness/opacity.
// Requires minimum speed to turn on to prevent burning the substrate.
IF rActualWebSpeed > 20.0 THEN
    rBaseUV := (rActualWebSpeed / rMaxWebSpeed) * 100.0;

    // Modify based on substrate properties (thicker/more opaque requires more energy)
    rThicknessModifier := rSubstrateThickness * 0.1; // e.g., 50 microns = +5%
    rOpacityModifier := rSubstrateOpacity * 0.05;    // e.g., 80% = +4%

    rFinalUV := rBaseUV + rThicknessModifier + rOpacityModifier;

    // Clamp to 100%
    IF rFinalUV > 100.0 THEN rFinalUV := 100.0; END_IF;

    // Distribute across 4 lamps (can stagger them for profile)
    rUVLamp1IntensityCmd := rFinalUV;
    rUVLamp2IntensityCmd := rFinalUV * 0.9;
    rUVLamp3IntensityCmd := rFinalUV * 0.8;
    rUVLamp4IntensityCmd := rFinalUV * 1.0; // Final bump
ELSE
    rUVLamp1IntensityCmd := 0.0;
    rUVLamp2IntensityCmd := 0.0;
    rUVLamp3IntensityCmd := 0.0;
    rUVLamp4IntensityCmd := 0.0;
END_IF;

END_FUNCTION_BLOCK
