FUNCTION_BLOCK FB_WaveEnergy_Desalination
TITLE = 'Wave Energy Point-Absorber & RO Desalination Controller'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Data Architect'

// -----------------------------------------------------------------------------
// DESCRIPTION:
// Master-tier controller for a point-absorber wave energy converter (WEC).
// Features Direct-Drive Linear Generator for electrical power and 
// integrated Reverse Osmosis (RO) high-pressure desalination pumping.
// Includes wave-by-wave latching control (resonance tuning).
// -----------------------------------------------------------------------------

VAR_INPUT
    bEnable                 : BOOL;                 // PackML Enable Command
    bReset                  : BOOL;                 // Fault Reset
    fHeavePosition          : LREAL;                // [m] Current buoy heave position
    fHeaveVelocity          : LREAL;                // [m/s] Current buoy heave velocity
    fWaveElevationSensor    : LREAL;                // [m] Up-wave radar/ADCP surface elevation
    fPTO_Force_Feedback     : LREAL;                // [N] Measured Power Take-Off force
    fRO_FeedPressure        : LREAL;                // [psi] Reverse Osmosis membrane feed pressure
    fRO_PermeateFlow        : LREAL;                // [L/min] Freshwater production rate
    fGridVoltage            : LREAL;                // [V] AC Grid Voltage
    fGridFrequency          : LREAL;                // [Hz] AC Grid Frequency
END_VAR

VAR_OUTPUT
    eState                  : INT;                  // Current machine state (0=IDLE, 1=EXECUTE)
    bHydraulicLatchCmd      : BOOL;                 // TRUE = Lock cylinder (Latching), FALSE = Free
    fPTODampingCmd          : LREAL;                // [N/(m/s)] Linear generator damping command
    fRO_BypassValveCmd      : LREAL;                // [%] 0.0 to 100.0% Bypass valve for RO pressure regulation
    bGridSyncContactor      : BOOL;                 // Close grid tie contactor
    bFault                  : BOOL;                 // Active Fault
    nFaultCode              : UDINT;                // Fault code
    fPowerGenerated         : LREAL;                // [kW] Instantaneous electrical power
END_VAR

VAR
    // State Machine Constants (Simulated PackML)
    STATE_IDLE              : INT := 0;
    STATE_STARTING          : INT := 1;
    STATE_EXECUTE           : INT := 2;
    STATE_ABORTED           : INT := 3;

    // Wave Spectral Analysis & Kinematics
    fZeroCrossingTime       : LREAL := 0.0;
    fPrevWaveElevation      : LREAL := 0.0;
    fPeakPeriod_Tp          : LREAL := 10.0;        // [s] Estimated wave period
    fWaveFreq_w             : LREAL := 0.628;       // [rad/s]

    // Hydrodynamic Parameters
    fMass_m                 : LREAL := 150000.0;    // [kg] Buoy mass
    fAddedMass_ma           : LREAL := 80000.0;     // [kg] Infinite frequency added mass
    fHydroStiff_K           : LREAL := 250000.0;    // [N/m] Hydrostatic stiffness
    fNaturalFreq_wn         : LREAL;                // [rad/s] Natural frequency

    // Latching Logic
    bVelocityZeroCross      : BOOL;
    fPrevVelocity           : LREAL := 0.0;
    fLatchingTimer          : LREAL := 0.0;         // [s] Time spent in latched state
    fLatchingDurationReq    : LREAL := 0.0;         // [s] Required latch duration to match phase

    // Reverse Osmosis (RO) Control
    fTargetROPressure       : LREAL := 800.0;       // [psi] Optimal RO operating pressure
    fRO_Kp                  : LREAL := 2.5;
    fRO_Ki                  : LREAL := 0.5;
    fRO_Error               : LREAL := 0.0;
    fRO_Integral            : LREAL := 0.0;

    // Timers & System
    tCycleTime              : LREAL := 0.01;        // [s] 10ms execution cycle
    fClock                  : LREAL := 0.0;         // [s] Internal high-res clock
END_VAR

// -----------------------------------------------------------------------------
// SYSTEM INITIALIZATION & KINEMATICS
// -----------------------------------------------------------------------------
fClock := fClock + tCycleTime;

// Fault Handling Priority
IF bFault THEN
    eState := STATE_ABORTED;
    bHydraulicLatchCmd := TRUE; // Fail-safe lock
    fRO_BypassValveCmd := 100.0; // Open bypass to depressurize
    bGridSyncContactor := FALSE;

    IF bReset THEN
        bFault := FALSE;
        nFaultCode := 0;
        eState := STATE_IDLE;
    END_IF;
    RETURN;
END_IF;

// Calculate System Natural Frequency (wn = SQRT(K / (m + ma)))
fNaturalFreq_wn := SQRT(fHydroStiff_K / (fMass_m + fAddedMass_ma));

// Spectral Wave Analysis (Zero-crossing to estimate Tp)
IF (fWaveElevationSensor >= 0.0 AND fPrevWaveElevation < 0.0) THEN
    fPeakPeriod_Tp := fClock - fZeroCrossingTime;
    fZeroCrossingTime := fClock;
    IF fPeakPeriod_Tp > 0.1 THEN
        fWaveFreq_w := (2.0 * 3.14159265359) / fPeakPeriod_Tp;
    END_IF;
END_IF;
fPrevWaveElevation := fWaveElevationSensor;

// -----------------------------------------------------------------------------
// MAIN PACKML STATE MACHINE
// -----------------------------------------------------------------------------
CASE eState OF

    STATE_IDLE:
        bHydraulicLatchCmd := TRUE; // Locked while idle
        fPTODampingCmd := 0.0;
        fRO_BypassValveCmd := 100.0;
        bGridSyncContactor := FALSE;

        IF bEnable THEN
            eState := STATE_STARTING;
        END_IF;

    STATE_STARTING:
        // Grid Synchronization Check
        IF ABS(fGridVoltage - 400.0) < 20.0 AND ABS(fGridFrequency - 50.0) < 0.5 THEN
            bGridSyncContactor := TRUE;
            eState := STATE_EXECUTE;
        ELSE
            bFault := TRUE;
            nFaultCode := 1001; // Grid Sync Failure
        END_IF;

    STATE_EXECUTE:
        // ---------------------------------------------------------------------
        // 1. WAVE-BY-WAVE LATCHING CONTROL (RESONANCE TUNING)
        // ---------------------------------------------------------------------
        // Detect extrema: Velocity crosses zero
        IF (fHeaveVelocity >= 0.0 AND fPrevVelocity < 0.0) OR (fHeaveVelocity <= 0.0 AND fPrevVelocity > 0.0) THEN
            bVelocityZeroCross := TRUE;
        ELSE
            bVelocityZeroCross := FALSE;
        END_IF;

        // Phase control logic: 
        // If incoming wave frequency is lower than natural frequency, we apply latching
        // Latching duration = (Tw / 2) - (Tn / 2)
        IF fWaveFreq_w < fNaturalFreq_wn THEN
            fLatchingDurationReq := (3.14159265359 / fWaveFreq_w) - (3.14159265359 / fNaturalFreq_wn);
            IF fLatchingDurationReq < 0.0 THEN fLatchingDurationReq := 0.0; END_IF;
        ELSE
            fLatchingDurationReq := 0.0;
        END_IF;

        // Apply latching
        IF bVelocityZeroCross AND NOT bHydraulicLatchCmd AND (fLatchingDurationReq > 0.01) THEN
            bHydraulicLatchCmd := TRUE;
            fLatchingTimer := 0.0;
        END_IF;

        // Release latching
        IF bHydraulicLatchCmd THEN
            fLatchingTimer := fLatchingTimer + tCycleTime;
            IF fLatchingTimer >= fLatchingDurationReq THEN
                bHydraulicLatchCmd := FALSE;
            END_IF;
        END_IF;

        // ---------------------------------------------------------------------
        // 2. DIRECT-DRIVE LINEAR GENERATOR PTO CONTROL
        // ---------------------------------------------------------------------
        // Optimal viscous damping for power extraction 
        // B_opt = SQRT( (B_rad)^2 + (w(m+ma) - K/w)^2 )
        // Simplified proportional damping for control demo
        fPTODampingCmd := fAddedMass_ma * fWaveFreq_w * 0.5;

        // Instantaneous power calculation P = F * v
        fPowerGenerated := ABS(fPTO_Force_Feedback * fHeaveVelocity) / 1000.0; // kW

        // ---------------------------------------------------------------------
        // 3. REVERSE OSMOSIS (RO) PRESSURE REGULATION (PI CONTROL)
        // ---------------------------------------------------------------------
        fRO_Error := fTargetROPressure - fRO_FeedPressure;

        // Anti-windup integration (freeze during latching)
        IF NOT bHydraulicLatchCmd THEN 
            fRO_Integral := fRO_Integral + (fRO_Error * tCycleTime);
        END_IF;

        // Clamp integral
        IF fRO_Integral > 100.0 THEN fRO_Integral := 100.0; END_IF;
        IF fRO_Integral < -100.0 THEN fRO_Integral := -100.0; END_IF;

        fRO_BypassValveCmd := (fRO_Error * fRO_Kp) + (fRO_Integral * fRO_Ki);

        // Output clamping (0% = Full flow to RO, 100% = Full bypass)
        fRO_BypassValveCmd := 50.0 - fRO_BypassValveCmd; 
        IF fRO_BypassValveCmd > 100.0 THEN fRO_BypassValveCmd := 100.0; END_IF;
        IF fRO_BypassValveCmd < 0.0 THEN fRO_BypassValveCmd := 0.0; END_IF;

        // Stop condition
        IF NOT bEnable THEN
            eState := STATE_IDLE;
        END_IF;

    ELSE
        eState := STATE_IDLE;

END_CASE;

// Store previous values
fPrevVelocity := fHeaveVelocity;

END_FUNCTION_BLOCK
```

