FUNCTION_BLOCK "RO_Control_Adversarial"
TITLE = 'RO Control with HIL and Drift Detection'
VERSION : 1.0

VAR_INPUT
    Feed_Pressure : REAL;
    Feed_Flow_Rate : REAL;
    Conductivity_Sensor1 : REAL;
    Conductivity_Sensor2 : REAL;
    High_Pressure_Setpoint : REAL;
    Conductivity_Limit : REAL;
    Pump1_Fault : BOOL;
    Pump2_Fault : BOOL;
    Simulated_Feed_Pressure : REAL; // For HIL
    Simulated_Conductivity : REAL;  // For HIL
END_VAR

VAR_IN_OUT
    SCADA_Data : "UDT_SCADA_Advanced"; 
END_VAR

VAR_OUTPUT
    HP_Pump1_Run : BOOL;
    HP_Pump2_Run : BOOL;
    HP_Pump_Speed : REAL;
    Inlet_Valve : BOOL;
    Flush_Valve : BOOL;
    System_Fault : BOOL;
    Sensor_Drift_Alarm : BOOL;
END_VAR

VAR
    State : INT; // 0=Off, 5=SelfTest, 1=Startup, 2=Running, 3=Flushing, 4=Fault
    Self_Test_Timer : TON;
    Flush_Timer : TON;
    PID_Inst : "PID_Compact";
    Active_Pump : INT := 1;
    Active_Feed_Pressure : REAL;
    Active_Conductivity : REAL;
    Conductivity_Diff : REAL;
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;
END_VAR

BEGIN
    // HIL Digital Twin Synchronization
    IF SCADA_Data.HIL_Mode_Active THEN
        Active_Feed_Pressure := Simulated_Feed_Pressure;
        Active_Conductivity := Simulated_Conductivity;
    ELSE
        Active_Feed_Pressure := Feed_Pressure;
        // Sensor Drift Detection (Statistical deviation between dual sensors)
        Conductivity_Diff := ABS(Conductivity_Sensor1 - Conductivity_Sensor2);
        IF Conductivity_Diff > 5.0 THEN // Drift Threshold
            Sensor_Drift_Alarm := TRUE;
            Active_Conductivity := MAX(Conductivity_Sensor1, Conductivity_Sensor2); // Safe fallback
        ELSE
            Sensor_Drift_Alarm := FALSE;
            Active_Conductivity := (Conductivity_Sensor1 + Conductivity_Sensor2) / 2.0;
        END_IF;
    END_IF;

    // CyberSecurity & Controls
    IF SCADA_Data.Active_User_Role < 2 THEN
        Start_Cmd := FALSE; // Block unprivileged start
    ELSE
        Start_Cmd := SCADA_Data.Control_Word.%X0;
    END_IF;
    Stop_Cmd := SCADA_Data.Control_Word.%X1;

    // Failover Logic
    IF Active_Pump = 1 AND Pump1_Fault THEN Active_Pump := 2;
    ELSIF Active_Pump = 2 AND Pump2_Fault THEN Active_Pump := 1; END_IF;

    // Fault Management
    IF Active_Feed_Pressure < 1.5 THEN
        System_Fault := TRUE; SCADA_Data.Active_Fault_Code := 1;
    ELSIF Active_Conductivity > Conductivity_Limit THEN
        System_Fault := TRUE; SCADA_Data.Active_Fault_Code := 2;
    ELSIF Pump1_Fault AND Pump2_Fault THEN
        System_Fault := TRUE; SCADA_Data.Active_Fault_Code := 3;
    END_IF;

    // State Machine
    IF System_Fault THEN
        State := 4;
    ELSIF Stop_Cmd THEN
        IF State = 2 THEN State := 3; ELSE State := 0; END_IF;
    ELSIF Start_Cmd AND NOT System_Fault AND State = 0 THEN
        State := 5; // Go to Self-Test first
    END_IF;

    CASE State OF
        0: // Off
            HP_Pump1_Run := FALSE; HP_Pump2_Run := FALSE; Inlet_Valve := FALSE; Flush_Valve := FALSE;
            SCADA_Data.Self_Test_Passed := FALSE;
        5: // Self-Test Routine
            Inlet_Valve := TRUE; // Open inlet to check pressure rise
            Self_Test_Timer(IN:=TRUE, PT:=T#5S);
            IF Self_Test_Timer.Q THEN
                IF Active_Feed_Pressure > 1.0 AND NOT Pump1_Fault THEN
                    SCADA_Data.Self_Test_Passed := TRUE;
                    State := 1; // Proceed to startup
                ELSE
                    System_Fault := TRUE;
                    SCADA_Data.Active_Fault_Code := 99; // Self-Test Failed
                END_IF;
                Self_Test_Timer(IN:=FALSE, PT:=T#0S);
            END_IF;
        1: // Startup
            State := 2;
        2: // Running
            IF Active_Pump = 1 THEN HP_Pump1_Run := TRUE; HP_Pump2_Run := FALSE; ELSE HP_Pump1_Run := FALSE; HP_Pump2_Run := TRUE; END_IF;
            PID_Inst(Setpoint := High_Pressure_Setpoint, Feedback := Active_Feed_Pressure, Output => HP_Pump_Speed);
        3: // Flushing
            Flush_Valve := TRUE; HP_Pump_Speed := 50.0;
            Flush_Timer(IN:=TRUE, PT:=T#30S);
            IF Flush_Timer.Q THEN State := 0; END_IF;
        4: // Fault
            HP_Pump1_Run := FALSE; HP_Pump2_Run := FALSE; Inlet_Valve := FALSE; Flush_Valve := FALSE;
    END_CASE;

    SCADA_Data.Current_State := State;
END_FUNCTION_BLOCK
