FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable                 : BOOL; // Enable the fleet management system
    bEmergencyStop          : BOOL; // Global emergency stop
    nActiveOrders           : INT;  // Number of active orders in the queue
    arrToteDestinations     : ARRAY[1..MAX_ORDERS] OF ST_Position3D; // Target destinations for active orders
    arrShuttleCurrentPos    : ARRAY[1..MAX_SHUTTLES] OF ST_Position3D; // Current positions of all active shuttles
    arrShuttleStatus        : ARRAY[1..MAX_SHUTTLES] OF INT; // 0=Idle, 1=Moving, 2=Retrieving, 3=Fault, 4=LowBattery
    arrGridSensors          : ARRAY[1..GRID_X, 1..GRID_Y, 1..GRID_Z] OF BOOL; // True if grid cell is occupied
END_VAR
VAR_OUTPUT
    arrShuttleCommands      : ARRAY[1..MAX_SHUTTLES] OF ST_ShuttleCmd; // Velocity and direction commands
    bSystemReady            : BOOL; // True if system is initialized and ready
    bCollisionWarning       : BOOL; // True if collision avoidance was triggered
    nThroughputTotesPerHour : REAL; // Calculated throughput
    arrShuttleErrors        : ARRAY[1..MAX_SHUTTLES] OF INT; // Error codes for diagnostics
END_VAR
VAR
    i, j, k                 : INT;
    distX, distY, distZ     : REAL;
    minDist                 : REAL;
    bCollisionRisk          : BOOL;
    nState                  : INT := 0; // State machine variable
    arrShuttlePath          : ARRAY[1..MAX_SHUTTLES, 1..MAX_PATH_NODES] OF ST_Position3D;
    tHeartbeat              : TON;
    nProcessedOrders        : INT := 0;
    rTotalDistance          : REAL := 0.0;
END_VAR
VAR CONSTANT
    MAX_SHUTTLES            : INT := 50;
    MAX_ORDERS              : INT := 100;
    MAX_PATH_NODES          : INT := 20;
    GRID_X                  : INT := 100;
    GRID_Y                  : INT := 50;
    GRID_Z                  : INT := 20;
    SAFE_DISTANCE           : REAL := 2.5; // Minimum safe distance between shuttles
END_VAR

// -----------------------------------------------------------------------------
// State Machine: 0=Init, 1=Monitor, 2=Assign, 3=Move, 4=Fault
// -----------------------------------------------------------------------------

IF bEmergencyStop THEN
    nState := 4;
    bSystemReady := FALSE;
    FOR i := 1 TO MAX_SHUTTLES DO
        arrShuttleCommands[i].bStopCommand := TRUE;
        arrShuttleCommands[i].rSpeedTarget := 0.0;
    END_FOR;
    RETURN;
END_IF

CASE nState OF
    0: // Initialization
        IF bEnable THEN
            bSystemReady := TRUE;
            nState := 1;
            bCollisionWarning := FALSE;
        END_IF

    1: // Monitor & Collision Avoidance
        bCollisionRisk := FALSE;
        FOR i := 1 TO (MAX_SHUTTLES - 1) DO
            FOR j := (i + 1) TO MAX_SHUTTLES DO
                IF arrShuttleStatus[i] <> 0 AND arrShuttleStatus[j] <> 0 THEN
                    distX := ABS(arrShuttleCurrentPos[i].X - arrShuttleCurrentPos[j].X);
                    distY := ABS(arrShuttleCurrentPos[i].Y - arrShuttleCurrentPos[j].Y);
                    distZ := ABS(arrShuttleCurrentPos[i].Z - arrShuttleCurrentPos[j].Z);

                    // Simple Manhattan distance for grid risk estimation
                    minDist := distX + distY + distZ;

                    IF minDist < SAFE_DISTANCE THEN
                        bCollisionRisk := TRUE;
                        // Resolve collision by prioritizing lower index
                        arrShuttleCommands[j].bStopCommand := TRUE;
                        arrShuttleCommands[j].rSpeedTarget := 0.0;
                        arrShuttleErrors[j] := 1001; // Collision avoidance halt
                    END_IF
                END_IF
            END_FOR
        END_FOR

        bCollisionWarning := bCollisionRisk;

        IF nActiveOrders > 0 THEN
            nState := 2;
        END_IF

    2: // Assign Tasks
        FOR i := 1 TO MAX_ORDERS DO
            // Simple assignment logic: Find first idle shuttle
            FOR j := 1 TO MAX_SHUTTLES DO
                IF arrShuttleStatus[j] = 0 THEN // Idle
                    // Assign order destination to shuttle
                    arrShuttleCommands[j].stTargetPos := arrToteDestinations[i];
                    arrShuttleCommands[j].bStartCommand := TRUE;
                    arrShuttleCommands[j].rSpeedTarget := 2.0; // Nominal speed
                    EXIT; // Proceed to next order
                END_IF
            END_FOR
        END_FOR
        nState := 1; // Return to monitoring

    4: // Fault State
        IF NOT bEmergencyStop THEN
            // Reset logic
            bSystemReady := FALSE;
            nState := 0;
        END_IF
END_CASE

// Update throughput calculation
tHeartbeat(IN := NOT tHeartbeat.Q, PT := T#1S);
IF tHeartbeat.Q THEN
    // Placeholder throughput calculation based on processed orders
    nThroughputTotesPerHour := float(nProcessedOrders) * 3600.0;
    nProcessedOrders := 0; // Reset counter for sliding window logic
END_IF

END_FUNCTION_BLOCK\n```
