FUNCTION_BLOCK "Lyophilizer_Advanced"
VERSION : 0.1
VAR_INPUT
    Start_Cycle : Bool;
    Stop_Cycle : Bool;
    Chamber_Pressure : Real;
    Shelf_Temp : Real;
    Condenser_Temp : Real;
    Chamber_Temp : Real;
    Target_Freeze_Temp : Real;
    Target_Primary_Dry_Temp : Real;
    Target_Vacuum : Real;
    Start_Defrost : Bool;
    Start_SIP : Bool;
END_VAR
VAR_OUTPUT
    Vacuum_Pump_Run : Bool;
    Compressor_Run : Bool;
    Heater_Run : Bool;
    Defrost_Valve : Bool;
    Steam_Valve : Bool;
    Status : Int;
END_VAR
VAR
    State : Int;
    SIP_Timer : TON;
END_VAR
BEGIN
    IF Stop_Cycle THEN
        State := 0;
    END_IF;

    CASE State OF
        0: // Idle
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
            Defrost_Valve := FALSE;
            Steam_Valve := FALSE;
            IF Start_Cycle THEN State := 1; END_IF;
            IF Start_Defrost THEN State := 5; END_IF;
            IF Start_SIP THEN State := 6; END_IF;
        1: // Freezing
            Compressor_Run := TRUE;
            IF Shelf_Temp <= Target_Freeze_Temp THEN State := 2; END_IF;
        2: // Drying
            Compressor_Run := TRUE;
            Vacuum_Pump_Run := TRUE;
            IF Chamber_Pressure <= Target_Vacuum THEN
                Heater_Run := (Shelf_Temp < Target_Primary_Dry_Temp);
                IF Shelf_Temp >= Target_Primary_Dry_Temp THEN State := 4; END_IF;
            END_IF;
        4: // Complete
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
        5: // Defrost
            Compressor_Run := FALSE;
            Vacuum_Pump_Run := FALSE;
            Heater_Run := TRUE;
            Defrost_Valve := TRUE;
            IF Condenser_Temp > 20.0 THEN
                Defrost_Valve := FALSE;
                Heater_Run := FALSE;
                State := 0;
            END_IF;
        6: // SIP (Sterilization)
            Steam_Valve := TRUE;
            SIP_Timer(IN:= (Chamber_Temp > 121.1), PT:= t#30m);
            IF SIP_Timer.Q THEN
                Steam_Valve := FALSE;
                State := 0;
            END_IF;
    END_CASE;
    Status := State;
END_FUNCTION_BLOCK
