FUNCTION_BLOCK FB_GlassFiberDrawCtrl
TITLE = 'Continuous Glass Fiber Drawing Control System - Master Function Block'
VERSION : '2.1'
AUTHOR : 'Lumina AI Cloud Swarm'

(* 
   This function block controls the continuous glass fiber drawing process, managing the critical
   loops for bushing precious metal resistive heating, the glass strand sizing applicator roll speed, 
   and the multi-collet winder tension with dynamic diameter compensation.
*)

VAR_INPUT
    rBushingTemp_PV       : REAL;  (* Process value of bushing temperature (deg C) *)
    rBushingTemp_SP       : REAL;  (* Setpoint of bushing temperature (deg C) *)
    rWinderSpeed_PV       : REAL;  (* Process value of winder collet speed (m/min) *)
    rWinderSpeed_SP       : REAL;  (* Setpoint for winder drawing speed (m/min) *)
    rStrandTension_PV     : REAL;  (* Measured tension of glass strand (N) *)
    rStrandTension_SP     : REAL;  (* Target tension (N) *)
    rApplicatorRoll_PV    : REAL;  (* Applicator roll speed feedback (RPM) *)
    bSystemRun            : BOOL;  (* Master run command from SCADA/HMI *)
    bEstopActive          : BOOL;  (* Emergency stop active loop feedback *)
    bBreakoutDetected     : BOOL;  (* Optical sensor for strand breakout detection *)
END_VAR

VAR_OUTPUT
    rBushingHeating_Cmd   : REAL;  (* Precious metal resistive heating power command (0-100%) *)
    rWinderMotor_Cmd      : REAL;  (* Winder motor speed command (0-100%) *)
    rApplicatorRoll_Cmd   : REAL;  (* Sizing applicator roll speed command (0-100%) *)
    bAlarm_TempHigh       : BOOL;  (* Bushing temperature critically high alarm *)
    bAlarm_TempLow        : BOOL;  (* Bushing temperature critically low alarm *)
    bAlarm_TensionLoss    : BOOL;  (* Strand tension loss - probable break *)
    bAlarm_TensionHigh    : BOOL;  (* Strand tension high - risk of breakage *)
    bSystemReady          : BOOL;  (* All PID loops stabilized and ready for drawing *)
END_VAR

VAR
    (* Bushing Temperature PID Variables *)
    rTempError            : REAL;
    rTempIntegral         : REAL := 0.0;
    rTempDerivative       : REAL := 0.0;
    rTempLastPV           : REAL := 0.0;
    rTempKp               : REAL := 3.25;
    rTempKi               : REAL := 0.015;
    rTempKd               : REAL := 0.45;

    (* Strand Tension PI Variables *)
    rTensionError         : REAL;
    rTensionIntegral      : REAL := 0.0;
    rTensionKp            : REAL := 1.85;
    rTensionKi            : REAL := 0.055;

    (* Process Constraints & Configuration *)
    rApplicatorRatio      : REAL := 0.075; (* Applicator roll to winder line speed gear ratio *)
    rMaxHeatingPower      : REAL := 100.0;
    rMinHeatingPower      : REAL := 0.0;
    rPackageDiameter      : REAL := 150.0; (* Base core package diameter in mm *)
    rDiameterBuildRate    : REAL := 0.012; (* Extrapolated mm per cycle based on line speed *)

    (* State Tracking *)
    bInitializationDone   : BOOL := FALSE;
END_VAR

(* First Pass Initialization *)
IF NOT bInitializationDone THEN
    rTempLastPV := rBushingTemp_PV;
    bInitializationDone := TRUE;
END_IF;

(* Safety Interlocks & Emergency Stop Handling *)
IF bEstopActive OR NOT bSystemRun OR bBreakoutDetected THEN
    rBushingHeating_Cmd := 0.0;
    rWinderMotor_Cmd := 0.0;
    rApplicatorRoll_Cmd := 0.0;

    (* Reset integral accumulations to prevent windup during stop *)
    rTempIntegral := 0.0;
    rTensionIntegral := 0.0;

    bSystemReady := FALSE;
    RETURN;
END_IF;

bSystemReady := TRUE;

(* ====================================================================
   1. Bushing Precious Metal Resistive Heating Control (PID)
   ==================================================================== *)
rTempError := rBushingTemp_SP - rBushingTemp_PV;
rTempIntegral := rTempIntegral + (rTempError * rTempKi);

(* Anti-windup protection for Temperature Integral *)
IF rTempIntegral > rMaxHeatingPower THEN 
    rTempIntegral := rMaxHeatingPower; 
ELSIF rTempIntegral < rMinHeatingPower THEN 
    rTempIntegral := rMinHeatingPower; 
END_IF;

rTempDerivative := (rBushingTemp_PV - rTempLastPV) * rTempKd;
rTempLastPV := rBushingTemp_PV;

rBushingHeating_Cmd := (rTempError * rTempKp) + rTempIntegral - rTempDerivative;

(* Command Saturation Limits *)
IF rBushingHeating_Cmd > rMaxHeatingPower THEN 
    rBushingHeating_Cmd := rMaxHeatingPower; 
ELSIF rBushingHeating_Cmd < rMinHeatingPower THEN 
    rBushingHeating_Cmd := rMinHeatingPower; 
END_IF;

(* Alarm Generation for Bushing Over/Under Temp *)
bAlarm_TempHigh := (rBushingTemp_PV > (rBushingTemp_SP + 15.0));
bAlarm_TempLow  := (rBushingTemp_PV < (rBushingTemp_SP - 15.0));

(* ====================================================================
   2. Glass Strand Sizing Applicator Roll Speed Control
   ==================================================================== *)
(* The applicator roll speed must remain strictly synchronized to the 
   measured winder line speed to ensure consistent sizing chemical application. *)
rApplicatorRoll_Cmd := rWinderSpeed_PV * rApplicatorRatio;
IF rApplicatorRoll_Cmd > 100.0 THEN 
    rApplicatorRoll_Cmd := 100.0; 
END_IF;

(* ====================================================================
   3. Multi-Collet Winder Tension Control with Diameter Compensation
   ==================================================================== *)
rTensionError := rStrandTension_SP - rStrandTension_PV;
rTensionIntegral := rTensionIntegral + (rTensionError * rTensionKi);

(* Continuous estimation of the winder package diameter buildup 
   This prevents tension drops as the package grows and requires lower RPM *)
rPackageDiameter := rPackageDiameter + rDiameterBuildRate;
IF rPackageDiameter > 800.0 THEN 
    rPackageDiameter := 800.0; (* Physical limit of multi-collet carriage *)
END_IF;

(* Advanced Feed-forward line speed conversion plus PID trim *)
rWinderMotor_Cmd := ((rWinderSpeed_SP * 1000.0) / (3.14159 * rPackageDiameter)) + (rTensionError * rTensionKp) + rTensionIntegral;

(* Command Saturation Limits *)
IF rWinderMotor_Cmd > 100.0 THEN 
    rWinderMotor_Cmd := 100.0; 
ELSIF rWinderMotor_Cmd < 0.0 THEN 
    rWinderMotor_Cmd := 0.0; 
END_IF;

(* Quality and Process Alarms for Tension Control *)
bAlarm_TensionHigh := (rStrandTension_PV > (rStrandTension_SP * 1.45));
bAlarm_TensionLoss := (rStrandTension_PV < 0.25); (* Threshold for strand loss detection *)

END_FUNCTION_BLOCK
