FUNCTION_BLOCK FB_WebOffsetPressMaster
TITLE = 'High-Speed Web Offset Printing Press - Master Control'
//=============================================================================
// DESCRIPTION:
// Advanced control block for high-speed web offset printing.
// Handles multi-zone web tension via dancer roll PID cascades, 
// zero-speed automated flying splice kinematics, and real-time 
// CMYK optical registration correction.
//=============================================================================

VAR_INPUT
    // Machine State
    xEnable                  : BOOL; // Enable block processing
    xStartPress              : BOOL; // Start press sequence
    xEmergencyStop           : BOOL; // Emergency stop circuit
    rLineSpeedSetpoint       : REAL; // Master line speed setpoint (m/min)
    rActualLineSpeed         : REAL; // Actual line speed feedback (m/min)

    // Web Tension & Splicing
    rDancerPositionRaw       : REAL; // Raw analog input from dancer LVDT (0-100%)
    xSpliceRequest           : BOOL; // Request to perform flying splice
    rNewRollDiameter         : REAL; // Diameter of new paper roll (mm)
    rExpiringRollDiameter    : REAL; // Diameter of expiring roll (mm)
    xNewRollPrepared         : BOOL; // Splice tape applied and roll ready

    // Optical Registration (CMYK)
    rCyanMarkPos             : REAL; // Cyan registration mark position (mm)
    rMagentaMarkPos          : REAL; // Magenta registration mark position (mm)
    rYellowMarkPos           : REAL; // Yellow registration mark position (mm)
    rBlackMarkPos            : REAL; // Black (Key) registration mark position (mm)
    rTargetMarkPos           : REAL; // Ideal registration position reference (mm)
END_VAR

VAR_OUTPUT
    // Motor Speed References
    rUnwindSpeedRef          : REAL; // Speed reference to unwind drive (m/min)
    rInfeedNipSpeedRef       : REAL; // Speed reference to infeed nip (m/min)
    rMainDriveSpeedRef       : REAL; // Speed reference to main print cylinders (m/min)

    // Splice Control Actuators
    xEngageSpliceArm         : BOOL; // Fire pneumatic cylinder for splice arm
    xFireKnife               : BOOL; // Fire cut-off knife
    xAccelerateNewRoll       : BOOL; // Command new roll to match line speed
    rNewRollSpeedRef         : REAL; // Speed reference for new roll prep (m/min)

    // Registration Compensators
    rCyanCompensatorPos      : REAL; // Cyan linear compensator command (mm)
    rMagentaCompensatorPos   : REAL; // Magenta linear compensator command (mm)
    rYellowCompensatorPos    : REAL; // Yellow linear compensator command (mm)

    // Status
    xPressRunning            : BOOL;
    xSpliceInProgress        : BOOL;
    xRegistrationError       : BOOL;
    xTensionError            : BOOL;
    iState                   : INT;
END_VAR

VAR
    // PID Controller for Dancer Tension
    PID_Tension              : FB_PID; 
    rTensionSetpoint         : REAL := 50.0; // Target dancer position (50% midpoint)
    rTensionKp               : REAL := 1.25;
    rTensionKi               : REAL := 0.45;
    rTensionKd               : REAL := 0.05;
    rTensionError            : REAL;
    rTensionOutput           : REAL;

    // Kinematic Splice Variables
    rMatchSpeedTolerance     : REAL := 0.5; // Acceptable delta V for splice (m/min)
    rNewRollSurfaceSpeed     : REAL;
    tSpliceTimer             : TON;
    iSpliceState             : INT := 0;

    // Registration Variables
    rCyanError               : REAL;
    rMagentaError            : REAL;
    rYellowError             : REAL;
    rMaxRegError             : REAL := 2.5; // Maximum allowed registration error (mm)

    // Internal Flags
    xTensionOk               : BOOL;
END_VAR

//=============================================================================
// 1. EMERGENCY STOP & SAFETY INTERLOCKS
//=============================================================================
IF xEmergencyStop THEN
    rUnwindSpeedRef := 0.0;
    rInfeedNipSpeedRef := 0.0;
    rMainDriveSpeedRef := 0.0;
    xEngageSpliceArm := FALSE;
    xFireKnife := FALSE;
    xPressRunning := FALSE;
    iState := 0;
    RETURN;
END_IF;

IF NOT xEnable THEN
    rUnwindSpeedRef := 0.0;
    rInfeedNipSpeedRef := 0.0;
    rMainDriveSpeedRef := 0.0;
    xPressRunning := FALSE;
    RETURN;
END_IF;

//=============================================================================
// 2. TENSION DANCER ROLL PID CASCADE
//=============================================================================
// Calculate tension error based on dancer position
rTensionError := rTensionSetpoint - rDancerPositionRaw;

IF ABS(rTensionError) > 40.0 THEN
    xTensionError := TRUE;
ELSE
    xTensionError := FALSE;
END_IF;

// Execute PID Controller for Tension
PID_Tension(
    xEnable := xPressRunning,
    rSetpoint := rTensionSetpoint,
    rProcessValue := rDancerPositionRaw,
    rKp := rTensionKp,
    rKi := rTensionKi,
    rKd := rTensionKd,
    rOutput => rTensionOutput
);

// Cascade: Main speed + Tension trim for Infeed Nip
rMainDriveSpeedRef := rLineSpeedSetpoint;
rInfeedNipSpeedRef := rLineSpeedSetpoint + rTensionOutput;

// Unwind matches line speed scaled by roll diameter ratio + trim
IF rExpiringRollDiameter > 0.0 THEN
    rUnwindSpeedRef := (rLineSpeedSetpoint / rExpiringRollDiameter) * 1000.0 + (rTensionOutput * 0.5);
END_IF;

//=============================================================================
// 3. AUTOMATED PAPER SPLICING KINEMATICS (ZERO-SPEED FLYING SPLICE)
//=============================================================================
IF xSpliceRequest AND NOT xSpliceInProgress AND xNewRollPrepared THEN
    xSpliceInProgress := TRUE;
    iSpliceState := 1;
END_IF;

IF xSpliceInProgress THEN
    CASE iSpliceState OF
        1: // Accelerate new roll to match surface speed of the expiring web
            xAccelerateNewRoll := TRUE;
            rNewRollSpeedRef := rActualLineSpeed;

            // Calculate surface speed of new roll
            rNewRollSurfaceSpeed := rNewRollSpeedRef;

            IF ABS(rNewRollSurfaceSpeed - rActualLineSpeed) <= rMatchSpeedTolerance THEN
                iSpliceState := 2;
            END_IF;

        2: // Engage splice arm to press web against new roll with tape
            xEngageSpliceArm := TRUE;
            tSpliceTimer(IN:= TRUE, PT:= T#250ms);

            IF tSpliceTimer.Q THEN
                iSpliceState := 3;
                tSpliceTimer(IN:= FALSE);
            END_IF;

        3: // Fire knife to cut expiring web
            xFireKnife := TRUE;
            tSpliceTimer(IN:= TRUE, PT:= T#100ms);

            IF tSpliceTimer.Q THEN
                iSpliceState := 4;
            END_IF;

        4: // Splice complete, reset sequence
            xEngageSpliceArm := FALSE;
            xFireKnife := FALSE;
            xAccelerateNewRoll := FALSE;
            xSpliceInProgress := FALSE;
            xSpliceRequest := FALSE;
            iSpliceState := 0;
    END_CASE;
ELSE
    xEngageSpliceArm := FALSE;
    xFireKnife := FALSE;
    xAccelerateNewRoll := FALSE;
    tSpliceTimer(IN:= FALSE);
END_IF;

//=============================================================================
// 4. CMYK OPTICAL REGISTRATION SCANNING & CORRECTION
//=============================================================================
// Assume Black is the key color (reference). Target is relative to it.
// Calculate positional errors for CMY relative to Target
rCyanError := rTargetMarkPos - rCyanMarkPos;
rMagentaError := rTargetMarkPos - rMagentaMarkPos;
rYellowError := rTargetMarkPos - rYellowMarkPos;

// Check for gross registration loss
IF ABS(rCyanError) > rMaxRegError OR ABS(rMagentaError) > rMaxRegError OR ABS(rYellowError) > rMaxRegError THEN
    xRegistrationError := TRUE;
ELSE
    xRegistrationError := FALSE;
END_IF;

// Proportional correction for linear compensators (motorized web path rollers)
IF xPressRunning AND NOT xRegistrationError THEN
    rCyanCompensatorPos := rCyanCompensatorPos + (rCyanError * 0.1);
    rMagentaCompensatorPos := rMagentaCompensatorPos + (rMagentaError * 0.1);
    rYellowCompensatorPos := rYellowCompensatorPos + (rYellowError * 0.1);
END_IF;

//=============================================================================
// MACHINE STATE
//=============================================================================
IF xStartPress AND NOT xEmergencyStop AND NOT xTensionError THEN
    xPressRunning := TRUE;
    iState := 10;
END_IF;

END_FUNCTION_BLOCK
