FUNCTION_BLOCK FB_BlisterPack_MasterControl
TITLE = 'High-Speed Pharmaceutical Blister Packaging Master Control'
AUTHOR : 'Lumina AI Cloud Swarm'
VERSION : '1.0'

VAR_INPUT
    xEnable : BOOL; // System enable
    xEmergencyStop : BOOL; // E-Stop condition (NC)
    rWebSpeed_SP_mm_s : REAL; // Target web speed in mm/s
    rPreHeatTemp_SP_C : REAL; // Setpoint for thermoforming pre-heater
    rSealPressure_SP_bar : REAL; // Setpoint for rotary seal pressure
    xVisionInspectionSync : BOOL; // Sync pulse from high-speed camera
    xCavityFilled : ARRAY[0..15] OF BOOL; // Vision results for current index
END_VAR

VAR_OUTPUT
    xSystemReady : BOOL;
    rWebSpeed_PV_mm_s : REAL; // Current web speed
    rPreHeatTemp_PV_C : REAL; // Current pre-heat temperature
    rSealPressure_PV_bar : REAL; // Current sealing pressure
    xRejectStation_Trigger : BOOL; // Trigger for reject mechanism
    xDriveEnable : BOOL; // Servo drive enable
    wGoodBlistersCount : DWORD; // Total accepted
    wRejectBlistersCount : DWORD; // Total rejected
END_VAR

VAR
    // State Machine
    iState : INT := 0;

    // PID Control variables for Heater
    rHeaterError : REAL;
    rHeaterIntegral : REAL;
    rHeaterDerivative : REAL;
    rHeaterLastError : REAL;
    rHeaterKp : REAL := 2.5;
    rHeaterKi : REAL := 0.5;
    rHeaterKd : REAL := 0.1;
    rHeaterOutput : REAL;

    // Shift Register for Reject Tracking (64 indices distance between camera and reject)
    xRejectShiftReg : ARRAY[0..63] OF BOOL;
    iShiftIndex : INT := 0;
    i : INT;

    // General internal
    xLocalFault : BOOL;
    xHeaterAtTemp : BOOL;
    xPressureOK : BOOL;
END_VAR

// Logic Execution
IF NOT xEmergencyStop OR xLocalFault THEN
    iState := 99; // Fault state
    xDriveEnable := FALSE;
    rHeaterOutput := 0.0;
    xSystemReady := FALSE;
END_IF;

CASE iState OF
    0: // Idle
        xSystemReady := FALSE;
        IF xEnable AND NOT xLocalFault THEN
            iState := 10;
        END_IF;

    10: // Pre-Heating
        // Implement basic PI control for pre-heat temperature
        rHeaterError := rPreHeatTemp_SP_C - rPreHeatTemp_PV_C;
        rHeaterIntegral := rHeaterIntegral + (rHeaterError * 0.01); // Assuming 10ms task
        rHeaterDerivative := (rHeaterError - rHeaterLastError) / 0.01;
        rHeaterLastError := rHeaterError;

        rHeaterOutput := (rHeaterKp * rHeaterError) + (rHeaterKi * rHeaterIntegral) + (rHeaterKd * rHeaterDerivative);

        // Clamp output
        IF rHeaterOutput > 100.0 THEN
            rHeaterOutput := 100.0;
        ELSIF rHeaterOutput < 0.0 THEN
            rHeaterOutput := 0.0;
        END_IF;

        IF ABS(rHeaterError) < 2.0 THEN
            xHeaterAtTemp := TRUE;
        ELSE
            xHeaterAtTemp := FALSE;
        END_IF;

        IF xHeaterAtTemp THEN
            iState := 20;
        END_IF;

    20: // Operational
        xSystemReady := TRUE;
        xDriveEnable := TRUE;

        // Shift register logic for Vision Inspection
        IF xVisionInspectionSync THEN
            // Check if all 16 cavities in the current blister index are filled
            xRejectShiftReg[0] := FALSE; // Default to Good
            FOR i := 0 TO 15 DO
                IF NOT xCavityFilled[i] THEN
                    xRejectShiftReg[0] := TRUE; // Mark for reject if any cavity is missing
                    EXIT;
                END_IF;
            END_FOR;

            // Shift the register
            xRejectStation_Trigger := xRejectShiftReg[63];

            IF xRejectStation_Trigger THEN
                wRejectBlistersCount := wRejectBlistersCount + 1;
            ELSE
                wGoodBlistersCount := wGoodBlistersCount + 1;
            END_IF;

            FOR i := 63 DOWNTO 1 DO
                xRejectShiftReg[i] := xRejectShiftReg[i-1];
            END_FOR;

        END_IF;

        // Monitor Sealing Pressure
        IF rSealPressure_PV_bar < (rSealPressure_SP_bar * 0.9) THEN
            xLocalFault := TRUE; // Drop out if pressure fails
        END_IF;

    99: // Fault
        // Fault handling logic
        xSystemReady := FALSE;
        IF xEmergencyStop AND NOT xLocalFault AND NOT xEnable THEN
            iState := 0; // Reset
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
