FUNCTION_BLOCK "FrancisTurbine_GuideVane_Mut1"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Enable_Control : Bool;
      Target_Gate_Position : Real; 
      Actual_Gate_Position : Real; 
      Hydraulic_Pressure : Real; // bar
      Emergency_Stop : Bool;
   END_VAR

   VAR_OUTPUT 
      Servo_Control_Signal : Real; 
      Gate_Sync_Achieved : Bool;
      Hydraulic_Fault : Bool;
      ESD_Active : Bool;
   END_VAR

   VAR 
      Position_Error : Real;
      Kp : Real := 2.5;
      Deadband : Real := 0.5;
      Min_Pressure : Real := 120.0; // bar
   END_VAR

BEGIN
    // Hydraulic Accumulator Monitoring
    IF #Hydraulic_Pressure < #Min_Pressure THEN
        #Hydraulic_Fault := TRUE;
    ELSE
        #Hydraulic_Fault := FALSE;
    END_IF;

    // Emergency Shutdown Sequence (ESD)
    IF #Emergency_Stop OR #Hydraulic_Fault THEN
        #ESD_Active := TRUE;
        #Servo_Control_Signal := -100.0; // Fast close
        #Gate_Sync_Achieved := FALSE;
        RETURN;
    ELSE
        #ESD_Active := FALSE;
    END_IF;

    IF NOT #Enable_Control THEN
        #Servo_Control_Signal := 0.0;
        #Gate_Sync_Achieved := FALSE;
        RETURN;
    END_IF;

    #Position_Error := #Target_Gate_Position - #Actual_Gate_Position;

    IF ABS(#Position_Error) > #Deadband THEN
        #Servo_Control_Signal := #Position_Error * #Kp;
        #Gate_Sync_Achieved := FALSE;
    ELSE
        #Servo_Control_Signal := 0.0;
        #Gate_Sync_Achieved := TRUE;
    END_IF;

    IF #Servo_Control_Signal > 100.0 THEN
        #Servo_Control_Signal := 100.0;
    ELSIF #Servo_Control_Signal < -100.0 THEN
        #Servo_Control_Signal := -100.0;
