FUNCTION_BLOCK FB_SubseaHydrateExtractionCrawler
VAR_INPUT
    (* Essential Physical Inputs for Crawler and Extraction *)
    bEnable                 : BOOL;     (* System master enable interlock *)
    bEmergencyStop          : BOOL;     (* E-Stop Ok circuit from top-side vessel *)
    rAmbientPressure        : REAL;     (* Hydrostatic pressure in Bar, typically >100 Bar at depth *)
    rSlurryDensity          : REAL;     (* Hydrate slurry density measured by Coriolis meter (kg/m3) *)
    rSonarTerrainDist       : REAL;     (* Forward obstacle distance from Sonar array (meters) *)
    rHighPressureJetFlow    : REAL;     (* Depressurization water jet flow (L/min) *)
    rThrusterRPM            : REAL;     (* Actual RPM of main crawler thrusters *)
    rMethaneConc            : REAL;     (* Dissolved methane concentration at seabed (ppm) *)
END_VAR
VAR_OUTPUT
    (* Control Outputs for Actuators *)
    bSystemReady            : BOOL;     (* Ready to commence extraction sequence *)
    rWaterJetCmd            : REAL;     (* Flow command to high-pressure water jets (0-100%) *)
    rSlurryPumpSpeed        : REAL;     (* Subsea multi-phase pump speed command (RPM) *)
    rThrusterCmd            : REAL;     (* Drive command for traction/thrusters (-100 to 100%) *)
    bCollisionWarning       : BOOL;     (* Sonar detected obstacle in collision radius *)
    bFlowAssuranceFault     : BOOL;     (* Multi-phase flow blockage or density mismatch *)
    bEStopActive            : BOOL;     (* E-stop triggered or comms lost *)
END_VAR
VAR
    (* Internal State and Processing Variables *)
    iState                  : INT := 0; (* Master state machine index *)
    tExtractTimer           : TON;      (* Timer for extraction steps stabilization *)
    tFaultTimer             : TON;      (* Debounce timer for transient flow faults *)

    (* Filtered Sensor Data *)
    rFilteredDensity        : REAL := 0.0;
    rFilteredDistance       : REAL := 0.0;

    (* Internal Constants *)
    MIN_SLURRY_DENSITY      : REAL := 1050.0;
    MAX_SLURRY_DENSITY      : REAL := 1250.0;
    COLLISION_THRESHOLD     : REAL := 2.5; 
    HYDRATE_DISSOCIATION_P  : REAL := 50.0;
END_VAR

(* === MAIN LOGIC === *)

(* Emergency Stop Interlock *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bEStopActive := TRUE;
    rWaterJetCmd := 0.0;
    rSlurryPumpSpeed := 0.0;
    rThrusterCmd := 0.0;
    bCollisionWarning := FALSE;
    iState := 0;
    RETURN;
ELSE
    bEStopActive := FALSE;
END_IF;

(* Simple first-order low-pass filters for noisy subsea measurements *)
rFilteredDensity := (0.8 * rFilteredDensity) + (0.2 * rSlurryDensity);
rFilteredDistance := (0.9 * rFilteredDistance) + (0.1 * rSonarTerrainDist);

(* Sonar Collision Avoidance Override *)
IF rFilteredDistance < COLLISION_THRESHOLD AND rFilteredDistance > 0.0 THEN
    bCollisionWarning := TRUE;
    rThrusterCmd := 0.0; (* Halt forward motion immediately *)
ELSE
    bCollisionWarning := FALSE;
END_IF;

(* Flow Assurance Monitoring *)
IF (rFilteredDensity < MIN_SLURRY_DENSITY OR rFilteredDensity > MAX_SLURRY_DENSITY) AND iState >= 30 THEN
    tFaultTimer(IN := TRUE, PT := T#2S);
    IF tFaultTimer.Q THEN
        bFlowAssuranceFault := TRUE;
        iState := 99; (* Transition to fault state *)
    END_IF;
ELSE
    tFaultTimer(IN := FALSE);
    bFlowAssuranceFault := FALSE;
END_IF;

(* Master State Machine for Extraction Sequence *)
CASE iState OF
    0: (* IDLE & INIT *)
        bSystemReady := FALSE;
        rWaterJetCmd := 0.0;
        rSlurryPumpSpeed := 0.0;
        rThrusterCmd := 0.0;
        IF bEnable AND NOT bCollisionWarning AND NOT bFlowAssuranceFault THEN
            bSystemReady := TRUE;
            iState := 10;
        END_IF;

    10: (* APPROACH TERRAIN *)
        bSystemReady := TRUE;
        IF rFilteredDistance > (COLLISION_THRESHOLD + 2.0) THEN
            rThrusterCmd := 30.0; (* Crawl forward slowly *)
        ELSE
            rThrusterCmd := 0.0;
            iState := 20; (* Ready to engage jets *)
        END_IF;

    20: (* DEPRESSURIZATION JET STARTUP *)
        rWaterJetCmd := rWaterJetCmd + 1.0; (* Ramp up water jet *)
        IF rWaterJetCmd >= 75.0 THEN
            tExtractTimer(IN := TRUE, PT := T#10S);
            IF tExtractTimer.Q THEN
                tExtractTimer(IN := FALSE);
                iState := 30;
            END_IF;
        END_IF;

    30: (* MULTI-PHASE SLURRY PUMPING *)
        (* Maintain optimal slurry flow using density feedback PID loop approximation *)
        IF rFilteredDensity > 1150.0 THEN
            rSlurryPumpSpeed := rSlurryPumpSpeed + 10.0;
        ELSIF rFilteredDensity < 1100.0 THEN
            rSlurryPumpSpeed := rSlurryPumpSpeed - 5.0;
        END_IF;

        (* Cap pump speed for motor limits *)
        IF rSlurryPumpSpeed > 1800.0 THEN
            rSlurryPumpSpeed := 1800.0;
        ELSIF rSlurryPumpSpeed < 0.0 THEN
            rSlurryPumpSpeed := 0.0;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        rWaterJetCmd := 0.0;
        rSlurryPumpSpeed := 0.0;
        rThrusterCmd := 0.0;
        bSystemReady := FALSE;
        IF NOT bFlowAssuranceFault AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_TidalStreamTurbine
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable         : BOOL;     (* System enable signal *)
    bEmergencyStop  : BOOL;     (* Safety relay OK signal *)
    rProcessVar     : REAL;     (* Physical measurement e.g. temperature in deg C *)
    rTidalFlowVelocity : REAL; (* Tidal current velocity in m/s *)
    rNacelleHeading : REAL; (* Current yaw heading relative to magnetic north in degrees *)
    bSeawaterIngressSensor : BOOL; (* Acoustic seawater ingress monitoring OK signal *)
    rGridFrequency : REAL; (* Synchronous generator grid tie frequency in Hz *)
    rGridVoltage : REAL; (* Grid tie voltage in kV *)
    rRotorRPM : REAL; (* Turbine rotor speed in RPM *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady    : BOOL;     (* System ready status *)
    rControlOutput  : REAL;     (* Control signal to actuator *)
    bAlarm          : BOOL;     (* Fault alarm output *)
    rPitchAngleSetpoint : REAL; (* Dynamic blade pitch angle setpoint in degrees *)
    rYawTorqueDemand : REAL; (* Bi-directional yaw drive torque demand *)
    bGridTieBreakerClose : BOOL; (* Command to close grid-tie breaker *)
    iFaultCode : INT; (* Detailed fault diagnostic code *)
END_VAR
VAR
    (* Internal state variables *)
    iState          : INT := 0;
    tTimer          : TON;
    tGridSyncTimer : TON;
    tStartDelay : TON;
    rFilteredFlow : REAL := 0.0;
    rPitchIntegral : REAL := 0.0;
    rFlowAlpha : REAL := 0.05; (* Low pass filter alpha for flow *)
    bTargetReached : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop OR NOT bSeawaterIngressSensor THEN
    bSystemReady := FALSE;
    bGridTieBreakerClose := FALSE;
    bAlarm := TRUE;
    rPitchAngleSetpoint := 90.0; (* Feather blades *)
    rYawTorqueDemand := 0.0;
    iState := 999; (* Fault state *)
    iFaultCode := 16#F001; (* Emergency stop or leak *)
    RETURN;
END_IF;

(* Flow filter *)
rFilteredFlow := rFilteredFlow + rFlowAlpha * (rTidalFlowVelocity - rFilteredFlow);

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        iFaultCode := 0;
        bGridTieBreakerClose := FALSE;
        rPitchAngleSetpoint := 90.0; (* Feathered *)
        rYawTorqueDemand := 0.0;

        IF bEnable AND rFilteredFlow > 1.2 THEN (* Min cut-in speed *)
            iState := 10;
        END_IF;

    10: (* YAW ALIGNMENT *)
        (* Simplified yaw controller seeking 0 flow angle error, assuming heading target is 0 for tide *)
        IF rNacelleHeading > 5.0 THEN
            rYawTorqueDemand := -1500.0;
        ELSIF rNacelleHeading < -5.0 THEN
            rYawTorqueDemand := 1500.0;
        ELSE
            rYawTorqueDemand := 0.0;
            tStartDelay(IN := TRUE, PT := T#10S);
            IF tStartDelay.Q THEN
                tStartDelay(IN := FALSE);
                iState := 20;
            END_IF;
        END_IF;

    20: (* ROTOR ACCELERATION *)
        (* Gradually unfeather blades *)
        rPitchAngleSetpoint := rPitchAngleSetpoint - 0.5;
        IF rPitchAngleSetpoint < 15.0 THEN
            rPitchAngleSetpoint := 15.0;
        END_IF;

        (* Check RPM *)
        IF rRotorRPM > 18.0 THEN
            iState := 30;
        END_IF;

    30: (* GRID SYNC AND TIE *)
        (* Maintain speed while waiting for sync *)
        IF rRotorRPM > 20.0 THEN
            rPitchAngleSetpoint := rPitchAngleSetpoint + 0.1;
        ELSIF rRotorRPM < 19.5 THEN
            rPitchAngleSetpoint := rPitchAngleSetpoint - 0.1;
        END_IF;

        IF rGridFrequency > 49.8 AND rGridFrequency < 50.2 AND rGridVoltage > 31.0 AND rGridVoltage < 34.0 THEN
            tGridSyncTimer(IN := TRUE, PT := T#5S);
            IF tGridSyncTimer.Q THEN
                bGridTieBreakerClose := TRUE;
                tGridSyncTimer(IN := FALSE);
                iState := 40;
            END_IF;
        ELSE
            tGridSyncTimer(IN := FALSE);
        END_IF;

    40: (* RUNNING / POWER TRACKING *)
        (* Max Power Point Tracking (MPPT) logic placeholder *)
        IF rFilteredFlow > 3.5 THEN (* Rated speed *)
            rPitchAngleSetpoint := 5.0 + (rFilteredFlow - 3.5) * 10.0; (* Pitch to shed power *)
        ELSE
            rPitchAngleSetpoint := 5.0; (* Optimal pitch *)
        END_IF;
        rControlOutput := rFilteredFlow * 1.5;

        IF rFilteredFlow < 1.0 OR NOT bEnable THEN
            bGridTieBreakerClose := FALSE;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        IF bEmergencyStop AND bSeawaterIngressSensor THEN
            IF NOT bEnable THEN (* Require reset toggle *)
                iState := 0;
            END_IF;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
