Here is a Siemens SCL (Structured Control Language) function block (FB) for a Dairy Pasteurizer implementing a High-Temperature Short-Time (HTST) cascade PID control and Safety Flow Divert Valve (FDV) logic.

FUNCTION_BLOCK "Dairy_Pasteurizer_Base"
VERSION : 0.1
   VAR_INPUT
      Enable : Bool; // Start pasteurizer process
      ProductTemp : Real; // Current product temperature at holding tube (deg C)
      HeatingMediumTemp : Real; // Current hot water/steam temperature (deg C)
      SetpointTemp : Real; // Desired product pasteurization temperature (e.g., 72.0 deg C)
   END_VAR

   VAR_OUTPUT
      HeatingValveOut : Real; // 0-100% control for steam/hot water valve
      ForwardFlowValve : Bool; // True = Forward, False = Divert
      DivertFlowValve : Bool; // True = Divert, False = Forward
      SystemAlarm : Bool; // General system alarm
   END_VAR

   VAR
      PID_Master : "PID_Compact";
      PID_Slave : "PID_Compact";
      MasterOutSetpoint : Real;
      LegalTempMet : Bool;
      DivertTimer : TON;
   END_VAR

   VAR_TEMP
      MasterPID_Out : Real;
   END_VAR

BEGIN
   // Cascade PID Control
   // Master PID: Controls Product Temp, outputs Setpoint for Heating Medium
   #PID_Master(
      Reset := NOT #Enable,
      Setpoint := #SetpointTemp,
      Input := #ProductTemp,
      Output => #MasterOutSetpoint
   );

   // Slave PID: Controls Heating Medium Temp to match Master Output
   #PID_Slave(
      Reset := NOT #Enable,
      Setpoint := #MasterOutSetpoint,
      Input := #HeatingMediumTemp,
      Output => #HeatingValveOut
   );

   // Safety Flow Divert Valve (FDV) Logic
   // Legal pasteurization temperature must be met (e.g., 72 C for milk)
   IF #ProductTemp >= #SetpointTemp AND #Enable THEN
      #LegalTempMet := TRUE;
   ELSE
      #LegalTempMet := FALSE;
   END_IF;

   // Timer to ensure temp is held for legal time before allowing forward flow
   #DivertTimer(
      IN := #LegalTempMet,
      PT := T#15s // Typical holding time for HTST
   );

   IF #DivertTimer.Q THEN
      #ForwardFlowValve := TRUE;
      #DivertFlowValve := FALSE;
   ELSE
      #ForwardFlowValve := FALSE;
      #DivertFlowValve := TRUE;
   END_IF;

   // Alarm Logic
   #SystemAlarm := NOT #LegalTempMet AND #Enable;

END_FUNCTION_BLOCK
