FUNCTION_BLOCK FB_CNG_Station_Control
TITLE = 'Utility-Scale CNG Filling Station Control'

VAR_INPUT
    bStart_System : BOOL;
    bStop_System : BOOL;
    bEmergency_Stop : BOOL;
    rInlet_Pressure_bar : REAL;
    rLow_Bank_Pressure_bar : REAL;
    rMedium_Bank_Pressure_bar : REAL;
    rHigh_Bank_Pressure_bar : REAL;
    rVehicle_Fill_Pressure_bar : REAL;
    rCompressor_Discharge_Temp_C : REAL;
    rAmbient_Temp_C : REAL;
    rChiller_Water_Temp_C : REAL;
    bCompressor1_Ready : BOOL;
    bCompressor2_Ready : BOOL;
    bChiller_Ready : BOOL;
END_VAR

VAR_OUTPUT
    bCompressor1_Run : BOOL;
    bCompressor2_Run : BOOL;
    bCompressor1_Unload : BOOL;
    bCompressor2_Unload : BOOL;
    bValve_Inlet : BOOL;
    bValve_Low_Bank_Fill : BOOL;
    bValve_Medium_Bank_Fill : BOOL;
    bValve_High_Bank_Fill : BOOL;
    bValve_Vehicle_Low_Dispense : BOOL;
    bValve_Vehicle_Medium_Dispense : BOOL;
    bValve_Vehicle_High_Dispense : BOOL;
    bChiller_Run : BOOL;
    bSystem_Running : BOOL;
    bFault_Active : BOOL;
    iFault_Code : INT;
END_VAR

VAR
    eState : INT := 0;
    eFillState : INT := 0;
    tonStartDelay : TON;
    tonCompressorSeq : TON;
    tonChillerDelay : TON;
    rLow_Bank_Target : REAL := 200.0;
    rMedium_Bank_Target : REAL := 220.0;
    rHigh_Bank_Target : REAL := 250.0;
    rTemp_High_Limit : REAL := 80.0;
    bCascade_Demand : BOOL;
    bChilling_Required : BOOL;
END_VAR

IF NOT bEmergency_Stop OR rCompressor_Discharge_Temp_C > rTemp_High_Limit THEN
    eState := 99;
    bSystem_Running := FALSE;
    bCompressor1_Run := FALSE;
    bCompressor2_Run := FALSE;
    bValve_Inlet := FALSE;
    bValve_Low_Bank_Fill := FALSE;
    bValve_Medium_Bank_Fill := FALSE;
    bValve_High_Bank_Fill := FALSE;
    bValve_Vehicle_Low_Dispense := FALSE;
    bValve_Vehicle_Medium_Dispense := FALSE;
    bValve_Vehicle_High_Dispense := FALSE;
    bChiller_Run := FALSE;
    bFault_Active := TRUE;
    IF NOT bEmergency_Stop THEN
        iFault_Code := 1;
    ELSIF rCompressor_Discharge_Temp_C > rTemp_High_Limit THEN
        iFault_Code := 2;
    END_IF;
    RETURN;
END_IF;

CASE eState OF
    0:
        bSystem_Running := FALSE;
        IF bStart_System AND NOT bStop_System AND NOT bFault_Active THEN
            eState := 1;
        END_IF;
    1:
        bValve_Inlet := TRUE;
        bSystem_Running := TRUE;
        tonStartDelay(IN:=TRUE, PT:=T#5S);
        IF tonStartDelay.Q THEN
            eState := 2;
            tonStartDelay(IN:=FALSE);
        END_IF;
    2:
        IF bStop_System THEN
            eState := 3;
        END_IF;
    3:
        bCompressor1_Run := FALSE;
        bCompressor2_Run := FALSE;
        bValve_Inlet := FALSE;
        eState := 0;
END_CASE;

IF eState = 2 THEN
    IF rHigh_Bank_Pressure_bar < (rHigh_Bank_Target - 10.0) THEN
        eFillState := 3;
        bCascade_Demand := TRUE;
    ELSIF rMedium_Bank_Pressure_bar < (rMedium_Bank_Target - 10.0) THEN
        eFillState := 2;
        bCascade_Demand := TRUE;
    ELSIF rLow_Bank_Pressure_bar < (rLow_Bank_Target - 10.0) THEN
        eFillState := 1;
        bCascade_Demand := TRUE;
    ELSE
        eFillState := 0;
        bCascade_Demand := FALSE;
    END_IF;

    IF bCascade_Demand THEN
        IF bCompressor1_Ready AND NOT bCompressor1_Run THEN
            bCompressor1_Run := TRUE;
        END_IF;
        tonCompressorSeq(IN:=bCompressor1_Run, PT:=T#30S);
        IF tonCompressorSeq.Q AND bCompressor2_Ready AND NOT bCompressor2_Run AND rHigh_Bank_Pressure_bar < (rHigh_Bank_Target - 20.0) THEN
            bCompressor2_Run := TRUE;
        END_IF;
    ELSE
        bCompressor1_Run := FALSE;
        bCompressor2_Run := FALSE;
        tonCompressorSeq(IN:=FALSE);
    END_IF;

    bValve_High_Bank_Fill := (eFillState = 3);
    bValve_Medium_Bank_Fill := (eFillState = 2);
    bValve_Low_Bank_Fill := (eFillState = 1);

    IF rCompressor_Discharge_Temp_C > 50.0 THEN
        bChilling_Required := TRUE;
    ELSIF rCompressor_Discharge_Temp_C < 40.0 THEN
        bChilling_Required := FALSE;
    END_IF;

    IF bChilling_Required AND bChiller_Ready THEN
        bChiller_Run := TRUE;
    ELSE
        bChiller_Run := FALSE;
    END_IF;

    IF rVehicle_Fill_Pressure_bar < 200.0 THEN
        IF rLow_Bank_Pressure_bar > (rVehicle_Fill_Pressure_bar + 10.0) THEN
            bValve_Vehicle_Low_Dispense := TRUE;
            bValve_Vehicle_Medium_Dispense := FALSE;
            bValve_Vehicle_High_Dispense := FALSE;
        ELSIF rMedium_Bank_Pressure_bar > (rVehicle_Fill_Pressure_bar + 10.0) THEN
            bValve_Vehicle_Low_Dispense := FALSE;
            bValve_Vehicle_Medium_Dispense := TRUE;
            bValve_Vehicle_High_Dispense := FALSE;
        ELSIF rHigh_Bank_Pressure_bar > (rVehicle_Fill_Pressure_bar + 10.0) THEN
            bValve_Vehicle_Low_Dispense := FALSE;
            bValve_Vehicle_Medium_Dispense := FALSE;
            bValve_Vehicle_High_Dispense := TRUE;
        END_IF;
    ELSE
        bValve_Vehicle_Low_Dispense := FALSE;
        bValve_Vehicle_Medium_Dispense := FALSE;
        bValve_Vehicle_High_Dispense := FALSE;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
