```iec-st
// Siemens SCL - Rollercoaster Block Zone & Launch System
// Features: Block zones, brake modulation, anti-rollback, dynamic weighing, LSM launch sync

FUNCTION_BLOCK FB_Rollercoaster_LaunchSafety
TITLE = 'Rollercoaster Safety and Launch System'
VERSION : '2.0'

VAR_INPUT
    Zone1_Occupied : BOOL;
    Zone2_Occupied : BOOL;
    LaunchZone_Occupied : BOOL;
    TrainSpeed : REAL;
    TrainDirection : INT;
    E_Stop : BOOL;
    LoadCell1_Weight : REAL; // kg
    LoadCell2_Weight : REAL; // kg
    LoadCell3_Weight : REAL; // kg
    LoadCell4_Weight : REAL; // kg
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    TotalTrainMass : REAL; // kg
    LSM_ThrustForce : REAL; // kN
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;
END_VAR

VAR
    TargetSpeed : REAL := 5.0;
    MaxAllowableMass : REAL := 8000.0; // kg
    MinAllowableMass : REAL := 2500.0; // kg
    BaseThrust : REAL := 50.0; // kN for empty train
    MassThrustFactor : REAL := 0.01; // kN per kg
END_VAR

BEGIN
    // Fault Reset
    SystemFault := FALSE;
    FaultCode := 0;

    // E-Stop handling
    IF NOT E_Stop THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        FaultCode := 1; // E-Stop
        RETURN;
    END_IF;

    // Dynamic Train Weighing
    IF LaunchZone_Occupied AND TrainSpeed < 0.1 THEN
        TotalTrainMass := LoadCell1_Weight + LoadCell2_Weight + LoadCell3_Weight + LoadCell4_Weight;

        IF TotalTrainMass > MaxAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 2; // Overweight
            LSM_LaunchEnable := FALSE;
        ELSIF TotalTrainMass < MinAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 3; // Underweight (sensor fault or empty car error)
            LSM_LaunchEnable := FALSE;
        ELSE
            // Calculate required LSM thrust based on mass
            LSM_ThrustForce := BaseThrust + (TotalTrainMass - MinAllowableMass) * MassThrustFactor;
            // Check next block zone before enabling launch
            IF NOT Zone1_Occupied THEN
                LSM_LaunchEnable := TRUE;
            ELSE
                LSM_LaunchEnable := FALSE;
            END_IF;
        END_IF;
    ELSE
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
    END_IF;

    // Block Zone Interlock
    IF Zone1_Occupied AND NOT Zone2_Occupied THEN
        AllowProceedToZone2 := TRUE;
    ELSE
        AllowProceedToZone2 := FALSE;
    END_IF;

    // Brake Modulation
    IF Zone1_Occupied AND NOT AllowProceedToZone2 THEN
        FrictionBrakeLevel := 100.0;
    ELSIF Zone1_Occupied AND AllowProceedToZone2 THEN
        IF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback
    IF TrainDirection = -1 AND TrainSpeed > 0.1 THEN
        AntiRollbackDeploy := TRUE;
    ELSE
        AntiRollbackDeploy := FALSE;
    END_IF;

END_FUNCTION_BLOCK
