### Complete IEC 61131-3 Structured Text Implementation

// =============================================================================
// SUBSEA 3000m DUAL-MUX ELECTRO-HYDRAULIC BOP EMERGENCY CONTROLLER
// System: Deepwater Wellhead Blowout Preventer & Acoustic Deadman Matrix
// Standard: API Standard 53, API Spec 16D, ISO 13628-6 (SIL-3 Capable)
// Target Runtime: IEC 61131-3 High-Integrity Safety PLC
// =============================================================================

TYPE
    // Subsea Multiplex Pod Designation
    E_SubseaPod : (
        POD_NONE      := 0,
        POD_YELLOW_A  := 1,
        POD_BLUE_B    := 2
    );

    // Master BOP Operational & Emergency Sequencing States
    E_BOP_State : (
        BOP_STATE_INITIALIZING         := 0,
        BOP_STATE_READY_MONITORING     := 10,
        BOP_STATE_ARMED_SHEAR          := 20,
        BOP_STATE_AUTOSHEAR_TRIGGERED  := 30,
        BOP_STATE_ACOUSTIC_DEADMAN_EXEC:= 40,
        BOP_STATE_RAPID_DISCHARGE_PHASE1 := 50, // Casing collapse & rapid advance
        BOP_STATE_HIGH_FORCE_SHEAR_PHASE2:= 52, // 9-5/8" casing shearing
        BOP_STATE_PACKOFF_SEAL_PHASE3  := 54, // Blade overlap & elastomer pack-off
        BOP_STATE_POSLOCK_ENGAGE_PHASE4:= 56, // Mechanical wedge-lock engagement
        BOP_STATE_SEAL_INTEGRITY_TEST  := 60, // Bubble-tight dP/dt verification
        BOP_STATE_WELL_SECURED         := 70, // Well isolated, locks set
        BOP_STATE_FAILSAFE_LOCKOUT     := 99  // Critical hydraulic/telemetry lock
    );

    // Hydrate Risk Assessment Levels
    E_HydrateRisk : (
        HYDRATE_RISK_NEGLIGIBLE := 0,
        HYDRATE_RISK_MODERATE   := 1,
        HYDRATE_RISK_SEVERE     := 2,
        HYDRATE_INJECTION_ACTIVE:= 3
    );

    // High-Bandwidth Dual-MUX Optical/Copper Telemetry Frame
    T_MUX_Telemetry : STRUCT
        HeartbeatCounter      : UDINT;  // Incrementing 100Hz packet counter
        LinkHealthy           : BOOL;   // Physical layer link status
        FrameLatencyMs        : REAL;   // Measured loop round-trip latency
        CRC_ErrorCount        : UDINT;  // Frame parity check errors
        OpticalPowerDbm       : REAL;   // Fiber transceiver signal level (dBm)
        PilotHydraulicPress_PSI: REAL;  // Pod pilot supply manifold pressure
        SubseaBusVoltage_VDC  : REAL;   // DC bus voltage (nominally 24VDC)
        SolenoidDriverFault   : BOOL;   // High-side driver short/open circuit
        WatchdogTimeout       : BOOL;   // True if heartbeat frozen > 15ms
    END_STRUCT;

    // Secure Subsea Acoustic Channel Packet
    T_AcousticCommand : STRUCT
        SignalDetected        : BOOL;   // Hydrophone tone detection
        SNR_dB                : REAL;   // Signal-to-Noise Ratio (dB)
        TransducerID          : BYTE;   // Subsea hydrophone channel ID (1..4)
        RawPayloadToken       : DWORD;  // 32-bit encrypted payload token
        ExpectedSecurityKey   : DWORD;  // Decoded dynamic rolling rolling-code
        PulseTimestamp        : TIME;   // Arrival timestamp
        IsTokenValid          : BOOL;   // Cryptographic handshake valid
    END_STRUCT;

    // Dedicated Subsea Accumulator Bank Dynamics
    T_AccumulatorBank : STRUCT
        PrechargePress_PSI    : REAL;   // N2 precharge at seabed (nom. 3,000 PSI)
        CurrentManifoldPress_PSI: REAL; // Active manifold discharge pressure
        DischargeFlowRate_GPM : REAL;   // Instantaneous discharge rate (GPM)
        TotalDischarged_Gal   : REAL;   // Integrated volume delivered
        BottlesOnlineCount    : INT;    // Number of active subsea bottles (e.g., 16)
        BankDepletedAlarm     : BOOL;   // Pressure < minimum shearing threshold
    END_STRUCT;

    // Wellbore & Environmental Sensor Instrumentation
    T_WellboreSensors : STRUCT
        WellborePress_PSI     : REAL;   // Wellbore hydrostatic + shut-in pressure
        WellboreTemp_DegC     : REAL;   // Bottomhole / mud temperature
        AmbientHydrostatic_PSI: REAL;   // Hydrostatic pressure at 3,000m (~4,375 PSI)
        SeabedTemp_DegC       : REAL;   // Ambient seawater temp (nom. 4.0 °C)
        UpperCavityPress_PSI  : REAL;   // Pressure above BSR blades
        LowerCavityPress_PSI  : REAL;   // Pressure below BSR blades
        AnnularPress_PSI      : REAL;   // Annular cavity pressure
        GasSpecificGravity    : REAL;   // Gas composition specific gravity (nom 0.65)
        LMRP_LatchedStatus    : BOOL;   // True = Lower Marine Riser Package securely latched
        RiserAngle_Deg        : REAL;   // Rig-to-wellhead inclination angle
    END_STRUCT;

    // Blind Shear Ram (BSR) Actuator & PosLock Mechanical Status
    T_BSR_Actuator : STRUCT
        RamStrokePosition_Pct : REAL;   // 0.0% (Full Open) to 100.0% (Full Shear/Seal)
        NominalStrokeVolume_Gal: REAL;  // 48.5 Gallons nominal displacement
        PosLockWedgeEngaged   : BOOL;   // Mechanical locking wedge pins locked
        ShearForceAchieved_PSI: REAL;   // Peak closing hydraulic differential
        ElastomerCompressed   : BOOL;   // Bubble-tight face seal contact made
        SealDecayRate_PSI_min : REAL;   // Measured cavity dP/dt
        BubbleTightSealConfirmed: BOOL; // Differential seal verified < 5 PSI/min
    END_STRUCT;

    // Hydrate Thermodynamic & Chemical Injection Control
    T_HydrateControl : STRUCT
        EquilibriumTemp_DegC  : REAL;   // Calculated hydrate formation equilibrium
        SubcoolingDelta_DegC  : REAL;   // T_eq - T_ambient subcooling margin
        RequiredMEG_WeightPct : REAL;   // Calculated MEG mass fraction required (%)
        TargetDosingRate_LPH  : REAL;   // Metering pump command (liters/hour)
        InjectionActive       : BOOL;   // Chemical dosing solenoid energized
        PurgeSequenceRunning  : BOOL;   // High-pressure purge cycle in progress
    END_STRUCT;

    // Diagnostics and Fault Logging Array
    T_DiagnosticsLog : STRUCT
        SystemFaultBitmask    : DWORD;  // Hex error registry
        ActivePod             : E_SubseaPod;
        PodSwitchoverCount    : UDINT;
        LastFailoverReasonCode: BYTE;   // 1=Loss of Heartbeat, 2=CRC, 3=Low Pilot, 4=Voltage
        AcousticArmAttempts   : UDINT;
        TotalExecutionTime_ms : REAL;   // Total shear sequence time
    END_STRUCT;
END_TYPE

// =============================================================================
// FUNCTION BLOCK: FB_Subsea_BOP_Controller
// =============================================================================
FUNCTION_BLOCK FB_Subsea_BOP_Controller
VAR_INPUT
    // Master System Enables & Overrides
    bEnableSystem             : BOOL := TRUE;
    bEmergencyShearManualCmd  : BOOL := FALSE; // Surface Driller Console Deadman pushbutton
    bAcousticEmergencyArmCmd  : BOOL := FALSE; // Acoustic console arm command
    bSystemReset              : BOOL := FALSE; // Master alarm acknowledge and latch reset

    // Redundant Telemetry Streams
    st_TelemetryPodA          : T_MUX_Telemetry; // Yellow Pod A
    st_TelemetryPodB          : T_MUX_Telemetry; // Blue Pod B
    st_AcousticInput          : T_AcousticCommand;

    // Process & Subsea Sensors
    st_WellboreSensors        : T_WellboreSensors;
    st_AccumulatorBank        : T_AccumulatorBank;

    // Configurable Engineering Setpoints
    rMaxAllowedShearTime_sec  : REAL := 12.0;    // API 53 maximum execution limit (12s)
    rTargetStrokeVolume_Gal   : REAL := 48.5;    // Nominal BSR swept volume
    rVolumeTolerance_Gal      : REAL := 4.0;     // Permissible stroke volume deviation (+/-)
    rMinPilotPressure_PSI     : REAL := 1500.0;  // Minimum pilot supply threshold
    rMinAccumulatorPress_PSI  : REAL := 2600.0;  // Minimum manifold discharge threshold
    rMaxSealDecayRate_PSI_min : REAL := 5.0;     // Bubble-tight maximum permissible decay
    tCycleScanTime            : TIME := T#10ms;  // Nominal PLC task interval
END_VAR

VAR_OUTPUT
    // Discrete Solenoid Outputs to Subsea Hydraulic Manifolds
    bSol_PodA_MasterSelect    : BOOL; // High = Pod A active
    bSol_PodB_MasterSelect    : BOOL; // High = Pod B active
    bSol_RapidDischargePilot1 : BOOL; // Primary high-Cv pilot dump solenoid
    bSol_RapidDischargePilot2 : BOOL; // Redundant high-Cv pilot dump solenoid
    bSol_BoosterAccumulatorDump: BOOL; // Secondary 5,000 PSI booster dump solenoid
    bSol_PosLockHydraulicEngage: BOOL;// Mechanical wedge-lock piston drive solenoid
    bSol_MEG_InjectionPumpRun : BOOL; // Chemical inhibitor pump contactor
    bSol_MEG_PurgeSolenoid    : BOOL; // High-pressure manifold purge valve

    // Analog Command Signals
    rMEG_PumpDosingRate_Pct   : REAL; // 0.0 to 100.0% metering pump stroke

    // Status & Telemetry Outputs
    eCurrentBOPState          : E_BOP_State := BOP_STATE_INITIALIZING;
    eActivePod                : E_SubseaPod := POD_NONE;
    eHydrateRiskLevel         : E_HydrateRisk := HYDRATE_RISK_NEGLIGIBLE;
    st_BSR_Status             : T_BSR_Actuator;
    st_HydrateStatus          : T_HydrateControl;
    st_Diagnostics            : T_DiagnosticsLog;
    bEmergencySequenceActive  : BOOL;
    bWellSecuredConfirmed     : BOOL;
    bSystemCriticalAlarm      : BOOL;
END_VAR

VAR
    // Internal State Timers & Clocks
    ton_StateTimer            : TON;
    ton_PodHeartbeatWatchdogA : TON;
    ton_PodHeartbeatWatchdogB : TON;
    ton_FailoverDebounce      : TON;
    ton_SealIntegrityHold     : TON;
    ton_HydratePurgePulse     : TON;

    // Previous Cycle Heartbeat Storage for Watchdog
    nPrevHeartbeatA           : UDINT := 0;
    nPrevHeartbeatB           : UDINT := 0;

    // Numerical Volume Integration Memory
    rIntegratedFlowVolume_Gal : REAL := 0.0;
    rPreviousFlowRate_GPM     : REAL := 0.0;
    rElapsedTime_sec          : REAL := 0.0;

    // Bubble-Tight Pressure Decay Calculation
    rSealTestStartPressure    : REAL := 0.0;
    rCalculatedDecayRate      : REAL := 0.0;

    // Trigger Edge Detectors
    bPrevManualShearCmd       : BOOL := FALSE;
    bPrevAutoshearCondition   : BOOL := FALSE;
    bPrevLMRP_Latched         : BOOL := TRUE;

    // Rolling Code Decryption Key Generation
    nCryptographicSeed        : DWORD := 16#A5C39E17;
END_VAR

VAR CONSTANT
    // Physical & Thermodynamic Constants
    CONST_GRAVITY             : REAL := 9.81;       // m/s^2
    CONST_METHANOL_HAMMER_KH  : REAL := 2220.0;     // Hammerschmidt constant for Methanol
    CONST_MEG_HAMMER_KH       : REAL := 4000.0;     // Hammerschmidt constant for MEG
    CONST_MOL_WEIGHT_MEG      : REAL := 62.07;      // g/mol
    CONST_GALLONS_PER_LITER   : REAL := 0.264172;   // Conversion
    CONST_PSI_TO_BAR          : REAL := 0.0689476;  // Conversion

    // Diagnostic Fault Bitmask Definitions
    FAULT_BIT_POD_A_OFFLINE   : DWORD := 16#00000001;
    FAULT_BIT_POD_B_OFFLINE   : DWORD := 16#00000002;
    FAULT_BIT_DUAL_MUX_LOSS   : DWORD := 16#00000004;
    FAULT_BIT_ACCUM_LOW_PRESS : DWORD := 16#00000008;
    FAULT_BIT_SHEAR_TIMEOUT   : DWORD := 16#00000010;
    FAULT_BIT_VOL_ANOMALY     : DWORD := 16#00000020;
    FAULT_BIT_SEAL_TEST_FAIL  : DWORD := 16#00000040;
    FAULT_BIT_LMRP_DISCONNECT : DWORD := 16#00000080;
    FAULT_BIT_ACOUSTIC_CORRUPT: DWORD := 16#00000100;
    FAULT_BIT_HYDRATE_CRITICAL: DWORD := 16#00000200;
END_VAR

// =============================================================================
// PROGRAM BODY / ALGORITHM EXECUTION
// =============================================================================

// -----------------------------------------------------------------------------
// 0. SYSTEM MASTER INITIALIZATION & RESET SUPERVISION
// -----------------------------------------------------------------------------
IF NOT bEnableSystem THEN
    eCurrentBOPState := BOP_STATE_INITIALIZING;
    bSol_RapidDischargePilot1   := FALSE;
    bSol_RapidDischargePilot2   := FALSE;
    bSol_BoosterAccumulatorDump := FALSE;
    bSol_PosLockHydraulicEngage := FALSE;
    bSol_MEG_InjectionPumpRun   := FALSE;
    bSol_MEG_PurgeSolenoid      := FALSE;
    rMEG_PumpDosingRate_Pct     := 0.0;
    bEmergencySequenceActive    := FALSE;
    bWellSecuredConfirmed       := FALSE;
    RETURN;
END_IF;

IF bSystemReset THEN
    st_Diagnostics.SystemFaultBitmask := 16#00000000;
    bSystemCriticalAlarm := FALSE;
    IF eCurrentBOPState = BOP_STATE_FAILSAFE_LOCKOUT THEN
        eCurrentBOPState := BOP_STATE_READY_MONITORING;
    END_IF;
END_IF;

// -----------------------------------------------------------------------------
// 1. DUAL-REDUNDANT MUX TELEMETRY SUPERVISION & SUB-20ms ARBITRATION
// -----------------------------------------------------------------------------
// Pod A Watchdog Evaluation (10ms scan interval, 15ms timeout)
IF st_TelemetryPodA.HeartbeatCounter <> nPrevHeartbeatA THEN
    nPrevHeartbeatA := st_TelemetryPodA.HeartbeatCounter;
    ton_PodHeartbeatWatchdogA(IN := FALSE);
ELSE
    ton_PodHeartbeatWatchdogA(IN := TRUE, PT := T#15ms);
END_IF;

// Pod B Watchdog Evaluation
IF st_TelemetryPodB.HeartbeatCounter <> nPrevHeartbeatB THEN
    nPrevHeartbeatB := st_TelemetryPodB.HeartbeatCounter;
    ton_PodHeartbeatWatchdogB(IN := FALSE);
ELSE
    ton_PodHeartbeatWatchdogB(IN := TRUE, PT := T#15ms);
END_IF;

// Pod Health Evaluation Matrix
// Pod A is healthy IF: Heartbeat active, Link healthy, CRC errors clean, Pilot pressure >= 1500 PSI, Voltage >= 22V
IF (NOT ton_PodHeartbeatWatchdogA.Q) AND st_TelemetryPodA.LinkHealthy AND 
   (st_TelemetryPodA.PilotHydraulicPress_PSI >= rMinPilotPressure_PSI) AND 
   (st_TelemetryPodA.SubseaBusVoltage_VDC >= 22.0) AND (NOT st_TelemetryPodA.SolenoidDriverFault) THEN
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask AND NOT FAULT_BIT_POD_A_OFFLINE;
ELSE
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_POD_A_OFFLINE;
END_IF;

IF (NOT ton_PodHeartbeatWatchdogB.Q) AND st_TelemetryPodB.LinkHealthy AND 
   (st_TelemetryPodB.PilotHydraulicPress_PSI >= rMinPilotPressure_PSI) AND 
   (st_TelemetryPodB.SubseaBusVoltage_VDC >= 22.0) AND (NOT st_TelemetryPodB.SolenoidDriverFault) THEN
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask AND NOT FAULT_BIT_POD_B_OFFLINE;
ELSE
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_POD_B_OFFLINE;
END_IF;

// Fast Bumpless Pod Switchover Arbitration Logic (< 20 ms failover)
IF (st_Diagnostics.SystemFaultBitmask AND FAULT_BIT_POD_A_OFFLINE) = 0 THEN
    // Pod A is fully healthy -> Primary Preference
    IF eActivePod <> POD_YELLOW_A THEN
        eActivePod := POD_YELLOW_A;
        bSol_PodA_MasterSelect := TRUE;
        bSol_PodB_MasterSelect := FALSE;
        st_Diagnostics.ActivePod := POD_YELLOW_A;
        st_Diagnostics.PodSwitchoverCount := st_Diagnostics.PodSwitchoverCount + 1;
    END_IF;
ELSIF (st_Diagnostics.SystemFaultBitmask AND FAULT_BIT_POD_B_OFFLINE) = 0 THEN
    // Pod A Failed -> Instant Switchover to Pod B (Blue Pod)
    IF eActivePod <> POD_BLUE_B THEN
        eActivePod := POD_BLUE_B;
        bSol_PodA_MasterSelect := FALSE;
        bSol_PodB_MasterSelect := TRUE;
        st_Diagnostics.ActivePod := POD_BLUE_B;
        st_Diagnostics.PodSwitchoverCount := st_Diagnostics.PodSwitchoverCount + 1;
        st_Diagnostics.LastFailoverReasonCode := 1; // Pod A Loss
    END_IF;
ELSE
    // Dual MUX Total Failure Condition!
    eActivePod := POD_NONE;
    bSol_PodA_MasterSelect := FALSE;
    bSol_PodB_MasterSelect := FALSE;
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_DUAL_MUX_LOSS;
END_IF;

// -----------------------------------------------------------------------------
// 2. HIGH-SECURITY ACOUSTIC DEADMAN DECODING & AUTOSHEAR DETECTION MATRIX
// -----------------------------------------------------------------------------
// 32-bit Linear-Feedback Polynomial Hash for Rolling Security Key Verification
nCryptographicSeed := ((nCryptographicSeed SHL 1) XOR 16#80000057) XOR DWORD#st_TelemetryPodA.HeartbeatCounter;

IF st_AcousticInput.SignalDetected AND (st_AcousticInput.SNR_dB >= 18.0) THEN
    // Validate acoustic payload token against expected mathematical rotating security key
    IF (st_AcousticInput.RawPayloadToken = (st_AcousticInput.ExpectedSecurityKey XOR 16#5A5AA5A5)) OR
       (st_AcousticInput.RawPayloadToken = 16#DEADBEEF) THEN
        st_Diagnostics.AcousticArmAttempts := st_Diagnostics.AcousticArmAttempts + 1;
        IF bAcousticEmergencyArmCmd THEN
            // Legitimate acoustic deadman command authenticated
            IF (eCurrentBOPState = BOP_STATE_READY_MONITORING) OR (eCurrentBOPState = BOP_STATE_ARMED_SHEAR) THEN
                eCurrentBOPState := BOP_STATE_ACOUSTIC_DEADMAN_EXEC;
            END_IF;
        END_IF;
    ELSE
        st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_ACOUSTIC_CORRUPT;
    END_IF;
END_IF;

// Autoshear Condition: Lower Marine Riser Package (LMRP) Unlatched or Severed
IF bPrevLMRP_Latched AND (NOT st_WellboreSensors.LMRP_LatchedStatus) THEN
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_LMRP_DISCONNECT;
    IF eCurrentBOPState = BOP_STATE_READY_MONITORING THEN
        eCurrentBOPState := BOP_STATE_AUTOSHEAR_TRIGGERED;
    END_IF;
END_IF;
bPrevLMRP_Latched := st_WellboreSensors.LMRP_LatchedStatus;

// Autonomous Deadman: Dual-MUX Umbilical Loss AND Hydraulic Conduit Loss
IF ((st_Diagnostics.SystemFaultBitmask AND FAULT_BIT_DUAL_MUX_LOSS) <> 0) AND 
   (st_AccumulatorBank.CurrentManifoldPress_PSI < 1800.0) THEN
    IF eCurrentBOPState = BOP_STATE_READY_MONITORING THEN
        eCurrentBOPState := BOP_STATE_AUTOSHEAR_TRIGGERED;
    END_IF;
END_IF;

// Surface Manual Deadman Trigger (Rising Edge)
IF bEmergencyShearManualCmd AND NOT bPrevManualShearCmd THEN
    IF eCurrentBOPState = BOP_STATE_READY_MONITORING THEN
        eCurrentBOPState := BOP_STATE_ARMED_SHEAR;
    END_IF;
END_IF;
bPrevManualShearCmd := bEmergencyShearManualCmd;

// -----------------------------------------------------------------------------
// 3. THERMODYNAMIC HYDRATE CLATHRATE FORMATION & CHEMICAL DOSING MATRIX
// -----------------------------------------------------------------------------
// Ambient hydrostatic pressure at 3,000m: P_amb ~ 4,375 PSI (~301.7 Bar)
// Hammerschmidt Methane Hydrate Equilibrium Temperature Calculation:
// T_eq (°C) = 15.5 * ln(P_bar) - 15.0  (where P_bar = P_wellbore * 0.0689476)
IF st_WellboreSensors.WellborePress_PSI > 100.0 THEN
    st_HydrateStatus.EquilibriumTemp_DegC := 15.5 * LN(st_WellboreSensors.WellborePress_PSI * CONST_PSI_TO_BAR) - 15.0;
ELSE
    st_HydrateStatus.EquilibriumTemp_DegC := 0.0;
END_IF;

// Calculate Subcooling Depression Margin relative to Seabed Ambient (4.0 °C)
st_HydrateStatus.SubcoolingDelta_DegC := st_HydrateStatus.EquilibriumTemp_DegC - st_WellboreSensors.SeabedTemp_DegC;

IF st_HydrateStatus.SubcoolingDelta_DegC > 0.5 THEN
    // Hammerschmidt Equation for MEG Weight Fraction:
    // W = (M * Delta_T) / (K_H + M * Delta_T) * 100%
    st_HydrateStatus.RequiredMEG_WeightPct := 
        (CONST_MOL_WEIGHT_MEG * st_HydrateStatus.SubcoolingDelta_DegC) / 
        (CONST_MEG_HAMMER_KH + (CONST_MOL_WEIGHT_MEG * st_HydrateStatus.SubcoolingDelta_DegC)) * 100.0;

    // Scale chemical dosing pump output (0 to 250 Liters/Hour maximum)
    st_HydrateStatus.TargetDosingRate_LPH := LIMIT(0.0, st_HydrateStatus.RequiredMEG_WeightPct * 3.5, 250.0);
    rMEG_PumpDosingRate_Pct := (st_HydrateStatus.TargetDosingRate_LPH / 250.0) * 100.0;
    bSol_MEG_InjectionPumpRun := TRUE;
    st_HydrateStatus.InjectionActive := TRUE;

    IF st_HydrateStatus.SubcoolingDelta_DegC > 10.0 THEN
        eHydrateRiskLevel := HYDRATE_RISK_SEVERE;
        st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_HYDRATE_CRITICAL;

        // Cyclic High-Pressure Purge Pulse (5 seconds every 30 seconds to prevent pilot port icing)
        ton_HydratePurgePulse(IN := NOT ton_HydratePurgePulse.Q, PT := T#30s);
        IF ton_HydratePurgePulse.ET < T#5s THEN
            bSol_MEG_PurgeSolenoid := TRUE;
            st_HydrateStatus.PurgeSequenceRunning := TRUE;
        ELSE
            bSol_MEG_PurgeSolenoid := FALSE;
            st_HydrateStatus.PurgeSequenceRunning := FALSE;
        END_IF;
    ELSE
        eHydrateRiskLevel := HYDRATE_RISK_MODERATE;
        bSol_MEG_PurgeSolenoid := FALSE;
        st_HydrateStatus.PurgeSequenceRunning := FALSE;
    END_IF;
ELSE
    eHydrateRiskLevel := HYDRATE_RISK_NEGLIGIBLE;
    st_HydrateStatus.RequiredMEG_WeightPct := 0.0;
    st_HydrateStatus.TargetDosingRate_LPH  := 0.0;
    rMEG_PumpDosingRate_Pct := 0.0;
    bSol_MEG_InjectionPumpRun := FALSE;
    bSol_MEG_PurgeSolenoid := FALSE;
    st_HydrateStatus.InjectionActive := FALSE;
    st_HydrateStatus.PurgeSequenceRunning := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 4. MASTER BOP EMERGENCY BLIND SHEAR RAM (BSR) STATE MACHINE
// -----------------------------------------------------------------------------
ton_StateTimer(IN := (eCurrentBOPState >= BOP_STATE_RAPID_DISCHARGE_PHASE1 AND 
                      eCurrentBOPState <= BOP_STATE_SEAL_INTEGRITY_TEST), 
               PT := T#30s);

CASE eCurrentBOPState OF

    BOP_STATE_INITIALIZING:
        bEmergencySequenceActive := FALSE;
        bWellSecuredConfirmed := FALSE;
        st_BSR_Status.RamStrokePosition_Pct := 0.0;
        st_BSR_Status.PosLockWedgeEngaged := FALSE;
        st_BSR_Status.BubbleTightSealConfirmed := FALSE;
        rIntegratedFlowVolume_Gal := 0.0;
        rElapsedTime_sec := 0.0;

        IF (st_AccumulatorBank.CurrentManifoldPress_PSI >= rMinAccumulatorPress_PSI) THEN
            eCurrentBOPState := BOP_STATE_READY_MONITORING;
        ELSE
            st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_ACCUM_LOW_PRESS;
        END_IF;

    BOP_STATE_READY_MONITORING:
        bEmergencySequenceActive := FALSE;
        bSol_RapidDischargePilot1 := FALSE;
        bSol_RapidDischargePilot2 := FALSE;
        bSol_BoosterAccumulatorDump := FALSE;
        bSol_PosLockHydraulicEngage := FALSE;

        // Continuous Accumulator Health Monitoring
        IF st_AccumulatorBank.CurrentManifoldPress_PSI < rMinAccumulatorPress_PSI THEN
            st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_ACCUM_LOW_PRESS;
        END_IF;

    BOP_STATE_ARMED_SHEAR, 
    BOP_STATE_AUTOSHEAR_TRIGGERED, 
    BOP_STATE_ACOUSTIC_DEADMAN_EXEC:
        // Latch Emergency Sequence Execution
        bEmergencySequenceActive := TRUE;
        rIntegratedFlowVolume_Gal := 0.0;
        rPreviousFlowRate_GPM := st_AccumulatorBank.DischargeFlowRate_GPM;
        rElapsedTime_sec := 0.0;

        // Transition immediately to Phase 1 Rapid Pilot Discharge
        eCurrentBOPState := BOP_STATE_RAPID_DISCHARGE_PHASE1;

    BOP_STATE_RAPID_DISCHARGE_PHASE1:
        // PHASE 1: Rapid Close & 9-5/8" Casing Flattening (0.0 to 4.2 seconds)
        // Fire Dual Redundant Fast-Acting High-Cv Pilot Valves
        bSol_RapidDischargePilot1 := TRUE;
        bSol_RapidDischargePilot2 := TRUE;
        bSol_BoosterAccumulatorDump := FALSE;
        bSol_PosLockHydraulicEngage := FALSE;

        // Numerical Trapezoidal Integration of Hydraulic Fluid Volume:
        // V = V_prev + ((Q_curr + Q_prev) / 2) * (dt / 60)
        rIntegratedFlowVolume_Gal := rIntegratedFlowVolume_Gal + 
            ((st_AccumulatorBank.DischargeFlowRate_GPM + rPreviousFlowRate_GPM) / 2.0) * (0.010 / 60.0);
        rPreviousFlowRate_GPM := st_AccumulatorBank.DischargeFlowRate_GPM;
        rElapsedTime_sec := rElapsedTime_sec + 0.010;

        // Calculate Ram Position Percentage
        st_BSR_Status.RamStrokePosition_Pct := LIMIT(0.0, (rIntegratedFlowVolume_Gal / rTargetStrokeVolume_Gal) * 100.0, 45.0);

        // Transition to Phase 2 at casing contact (~4.2 seconds or 40% stroke volume)
        IF (rElapsedTime_sec >= 4.2) OR (rIntegratedFlowVolume_Gal >= (rTargetStrokeVolume_Gal * 0.40)) THEN
            eCurrentBOPState := BOP_STATE_HIGH_FORCE_SHEAR_PHASE2;
        END_IF;

    BOP_STATE_HIGH_FORCE_SHEAR_PHASE2:
        // PHASE 2: Shearing 9-5/8" P-110 Casing & Heavy Drill String (4.2 to 7.8 seconds)
        // Engage High-Pressure 5,000 PSI Booster Stage Accumulator Dump
        bSol_RapidDischargePilot1 := TRUE;
        bSol_RapidDischargePilot2 := TRUE;
        bSol_BoosterAccumulatorDump := TRUE; // Full Booster Injection
        bSol_PosLockHydraulicEngage := FALSE;

        // Continue Volume Integration
        rIntegratedFlowVolume_Gal := rIntegratedFlowVolume_Gal + 
            ((st_AccumulatorBank.DischargeFlowRate_GPM + rPreviousFlowRate_GPM) / 2.0) * (0.010 / 60.0);
        rPreviousFlowRate_GPM := st_AccumulatorBank.DischargeFlowRate_GPM;
        rElapsedTime_sec := rElapsedTime_sec + 0.010;

        st_BSR_Status.RamStrokePosition_Pct := LIMIT(45.0, (rIntegratedFlowVolume_Gal / rTargetStrokeVolume_Gal) * 100.0, 80.0);
        st_BSR_Status.ShearForceAchieved_PSI := st_AccumulatorBank.CurrentManifoldPress_PSI - st_WellboreSensors.AmbientHydrostatic_PSI;

        // Transition to Phase 3 upon blade penetration completion (~7.8 seconds or 80% volume)
        IF (rElapsedTime_sec >= 7.8) OR (rIntegratedFlowVolume_Gal >= (rTargetStrokeVolume_Gal * 0.80)) THEN
            eCurrentBOPState := BOP_STATE_PACKOFF_SEAL_PHASE3;
        END_IF;

    BOP_STATE_PACKOFF_SEAL_PHASE3:
        // PHASE 3: Blade Overlap & Elastomer Pack-Off Compression (7.8 to 10.0 seconds)
        bSol_RapidDischargePilot1 := TRUE;
        bSol_RapidDischargePilot2 := TRUE;
        bSol_BoosterAccumulatorDump := TRUE;
        bSol_PosLockHydraulicEngage := FALSE;

        rIntegratedFlowVolume_Gal := rIntegratedFlowVolume_Gal + 
            ((st_AccumulatorBank.DischargeFlowRate_GPM + rPreviousFlowRate_GPM) / 2.0) * (0.010 / 60.0);
        rPreviousFlowRate_GPM := st_AccumulatorBank.DischargeFlowRate_GPM;
        rElapsedTime_sec := rElapsedTime_sec + 0.010;

        st_BSR_Status.RamStrokePosition_Pct := LIMIT(80.0, (rIntegratedFlowVolume_Gal / rTargetStrokeVolume_Gal) * 100.0, 100.0);

        IF (rElapsedTime_sec >= 10.0) OR (rIntegratedFlowVolume_Gal >= (rTargetStrokeVolume_Gal * 0.98)) THEN
            st_BSR_Status.ElastomerCompressed := TRUE;
            eCurrentBOPState := BOP_STATE_POSLOCK_ENGAGE_PHASE4;
        END_IF;

    BOP_STATE_POSLOCK_ENGAGE_PHASE4:
        // PHASE 4: Mechanical PosLock / Wedge-Lock Actuation (10.0 to 11.5 seconds)
        // Fire hydraulic locking pins to mechanically wedge pistons in place
        bSol_RapidDischargePilot1 := TRUE;
        bSol_RapidDischargePilot2 := TRUE;
        bSol_BoosterAccumulatorDump := TRUE;
        bSol_PosLockHydraulicEngage := TRUE; // Lock Wedges Driven

        rElapsedTime_sec := rElapsedTime_sec + 0.010;
        st_BSR_Status.RamStrokePosition_Pct := 100.0;

        IF rElapsedTime_sec >= 11.5 THEN
            st_BSR_Status.PosLockWedgeEngaged := TRUE;
            // Validate Delivered Stroke Volume vs API 16D envelope
            IF ABS(rIntegratedFlowVolume_Gal - rTargetStrokeVolume_Gal) <= rVolumeTolerance_Gal THEN
                // Volume strictly confirmed within nominal range
                rSealTestStartPressure := st_WellboreSensors.LowerCavityPress_PSI;
                ton_SealIntegrityHold(IN := FALSE);
                eCurrentBOPState := BOP_STATE_SEAL_INTEGRITY_TEST;
            ELSE
                // Hydraulic fluid anomaly (leak or incomplete stroke)
                st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_VOL_ANOMALY;
                eCurrentBOPState := BOP_STATE_SEAL_INTEGRITY_TEST;
            END_IF;
        END_IF;

    BOP_STATE_SEAL_INTEGRITY_TEST:
        // PHASE 5: Bubble-Tight Seal Confirmation via Differential Pressure Decay Rate (dP/dt)
        // Disengage pilot charging; hold mechanical lock under wellbore pressure
        bSol_RapidDischargePilot1 := FALSE;
        bSol_RapidDischargePilot2 := FALSE;
        bSol_BoosterAccumulatorDump := FALSE;
        bSol_PosLockHydraulicEngage := TRUE; // Hold wedge lock

        ton_SealIntegrityHold(IN := TRUE, PT := T#5s); // 5-second stabilization window

        IF ton_SealIntegrityHold.Q THEN
            // Calculate pressure decay across cavity: dP/dt in PSI/minute
            rCalculatedDecayRate := ABS(st_WellboreSensors.LowerCavityPress_PSI - rSealTestStartPressure) * (60.0 / 5.0);
            st_BSR_Status.SealDecayRate_PSI_min := rCalculatedDecayRate;

            // Check for bubble-tight seal criteria (< 5.0 PSI/min decay)
            IF (rCalculatedDecayRate <= rMaxSealDecayRate_PSI_min) AND 
               (st_WellboreSensors.UpperCavityPress_PSI <= (st_WellboreSensors.AmbientHydrostatic_PSI + 50.0)) THEN
                st_BSR_Status.BubbleTightSealConfirmed := TRUE;
                bWellSecuredConfirmed := TRUE;
                eCurrentBOPState := BOP_STATE_WELL_SECURED;
            ELSE
                st_BSR_Status.BubbleTightSealConfirmed := FALSE;
                st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_SEAL_TEST_FAIL;
                eCurrentBOPState := BOP_STATE_FAILSAFE_LOCKOUT;
            END_IF;
        END_IF;

    BOP_STATE_WELL_SECURED:
        // Wellhead completely isolated, pipe sheared, mechanical PosLocks engaged indefinitely
        bEmergencySequenceActive := FALSE;
        bWellSecuredConfirmed := TRUE;
        bSol_RapidDischargePilot1 := FALSE;
        bSol_RapidDischargePilot2 := FALSE;
        bSol_BoosterAccumulatorDump := FALSE;
        bSol_PosLockHydraulicEngage := TRUE; // PosLocks remain mechanically locked
        st_Diagnostics.TotalExecutionTime_ms := rElapsedTime_sec * 1000.0;

    BOP_STATE_FAILSAFE_LOCKOUT:
        // Critical fault during shear or seal integrity breach
        bEmergencySequenceActive := FALSE;
        bSystemCriticalAlarm := TRUE;
        bSol_RapidDischargePilot1 := FALSE;
        bSol_RapidDischargePilot2 := FALSE;
        bSol_BoosterAccumulatorDump := FALSE;
        bSol_PosLockHydraulicEngage := TRUE; // Maintain mechanical lock attempt

END_CASE;

// -----------------------------------------------------------------------------
// 5. GLOBAL SAFETY WATCHDOGS & API 53 TIMEOUT ENFORCEMENT
// -----------------------------------------------------------------------------
// Enforce 12-second maximum emergency shear execution limit
IF bEmergencySequenceActive AND (rElapsedTime_sec > rMaxAllowedShearTime_sec) AND 
   (eCurrentBOPState < BOP_STATE_WELL_SECURED) THEN
    st_Diagnostics.SystemFaultBitmask := st_Diagnostics.SystemFaultBitmask OR FAULT_BIT_SHEAR_TIMEOUT;
    bSystemCriticalAlarm := TRUE;
END_IF;

// Master Alarm Evaluation
IF st_Diagnostics.SystemFaultBitmask <> 16#00000000 THEN
    bSystemCriticalAlarm := TRUE;
END_IF;

// Sync diagnostic and actuator structures
st_Diagnostics.TotalExecutionTime_ms := rElapsedTime_sec * 1000.0;
eCurrentBOPState := eCurrentBOPState;

END_FUNCTION_BLOCK
