```iec-st
FUNCTION_BLOCK FB_EBeam_Sterilization_Control
TITLE = 'Commercial E-Beam Sterilization Cell Control'
VERSION : '2.1'

VAR_INPUT
    bEnableProcess         : BOOL;        // Master Start Command from HMI
    bResetAlarms           : BOOL;        // Reset Fault conditions
    rTargetDose_kGy        : REAL;        // Desired sterilization dose (e.g., 25.0 kGy)
    rConveyorSpeedSet_mmin : REAL;        // Requested conveyor speed (m/min)
    rCathodeVoltageSet_kV  : REAL;        // Requested acceleration voltage (kV)
    rBeamCurrentSet_mA     : REAL;        // Requested beam current (mA)

    // Physical I/O Feedbacks
    bShieldDoorsClosed     : BOOL;        // Double-interlocked radiation shield doors
    bOzoneExhaustRunning   : BOOL;        // Exhaust blower operational status
    bProductPresentTrigger : BOOL;        // Upstream product entry detection
    rActualCathodeV_kV     : REAL;        // Feedback from high voltage power supply
    rActualBeamCurrent_mA  : REAL;        // Feedback from beam current transformer
    rProductWeight_kg      : REAL;        // Load cell measurement for dose density correction

    tTaskCycleTime         : TIME;        // Cycle time of the calling task for integration
END_VAR

VAR_OUTPUT
    bSystemReady           : BOOL;        // Safe and ready for emission
    bHVEnable              : BOOL;        // Interlock release for High Voltage Power Supply
    bBeamEnable            : BOOL;        // Grid control for beam emission
    rCommandVoltage_kV     : REAL;        // Analog command to HVPS
    rCommandCurrent_mA     : REAL;        // Analog command to beam grid
    bConveyorRun           : BOOL;        // Command to conveyor VFD
    rCalculatedDose_kGy    : REAL;        // Integrated dose applied to current product

    bAlarmActive           : BOOL;        // Global alarm flag
    iAlarmCode             : INT;         // Specific alarm code
    sAlarmDescription      : STRING(50);  // Text description of alarm
END_VAR

VAR
    iStateMachine          : INT := 0;    // Main sequence state
    rDoseIntegration       : REAL := 0.0; // Internal dose accumulator
    rTimeStep_sec          : REAL;        // Integration time step derived from tTaskCycleTime
    rDoseRateConstant      : REAL := 0.045; // Calibration factor: (kGy * m/min) / (mA * kV)

    tDoseTimer             : TON;         // Timer for product transit tracking
    tPreSweepTimer         : TON;         // Timer for ozone purge before beam enable

    // Cathode Emission Mapping
    aCathodeMap_Zones      : ARRAY[1..10] OF REAL; // Emission uniform profile across 10 scan zones
    iZoneIndex             : INT;
    rAvgUniformity         : REAL;
    rMaxDeviation          : REAL;
    rZoneCorrectionFactor  : REAL := 1.02; // Empirical correction for beam scatter
END_VAR

// ==============================================================================
// MAIN LOGIC IMPLEMENTATION
// ==============================================================================

// Calculate time step in seconds for numerical integration
rTimeStep_sec := TIME_TO_REAL(tTaskCycleTime) / 1000.0;

// ALARM AND SAFETY INTERLOCK HANDLING
IF NOT bShieldDoorsClosed THEN
    bAlarmActive := TRUE;
    iAlarmCode := 101;
    sAlarmDescription := 'CRITICAL: Shield Doors Opened!';
    iStateMachine := 999; // Jump to fault state
ELSIF NOT bOzoneExhaustRunning THEN
    bAlarmActive := TRUE;
    iAlarmCode := 102;
    sAlarmDescription := 'FAULT: Ozone Exhaust Failure';
    iStateMachine := 999;
ELSIF bResetAlarms THEN
    bAlarmActive := FALSE;
    iAlarmCode := 0;
    sAlarmDescription := 'No Alarms';
    IF iStateMachine = 999 THEN
        iStateMachine := 0; // Reset to idle
    END_IF;
END_IF;

// MAIN STATE MACHINE
CASE iStateMachine OF
    0: // IDLE
        bSystemReady := bShieldDoorsClosed AND bOzoneExhaustRunning;
        bHVEnable := FALSE;
        bBeamEnable := FALSE;
        bConveyorRun := FALSE;
        rCommandVoltage_kV := 0.0;
        rCommandCurrent_mA := 0.0;
        rDoseIntegration := 0.0;

        IF bEnableProcess AND bSystemReady AND NOT bAlarmActive THEN
            iStateMachine := 10;
        END_IF;

    10: // PRE-SWEEP & HV RAMP-UP
        tPreSweepTimer(IN := TRUE, PT := T#5S);
        rCommandVoltage_kV := rCathodeVoltageSet_kV; // Command voltage
        bHVEnable := TRUE; // Enable HVPS

        // Wait for pre-sweep and high voltage stabilization
        IF tPreSweepTimer.Q AND (ABS(rActualCathodeV_kV - rCathodeVoltageSet_kV) < 5.0) THEN
            tPreSweepTimer(IN := FALSE);
            iStateMachine := 20;
        END_IF;

    20: // READY FOR PRODUCT
        bConveyorRun := TRUE; // Start conveyor

        // Map emission zones before beam on (Simulated mapping logic)
        rAvgUniformity := 0.0;
        FOR iZoneIndex := 1 TO 10 DO
            aCathodeMap_Zones[iZoneIndex] := rBeamCurrentSet_mA / 10.0 * rZoneCorrectionFactor;
            rAvgUniformity := rAvgUniformity + aCathodeMap_Zones[iZoneIndex];
        END_FOR;
        rAvgUniformity := rAvgUniformity / 10.0;

        IF bProductPresentTrigger THEN
            rDoseIntegration := 0.0; // Reset dose accumulator
            iStateMachine := 30;
        END_IF;

    30: // IRRADIATION IN PROGRESS
        bBeamEnable := TRUE;
        rCommandCurrent_mA := rBeamCurrentSet_mA;

        // Continuous Dose Integration using actual process variables
        // Dose Rate ~ Current * Voltage / (Conveyor Speed * Density Factor)
        IF rConveyorSpeedSet_mmin > 0.1 AND rProductWeight_kg > 0.0 THEN
            rDoseIntegration := rDoseIntegration + 
                (rActualBeamCurrent_mA * rActualCathodeV_kV * rDoseRateConstant / 
                (rConveyorSpeedSet_mmin * (rProductWeight_kg * 0.1))) * rTimeStep_sec;
        END_IF;

        rCalculatedDose_kGy := rDoseIntegration;

        // Check if product has received target dose or passed through zone
        // For continuous flow, this state transitions based on product exit
        IF NOT bProductPresentTrigger AND (rCalculatedDose_kGy >= rTargetDose_kGy) THEN
            bBeamEnable := FALSE;
            rCommandCurrent_mA := 0.0;
            iStateMachine := 20; // Wait for next product
        ELSIF NOT bProductPresentTrigger AND (rCalculatedDose_kGy < rTargetDose_kGy) THEN
            bAlarmActive := TRUE;
            iAlarmCode := 201;
            sAlarmDescription := 'FAULT: Under-dose detected';
            iStateMachine := 999;
        END_IF;

    999: // FAULT STATE
        bHVEnable := FALSE;
        bBeamEnable := FALSE;
        bConveyorRun := FALSE;
        rCommandVoltage_kV := 0.0;
        rCommandCurrent_mA := 0.0;
        tPreSweepTimer(IN := FALSE);

END_CASE;
END_FUNCTION_BLOCK
