FUNCTION_BLOCK "FB_Autoclave_Cure_M3"
TITLE = 'Autoclave with Cybersecurity, Failover, SCADA'
VERSION : '1.3'

VAR_INPUT
    bStart_Cycle : Bool;
    rAct_Temp_1 : Real; // Primary TC
    rAct_Temp_2 : Real; // Redundant TC
    rAct_Pressure : Real;
    rAct_N2_Level : Real;
    rAct_Vac_Pressure : Real;
    wPN_Device_Status : Word;
    iUser_Role : Int; // IEC 62443 RBAC
    bSCADA_Override : Bool;
END_VAR

VAR_OUTPUT
    bCmd_Heater : Bool;
    bCmd_PressValve : Bool;
    bCmd_N2_Purge : Bool;
    bCmd_Vac_Pump : Bool;
    bAlarm_Abort : Bool;
    wDiag_Code : Word;
    iSCADA_State_Tag : Int; // SCADA Integration
    bFailover_Active : Bool;
    bCyberSec_Alarm : Bool;
END_VAR

VAR
    iState : Int;
    tDwell_Timer : TON_TIME;
    rActive_Temp : Real;
END_VAR

BEGIN
    // IEC 62443 RBAC
    IF bStart_Cycle AND (iUser_Role < 3) AND NOT bSCADA_Override THEN
        bCyberSec_Alarm := TRUE;
        wDiag_Code := 16#C001; // Unauthorized access
        iState := 99;
    ELSE
        bCyberSec_Alarm := FALSE;
    END_IF;

    // Failover Redundancy Logic
    IF ABS(rAct_Temp_1 - rAct_Temp_2) > 5.0 THEN
        rActive_Temp := rAct_Temp_2; // Failover to redundant
        bFailover_Active := TRUE;
        wDiag_Code := 16#E010; // Sensor discrepancy warning
    ELSE
        rActive_Temp := rAct_Temp_1;
        bFailover_Active := FALSE;
    END_IF;

    CASE iState OF
        0: // Idle
            bAlarm_Abort := FALSE;
            IF bStart_Cycle AND wDiag_Code = 16#0000 THEN iState := 10; END_IF;
        10: // Purge & Vacuum
            bCmd_N2_Purge := TRUE;
            bCmd_Vac_Pump := TRUE;
            IF (rAct_N2_Level > 95.0) AND (rAct_Vac_Pressure < 0.1) THEN
                bCmd_N2_Purge := FALSE;
                iState := 20;
            END_IF;
        20: // Heat & Pressurize
            bCmd_Heater := (rActive_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF (rActive_Temp >= 180.0) AND (rAct_Pressure >= 7.0) THEN iState := 30; END_IF;
        30: // Dwell
            tDwell_Timer(IN := TRUE, PT := T#120M);
            bCmd_Heater := (rActive_Temp < 180.0);
            IF tDwell_Timer.Q THEN
                bCmd_Heater := FALSE;
                bCmd_PressValve := FALSE;
                iState := 40;
            END_IF;
        40: // Cool
            bCmd_Vac_Pump := FALSE;
            IF rActive_Temp < 50.0 THEN iState := 0; tDwell_Timer(IN := FALSE, PT := T#0S); END_IF;
        99: // Abort
            bCmd_Heater := FALSE;
            bCmd_PressValve := FALSE;
            bAlarm_Abort := TRUE;
    END_CASE;

    iSCADA_State_Tag := iState; // Export to SCADA
END_FUNCTION_BLOCK
