FUNCTION_BLOCK "FB_BatchReactor_Breadth"
VERSION : 0.1
   VAR_INPUT 
      start_batch : Bool;
      reactor_temp : Real;
      reactor_press : Real;
      catalyst_flow : Real;
      agitator_load : Real;
      setpoint_temp : Real;
      setpoint_dosing : Real;
      pn_io_status : Word;
   END_VAR

   VAR_OUTPUT 
      cooling_valve : Real;
      dosing_pump : Bool;
      agitator_speed_ref : Real;
      alarm_high_press : Bool;
      interlock_rupture : Bool;
      fault_io_module : Bool;
      fault_code : Word;
   END_VAR

   VAR 
      pid_cooling : "PID_Compact";
      total_catalyst : Real;
      batch_active : Bool;
   END_VAR

BEGIN
   // Profinet Diagnostics
   IF #pn_io_status <> 16#0000 THEN
       #fault_io_module := TRUE;
       #fault_code := #pn_io_status;
       // Fail-safe state on IO loss
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
       RETURN;
   ELSE
       #fault_io_module := FALSE;
       #fault_code := 16#0000;
   END_IF;

   // Interlocks
   IF #reactor_press > 10.0 THEN
       #interlock_rupture := TRUE;
       #alarm_high_press := TRUE;
       #batch_active := FALSE;
   END_IF;

   IF #interlock_rupture THEN
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
       RETURN;
   END_IF;

   IF #start_batch AND NOT #interlock_rupture THEN
       #batch_active := TRUE;
   END_IF;

   IF #batch_active THEN
       // Cooling PID
       #pid_cooling(Setpoint := #setpoint_temp, Input := #reactor_temp, Output => #cooling_valve);

       // Dosing
       IF #total_catalyst < #setpoint_dosing THEN
           #dosing_pump := TRUE;
           #total_catalyst := #total_catalyst + (#catalyst_flow * 0.1);
       ELSE
           #dosing_pump := FALSE;
       END_IF;

       // Agitator VFD Control
       IF #agitator_load > 85.0 THEN
           #agitator_speed_ref := 40.0; // Load shedding
       ELSE
           #agitator_speed_ref := 100.0;
       END_IF;
   ELSE
       #cooling_valve := 0.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
   END_IF;
END_FUNCTION_BLOCK
