FUNCTION_BLOCK FB_AAV_BioreactorControl
TITLE = 'Gene Therapy Viral Vector Bioreactor Advanced Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    rTransfectionTime       : REAL; // Current transfection time [h]
    bTransfectionStart      : BOOL; // Start transfection process
    rAgitatorSpeed          : REAL; // Current agitator speed [rpm]
    rCellDensity            : REAL; // Current viable cell density [cells/mL]
    rFeedPressure           : REAL; // TFF feed pressure [bar]
    rRetentatePressure      : REAL; // TFF retentate pressure [bar]
    rPermeatePressure       : REAL; // TFF permeate pressure [bar]
    rTargetShearStress      : REAL; // Max allowed shear stress [Pa]
    rViscosity              : REAL; // Culture viscosity [mPa.s]
END_VAR

VAR_OUTPUT
    rDosingPumpSpeed        : REAL; // Speed of dosing pump [mL/min]
    rTransmembranePressure  : REAL; // Calculated TMP [bar]
    rRetentateValvePos      : REAL; // Position of retentate control valve [%]
    rAgitatorSetpoint       : REAL; // Corrected agitator speed to limit shear [%]
    bShearAlarm             : BOOL; // Alarm if shear stress is too high
    bDosingComplete         : BOOL; // Transfection dosing completed
END_VAR

VAR
    rTMP_Setpoint           : REAL := 0.8; // Target TMP [bar]
    rPID_Kp                 : REAL := 2.5; // PID proportional gain for TFF
    rPID_Ki                 : REAL := 0.5; // PID integral gain for TFF
    rIntegralError          : REAL := 0.0;
    rCurrentShearStress     : REAL;
    rImpellerDiameter       : REAL := 0.15; // Impeller diameter [m]
    rFluidDensity           : REAL := 1010.0; // Culture density [kg/m^3]
    rReagentTotalVolume     : REAL := 5000.0; // Total reagent [mL]
    rDosedVolume            : REAL := 0.0; // Accumulated dosed volume
    tLastCycleTime          : TIME := T#100MS; // Control cycle time
END_VAR

// 1. Transfection Reagent Dosing Timing
IF bTransfectionStart AND NOT bDosingComplete THEN
    IF rTransfectionTime < 2.0 THEN
        rDosingPumpSpeed := 50.0 + (rCellDensity / 1.0E6) * 10.0;
    ELSIF rTransfectionTime >= 2.0 AND rTransfectionTime < 6.0 THEN
        rDosingPumpSpeed := 120.0 + (rCellDensity / 1.0E6) * 15.0;
    ELSE
        rDosingPumpSpeed := 0.0;
        bDosingComplete := TRUE;
    END_IF;

    rDosedVolume := rDosedVolume + (rDosingPumpSpeed / 600.0);

    IF rDosedVolume >= rReagentTotalVolume THEN
        bDosingComplete := TRUE;
        rDosingPumpSpeed := 0.0;
    END_IF;
ELSE
    rDosingPumpSpeed := 0.0;
END_IF;

// 2. Tangential Cross-Flow Filtration (TFF) Pressure Regulation
rTransmembranePressure := ((rFeedPressure + rRetentatePressure) / 2.0) - rPermeatePressure;
rIntegralError := rIntegralError + ((rTMP_Setpoint - rTransmembranePressure) * 0.1);
IF rIntegralError > 100.0 THEN rIntegralError := 100.0; END_IF;
IF rIntegralError < -100.0 THEN rIntegralError := -100.0; END_IF;
rRetentateValvePos := (rPID_Kp * (rTMP_Setpoint - rTransmembranePressure)) + (rPID_Ki * rIntegralError);
IF rRetentateValvePos > 100.0 THEN rRetentateValvePos := 100.0; END_IF;
IF rRetentateValvePos < 0.0 THEN rRetentateValvePos := 0.0; END_IF;

// 3. Cellular Shear Stress Limitation
rCurrentShearStress := rViscosity * (rAgitatorSpeed / 60.0) * (rImpellerDiameter / 0.1); 
IF rCurrentShearStress > rTargetShearStress THEN
    bShearAlarm := TRUE;
    rAgitatorSetpoint := rAgitatorSpeed * (rTargetShearStress / rCurrentShearStress) * 0.95;
ELSE
    bShearAlarm := FALSE;
    rAgitatorSetpoint := rAgitatorSpeed;
END_IF;

END_FUNCTION_BLOCK
