FUNCTION_BLOCK FB_SMR_ReactorControl
TITLE = 'SMR Primary Core and Safety Systems Control'
VERSION : '2.1'
AUTHOR  : 'Lumina Swarm Architect'

(* 
   Highly complex control scenario for Small Modular Reactor (SMR):
   - Passive safety decay heat removal
   - Control rod magnetic shim drives
   - Primary coolant boron injection cascades
*)

VAR_INPUT
    bAutoMode : BOOL; // Auto control active
    bScramTrigger : BOOL; // Manual or external SCRAM command
    rCoreTempAvg : REAL; // Average core temperature in Celsius
    rCorePressure : REAL; // Primary loop pressure in Bar
    rNeutronFlux : REAL; // Neutron flux percentage
    rCoolantFlow : REAL; // Primary coolant flow rate L/s
    bDecayHeatSystemAvail : BOOL; // Decay heat removal system availability
END_VAR

VAR_OUTPUT
    bRodDropCmd : BOOL; // Command to drop all control rods
    rRodPositionSetpoint : REAL; // Target position for magnetic shims (0-100%)
    bBoronPumpCmd : BOOL; // Command to start boron injection pump
    rBoronValveOpening : REAL; // Boron injection cascade valve opening (0-100%)
    bPassiveCoolingActive : BOOL; // Passive cooling engaged
    bPlantTripAlarm : BOOL; // Critical plant trip status
    iSystemState : INT; // Current operating state
END_VAR

VAR
    bInternalScram : BOOL; // Internally generated SCRAM condition
    tScramTimer : TON; // Timer to verify rod drop
    rTempRateOfChange : REAL;
    rLastCoreTemp : REAL;
    bBoronInterlock : BOOL;
    tBoronCascadeTimer : TON;
    rCalculatedReactivity : REAL;
    bEmergencyCoolingTrigger : BOOL;

    // Safety thresholds
    rMaxTemp_Trip : REAL := 345.0; // Celsius
    rMaxPress_Trip : REAL := 155.0; // Bar
    rHighFlux_Trip : REAL := 110.0; // %
END_VAR

BEGIN
    // Step 1: Compute Rate of Change for Core Temperature (derivative protection)
    rTempRateOfChange := rCoreTempAvg - rLastCoreTemp;
    rLastCoreTemp := rCoreTempAvg;

    // Step 2: Critical Trip Condition Monitoring (SCRAM Evaluation)
    IF rCoreTempAvg > rMaxTemp_Trip OR 
       rCorePressure > rMaxPress_Trip OR 
       rNeutronFlux > rHighFlux_Trip OR 
       rTempRateOfChange > 15.0 THEN
        bInternalScram := TRUE;
    ELSE
        bInternalScram := FALSE;
    END_IF;

    // Step 3: SCRAM Execution (Magnetic Shim Drive Release)
    IF bScramTrigger OR bInternalScram THEN
        bRodDropCmd := TRUE;
        bPlantTripAlarm := TRUE;
        rRodPositionSetpoint := 0.0; // Fully inserted
        iSystemState := 99; // TRIP STATE

        // Timer for SCRAM verification
        tScramTimer(IN:=TRUE, PT:=T#2S);

        // If rods fail to fully insert (simulated by timeout), initiate emergency boron
        IF tScramTimer.Q THEN
            bBoronInterlock := TRUE;
        END_IF;
    ELSE
        bRodDropCmd := FALSE;
        bPlantTripAlarm := FALSE;
        tScramTimer(IN:=FALSE);
        bBoronInterlock := FALSE;
    END_IF;

    // Step 4: Passive Safety Decay Heat Removal System
    // In SMRs, passive cooling uses natural circulation when active flow is lost or during SCRAM
    IF (bPlantTripAlarm AND rCoolantFlow < 50.0) AND bDecayHeatSystemAvail THEN
        bEmergencyCoolingTrigger := TRUE;
    END_IF;

    IF bEmergencyCoolingTrigger THEN
        bPassiveCoolingActive := TRUE;
        // Logic to modulate heat exchangers would go here
    ELSE
        bPassiveCoolingActive := FALSE;
    END_IF;

    // Step 5: Primary Coolant Boron Injection Cascades
    // Used for secondary reactivity control if magnetic shims fail or for long-term shutdown margin
    IF bBoronInterlock OR (rCoreTempAvg > (rMaxTemp_Trip - 10.0) AND NOT bRodDropCmd) THEN
        bBoronPumpCmd := TRUE;
        tBoronCascadeTimer(IN:=TRUE, PT:=T#10S);

        // Cascade injection staging
        IF tBoronCascadeTimer.ET < T#5S THEN
            rBoronValveOpening := 30.0; // 30% initial cascade
        ELSIF tBoronCascadeTimer.ET >= T#5S AND tBoronCascadeTimer.ET < T#10S THEN
            rBoronValveOpening := 60.0; // 60% secondary cascade
        ELSE
            rBoronValveOpening := 100.0; // 100% full emergency injection
        END_IF;
    ELSE
        bBoronPumpCmd := FALSE;
        rBoronValveOpening := 0.0;
        tBoronCascadeTimer(IN:=FALSE);
    END_IF;

    // Step 6: Normal Operation Magnetic Shim Drive Control
    IF bAutoMode AND NOT bPlantTripAlarm THEN
        iSystemState := 1; // NORMAL AUTO
        // Simplified reactivity calculation based on inverse temp logic
        rCalculatedReactivity := 100.0 - ((rCoreTempAvg / 300.0) * 100.0);

        IF rCalculatedReactivity > 100.0 THEN
            rRodPositionSetpoint := 100.0;
        ELSIF rCalculatedReactivity < 0.0 THEN
            rRodPositionSetpoint := 0.0;
        ELSE
            rRodPositionSetpoint := rCalculatedReactivity;
        END_IF;
    ELSIF NOT bPlantTripAlarm THEN
        iSystemState := 2; // NORMAL MANUAL
    END_IF;

END_FUNCTION_BLOCK
