FUNCTION_BLOCK FB_HVDC_Bipolar_Controller
TITLE = 'HVDC Bipolar System Control and Firing Angle Calculator'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Swarm'

VAR_INPUT
    rVdc_Pole1_Meas : REAL; (* Measured DC Voltage Pole 1 (kV) *)
    rVdc_Pole2_Meas : REAL; (* Measured DC Voltage Pole 2 (kV) *)
    rIdc_Pole1_Meas : REAL; (* Measured DC Current Pole 1 (kA) *)
    rIdc_Pole2_Meas : REAL; (* Measured DC Current Pole 2 (kA) *)
    rVdc_Ref        : REAL; (* Reference DC Voltage (kV) *)
    rIdc_Ref        : REAL; (* Reference DC Current (kA) *)
    bInverterMode   : BOOL; (* TRUE = Inverter, FALSE = Rectifier *)
    rVac_Grid_Meas  : REAL; (* AC Grid Voltage (kV) *)
    rQ_Demand       : REAL; (* Reactive Power Demand (MVAR) *)
    bEmergencyStop  : BOOL; (* Emergency Trip *)
END_VAR

VAR_OUTPUT
    rAlpha_Pole1    : REAL; (* Firing Angle Pole 1 (degrees) *)
    rAlpha_Pole2    : REAL; (* Firing Angle Pole 2 (degrees) *)
    rGamma_Pole1    : REAL; (* Extinction Angle Pole 1 (degrees) *)
    rGamma_Pole2    : REAL; (* Extinction Angle Pole 2 (degrees) *)
    bFilterBank1_Cmd: BOOL; (* Reactive Power Filter Bank 1 ON/OFF *)
    bFilterBank2_Cmd: BOOL; (* Reactive Power Filter Bank 2 ON/OFF *)
    bFilterBank3_Cmd: BOOL; (* Reactive Power Filter Bank 3 ON/OFF *)
    bTripCommand    : BOOL; (* System Trip Command *)
    rDelta_Vdc_Err  : REAL; (* Voltage Imbalance *)
    rDelta_Idc_Err  : REAL; (* Current Imbalance *)
END_VAR

VAR
    rKp_V           : REAL := 0.45;
    rKi_V           : REAL := 1.25;
    rKp_I           : REAL := 0.85;
    rKi_I           : REAL := 2.10;
    rInteg_V1       : REAL := 0.0;
    rInteg_V2       : REAL := 0.0;
    rInteg_I1       : REAL := 0.0;
    rInteg_I2       : REAL := 0.0;
    rError_V1       : REAL;
    rError_V2       : REAL;
    rError_I1       : REAL;
    rError_I2       : REAL;
    rAlphaMin       : REAL := 5.0;
    rAlphaMax_Rect  : REAL := 85.0;
    rAlphaMin_Inv   : REAL := 110.0;
    rAlphaMax_Inv   : REAL := 160.0;
    rGammaMin       : REAL := 15.0;
    rVdc_Nominal    : REAL := 500.0;
    rQ_FilterStep   : REAL := 50.0;
    bCommutationFail: BOOL := FALSE;
    rTimeStep       : REAL := 0.001; (* 1ms scan cycle *)
END_VAR

(* Control Logic Starts Here *)
IF bEmergencyStop THEN
    bTripCommand := TRUE;
    rAlpha_Pole1 := 90.0;
    rAlpha_Pole2 := 90.0;
    bFilterBank1_Cmd := FALSE;
    bFilterBank2_Cmd := FALSE;
    bFilterBank3_Cmd := FALSE;
    RETURN;
ELSE
    bTripCommand := FALSE;
END_IF;

(* Calculate Imbalances for Pole Balancing *)
rDelta_Vdc_Err := ABS(rVdc_Pole1_Meas - rVdc_Pole2_Meas);
rDelta_Idc_Err := ABS(rIdc_Pole1_Meas - rIdc_Pole2_Meas);

(* Protection: Commutation Failure Check (Inverter Mode) *)
IF bInverterMode AND (rVac_Grid_Meas < 0.85 * (rVdc_Nominal / 1.35)) THEN
    bCommutationFail := TRUE;
ELSE
    bCommutationFail := FALSE;
END_IF;

IF bCommutationFail THEN
    rAlpha_Pole1 := 140.0; (* Advance firing to increase commutation margin *)
    rAlpha_Pole2 := 140.0;
    rGamma_Pole1 := 20.0;
    rGamma_Pole2 := 20.0;
ELSE
    (* PI Controllers for Current and Voltage *)
    rError_V1 := rVdc_Ref - rVdc_Pole1_Meas;
    rError_V2 := rVdc_Ref - rVdc_Pole2_Meas;
    rError_I1 := rIdc_Ref - rIdc_Pole1_Meas;
    rError_I2 := rIdc_Ref - rIdc_Pole2_Meas;

    (* Integration with anti-windup *)
    rInteg_V1 := rInteg_V1 + (rError_V1 * rKi_V * rTimeStep);
    rInteg_V2 := rInteg_V2 + (rError_V2 * rKi_V * rTimeStep);
    rInteg_I1 := rInteg_I1 + (rError_I1 * rKi_I * rTimeStep);
    rInteg_I2 := rInteg_I2 + (rError_I2 * rKi_I * rTimeStep);

    IF NOT bInverterMode THEN
        (* Rectifier: Constant Current Control primarily, Alpha limits 5-85 *)
        rAlpha_Pole1 := (rError_I1 * rKp_I) + rInteg_I1;
        rAlpha_Pole2 := (rError_I2 * rKp_I) + rInteg_I2;

        IF rAlpha_Pole1 > rAlphaMax_Rect THEN rAlpha_Pole1 := rAlphaMax_Rect; END_IF;
        IF rAlpha_Pole1 < rAlphaMin THEN rAlpha_Pole1 := rAlphaMin; END_IF;
        IF rAlpha_Pole2 > rAlphaMax_Rect THEN rAlpha_Pole2 := rAlphaMax_Rect; END_IF;
        IF rAlpha_Pole2 < rAlphaMin THEN rAlpha_Pole2 := rAlphaMin; END_IF;

        rGamma_Pole1 := 180.0 - rAlpha_Pole1 - 15.0; (* Approx overlap 15 deg *)
        rGamma_Pole2 := 180.0 - rAlpha_Pole2 - 15.0;
    ELSE
        (* Inverter: Constant Extinction Angle (Gamma) or Voltage Control *)
        rAlpha_Pole1 := (rError_V1 * rKp_V) + rInteg_V1 + 135.0; (* Base offset *)
        rAlpha_Pole2 := (rError_V2 * rKp_V) + rInteg_V2 + 135.0;

        IF rAlpha_Pole1 > rAlphaMax_Inv THEN rAlpha_Pole1 := rAlphaMax_Inv; END_IF;
        IF rAlpha_Pole1 < rAlphaMin_Inv THEN rAlpha_Pole1 := rAlphaMin_Inv; END_IF;
        IF rAlpha_Pole2 > rAlphaMax_Inv THEN rAlpha_Pole2 := rAlphaMax_Inv; END_IF;
        IF rAlpha_Pole2 < rAlphaMin_Inv THEN rAlpha_Pole2 := rAlphaMin_Inv; END_IF;

        rGamma_Pole1 := 180.0 - rAlpha_Pole1 - 20.0; (* Overlap approx 20 deg at inverter *)
        rGamma_Pole2 := 180.0 - rAlpha_Pole2 - 20.0;
    END_IF;
END_IF;

(* Reactive Power Compensation Switching Logic *)
(* Switches filter banks based on Q demand to maintain power factor *)
IF rQ_Demand > (2.5 * rQ_FilterStep) THEN
    bFilterBank1_Cmd := TRUE;
    bFilterBank2_Cmd := TRUE;
    bFilterBank3_Cmd := TRUE;
ELSIF rQ_Demand > (1.5 * rQ_FilterStep) THEN
    bFilterBank1_Cmd := TRUE;
    bFilterBank2_Cmd := TRUE;
    bFilterBank3_Cmd := FALSE;
ELSIF rQ_Demand > (0.5 * rQ_FilterStep) THEN
    bFilterBank1_Cmd := TRUE;
    bFilterBank2_Cmd := FALSE;
    bFilterBank3_Cmd := FALSE;
ELSE
    bFilterBank1_Cmd := FALSE;
    bFilterBank2_Cmd := FALSE;
    bFilterBank3_Cmd := FALSE;
END_IF;

END_FUNCTION_BLOCK
