FUNCTION_BLOCK FB_Spacecraft_TVAC_Control
TITLE = 'Spacecraft Thermal Vacuum Chamber Control System'
VERSION : '2.1'

VAR_INPUT
    bStart_Sequence : BOOL; // Initiate TVAC profile
    bEStop : BOOL; // Emergency stop
    rTarget_Temp_K : REAL; // Target temperature in Kelvin
    rTarget_Vacuum_Torr : REAL; // Target vacuum level in Torr
    rCurrent_Chamber_Temp_K : REAL; // Feedback from chamber average temp sensors
    rCurrent_Shroud_Temp_K : REAL; // Feedback from shroud temp sensors
    rCurrent_Vacuum_Torr : REAL; // Feedback from high-vacuum gauges
    bRoughing_Pump_Ready : BOOL;
    bTurbo_Pump_Ready : BOOL;
    bLN2_Supply_Ready : BOOL;
END_VAR

VAR_OUTPUT
    bRoughing_Pump_Run : BOOL;
    bTurbo_Pump_Run : BOOL;
    rIR_Lamp_Power_Setpoint : REAL; // 0.0 to 100.0 %
    rLN2_Valve_Position : REAL; // 0.0 to 100.0 %
    bCryoshroud_Circulator_Run : BOOL;
    nSystem_State : INT; // Current state machine step
    bProfile_Complete : BOOL;
    bAlarm_Active : BOOL;
    sStatus_Message : STRING[50];
END_VAR

VAR
    TMR_Soak_Time : TON;
    PID_Heater : PID; // Standard PID block for heating
    PID_Cryo : PID; // Standard PID block for cooling
    rTemp_Error : REAL;
    bVacuum_Achieved : BOOL;
    tSoak_Duration : TIME := T#24H; // 24-hour thermal soak
END_VAR

// State Machine Constants
VAR CONSTANT
    STATE_IDLE : INT := 0;
    STATE_PUMPDOWN_ROUGHING : INT := 10;
    STATE_PUMPDOWN_HIGH_VAC : INT := 20;
    STATE_THERMAL_RAMP : INT := 30;
    STATE_THERMAL_SOAK : INT := 40;
    STATE_RECOVERY_BACKFILL : INT := 50;
    STATE_ESTOP_FAULT : INT := 99;
END_VAR

// Main Logic
IF bEStop THEN
    nSystem_State := STATE_ESTOP_FAULT;
END_IF;

CASE nSystem_State OF
    STATE_IDLE:
        bRoughing_Pump_Run := FALSE;
        bTurbo_Pump_Run := FALSE;
        rIR_Lamp_Power_Setpoint := 0.0;
        rLN2_Valve_Position := 0.0;
        bCryoshroud_Circulator_Run := FALSE;
        bProfile_Complete := FALSE;
        sStatus_Message := 'System Idle. Ready for sequence.';

        IF bStart_Sequence AND bRoughing_Pump_Ready AND bTurbo_Pump_Ready AND bLN2_Supply_Ready THEN
            nSystem_State := STATE_PUMPDOWN_ROUGHING;
        END_IF;

    STATE_PUMPDOWN_ROUGHING:
        sStatus_Message := 'Roughing pumpdown in progress.';
        bRoughing_Pump_Run := TRUE;

        // Transition to high vacuum when < 1.0 Torr
        IF rCurrent_Vacuum_Torr <= 1.0 THEN
            nSystem_State := STATE_PUMPDOWN_HIGH_VAC;
        END_IF;

        // Timeout or fault logic could be added here

    STATE_PUMPDOWN_HIGH_VAC:
        sStatus_Message := 'High vacuum pumpdown (Turbo) in progress.';
        bRoughing_Pump_Run := TRUE; // Backing pump
        bTurbo_Pump_Run := TRUE;

        IF rCurrent_Vacuum_Torr <= rTarget_Vacuum_Torr THEN
            bVacuum_Achieved := TRUE;
            nSystem_State := STATE_THERMAL_RAMP;
        END_IF;

    STATE_THERMAL_RAMP:
        sStatus_Message := 'Thermal ramping to target temperature.';
        bCryoshroud_Circulator_Run := TRUE;

        // Calculate error
        rTemp_Error := rTarget_Temp_K - rCurrent_Chamber_Temp_K;

        IF rTemp_Error > 0.0 THEN
            // Heating required
            PID_Heater(
                IN := rCurrent_Chamber_Temp_K,
                SP := rTarget_Temp_K,
                KP := 2.5,
                KI := 0.1,
                KD := 0.5,
                OUT => rIR_Lamp_Power_Setpoint
            );
            rLN2_Valve_Position := 0.0;
        ELSE
            // Cooling required
            PID_Cryo(
                IN := rCurrent_Chamber_Temp_K,
                SP := rTarget_Temp_K,
                KP := 5.0,
                KI := 0.2,
                KD := 1.0,
                OUT => rLN2_Valve_Position
            );
            rIR_Lamp_Power_Setpoint := 0.0;
        END_IF;

        IF ABS(rTemp_Error) < 1.0 THEN
            nSystem_State := STATE_THERMAL_SOAK;
        END_IF;

    STATE_THERMAL_SOAK:
        sStatus_Message := 'Thermal soak at target temperature.';
        TMR_Soak_Time(IN := TRUE, PT := tSoak_Duration);

        // Maintain temperature
        IF rTarget_Temp_K > 273.15 THEN
            // Simplistic PID call for soak
            rIR_Lamp_Power_Setpoint := 25.0; // Maintenance heat
            rLN2_Valve_Position := 0.0;
        ELSE
            rIR_Lamp_Power_Setpoint := 0.0;
            rLN2_Valve_Position := 30.0; // Maintenance cooling
        END_IF;

        IF TMR_Soak_Time.Q THEN
            nSystem_State := STATE_RECOVERY_BACKFILL;
            TMR_Soak_Time(IN := FALSE); // Reset timer
        END_IF;

    STATE_RECOVERY_BACKFILL:
        sStatus_Message := 'Thermal profile complete. Returning to ambient.';
        bTurbo_Pump_Run := FALSE;
        bRoughing_Pump_Run := FALSE;
        rIR_Lamp_Power_Setpoint := 0.0;
        rLN2_Valve_Position := 0.0;
        bCryoshroud_Circulator_Run := FALSE;

        bProfile_Complete := TRUE;

        // Wait for operator to acknowledge and clear
        IF NOT bStart_Sequence THEN
            nSystem_State := STATE_IDLE;
        END_IF;

    STATE_ESTOP_FAULT:
        sStatus_Message := 'EMERGENCY STOP / FAULT ACTIVE!';
        bRoughing_Pump_Run := FALSE;
        bTurbo_Pump_Run := FALSE;
        rIR_Lamp_Power_Setpoint := 0.0;
        rLN2_Valve_Position := 0.0; // Fail close
        bCryoshroud_Circulator_Run := FALSE;
        bAlarm_Active := TRUE;

        IF NOT bEStop THEN
            bAlarm_Active := FALSE;
            nSystem_State := STATE_IDLE;
        END_IF;

    ELSE
        nSystem_State := STATE_IDLE;
END_CASE;
END_FUNCTION_BLOCK
