FUNCTION_BLOCK FB_MOCVD_GaNEpitaxy
VAR_INPUT
    bEnable                 : BOOL;     (* System Enable Signal - Master start/stop for epitaxy process *)
    bEmergencyStop          : BOOL;     (* E-Stop interlock, MUST be TRUE for operation (Fail-safe) *)
    rSusceptorTempPV        : REAL;     (* Process Value: Actual susceptor temperature from pyrometer [deg C] *)
    rTMGaFlowPV             : REAL;     (* Process Value: Trimethylgallium (TMGa) mass flow [sccm] *)
    rNH3FlowPV              : REAL;     (* Process Value: Ammonia (NH3) mass flow [slm] *)
    rReactorPressurePV      : REAL;     (* Process Value: Reactor chamber pressure [Torr] *)
    rReflectanceSignal      : REAL;     (* In-situ laser reflectance signal for growth rate monitoring [V] *)
    rSusceptorSpeedPV       : REAL;     (* Process Value: Susceptor planetary rotation speed [RPM] *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for epitaxial growth *)
    rSusceptorTempCV        : REAL;     (* Control Variable: Susceptor heater power setpoint [%] *)
    rTMGaFlowCV             : REAL;     (* Control Variable: TMGa MFC setpoint [sccm] *)
    rNH3FlowCV              : REAL;     (* Control Variable: NH3 MFC setpoint [slm] *)
    rReactorPressureCV      : REAL;     (* Control Variable: Throttle valve position setpoint [%] *)
    rSusceptorSpeedCV       : REAL;     (* Control Variable: Rotation motor VFD setpoint [Hz] *)
    bGrowthComplete         : BOOL;     (* Target epitaxial thickness achieved *)
    bCriticalAlarm          : BOOL;     (* Critical fault requiring immediate system safe-state abort *)
    rEstimatedThickness     : REAL;     (* Calculated epitaxial layer thickness from interferometry [nm] *)
END_VAR
VAR
    iState                  : INT := 0; (* Main MOCVD state machine index *)

    (* Internal PID Controllers - Simplified representations *)
    rTempError              : REAL;
    rTempIntegral           : REAL;
    rPressureError          : REAL;
    rPressureIntegral       : REAL;

    (* Process Parameters *)
    rTargetTemp             : REAL := 1050.0; (* GaN Growth Temperature [deg C] *)
    rTargetPressure         : REAL := 100.0;  (* Growth pressure [Torr] *)
    rTargetRotation         : REAL := 1200.0; (* Planetary rotation [RPM] *)

    (* Timers *)
    tPurgeTimer             : TON;
    tGrowthTimer            : TON;
    tStabilizationTimer     : TON;

    (* Interferometry tracking *)
    rReflectancePrev        : REAL;
    bReflectanceRising      : BOOL;
    iInterferenceFringes    : INT := 0;
    rGrowthRate             : REAL := 0.5; (* nm per fringe (simplified calibration) *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady        := FALSE;
    bCriticalAlarm      := TRUE;
    rSusceptorTempCV    := 0.0;
    rTMGaFlowCV         := 0.0;
    rNH3FlowCV          := 0.0;
    rReactorPressureCV  := 0.0;
    rSusceptorSpeedCV   := 0.0;
    iState              := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* Continuous Reflectance Monitoring (Fringe Counting for Thickness) *)
IF (rReflectanceSignal > rReflectancePrev) AND NOT bReflectanceRising THEN
    bReflectanceRising := TRUE;
ELSIF (rReflectanceSignal < rReflectancePrev) AND bReflectanceRising THEN
    bReflectanceRising := FALSE;
    iInterferenceFringes := iInterferenceFringes + 1;
    rEstimatedThickness := INT_TO_REAL(iInterferenceFringes) * rGrowthRate;
END_IF;
rReflectancePrev := rReflectanceSignal;

(* PID Loops for continuous background control (when active) *)
IF iState >= 20 AND iState <= 50 THEN
    (* Temperature PID *)
    rTempError := rTargetTemp - rSusceptorTempPV;
    rTempIntegral := rTempIntegral + rTempError * 0.1;
    rSusceptorTempCV := (rTempError * 2.5) + (rTempIntegral * 0.05);
    IF rSusceptorTempCV > 100.0 THEN rSusceptorTempCV := 100.0; END_IF;
    IF rSusceptorTempCV < 0.0 THEN rSusceptorTempCV := 0.0; END_IF;

    (* Pressure PID *)
    rPressureError := rTargetPressure - rReactorPressurePV;
    rPressureIntegral := rPressureIntegral + rPressureError * 0.1;
    rReactorPressureCV := (rPressureError * 1.8) + (rPressureIntegral * 0.02);
    IF rReactorPressureCV > 100.0 THEN rReactorPressureCV := 100.0; END_IF;
    IF rReactorPressureCV < 0.0 THEN rReactorPressureCV := 0.0; END_IF;

    (* Rotation Control (Open loop VFD command approx) *)
    rSusceptorSpeedCV := rTargetRotation / 20.0; (* Assuming 60Hz = 1200RPM *)
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* SYSTEM IDLE & CHECK *)
        bSystemReady := TRUE;
        bGrowthComplete := FALSE;
        rEstimatedThickness := 0.0;
        iInterferenceFringes := 0;

        IF bEnable THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PURGE & EVACUATION *)
        rTargetPressure := 10.0; (* Low pressure for purge *)
        rTargetTemp := 50.0;
        tPurgeTimer(IN := TRUE, PT := T#30S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* THERMAL RAMP & BAKE *)
        rTargetTemp := 1100.0; (* High temp bake *)
        rTargetPressure := 50.0;
        rTargetRotation := 600.0;

        IF ABS(rSusceptorTempPV - rTargetTemp) < 5.0 THEN
            tStabilizationTimer(IN := TRUE, PT := T#1M);
            IF tStabilizationTimer.Q THEN
                 tStabilizationTimer(IN := FALSE);
                 iState := 30;
            END_IF;
        ELSE
            tStabilizationTimer(IN := FALSE);
        END_IF;

    30: (* PRECURSOR STABILIZATION & BUFFER LAYER *)
        rTargetTemp := 1050.0;
        rTargetPressure := 100.0;
        rTargetRotation := 1200.0;

        (* Introduce NH3 first to prevent desorption *)
        rNH3FlowCV := 5.0; 

        IF ABS(rSusceptorTempPV - rTargetTemp) < 2.0 AND ABS(rReactorPressurePV - rTargetPressure) < 1.0 THEN
            iState := 40;
        END_IF;

    40: (* MAIN EPITAXIAL GROWTH (GaN) *)
        rTMGaFlowCV := 50.0; (* Start Ga precursor *)
        rNH3FlowCV := 10.0;  (* Increase NH3 for high V/III ratio *)

        tGrowthTimer(IN := TRUE, PT := T#60M); (* Max growth time safety *)

        IF (rEstimatedThickness >= 2000.0) OR tGrowthTimer.Q THEN (* Target 2um GaN *)
            tGrowthTimer(IN := FALSE);
            rTMGaFlowCV := 0.0; (* Stop Ga *)
            iState := 50;
        END_IF;

    50: (* COOL DOWN *)
        rTargetTemp := 50.0;
        rNH3FlowCV := 2.0; (* Keep some NH3 until below 500C *)

        IF rSusceptorTempPV < 500.0 THEN
            rNH3FlowCV := 0.0;
        END_IF;

        IF rSusceptorTempPV < 100.0 THEN
            iState := 60;
        END_IF;

    60: (* PROCESS COMPLETE *)
        bGrowthComplete := TRUE;
        rReactorPressureCV := 0.0;
        rSusceptorSpeedCV := 0.0;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        (* Maintain safe state until reset *)
        IF NOT bCriticalAlarm AND bEmergencyStop AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
