TYPE "OPC_UA_SCADA_Data"
VERSION : 1.0
    STRUCT
        SetAlpha_SCADA : REAL;
        Access_Level : INT;
        Token : DWORD;
        ControllerRole : INT; // 1=Primary, 2=Secondary
        Heartbeat_Partner : BOOL;
