FUNCTION_BLOCK FB_CarbonCaptureAmine
VAR_INPUT
    (* Required: Advanced Carbon Capture and Storage (CCS) physical inputs *)
    bEnable                 : BOOL;     (* System master enable signal for column control *)
    bEmergencyStop          : BOOL;     (* Safety instrumented system (SIS) OK signal *)
    rFlueGasFlowIn          : REAL;     (* Incoming raw flue gas mass flow rate (kg/s) *)
    rFlueGasTempIn          : REAL;     (* Incoming raw flue gas temperature (deg C) *)
    rLeanAmineTempIn        : REAL;     (* Temperature of Lean Amine feeding into the column (deg C) *)
    rAbsorberPressure       : REAL;     (* Operating pressure inside the absorption column (bar) *)
    rCO2ConcentrationIn     : REAL;     (* Input CO2 molar concentration in flue gas (%) *)
END_VAR
VAR_OUTPUT
    (* Required: Control outputs for Advanced Carbon Capture *)
    bSystemReady            : BOOL;     (* Main column operating ready status *)
    rLeanAmineFlowCmd       : REAL;     (* Lean amine solvent flow rate control command (kg/s) *)
    rDCCWaterFlowCmd        : REAL;     (* Direct Contact Cooler (DCC) water quenching flow rate (kg/s) *)
    rReboilerSteamTrim      : REAL;     (* Stripper reboiler steam temperature trim demand (deg C) *)
    bAlarmHighPressure      : BOOL;     (* Alarm: Column pressure exceeded high-high safety limit *)
    bFault                  : BOOL;     (* General system fault or trip flag *)
END_VAR
VAR
    (* Internal states, timers, and calculated process variables *)
    iState                  : INT := 0; (* Main state machine transition integer *)
    tStartupDelay           : TON;      (* Timer for system initialization and thermal stabilization *)
    rCalculatedLGRatio      : REAL;     (* Dynamic Liquid to Gas (L/G) mass flow ratio setpoint *)
    rTargetCO2Removal       : REAL := 0.90; (* 90% target capture efficiency *)

    (* Filtered Process Variables *)
    rFilteredGasFlow        : REAL := 0.0;

    (* Tuning and physical parameters *)
    K_p_Amine               : REAL := 2.5;  (* Gain for amine flow control loop *)
    K_p_DCC                 : REAL := 0.8;  (* Gain for Direct Contact Cooler temperature quenching *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Master Control Evaluation *)
IF NOT bEmergencyStop THEN
    (* Immediate safe state execution on trip *)
    bSystemReady        := FALSE;
    bFault              := TRUE;
    rLeanAmineFlowCmd   := 0.0;
    rDCCWaterFlowCmd    := 0.0;
    rReboilerSteamTrim  := 0.0;
    bAlarmHighPressure  := FALSE;
    iState              := 0;
    RETURN;
END_IF;

(* Reset fault if healthy *)
bFault := FALSE;

(* 2. Limit and Alarm Checking for Column Integrity *)
IF rAbsorberPressure > 1.25 THEN
    bAlarmHighPressure := TRUE;
ELSE
    bAlarmHighPressure := FALSE;
END_IF;

(* 3. Simple First-Order Filter for Incoming Flue Gas Flow Smoothing *)
rFilteredGasFlow := rFilteredGasFlow + 0.1 * (rFlueGasFlowIn - rFilteredGasFlow);

(* 4. Main Carbon Capture State Machine Execution *)
CASE iState OF
    0: (* IDLE / SHUTDOWN *)
        bSystemReady := FALSE;
        rLeanAmineFlowCmd := 0.0;
        rDCCWaterFlowCmd := 0.0;
        rReboilerSteamTrim := 0.0;

        IF bEnable AND NOT bAlarmHighPressure THEN
            iState := 10;
        END_IF;

    10: (* INITIALIZATION & QUENCHING STABILIZATION *)
        (* Bring DCC water flow up based on incoming gas temperature to pre-cool before amine introduction *)
        rDCCWaterFlowCmd := (rFlueGasTempIn - 40.0) * K_p_DCC;
        IF rDCCWaterFlowCmd < 0.0 THEN
            rDCCWaterFlowCmd := 0.0;
        END_IF;

        tStartupDelay(IN := TRUE, PT := T#15S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RUNNING / ADVANCED SOLVENT ABSORPTION CONTROL *)
        bSystemReady := TRUE;

        (* Feed-forward mapping of Liquid/Gas ratio based on input CO2 concentration and target removal efficiency *)
        rCalculatedLGRatio := (rCO2ConcentrationIn * rTargetCO2Removal) * 4.2; 

        (* Calculate primary Lean Amine Flow Command *)
        rLeanAmineFlowCmd := rFilteredGasFlow * rCalculatedLGRatio * K_p_Amine;

        (* Reboiler Steam Trim adjustment based on solvent saturation *)
        (* Higher CO2 loading leads to requirement for more stripping energy in the regenerator column *)
        IF rLeanAmineFlowCmd > 50.0 THEN
            rReboilerSteamTrim := 15.5; 
        ELSE
            rReboilerSteamTrim := 5.0;
        END_IF;

        (* Continuous temperature management in Direct Contact Cooler *)
        rDCCWaterFlowCmd := (rFlueGasTempIn - 35.0) * K_p_DCC;

        IF NOT bEnable OR bAlarmHighPressure THEN
            iState := 0;
        END_IF;

    ELSE
        (* Failsafe default transition *)
        iState := 0;

END_CASE;

END_FUNCTION_BLOCK
