FUNCTION_BLOCK FB_AerosolCanFillingLine_SuperComplex
VAR_INPUT
    xSystemStart : BOOL;                // Master Start
    xEstopOk : BOOL;                    // Emergency stop healthy (Normally Closed loop)

    // Gasser & Shaker Inputs
    xCanAtGasser : BOOL;                // Photoeye can detect at gasser/shaker station
    rGasManifoldPressure : REAL;        // Propellant gas manifold pressure (Bar)
    rGasTemperature : REAL;             // Gas temperature (Celsius)
    xShakerManifoldHome : BOOL;         // Shaker at home position

    // Crimper Inputs
    xCanAtCrimper : BOOL;               // Photoeye can detect at crimper station
    rCrimpColletDepthRaw : REAL;        // Analog sensor for crimp collet depth (mm)
    xCrimperUpPos : BOOL;               // Crimper in UP position

    // Water Bath Inputs
    xCanAtWaterBath : BOOL;             // Can entering water bath
    xLeakDetectedSonic : BOOL;          // Ultrasonic bubble detection in water bath
    rBathTemperature : REAL;            // Water bath temperature
END_VAR

VAR_OUTPUT
    // Actuators
    xGasValve1 : BOOL;                  // Propellant Stage 1 Valve
    xGasValve2 : BOOL;                  // Propellant Stage 2 Valve
    xShakerMotor : BOOL;                // Shaker agitation motor
    xCrimpSolenoid : BOOL;              // Fire crimper mechanism
    xBathConveyorRun : BOOL;            // Run water bath conveyor

    // Reject Mechanisms
    xRejectGasser : BOOL;               // Reject due to improper gas fill
    xRejectCrimper : BOOL;              // Reject due to out of spec crimp depth
    xRejectBath : BOOL;                 // Reject due to leak detected

    // Status / HMI
    xSystemReady : BOOL;
    xMajorFault : BOOL;
    iGasserStep : INT;
    iCrimperStep : INT;
    rAvgCrimpDepth : REAL;
END_VAR

VAR
    // Timers
    tonGasserS1 : TON;                  // Stage 1 Gassing Timer
    tonGasserS2 : TON;                  // Stage 2 Gassing Timer
    tonShaker : TON;                    // Shaker Agitation Timer
    tonCrimpDwell : TON;                // Crimp Dwell Timer
    tonBathTransit : TON;               // Bath Transit tracking timer

    // Settings
    rTargetGasPress : REAL := 12.0;     // Target pressure in Bar
    rMaxGasPressDev : REAL := 0.5;      // Max allowed deviation
    rTargetCrimpDepth : REAL := 5.00;   // Target depth in mm
    rCrimpTolerance : REAL := 0.15;     // Acceptable depth tolerance +/- mm
    tGasserS1Time : TIME := T#500MS;
    tGasserS2Time : TIME := T#800MS;
    tShakerTime : TIME := T#1500MS;
    tCrimpDwellTime : TIME := T#250MS;

    // State variables
    xGasPressOk : BOOL;
    xDepthOk : BOOL;
    rCrimpDepthFiltered : REAL;
    aDepthHistory : ARRAY[1..10] OF REAL;
    iDepthIdx : INT := 1;
    i : INT;
    rSum : REAL;
END_VAR

// =========================================================================
// Safety & System Interlocks
// =========================================================================
IF NOT xEstopOk THEN
    xGasValve1 := FALSE;
    xGasValve2 := FALSE;
    xShakerMotor := FALSE;
    xCrimpSolenoid := FALSE;
    xBathConveyorRun := FALSE;
    xMajorFault := TRUE;
    xSystemReady := FALSE;
    iGasserStep := 0;
    iCrimperStep := 0;
    RETURN;
END_IF;

xSystemReady := TRUE;
xMajorFault := FALSE;

// =========================================================================
// Propellant Gas Pressure Check
// =========================================================================
xGasPressOk := ABS(rGasManifoldPressure - rTargetGasPress) <= rMaxGasPressDev;
IF NOT xGasPressOk AND xSystemStart THEN
    xMajorFault := TRUE;
END_IF;

// =========================================================================
// GASSER & SHAKER MANIFOLD STAGING
// =========================================================================
CASE iGasserStep OF
    0: // Idle / Wait for Can
        xGasValve1 := FALSE;
        xGasValve2 := FALSE;
        xShakerMotor := FALSE;
        xRejectGasser := FALSE;
        IF xSystemStart AND xCanAtGasser AND xGasPressOk THEN
            iGasserStep := 10;
        END_IF;

    10: // Stage 1 Gassing
        xGasValve1 := TRUE;
        tonGasserS1(IN:= TRUE, PT:= tGasserS1Time);
        IF tonGasserS1.Q THEN
            xGasValve1 := FALSE;
            tonGasserS1(IN:= FALSE);
            iGasserStep := 20;
        END_IF;

    20: // Shaker Agitation & Stage 2 Gassing
        xShakerMotor := TRUE;
        xGasValve2 := TRUE;
        tonShaker(IN:= TRUE, PT:= tShakerTime);
        tonGasserS2(IN:= TRUE, PT:= tGasserS2Time);

        IF tonGasserS2.Q THEN
            xGasValve2 := FALSE;
        END_IF;

        IF tonShaker.Q THEN
            xShakerMotor := FALSE;
            tonShaker(IN:= FALSE);
            tonGasserS2(IN:= FALSE);
            iGasserStep := 30;
        END_IF;

    30: // Verification & Complete
        IF rGasManifoldPressure < (rTargetGasPress - 1.0) THEN
            xRejectGasser := TRUE;
        END_IF;
        IF NOT xCanAtGasser THEN
            iGasserStep := 0; // Reset for next can
        END_IF;
END_CASE;

// =========================================================================
// CRIMP COLLET DEPTH TRACKING
// =========================================================================
// Filter the raw crimp depth signal (simple moving average for stability)
aDepthHistory[iDepthIdx] := rCrimpColletDepthRaw;
iDepthIdx := iDepthIdx + 1;
IF iDepthIdx > 10 THEN iDepthIdx := 1; END_IF;

rSum := 0.0;
FOR i := 1 TO 10 DO
    rSum := rSum + aDepthHistory[i];
END_FOR;
rCrimpDepthFiltered := rSum / 10.0;
rAvgCrimpDepth := rCrimpDepthFiltered;

CASE iCrimperStep OF
    0: // Wait for Can
        xCrimpSolenoid := FALSE;
        xRejectCrimper := FALSE;
        IF xSystemStart AND xCanAtCrimper AND xCrimperUpPos THEN
            iCrimperStep := 10;
        END_IF;

    10: // Fire Crimp Solenoid
        xCrimpSolenoid := TRUE;
        tonCrimpDwell(IN:= TRUE, PT:= tCrimpDwellTime);
        IF tonCrimpDwell.Q THEN
            xDepthOk := (rCrimpDepthFiltered >= (rTargetCrimpDepth - rCrimpTolerance)) AND 
                        (rCrimpDepthFiltered <= (rTargetCrimpDepth + rCrimpTolerance));

            xCrimpSolenoid := FALSE;
            tonCrimpDwell(IN:= FALSE);
            iCrimperStep := 20;
        END_IF;

    20: // Retract and Evaluate
        IF NOT xDepthOk THEN
            xRejectCrimper := TRUE;
        END_IF;
        IF NOT xCanAtCrimper THEN
            iCrimperStep := 0;
        END_IF;
END_CASE;

// =========================================================================
// WATER BATH LEAK DETECTION
// =========================================================================
IF xSystemStart AND NOT xMajorFault THEN
    xBathConveyorRun := TRUE;
ELSE
    xBathConveyorRun := FALSE;
END_IF;

// Simple tracking of leak detector while can is present
tonBathTransit(IN:= xCanAtWaterBath, PT:= T#5S);
IF xCanAtWaterBath THEN
    IF xLeakDetectedSonic THEN
        xRejectBath := TRUE;
    END_IF;
ELSE
    IF NOT tonBathTransit.IN THEN
        xRejectBath := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
