FUNCTION_BLOCK "GrainSiloControl_Depth"
VERSION : 0.1
   VAR_INPUT 
      DustLevel : Real;
      AugerTorque : Real;
      ZoneTemps : ARRAY[1..4] OF Real;
      DustThreshold : Real := 50.0;
      TorqueLimit : Real := 150.0;
      TempHighLimit : Real := 40.0;
      TempCritLimit : Real := 65.0;
      SystemEnable : Bool;
   END_VAR

   VAR_OUTPUT 
      MistValve : Bool;
      AugerFwd : Bool;
      AugerRev : Bool;
      AerationFan : Bool;
      AlarmJam : Bool;
      AlarmFireHazard : Bool;
   END_VAR

   VAR 
      JamTimer : TON;
      RevTimer : TON;
      AntiJamActive : Bool;
      i : Int;
      MaxTemp : Real;
   END_VAR

BEGIN
    // Temperature Monitoring & Aeration
    #MaxTemp := 0.0;
    FOR #i := 1 TO 4 DO
        IF #ZoneTemps[#i] > #MaxTemp THEN
            #MaxTemp := #ZoneTemps[#i];
        END_IF;
    END_FOR;

    #AlarmFireHazard := (#MaxTemp > #TempCritLimit);
    #AerationFan := #SystemEnable AND (#MaxTemp > #TempHighLimit) AND NOT #AlarmFireHazard;

    // Dust Suppression Control
    #MistValve := #SystemEnable AND (#DustLevel > #DustThreshold) AND NOT #AlarmFireHazard;

    // Auger Anti-Jam Logic
    #JamTimer(IN := #SystemEnable AND (#AugerTorque > #TorqueLimit) AND NOT #AntiJamActive AND NOT #AlarmFireHazard,
              PT := T#2S);

    IF #JamTimer.Q THEN
        #AntiJamActive := TRUE;
    END_IF;

    #RevTimer(IN := #AntiJamActive,
              PT := T#3S);

    IF #RevTimer.Q THEN
        #AntiJamActive := FALSE;
        IF #AugerTorque > #TorqueLimit THEN
            #AlarmJam := TRUE;
        END_IF;
    END_IF;

    IF #SystemEnable AND NOT #AlarmJam AND NOT #AlarmFireHazard THEN
        #AugerFwd := NOT #AntiJamActive;
        #AugerRev := #AntiJamActive;
    ELSE
        #AugerFwd := FALSE;
        #AugerRev := FALSE;
    END_IF;
END_FUNCTION_BLOCK
