FUNCTION_BLOCK FB_LunarISRU_MicrowavePaver
(*
    ================================================================================
    Title: Lunar ISRU Microwave Sintering Paving Robot Controller
    Author: Lumina Elite Synthetic Data Architect
    Date: 2026-08-22
    Target: Lunar Base Megaproject - In-Situ Resource Utilization
    Description:
    Controls a 50kW, 2.45GHz magnetron array and crawler platform to melt lunar 
    basalt regolith into continuous landing pad tiles. Uses IR pyrometer feedback 
    to maintain a 1,200 deg C melt-pool temperature by modulating rover velocity 
    and magnetron power. Manages active ammonia heat-pipe circulation for thermal 
    rejection in vacuum. PackML state machine integrated.
    ================================================================================
*)

VAR_INPUT
    bEnable                 : BOOL;         (* Enable automated paving *)
    bStart                  : BOOL;         (* Start sequence *)
    bStop                   : BOOL;         (* Stop sequence *)
    bEstop                  : BOOL;         (* Emergency Stop *)
    bReset                  : BOOL;         (* Reset faults *)

    // Sensor Feedbacks
    fActMeltTemp            : LREAL;        (* Actual melt-pool temp (deg C) from IR pyrometer *)
    fActRoverVel            : LREAL;        (* Actual forward velocity (m/s) *)
    fActMagnetronTemp       : LREAL;        (* Magnetron array temp (deg C) *)
    fActRadiatorTemp        : LREAL;        (* Radiator temp (deg C) *)
    fActRegolithDepth       : LREAL;        (* Processed regolith depth (m) *)

    // Setpoints
    fSetpointMeltTemp       : LREAL := 1200.0;  (* Target vitrification temp (deg C) *)
    fMaxMagnetronPower      : LREAL := 50000.0; (* 50kW max magnetron power (W) *)
    fMaxRoverVel            : LREAL := 0.05;    (* Maximum crawler speed (m/s) *)
    fRadiatorTargetTemp     : LREAL := 20.0;    (* Target coolant temp (deg C) *)
END_VAR

VAR_OUTPUT
    // Actuator Commands
    fCmdMagnetronPower      : LREAL;        (* Commanded magnetron RF power (W) *)
    fCmdRoverVel            : LREAL;        (* Commanded forward velocity (m/s) *)
    fCmdAmmoniaPumpSpd      : LREAL;        (* Heat-pipe circulation pump speed (%) *)

    // PackML State Status
    eCurrentState           : E_PackML_State;   (* Current operating state *)
    bReady                  : BOOL;         (* Paver is ready *)
    bFault                  : BOOL;         (* Fault active *)

    // Process Data
    fTotalEnergyConsumed    : LREAL;        (* Total energy used (J) *)
    fTotalAreaPaved         : LREAL;        (* Total area vitrified (m^2) *)
    nPavingStatus           : INT;          (* 0: Idle, 1: Pre-heating, 2: Sintering, 3: Cool-down *)
END_VAR

VAR
    // PackML State Machine
    State                   : E_PackML_State := E_PackML_State.IDLE;

    // PID Controllers
    fbTempPID               : FB_PID_Controller;
    fbThermalMgmtPID        : FB_PID_Controller;

    // Internal Variables
    fDeltaTemp              : LREAL;
    fRoverVelAdj            : LREAL;
    tSinteringTimer         : TON;
    tPreheatTimer           : TON;
    fLastUpdateTime         : LREAL;        (* Simulated time delta (s) *)
    fIntegrationCycle       : LREAL := 0.01;(* 10ms task cycle *)
    bPavedFirstTile         : BOOL := FALSE;

    // Constants
    c_fAmbientLunarTemp     : LREAL := -150.0;  (* Deep space / lunar night temp approx (deg C) *)
    c_fRegolithHeatCap      : LREAL := 800.0;   (* Specific heat capacity of basalt (J/kgK) *)
    c_fPavingWidth          : LREAL := 2.0;     (* Width of the paving array (m) *)
END_VAR

(* 
    ================================================================================
    State Machine Implementation (PackML subset)
    ================================================================================
*)
IF bEstop THEN
    State := E_PackML_State.ABORTED;
END_IF

CASE State OF
    E_PackML_State.IDLE:
        bReady := TRUE;
        bFault := FALSE;
        fCmdMagnetronPower := 0.0;
        fCmdRoverVel := 0.0;
        fCmdAmmoniaPumpSpd := 0.0;
        nPavingStatus := 0;

        IF bStart AND bEnable THEN
            bReady := FALSE;
            State := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        // Initialize systems, prime ammonia pumps
        fCmdAmmoniaPumpSpd := 50.0; 
        IF fActMagnetronTemp < 50.0 THEN
            tPreheatTimer(IN := TRUE, PT := T#5S);
            IF tPreheatTimer.Q THEN
                tPreheatTimer(IN := FALSE);
                State := E_PackML_State.EXECUTE;
            END_IF
        ELSE
            State := E_PackML_State.EXECUTE;
        END_IF

    E_PackML_State.EXECUTE:
        nPavingStatus := 2; // Sintering

        // ---------------------------------------------------------------------
        // 1. Melt-Pool Temperature Control (Magnetron & Velocity Modulation)
        // ---------------------------------------------------------------------
        // PID controls magnetron power based on temperature error
        fbTempPID(
            fSetpoint := fSetpointMeltTemp,
            fActual := fActMeltTemp,
            fKp := 150.5,
            fKi := 10.2,
            fKd := 5.5,
            fCycleTime := fIntegrationCycle,
            fOutput => fCmdMagnetronPower
        );

        // Clamp Power
        IF fCmdMagnetronPower > fMaxMagnetronPower THEN
            fCmdMagnetronPower := fMaxMagnetronPower;
        ELSIF fCmdMagnetronPower < 0.0 THEN
            fCmdMagnetronPower := 0.0;
        END_IF

        // Velocity Adaptation: Slow down if we are below vitrification temperature
        fDeltaTemp := fSetpointMeltTemp - fActMeltTemp;
        IF fDeltaTemp > 50.0 THEN
            // Too cold: decelerate crawler to dump more specific energy
            fRoverVelAdj := fMaxRoverVel * (1.0 - (fDeltaTemp / 200.0));
        ELSE
            // Ideal or hot: proceed at optimal or max speed
            fRoverVelAdj := fMaxRoverVel;
        END_IF

        // Clamp Velocity
        IF fRoverVelAdj < 0.005 THEN
            fCmdRoverVel := 0.005; // Keep moving slowly to prevent cratering
        ELSIF fRoverVelAdj > fMaxRoverVel THEN
            fCmdRoverVel := fMaxRoverVel;
        ELSE
            fCmdRoverVel := fRoverVelAdj;
        END_IF

        // ---------------------------------------------------------------------
        // 2. Active Thermal Vacuum Radiator Management
        // ---------------------------------------------------------------------
        // PID controls ammonia pump speed based on magnetron temperature
        fbThermalMgmtPID(
            fSetpoint := fRadiatorTargetTemp,
            fActual := fActMagnetronTemp,
            fKp := 2.5,
            fKi := 0.1,
            fKd := 0.5,
            fCycleTime := fIntegrationCycle,
            fOutput => fCmdAmmoniaPumpSpd
        );

        // Clamp Pump Speed
        IF fCmdAmmoniaPumpSpd > 100.0 THEN
            fCmdAmmoniaPumpSpd := 100.0;
        ELSIF fCmdAmmoniaPumpSpd < 10.0 THEN
            fCmdAmmoniaPumpSpd := 10.0; // Minimum circulation
        END_IF

        // ---------------------------------------------------------------------
        // 3. Telemetry and Odometry
        // ---------------------------------------------------------------------
        fTotalEnergyConsumed := fTotalEnergyConsumed + (fCmdMagnetronPower * fIntegrationCycle);
        fTotalAreaPaved := fTotalAreaPaved + (fActRoverVel * c_fPavingWidth * fIntegrationCycle);

        IF bStop THEN
            State := E_PackML_State.STOPPING;
        END_IF

    E_PackML_State.STOPPING:
        nPavingStatus := 3; // Cool-down
        fCmdRoverVel := 0.0;
        fCmdMagnetronPower := 0.0;

        // Keep cooling active until magnetron is safe
        IF fActMagnetronTemp < 40.0 THEN
            fCmdAmmoniaPumpSpd := 0.0;
            State := E_PackML_State.IDLE;
        ELSE
            fCmdAmmoniaPumpSpd := 80.0;
        END_IF

    E_PackML_State.ABORTED:
        bFault := TRUE;
        bReady := FALSE;
        fCmdMagnetronPower := 0.0;
        fCmdRoverVel := 0.0;
        fCmdAmmoniaPumpSpd := 100.0; // Max cooling on emergency
        nPavingStatus := 0;

        IF bReset THEN
            State := E_PackML_State.IDLE;
        END_IF

END_CASE

END_FUNCTION_BLOCK
