FUNCTION_BLOCK "CC_Control_With_Profinet_Diag"
VERSION : 0.3
   VAR_INPUT
      Start_Cast : Bool;
      Stop_Cast : Bool;
      Mould_Level_Raw : Real;
      Casting_Speed : Real; 
      Thermocouple_Grid : Array[1..20] of Real;
      Steel_Grade_ID : Int;
      PN_Node_Status : DWord; // Profinet Node Status Word
   END_VAR

   VAR_OUTPUT
      Stopper_Rod_Pos : Real;
      Oscillator_Freq : Real;
      Oscillator_Amp : Real;
      Breakout_Alarm : Bool;
      Spray_Zone_1_Flow : Real;
      Spray_Zone_2_Flow : Real;
      System_Fault : Bool;
      Diag_Code : Int;
      PN_Data_Out : Array[0..7] of Byte; // Profinet transmit buffer
   END_VAR

   VAR_IN_OUT
      PID_Instance : "PID_Compact";
   END_VAR

   VAR
      Cast_Active : Bool;
      Mould_Level_SP : Real := 80.0;
      i : Int;
      Specific_Water_Flow : Real;
   END_VAR

BEGIN
   #System_Fault := FALSE;
   #Diag_Code := 0;
   IF (#PN_Node_Status AND 16#00000001) = 0 THEN 
      #System_Fault := TRUE;
      #Diag_Code := 1001; // Communication loss
   ELSIF #Mould_Level_Raw < 0.0 OR #Mould_Level_Raw > 105.0 THEN
      #System_Fault := TRUE;
      #Diag_Code := 2001; // Sensor out of range
   END_IF;

   IF #System_Fault THEN
      #Cast_Active := FALSE;
      #Stopper_Rod_Pos := 0.0;
      #Oscillator_Freq := 0.0;
      #Spray_Zone_1_Flow := 0.0;
      #Spray_Zone_2_Flow := 0.0;
      RETURN; 
   END_IF;

   IF #Start_Cast AND NOT #Stop_Cast THEN #Cast_Active := TRUE;
   ELSIF #Stop_Cast THEN #Cast_Active := FALSE; END_IF;

   #PID_Instance(Setpoint := #Mould_Level_SP, Input := #Mould_Level_Raw, Reset := NOT #Cast_Active, Output => #Stopper_Rod_Pos);
   IF NOT #Cast_Active THEN #Stopper_Rod_Pos := 0.0; END_IF;

   IF #Cast_Active THEN
      #Oscillator_Freq := #Casting_Speed * 1.5; #Oscillator_Amp := 4.0;
   ELSE
      #Oscillator_Freq := 0.0; #Oscillator_Amp := 0.0;
   END_IF;

   #Breakout_Alarm := FALSE;
   FOR #i := 2 TO 20 DO
      IF (#Thermocouple_Grid[#i] - #Thermocouple_Grid[#i-1]) > 50.0 AND #Cast_Active THEN #Breakout_Alarm := TRUE; END_IF;
   END_FOR;
   IF #Breakout_Alarm THEN #Cast_Active := FALSE; #Stopper_Rod_Pos := 0.0; END_IF;

   CASE #Steel_Grade_ID OF
      1: #Specific_Water_Flow := 1.2;
      2: #Specific_Water_Flow := 0.8;
      ELSE #Specific_Water_Flow := 1.0;
   END_CASE;

   IF #Cast_Active THEN
      #Spray_Zone_1_Flow := #Specific_Water_Flow * #Casting_Speed * 100.0;
      #Spray_Zone_2_Flow := #Specific_Water_Flow * #Casting_Speed * 80.0;
   ELSE
      #Spray_Zone_1_Flow := 0.0; #Spray_Zone_2_Flow := 0.0;
   END_IF;

   #PN_Data_Out[0] := Bool_To_Byte(#Cast_Active);
   #PN_Data_Out[1] := Bool_To_Byte(#Breakout_Alarm);
END_FUNCTION_BLOCK
