Here is the Siemens SCL PID controller expanded with an advanced split-range control sub-system for dual actuators (heating and cooling).

FUNCTION_BLOCK "FB_TempPID_SplitRange"
TITLE = 'Split-Range Temperature PID Controller'
VERSION : '1.1'

VAR_INPUT
    Setpoint : REAL;
    ProcessValue : REAL;
    ManualMode : BOOL;
    ManualHeat : REAL;
    ManualCool : REAL;
    Kp : REAL;
    Ti : REAL;
    Td : REAL;
    Ts : REAL;
    OutMin : REAL := -100.0;
    OutMax : REAL := 100.0;
    Deadband : REAL := 2.0;
END_VAR

VAR_OUTPUT
    HeatValveOut : REAL;
    CoolValveOut : REAL;
END_VAR

VAR
    IntTerm : REAL;
    PrevProcessValue : REAL;
END_VAR

VAR_TEMP
    Error : REAL;
    PropTerm : REAL;
    DerivTerm : REAL;
    RawOutput : REAL;
    DeltaPV : REAL;
END_VAR

BEGIN
    Error := Setpoint - ProcessValue;
    DeltaPV := ProcessValue - PrevProcessValue;

    IF ManualMode THEN
        HeatValveOut := ManualHeat;
        CoolValveOut := ManualCool;
        IF ManualHeat > 0.0 THEN IntTerm := ManualHeat;
        ELSIF ManualCool > 0.0 THEN IntTerm := -ManualCool;
        ELSE IntTerm := 0.0;
        END_IF;
    ELSE
        PropTerm := Kp * Error;

        IF Ti > 0.0 THEN
            IntTerm := IntTerm + ((Kp * Ts) / Ti) * Error;
        END_IF;

        IF IntTerm > OutMax THEN IntTerm := OutMax;
        ELSIF IntTerm < OutMin THEN IntTerm := OutMin;
        END_IF;

        IF Ts > 0.0 THEN
            DerivTerm := - (Kp * Td / Ts) * DeltaPV;
        ELSE
            DerivTerm := 0.0;
        END_IF;

        RawOutput := PropTerm + IntTerm + DerivTerm;

        IF RawOutput > OutMax THEN RawOutput := OutMax;
        ELSIF RawOutput < OutMin THEN RawOutput := OutMin;
        END_IF;

        IF RawOutput > Deadband THEN
            HeatValveOut := RawOutput;
            CoolValveOut := 0.0;
        ELSIF RawOutput < -Deadband THEN
            HeatValveOut := 0.0;
            CoolValveOut := ABS(RawOutput);
        ELSE
            HeatValveOut := 0.0;
            CoolValveOut := 0.0;
        END_IF;
    END_IF;

    PrevProcessValue := ProcessValue;
END_FUNCTION_BLOCK
