FUNCTION_BLOCK FB_SlotDieCoating_AdvancedControl
TITLE = 'Lithium-ion Battery Electrode Double-Sided Slot-Die Coating'
// ==============================================================================
// Description:
// Controls double-sided slot-die coating processes for lithium-ion battery 
// electrodes. Manages slurry delivery (pump speed), fluid meniscus stability 
// via vacuum box pressure, backing roll gap, and web tension across the 
// flotation dryer. Incorporates beta-gauge area weight feedback for precise 
// closed-loop control.
// ==============================================================================

VAR_INPUT
    // Main Line Parameters
    rLineSpeed_m_min         : REAL;   // Current web line speed in m/min
    bRunCoating              : BOOL;   // Coating enable command

    // Beta-Gauge Area Weight Feedback (g/m^2)
    rBetaGauge_Top_g_m2      : REAL;   // Measured area weight Top
    rBetaGauge_Bot_g_m2      : REAL;   // Measured area weight Bottom
    rTargetWeight_Top_g_m2   : REAL;   // Target area weight Top
    rTargetWeight_Bot_g_m2   : REAL;   // Target area weight Bottom

    // Gap and Meniscus Sensors
    rGap_Top_um              : REAL;   // Measured gap Top die in micrometers
    rGap_Bot_um              : REAL;   // Measured gap Bottom die in micrometers
    rVacuum_Actual_Pa        : REAL;   // Vacuum box actual pressure in Pascal

    // Flotation Dryer Tension
    rTension_Actual_N        : REAL;   // Load cell tension feedback in Newtons
    rTension_Target_N        : REAL;   // Target web tension in Newtons

    // Slurry Properties
    rSlurryViscosity_mPas    : REAL;   // Slurry dynamic viscosity
    rSlurryDensity_kg_m3     : REAL;   // Slurry density

    // Control Tuning (PID Parameters)
    rKp_Weight               : REAL := 0.5;
    rKi_Weight               : REAL := 0.01;
    rKp_Vacuum               : REAL := 1.2;
    rKi_Vacuum               : REAL := 0.05;
    rKp_Tension              : REAL := 2.0;
    rKi_Tension              : REAL := 0.1;
END_VAR

VAR_OUTPUT
    // Actuator Commands
    rPumpSpeedCmd_Top_rpm    : REAL;   // Target speed for Top slurry pump
    rPumpSpeedCmd_Bot_rpm    : REAL;   // Target speed for Bottom slurry pump
    rVacuumFanCmd_Hz         : REAL;   // Target frequency for vacuum box exhaust fan
    rGapServoCmd_Top_um      : REAL;   // Position command for Top die gap servo
    rGapServoCmd_Bot_um      : REAL;   // Position command for Bottom die gap servo
    rDryerDriveCmd_Torque    : REAL;   // Torque command for flotation dryer drive

    // System Status
    bMeniscusStable          : BOOL;   // Flag indicating meniscus vacuum is within bounds
    bWeightInTol             : BOOL;   // Flag indicating area weight is within tolerance
    bTensionStable           : BOOL;   // Flag indicating tension is stable
    bSystemAlarm             : BOOL;   // General fault alarm
    iAlarmCode               : INT;    // Specific fault code
END_VAR

VAR
    // Internal State Variables for PIDs
    rWeightError_Top         : REAL;
    rWeightError_Bot         : REAL;
    rWeightIntegral_Top      : REAL;
    rWeightIntegral_Bot      : REAL;

    rVacuumError             : REAL;
    rVacuumIntegral          : REAL;
    rVacuumTarget_Pa         : REAL;

    rTensionError            : REAL;
    rTensionIntegral         : REAL;

    // Feedforward Calculations
    rBasePumpSpeed_Top       : REAL;
    rBasePumpSpeed_Bot       : REAL;

    // Internal Timers
    tCoatingActiveTimer      : TON;
    tFaultTimer              : TON;

    // Constants
    rMAX_PUMP_RPM            : REAL := 150.0;
    rMAX_VACUUM_HZ           : REAL := 60.0;
    rMAX_TORQUE_NM           : REAL := 250.0;
    rCOATING_WIDTH_M         : REAL := 0.65; // 650mm coating width
END_VAR

// ==============================================================================
// IMPLEMENTATION LOGIC
// ==============================================================================

// 1. Coating Enable Timer
tCoatingActiveTimer(IN := bRunCoating, PT := T#2S);

IF NOT bRunCoating THEN
    // Reset outputs if coating is stopped
    rPumpSpeedCmd_Top_rpm := 0.0;
    rPumpSpeedCmd_Bot_rpm := 0.0;
    rVacuumFanCmd_Hz := 0.0;
    rDryerDriveCmd_Torque := 0.0;
    rWeightIntegral_Top := 0.0;
    rWeightIntegral_Bot := 0.0;
    rVacuumIntegral := 0.0;
    rTensionIntegral := 0.0;
    bSystemAlarm := FALSE;
    iAlarmCode := 0;
    RETURN;
END_IF;

// 2. Feedforward Calculation for Slurry Pumps based on Line Speed and Target Weight
// Volume Flow (m3/min) = Line Speed (m/min) * Width (m) * Thickness (m)
// Conversion uses Density (kg/m3) and Area Weight (g/m2)
IF rLineSpeed_m_min > 0.0 THEN
    rBasePumpSpeed_Top := (rTargetWeight_Top_g_m2 * rCOATING_WIDTH_M * rLineSpeed_m_min) / (rSlurryDensity_kg_m3 * 1.0); 
    rBasePumpSpeed_Bot := (rTargetWeight_Bot_g_m2 * rCOATING_WIDTH_M * rLineSpeed_m_min) / (rSlurryDensity_kg_m3 * 1.0);
ELSE
    rBasePumpSpeed_Top := 0.0;
    rBasePumpSpeed_Bot := 0.0;
END_IF;

// 3. Area Weight PID Feedback Control
rWeightError_Top := rTargetWeight_Top_g_m2 - rBetaGauge_Top_g_m2;
rWeightError_Bot := rTargetWeight_Bot_g_m2 - rBetaGauge_Bot_g_m2;

// Anti-windup bounds for integrals
rWeightIntegral_Top := LIMIT(-50.0, rWeightIntegral_Top + rWeightError_Top, 50.0);
rWeightIntegral_Bot := LIMIT(-50.0, rWeightIntegral_Bot + rWeightError_Bot, 50.0);

rPumpSpeedCmd_Top_rpm := LIMIT(0.0, rBasePumpSpeed_Top + (rKp_Weight * rWeightError_Top) + (rKi_Weight * rWeightIntegral_Top), rMAX_PUMP_RPM);
rPumpSpeedCmd_Bot_rpm := LIMIT(0.0, rBasePumpSpeed_Bot + (rKp_Weight * rWeightError_Bot) + (rKi_Weight * rWeightIntegral_Bot), rMAX_PUMP_RPM);

// Status Evaluation
bWeightInTol := ABS(rWeightError_Top) < 2.0 AND ABS(rWeightError_Bot) < 2.0;

// 4. Fluid Meniscus Stability (Vacuum Box Control)
// Vacuum target is dynamically set based on capillary number (line speed & viscosity)
rVacuumTarget_Pa := 150.0 + (rLineSpeed_m_min * 2.5) + (rSlurryViscosity_mPas * 0.1);

rVacuumError := rVacuumTarget_Pa - rVacuum_Actual_Pa;
rVacuumIntegral := LIMIT(-500.0, rVacuumIntegral + rVacuumError, 500.0);

rVacuumFanCmd_Hz := LIMIT(0.0, (rKp_Vacuum * rVacuumError) + (rKi_Vacuum * rVacuumIntegral) + 10.0, rMAX_VACUUM_HZ);

bMeniscusStable := ABS(rVacuumError) < 20.0;

// 5. Gap Servo Adjustment (Simplified Profile Tracking)
// Adjust physical gap based on speed to account for dynamic pressure in the die lip
rGapServoCmd_Top_um := 120.0 + (rLineSpeed_m_min * 0.5); 
rGapServoCmd_Bot_um := 120.0 + (rLineSpeed_m_min * 0.5);

// 6. Flotation Dryer Web Tension PID Control
rTensionError := rTension_Target_N - rTension_Actual_N;
rTensionIntegral := LIMIT(-100.0, rTensionIntegral + rTensionError, 100.0);

rDryerDriveCmd_Torque := LIMIT(0.0, (rKp_Tension * rTensionError) + (rKi_Tension * rTensionIntegral) + (rLineSpeed_m_min * 1.5), rMAX_TORQUE_NM);

bTensionStable := ABS(rTensionError) < 10.0;

// 7. System Alarms and Diagnostics
tFaultTimer(IN := (NOT bWeightInTol OR NOT bMeniscusStable OR NOT bTensionStable) AND tCoatingActiveTimer.Q, PT := T#10S);

IF tFaultTimer.Q THEN
    bSystemAlarm := TRUE;
    IF NOT bMeniscusStable THEN
        iAlarmCode := 101; // Meniscus Blow-Out or Instability
    ELSIF NOT bWeightInTol THEN
        iAlarmCode := 102; // Area Weight Out of Tolerance
    ELSIF NOT bTensionStable THEN
        iAlarmCode := 103; // Web Tension Loss in Dryer
    END_IF;
ELSE
    bSystemAlarm := FALSE;
    iAlarmCode := 0;
END_IF;

END_FUNCTION_BLOCK
