    rCutterSpeed : REAL := 120.0; // Cuts per minute
    rAmmoniaPressureMin : REAL := 1.2; // Min ammonia pressure (bar)
    rAmmoniaPressureMax : REAL := 2.5; // Max ammonia pressure (bar)
    rAirMassFlowSetpt : REAL := 15.0; // Air mass flow (kg/h)

    // Physical Inputs
    rActualCylinderTemp : REAL; 
    rActualAmmoniaPressure : REAL;
    rActualMixFlowRate : REAL;
    rActualAirMassFlow : REAL;
    bCutterHomePosition : BOOL;
    bAmmoniaCompressorRunning : BOOL;
    bMixPumpRunning : BOOL;
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bFreezingActive : BOOL;
    bAirInjectionActive : BOOL;
    bCuttingActive : BOOL;

    // Physical Outputs
    rAmmoniaValvePos : REAL; // 0-100%
    rAirMassFlowValvePos : REAL; // 0-100%
    rCutterServoVelocity : REAL; // RPM
    bMixPumpRun : BOOL;
    rMixPumpSpeed : REAL; // 0-100%

    // Alarms
    bAlarmTempDeviation : BOOL;
    bAlarmOverrunDeviation : BOOL;
    bAlarmAmmoniaPressure : BOOL;
END_VAR

VAR
    rTempError : REAL;
    rTempIntegral : REAL;
    rTempDerivative : REAL;
    rLastTempError : REAL;
    rKpTemp : REAL := 2.5;
    rKiTemp : REAL := 0.1;
    rKdTemp : REAL := 0.5;

    rOverrunError : REAL;
    rOverrunIntegral : REAL;
    rLastOverrunError : REAL;
    rKpOverrun : REAL := 1.2;
    rKiOverrun : REAL := 0.05;

    tUpdateTimer : TON;
    rDeltaT : REAL := 0.1; // 100ms update rate

    eState : (INIT, PRE_CHILL, RUNNING, STOPPING, FAULT);
END_VAR

// Control logic
tUpdateTimer(IN := NOT tUpdateTimer.Q, PT := T#100MS);

IF tUpdateTimer.Q THEN
    CASE eState OF
        INIT:
            bSystemReady := FALSE;
            bFreezingActive := FALSE;
            bAirInjectionActive := FALSE;
            bCuttingActive := FALSE;
            rAmmoniaValvePos := 0.0;
            rAirMassFlowValvePos := 0.0;
            rCutterServoVelocity := 0.0;
            bMixPumpRun := FALSE;
            rMixPumpSpeed := 0.0;

            IF bEnable AND bAmmoniaCompressorRunning THEN
                eState := PRE_CHILL;
            END_IF

        PRE_CHILL:
            // Pre-chill the cylinder before introducing mix
            rTempError := rTargetTemperature - rActualCylinderTemp;
            rAmmoniaValvePos := LIMIT(0.0, rKpTemp * rTempError, 100.0);

            IF ABS(rTempError) < 0.5 THEN
                eState := RUNNING;
                bSystemReady := TRUE;
            END_IF

            IF NOT bEnable THEN
                eState := STOPPING;
            END_IF

        RUNNING:
            bFreezingActive := TRUE;
            bAirInjectionActive := TRUE;
            bCuttingActive := TRUE;
            bMixPumpRun := TRUE;

            // 1. Ammonia Direct Expansion Temperature Control (PID)
            rTempError := rActualCylinderTemp - rTargetTemperature; // Inverse acting
            rTempIntegral := rTempIntegral + (rTempError * rDeltaT);
            rTempDerivative := (rTempError - rLastTempError) / rDeltaT;
            rAmmoniaValvePos := LIMIT(0.0, (rKpTemp * rTempError) + (rKiTemp * rTempIntegral) + (rKdTemp * rTempDerivative), 100.0);
            rLastTempError := rTempError;

            // 2. Overrun Air Mass Flow Control (PI)
            // Target Overrun is ratio of air to mix. Calculate required air mass flow based on actual mix flow rate.
            rOverrunError := rAirMassFlowSetpt - rActualAirMassFlow;
            rOverrunIntegral := rOverrunIntegral + (rOverrunError * rDeltaT);
            rAirMassFlowValvePos := LIMIT(0.0, (rKpOverrun * rOverrunError) + (rKiOverrun * rOverrunIntegral), 100.0);

            // 3. Mix Pump Speed Control (Open Loop / Feedforward)
            rMixPumpSpeed := LIMIT(0.0, (rMixFlowRate / 2000.0) * 100.0, 100.0); // Assuming 2000 L/h max capacity

            // 4. Servo Wire-Cut Slicing
            // Cutter speed in cuts per minute converted to Servo RPM (assuming 1 cut = 1 revolution)
            rCutterServoVelocity := rCutterSpeed; 

            // Alarm Monitoring
            bAlarmTempDeviation := ABS(rActualCylinderTemp - rTargetTemperature) > 2.0;
            bAlarmAmmoniaPressure := rActualAmmoniaPressure < rAmmoniaPressureMin OR rActualAmmoniaPressure > rAmmoniaPressureMax;

            IF bAlarmAmmoniaPressure THEN
                eState := FAULT;
            END_IF

            IF NOT bEnable THEN
                eState := STOPPING;
            END_IF

        STOPPING:
            bSystemReady := FALSE;
            bFreezingActive := FALSE;
            bAirInjectionActive := FALSE;
            bCuttingActive := FALSE;
            bMixPumpRun := FALSE;
            rMixPumpSpeed := 0.0;
            rAirMassFlowValvePos := 0.0;
            rCutterServoVelocity := 0.0;
            rAmmoniaValvePos := 0.0;

            IF NOT bEnable AND rActualCylinderTemp > 0.0 THEN
                eState := INIT;
            END_IF

        FAULT:
            bSystemReady := FALSE;
            bFreezingActive := FALSE;
            bAirInjectionActive := FALSE;
            bCuttingActive := FALSE;
            bMixPumpRun := FALSE;
            rMixPumpSpeed := 0.0;
            rAirMassFlowValvePos := 0.0;
            rCutterServoVelocity := 0.0;
            rAmmoniaValvePos := 0.0;

            IF bEnable AND NOT bAlarmAmmoniaPressure THEN // Reset condition
                eState := INIT;
            END_IF

    END_CASE
END_IF
END_FUNCTION_BLOCK
