FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    rGridVoltage : REAL; // V
    rGridFrequency : REAL; // Hz
    rGridPowerReq : REAL; // kW
    rGridReactiveReq : REAL; // kVAR
    rCoilCurrent : REAL; // A
    rCoilTemp : REAL; // K (Liquid Helium)
    rCryoPressure : REAL; // bar
    bEnable : BOOL;
    bEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    rThyristorAlpha : REAL; // Firing angle (rad)
    rCryoValvePos : REAL; // % open
    rCompressorSpeed : REAL; // rpm
    rActivePowerOutput : REAL; // kW
    rReactivePowerOutput : REAL; // kVAR
    bSystemReady : BOOL;
    bAlarmCryo : BOOL;
    bAlarmCoilQuench : BOOL;
    bFault : BOOL;
END_VAR

VAR
    rNominalTemp : REAL := 4.2; // Nominal liquid helium temp
    rMaxTemp : REAL := 5.0; // Quench threshold
    rCurrentCapacity : REAL := 10000.0;
    rEnergyStored : REAL;
    rAlphaMin : REAL := 0.1745; // 10 degrees
    rAlphaMax : REAL := 2.967; // 170 degrees
    rKp_Cryo : REAL := 15.0;
    rKi_Cryo : REAL := 0.5;
    rCryoErrorAccum : REAL;
    rVoltageError : REAL;
    tStateTimer : TON;
    nState : INT := 0; // 0=Off, 1=Cooling, 2=Charging, 3=Ready, 4=Discharging, 5=Fault
END_VAR

// 1. Safety and Quench Detection
IF bEmergencyStop OR (rCoilTemp > rMaxTemp) THEN
    bFault := TRUE;
    IF rCoilTemp > rMaxTemp THEN
        bAlarmCoilQuench := TRUE;
    END_IF;
    nState := 5;
    rThyristorAlpha := rAlphaMax; // Inverter mode to dump energy quickly if possible, or freewheel
    rCryoValvePos := 100.0; // Max cooling
    rCompressorSpeed := 3000.0;
    bSystemReady := FALSE;
    RETURN;
END_IF;

// 2. Cryogenic Loop Control (Liquid Helium)
// PI Controller for Valve Position
rVoltageError := rCoilTemp - rNominalTemp;
rCryoErrorAccum := rCryoErrorAccum + rVoltageError * 0.1; // Assuming 100ms cycle
IF rCryoErrorAccum > 50.0 THEN rCryoErrorAccum := 50.0; END_IF;
IF rCryoErrorAccum < -50.0 THEN rCryoErrorAccum := -50.0; END_IF;

rCryoValvePos := (rKp_Cryo * rVoltageError) + (rKi_Cryo * rCryoErrorAccum);
IF rCryoValvePos > 100.0 THEN rCryoValvePos := 100.0; END_IF;
IF rCryoValvePos < 0.0 THEN rCryoValvePos := 0.0; END_IF;

// Compressor speed scales with valve position
rCompressorSpeed := 1000.0 + (rCryoValvePos * 20.0);

IF rCoilTemp > 4.5 THEN
    bAlarmCryo := TRUE;
ELSE
    bAlarmCryo := FALSE;
END_IF;

// 3. State Machine & Grid Power Injection
CASE nState OF
    0: // Off
        IF bEnable AND NOT bFault THEN
            nState := 1;
        END_IF;
    1: // Cooling
        IF rCoilTemp <= rNominalTemp THEN
            nState := 2;
        END_IF;
    2: // Charging (Rectifier Mode)
        rThyristorAlpha := rAlphaMin; // Full rectification
        IF rCoilCurrent >= (rCurrentCapacity * 0.95) THEN
            nState := 3;
        END_IF;
    3: // Ready
        rThyristorAlpha := 1.57; // 90 degrees (freewheeling, zero power)
        bSystemReady := TRUE;
        IF rGridPowerReq > 100.0 THEN
            nState := 4;
        END_IF;
    4: // Discharging (Inverter Mode)
        // Calculate firing angle based on power requirement
        rThyristorAlpha := 1.57 + (rGridPowerReq / 10000.0) * 1.39; 
        IF rThyristorAlpha > rAlphaMax THEN rThyristorAlpha := rAlphaMax; END_IF;
        IF rGridPowerReq <= 10.0 OR rCoilCurrent < 500.0 THEN
            nState := 3;
        END_IF;
    5: // Fault
        bSystemReady := FALSE;
        IF NOT bEmergencyStop AND NOT bAlarmCoilQuench THEN
            nState := 0; // Reset
        END_IF;
END_CASE;

// 4. Output calculations
IF nState = 4 THEN
    rActivePowerOutput := rCoilCurrent * rGridVoltage * COS(rThyristorAlpha);
    rReactivePowerOutput := rCoilCurrent * rGridVoltage * SIN(rThyristorAlpha);
ELSE
    rActivePowerOutput := 0.0;
    rReactivePowerOutput := 0.0;
END_IF;

END_FUNCTION_BLOCK\n```
