Here is the advanced SCL program incorporating Profinet IO diagnostics and data mapping. This ensures that fieldbus errors from the dosing valve actuator or the GigE Vision camera are caught immediately, maintaining pharmaceutical data integrity.

TYPE "UDT_Profinet_Diag"
    STRUCT
        Device_Reachable : Bool;
        Port_Link_Up : Bool;
        Hardware_Fault : Bool;
        Comm_Error_Code : Word;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "API_Dosing_Profinet_Diag"
VERSION : 0.1
   VAR_INPUT
      Start_Production : Bool;
      Start_CIP_SIP : Bool;
      Scale_Weight : Real;
      Target_Weight : Real;
      Tolerance : Real;
      Camera_Defect_Detected : Bool;
      Vial_Present : Bool;

      // Profinet Diagnostics Inputs
      PN_DosingValve_Diag : "UDT_Profinet_Diag";
      PN_Camera_Diag : "UDT_Profinet_Diag";
   END_VAR

   VAR_OUTPUT
      Dosing_Valve_Open : Bool;
      Reject_Pusher : Bool;
      Conveyor_Run : Bool;
      CIP_Pump_Run : Bool;
      Steam_Valve_Open : Bool;
      System_Fault : Bool;
      Diagnostic_Alarm_Active : Bool;
   END_VAR

   VAR
      State : Int;
      S_IDLE : Int := 0;
      S_CIP_SIP : Int := 10;
      S_CONVEYOR_MOVE : Int := 20;
      S_DOSING : Int := 21;
      S_INSPECTION : Int := 22;
      S_FAULT : Int := 99;

      System_Sterile : Bool := FALSE;
   END_VAR

BEGIN
    // Comprehensive Profinet Diagnostics Check
    IF NOT PN_DosingValve_Diag.Device_Reachable OR PN_DosingValve_Diag.Hardware_Fault OR 
       NOT PN_Camera_Diag.Device_Reachable OR PN_Camera_Diag.Hardware_Fault THEN
        Diagnostic_Alarm_Active := TRUE;
        State := S_FAULT;
    ELSE
        Diagnostic_Alarm_Active := FALSE;
    END_IF;

    CASE State OF
        S_IDLE:
            IF Start_CIP_SIP THEN
                State := S_CIP_SIP;
            ELSIF Start_Production AND System_Sterile THEN
                State := S_CONVEYOR_MOVE;
            END_IF;

        S_CIP_SIP:
            CIP_Pump_Run := TRUE;
            Steam_Valve_Open := TRUE;
            // Simulated completion
            System_Sterile := TRUE;
            State := S_IDLE;

        S_CONVEYOR_MOVE:
            CIP_Pump_Run := FALSE;
            Steam_Valve_Open := FALSE;
            Conveyor_Run := TRUE;
            IF Vial_Present THEN
                Conveyor_Run := FALSE;
                State := S_DOSING;
            END_IF;

        S_DOSING:
            IF Scale_Weight < Target_Weight THEN
                Dosing_Valve_Open := TRUE;
            ELSE
                Dosing_Valve_Open := FALSE;
                State := S_INSPECTION;
            END_IF;

        S_INSPECTION:
            IF Camera_Defect_Detected OR (ABS(Scale_Weight - Target_Weight) > Tolerance) THEN
                Reject_Pusher := TRUE;
            ELSE
                Reject_Pusher := FALSE;
            END_IF;
            State := S_CONVEYOR_MOVE;

        S_FAULT:
            System_Fault := TRUE;
            Dosing_Valve_Open := FALSE;
            Conveyor_Run := FALSE;
            CIP_Pump_Run := FALSE;
            Steam_Valve_Open := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
