FUNCTION_BLOCK FB_AdvancedBiogasUpgrader
VAR_INPUT
    bEnableSys            : BOOL;     (* Main system enable interlock *)
    bEmergencyStop        : BOOL;     (* E-Stop safety relay OK signal *)
    rRawBiogasFlow        : REAL;     (* Raw biogas inlet flowrate [Nm3/h] *)
    rRawMethaneConc       : REAL;     (* Raw CH4 concentration [% vol] *)
    rRawH2SConc           : REAL;     (* Raw H2S concentration [ppm] *)
    rMembranePress        : REAL;     (* Membrane separation stage pressure [bar] *)
    rPermeateFlow         : REAL;     (* Off-gas permeate flow [Nm3/h] *)
    rProductMethaneConc   : REAL;     (* Final product CH4 purity [% vol] *)
END_VAR
VAR_OUTPUT
    bSystemReady          : BOOL;     (* Upgrading plant ready for processing *)
    bSafetyTrip           : BOOL;     (* Critical safety trip active *)
    bProductOffSpec       : BOOL;     (* Product purity below grid injection threshold *)
    rCompressorSpeedSp    : REAL;     (* Main compressor speed setpoint [RPM] *)
    rRecycleValvePos      : REAL;     (* Tail gas recycle control valve [%] *)
    rH2SDosingPumpSp      : REAL;     (* Biological desulfurization nutrient dosing [L/h] *)
END_VAR
VAR
    iState                : INT := 0; (* Main state machine step *)
    tStartupTimer         : TON;      (* Plant sequence startup timer *)
    tPurgeTimer           : TON;      (* Nitrogen purge timer for safety *)
    tOffSpecTimer         : TON;      (* Delay before tripping on off-spec gas *)
    rInternalCH4Sp        : REAL := 97.5; (* Target CH4 purity for grid injection *)
    rErrorPurity          : REAL;
    rIntegralPurity       : REAL;
    rKp                   : REAL := 2.5;
    rKi                   : REAL := 0.15;
    bInitializeDone       : BOOL;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bSafetyTrip := TRUE;
    iState := 999; (* EMERGENCY SHUTDOWN STATE *)
    rCompressorSpeedSp := 0.0;
    rRecycleValvePos := 100.0; (* Fail-open for safety venting *)
    rH2SDosingPumpSp := 0.0;
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bSafetyTrip := FALSE;
        bProductOffSpec := FALSE;
        rCompressorSpeedSp := 0.0;
        rRecycleValvePos := 0.0;
        IF bEnableSys THEN
            iState := 10;
        END_IF;

    10: (* PURGE SEQUENCE *)
        tPurgeTimer(IN := TRUE, PT := T#30S);
        rRecycleValvePos := 50.0; (* Vent configuration *)
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* COMPRESSOR STARTUP *)
        rCompressorSpeedSp := 1500.0; (* Base startup speed *)
        tStartupTimer(IN := TRUE, PT := T#15S);
        IF tStartupTimer.Q THEN
            tStartupTimer(IN := FALSE);
            IF rMembranePress > 10.0 THEN
                iState := 30;
                bSystemReady := TRUE;
            END_IF;
        END_IF;

    30: (* PRODUCTION RUNNING AND CASCADE PID *)
        (* Biological Desulfurization Feed-Forward Control *)
        IF rRawH2SConc > 500.0 THEN
            rH2SDosingPumpSp := rRawBiogasFlow * 0.02;
        ELSE
            rH2SDosingPumpSp := rRawBiogasFlow * 0.005;
        END_IF;

        (* Methane Purity Cascade Trim PID Control *)
        rErrorPurity := rInternalCH4Sp - rProductMethaneConc;
        rIntegralPurity := rIntegralPurity + (rErrorPurity * 0.1); (* Assuming 100ms cycle time *)

        (* Anti-windup for integral action *)
        IF rIntegralPurity > 50.0 THEN
            rIntegralPurity := 50.0;
        ELSIF rIntegralPurity < -50.0 THEN
            rIntegralPurity := -50.0;
        END_IF;

        rRecycleValvePos := (rErrorPurity * rKp) + (rIntegralPurity * rKi);

        (* Valve saturation limits *)
        IF rRecycleValvePos > 100.0 THEN
            rRecycleValvePos := 100.0;
        ELSIF rRecycleValvePos < 0.0 THEN
            rRecycleValvePos := 0.0;
        END_IF;

        (* Compressor speed mapping based on raw gas feed *)
        rCompressorSpeedSp := 1500.0 + (rRawBiogasFlow * 2.0);
        IF rCompressorSpeedSp > 3000.0 THEN
            rCompressorSpeedSp := 3000.0;
        END_IF;

        (* Off-Spec Detection Logic *)
        IF rProductMethaneConc < 96.0 THEN
            tOffSpecTimer(IN := TRUE, PT := T#10S);
            IF tOffSpecTimer.Q THEN
                bProductOffSpec := TRUE;
            END_IF;
        ELSE
            tOffSpecTimer(IN := FALSE);
            bProductOffSpec := FALSE;
        END_IF;

        (* Shutdown condition *)
        IF NOT bEnableSys THEN
            iState := 40;
        END_IF;

    40: (* CONTROLLED SHUTDOWN *)
        bSystemReady := FALSE;
        rCompressorSpeedSp := rCompressorSpeedSp - 10.0;
        IF rCompressorSpeedSp <= 0.0 THEN
            rCompressorSpeedSp := 0.0;
            iState := 0;
        END_IF;

    999: (* EMERGENCY SHUTDOWN WAIT FOR RESET *)
        IF bEmergencyStop AND NOT bEnableSys THEN
            iState := 0; (* Requires manual reset of enable *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

