FUNCTION_BLOCK FB_AeroponicMistController_Enterprise
TITLE = 'Closed-Loop Aeroponic Mist Controller'
VERSION : '3.2'
AUTHOR : 'Elite Systems Eng'
// Enterprise-grade aeroponic misting, nutrient dosing, and UV-C sterilization

VAR_INPUT
    // Fogger & Environment Inputs
    rTargetDropletSize_um : REAL := 50.0; // Target droplet size in microns
    rCurrentChamberTemp_C : REAL; // Current chamber temperature
    rCurrentChamberHum_RH : REAL; // Current relative humidity

    // Sap-Flow Sensor Inputs (Nutrient Dosing)
    rSapFlowRate_ml_hr    : REAL; // Real-time sap flow in stems
    rNutrientTankLevel_pct: REAL; // Nutrient tank fill level

    // Recirculation Loop Inputs (UV-C Sterilization)
    rWaterRecircFlow_lpm  : REAL; // Flow rate in recirculation loop
    bUVCLampStatus_OK     : BOOL; // True if UV-C lamps are operational

    // System Control
    bEnableController     : BOOL; // Master enable
    bResetErrors          : BOOL; // Acknowledge and reset faults
END_VAR

VAR_OUTPUT
    // Ultrasonic Fogger Control
    rFoggerFreq_kHz       : REAL; // Modulated frequency for foggers
    bFoggerEnable         : BOOL; // Enable fogger activation

    // Nutrient Dosing Pump
    rDosingPumpSpeed_pct  : REAL; // Nutrient dosing speed (0-100%)

    // UV-C Sterilization
    bUVCEnable            : BOOL; // Enable UV-C lamp array

    // Status & Diagnostics
    bSystemHealthy        : BOOL;
    dwErrorCode           : DWORD; // Bitmask of active error codes
    sStatusMessage        : STRING[50];
END_VAR

VAR
    // Internal Timers & Regulators
    tonUVC_DwellTime      : TON; // Dwell time for UV exposure
    tonDosingInterval     : TON; // Continuous dosing cycle timer

    // Process Variables
    rCalculatedFreq       : REAL;
    rRequiredNutrients    : REAL;
    bUVCCycleActive       : BOOL;

    // Constants
    cBaseFreq_kHz         : REAL := 1.7; // Base freq for 50-micron droplet
    cUVC_Dwell_ms         : TIME := T#15S; // 15s standard dwell for sterilization
END_VAR

BEGIN
    // ------------------------------------------------------------------------
    // 1. Error Handling and System State
    // ------------------------------------------------------------------------
    IF bResetErrors THEN
        dwErrorCode := 16#00000000;
        sStatusMessage := 'SYSTEM_NOMINAL';
    END_IF;

    IF NOT bEnableController THEN
        bFoggerEnable := FALSE;
        rDosingPumpSpeed_pct := 0.0;
        bUVCEnable := FALSE;
        rFoggerFreq_kHz := 0.0;
        bSystemHealthy := FALSE;
        sStatusMessage := 'CONTROLLER_DISABLED';
        RETURN;
    END_IF;

    // Fault detection
    IF rNutrientTankLevel_pct < 5.0 THEN
        dwErrorCode := dwErrorCode OR 16#00000001; // Nutrient Low
    END_IF;

    IF NOT bUVCLampStatus_OK THEN
        dwErrorCode := dwErrorCode OR 16#00000002; // UVC Failure
    END_IF;

    bSystemHealthy := (dwErrorCode = 16#00000000);

    // ------------------------------------------------------------------------
    // 2. Ultrasonic Fogger Frequency Modulation (Targeting 50-micron droplet)
    // ------------------------------------------------------------------------
    // Droplet size in ultrasonic atomization is inversely proportional to the 
    // cube root of the square of the frequency.
    // Simplified environmental compensation: frequency tweaks based on temp/humidity
    rCalculatedFreq := cBaseFreq_kHz * (50.0 / rTargetDropletSize_um);

    // Temp/Hum compensation for fogger efficiency
    IF rCurrentChamberTemp_C > 28.0 THEN
        rCalculatedFreq := rCalculatedFreq * 1.05;
    ELSIF rCurrentChamberHum_RH > 95.0 THEN
        rCalculatedFreq := rCalculatedFreq * 0.95;
    END_IF;

    rFoggerFreq_kHz := LIMIT(MN:=1.2, IN:=rCalculatedFreq, MX:=2.5);
    bFoggerEnable   := bSystemHealthy;

    // ------------------------------------------------------------------------
    // 3. Nutrient Dosing Proportional to Sap-Flow
    // ------------------------------------------------------------------------
    // If plants are actively transpiring and sap is flowing, dose proportionally.
    // Flow logic: scale 0-100 ml/hr to 0-100% pump speed.
    IF bSystemHealthy THEN
        rRequiredNutrients := rSapFlowRate_ml_hr * 1.25; // 25% safety margin
        rDosingPumpSpeed_pct := LIMIT(MN:=0.0, IN:=rRequiredNutrients, MX:=100.0);
    ELSE
        rDosingPumpSpeed_pct := 0.0;
    END_IF;

    // ------------------------------------------------------------------------
    // 4. UV-C Sterilization Sequencing
    // ------------------------------------------------------------------------
    // Recirculation flow must meet minimum for effective UV dosage.
    IF rWaterRecircFlow_lpm > 5.0 AND bSystemHealthy THEN
        tonUVC_DwellTime(IN := TRUE, PT := cUVC_Dwell_ms);
        IF tonUVC_DwellTime.Q THEN
            bUVCEnable := TRUE;
            bUVCCycleActive := TRUE;
        END_IF;
    ELSE
        tonUVC_DwellTime(IN := FALSE);
        bUVCEnable := FALSE;
        bUVCCycleActive := FALSE;
    END_IF;

    // Update Status string if healthy
    IF bSystemHealthy THEN
        sStatusMessage := 'AERO_LOOP_ACTIVE';
    END_IF;
END_FUNCTION_BLOCK
