Here is the evolved production-ready IEC 61131-3 implementation for the Deep-Sea ROV Tether Management System (TMS) Controller.

FUNCTION_BLOCK FB_ROV_TMS_Controller
TITLE = 'Deep-Sea ROV Tether Management System Controller'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Data Architect'

// -----------------------------------------------------------------------------
// DESCRIPTION:
// Advanced ROV Tether Management System with:
// 1. Constant-tension active heave compensation (AHC) for 6,000m fiber-optic umbilical.
// 2. Slip-ring optical attenuation monitoring.
// 3. Automated latched/unlatched garage docking sequence in subsea currents.
// -----------------------------------------------------------------------------

VAR_INPUT
    // System Inputs
    bEnableSystem         : BOOL; // Master Enable
    bEmergencyStop        : BOOL; // E-Stop cuts power to all drives immediately

    // AHC & Winch Inputs
    rHeaveVesselPos       : REAL; // Vessel heave position (m) from MRU
    rHeaveVesselVel       : REAL; // Vessel heave velocity (m/s)
    rUmbilicalTension     : REAL; // Current tension measured at sheave (kN)
    rTensionSetpoint      : REAL; // Target tension (kN)
    rWinchEncoderPos      : REAL; // Current length paid out (m)

    // Slip Ring Monitoring
    rOpticalAtten_dB      : REAL; // Current optical attenuation through slip-ring (dB)
    rOpticalAtten_Max_dB  : REAL; // Maximum allowable attenuation before alarm

    // Docking & Environment
    bDockingInitiate      : BOOL; // Initiate garage docking sequence
    rSubseaCurrentVel     : REAL; // Measured subsea current (knots)
    bLatchSensor1         : BOOL; // Primary latch proximity sensor
    bLatchSensor2         : BOOL; // Secondary latch proximity sensor
END_VAR

VAR_OUTPUT
    // Winch Drive Commands
    rWinchVelocityRef     : REAL; // Winch drum velocity setpoint (m/s)
    bWinchBrakeRelease    : BOOL; // Winch brake control

    // TMS Garage Control
    bLatchCommand         : BOOL; // Command to engage mechanical latches
    rDockingThrusterCmd   : REAL; // TMS Thruster compensation for currents

    // Status & Alarms
    bAHC_Active           : BOOL; // AHC is currently compensating
    bDockingComplete      : BOOL; // Garage docking successfully latched
    bAlarmSlipRing        : BOOL; // Critical attenuation in fiber optics
    bAlarmTension         : BOOL; // Tension out of bounds
    sSystemState          : STRING[32]; // Current system state
END_VAR

VAR
    // Internal States
    eTMS_State : (
        STATE_INIT,
        STATE_IDLE,
        STATE_DEPLOYED,
        STATE_AHC_ACTIVE,
        STATE_DOCKING_APPROACH,
        STATE_DOCKING_ALIGN,
        STATE_LATCHING,
        STATE_DOCKED,
        STATE_FAULT
    ) := STATE_INIT;

    // PID Controllers for AHC
    rTensionError         : REAL;
    rIntegralTension      : REAL;
    rDerivativeTension    : REAL;
    rPrevTensionError     : REAL;

    // Tuning parameters
    Kp_Tension : REAL := 2.5;
    Ki_Tension : REAL := 0.5;
    Kd_Tension : REAL := 0.1;

    // Timers
    tDockingTimeout       : TON;
    tLatchDebounce        : TON;
END_VAR

// -----------------------------------------------------------------------------
// MAIN LOGIC
// -----------------------------------------------------------------------------
IF bEmergencyStop THEN
    eTMS_State := STATE_FAULT;
    sSystemState := 'E-STOP / FAULT';
    rWinchVelocityRef := 0.0;
    bWinchBrakeRelease := FALSE;
    bLatchCommand := FALSE;
    bAHC_Active := FALSE;
    RETURN;
END_IF

// Slip Ring Monitoring (Fiber Optic Attenuation)
IF rOpticalAtten_dB >= rOpticalAtten_Max_dB THEN
    bAlarmSlipRing := TRUE;
    // Log attenuation spike, possibly limit winch speed to prevent micro-bending
ELSE
    bAlarmSlipRing := FALSE;
END_IF

// State Machine
CASE eTMS_State OF
    STATE_INIT:
        sSystemState := 'INITIALIZING';
        bWinchBrakeRelease := FALSE;
        IF bEnableSystem THEN
            eTMS_State := STATE_IDLE;
        END_IF

    STATE_IDLE:
        sSystemState := 'IDLE / HOLDING';
        bWinchBrakeRelease := FALSE;
        bAHC_Active := FALSE;
        IF bDockingInitiate THEN
            eTMS_State := STATE_DOCKING_APPROACH;
        ELSIF rWinchEncoderPos > 50.0 AND rTensionSetpoint > 0.0 THEN
            eTMS_State := STATE_AHC_ACTIVE;
        END_IF

    STATE_AHC_ACTIVE:
        sSystemState := 'AHC COMPENSATING';
        bAHC_Active := TRUE;
        bWinchBrakeRelease := TRUE;

        // Active Heave Compensation with Constant Tension
        // Calculate tension error
        rTensionError := rTensionSetpoint - rUmbilicalTension;

        // PI Control for Tension
        rIntegralTension := rIntegralTension + (rTensionError * 0.1); // Assuming 100ms cycle
        rDerivativeTension := (rTensionError - rPrevTensionError) / 0.1;

        // Base winch speed driven by MRU heave velocity + tension correction
        // Feedforward from Vessel Heave
        rWinchVelocityRef := rHeaveVesselVel + 
                             (Kp_Tension * rTensionError) + 
                             (Ki_Tension * rIntegralTension) + 
                             (Kd_Tension * rDerivativeTension);

        rPrevTensionError := rTensionError;

        // Tension Alarm logic
        IF ABS(rTensionError) > (rTensionSetpoint * 0.3) THEN
            bAlarmTension := TRUE;
        ELSE
            bAlarmTension := FALSE;
        END_IF

        IF bDockingInitiate THEN
            bAHC_Active := FALSE;
            eTMS_State := STATE_DOCKING_APPROACH;
        END_IF

    STATE_DOCKING_APPROACH:
        sSystemState := 'DOCKING APPROACH';
        // Haul in umbilical at safe speed
        bWinchBrakeRelease := TRUE;
        rWinchVelocityRef := 0.5; // m/s haul in

        // Compensate for subsea currents using TMS thrusters
        IF rSubseaCurrentVel > 0.5 THEN
            // Oppose current drag on the TMS bullet
            rDockingThrusterCmd := rSubseaCurrentVel * 1.5; 
        ELSE
            rDockingThrusterCmd := 0.0;
        END_IF

        IF rWinchEncoderPos < 10.0 THEN
            eTMS_State := STATE_DOCKING_ALIGN;
        END_IF

    STATE_DOCKING_ALIGN:
        sSystemState := 'DOCKING ALIGNMENT';
        rWinchVelocityRef := 0.1; // Creep speed

        // Check sensors
        IF bLatchSensor1 AND bLatchSensor2 THEN
            eTMS_State := STATE_LATCHING;
        END_IF

        tDockingTimeout(IN:=TRUE, PT:=T#60s);
        IF tDockingTimeout.Q THEN
            eTMS_State := STATE_FAULT; // Failed to align
        END_IF

    STATE_LATCHING:
        sSystemState := 'LATCHING ENGAGED';
        rWinchVelocityRef := 0.0;
        bLatchCommand := TRUE;

        tLatchDebounce(IN:=TRUE, PT:=T#2s);
        IF tLatchDebounce.Q THEN
            bWinchBrakeRelease := FALSE;
            bDockingComplete := TRUE;
            eTMS_State := STATE_DOCKED;
        END_IF

    STATE_DOCKED:
        sSystemState := 'SECURE IN GARAGE';
        bLatchCommand := TRUE;
        bWinchBrakeRelease := FALSE;
        rDockingThrusterCmd := 0.0;

        IF NOT bDockingInitiate THEN
            // Unlatch and deploy
            bLatchCommand := FALSE;
            bDockingComplete := FALSE;
            eTMS_State := STATE_IDLE;
        END_IF

    STATE_FAULT:
        sSystemState := 'FAULT - SAFE HOLD';
        bWinchBrakeRelease := FALSE;
        rWinchVelocityRef := 0.0;
        // Require reset to clear fault
        IF NOT bEmergencyStop AND bEnableSystem THEN
            eTMS_State := STATE_INIT;
        END_IF
END_CASE

END_FUNCTION_BLOCK
