FUNCTION_BLOCK "WetBench_Base"
VAR_INPUT
    bStart_Process : Bool;
    bStop_Process : Bool;
    bWafer_Present : Bool;
    rHF_Flow_SP : Real;
    rRinse_Time_SP : Time;
END_VAR
VAR_OUTPUT
    bHF_Valve : Bool;
    bDI_Valve : Bool;
    bDrain_Valve : Bool;
    bProcess_Complete : Bool;
    iState : Int;
END_VAR
VAR
    tTimer : TON;
END_VAR

BEGIN
    // State Machine
    IF bStop_Process THEN
        iState := 0;
    END_IF;

    CASE iState OF
        0: // Idle
            bHF_Valve := FALSE;
            bDI_Valve := FALSE;
            bDrain_Valve := TRUE;
            bProcess_Complete := FALSE;
            IF bStart_Process AND bWafer_Present THEN
                iState := 10;
                bDrain_Valve := FALSE;
            END_IF;

        10: // HF Dosing
            bHF_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=T#30s);
            IF tTimer.Q THEN
                bHF_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=T#30s);
                iState := 20;
            END_IF;

        20: // DI Rinse
            bDI_Valve := TRUE;
            bDrain_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=rRinse_Time_SP);
            IF tTimer.Q THEN
                bDI_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=rRinse_Time_SP);
                iState := 30;
            END_IF;

        30: // Complete
            bProcess_Complete := TRUE;
            bDrain_Valve := TRUE;
            IF NOT bStart_Process THEN
                iState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
