FUNCTION_BLOCK "CIP_System_Mut1"
VERSION : 0.1
VAR_INPUT
    Start_CIP : Bool;
    Stop_CIP : Bool;
    Conductivity_Raw : Real;
    Temp_Actual : Real;
END_VAR
VAR_OUTPUT
    Pump_Cmd : Bool;
    Valve_Water : Bool;
    Valve_Caustic : Bool;
    Valve_Acid : Bool;
    Valve_Sanitizer : Bool;
    Valve_Drain : Bool;
    Valve_Return : Bool;
    Heater_Cmd : Real;
    State_Status : Int;
END_VAR
VAR
    CIP_State : Int := 0;
    Step_Timer : TON_TIME;
    PID_Ctrl : PID_Compact;
    Setpoint_Temp : Real;
END_VAR
VAR_CONSTANT
    COND_WATER : Real := 0.5;
    COND_CAUSTIC : Real := 50.0;
    COND_ACID : Real := 30.0;
    TEMP_CAUSTIC : Real := 80.0;
    TEMP_ACID : Real := 60.0;
END_VAR

BEGIN
    IF Stop_CIP THEN
        CIP_State := 0;
    END_IF;

    CASE CIP_State OF
        0:
            IF Start_CIP THEN CIP_State := 1; END_IF;
            Setpoint_Temp := 20.0;
        1:
            Valve_Water := TRUE; Valve_Drain := TRUE; Pump_Cmd := TRUE;
            Setpoint_Temp := 25.0;
            IF Conductivity_Raw < COND_WATER THEN CIP_State := 2; END_IF;
        2:
            Valve_Caustic := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            Setpoint_Temp := TEMP_CAUSTIC;
            IF Conductivity_Raw > COND_CAUSTIC AND Temp_Actual >= TEMP_CAUSTIC THEN
                CIP_State := 3;
            END_IF;
        3:
            Valve_Acid := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            Setpoint_Temp := TEMP_ACID;
            IF Conductivity_Raw > COND_ACID AND Temp_Actual >= TEMP_ACID THEN
                CIP_State := 4;
            END_IF;
        4:
            Valve_Sanitizer := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            Setpoint_Temp := 90.0;
            Step_Timer(IN:=TRUE, PT:=T#5M);
            IF Step_Timer.Q THEN CIP_State := 5; END_IF;
        5:
            Pump_Cmd := FALSE;
            IF NOT Start_CIP THEN CIP_State := 0; END_IF;
    END_CASE;

    PID_Ctrl(
        Setpoint := Setpoint_Temp,
        Input := Temp_Actual,
        ManualEnable := FALSE,
        Reset := Stop_CIP,
        Output => Heater_Cmd
    );
END_FUNCTION_BLOCK
