FUNCTION_BLOCK "Escalator_Controller_M1"
VERSION : 0.1
   VAR_INPUT 
      Start_Up : Bool;
      Start_Down : Bool;
      Stop : Bool;
      E_Stop : Bool;
      Step_Sensor_1 : Bool;
      Motor_Speed_RPM : Real;
      Maintenance_Mode : Bool;
      Passenger_Radar : Bool;
   END_VAR

   VAR_OUTPUT 
      Motor_Fwd : Bool;
      Motor_Rev : Bool;
