      Speed_Timer : TON;
      Passenger_Timer : TON;
   END_VAR

BEGIN
    // Safety
    IF "E_Stop" OR "System_Fault" THEN
        "Motor_Fwd" := FALSE;
        "Motor_Rev" := FALSE;
        "Brake_Release" := FALSE;
        "VFD_Speed_Ref" := 0.0;
        "State" := 0;
        RETURN;
