FUNCTION_BLOCK FB_WindTurbine_YawPitchControl
VAR_INPUT
    bEnable                 : BOOL;                 // System enable flag
    bEmergencyStop          : BOOL;                 // Emergency stop from safety relay
    rWindSpeed              : REAL;                 // Filtered wind speed from anemometer (m/s)
    rWindDirection          : REAL;                 // Filtered wind direction relative to north (degrees 0-359.9)
    rNacelleHeading         : REAL;                 // Current nacelle heading relative to north (degrees 0-359.9)
    rRotorSpeed             : REAL;                 // Main shaft rotor speed (RPM)
    rGridPower              : REAL;                 // Active power delivered to grid (kW)
    rHydraulicPressure      : REAL;                 // System hydraulic pressure (bar)
    rBlade1PitchFbk         : REAL;                 // Feedback angle for Blade 1 (degrees)
    rBlade2PitchFbk         : REAL;                 // Feedback angle for Blade 2 (degrees)
    rBlade3PitchFbk         : REAL;                 // Feedback angle for Blade 3 (degrees)
    bGridFault              : BOOL;                 // Grid loss or voltage dip indicator
END_VAR

VAR_OUTPUT
    bYawMotorCW             : BOOL;                 // Command yaw motor clockwise
    bYawMotorCCW            : BOOL;                 // Command yaw motor counter-clockwise
    bYawBrakeEngage         : BOOL;                 // Engage hydraulic yaw brakes
    rBlade1PitchCmd         : REAL;                 // Pitch command for Blade 1 (degrees)
    rBlade2PitchCmd         : REAL;                 // Pitch command for Blade 2 (degrees)
    rBlade3PitchCmd         : REAL;                 // Pitch command for Blade 3 (degrees)
    bHydraulicPumpEnable    : BOOL;                 // Enable main hydraulic pump
    bAerodynamicBrake       : BOOL;                 // Deploy emergency aero brakes
    bSystemFault            : BOOL;                 // General system fault indicator
    iSystemState            : INT;                  // Current state of the control state machine
END_VAR

VAR
    rYawError               : REAL;                 // Difference between wind direction and nacelle heading
    rAbsYawError            : REAL;                 // Absolute value of yaw error
    tYawTimer               : TON;                  // Timer for yaw actuation to prevent hunting
    tPitchTimer             : TON;                  // Timer for pitch actuation rate limit
    rTargetPitch            : REAL;                 // Calculated common target pitch angle
    rPitchRateLimit         : REAL := 5.0;          // Maximum pitch rate (deg/s)
    rYawDeadband            : REAL := 8.0;          // Deadband for yaw error (degrees)
    tYawDelay               : TIME := T#10S;        // Delay before initiating yaw
    iState                  : INT := 0;             // Internal state variable

    // Constants
    rCutInWindSpeed         : REAL := 3.5;
    rRatedWindSpeed         : REAL := 12.0;
    rCutOutWindSpeed        : REAL := 25.0;
    rMaxRotorSpeed          : REAL := 18.0;
    rFinePitchAngle         : REAL := 0.0;
    rFeatheredPitchAngle    : REAL := 90.0;

    // Control variables
    rProportionalGain       : REAL := 2.5;
    rIntegralGain           : REAL := 0.5;
    rSpeedError             : REAL;
    rSpeedIntegral          : REAL;
END_VAR

// 1. Fault Monitoring and Emergency Handling
IF bEmergencyStop OR bGridFault OR (rHydraulicPressure < 120.0) THEN
    bSystemFault := TRUE;
    iState := 99; // Emergency State
END_IF;

// State Machine
CASE iState OF
    0: // INIT / OFF
        bYawMotorCW := FALSE;
        bYawMotorCCW := FALSE;
        bYawBrakeEngage := TRUE;
        bHydraulicPumpEnable := FALSE;
        rTargetPitch := rFeatheredPitchAngle;
        bAerodynamicBrake := FALSE;

        IF bEnable AND NOT bSystemFault THEN
            bHydraulicPumpEnable := TRUE;
            IF rHydraulicPressure > 150.0 THEN
                iState := 1; // Standby
            END_IF;
        END_IF;

    1: // STANDBY
        rTargetPitch := rFeatheredPitchAngle;
        bYawBrakeEngage := TRUE;

        IF rWindSpeed > rCutInWindSpeed AND rWindSpeed < rCutOutWindSpeed THEN
            iState := 2; // Startup
        END_IF;

    2: // STARTUP
        // Gradually decrease pitch to catch the wind
        rTargetPitch := rTargetPitch - 0.1;
        IF rTargetPitch < rFinePitchAngle THEN
            rTargetPitch := rFinePitchAngle;
        END_IF;

        IF rRotorSpeed > 10.0 THEN
            iState := 3; // Power Generation
        END_IF;

    3: // POWER GENERATION (PI Pitch Control & Yaw Control)

        // --- Yaw Control ---
        // Calculate shortest path for yaw error
        rYawError := rWindDirection - rNacelleHeading;
        IF rYawError > 180.0 THEN
            rYawError := rYawError - 360.0;
        ELSIF rYawError < -180.0 THEN
            rYawError := rYawError + 360.0;
        END_IF;

        rAbsYawError := ABS(rYawError);

        tYawTimer(IN := (rAbsYawError > rYawDeadband), PT := tYawDelay);

        IF tYawTimer.Q THEN
            bYawBrakeEngage := FALSE;
            IF rYawError > 0.0 THEN
                bYawMotorCW := TRUE;
                bYawMotorCCW := FALSE;
            ELSE
                bYawMotorCW := FALSE;
                bYawMotorCCW := TRUE;
            END_IF;
        ELSE
            bYawMotorCW := FALSE;
            bYawMotorCCW := FALSE;
            bYawBrakeEngage := TRUE;
        END_IF;

        // --- Pitch Control ---
        IF rWindSpeed >= rRatedWindSpeed THEN
            rSpeedError := rRotorSpeed - rMaxRotorSpeed;
            rSpeedIntegral := rSpeedIntegral + (rSpeedError * 0.1); // Assuming 100ms cycle

            // Anti-windup
            IF rSpeedIntegral > 40.0 THEN rSpeedIntegral := 40.0; END_IF;
            IF rSpeedIntegral < 0.0 THEN rSpeedIntegral := 0.0; END_IF;

            rTargetPitch := (rProportionalGain * rSpeedError) + (rIntegralGain * rSpeedIntegral);

            IF rTargetPitch < rFinePitchAngle THEN rTargetPitch := rFinePitchAngle; END_IF;
            IF rTargetPitch > rFeatheredPitchAngle THEN rTargetPitch := rFeatheredPitchAngle; END_IF;
        ELSE
            rTargetPitch := rFinePitchAngle;
            rSpeedIntegral := 0.0;
        END_IF;

        // --- High Wind Cut-out ---
        IF rWindSpeed > rCutOutWindSpeed THEN
            iState := 4; // High Wind Shutdown
        END_IF;

    4: // HIGH WIND SHUTDOWN
        bYawMotorCW := FALSE;
        bYawMotorCCW := FALSE;
        bYawBrakeEngage := TRUE;
        rTargetPitch := rFeatheredPitchAngle; // Pitch to feather

        IF rRotorSpeed < 2.0 AND rWindSpeed < (rCutOutWindSpeed - 3.0) THEN
            iState := 1; // Return to standby if wind drops
        END_IF;

    99: // EMERGENCY FAULT
        bYawMotorCW := FALSE;
        bYawMotorCCW := FALSE;
        bYawBrakeEngage := TRUE;
        bHydraulicPumpEnable := FALSE;
        rTargetPitch := rFeatheredPitchAngle;
        bAerodynamicBrake := TRUE; // Deploy emergency brakes

        // Require manual reset
        IF NOT bEmergencyStop AND NOT bGridFault AND NOT bEnable THEN
            bSystemFault := FALSE;
            bAerodynamicBrake := FALSE;
            iState := 0;
        END_IF;
END_CASE;

