FUNCTION_BLOCK FB_PaintCuringOvenControl
VAR_INPUT
    bEnable : BOOL; // System enable
    rConveyorSpeed : REAL; // mm/s
    rZone1_TempSetpoint : REAL; // IR Zone 1 Target
    rZone2_TempSetpoint : REAL; // IR Zone 2 Target
    rZone3_TempSetpoint : REAL; // Convection Zone Target
    rAmbientTemp : REAL; // Factory ambient temperature
    rVOC_Concentration : REAL; // Volatile Organic Compounds % LEL
    rExhaustFlowFeedback : REAL; // m3/h
    bEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    rZone1_HeaterCmd : REAL; // 0-100% output to SCR
    rZone2_HeaterCmd : REAL; // 0-100% output to SCR
    rZone3_HeaterCmd : REAL; // 0-100% output to gas burner valve
    rExhaustFanSpeed : REAL; // 0-100% VFD output
    rConveyorVFD : REAL; // 0-100% speed command
    bAlarmHighVOC : BOOL;
    bAlarmOvertemp : BOOL;
    bSystemReady : BOOL;
END_VAR

VAR
    // PID Controllers (Internal)
    pidZone1 : FB_PID;
    pidZone2 : FB_PID;
    pidZone3 : FB_PID;

    // Thermal cascade variables
    rZone1_CascadeSP : REAL;
    rZone2_CascadeSP : REAL;

    // Timers
    tonDwellTime : TON;
    tonExhaustPurge : TON;

    // State machine
    eState : INT;

    // Internal calculations
    rCalculatedDwellTime : REAL;
    rRequiredExhaustFlow : REAL;
    bPurgeComplete : BOOL;
END_VAR

VAR CONSTANT
    INIT : INT := 0;
    PURGE : INT := 1;
    WARMUP : INT := 2;
    RUNNING : INT := 3;
    COOLDOWN : INT := 4;
    FAULT : INT := 5;
END_VAR

// -----------------------------------------------------------------------------
// IMPLEMENTATION
// -----------------------------------------------------------------------------

IF bEmergencyStop THEN
    eState := FAULT;
END_IF;

// VOC Safety Override
IF rVOC_Concentration > 40.0 THEN // > 40% LEL is dangerous
    bAlarmHighVOC := TRUE;
    rRequiredExhaustFlow := 10000.0; // Max flow
    rExhaustFanSpeed := 100.0;
    // Cut heat
    rZone1_HeaterCmd := 0.0;
    rZone2_HeaterCmd := 0.0;
    rZone3_HeaterCmd := 0.0;
ELSE
    bAlarmHighVOC := FALSE;
END_IF;

// State Machine
CASE eState OF
    INIT:
        rZone1_HeaterCmd := 0.0;
        rZone2_HeaterCmd := 0.0;
        rZone3_HeaterCmd := 0.0;
        rExhaustFanSpeed := 0.0;
        rConveyorVFD := 0.0;
        bSystemReady := FALSE;
        IF bEnable AND NOT bEmergencyStop THEN
            eState := PURGE;
        END_IF;

    PURGE:
        // OSHA standard requires 4 volume changes before ignition
        rExhaustFanSpeed := 80.0; // Purge speed
        tonExhaustPurge(IN := TRUE, PT := T#5M);
        IF tonExhaustPurge.Q THEN
            tonExhaustPurge(IN := FALSE); // Reset
            eState := WARMUP;
        END_IF;

    WARMUP:
        // Thermal cascade - IR zones ramp up first
        rZone1_CascadeSP := rZone1_TempSetpoint * 0.5;
        rZone2_CascadeSP := rZone2_TempSetpoint * 0.5;
        rExhaustFanSpeed := 30.0; // Minimum safe flow

        // PID logic execution
        // pidZone1(rSetpoint := rZone1_TempSetpoint, rFeedback := rAmbientTemp); // Mock feedback
        // rZone1_HeaterCmd := pidZone1.rOutput;
        rZone1_HeaterCmd := 50.0; // mock output

        // Check warmup complete
        // IF (pidZone1.rFeedback > (rZone1_TempSetpoint - 5.0)) THEN
            eState := RUNNING;
        // END_IF;

    RUNNING:
        bSystemReady := TRUE;

        // Calculate dynamic dwell time based on conveyor speed
        // Assuming oven length is 20,000 mm
        IF rConveyorSpeed > 0.0 THEN
            rCalculatedDwellTime := 20000.0 / rConveyorSpeed;
        ELSE
            rCalculatedDwellTime := 0.0;
        END_IF;

        // VOC tracking for dynamic exhaust
        rRequiredExhaustFlow := 2000.0 + (rVOC_Concentration * 150.0);
        IF rRequiredExhaustFlow > 10000.0 THEN rRequiredExhaustFlow := 10000.0; END_IF;
        rExhaustFanSpeed := (rRequiredExhaustFlow / 10000.0) * 100.0;

        // IR and Convection PID Updates
        // pidZone1(rSetpoint := rZone1_TempSetpoint);
        // pidZone2(rSetpoint := rZone2_TempSetpoint);
        // pidZone3(rSetpoint := rZone3_TempSetpoint);

        // rZone1_HeaterCmd := pidZone1.rOutput;
        // rZone2_HeaterCmd := pidZone2.rOutput;
        // rZone3_HeaterCmd := pidZone3.rOutput;

        IF NOT bEnable THEN
            eState := COOLDOWN;
        END_IF;

    COOLDOWN:
        bSystemReady := FALSE;
        rZone1_HeaterCmd := 0.0;
        rZone2_HeaterCmd := 0.0;
        rZone3_HeaterCmd := 0.0;
        rExhaustFanSpeed := 50.0; // Keep exhaust on to remove residual heat
        // Add timer or temp check here to transition to INIT
        eState := INIT;

    FAULT:
        rZone1_HeaterCmd := 0.0;
        rZone2_HeaterCmd := 0.0;
        rZone3_HeaterCmd := 0.0;
        rConveyorVFD := 0.0;
        bSystemReady := FALSE;
        // Require reset logic to exit
        IF NOT bEmergencyStop THEN
            eState := INIT;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
