FUNCTION_BLOCK FB_VerticalFarming_Control
VAR_INPUT
    rTempSensors : ARRAY[1..10] OF REAL; // Zone temperatures
    rHumiditySensors : ARRAY[1..10] OF REAL; // Zone humidity levels
    rNutrientEC : REAL; // Current electrical conductivity
    rNutrientPH : REAL; // Current pH level
    rWaterLevel : REAL; // Reservoir water level
    bDayCycle : BOOL; // True for day cycle, false for night
    rTargetTempDay : REAL := 24.0;
    rTargetTempNight : REAL := 18.0;
    rTargetHumidity : REAL := 60.0;
    rTargetEC : REAL := 1.8;
    rTargetPH : REAL := 6.0;
    rFlowRate : REAL; // Current flow rate of nutrient mix
    xEmergencyStop : BOOL;
END_VAR

VAR_OUTPUT
    rHVAC_Cooling_Valve : REAL; // 0-100%
    rHVAC_Heating_Valve : REAL; // 0-100%
    bDehumidifier_Enable : BOOL;
    bHumidifier_Enable : BOOL;
    rNutrientPump_A : REAL; // Part A nutrient dosing speed
    rNutrientPump_B : REAL; // Part B nutrient dosing speed
    rPHPump_Up : REAL; // pH Up dosing
    rPHPump_Down : REAL; // pH Down dosing
    bMainCirculationPump : BOOL;
    bLED_Red_PWM : REAL; // 0-100%
    bLED_Blue_PWM : REAL; // 0-100%
    bLED_White_PWM : REAL; // 0-100%
    bLED_UV_PWM : REAL; // 0-100%
    bAlarm_EC_Out_Of_Range : BOOL;
    bAlarm_PH_Out_Of_Range : BOOL;
    bAlarm_LowWater : BOOL;
END_VAR

VAR
    rAvgTemp : REAL;
    rAvgHumidity : REAL;
    i : INT;

    // PID for EC
    rErrorEC : REAL;
    rIntegralEC : REAL;
    rDerivativeEC : REAL;
    rPrevErrorEC : REAL;

    // PID for PH
    rErrorPH : REAL;
    rIntegralPH : REAL;
    rDerivativePH : REAL;
    rPrevErrorPH : REAL;

    // PID Parameters
    Kp_EC : REAL := 50.0; Ki_EC : REAL := 0.5; Kd_EC : REAL := 0.1;
    Kp_PH : REAL := 40.0; Ki_PH : REAL := 0.2; Kd_PH : REAL := 0.05;

    // Internal States
    rCurrentTargetTemp : REAL;
    tTimer : TON;
    xInit : BOOL := FALSE;
END_VAR

// Initialization
IF NOT xInit THEN
    rIntegralEC := 0.0;
    rIntegralPH := 0.0;
    xInit := TRUE;
END_IF

// Calculate Averages
rAvgTemp := 0.0;
rAvgHumidity := 0.0;
FOR i := 1 TO 10 DO
    rAvgTemp := rAvgTemp + rTempSensors[i];
    rAvgHumidity := rAvgHumidity + rHumiditySensors[i];
END_FOR
rAvgTemp := rAvgTemp / 10.0;
rAvgHumidity := rAvgHumidity / 10.0;

// Determine Target Temperature based on Day/Night Cycle
IF bDayCycle THEN
    rCurrentTargetTemp := rTargetTempDay;
    // LED Spectral Shifting Map for Day (Full spectrum with UV for resin production)
    bLED_Red_PWM := 85.0;
    bLED_Blue_PWM := 65.0;
    bLED_White_PWM := 100.0;
    bLED_UV_PWM := 20.0;
ELSE
    rCurrentTargetTemp := rTargetTempNight;
    // LED Spectral Shifting Map for Night (Dark period)
    bLED_Red_PWM := 0.0;
    bLED_Blue_PWM := 0.0;
    bLED_White_PWM := 0.0;
    bLED_UV_PWM := 0.0;
END_IF

// HVAC & Dehumidification Logic
IF rAvgTemp > (rCurrentTargetTemp + 1.0) THEN
    rHVAC_Cooling_Valve := (rAvgTemp - rCurrentTargetTemp) * 10.0; 
    rHVAC_Heating_Valve := 0.0;
ELSIF rAvgTemp < (rCurrentTargetTemp - 1.0) THEN
    rHVAC_Heating_Valve := (rCurrentTargetTemp - rAvgTemp) * 10.0;
    rHVAC_Cooling_Valve := 0.0;
ELSE
    rHVAC_Cooling_Valve := 0.0;
    rHVAC_Heating_Valve := 0.0;
END_IF

// Dehumidification
IF rAvgHumidity > (rTargetHumidity + 5.0) THEN
    bDehumidifier_Enable := TRUE;
    bHumidifier_Enable := FALSE;
ELSIF rAvgHumidity < (rTargetHumidity - 5.0) THEN
    bDehumidifier_Enable := FALSE;
    bHumidifier_Enable := TRUE;
ELSE
    bDehumidifier_Enable := FALSE;
    bHumidifier_Enable := FALSE;
END_IF

// Hydroponic Nutrient Dosing PID
rErrorEC := rTargetEC - rNutrientEC;
rIntegralEC := rIntegralEC + rErrorEC;
rDerivativeEC := rErrorEC - rPrevErrorEC;
rPrevErrorEC := rErrorEC;

IF rErrorEC > 0.0 THEN // Need more nutrients
    rNutrientPump_A := (Kp_EC * rErrorEC) + (Ki_EC * rIntegralEC) + (Kd_EC * rDerivativeEC);
    rNutrientPump_B := rNutrientPump_A; // Equal parts A and B
ELSE
    rNutrientPump_A := 0.0;
    rNutrientPump_B := 0.0;
END_IF

// Limit Outputs
IF rNutrientPump_A > 100.0 THEN rNutrientPump_A := 100.0; END_IF;
IF rNutrientPump_B > 100.0 THEN rNutrientPump_B := 100.0; END_IF;

// pH Dosing PID
rErrorPH := rTargetPH - rNutrientPH;
rIntegralPH := rIntegralPH + rErrorPH;
rDerivativePH := rErrorPH - rPrevErrorPH;
rPrevErrorPH := rErrorPH;

IF rErrorPH > 0.1 THEN // pH is too low, add pH UP
    rPHPump_Up := (Kp_PH * rErrorPH) + (Ki_PH * rIntegralPH) + (Kd_PH * rDerivativePH);
    rPHPump_Down := 0.0;
    IF rPHPump_Up > 100.0 THEN rPHPump_Up := 100.0; END_IF;
ELSIF rErrorPH < -0.1 THEN // pH is too high, add pH DOWN
    rPHPump_Down := (Kp_PH * abs(rErrorPH)) + (Ki_PH * rIntegralPH) + (Kd_PH * abs(rDerivativePH));
    rPHPump_Up := 0.0;
    IF rPHPump_Down > 100.0 THEN rPHPump_Down := 100.0; END_IF;
ELSE
    rPHPump_Up := 0.0;
    rPHPump_Down := 0.0;
END_IF

// Safety and Alarms
IF rWaterLevel < 10.0 THEN
    bAlarm_LowWater := TRUE;
    bMainCirculationPump := FALSE; // Prevent running dry
ELSE
    bAlarm_LowWater := FALSE;
    bMainCirculationPump := TRUE;
END_IF

bAlarm_EC_Out_Of_Range := (rNutrientEC < 0.5) OR (rNutrientEC > 3.0);
bAlarm_PH_Out_Of_Range := (rNutrientPH < 4.0) OR (rNutrientPH > 8.0);

// Emergency Stop override
IF xEmergencyStop THEN
    rHVAC_Cooling_Valve := 0.0;
    rHVAC_Heating_Valve := 0.0;
    bDehumidifier_Enable := FALSE;
    bHumidifier_Enable := FALSE;
    rNutrientPump_A := 0.0;
    rNutrientPump_B := 0.0;
    rPHPump_Up := 0.0;
    rPHPump_Down := 0.0;
    bMainCirculationPump := FALSE;
    bLED_Red_PWM := 0.0;
    bLED_Blue_PWM := 0.0;
    bLED_White_PWM := 0.0;
    bLED_UV_PWM := 0.0;
END_IF

END_FUNCTION_BLOCK
