    rHeaterValve_Bath := 0.0;
    rSolventPump_Speed := 0.0;
    rRoller1_Speed_Out := 0.0;
    rRoller2_Speed_Out := 0.0;
    rHeater_Zone1_Out := 0.0;
    rHeater_Zone2_Out := 0.0;
    rHeater_Zone3_Out := 0.0;
    RETURN;
END_IF;

IF NOT bEnable THEN
    bSystemReady := TRUE;
    sStatusMessage := 'SYSTEM STANDBY';
    RETURN;
END_IF;

// 1. Coagulation Bath Control
fbPID_BathTemp(
    Enable := TRUE,
    SP := rBathTemp_SP,
    PV := rBathTemp_PV,
    Out => rHeaterValve_Bath
);

fbPID_Solvent(
    Enable := TRUE,
    SP := rSolventConc_SP,
    PV := rSolventConc_PV,
    Out => rSolventPump_Speed
);

// 2. Wash/Draw Roller Kinematics & Tension
// The base speed is applied to roller 1. Roller 2 provides the draw ratio.
rRoller1_Speed_Out := rBaseSpeed;
rRoller2_Speed_Out := rBaseSpeed * rDrawRatio_SP;

// Tension trim applied to roller 2 speed to maintain stable fiber web
fbPID_Tension(
    Enable := TRUE,
    SP := rTension_SP,
    PV := rTension_PV
);
// Trim roller 2 speed based on tension control (inverse relationship: faster roller 2 = more tension)
rRoller2_Speed_Out := rRoller2_Speed_Out + fbPID_Tension.Out;

// 3. Multi-Zone Drying Oven Profiling
fbPID_Zone1(Enable := TRUE, SP := rZone1_Temp_SP, PV := rZone1_Temp_PV, Out => rHeater_Zone1_Out);
fbPID_Zone2(Enable := TRUE, SP := rZone2_Temp_SP, PV := rZone2_Temp_PV, Out => rHeater_Zone2_Out);
fbPID_Zone3(Enable := TRUE, SP := rZone3_Temp_SP, PV := rZone3_Temp_PV, Out => rHeater_Zone3_Out);

// Diagnostics & Alarms
bAlarmBathTemp := ABS(rBathTemp_PV - rBathTemp_SP) > 5.0;
bAlarmSolvent := ABS(rSolventConc_PV - rSolventConc_SP) > 2.0;
bAlarmTension := rTension_PV > (rTension_SP * 1.5);

bFaultActive := bAlarmBathTemp OR bAlarmSolvent OR bAlarmTension;

IF bFaultActive THEN
    sStatusMessage := 'PROCESS DEVIATION FAULT';
ELSE
    sStatusMessage := 'RUNNING NORMAL';
END_IF;

END_FUNCTION_BLOCK
