FUNCTION_BLOCK FB_ContinuousPlywoodHotPress
TITLE = 'Continuous Plywood Hot Press Control System'
VERSION : '1.0'

(*
   Description:
   Highly complex control system for a Continuous Plywood Hot Press.
   Manages hydraulic daylight platen position tracking, 
   high-pressure steam distribution for uniform heating,
   and phenolic resin curing thermal profiles across multiple zones.
*)

VAR_INPUT
    bEnable                 : BOOL; // System Enable
    bEmergencyStop          : BOOL; // E-Stop, active low normally but here active high means STOP

    // Hydraulic System
    rTargetThickness        : REAL; // Target plywood thickness in mm
    rActualPosition_Zone1   : REAL; // Platen position Zone 1 (mm)
    rActualPosition_Zone2   : REAL; // Platen position Zone 2 (mm)
    rActualPosition_Zone3   : REAL; // Platen position Zone 3 (mm)
    rHydraulicPressureIn    : REAL; // Main hydraulic line pressure (bar)

    // Steam Distribution System
    rTargetTemperature      : REAL; // Target curing temperature (Celsius)
    rSteamPressureIn        : REAL; // Incoming steam pressure (bar)
    rActualTemp_Zone1       : REAL; // Zone 1 Temperature (Celsius)
    rActualTemp_Zone2       : REAL; // Zone 2 Temperature (Celsius)
    rActualTemp_Zone3       : REAL; // Zone 3 Temperature (Celsius)

    // Line Speed
    rLineSpeedCmd           : REAL; // Desired line speed (m/min)
    rActualLineSpeed        : REAL; // Feedback line speed (m/min)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL; // System is ready and healthy
    bFault                  : BOOL; // System Fault indicator
    iFaultCode              : INT;  // Specific fault code

    // Hydraulic Outputs
    rHydraulicValveCmd_Z1   : REAL; // 0-100% control valve for Zone 1
    rHydraulicValveCmd_Z2   : REAL; // 0-100% control valve for Zone 2
    rHydraulicValveCmd_Z3   : REAL; // 0-100% control valve for Zone 3

    // Steam Distribution Outputs
    rSteamValveCmd_Z1       : REAL; // 0-100% steam valve for Zone 1
    rSteamValveCmd_Z2       : REAL; // 0-100% steam valve for Zone 2
    rSteamValveCmd_Z3       : REAL; // 0-100% steam valve for Zone 3

    // Main Drive
    rDriveSpeedCmd          : REAL; // Commanded speed to drive VFD
END_VAR

VAR
    // PID Controllers for Temperature
    PID_Temp_Z1 : PID_CONTROLLER;
    PID_Temp_Z2 : PID_CONTROLLER;
    PID_Temp_Z3 : PID_CONTROLLER;

    // PID Controllers for Hydraulic Position
    PID_Pos_Z1  : PID_CONTROLLER;
    PID_Pos_Z2  : PID_CONTROLLER;
    PID_Pos_Z3  : PID_CONTROLLER;

    // Internal States
    eState : (INIT, WARMUP, READY, PRESSING, FAULT, STOPPING);
    rResinCureTimer : REAL := 0.0;

    // Parameters
    rTempTolerance : REAL := 2.5; // +/- 2.5 degrees C
    rPosTolerance  : REAL := 0.1; // +/- 0.1 mm
    rMaxHydPressure: REAL := 300.0; // 300 bar max
END_VAR

// -----------------------------------------------------------------------------
// MAIN CONTROL LOGIC
// -----------------------------------------------------------------------------
IF bEmergencyStop THEN
    eState := FAULT;
    iFaultCode := 999;
END_IF;

CASE eState OF
    INIT:
        bSystemReady := FALSE;
        bFault := FALSE;
        iFaultCode := 0;

        rHydraulicValveCmd_Z1 := 0.0;
        rHydraulicValveCmd_Z2 := 0.0;
        rHydraulicValveCmd_Z3 := 0.0;

        rSteamValveCmd_Z1 := 0.0;
        rSteamValveCmd_Z2 := 0.0;
        rSteamValveCmd_Z3 := 0.0;

        rDriveSpeedCmd := 0.0;

        IF bEnable THEN
            eState := WARMUP;
        END_IF;

    WARMUP:
        // Gradually open steam valves to reach target temperature
        PID_Temp_Z1(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone1, Kp := 2.5, Ti := 10.0, Td := 1.0, rOutput => rSteamValveCmd_Z1);
        PID_Temp_Z2(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone2, Kp := 2.5, Ti := 10.0, Td := 1.0, rOutput => rSteamValveCmd_Z2);
        PID_Temp_Z3(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone3, Kp := 2.5, Ti := 10.0, Td := 1.0, rOutput => rSteamValveCmd_Z3);

        IF (ABS(rActualTemp_Zone1 - rTargetTemperature) <= rTempTolerance) AND
           (ABS(rActualTemp_Zone2 - rTargetTemperature) <= rTempTolerance) AND
           (ABS(rActualTemp_Zone3 - rTargetTemperature) <= rTempTolerance) THEN
            eState := READY;
        END_IF;

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF;

    READY:
        bSystemReady := TRUE;

        // Maintain Temperature
        PID_Temp_Z1(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone1, Kp := 1.5, Ti := 15.0, Td := 0.5, rOutput => rSteamValveCmd_Z1);
        PID_Temp_Z2(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone2, Kp := 1.5, Ti := 15.0, Td := 0.5, rOutput => rSteamValveCmd_Z2);
        PID_Temp_Z3(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone3, Kp := 1.5, Ti := 15.0, Td := 0.5, rOutput => rSteamValveCmd_Z3);

        IF bEnable AND (rLineSpeedCmd > 0.0) THEN
            eState := PRESSING;
        END_IF;

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF;

    PRESSING:
        // 1. Thermal Profile Management
        PID_Temp_Z1(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone1, Kp := 3.0, Ti := 8.0, Td := 1.5, rOutput => rSteamValveCmd_Z1);
        PID_Temp_Z2(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone2, Kp := 3.0, Ti := 8.0, Td := 1.5, rOutput => rSteamValveCmd_Z2);
        PID_Temp_Z3(bEnable := TRUE, rSetpoint := rTargetTemperature, rActual := rActualTemp_Zone3, Kp := 3.0, Ti := 8.0, Td := 1.5, rOutput => rSteamValveCmd_Z3);

        // 2. Hydraulic Daylight Platen Position Tracking
        PID_Pos_Z1(bEnable := TRUE, rSetpoint := rTargetThickness, rActual := rActualPosition_Zone1, Kp := 5.0, Ti := 2.0, Td := 0.2, rOutput => rHydraulicValveCmd_Z1);
        PID_Pos_Z2(bEnable := TRUE, rSetpoint := rTargetThickness, rActual := rActualPosition_Zone2, Kp := 5.0, Ti := 2.0, Td := 0.2, rOutput => rHydraulicValveCmd_Z2);
        PID_Pos_Z3(bEnable := TRUE, rSetpoint := rTargetThickness, rActual := rActualPosition_Zone3, Kp := 5.0, Ti := 2.0, Td := 0.2, rOutput => rHydraulicValveCmd_Z3);

        // 3. Line Speed Control
        rDriveSpeedCmd := rLineSpeedCmd;

        // Safety / Interlock Check
        IF rHydraulicPressureIn > rMaxHydPressure THEN
            iFaultCode := 101; // Overpressure fault
            eState := FAULT;
        END_IF;

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF;

    STOPPING:
        bSystemReady := FALSE;
        rDriveSpeedCmd := 0.0;

        // Retract hydraulics
        rHydraulicValveCmd_Z1 := -10.0; // Negative to retract
        rHydraulicValveCmd_Z2 := -10.0;
        rHydraulicValveCmd_Z3 := -10.0;

        // Close Steam
        rSteamValveCmd_Z1 := 0.0;
        rSteamValveCmd_Z2 := 0.0;
        rSteamValveCmd_Z3 := 0.0;

        IF (rActualLineSpeed < 0.1) THEN
            eState := INIT;
        END_IF;

    FAULT:
        bSystemReady := FALSE;
        bFault := TRUE;

        // Fail-safe state
        rDriveSpeedCmd := 0.0;
        rHydraulicValveCmd_Z1 := -50.0; // Fast retract
        rHydraulicValveCmd_Z2 := -50.0;
        rHydraulicValveCmd_Z3 := -50.0;
        rSteamValveCmd_Z1 := 0.0; // Vent / block steam
        rSteamValveCmd_Z2 := 0.0;
        rSteamValveCmd_Z3 := 0.0;

        IF NOT bEmergencyStop AND NOT bEnable THEN
            // Reset required
            eState := INIT;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
