(* 
    ======================================================================================
    BLOCK: FB_SRFCavity_DetuningControl
    DESCRIPTION: Superconducting RF (SRF) Cavity Lorentz Force & Microphonics Detuning Controller
    AUTHOR: Lead Accelerator Controls Physicist
    DATE: 2026-08-22
    VERSION: 1.0.0
    ======================================================================================
*)

FUNCTION_BLOCK FB_SRFCavity_DetuningControl
VAR_INPUT
    bEnable                 : BOOL;   (* Enable detuning controller *)
    fGradient_MVm           : LREAL;  (* Current cavity gradient in MV/m *)
    fPulseTrig              : BOOL;   (* RF Pulse Trigger (1 ms pulse) *)

    (* I/Q baseband signals for detuning extraction *)
    fCavityVoltage_I        : LREAL;
    fCavityVoltage_Q        : LREAL;
    fForwardPower_I         : LREAL;
    fForwardPower_Q         : LREAL;

    (* PackML State Control *)
    eCommand                : E_PackML_Command; 
END_VAR

VAR_OUTPUT
    fPiezoDriveVolt         : LREAL;  (* Feedforward + Feedback voltage to Piezo Tuner (0-200V) *)
    fDetuning_Hz            : LREAL;  (* Extracted Mechanical Detuning (Delta Omega / 2*Pi) *)

    (* PackML Status *)
    eState                  : E_PackML_State;
    bError                  : BOOL;
    nErrorID                : UDINT;
END_VAR

VAR
    (* Lorentz Force Detuning (LFD) Parameters *)
    fKLorentz               : LREAL := -1.0; (* LFD constant [Hz/(MV/m)^2] - Niobium property *)
    fLFD_CompensationDelay  : LREAL := 0.0002; (* 200 us delay for piezo acoustic wave propagation *)

    (* Microphonics Damping Parameters *)
    fMicrophonics_Kp        : LREAL := 0.5;
    fMicrophonics_Ki        : LREAL := 5.0;
    fIntegrator             : LREAL := 0.0;

    (* internal calculation variables *)
    fDeltaOmega             : LREAL;
    fPhaseCavity            : LREAL;
    fPhaseForward           : LREAL;
    fCalculatedLFD_Hz       : LREAL;
    fPiezoFeedforward       : LREAL;
    fPiezoFeedback          : LREAL;

    (* RF Pulse edge detection *)
    rTrigPulse              : R_TRIG;
    fTimeSincePulse         : LREAL;

    (* constants *)
    PI                      : LREAL := 3.14159265358979323846;
    fCavityBandwidth_Hz     : LREAL := 300.0; (* 300 Hz half-bandwidth for QL = 3e6 at 1.3GHz *)
END_VAR

(* 
    ======================================================================================
    PackML State Machine Implementation 
    ======================================================================================
*)
CASE eState OF
    E_PackML_State.STOPPED:
        fPiezoDriveVolt := 0.0;
        fIntegrator := 0.0;
        IF eCommand = E_PackML_Command.START THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        (* Initialization and setup for SRF Control *)
        fIntegrator := 0.0;
        bError := FALSE;
        nErrorID := 0;
        eState := E_PackML_State.EXECUTE;

    E_PackML_State.EXECUTE:
        IF eCommand = E_PackML_Command.STOP THEN
            eState := E_PackML_State.STOPPING;
        ELSIF NOT bEnable THEN
            eState := E_PackML_State.IDLE;
        ELSE
            (* --- 1. Real-time Detuning Extraction (Delta Omega) via I/Q Baseband --- *)
            (* Calculate Phase of Cavity and Forward Power *)
            fPhaseCavity := ATAN2(fCavityVoltage_Q, fCavityVoltage_I);
            fPhaseForward := ATAN2(fForwardPower_Q, fForwardPower_I);

            (* Calculate detuning using the phase derivative approach (simplified steady state here)
               Delta_omega = - bandwidth * tan(PhaseCavity - PhaseForward) 
               Assuming steady state during flat-top for microphonics *)
            fDeltaOmega := -2.0 * PI * fCavityBandwidth_Hz * TAN(fPhaseCavity - fPhaseForward);
            fDetuning_Hz := fDeltaOmega / (2.0 * PI);

            (* --- 2. Lorentz Force Detuning (LFD) Feedforward --- *)
            (* LFD is proportional to the square of the gradient *)
            fCalculatedLFD_Hz := fKLorentz * EXPT(fGradient_MVm, 2);

            rTrigPulse(CLK := fPulseTrig);
            IF rTrigPulse.Q THEN
                fTimeSincePulse := 0.0;
            END_IF;

            (* Predictive Feedforward: Triggered by RF pulse. We map the predicted LFD 
               to a required piezo voltage. Assuming 1V = 1Hz tuning coefficient. *)
            IF fPulseTrig THEN
                (* Feedforward pulse shaped to counteract mechanical deformation *)
                fPiezoFeedforward := -fCalculatedLFD_Hz * 1.0; 
            ELSE
                fPiezoFeedforward := 0.0;
            END_IF

            (* --- 3. Active Microphonics Damping (PI Controller) --- *)
            (* Low frequency < 100 Hz tracking for cryogenic pump vibrations. *)
            fIntegrator := fIntegrator + (fDetuning_Hz * fMicrophonics_Ki * 0.001); (* 1ms sample time assumed *)

            (* Anti-windup limit for integrator *)
            IF fIntegrator > 50.0 THEN fIntegrator := 50.0; END_IF
            IF fIntegrator < -50.0 THEN fIntegrator := -50.0; END_IF

            fPiezoFeedback := (fDetuning_Hz * fMicrophonics_Kp) + fIntegrator;

            (* --- 4. Total Piezo Drive Output --- *)
            (* Combine Feedforward and Feedback, and apply limits (0 - 200V) *)
            fPiezoDriveVolt := fPiezoFeedforward + fPiezoFeedback + 100.0; (* 100V DC bias *)

            IF fPiezoDriveVolt > 200.0 THEN
                fPiezoDriveVolt := 200.0;
            ELSIF fPiezoDriveVolt < 0.0 THEN
                fPiezoDriveVolt := 0.0;
            END_IF

        END_IF

    E_PackML_State.STOPPING:
        fPiezoDriveVolt := 0.0;
        eState := E_PackML_State.STOPPED;

    E_PackML_State.IDLE:
        fPiezoDriveVolt := 0.0;
        IF bEnable THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.ABORTED:
        fPiezoDriveVolt := 0.0;
        fIntegrator := 0.0;
        IF eCommand = E_PackML_Command.CLEAR THEN
            eState := E_PackML_State.STOPPED;
        END_IF

END_CASE

END_FUNCTION_BLOCK
