\nFUNCTION_BLOCK FB_FiberLaserCuttingController
FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Fiber Laser Cutting Main Controller'
VERSION : '2.1'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    bEnable                 : BOOL;   // Master enable
    bStartCut               : BOOL;   // Trigger cut sequence
    rTargetStandoffHeight   : REAL;   // Target capacitive standoff height (mm)
    rMaterialThickness      : REAL;   // Material thickness (mm)
    rFeedRate               : REAL;   // Cutting feed rate (mm/min)
    iAssistGasType          : INT;    // 0=N2, 1=O2, 2=Air
    rActualStandoffHeight   : REAL;   // Feedback from capacitive sensor (mm)
    rLaserPowerReq          : REAL;   // Requested CW laser power (W)
    bEmergencyStop          : BOOL;   // E-Stop signal
END_VAR

VAR_OUTPUT
    bLaserEmissionOn        : BOOL;   // Enable laser emission
    rCommandLaserPower      : REAL;   // Actual power output command (W)
    rGasPressureCmd         : REAL;   // Proportional valve pressure command (bar)
    rZAxisVelocityCmd       : REAL;   // Z-Axis velocity for height control (mm/s)
    iMachineState           : INT;    // Current state (0=Idle, 1=Piercing, 2=Cutting, 3=Fault)
    bFault                  : BOOL;   // Fault indicator
    sFaultMessage           : STRING[100]; // Fault description
END_VAR

VAR
    rKp_Height              : REAL := 5.0;
    rKi_Height              : REAL := 0.2;
    rKd_Height              : REAL := 0.05;
    rHeightError            : REAL;
    rHeightErrorPrev        : REAL;
    rHeightIntegral         : REAL;
    rHeightDerivative       : REAL;
    rPiercingTime           : TIME;
    tPiercingTimer          : TON;
    rBasePressure           : REAL;
    rDynamicPressure        : REAL;
    rLaserModulationFreq    : REAL;
    rDutyCycle              : REAL;
    bInitialize             : BOOL := TRUE;
END_VAR

VAR_TEMP
    rTempPressureLimit      : REAL;
END_VAR

// Initialization
IF bInitialize THEN
    iMachineState := 0;
    bFault := FALSE;
    sFaultMessage := '';
    bInitialize := FALSE;
    bLaserEmissionOn := FALSE;
    rCommandLaserPower := 0.0;
    rGasPressureCmd := 0.0;
    rZAxisVelocityCmd := 0.0;
END_IF;

// E-Stop Handling
IF bEmergencyStop THEN
    iMachineState := 3;
    bFault := TRUE;
    sFaultMessage := 'EMERGENCY STOP ACTIVE';
    bLaserEmissionOn := FALSE;
    rCommandLaserPower := 0.0;
    rGasPressureCmd := 0.0;
    rZAxisVelocityCmd := 0.0;
    RETURN;
END_IF;

// Main State Machine
CASE iMachineState OF
    0: // IDLE
        bLaserEmissionOn := FALSE;
        rCommandLaserPower := 0.0;
        rGasPressureCmd := 0.0;
        rZAxisVelocityCmd := 0.0;

        IF bEnable AND bStartCut AND NOT bFault THEN
            // Calculate piercing parameters based on material thickness
            IF rMaterialThickness < 2.0 THEN
                rPiercingTime := T#500MS;
                rBasePressure := 5.0; // bar
                rLaserModulationFreq := 5000.0; // Hz
                rDutyCycle := 50.0; // %
            ELSIF rMaterialThickness < 10.0 THEN
                rPiercingTime := T#1500MS;
                rBasePressure := 10.0; // bar
                rLaserModulationFreq := 2000.0; // Hz
                rDutyCycle := 80.0; // %
            ELSE
                rPiercingTime := T#3000MS;
                rBasePressure := 15.0; // bar
                rLaserModulationFreq := 1000.0; // Hz
                rDutyCycle := 100.0; // CW Mode
            END_IF;

            iMachineState := 1; // Move to PIERCING
            tPiercingTimer(IN := FALSE); // Reset timer
        END_IF;

    1: // PIERCING
        tPiercingTimer(IN := TRUE, PT := rPiercingTime);
        bLaserEmissionOn := TRUE;

        // Standoff Height Control (PID)
        rHeightError := rTargetStandoffHeight - rActualStandoffHeight;
        rHeightIntegral := rHeightIntegral + rHeightError;
        rHeightDerivative := rHeightError - rHeightErrorPrev;
        rZAxisVelocityCmd := (rKp_Height * rHeightError) + (rKi_Height * rHeightIntegral) + (rKd_Height * rHeightDerivative);
        rHeightErrorPrev := rHeightError;

        // Output piercing power and pressure
        rCommandLaserPower := rLaserPowerReq * (rDutyCycle / 100.0);
        rGasPressureCmd := rBasePressure;

        IF tPiercingTimer.Q THEN
            iMachineState := 2; // Move to CUTTING
        END_IF;

    2: // CUTTING
        IF NOT bStartCut THEN
            iMachineState := 0; // Back to IDLE
        END_IF;

        // Standoff Height Control (PID)
        rHeightError := rTargetStandoffHeight - rActualStandoffHeight;

        // Anti-windup for Integral term
        IF rHeightIntegral > 100.0 THEN rHeightIntegral := 100.0; END_IF;
        IF rHeightIntegral < -100.0 THEN rHeightIntegral := -100.0; END_IF;

        rHeightIntegral := rHeightIntegral + rHeightError;
        rHeightDerivative := rHeightError - rHeightErrorPrev;
        rZAxisVelocityCmd := (rKp_Height * rHeightError) + (rKi_Height * rHeightIntegral) + (rKd_Height * rHeightDerivative);
        rHeightErrorPrev := rHeightError;

        // Dynamic Assist Gas Pressure based on velocity/thickness
        IF iAssistGasType = 0 THEN // N2 (High pressure, clean cut)
            rTempPressureLimit := 25.0;
            rDynamicPressure := rBasePressure + (rFeedRate * 0.001 * rMaterialThickness);
        ELSIF iAssistGasType = 1 THEN // O2 (Low pressure, exothermic)
            rTempPressureLimit := 6.0;
            rDynamicPressure := rBasePressure * 0.5 + (rFeedRate * 0.0001);
        ELSE // Air
            rTempPressureLimit := 15.0;
            rDynamicPressure := rBasePressure * 0.8 + (rFeedRate * 0.0005);
        END_IF;

        // Saturate pressure command
        IF rDynamicPressure > rTempPressureLimit THEN
            rGasPressureCmd := rTempPressureLimit;
        ELSE
            rGasPressureCmd := rDynamicPressure;
        END_IF;

        // Continuous wave power requested during cutting
        bLaserEmissionOn := TRUE;
        rCommandLaserPower := rLaserPowerReq;

    3: // FAULT
        bLaserEmissionOn := FALSE;
        rCommandLaserPower := 0.0;
        rGasPressureCmd := 0.0;
        rZAxisVelocityCmd := 0.0;
        IF NOT bEmergencyStop AND bEnable THEN
            // Reset Fault
            bFault := FALSE;
            sFaultMessage := '';
            iMachineState := 0;
        END_IF;

    ELSE
        iMachineState := 3;
        bFault := TRUE;
        sFaultMessage := 'UNKNOWN STATE';
END_CASE;

