    rSpargeKp : REAL := 1.75;
    rSpargeKi : REAL := 0.02;

    (* Fermenter Glycol parameters *)
    rGlycolKp : REAL := 5.2;
    rGlycolKi : REAL := 0.25;
    rGlycolIntegral : REAL := 0.0;
    rGlycolPrevError : REAL := 0.0;

    (* State Machine *)
    nBrewState : INT := 0; (* 0=IDLE, 1=LAUTERING, 2=BOILING, 3=FERMENTING, 99=ESTOP *)
    rError : REAL;
    rDerivative : REAL;
    rOutput : REAL;
    rCycleTime : REAL := 0.1; (* 100ms cycle time assumption *)
END_VAR

(* -----------------------------------------------------------------------------
   BODY OF FUNCTION BLOCK
   ----------------------------------------------------------------------------- *)

(* Emergency Stop Handling *)
IF bEmergencyStop THEN
    rBoilerSteamValveCmd := 0.0;
    rSpargePumpSpeed := 0.0;
    rGlycolValveCmd := 100.0; (* Fail-safe full cooling on fermenter *)
    sProcessStatus := 'EMERGENCY STOP ACTIVE';
    nBrewState := 99;
    bEStopActive := TRUE;
    RETURN;
ELSE
    bEStopActive := FALSE;
    IF nBrewState = 99 THEN
        nBrewState := 0; (* Reset to IDLE after E-Stop cleared *)
    END_IF;
END_IF;

IF NOT bEnableProcess THEN
    rBoilerSteamValveCmd := 0.0;
    rSpargePumpSpeed := 0.0;
    rGlycolValveCmd := 0.0;
    sProcessStatus := 'Process Disabled - Awaiting Enable';
    nBrewState := 0;
    RETURN;
END_IF;

(* State Machine Logic *)
CASE nBrewState OF
    0: (* IDLE STATE *)
        sProcessStatus := 'IDLE';
        rBoilerSteamValveCmd := 0.0;
        rSpargePumpSpeed := 0.0;
        rGlycolValveCmd := 0.0;

        IF bLauterStart THEN nBrewState := 1; END_IF;
        IF bBoilStart THEN nBrewState := 2; END_IF;
        IF bFermentStart THEN nBrewState := 3; END_IF;

    1: (* LAUTERING & SPARGING STATE *)
        sProcessStatus := 'LAUTERING - PI LEVEL CONTROL ACTIVE';
        rError := rTargetSpargeLevel - rLauterLevel;
        rSpargeIntegral := rSpargeIntegral + (rError * rCycleTime);

        (* PI Control for Sparge VFD *)
        rOutput := (rSpargeKp * rError) + (rSpargeKi * rSpargeIntegral);

        IF rOutput > 100.0 THEN
            rOutput := 100.0;
            rSpargeIntegral := rSpargeIntegral - (rError * rCycleTime); (* Anti-windup *)
        ELSIF rOutput < 0.0 THEN
            rOutput := 0.0;
            rSpargeIntegral := rSpargeIntegral - (rError * rCycleTime);
        END_IF;

        rSpargePumpSpeed := rOutput;

        (* State Transition Check *)
        IF NOT bLauterStart THEN
            rSpargePumpSpeed := 0.0;
            nBrewState := 0;
        END_IF;

    2: (* WORT BOILING STATE *)
        sProcessStatus := 'WORT BOILING - PID THERMAL CASCADE';
        rError := rWortTempSetpoint - rWortTempProcessValue;
        rBoilerIntegral := rBoilerIntegral + (rError * rCycleTime);
        rDerivative := (rError - rBoilerPrevError) / rCycleTime;

        (* Full PID Calculation *)
        rOutput := (rBoilerKp * rError) + (rBoilerKi * rBoilerIntegral) + (rBoilerKd * rDerivative);

        (* Actuator Saturation & Anti-windup *)
        IF rOutput > 100.0 THEN
            rOutput := 100.0;
            rBoilerIntegral := rBoilerIntegral - (rError * rCycleTime);
        ELSIF rOutput < 0.0 THEN
            rOutput := 0.0;
            rBoilerIntegral := rBoilerIntegral - (rError * rCycleTime);
        END_IF;

        rBoilerSteamValveCmd := rOutput;
        rBoilerPrevError := rError;

        (* Alarm Monitoring *)
        IF rWortTempProcessValue > (rWortTempSetpoint + 2.5) THEN
            bAlarmHighTemp := TRUE;
        ELSE
            bAlarmHighTemp := FALSE;
        END_IF;

        (* State Transition Check *)
        IF NOT bBoilStart THEN
            rBoilerSteamValveCmd := 0.0;
            nBrewState := 0;
        END_IF;

    3: (* FERMENTATION GLYCOL CHILLING STATE *)
        sProcessStatus := 'FERMENTATION - REVERSE ACTING GLYCOL CHILLING';
        (* Cooling is reverse acting: Setpoint < Process Value means we need positive error to open valve *)
        rError := rFermenterTemp - rFermenterSetpoint;
        rGlycolIntegral := rGlycolIntegral + (rError * rCycleTime);

        rOutput := (rGlycolKp * rError) + (rGlycolKi * rGlycolIntegral);

        IF rOutput > 100.0 THEN
            rOutput := 100.0;
            rGlycolIntegral := rGlycolIntegral - (rError * rCycleTime);
        ELSIF rOutput < 0.0 THEN
            rOutput := 0.0;
            rGlycolIntegral := rGlycolIntegral - (rError * rCycleTime);
        END_IF;

        rGlycolValveCmd := rOutput;
        rGlycolPrevError := rError;

        IF NOT bFermentStart THEN
            rGlycolValveCmd := 0.0;
            nBrewState := 0;
        END_IF;

    ELSE
        nBrewState := 0; (* Fallback *)
END_CASE;

(* Global Safety Interlocks & Alarms *)
IF rLauterLevel < 100.0 AND nBrewState = 1 THEN
    bAlarmLowLevel := TRUE;
ELSE
    bAlarmLowLevel := FALSE;
END_IF;
END_FUNCTION_BLOCK
