FUNCTION_BLOCK FB_ASU_DistillationControl
VAR_INPUT
    rFeedTemp           : REAL; (* Main air feed temperature (K) *)
    rFeedPress          : REAL; (* Main air feed pressure (bar) *)
    rMainExchangerEff   : REAL; (* Heat exchanger efficiency (0-1) *)
    rArgonDrawFlow      : REAL; (* Argon side-draw flow rate (kg/h) *)
    bTurboTrip          : BOOL; (* Turbo-expander trip signal *)
    bStartSequence      : BOOL;
    bEmergencyStop      : BOOL;
END_VAR
VAR_OUTPUT
    rN2ProductFlow      : REAL;
    rO2ProductFlow      : REAL;
    rTurboSpeedCmd      : REAL;
    rReboilerHeaterCmd  : REAL;
    rRefluxValveCmd     : REAL;
    bSystemStable       : BOOL;
    bAlarmHighPress     : BOOL;
    bAlarmLowTemp       : BOOL;
END_VAR
VAR
    eState              : DINT;
    rInternalTemp       : REAL := 298.15;
    rColumnPress        : REAL := 1.0;
    rArgonPurity        : REAL := 0.0;
    rLiquidLevel        : REAL := 0.0;
    TimerStartup        : TON;
    rTurboTargetSpeed   : REAL := 0.0;
END_VAR

(* Main State Machine for Cryogenic Air Separation *)
IF bEmergencyStop OR bTurboTrip THEN
    eState := 5; (* SAFE_SHUTDOWN *)
END_IF;

CASE eState OF
    0: (* INIT *)
        rN2ProductFlow := 0.0;
        rO2ProductFlow := 0.0;
        rTurboSpeedCmd := 0.0;
        rReboilerHeaterCmd := 0.0;
        rRefluxValveCmd := 0.0;
        bSystemStable := FALSE;
        IF bStartSequence THEN
            eState := 1; (* STARTUP *)
        END_IF;

    1: (* STARTUP *)
        rTurboTargetSpeed := 15000.0; (* RPM *)
        TimerStartup(IN:=TRUE, PT:=T#5M);
        IF TimerStartup.Q THEN
            eState := 2; (* COOLING *)
            TimerStartup(IN:=FALSE);
        END_IF;

    2: (* COOLING *)
        rInternalTemp := rInternalTemp - (rMainExchangerEff * 2.5);
        IF rInternalTemp < 90.0 THEN
            bAlarmLowTemp := TRUE;
        END_IF;

        IF rInternalTemp <= 100.0 THEN
            eState := 3; (* DISTILLATION *)
        END_IF;

    3: (* DISTILLATION *)
        rColumnPress := rFeedPress * 0.85;
        IF rColumnPress > 6.5 THEN
            bAlarmHighPress := TRUE;
        END_IF;

        rN2ProductFlow := rFeedPress * 100.0 * (100.0 / rInternalTemp);
        rO2ProductFlow := rFeedPress * 20.0 * (150.0 / rInternalTemp);
        rReboilerHeaterCmd := 45.5; 

        IF rArgonDrawFlow > 10.0 THEN
            rArgonPurity := 98.5;
        END_IF;

        IF ABS(rN2ProductFlow - 500.0) < 50.0 THEN
            eState := 4; (* STABILIZATION *)
        END_IF;

    4: (* STABILIZATION *)
        bSystemStable := TRUE;
        IF rInternalTemp > 110.0 THEN
            bSystemStable := FALSE;
            eState := 3; (* DISTILLATION *)
        END_IF;

    5: (* SAFE_SHUTDOWN *)
        rTurboSpeedCmd := 0.0;
        rRefluxValveCmd := 0.0;
        rReboilerHeaterCmd := 0.0;
        bSystemStable := FALSE;
        IF NOT bEmergencyStop AND NOT bTurboTrip THEN
            eState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
