FUNCTION_BLOCK FB_FOWT_ActiveBallastHeaveComp
VAR_INPUT
    (* System Enable and Safety Interlocks *)
    bEnableSystem       : BOOL;     (* Main activation command for the active ballast system *)
    bEmergencyStop      : BOOL;     (* Safety loop status (TRUE = Healthy, FALSE = Tripped) *)
    rWavePeriodPred     : REAL;     (* Predicted dominant wave period from 3-axis accelerometer/lidar array (s) *)
    rHeaveAccelZ        : REAL;     (* Real-time Z-axis heave acceleration (m/s^2) *)
    rMooringTension     : ARRAY [1..4] OF REAL; (* Tether tension readings for quadrants 1-4 (kN) *)
    rPontoonLevel       : ARRAY [1..4] OF REAL; (* Pneumatic pontoon fast-flooding levels (%) *)
    rPitchAngle         : REAL;     (* Turbine tower pitch angle from vertical (deg) *)
    rRollAngle          : REAL;     (* Turbine tower roll angle from vertical (deg) *)
END_VAR
VAR_OUTPUT
    (* System Status and Actuation *)
    bSystemReady        : BOOL;     (* Active ballast controller is online and healthy *)
    bPneumaticValveOpen : ARRAY [1..4] OF BOOL; (* High-speed pneumatic valve commands for rapid flooding/venting *)
    rPumpSpeedCmd       : ARRAY [1..4] OF REAL; (* Variable frequency drive (VFD) speed command for ballast pumps (%) *)
    bCriticalAlarm      : BOOL;     (* General critical fault indicator *)
    rFilteredHeave      : REAL;     (* Kalman-filtered heave displacement estimation (m) *)
    iActiveState        : INT;      (* Current state machine status *)
END_VAR
VAR
    (* Internal state and filtering *)
    iState              : INT := 0; 
    tSafetyTimer        : TON;
    tPneumaticPulse     : TON;
    rHeaveVelZ          : REAL := 0.0;
    rHeavePosZ          : REAL := 0.0;
    rAlpha              : REAL := 0.05; (* Low-pass filter coefficient for noise rejection *)
    iIter               : INT;
    rMaxTension         : REAL;
    rTensionDelta       : REAL;
    rCompensationGain   : REAL := 2.5;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Hardware Monitoring *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    iState := 999; (* FAULT STATE *)

    (* Fail-safe: Close all pneumatic valves, stop pumps *)
    FOR iIter := 1 TO 4 DO
        bPneumaticValveOpen[iIter] := FALSE;
        rPumpSpeedCmd[iIter] := 0.0;
    END_FOR;
    RETURN;
END_IF;

(* 2. Sensor Fusion & Noise Filtering (Simplified Kalman/Euler step for Heave) *)
(* Integrate acceleration to velocity, then to position, with leak factor for drift compensation *)
rHeaveVelZ := (rHeaveVelZ + rHeaveAccelZ * 0.05) * 0.98;
rHeavePosZ := (rHeavePosZ + rHeaveVelZ * 0.05) * 0.95; 

(* Apply first-order low-pass filter to output *)
rFilteredHeave := rAlpha * rHeavePosZ + (1.0 - rAlpha) * rFilteredHeave;

(* 3. State Machine for Active Ballast Heave Compensation *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := TRUE;
        bCriticalAlarm := FALSE;
        FOR iIter := 1 TO 4 DO
            bPneumaticValveOpen[iIter] := FALSE;
            rPumpSpeedCmd[iIter] := 0.0;
        END_FOR;

        IF bEnableSystem THEN
            tSafetyTimer(IN := FALSE);
            iState := 10;
        END_IF;

    10: (* MONITORING AND PRE-CALCULATION *)
        (* Check Mooring Tension Imbalance *)
        rMaxTension := rMooringTension[1];
        FOR iIter := 2 TO 4 DO
            IF rMooringTension[iIter] > rMaxTension THEN
                rMaxTension := rMooringTension[iIter];
            END_IF;
        END_FOR;

        (* If wave period indicates resonance or heave exceeds threshold, enter active compensation *)
        IF (rWavePeriodPred > 8.0 AND rWavePeriodPred < 14.0) OR ABS(rFilteredHeave) > 1.5 THEN
            iState := 20;
        END_IF;

        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    20: (* DYNAMIC PNEUMATIC PONTOON REDISTRIBUTION *)
        (* Apply antagonistic control based on pitch/roll and heave direction *)
        FOR iIter := 1 TO 4 DO
            rTensionDelta := rMooringTension[iIter] - 5000.0; (* 5000 kN nominal target tension *)

            IF rFilteredHeave > 0.0 THEN
                (* Wave is pushing up, flood ballast to increase mass *)
                bPneumaticValveOpen[iIter] := TRUE;
                rPumpSpeedCmd[iIter] := LIMIT(0.0, rCompensationGain * rTensionDelta / 100.0, 100.0);
            ELSE
                (* Trough passing, evacuate ballast to increase buoyancy *)
                bPneumaticValveOpen[iIter] := FALSE;
                rPumpSpeedCmd[iIter] := LIMIT(-100.0, -rCompensationGain * rTensionDelta / 100.0, 0.0);
            END_IF;
        END_FOR;

        tPneumaticPulse(IN := TRUE, PT := T#2S);
        IF tPneumaticPulse.Q THEN
            tPneumaticPulse(IN := FALSE);
            iState := 10; (* Return to monitoring cycle after burst adjustment *)
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bCriticalAlarm := TRUE;
        IF bEmergencyStop AND NOT bEnableSystem THEN
            iState := 0; (* Reset only when system is healthy and explicitly disabled *)
        END_IF;

END_CASE;

iActiveState := iState;

END_FUNCTION_BLOCK
