FUNCTION_BLOCK FB_HydroformingPress
VAR_INPUT
    (* Required: physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal for the entire press sequence *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (TRUE = Safe, FALSE = E-STOP) *)
    rInternalPressurePSI    : REAL;     (* Internal fluid pressure inside the steel part (PSI) *)
    rAxialPunchPosLeft      : REAL;     (* Left axial punch position feedback (mm) *)
    rAxialPunchPosRight     : REAL;     (* Right axial punch position feedback (mm) *)
    bPressureReliefValveOK  : BOOL;     (* Status of extreme pressure relief burst monitoring valve *)
END_VAR
VAR_OUTPUT
    (* Required: outputs with types and comments *)
    bSystemReady            : BOOL;     (* System ready status for auto sequence start *)
    rIntensifierCmd         : REAL;     (* Analog control signal to high-pressure intensifier (0-100%) *)
    rAxialPunchCmdLeft      : REAL;     (* Left axial punch servo speed/force command *)
    rAxialPunchCmdRight     : REAL;     (* Right axial punch servo speed/force command *)
    bAlarm                  : BOOL;     (* High-level fault or interlock alarm output *)
    bBurstDetected          : BOOL;     (* Detected material failure / catastrophic pressure loss *)
END_VAR
VAR
    (* Internal state and mathematical tracking variables *)
    iState                  : INT := 0;
    tTimer                  : TON;
    rVolumetricCompensation : REAL := 0.0;
    rExpectedPressure       : REAL := 0.0;
    rDeltaPressure          : REAL := 0.0;
    bPressureStable         : BOOL := FALSE;
    rMaxPressureLimit       : REAL := 105000.0; (* Limit for 100k PSI system + margin *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rIntensifierCmd := 0.0;
    rAxialPunchCmdLeft := 0.0;
    rAxialPunchCmdRight := 0.0;
    bAlarm := TRUE;
    iState := 999; (* Transition immediately to fault state *)
    RETURN;
END_IF;

(* Continuous safety monitoring of critical pressure conditions *)
IF rInternalPressurePSI > rMaxPressureLimit OR NOT bPressureReliefValveOK THEN
    bAlarm := TRUE;
    rIntensifierCmd := 0.0;
END_IF;

CASE iState OF
    0: (* IDLE - Await Enable & Reset *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        bBurstDetected := FALSE;
        rIntensifierCmd := 0.0;
        IF bEnable AND NOT bAlarm THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PRE-FILL / LOW PRESSURE PHASE *)
        (* Initiate low pressure water fill before axial punch engagement *)
        rIntensifierCmd := 5.0; (* 5% control command for initial low-pressure fill *)
        IF rInternalPressurePSI > 2000.0 THEN
            iState := 20;
        END_IF;

    20: (* AXIAL PUNCH ENGAGEMENT & HIGH PRESSURE FORMING *)
        (* Calculate volumetric synchronization between lateral punches and internal hydrostatic pressure *)
        rVolumetricCompensation := (rAxialPunchPosLeft + rAxialPunchPosRight) * 0.15;
        rExpectedPressure := 2000.0 + (rVolumetricCompensation * 150.0);

        (* Command axial punches to move in synchronization *)
        rAxialPunchCmdLeft := 50.0; 
        rAxialPunchCmdRight := 50.0;

        (* Dynamic pressure intensification up to extreme target forming pressure *)
        rIntensifierCmd := rIntensifierCmd + 0.1;
        IF rIntensifierCmd > 100.0 THEN 
            rIntensifierCmd := 100.0; 
        END_IF;

        (* Extreme Burst Detection Logic: Rapid unexpected pressure drop during form (Material failure) *)
        rDeltaPressure := rExpectedPressure - rInternalPressurePSI;
        IF (rInternalPressurePSI > 50000.0) AND (rDeltaPressure > 15000.0) THEN
            bBurstDetected := TRUE;
            iState := 999;
        END_IF;

        IF rInternalPressurePSI >= 100000.0 THEN
            iState := 30;
        END_IF;

    30: (* DWELL & PRESSURE RELIEF *)
        (* Hold maximum forming pressure and prepare for controlled decompression sequence *)
        tTimer(IN := TRUE, PT := T#3S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            rIntensifierCmd := 0.0;
            rAxialPunchCmdLeft := -25.0; (* Retract punches gently *)
            rAxialPunchCmdRight := -25.0;
            iState := 40;
        END_IF;

    40: (* COMPLETE / SYNCHRONOUS RESET *)
        (* Ensure pressure has fully dissipated before allowing next cycle *)
        IF rInternalPressurePSI < 100.0 THEN
            bSystemReady := TRUE;
            rAxialPunchCmdLeft := 0.0;
            rAxialPunchCmdRight := 0.0;
            IF NOT bEnable THEN
                iState := 0;
            END_IF;
        END_IF;

    999: (* FAULT STATE - CATASTROPHIC ABORT *)
        rIntensifierCmd := 0.0;
        rAxialPunchCmdLeft := 0.0;
        rAxialPunchCmdRight := 0.0;

        (* Require full reset of Enable, E-Stop OK, and Relief OK to clear fault *)
        IF NOT bEnable AND bEmergencyStop AND bPressureReliefValveOK THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
