\nFUNCTION_BLOCK FB_TireCuringPressControl
FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Automated Tire Manufacturing Curing Press Controller'
VERSION : '1.0'

(* 
    This function block controls the complete lifecycle of a tire curing press, 
    including mold hydraulics, bladder shaping, high-pressure vulcanization, 
    and vacuum sequencing.
*)

VAR_INPUT
    bStartCycle         : BOOL;  // Initiate the curing cycle
    bEmergencyStop      : BOOL;  // Emergency stop condition
    bGreenTireLoaded    : BOOL;  // Green tire is successfully loaded
    rTargetCureTemp     : REAL;  // Target vulcanization temperature (Deg C)
    rTargetCurePress    : REAL;  // Target vulcanization pressure (Bar)
    tCureTime           : TIME;  // Total cure time
    rActualMoldTemp     : REAL;  // Feedback: Actual mold temperature
    rActualBladderPress : REAL;  // Feedback: Actual internal bladder pressure
    bMoldClosedSw       : BOOL;  // Feedback: Mold fully closed limit switch
    bMoldLockedSw       : BOOL;  // Feedback: Mold locked limit switch
END_VAR

VAR_OUTPUT
    bMoldCloseCmd       : BOOL;  // Command to close segmented mold
    bMoldLockCmd        : BOOL;  // Command to engage lock ring
    bBladderShapeCmd    : BOOL;  // Command low-pressure steam for bladder shaping
    bSteamValvesOpen    : BOOL;  // Command high-pressure curing steam
    bNitrogenValvesOpen : BOOL;  // Command high-pressure nitrogen
    bVacuumCmd          : BOOL;  // Command vacuum for bladder collapse
    bMoldOpenCmd        : BOOL;  // Command to open segmented mold
    bCycleComplete      : BOOL;  // Curing cycle successfully completed
    bFaultActive        : BOOL;  // Fault active flag
    iFaultCode          : INT;   // Fault code for HMI
    rCurrentPhaseTime   : REAL;  // Elapsed time in current phase
END_VAR

VAR
    eState : (
        STATE_IDLE,
        STATE_MOLD_CLOSING,
        STATE_MOLD_LOCKING,
        STATE_BLADDER_SHAPING,
        STATE_CURING_HEATING,
        STATE_CURING_HOLD,
        STATE_EXHAUST_BLOWDOWN,
        STATE_VACUUM_COLLAPSE,
        STATE_MOLD_UNLOCKING,
        STATE_MOLD_OPENING,
        STATE_FAULT
    ) := STATE_IDLE;

    tStateTimer : TON;
    tCureTimer  : TON;

    rInternalTempSetpoint : REAL;
    bShapingDone          : BOOL;
END_VAR

// Main State Machine
IF bEmergencyStop THEN
    eState := STATE_FAULT;
    iFaultCode := 999;
END_IF;

CASE eState OF
    STATE_IDLE:
        bMoldCloseCmd := FALSE;
        bMoldLockCmd := FALSE;
        bBladderShapeCmd := FALSE;
        bSteamValvesOpen := FALSE;
        bNitrogenValvesOpen := FALSE;
        bVacuumCmd := FALSE;
        bMoldOpenCmd := FALSE;
        bCycleComplete := FALSE;
        bFaultActive := FALSE;
        iFaultCode := 0;

        IF bStartCycle AND bGreenTireLoaded THEN
            eState := STATE_MOLD_CLOSING;
            tStateTimer(IN := FALSE);
        END_IF;

    STATE_MOLD_CLOSING:
        bMoldCloseCmd := TRUE;
        tStateTimer(IN := TRUE, PT := T#15S);

        IF bMoldClosedSw THEN
            bMoldCloseCmd := FALSE;
            eState := STATE_MOLD_LOCKING;
            tStateTimer(IN := FALSE);
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 101; // Mold close timeout
        END_IF;

    STATE_MOLD_LOCKING:
        bMoldLockCmd := TRUE;
        tStateTimer(IN := TRUE, PT := T#10S);

        IF bMoldLockedSw THEN
            eState := STATE_BLADDER_SHAPING;
            tStateTimer(IN := FALSE);
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 102; // Mold lock timeout
        END_IF;

    STATE_BLADDER_SHAPING:
        bBladderShapeCmd := TRUE;
        tStateTimer(IN := TRUE, PT := T#5S);

        IF rActualBladderPress >= 2.0 AND tStateTimer.Q THEN // 2 Bar shaping pressure
            bBladderShapeCmd := FALSE;
            eState := STATE_CURING_HEATING;
            tStateTimer(IN := FALSE);
            tCureTimer(IN := FALSE);
        ELSIF tStateTimer.Q AND rActualBladderPress < 2.0 THEN
            eState := STATE_FAULT;
            iFaultCode := 103; // Shaping pressure fault
        END_IF;

    STATE_CURING_HEATING:
        bSteamValvesOpen := TRUE;
        bNitrogenValvesOpen := FALSE;
        tStateTimer(IN := TRUE, PT := T#5M); // Max time to reach temp

        IF rActualMoldTemp >= rTargetCureTemp AND rActualBladderPress >= rTargetCurePress THEN
            eState := STATE_CURING_HOLD;
            tStateTimer(IN := FALSE);
            tCureTimer(IN := TRUE, PT := tCureTime);
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 104; // Heating timeout
        END_IF;

    STATE_CURING_HOLD:
        tCureTimer(IN := TRUE, PT := tCureTime);
        // Basic bang-bang temp control during hold
        IF rActualMoldTemp < rTargetCureTemp - 2.0 THEN
            bSteamValvesOpen := TRUE;
        ELSIF rActualMoldTemp > rTargetCureTemp + 2.0 THEN
            bSteamValvesOpen := FALSE;
        END_IF;

        // Switch to Nitrogen for high pressure cure completion (saving steam)
        IF tCureTimer.ET > (tCureTime / 2) THEN
            bSteamValvesOpen := FALSE;
            bNitrogenValvesOpen := TRUE;
        END_IF;

        IF tCureTimer.Q THEN
            bSteamValvesOpen := FALSE;
            bNitrogenValvesOpen := FALSE;
            eState := STATE_EXHAUST_BLOWDOWN;
            tStateTimer(IN := FALSE);
        END_IF;

    STATE_EXHAUST_BLOWDOWN:
        // Valves commanded closed, wait for pressure to bleed off (assumes mechanical exhaust valve interlocked)
        tStateTimer(IN := TRUE, PT := T#30S);
        IF rActualBladderPress < 0.5 AND tStateTimer.Q THEN
            eState := STATE_VACUUM_COLLAPSE;
            tStateTimer(IN := FALSE);
        ELSIF tStateTimer.Q AND rActualBladderPress >= 0.5 THEN
            eState := STATE_FAULT;
            iFaultCode := 105; // Blowdown timeout
        END_IF;

    STATE_VACUUM_COLLAPSE:
        bVacuumCmd := TRUE;
        tStateTimer(IN := TRUE, PT := T#20S);

        IF rActualBladderPress <= -0.6 THEN // Good vacuum
            bVacuumCmd := FALSE;
            eState := STATE_MOLD_UNLOCKING;
            tStateTimer(IN := FALSE);
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 106; // Vacuum timeout
        END_IF;

    STATE_MOLD_UNLOCKING:
        bMoldLockCmd := FALSE;
        tStateTimer(IN := TRUE, PT := T#10S);

        IF NOT bMoldLockedSw THEN
            eState := STATE_MOLD_OPENING;
            tStateTimer(IN := FALSE);
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 107; // Mold unlock timeout
        END_IF;

    STATE_MOLD_OPENING:
        bMoldOpenCmd := TRUE;
        tStateTimer(IN := TRUE, PT := T#15S);

        IF NOT bMoldClosedSw THEN
            bMoldOpenCmd := FALSE;
            bCycleComplete := TRUE;
            eState := STATE_IDLE;
        ELSIF tStateTimer.Q THEN
            eState := STATE_FAULT;
            iFaultCode := 108; // Mold open timeout
        END_IF;

    STATE_FAULT:
        bMoldCloseCmd := FALSE;
        bBladderShapeCmd := FALSE;
        bSteamValvesOpen := FALSE;
        bNitrogenValvesOpen := FALSE;
        bVacuumCmd := FALSE;
        bMoldOpenCmd := FALSE;
        bFaultActive := TRUE;

        // Latch fault until manual reset (not implemented in this snippet)
END_CASE;

