FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // Enable inspection system
    bTriggerCam1 : BOOL; // Trigger for sidewall camera
    bTriggerCam2 : BOOL; // Trigger for lip dimension camera
    bEncoderPulse : BOOL; // High-speed encoder pulse from main conveyor
    iBottleID : UDINT; // Unique bottle identifier from tracking shift register
    rSidewallRefractionIndex : REAL; // Refraction index input from optical sensor
    rLipDiameter : REAL; // Measured lip diameter in mm
    rLipHeight : REAL; // Measured lip height in mm
    iConveyorSpeed : INT; // Current line speed in bottles per minute
END_VAR

VAR_OUTPUT
    bRejectTrigger : BOOL; // High-speed trigger to pneumatic star-wheel rejector
    bAcceptTrigger : BOOL; // Pass signal to packaging
    bSystemFault : BOOL; // System fault indicator
    iTotalInspected : UDINT; // Total bottles inspected
    iTotalRejected : UDINT; // Total bottles rejected
    iCurrentRejectCode : INT; // 1=Sidewall, 2=LipDiameter, 3=LipHeight, 4=Multiple
    rAverageThickness : REAL; // Moving average of bottle thickness
END_VAR

VAR
    // Internal state variables
    bInitialized : BOOL := FALSE;
    iState : INT := 0; // 0=Idle, 1=Active, 2=Fault

    // Limits and thresholds
    rMinThickness : REAL := 1.85; // mm
    rMaxThickness : REAL := 3.15; // mm
    rExpectedLipDiameter : REAL := 28.5; // mm
    rLipDiameterTolerance : REAL := 0.25; // mm
    rExpectedLipHeight : REAL := 15.0; // mm
    rLipHeightTolerance : REAL := 0.15; // mm

    // Evaluation flags
    bSidewallPass : BOOL;
    bLipPass : BOOL;

    // Moving average calculation array
    rThicknessHistory : ARRAY[0..99] OF REAL;
    iHistoryIndex : INT := 0;
    rThicknessSum : REAL := 0.0;
    i : INT;

    // Timers
    tRejectDelay : TON;
    tCameraTimeout : TON;
END_VAR

// Initialization
IF NOT bInitialized THEN
    FOR i := 0 TO 99 DO
        rThicknessHistory[i] := 2.5; // Initialize to nominal
    END_FOR;
    bInitialized := TRUE;
END_IF;

// Main State Machine
IF NOT bEnable THEN
    iState := 0; // Idle
    bRejectTrigger := FALSE;
    bAcceptTrigger := FALSE;
ELSE
    IF iState = 0 THEN
        iState := 1; // Active
    END_IF;
END_IF;

// Active Inspection Logic
IF iState = 1 THEN
    // 1. Sidewall Thickness Calculation based on optical refraction
    // Using simplified Snell's law derivation for thickness
    VAR_TEMP
        rCalculatedThickness : REAL;
        rLipDiameterDiff : REAL;
        rLipHeightDiff : REAL;
    END_VAR;

    rCalculatedThickness := rSidewallRefractionIndex * 1.52; // Approximation constant for glass

    // Update moving average
    rThicknessSum := rThicknessSum - rThicknessHistory[iHistoryIndex] + rCalculatedThickness;
    rThicknessHistory[iHistoryIndex] := rCalculatedThickness;
    rAverageThickness := rThicknessSum / 100.0;
    iHistoryIndex := (iHistoryIndex + 1) MOD 100;

    // Evaluate Sidewall
    IF rCalculatedThickness >= rMinThickness AND rCalculatedThickness <= rMaxThickness THEN
        bSidewallPass := TRUE;
    ELSE
        bSidewallPass := FALSE;
        iCurrentRejectCode := 1;
    END_IF;

    // 2. Lip Dimensional Checking
    rLipDiameterDiff := ABS(rLipDiameter - rExpectedLipDiameter);
    rLipHeightDiff := ABS(rLipHeight - rExpectedLipHeight);

    IF rLipDiameterDiff <= rLipDiameterTolerance AND rLipHeightDiff <= rLipHeightTolerance THEN
        bLipPass := TRUE;
    ELSE
        bLipPass := FALSE;
        IF NOT bSidewallPass THEN
            iCurrentRejectCode := 4; // Multiple faults
        ELSIF rLipDiameterDiff > rLipDiameterTolerance THEN
            iCurrentRejectCode := 2; // Lip Diameter fault
        ELSE
            iCurrentRejectCode := 3; // Lip Height fault
        END_IF;
    END_IF;

    // 3. Decision and Ejection Logic
    IF bTriggerCam1 AND bTriggerCam2 THEN // Assuming synchronized triggers for evaluation cycle
        iTotalInspected := iTotalInspected + 1;

        IF bSidewallPass AND bLipPass THEN
            // Pass
            bAcceptTrigger := TRUE;
            bRejectTrigger := FALSE;
        ELSE
            // Fail
            bAcceptTrigger := FALSE;
            bRejectTrigger := TRUE;
            iTotalRejected := iTotalRejected + 1;

            // Pneumatic star-wheel timing logic would be tied to encoder pulses here
            // (Abstracted to simple trigger for ST representation)
        END_IF;
    ELSE
        // Reset triggers between cycles
        bAcceptTrigger := FALSE;
        bRejectTrigger := FALSE;
    END_IF;

    // Basic fault detection (e.g., jam detection via speed/encoder mismatch)
    IF iConveyorSpeed > 0 AND NOT bEncoderPulse THEN
        tCameraTimeout(IN := TRUE, PT := T#500MS);
        IF tCameraTimeout.Q THEN
            bSystemFault := TRUE;
            iState := 2;
        END_IF;
    ELSE
        tCameraTimeout(IN := FALSE);
    END_IF;
END_IF;

// Fault State
IF iState = 2 THEN
    bRejectTrigger := FALSE;
    bAcceptTrigger := FALSE;
    // Require manual reset of bEnable to clear fault
    IF NOT bEnable THEN
        bSystemFault := FALSE;
        iState := 0;
    END_IF;
END_IF;
