    iActiveFaultCode : INT;          (* Active fault identifier (0 = OK) *)
    dTotalCupsProduced : DINT;       (* Lifetime production counter *)
END_VAR

VAR
    iState : INT := 0;               (* Main state machine index *)
    rCalculatedLubeRate : REAL;      (* Dynamic lube calculation based on SPM *)
    xFaultActive : BOOL := FALSE;    (* Internal fault flag *)
    fbEjectTimer : TON;              (* Timer for air blast duration fail-safe *)
    fbTensionPID : PID;              (* PID controller for infeed tension *)
    rTensionIntegral : REAL := 0.0;

    (* Configurable Parameters *)
    rLubeBaseFactor : REAL := 0.15;  (* mL per stroke base multiplier *)
    rAngleBlankHolderOn : REAL := 275.0;
    rAngleBlankHolderOff : REAL := 85.0;
    rAngleDrawPunchOn : REAL := 300.0;
    rAngleDrawPunchOff : REAL := 60.0;
    rAngleAirBlastStart : REAL := 120.0;
    rAngleAirBlastEnd : REAL := 170.0;
    tMaxAirBlastDuration : TIME := T#120MS;

    xAirBlastActive : BOOL;          (* Internal flag for air blast window *)
    xPrevCyclePulse : BOOL;          (* Edge detection for cycle counting *)
END_VAR

(* ============================================================================== *)
(* SAFETY AND FAULT MONITORING                                                    *)
(* ============================================================================== *)
IF NOT xEmergencyStop OR NOT xSafetyGuardsClosed THEN
    iActiveFaultCode := 1001; (* Safety circuit tripped *)
    xFaultActive := TRUE;
ELSIF rAirSupplyPressure < 5.5 THEN
    iActiveFaultCode := 2001; (* Low air pressure *)
    xFaultActive := TRUE;
ELSIF rLubeLevelPV < 10.0 THEN
    iActiveFaultCode := 3001; (* Low lubrication level *)
    xFaultActive := TRUE;
ELSIF xResetFaults AND xEmergencyStop AND xSafetyGuardsClosed THEN
    iActiveFaultCode := 0;
    xFaultActive := FALSE;
END_IF;

(* Stop everything if fault is active *)
IF xFaultActive THEN
    rMainDriveSpeedCmd := 0.0;
    xClutchEngage := FALSE;
    xBrakeRelease := FALSE;
    xBlankHolderValve := FALSE;
    xDrawPunchValve := FALSE;
    rLubePumpSpeed := 0.0;
    xCupEjectAirBlast := FALSE;
    xSystemReady := FALSE;
    RETURN;
END_IF;

xSystemReady := TRUE;

(* ============================================================================== *)
(* STATE MACHINE & MAIN DRIVE                                                     *)
(* ============================================================================== *)
IF xEnableSystem AND xStockPresent THEN
    rMainDriveSpeedCmd := rLineSpeedSP;
    xBrakeRelease := TRUE;

    (* Clutch engagement logic - simplified for example *)
    IF rActualSpeed > (rLineSpeedSP * 0.9) THEN
        xClutchEngage := TRUE;
    END_IF;
ELSE
    rMainDriveSpeedCmd := 0.0;
    xClutchEngage := FALSE;
    xBrakeRelease := FALSE;
END_IF;

(* ============================================================================== *)
(* COIL STOCK LUBRICATION METERING                                                *)
(* ============================================================================== *)
(* Lube pump speed is proportional to actual line speed to maintain constant film *)
IF xEnableSystem AND (rActualSpeed > 0.0) THEN
    rCalculatedLubeRate := rActualSpeed * rLubeBaseFactor;
    (* Clamp output to 0-100% *)
    IF rCalculatedLubeRate > 100.0 THEN
        rLubePumpSpeed := 100.0;
    ELSE
        rLubePumpSpeed := rCalculatedLubeRate;
    END_IF;
ELSE
    rLubePumpSpeed := 0.0;
END_IF;

(* ============================================================================== *)
(* DOUBLE-ACTION DRAW RAM TIMING                                                  *)
(* ============================================================================== *)
(* Blank Holder synchronization based on master crank angle *)
IF (rMasterCrankAngle >= rAngleBlankHolderOn) OR (rMasterCrankAngle <= rAngleBlankHolderOff) THEN
    xBlankHolderValve := TRUE;
ELSE
    xBlankHolderValve := FALSE;
END_IF;

(* Draw Punch synchronization *)
IF (rMasterCrankAngle >= rAngleDrawPunchOn) OR (rMasterCrankAngle <= rAngleDrawPunchOff) THEN
    xDrawPunchValve := TRUE;
ELSE
    xDrawPunchValve := FALSE;
END_IF;

(* ============================================================================== *)
(* CUP EJECTION AIR BLAST SYNCHRONIZATION                                         *)
(* ============================================================================== *)
(* Trigger air blast at specific crank angle to eject finished cup *)
IF (rMasterCrankAngle >= rAngleAirBlastStart) AND (rMasterCrankAngle <= rAngleAirBlastEnd) THEN
    xAirBlastActive := TRUE;
ELSE
    xAirBlastActive := FALSE;
END_IF;

(* Fail-safe timer to prevent blowing air continuously if press stops inside window *)
fbEjectTimer(IN := xAirBlastActive, PT := tMaxAirBlastDuration);

IF xAirBlastActive AND NOT fbEjectTimer.Q THEN
    xCupEjectAirBlast := TRUE;
ELSE
    xCupEjectAirBlast := FALSE;
END_IF;

(* ============================================================================== *)
(* CYCLE COUNTING                                                                 *)
(* ============================================================================== *)
(* Count one cup for every crossing of top dead center (0 degrees) *)
IF (rMasterCrankAngle < 5.0) AND NOT xPrevCyclePulse THEN
    dTotalCupsProduced := dTotalCupsProduced + 1;
    xPrevCyclePulse := TRUE;
ELSIF (rMasterCrankAngle > 10.0) THEN
    xPrevCyclePulse := FALSE;
END_IF;

END_FUNCTION_BLOCK
