FUNCTION_BLOCK FB_Geothermal_ORC_Control
TITLE = 'Geothermal Binary Cycle ORC and ACC Control'
VERSION : '1.1'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    rBrineInletTemp       : REAL; // Brine temperature from production well (Deg C)
    rBrineFlowRate        : REAL; // Brine flow rate (kg/s)
    rWorkingFluidPress    : REAL; // Pentane/Isopentane pressure in vaporizer (Bar)
    rWorkingFluidTemp     : REAL; // Pentane/Isopentane temperature (Deg C)
    rTurbineSpeed         : REAL; // Turbine shaft speed (RPM)
    rGridFrequency        : REAL; // Electrical grid frequency (Hz)
    rAmbientAirTemp       : REAL; // Ambient air temperature for ACC (Deg C)
    rCondenserPress       : REAL; // Pressure in the air-cooled condenser (Bar)
    bEmergencyStop        : BOOL; // E-Stop active high
    bStartSequence        : BOOL; // Start command
END_VAR

VAR_OUTPUT
    rBrineValvePosition     : REAL; // 0.0 to 100.0% open
    rTurbineInletValve      : REAL; // 0.0 to 100.0% open
    rTurbineBypassValve     : REAL; // 0.0 to 100.0% open
    rFeedPumpSpeed          : REAL; // 0.0 to 100.0% speed reference
    iAccFanMatrixRunMask    : INT;  // Bitmask for up to 16 ACC fans
    bTurbineTrip            : BOOL; // Trip signal to safety system
    sSystemState            : STRING[32]; // Current state string
END_VAR

VAR
    iState                  : INT := 0; // State machine index
    rSuperheatMargin        : REAL;
    rSaturationTemp         : REAL;
    tStateTimer             : TON;
    iActiveFans             : INT;
    i                       : INT;
END_VAR

VAR_CONSTANT
    C_MAX_BRINE_TEMP        : REAL := 180.0;
    C_MIN_SUPERHEAT         : REAL := 5.0; // Minimum superheat required (Deg C)
    C_NOMINAL_TURBINE_SPD   : REAL := 3000.0; // RPM for 50Hz (2-pole)
    C_TRIP_OVERSPEED        : REAL := 3300.0;
    C_MAX_CONDENSER_PRESS   : REAL := 4.5;
END_VAR

// Define basic saturation temperature curve for Isopentane (simplified linear approx for demonstration)
rSaturationTemp := (rWorkingFluidPress * 12.5) + 30.0;
rSuperheatMargin := rWorkingFluidTemp - rSaturationTemp;

// Emergency Trip Evaluation
IF bEmergencyStop OR (rTurbineSpeed > C_TRIP_OVERSPEED) OR (rCondenserPress > C_MAX_CONDENSER_PRESS) THEN
    bTurbineTrip := TRUE;
    iState := 99; // Trip State
END_IF;

// ACC Fan Matrix Control (Staged based on Condenser Pressure)
iActiveFans := 0;
IF rCondenserPress > 1.5 THEN iActiveFans := 2; END_IF;
IF rCondenserPress > 2.0 THEN iActiveFans := 4; END_IF;
IF rCondenserPress > 2.5 THEN iActiveFans := 8; END_IF;
IF rCondenserPress > 3.0 THEN iActiveFans := 12; END_IF;
IF rCondenserPress > 3.5 THEN iActiveFans := 16; END_IF;

iAccFanMatrixRunMask := 0;
FOR i := 0 TO iActiveFans - 1 DO
    iAccFanMatrixRunMask := iAccFanMatrixRunMask OR SHL(INT#1, i);
END_FOR;

// State Machine for ORC Loop
CASE iState OF
    0: // IDLE
        sSystemState := 'IDLE';
        rBrineValvePosition := 0.0;
        rTurbineInletValve := 0.0;
        rTurbineBypassValve := 100.0;
        rFeedPumpSpeed := 0.0;
        IF bStartSequence AND NOT bTurbineTrip THEN
            iState := 10;
        END_IF;

    10: // PRE-WARM VAPORIZER
        sSystemState := 'PRE-WARM';
        rFeedPumpSpeed := 25.0; // Circulate working fluid
        rBrineValvePosition := 10.0; // Crack open brine valve
        IF rWorkingFluidTemp > (rSaturationTemp - 10.0) THEN
            iState := 20;
        END_IF;

    20: // VAPORIZATION & SUPERHEAT ESTABLISHMENT
        sSystemState := 'ESTABLISH SUPERHEAT';
        rBrineValvePosition := 40.0;
        IF rSuperheatMargin > C_MIN_SUPERHEAT THEN
            tStateTimer(IN := TRUE, PT := T#30s);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iState := 30;
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

    30: // TURBINE ROLL-UP
        sSystemState := 'TURBINE ROLL-UP';
        // Ramp bypass down and inlet up
        rTurbineBypassValve := rTurbineBypassValve - 1.0;
        rTurbineInletValve := rTurbineInletValve + 1.0;
        IF rTurbineBypassValve <= 0.0 THEN
            rTurbineBypassValve := 0.0;
            rTurbineInletValve := 100.0;
        END_IF;

        IF rTurbineSpeed > (C_NOMINAL_TURBINE_SPD * 0.95) THEN
            iState := 40;
        END_IF;

    40: // GENERATION RUN
        sSystemState := 'GENERATING';
        // Modulate brine valve to maintain superheat and pressure
        IF rSuperheatMargin < C_MIN_SUPERHEAT THEN
            rBrineValvePosition := rBrineValvePosition + 0.5;
        ELSIF rSuperheatMargin > (C_MIN_SUPERHEAT + 10.0) THEN
            rBrineValvePosition := rBrineValvePosition - 0.5;
        END_IF;

        // Limit checks
        IF rBrineValvePosition > 100.0 THEN rBrineValvePosition := 100.0; END_IF;
        IF rBrineValvePosition < 0.0 THEN rBrineValvePosition := 0.0; END_IF;

    99: // TRIP / SAFE SHUTDOWN
        sSystemState := 'TRIPPED';
        rBrineValvePosition := 0.0;
        rTurbineInletValve := 0.0;
        rTurbineBypassValve := 100.0; // Bypass all vapor to condenser
        rFeedPumpSpeed := 0.0;
        IF NOT bEmergencyStop AND (rTurbineSpeed < 100.0) THEN
            bTurbineTrip := FALSE;
            iState := 0; // Return to idle once spun down and reset
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
