(* HYPERSCALE LIQUID COOLING CHILLER ARRAY *)
(* This module manages advanced direct-to-chip (D2C) liquid cooling for mega data center environments. *)
(* It features external wet-bulb temperature-based free cooling, dynamic flow regulation via IPMI telemetry, and N+1 pump failover. *)

FUNCTION_BLOCK FB_Hyperscale_Liquid_Cooling
VAR_INPUT
    // Environmental sensors
    rWetBulbTemp_C        : REAL; // External wet-bulb temperature in Celsius
    rAmbientTemp_C        : REAL; // External ambient temperature in Celsius

    // IT Load Telemetry (IPMI Aggregated Data)
    rAggregatedCPULoad_Pct : REAL; // Aggregated CPU load percentage across the zone (0.0 to 100.0)
    rMaxCPU_Temp_C        : REAL; // Highest reported CPU temperature in the zone

    // Primary Coolant Loop Sensors
    rSupplyTemp_C         : REAL; // Main supply header temperature
    rReturnTemp_C         : REAL; // Main return header temperature
    rSystemFlow_LPM       : REAL; // Current total system flow in liters per minute
    rSystemPressure_kPa   : REAL; // Main header pressure

    // Pump Status (N+1 Configuration, 3+1 setup = 4 pumps total)
    bPump1_Running        : BOOL;
    bPump1_Fault          : BOOL;
    bPump2_Running        : BOOL;
    bPump2_Fault          : BOOL;
    bPump3_Running        : BOOL;
    bPump3_Fault          : BOOL;
    bPump4_Running        : BOOL; // Redundant Pump
    bPump4_Fault          : BOOL;
END_VAR

VAR_OUTPUT
    // Economizer (Free-cooling) Control
    rFreeCoolingValve_Pct : REAL; // 0.0 (Closed) to 100.0 (Fully Open)
    rChillerLoad_Pct      : REAL; // 0.0 to 100.0 mechanical chiller stage

    // Direct-to-Chip Flow Regulation
    rPrimaryVFD_Speed_Pct : REAL; // Required VFD speed for active pumps

    // Pump Command Outputs
    bCmdPump1_Run         : BOOL;
    bCmdPump2_Run         : BOOL;
    bCmdPump3_Run         : BOOL;
    bCmdPump4_Run         : BOOL;

    // System Status & Alarms
    bCriticalAlarm        : BOOL;
    sStatusMessage        : STRING[80];
END_VAR

VAR
    // Internal state variables
    rTargetFlow_LPM       : REAL;
    rTargetSupplyTemp_C   : REAL := 32.0; // High supply temp for D2C efficiency

    // PID Controllers for flow and cooling
    fbFlowPID             : FB_PID_Advanced;
    fbCoolingPID          : FB_PID_Advanced;

    // Pump rotation logic
    iActivePumpCount      : INT;
    iRequiredPumpCount    : INT;

    // Timers
    tonFailoverDelay      : TON;
END_VAR

(* 1. FREE-COOLING (ECONOMIZER) STAGING *)
// Calculate cooling mode based on wet-bulb approach temperature
// ASHRAE TC9.9 W3 liquid cooling class allows higher supply temperatures
IF rWetBulbTemp_C < (rTargetSupplyTemp_C - 4.0) THEN
    // 100% Free Cooling Mode
    rFreeCoolingValve_Pct := 100.0;
    rChillerLoad_Pct := 0.0;
    sStatusMessage := 'MODE: Full Free Cooling';
ELSIF rWetBulbTemp_C < rTargetSupplyTemp_C THEN
    // Partial Free Cooling Mode (Trim chilling required)
    rFreeCoolingValve_Pct := 100.0;

    // PID control for trim chiller based on supply temperature error
    fbCoolingPID(
        rProcessValue := rSupplyTemp_C,
        rSetpoint := rTargetSupplyTemp_C,
        rKp := 2.5, rKi := 0.5, rKd := 0.1,
        rOutput => rChillerLoad_Pct
    );
    sStatusMessage := 'MODE: Partial Free Cooling';
ELSE
    // 100% Mechanical Cooling Mode
    rFreeCoolingValve_Pct := 0.0;
    fbCoolingPID(
        rProcessValue := rSupplyTemp_C,
        rSetpoint := rTargetSupplyTemp_C,
        rKp := 5.0, rKi := 1.0, rKd := 0.2,
        rOutput => rChillerLoad_Pct
    );
    sStatusMessage := 'MODE: Mechanical Cooling';
END_IF;

(* 2. DIRECT-TO-CHIP FLOW REGULATION (IPMI TELEMETRY) *)
// Calculate required flow based on CPU load and max CPU temperatures
// Base flow + flow proportional to CPU load + thermal override if CPUs are hot
rTargetFlow_LPM := 500.0 + (rAggregatedCPULoad_Pct * 15.0); // Base 500 LPM, up to 2000 LPM at 100% load

IF rMaxCPU_Temp_C > 75.0 THEN
    // Thermal override condition, boost flow by 25%
    rTargetFlow_LPM := rTargetFlow_LPM * 1.25;
END_IF;

// Cap target flow to maximum system capacity (e.g., 2500 LPM)
IF rTargetFlow_LPM > 2500.0 THEN
    rTargetFlow_LPM := 2500.0;
END_IF;

// PID controller to maintain target flow via VFD speed regulation
fbFlowPID(
    rProcessValue := rSystemFlow_LPM,
    rSetpoint := rTargetFlow_LPM,
    rKp := 1.2, rKi := 0.3, rKd := 0.05,
    rOutput => rPrimaryVFD_Speed_Pct
);

(* 3. REDUNDANT N+1 PUMP FAILOVER (ZERO FLOW INTERRUPTION) *)
// Determine required number of pumps based on target flow
iRequiredPumpCount := 3; // Base design is 3 pumps for full load
IF rTargetFlow_LPM < 800.0 THEN
    iRequiredPumpCount := 1;
ELSIF rTargetFlow_LPM < 1600.0 THEN
    iRequiredPumpCount := 2;
END_IF;

// Initialize run commands to false
bCmdPump1_Run := FALSE;
bCmdPump2_Run := FALSE;
bCmdPump3_Run := FALSE;
bCmdPump4_Run := FALSE;

// Failover Logic: Evaluate available pumps (not faulted)
// Primary pump 1
IF NOT bPump1_Fault AND iRequiredPumpCount > 0 THEN
    bCmdPump1_Run := TRUE;
    iRequiredPumpCount := iRequiredPumpCount - 1;
END_IF;

// Primary pump 2
IF NOT bPump2_Fault AND iRequiredPumpCount > 0 THEN
    bCmdPump2_Run := TRUE;
    iRequiredPumpCount := iRequiredPumpCount - 1;
END_IF;

// Primary pump 3
IF NOT bPump3_Fault AND iRequiredPumpCount > 0 THEN
    bCmdPump3_Run := TRUE;
    iRequiredPumpCount := iRequiredPumpCount - 1;
END_IF;

// Redundant pump 4 engages immediately if target pump count is not met (failover)
IF NOT bPump4_Fault AND iRequiredPumpCount > 0 THEN
    bCmdPump4_Run := TRUE;
    iRequiredPumpCount := iRequiredPumpCount - 1;
END_IF;

// Critical Alarm generation if we still cannot meet the required pump count
IF iRequiredPumpCount > 0 THEN
    bCriticalAlarm := TRUE;
    sStatusMessage := 'CRITICAL: Insufficient pumps available to meet flow demand';
ELSE
    bCriticalAlarm := FALSE;
END_IF;

// Zero flow interruption buffer: If a fault is detected, the next available pump
// is instantly commanded ON in the same PLC scan cycle, preventing pressure drops.

END_FUNCTION_BLOCK
