      ConveyorRun : Bool;
      ConveyorSpeedOut : Real;
      Zone1_Heater : Bool;
      Zone2_Heater : Bool;
      Zone3_Heater : Bool;
      SteamValve : Bool;
      Running : Bool;
      AlarmCode : Int;      // Global alarm register for diagnostics
   END_VAR

   VAR 
      StateRunning : Bool;
      CommsFault : Bool;
   END_VAR

BEGIN
    // Profinet Diagnostics Check
    #CommsFault := (#PN_NodeStatus <> 16#0000);

    // State Machine & Fault Management
    IF #CommsFault THEN
        #AlarmCode := 101; // PN Communication Loss Alarm
        #StateRunning := FALSE; // Interlock trip
    ELSIF #Stop THEN
        #StateRunning := FALSE;
        #AlarmCode := 0;
    ELSIF #Start AND NOT #CommsFault THEN
        #StateRunning := TRUE;
        #AlarmCode := 0;
    END_IF;

    #Running := #StateRunning;

    // Normal Operation Execution
    IF #StateRunning THEN
        #ConveyorRun := TRUE;
        #ConveyorSpeedOut := #TargetSpeed;

        #Zone1_Heater := #Zone1_TempActual < (#Zone1_TempTarget - 2.0);
        #Zone2_Heater := #Zone2_TempActual < (#Zone2_TempTarget - 2.0);
        #Zone3_Heater := #Zone3_TempActual < (#Zone3_TempTarget - 2.0);

        // Steam Subsystem
        IF #HumidityActual < (#HumidityTarget - 5.0) THEN
            #SteamValve := TRUE;
        ELSIF #HumidityActual >= #HumidityTarget THEN
            #SteamValve := FALSE;
        END_IF;
    ELSE
        // Failure and Shutdown state
        #ConveyorRun := FALSE;
        #ConveyorSpeedOut := 0.0;
        #Zone1_Heater := FALSE;
        #Zone2_Heater := FALSE;
        #Zone3_Heater := FALSE;
        #SteamValve := FALSE;
    END_IF;
END_FUNCTION_BLOCK
