END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine state *)
    tArgonPurgeTimer        : TON;      (* Timer to ensure laminar flow is established *)
    tMeltPoolFilter         : REAL;     (* Exponential moving average for pyrometer noise reduction *)
    rTempError              : REAL;     (* PID error for melt pool temp *)
    rTempErrorIntegral      : REAL;     (* PID integral term *)
    rTempErrorDerivative    : REAL;     (* PID derivative term *)
    rLastTempError          : REAL;     (* For PID derivative calculation *)

    (* PID Constants *)
    Kp                      : REAL := 1.25;
    Ki                      : REAL := 0.05;
    Kd                      : REAL := 0.01;

    bRecoaterJam            : BOOL := FALSE;
    bThermalRunaway         : BOOL := FALSE;

    tControlLoopTimer       : TON;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Check *)
IF NOT bEmergencyStop OR NOT bLaserInterlock THEN
    iState := 99; (* Transition to fault state *)
END_IF;

(* 2. Sensor Noise Filtering (Exponential Moving Average) *)
(* Time constant ~0.1s at 1ms scan cycle *)
tMeltPoolFilter := (tMeltPoolFilter * 0.90) + (rMeltPoolTemp * 0.10);

(* 3. Anomaly Detection (Recoater and Spatter/Thermal) *)
IF rRecoaterTorque > 15.0 THEN
    bRecoaterJam := TRUE;
    iState := 99;
END_IF;

IF tMeltPoolFilter > (rTargetMeltPoolTemp + 500.0) THEN
    bThermalRunaway := TRUE;
    iState := 99;
END_IF;

(* 4. Main State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        bLaserEmitting := FALSE;
        rActualLaserPower := 0.0;
        iErrorCode := 0;

        IF bEnable THEN
            iState := 10; (* Start Gas Purge *)
        END_IF;

    10: (* ARGON PURGE & LAMINAR FLOW STABILIZATION *)
        IF rArgonFlowRate >= 50.0 AND rArgonFlowRate <= 60.0 THEN
            tArgonPurgeTimer(IN := TRUE, PT := T#5S);
            IF tArgonPurgeTimer.Q THEN
                tArgonPurgeTimer(IN := FALSE);
                iState := 20; (* Ready *)
            END_IF;
        ELSE
            tArgonPurgeTimer(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* SYSTEM READY *)
        bSystemReady := TRUE;
        bLaserEmitting := FALSE;
        rActualLaserPower := 0.0;

        (* If ready and laser control demanded by supervisor *)
        IF rTargetLaserPower > 0.0 THEN
            iState := 30; (* Active Laser Melting *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* ACTIVE MELTING WITH CLOSED-LOOP PYROMETRY FEEDBACK *)
        bLaserEmitting := TRUE;

        (* Calculate PID Error *)
        rTempError := rTargetMeltPoolTemp - tMeltPoolFilter;

        (* Anti-windup for integral term *)
        IF (rActualLaserPower < 1000.0) AND (rActualLaserPower > 0.0) THEN
            rTempErrorIntegral := rTempErrorIntegral + rTempError;
        END_IF;

        rTempErrorDerivative := rTempError - rLastTempError;
        rLastTempError := rTempError;

        (* Calculate output with feedforward (rTargetLaserPower) + PID trim *)
        rActualLaserPower := rTargetLaserPower + (Kp * rTempError) + (Ki * rTempErrorIntegral) + (Kd * rTempErrorDerivative);

        (* Output Saturation *)
        IF rActualLaserPower > 1500.0 THEN
            rActualLaserPower := 1500.0;
        ELSIF rActualLaserPower < 0.0 THEN
            rActualLaserPower := 0.0;
        END_IF;

        (* Dynamic Galvo Correction based on Melt Pool Asymmetry heuristics *)
        (* Note: In realistic systems, this relies on vision feedback, simulated here via temp gradients *)
        IF rTempError > 100.0 THEN
            rGalvoCorrectionX := 5.0; (* Pre-compensate for thermal expansion track shifting *)
        ELSE
            rGalvoCorrectionX := 0.0;
        END_IF;

        (* Stop emitting if target power returns to 0 *)
        IF rTargetLaserPower <= 0.0 THEN
            iState := 20;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT / ERROR STATE *)
        bSystemReady := FALSE;
        bAlarm := TRUE;
        bLaserEmitting := FALSE;
        rActualLaserPower := 0.0;
        tArgonPurgeTimer(IN := FALSE);

        IF NOT bEmergencyStop OR NOT bLaserInterlock THEN
            iErrorCode := 1001; (* E-Stop or Interlock Broken *)
        ELSIF bRecoaterJam THEN
            iErrorCode := 2001; (* Recoater Torque High *)
        ELSIF bThermalRunaway THEN
            iErrorCode := 3001; (* Thermal Runaway Detected *)
        ELSE
            iErrorCode := 9999; (* Unknown Fault *)
        END_IF;

        (* Require manual reset (bEnable toggle) after faults clear *)
        IF NOT bEnable AND bEmergencyStop AND bLaserInterlock AND NOT bRecoaterJam AND NOT bThermalRunaway THEN
            iState := 0;
            iErrorCode := 0;
            bAlarm := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
