FUNCTION_BLOCK FB_Bioreactor_Cascade_Control
TITLE = 'Mammalian Cell Culture Bioreactor DO/pH Cascade Loop'
// Version 1.0 - Biopharmaceutical Fermentation Domain
// Author: Lumina Elite Synthetic Data Architect

VAR_INPUT
    rDO_PV : REAL;              // Dissolved Oxygen Process Variable (%)
    rDO_SP : REAL;              // Dissolved Oxygen Setpoint (%)
    rpH_PV : REAL;              // pH Process Variable (pH)
    rpH_SP : REAL;              // pH Setpoint (pH)
    rTemp_PV : REAL;            // Temperature Process Variable (C)
    bEnableDOControl : BOOL;    // Enable DO Cascade Control
    bEnablepHControl : BOOL;    // Enable pH Cascade Control
    bEmergencyStop : BOOL;      // Emergency stop from Safety PLC
    rAgitatorSpeed_Max : REAL;  // Maximum agitator speed constraint (RPM)
    rAirFlow_Max : REAL;        // Maximum Air flow rate (LPM)
    rO2Flow_Max : REAL;         // Maximum Oxygen flow rate (LPM)
END_VAR

VAR_OUTPUT
    rAgitatorSpeed_CV : REAL;   // Agitator Speed Control Variable (RPM)
    rAirFlow_CV : REAL;         // Air Flow Control Variable (LPM)
    rO2Flow_CV : REAL;          // O2 Flow Control Variable (LPM)
    rCO2Flow_CV : REAL;         // CO2 Flow Control Variable (LPM)
    rBasePump_CV : REAL;        // Base addition pump Control Variable (%)
    bAlarmDO_High : BOOL;       // DO High Alarm
    bAlarmDO_Low : BOOL;        // DO Low Alarm
    bAlarmpH_High : BOOL;       // pH High Alarm
    bAlarmpH_Low : BOOL;        // pH Low Alarm
    bControlActive : BOOL;      // Feedback signal indicating control loop is running
END_VAR

VAR
    // Internal PID controllers (instantiating standard PID FB)
    PID_DO : PID;
    PID_pH_Acid : PID;
    PID_pH_Base : PID;

    // Split range control variables
    rDO_CV_Total : REAL;
    rpH_CV_Total : REAL;

    // Tuning parameters (Internal)
    rDO_Kp : REAL := 2.5;
    rDO_Ti : REAL := 120.0;
    rDO_Td : REAL := 0.0;

    rpH_Kp : REAL := 1.8;
    rpH_Ti : REAL := 60.0;
    rpH_Td : REAL := 0.0;

    // Alarm Limits
    rDO_HighLimit : REAL := 60.0;
    rDO_LowLimit : REAL := 20.0;
    rpH_HighLimit : REAL := 7.4;
    rpH_LowLimit : REAL := 6.8;

    // Deadband for split range
    rpH_Deadband : REAL := 0.05;
END_VAR

// --- EXECUTION ---

IF bEmergencyStop THEN
    // Failsafe state
    rAgitatorSpeed_CV := 50.0; // Minimal agitation
    rAirFlow_CV := 1.0;        // Minimal air
    rO2Flow_CV := 0.0;
    rCO2Flow_CV := 0.0;
    rBasePump_CV := 0.0;
    bControlActive := FALSE;
    RETURN;
END_IF;

bControlActive := TRUE;

// DO Alarm Logic
bAlarmDO_High := rDO_PV > rDO_HighLimit;
bAlarmDO_Low := rDO_PV < rDO_LowLimit;

// pH Alarm Logic
bAlarmpH_High := rpH_PV > rpH_HighLimit;
bAlarmpH_Low := rpH_PV < rpH_LowLimit;

// DO Cascade Split-Range Control
// Total DO CV goes from 0 to 300%
// 0-100% : Agitator speed increases
// 100-200% : Air flow increases
// 200-300% : O2 flow increases
IF bEnableDOControl THEN
    PID_DO(
        EN := TRUE,
        PV := rDO_PV,
        SP := rDO_SP,
        KP := rDO_Kp,
        TN := rDO_Ti,
        TV := rDO_Td,
        Y_MAX := 300.0,
        Y_MIN := 0.0,
        Y => rDO_CV_Total
    );

    // Calculate individual control actions based on split range
    IF rDO_CV_Total <= 100.0 THEN
        rAgitatorSpeed_CV := (rDO_CV_Total / 100.0) * rAgitatorSpeed_Max;
        rAirFlow_CV := 0.0;
        rO2Flow_CV := 0.0;
    ELSIF rDO_CV_Total <= 200.0 THEN
        rAgitatorSpeed_CV := rAgitatorSpeed_Max;
        rAirFlow_CV := ((rDO_CV_Total - 100.0) / 100.0) * rAirFlow_Max;
        rO2Flow_CV := 0.0;
    ELSE
        rAgitatorSpeed_CV := rAgitatorSpeed_Max;
        rAirFlow_CV := rAirFlow_Max;
        rO2Flow_CV := ((rDO_CV_Total - 200.0) / 100.0) * rO2Flow_Max;
    END_IF;
ELSE
    rAgitatorSpeed_CV := 0.0;
    rAirFlow_CV := 0.0;
    rO2Flow_CV := 0.0;
END_IF;

// pH Split-Range Control
// Acid addition (via CO2 sparging) and Base addition (via pump)
IF bEnablepHControl THEN
    // Determine error
    rpH_CV_Total := rpH_PV - rpH_SP;

    IF rpH_CV_Total > rpH_Deadband THEN
        // pH is too high -> Add CO2 (Acid)
        PID_pH_Acid(
            EN := TRUE,
            PV := rpH_PV,
            SP := rpH_SP + rpH_Deadband,
            KP := rpH_Kp,
            TN := rpH_Ti,
            TV := rpH_Td,
            Y_MAX := 100.0,
            Y_MIN := 0.0,
            Y => rCO2Flow_CV
        );
        rBasePump_CV := 0.0;
    ELSIF rpH_CV_Total < -rpH_Deadband THEN
        // pH is too low -> Add Base
        PID_pH_Base(
            EN := TRUE,
            PV := -rpH_PV, // Inverted for positive action
            SP := -(rpH_SP - rpH_Deadband),
            KP := rpH_Kp,
            TN := rpH_Ti,
            TV := rpH_Td,
            Y_MAX := 100.0,
            Y_MIN := 0.0,
            Y => rBasePump_CV
        );
        rCO2Flow_CV := 0.0;
    ELSE
        rCO2Flow_CV := 0.0;
        rBasePump_CV := 0.0;
    END_IF;
ELSE
    rCO2Flow_CV := 0.0;
    rBasePump_CV := 0.0;
END_IF;

END_FUNCTION_BLOCK
