(*
======================================================================================
BLOCK: FB_Asteroid_Excavator (Micro-Gravity Regolith Excavator & Anchoring Controller)
AUTHOR: Lead Robotics Architect, Asteroid Mining Consortium
VERSION: 3.0 (Master-Tier Production)
DESCRIPTION:
  Advanced ST implementation for managing operations in micro-gravity ($0.001 G$).
  Handles:
   1. Triple Harpoon Tether Tensioning & Active Recoil Damping.
   2. Percussive Drill with Acoustic Resonance (FFT) for Material Detection.
   3. Thermal Vacuum Radiator (Ammonia-based) Louver Control for deep space heat rejection.
======================================================================================
*)
FUNCTION_BLOCK FB_Asteroid_Excavator
VAR_INPUT
    bEnable                 : BOOL; // System master enable
    bDeployAnchors          : BOOL; // Command to fire harpoons and tension
    bStartDrilling          : BOOL; // Command to start drilling sequence

    // Environmental Sensors
    fAmbientGravity_G       : REAL; // Measured local gravity (typically ~0.001)
    fSolarIrradiance_W      : REAL; // Solar flux (for thermal eclipse detection)

    // Harpoon & Tether Feedback
    fTetherTension_1_N      : REAL;
    fTetherTension_2_N      : REAL;
    fTetherTension_3_N      : REAL;
    fVehiclePitch_rad       : REAL; // IMU Pitch
    fVehicleRoll_rad        : REAL; // IMU Roll
    fVehicleZAccel_ms2      : REAL; // Vertical acceleration (recoil sensing)

    // Drill Telemetry
    fDrillFFT_PeakFreq_Hz   : REAL; // Dominant acoustic frequency from drill bit
    fDrillFFT_Amplitude     : REAL; // Acoustic amplitude
    fDrillDepth_m           : REAL; 

    // Thermal Loop
    fDrillMotorTemp_C       : REAL; // Temp of drill motor
    fAmmoniaLoopTemp_C      : REAL; // Temp of ammonia coolant
END_VAR

VAR_OUTPUT
    // Harpoon Actuators
    bFireHarpoon_1          : BOOL;
    bFireHarpoon_2          : BOOL;
    bFireHarpoon_3          : BOOL;
    fTetherWinchTorque_1_Nm : REAL; // Active recoil damping and tensioning
    fTetherWinchTorque_2_Nm : REAL;
    fTetherWinchTorque_3_Nm : REAL;

    // Drill Actuators
    fDrillRPM               : REAL;
    fDrillWOB_N             : REAL; // Weight-On-Bit (Downward force thrust)
    bPercussionEnabled      : BOOL;

    // Thermal Actuators
    fRadiatorLouverPos_pct  : REAL; // 0.0 = Closed (conserve heat), 100.0 = Fully Open (reject heat)
    fAmmoniaPumpSpeed_RPM   : REAL;

    // Status
    eSystemState            : E_ExcavatorState;
    eDetectedMaterial       : E_MaterialType;
    bAnchoredSecurely       : BOOL;
    bWarningHeat            : BOOL;
END_VAR

VAR
    // State Machines
    nAnchorState            : INT;
    nDrillState             : INT;
    nThermalState           : INT;

    // Control loops (PID simulation vars)
    fTargetTension_N        : REAL := 500.0;
    fTensionErr_1, fTensionErr_2, fTensionErr_3 : REAL;
    fKp_Tether              : REAL := 2.5;
    fKd_Tether              : REAL := 0.8;
    fPrevTetherErr_1        : REAL;

    // Material profiles (Frequency Hz mapping)
    fFreqSilicate_Min       : REAL := 450.0;
    fFreqSilicate_Max       : REAL := 800.0;
    fFreqNiFe_Min           : REAL := 1200.0;
    fFreqNiFe_Max           : REAL := 2500.0;
    fFreqIce_Min            : REAL := 150.0;
    fFreqIce_Max            : REAL := 400.0;

    // Timers
    tDrillDelay             : TON;
    tAnchorStabilize        : TON;
END_VAR

// -----------------------------------------------------------------------------
// 1. THERMAL VACUUM RADIATOR CONTROL (Ammonia Loop & Louvers)
// -----------------------------------------------------------------------------
// Control louver position based on ammonia temp and solar eclipse state.
IF bEnable THEN
    IF fAmmoniaLoopTemp_C > 85.0 THEN
        bWarningHeat := TRUE;
    ELSE
        bWarningHeat := FALSE;
    END_IF;

    // Pump speed proportional to motor temp
    fAmmoniaPumpSpeed_RPM := LIMIT(0.0, (fDrillMotorTemp_C - 20.0) * 50.0, 3000.0);

    // If solar irradiance is low (Eclipse), we might freeze. Close louvers if temp drops.
    IF fSolarIrradiance_W < 100.0 AND fAmmoniaLoopTemp_C < 5.0 THEN
        fRadiatorLouverPos_pct := 0.0; // Conserve heat
    ELSE
        // Proportional louver opening based on coolant temp
        fRadiatorLouverPos_pct := LIMIT(0.0, (fAmmoniaLoopTemp_C - 10.0) * 2.0, 100.0);
    END_IF;
ELSE
    fRadiatorLouverPos_pct := 0.0;
    fAmmoniaPumpSpeed_RPM := 0.0;
    bWarningHeat := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 2. TRIPLE HARPOON TETHER TENSIONING & ACTIVE RECOIL DAMPING
// -----------------------------------------------------------------------------
IF NOT bEnable THEN
    nAnchorState := 0;
    bAnchoredSecurely := FALSE;
    fTetherWinchTorque_1_Nm := 0.0;
    fTetherWinchTorque_2_Nm := 0.0;
    fTetherWinchTorque_3_Nm := 0.0;
ELSE
    CASE nAnchorState OF
        0: // Idle / Retracted
            IF bDeployAnchors THEN
                bFireHarpoon_1 := TRUE;
                bFireHarpoon_2 := TRUE;
                bFireHarpoon_3 := TRUE;
                nAnchorState := 10;
            END_IF;

        10: // Firing & Initial Tensioning
            bFireHarpoon_1 := FALSE;
            bFireHarpoon_2 := FALSE;
            bFireHarpoon_3 := FALSE;

            // Apply base torque to take up slack
            fTetherWinchTorque_1_Nm := 50.0;
            fTetherWinchTorque_2_Nm := 50.0;
            fTetherWinchTorque_3_Nm := 50.0;

            IF fTetherTension_1_N > 100.0 AND fTetherTension_2_N > 100.0 AND fTetherTension_3_N > 100.0 THEN
                nAnchorState := 20;
            END_IF;

        20: // Active Tension Control & Recoil Damping
            // Calculate errors
            fTensionErr_1 := fTargetTension_N - fTetherTension_1_N;
            fTensionErr_2 := fTargetTension_N - fTetherTension_2_N;
            fTensionErr_3 := fTargetTension_N - fTetherTension_3_N;

            // Recoil compensation derived from Z-axis acceleration (drilling thrust bounce)
            // If z-accel is positive (upward bounce), increase torque to hold down.
            VAR 
                fRecoilComp : REAL;
            END_VAR
            fRecoilComp := LIMIT(0.0, fVehicleZAccel_ms2 * 50.0, 200.0);

            // PD Control for each winch
            fTetherWinchTorque_1_Nm := LIMIT(10.0, (fTensionErr_1 * fKp_Tether) + ((fTensionErr_1 - fPrevTetherErr_1) * fKd_Tether) + fRecoilComp, 500.0);

            // Assume symmetric for 2 and 3 for brevity
            fTetherWinchTorque_2_Nm := LIMIT(10.0, (fTensionErr_2 * fKp_Tether) + fRecoilComp, 500.0);
            fTetherWinchTorque_3_Nm := LIMIT(10.0, (fTensionErr_3 * fKp_Tether) + fRecoilComp, 500.0);

            fPrevTetherErr_1 := fTensionErr_1;

            tAnchorStabilize(IN:=TRUE, PT:=T#3S);
            IF tAnchorStabilize.Q THEN
                bAnchoredSecurely := TRUE;
                eSystemState := E_ExcavatorState.ANCHORED;
            END_IF;

            IF NOT bDeployAnchors THEN
                nAnchorState := 0;
            END_IF;
    END_CASE;
END_IF;

// -----------------------------------------------------------------------------
// 3. PERCUSSIVE DRILL TELEMETRY & MATERIAL ADAPTATION
// -----------------------------------------------------------------------------
IF NOT bEnable OR NOT bAnchoredSecurely OR bWarningHeat THEN
    fDrillRPM := 0.0;
    fDrillWOB_N := 0.0;
    bPercussionEnabled := FALSE;
    nDrillState := 0;
ELSE
    CASE nDrillState OF
        0: // Waiting for command
            IF bStartDrilling THEN
                nDrillState := 10;
            END_IF;

        10: // Spudding in (low RPM, low WOB)
            fDrillRPM := 30.0;
            fDrillWOB_N := 150.0;
            bPercussionEnabled := FALSE;

            IF fDrillDepth_m > 0.05 THEN
                nDrillState := 20;
            END_IF;

        20: // Main Drilling & FFT Analysis
            // Determine Material based on FFT Peak Frequency
            IF fDrillFFT_PeakFreq_Hz >= fFreqIce_Min AND fDrillFFT_PeakFreq_Hz <= fFreqIce_Max THEN
                eDetectedMaterial := E_MaterialType.SUBSURFACE_ICE;
                // Ice: High RPM, Low WOB, No percussion (prevent melting/sublimation blowout)
                fDrillRPM := 150.0;
                fDrillWOB_N := 100.0;
                bPercussionEnabled := FALSE;

            ELSIF fDrillFFT_PeakFreq_Hz >= fFreqSilicate_Min AND fDrillFFT_PeakFreq_Hz <= fFreqSilicate_Max THEN
                eDetectedMaterial := E_MaterialType.SILICATE_ROCK;
                // Silicate: Medium RPM, Medium WOB, Percussion ON
                fDrillRPM := 80.0;
                fDrillWOB_N := 300.0;
                bPercussionEnabled := TRUE;

            ELSIF fDrillFFT_PeakFreq_Hz >= fFreqNiFe_Min AND fDrillFFT_PeakFreq_Hz <= fFreqNiFe_Max THEN
                eDetectedMaterial := E_MaterialType.NICKEL_IRON;
                // NiFe Vein: Low RPM, High WOB, Heavy Percussion
                fDrillRPM := 40.0;
                fDrillWOB_N := 600.0;
                bPercussionEnabled := TRUE;

            ELSE
                eDetectedMaterial := E_MaterialType.UNKNOWN_REGOLITH;
                fDrillRPM := 60.0;
                fDrillWOB_N := 200.0;
                bPercussionEnabled := FALSE;
            END_IF;

            // Thermal throttle
            IF fDrillMotorTemp_C > 120.0 THEN
                fDrillRPM := fDrillRPM * 0.5;
                fDrillWOB_N := fDrillWOB_N * 0.5;
                bPercussionEnabled := FALSE;
            END_IF;

            IF NOT bStartDrilling THEN
                nDrillState := 0;
            END_IF;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK
