FUNCTION_BLOCK FB_LINAC_ControlCore
TITLE = 'LINAC Klystron and Beam Steering Control'
VERSION : '2.4'

VAR_INPUT
    bSystemEnable : BOOL; // Main system run enable
    rTargetBeamEnergy_MeV : REAL; // Target energy in MeV
    rRF_DrivePower_kW : REAL; // Requested RF drive power
    bVacuumInterlock_OK : BOOL; // High vacuum status from Pirani/Ion gauges
    bWaterCooling_OK : BOOL; // Klystron and magnet cooling flow switches
    bRadiationDoor_Closed : BOOL; // Safety interlock for bunker
    rMagnetCurrentSetpoint_X : REAL; // Beam steering X-axis target current
    rMagnetCurrentSetpoint_Y : REAL; // Beam steering Y-axis target current
    tPulseDuration : TIME := T#5US; // Modulator pulse width
    rPulseRepetitionRate_Hz : REAL := 200.0; // PRF in Hz
END_VAR

VAR_OUTPUT
    bKlystron_HV_Enable : BOOL; // Thyratron trigger enable
    rKlystron_ForwardPower_kW : REAL; // Monitored forward power
    bBeamPermit : BOOL; // Beam injection permission to electron gun
    rMagnetCurrentActual_X : REAL; // Actual output to X steering coils
    rMagnetCurrentActual_Y : REAL; // Actual output to Y steering coils
    bFault_Vacuum : BOOL; 
    bFault_Cooling : BOOL;
    bFault_Safety : BOOL;
    iState : INT; // Current state machine state
END_VAR

VAR
    fbPulseTimer : TON;
    rInternalEnergySetpt : REAL := 0.0;
    rEnergyRampRate : REAL := 1.5; // MeV per sec
    tScanCycle : TIME := T#10MS;
    bInterlockChain_OK : BOOL;
    rModulatorVoltage_kV : REAL;
    iStepCounter : INT;
    xKlystronWarmupComplete : BOOL := FALSE;
    tWarmupTimer : TON;
END_VAR

//=============================================================================
// 1. Interlock and Safety Chain Processing
//=============================================================================
bFault_Vacuum := NOT bVacuumInterlock_OK;
bFault_Cooling := NOT bWaterCooling_OK;
bFault_Safety := NOT bRadiationDoor_Closed;

bInterlockChain_OK := bVacuumInterlock_OK AND bWaterCooling_OK AND bRadiationDoor_Closed;

IF NOT bInterlockChain_OK THEN
    bKlystron_HV_Enable := FALSE;
    bBeamPermit := FALSE;
    rMagnetCurrentActual_X := 0.0;
    rMagnetCurrentActual_Y := 0.0;
    iState := 99; // FAULT STATE
    RETURN;
END_IF;

//=============================================================================
// 2. Klystron Warm-up and RF Modulation
//=============================================================================
tWarmupTimer(IN := bSystemEnable AND bInterlockChain_OK, PT := T#5M);
xKlystronWarmupComplete := tWarmupTimer.Q;

IF xKlystronWarmupComplete AND bSystemEnable THEN
    IF iState = 0 OR iState = 99 THEN
        iState := 10; // WARMUP COMPLETE, READY
    END_IF;
ELSE
    iState := 0; // WARMING UP OR OFF
    bKlystron_HV_Enable := FALSE;
END_IF;

//=============================================================================
// 3. Beam Steering Electromagnet Mapping
//=============================================================================
// Simplified PID/Ramp for magnet current to avoid sudden deflection spikes
IF bSystemEnable THEN
    // Ramp X Axis
    IF rMagnetCurrentActual_X < rMagnetCurrentSetpoint_X THEN
        rMagnetCurrentActual_X := rMagnetCurrentActual_X + 0.05;
    ELSIF rMagnetCurrentActual_X > rMagnetCurrentSetpoint_X THEN
        rMagnetCurrentActual_X := rMagnetCurrentActual_X - 0.05;
    END_IF;

    // Ramp Y Axis
    IF rMagnetCurrentActual_Y < rMagnetCurrentSetpoint_Y THEN
        rMagnetCurrentActual_Y := rMagnetCurrentActual_Y + 0.05;
    ELSIF rMagnetCurrentActual_Y > rMagnetCurrentSetpoint_Y THEN
        rMagnetCurrentActual_Y := rMagnetCurrentActual_Y - 0.05;
    END_IF;
END_IF;

//=============================================================================
// 4. Klystron RF Power Delivery & Timing
//=============================================================================
IF iState = 10 AND rTargetBeamEnergy_MeV > 0.0 THEN
    // Determine required Modulator voltage based on target energy
    // v = k * sqrt(E)
    rModulatorVoltage_kV := 25.0 * SQRT(rTargetBeamEnergy_MeV);

    // Pulse Timing Generation
    fbPulseTimer(IN := NOT fbPulseTimer.Q, PT := REAL_TO_TIME(1000.0 / rPulseRepetitionRate_Hz));

    IF fbPulseTimer.Q THEN
        bKlystron_HV_Enable := TRUE; // Trigger pulse
        rKlystron_ForwardPower_kW := rRF_DrivePower_kW * 0.95; // Simulated efficiency
    ELSE
        bKlystron_HV_Enable := FALSE;
    END_IF;

    // Grant beam permit if RF is stable and magnets are near setpoints
    IF (ABS(rMagnetCurrentActual_X - rMagnetCurrentSetpoint_X) < 0.2) AND 
       (ABS(rMagnetCurrentActual_Y - rMagnetCurrentSetpoint_Y) < 0.2) THEN
        bBeamPermit := TRUE;
        iState := 20; // BEAM ON
    ELSE
        bBeamPermit := FALSE;
    END_IF;
ELSE
    bKlystron_HV_Enable := FALSE;
    rKlystron_ForwardPower_kW := 0.0;
    bBeamPermit := FALSE;
    IF iState = 20 THEN
        iState := 10;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
