FUNCTION_BLOCK "ExoReactor_Breadth"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Start : Bool;
      Stop : Bool;
      ReactorTemp : Real;
      TempSetpoint : Real;
      AgitatorCurrent : Real;
      AgitatorCurrentHighLimit : Real;
      ReactorPressure : Real;
      PressureHighLimit : Real;
      PressureCriticalLimit : Real;
      ProfinetStatusWord : Word;
   END_VAR
   VAR_OUTPUT 
      AgitatorCmd : Bool;
      ChilledWaterValve : Real;
      VentValve : Bool;
      EmergencyShutoff : Bool;
      FaultCode : Word;
   END_VAR
   VAR 
      PID_ChilledWater {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
      RunCmd : Bool;
      AgitatorOverload : Bool;
      PressureHigh : Bool;
      PressureCritical : Bool;
      CommFault : Bool;
      ReliefSeqStep : Int;
   END_VAR

BEGIN
// Profinet Diagnostics
#CommFault := (#ProfinetStatusWord <> 16#0000);

// Interlocks
#AgitatorOverload := #AgitatorCurrent > #AgitatorCurrentHighLimit;
#PressureHigh := #ReactorPressure > #PressureHighLimit;
#PressureCritical := #ReactorPressure > #PressureCriticalLimit;

IF #Stop OR #AgitatorOverload OR #PressureCritical OR #CommFault THEN
    #RunCmd := FALSE;
ELSIF #Start AND NOT #PressureHigh THEN
    #RunCmd := TRUE;
END_IF;

#AgitatorCmd := #RunCmd;

// Multi-stage pressure relief sequence
IF #PressureCritical THEN
    #ReliefSeqStep := 2;
ELSIF #PressureHigh THEN
    #ReliefSeqStep := 1;
ELSE
    #ReliefSeqStep := 0;
END_IF;

CASE #ReliefSeqStep OF
    0:
        #VentValve := FALSE;
        #EmergencyShutoff := FALSE;
    1:
        #VentValve := TRUE;
        #EmergencyShutoff := FALSE;
    2:
        #VentValve := TRUE;
        #EmergencyShutoff := TRUE;
END_CASE;

// PID Control
#PID_ChilledWater(
    Setpoint := #TempSetpoint,
    Input := #ReactorTemp,
    Reset := NOT #RunCmd,
    Output => #ChilledWaterValve
);

// Diagnostic Error Codes
#FaultCode := 16#0000;
IF #AgitatorOverload THEN #FaultCode := #FaultCode OR 16#0001; END_IF;
IF #PressureHigh THEN #FaultCode := #FaultCode OR 16#0002; END_IF;
IF #PressureCritical THEN #FaultCode := #FaultCode OR 16#0004; END_IF;
IF #CommFault THEN #FaultCode := #FaultCode OR 16#0008; END_IF;

END_FUNCTION_BLOCK
