FUNCTION_BLOCK "WaferSpinner_Mut2"
VERSION : 0.1
   VAR_INPUT
      execute : Bool;
      targetSpeed : Real;
      dispenseTime : Time;
      flowFeedback : Real; 
      targetFlow : Real;
      pnStatusWord : Word; // Profinet comms status
   END_VAR
   VAR_OUTPUT
      busy : Bool;
      done : Bool;
      error : Bool;
      errorID : Int; // 0=None, 1=PN Loss, 2=Servo Error, 3=Low Chem
      currentSpeed : Real;
      pumpControl : Real; 
   END_VAR
   VAR
      state : Int;
      timer : TON_TIME;
      pidInst : PID_Compact;
      pidEnable : Bool;
   END_VAR

BEGIN
   // Diagnostics
   IF (#pnStatusWord AND 16#0001) = 0 THEN
      #error := TRUE;
      #errorID := 1;
      #state := 99; // Fault state
   END_IF;

   #pidInst(Setpoint := #targetFlow, Input := #flowFeedback, Reset := NOT #pidEnable);

   CASE #state OF
      0: // Idle
         #error := FALSE;
         #errorID := 0;
         #busy := FALSE;
         #done := FALSE;
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pumpControl := 0.0;
         IF #execute AND NOT #error THEN
            #state := 10;
            #busy := TRUE;
         END_IF;

      10: // Spin Up
         #currentSpeed := #targetSpeed; 
         IF #currentSpeed >= #targetSpeed THEN
            #state := 20;
         END_IF;

      20: // Dispense with PID
         #pidEnable := TRUE;
         #pumpControl := #pidInst.Output;
         #timer(IN := TRUE, PT := #dispenseTime);
         IF #timer.Q THEN
            #pidEnable := FALSE;
            #pumpControl := 0.0;
            #timer(IN := FALSE, PT := #dispenseTime);
            #state := 30;
         END_IF;

      30: // Stop
         #currentSpeed := 0.0;
         #done := TRUE;
         #busy := FALSE;
         IF NOT #execute THEN
            #state := 0;
         END_IF;

      99: // Fault
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pumpControl := 0.0;
         #busy := FALSE;
         IF NOT #execute THEN // Reset fault
            #state := 0;
         END_IF;
   END_CASE;
END_FUNCTION_BLOCK
