FUNCTION_BLOCK FB_CigaretteMakerControl
VAR_INPUT
    bEnable : BOOL; // System enable
    bReset : BOOL; // Reset faults
    rMachineSpeedSetpoint : REAL; // Target machine speed (CPM)
    iMainEncoderPos : DINT; // Main machine encoder position
    rMicrowaveDensityRaw : REAL; // Raw analog value from microwave density scanner
    bFilterSupplyOK : BOOL; // Filter supply status
    bPaperTensionOK : BOOL; // Cigarette paper tension status
END_VAR
VAR_OUTPUT
    bSystemReady : BOOL;
    bRunning : BOOL;
    rActualSpeed : REAL;
    rTobaccoFeedRateCmd : REAL; // Command to tobacco feed motor
    bRejectValveCmd : BOOL; // High speed rejection valve command
    iTotalProduced : DINT;
    iTotalRejected : DINT;
    bFault : BOOL;
    iFaultCode : INT;
END_VAR
VAR
    rDensitySetpoint : REAL := 250.0; // mg/cm3
    rKp_Density : REAL := 1.5;
    rKi_Density : REAL := 0.5;
    rKd_Density : REAL := 0.1;
    rDensityError : REAL;
    rDensityErrorPrev : REAL;
    rDensityIntegral : REAL;
    rDensityDerivative : REAL;
    aDensityBuffer : ARRAY[0..255] OF REAL; 
    aRejectBuffer : ARRAY[0..255] OF BOOL; 
    iWriteIndex : INT := 0;
    iRejectionOffset : INT := 120; 
    iMachineState : INT := 0;
    rCalculatedWeight : REAL;
    bDefectDetected : BOOL;
    tRejectPulse : TON;
    iReadIndex : INT;
END_VAR

// State Machine
CASE iMachineState OF
    0: // INIT
        bSystemReady := FALSE;
        bRunning := FALSE;
        bFault := FALSE;
        rTobaccoFeedRateCmd := 0.0;
        bRejectValveCmd := FALSE;
        IF bEnable AND bFilterSupplyOK AND bPaperTensionOK THEN
            iMachineState := 10;
        END_IF;

    10: // READY
        bSystemReady := TRUE;
        IF bEnable AND (rMachineSpeedSetpoint > 0.0) THEN
            iMachineState := 20;
        ELSIF NOT bEnable THEN
            iMachineState := 0;
        END_IF;

    20: // RUNNING
        bRunning := TRUE;
        rActualSpeed := rMachineSpeedSetpoint; 

        rDensityError := rDensitySetpoint - rMicrowaveDensityRaw;
        rDensityIntegral := rDensityIntegral + rDensityError;

        IF rDensityIntegral > 1000.0 THEN rDensityIntegral := 1000.0; END_IF;
        IF rDensityIntegral < -1000.0 THEN rDensityIntegral := -1000.0; END_IF;

        rDensityDerivative := rDensityError - rDensityErrorPrev;
        rDensityErrorPrev := rDensityError;

        rTobaccoFeedRateCmd := (rKp_Density * rDensityError) + 
                               (rKi_Density * rDensityIntegral) + 
                               (rKd_Density * rDensityDerivative);

        rTobaccoFeedRateCmd := rTobaccoFeedRateCmd + (rActualSpeed * 0.05);
        IF rTobaccoFeedRateCmd < 0.0 THEN rTobaccoFeedRateCmd := 0.0; END_IF;
        IF rTobaccoFeedRateCmd > 100.0 THEN rTobaccoFeedRateCmd := 100.0; END_IF;

        rCalculatedWeight := rMicrowaveDensityRaw * 1.2; 
        bDefectDetected := (rCalculatedWeight < 230.0) OR (rCalculatedWeight > 270.0);

        iWriteIndex := iWriteIndex + 1;
        IF iWriteIndex > 255 THEN iWriteIndex := 0; END_IF;

        aDensityBuffer[iWriteIndex] := rCalculatedWeight;
        aRejectBuffer[iWriteIndex] := bDefectDetected;

        iReadIndex := iWriteIndex - iRejectionOffset;
        IF iReadIndex < 0 THEN
            iReadIndex := iReadIndex + 256;
        END_IF;

        IF aRejectBuffer[iReadIndex] THEN
            bRejectValveCmd := TRUE;
            iTotalRejected := iTotalRejected + 1;
            aRejectBuffer[iReadIndex] := FALSE; 
        ELSE
            bRejectValveCmd := FALSE;
        END_IF;

        iTotalProduced := iTotalProduced + 1; 

        IF NOT bFilterSupplyOK THEN
            bFault := TRUE;
            iFaultCode := 101; 
            iMachineState := 99;
        END_IF;
        IF NOT bPaperTensionOK THEN
            bFault := TRUE;
            iFaultCode := 102; 
            iMachineState := 99;
        END_IF;

    99: // FAULT
        bRunning := FALSE;
        bSystemReady := FALSE;
        rTobaccoFeedRateCmd := 0.0;
        bRejectValveCmd := FALSE;
        IF bReset THEN
            bFault := FALSE;
            iFaultCode := 0;
            iMachineState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
