FUNCTION_BLOCK FB_Bioethanol_Fermentation_Control
TITLE = 'Bioethanol Fermentation Advanced Control'
VERSION : '2.1'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    // Physical I/O - Sensors
    rSaccharification_Temp : REAL; // PT100 temperature in C
    rSaccharification_pH : REAL; // pH level
    rYeastProp_Temp : REAL;
    rYeastProp_pH : REAL;
    rYeastProp_DO : REAL; // Dissolved Oxygen %
    rMainFerm_Temp : REAL;
    rMainFerm_Level : REAL; // Tank level in meters
    rDistillation_TopTemp : REAL; // Reflux column top temp
    rDistillation_BottomTemp : REAL; // Reflux column bottom temp
    bEmergencyStop : BOOL;
    bStartSequence : BOOL;
END_VAR

VAR_OUTPUT
    // Physical I/O - Actuators
    rSaccharification_Enzyme_Pump : REAL; // 0-100% speed
    rYeastProp_Acid_Pump : REAL; // pH buffering
    rYeastProp_Base_Pump : REAL;
    rYeastProp_Agitator : REAL;
    rMainFerm_CoolingValve : REAL; // 0-100% open
    rDistillation_RefluxValve : REAL;
    rDistillation_SteamValve : REAL;
    bSystemFault : BOOL;
    iCurrentState : INT;
END_VAR

VAR
    // Internal Variables & Timers
    tSaccharificationTimer : TON;
    tYeastPropTimer : TON;
    tMainFermTimer : TON;

    // PID Internal States (Simplified)
    rpH_Error : REAL;
    rpH_Kp : REAL := 2.5;
    rpH_Ki : REAL := 0.1;
    rpH_Integral : REAL := 0.0;

    rTemp_Error : REAL;
    rTemp_Kp : REAL := 5.0;

    rReflux_Error : REAL;

    eState : (IDLE, SACCHARIFICATION, YEAST_PROPAGATION, MAIN_FERMENTATION, DISTILLATION, FAULT) := IDLE;
END_VAR

// ---------------------------------------------------------
// MAIN CONTROL LOGIC
// ---------------------------------------------------------

// Global Safety Interlock
IF bEmergencyStop THEN
    rSaccharification_Enzyme_Pump := 0.0;
    rYeastProp_Acid_Pump := 0.0;
    rYeastProp_Base_Pump := 0.0;
    rYeastProp_Agitator := 0.0;
    rMainFerm_CoolingValve := 0.0;
    rDistillation_RefluxValve := 100.0; // Full reflux on E-Stop
    rDistillation_SteamValve := 0.0;
    bSystemFault := TRUE;
    eState := FAULT;
    RETURN;
END_IF;

CASE eState OF
    IDLE:
        iCurrentState := 0;
        IF bStartSequence AND NOT bSystemFault THEN
            eState := SACCHARIFICATION;
        END_IF;

    SACCHARIFICATION:
        iCurrentState := 1;
        // Enzyme Dosing Logic based on temperature
        IF rSaccharification_Temp >= 60.0 AND rSaccharification_Temp <= 65.0 THEN
            rSaccharification_Enzyme_Pump := 50.0; // Optimal temp, standard dosing
        ELSIF rSaccharification_Temp < 60.0 THEN
            rSaccharification_Enzyme_Pump := 10.0; // Slow dosing
        ELSE
            rSaccharification_Enzyme_Pump := 0.0; // Stop dosing, too hot (denaturation risk)
        END_IF;

        tSaccharificationTimer(IN:=TRUE, PT:=T#120M); // 2 Hours
        IF tSaccharificationTimer.Q THEN
            tSaccharificationTimer(IN:=FALSE); // Reset
            rSaccharification_Enzyme_Pump := 0.0;
            eState := YEAST_PROPAGATION;
        END_IF;

    YEAST_PROPAGATION:
        iCurrentState := 2;
        // Agitation based on DO
        IF rYeastProp_DO < 30.0 THEN
            rYeastProp_Agitator := 80.0; // Increase agitation for O2 transfer
        ELSE
            rYeastProp_Agitator := 40.0; // Maintenance agitation
        END_IF;

        // pH Buffering Logic (Target pH 4.5)
        rpH_Error := 4.5 - rYeastProp_pH;
        IF rpH_Error > 0.5 THEN // Too acidic
            rYeastProp_Base_Pump := rpH_Error * rpH_Kp;
            rYeastProp_Acid_Pump := 0.0;
        ELSIF rpH_Error < -0.5 THEN // Too alkaline
            rYeastProp_Acid_Pump := ABS(rpH_Error) * rpH_Kp;
            rYeastProp_Base_Pump := 0.0;
        ELSE
            rYeastProp_Acid_Pump := 0.0;
            rYeastProp_Base_Pump := 0.0;
        END_IF;

        tYeastPropTimer(IN:=TRUE, PT:=T#48H); // 48 Hours prop time
        IF tYeastPropTimer.Q THEN
            tYeastPropTimer(IN:=FALSE);
            rYeastProp_Agitator := 0.0;
            eState := MAIN_FERMENTATION;
        END_IF;

    MAIN_FERMENTATION:
        iCurrentState := 3;
        // Exothermic reaction cooling control (Target 32.0 C)
        rTemp_Error := rMainFerm_Temp - 32.0;
        IF rTemp_Error > 0.0 THEN
            rMainFerm_CoolingValve := rTemp_Error * rTemp_Kp; // Proportional cooling
            IF rMainFerm_CoolingValve > 100.0 THEN rMainFerm_CoolingValve := 100.0; END_IF;
        ELSE
            rMainFerm_CoolingValve := 0.0;
        END_IF;

        tMainFermTimer(IN:=TRUE, PT:=T#72H);
        IF tMainFermTimer.Q THEN
            tMainFermTimer(IN:=FALSE);
            rMainFerm_CoolingValve := 100.0; // Chill before distillation
            eState := DISTILLATION;
        END_IF;

    DISTILLATION:
        iCurrentState := 4;
        // Distillation Column Reflux Loop (Target Top Temp 78.3 C - Ethanol Boiling Point)
        rReflux_Error := rDistillation_TopTemp - 78.3;

        // If top temp is too high (water vapor), increase reflux (send liquid back down)
        IF rReflux_Error > 0.2 THEN
            rDistillation_RefluxValve := 100.0; // Full reflux
            rDistillation_SteamValve := 40.0; // Reduce steam
        // If top temp is too low, decrease reflux, increase steam
        ELSIF rReflux_Error < -0.2 THEN
            rDistillation_RefluxValve := 20.0; // Minimum reflux to maintain tray liquid
            rDistillation_SteamValve := 80.0; // Increase steam
        ELSE
            // Steady state
            rDistillation_RefluxValve := 50.0;
            rDistillation_SteamValve := 60.0;
        END_IF;

    FAULT:
        iCurrentState := 99;
        // Await manual reset
        IF NOT bEmergencyStop THEN
            bSystemFault := FALSE;
            eState := IDLE;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
