FUNCTION_BLOCK FB_PWR_PrimaryCoolantControl
TITLE = 'Nuclear Submarine PWR Primary Coolant Regulation'
VERSION : '2.5'

(* 
  This function block manages the primary coolant loop of a naval pressurized water reactor.
  It controls Main Coolant Pump (MCP) speed to maintain optimal delta-T across the core,
  regulates pressurizer pressure using heaters and spray valves, and monitors critical
  safety limits to initiate an automatic scram (reactor trip) if necessary.
*)

VAR_INPUT
    rReactorPower_Pct      : REAL;   (* Reactor thermal power (0.0 to 100.0 %) *)
    rCoreInletTemp_C       : REAL;   (* Primary coolant core inlet temperature (deg C) *)
    rCoreOutletTemp_C      : REAL;   (* Primary coolant core outlet temperature (deg C) *)
    rPrimaryPressure_MPa   : REAL;   (* Primary loop pressure (MPa) *)
    rMCPSpeedFeedback_RPM  : REAL;   (* Main Coolant Pump speed feedback (RPM) *)
    rSG_Level_Pct          : REAL;   (* Steam Generator water level (0.0 to 100.0 %) *)
    bExternalScram         : BOOL;   (* External scram command *)
    bAckAlarms             : BOOL;   (* Acknowledge alarms *)
    tCycleTime_ms          : REAL := 10.0; (* Execution cycle time in ms *)
END_VAR

VAR_OUTPUT
    rMCPSpeedSetpoint_RPM  : REAL;   (* Commanded MCP speed (RPM) *)
    rPressurizerHeater_Pct : REAL;   (* Proportional heater command (0.0 to 100.0 %) *)
    bPressurizerSprayValve : BOOL;   (* Spray valve open command *)
    bScramInitiated        : BOOL;   (* Reactor scram triggered *)
    bAlarm_HighTemp        : BOOL;   (* High temperature alarm flag *)
    bAlarm_HighPressure    : BOOL;   (* High pressure alarm flag *)
    bAlarm_LowPressure     : BOOL;   (* Low pressure alarm flag *)
    bAlarm_MCPTrip         : BOOL;   (* Main coolant pump trip alarm *)
END_VAR

VAR
    rTargetDeltaT          : REAL;   (* Calculated target delta T based on power *)
    rActualDeltaT          : REAL;   (* Actual core delta T *)
    rSpeedError            : REAL;   (* Speed error for MCP PI controller *)
    rSpeedIntegral         : REAL;   (* Integral term for MCP PI *)
    rKp_MCP                : REAL := 15.5;  (* Proportional gain for MCP *)
    rKi_MCP                : REAL := 2.2;   (* Integral gain for MCP *)
    rMaxMCPSpeed           : REAL := 3600.0; (* Max pump speed in RPM *)
    rMinMCPSpeed           : REAL := 450.0;  (* Min pump speed in RPM (decay heat removal) *)

    rNominalPressure       : REAL := 15.5;   (* Nominal primary pressure (MPa) *)
    rPressureError         : REAL;

    bScramLatch            : BOOL := FALSE;
END_VAR

VAR CONSTANT
    MAX_CORE_OUTLET_TEMP   : REAL := 320.0;  (* Deg C, scram limit *)
    MAX_PRIMARY_PRESSURE   : REAL := 17.2;   (* MPa, scram limit *)
    MIN_PRIMARY_PRESSURE   : REAL := 12.5;   (* MPa, scram limit *)
    SCRAM_PUMP_SPEED       : REAL := 450.0;  (* RPM, minimal flow post-scram *)
END_VAR

(* --- Safety & Scram Logic --- *)
IF rCoreOutletTemp_C > MAX_CORE_OUTLET_TEMP THEN
    bAlarm_HighTemp := TRUE;
END_IF;

IF rPrimaryPressure_MPa > MAX_PRIMARY_PRESSURE THEN
    bAlarm_HighPressure := TRUE;
ELSIF rPrimaryPressure_MPa < MIN_PRIMARY_PRESSURE THEN
    bAlarm_LowPressure := TRUE;
END_IF;

IF (bAlarm_HighTemp OR bAlarm_HighPressure OR bAlarm_LowPressure OR bExternalScram) THEN
    bScramLatch := TRUE;
END_IF;

bScramInitiated := bScramLatch;

(* --- Main Coolant Pump Speed Control --- *)
IF bScramLatch THEN
    (* Post-scram decay heat removal mode *)
    rMCPSpeedSetpoint_RPM := SCRAM_PUMP_SPEED;
    rSpeedIntegral := 0.0; (* Reset integral windup *)
ELSE
    (* Normal operations: calculate required flow based on power level *)
    rTargetDeltaT := rReactorPower_Pct * 0.35; (* Empirical thermal curve *)
    rActualDeltaT := rCoreOutletTemp_C - rCoreInletTemp_C;

    (* Cascade control: temperature error drives flow demand *)
    rSpeedError := (rActualDeltaT - rTargetDeltaT) * 50.0; 

    rSpeedIntegral := rSpeedIntegral + (rSpeedError * rKi_MCP * (tCycleTime_ms / 1000.0));

    (* Anti-windup limits *)
    IF rSpeedIntegral > rMaxMCPSpeed THEN
        rSpeedIntegral := rMaxMCPSpeed;
    ELSIF rSpeedIntegral < 0.0 THEN
        rSpeedIntegral := 0.0;
    END_IF;

    rMCPSpeedSetpoint_RPM := (rSpeedError * rKp_MCP) + rSpeedIntegral + rMinMCPSpeed;

    (* Saturate MCP Output *)
    IF rMCPSpeedSetpoint_RPM > rMaxMCPSpeed THEN
        rMCPSpeedSetpoint_RPM := rMaxMCPSpeed;
    ELSIF rMCPSpeedSetpoint_RPM < rMinMCPSpeed THEN
        rMCPSpeedSetpoint_RPM := rMinMCPSpeed;
    END_IF;
END_IF;

(* --- Pressurizer Control --- *)
rPressureError := rNominalPressure - rPrimaryPressure_MPa;

IF rPressureError > 0.2 THEN
    (* Pressure too low -> activate proportional heaters *)
    rPressurizerHeater_Pct := rPressureError * 150.0; 
    IF rPressurizerHeater_Pct > 100.0 THEN
        rPressurizerHeater_Pct := 100.0;
    END_IF;
    bPressurizerSprayValve := FALSE;
ELSIF rPressureError < -0.2 THEN
    (* Pressure too high -> deactivate heaters, open spray valve *)
    rPressurizerHeater_Pct := 0.0;
    bPressurizerSprayValve := TRUE;
ELSE
    (* Deadband *)
    rPressurizerHeater_Pct := 0.0;
    bPressurizerSprayValve := FALSE;
END_IF;

(* --- Alarm Acknowledgement --- *)
IF bAckAlarms AND NOT (rCoreOutletTemp_C > MAX_CORE_OUTLET_TEMP) THEN
    bAlarm_HighTemp := FALSE;
END_IF;

IF bAckAlarms AND NOT (rPrimaryPressure_MPa > MAX_PRIMARY_PRESSURE) THEN
    bAlarm_HighPressure := FALSE;
END_IF;

IF bAckAlarms AND NOT (rPrimaryPressure_MPa < MIN_PRIMARY_PRESSURE) THEN
    bAlarm_LowPressure := FALSE;
END_IF;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_FoilMill_AGC_Tension
TITLE = 'Aluminum Foil Cold Rolling Mill - AGC and Tension Control'
// Highly complex control scenario for Aluminum Foil Cold Rolling Mill
// Integrates Hydraulic Roll Bite Profiling, X-Ray Thickness Feedback Cascades,
// and Tandem Coiler Tension Control.

VAR_INPUT
    bEnable : BOOL; // System enable
    rTargetThickness : REAL; // Target exit thickness (mm)
    rEntryThickness : REAL; // Measured entry thickness (mm)
    rExitThicknessXRay : REAL; // Measured exit thickness from X-Ray (mm)
    rLineSpeedRef : REAL; // Reference line speed (m/min)
    rUncoilerTensionRef : REAL; // Reference entry tension (N)
    rCoilerTensionRef : REAL; // Reference exit tension (N)
    rHydraulicPressureFbk : REAL; // Feedback from hydraulic roll force (bar)
    bRollCoolingOn : BOOL; // Roll cooling system status
    rMaterialWidth : REAL; // Foil width (mm)
    rMaterialAlloyFactor : REAL; // Hardness/Alloy compensation factor
END_VAR

VAR_OUTPUT
    rHydraulicValveCmd : REAL; // Command to hydraulic servo valve (%)
    rUncoilerTorqueCmd : REAL; // Command to uncoiler drive (Nm)
    rCoilerTorqueCmd : REAL; // Command to coiler drive (Nm)
    rMainDriveSpeedCmd : REAL; // Command to mill main drive (rpm)
    bCoolingSprayCmd : BOOL; // Command to cooling spray manifold
    bThicknessAlarm : BOOL; // Out of tolerance alarm
    bTensionAlarm : BOOL; // Tension loss or over-tension alarm
END_VAR

VAR
    // Internal States and PI Controllers
    rThicknessError : REAL;
    rThicknessErrorIntegral : REAL;
    rThicknessErrorPrev : REAL;

    rForceSetpoint : REAL;
    rForceError : REAL;
    rForceErrorIntegral : REAL;

    rUncoilerTensionError : REAL;
    rUncoilerTensionIntegral : REAL;

    rCoilerTensionError : REAL;
    rCoilerTensionIntegral : REAL;

    // Tuning Parameters
    Kp_Thick : REAL := 50.0;
    Ki_Thick : REAL := 10.0;
    Kd_Thick : REAL := 2.0;

    Kp_Force : REAL := 2.5;
    Ki_Force : REAL := 0.5;

    Kp_Tension : REAL := 15.0;
    Ki_Tension : REAL := 3.0;

    // Limits
    rMaxHydraulicValveCmd : REAL := 100.0;
    rMinHydraulicValveCmd : REAL := -100.0;
    rMaxThicknessError : REAL := 0.05; // 50 microns limit

    // Constants
    dt : REAL := 0.01; // 10ms task cycle time
END_VAR

// Implementation
IF NOT bEnable THEN
    rHydraulicValveCmd := 0.0;
    rUncoilerTorqueCmd := 0.0;
    rCoilerTorqueCmd := 0.0;
    rMainDriveSpeedCmd := 0.0;
    bCoolingSprayCmd := FALSE;
    bThicknessAlarm := FALSE;
    bTensionAlarm := FALSE;
    rThicknessErrorIntegral := 0.0;
    rForceErrorIntegral := 0.0;
    rUncoilerTensionIntegral := 0.0;
    rCoilerTensionIntegral := 0.0;
    RETURN;
END_IF;

// 1. X-Ray Thickness Feedback Cascade (Outer Loop)
// Calculate the error between target and actual exit thickness
rThicknessError := rTargetThickness - rExitThicknessXRay;

// Alarm Check
IF ABS(rThicknessError) > rMaxThicknessError THEN
    bThicknessAlarm := TRUE;
ELSE
    bThicknessAlarm := FALSE;
END_IF;

// PID for Thickness Control yielding a Force Delta Setpoint
rThicknessErrorIntegral := rThicknessErrorIntegral + (rThicknessError * dt);
rForceSetpoint := (Kp_Thick * rThicknessError) + (Ki_Thick * rThicknessErrorIntegral) + (Kd_Thick * (rThicknessError - rThicknessErrorPrev) / dt);
rThicknessErrorPrev := rThicknessError;

// Add base force based on entry thickness and alloy factor
rForceSetpoint := rForceSetpoint + (rEntryThickness * rMaterialAlloyFactor * rMaterialWidth * 1.5);

// 2. Automatic Gauge Control (AGC) Hydraulic Roll Bite Profiling (Inner Loop)
rForceError := rForceSetpoint - rHydraulicPressureFbk;
rForceErrorIntegral := rForceErrorIntegral + (rForceError * dt);

rHydraulicValveCmd := (Kp_Force * rForceError) + (Ki_Force * rForceErrorIntegral);

// Anti-windup and limit
IF rHydraulicValveCmd > rMaxHydraulicValveCmd THEN
    rHydraulicValveCmd := rMaxHydraulicValveCmd;
    rForceErrorIntegral := rForceErrorIntegral - (rForceError * dt); // Anti-windup
ELSIF rHydraulicValveCmd < rMinHydraulicValveCmd THEN
    rHydraulicValveCmd := rMinHydraulicValveCmd;
    rForceErrorIntegral := rForceErrorIntegral - (rForceError * dt);
END_IF;

// Roll cooling integration
IF rHydraulicPressureFbk > (rForceSetpoint * 0.9) AND bRollCoolingOn THEN
    bCoolingSprayCmd := TRUE;
ELSE
    bCoolingSprayCmd := FALSE;
END_IF;

// 3. Tandem Coiler Tension Control
// Assuming simulated feedback from tension meters
rUncoilerTensionError := rUncoilerTensionRef - (rUncoilerTorqueCmd * 0.1); 
rUncoilerTensionIntegral := rUncoilerTensionIntegral + (rUncoilerTensionError * dt);
rUncoilerTorqueCmd := (Kp_Tension * rUncoilerTensionError) + (Ki_Tension * rUncoilerTensionIntegral) + (rLineSpeedRef * 0.5);

rCoilerTensionError := rCoilerTensionRef - (rCoilerTorqueCmd * 0.1);
rCoilerTensionIntegral := rCoilerTensionIntegral + (rCoilerTensionError * dt);
rCoilerTorqueCmd := (Kp_Tension * rCoilerTensionError) + (Ki_Tension * rCoilerTensionIntegral) + (rLineSpeedRef * 0.5);

rMainDriveSpeedCmd := rLineSpeedRef * 1.05;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_CoffeeRoasterControl
VAR_INPUT
    bEnable : BOOL; // System enable
    bStartRoast : BOOL; // Start roasting cycle
    bEStop : BOOL; // Emergency stop
    rDrumTempActual : REAL; // Actual drum temperature (C)
    rExhaustTempActual : REAL; // Actual exhaust temperature (C)
    rCyclonePressure : REAL; // Cyclone extraction pressure (mbar)
    rBeanTempActual : REAL; // Actual bean temperature (C)
    iRecipeID : INT; // Current recipe profile ID
    rGasPressure : REAL; // Inlet gas pressure (mbar)
END_VAR

VAR_OUTPUT
    bBurnerIgnition : BOOL; // Command to ignite burner
    rGasValvePos : REAL; // Gas proportional valve (0-100%)
    rDrumMotorSpeed : REAL; // Drum motor VFD speed (0-100%)
    rExhaustFanSpeed : REAL; // Exhaust fan VFD speed (0-100%)
    bCoolingTrayFan : BOOL; // Cooling tray fan
    bCoolingTrayStirrer : BOOL; // Cooling tray stirrer
    bQuenchValve : BOOL; // Emergency water quench valve
    bChaffRotaryValve : BOOL; // Chaff collection rotary valve
    eSystemState : INT; // Current state of the roasting system
    bAlarmActive : BOOL; // Any alarm active
END_VAR

VAR
    // PID for Drum Temperature
    PID_DrumTemp : PID;
    rDrumTempSetpoint : REAL;

    // PID for Cyclone Pressure
    PID_Cyclone : PID;
    rCyclonePressureSP : REAL := -12.5; // Target mbar

    // Timers
    TMR_RoastDuration : TON;
    TMR_Ignition : TON;
    TMR_QuenchDuration : TON;
    TMR_CoolingDuration : TON;

    // Internal States
    STATE_IDLE : INT := 0;
    STATE_PURGE : INT := 10;
    STATE_IGNITION : INT := 20;
    STATE_PREHEAT : INT := 30;
    STATE_CHARGE : INT := 40;
    STATE_DRYING : INT := 50;
    STATE_MAILLARD : INT := 60;
    STATE_FIRST_CRACK : INT := 70;
    STATE_DEVELOPMENT : INT := 80;
    STATE_DROP : INT := 90;
    STATE_COOLING : INT := 100;
    STATE_QUENCH : INT := 999;

    iCurrentState : INT := 0;

    // Alarms and Limits
    rMaxDrumTemp : REAL := 280.0;
    rMaxBeanTemp : REAL := 250.0;
    rMinGasPressure : REAL := 20.0;

    bOverTempAlarm : BOOL;
    bGasPressureAlarm : BOOL;
END_VAR

// Alarm Monitoring
bOverTempAlarm := (rDrumTempActual > rMaxDrumTemp) OR (rBeanTempActual > rMaxBeanTemp);
bGasPressureAlarm := rGasPressure < rMinGasPressure;
bAlarmActive := bOverTempAlarm OR bGasPressureAlarm OR bEStop;

IF bAlarmActive OR bEStop THEN
    iCurrentState := STATE_QUENCH;
END_IF;

// State Machine
CASE iCurrentState OF
    STATE_IDLE:
        bBurnerIgnition := FALSE;
        rGasValvePos := 0.0;
        rDrumMotorSpeed := 0.0;
        rExhaustFanSpeed := 0.0;
        bCoolingTrayFan := FALSE;
        bCoolingTrayStirrer := FALSE;
        bQuenchValve := FALSE;
        bChaffRotaryValve := FALSE;

        IF bEnable AND bStartRoast AND NOT bAlarmActive THEN
            iCurrentState := STATE_PURGE;
            TMR_Ignition(IN := FALSE);
        END_IF;

    STATE_PURGE:
        rExhaustFanSpeed := 100.0;
        rDrumMotorSpeed := 50.0;
        TMR_Ignition(IN := TRUE, PT := T#30s);

        IF TMR_Ignition.Q THEN
            iCurrentState := STATE_IGNITION;
            TMR_Ignition(IN := FALSE);
        END_IF;

    STATE_IGNITION:
        bBurnerIgnition := TRUE;
        rGasValvePos := 20.0; // Low fire
        TMR_Ignition(IN := TRUE, PT := T#5s);

        IF TMR_Ignition.Q THEN
            iCurrentState := STATE_PREHEAT;
        END_IF;

    STATE_PREHEAT:
        // Ramp to target charge temp based on recipe
        rDrumTempSetpoint := 200.0; // Example static, would be recipe driven
        PID_DrumTemp(ACT := rDrumTempActual, SET := rDrumTempSetpoint, KP := 2.5, TN := T#10s, TV := T#2s);
        rGasValvePos := PID_DrumTemp.OUT;

        IF rDrumTempActual >= 195.0 THEN
            iCurrentState := STATE_CHARGE;
        END_IF;

    STATE_CHARGE:
        // Wait for beans to drop into drum
        // Simulating charge phase
        rGasValvePos := 0.0; // Cut gas briefly
        iCurrentState := STATE_DRYING;
        TMR_RoastDuration(IN := FALSE);

    STATE_DRYING:
        TMR_RoastDuration(IN := TRUE, PT := T#20m);
        rDrumTempSetpoint := 150.0;
        PID_DrumTemp(ACT := rBeanTempActual, SET := rDrumTempSetpoint, KP := 1.8, TN := T#15s);
        rGasValvePos := PID_DrumTemp.OUT;

        IF rBeanTempActual >= 150.0 THEN
            iCurrentState := STATE_MAILLARD;
        END_IF;

    STATE_MAILLARD:
        rDrumTempSetpoint := 200.0;
        PID_DrumTemp(ACT := rBeanTempActual, SET := rDrumTempSetpoint, KP := 2.0, TN := T#12s);
        rGasValvePos := PID_DrumTemp.OUT;

        IF rBeanTempActual >= 195.0 THEN
            iCurrentState := STATE_FIRST_CRACK;
        END_IF;

    STATE_FIRST_CRACK:
        // Modulate heat to avoid crashing the roast
        rGasValvePos := rGasValvePos * 0.8;
        IF rBeanTempActual >= 205.0 THEN
            iCurrentState := STATE_DEVELOPMENT;
        END_IF;

    STATE_DEVELOPMENT:
        // Final development phase
        rGasValvePos := 15.0; // Low fire
        IF rBeanTempActual >= 215.0 THEN // Drop temp
            iCurrentState := STATE_DROP;
        END_IF;

    STATE_DROP:
        bBurnerIgnition := FALSE;
        rGasValvePos := 0.0;
        rDrumMotorSpeed := 100.0; // Eject beans
        bCoolingTrayFan := TRUE;
        bCoolingTrayStirrer := TRUE;
        iCurrentState := STATE_COOLING;
        TMR_CoolingDuration(IN := FALSE);

    STATE_COOLING:
        TMR_CoolingDuration(IN := TRUE, PT := T#4m);
        IF TMR_CoolingDuration.Q THEN
            bCoolingTrayFan := FALSE;
            bCoolingTrayStirrer := FALSE;
            rDrumMotorSpeed := 0.0;
            rExhaustFanSpeed := 0.0;
            iCurrentState := STATE_IDLE;
        END_IF;

    STATE_QUENCH:
        // Emergency cascade
        bBurnerIgnition := FALSE;
        rGasValvePos := 0.0;
        rExhaustFanSpeed := 100.0; // Full exhaust
        rDrumMotorSpeed := 0.0;

        // If overtemp, activate quench valve
        IF bOverTempAlarm THEN
            bQuenchValve := TRUE;
            TMR_QuenchDuration(IN := TRUE, PT := T#1m);
            IF TMR_QuenchDuration.Q THEN
                bQuenchValve := FALSE;
            END_IF;
        END_IF;

        IF NOT bAlarmActive AND NOT bEStop THEN
            iCurrentState := STATE_IDLE;
        END_IF;
END_CASE;

// Cyclone extraction pressure control (runs parallel to state machine)
IF iCurrentState >= STATE_PURGE AND iCurrentState <= STATE_DROP THEN
    PID_Cyclone(ACT := rCyclonePressure, SET := rCyclonePressureSP, KP := 1.0, TN := T#5s);
    rExhaustFanSpeed := PID_Cyclone.OUT;
    bChaffRotaryValve := TRUE; // Run rotary valve during roasting
ELSE
    bChaffRotaryValve := FALSE;
END_IF;

eSystemState := iCurrentState;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_MoltenSaltReceiverControl
TITLE = 'Solar Tower Molten Salt Receiver Complex Control'
VERSION : '1.1'

VAR_INPUT
    rPeakFlux_kWm2 : REAL; (* Peak solar flux from heliostat aiming *)
    rColdTankLevel_m : REAL;
    rHotTankLevel_m : REAL;
    rReceiverInletTemp_C : REAL;
    rReceiverOutletTemp_C : REAL;
    rSaltFlowRate_kg_s : REAL;
    bEmergencyStop : BOOL;
    bWeatherWarning : BOOL;
    aTraceHeatingTemps_C : ARRAY[1..10] OF REAL; (* Temperatures along the pipe *)
END_VAR

VAR_OUTPUT
    rColdSaltPumpSpeed_RPM : REAL;
    rHotSaltValvePos_Pct : REAL;
    bHeliostatDefocusCmd : BOOL;
    rTargetAimingOffset_m : REAL;
    aTraceHeatingCmd : ARRAY[1..10] OF BOOL;
    bReceiverDrainValve : BOOL;
    bSystemAlarm : BOOL;
    iActiveState : INT;
END_VAR

VAR
    (* Internal State *)
    eState : (INIT, STANDBY, PREHEAT, RUNNING, DEFOCUS, DRAIN, FAULT) := INIT;

    (* Timers *)
    tonPreheatTimer : TON;
    tonDrainTimer : TON;

    (* PI Controllers *)
    rFlowError : REAL;
    rFlowIntegral : REAL;
    rKp_Flow : REAL := 2.5;
    rKi_Flow : REAL := 0.15;

    (* Constants *)
    MAX_FLUX : REAL := 1200.0; (* kW/m2 *)
    MIN_SALT_TEMP : REAL := 290.0; (* C *)
    MAX_SALT_TEMP : REAL := 565.0; (* C *)

    i : INT;
END_VAR

(* -- Main State Machine -- *)
IF bEmergencyStop THEN
    eState := FAULT;
END_IF;

CASE eState OF
    INIT:
        rColdSaltPumpSpeed_RPM := 0.0;
        rHotSaltValvePos_Pct := 0.0;
        bHeliostatDefocusCmd := TRUE;
        bReceiverDrainValve := TRUE; (* Open to drain by default *)
        bSystemAlarm := FALSE;
        eState := STANDBY;

    STANDBY:
        bHeliostatDefocusCmd := TRUE;
        bReceiverDrainValve := TRUE;
        rColdSaltPumpSpeed_RPM := 0.0;
        IF NOT bWeatherWarning AND rColdTankLevel_m > 2.0 THEN
            eState := PREHEAT;
        END_IF;

    PREHEAT:
        (* Activate trace heating fully during preheat *)
        FOR i := 1 TO 10 DO
            aTraceHeatingCmd[i] := TRUE;
        END_FOR;
        bReceiverDrainValve := FALSE; (* Close drain to build pressure *)
        tonPreheatTimer(IN := TRUE, PT := T#30M);
        IF tonPreheatTimer.Q THEN
            eState := RUNNING;
            tonPreheatTimer(IN := FALSE);
        END_IF;

    RUNNING:
        bHeliostatDefocusCmd := FALSE;
        bReceiverDrainValve := FALSE;

        (* Flow PI Controller based on outlet temp target (e.g. 565C) *)
        rFlowError := rReceiverOutletTemp_C - MAX_SALT_TEMP;
        rFlowIntegral := rFlowIntegral + (rFlowError * 0.1); (* Assuming 100ms cycle *)

        IF rFlowIntegral > 1000.0 THEN rFlowIntegral := 1000.0; END_IF;
        IF rFlowIntegral < 0.0 THEN rFlowIntegral := 0.0; END_IF;

        rColdSaltPumpSpeed_RPM := (rFlowError * rKp_Flow) + (rFlowIntegral * rKi_Flow);
        IF rColdSaltPumpSpeed_RPM > 3000.0 THEN rColdSaltPumpSpeed_RPM := 3000.0; END_IF;
        IF rColdSaltPumpSpeed_RPM < 500.0 THEN rColdSaltPumpSpeed_RPM := 500.0; END_IF;

        (* Flux Mapping and Defocus Logic *)
        IF rPeakFlux_kWm2 > MAX_FLUX THEN
            rTargetAimingOffset_m := (rPeakFlux_kWm2 - MAX_FLUX) * 0.05;
            IF rTargetAimingOffset_m > 5.0 THEN
                bHeliostatDefocusCmd := TRUE;
                eState := DEFOCUS;
            END_IF;
        ELSE
            rTargetAimingOffset_m := 0.0;
        END_IF;

        (* Tank Level Cascade *)
        IF rHotTankLevel_m > 12.0 THEN
            rHotSaltValvePos_Pct := 100.0;
        ELSIF rHotTankLevel_m < 2.0 THEN
            rHotSaltValvePos_Pct := 0.0;
        ELSE
            rHotSaltValvePos_Pct := (rHotTankLevel_m - 2.0) * 10.0;
        END_IF;

        (* Anti-freeze trace heating loop during running *)
        FOR i := 1 TO 10 DO
            IF aTraceHeatingTemps_C[i] < MIN_SALT_TEMP + 10.0 THEN
                aTraceHeatingCmd[i] := TRUE;
            ELSIF aTraceHeatingTemps_C[i] > MIN_SALT_TEMP + 30.0 THEN
                aTraceHeatingCmd[i] := FALSE;
            END_IF;
        END_FOR;

        (* Abnormal condition checks *)
        IF rReceiverOutletTemp_C < MIN_SALT_TEMP OR bWeatherWarning THEN
            eState := DRAIN;
        END_IF;

    DEFOCUS:
        bHeliostatDefocusCmd := TRUE;
        rColdSaltPumpSpeed_RPM := 1500.0; (* Maintain flow to cool down *)
        IF rPeakFlux_kWm2 < (MAX_FLUX * 0.8) THEN
            eState := RUNNING;
        END_IF;

    DRAIN:
        bHeliostatDefocusCmd := TRUE;
        bReceiverDrainValve := TRUE; (* Open drain valves gravity dump to cold tank *)
        rColdSaltPumpSpeed_RPM := 0.0;
        tonDrainTimer(IN := TRUE, PT := T#10M);
        IF tonDrainTimer.Q THEN
            eState := STANDBY;
            tonDrainTimer(IN := FALSE);
        END_IF;

    FAULT:
        bHeliostatDefocusCmd := TRUE;
        bReceiverDrainValve := TRUE;
        rColdSaltPumpSpeed_RPM := 0.0;
        rHotSaltValvePos_Pct := 0.0;
        bSystemAlarm := TRUE;
        (* Latch fault until reset manually (not shown in this basic state machine) *)

END_CASE;

iActiveState := eState;

END_FUNCTION_BLOCK
