FUNCTION_BLOCK FB_BlownFilm_ExtrusionControl
TITLE = 'Blown Film Line Master Control'
// Extrusion Blown Film Line Control: IBC (Internal Bubble Cooling), 
// Haul-off Nip Roll Kinematics, and Polymer Melt Pressure Cascading.

VAR_INPUT
    rTargetLayflatWidth : REAL;  // [mm] Target layflat width of the film
    rTargetThickness    : REAL;  // [um] Target film thickness
    rTargetLineSpeed    : REAL;  // [m/min] Target haul-off speed

    // Extruder & Melt
    rActualMeltPressure : REAL;  // [bar] Actual melt pressure at die head
    rTargetMeltPressure : REAL;  // [bar] Target melt pressure
    rExtruderSpeedMax   : REAL;  // [RPM] Maximum allowable extruder speed

    // IBC (Internal Bubble Cooling)
    rActualBubbleDia    : REAL;  // [mm] Actual bubble diameter from ultrasonic sensor
    rSupplyAirTemp      : REAL;  // [degC] Supply air temperature
    rExhaustAirTemp     : REAL;  // [degC] Exhaust air temperature

    // Haul-off Nip Roll
    rActualNipSpeed     : REAL;  // [m/min] Actual nip roll speed
    rNipRollTension     : REAL;  // [N] Actual tension at nip roll
    rTargetNipTension   : REAL;  // [N] Target tension at nip roll

    bEnableControl      : BOOL;  // Master control enable flag
    bEmergencyStop      : BOOL;  // E-Stop flag
END_VAR

VAR_OUTPUT
    // Extruder Control
    rExtruderSpeedCmd   : REAL;  // [RPM] Speed command for extruder drive
    bExtruderAlarm      : BOOL;  // Extruder out-of-limits alarm

    // IBC Control
    rIBCSupplyFanSpeed  : REAL;  // [%] Supply fan speed command
    rIBCExhaustFanSpeed : REAL;  // [%] Exhaust fan speed command
    bIBCAlarm           : BOOL;  // IBC out-of-limits alarm

    // Haul-off Nip Roll
    rNipRollSpeedCmd    : REAL;  // [m/min] Nip roll speed command
    rNipRollTorqueCmd   : REAL;  // [%] Nip roll torque limit command

    // Process Status
    bSystemReady        : BOOL;  // System ready for production
    sStatusMessage      : STRING(50); // Current system status
END_VAR

VAR
    // Internal state variables
    rTargetBubbleDia    : REAL;

    // PID Controllers for Melt Pressure (Cascading to Extruder Speed)
    rMeltKp             : REAL := 1.5;
    rMeltKi             : REAL := 0.2;
    rMeltKd             : REAL := 0.05;
    rMeltError          : REAL;
    rMeltIntegral       : REAL;
    rMeltPrevError      : REAL;

    // PID Controllers for IBC
    rIBCKp              : REAL := 2.0;
    rIBCKi              : REAL := 0.5;
    rIBCError           : REAL;
    rIBCIntegral        : REAL;

    // Kinematic & Tension variables
    rTensionKp          : REAL := 0.8;
    rTensionError       : REAL;
    rDrawRatio          : REAL;
    rBlowUpRatio        : REAL;

    // General
    rDeltaTime          : REAL := 0.01; // 10ms task cycle time assumed
    bInitialized        : BOOL := FALSE;
END_VAR

// Initialization
IF NOT bInitialized THEN
    rMeltIntegral := 0.0;
    rIBCIntegral := 0.0;
    rExtruderSpeedCmd := 0.0;
    rIBCSupplyFanSpeed := 50.0;
    rIBCExhaustFanSpeed := 50.0;
    bInitialized := TRUE;
    sStatusMessage := 'Initialized, awaiting enable.';
END_IF;

// Safety & E-Stop Interlocks
IF bEmergencyStop THEN
    rExtruderSpeedCmd := 0.0;
    rIBCSupplyFanSpeed := 0.0;
    rIBCExhaustFanSpeed := 100.0; // Fail-safe: evacuate bubble
    rNipRollSpeedCmd := 0.0;
    rNipRollTorqueCmd := 0.0;
    bSystemReady := FALSE;
    sStatusMessage := 'E-STOP ACTIVE';
    RETURN;
END_IF;

IF NOT bEnableControl THEN
    bSystemReady := TRUE;
    sStatusMessage := 'Standby. Control Disabled.';
    RETURN;
END_IF;

sStatusMessage := 'Running: Production Mode';

// ---------------------------------------------------------
// 1. Geometry & Kinematics Calculations
// ---------------------------------------------------------
// Layflat to Bubble Diameter Conversion: Dia = (2 * Layflat) / PI
rTargetBubbleDia := (2.0 * rTargetLayflatWidth) / 3.14159265;

// Blow Up Ratio (BUR) and Draw Down Ratio (DDR) estimation
// Assuming Die Diameter is a constant (e.g., 200 mm)
rBlowUpRatio := rTargetBubbleDia / 200.0; 

// ---------------------------------------------------------
// 2. Melt Pressure Cascading Control (Extruder Speed)
// ---------------------------------------------------------
rMeltError := rTargetMeltPressure - rActualMeltPressure;
rMeltIntegral := rMeltIntegral + (rMeltError * rDeltaTime);

// Anti-windup
IF rMeltIntegral > 100.0 THEN rMeltIntegral := 100.0; END_IF;
IF rMeltIntegral < -100.0 THEN rMeltIntegral := -100.0; END_IF;

rExtruderSpeedCmd := (rMeltKp * rMeltError) + (rMeltKi * rMeltIntegral) + (rMeltKd * (rMeltError - rMeltPrevError) / rDeltaTime);
rMeltPrevError := rMeltError;

// Limits
IF rExtruderSpeedCmd > rExtruderSpeedMax THEN rExtruderSpeedCmd := rExtruderSpeedMax; END_IF;
IF rExtruderSpeedCmd < 0.0 THEN rExtruderSpeedCmd := 0.0; END_IF;

IF ABS(rMeltError) > 20.0 THEN
    bExtruderAlarm := TRUE;
ELSE
    bExtruderAlarm := FALSE;
END_IF;

// ---------------------------------------------------------
// 3. Bubble Internal Cooling (IBC) Control
// ---------------------------------------------------------
rIBCError := rTargetBubbleDia - rActualBubbleDia;
rIBCIntegral := rIBCIntegral + (rIBCError * rDeltaTime);

// Simple PI for Exhaust Fan (Supply Fan held constant or ratioed)
// A larger exhaust decreases the bubble, a smaller exhaust increases it.
rIBCExhaustFanSpeed := 50.0 - ((rIBCKp * rIBCError) + (rIBCKi * rIBCIntegral));

// Clamp IBC Output
IF rIBCExhaustFanSpeed > 100.0 THEN rIBCExhaustFanSpeed := 100.0; END_IF;
IF rIBCExhaustFanSpeed < 10.0 THEN rIBCExhaustFanSpeed := 10.0; END_IF;

// Maintain supply fan at nominal to ensure cooling capacity
rIBCSupplyFanSpeed := 60.0;

IF ABS(rIBCError) > (rTargetBubbleDia * 0.1) THEN
    bIBCAlarm := TRUE;
ELSE
    bIBCAlarm := FALSE;
END_IF;

// ---------------------------------------------------------
// 4. Haul-off Nip Roll Kinematics and Tension Control
// ---------------------------------------------------------
// Baseline speed is the target line speed. Trim is applied based on tension.
rTensionError := rTargetNipTension - rNipRollTension;
rNipRollSpeedCmd := rTargetLineSpeed + (rTensionKp * rTensionError * rDeltaTime);

// Torque limiting for safety
rNipRollTorqueCmd := 85.0; // Fixed at 85% for nominal operation

END_FUNCTION_BLOCK
```

