FUNCTION_BLOCK FB_AmpouleFillingLine
VAR_INPUT
    bEnable : BOOL; // System enable
    bEstop : BOOL; // Emergency stop
    rLineSpeed : REAL; // Ampoules per minute (target)
    rTargetVolume : REAL; // Target fill volume in ml
    rNitrogenPressure : REAL; // Nitrogen line pressure
    rBurnerGasFlow : REAL; // Combustible gas flow
    rBurnerOxygenFlow : REAL; // Oxygen flow
END_VAR
VAR_OUTPUT
    bSystemReady : BOOL;
    bPurgeActive : BOOL;
    bFillActive : BOOL;
    bSealActive : BOOL;
    rActualVolume : REAL;
    iTotalFilled : DINT;
    iTotalRejected : DINT;
    iTotalSealed : DINT;
    iAlarmCode : INT;
END_VAR
VAR
    eState : INT := 0; // 0=INIT, 1=PURGE, 2=FILL, 3=SEAL, 4=REJECT, 5=ERROR
    tonPurgeTime : TON;
    tonFillTime : TON;
    tonSealTime : TON;
    rFillRate : REAL := 0.0;
    rCurrentFill : REAL := 0.0;
    bFillComplete : BOOL;
    bSealComplete : BOOL;
    rGasRatio : REAL;
    tPurgeDuration : TIME := T#2S;
    tFillDuration : TIME := T#1S;
    tSealDuration : TIME := T#1500MS;
END_VAR

// Main State Machine
IF bEstop THEN
    eState := 5;
    iAlarmCode := 999;
END_IF;

CASE eState OF
    0: // INIT
        bSystemReady := FALSE;
        bPurgeActive := FALSE;
        bFillActive := FALSE;
        bSealActive := FALSE;
        IF bEnable AND NOT bEstop AND rNitrogenPressure > 2.0 AND rBurnerGasFlow > 10.0 THEN
            bSystemReady := TRUE;
            eState := 1;
        END_IF;

    1: // PURGE
        bSystemReady := TRUE;
        bPurgeActive := TRUE;
        tonPurgeTime(IN:=TRUE, PT:=tPurgeDuration);
        IF tonPurgeTime.Q THEN
            bPurgeActive := FALSE;
            tonPurgeTime(IN:=FALSE);
            eState := 2;
        END_IF;
        IF rNitrogenPressure < 1.5 THEN
            iAlarmCode := 101;
            eState := 5;
        END_IF;

    2: // FILL
        bFillActive := TRUE;
        tonFillTime(IN:=TRUE, PT:=tFillDuration);
        rFillRate := rTargetVolume / (TIME_TO_REAL(tFillDuration) / 1000.0);
        rCurrentFill := rFillRate * (TIME_TO_REAL(tonFillTime.ET) / 1000.0);
        rActualVolume := rCurrentFill;

        IF tonFillTime.Q THEN
            bFillActive := FALSE;
            tonFillTime(IN:=FALSE);
            IF ABS(rActualVolume - rTargetVolume) <= (rTargetVolume * 0.02) THEN
                iTotalFilled := iTotalFilled + 1;
                eState := 3;
            ELSE
                eState := 4;
            END_IF;
        END_IF;

    3: // SEAL
        bSealActive := TRUE;
        tonSealTime(IN:=TRUE, PT:=tSealDuration);
        rGasRatio := rBurnerGasFlow / MAX(rBurnerOxygenFlow, 1.0);
        IF rGasRatio < 0.8 OR rGasRatio > 1.2 THEN
            iAlarmCode := 201; // Invalid burner mix
            eState := 5;
        END_IF;

        IF tonSealTime.Q THEN
            bSealActive := FALSE;
            tonSealTime(IN:=FALSE);
            iTotalSealed := iTotalSealed + 1;
            eState := 1; // Next ampoule
        END_IF;

    4: // REJECT
        iTotalRejected := iTotalRejected + 1;
        eState := 1; // Reset for next

    5: // ERROR
        bSystemReady := FALSE;
        bPurgeActive := FALSE;
        bFillActive := FALSE;
        bSealActive := FALSE;
        // Require estop reset and manual clear
        IF NOT bEstop AND NOT bEnable THEN
            iAlarmCode := 0;
            eState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
