```iec-st
FUNCTION_BLOCK FB_Spacecraft_CDRA
(*
================================================================================
  Advanced Commercial Spacecraft Carbon Dioxide Removal Assembly (CDRA)
  Controller FB
  Author: Lumina AI Cloud Swarm
  Description:
    Manages Zeolite sorbent bed thermal amine desorption cycling, trace 
    contaminant trace outgassing venting, and deep-space regenerative 
    molecular sieve moisture removal.
    Includes multi-layered safety interlocks and sensor noise filtering.
================================================================================
*)
VAR_INPUT
    (* Mandatory inputs *)
    bSystemEnable       : BOOL;     (* Main system enable command from flight computer *)
    bEmergencyStop      : BOOL;     (* Hardwired emergency stop safety loop *)
    rCO2Concentration   : REAL;     (* Measured cabin CO2 concentration (ppm) *)
    rBedTemperature_A   : REAL;     (* Zeolite bed A temperature (Celsius) *)
    rBedTemperature_B   : REAL;     (* Zeolite bed B temperature (Celsius) *)
    rSystemPressure     : REAL;     (* CDRA internal manifold pressure (psia) *)
    rInletHumidity      : REAL;     (* Process air inlet relative humidity (%) *)
    bVentValveStatus    : BOOL;     (* True if space vacuum vent valve is verified open *)
END_VAR

VAR_OUTPUT
    (* Mandatory outputs *)
    bSystemReady        : BOOL;     (* System is operational and tracking targets *)
    rHeaterControl_A    : REAL;     (* PWM control signal to Bed A desorption heaters (0-100%) *)
    rHeaterControl_B    : REAL;     (* PWM control signal to Bed B desorption heaters (0-100%) *)
    bBlowerActive       : BOOL;     (* Process air blower enable signal *)
    bVentValveCmd       : BOOL;     (* Command to open space vacuum vent valve *)
    bCriticalAlarm      : BOOL;     (* Output high if fault condition exists *)
END_VAR

VAR
    (* Internal state and filters *)
    iState              : INT := 0; (* Primary state machine variable *)
    rFilteredCO2        : REAL := 0.0; (* Exponential moving average of CO2 *)
    tCycleTimer         : TON;      (* Half-cycle duration timer *)
    tVentTimer          : TON;      (* Outgassing vent delay timer *)
    rKp                 : REAL := 0.5; (* Heater PID Proportional Gain *)
    rKi                 : REAL := 0.1; (* Heater PID Integral Gain *)
    rErrorSumA          : REAL := 0.0; (* Integral accumulator for Bed A *)
    rErrorSumB          : REAL := 0.0; (* Integral accumulator for Bed B *)
    rTargetDesorbTemp   : REAL := 205.0; (* Desorption target temp (C) *)
    rAlpha              : REAL := 0.05; (* EMA Filter coefficient *)
    bFaultActive        : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety Interlocks and Hard Faults *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bBlowerActive := FALSE;
    rHeaterControl_A := 0.0;
    rHeaterControl_B := 0.0;
    bVentValveCmd := FALSE;
    bCriticalAlarm := TRUE;
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* 2. Sensor Noise Filtering (Exponential Moving Average) *)
rFilteredCO2 := (rAlpha * rCO2Concentration) + ((1.0 - rAlpha) * rFilteredCO2);

(* 3. Alarm Thresholds *)
IF rSystemPressure > 15.5 OR rBedTemperature_A > 250.0 OR rBedTemperature_B > 250.0 THEN
    bFaultActive := TRUE;
    bCriticalAlarm := TRUE;
    iState := 999;
ELSE
    bFaultActive := FALSE;
    bCriticalAlarm := FALSE;
END_IF;

(* 4. State Machine: Thermal Amine Desorption Cycling *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rHeaterControl_A := 0.0;
        rHeaterControl_B := 0.0;
        bBlowerActive := FALSE;
        bVentValveCmd := FALSE;
        rErrorSumA := 0.0;
        rErrorSumB := 0.0;

        IF bSystemEnable AND NOT bFaultActive THEN
            iState := 10;
        END_IF;

    10: (* BED A ADSORB / BED B PRE-HEAT *)
        bSystemReady := TRUE;
        bBlowerActive := TRUE; (* Blowing cabin air through Bed A *)

        (* PID Control for Bed B Pre-heat *)
        rErrorSumB := rErrorSumB + (rTargetDesorbTemp - rBedTemperature_B);
        (* Anti-windup *)
        IF rErrorSumB > 1000.0 THEN rErrorSumB := 1000.0; END_IF;
        IF rErrorSumB < 0.0 THEN rErrorSumB := 0.0; END_IF;

        rHeaterControl_B := (rKp * (rTargetDesorbTemp - rBedTemperature_B)) + (rKi * rErrorSumB);
        rHeaterControl_A := 0.0;

        (* Bound PWM output *)
        IF rHeaterControl_B > 100.0 THEN rHeaterControl_B := 100.0; END_IF;
        IF rHeaterControl_B < 0.0 THEN rHeaterControl_B := 0.0; END_IF;

        (* Bed B vent to space vacuum once heated *)
        IF rBedTemperature_B >= (rTargetDesorbTemp - 5.0) THEN
            bVentValveCmd := TRUE;
            IF bVentValveStatus THEN
                tCycleTimer(IN := TRUE, PT := T#45M); (* 45 minute desorption *)
                IF tCycleTimer.Q THEN
                    tCycleTimer(IN := FALSE);
                    bVentValveCmd := FALSE;
                    iState := 20; (* Transition to Bed B Adsorb *)
                END_IF;
            END_IF;
        END_IF;

    20: (* BED B ADSORB / BED A PRE-HEAT *)
        bSystemReady := TRUE;
        bBlowerActive := TRUE;

        (* PID Control for Bed A Pre-heat *)
        rErrorSumA := rErrorSumA + (rTargetDesorbTemp - rBedTemperature_A);
        IF rErrorSumA > 1000.0 THEN rErrorSumA := 1000.0; END_IF;
        IF rErrorSumA < 0.0 THEN rErrorSumA := 0.0; END_IF;

        rHeaterControl_A := (rKp * (rTargetDesorbTemp - rBedTemperature_A)) + (rKi * rErrorSumA);
        rHeaterControl_B := 0.0;

        IF rHeaterControl_A > 100.0 THEN rHeaterControl_A := 100.0; END_IF;
        IF rHeaterControl_A < 0.0 THEN rHeaterControl_A := 0.0; END_IF;

        IF rBedTemperature_A >= (rTargetDesorbTemp - 5.0) THEN
            bVentValveCmd := TRUE;
            IF bVentValveStatus THEN
                tCycleTimer(IN := TRUE, PT := T#45M);
                IF tCycleTimer.Q THEN
                    tCycleTimer(IN := FALSE);
                    bVentValveCmd := FALSE;
                    iState := 10; (* Loop back *)
                END_IF;
            END_IF;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rHeaterControl_A := 0.0;
        rHeaterControl_B := 0.0;
        bBlowerActive := FALSE;
        bVentValveCmd := FALSE;
        tCycleTimer(IN := FALSE);

        IF NOT bFaultActive AND bSystemEnable THEN
            (* Await reset signal, simplified here to auto-recover if fault clears *)
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
