FUNCTION_BLOCK FB_ECLSS_Controller
VAR_INPUT
    rCabinPressure        : REAL; (* Absolute pressure in kPa *)
    rCabinCO2Level        : REAL; (* CO2 ppm *)
    rCabinO2Level         : REAL; (* O2 ppm or percentage *)
    rCabinTemperature     : REAL; (* Celsius *)
    rCoolantTemp          : REAL; (* Celsius *)
    bScrubberBypass       : BOOL; (* Manual bypass for CO2 scrubber *)
    bElectrolysisEnable   : BOOL; (* Enable O2 generation *)
    rSolarArrayPower      : REAL; (* Available power in kW *)
END_VAR

VAR_OUTPUT
    rScrubberFanSpeed     : REAL; (* 0.0 to 100.0 % *)
    bScrubberHeaterOn     : BOOL;
    rO2GeneratorCurrent   : REAL; (* Electrolysis current in Amps *)
    bVentValveOpen        : BOOL;
    rCoolantPumpSpeed     : REAL; (* 0.0 to 100.0 % *)
    bSystemAlarm          : BOOL;
    iErrorCode            : INT;
END_VAR

VAR
    rTargetPressure       : REAL := 101.325; (* Sea level standard *)
    rMaxCO2               : REAL := 3000.0;
    rTargetO2             : REAL := 21.0;
    rTargetTemp           : REAL := 22.0;

    timerScrubberCycle    : TON;
    bScrubberRegen        : BOOL;

    (* Internal PID variables for Scrubber *)
    rCO2Error             : REAL;
    rCO2Integral          : REAL;

    (* Internal PID variables for Thermal *)
    rTempError            : REAL;
    rTempIntegral         : REAL;
END_VAR

(* Implementation *)
(* 1. CO2 Scrubbing Logic *)
rCO2Error := rCabinCO2Level - 500.0; (* 500 ppm target *)
IF rCO2Error > 0.0 THEN
    rCO2Integral := rCO2Integral + (rCO2Error * 0.01);
ELSE
    rCO2Integral := rCO2Integral * 0.99; (* Decay *)
END_IF;

IF bScrubberBypass THEN
    rScrubberFanSpeed := 0.0;
ELSIF rCabinCO2Level > rMaxCO2 THEN
    rScrubberFanSpeed := 100.0;
    bSystemAlarm := TRUE;
    iErrorCode := 101; (* High CO2 Alarm *)
ELSE
    rScrubberFanSpeed := (rCO2Error * 0.5) + (rCO2Integral * 0.05);
    IF rScrubberFanSpeed > 100.0 THEN
        rScrubberFanSpeed := 100.0;
    ELSIF rScrubberFanSpeed < 20.0 AND rCO2Error > 100.0 THEN
        rScrubberFanSpeed := 20.0;
    ELSIF rScrubberFanSpeed < 0.0 THEN
        rScrubberFanSpeed := 0.0;
    END_IF;
END_IF;

(* 2. Oxygen Generation (Electrolysis) *)
IF bElectrolysisEnable AND rSolarArrayPower > 5.0 THEN
    IF rCabinO2Level < rTargetO2 THEN
        rO2GeneratorCurrent := (rTargetO2 - rCabinO2Level) * 50.0;
        IF rO2GeneratorCurrent > 150.0 THEN
            rO2GeneratorCurrent := 150.0;
        END_IF;
    ELSE
        rO2GeneratorCurrent := 0.0;
    END_IF;
ELSE
    rO2GeneratorCurrent := 0.0;
END_IF;

(* 3. Thermal & Coolant Control *)
rTempError := rCabinTemperature - rTargetTemp;
IF rTempError > 0.0 THEN
    rCoolantPumpSpeed := rTempError * 10.0;
    IF rCoolantPumpSpeed > 100.0 THEN rCoolantPumpSpeed := 100.0; END_IF;
ELSE
    rCoolantPumpSpeed := 10.0; (* Minimum circulation *)
END_IF;

(* 4. Pressure Regulation *)
IF rCabinPressure > (rTargetPressure + 5.0) THEN
    bVentValveOpen := TRUE;
ELSE
    bVentValveOpen := FALSE;
END_IF;

(* Alarm Reset Logic (simplified) *)
IF rCabinCO2Level <= rMaxCO2 AND rCabinPressure <= (rTargetPressure + 5.0) THEN
    bSystemAlarm := FALSE;
    iErrorCode := 0;
END_IF;

END_FUNCTION_BLOCK
