FUNCTION_BLOCK "Mining_Conveyor_VFD_LoadShare"
VERSION : 0.2
   VAR_INPUT 
      StartCmd : Bool;
      StopCmd : Bool;
      BeltTearSensor : Bool;
      MasterSpeedActual : Real;
      SlaveSpeedActual : Real;
      MasterTorqueActual : Real;
      SlaveTorqueActual : Real;
      TailSpeed : Real;
      TensionSet : Real;
      TensionAct : Real;
      ResetFault : Bool;
   END_VAR

   VAR_OUTPUT 
      MasterRunCmd : Bool;
      SlaveRunCmd : Bool;
      MasterSpeedRef : Real;
      SlaveTorqueRef : Real;
      WinchFwd : Bool;
      WinchRev : Bool;
      SysFault : Bool;
   END_VAR

   VAR 
      Running : Bool;
      FaultActive : Bool;
      LoadShareError : Real;
      SlaveTorqueIntegral : Real;
      TargetSpeed : Real;
   END_VAR

BEGIN
   IF #BeltTearSensor THEN
      #FaultActive := TRUE;
   END_IF;

   IF #MasterSpeedActual > 0.5 THEN
      IF ((#MasterSpeedActual - #TailSpeed) / #MasterSpeedActual) * 100.0 > 5.0 THEN
         #FaultActive := TRUE;
      END_IF;
   END_IF;

   IF #StopCmd OR #FaultActive THEN
      #Running := FALSE;
      #TargetSpeed := 0.0;
   ELSIF #StartCmd AND NOT #FaultActive THEN
      #Running := TRUE;
      #TargetSpeed := 2.5;
   END_IF;

   IF #ResetFault AND NOT #BeltTearSensor THEN
      #FaultActive := FALSE;
   END_IF;

   #MasterRunCmd := #Running;
   #SlaveRunCmd := #Running;
   #SysFault := #FaultActive;

   IF #Running THEN
      #MasterSpeedRef := #TargetSpeed;

      // Slave Torque Follows Master Torque with PI trim
      #LoadShareError := #MasterTorqueActual - #SlaveTorqueActual;
      #SlaveTorqueIntegral := #SlaveTorqueIntegral + (#LoadShareError * 0.05);
      #SlaveTorqueRef := #MasterTorqueActual + (#LoadShareError * 0.5) + #SlaveTorqueIntegral;
   ELSE
      #MasterSpeedRef := 0.0;
      #SlaveTorqueRef := 0.0;
      #SlaveTorqueIntegral := 0.0;
   END_IF;
END_FUNCTION_BLOCK
### Explanation:
Added **Multi-Drive Load Sharing**: The Master drive receives a speed reference. The Slave drive receives a torque reference derived directly from the Master's actual torque, trimmed by a PI controller to ensure equal load distribution.
