FUNCTION_BLOCK FB_SFCL_Superconducting_Fault_Current_Limiter
TITLE = 'Enterprise Grade SFCL Advanced Control System'
VERSION : '3.4.1'
// -----------------------------------------------------------------------------
// DESCRIPTION:
// This function block implements a comprehensive control and monitoring system
// for a resistive-type Superconducting Fault Current Limiter (SFCL).
// It manages the liquid nitrogen (LN2) cryostat environment, executes 
// instantaneous quench detection via phase current monitoring, calculates
// dynamic resistance insertion, and safely orchestrates grid reclosure 
// synchronization after a fault clears and thermal recovery is complete.
// -----------------------------------------------------------------------------

VAR_INPUT
    // Grid Electrical Measurements
    rVoltage_PhaseA     : REAL; // Phase A Grid Voltage (kV RMS)
    rVoltage_PhaseB     : REAL; // Phase B Grid Voltage (kV RMS)
    rVoltage_PhaseC     : REAL; // Phase C Grid Voltage (kV RMS)
    rCurrent_PhaseA     : REAL; // Phase A Grid Current (kA RMS)
    rCurrent_PhaseB     : REAL; // Phase B Grid Current (kA RMS)
    rCurrent_PhaseC     : REAL; // Phase C Grid Current (kA RMS)

    // Cryostat Environmental Sensors
    rLN2_Temperature    : REAL; // Cryostat LN2 Temperature (Kelvin)
    rLN2_Level          : REAL; // Liquid Nitrogen Fill Level (%)
    rCryo_Pressure      : REAL; // Cryostat Internal Pressure (Bar)
    rColdhead_Temp      : REAL; // Cryocooler coldhead temperature (Kelvin)

    // Control & Synchronization Signals
    bGridFreqStable     : BOOL; // Indicates grid frequency is within tolerance
    bPhaseSyncOk        : BOOL; // Indicates phase synchronization is suitable for reclosure
    bManualOverride     : BOOL; // Manual control override flag
    bSystemReset        : BOOL; // Reset system fault conditions

    // Configurable Parameters
    rMaxCurrentThresh   : REAL := 15.0; // Quench detection threshold (kA)
    rNominalCryoTemp    : REAL := 77.0; // Nominal operating temperature (K)
    rCriticalCryoTemp   : REAL := 89.0; // Critical temperature, transition to normal state (K)
    rMaxPressureLmt     : REAL := 2.5;  // Maximum allowable internal pressure (Bar)
END_VAR

VAR_OUTPUT
    // Breaker & Actuator Commands
    bTrip_MainBreaker   : BOOL; // Command to instantly trip the main line breaker
    bClose_MainBreaker  : BOOL; // Command to close the main line breaker (reclosure)
    bRun_CryoCooler     : BOOL; // Command to run cryocooler compressors
    bOpen_VentValve     : BOOL; // Command to open pressure relief vent valve
    bAlarm_Siren        : BOOL; // Trigger external plant alarm

    // Status & Telemetry
    bQuenchStateActive  : BOOL; // TRUE when SFCL has quenched (resistive state)
    iStateMachineState  : INT;  // 0=Init, 1=Superconducting, 2=Quench_Isolate, 3=Thermal_Recovery, 4=Reclosing, 5=System_Fault
    rDynamicResistance  : REAL; // Estimated instantaneous resistance of the SFCL element (Ohms)
    sTelemetryMsg       : STRING[80]; // Human-readable status message for SCADA HMI
END_VAR

VAR
    // Internal Timers
    tonRecoveryTimer    : TON; // Thermal recovery delay timer
    tonReclosePulse     : TON; // Pulse width for breaker close command
    tonFaultLatch       : TON; // Delay for latching persistent faults

    // Internal Flags
    bCurrentExceeded    : BOOL;
    bCryoSystemFault    : BOOL;
    bThermalRecoveryOk  : BOOL;

    tRecoveryDuration   : TIME := T#45S; // Required time at superconducting temp before reclosure
    tPulseWidth         : TIME := T#500MS; 
END_VAR

// =============================================================================
// CRYOSTAT THERMODYNAMIC CONTROL
// =============================================================================
// Maintain optimal temperature and pressure for the high-temperature superconductor (HTS)
IF rLN2_Temperature > (rNominalCryoTemp + 1.5) OR rLN2_Level < 65.0 THEN
    bRun_CryoCooler := TRUE;
ELSE
    bRun_CryoCooler := FALSE;
END_IF;

// Overpressure protection venting
IF rCryo_Pressure > rMaxPressureLmt THEN
    bOpen_VentValve := TRUE;
ELSE
    bOpen_VentValve := FALSE;
END_IF;

// Critical environmental fault evaluation
IF rLN2_Temperature >= rCriticalCryoTemp OR rLN2_Level < 25.0 OR rCryo_Pressure > (rMaxPressureLmt * 1.2) THEN
    bCryoSystemFault := TRUE;
ELSE
    bCryoSystemFault := FALSE;
END_IF;

// =============================================================================
// QUENCH DETECTION & FAULT ISOLATION
// =============================================================================
// Evaluate phase currents against the quench threshold
bCurrentExceeded := (rCurrent_PhaseA > rMaxCurrentThresh) OR 
                    (rCurrent_PhaseB > rMaxCurrentThresh) OR 
                    (rCurrent_PhaseC > rMaxCurrentThresh);

// Instantaneous reaction to a fault current (quench)
IF bCurrentExceeded AND NOT bQuenchStateActive AND NOT bManualOverride THEN
    bQuenchStateActive := TRUE;
    bTrip_MainBreaker := TRUE;
    iStateMachineState := 2; // Quench & Isolate
    sTelemetryMsg := 'CRITICAL: FAULT CURRENT QUENCH DETECTED. BREAKER TRIPPED.';
END_IF;

// =============================================================================
// DYNAMIC RESISTANCE CALCULATION
// =============================================================================
// Simplified Ohmic calculation during the fault state
IF bQuenchStateActive AND rCurrent_PhaseA > 0.1 THEN
    // Calculate resistance based on Phase A for telemetry (Ohms = V / I)
    rDynamicResistance := (rVoltage_PhaseA / rCurrent_PhaseA); 
ELSE
    // In superconducting state, resistance is practically zero
    rDynamicResistance := 0.0001; 
END_IF;

// =============================================================================
// THERMAL RECOVERY & GRID SYNCHRONIZED RECLOSURE
// =============================================================================
// Check if the HTS element has cooled back down to the superconducting regime
bThermalRecoveryOk := (rLN2_Temperature <= rNominalCryoTemp + 1.0) AND NOT bCryoSystemFault;

// Timer evaluates the duration of stable recovery temperatures
tonRecoveryTimer(IN := bQuenchStateActive AND NOT bCurrentExceeded AND bThermalRecoveryOk, PT := tRecoveryDuration);

// Reclosure Logic: Requires recovery, stable grid frequency, and phase sync
IF bQuenchStateActive AND tonRecoveryTimer.Q THEN
    iStateMachineState := 3; // Thermal Recovery Complete
    sTelemetryMsg := 'RECOVERY COMPLETE. AWAITING GRID SYNCHRONIZATION...';

    IF bGridFreqStable AND bPhaseSyncOk THEN
        iStateMachineState := 4; // Reclosing
        bTrip_MainBreaker := FALSE; // Release the trip coil
        bClose_MainBreaker := TRUE; // Pulse the close coil
        bQuenchStateActive := FALSE; // Reset quench state
        sTelemetryMsg := 'GRID SYNC OK. EXECUTING BREAKER RECLOSURE.';
    END_IF;
END_IF;

// Breaker close pulse reset
tonReclosePulse(IN := bClose_MainBreaker, PT := tPulseWidth);
IF tonReclosePulse.Q THEN
    bClose_MainBreaker := FALSE;
END_IF;

// =============================================================================
// SYSTEM NORMALIZATION & FAULT MANAGEMENT
// =============================================================================
IF NOT bQuenchStateActive AND NOT bCryoSystemFault AND NOT bClose_MainBreaker THEN
    iStateMachineState := 1; // Superconducting Normal State
    sTelemetryMsg := 'SYSTEM NORMAL: SUPERCONDUCTING STATE ACTIVE.';
END_IF;

IF bCryoSystemFault THEN
    bTrip_MainBreaker := TRUE;
    bAlarm_Siren := TRUE;
    iStateMachineState := 5; // System Fault State
    sTelemetryMsg := 'ALARM: CRYOSTAT ENVIRONMENTAL FAILURE. SYSTEM TRIPPED.';
END_IF;

// Reset condition logic
IF bSystemReset THEN
    bQuenchStateActive := FALSE;
    bTrip_MainBreaker := FALSE;
    bClose_MainBreaker := FALSE;
    bAlarm_Siren := FALSE;
    iStateMachineState := 0; // Initialization State
    sTelemetryMsg := 'SYSTEM RESET ACKNOWLEDGED.';
END_IF;

END_FUNCTION_BLOCK
```

