FUNCTION_BLOCK FB_GypsumBoardLine_Control
VAR_INPUT
    rStuccoFlow_kg_h : REAL; (* Incoming stucco flow rate in kg/hr *)
    rTargetDensity_kg_m3 : REAL; (* Target board density *)
    rLineSpeed_m_min : REAL; (* Current production line speed *)
    rPaperTension_Top_N : REAL; (* Top paper web tension feedback *)
    rPaperTension_Bot_N : REAL; (* Bottom paper web tension feedback *)
    rKilnZone1_Temp_C : REAL; (* Kiln zone 1 temperature feedback *)
    rKilnZone2_Temp_C : REAL; (* Kiln zone 2 temperature feedback *)
    rKilnZone3_Temp_C : REAL; (* Kiln zone 3 temperature feedback *)
    rKilnExhaust_Moisture_Pct : REAL; (* Kiln exhaust moisture percentage *)
    bStartLine : BOOL; (* Start command *)
    bStopLine : BOOL; (* Stop command *)
    bEmergencyStop : BOOL; (* Emergency stop *)
END_VAR

VAR_OUTPUT
    rWaterFlowSetPoint_L_h : REAL; (* Setpoint for water addition *)
    rFoamFlowSetPoint_L_h : REAL; (* Setpoint for foam addition *)
    rTensionCtrlOutput_Top_Pct : REAL; (* Top paper tension control valve/drive output 0-100% *)
    rTensionCtrlOutput_Bot_Pct : REAL; (* Bottom paper tension control valve/drive output 0-100% *)
    rKilnBurner1_Output_Pct : REAL; (* Burner 1 control output *)
    rKilnBurner2_Output_Pct : REAL; (* Burner 2 control output *)
    rKilnBurner3_Output_Pct : REAL; (* Burner 3 control output *)
    bSystemReady : BOOL;
    bSystemRunning : BOOL;
    bAlarmActive : BOOL;
    iAlarmCode : INT;
END_VAR

VAR
    (* Internal PID variables for Water/Foam cascade control *)
    fbWaterPID : PID_T;
    fbFoamPID : PID_T;
    rWaterRatio : REAL := 0.65; (* Base water to stucco ratio *)
    rFoamRatio : REAL := 0.05; (* Base foam to stucco ratio adjusted by density *)

    (* Tension Control *)
    fbTopTensionPID : PID_T;
    fbBotTensionPID : PID_T;
    rTargetTension_N : REAL := 150.0;

    (* Kiln Thermal Profiling *)
    fbZone1PID : PID_T;
    fbZone2PID : PID_T;
    fbZone3PID : PID_T;
    rTargetZ1_Temp_C : REAL := 220.0;
    rTargetZ2_Temp_C : REAL := 250.0;
    rTargetZ3_Temp_C : REAL := 180.0;

    (* Timers and State *)
    fbStartupDelay : TON;
    eState : (STATE_INIT, STATE_READY, STATE_STARTING, STATE_RUNNING, STATE_STOPPING, STATE_FAULT);

    (* Internal limits and calculation buffers *)
    rCalculatedFoamReq : REAL;
    rCalculatedWaterReq : REAL;
END_VAR

(* 
    Gypsum Board Manufacturing Line Control 
    Handles main stucco mixer inputs, paper tension for top/bottom webs, 
    and the 3-zone drying kiln.
*)

IF bEmergencyStop THEN
    eState := STATE_FAULT;
    bAlarmActive := TRUE;
    iAlarmCode := 9999;
    bSystemRunning := FALSE;
    bSystemReady := FALSE;
    rWaterFlowSetPoint_L_h := 0.0;
    rFoamFlowSetPoint_L_h := 0.0;
    rTensionCtrlOutput_Top_Pct := 0.0;
    rTensionCtrlOutput_Bot_Pct := 0.0;
    rKilnBurner1_Output_Pct := 0.0;
    rKilnBurner2_Output_Pct := 0.0;
    rKilnBurner3_Output_Pct := 0.0;
    RETURN;
END_IF;

CASE eState OF
    STATE_INIT:
        bAlarmActive := FALSE;
        iAlarmCode := 0;
        IF rStuccoFlow_kg_h > 0.0 THEN
            bSystemReady := TRUE;
            eState := STATE_READY;
        END_IF;

    STATE_READY:
        IF bStartLine THEN
            eState := STATE_STARTING;
            fbStartupDelay(IN := TRUE, PT := T#5S);
        END_IF;

    STATE_STARTING:
        fbStartupDelay(IN := TRUE, PT := T#5S);
        IF fbStartupDelay.Q THEN
            eState := STATE_RUNNING;
            bSystemRunning := TRUE;
        END_IF;

    STATE_RUNNING:
        IF bStopLine THEN
            eState := STATE_STOPPING;
            bSystemRunning := FALSE;
        END_IF;

        (* 1. Stucco Mixer Water/Foam Ratio Cascade Control *)
        (* Water requirement is primarily a function of stucco flow *)
        rCalculatedWaterReq := rStuccoFlow_kg_h * rWaterRatio;

        (* Foam requirement is a function of target density and line speed *)
        IF rTargetDensity_kg_m3 < 700.0 THEN
            rFoamRatio := 0.08;
        ELSIF rTargetDensity_kg_m3 > 850.0 THEN
            rFoamRatio := 0.03;
        ELSE
            rFoamRatio := 0.05;
        END_IF;
        rCalculatedFoamReq := rStuccoFlow_kg_h * rFoamRatio * (rLineSpeed_m_min / 50.0);

        rWaterFlowSetPoint_L_h := rCalculatedWaterReq;
        rFoamFlowSetPoint_L_h := rCalculatedFoamReq;

        (* 2. Continuous Paper Web Tension Control *)
        (* Simplified P-control for demonstration *)
        rTensionCtrlOutput_Top_Pct := (rTargetTension_N - rPaperTension_Top_N) * 0.5 + 50.0;
        rTensionCtrlOutput_Bot_Pct := (rTargetTension_N - rPaperTension_Bot_N) * 0.5 + 50.0;

        (* Clamp outputs *)
        IF rTensionCtrlOutput_Top_Pct > 100.0 THEN rTensionCtrlOutput_Top_Pct := 100.0; END_IF;
        IF rTensionCtrlOutput_Top_Pct < 0.0 THEN rTensionCtrlOutput_Top_Pct := 0.0; END_IF;
        IF rTensionCtrlOutput_Bot_Pct > 100.0 THEN rTensionCtrlOutput_Bot_Pct := 100.0; END_IF;
        IF rTensionCtrlOutput_Bot_Pct < 0.0 THEN rTensionCtrlOutput_Bot_Pct := 0.0; END_IF;

        (* 3. Multi-deck Drying Kiln Thermal Profiling *)
        (* Moisture feedback adjusts Zone 3 Target *)
        IF rKilnExhaust_Moisture_Pct > 12.0 THEN
            rTargetZ3_Temp_C := 190.0;
        ELSIF rKilnExhaust_Moisture_Pct < 5.0 THEN
            rTargetZ3_Temp_C := 160.0;
        ELSE
            rTargetZ3_Temp_C := 180.0;
        END_IF;

        rKilnBurner1_Output_Pct := (rTargetZ1_Temp_C - rKilnZone1_Temp_C) * 2.0;
        rKilnBurner2_Output_Pct := (rTargetZ2_Temp_C - rKilnZone2_Temp_C) * 2.5;
        rKilnBurner3_Output_Pct := (rTargetZ3_Temp_C - rKilnZone3_Temp_C) * 1.5;

    STATE_STOPPING:
        bSystemRunning := FALSE;
        rWaterFlowSetPoint_L_h := 0.0;
        rFoamFlowSetPoint_L_h := 0.0;
        fbStartupDelay(IN := FALSE);
        eState := STATE_READY;

    STATE_FAULT:
        (* Require manual reset *)
        IF NOT bEmergencyStop THEN
            eState := STATE_INIT;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
