    bPrimaryPLC_Active : BOOL; 
    bIsSecondary : BOOL; 

    // HIL Digital Twin
    rTwinExpectedElevation : REAL; // Elevation predicted by digital twin
    bTwinCommsOK : BOOL;
END_VAR

VAR_OUTPUT
    rShearerLiftCmd : REAL;
    rConveyorSpeedCmd : REAL;
    bSystemRunning : BOOL;
    iErrorCode : INT;
    stSCADA : UDT_SCADA_Data; 
END_VAR

VAR
    bActive : BOOL := FALSE;
    bSecureMode : BOOL := FALSE;
    bFailoverActive : BOOL := FALSE;
    rMaxSafePressure : REAL := 250.0;
    dwValidToken : DWORD := 16#A1B2C3D4;

    // Self-Test and Adversarial
    iState : INT := 0; // 0=Init, 1=SelfTest, 2=Ready, 3=Running, 4=Fault
    tSelfTestTimer : TON;
    bSelfTestPassed : BOOL := FALSE;
    rConsolidatedElevation : REAL;
    bSensorDrift : BOOL := FALSE;
    bTwinMismatch : BOOL := FALSE;
END_VAR

BEGIN
    // Sensor Drift Detection (Adversarial defense against spoofing/degradation)
    IF ABS(rShearerActualElevation1 - rShearerActualElevation2) > 5.0 THEN
        bSensorDrift := TRUE;
    ELSE
        bSensorDrift := FALSE;
        rConsolidatedElevation := (rShearerActualElevation1 + rShearerActualElevation2) / 2.0;
    END_IF;

    // Digital Twin Sync check
    IF bTwinCommsOK AND (ABS(rConsolidatedElevation - rTwinExpectedElevation) > 15.0) THEN
        bTwinMismatch := TRUE;
    ELSE
        bTwinMismatch := FALSE;
    END_IF;

    // Cybersecurity
    IF bSecureModeReq AND (dwAuthToken = dwValidToken) THEN
        bSecureMode := TRUE;
    ELSE
        bSecureMode := FALSE;
    END_IF;

    // Failover
    bFailoverActive := bIsSecondary AND NOT bPrimaryPLC_Active;

    IF NOT bIsSecondary OR bFailoverActive THEN

        // Diagnostic Evaluation
        IF NOT bProfinetOK THEN iErrorCode := 1001; iState := 4;
        ELSIF rHydraulicPressure > rMaxSafePressure THEN iErrorCode := 2001; iState := 4;
        ELSIF NOT bSecureMode THEN iErrorCode := 4001; iState := 4;
        ELSIF bSensorDrift THEN iErrorCode := 5001; iState := 4; // Sensor drift detected
        ELSIF bTwinMismatch THEN iErrorCode := 5002; iState := 4; // Digital Twin mismatch
        ELSE iErrorCode := 0; 
        END_IF;

        // State Machine
        CASE iState OF
            0: // Init
                IF iErrorCode = 0 THEN iState := 1; END_IF;

            1: // Self-Test
                tSelfTestTimer(IN:=TRUE, PT:=T#3S); // 3-second self-test
                IF tSelfTestTimer.Q THEN
                    bSelfTestPassed := TRUE;
                    tSelfTestTimer(IN:=FALSE);
                    iState := 2;
                END_IF;

            2: // Ready
                IF bStart AND NOT bStop THEN
                    iState := 3;
                ELSIF iErrorCode <> 0 THEN
                    iState := 4;
                END_IF;

            3: // Running
                IF bStop OR iErrorCode <> 0 THEN
                    iState := 4;
                END_IF;

            4: // Fault/Stop
                bSelfTestPassed := FALSE; // Require self-test on reset
                IF bStop AND iErrorCode = 0 THEN // Reset with stop command
                    iState := 0;
                END_IF;
        END_CASE;

        bActive := (iState = 3);
        bSystemRunning := bActive;

        IF bActive THEN
            rShearerLiftCmd := (rShearerTargetElevation - rConsolidatedElevation) * 0.5;
            IF rShearerLiftCmd > 100.0 THEN rShearerLiftCmd := 100.0; END_IF;
            IF rShearerLiftCmd < -100.0 THEN rShearerLiftCmd := -100.0; END_IF;
            rConveyorSpeedCmd := rConveyorTargetSpeed;
        ELSE
            rShearerLiftCmd := 0.0;
            rConveyorSpeedCmd := 0.0;
        END_IF;
    ELSE
        // Standby
        bSystemRunning := FALSE;
        rShearerLiftCmd := 0.0;
        rConveyorSpeedCmd := 0.0;
        iErrorCode := 9999;
    END_IF;

    // SCADA Updates
    stSCADA.bRunning := bSystemRunning;
    stSCADA.iErrorCode := iErrorCode;
    stSCADA.rActualElevation := rConsolidatedElevation;
    stSCADA.rActualSpeed := rConveyorActualSpeed;
    stSCADA.rHydraulicPressure := rHydraulicPressure;
    stSCADA.bSecureModeActive := bSecureMode;
    stSCADA.bTwinSyncOK := NOT bTwinMismatch;
    stSCADA.bSelfTestPassed := bSelfTestPassed;

END_FUNCTION_BLOCK
