FUNCTION_BLOCK FB_RVM_MainController
VAR_INPUT
    bStart_Process          : BOOL; // System start signal
    bEmergencyStop          : BOOL; // Emergency stop signal
    nBarcodeData            : DINT; // Scanned barcode ID
    bItemDetected           : BOOL; // Presence sensor at entry
    rSpectralIRValue        : REAL; // IR spectral reflectivity (0.0-1.0)
    rSpectralUVValue        : REAL; // UV spectral transmittance (0.0-1.0)
    bShapeMatched           : BOOL; // 3D camera shape match success
    nItemWeightGrams        : INT;  // Weight measured in grams
    bBinFull_Plastic        : BOOL; // Plastic bin level switch
    bBinFull_Glass          : BOOL; // Glass bin level switch
    bBinFull_Aluminum       : BOOL; // Aluminum bin level switch
END_VAR
VAR_OUTPUT
    bConveyorEnable         : BOOL; // Main intake conveyor
    nFlipperPosition        : INT;  // 0: Reject, 1: Plastic, 2: Glass, 3: Aluminum
    bCompactorHydraulicPump : BOOL; // Enable hydraulic pump for compaction
    bCompactorValve_Plastic : BOOL; // Fire plastic compaction cylinder
    bCompactorValve_Aluminum: BOOL; // Fire aluminum compaction cylinder
    bSystemReady            : BOOL; // HMI ready light
    bAlarmActive            : BOOL; // General alarm
    nErrorCode              : INT;  // Error diagnostic code
END_VAR
VAR
    eState                  : INT := 0; // State machine step
    tConveyorTimer          : TON;
    tFlipperTimer           : TON;
    tCompactorTimer         : TON;
    tDelay                  : TIME;
    eMaterialType           : INT := 0; // 0: Unknown, 1: PET, 2: Glass, 3: Alu
    rConfLevelPlastic       : REAL;
    rConfLevelGlass         : REAL;
    rConfLevelAluminum      : REAL;
    nItemsProcessed         : DINT := 0;
END_VAR

// ==============================================================================
// State Machine for High-Speed Sorting and Compaction
// ==============================================================================
IF bEmergencyStop THEN
    eState := 999;
END_IF;

CASE eState OF
    0: // Initialization & Idle
        bConveyorEnable := FALSE;
        bCompactorHydraulicPump := FALSE;
        bCompactorValve_Plastic := FALSE;
        bCompactorValve_Aluminum := FALSE;
        nFlipperPosition := 0;
        bSystemReady := NOT (bBinFull_Plastic OR bBinFull_Glass OR bBinFull_Aluminum);
        bAlarmActive := FALSE;
        nErrorCode := 0;

        IF bStart_Process AND bSystemReady THEN
            eState := 10;
        ELSIF bStart_Process AND NOT bSystemReady THEN
            nErrorCode := 1001; // Bins full
            bAlarmActive := TRUE;
        END_IF;

    10: // Active Scanning Phase
        bConveyorEnable := TRUE;
        bSystemReady := TRUE;
        IF bItemDetected THEN
            // Trigger item classification
            eState := 20;
        END_IF;

    20: // Sensor Fusion & Classification (Spectral, Shape, Weight)
        // Reset confidence
        rConfLevelPlastic := 0.0;
        rConfLevelGlass := 0.0;
        rConfLevelAluminum := 0.0;
        eMaterialType := 0; // Unknown

        // Analyze Spectral Signatures
        IF rSpectralIRValue > 0.8 AND rSpectralUVValue < 0.2 THEN
            rConfLevelPlastic := rConfLevelPlastic + 0.4;
        END_IF;
        IF rSpectralIRValue < 0.3 AND rSpectralUVValue > 0.7 THEN
            rConfLevelGlass := rConfLevelGlass + 0.5;
        END_IF;
        IF rSpectralIRValue > 0.5 AND rSpectralIRValue < 0.7 THEN
            rConfLevelAluminum := rConfLevelAluminum + 0.6;
        END_IF;

        // Weight verification
        IF nItemWeightGrams > 10 AND nItemWeightGrams < 50 THEN
            rConfLevelPlastic := rConfLevelPlastic + 0.3;
            rConfLevelAluminum := rConfLevelAluminum + 0.2;
        ELSIF nItemWeightGrams > 100 AND nItemWeightGrams < 800 THEN
            rConfLevelGlass := rConfLevelGlass + 0.3;
        END_IF;

        // Shape and Barcode verification
        IF bShapeMatched THEN
            rConfLevelPlastic := rConfLevelPlastic + 0.1;
            rConfLevelGlass := rConfLevelGlass + 0.1;
            rConfLevelAluminum := rConfLevelAluminum + 0.1;
        END_IF;

        IF nBarcodeData > 0 THEN // valid barcode
            // Assuming database lookup completed asynchronously and updated confidence
            rConfLevelPlastic := rConfLevelPlastic + 0.2;
        END_IF;

        // Determine Highest Confidence
        IF rConfLevelPlastic >= 0.7 THEN
            eMaterialType := 1;
        ELSIF rConfLevelGlass >= 0.8 THEN
            eMaterialType := 2;
        ELSIF rConfLevelAluminum >= 0.8 THEN
            eMaterialType := 3;
        ELSE
            eMaterialType := 0; // Reject
        END_IF;

        eState := 30;

    30: // Actuate High-Speed Sorting Flipper
        // Flipper target matches material type
        nFlipperPosition := eMaterialType;

        tFlipperTimer(IN:=TRUE, PT:=T#150ms);
        IF tFlipperTimer.Q THEN
            tFlipperTimer(IN:=FALSE);
            IF eMaterialType = 1 THEN
                eState := 40; // Plastic Compaction
            ELSIF eMaterialType = 3 THEN
                eState := 50; // Aluminum Compaction
            ELSIF eMaterialType = 2 THEN
                eState := 60; // Glass (No compaction, just route)
            ELSE
                eState := 70; // Reject handling
            END_IF;
        END_IF;

    40: // Hydraulic Compaction: Plastic
        bCompactorHydraulicPump := TRUE;
        tCompactorTimer(IN:=TRUE, PT:=T#500ms);
        IF tCompactorTimer.Q THEN
            bCompactorValve_Plastic := TRUE;
            // Wait for stroke complete
            tDelay := T#2S;
            IF tCompactorTimer.ET > (T#500ms + tDelay) THEN
                bCompactorValve_Plastic := FALSE;
                bCompactorHydraulicPump := FALSE;
                tCompactorTimer(IN:=FALSE);
                nItemsProcessed := nItemsProcessed + 1;
                eState := 10;
            END_IF;
        END_IF;

    50: // Hydraulic Compaction: Aluminum
        bCompactorHydraulicPump := TRUE;
        tCompactorTimer(IN:=TRUE, PT:=T#300ms);
        IF tCompactorTimer.Q THEN
            bCompactorValve_Aluminum := TRUE;
            // Wait for stroke complete
            tDelay := T#1500MS;
            IF tCompactorTimer.ET > (T#300ms + tDelay) THEN
                bCompactorValve_Aluminum := FALSE;
                bCompactorHydraulicPump := FALSE;
                tCompactorTimer(IN:=FALSE);
                nItemsProcessed := nItemsProcessed + 1;
                eState := 10;
            END_IF;
        END_IF;

    60: // Route Glass
        // Glass falls through chute, no compaction
        nItemsProcessed := nItemsProcessed + 1;
        eState := 10;

    70: // Reject
        // Item returned to user
        eState := 10;

    999: // Emergency Stop / Fault
        bConveyorEnable := FALSE;
        bCompactorHydraulicPump := FALSE;
        bCompactorValve_Plastic := FALSE;
        bCompactorValve_Aluminum := FALSE;
        nFlipperPosition := 0;
        bSystemReady := FALSE;
        bAlarmActive := TRUE;
        nErrorCode := 9999; // E-Stop pressed

        IF NOT bEmergencyStop THEN // Reset condition
            eState := 0;
        END_IF;

    ELSE
        eState := 0;
END_CASE;
END_FUNCTION_BLOCK
