FUNCTION_BLOCK FB_GasAtomizerControl
TITLE = 'Metal Powder Gas Atomizer Control System'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Architect'

VAR_INPUT
    bEnableSystem       : BOOL;   (* Master enable *)
    bStartProcess       : BOOL;   (* Start atomization cycle *)
    bEmergencyStop      : BOOL;   (* Safety E-Stop *)
    rVIM_Temp_PV        : REAL;   (* Vacuum Induction Melting Crucible Temp (C) *)
    rVIM_Temp_SP        : REAL;   (* Target Melt Temp (C) *)
    rArgonPress_PV      : REAL;   (* Atomization Gas Pressure (Bar) *)
    rArgonPress_SP      : REAL;   (* Target Gas Pressure (Bar) *)
    rCycloneDiffPress_PV: REAL;   (* Cyclone Classification Diff Press (mBar) *)
    rMeltLevel_PV       : REAL;   (* Tundish melt level (%) *)
END_VAR

VAR_OUTPUT
    rInductionPower_CV  : REAL;   (* Induction Heater Power Control (0-100%) *)
    rArgonValve_CV      : REAL;   (* Argon Flow Valve Position (0-100%) *)
    bCycloneRotaryValve : BOOL;   (* Cyclone Powder Collection Rotary Valve *)
    bVacuumPumpCmd      : BOOL;   (* Vacuum pump command *)
    iSystemState        : INT;    (* 0:Idle, 1:PumpDown, 2:Melt, 3:Atomize, 4:Cool, 99:Fault *)
    bAlarmActive        : BOOL;   (* System fault active *)
    sStatusMessage      : STRING[50];
END_VAR

VAR
    // Timers
    tonMeltSoak         : TON;
    tonPurge            : TON;
    tonCooling          : TON;

    // State Machine
    State               : INT := 0;
    bFault              : BOOL := FALSE;

    // Internal process variables
    rTempError          : REAL;
    rPressError         : REAL;
    rHeaterProportional : REAL := 2.5;
    rValveProportional  : REAL := 5.0;
    rDerivError         : REAL := 0.0;
    rLastTempError      : REAL := 0.0;
END_VAR

(* --- MAIN LOGIC --- *)

// 1. Emergency Stop and Fault Handling
IF bEmergencyStop THEN
    bFault := TRUE;
    State := 99;
    sStatusMessage := 'E-STOP ACTIVATED';
END_IF;

// 2. State Machine
CASE State OF
    0: // IDLE
        rInductionPower_CV := 0.0;
        rArgonValve_CV := 0.0;
        bCycloneRotaryValve := FALSE;
        bVacuumPumpCmd := FALSE;
        bAlarmActive := FALSE;
        sStatusMessage := 'System Idle';

        IF bEnableSystem AND bStartProcess AND NOT bFault THEN
            State := 1;
        END_IF;

    1: // PUMP DOWN / PURGE
        bVacuumPumpCmd := TRUE;
        sStatusMessage := 'Chamber Evacuation & Purge';
        tonPurge(IN:= TRUE, PT:= T#5M);
        IF tonPurge.Q THEN
            tonPurge(IN:= FALSE);
            State := 2;
        END_IF;

    2: // VIM HEATING & MELTING
        bVacuumPumpCmd := TRUE;
        sStatusMessage := 'VIM Heating & Soak';

        rTempError := rVIM_Temp_SP - rVIM_Temp_PV;
        rDerivError := rTempError - rLastTempError;

        // Simple PD-Control for Heater
        IF rTempError > 0.0 THEN
            rInductionPower_CV := (rTempError * rHeaterProportional) + (rDerivError * 1.5);
            IF rInductionPower_CV > 100.0 THEN rInductionPower_CV := 100.0; END_IF;
            IF rInductionPower_CV < 0.0 THEN rInductionPower_CV := 0.0; END_IF;
        ELSE
            rInductionPower_CV := 0.0;
        END_IF;
        rLastTempError := rTempError;

        // Check if temperature reached SP and soak
        tonMeltSoak(IN:= (ABS(rTempError) < 15.0), PT:= T#10M);
        IF tonMeltSoak.Q AND (rMeltLevel_PV > 80.0) THEN
            tonMeltSoak(IN:= FALSE);
            State := 3;
        END_IF;

    3: // ATOMIZATION PHASE
        sStatusMessage := 'High-Pressure Gas Atomization';

        // Maintain heat
        rTempError := rVIM_Temp_SP - rVIM_Temp_PV;
        rInductionPower_CV := rTempError * rHeaterProportional;
        IF rInductionPower_CV > 100.0 THEN rInductionPower_CV := 100.0; END_IF;
        IF rInductionPower_CV < 0.0 THEN rInductionPower_CV := 0.0; END_IF;

        // Control Argon Gas Pressure
        rPressError := rArgonPress_SP - rArgonPress_PV;
        rArgonValve_CV := rArgonValve_CV + (rPressError * rValveProportional * 0.1);
        IF rArgonValve_CV > 100.0 THEN rArgonValve_CV := 100.0; END_IF;
        IF rArgonValve_CV < 0.0 THEN rArgonValve_CV := 0.0; END_IF;

        // Cyclone Classification Monitoring
        IF (rCycloneDiffPress_PV > 50.0) AND (rCycloneDiffPress_PV < 150.0) THEN
            bCycloneRotaryValve := TRUE; // Extract classified powder
        ELSE
            bCycloneRotaryValve := FALSE;
        END_IF;

        // Transition to cool down when melt is depleted
        IF rMeltLevel_PV < 5.0 THEN
            State := 4;
        END_IF;

    4: // COOL DOWN
        sStatusMessage := 'System Cool Down';
        rInductionPower_CV := 0.0;
        rArgonValve_CV := 0.0;
        bCycloneRotaryValve := FALSE;

        tonCooling(IN:= TRUE, PT:= T#30M);
        IF tonCooling.Q AND (rVIM_Temp_PV < 100.0) THEN
            tonCooling(IN:= FALSE);
            bVacuumPumpCmd := FALSE;
            State := 0; // Return to idle
        END_IF;

    99: // FAULT STATE
        rInductionPower_CV := 0.0;
        rArgonValve_CV := 0.0;
        bCycloneRotaryValve := FALSE;
        bVacuumPumpCmd := FALSE;
        bAlarmActive := TRUE;

        IF NOT bEmergencyStop AND bEnableSystem THEN
            bFault := FALSE;
            State := 0;
        END_IF;
END_CASE;

iSystemState := State;
END_FUNCTION_BLOCK
