FUNCTION_BLOCK FB_GlassFiberDrawTowerControl
VAR_INPUT
    bEnable : BOOL; // Enable draw tower control
    rFurnaceLevelSetpoint : REAL; // Target furnace melt level (mm)
    rFurnaceLevelActual : REAL; // Actual furnace melt level (mm)
    rBushingTempSetpoint : REAL; // Target bushing tip temp (deg C)
    rBushingTempActual : REAL; // Actual bushing tip temp (deg C)
    rWinderSpeedSetpoint : REAL; // Target winder speed (m/s)
    rWinderTensionActual : REAL; // Actual winder tension (N)
    rTensionSetpoint : REAL; // Target winder tension (N)
    bEmergencyStop : BOOL; // E-Stop condition
    bReset : BOOL; // Reset fault conditions
END_VAR
VAR_OUTPUT
    rFurnaceFeedRateCmd : REAL; // Command to raw material feeder (kg/h)
    rBushingPowerCmd : REAL; // Command to bushing transformer (kW)
    rWinderTorqueCmd : REAL; // Command to winder motor (Nm)
    bSystemReady : BOOL; // System ready to draw
    bFaultActive : BOOL; // General fault active
    iFaultCode : INT; // Fault code
END_VAR
VAR
    // PID for Furnace Level
    fbFurnacePID : FB_PID_Controller;
    // PID for Bushing Temperature
    fbBushingPID : FB_PID_Controller;
    // PID for Winder Tension
    fbWinderPID : FB_PID_Controller;

    rLevelError : REAL;
    rTempError : REAL;
    rTensionError : REAL;

    // Limits
    MAX_FEED_RATE : REAL := 500.0;
    MAX_BUSHING_POWER : REAL := 150.0;
    MAX_WINDER_TORQUE : REAL := 100.0;

    // State Machine
    eState : (INIT, HEATING, LEVELING, DRAWING, FAULT);

    tTimer : TON;
END_VAR

// Main control logic
IF bEmergencyStop THEN
    eState := FAULT;
    iFaultCode := 99; // E-Stop
ELSIF bReset AND eState = FAULT THEN
    eState := INIT;
    bFaultActive := FALSE;
    iFaultCode := 0;
END_IF;

CASE eState OF
    INIT:
        rFurnaceFeedRateCmd := 0.0;
        rBushingPowerCmd := 0.0;
        rWinderTorqueCmd := 0.0;
        bSystemReady := FALSE;
        IF bEnable THEN
            eState := HEATING;
        END_IF;

    HEATING:
        // Heat bushing to setpoint
        rTempError := rBushingTempSetpoint - rBushingTempActual;
        fbBushingPID(
            rSetpoint := rBushingTempSetpoint,
            rActual := rBushingTempActual,
            rKp := 2.5,
            rKi := 0.1,
            rKd := 0.05,
            rMaxOutput := MAX_BUSHING_POWER,
            rMinOutput := 0.0,
            rOutput => rBushingPowerCmd
        );
        IF ABS(rTempError) < 5.0 THEN
            tTimer(IN:=TRUE, PT:=T#5S);
            IF tTimer.Q THEN
                tTimer(IN:=FALSE);
                eState := LEVELING;
            END_IF;
        ELSE
            tTimer(IN:=FALSE);
        END_IF;

    LEVELING:
        // Maintain furnace level
        fbBushingPID(rSetpoint:=rBushingTempSetpoint, rActual:=rBushingTempActual, rOutput=>rBushingPowerCmd);
        rLevelError := rFurnaceLevelSetpoint - rFurnaceLevelActual;
        fbFurnacePID(
            rSetpoint := rFurnaceLevelSetpoint,
            rActual := rFurnaceLevelActual,
            rKp := 1.2,
            rKi := 0.05,
            rKd := 0.01,
            rMaxOutput := MAX_FEED_RATE,
            rMinOutput := 0.0,
            rOutput => rFurnaceFeedRateCmd
        );
        IF ABS(rLevelError) < 2.0 THEN
            bSystemReady := TRUE;
            eState := DRAWING;
        END_IF;

    DRAWING:
        bSystemReady := TRUE;
        fbBushingPID(rSetpoint:=rBushingTempSetpoint, rActual:=rBushingTempActual, rOutput=>rBushingPowerCmd);
        fbFurnacePID(rSetpoint:=rFurnaceLevelSetpoint, rActual:=rFurnaceLevelActual, rOutput=>rFurnaceFeedRateCmd);

        // Control tension
        rTensionError := rTensionSetpoint - rWinderTensionActual;
        fbWinderPID(
            rSetpoint := rTensionSetpoint,
            rActual := rWinderTensionActual,
            rKp := 5.0,
            rKi := 0.5,
            rKd := 0.1,
            rMaxOutput := MAX_WINDER_TORQUE,
            rMinOutput := 0.0,
            rOutput => rWinderTorqueCmd
        );

        // Check fault conditions
        IF rBushingTempActual > 1500.0 THEN
            eState := FAULT;
            iFaultCode := 1; // Over temp
        END_IF;
        IF rWinderTensionActual > 500.0 THEN
            eState := FAULT;
            iFaultCode := 2; // Over tension
        END_IF;

    FAULT:
        rFurnaceFeedRateCmd := 0.0;
        rBushingPowerCmd := 0.0;
        rWinderTorqueCmd := 0.0;
        bSystemReady := FALSE;
        bFaultActive := TRUE;
END_CASE;
END_FUNCTION_BLOCK
