FUNCTION_BLOCK FB_HydrogenElectrolyzerMegawattArray
VAR_INPUT
    bEnable : BOOL; // System enable command
    rTargetProduction : REAL; // Target H2 production rate (kg/h)
    rDCCurrentSetpoint : REAL; // Requested DC current (A)
    rInletWaterTemp : REAL; // DI water inlet temperature (°C)
    rStackVoltage : REAL; // Overall stack voltage (V)
    rH2PurityCrossMembrane : REAL; // H2 purity measured (vol %)
    rO2PurityCrossMembrane : REAL; // O2 purity measured (vol %)
    rStackPressure : REAL; // Operating pressure (bar)
    rDIWaterFlowRate : REAL; // DI water flow (L/min)
END_VAR

VAR_OUTPUT
    bDCPowerSupplyEnable : BOOL; // Enable to DC power supply
    rDCCurrentCommand : REAL; // Modulated DC current command (A)
    rDIWaterPumpSpeed : REAL; // 0-100% pump speed
    bVentValveOpen : BOOL; // Safety vent valve
    bPurgeValveOpen : BOOL; // Nitrogen purge valve
    bSystemReady : BOOL; // Ready for operation
    bFault : BOOL; // General fault flag
    iFaultCode : INT; // Error code for diagnostics
END_VAR

VAR
    rCurrentRampRate : REAL := 10.0; // A/s
    rMaxCurrent : REAL := 15000.0; // Max allowed current
    rMinPurity : REAL := 99.5; // Min safe H2 purity
    rMaxTemp : REAL := 80.0; // Max operating temperature
    rMaxPressure : REAL := 35.0; // Max operating pressure
    rActualCurrentCmd : REAL := 0.0;

    // Timers
    tStartupDelay : TON;
    tPurgeTimer : TON;

    // State Machine
    iState : INT := 0; 
    (* States:
       0: Init
       1: Purge
       2: Standby
       3: Ramping
       4: Production
       5: Shutdown
       6: Fault
    *)
END_VAR

// Control Logic
tStartupDelay(IN:= (iState = 2) AND bEnable, PT:= T#5S);
tPurgeTimer(IN:= (iState = 1), PT:= T#30S);

CASE iState OF
    0: // Init
        bDCPowerSupplyEnable := FALSE;
        rActualCurrentCmd := 0.0;
        rDIWaterPumpSpeed := 0.0;
        bVentValveOpen := TRUE;
        bPurgeValveOpen := FALSE;
        bSystemReady := FALSE;
        bFault := FALSE;
        iFaultCode := 0;
        iState := 1;

    1: // Purge
        bPurgeValveOpen := TRUE;
        bVentValveOpen := TRUE;
        IF tPurgeTimer.Q THEN
            bPurgeValveOpen := FALSE;
            iState := 2;
        END_IF

    2: // Standby
        bSystemReady := TRUE;
        bVentValveOpen := FALSE;
        IF bEnable AND tStartupDelay.Q THEN
            iState := 3;
        ELSIF NOT bEnable THEN
            // Remain in Standby
        END_IF

    3: // Ramping
        bDCPowerSupplyEnable := TRUE;
        rDIWaterPumpSpeed := 50.0; // Base flow

        // Ramp up logic
        IF rActualCurrentCmd < rDCCurrentSetpoint THEN
            rActualCurrentCmd := rActualCurrentCmd + (rCurrentRampRate * 0.1); // Assuming 100ms cycle
        ELSE
            iState := 4; // Reached setpoint
        END_IF

        rDCCurrentCommand := rActualCurrentCmd;

    4: // Production
        // Maintain setpoints, monitor safeties
        rDCCurrentCommand := rDCCurrentSetpoint;

        // Flow control cascade based on temp
        IF rInletWaterTemp > 65.0 THEN
            rDIWaterPumpSpeed := 100.0;
        ELSIF rInletWaterTemp > 50.0 THEN
            rDIWaterPumpSpeed := 75.0;
        ELSE
            rDIWaterPumpSpeed := 50.0;
        END_IF

    5: // Shutdown
        bDCPowerSupplyEnable := FALSE;
        rActualCurrentCmd := 0.0;
        rDCCurrentCommand := 0.0;
        bVentValveOpen := TRUE;
        iState := 0;

    6: // Fault
        bDCPowerSupplyEnable := FALSE;
        rActualCurrentCmd := 0.0;
        rDCCurrentCommand := 0.0;
        bPurgeValveOpen := TRUE;
        bVentValveOpen := TRUE;
        bFault := TRUE;
END_CASE

// Safety Checks (Active in all states except Init/Fault)
IF iState > 0 AND iState < 6 THEN
    IF rH2PurityCrossMembrane < rMinPurity THEN
        iState := 6;
        iFaultCode := 101; // Purity fault
    END_IF
    IF rInletWaterTemp > rMaxTemp THEN
        iState := 6;
        iFaultCode := 102; // Over temp
    END_IF
    IF rStackPressure > rMaxPressure THEN
        iState := 6;
        iFaultCode := 103; // Over pressure
    END_IF
    IF rStackVoltage > 250.0 THEN
        iState := 6;
        iFaultCode := 104; // Over voltage
    END_IF
END_IF

// External Stop
IF NOT bEnable AND (iState = 3 OR iState = 4) THEN
    iState := 5;
END_IF
END_FUNCTION_BLOCK
