FUNCTION_BLOCK FB_SFCL_Cryostat
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal, interlocked with substation protection *)
    bEmergencyStop          : BOOL;     (* E-Stop safety relay OK signal *)
    rGridVoltageKV          : REAL;     (* Measured 66kV grid voltage for quench detection *)
    rGridCurrentKA          : REAL;     (* Measured grid current for rapid fault detection *)
    rLN2LevelMM             : REAL;     (* Liquid Nitrogen (LN2) level in cryostat, mm *)
    rCryostatTempK          : REAL;     (* Superconductor temperature in Kelvin, operational range 65K-75K *)
    rSubCoolerPressureBAR   : REAL;     (* Sub-cooler operating pressure, typical 1.2 bar *)
    bFaultAcknowledge       : BOOL;     (* Operator reset for soft fault conditions *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* SFCL is ready and in fully superconducting state *)
    rCryoCoolerValveCmd     : REAL;     (* 0-100% control for LN2 sub-cooler cryocooler loop *)
    rLN2FillValveCmd        : REAL;     (* 0-100% control for LN2 auto-fill valve *)
    bQuenchDetected         : BOOL;     (* Critical signal: Quench occurred, tripping bypass breakers *)
    bWarningAlarm           : BOOL;     (* Non-critical warning (e.g. LN2 level approaching low limit) *)
    bCriticalAlarm          : BOOL;     (* Critical fault requiring immediate operator intervention *)
END_VAR
VAR
    (* Internal state variables *)
    iCryoState              : INT := 0; (* 0:Init, 10:Cooldown, 20:Standby, 30:Run, 40:Quench, 99:Fault *)
    tQuenchTimer            : TON;      (* Extremely fast timer for dI/dt detection qualification *)
    tRecoveryTimer          : TON;      (* Post-quench thermal recovery stabilization delay *)
    rFilteredTemp           : REAL;     (* First-order low-pass filtered temp *)
    rTempAlpha              : REAL := 0.1; (* Smoothing factor *)

    (* PID variables for LN2 Level Control *)
    rLevelSetpoint          : REAL := 1500.0;
    rLevelError             : REAL;
    rLevelIntegral          : REAL := 0.0;
    Kp                      : REAL := 2.5;
    Ki                      : REAL := 0.05;

    (* Limit Constants *)
    TEMP_MAX_SUPERCOND      : REAL := 76.5; 
    TEMP_QUENCH_TRIP        : REAL := 82.0;
    CURRENT_FAULT_KA        : REAL := 15.0;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety & Emergency Stop Evaluation *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bQuenchDetected := FALSE;
    rCryoCoolerValveCmd := 0.0;
    rLN2FillValveCmd := 0.0;
    bCriticalAlarm := TRUE;
    iCryoState := 99; (* Force fault state *)
    RETURN;
END_IF;

(* 2. Sensor Filtering & Basic Diagnostics *)
rFilteredTemp := (rTempAlpha * rCryostatTempK) + ((1.0 - rTempAlpha) * rFilteredTemp);

(* 3. High-Speed Quench Detection *)
IF (rGridCurrentKA > CURRENT_FAULT_KA) OR (rFilteredTemp > TEMP_QUENCH_TRIP) THEN
    tQuenchTimer(IN := TRUE, PT := T#2MS); (* 2 millisecond debounce for dI/dt noise *)
    IF tQuenchTimer.Q THEN
        bQuenchDetected := TRUE;
        iCryoState := 40;
    END_IF;
ELSE
    tQuenchTimer(IN := FALSE);
END_IF;

(* 4. LN2 Level PID Control (Background Task) *)
rLevelError := rLevelSetpoint - rLN2LevelMM;
IF NOT bCriticalAlarm THEN
    rLevelIntegral := rLevelIntegral + (rLevelError * 0.1); (* 100ms cycle approx *)
    (* Anti-windup *)
    IF rLevelIntegral > 100.0 THEN rLevelIntegral := 100.0; END_IF;
    IF rLevelIntegral < 0.0 THEN rLevelIntegral := 0.0; END_IF;

    rLN2FillValveCmd := (Kp * rLevelError) + (Ki * rLevelIntegral);
    IF rLN2FillValveCmd > 100.0 THEN rLN2FillValveCmd := 100.0; END_IF;
    IF rLN2FillValveCmd < 0.0 THEN rLN2FillValveCmd := 0.0; END_IF;
ELSE
    rLN2FillValveCmd := 0.0;
END_IF;

(* 5. State Machine Control *)
CASE iCryoState OF
    0: (* INIT *)
        bSystemReady := FALSE;
        bWarningAlarm := FALSE;
        IF bEnable THEN
            iCryoState := 10;
        END_IF;

    10: (* COOLDOWN *)
        rCryoCoolerValveCmd := 100.0; (* Full cooling power *)
        IF rFilteredTemp <= TEMP_MAX_SUPERCOND THEN
            iCryoState := 20;
        END_IF;

    20: (* STANDBY *)
        rCryoCoolerValveCmd := 50.0; (* Maintenance cooling *)
        bSystemReady := TRUE;
        IF bEnable AND rGridVoltageKV > 60.0 THEN
            iCryoState := 30;
        END_IF;

    30: (* RUN / ACTIVE GRID CONNECTION *)
        (* Precise sub-cooler loop management *)
        rCryoCoolerValveCmd := 40.0 + (rFilteredTemp - 65.0) * 5.0;
        IF rCryoCoolerValveCmd > 100.0 THEN rCryoCoolerValveCmd := 100.0; END_IF;
        IF rCryoCoolerValveCmd < 0.0 THEN rCryoCoolerValveCmd := 0.0; END_IF;

        IF NOT bEnable THEN
            iCryoState := 20;
        END_IF;

    40: (* QUENCH HANDLING & RECOVERY *)
        bSystemReady := FALSE;
        rCryoCoolerValveCmd := 100.0; (* Max cooling to recover superconducting state *)

        tRecoveryTimer(IN := TRUE, PT := T#300S); (* 5 minute thermal recovery *)
        IF tRecoveryTimer.Q AND (rFilteredTemp <= TEMP_MAX_SUPERCOND) AND bFaultAcknowledge THEN
            tRecoveryTimer(IN := FALSE);
            bQuenchDetected := FALSE;
            iCryoState := 20;
        END_IF;

    99: (* FAULT *)
        bSystemReady := FALSE;
        bCriticalAlarm := TRUE;
        IF bFaultAcknowledge AND bEmergencyStop THEN
            bCriticalAlarm := FALSE;
            iCryoState := 0;
        END_IF;

END_CASE;

(* 6. Warning Logic *)
IF rLN2LevelMM < 1200.0 THEN
    bWarningAlarm := TRUE;
ELSE
    bWarningAlarm := FALSE;
END_IF;

END_FUNCTION_BLOCK
