FUNCTION_BLOCK FB_SkyscraperElevatorMasterControl
TITLE = 'Skyscraper High-Speed Elevator Master Control'
VERSION : '2.1'
AUTHOR : 'Lumina AI Elite'

VAR_INPUT
    bEnable                 : BOOL; // Master enable for the control system
    rActualVelocity         : REAL; // Actual car velocity (m/s) from encoder
    rCommandedVelocity      : REAL; // Commanded velocity (m/s)
    rSheaveSpeed            : REAL; // Traction sheave angular velocity (rad/s)
    rSheaveRadius           : REAL; // Traction sheave radius (m)
    rCarMass                : REAL; // Live car mass including passengers (kg)
    rCounterweightMass      : REAL; // Counterweight mass (kg)
    rHoistwayVibrationX     : REAL; // X-axis acceleration from accelerometer (m/s^2)
    rHoistwayVibrationY     : REAL; // Y-axis acceleration from accelerometer (m/s^2)
    iActiveZone             : INT;  // Current destination dispatch zone (1..10)
    arrHallCalls            : ARRAY[1..100] OF BOOL; // Destination dispatch hall calls
END_VAR

VAR_OUTPUT
    rSlipCompensationTq     : REAL; // Additional torque required to compensate for slip (Nm)
    rActiveRollerForceX     : REAL; // Commanded force for X-axis active roller guides (N)
    rActiveRollerForceY     : REAL; // Commanded force for Y-axis active roller guides (N)
    iNextDispatchFloor      : INT;  // Calculated next optimum floor based on zoning
    bSlipWarning            : BOOL; // True if sheave slip exceeds safety threshold
    bVibrationWarning       : BOOL; // True if vibration exceeds damping capabilities
END_VAR

VAR
    // Slip Compensation Internal Variables
    rTheoreticalVelocity    : REAL;
    rVelocityError          : REAL;
    rSlipIntegral           : REAL := 0.0;
    rKp_Slip                : REAL := 1500.0;
    rKi_Slip                : REAL := 500.0;
    rSlipThreshold          : REAL := 0.15; // 15% slip safety limit

    // Active Roller Guide Internal Variables
    rKp_Vib                 : REAL := 8000.0;
    rKd_Vib                 : REAL := 2500.0;
    rPrevVibrationX         : REAL := 0.0;
    rPrevVibrationY         : REAL := 0.0;
    rDerivativeX            : REAL;
    rDerivativeY            : REAL;
    rVibThreshold           : REAL := 2.5; // m/s^2

    // Zoning Internal Variables
    iLoop                   : INT;
    iClosestCall            : INT;
    iMinDistance            : INT;
    iCurrentFloor           : INT;
END_VAR

// --- [1] Traction Sheave Slip Compensation ---
// Calculate theoretical velocity based on sheave speed
rTheoreticalVelocity := rSheaveSpeed * rSheaveRadius;
rVelocityError := rTheoreticalVelocity - rActualVelocity;

IF bEnable THEN
    // PI Controller for Slip Compensation
    rSlipIntegral := rSlipIntegral + (rVelocityError * 0.01); // Assuming 10ms cycle time

    // Anti-windup
    IF rSlipIntegral > 1000.0 THEN rSlipIntegral := 1000.0; END_IF;
    IF rSlipIntegral < -1000.0 THEN rSlipIntegral := -1000.0; END_IF;

    rSlipCompensationTq := (rKp_Slip * rVelocityError) + (rKi_Slip * rSlipIntegral);

    // Dynamic load adjustment (Roping ratio assumed 1:1 for high speed)
    rSlipCompensationTq := rSlipCompensationTq + ((rCarMass - rCounterweightMass) * 9.81 * rSheaveRadius * 0.05); // 5% feed-forward

    // Slip Safety Monitor
    IF ABS(rVelocityError) > (rSlipThreshold * rTheoreticalVelocity) AND rTheoreticalVelocity > 0.5 THEN
        bSlipWarning := TRUE;
    ELSE
        bSlipWarning := FALSE;
    END_IF;
ELSE
    rSlipCompensationTq := 0.0;
    rSlipIntegral := 0.0;
    bSlipWarning := FALSE;
END_IF;

// --- [2] Active Roller Guide Vibration Damping ---
IF bEnable THEN
    // Calculate derivatives for PD control (Assuming 10ms cycle)
    rDerivativeX := (rHoistwayVibrationX - rPrevVibrationX) / 0.01;
    rDerivativeY := (rHoistwayVibrationY - rPrevVibrationY) / 0.01;

    // Apply opposing force to dampen vibration (Sky-hook damping strategy)
    rActiveRollerForceX := -(rKp_Vib * rHoistwayVibrationX) - (rKd_Vib * rDerivativeX);
    rActiveRollerForceY := -(rKp_Vib * rHoistwayVibrationY) - (rKd_Vib * rDerivativeY);

    // Update previous states
    rPrevVibrationX := rHoistwayVibrationX;
    rPrevVibrationY := rHoistwayVibrationY;

    // Safety Monitor
    IF ABS(rHoistwayVibrationX) > rVibThreshold OR ABS(rHoistwayVibrationY) > rVibThreshold THEN
        bVibrationWarning := TRUE;
    ELSE
        bVibrationWarning := FALSE;
    END_IF;
ELSE
    rActiveRollerForceX := 0.0;
    rActiveRollerForceY := 0.0;
    bVibrationWarning := FALSE;
END_IF;

// --- [3] Destination Dispatch Hall Call Zoning ---
// Determine the next optimal floor based on dynamic zoning constraints
iMinDistance := 999;
iClosestCall := 0;

// Estimate current floor based on active zone (simple heuristic for example)
iCurrentFloor := (iActiveZone * 10) - 5; // Midpoint of the 10-floor zone

IF bEnable THEN
    FOR iLoop := ((iActiveZone - 1) * 10 + 1) TO (iActiveZone * 10) DO
        IF arrHallCalls[iLoop] THEN
            IF ABS(iLoop - iCurrentFloor) < iMinDistance THEN
                iMinDistance := ABS(iLoop - iCurrentFloor);
                iClosestCall := iLoop;
            END_IF;
        END_IF;
    END_FOR;

    IF iClosestCall <> 0 THEN
        iNextDispatchFloor := iClosestCall;
    ELSE
        // Fallback to default parking floor for the zone if no calls
        iNextDispatchFloor := (iActiveZone * 10) - 9;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
