FUNCTION_BLOCK "BeverageFiller_Capping"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    BottlePresent : Bool;
    CapPresent : Bool;
    FillLevelSensor : Real; 
    CarbonationPressure : Real; 
    TargetLevel : Real;
    TargetPressure : Real;
    TargetTorque : Real;
    ActualTorque : Real;
