VAR_OUTPUT
    FillValve : Bool;
    CO2Valve : Bool;
    ConveyorMotor : Bool;
    CapperMotor : Bool;
    Ready : Bool;
END_VAR
VAR
    FillingState : Int;
END_VAR

BEGIN
    IF Stop THEN
        FillValve := FALSE;
        CO2Valve := FALSE;
        ConveyorMotor := FALSE;
        CapperMotor := FALSE;
        FillingState := 0;
        Ready := FALSE;
        RETURN;
    END_IF;

    CASE FillingState OF
        0: // Idle
            ConveyorMotor := Start;
            Ready := TRUE;
            IF BottlePresent THEN
                ConveyorMotor := FALSE;
                FillingState := 1;
            END_IF;
        1: // Carbonation
            Ready := FALSE;
            IF CarbonationPressure < TargetPressure THEN
                CO2Valve := TRUE;
            ELSE
                CO2Valve := FALSE;
                FillingState := 2;
            END_IF;
        2: // Filling
            IF FillLevelSensor < TargetLevel THEN
                FillValve := TRUE;
            ELSE
                FillValve := FALSE;
                FillingState := 3;
            END_IF;
        3: // Capping
            IF CapPresent AND ActualTorque < TargetTorque THEN
                CapperMotor := TRUE;
            ELSE
                CapperMotor := FALSE;
                FillingState := 0;
            END_IF;
    END_CASE;
