Here is the enhanced code with Profinet communication diagnostics and specific fault codes:

FUNCTION_BLOCK "SagMill_Control_Profinet_Diag"
VERSION : 0.1
   VAR_INPUT 
      start_cmd : Bool;   
      stop_cmd : Bool;    
      reset_cmd : Bool;
      mill_speed_act : Real; 
      lp_lube_pressure_act : Real; 
      hp_lube_pressure_act : Real; 
      trunnion_lift_act : Real; 
      lube_temp_act : Real; 
      ore_feed_rate_sp : Real; 
      mill_weight_act : Real; 
      // Profinet Diagnostics
      pn_vfd_lp_ok : Bool;
      pn_vfd_hp_ok : Bool;
      pn_vfd_main_ok : Bool;
      pn_vfd_feeder_ok : Bool;
   END_VAR

   VAR_OUTPUT 
      lp_lube_pump_cmd : Bool;   
      hp_lube_pump_cmd : Bool;
      mill_motor_cmd : Bool;  
      ore_feeder_cmd : Real;  
      fault_active : Bool;
      fault_code : Word; // Specific diagnostic code
      state_out : Int;
   END_VAR

   VAR 
      state : Int; 
      lp_timer : TON_TIME;
      hp_timer : TON_TIME;
      pid_feeder : "PID_Compact"; 
      pid_ctrl_val : Real;
   END_VAR

   VAR_CONSTANT 
      MIN_LP_PRESSURE : Real := 2.5; 
      MIN_HP_PRESSURE : Real := 150.0;
      MIN_LIFT_MM : Real := 0.15;
      MIN_RUN_RPM : Real := 5.0;
      MAX_LUBE_TEMP : Real := 60.0;    
      MAX_MILL_WEIGHT : Real := 500.0; 

      // Fault Codes
      F_NONE : Word := 16#0000;
      F_PROFINET_LP : Word := 16#0001;
      F_PROFINET_HP : Word := 16#0002;
      F_PROFINET_MAIN : Word := 16#0003;
      F_PROFINET_FEEDER : Word := 16#0004;
      F_LP_PRESSURE_LOW : Word := 16#0010;
      F_HP_LIFT_FAIL : Word := 16#0011;
      F_TEMP_HIGH : Word := 16#0012;
      F_WEIGHT_HIGH : Word := 16#0013;
   END_VAR

BEGIN
    // Communication Diagnostics
    IF NOT pn_vfd_lp_ok THEN fault_code := F_PROFINET_LP; state := 99; END_IF;
    IF NOT pn_vfd_hp_ok THEN fault_code := F_PROFINET_HP; state := 99; END_IF;
    IF NOT pn_vfd_main_ok THEN fault_code := F_PROFINET_MAIN; state := 99; END_IF;
    IF NOT pn_vfd_feeder_ok THEN fault_code := F_PROFINET_FEEDER; state := 99; END_IF;

    // Process Faults
    IF state > 0 AND state <> 99 THEN
        IF lp_lube_pressure_act < MIN_LP_PRESSURE THEN fault_code := F_LP_PRESSURE_LOW; state := 99; END_IF;
        IF lube_temp_act > MAX_LUBE_TEMP THEN fault_code := F_TEMP_HIGH; state := 99; END_IF;
        IF mill_weight_act > MAX_MILL_WEIGHT THEN fault_code := F_WEIGHT_HIGH; state := 99; END_IF;

        IF (state = 30 OR state = 40) AND (hp_lube_pressure_act < MIN_HP_PRESSURE OR trunnion_lift_act < MIN_LIFT_MM) AND mill_speed_act < MIN_RUN_RPM THEN
            fault_code := F_HP_LIFT_FAIL; state := 99; 
        END_IF;
    END_IF;

    IF stop_cmd THEN
        state := 0;
    END_IF;

    IF reset_cmd AND state = 99 THEN
        fault_code := F_NONE;
        state := 0;
    END_IF;

    CASE state OF
        0: // Stop
            lp_lube_pump_cmd := FALSE;
            hp_lube_pump_cmd := FALSE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := FALSE;
            IF start_cmd AND NOT stop_cmd AND fault_code = F_NONE THEN
                state := 10;
            END_IF;

        10: // LP Lube
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := FALSE;
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;

            lp_timer(IN:=(lp_lube_pressure_act >= MIN_LP_PRESSURE), PT:=T#5s);
            IF lp_timer.Q THEN state := 20; END_IF;

        20: // HP Lift
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := TRUE;

            hp_timer(IN:=(hp_lube_pressure_act >= MIN_HP_PRESSURE) AND (trunnion_lift_act >= MIN_LIFT_MM), PT:=T#3s);
            IF hp_timer.Q THEN state := 30; END_IF;

        30: // Main Motor
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := TRUE;
            mill_motor_cmd := TRUE;

            IF mill_speed_act >= MIN_RUN_RPM THEN state := 40; END_IF;

        40: // Normal Run
            lp_lube_pump_cmd := TRUE;
            hp_lube_pump_cmd := FALSE; 
            mill_motor_cmd := TRUE;

            pid_feeder(Setpoint := ore_feed_rate_sp, Feedback := mill_weight_act, Output => pid_ctrl_val);
            ore_feeder_cmd := pid_ctrl_val;

        99: // Fault
            lp_lube_pump_cmd := TRUE; 
            hp_lube_pump_cmd := TRUE; 
            mill_motor_cmd := FALSE;
            ore_feeder_cmd := 0.0;
            fault_active := TRUE;

            IF mill_speed_act < 0.1 THEN hp_lube_pump_cmd := FALSE; END_IF;
    END_CASE;

    state_out := state;
END_FUNCTION_BLOCK
