FUNCTION_BLOCK FB_MiningShovelEnergyRecovery
TITLE = 'Megawatt-scale regenerative swing braking energy recovery'
// Version 1.0 - Elite Industrial PLC Architect

VAR_INPUT
    bEnableRecovery     : BOOL;     (* Main enable for energy recovery system *)
    bEmergencyStop      : BOOL;     (* Safety relay OK signal - hard interlock *)
    rSwingMotorSpeed    : REAL;     (* Swing motor speed in RPM (negative for CCW) *)
    rDCBusVoltage       : REAL;     (* Variable voltage DC bus measurement (V) *)
    rSupercapSoc        : REAL;     (* Supercapacitor State of Charge (0.0 to 100.0%) *)
    rSupercapTemp       : REAL;     (* Supercapacitor bank temperature (deg C) *)
    rBrakingTorqueReq   : REAL;     (* Requested braking torque from operator/auto (Nm) *)
    bGridPowerOK        : BOOL;     (* Status of main trailing cable grid power *)
END_VAR

VAR_OUTPUT
    bSystemReady        : BOOL;     (* Recovery system ready status *)
    rChopperDutyCycle   : REAL;     (* Control signal to supercapacitor buck-boost chopper (0.0 to 100.0) *)
    rFrictionBrakeCmd   : REAL;     (* Command to mechanical friction brakes (0.0 to 100.0%) *)
    bOvervoltageAlarm   : BOOL;     (* DC bus overvoltage critical fault alarm *)
    bThermalAlarm       : BOOL;     (* Supercapacitor thermal warning/fault *)
    iOperatingState     : INT;      (* Current internal state for SCADA visualization *)
END_VAR

VAR
    (* Internal State Variables *)
    iState              : INT := 0;
    iNextState          : INT := 0;

    (* Timers and Filtering *)
    tFaultTimer         : TON;
    tCooldownTimer      : TON;
    rFilteredDCBus      : REAL := 0.0;

    (* Constants *)
    c_rMaxDCVoltage     : REAL := 1500.0;
    c_rNominalDCBus     : REAL := 900.0;
    c_rMaxTemp          : REAL := 65.0;
    c_rMaxSoC           : REAL := 98.0;

    (* PID Controller for Chopper (Simplified implementation) *)
    rErrorVal           : REAL;
    rIntegral           : REAL;
    rDerivative         : REAL;
    rLastError          : REAL;
    rKp                 : REAL := 0.25;
    rKi                 : REAL := 0.05;
    rKd                 : REAL := 0.01;
END_VAR

(* === MAIN LOGIC === *)
(* First pass: Safety interlocks and fundamental filtering *)
rFilteredDCBus := (rFilteredDCBus * 0.8) + (rDCBusVoltage * 0.2); // Low pass filter for sensor noise

IF NOT bEmergencyStop OR NOT bGridPowerOK THEN
    bSystemReady := FALSE;
    rChopperDutyCycle := 0.0;
    rFrictionBrakeCmd := rBrakingTorqueReq; (* Fallback to full mechanical braking *)
    iState := 99; (* Fault/Safe State *)
END_IF;

(* Thermal and Overvoltage Protection *)
IF rFilteredDCBus > c_rMaxDCVoltage THEN
    bOvervoltageAlarm := TRUE;
    iState := 99;
ELSE
    bOvervoltageAlarm := FALSE;
END_IF;

IF rSupercapTemp > c_rMaxTemp THEN
    bThermalAlarm := TRUE;
    iState := 99;
ELSE
    bThermalAlarm := FALSE;
END_IF;

(* State Machine Execution *)
CASE iState OF
    0: (* INIT *)
        bSystemReady := FALSE;
        rChopperDutyCycle := 0.0;
        rFrictionBrakeCmd := 0.0;
        rIntegral := 0.0;
        rLastError := 0.0;
        IF bEnableRecovery AND bEmergencyStop THEN
            iState := 10;
        END_IF;

    10: (* STANDBY / IDLE *)
        bSystemReady := TRUE;
        iOperatingState := 10;
        rChopperDutyCycle := 0.0;
        rFrictionBrakeCmd := 0.0;

        IF rBrakingTorqueReq > 5.0 AND ABS(rSwingMotorSpeed) > 10.0 THEN
            iState := 20; (* Transition to Regenerative Braking *)
        END_IF;

    20: (* REGENERATIVE BRAKING (BUCK-BOOST STABILIZATION) *)
        iOperatingState := 20;

        (* Verify we can accept charge *)
        IF rSupercapSoc >= c_rMaxSoC THEN
            (* Supercapacitor full, must use friction brakes or grid return *)
            rChopperDutyCycle := 0.0;
            rFrictionBrakeCmd := rBrakingTorqueReq;
        ELSE
            (* Calculate Chopper Duty Cycle to stabilize DC Bus while absorbing energy *)
            rErrorVal := rFilteredDCBus - c_rNominalDCBus;
            rIntegral := rIntegral + rErrorVal;

            (* Anti-windup *)
            IF rIntegral > 1000.0 THEN rIntegral := 1000.0; END_IF;
            IF rIntegral < -1000.0 THEN rIntegral := -1000.0; END_IF;

            rDerivative := rErrorVal - rLastError;
            rChopperDutyCycle := (rKp * rErrorVal) + (rKi * rIntegral) + (rKd * rDerivative);
            rLastError := rErrorVal;

            (* Clamp output *)
            IF rChopperDutyCycle > 100.0 THEN rChopperDutyCycle := 100.0; END_IF;
            IF rChopperDutyCycle < 0.0 THEN rChopperDutyCycle := 0.0; END_IF;

            (* Share torque with mechanical brakes if required *)
            IF rChopperDutyCycle > 95.0 AND rFilteredDCBus > (c_rNominalDCBus * 1.1) THEN
                rFrictionBrakeCmd := rBrakingTorqueReq * 0.5; (* Blend in friction *)
            ELSE
                rFrictionBrakeCmd := 0.0;
            END_IF;
        END_IF;

        IF rBrakingTorqueReq <= 1.0 OR ABS(rSwingMotorSpeed) < 2.0 THEN
            iState := 10; (* Return to standby *)
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        iOperatingState := 99;
        rChopperDutyCycle := 0.0;

        tFaultTimer(IN := TRUE, PT := T#10S);
        IF tFaultTimer.Q AND bEmergencyStop AND bGridPowerOK AND (rFilteredDCBus <= c_rNominalDCBus) AND (rSupercapTemp <= c_rMaxTemp) THEN
            tFaultTimer(IN := FALSE);
            iState := 0; (* Reset sequence *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

