FUNCTION_BLOCK FB_SSB_R2R_Sintering_Sync
VAR_INPUT
    (* Mandatory System Level Enables *)
    bSystemEnable           : BOOL;     (* Global Enable for Sintering Subsystem *)
    bEmergencyStop          : BOOL;     (* Safety Relay Health OK signal *)
    bArgonPurgeComplete     : BOOL;     (* Purge confirmation prior to run *)
    bChamberSealed          : BOOL;     (* Chamber airtight status flag *)

    (* Roll-to-Roll (R2R) Kinematic Tracking Variables *)
    rWebSpeedSetPoint       : REAL;     (* Desired Web Velocity [mm/sec] *)
    rWebSpeedActual         : REAL;     (* Encoder Feedback Velocity [mm/sec] *)
    rWebTensionActual       : REAL;     (* Load Cell Web Tension [N] *)
    rWebPosition            : LREAL;    (* Absolute Web Distance from Origin [mm] *)

    (* Photonic Sintering Zone Analog Measurements *)
    rFlashLampIntensitySet  : REAL;     (* Radiant Exposure setpoint [J/cm^2] *)
    rThermographyTempZone1  : REAL;     (* IR Pyrometer T1 [°C] *)
    rThermographyTempZone2  : REAL;     (* IR Pyrometer T2 [°C] *)
    rThermographyTempZone3  : REAL;     (* IR Pyrometer T3 [°C] *)

    (* Environmental Conditions *)
    rArgonDewPoint          : REAL;     (* Moisture level [°C] <-70°C target *)
    rArgonO2PPM             : REAL;     (* Oxygen concentration [ppm] *)
END_VAR

VAR_OUTPUT
    (* Status Flags *)
    bSystemReady            : BOOL;     (* All preconditions met, ready to process *)
    bActiveSintering        : BOOL;     (* Lamps are firing on web *)
    bAlarmSinteringFault    : BOOL;     (* Sintering subsystem fault *)
    bAlarmEnvironmental     : BOOL;     (* Environmental fault (O2 or Dew Point) *)

    (* Control Actuators Output Commands *)
    rFlashLampDriverVolts   : REAL;     (* Capacitor Bank Charging Command [VDC] *)
    rLampPulseDurationMS    : REAL;     (* FWHM Pulse Width [ms] *)
    rWebTensionDriveTorque  : REAL;     (* Unwind/Rewind torque command [%] *)

    iSinteringStateCode     : INT;      (* Current state index for HMI *)
END_VAR

VAR
    (* Internal State and Timers *)
    iSinteringState         : INT := 0; (* Internal FSM State Variable *)
    tPurgeTimer             : TON;      (* Timeout for purge sequences *)
    tLampCoolingTimer       : TON;      (* Duty cycle limits for lamps *)
    tFaultDeterrence        : TON;      (* Debounce for minor transients *)

    (* PID and Math State *)
    rTempAverage            : REAL;     (* Averaged Zone Temperature [°C] *)
    rTemperatureError       : REAL;     (* e(t) for Thermal control loop *)
    rIntegralTerm           : REAL := 0.0; (* Thermal loop integral memory *)

    (* Constants for Physics Constraints *)
    c_rDewPointLimit        : REAL := -70.0;    (* Maximum allowed Dew Point °C *)
    c_rO2LimitPPM           : REAL := 10.0;     (* Maximum allowed Oxygen ppm *)
    c_rMaxTempSinter        : REAL := 850.0;    (* Solid-State melting threshold °C *)
    c_rMinTempSinter        : REAL := 600.0;    (* Ceramic crystallization threshold °C *)
    c_rThermalKp            : REAL := 2.5;      (* Thermal control proportional gain *)
    c_rThermalKi            : REAL := 0.05;     (* Thermal control integral gain *)
END_VAR

(* === SAFETY & INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    (* Immediate Halting of all energy emission *)
    bSystemReady            := FALSE;
    bActiveSintering        := FALSE;
    rFlashLampDriverVolts   := 0.0;
    rLampPulseDurationMS    := 0.0;
    rWebTensionDriveTorque  := 0.0;
    bAlarmSinteringFault    := TRUE;
    iSinteringState         := -1; (* FAULT STATE *)
    iSinteringStateCode     := iSinteringState;
    RETURN;
END_IF;

(* Evaluate Environmental Integrity *)
IF (rArgonDewPoint > c_rDewPointLimit) OR (rArgonO2PPM > c_rO2LimitPPM) THEN
    tFaultDeterrence(IN := TRUE, PT := T#2S); (* 2 second debounce for sensor noise *)
    IF tFaultDeterrence.Q THEN
        bAlarmEnvironmental := TRUE;
        bSystemReady        := FALSE;
        bActiveSintering    := FALSE;
        iSinteringState     := -2; (* ENV FAULT *)
        iSinteringStateCode := iSinteringState;
        RETURN;
    END_IF;
ELSE
    tFaultDeterrence(IN := FALSE);
    bAlarmEnvironmental := FALSE;
END_IF;

(* Compute average sintering temperature *)
rTempAverage := (rThermographyTempZone1 + rThermographyTempZone2 + rThermographyTempZone3) / 3.0;

(* === MAIN STATE MACHINE === *)
CASE iSinteringState OF

    0: (* IDLE & PRE-CHECK *)
        bSystemReady := FALSE;
        bActiveSintering := FALSE;
        bAlarmSinteringFault := FALSE;
        rFlashLampDriverVolts := 0.0;

        IF bSystemEnable AND bChamberSealed AND bArgonPurgeComplete THEN
            iSinteringState := 10; (* PRE-CHARGE CAPACITORS *)
        END_IF;

    10: (* PRE-CHARGE CAPACITOR BANKS *)
        (* Calculate base voltage required to meet Flash Lamp Intensity Setpoint *)
        (* Non-linear empirical mapping: V = 100 * sqrt(Intensity) *)
        rFlashLampDriverVolts := 100.0 * SQRT(rFlashLampIntensitySet);
        bSystemReady := TRUE;

        (* Wait for Web Kinematics to stabilize at Setpoint before firing *)
        IF ABS(rWebSpeedActual - rWebSpeedSetPoint) < 2.5 THEN
            iSinteringState := 20; (* SINTERING ACTIVE *)
        END_IF;

        IF NOT bSystemEnable THEN
            iSinteringState := 0;
        END_IF;

    20: (* SINTERING ACTIVE *)
        bActiveSintering := TRUE;

        (* Advanced Synchronized Photonic Thermal Control (PI Loop) *)
        (* Objective: Modulate pulse duration to maintain exact average temperature *)
        rTemperatureError := c_rMaxTempSinter - rTempAverage;

        IF bActiveSintering THEN
            rIntegralTerm := rIntegralTerm + (rTemperatureError * c_rThermalKi);
        END_IF;

        (* Anti-windup limit for Integral term *)
        IF rIntegralTerm > 10.0 THEN rIntegralTerm := 10.0; END_IF;
        IF rIntegralTerm < -5.0 THEN rIntegralTerm := -5.0; END_IF;

        rLampPulseDurationMS := (rTemperatureError * c_rThermalKp) + rIntegralTerm;

        (* Boundary Clamp for Pulse Duration (0.5ms to 5.0ms) *)
        IF rLampPulseDurationMS < 0.5 THEN rLampPulseDurationMS := 0.5; END_IF;
        IF rLampPulseDurationMS > 5.0 THEN rLampPulseDurationMS := 5.0; END_IF;

        (* If Over-temperature occurs, shutdown firing immediately to save electrolyte *)
        IF rTempAverage > (c_rMaxTempSinter + 25.0) THEN
            bAlarmSinteringFault := TRUE;
            iSinteringState := -3; (* THERMAL RUNAWAY FAULT *)
        END_IF;

        IF NOT bSystemEnable THEN
            iSinteringState := 30; (* CONTROLLED SHUTDOWN *)
        END_IF;

    30: (* CONTROLLED SHUTDOWN *)
        bActiveSintering := FALSE;
        rFlashLampDriverVolts := 0.0;
        rLampPulseDurationMS := 0.0;
        rIntegralTerm := 0.0;

        tLampCoolingTimer(IN := TRUE, PT := T#15S);
        IF tLampCoolingTimer.Q THEN
            tLampCoolingTimer(IN := FALSE);
            iSinteringState := 0;
        END_IF;

    -1: (* SAFETY FAULT RECOVERY *)
        IF bEmergencyStop THEN
            iSinteringState := 0;
        END_IF;

    -2: (* ENVIRONMENTAL FAULT RECOVERY *)
        IF NOT bAlarmEnvironmental THEN
            iSinteringState := 0;
        END_IF;

    -3: (* THERMAL RUNAWAY RECOVERY *)
        bActiveSintering := FALSE;
        rFlashLampDriverVolts := 0.0;
        IF rTempAverage < (c_rMinTempSinter - 50.0) THEN
            bAlarmSinteringFault := FALSE;
            iSinteringState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
