Here is the updated CIP Skid SCL program with Profinet communication arrays and fault diagnostics.

FUNCTION_BLOCK "CIP_Skid_Breadth"
VERSION : 1.1
VAR_INPUT
    Execute : Bool;
    Cond_AI : Real;
    Flow_AI : Real;
    Temp_AI : Real;
    PN_Data_In : Array[0..15] of Byte; // Profinet inputs
END_VAR
VAR_OUTPUT
    Flow_CV : Real;
    Temp_CV : Real;
    Dosing_Pump_Run : Bool;
    PN_Data_Out : Array[0..15] of Byte; // Profinet outputs
    Fault_Code : Int;
END_VAR
VAR
    State : Int;
END_VAR

BEGIN
    // Diagnostics & Comm Watchdog
    IF NOT Execute THEN
        Fault_Code := 0;
    ELSIF Cond_AI < 0.0 OR Cond_AI > 200.0 THEN
        Fault_Code := 101; // Sensor fault
    ELSIF Flow_AI > 5000.0 THEN
        Fault_Code := 102; // Overpressure/flow
    ELSE
        Fault_Code := 0;
    END_IF;

    // Map Profinet Data
    IF PN_Data_In[0] = 16#FF THEN
        // Remote Estop
        Fault_Code := 999;
    END_IF;

    IF Fault_Code = 0 THEN
        // Phase Transition
        IF Cond_AI < 1.0 THEN State := 1;
        ELSIF Cond_AI <= 50.0 THEN State := 2;
        ELSE State := 3; END_IF;

        Flow_CV := 50.0; // Simplified for brevity
        Temp_CV := 30.0;
        Dosing_Pump_Run := (State > 1);
    ELSE
        Flow_CV := 0.0;
        Temp_CV := 0.0;
        Dosing_Pump_Run := FALSE;
        State := 99; // Fault state
    END_IF;

    // Output mapping
    PN_Data_Out[0] := INT_TO_BYTE(State);
    PN_Data_Out[1] := INT_TO_BYTE(Fault_Code);
END_FUNCTION_BLOCK
