\nFUNCTION_BLOCK FB_Biomass_CHP_Combustion
FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Biomass Cogeneration Moving Grate Combustion Control'
VERSION : '2.4'

VAR_INPUT
    rSteamDemand : REAL; (* Main steam pressure setpoint control demand (%) *)
    rFuelMoisture : REAL; (* Measured fuel moisture content (%) *)
    rFurnaceTemp_Zone1 : REAL; (* Temperature in drying zone (°C) *)
    rFurnaceTemp_Zone2 : REAL; (* Temperature in primary combustion zone (°C) *)
    rFurnaceTemp_Zone3 : REAL; (* Temperature in burnout zone (°C) *)
    rFlueGasOxygen : REAL; (* Flue gas O2 concentration (%) *)
    rPrimaryAirTemp : REAL; (* Preheated primary air temperature (°C) *)
    bEmergencyStop : BOOL;
    bPlantReady : BOOL;
END_VAR

VAR_OUTPUT
    rGrateSpeed : REAL; (* Grate forward speed (%) *)
    rPrimaryAirFlow_Zone1 : REAL; (* Air flow drying zone (kg/s) *)
    rPrimaryAirFlow_Zone2 : REAL; (* Air flow combustion zone (kg/s) *)
    rPrimaryAirFlow_Zone3 : REAL; (* Air flow burnout zone (kg/s) *)
    rSecondaryAirFlow : REAL; (* Overfire air flow (kg/s) *)
    rFuelFeederSpeed : REAL; (* Fuel feed rate (%) *)
    bIgnitionBurnerStart : BOOL;
    bAlarmHighTemp : BOOL;
    bAlarmLowOxygen : BOOL;
END_VAR

VAR
    rInternalLoadDemand : REAL := 0.0;
    rOxygenSetpoint : REAL := 4.5;
    rTotalAirDemand : REAL;
    rAirFuelRatio : REAL;
    rErrorO2 : REAL;
    rIntegralO2 : REAL := 0.0;

    (* PI Controller constants *)
    Kp_O2 : REAL := 1.2;
    Ki_O2 : REAL := 0.05;

    T_CYCLE : TIME := T#100ms;
END_VAR

(* Implementation *)
IF bEmergencyStop OR NOT bPlantReady THEN
    rGrateSpeed := 0.0;
    rFuelFeederSpeed := 0.0;
    rPrimaryAirFlow_Zone1 := 0.0;
    rPrimaryAirFlow_Zone2 := 0.0;
    rPrimaryAirFlow_Zone3 := 0.0;
    rSecondaryAirFlow := 0.0;
    bIgnitionBurnerStart := FALSE;
    RETURN;
END_IF;

(* 1. Load Demand Calculation *)
rInternalLoadDemand := rSteamDemand;

(* 2. Fuel Feed and Grate Speed *)
rFuelFeederSpeed := rInternalLoadDemand * (1.0 + (rFuelMoisture * 0.015));
rGrateSpeed := LIMIT(10.0, rInternalLoadDemand * (1.0 - (rFuelMoisture * 0.02)), 100.0);

(* 3. Air Distribution based on Zones and Moisture *)
rTotalAirDemand := rFuelFeederSpeed * 2.5;
rPrimaryAirFlow_Zone1 := rTotalAirDemand * (0.2 + (rFuelMoisture * 0.005));
rPrimaryAirFlow_Zone2 := rTotalAirDemand * 0.6;
rPrimaryAirFlow_Zone3 := rTotalAirDemand - rPrimaryAirFlow_Zone1 - rPrimaryAirFlow_Zone2;

(* 4. Oxygen Trim Control (Secondary Air) *)
rOxygenSetpoint := 6.0 - (rInternalLoadDemand * 0.02);
rOxygenSetpoint := LIMIT(3.5, rOxygenSetpoint, 7.0);

rErrorO2 := rOxygenSetpoint - rFlueGasOxygen;
rIntegralO2 := rIntegralO2 + (rErrorO2 * 0.1);
rIntegralO2 := LIMIT(-20.0, rIntegralO2, 20.0);

rSecondaryAirFlow := (rInternalLoadDemand * 1.5) + (Kp_O2 * rErrorO2) + rIntegralO2;
rSecondaryAirFlow := LIMIT(10.0, rSecondaryAirFlow, 100.0);

(* 5. Safety and Alarms *)
bAlarmHighTemp := (rFurnaceTemp_Zone2 > 1150.0);
bAlarmLowOxygen := (rFlueGasOxygen < 2.0);

IF rFurnaceTemp_Zone1 < 600.0 AND rFuelFeederSpeed > 10.0 THEN
    bIgnitionBurnerStart := TRUE;
ELSE
    bIgnitionBurnerStart := FALSE;
END_IF;

END_FUNCTION_BLOCK\n```
