FUNCTION_BLOCK FB_Scramjet_Propulsion
VAR_INPUT
    bEnable                 : BOOL;     // Enable controller
    bStart                  : BOOL;     // Initiate ignition sequence
    bAbort                  : BOOL;     // Emergency shutdown
    fMachNumber             : LREAL;    // Flight Mach number (5.0 to 7.0)
    fAltitude               : LREAL;    // Flight altitude in meters
    fDynamicPressure        : LREAL;    // Dynamic pressure in kPa
    fCombustorWallTemp      : LREAL;    // Average combustor wall temperature (K)
    fInletStagnationTemp    : LREAL;    // Freestream stagnation temperature (K)
    fFuelInletTemp          : LREAL;    // Fuel temperature before cooling jacket (K)
    fIsolatorPressureStatic : LREAL;    // Static pressure in the isolator (kPa)
    fCombustorPressure      : LREAL;    // Static pressure in combustor (kPa)

    // Limits
    fMaxWallTemp            : LREAL := 2200.0; // Max allowed wall temp (K)
    fMinFuelTemp_Injection  : LREAL := 800.0;  // Min fuel temp for stable cracking (K)
    fMaxFuelTemp_Injection  : LREAL := 1100.0; // Max fuel temp to prevent coking (K)
END_VAR

VAR_OUTPUT
    // Actuators
    fCowlFlapAngle          : LREAL;    // Angle of inlet cowl flap (degrees)
    fFuelMassFlowRate       : LREAL;    // Fuel mass flow rate (kg/s)
    fCoolingBypassValve     : LREAL;    // 0.0 to 1.0 (0% to 100% routing through jacket)

    // Status
    ePackMLState            : INT;      // Current PackML State (0=STOPPED, 1=STARTING, etc.)
    bShockUnstartWarning    : BOOL;     // True if shock train is moving forward
    fEstimatedPyrolysis     : LREAL;    // Estimated fuel cracking fraction (0.0 to 1.0)
    bSystemReady            : BOOL;     // Ready for ignition
    bThermalChokingWarning  : BOOL;     // Approaching thermal choking limit
END_VAR

VAR
    // Internal State
    eState                  : INT := 0;
    // 0: STOPPED, 1: STARTING, 2: EXECUTE, 3: STOPPING, 4: ABORTING, 5: ABORTED

    // Gas Dynamics & Thermodynamics
    fGamma                  : LREAL := 1.4; // Ratio of specific heats for air
    fGasConstant            : LREAL := 287.05; // J/(kg*K)
    fTargetShockAngle       : LREAL;
    fCurrentShockAngle      : LREAL;

    // Control loops (Simplified PID)
    fCowlKp                 : LREAL := 2.5;
    fCowlKi                 : LREAL := 0.1;
    fCowlKd                 : LREAL := 0.5;
    fCowlIntegral           : LREAL := 0.0;
    fCowlLastError          : LREAL := 0.0;

    fFuelKp                 : LREAL := 0.05;
    fFuelKi                 : LREAL := 0.001;
    fFuelKd                 : LREAL := 0.01;
    fFuelIntegral           : LREAL := 0.0;
    fFuelLastError          : LREAL := 0.0;

    // Safety & Filtering
    fPressureRatio          : LREAL;
    fUnstartMargin          : LREAL;
    fUnstartThreshold       : LREAL := 0.85; // Pressure ratio indicating imminent unstart
    fTimeDelta              : LREAL := 0.01; // 10ms cycle time assumption
    fError                  : LREAL;
    fDerivative             : LREAL;

    // Pyrolysis constants (simplified Arrhenius for Jet-A endothermic cracking)
    fActivationEnergy       : LREAL := 250000.0; // J/mol
    fUniversalGasConst      : LREAL := 8.314;    // J/(mol*K)
    fPreExponentialFactor   : LREAL := 1.5E13;   // 1/s
END_VAR

// ==============================================================================
// PackML State Machine Implementation
// ==============================================================================
IF bAbort THEN
    eState := 4; // ABORTING
END_IF

CASE eState OF

    0: // STOPPED
        fCowlFlapAngle := 0.0;
        fFuelMassFlowRate := 0.0;
        fCoolingBypassValve := 1.0; // Bypass completely
        bShockUnstartWarning := FALSE;
        bThermalChokingWarning := FALSE;
        bSystemReady := FALSE;

        IF bEnable THEN
            eState := 1; // STARTING
        END_IF

    1: // STARTING
        // Reset Integrals
        fCowlIntegral := 0.0;
        fCowlLastError := 0.0;
        fFuelIntegral := 0.0;
        fFuelLastError := 0.0;

        bSystemReady := TRUE;

        IF bStart AND fMachNumber >= 4.5 THEN
            eState := 2; // EXECUTE
        ELSIF NOT bEnable THEN
            eState := 3; // STOPPING
        END_IF

    2: // EXECUTE

        // ---------------------------------------------------------
        // 1. Oblique Shockwave & Isolator Positioning
        // ---------------------------------------------------------
        // Empirical target shock angle calculation based on geometry (simplified for Mach 5-7)
        // Approximation for beta based on Mach
        IF fMachNumber > 1.0 THEN
            // Approximation for Oblique shock beta
            fTargetShockAngle := 15.0 + 35.0 / fMachNumber;
        ELSE
            fTargetShockAngle := 90.0;
        END_IF

        // Simulated current shock position error
        fCurrentShockAngle := (fMachNumber * 2.0) + fCowlFlapAngle;

        // PID for Cowl Flap Angle (Position Oblique Shock)
        fError := fTargetShockAngle - fCurrentShockAngle;
        fCowlIntegral := fCowlIntegral + (fError * fTimeDelta);
        fDerivative := (fError - fCowlLastError) / fTimeDelta;
        fCowlLastError := fError;

        fCowlFlapAngle := (fCowlKp * fError) + (fCowlKi * fCowlIntegral) + (fCowlKd * fDerivative);

        // Anti-windup and limits
        IF fCowlFlapAngle > 15.0 THEN fCowlFlapAngle := 15.0; END_IF;
        IF fCowlFlapAngle < -15.0 THEN fCowlFlapAngle := -15.0; END_IF;

        // ---------------------------------------------------------
        // 2. Unstart Prevention (Isolator Back-Pressure Monitoring)
        // ---------------------------------------------------------
        IF fIsolatorPressureStatic > 1.0 THEN
            fPressureRatio := fCombustorPressure / fIsolatorPressureStatic;
        ELSE
            fPressureRatio := 1.0;
        END_IF

        fUnstartMargin := 1.0 - (fPressureRatio / 5.0); // 5.0 assumed normal ratio

        IF fUnstartMargin < fUnstartThreshold THEN
            bShockUnstartWarning := TRUE;
            // Immediate mitigation: spill air by opening cowl slightly, reduce fuel
            fCowlFlapAngle := fCowlFlapAngle - 2.0; 
            fFuelMassFlowRate := fFuelMassFlowRate * 0.9;
        ELSE
            bShockUnstartWarning := FALSE;
        END_IF

        // ---------------------------------------------------------
        // 3. Endothermic Hydrocarbon Fuel Active Cooling
        // ---------------------------------------------------------
        // PID for Cooling Bypass (Regulate Combustor Wall Temperature)
        fError := (fMaxWallTemp * 0.85) - fCombustorWallTemp;
        fFuelIntegral := fFuelIntegral + (fError * fTimeDelta);
        fDerivative := (fError - fFuelLastError) / fTimeDelta;
        fFuelLastError := fError;

        fCoolingBypassValve := (fFuelKp * fError) + (fFuelKi * fFuelIntegral) + (fFuelKd * fDerivative);

        // Invert and Limit (0.0 to 1.0)
        fCoolingBypassValve := 1.0 - fCoolingBypassValve;
        IF fCoolingBypassValve > 1.0 THEN fCoolingBypassValve := 1.0; END_IF;
        IF fCoolingBypassValve < 0.0 THEN fCoolingBypassValve := 0.0; END_IF;

        // Base fuel schedule on dynamic pressure and Mach
        fFuelMassFlowRate := (fDynamicPressure * fMachNumber) * 0.002;

        // ---------------------------------------------------------
        // 4. Pyrolysis & Cracking Estimation
        // ---------------------------------------------------------
        // Estimate reaction rate k = A * exp(-Ea / (R * T))
        IF fCombustorWallTemp > 600.0 THEN
            // EXP function used for Arrhenius equation
            fEstimatedPyrolysis := fPreExponentialFactor * 
                                   EXP(-fActivationEnergy / (fUniversalGasConst * fCombustorWallTemp)) * 
                                   fTimeDelta;
            IF fEstimatedPyrolysis > 1.0 THEN fEstimatedPyrolysis := 1.0; END_IF;
        ELSE
            fEstimatedPyrolysis := 0.0;
        END_IF

        // Injection temp logic
        fFuelInletTemp := fFuelInletTemp + (fCombustorWallTemp - fFuelInletTemp) * (1.0 - fCoolingBypassValve) * 0.5;

        IF fFuelInletTemp > fMaxFuelTemp_Injection THEN
            // Danger of coking, increase fuel flow to act as larger heat sink
            fFuelMassFlowRate := fFuelMassFlowRate * 1.1; 
        END_IF

        IF NOT bEnable THEN
            eState := 3; // STOPPING
        END_IF

    3: // STOPPING
        fFuelMassFlowRate := fFuelMassFlowRate * 0.95; // Ramp down
        IF fFuelMassFlowRate < 0.01 THEN
            eState := 0; // STOPPED
        END_IF

    4: // ABORTING
        fFuelMassFlowRate := 0.0; // Cut fuel immediately
        fCoolingBypassValve := 1.0; // Bypass
        fCowlFlapAngle := 0.0; // Neutral
        eState := 5; // ABORTED

    5: // ABORTED
        IF NOT bAbort THEN
            eState := 0; // STOPPED
        END_IF

END_CASE

ePackMLState := eState;
END_FUNCTION_BLOCK
```

