    rLaserPowerCmd_kW           : REAL;     (* Commanded laser power out to IPG source *)
    bLaserEmissionActive        : BOOL;     (* Laser emission status feedback *)
    rAssistGasValveCmd_pct      : REAL;     (* Proportional valve command for Argon gas 0-100% *)
    bWeldDepthOK                : BOOL;     (* In-process quality tracking: weld depth meets tolerance *)
    bFaultActive                : BOOL;     (* Any active fault in the welding cell *)
    iFaultCode                  : INT;      (* Detailed fault code for diagnostics *)
END_VAR
VAR
    (* Internal State Machine *)
    iSeqState                   : INT := 0; 

    (* Internal timers and triggers *)
    tGasPreFlow                 : TON;
    tLaserPulseWidth            : TON;
    tSettleDelay                : TON;

    (* Internal processing variables *)
    rActualDepthDev             : REAL;
    rVibrationFiltered          : REAL := 0.0;
    bPlumeInterference          : BOOL := FALSE;
    iRetryCount                 : INT := 0;

    (* Filter Constants for Vibration Suppression *)
    rAlpha                      : REAL := 0.15; (* Low pass filter coefficient for vibration *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Hard Stops *)
IF NOT bEmergencyStop THEN
    bSystemReady         := FALSE;
    bLaserEmissionActive := FALSE;
    rLaserPowerCmd_kW    := 0.0;
    rAssistGasValveCmd_pct := 0.0;
    bFaultActive         := TRUE;
    iFaultCode           := 9999; (* Critical E-STOP Fault *)
    iSeqState            := 0;
    RETURN;
END_IF;

(* 2. Real-time Process Calculations: Vibration Filtering (Low-Pass IIR) *)
rVibrationFiltered := (rAlpha * rGantryVibrationLimit_mm_s) + ((1.0 - rAlpha) * rVibrationFiltered);
IF rVibrationFiltered > 15.0 THEN 
    bFaultActive := TRUE;
    iFaultCode   := 1001; (* Gantry vibration exceeded absolute max threshold *)
    iSeqState    := 900;  (* Abort sequence *)
END_IF;

(* 3. Weld Cell Sequence State Machine *)
CASE iSeqState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rLaserPowerCmd_kW := 0.0;
        bLaserEmissionActive := FALSE;
        rAssistGasValveCmd_pct := 0.0;
        bFaultActive := FALSE;
        iFaultCode := 0;
        bWeldDepthOK := FALSE;

        IF bEnableSys AND NOT bFaultActive THEN
            iSeqState := 10;
        END_IF;

    10: (* PRE-FLOW ASSIST GAS (Supersonic Argon mapped to pressure gradient) *)
        rAssistGasValveCmd_pct := rAssistGasFlow_Lmin * 1.85; (* Simple mapping formula *)
        IF rAssistGasValveCmd_pct > 100.0 THEN
            rAssistGasValveCmd_pct := 100.0;
        END_IF;

        tGasPreFlow(IN := TRUE, PT := T#500MS);
        IF tGasPreFlow.Q THEN
            tGasPreFlow(IN := FALSE);
            bSystemReady := TRUE;
            iSeqState := 20;
        END_IF;

    20: (* ARM LASER & AWAIT WELD COMMAND *)
        IF rLaserPowerSetpoint_kW > 0.1 THEN
            iSeqState := 30;
        END_IF;

    30: (* WELDING IN PROGRESS WITH OCT FEEDBACK CONTROL *)
        rLaserPowerCmd_kW := rLaserPowerSetpoint_kW;
        bLaserEmissionActive := TRUE;

        (* Simulated closed loop PI control step on depth *)
        rActualDepthDev := rOCTWeldDepthTarget_mm - 1.25; (* Simulated process value *)
        IF ABS(rActualDepthDev) <= 0.15 THEN
            bWeldDepthOK := TRUE;
        ELSE
            bWeldDepthOK := FALSE;
            (* Modulate power to correct penetration *)
            rLaserPowerCmd_kW := rLaserPowerCmd_kW + (rActualDepthDev * 0.5); 
        END_IF;

        (* Clamp Output *)
        IF rLaserPowerCmd_kW > 8.0 THEN rLaserPowerCmd_kW := 8.0; END_IF;
        IF rLaserPowerCmd_kW < 0.0 THEN rLaserPowerCmd_kW := 0.0; END_IF;

        tLaserPulseWidth(IN := TRUE, PT := T#2S);
        IF tLaserPulseWidth.Q THEN
            tLaserPulseWidth(IN := FALSE);
            bLaserEmissionActive := FALSE;
            rLaserPowerCmd_kW := 0.0;
            iSeqState := 40;
        END_IF;

    40: (* POST-FLOW & Settle *)
        tSettleDelay(IN := TRUE, PT := T#300MS);
        IF tSettleDelay.Q THEN
             tSettleDelay(IN := FALSE);
             rAssistGasValveCmd_pct := 0.0;
             iSeqState := 0; (* Reset to Idle *)
        END_IF;

    900: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rLaserPowerCmd_kW := 0.0;
        bLaserEmissionActive := FALSE;
        rAssistGasValveCmd_pct := 0.0;

        IF NOT bEnableSys THEN
            bFaultActive := FALSE;
            iFaultCode := 0;
            iSeqState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
