FUNCTION_BLOCK FB_Cyclotron_Breadth
TITLE = 'Cyclotron with Profinet & Diagnostics'
VERSION : '1.2'

VAR_INPUT
    // Profinet Inputs from SCADA
    PN_ControlWord : WORD;
    PN_Setpoints : ARRAY[0..3] OF REAL;

    // Sensor Inputs
    Sens_Vacuum : REAL;
    Sens_MagnetTemp : REAL;
    Sens_RFFreqActual : REAL;
    Sens_RFCavityVolt : REAL;
END_VAR

VAR_OUTPUT
    // Profinet Outputs to SCADA
    PN_StatusWord : WORD;
    PN_ErrorCode : DWORD;
    PN_Actuals : ARRAY[0..3] OF REAL;

    // Actuator Commands
    Cmd_BeamActive : BOOL;
    Cmd_MagnetCurrent : REAL;
    Cmd_RFFreqSetpt : REAL;
    Cmd_RFPwrEnable : BOOL;
END_VAR

VAR
    Req_BeamOn : BOOL;
    Stat_Current : REAL := 0.0;
    Fault_Code : DWORD := 16#00000000;
END_VAR

CONST
    LIMIT_VACUUM : REAL := 1.0E-6;
    LIMIT_TEMP : REAL := 45.0;
    ERR_VACUUM : DWORD := 16#00000001;
    ERR_TEMP   : DWORD := 16#00000002;
    ERR_RF     : DWORD := 16#00000004;
END_CONST

BEGIN
    // Unpack Profinet Control Word
    Req_BeamOn := (PN_ControlWord AND 16#0001) <> 0;

    // Diagnostics & Interlocks
    Fault_Code := 16#00000000;
    IF Sens_Vacuum > LIMIT_VACUUM THEN Fault_Code := Fault_Code OR ERR_VACUUM; END_IF;
    IF Sens_MagnetTemp > LIMIT_TEMP THEN Fault_Code := Fault_Code OR ERR_TEMP; END_IF;

    PN_ErrorCode := Fault_Code;

    IF Fault_Code <> 0 THEN
        Cmd_BeamActive := FALSE;
        Cmd_RFPwrEnable := FALSE;
        Stat_Current := 0.0;
        PN_StatusWord := 16#0002; // Fault Status
    ELSE
        PN_StatusWord := 16#0001; // Healthy

        IF Req_BeamOn THEN
            IF Stat_Current < PN_Setpoints[0] THEN
                Stat_Current := Stat_Current + 0.5;
            ELSE
                Cmd_RFPwrEnable := TRUE;
                Cmd_RFFreqSetpt := PN_Setpoints[1];
                IF Sens_RFCavityVolt >= PN_Setpoints[2] THEN
                    Cmd_BeamActive := TRUE;
                    PN_StatusWord := 16#0005; // Healthy + Beam Active
                ELSE
                    PN_ErrorCode := PN_ErrorCode OR ERR_RF;
                END_IF;
            END_IF;
        ELSE
            Cmd_BeamActive := FALSE;
            Cmd_RFPwrEnable := FALSE;
            Stat_Current := 0.0;
        END_IF;
    END_IF;

    Cmd_MagnetCurrent := Stat_Current;

    // Pack Profinet Actuals
    PN_Actuals[0] := Stat_Current;
    PN_Actuals[1] := Sens_Vacuum;
    PN_Actuals[2] := Sens_MagnetTemp;
    PN_Actuals[3] := Sens_RFCavityVolt;
END_FUNCTION_BLOCK
