   // IEC 62443 Role-Based Access Control
   #q_SecurityAlert := FALSE;
   IF #i_ApplySetpoints THEN
      IF #i_UserRole >= 2 THEN
         #stat_ActiveSetpoints_Conc := #i_NewConcSetpoint;
         #stat_ActiveSetpoints_Steam := #i_NewSteamSetpoint;
      ELSE
         #q_SecurityAlert := TRUE;
      END_IF;
   END_IF;

   // Failover Logic
   IF #stat_ActiveEjector = 1 AND #i_Ejector1_Fault AND NOT #i_Ejector2_Fault THEN
      #stat_ActiveEjector := 2;
   ELSIF #stat_ActiveEjector = 2 AND #i_Ejector2_Fault AND NOT #i_Ejector1_Fault THEN
      #stat_ActiveEjector := 1;
   END_IF;

   // Start/Stop Logic
   IF #i_StartCmd AND NOT #i_StopCmd AND NOT #q_ScadaCommFault THEN
      #stat_Running := TRUE;
   ELSIF #i_StopCmd OR #q_ScadaCommFault THEN
      #stat_Running := FALSE;
   END_IF;

   #q_Running := #stat_Running;

   // Process Control
   IF #stat_Running THEN
      IF #i_BrineConc > #stat_ActiveSetpoints_Conc THEN
         #q_BlowdownValve := TRUE;
      ELSIF #i_BrineConc < (#stat_ActiveSetpoints_Conc * 0.9) THEN
