FUNCTION_BLOCK FB_5Axis_Gantry_AdaptiveControl
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety circuit OK / E-Stop active low *)
    rSpindleVibration       : REAL;     (* Measured spindle vibration in mm/s RMS *)
    rToolTemp               : REAL;     (* Tool tip temperature in deg C from IR sensor *)
    rAxisPositionX          : REAL;     (* X-axis absolute position (mm) *)
    rAxisPositionY          : REAL;     (* Y-axis absolute position (mm) *)
    rAxisPositionZ          : REAL;     (* Z-axis absolute position (mm) *)
    rAxisPositionA          : REAL;     (* A-axis rotary position (deg) *)
    rAxisPositionC          : REAL;     (* C-axis rotary position (deg) *)
    rProgrammedFeedrate     : REAL;     (* Base feedrate from G-code (mm/min) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Control algorithm active and healthy *)
    rAdaptiveFeedrate       : REAL;     (* Real-time overridden feedrate to CNC (mm/min) *)
    rThermalCompZ           : REAL;     (* Z-axis dynamic thermal compensation offset (mm) *)
    bChatterAlarm           : BOOL;     (* Severe chatter detected, critical stop *)
    rVolumetricErrorComp    : ARRAY[1..3] OF REAL; (* TCP XYZ dynamic compensation vector *)
END_VAR
VAR
    iState                  : INT := 0; (* State machine index *)
    tSamplingTimer          : TON;      (* Control loop execution timer *)
    rBaseVibrationLimit     : REAL := 15.0; (* Chatter threshold mm/s RMS *)
    rThermalExpansionCoef   : REAL := 0.000012; (* Thermal expansion mm/mm/degC *)
    rBaseTemp               : REAL := 20.0;     (* Base calibration temp degC *)
    rSpindleLength          : REAL := 350.0;    (* Spindle characteristic length mm *)

    (* Kinematic matrix parameters *)
    rToolLength             : REAL := 120.5;

    (* Internal filters *)
    rFilteredVibration      : REAL := 0.0;
    rVibrationAlpha         : REAL := 0.15; (* Low pass filter coefficient *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bChatterAlarm := TRUE;
    rAdaptiveFeedrate := 0.0;
    rThermalCompZ := 0.0;
    iState := 0;
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE AND INITIALIZATION *)
        IF bEnable THEN
            bSystemReady := TRUE;
            bChatterAlarm := FALSE;
            rFilteredVibration := 0.0;
            iState := 10;
        END_IF;

    10: (* ACTIVE ADAPTIVE CONTROL LOOP *)
        (* Execute loop at 10ms intervals *)
        tSamplingTimer(IN := TRUE, PT := T#10MS);

        IF tSamplingTimer.Q THEN
            tSamplingTimer(IN := FALSE);

            (* 1. First-order low-pass filter for spindle vibration *)
            rFilteredVibration := (rVibrationAlpha * rSpindleVibration) + ((1.0 - rVibrationAlpha) * rFilteredVibration);

            (* 2. Chatter Detection & Adaptive Feedrate Override *)
            IF rFilteredVibration > rBaseVibrationLimit THEN
                bChatterAlarm := TRUE;
                rAdaptiveFeedrate := 0.0; (* Halt feed due to extreme chatter *)
                iState := 99; (* Transition to fault state *)
            ELSIF rFilteredVibration > (rBaseVibrationLimit * 0.7) THEN
                (* Aggressive feedrate reduction (chatter avoidance) *)
                rAdaptiveFeedrate := rProgrammedFeedrate * 0.4;
            ELSIF rFilteredVibration > (rBaseVibrationLimit * 0.4) THEN
                (* Mild feedrate reduction *)
                rAdaptiveFeedrate := rProgrammedFeedrate * 0.8;
            ELSE
                (* Normal operation, optimal feed *)
                rAdaptiveFeedrate := rProgrammedFeedrate;
            END_IF;

            (* 3. Z-Axis Thermal Volumetric Compensation *)
            (* Calculates expansion based on spindle nose heating *)
            rThermalCompZ := (rToolTemp - rBaseTemp) * rThermalExpansionCoef * (rSpindleLength + rToolLength);

            (* 4. 5-Axis TCP (Tool Center Point) Kinematic Compensation *)
            (* Simplified projection matrix for A and C rotary axes coupling *)
            rVolumetricErrorComp[1] := rAxisPositionX * 0.000005 * rAxisPositionA; (* X-error due to A-axis sag *)
            rVolumetricErrorComp[2] := rAxisPositionY * 0.000005 * rAxisPositionC; (* Y-error due to C-axis eccentricity *)
            rVolumetricErrorComp[3] := rThermalCompZ + (rAxisPositionZ * 0.00001); (* Z-error combined thermal & structural *)

        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT STATE *)
        bSystemReady := FALSE;
        rAdaptiveFeedrate := 0.0;
        IF NOT bEnable THEN (* Require manual reset by disabling *)
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
