      SlipRatio : Real;
      ThermalDeratingFactor : Real;
   END_VAR
   CONST
      MAX_ALLOWABLE_SLIP := 0.15;
      MAX_TORQUE := 10000.0;
      TEMP_WARN := 150.0;
      TEMP_CRIT := 200.0;
   END_CONST
BEGIN
