FUNCTION_BLOCK "FB_HighSpeedRoboticPedestal"
TITLE = 'High-Speed Robotic Camera Pedestal for Live Sports'
VERSION : '3.0'
AUTHOR : 'Lumina Broadcast Systems'

(* 
    Advanced 3-Axis Camera Pedestal Controller 
    - Pan/Tilt/Zoom Inverse Kinematic Tracking
    - Gyroscopic Stabilization for stadium vibrations
    - Fiber-optic slip ring telemetry and diagnostics
*)

VAR_INPUT
    // Targeting System (Coordinates from Athlete Tracking System)
    xEnable : BOOL;                     // Enable tracking
    rTargetX : REAL;                    // Target X coordinate (m)
    rTargetY : REAL;                    // Target Y coordinate (m)
    rTargetZ : REAL;                    // Target Z coordinate (m)
    rCameraPosX : REAL;                 // Current Pedestal X Position (m)
    rCameraPosY : REAL;                 // Current Pedestal Y Position (m)
    rCameraPosZ : REAL;                 // Current Pedestal Z Position (m)

    // Gyroscopic Feedback (Stadium Vibration)
    rGyroRoll : REAL;                   // Pitch vibration rate (deg/s)
    rGyroPitch : REAL;                  // Roll vibration rate (deg/s)
    rGyroYaw : REAL;                    // Yaw vibration rate (deg/s)

    // Fiber-optic Slip Ring Telemetry
    wSlipRingStatusWord : WORD;         // Diagnostics from slip ring controller
    rFiberOpticSignalDb : REAL;         // Signal strength (dBm)
    xTelemetryCommsOk : BOOL;           // Heartbeat from telemetry module

    // Settings
    rMaxPanSpeed : REAL := 120.0;       // Max Pan Speed (deg/s)
    rMaxTiltSpeed : REAL := 90.0;       // Max Tilt Speed (deg/s)
    rMaxZoomAccel : REAL := 50.0;       // Max Zoom Acceleration (mm/s^2)
    rSmoothingFactor : REAL := 0.85;    // PID smoothing coefficient
END_VAR

VAR_OUTPUT
    // Motor Drive References
    rRefPanSpeed : REAL;                // Drive reference pan speed (deg/s)
    rRefTiltSpeed : REAL;               // Drive reference tilt speed (deg/s)
    rRefZoomPos : REAL;                 // Drive reference zoom position (mm)

    // System Status
    xReady : BOOL;
    xTrackingActive : BOOL;
    xTrackingError : BOOL;

    // Diagnostics
    xWarningSlipRing : BOOL;
    xFaultTelemetryLost : BOOL;
    xFaultFiberSignalLow : BOOL;
    sDiagnosticMessage : STRING[50];
END_VAR

VAR
    // Internal States
    rDeltaX : REAL;
    rDeltaY : REAL;
    rDeltaZ : REAL;
    rDistance : REAL;

    // Calculated IK Targets
    rTargetPanDeg : REAL;
    rTargetTiltDeg : REAL;
    rTargetZoom : REAL;

    // Actual Feedback (from encoders, assumed read externally)
    rActPanDeg : REAL;
    rActTiltDeg : REAL;

    // Control Variables (PID / Smoothing)
    rPanError : REAL;
    rTiltError : REAL;
    rPanIntegral : REAL;
    rTiltIntegral : REAL;

    // Stabilization Filters
    rStabPanOffset : REAL;
    rStabTiltOffset : REAL;

    // Timers
    fbTelemetryTimeout : TON;
    rLastExecTime : LREAL;
    rDeltaT : REAL := 0.01; // Assuming 10ms cycle
END_VAR

CONST
    C_FIBER_WARNING_LIMIT : REAL := -20.0; // dBm threshold
    C_RAD_TO_DEG : REAL := 57.2957795;
END_CONST

BEGIN
    // ==========================================
    // 1. Fiber-Optic Slip Ring & Telemetry Diagnostics
    // ==========================================
    fbTelemetryTimeout(IN := NOT xTelemetryCommsOk, PT := T#500ms);
    xFaultTelemetryLost := fbTelemetryTimeout.Q;

    xFaultFiberSignalLow := (rFiberOpticSignalDb < C_FIBER_WARNING_LIMIT);
    xWarningSlipRing := (wSlipRingStatusWord <> 16#0000); // Any non-zero status indicates warning

    IF xFaultTelemetryLost THEN
        sDiagnosticMessage := 'FAULT: Telemetry Comms Lost';
        xReady := FALSE;
    ELSIF xFaultFiberSignalLow THEN
        sDiagnosticMessage := 'FAULT: Fiber Signal Critical';
        xReady := FALSE;
    ELSIF xWarningSlipRing THEN
        sDiagnosticMessage := 'WARN: Slip Ring Diagnostic Code';
        xReady := TRUE;
    ELSE
        sDiagnosticMessage := 'System OK';
        xReady := TRUE;
    END_IF;

    // Halt tracking if system not ready
    IF NOT xReady OR NOT xEnable THEN
        rRefPanSpeed := 0.0;
        rRefTiltSpeed := 0.0;
        xTrackingActive := FALSE;
        RETURN;
    END_IF;

    xTrackingActive := TRUE;

    // ==========================================
    // 2. Inverse Kinematics (Athlete Targeting)
    // ==========================================
    // Calculate relative deltas
    rDeltaX := rTargetX - rCameraPosX;
    rDeltaY := rTargetY - rCameraPosY;
    rDeltaZ := rTargetZ - rCameraPosZ;

    // 3D Distance for Zoom scaling
    rDistance := SQRT((rDeltaX * rDeltaX) + (rDeltaY * rDeltaY) + (rDeltaZ * rDeltaZ));

    // Calculate Target Pan (Yaw) via ATAN2 (in radians, convert to degrees)
    // Avoid division by zero
    IF rDeltaX <> 0.0 OR rDeltaY <> 0.0 THEN
        rTargetPanDeg := ATAN2(Y := rDeltaY, X := rDeltaX) * C_RAD_TO_DEG;
    ELSE
        rTargetPanDeg := rActPanDeg; // Hold position
    END_IF;

    // Calculate Target Tilt (Pitch)
    // Planar distance (hypotenuse in XY plane)
    rTargetTiltDeg := ATAN2(Y := rDeltaZ, X := SQRT((rDeltaX * rDeltaX) + (rDeltaY * rDeltaY))) * C_RAD_TO_DEG;

    // Dynamic Zoom calculation based on distance to keep athlete framed
    // Simplified model: base focus point = 10m -> zoom = 50mm, scales linearly
    rTargetZoom := 50.0 + (rDistance * 2.5);

    // ==========================================
    // 3. Gyroscopic Stabilization (Anti-Vibration)
    // ==========================================
    // Stadium vibrations (e.g., bass frequencies, crowd jumping) induce micromovements
    // Active cancellation offsets the target angle by the integrated gyro rates
    // Assuming rGyroYaw and rGyroPitch are rates (deg/s), multiply by cycle time to get angle delta to compensate

    rStabPanOffset := -rGyroYaw * rDeltaT; 
    rStabTiltOffset := -rGyroPitch * rDeltaT;

    // Apply stabilization offsets
    rTargetPanDeg := rTargetPanDeg + rStabPanOffset;
    rTargetTiltDeg := rTargetTiltDeg + rStabTiltOffset;

    // ==========================================
    // 4. Smooth Tracking & Motion Control (PID)
    // ==========================================
    // Calculate Error
    rPanError := rTargetPanDeg - rActPanDeg;
    rTiltError := rTargetTiltDeg - rActTiltDeg;

    // Simplified Proportional-Integral with Smoothing
    // For smooth broadcast tracking, aggressive D-term is avoided to prevent judder
    rPanIntegral := rPanIntegral + (rPanError * rDeltaT);
    rTiltIntegral := rTiltIntegral + (rTiltError * rDeltaT);

    // Anti-windup
    rPanIntegral := LIMIT(MN := -20.0, IN := rPanIntegral, MX := 20.0);
    rTiltIntegral := LIMIT(MN := -20.0, IN := rTiltIntegral, MX := 20.0);

    // Calculate Raw Speed References
    // (Kp = 2.5, Ki = 0.5)
    rRefPanSpeed := (rPanError * 2.5) + (rPanIntegral * 0.5);
    rRefTiltSpeed := (rTiltError * 2.5) + (rTiltIntegral * 0.5);

    // Apply Velocity Limits
    rRefPanSpeed := LIMIT(MN := -rMaxPanSpeed, IN := rRefPanSpeed, MX := rMaxPanSpeed);
    rRefTiltSpeed := LIMIT(MN := -rMaxTiltSpeed, IN := rRefTiltSpeed, MX := rMaxTiltSpeed);

    // Apply Low-Pass Smoothing Filter to speed output
    // Previous Speed Reference is assumed retained on next cycle due to static nature of outputs in FB
    // Y_n = (Y_n-1 * smoothing) + (X_n * (1 - smoothing))
    rRefPanSpeed := (rRefPanSpeed * rSmoothingFactor) + (rRefPanSpeed * (1.0 - rSmoothingFactor));
    rRefTiltSpeed := (rRefTiltSpeed * rSmoothingFactor) + (rRefTiltSpeed * (1.0 - rSmoothingFactor));

    // Zoom Position output directly applied with limit
    rRefZoomPos := LIMIT(MN := 10.0, IN := rTargetZoom, MX := 500.0); // Assuming 10mm to 500mm lens

    // Mock actual position integration for the FB
    rActPanDeg := rActPanDeg + (rRefPanSpeed * rDeltaT);
    rActTiltDeg := rActTiltDeg + (rRefTiltSpeed * rDeltaT);

END_FUNCTION_BLOCK
