END_IF;
CASE nCurrentStep OF
    0: 
        bHeaterTank1_ON := FALSE;
        bHeaterTank2_ON := FALSE;
        bUltrasonicSweepActive := FALSE;
        bOilSkimmerPump_ON := FALSE;
        bVacuumPump_ON := FALSE;
        bVentValve_OPEN := FALSE;
        bAlarm := FALSE;
        IF bStartCycle AND bPartPresent THEN
            nCurrentStep := 10;
        END_IF;
    10:
        bHeaterTank1_ON := (rTank1Temp_C < rTargetWashTemp);
        bHeaterTank2_ON := (rTank2Temp_C < rTargetRinseTemp);
        bHeatingComplete := NOT bHeaterTank1_ON AND NOT bHeaterTank2_ON;
        IF bHeatingComplete THEN
            nCurrentStep := 20;
            tCycleTimer(IN := FALSE);
        END_IF;
    20:
        bHeaterTank1_ON := (rTank1Temp_C < rTargetWashTemp - 2.0);
        bUltrasonicSweepActive := TRUE;
        tCycleTimer(IN := TRUE, PT := T#5M);
        tSweepTimer(IN := TRUE, PT := T#10S);
        IF tSweepTimer.Q THEN
            nSweepIndex := (nSweepIndex + 1) MOD 4;
            tSweepTimer(IN := FALSE);
        END_IF;
        nUltrasonicFrequency_kHz := arrSweepFreqs[nSweepIndex];
        IF tCycleTimer.Q THEN
            bUltrasonicSweepActive := FALSE;
            nCurrentStep := 30;
            tCycleTimer(IN := FALSE);
        END_IF;
    30:
        bOilSkimmerPump_ON := TRUE;
        tCycleTimer(IN := TRUE, PT := T#2M);
        IF tCycleTimer.Q OR (rOilLevel_pct < 5.0) THEN
            bOilSkimmerPump_ON := FALSE;
            nCurrentStep := 40;
            tCycleTimer(IN := FALSE);
        END_IF;
    40:
        bHeaterTank2_ON := (rTank2Temp_C < rTargetRinseTemp - 2.0);
        tCycleTimer(IN := TRUE, PT := T#3M);
        IF tCycleTimer.Q THEN
            nCurrentStep := 50;
            tCycleTimer(IN := FALSE);
        END_IF;
    50:
        bVacuumPump_ON := TRUE;
        bVentValve_OPEN := FALSE;
        bVacuumReached := (rChamberPressure_mbar <= rTargetVacuumPressure);
        IF bVacuumReached THEN
            tCycleTimer(IN := TRUE, PT := T#3M);
            IF tCycleTimer.Q THEN
                bVacuumPump_ON := FALSE;
                bVentValve_OPEN := TRUE;
                nCurrentStep := 60;
                tCycleTimer(IN := FALSE);
            END_IF;
        ELSE
            tCycleTimer(IN := FALSE);
        END_IF;
    60:
        bVentValve_OPEN := TRUE;
        IF rChamberPressure_mbar >= 980.0 THEN
            bVentValve_OPEN := FALSE;
            nCurrentStep := 100;
        END_IF;
    100:
        IF NOT bStartCycle THEN
            nCurrentStep := 0;
        END_IF;
    ELSE
        bAlarm := TRUE;
        nCurrentStep := -1;
END_CASE;
