```iec-st
FUNCTION_BLOCK FB_GlassTemperingFurnaceControl
VAR_INPUT
    bEnable : BOOL; // Enable control
    rGlassThickness_mm : REAL; // Thickness of the glass
    rFurnaceSetpoint_C : REAL; // Target furnace temp
    rCurrentFurnaceTemp_C : REAL; // Measured furnace temp
    rConvectionPressure_Pa : REAL; // Measured convection pressure
    rQuenchBlowerSpeed_RPM : REAL; // Current blower speed
    bGlassInHeatingZone : BOOL; // Sensor input
    bGlassInQuenchZone : BOOL; // Sensor input
    rOscillationSpeed_m_s : REAL; // Current oscillation speed
END_VAR
VAR_OUTPUT
    rHeatingElementsPower_pct : REAL; // 0-100% heating element power
    rConvectionFanSpeed_pct : REAL; // 0-100% convection fan speed
    rQuenchBlowerSetpoint_RPM : REAL; // Blower speed target
    rRollerDriveSpeed_m_s : REAL; // Target roller speed
    bHeaterActive : BOOL; // Heating status
    bQuenchActive : BOOL; // Quenching status
    iFaultCode : INT; // Diagnostics
END_VAR
VAR
    // Internal States
    rPID_Integral : REAL := 0.0;
    rPID_PrevError : REAL := 0.0;
    rPID_Kp : REAL := 2.5;
    rPID_Ki : REAL := 0.1;
    rPID_Kd : REAL := 0.5;

    // Quench Profile
    rTargetQuenchPressure : REAL;
    rBlowerPID_Integral : REAL := 0.0;
    rBlowerPID_PrevError : REAL := 0.0;
    rBlowerPID_Kp : REAL := 1.2;
    rBlowerPID_Ki : REAL := 0.05;
    rBlowerPID_Kd : REAL := 0.1;

    // Kinematics
    rOscillationAmplitude : REAL := 0.15; // meters
    rOscillationFrequency : REAL := 0.5; // Hz
    tTimeInZone : TIME;
    fbTimer : TON;
    rTimeSeconds : REAL;

    // Thermal Stress fragmentation
    rStressFactor : REAL;

    // Temp Vars
    rErrorTemp : REAL;
    rDerivativeTemp : REAL;
    rErrorPressure : REAL;
    rDerivativePressure : REAL;
END_VAR

// Control Logic
IF NOT bEnable THEN
    rHeatingElementsPower_pct := 0.0;
    rConvectionFanSpeed_pct := 0.0;
    rQuenchBlowerSetpoint_RPM := 0.0;
    rRollerDriveSpeed_m_s := 0.0;
    bHeaterActive := FALSE;
    bQuenchActive := FALSE;
    iFaultCode := 0;
    RETURN;
END_IF;

// 1. Heating Zone Control (Thermal Profile)
IF bGlassInHeatingZone THEN
    bHeaterActive := TRUE;
    // Simple PID for Furnace Temperature
    rErrorTemp := rFurnaceSetpoint_C - rCurrentFurnaceTemp_C;
    rPID_Integral := rPID_Integral + (rErrorTemp * 0.1); // Assuming 100ms cycle
    // Anti-windup
    IF rPID_Integral > 100.0 THEN rPID_Integral := 100.0; END_IF;
    IF rPID_Integral < -100.0 THEN rPID_Integral := -100.0; END_IF;

    rDerivativeTemp := (rErrorTemp - rPID_PrevError) / 0.1;
    rHeatingElementsPower_pct := (rPID_Kp * rErrorTemp) + (rPID_Ki * rPID_Integral) + (rPID_Kd * rDerivativeTemp);
    rPID_PrevError := rErrorTemp;

    // Clamp Power
    IF rHeatingElementsPower_pct > 100.0 THEN rHeatingElementsPower_pct := 100.0; END_IF;
    IF rHeatingElementsPower_pct < 0.0 THEN rHeatingElementsPower_pct := 0.0; END_IF;

    // Forced-air convection profiling based on glass thickness
    rConvectionFanSpeed_pct := 50.0 + (rGlassThickness_mm * 2.5);
    IF rConvectionFanSpeed_pct > 100.0 THEN rConvectionFanSpeed_pct := 100.0; END_IF;
ELSE
    bHeaterActive := FALSE;
    rHeatingElementsPower_pct := 0.0;
    rConvectionFanSpeed_pct := 10.0; // Idle speed
END_IF;

// 2. Oscillating Roller Hearth Kinematics
fbTimer(IN:= bGlassInHeatingZone OR bGlassInQuenchZone, PT:= T#1000H);
IF fbTimer.IN THEN
    rTimeSeconds := TIME_TO_REAL(fbTimer.ET) / 1000.0;
    // V(t) = A * 2 * PI * f * cos(2 * PI * f * t)
    // Adding a base forward velocity
    rRollerDriveSpeed_m_s := 0.05 + (rOscillationAmplitude * 6.28318 * rOscillationFrequency * COS(6.28318 * rOscillationFrequency * rTimeSeconds));
ELSE
    rRollerDriveSpeed_m_s := 0.0;
    fbTimer(IN:= FALSE, PT:= T#0S); // Reset
END_IF;

// 3. Quench Section Forced-Air Convection & Thermal Stress Fragmentation
IF bGlassInQuenchZone THEN
    bQuenchActive := TRUE;
    // Calculate target pressure based on glass thickness for optimal fragmentation
    // Thinner glass requires significantly higher quench pressure
    rTargetQuenchPressure := 150000.0 / (rGlassThickness_mm * rGlassThickness_mm);

    // Calculate stress factor for fragmentation diagnostics
    rStressFactor := (rCurrentFurnaceTemp_C - 20.0) * rTargetQuenchPressure / 10000.0;
    IF rStressFactor > 50000.0 THEN
        iFaultCode := 1; // Potential glass breakage risk
    ELSE
        iFaultCode := 0;
    END_IF;

    // PID for Quench Blower
    rErrorPressure := rTargetQuenchPressure - rConvectionPressure_Pa;
    rBlowerPID_Integral := rBlowerPID_Integral + (rErrorPressure * 0.1);
    rDerivativePressure := (rErrorPressure - rBlowerPID_PrevError) / 0.1;

    rQuenchBlowerSetpoint_RPM := rQuenchBlowerSetpoint_RPM + (rBlowerPID_Kp * rErrorPressure) + (rBlowerPID_Ki * rBlowerPID_Integral) + (rBlowerPID_Kd * rDerivativePressure);
    rBlowerPID_PrevError := rErrorPressure;

    // Clamp RPM
