FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // Enable press control
    rWebSpeed : REAL; // Current web speed in m/min
    rTargetWebSpeed : REAL; // Target web speed in m/min
    rDoctorBladePressureSetpoint : REAL; // Base pressure in bar
    rInkViscosity : REAL; // Current ink viscosity in cP
    rESA_VoltageSetpoint : REAL; // Base ESA voltage in kV
