VAR_OUTPUT
    rDoctorBladePressureCmd : REAL; // Commanded blade pressure
    rESA_VoltageCmd : REAL; // Commanded ESA voltage
    rExhaustFanSpeedCmd : REAL; // Commanded exhaust fan speed
    bAlarmLEL : BOOL; // High LEL alarm
    bTripLEL : BOOL; // Critical LEL trip
    bESA_Active : BOOL; // ESA system active
