VAR
    rSpeedFactor : REAL;
    rViscosityFactor : REAL;
    rMaxLEL : REAL;
    rExhaustFanPID_P : REAL := 2.5;
    rExhaustFanPID_I : REAL := 0.5;
    rExhaustFanIntegral : REAL := 0.0;
    rExhaustError : REAL;
    rLEL_LimitWarning : REAL := 25.0; // 25% LEL
    rLEL_LimitTrip : REAL := 40.0; // 40% LEL
    rExhaustBaseSpeed : REAL := 1500.0;
    bInitialize : BOOL := TRUE;
END_VAR

IF NOT bEnable THEN
    rDoctorBladePressureCmd := 0.0;
    rESA_VoltageCmd := 0.0;
    rExhaustFanSpeedCmd := rExhaustBaseSpeed * 0.2; // Idle speed
    bESA_Active := FALSE;
    bAlarmLEL := FALSE;
    bTripLEL := FALSE;
    RETURN;
END_IF;

// Determine maximum LEL reading
IF rLEL_Sensor1 > rLEL_Sensor2 THEN
    rMaxLEL := rLEL_Sensor1;
ELSE
    rMaxLEL := rLEL_Sensor2;
END_IF;

// LEL Alarm and Trip Logic
bAlarmLEL := (rMaxLEL >= rLEL_LimitWarning);
bTripLEL := (rMaxLEL >= rLEL_LimitTrip);

IF bTripLEL THEN
    // Emergency purge sequence
    rExhaustFanSpeedCmd := 3000.0; // Max speed
    rESA_VoltageCmd := 0.0;
    bESA_Active := FALSE;
    rDoctorBladePressureCmd := 0.0;
    RETURN;
END_IF;

// Doctor Blade Pneumatic Pressure Profiling
// Pressure must increase dynamically with web speed and ink viscosity to prevent hydroplaning
rSpeedFactor := rWebSpeed / 500.0; // Normalized to 500 m/min max speed
rViscosityFactor := (rInkViscosity - 20.0) / 10.0; // Normalized deviation from 20 cP

rDoctorBladePressureCmd := rDoctorBladePressureSetpoint + (rSpeedFactor * 1.5) + (rViscosityFactor * 0.2);

// Clamp pressure to safe mechanical limits
IF rDoctorBladePressureCmd > 6.0 THEN
    rDoctorBladePressureCmd := 6.0;
ELSIF rDoctorBladePressureCmd < 1.0 THEN
    rDoctorBladePressureCmd := 1.0;
END_IF;

// Electrostatic Ink Assist (ESA) Control
// ESA voltage scales with speed to maintain ink transfer efficiency
IF rWebSpeed > 50.0 AND NOT bAlarmLEL THEN
    bESA_Active := TRUE;
    rESA_VoltageCmd := rESA_VoltageSetpoint + (rSpeedFactor * 2.0); // Increase up to +2kV at max speed
ELSE
    bESA_Active := FALSE;
    rESA_VoltageCmd := 0.0;
END_IF;

// Clamp ESA voltage
IF rESA_VoltageCmd > 10.0 THEN
    rESA_VoltageCmd := 10.0;
END_IF;

// Dryer Exhaust LEL Tracking and Fan Control (PI Controller)
// Goal: Maintain LEL below 15% during normal operation for energy efficiency
rExhaustError := rMaxLEL - 15.0;

// Anti-windup for integral
IF rExhaustError > 0.0 OR rExhaustFanIntegral > 0.0 THEN
    rExhaustFanIntegral := rExhaustFanIntegral + (rExhaustError * rExhaustFanPID_I * 0.1); // Assuming 100ms task cycle
END_IF;

IF rExhaustFanIntegral > 1000.0 THEN
    rExhaustFanIntegral := 1000.0;
ELSIF rExhaustFanIntegral < -500.0 THEN
    rExhaustFanIntegral := -500.0;
END_IF;

rExhaustFanSpeedCmd := rExhaustBaseSpeed + (rExhaustError * rExhaustFanPID_P) + rExhaustFanIntegral;

// Adjust base speed according to web speed feed-forward
rExhaustFanSpeedCmd := rExhaustFanSpeedCmd + (rSpeedFactor * 500.0);

IF rExhaustFanSpeedCmd > 3000.0 THEN
    rExhaustFanSpeedCmd := 3000.0;
ELSIF rExhaustFanSpeedCmd < 500.0 THEN
    rExhaustFanSpeedCmd := 500.0;
END_IF;

END_FUNCTION_BLOCK\n```
