FUNCTION_BLOCK FB_HumanCentrifugeControl
VAR_INPUT
    (* --- Critical Safety Interlocks --- *)
    bSystemEnable           : BOOL;     (* Global enable from flight director console *)
    bHarnessInterlock       : BOOL;     (* 5-point harness secured and verified *)
    bDoorSealInterlock      : BOOL;     (* Gondola hermetic seal verified OK *)
    bSubjectConscious       : BOOL;     (* Dead-man switch or cognitive assessment OK *)

    (* --- Kinematic Commands --- *)
    rTargetGForce           : LREAL;    (* Commanded total vector sum G-force (1.0 to 15.0 G) *)
    rTargetPitchAngle       : LREAL;    (* Commanded gondola pitch angle (rad) *)
    rTargetRollAngle        : LREAL;    (* Commanded gondola roll angle (rad) *)

    (* --- Telemetry / Physiological Feedback --- *)
    rSubjectHeartRate       : REAL;     (* Subject heart rate (bpm) via real-time ECG *)
    rSubjectMAP             : REAL;     (* Mean Arterial Pressure (mmHg) via continuous cuff *)

    (* --- Drive System Feedback --- *)
    rActualMainArmVelocity  : LREAL;    (* Actual main arm rotational speed (rad/s) *)
END_VAR
VAR_OUTPUT
    (* --- System Status & Annunciation --- *)
    bSystemReady            : BOOL;     (* Drive system initialized, cooled, and ready *)
    bEmergencyAbort         : BOOL;     (* Emergency abort active - active regenerative braking initiated *)
    iSystemState            : INT;      (* Current active state machine step for HMI display *)

    (* --- Drive Control References --- *)
    rMainArmSpeedRef        : LREAL;    (* Speed reference for 50MW main arm inverter (rad/s) *)
    rPitchTorqueRef         : LREAL;    (* Feed-forward torque ref for direct-drive pitch motor (Nm) *)
    rRollTorqueRef          : LREAL;    (* Feed-forward torque ref for direct-drive roll motor (Nm) *)

    (* --- Life Support Sub-systems --- *)
    rGSuitPressureCmd       : REAL;     (* Pressure command to Anti-G suit pneumatic servo valves (psi) *)
END_VAR
VAR
    (* Internal State Control *)
    iState                  : INT := 0;

    (* System Timers *)
    tRunTimer               : TON;
    tGOnsetTimer            : TON;

    (* Dynamic Trajectory Variables *)
    rFilteredGForceCmd      : LREAL;
    rGForceRateLimit        : LREAL := 0.75; (* Max allowed G/s onset limit to prevent sudden GLOC *)
    rCalculatedOmega        : LREAL;    (* Required rotational velocity for desired radial G *)

    (* Kinematic Constants *)
    rArmRadius              : LREAL := 8.5; (* Centrifuge main arm effective radius in meters *)
    rGravityConst           : LREAL := 9.80665;

    (* Physiological protection constants (GLOC Prevention Algorithm) *)
    rMaxSafeHeartRate       : REAL := 195.0;
    rMinSafeMAP             : REAL := 55.0;

    (* PID state for Coriolis Suppression *)
    rPitchErrorIntegral     : LREAL := 0.0;
    rRollErrorIntegral      : LREAL := 0.0;
END_VAR

(* =====================================================================
   MAIN SAFETY AND INTERLOCK EVALUATION LOGIC
   Evaluated every PLC scan cycle (1ms deterministic execution)
   ===================================================================== *)
IF NOT bSystemEnable OR NOT bHarnessInterlock OR NOT bDoorSealInterlock THEN
    bSystemReady := FALSE;
    bEmergencyAbort := TRUE;
    rMainArmSpeedRef := 0.0;
    rPitchTorqueRef := 0.0;
    rRollTorqueRef := 0.0;
    rGSuitPressureCmd := 0.0;
    iState := 999; (* Hard transition to fault/abort state *)
END_IF;

(* Physiological abort check - Automatic Gravity-Induced Loss of Consciousness (GLOC) prevention *)
IF bSystemEnable AND (NOT bSubjectConscious OR (rSubjectMAP < rMinSafeMAP) OR (rSubjectHeartRate > rMaxSafeHeartRate)) THEN
    bEmergencyAbort := TRUE;
    iState := 999;
END_IF;

(* =====================================================================
   CENTRIFUGE KINEMATIC STATE MACHINE
   ===================================================================== *)
CASE iState OF
    0: (* INIT / IDLE STATE *)
        bSystemReady := TRUE;
        bEmergencyAbort := FALSE;
        rMainArmSpeedRef := 0.0;
        rGSuitPressureCmd := 0.0;
        rFilteredGForceCmd := 1.0; (* Base 1G at rest *)

        IF bSystemEnable AND NOT bEmergencyAbort THEN
            iState := 10;
        END_IF;

    10: (* SPIN UP TO IDLE / STANDBY G (1.4G profile) *)
        rFilteredGForceCmd := 1.4;
        (* Calculate required angular velocity: G_radial = r * w^2 / g *)
        rCalculatedOmega := SQRT((rFilteredGForceCmd * rGravityConst) / rArmRadius);
        rMainArmSpeedRef := rCalculatedOmega;
        rPitchTorqueRef := 125.0; (* Pre-tension pitch drive to counteract initial windage *)

        IF rActualMainArmVelocity >= (rCalculatedOmega * 0.95) THEN
            iState := 20;
        END_IF;

    20: (* DYNAMIC G-PROFILE TRACKING AND CORIOLIS SUPPRESSION *)
        (* Rate limit the G-force command trajectory to safely track desired profile *)
        IF (rTargetGForce - rFilteredGForceCmd) > (rGForceRateLimit * 0.001) THEN (* Assuming 1ms cycle *)
            rFilteredGForceCmd := rFilteredGForceCmd + (rGForceRateLimit * 0.001);
        ELSIF (rTargetGForce - rFilteredGForceCmd) < -(rGForceRateLimit * 0.001) THEN
            rFilteredGForceCmd := rFilteredGForceCmd - (rGForceRateLimit * 0.001);
        ELSE
            rFilteredGForceCmd := rTargetGForce;
        END_IF;

        (* Complex Kinematics: Calculate main arm omega for combined vector
           Total G = sqrt(G_radial^2 + 1G^2) --> G_radial = sqrt(Total_G^2 - 1) *)
        IF rFilteredGForceCmd > 1.0 THEN
            rCalculatedOmega := SQRT((SQRT(EXPT(rFilteredGForceCmd, 2) - 1.0) * rGravityConst) / rArmRadius);
        ELSE
            rCalculatedOmega := 0.0;
        END_IF;
        rMainArmSpeedRef := rCalculatedOmega;

        (* Coriolis illusion suppression - Feed-forward torque compensation based on rate-of-change
           Allows high fidelity multi-axis coordination while spinning at high RPM *)
        rPitchTorqueRef := rTargetPitchAngle * 3500.0; 
        rRollTorqueRef := rTargetRollAngle * 2800.0;

        (* Cardiovascular synchronization logic - pressurize anti-G suit linearly based on G-load above 2G
           to restrict blood pooling in lower extremities *)
        IF rFilteredGForceCmd > 2.0 THEN
            rGSuitPressureCmd := LREAL_TO_REAL((rFilteredGForceCmd - 2.0) * 1.85); (* 1.85 psi per G above 2G *)
        ELSE
            rGSuitPressureCmd := 0.0;
        END_IF;

    999: (* EMERGENCY ABORT SEQUENCE *)
        (* Active regenerative controlled deceleration to prevent severe tumbling and subject injury *)
        IF rMainArmSpeedRef > 0.05 THEN
            rMainArmSpeedRef := rMainArmSpeedRef - 0.05; (* Safe ramp down parameter *)
        ELSE
            rMainArmSpeedRef := 0.0;
            IF NOT bSystemEnable THEN
                iState := 0; (* Require manual operator reset to leave abort state *)
            END_IF;
        END_IF;

        (* Immediately dump G-suit pressure on abort to restore normal circulation *)
        rGSuitPressureCmd := 0.0; 

END_CASE;

(* Expose current state for SCADA / HMI telemetry *)
iSystemState := iState;

END_FUNCTION_BLOCK
