VERSION : 0.1
   VAR_INPUT
      Enable : Bool;
      Setpoint_Speed : Real;
      Actual_Speed : Real;
      Vibration_Level : Real;
      ATC_Request : Bool;
      Tool_Unclamp_Sensor : Bool;
      Tool_Clamp_Sensor : Bool;
      Bearing_Temp : Real; // Celsius
   END_VAR
   VAR_OUTPUT
      Drive_Speed_Ref : Real;
      Spindle_Ready : Bool;
      Tool_Wear_Warning : Bool;
      Spindle_Fault : Bool;
      ATC_State : Int;
   END_VAR
   VAR
      Kp : Real := 0.5;
      Ki : Real := 0.1;
      Speed_Error : Real;
      Integral_Sum : Real;
      Vibration_Limit : Real := 5.0; 
      State : Int;
      Max_Speed : Real;
