IF #Bearing_Temp > 100.0 THEN
    #Spindle_Fault := TRUE;
    #Max_Speed := 0.0;
ELSIF #Bearing_Temp > 80.0 THEN
    #Max_Speed := 5000.0; // Derate speed due to heating
ELSE
