FUNCTION_BLOCK FB_UtilityTidalTurbineArray
VAR_INPUT
    rTideVelocity_ms     : REAL;  (* Current tide velocity in m/s *)
    bEbbFlowDirection    : BOOL;  (* TRUE = Ebb direction, FALSE = Flow direction *)
    rWaterDensity        : REAL := 1025.0; (* Seawater density kg/m^3 *)
    aSealPressures       : ARRAY[1..6] OF REAL; (* Subsea pod seal pressures (bar) *)
    aMoistureSensors     : ARRAY[1..6] OF BOOL; (* Moisture intrusion sensors inside pods *)
    aRotorSpeeds_RPM     : ARRAY[1..6] OF REAL; (* Rotor speeds RPM *)
    rGridDemand_MW       : REAL;  (* MW target from grid operator *)
END_VAR
VAR_OUTPUT
    aPitchAngles_deg     : ARRAY[1..6] OF REAL; (* Commanded blade pitch angles (deg) *)
    aGeneratorTorques_kNm: ARRAY[1..6] OF REAL; (* Commanded torques (kNm) *)
    bEmergencyStop       : BOOL;  (* Global E-Stop for the tidal pod array *)
    bLeakAlarm           : BOOL;  (* Seal leak detected in one or more pods *)
    rSmoothedPower_MW    : REAL;  (* Smoothed MW output for the array *)
    nErrorCode           : DINT;  (* Diagnostic code *)
END_VAR
VAR
    i                    : INT;
    rTargetPitch         : REAL;
    rIdealPower_kW       : REAL;
    rCurrentPower_kW     : REAL;
    aWakeInterference    : ARRAY[1..6] OF REAL;
    rTempSum_MW          : REAL;
    rPressureDropLimit   : REAL := 0.45; (* Max allowed pressure drop in bar before alarm *)
    rNominalSealPressure : REAL := 3.0;  (* Nominal hydrostatic seal pressure at depth *)
    rMaxPitchLimit       : REAL := 85.0; (* Feathered max pitch *)
    rMinPitchLimit       : REAL := -5.0; (* Max reverse pitch *)
    rCp_Max              : REAL := 0.48; (* Maximum power coefficient of the turbine *)
    rSweptArea_m2        : REAL := 450.0; (* Swept area of a single turbine *)
END_VAR

(* =========================================================================
   SUBSEA POD SEAL LEAK DETECTION SUBSYSTEM
   Monitors hydrostatic seal integrity and moisture sensors across all pods.
   Trips emergency stop if intrusion is detected to prevent generator failure.
   ========================================================================= *)
bLeakAlarm := FALSE;
bEmergencyStop := FALSE;
nErrorCode := 0;

FOR i := 1 TO 6 DO
    (* Condition: Moisture detected OR severe pressure drop indicating seal blowout *)
    IF aMoistureSensors[i] OR ((rNominalSealPressure - aSealPressures[i]) > rPressureDropLimit) THEN
        bLeakAlarm := TRUE;
        bEmergencyStop := TRUE;
        nErrorCode := 16#F000 + INT_TO_DINT(i); (* High byte F0 indicates leak, low nibble indicates pod index *)
        EXIT;
    END_IF;
END_FOR;

IF bEmergencyStop THEN
    (* Emergency routine: Feather all blades to shed load and drop excitation torque to 0 *)
    FOR i := 1 TO 6 DO
        aPitchAngles_deg[i]      := rMaxPitchLimit;
        aGeneratorTorques_kNm[i] := 0.0;
    END_FOR;
    rSmoothedPower_MW := 0.0;
    RETURN; (* Halt further control processing during E-Stop *)
END_IF;

(* =========================================================================
   BI-DIRECTIONAL EBB/FLOW BLADE PITCHING KINEMATICS
   Adjusts baseline pitch angle for optimal angle of attack based on tide dir.
   ========================================================================= *)
IF bEbbFlowDirection THEN
    (* Ebb tide characteristic curve (e.g., flow toward sea) *)
    rTargetPitch := (rTideVelocity_ms * 2.85) - 4.5; 
ELSE
    (* Flow tide characteristic curve (e.g., flow toward land) *)
    (* Flow may have different turbulence and velocity profiles *)
    rTargetPitch := (rTideVelocity_ms * 2.30) - 1.5; 
END_IF;

(* Enforce hard mechanical limits on blade pitching mechanism *)
IF rTargetPitch > 45.0 THEN
    rTargetPitch := 45.0;
ELSIF rTargetPitch < rMinPitchLimit THEN
    rTargetPitch := rMinPitchLimit;
END_IF;

(* =========================================================================
   WAKE INTERFERENCE AND ACTIVE POWER SMOOTHING
   Downstream turbines experience lower incident velocity and higher turbulence.
   We dynamically map wake interference factors to distribute load.
   ========================================================================= *)
(* Base theoretical extracted power for a single turbine without wake deficits *)
rIdealPower_kW := 0.5 * rWaterDensity * rSweptArea_m2 * (rTideVelocity_ms * rTideVelocity_ms * rTideVelocity_ms) * rCp_Max / 1000.0;

rTempSum_MW := 0.0;

FOR i := 1 TO 6 DO
    (* Determine sequential wake loss coefficient. Upstream is index 1 or 6 based on tide dir *)
    IF bEbbFlowDirection THEN
        aWakeInterference[i] := 1.0 - (INT_TO_REAL(i - 1) * 0.065);
    ELSE
        aWakeInterference[i] := 1.0 - (INT_TO_REAL(6 - i) * 0.065);
    END_IF;

    (* Floor the wake coefficient to prevent negative extraction modeling *)
    IF aWakeInterference[i] < 0.4 THEN
        aWakeInterference[i] := 0.4;
    END_IF;

    (* Fine-tune individual blade pitch to operate efficiently in the specific wake zone *)
    aPitchAngles_deg[i] := rTargetPitch + ((1.0 - aWakeInterference[i]) * 8.5);

    (* Calculate generator torque command (P = T * w => T = P / w) *)
    (* Convert RPM to rad/s : RPM * 0.1047197 *)
    IF aRotorSpeeds_RPM[i] > 1.0 THEN
        aGeneratorTorques_kNm[i] := (rIdealPower_kW * aWakeInterference[i]) / (aRotorSpeeds_RPM[i] * 0.1047197);
    ELSE
        aGeneratorTorques_kNm[i] := 0.0; (* Anti-stall protection *)
    END_IF;

    (* Accumulate instantaneous estimated power across the array for grid reporting *)
    rCurrentPower_kW := aGeneratorTorques_kNm[i] * (aRotorSpeeds_RPM[i] * 0.1047197);
    rTempSum_MW := rTempSum_MW + (rCurrentPower_kW / 1000.0);
END_FOR;

rSmoothedPower_MW := rTempSum_MW;

(* Active Grid Power Clipping *)
(* If total array extraction exceeds the requested grid demand, pitch out to spill kinetic energy *)
IF rSmoothedPower_MW > rGridDemand_MW THEN
    FOR i := 1 TO 6 DO
        (* Increment pitch angle to reduce lift and torque on the blades *)
        aPitchAngles_deg[i] := aPitchAngles_deg[i] + 3.5; 
        (* Scale back generator torque proportional to the excess power *)
        aGeneratorTorques_kNm[i] := aGeneratorTorques_kNm[i] * (rGridDemand_MW / rSmoothedPower_MW);
    END_FOR;
    rSmoothedPower_MW := rGridDemand_MW;
END_IF;

END_FUNCTION_BLOCK
```

