FUNCTION_BLOCK FB_PET_Stretch_Blow_Molder
VAR_INPUT
    bEnable : BOOL; (* Enable system *)
    bEStop : BOOL; (* Emergency Stop *)
    bStartCycle : BOOL; (* Start molding cycle *)

    (* Preform IR Oven *)
    rPreformTempSetpoints : ARRAY[1..10] OF REAL; (* Target temperatures for each heating zone *)
    rPreformTempActuals : ARRAY[1..10] OF REAL; (* Actual temperatures from IR sensors *)

    (* High-Pressure Blowing *)
    rStretchRodPosition : REAL; (* Position of the stretch rod (mm) *)
    rPreBlowPressureSetpt : REAL; (* Pre-blow pressure target (bar) *)
    rMainBlowPressureSetpt : REAL; (* Main blow pressure target (bar) *)
    rActualBottlePressure : REAL; (* Actual pressure inside the bottle (bar) *)

    (* Mold Chilled Water *)
    rMoldTempSetpt : REAL; (* Target mold temperature *)
    rMoldTempActual : REAL; (* Actual mold temperature *)
    rChilledWaterFlowRate : REAL; (* Current flow rate (L/min) *)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bCycleActive : BOOL;

    (* Oven Control *)
    rHeaterPowerOutputs : ARRAY[1..10] OF REAL; (* Power output to IR heaters 0-100% *)

    (* Valve Control *)
    bPreBlowValveOpen : BOOL;
    bMainBlowValveOpen : BOOL;
    bExhaustValveOpen : BOOL;
    bStretchRodExtend : BOOL;

    (* Chiller Control *)
    rChillerPumpSpeed : REAL; (* 0-100% *)
    bMoldCoolingValveOpen : BOOL;

    (* Status/Errors *)
    nState : INT;
    bAlarm : BOOL;
    sAlarmMsg : STRING[50];
END_VAR

VAR
    (* Internal State Machine *)
    Step : INT := 0;

    (* Timers *)
    tPreBlowTimer : TON;
    tMainBlowTimer : TON;
    tCoolingTimer : TON;
    tExhaustTimer : TON;

    (* PID Controllers for Oven *)
    fbOvenPID : ARRAY[1..10] OF PID;
    fbMoldPID : PID;

    i : INT;
END_VAR

(* Emergency Stop Handling *)
IF bEStop THEN
    Step := 999;
    bSystemReady := FALSE;
    bCycleActive := FALSE;
    bAlarm := TRUE;
    sAlarmMsg := 'EMERGENCY STOP PRESSED';

    (* Safe state for outputs *)
    FOR i := 1 TO 10 DO
        rHeaterPowerOutputs[i] := 0.0;
    END_FOR;
    bPreBlowValveOpen := FALSE;
    bMainBlowValveOpen := FALSE;
    bExhaustValveOpen := TRUE; (* Vent pressure safely *)
    bStretchRodExtend := FALSE;
    rChillerPumpSpeed := 100.0; (* Max cooling just in case *)
    RETURN;
END_IF;

(* Main State Machine *)
CASE Step OF
    0: (* Initialization and Oven Heating *)
        bSystemReady := FALSE;
        bCycleActive := FALSE;
        bAlarm := FALSE;
        sAlarmMsg := '';

        (* Oven Temperature Control Loop *)
        FOR i := 1 TO 10 DO
            fbOvenPID[i](
                ACT := rPreformTempActuals[i],
                SET := rPreformTempSetpoints[i],
                KP := 2.5, TN := T#10s, TV := T#1s,
                Y => rHeaterPowerOutputs[i]
            );
        END_FOR;

        (* Mold Temperature Control Loop *)
        fbMoldPID(
            ACT := rMoldTempActual,
            SET := rMoldTempSetpt,
            KP := 5.0, TN := T#20s, TV := T#2s,
            Y => rChillerPumpSpeed
        );
        bMoldCoolingValveOpen := (rMoldTempActual > rMoldTempSetpt + 2.0);

        (* Check if temperatures are in range *)
        bSystemReady := TRUE;
        FOR i := 1 TO 10 DO
            IF ABS(rPreformTempActuals[i] - rPreformTempSetpoints[i]) > 5.0 THEN
                bSystemReady := FALSE;
            END_IF;
        END_FOR;
        IF ABS(rMoldTempActual - rMoldTempSetpt) > 3.0 THEN
            bSystemReady := FALSE;
        END_IF;

        IF bSystemReady AND bEnable AND bStartCycle THEN
            Step := 10;
        END_IF;

    10: (* Pre-Blow & Stretching *)
        bCycleActive := TRUE;
        bStretchRodExtend := TRUE;
        bExhaustValveOpen := FALSE;

        (* Start pre-blow when stretch rod reaches specific position *)
        IF rStretchRodPosition > 50.0 THEN
            bPreBlowValveOpen := TRUE;
            tPreBlowTimer(IN := TRUE, PT := T#250ms);
        END_IF;

        IF tPreBlowTimer.Q OR (rActualBottlePressure >= rPreBlowPressureSetpt) THEN
            tPreBlowTimer(IN := FALSE);
            bPreBlowValveOpen := FALSE;
            Step := 20;
        END_IF;

    20: (* Main Blow Phase *)
        bMainBlowValveOpen := TRUE;
        tMainBlowTimer(IN := TRUE, PT := T#800ms);

        IF tMainBlowTimer.Q OR (rActualBottlePressure >= rMainBlowPressureSetpt) THEN
            tMainBlowTimer(IN := FALSE);
            bMainBlowValveOpen := FALSE;
            Step := 30;
        END_IF;

    30: (* Mold Cooling Under Pressure *)
        (* Maintained by residual pressure, chiller runs *)
        tCoolingTimer(IN := TRUE, PT := T#1500ms);

        IF tCoolingTimer.Q THEN
            tCoolingTimer(IN := FALSE);
            Step := 40;
        END_IF;

    40: (* Exhaust / Venting *)
        bExhaustValveOpen := TRUE;
        bStretchRodExtend := FALSE; (* Retract stretch rod *)
        tExhaustTimer(IN := TRUE, PT := T#300ms);

        IF tExhaustTimer.Q AND rActualBottlePressure < 0.5 THEN
            tExhaustTimer(IN := FALSE);
            bExhaustValveOpen := FALSE;
            Step := 50;
        END_IF;

    50: (* Ejection & Reset *)
        bCycleActive := FALSE;
        Step := 0;

    999: (* Fault State *)
        (* Handled at top, reset required to clear *)
        IF NOT bEStop AND bEnable THEN
            Step := 0;
        END_IF;

    ELSE
        Step := 0;
END_CASE;

(* Maintain background PID updates during cycle *)
IF Step > 0 AND Step < 999 THEN
    FOR i := 1 TO 10 DO
        fbOvenPID[i](
            ACT := rPreformTempActuals[i],
            SET := rPreformTempSetpoints[i],
            KP := 2.5, TN := T#10s, TV := T#1s,
            Y => rHeaterPowerOutputs[i]
        );
    END_FOR;

    fbMoldPID(
        ACT := rMoldTempActual,
        SET := rMoldTempSetpt,
        KP := 5.0, TN := T#20s, TV := T#2s,
        Y => rChillerPumpSpeed
    );
END_IF;

nState := Step;
END_FUNCTION_BLOCK
