FUNCTION_BLOCK FB_ZeroGravity_MultiMaterial_EBM_Print
VAR_INPUT
    (* Required inputs for safety and environmental baseline in micro-gravity *)
    bEnable                 : BOOL;     (* System enable signal for the 3D printer *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (FALSE = STOP) *)
    rMicroGravityZ          : REAL;     (* Z-axis accelerometer feedback (g) *)
    rChamberVacuum          : REAL;     (* Chamber vacuum pressure (mbar) *)
    rPowderBedTemp_Ti       : REAL;     (* Titanium melt pool pyrometer feedback (deg C) *)
    rPowderBedTemp_Al       : REAL;     (* Aluminum melt pool pyrometer feedback (deg C) *)
    rAcousticLevFreq        : REAL;     (* Acoustic levitator frequency feedback (kHz) *)
    bLayerComplete          : BOOL;     (* Signal from vision system that layer is verified *)
END_VAR
VAR_OUTPUT
    (* Required outputs for control and telemetry *)
    bSystemReady            : BOOL;     (* System ready status for orbital network *)
    bAlarm                  : BOOL;     (* Fault alarm output (Critical error) *)
    rControlOutput_EBeam    : REAL;     (* Electron Beam power control output (kW) *)
    rAcousticAmplitude      : REAL;     (* Acoustic amplitude control for powder recovery (%) *)
    bRecoaterActive         : BOOL;     (* Activation signal for zero-G powder recoater blade *)
    iActiveMaterial         : INT;      (* 1 = Titanium, 2 = Aluminum, 0 = None *)
END_VAR
VAR
    (* Internal state tracking and advanced control variables *)
    iState                  : INT := 0; (* Main finite state machine sequence *)
    tLayerTimer             : TON;      (* Timer to prevent infinite melt loops *)
    tVacuumStabilize        : TON;      (* Timer for vacuum stabilization *)
    rPidError               : REAL := 0.0;
    rIntegral               : REAL := 0.0;
    rDerivative             : REAL := 0.0;
    rLastError              : REAL := 0.0;
    rKp                     : REAL := 0.025;
    rKi                     : REAL := 0.001;
    rKd                     : REAL := 0.005;
    rTargetTemp             : REAL;
    rCurrentTemp            : REAL;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency and Safety Interlocks *)
IF NOT bEmergencyStop OR (rChamberVacuum > 1.0E-3) THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rControlOutput_EBeam := 0.0;
    rAcousticAmplitude := 0.0;
    bRecoaterActive := FALSE;
    iState := 999; (* Transition to fault state *)
    RETURN;
END_IF;

(* Micro-gravity stability check *)
IF ABS(rMicroGravityZ) > 0.05 THEN
    (* Perturbations detected, suspend melting temporarily *)
    rControlOutput_EBeam := rControlOutput_EBeam * 0.1; (* Drop power to holding level *)
    bSystemReady := FALSE;
ELSE
    bSystemReady := TRUE;
END_IF;

(* State Machine for Zero-G Multi-Material Printing *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        rControlOutput_EBeam := 0.0;
        rAcousticAmplitude := 10.0; (* Keep baseline acoustic field active to hold powder *)
        bRecoaterActive := FALSE;
        IF bEnable AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: (* VACUUM STABILIZATION & LEVITATION PREP *)
        tVacuumStabilize(IN := TRUE, PT := T#15S);
        IF tVacuumStabilize.Q THEN
            tVacuumStabilize(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* MATERIAL SELECTION & RECOATING *)
        (* Alternate materials for graded alloy transition *)
        IF iActiveMaterial = 1 THEN
            iActiveMaterial := 2; (* Switch to Al *)
            rTargetTemp := 660.3; (* Al melting point *)
        ELSE
            iActiveMaterial := 1; (* Switch to Ti *)
            rTargetTemp := 1668.0;(* Ti melting point *)
        END_IF;

        bRecoaterActive := TRUE;
        rAcousticAmplitude := 85.0; (* High amplitude to sweep loose powder *)

        IF bLayerComplete THEN
            bRecoaterActive := FALSE;
            iState := 30;
        END_IF;

    30: (* MELTING PID CONTROL LOOP *)
        (* Select appropriate sensor feedback based on active material *)
        IF iActiveMaterial = 1 THEN
            rCurrentTemp := rPowderBedTemp_Ti;
        ELSE
            rCurrentTemp := rPowderBedTemp_Al;
        END_IF;

        (* PID calculation for Electron Beam Power *)
        rPidError := rTargetTemp - rCurrentTemp;
        rIntegral := rIntegral + rPidError;

        (* Anti-windup *)
        IF rIntegral > 1000.0 THEN rIntegral := 1000.0; END_IF;
        IF rIntegral < -1000.0 THEN rIntegral := -1000.0; END_IF;

        rDerivative := rPidError - rLastError;
        rControlOutput_EBeam := (rKp * rPidError) + (rKi * rIntegral) + (rKd * rDerivative);

        (* Bound output 0.0 to 10.0 kW *)
        IF rControlOutput_EBeam > 10.0 THEN rControlOutput_EBeam := 10.0; END_IF;
        IF rControlOutput_EBeam < 0.0 THEN rControlOutput_EBeam := 0.0; END_IF;

        rLastError := rPidError;

        tLayerTimer(IN := TRUE, PT := T#45S);
        IF tLayerTimer.Q OR (ABS(rPidError) < 5.0 AND bLayerComplete) THEN
            tLayerTimer(IN := FALSE);
            rControlOutput_EBeam := 0.0;
            iState := 20; (* Loop to next layer *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT RECOVERY *)
        IF bEmergencyStop AND (rChamberVacuum <= 1.0E-3) THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

