FUNCTION_BLOCK FB_H2FC_LocomotivePowertrainControl
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main contactor and system enable signal *)
    bEmergencyStop          : BOOL;     (* SIL-3 safety relay OK signal, TRUE=OK *)
    rFcStackCurrentTarget   : REAL;     (* Requested stack current from EMS (A) *)
    rFcStackTemp            : REAL;     (* PEM stack coolant outlet temperature (C) *)
    rH2SupplyPressure       : REAL;     (* Hydrogen supply pressure from tanks (Bar) *)
    rDcLinkVoltage          : REAL;     (* Measured DC Link voltage (V) *)
    rSupercapSoc            : REAL;     (* Supercapacitor bank State of Charge (%) *)
    bRegenBrakeActive       : BOOL;     (* Regenerative braking flag *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready and nominal status *)
    rFcCoolantPumpSpeed     : REAL;     (* Target speed for thermal management coolant pump (RPM) *)
    rH2ValvePosition        : REAL;     (* Target position for proportional H2 supply valve (%) *)
    rBoostConverterDuty     : REAL;     (* PWM duty cycle for interleaved boost converter (0-1) *)
    bScDumpResistorEnable   : BOOL;     (* Enable signal for regenerative braking dump resistor chopper *)
    bCriticalAlarm          : BOOL;     (* Fault alarm output necessitating immediate traction disconnect *)
    iStateOut               : INT;      (* Current state machine step for HMI/diagnostic logging *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine tracker *)
    tStartupTimer           : TON;      (* Purge and pre-charge delay timer *)
    tFaultTimer             : TON;      (* Fault debouncing timer *)

    (* Filter variables for sensor noise *)
    rFilteredStackTemp      : REAL;
    rFilteredDcLinkVolt     : REAL;

    (* PI Controller internal states *)
    rTempError              : REAL;
    rTempIntegral           : REAL;

    rVoltError              : REAL;
    rVoltIntegral           : REAL;

    (* Constants *)
    rTEMP_KP                : REAL := 12.5;
    rTEMP_KI                : REAL := 0.25;
    rVOLT_KP                : REAL := 0.05;
    rVOLT_KI                : REAL := 0.001;

    rNOMINAL_DC_LINK        : REAL := 1800.0; (* 1.8kV nominal DC link for heavy rail *)
    rMAX_STACK_TEMP         : REAL := 85.0;   (* Max allowable PEM temp *)
END_VAR

(* === MAIN LOGIC === *)
(* First pass: Safety interlocks and fundamental sanity checks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    rFcCoolantPumpSpeed := 1500.0; (* Maintain some cooling on e-stop to prevent thermal runaway *)
    rH2ValvePosition := 0.0;
    rBoostConverterDuty := 0.0;
    bScDumpResistorEnable := FALSE;
    iState := 999; (* Fault state *)
    iStateOut := iState;
    RETURN;
END_IF;

(* Simple Exponential Moving Average (EMA) filters for noisy sensors *)
rFilteredStackTemp := (rFilteredStackTemp * 0.9) + (rFcStackTemp * 0.1);
rFilteredDcLinkVolt := (rFilteredDcLinkVolt * 0.9) + (rDcLinkVoltage * 0.1);

(* Hard limit checks on critical variables *)
IF rFilteredStackTemp > 90.0 OR rH2SupplyPressure < 2.0 OR rFilteredDcLinkVolt > 2200.0 THEN
    tFaultTimer(IN := TRUE, PT := T#500MS);
    IF tFaultTimer.Q THEN
        bCriticalAlarm := TRUE;
        iState := 999;
    END_IF;
ELSE
    tFaultTimer(IN := FALSE);
    bCriticalAlarm := FALSE;
END_IF;

(* State Machine for H2 Locomotive Powertrain Orchestration *)
CASE iState OF
    0: (* IDLE & STANDBY *)
        bSystemReady := FALSE;
        rH2ValvePosition := 0.0;
        rBoostConverterDuty := 0.0;
        bScDumpResistorEnable := FALSE;
        rFcCoolantPumpSpeed := 0.0;

        (* Reset PI integrals *)
        rTempIntegral := 0.0;
        rVoltIntegral := 0.0;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* PRE-CHARGE AND PURGE *)
        (* Open proportional valve slightly to purge nitrogen/water from anode, spin up coolant *)
        rH2ValvePosition := 5.0; 
        rFcCoolantPumpSpeed := 500.0;

        tStartupTimer(IN := TRUE, PT := T#10S);
        IF tStartupTimer.Q THEN
            tStartupTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RUNNING - DYNAMIC REGULATION *)
        bSystemReady := TRUE;

        (* Thermal Management PI Control *)
        rTempError := rFilteredStackTemp - 75.0; (* 75C target *)
        IF rTempError > 0.0 THEN
            rTempIntegral := rTempIntegral + rTempError;
            (* Anti-windup clamp *)
            IF rTempIntegral > 2000.0 THEN rTempIntegral := 2000.0; END_IF;
            rFcCoolantPumpSpeed := 500.0 + (rTempError * rTEMP_KP) + (rTempIntegral * rTEMP_KI);
        ELSE
            rFcCoolantPumpSpeed := 500.0; (* Minimum idle circulation *)
        END_IF;

        IF rFcCoolantPumpSpeed > 3000.0 THEN rFcCoolantPumpSpeed := 3000.0; END_IF;

        (* DC-Link Voltage Boost Converter PI Control *)
        rVoltError := rNOMINAL_DC_LINK - rFilteredDcLinkVolt;
        rVoltIntegral := rVoltIntegral + rVoltError;
        (* Anti-windup *)
        IF rVoltIntegral > 500.0 THEN rVoltIntegral := 500.0; END_IF;
        IF rVoltIntegral < -500.0 THEN rVoltIntegral := -500.0; END_IF;

        rBoostConverterDuty := 0.5 + (rVoltError * rVOLT_KP) + (rVoltIntegral * rVOLT_KI);
        IF rBoostConverterDuty > 0.95 THEN rBoostConverterDuty := 0.95; END_IF;
        IF rBoostConverterDuty < 0.05 THEN rBoostConverterDuty := 0.05; END_IF;

        (* Proportional H2 Feed Forward based on current target, plus feedback *)
        rH2ValvePosition := (rFcStackCurrentTarget / 1000.0) * 10.0;
        IF rH2ValvePosition > 100.0 THEN rH2ValvePosition := 100.0; END_IF;

        (* Supercapacitor Dump Resistor Logic for Regen Braking *)
        IF bRegenBrakeActive AND rSupercapSoc > 95.0 AND rFilteredDcLinkVolt > 1950.0 THEN
            bScDumpResistorEnable := TRUE;
        ELSE
            bScDumpResistorEnable := FALSE;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT LOCKOUT *)
        bSystemReady := FALSE;
        rH2ValvePosition := 0.0;
        rBoostConverterDuty := 0.0;
        bScDumpResistorEnable := TRUE; (* Dump remaining DC-link energy for safety *)
        rFcCoolantPumpSpeed := 1500.0;

        (* Manual reset required via system disable then enable when e-stop is cleared *)
        IF NOT bSystemEnable AND NOT bCriticalAlarm THEN
            iState := 0;
        END_IF;

END_CASE;

iStateOut := iState;

END_FUNCTION_BLOCK
```

