FUNCTION_BLOCK FB_LiIon_Winding_Machine
VAR_INPUT
    bEnable : BOOL; (* System Enable *)
    bEmergencyStop : BOOL; (* E-Stop *)
    fTargetWindingDiameter : REAL; (* Target final cell diameter in mm *)
    fLineSpeedSetpoint : REAL; (* Web speed setpoint m/min *)
    fAnodeTensionSetpoint : REAL; (* N *)
    fCathodeTensionSetpoint : REAL; (* N *)
    fSeparatorTensionSetpoint : REAL; (* N *)
    fAnodeWebThickness : REAL; (* mm *)
    fCathodeWebThickness : REAL; (* mm *)
    fSeparatorThickness : REAL; (* mm *)
    fMandrelInitialDiameter : REAL; (* mm *)

    // Sensor inputs
    fAnodeTensionFeedback : REAL; 
    fCathodeTensionFeedback : REAL;
    fSeparatorTensionFeedback : REAL;
    fMandrelEncoderPos : REAL; (* Degrees *)
    fMandrelSpeedFeedback : REAL; (* RPM *)

    bStaticEliminatorFault : BOOL;
END_VAR

VAR_OUTPUT
    fMandrelMotorTorqueRef : REAL; (* % *)
    fMandrelMotorSpeedRef : REAL; (* RPM *)

    fAnodeDancerPressureRef : REAL; (* bar *)
    fCathodeDancerPressureRef : REAL; (* bar *)
    fSeparatorDancerPressureRef : REAL; (* bar *)

    bStaticEliminatorEnable : BOOL;
    bSystemFault : BOOL;
    nState : INT; (* 0: Off, 10: Init, 20: Threading, 30: Ramping, 40: Winding, 50: Decel, 60: Cut & Tape *)
    fCurrentDiameter : REAL; (* mm *)
END_VAR

VAR
    fWoundThickness : REAL;
    fAngularPosTotal : LREAL;
    fPrevEncoderPos : REAL;
    fMandrelRPM_Set : REAL;

    // PID Controllers for Tension
    fbAnodeTensionPID : PID;
    fbCathodeTensionPID : PID;
    fbSeparatorTensionPID : PID;

    fAnodeError : REAL;
    fCathodeError : REAL;
    fSeparatorError : REAL;

    // Winding Profile
    fRampRate : REAL := 5.0; // m/min per sec
    fCurrentWebSpeed : REAL; // m/min

    // Static Elimination
    fStaticDischargePulseTimer : TON;
END_VAR

// Implementation
IF bEmergencyStop THEN
    nState := 0;
    bSystemFault := TRUE;
    fMandrelMotorSpeedRef := 0.0;
    fMandrelMotorTorqueRef := 0.0;
    bStaticEliminatorEnable := FALSE;
    RETURN;
END_IF

// Calculate Current Diameter based on accumulated rotation
IF fMandrelEncoderPos < fPrevEncoderPos THEN
    fAngularPosTotal := fAngularPosTotal + (360.0 - fPrevEncoderPos + fMandrelEncoderPos);
ELSE
    fAngularPosTotal := fAngularPosTotal + (fMandrelEncoderPos - fPrevEncoderPos);
END_IF
fPrevEncoderPos := fMandrelEncoderPos;

// Each revolution adds (Anode + Cathode + 2*Separator) to the radius (twice to the diameter)
fWoundThickness := (fAnodeWebThickness + fCathodeWebThickness + 2.0 * fSeparatorThickness) * (fAngularPosTotal / 360.0);
fCurrentDiameter := fMandrelInitialDiameter + (fWoundThickness * 2.0);

// State Machine for Winding Cycle
CASE nState OF
    0: // Off
        fCurrentWebSpeed := 0.0;
        IF bEnable AND NOT bSystemFault THEN
            nState := 10;
        END_IF

    10: // Init
        fAngularPosTotal := 0.0;
        fCurrentDiameter := fMandrelInitialDiameter;
        bStaticEliminatorEnable := TRUE;
        IF NOT bStaticEliminatorFault THEN
            nState := 20;
        END_IF

    20: // Threading
        fCurrentWebSpeed := 5.0; // Low speed for threading
        nState := 30; // Auto transition for simulation

    30: // Ramping
        fCurrentWebSpeed := fCurrentWebSpeed + fRampRate * 0.01; // Assuming 10ms cycle time
        IF fCurrentWebSpeed >= fLineSpeedSetpoint THEN
            fCurrentWebSpeed := fLineSpeedSetpoint;
            nState := 40;
        END_IF

    40: // Winding
        IF fCurrentDiameter >= (fTargetWindingDiameter - 2.0) THEN
            nState := 50; // Start deceleration before target diameter
        END_IF

    50: // Deceleration
        fCurrentWebSpeed := fCurrentWebSpeed - fRampRate * 0.01;
        IF fCurrentWebSpeed <= 2.0 THEN
            fCurrentWebSpeed := 2.0;
            nState := 60;
        END_IF

    60: // Cut & Tape
        fCurrentWebSpeed := 0.0;
        // External logic to apply tape and cut the webs
        nState := 0; // Cycle complete
END_CASE

// Mandrel Kinematics (Mandrel Speed = WebSpeed / (PI * Current Diameter))
// Ensure unit consistency: WebSpeed in m/min, Diameter in mm -> RPM
IF fCurrentDiameter > 0.0 THEN
    fMandrelMotorSpeedRef := (fCurrentWebSpeed * 1000.0) / (3.14159265359 * fCurrentDiameter);
ELSE
    fMandrelMotorSpeedRef := 0.0;
END_IF

// Tension Cascading Control via PID Controllers
fAnodeError := fAnodeTensionSetpoint - fAnodeTensionFeedback;
fbAnodeTensionPID(
    ACTUAL := fAnodeTensionFeedback,
    SET_POINT := fAnodeTensionSetpoint,
    KP := 1.5,
    KI := 0.5,
    KD := 0.1,
    OUT => fAnodeDancerPressureRef
);

fCathodeError := fCathodeTensionSetpoint - fCathodeTensionFeedback;
fbCathodeTensionPID(
    ACTUAL := fCathodeTensionFeedback,
    SET_POINT := fCathodeTensionSetpoint,
    KP := 1.6,
    KI := 0.6,
    KD := 0.12,
    OUT => fCathodeDancerPressureRef
);

fSeparatorError := fSeparatorTensionSetpoint - fSeparatorTensionFeedback;
fbSeparatorTensionPID(
    ACTUAL := fSeparatorTensionFeedback,
    SET_POINT := fSeparatorTensionSetpoint,
    KP := 1.2,
    KI := 0.4,
    KD := 0.05,
    OUT => fSeparatorDancerPressureRef
);

// Taper Tension Control Implementation
// Reduce setpoint tension proportionally as wound diameter increases 
// to prevent internal stress, telescoping, and wrinkling of the jelly roll.
fAnodeDancerPressureRef := fAnodeDancerPressureRef * (1.0 - 0.15 * (fCurrentDiameter / fTargetWindingDiameter));
fCathodeDancerPressureRef := fCathodeDancerPressureRef * (1.0 - 0.15 * (fCurrentDiameter / fTargetWindingDiameter));

// Static Elimination pulsing logic for high-speed separator unwinding
fStaticDischargePulseTimer(IN := NOT fStaticDischargePulseTimer.Q, PT := T#500MS);
IF fStaticDischargePulseTimer.Q AND nState >= 30 THEN
    // Pulse static elimination to prevent charge build-up and separator sticking
    bStaticEliminatorEnable := NOT bStaticEliminatorEnable;
ELSIF nState < 30 THEN
    bStaticEliminatorEnable := TRUE;
END_IF

END_FUNCTION_BLOCK
