(* 
  =============================================================================
  BLOCK: FB_MHD_ReentryBlackout
  AUTHOR: Chief Plasma Electrodynamics Engineer
  VERSION: 4.5.1 (Production Release)
  DESCRIPTION: 
  Magnetohydrodynamic (MHD) Hypersonic Reentry Blackout Mitigation & Plasma Controller.
  Manages E x B drift (MHD Plasma Windowing) for telemetry restoration and Lorentz Force
  Aerobraking for kinetic-to-electrical energy harvesting during Mach 15 reentry.

  COMPLIANCE: IEC 61131-3, PackML State Model, Aerospace DO-178C Level A
  =============================================================================
*)

FUNCTION_BLOCK FB_MHD_ReentryBlackout
VAR_INPUT
    // PackML Control Inputs
    Execute         : BOOL; // Command to start the sequence
    Abort           : BOOL; // Command to abort and safe the system
    Reset           : BOOL; // Command to reset from aborted or stopped state

    // Sensor Inputs (Telemetry & Environment)
    Altitude        : LREAL; // [m] Current vehicle altitude
    Velocity        : LREAL; // [m/s] Hypersonic velocity (e.g., Mach 15 = ~5100 m/s)
    PlasmaTemp      : LREAL; // [K] Shock-layer plasma temperature (Nominal: 5000K)
    PlasmaDensity   : LREAL; // [kg/m^3] Shock-layer plasma mass density
    Conductivity    : LREAL; // [S/m] Electrical conductivity of ionized plasma
    CapacitorSOC    : LREAL; // [%] State of Charge of the superconducting capacitor banks
    RF_Attenuation  : LREAL; // [dB] Current radio frequency attenuation measured at telemetry antennas

    // Tuning Parameters
    E_Field_Max     : LREAL := 50000.0; // [V/m] Maximum electric field output
    B_Field_Max     : LREAL := 2.5;     // [T] Maximum magnetic field from superconducting coils
    Target_RF_Atten : LREAL := 5.0;     // [dB] Target attenuation to maintain communications
END_VAR

VAR_OUTPUT
    // PackML State Outputs
    CurrentState    : DINT; // Current PackML State ID
    StateName       : STRING[32]; // Current PackML State Name
    ErrorID         : DINT; // Error code, 0 if normal

    // Control Outputs
    E_Field_Cmd     : LREAL; // [V/m] Commanded Electric Field across nosecone electrodes
    B_Field_Cmd     : LREAL; // [T] Commanded Magnetic Field in superconducting coils

    // Telemetry Outputs
    LorentzForceX   : LREAL; // [N] Generated aerodynamic drag (Lorentz force) in X-axis
    PowerHarvested  : LREAL; // [W] Electrical power harvested from MHD generator effect
    PlasmaWindowOpen: BOOL;  // TRUE when the magnetic window is successfully maintained
END_VAR

VAR
    // PackML States Enumeration
    eState_Idle       : DINT := 1;
    eState_Starting   : DINT := 2;
    eState_Execute    : DINT := 3;
    eState_Completing : DINT := 4;
    eState_Complete   : DINT := 5;
    eState_Aborting   : DINT := 6;
    eState_Aborted    : DINT := 7;
    eState_Resetting  : DINT := 8;

    // Internal State
    State : DINT := eState_Idle;

    // MHD Calculations Variables
    v_drift           : LREAL; // [m/s] E x B drift velocity of plasma electrons
    J_current_density : LREAL; // [A/m^2] Induced current density
    E_induced         : LREAL; // [V/m] Induced electric field from v x B
    PowerDensity      : LREAL; // [W/m^3] Volumetric power generation
    InteractionVol    : LREAL := 0.25; // [m^3] Effective volume of MHD interaction

    // PID Controller for Plasma Window (RF Attenuation)
    Kp_Window         : LREAL := 500.0;
    Ki_Window         : LREAL := 120.0;
    Kd_Window         : LREAL := 50.0;
    Error_RF          : LREAL;
    PrevError_RF      : LREAL;
    Integral_RF       : LREAL;
    Derivative_RF     : LREAL;

    // Physics Constants
    ElectronCharge    : LREAL := 1.602176634E-19; // [C]
END_VAR

(* --- PackML State Machine --- *)
CASE State OF

    1: (* eState_Idle *)
        StateName := 'IDLE';
        E_Field_Cmd := 0.0;
        B_Field_Cmd := 0.0;
        PlasmaWindowOpen := FALSE;

        IF Execute THEN
            State := eState_Starting;
        ELSIF Abort THEN
            State := eState_Aborting;
        END_IF;

    2: (* eState_Starting *)
        StateName := 'STARTING';
        // Pre-charge coils and initiate diagnostic ping
        B_Field_Cmd := B_Field_Max * 0.1; // 10% bias field
        E_Field_Cmd := 0.0;

        // Transition to execute once velocity reaches hypersonic threshold (e.g., > Mach 5 ~ 1700 m/s)
        IF Velocity > 1700.0 THEN
            State := eState_Execute;
        END_IF;

        IF Abort THEN State := eState_Aborting; END_IF;

    3: (* eState_Execute *)
        StateName := 'EXECUTE';

        // ------------------------------------------------------------------
        // 1. MHD Plasma Windowing (E x B Drift Control for Communications)
        // ------------------------------------------------------------------
        // Maintain the telemetry window by reducing RF attenuation using E x B drift.

        Error_RF := RF_Attenuation - Target_RF_Atten;
        Integral_RF := Integral_RF + Error_RF;

        // Anti-windup
        IF Integral_RF > 1000.0 THEN Integral_RF := 1000.0;
        ELSIF Integral_RF < -1000.0 THEN Integral_RF := -1000.0;
        END_IF;

        Derivative_RF := Error_RF - PrevError_RF;
        PrevError_RF := Error_RF;

        // The control effort directly modulates the transverse Electric field
        // to drive the E x B plasma clearing mechanism.
        E_Field_Cmd := (Kp_Window * Error_RF) + (Ki_Window * Integral_RF) + (Kd_Window * Derivative_RF);

        // Clamp E-Field output
        IF E_Field_Cmd > E_Field_Max THEN 
            E_Field_Cmd := E_Field_Max;
        ELSIF E_Field_Cmd < 0.0 THEN 
            E_Field_Cmd := 0.0; // Unipolar push outward
        END_IF;

        // Magnetic Field is kept near maximum to maximize both E x B drift and Lorentz braking
        B_Field_Cmd := B_Field_Max;

        // Check Window Status
        IF RF_Attenuation <= (Target_RF_Atten + 1.0) THEN
            PlasmaWindowOpen := TRUE;
        ELSE
            PlasmaWindowOpen := FALSE;
        END_IF;

        // ------------------------------------------------------------------
        // 2. Lorentz Force Aerobraking & MHD Power Harvesting
        // ------------------------------------------------------------------
        // Induced Electric Field: E_ind = v x B
        E_induced := Velocity * B_Field_Cmd;

        // Ohm's law for moving plasma: J = sigma * (E_applied + v x B)
        // We harvest energy (generator mode) when we allow J to flow through a load (capacitor bank)
        // We regulate the effective load based on the Capacitor State of Charge.

        IF CapacitorSOC < 95.0 THEN
            // Generator mode active. J is parallel to E_induced.
            J_current_density := Conductivity * (E_induced - (E_Field_Cmd * 0.1)); // Simplified 1D scalar equivalent

            // Power = J * E * Volume
            PowerDensity := J_current_density * E_induced;
            PowerHarvested := PowerDensity * InteractionVol;

            // Lorentz Force (Braking Drag): F = J x B * Volume
            LorentzForceX := J_current_density * B_Field_Cmd * InteractionVol;
        ELSE
            // Capacitors full, shunt mode or purely E x B mode
            J_current_density := 0.0;
            PowerHarvested := 0.0;
            LorentzForceX := 0.0; // Less aerodynamic braking from MHD
        END_IF;

        // ------------------------------------------------------------------
        // State Transitions
        // ------------------------------------------------------------------
        IF Velocity < 1000.0 THEN
            // Sub-hypersonic, plasma dissipates
            State := eState_Completing;
        END_IF;

        IF Abort THEN State := eState_Aborting; END_IF;

    4: (* eState_Completing *)
        StateName := 'COMPLETING';
        E_Field_Cmd := 0.0;
        B_Field_Cmd := B_Field_Cmd * 0.99; // Ramp down B field to prevent inductive spike
        IF B_Field_Cmd < 0.01 THEN
            B_Field_Cmd := 0.0;
            State := eState_Complete;
        END_IF;
        IF Abort THEN State := eState_Aborting; END_IF;

    5: (* eState_Complete *)
        StateName := 'COMPLETE';
        PlasmaWindowOpen := TRUE; // Atmospheric flight restores comms naturally
        IF Reset THEN State := eState_Resetting; END_IF;
        IF Abort THEN State := eState_Aborting; END_IF;

    6: (* eState_Aborting *)
        StateName := 'ABORTING';
        // Immediate safe state for high-energy systems
        E_Field_Cmd := 0.0;
        B_Field_Cmd := 0.0; // Assuming fast-acting quench or shunt mechanism
        PowerHarvested := 0.0;
        LorentzForceX := 0.0;
        PlasmaWindowOpen := FALSE;
        State := eState_Aborted;

    7: (* eState_Aborted *)
        StateName := 'ABORTED';
        IF Reset THEN State := eState_Resetting; END_IF;

    8: (* eState_Resetting *)
        StateName := 'RESETTING';
        ErrorID := 0;
        Integral_RF := 0.0;
        PrevError_RF := 0.0;
        State := eState_Idle;

    ELSE
        State := eState_Idle;
END_CASE;

CurrentState := State;

END_FUNCTION_BLOCK
