FUNCTION_BLOCK FB_SlurryMixerControl
VAR_INPUT
    bStartProcess : BOOL;
    bEmergencyStop : BOOL;
    rTargetViscosity : REAL; (* Target viscosity in Pa.s *)
    rMainAgitatorSpeedSP : REAL; (* RPM *)
    rPlanetarySpeedSP : REAL; (* RPM *)
    bVacuumEnable : BOOL;
    rTargetVacuum : REAL; (* mbar *)
    rCoolingTempSP : REAL; (* deg C *)
END_VAR
VAR_OUTPUT
    bProcessRunning : BOOL;
    bProcessComplete : BOOL;
    bError : BOOL;
    nErrorCode : INT;
    rActualViscosity : REAL;
    rCurrentTorque : REAL;
END_VAR
VAR
    (* Internal State *)
    nState : INT := 0;
    rAgitatorSpeedPV : REAL;
    rPlanetarySpeedPV : REAL;
    rJacketTempPV : REAL;
    rVacuumPV : REAL;

    (* Timers and Controllers *)
    tonMixingTimer : TON;
    pidViscosity : PID;
    pidCooling : PID;

    (* Simulating inputs/outputs *)
    rMixingTimeLimit : TIME := T#120M;
    rMaxTorque : REAL := 5000.0; (* Nm *)
END_VAR

(* Emergency Stop Handling *)
IF bEmergencyStop THEN
    bProcessRunning := FALSE;
    bProcessComplete := FALSE;
    bError := TRUE;
    nErrorCode := 9999;
    nState := 0;
    rAgitatorSpeedPV := 0.0;
    rPlanetarySpeedPV := 0.0;
    RETURN;
END_IF;

(* Main State Machine for Planetary Dispersive Mixer *)
CASE nState OF
    0: (* Idle *)
        bProcessRunning := FALSE;
        IF bStartProcess AND NOT bError THEN
            nState := 10;
            bProcessRunning := TRUE;
            bProcessComplete := FALSE;
            tonMixingTimer(IN := FALSE);
        END_IF;

    10: (* Initialization and Dry Mixing *)
        rAgitatorSpeedPV := rMainAgitatorSpeedSP * 0.2; (* Low speed for dry powder *)
        rPlanetarySpeedPV := rPlanetarySpeedSP * 0.2;
        IF rActualViscosity < 10.0 THEN
            nState := 20; (* Transition to wet mixing *)
        END_IF;

    20: (* Solvent Addition & Wet Mixing *)
        rAgitatorSpeedPV := rMainAgitatorSpeedSP * 0.5;
        rPlanetarySpeedPV := rPlanetarySpeedSP * 0.5;
        (* PID Control for Cooling Jacket *)
        pidCooling(
            ACT := rJacketTempPV,
            SET := rCoolingTempSP,
            SUP := 2.0, (* P gain *)
            INT := 10.0 (* I gain *)
        );
        IF rActualViscosity > 100.0 THEN
            nState := 30; (* High shear mixing *)
        END_IF;

    30: (* High Shear Dispersive Mixing & Vacuum Degassing *)
        rAgitatorSpeedPV := rMainAgitatorSpeedSP;
        rPlanetarySpeedPV := rPlanetarySpeedSP;

        (* Torque monitoring *)
        IF rCurrentTorque > rMaxTorque THEN
            nState := 99; (* Error state *)
            nErrorCode := 1001; (* Torque limit exceeded *)
        END_IF;

        (* Vacuum Cascade *)
        IF bVacuumEnable THEN
            IF rVacuumPV > rTargetVacuum THEN
                (* Command Vacuum Pump *)
                rVacuumPV := rVacuumPV - 5.0; (* Simulated pump down *)
            END_IF;
        END_IF;

        (* Viscosity Tracking *)
        pidViscosity(
            ACT := rActualViscosity,
            SET := rTargetViscosity,
            SUP := 1.5,
            INT := 5.0
        );

        tonMixingTimer(IN := TRUE, PT := rMixingTimeLimit);
        IF tonMixingTimer.Q AND (ABS(rActualViscosity - rTargetViscosity) < 5.0) THEN
            nState := 40; (* Finishing *)
        END_IF;

    40: (* Finishing and Venting *)
        rAgitatorSpeedPV := rMainAgitatorSpeedSP * 0.1;
        rPlanetarySpeedPV := rPlanetarySpeedSP * 0.1;
        rVacuumPV := 1013.25; (* Venting to atmosphere *)
        IF rVacuumPV >= 1000.0 THEN
            bProcessComplete := TRUE;
            bProcessRunning := FALSE;
            nState := 0;
        END_IF;

    99: (* Fault *)
        bError := TRUE;
        bProcessRunning := FALSE;
        rAgitatorSpeedPV := 0.0;
        rPlanetarySpeedPV := 0.0;
END_CASE;
END_FUNCTION_BLOCK
