FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    rSetPress        : REAL; (* Setpoint for headbox pressure [kPa] *)
    rActPress        : REAL; (* Actual headbox pressure [kPa] *)
    rStockFlowIn     : REAL; (* Incoming stock flow rate [l/min] *)
    rSliceLipSet     : ARRAY[1..16] OF REAL; (* Target slice lip profile [mm] *)
    rSliceLipAct     : ARRAY[1..16] OF REAL; (* Actual slice lip profile [mm] *)
    rWireSpeed       : REAL; (* Wire section speed [m/min] *)
    rVacuum1Act      : REAL; (* Drainage vacuum section 1 [kPa] *)
    rSteamPressAct   : ARRAY[1..5] OF REAL; (* Steam pressure in drying cylinders 1-5 [bar] *)
    bStart           : BOOL; (* Start process *)
    bStop            : BOOL; (* Stop process *)
    bEmergencyStop   : BOOL; (* Emergency stop flag *)
END_VAR

VAR_OUTPUT
    rPumpSpeedOut    : REAL; (* Fan pump speed control 0-100% *)
    rBleedValveOut   : REAL; (* Headbox bleed valve control 0-100% *)
    rSliceLipCmd     : ARRAY[1..16] OF REAL; (* Commands to slice lip actuators *)
    rVacuum1Cmd      : REAL; (* Command to drainage vacuum pump 1 *)
    rSteamPressCmd   : ARRAY[1..5] OF REAL; (* Target steam pressure for cascade 1-5 *)
    bFault           : BOOL; (* Fault indicator *)
    iFaultCode       : INT;  (* Fault code definition *)
END_VAR

VAR
    rPressError      : REAL;
    rPressIntegral   : REAL := 0.0;
    rPressDerivative : REAL := 0.0;
    rPressLastErr    : REAL := 0.0;
    rKp_Press        : REAL := 2.5;
    rKi_Press        : REAL := 0.8;
    rKd_Press        : REAL := 0.1;
    rJetToWireRatio  : REAL;

    i                : INT;
    rProfileErr      : REAL;
    rProfileKp       : REAL := 1.2;
    rSteamKp         : REAL := 0.5;

    tUpdateTimer     : TON;
END_VAR

(* Implementation *)
IF bEmergencyStop THEN
    rPumpSpeedOut := 0.0;
    rBleedValveOut := 100.0; (* Fully open bleed to drop pressure rapidly *)
    rVacuum1Cmd := 0.0;
    FOR i := 1 TO 16 DO rSliceLipCmd[i] := 0.0; END_FOR;
    FOR i := 1 TO 5 DO rSteamPressCmd[i] := 0.0; END_FOR;
    bFault := TRUE;
    iFaultCode := 99; (* Emergency stop code *)
    RETURN;
END_IF

IF bStop THEN
    rPumpSpeedOut := 0.0;
    bFault := FALSE;
    iFaultCode := 0;
    RETURN;
END_IF

IF bStart THEN
    tUpdateTimer(IN:=NOT tUpdateTimer.Q, PT:=T#50MS);

    IF tUpdateTimer.Q THEN
        (* Headbox Pressure PID Control *)
        rPressError := rSetPress - rActPress;
        rPressIntegral := rPressIntegral + (rPressError * 0.05);
        rPressDerivative := (rPressError - rPressLastErr) / 0.05;
        rPressLastErr := rPressError;

        rPumpSpeedOut := (rKp_Press * rPressError) + (rKi_Press * rPressIntegral) + (rKd_Press * rPressDerivative);

        (* Limit fan pump output *)
        IF rPumpSpeedOut > 100.0 THEN rPumpSpeedOut := 100.0; END_IF;
        IF rPumpSpeedOut < 0.0 THEN rPumpSpeedOut := 0.0; END_IF;

        (* Slice Lip Profile Control (Cross Direction) *)
        FOR i := 1 TO 16 DO
            rProfileErr := rSliceLipSet[i] - rSliceLipAct[i];
            rSliceLipCmd[i] := rSliceLipAct[i] + (rProfileKp * rProfileErr);
            (* Saturation limit *)
            IF rSliceLipCmd[i] > 20.0 THEN rSliceLipCmd[i] := 20.0; END_IF;
            IF rSliceLipCmd[i] < 0.0 THEN rSliceLipCmd[i] := 0.0; END_IF;
        END_FOR;

        (* Calculate Jet-to-Wire ratio estimation based on pressure and speed *)
        IF rWireSpeed > 0 THEN
            rJetToWireRatio := (SQRT(rActPress * 1000.0) * 0.141) / rWireSpeed;
        ELSE
            rJetToWireRatio := 0.0;
        END_IF;

        (* Drainage vacuum cascading control *)
        rVacuum1Cmd := LIMIT(10.0, rWireSpeed * 0.2 + (rJetToWireRatio * 5.0), 80.0);

        (* Multi-cylinder steam drying cascades based on stock flow and speed *)
        FOR i := 1 TO 5 DO
            rSteamPressCmd[i] := LIMIT(0.5, (rWireSpeed * 0.005) + (rStockFlowIn * 0.001) * INT_TO_REAL(i), 12.0);
        END_FOR;

        (* Fault Detection *)
        IF rActPress > 150.0 THEN
            bFault := TRUE;
            iFaultCode := 1; (* Overpressure *)
        ELSIF rActPress < 10.0 AND rPumpSpeedOut > 90.0 THEN
            bFault := TRUE;
            iFaultCode := 2; (* Pump maxed but pressure low *)
        ELSE
            bFault := FALSE;
            iFaultCode := 0;
        END_IF;
    END_IF;
END_IF
END_FUNCTION_BLOCK\n```
