```iec-st
FUNCTION_BLOCK fb_HPP_Pasteurization_Controller
TITLE = 'High-Pressure Processing (HPP) Pasteurization Controller'
AUTHOR : 'Lumina Elite Data Architect'
VERSION : '1.0'

(*
    HPP Pasteurization Controller
    Specifications:
    - Ultra-high pressure target: 87,000 PSI (approx 6,000 bar)
    - Sequential staging of redundant intensifier pumps
    - Critical decompression rate profiling
    - Safety interlocks for vessel plug and locking ring
*)

VAR_INPUT
    bStart_Process          : BOOL;           // Command to start pasteurization cycle
    bEmergency_Stop         : BOOL;           // E-Stop (Fail-safe)
    rCurrent_Pressure_PSI   : REAL;           // Feedback from high-pressure transducer
    bPlug_Inserted          : BOOL;           // Proximity sensor: Vessel plug seated
    bLocking_Ring_Closed    : BOOL;           // Proximity sensor: Ring rotated and locked
    bLocking_Pin_Engaged    : BOOL;           // Mechanical pin verification
    rTarget_Hold_Time_Sec   : REAL := 180.0;  // Standard 3-minute hold time
    rTarget_Pressure_PSI    : REAL := 87000.0;// Standard operating pressure
END_VAR

VAR_OUTPUT
    bIntensifier_Pump_1     : BOOL;           // Primary pump enable
    bIntensifier_Pump_2     : BOOL;           // Secondary/Booster pump enable
    rDecompression_Valve_Cmd: REAL;           // 0.0 - 100.0% analog control
    bLocking_Ring_Open_Cmd  : BOOL;           // Command to actuate locking ring
    bSystem_Ready           : BOOL;           // Ready to process
    bCycle_Complete         : BOOL;           // Process successful
    bAlarm_Interlock_Fault  : BOOL;           // Safety interlock failure
    bAlarm_Over_Pressure    : BOOL;           // Pressure exceeded safety limit
    bAlarm_Decomp_Fault     : BOOL;           // Decompression profile tracking error
    iProcess_State          : INT;            // Current state machine step
END_VAR

VAR
    timer_Hold_Time         : TON;            // Pasteurization hold timer
    timer_Pump_Stage        : TON;            // Delay between intensifier start
    timer_Cycle             : TON;            // Overall cycle watchdog

    rDecomp_Rate_Setpoint   : REAL;           // PSI/sec target drop rate
    rExpected_Pressure      : REAL;           // Profile tracking variable

    // Constants
    cMax_Pressure_PSI       : REAL := 92000.0; // Over-pressure trip
    cDecomp_Initial_Drop    : REAL := 15000.0; // Fast drop limit (PSI)
    cDecomp_Slow_Rate       : REAL := 2500.0;  // PSI/sec to prevent explosion
    cUpdate_Interval_Sec    : REAL := 0.1;     // Scan cycle reference
END_VAR

BEGIN
    // =========================================================================
    // SAFETY & INTERLOCKS
    // =========================================================================
    IF bEmergency_Stop OR rCurrent_Pressure_PSI > cMax_Pressure_PSI THEN
        bIntensifier_Pump_1 := FALSE;
        bIntensifier_Pump_2 := FALSE;
        rDecompression_Valve_Cmd := 100.0; // Fail open for decompression
        bAlarm_Over_Pressure := (rCurrent_Pressure_PSI > cMax_Pressure_PSI);
        iProcess_State := 99; // Fault state
        RETURN;
    END_IF;

    bSystem_Ready := (bPlug_Inserted AND bLocking_Ring_Closed AND bLocking_Pin_Engaged AND rCurrent_Pressure_PSI < 50.0);

    // =========================================================================
    // STATE MACHINE
    // =========================================================================
    // 0: IDLE
    // 10: PRE-FILL & SEAL VERIFICATION
    // 20: PRESSURIZATION - STAGE 1
    // 30: PRESSURIZATION - STAGE 2
    // 40: HOLD TIMER
    // 50: DECOMPRESSION - FAST BLOWDOWN
    // 60: DECOMPRESSION - CONTROLLED PROFILE
    // 70: COMPLETION & UNLOCK
    // 99: FAULT

    CASE iProcess_State OF
        0: // IDLE
            bIntensifier_Pump_1 := FALSE;
            bIntensifier_Pump_2 := FALSE;
            rDecompression_Valve_Cmd := 100.0; 
            bCycle_Complete := FALSE;
            bLocking_Ring_Open_Cmd := TRUE; // Keep open until cycle starts

            IF bStart_Process AND bSystem_Ready THEN
                iProcess_State := 10;
                bLocking_Ring_Open_Cmd := FALSE;
            ELSIF bStart_Process AND NOT bSystem_Ready THEN
                bAlarm_Interlock_Fault := TRUE;
            END_IF;

        10: // PRE-FILL & SEAL VERIFICATION
            rDecompression_Valve_Cmd := 0.0; // Close vent
            IF bPlug_Inserted AND bLocking_Ring_Closed AND bLocking_Pin_Engaged THEN
                iProcess_State := 20;
            ELSE
                bAlarm_Interlock_Fault := TRUE;
                iProcess_State := 99;
            END_IF;

        20: // PRESSURIZATION - STAGE 1 (Primary Intensifier)
            bIntensifier_Pump_1 := TRUE;

            // Wait until intermediate pressure is reached to start booster
            IF rCurrent_Pressure_PSI > 45000.0 THEN
                timer_Pump_Stage(IN:=TRUE, PT:=T#2S); // Prevent hydraulic shock
                IF timer_Pump_Stage.Q THEN
                    iProcess_State := 30;
                    timer_Pump_Stage(IN:=FALSE);
                END_IF;
            END_IF;

        30: // PRESSURIZATION - STAGE 2 (Booster Intensifier)
            bIntensifier_Pump_2 := TRUE;

            IF rCurrent_Pressure_PSI >= rTarget_Pressure_PSI THEN
                bIntensifier_Pump_1 := FALSE; // Optional: maintain pressure with small makeup valve
                bIntensifier_Pump_2 := FALSE;
                timer_Hold_Time(IN:=FALSE); // Reset timer
                iProcess_State := 40;
            END_IF;

        40: // HOLD TIMER
            timer_Hold_Time(IN:=TRUE, PT:=REAL_TO_TIME(rTarget_Hold_Time_Sec * 1000.0));

            // Pressure maintenance (Makeup)
            IF rCurrent_Pressure_PSI < (rTarget_Pressure_PSI - 2000.0) THEN
                bIntensifier_Pump_1 := TRUE;
            ELSIF rCurrent_Pressure_PSI >= rTarget_Pressure_PSI THEN
                bIntensifier_Pump_1 := FALSE;
            END_IF;

            IF timer_Hold_Time.Q THEN
                bIntensifier_Pump_1 := FALSE;
                bIntensifier_Pump_2 := FALSE;
                rExpected_Pressure := rCurrent_Pressure_PSI; // Initialize decompression profile
                iProcess_State := 50;
            END_IF;

        50: // DECOMPRESSION - FAST BLOWDOWN (Adiabatic shock)
            // Initial rapid drop to save time before critical expansion zone
            rDecompression_Valve_Cmd := 40.0; 

            IF rCurrent_Pressure_PSI < (rTarget_Pressure_PSI - cDecomp_Initial_Drop) THEN
                iProcess_State := 60;
                rExpected_Pressure := rCurrent_Pressure_PSI;
            END_IF;

        60: // DECOMPRESSION - CONTROLLED PROFILE
            // Prevents package delamination / explosion
            rExpected_Pressure := rExpected_Pressure - (cDecomp_Slow_Rate * cUpdate_Interval_Sec);

            // PI-like valve control based on profile tracking
            IF rCurrent_Pressure_PSI > rExpected_Pressure THEN
                rDecompression_Valve_Cmd := MIN(rDecompression_Valve_Cmd + 1.0, 100.0);
            ELSIF rCurrent_Pressure_PSI < rExpected_Pressure THEN
                rDecompression_Valve_Cmd := MAX(rDecompression_Valve_Cmd - 1.0, 5.0);
            END_IF;

            IF rCurrent_Pressure_PSI < 150.0 THEN
                rDecompression_Valve_Cmd := 100.0; // Fully open at bottom
                iProcess_State := 70;
            END_IF;

        70: // COMPLETION & UNLOCK
            bCycle_Complete := TRUE;

            // Redundant check before unlock
            IF rCurrent_Pressure_PSI < 20.0 THEN
                bLocking_Ring_Open_Cmd := TRUE; // Allow operator to open vessel
            END_IF;

            IF NOT bStart_Process THEN
                iProcess_State := 0; // Reset for next batch
            END_IF;

        99: // FAULT
            bIntensifier_Pump_1 := FALSE;
            bIntensifier_Pump_2 := FALSE;
            rDecompression_Valve_Cmd := 100.0;
            IF NOT bEmergency_Stop AND NOT bStart_Process THEN
                // Acknowledge fault
                bAlarm_Interlock_Fault := FALSE;
                bAlarm_Over_Pressure := FALSE;
                iProcess_State := 0;
            END_IF;
    END_CASE;

END_FUNCTION_BLOCK
