FUNCTION_BLOCK FB_DeepSeaMicrobialFermentor
VAR_INPUT
    (* System & Safety Control Signals *)
    bEnable                : BOOL;      (* Master system enable for hydrothermal vent fermentor sequence *)
    bEmergencyStop         : BOOL;      (* Hardwired safety interlock - Hyperbaric blowout preventer status *)
    bReset                 : BOOL;      (* Fault reset acknowledgment *)

    (* Process Variable (PV) Measurements from Hyperbaric Sensors *)
    rVesselPressure        : REAL;      (* In-situ hyperbaric vessel pressure [Bar], target: 400.0 Bar *)
    rVentFluidTemp         : REAL;      (* Input vent fluid temperature [DegC], extremophile range: 120.0 - 400.0 DegC *)
    rRedoxPotential        : REAL;      (* Oxidation-reduction potential of the culture [mV] *)
    rHeavyMetalConc        : REAL;      (* Heavy metal toxicity level (e.g., Cu, Fe, Zn) [ppm] *)
    bRedoxSensorValid      : BOOL;      (* Validation signal for redox ORP probe operating at extreme depth/pressure *)
END_VAR

VAR_OUTPUT
    (* System Status Flags *)
    bSystemReady           : BOOL;      (* True when vessel is fully pressurized, stable, and ready for cultivation *)
    bAlarmCritical         : BOOL;      (* Critical fault detected (e.g., structural limits exceeded, sensor failure) *)
    iSystemState           : INT;       (* Current state of the sequencer [0=IDLE, 10=PRESSURIZING, 20=TOXICITY_CTL, 30=CULTIVATION, 99=FAULT] *)

    (* Actuator Commands (Manipulated Variables) *)
    rPressurizationValve   : REAL;      (* Variable VFD command [0.0 - 100.0%] to hyperbaric booster pump *)
    rToxicitySuppressorDose: REAL;      (* Flow rate for chelating agent injection [mL/min] to suppress heavy metal toxicity *)
    rVentHeaterPWM         : REAL;      (* Power duty cycle for induction heater [0.0 - 100.0%] to maintain thermophile temp *)
END_VAR

VAR
    (* Internal State & Memory Variables *)
    iState                 : INT := 0;      (* State Machine Index *)
    rPrevPressure          : REAL := 0.0;
    tPressurizationTimer   : TON;           (* Delay timer for pressure stabilization *)
    tHoldTimer             : TON;           (* Incubation hold timer *)

    (* Cascaded Control Tuning Parameters *)
    rKp_Pressure           : REAL := 2.5;
    rKi_Pressure           : REAL := 0.05;
    rErr_Pressure          : REAL := 0.0;
    rIntegral_Pressure     : REAL := 0.0;
    rTargetPressure        : REAL := 400.0; (* 400 Bar hyperbaric setpoint *)

    rChelateRatio          : REAL := 1.25;  (* Multiplier for toxicity dosing based on HeavyMetalConc *)
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlock Processing *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarmCritical := TRUE;
    rPressurizationValve := 0.0;
    rToxicitySuppressorDose := 0.0;
    rVentHeaterPWM := 0.0;
    iState := 99; (* Transition to Hard Fault State *)
    RETURN;
END_IF;

(* Extreme Over-Pressure Protection *)
IF rVesselPressure > 420.0 THEN
    bAlarmCritical := TRUE;
    rPressurizationValve := 0.0;
    iState := 99;
END_IF;

(* Main State Machine (Sequencer) *)
CASE iState OF
    0: (* IDLE - Await Enable Signal *)
        bSystemReady := FALSE;
        bAlarmCritical := FALSE;
        rPressurizationValve := 0.0;
        rToxicitySuppressorDose := 0.0;
        rVentHeaterPWM := 0.0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* PRESSURIZING - Ramp up to 400 Bar Hyperbaric Condition *)
        (* Simple PI Control Loop for Pressurization Pump *)
        rErr_Pressure := rTargetPressure - rVesselPressure;
        rIntegral_Pressure := rIntegral_Pressure + (rErr_Pressure * 0.1); (* 100ms cycle time assumption *)

        (* Anti-windup for integral component *)
        IF rIntegral_Pressure > 50.0 THEN rIntegral_Pressure := 50.0; END_IF;
        IF rIntegral_Pressure < -50.0 THEN rIntegral_Pressure := -50.0; END_IF;

        rPressurizationValve := (rKp_Pressure * rErr_Pressure) + (rKi_Pressure * rIntegral_Pressure);

        (* Clamp output to 0-100% *)
        IF rPressurizationValve > 100.0 THEN rPressurizationValve := 100.0; END_IF;
        IF rPressurizationValve < 0.0 THEN rPressurizationValve := 0.0; END_IF;

        (* Stabilization Check *)
        IF (rVesselPressure >= 398.0) AND (rVesselPressure <= 402.0) THEN
            tPressurizationTimer(IN := TRUE, PT := T#30S);
            IF tPressurizationTimer.Q THEN
                tPressurizationTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tPressurizationTimer(IN := FALSE);
        END_IF;

    20: (* TOXICITY_CTL - In-Situ Heavy Metal Suppression & Redox Control *)
        (* Continuously maintain pressure while adjusting chemical balances *)
        rPressurizationValve := 10.0; (* Maintenance holding flow *)

        (* Calculate Chelating Agent Dosing based on real-time heavy metal detection *)
        IF rHeavyMetalConc > 15.0 THEN
            rToxicitySuppressorDose := rHeavyMetalConc * rChelateRatio;
        ELSE
            rToxicitySuppressorDose := 0.0;
        END_IF;

        (* Validate ORP Sensor before proceeding to Cultivation Phase *)
        IF bRedoxSensorValid AND (rRedoxPotential < -200.0) THEN
            iState := 30;
        END_IF;

    30: (* CULTIVATION - Deep-Sea Thermophile Archaea Growth Phase *)
        bSystemReady := TRUE;

        (* Induction Heater Control based on Vent Fluid Temp *)
        IF rVentFluidTemp < 350.0 THEN
            rVentHeaterPWM := 65.5; (* High duty cycle for primary heating *)
        ELSIF rVentFluidTemp > 380.0 THEN
            rVentHeaterPWM := 0.0;
        ELSE
            rVentHeaterPWM := 25.0; (* Steady state maintenance *)
        END_IF;

        (* Graceful Shutdown on Disable *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT STATE *)
        rPressurizationValve := 0.0;
        rToxicitySuppressorDose := 0.0;
        rVentHeaterPWM := 0.0;

        IF bReset AND NOT bAlarmCritical THEN
            iState := 0;
        END_IF;

END_CASE;

(* Output the current state for telemetry / HMI monitoring *)
iSystemState := iState;

END_FUNCTION_BLOCK
