FUNCTION_BLOCK FB_MOCVD_AdvancedControl
VAR_INPUT
    bEnable                 : BOOL;   (* Enable MOCVD Process *)
    bEmergencyStop          : BOOL;   (* E-Stop condition *)
    rSetPointTempSusceptor  : REAL;   (* Target Susceptor Temperature [degC] *)
    rActualTempSusceptor    : REAL;   (* Actual Susceptor Temperature [degC] *)
    rSetPointPressBubbler   : REAL;   (* Target Bubbler Pressure [Torr] *)
    rActualPressBubbler     : REAL;   (* Actual Bubbler Pressure [Torr] *)
    rTMGaFlowTarget         : REAL;   (* Trimethylgallium flow target [sccm] *)
    rNH3FlowTarget          : REAL;   (* Ammonia flow target [sccm] *)
    tALD_PulseTime          : TIME;   (* ALD Pulse Duration *)
    tALD_PurgeTime          : TIME;   (* ALD Purge Duration *)
    nALD_Cycles             : INT;    (* Number of ALD cycles *)
END_VAR

VAR_OUTPUT
    bHeatingEnable          : BOOL;   (* RF Generator enable for induction heating *)
    rRF_PowerCommand        : REAL;   (* RF Power Output 0-100% *)
    bBubblerValveOpen       : BOOL;   (* TMGa bubbler carrier gas valve *)
    rMFC_TMGa_Command       : REAL;   (* MFC setpoint for TMGa *)
    rMFC_NH3_Command        : REAL;   (* MFC setpoint for NH3 *)
    bProcessComplete        : BOOL;   (* Sequence complete flag *)
    bError                  : BOOL;   (* Fault detection flag *)
    iErrorCode              : INT;    (* Error ID *)
END_VAR

VAR
    (* Internal PID variables for Temperature *)
    rTempError              : REAL;
    rTempIntegral           : REAL;
    rTempDerivative         : REAL;
    rTempLastError          : REAL;
    rKp_Temp                : REAL := 2.5;
    rKi_Temp                : REAL := 0.05;
    rKd_Temp                : REAL := 0.1;

    (* Internal PID variables for Pressure *)
    rPressError             : REAL;
    rPressIntegral          : REAL;
    rPressDerivative        : REAL;
    rPressLastError         : REAL;
    rKp_Press               : REAL := 1.2;
    rKi_Press               : REAL := 0.1;

    (* ALD State Machine *)
    iState                  : INT := 0;
    nCurrentCycle           : INT := 0;
    fbTimerProcess          : TON;

    (* Constants *)
    TEMP_TOLERANCE          : REAL := 0.5;
    PRESS_TOLERANCE         : REAL := 0.1;
END_VAR

(* Implementation *)
IF bEmergencyStop THEN
    bHeatingEnable := FALSE;
    rRF_PowerCommand := 0.0;
    bBubblerValveOpen := FALSE;
    rMFC_TMGa_Command := 0.0;
    rMFC_NH3_Command := 0.0;
    bError := TRUE;
    iErrorCode := 999;
    iState := 0;
    RETURN;
END_IF;

IF NOT bEnable THEN
    bHeatingEnable := FALSE;
    rRF_PowerCommand := 0.0;
    bBubblerValveOpen := FALSE;
    rMFC_TMGa_Command := 0.0;
    rMFC_NH3_Command := 0.0;
    bProcessComplete := FALSE;
    iState := 0;
    RETURN;
END_IF;

(* Temperature Control - Cascade Induction Heating *)
rTempError := rSetPointTempSusceptor - rActualTempSusceptor;
rTempIntegral := rTempIntegral + rTempError;
rTempDerivative := rTempError - rTempLastError;
rTempLastError := rTempError;

rRF_PowerCommand := (rKp_Temp * rTempError) + (rKi_Temp * rTempIntegral) + (rKd_Temp * rTempDerivative);

IF rRF_PowerCommand > 100.0 THEN
    rRF_PowerCommand := 100.0;
ELSIF rRF_PowerCommand < 0.0 THEN
    rRF_PowerCommand := 0.0;
END_IF;

IF rRF_PowerCommand > 5.0 THEN
    bHeatingEnable := TRUE;
ELSE
    bHeatingEnable := FALSE;
END_IF;

(* Pressure Control - Bubbler Carrier Gas *)
rPressError := rSetPointPressBubbler - rActualPressBubbler;
rPressIntegral := rPressIntegral + rPressError;
rPressDerivative := rPressError - rPressLastError;
rPressLastError := rPressError;

(* ALD Sequence State Machine *)
CASE iState OF
    0: (* Wait for steady state temperature and pressure *)
        IF (ABS(rTempError) < TEMP_TOLERANCE) AND (ABS(rPressError) < PRESS_TOLERANCE) THEN
            iState := 10;
            nCurrentCycle := 0;
        END_IF;

    10: (* TMGa Pulse - Gallium Deposition *)
        bBubblerValveOpen := TRUE;
        rMFC_TMGa_Command := rTMGaFlowTarget;
        rMFC_NH3_Command := 0.0;
        fbTimerProcess(IN := TRUE, PT := tALD_PulseTime);
        IF fbTimerProcess.Q THEN
            fbTimerProcess(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* Purge 1 *)
        bBubblerValveOpen := FALSE;
        rMFC_TMGa_Command := 0.0;
        rMFC_NH3_Command := 0.0;
        fbTimerProcess(IN := TRUE, PT := tALD_PurgeTime);
        IF fbTimerProcess.Q THEN
            fbTimerProcess(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* NH3 Pulse - Nitrogen Deposition *)
        bBubblerValveOpen := FALSE;
        rMFC_TMGa_Command := 0.0;
        rMFC_NH3_Command := rNH3FlowTarget;
        fbTimerProcess(IN := TRUE, PT := tALD_PulseTime);
        IF fbTimerProcess.Q THEN
            fbTimerProcess(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* Purge 2 *)
        bBubblerValveOpen := FALSE;
        rMFC_TMGa_Command := 0.0;
        rMFC_NH3_Command := 0.0;
        fbTimerProcess(IN := TRUE, PT := tALD_PurgeTime);
        IF fbTimerProcess.Q THEN
            fbTimerProcess(IN := FALSE);
            nCurrentCycle := nCurrentCycle + 1;
            IF nCurrentCycle >= nALD_Cycles THEN
                iState := 50;
            ELSE
                iState := 10;
            END_IF;
        END_IF;

    50: (* Process Complete *)
        bProcessComplete := TRUE;
        bHeatingEnable := FALSE;
        rRF_PowerCommand := 0.0;
        bBubblerValveOpen := FALSE;
        rMFC_TMGa_Command := 0.0;
        rMFC_NH3_Command := 0.0;

    ELSE
        bError := TRUE;
        iErrorCode := 100;
END_CASE;

END_FUNCTION_BLOCK
