    bPump_Failover_Active : BOOL;
    bLeak_Isolation_Tripped : BOOL;
END_VAR

VAR
    // Internal State
    nPump_State : INT := 0; // 0=Init, 1=A_Lead, 2=B_Lead, 3=Transition, 4=Fault
    rMax_CPU_Temp : REAL;
    rTarget_Flow_LPM : REAL;
    rFlow_Error : REAL;
    rFlow_Integral : REAL;
    rFlow_Kp : REAL := 2.5;
    rFlow_Ki : REAL := 0.15;
    rFlow_Kd : REAL := 0.05;
    rPrev_Flow_Error : REAL;

    // Timers
    tFailover_Delay : TON;
    tThrottling_Delay : TON;
    tLeak_Debounce : TON;

    // Constants
    MAX_SAFE_TEMP : REAL := 75.0;
    CRITICAL_TEMP : REAL := 88.0;
    NOMINAL_PRESSURE : REAL := 3.5;
END_VAR

// Logic implementation
// 1. Safety and Interlocks
tLeak_Debounce(IN := bLeak_Detected_Rack OR bLeak_Detected_Manifold, PT := T#2S);
IF tLeak_Debounce.Q OR bEmergency_Stop THEN
    bLeak_Isolation_Tripped := TRUE;
    rPumpA_Speed_Ref_Pct := 0.0;
    rPumpB_Speed_Ref_Pct := 0.0;
    rProportional_Valve_Pos_Pct := 0.0;
    bChiller1_Enable := FALSE;
    bChiller2_Enable := FALSE;
    bCritical_OverTemp_Trip := TRUE; // Force server shutdown immediately on leak
    RETURN;
END_IF;

// 2. Thermal Monitoring & Throttling
rMax_CPU_Temp := MAX(rCPU1_Temp_C, rCPU2_Temp_C);
rMax_CPU_Temp := MAX(rMax_CPU_Temp, rASIC_Array_Temp_C);

IF rMax_CPU_Temp > CRITICAL_TEMP THEN
    bCritical_OverTemp_Trip := TRUE;
ELSE
    bCritical_OverTemp_Trip := FALSE;
END_IF;

tThrottling_Delay(IN := (rMax_CPU_Temp > MAX_SAFE_TEMP), PT := T#5S);
bThermal_Throttling_Req := tThrottling_Delay.Q;

// 3. Pump Redundancy State Machine
CASE nPump_State OF
    0: // Init
        IF NOT bPumpA_Fault THEN
            nPump_State := 1;
        ELSIF NOT bPumpB_Fault THEN
            nPump_State := 2;
        END_IF;

    1: // Pump A Lead
        bPump_Failover_Active := FALSE;
        rPumpA_Speed_Ref_Pct := 80.0; // Base speed, normally modulated by pressure PID
        rPumpB_Speed_Ref_Pct := 0.0;
        IF bPumpA_Fault OR (NOT bPumpA_Running AND rPrimary_Header_Pressure_Bar < 1.0) THEN
            nPump_State := 3; // Initiate failover
            tFailover_Delay(IN := FALSE);
        END_IF;

    2: // Pump B Lead
        bPump_Failover_Active := FALSE;
        rPumpA_Speed_Ref_Pct := 0.0;
        rPumpB_Speed_Ref_Pct := 80.0;
        IF bPumpB_Fault OR (NOT bPumpB_Running AND rPrimary_Header_Pressure_Bar < 1.0) THEN
            nPump_State := 3;
            tFailover_Delay(IN := FALSE);
        END_IF;

    3: // Transition / Failover
        bPump_Failover_Active := TRUE;
        tFailover_Delay(IN := TRUE, PT := T#3S);
        IF tFailover_Delay.Q THEN
            IF bPumpA_Fault AND NOT bPumpB_Fault THEN
                nPump_State := 2;
            ELSIF bPumpB_Fault AND NOT bPumpA_Fault THEN
                nPump_State := 1;
            ELSE
                nPump_State := 4; // Total pump failure
            END_IF;
        END_IF;

    4: // Total Failure
        bThermal_Throttling_Req := TRUE;
        bCritical_OverTemp_Trip := TRUE; // Needs OS shutdown
        rPumpA_Speed_Ref_Pct := 0.0;
        rPumpB_Speed_Ref_Pct := 0.0;
END_CASE;

// 4. Microchannel Proportional Valve PID (Flow Control based on Temp)
// Cascade control: Temperature error determines target flow, target flow sets valve position
rTarget_Flow_LPM := 10.0 + (rMax_CPU_Temp - 40.0) * 0.5;
IF rTarget_Flow_LPM > 40.0 THEN rTarget_Flow_LPM := 40.0; END_IF;
IF rTarget_Flow_LPM < 10.0 THEN rTarget_Flow_LPM := 10.0; END_IF;

rFlow_Error := rTarget_Flow_LPM - rMicrochannel_Flow_LPM;
rFlow_Integral := rFlow_Integral + (rFlow_Error * 0.1); // Assuming 100ms cycle
// Anti-windup
IF rFlow_Integral > 100.0 THEN rFlow_Integral := 100.0; END_IF;
IF rFlow_Integral < 0.0 THEN rFlow_Integral := 0.0; END_IF;

rProportional_Valve_Pos_Pct := (rFlow_Kp * rFlow_Error) + rFlow_Integral + (rFlow_Kd * (rFlow_Error - rPrev_Flow_Error));
IF rProportional_Valve_Pos_Pct > 100.0 THEN rProportional_Valve_Pos_Pct := 100.0; END_IF;
IF rProportional_Valve_Pos_Pct < 0.0 THEN rProportional_Valve_Pos_Pct := 0.0; END_IF;
rPrev_Flow_Error := rFlow_Error;

// 5. Chiller Cascade
rChiller_SetPoint_C := 18.0; // Nominal high-density direct chip setpoint
IF rMax_CPU_Temp > (MAX_SAFE_TEMP - 5.0) THEN
    rChiller_SetPoint_C := 15.0; // Pre-cool aggressive
END_IF;

bChiller1_Enable := bChiller1_Available AND (rMax_CPU_Temp > 30.0);
// Stage Chiller 2 if secondary return temp remains high
bChiller2_Enable := bChiller2_Available AND (rSecondary_Return_Temp_C > 25.0);

END_FUNCTION_BLOCK
```

