FUNCTION_BLOCK FB_BlastFurnace_Breadth
VAR_INPUT
    TuyereFlowRate_SP, TuyereFlowRate_PV : REAL;
    TopGasPressure_SP, TopGasPressure_PV : REAL;
    BlastTemp_SP, BlastTemp_PV : REAL;
    PN_Status : "UDT_Profinet_Status";
    Kp, Ki, CycleTime : REAL; 
    StoveHeatingMode : BOOL;
END_VAR
VAR_OUTPUT
    TuyereValvePos : REAL; 
    TopGasValvePos : REAL; 
    ColdBlastValvePos, HotBlastValvePos, GasBurnerValvePos : REAL;
    SystemFault : BOOL;
    FaultCode : INT; // 0=OK, 1=PN_Loss, 2=Sensor_High, 3=Sensor_Low
END_VAR
VAR
    Tuyere_Int, TopGas_Int, BlastTemp_Int : REAL := 0.0;
END_VAR

BEGIN
    SystemFault := FALSE;
    FaultCode := 0;

    // Diagnostics
    IF PN_Status.ConnectionLost OR PN_Status.HardwareError THEN
        SystemFault := TRUE;
        FaultCode := 1;
        TuyereValvePos := 0.0;
        TopGasValvePos := 0.0;
        RETURN; // Safety shutdown
    END_IF;

    IF TuyereFlowRate_PV < 0.0 OR TopGasPressure_PV < 0.0 THEN
        SystemFault := TRUE; FaultCode := 3; RETURN;
    ELSIF TuyereFlowRate_PV > 50000.0 THEN
        SystemFault := TRUE; FaultCode := 2; RETURN;
    END_IF;

    // Control logic
    Tuyere_Int := Tuyere_Int + ((TuyereFlowRate_SP - TuyereFlowRate_PV) * CycleTime);
    TuyereValvePos := LIMIT(MN:=0.0, IN:=(Kp * (TuyereFlowRate_SP - TuyereFlowRate_PV)) + (Ki * Tuyere_Int), MX:=100.0);

    TopGas_Int := TopGas_Int + ((TopGasPressure_SP - TopGasPressure_PV) * CycleTime);
    TopGasValvePos := LIMIT(MN:=0.0, IN:=(Kp * (TopGasPressure_SP - TopGasPressure_PV)) + (Ki * TopGas_Int), MX:=100.0);

    IF StoveHeatingMode THEN
        GasBurnerValvePos := 100.0; HotBlastValvePos := 0.0; ColdBlastValvePos := 0.0;
    ELSE
        GasBurnerValvePos := 0.0; HotBlastValvePos := 100.0;
        BlastTemp_Int := BlastTemp_Int + ((BlastTemp_SP - BlastTemp_PV) * CycleTime);
        ColdBlastValvePos := LIMIT(MN:=0.0, IN:=(Kp * (BlastTemp_SP - BlastTemp_PV)) + (Ki * BlastTemp_Int), MX:=100.0);
    END_IF;
END_FUNCTION_BLOCK
