FUNCTION_BLOCK "WindTunnel_Mutation4"
VAR_INPUT
    Start_Cmd : Bool;
    SCADA_Heartbeat : Bool;
    User_Role : Int;
    Setpoint_Mach : Real;
    Actual_Mach_Primary : Real;
    Actual_Mach_Redundant : Real;
    Diff_Pressure : Real;
    HIL_Expected_Pitch : Real;
    Self_Test_Enable : Bool;
END_VAR
VAR_OUTPUT
    Fan_Pitch_Cmd : Real;
    Stator_Vane_Angle : Real;
    State : Int; // 0=Off, 1=SelfTest, 2=Running, 3=Degraded, 4=Fault
    Sensor_Drift_Alarm : Bool;
END_VAR
VAR
    Mach_PID : "PID_Compact";
    Stator_PID : "PID_Compact";
    Mach_Diff : Real;
    Active_Mach : Real;
END_VAR

BEGIN
    Mach_Diff := ABS(Actual_Mach_Primary - Actual_Mach_Redundant);

    IF Mach_Diff > (0.02 * Actual_Mach_Primary) THEN
        Sensor_Drift_Alarm := TRUE;
        Active_Mach := Actual_Mach_Redundant; // Graceful degradation
        State := 3;
    ELSE
        Sensor_Drift_Alarm := FALSE;
        Active_Mach := Actual_Mach_Primary;
    END_IF;

    IF Self_Test_Enable AND State = 0 THEN
        State := 1;
        Fan_Pitch_Cmd := 10.0; // Test pulse
        IF ABS(Fan_Pitch_Cmd - HIL_Expected_Pitch) > 5.0 THEN
            State := 4; // Fail self-test
        ELSE
            State := 0; // Test passed
        END_IF;
    END_IF;

    IF State <> 4 AND State <> 1 AND Start_Cmd AND User_Role > 0 THEN
        IF State <> 3 THEN State := 2; END_IF;
        Mach_PID(Setpoint := Setpoint_Mach, Input := Active_Mach, Output => Fan_Pitch_Cmd);
        Stator_PID(Setpoint := 50.0, Input := Diff_Pressure, Output => Stator_Vane_Angle);
    ELSIF State <> 1 THEN
        Fan_Pitch_Cmd := 0.0;
        Stator_Vane_Angle := 0.0;
        IF NOT Start_Cmd AND State <> 4 THEN State := 0; END_IF;
    END_IF;
END_FUNCTION_BLOCK
