FUNCTION_BLOCK FB_WasteIncinerator_M4
TITLE = 'Waste Incinerator Control with Adversarial Features'
VERSION : '1.0'
AUTHOR : 'AI'

VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    FuelFlowRate : REAL;
    AirFlowRate : REAL;
    TargetStoichRatio : REAL;
    FlueGasSO2 : REAL;
    TargetSO2 : REAL;
    TurbineTempPV : REAL;
    TurbineTempSP : REAL;
    ProfinetStatusNode1 : WORD;
    ProfinetStatusNode2 : WORD;
    UserRole : INT; // 0=Guest, 1=Operator, 2=Admin
    SCADA_Heartbeat_In : INT;
    RedundantPLC_Alive : BOOL;
    Primary_PLC : BOOL;
    O2_Sensor_1 : REAL; // Adversarial - redundant sensors
    O2_Sensor_2 : REAL;
    HIL_TwinMode : BOOL; // Digital twin sync mode
    SelfTestInitiate : BOOL;
END_VAR

VAR_OUTPUT
    AirValveCommand : REAL;
    ScrubberPumpCommand : REAL;
    TurbineBypassValve : REAL;
    BurnerActive : BOOL;
    ScrubberActive : BOOL;
    TurbineActive : BOOL;
    AlarmWord : DWORD;
    SCADA_Heartbeat_Out : INT;
    SyncDataToStandby : REAL;
    SelfTestComplete : BOOL;
    SelfTestResult : BOOL; // True = Pass
END_VAR

VAR
    CurrentStoichRatio : REAL;
    PID_Error : REAL;
    PID_Integral : REAL;
    CommsFault : BOOL;
    ActiveControl : BOOL;
    LastHeartbeat : INT;
    HeartbeatTimeout : INT;
    SensorDrift : REAL;
    SelfTestStep : INT;
    TestTimer : INT;
END_VAR

BEGIN
    // HIL Digital Twin Mode Bypass
    IF HIL_TwinMode THEN
        // Output deterministic test pattern for HIL loopback
        AirValveCommand := 50.0;
        ScrubberPumpCommand := 50.0;
        TurbineBypassValve := 50.0;
        AlarmWord := 16#FFFFFFFF; // Signal HIL active
        RETURN;
    END_IF;

    // Self Test Routine
    IF SelfTestInitiate AND NOT BurnerActive THEN
        CASE SelfTestStep OF
            0: 
                AirValveCommand := 10.0; 
                ScrubberPumpCommand := 10.0;
                TestTimer := 0;
                SelfTestStep := 1;
            1:
                TestTimer := TestTimer + 1;
                IF TestTimer > 100 THEN
                    IF O2_Sensor_1 > 0.0 THEN
                        SelfTestResult := TRUE;
                    ELSE
                        SelfTestResult := FALSE;
                    END_IF;
                    SelfTestComplete := TRUE;
                    SelfTestStep := 0;
                END_IF;
        END_CASE;
        RETURN;
    END_IF;

    SelfTestComplete := FALSE;

    // Sensor Drift Detection
    SensorDrift := ABS(O2_Sensor_1 - O2_Sensor_2);
    IF SensorDrift > 5.0 THEN
        AlarmWord := AlarmWord OR 16#00000020; // Sensor drift detected
    END_IF;

    // IEC 62443 RBAC Check
    IF UserRole < 1 THEN
        AlarmWord := AlarmWord OR 16#00000008; 
        RETURN; 
    END_IF;

    // SCADA Heartbeat
    IF SCADA_Heartbeat_In <> LastHeartbeat THEN
        HeartbeatTimeout := 0;
        LastHeartbeat := SCADA_Heartbeat_In;
        SCADA_Heartbeat_Out := SCADA_Heartbeat_In + 1;
    ELSE
        HeartbeatTimeout := HeartbeatTimeout + 1;
        IF HeartbeatTimeout > 100 THEN
            AlarmWord := AlarmWord OR 16#00000010; 
        END_IF;
    END_IF;

    // Failover Logic
    ActiveControl := Primary_PLC OR NOT RedundantPLC_Alive;

    // Diagnostics & Profinet Health
    CommsFault := (ProfinetStatusNode1 <> 16#0000) OR (ProfinetStatusNode2 <> 16#0000);
    IF CommsFault THEN AlarmWord := AlarmWord OR 16#00000001; END_IF;

    IF ActiveControl THEN
        IF Start AND NOT Stop AND NOT CommsFault THEN
            BurnerActive := TRUE;
            ScrubberActive := TRUE;
            TurbineActive := TRUE;
        ELSIF Stop OR CommsFault THEN
            BurnerActive := FALSE;
            ScrubberActive := FALSE;
            TurbineActive := FALSE;
        END_IF;

        IF BurnerActive THEN
            IF FuelFlowRate > 0.0 THEN
                CurrentStoichRatio := AirFlowRate / FuelFlowRate;
                AirValveCommand := AirValveCommand + (TargetStoichRatio - CurrentStoichRatio) * 0.1;
            END_IF;
        ELSE
            AirValveCommand := 0.0;
        END_IF;

        IF ScrubberActive THEN
            IF FlueGasSO2 > TargetSO2 THEN
                ScrubberPumpCommand := ScrubberPumpCommand + (FlueGasSO2 - TargetSO2) * 0.2;
            ELSE
                ScrubberPumpCommand := ScrubberPumpCommand - 0.1;
            END_IF;
            IF ScrubberPumpCommand > 100.0 THEN ScrubberPumpCommand := 100.0; END_IF;
            IF ScrubberPumpCommand < 0.0 THEN ScrubberPumpCommand := 0.0; END_IF;
        ELSE
            ScrubberPumpCommand := 0.0;
        END_IF;

        IF TurbineActive THEN
            PID_Error := TurbineTempSP - TurbineTempPV;
            PID_Integral := PID_Integral + PID_Error * 0.05;
            TurbineBypassValve := (PID_Error * 1.5) + PID_Integral;
            IF TurbineBypassValve > 100.0 THEN TurbineBypassValve := 100.0; END_IF;
            IF TurbineBypassValve < 0.0 THEN TurbineBypassValve := 0.0; END_IF;
        ELSE
            TurbineBypassValve := 100.0;
            PID_Integral := 0.0;
        END_IF;

        // Sync critical data
