FUNCTION_BLOCK FB_LH2_BunkeringTransferControl
VAR_INPUT
    (* Core Safety and Enable *)
    bSystemEnable           : BOOL;     (* Master enable for the LH2 transfer sequence *)
    bEmergencyStop          : BOOL;     (* E-stop chain OK (TRUE = OK, FALSE = Stop) *)
    bESDActivated           : BOOL;     (* Emergency Shutdown sequence triggered externally *)

    (* Cryogenic Process Variables *)
    rHoseTempKelvin         : REAL;     (* Coupling hose temperature in Kelvin (target ~20K) *)
    rFlangeTempKelvin       : REAL;     (* Receiving vessel flange temperature in Kelvin *)
    rSupplyPressureBar      : REAL;     (* LH2 Supply line pressure in bar *)
    rReturnBOGPressureBar   : REAL;     (* Boil-Off Gas return line pressure in bar *)
    rFlowRateKgS            : REAL;     (* Mass flow rate of LH2 transfer in kg/s *)

    (* Actuator Feedbacks *)
    bCouplingSecured        : BOOL;     (* Mechanical locking of bunkering hose confirmed *)
    bPurgeComplete          : BOOL;     (* Nitrogen/Helium purge sequence completed *)
END_VAR
VAR_OUTPUT
    (* Sequence Status *)
    bSystemReady            : BOOL;     (* System is ready to commence transfer *)
    bTransferActive         : BOOL;     (* LH2 transfer is currently active *)
    bCoolDownActive         : BOOL;     (* Initial cryogenic cool-down sequence active *)

    (* Control Signals *)
    rMainValveCmd           : REAL;     (* Main LH2 supply valve opening command (0.0-100.0%) *)
    rBOGCompressorCmd       : REAL;     (* BOG return compressor speed command (0.0-100.0%) *)
    bPurgeValveCmd          : BOOL;     (* Command to open purge line valve *)

    (* Alarms & Faults *)
    bThermalShockAlarm      : BOOL;     (* Flange delta-T exceeded limits *)
    bPressureAnomalyAlarm   : BOOL;     (* Supply or BOG pressure out of safe operating envelope *)
    bCriticalFault          : BOOL;     (* General critical fault requiring sequence abort *)
END_VAR
VAR
    (* Internal State Machine and Timers *)
    iSeqState               : INT := 0; (* Main state machine step *)
    tCoolDownTimer          : TON;
    tPurgeTimer             : TON;
    tStabilizationTimer     : TON;

    (* Internal Process Calculation *)
    rMaxDeltaT              : REAL := 50.0; (* Maximum allowed temp difference to avoid thermal shock *)
    rCurrentDeltaT          : REAL := 0.0;

    (* Constants *)
    c_rTargetCryoTemp       : REAL := 25.0; (* Target temperature for cool-down complete *)
    c_rMaxTransferPress     : REAL := 10.0; (* Max allowable transfer pressure *)
END_VAR

(* === SAFETY & INTERLOCK EVALUATION === *)
(* Immediate halt and fault if E-Stop drops, ESD activates, or critical anomalies occur *)
IF NOT bEmergencyStop OR bESDActivated THEN
    iSeqState := 999; (* Jump to safe abort state *)
    bCriticalFault := TRUE;
END_IF;

(* Calculate thermal shock gradient between supply hose and receiving flange *)
rCurrentDeltaT := ABS(rHoseTempKelvin - rFlangeTempKelvin);
IF rCurrentDeltaT > rMaxDeltaT THEN
    bThermalShockAlarm := TRUE;
    iSeqState := 999; (* Abort transfer to prevent flange fracture *)
ELSE
    bThermalShockAlarm := FALSE;
END_IF;

(* Pressure monitoring *)
IF rSupplyPressureBar > c_rMaxTransferPress OR rReturnBOGPressureBar > (c_rMaxTransferPress * 0.5) THEN
    bPressureAnomalyAlarm := TRUE;
    iSeqState := 999;
ELSE
    bPressureAnomalyAlarm := FALSE;
END_IF;

(* === MAIN TRANSFER STATE MACHINE === *)
CASE iSeqState OF
    0: (* STATE 0: IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bTransferActive := FALSE;
        bCoolDownActive := FALSE;
        rMainValveCmd := 0.0;
        rBOGCompressorCmd := 0.0;
        bPurgeValveCmd := FALSE;

        IF bSystemEnable AND bCouplingSecured AND bEmergencyStop THEN
            iSeqState := 10;
        END_IF;

    10: (* STATE 10: PURGING SEQUENCE *)
        (* Execute N2/He purge to remove ambient moisture and air from lines *)
        bPurgeValveCmd := TRUE;
        tPurgeTimer(IN := TRUE, PT := T#30S);

        IF tPurgeTimer.Q AND bPurgeComplete THEN
            tPurgeTimer(IN := FALSE);
            bPurgeValveCmd := FALSE;
            iSeqState := 20;
        END_IF;

    20: (* STATE 20: SYSTEM READY *)
        bSystemReady := TRUE;
        IF bSystemEnable THEN
            bSystemReady := FALSE;
            iSeqState := 30;
        END_IF;

    30: (* STATE 30: CRYOGENIC COOL-DOWN *)
        (* Slowly introduce LH2 to cool down the lines and avoid thermal shock *)
        bCoolDownActive := TRUE;
        rMainValveCmd := 5.0; (* 5% opening for slow trickle *)
        rBOGCompressorCmd := 20.0; (* Low speed BOG handling *)

        IF rHoseTempKelvin <= c_rTargetCryoTemp AND rFlangeTempKelvin <= c_rTargetCryoTemp THEN
            tCoolDownTimer(IN := TRUE, PT := T#60S);
            IF tCoolDownTimer.Q THEN
                tCoolDownTimer(IN := FALSE);
                bCoolDownActive := FALSE;
                iSeqState := 40;
            END_IF;
        ELSE
            tCoolDownTimer(IN := FALSE);
        END_IF;

    40: (* STATE 40: FULL TRANSFER ACTIVE *)
        bTransferActive := TRUE;
        rMainValveCmd := 100.0; (* Full open for transfer *)

        (* Modulate BOG Compressor based on return pressure to maintain safe envelope *)
        IF rReturnBOGPressureBar > 2.0 THEN
            rBOGCompressorCmd := 80.0;
        ELSIF rReturnBOGPressureBar > 1.0 THEN
            rBOGCompressorCmd := 50.0;
        ELSE
            rBOGCompressorCmd := 20.0;
        END_IF;

        IF NOT bSystemEnable THEN
            (* Operator requested normal stop *)
            iSeqState := 50;
        END_IF;

    50: (* STATE 50: NORMAL RAMP DOWN & SECURE *)
        bTransferActive := FALSE;
        rMainValveCmd := 0.0; (* Close main supply *)

        (* Keep BOG running briefly to clear boil-off *)
        tStabilizationTimer(IN := TRUE, PT := T#120S);
        IF tStabilizationTimer.Q THEN
            rBOGCompressorCmd := 0.0;
            tStabilizationTimer(IN := FALSE);
            iSeqState := 0;
        END_IF;

    999: (* STATE 999: EMERGENCY ABORT *)
        (* Immediate closure of all process lines *)
        bSystemReady := FALSE;
        bTransferActive := FALSE;
        bCoolDownActive := FALSE;
        rMainValveCmd := 0.0;
        rBOGCompressorCmd := 100.0; (* Max out BOG to depressurize safe side *)
        bPurgeValveCmd := TRUE;     (* Open purge to dilute remaining LH2 *)

        (* Require explicit manual reset via removing SystemEnable once fault clears *)
        IF NOT bSystemEnable AND NOT bESDActivated AND NOT bThermalShockAlarm THEN
            bCriticalFault := FALSE;
            iSeqState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
