Here is the code with added cybersecurity principles, failover logic, and SCADA heartbeat monitoring.

FUNCTION_BLOCK "SolarInverter_Cyber_Failover"
VERSION : 1.3
VAR_INPUT
    Enable : Bool;
    PV_Voltage : Real;
    PV_Current : Real;
    Grid_Voltage : Real;
    IGBT_Temp : Real;
    Profinet_Ctrl_Word : Word;
    Auth_Token : DWord;
    Partner_Alive : Bool;
    SCADA_Heartbeat : Int;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : Real;
    Profinet_Stat_Word : Word;
    Error_Buffer : Array[0..9] of Int;
    Active_Controller : Bool;
END_VAR
VAR
    Duty_Cycle : Real := 0.5;
    Prev_Power : Real := 0.0;
    Prev_Voltage : Real := 0.0;
    Last_Heartbeat : Int := 0;
    Heartbeat_Timer : Int := 0;
    Security_Lockout : Bool := FALSE;
    Is_Primary : Bool := TRUE;
END_VAR
BEGIN
    // Cybersecurity: Role-based Command Authentication (IEC 62443)
    IF Auth_Token <> 16#A5A5_5A5A THEN
        Security_Lockout := TRUE;
        Profinet_Stat_Word := Profinet_Stat_Word OR 16#0010; // Security Alert
        PWM_Duty_Cycle := 0.0;
        RETURN;
    ELSE
        Security_Lockout := FALSE;
    END_IF;

    // SCADA Heartbeat Monitoring
    IF SCADA_Heartbeat <> Last_Heartbeat THEN
        Last_Heartbeat := SCADA_Heartbeat;
        Heartbeat_Timer := 0;
    ELSE
        Heartbeat_Timer := Heartbeat_Timer + 1;
        IF Heartbeat_Timer > 1000 THEN
            PWM_Duty_Cycle := 0.0;
            Error_Buffer[0] := 301; // Comm Loss
            RETURN;
        END_IF;
    END_IF;

    // Failover Logic for Dual-Redundant Controllers
    IF NOT Partner_Alive AND NOT Is_Primary THEN
        Active_Controller := TRUE;
    ELSIF Is_Primary THEN
        Active_Controller := TRUE;
    ELSE
        Active_Controller := FALSE;
        RETURN; // Standby mode
    END_IF;

    // Core Inverter Logic (Simplified for brevity)
    IF NOT Enable OR Security_Lockout THEN
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // MPPT & Thermal Derating
    VAR Power_Limit : Real := 1.0;
    IF IGBT_Temp > 90.0 THEN
        PWM_Duty_Cycle := 0.0;
        Error_Buffer[1] := 101;
        RETURN;
    ELSIF IGBT_Temp > 75.0 THEN
        Power_Limit := (90.0 - IGBT_Temp) / 15.0;
    END_IF;

    VAR Temp_Power : Real := PV_Voltage * PV_Current;
    IF (Temp_Power - Prev_Power) > 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle - 0.005;
        ELSE
            Duty_Cycle := Duty_Cycle + 0.005;
        END_IF;
    END_IF;

    IF Duty_Cycle > (0.95 * Power_Limit) THEN Duty_Cycle := 0.95 * Power_Limit; END_IF;
    Prev_Power := Temp_Power;
    Prev_Voltage := PV_Voltage;
    PWM_Duty_Cycle := Duty_Cycle;

END_FUNCTION_BLOCK
