FUNCTION_BLOCK FB_HPP_Pasteurization_Control
VAR_INPUT
    (* System enable and safety signals *)
    bSystemEnable           : BOOL;     (* Main process enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal - Active High means OK *)
    bVesselSealed           : BOOL;     (* Proximity sensors confirm vessel is fully sealed *)

    (* Process measurements *)
    rTargetPressure_Bar     : REAL;     (* Target HPP pressure, typically 6000.0 Bar (87000 psi) *)
    rCurrentPressure_Bar    : REAL;     (* Transducer reading of current vessel pressure *)
    rProductTemp_C          : REAL;     (* Initial product temperature in Celsius *)
    rHoldTime_Sec           : REAL;     (* Required hold time at target pressure *)
END_VAR
VAR_OUTPUT
    (* Actuator commands *)
    bIntensifierPumpRun     : BOOL;     (* Command to run the high-pressure intensifier pump *)
    rIntensifierSpeed       : REAL;     (* Pump speed reference 0.0 - 100.0% *)
    bDecompressionValve     : BOOL;     (* Command to open the rapid decompression valve *)

    (* Status and indications *)
    bProcessComplete        : BOOL;     (* Indicates a successful pasteurization cycle *)
    bSystemReady            : BOOL;     (* System is ready to accept a new batch *)
    bAlarm                  : BOOL;     (* Fault alarm output *)
    rEstimatedProductTemp   : REAL;     (* Adiabatic heating compensated product temperature *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tHoldTimer              : TON;
    tDecompressionTimer     : TON;
    rFatigueAccumulator     : REAL := 0.0;  (* Vessel fatigue cycle accumulator *)
    rAdiabaticFactor        : REAL := 0.035;(* Approx. 3.5C increase per 1000 Bar for water-based foods *)
    rError                  : REAL;
    rKp                     : REAL := 2.5;  (* Proportional gain for pressure profiling *)
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlock *)
IF NOT bEmergencyStop THEN
    bIntensifierPumpRun := FALSE;
    rIntensifierSpeed := 0.0;
    bDecompressionValve := TRUE; (* Fail-safe open to depressurize *)
    bSystemReady := FALSE;
    bProcessComplete := FALSE;
    bAlarm := TRUE;
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* Adiabatic Heating Calculation *)
(* 3.5C rise per 1000 Bar is a standard adiabatic rule for HPP in water *)
rEstimatedProductTemp := rProductTemp_C + ((rCurrentPressure_Bar / 1000.0) * rAdiabaticFactor * 100.0);

CASE iState OF
    0: (* IDLE *)
        bIntensifierPumpRun := FALSE;
        rIntensifierSpeed := 0.0;
        bDecompressionValve := FALSE;
        bSystemReady := TRUE;
        bProcessComplete := FALSE;
        bAlarm := FALSE;

        IF bSystemEnable AND bVesselSealed THEN
            bSystemReady := FALSE;
            iState := 10;
        ELSIF bSystemEnable AND NOT bVesselSealed THEN
            bAlarm := TRUE; (* Cannot start if not sealed *)
        END_IF;

    10: (* PRESSURIZATION_RAMP *)
        bIntensifierPumpRun := TRUE;
        bDecompressionValve := FALSE;
        rError := rTargetPressure_Bar - rCurrentPressure_Bar;

        (* Proportional speed control for smooth intensifier operation *)
        rIntensifierSpeed := rError * rKp;
        IF rIntensifierSpeed > 100.0 THEN
            rIntensifierSpeed := 100.0;
        ELSIF rIntensifierSpeed < 10.0 THEN
            rIntensifierSpeed := 10.0; (* Minimum pump speed *)
        END_IF;

        IF rCurrentPressure_Bar >= rTargetPressure_Bar THEN
            rIntensifierSpeed := 0.0;
            bIntensifierPumpRun := FALSE;
            (* Log a full high-pressure cycle for vessel fatigue tracking *)
            rFatigueAccumulator := rFatigueAccumulator + 1.0;
            iState := 20;
        END_IF;

        (* Overpressure Protection *)
        IF rCurrentPressure_Bar > (rTargetPressure_Bar * 1.05) THEN
            iState := 999; (* Transition to fault *)
        END_IF;

    20: (* HOLD_PRESSURE *)
        (* Keep pressure within 1% deadband *)
        IF rCurrentPressure_Bar < (rTargetPressure_Bar * 0.99) THEN
            bIntensifierPumpRun := TRUE;
            rIntensifierSpeed := 20.0; (* Maintenance speed *)
        ELSE
            bIntensifierPumpRun := FALSE;
            rIntensifierSpeed := 0.0;
        END_IF;

        tHoldTimer(IN := TRUE, PT := REAL_TO_TIME(rHoldTime_Sec * 1000.0));
        IF tHoldTimer.Q THEN
            tHoldTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* DECOMPRESSION *)
        bIntensifierPumpRun := FALSE;
        rIntensifierSpeed := 0.0;
        bDecompressionValve := TRUE; (* Open decompression valve *)

        tDecompressionTimer(IN := TRUE, PT := T#10S); (* Wait for rapid decompression *)
        IF tDecompressionTimer.Q AND (rCurrentPressure_Bar < 5.0) THEN
            tDecompressionTimer(IN := FALSE);
            bDecompressionValve := FALSE;
            bProcessComplete := TRUE;
            iState := 40;
        END_IF;

    40: (* COMPLETE *)
        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bIntensifierPumpRun := FALSE;
        rIntensifierSpeed := 0.0;
        bDecompressionValve := TRUE;
        bAlarm := TRUE;

        (* Require enable signal removal to reset fault, assuming e-stop is cleared *)
        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

