FUNCTION_BLOCK "BeverageFiller_Secure"
VAR_INPUT
    UserRole : Int; // 0=None, 1=Operator, 2=Admin
    SCADA_Cmd : Int;
    PN_Status : Word;
    Start : Bool;
    Stop : Bool;
    BottlePresent : Bool;
    CapPresent : Bool;
    FillLevelSensor : Real; 
    CarbonationPressure : Real; 
    TargetLevel : Real;
    TargetPressure : Real;
    TargetTorque : Real;
    ActualTorque : Real;
    Pump1_Fail : Bool;
END_VAR
VAR_OUTPUT
    FillValve : Bool;
    CO2Valve : Bool;
    ConveyorMotor : Bool;
    CapperMotor : Bool;
    PumpActive : Int;
    Ready : Bool;
    FaultID : Int;
    SCADA_Status : Int;
END_VAR
VAR
    FillingState : Int;
    FaultActive : Bool;
END_VAR

BEGIN
    // IEC 62443 Role-based access
    IF UserRole < 1 THEN
        FaultActive := TRUE;
        FaultID := 10; // Unauthorized Access
    END_IF;

    // Failover Handling
    IF Pump1_Fail THEN
        PumpActive := 2; // Switch to backup pump
    ELSE
        PumpActive := 1;
    END_IF;

    // SCADA Integration
    SCADA_Status := FillingState;

    IF FaultActive OR Stop OR SCADA_Cmd = 99 THEN // 99=E-Stop
        FillValve := FALSE;
        CO2Valve := FALSE;
        CapperMotor := FALSE;
        Ready := FALSE;
        RETURN;
    END_IF;

    CASE FillingState OF
        0: // Idle
            ConveyorMotor := (Start OR SCADA_Cmd = 1);
            Ready := TRUE;
            IF BottlePresent THEN
                ConveyorMotor := FALSE;
                FillingState := 1;
            END_IF;
        1: // Carbonation
            Ready := FALSE;
            IF CarbonationPressure < TargetPressure THEN
                CO2Valve := TRUE;
            ELSE
                CO2Valve := FALSE;
                FillingState := 2;
            END_IF;
        2: // Filling
            IF FillLevelSensor < TargetLevel THEN
                FillValve := TRUE;
            ELSE
                FillValve := FALSE;
                FillingState := 3;
            END_IF;
        3: // Capping
            IF CapPresent AND ActualTorque < TargetTorque THEN
                CapperMotor := TRUE;
            ELSE
                CapperMotor := FALSE;
                FillingState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
