FUNCTION_BLOCK FB_PlasmaWakefieldAccelerator
VAR_INPUT
    bEnableAccelerator      : BOOL;     (* System master enable interlock *)
    bCryoCoolingOK          : BOOL;     (* Cryogenic cavity Q-factor cooling status (TRUE = nominal < 4K) *)
    rLaserPulseEnergy       : REAL;     (* Femtosecond laser pulse energy in mJ *)
    rElectronBunchCharge    : REAL;     (* Injected electron bunch charge in pC *)
    rPlasmaDensitySetp      : REAL;     (* Desired background ionospheric plasma density in cm^-3 *)
    rBeamTrajectoryX        : REAL;     (* X-axis trajectory alignment deviation in nm *)
    rBeamTrajectoryY        : REAL;     (* Y-axis trajectory alignment deviation in nm *)
END_VAR
VAR_OUTPUT
    bAcceleratorReady       : BOOL;     (* Accelerator primed and stable for next injection *)
    rLaserModulationVoltage : REAL;     (* Laser pulse envelope modulation control voltage *)
    rMagneticSteeringX      : REAL;     (* Nanometer trajectory steering magnet X-axis current (A) *)
    rMagneticSteeringY      : REAL;     (* Nanometer trajectory steering magnet Y-axis current (A) *)
    rPlasmaDensityError     : REAL;     (* Error between setpoint and actual plasma density for logging *)
    bCriticalFault          : BOOL;     (* Global interlock fault condition triggered *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine tracker *)
    rKpX                    : REAL := 1.25; (* Proportional gain for X steering *)
    rKiX                    : REAL := 0.05; (* Integral gain for X steering *)
    rKpY                    : REAL := 1.25; (* Proportional gain for Y steering *)
    rKiY                    : REAL := 0.05; (* Integral gain for Y steering *)
    rIntegralX              : REAL := 0.0;
    rIntegralY              : REAL := 0.0;
    rSteeringLimit          : REAL := 15.0; (* Max allowable steering current in Amps *)
    tStabilizationTimer     : TON;      (* Timer for cavity thermal stabilization *)
    tPulseSyncTimer         : TON;      (* Timer for repetition rate sync *)
    rCavityTemperatureAct   : REAL := 1.8; (* Simulated or read actual temperature in K *)
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Interlock Checks *)
IF NOT bCryoCoolingOK OR rCavityTemperatureAct > 2.5 THEN
    bAcceleratorReady := FALSE;
    bCriticalFault := TRUE;
    rLaserModulationVoltage := 0.0;
    rMagneticSteeringX := 0.0;
    rMagneticSteeringY := 0.0;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* PID Trajectory Control Routine (Nanometer Steering) *)
IF bEnableAccelerator AND NOT bCriticalFault THEN
    rIntegralX := rIntegralX + (rBeamTrajectoryX * 0.01);
    rIntegralY := rIntegralY + (rBeamTrajectoryY * 0.01);

    (* Anti-windup clamping X *)
    IF rIntegralX > 10.0 THEN rIntegralX := 10.0; ELSIF rIntegralX < -10.0 THEN rIntegralX := -10.0; END_IF;
    (* Anti-windup clamping Y *)
    IF rIntegralY > 10.0 THEN rIntegralY := 10.0; ELSIF rIntegralY < -10.0 THEN rIntegralY := -10.0; END_IF;

    rMagneticSteeringX := (rBeamTrajectoryX * rKpX) + (rIntegralX * rKiX);
    rMagneticSteeringY := (rBeamTrajectoryY * rKpY) + (rIntegralY * rKiY);

    (* Output clamping *)
    IF rMagneticSteeringX > rSteeringLimit THEN rMagneticSteeringX := rSteeringLimit; ELSIF rMagneticSteeringX < -rSteeringLimit THEN rMagneticSteeringX := -rSteeringLimit; END_IF;
    IF rMagneticSteeringY > rSteeringLimit THEN rMagneticSteeringY := rSteeringLimit; ELSIF rMagneticSteeringY < -rSteeringLimit THEN rMagneticSteeringY := -rSteeringLimit; END_IF;
END_IF;

(* Accelerator Sequence State Machine *)
CASE iState OF
    0: (* IDLE & STANDBY *)
        bAcceleratorReady := FALSE;
        rLaserModulationVoltage := 0.0;
        IF bEnableAccelerator AND bCryoCoolingOK THEN
            iState := 10; (* PRE-FLIGHT THERMAL STABILIZATION *)
        END_IF;

    10: (* THERMAL STABILIZATION & Q-FACTOR OPTIMIZATION *)
        tStabilizationTimer(IN := TRUE, PT := T#15S);
        IF tStabilizationTimer.Q THEN
            tStabilizationTimer(IN := FALSE);
            iState := 20; (* PLASMA DENSITY MATCHING *)
        END_IF;

    20: (* PLASMA DENSITY MATCHING *)
        rPlasmaDensityError := rPlasmaDensitySetp - 1.0E17; (* Simulated base density measurement *)
        IF ABS(rPlasmaDensityError) < 1.0E15 THEN
            iState := 30; (* WAKEFIELD PRIMING *)
        END_IF;

    30: (* WAKEFIELD PRIMING & LASER MODULATION *)
        (* Map desired pulse energy to piezo modulation voltage (non-linear curve sim) *)
        rLaserModulationVoltage := rLaserPulseEnergy * 0.85 + (rLaserPulseEnergy * rLaserPulseEnergy * 0.002);
        IF rLaserModulationVoltage > 10.0 THEN
            rLaserModulationVoltage := 10.0; (* 10V DAC clamp *)
        END_IF;
        iState := 40; (* READY FOR INJECTION *)

    40: (* READY FOR INJECTION *)
        bAcceleratorReady := TRUE;
        bCriticalFault := FALSE;
        IF NOT bEnableAccelerator THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bAcceleratorReady := FALSE;
        bCriticalFault := TRUE;
        rLaserModulationVoltage := 0.0;
        IF NOT bEnableAccelerator AND bCryoCoolingOK AND rCavityTemperatureAct <= 2.5 THEN
            iState := 0; (* Reset sequence when enable is cleared and temps are OK *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

