FUNCTION_BLOCK FB_CCC_DesublimationChamber
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (E-Stop OK = TRUE) *)
    rChamberPressure        : REAL;     (* Chamber absolute pressure [kPa] *)
    rFlueGasInletTemp       : REAL;     (* Flue gas inlet temperature [deg C] *)
    rCoolantInletTemp       : REAL;     (* Cryogenic refrigerant temperature [deg C] *)
    rFrostThickness         : REAL;     (* Measured CO2 frost thickness on coils [mm] *)
    rFlueGasMassFlow        : REAL;     (* Flue gas mass flow rate [kg/s] *)
    bDefrostRequest         : BOOL;     (* Manual or external defrost request *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Desublimation chamber ready for operation *)
    rCoolantValveCmd        : REAL;     (* Cryogenic coolant valve opening [%] *)
    rFlueGasBypassCmd       : REAL;     (* Flue gas bypass damper position [%] *)
    bDefrostActive          : BOOL;     (* Defrost cycle active flag *)
    bAlarm                  : BOOL;     (* System critical alarm *)
    iOperationState         : INT;      (* Current state machine step *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine *)
    tDefrostTimer           : TON;      (* Defrost cycle timer *)
    tStartupDelay           : TON;      (* Startup stabilization timer *)
    rTempError              : REAL;     (* Temperature error for cascade control *)
    rCoolantValveTarget     : REAL;     (* Internal coolant valve target *)
    rCoolantValveCurrent    : REAL;     (* Internal coolant valve current state *)
    rIntegralTerm           : REAL := 0.0; (* PID Integral term *)
    rDerivativeTerm         : REAL := 0.0; (* PID Derivative term *)
    rLastError              : REAL := 0.0; (* Previous error for Derivative *)

    (* Control parameters *)
    rKp                     : REAL := 2.5; 
    rKi                     : REAL := 0.15;
    rKd                     : REAL := 0.5;
    rTargetFrostTemp        : REAL := -120.0; (* Target deposition temp [deg C] *)
    rMaxFrostThickness      : REAL := 15.0;   (* Maximum allowed frost thickness [mm] *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety & Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rCoolantValveCmd := 0.0;
    rFlueGasBypassCmd := 100.0; (* Full bypass on E-Stop *)
    bDefrostActive := FALSE;
    iState := 0;
    iOperationState := iState;
    RETURN;
END_IF;

(* 2. Fault Detection *)
IF (rChamberPressure > 150.0) OR (rChamberPressure < 10.0) THEN
    bAlarm := TRUE;
ELSE
    bAlarm := FALSE;
END_IF;

(* 3. State Machine *)
CASE iState OF
    0: (* IDLE / OFF *)
        bSystemReady := FALSE;
        rCoolantValveTarget := 0.0;
        rFlueGasBypassCmd := 100.0;
        bDefrostActive := FALSE;

        IF bEnable AND NOT bAlarm THEN
            iState := 10;
        END_IF;

    10: (* PRE-COOLING *)
        bSystemReady := FALSE;
        rFlueGasBypassCmd := 100.0; (* Keep bypassing gas while cooling *)

        (* Open coolant valve to pre-cool chamber *)
        rCoolantValveTarget := 75.0; 

        IF rCoolantInletTemp <= (rTargetFrostTemp + 10.0) THEN
            tStartupDelay(IN := TRUE, PT := T#30S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* ACTIVE DESUBLIMATION (NORMAL RUN) *)
        bSystemReady := TRUE;
        rFlueGasBypassCmd := 0.0; (* Direct gas into chamber *)

        (* PID Control for Coolant Valve based on frost target temp *)
        rTempError := rTargetFrostTemp - rCoolantInletTemp; 

        rIntegralTerm := rIntegralTerm + (rTempError * rKi);
        (* Anti-windup *)
        IF rIntegralTerm > 100.0 THEN rIntegralTerm := 100.0; END_IF;
        IF rIntegralTerm < 0.0 THEN rIntegralTerm := 0.0; END_IF;

        rDerivativeTerm := (rTempError - rLastError) * rKd;
        rLastError := rTempError;

        rCoolantValveTarget := (rTempError * rKp) + rIntegralTerm + rDerivativeTerm;

        IF rCoolantValveTarget > 100.0 THEN rCoolantValveTarget := 100.0; END_IF;
        IF rCoolantValveTarget < 10.0 THEN rCoolantValveTarget := 10.0; END_IF;

        (* Check for frost buildup *)
        IF (rFrostThickness >= rMaxFrostThickness) OR bDefrostRequest THEN
            iState := 30;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* DEFROST CYCLE INITIATION *)
        bSystemReady := FALSE;
        bDefrostActive := TRUE;
        rFlueGasBypassCmd := 100.0; (* Bypass gas during defrost *)
        rCoolantValveTarget := 0.0; (* Shut off cryogenic coolant *)

        tDefrostTimer(IN := TRUE, PT := T#5M); (* 5 minute defrost assumed *)

        IF tDefrostTimer.Q THEN
            tDefrostTimer(IN := FALSE);
            bDefrostActive := FALSE;
            IF bEnable THEN
                iState := 10; (* Return to pre-cooling *)
            ELSE
                iState := 0;
            END_IF;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

(* 4. Output processing with rate limiting (simulated actuator physics) *)
(* Ramp the valve command to avoid water hammer in cryogenic lines *)
IF rCoolantValveCurrent < rCoolantValveTarget THEN
    rCoolantValveCurrent := rCoolantValveCurrent + 0.5;
    IF rCoolantValveCurrent > rCoolantValveTarget THEN rCoolantValveCurrent := rCoolantValveTarget; END_IF;
ELSIF rCoolantValveCurrent > rCoolantValveTarget THEN
    rCoolantValveCurrent := rCoolantValveCurrent - 0.5;
    IF rCoolantValveCurrent < rCoolantValveTarget THEN rCoolantValveCurrent := rCoolantValveTarget; END_IF;
END_IF;

rCoolantValveCmd := rCoolantValveCurrent;
iOperationState := iState;

END_FUNCTION_BLOCK
```

