FUNCTION_BLOCK FB_HighSpeedRotaryCanSeamer
VAR_INPUT
    bEnable : BOOL;
    lrMasterAxisVelocity : LREAL; (* Cans per minute *)
    bCanPresent : BOOL;
    bLidPresent : BOOL;
    lrSteamPressureActual : LREAL;
    lrSeamThicknessFeedback : LREAL;
    lrSeamLengthFeedback : LREAL;
    bEStop : BOOL;
END_VAR
VAR_OUTPUT
    bSystemReady : BOOL;
    bFaultActive : BOOL;
    nFaultCode : INT;
    lrChuckAxisSetpoint : LREAL;
    lrSeamRollAxis1Setpoint : LREAL;
    lrSeamRollAxis2Setpoint : LREAL;
    lrSteamInjectionValveCmd : LREAL;
    bRejectCan : BOOL;
END_VAR
VAR
    eState : (INIT, IDLE, RAMP_UP, PRODUCTION, STOPPING, FAULT);
    lrCamPhaseAngle : LREAL;
    lrBaseSpeedPhase : LREAL;

    (* Seam Profile Constants *)
    lrOperationAngleStart1 : LREAL := 45.0;
    lrOperationAngleEnd1 : LREAL := 180.0;
    lrOperationAngleStart2 : LREAL := 180.0;
    lrOperationAngleEnd2 : LREAL := 315.0;

    (* Steam Vacuum PID *)
    lrSteamPressureSetpoint : LREAL := 2.5; (* bar *)
    lrSteamKp : LREAL := 1.2;
    lrSteamKi : LREAL := 0.5;
    lrSteamErrorSum : LREAL;

    (* Micro-adjustments *)
    lrThicknessTarget : LREAL := 1.25; (* mm *)
    lrThicknessTolerance : LREAL := 0.05;
    lrSeamRoll1OffsetCmd : LREAL;

    lrLengthTarget : LREAL := 2.80; (* mm *)
    lrLengthTolerance : LREAL := 0.10;
    lrSeamRoll2OffsetCmd : LREAL;
END_VAR

(* Implementation *)
IF bEStop THEN
    eState := FAULT;
    nFaultCode := 1000; (* E-Stop *)
END_IF;

CASE eState OF
    INIT:
        bSystemReady := FALSE;
        bFaultActive := FALSE;
        lrChuckAxisSetpoint := 0.0;
        lrSeamRollAxis1Setpoint := 0.0;
        lrSeamRollAxis2Setpoint := 0.0;
        lrSteamInjectionValveCmd := 0.0;
        IF bEnable THEN
            eState := IDLE;
        END_IF;

    IDLE:
        bSystemReady := TRUE;
        IF bEnable AND lrMasterAxisVelocity > 0.0 THEN
            eState := RAMP_UP;
        END_IF;

    RAMP_UP:
        (* Synchronizing phase angles *)
        lrBaseSpeedPhase := lrBaseSpeedPhase + (lrMasterAxisVelocity * 0.01); 
        IF lrBaseSpeedPhase >= 360.0 THEN
            lrBaseSpeedPhase := lrBaseSpeedPhase - 360.0;
        END_IF;

        IF lrMasterAxisVelocity > 500.0 THEN (* Target CPM threshold *)
            eState := PRODUCTION;
        END_IF;

    PRODUCTION:
        (* Virtual Master Cam Phase Generation *)
        lrCamPhaseAngle := lrCamPhaseAngle + (lrMasterAxisVelocity * 6.0 * 0.001); (* 1ms task assumed *)
        IF lrCamPhaseAngle >= 360.0 THEN
            lrCamPhaseAngle := lrCamPhaseAngle - 360.0;
        END_IF;

        (* Chuck Axis is directly geared to Master Phase *)
        lrChuckAxisSetpoint := lrCamPhaseAngle;

        (* First Operation Seaming Roll Cam Profile *)
        IF lrCamPhaseAngle >= lrOperationAngleStart1 AND lrCamPhaseAngle <= lrOperationAngleEnd1 THEN
            lrSeamRollAxis1Setpoint := SIN((lrCamPhaseAngle - lrOperationAngleStart1) * 3.14159 / (lrOperationAngleEnd1 - lrOperationAngleStart1)) * 10.0 + lrSeamRoll1OffsetCmd;
        ELSE
            lrSeamRollAxis1Setpoint := 0.0;
        END_IF;

        (* Second Operation Seaming Roll Cam Profile *)
        IF lrCamPhaseAngle >= lrOperationAngleStart2 AND lrCamPhaseAngle <= lrOperationAngleEnd2 THEN
            lrSeamRollAxis2Setpoint := SIN((lrCamPhaseAngle - lrOperationAngleStart2) * 3.14159 / (lrOperationAngleEnd2 - lrOperationAngleStart2)) * 8.0 + lrSeamRoll2OffsetCmd;
        ELSE
            lrSeamRollAxis2Setpoint := 0.0;
        END_IF;

        (* Headspace Steam Vacuum Injection PID Control *)
        IF bCanPresent AND bLidPresent THEN
            lrSteamErrorSum := lrSteamErrorSum + (lrSteamPressureSetpoint - lrSteamPressureActual) * 0.001;
            lrSteamInjectionValveCmd := (lrSteamPressureSetpoint - lrSteamPressureActual) * lrSteamKp + lrSteamErrorSum * lrSteamKi;

            IF lrSteamInjectionValveCmd > 100.0 THEN
                lrSteamInjectionValveCmd := 100.0;
            ELSIF lrSteamInjectionValveCmd < 0.0 THEN
                lrSteamInjectionValveCmd := 0.0;
            END_IF;
        ELSE
            lrSteamInjectionValveCmd := 0.0;
            lrSteamErrorSum := 0.0;
        END_IF;

        (* Double-Seam Micrometer Feedback Adjustments *)
        IF ABS(lrSeamThicknessFeedback - lrThicknessTarget) > lrThicknessTolerance THEN
            lrSeamRoll1OffsetCmd := lrSeamRoll1OffsetCmd + (lrSeamThicknessFeedback - lrThicknessTarget) * 0.1; 
            bRejectCan := TRUE;
        ELSE
            bRejectCan := FALSE;
        END_IF;

        IF ABS(lrSeamLengthFeedback - lrLengthTarget) > lrLengthTolerance THEN
            lrSeamRoll2OffsetCmd := lrSeamRoll2OffsetCmd + (lrSeamLengthFeedback - lrLengthTarget) * 0.1;
            bRejectCan := TRUE;
        END_IF;

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF;

    STOPPING:
        lrChuckAxisSetpoint := 0.0;
        lrSeamRollAxis1Setpoint := 0.0;
        lrSeamRollAxis2Setpoint := 0.0;
        lrSteamInjectionValveCmd := 0.0;
        eState := IDLE;

    FAULT:
        bSystemReady := FALSE;
        bFaultActive := TRUE;
        lrChuckAxisSetpoint := 0.0;
        lrSeamRollAxis1Setpoint := 0.0;
        lrSeamRollAxis2Setpoint := 0.0;
        lrSteamInjectionValveCmd := 0.0;
        IF NOT bEStop THEN
            eState := INIT;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
