    rBrineHeaterTempTarget : REAL; // Target temperature for brine heater (deg C)
    rSeaWaterInletTemp : REAL; // Sea water inlet temperature (deg C)
    rTopBrineTemperature : REAL; // Measured Top Brine Temperature (TBT)
