    rSteamValveKp : REAL := 2.5;
    rSteamValveKi : REAL := 0.15;
    rSteamValveKd : REAL := 0.05;

    rMakeUpError : REAL;
    rMakeUpIntegral : REAL := 0.0;
    rMakeUpKp : REAL := 1.2;
    rMakeUpKi : REAL := 0.08;

    bSalinityHigh : BOOL;
    tSalinityTimer : TON;
    tSystemStartupTimer : TON;

    eState : (INIT, PURGE, WARM_UP, NORMAL_OP, ALARM, SHUTDOWN);
END_VAR

// Main State Machine
CASE eState OF
    INIT:
        rSteamValveCmd := 0.0;
        rMakeUpValveCmd := 0.0;
        rRecyclePumpSpeed := 0.0;
        bVacuumEjectorEnable := FALSE;
        bDistillateDivertValve := TRUE; // Divert by default
        bSystemAlarm := FALSE;
        iAlarmCode := 0;

        IF bEnable AND NOT bEmergencyStop THEN
            eState := PURGE;
            tSystemStartupTimer(IN := FALSE, PT := T#30s);
        END_IF;

    PURGE:
        bVacuumEjectorEnable := TRUE; // Start pulling vacuum
        rMakeUpValveCmd := 50.0; // Fill stages
        rRecyclePumpSpeed := 30.0; // Minimal flow

        tSystemStartupTimer(IN := TRUE, PT := T#5m);
        IF tSystemStartupTimer.Q THEN
            eState := WARM_UP;
        END_IF;

    WARM_UP:
        rRecyclePumpSpeed := 60.0;
        // Simple ramp for steam valve
        IF rTopBrineTemperature < rBrineHeaterTempTarget THEN
            rSteamValveCmd := MIN(rSteamValveCmd + 0.1, 80.0);
        ELSE
            eState := NORMAL_OP;
        END_IF;

    NORMAL_OP:
        // Top Brine Temperature PID Control
        rTbtError := rBrineHeaterTempTarget - rTopBrineTemperature;
        rTbtIntegral := rTbtIntegral + rTbtError;
        // Anti-windup
        IF rTbtIntegral > 1000.0 THEN rTbtIntegral := 1000.0; END_IF;
        IF rTbtIntegral < -1000.0 THEN rTbtIntegral := -1000.0; END_IF;
        rTbtDerivative := rTbtError - rTbtLastError;
        rTbtLastError := rTbtError;

        rSteamValveCmd := (rTbtError * rSteamValveKp) + (rTbtIntegral * rSteamValveKi) + (rTbtDerivative * rSteamValveKd);
        rSteamValveCmd := MAX(0.0, MIN(100.0, rSteamValveCmd));

        // Make-Up Flow Control to maintain mass balance (simplified)
        rMakeUpError := rRecycleFlowRate * 0.15 - rMakeUpFlowRate; // Assuming 15% blowdown/distillate ratio
        rMakeUpIntegral := rMakeUpIntegral + rMakeUpError;
        rMakeUpValveCmd := (rMakeUpError * rMakeUpKp) + (rMakeUpIntegral * rMakeUpKi);
        rMakeUpValveCmd := MAX(0.0, MIN(100.0, rMakeUpValveCmd));

        // Vacuum Maintenance
        IF rVacuumLevelStageN > 50.0 THEN // Absolute pressure too high (loss of vacuum)
            bVacuumEjectorEnable := TRUE;
        ELSIF rVacuumLevelStageN < 30.0 THEN
            // Vacuum is excellent, could modulate cooling water or ejectors
            bVacuumEjectorEnable := TRUE; // Usually kept on for non-condensables extraction
        END_IF;

        // Salinity Check
        tSalinityTimer(IN := (rDistillateSalinity > 10.0), PT := T#10s);
        IF tSalinityTimer.Q THEN
            bDistillateDivertValve := TRUE; // Dump out-of-spec product
        ELSE
            bDistillateDivertValve := FALSE; // Send to product tank
        END_IF;

        // GOR Calculation (Distillate produced / Steam consumed equivalent)
        IF rSteamValveCmd > 5.0 THEN
            rCalculatedGOR := (rMakeUpFlowRate * 0.8) / (rSteamValveCmd * 0.5); // Mock physics equation
        ELSE
            rCalculatedGOR := 0.0;
        END_IF;

        // Faults
        IF bAntiScaleInjectionFault THEN
            eState := ALARM;
            iAlarmCode := 101;
        END_IF;
        IF rTopBrineTemperature > 120.0 THEN // Max temp exceeded
            eState := ALARM;
            iAlarmCode := 102;
        END_IF;

    ALARM:
        bSystemAlarm := TRUE;
        rSteamValveCmd := 0.0; // Isolate heat
        rRecyclePumpSpeed := 30.0; // Cool down
        bDistillateDivertValve := TRUE;
        IF NOT bEnable THEN
            eState := SHUTDOWN;
        END_IF;

    SHUTDOWN:
        rSteamValveCmd := 0.0;
        rMakeUpValveCmd := 0.0;
        rRecyclePumpSpeed := 0.0;
        bVacuumEjectorEnable := FALSE;
        bDistillateDivertValve := TRUE;
        bSystemAlarm := FALSE;
        IF NOT bEmergencyStop AND bEnable THEN
            eState := INIT;
        END_IF;
END_CASE;

// Global Emergency Override
IF bEmergencyStop THEN
    eState := SHUTDOWN;
    rSteamValveCmd := 0.0;
    rMakeUpValveCmd := 0.0;
    rRecyclePumpSpeed := 0.0;
    bVacuumEjectorEnable := FALSE;
    bDistillateDivertValve := TRUE;
    bSystemAlarm := TRUE;
    iAlarmCode := 999;
END_IF;

END_FUNCTION_BLOCK
