FUNCTION_BLOCK FB_WetWipesConverting
VAR_INPUT
    bEnable : BOOL; // Enable machine operations
    rLineSpeed_m_min : REAL; // Current machine line speed
    rTargetWebTension_N : REAL; // Target tension for nonwoven slitting
    rActualWebTension_N : REAL; // Measured tension from load cells
    rTargetLotionDosing_g_m2 : REAL; // Target lotion amount per square meter
    rCurrentLotionFlow_g_s : REAL; // Mass flow meter feedback for lotion
    bCrossSealTrigger : BOOL; // Trigger signal for ultrasonic cross seal
    rUltrasonicFrequency_kHz : REAL; // Current frequency of ultrasonic horn
    rUltrasonicPowerFeedback_W : REAL; // Feedback power from ultrasonic generator
END_VAR
VAR_OUTPUT
    rUnwindBrakeTorque_Nm : REAL; // Output to unwind brake for tension control
    rLotionPumpSpeed_RPM : REAL; // Command to lotion dosing pump
    bUltrasonicWeldStart : BOOL; // Command to start ultrasonic weld
    rUltrasonicAmplitude_Pct : REAL; // Amplitude setpoint for cross-seal
    bMachineFault : BOOL; // General fault flag
    iErrorCode : INT; // Error code (0 = No Error)
END_VAR
VAR
    // Internal states and PID instances
    fbTensionPID : PID; // Standard PID block (assumed existing)
    fbDosingPID : PID; // Standard PID block (assumed existing)

    // Slitting Tension Variables
    rTensionError : REAL;
    rTensionKp : REAL := 2.5;
    rTensionKi : REAL := 0.1;
    rTensionKd : REAL := 0.05;

    // Lotion Dosing Variables
    rCalculatedLotionFlowTarget : REAL; // Calculated target in g/s based on line speed
    rWebWidth_m : REAL := 1.2; // Web width in meters
    rDosingError : REAL;
    rDosingKp : REAL := 1.0;
    rDosingKi : REAL := 0.05;

    // Ultrasonic Sealing Variables
    timerWeldDuration : TON;
    tWeldTime : TIME := T#150ms;
    rOptimalPower_W : REAL := 1500.0;
    rPowerTolerance_W : REAL := 200.0;

    // State machine
    iState : INT := 0; 
END_VAR

// Reset outputs if disabled
IF NOT bEnable THEN
    rUnwindBrakeTorque_Nm := 0.0;
    rLotionPumpSpeed_RPM := 0.0;
    bUltrasonicWeldStart := FALSE;
    rUltrasonicAmplitude_Pct := 0.0;
    bMachineFault := FALSE;
    iErrorCode := 0;
    iState := 0;
    RETURN;
END_IF

// =========================================================================
// 1. Nonwoven Fabric Slitting Tension Control
// =========================================================================
rTensionError := rTargetWebTension_N - rActualWebTension_N;

fbTensionPID(
    ACTUAL := rActualWebTension_N,
    SET_POINT := rTargetWebTension_N,
    KP := rTensionKp,
    KI := rTensionKi,
    KD := rTensionKd,
    Y => rUnwindBrakeTorque_Nm
);

// Safety bounds for brake torque
IF rUnwindBrakeTorque_Nm < 0.0 THEN
    rUnwindBrakeTorque_Nm := 0.0;
ELSIF rUnwindBrakeTorque_Nm > 100.0 THEN
    rUnwindBrakeTorque_Nm := 100.0;
END_IF

// Tension Fault Detection
IF ABS(rTensionError) > 50.0 THEN
    bMachineFault := TRUE;
    iErrorCode := 101; // Tension out of bounds
END_IF


// =========================================================================
// 2. Lotion Dosing Impregnation Mass Flow
// =========================================================================
rCalculatedLotionFlowTarget := (rLineSpeed_m_min / 60.0) * rWebWidth_m * rTargetLotionDosing_g_m2;

fbDosingPID(
    ACTUAL := rCurrentLotionFlow_g_s,
    SET_POINT := rCalculatedLotionFlowTarget,
    KP := rDosingKp,
    KI := rDosingKi,
    Y => rLotionPumpSpeed_RPM
);

// Pump safety bounds
IF rLotionPumpSpeed_RPM < 0.0 THEN
    rLotionPumpSpeed_RPM := 0.0;
ELSIF rLotionPumpSpeed_RPM > 1500.0 THEN // Max RPM
    rLotionPumpSpeed_RPM := 1500.0;
END_IF

// Dosing Fault Detection
rDosingError := rCalculatedLotionFlowTarget - rCurrentLotionFlow_g_s;
IF ABS(rDosingError) > 20.0 THEN
    bMachineFault := TRUE;
    iErrorCode := 102; // Dosing mismatch
END_IF


// =========================================================================
// 3. Flow Wrapper Ultrasonic Cross-Seal
// =========================================================================
IF rLineSpeed_m_min > 0.0 THEN
    rUltrasonicAmplitude_Pct := 60.0 + (rLineSpeed_m_min * 0.4);
    IF rUltrasonicAmplitude_Pct > 100.0 THEN
        rUltrasonicAmplitude_Pct := 100.0;
    END_IF
ELSE
    rUltrasonicAmplitude_Pct := 0.0;
END_IF

IF bCrossSealTrigger AND NOT timerWeldDuration.IN THEN
    bUltrasonicWeldStart := TRUE;
END_IF

timerWeldDuration(IN := bUltrasonicWeldStart, PT := tWeldTime);

IF timerWeldDuration.Q THEN
    bUltrasonicWeldStart := FALSE;
END_IF

IF bUltrasonicWeldStart THEN
    IF ABS(rUltrasonicPowerFeedback_W - rOptimalPower_W) > rPowerTolerance_W THEN
        bMachineFault := TRUE;
        iErrorCode := 103; // Ultrasonic Power Warning
    END_IF
END_IF

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_UHBR_TestCell_VAFN_FlutterControl
(*
======================================================================================
BLOCK NAME: FB_UHBR_TestCell_VAFN_FlutterControl
DESCRIPTION: Advanced closed-loop controller for Ultra-High Bypass Turbofan 
             Variable Area Fan Nozzle (VAFN) dynamic flutter tracking and 
             mitigation during extreme thrust transients in a cross-wind 
             distortion matrix environment. Uses Kalman-filtered multi-axis
             piezo-electric strain gauge telemetry.
AUTHOR: 40-Year Veteran PLC Automation Architect
======================================================================================
*)
VAR_INPUT
    bSystemEnable           : BOOL;     (* System master enable interlock *)
    bEmergencyStopOk        : BOOL;     (* Safety relay OK signal (Normally Closed loop) *)
    rMainThrustCommand      : REAL;     (* Thrust command input (kN) *)
    rPiezoForceX            : REAL;     (* X-axis force measurement from thrust stand (kN) *)
    rPiezoForceY            : REAL;     (* Y-axis lateral flutter measurement (kN) *)
    rPiezoForceZ            : REAL;     (* Z-axis vertical flutter measurement (kN) *)
    rCrossWindVel           : REAL;     (* Inlet distortion cross-wind velocity (m/s) *)
    rFanSpeedRPM            : REAL;     (* N1 Fan speed (RPM) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Control loop ready and stabilized *)
    rVAFN_ActuatorPosCmd    : REAL;     (* Variable Area Fan Nozzle actuator position (0.0 to 100.0 %) *)
    rInletGuideVaneCmd      : REAL;     (* Inlet Guide Vane angle command (degrees) *)
    bFlutterAlarm           : BOOL;     (* Aerodynamic flutter threshold exceeded alarm *)
    bThrustStandFault       : BOOL;     (* Thrust stand measurement anomaly detected *)
    rFilteredThrust         : REAL;     (* Noise-filtered resultant thrust output (kN) *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine variable *)
    tStartupDelay           : TON;      (* Initialization stabilization timer *)
    tFlutterDebounce        : TON;      (* Flutter detection debounce timer *)

    (* Internal Calculations *)
    rResultantFlutterMag    : REAL;
    rErrorMargin            : REAL;
    rDerivativeWind         : REAL;
    rLastCrossWind          : REAL := 0.0;

    (* Filter Constants *)
    c_AlphaFilt             : REAL := 0.05; 
    c_FlutterThreshold      : REAL := 45.5; (* kN limit for structural integrity *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Quick Stop *)
IF NOT bEmergencyStopOk THEN
    bSystemReady            := FALSE;
    bFlutterAlarm           := TRUE;
    rVAFN_ActuatorPosCmd    := 100.0; (* Fail-safe fully open nozzle *)
    rInletGuideVaneCmd      := 0.0;
    rFilteredThrust         := 0.0;
    iState                  := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* 2. Core State Machine *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bFlutterAlarm := FALSE;
        bThrustStandFault := FALSE;
        rVAFN_ActuatorPosCmd := 100.0; (* Open for startup *)

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* SENSOR CALIBRATION AND STARTUP DELAY *)
        tStartupDelay(IN := TRUE, PT := T#3S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* ACTIVE CONTROL LOOP *)
        bSystemReady := TRUE;

        (* Low-pass filter on main thrust measurement to remove high-frequency noise *)
        rFilteredThrust := (c_AlphaFilt * rPiezoForceX) + ((1.0 - c_AlphaFilt) * rFilteredThrust);

        (* Calculate dynamic wind distortion derivative *)
        rDerivativeWind := rCrossWindVel - rLastCrossWind;
        rLastCrossWind  := rCrossWindVel;

        (* Vector magnitude of lateral and vertical flutter forces *)
        rResultantFlutterMag := SQRT((rPiezoForceY * rPiezoForceY) + (rPiezoForceZ * rPiezoForceZ));

        (* Evaluate flutter against dynamic thresholds based on cross wind derivatives *)
        IF rResultantFlutterMag > (c_FlutterThreshold - (rDerivativeWind * 2.0)) THEN
            tFlutterDebounce(IN := TRUE, PT := T#200MS);
        ELSE
            tFlutterDebounce(IN := FALSE);
            bFlutterAlarm := FALSE;
        END_IF;

        IF tFlutterDebounce.Q THEN
            bFlutterAlarm := TRUE;
            (* Aggressively open VAFN to reduce backpressure and stabilize flow *)
            rVAFN_ActuatorPosCmd := 100.0;
            (* Adjust Inlet Guide Vanes to counter cross-wind distortion *)
            rInletGuideVaneCmd := LIMIT(MIN:= -15.0, IN:= rCrossWindVel * 0.5, MAX:= 15.0);
        ELSE
            (* Normal VAFN tracking based on thrust command and fan speed *)
            rErrorMargin := rMainThrustCommand - rFilteredThrust;
            rVAFN_ActuatorPosCmd := LIMIT(MIN:= 10.0, IN:= 50.0 + (rErrorMargin * 0.2) + (rFanSpeedRPM * 0.001), MAX:= 100.0);
            rInletGuideVaneCmd := 0.0;
        END_IF;

        (* Sensor Fault Detection (e.g., negative force on X axis outside margin) *)
        IF rPiezoForceX < -10.0 THEN
            bThrustStandFault := TRUE;
            iState := 999;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        IF NOT bEmergencyStopOk THEN
            (* Wait for safety reset *)
        ELSIF bSystemEnable = FALSE AND bThrustStandFault = FALSE THEN
            iState := 0; (* Reset only if enable is dropped and fault is cleared *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

```iec-st
(*
version 1.5	13. mar. 2009
programmer 	oscat
tested by		hans

sequence_4 enables run when a low to high transition is present on start.
a low to high transition on start will restart the sequencer at any time while a rst will hold the sequencer in reset while true.
after run is enabled with a rising edge on start the sequencer waits for wait0 on in0 to enable q0 which stays on for delay0.
the next cycle starts with wait1, continues with delay 1 and so on...
if an edge is not detected during the wait period, the sequencer will then display the error number on the status output.
the status numbers 1..4 are errors in step 0..3.
after the last step that sets q3, the sequencer leaves q3 on for delay3 and then resets to the initial state.
a step output will indicate the current step of the sequencer and will also be present with a fault condition.
after the first output is turened on the sequencer switches from q0 to q1 and so on, at any time there is only one output enabled.
if an input signal is not detected during a wait period, the sequencer will display the error number ( 1 for in0, 2 for in1 .... ).
when an error is present and the config variable stop_on_error is set then the sequencer will stop. otherwise it will continue.
The status output will also display 110 for waiting and 111 for sequence running.
*)
FUNCTION_BLOCK SEQUENCE_4
VAR_INPUT
	in0 : BOOL := TRUE;
	in1 : BOOL := TRUE;
	in2 : BOOL := TRUE;
	in3 : BOOL := TRUE;
	start : BOOL;
	rst : BOOL;
	wait0 : TIME;
	delay0 : TIME;
	wait1 : TIME;
	delay1 : TIME;
	wait2 : TIME;
	delay2 : TIME;
	wait3 : TIME;
	delay3 : TIME;
END_VAR
VAR_INPUT CONSTANT
	stop_on_error : BOOL;
END_VAR
VAR_OUTPUT
	Q0 : BOOL;
	Q1 : BOOL;
	Q2 : BOOL;
	Q3 : BOOL;
	QX : BOOL;
	run: BOOL;
	step : INT := -1;
	status : BYTE;
END_VAR
VAR
	last : TIME;
	edge : BOOL;
	tx: TIME;
	init: BOOL;
END_VAR
(* read sps timer *)
tx := DWORD_TO_TIME(T_PLC_MS());

(* initialize on startup *)
IF NOT init THEN
	last := tx;
	init := TRUE;
	status := 110;
END_IF;

(* asynchronous reset *)
IF rst THEN
	step := -1;
	Q0 := 0;
	Q1 := 0;
	Q2 := 0;
	Q3 := 0;
	status := 110;
	run := 0;

(* edge on start input restarts the sequencer *)
ELSIF start AND NOT edge THEN
	step := 0;
	last := tx;
	status := 111;
	Q0 := 0;
	Q1 := 0;
	Q2 := 0;
	Q3 := 0;
	run := 1;
END_IF;
edge := start;

(* check if stop on status is necessary *)
IF status > 0 AND status < 100 AND stop_on_error THEN RETURN; END_IF;

(* sequence is running *)
IF run AND step = 0 THEN
	IF NOT q0 AND in0 AND tx - last <= wait0 THEN
		Q0 := TRUE;
		last := tx;
	ELSIF NOT q0 AND tx - last > wait0 THEN
		status := 1;
		run := FALSE;
	ELSIF q0 AND tx - last >= delay0 THEN
		step := 1;
		last := tx;
	END_IF;
END_IF;
IF run AND step = 1 THEN
	IF NOT q1 AND in1 AND tx - last <= wait1 THEN
		Q0 := FALSE;
		Q1 := TRUE;
		last := tx;
	ELSIF NOT q1 AND Tx - last > wait1 THEN
		status := 2;
		q0 := FALSE;
		run := FALSE;
	ELSIF q1 AND tx - last >= delay1 THEN
		step := 2;
		last := tx;
	END_IF;
END_IF;
IF run AND step = 2 THEN
	IF NOT q2 AND in2 AND tx - last <= wait2 THEN
		Q1 := FALSE;
		Q2 := TRUE;
		last := tx;
	ELSIF NOT q2 AND Tx - last > wait2 THEN
		status := 3;
		q1 := FALSE;
		run := FALSE;
	ELSIF q2 AND tx - last >= delay2 THEN
		step := 3;
		last := tx;
	END_IF;
END_IF;
IF run AND step = 3 THEN
	IF NOT q3 AND in3 AND tx - last <= wait3 THEN
		Q2 := FALSE;
		Q3 := TRUE;
		last := tx;
	ELSIF NOT q3 AND Tx - last > wait3 THEN
		status := 4;
		q2 := FALSE;
		run := FALSE;
	ELSIF q3 AND tx - last >= delay3 THEN
		step := -1;
		q3 := FALSE;
		run := FALSE;
		status := 110;
	END_IF;
END_IF;
QX := q0 OR q1 OR q2 OR q3;

(*
hm 1.10.06		rev 1.1
	corrected delay logic to be after event and not before
	added any output

hm 1.12.06		rev 1.2
	corrected failure in sequence logic.
	added init at startup to prevent from initial error after start.

hm 17.1.2007		rev 1.3
	changed output fault to status for better compatibility with other modules (ESR).
	added stop on error functionality and setup variable
	default for inputs in0..3 is true.
	renamed variable state to step

hm	17.sep 2007	rev 1.4
	replaced time() with T_PLC_MS() for compatibility reasons

hm	13. mar. 2009	rev 1.5
	renamed output any to qx for compatibility resons

*)
END_FUNCTION_BLOCK
```

