\nFUNCTION_BLOCK FB_PantographInspectionSys
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bSystemEnable : BOOL; // Enable the inspection system
    rTrainSpeed_Kmph : REAL; // Current train speed in km/h
    rTargetUpwardForce_N : REAL; // Desired aerodynamic upward force
    rMeasuredUpwardForce_N : REAL; // Actual measured upward force from load cells
    iUvSensorLevel : INT; // UV intensity from arc flash sensor (0-32767)
    rLaserStaggerPos_mm : REAL; // Contact wire stagger position measured by laser (-500.0 to 500.0 mm)
    rContactWireHeight_mm : REAL; // Contact wire height measured by laser
    bGpsSyncPulse : BOOL; // GPS 1PPS for synchronization
END_VAR
VAR_OUTPUT
    rForceControlValves_Pct : REAL; // Output to proportional valves for force control (0.0 - 100.0%)
    bArcFlashDetected : BOOL; // High level alarm for arc flash
    bArcFlashWarning : BOOL; // Warning level for minor arcing
    bStaggerOut_Of_Bounds : BOOL; // True if stagger exceeds safety limits
    iRecordedFaultCode : INT; // System fault code output
    bLoggingTrigger : BOOL; // Trigger for high-speed data acquisition
    rEffectiveStagger_mm : REAL; // Filtered stagger measurement
END_VAR
VAR
    rForceError_N : REAL; // Force error
    rForceIntegral_N : REAL; // Integral of force error
    rForceDerivative_N : REAL; // Derivative of force error
    rPrevForceError_N : REAL; // Previous force error for derivative calculation
    rKp : REAL := 0.5; // Proportional gain for force control
    rKi : REAL := 0.02; // Integral gain for force control
    rKd : REAL := 0.05; // Derivative gain for force control
    rMaxForceValve_Pct : REAL := 100.0;
    rMinForceValve_Pct : REAL := 0.0;

    // Filters
    rStaggerBuffer : ARRAY[0..9] OF REAL;
    iBufferIdx : INT := 0;
    rStaggerSum : REAL;
    i : INT;

    // Timers & Triggers
    tonArcFlashFilter : TON;
    tonStaggerFilter : TON;
    rMaxStaggerLimit_mm : REAL := 300.0; // Standard limit for stagger
    iArcWarningThreshold : INT := 5000;
    iArcFaultThreshold : INT := 25000;

    // Status
    bInitialized : BOOL := FALSE;
END_VAR

// Initialization
IF NOT bInitialized THEN
    FOR i := 0 TO 9 DO
        rStaggerBuffer[i] := 0.0;
    END_FOR;
    rForceIntegral_N := 0.0;
    rPrevForceError_N := 0.0;
    bInitialized := TRUE;
END_IF;

IF NOT bSystemEnable THEN
    rForceControlValves_Pct := 0.0;
    bArcFlashDetected := FALSE;
    bArcFlashWarning := FALSE;
    bStaggerOut_Of_Bounds := FALSE;
    iRecordedFaultCode := 0;
    bLoggingTrigger := FALSE;
    RETURN;
END_IF;

// 1. Pantograph Upward Force Active Tracking (PID Control)
rForceError_N := rTargetUpwardForce_N - rMeasuredUpwardForce_N;
rForceIntegral_N := rForceIntegral_N + rForceError_N;

// Anti-windup for integral
IF rForceIntegral_N > 1000.0 THEN
    rForceIntegral_N := 1000.0;
ELSIF rForceIntegral_N < -1000.0 THEN
    rForceIntegral_N := -1000.0;
END_IF;

rForceDerivative_N := rForceError_N - rPrevForceError_N;

rForceControlValves_Pct := (rKp * rForceError_N) + (rKi * rForceIntegral_N) + (rKd * rForceDerivative_N);

IF rForceControlValves_Pct > rMaxForceValve_Pct THEN
    rForceControlValves_Pct := rMaxForceValve_Pct;
ELSIF rForceControlValves_Pct < rMinForceValve_Pct THEN
    rForceControlValves_Pct := rMinForceValve_Pct;
END_IF;

rPrevForceError_N := rForceError_N;

// 2. Arc Flash UV Detection
IF iUvSensorLevel >= iArcFaultThreshold THEN
    tonArcFlashFilter(IN := TRUE, PT := T#10MS);
    IF tonArcFlashFilter.Q THEN
        bArcFlashDetected := TRUE;
        bLoggingTrigger := TRUE;
        iRecordedFaultCode := 101; // Severe Arc
    END_IF;
ELSE
    tonArcFlashFilter(IN := FALSE);
    bArcFlashDetected := FALSE;
END_IF;

IF iUvSensorLevel >= iArcWarningThreshold AND NOT bArcFlashDetected THEN
    bArcFlashWarning := TRUE;
ELSE
    bArcFlashWarning := FALSE;
END_IF;

// 3. Laser Wire Stagger Measurement (Moving Average Filter)
rStaggerBuffer[iBufferIdx] := rLaserStaggerPos_mm;
iBufferIdx := (iBufferIdx + 1) MOD 10;

rStaggerSum := 0.0;
FOR i := 0 TO 9 DO
    rStaggerSum := rStaggerSum + rStaggerBuffer[i];
END_FOR;
rEffectiveStagger_mm := rStaggerSum / 10.0;

// Stagger out of bounds detection
IF ABS(rEffectiveStagger_mm) > rMaxStaggerLimit_mm THEN
    tonStaggerFilter(IN := TRUE, PT := T#50MS);
    IF tonStaggerFilter.Q THEN
        bStaggerOut_Of_Bounds := TRUE;
        bLoggingTrigger := TRUE;
        IF iRecordedFaultCode = 0 THEN
            iRecordedFaultCode := 201; // Stagger Violation
        END_IF;
    END_IF;
ELSE
    tonStaggerFilter(IN := FALSE);
    bStaggerOut_Of_Bounds := FALSE;
END_IF;

// Reset fault code if nominal
IF NOT bArcFlashDetected AND NOT bStaggerOut_Of_Bounds THEN
    iRecordedFaultCode := 0;
    bLoggingTrigger := FALSE;
END_IF;

END_FUNCTION_BLOCK\n```
