FUNCTION_BLOCK "AGV_Traffic_Controller"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      agv_Position : Int;
      agv_BatteryLvl : Real;
      agv_DestNode : Int;
      agv_PayloadWeight : Real;
      sensor_WeightRaw1 : Real;
      sensor_WeightRaw2 : Real;
      node_Occupied : Array[1..20] of Bool;
      pn_CommStatus : Bool;
      scada_AuthToken : DWord;
      plc_IsPrimary : Bool;
      hil_SimMode : Bool;
      startup_Init : Bool;
   END_VAR

   VAR_OUTPUT 
      agv_GoToNode : Int;
      agv_SpeedCmd : Real;
      charge_Req : Bool;
      error_Sts : Bool;
      diag_Code : Word;
      pn_StatusWord : Word;
      hil_SyncOut : DWord;
   END_VAR

   VAR 
      auth_Valid : Bool;
      self_Test_Done : Bool;
      sensor_Drift : Real;
   END_VAR

   VAR_TEMP 
      max_Speed : Real;
      path_Found : Bool;
      next_Node : Int;
   END_VAR

BEGIN
    // Automated Startup Self-Test Routine
    IF #startup_Init AND NOT #self_Test_Done THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#T001; // Self-test running
        // Mock self-test
        #self_Test_Done := TRUE;
        RETURN;
    END_IF;

    // Adversarial Sensor Drift Detection
    #sensor_Drift := ABS(#sensor_WeightRaw1 - #sensor_WeightRaw2);
    IF #sensor_Drift > 5.0 AND NOT #hil_SimMode THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#E003; // Sensor drift fault
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // HIL Digital Twin Sync
    IF #hil_SimMode THEN
        #hil_SyncOut := REAL_TO_DWORD(#agv_SpeedCmd);
    END_IF;

    // Cybersecurity Access Control
    #auth_Valid := (#scada_AuthToken = 16#DEADBEEF);
    IF NOT #auth_Valid THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#F001; // Security violation
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // PLC Redundancy
    IF NOT #plc_IsPrimary THEN RETURN; END_IF;

    #diag_Code := 16#0000;

    // Profinet Comm
    IF NOT #pn_CommStatus THEN
        #agv_SpeedCmd := 0.0;
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // Dynamic Speed Limiting
    IF #agv_PayloadWeight > 1000.0 THEN #max_Speed := 0.5;
    ELSIF #agv_PayloadWeight > 500.0 THEN #max_Speed := 1.0;
    ELSE #max_Speed := 2.0; END_IF;

    // Battery
    IF #agv_BatteryLvl < 20.0 THEN
        #charge_Req := TRUE;
        #agv_DestNode := 1; 
    ELSE
        #charge_Req := FALSE;
    END_IF;

    // Routing & Avoidance
    #path_Found := FALSE;
    #next_Node := #agv_Position + 1; 
    IF #next_Node <= 20 THEN
        IF NOT #node_Occupied[#next_Node] THEN
            #agv_GoToNode := #next_Node;
            #agv_SpeedCmd := #max_Speed; 
            #path_Found := TRUE;
        ELSE
            #agv_SpeedCmd := 0.0; 
            #path_Found := FALSE;
            #diag_Code := 16#W001; 
        END_IF;
    END_IF;

    #error_Sts := (NOT #path_Found AND #agv_Position <> #agv_DestNode);
    #pn_StatusWord.%X0 := #error_Sts;
END_FUNCTION_BLOCK
