FUNCTION_BLOCK FB_TBM_Control_Core
TITLE = 'Tunnel Boring Machine Main Control - EPB and Erector Systems'
VERSION : '1.0'

VAR_INPUT
    // Cutterhead Variables
    rCutterheadSpeedReq : REAL;       // Requested cutterhead speed in RPM
    rCutterheadTorqueReq : REAL;      // Requested cutterhead torque limit (kNm)
    bEnableCutterhead : BOOL;         // Enable bit for cutterhead drives

    // Thrust Cylinders
    rAdvancementSpeedReq : REAL;      // Required advance rate (mm/min)
    rTotalThrustForceReq : REAL;      // Requested total thrust force (kN)

    // Earth Pressure Balance (EPB) Sensors
    rChamberPressure1 : REAL;         // Bulkhead pressure sensor 1 (bar)
    rChamberPressure2 : REAL;         // Bulkhead pressure sensor 2 (bar)
    rChamberPressure3 : REAL;         // Bulkhead pressure sensor 3 (bar)
    rChamberPressure4 : REAL;         // Bulkhead pressure sensor 4 (bar)
    rTargetEarthPressure : REAL;      // Target earth pressure to maintain (bar)

    // Foam Injection System
    rFoamExpansionRatio : REAL;       // FER required
    rFoamInjectionRatio : REAL;       // FIR required (%)
    bEnableFoamInjection : BOOL;      // Enable foam plant

    // Segment Erector
    rErectorPosTheta : REAL;          // Current angular position of erector (deg)
    rErectorPosZ : REAL;              // Current longitudinal position (mm)
    bErectorVacuumGrip : BOOL;        // Vacuum pad grip feedback
    bErectorStartAutoSequence : BOOL; // Start segment installation sequence
END_VAR

VAR_OUTPUT
    // Cutterhead Drives Output
    rCutterheadSpeedCmd : REAL;       // Command to VFDs (RPM)
    rCutterheadTorqueCmd : REAL;      // Torque command to VFDs (kNm)

    // Thrust Cylinders Output
    rThrustPressureGroupA : REAL;     // Thrust group A pressure (bar)
    rThrustPressureGroupB : REAL;     // Thrust group B pressure (bar)
    rThrustPressureGroupC : REAL;     // Thrust group C pressure (bar)
    rThrustPressureGroupD : REAL;     // Thrust group D pressure (bar)

    // EPB / Screw Conveyor Output
    rScrewConveyorSpeedCmd : REAL;    // Speed command to screw conveyor (RPM)
    bScrewConveyorEnable : BOOL;      // Enable screw conveyor

    // Foam Injection Output
    rAirFlowRateCmd : REAL;           // Air mass flow controller (NL/min)
    rSurfactantFlowCmd : REAL;        // Surfactant pump command (L/min)
    rWaterFlowCmd : REAL;             // Water pump command (L/min)

    // Segment Erector Output
    rErectorDriveThetaCmd : REAL;     // Erector rotational drive command
    rErectorDriveZCmd : REAL;         // Erector longitudinal drive command
    bErectorVacuumPumpOn : BOOL;      // Vacuum pump enable
    bSegmentSequenceActive : BOOL;    // Auto sequence active flag

    // General Status
    iSystemState : INT;               // Current machine state
    wErrorFlags : WORD;               // System error bits
END_VAR

VAR
    // Internal Variables
    rAvgChamberPressure : REAL;
    rPressureError : REAL;
    rScrewPIDIntegral : REAL;
    rScrewPIDDerivative : REAL;
    rPrevPressureError : REAL;
    rScrewP : REAL := 5.0;            // PID Proportional gain for EPB
    rScrewI : REAL := 0.2;            // PID Integral gain for EPB
    rScrewD : REAL := 0.1;            // PID Derivative gain for EPB

    rActualAdvanceRate : REAL;
    rExcavatedVolume : REAL;
    rCalculatedFoamVol : REAL;

    iErectorStep : INT := 0;
    rErectorTargetTheta : REAL;
    tErectorTimer : TIME;

    bInitDone : BOOL := FALSE;
END_VAR

// -----------------------------------------------------------------------------
// Initialization
// -----------------------------------------------------------------------------
IF NOT bInitDone THEN
    rScrewPIDIntegral := 0.0;
    rPrevPressureError := 0.0;
    iSystemState := 0; // 0 = Standby
    wErrorFlags := 0;
    bInitDone := TRUE;
END_IF;

// -----------------------------------------------------------------------------
// 1. Earth Pressure Balance (EPB) Control Loop
// -----------------------------------------------------------------------------
rAvgChamberPressure := (rChamberPressure1 + rChamberPressure2 + rChamberPressure3 + rChamberPressure4) / 4.0;
rPressureError := rAvgChamberPressure - rTargetEarthPressure;

// PI Control for screw conveyor
rScrewPIDIntegral := rScrewPIDIntegral + (rPressureError * 0.1); // Assuming 100ms cycle
IF rScrewPIDIntegral > 100.0 THEN rScrewPIDIntegral := 100.0; END_IF;
IF rScrewPIDIntegral < 0.0 THEN rScrewPIDIntegral := 0.0; END_IF;

rScrewPIDDerivative := (rPressureError - rPrevPressureError) / 0.1;
rScrewConveyorSpeedCmd := (rPressureError * rScrewP) + (rScrewPIDIntegral * rScrewI) + (rScrewPIDDerivative * rScrewD);

IF rScrewConveyorSpeedCmd > 30.0 THEN
    rScrewConveyorSpeedCmd := 30.0; 
ELSIF rScrewConveyorSpeedCmd < 0.0 THEN
    rScrewConveyorSpeedCmd := 0.0;
END_IF;

rPrevPressureError := rPressureError;

IF bEnableCutterhead AND rAvgChamberPressure > (rTargetEarthPressure * 0.5) THEN
    bScrewConveyorEnable := TRUE;
ELSE
    bScrewConveyorEnable := FALSE;
    rScrewConveyorSpeedCmd := 0.0;
END_IF;

// -----------------------------------------------------------------------------
// 2. Cutterhead and Thrust Vectoring
// -----------------------------------------------------------------------------
IF bEnableCutterhead THEN
    rCutterheadSpeedCmd := rCutterheadSpeedReq;
    rCutterheadTorqueCmd := rCutterheadTorqueReq;

    // Distribute thrust equally for straight alignment (simplified)
    rThrustPressureGroupA := rTotalThrustForceReq / 4.0;
    rThrustPressureGroupB := rTotalThrustForceReq / 4.0;
    rThrustPressureGroupC := rTotalThrustForceReq / 4.0;
    rThrustPressureGroupD := rTotalThrustForceReq / 4.0;
    iSystemState := 1; // 1 = Excavation
ELSE
    rCutterheadSpeedCmd := 0.0;
    rCutterheadTorqueCmd := 0.0;
    rThrustPressureGroupA := 0.0;
    rThrustPressureGroupB := 0.0;
    rThrustPressureGroupC := 0.0;
    rThrustPressureGroupD := 0.0;
    iSystemState := 0; // Standby
END_IF;

// -----------------------------------------------------------------------------
// 3. Foam Injection System (Conditioning)
// -----------------------------------------------------------------------------
IF bEnableFoamInjection AND bEnableCutterhead THEN
    rExcavatedVolume := (rAdvancementSpeedReq / 1000.0) * 50.0; 
    rCalculatedFoamVol := rExcavatedVolume * (rFoamInjectionRatio / 100.0) * 1000.0; 

    rAirFlowRateCmd := rCalculatedFoamVol * (1.0 - (1.0 / rFoamExpansionRatio));
    rWaterFlowCmd := (rCalculatedFoamVol / rFoamExpansionRatio) * 0.97;
    rSurfactantFlowCmd := (rCalculatedFoamVol / rFoamExpansionRatio) * 0.03;
ELSE
    rAirFlowRateCmd := 0.0;
    rWaterFlowCmd := 0.0;
    rSurfactantFlowCmd := 0.0;
END_IF;

// -----------------------------------------------------------------------------
// 4. Precast Segment Erector Sequencer
// -----------------------------------------------------------------------------
IF bErectorStartAutoSequence AND iSystemState = 0 THEN
    bSegmentSequenceActive := TRUE;
    iSystemState := 2; // 2 = Ring Build

    CASE iErectorStep OF
        0: // Move to pickup position
            rErectorTargetTheta := 180.0; 
            rErectorDriveThetaCmd := (rErectorTargetTheta - rErectorPosTheta) * 0.5;
            IF ABS(rErectorTargetTheta - rErectorPosTheta) < 1.0 THEN
                iErectorStep := 1;
            END_IF;

        1: // Activate Vacuum
            bErectorVacuumPumpOn := TRUE;
            IF bErectorVacuumGrip THEN
                iErectorStep := 2;
            END_IF;

        2: // Retract Z
            rErectorDriveZCmd := -10.0; 
            IF rErectorPosZ < 100.0 THEN
                rErectorDriveZCmd := 0.0;
                iErectorStep := 3;
            END_IF;

        3: // Rotate to placement position (e.g., top)
            rErectorTargetTheta := 0.0; 
            rErectorDriveThetaCmd := (rErectorTargetTheta - rErectorPosTheta) * 0.5;
            IF ABS(rErectorTargetTheta - rErectorPosTheta) < 1.0 THEN
                rErectorDriveThetaCmd := 0.0;
                iErectorStep := 4;
            END_IF;

        4: // Sequence Complete
            bSegmentSequenceActive := FALSE;
            bErectorStartAutoSequence := FALSE; 
            iErectorStep := 0;
            iSystemState := 0; 
    END_CASE;
ELSE
    IF NOT bSegmentSequenceActive THEN
        rErectorDriveThetaCmd := 0.0;
        rErectorDriveZCmd := 0.0;
        bErectorVacuumPumpOn := FALSE;
        iErectorStep := 0;
    END_IF;
END_IF;

// Safety and Error Handling
IF rAvgChamberPressure > (rTargetEarthPressure * 1.5) THEN
    wErrorFlags := wErrorFlags OR 16#0001; 
END_IF;

IF bSegmentSequenceActive AND NOT bErectorVacuumGrip AND iErectorStep > 1 THEN
    wErrorFlags := wErrorFlags OR 16#0002; 
    iErectorStep := 0; 
END_IF;

END_FUNCTION_BLOCK
