    rDO_SP                : REAL := 40.0; // Dissolved Oxygen Setpoint (%)
    rpH_SP                : REAL := 7.0;  // pH Setpoint
    rTemp_SP              : REAL := 37.0; // Temperature Setpoint (°C)

    // SIP Parameters
    bStartSIP             : BOOL;  // Start Sterilization in Place sequence
    rSIP_Temp_SP          : REAL := 121.1; // SIP Sterilization Temp
    tSIP_HoldTime         : TIME := T#30m; // SIP Hold Time

    // Limits
    rMaxTipSpeed          : REAL := 1.5;   // Maximum Tip Speed (m/s) to prevent shear damage
    rImpellerDiameter     : REAL := 0.25;  // Impeller diameter (m)
END_VAR

VAR_OUTPUT
    // Control Outputs (CV)
    rAgitatorSpeed_CV     : REAL;  // Agitator Speed Command (RPM)
    rO2_SpargeFlow_CV     : REAL;  // O2 Mass Flow Controller Command (0-100%)
    rAir_SpargeFlow_CV    : REAL;  // Air Mass Flow Controller Command (0-100%)
    rBase_Pump_CV         : REAL;  // Base Addition Pump Command (0-100%)
    rAcid_Pump_CV         : REAL;  // Acid Addition Pump Command (0-100%)
    rCooling_Valve_CV     : REAL;  // Cooling Water Valve Command (0-100%)
    rHeating_Valve_CV     : REAL;  // Heating Steam Valve Command (0-100%)

    // State and Status
    eSIP_State            : INT;   // SIP Sequence State (0=Idle, 1=Heating, 2=Holding, 3=Cooling, 4=Complete)
    bSIP_Complete         : BOOL;  // SIP completed successfully
    bShearAlarm           : BOOL;  // Shear stress alarm (Tip speed > Max limit)
END_VAR

VAR
    // PID Controllers (Assume FB_PID exists)
    fbPID_DO_Agitator     : FB_PID;
    fbPID_DO_O2           : FB_PID;
    fbPID_DO_Air          : FB_PID;
    fbPID_pH_Base         : FB_PID;
    fbPID_pH_Acid         : FB_PID;
    fbPID_Temp            : FB_PID;

    // Internal Variables
    rTipSpeed             : REAL;
    rAgitatorSpeed_MaxRPM : REAL;
    tSIP_Timer            : TON;
    rDO_Error             : REAL;
    rDO_Cascade_Output    : REAL;
END_VAR

// 1. Calculate Maximum Agitator RPM based on Shear Limit (Tip Speed)
// Tip Speed = pi * D * N / 60, where N is RPM, D is diameter in meters
// N = Tip Speed * 60 / (pi * D)
rAgitatorSpeed_MaxRPM := (rMaxTipSpeed * 60.0) / (3.14159 * rImpellerDiameter);

// Calculate current tip speed
rTipSpeed := (3.14159 * rImpellerDiameter * rAgitatorSpeed_PV) / 60.0;

IF rTipSpeed > rMaxTipSpeed THEN
    bShearAlarm := TRUE;
ELSE
    bShearAlarm := FALSE;
END_IF;

// 2. SIP (Sterilization In Place) State Machine
IF bStartSIP AND eSIP_State = 0 THEN
    eSIP_State := 1; // Heating
    bSIP_Complete := FALSE;
END_IF;

CASE eSIP_State OF
    0: // Idle
        rHeating_Valve_CV := 0.0;
        rCooling_Valve_CV := 0.0;

    1: // Heating Phase
        rHeating_Valve_CV := 100.0;
        rCooling_Valve_CV := 0.0;
        IF rTemp_PV >= rSIP_Temp_SP THEN
            eSIP_State := 2; // Holding Phase
        END_IF;

    2: // Holding Phase
        // Simple ON/OFF for holding temp, in reality PID would be used
        IF rTemp_PV < rSIP_Temp_SP THEN
            rHeating_Valve_CV := 50.0;
        ELSE
            rHeating_Valve_CV := 0.0;
        END_IF;

        tSIP_Timer(IN := TRUE, PT := tSIP_HoldTime);
        IF tSIP_Timer.Q THEN
            tSIP_Timer(IN := FALSE); // Reset timer
            eSIP_State := 3; // Cooling
        END_IF;

    3: // Cooling Phase
        rHeating_Valve_CV := 0.0;
        rCooling_Valve_CV := 100.0;
        IF rTemp_PV <= 37.0 THEN // Cool down to process temp
            eSIP_State := 4; // Complete
        END_IF;

    4: // Complete
        rCooling_Valve_CV := 0.0;
        bSIP_Complete := TRUE;
        IF NOT bStartSIP THEN
            eSIP_State := 0; // Reset to Idle
        END_IF;
END_CASE;

// 3. Process Control (Only run if not in SIP)
IF eSIP_State = 0 THEN

    // Temperature Control
    fbPID_Temp(
        EN := TRUE, 
        SP := rTemp_SP, 
        PV := rTemp_PV, 
        Kp := 2.5, 
        Ki := 0.1, 
        Kd := 0.0
    );
    IF fbPID_Temp.CV > 0.0 THEN
        rHeating_Valve_CV := fbPID_Temp.CV;
        rCooling_Valve_CV := 0.0;
    ELSE
        rHeating_Valve_CV := 0.0;
        rCooling_Valve_CV := ABS(fbPID_Temp.CV);
    END_IF;

    // pH Control (Split Range)
    fbPID_pH_Base(
        EN := TRUE,
        SP := rpH_SP,
        PV := rpH_PV,
        Kp := 1.5,
        Ki := 0.05
    );
    IF rpH_PV < rpH_SP THEN
        rBase_Pump_CV := fbPID_pH_Base.CV;
        rAcid_Pump_CV := 0.0;
    ELSIF rpH_PV > rpH_SP THEN
        rBase_Pump_CV := 0.0;
        rAcid_Pump_CV := ABS(fbPID_pH_Base.CV); // Assuming standard PID calculates negative CV for PV > SP
    END_IF;

    // DO (Dissolved Oxygen) Cascade Control
    rDO_Error := rDO_SP - rDO_PV;

    // Master DO PID Controller Output (0-100% Demand)
    fbPID_DO_Agitator(
        EN := TRUE,
        SP := rDO_SP,
        PV := rDO_PV,
        Kp := 1.0,
        Ki := 0.02
    );
    rDO_Cascade_Output := fbPID_DO_Agitator.CV; // Master DO Demand (0-100%)

    // Cascade Strategy:
    // 0-33%: Agitation
    // 33-66%: Air Sparging
    // 66-100%: Oxygen Sparging

    IF rDO_Cascade_Output <= 33.3 THEN
        // Agitation only
        rAgitatorSpeed_CV := (rDO_Cascade_Output / 33.3) * rAgitatorSpeed_MaxRPM;
        rAir_SpargeFlow_CV := 0.0;
        rO2_SpargeFlow_CV := 0.0;
    ELSIF rDO_Cascade_Output <= 66.6 THEN
        // Max Agitation + Air
        rAgitatorSpeed_CV := rAgitatorSpeed_MaxRPM;
        rAir_SpargeFlow_CV := ((rDO_Cascade_Output - 33.3) / 33.3) * 100.0; // 0-100% flow demand
        rO2_SpargeFlow_CV := 0.0;
    ELSE
        // Max Agitation + Max Air + Oxygen
        rAgitatorSpeed_CV := rAgitatorSpeed_MaxRPM;
        rAir_SpargeFlow_CV := 100.0;
        rO2_SpargeFlow_CV := ((rDO_Cascade_Output - 66.6) / 33.4) * 100.0;
    END_IF;

    // Clamp Agitator Speed for safety
    IF rAgitatorSpeed_CV > rAgitatorSpeed_MaxRPM THEN
        rAgitatorSpeed_CV := rAgitatorSpeed_MaxRPM;
    END_IF;

END_IF;
END_FUNCTION_BLOCK
