(*
================================================================================
Function Block: FB_3DConcretePrinterController
Description: 3D Concrete Printing Gantry Controller evolved from a basic CNC block.
It manages continuous extrusion slaved to X/Y velocity, slump monitoring with 
chemical accelerator dosing, and environmental compensation.
================================================================================
*)

FUNCTION_BLOCK FB_3DConcretePrinterController
VAR_INPUT
    // Gantry Kinematics
    rTargetVelX : REAL; // Commanded X axis velocity (mm/s)
    rTargetVelY : REAL; // Commanded Y axis velocity (mm/s)
    rActualVelX : REAL; // Actual X axis velocity from encoder (mm/s)
    rActualVelY : REAL; // Actual Y axis velocity from encoder (mm/s)

    // Slump Monitoring (Vision or Rheometer based)
    rTargetSlump : REAL; // Desired slump value (mm)
    rActualSlump : REAL; // Measured slump value (mm)

    // Environmental Sensors
    rWindSpeed : REAL; // Wind speed (m/s)
    rAmbientTemp : REAL; // Ambient temperature (Celsius)

    // Extrusion Specs
    rLayerHeight : REAL; // Layer height (mm)
    rNozzleDiameter : REAL; // Nozzle diameter (mm)

    bEnable : BOOL; // System enable
END_VAR

VAR_OUTPUT
    rPumpSpeedCmd : REAL; // Commanded concrete pump speed (RPM)
    rAcceleratorDosingCmd : REAL; // Commanded accelerator dosing rate (ml/s)
    rVelocityOverride : REAL; // Recommended Gantry velocity override (%)
    bExtrusionActive : BOOL;
    bAlarm : BOOL;
    sStatusMsg : STRING(50);
END_VAR

VAR
    // Internal States
    rCombinedVel : REAL; // Vector sum of X and Y velocity
    rBaseFlowRate : REAL; // Volumetric flow rate required (mm^3/s)
    rCuringFactor : REAL; // Factor affecting cure time

    // PID Controllers for Slump
    fbSlumpPID : PID; 

    // Constants
    cMaxPumpRPM : REAL := 1500.0;
    cBaseExtrusionConst : REAL := 1.25; // Tuning parameter for extrusion
END_VAR

IF NOT bEnable THEN
    rPumpSpeedCmd := 0.0;
    rAcceleratorDosingCmd := 0.0;
    rVelocityOverride := 100.0;
    bExtrusionActive := FALSE;
    sStatusMsg := 'SYSTEM DISABLED';
    RETURN;
END_IF;

(* 1. Continuous Concrete Extrusion Slaved to X/Y Velocity *)
// Calculate true vector velocity of the gantry
rCombinedVel := SQRT(EXPT(rActualVelX, 2) + EXPT(rActualVelY, 2));

// Calculate required volumetric flow rate: Velocity * Cross-section area
rBaseFlowRate := rCombinedVel * rLayerHeight * rNozzleDiameter * cBaseExtrusionConst;

// Map volumetric flow rate to pump RPM (Assume linear relationship for this block, normally requires polynomial calibration)
rPumpSpeedCmd := LIMIT(0.0, (rBaseFlowRate / 1000.0) * 50.0, cMaxPumpRPM);

bExtrusionActive := rPumpSpeedCmd > 0.0;

(* 2. Real-Time Slump Monitoring and Chemical Accelerator Dosing *)
// Use PID to adjust accelerator dosing to maintain slump
fbSlumpPID(
    ACTUAL := rActualSlump,
    SET_POINT := rTargetSlump,
    KP := 2.5,
    TN := T#5S,
    TV := T#0S,
    Y_MIN := 0.0,
    Y_MAX := 100.0,
    RESET := NOT bEnable
);

(* 3. Wind and Temperature Compensation for Curing Times *)
// High winds or high temperatures accelerate drying/curing
// We calculate a curing severity factor (1.0 = nominal, >1.0 = fast cure, <1.0 = slow cure)
rCuringFactor := 1.0;

IF rAmbientTemp > 25.0 THEN
    rCuringFactor := rCuringFactor + ((rAmbientTemp - 25.0) * 0.05); // 5% faster per degree above 25C
ELSIF rAmbientTemp < 15.0 THEN
    rCuringFactor := rCuringFactor - ((15.0 - rAmbientTemp) * 0.05); // 5% slower per degree below 15C
END_IF;

IF rWindSpeed > 5.0 THEN
    rCuringFactor := rCuringFactor + ((rWindSpeed - 5.0) * 0.1); // 10% faster per m/s over 5m/s
END_IF;

// Adjust dosing based on curing factor (e.g. if curing is fast, reduce accelerator)
rAcceleratorDosingCmd := LIMIT(0.0, fbSlumpPID.Y / rCuringFactor, 100.0);

// Adjust gantry speed if curing is too fast or slow
IF rCuringFactor > 1.5 THEN
    rVelocityOverride := 120.0; // Print faster to keep up with fast cure
    sStatusMsg := 'FAST CURE: OVERRIDE 120%';
ELSIF rCuringFactor < 0.7 THEN
    rVelocityOverride := 80.0; // Print slower to allow setting
    sStatusMsg := 'SLOW CURE: OVERRIDE 80%';
ELSE
    rVelocityOverride := 100.0;
    sStatusMsg := 'NOMINAL PRINTING';
END_IF;

// Failsafe alarms
IF rActualSlump > (rTargetSlump * 1.5) OR rActualSlump < (rTargetSlump * 0.5) THEN
    bAlarm := TRUE;
    sStatusMsg := 'CRITICAL SLUMP ALARM';
ELSE
    bAlarm := FALSE;
END_IF;
END_FUNCTION_BLOCK
