FUNCTION_BLOCK FB_AntiSurgeControl
TITLE = 'Centrifugal Compressor Anti-Surge Control'
VERSION : '2.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    rDischargePressure : REAL; (* Compressor Discharge Pressure (bar) *)
    rSuctionPressure : REAL; (* Compressor Suction Pressure (bar) *)
    rDischargeTemp : REAL; (* Compressor Discharge Temperature (K) *)
    rSuctionTemp : REAL; (* Compressor Suction Temperature (K) *)
    rMassFlow : REAL; (* Mass Flow Rate (kg/s) *)
    rMolecularWeight : REAL; (* Gas Molecular Weight (g/mol) *)
    rCompressibilityZ : REAL; (* Compressibility Factor *)
    rSpeed : REAL; (* Compressor Rotational Speed (RPM) *)
    bSurgeTestMode : BOOL; (* Manual Surge Test Activation *)
    bResetSurgeTrip : BOOL; (* Reset Surge Trip Flag *)
    bEnableHGBV : BOOL; (* Enable Hot Gas Bypass Valve Control *)
END_VAR

VAR_OUTPUT
    rHGBV_Position_Cmd : REAL; (* Commanded Position for HGB Valve (%) *)
    bSurgeDetected : BOOL; (* True if Transient Surge Detected *)
    bSurgeTrip : BOOL; (* Latching Trip output on prolonged surge *)
    rPolytropicHead : REAL; (* Calculated Polytropic Head (kJ/kg) *)
    rVolumetricFlow : REAL; (* Calculated Inlet Volumetric Flow (m3/s) *)
    rDistanceToSurge : REAL; (* Operating Point Distance to Surge Line (%) *)
END_VAR

VAR
    rCompressionRatio : REAL;
    rGasConstantR : REAL := 8.314; (* Universal Gas Constant J/(mol*K) *)
    rSpecificHeatRatio : REAL := 1.4; (* Gamma for diatomic gas approx *)
    rPolytropicExp : REAL;

    rSurgeLineFlow : REAL; (* Surge Line Flow at current Head *)
    rControlLineFlow : REAL; (* Control Line Flow (Surge + Margin) *)
    rSurgeMarginPct : REAL := 10.0; (* 10% Margin for Control Line *)
    rSurgeTripMarginPct : REAL := 2.0; (* 2% Margin for Surge Trip *)

    rKp : REAL := 2.5; (* PI Controller Proportional Gain *)
    rKi : REAL := 0.8; (* PI Controller Integral Gain *)
    rError : REAL;
    rIntegralSum : REAL := 0.0;

    timerSurgeTrip : TON;
    rDerivativeFlow : REAL;
    rLastFlow : REAL;
    tLastCycleTime : TIME;
END_VAR

(* Implementation details *)
BEGIN
    (* Calculate Gas Properties *)
    IF rSuctionPressure > 0.0 THEN
        rCompressionRatio := rDischargePressure / rSuctionPressure;
    ELSE
        rCompressionRatio := 1.0;
    END_IF;

    (* Volumetric Flow Calculation *)
    IF rSuctionPressure > 0.0 THEN
        rVolumetricFlow := (rMassFlow * rGasConstantR * rSuctionTemp * rCompressibilityZ) / (rMolecularWeight * rSuctionPressure * 100000.0);
    ELSE
        rVolumetricFlow := 0.0;
    END_IF;

    (* Polytropic Exponent and Head Calculation *)
    rPolytropicExp := (rSpecificHeatRatio - 1.0) / (rSpecificHeatRatio * 0.85); (* Assuming 85% polytropic efficiency *)
    IF rCompressionRatio > 1.0 THEN
        rPolytropicHead := (rCompressibilityZ * rGasConstantR * rSuctionTemp / rMolecularWeight) * (1.0 / rPolytropicExp) * (EXPT(rCompressionRatio, rPolytropicExp) - 1.0);
    ELSE
        rPolytropicHead := 0.0;
    END_IF;

    (* Surge Line Modeling - 2nd Order Polynomial: Flow = a*Head^2 + b*Head + c *)
    rSurgeLineFlow := (0.00005 * rPolytropicHead * rPolytropicHead) + (0.02 * rPolytropicHead) + 5.0;

    (* Control Line Generation *)
    rControlLineFlow := rSurgeLineFlow * (1.0 + (rSurgeMarginPct / 100.0));

    (* Distance to Surge *)
    IF rControlLineFlow > 0.0 THEN
        rDistanceToSurge := ((rVolumetricFlow - rSurgeLineFlow) / rSurgeLineFlow) * 100.0;
    ELSE
        rDistanceToSurge := 100.0;
    END_IF;

    (* Transient Surge Detection (High negative dF/dt) *)
    rDerivativeFlow := rVolumetricFlow - rLastFlow;
    rLastFlow := rVolumetricFlow;

    IF rDerivativeFlow < -15.0 THEN (* Threshold for sudden flow drop *)
        bSurgeDetected := TRUE;
    ELSE
        bSurgeDetected := FALSE;
    END_IF;

    (* PI Controller for HGB Valve *)
    rError := rControlLineFlow - rVolumetricFlow;

    IF rError > 0.0 THEN
        rIntegralSum := rIntegralSum + (rError * rKi * 0.1); (* Assuming 100ms cycle *)

        IF rIntegralSum > 100.0 THEN
            rIntegralSum := 100.0;
        END_IF;

        rHGBV_Position_Cmd := (rError * rKp) + rIntegralSum;
    ELSE
        rIntegralSum := rIntegralSum - 0.5; (* Gradual valve closure *)
        IF rIntegralSum < 0.0 THEN
            rIntegralSum := 0.0;
        END_IF;
        rHGBV_Position_Cmd := rIntegralSum;
    END_IF;

    (* Valve Position Limiting and Override *)
    IF NOT bEnableHGBV THEN
        rHGBV_Position_Cmd := 0.0;
        rIntegralSum := 0.0;
    END_IF;

    IF rHGBV_Position_Cmd > 100.0 THEN
        rHGBV_Position_Cmd := 100.0;
    ELSIF rHGBV_Position_Cmd < 0.0 THEN
        rHGBV_Position_Cmd := 0.0;
    END_IF;

    IF bSurgeDetected OR bSurgeTestMode THEN
        rHGBV_Position_Cmd := 100.0; (* Fast Open on Surge *)
    END_IF;

    (* Trip Logic *)
    timerSurgeTrip(IN := (rDistanceToSurge < rSurgeTripMarginPct) OR bSurgeDetected, PT := T#2S);

    IF timerSurgeTrip.Q THEN
        bSurgeTrip := TRUE;
    END_IF;

    IF bResetSurgeTrip THEN
        bSurgeTrip := FALSE;
    END_IF;

END_FUNCTION_BLOCK
