VAR_INPUT
    PN_IN : "PN_Data_In";
    Rectifier1_OK : Bool;
    Rectifier2_OK : Bool;
END_VAR
VAR_OUTPUT
    Rectifier1_Volt : Real;
    Rectifier2_Volt : Real;
