FUNCTION_BLOCK "Autoclave_Control"
VERSION : 0.3
   VAR_INPUT
      Start_Cycle : Bool;
      Temp_Chamber : Real;
      Press_Chamber : Real;
      Press_Jacket : Real;
      Door_Closed : Bool;
      Door_Locked : Bool;
      PN_Inputs : "PN_IO_Data";
   END_VAR
   VAR_OUTPUT
      Valve_Steam_In : Bool;
      Valve_Exhaust : Bool;
      Vacuum_Pump : Bool;
      Door_Lock_Cmd : Bool;
      Cycle_Complete : Bool;
      Alarm_Code : Int; // 0=OK, 1=Door Fault, 2=Heat Timeout, 3=Vacuum Fault
      F0_Value : Real;
   END_VAR
   VAR
      State : Int;
      Vac_Pulses : Int;
      Timer_Heat : TON_TIME;
   END_VAR
   CONST
      T_REF : Real := 121.1;
      Z_VAL : Real := 10.0;
   END_CONST

BEGIN
    // Fault Diagnostics & Interlock
    IF NOT Door_Closed THEN
        Door_Lock_Cmd := FALSE;
        Alarm_Code := 1;
        State := 0;
    ELSE
        Door_Lock_Cmd := TRUE;
    END_IF;

    // F0 Calculation
    IF Temp_Chamber >= 115.0 THEN
        F0_Value := F0_Value + ((10.0 ** ((Temp_Chamber - T_REF) / Z_VAL)) / 60.0);
    END_IF;

    // Timer for Diagnostics
    Timer_Heat(IN := (State = 1), PT := T#15M);
    IF Timer_Heat.Q THEN
        Alarm_Code := 2;
        State := 0;
    END_IF;

    CASE State OF
        0: // Idle
            Valve_Steam_In := FALSE;
            Valve_Exhaust := FALSE;
            Vacuum_Pump := FALSE;
            Cycle_Complete := FALSE;
            F0_Value := 0.0;
            IF Start_Cycle AND Door_Locked AND Alarm_Code = 0 THEN
                State := 10;
                Vac_Pulses := 0;
            END_IF;

        10: // Pre-vacuum
            Vacuum_Pump := TRUE;
            IF Press_Chamber <= 0.15 THEN
                Vacuum_Pump := FALSE;
                Valve_Steam_In := TRUE;
                IF Press_Chamber >= 1.2 THEN
                    Valve_Steam_In := FALSE;
                    Vac_Pulses := Vac_Pulses + 1;
                    IF Vac_Pulses >= 3 THEN State := 1; END_IF;
                END_IF;
            END_IF;

        1: // Heating
            Valve_Steam_In := (Press_Chamber < Press_Jacket + 0.1);
            IF Temp_Chamber >= 121.1 THEN State := 2; END_IF;

        2: // Sterilizing
            Valve_Steam_In := Temp_Chamber < 121.5;
            IF F0_Value >= 15.0 THEN State := 3; END_IF;

        3: // Exhaust
            Valve_Steam_In := FALSE;
            Valve_Exhaust := TRUE;
            IF Press_Chamber <= 1.05 THEN State := 30; END_IF;

        30: // Post-vacuum
            Valve_Exhaust := FALSE;
            Vacuum_Pump := TRUE;
            IF Press_Chamber <= 0.1 THEN State := 4; END_IF;

        4: // Complete
            Vacuum_Pump := FALSE;
            Cycle_Complete := TRUE;
            IF NOT Start_Cycle THEN State := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
