    rLastError            : REAL;
    rKp                   : REAL := 2.5;
    rKi                   : REAL := 0.15;
    rKd                   : REAL := 0.05;
    rPIDOut               : REAL;

    rMeltRateSetpoint     : REAL := 350.0; (* kg/hr *)
    rArcVoltageTarget     : REAL := 32.5;  (* V *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop OR rVacuumLevel_mBar > 1.0 THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rElectrodeFeed_mm_s := 0.0;
    rHeliumFlow_LPM := 100.0; (* Flood with helium for rapid cooling on abort *)
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

bAlarm := FALSE;

(* 1. Impedance Tracking (High-Current 20kA DC Arc) *)
IF rArcCurrent_kA > 0.1 THEN
    rImpedanceRaw := (rArcVoltage_V / rArcCurrent_kA); (* Returns mOhm if V / kA *)
    (* Simple low-pass filter for impedance *)
    rArcImpedance_mOhm := (rArcImpedance_mOhm * 0.9) + (rImpedanceRaw * 0.1);
ELSE
    rArcImpedance_mOhm := 0.0;
END_IF;

(* 2. Real-Time Consumable Electrode Melt Rate Calculation (dM/dt) *)
tDerivativeTimer(IN := NOT tDerivativeTimer.Q, PT := T#1S);
IF tDerivativeTimer.Q THEN
    rWeightDelta := rLastWeight_kg - rElectrodeWeight_kg;
    rLastWeight_kg := rElectrodeWeight_kg;
    (* Convert delta per second to kg/hr: delta * 3600 *)
    rFilteredMeltRate := (rFilteredMeltRate * 0.8) + ((rWeightDelta * 3600.0) * 0.2);
    rCalculatedMeltRate := rFilteredMeltRate;
END_IF;

(* 3. Main State Machine *)
CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := TRUE;
        rElectrodeFeed_mm_s := 0.0;
        rHeliumFlow_LPM := 0.0;
        IF bEnable THEN
            iState := 10;
            rLastWeight_kg := rElectrodeWeight_kg;
            rIntegral := 0.0;
            rLastError := 0.0;
        END_IF;

    10: (* IGNITION & STRIKE ARC *)
        bSystemReady := FALSE;
        (* Drive electrode down slowly until arc current spikes *)
        rElectrodeFeed_mm_s := -1.0; 
        IF rArcCurrent_kA > 2.0 THEN
            iState := 20;
        END_IF;

    20: (* MELTING (Melt Rate PID & Gap Control) *)
        rError := rMeltRateSetpoint - rCalculatedMeltRate;
        rIntegral := rIntegral + (rError * 1.0); (* 1s dt assumption from timer *)

        (* Anti-windup *)
        IF rIntegral > 500.0 THEN rIntegral := 500.0; END_IF;
        IF rIntegral < -500.0 THEN rIntegral := -500.0; END_IF;

        rDerivative := rError - rLastError;
        rLastError := rError;

        rPIDOut := (rKp * rError) + (rKi * rIntegral) + (rKd * rDerivative);

        (* Base speed from impedance/voltage plus melt rate trim *)
        rElectrodeFeed_mm_s := ((rArcVoltage_V - rArcVoltageTarget) * 0.5) + (rPIDOut * 0.01);

        (* Helium spot cooling crucible extraction profiling *)
        (* Apply more helium flow as crucible wall temp increases *)
        IF rCrucibleWallTemp_C > 400.0 THEN
            rHeliumFlow_LPM := (rCrucibleWallTemp_C - 400.0) * 0.5;
        ELSE
            rHeliumFlow_LPM := 5.0; (* Baseline cooling *)
        END_IF;

        (* Check completion condition *)
        IF rElectrodeWeight_kg < 50.0 THEN (* Stub weight reached *)
            iState := 30;
        END_IF;

        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    30: (* HOT-TOPPING *)
        rElectrodeFeed_mm_s := -0.1;
        (* Gradually reduce arc power via external block, handled externally here *)
        rHeliumFlow_LPM := 50.0;
        tMeltTimer(IN := TRUE, PT := T#30M);
        IF tMeltTimer.Q THEN
            tMeltTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* COOLING DOWN *)
        rElectrodeFeed_mm_s := 5.0; (* Retract electrode quickly *)
        rHeliumFlow_LPM := 150.0; (* Max flow for rapid ingot cooling *)
        IF rCrucibleBottomTemp_C < 100.0 THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        IF bEmergencyStop AND rVacuumLevel_mBar <= 1.0 AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;
iActiveState := iState;

END_FUNCTION_BLOCK
