FUNCTION_BLOCK FB_BlisterPackMachineControl
VAR_INPUT
    bEnable : BOOL; (* Main machine enable *)
    bEStop : BOOL; (* Emergency stop *)
    rHeatSealSetTemp : REAL := 155.0; (* Set temperature for sealing plates in deg C *)
    rHeatSealTolerance : REAL := 2.5; (* Allowable deviation from set temp *)
    lrMasterSpeedSync : LREAL; (* Master virtual axis speed *)

    (* Vision System I/O *)
    bVisionResultValid : BOOL;
    iPillCountDetected : INT;
    iPillColorCode : INT; (* 0 = Unknown, 1 = White, 2 = Blue, 3 = Red *)

    (* Servo I/O *)
    lrPunchPositionActual : LREAL;
    bPunchServoReady : BOOL;

    (* Heater I/O *)
    arHeatZonesActual : ARRAY[1..6] OF REAL; (* Actual temperatures from 6 zones *)
END_VAR

VAR_OUTPUT
    bMachineReady : BOOL;
    bError : BOOL;
    iErrorCode : INT;

    (* Outputs to Servos *)
    lrPunchPositionTarget : LREAL;
    bPunchServoEnable : BOOL;
    bPunchExecute : BOOL;

    (* Outputs to Heaters *)
    arHeaterPWM : ARRAY[1..6] OF REAL; (* 0-100% duty cycle for SSRs *)

    (* Reject Station *)
    bRejectBlister : BOOL;
END_VAR

VAR
    (* State Machine *)
    eState : (INIT, HEATING, WAIT_FOR_SYNC, RUNNING, FAULT);
    i : INT;

    (* PID Controllers for Heat Zones *)
    arHeaterPID_Kp : ARRAY[1..6] OF REAL := [6(5.0)];
    arHeaterPID_Ki : ARRAY[1..6] OF REAL := [6(0.1)];
    arHeaterPID_Kd : ARRAY[1..6] OF REAL := [6(0.05)];
    arHeaterPID_Error : ARRAY[1..6] OF REAL;
    arHeaterPID_ErrorPrev : ARRAY[1..6] OF REAL;
    arHeaterPID_Integral : ARRAY[1..6] OF REAL;

    bHeatersAtTemp : BOOL;

    (* Vision evaluation *)
    iExpectedPills : INT := 10;
    iExpectedColor : INT := 1; (* Expecting White pills *)

    (* Servo Sync *)
    lrPunchPhaseOffset : LREAL := 15.0; (* Phase shift in degrees *)
END_VAR

(* E-Stop Check *)
IF NOT bEStop THEN
    eState := FAULT;
    iErrorCode := 999;
END_IF

CASE eState OF
    INIT:
        bMachineReady := FALSE;
        bError := FALSE;
        iErrorCode := 0;
        bRejectBlister := FALSE;
        bPunchServoEnable := FALSE;

        FOR i := 1 TO 6 DO
            arHeaterPWM[i] := 0.0;
            arHeaterPID_Integral[i] := 0.0;
            arHeaterPID_ErrorPrev[i] := 0.0;
        END_FOR

        IF bEnable AND bEStop THEN
            eState := HEATING;
        END_IF

    HEATING:
        bHeatersAtTemp := TRUE;

        (* Execute PID for 6 heating zones *)
        FOR i := 1 TO 6 DO
            arHeaterPID_Error[i] := rHeatSealSetTemp - arHeatZonesActual[i];
            arHeaterPID_Integral[i] := arHeaterPID_Integral[i] + arHeaterPID_Error[i];

            (* Anti-windup *)
            IF arHeaterPID_Integral[i] > 1000.0 THEN arHeaterPID_Integral[i] := 1000.0; END_IF
            IF arHeaterPID_Integral[i] < -1000.0 THEN arHeaterPID_Integral[i] := -1000.0; END_IF

            arHeaterPWM[i] := (arHeaterPID_Kp[i] * arHeaterPID_Error[i]) + 
                              (arHeaterPID_Ki[i] * arHeaterPID_Integral[i]) + 
                              (arHeaterPID_Kd[i] * (arHeaterPID_Error[i] - arHeaterPID_ErrorPrev[i]));

            arHeaterPID_ErrorPrev[i] := arHeaterPID_Error[i];

            IF arHeaterPWM[i] > 100.0 THEN arHeaterPWM[i] := 100.0; END_IF
            IF arHeaterPWM[i] < 0.0 THEN arHeaterPWM[i] := 0.0; END_IF

            IF ABS(arHeaterPID_Error[i]) > rHeatSealTolerance THEN
                bHeatersAtTemp := FALSE;
            END_IF
        END_FOR

        IF bHeatersAtTemp THEN
            eState := WAIT_FOR_SYNC;
        END_IF

    WAIT_FOR_SYNC:
        bPunchServoEnable := TRUE;
        bMachineReady := TRUE;

        IF bPunchServoReady AND lrMasterSpeedSync > 0.0 THEN
            eState := RUNNING;
        END_IF

    RUNNING:
        (* Ensure temperature remains in bound *)
        FOR i := 1 TO 6 DO
            IF ABS(rHeatSealSetTemp - arHeatZonesActual[i]) > (rHeatSealTolerance * 2.0) THEN
                eState := FAULT;
                iErrorCode := 101; (* Heater deviation fault *)
            END_IF
        END_FOR

        (* Vision Inspection Logic *)
        IF bVisionResultValid THEN
            IF (iPillCountDetected <> iExpectedPills) OR (iPillColorCode <> iExpectedColor) THEN
                bRejectBlister := TRUE;
            ELSE
                bRejectBlister := FALSE;
            END_IF
        END_IF

        (* Punch Servo Camming / Synchronization *)
        (* Calculate target position based on master speed and phase offset *)
        lrPunchPositionTarget := (lrMasterSpeedSync * 1.5) + lrPunchPhaseOffset;
        IF lrPunchPositionTarget >= 360.0 THEN
            lrPunchPositionTarget := lrPunchPositionTarget - 360.0;
        END_IF
        bPunchExecute := TRUE;

        IF NOT bEnable THEN
            eState := INIT;
        END_IF

    FAULT:
        bMachineReady := FALSE;
        bPunchServoEnable := FALSE;
        bPunchExecute := FALSE;
        FOR i := 1 TO 6 DO
            arHeaterPWM[i] := 0.0;
        END_FOR
        bError := TRUE;

        IF NOT bEStop AND NOT bEnable THEN
            eState := INIT; (* Reset requirement *)
        END_IF
END_CASE
END_FUNCTION_BLOCK
