FUNCTION_BLOCK FB_AirJetLoomControl
TITLE = 'High-Speed Textile Air-Jet Loom Control System'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    bEnableOperation        : BOOL;
    bMachineRun             : BOOL;
    rMachineSpeed           : REAL;
    rMainShaftAngle         : REAL;
    rTargetWeftSpeed        : REAL;
    rMainNozzleStartAngle   : REAL;
    rMainNozzleDuration     : REAL;
    rRelayNozzleStartAngle  : REAL;
    rRelayNozzleDuration    : REAL;
    rSubNozzleDelay         : REAL;
    rTargetWarpTension      : REAL;
    rActualWarpTension      : REAL;
    rBeamDiameter           : REAL;
    rTargetPickDensity      : REAL;
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;
    bMainNozzleValve        : BOOL;
    bRelayNozzleBank1       : BOOL;
    bRelayNozzleBank2       : BOOL;
    bRelayNozzleBank3       : BOOL;
    bRelayNozzleBank4       : BOOL;
    bWeftCutterValve        : BOOL;
    rLetOffSpeedRef         : REAL;
    rTakeUpSpeedRef         : REAL;
    bFaultActive            : BOOL;
    iFaultCode              : INT;
END_VAR

VAR
    rTensionError           : REAL;
    rTensionErrorIntegral   : REAL;
    rTensionErrorDeriv      : REAL;
    rPrevTensionError       : REAL;
    rLetOffKp               : REAL := 2.5;
    rLetOffKi               : REAL := 0.15;
    rLetOffKd               : REAL := 0.05;
    rPIDOutput              : REAL;
    rCycleTimeS             : REAL := 0.001;
    rRelay1Start            : REAL;
    rRelay2Start            : REAL;
    rRelay3Start            : REAL;
    rRelay4Start            : REAL;
    rMaxTensionError        : REAL := 100.0;
    rMaxLetOffSpeed         : REAL := 3000.0;
END_VAR

IF NOT bEnableOperation THEN
    bSystemReady := FALSE;
    bMainNozzleValve := FALSE;
    bRelayNozzleBank1 := FALSE;
    bRelayNozzleBank2 := FALSE;
    bRelayNozzleBank3 := FALSE;
    bRelayNozzleBank4 := FALSE;
    bWeftCutterValve := FALSE;
    rLetOffSpeedRef := 0.0;
    rTakeUpSpeedRef := 0.0;
    bFaultActive := FALSE;
    iFaultCode := 0;
    RETURN;
END_IF;

bSystemReady := TRUE;

IF bMachineRun THEN
    IF (rMainShaftAngle >= rMainNozzleStartAngle) AND 
       (rMainShaftAngle <= (rMainNozzleStartAngle + rMainNozzleDuration)) THEN
        bMainNozzleValve := TRUE;
    ELSE
        bMainNozzleValve := FALSE;
    END_IF;

    rRelay1Start := rRelayNozzleStartAngle;
    rRelay2Start := rRelayNozzleStartAngle + rSubNozzleDelay;
    rRelay3Start := rRelayNozzleStartAngle + (2.0 * rSubNozzleDelay);
    rRelay4Start := rRelayNozzleStartAngle + (3.0 * rSubNozzleDelay);

    IF (rMainShaftAngle >= rRelay1Start) AND 
       (rMainShaftAngle <= (rRelay1Start + rRelayNozzleDuration)) THEN
        bRelayNozzleBank1 := TRUE;
    ELSE
        bRelayNozzleBank1 := FALSE;
    END_IF;

    IF (rMainShaftAngle >= rRelay2Start) AND 
       (rMainShaftAngle <= (rRelay2Start + rRelayNozzleDuration)) THEN
        bRelayNozzleBank2 := TRUE;
    ELSE
        bRelayNozzleBank2 := FALSE;
    END_IF;

    IF (rMainShaftAngle >= rRelay3Start) AND 
       (rMainShaftAngle <= (rRelay3Start + rRelayNozzleDuration)) THEN
        bRelayNozzleBank3 := TRUE;
    ELSE
        bRelayNozzleBank3 := FALSE;
    END_IF;

    IF (rMainShaftAngle >= rRelay4Start) AND 
       (rMainShaftAngle <= (rRelay4Start + rRelayNozzleDuration)) THEN
        bRelayNozzleBank4 := TRUE;
    ELSE
        bRelayNozzleBank4 := FALSE;
    END_IF;

    IF (rMainShaftAngle >= 330.0) AND (rMainShaftAngle <= 345.0) THEN
        bWeftCutterValve := TRUE;
    ELSE
        bWeftCutterValve := FALSE;
    END_IF;

ELSE
    bMainNozzleValve := FALSE;
    bRelayNozzleBank1 := FALSE;
    bRelayNozzleBank2 := FALSE;
    bRelayNozzleBank3 := FALSE;
    bRelayNozzleBank4 := FALSE;
    bWeftCutterValve := FALSE;
END_IF;

IF bMachineRun THEN
    rTensionError := rTargetWarpTension - rActualWarpTension;

    IF ABS(rTensionError) > rMaxTensionError THEN
        bFaultActive := TRUE;
        iFaultCode := 101;
    END_IF;

    IF NOT bFaultActive THEN
        rTensionErrorIntegral := rTensionErrorIntegral + (rTensionError * rCycleTimeS);
        IF rTensionErrorIntegral > 500.0 THEN rTensionErrorIntegral := 500.0; END_IF;
        IF rTensionErrorIntegral < -500.0 THEN rTensionErrorIntegral := -500.0; END_IF;
    END_IF;

    rTensionErrorDeriv := (rTensionError - rPrevTensionError) / rCycleTimeS;
    rPrevTensionError := rTensionError;

    rPIDOutput := (rLetOffKp * rTensionError) + 
                  (rLetOffKi * rTensionErrorIntegral) + 
                  (rLetOffKd * rTensionErrorDeriv);

    IF rBeamDiameter > 0.0 THEN
        rLetOffSpeedRef := ((rMachineSpeed / rTargetPickDensity) * 10.0 / (3.14159 * rBeamDiameter)) * 60.0; 
        rLetOffSpeedRef := rLetOffSpeedRef + rPIDOutput;
    ELSE
        bFaultActive := TRUE;
        iFaultCode := 102;
        rLetOffSpeedRef := 0.0;
    END_IF;

    IF rLetOffSpeedRef > rMaxLetOffSpeed THEN rLetOffSpeedRef := rMaxLetOffSpeed; END_IF;
    IF rLetOffSpeedRef < 0.0 THEN rLetOffSpeedRef := 0.0; END_IF;

ELSE
    rLetOffSpeedRef := 0.0;
    rTensionErrorIntegral := 0.0;
END_IF;

IF bMachineRun AND NOT bFaultActive THEN
    IF rTargetPickDensity > 0.0 THEN
        rTakeUpSpeedRef := rMachineSpeed / rTargetPickDensity; 
    ELSE
        bFaultActive := TRUE;
        iFaultCode := 103;
        rTakeUpSpeedRef := 0.0;
    END_IF;
ELSE
    rTakeUpSpeedRef := 0.0;
END_IF;
END_FUNCTION_BLOCK
