BEGIN
    // 1. Cybersecurity Check
    IF #SCADA_AccessKey <> 16#A1B2C3D4 THEN
        RETURN;
    END_IF;

    // 2. Sensor Drift Detection (Adversarial resilience)
    IF ABS(#Winch1_PN_IN.ActTorque - #Winch1_RedundantSensor) > #DriftThreshold THEN
        #SensorDriftFault := TRUE;
        #Winch1_PN_OUT.ControlWord := 16#0000; // Safe state
        RETURN;
    ELSE
        #SensorDriftFault := FALSE;
    END_IF;

    // 3. HIL Digital Twin Synchronization
    #HIL_Twin_Feedback := #Winch1_PN_IN.ActTorque;
    IF ABS(#Winch1_PN_IN.ActTorque - #HIL_Twin_Tension_Pred) > (#DriftThreshold * 2.0) THEN
        // Twin divergence - log diagnostic anomaly
    END_IF;

    // 4. Automated Self-Test Routine
    IF #SelfTest_Trigger THEN
        #SelfTestActive := TRUE;
        CASE #TestSequenceStep OF
            0: 
                #Winch1_PN_OUT.CmdTorque := 10.0; // Test pulse
                #TestSequenceStep := 1;
            1:
                IF #Winch1_PN_IN.ActTorque > 8.0 THEN
                    #TestSequenceStep := 2; // Pulse verified
                END_IF;
            2:
                #Winch1_PN_OUT.CmdTorque := 0.0;
                #SelfTestActive := FALSE;
                #TestSequenceStep := 0;
        END_CASE;
        RETURN;
    END_IF;

    // Core Control
    #Winch1_PN_OUT.ControlWord := 16#047F;
    #Winch1_PN_OUT.CmdTorque := #SCADA_ReqTotalTension / 4.0;
END_FUNCTION_BLOCK
