FUNCTION_BLOCK FB_TireBuildingMachine_MainControl
TITLE = 'TBM Master Controller - High Speed Kinematics & Pneumatics'
// This Function Block controls the core processes of a Tire Building Machine.
// It includes body ply drum expansion kinematics, bead apex setting pneumatics, 
// and laser contour tread application.

VAR_INPUT
    bEnableMachine          : BOOL;         // Global machine enable
    bStartCycle             : BOOL;         // Initiate automatic build cycle
    bEmergencyStop          : BOOL;         // E-Stop status (Active Low)
    rDrumDiameterTarget     : REAL;         // Target expansion diameter (mm)
    rBeadSettingPressureTarget : REAL;      // Target pressure for bead apex setting (Bar)
    rTreadSpeedSetpoint     : REAL;         // Tread application speed (mm/s)
    bLaserContourOk         : BOOL;         // Laser scanner confirms contour
    aTreadProfile           : ARRAY[0..99] OF REAL; // Laser profile feedback array
END_VAR

VAR_OUTPUT
    bMachineReady           : BOOL;         // Machine is ready for cycle
    bCycleInProgress        : BOOL;         // Build cycle is active
    bError                  : BOOL;         // Global error flag
    iErrorCode              : INT;          // Specific error code

    // Actuator Commands
    rDrumExpansionValve     : REAL;         // Proportional valve signal (0-10V)
    bBeadPneumaticSolenoidA : BOOL;         // Solenoid advance
    bBeadPneumaticSolenoidB : BOOL;         // Solenoid retract
    rTreadExtruderSpeedCmd  : REAL;         // Speed command to extruder drive
END_VAR

VAR
    iState                  : INT := 0;     // State machine step
    tStepTimer              : TON;          // Step timer
    rCurrentDrumDiameter    : REAL := 400.0;// Simulated current diameter
    rCurrentBeadPressure    : REAL := 0.0;  // Simulated current pressure
    i                       : INT;
    rProfileAverage         : REAL;
    rProfileSum             : REAL;
END_VAR

// Main State Machine
CASE iState OF
    0: // Initialization and Safety Check
        bMachineReady := FALSE;
        bCycleInProgress := FALSE;
        bError := FALSE;
        iErrorCode := 0;

        rDrumExpansionValve := 0.0;
        bBeadPneumaticSolenoidA := FALSE;
        bBeadPneumaticSolenoidB := TRUE;
        rTreadExtruderSpeedCmd := 0.0;

        IF bEmergencyStop AND bEnableMachine THEN
            bMachineReady := TRUE;
            IF bStartCycle THEN
                iState := 10; // Move to Drum Expansion
            END_IF;
        ELSIF NOT bEmergencyStop THEN
            bError := TRUE;
            iErrorCode := 999; // E-Stop pressed
        END_IF;

    10: // Body Ply Drum Expansion Kinematics
        bMachineReady := FALSE;
        bCycleInProgress := TRUE;

        // Simple PI loop simulation for drum expansion
        IF rCurrentDrumDiameter < rDrumDiameterTarget - 1.0 THEN
            rDrumExpansionValve := (rDrumDiameterTarget - rCurrentDrumDiameter) * 0.5; // P-Gain
            // Simulate physical response
            rCurrentDrumDiameter := rCurrentDrumDiameter + (rDrumExpansionValve * 0.1);
        ELSIF rCurrentDrumDiameter > rDrumDiameterTarget + 1.0 THEN
            rDrumExpansionValve := 0.0;
            bError := TRUE;
            iErrorCode := 101; // Overshoot error
            iState := 900;
        ELSE
            rDrumExpansionValve := 5.0; // Holding voltage
            tStepTimer(IN := TRUE, PT := T#2S);
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iState := 20; // Move to Bead Setting
            END_IF;
        END_IF;

    20: // Bead Apex Setting Pneumatics
        bBeadPneumaticSolenoidA := TRUE;
        bBeadPneumaticSolenoidB := FALSE;

        // Simulate pressure build-up
        rCurrentBeadPressure := rCurrentBeadPressure + 0.5;

        IF rCurrentBeadPressure >= rBeadSettingPressureTarget THEN
            tStepTimer(IN := TRUE, PT := T#1S); // Hold pressure for 1s
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iState := 30; // Move to Laser Contour Tread
            END_IF;
        END_IF;

        IF rCurrentBeadPressure > 10.0 THEN // Max safe pressure
            bError := TRUE;
            iErrorCode := 201; // Overpressure
            iState := 900;
        END_IF;

    30: // Laser Contour Tread Application
        // Analyze laser profile
        rProfileSum := 0.0;
        FOR i := 0 TO 99 DO
            rProfileSum := rProfileSum + aTreadProfile[i];
        END_FOR;
        rProfileAverage := rProfileSum / 100.0;

        IF bLaserContourOk AND rProfileAverage > 2.0 THEN
            rTreadExtruderSpeedCmd := rTreadSpeedSetpoint;
            tStepTimer(IN := TRUE, PT := T#5S); // Simulate extrusion time
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                rTreadExtruderSpeedCmd := 0.0;
                iState := 40; // Cycle Complete
            END_IF;
        ELSE
            bError := TRUE;
            iErrorCode := 301; // Laser contour invalid
            iState := 900;
        END_IF;

    40: // Cycle Complete Reset
        bCycleInProgress := FALSE;
        // Reset simulated values
        rCurrentDrumDiameter := 400.0;
        rCurrentBeadPressure := 0.0;
        bBeadPneumaticSolenoidA := FALSE;
        bBeadPneumaticSolenoidB := TRUE;
        iState := 0;

    900: // Fault State
        bCycleInProgress := FALSE;
        rDrumExpansionValve := 0.0;
        bBeadPneumaticSolenoidA := FALSE;
        bBeadPneumaticSolenoidB := TRUE;
        rTreadExtruderSpeedCmd := 0.0;

        IF NOT bStartCycle AND NOT bError THEN // Reset condition
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

