FUNCTION_BLOCK FB_ViralVector_CPC_Control
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal - Active HIGH means safe *)
    rRotorSpeed_RPM         : REAL;     (* Rotor speed in RPM *)
    rMobilePhaseFlow_Lmin   : REAL;     (* Mobile phase flow rate in L/min *)
    rSystemPressure_Bar     : REAL;     (* Hydrostatic cell pressure in Bar *)
    rUV280_Absorbance       : REAL;     (* UV 280 nm absorbance for elution peak cutting *)
    rTemperature_C          : REAL;     (* Cooling jacket temperature in deg C *)
    bPhaseInject            : BOOL;     (* Trigger for stationary phase injection *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is primed, pressurized, and ready for feed *)
    rRotorSpeedTarget       : REAL;     (* Output setpoint to rotor VFD *)
    rPumpFlowSetPoint       : REAL;     (* Output setpoint to mobile phase pump *)
    bFractionCollect        : BOOL;     (* Valve actuation for fraction collection (peak cutting) *)
    bAlarm                  : BOOL;     (* System fault / alarm active *)
    iStateOut               : INT;      (* Current step in the sequence for HMI *)
END_VAR
VAR
    iState                  : INT := 0;
    tTimerWait              : TON;
    tElutionTimer           : TON;

    (* Internal PID / Filter variables *)
    rFilteredPressure       : REAL := 0.0;
    rFilteredUV             : REAL := 0.0;

    (* Constants and Thresholds *)
    c_rMaxPressure          : REAL := 150.0;  (* Max allowable pressure bar *)
    c_rNominalRotorSpeed    : REAL := 2500.0; (* RPM *)
    c_rNominalFlow          : REAL := 1.5;    (* L/min *)
    c_rUVPeakThreshold      : REAL := 2.5;    (* mAU threshold for peak start *)
    c_rUVPeakEndThreshold   : REAL := 0.5;    (* mAU threshold for peak end *)
    c_rFilterAlpha          : REAL := 0.1;    (* Exponential smoothing factor *)
END_VAR

(* === MAIN LOGIC === *)
(* Emergency and Safety Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bFractionCollect := FALSE;
    rRotorSpeedTarget := 0.0;
    rPumpFlowSetPoint := 0.0;
    bAlarm := TRUE;
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* Sensor noise filtering via Exponential Moving Average (EMA) *)
rFilteredPressure := (c_rFilterAlpha * rSystemPressure_Bar) + ((1.0 - c_rFilterAlpha) * rFilteredPressure);
rFilteredUV := (c_rFilterAlpha * rUV280_Absorbance) + ((1.0 - c_rFilterAlpha) * rFilteredUV);

(* Overpressure interlock *)
IF rFilteredPressure > c_rMaxPressure THEN
    bSystemReady := FALSE;
    bFractionCollect := FALSE;
    rRotorSpeedTarget := 0.0;
    rPumpFlowSetPoint := 0.0;
    bAlarm := TRUE;
    iState := 999; 
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE - Awaiting Master Enable *)
        bSystemReady := FALSE;
        bFractionCollect := FALSE;
        bAlarm := FALSE;
        rRotorSpeedTarget := 0.0;
        rPumpFlowSetPoint := 0.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* PRIMING & ROTOR ACCELERATION *)
        (* Ramp up rotor to create hydrostatic retention *)
        rRotorSpeedTarget := c_rNominalRotorSpeed;
        IF ABS(rRotorSpeed_RPM - c_rNominalRotorSpeed) < 50.0 THEN
            (* Wait for hydrodynamic equilibrium *)
            tTimerWait(IN := TRUE, PT := T#30S);
            IF tTimerWait.Q THEN
                tTimerWait(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tTimerWait(IN := FALSE);
        END_IF;

    20: (* STATIONARY PHASE INJECTION *)
        IF bPhaseInject THEN
            rPumpFlowSetPoint := c_rNominalFlow * 0.5; (* Slow flow for phase loading *)
            tTimerWait(IN := TRUE, PT := T#60S);
            IF tTimerWait.Q THEN
                tTimerWait(IN := FALSE);
                iState := 30;
            END_IF;
        END_IF;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* MOBILE PHASE EQUILIBRATION *)
        rPumpFlowSetPoint := c_rNominalFlow;
        bSystemReady := TRUE;
        (* Await sample injection event implicitly handled by UV monitoring *)
        IF rFilteredUV > c_rUVPeakThreshold THEN
            iState := 40;
        END_IF;

    40: (* ELUTION AND PEAK CUTTING *)
        bSystemReady := FALSE;
        bFractionCollect := TRUE; (* Divert to product collection *)

        (* Fallback timer in case peak doesn't fall naturally *)
        tElutionTimer(IN := TRUE, PT := T#5M);

        IF (rFilteredUV < c_rUVPeakEndThreshold) OR tElutionTimer.Q THEN
            tElutionTimer(IN := FALSE);
            bFractionCollect := FALSE;
            iState := 50;
        END_IF;

    50: (* WASH & SHUTDOWN *)
        rPumpFlowSetPoint := c_rNominalFlow * 1.5; (* High flow wash *)
        tTimerWait(IN := TRUE, PT := T#2M);
        IF tTimerWait.Q THEN
            tTimerWait(IN := FALSE);
            iState := 0; 
        END_IF;

    999: (* FAULT HANDLING *)
        bAlarm := TRUE;
        bSystemReady := FALSE;
        bFractionCollect := FALSE;
        rRotorSpeedTarget := 0.0;
        rPumpFlowSetPoint := 0.0;
        (* Requires reset of Enable to clear fault *)
        IF NOT bEnable AND bEmergencyStop AND (rFilteredPressure <= c_rMaxPressure) THEN
            iState := 0;
        END_IF;
END_CASE;

iStateOut := iState;

END_FUNCTION_BLOCK
