FUNCTION_BLOCK FB_LithographyStepper
VAR_INPUT
    bEnableSystem          : BOOL;  (* Master enable for the stepper system *)
    bEmergencyStop         : BOOL;  (* Safety relay status, must be TRUE to operate *)
    rWaferXPos             : LREAL; (* Sub-nanometer X position feedback from laser interferometer *)
    rWaferYPos             : LREAL; (* Sub-nanometer Y position feedback from laser interferometer *)
    rFocusCapacitance      : LREAL; (* Capacitive gauge feedback for Z-axis autofocus *)
    rTargetXPos            : LREAL; (* Target X position for the exposure field *)
    rTargetYPos            : LREAL; (* Target Y position for the exposure field *)
    rTargetDose            : REAL;  (* Required UV exposure dose in mJ/cm^2 *)
    rLampIntensity         : REAL;  (* Real-time mercury lamp intensity feedback in mW/cm^2 *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;  (* TRUE when system is homed, aligned, and ready for exposure *)
    rCmdXVelocity          : LREAL; (* Command velocity for X-axis piezo stage *)
    rCmdYVelocity          : LREAL; (* Command velocity for Y-axis piezo stage *)
    rCmdZPosition          : LREAL; (* Command position for Z-axis voice coil autofocus *)
    bShutterOpen           : BOOL;  (* TRUE to open the exposure shutter *)
    rAccumulatedDose       : REAL;  (* Current accumulated exposure dose for the field *)
    bExposureComplete      : BOOL;  (* TRUE when target dose is reached *)
    bFaultAlarm            : BOOL;  (* System fault alarm *)
END_VAR
VAR
    iState                 : INT := 0; (* Stepper state machine *)
    rPosErrorX             : LREAL;
    rPosErrorY             : LREAL;
    rPosErrorTolerance     : LREAL := 0.000001; (* 1 nm tolerance *)
    rFocusError            : LREAL;
    rFocusTarget           : LREAL := 50.0; (* 50 pF nominal gap target *)
    rFocusTolerance        : LREAL := 0.05;
    tDoseTimer             : TON;
    tSettleTimer           : TON;
    rLastCycleTime         : REAL := 0.001; (* 1ms cycle time *)
END_VAR

(* === MAIN SAFETY INTERLOCK === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bShutterOpen := FALSE;
    rCmdXVelocity := 0.0;
    rCmdYVelocity := 0.0;
    bFaultAlarm := TRUE;
    iState := 0;
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bExposureComplete := FALSE;
        bShutterOpen := FALSE;
        rAccumulatedDose := 0.0;
        bFaultAlarm := FALSE;
        IF bEnableSystem THEN
            iState := 10;
        END_IF;

    10: (* XY STAGE POSITIONING *)
        rPosErrorX := rTargetXPos - rWaferXPos;
        rPosErrorY := rTargetYPos - rWaferYPos;

        (* Proportional control for piezo stages *)
        rCmdXVelocity := rPosErrorX * 5000.0;
        rCmdYVelocity := rPosErrorY * 5000.0;

        IF (ABS(rPosErrorX) < rPosErrorTolerance) AND (ABS(rPosErrorY) < rPosErrorTolerance) THEN
            rCmdXVelocity := 0.0;
            rCmdYVelocity := 0.0;
            tSettleTimer(IN := TRUE, PT := T#50MS);
            IF tSettleTimer.Q THEN
                tSettleTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tSettleTimer(IN := FALSE);
        END_IF;

    20: (* Z-AXIS AUTOFOCUS *)
        rFocusError := rFocusTarget - rFocusCapacitance;
        rCmdZPosition := rCmdZPosition + (rFocusError * 0.01);

        IF ABS(rFocusError) < rFocusTolerance THEN
            bSystemReady := TRUE;
            iState := 30;
        END_IF;

    30: (* EXPOSURE EXECUTION *)
        bShutterOpen := TRUE;
        (* Integrate dose: intensity (mW/cm^2) * time (s) = mJ/cm^2 *)
        rAccumulatedDose := rAccumulatedDose + (rLampIntensity * rLastCycleTime);

        IF rAccumulatedDose >= rTargetDose THEN
            bShutterOpen := FALSE;
            bExposureComplete := TRUE;
            bSystemReady := FALSE;
            iState := 40;
        END_IF;

    40: (* POST-EXPOSURE CLEANUP *)
        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    ELSE
        bFaultAlarm := TRUE;
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
```

