FUNCTION_BLOCK FB_AsepticCartonFiller_AdvancedControl
VAR_INPUT
    bEnable : BOOL; // Enable machine operation
    bEStop : BOOL; // Emergency stop active low
    rSetDosingVol : REAL; // Target volume in ml
    rBathTempSetpoint : REAL; // H2O2 bath temperature setpoint
    rH2O2ConcentrationSP : REAL; // Target H2O2 concentration %
    rWebSpeedSetpoint : REAL; // Web speed mm/s
    bMaterialAvailable : BOOL; // Packaging material presence
    bCleanInPlace : BOOL; // CIP sequence active
    rUltrasoundFreqSP : REAL; // Target sealing frequency Hz
    rUltrasoundPowerSP : REAL; // Target sealing power W
END_VAR
VAR_OUTPUT
    bReady : BOOL; // Machine is ready for production
    bFault : BOOL; // Global fault indicator
    rActualVol : REAL; // Actual dosed volume
    rBathTempActual : REAL; // Current bath temperature
    bSealQualityOK : BOOL; // Seal integrity check passed
    iCartonsProduced : DINT; // Production counter
    sStatusMessage : STRING[80]; // HMI status message
    rCurrentWebSpeed : REAL; // Actual web tracking speed
    bSterilizationOK : BOOL; // Sterilization criteria met
END_VAR
VAR
    iState : INT := 0; // State machine step
    tonHeating : TON; // Heating delay timer
    tonSterilization : TON; // Bath exposure timer
    tonSealing : TON; // Ultrasonic seal timer

    // Servo Dosing variables
    rServoPos : REAL; // Servo axis position
    rServoVel : REAL; // Servo axis velocity
    bServoMoveDone : BOOL; // Move complete flag

    // Ultrasonic sealing variables
    rUSFrequency : REAL := 20000.0;
    rUSPower : REAL := 0.0;

    // Sterilization bath
    rBathLevel : REAL;
    bHeaterOn : BOOL;
    bH2O2PumpOn : BOOL;

    // Fault tracking
    iFaultCode : INT := 0;
END_VAR

// ==============================================================================
// Main State Machine for Aseptic Carton Filling
// ==============================================================================

// E-Stop evaluation (Highest Priority)
IF NOT bEStop THEN
    iState := 99; // Fault state for E-Stop
    bFault := TRUE;
    sStatusMessage := 'CRITICAL: E-STOP ACTIVE';
    iFaultCode := 1001;
END_IF;

CASE iState OF
    0: // Idle State
        bReady := FALSE;
        bFault := FALSE;
        bHeaterOn := FALSE;
        bH2O2PumpOn := FALSE;
        rCurrentWebSpeed := 0.0;

        IF bEnable AND bMaterialAvailable AND NOT bCleanInPlace THEN
            iState := 10;
            sStatusMessage := 'SYS_START: HEATING BATH';
        ELSIF bCleanInPlace THEN
            sStatusMessage := 'SYS_MODE: CIP ACTIVE';
        ELSE
            sStatusMessage := 'SYS_MODE: STANDBY';
        END_IF;

    10: // H2O2 Bath Heating and Concentration Control Cascade
        bHeaterOn := (rBathTempActual < rBathTempSetpoint);
        bH2O2PumpOn := TRUE; 

        IF rBathTempActual >= (rBathTempSetpoint - 2.0) THEN
            tonHeating(IN := TRUE, PT := T#5S); 
            IF tonHeating.Q THEN
                iState := 20;
                tonHeating(IN := FALSE);
                bSterilizationOK := TRUE;
                sStatusMessage := 'SYS_PREP: STERILIZING WEB';
            END_IF;
        ELSE
            tonHeating(IN := FALSE);
            bSterilizationOK := FALSE;
        END_IF;

    20: // Sterilization web tracking synchronization
        IF rCurrentWebSpeed < rWebSpeedSetpoint THEN
            rCurrentWebSpeed := rCurrentWebSpeed + 5.0; 
        END_IF;

        tonSterilization(IN := TRUE, PT := T#10S); 
        IF tonSterilization.Q THEN
            iState := 30;
            bReady := TRUE;
            sStatusMessage := 'SYS_RUN: DOSING & SEALING';
        END_IF;

    30: // Volumetric Servo Dosing and Longitudinal Ultrasonic Sealing
        rCurrentWebSpeed := rWebSpeedSetpoint;
        rServoVel := 500.0; 
        rActualVol := rSetDosingVol; 
        bServoMoveDone := TRUE;

        rUSPower := rUltrasoundPowerSP;
        rUSFrequency := rUltrasoundFreqSP;

        tonSealing(IN := TRUE, PT := T#2S); 
        IF tonSealing.Q THEN
            tonSealing(IN := FALSE);
            bSealQualityOK := (rUSPower >= (rUltrasoundPowerSP * 0.95));
            IF bSealQualityOK AND bServoMoveDone THEN
                iCartonsProduced := iCartonsProduced + 1;
            END_IF;
            IF NOT bEnable THEN
                iState := 0; 
            END_IF;
        END_IF;

    99: // Global Fault Handler
        bReady := FALSE;
        rCurrentWebSpeed := 0.0;
        bHeaterOn := FALSE;
        bH2O2PumpOn := FALSE;
        rUSPower := 0.0;

        IF bEStop AND NOT bEnable THEN
            iState := 0; 
            bFault := FALSE;
            iFaultCode := 0;
            sStatusMessage := 'SYS_READY: FAULT CLEARED';
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
