FUNCTION_BLOCK FB_PumpedStorage_ModeSwitcher
TITLE = 'Pumped-Storage Plant Mode Switcher - 500MW Francis Turbine'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Data Architect'

// Description:
// State machine for transitioning a 500MW Francis Turbine from Generating to Pumping mode.
// Handles draft tube water depression via compressed air and SFC synchronization.

TYPE
    E_PumpStorageState : (
        STATE_IDLE,
        STATE_GEN_SHUTDOWN,
        STATE_WAIT_STANDSTILL,
        STATE_DRAFT_TUBE_DEPRESSION,
        STATE_SFC_STARTUP,
        STATE_SFC_SYNCHRONIZATION,
        STATE_PUMP_MODE_RAMP_UP,
        STATE_PUMP_MODE_ACTIVE,
        STATE_FAULT
    );
END_TYPE

VAR_INPUT
    bStartModeSwitch     : BOOL; // Command to switch from Gen to Pump
    bTurbineStandstill   : BOOL; // Speed < 1% nominal
    rTurbineSpeed        : REAL; // Current Speed (RPM)
    bWaterLevelDepressed : BOOL; // Draft tube water level below runner
    bSFC_Ready           : BOOL; // Static Frequency Converter ready
    bSFC_Synchronized    : BOOL; // SFC phase/frequency match with grid
    bGridBreakerClosed   : BOOL; // Main grid breaker status
    bFault_Reset         : BOOL; // Reset faults
END_VAR

VAR_OUTPUT
    eCurrentState        : E_PumpStorageState;
    bCmdCloseWicketGates : BOOL;
    bCmdOpenAirValves    : BOOL; // Compressed air into draft tube
    bCmdSFC_Start        : BOOL; // Start SFC for reverse rotation
    bCmdCloseGridBreaker : BOOL;
    rTargetSpeed         : REAL; 
    bModeSwitchComplete  : BOOL;
    bErrorActive         : BOOL;
    sStatusMsg           : STRING[50];
END_VAR

VAR
    eState               : E_PumpStorageState := STATE_IDLE;
    tDepressionTimer     : TON;
    tSFCSyncTimer        : TON;
END_VAR

BEGIN
    // Handle fault reset
    IF bFault_Reset THEN
        bErrorActive := FALSE;
        eState := STATE_IDLE;
    END_IF;

    // Main State Machine
    CASE eState OF

        STATE_IDLE:
            sStatusMsg := 'Idle / Gen Mode';
            bModeSwitchComplete := FALSE;
            bCmdCloseWicketGates := FALSE;
            bCmdOpenAirValves := FALSE;
            bCmdSFC_Start := FALSE;

            IF bStartModeSwitch AND NOT bErrorActive THEN
                eState := STATE_GEN_SHUTDOWN;
            END_IF;

        STATE_GEN_SHUTDOWN:
            sStatusMsg := 'Shutting down Generator';
            bCmdCloseWicketGates := TRUE; // Close wicket gates to stop water flow

            IF bCmdCloseWicketGates THEN
                eState := STATE_WAIT_STANDSTILL;
            END_IF;

        STATE_WAIT_STANDSTILL:
            sStatusMsg := 'Waiting for Turbine Standstill';
            IF bTurbineStandstill THEN
                eState := STATE_DRAFT_TUBE_DEPRESSION;
            ELSIF rTurbineSpeed < 5.0 THEN
                // Optional braking logic can be engaged here
            END_IF;

        STATE_DRAFT_TUBE_DEPRESSION:
            sStatusMsg := 'Depressing Draft Tube Water';
            bCmdOpenAirValves := TRUE; // Inject compressed air

            // Wait for water level to drop below runner
            tDepressionTimer(IN := TRUE, PT := T#5M);

            IF bWaterLevelDepressed THEN
                tDepressionTimer(IN := FALSE);
                eState := STATE_SFC_STARTUP;
            ELSIF tDepressionTimer.Q THEN
                sStatusMsg := 'FAULT: Depression Timeout';
                eState := STATE_FAULT;
            END_IF;

        STATE_SFC_STARTUP:
            sStatusMsg := 'Starting SFC (Reverse Rotation)';
            IF bSFC_Ready THEN
                bCmdSFC_Start := TRUE;
                rTargetSpeed := 428.6; // Nominal pump speed in RPM
                eState := STATE_SFC_SYNCHRONIZATION;
            END_IF;

        STATE_SFC_SYNCHRONIZATION:
            sStatusMsg := 'SFC Syncing with Grid';
            tSFCSyncTimer(IN := TRUE, PT := T#10M);

            IF bSFC_Synchronized THEN
                tSFCSyncTimer(IN := FALSE);
                bCmdCloseGridBreaker := TRUE;
                eState := STATE_PUMP_MODE_RAMP_UP;
            ELSIF tSFCSyncTimer.Q THEN
                sStatusMsg := 'FAULT: SFC Sync Timeout';
                eState := STATE_FAULT;
            END_IF;

        STATE_PUMP_MODE_RAMP_UP:
            sStatusMsg := 'Ramping up Pump Mode';
            IF bGridBreakerClosed THEN
                // Release compressed air, open wicket gates to start pumping
                bCmdOpenAirValves := FALSE; 
                bCmdSFC_Start := FALSE; // SFC disconnects after grid tie
                eState := STATE_PUMP_MODE_ACTIVE;
            END_IF;

        STATE_PUMP_MODE_ACTIVE:
            sStatusMsg := 'Pumping Mode Active';
            bModeSwitchComplete := TRUE;

        STATE_FAULT:
            bErrorActive := TRUE;
            bCmdCloseWicketGates := TRUE;
            bCmdOpenAirValves := FALSE;
            bCmdSFC_Start := FALSE;

    END_CASE;

    eCurrentState := eState;
END_FUNCTION_BLOCK
