FUNCTION_BLOCK FB_ScissorLiftAdvancedControl
TITLE = 'Commercial Scissor Lift Table - Advanced Control'
VERSION : '1.0'

(* 
   Highly complex control scenario for a commercial scissor lift table.
   Features:
   - Proportional hydraulic valve dynamic damping
   - Regenerative lowering energy capture
   - Off-center payload imbalance detection using four load cells
*)

VAR_INPUT
    bEnable : BOOL; // Enable system
    bRaiseRequest : BOOL; // Request to raise the lift
    bLowerRequest : BOOL; // Request to lower the lift
    rTargetPosition_mm : REAL; // Target height in mm
    rActualPosition_mm : REAL; // Actual height from linear encoder
    rLoadCell_FL_kg : REAL; // Front-Left load cell
    rLoadCell_FR_kg : REAL; // Front-Right load cell
    rLoadCell_RL_kg : REAL; // Rear-Left load cell
    rLoadCell_RR_kg : REAL; // Rear-Right load cell
    rHydraulicPressure_bar : REAL; // System hydraulic pressure
    rRegenBatteryVoltage_V : REAL; // Regenerative battery voltage
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL; // System is ready and fault-free
    rPropValveCommand_V : REAL; // 0-10V command to proportional valve
    bRegenValveEnable : BOOL; // Enable regenerative lowering path
    bAlarmImbalance : BOOL; // Load imbalance detected
    bAlarmOverload : BOOL; // Total load exceeds capacity
    bAlarmPressure : BOOL; // Hydraulic pressure anomaly
    rEstimatedMass_kg : REAL; // Total estimated mass
    sStatusMessage : STRING[50]; // Status string
END_VAR

VAR
    // Internal States
    eState : (INIT, IDLE, RAISING, LOWERING, DAMPING, FAULT) := INIT;

    // Imbalance Detection
    rTotalLoad : REAL;
    rCOG_X : REAL;
    rCOG_Y : REAL;
    rMaxAllowedImbalance : REAL := 15.0; // % deviation allowed

    // Proportional Damping
    rPositionError : REAL;
    rPrevPositionError : REAL;
    rIntegralError : REAL;
    rDerivativeError : REAL;
    rKp : REAL := 0.05;
    rKi : REAL := 0.001;
    rKd : REAL := 0.02;
    rValveOffset : REAL := 5.0; // Midpoint for spool

    // Regenerative Energy Capture
    rMinRegenVoltage : REAL := 22.0;
    rMaxRegenVoltage : REAL := 28.5;
    bRegenActive : BOOL;

    // Timers
    TMR_Damping : TON;
    TMR_FaultDelay : TON;
END_VAR

VAR_CONSTANT
    cMaxLoadCapacity_kg : REAL := 2000.0;
    cMaxPressure_bar : REAL := 250.0;
    cPositionTolerance_mm : REAL := 2.0;
END_VAR

// -----------------------------------------------------------------------------
// 1. Load Calculation and Imbalance Detection
// -----------------------------------------------------------------------------
rTotalLoad := rLoadCell_FL_kg + rLoadCell_FR_kg + rLoadCell_RL_kg + rLoadCell_RR_kg;
rEstimatedMass_kg := rTotalLoad;

IF rTotalLoad > 10.0 THEN
    // Normalize coordinates -1 to 1 based on load distribution
    rCOG_X := ((rLoadCell_FR_kg + rLoadCell_RR_kg) - (rLoadCell_FL_kg + rLoadCell_RL_kg)) / rTotalLoad;
    rCOG_Y := ((rLoadCell_FL_kg + rLoadCell_FR_kg) - (rLoadCell_RL_kg + rLoadCell_RR_kg)) / rTotalLoad;

    IF (ABS(rCOG_X) > (rMaxAllowedImbalance/100.0)) OR (ABS(rCOG_Y) > (rMaxAllowedImbalance/100.0)) THEN
        bAlarmImbalance := TRUE;
    ELSE
        bAlarmImbalance := FALSE;
    END_IF;
ELSE
    rCOG_X := 0.0;
    rCOG_Y := 0.0;
    bAlarmImbalance := FALSE;
END_IF;

IF rTotalLoad > cMaxLoadCapacity_kg THEN
    bAlarmOverload := TRUE;
ELSE
    bAlarmOverload := FALSE;
END_IF;

IF rHydraulicPressure_bar > cMaxPressure_bar THEN
    bAlarmPressure := TRUE;
ELSE
    bAlarmPressure := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 2. State Machine and Dynamic Control
// -----------------------------------------------------------------------------
IF NOT bEnable OR bAlarmOverload OR bAlarmPressure THEN
    eState := FAULT;
END_IF;

CASE eState OF
    INIT:
        rPropValveCommand_V := rValveOffset; // Neutral
        bRegenValveEnable := FALSE;
        bSystemReady := FALSE;
        IF bEnable AND NOT bAlarmOverload AND NOT bAlarmPressure THEN
            eState := IDLE;
        END_IF;
        sStatusMessage := 'Initializing';

    IDLE:
        rPropValveCommand_V := rValveOffset;
        bRegenValveEnable := FALSE;
        bSystemReady := TRUE;

        IF bAlarmImbalance THEN
            sStatusMessage := 'IDLE - Imbalance Detected';
        ELSE
            sStatusMessage := 'IDLE - Ready';
            IF bRaiseRequest AND NOT bLowerRequest THEN
                eState := RAISING;
            ELSIF bLowerRequest AND NOT bRaiseRequest THEN
                eState := LOWERING;
            END_IF;
        END_IF;

    RAISING:
        bSystemReady := TRUE;
        bRegenValveEnable := FALSE;
        rPositionError := rTargetPosition_mm - rActualPosition_mm;

        IF rPositionError <= cPositionTolerance_mm THEN
            eState := DAMPING;
        ELSIF NOT bRaiseRequest THEN
            eState := IDLE;
        ELSE
            // PID Control for Proportional Valve
            rIntegralError := rIntegralError + rPositionError;
            rDerivativeError := rPositionError - rPrevPositionError;

            rPropValveCommand_V := rValveOffset + (rKp * rPositionError) + (rKi * rIntegralError) + (rKd * rDerivativeError);

            // Clamp output
            IF rPropValveCommand_V > 10.0 THEN rPropValveCommand_V := 10.0; END_IF;
            IF rPropValveCommand_V < rValveOffset THEN rPropValveCommand_V := rValveOffset; END_IF; // Cannot lower in raise state

            sStatusMessage := 'RAISING';
        END_IF;
        rPrevPositionError := rPositionError;

    LOWERING:
        bSystemReady := TRUE;
        rPositionError := rActualPosition_mm - rTargetPosition_mm; // Positive means we need to go down

        // Regenerative Energy Capture Logic
        IF rRegenBatteryVoltage_V < rMaxRegenVoltage THEN
            bRegenActive := TRUE;
            bRegenValveEnable := TRUE;
        ELSE
            bRegenActive := FALSE;
            bRegenValveEnable := FALSE;
        END_IF;

        IF rPositionError <= cPositionTolerance_mm THEN
            eState := DAMPING;
        ELSIF NOT bLowerRequest THEN
            eState := IDLE;
        ELSE
            // PID Control for Lowering (Inverse of raising)
            rIntegralError := rIntegralError + rPositionError;
            rDerivativeError := rPositionError - rPrevPositionError;

            // Valve command goes below offset to lower
            rPropValveCommand_V := rValveOffset - ((rKp * rPositionError) + (rKi * rIntegralError) + (rKd * rDerivativeError));

            // Apply dynamic damping factor if regen is active (slower response)
            IF bRegenActive THEN
                rPropValveCommand_V := rPropValveCommand_V * 0.85; 
            END_IF;

            // Clamp output
            IF rPropValveCommand_V < 0.0 THEN rPropValveCommand_V := 0.0; END_IF;
            IF rPropValveCommand_V > rValveOffset THEN rPropValveCommand_V := rValveOffset; END_IF;

            sStatusMessage := 'LOWERING (Regen Active)';
        END_IF;
        rPrevPositionError := rPositionError;

    DAMPING:
        // Settle the mechanical structure dynamically
        TMR_Damping(IN:=TRUE, PT:=T#2S);
        rPropValveCommand_V := rValveOffset; // Neutral

        IF TMR_Damping.Q THEN
            TMR_Damping(IN:=FALSE);
            eState := IDLE;
        END_IF;
        sStatusMessage := 'DAMPING';

    FAULT:
        rPropValveCommand_V := rValveOffset; // Neutral
        bRegenValveEnable := FALSE;
        bSystemReady := FALSE;
        bRegenActive := FALSE;
        sStatusMessage := 'FAULT STATE';

        IF NOT bEnable THEN
            eState := INIT; // Reset via enable toggle
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

