`iec-st
FUNCTION_BLOCK FB_MassDriverLaunchControl
VAR_INPUT
    (* System Operation and Commands *)
    bSystemEnable           : BOOL;     (* Main power and control enable signal *)
    bLaunchCommand          : BOOL;     (* Initiate the complex launch sequence *)
    bTrackClearInterlock    : BOOL;     (* SIL-3 certified track clear optical interlock status *)
    bCryoQuenchDetect       : BOOL;     (* Fast-acting superconducting quench detection signal *)

    (* Physical Measurements and Sensor Inputs *)
    rAccelTarget_G          : REAL;     (* Target acceleration profile in Gs (e.g., 100.0) *)
    rCryoTemp_K             : REAL;     (* Superconducting magnet temperature in Kelvin *)
    rLinearVelocity_mps     : REAL;     (* Current projectile velocity in m/s via laser Doppler *)
    rCapacitorBankVoltage_V : REAL;     (* Primary energy storage voltage level *)
END_VAR
VAR_OUTPUT
    (* System Status and Actuation *)
    bLaunchReady            : BOOL;     (* System is fully charged and ready for launch commit *)
    bLaunchInProgress       : BOOL;     (* Active propulsion phase active *)
    rLIM_PhaseCmd_A         : REAL;     (* Pulsed linear induction motor phase current command (Amps) *)
    bDumpEnergyTrigger      : BOOL;     (* Cryogenic quench-protection energy dump activation *)
    rActualAccel_G          : REAL;     (* Filtered actual acceleration (G) for telemetry *)
    bCriticalFault          : BOOL;     (* System abort or hardware fault indication *)
END_VAR
VAR
    (* Internal State and Mathematical Filtering *)
    iLaunchState            : INT := 0; (* Mission phase state machine index *)
    tLaunchTimeout          : TON;      (* Maximum duration constraint for active launch phase *)
    rPrevVelocity           : REAL := 0.0;
    rRawAccel               : REAL;
    rAlphaFilter            : REAL := 0.2; (* Low-pass exponential smoothing coefficient for acceleration *)

    (* Control Loop Variables *)
    rError                  : REAL;
    rIntegral               : REAL;
    rProportional           : REAL;
    rKp                     : REAL := 150.5; (* Tuning parameter: Proportional gain *)
    rKi                     : REAL := 20.1;  (* Tuning parameter: Integral gain *)

    (* Physical Constants and Thresholds *)
    rMAX_TEMP_K             : REAL := 4.5;    (* Liquid helium temp threshold for superconducting state *)
    rMIN_VOLTAGE_V          : REAL := 12000.0;(* Minimum required capacitor bank voltage (12 kV) *)
    rMAX_PHASE_A            : REAL := 50000.0;(* 50 kA absolute thermal current limit *)
    rGRAVITY_MPS2           : REAL := 9.80665;(* Standard Earth gravity for acceleration normalization *)
END_VAR

(* === MAIN SAFETY AND SIGNAL PROCESSING === *)
(* Calculate actual acceleration via numeric derivative of velocity, then convert to standard Gs *)
rRawAccel := (rLinearVelocity_mps - rPrevVelocity) / 0.01; (* Assuming a deterministic 10ms task cycle time *)
rPrevVelocity := rLinearVelocity_mps;

(* Apply exponential moving average filter for noise rejection on acceleration reading *)
rActualAccel_G := (rAlphaFilter * (rRawAccel / rGRAVITY_MPS2)) + ((1.0 - rAlphaFilter) * rActualAccel_G);

(* Immediate Safety Interlocks: Thermal Quench or Track Obstruction *)
IF bCryoQuenchDetect OR (rCryoTemp_K > rMAX_TEMP_K) THEN
    bCriticalFault := TRUE;
    bDumpEnergyTrigger := TRUE; (* Dump extreme energy to protect multi-million dollar superconducting magnets *)
    iLaunchState := 999;        (* TRANSITION TO UNRECOVERABLE FAULT STATE *)
    rLIM_PhaseCmd_A := 0.0;
    bLaunchReady := FALSE;
    bLaunchInProgress := FALSE;
END_IF;

IF NOT bTrackClearInterlock AND iLaunchState <> 999 THEN
    bCriticalFault := TRUE;
    iLaunchState := 999; (* Obstruction detected -> immediately fault *)
END_IF;

IF NOT bSystemEnable THEN
    iLaunchState := 0;
    bLaunchReady := FALSE;
    bDumpEnergyTrigger := FALSE;
    rLIM_PhaseCmd_A := 0.0;
    bLaunchInProgress := FALSE;
    bCriticalFault := FALSE;
END_IF;

(* === ELECTROMAGNETIC LAUNCH SEQUENCE STATE MACHINE === *)
CASE iLaunchState OF
    0: (* IDLE & SYSTEM INITIALIZATION *)
        rLIM_PhaseCmd_A := 0.0;
        rIntegral := 0.0;
        bLaunchReady := FALSE;
        bLaunchInProgress := FALSE;
        tLaunchTimeout(IN := FALSE);

        IF bSystemEnable AND NOT bCriticalFault THEN
            iLaunchState := 10;
        END_IF;

    10: (* CHARGING & PRE-LAUNCH COMMUTATION CHECK *)
        IF rCapacitorBankVoltage_V >= rMIN_VOLTAGE_V AND rCryoTemp_K <= 4.2 THEN
            bLaunchReady := TRUE;
        ELSE
            bLaunchReady := FALSE;
        END_IF;

        IF bLaunchReady AND bLaunchCommand THEN
            bLaunchReady := FALSE;
            bLaunchInProgress := TRUE;
            iLaunchState := 20;
        END_IF;

    20: (* ACTIVE LAUNCH PROFILE - PI LOOP CONTROL FOR 100G SHAPING *)
        tLaunchTimeout(IN := TRUE, PT := T#5S); (* Max 5 sec launch window, beyond which we abort *)

        (* Compute error between desired 100G target and actual measured G force *)
        rError := rAccelTarget_G - rActualAccel_G;
        rIntegral := rIntegral + (rError * 0.01); (* 10ms integration delta time *)

        rProportional := rKp * rError;
        rLIM_PhaseCmd_A := rProportional + (rKi * rIntegral);

        (* Anti-Windup and Absolute Limit Clamping for Phase Current *)
        IF rLIM_PhaseCmd_A > rMAX_PHASE_A THEN
            rLIM_PhaseCmd_A := rMAX_PHASE_A;
        ELSIF rLIM_PhaseCmd_A < 0.0 THEN
            rLIM_PhaseCmd_A := 0.0; (* Uni-directional forward propulsion only, no regenerative braking during launch *)
        END_IF;

        (* Phase termination checks *)
        IF tLaunchTimeout.Q OR (rLinearVelocity_mps >= 8000.0) THEN
            (* Launch complete or timeout triggered, orbital velocity achieved (8 km/s) *)
            rLIM_PhaseCmd_A := 0.0;
            bLaunchInProgress := FALSE;
            iLaunchState := 30;
            tLaunchTimeout(IN := FALSE);
        END_IF;

    30: (* POST-LAUNCH COOLDOWN & SYSTEM RESET *)
        rLIM_PhaseCmd_A := 0.0;
        IF NOT bLaunchCommand THEN
            iLaunchState := 0; (* Return to idle state for next launch cycle *)
        END_IF;

    999: (* FAULT HANDLING & EMERGENCY SAFE STATE *)
        rLIM_PhaseCmd_A := 0.0;
        bLaunchReady := FALSE;
        bLaunchInProgress := FALSE;
        (* System locked until manual supervisory reset clears the physical fault *)

END_CASE;

END_FUNCTION_BLOCK
