BEGIN
    // 1. Dissolved Oxygen Cascade & Power Override
    #DO_PID(Setpoint := #DO_SP, Input := #DO_PV, Reset := #Reset, Output => #DO_Control_Out);

    IF #DO_Control_Out <= 50.0 THEN
        #Agitator_Speed_SP := (#DO_Control_Out / 50.0) * 200.0; 
        #Air_Flow_SP := 10.0; 
    ELSE
        #Agitator_Speed_SP := 200.0; 
        #Air_Flow_SP := 10.0 + ((#DO_Control_Out - 50.0) / 50.0) * 190.0; 
    END_IF;

    IF #Agitator_Power_PV > #Power_Max THEN
        #Agitator_Speed_SP := #Agitator_Speed_SP * (#Power_Max / #Agitator_Power_PV);
    END_IF;

    // 2. pH Control (Split Range Dosing)
    #pH_PID(Setpoint := #pH_SP, Input := #pH_PV, Reset := #Reset, Output => #pH_Control_Out); // Range: -100 to +100

    IF #pH_Control_Out < 0.0 THEN
        // Acid Required
        #Acid_PWM(INV := ABS(#pH_Control_Out), CYCLE := T#5s, Q => #Acid_Pump_Cmd);
