        // Base Required
        #Base_PWM(INV := #pH_Control_Out, CYCLE := T#5s, Q => #Base_Pump_Cmd);
        #Acid_Pump_Cmd := FALSE;
    END_IF;

    // 3. Foam Control based on Conductivity Sensor Delay
    #Foam_Timer(IN := #Foam_Level_Sensor, PT := T#3s);
    #Antifoam_Pump_Cmd := #Foam_Timer.Q;

END_FUNCTION_BLOCK
This mutation incorporates a `PID_Compact` block operating in bipolar mode (-100 to 100%) for pH, routed to independent PWM functions for the Acid and Base pumps. A timer debounce is applied to the conductivity-based foam sensor to prevent spurious antifoam injections.
