\nFUNCTION_BLOCK FB_VacuumDistillationUnit
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    rFeedFlowRate : REAL; (* Crude oil feed flow rate kg/h *)
    rFeedTemp : REAL; (* Feed temperature before furnace C *)
    rFurnaceOutletTemp : REAL; (* Temperature leaving furnace C *)
    rVacuumPressure : REAL; (* Vacuum column top pressure mmHg absolute *)
    rRefluxFlow : REAL; (* Top reflux flow rate kg/h *)
    rSteamInjectionRate : REAL; (* Stripping steam rate kg/h *)
    bEjector1Status : BOOL; (* Stage 1 vacuum ejector status *)
    bEjector2Status : BOOL; (* Stage 2 vacuum ejector status *)
    bEjector3Status : BOOL; (* Stage 3 vacuum ejector status *)
END_VAR

VAR_OUTPUT
    rLVGODrawRate : REAL; (* Light Vacuum Gas Oil draw rate kg/h *)
    rHVGODrawRate : REAL; (* Heavy Vacuum Gas Oil draw rate kg/h *)
    rVRBottomsRate : REAL; (* Vacuum Residue bottoms rate kg/h *)
    rFurnaceFuelValveCmd : REAL; (* 0-100% fuel gas valve command *)
    rRefluxValveCmd : REAL; (* 0-100% reflux valve command *)
    bAlarmHighTemp : BOOL;
    bAlarmLowVacuum : BOOL;
    bTripInterlock : BOOL;
END_VAR

VAR
    rTargetFurnaceTemp : REAL := 390.0; (* C *)
    rTargetVacuumPressure : REAL := 15.0; (* mmHg *)
    rTempError : REAL;
    rVacuumError : REAL;

    (* PID variables for furnace temp *)
    rKp_Temp : REAL := 2.5;
    rKi_Temp : REAL := 0.1;
    rFurnaceIntegral : REAL := 0.0;

    (* PID variables for reflux *)
    rKp_Reflux : REAL := 1.2;
    rKi_Reflux : REAL := 0.05;
    rRefluxIntegral : REAL := 0.0;
END_VAR

(* Interlock and Alarms *)
bAlarmHighTemp := (rFurnaceOutletTemp > 410.0);
bAlarmLowVacuum := (rVacuumPressure > 35.0);

IF bAlarmHighTemp OR bAlarmLowVacuum OR NOT (bEjector1Status AND bEjector2Status) THEN
    bTripInterlock := TRUE;
ELSE
    bTripInterlock := FALSE;
END_IF;

IF bTripInterlock THEN
    rFurnaceFuelValveCmd := 0.0;
    rRefluxValveCmd := 100.0;
    rLVGODrawRate := 0.0;
    rHVGODrawRate := 0.0;
    rVRBottomsRate := rFeedFlowRate;
    RETURN;
END_IF;

(* Furnace Temperature PID Control *)
rTempError := rTargetFurnaceTemp - rFurnaceOutletTemp;
rFurnaceIntegral := rFurnaceIntegral + (rTempError * 0.1);
IF rFurnaceIntegral > 100.0 THEN rFurnaceIntegral := 100.0; END_IF;
IF rFurnaceIntegral < 0.0 THEN rFurnaceIntegral := 0.0; END_IF;
rFurnaceFuelValveCmd := (rKp_Temp * rTempError) + (rKi_Temp * rFurnaceIntegral);
IF rFurnaceFuelValveCmd > 100.0 THEN rFurnaceFuelValveCmd := 100.0; END_IF;
IF rFurnaceFuelValveCmd < 0.0 THEN rFurnaceFuelValveCmd := 0.0; END_IF;

