FUNCTION_BLOCK "BESS_Advanced_Thermal"
VAR_INPUT
    NumCells : INT;
    CellVoltages : ARRAY[1..100] OF REAL;
    CellSoC : ARRAY[1..100] OF REAL;
    CellTemps : ARRAY[1..100] OF REAL;
