FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bStartSequence : BOOL; // Command to start transition
    eTargetMode : INT; // 0=Standstill, 1=Turbine, 2=Pump, 3=Synchronous Condenser
    rPenstockPressure : REAL; // Current penstock pressure [bar]
