    rMaxPressureChangeRate : REAL := 5.0; // Max allowed dp/dt for water hammer [bar/s]
    rNominalSpeed : REAL := 300.0; // Nominal speed [rpm]
    rSpeedTolerance : REAL := 2.0; // Speed tolerance for sync [rpm]
    bSequenceAborted : BOOL; // Internal flag for aborted sequence
END_VAR

// Mode constants
VAR CONSTANT
    MODE_STANDSTILL : INT := 0;
    MODE_TURBINE : INT := 1;
    MODE_PUMP : INT := 2;
    MODE_SYNC_COND : INT := 3;
END_VAR

// State Machine for Mode Transition
IF bStartSequence AND iStep = 0 AND NOT bError THEN
    iStep := 10;
    bTransitionActive := TRUE;
    bTransitionComplete := FALSE;
    bSequenceAborted := FALSE;
    bError := FALSE;
    iErrorCode := 0;
END_IF;

IF bTransitionActive THEN
    CASE iStep OF
        10: // Pre-checks
            IF bBearingLubeOK AND bCoolingWaterOK THEN
                iStep := 20;
            ELSE
                bError := TRUE;
                iErrorCode := 101; // Auxiliaries not ready
                iStep := 999;
            END_IF;

        20: // Determine path based on target mode
            IF eTargetMode = MODE_TURBINE THEN
                iStep := 100; // Turbine start sequence
            ELSIF eTargetMode = MODE_PUMP THEN
                iStep := 200; // Pump start sequence (SFC required)
            ELSE
                iStep := 999; // Unsupported for this example
            END_IF;

        // --- TURBINE START SEQUENCE ---
        100: // Open Main Inlet Valve (MIV) carefully to prevent water hammer
            bMainInletValveCmd_Open := TRUE;
            tStepTimer(IN := TRUE, PT := T#30s);
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iStep := 110;
            END_IF;

        110: // Open guide vanes to breakaway position
            rGuideVaneCmd_TargetPos := 15.0; // 15% breakaway
            bGuideVaneCmd_Open := TRUE;
            IF rGuideVanePos >= 14.5 THEN
                iStep := 120;
            END_IF;

        120: // Wait for nominal speed and grid sync
            IF ABS(rSFC_Speed - rNominalSpeed) <= rSpeedTolerance AND bGridSyncOK THEN
                bBreakerCmd_Close := TRUE;
                tStepTimer(IN := TRUE, PT := T#2s);
                IF tStepTimer.Q THEN
                    tStepTimer(IN:=FALSE);
                    iStep := 130;
                END_IF;
            END_IF;

        130: // Turbine mode achieved
            eCurrentMode := MODE_TURBINE;
            bTransitionActive := FALSE;
            bTransitionComplete := TRUE;
            iStep := 0;

        // --- PUMP START SEQUENCE (SFC SOFT START) ---
        200: // Blow down runner with compressed air to reduce starting torque
            bBlowdownAirCmd := TRUE;
            tStepTimer(IN := TRUE, PT := T#15s);
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iStep := 210;
            END_IF;

        210: // Start SFC
            bSFCCmd_Start := TRUE;
            rSFCCmd_SpeedRef := rNominalSpeed;
            IF rSFC_Speed >= (rNominalSpeed - rSpeedTolerance) AND bGridSyncOK THEN
                bBreakerCmd_Close := TRUE;
                iStep := 220;
            END_IF;

        220: // Evacuate air, prime pump, open MIV
            bBlowdownAirCmd := FALSE;
            bMainInletValveCmd_Open := TRUE;
            tStepTimer(IN := TRUE, PT := T#20s);
            IF tStepTimer.Q THEN
                tStepTimer(IN := FALSE);
                iStep := 230;
            END_IF;

        230: // Open guide vanes slowly to pumping load
            rGuideVaneCmd_TargetPos := 60.0; // 60% optimal pumping
            bGuideVaneCmd_Open := TRUE;
            IF rGuideVanePos >= 59.0 THEN
                iStep := 240;
            END_IF;

        240: // Pump mode achieved
            eCurrentMode := MODE_PUMP;
            bTransitionActive := FALSE;
            bTransitionComplete := TRUE;
            bSFCCmd_Start := FALSE; // SFC shuts down once synced and breaker closed
            iStep := 0;

        999: // Error state
            bTransitionActive := FALSE;
            bTransitionComplete := FALSE;
            // Retain iErrorCode
    END_CASE;

    // Update timer if not explicitly handled
    IF iStep <> 100 AND iStep <> 120 AND iStep <> 200 AND iStep <> 220 THEN
        tStepTimer(IN := FALSE);
    END_IF;
END_IF;
END_FUNCTION_BLOCK\n```
