FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; (* Enable system *)
    rChilledWaterSupplyTempSetpoint : REAL := 4.5; (* Deg C *)
    rChilledWaterReturnTemp : REAL; (* Deg C *)
    rChilledWaterSupplyTemp : REAL; (* Deg C *)
    rDifferentialPressure : REAL; (* kPa *)
    rDifferentialPressureSetpoint : REAL := 150.0; (* kPa *)
    rCoolingLoadTarget : REAL; (* kW *)
    rIceStorageInventory : REAL; (* % *)
    bTimeOfUsePeak : BOOL; (* True if during peak electrical pricing *)
    bTimeOfUseOffPeak : BOOL; (* True if during off-peak electrical pricing *)
END_VAR

VAR_OUTPUT
    bChiller1Enable : BOOL;
    bChiller2Enable : BOOL;
    bChiller3Enable : BOOL;
    rChiller1Capacity : REAL; (* 0-100% *)
    rChiller2Capacity : REAL; (* 0-100% *)
    rChiller3Capacity : REAL; (* 0-100% *)
    bIceMeltValveOpen : BOOL;
    rIceMeltValvePos : REAL; (* 0-100% *)
    rPrimaryPumpSpeed : REAL; (* 0-100% *)
    rSecondaryPumpSpeed : REAL; (* 0-100% *)
    bSystemAlarm : BOOL;
END_VAR

VAR
    rCurrentLoad : REAL;
    rErrorDP : REAL;
    rIntegralDP : REAL := 0.0;
    rKpDP : REAL := 0.5;
    rKiDP : REAL := 0.01;

    rErrorTemp : REAL;
    rIntegralTemp : REAL := 0.0;
    rKpTemp : REAL := 2.0;
    rKiTemp : REAL := 0.05;

    tDelayTimer : TON;
    nActiveChillers : INT := 0;
END_VAR

(* Calculate Current Load based on Delta T (simplified) *)
rCurrentLoad := (rChilledWaterReturnTemp - rChilledWaterSupplyTemp) * 4.184 * rSecondaryPumpSpeed * 0.1;

IF NOT bEnable THEN
    bChiller1Enable := FALSE;
    bChiller2Enable := FALSE;
    bChiller3Enable := FALSE;
    rChiller1Capacity := 0.0;
    rChiller2Capacity := 0.0;
    rChiller3Capacity := 0.0;
    bIceMeltValveOpen := FALSE;
    rIceMeltValvePos := 0.0;
    rPrimaryPumpSpeed := 0.0;
    rSecondaryPumpSpeed := 0.0;
    bSystemAlarm := FALSE;
    RETURN;
END_IF;

(* Secondary Pumping Differential Pressure Control (PI Loop) *)
rErrorDP := rDifferentialPressureSetpoint - rDifferentialPressure;
rIntegralDP := rIntegralDP + rErrorDP;
rSecondaryPumpSpeed := (rKpDP * rErrorDP) + (rKiDP * rIntegralDP);

IF rSecondaryPumpSpeed > 100.0 THEN
    rSecondaryPumpSpeed := 100.0;
    rIntegralDP := (100.0 - (rKpDP * rErrorDP)) / rKiDP;
ELSIF rSecondaryPumpSpeed < 20.0 THEN
    rSecondaryPumpSpeed := 20.0;
    rIntegralDP := (20.0 - (rKpDP * rErrorDP)) / rKiDP;
END_IF;

(* Ice Thermal Storage Strategy *)
IF bTimeOfUsePeak AND (rIceStorageInventory > 10.0) THEN
    (* Peak time: Maximize ice melting to offset chiller usage *)
    bIceMeltValveOpen := TRUE;
    rErrorTemp := rChilledWaterSupplyTemp - rChilledWaterSupplyTempSetpoint;
    rIntegralTemp := rIntegralTemp + rErrorTemp;
    rIceMeltValvePos := (rKpTemp * rErrorTemp) + (rKiTemp * rIntegralTemp);

    IF rIceMeltValvePos > 100.0 THEN
        rIceMeltValvePos := 100.0;
    ELSIF rIceMeltValvePos < 0.0 THEN
        rIceMeltValvePos := 0.0;
    END_IF;

    (* Reduce Chiller load since ice is taking it *)
    nActiveChillers := 1;
    rChiller1Capacity := 50.0;
    bChiller1Enable := TRUE;
    bChiller2Enable := FALSE;
    bChiller3Enable := FALSE;

ELSE
    (* Off-Peak or no ice: Normal Chiller Cascade Staging *)
    bIceMeltValveOpen := FALSE;
    rIceMeltValvePos := 0.0;

    (* Chiller Staging based on Cooling Load Target *)
    IF rCoolingLoadTarget > 2000.0 THEN
        nActiveChillers := 3;
        bChiller1Enable := TRUE;
        bChiller2Enable := TRUE;
        bChiller3Enable := TRUE;
        rChiller1Capacity := 100.0;
        rChiller2Capacity := 100.0;
        rChiller3Capacity := (rCoolingLoadTarget - 2000.0) / 10.0; 
    ELSIF rCoolingLoadTarget > 1000.0 THEN
        nActiveChillers := 2;
        bChiller1Enable := TRUE;
        bChiller2Enable := TRUE;
        bChiller3Enable := FALSE;
        rChiller1Capacity := 100.0;
        rChiller2Capacity := (rCoolingLoadTarget - 1000.0) / 10.0;
        rChiller3Capacity := 0.0;
    ELSE
        nActiveChillers := 1;
        bChiller1Enable := TRUE;
        bChiller2Enable := FALSE;
        bChiller3Enable := FALSE;
        rChiller1Capacity := rCoolingLoadTarget / 10.0;
        rChiller2Capacity := 0.0;
        rChiller3Capacity := 0.0;
    END_IF;

    (* Cap capacities *)
    IF rChiller1Capacity > 100.0 THEN rChiller1Capacity := 100.0; END_IF;
    IF rChiller2Capacity > 100.0 THEN rChiller2Capacity := 100.0; END_IF;
    IF rChiller3Capacity > 100.0 THEN rChiller3Capacity := 100.0; END_IF;
END_IF;

(* Primary Pump Speed (matches active chillers) *)
IF nActiveChillers = 3 THEN
    rPrimaryPumpSpeed := 100.0;
ELSIF nActiveChillers = 2 THEN
    rPrimaryPumpSpeed := 66.0;
ELSIF nActiveChillers = 1 THEN
    rPrimaryPumpSpeed := 33.0;
ELSE
    rPrimaryPumpSpeed := 0.0;
END_IF;

END_FUNCTION_BLOCK\n```
