FUNCTION_BLOCK FB_ChocolateConcheControl
VAR_INPUT
    bEnable : BOOL; (* Start the conching sequence *)
    bEStop : BOOL; (* Emergency Stop *)
    rActualVatTemp : REAL; (* Current temperature of the conching vat in Celsius *)
    rActualMotorTorque : REAL; (* Current torque of the main shear motor in Nm *)
    rActualMotorSpeed : REAL; (* Current speed of the shear motor in RPM *)
    rFatTankLevel : REAL; (* Level of cocoa butter/fat tank in % *)
    rLecithinLevel : REAL; (* Level of lecithin tank in % *)
END_VAR
VAR_OUTPUT
    bMotorEnable : BOOL; (* Enable main shear motor *)
    rMotorSpeedRef : REAL; (* Speed reference for main motor RPM *)
    bHeaterEnable : BOOL; (* Enable vat heating jacket *)
    bCoolerEnable : BOOL; (* Enable vat cooling jacket *)
    bFatPumpEnable : BOOL; (* Enable fat dosing pump *)
    bLecithinPumpEnable : BOOL; (* Enable lecithin dosing pump *)
    iCurrentPhase : INT; (* 0:Off, 1:Dry, 2:Pasty, 3:Liquid, 4:Complete, 99:Error *)
    bAlarm : BOOL; (* Alarm active *)
    sStatusMessage : STRING[50]; (* Human readable status *)
END_VAR
VAR
    TimerPhaseDuration : TON;
    rPhaseTimerElapsed : REAL;
    bTransitionToPasty : BOOL;
    bTransitionToLiquid : BOOL;
    bTransitionToComplete : BOOL;

    (* PID and Profiling Constants *)
    rMaxDryTorque : REAL := 850.0;
    rMaxPastyTorque : REAL := 1200.0;
    rMaxLiquidTorque : REAL := 400.0;

    rTargetTempDry : REAL := 60.0;
    rTargetTempPasty : REAL := 75.0;
    rTargetTempLiquid : REAL := 55.0;

    tDryDuration : TIME := T#4H;
    tPastyDuration : TIME := T#2H;
    tLiquidDuration : TIME := T#1H;

    bFatDosingDone : BOOL;
    bLecithinDosingDone : BOOL;

    State : INT := 0; 
END_VAR

(* Main State Machine for Conching Phases *)
IF bEStop THEN
    State := 99;
ELSIF NOT bEnable AND State <> 99 THEN
    State := 0;
END_IF;

CASE State OF
    0: (* OFF STATE *)
        bMotorEnable := FALSE;
        rMotorSpeedRef := 0.0;
        bHeaterEnable := FALSE;
        bCoolerEnable := FALSE;
        bFatPumpEnable := FALSE;
        bLecithinPumpEnable := FALSE;
        TimerPhaseDuration(IN:=FALSE);
        bFatDosingDone := FALSE;
        bLecithinDosingDone := FALSE;
        sStatusMessage := 'Idle';
        iCurrentPhase := 0;

        IF bEnable AND NOT bEStop THEN
            State := 1; (* Start Dry Phase *)
        END_IF;

    1: (* DRY PHASE: High friction, moisture and acid removal *)
        iCurrentPhase := 1;
        sStatusMessage := 'Dry Phase Active';
        bMotorEnable := TRUE;
        rMotorSpeedRef := 30.0; (* Slow speed for dry friction *)

        (* Temperature Control for Dry Phase *)
        IF rActualVatTemp < rTargetTempDry - 2.0 THEN
            bHeaterEnable := TRUE;
            bCoolerEnable := FALSE;
        ELSIF rActualVatTemp > rTargetTempDry + 2.0 THEN
            bHeaterEnable := FALSE;
            bCoolerEnable := TRUE;
        ELSE
            bHeaterEnable := FALSE;
            bCoolerEnable := FALSE;
        END_IF;

        (* Torque Monitoring - Reduce speed if too thick *)
        IF rActualMotorTorque > rMaxDryTorque THEN
            rMotorSpeedRef := 15.0;
        END_IF;

        TimerPhaseDuration(IN:=TRUE, PT:=tDryDuration);
        IF TimerPhaseDuration.Q THEN
            State := 2;
            TimerPhaseDuration(IN:=FALSE);
        END_IF;

    2: (* PASTY PHASE: Addition of some fat, high shearing forces *)
        iCurrentPhase := 2;
        sStatusMessage := 'Pasty Phase Active';
        rMotorSpeedRef := 45.0; 

        (* Temp Control *)
        IF rActualVatTemp < rTargetTempPasty - 1.5 THEN
            bHeaterEnable := TRUE;
            bCoolerEnable := FALSE;
        ELSIF rActualVatTemp > rTargetTempPasty + 1.5 THEN
            bHeaterEnable := FALSE;
            bCoolerEnable := TRUE;
        ELSE
            bHeaterEnable := FALSE;
            bCoolerEnable := FALSE;
        END_IF;

        (* Fat Dosing Sequence *)
        IF NOT bFatDosingDone THEN
            bFatPumpEnable := TRUE;
            (* Simulated volume check: Assuming flow rate completes in 10 mins *)
            IF TimerPhaseDuration.ET > T#10M THEN
                bFatPumpEnable := FALSE;
                bFatDosingDone := TRUE;
            END_IF;
        END_IF;

        (* Overload Protection *)
        IF rActualMotorTorque > rMaxPastyTorque THEN
            State := 99; (* Hard torque fault during pasty phase *)
        END_IF;

        TimerPhaseDuration(IN:=TRUE, PT:=tPastyDuration);
        IF TimerPhaseDuration.Q THEN
            State := 3;
            TimerPhaseDuration(IN:=FALSE);
        END_IF;

    3: (* LIQUID PHASE: Final liquefaction, addition of lecithin and remaining fat *)
        iCurrentPhase := 3;
        sStatusMessage := 'Liquid Phase Active';
        rMotorSpeedRef := 70.0; (* High speed for final homogenization *)

        (* Temp Control - Cool down for liquid phase *)
        IF rActualVatTemp < rTargetTempLiquid - 1.0 THEN
            bHeaterEnable := TRUE;
            bCoolerEnable := FALSE;
        ELSIF rActualVatTemp > rTargetTempLiquid + 1.0 THEN
            bHeaterEnable := FALSE;
            bCoolerEnable := TRUE;
        ELSE
            bHeaterEnable := FALSE;
            bCoolerEnable := FALSE;
        END_IF;

        (* Lecithin Dosing Sequence *)
        IF NOT bLecithinDosingDone AND TimerPhaseDuration.ET > T#5M THEN
            bLecithinPumpEnable := TRUE;
            IF TimerPhaseDuration.ET > T#8M THEN
                bLecithinPumpEnable := FALSE;
                bLecithinDosingDone := TRUE;
            END_IF;
        END_IF;

        TimerPhaseDuration(IN:=TRUE, PT:=tLiquidDuration);
        IF TimerPhaseDuration.Q THEN
            State := 4;
            TimerPhaseDuration(IN:=FALSE);
        END_IF;

    4: (* COMPLETE *)
        iCurrentPhase := 4;
        sStatusMessage := 'Conching Complete';
        bMotorEnable := FALSE;
        rMotorSpeedRef := 0.0;
        bHeaterEnable := FALSE;
        bCoolerEnable := FALSE;
        bFatPumpEnable := FALSE;
        bLecithinPumpEnable := FALSE;

    99: (* ERROR / ESTOP *)
        iCurrentPhase := 99;
        sStatusMessage := 'FAULT: E-Stop or Torque Overload';
        bMotorEnable := FALSE;
        rMotorSpeedRef := 0.0;
        bHeaterEnable := FALSE;
        bCoolerEnable := FALSE;
        bFatPumpEnable := FALSE;
        bLecithinPumpEnable := FALSE;
        bAlarm := TRUE;

END_CASE;
END_FUNCTION_BLOCK
