FUNCTION_BLOCK FB_FlexoPressControl
VAR_INPUT
    bEnable : BOOL; // Master enable
    rLineSpeed_mmin : REAL; // Current web line speed in m/min
    rTargetSpeed_mmin : REAL; // Target web line speed in m/min
    rTensionActual_N : REAL; // Actual web tension in Newtons

    // Thermal Control Inputs
    rCICylinderTemp_C : REAL; // Central Impression cylinder surface temp
    rCoolantInletTemp_C : REAL;

    // Registration Inputs (4 colors)
    arColorMarkPhaseErr_mm : ARRAY[1..4] OF REAL; // Phase error for Cyan, Magenta, Yellow, Black

    // Curing Inputs
    rUVIntensityFeedback_mWcm2 : REAL; // UV LED curing intensity feedback
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;

    // Thermal Control Outputs
    rChillerValvePosition_Pct : REAL; // 0-100%
    bHeaterEnable : BOOL;
    rHeaterPower_Pct : REAL;

    // Registration Outputs
    arServoCorrection_mm : ARRAY[1..4] OF REAL; // Correction offsets for servos

    // Curing Outputs
    rUVLEDSetPoint_Pct : REAL; // 0-100% PWM
    bCuringFault : BOOL;
END_VAR

VAR
    // Internal States
    nState : INT := 0;

    // Thermal PID
    rTempSetPoint_C : REAL := 32.5; // Optimal CI cylinder temp
    rTempError : REAL;
    rTempKp : REAL := 2.5;
    rTempKi : REAL := 0.15;
    rTempIntegral : REAL;
    rCoolingDemand : REAL;

    // Registration Control
    i : INT;
    arRegKp : ARRAY[1..4] OF REAL := [0.8, 0.8, 0.85, 0.9];
    rMaxCorrectionStep : REAL := 0.05; // Max mm per cycle

    // UV Curing Profile
    rBaseUVPower_Pct : REAL := 20.0;
    rSpeedFactor : REAL := 0.25; // % per m/min
    rMaxUVPower_Pct : REAL := 95.0;

    // Timers
    tCuringDelay : TON;
END_VAR

// ==============================================================================
// High-Speed Web Flexographic Printing Press - Core Control Logic
// ==============================================================================

IF NOT bEnable THEN
    bSystemReady := FALSE;
    rChillerValvePosition_Pct := 0.0;
    bHeaterEnable := FALSE;
    rHeaterPower_Pct := 0.0;
    rUVLEDSetPoint_Pct := 0.0;
    FOR i := 1 TO 4 DO
        arServoCorrection_mm[i] := 0.0;
    END_FOR;
    rTempIntegral := 0.0;
    RETURN;
END_IF;

bSystemReady := TRUE;

// ------------------------------------------------------------------------------
// 1. Central Impression (CI) Cylinder Thermal Stability
// Maintains strict drum temperature to prevent web distortion
// ------------------------------------------------------------------------------
rTempError := rCICylinderTemp_C - rTempSetPoint_C;
rTempIntegral := rTempIntegral + (rTempError * 0.01); // Assuming 10ms task time

// Anti-windup
IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
IF rTempIntegral < -100.0 THEN rTempIntegral := -100.0; END_IF;

rCoolingDemand := (rTempKp * rTempError) + (rTempKi * rTempIntegral);

IF rCoolingDemand > 0.0 THEN
    // Requires cooling
    rChillerValvePosition_Pct := LIMIT(0.0, rCoolingDemand, 100.0);
    bHeaterEnable := FALSE;
    rHeaterPower_Pct := 0.0;
ELSE
    // Requires heating
    rChillerValvePosition_Pct := 0.0;
    bHeaterEnable := TRUE;
    rHeaterPower_Pct := LIMIT(0.0, ABS(rCoolingDemand), 100.0);
END_IF;

// ------------------------------------------------------------------------------
// 2. Multi-Color Servo Registration (Longitudinal Phase Correction)
// Applies dynamic offsets based on mark sensor readings
// ------------------------------------------------------------------------------
FOR i := 1 TO 4 DO
    // Calculate proportional correction based on mark phase error
    arServoCorrection_mm[i] := arColorMarkPhaseErr_mm[i] * arRegKp[i];

    // Slew rate limiting to prevent web snap or tension spikes
    IF arServoCorrection_mm[i] > rMaxCorrectionStep THEN
        arServoCorrection_mm[i] := rMaxCorrectionStep;
    ELSIF arServoCorrection_mm[i] < -rMaxCorrectionStep THEN
        arServoCorrection_mm[i] := -rMaxCorrectionStep;
    END_IF;
END_FOR;

// ------------------------------------------------------------------------------
// 3. UV LED Ink Curing Intensity Profiling
// Dynamically scales UV power with line speed to ensure consistent dose
// ------------------------------------------------------------------------------
IF rLineSpeed_mmin > 10.0 THEN
    // Scale UV output linearly with speed above a minimum threshold
    rUVLEDSetPoint_Pct := rBaseUVPower_Pct + (rLineSpeed_mmin * rSpeedFactor);
    rUVLEDSetPoint_Pct := LIMIT(0.0, rUVLEDSetPoint_Pct, rMaxUVPower_Pct);
ELSE
    // Standby curing mode when slow or stopped
    rUVLEDSetPoint_Pct := 0.0;
END_IF;

// Fault monitoring: Check if actual UV intensity deviates too far from expected
IF rLineSpeed_mmin > 50.0 AND rUVIntensityFeedback_mWcm2 < (rUVLEDSetPoint_Pct * 0.5) THEN
    tCuringDelay(IN:= TRUE, PT:= T#2S);
    IF tCuringDelay.Q THEN
        bCuringFault := TRUE;
    END_IF;
ELSE
    tCuringDelay(IN:= FALSE);
    bCuringFault := FALSE;
END_IF;

END_FUNCTION_BLOCK
```

