FUNCTION_BLOCK FB_IntaglioPress_MasterControl
TITLE = 'High-Speed Banknote Intaglio Printing Press Master Controller'
VERSION : '2.4'

VAR_INPUT
    bEnablePress            : BOOL; // Master enable signal
    rPressSpeedSetpoint_m_s : REAL; // Target press speed (m/s)
    rActualPressSpeed_m_s   : REAL; // Actual press speed from encoder
    rSubstrateThickness_um  : REAL; // Measured substrate thickness in microns
    rInkViscosity_mPa_s     : REAL; // Real-time ink viscosity measurement
    rWipingRollerTemp_C     : REAL; // Wiping roller temperature feedback
    bOpticalDefectDetected  : BOOL; // Trigger from optical inspection system
    nDefectErrorCode        : INT;  // Vision system error code
    nSheetID                : DINT; // Current banknote sheet serial/ID
END_VAR

VAR_OUTPUT
    rWipingRollerPressure_bar : REAL; // Commanded wiping pressure
    rUVCuringIntensity_pct    : REAL; // Commanded UV lamp intensity (0-100%)
    bPressEmergencyStop       : BOOL; // E-stop trigger
    bWipingPressureAlarm      : BOOL; // Pressure tolerance out of bounds
    nTotalSheetsPrinted       : DINT; // Total sheets counter
    nTotalDefectiveSheets     : DINT; // Defect counter
END_VAR

VAR
    // Internal state variables
    rSpeedError               : REAL;
    rBaseWipingPressure       : REAL;
    rTempCompensation         : REAL;
    rViscosityCompensation    : REAL;

    // Defect Tracking FIFO
    aDefectSheetIDs           : ARRAY[0..99] OF DINT;
    aDefectCodes              : ARRAY[0..99] OF INT;
    nFifoHead                 : INT := 0;
    nFifoTail                 : INT := 0;

    // PID variables for wiping pressure
    rKp_Wipe                  : REAL := 1.25;
    rKi_Wipe                  : REAL := 0.45;
    rIntegralAccumulator      : REAL := 0.0;

    // Constants
    MAX_UV_INTENSITY          : REAL := 100.0;
    MIN_UV_INTENSITY          : REAL := 15.0;
    NOMINAL_WIPE_TEMP         : REAL := 42.0; // Celsius
    NOMINAL_INK_VISC          : REAL := 850.0; // mPa.s
END_VAR

// ==============================================================================
// MAIN CONTROL LOGIC
// ==============================================================================

// 1. Safety and Enable Interlocks
IF NOT bEnablePress THEN
    rWipingRollerPressure_bar := 0.0;
    rUVCuringIntensity_pct := 0.0;
    rIntegralAccumulator := 0.0;
    RETURN;
END_IF;

// 2. Wiping Roller Pressure Control Algorithm
// The base pressure is proportional to the press speed and substrate thickness.
rBaseWipingPressure := (rActualPressSpeed_m_s * 1.5) + (rSubstrateThickness_um * 0.02);

// Temperature compensation: Hotter rollers require slightly less pressure to maintain ink film
rTempCompensation := (NOMINAL_WIPE_TEMP - rWipingRollerTemp_C) * 0.05;

// Viscosity compensation: Higher viscosity requires more wiping pressure
rViscosityCompensation := (rInkViscosity_mPa_s - NOMINAL_INK_VISC) * 0.001;

// PI Control for Wiping Pressure
rSpeedError := rPressSpeedSetpoint_m_s - rActualPressSpeed_m_s;
rIntegralAccumulator := rIntegralAccumulator + (rSpeedError * rKi_Wipe);

// Anti-windup
IF rIntegralAccumulator > 5.0 THEN
    rIntegralAccumulator := 5.0;
ELSIF rIntegralAccumulator < -5.0 THEN
    rIntegralAccumulator := -5.0;
END_IF;

rWipingRollerPressure_bar := rBaseWipingPressure + rTempCompensation + rViscosityCompensation + (rSpeedError * rKp_Wipe) + rIntegralAccumulator;

// Pressure limits and alarms
IF rWipingRollerPressure_bar > 12.0 THEN
    rWipingRollerPressure_bar := 12.0;
    bWipingPressureAlarm := TRUE;
ELSIF rWipingRollerPressure_bar < 2.0 THEN
    rWipingRollerPressure_bar := 2.0;
    bWipingPressureAlarm := TRUE;
ELSE
    bWipingPressureAlarm := FALSE;
END_IF;

// 3. UV Curing Intensity Profiling
// UV intensity scales quadratically with speed to ensure complete curing of thick intaglio ink
rUVCuringIntensity_pct := MIN_UV_INTENSITY + (rActualPressSpeed_m_s * rActualPressSpeed_m_s * 2.5);

// Add additional intensity for thicker substrates
IF rSubstrateThickness_um > 110.0 THEN
    rUVCuringIntensity_pct := rUVCuringIntensity_pct + 15.0;
END_IF;

IF rUVCuringIntensity_pct > MAX_UV_INTENSITY THEN
    rUVCuringIntensity_pct := MAX_UV_INTENSITY;
END_IF;

// 4. Optical Defect Registration (FIFO Queue)
IF bOpticalDefectDetected THEN
    // Push defect to FIFO
    aDefectSheetIDs[nFifoHead] := nSheetID;
    aDefectCodes[nFifoHead]    := nDefectErrorCode;

    nFifoHead := (nFifoHead + 1) MOD 100;
    nTotalDefectiveSheets := nTotalDefectiveSheets + 1;

    // Overwrite protection
    IF nFifoHead = nFifoTail THEN
        nFifoTail := (nFifoTail + 1) MOD 100;
    END_IF;

    // Critical Defect E-Stop Interlock (e.g., massive ink smudge or paper tear)
    IF nDefectErrorCode >= 9000 THEN
        bPressEmergencyStop := TRUE;
        bEnablePress := FALSE;
    END_IF;
END_IF;

// Update production counter (assuming triggered once per cycle externally)
nTotalSheetsPrinted := nTotalSheetsPrinted + 1;

END_FUNCTION_BLOCK
