FUNCTION_BLOCK FB_TissuePaperMachineControl
VAR_INPUT
    bEnable : BOOL; // System enable
    rWebSpeedRef : REAL; // Reference web speed [m/min]
    rActualWebSpeed : REAL; // Actual web speed [m/min]

    // Yankee Cylinder Inputs
    rYankeeSteamPress : REAL; // Current steam pressure [bar]
    rYankeeSurfaceTemp : ARRAY[1..10] OF REAL; // Zone temperature sensors [C]
    rYankeeTempRef : REAL; // Reference temperature [C]

    // Doctor Blade Inputs
    rBladeVibFreqFeedback : REAL; // Actual vibration frequency [Hz]
    rBladeVibAmpFeedback : REAL; // Actual vibration amplitude [mm]
    rBladeWearSensor : REAL; // Blade wear measurement [mm]

    // Reeler Inputs
    rReelerTensionFbk : REAL; // Web tension feedback [N/m]
    rReelerDiameter : REAL; // Current parent roll diameter [m]
    rReelerTorqueRef : REAL; // Base torque reference [Nm]
END_VAR

VAR_OUTPUT
    // Yankee Cylinder Outputs
    rYankeeSteamValveCmd : REAL; // Steam valve command [%]
    rYankeeHoodExhaustCmd : ARRAY[1..10] OF REAL; // Zone hood exhaust damper commands [%]

    // Doctor Blade Outputs
    rBladeVibFreqCmd : REAL; // Command vibration frequency [Hz]
    rBladeVibAmpCmd : REAL; // Command vibration amplitude [mm]
    rBladePressureCmd : REAL; // Loading pressure command [bar]

    // Reeler Outputs
    rReelerDriveTorqueCmd : REAL; // Final drive torque command [Nm]
    bWebBreakDetected : BOOL; // Web break alarm

    // Status
    bSystemReady : BOOL;
    wErrorCode : WORD;
END_VAR

VAR
    // Yankee Thermal Profiling
    iZone : INT;
    rTempError : ARRAY[1..10] OF REAL;
    rTempIntegral : ARRAY[1..10] OF REAL;
    rZoneKp : REAL := 2.5;
    rZoneKi : REAL := 0.15;

    // Doctor Blade
    rBaseFreq : REAL := 15.0;
    rBaseAmp : REAL := 0.5;
    rWearCompensation : REAL;

    // Reeler Tension Control
    rTensionError : REAL;
    rTensionIntegral : REAL;
    rTensionKp : REAL := 12.0;
    rTensionKi : REAL := 1.2;
    rInertiaCompensation : REAL;
    rAccelTorque : REAL;
    rLastSpeed : REAL;

    // Timers
    tCycleTime : TIME := T#10MS;
END_VAR

// -----------------------------------------------------------------------------
// Initialization & Safety Check
// -----------------------------------------------------------------------------
IF NOT bEnable THEN
    rYankeeSteamValveCmd := 0.0;
    rBladeVibFreqCmd := 0.0;
    rBladeVibAmpCmd := 0.0;
    rBladePressureCmd := 0.0;
    rReelerDriveTorqueCmd := 0.0;
    bSystemReady := FALSE;
    RETURN;
END_IF;

bSystemReady := TRUE;
wErrorCode := 0;

// -----------------------------------------------------------------------------
// Yankee Cylinder Thermal Profiling
// -----------------------------------------------------------------------------
// Calculate overall steam valve command based on average temperature error
rYankeeSteamValveCmd := (rYankeeTempRef - rYankeeSurfaceTemp[5]) * 0.5;
IF rYankeeSteamValveCmd > 100.0 THEN rYankeeSteamValveCmd := 100.0; END_IF;
IF rYankeeSteamValveCmd < 0.0 THEN rYankeeSteamValveCmd := 0.0; END_IF;

// Calculate zone-specific exhaust commands to correct cross-directional moisture profile
FOR iZone := 1 TO 10 DO
    rTempError[iZone] := rYankeeTempRef - rYankeeSurfaceTemp[iZone];
    rTempIntegral[iZone] := rTempIntegral[iZone] + (rTempError[iZone] * 0.01); // 10ms cycle

    // Anti-windup
    IF rTempIntegral[iZone] > 50.0 THEN rTempIntegral[iZone] := 50.0; END_IF;
    IF rTempIntegral[iZone] < -50.0 THEN rTempIntegral[iZone] := -50.0; END_IF;

    rYankeeHoodExhaustCmd[iZone] := (rTempError[iZone] * rZoneKp) + (rTempIntegral[iZone] * rZoneKi);

    // Clamp output
    IF rYankeeHoodExhaustCmd[iZone] > 100.0 THEN rYankeeHoodExhaustCmd[iZone] := 100.0; END_IF;
    IF rYankeeHoodExhaustCmd[iZone] < 0.0 THEN rYankeeHoodExhaustCmd[iZone] := 0.0; END_IF;
END_FOR;

// -----------------------------------------------------------------------------
// Creping Doctor Blade Active Vibration Control
// -----------------------------------------------------------------------------
// Adjust blade pressure and vibration based on web speed and blade wear
rWearCompensation := rBladeWearSensor * 1.5; // Increase pressure as blade wears
rBladePressureCmd := 5.0 + rWearCompensation + (rActualWebSpeed * 0.002);

// Active vibration to improve crepe structure and blade life
IF rActualWebSpeed > 500.0 THEN
    rBladeVibFreqCmd := rBaseFreq + ((rActualWebSpeed - 500.0) * 0.01);
    rBladeVibAmpCmd := rBaseAmp - (rBladeWearSensor * 0.1);
ELSE
    rBladeVibFreqCmd := 0.0;
    rBladeVibAmpCmd := 0.0;
END_IF;

// -----------------------------------------------------------------------------
// Parent Roll Reeler Tension Control
// -----------------------------------------------------------------------------
// Web break detection
IF (rActualWebSpeed > 100.0) AND (rReelerTensionFbk < 10.0) THEN
    bWebBreakDetected := TRUE;
    wErrorCode := 16#0001;
ELSE
    bWebBreakDetected := FALSE;
END_IF;

IF NOT bWebBreakDetected THEN
    // Tension PI Control
    rTensionError := 150.0 - rReelerTensionFbk; // Assuming setpoint 150 N/m
    rTensionIntegral := rTensionIntegral + (rTensionError * 0.01);

    // Anti-windup
    IF rTensionIntegral > 1000.0 THEN rTensionIntegral := 1000.0; END_IF;
    IF rTensionIntegral < -1000.0 THEN rTensionIntegral := -1000.0; END_IF;

    // Inertia compensation based on changing roll diameter
    rInertiaCompensation := (rReelerDiameter * rReelerDiameter) * 0.5;

    // Acceleration torque feedforward
    rAccelTorque := (rActualWebSpeed - rLastSpeed) * rInertiaCompensation * 10.0;
    rLastSpeed := rActualWebSpeed;

    // Final torque command combining base torque, PI trim, and inertia compensation
    rReelerDriveTorqueCmd := rReelerTorqueRef + 
                             (rTensionError * rTensionKp) + 
                             (rTensionIntegral * rTensionKi) + 
                             rAccelTorque;

    // Taper tension adjustment (decrease tension as roll diameter increases to prevent telescoping)
    rReelerDriveTorqueCmd := rReelerDriveTorqueCmd * (1.0 - (rReelerDiameter * 0.1));

    // Limits
    IF rReelerDriveTorqueCmd > 5000.0 THEN rReelerDriveTorqueCmd := 5000.0; END_IF;
    IF rReelerDriveTorqueCmd < 0.0 THEN rReelerDriveTorqueCmd := 0.0; END_IF;
ELSE
    rReelerDriveTorqueCmd := 0.0;
END_IF;

END_FUNCTION_BLOCK
