FUNCTION_BLOCK FB_AUV_BuoyancyEngine
VAR_INPUT
    bEnableSys              : BOOL;     (* Main system enable command from vehicle management *)
    bEmergencyAscent        : BOOL;     (* Dead-man switch / fail-safe drop weights command *)
    rDepthTargetMeters      : REAL;     (* Desired operation depth in meters *)
    rCurrentDepthMeters     : REAL;     (* Feedback from precision pressure sensor (m) *)
    rExternalPressureBar    : REAL;     (* Absolute external pressure sensing (Bar) *)
    rInternalHullStrain     : REAL;     (* Pressure hull strain micro-strain feedback *)
    rHydraulicSupplyPress   : REAL;     (* HP hydraulic supply rail pressure (Bar) *)
    rSyntacticFoamComp      : REAL;     (* Syntactic foam compression differential volume (L) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System fully initialized and ready for commands *)
    rOilTransferCmd_Lpm     : REAL;     (* Commanded hydraulic fluid flow rate to external bladder (L/min) *)
    bPumpEnable             : BOOL;     (* Enable signal for high-pressure hydraulic pump *)
    bSolenoidValveA         : BOOL;     (* Valve for fluid flow to expansion bladder *)
    bSolenoidValveB         : BOOL;     (* Valve for fluid return to internal hard tank *)
    bCriticalAlarm          : BOOL;     (* Hull strain or pressure integrity failure alarm *)
    iCurrentStateCode       : INT;      (* Diagnostics: Current active state machine code *)
END_VAR

VAR
    (* Internal State Variables *)
    iState                  : INT := 0; 
    tCycleTimer             : TON;
    tSolenoidDebounce       : TON;

    (* Filtered values *)
    rDepthFiltered          : REAL := 0.0;
    rDepthError             : REAL := 0.0;

    (* Control Parameters *)
    rKp                     : REAL := 2.5; 
    rKi                     : REAL := 0.15;
    rKd                     : REAL := 1.2;
    rIntegral               : REAL := 0.0;
    rPrevError              : REAL := 0.0;
    rDerivative             : REAL := 0.0;

    (* Safety limits *)
    rMaxDepth               : REAL := 6000.0;   (* 6000m abyssal rating *)
    rMaxHullStrain          : REAL := 1500.0;   (* Maximum allowed microstrain *)
    rMaxFlowCmd             : REAL := 50.0;     (* Max flow 50 L/min *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF bEmergencyAscent THEN
    bSystemReady := FALSE;
    bPumpEnable := FALSE;
    bSolenoidValveA := FALSE;
    bSolenoidValveB := TRUE; (* Dump all fluid back to hard tank or drop weights *)
    rOilTransferCmd_Lpm := 0.0;
    bCriticalAlarm := TRUE;
    iCurrentStateCode := 999;
    RETURN;
END_IF;

IF rInternalHullStrain > rMaxHullStrain OR rCurrentDepthMeters > rMaxDepth THEN
    bCriticalAlarm := TRUE;
    bSystemReady := FALSE;
    bPumpEnable := FALSE;
    bSolenoidValveA := FALSE;
    bSolenoidValveB := TRUE;
    rOilTransferCmd_Lpm := 0.0;
    iCurrentStateCode := 888;
    RETURN;
END_IF;

(* === SENSOR FILTERING === *)
(* Simple first-order low-pass filter for depth reading to mitigate sensor noise *)
rDepthFiltered := (rDepthFiltered * 0.9) + (rCurrentDepthMeters * 0.1);

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bPumpEnable := FALSE;
        bSolenoidValveA := FALSE;
        bSolenoidValveB := FALSE;
        rOilTransferCmd_Lpm := 0.0;
        bCriticalAlarm := FALSE;

        IF bEnableSys THEN
            tCycleTimer(IN := TRUE, PT := T#2S);
            IF tCycleTimer.Q THEN
                tCycleTimer(IN := FALSE);
                bSystemReady := TRUE;
                iState := 10;
            END_IF;
        ELSE
            tCycleTimer(IN := FALSE);
        END_IF;

    10: (* ACTIVE DEPTH REGULATION (PID LOOP) *)
        IF NOT bEnableSys THEN
            iState := 0;
        ELSE
            (* Calculate Error *)
            rDepthError := rDepthTargetMeters - rDepthFiltered;

            (* Anti-windup for integral term *)
            IF (rOilTransferCmd_Lpm < rMaxFlowCmd AND rOilTransferCmd_Lpm > -rMaxFlowCmd) THEN
                rIntegral := rIntegral + rDepthError;
            END_IF;

            rDerivative := rDepthError - rPrevError;

            (* PID Equation *)
            rOilTransferCmd_Lpm := (rKp * rDepthError) + (rKi * rIntegral) + (rKd * rDerivative);

            (* Syntactic foam compression compensation feed-forward term *)
            rOilTransferCmd_Lpm := rOilTransferCmd_Lpm + (rSyntacticFoamComp * 0.5);

            (* Output Saturation and valve logic *)
            IF rOilTransferCmd_Lpm > rMaxFlowCmd THEN
                rOilTransferCmd_Lpm := rMaxFlowCmd;
            ELSIF rOilTransferCmd_Lpm < -rMaxFlowCmd THEN
                rOilTransferCmd_Lpm := -rMaxFlowCmd;
            END_IF;

            (* Valve Actuation Logic based on commanded flow direction *)
            IF rOilTransferCmd_Lpm > 1.0 THEN
                (* Pumping fluid out to bladder to increase buoyancy / go up *)
                bPumpEnable := TRUE;
                bSolenoidValveA := TRUE;
                bSolenoidValveB := FALSE;
            ELSIF rOilTransferCmd_Lpm < -1.0 THEN
                (* Bringing fluid in to hard tank to decrease buoyancy / go down *)
                bPumpEnable := FALSE; (* Differential pressure drives fluid back *)
                bSolenoidValveA := FALSE;
                bSolenoidValveB := TRUE;
            ELSE
                (* Maintain neutral buoyancy *)
                bPumpEnable := FALSE;
                bSolenoidValveA := FALSE;
                bSolenoidValveB := FALSE;
                rOilTransferCmd_Lpm := 0.0;
            END_IF;

            rPrevError := rDepthError;
        END_IF;

    ELSE
        (* FAULT STATE CATCH-ALL *)
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
