```iec-st
FUNCTION_BLOCK FB_CAES_IsothermalExpansion
VAR_INPUT
    (* Required inputs for CAES isothermal expansion control *)
    bSystemEnable           : BOOL;     (* Main activation command from Grid Operator *)
    bEmergencyStop          : BOOL;     (* Hardware safety relay OK signal *)
    rCavernPressure         : REAL;     (* Air cavern pressure (bar) *)
    rCavernTemp             : REAL;     (* Air cavern temperature (deg C) *)
    rGridFreq               : REAL;     (* Current grid frequency (Hz) *)
    rPowerDemand_MW         : REAL;     (* Requested generation power (MW) *)
    rHeatXchangerLiqTemp    : REAL;     (* Liquid piston heat exchange medium temperature (deg C) *)
    bSyncGenReady           : BOOL;     (* Synchronous generator excitation and field ready *)
END_VAR
VAR_OUTPUT
    (* Required outputs for actuation and status *)
    bSystemReady            : BOOL;     (* Indicates system is primed and ready to produce power *)
    rThrottleValvePos       : REAL;     (* Main high-pressure withdrawal valve setpoint (0-100%) *)
    rLiqPumpSpeed           : REAL;     (* Liquid piston fluid circulation pump speed (RPM) *)
    bGeneratorBreakerClose  : BOOL;     (* Command to close main generator breaker to grid *)
    bCriticalAlarm          : BOOL;     (* System fault / emergency shutdown active *)
    rActivePower_MW         : REAL;     (* Estimated current active power production (MW) *)
END_VAR
VAR
    (* Internal State and Timers *)
    iExpansionState         : INT := 0; (* Internal state machine *)
    tStartupTimer           : TON;
    tSyncTimer              : TON;

    (* Internal process variables *)
    rMassFlowRate           : REAL;
    rTargetPressure         : REAL;
    rDeltaF                 : REAL;

    (* Constants *)
    NOMINAL_FREQ            : REAL := 50.0;
    DROOP_COEFF             : REAL := 0.04;
    MIN_CAVERN_PRESS        : REAL := 45.0;
    MAX_VALVE_RATE          : REAL := 5.0; 
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlock Evaluation *)
IF NOT bEmergencyStop OR rCavernPressure < MIN_CAVERN_PRESS THEN
    bSystemReady := FALSE;
    bGeneratorBreakerClose := FALSE;
    rThrottleValvePos := 0.0;
    rLiqPumpSpeed := 0.0;
    bCriticalAlarm := TRUE;
    iExpansionState := 999; (* Fault state *)
    RETURN;
ELSE
    bCriticalAlarm := FALSE;
END_IF;

(* Primary Isothermal Expansion State Machine *)
CASE iExpansionState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        rThrottleValvePos := 0.0;
        rLiqPumpSpeed := 0.0;
        bGeneratorBreakerClose := FALSE;

        IF bSystemEnable AND bSyncGenReady THEN
            iExpansionState := 10;
        END_IF;

    10: (* PRIMING_HEAT_EXCHANGER *)
        bSystemReady := FALSE;
        (* Start liquid pump to precondition the isothermal chamber *)
        rLiqPumpSpeed := 1500.0; 

        tStartupTimer(IN := TRUE, PT := T#15S);
        IF tStartupTimer.Q THEN
            tStartupTimer(IN := FALSE);
            iExpansionState := 20;
        END_IF;

    20: (* PRESSURE_RAMPUP *)
        (* Calculate target pressure based on power demand and frequency droop *)
        rDeltaF := NOMINAL_FREQ - rGridFreq;
        rTargetPressure := (rPowerDemand_MW * 0.8) + (rDeltaF * DROOP_COEFF * 100.0);

        (* Ramp throttle valve safely *)
        IF rThrottleValvePos < (rTargetPressure * 0.5) THEN
            rThrottleValvePos := rThrottleValvePos + MAX_VALVE_RATE;
        ELSE
            iExpansionState := 30;
