    bCyclone2ValveOpen : BOOL; (* Valve to second stage separator *)
    iProcessState : INT; (* 0: Idle, 1: Pressurizing, 2: Heating, 3: Extracting, 4: Depressurizing, 5: Fault *)
    sStatusMessage : STRING(50);
