(* Logic Implementation *)
rtStart(CLK := bStartProcess);

IF bEmergencyStop THEN
    iProcessState := 5;
    bPumpEnable := FALSE;
    bHeaterEnable := FALSE;
    bChillerEnable := FALSE;
    bExtractionValveOpen := FALSE;
    bCyclone1ValveOpen := FALSE;
    bCyclone2ValveOpen := FALSE;
    rPumpSpeedCmd_pct := 0.0;
    rHeaterPower_pct := 0.0;
    sStatusMessage := 'EMERGENCY STOP';
    RETURN;
END_IF;

CASE iProcessState OF
    0: (* Idle *)
        sStatusMessage := 'Idle';
        IF rtStart.Q THEN
            iProcessState := 1;
            rCurrentTargetPressure := rVesselPressure_Bar;
            rIntegralPump := 0.0;
            rIntegralHeater := 0.0;
            bChillerEnable := TRUE;
            bExtractionValveOpen := TRUE;
        END_IF;

    1: (* Pressurizing *)
        sStatusMessage := 'Pressurizing Vessel';
        bPumpEnable := TRUE;
        bHeaterEnable := TRUE;

        (* Ramp pressure *)
        IF rCurrentTargetPressure < rTargetPressure_Bar THEN
            rCurrentTargetPressure := rCurrentTargetPressure + (rPressureRampRate / 60.0);
        ELSE
            rCurrentTargetPressure := rTargetPressure_Bar;
        END_IF;

        (* PI Control for Pump (Pressure) *)
        rPressureError := rCurrentTargetPressure - rVesselPressure_Bar;
        rIntegralPump := rIntegralPump + (rPressureError * rKi_Pump);
        IF rIntegralPump > 100.0 THEN rIntegralPump := 100.0; END_IF;
        IF rIntegralPump < 0.0 THEN rIntegralPump := 0.0; END_IF;
        rPumpSpeedCmd_pct := (rKp_Pump * rPressureError) + rIntegralPump;
        IF rPumpSpeedCmd_pct > 100.0 THEN rPumpSpeedCmd_pct := 100.0; END_IF;
        IF rPumpSpeedCmd_pct < 0.0 THEN rPumpSpeedCmd_pct := 0.0; END_IF;

        (* PI Control for Heater (Temperature) *)
        rTempError := rTargetTemp_C - rVesselTemp_C;
        rIntegralHeater := rIntegralHeater + (rTempError * rKi_Heater);
        IF rIntegralHeater > 100.0 THEN rIntegralHeater := 100.0; END_IF;
        IF rIntegralHeater < 0.0 THEN rIntegralHeater := 0.0; END_IF;
        rHeaterPower_pct := (rKp_Heater * rTempError) + rIntegralHeater;
        IF rHeaterPower_pct > 100.0 THEN rHeaterPower_pct := 100.0; END_IF;
        IF rHeaterPower_pct < 0.0 THEN rHeaterPower_pct := 0.0; END_IF;

        IF (ABS(rVesselPressure_Bar - rTargetPressure_Bar) < 2.0) AND (ABS(rVesselTemp_C - rTargetTemp_C) < 1.0) THEN
            iProcessState := 3;
            bCyclone1ValveOpen := TRUE;
            bCyclone2ValveOpen := TRUE;
        END_IF;

    3: (* Extracting *)
        sStatusMessage := 'Extracting - Supercritical Phase';
        bSupercriticalPhase := (rVesselPressure_Bar > 73.8) AND (rVesselTemp_C > 31.1);

        rPressureError := rTargetPressure_Bar - rVesselPressure_Bar;
        rIntegralPump := rIntegralPump + (rPressureError * rKi_Pump);
        rPumpSpeedCmd_pct := (rKp_Pump * rPressureError) + rIntegralPump;
        IF rPumpSpeedCmd_pct > 100.0 THEN rPumpSpeedCmd_pct := 100.0; END_IF;
        IF rPumpSpeedCmd_pct < 0.0 THEN rPumpSpeedCmd_pct := 0.0; END_IF;

        rTempError := rTargetTemp_C - rVesselTemp_C;
        rIntegralHeater := rIntegralHeater + (rTempError * rKi_Heater);
        rHeaterPower_pct := (rKp_Heater * rTempError) + rIntegralHeater;
        IF rHeaterPower_pct > 100.0 THEN rHeaterPower_pct := 100.0; END_IF;
        IF rHeaterPower_pct < 0.0 THEN rHeaterPower_pct := 0.0; END_IF;

        fbTimerExtraction(IN := TRUE, PT := tExtractionTime);
        IF fbTimerExtraction.Q THEN
            fbTimerExtraction(IN := FALSE);
            iProcessState := 4;
        END_IF;

    4: (* Depressurizing *)
        sStatusMessage := 'Depressurizing';
        bPumpEnable := FALSE;
        bHeaterEnable := FALSE;
        rPumpSpeedCmd_pct := 0.0;
        rHeaterPower_pct := 0.0;
        bExtractionValveOpen := FALSE;

        IF rVesselPressure_Bar < 10.0 THEN
            bCyclone1ValveOpen := FALSE;
            bCyclone2ValveOpen := FALSE;
            bChillerEnable := FALSE;
            iProcessState := 0;
        END_IF;

    5: (* Fault *)
        sStatusMessage := 'FAULT STATE';
        bPumpEnable := FALSE;
        bHeaterEnable := FALSE;
        rPumpSpeedCmd_pct := 0.0;
        rHeaterPower_pct := 0.0;
END_CASE;
END_FUNCTION_BLOCK\n```
