\nFUNCTION_BLOCK FB_WireHarnessControl
FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Advanced Wire Harness Manufacturing Control'
VERSION : '1.5'

VAR_INPUT
    bEnableSystem       : BOOL;         // Master enable command
    bEmergencyStop      : BOOL;         // E-Stop signal (NC)
    bReset              : BOOL;         // Fault reset push button

    rWireFeedPos        : REAL;         // Current wire feed position from encoder (mm)
    rStripDepthSensor   : REAL;         // Laser micrometer depth sensor reading (um)
    rCrimpForce         : REAL;         // Peak force sensor reading from piezo cell (N)
    bContinuityPass     : BOOL;         // High-speed electrical test result (TRUE = Pass)
    bJacketDetect       : BOOL;         // Optical sensor for jacket presence

    rTargetLength       : REAL := 150.0;// Target wire length (mm)
    rStripDepthSetPt    : REAL := 2.5;  // Target strip depth (um)
    rStripDepthTol      : REAL := 0.1;  // Strip depth tolerance (um)
    rCrimpForceTarget   : REAL := 450.0;// Target crimp force (N)
    rCrimpForceTol      : REAL := 15.0; // Crimp force tolerance (N)
    tCycleTimeout       : TIME := T#2s; // Max allowable cycle time
END_VAR

VAR_OUTPUT
    bSystemReady        : BOOL;         // System ready for operation
    bFaultActive        : BOOL;         // Fault present in the system
    nFaultCode          : INT;          // Active fault code for HMI

    rDriveSpeed         : REAL;         // Feed drive speed reference (mm/s)
    bBladeActuate       : BOOL;         // Strip blade actuation solenoid command
    bCrimpPress         : BOOL;         // Crimp press actuation servo command
    bRejectGate         : BOOL;         // Reject gate solenoid (divert bad part)
    bTestProbeActuate   : BOOL;         // Actuate electrical test probes

    rLastStripDepth     : REAL;         // Quality tracking: Last strip depth
    rLastCrimpForce     : REAL;         // Quality tracking: Last crimp force
    nTotalProduced      : DINT;         // Production metric: Good parts
    nTotalRejected      : DINT;         // Production metric: Bad parts
END_VAR

VAR
    eState              : INT := 0;     // Main sequence state machine
    ePrevState          : INT := 0;     // Previous state for transition tracking
    bInitComplete       : BOOL := FALSE;// Initialization flag
    tonCycleTimer       : TON;          // Cycle watchdog timeout
    tonDelay            : TON;          // General purpose process delay
    trigReset           : R_TRIG;       // Rising edge trigger for reset
END_VAR

VAR CONSTANT
    STATE_INIT          : INT := 0;
    STATE_IDLE          : INT := 10;
    STATE_FEED          : INT := 20;
    STATE_STRIP         : INT := 30;
    STATE_CRIMP         : INT := 40;
    STATE_TEST          : INT := 50;
    STATE_EJECT         : INT := 60;
    STATE_FAULT         : INT := 99;

    ERR_NONE            : INT := 0;
    ERR_ESTOP           : INT := 1000;
    ERR_FEED_TIMEOUT    : INT := 1001;
    ERR_STRIP_DEPTH     : INT := 1002;
    ERR_CRIMP_FORCE     : INT := 1003;
    ERR_CONTINUITY      : INT := 1004;
    ERR_JACKET_MISSING  : INT := 1005;
END_VAR

// --- Safety and Fault Reset Logic ---
IF NOT bEmergencyStop THEN
    eState := STATE_FAULT;
    nFaultCode := ERR_ESTOP;
END_IF;

trigReset(CLK := bReset);
IF trigReset.Q AND bEmergencyStop THEN
    IF eState = STATE_FAULT THEN
        eState := STATE_INIT;
        nFaultCode := ERR_NONE;
        bFaultActive := FALSE;
        bSystemReady := TRUE;
    END_IF;
END_IF;

// --- Main Manufacturing State Machine ---
CASE eState OF
    STATE_INIT:
        rDriveSpeed := 0.0;
        bBladeActuate := FALSE;
        bCrimpPress := FALSE;
        bRejectGate := FALSE;
        bTestProbeActuate := FALSE;
        eState := STATE_IDLE;
        tonCycleTimer(IN := FALSE);

    STATE_IDLE:
        IF bEnableSystem AND NOT bFaultActive THEN
            tonCycleTimer(IN := TRUE, PT := tCycleTimeout);
            eState := STATE_FEED;
        END_IF;

    STATE_FEED:
        rDriveSpeed := 800.0; // High speed positioning (mm/s)
        IF rWireFeedPos >= rTargetLength THEN
            rDriveSpeed := 0.0;
            IF NOT bJacketDetect THEN
                nFaultCode := ERR_JACKET_MISSING;
                eState := STATE_FAULT;
            ELSE
                eState := STATE_STRIP;
            END_IF;
        END_IF;

    STATE_STRIP:
        bBladeActuate := TRUE;
        tonDelay(IN := bBladeActuate, PT := T#125ms);
        IF tonDelay.Q THEN
            rLastStripDepth := rStripDepthSensor;
            IF ABS(rLastStripDepth - rStripDepthSetPt) > rStripDepthTol THEN
                nFaultCode := ERR_STRIP_DEPTH;
                eState := STATE_FAULT;
            ELSE
                bBladeActuate := FALSE;
                tonDelay(IN := FALSE);
                eState := STATE_CRIMP;
            END_IF;
        END_IF;

    STATE_CRIMP:
        bCrimpPress := TRUE;
        tonDelay(IN := bCrimpPress, PT := T#150ms);
        IF tonDelay.Q THEN
            rLastCrimpForce := rCrimpForce;
            IF ABS(rLastCrimpForce - rCrimpForceTarget) > rCrimpForceTol THEN
                nFaultCode := ERR_CRIMP_FORCE;
                eState := STATE_FAULT;
            ELSE
                bCrimpPress := FALSE;
                tonDelay(IN := FALSE);
                eState := STATE_TEST;
            END_IF;
        END_IF;

    STATE_TEST:
        bTestProbeActuate := TRUE;
        tonDelay(IN := bTestProbeActuate, PT := T#50ms);
        IF tonDelay.Q THEN
            IF bContinuityPass THEN
                bTestProbeActuate := FALSE;
                tonDelay(IN := FALSE);
                eState := STATE_EJECT;
            ELSE
                nFaultCode := ERR_CONTINUITY;
                eState := STATE_FAULT;
            END_IF;
        END_IF;

    STATE_EJECT:
        bRejectGate := FALSE; // Ensure gate routes to good bin
        nTotalProduced := nTotalProduced + 1;
        tonCycleTimer(IN := FALSE);
        eState := STATE_IDLE;

    STATE_FAULT:
        bSystemReady := FALSE;
        bFaultActive := TRUE;
        rDriveSpeed := 0.0;
        bBladeActuate := FALSE;
        bCrimpPress := FALSE;
        bTestProbeActuate := FALSE;
        bRejectGate := TRUE;  // Divert part to reject bin on fault

        // Increment reject counter exactly once upon fault entry
        IF ePrevState <> STATE_FAULT THEN
            nTotalRejected := nTotalRejected + 1;
        END_IF;
        tonCycleTimer(IN := FALSE);

END_CASE;

ePrevState := eState;

// Cycle Timeout Watchdog
IF tonCycleTimer.Q AND eState <> STATE_IDLE AND eState <> STATE_FAULT THEN
    nFaultCode := ERR_FEED_TIMEOUT;
    eState := STATE_FAULT;
END_IF;

END_FUNCTION_BLOCK\n```
