FUNCTION_BLOCK FB_SubseaBOP_MUX_Control
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnableMuxSystem     : BOOL;     (* Main power and multiplex system enable *)
    bEmergencyDisconnect : BOOL;     (* Emergency Disconnect Sequence (EDS) trigger *)
    bDeadmanSwitchStatus : BOOL;     (* Loss of communication and power deadman trigger *)
    bAcousticFireCommand : BOOL;     (* Acoustic telemetry backup firing trigger *)
    rAccumulatorPress    : REAL;     (* Subsea accumulator bank pressure [psi] *)
    rAmbientPressure     : REAL;     (* Ambient seawater pressure at depth [psi] *)
    rShearRamPosFeedback : REAL;     (* Feedback position of blind shear rams [0.0 - 100.0%] *)
    bRedundantPodActive  : BOOL;     (* Indicates if the redundant yellow/blue pod is active *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady         : BOOL;     (* BOP control system ready for operations *)
    bShearRamActuate     : BOOL;     (* Output to electro-hydraulic pilot valve for shear rams *)
    bAnnularActuate      : BOOL;     (* Output to actuate annular preventer *)
    rCompensatedPress    : REAL;     (* Depth-compensated available hydraulic pressure [psi] *)
    bCriticalFaultAlarm  : BOOL;     (* General critical fault indicator *)
    bEDSSequenceActive   : BOOL;     (* Indicates EDS is currently in progress *)
END_VAR
VAR
    (* Internal state variables *)
    iState               : INT := 0; (* MUX Control State Machine *)
    tActuationTimer      : TON;      (* Timer for physical actuation timeouts *)
    bLocalEDSFlag        : BOOL := FALSE;
    bLocalDeadmanFlag    : BOOL := FALSE;
    rMinRequiredPressure : REAL := 3000.0; (* Min pressure diff required for shear [psi] *)
    rDifferentialPress   : REAL;
END_VAR

(* === MAIN LOGIC === *)
(* Calculate ambient compensated pressure *)
rDifferentialPress := rAccumulatorPress - rAmbientPressure;
rCompensatedPress := rDifferentialPress;

(* Check critical pressure fault *)
IF rDifferentialPress < rMinRequiredPressure AND iState > 0 THEN
    bCriticalFaultAlarm := TRUE;
ELSE
    bCriticalFaultAlarm := FALSE;
END_IF;

(* Latch emergency conditions *)
IF bEmergencyDisconnect OR bAcousticFireCommand THEN
    bLocalEDSFlag := TRUE;
END_IF;

IF NOT bDeadmanSwitchStatus THEN
    bLocalDeadmanFlag := TRUE;
END_IF;

CASE iState OF
    0: (* INIT / STANDBY *)
        bSystemReady := FALSE;
        bShearRamActuate := FALSE;
        bAnnularActuate := FALSE;
        bEDSSequenceActive := FALSE;
        IF bEnableMuxSystem AND rDifferentialPress >= rMinRequiredPressure THEN
            bSystemReady := TRUE;
            iState := 10;
        END_IF;

    10: (* NORMAL OPERATIONS *)
        IF bLocalEDSFlag OR bLocalDeadmanFlag THEN
            bSystemReady := FALSE;
            bEDSSequenceActive := TRUE;
            iState := 100; (* Jump to EDS Sequence *)
        END_IF;

        (* Normal operation logic would be placed here (e.g., manual annular control) *)

    100: (* EMERGENCY DISCONNECT SEQUENCE - FIRE SHEAR RAMS *)
        (* First priority: Actuate Blind Shear Rams *)
        bShearRamActuate := TRUE;
        tActuationTimer(IN := TRUE, PT := T#15S);

        IF rShearRamPosFeedback >= 99.5 THEN
            (* Shear rams successfully closed *)
            tActuationTimer(IN := FALSE);
            iState := 110;
        ELSIF tActuationTimer.Q THEN
            (* Timeout actuating shear rams - trigger critical fault but proceed to annular *)
            bCriticalFaultAlarm := TRUE;
            tActuationTimer(IN := FALSE);
            iState := 110;
        END_IF;

    110: (* EDS - CLOSE ANNULAR AND DISCONNECT *)
        bAnnularActuate := TRUE;
        tActuationTimer(IN := TRUE, PT := T#10S);

        IF tActuationTimer.Q THEN
            tActuationTimer(IN := FALSE);
            iState := 120;
        END_IF;

    120: (* EDS - SECURED *)
        (* LMRP disconnect commands would fire here *)
        (* System remains in this terminal state until reset by ROV intervention *)
        bShearRamActuate := TRUE;
        bAnnularActuate := TRUE;

END_CASE;

END_FUNCTION_BLOCK
