FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bStartSequence : BOOL; (* Initiate wash sequence *)
    bEmergencyStop : BOOL; (* Global E-Stop *)
    bTrainDetected : BOOL; (* Train entry sensor *)
    bPantographLowered : BOOL; (* Clearance interlock *)
    rTrainSpeed : REAL; (* Speed of train in m/s *)
    rROWaterPressure : REAL; (* Reverse Osmosis pressure in bar *)
    rBrushTorqueFeedback : REAL; (* Torque on main brushes in Nm *)
    bWaterTankLow : BOOL; (* Low water level switch *)
END_VAR

VAR_OUTPUT
    bPumpStart : BOOL; (* Start main water pump *)
    bROValveOpen : BOOL; (* Open Reverse Osmosis valve *)
    bBrushMotorStart : BOOL; (* Start brush motors *)
    rBrushSpeedSetPoint : REAL; (* Setpoint for VFDs *)
    bAlarmActive : BOOL; (* System alarm state *)
    iWashState : INT; (* Current state of the wash sequence *)
    sStatusMessage : STRING(50); (* HMI Status *)
END_VAR

VAR
    TMR_WashCycle : TON;
    TMR_PreRinse : TON;
    TMR_SoapDwell : TON;
    bInterlocksOK : BOOL;
    rMaxTorque : REAL := 150.0; (* Max allowable brush torque *)
    rMinPressure : REAL := 3.5; (* Min required RO pressure *)
END_VAR

(* Interlock verification *)
bInterlocksOK := bPantographLowered AND NOT bEmergencyStop AND NOT bWaterTankLow;

IF bEmergencyStop THEN
    iWashState := 99; (* E-Stop State *)
    bPumpStart := FALSE;
    bROValveOpen := FALSE;
    bBrushMotorStart := FALSE;
    bAlarmActive := TRUE;
    sStatusMessage := 'EMERGENCY STOP ACTIVE';
ELSIF NOT bInterlocksOK THEN
    iWashState := 0;
    bPumpStart := FALSE;
    bROValveOpen := FALSE;
    bBrushMotorStart := FALSE;
    bAlarmActive := TRUE;
    sStatusMessage := 'INTERLOCKS NOT MET';
ELSE
    bAlarmActive := FALSE;
END_IF;

CASE iWashState OF
    0: (* Idle / Ready *)
        sStatusMessage := 'SYSTEM READY';
        IF bStartSequence AND bTrainDetected AND bInterlocksOK THEN
            iWashState := 10;
        END_IF;

    10: (* Pre-rinse stage *)
        sStatusMessage := 'PRE-RINSE ACTIVE';
        bPumpStart := TRUE;
        TMR_PreRinse(IN:=TRUE, PT:=T#15S);
        IF TMR_PreRinse.Q THEN
            TMR_PreRinse(IN:=FALSE);
            iWashState := 20;
        END_IF;

    20: (* Brush Wash stage *)
        sStatusMessage := 'BRUSH WASH ACTIVE';
        bBrushMotorStart := TRUE;
        rBrushSpeedSetPoint := 50.0; (* Base speed *)

        (* Torque feedback loop - simplify *)
        IF rBrushTorqueFeedback > rMaxTorque THEN
            bAlarmActive := TRUE;
            iWashState := 99; (* Fault state *)
            sStatusMessage := 'BRUSH TORQUE FAULT';
        END_IF;

        (* Advance based on some timer or train position *)
        TMR_WashCycle(IN:=TRUE, PT:=T#45S);
        IF TMR_WashCycle.Q THEN
            TMR_WashCycle(IN:=FALSE);
            bBrushMotorStart := FALSE;
            bPumpStart := FALSE;
            iWashState := 30;
        END_IF;

    30: (* Reverse Osmosis Spot-Free Rinse *)
        sStatusMessage := 'RO RINSE ACTIVE';
        IF rROWaterPressure >= rMinPressure THEN
            bROValveOpen := TRUE;
            TMR_SoapDwell(IN:=TRUE, PT:=T#20S);
            IF TMR_SoapDwell.Q THEN
                TMR_SoapDwell(IN:=FALSE);
                bROValveOpen := FALSE;
                iWashState := 40;
            END_IF;
        ELSE
            bAlarmActive := TRUE;
            iWashState := 99;
            sStatusMessage := 'LOW RO PRESSURE';
        END_IF;

    40: (* Complete *)
        sStatusMessage := 'WASH COMPLETE';
        IF NOT bTrainDetected THEN
            iWashState := 0;
        END_IF;

    99: (* Fault/Error Handling *)
        bPumpStart := FALSE;
        bROValveOpen := FALSE;
        bBrushMotorStart := FALSE;
        rBrushSpeedSetPoint := 0.0;
        IF NOT bEmergencyStop AND bInterlocksOK THEN
            (* Reset logic here *)
            iWashState := 0;
        END_IF;
END_CASE;
