FUNCTION_BLOCK "RO_Control_Depth"
TITLE = 'RO Control System with Dosing'
VERSION : 0.2

VAR_INPUT
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;
    Feed_Pressure : REAL;
    Feed_Flow_Rate : REAL;
    Permeate_Conductivity : REAL;
    High_Pressure_Setpoint : REAL;
    Conductivity_Limit : REAL;
    Dosing_Ratio : REAL; // ml per liter of feed flow
    Tank_Level_High : BOOL;
    Ack_Fault : BOOL;
