        Dosing_Pump_Run := FALSE;
        Dosing_Pump_Speed := 0.0;
    END_IF;

    // State Machine
    IF System_Fault THEN
        State := 4;
    ELSIF Stop_Cmd OR Tank_Level_High THEN
        IF State = 2 THEN
            State := 3; 
        ELSE
            State := 0;
        END_IF;
    ELSIF Start_Cmd AND NOT System_Fault AND State = 0 THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Off
            HP_Pump_Run := FALSE;
            HP_Pump_Speed := 0.0;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
            Flush_Timer(IN:=FALSE, PT:=T#0S);
        1: // Startup
            Inlet_Valve := TRUE;
            Flush_Valve := FALSE;
            HP_Pump_Run := TRUE;
            State := 2;
        2: // Running
            Inlet_Valve := TRUE;
            Flush_Valve := FALSE;
            HP_Pump_Run := TRUE;
            PID_Inst(Setpoint := High_Pressure_Setpoint,
                     Feedback := Feed_Pressure,
                     Output => HP_Pump_Speed);
        3: // Flushing
            Inlet_Valve := TRUE;
            Flush_Valve := TRUE;
            HP_Pump_Run := TRUE;
            HP_Pump_Speed := 50.0;
            Flush_Timer(IN:=TRUE, PT:=T#30S);
            IF Flush_Timer.Q THEN
                State := 0;
            END_IF;
        4: // Fault
            HP_Pump_Run := FALSE;
            HP_Pump_Speed := 0.0;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
