FUNCTION_BLOCK FB_LNG_Reliquefaction_Control
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bSystemEnable       : BOOL;     (* Master reliquefaction enable command from IAS *)
    bEmergencyStop      : BOOL;     (* ESD Safety loop OK signal (1 = OK, 0 = TRIP) *)
    rCargoTankPressure  : REAL;     (* Cargo tank pressure measured in barg *)
    rBOGCompInletTemp   : REAL;     (* Boil-Off Gas compressor inlet temperature in degC *)
    rN2ExpanderSpeed    : REAL;     (* Nitrogen expander speed feedback in rpm *)
    rSurgeMargin        : REAL;     (* BOG compressor calculated surge margin (%) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bReliquefactionReady: BOOL;     (* Plant is ready and stable for full capacity *)
    rBOGCompSpeedCmd    : REAL;     (* BOG Compressor VFD speed reference (0-100%) *)
    rJTVValvePosCmd     : REAL;     (* Joule-Thomson valve position control (0-100%) *)
    bSurgeAlarm         : BOOL;     (* Anti-surge protection warning active *)
    bTripStatus         : BOOL;     (* Plant trip alarm status *)
END_VAR
VAR
    (* Internal state and control variables *)
    iState              : INT := 0;
    tPreCoolTimer       : TON;
    tPurgeTimer         : TON;
    rTempSetpoint       : REAL := -160.0; (* Liquefaction temperature target in degC *)
    rPressureSetpoint   : REAL := 0.15;   (* Tank pressure target in barg *)

    (* PID Control internal state for Pressure cascade *)
    rPID_Kp             : REAL := 2.5;
    rPID_Ki             : REAL := 0.1;
    rPID_Error          : REAL;
    rPID_Integral       : REAL := 0.0;

    (* Anti-surge internal variables *)
    rMinSurgeMargin     : REAL := 10.0; (* Minimum safe margin before acting (%) *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    (* Instantaneous safety trip action *)
    bReliquefactionReady := FALSE;
    rBOGCompSpeedCmd := 0.0;
    rJTVValvePosCmd := 0.0;
    bSurgeAlarm := FALSE;
    bTripStatus := TRUE;
    iState := 99; (* Transition to fault state *)
    RETURN;
END_IF;

(* === MAIN STATE MACHINE: RELIQUEFACTION SEQUENCER === *)
CASE iState OF
    0: (* STATE 0: IDLE AND WAITING FOR START *)
        bTripStatus := FALSE;
        bReliquefactionReady := FALSE;
        rBOGCompSpeedCmd := 0.0;
        rJTVValvePosCmd := 0.0;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* STATE 10: PRE-COOLING AND PURGE *)
        (* Initiate cryogenic cooling sequence of the cold box *)
        rJTVValvePosCmd := 15.0; (* Crack open JT valve for initial cooldown *)
        tPreCoolTimer(IN := TRUE, PT := T#120S);

        IF tPreCoolTimer.Q THEN
            tPreCoolTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* STATE 20: BOG COMPRESSOR STARTUP AND ANTI-SURGE CHECK *)
        (* Ensure nitrogen circuit is spinning before loading BOG compressor *)
        IF rN2ExpanderSpeed > 15000.0 THEN
            (* Start loading the compressor slowly *)
            rBOGCompSpeedCmd := rBOGCompSpeedCmd + 0.1;

            IF rBOGCompSpeedCmd >= 30.0 THEN
                iState := 30;
            END_IF;
        END_IF;

        (* Anti-surge fast override during startup *)
        IF rSurgeMargin < rMinSurgeMargin THEN
            bSurgeAlarm := TRUE;
            rBOGCompSpeedCmd := rBOGCompSpeedCmd + 5.0; (* Speed up to avoid surge *)
        ELSE
            bSurgeAlarm := FALSE;
        END_IF;

    30: (* STATE 30: STEADY STATE CASCADED CONTROL *)
        bReliquefactionReady := TRUE;

        (* PI Controller for Tank Pressure Control *)
        rPID_Error := rCargoTankPressure - rPressureSetpoint;
        rPID_Integral := rPID_Integral + (rPID_Error * 0.1); (* Assuming 100ms cycle *)

        (* Anti-windup clamping *)
        IF rPID_Integral > 100.0 THEN rPID_Integral := 100.0; END_IF;
        IF rPID_Integral < 0.0 THEN rPID_Integral := 0.0; END_IF;

        rBOGCompSpeedCmd := (rPID_Kp * rPID_Error) + (rPID_Ki * rPID_Integral);

        (* Limit command outputs *)
        IF rBOGCompSpeedCmd > 100.0 THEN rBOGCompSpeedCmd := 100.0; END_IF;
        IF rBOGCompSpeedCmd < 30.0 THEN rBOGCompSpeedCmd := 30.0; END_IF;

        (* Joule-Thomson Valve Thermal Control based on compressor suction *)
        IF rBOGCompInletTemp > -120.0 THEN
            rJTVValvePosCmd := rJTVValvePosCmd + 0.05; (* Need more cooling *)
        ELSE
            rJTVValvePosCmd := rJTVValvePosCmd - 0.05; (* Prevent liquid carryover *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 40;
        END_IF;

    40: (* STATE 40: NORMAL SHUTDOWN *)
        bReliquefactionReady := FALSE;
        rBOGCompSpeedCmd := rBOGCompSpeedCmd - 0.5; (* Ramp down *)
        rJTVValvePosCmd := rJTVValvePosCmd - 0.5;

        IF rBOGCompSpeedCmd <= 0.0 AND rJTVValvePosCmd <= 0.0 THEN
            rBOGCompSpeedCmd := 0.0;
            rJTVValvePosCmd := 0.0;
            iState := 0;
        END_IF;

    99: (* STATE 99: TRIP / FAULT RECOVERY *)
        (* Wait for ESD reset and operator enable signal transition *)
        IF NOT bEmergencyStop AND NOT bSystemEnable THEN
            bTripStatus := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

