FUNCTION_BLOCK FB_OTEC_AmmoniaTurbine
(* 
   Advanced OTEC Ammonia Turbine Control 
   Includes VIV suppression for CWP, cascaded pressure letdown, and turbine load management.
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System Enable Signal *)
    bEmergencyStop          : BOOL;     (* Emergency Stop / Safety Chain OK *)
    rWarmSeawaterTemp_C     : REAL;     (* Warm Seawater Inlet Temperature (deg C) *)
    rColdSeawaterTemp_C     : REAL;     (* Cold Seawater Inlet Temperature (deg C) *)
    rAmmoniaVaporPress_Bar  : REAL;     (* Ammonia Vapor Pressure at Turbine Inlet (Bar) *)
    rTurbineSpeed_RPM       : REAL;     (* Turbine Rotor Speed (RPM) *)
    rCWP_VIV_Amplitude_mm   : REAL;     (* Cold Water Pipe Vortex Induced Vibration Amplitude (mm) *)
    rGridFrequency_Hz       : REAL;     (* Grid Frequency for Synchronization (Hz) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Turbine Ready for Synchronization *)
    bGridSyncPulse          : BOOL;     (* Grid Synchronization Command Pulse *)
    rGuideVanePos_Pct       : REAL;     (* Turbine Guide Vane Position Command (0-100%) *)
    rBypassValvePos_Pct     : REAL;     (* Ammonia Bypass Valve Position Command (0-100%) *)
    rVIVSuppressionThrust_N : REAL;     (* Active VIV Suppression Thruster Output (N) *)
    bAlarmCrit              : BOOL;     (* Critical Alarm / Trip Signal *)
END_VAR

VAR
    iState                  : INT := 0; (* State Machine Index *)
    tStartupDelay           : TON;
    tSyncPulseTimer         : TON;
    rAmmoniaSuperheat_K     : REAL;
    rSpeedError             : REAL;
    rTargetSpeed            : REAL := 3000.0; (* Nominal RPM for 50Hz grid, 2-pole *)
    bCWP_VIV_Active         : BOOL;

    (* PI Controller for Speed *)
    rKp_Speed               : REAL := 0.45;
    rKi_Speed               : REAL := 0.12;
    rIntegralTerm           : REAL := 0.0;
    rProportionalTerm       : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)

(* Safety Interlock Check *)
IF NOT bEmergencyStop THEN
    iState := 999; (* Trip state *)
END_IF;

(* CWP VIV Suppression Logic *)
IF rCWP_VIV_Amplitude_mm > 50.0 THEN
    bCWP_VIV_Active := TRUE;
    (* Proportional counter-thrust based on amplitude to dampen vibration *)
    rVIVSuppressionThrust_N := (rCWP_VIV_Amplitude_mm - 50.0) * 1500.0; 
    IF rVIVSuppressionThrust_N > 100000.0 THEN
        rVIVSuppressionThrust_N := 100000.0;
    END_IF;
ELSE
    bCWP_VIV_Active := FALSE;
    rVIVSuppressionThrust_N := 0.0;
END_IF;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bGridSyncPulse := FALSE;
        rGuideVanePos_Pct := 0.0;
        rBypassValvePos_Pct := 100.0; (* Full bypass on idle *)
        bAlarmCrit := FALSE;

        IF bEnable AND bEmergencyStop THEN
            IF rWarmSeawaterTemp_C > 22.0 AND rColdSeawaterTemp_C < 7.0 THEN
                iState := 10; (* Priming and Pressurization *)
            END_IF;
        END_IF;

    10: (* PRIMING & PRESSURIZATION *)
        rBypassValvePos_Pct := 50.0;
        (* Wait for minimum ammonia vapor pressure *)
        IF rAmmoniaVaporPress_Bar >= 8.5 THEN
            tStartupDelay(IN := TRUE, PT := T#10S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20; (* Turbine Spin-up *)
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* TURBINE SPIN-UP *)
        (* Gradually close bypass and open guide vanes to reach target RPM *)
        rSpeedError := rTargetSpeed - rTurbineSpeed_RPM;

        rProportionalTerm := rKp_Speed * rSpeedError;
        rIntegralTerm := rIntegralTerm + (rKi_Speed * rSpeedError * 0.1); (* Assuming 100ms task rate *)

        (* Anti-windup *)
        IF rIntegralTerm > 100.0 THEN rIntegralTerm := 100.0; END_IF;
        IF rIntegralTerm < 0.0 THEN rIntegralTerm := 0.0; END_IF;

        rGuideVanePos_Pct := rProportionalTerm + rIntegralTerm;

        IF rGuideVanePos_Pct > 100.0 THEN rGuideVanePos_Pct := 100.0; END_IF;
        IF rGuideVanePos_Pct < 0.0 THEN rGuideVanePos_Pct := 0.0; END_IF;

        rBypassValvePos_Pct := 100.0 - rGuideVanePos_Pct;

        IF ABS(rSpeedError) < 15.0 AND rTurbineSpeed_RPM > 2900.0 THEN
            iState := 30; (* Synchronization Ready *)
        END_IF;

    30: (* SYNCHRONIZATION READY *)
        bSystemReady := TRUE;
        (* Fine tune speed to match grid frequency *)
        rTargetSpeed := rGridFrequency_Hz * 60.0; 

        (* Simple phase matching simulation *)
        IF ABS(rTargetSpeed - rTurbineSpeed_RPM) < 2.0 THEN
            bGridSyncPulse := TRUE;
            tSyncPulseTimer(IN := TRUE, PT := T#500MS);
            IF tSyncPulseTimer.Q THEN
                iState := 40; (* Loaded / Operating *)
            END_IF;
        END_IF;

    40: (* LOADED / OPERATING *)
        bGridSyncPulse := FALSE;
        (* In loaded state, load controller takes over guide vanes (simulated here) *)
        rGuideVanePos_Pct := 85.0; 
        rBypassValvePos_Pct := 0.0;

        IF rTurbineSpeed_RPM > 3300.0 OR rAmmoniaVaporPress_Bar > 15.0 THEN
            iState := 999; (* Trip on overspeed or overpressure *)
        END_IF;

    999: (* TRIP / EMERGENCY STOP *)
        bSystemReady := FALSE;
        bGridSyncPulse := FALSE;
        rGuideVanePos_Pct := 0.0;
        rBypassValvePos_Pct := 100.0; 
        bAlarmCrit := TRUE;
        rIntegralTerm := 0.0;

        IF bEmergencyStop AND NOT bEnable THEN
            iState := 0; (* Reset sequence *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

