FUNCTION_BLOCK FB_H2TurbineControl
TITLE = 'Hydrogen Gas Turbine Advanced Control System'
VERSION : '1.0'

(*
=============================================================================
DESCRIPTION:
This function block manages the critical control loops for a Hydrogen-fueled 
Gas Turbine Power Plant. It handles multi-stage combustor flame stability,
NOx suppression via water injection, and grid synchronization. 
The control logic utilizes advanced PID control and sequence state machines.
=============================================================================
*)

VAR_INPUT
    // Physical I/O - Sensors
    rFlameIntensity_Stage1 : REAL;     (* % Flame intensity in primary combustor stage *)
    rFlameIntensity_Stage2 : REAL;     (* % Flame intensity in secondary combustor stage *)
    rTurbineInletTemp      : REAL;     (* C Turbine Inlet Temperature (TIT) *)
    rExhaustNOxLevel       : REAL;     (* ppm NOx emissions measured at exhaust stack *)
    rGridVoltage           : REAL;     (* kV Current grid voltage *)
    rGridFrequency         : REAL;     (* Hz Current grid frequency *)
    rGeneratorVoltage      : REAL;     (* kV Current generator voltage *)
    rGeneratorFrequency    : REAL;     (* Hz Current generator frequency *)
    rGeneratorPhase        : REAL;     (* deg Phase angle of generator relative to grid *)
    bStartSequence         : BOOL;     (* Command to initiate turbine startup sequence *)
    bStopSequence          : BOOL;     (* Command to initiate turbine shutdown sequence *)
    bGridSyncEnable        : BOOL;     (* Command to enable grid synchronization *)
END_VAR

VAR_OUTPUT
    // Physical I/O - Actuators
    rH2FuelValve_Stage1    : REAL;     (* % Command for primary H2 fuel valve (0-100%) *)
    rH2FuelValve_Stage2    : REAL;     (* % Command for secondary H2 fuel valve (0-100%) *)
    rWaterInjectValve      : REAL;     (* % Command for NOx suppression water injection (0-100%) *)
    bBreakerCloseCommand   : BOOL;     (* Command to close main generator breaker to grid *)

    // Status Flags
    bFlameStable           : BOOL;     (* Indicates stable flame across all stages *)
    bNOxWithinLimits       : BOOL;     (* Indicates NOx levels are within regulatory limits *)
    bGridSynchronized      : BOOL;     (* Indicates generator is synchronized and breaker is closed *)
    iTurbineState          : INT;      (* Current state of the turbine sequencer *)
END_VAR

VAR
    // Internal Control Variables
    rH2FuelDemand          : REAL := 50.0;
    rNOxError              : REAL;     
    rWaterPID_P            : REAL := 0.5; 
    rWaterPID_I            : REAL := 0.1; 
    rWaterPID_Integral     : REAL := 0.0; 

    // Grid Synchronization Tolerance Variables
    rVoltDiff              : REAL;
    rFreqDiff              : REAL;
    rPhaseDiff             : REAL;

    // Timers
    tFlameLossTimer        : TON;
    tSyncWindowTimer       : TON;

    // Constants
    MAX_TIT                : REAL := 1400.0;
    NOX_SETPOINT           : REAL := 15.0;  
    MIN_FLAME_INTENSITY    : REAL := 45.0;  
    SYNC_VOLT_TOL          : REAL := 0.5;   
    SYNC_FREQ_TOL          : REAL := 0.1;   
    SYNC_PHASE_TOL         : REAL := 5.0;   
END_VAR

(* CONTROL LOGIC IMPLEMENTATION *)

// 1. Multi-Stage Combustor Flame Stability Tracking
bFlameStable := (rFlameIntensity_Stage1 > MIN_FLAME_INTENSITY) AND 
                (rFlameIntensity_Stage2 > MIN_FLAME_INTENSITY);

tFlameLossTimer(IN := NOT bFlameStable AND (iTurbineState >= 3), PT := T#2S);

IF tFlameLossTimer.Q THEN
    iTurbineState := 99; // Emergency Trip
    rH2FuelValve_Stage1 := 0.0;
    rH2FuelValve_Stage2 := 0.0;
END_IF;

IF iTurbineState >= 3 AND NOT tFlameLossTimer.Q THEN
    rH2FuelValve_Stage1 := rH2FuelDemand * 0.6;
    rH2FuelValve_Stage2 := rH2FuelDemand * 0.4;

    IF rTurbineInletTemp > MAX_TIT THEN
        rH2FuelValve_Stage1 := rH2FuelValve_Stage1 * 0.9;
        rH2FuelValve_Stage2 := rH2FuelValve_Stage2 * 0.9;
    END_IF;
END_IF;

// 2. NOx Suppression Water Injection
IF iTurbineState >= 3 THEN
    bNOxWithinLimits := (rExhaustNOxLevel <= NOX_SETPOINT + 5.0);
    rNOxError := rExhaustNOxLevel - NOX_SETPOINT;

    IF (rWaterInjectValve < 100.0 AND rNOxError > 0.0) OR (rWaterInjectValve > 0.0 AND rNOxError < 0.0) THEN
        rWaterPID_Integral := rWaterPID_Integral + (rNOxError * rWaterPID_I);
    END_IF;

    IF rNOxError > 0.0 THEN
        rWaterInjectValve := (rNOxError * rWaterPID_P) + rWaterPID_Integral;
    ELSE
        rWaterInjectValve := rWaterPID_Integral; 
    END_IF;

    IF rWaterInjectValve > 100.0 THEN rWaterInjectValve := 100.0;
    ELSIF rWaterInjectValve < 0.0 THEN rWaterInjectValve := 0.0; END_IF;
ELSE
    rWaterInjectValve := 0.0;
    rWaterPID_Integral := 0.0;
END_IF;

// 3. Grid Synchronization
IF bGridSyncEnable AND (iTurbineState = 4) THEN
    rVoltDiff := ABS(rGridVoltage - rGeneratorVoltage);
    rFreqDiff := ABS(rGridFrequency - rGeneratorFrequency);
    rPhaseDiff := ABS(rGeneratorPhase); 

    IF (rVoltDiff <= SYNC_VOLT_TOL) AND (rFreqDiff <= SYNC_FREQ_TOL) AND (rPhaseDiff <= SYNC_PHASE_TOL) THEN
        tSyncWindowTimer(IN := TRUE, PT := T#500MS);
        IF tSyncWindowTimer.Q AND NOT bGridSynchronized THEN
            bBreakerCloseCommand := TRUE;
            bGridSynchronized := TRUE;
            iTurbineState := 5; 
        END_IF;
    ELSE
        tSyncWindowTimer(IN := FALSE, PT := T#500MS);
        bBreakerCloseCommand := FALSE;
    END_IF;
ELSIF NOT bGridSyncEnable THEN
    bBreakerCloseCommand := FALSE;
    bGridSynchronized := FALSE;
    tSyncWindowTimer(IN := FALSE, PT := T#500MS);
END_IF;
END_FUNCTION_BLOCK
