FUNCTION_BLOCK FB_sCO2_BraytonCycle_Ctrl
VAR_INPUT
    (* Essential Physical Inputs for sCO2 Control *)
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (1=OK, 0=Stop) *)
    rMainCompressorInletT   : REAL;     (* sCO2 temperature at main compressor inlet [degC] *)
    rMainCompressorInletP   : REAL;     (* sCO2 pressure at main compressor inlet [bar] *)
    rTurbineInletT          : REAL;     (* sCO2 temperature at turbine inlet [degC] *)
    rGridDemandMW           : REAL;     (* Target power generation demand [MW] *)
    bPCHE_TempOK            : BOOL;     (* PCHE thermal stress limits OK *)
    rDryGasSealClearance    : REAL;     (* Dry gas seal dynamic clearance floating measurement [um] *)
END_VAR
VAR_OUTPUT
    (* Actuators and Supervisory Status *)
    bSystemReady            : BOOL;     (* Control system initialized and ready *)
    rCompressorSpeedSp      : REAL;     (* Target speed for 300-bar sub-cooling turbo-compressor [RPM] *)
    rBypassValveCmd         : REAL;     (* Bypass valve command for surge mitigation [0-100%] *)
    rHeaterPowerCmd         : REAL;     (* Power command to main heater / reactor [MW] *)
    bSurgeAlarm             : BOOL;     (* Compressor surge warning/alarm *)
    bTripCommand            : BOOL;     (* Trip command to fast-acting stop valves *)
    iOperatingState         : INT;      (* Current operating state code *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0; (* 0:IDLE, 10:PRESTART, 20:ACCEL, 30:RUN, 99:TRIP *)
    tSurgeTimer             : TON;
    tStartDelay             : TON;
    rFilteredInletT         : REAL;
    rFilteredInletP         : REAL;
    rSurgeMargin            : REAL;

    (* Low-Pass Filter Constants for Sensor Noise *)
    rAlphaT                 : REAL := 0.05;
    rAlphaP                 : REAL := 0.1;
END_VAR

(* === MAIN LOGIC === *)
(* Multi-layered safety interlock: Monitor ESTOP, Heat Exchanger Stress, and Dry Gas Seal Clearance *)
IF NOT bEmergencyStop OR NOT bPCHE_TempOK OR (rDryGasSealClearance < 2.5) THEN
    bSystemReady := FALSE;
    bTripCommand := TRUE;
    rCompressorSpeedSp := 0.0;
    rBypassValveCmd := 100.0; (* Fail-safe full open to prevent compressor surge *)
    rHeaterPowerCmd := 0.0;
    iState := 99;
    bSurgeAlarm := FALSE;
    RETURN;
END_IF;

bTripCommand := FALSE;

(* Sensor noise filtering (1st order low-pass) to ensure mathematically rigorous control inputs *)
rFilteredInletT := (rMainCompressorInletT * rAlphaT) + (rFilteredInletT * (1.0 - rAlphaT));
rFilteredInletP := (rMainCompressorInletP * rAlphaP) + (rFilteredInletP * (1.0 - rAlphaP));

(* Critical Surge Margin Calculation (Advanced dynamic modelling simulation) *)
rSurgeMargin := (rFilteredInletP * 1.5) - (rFilteredInletT * 0.8);
IF rSurgeMargin < 15.0 THEN
    bSurgeAlarm := TRUE;
    tSurgeTimer(IN := TRUE, PT := T#2S);
ELSE
    bSurgeAlarm := FALSE;
    tSurgeTimer(IN := FALSE, PT := T#2S);
END_IF;

CASE iState OF
    0: (* IDLE - Awaiting operator or remote dispatch *)
        bSystemReady := TRUE;
        rCompressorSpeedSp := 0.0;
        rBypassValveCmd := 100.0;
        rHeaterPowerCmd := 0.0;
        iOperatingState := 0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* PRESTART / SYSTEM PURGING *)
        bSystemReady := TRUE;
        iOperatingState := 10;
        rBypassValveCmd := 80.0;
        tStartDelay(IN := TRUE, PT := T#10S);

        IF tStartDelay.Q THEN
            tStartDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* ACCELERATION - Cascading spin-up of turbo-machinery *)
        iOperatingState := 20;

        (* Slowly ramp up compressor speed avoiding critical resonance frequencies *)
        IF rCompressorSpeedSp < 15000.0 THEN
            rCompressorSpeedSp := rCompressorSpeedSp + 50.0;
        END_IF;

        (* Close bypass progressively *)
        IF rBypassValveCmd > 20.0 THEN
            rBypassValveCmd := rBypassValveCmd - 0.5;
        END_IF;

        IF rCompressorSpeedSp >= 15000.0 AND rBypassValveCmd <= 20.0 THEN
            iState := 30;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* NORMAL RUNNING - Supercritical Brayton Cycle Power Block Control *)
        iOperatingState := 30;

        (* PID-driven target generation derived from Grid Demand *)
        rCompressorSpeedSp := 15000.0 + (rGridDemandMW * 50.0); 

        (* Cascading loop to primary heat source *)
        IF rTurbineInletT < 550.0 THEN
            rHeaterPowerCmd := rGridDemandMW * 1.1;
        ELSE
            rHeaterPowerCmd := rGridDemandMW * 0.9;
        END_IF;

        (* Anti-surge fast action override via dry gas dynamic boundary checking *)
        IF tSurgeTimer.Q THEN
            rBypassValveCmd := 100.0; (* Pop open bypass valve immediately *)
        ELSE
            rBypassValveCmd := 5.0; (* Keep slightly open for stability *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* TRIP / FAULT CONDITION MET *)
        bSystemReady := FALSE;
        iOperatingState := 99;
        rCompressorSpeedSp := 0.0;
        rBypassValveCmd := 100.0;
        rHeaterPowerCmd := 0.0;

        (* Require full reset of bEnable after trip condition clears *)
        IF NOT bEnable AND bEmergencyStop THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
