FUNCTION_BLOCK FB_TidalTurbineController
VAR_INPUT
    (* Core operation signals *)
    bEnable                 : BOOL;     (* System enable command *)
    bEmergencyStop          : BOOL;     (* Safety loop OK signal - hardwired safety relay *)
    (* Environmental and grid sensors *)
    rFlowVelocity           : REAL;     (* Measured tidal flow velocity [m/s] *)
    rFlowDirection          : REAL;     (* Measured tidal flow direction [deg] *)
    rRotor1Speed            : REAL;     (* Rotor 1 (forward) actual speed [rpm] *)
    rRotor2Speed            : REAL;     (* Rotor 2 (counter) actual speed [rpm] *)
    rGridVoltage            : REAL;     (* Subsea grid voltage [kV] *)
    rGridFreq               : REAL;     (* Subsea grid frequency [Hz] *)
END_VAR
VAR_OUTPUT
    (* Actuator and status outputs *)
    bSystemReady            : BOOL;     (* System ready for active power generation *)
    rPitchAngleR1           : REAL;     (* Commanded pitch angle for Rotor 1 [deg] *)
    rPitchAngleR2           : REAL;     (* Commanded pitch angle for Rotor 2 [deg] *)
    rTorqueCmd              : REAL;     (* Commanded generator torque [Nm] *)
    bGridContactor          : BOOL;     (* Connect to subsea electrical grid *)
    bAlarm                  : BOOL;     (* System fault active - require manual reset *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState                  : INT := 0;
    tTidalDelay             : TON;
    tGridSync               : TON;

    (* Filtered values & Control Variables *)
    rFilteredFlow           : REAL := 0.0;
    rSpeedError             : REAL := 0.0;
    rIntegralTorque         : REAL := 0.0;
    bFlowReversed           : BOOL := FALSE;

    (* Control Constants and Tunings *)
    Kp_Torque               : REAL := 1500.5;
    Ki_Torque               : REAL := 250.2;
    rCutInSpeed             : REAL := 1.2;
    rCutOutSpeed            : REAL := 4.5;
    rMaxTorqueLimit         : REAL := 50000.0;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency and Safety Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bGridContactor := FALSE;
    rPitchAngleR1 := 90.0; (* Feather rotors to stall condition *)
    rPitchAngleR2 := 90.0;
    rTorqueCmd := 0.0;
    bAlarm := TRUE;
    iState := 999; (* Enter hard fault state *)
    RETURN;
END_IF;

(* Filter noisy flow sensor using simple Exponential Moving Average (EMA) *)
rFilteredFlow := (rFilteredFlow * 0.95) + (rFlowVelocity * 0.05);

(* Determine bi-directional flow reversal based on compass heading *)
IF (rFlowDirection > 90.0) AND (rFlowDirection < 270.0) THEN
    bFlowReversed := TRUE;
ELSE
    bFlowReversed := FALSE;
END_IF;

CASE iState OF
    0: (* IDLE & MONITORING *)
        bSystemReady := FALSE;
        bGridContactor := FALSE;
        rPitchAngleR1 := 90.0;
        rPitchAngleR2 := 90.0;
        rTorqueCmd := 0.0;

        (* Verify conditions are met for startup *)
        IF bEnable AND (rFilteredFlow > rCutInSpeed) AND (rFilteredFlow < rCutOutSpeed) THEN
            iState := 10;
        END_IF;

    10: (* PITCH TO START *)
        bSystemReady := TRUE;
        tTidalDelay(IN := TRUE, PT := T#10S);

        (* Adjust pitch to capture energy based on flow direction *)
        IF bFlowReversed THEN
            rPitchAngleR1 := -15.0;
            rPitchAngleR2 := 15.0;
        ELSE
            rPitchAngleR1 := 15.0;
            rPitchAngleR2 := -15.0;
        END_IF;

        (* Transition to generating when minimum rotational speeds are reached *)
        IF tTidalDelay.Q AND (rRotor1Speed > 10.0) AND (rRotor2Speed > 10.0) THEN
            tTidalDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* GRID SYNC & TORQUE CONTROL *)
        (* Ensure subsea grid is stable before closing contactor *)
        IF (rGridVoltage > 10.5) AND (rGridVoltage < 11.5) AND (rGridFreq > 49.5) AND (rGridFreq < 50.5) THEN
            tGridSync(IN := TRUE, PT := T#5S);
        ELSE
            tGridSync(IN := FALSE);
        END_IF;

        IF tGridSync.Q THEN
            bGridContactor := TRUE;
        END_IF;

        (* PI Torque Controller for counter-rotating dynamic balancing *)
        rSpeedError := rRotor1Speed - rRotor2Speed;
        rIntegralTorque := rIntegralTorque + (rSpeedError * Ki_Torque * 0.01);

        (* Anti-windup for integral term *)
        IF rIntegralTorque > rMaxTorqueLimit THEN rIntegralTorque := rMaxTorqueLimit; END_IF;
        IF rIntegralTorque < -rMaxTorqueLimit THEN rIntegralTorque := -rMaxTorqueLimit; END_IF;

        rTorqueCmd := (rSpeedError * Kp_Torque) + rIntegralTorque;

        (* Active Power Curtailment during exceptionally high flow conditions *)
        IF rFilteredFlow > (rCutOutSpeed * 0.9) THEN
            rPitchAngleR1 := rPitchAngleR1 + 0.5; (* Gradually feather to curtail power *)
            rPitchAngleR2 := rPitchAngleR2 + 0.5;
        END_IF;

        (* Shut down if flow drops below threshold or enable is removed *)
        IF NOT bEnable OR (rFilteredFlow < (rCutInSpeed * 0.8)) THEN
            tGridSync(IN := FALSE);
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        IF bEmergencyStop AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0; (* Reset only if e-stop cleared and enable toggled off *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
