FUNCTION_BLOCK FB_VARTM_ResinInfusionSync
(* 
   Advanced Composite Wind Turbine Blade Resin Infusion (VARTM)
   100-port flow front synchronization, localized exothermic curing zone modulation, 
   and dynamic viscosity mass-flow tracking.
*)
VAR_INPUT
    bEnableMaster       : BOOL;     (* System master enable for VARTM process *)
    bEStopActive        : BOOL;     (* Emergency stop circuit OK signal (Safety) *)
    rResinTempInlet     : REAL;     (* Inlet resin temperature [deg C] *)
    rMoldVacuumLevel    : REAL;     (* Global mold vacuum level [mbar] *)
    rAmbientHumidity    : REAL;     (* Ambient humidity [%RH] *)
    aFlowFrontSensors   : ARRAY[1..100] OF REAL; (* Flow front position from dielectric sensors [%] *)
    aExothermTempZones  : ARRAY[1..50] OF REAL;  (* Localized temperature zones [deg C] *)
    rResinViscosity     : REAL;     (* Dynamic viscosity from inline rheometer [Pa.s] *)
END_VAR
VAR_OUTPUT
    bSystemReady        : BOOL;     (* Infusion system ready status *)
    bInfusionActive     : BOOL;     (* Infusion process is currently active *)
    aPortValvesCmd      : ARRAY[1..100] OF REAL; (* Proportional valve commands for infusion ports [0.0-100.0%] *)
    aHeatingZonesCmd    : ARRAY[1..50] OF REAL;  (* Localized heating/cooling zone commands [-100.0 to 100.0%] *)
    rMainPumpSpeed      : REAL;     (* Main resin delivery pump speed command [%] *)
    bProcessAlarm       : BOOL;     (* Critical process deviation alarm *)
    iErrorCode          : INT;      (* Specific error code for diagnostics *)
END_VAR
VAR
    iState              : INT := 0; (* State machine step *)
    i                   : INT;      (* Loop index *)
    rAvgFlowFront       : REAL;
    rFlowDeviation      : REAL;
    rMaxExothermRate    : REAL;
    rTempDerivative     : ARRAY[1..50] OF REAL;
    rLastTemp           : ARRAY[1..50] OF REAL;
    tProcessTimer       : TON;
    tSampleTimer        : TON;
    rMassFlowTarget     : REAL;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEStopActive THEN
    bSystemReady := FALSE;
    bInfusionActive := FALSE;
    bProcessAlarm := TRUE;
    rMainPumpSpeed := 0.0;
    iErrorCode := 999; (* E-Stop triggered *)
    FOR i := 1 TO 100 DO
        aPortValvesCmd[i] := 0.0;
    END_FOR;
    FOR i := 1 TO 50 DO
        aHeatingZonesCmd[i] := 0.0;
    END_FOR;
    iState := 0;
    RETURN;
END_IF;

tSampleTimer(IN := NOT tSampleTimer.Q, PT := T#500MS);

CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := FALSE;
        bInfusionActive := FALSE;
        bProcessAlarm := FALSE;
        iErrorCode := 0;

        (* Verify conditions for infusion *)
        IF rMoldVacuumLevel < 20.0 AND rAmbientHumidity < 60.0 AND rResinTempInlet > 20.0 THEN
            bSystemReady := TRUE;
            IF bEnableMaster THEN
                iState := 10;
                tProcessTimer(IN := FALSE);
            END_IF;
        ELSE
            iErrorCode := 101; (* Vacuum or environment out of bounds *)
        END_IF;

    10: (* INFUSION INITIATION *)
        bInfusionActive := TRUE;
        rMainPumpSpeed := 15.0; (* Gentle start *)

        (* Open initial root ports *)
        FOR i := 1 TO 10 DO
            aPortValvesCmd[i] := 100.0;
        END_FOR;

        tProcessTimer(IN := TRUE, PT := T#2M);
        IF tProcessTimer.Q THEN
            tProcessTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* DYNAMIC FLOW FRONT SYNCHRONIZATION & VISCOSITY TRACKING *)
        bInfusionActive := TRUE;

        (* Calculate average flow front *)
        rAvgFlowFront := 0.0;
        FOR i := 1 TO 100 DO
            rAvgFlowFront := rAvgFlowFront + aFlowFrontSensors[i];
        END_FOR;
        rAvgFlowFront := rAvgFlowFront / 100.0;

        (* Mass-flow tracking based on viscosity compensation *)
        rMassFlowTarget := 50.0 + (rResinViscosity * 10.0);
        IF rMassFlowTarget > 100.0 THEN rMassFlowTarget := 100.0; END_IF;
        rMainPumpSpeed := rMassFlowTarget;

        (* Port flow synchronization *)
        FOR i := 1 TO 100 DO
            rFlowDeviation := aFlowFrontSensors[i] - rAvgFlowFront;
            IF rFlowDeviation > 5.0 THEN
                (* Port is ahead, throttle down *)
                aPortValvesCmd[i] := MAX(0.0, aPortValvesCmd[i] - 5.0);
            ELSIF rFlowDeviation < -5.0 THEN
                (* Port is lagging, open up *)
                aPortValvesCmd[i] := MIN(100.0, aPortValvesCmd[i] + 5.0);
            END_IF;
        END_FOR;

        (* Localized Exothermic Curing Modulation *)
        IF tSampleTimer.Q THEN
            FOR i := 1 TO 50 DO
                rTempDerivative[i] := aExothermTempZones[i] - rLastTemp[i];
                rLastTemp[i] := aExothermTempZones[i];

                IF rTempDerivative[i] > 2.0 THEN
                    (* Rapid exotherm detected, apply cooling *)
                    aHeatingZonesCmd[i] := -100.0;
                ELSIF aExothermTempZones[i] < 35.0 THEN
                    (* Assist curing *)
                    aHeatingZonesCmd[i] := 50.0;
                ELSE
                    aHeatingZonesCmd[i] := 0.0;
                END_IF;
            END_FOR;
        END_IF;

        (* Check completion criteria *)
        IF rAvgFlowFront >= 99.0 THEN
            iState := 30;
            tProcessTimer(IN := FALSE);
        END_IF;

        (* Catch abnormal viscosity spike indicating premature gelation *)
        IF rResinViscosity > 1500.0 THEN
            bProcessAlarm := TRUE;
            iErrorCode := 202; (* Premature gelation detected *)
            iState := 99; (* Fault state *)
        END_IF;

    30: (* CURING / DWELL PHASE *)
        bInfusionActive := FALSE;
        rMainPumpSpeed := 0.0;
        FOR i := 1 TO 100 DO
            aPortValvesCmd[i] := 0.0;
        END_FOR;

        (* Maintain temperature for curing *)
        FOR i := 1 TO 50 DO
            IF aExothermTempZones[i] < 70.0 THEN
                aHeatingZonesCmd[i] := 80.0;
            ELSE
                aHeatingZonesCmd[i] := 10.0;
            END_IF;
        END_FOR;

        tProcessTimer(IN := TRUE, PT := T#4H);
        IF tProcessTimer.Q THEN
            iState := 40;
        END_IF;

    40: (* COMPLETE *)
        bSystemReady := TRUE;
        bInfusionActive := FALSE;
        FOR i := 1 TO 50 DO
            aHeatingZonesCmd[i] := 0.0;
        END_FOR;

        IF NOT bEnableMaster THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bInfusionActive := FALSE;
        rMainPumpSpeed := 0.0;
        FOR i := 1 TO 100 DO
            aPortValvesCmd[i] := 0.0;
        END_FOR;
        IF NOT bEnableMaster THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
