```iec-st
FUNCTION_BLOCK FB_BreadDoughDividerRounder_Enterprise
TITLE = 'Commercial Bread Dough Divider and Rounder Control'
VERSION : '1.1'
AUTHOR : 'Lumina AI Cloud Swarm'
FAMILY : 'DoughPrep'

VAR_INPUT
    bSystemEnable : BOOL; (* Master enable for the entire dough handling system *)
    bEmergencyStop : BOOL; (* E-Stop feedback, True means healthy *)
    bStartCycle : BOOL; (* Trigger to start a dividing and rounding cycle *)
    rTargetWeight : REAL; (* Target dough piece weight in grams, e.g., 400.0g for a standard loaf *)
    rActualWeight : REAL; (* Real-time feedback from the downstream dynamic check weigher in grams *)
    rBeltSpeedSetpoint : REAL; (* Desired rounding belt speed in meters per minute *)
    bFlourDusterEnable : BOOL; (* Enable the pneumatic flour duster dosing system *)
    tDusterPulseTime : TIME := T#250MS; (* Duration of the flour dusting pulse *)
    rMainHydraulicPressure : REAL; (* Feedback from main hydraulic line in bar *)
END_VAR

VAR_OUTPUT
    bPistonExtendCmd : BOOL; (* Command to extend volumetric dividing piston *)
    bPistonRetractCmd : BOOL; (* Command to retract volumetric dividing piston *)
    rRoundingBeltSpeedCmd : REAL; (* Speed reference to the rounding belt VFD (0-100%) *)
    bFlourDusterValveCmd : BOOL; (* Command to open the pneumatic flour duster solenoid valve *)
    bSystemReady : BOOL; (* System is primed, pressurized, and ready for cycle *)
    bWeightToleranceAlarm : BOOL; (* High when actual weight deviates from target by > 5% *)
    bPressureFault : BOOL; (* High if hydraulic pressure is insufficient for piston operation *)
    nCurrentState : INT; (* Current active step in the state machine for HMI display *)
END_VAR

VAR
    (* Volumetric Scaling Adaptive Control *)
    rWeightError : REAL;
    rProportionalTerm : REAL;
    rIntegralTerm : REAL;
    rKp_Weight : REAL := 0.65;
    rKi_Weight : REAL := 0.15;
    rMaxIntegralCap : REAL := 100.0;
    rCalculatedPistonStroke : REAL;

    (* Sequence Control and Timers *)
    nStep : INT := 0;
    tPistonExtendTimer : TON;
    tPistonRetractTimer : TON;
    tDusterPulseTimer : TON;
    tCycleTimeoutTimer : TON;

    (* Synchronization and Drive Constraints *)
    rSyncRatioMultiplier : REAL := 1.085; (* Ratio to maintain tension between dividing and rounding belts *)
    rMaxBeltSpeedLimit : REAL := 60.0;

    (* Internal Status Flags *)
    bCycleInProgress : BOOL;
    bFirstScan : BOOL := TRUE;
END_VAR

(* Initialization and Safety Interlocks *)
IF bFirstScan THEN
    bPistonExtendCmd := FALSE;
    bPistonRetractCmd := FALSE;
    rRoundingBeltSpeedCmd := 0.0;
    bFlourDusterValveCmd := FALSE;
    nStep := 0;
    bFirstScan := FALSE;
END_IF;

IF NOT bEmergencyStop OR NOT bSystemEnable THEN
    bPistonExtendCmd := FALSE;
    bPistonRetractCmd := FALSE;
    rRoundingBeltSpeedCmd := 0.0;
    bFlourDusterValveCmd := FALSE;
    bSystemReady := FALSE;
    nStep := 0;
    rIntegralTerm := 0.0;
    bCycleInProgress := FALSE;
    RETURN;
END_IF;

(* Hydraulic Pressure Monitoring *)
IF rMainHydraulicPressure < 120.0 THEN
    bPressureFault := TRUE;
    bSystemReady := FALSE;
ELSE
    bPressureFault := FALSE;
    bSystemReady := TRUE;
END_IF;

(* Volumetric Scaling Feedback Loop (PI Controller) *)
rWeightError := rTargetWeight - rActualWeight;
rProportionalTerm := rWeightError * rKp_Weight;
rIntegralTerm := rIntegralTerm + (rWeightError * rKi_Weight);

(* Anti-Windup for Integral Term *)
IF rIntegralTerm > rMaxIntegralCap THEN
    rIntegralTerm := rMaxIntegralCap;
ELSIF rIntegralTerm < -rMaxIntegralCap THEN
    rIntegralTerm := -rMaxIntegralCap;
END_IF;

rCalculatedPistonStroke := rProportionalTerm + rIntegralTerm;

(* Weight Tolerance Alarm Monitoring *)
IF ABS(rWeightError) > (rTargetWeight * 0.05) THEN
    bWeightToleranceAlarm := TRUE;
ELSE
    bWeightToleranceAlarm := FALSE;
END_IF;

(* Belt Speed Synchronization *)
rRoundingBeltSpeedCmd := rBeltSpeedSetpoint * rSyncRatioMultiplier;
IF rRoundingBeltSpeedCmd > rMaxBeltSpeedLimit THEN
    rRoundingBeltSpeedCmd := rMaxBeltSpeedLimit;
END_IF;

(* Main State Machine for Divider and Rounder Sequences *)
CASE nStep OF
    0: (* IDLE STATE: Waiting for cycle start trigger *)
        bPistonExtendCmd := FALSE;
        bPistonRetractCmd := FALSE;
        bFlourDusterValveCmd := FALSE;
        bCycleInProgress := FALSE;

        IF bStartCycle AND bSystemReady AND NOT bPressureFault THEN
            bCycleInProgress := TRUE;
            nStep := 10;
        END_IF;

    10: (* EXTRUDE/DIVIDE STATE: Extend volumetric piston *)
        bPistonExtendCmd := TRUE;
        bPistonRetractCmd := FALSE;

        tPistonExtendTimer(IN:=TRUE, PT:=T#600MS);
        IF tPistonExtendTimer.Q THEN
            tPistonExtendTimer(IN:=FALSE);
            nStep := 20;
        END_IF;

    20: (* CUT/RETRACT STATE: Retract volumetric piston *)
        bPistonExtendCmd := FALSE;
        bPistonRetractCmd := TRUE;

        tPistonRetractTimer(IN:=TRUE, PT:=T#500MS);
        IF tPistonRetractTimer.Q THEN
            tPistonRetractTimer(IN:=FALSE);
            nStep := 30;
        END_IF;

    30: (* DUSTING STATE: Pneumatic flour duster dosing on the rounded dough *)
        bPistonRetractCmd := FALSE; (* Turn off retract command *)

        IF bFlourDusterEnable THEN
            bFlourDusterValveCmd := TRUE;
            tDusterPulseTimer(IN:=TRUE, PT:=tDusterPulseTime);
            IF tDusterPulseTimer.Q THEN
                bFlourDusterValveCmd := FALSE;
                tDusterPulseTimer(IN:=FALSE);
                nStep := 40; 
            END_IF;
        ELSE
            nStep := 40;
        END_IF;

    40: (* CYCLE COMPLETE: Reset and wait for next start *)
        bCycleInProgress := FALSE;
        IF NOT bStartCycle THEN
            nStep := 0;
        END_IF;

    ELSE
        (* FAULT/UNKNOWN STATE: Safe fallback *)
        nStep := 0;
END_CASE;

nCurrentState := nStep;
END_FUNCTION_BLOCK
