FUNCTION_BLOCK "Bottling_RotaryFiller_CapSorter"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    CIP_Start : Bool;
    Bottle_Present : Bool;
    Cap_Level_Low : Bool;
    Speed_Setpoint : Real;
END_VAR
VAR_OUTPUT
    Filler_Running : Bool;
    CIP_Active : Bool;
    Valve_Open : Bool;
    Pump_Speed : Real;
    Cap_Sorter_Running : Bool;
    Cap_Sorter_Speed : Real;
END_VAR
VAR
    State : Int; // 0: Idle, 1: Filling, 2: CIP
    CIP_Step : Int;
    Timer : TON;
END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF CIP_Start THEN
        State := 2;
    ELSIF Start AND NOT CIP_Start THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Idle
            Filler_Running := FALSE;
            CIP_Active := FALSE;
            Valve_Open := FALSE;
            Pump_Speed := 0.0;
            Cap_Sorter_Running := FALSE;
            Cap_Sorter_Speed := 0.0;
        1: // Filling
            Filler_Running := TRUE;
            CIP_Active := FALSE;
            Pump_Speed := Speed_Setpoint;
            Valve_Open := Bottle_Present;

            // Cap Sorter Logic
            IF NOT Cap_Level_Low THEN
                Cap_Sorter_Running := TRUE;
                Cap_Sorter_Speed := Speed_Setpoint * 1.1; // Sorter runs 10% faster than filler to maintain buffer
            ELSE
                Cap_Sorter_Running := FALSE;
                Cap_Sorter_Speed := 0.0;
            END_IF;
        2: // CIP Sequence
            Filler_Running := FALSE;
            CIP_Active := TRUE;
            Pump_Speed := 50.0;
            Cap_Sorter_Running := FALSE;
            Cap_Sorter_Speed := 0.0;
            CASE CIP_Step OF
                0: // Pre-rinse
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#5m);
                    IF Timer.Q THEN
                        CIP_Step := 1;
                        Timer(IN:=FALSE, PT:=T#5m);
                    END_IF;
                1: // Caustic Wash
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#10m);
                    IF Timer.Q THEN
                        CIP_Step := 2;
                        Timer(IN:=FALSE, PT:=T#10m);
                    END_IF;
                2: // Final Rinse
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#5m);
                    IF Timer.Q THEN
                        CIP_Step := 0;
                        State := 0;
                        Timer(IN:=FALSE, PT:=T#5m);
                    END_IF;
            END_CASE;
    END_CASE;
END_FUNCTION_BLOCK
