FUNCTION_BLOCK FB_GAA_FET_Epitaxy
VAR_INPUT
    (* Core Process Signals *)
    bEnableSys                  : BOOL;     (* Main process enable interlock from MES/SECS-GEM *)
    bEmergencyStop              : BOOL;     (* Fast safety hardware loop (active HIGH = OK) *)
    rChamberPressureUHV         : REAL;     (* UHV chamber pressure feedback in Torr (typical 1e-9) *)
    rWaferTemperature           : REAL;     (* Pyrometer temperature feedback in Celsius (typ 600-750) *)

    (* Precursor Partial Pressures (Silane, Germane, Carrier Gas) *)
    rSilaneFlow_sccm            : REAL;     (* Mass flow controller feedback for SiH4 *)
    rGermaneFlow_sccm           : REAL;     (* Mass flow controller feedback for GeH4 *)
    rHydrogenCarrierFlow_sccm   : REAL;     (* Carrier gas flow feedback H2 *)

    (* Metrology *)
    rReflectometryThickness_nm  : REAL;     (* In-situ multi-wavelength reflectometry for monolayer count *)
END_VAR
VAR_OUTPUT
    (* Actuators & Setpoints *)
    bSystemReady                : BOOL;     (* Epitaxy system ready for batch start *)
    bCriticalAlarm              : BOOL;     (* Process deviation or hardware fault *)
    rHeaterPowerControl_kW      : REAL;     (* Control signal to main RF induction heater (0-50 kW) *)

    (* MFC Commands *)
    rSilaneValveCmd_pct         : REAL;     (* SiH4 pneumatic proportioning valve command (0.0-100.0%) *)
    rGermaneValveCmd_pct        : REAL;     (* GeH4 pneumatic proportioning valve command (0.0-100.0%) *)
    rHydrogenValveCmd_pct       : REAL;     (* H2 main loop command *)

    (* Analytics *)
    iDepositedSuperlatticePairs : INT;      (* Calculated Si/SiGe superlattice pair count *)
END_VAR
VAR
    (* State Machine & Internal Variables *)
    iProcessState               : INT := 0; (* 0=IDLE, 10=PUMP_DOWN, 20=BAKE, 30=EPI_GROWTH, 99=FAULT *)
    iGrowthSubState             : INT := 0; (* 0=INIT, 1=SI_LAYER, 2=SIGE_LAYER, 3=PURGE *)

    (* Timers & Triggers *)
    tPumpDownTimer              : TON;
    tPurgeTimer                 : TON;
    tLayerTimer                 : TON;

    (* PID & Math *)
    rTempError                  : REAL;
    rTempIntegral               : REAL;
    rDerivative                 : REAL;
    rLastTemp                   : REAL;

    (* Constants *)
    rTargetBasePressure         : REAL := 1.0E-9;
    rTargetBakeTemp             : REAL := 750.0;
    rTargetEpiTemp              : REAL := 650.0;
    rKp                         : REAL := 2.5;
    rKi                         : REAL := 0.15;
    rKd                         : REAL := 0.8;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety & Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    iProcessState := 99;
    rHeaterPowerControl_kW := 0.0;
    rSilaneValveCmd_pct := 0.0;
    rGermaneValveCmd_pct := 0.0;
    rHydrogenValveCmd_pct := 0.0;
    RETURN;
END_IF;

(* 2. Temperature PID Control Loop (Simplified for deterministic behavior) *)
rTempError := rTargetEpiTemp - rWaferTemperature;
rTempIntegral := rTempIntegral + (rTempError * 0.1); (* Assuming 100ms cycle time *)

(* Anti-windup clamping *)
IF rTempIntegral > 50.0 THEN
    rTempIntegral := 50.0;
ELSIF rTempIntegral < -50.0 THEN
    rTempIntegral := -50.0;
END_IF;

rDerivative := (rWaferTemperature - rLastTemp) / 0.1;
rLastTemp := rWaferTemperature;

rHeaterPowerControl_kW := (rTempError * rKp) + (rTempIntegral * rKi) - (rDerivative * rKd);

(* Clamp Heater Output *)
IF rHeaterPowerControl_kW > 50.0 THEN
    rHeaterPowerControl_kW := 50.0;
ELSIF rHeaterPowerControl_kW < 0.0 THEN
    rHeaterPowerControl_kW := 0.0;
END_IF;

(* 3. Main State Machine for Epitaxial Growth *)
CASE iProcessState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bCriticalAlarm := FALSE;
        IF bEnableSys THEN
            bSystemReady := FALSE;
            iProcessState := 10;
        END_IF;

    10: (* PUMP_DOWN to UHV *)
        IF rChamberPressureUHV <= rTargetBasePressure THEN
            tPumpDownTimer(IN := TRUE, PT := T#30S);
            IF tPumpDownTimer.Q THEN
                tPumpDownTimer(IN := FALSE);
                iProcessState := 20;
            END_IF;
        ELSE
            tPumpDownTimer(IN := FALSE);
        END_IF;

    20: (* BAKE - Pre-epi clean and oxide desorption *)
        IF rWaferTemperature >= rTargetBakeTemp THEN
            iProcessState := 30;
            iGrowthSubState := 0;
            iDepositedSuperlatticePairs := 0;
        END_IF;

    30: (* EPI_GROWTH - Alternating Superlattice Deposition *)
        CASE iGrowthSubState OF
            0: (* INIT *)
                rHydrogenValveCmd_pct := 100.0; (* Full carrier flow *)
                iGrowthSubState := 1;

            1: (* SI_LAYER (Sacrificial or Channel) *)
                rSilaneValveCmd_pct := 45.0;
                rGermaneValveCmd_pct := 0.0;
                tLayerTimer(IN := TRUE, PT := T#10S); (* Growth time function of partial pressure *)
                IF tLayerTimer.Q THEN
                    tLayerTimer(IN := FALSE);
                    iGrowthSubState := 3; (* PURGE before next layer *)
                END_IF;

            2: (* SIGE_LAYER (Sacrificial or Channel) *)
                rSilaneValveCmd_pct := 40.0;
                rGermaneValveCmd_pct := 25.0;
                tLayerTimer(IN := TRUE, PT := T#12S);
                IF tLayerTimer.Q THEN
                    tLayerTimer(IN := FALSE);
                    iDepositedSuperlatticePairs := iDepositedSuperlatticePairs + 1;

                    IF iDepositedSuperlatticePairs >= 10 THEN (* Target 10 pairs *)
                        iProcessState := 0; (* COMPLETE - Go Idle *)
                    ELSE
                        iGrowthSubState := 3; (* PURGE *)
                    END_IF;
                END_IF;

            3: (* PURGE *)
                rSilaneValveCmd_pct := 0.0;
                rGermaneValveCmd_pct := 0.0;
                tPurgeTimer(IN := TRUE, PT := T#5S);
                IF tPurgeTimer.Q THEN
                    tPurgeTimer(IN := FALSE);
                    (* Toggle logic based on last layer using modulus *)
                    IF (iDepositedSuperlatticePairs * 2) MOD 2 = 0 THEN
                        iGrowthSubState := 2; (* Go to SiGe *)
                    ELSE
                        iGrowthSubState := 1; (* Go to Si *)
                    END_IF;
                END_IF;
        END_CASE;

    99: (* FAULT HANDLING *)
        bCriticalAlarm := TRUE;
        rHeaterPowerControl_kW := 0.0;
        rSilaneValveCmd_pct := 0.0;
        rGermaneValveCmd_pct := 0.0;
        rHydrogenValveCmd_pct := 0.0;
        IF NOT bEnableSys THEN (* Await reset *)
            iProcessState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_SX_MixerSettler_Control
TITLE = 'Hydrometallurgical Solvent Extraction (SX) - Mixer-Settler Control'
// 
// This function block manages the complex hydrodynamics and mass transfer 
// processes within a solvent extraction mixer-settler unit.
// Features:
// 1. Aqueous and Organic feed ratio control for optimal phase dispersion.
// 2. Mixer agitator speed control to maintain specific droplet size.
// 3. Phase inversion detection (monitoring conductivity and viscosity).
// 4. Settler interface level control (aqueous/organic boundary).
// 5. Automatic crud (interfacial solids) detection and removal sequence.
//

VAR_INPUT
    bEnable : BOOL; // Enable unit operation

    // Process Variables (Analog Inputs)
    rFlowAqIn : REAL; // Aqueous feed flow rate (m3/h)
    rFlowOrgIn : REAL; // Organic feed flow rate (m3/h)
    rMixerLevel : REAL; // Mixer total liquid level (mm)
    rMixerConductivity : REAL; // Mixture conductivity (mS/cm) - Used for phase inversion
    rMixerViscosity : REAL; // Mixture viscosity (cP)
    rSettlerInterfaceLevel : REAL; // Settler O/A interface level (mm)
    rSettlerCrudThickness : REAL; // Measured crud layer thickness (mm)

    // Setpoints
    rSpRatioOrgAq : REAL := 1.1; // Setpoint for Organic to Aqueous ratio
    rSpMixerLevel : REAL := 1500.0; // Setpoint for mixer level (mm)
    rSpInterfaceLevel : REAL := 800.0; // Setpoint for settler interface (mm)
    rSpAgitatorSpeed : REAL := 150.0; // Setpoint for agitator speed (RPM)

    // Tuning & Limits
    rMaxConductivityOrgCont : REAL := 5.0; // Max conductivity for organic continuous (mS/cm)
    rMinConductivityAqCont : REAL := 50.0; // Min conductivity for aqueous continuous (mS/cm)
    rCrudThicknessLimit : REAL := 100.0; // Limit to trigger automatic crud removal (mm)
END_VAR

VAR_OUTPUT
    // Control Outputs (Analog)
    rCmdValveAqFeed : REAL; // Aqueous feed control valve (%)
    rCmdValveOrgFeed : REAL; // Organic feed control valve (%)
    rCmdAgitatorSpeed : REAL; // Agitator VFD speed command (RPM)
    rCmdValveAqDischarge : REAL; // Aqueous discharge valve (interface control) (%)
    rCmdValveOrgDischarge : REAL; // Organic discharge valve (overflow control) (%)

    // Discrete Outputs
    bCmdCrudPumpRun : BOOL; // Command to start crud removal pump
    bCmdCrudValveOpen : BOOL; // Command to open crud extraction valve

    // Status & Alarms
    bPhaseInversionDetected : BOOL; // True if phase inversion is detected
    bCrudRemovalActive : BOOL; // True while crud removal sequence is running
    bAlarmHighCrud : BOOL; // Alarm for excessive crud
    bAlarmLevelDeviation : BOOL; // Mixer or Settler level deviation alarm
    iOperationState : INT; // 0=Off, 1=Startup, 2=Running, 3=CrudRemoval, 4=Fault
END_VAR

VAR
    // Internal State and Timers
    TMR_CrudSequence : TON;
    TMR_PhaseInversionDelay : TON;

    // PID Controllers (Simplified for representation)
    rErrInterface : REAL;
    rIntInterface : REAL;

    rErrRatio : REAL;
    rIntRatio : REAL;

    // Phase Continuity Determination
    bIsOrganicContinuous : BOOL;
    bIsAqueousContinuous : BOOL;

    // Internal Flags
    bTriggerCrudRemoval : BOOL;
    stepCrud : INT;
END_VAR

// =========================================================================
// FUNCTION BLOCK IMPLEMENTATION
// =========================================================================

IF NOT bEnable THEN
    // Safe state shutdown
    rCmdValveAqFeed := 0.0;
    rCmdValveOrgFeed := 0.0;
    rCmdAgitatorSpeed := 0.0;
    rCmdValveAqDischarge := 0.0;
    rCmdValveOrgDischarge := 0.0;
    bCmdCrudPumpRun := FALSE;
    bCmdCrudValveOpen := FALSE;
    iOperationState := 0;
    bPhaseInversionDetected := FALSE;
    bCrudRemovalActive := FALSE;
    RETURN;
END_IF;

// 1. Phase Inversion Detection
// Organic continuous operations should have low conductivity. If it spikes, we inverted to aqueous continuous.
IF rMixerConductivity > rMinConductivityAqCont THEN
    bIsAqueousContinuous := TRUE;
    bIsOrganicContinuous := FALSE;
ELSIF rMixerConductivity < rMaxConductivityOrgCont THEN
    bIsOrganicContinuous := TRUE;
    bIsAqueousContinuous := FALSE;
ELSE
    // Transitional or unstable phase
    bIsOrganicContinuous := FALSE;
    bIsAqueousContinuous := FALSE;
END_IF;

// Assume design is Organic Continuous. Phase inversion is a fault condition.
TMR_PhaseInversionDelay(IN := bIsAqueousContinuous, PT := T#10s);
bPhaseInversionDetected := TMR_PhaseInversionDelay.Q;

// 2. Feed Ratio Control (O/A Ratio)
// Adjust organic feed to match the aqueous feed multiplied by the desired ratio
rErrRatio := (rFlowAqIn * rSpRatioOrgAq) - rFlowOrgIn;
rIntRatio := rIntRatio + (rErrRatio * 0.1); // Simple integration
IF rIntRatio > 100.0 THEN rIntRatio := 100.0; END_IF;
IF rIntRatio < 0.0 THEN rIntRatio := 0.0; END_IF;

rCmdValveOrgFeed := rErrRatio * 2.5 + rIntRatio; // PI Control
rCmdValveOrgFeed := LIMIT(0.0, rCmdValveOrgFeed, 100.0);

// Base aqueous feed on mixer level to ensure constant residence time
rCmdValveAqFeed := (rSpMixerLevel - rMixerLevel) * 0.5 + 50.0; 
rCmdValveAqFeed := LIMIT(0.0, rCmdValveAqFeed, 100.0);

// 3. Settler Interface Level Control
// Modulate aqueous discharge valve to maintain the interface level
rErrInterface := rSettlerInterfaceLevel - rSpInterfaceLevel;
rIntInterface := rIntInterface + (rErrInterface * 0.05);
IF rIntInterface > 100.0 THEN rIntInterface := 100.0; END_IF;
IF rIntInterface < -100.0 THEN rIntInterface := -100.0; END_IF;

// Direct acting: higher interface -> open aqueous valve more
rCmdValveAqDischarge := rErrInterface * 1.5 + rIntInterface + 50.0;
rCmdValveAqDischarge := LIMIT(0.0, rCmdValveAqDischarge, 100.0);

// Organic discharge is typically overflow or a back-pressure valve
rCmdValveOrgDischarge := 100.0; // Assume free overflow in this simplified model

// 4. Agitator Speed Control
// Decrease speed if viscosity drops sharply (avoiding excessive shearing) or phase inverts
IF bPhaseInversionDetected THEN
    rCmdAgitatorSpeed := rSpAgitatorSpeed * 0.5; // Reduce shear to recover
ELSE
    rCmdAgitatorSpeed := rSpAgitatorSpeed;
END_IF;

// 5. Automatic Crud Removal Sequence
IF rSettlerCrudThickness > rCrudThicknessLimit THEN
    bTriggerCrudRemoval := TRUE;
    bAlarmHighCrud := TRUE;
ELSE
    bAlarmHighCrud := FALSE;
END_IF;

IF bTriggerCrudRemoval AND NOT bCrudRemovalActive THEN
    bCrudRemovalActive := TRUE;
    stepCrud := 1;
    TMR_CrudSequence(IN := FALSE, PT := T#0s);
END_IF;

IF bCrudRemovalActive THEN
    CASE stepCrud OF
        1: // Open Crud Valve
            bCmdCrudValveOpen := TRUE;
            TMR_CrudSequence(IN := TRUE, PT := T#5s);
            IF TMR_CrudSequence.Q THEN
                TMR_CrudSequence(IN := FALSE, PT := T#0s);
                stepCrud := 2;
            END_IF;
        2: // Start Pump
            bCmdCrudPumpRun := TRUE;
            TMR_CrudSequence(IN := TRUE, PT := T#60s); // Pump for 60 seconds
            IF TMR_CrudSequence.Q THEN
                TMR_CrudSequence(IN := FALSE, PT := T#0s);
                stepCrud := 3;
            END_IF;
        3: // Stop Pump
            bCmdCrudPumpRun := FALSE;
            TMR_CrudSequence(IN := TRUE, PT := T#5s);
            IF TMR_CrudSequence.Q THEN
                TMR_CrudSequence(IN := FALSE, PT := T#0s);
                stepCrud := 4;
            END_IF;
        4: // Close Valve and Reset
            bCmdCrudValveOpen := FALSE;
            bCrudRemovalActive := FALSE;
            bTriggerCrudRemoval := FALSE;
            stepCrud := 0;
    END_CASE;
ELSE
    bCmdCrudPumpRun := FALSE;
    bCmdCrudValveOpen := FALSE;
END_IF;

// Set Operation State
IF bPhaseInversionDetected THEN
    iOperationState := 4; // Fault
ELSIF bCrudRemovalActive THEN
    iOperationState := 3; // Crud Removal
ELSE
    iOperationState := 2; // Running
END_IF;

END_FUNCTION_BLOCK
