Here is the expanded SCL program incorporating a dynamic Load Shedding Matrix with Solar PV and BESS capacity constraints.

FUNCTION_BLOCK "Microgrid_Controller_LoadShed"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT 
      Grid_Lost : Bool;
      PV_KW : Real;
      BESS_KW : Real;
      Total_Load_KW : Real;
      DG_Available : Bool;
      DG_Capacity_KW : Real;
   END_VAR
   VAR_OUTPUT 
      Main_Breaker_Open : Bool;
      DG_Start_Cmd : Bool;
      DG_Breaker_Close : Bool;
      Load_Feeder_Shed : Array[1..4] of Bool; // 1: High Prio -> 4: Low Prio
   END_VAR
   VAR 
      State : Int;
      TMR_Warmup : TON_TIME;
      Avail_Capacity : Real;
   END_VAR
BEGIN
    IF Grid_Lost THEN
        IF #State = 0 THEN #State := 1; END_IF;
    END_IF;
    #Avail_Capacity := #PV_KW + #BESS_KW;
    IF #State = 3 THEN
        #Avail_Capacity := #Avail_Capacity + #DG_Capacity_KW;
    END_IF;

    // Load Shedding Logic
    IF #State > 0 AND #Total_Load_KW > #Avail_Capacity THEN
        #Load_Feeder_Shed[4] := TRUE;
        IF (#Total_Load_KW * 0.8) > #Avail_Capacity THEN #Load_Feeder_Shed[3] := TRUE; END_IF;
        IF (#Total_Load_KW * 0.6) > #Avail_Capacity THEN #Load_Feeder_Shed[2] := TRUE; END_IF;
    ELSE
        #Load_Feeder_Shed[4] := FALSE;
        #Load_Feeder_Shed[3] := FALSE;
        #Load_Feeder_Shed[2] := FALSE;
        #Load_Feeder_Shed[1] := FALSE;
    END_IF;

    CASE #State OF
        0: 
            #Main_Breaker_Open := FALSE;
            #DG_Start_Cmd := FALSE;
            #DG_Breaker_Close := FALSE;
        1:
            #Main_Breaker_Open := TRUE;
            IF #DG_Available THEN
                #DG_Start_Cmd := TRUE;
                #State := 2;
            END_IF;
        2:
            #DG_Start_Cmd := TRUE;
            #TMR_Warmup(IN:=TRUE, PT:=T#10s);
            IF #TMR_Warmup.Q THEN
                #DG_Breaker_Close := TRUE;
                #State := 3;
            END_IF;
        3:
            // Islanded mode logic
    END_CASE;
    IF #State <> 2 THEN #TMR_Warmup(IN:=FALSE, PT:=T#10s); END_IF;
END_FUNCTION_BLOCK
