    bActive := FALSE;
    fActuatorCmd1 := 0.0; fActuatorCmd2 := 0.0; fActuatorCmd3 := 0.0;
    fActuatorCmd4 := 0.0; fActuatorCmd5 := 0.0; fActuatorCmd6 := 0.0;
    eState := 0;
    RETURN;
END_IF;

IF fVacuumPressure > fVacuumLimit THEN
    bError := TRUE;
    nErrorCode := 16#A001; // Vacuum interlock
    bActive := FALSE;
    RETURN;
END_IF;

bActive := TRUE;

// --- State Machine ---
CASE eState OF
