FUNCTION_BLOCK FB_Tokamak_VDE_Mitigation
TITLE = 'Tokamak Plasma Vertical Displacement Event Mitigation Control'
// Highly complex safety and control module for magnetic confinement fusion reactors.
// Monitors plasma Z-position, growth rates of instability, and actuates
// active stabilization coils or triggers disruption mitigation systems (MGI/SPI)
// in case of an unavoidable VDE.

VAR_INPUT
    bSystemEnable : BOOL; // Global enable signal for the VDE mitigation system
    rPlasmaZ_Pos : REAL; // Current vertical position of the plasma magnetic axis [m]
    rPlasmaZ_Vel : REAL; // Vertical velocity of the plasma [m/s]
    rPlasmaCurrent : REAL; // Toroidal plasma current [MA]
    ar_rPoloidalCoilCurrents : ARRAY [1..8] OF REAL; // Currents in the 8 poloidal field coils [kA]
    rHaloCurrent : REAL; // Measured halo current in the vessel structures [MA]
    rVDE_PositionThreshold : REAL := 0.15; // Max allowed vertical displacement [m]
    rVDE_VelocityThreshold : REAL := 0.05; // Max allowed vertical velocity [m/s]
    rHaloCurrentThreshold : REAL := 0.50; // Threshold for halo current fraction triggering fast shutdown [MA]
    tResponseTime : TIME := T#2MS; // Cycle time of the control loop
END_VAR

VAR_OUTPUT
    bMGI_Trigger : BOOL; // Trigger Massive Gas Injection for safe disruption
    bSPI_Trigger : BOOL; // Trigger Shattered Pellet Injection
    bFastCoilDischarge : BOOL; // Trigger fast discharge of superconducting coils
    ar_rActiveControlVoltages : ARRAY [1..8] OF REAL; // Demanded voltages for in-vessel active control coils [kV]
    bVDE_Alarm : BOOL; // General alarm for Vertical Displacement Event
    bPlasmaDisruptionImminent : BOOL; // Flag indicating an unrecoverable disruption is starting
    rCalculatedGrowthRate : REAL; // Estimated VDE growth rate [s^-1]
END_VAR

VAR
    rZ_PosError : REAL;
    rZ_VelError : REAL;
    rProportionalGain : REAL := 150.0;
    rDerivativeGain : REAL := 25.0;
    rControlEffort : REAL;

    // Filters and state variables
    rZ_PosFiltered : REAL;
    rZ_PosPrev : REAL;
    rAlphaFilter : REAL := 0.2; // First-order low pass filter coefficient

    // Timers for triggering systems
    tonMGI_Delay : TON;
    tonSPI_Delay : TON;
    bMGI_Latched : BOOL;
    bSPI_Latched : BOOL;

    iCoilIndex : INT;
END_VAR

//=============================================================================
// Implementation
//=============================================================================

IF NOT bSystemEnable THEN
    bMGI_Trigger := FALSE;
    bSPI_Trigger := FALSE;
    bFastCoilDischarge := FALSE;
    bVDE_Alarm := FALSE;
    bPlasmaDisruptionImminent := FALSE;
    rCalculatedGrowthRate := 0.0;
    FOR iCoilIndex := 1 TO 8 DO
        ar_rActiveControlVoltages[iCoilIndex] := 0.0;
    END_FOR;
    RETURN;
END_IF;

// 1. Signal Processing: Filter the noisy Z-position measurement
rZ_PosFiltered := (rAlphaFilter * rPlasmaZ_Pos) + ((1.0 - rAlphaFilter) * rZ_PosPrev);
rZ_PosPrev := rZ_PosFiltered;

// 2. Calculate errors (target is exactly z = 0.0m midplane)
rZ_PosError := 0.0 - rZ_PosFiltered;
rZ_VelError := 0.0 - rPlasmaZ_Vel;

// 3. Active Feedback Control for In-Vessel Coils (Fast response)
// A simplified PD control law mapped to the upper and lower active coils
rControlEffort := (rProportionalGain * rZ_PosError) + (rDerivativeGain * rZ_VelError);

// Distribute control effort across the 8 coils, assuming alternating up/down symmetry
FOR iCoilIndex := 1 TO 8 DO
    IF iCoilIndex <= 4 THEN
        // Upper coils pull upwards if plasma is going down
        ar_rActiveControlVoltages[iCoilIndex] := rControlEffort * 0.25;
    ELSE
        // Lower coils push upwards
        ar_rActiveControlVoltages[iCoilIndex] := -rControlEffort * 0.25;
    END_FOR;

    // Saturation limit check on coil voltages
    IF ar_rActiveControlVoltages[iCoilIndex] > 5.0 THEN
        ar_rActiveControlVoltages[iCoilIndex] := 5.0;
    ELSIF ar_rActiveControlVoltages[iCoilIndex] < -5.0 THEN
        ar_rActiveControlVoltages[iCoilIndex] := -5.0;
    END_IF;
END_FOR;

// 4. Disruption Prediction and VDE Severity Assessment
rCalculatedGrowthRate := ABS(rPlasmaZ_Vel) / MAX(ABS(rPlasmaZ_Pos), 0.001);

IF ABS(rZ_PosFiltered) > rVDE_PositionThreshold THEN
    bVDE_Alarm := TRUE;
ELSE
    bVDE_Alarm := FALSE;
END_IF;

// Determine if the VDE is unrecoverable
IF (ABS(rZ_PosFiltered) > rVDE_PositionThreshold AND ABS(rPlasmaZ_Vel) > rVDE_VelocityThreshold) OR 
   (rHaloCurrent > rHaloCurrentThreshold) THEN
    bPlasmaDisruptionImminent := TRUE;
ELSE
    bPlasmaDisruptionImminent := FALSE;
END_IF;

// 5. Disruption Mitigation System (DMS) Trigger Logic
// Once unrecoverable, we must latch the mitigation systems to safely quench the plasma

