tonMGI_Delay(IN := bMGI_Latched, PT := T#1MS);
IF tonMGI_Delay.Q THEN
    bMGI_Trigger := TRUE;
END_IF;

// Shattered Pellet Injection trigger (slightly delayed after MGI for thermal mitigation)
tonSPI_Delay(IN := bMGI_Latched, PT := T#5MS);
IF tonSPI_Delay.Q THEN
    bSPI_Trigger := TRUE;
