FUNCTION_BLOCK FB_EUV_Lithography_Source
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main enable for EUV source generation *)
    bEmergencyStop          : BOOL;     (* Safety loop status (TRUE = Safe) *)
    rCO2LaserPowerCmd       : REAL;     (* Commanded CO2 laser power [kW], max 30.0 *)
    rTinDropletFreqCmd      : REAL;     (* Commanded tin droplet generator frequency [kHz], e.g., 50.0 *)
    rVacuumLevel            : REAL;     (* Current vessel vacuum level [mbar] *)
    rPlasmaTempFeedback     : REAL;     (* Measured plasma temperature [eV] *)
    bDebrisMitigationOK     : BOOL;     (* Hydrogen gas buffer and magnetic fields OK *)
    bSyncPulseIn            : BOOL;     (* High-speed synchronization pulse from scanner *)
END_VAR
VAR_OUTPUT
    bEUVSourceReady         : BOOL;     (* EUV source operational and stable *)
    rActualCO2Power         : REAL;     (* Actual applied CO2 laser power [kW] *)
    rActualDropletFreq      : REAL;     (* Actual droplet generation frequency [kHz] *)
    rEUVOutputEnergy        : REAL;     (* Measured EUV energy per pulse [mJ] *)
    bWarningHighDebris      : BOOL;     (* Warning: debris mitigation system near limit *)
    bFaultActive            : BOOL;     (* Critical fault active, system shutdown *)
    iErrorCode              : INT;      (* Diagnostics error code *)
END_VAR
VAR
    iMainState              : INT := 0; (* Main state machine sequence *)
    iPulseSyncState         : INT := 0; (* High-speed synchronization sub-state *)
    tStartupTimer           : TON;      (* Timer for system initialization phases *)
    tPurgeTimer             : TON;      (* Timer for vacuum and gas purge *)
    tPlasmaStabilization    : TON;      (* Timer for plasma stabilization window *)
    rPidIntegral            : REAL := 0.0; (* Integral component for laser power PID *)
    rPidError               : REAL := 0.0;
    rPidErrorPrev           : REAL := 0.0;
    rDropletPhase           : REAL := 0.0; (* Droplet acoustic modulation phase *)
    bInternSyncPulse        : BOOL;     (* Edge detected sync pulse *)
    bInternSyncPulseOld     : BOOL;
END_VAR

(* === MAIN SAFETY AND INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bEUVSourceReady     := FALSE;
    bFaultActive        := TRUE;
    iErrorCode          := 999; (* Emergency stop active *)
    rActualCO2Power     := 0.0;
    rActualDropletFreq  := 0.0;
    rEUVOutputEnergy    := 0.0;
    iMainState          := 0;
    RETURN;
END_IF;

IF rVacuumLevel > 1.0E-2 THEN
    bFaultActive        := TRUE;
    iErrorCode          := 101; (* Vacuum limit exceeded *)
    iMainState          := 0;
END_IF;

(* === SYNCHRONIZATION EDGE DETECTION === *)
bInternSyncPulse := bSyncPulseIn AND NOT bInternSyncPulseOld;
bInternSyncPulseOld := bSyncPulseIn;

(* === MAIN CONTROL STATE MACHINE === *)
CASE iMainState OF
    0: (* SYSTEM IDLE & RESET *)
        bEUVSourceReady := FALSE;
        bFaultActive := FALSE;
        iErrorCode := 0;
        rActualCO2Power := 0.0;
        rActualDropletFreq := 0.0;

        IF bSystemEnable AND bDebrisMitigationOK THEN
            iMainState := 10; (* Transition to Vacuum Prep *)
        END_IF;

    10: (* VACUUM PREPARATION & PURGING *)
        tPurgeTimer(IN := TRUE, PT := T#15S);
        IF tPurgeTimer.Q AND (rVacuumLevel < 1.0E-3) THEN
            tPurgeTimer(IN := FALSE);
            iMainState := 20; (* Transition to Droplet Generator Startup *)
        ELSIF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            bFaultActive := TRUE;
            iErrorCode := 102; (* Purge timeout *)
            iMainState := 0;
        END_IF;

    20: (* DROPLET GENERATOR RAMP-UP *)
        IF rActualDropletFreq < rTinDropletFreqCmd THEN
            rActualDropletFreq := rActualDropletFreq + 0.5; (* Ramp up 0.5 kHz per cycle *)
        ELSE
            iMainState := 30; (* Droplet stable, prep laser *)
        END_IF;

    30: (* CO2 LASER PRE-PULSE ALIGNMENT & PID CONTROL *)
        (* Closed-loop control on plasma temperature approximation *)
        rPidError := rCO2LaserPowerCmd - rActualCO2Power;
        rPidIntegral := rPidIntegral + (rPidError * 0.01);
        rActualCO2Power := (rPidError * 1.5) + (rPidIntegral * 0.2) + ( (rPidError - rPidErrorPrev) * 0.05 );
        rPidErrorPrev := rPidError;

        IF rActualCO2Power < 0.0 THEN
            rActualCO2Power := 0.0;
        ELSIF rActualCO2Power > 30.0 THEN
            rActualCO2Power := 30.0;
        END_IF;

        tPlasmaStabilization(IN := TRUE, PT := T#5S);
        IF tPlasmaStabilization.Q THEN
            tPlasmaStabilization(IN := FALSE);
            iMainState := 40; (* Plasma stable *)
        END_IF;

    40: (* EXTREME UV PRODUCTION MODE *)
        bEUVSourceReady := TRUE;

        (* Droplet targeting synchronization on sync pulse *)
        IF bInternSyncPulse THEN
            (* Simulate energy yield based on synchronization precision *)
            rEUVOutputEnergy := 10.0 + (rPlasmaTempFeedback * 0.1) - (rVacuumLevel * 1000.0);
        END_IF;

        (* Debris mitigation warning trigger *)
        IF NOT bDebrisMitigationOK THEN
            bWarningHighDebris := TRUE;
        ELSE
            bWarningHighDebris := FALSE;
        END_IF;

        IF NOT bSystemEnable THEN
            iMainState := 50; (* Shutdown sequence *)
        END_IF;

    50: (* SHUTDOWN SEQUENCE *)
        bEUVSourceReady := FALSE;
        rActualCO2Power := 0.0;
        rActualDropletFreq := rActualDropletFreq - 1.0; (* Ramp down droplet generator *)
        IF rActualDropletFreq <= 0.0 THEN
            rActualDropletFreq := 0.0;
            iMainState := 0;
        END_IF;

    ELSE
        (* Invalid state trap *)
        iMainState := 0;
        bFaultActive := TRUE;
        iErrorCode := 998;
END_CASE;

END_FUNCTION_BLOCK
