FUNCTION_BLOCK FB_UtilityScaleElectrolyzerRectifier
VAR_INPUT
    (* Core Enable and Safety Signals *)
    bSystemEnable         : BOOL;      (* Main system enable interlock from higher level EMS *)
    bEmergencyStop        : BOOL;      (* Category 4 E-Stop OK relay feedback (NC) *)

    (* AC Grid and Transformer Inputs *)
    rGridVoltageKV        : REAL;      (* AC Grid Voltage feedback in kV *)
    rGridFrequencyHz      : REAL;      (* AC Grid Frequency in Hz *)
    rTransformerTempDegC  : REAL;      (* Rectifier transformer oil temperature in DegC *)

    (* DC Output and Load Feedback *)
    rLoadCurrentKA        : REAL;      (* Measured DC load current to electrolyzer stacks in kA *)
    rLoadVoltageDC        : REAL;      (* Measured DC bus voltage across electrolyzer stacks *)
    rElectrolyteFlowLPM   : REAL;      (* Electrolyte flow rate interlock in L/min *)

    (* Dynamic Optimization Targets *)
    rTargetCurrentKA      : REAL;      (* Target DC current from grid optimization controller *)
    rMaxHarmonicTHD       : REAL;      (* Maximum allowable Total Harmonic Distortion limit (%) *)
END_VAR
VAR_OUTPUT
    (* Status and Safety Outputs *)
    bSystemReady          : BOOL;      (* Rectifier system is energized and ready for load *)
    bFaultActive          : BOOL;      (* Any major critical fault active *)
    iOperatingState       : INT;       (* Current operating state enumeration *)

    (* Control Outputs *)
    rThyristorFiringAngle : REAL;      (* Dynamic 12-pulse thyristor firing phase angle (0-180 deg) *)
    rActiveFilterCompKA   : REAL;      (* DC ripple active harmonic filter compensation signal in kA *)
    bCoolingPumpCmd       : BOOL;      (* Command to liquid cooling pumps for busbar/transformer *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState                : INT := 0;  (* State machine internal tracker *)
    tStartupDelay         : TON;       (* Delay before allowing firing pulses *)
    tCoolingDelay         : TOF;       (* Delay off timer for cooling pumps *)
    tAlarmDelay           : TON;       (* Filter delay for transient alarms *)

    (* Internal Calculations and PID *)
    rCurrentError         : REAL;
    rCurrentIntegral      : REAL;
    rProportionalGain     : REAL := 2.5;
    rIntegralGain         : REAL := 0.85;
    rCalculatedPhase      : REAL;
    rRippleEstimate       : REAL;

    (* Constants *)
    c_MaxFiringAngle      : REAL := 175.0;
    c_MinFiringAngle      : REAL := 15.0;
    c_NominalFreq         : REAL := 50.0;
    c_TempLimitCrit       : REAL := 95.0;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Interlock Processing *)
IF NOT bEmergencyStop OR rTransformerTempDegC >= c_TempLimitCrit OR rElectrolyteFlowLPM < 50.0 THEN
    bSystemReady := FALSE;
    bFaultActive := TRUE;
    iState := 999; (* FAULT STATE *)
    rThyristorFiringAngle := c_MaxFiringAngle; (* Fully block conduction *)
    rActiveFilterCompKA := 0.0;
    RETURN;
END_IF;

(* Clear Transient Faults if Interlocks Normal *)
bFaultActive := FALSE;

(* Dynamic State Machine for Rectifier Control *)
CASE iState OF
    0: (* INIT / STANDBY *)
        bSystemReady := FALSE;
        rThyristorFiringAngle := c_MaxFiringAngle;
        bCoolingPumpCmd := FALSE;

        IF bSystemEnable AND (rGridVoltageKV > 30.0) AND (ABS(rGridFrequencyHz - c_NominalFreq) < 2.0) THEN
            iState := 10;
        END_IF;

    10: (* PRE-CHARGE & COOLING START *)
        bCoolingPumpCmd := TRUE;
        tStartupDelay(IN := TRUE, PT := T#10S);

        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* RAMP-UP / ACTIVE REGULATION *)
        (* PI Control for 12-Pulse Thyristor Firing Angle *)
        rCurrentError := rTargetCurrentKA - rLoadCurrentKA;
        rCurrentIntegral := rCurrentIntegral + (rCurrentError * rIntegralGain);

        (* Anti-windup protection for integral term *)
        IF rCurrentIntegral > 180.0 THEN rCurrentIntegral := 180.0; END_IF;
        IF rCurrentIntegral < -180.0 THEN rCurrentIntegral := -180.0; END_IF;

        (* Calculate firing angle - Inverse relationship (higher angle = lower output) *)
        rCalculatedPhase := 90.0 - (rCurrentError * rProportionalGain) - rCurrentIntegral;

        (* Clamp firing angle within safe limits *)
        IF rCalculatedPhase > c_MaxFiringAngle THEN
            rThyristorFiringAngle := c_MaxFiringAngle;
        ELSIF rCalculatedPhase < c_MinFiringAngle THEN
            rThyristorFiringAngle := c_MinFiringAngle;
        ELSE
            rThyristorFiringAngle := rCalculatedPhase;
        END_IF;

        (* Active Harmonic Filter Calculation based on operating point *)
        rRippleEstimate := rLoadCurrentKA * 0.05 * COS(rThyristorFiringAngle * 3.14159 / 180.0);
        rActiveFilterCompKA := rRippleEstimate;

        (* Check if Disable Requested *)
        IF NOT bSystemEnable THEN
            rCurrentIntegral := 0.0;
            iState := 30;
        END_IF;

    30: (* RAMP-DOWN & COOLING OFF *)
        rThyristorFiringAngle := c_MaxFiringAngle;
        rActiveFilterCompKA := 0.0;
        bSystemReady := FALSE;

        tCoolingDelay(IN := FALSE, PT := T#5M); (* Keep pumps running for 5 mins after shutdown *)
        IF NOT tCoolingDelay.Q THEN
            bCoolingPumpCmd := FALSE;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        rThyristorFiringAngle := c_MaxFiringAngle;
        bSystemReady := FALSE;
        bCoolingPumpCmd := TRUE; (* Force cooling on during fault *)
        rCurrentIntegral := 0.0;
        rActiveFilterCompKA := 0.0;

        IF bSystemEnable = FALSE AND bEmergencyStop THEN
            iState := 0; (* Reset only when enable is cycled and E-Stop is OK *)
        END_IF;

END_CASE;

iOperatingState := iState;
tCoolingDelay(IN := (iState = 20 OR iState = 10));

END_FUNCTION_BLOCK
