FUNCTION_BLOCK FB_PaintSludgeDecanter
TITLE = 'Automated Paint Sludge Decanter Centrifuge Control'
// Highly complex decanter centrifuge controller for paint sludge dewatering
// Incorporates coagulant dosing, bowl speed mapping, differential speed PID, and solids ejection.

VAR_INPUT
    bEnable : BOOL;                     // Enable centrifuge sequence
    bEmergencyStop : BOOL;              // E-stop active low
    rSludgeFeedFlow_LPM : REAL;         // Feed flow rate
    rBowlSpeedFeedback_RPM : REAL;      // Main bowl speed feedback
    rScrollSpeedFeedback_RPM : REAL;    // Scroll (conveyor) speed feedback
    rMainMotorTorque_Pct : REAL;        // Main motor torque %
    rScrollMotorTorque_Pct : REAL;      // Scroll motor torque %
    rVibrationLevel_mms : REAL;         // Vibration in mm/s
    bSolidsChuteBlocked : BOOL;         // Chute blockage sensor
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bFeedPumpRun : BOOL;
    rMainMotorSpeedSet_RPM : REAL;
    rScrollMotorSpeedSet_RPM : REAL;
    rCoagulantDoseRate_LPH : REAL;
    bSolidsEjectionActive : BOOL;
    bAlarmVibration : BOOL;
    bAlarmTorque : BOOL;
    bAlarmChute : BOOL;
    iState : INT;                       // Sequence state
END_VAR

VAR
    rDifferentialSpeed_RPM : REAL;
    rDifferentialSpeedTarget : REAL;
    rTorqueHighLimit : REAL := 85.0;
    rTorqueTripLimit : REAL := 95.0;
    rVibrationTripLimit : REAL := 12.5;

    // PID for Differential Speed Control
    rKp_DiffSpeed : REAL := 0.5;
    rKi_DiffSpeed : REAL := 0.1;
    rDiffSpeedError : REAL;
    rDiffSpeedIntegral : REAL;

    // Timers
    tStartupDelay : TON;
    tEjectionPulse : TON;
    tEjectionInterval : TON;

    // Internal States
    bCentrifugeAtSpeed : BOOL;
    bDosingActive : BOOL;
END_VAR

// Implementation
IF NOT bEmergencyStop THEN
    iState := 999; // E-Stop State
    bFeedPumpRun := FALSE;
    bDosingActive := FALSE;
    rMainMotorSpeedSet_RPM := 0.0;
    rScrollMotorSpeedSet_RPM := 0.0;
    bAlarmVibration := FALSE;
    bAlarmTorque := FALSE;
    RETURN;
END_IF;

// Calculate actual differential speed
rDifferentialSpeed_RPM := rBowlSpeedFeedback_RPM - rScrollSpeedFeedback_RPM;

// Alarms Evaluation
IF rVibrationLevel_mms > rVibrationTripLimit THEN
    bAlarmVibration := TRUE;
END_IF;

IF rMainMotorTorque_Pct > rTorqueTripLimit OR rScrollMotorTorque_Pct > rTorqueTripLimit THEN
    bAlarmTorque := TRUE;
END_IF;

IF bSolidsChuteBlocked THEN
    bAlarmChute := TRUE;
END_IF;

// State Machine
CASE iState OF
    0: // Idle State
        bSystemReady := NOT bAlarmVibration AND NOT bAlarmTorque AND NOT bAlarmChute;
        bFeedPumpRun := FALSE;
        rMainMotorSpeedSet_RPM := 0.0;
        rScrollMotorSpeedSet_RPM := 0.0;
        IF bEnable AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: // Startup - Bowl Acceleration
        rMainMotorSpeedSet_RPM := 3000.0; // Target Bowl Speed
        IF rBowlSpeedFeedback_RPM > 2950.0 THEN
            bCentrifugeAtSpeed := TRUE;
            iState := 20;
        END_IF;

    20: // Establish Differential Speed
        rDifferentialSpeedTarget := 15.0;
        rScrollMotorSpeedSet_RPM := rMainMotorSpeedSet_RPM - rDifferentialSpeedTarget;

        tStartupDelay(IN:=TRUE, PT:=T#10S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN:=FALSE);
            iState := 30;
        END_IF;

    30: // Feed Introduction and Coagulant Dosing
        bFeedPumpRun := TRUE;
        bDosingActive := TRUE;

        // Coagulant cascade - proportional to feed flow
        rCoagulantDoseRate_LPH := rSludgeFeedFlow_LPM * 0.05;

        // Dynamic Differential Speed Control based on Torque
        // Attempt to keep scroll torque constant
        rDiffSpeedError := 60.0 - rScrollMotorTorque_Pct; // Target 60% torque
        rDiffSpeedIntegral := rDiffSpeedIntegral + (rDiffSpeedError * 0.1); // simple I term
        rDifferentialSpeedTarget := 15.0 + (rKp_DiffSpeed * rDiffSpeedError) + (rKi_DiffSpeed * rDiffSpeedIntegral);

        // Clamp diff speed target
        IF rDifferentialSpeedTarget < 5.0 THEN
            rDifferentialSpeedTarget := 5.0;
        ELSIF rDifferentialSpeedTarget > 35.0 THEN
            rDifferentialSpeedTarget := 35.0;
        END_IF;

        rScrollMotorSpeedSet_RPM := rMainMotorSpeedSet_RPM - rDifferentialSpeedTarget;

        // Handle high torque condition
        IF rMainMotorTorque_Pct > rTorqueHighLimit THEN
            bFeedPumpRun := FALSE; // Stop feed to clear
            rDifferentialSpeedTarget := 35.0; // Max differential to clear solids
            iState := 40;
        END_IF;

        IF NOT bEnable THEN
            iState := 50;
        END_IF;

    40: // Clearing High Torque
        rScrollMotorSpeedSet_RPM := rMainMotorSpeedSet_RPM - 35.0;
        IF rMainMotorTorque_Pct < 50.0 THEN
            iState := 30; // Return to normal operation
        END_IF;

    50: // Shutdown Sequence
        bFeedPumpRun := FALSE;
        bDosingActive := FALSE;
        rMainMotorSpeedSet_RPM := 0.0;
        rScrollMotorSpeedSet_RPM := 0.0;

        IF rBowlSpeedFeedback_RPM < 50.0 THEN
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

// Solids Ejection Logic
tEjectionInterval(IN:= NOT tEjectionPulse.Q AND bFeedPumpRun, PT:=T#5M);
tEjectionPulse(IN:= tEjectionInterval.Q, PT:=T#5S);

bSolidsEjectionActive := tEjectionPulse.Q;

END_FUNCTION_BLOCK
