FUNCTION_BLOCK FB_ToxicGasAbatementScrubber
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bSystemEnable       : BOOL;     (* System master enable *)
    bEStopSafetyRelay   : BOOL;     (* E-Stop safety relay OK signal, active high *)
    rExhaustPressure    : REAL;     (* Scrubber exhaust pressure [Pa] *)
    rPHLevelStage1      : REAL;     (* Wet scrubber stage 1 pH level *)
    rPHLevelStage2      : REAL;     (* Wet scrubber stage 2 pH level *)
    bSilaneLELDetector  : BOOL;     (* Silane Lower Explosive Limit detector trip *)
    bPhosLELDetector    : BOOL;     (* Phosphine LEL detector trip *)
    rBurnerTemp         : REAL;     (* Pyrophoric burner temperature [°C] *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady        : BOOL;     (* Abatement system ready for tool processing *)
    bBurnerIgnitionCmd  : BOOL;     (* Pyrophoric burner ignition command *)
    rVFDSpeedSetpoint   : REAL;     (* Scrubber exhaust fan VFD speed setpoint [%] *)
    rDosingPumpStage1   : REAL;     (* pH neutralization dosing pump 1 speed [%] *)
    rDosingPumpStage2   : REAL;     (* pH neutralization dosing pump 2 speed [%] *)
    bCriticalAlarm      : BOOL;     (* Critical life-safety or environmental alarm *)
END_VAR
VAR
    (* Internal state variables *)
    iMainState          : INT := 0; 
    tIgnitionTimer      : TON;
    tPurgeTimer         : TON;

    (* Control loop parameters *)
    rPressSetpoint      : REAL := -200.0; (* Negative pressure setpoint *)
    rPHSetpoint         : REAL := 7.0;    (* Neutral pH *)
    rPressError         : REAL;
    rPHError1           : REAL;
    rPHError2           : REAL;

    (* Safety flags *)
    bGasLeakDetected    : BOOL;
    bBurnerFault        : BOOL;
END_VAR

(* === MAIN LOGIC === *)

(* Safety Interlock Evaluation *)
bGasLeakDetected := bSilaneLELDetector OR bPhosLELDetector;
IF (rBurnerTemp > 1200.0) OR (rBurnerTemp < 200.0 AND iMainState >= 30) THEN
    bBurnerFault := TRUE;
ELSE
    bBurnerFault := FALSE;
END_IF;

IF NOT bEStopSafetyRelay OR bGasLeakDetected OR bBurnerFault THEN
    (* Critical Emergency Shutdown *)
    bSystemReady := FALSE;
    bCriticalAlarm := TRUE;
    bBurnerIgnitionCmd := FALSE;
    rVFDSpeedSetpoint := 100.0; (* Max exhaust for purge during leak *)
    rDosingPumpStage1 := 0.0;
    rDosingPumpStage2 := 0.0;
    iMainState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

bCriticalAlarm := FALSE;

(* Main State Machine *)
CASE iMainState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rVFDSpeedSetpoint := 20.0; (* Idle draft *)
        bBurnerIgnitionCmd := FALSE;
        IF bSystemEnable THEN
            iMainState := 10;
        END_IF;

    10: (* PRE-PURGE *)
        rVFDSpeedSetpoint := 80.0; (* High draft for pre-purge *)
        tPurgeTimer(IN := TRUE, PT := T#30S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iMainState := 20;
        END_IF;

    20: (* BURNER IGNITION *)
        bBurnerIgnitionCmd := TRUE;
        tIgnitionTimer(IN := TRUE, PT := T#15S);
        IF rBurnerTemp > 600.0 THEN
            tIgnitionTimer(IN := FALSE);
            iMainState := 30;
        ELSIF tIgnitionTimer.Q THEN
            (* Ignition failed *)
            bBurnerFault := TRUE;
            tIgnitionTimer(IN := FALSE);
        END_IF;

    30: (* NORMAL OPERATION *)
        bSystemReady := TRUE;

        (* Exhaust Fan Pressure PID Mock-up (P-only for illustration) *)
        rPressError := rPressSetpoint - rExhaustPressure;
        rVFDSpeedSetpoint := 50.0 - (rPressError * 0.5); 
        IF rVFDSpeedSetpoint > 100.0 THEN rVFDSpeedSetpoint := 100.0; END_IF;
        IF rVFDSpeedSetpoint < 20.0 THEN rVFDSpeedSetpoint := 20.0; END_IF;

        (* pH Neutralization Cascading Control Mock-up *)
        rPHError1 := rPHSetpoint - rPHLevelStage1;
        IF rPHError1 > 0.0 THEN rDosingPumpStage1 := rPHError1 * 10.0; ELSE rDosingPumpStage1 := 0.0; END_IF;

        rPHError2 := rPHSetpoint - rPHLevelStage2;
        IF rPHError2 > 0.0 THEN rDosingPumpStage2 := rPHError2 * 5.0; ELSE rDosingPumpStage2 := 0.0; END_IF;

        IF NOT bSystemEnable THEN
            iMainState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        (* Require manual reset via disabling system *)
        IF NOT bSystemEnable AND NOT bGasLeakDetected AND NOT bBurnerFault AND bEStopSafetyRelay THEN
            iMainState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
