VAR
    // PID Controllers
    fbThicknessPID : FB_PID_Controller;
    fbTensionPID : FB_PID_Controller;
    arOvenPID : ARRAY[1..4] OF FB_PID_Controller;

    // State machine
    nState : INT;
    tTimer : TON;
    i : INT;

    // Internal calculations
    rThicknessError : REAL;
    rTensionError : REAL;
