        bFault := FALSE;
        nFaultCode := 0;
        rDriveSpeedRef := 0.0;
        rApplicatorRollSpeed := 0.0;
        rDoctorBladePos := 0.0;
        rStenterWidthCmd := 0.0;
        FOR i := 1 TO 4 DO
            arHeaterPowerCmd[i] := 0.0;
        END_FOR;

        IF bEnable THEN
            nState := 10;
        END_IF;

    10: // Pre-Heating Oven
        bSystemReady := FALSE;
        // Run oven PID controllers
        FOR i := 1 TO 4 DO
            arOvenPID[i](
                Enable := TRUE,
                Setpoint := arOvenTempCmd[i],
                ProcessValue := arOvenTempActual[i],
                Kp := 2.5, Ki := 0.1, Kd := 0.05,
                Output => arHeaterPowerCmd[i]
            );
        END_FOR;

        // Check if temperatures are within tolerance
        IF ABS(arOvenTempActual[1] - arOvenTempCmd[1]) < 2.0 AND
           ABS(arOvenTempActual[2] - arOvenTempCmd[2]) < 2.0 AND
           ABS(arOvenTempActual[3] - arOvenTempCmd[3]) < 2.0 AND
           ABS(arOvenTempActual[4] - arOvenTempCmd[4]) < 2.0 THEN
            nState := 20;
        END_IF;

    20: // Ready
        bSystemReady := TRUE;

        // Main Drive Control (simplified linear ramp would be here)
        rDriveSpeedRef := rLineSpeedCmd;

        // Applicator and Thickness Profiling (Feedforward + Feedback)
        rApplicatorRollSpeed := rLineSpeedCmd * 1.05; // 5% overspeed for application

        fbThicknessPID(
            Enable := TRUE,
            Setpoint := rTargetThickness,
            ProcessValue := rActualThickness,
            Kp := 1.2, Ki := 0.05, Kd := 0.01,
            Output => rThicknessError
        );
        rDoctorBladePos := rTargetThickness - rThicknessError; // Adjust blade gap

        // Transversal Tensioning (Stenter chain)
        fbTensionPID(
            Enable := TRUE,
            Setpoint := rTargetTension,
            ProcessValue := rActualTension,
            Kp := 0.8, Ki := 0.02, Kd := 0.0,
            Output => rTensionError
        );
        rStenterWidthCmd := rStenterWidthCmd + (rTensionError * 0.01); // Incremental width adjustment

        // Keep oven heated
        FOR i := 1 TO 4 DO
            arOvenPID[i](
                Enable := TRUE,
                Setpoint := arOvenTempCmd[i],
                ProcessValue := arOvenTempActual[i],
                Output => arHeaterPowerCmd[i]
            );
        END_FOR;

        IF NOT bEnable THEN
            nState := 0;
        END_IF;

    99: // Fault
        bSystemReady := FALSE;
        bFault := TRUE;
        rDriveSpeedRef := 0.0;
        rApplicatorRollSpeed := 0.0;
        rStenterWidthCmd := 0.0;
        FOR i := 1 TO 4 DO
            arHeaterPowerCmd[i] := 0.0; // Shut down heaters on fault
        END_FOR;
        IF NOT bEStopActive AND NOT bEnable THEN
            nState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
