END_TYPE

FUNCTION_BLOCK FB_Neutrino_LArTPC
VAR_INPUT
    bEnable            : BOOL;
    bStart             : BOOL;
    bStop              : BOOL;
    bAbort             : BOOL;

    (* Environmental and System Inputs *)
    Purity_Sensors     : ARRAY[1..4] OF ST_LAr_Purity;
    HV_Cathode         : ST_HV_System;

    (* PMT Event Buffer - simplified for PLC execution per cycle *)
    New_Hits           : ARRAY[1..128] OF ST_PMT_Hit;
    Num_New_Hits       : DINT; 

    (* Thresholds *)
    Max_Impurity_ppt   : LREAL := 100.0; (* Max O2/H2O before alarms *)
    Min_Electron_LT_ms : LREAL := 5.0;   (* Min electron lifetime *)
    Target_HV_kV       : LREAL := -300.0;
    Max_HV_Ripple_kV   : LREAL := 0.5;
    Coincidence_Window_ns : LINT := 200; (* 200 ns window for cosmic muon tagging *)
    Min_Veto_Hits      : DINT := 10;     (* Minimum PMT hits to flag a cosmic muon *)
END_VAR

VAR_OUTPUT
    CurrentState       : E_PackML_State;
    bReady             : BOOL;
    bAlarm             : BOOL;

    (* LArTPC Health Diagnostics *)
    Avg_O2_ppt         : LREAL;
    Avg_H2O_ppt        : LREAL;
    Veto_Active        : BOOL; (* Set to TRUE if a cosmic muon is currently masking triggers *)
    Supernova_Trigger  : BOOL; (* High multiplicity contained event candidate *)

    Total_Cosmic_Muons : LINT;
    HV_Trip_Count      : DINT;
END_VAR

VAR
    i                  : DINT;
    Veto_Hit_Count     : DINT;
    Coincidence_Start  : LINT;

    O2_Sum             : LREAL;
    H2O_Sum            : LREAL;

    bPurity_OK         : BOOL;
    bHV_OK             : BOOL;
END_VAR

(* 
    Implementation logic for LArTPC Control 
*)
CASE CurrentState OF
    E_PackML_State.IDLE:
        bReady := TRUE;
        IF bStart THEN
            CurrentState := E_PackML_State.STARTING;
            bReady := FALSE;
        END_IF

    E_PackML_State.STARTING:
        (* Initialize counters and clear flags *)
        Total_Cosmic_Muons := 0;
        HV_Trip_Count := 0;
        Veto_Active := FALSE;
        Supernova_Trigger := FALSE;
        CurrentState := E_PackML_State.EXECUTE;

    E_PackML_State.EXECUTE:
        IF bStop THEN
            CurrentState := E_PackML_State.STOPPING;
        ELSIF bAbort THEN
            CurrentState := E_PackML_State.ABORTING;
        END_IF

        (* 1. Cryogenic Liquid Argon Purity Monitoring *)
        O2_Sum := 0.0;
        H2O_Sum := 0.0;
        FOR i := 1 TO 4 DO
            O2_Sum := O2_Sum + Purity_Sensors[i].O2_Level_ppt;
            H2O_Sum := H2O_Sum + Purity_Sensors[i].H2O_Level_ppt;
        END_FOR

        Avg_O2_ppt := O2_Sum / 4.0;
        Avg_H2O_ppt := H2O_Sum / 4.0;

        bPurity_OK := (Avg_O2_ppt < Max_Impurity_ppt) AND (Avg_H2O_ppt < Max_Impurity_ppt);

        (* 2. High Voltage Field Regulation & Monitoring *)
        bHV_OK := (ABS(HV_Cathode.Voltage_kV - Target_HV_kV) < Max_HV_Ripple_kV) AND NOT HV_Cathode.Discharge_Detected;
        IF HV_Cathode.Discharge_Detected THEN
            HV_Trip_Count := HV_Trip_Count + 1;
            bAlarm := TRUE;
        END_IF

        IF NOT bPurity_OK OR NOT bHV_OK THEN
            bAlarm := TRUE;
        ELSE
            bAlarm := FALSE;
        END_IF

        (* 3. Cosmic Ray Muon Veto Coincidence Logic *)
        Veto_Hit_Count := 0;
        Veto_Active := FALSE;
        Supernova_Trigger := FALSE;

        IF Num_New_Hits > 0 AND Num_New_Hits <= 128 THEN
            Coincidence_Start := New_Hits[1].Timestamp_ns;

            FOR i := 1 TO Num_New_Hits DO
                IF New_Hits[i].Is_Veto_Region THEN
                    IF (New_Hits[i].Timestamp_ns - Coincidence_Start) <= Coincidence_Window_ns THEN
                        Veto_Hit_Count := Veto_Hit_Count + 1;
                    ELSE
                        Coincidence_Start := New_Hits[i].Timestamp_ns;
                        Veto_Hit_Count := 1;
                    END_IF

                    IF Veto_Hit_Count >= Min_Veto_Hits THEN
                        Veto_Active := TRUE;
                        Total_Cosmic_Muons := Total_Cosmic_Muons + 1;
                        Veto_Hit_Count := 0;
                    END_IF
                END_IF
            END_FOR

            (* Check for inner PMT bursts without veto activity -> Candidate Supernova Burst *)
            IF NOT Veto_Active AND (Num_New_Hits > 50) THEN
                Supernova_Trigger := TRUE;
            END_IF
        END_IF

    E_PackML_State.STOPPING:
        CurrentState := E_PackML_State.STOPPED;

    E_PackML_State.STOPPED:
        IF bAbort THEN
            CurrentState := E_PackML_State.ABORTING;
        ELSIF NOT bStop THEN
            CurrentState := E_PackML_State.IDLE;
        END_IF

    E_PackML_State.ABORTING:
        CurrentState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF NOT bAbort THEN
            CurrentState := E_PackML_State.IDLE;
        END_IF

    ELSE
        CurrentState := E_PackML_State.IDLE;
END_CASE
END_FUNCTION_BLOCK
