FUNCTION_BLOCK FB_AutonomousDerrickControl
TITLE = 'Autonomous Oil Rig Derrick Control'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Data Architect'

VAR_INPUT
    bEnableSystem         : BOOL;
    bEmergencyStop        : BOOL;
    rVesselHeavePos       : REAL;
    rVesselHeaveVel       : REAL;
    rVesselHeaveAcc       : REAL;
    rTargetWOB            : REAL;
    rCurrentWOB           : REAL;
    bPipeReadyDeck        : BOOL;
    bTopDriveConnected    : BOOL;
    bSlipsSet             : BOOL;
    bMakeupComplete       : BOOL;
    rMeasuredTorque       : REAL;
    rMeasuredRPM          : REAL;
    rDownholeToolFace     : REAL;
    rTargetToolFace       : REAL;
END_VAR

VAR_OUTPUT
    bSystemReady          : BOOL;
    bFaultActive          : BOOL;
    iErrorCode            : INT;
    rWinchCommandVelocity : REAL;
    rWinchCommandTorque   : REAL;
    bExtendRoughneck      : BOOL;
    bSpinPipe             : BOOL;
    bTorquePipe           : BOOL;
    bRetractRoughneck     : BOOL;
    bReleaseSlips         : BOOL;
    rTopDriveTorqueLimit  : REAL;
    rTopDriveRPMCmd       : REAL;
END_VAR

VAR
    eRoughneckState       : INT := 0;
    rFilteredWOB          : REAL;
    rWOBError             : REAL;
    rWOBPID_Integral      : REAL := 0.0;
    rWOBPID_Derivative    : REAL := 0.0;
    rWOBPID_PrevError     : REAL := 0.0;
    rTorqueError          : REAL;
    rToolfacePID_Int      : REAL := 0.0;
    rToolfacePID_PrevErr  : REAL := 0.0;
    Kp_WOB                : REAL := 1.5;
    Ki_WOB                : REAL := 0.2;
    Kd_WOB                : REAL := 0.05;
    Kp_Toolface           : REAL := 2.5;
    Ki_Toolface           : REAL := 0.1;
    tMakeupTimer          : TON;
    tRoughneckExtend      : TON;
    bStickSlipDetected    : BOOL := FALSE;
    rMaxTorqueThreshold   : REAL := 45.0;
    rMinTorqueThreshold   : REAL := 15.0;
END_VAR

IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bFaultActive := TRUE;
    iErrorCode := 999;
    rWinchCommandVelocity := 0.0;
    rWinchCommandTorque := 0.0;
    bExtendRoughneck := FALSE;
    bSpinPipe := FALSE;
    bTorquePipe := FALSE;
    bRetractRoughneck := TRUE;
    rTopDriveTorqueLimit := 0.0;
    rTopDriveRPMCmd := 0.0;
    eRoughneckState := 0;
    RETURN;
END_IF;

IF NOT bEnableSystem THEN
    bSystemReady := FALSE;
    RETURN;
END_IF;

bSystemReady := TRUE;

rFilteredWOB := rFilteredWOB + 0.1 * (rCurrentWOB - rFilteredWOB);
rWOBError := rTargetWOB - rFilteredWOB;
rWOBPID_Integral := rWOBPID_Integral + (rWOBError * 0.01);
rWOBPID_Derivative := (rWOBError - rWOBPID_PrevError) / 0.01;
rWOBPID_PrevError := rWOBError;
IF rWOBPID_Integral > 10.0 THEN rWOBPID_Integral := 10.0; END_IF;
IF rWOBPID_Integral < -10.0 THEN rWOBPID_Integral := -10.0; END_IF;
rWinchCommandVelocity := -rVesselHeaveVel + (Kp_WOB * rWOBError) + (Ki_WOB * rWOBPID_Integral) + (Kd_WOB * rWOBPID_Derivative);
rWinchCommandTorque := 50.0 + (Kp_WOB * rWOBError * 0.5);
IF rWinchCommandTorque > 150.0 THEN rWinchCommandTorque := 150.0; END_IF;

IF rMeasuredTorque > rMaxTorqueThreshold AND rMeasuredRPM < 10.0 THEN
    bStickSlipDetected := TRUE;
ELSIF rMeasuredTorque < rMinTorqueThreshold AND rMeasuredRPM > 120.0 THEN
    bStickSlipDetected := FALSE;
END_IF;
rTorqueError := rTargetToolFace - rDownholeToolFace;
IF rTorqueError > 180.0 THEN rTorqueError := rTorqueError - 360.0; END_IF;
IF rTorqueError < -180.0 THEN rTorqueError := rTorqueError + 360.0; END_IF;

IF bStickSlipDetected THEN
    rTopDriveRPMCmd := 100.0;
    rTopDriveTorqueLimit := rMaxTorqueThreshold * 1.2;
    iErrorCode := 101;
ELSE
    rToolfacePID_Int := rToolfacePID_Int + (rTorqueError * 0.01);
    IF rToolfacePID_Int > 50.0 THEN rToolfacePID_Int := 50.0; END_IF;
    IF rToolfacePID_Int < -50.0 THEN rToolfacePID_Int := -50.0; END_IF;
    rTopDriveRPMCmd := 60.0 + (Kp_Toolface * rTorqueError) + (Ki_Toolface * rToolfacePID_Int);
    rTopDriveTorqueLimit := 40.0;
END_IF;
IF rTopDriveRPMCmd > 180.0 THEN rTopDriveRPMCmd := 180.0; END_IF;
IF rTopDriveRPMCmd < 0.0 THEN rTopDriveRPMCmd := 0.0; END_IF;

CASE eRoughneckState OF
    0:
        bExtendRoughneck := FALSE;
        bSpinPipe := FALSE;
        bTorquePipe := FALSE;
        bRetractRoughneck := TRUE;
        bReleaseSlips := FALSE;
        IF bPipeReadyDeck AND bTopDriveConnected AND bSlipsSet THEN eRoughneckState := 10; END_IF;
    10:
        bRetractRoughneck := FALSE;
        bExtendRoughneck := TRUE;
        tRoughneckExtend(IN := TRUE, PT := T#5S);
        IF tRoughneckExtend.Q THEN
            eRoughneckState := 20;
            tRoughneckExtend(IN := FALSE);
        END_IF;
    20:
        bSpinPipe := TRUE;
        tMakeupTimer(IN := TRUE, PT := T#10S);
        IF tMakeupTimer.Q THEN
            bSpinPipe := FALSE;
            bTorquePipe := TRUE;
            eRoughneckState := 30;
            tMakeupTimer(IN := FALSE);
        END_IF;
    30:
        IF bMakeupComplete THEN
            bTorquePipe := FALSE;
            eRoughneckState := 40;
        END_IF;
    40:
        bRetractRoughneck := TRUE;
        bExtendRoughneck := FALSE;
        bReleaseSlips := TRUE;
        IF NOT bSlipsSet THEN eRoughneckState := 0; END_IF;
    ELSE eRoughneckState := 0;
END_CASE;
END_FUNCTION_BLOCK
