        sStatusMsg := 'ABORT: Emergency Stop Triggered - Safing Vehicle';
        bLoxValveOpen := FALSE;
        bMethaneValveOpen := FALSE;
        bLoxPurgeValve := TRUE;
        bMethanePurgeValve := TRUE;
