        bRetractStrongback := FALSE;
        bReleaseUmbilical := FALSE;
        bIgnitionSequenceStart := FALSE;
        bGoForLaunch := FALSE;
        bFault := TRUE;

    ELSE
        State := 0;
END_CASE;

iCurrentState := State;
``END_FUNCTION_BLOCK
