FUNCTION_BLOCK "DP2_Adversarial_HIL"
VERSION : 3.0
VAR_INPUT
    enable_dp : BOOL;
    gps_array : ARRAY[1..3] OF REAL;
    hil_digital_twin_pos : REAL; // Feedback from HIL simulation
    hil_sync_valid : BOOL;
END_VAR

VAR_OUTPUT
    thruster_cmd : ARRAY[1..3] OF REAL;
    system_state : INT; // 0: Off, 1: Self-Test, 2: Active, 3: Degraded, 4: Fault
    drift_alarm : BOOL;
END_VAR

VAR
    est_pos : REAL;
    P_pos : REAL := 1.0;
    voted_pos : REAL;

    // Self-Test vars
    test_step : INT := 0;
    test_timer : TIME := T#0s;

    // Drift detection vars
    drift_integrator : REAL := 0.0;
END_VAR

BEGIN
    // State Machine
    IF NOT enable_dp THEN
        system_state := 0;
        test_step := 0;
    ELSIF enable_dp AND system_state = 0 THEN
        system_state := 1; // Enter Self-Test
    END_IF;

    // 1. Autonomous Self-Test Routine
    IF system_state = 1 THEN
        // Test thruster responses incrementally without moving vessel significantly
        IF test_step = 0 THEN
            thruster_cmd[1] := 5.0;
            test_step := 1;
        ELSIF test_step = 1 THEN
            thruster_cmd[1] := 0.0;
            test_step := 2;
            system_state := 2; // Test passed, go Active
        END_IF;
        RETURN; // Skip control logic during test
    END_IF;

    // 2. TMR Voting
    voted_pos := (gps_array[1] + gps_array[2] + gps_array[3]) / 3.0;

    // 3. Adversarial Sensor Drift Detection (Spoofing Check)
    // Compare TMR voted position against the Physics-Based Digital Twin (HIL)
    VAR
        twin_deviation : REAL;
    END_VAR
    IF hil_sync_valid THEN
        twin_deviation := voted_pos - hil_digital_twin_pos;
        drift_integrator := drift_integrator + (twin_deviation * 0.1);

        IF ABS(drift_integrator) > 50.0 THEN
            drift_alarm := TRUE;
            system_state := 3; // Degraded state due to possible GPS spoofing
        END_IF;
    ELSE
        system_state := 3; // Degraded if HIL sync lost
    END_IF;

    // 4. Kalman Filter
    est_pos := est_pos + 0.0;
    P_pos := P_pos + 0.01;
    VAR
        K_pos : REAL;
        sensor_feed : REAL;
    END_VAR

    // Graceful degradation: Rely on Digital Twin if GPS is spoofed
    IF drift_alarm AND hil_sync_valid THEN
        sensor_feed := hil_digital_twin_pos;
    ELSE
        sensor_feed := voted_pos;
    END_IF;

    K_pos := P_pos / (P_pos + 0.5);
    est_pos := est_pos + K_pos * (sensor_feed - est_pos);
    P_pos := (1.0 - K_pos) * P_pos;

    // 5. Thruster Allocation
    IF system_state = 2 OR system_state = 3 THEN
        VAR
            err_pos : REAL;
        END_VAR
        err_pos := 0.0 - est_pos; // Assuming setpoint is 0.0 for station keeping

        // If degraded, limit max thrust to prevent erratic runaway
        VAR
            thrust_limit : REAL := 100.0;
        END_VAR
        IF system_state = 3 THEN thrust_limit := 30.0; END_IF;

        thruster_cmd[1] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
        thruster_cmd[2] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
        thruster_cmd[3] := LIMIT(MN := -thrust_limit, IN := err_pos * 10.0, MX := thrust_limit);
    ELSE
        thruster_cmd[1] := 0.0;
        thruster_cmd[2] := 0.0;
        thruster_cmd[3] := 0.0;
    END_IF;
END_FUNCTION_BLOCK
This logic protects the vessel against subtle GPS spoofing by constantly verifying the physical reality of the sensors against a trusted Digital Twin dynamic model. If an anomaly is detected, it triggers a drift alarm and smoothly degrades into a thrust-limited state, falling back on the HIL model for navigation if necessary.
