FUNCTION_BLOCK "RobotCell_TCP_Collision"
{
  S7_Optimized_Access := 'TRUE'
}
VERSION : 0.1
   VAR_INPUT
      Robot_TCP_Pos_X : Real;
      Robot_TCP_Pos_Y : Real;
      Robot_TCP_Pos_Z : Real;
      TCP_Velocity : Real;
      Max_TCP_Velocity : Real;
      Collision_Zone_X : Real;
      Collision_Zone_Y : Real;
      Collision_Zone_Z : Real;
      Collision_Threshold : Real;
   END_VAR

   VAR_OUTPUT
      Speed_Override : Real;
      Collision_Alarm : Bool;
      Stop_Robot : Bool;
   END_VAR

   VAR
      Distance_To_Collision : Real;
   END_VAR

BEGIN
    // Calculate Distance to closest collision zone
    #Distance_To_Collision := SQRT(SQR(#Robot_TCP_Pos_X - #Collision_Zone_X) + 
                                   SQR(#Robot_TCP_Pos_Y - #Collision_Zone_Y) + 
                                   SQR(#Robot_TCP_Pos_Z - #Collision_Zone_Z));

    // Collision Avoidance Logic
    IF #Distance_To_Collision < #Collision_Threshold THEN
        #Collision_Alarm := TRUE;
        #Stop_Robot := TRUE;
        #Speed_Override := 0.0;
    ELSIF #Distance_To_Collision < (#Collision_Threshold * 2.0) THEN
        #Collision_Alarm := TRUE;
        #Stop_Robot := FALSE;
