FUNCTION_BLOCK FB_CleanroomMAU_AdvancedControl
VAR_INPUT
    bEnable                 : BOOL; // Enable MAU operation
    rOutsideAirTemp         : REAL; // Outside Air Temperature (Celsius)
    rOutsideAirRH           : REAL; // Outside Air Relative Humidity (%)
    rMixedAirTemp           : REAL; // Mixed Air Temperature (Celsius)
    rDischargeAirTemp       : REAL; // Discharge Air Temperature (Celsius)
    rDischargeAirDewPoint   : REAL; // Discharge Air Dew Point (Celsius)
    rCleanroomPressure      : REAL; // Cleanroom Static Pressure (Pa)
    rULPAFilterDiffPress    : REAL; // ULPA Filter Differential Pressure (Pa)

    // Setpoints
    rDischargeTempSetpt     : REAL := 18.0; 
    rDischargeDewPtSetpt    : REAL := 10.0;
    rCleanroomPressSetpt    : REAL := 25.0; // Positive pressure setpoint
    rULPAFilterAlarmLimit   : REAL := 250.0; // Max DP across ULPA filter

    // Feedback
    rChilledWaterValveFbk   : REAL; // 0-100%
    rHotWaterValveFbk       : REAL; // 0-100%
    rHumidifierFbk          : REAL; // 0-100%
    rVFD_SpeedFbk           : REAL; // 0-100%
END_VAR

VAR_OUTPUT
    rChilledWaterValveCmd   : REAL; // Command to ChW Valve 0-100%
    rHotWaterValveCmd       : REAL; // Command to HW Valve 0-100%
    rHumidifierCmd          : REAL; // Command to Adiabatic Humidifier 0-100%
    rVFD_SpeedCmd           : REAL; // Command to Supply Fan VFD 0-100%

    bULPAFilterAlarm        : BOOL; // ULPA Filter Change Required
    bDewPointAlarm          : BOOL; // Dew point out of range
    bSystemFault            : BOOL; // General system fault
END_VAR

VAR
    // PID Controllers (Assume FB_PID is a standard library function block)
    PID_TempCtrl            : FB_PID;
    PID_DewPointCtrl        : FB_PID;
    PID_PressureCtrl        : FB_PID;

    // Internal calculations
    rEnthalpyOutside        : REAL;
    rEnthalpySetpoint       : REAL;

    // Timers
    TON_FilterAlarm         : TON;
    TON_DewPointAlarm       : TON;

    // State Machine
    eState                  : INT := 0; // 0=Off, 1=Startup, 2=Normal, 3=Fault
END_VAR

// Constants for State Machine
VAR CONSTANT
    STATE_OFF       : INT := 0;
    STATE_STARTUP   : INT := 1;
    STATE_NORMAL    : INT := 2;
    STATE_FAULT     : INT := 3;
END_VAR

// --- Implementation ---
IF NOT bEnable THEN
    eState := STATE_OFF;
END_IF;

CASE eState OF
    STATE_OFF:
        rChilledWaterValveCmd := 0.0;
        rHotWaterValveCmd := 0.0;
        rHumidifierCmd := 0.0;
        rVFD_SpeedCmd := 0.0;
        bSystemFault := FALSE;

        IF bEnable THEN
            eState := STATE_STARTUP;
        END_IF;

    STATE_STARTUP:
        // Start fan at minimum speed to establish airflow
        rVFD_SpeedCmd := 20.0; 

        // Wait for airflow stabilization (pseudo logic here)
        IF rVFD_SpeedFbk > 15.0 THEN
            eState := STATE_NORMAL;
        END_IF;

    STATE_NORMAL:
        // 1. Cleanroom Pressure Control (Supply Fan VFD)
        PID_PressureCtrl(
            rSetpoint := rCleanroomPressSetpt,
            rProcessVariable := rCleanroomPressure,
            rKp := 2.5, rTi := 15.0, rTd := 0.0,
            rOutput => rVFD_SpeedCmd
        );

        // Limit VFD speed
        IF rVFD_SpeedCmd > 100.0 THEN rVFD_SpeedCmd := 100.0; END_IF;
        IF rVFD_SpeedCmd < 20.0 THEN rVFD_SpeedCmd := 20.0; END_IF;

        // 2. Dew Point Tracking (Chilled Water Valve for Dehumidification)
        // If outside air humidity is high, we cool to strip moisture.
        PID_DewPointCtrl(
            rSetpoint := rDischargeDewPtSetpt,
            rProcessVariable := rDischargeAirDewPoint,
            rKp := 1.8, rTi := 20.0, rTd := 0.0,
            rOutput => rChilledWaterValveCmd
        );

        // 3. Temperature Control (Hot Water Valve for Reheat)
        // Since chilled water might have overcooled the air to reach dew point, we reheat.
        PID_TempCtrl(
            rSetpoint := rDischargeTempSetpt,
            rProcessVariable := rDischargeAirTemp,
            rKp := 3.0, rTi := 10.0, rTd := 0.0,
            rOutput => rHotWaterValveCmd
        );

        // 4. Adiabatic Humidification Cascade
        // If dew point is too low, we add moisture (adiabatic cooling effect)
        IF rDischargeAirDewPoint < (rDischargeDewPtSetpt - 1.0) THEN
            rHumidifierCmd := (rDischargeDewPtSetpt - rDischargeAirDewPoint) * 10.0; // Proportional only for simplicity
        ELSE
            rHumidifierCmd := 0.0;
        END_IF;

        // Ensure commands are within 0-100%
        IF rChilledWaterValveCmd > 100.0 THEN rChilledWaterValveCmd := 100.0; ELSIF rChilledWaterValveCmd < 0.0 THEN rChilledWaterValveCmd := 0.0; END_IF;
        IF rHotWaterValveCmd > 100.0 THEN rHotWaterValveCmd := 100.0; ELSIF rHotWaterValveCmd < 0.0 THEN rHotWaterValveCmd := 0.0; END_IF;
        IF rHumidifierCmd > 100.0 THEN rHumidifierCmd := 100.0; ELSIF rHumidifierCmd < 0.0 THEN rHumidifierCmd := 0.0; END_IF;

        // 5. ULPA Filter Monitoring
        TON_FilterAlarm(IN := (rULPAFilterDiffPress > rULPAFilterAlarmLimit), PT := T#30S);
        bULPAFilterAlarm := TON_FilterAlarm.Q;

        // 6. Dew Point Monitoring
        TON_DewPointAlarm(IN := (ABS(rDischargeAirDewPoint - rDischargeDewPtSetpt) > 2.0), PT := T#5M);
        bDewPointAlarm := TON_DewPointAlarm.Q;

        IF bULPAFilterAlarm THEN
            // Consider transitioning to fault if critical
            // eState := STATE_FAULT;
        END_IF;

    STATE_FAULT:
        rChilledWaterValveCmd := 0.0;
        rHotWaterValveCmd := 0.0;
        rHumidifierCmd := 0.0;
        rVFD_SpeedCmd := 0.0;
        bSystemFault := TRUE;

        // Requires manual reset to clear fault state
        IF NOT bEnable THEN
            eState := STATE_OFF;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
