FUNCTION_BLOCK FB_SMES_ToroidalCoilControl
VAR_INPUT
    (* Core Enable & Safety Inputs *)
    bSystemEnable           : BOOL;     (* Main enable signal from PCS *)
    bEmergencyStop          : BOOL;     (* Hardwired ESTOP, FALSE = Stop *)

    (* Cryogenic Sub-Cooling Variables *)
    rHeliumTemp             : REAL;     (* He bath temperature [K] *)
    rHeliumPressure         : REAL;     (* He pressure [MPa] *)
    rCryocoolerFlow         : REAL;     (* Flow rate [g/s] *)

    (* Electrical & Quench Detection *)
    rCoilCurrent            : REAL;     (* Main DC current [kA] *)
    rCoilVoltage            : REAL;     (* Tap voltage across coil [V] *)
    rSecVoltageTap1         : REAL;     (* Secondary quench tap 1 [mV] *)
    rSecVoltageTap2         : REAL;     (* Secondary quench tap 2 [mV] *)

    (* Grid & PCS *)
    rGridFreq               : REAL;     (* Grid frequency [Hz] *)
    rPowerDemand            : REAL;     (* Real power injection demand [MW] *)
END_VAR

VAR_OUTPUT
    (* Status & Safety *)
    bSystemReady            : BOOL;     (* True when ready for power injection *)
    bQuenchDetected         : BOOL;     (* True if coil quench is detected *)
    bAlarm                  : BOOL;     (* General fault alarm *)

    (* Actuators *)
    rPowerOutputSetpt       : REAL;     (* Power reference to PCS [MW] *)
    rCurrentChargeSetpt     : REAL;     (* Charging current reference [kA] *)
    rCryocoolerValve        : REAL;     (* Valve position for sub-cooling [0-100%] *)
END_VAR

VAR
    (* Internal States & Filters *)
    iState                  : INT := 0;

    (* Quench Detection Filters *)
    rVoltageDiff            : REAL;
    rFilteredQuenchVolts    : REAL;
    rAlphaQuench            : REAL := 0.05; (* EMA Filter Constant *)

    (* Timers *)
    tStartupDelay           : TON;
    tQuenchBlanking         : TON;

    (* PID variables for Cryocooler *)
    rTempError              : REAL;
    rTempIntegral           : REAL;
    rKp_Cryo                : REAL := 2.5;
    rKi_Cryo                : REAL := 0.1;
    rTempTarget             : REAL := 4.2; (* 4.2K target *)

    (* Constants *)
    rMaxOperatingCurrent    : REAL := 50.0; (* 50 kA limit *)
    rQuenchThreshold        : REAL := 15.0; (* 15 mV threshold for quench *)
END_VAR

(* === MULTI-LAYERED SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    bQuenchDetected := FALSE;
    rPowerOutputSetpt := 0.0;
    rCurrentChargeSetpt := 0.0;
    rCryocoolerValve := 100.0; (* Full cooling on ESTOP *)
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* === QUENCH DETECTION (PRIMARY & SECONDARY) === *)
rVoltageDiff := ABS(rSecVoltageTap1 - rSecVoltageTap2);
(* Noise filtering via Exponential Moving Average *)
rFilteredQuenchVolts := (rAlphaQuench * rVoltageDiff) + ((1.0 - rAlphaQuench) * rFilteredQuenchVolts);

IF rFilteredQuenchVolts > rQuenchThreshold AND rCoilCurrent > 1.0 THEN
    tQuenchBlanking(IN := TRUE, PT := T#10MS);
    IF tQuenchBlanking.Q THEN
        bQuenchDetected := TRUE;
        bSystemReady := FALSE;
        rPowerOutputSetpt := 0.0;
        rCurrentChargeSetpt := 0.0;
        iState := 999; 
        bAlarm := TRUE;
        RETURN;
    END_IF;
ELSE
    tQuenchBlanking(IN := FALSE);
END_IF;

(* === CRYO-COOLING PID CONTROL LOOP === *)
rTempError := rHeliumTemp - rTempTarget;
rTempIntegral := rTempIntegral + (rTempError * 0.1); (* Assuming 100ms task cycle *)
(* Anti-windup *)
IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
IF rTempIntegral < -100.0 THEN rTempIntegral := -100.0; END_IF;

rCryocoolerValve := (rKp_Cryo * rTempError) + (rKi_Cryo * rTempIntegral);
IF rCryocoolerValve > 100.0 THEN rCryocoolerValve := 100.0; END_IF;
IF rCryocoolerValve < 0.0 THEN rCryocoolerValve := 0.0; END_IF;


(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := FALSE;
        rPowerOutputSetpt := 0.0;
        IF bSystemEnable AND rHeliumTemp <= 4.5 AND rHeliumPressure < 0.2 THEN
            iState := 10;
        END_IF;

    10: (* SUB-COOLING STABILIZATION *)
        tStartupDelay(IN := TRUE, PT := T#30S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;
        IF rHeliumTemp > 4.6 THEN
            iState := 0; (* Abort if temp rises *)
            tStartupDelay(IN := FALSE);
        END_IF;

    20: (* READY TO CHARGE / INJECT *)
        bSystemReady := TRUE;

        (* Transient Power Injection Logic *)
        IF rPowerDemand > 0.1 AND rGridFreq < 49.8 THEN
            (* Grid under-frequency event -> Inject Power *)
            rPowerOutputSetpt := rPowerDemand;
            rCurrentChargeSetpt := 0.0;
        ELSIF rPowerDemand < -0.1 AND rCoilCurrent < rMaxOperatingCurrent THEN
            (* Grid over-frequency or surplus -> Absorb Power *)
            rPowerOutputSetpt := 0.0;
            rCurrentChargeSetpt := ABS(rPowerDemand) * 10.0; (* Proportional charge *)
        ELSE
            (* Hold state *)
            rPowerOutputSetpt := 0.0;
            rCurrentChargeSetpt := 0.0; (* Should hold current in persistent mode *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT / TRIP STATE *)
        bSystemReady := FALSE;
        rPowerOutputSetpt := 0.0;
        rCurrentChargeSetpt := 0.0;
        (* Require manual reset via cycling bEmergencyStop *)

END_CASE;

END_FUNCTION_BLOCK
```

