Here is the final, highly robust SCL program. It introduces an adversarial robustness layer utilizing redundant sensor correlation to detect drift, enforces HIL digital twin synchronization, and implements a state-machine driven pre-startup self-test sequence.

TYPE "SCADA_Data"
    STRUCT
        InverterState : INT;
        ActivePower : REAL;
        FaultCode : WORD;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "Solar_Inverter_Adversarial"
VAR_INPUT
    PV_Voltage_1 : REAL;
    PV_Voltage_2 : REAL; // Redundant sensor for drift detection
    PV_Current : REAL;
    Grid_Voltage : REAL;
    Grid_Freq : REAL;
    IGBT_Temp : REAL;
    AccessLevel : INT; 
    Primary_Active : BOOL;
    Peer_Heartbeat : BOOL;
    HIL_Sync_Clock : DINT; // Digital Twin clock sync signal
    Start_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : REAL;
    Sync_OK : BOOL;
    Standby_Mode : BOOL;
    SCADA_Out : "SCADA_Data";
    Self_Test_Passed : BOOL;
END_VAR
VAR
    Fault_Word : WORD;
    Prev_Power : REAL;
    Prev_Voltage : REAL;
    State : INT := 0; // 0=Off, 1=Self-Test, 2=Run
END_VAR
BEGIN
    // Security check (IEC 62443)
    IF AccessLevel < 2 THEN RETURN; END_IF;

    // Sensor Drift Detection (Adversarial Robustness)
    IF ABS(PV_Voltage_1 - PV_Voltage_2) > 5.0 THEN
        Fault_Word := Fault_Word OR 16#0100; // Sensor drift fault flag
    END_IF;
    VAR PV_Voltage_Safe : REAL := (PV_Voltage_1 + PV_Voltage_2) / 2.0; // Use average if safe

    // Failover
    Standby_Mode := NOT (Primary_Active AND Peer_Heartbeat);

    // State Machine & Self-Test Routine
    CASE State OF
        0: // Off
            IF Start_Cmd THEN State := 1; END_IF;
            PWM_Duty_Cycle := 0.0;
            Self_Test_Passed := FALSE;
        1: // Self-Test & HIL Sync check
            IF Fault_Word = 0 AND PV_Voltage_Safe > 50.0 AND HIL_Sync_Clock > 0 THEN
                Self_Test_Passed := TRUE;
                State := 2;
            ELSE
                State := 0; // Failed test, return to Off
            END_IF;
        2: // Run
            IF NOT Standby_Mode AND Fault_Word = 0 THEN
                VAR Current_Power : REAL := PV_Voltage_Safe * PV_Current;
                VAR Power_Limit : REAL := LIMIT(MN:=0.0, IN:=(1.0 - (IGBT_Temp - 85.0)*0.05), MX:=1.0);

                VAR deltaP : REAL := Current_Power - Prev_Power;
                VAR deltaV : REAL := PV_Voltage_Safe - Prev_Voltage;
                IF (deltaP > 0.0 AND deltaV > 0.0) OR (deltaP < 0.0 AND deltaV < 0.0) THEN
                    PWM_Duty_Cycle := PWM_Duty_Cycle - 0.01;
                ELSE
                    PWM_Duty_Cycle := PWM_Duty_Cycle + 0.01;
                END_IF;

                PWM_Duty_Cycle := LIMIT(MN:=0.0, IN:=PWM_Duty_Cycle * Power_Limit, MX:=1.0);
                Prev_Power := Current_Power; Prev_Voltage := PV_Voltage_Safe;
                SCADA_Out.ActivePower := Current_Power;
            ELSE
                PWM_Duty_Cycle := 0.0;
            END_IF;
    END_CASE;

    Sync_OK := (Grid_Voltage > 210.0 AND Grid_Voltage < 250.0) AND (Grid_Freq > 49.5 AND Grid_Freq < 50.5);
    SCADA_Out.InverterState := State;
    SCADA_Out.FaultCode := Fault_Word;
END_FUNCTION_BLOCK
