FUNCTION_BLOCK FB_MultiAxisPalletizing_Core
VAR_INPUT
    bEnableSystem : BOOL; // Master enable
    bEStopActuated : BOOL; // Emergency stop active high
    bProductAtPick : BOOL; // Sensor input: Product ready for pickup
    bSlipSheetMagEmpty : BOOL; // Sensor input: Slip sheet magazine empty
    bPalletPresent : BOOL; // Sensor input: Empty pallet present
    iRecipeID : INT; // 1=Standard Carton, 2=Display Carton, 3=Heavy Bags
    iLayerPattern : INT; // 1=Interlocking, 2=Column, 3=Pinwheel
    rActPosX : REAL; // Current robot articulation X
    rActPosY : REAL; // Current robot articulation Y
    rActPosZ : REAL; // Current robot articulation Z
    rActPosW : REAL; // Current robot articulation W
    rVacuumLevel : REAL; // Current vacuum level measured at EOAT manifold
END_VAR
VAR_OUTPUT
    bDriveEnable : BOOL; // Enable servos
    bVacuumValveZone1 : BOOL; // EOAT cascade zone 1
    bVacuumValveZone2 : BOOL; // EOAT cascade zone 2
    bVacuumValveZone3 : BOOL; // EOAT cascade zone 3
    bVacuumValveZone4 : BOOL; // EOAT cascade zone 4
    bBlowoffValve : BOOL; // Release assist
    bRequestPalletExchange : BOOL;
    rCmdPosX : REAL; // Command X
    rCmdPosY : REAL; // Command Y
    rCmdPosZ : REAL; // Command Z
    rCmdPosW : REAL; // Command W
    rMotionSpeed : REAL; // Override speed (0.0 to 100.0)
    iSequenceState : INT; // Current step in sequence
    bFaultActive : BOOL;
    iFaultCode : DINT;
END_VAR
VAR
    // Internal state logic
    iCurrentLayer : INT := 1;
    iBoxesPlacedInLayer : INT := 0;
    iMaxBoxesPerLayer : INT := 10;
    iMaxLayers : INT := 5;
    iSlipSheetFreq : INT := 2; // Insert slip sheet every 2 layers

    // Timers
    tVacuumSettle : TON;
    tBlowoffPulse : TON;
    tMotionTimeout : TON;

    // Coordinates and offsets
    rPickPosX : REAL := 1500.0;
    rPickPosY : REAL := -500.0;
    rPickPosZ : REAL := 800.0;

    rSlipSheetPickX : REAL := -1200.0;
    rSlipSheetPickY : REAL := 0.0;
    rSlipSheetPickZ : REAL := 500.0;

    rPalletOriginX : REAL := 0.0;
    rPalletOriginY : REAL := 1500.0;
    rPalletOriginZ : REAL := 100.0;

    rBoxDimX : REAL := 300.0;
    rBoxDimY : REAL := 200.0;
    rBoxDimZ : REAL := 250.0;

    // State Machine Enum implementation (using INT)
    // 0=Init, 10=WaitProduct, 20=ApproachPick, 30=EngageVacuum, 40=DepartPick, 50=ApproachPlace, 60=ReleaseProduct, 70=DepartPlace, 80=CheckLayer, 90=SlipSheetRoutine, 100=PalletExchange, 999=Fault

    bInitDone : BOOL := FALSE;
END_VAR

// [1] Emergency Stop & Fault Handling
IF bEStopActuated THEN
    bDriveEnable := FALSE;
    bVacuumValveZone1 := FALSE; bVacuumValveZone2 := FALSE;
    bVacuumValveZone3 := FALSE; bVacuumValveZone4 := FALSE;
    bFaultActive := TRUE;
    iFaultCode := 16#E570; // E-STOP
    iSequenceState := 999;
    RETURN;
END_IF

IF NOT bEnableSystem THEN
    iSequenceState := 0; // Reset to init
    bDriveEnable := FALSE;
    RETURN;
END_IF

// [2] Initialization
IF NOT bInitDone THEN
    iCurrentLayer := 1;
    iBoxesPlacedInLayer := 0;
    bRequestPalletExchange := FALSE;

    // Load recipe specifics
    CASE iRecipeID OF
        1: // Standard Carton
            iMaxBoxesPerLayer := 12;
            iMaxLayers := 6;
            rBoxDimX := 400.0; rBoxDimY := 300.0; rBoxDimZ := 200.0;
        2: // Display Carton
            iMaxBoxesPerLayer := 8;
            iMaxLayers := 4;
            rBoxDimX := 600.0; rBoxDimY := 400.0; rBoxDimZ := 300.0;
    ELSE
        iFaultCode := 16#1001; // Invalid Recipe
        iSequenceState := 999;
    END_CASE

    bInitDone := TRUE;
    bDriveEnable := TRUE;
    iSequenceState := 10;
END_IF

// [3] Main State Machine
CASE iSequenceState OF

    10: // WaitProduct
        IF bProductAtPick AND bPalletPresent THEN
            iSequenceState := 20;
        ELSIF NOT bPalletPresent THEN
            iSequenceState := 100;
        END_IF

    20: // ApproachPick
        rCmdPosX := rPickPosX;
        rCmdPosY := rPickPosY;
        rCmdPosZ := rPickPosZ;
        rCmdPosW := 0.0;
        rMotionSpeed := 80.0;

        // Check in position (simulated via deadband)
        IF ABS(rActPosX - rCmdPosX) < 5.0 AND ABS(rActPosY - rCmdPosY) < 5.0 THEN
            iSequenceState := 30;
        END_IF

    30: // EngageVacuum - Cascade logic
        // Turn on zones depending on recipe
        bVacuumValveZone1 := TRUE;
        bVacuumValveZone2 := TRUE;
        IF iRecipeID = 2 THEN
            bVacuumValveZone3 := TRUE;
            bVacuumValveZone4 := TRUE;
        END_IF

        tVacuumSettle(IN:= TRUE, PT:= T#500MS);
        IF tVacuumSettle.Q AND rVacuumLevel > 65.0 THEN // Vacuum established
            tVacuumSettle(IN:= FALSE);
            iSequenceState := 40;
        ELSIF tVacuumSettle.Q AND rVacuumLevel <= 65.0 THEN
            iFaultCode := 16#2001; // Vacuum Fail
            iSequenceState := 999;
        END_IF

    40: // DepartPick
        rCmdPosZ := rPickPosZ + 300.0; // Clear height
        IF ABS(rActPosZ - rCmdPosZ) < 5.0 THEN
            iSequenceState := 50;
        END_IF

    50: // ApproachPlace - Pattern Generation Logic
        // Simple column/interlocking logic demonstration
        IF iLayerPattern = 1 THEN // Interlocking
            IF (iCurrentLayer MOD 2) <> 0 THEN
                rCmdPosX := rPalletOriginX + ((iBoxesPlacedInLayer MOD 3) * rBoxDimX);
                rCmdPosY := rPalletOriginY + ((iBoxesPlacedInLayer / 3) * rBoxDimY);
                rCmdPosW := 0.0;
            ELSE
                rCmdPosX := rPalletOriginX + ((iBoxesPlacedInLayer MOD 4) * rBoxDimY);
                rCmdPosY := rPalletOriginY + ((iBoxesPlacedInLayer / 4) * rBoxDimX);
                rCmdPosW := 90.0; // Rotate 90 degrees
            END_IF
        ELSE // Column (Pattern 2)
            rCmdPosX := rPalletOriginX + ((iBoxesPlacedInLayer MOD 3) * rBoxDimX);
            rCmdPosY := rPalletOriginY + ((iBoxesPlacedInLayer / 3) * rBoxDimY);
            rCmdPosW := 0.0;
        END_IF

        rCmdPosZ := rPalletOriginZ + ((iCurrentLayer - 1) * rBoxDimZ) + rBoxDimZ;
        rMotionSpeed := 60.0;

        IF ABS(rActPosX - rCmdPosX) < 5.0 AND ABS(rActPosY - rCmdPosY) < 5.0 AND ABS(rActPosZ - rCmdPosZ) < 5.0 THEN
            iSequenceState := 60;
        END_IF

    60: // ReleaseProduct
        bVacuumValveZone1 := FALSE; bVacuumValveZone2 := FALSE;
        bVacuumValveZone3 := FALSE; bVacuumValveZone4 := FALSE;
        bBlowoffValve := TRUE;

        tBlowoffPulse(IN:= TRUE, PT:= T#200MS);
        IF tBlowoffPulse.Q THEN
            bBlowoffValve := FALSE;
            tBlowoffPulse(IN:= FALSE);
            iBoxesPlacedInLayer := iBoxesPlacedInLayer + 1;
            iSequenceState := 70;
        END_IF

    70: // DepartPlace
        rCmdPosZ := rCmdPosZ + 200.0; // Z-clearance
        IF ABS(rActPosZ - rCmdPosZ) < 5.0 THEN
            iSequenceState := 80;
        END_IF

    80: // CheckLayer
        IF iBoxesPlacedInLayer >= iMaxBoxesPerLayer THEN
            iCurrentLayer := iCurrentLayer + 1;
            iBoxesPlacedInLayer := 0;

            IF iCurrentLayer > iMaxLayers THEN
                iSequenceState := 100; // Pallet full
            ELSIF (iCurrentLayer - 1) MOD iSlipSheetFreq = 0 THEN
                iSequenceState := 90; // Needs slip sheet
            ELSE
                iSequenceState := 10; // Wait for next product
            END_IF
        ELSE
            iSequenceState := 10;
        END_IF

    90: // SlipSheetRoutine - Abstracted implementation
        IF bSlipSheetMagEmpty THEN
            iFaultCode := 16#3001; // No Slip Sheets
            iSequenceState := 999;
        ELSE
            // Sub-routine to pick and place slip sheet would go here
            // Assumed completed synchronously for this FB scope
            iSequenceState := 10;
        END_IF

    100: // PalletExchange
        bRequestPalletExchange := TRUE;
        IF bPalletPresent AND NOT bProductAtPick THEN // User reset
            bRequestPalletExchange := FALSE;
            iCurrentLayer := 1;
            iBoxesPlacedInLayer := 0;
            iSequenceState := 10;
        END_IF

    999: // Fault state
        bDriveEnable := FALSE;
        bFaultActive := TRUE;
