TYPE E_PSA_Phase : (
    PSA_ADSORPTION          := 0,
    PSA_EQUALIZATION_DOWN   := 1,
    PSA_BLOWDOWN            := 2,
    PSA_PURGE               := 3,
    PSA_EQUALIZATION_UP     := 4,
