FUNCTION_BLOCK FB_EGS_ORC_Control
(* =====================================================================================
   Title: Enhanced Geothermal System (EGS) Binary Cycle ORC Controller
   Description: Advanced utility-scale control for Organic Rankine Cycle (ORC) isobutane 
                flashing, production well submersible pump Variable Frequency Drive (VFD), 
                and injection well thermal fracturing micro-seismic safety monitoring.
   Author: 40-Year Veteran Automation Architect
   ===================================================================================== *)

VAR_INPUT
    bEnableSystem          : BOOL;  (* Master system enable for EGS binary cycle *)
    bEmergencyStopOk       : BOOL;  (* Safety relay input (TRUE = OK, FALSE = E-STOP) *)
    rProductionTemp        : REAL;  (* Production wellhead fluid temperature (deg C) *)
    rProductionPress       : REAL;  (* Production wellhead fluid pressure (bar) *)
    rIsobutaneFlowRate     : REAL;  (* Isobutane working fluid mass flow (kg/s) *)
    rTurbineSpeedRPM       : REAL;  (* ORC turbine speed feedback (RPM) *)
    rMicroSeismicPeakG     : REAL;  (* Peak ground acceleration from geophones (g) *)
    bGridSyncOk            : BOOL;  (* Electrical grid synchronization status *)
END_VAR

VAR_OUTPUT
    bSystemRunning         : BOOL;  (* Main operational state indicator *)
    rPumpVFDReference      : REAL;  (* Submersible pump speed reference (0-100%) *)
    rIsobutaneValveCmd     : REAL;  (* Isobutane expansion valve position (0-100%) *)
    bInjectionValveOpen    : BOOL;  (* Injection well reinjection valve command *)
    bTurbineTrip           : BOOL;  (* Emergency turbine trip signal *)
    bSeismicAlarm          : BOOL;  (* Micro-seismic threshold exceeded alarm *)
    iStateCurrent          : INT;   (* Current internal state machine step *)
END_VAR

VAR
    iState                 : INT := 0;  (* Internal state machine variable *)
    tWarmUpTimer           : TON;       (* Production well thermal stabilization timer *)
    tSeismicHoldTimer      : TON;       (* Hold timer after seismic event *)
    rTargetFlowCalc        : REAL;      (* Calculated target isobutane flow *)

    (* Constants for Process Limits *)
    MAX_TEMP_C             : REAL := 220.0;
    MIN_TEMP_C             : REAL := 150.0;
    MAX_SEISMIC_G          : REAL := 0.05; 
    TURBINE_OVERSPEED      : REAL := 3600.0;
END_VAR

(* === SAFETY & INTERLOCKS === *)
IF NOT bEmergencyStopOk THEN
    (* Immediate system shutdown on E-Stop loss *)
    bSystemRunning      := FALSE;
    rPumpVFDReference   := 0.0;
    rIsobutaneValveCmd  := 0.0;
    bInjectionValveOpen := FALSE;
    bTurbineTrip        := TRUE;
    iState              := 999; (* Fault state *)
    RETURN;
END_IF;

(* Continuous Seismic Monitoring *)
IF rMicroSeismicPeakG > MAX_SEISMIC_G THEN
    bSeismicAlarm       := TRUE;
    rPumpVFDReference   := 0.0; (* Stop production well pumping *)
    bInjectionValveOpen := FALSE; (* Stop injection to halt thermal fracturing *)
    tSeismicHoldTimer(IN := TRUE, PT := T#12H); (* 12-hour mandatory hold *)
ELSE
    tSeismicHoldTimer(IN := FALSE);
    IF tSeismicHoldTimer.Q THEN
        bSeismicAlarm := FALSE;
    END_IF;
END_IF;

(* Turbine Overspeed Protection *)
IF rTurbineSpeedRPM > TURBINE_OVERSPEED THEN
    bTurbineTrip := TRUE;
    rIsobutaneValveCmd := 0.0;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & READY TO START *)
        bSystemRunning := FALSE;
        rPumpVFDReference := 0.0;
        rIsobutaneValveCmd := 0.0;
        bInjectionValveOpen := FALSE;
        bTurbineTrip := FALSE;
        iStateCurrent := 0;

        IF bEnableSystem AND NOT bSeismicAlarm AND NOT bTurbineTrip THEN
            iState := 10;
        END_IF;

    10: (* PRODUCTION WELL WARM-UP *)
        iStateCurrent := 10;
        rPumpVFDReference := 25.0; (* Start pump at 25% for slow fluid draw *)

        (* Wait for temperature to reach operating range *)
        tWarmUpTimer(IN := (rProductionTemp > MIN_TEMP_C), PT := T#10M);

        IF tWarmUpTimer.Q THEN
            tWarmUpTimer(IN := FALSE);
            iState := 20;
        END_IF;

        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    20: (* BINARY CYCLE SYNCHRONIZATION *)
        iStateCurrent := 20;
        bInjectionValveOpen := TRUE;
        rPumpVFDReference := 60.0; (* Ramp up production *)

        (* PID-like calc for valve based on pressure and temperature *)
        rTargetFlowCalc := (rProductionTemp - MIN_TEMP_C) * 1.25;
        rIsobutaneValveCmd := LIMIT(0.0, rTargetFlowCalc, 100.0);

        IF bGridSyncOk AND rTurbineSpeedRPM > 2900.0 THEN
            iState := 30;
        END_IF;

        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    30: (* FULL STEADY-STATE OPERATION *)
        iStateCurrent := 30;
        bSystemRunning := TRUE;
        rPumpVFDReference := 90.0; (* Max efficiency point *)

        (* Maintain steady isobutane expansion *)
        IF rIsobutaneFlowRate < (rTargetFlowCalc * 0.9) THEN
            rIsobutaneValveCmd := MIN(rIsobutaneValveCmd + 0.5, 100.0);
        ELSIF rIsobutaneFlowRate > (rTargetFlowCalc * 1.1) THEN
            rIsobutaneValveCmd := MAX(rIsobutaneValveCmd - 0.5, 0.0);
        END_IF;

        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

    999: (* FAULT SHUTDOWN STATE *)
        iStateCurrent := 999;
        bSystemRunning := FALSE;
        IF bEmergencyStopOk AND NOT bSeismicAlarm THEN
            (* Manual reset logic could go here; auto-reset to IDLE if safe *)
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
