```iec-st
\nFUNCTION_BLOCK FB_RollToRollSintering_SolidState
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL;
    bReset : BOOL;
    rWebSpeedCmd : REAL; // Commanded web speed [m/min]
    rTensionSetpoint : REAL; // Setpoint tension [N]
    rThicknessSetpoint : REAL; // Target thickness [um]
    rZone1TempSetpoint : REAL; // Sintering zone 1 temperature setpoint [C]
    rZone2TempSetpoint : REAL; // Sintering zone 2 temperature setpoint [C]
    rZone3TempSetpoint : REAL; // Sintering zone 3 temperature setpoint [C]
    rLaserThicknessActual : REAL; // Actual thickness from laser measurement [um]
    rWebTensionActual : REAL; // Actual web tension from load cells [N]
    rZone1TempActual : REAL;
    rZone2TempActual : REAL;
    rZone3TempActual : REAL;
    rCoolingZoneTempActual : REAL;
END_VAR
VAR_OUTPUT
    bSystemReady : BOOL;
    bRunning : BOOL;
    bAlarm : BOOL;
    iAlarmCode : INT;
    rDriveSpeedRef : REAL; // Speed reference to main drive
    rUnwindBrakeTorque : REAL; // Torque command to unwind brake
    rRewindTorque : REAL; // Torque command to rewind drive
    rZone1HeaterCmd : REAL; // Heater output 0-100%
    rZone2HeaterCmd : REAL; // Heater output 0-100%
    rZone3HeaterCmd : REAL; // Heater output 0-100%
    rCoolingFanCmd : REAL; // Cooling fan output 0-100%
    rCalenderPressureCmd : REAL; // Pressure command for calendering rolls [bar]
END_VAR
VAR
    // PID controllers
    fbPID_Tension : FB_PID_Advanced;
    fbPID_Rewind : FB_PID_Advanced;
    fbPID_Zone1 : FB_PID_Advanced;
    fbPID_Zone2 : FB_PID_Advanced;
    fbPID_Zone3 : FB_PID_Advanced;
    fbPID_Thickness : FB_PID_Advanced;

    // State machine
    eState : (INIT, IDLE, WARMUP, RUNNING, STOPPING, FAULT);

    // Timers
    tWarmupTimer : TON;
    tTensionFilter : FILTER_IIR;
    tThicknessFilter : FILTER_IIR;

    // Internal variables
    rFilteredTension : REAL;
    rFilteredThickness : REAL;
    bTempsAtSetpoint : BOOL;
    rMaxTempDev : REAL := 5.0; // Max temp deviation in C
    bInitDone : BOOL;
END_VAR

// Initialization
IF NOT bInitDone THEN
    bInitDone := TRUE;
    eState := INIT;
    // Init PID parameters for tension
    fbPID_Tension(Kp := 0.85, Ki := 0.12, Kd := 0.05, OutMin := 0.0, OutMax := 100.0);
    fbPID_Rewind(Kp := 1.1, Ki := 0.15, Kd := 0.02, OutMin := 0.0, OutMax := 100.0);

    // Init PID parameters for thickness control (calendering pressure)
    fbPID_Thickness(Kp := 2.5, Ki := 0.5, Kd := 0.1, OutMin := 0.0, OutMax := 150.0);

    // Init PID parameters for heating zones
    fbPID_Zone1(Kp := 5.0, Ki := 0.2, Kd := 1.0, OutMin := 0.0, OutMax := 100.0);
    fbPID_Zone2(Kp := 5.0, Ki := 0.2, Kd := 1.0, OutMin := 0.0, OutMax := 100.0);
    fbPID_Zone3(Kp := 5.0, Ki := 0.2, Kd := 1.0, OutMin := 0.0, OutMax := 100.0);

    // Init filters
    tTensionFilter(TimeConstant := T#100ms);
    tThicknessFilter(TimeConstant := T#50ms);
END_IF

// Filter Inputs
rFilteredTension := tTensionFilter(rWebTensionActual);
rFilteredThickness := tThicknessFilter(rLaserThicknessActual);

// Reset Logic
IF bReset THEN
    bAlarm := FALSE;
    iAlarmCode := 0;
    IF eState = FAULT THEN
        eState := IDLE;
    END_IF
END_IF

// State Machine
CASE eState OF
    INIT:
        eState := IDLE;

    IDLE:
        bSystemReady := TRUE;
        bRunning := FALSE;
        rDriveSpeedRef := 0.0;
        rUnwindBrakeTorque := 0.0;
        rRewindTorque := 0.0;
        rZone1HeaterCmd := 0.0;
        rZone2HeaterCmd := 0.0;
        rZone3HeaterCmd := 0.0;
        rCalenderPressureCmd := 0.0;

        IF bEnable THEN
            eState := WARMUP;
            bSystemReady := FALSE;
        END_IF

    WARMUP:
        // Turn on heaters
        fbPID_Zone1(rSetpoint := rZone1TempSetpoint, rActual := rZone1TempActual, rOutput => rZone1HeaterCmd);
        fbPID_Zone2(rSetpoint := rZone2TempSetpoint, rActual := rZone2TempActual, rOutput => rZone2HeaterCmd);
        fbPID_Zone3(rSetpoint := rZone3TempSetpoint, rActual := rZone3TempActual, rOutput => rZone3HeaterCmd);

        // Check if temps are at setpoint
        bTempsAtSetpoint := (ABS(rZone1TempSetpoint - rZone1TempActual) < rMaxTempDev) AND
                            (ABS(rZone2TempSetpoint - rZone2TempActual) < rMaxTempDev) AND
                            (ABS(rZone3TempSetpoint - rZone3TempActual) < rMaxTempDev);

        tWarmupTimer(IN := bTempsAtSetpoint, PT := T#10s);

        IF tWarmupTimer.Q THEN
            eState := RUNNING;
        END_IF

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF

    RUNNING:
        bRunning := TRUE;

        // Web tension control
        fbPID_Tension(rSetpoint := rTensionSetpoint, rActual := rFilteredTension, rOutput => rUnwindBrakeTorque);
        fbPID_Rewind(rSetpoint := rTensionSetpoint, rActual := rFilteredTension, rOutput => rRewindTorque); // Simplified rewind tension matching

        // Thickness control via Calender pressure
        fbPID_Thickness(rSetpoint := rThicknessSetpoint, rActual := rFilteredThickness, rOutput => rCalenderPressureCmd);

        // Sintering zones temperature control
        fbPID_Zone1(rSetpoint := rZone1TempSetpoint, rActual := rZone1TempActual, rOutput => rZone1HeaterCmd);
        fbPID_Zone2(rSetpoint := rZone2TempSetpoint, rActual := rZone2TempActual, rOutput => rZone2HeaterCmd);
        fbPID_Zone3(rSetpoint := rZone3TempSetpoint, rActual := rZone3TempActual, rOutput => rZone3HeaterCmd);

        // Speed control
        rDriveSpeedRef := rWebSpeedCmd;

        // Cooling fan simple logic based on actual temp
        IF rCoolingZoneTempActual > 40.0 THEN
            rCoolingFanCmd := 100.0;
        ELSE
            rCoolingFanCmd := 0.0;
        END_IF

        // Alarms
        IF rFilteredTension > (rTensionSetpoint * 1.5) THEN
            bAlarm := TRUE;
            iAlarmCode := 101; // Over tension
            eState := FAULT;
        END_IF

        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF

    STOPPING:
        bRunning := FALSE;
        rDriveSpeedRef := 0.0;

        // Turn off heaters
        rZone1HeaterCmd := 0.0;
        rZone2HeaterCmd := 0.0;
        rZone3HeaterCmd := 0.0;

        // Slowly release tension
        rUnwindBrakeTorque := rUnwindBrakeTorque * 0.99; 
        rRewindTorque := rRewindTorque * 0.99;

        IF rUnwindBrakeTorque < 1.0 AND rRewindTorque < 1.0 THEN
            eState := IDLE;
        END_IF

    FAULT:
        bRunning := FALSE;
        rDriveSpeedRef := 0.0;
        rUnwindBrakeTorque := 0.0;
        rRewindTorque := 0.0;
        rZone1HeaterCmd := 0.0;
        rZone2HeaterCmd := 0.0;
        rZone3HeaterCmd := 0.0;
        rCalenderPressureCmd := 0.0;

END_CASE
END_FUNCTION_BLOCK\n```
