FUNCTION_BLOCK FB_SupertallElevatorDynamics
TITLE = 'High-Speed Skyscraper Elevator Comprehensive Control'
// Author: Lumina Synthetic Swarm
// Domain: Supertall Skyscraper High-Speed Elevators
// Capabilities: Active Mass Damper Sway Mitigation, Aero-Guide Shoe Tracking, Regenerative Braking
// Version: 1.0.0
// Description: Implements comprehensive multi-axis motion and dynamics management for 
//              elevators operating in >600m class megatall structures.

VAR_INPUT
    // Physical I/O & Sensor Feedback
    rBuildingSwayX_mm       : REAL; // X-axis building sway amplitude from optical laser gyros
    rBuildingSwayY_mm       : REAL; // Y-axis building sway amplitude from optical laser gyros
    rCarVelocity_mps        : REAL; // Current elevator velocity in meters/sec
    rCarPosition_m          : REAL; // Current vertical position in meters (absolute encoder)
    rTargetPosition_m       : REAL; // Target vertical position requested by dispatch
    rCarAcceleration_mpss   : REAL; // Current acceleration (IMU z-axis)
    rGuideShoeGap_N_mm      : REAL; // North active guide shoe gap feedback (eddy current sensor)
    rGuideShoeGap_S_mm      : REAL; // South active guide shoe gap feedback
    rGuideShoeGap_E_mm      : REAL; // East active guide shoe gap feedback
    rGuideShoeGap_W_mm      : REAL; // West active guide shoe gap feedback
    bGridPowerAvailable     : BOOL; // Status of local energy grid for regen braking sync
    rSwayFrequency_Hz       : REAL; // Dominant structural resonance frequency (FFT derived)
END_VAR

VAR_OUTPUT
    // Actuators & Drive Commands
    rHoistMotorTorqueCmd    : REAL; // Hoist drive torque command (-100.0 to 100.0%)
    bRegenContactorClose    : BOOL; // Enable regenerative brake dumping to AC grid
    rDamperForceX_N         : REAL; // Command force for X-axis active mass damper linear motors
    rDamperForceY_N         : REAL; // Command force for Y-axis active mass damper linear motors
    rAeroShoeAngleX_deg     : REAL; // Actuator angle for X-axis aerodynamic guide shoes (East/West)
    rAeroShoeAngleY_deg     : REAL; // Actuator angle for Y-axis aerodynamic guide shoes (North/South)
    rEmergencyBrakeForce_kN : REAL; // Mechanical brake force command (proportional solenoid)
    bSystemHealthy          : BOOL; // Master safety interlock relay output
END_VAR

VAR
    // Internal State & Tuning Parameters
    rVelocityError          : REAL;
    rPositionError          : REAL;
    rDecelerationPoint_m    : REAL := 15.0; // Distance to start regenerative deceleration profile
    rSwayThreshold_mm       : REAL := 45.0; // Threshold before active mass damping engages

    // PID States for Linear Motor Damper
    rDamperKp               : REAL := 15.5; // Proportional gain for sway tracking
    rDamperKd               : REAL := 6.2;  // Derivative gain for sway velocity
    rDamperPrevErrorX       : REAL := 0.0;
    rDamperPrevErrorY       : REAL := 0.0;

    // Aero Shoe Controller
    rNominalGap_mm          : REAL := 5.0;  // mm target gap for smooth ride
    rAeroGain               : REAL := 3.1;  // Aerodynamic control surface multiplier

    // State Machine
    iElevatorState          : INT := 0; // 0=IDLE, 1=ACCEL, 2=CRUISE, 3=DECEL(REGEN), 4=LEVELING, 99=FAULT
    bOverspeedFault         : BOOL := FALSE;
    bTrackingError          : BOOL := FALSE;
END_VAR

// ==============================================================================
// 1. STATE MACHINE & VERTICAL MOTION PROFILE 
// ==============================================================================
rPositionError := rTargetPosition_m - rCarPosition_m;
bSystemHealthy := NOT bOverspeedFault AND NOT bTrackingError;

IF bSystemHealthy THEN
    IF ABS(rPositionError) < 0.015 THEN
        iElevatorState := 0; // IDLE / HOLD
        rHoistMotorTorqueCmd := 0.0;
        bRegenContactorClose := FALSE;
    ELSIF ABS(rPositionError) > rDecelerationPoint_m AND rCarVelocity_mps < 20.0 THEN
        iElevatorState := 1; // ACCEL / CRUISE
        rHoistMotorTorqueCmd := 85.0; // Accelerating torque profile
        bRegenContactorClose := FALSE;
    ELSIF ABS(rPositionError) <= rDecelerationPoint_m THEN
        iElevatorState := 3; // DECEL (REGEN PHASE)
        rHoistMotorTorqueCmd := -65.0; // Braking torque applied
        // Enable Regen dumping if grid is synchronized and kinetic energy is sufficient
        IF bGridPowerAvailable AND rCarVelocity_mps > 2.5 THEN
            bRegenContactorClose := TRUE;
        ELSE
            bRegenContactorClose := FALSE;
        END_IF;
    END_IF;
ELSE
    iElevatorState := 99; // FAULT
END_IF;

// SIL3 Safety Override
IF rCarVelocity_mps > 24.5 THEN
    bOverspeedFault := TRUE;
    rEmergencyBrakeForce_kN := 180.0; // Deploy progressive safety gears
    rHoistMotorTorqueCmd := 0.0;
    bRegenContactorClose := FALSE;
END_IF;

// ==============================================================================
// 2. ACTIVE MASS DAMPER SWAY MITIGATION (CAR ROOF)
// ==============================================================================
// Implementing PD control loop to counteract vortex-shedding building sway 
// Calculates required counter-force vectors based on frequency and optical gyros.
IF ABS(rBuildingSwayX_mm) > rSwayThreshold_mm THEN
    rDamperForceX_N := (rBuildingSwayX_mm * rDamperKp) + ((rBuildingSwayX_mm - rDamperPrevErrorX) * rDamperKd * rSwayFrequency_Hz);
ELSE
    rDamperForceX_N := 0.0;
END_IF;
rDamperPrevErrorX := rBuildingSwayX_mm;

IF ABS(rBuildingSwayY_mm) > rSwayThreshold_mm THEN
    rDamperForceY_N := (rBuildingSwayY_mm * rDamperKp) + ((rBuildingSwayY_mm - rDamperPrevErrorY) * rDamperKd * rSwayFrequency_Hz);
ELSE
    rDamperForceY_N := 0.0;
END_IF;
rDamperPrevErrorY := rBuildingSwayY_mm;

// ==============================================================================
// 3. DIFFERENTIAL AERODYNAMIC GUIDE SHOE TRACKING
// ==============================================================================
// Adjusts aerodynamic deflectors at extreme descent/ascent speeds to maintain nominal 
// gap tolerances against piston effect and shaft air resistance dynamics.
IF rCarVelocity_mps > 12.0 AND NOT bOverspeedFault THEN
    // X-Axis (East/West) Aero adjustment using differential gap error
    rAeroShoeAngleX_deg := ( (rGuideShoeGap_E_mm - rGuideShoeGap_W_mm) * rAeroGain );
    // Y-Axis (North/South) Aero adjustment
    rAeroShoeAngleY_deg := ( (rGuideShoeGap_N_mm - rGuideShoeGap_S_mm) * rAeroGain );

    // Saturation logic for aerodynamic actuators
    IF rAeroShoeAngleX_deg > 18.0 THEN rAeroShoeAngleX_deg := 18.0; END_IF;
    IF rAeroShoeAngleX_deg < -18.0 THEN rAeroShoeAngleX_deg := -18.0; END_IF;
    IF rAeroShoeAngleY_deg > 18.0 THEN rAeroShoeAngleY_deg := 18.0; END_IF;
    IF rAeroShoeAngleY_deg < -18.0 THEN rAeroShoeAngleY_deg := -18.0; END_IF;
ELSE
    // Retract aero surfaces at lower speeds to minimize mechanical drag
    rAeroShoeAngleX_deg := 0.0;
    rAeroShoeAngleY_deg := 0.0;
END_IF;

END_FUNCTION_BLOCK
