FUNCTION_BLOCK FB_WetMateHVConnectorROVTool
VAR_INPUT
    (* Subsea Wet-Mate Connector Inputs *)
    bEnableOperation        : BOOL;      (* Enable automated mating sequence *)
    bEmergencyAbort         : BOOL;      (* ROV safety shutdown, drops hydraulics *)
    rDepthPressureBar       : REAL;      (* Ambient subsea hydrostatic pressure in Bar *)
    rStabPlateX_Offset      : REAL;      (* ROV Vision/Stab X-axis misalignment mm *)
    rStabPlateY_Offset      : REAL;      (* ROV Vision/Stab Y-axis misalignment mm *)
    rStabPlateZ_Offset      : REAL;      (* ROV Vision/Stab Z-axis approach dist mm *)
    bDielectricOilLevelOK   : BOOL;      (* Internal compensator fluid level sufficient *)
    rPinResistanceOhm       : REAL;      (* Insulation resistance monitoring via megger *)
END_VAR
VAR_OUTPUT
    (* Control System Outputs *)
    bSequenceComplete       : BOOL;      (* High-Voltage connector successfully mated *)
    bSystemFault            : BOOL;      (* Abort/Fault state triggered *)
    iOperationStep          : INT;       (* Current state machine step for HMI/Telemetry *)
    rHydraulicDriveCmd      : REAL;      (* Active compliance Z-axis hydraulic command 0-100% *)
    rX_AxisCompCmd          : REAL;      (* Active compliance X-axis adjustment command *)
    rY_AxisCompCmd          : REAL;      (* Active compliance Y-axis adjustment command *)
    bFlushingValveOpen      : BOOL;      (* Control signal for dielectric oil flush solenoid *)
END_VAR
VAR
    (* Internal state handling and diagnostics variables *)
    iState                  : INT := 0;  (* Internal State Machine variable *)
    tAlignmentTimer         : TON;       (* Timer for mechanical alignment settling *)
    tFlushingTimer          : TON;       (* Timer for dielectric oil flushing duration *)
    tResistanceCheckTimer   : TON;       (* Dwell time for IR test after mate *)
    rAlignmentTolerance     : REAL := 2.5; (* Max allowable mm misalignment to proceed *)
    rPressureDeltaOK        : REAL := 5.0; (* Allowed delta P across seal in Bar *)
    bAlignmentAchieved      : BOOL;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF bEmergencyAbort OR NOT bDielectricOilLevelOK THEN
    bSystemFault := TRUE;
    bSequenceComplete := FALSE;
    bFlushingValveOpen := FALSE;
    rHydraulicDriveCmd := 0.0;
    rX_AxisCompCmd := 0.0;
    rY_AxisCompCmd := 0.0;
    iState := 999; (* FAULT STATE *)
    iOperationStep := iState;
    RETURN;
END_IF;

(* === AUTOMATED MATING STATE MACHINE === *)
CASE iState OF

    0: (* IDLE & INITIALIZATION *)
        bSystemFault := FALSE;
        bSequenceComplete := FALSE;
        bFlushingValveOpen := FALSE;
        rHydraulicDriveCmd := 0.0;
        rX_AxisCompCmd := 0.0;
        rY_AxisCompCmd := 0.0;

        IF bEnableOperation THEN
            iState := 10; (* Start Alignment Phase *)
        END_IF;

    10: (* ACTIVE COMPLIANCE ALIGNMENT (X/Y) *)
        (* Closed-loop proportional control for ROV fine alignment to receptacle *)
        rX_AxisCompCmd := rStabPlateX_Offset * -0.5; (* Proportional gain = 0.5 *)
        rY_AxisCompCmd := rStabPlateY_Offset * -0.5;

        (* Evaluate if within tolerance bounds for final stab insertion *)
        IF (ABS(rStabPlateX_Offset) < rAlignmentTolerance) AND (ABS(rStabPlateY_Offset) < rAlignmentTolerance) THEN
            bAlignmentAchieved := TRUE;
        ELSE
            bAlignmentAchieved := FALSE;
        END_IF;

        tAlignmentTimer(IN := bAlignmentAchieved, PT := T#2S);

        IF tAlignmentTimer.Q THEN
            tAlignmentTimer(IN := FALSE);
            iState := 20; (* Proceed to Pre-Mating Flush *)
            rX_AxisCompCmd := 0.0; (* Lock X/Y compliance once aligned *)
            rY_AxisCompCmd := 0.0;
        END_IF;

    20: (* PRE-MATING DIELECTRIC OIL FLUSH *)
        (* Displaces seawater from the mating chamber before complete pin insertion *)
        bFlushingValveOpen := TRUE;
        tFlushingTimer(IN := TRUE, PT := T#15S); (* Flush for 15 seconds *)

        (* Slowly advance Z-axis while flushing to engage primary seals *)
        rHydraulicDriveCmd := 15.0; (* 15% advance speed limit *)

        IF tFlushingTimer.Q AND (rStabPlateZ_Offset < 20.0) THEN
            tFlushingTimer(IN := FALSE);
            bFlushingValveOpen := FALSE;
            iState := 30; (* Proceed to Final Mating Stroke *)
        END_IF;

    30: (* FINAL MATING STROKE *)
        (* High force insertion to fully engage high-voltage electrical contacts and mechanical latch *)
        rHydraulicDriveCmd := 85.0; (* 85% advance speed/force *)

        IF rStabPlateZ_Offset <= 0.5 THEN (* Fully seated mechanically *)
            rHydraulicDriveCmd := 0.0; (* Stop hydraulic push, hold position *)
            iState := 40; (* Proceed to Electrical Verification *)
        END_IF;

    40: (* INSULATION RESISTANCE (IR) VERIFICATION *)
        (* Wait for ROV-mounted IR tester to complete measurement loop across mated pins vs Ground *)
        tResistanceCheckTimer(IN := TRUE, PT := T#10S);

        IF tResistanceCheckTimer.Q THEN
            tResistanceCheckTimer(IN := FALSE);
            (* Verify >= 1000 Megohms IR before declaring mating successful for HV energization *)
            IF rPinResistanceOhm >= 1000.0 THEN
                iState := 50; (* SUCCESS *)
            ELSE
                iState := 999; (* FAULT: Insulation Failure - Water ingress or particulate detected *)
            END_IF;
        END_IF;

    50: (* SEQUENCE COMPLETE *)
        bSequenceComplete := TRUE;
        IF NOT bEnableOperation THEN
            (* Reset state machine if operation is disabled by master controller post-mate *)
            iState := 0; 
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemFault := TRUE;
        bSequenceComplete := FALSE;
        bFlushingValveOpen := FALSE;
        rHydraulicDriveCmd := 0.0;
        rX_AxisCompCmd := 0.0;
        rY_AxisCompCmd := 0.0;

        IF NOT bEnableOperation AND NOT bEmergencyAbort AND bDielectricOilLevelOK THEN
            (* Operator acknowledged fault and reset condition via toggle of Enable *)
            iState := 0;
        END_IF;

END_CASE;

iOperationStep := iState;

END_FUNCTION_BLOCK
