FUNCTION_BLOCK FB_SubmersiblePenControl
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable            : BOOL;     (* Master system enable signal for the entire pen platform *)
    bEmergencyStop     : BOOL;     (* Safety relay OK signal (NC logic, TRUE = System OK) *)
    rDepthSetpoint     : REAL;     (* Target depth of the submersible pen in meters *)
    rCurrentDepth      : REAL;     (* Measured depth from hydrostatic pressure sensors (m) *)
    rNetTension1       : REAL;     (* Upper mooring ring load cell tension (kN) *)
    rNetTension2       : REAL;     (* Lower mooring ring load cell tension (kN) *)
