    rBallastValveCmd   : REAL;     (* Command to main pneumatic manifold valve (-100 to 100%) *)
    rFeedRateCmd       : REAL;     (* Pellet dispensing feed rate command (kg/hr) *)
    bAlarm             : BOOL;     (* Master fault alarm output *)
    bPredatorAlert     : BOOL;     (* Excessive localized net tension indicating potential predator interaction *)
END_VAR
VAR
    (* Internal state variables *)
    iState             : INT := 0;
    tFeedCycle         : TON;
    tAlarmDelay        : TON;
    rDepthError        : REAL;
    rTensionMax        : REAL;
    rFeedBaseRate      : REAL;
    bTensionFault      : BOOL;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady     := FALSE;
    rBallastValveCmd := 0.0;
    rFeedRateCmd     := 0.0;
    bAlarm           := TRUE;
    iState           := 99; (* Transition to Safe/Estop State *)
    RETURN;
END_IF;

(* Evaluate critical physical limits (High-Tension Net Monitoring) *)
rTensionMax := MAX(rNetTension1, rNetTension2);
IF rTensionMax > 150.0 THEN (* 150 kN critical structural threshold *)
    tAlarmDelay(IN := TRUE, PT := T#2S);
    IF tAlarmDelay.Q THEN
        bTensionFault := TRUE;
        bPredatorAlert := TRUE;
    END_IF;
ELSE
    tAlarmDelay(IN := FALSE);
END_IF;

(* Main Control State Machine *)
CASE iState OF
    0: (* IDLE / INIT *)
        bSystemReady := FALSE;
        rBallastValveCmd := 0.0;
        rFeedRateCmd := 0.0;
        IF bEnable AND NOT bTensionFault THEN
            iState := 10;
        END_IF;

    10: (* RUNNING / BALANCE MONITORING *)
        bSystemReady := TRUE;
        rDepthError := rDepthSetpoint - rCurrentDepth;

        (* Evaluate deadband for buoyancy depth control *)
        IF ABS(rDepthError) > 2.5 THEN
            iState := 20;
        END_IF;

        (* Biomass Feed-forward Check: Start feeding cycle if temperature & stock allow *)
        IF (rWaterTemp > 8.0) AND (rBiomassEstimate > 1000.0) AND NOT bTensionFault THEN
            iState := 30;
        END_IF;

        (* Check enable toggle *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* BUOYANCY CONTROL (Dynamic Multi-Chamber Pneumatic Balancing) *)
        bSystemReady := FALSE;

        (* Simple proportional control for pneumatic ballast valve simulation *)
        IF rDepthError > 0.0 THEN
            rBallastValveCmd := rDepthError * -10.0; (* Negative to vent air and dive *)
        ELSE
            rBallastValveCmd := rDepthError * 10.0;  (* Positive to blow air and surface *)
        END_IF;

        (* Clamp outputs to physical constraints *)
        IF rBallastValveCmd > 100.0 THEN rBallastValveCmd := 100.0; END_IF;
        IF rBallastValveCmd < -100.0 THEN rBallastValveCmd := -100.0; END_IF;

        IF ABS(rDepthError) <= 0.5 THEN
            rBallastValveCmd := 0.0;
            iState := 10;
        END_IF;

    30: (* FEEDING (Acoustic Biomass Feed-Forward Pellet Dispensing) *)
        (* Metabolic rate temperature coefficient modifier *)
        rFeedBaseRate := rBiomassEstimate * 0.02; (* Base parameter: 2% of total body weight *)
        IF rWaterTemp > 12.0 THEN
            rFeedRateCmd := rFeedBaseRate * 1.5; (* High metabolic mode *)
        ELSE
            rFeedRateCmd := rFeedBaseRate * 0.8; (* Low metabolic mode *)
        END_IF;

        tFeedCycle(IN := TRUE, PT := T#30M); (* Run precise 30-minute feed burst profile *)
        IF tFeedCycle.Q THEN
            tFeedCycle(IN := FALSE);
            rFeedRateCmd := 0.0;
            iState := 10;
        END_IF;

    99: (* FAULT / ESTOP STATE *)
        bSystemReady := FALSE;
        rBallastValveCmd := 0.0;
        rFeedRateCmd := 0.0;

        IF bEmergencyStop AND NOT bTensionFault THEN
            bAlarm := FALSE;
            iState := 0; (* Reset back to Init when safe *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
