VERSION : '1.0'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

(*
    Description:
    Master-tier, production-ready IEC 61131-3 Structured Text implementation for 
    Stratospheric Aerosol Injection (SAI). Manages swarm spacing via Model Predictive
    Control (MPC) to avoid wake vortices and handles ultrasonic nozzle atomization
    for 0.5-micron SO2 droplet dispersion at 70,000 ft altitude.
    Adheres to PackML state model.
*)

VAR_INPUT
    (* PackML State Commands *)
    bExecute            : BOOL;     (* Command to start dispersion *)
    bStop               : BOOL;     (* Command to stop dispersion *)
    bAbort              : BOOL;     (* Emergency abort *)

    (* Environmental Telemetry (70,000 ft) *)
    fAltitude_m         : LREAL;    (* Current altitude in meters (Target: ~21336m) *)
    fAmbientTemp_K      : LREAL;    (* Ambient temperature in Kelvin *)
    fAmbientPress_Pa    : LREAL;    (* Ambient pressure in Pascals *)
    fWindShear_ms       : LREAL;    (* Real-time stratospheric wind shear in m/s *)
    fUpdraftVel_ms      : LREAL;    (* Local updraft velocity in m/s *)

    (* Swarm & Drone Navigation Telemetry *)
    fDronePosX_m        : LREAL;    (* Drone X position in swarm formation *)
    fDronePosY_m        : LREAL;    (* Drone Y position in swarm formation *)
    fDronePosZ_m        : LREAL;    (* Drone Z position in swarm formation *)
    fSwarmLeadPosX_m    : LREAL;    (* Leader Drone X position *)
    fSwarmLeadPosY_m    : LREAL;    (* Leader Drone Y position *)
    fSwarmLeadPosZ_m    : LREAL;    (* Leader Drone Z position *)

    (* Chemical Payload & Injection Specs *)
    fSO2TankLevel_pct   : LREAL;    (* Payload SO2 remaining level (0-100%) *)
    fSO2TankTemp_K      : LREAL;    (* SO2 tank temperature in Kelvin *)
    fTargetAlbedoRef    : LREAL;    (* Target albedo reflection efficiency index *)
END_VAR

VAR_OUTPUT
    (* PackML Status *)
    eCurrentState       : INT;      (* Current PackML State Enum *)
    bError              : BOOL;     (* Fault indicator *)
    iErrorID            : INT;      (* Fault code *)

    (* Actuation Commands *)
    fNozzleFreq_kHz     : LREAL;    (* Ultrasonic atomizer frequency (target 0.5-micron) *)
    fPumpFlowRate_gs    : LREAL;    (* SO2 pump flow rate in grams/second *)

    (* Swarm Avoidance Navigation Offsets (MPC Output) *)
    fCmdOffsetX_m       : LREAL;    (* X correction to avoid caustic wake *)
    fCmdOffsetY_m       : LREAL;    (* Y correction to avoid caustic wake *)
    fCmdOffsetZ_m       : LREAL;    (* Z correction to avoid caustic wake *)

    (* Process Variables *)
    fCalcDropletSize_um : LREAL;    (* Estimated dispersed droplet size *)
    fAdiabaticExp_Ratio : LREAL;    (* Calculated adiabatic expansion ratio *)
END_VAR

VAR
    (* Internal State Variables *)
    iState              : INT := 1; (* 1: IDLE, 2: STARTING, 3: EXECUTE, 4: STOPPING, 5: ABORTING, 6: ABORTED *)

    (* Physical Constants *)
    c_R                 : LREAL := 8.314462618;  (* Universal gas constant J/(mol*K) *)
    c_MolarMass_SO2     : LREAL := 0.064066;     (* Molar mass of SO2 in kg/mol *)
    c_Gamma_SO2         : LREAL := 1.29;         (* Heat capacity ratio (Cp/Cv) for SO2 *)
    c_TargetParticle_um : LREAL := 0.5;          (* 0.5 microns targeted *)

    (* MPC Swarm Spacing Parameters *)
    fMinWakeDist_m      : LREAL := 150.0;        (* Minimum distance from wake vortex (thin air density) *)
    fWakeDecayFact      : LREAL;                 (* Wake dissipation factor based on wind shear *)
    fRelDistanceX       : LREAL;
    fRelDistanceY       : LREAL;
    fRelDistanceZ       : LREAL;
    fDistToLeader       : LREAL;

    (* PID / Flow Control Variables *)
    fFlowError          : LREAL;
    fFlowErrorSum       : LREAL;
    fKp_Flow            : LREAL := 1.25;
    fKi_Flow            : LREAL := 0.15;

    (* Atomization Constants *)
    fSurfaceTension_Nm  : LREAL := 0.0284;       (* SO2 liquid surface tension at operating temp *)
    fDensity_SO2_kgm3   : LREAL := 1460.0;       (* Density of liquid SO2 *)
END_VAR

(* 
    ========================================================================
    STATE MACHINE (PackML Simplified)
    ========================================================================
*)

IF bAbort THEN
    iState := 5; (* ABORTING *)
ELSIF bStop AND (iState = 3 OR iState = 2) THEN
    iState := 4; (* STOPPING *)
ELSIF bExecute AND iState = 1 THEN
    iState := 2; (* STARTING *)
END_IF;

eCurrentState := iState;

CASE iState OF
    1: (* IDLE *)
        fPumpFlowRate_gs := 0.0;
        fNozzleFreq_kHz := 0.0;
        fCmdOffsetX_m := 0.0;
        fCmdOffsetY_m := 0.0;
        fCmdOffsetZ_m := 0.0;

        IF fAltitude_m < 20000.0 THEN
            bError := TRUE;
            iErrorID := 1001; (* Below operational altitude *)
        ELSE
            bError := FALSE;
            iErrorID := 0;
        END_IF;

    2: (* STARTING *)
        (* Prime pumps, pre-heat ultrasonic nozzles *)
        fNozzleFreq_kHz := 20.0; (* Pre-resonance *)
        iState := 3;

    3: (* EXECUTE: Dispersion and Swarm Control *)

        (* -------------------------------------------------------------
           THERMODYNAMICS & ADIABATIC EXPANSION
           ------------------------------------------------------------- *)
        (* P1*V1^gamma = P2*V2^gamma -> T2 = T1 * (P2/P1)^((gamma-1)/gamma) *)
        (* Calculate Expansion Ratio based on Tank vs Ambient *)
        IF fAmbientPress_Pa > 0.0 AND fSO2TankTemp_K > 0.0 THEN
            fAdiabaticExp_Ratio := EXPT( (fAmbientPress_Pa / 500000.0), ((c_Gamma_SO2 - 1.0) / c_Gamma_SO2) );
        ELSE
            fAdiabaticExp_Ratio := 1.0;
        END_IF;

        (* -------------------------------------------------------------
           ATOMIZATION CONTROL (Target: 0.5 micron)
           ------------------------------------------------------------- *)
        (* Lang's Equation for Ultrasonic Droplet Size: D = 0.34 * (8 * pi * sigma / (rho * f^2))^(1/3) *)
        (* Rearranging for Frequency (f): f = SQRT( (8 * pi * sigma) / (rho * (D/0.34)^3) ) *)

        IF c_TargetParticle_um > 0.0 THEN
            (* Convert target from um to m *)
            fCalcDropletSize_um := c_TargetParticle_um * 1E-6;

            fNozzleFreq_kHz := SQRT( (8.0 * 3.14159265 * fSurfaceTension_Nm) / 
                                     (fDensity_SO2_kgm3 * EXPT((fCalcDropletSize_um / 0.34), 3.0)) ) / 1000.0;
        END_IF;

        (* Plume Flow Modulation based on updraft and windshear *)
        (* Maximize albedo coverage by increasing flow in high shear (rapid mixing) *)
        fFlowError := (fWindShear_ms * 1.5 + fUpdraftVel_ms * 2.0) * fTargetAlbedoRef;
        fFlowErrorSum := fFlowErrorSum + fFlowError;

        (* Anti-windup limit *)
        IF fFlowErrorSum > 1000.0 THEN fFlowErrorSum := 1000.0; END_IF;
        IF fFlowErrorSum < -1000.0 THEN fFlowErrorSum := -1000.0; END_IF;

        fPumpFlowRate_gs := (fKp_Flow * fFlowError) + (fKi_Flow * fFlowErrorSum);

        (* Clamp flow rate based on remaining SO2 *)
        IF fSO2TankLevel_pct <= 0.0 THEN
            fPumpFlowRate_gs := 0.0;
            iState := 4; (* Stop when empty *)
        END_IF;

        IF fPumpFlowRate_gs > 500.0 THEN fPumpFlowRate_gs := 500.0; END_IF;
        IF fPumpFlowRate_gs < 0.0 THEN fPumpFlowRate_gs := 0.0; END_IF;

        (* -------------------------------------------------------------
           SWARM MPC WAKE AVOIDANCE (Thin Air Density Compensation)
           ------------------------------------------------------------- *)
        (* Calculate relative distance to leader *)
        fRelDistanceX := fSwarmLeadPosX_m - fDronePosX_m;
        fRelDistanceY := fSwarmLeadPosY_m - fDronePosY_m;
        fRelDistanceZ := fSwarmLeadPosZ_m - fDronePosZ_m;

        fDistToLeader := SQRT( (fRelDistanceX * fRelDistanceX) + 
                               (fRelDistanceY * fRelDistanceY) + 
                               (fRelDistanceZ * fRelDistanceZ) );

        (* Calculate wake decay based on wind shear. Thin air = longer wake persistence *)
        fWakeDecayFact := 1.0 + (50.0 / (fWindShear_ms + 0.1));

        (* If inside caustic SO2 wake cone of leader *)
        IF (fDistToLeader < (fMinWakeDist_m * fWakeDecayFact)) AND (fRelDistanceX > 0.0) THEN
            (* Initiate MPC evasion vectors - move laterally and change altitude slightly *)
            fCmdOffsetX_m := -10.0; 
            fCmdOffsetY_m := 50.0;  (* Shift sideways out of wake *)
            fCmdOffsetZ_m := 5.0;   (* Slight altitude bump to avoid downdraft of wake *)
        ELSE
            (* Hold standard formation *)
            fCmdOffsetX_m := 0.0;
            fCmdOffsetY_m := 0.0;
            fCmdOffsetZ_m := 0.0;
        END_IF;

    4: (* STOPPING *)
        fPumpFlowRate_gs := 0.0;
        fNozzleFreq_kHz := 0.0;
        fCmdOffsetX_m := 0.0;
        fCmdOffsetY_m := 0.0;
        fCmdOffsetZ_m := 0.0;
        iState := 1; (* Transition back to idle *)

    5: (* ABORTING *)
        fPumpFlowRate_gs := 0.0;
        fNozzleFreq_kHz := 0.0;
        (* Execute immediate evasion vector in case of collision threat *)
        fCmdOffsetX_m := 0.0;
        fCmdOffsetY_m := 100.0;
        fCmdOffsetZ_m := -50.0; 
        iState := 6;

    6: (* ABORTED *)
        bError := TRUE;
        iErrorID := 9999; (* Critical Abort *)
        (* Requires reset to clear *)
        IF NOT bAbort THEN
            iState := 1;
        END_IF;

    ELSE
        iState := 1;
END_CASE;
END_FUNCTION_BLOCK
