FUNCTION_BLOCK FB_RingSpinningFrame_Master
TITLE = 'High-Speed Textile Ring Spinning Frame Control'
VERSION : '2.1'

VAR_INPUT
    bEnableDrive          : BOOL;  // System Enable
    bStartSpinning        : BOOL;  // Start production cycle
    bEmergencyStop        : BOOL;  // E-Stop active low
    bAcknowledgeDoff      : BOOL;  // Operator ack for doffing
    fTargetYarnCount_Tex  : REAL;  // Yarn count in Tex
    fTotalDraftRatio      : REAL;  // Total drafting ratio (e.g., 30.0 - 50.0)
    fSpindleSpeedTarget   : REAL;  // Spindle speed setpoint [RPM] (e.g., 20000)
    fRingDiameter         : REAL;  // Ring diameter [mm]
    fBobbinHeight         : REAL;  // Total bobbin height [mm]
    fTravelerWeight       : REAL;  // Traveler ISO weight
END_VAR

VAR_OUTPUT
    fRefSpindleMainDrive  : REAL;  // Spindle tangential belt drive ref [RPM]
    fRefFrontRollerDrive  : REAL;  // Front drafting roller speed ref [RPM]
    fRefMiddleRollerDrive : REAL;  // Middle drafting roller speed ref [RPM]
    fRefBackRollerDrive   : REAL;  // Back drafting roller speed ref [RPM]
    fRefRingRailServoPos  : REAL;  // Ring rail servo position command [mm]
    fRefRingRailServoVel  : REAL;  // Ring rail servo velocity command [mm/s]

    bOutDofferGripper     : BOOL;  // Doffer arm gripper actuate
    bOutDofferScissors    : BOOL;  // Yarn cutting scissors actuate
    bOutPegTrayConveyor   : BOOL;  // Peg tray conveyor advance

    nSystemState          : INT;   // Current state machine step
    bSystemFault          : BOOL;  // General fault flag
    bCopFull              : BOOL;  // Cop is fully built
END_VAR

VAR
    eState : (STATE_IDLE, STATE_RAMP_UP, STATE_SPINNING, STATE_COP_BUILD, STATE_PRE_DOFF, STATE_DOFFING, STATE_FAULT) := STATE_IDLE;
    fCurrentSpindleSpeed  : REAL := 0.0;
    fCurrentRailPos       : REAL := 0.0;
    fRailTraverseStroke   : REAL := 45.0; // Chase length
    fRailBasePos          : REAL := 0.0;
    fDeliverySpeed        : REAL; // Delivery speed in m/min
    fDraftingConstant     : REAL := 3.14159 * 27.0 / 1000.0; // Roller diameter math
    tDoffingTimer         : TON;
    fRampRate             : REAL := 500.0; // RPM/s
END_VAR

// Implementation
IF NOT bEmergencyStop THEN
    eState := STATE_FAULT;
    bSystemFault := TRUE;
END_IF;

// Kinematic and Process calculations
// Delivery speed (m/min) = SpindleSpeed / TwistMultiplier (approx)
fDeliverySpeed := fTargetYarnCount_Tex * 0.1 * (fCurrentSpindleSpeed / 1000.0);
fRefFrontRollerDrive := fDeliverySpeed / fDraftingConstant;
fRefBackRollerDrive := fRefFrontRollerDrive / fTotalDraftRatio;
fRefMiddleRollerDrive := fRefBackRollerDrive * 1.2; // Break draft factor

CASE eState OF
    STATE_IDLE:
        fCurrentSpindleSpeed := 0.0;
        fRefRingRailServoVel := 0.0;
        bOutDofferGripper := FALSE;
        IF bEnableDrive AND bStartSpinning THEN
            eState := STATE_RAMP_UP;
            bSystemFault := FALSE;
            bCopFull := FALSE;
        END_IF;

    STATE_RAMP_UP:
        // Ramping spindle speed
        IF fCurrentSpindleSpeed < fSpindleSpeedTarget THEN
            fCurrentSpindleSpeed := fCurrentSpindleSpeed + (fRampRate * 0.01); // Assuming 10ms cycle
        ELSE
            fCurrentSpindleSpeed := fSpindleSpeedTarget;
            eState := STATE_COP_BUILD;
        END_IF;

    STATE_COP_BUILD:
        // Winding kinematics (Cop building motion)
        // Complex ring rail profile: combined base movement and traverse movement
        fRailBasePos := fRailBasePos + 0.005; // Base shift per cycle
        IF fRailBasePos > (fBobbinHeight - fRailTraverseStroke) THEN
            bCopFull := TRUE;
            eState := STATE_PRE_DOFF;
        END_IF;
        // Simplified triangular traverse profile calculation
        fCurrentRailPos := fRailBasePos + (fRailTraverseStroke * ABS(SIN(fRailBasePos * 0.5)));
        fRefRingRailServoPos := fCurrentRailPos;
        fRefRingRailServoVel := 15.0; // Traverse speed

    STATE_PRE_DOFF:
        // Underwinding sequence
        fCurrentSpindleSpeed := fCurrentSpindleSpeed - (fRampRate * 0.05);
        IF fCurrentSpindleSpeed <= 0.0 THEN
            fCurrentSpindleSpeed := 0.0;
            IF bAcknowledgeDoff THEN
                eState := STATE_DOFFING;
            END_IF;
        END_IF;

    STATE_DOFFING:
        tDoffingTimer(IN := TRUE, PT := T#15S);
        IF tDoffingTimer.ET < T#3S THEN
            bOutDofferGripper := TRUE;
        ELSIF tDoffingTimer.ET < T#5S THEN
            bOutDofferScissors := TRUE;
        ELSIF tDoffingTimer.ET < T#10S THEN
            bOutPegTrayConveyor := TRUE;
        ELSE
            bOutDofferGripper := FALSE;
            bOutDofferScissors := FALSE;
            bOutPegTrayConveyor := FALSE;
            tDoffingTimer(IN := FALSE);
            fRailBasePos := 0.0;
            eState := STATE_IDLE;
        END_IF;

    STATE_FAULT:
        fCurrentSpindleSpeed := 0.0;
        fRefFrontRollerDrive := 0.0;
        fRefMiddleRollerDrive := 0.0;
        fRefBackRollerDrive := 0.0;
END_CASE;

fRefSpindleMainDrive := fCurrentSpindleSpeed;
nSystemState := eState;

END_FUNCTION_BLOCK
