    (* Historical arrays or moving averages for acoustic logic *)
    rAcousticAcc            : REAL := 0.0;
    bStallImminent          : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlocks Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAcousticAlarm := TRUE;
    bThermalInterlock := TRUE;
    rThrustVectorCmd_X := 0.0;
    rThrustVectorCmd_Y := 0.0;
    rCompressorStallMargin := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* 2. Thermal Conditioning Logic *)
IF rCryoFuelTemp_C < -150.0 THEN
    bThermalInterlock := FALSE; (* Safe to operate *)
ELSE
    bThermalInterlock := TRUE;
END_IF;

(* 3. Active Acoustic Monitoring for Transient Stall Detection *)
IF rAcousticVibration_g > 15.0 THEN
    tAcousticFilterTimer(IN := TRUE, PT := T#50MS);
    IF tAcousticFilterTimer.Q THEN
        bAcousticAlarm := TRUE;
        bStallImminent := TRUE;
    END_IF;
ELSE
    tAcousticFilterTimer(IN := FALSE, PT := T#50MS);
    bStallImminent := FALSE;
END_IF;

(* 4. State Machine for Thrust Vectoring and Load Measurement Profile *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := NOT bThermalInterlock AND NOT bAcousticAlarm;
        IF bEnable AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: (* ACCELERATION PROFILE *)
        rThrustVectorCmd_X := rN1_FanSpeedRPM * 0.05;
        rThrustVectorCmd_Y := rN2_CoreSpeedRPM * 0.02;

        IF rN1_FanSpeedRPM > 3000.0 THEN
            iState := 20;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* STEADY STATE ACOUSTIC ANALYSIS *)
        (* Calculate theoretical pressure ratio approximation *)
        rPressureRatio := rCompressorDischargeP_kPa / 101.325;
        rTempCorrection := (rInletAirTemp_C + 273.15) / 288.15;

        (* Complex active stall margin calculation based on empirical map *)
        rCompressorStallMargin := rBaseStallMargin - (rPressureRatio * rTempCorrection) + (rN2_CoreSpeedRPM * 0.001);

        IF bStallImminent OR rCompressorStallMargin < 5.0 THEN
            rCompressorStallMargin := 0.0;
            bAcousticAlarm := TRUE;
            iState := 99; (* Emergency Run-Down *)
        END_IF;

        tTestTimer(IN := TRUE, PT := T#120S);
        IF tTestTimer.Q THEN
            tTestTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* NORMAL DECELERATION *)
        rThrustVectorCmd_X := rThrustVectorCmd_X * 0.95;
        rThrustVectorCmd_Y := rThrustVectorCmd_Y * 0.95;

        IF rN1_FanSpeedRPM < 500.0 THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        rThrustVectorCmd_X := 0.0;
        rThrustVectorCmd_Y := 0.0;
        IF NOT bEnable THEN
            iState := 0;
            bAcousticAlarm := FALSE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
