FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    rTemp_Indoor : REAL; (* Celsius *)
    rRH_Indoor : REAL; (* Relative Humidity % *)
    rLightIntensity : REAL; (* PAR umol/m2/s *)
    rWaterTemp : REAL; (* Celsius *)
    rCurrentPH : REAL; 
    rCurrentEC : REAL; (* mS/cm *)
    bSystemEnable : BOOL;
    rCO2_Level : REAL; (* ppm *)
END_VAR

VAR_OUTPUT
    bPumpNutrientA : BOOL;
    bPumpNutrientB : BOOL;
    bPumpMicro : BOOL;
    bPumpPHUp : BOOL;
    bPumpPHDown : BOOL;
    rTargetVPD : REAL;
    bHumidifier : BOOL;
    bDehumidifier : BOOL;
    bCoolingEnable : BOOL;
    bHeatingEnable : BOOL;
    bGrowLights : BOOL;
    bCO2Generator : BOOL;
END_VAR

VAR
    rSVP : REAL; (* Saturation Vapor Pressure *)
    rAVP : REAL; (* Actual Vapor Pressure *)
    rCurrentVPD : REAL;
    rVPD_SP : REAL := 1.0; (* 1.0 kPa target *)
    rVPD_Deadband : REAL := 0.1;

    rPH_SP : REAL := 5.8;
    rPH_Deadband : REAL := 0.2;
    rEC_SP : REAL := 2.2;
    rEC_Deadband : REAL := 0.1;
    rCO2_SP : REAL := 1200.0;
    rCO2_Deadband : REAL := 50.0;

    T_Dose_Interval : TON;
    bCanDose : BOOL := TRUE;
    rPulseDuration : TIME := T#5S;

    state : INT := 0;
    bInit : BOOL := FALSE;
END_VAR

(* Calculate Vapor Pressure Deficit (VPD) *)
(* SVP formula approximation (Tetens equation) *)
rSVP := 0.61078 * EXP((17.27 * rTemp_Indoor) / (rTemp_Indoor + 237.3));
rAVP := rSVP * (rRH_Indoor / 100.0);
rCurrentVPD := rSVP - rAVP;

(* Determine VPD control actions *)
IF bSystemEnable THEN
    IF rCurrentVPD > (rVPD_SP + rVPD_Deadband) THEN
        bHumidifier := TRUE;
        bDehumidifier := FALSE;
    ELSIF rCurrentVPD < (rVPD_SP - rVPD_Deadband) THEN
        bHumidifier := FALSE;
        bDehumidifier := TRUE;
    ELSE
        bHumidifier := FALSE;
        bDehumidifier := FALSE;
    END_IF;

    (* Dosing Logic Cascades - Time-based Pulse Width *)
    T_Dose_Interval(IN := NOT T_Dose_Interval.Q, PT := T#5M);

    IF T_Dose_Interval.Q THEN
        bCanDose := TRUE;
    END_IF;

    bPumpNutrientA := FALSE;
    bPumpNutrientB := FALSE;
    bPumpMicro := FALSE;
    bPumpPHUp := FALSE;
    bPumpPHDown := FALSE;

    IF bCanDose THEN
        (* Priority 1: pH Control *)
        IF rCurrentPH < (rPH_SP - rPH_Deadband) THEN
            bPumpPHUp := TRUE;
            bCanDose := FALSE;
        ELSIF rCurrentPH > (rPH_SP + rPH_Deadband) THEN
            bPumpPHDown := TRUE;
            bCanDose := FALSE;
        (* Priority 2: EC/Nutrient Control *)
        ELSIF rCurrentEC < (rEC_SP - rEC_Deadband) THEN
            bPumpNutrientA := TRUE;
            bPumpNutrientB := TRUE;
            bPumpMicro := TRUE;
            bCanDose := FALSE;
        END_IF;
    END_IF;

    (* Multi-zone precision photoperiod pulsing and CO2 *)
    IF rLightIntensity < 800.0 THEN
        bGrowLights := TRUE;
        IF rCO2_Level < (rCO2_SP - rCO2_Deadband) THEN
            bCO2Generator := TRUE;
        ELSE
            bCO2Generator := FALSE;
        END_IF;
    ELSE
        bGrowLights := FALSE;
        bCO2Generator := FALSE; (* Turn off CO2 during dark period *)
    END_IF;
ELSE
    bHumidifier := FALSE;
    bDehumidifier := FALSE;
    bPumpNutrientA := FALSE;
    bPumpNutrientB := FALSE;
    bPumpMicro := FALSE;
    bPumpPHUp := FALSE;
    bPumpPHDown := FALSE;
    bGrowLights := FALSE;
    bCO2Generator := FALSE;
END_IF;
END_FUNCTION_BLOCK
