FUNCTION_BLOCK FB_HypersonicBlowdownTunnel
TITLE = 'Mach 7+ Blowdown Fast-Acting Valve & Schlieren Sync'
// ==============================================================================
// Function Block: FB_HypersonicBlowdownTunnel
// Description: Advanced Hypersonic Blowdown Wind Tunnel Control.
// Manages fast-acting valve sequencing, Mach 7+ stagnation pressure regulation,
// and high-speed Schlieren imaging synchronization.
// ==============================================================================

VAR_INPUT
    bStartSequence         : BOOL; // Initiate the blowdown sequence
    bEmergencyStop         : BOOL; // E-Stop command
    rTargetStagnationPress : REAL; // Target Stagnation Pressure (kPa)
    rTargetMachNumber      : REAL; // Target Mach Number (e.g., 7.0)
    rReservoirPressure     : REAL; // Current Storage Reservoir Pressure (kPa)
    rTestSectionStatic     : REAL; // Current Test Section Static Pressure (kPa)
    rStagnationTemp        : REAL; // Stagnation Temperature (K)
    bVacuumSystemReady     : BOOL; // Vacuum sphere pressure acceptable
END_VAR

VAR_OUTPUT
    bSystemReady           : BOOL; // System is primed and ready
    bTestInProgress        : BOOL; // Active blowdown phase
    bSchlierenTrigger      : BOOL; // Trigger for high-speed camera (100kHz)
    bLaserPulseSync        : BOOL; // Laser pulse sync for PIV/Schlieren
    rMainValveCmd          : REAL; // Analog command to Fast-Acting Valve (0-100%)
    rEjectorValveCmd       : REAL; // Ejector system valve command (0-100%)
    nState                 : INT;  // Current State Machine Step
    sStatusMsg             : STRING[64]; // Status description
    bError                 : BOOL; // Error flag
END_VAR

VAR
    // Internal State Machine
    eState : (
        STATE_IDLE := 0,
        STATE_PRIMING := 10,
        STATE_IGNITION_HEATER := 20,
        STATE_EJECTOR_START := 30,
        STATE_MAIN_VALVE_OPEN := 40,
        STATE_REGULATION := 50,
        STATE_SHUTDOWN := 60,
        STATE_ERROR := 99
    );

    // Timers
    tHeaterWarmup          : TON;
    tBlowdownDuration      : TON;
    tValveRamp             : TON;

    // PID Controller for Stagnation Pressure
    rKp                    : REAL := 2.5;
    rKi                    : REAL := 0.8;
    rKd                    : REAL := 0.05;
    rPressError            : REAL;
    rPressErrorPrev        : REAL;
    rPressIntegral         : REAL;
    rPressDerivative       : REAL;

    // Constants
    MAX_TEST_DURATION      : TIME := T#250ms; // Ultra-short duration for Mach 7 blowdown
    HEATER_TIME            : TIME := T#5s;

    // Internal flags
    bHeaterReady           : BOOL;
    bRegulating            : BOOL;
    nPulseCounter          : DINT;
END_VAR

// ------------------------------------------------------------------------------
// Emergency Stop Handling
// ------------------------------------------------------------------------------
IF bEmergencyStop THEN
    eState := STATE_ERROR;
    sStatusMsg := 'E-STOP ACTIVATED. ALL VALVES CLOSED.';
    rMainValveCmd := 0.0;
    rEjectorValveCmd := 0.0;
    bSchlierenTrigger := FALSE;
    bLaserPulseSync := FALSE;
    bTestInProgress := FALSE;
    bError := TRUE;
    RETURN;
END_IF

// ------------------------------------------------------------------------------
// Main State Machine
// ------------------------------------------------------------------------------
CASE eState OF

    STATE_IDLE:
        bTestInProgress := FALSE;
        bSchlierenTrigger := FALSE;
        bLaserPulseSync := FALSE;
        rMainValveCmd := 0.0;
        rEjectorValveCmd := 0.0;
        bError := FALSE;

        IF rReservoirPressure > (rTargetStagnationPress * 1.5) AND bVacuumSystemReady THEN
            bSystemReady := TRUE;
            sStatusMsg := 'IDLE: System Ready for Blowdown';
        ELSE
            bSystemReady := FALSE;
            sStatusMsg := 'IDLE: Waiting for Reservoir or Vacuum';
        END_IF

        IF bStartSequence AND bSystemReady THEN
            eState := STATE_PRIMING;
            sStatusMsg := 'PRIMING: Initiating Sequence';
        END_IF

    STATE_PRIMING:
        bTestInProgress := TRUE;
        bSystemReady := FALSE;
        // Pre-arm diagnostics
        IF bVacuumSystemReady THEN
            eState := STATE_IGNITION_HEATER;
            sStatusMsg := 'HEATING: Activating Stagnation Heater';
        ELSE
            eState := STATE_ERROR;
            sStatusMsg := 'ERROR: Vacuum lost during prime';
        END_IF

    STATE_IGNITION_HEATER:
        tHeaterWarmup(IN:=TRUE, PT:=HEATER_TIME);
        IF tHeaterWarmup.Q THEN
            bHeaterReady := TRUE;
            tHeaterWarmup(IN:=FALSE);
            eState := STATE_EJECTOR_START;
            sStatusMsg := 'EJECTOR: Starting exhaust ejectors';
        END_IF

    STATE_EJECTOR_START:
        rEjectorValveCmd := 100.0; // Fully open ejectors
        IF rTestSectionStatic < 1.0 THEN // Vacuum established in test section (kPa)
            eState := STATE_MAIN_VALVE_OPEN;
            sStatusMsg := 'MAIN VALVE: Initiating fast opening';
        END_IF

    STATE_MAIN_VALVE_OPEN:
        // Burst logic for fast-acting valve (approx 10-20ms to open)
        // Set initial feedforward command
        rMainValveCmd := 85.0; 
        IF rStagnationTemp > 800.0 THEN // Confirm enthalpy
            bSchlierenTrigger := TRUE; // Start cameras before flow hits test section
            eState := STATE_REGULATION;
            sStatusMsg := 'REGULATING: Active Blowdown Phase';
        END_IF

    STATE_REGULATION:
        tBlowdownDuration(IN:=TRUE, PT:=MAX_TEST_DURATION);

        // High-speed PID for Stagnation Pressure Regulation
        rPressError := rTargetStagnationPress - rReservoirPressure; // Simplified model
        rPressIntegral := rPressIntegral + (rPressError * 0.001); // Assumes 1ms task cycle
        rPressDerivative := (rPressError - rPressErrorPrev) / 0.001;

        rMainValveCmd := (rKp * rPressError) + (rKi * rPressIntegral) + (rKd * rPressDerivative) + 50.0; // 50% base feedforward

        // Clamp output
        IF rMainValveCmd > 100.0 THEN
            rMainValveCmd := 100.0;
        ELSIF rMainValveCmd < 0.0 THEN
            rMainValveCmd := 0.0;
        END_IF

        rPressErrorPrev := rPressError;

        // Laser Pulse Sync generation (100kHz simulation logic)
        nPulseCounter := nPulseCounter + 1;
        IF (nPulseCounter MOD 10) = 0 THEN
            bLaserPulseSync := NOT bLaserPulseSync;
        END_IF

        IF tBlowdownDuration.Q THEN
            eState := STATE_SHUTDOWN;
            tBlowdownDuration(IN:=FALSE);
            sStatusMsg := 'SHUTDOWN: Test Complete';
        END_IF

    STATE_SHUTDOWN:
        rMainValveCmd := 0.0;
        bSchlierenTrigger := FALSE;
        bLaserPulseSync := FALSE;

        IF rReservoirPressure < 100.0 THEN
            rEjectorValveCmd := 0.0;
            bTestInProgress := FALSE;
            eState := STATE_IDLE;
        END_IF

    STATE_ERROR:
        rMainValveCmd := 0.0;
        rEjectorValveCmd := 0.0;
        bSchlierenTrigger := FALSE;
        bLaserPulseSync := FALSE;
        bError := TRUE;
        bTestInProgress := FALSE;
        // Requires manual reset

END_CASE

nState := eState;
END_FUNCTION_BLOCK
