FUNCTION_BLOCK FB_AeroEngineTestCell
TITLE = 'Aircraft Engine Test Cell Control and Data Acquisition'
VERSION : '1.0'

VAR_INPUT
    rThrust_Raw_kN : REAL; (* Dynamometer raw thrust signal from load cells *)
    rFuelMassFlow_kg_s : REAL; (* Coriolis mass flow meter signal for Jet-A1 *)
    rInletAirTemp_K : REAL; (* T2 engine inlet temperature *)
    rInletAirPress_kPa : REAL; (* P2 engine inlet pressure *)
    rExhaustGasTemp_C : REAL; (* EGT / T4.5 Turbine Exhaust Gas Temperature *)
    rCoreSpeed_N2_rpm : REAL; (* High pressure spool speed (N2) *)
    rFanSpeed_N1_rpm : REAL; (* Low pressure spool speed (N1) *)
    rOilPress_kPa : REAL; (* Main engine oil pressure *)
    rOilTemp_C : REAL; (* Main engine oil temperature *)
    bEmergencyStop : BOOL; (* ESTOP signal from test cell control room *)
    bFireDetected : BOOL; (* UV/IR fire detection system active *)
    rEnclosureTemp_C : REAL; (* Acoustic enclosure ambient temperature *)
    bTestInitiate : BOOL; (* Operator push button to start recording *)
END_VAR

VAR_OUTPUT
    rCorrectedThrust_kN : REAL; (* Thrust corrected to standard day conditions *)
    rSpecificFuelConsumption : REAL; (* SFC in kg/(s*kN) *)
    rCorrectedCoreSpeed_N2_rpm : REAL; (* N2 corrected to standard day *)
    rCorrectedFanSpeed_N1_rpm : REAL; (* N1 corrected to standard day *)
    bTestCellAbort : BOOL; (* Abort signal to Engine ECU and facility *)
    bVentilationFanEnable : BOOL; (* Enclosure cooling fan start/stop *)
    rVentilationDamperPos : REAL; (* Damper position command 0.0 to 100.0% *)
    bFuelShutoffValve : BOOL; (* Facility fuel isolation valve command *)
    bDataLoggingActive : BOOL; (* High speed DAQ trigger *)
    rEngineRunTimer_s : REAL; (* Total test duration in seconds *)
    bWarningEnclosureTemp : BOOL; (* High enclosure temperature alarm *)
    bWarningEGT : BOOL; (* High Exhaust Gas Temperature alarm *)
    bWarningOilPress : BOOL; (* Low oil pressure alarm *)
    iTestPhase : INT; (* 0=Idle, 1=Takeoff, 2=Cruise, 3=Cool-down, 99=Fault *)
END_VAR

VAR
    rStdTemp_K : REAL := 288.15; (* Standard Day ISA Temperature *)
    rStdPress_kPa : REAL := 101.325; (* Standard Day ISA Pressure *)
    rTheta2 : REAL; (* Temperature correction factor *)
    rDelta2 : REAL; (* Pressure correction factor *)
    rSqrtTheta2 : REAL; (* Square root of Theta2 for speed correction *)
    rThrustFilter : REAL := 0.0;
    rAlpha : REAL := 0.15; (* Low pass filter coefficient for thrust *)
    bActiveTest : BOOL := FALSE;
    fEnclTempLimit_C : REAL := 65.0; (* Maximum allowed enclosure temp *)
    fEGTLimit_C : REAL := 950.0; (* Redline EGT limit *)
    fMinOilPress_kPa : REAL := 250.0; (* Minimum required oil pressure at idle *)
END_VAR

(* ===================================================================== *)
(* SAFETY INTERLOCKS AND FAULT MANAGEMENT                                *)
(* ===================================================================== *)
IF bEmergencyStop OR bFireDetected THEN
    bTestCellAbort := TRUE;
    bFuelShutoffValve := FALSE; (* Close facility fuel supply immediately *)
    bVentilationFanEnable := TRUE; (* Max ventilation to clear potential fumes/fire suppressants *)
    rVentilationDamperPos := 100.0;
    bActiveTest := FALSE;
    bDataLoggingActive := FALSE;
    iTestPhase := 99; (* Fault State *)
    RETURN; (* Halt further processing during critical safety event *)
END_IF;

(* Equipment Health Monitoring *)
IF rExhaustGasTemp_C > fEGTLimit_C THEN
    bWarningEGT := TRUE;
ELSE
    bWarningEGT := FALSE;
END_IF;

IF rOilPress_kPa < fMinOilPress_kPa AND rCoreSpeed_N2_rpm > 1000.0 THEN
    bWarningOilPress := TRUE;
ELSE
    bWarningOilPress := FALSE;
END_IF;

(* Automatic abort on critical engine health parameters *)
IF bWarningEGT OR bWarningOilPress THEN
    bTestCellAbort := TRUE;
    iTestPhase := 99;
ELSE
    bTestCellAbort := FALSE;
END_IF;

(* ===================================================================== *)
(* AERODYNAMIC AND THERMODYNAMIC CORRECTIONS                             *)
(* ===================================================================== *)
(* Calculate Theta (Temperature ratio) and Delta (Pressure ratio) per SAE AS681 *)
IF rInletAirTemp_K > 0.0 AND rInletAirPress_kPa > 0.0 THEN
    rTheta2 := rInletAirTemp_K / rStdTemp_K;
    rDelta2 := rInletAirPress_kPa / rStdPress_kPa;

    (* Protect against negative square root *)
    IF rTheta2 > 0.0 THEN
        rSqrtTheta2 := SQRT(rTheta2);
    ELSE
        rSqrtTheta2 := 1.0;
    END_IF;
ELSE
    rTheta2 := 1.0;
    rDelta2 := 1.0;
    rSqrtTheta2 := 1.0;
END_IF;

(* Low Pass Filter on raw thrust to reduce dynamic load cell noise *)
rThrustFilter := (rAlpha * rThrust_Raw_kN) + ((1.0 - rAlpha) * rThrustFilter);

(* Calculate Corrected Thrust: F_corr = F_raw / Delta2 *)
IF rDelta2 > 0.0 THEN
    rCorrectedThrust_kN := rThrustFilter / rDelta2;
ELSE
    rCorrectedThrust_kN := 0.0;
END_IF;

(* Calculate Corrected Speeds: N_corr = N_raw / sqrt(Theta2) *)
rCorrectedCoreSpeed_N2_rpm := rCoreSpeed_N2_rpm / rSqrtTheta2;
rCorrectedFanSpeed_N1_rpm := rFanSpeed_N1_rpm / rSqrtTheta2;

(* ===================================================================== *)
(* PERFORMANCE METRICS                                                   *)
(* ===================================================================== *)
(* Specific Fuel Consumption (SFC) Calculation *)
IF rCorrectedThrust_kN > 5.0 THEN
    (* SFC = Fuel Flow / Corrected Thrust *)
    rSpecificFuelConsumption := rFuelMassFlow_kg_s / rCorrectedThrust_kN;
    bActiveTest := TRUE;
ELSE
    rSpecificFuelConsumption := 0.0;
    bActiveTest := FALSE;
END_IF;

(* ===================================================================== *)
(* TEST CELL FACILITY CONTROL                                            *)
(* ===================================================================== *)
(* Acoustic Enclosure Ventilation Logic based on ambient heat rejection *)
IF rEnclosureTemp_C > fEnclTempLimit_C THEN
    bWarningEnclosureTemp := TRUE;
    bVentilationFanEnable := TRUE;
    rVentilationDamperPos := 100.0;
ELSIF rEnclosureTemp_C > (fEnclTempLimit_C - 20.0) THEN
    bWarningEnclosureTemp := FALSE;
    bVentilationFanEnable := TRUE;
    (* Modulate damper proportionally from 30% to 100% over the 20 deg C band *)
    rVentilationDamperPos := 30.0 + ((rEnclosureTemp_C - (fEnclTempLimit_C - 20.0)) / 20.0) * 70.0;
ELSE
    bWarningEnclosureTemp := FALSE;
    bVentilationFanEnable := FALSE;
    rVentilationDamperPos := 10.0; (* Minimum purge position for safety *)
END_IF;

(* Fuel Isolation Valve Enable condition - Requires no aborts and active test command *)
IF NOT bTestCellAbort AND bTestInitiate THEN
    bFuelShutoffValve := TRUE;
    bDataLoggingActive := TRUE;
    IF iTestPhase = 0 THEN
        iTestPhase := 1; (* Transition from idle to active testing *)
    END_IF;
ELSE
    bFuelShutoffValve := FALSE;
    bDataLoggingActive := FALSE;
    IF iTestPhase <> 99 THEN
        iTestPhase := 0;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
