FUNCTION_BLOCK FB_VAR_Furnace_Control
TITLE = 'Vacuum Arc Remelting Furnace Core Control'
VERSION : '1.5'

VAR_INPUT
    bEnable                 : BOOL; // System Master Enable
    bEmergencyStop          : BOOL; // E-Stop Active Low
    rTargetMeltRate         : REAL; // kg/min target melt rate
    rArcVoltageAct          : REAL; // Actual arc voltage (V)
    rArcCurrentAct          : REAL; // Actual arc current (A)
    rCrucibleTemp           : REAL; // Crucible wall temperature (C)
    rVacuumLevelAct         : REAL; // Chamber vacuum level (mBar)
    rElectrodeWeightAct     : REAL; // Current weight of consumable electrode (kg)
    rCoolingWaterFlowIn     : REAL; // L/min
    bHeliumInjectEnable     : BOOL; 
END_VAR

VAR_OUTPUT
    rArcCurrentSetpoint     : REAL; // Command to power supply (A)
    rElectrodeDriveSpeed    : REAL; // Command to Z-axis drive (mm/min)
    bMagneticStirrerEnable  : BOOL; 
    rMagneticStirrerFreq    : REAL; // Hz
    bHeliumValveCmd         : BOOL; // Open/close helium cooling valve
    rHeliumFlowSetpoint     : REAL; // L/min
    bSystemFault            : BOOL; // Global fault flag
    iFaultCode              : INT;  // Specific fault code
END_VAR

VAR
    rPrevElectrodeWeight    : REAL;
    tLastWeightSample       : TIME;
    rCalculatedMeltRate     : REAL; // kg/min

    rMeltRateError          : REAL;
    rMeltRateIntegral       : REAL;
    rMeltRateDerivative     : REAL;
    rPrevMeltRateError      : REAL;
    rKp_Melt                : REAL := 15.5;
    rKi_Melt                : REAL := 2.1;
    rKd_Melt                : REAL := 0.5;

    rGapVoltageTarget       : REAL := 25.0; // V
    rGapError               : REAL;
    rGapIntegral            : REAL;
    rKp_Gap                 : REAL := 5.0;
    rKi_Gap                 : REAL := 0.8;

    tonWeightSample         : TON;
    tonStirrerCycle         : TON;

    eState                  : INT;
    STATE_IDLE              : INT := 0;
    STATE_PUMPDOWN          : INT := 10;
    STATE_STRIKE_ARC        : INT := 20;
    STATE_MELTING           : INT := 30;
    STATE_HOT_TOPPING       : INT := 40;
    STATE_COOLING           : INT := 50;
    STATE_FAULT             : INT := 99;
END_VAR

VAR CONSTANT
    WEIGHT_SAMPLE_RATE      : TIME := T#1S;
    MAX_ARC_CURRENT         : REAL := 15000.0; 
    MIN_VACUUM_LEVEL        : REAL := 1.0E-3; 
END_VAR

IF NOT bEmergencyStop THEN
    eState := STATE_FAULT;
    iFaultCode := 1001; 
    bSystemFault := TRUE;
END_IF;

IF rCoolingWaterFlowIn < 50.0 AND eState >= STATE_STRIKE_ARC AND eState <= STATE_HOT_TOPPING THEN
    eState := STATE_FAULT;
    iFaultCode := 2001; 
    bSystemFault := TRUE;
END_IF;

tonWeightSample(IN := bEnable AND NOT tonWeightSample.Q, PT := WEIGHT_SAMPLE_RATE);
IF tonWeightSample.Q THEN
    rCalculatedMeltRate := (rPrevElectrodeWeight - rElectrodeWeightAct) * 60.0;
    rPrevElectrodeWeight := rElectrodeWeightAct;
END_IF;

CASE eState OF
    STATE_IDLE:
        rArcCurrentSetpoint := 0.0;
        rElectrodeDriveSpeed := 0.0;
        bMagneticStirrerEnable := FALSE;
        bHeliumValveCmd := FALSE;
        IF bEnable AND rVacuumLevelAct > MIN_VACUUM_LEVEL THEN
            eState := STATE_PUMPDOWN;
        ELSIF bEnable THEN
            eState := STATE_STRIKE_ARC;
        END_IF;

    STATE_PUMPDOWN:
        IF rVacuumLevelAct <= MIN_VACUUM_LEVEL THEN
            eState := STATE_STRIKE_ARC;
        END_IF;

    STATE_STRIKE_ARC:
        rArcCurrentSetpoint := 2000.0; 
        rElectrodeDriveSpeed := -5.0;  
        IF rArcVoltageAct < 35.0 AND rArcVoltageAct > 15.0 THEN
            eState := STATE_MELTING;
            rMeltRateIntegral := 0.0;
            rGapIntegral := 0.0;
        END_IF;

    STATE_MELTING:
        rMeltRateError := rTargetMeltRate - rCalculatedMeltRate;
        rMeltRateIntegral := rMeltRateIntegral + (rMeltRateError * 1.0); 
        rMeltRateDerivative := (rMeltRateError - rPrevMeltRateError) / 1.0;
        rPrevMeltRateError := rMeltRateError;

        rArcCurrentSetpoint := (rKp_Melt * rMeltRateError) + (rKi_Melt * rMeltRateIntegral) + (rKd_Melt * rMeltRateDerivative);

        IF rArcCurrentSetpoint > MAX_ARC_CURRENT THEN
            rArcCurrentSetpoint := MAX_ARC_CURRENT;
        ELSIF rArcCurrentSetpoint < 1000.0 THEN
            rArcCurrentSetpoint := 1000.0;
        END_IF;

        rGapError := rArcVoltageAct - rGapVoltageTarget;
        rGapIntegral := rGapIntegral + (rGapError * 1.0);
        rElectrodeDriveSpeed := (rKp_Gap * rGapError) + (rKi_Gap * rGapIntegral);

        tonStirrerCycle(IN := NOT tonStirrerCycle.Q, PT := T#10S);
        bMagneticStirrerEnable := TRUE;
        IF tonStirrerCycle.ET < T#5S THEN
            rMagneticStirrerFreq := 2.5; 
        ELSE
            rMagneticStirrerFreq := -2.5; 
        END_IF;

        IF bHeliumInjectEnable AND rCrucibleTemp > 450.0 THEN
            bHeliumValveCmd := TRUE;
            rHeliumFlowSetpoint := (rCrucibleTemp - 450.0) * 0.5; 
        ELSE
            bHeliumValveCmd := FALSE;
            rHeliumFlowSetpoint := 0.0;
        END_IF;

        IF rElectrodeWeightAct < 50.0 THEN
            eState := STATE_HOT_TOPPING;
        END_IF;

    STATE_HOT_TOPPING:
        rArcCurrentSetpoint := rArcCurrentSetpoint - 10.0; 
        IF rArcCurrentSetpoint <= 0.0 THEN
            eState := STATE_COOLING;
        END_IF;

    STATE_COOLING:
        rArcCurrentSetpoint := 0.0;
        rElectrodeDriveSpeed := 0.0;
        bMagneticStirrerEnable := FALSE;
        bHeliumValveCmd := TRUE; 
        rHeliumFlowSetpoint := 50.0;
        IF rCrucibleTemp < 100.0 THEN
            eState := STATE_IDLE;
        END_IF;

    STATE_FAULT:
        rArcCurrentSetpoint := 0.0;
        rElectrodeDriveSpeed := 100.0; 
        bMagneticStirrerEnable := FALSE;
        bHeliumValveCmd := FALSE;
        IF NOT bSystemFault THEN
            eState := STATE_IDLE;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
