FUNCTION_BLOCK FB_SMT_PickAndPlace_Core
TITLE = 'SMT Pick and Place Core Control'
VERSION : '1.0'

VAR_INPUT
    bEnableOperation : BOOL;
    bEmergencyStop : BOOL;
    bReset : BOOL;

    // Vision System Inputs
    fFiducialOffsetX : REAL; // mm
    fFiducialOffsetY : REAL; // mm
    fFiducialTheta : REAL;   // degrees
    bVisionDataReady : BOOL;

    // Gantry Feedback
    fActualX : REAL;
    fActualY : REAL;
    fActualZ : REAL;
    fActualTheta : REAL;

    // Component Reel Feeder
    bFeederReady : ARRAY[1..16] OF BOOL;
    iActiveFeederID : INT;

    // Head Status
    bVacuumSensor : ARRAY[1..8] OF BOOL; // True if component is held
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bError : BOOL;
    iErrorID : INT;

    // Gantry Commands
    fTargetX : REAL;
    fTargetY : REAL;
    fTargetZ : REAL;
    fTargetTheta : REAL;

    // Vacuum and Air Commands
    bVacuumEnable : ARRAY[1..8] OF BOOL;
    bAirBlowoff : ARRAY[1..8] OF BOOL;

    // Feeder Commands
    bAdvanceFeeder : ARRAY[1..16] OF BOOL;

    // Vision Sync
    bTriggerCamera : BOOL;
END_VAR

VAR
    iState : INT := 0; // State Machine
    iStep : INT := 0;
    iCurrentNozzle : INT := 1;
    fHomePosX : REAL := 0.0;
    fHomePosY : REAL := 0.0;
    fHomePosZ : REAL := 50.0;

    // Transformation matrix components for fiducial correction
    fCosTheta : REAL;
    fSinTheta : REAL;

    // Timers
    tSettleTimer : TON;
    tVacuumTimer : TON;
    tBlowoffTimer : TON;
END_VAR

(*
    State Machine Description:
    0 = Init & Homing
    10 = Wait for Start
    20 = Feeder Indexing & Pick Preparation
    30 = Z-Axis Descend to Pick
    40 = Enable Vacuum & Dwell
    50 = Z-Axis Retract
    60 = Move to Vision Camera
    70 = Capture Image & Process offset
    80 = Move to Placement Coordinate (Applying Fiducial offset)
    90 = Z-Axis Descend to Place
    100 = Disable Vacuum, Air Blowoff
    110 = Z-Axis Retract & Advance Feeder
    999 = Error State
*)

IF bEmergencyStop THEN
    iState := 999;
    iErrorID := 1;
END_IF;

IF bReset AND iState = 999 AND NOT bEmergencyStop THEN
    iState := 0;
    bError := FALSE;
    iErrorID := 0;
END_IF;

CASE iState OF
    0: // Init & Homing
        bSystemReady := FALSE;
        fTargetX := fHomePosX;
        fTargetY := fHomePosY;
        fTargetZ := fHomePosZ;
        fTargetTheta := 0.0;

        // Disable all nozzles
        FOR iStep := 1 TO 8 DO
            bVacuumEnable[iStep] := FALSE;
            bAirBlowoff[iStep] := FALSE;
        END_FOR;

        // Wait for gantry to reach home (Simulated threshold)
        IF ABS(fActualX - fHomePosX) < 0.1 AND ABS(fActualZ - fHomePosZ) < 0.1 THEN
            iState := 10;
        END_IF;

    10: // Wait for Start
        bSystemReady := TRUE;
        IF bEnableOperation THEN
            bSystemReady := FALSE;
            iCurrentNozzle := 1;
            iState := 20;
        END_IF;

    20: // Feeder Indexing & Move to Pick Location
        IF iActiveFeederID > 0 AND iActiveFeederID <= 16 THEN
            IF bFeederReady[iActiveFeederID] THEN
                // Simulated coordinates for feeder locations
                fTargetX := INT_TO_REAL(iActiveFeederID) * 25.0; 
                fTargetY := 500.0;
                fTargetTheta := 0.0;

                IF ABS(fActualX - fTargetX) < 0.1 AND ABS(fActualY - fTargetY) < 0.1 THEN
                    iState := 30;
                END_IF;
            ELSE
                iState := 999; // Feeder not ready error
                iErrorID := 2;
            END_IF;
        END_IF;

    30: // Z-Axis Descend to Pick
        fTargetZ := 5.0; // Pick height
        IF ABS(fActualZ - fTargetZ) < 0.05 THEN
            iState := 40;
            tVacuumTimer(IN := FALSE);
        END_IF;

    40: // Enable Vacuum & Dwell
        bVacuumEnable[iCurrentNozzle] := TRUE;
        tVacuumTimer(IN := TRUE, PT := T#50MS);
        IF tVacuumTimer.Q THEN
            IF bVacuumSensor[iCurrentNozzle] THEN
                iState := 50;
            ELSE
                iState := 999; // Missed pick
                iErrorID := 3;
            END_IF;
        END_IF;

    50: // Z-Axis Retract
        fTargetZ := fHomePosZ;
        IF ABS(fActualZ - fTargetZ) < 0.1 THEN
            iState := 60;
        END_IF;

    60: // Move to Vision Camera
        fTargetX := 200.0; // Camera X
        fTargetY := 200.0; // Camera Y
        IF ABS(fActualX - fTargetX) < 0.1 AND ABS(fActualY - fTargetY) < 0.1 THEN
            bTriggerCamera := TRUE;
            IF bVisionDataReady THEN
                bTriggerCamera := FALSE;
                iState := 70;
            END_IF;
        END_IF;

    70: // Process Vision Offset
        // Simple matrix transformation simulation for component offset
        fCosTheta := COS(fFiducialTheta * 3.14159 / 180.0);
        fSinTheta := SIN(fFiducialTheta * 3.14159 / 180.0);
        iState := 80;

    80: // Move to Placement Coordinate (Applying Fiducial offset)
        // Simulated placement target (Board coordinate)
        fTargetX := 150.0 + (fFiducialOffsetX * fCosTheta - fFiducialOffsetY * fSinTheta);
        fTargetY := 300.0 + (fFiducialOffsetX * fSinTheta + fFiducialOffsetY * fCosTheta);
        fTargetTheta := fFiducialTheta;

        IF ABS(fActualX - fTargetX) < 0.1 AND ABS(fActualY - fTargetY) < 0.1 THEN
            iState := 90;
        END_IF;

    90: // Z-Axis Descend to Place
        fTargetZ := 1.5; // Place height
        IF ABS(fActualZ - fTargetZ) < 0.05 THEN
            iState := 100;
            tBlowoffTimer(IN := FALSE);
        END_IF;

    100: // Disable Vacuum, Air Blowoff
        bVacuumEnable[iCurrentNozzle] := FALSE;
        bAirBlowoff[iCurrentNozzle] := TRUE;
        tBlowoffTimer(IN := TRUE, PT := T#30MS);
        IF tBlowoffTimer.Q THEN
            bAirBlowoff[iCurrentNozzle] := FALSE;
            iState := 110;
        END_IF;

    110: // Z-Axis Retract & Advance Feeder
        fTargetZ := fHomePosZ;
        bAdvanceFeeder[iActiveFeederID] := TRUE;
        IF ABS(fActualZ - fTargetZ) < 0.1 THEN
            bAdvanceFeeder[iActiveFeederID] := FALSE;
            iState := 10; // Back to wait for next cycle or finish
        END_IF;

    999: // Error State
        bError := TRUE;
        bSystemReady := FALSE;
        FOR iStep := 1 TO 8 DO
            bVacuumEnable[iStep] := FALSE;
            bAirBlowoff[iStep] := FALSE;
            bAdvanceFeeder[iStep] := FALSE;
        END_FOR;

END_CASE;

END_FUNCTION_BLOCK
```

