    rCurrentTemp : REAL; // Current zone temperature (C)
    rCurrentHumidity : REAL; // Current zone humidity (%)
    rCurrentCO2 : REAL; // Current CO2 concentration (ppm)
    rCurrentPH : REAL; // Nutrient solution pH
    rCurrentEC : REAL; // Nutrient solution Electrical Conductivity (mS/cm)
