    // Time control
    tCurrentTime : TIME_OF_DAY;
    tDayStart : TIME_OF_DAY := TOD#06:00:00;
    tDayEnd : TIME_OF_DAY := TOD#22:00:00;

    // Aeroponic Cycle Setpoints
    tMistOnTime : TIME := T#5S;
    tMistOffTime : TIME := T#5M;
END_VAR

VAR_OUTPUT
    // Actuators
    bMistPumpRun : BOOL;
    rLEDRedDimming : REAL; // 0-100%
    rLEDBlueDimming : REAL; // 0-100%
    rLEDWhiteDimming : REAL; // 0-100%
    bCoolingValve : BOOL;
    bHeatingValve : BOOL;
    bHumidifierRun : BOOL;
    bDehumidifierRun : BOOL;
    bCO2ValveRun : BOOL;

    // Nutrient Dosing
    bPHUpDosing : BOOL;
    bPHDownDosing : BOOL;
    bNutrientADosing : BOOL;
    bNutrientBDosing : BOOL;

    // Alarms
    bAlarmCriticalTemp : BOOL;
    bAlarmLowWater : BOOL;
    bAlarmPHOutOfRange : BOOL;
END_VAR

VAR
    // Internal States
    bIsDaytime : BOOL;
    rActiveTargetTemp : REAL;

    // Timers
    tonMistOff : TON;
    tonMistOn : TON;
    tonDosingInterval : TON;

    // PID Controllers (Conceptual for ST)
    rTempError : REAL;
    rHumidityError : REAL;
    rCO2Error : REAL;

    // Dosing state
    iDosingState : INT := 0; 
END_VAR

// --- Day/Night Cycle Determination ---
IF tCurrentTime >= tDayStart AND tCurrentTime < tDayEnd THEN
    bIsDaytime := TRUE;
    rActiveTargetTemp := rTargetTempDay;
ELSE
    bIsDaytime := FALSE;
    rActiveTargetTemp := rTargetTempNight;
END_IF;

IF NOT bSystemEnable THEN
    bMistPumpRun := FALSE;
    rLEDRedDimming := 0.0;
    rLEDBlueDimming := 0.0;
    rLEDWhiteDimming := 0.0;
    bCoolingValve := FALSE;
    bHeatingValve := FALSE;
    bHumidifierRun := FALSE;
    bDehumidifierRun := FALSE;
    bCO2ValveRun := FALSE;
    bPHUpDosing := FALSE;
    bPHDownDosing := FALSE;
    bNutrientADosing := FALSE;
    bNutrientBDosing := FALSE;
    RETURN;
END_IF;

// --- Aeroponic Misting Cycle ---
tonMistOff(IN := NOT bMistPumpRun AND bSystemEnable, PT := tMistOffTime);
IF tonMistOff.Q THEN
    bMistPumpRun := TRUE;
END_IF;

tonMistOn(IN := bMistPumpRun AND bSystemEnable, PT := tMistOnTime);
IF tonMistOn.Q THEN
    bMistPumpRun := FALSE;
END_IF;

// --- Variable Spectrum LED Control ---
IF bIsDaytime THEN
    // Adjust spectrum based on growth phase / PPFD target.
    // Simplified model: base white, adjust red/blue for photosynthesis efficiency.
    rLEDWhiteDimming := (rTargetPPFD / 1000.0) * 50.0; 
    rLEDRedDimming := (rTargetPPFD / 1000.0) * 80.0;
    rLEDBlueDimming := (rTargetPPFD / 1000.0) * 60.0;

    // Cap at 100%
    IF rLEDWhiteDimming > 100.0 THEN rLEDWhiteDimming := 100.0; END_IF;
    IF rLEDRedDimming > 100.0 THEN rLEDRedDimming := 100.0; END_IF;
    IF rLEDBlueDimming > 100.0 THEN rLEDBlueDimming := 100.0; END_IF;
ELSE
    rLEDWhiteDimming := 0.0;
    rLEDRedDimming := 0.0;
    rLEDBlueDimming := 0.0;
END_IF;

// --- Climate Control: Temperature & Humidity ---
rTempError := rCurrentTemp - rActiveTargetTemp;
IF rTempError > 1.5 THEN
    bCoolingValve := TRUE;
    bHeatingValve := FALSE;
ELSIF rTempError < -1.5 THEN
    bCoolingValve := FALSE;
    bHeatingValve := TRUE;
ELSE
    bCoolingValve := FALSE;
    bHeatingValve := FALSE;
END_IF;

rHumidityError := rCurrentHumidity - rTargetHumidity;
IF rHumidityError > 5.0 THEN
    bDehumidifierRun := TRUE;
    bHumidifierRun := FALSE;
ELSIF rHumidityError < -5.0 THEN
    bDehumidifierRun := FALSE;
    bHumidifierRun := TRUE;
ELSE
    bDehumidifierRun := FALSE;
    bHumidifierRun := FALSE;
END_IF;

// --- CO2 Enrichment Cascade ---
// Only enrich during daytime (photosynthesis active)
IF bIsDaytime THEN
    rCO2Error := rTargetCO2 - rCurrentCO2;
    IF rCO2Error > 50.0 AND NOT bDehumidifierRun THEN 
        // Interlock: don't inject CO2 if dehumidifier/exhaust is running heavily
        bCO2ValveRun := TRUE;
    ELSIF rCO2Error <= 0.0 THEN
        bCO2ValveRun := FALSE;
    END_IF;
ELSE
    bCO2ValveRun := FALSE;
END_IF;

// --- Nutrient & pH Dosing (State Machine) ---
tonDosingInterval(IN := (iDosingState = 0), PT := T#10M);

IF tonDosingInterval.Q THEN
    iDosingState := 1; // Check pH
END_IF;

CASE iDosingState OF
    0: // Idle
        bPHUpDosing := FALSE;
        bPHDownDosing := FALSE;
        bNutrientADosing := FALSE;
        bNutrientBDosing := FALSE;

    1: // Evaluate pH
        IF rCurrentPH < (rTargetPH - 0.2) THEN
            bPHUpDosing := TRUE;
            iDosingState := 2; // Dosing Up
        ELSIF rCurrentPH > (rTargetPH + 0.2) THEN
            bPHDownDosing := TRUE;
            iDosingState := 3; // Dosing Down
        ELSE
            iDosingState := 4; // pH OK, Check EC
        END_IF;

    2, 3: // Dosing pH
        // In real system, this would be a timer for dose volume.
        // Simplified to jump to wait state.
        bPHUpDosing := FALSE;
        bPHDownDosing := FALSE;
        iDosingState := 0; 

    4: // Evaluate EC
        IF rCurrentEC < (rTargetEC - 0.1) THEN
            bNutrientADosing := TRUE;
            bNutrientBDosing := TRUE;
            iDosingState := 5; // Dosing Nutrients
        ELSE
            iDosingState := 0; // All Good
        END_IF;

    5: // Dosing Nutrients
        bNutrientADosing := FALSE;
        bNutrientBDosing := FALSE;
        iDosingState := 0;
END_CASE;

// --- Alarms ---
bAlarmCriticalTemp := (rCurrentTemp > 35.0 OR rCurrentTemp < 10.0);
bAlarmLowWater := (rWaterLevel < 10.0);
bAlarmPHOutOfRange := (rCurrentPH < 4.0 OR rCurrentPH > 8.0);

END_FUNCTION_BLOCK
