FUNCTION_BLOCK FB_BerylliumPrimaryMirrorPolisher
VAR_INPUT
    bEnable                 : BOOL;       (* Master enable signal for the polishing cell *)
    bEmergencyStop          : BOOL;       (* Safety circuit OK (Active HIGH = Safe) *)
    rVibrationZ             : REAL;       (* Z-axis interferometer vibration measurement (nm) *)
    rVibrationX             : REAL;       (* X-axis interferometer vibration measurement (nm) *)
    rVibrationY             : REAL;       (* Y-axis interferometer vibration measurement (nm) *)
    rMRFFluidTemp           : REAL;       (* Magnetorheological fluid temperature (C) *)
    rTargetDwellTime        : REAL;       (* Sub-nanometer deterministic dwell time mapping base (ms) *)
    bInterferometerValid    : BOOL;       (* Interferometry data validity flag *)
    rBerylliumTemp          : REAL;       (* Beryllium substrate surface temperature (C) *)
    iToolPathIndex          : DINT;       (* Current CNC tool path vector index *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;       (* Indicates polishing cell is ready for operations *)
    bPolishingActive        : BOOL;       (* Active state of the MRF polishing process *)
    rPneumaticCompZ         : REAL;       (* Z-axis active pneumatic vibration compensation (bar) *)
    rPneumaticCompX         : REAL;       (* X-axis active pneumatic vibration compensation (bar) *)
    rPneumaticCompY         : REAL;       (* Y-axis active pneumatic vibration compensation (bar) *)
    rMagneticFieldStrength  : REAL;       (* Output control for electromagnet (Tesla) for MRF fluid stiffening *)
    bAlarm                  : BOOL;       (* Critical fault detected - safely aborting *)
    iErrorCode              : INT;        (* Detailed error code for diagnostics *)
END_VAR

VAR
    iState                  : INT := 0;   (* State machine internal integer *)
    tStartupDelay           : TON;        (* System initialization timer *)
    tMRFStabilize           : TON;        (* Fluid temperature stabilization timer *)
    rVibrationThreshold     : REAL := 5.0;(* Maximum allowed vibration in nm *)
    rMaxTempBeryllium       : REAL := 22.5;(* Max Be substrate temp to avoid thermal expansion anomalies (C) *)
    rNominalTemp            : REAL := 20.0;(* Nominal operating temperature (C) *)
    rKpVibration            : REAL := 0.015; (* Proportional gain for vibration isolation *)
    rKiVibration            : REAL := 0.002; (* Integral gain for vibration isolation *)
    rIntZ, rIntX, rIntY     : REAL := 0.0; (* Integral accumulators for XYZ isolation *)
    bThermalFault           : BOOL := FALSE;
    bVibrationFault         : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Critical Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bPolishingActive := FALSE;
    rMagneticFieldStrength := 0.0;
    rPneumaticCompZ := 0.0;
    rPneumaticCompX := 0.0;
    rPneumaticCompY := 0.0;
    bAlarm := TRUE;
    iErrorCode := 9999; (* E-Stop active *)
    iState := 0;
    RETURN;
END_IF;

(* 2. Thermal Monitoring of Beryllium Substrate *)
IF (rBerylliumTemp > rMaxTempBeryllium) OR (rMRFFluidTemp > 24.0) THEN
    bThermalFault := TRUE;
ELSE
    bThermalFault := FALSE;
END_IF;

(* 3. Active Vibration Isolation (Pneumatic Compensation) *)
IF bEnable AND NOT bThermalFault THEN
    (* Proportional-Integral Control for sub-nanometer isolation *)
    rIntZ := rIntZ + (rVibrationZ * rKiVibration);
    rIntX := rIntX + (rVibrationX * rKiVibration);
    rIntY := rIntY + (rVibrationY * rKiVibration);

    (* Limit integral windup *)
    IF rIntZ > 1.0 THEN rIntZ := 1.0; ELSIF rIntZ < -1.0 THEN rIntZ := -1.0; END_IF;
    IF rIntX > 1.0 THEN rIntX := 1.0; ELSIF rIntX < -1.0 THEN rIntX := -1.0; END_IF;
    IF rIntY > 1.0 THEN rIntY := 1.0; ELSIF rIntY < -1.0 THEN rIntY := -1.0; END_IF;

    rPneumaticCompZ := (rVibrationZ * rKpVibration) + rIntZ;
    rPneumaticCompX := (rVibrationX * rKpVibration) + rIntX;
    rPneumaticCompY := (rVibrationY * rKpVibration) + rIntY;

    (* Vibration Fault Check *)
    IF (ABS(rVibrationZ) > rVibrationThreshold) OR (ABS(rVibrationX) > rVibrationThreshold) OR (ABS(rVibrationY) > rVibrationThreshold) THEN
        bVibrationFault := TRUE;
    ELSE
        bVibrationFault := FALSE;
    END_IF;
ELSE
    rPneumaticCompZ := 0.0;
    rPneumaticCompX := 0.0;
    rPneumaticCompY := 0.0;
END_IF;

(* 4. Main State Machine for MRF Polishing Sequence *)
CASE iState OF
    0: (* IDLE & SAFETY CHECK *)
        bSystemReady := FALSE;
        bPolishingActive := FALSE;
        rMagneticFieldStrength := 0.0;
        IF bEnable AND NOT bThermalFault AND NOT bVibrationFault AND bInterferometerValid THEN
            iState := 10;
        END_IF;
        IF bThermalFault THEN iErrorCode := 1001; END_IF;
        IF bVibrationFault THEN iErrorCode := 1002; END_IF;

    10: (* SYSTEM INITIALIZATION AND PNEUMATIC STABILIZATION *)
        tStartupDelay(IN := TRUE, PT := T#10S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* MRF FLUID CONDITIONING *)
        (* Target fluid stiffness requires ~0.8 Tesla based on dwell map *)
        rMagneticFieldStrength := 0.85; 
        tMRFStabilize(IN := TRUE, PT := T#5S);
        IF tMRFStabilize.Q THEN
            tMRFStabilize(IN := FALSE);
            IF bInterferometerValid THEN
                iState := 30; (* Proceed to active polishing *)
            ELSE
                iState := 0; (* Lost interferometry, abort to safe state *)
                iErrorCode := 2001;
            END_IF;
        END_IF;

    30: (* ACTIVE POLISHING *)
        bPolishingActive := TRUE;
        (* Dynamically adjust magnetic field based on target dwell time and current velocity vector *)
        (* Complex polynomial scaling for MRF ribbon stiffness mapping *)
        rMagneticFieldStrength := 0.5 + (rTargetDwellTime * 0.001) - (rMRFFluidTemp - rNominalTemp)*0.01;

        (* Bounds checking for magnetic field *)
        IF rMagneticFieldStrength > 1.5 THEN
            rMagneticFieldStrength := 1.5;
        ELSIF rMagneticFieldStrength < 0.2 THEN
            rMagneticFieldStrength := 0.2;
        END_IF;

        (* Continuous Fault Monitoring during active polishing *)
        IF bThermalFault OR bVibrationFault OR NOT bInterferometerValid OR NOT bEnable THEN
            bPolishingActive := FALSE;
            rMagneticFieldStrength := 0.0;
            iState := 0;
            IF bThermalFault THEN iErrorCode := 3001; END_IF;
            IF bVibrationFault THEN iErrorCode := 3002; END_IF;
            IF NOT bInterferometerValid THEN iErrorCode := 3003; END_IF;
        END_IF;

    ELSE
        (* INVALID STATE RECOVERY *)
        iState := 0;
        iErrorCode := 9999;
END_CASE;

(* 5. Final Alarm Output Logic *)
bAlarm := bThermalFault OR bVibrationFault OR (iErrorCode > 0 AND iErrorCode <> 9999);
IF NOT bAlarm AND bSystemReady THEN
    iErrorCode := 0; (* Clear error if system healthy *)
END_IF;

END_FUNCTION_BLOCK
```

