FUNCTION_BLOCK FB_BallastWaterTreatment
VAR_INPUT
    bStartProcess       : BOOL;   (* Start the entire BWT process *)
    bEmergencyStop      : BOOL;   (* Emergency Stop *)
    rFlowRate           : REAL;   (* Main ballast flow rate m3/h *)
    rSalinity           : REAL;   (* Seawater salinity PSU *)
    rTemperature        : REAL;   (* Seawater temperature Celsius *)
    rTRO_Level          : REAL;   (* Total Residual Oxidant mg/L *)
    bFilterDP_High      : BOOL;   (* Filter Differential Pressure High *)
    bTRO_SensorFault    : BOOL;
END_VAR

VAR_OUTPUT
    bPumpRun            : BOOL;   (* Main Ballast Pump run command *)
    bFilterBackwash     : BOOL;   (* Filter Auto-backwash command *)
    bElectrolysisRun    : BOOL;   (* Electrolyzer run command *)
    rElectrolysisCurrent: REAL;   (* Electrolyzer Current Setpoint A *)
    bNeutralizationRun  : BOOL;   (* Neutralization unit run command *)
    rNeutralizerDosing  : REAL;   (* Neutralizer dosing rate L/h *)
    bSystemFault        : BOOL;   (* General System Fault *)
    nState              : INT;    (* Current state of the process *)
END_VAR

VAR
    tBackwashTimer      : TON;
    tElectrolysisDelay  : TON;
    tTROMonitoring      : TON;
    rTargetTRO          : REAL := 2.0; (* Target TRO in mg/L *)
    bBackwashing        : BOOL := FALSE;
    bInitialization     : BOOL := FALSE;
    rIntegralError      : REAL := 0.0;
    rKp                 : REAL := 50.0;
    rKi                 : REAL := 2.5;
END_VAR

(* State Machine Definitions *)
VAR CONSTANT
    ST_IDLE          : INT := 0;
    ST_INIT          : INT := 10;
    ST_RUNNING       : INT := 20;
    ST_BACKWASH      : INT := 30;
    ST_NEUTRALIZATION: INT := 40;
    ST_FAULT         : INT := 99;
END_VAR

(* Emergency Stop Handling *)
IF bEmergencyStop THEN
    bPumpRun := FALSE;
    bFilterBackwash := FALSE;
    bElectrolysisRun := FALSE;
    bNeutralizationRun := FALSE;
    rElectrolysisCurrent := 0.0;
    rNeutralizerDosing := 0.0;
    bSystemFault := TRUE;
    nState := ST_FAULT;
    RETURN;
END_IF

(* State Machine implementation for Ballast Water Treatment *)
CASE nState OF
    ST_IDLE:
        bPumpRun := FALSE;
        bElectrolysisRun := FALSE;
        IF bStartProcess AND NOT bSystemFault THEN
            nState := ST_INIT;
        END_IF

    ST_INIT:
        (* Pre-checks: Salinity and Temperature *)
        IF (rSalinity < 1.5) OR (rTemperature < -2.0) THEN
            (* Water too fresh or too cold for efficient electrolysis, requires external salt/heater *)
            bSystemFault := TRUE;
            nState := ST_FAULT;
        ELSE
            bPumpRun := TRUE;
            bInitialization := TRUE;
            tElectrolysisDelay(IN := bInitialization, PT := T#5S);
            IF tElectrolysisDelay.Q THEN
                nState := ST_RUNNING;
            END_IF
        END_IF

    ST_RUNNING:
        bElectrolysisRun := TRUE;

        (* PI Controller for Electrolyzer Current based on TRO Level *)
        IF NOT bTRO_SensorFault THEN
            rIntegralError := rIntegralError + (rTargetTRO - rTRO_Level) * 0.1; (* 100ms cycle assumed *)
            (* Anti-windup *)
            IF rIntegralError > 100.0 THEN rIntegralError := 100.0; END_IF
            IF rIntegralError < 0.0 THEN rIntegralError := 0.0; END_IF

            rElectrolysisCurrent := rKp * (rTargetTRO - rTRO_Level) + rKi * rIntegralError;

            (* Base current feed-forward based on flow rate *)
            rElectrolysisCurrent := rElectrolysisCurrent + (rFlowRate * 0.5);

            (* Clamp Current *)
            IF rElectrolysisCurrent > 5000.0 THEN rElectrolysisCurrent := 5000.0; END_IF
            IF rElectrolysisCurrent < 0.0 THEN rElectrolysisCurrent := 0.0; END_IF
        ELSE
            (* Fallback open loop control based purely on flow if TRO sensor fails *)
            rElectrolysisCurrent := rFlowRate * 0.8;
            bSystemFault := TRUE; (* Warning level *)
        END_IF

        (* Check Filter Differential Pressure *)
        IF bFilterDP_High THEN
            nState := ST_BACKWASH;
        END_IF

        IF NOT bStartProcess THEN
            nState := ST_IDLE;
        END_IF

    ST_BACKWASH:
        (* Auto-backwash sequence *)
        bFilterBackwash := TRUE;
        bBackwashing := TRUE;
        tBackwashTimer(IN := bBackwashing, PT := T#30S);

        IF tBackwashTimer.Q THEN
            bFilterBackwash := FALSE;
            bBackwashing := FALSE;
            tBackwashTimer(IN := FALSE); (* Reset timer *)
            nState := ST_RUNNING;
        END_IF

    ST_FAULT:
        (* Fault state requires manual reset *)
        bPumpRun := FALSE;
        bElectrolysisRun := FALSE;
        bFilterBackwash := FALSE;
        rElectrolysisCurrent := 0.0;

        IF NOT bEmergencyStop AND NOT bStartProcess THEN
            bSystemFault := FALSE;
            nState := ST_IDLE;
        END_IF

END_CASE
END_FUNCTION_BLOCK
