FUNCTION_BLOCK "FB_Autoclave_Cure_M1"
TITLE = 'Autoclave with Vacuum Leak Detection'
VERSION : '1.1'

VAR_INPUT
    bStart_Cycle : Bool;
    rAct_Temp : Real;
    rAct_Pressure : Real;
    rAct_N2_Level : Real;
    rAct_Vac_Pressure : Real;
END_VAR

VAR_OUTPUT
    bCmd_Heater : Bool;
    bCmd_PressValve : Bool;
    bCmd_N2_Purge : Bool;
    bCmd_Vac_Pump : Bool;
    bAlarm_Abort : Bool;
    iStep_ID : Int;
END_VAR

VAR
    iState : Int;
    tDwell_Timer : TON_TIME;
    rLast_Vac_Pressure : Real;
    tLeak_Timer : TON_TIME;
END_VAR

BEGIN
    // Leak Detection System
    tLeak_Timer(IN := (iState > 0 AND iState < 40), PT := T#1S);
    IF tLeak_Timer.Q THEN
        IF (rAct_Vac_Pressure - rLast_Vac_Pressure) > 0.05 THEN
            iState := 99; // Leak detected -> Abort
        END_IF;
        rLast_Vac_Pressure := rAct_Vac_Pressure;
        tLeak_Timer(IN := FALSE, PT := T#0S);
    END_IF;

    CASE iState OF
        0: // Idle
            bAlarm_Abort := FALSE;
            IF bStart_Cycle THEN iState := 10; END_IF;
        10: // Purge and Vacuum Phase
            bCmd_N2_Purge := TRUE;
            bCmd_Vac_Pump := TRUE;
            IF rAct_N2_Level > 95.0 AND rAct_Vac_Pressure < 0.1 THEN
                bCmd_N2_Purge := FALSE;
                iState := 20;
            END_IF;
        20: // Heat and Pressurize Phase
            bCmd_Heater := (rAct_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF (rAct_Temp >= 180.0) AND (rAct_Pressure >= 7.0) THEN
                iState := 30;
            END_IF;
        30: // Dwell Phase
            tDwell_Timer(IN := TRUE, PT := T#120M);
            bCmd_Heater := (rAct_Temp < 180.0);
            IF tDwell_Timer.Q THEN
                bCmd_Heater := FALSE;
                bCmd_PressValve := FALSE;
                iState := 40;
            END_IF;
        40: // Cool Down Phase
            bCmd_Vac_Pump := FALSE;
            IF rAct_Temp < 50.0 THEN
                iState := 0;
                tDwell_Timer(IN := FALSE, PT := T#0S);
            END_IF;
        99: // Abort Sequence
            bCmd_Heater := FALSE;
            bCmd_PressValve := FALSE;
            bCmd_Vac_Pump := TRUE;
            bAlarm_Abort := TRUE;
    END_CASE;
    iStep_ID := iState;
END_FUNCTION_BLOCK
