FUNCTION_BLOCK FB_CBW_Control
VAR_INPUT
    bStart_Sequence : BOOL;
    bEmergencyStop : BOOL;
    rCurrent_pH_Compartment_1 : REAL; (* Range 0.0 to 14.0 *)
    rCurrent_pH_Compartment_2 : REAL;
    rWater_Level_Press : REAL; (* Liters *)
    rTemperature_Compartment_1 : REAL; (* Celsius *)
    rTemperature_Compartment_2 : REAL;
    bShuttle_Ready : BOOL;
    bMembrane_Press_Ready : BOOL;
END_VAR

VAR_OUTPUT
    bDosing_Pump_Alkali_Cmd : BOOL;
    bDosing_Pump_Acid_Cmd : BOOL;
    bDosing_Pump_Detergent_Cmd : BOOL;
    bHeater_Compartment_1_Cmd : BOOL;
    bHeater_Compartment_2_Cmd : BOOL;
    bTransfer_To_Press_Cmd : BOOL;
    rPress_Pressure_Setpoint : REAL;
    bPress_Start_Extraction : BOOL;
    bShuttle_Load_Cmd : BOOL;
    nActive_Step : INT;
    bSystemFault : BOOL;
END_VAR

VAR
    rtStart : R_TRIG;
    tDosing_Timer : TON;
    tPress_Timer : TON;
    tTransfer_Timer : TON;

    rTarget_pH_Comp1 : REAL := 10.5;
    rTarget_pH_Comp2 : REAL := 6.5;
    rTarget_Temp_Comp1 : REAL := 75.0;
    rTarget_Temp_Comp2 : REAL := 40.0;

    bDosing_Active : BOOL;
    bHeating_Active : BOOL;
    bPress_Active : BOOL;
    nState : INT := 0;
END_VAR

(* Control Logic for Continuous Batch Washer *)
rtStart(CLK := bStart_Sequence);

IF bEmergencyStop THEN
    nState := 999; (* Fault State *)
END_IF;

CASE nState OF
    0: (* Idle State *)
        nActive_Step := 0;
        bDosing_Pump_Alkali_Cmd := FALSE;
        bDosing_Pump_Acid_Cmd := FALSE;
        bDosing_Pump_Detergent_Cmd := FALSE;
        bHeater_Compartment_1_Cmd := FALSE;
        bHeater_Compartment_2_Cmd := FALSE;
        bTransfer_To_Press_Cmd := FALSE;
        bPress_Start_Extraction := FALSE;
        bShuttle_Load_Cmd := FALSE;
        bSystemFault := FALSE;

        IF rtStart.Q THEN
            nState := 10;
        END_IF;

    10: (* Compartment 1: Wash & Heating *)
        nActive_Step := 10;
        (* Temperature Control *)
        IF rTemperature_Compartment_1 < rTarget_Temp_Comp1 - 2.0 THEN
            bHeater_Compartment_1_Cmd := TRUE;
        ELSIF rTemperature_Compartment_1 >= rTarget_Temp_Comp1 THEN
            bHeater_Compartment_1_Cmd := FALSE;
        END_IF;

        (* pH and Dosing Control *)
        IF rCurrent_pH_Compartment_1 < rTarget_pH_Comp1 THEN
            bDosing_Pump_Alkali_Cmd := TRUE;
            bDosing_Pump_Detergent_Cmd := TRUE;
        ELSE
            bDosing_Pump_Alkali_Cmd := FALSE;
            bDosing_Pump_Detergent_Cmd := FALSE;
        END_IF;

        (* Transition Condition *)
        IF rTemperature_Compartment_1 >= rTarget_Temp_Comp1 AND rCurrent_pH_Compartment_1 >= rTarget_pH_Comp1 THEN
            nState := 20;
        END_IF;

    20: (* Compartment 2: Rinse & Neutralization *)
        nActive_Step := 20;
        bDosing_Pump_Alkali_Cmd := FALSE;
        bDosing_Pump_Detergent_Cmd := FALSE;

        (* Temperature Control *)
        IF rTemperature_Compartment_2 < rTarget_Temp_Comp2 - 2.0 THEN
            bHeater_Compartment_2_Cmd := TRUE;
        ELSIF rTemperature_Compartment_2 >= rTarget_Temp_Comp2 THEN
            bHeater_Compartment_2_Cmd := FALSE;
        END_IF;

        (* pH Control *)
        IF rCurrent_pH_Compartment_2 > rTarget_pH_Comp2 THEN
            bDosing_Pump_Acid_Cmd := TRUE;
        ELSE
            bDosing_Pump_Acid_Cmd := FALSE;
        END_IF;

        (* Transition Condition *)
        IF rTemperature_Compartment_2 >= rTarget_Temp_Comp2 AND rCurrent_pH_Compartment_2 <= rTarget_pH_Comp2 THEN
            nState := 30;
        END_IF;

    30: (* Transfer to Membrane Press *)
        nActive_Step := 30;
        bHeater_Compartment_2_Cmd := FALSE;
        bDosing_Pump_Acid_Cmd := FALSE;

        IF bMembrane_Press_Ready THEN
            bTransfer_To_Press_Cmd := TRUE;
            tTransfer_Timer(IN:= TRUE, PT:= T#10S);
            IF tTransfer_Timer.Q THEN
                bTransfer_To_Press_Cmd := FALSE;
                tTransfer_Timer(IN:= FALSE);
                nState := 40;
            END_IF;
        END_IF;

    40: (* Membrane Press Extraction *)
        nActive_Step := 40;
        rPress_Pressure_Setpoint := 40.0; (* 40 Bar for Heavy Cotton *)
        bPress_Start_Extraction := TRUE;

        tPress_Timer(IN:= TRUE, PT:= T#120S); (* 2 Minutes Extraction *)
        IF tPress_Timer.Q THEN
            bPress_Start_Extraction := FALSE;
            tPress_Timer(IN:= FALSE);
            nState := 50;
        END_IF;

    50: (* Shuttle Conveyor Loading *)
        nActive_Step := 50;
        IF bShuttle_Ready THEN
            bShuttle_Load_Cmd := TRUE;
            tTransfer_Timer(IN:= TRUE, PT:= T#5S);
            IF tTransfer_Timer.Q THEN
                bShuttle_Load_Cmd := FALSE;
                tTransfer_Timer(IN:= FALSE);
                nState := 0; (* Cycle Complete *)
            END_IF;
        END_IF;

    999: (* Fault State *)
        nActive_Step := 999;
        bDosing_Pump_Alkali_Cmd := FALSE;
        bDosing_Pump_Acid_Cmd := FALSE;
        bDosing_Pump_Detergent_Cmd := FALSE;
        bHeater_Compartment_1_Cmd := FALSE;
        bHeater_Compartment_2_Cmd := FALSE;
        bTransfer_To_Press_Cmd := FALSE;
        bPress_Start_Extraction := FALSE;
        bShuttle_Load_Cmd := FALSE;
        bSystemFault := TRUE;

        IF NOT bEmergencyStop THEN
           nState := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
