FUNCTION_BLOCK FB_Rotogravure_Press_Control
TITLE = 'High-Speed Web Rotogravure Packaging Press Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI Cloud Swarm'

(* 
   This function block orchestrates the critical environmental and web-handling 
   subsystems of a high-speed rotogravure printing press. 

   Subsystem 1: Volatile Organic Compound (VOC) Capture Ventilation.
   In rotogravure, solvent-based inks flash off VOCs during drying. 
   A PI controller modulates the main exhaust variable frequency drive (VFD) 
   to maintain safe Lower Explosive Limit (LEL) percentages while optimizing energy.

   Subsystem 2: Chilling Roller Web Shrinkage Compensation.
   The heated web must be flash-chilled to set the ink. Thermal shock induces 
   web shrinkage (neck-in and machine-direction contraction). 
   This logic adjusts web tension dynamically based on the delta temperature.

   Subsystem 3: Pneumatic Edge Guiding.
   At high speeds (>400 m/min), aerodynamic boundary layers induce web weave. 
   A PD control loop operates a proportional pneumatic valve to adjust the guide frame.
*)

VAR_INPUT
    bEnable : BOOL; (* Master system enable *)
    bE_Stop : BOOL; (* Emergency Stop - Active Low *)
    rLineSpeed_m_min : REAL; (* Current production speed in meters per minute *)
    rVOC_LEL_Percent : REAL; (* VOC concentration as % of Lower Explosive Limit *)
    rChillerInletTemp_C : REAL; (* Temperature of web entering chiller section *)
    rChillerRollerTemp_C : REAL; (* Actual temperature of the chill roller *)
    rWebTension_Actual_N : REAL; (* Measured web tension from load cells *)
    rEdgeSensor_mm : REAL; (* Ultrasonic/Optical edge sensor deviation from center *)
END_VAR

VAR_OUTPUT
    rExhaustFan_VFD_Hz : REAL; (* Frequency command for exhaust fan VFD *)
    rChillerFlowValve_Pct : REAL; (* Chilled water proportional valve (0-100%) *)
    rWebTension_Cmd_N : REAL; (* Tension setpoint to downstream draw nip *)
    rPneumaticGuide_Bar : REAL; (* Proportional pressure for edge guide cylinder *)
    bVOC_High_Alarm : BOOL; (* Alarm output if LEL approaches unsafe levels *)
    bWebTracking_Fault : BOOL; (* Fault output if edge deviation exceeds tolerance *)
    bSystemReady : BOOL; (* Status flag indicating all subsystems are nominal *)
END_VAR

VAR
    (* VOC PI Controller Parameters *)
    rLEL_Setpoint : REAL := 25.0; (* Target 25% LEL for energy efficiency vs safety *)
    rLEL_Max_Limit : REAL := 45.0; (* NFPA 86 limit is typically 50% with LEL monitors *)
    Kp_VOC : REAL := 1.25;
    Ki_VOC : REAL := 0.15;
    rIntegralVOC : REAL := 0.0;

    (* Shrinkage & Tension Parameters *)
    rBaseTension_N : REAL := 250.0; (* Baseline tension for 50-micron BOPP film *)
    rThermalExpansionCoeff : REAL := 0.00015; (* Simplified coefficient for BOPP *)
    rWebWidth_mm : REAL := 1200.0;
    rTensionCompensation : REAL;
    rDeltaT : REAL;

    (* Edge Guiding PD Controller Parameters *)
    Kp_Edge : REAL := 0.85;
    Kd_Edge : REAL := 0.35;
    rLastEdgeError : REAL := 0.0;
    rDerivativeEdge : REAL;
    rNeutralPressure_Bar : REAL := 3.0; (* Mid-stroke balancing pressure *)

    (* Timing & Execution *)
    rScanTime_s : REAL := 0.01; (* Assumed 10ms execution cycle *)
END_VAR

(* -----------------------------------------------------------------------------
   Master Enable and Safety Interlocks
----------------------------------------------------------------------------- *)
IF NOT bEnable OR NOT bE_Stop THEN
    rExhaustFan_VFD_Hz := 60.0; (* Fail-safe: Purge at max speed *)
    rChillerFlowValve_Pct := 100.0; (* Fail-safe: Max cooling *)
    rWebTension_Cmd_N := 0.0;
    rPneumaticGuide_Bar := rNeutralPressure_Bar;
    rIntegralVOC := 0.0;
    bSystemReady := FALSE;
    RETURN;
ELSE
    bSystemReady := TRUE;
END_IF;

(* -----------------------------------------------------------------------------
   1. VOC Capture Ventilation Control
----------------------------------------------------------------------------- *)
(* Anti-windup integration *)
IF (rExhaustFan_VFD_Hz < 60.0) AND (rExhaustFan_VFD_Hz > 15.0) THEN
    rIntegralVOC := rIntegralVOC + ((rVOC_LEL_Percent - rLEL_Setpoint) * rScanTime_s);
END_IF;

rExhaustFan_VFD_Hz := 15.0 + ((rVOC_LEL_Percent - rLEL_Setpoint) * Kp_VOC) + (rIntegralVOC * Ki_VOC);

(* Hard constraints for VFD *)
IF rExhaustFan_VFD_Hz > 60.0 THEN
    rExhaustFan_VFD_Hz := 60.0;
ELSIF rExhaustFan_VFD_Hz < 15.0 THEN
    rExhaustFan_VFD_Hz := 15.0; (* Minimum flow to maintain negative pressure in dryer *)
END_IF;

(* Alarm Logic *)
IF rVOC_LEL_Percent > rLEL_Max_Limit THEN
    bVOC_High_Alarm := TRUE;
ELSE
    bVOC_High_Alarm := FALSE;
END_IF;

(* -----------------------------------------------------------------------------
   2. Chilling Roller Web Shrinkage Compensation
----------------------------------------------------------------------------- *)
(* Calculate the thermal shock delta *)
rDeltaT := rChillerInletTemp_C - rChillerRollerTemp_C;
IF rDeltaT < 0.0 THEN
    rDeltaT := 0.0;
END_IF;

(* Calculate required cooling valve percentage based on line speed and delta T *)
(* Higher speeds require more flow to maintain roller temperature *)
rChillerFlowValve_Pct := (rLineSpeed_m_min / 500.0) * 50.0 + (rDeltaT * 0.5);
IF rChillerFlowValve_Pct > 100.0 THEN
    rChillerFlowValve_Pct := 100.0;
END_IF;

(* Calculate tension compensation due to thermal shrinkage *)
(* As temperature drops, the web shrinks, increasing apparent tension.
   We must reduce the commanded tension from the drive to prevent web breaks. *)
rTensionCompensation := rBaseTension_N * (rDeltaT * rThermalExpansionCoeff);
rWebTension_Cmd_N := rBaseTension_N - rTensionCompensation;

(* Limit tension command to safe mechanical limits *)
IF rWebTension_Cmd_N < 50.0 THEN
    rWebTension_Cmd_N := 50.0;
ELSIF rWebTension_Cmd_N > 400.0 THEN
    rWebTension_Cmd_N := 400.0;
END_IF;

(* -----------------------------------------------------------------------------
   3. Pneumatic Edge Guiding
----------------------------------------------------------------------------- *)
(* Calculate derivative of the edge deviation (rate of change) *)
rDerivativeEdge := (rEdgeSensor_mm - rLastEdgeError) / rScanTime_s;

(* Compute the pneumatic pressure using PD control *)
(* A deviation to the positive side increases pressure to push the web back,
   a negative deviation decreases pressure to pull the web back. *)
rPneumaticGuide_Bar := rNeutralPressure_Bar + (rEdgeSensor_mm * Kp_Edge) + (rDerivativeEdge * Kd_Edge);

(* Limit pneumatic pressure between 0 and 6 Bar *)
IF rPneumaticGuide_Bar > 6.0 THEN
    rPneumaticGuide_Bar := 6.0;
ELSIF rPneumaticGuide_Bar < 0.0 THEN
    rPneumaticGuide_Bar := 0.0;
END_IF;

(* Fault Logic for Tracking *)
IF ABS(rEdgeSensor_mm) > 15.0 THEN
    bWebTracking_Fault := TRUE;
ELSE
    bWebTracking_Fault := FALSE;
END_IF;

(* Store current error for next cycle's derivative calculation *)
rLastEdgeError := rEdgeSensor_mm;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_CarpetTuftingControl
TITLE = 'Commercial Carpet Tufting Machine Control'
VERSION : 1.0

(* 
    This function block controls the highly complex synchronized movements of a 
    commercial carpet tufting machine. The machine operates at high speeds and 
    requires precise coordination between three main subsystems:
    1. Yarn Feed Roller Tension: Maintains constant tension using closed-loop PI control 
       with a load cell feedback to prevent yarn breakage or loose loops.
    2. Needle Bar Transverse Shifting: Uses a high-speed servo to shift the needle 
       bar laterally (pattern shifting) precisely while needles are out of the backing material.
    3. Looper Hook Synchronization: An electronic camming profile ensures looper hooks 
       catch the yarn exactly when the needle penetrates the primary backing, forming the loop.

    Extreme deterministic behavior is required.
*)

VAR_INPUT
    bEnable : BOOL; // System Enable command from safety relay/HMI
    bStart : BOOL; // Start Tufting Process command
    bEStop : BOOL; // Emergency Stop from hardwired safety circuit
    rSetYarnTension : REAL; // Target Yarn Tension (N)
    rSetNeedleSpeed : REAL; // Target Needle Bar Speed (Stitches/min)
    iPatternShiftTarget : INT; // Target Needle Bar Transverse Shift (mm)
    rLooperSyncOffset : REAL; // Looper Hook Phase Offset (degrees) for timing adjustment

    // Physical I/O Feedback
    rActYarnTension : REAL; // Actual tension from load cell analog input
    rActNeedlePos : REAL; // Needle bar encoder position (0-360 deg)
    rActLooperPos : REAL; // Looper encoder position (0-360 deg)
    iActPatternShift : INT; // Actual transverse shift (mm) from linear encoder
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL; // Indicates machine is ready to start
    bRunning : BOOL; // Machine is actively tufting
    bError : BOOL; // Fault condition active
    iErrorID : INT; // Error Code for HMI diagnostics

    // Physical I/O Commands
    rCmdYarnFeedSpeed : REAL; // Feed roller servo velocity command (RPM)
    rCmdNeedleMotorTorque : REAL; // Needle main drive torque/velocity command
    rCmdLooperMotorTorque : REAL; // Looper sync drive command
    iCmdPatternShiftPos : INT; // Shift servo target position (mm)
END_VAR

VAR
    iState : INT := 0; // State Machine step variable

    // Tension PI Controller Variables
    rTensionError : REAL;
    rTensionIntegral : REAL := 0.0;
    rKpTension : REAL := 3.25; // Proportional Gain
    rKiTension : REAL := 0.45; // Integral Gain

    // Looper Synchronization Variables
    rPhaseDiff : REAL;
    rLooperKp : REAL := 8.5;
    rLooperKd : REAL := 0.2;
    rPrevPhaseDiff : REAL := 0.0;
    rPhaseDeriv : REAL := 0.0;

    bInitDone : BOOL := FALSE;
END_VAR

// --- MAIN LOGIC EXECUTION ---
IF bEStop THEN
    // Immediate disabling of all kinetic energy sources
    bRunning := FALSE;
    bSystemReady := FALSE;
    bError := TRUE;
    iErrorID := 999; // Emergency Stop Active
    rCmdYarnFeedSpeed := 0.0;
    rCmdNeedleMotorTorque := 0.0;
    rCmdLooperMotorTorque := 0.0;
    iState := 0;
    RETURN; // Halt execution of further logic
END_IF;

IF NOT bEnable THEN
    bSystemReady := FALSE;
    bRunning := FALSE;
    rCmdYarnFeedSpeed := 0.0;
    rCmdNeedleMotorTorque := 0.0;
    rCmdLooperMotorTorque := 0.0;
    iState := 0;
    RETURN;
ELSE
    bSystemReady := NOT bError;
END_IF;

// State Machine for Machine Sequencing
CASE iState OF
    0: // Initialization and Standby
        IF bSystemReady AND bStart THEN
            iState := 10;
            bRunning := TRUE;
            bError := FALSE;
            iErrorID := 0;
            rTensionIntegral := 0.0; // Reset integral windup
        END_IF;

    10: // Active Tufting Control (Tension, Shifting, Camming)

        // 1. Yarn Feed Roller Tension Closed-Loop PI Control
        rTensionError := rSetYarnTension - rActYarnTension;
        rTensionIntegral := rTensionIntegral + (rTensionError * 0.01); // Assuming 10ms task cycle

        // Anti-windup clamping for PI controller
        IF rTensionIntegral > 100.0 THEN rTensionIntegral := 100.0; END_IF;
        IF rTensionIntegral < -100.0 THEN rTensionIntegral := -100.0; END_IF;

        // Calculate Feed Roller Command
        rCmdYarnFeedSpeed := (rKpTension * rTensionError) + (rKiTension * rTensionIntegral);

        // 2. Needle Bar Transverse Pattern Shifting
        // The shift should only happen when needles are clear of the backing material (e.g., pos 0-90 or 270-360)
        IF (rActNeedlePos > 270.0 OR rActNeedlePos < 90.0) THEN
            IF iActPatternShift <> iPatternShiftTarget THEN
                iCmdPatternShiftPos := iPatternShiftTarget;
            END_IF;
        END_IF;

        // 3. Looper Hook Synchronization (Electronic Camming)
        // Calculate the shortest path phase difference between master (needle) and slave (looper)
        rPhaseDiff := (rActNeedlePos + rLooperSyncOffset) - rActLooperPos;

        // Handle circular wrap-around at 360 degrees
        IF rPhaseDiff > 180.0 THEN rPhaseDiff := rPhaseDiff - 360.0; END_IF;
        IF rPhaseDiff < -180.0 THEN rPhaseDiff := rPhaseDiff + 360.0; END_IF;

        // Derivative term for looper stability at high speeds
        rPhaseDeriv := (rPhaseDiff - rPrevPhaseDiff) / 0.01;
        rPrevPhaseDiff := rPhaseDiff;

        // Output torque command for looper servo
        rCmdLooperMotorTorque := (rPhaseDiff * rLooperKp) + (rPhaseDeriv * rLooperKd);

        // 4. Main Needle Drive Control
        // In a real application, this would have its own velocity profile
        rCmdNeedleMotorTorque := rSetNeedleSpeed * 0.75; 

        // Critical Fault Detection: Loss of Looper Synchronization
        IF ABS(rPhaseDiff) > 5.0 THEN // Tight tolerance for carpet tufting
            bError := TRUE;
            iErrorID := 101; // Looper Sync Fault - Danger of Needle/Looper Crash
            iState := 99; // Transition to fault handling state
        END_IF;

        // Normal Stop Request
        IF NOT bStart THEN
            iState := 20; // Transition to controlled stopping sequence
        END_IF;

    20: // Controlled Stopping Sequence
        // Decelerate Needle
        rCmdNeedleMotorTorque := 0.0;

        // Wait for Top Dead Center (TDC) to park the machine safely
        IF (rActNeedlePos < 2.0 OR rActNeedlePos > 358.0) THEN 
            rCmdLooperMotorTorque := 0.0; // Release looper torque
            rCmdYarnFeedSpeed := 0.0; // Stop yarn feed
            bRunning := FALSE;
            iState := 0; // Return to standby
        END_IF;

    99: // Fault Handling State
        bRunning := FALSE;
        rCmdYarnFeedSpeed := 0.0;
        rCmdNeedleMotorTorque := 0.0;
        rCmdLooperMotorTorque := 0.0;
        // Require bStart to be removed before clearing error
        IF NOT bStart THEN
            // Acknowledge fault if system reset (could add bReset input)
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
