```iec-st
FUNCTION_BLOCK FB_HighSpeedLabelPressControl
TITLE = 'High-Speed Web Converting Label Press - Core Process Controller'
VERSION : '1.0'
AUTHOR : 'Lumina AI Swarm'

VAR_INPUT
    rWebSpeed_m_min           : REAL;   // Current web speed in meters per minute
    rTargetWebTension_N       : REAL;   // Target web tension in Newtons
    rActualWebTension_N       : REAL;   // Actual web tension measured by load cells
    bEnablePress              : BOOL;   // Master press enable signal
    bColdFoilEngage           : BOOL;   // Request to engage cold foil nip
    rFoilNipTargetPressure_bar: REAL;   // Target cold foil nip pressure
    rFoilNipActualPressure_bar: REAL;   // Actual pressure of foil nip
    rCoronaTargetDosage_Wmin_m2: REAL;  // Target corona dosage (Watt-min/m^2)
    rPrintRepeatLength_mm     : REAL;   // Print repeat length
    rDieRegisterError_mm      : REAL;   // Error measured by print mark sensor
    bDieRegisterEnable        : BOOL;   // Enable semi-rotary die register control
END_VAR

VAR_OUTPUT
    rFoilNipValveCommand      : REAL;   // Proportional valve command for foil nip (0-100%)
    rCoronaPowerSetpoint_kW   : REAL;   // Power setpoint to corona treater (kW)
    rDieAdvanceRetardCmd_deg  : REAL;   // Correction command to die servo (degrees)
    bSystemFault              : BOOL;   // Overall system fault flag
    iFaultCode                : INT;    // Specific fault code
END_VAR

VAR
    // Foil Nip PI Controller Variables
    rFoilKp : REAL := 2.5;
    rFoilKi : REAL := 0.15;
    rFoilError : REAL;
    rFoilIntegral : REAL;

    // Corona Power Calculation Variables
    rTreaterWidth_m : REAL := 0.5; // Web width for treatment area calculation
    rCalculatedPower_W : REAL;

    // Die Register Control Variables
    rRegisterKp : REAL := 0.8;
    rRegisterKd : REAL := 0.05;
    rPrevRegisterError : REAL;
    rRegisterDerivative : REAL;
    rMaxCorrectionStep : REAL := 2.0; // Max step per scan in degrees

    // Timers and Triggers
    fbFoilEngageDelay : TON;
    fbFaultTimer      : TON;

    // State machine
    eState : (INIT, IDLE, RAMP_UP, RUNNING, FAULT) := INIT;
END_VAR

// -----------------------------------------------------------------------------
// CONTROL LOGIC IMPLEMENTATION
// -----------------------------------------------------------------------------

// Safety and Interlock Check
IF NOT bEnablePress THEN
    rFoilNipValveCommand := 0.0;
    rCoronaPowerSetpoint_kW := 0.0;
    rDieAdvanceRetardCmd_deg := 0.0;
    eState := IDLE;
    bSystemFault := FALSE;
    iFaultCode := 0;
    RETURN;
END_IF;

// Foil Nip Pressure PI Control
IF bColdFoilEngage THEN
    rFoilError := rFoilNipTargetPressure_bar - rFoilNipActualPressure_bar;
    rFoilIntegral := rFoilIntegral + (rFoilError * 0.01); // Assuming 10ms task

    // Anti-windup
    IF rFoilIntegral > 100.0 THEN rFoilIntegral := 100.0; END_IF;
    IF rFoilIntegral < 0.0 THEN rFoilIntegral := 0.0; END_IF;

    rFoilNipValveCommand := (rFoilKp * rFoilError) + rFoilIntegral;

    // Output Limits
    IF rFoilNipValveCommand > 100.0 THEN rFoilNipValveCommand := 100.0; END_IF;
    IF rFoilNipValveCommand < 0.0 THEN rFoilNipValveCommand := 0.0; END_IF;
ELSE
    rFoilNipValveCommand := 0.0;
    rFoilIntegral := 0.0;
END_IF;

// Corona Surface Treatment Discharge Control (kW/m2)
// Calculation: Power (W) = Dosage (W*min/m2) * Speed (m/min) * Width (m)
IF rWebSpeed_m_min > 5.0 THEN
    rCalculatedPower_W := rCoronaTargetDosage_Wmin_m2 * rWebSpeed_m_min * rTreaterWidth_m;
    rCoronaPowerSetpoint_kW := rCalculatedPower_W / 1000.0;

    // Clamp max power based on typical 10kW generator
    IF rCoronaPowerSetpoint_kW > 10.0 THEN
        rCoronaPowerSetpoint_kW := 10.0;
    END_IF;
ELSE
    // Web too slow, disable corona to prevent burning substrate
    rCoronaPowerSetpoint_kW := 0.0;
END_IF;

// Semi-Rotary Die Register Correction (PD Controller)
// In semi-rotary, the die cylinder accelerates/decelerates to match repeat length.
// We provide an advance/retard offset to the base electronic cam profile.
IF bDieRegisterEnable AND rWebSpeed_m_min > 10.0 THEN
    rRegisterDerivative := (rDieRegisterError_mm - rPrevRegisterError) / 0.01; // 10ms cycle

    rDieAdvanceRetardCmd_deg := (rRegisterKp * rDieRegisterError_mm) + (rRegisterKd * rRegisterDerivative);

    // Rate limiter / Clamp
    IF rDieAdvanceRetardCmd_deg > rMaxCorrectionStep THEN
        rDieAdvanceRetardCmd_deg := rMaxCorrectionStep;
    ELSIF rDieAdvanceRetardCmd_deg < -rMaxCorrectionStep THEN
        rDieAdvanceRetardCmd_deg := -rMaxCorrectionStep;
    END_IF;

    rPrevRegisterError := rDieRegisterError_mm;
ELSE
    rDieAdvanceRetardCmd_deg := 0.0;
    rPrevRegisterError := 0.0;
END_IF;

// Basic Fault Monitoring
fbFaultTimer(IN := ABS(rFoilNipTargetPressure_bar - rFoilNipActualPressure_bar) > 2.0 AND bColdFoilEngage, PT := T#5S);
IF fbFaultTimer.Q THEN
    bSystemFault := TRUE;
    iFaultCode := 1001; // Nip Pressure deviation fault
END_IF;

END_FUNCTION_BLOCK
