Below is the expanded Siemens SCL program integrating Profinet VFD mapping and extensive fault diagnostics.

FUNCTION_BLOCK "SorterProfinetDiag"
VAR_INPUT
    Profinet_VFD_Status : ARRAY[1..5] OF Word;
    Air_Pressure_OK : Bool;
    RFID_Data : DInt;
    RFID_Valid : Bool;
    RFID_Error : Bool;
    PE_Entry : Bool;
    Encoder_Pulse : Bool;
END_VAR
VAR_OUTPUT
    Profinet_VFD_Ctrl : ARRAY[1..5] OF Word;
    Induction_Speed_Cmd : Real;
    Diverter_Valve : Bool;
    Alarm_MotorOverload : Bool;
    Alarm_AirPressureLoss : Bool;
    Alarm_RFIDFailure : Bool;
END_VAR
VAR
    Shift_Reg : ARRAY[0..2000] OF DInt;
    PE_Entry_Prev : Bool;
    Dwell_Count : Int;
    i, v : Int;
    TON_AirLoss : TON_TIME;
    TON_RFIDFail : TON_TIME;
END_VAR
BEGIN
    // Fault Diagnostics
    Alarm_MotorOverload := FALSE;
    FOR v := 1 TO 5 DO
        IF (Profinet_VFD_Status[v] AND 16#0008) <> 0 THEN // Assume bit 3 is fault/overload
            Alarm_MotorOverload := TRUE;
        END_IF;
        Profinet_VFD_Ctrl[v] := 16#047F; // Ready to operate control word
    END_FOR;

    TON_AirLoss(IN := NOT Air_Pressure_OK, PT := T#2S);
    Alarm_AirPressureLoss := TON_AirLoss.Q;

    TON_RFIDFail(IN := RFID_Error, PT := T#3S);
    Alarm_RFIDFailure := TON_RFIDFail.Q;

    // If critical alarm, stop induction
    IF Alarm_MotorOverload OR Alarm_AirPressureLoss THEN
        Induction_Speed_Cmd := 0.0;
    ELSE
        Induction_Speed_Cmd := 100.0; // Nominal speed with gap opt logic here
    END_IF;

    // Shift register & Diverter Logic
    IF Encoder_Pulse THEN
        FOR i := 2000 TO 1 BY -1 DO Shift_Reg[i] := Shift_Reg[i-1]; END_FOR;
        Shift_Reg[0] := 0;
        IF Dwell_Count > 0 THEN Dwell_Count := Dwell_Count - 1; ELSE Diverter_Valve := FALSE; END_IF;
    END_IF;

    IF PE_Entry AND NOT PE_Entry_Prev AND RFID_Valid THEN Shift_Reg[0] := RFID_Data; END_IF;
    PE_Entry_Prev := PE_Entry;

    IF Shift_Reg[500] = 1 THEN
        Diverter_Valve := TRUE;
        Dwell_Count := 20;
        Shift_Reg[500] := 0;
    END_IF;
END_FUNCTION_BLOCK
This FB now parses Profinet status words for 5 VFDs to detect overloads, applies `TON` timers for debouncing air pressure loss and RFID errors, and maps standardized control words back to the VFDs.
