FUNCTION_BLOCK FB_CZ_Puller_Control
TITLE = 'Czochralski Ingot Puller Advanced Control'
// High-precision control of Silicon Ingot Czochralski (CZ) Puller
// Subsystems: Crucible Rotation/Lift, Argon Mass Flow, Multi-zone Induction Heating

VAR_INPUT
    // Master Control
    xSystemEnable : BOOL; // Main system enable
    xAutoMode     : BOOL; // Automatic growth mode

    // Process Setpoints
    rTargetIngotDiameter : REAL; // Target ingot diameter (mm)
    rTargetPullSpeed     : REAL; // Target crystal pull speed (mm/min)
    rTargetCrucibleRot   : REAL; // Target crucible rotation (rpm)
    rTargetArgonFlow     : REAL; // Target Argon gas flow (slpm)
    rTargetMeltTemp      : REAL; // Target melt temperature (Celsius)

    // Physical Sensors (Inputs)
    rActIngotDiameter    : REAL; // Actual measured diameter (mm)
    rActMeltLevel        : REAL; // Actual melt surface level (mm)
    rActArgonFlow        : REAL; // Mass flow meter feedback (slpm)
    rActTempZone1        : REAL; // Pyrometer/TC Zone 1 (Center)
    rActTempZone2        : REAL; // Pyrometer/TC Zone 2 (Middle)
    rActTempZone3        : REAL; // Pyrometer/TC Zone 3 (Outer)
    rActCrucibleLiftPos  : REAL; // Crucible lift position (mm)

    // Safety & Interlocks
    xCoolingWaterFlowOK  : BOOL; // Cooling water flow switch
    xChamberVacuumOK     : BOOL; // Chamber vacuum level OK
    xCrucibleLimitTop    : BOOL; // Crucible overtravel top limit
    xCrucibleLimitBot    : BOOL; // Crucible overtravel bottom limit
END_VAR

VAR_OUTPUT
    // Physical Actuators (Outputs)
    rCmdCrucibleLiftSpeed: REAL; // Servo command: crucible lift speed (mm/min)
    rCmdCrucibleRotSpeed : REAL; // Servo command: crucible rotation (rpm)
    rCmdSeedLiftSpeed    : REAL; // Servo command: seed lift speed (mm/min)
    rCmdSeedRotSpeed     : REAL; // Servo command: seed rotation (rpm)
    rCmdArgonValvePos    : REAL; // Control valve: Argon flow (0-100%)

    // Heater Power Demands (0-100%)
    rCmdHeaterPwrZone1   : REAL;
    rCmdHeaterPwrZone2   : REAL;
    rCmdHeaterPwrZone3   : REAL;

    // Status and Alarms
    xReadyToGrow         : BOOL;
    xAlarmActive         : BOOL;
    iAlarmCode           : INT;
END_VAR

VAR
    // PID Controllers (Instantiated FB, assume standard PID block exists)
    fbPidTempZone1       : PID_Standard;
    fbPidTempZone2       : PID_Standard;
    fbPidTempZone3       : PID_Standard;
    fbPidArgonFlow       : PID_Standard;
    fbPidDiameter        : PID_Standard;

    // Internal State Variables
    rFilteredDiameter    : REAL;
    rMeltDepletionRate   : REAL;
    rCrucibleLiftComp    : REAL; // Compensation for melt drop

    // Timers
    tonSafetyDelay       : TON;
    tonGrowthStabilize   : TON;
END_VAR

// ==============================================================================
// 1. Safety & Interlocks Evaluation
// ==============================================================================
xAlarmActive := FALSE;
iAlarmCode := 0;

IF NOT xCoolingWaterFlowOK THEN
    xAlarmActive := TRUE;
    iAlarmCode := 101; // Cooling failure
ELSIF NOT xChamberVacuumOK THEN
    xAlarmActive := TRUE;
    iAlarmCode := 102; // Vacuum failure
END_IF;

IF xAlarmActive THEN
    // Safe state overrides
    rCmdCrucibleLiftSpeed := 0.0;
    rCmdCrucibleRotSpeed  := 0.0;
    rCmdSeedLiftSpeed     := 0.0;
    rCmdSeedRotSpeed      := 0.0;
    rCmdArgonValvePos     := 0.0;
    rCmdHeaterPwrZone1    := 0.0;
    rCmdHeaterPwrZone2    := 0.0;
    rCmdHeaterPwrZone3    := 0.0;
    xReadyToGrow          := FALSE;
    RETURN;
END_IF;

// ==============================================================================
// 2. Argon Gas Purge Mass Flow Control
// ==============================================================================
IF xSystemEnable THEN
    fbPidArgonFlow(
        EN := TRUE,
        SP := rTargetArgonFlow,
        PV := rActArgonFlow,
        Kp := 2.5,
        Ti := 1.0,
        Td := 0.0,
        CV => rCmdArgonValvePos
    );
ELSE
    rCmdArgonValvePos := 0.0;
END_IF;

// ==============================================================================
// 3. Multi-zone Induction Heater Profiling
// ==============================================================================
// Zone 1 (Center) tracks target directly.
// Zone 2 and 3 have offsets to maintain radial thermal gradient.
IF xSystemEnable THEN
    fbPidTempZone1(
        EN := TRUE,
        SP := rTargetMeltTemp,
        PV := rActTempZone1,
        Kp := 15.0, Ti := 30.0, Td := 5.0,
        CV => rCmdHeaterPwrZone1
    );

    fbPidTempZone2(
        EN := TRUE,
        SP := rTargetMeltTemp + 5.0, // Radial gradient
        PV := rActTempZone2,
        Kp := 12.0, Ti := 30.0, Td := 4.0,
        CV => rCmdHeaterPwrZone2
    );

    fbPidTempZone3(
        EN := TRUE,
        SP := rTargetMeltTemp + 12.0, // Outer edge hotter
        PV := rActTempZone3,
        Kp := 10.0, Ti := 30.0, Td := 4.0,
        CV => rCmdHeaterPwrZone3
    );
ELSE
    rCmdHeaterPwrZone1 := 0.0;
    rCmdHeaterPwrZone2 := 0.0;
    rCmdHeaterPwrZone3 := 0.0;
END_IF;

// ==============================================================================
// 4. Crucible Rotation and Lift Servo Coupling (Melt Level Control)
// ==============================================================================
// As the crystal is pulled, melt is consumed. Crucible must rise to keep melt surface stationary.
// Calculate required lift speed based on mass balance (simplified ratio here).
IF xAutoMode AND xSystemEnable AND NOT xCrucibleLimitTop THEN

    // Basic rotation commands
    rCmdCrucibleRotSpeed := rTargetCrucibleRot;

    // Diameter Control via Pull Speed modulation
    fbPidDiameter(
        EN := TRUE,
        SP := rTargetIngotDiameter,
        PV := rActIngotDiameter,
        Kp := 0.5, Ti := 10.0, Td := 1.0,
        CV => rCmdSeedLiftSpeed
    );

    // Feedforward Crucible Lift Compensation
    // Melt drops proportional to pull speed and cross-sectional area ratio
    // A_crystal / A_crucible ~ (D_crystal^2) / (D_crucible^2)
    // Assume D_crucible = 600mm
    rCrucibleLiftComp := rCmdSeedLiftSpeed * ((rActIngotDiameter * rActIngotDiameter) / (600.0 * 600.0));

    // Add minor trim from actual melt level sensor (optical/laser)
    IF rActMeltLevel < 0.0 THEN
        rCmdCrucibleLiftSpeed := rCrucibleLiftComp + 0.1;
    ELSIF rActMeltLevel > 0.0 THEN
        rCmdCrucibleLiftSpeed := rCrucibleLiftComp - 0.1;
    ELSE
        rCmdCrucibleLiftSpeed := rCrucibleLiftComp;
    END_IF;

    // Seed rotation
    rCmdSeedRotSpeed := 15.0; // Fixed nominal for this phase

ELSE
    IF NOT xSystemEnable THEN
        rCmdCrucibleRotSpeed  := 0.0;
        rCmdCrucibleLiftSpeed := 0.0;
        rCmdSeedLiftSpeed     := 0.0;
        rCmdSeedRotSpeed      := 0.0;
    END_IF;
END_IF;

xReadyToGrow := xSystemEnable AND (ABS(rActTempZone1 - rTargetMeltTemp) < 2.0);

END_FUNCTION_BLOCK
