FUNCTION_BLOCK FB_MiningPantographSubstation
(*
================================================================================
NAME: FB_MiningPantographSubstation
AUTHOR: 40-Year Veteran PLC Automation Architect
DESCRIPTION:
Ultra-complex control for a Next-Gen Heavy-Duty Electric Mining Haul Truck 
Pantograph Substation. This logic manages 3-megawatt dynamic pantograph 
contact voltage regulation, regenerative braking to grid harmonic filtering, 
and overhead catenary line droop/tension active compensation.
================================================================================
*)
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main system enable command *)
    bEmergencyStop          : BOOL;     (* Safety loop E-Stop relay OK signal (Normally Closed) *)
    rGridVoltageKV          : REAL;     (* Measured incoming grid voltage (kV) *)
    rPantographContactForce : REAL;     (* Dynamic contact force from load cell (kN) *)
    rCatenaryTension        : REAL;     (* Catenary tension measurement (kN) *)
    rRegenCurrentA          : REAL;     (* High-frequency regenerative braking current (A) *)
    rAmbientTempC           : REAL;     (* Ambient temperature for thermal compensation (C) *)
    rTruckVelocityKmph      : REAL;     (* Approaching truck speed for feed-forward control *)
END_VAR

VAR_OUTPUT
    bSubstationReady        : BOOL;     (* True when substation is healthy and ready to deliver power *)
    rVoltageReferenceKV     : REAL;     (* Dynamic voltage reference setpoint to power converter (kV) *)
    rActiveTensionCmd       : REAL;     (* Command to hydraulic tensioner for catenary droop comp (kN) *)
    bHarmonicFilterEnable   : BOOL;     (* Enables active harmonic filter during regen braking *)
    bCriticalAlarm          : BOOL;     (* Critical fault requiring immediate power removal *)
    rThermalDeratingFactor  : REAL;     (* Derating multiplier (0.0 to 1.0) based on thermal limits *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine *)
    tStartupDelay           : TON;      (* Delay timer for converter magnetization *)
    tGridLossDebounce       : TON;      (* Debounce for grid loss detection *)
    tHarmonicFilterDelay    : TOF;      (* Off-delay to ensure filter completes discharge cycle *)

    rTargetForce            : REAL := 120.0;    (* Target pantograph contact force (kN) *)
    rBaseTension            : REAL := 25.0;     (* Nominal catenary base tension (kN) *)

    rIntegralError          : REAL := 0.0;      (* Integrator for tension PI loop *)
    rProportionalGain       : REAL := 1.85;     (* Proportional gain for tension control *)
    rIntegralGain           : REAL := 0.05;     (* Integral gain for tension control *)
    rVoltageSetpointBase    : REAL := 3.3;      (* Base DC link voltage for truck (kV) *)

    bOverTempFault          : BOOL := FALSE;
    bTensionFault           : BOOL := FALSE;
END_VAR

(* === MAIN SAFETY AND PRE-CHECKS === *)
IF NOT bEmergencyStop THEN
    bSubstationReady := FALSE;
    bCriticalAlarm := TRUE;
    rVoltageReferenceKV := 0.0;
    rActiveTensionCmd := rBaseTension; 
    bHarmonicFilterEnable := FALSE;
    iState := 999; (* FAULT STATE *)
    RETURN;
END_IF;

(* Thermal Derating Calculation *)
IF rAmbientTempC > 50.0 THEN
    rThermalDeratingFactor := 0.5;
    bOverTempFault := TRUE;
ELSIF rAmbientTempC > 40.0 THEN
    rThermalDeratingFactor := 1.0 - ((rAmbientTempC - 40.0) * 0.05);
    bOverTempFault := FALSE;
ELSE
    rThermalDeratingFactor := 1.0;
    bOverTempFault := FALSE;
END_IF;

(* Catenary Tension Active PI Control with Feed-Forward *)
(* High truck velocity requires stiffer tension to prevent wave reflection *)
rProportionalGain := 1.85 + (rTruckVelocityKmph * 0.015);
rIntegralError := rIntegralError + ((rTargetForce - rPantographContactForce) * rIntegralGain);

(* Clamp Integrator (Anti-Windup) *)
IF rIntegralError > 20.0 THEN
    rIntegralError := 20.0;
ELSIF rIntegralError < -20.0 THEN
    rIntegralError := -20.0;
END_IF;

rActiveTensionCmd := rBaseTension + (rTargetForce - rPantographContactForce) * rProportionalGain + rIntegralError;

(* Limit Active Tension Command *)
IF rActiveTensionCmd > 50.0 THEN
    rActiveTensionCmd := 50.0;
ELSIF rActiveTensionCmd < 10.0 THEN
    rActiveTensionCmd := 10.0;
END_IF;

(* Regenerative Braking Harmonic Filter Logic *)
(* Engage filter if regen current exceeds 500A, hold for 10s after it drops *)
IF rRegenCurrentA > 500.0 THEN
    tHarmonicFilterDelay(IN := TRUE, PT := T#10S);
ELSE
    tHarmonicFilterDelay(IN := FALSE, PT := T#10S);
END_IF;
bHarmonicFilterEnable := tHarmonicFilterDelay.Q;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE - WAIT FOR ENABLE *)
        bSubstationReady := FALSE;
        bCriticalAlarm := FALSE;
        rVoltageReferenceKV := 0.0;
        IF bSystemEnable AND NOT bOverTempFault THEN
            iState := 10;
        END_IF;

    10: (* PRE-CHARGE CONVERTERS *)
        tStartupDelay(IN := TRUE, PT := T#3S);
        rVoltageReferenceKV := rVoltageSetpointBase * 0.5; (* 50% voltage for pre-charge *)
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RUNNING / ACTIVE REGULATION *)
        bSubstationReady := TRUE;
        (* Dynamically regulate voltage based on grid conditions and thermal derating *)
        rVoltageReferenceKV := (rVoltageSetpointBase + (rGridVoltageKV * 0.02)) * rThermalDeratingFactor;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSubstationReady := FALSE;
        bCriticalAlarm := TRUE;
        rVoltageReferenceKV := 0.0;
        (* Require System Enable toggle to reset fault, provided E-Stop is clear *)
        IF NOT bSystemEnable AND bEmergencyStop THEN
            iState := 0;
            bCriticalAlarm := FALSE;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
