         "Heater_Output" := 0.0;
         "Vacuum_Valve_Output" := 0.0;
         "Condenser_Compressor" := FALSE;
         "Defrost_Heater" := FALSE;

      1: // Sublimation
         "Defrost_Heater" := FALSE;
