FUNCTION_BLOCK FB_GESS_WinchControl
TITLE = 'Gravity Energy Storage System - Multi-Shaft Winch Control'
// Highly complex control scenario for Gravity Energy Storage System
// Features: Multi-shaft synchronous generator hoisting, trolley braking algorithms, regenerative descent power tracking.

VAR_INPUT
    bEnable                 : BOOL; // System enable
    eMode                   : INT;  // 0: Standby, 1: Hoisting (Charging), 2: Descending (Discharging)
    lrMassBlockWeight       : LREAL; // Weight of the current mass block (kg)
    lrTargetPosition        : LREAL; // Target elevation (m)
    lrCurrentPosition       : LREAL; // Current elevation (m)
    lrGridFrequency         : LREAL; // Grid frequency (Hz)
    lrGridVoltage           : LREAL; // Grid voltage (V)
    lrMaxPowerLimit         : LREAL; // Maximum allowable power draw/feed (kW)
    bTrolleyEngaged         : BOOL;  // Mass block trolley engagement status
    bEmergencyStop          : BOOL;  // E-Stop active
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;
    bMoving                 : BOOL;
    lrSpeedCmd              : LREAL; // Command speed to variable frequency drives (m/s)
    lrTorqueCmd             : LREAL; // Command torque (Nm)
    lrBrakeForce            : LREAL; // Mechanical brake force command (%)
    lrRegenPower            : LREAL; // Calculated regenerative power (kW)
    bFault                  : BOOL;
    nFaultID                : INT;
END_VAR

VAR
    lrSpeedError            : LREAL;
    lrPosError              : LREAL;
    lrKp_Pos                : LREAL := 1.5;
    lrKi_Pos                : LREAL := 0.05;
    lrPosIntegral           : LREAL := 0.0;

    lrAccelRamp             : LREAL := 0.5; // m/s^2
    lrMaxSpeed              : LREAL := 2.5; // m/s

    lrGravity               : LREAL := 9.81;
    lrWinchRadius           : LREAL := 1.25; // m
    lrGearboxRatio          : LREAL := 50.0;
    lrEfficiency            : LREAL := 0.92;

    bHoldBrakeCmd           : BOOL;
    bDynamicBraking         : BOOL;
    tonBrakeDelay           : TON;
END_VAR

// State Machine and Fault Handling
IF bEmergencyStop THEN
    bFault := TRUE;
    nFaultID := 99;
    lrSpeedCmd := 0.0;
    lrTorqueCmd := 0.0;
    lrBrakeForce := 100.0;
    bMoving := FALSE;
    RETURN;
END_IF;

bSystemReady := bEnable AND NOT bFault AND bTrolleyEngaged;

IF NOT bSystemReady THEN
    lrSpeedCmd := 0.0;
    lrBrakeForce := 100.0;
    RETURN;
END_IF;

// Position Control Loop
lrPosError := lrTargetPosition - lrCurrentPosition;
lrPosIntegral := lrPosIntegral + (lrPosError * 0.01); // Assuming 10ms task
IF lrPosIntegral > 10.0 THEN lrPosIntegral := 10.0; END_IF;
IF lrPosIntegral < -10.0 THEN lrPosIntegral := -10.0; END_IF;

CASE eMode OF
    0: // Standby
        lrSpeedCmd := 0.0;
        lrTorqueCmd := (lrMassBlockWeight * lrGravity * lrWinchRadius) / (lrGearboxRatio * lrEfficiency);
        lrBrakeForce := 100.0;
        bMoving := FALSE;

    1: // Hoisting (Charging)
        bMoving := TRUE;
        lrBrakeForce := 0.0; // Release brakes
        lrSpeedCmd := (lrPosError * lrKp_Pos) + lrPosIntegral;
        IF lrSpeedCmd > lrMaxSpeed THEN lrSpeedCmd := lrMaxSpeed; END_IF;
        IF lrSpeedCmd < 0.0 THEN lrSpeedCmd := 0.0; END_IF;

        // Torque feedforward
        lrTorqueCmd := (lrMassBlockWeight * lrGravity * lrWinchRadius) / (lrGearboxRatio * lrEfficiency);

        // Power limit check
        IF (lrSpeedCmd * lrTorqueCmd) > (lrMaxPowerLimit * 1000.0) THEN
            lrSpeedCmd := (lrMaxPowerLimit * 1000.0) / lrTorqueCmd;
        END_IF;

    2: // Descending (Discharging)
        bMoving := TRUE;
        lrBrakeForce := 0.0;
        lrSpeedCmd := (lrPosError * lrKp_Pos) + lrPosIntegral;
        IF lrSpeedCmd < -lrMaxSpeed THEN lrSpeedCmd := -lrMaxSpeed; END_IF;
        IF lrSpeedCmd > 0.0 THEN lrSpeedCmd := 0.0; END_IF;

        // Regenerative Torque control (acting as generator)
        lrTorqueCmd := -1.0 * (lrMassBlockWeight * lrGravity * lrWinchRadius * lrEfficiency) / lrGearboxRatio;

        // Regenerative Power calculation
        lrRegenPower := ABS(lrSpeedCmd * lrTorqueCmd) / 1000.0;

        // Grid synch constraint
        IF lrGridFrequency > 50.5 OR lrGridVoltage > 440.0 THEN
            // Grid overvoltage/overfrequency, apply mechanical braking to dissipate energy
            bDynamicBraking := TRUE;
            lrBrakeForce := 50.0;
            lrRegenPower := lrRegenPower * 0.5; // Throttle regen
        ELSE
            bDynamicBraking := FALSE;
        END_IF;

    ELSE
        bFault := TRUE;
        nFaultID := 1; // Invalid mode
END_CASE;

// Brake sequencing
tonBrakeDelay(IN:= (lrSpeedCmd < 0.05 AND lrSpeedCmd > -0.05) AND eMode = 0, PT:= T#2S);
IF tonBrakeDelay.Q THEN
    bHoldBrakeCmd := TRUE;
    lrBrakeForce := 100.0;
ELSE
    bHoldBrakeCmd := FALSE;
END_IF;

END_FUNCTION_BLOCK
