FUNCTION_BLOCK FB_WireBonderControl
VAR_INPUT
    bEnable : BOOL; // Enable the wire bonding sequence
    bStartBond : BOOL; // Trigger start of bonding cycle
    rTargetZ_Position : REAL; // Target Z-axis position (um)
    rTargetForce_mN : REAL; // Target bonding force (mN)
    rUSG_Power_W : REAL; // Ultrasonic generator power target (W)
    tBondTime : TIME; // Duration of the ultrasonic pulse
    bLeadframeIndexDone : BOOL; // Signal from indexer that leadframe is in position
END_VAR

VAR_OUTPUT
    bBusy : BOOL; // Bonding cycle in progress
    bDone : BOOL; // Bonding cycle complete
    bError : BOOL; // Error active
    iErrorID : INT; // Error code
    rActualZ_Position : REAL; // Current Z-axis position (um)
    rActualForce_mN : REAL; // Current force (mN)
    bIndexerStart : BOOL; // Command to start next leadframe index
    bEFO_Fire : BOOL; // Fire Electronic Flame-Off to form free air ball
END_VAR

VAR
    iState : INT := 0; // State machine state
    fbTonBondPulse : TON; // Timer for bonding pulse duration
    fbTonEFO : TON; // Timer for EFO duration
    fbPidForce : PID; // PID controller for Z-axis bonding force
    rZ_TrajectoryTarget : REAL; // Intermediate Z target for trajectory generation
    iTrajectoryStep : INT; // Step within trajectory generation
    bZAxisInPosition : BOOL;
    bForceReached : BOOL;
    rUSG_Frequency_kHz : REAL := 120.0; // Nominal USG frequency
    rUSG_CurrentFeedback : REAL;
    bEFO_Done : BOOL;
END_VAR

// Main State Machine for Wire Bonding Cycle
CASE iState OF
    0: // Idle State
        bBusy := FALSE;
        bDone := FALSE;
        bError := FALSE;
        iErrorID := 0;
        bIndexerStart := FALSE;
        bEFO_Fire := FALSE;

        IF bEnable AND bStartBond AND bLeadframeIndexDone THEN
            bBusy := TRUE;
            iState := 10;
        END_IF;

    10: // Form Free Air Ball (FAB) using EFO
        bEFO_Fire := TRUE;
        fbTonEFO(IN:= TRUE, PT:= T#2ms);
        IF fbTonEFO.Q THEN
            bEFO_Fire := FALSE;
            fbTonEFO(IN:= FALSE);
            bEFO_Done := TRUE;
            iState := 20;
        END_IF;

    20: // Fast Z-Axis approach to search height
        rZ_TrajectoryTarget := rTargetZ_Position + 150.0; // 150um above target
        // Simulated tracking logic
        IF ABS(rActualZ_Position - rZ_TrajectoryTarget) < 5.0 THEN
            bZAxisInPosition := TRUE;
            iState := 30;
        END_IF;

    30: // Search speed descent and Touchdown detection
        rZ_TrajectoryTarget := rTargetZ_Position;
        // Monitor for physical contact (force feedback spike)
        IF rActualForce_mN > 10.0 THEN // Touchdown threshold
            iState := 40;
        END_IF;

    40: // Apply Bonding Force (First Bond)
        fbPidForce(
            ACT:= rActualForce_mN,
            SET:= rTargetForce_mN,
            KP:= 1.5,
            KI:= 0.1,
            KD:= 0.05
        );
        IF ABS(rActualForce_mN - rTargetForce_mN) < 2.0 THEN
            bForceReached := TRUE;
            iState := 50;
        END_IF;

    50: // Apply Ultrasonic Energy
        // Enable USG transducer tuning and apply power
        fbTonBondPulse(IN:= TRUE, PT:= tBondTime);
        IF fbTonBondPulse.Q THEN
            fbTonBondPulse(IN:= FALSE);
            iState := 60;
        END_IF;

    60: // Loop control and Second Bond (simplified)
        // Move Z up, XY move, Z down, second bond logic...
        iState := 70; // Jumping straight to completion for brevity

    70: // Complete and request index
        bBusy := FALSE;
        bDone := TRUE;
        bIndexerStart := TRUE; // Signal leadframe indexer
        IF NOT bStartBond THEN
            bIndexerStart := FALSE;
            iState := 0;
        END_IF;

    999: // Error Handling
        bBusy := FALSE;
        bError := TRUE;
        // Error recovery logic here
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

ELSE
    iState := 0;
END_CASE;

// Safety and Interlock Monitoring
IF bBusy AND NOT bEnable THEN
    iErrorID := 1001; // Emergency Stop / Enable Lost
    iState := 999;
END_IF;
END_FUNCTION_BLOCK
