FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bStart_Mashing : BOOL;
    rActual_Temp_C : REAL;
    rTarget_Volume_L : REAL;
    rActual_Volume_L : REAL;
    rDiff_Pressure_mbar : REAL;
    bSparge_Request : BOOL;
END_VAR
VAR_OUTPUT
    bPump_Recirculation_Run : BOOL;
    rHeater_Output_Pct : REAL;
    rSparge_Valve_Open_Pct : REAL;
    iCurrent_Step : INT;
    bMash_Complete : BOOL;
    sStatus_Message : STRING[50];
END_VAR
VAR
    iState : INT := 0;
    rError : REAL;
    rIntegral : REAL;
    rKp : REAL := 2.5;
    rKi : REAL := 0.1;
    timer_Step : TON;
    rTarget_Temp_C : REAL;
    tStep_Duration : TIME;
END_VAR

// Complex multi-step mashing profile
CASE iState OF
    0: // Idle
        bPump_Recirculation_Run := FALSE;
        rHeater_Output_Pct := 0.0;
        rSparge_Valve_Open_Pct := 0.0;
        iCurrent_Step := 0;
        bMash_Complete := FALSE;
        sStatus_Message := 'IDLE';
        IF bStart_Mashing THEN
            iState := 10;
        END_IF;

    10: // Protein Rest (50°C for 20 mins)
        iCurrent_Step := 1;
        sStatus_Message := 'PROTEIN REST';
        rTarget_Temp_C := 50.0;
        tStep_Duration := T#20M;
        bPump_Recirculation_Run := TRUE;

        timer_Step(IN := (rActual_Temp_C >= (rTarget_Temp_C - 0.5)), PT := tStep_Duration);
        IF timer_Step.Q THEN
            timer_Step(IN := FALSE);
            iState := 20;
        END_IF;

    20: // Beta Amylase Saccharification (62°C for 45 mins)
        iCurrent_Step := 2;
        sStatus_Message := 'BETA AMYLASE';
        rTarget_Temp_C := 62.0;
        tStep_Duration := T#45M;
        bPump_Recirculation_Run := TRUE;

        timer_Step(IN := (rActual_Temp_C >= (rTarget_Temp_C - 0.5)), PT := tStep_Duration);
        IF timer_Step.Q THEN
            timer_Step(IN := FALSE);
            iState := 30;
        END_IF;

    30: // Alpha Amylase Saccharification (72°C for 30 mins)
        iCurrent_Step := 3;
        sStatus_Message := 'ALPHA AMYLASE';
        rTarget_Temp_C := 72.0;
        tStep_Duration := T#30M;
        bPump_Recirculation_Run := TRUE;

        timer_Step(IN := (rActual_Temp_C >= (rTarget_Temp_C - 0.5)), PT := tStep_Duration);
        IF timer_Step.Q THEN
            timer_Step(IN := FALSE);
            iState := 40;
        END_IF;

    40: // Mash Out (78°C for 10 mins)
        iCurrent_Step := 4;
        sStatus_Message := 'MASH OUT';
        rTarget_Temp_C := 78.0;
        tStep_Duration := T#10M;
        bPump_Recirculation_Run := TRUE;

        timer_Step(IN := (rActual_Temp_C >= (rTarget_Temp_C - 0.5)), PT := tStep_Duration);
        IF timer_Step.Q THEN
            timer_Step(IN := FALSE);
            iState := 50;
        END_IF;

    50: // Lautering and Sparge
        iCurrent_Step := 5;
        sStatus_Message := 'LAUTERING / SPARGE';
        bPump_Recirculation_Run := FALSE;
        rTarget_Temp_C := 78.0; // Maintain mash out temp

        // Sparge differential pressure logic
        IF bSparge_Request THEN
            IF rDiff_Pressure_mbar > 20.0 THEN
                // Bed compacting, reduce flow
                rSparge_Valve_Open_Pct := rSparge_Valve_Open_Pct - 0.5;
            ELSIF rDiff_Pressure_mbar < 10.0 THEN
                // Increase flow
                rSparge_Valve_Open_Pct := rSparge_Valve_Open_Pct + 0.5;
            END_IF;

            // Limit bounds
            IF rSparge_Valve_Open_Pct > 100.0 THEN rSparge_Valve_Open_Pct := 100.0; END_IF;
            IF rSparge_Valve_Open_Pct < 0.0 THEN rSparge_Valve_Open_Pct := 0.0; END_IF;
        ELSE
            rSparge_Valve_Open_Pct := 0.0;
        END_IF;

        IF rActual_Volume_L >= rTarget_Volume_L THEN
            iState := 60;
        END_IF;

    60: // Complete
        bPump_Recirculation_Run := FALSE;
        rHeater_Output_Pct := 0.0;
        rSparge_Valve_Open_Pct := 0.0;
        bMash_Complete := TRUE;
        sStatus_Message := 'COMPLETE';
        IF NOT bStart_Mashing THEN
            iState := 0;
        END_IF;
END_CASE

// PID Temperature Control for Heater Output
IF iState >= 10 AND iState <= 50 THEN
    rError := rTarget_Temp_C - rActual_Temp_C;
    IF rError > 0.0 THEN
        rIntegral := rIntegral + rError * 0.1; // Assuming 100ms cycle time
        rHeater_Output_Pct := (rKp * rError) + (rKi * rIntegral);
    ELSE
        rHeater_Output_Pct := 0.0;
    END_IF;

    // Bounds checking
    IF rHeater_Output_Pct > 100.0 THEN
        rHeater_Output_Pct := 100.0;
        rIntegral := rIntegral - rError * 0.1; // Anti-windup
    END_IF;
    IF rHeater_Output_Pct < 0.0 THEN
        rHeater_Output_Pct := 0.0;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
