FUNCTION_BLOCK FB_AdvancedAtomicLayerEtching_Controller
VAR_INPUT
    bEnable                 : BOOL;     (* Main enable signal to begin ALE sequence *)
    bEmergencyStop          : BOOL;     (* Hardware E-Stop and chamber safety interlock *)
    rChamberPressure        : REAL;     (* Feedback from capacitance manometer (mTorr) *)
    rSubstrateTemp          : REAL;     (* Feedback from ESC wafer chuck (deg C) *)
    bOesEndpointTrigger     : BOOL;     (* Optical Emission Spectroscopy Monolayer Endpoint detect *)
    rRfForwardPower         : REAL;     (* Measured Forward RF Power (Watts) *)
    rReactantFlowRate       : REAL;     (* Mass flow controller feedback (sccm) *)
    bPlasmaStrikeIgnited    : BOOL;     (* Plasma strike confirmation via RF impedance monitor *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System initialized and ready for cyclic processing *)
    bEtchCycleActive        : BOOL;     (* Indicates active etching sequence execution *)
    rPressureSetPoint       : REAL;     (* Chamber pressure control loop setpoint (mTorr) *)
    rRfPowerCmd             : REAL;     (* Command to RF Generator for ion bombardment (Watts) *)
    bReactantValveOpen      : BOOL;     (* Pulsed ALD/ALE valve command for precursor injection *)
    bPurgeValveOpen         : BOOL;     (* Inert gas purge valve command *)
    bAlarm                  : BOOL;     (* Fault and safety interlock violation output *)
    iCurrentCycleCount      : INT;      (* Number of ALE cycles successfully completed *)
    sStatusMessage          : STRING(80); (* Diagnostic machine state string *)
END_VAR

VAR
    iState                  : INT := 0; (* Main Finite State Machine step index *)
    iTargetCycles           : INT := 500; (* Target number of atomic layers to etch *)

    tAdsorptionTimer        : TON;
    tPurge1Timer            : TON;
    tBombardmentTimer       : TON;
    tPurge2Timer            : TON;
    tWatchdogTimer          : TON;

    rNominalPressure        : REAL := 15.0; (* 15 mTorr nominal process pressure *)
    rRfPulsedPower          : REAL := 250.0; (* 250 Watts for precise ion energy control *)

    bInitDone               : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC START === *)
(* 1. Safety Interlocks and Hardware Constraints *)
IF NOT bEmergencyStop THEN
    iState := 999; (* Enter Fault State immediately *)
END_IF;

(* 2. Main Process State Machine *)
CASE iState OF
    0: (* STATE 0: IDLE AND INITIALIZATION *)
        bSystemReady := TRUE;
        bEtchCycleActive := FALSE;
        bReactantValveOpen := FALSE;
        bPurgeValveOpen := FALSE;
        rRfPowerCmd := 0.0;
        rPressureSetPoint := 0.0;
        bAlarm := FALSE;
        sStatusMessage := 'Idle - Waiting for Enable';

        IF bEnable AND bEmergencyStop THEN
            bSystemReady := FALSE;
            bEtchCycleActive := TRUE;
            iCurrentCycleCount := 0;
            iState := 10;
        END_IF;

    10: (* STATE 10: STEP A - PRECURSOR ADSORPTION (SELF-LIMITING) *)
        sStatusMessage := 'Step A: Reactant Adsorption Phase';
        rPressureSetPoint := rNominalPressure;
        bReactantValveOpen := TRUE;
        bPurgeValveOpen := FALSE;
        rRfPowerCmd := 0.0;

        tAdsorptionTimer(IN := TRUE, PT := T#200MS); (* Ultra-fast ALD valve timing *)
        IF tAdsorptionTimer.Q THEN
            tAdsorptionTimer(IN := FALSE);
            bReactantValveOpen := FALSE;
            iState := 20;
        END_IF;

    20: (* STATE 20: STEP B - FIRST INERT PURGE *)
        sStatusMessage := 'Step B: Precursor Purge Phase';
        bPurgeValveOpen := TRUE;

        tPurge1Timer(IN := TRUE, PT := T#1500MS);
        IF tPurge1Timer.Q THEN
            tPurge1Timer(IN := FALSE);
            bPurgeValveOpen := FALSE;
            iState := 30;
        END_IF;

    30: (* STATE 30: STEP C - ION BOMBARDMENT (DESORPTION OF VOLATILE SPECIES) *)
        sStatusMessage := 'Step C: RF Plasma Ion Bombardment';
        rPressureSetPoint := rNominalPressure * 0.8; (* Lower pressure for longer mean free path *)
        rRfPowerCmd := rRfPulsedPower;

        tBombardmentTimer(IN := TRUE, PT := T#800MS);
        IF tBombardmentTimer.Q OR bOesEndpointTrigger THEN
            (* Terminate early if OES detects complete monolayer removal *)
            tBombardmentTimer(IN := FALSE);
            rRfPowerCmd := 0.0;
            iState := 40;
        END_IF;

    40: (* STATE 40: STEP D - SECOND INERT PURGE *)
        sStatusMessage := 'Step D: Volatile Byproduct Purge Phase';
        bPurgeValveOpen := TRUE;

        tPurge2Timer(IN := TRUE, PT := T#1200MS);
        IF tPurge2Timer.Q THEN
            tPurge2Timer(IN := FALSE);
            bPurgeValveOpen := FALSE;
            iCurrentCycleCount := iCurrentCycleCount + 1;

            IF iCurrentCycleCount >= iTargetCycles THEN
                iState := 50; (* Etch complete *)
            ELSE
                iState := 10; (* Loop to next layer *)
            END_IF;
        END_IF;

    50: (* STATE 50: PROCESS COMPLETE *)
        sStatusMessage := 'Process Complete - Target Cycles Reached';
        bEtchCycleActive := FALSE;
        rPressureSetPoint := 0.0;

        IF NOT bEnable THEN
            iState := 0; (* Reset to idle *)
        END_IF;

    999: (* STATE 999: FAULT AND EMERGENCY STOP *)
        bSystemReady := FALSE;
        bEtchCycleActive := FALSE;
        bReactantValveOpen := FALSE;
        bPurgeValveOpen := FALSE;
        rRfPowerCmd := 0.0;
        rPressureSetPoint := 0.0;
        bAlarm := TRUE;
        sStatusMessage := 'CRITICAL FAULT: Emergency Stop Activated';

        IF bEmergencyStop AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0; (* Acknowledge fault by dropping enable *)
        END_IF;

    ELSE
        iState := 999; (* Unhandled state fall-through *)
END_CASE;

(* 3. Process Watchdog and Limits Verification *)
tWatchdogTimer(IN := (iState >= 10 AND iState <= 40), PT := T#10S);
IF tWatchdogTimer.Q THEN
    iState := 999; (* Cycle took too long, hard fault *)
    tWatchdogTimer(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK
