FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Tissue Rewinder Line Control'
// Advanced control logic for Tissue Paper Rewinder Line
// Including log saw cutting synchronization, perforation blade timing logic, and tail gluing servo profiling.

VAR_INPUT
    bEnable : BOOL; // Enable block
    bReset : BOOL; // Reset fault
    lrLineSpeedMaster : LREAL; // Master line speed [m/min]
    lrWebTensionAct : LREAL; // Actual web tension [N]
    lrWebTensionRef : LREAL; // Reference web tension [N]

    // Perforation Settings
    lrPerfPitch_mm : LREAL := 115.0; // Perforation pitch length in mm
    lrPerfBladeDiameter_mm : LREAL := 250.0; // Perforation blade roll diameter

    // Log Saw Settings
    lrLogSawCutLength_mm : LREAL := 100.0; // Log saw cut length
    lrLogSawBladeDiameter_mm : LREAL := 600.0; // Log saw blade diameter
    bSawCutRequest : BOOL; // Request to cut

    // Tail Gluing Settings
    lrGlueApplicationPos_deg : LREAL := 45.0; // Angle for glue application
    lrGlueViscosityFactor : LREAL := 1.0; // Viscosity compensation
END_VAR

VAR_OUTPUT
    bReady : BOOL; // System is ready
    bFault : BOOL; // Fault active
    iFaultCode : INT; // Fault code

    // Servo References
    lrPerfServoVelRef : LREAL; // Perforation servo velocity reference [rad/s]
    lrLogSawServoPosRef : LREAL; // Log saw servo position reference [rad]
    lrGlueServoVelRef : LREAL; // Tail gluing servo velocity reference [rad/s]

    // Status
    bPerfSyncActive : BOOL;
    bSawSyncActive : BOOL;
    bGlueApplicationActive : BOOL;
END_VAR

VAR
    // Internal States
    eState : INT := 0; // State machine step
    lrMasterPos : LREAL; // Master virtual axis position

    // Perforation calc
    lrPerfCircumference : LREAL;
    lrPerfRatio : LREAL;

    // Log Saw calc
    lrSawSyncPos : LREAL;
    lrSawAccelRamp : LREAL;

    // Gluing calc
    lrGlueProfileVal : LREAL;

    // Timers
    tSawDwellTimer : TON;
    tGlueTimer : TON;
END_VAR

// -----------------------------------------------------------------------------
// Initialize and calculate constants
// -----------------------------------------------------------------------------
IF bReset THEN
    bFault := FALSE;
    iFaultCode := 0;
    eState := 0;
END_IF

IF NOT bEnable THEN
    bReady := FALSE;
    lrPerfServoVelRef := 0.0;
    lrLogSawServoPosRef := 0.0;
    lrGlueServoVelRef := 0.0;
    bPerfSyncActive := FALSE;
    bSawSyncActive := FALSE;
    bGlueApplicationActive := FALSE;
    RETURN;
END_IF

bReady := TRUE;

// Calculate Perforation Circumference
lrPerfCircumference := lrPerfBladeDiameter_mm * 3.14159265359;

// Calculate Perforation Ratio (Line speed to Perf roll speed)
// Assuming one blade on the roll. To get the required pitch:
// V_perf = V_line * (lrPerfCircumference / lrPerfPitch_mm) ? 
// Actually, to get pitch P, the roll must rotate 1 rev per P mm of web.
// So angular velocity w_perf = (V_line / P) * 2 * PI.
IF lrPerfPitch_mm > 0.0 THEN
    // V_line is m/min -> m/s is V_line / 60
    lrPerfServoVelRef := ((lrLineSpeedMaster / 60.0 * 1000.0) / lrPerfPitch_mm) * 2.0 * 3.14159265359;
ELSE
    lrPerfServoVelRef := 0.0;
    bFault := TRUE;
    iFaultCode := 101; // Invalid Pitch
END_IF
bPerfSyncActive := (lrPerfServoVelRef > 0.0);

// -----------------------------------------------------------------------------
// Log Saw Cutting Synchronization
// -----------------------------------------------------------------------------
// The log saw must synchronize its carriage speed to the log advancing speed,
// make the cut, and return. We simulate the cutting profile here.
CASE eState OF
    0: // Waiting for cut request
        IF bSawCutRequest AND NOT bFault THEN
            eState := 10;
            lrSawSyncPos := 0.0;
        END_IF
        bSawSyncActive := FALSE;

    10: // Accelerate carriage to match line speed (Log advance speed)
        // Log advance speed is proportional to line speed, assume 1:1 for simplicity
        lrSawAccelRamp := lrSawAccelRamp + 0.1;
        IF lrSawAccelRamp >= 1.0 THEN
            lrSawAccelRamp := 1.0;
            eState := 20;
        END_IF
        lrLogSawServoPosRef := lrLogSawServoPosRef + (lrLineSpeedMaster * lrSawAccelRamp * 0.01);

    20: // Synchronized, execute cut
        bSawSyncActive := TRUE;
        tSawDwellTimer(IN := TRUE, PT := T#200MS);
        lrLogSawServoPosRef := lrLogSawServoPosRef + (lrLineSpeedMaster * 0.01);
        IF tSawDwellTimer.Q THEN
            tSawDwellTimer(IN := FALSE);
            eState := 30;
        END_IF

    30: // Decelerate and return carriage
        bSawSyncActive := FALSE;
        lrSawAccelRamp := lrSawAccelRamp - 0.1;
        IF lrSawAccelRamp <= 0.0 THEN
            lrSawAccelRamp := 0.0;
            eState := 0;
        END_IF
        lrLogSawServoPosRef := lrLogSawServoPosRef + (lrLineSpeedMaster * lrSawAccelRamp * 0.01);

END_CASE

// -----------------------------------------------------------------------------
// Tail Gluing Servo Profiling
// -----------------------------------------------------------------------------
// Tail gluing requires precise dispensing of glue based on line speed and viscosity.
// Profiling uses an electronic CAM based on the master axis.

IF lrLineSpeedMaster > 10.0 THEN
    // Profile function: a simple sine wave superimposed on base speed
    lrGlueProfileVal := SIN(lrMasterPos * 3.14159265359 / 180.0) * 0.5 + 1.0;
    lrGlueServoVelRef := (lrLineSpeedMaster * 0.5) * lrGlueProfileVal * lrGlueViscosityFactor;
    bGlueApplicationActive := TRUE;
ELSE
    lrGlueServoVelRef := 0.0;
    bGlueApplicationActive := FALSE;
END_IF

// Update Master Position (simulated)
lrMasterPos := lrMasterPos + (lrLineSpeedMaster * 0.05);
IF lrMasterPos >= 360.0 THEN
    lrMasterPos := lrMasterPos - 360.0;
END_IF

END_FUNCTION_BLOCK\n```
