FUNCTION_BLOCK FB_HVDC_CarouselSync
VAR_INPUT
    (* Core operational inputs *)
    bEnable                 : BOOL;       (* Master enable signal for the carousel subsystem *)
    bEmergencyStop          : BOOL;       (* Safety circuit OK (Active HIGH = OK) *)
    bAcousticTransponderOK  : BOOL;       (* Acoustic positioning system health status *)

    (* Kinematic feedback *)
    rVesselSpeed            : REAL;       (* Vessel Speed Over Ground in meters/second *)
    rCarouselPosition       : REAL;       (* Absolute rotary position of turntable in degrees *)
    rCarouselVelocity       : REAL;       (* Rotational velocity of turntable in rad/sec *)
    rTensionerFeedback      : REAL;       (* Measured tension at payout tensioner in kN (kiloNewtons) *)

    (* Environmental & Target Parameters *)
    rTargetLayTension       : REAL;       (* Desired lay tension in kN, typically 50-150 kN for deep sea *)
    rCurrentDepth           : REAL;       (* Sea depth from multibeam echo sounder in meters *)
    rSeabedSlopeAngle       : REAL;       (* Local seabed gradient in degrees *)
END_VAR

VAR_OUTPUT
    (* Actuator commands *)
    bSystemReady            : BOOL;       (* Indicates synchronization loops are closed and ready *)
    bAlarm                  : BOOL;       (* Critical fault indicator (e.g. tension limit, sync lost) *)
    rCarouselTorqueCmd      : REAL;       (* Command to the variable frequency drives for torque (Nm) *)
    rTensionerSpeedCmd      : REAL;       (* Payout speed command to the track tensioner (m/s) *)
    iOperationState         : INT;        (* Current state machine step for HMI visualization *)
END_VAR

VAR
    (* Internal State and Timers *)
    iState                  : INT := 0;   (* Internal state machine index *)
    tStartupDelay           : TON;        (* Delay timer for drive magnetization and brake release *)
    tFaultTimer             : TON;        (* Filter for transient tension spikes *)

    (* PI Controller Variables for Tension *)
    rTensionError           : REAL;
    rTensionIntegral        : REAL;
    rKp_Tension             : REAL := 2.5;
    rKi_Tension             : REAL := 0.15;
    rTensionMax             : REAL := 250.0; (* Safety limit for cable yielding *)

    (* Kinematic calculations *)
    rRequiredPayoutRate     : REAL;
    rDynamicCompensation    : REAL;
END_VAR

(* === MAIN LOGIC === *)
(* Safety Interlock Block *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rCarouselTorqueCmd := 0.0;
    rTensionerSpeedCmd := 0.0;
    iState := 999; (* Fault state *)
    RETURN;
END_IF;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE - Wait for master enable *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rCarouselTorqueCmd := 0.0;
        rTensionerSpeedCmd := 0.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* INITIALIZATION - System Checks & Magnetization *)
        tStartupDelay(IN := TRUE, PT := T#3S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            IF bAcousticTransponderOK THEN
                iState := 20;
            ELSE
                bAlarm := TRUE;
                iState := 999;
            END_IF;
        END_IF;

    20: (* ACTIVE SYNCHRONIZATION - Laying Operation *)
        bSystemReady := TRUE;
        bAlarm := FALSE;

        (* Calculate required payout rate based on vessel speed and seabed profile *)
        (* Simple catenary profile assumption augmented with acoustic slope data *)
        IF rSeabedSlopeAngle < 45.0 THEN
            rRequiredPayoutRate := rVesselSpeed / COS(rSeabedSlopeAngle * 3.14159 / 180.0);
        ELSE
            rRequiredPayoutRate := rVesselSpeed * 1.414; (* Max compensation factor *)
        END_IF;

        (* Tension Control Loop (PI) *)
        rTensionError := rTargetLayTension - rTensionerFeedback;

        (* Anti-windup for integral term *)
        IF (rCarouselTorqueCmd < 10000.0) AND (rCarouselTorqueCmd > -10000.0) THEN
            rTensionIntegral := rTensionIntegral + (rTensionError * rKi_Tension);
        END_IF;

        (* Total dynamic torque command to Carousel VFDs *)
        rDynamicCompensation := rRequiredPayoutRate * 50.0; (* Base friction/inertia comp *)
        rCarouselTorqueCmd := (rTensionError * rKp_Tension) + rTensionIntegral + rDynamicCompensation;

        (* Limit torque commands to physical constraints *)
        IF rCarouselTorqueCmd > 12000.0 THEN
            rCarouselTorqueCmd := 12000.0;
        ELSIF rCarouselTorqueCmd < -5000.0 THEN
            rCarouselTorqueCmd := -5000.0; (* Max regenerative braking *)
        END_IF;

        (* Synchronize track tensioner speed command *)
        rTensionerSpeedCmd := rRequiredPayoutRate;

        (* Critical Fault Monitoring *)
        tFaultTimer(IN := (rTensionerFeedback > rTensionMax), PT := T#2S);
        IF tFaultTimer.Q THEN
            iState := 999;
            bAlarm := TRUE;
        END_IF;

        IF NOT bEnable THEN
            iState := 30;
        END_IF;

    30: (* NORMAL SHUTDOWN *)
        bSystemReady := FALSE;
        rCarouselTorqueCmd := 0.0;
        rTensionerSpeedCmd := 0.0;
        iState := 0;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rCarouselTorqueCmd := 0.0; (* Let mechanical brakes engage immediately *)
        rTensionerSpeedCmd := 0.0;
        IF NOT bEmergencyStop AND bEnable = FALSE THEN
            (* Require manual reset via HMI (toggling enable) after fault is cleared physically *)
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* Update diagnostic output *)
iOperationState := iState;

END_FUNCTION_BLOCK
