FUNCTION_BLOCK FB_PaintDispenserControl
VAR_INPUT
    bStartDosing : BOOL;
    bEStop : BOOL;
    bAgitatorOn : BOOL;
    rTargetWeightBase : REAL;
    rTargetWeightColorant : REAL;
    rCurrentWeightBase : REAL;
    rCurrentWeightColorant : REAL;
    rViscositySensor : REAL;
    bFlushRequest : BOOL;
    tAgitatorDelay : TIME := T#5S;
END_VAR

VAR_OUTPUT
    bPumpBaseDosing : BOOL;
    bPumpColorantDosing : BOOL;
    bAgitatorRun : BOOL;
    bSolventValveOpen : BOOL;
    bError : BOOL;
    iDosingState : INT;
    rCalculatedViscosity : REAL;
END_VAR

VAR
    timerAgitator : TON;
    bDosingComplete : BOOL := FALSE;
    bFlushInProgress : BOOL := FALSE;
    rDiffBase : REAL;
    rDiffColorant : REAL;
    state : INT := 0; 
END_VAR

(* Implementation of Gravimetric Dosing and High-Shear Agitation *)
IF bEStop THEN
    bPumpBaseDosing := FALSE;
    bPumpColorantDosing := FALSE;
    bAgitatorRun := FALSE;
    bSolventValveOpen := FALSE;
    state := 99;
    bError := TRUE;
ELSE
    CASE state OF
        0: (* IDLE *)
            bPumpBaseDosing := FALSE;
            bPumpColorantDosing := FALSE;
            bAgitatorRun := FALSE;
            bSolventValveOpen := FALSE;
            IF bStartDosing AND NOT bFlushRequest THEN
                state := 10;
                bDosingComplete := FALSE;
                bError := FALSE;
            ELSIF bFlushRequest THEN
                state := 50;
            END_IF;

        10: (* DOSE BASE *)
            rDiffBase := rTargetWeightBase - rCurrentWeightBase;
            IF rDiffBase > 0.5 THEN
                bPumpBaseDosing := TRUE;
            ELSE
                bPumpBaseDosing := FALSE;
                state := 20;
            END_IF;

        20: (* DOSE COLORANT MICRO-DOSING *)
            rDiffColorant := rTargetWeightColorant - rCurrentWeightColorant;
            IF rDiffColorant > 0.05 THEN
                bPumpColorantDosing := TRUE;
            ELSE
                bPumpColorantDosing := FALSE;
                state := 30;
            END_IF;

        30: (* AGITATION & VISCOSITY TRACKING *)
            timerAgitator(IN := TRUE, PT := tAgitatorDelay);
            bAgitatorRun := TRUE;
            rCalculatedViscosity := rViscositySensor * 1.05 + 0.2; (* Simulated high-shear compensation *)
            IF timerAgitator.Q THEN
                bAgitatorRun := FALSE;
                timerAgitator(IN := FALSE);
                bDosingComplete := TRUE;
                state := 0;
            END_IF;

        50: (* SOLVENT FLUSH SEQUENCE *)
            bSolventValveOpen := TRUE;
            timerAgitator(IN := TRUE, PT := T#10S);
            IF timerAgitator.Q THEN
                bSolventValveOpen := FALSE;
                timerAgitator(IN := FALSE);
                bFlushRequest := FALSE;
                state := 0;
            END_IF;

        99: (* ERROR *)
            IF NOT bEStop THEN
                state := 0;
                bError := FALSE;
            END_IF;
    END_CASE;
END_IF;
iDosingState := state;
END_FUNCTION_BLOCK
