FUNCTION_BLOCK FB_PU_Foam_Slabstock_MixHead
VAR_INPUT
    (* System operation signals *)
    bSystemEnable          : BOOL;  (* Master system enable *)
    bEmergencyStop         : BOOL;  (* E-Stop safety relay OK signal *)

    (* Process setpoints *)
    rPolyolFlowRate_Target : REAL;  (* Target polyol flow rate [kg/min] *)
    rIsoFlowRate_Target    : REAL;  (* Target isocyanate flow rate [kg/min] *)

    (* Actual process variables *)
    rPolyolPressure_Act    : REAL;  (* Actual polyol pressure [bar] *)
    rIsoPressure_Act       : REAL;  (* Actual isocyanate pressure [bar] *)
    rBlockTemp_Act         : REAL;  (* Exothermic reaction block temperature [°C] *)
END_VAR
VAR_OUTPUT
    (* System Status *)
    bMixHeadReady          : BOOL;  (* Mix head is up to pressure and ready *)
    bStoichiometricAlarm   : BOOL;  (* Ratio tolerance exceeded alarm *)
    bTempWarning           : BOOL;  (* Exothermic runaway warning *)

    (* Control Outputs *)
    rPolyolPumpSpeed_Cmd   : REAL;  (* Command to Polyol VFD [%] *)
    rIsoPumpSpeed_Cmd      : REAL;  (* Command to Iso VFD [%] *)
    rConveyorSpeed_Cmd     : REAL;  (* Sync speed for slab conveyor [m/min] *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState                 : INT := 0; (* State machine index *)
    tStartupDelay          : TON;
    tAlarmDelay            : TON;

    (* Process Calculations *)
    rCurrentRatio          : REAL;
    rTargetRatio           : REAL;
    rRatioError            : REAL;
    rConveyorBaseSpeed     : REAL := 5.0; (* Base speed [m/min] *)

    (* PID controllers for pressure/flow *)
    rPolyolKp : REAL := 1.2;
    rIsoKp    : REAL := 1.4;

    (* Integrators *)
    rPolyolErrSum : REAL := 0.0;
    rIsoErrSum    : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)
(* Ensure fail-safe shutdown upon emergency stop *)
IF NOT bEmergencyStop THEN
    bMixHeadReady := FALSE;
    rPolyolPumpSpeed_Cmd := 0.0;
    rIsoPumpSpeed_Cmd := 0.0;
    rConveyorSpeed_Cmd := 0.0;
    bStoichiometricAlarm := TRUE;
    bTempWarning := FALSE;
    iState := 0;
    RETURN;
END_IF;

(* Stoichiometric calculation (Iso/Polyol) *)
IF rPolyolFlowRate_Target > 0.0 THEN
    rTargetRatio := rIsoFlowRate_Target / rPolyolFlowRate_Target;
ELSE
    rTargetRatio := 0.0;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bMixHeadReady := FALSE;
        rPolyolPumpSpeed_Cmd := 0.0;
        rIsoPumpSpeed_Cmd := 0.0;
        rConveyorSpeed_Cmd := 0.0;
        bStoichiometricAlarm := FALSE;
        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* PRESSURIZE SYSTEM *)
        (* Ramp up pumps to build head pressure prior to injection *)
        rPolyolPumpSpeed_Cmd := rPolyolPumpSpeed_Cmd + 0.1;
        rIsoPumpSpeed_Cmd := rIsoPumpSpeed_Cmd + 0.1;

        IF (rPolyolPressure_Act >= 150.0) AND (rIsoPressure_Act >= 150.0) THEN
            tStartupDelay(IN := TRUE, PT := T#3S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20;
            END_IF;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* RUNNING - ACTIVE MIXING AND POURING *)
        bMixHeadReady := TRUE;

        (* PI Control for Polyol Flow *)
        rPolyolErrSum := rPolyolErrSum + (150.0 - rPolyolPressure_Act) * 0.01;
        rPolyolPumpSpeed_Cmd := (150.0 - rPolyolPressure_Act) * rPolyolKp + rPolyolErrSum;

        (* PI Control for Iso Flow *)
        rIsoErrSum := rIsoErrSum + (150.0 - rIsoPressure_Act) * 0.01;
        rIsoPumpSpeed_Cmd := (150.0 - rIsoPressure_Act) * rIsoKp + rIsoErrSum;

        (* Conveyor speed synchronization based on mass output and exothermic expansion *)
        rConveyorSpeed_Cmd := rConveyorBaseSpeed * (rPolyolFlowRate_Target + rIsoFlowRate_Target) / 100.0;
        IF rBlockTemp_Act > 110.0 THEN
            (* Exothermic expansion is too fast, speed up conveyor slightly to prevent slab bunching *)
            rConveyorSpeed_Cmd := rConveyorSpeed_Cmd * 1.05;
            bTempWarning := TRUE;
        ELSE
            bTempWarning := FALSE;
        END_IF;

        (* Stoichiometry Alarm check *)
        rCurrentRatio := (rIsoPressure_Act * rIsoPumpSpeed_Cmd) / (rPolyolPressure_Act * rPolyolPumpSpeed_Cmd + 0.001);
        rRatioError := ABS(rCurrentRatio - rTargetRatio);
        IF rRatioError > 0.05 THEN
            tAlarmDelay(IN := TRUE, PT := T#2S);
            IF tAlarmDelay.Q THEN
                bStoichiometricAlarm := TRUE;
            END_IF;
        ELSE
            tAlarmDelay(IN := FALSE);
            bStoichiometricAlarm := FALSE;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 30;
        END_IF;

    30: (* SHUTDOWN FLUSH *)
        bMixHeadReady := FALSE;
        rIsoPumpSpeed_Cmd := 0.0; (* Stop Iso first *)
        rPolyolPumpSpeed_Cmd := 20.0; (* Keep Polyol running briefly to flush mixing chamber *)

        tStartupDelay(IN := TRUE, PT := T#5S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 0;
        END_IF;

END_CASE;

(* Output Clamping *)
IF rPolyolPumpSpeed_Cmd > 100.0 THEN rPolyolPumpSpeed_Cmd := 100.0; END_IF;
IF rPolyolPumpSpeed_Cmd < 0.0 THEN rPolyolPumpSpeed_Cmd := 0.0; END_IF;
IF rIsoPumpSpeed_Cmd > 100.0 THEN rIsoPumpSpeed_Cmd := 100.0; END_IF;
IF rIsoPumpSpeed_Cmd < 0.0 THEN rIsoPumpSpeed_Cmd := 0.0; END_IF;

END_FUNCTION_BLOCK
`
