FUNCTION_BLOCK FB_HPDC_DieCasting_EngineBlock_Cell
VAR_INPUT
    bAutoModeEnable       : BOOL;     (* System fully enabled for automatic casting cycle *)
    bEmergencyStopOk      : BOOL;     (* Safety relays and light curtains clear *)
    rMoldTempFixed_C      : REAL;     (* Thermocouple reading from fixed die half [deg C] *)
    rMoldTempMoving_C     : REAL;     (* Thermocouple reading from moving die half [deg C] *)
    rFurnaceMetalTemp_C   : REAL;     (* Aluminum holding furnace temperature [deg C] *)
    rShotSleevePos_mm     : REAL;     (* Linear transducer position of plunger [mm] *)
    rHydraulicPress_bar   : REAL;     (* System hydraulic pressure transducer [bar] *)
    rVacuumLevel_mbar     : REAL;     (* Vacuum evacuation sensor for die cavity [mbar] *)
    rClampTonnage_kN      : REAL;     (* Toggle clamp force strain gauge feedback [kN] *)
    bBiscuitEjected       : BOOL;     (* Proximity sensor confirming biscuit ejection *)
END_VAR
VAR_OUTPUT
    bSystemReady          : BOOL;     (* All pre-conditions met for casting cycle *)
    bCycleActive          : BOOL;     (* Casting sequence in progress *)
    rPlungerVelocity_m_s  : REAL;     (* Commanded plunger velocity via proportional valve [m/s] *)
    rIntensificationPrs_bar: REAL;    (* Target intensification pressure for Phase 3 [bar] *)
    bVacuumValveCmd       : BOOL;     (* Command to open vacuum evacuation valve *)
    rCoolingWaterFlow_lpm : REAL;     (* Die cooling water proportional flow command [L/min] *)
    bAlarmFault           : BOOL;     (* General fault or process deviation alarm *)
    iAlarmCode            : INT;      (* Specific alarm code for HMI diagnostics *)
    rQualityIndex_pct     : REAL;     (* Calculated casting quality confidence index [%] *)
END_VAR
VAR
    iCastingState         : INT := 0; (* Internal state machine tracker *)
    tCoolingTimer         : TON;      (* Timer for solidification dwell *)
    tVacuumTimer          : TON;      (* Timer for vacuum drawing before Phase 2 *)
    tFaultTimer           : TON;      (* Timeout watchdog for mechanical motions *)

    rPhase1Vel_Setpoint   : REAL := 0.3;   (* Phase 1 slow shot velocity [m/s] *)
    rPhase2Vel_Setpoint   : REAL := 4.5;   (* Phase 2 fast shot velocity [m/s] *)
    rPhase3Prs_Setpoint   : REAL := 350.0; (* Phase 3 intensification pressure [bar] *)

    rPosPhase2Trigger_mm  : REAL := 450.0; (* Position to trigger fast shot [mm] *)
    rPosPhase3Trigger_mm  : REAL := 680.0; (* Position to trigger intensification [mm] *)

    rMaxMoldTemp_C        : REAL := 280.0; (* Maximum allowed mold temperature *)
    rMinMoldTemp_C        : REAL := 180.0; (* Minimum allowed mold temperature *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Checks *)
IF NOT bEmergencyStopOk THEN
    bSystemReady := FALSE;
    bCycleActive := FALSE;
    rPlungerVelocity_m_s := 0.0;
    rIntensificationPrs_bar := 0.0;
    bVacuumValveCmd := FALSE;
    rCoolingWaterFlow_lpm := 0.0;
    bAlarmFault := TRUE;
    iAlarmCode := 999; (* E-STOP *)
    iCastingState := 0;
    RETURN;
END_IF;

(* Continuous Cooling Control Based on Die Temperatures *)
IF (rMoldTempFixed_C > rMaxMoldTemp_C) OR (rMoldTempMoving_C > rMaxMoldTemp_C) THEN
    rCoolingWaterFlow_lpm := 50.0; (* Max flow *)
ELSIF (rMoldTempFixed_C > rMinMoldTemp_C) OR (rMoldTempMoving_C > rMinMoldTemp_C) THEN
    rCoolingWaterFlow_lpm := 20.0; (* Nominal flow *)
ELSE
    rCoolingWaterFlow_lpm := 5.0;  (* Minimum flow to prevent freezing *)
END_IF;

(* Ready Condition Monitoring *)
bSystemReady := bAutoModeEnable 
                AND (rClampTonnage_kN >= 28000.0) (* Minimum 28,000 kN / ~2800 Ton clamp force *)
                AND (rFurnaceMetalTemp_C >= 660.0) AND (rFurnaceMetalTemp_C <= 720.0)
                AND (rHydraulicPress_bar >= 140.0)
                AND (iCastingState = 0);

(* 2. HPDC State Machine *)
CASE iCastingState OF
    0: (* IDLE / WAITING TO START *)
        bCycleActive := FALSE;
        rPlungerVelocity_m_s := 0.0;
        rIntensificationPrs_bar := 0.0;
        bVacuumValveCmd := FALSE;
        bAlarmFault := FALSE;
        iAlarmCode := 0;

        IF bSystemReady THEN
            iCastingState := 10; (* Start Cycle: Vacuum and Phase 1 *)
        END_IF;

    10: (* PHASE 1: SLOW SHOT & VACUUM EVACUATION *)
        bCycleActive := TRUE;
        bVacuumValveCmd := TRUE; (* Open vacuum valve to draw air out of mold *)
        rPlungerVelocity_m_s := rPhase1Vel_Setpoint;

        (* Watchdog timer for Phase 1 *)
        tFaultTimer(IN := TRUE, PT := T#10S);

        (* Check transition to Phase 2 *)
        IF rShotSleevePos_mm >= rPosPhase2Trigger_mm THEN
            tFaultTimer(IN := FALSE);
            iCastingState := 20;
        ELSIF tFaultTimer.Q THEN
            tFaultTimer(IN := FALSE);
            bAlarmFault := TRUE;
            iAlarmCode := 101; (* Phase 1 Timeout *)
            iCastingState := 99; (* Error State *)
        END_IF;

    20: (* PHASE 2: FAST SHOT (MOLD FILLING) *)
        rPlungerVelocity_m_s := rPhase2Vel_Setpoint;

        (* Monitor vacuum level during fast shot for porosity reduction *)
        IF rVacuumLevel_mbar > 150.0 THEN
            (* Sub-optimal vacuum; degrade quality index but continue *)
            rQualityIndex_pct := 75.0;
        ELSE
            rQualityIndex_pct := 99.5;
        END_IF;

        tFaultTimer(IN := TRUE, PT := T#2S);

        IF rShotSleevePos_mm >= rPosPhase3Trigger_mm THEN
            tFaultTimer(IN := FALSE);
            bVacuumValveCmd := FALSE; (* Close vacuum before aluminum reaches valve *)
            iCastingState := 30;
        ELSIF tFaultTimer.Q THEN
            tFaultTimer(IN := FALSE);
            bAlarmFault := TRUE;
            iAlarmCode := 102; (* Phase 2 Timeout *)
            iCastingState := 99;
        END_IF;

    30: (* PHASE 3: INTENSIFICATION (SHRINKAGE COMPENSATION) *)
        rPlungerVelocity_m_s := 0.0; (* Velocity control switches to pressure control *)
        rIntensificationPrs_bar := rPhase3Prs_Setpoint;

        tCoolingTimer(IN := TRUE, PT := T#12S); (* 12 seconds intensification and cooling dwell *)

        IF tCoolingTimer.Q THEN
            tCoolingTimer(IN := FALSE);
            rIntensificationPrs_bar := 0.0;
            iCastingState := 40;
        END_IF;

    40: (* EJECTION & CYCLE COMPLETE *)
        (* Wait for external sequence to open die and eject *)
        IF bBiscuitEjected THEN
            bCycleActive := FALSE;
            iCastingState := 0; (* Reset for next cycle *)
        END_IF;

    99: (* ERROR RECOVERY STATE *)
        bCycleActive := FALSE;
        rPlungerVelocity_m_s := 0.0;
        rIntensificationPrs_bar := 0.0;
        bVacuumValveCmd := FALSE;

        (* Wait for manual intervention and reset (bAutoModeEnable toggled) *)
        IF NOT bAutoModeEnable THEN
            bAlarmFault := FALSE;
            iAlarmCode := 0;
            iCastingState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
