FUNCTION_BLOCK FB_FloatingWindPlatformControl
TITLE = 'Active Ballast, Catenary Tension, and Yaw Misalignment Control'
VERSION : '1.2'
AUTHOR : 'Lumina AI Swarm'

VAR_INPUT
    Enable : BOOL; // System Enable
    WindSpeed : REAL; // m/s
    WindDirection : REAL; // Degrees (0-360)
    PlatformHeading : REAL; // Degrees (0-360)
    PontoonPitch : REAL; // Degrees
    PontoonRoll : REAL; // Degrees
    PontoonHeave : REAL; // Meters
    ExportCableTension : REAL; // kN
    ExportCableTensionLimit : REAL; // kN
    BallastTank1Level : REAL; // %
    BallastTank2Level : REAL; // %
    BallastTank3Level : REAL; // %
    BallastTank4Level : REAL; // %
    PumpFlowRateMax : REAL; // m3/hr
END_VAR

VAR_OUTPUT
    YawCommand : REAL; // Degrees Target
    YawDriveEnable : BOOL; // Enable Yaw Motors
    BallastPump1Cmd : REAL; // % Speed
    BallastPump2Cmd : REAL; // % Speed
    BallastPump3Cmd : REAL; // % Speed
    BallastPump4Cmd : REAL; // % Speed
    Valve1Open : BOOL;
    Valve2Open : BOOL;
    Valve3Open : BOOL;
    Valve4Open : BOOL;
    CableTensionAlarm : BOOL;
    PlatformStable : BOOL;
    EmergencyStop : BOOL;
END_VAR

VAR
    YawMisalignment : REAL;
    PitchError : REAL;
    RollError : REAL;
    Kp_Yaw : REAL := 1.5;
    Kp_Ballast : REAL := 5.0;
    Ki_Ballast : REAL := 0.5;
    IntegralPitch : REAL;
    IntegralRoll : REAL;
    TensionMargin : REAL;
    ControlActive : BOOL;
    CycleCount : INT := 0;
END_VAR

(* Implementation *)
IF NOT Enable OR EmergencyStop THEN
    YawDriveEnable := FALSE;
    BallastPump1Cmd := 0.0;
    BallastPump2Cmd := 0.0;
    BallastPump3Cmd := 0.0;
    BallastPump4Cmd := 0.0;
    Valve1Open := FALSE;
    Valve2Open := FALSE;
    Valve3Open := FALSE;
    Valve4Open := FALSE;
    ControlActive := FALSE;
    RETURN;
END_IF;

ControlActive := TRUE;

(* 1. Yaw Misalignment Calculation *)
YawMisalignment := WindDirection - PlatformHeading;
IF YawMisalignment > 180.0 THEN
    YawMisalignment := YawMisalignment - 360.0;
ELSIF YawMisalignment < -180.0 THEN
    YawMisalignment := YawMisalignment + 360.0;
END_IF;

IF ABS(YawMisalignment) > 5.0 THEN
    YawCommand := PlatformHeading + (YawMisalignment * Kp_Yaw);
    YawDriveEnable := TRUE;
ELSE
    YawDriveEnable := FALSE;
END_IF;

(* 2. Active Ballast Transfer for Pitch & Roll Stability *)
PitchError := 0.0 - PontoonPitch;
RollError := 0.0 - PontoonRoll;

IntegralPitch := IntegralPitch + (PitchError * 0.1); (* Assuming 100ms cycle *)
IntegralRoll := IntegralRoll + (RollError * 0.1);

IF IntegralPitch > 50.0 THEN IntegralPitch := 50.0; END_IF;
IF IntegralPitch < -50.0 THEN IntegralPitch := -50.0; END_IF;
IF IntegralRoll > 50.0 THEN IntegralRoll := 50.0; END_IF;
IF IntegralRoll < -50.0 THEN IntegralRoll := -50.0; END_IF;

(* Pump Commands based on combined PI control for pitch and roll *)
(* Mapping: Tank1 Fwd-Port, Tank2 Fwd-Stbd, Tank3 Aft-Port, Tank4 Aft-Stbd *)
BallastPump1Cmd := MAX(0.0, MIN(100.0, (PitchError * Kp_Ballast + IntegralPitch) + (RollError * Kp_Ballast + IntegralRoll)));
BallastPump2Cmd := MAX(0.0, MIN(100.0, (PitchError * Kp_Ballast + IntegralPitch) - (RollError * Kp_Ballast + IntegralRoll)));
BallastPump3Cmd := MAX(0.0, MIN(100.0, -(PitchError * Kp_Ballast + IntegralPitch) + (RollError * Kp_Ballast + IntegralRoll)));
BallastPump4Cmd := MAX(0.0, MIN(100.0, -(PitchError * Kp_Ballast + IntegralPitch) - (RollError * Kp_Ballast + IntegralRoll)));

Valve1Open := BallastPump1Cmd > 5.0;
Valve2Open := BallastPump2Cmd > 5.0;
Valve3Open := BallastPump3Cmd > 5.0;
Valve4Open := BallastPump4Cmd > 5.0;

(* 3. Dynamic Export Cable Catenary Tension *)
TensionMargin := ExportCableTensionLimit - ExportCableTension;

IF TensionMargin < 50.0 THEN
    CableTensionAlarm := TRUE;
    (* Shift ballast aft to relieve tension if possible *)
    BallastPump1Cmd := 0.0; BallastPump2Cmd := 0.0;
    BallastPump3Cmd := 50.0; BallastPump4Cmd := 50.0;
    Valve1Open := FALSE; Valve2Open := FALSE;
    Valve3Open := TRUE; Valve4Open := TRUE;
ELSE
    CableTensionAlarm := FALSE;
END_IF;

IF ExportCableTension > ExportCableTensionLimit THEN
    EmergencyStop := TRUE;
END_IF;

(* 4. Stability Evaluation *)
IF ABS(PitchError) < 1.0 AND ABS(RollError) < 1.0 AND NOT CableTensionAlarm THEN
    PlatformStable := TRUE;
ELSE
    PlatformStable := FALSE;
END_IF;

CycleCount := CycleCount + 1;
IF CycleCount > 32760 THEN CycleCount := 0; END_IF;

END_FUNCTION_BLOCK
