FUNCTION_BLOCK FB_AdvancedWaterTreatment
VAR_INPUT
    rOzoneFlowRate      : REAL; (* m3/h *)
    rOzoneConcentration : REAL; (* g/Nm3 *)
    rWaterFlowRate      : REAL; (* m3/h *)
    rFilterHeadLoss     : REAL; (* bar *)
    bFilterRunTimeLimit : BOOL; 
    rChlorineDose       : REAL; (* mg/L *)
    rBasinVolume        : REAL; (* m3 *)
    rBafflingFactor     : REAL; (* 0.0 to 1.0 *)
END_VAR

VAR_OUTPUT
    rCoronaVoltageCmd   : REAL; (* kV *)
    bBackwashActive     : BOOL;
    bAirScourActive     : BOOL;
    rContactTimeMin     : REAL; (* minutes *)
    rCT_Value           : REAL; (* mg-min/L *)
    bSystemAlarm        : BOOL;
END_VAR

VAR
    rOzoneDemand        : REAL;
    rSpecificEnergy     : REAL;
    tBackwashTimer      : TON;
    tAirScourTimer      : TON;
    iBackwashStep       : INT := 0;
    rTheoreticalHRT     : REAL;
END_VAR

(* Ozone Generator Corona Discharge Voltage Scaling *)
(* Calculate required ozone demand (g/h) *)
rOzoneDemand := rWaterFlowRate * rOzoneConcentration;

(* Corona voltage scales non-linearly with ozone demand and flow rate *)
IF rOzoneFlowRate > 0.0 THEN
    rSpecificEnergy := rOzoneDemand / rOzoneFlowRate;
    (* Example empirical scaling: V = 2.5 + 0.15*E + 0.005*E^2 *)
    rCoronaVoltageCmd := 2.5 + (0.15 * rSpecificEnergy) + (0.005 * rSpecificEnergy * rSpecificEnergy);

    (* Limit voltage to physical constraints (e.g., max 15 kV) *)
    IF rCoronaVoltageCmd > 15.0 THEN
        rCoronaVoltageCmd := 15.0;
        bSystemAlarm := TRUE;
    ELSE
        bSystemAlarm := FALSE;
    END_IF;
ELSE
    rCoronaVoltageCmd := 0.0;
END_IF;

(* Biological Aerated Filter (BAF) Backwash Logic *)
(* Trigger backwash on headloss or runtime limit *)
IF (rFilterHeadLoss > 0.8 OR bFilterRunTimeLimit) AND iBackwashStep = 0 THEN
    iBackwashStep := 1; (* Initiate backwash sequence *)
END_IF;

CASE iBackwashStep OF
    0: (* Normal Operation *)
        bBackwashActive := FALSE;
        bAirScourActive := FALSE;
        tAirScourTimer(IN:=FALSE);
        tBackwashTimer(IN:=FALSE);

    1: (* Air Scour Only - 5 minutes *)
        bBackwashActive := FALSE;
        bAirScourActive := TRUE;
        tAirScourTimer(IN:=TRUE, PT:=T#5m);
        IF tAirScourTimer.Q THEN
            iBackwashStep := 2;
        END_IF;

    2: (* Combined Air and Water Scour - 10 minutes *)
        bBackwashActive := TRUE;
        bAirScourActive := TRUE;
        tBackwashTimer(IN:=TRUE, PT:=T#10m);
        IF tBackwashTimer.Q THEN
            iBackwashStep := 3;
            tAirScourTimer(IN:=FALSE);
            tBackwashTimer(IN:=FALSE);
        END_IF;

    3: (* Water Rinse Only - 5 minutes *)
        bBackwashActive := TRUE;
        bAirScourActive := FALSE;
        tBackwashTimer(IN:=TRUE, PT:=T#5m);
        IF tBackwashTimer.Q THEN
            iBackwashStep := 0; (* Sequence complete *)
            tBackwashTimer(IN:=FALSE);
        END_IF;
ELSE
    iBackwashStep := 0;
END_CASE;

(* Chlorine Contact Time (CT) Calculation *)
(* HRT = Volume / Flow Rate *)
IF rWaterFlowRate > 0.0 THEN
    rTheoreticalHRT := (rBasinVolume / rWaterFlowRate) * 60.0; (* Convert to minutes *)
    rContactTimeMin := rTheoreticalHRT * rBafflingFactor;
    rCT_Value := rContactTimeMin * rChlorineDose;
ELSE
    rContactTimeMin := 0.0;
    rCT_Value := 0.0;
END_IF;

END_FUNCTION_BLOCK
