FUNCTION_BLOCK FB_mRNA_ContinuousTFF
(* 
   =============================================================================
   LUMINA AI CLOUD SWARM - ELITE SYNTHETIC DATA ARCHITECT
   DOMAIN: Advanced Biopharmaceutical Continuous mRNA Tangential Flow Filtration (TFF)
   DESCRIPTION: 
     Advanced control block for continuous mRNA Tangential Flow Filtration (TFF).
     Implements Retentate Trans-Membrane Pressure (TMP) optimization, 
     diafiltration buffer cascading, and ultra-low shear feed pump flow regulation.
     Includes advanced safety interlocks, moving average filters for sensor noise,
     and multi-stage PID control for shear-sensitive mRNA processing.
   AUTHOR: 40-Year Veteran PLC Automation Architect
   =============================================================================
*)

VAR_INPUT
    (* Required physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (Normally Closed) *)
    rFeedPressure           : REAL;     (* Feed pressure sensor (bar) - critical for TMP *)
    rRetentatePressure      : REAL;     (* Retentate pressure sensor (bar) *)
    rPermeatePressure       : REAL;     (* Permeate pressure sensor (bar) *)
    rFeedFlowRate           : REAL;     (* Actual feed flow rate (L/min) *)
    rDiafiltrationFlowRate  : REAL;     (* Actual diafiltration buffer addition rate (L/min) *)
    rTargetTMP              : REAL;     (* Target Trans-Membrane Pressure (bar) *)
    rTargetShearRate        : REAL;     (* Desired shear rate for mRNA preservation (s^-1) *)
    bBufferCascadeReady     : BOOL;     (* Upstream buffer cascading system ready state *)
END_VAR

VAR_OUTPUT
    (* Required physical outputs with types and comments *)
    bSystemReady            : BOOL;     (* TFF System ready status for upstream integration *)
    bRunning                : BOOL;     (* TFF System active execution status *)
    rFeedPumpControl        : REAL;     (* Control signal to feed pump VFD (0-100%) *)
    rRetentateValveControl  : REAL;     (* Control signal to retentate proportional valve (0-100%) *)
    rPermeateValveControl   : REAL;     (* Control signal to permeate proportional valve (0-100%) *)
    bAlarm                  : BOOL;     (* Critical fault alarm output *)
    iAlarmCode              : INT;      (* Specific alarm code for HMI diagnostics *)
    rCalculatedTMP          : REAL;     (* Live calculated TMP for monitoring (bar) *)
END_VAR

VAR
    (* Internal state variables and timers *)
    iState                  : INT := 0; (* Main state machine step *)
    tStartupTimer           : TON;      (* Delay timer for pump start sequencing *)
    tStablizationTimer      : TON;      (* Timer to allow pressures to stabilize *)
    tAlarmDelayTimer        : TON;      (* Filter out transient pressure spikes *)

    (* Filtered signals *)
    rFiltFeedPressure       : REAL := 0.0;
    rFiltRetentatePressure  : REAL := 0.0;
    rFiltPermeatePressure   : REAL := 0.0;

    (* PID Control Variables (Simplified for ST representation) *)
    rErrorTMP               : REAL;
    rIntegralTMP            : REAL := 0.0;
    rDerivativeTMP          : REAL;
    rLastTMP                : REAL := 0.0;

    rErrorFlow              : REAL;
    rIntegralFlow           : REAL := 0.0;

    (* Constants *)
    c_rAlphaFilter          : REAL := 0.2;  (* Exponential moving average coefficient *)
    c_rMaxTMP               : REAL := 1.5;  (* Absolute maximum TMP for mRNA (bar) *)
    c_rKp_TMP               : REAL := 25.0; (* Proportional gain for TMP control *)
    c_rKi_TMP               : REAL := 2.0;  (* Integral gain for TMP control *)
    c_rKp_Flow              : REAL := 15.0; (* Proportional gain for Shear/Flow control *)
    c_rKi_Flow              : REAL := 1.5;  (* Integral gain for Shear/Flow control *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety and Emergency Stop Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bRunning := FALSE;
    bAlarm := TRUE;
    iAlarmCode := 99; (* 99 = E-STOP Activated *)
    rFeedPumpControl := 0.0;
    rRetentateValveControl := 100.0; (* Fail open for safety *)
    rPermeateValveControl := 100.0;  (* Fail open for safety *)
    iState := 0;
    RETURN;
END_IF;

(* 2. Signal Filtering (Exponential Moving Average) *)
rFiltFeedPressure := (c_rAlphaFilter * rFeedPressure) + ((1.0 - c_rAlphaFilter) * rFiltFeedPressure);
rFiltRetentatePressure := (c_rAlphaFilter * rRetentatePressure) + ((1.0 - c_rAlphaFilter) * rFiltRetentatePressure);
rFiltPermeatePressure := (c_rAlphaFilter * rPermeatePressure) + ((1.0 - c_rAlphaFilter) * rFiltPermeatePressure);

(* 3. Trans-Membrane Pressure (TMP) Calculation *)
rCalculatedTMP := ((rFiltFeedPressure + rFiltRetentatePressure) / 2.0) - rFiltPermeatePressure;

(* 4. Critical TMP Safety Interlock *)
tAlarmDelayTimer(IN := (rCalculatedTMP > c_rMaxTMP), PT := T#2S);
IF tAlarmDelayTimer.Q THEN
    bAlarm := TRUE;
    iAlarmCode := 10; (* 10 = TMP High Limit Exceeded *)
    iState := 900;    (* Jump to fault state *)
END_IF;

(* 5. State Machine *)
CASE iState OF
    0: (* IDLE - Await Enable and Buffer Ready *)
        bSystemReady := bBufferCascadeReady;
        bRunning := FALSE;
        rFeedPumpControl := 0.0;
        rRetentateValveControl := 10.0; (* Slightly open *)
        rPermeateValveControl := 10.0;
        rIntegralTMP := 0.0;
        rIntegralFlow := 0.0;

        IF bEnable AND bBufferCascadeReady AND NOT bAlarm THEN
            iState := 10;
        END_IF;

    10: (* PRIMING - Start Feed Pump Slowly for ultra-low shear *)
        bRunning := TRUE;
        tStartupTimer(IN := TRUE, PT := T#10S);

        (* Ramp pump to 10% initially *)
        IF rFeedPumpControl < 10.0 THEN
            rFeedPumpControl := rFeedPumpControl + 0.1; 
        END_IF;

        IF tStartupTimer.Q THEN
            tStartupTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* STABILIZATION - Close valves gradually to build pressure *)
        tStablizationTimer(IN := TRUE, PT := T#15S);

        IF rRetentateValveControl < 50.0 THEN
             rRetentateValveControl := rRetentateValveControl + 0.5;
        END_IF;

        IF tStablizationTimer.Q THEN
            tStablizationTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* CONTINUOUS RUN - Advanced PID control for TMP and Flow *)
        (* TMP Control Loop -> Controls Retentate Valve *)
        rErrorTMP := rTargetTMP - rCalculatedTMP;
        rIntegralTMP := rIntegralTMP + rErrorTMP;

        (* Anti-windup *)
        IF rIntegralTMP > 50.0 THEN rIntegralTMP := 50.0; END_IF;
        IF rIntegralTMP < -50.0 THEN rIntegralTMP := -50.0; END_IF;

        rRetentateValveControl := 50.0 + (rErrorTMP * c_rKp_TMP) + (rIntegralTMP * c_rKi_TMP);

        (* Clamp Valve Output *)
        IF rRetentateValveControl > 100.0 THEN rRetentateValveControl := 100.0; END_IF;
        IF rRetentateValveControl < 0.0 THEN rRetentateValveControl := 0.0; END_IF;

        (* Flow Control Loop -> Controls Feed Pump for target shear *)
        rErrorFlow := rTargetShearRate - (rFeedFlowRate * 1.5); (* Mock shear calc *)
        rIntegralFlow := rIntegralFlow + rErrorFlow;

        rFeedPumpControl := 10.0 + (rErrorFlow * c_rKp_Flow) + (rIntegralFlow * c_rKi_Flow);

        IF rFeedPumpControl > 100.0 THEN rFeedPumpControl := 100.0; END_IF;
        IF rFeedPumpControl < 10.0 THEN rFeedPumpControl := 10.0; END_IF;

        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    40: (* SHUTDOWN - Ramp down smoothly *)
        rFeedPumpControl := rFeedPumpControl * 0.95;
        rRetentateValveControl := 100.0; (* Open to relieve pressure *)

        IF rFeedPumpControl < 1.0 THEN
            iState := 0;
        END_IF;

    900: (* FAULT STATE *)
        bRunning := FALSE;
        rFeedPumpControl := 0.0;
        rRetentateValveControl := 100.0;
        rPermeateValveControl := 100.0;
        IF bEnable = FALSE AND bEmergencyStop = TRUE THEN
            bAlarm := FALSE;
            iAlarmCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
