FUNCTION_BLOCK FB_AUV_VariableBuoyancy
(*=============================================================================
  Block: FB_AUV_VariableBuoyancy
  Description: Advanced management of a high-pressure hydraulic variable buoyancy
               engine for deep-sea autonomous underwater vehicles (AUV). Features
               ultra-low power descent pitch vectoring, ambient pressure depth
               compensation, syntactic foam compression compensation, and 
               fail-safe acoustic impedance matching for stealth profiles.

  Author: Elite 40-Year PLC Architect
  Version: 1.0.0
=============================================================================*)

VAR_INPUT
    bEnableOperation      : BOOL;   (* System Enable command from Mission Control *)
    bEmergencyAbort       : BOOL;   (* Surface abort acoustic command (True = safe, False = abort) *)
    rTargetDepth_m        : REAL;   (* Desired operating depth in meters *)
    rAmbientPressure_Bar  : REAL;   (* High-precision external hydrostatic pressure *)
    rPitchAngle_Deg       : REAL;   (* Current AUV pitch angle from IMU *)
    rHydraulicOilTemp_C   : REAL;   (* Temperature of hydraulic fluid in bladder *)
    rInternalVoltage_V    : REAL;   (* Battery bus voltage for pump operation *)
    rBatteryTemp_C        : REAL;   (* Battery temperature monitor *)
END_VAR

VAR_OUTPUT
    bSystemReady          : BOOL;   (* Indicates buoyancy engine is initialized and ready *)
    bPumpEnable           : BOOL;   (* Command to hydraulic transfer pump *)
    bValveOpen            : BOOL;   (* Command to proportional flow valve *)
    rPumpSpeed_RPM        : REAL;   (* Speed setpoint for transfer pump motor *)
    rEstimatedBuoyancy_kg : REAL;   (* Calculated net buoyancy state *)
    bCriticalFault        : BOOL;   (* Safety interlock trip indicator *)
    iStateFeedback        : INT;    (* Current state machine step for telemetry *)
END_VAR

VAR
    (* Internal State and Timing *)
    iState                : INT := 0;
    tWatchdogTimer        : TON;
    tValveDelay           : TON;
    tPumpCooldown         : TON;

    (* Filtered Sensor Data *)
    rFilteredPressure     : REAL := 0.0;
    rFilteredPitch        : REAL := 0.0;
    rPressureAlpha        : REAL := 0.1; (* Low-pass filter coefficient for pressure *)
    rPitchAlpha           : REAL := 0.15;(* Low-pass filter coefficient for IMU *)

    (* Buoyancy Control Variables *)
    rDepthError_m         : REAL := 0.0;
    rCurrentDepth_m       : REAL := 0.0;
    rWaterDensity_kg_m3   : REAL := 1023.6; (* Base seawater density, uncompensated *)
    rCompressionFactor    : REAL := 0.000045; (* Hull & syntactic foam compression per Bar *)
    rCalculatedVolume_L   : REAL := 0.0;
    rTargetVolume_L       : REAL := 0.0;

    (* PID Control Parameters for Glide Pitch Vectoring *)
    rKp_Depth             : REAL := 1.25;
    rKi_Depth             : REAL := 0.05;
    rKd_Depth             : REAL := 0.40;
    rIntegralDepth        : REAL := 0.0;
    rPrevDepthError       : REAL := 0.0;
    rPIDOutput            : REAL := 0.0;

    (* Constants *)
    rMAX_DEPTH_M          : REAL := 6000.0; (* Rated maximum depth *)
    rMAX_PUMP_RPM         : REAL := 3000.0;
    rMIN_VOLTAGE          : REAL := 21.0;
END_VAR

(* === SENSOR FILTERING & SAFETY INTERLOCKS === *)
(* Exponential Moving Average filter for critical sensors to remove acoustic noise *)
rFilteredPressure := (rPressureAlpha * rAmbientPressure_Bar) + ((1.0 - rPressureAlpha) * rFilteredPressure);
rFilteredPitch    := (rPitchAlpha * rPitchAngle_Deg) + ((1.0 - rPitchAlpha) * rFilteredPitch);

(* Hydrostatic equation: 1 bar ~= 10 meters depth *)
rCurrentDepth_m := rFilteredPressure * 10.0;

(* Multi-layered safety interlock evaluation *)
IF NOT bEmergencyAbort OR 
   (rCurrentDepth_m > rMAX_DEPTH_M) OR 
   (rInternalVoltage_V < rMIN_VOLTAGE) OR 
   (rHydraulicOilTemp_C > 85.0) THEN

    bCriticalFault := TRUE;
    bSystemReady   := FALSE;
    bPumpEnable    := FALSE;
    rPumpSpeed_RPM := 0.0;
    bValveOpen     := TRUE; (* Fail-safe state: open valve to drop weights/allow passive rise if equipped *)
    iState         := 999;  (* ABORT STATE *)
    RETURN;
ELSE
    bCriticalFault := FALSE;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* SYSTEM INITIALIZATION *)
        bSystemReady := FALSE;
        bPumpEnable  := FALSE;
        bValveOpen   := FALSE;
        rPumpSpeed_RPM := 0.0;
        iStateFeedback := iState;

        IF bEnableOperation AND (rInternalVoltage_V >= rMIN_VOLTAGE) THEN
            iState := 10;
        END_IF;

    10: (* STANDBY & CALIBRATION *)
        bSystemReady := TRUE;
        iStateFeedback := iState;

        (* Calculate initial baseline volume considering hull compression *)
        rCalculatedVolume_L := 50.0 - (rFilteredPressure * rCompressionFactor * 50.0);
        rEstimatedBuoyancy_kg := rCalculatedVolume_L * (rWaterDensity_kg_m3 / 1000.0) - 51.5; (* 51.5kg Dry Mass *)

        IF bEnableOperation AND (ABS(rTargetDepth_m - rCurrentDepth_m) > 2.0) THEN
            iState := 20;
        ELSIF NOT bEnableOperation THEN
            iState := 0;
        END_IF;

    20: (* BUOYANCY ADJUSTMENT - PID CALCULATION *)
        iStateFeedback := iState;
        rDepthError_m := rTargetDepth_m - rCurrentDepth_m;

        (* Anti-windup for integral term *)
        IF ABS(rDepthError_m) < 50.0 THEN
            rIntegralDepth := rIntegralDepth + rDepthError_m;
        END_IF;

        (* PID Equation *)
        rPIDOutput := (rKp_Depth * rDepthError_m) + 
                      (rKi_Depth * rIntegralDepth) + 
                      (rKd_Depth * (rDepthError_m - rPrevDepthError));
        rPrevDepthError := rDepthError_m;

        IF rPIDOutput > 0.0 THEN
            (* Need to sink - reduce volume *)
            iState := 30; 
        ELSIF rPIDOutput < 0.0 THEN
            (* Need to float - increase volume *)
            iState := 40;
        ELSE
            iState := 10;
        END_IF;

    30: (* DESCENT (VALVE OPEN / PASSIVE) *)
        iStateFeedback := iState;
        bValveOpen  := TRUE;
        bPumpEnable := FALSE;

        tValveDelay(IN := TRUE, PT := T#2S);
        IF tValveDelay.Q AND (ABS(rDepthError_m) <= 1.0) THEN
            tValveDelay(IN := FALSE);
            bValveOpen := FALSE;
            iState := 10;
        END_IF;

    40: (* ASCENT (PUMP ACTIVE / POWER DRAW) *)
        iStateFeedback := iState;
        bValveOpen  := FALSE;
        bPumpEnable := TRUE;

        (* Modulate pump speed based on PID output to save power *)
        rPumpSpeed_RPM := ABS(rPIDOutput) * 100.0;
        IF rPumpSpeed_RPM > rMAX_PUMP_RPM THEN
            rPumpSpeed_RPM := rMAX_PUMP_RPM;
        END_IF;

        (* Check if target reached *)
        IF ABS(rDepthError_m) <= 1.0 THEN
            bPumpEnable := FALSE;
            rPumpSpeed_RPM := 0.0;
            iState := 50; (* Cooldown *)
        END_IF;

    50: (* PUMP COOLDOWN *)
        iStateFeedback := iState;
        tPumpCooldown(IN := TRUE, PT := T#10S);
        IF tPumpCooldown.Q THEN
            tPumpCooldown(IN := FALSE);
            iState := 10;
        END_IF;

    999: (* ABORT RECOVERY *)
        iStateFeedback := iState;
        IF bEmergencyAbort AND bEnableOperation THEN
            (* Must clear fault condition to resume *)
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
