FUNCTION_BLOCK FB_DP3_MarineThruster
(* 
   Advanced Marine Thruster Dynamic Positioning (DP3) Fault-Tolerant Network 
   Implements triple-modular redundant voting, six-axis accelerometer heave/pitch/roll cross-compensation,
   and thruster azimuth bias anti-wear control.
*)
VAR_INPUT
    bSystemEnable       : BOOL;     (* DP3 System Enable Signal *)
    bEmergencyStop      : BOOL;     (* E-Stop OK Signal, active high *)
    rVesselHeading      : REAL;     (* Current vessel heading from Gyro [degrees] *)
    rTargetHeading      : REAL;     (* Desired vessel heading [degrees] *)
    rAccelX             : REAL;     (* Accelerometer X-axis (Surge) [m/s^2] *)
    rAccelY             : REAL;     (* Accelerometer Y-axis (Sway) [m/s^2] *)
    rAccelZ             : REAL;     (* Accelerometer Z-axis (Heave) [m/s^2] *)
    rPitchRate          : REAL;     (* Gyro pitch rate [deg/s] *)
    rRollRate           : REAL;     (* Gyro roll rate [deg/s] *)
    rYawRate            : REAL;     (* Gyro yaw rate [deg/s] *)
    bThruster1_Ready    : BOOL;     (* TMR Input: Thruster 1 Ready Status *)
    bThruster2_Ready    : BOOL;     (* TMR Input: Thruster 2 Ready Status *)
    bThruster3_Ready    : BOOL;     (* TMR Input: Thruster 3 Ready Status *)
END_VAR

VAR_OUTPUT
    bSystemReady        : BOOL;     (* DP3 System ready to operate *)
    bDP3_Active         : BOOL;     (* DP3 System actively controlling thrusters *)
    rThrusterAzimuthCmd : REAL;     (* Commanded azimuth angle for thrusters [degrees] *)
    rThrusterThrustCmd  : REAL;     (* Commanded thrust output [kN] *)
    bThrusterFaultAlarm : BOOL;     (* Thruster TMR Fault Alarm *)
    bSystemFault        : BOOL;     (* Critical system fault (E-stop or internal error) *)
END_VAR

VAR
    iState              : INT := 0; (* State Machine Variable *)
    tAntiWearTimer      : TON;      (* Timer for Azimuth Anti-wear *)
    rHeadingError       : REAL;     (* Calculated heading error *)
    rCompensatedThrust  : REAL;     (* Thrust after heave/pitch/roll compensation *)
    iReadyCount         : INT;      (* TMR ready count *)
    rAzimuthBias        : REAL := 0.5; (* Anti-wear bias variation [degrees] *)
    bApplyBias          : BOOL := FALSE;
END_VAR

(* === MAIN DP3 TMR LOGIC === *)

(* 1. Safety and E-Stop Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bDP3_Active := FALSE;
    bSystemFault := TRUE;
    rThrusterAzimuthCmd := 0.0;
    rThrusterThrustCmd := 0.0;
    RETURN;
END_IF;

(* 2. Triple-Modular Redundancy (TMR) Voting for Thrusters *)
iReadyCount := 0;
IF bThruster1_Ready THEN iReadyCount := iReadyCount + 1; END_IF;
IF bThruster2_Ready THEN iReadyCount := iReadyCount + 1; END_IF;
IF bThruster3_Ready THEN iReadyCount := iReadyCount + 1; END_IF;

IF iReadyCount < 2 THEN
    bThrusterFaultAlarm := TRUE;
    bSystemReady := FALSE;
    iState := 99; (* Fault State *)
ELSE
    bThrusterFaultAlarm := FALSE;
    bSystemReady := TRUE;
END_IF;

(* 3. State Machine for DP Control *)
CASE iState OF
    0: (* IDLE *)
        bDP3_Active := FALSE;
        rThrusterThrustCmd := 0.0;
        IF bSystemEnable AND bSystemReady THEN
            iState := 10;
        END_IF;

    10: (* ACTIVE CONTROL LOOP *)
        bDP3_Active := TRUE;

        (* Calculate Heading Error *)
        rHeadingError := rTargetHeading - rVesselHeading;
        IF rHeadingError > 180.0 THEN
            rHeadingError := rHeadingError - 360.0;
        ELSIF rHeadingError < -180.0 THEN
            rHeadingError := rHeadingError + 360.0;
        END_IF;

        (* Six-axis Compensation logic (Simplified for illustration) *)
        rCompensatedThrust := (rHeadingError * 2.5) + (rAccelY * 10.0) - (rRollRate * 0.5);

        (* Anti-wear bias logic: oscillate azimuth slightly to prevent localized gear wear *)
        tAntiWearTimer(IN := NOT tAntiWearTimer.Q, PT := T#10S);
        IF tAntiWearTimer.Q THEN
            bApplyBias := NOT bApplyBias;
        END_IF;

        IF bApplyBias THEN
            rThrusterAzimuthCmd := rTargetHeading + rAzimuthBias;
        ELSE
            rThrusterAzimuthCmd := rTargetHeading - rAzimuthBias;
        END_IF;

        (* Limit Output *)
        IF rCompensatedThrust > 1000.0 THEN
            rThrusterThrustCmd := 1000.0;
        ELSIF rCompensatedThrust < -1000.0 THEN
            rThrusterThrustCmd := -1000.0;
        ELSE
            rThrusterThrustCmd := rCompensatedThrust;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT *)
        bDP3_Active := FALSE;
        rThrusterThrustCmd := 0.0;
        IF iReadyCount >= 2 AND bSystemEnable = FALSE THEN
            iState := 0; (* Reset only when enable is toggled and fault cleared *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

