CASE iState OF
    0:
        bDieselEngineStart := FALSE;
        bDieselEngineStop := TRUE;
        rDieselThrottleCmd := 0.0;
        bEngageGenerator := FALSE;
        bBatteryChargeContactor := FALSE;
        rHoistMotorTorqueCmd := 0.0;
        rHoistMotorSpeedCmd := 0.0;
        rGantryMotorTorqueCmd := 0.0;
        rTrolleyMotorTorqueCmd := 0.0;
        bSystemReady := FALSE;
        bErrorFault := FALSE;

        IF bStartOperation AND rBatteryChargeLevel > 20.0 THEN
            iState := 1;
        END_IF;

    1:
        bDieselEngineStop := FALSE;
        bDieselEngineStart := TRUE;
        rDieselThrottleCmd := 10.0;

        IF rDieselEngineRPM > 800.0 AND rGenOutputVoltage > 500.0 THEN
            bEngageGenerator := TRUE;
            bBatteryChargeContactor := TRUE;
            bSystemReady := TRUE;
            iState := 2;
        END_IF;

    2:
        IF rBatteryChargeLevel < 40.0 THEN
            rDieselThrottleCmd := 75.0;
        ELSIF rBatteryChargeLevel > 90.0 THEN
            rDieselThrottleCmd := 25.0;
        ELSE
            rDieselThrottleCmd := 50.0;
        END_IF;

        rSwayDerivativeX := rSwayAngleX - rLastSwayX;
        rSwayDerivativeY := rSwayAngleY - rLastSwayY;

        rGantryMotorTorqueCmd := (rSwayAngleX * rAntiSwayGainP) + (rSwayDerivativeX * rAntiSwayGainD);
