        IF rWindSpeed > 15.0 THEN
            rGantryMotorTorqueCmd := rGantryMotorTorqueCmd * 1.5;
        END_IF;

        rLastSwayX := rSwayAngleX;
        rLastSwayY := rSwayAngleY;

        bAllTwistLocksLocked := TRUE;
        FOR i := 1 TO 4 DO
            IF NOT rSpreaderTwistLockSensors[i] THEN
                bAllTwistLocksLocked := FALSE;
            END_IF;
        END_FOR;

        IF bAllTwistLocksLocked AND (ABS(rTargetHoistPos - rHoistPosition) < 0.5) THEN
            rHoistMotorSpeedCmd := (rTargetHoistPos - rHoistPosition) * 1.2;
            rHoistMotorTorqueCmd := 500.0;
        ELSE
            rHoistMotorSpeedCmd := 0.0;
            rHoistMotorTorqueCmd := 0.0;
        END_IF;

    3:
        bErrorFault := TRUE;
        bSystemReady := FALSE;
        bDieselEngineStop := TRUE;
        bEngageGenerator := FALSE;
        rHoistMotorTorqueCmd := 0.0;
        rGantryMotorTorqueCmd := 0.0;
        rTrolleyMotorTorqueCmd := 0.0;
END_CASE;
