FUNCTION_BLOCK FB_MultiStage_UF_Control
VAR_INPUT
    bEnable : BOOL; // System enable
    bStart_CEB : BOOL; // Manual trigger for Chemical Enhanced Backwash
    bStart_MIT : BOOL; // Manual trigger for Membrane Integrity Test
    rFeed_Pressure : REAL; // Feed pressure (bar)
    rFiltrate_Pressure : REAL; // Filtrate pressure (bar)
    rFlow_Rate : REAL; // Current flow rate (m3/h)
    rTemperature : REAL; // Water temperature (C)
    rTurbidity_In : REAL; // Feed turbidity (NTU)
    rpH_In : REAL; // Feed pH
END_VAR
VAR_OUTPUT
    bPump_Run : BOOL; // Feed pump command
    bValve_Feed : BOOL; // Feed valve command
    bValve_Filtrate : BOOL; // Filtrate valve command
    bValve_Backwash : BOOL; // Backwash valve command
    bValve_AirScour : BOOL; // Air scour valve command
    bValve_ChemDosing : BOOL; // Chemical dosing valve command
    bAlarm_Fouling : BOOL; // TMP High Fouling Alarm
    bAlarm_MIT_Fail : BOOL; // MIT Failure Alarm
    iState : INT; // Current state of the UF machine
    rTMP : REAL; // Calculated Transmembrane Pressure
    rPermeability : REAL; // Calculated Permeability
END_VAR
VAR
    State : INT := 0; 
    // 0 = Idle, 1 = Filtration, 2 = Backwash Prep, 3 = Air Scour, 
    // 4 = Backwash, 5 = CEB Dosing, 6 = CEB Soak, 7 = MIT Pressurize, 8 = MIT Decay

    tStateTimer : TON;
    rViscosityCorrection : REAL;

    // Configurable Parameters
    rMaxTMP : REAL := 1.5; // Max allowable TMP (bar)
    rMIT_TestPressure : REAL := 2.0; // Bar
    rMIT_MaxDecayRate : REAL := 0.05; // Bar/min
    tFiltrationDuration : TIME := T#30M;
    tBackwashDuration : TIME := T#60S;
    tAirScourDuration : TIME := T#30S;
    tCEBSoakDuration : TIME := T#15M;
    tMITPressurizeTime : TIME := T#2M;
    tMITDecayTime : TIME := T#5M;

    rMIT_StartPressure : REAL;
    bCEB_Required : BOOL := FALSE;
    iCycles_Since_CEB : INT := 0;
END_VAR

// 1. Calculate TMP and Permeability
rTMP := rFeed_Pressure - rFiltrate_Pressure;

// Temperature correction for viscosity (empirical approximation)
rViscosityCorrection := EXP(0.0239 * (20.0 - rTemperature));

IF rTMP > 0.0 AND rFlow_Rate > 0.0 THEN
    rPermeability := (rFlow_Rate / rTMP) * rViscosityCorrection;
ELSE
    rPermeability := 0.0;
END_IF;

// TMP Fouling Check
IF rTMP >= rMaxTMP THEN
    bAlarm_Fouling := TRUE;
    bCEB_Required := TRUE; // Force CEB on next cycle
END_IF;

// 2. State Machine
tStateTimer(IN := bEnable, PT := T#1D); // Reset dynamically

CASE State OF
    0: // IDLE
        bPump_Run := FALSE;
        bValve_Feed := FALSE;
        bValve_Filtrate := FALSE;
        bValve_Backwash := FALSE;
        bValve_AirScour := FALSE;
        bValve_ChemDosing := FALSE;

        IF bEnable THEN
            IF bStart_MIT THEN
                State := 7; // Jump to MIT
                tStateTimer(IN := FALSE);
            ELSIF bStart_CEB OR bCEB_Required THEN
                State := 2; // Jump to BW/CEB
                tStateTimer(IN := FALSE);
            ELSE
                State := 1; // Start Filtration
                tStateTimer(IN := FALSE);
            END_IF;
        END_IF;

    1: // FILTRATION
        bPump_Run := TRUE;
        bValve_Feed := TRUE;
        bValve_Filtrate := TRUE;
        tStateTimer(IN := TRUE, PT := tFiltrationDuration);

        IF tStateTimer.Q THEN
            State := 2;
            tStateTimer(IN := FALSE);
            iCycles_Since_CEB := iCycles_Since_CEB + 1;
        END_IF;

    2: // BACKWASH PREP (Drain/Flush)
        bPump_Run := FALSE;
        bValve_Feed := FALSE;
        bValve_Filtrate := FALSE;
        tStateTimer(IN := TRUE, PT := T#10S);

        IF tStateTimer.Q THEN
            State := 3;
            tStateTimer(IN := FALSE);
        END_IF;

    3: // AIR SCOUR
        bValve_AirScour := TRUE;
        tStateTimer(IN := TRUE, PT := tAirScourDuration);

        IF tStateTimer.Q THEN
            bValve_AirScour := FALSE;
            State := 4;
            tStateTimer(IN := FALSE);
        END_IF;

    4: // BACKWASH
        bValve_Backwash := TRUE;
        tStateTimer(IN := TRUE, PT := tBackwashDuration);

        IF tStateTimer.Q THEN
            bValve_Backwash := FALSE;
            IF bCEB_Required OR bStart_CEB OR iCycles_Since_CEB >= 10 THEN
                State := 5; // Go to CEB
            ELSE
                State := 0; // Return to Idle
            END_IF;
            tStateTimer(IN := FALSE);
        END_IF;

    5: // CEB DOSING
        bValve_Backwash := TRUE;
        bValve_ChemDosing := TRUE;
        tStateTimer(IN := TRUE, PT := T#30S);

        IF tStateTimer.Q THEN
            bValve_Backwash := FALSE;
            bValve_ChemDosing := FALSE;
            State := 6;
            tStateTimer(IN := FALSE);
        END_IF;

    6: // CEB SOAK
        // All valves closed, soaking in chemical
        tStateTimer(IN := TRUE, PT := tCEBSoakDuration);

        IF tStateTimer.Q THEN
            bCEB_Required := FALSE;
            bStart_CEB := FALSE;
            iCycles_Since_CEB := 0;
            State := 2; // Follow with a backwash to clear chemicals
            tStateTimer(IN := FALSE);
        END_IF;

    7: // MIT PRESSURIZE
        bValve_AirScour := TRUE; // Use air to pressurize the module
        bValve_Filtrate := FALSE;
        bValve_Feed := FALSE;
        tStateTimer(IN := TRUE, PT := tMITPressurizeTime);

        IF rFeed_Pressure >= rMIT_TestPressure OR tStateTimer.Q THEN
            bValve_AirScour := FALSE;
            rMIT_StartPressure := rFeed_Pressure;
            State := 8;
            tStateTimer(IN := FALSE);
        END_IF;

    8: // MIT DECAY TEST
        tStateTimer(IN := TRUE, PT := tMITDecayTime);

        IF tStateTimer.Q THEN
            IF (rMIT_StartPressure - rFeed_Pressure) > (rMIT_MaxDecayRate * 5.0) THEN // 5 minutes decay
                bAlarm_MIT_Fail := TRUE;
            END_IF;
            bStart_MIT := FALSE;
            State := 0;
            tStateTimer(IN := FALSE);
        END_IF;

END_CASE;

iState := State;
``END_FUNCTION_BLOCK
`
