FUNCTION_BLOCK FB_Gigafactory_BatteryProduction
VAR_INPUT
    bEnable : BOOL; // System enable
    rSlurryViscosity_cP : REAL; // Current slurry viscosity in centipoise
    rTargetViscosity_cP : REAL; // Target viscosity
    rCalenderingTension_N : REAL; // Current roll-to-roll tension in Newtons
    rTargetTension_N : REAL; // Target tension
    rCellVoltage_V : REAL; // Cell formation voltage
    rCellCurrent_A : REAL; // Cell formation current
    rCellTemp_C : REAL; // Cell temperature
    tCycleTime : TIME; // Task cycle time
END_VAR
VAR_OUTPUT
    rMixerSpeed_RPM : REAL; // Output mixer speed to adjust viscosity
    rSolventValve_Pct : REAL; // Output solvent valve position (0-100%)
    rTensionMotor_Torque : REAL; // Output tensioning motor torque command
    bGradeA_Cell : BOOL; // High quality cell
    bGradeB_Cell : BOOL; // Medium quality cell
    bRejectCell : BOOL; // Failed cell
    wErrorCode : WORD; // System error code
    bSystemReady : BOOL;
END_VAR
VAR
    // PID for Viscosity
    rViscosityError : REAL;
    rViscosityIntegral : REAL;
    rViscosityDerivative : REAL;
    rViscosityLastError : REAL;
    rKp_Visc : REAL := 2.5;
    rKi_Visc : REAL := 0.1;
    rKd_Visc : REAL := 0.05;

    // PID for Tension
    rTensionError : REAL;
    rTensionIntegral : REAL;
    rTensionDerivative : REAL;
    rTensionLastError : REAL;
    rKp_Tens : REAL := 5.0;
    rKi_Tens : REAL := 0.2;
    rKd_Tens : REAL := 0.1;

    // State machine for cell formation
    nFormationState : INT := 0;
    rTotalCharge_Ah : REAL := 0.0;

    // Timers
    fbMixerTimer : TON;
    fbFormationTimer : TON;

    // Internal calculations
    rDt : REAL;
END_VAR

// Conversion of cycle time to seconds
rDt := TIME_TO_REAL(tCycleTime) / 1000.0;
IF rDt <= 0.0 THEN
    rDt := 0.01;
END_IF;

IF NOT bEnable THEN
    rMixerSpeed_RPM := 0.0;
    rSolventValve_Pct := 0.0;
    rTensionMotor_Torque := 0.0;
    bSystemReady := FALSE;
    wErrorCode := 16#0001; // Disabled
    rViscosityIntegral := 0.0;
    rTensionIntegral := 0.0;
    nFormationState := 0;
    RETURN;
ELSE
    bSystemReady := TRUE;
    wErrorCode := 16#0000;
END_IF;

// =========================================================
// 1. Slurry Mixing Viscosity Control (PID)
// =========================================================
rViscosityError := rTargetViscosity_cP - rSlurryViscosity_cP;
rViscosityIntegral := rViscosityIntegral + (rViscosityError * rDt);
// Anti-windup
IF rViscosityIntegral > 1000.0 THEN rViscosityIntegral := 1000.0; END_IF;
IF rViscosityIntegral < -1000.0 THEN rViscosityIntegral := -1000.0; END_IF;

rViscosityDerivative := (rViscosityError - rViscosityLastError) / rDt;
rViscosityLastError := rViscosityError;

rMixerSpeed_RPM := (rKp_Visc * rViscosityError) + (rKi_Visc * rViscosityIntegral) + (rKd_Visc * rViscosityDerivative);

// Limit mixer speed and adjust solvent
IF rMixerSpeed_RPM > 1500.0 THEN
    rMixerSpeed_RPM := 1500.0;
    rSolventValve_Pct := 10.0; // Open solvent to thin if speed is saturated
ELSIF rMixerSpeed_RPM < 100.0 THEN
    rMixerSpeed_RPM := 100.0;
    rSolventValve_Pct := 0.0;
ELSE
    rSolventValve_Pct := 0.0;
END_IF;

// =========================================================
// 2. Roll-to-Roll Calendering Tension Control (PID)
// =========================================================
rTensionError := rTargetTension_N - rCalenderingTension_N;
rTensionIntegral := rTensionIntegral + (rTensionError * rDt);
// Anti-windup
IF rTensionIntegral > 500.0 THEN rTensionIntegral := 500.0; END_IF;
IF rTensionIntegral < -500.0 THEN rTensionIntegral := -500.0; END_IF;

rTensionDerivative := (rTensionError - rTensionLastError) / rDt;
rTensionLastError := rTensionError;

rTensionMotor_Torque := (rKp_Tens * rTensionError) + (rKi_Tens * rTensionIntegral) + (rKd_Tens * rTensionDerivative);

IF rTensionMotor_Torque > 100.0 THEN rTensionMotor_Torque := 100.0; END_IF;
IF rTensionMotor_Torque < -10.0 THEN rTensionMotor_Torque := -10.0; END_IF;

// =========================================================
// 3. Cell Formation Grading & Integration
// =========================================================
CASE nFormationState OF
    0: // Initialization
        bGradeA_Cell := FALSE;
        bGradeB_Cell := FALSE;
        bRejectCell := FALSE;
        rTotalCharge_Ah := 0.0;
        IF rCellVoltage_V > 2.5 THEN // Cell detected
            nFormationState := 10;
        END_IF;

    10: // Pre-charge phase
        // Calculate Ah
        rTotalCharge_Ah := rTotalCharge_Ah + (rCellCurrent_A * rDt / 3600.0);
        IF rCellVoltage_V > 3.0 THEN
            nFormationState := 20; // Move to constant current
        END_IF;
        IF rCellTemp_C > 45.0 THEN
            nFormationState := 99; // Reject on temp limit
        END_IF;

    20: // Constant Current (CC) phase
        rTotalCharge_Ah := rTotalCharge_Ah + (rCellCurrent_A * rDt / 3600.0);
        IF rCellVoltage_V >= 4.2 THEN
            nFormationState := 30; // Move to constant voltage
        END_IF;
        IF rCellTemp_C > 50.0 THEN
            nFormationState := 99;
        END_IF;

    30: // Constant Voltage (CV) phase
        rTotalCharge_Ah := rTotalCharge_Ah + (rCellCurrent_A * rDt / 3600.0);
        IF rCellCurrent_A < 0.05 THEN
            nFormationState := 40; // Grading
        END_IF;

    40: // Grading Evaluation
        IF rTotalCharge_Ah >= 3.2 AND rTotalCharge_Ah <= 3.5 AND rCellTemp_C < 40.0 THEN
            bGradeA_Cell := TRUE;
        ELSIF rTotalCharge_Ah >= 3.0 AND rTotalCharge_Ah < 3.2 THEN
            bGradeB_Cell := TRUE;
        ELSE
            bRejectCell := TRUE;
            wErrorCode := 16#0002; // Capacity issue
        END_IF;

    99: // Error state
        bRejectCell := TRUE;
        wErrorCode := 16#0003; // Temperature fault

END_CASE;

END_FUNCTION_BLOCK
