    ST_VibratorFeedback : STRUCT
        MassAcceleration   : REAL; // Feedback from mass accelerometer (g)
        BaseplatePhase     : REAL; // Baseplate phase angle (radians)
        HydraulicPressure  : REAL; // System pressure (PSI)
        LVDTPosition       : REAL; // Valve spool position (mm)
        IsReady            : BOOL; // Truck ready status
    END_STRUCT;

    // Structure for individual truck command outputs
    ST_VibratorCommand : STRUCT
        ServoDriveSignal   : REAL; // Command to pilot servo valve (-10V to +10V)
        Enable             : BOOL; // Hydraulic system enable
        PhaseError         : REAL; // Calculated phase error for telemetry
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_VibroseisArrayController
VAR_INPUT
    bStartSweep         : BOOL; // Trigger for vibroseis sweep
    bAbort              : BOOL; // Emergency abort
    fStartFreq          : REAL := 10.0; // Start frequency (Hz)
    fEndFreq            : REAL := 100.0; // End frequency (Hz)
    fSweepDuration      : REAL := 12.0; // Sweep duration (seconds)
    fTaperTime          : REAL := 0.5; // Cosine taper time at start/end (seconds)
    aTruckFeedback      : ARRAY[1..4] OF ST_VibratorFeedback; // Feedback from 4 trucks
END_VAR

VAR_OUTPUT
    aTruckCommand       : ARRAY[1..4] OF ST_VibratorCommand; // Commands to 4 trucks
    bSweepActive        : BOOL; // Indicates active sweep
    bSweepComplete      : BOOL; // Indicates sweep successfully completed
    bError              : BOOL; // Fault flag
    sStatusMsg          : STRING(50); // Status or error message
END_VAR

VAR
    // Internal state variables
    fElapsedTime        : REAL; // Sweep timer (s)
    fCurrentFreq        : REAL; // Current target frequency (Hz)
    fTargetPhase        : REAL; // Master reference phase (radians)
    fTargetAmplitude    : REAL; // Master reference amplitude (normalized 0.0-1.0)

    // Tapering (Envelope) Variables
    fEnvelope           : REAL; 

    // PID / PLL Loop Variables
    aPhaseError         : ARRAY[1..4] OF REAL;
    aPhaseIntegral      : ARRAY[1..4] OF REAL;

    // System cycle time
    fDeltaT             : REAL := 0.001; // 1 ms scan rate

    // Control constants
    Kp_Phase            : REAL := 2.5;
    Ki_Phase            : REAL := 0.1;
    Kd_Phase            : REAL := 0.05;
    MAX_DRIVE           : REAL := 10.0; // Max voltage to servo

    i                   : INT;
    bAllReady           : BOOL;
END_VAR

// 1. Safety and Readiness Checks
IF bAbort THEN
    bSweepActive := FALSE;
    bSweepComplete := FALSE;
    bError := TRUE;
    sStatusMsg := 'ABORT TRIGGERED: System Halted.';
    FOR i := 1 TO 4 DO
        aTruckCommand[i].ServoDriveSignal := 0.0;
        aTruckCommand[i].Enable := FALSE;
    END_FOR;
    RETURN;
END_IF;

bAllReady := TRUE;
FOR i := 1 TO 4 DO
    IF NOT aTruckFeedback[i].IsReady THEN
        bAllReady := FALSE;
    END_IF;
END_FOR;

// 2. State Machine for Sweep Operation
IF bStartSweep AND NOT bSweepActive AND bAllReady THEN
    // Initialize Sweep
    bSweepActive := TRUE;
    bSweepComplete := FALSE;
    bError := FALSE;
    fElapsedTime := 0.0;
    fTargetPhase := 0.0;
    sStatusMsg := 'SWEEP ACTIVE';

    FOR i := 1 TO 4 DO
        aTruckCommand[i].Enable := TRUE;
        aPhaseIntegral[i] := 0.0;
    END_FOR;
END_IF;

// 3. Main Sweep Logic (Active State)
IF bSweepActive THEN
    fElapsedTime := fElapsedTime + fDeltaT;

    IF fElapsedTime >= fSweepDuration THEN
        // Sweep Finished
        bSweepActive := FALSE;
        bSweepComplete := TRUE;
        sStatusMsg := 'SWEEP COMPLETE';
        FOR i := 1 TO 4 DO
            aTruckCommand[i].ServoDriveSignal := 0.0;
            aTruckCommand[i].Enable := FALSE;
        END_FOR;
    ELSE
        // A. Sweep Frequency Chirp Modulation (Linear)
        // f(t) = f0 + (k * t), where k = (f1 - f0) / T
        fCurrentFreq := fStartFreq + ((fEndFreq - fStartFreq) / fSweepDuration) * fElapsedTime;

        // Master Phase integration: Phase = Integral of (2 * PI * f(t)) dt
        fTargetPhase := fTargetPhase + (2.0 * 3.14159265359 * fCurrentFreq * fDeltaT);

        // Wrap phase between -PI and +PI for numeric stability
        IF fTargetPhase > 3.14159265359 THEN
            fTargetPhase := fTargetPhase - (2.0 * 3.14159265359);
        END_IF;

        // B. Amplitude Tapering (Cosine Taper to prevent shock to hydraulics)
        IF fElapsedTime < fTaperTime THEN
            fEnvelope := 0.5 * (1.0 - COS(3.14159265359 * fElapsedTime / fTaperTime));
        ELSIF fElapsedTime > (fSweepDuration - fTaperTime) THEN
            fEnvelope := 0.5 * (1.0 - COS(3.14159265359 * (fSweepDuration - fElapsedTime) / fTaperTime));
        ELSE
            fEnvelope := 1.0;
        END_IF;

        // Calculate master drive signal before phase correction
        fTargetAmplitude := fEnvelope * SIN(fTargetPhase);

        // C. Phase Locking Across 4 Separate 60,000lb Trucks
        FOR i := 1 TO 4 DO
            // Calculate phase difference (Error)
            aPhaseError[i] := fTargetPhase - aTruckFeedback[i].BaseplatePhase;

            // Handle phase wrapping in error calculation
            IF aPhaseError[i] > 3.14159265359 THEN
                aPhaseError[i] := aPhaseError[i] - (2.0 * 3.14159265359);
            ELSIF aPhaseError[i] < -3.14159265359 THEN
                aPhaseError[i] := aPhaseError[i] + (2.0 * 3.14159265359);
            END_IF;

            // Phase PID Compensation (PLL equivalent)
            aPhaseIntegral[i] := aPhaseIntegral[i] + (aPhaseError[i] * fDeltaT);

            // Combined control: feedforward (master sine) + PID phase correction
            aTruckCommand[i].ServoDriveSignal := (fTargetAmplitude * MAX_DRIVE) 
                                               + (Kp_Phase * aPhaseError[i]) 
                                               + (Ki_Phase * aPhaseIntegral[i]);

            // Output Limiting (Saturation protection for servo valves)
            IF aTruckCommand[i].ServoDriveSignal > MAX_DRIVE THEN
                aTruckCommand[i].ServoDriveSignal := MAX_DRIVE;
            ELSIF aTruckCommand[i].ServoDriveSignal < -MAX_DRIVE THEN
                aTruckCommand[i].ServoDriveSignal := -MAX_DRIVE;
            END_IF;

            // Diagnostic outputs
            aTruckCommand[i].PhaseError := aPhaseError[i];
        END_FOR;
    END_IF;
ELSIF NOT bStartSweep AND NOT bError THEN
    sStatusMsg := 'READY FOR SWEEP';
END_IF;
END_FUNCTION_BLOCK
``n
### Key Engineering Architecture Points:
1. **Chirp Modulation**: The block dynamically calculates  CurrentFreq linearly interpolating between 10Hz and 100Hz over  SweepDuration. Target phase is rigorously mathematically integrated at each scan cycle ( DeltaT).
2. **Synchronized Phase-Locked Loop (PLL)**: A dedicated discrete PID controller exists for each of the 4 vibrators (PhaseError). It continuously compares the calculated absolute master phase against the measured BaseplatePhase from the ST_VibratorFeedback, correcting hydraulic servo drive independently to ensure all 4 massive 60,000lb masses remain perfectly aligned to generate constructive P-waves.
3. **Envelope Modulation**: Prevents cavitation and hydraulic fluid hammer through cosine tapering. Amplitude softly scales up at the start and gracefully scales down at the end.
