FUNCTION_BLOCK FB_BloodFractionation_Centrifuge
(* 
   Advanced Biomedical High-Throughput Robotic Blood Fractionation Centrifuge
   Features:
   - 100,000 RPM Magnetic Levitation Rotor Harmonic Balancing
   - Optical Buffy-Coat Layer Phase Detection
   - Sterile Closed-Loop Pneumatic Aspiration
   - Active PID-based Acceleration/Deceleration Control
   - Multi-layered Safety Interlocks
*)
VAR_INPUT
    (* Minimum 4-8 physical inputs with types and comments *)
    bSystemEnable            : BOOL;     (* System master enable signal *)
    bEmergencyStop           : BOOL;     (* Safety relay OK signal (E-Stop chain) *)
    bVacuumSealOK            : BOOL;     (* Centrifuge chamber vacuum seal integrity *)
    rRotorSpeedMeas          : REAL;     (* Measured rotor speed in RPM via hall effect *)
    rVibrationSensor_X       : REAL;     (* X-axis harmonic vibration measurement (mm/s) *)
    rVibrationSensor_Y       : REAL;     (* Y-axis harmonic vibration measurement (mm/s) *)
    rOpticalDensityPhase     : REAL;     (* Optical density for buffy-coat detection (0.0-1.0) *)
    rAspirationPressure      : REAL;     (* Closed-loop pneumatic aspiration pressure (mbar) *)
END_VAR

VAR_OUTPUT
    (* Minimum 3-6 outputs with types and comments *)
    bSystemReady             : BOOL;     (* Overall system ready status *)
    rRotorDriveCmd           : REAL;     (* VFD drive control signal for mag-lev rotor (0-100%) *)
    rPneumaticValveCmd       : REAL;     (* Proportional valve command for aspiration (0-100%) *)
    bOpticalLayerDetected    : BOOL;     (* Buffy-coat layer successfully isolated and detected *)
    bFaultAlarm              : BOOL;     (* Critical fault alarm output (vibration, speed, seal) *)
    iOperationState          : INT;      (* Current operation state machine step *)
END_VAR

VAR
    (* Internal state variables *)
    iState                   : INT := 0;
    rTargetSpeed             : REAL := 0.0;
    rSpeedError              : REAL := 0.0;
    rSpeedIntegral           : REAL := 0.0;
    rVibrationMagnitude      : REAL := 0.0;
    tProcessTimer            : TON;
    tExtractionTimer         : TON;

    (* PID Constants for Mag-Lev Rotor *)
    Kp_Rotor                 : REAL := 0.015;
    Ki_Rotor                 : REAL := 0.005;

    (* Safety limits *)
    MAX_VIBRATION            : REAL := 2.5;     (* mm/s maximum acceptable vibration *)
    MAX_SPEED_RPM            : REAL := 105000.0;(* Absolute maximum speed *)
    BUFFY_COAT_THRESHOLD     : REAL := 0.68;    (* Optical density target for buffy-coat *)
END_VAR

(* === MAIN LOGIC === *)
(* Multi-Layered Safety Interlocks *)
IF NOT bEmergencyStop OR NOT bVacuumSealOK THEN
    bSystemReady := FALSE;
    bFaultAlarm := TRUE;
    rRotorDriveCmd := 0.0;
    rPneumaticValveCmd := 0.0;
    iState := 999; (* Fault State *)
    iOperationState := iState;
    RETURN;
END_IF;

(* Compute combined harmonic vibration magnitude *)
rVibrationMagnitude := SQRT((rVibrationSensor_X * rVibrationSensor_X) + (rVibrationSensor_Y * rVibrationSensor_Y));
IF rVibrationMagnitude > MAX_VIBRATION OR rRotorSpeedMeas > MAX_SPEED_RPM THEN
    bSystemReady := FALSE;
    bFaultAlarm := TRUE;
    rRotorDriveCmd := 0.0;
    iState := 999;
    iOperationState := iState;
    RETURN;
END_IF;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE & SYSTEM CHECK *)
        bSystemReady := TRUE;
        bFaultAlarm := FALSE;
        rTargetSpeed := 0.0;
        bOpticalLayerDetected := FALSE;
        rPneumaticValveCmd := 0.0;

        IF bSystemEnable THEN
            iState := 10; (* STARTUP RAMP *)
        END_IF;

    10: (* RAMP TO FRACTIONATION SPEED *)
        rTargetSpeed := 100000.0; (* 100k RPM for ultra-high-G fractionation *)

        (* Simple PID Control for Rotor Drive *)
        rSpeedError := rTargetSpeed - rRotorSpeedMeas;
        rSpeedIntegral := rSpeedIntegral + rSpeedError;
        rRotorDriveCmd := (Kp_Rotor * rSpeedError) + (Ki_Rotor * rSpeedIntegral);

        (* Limit drive command 0 to 100% *)
        IF rRotorDriveCmd > 100.0 THEN
            rRotorDriveCmd := 100.0;
        ELSIF rRotorDriveCmd < 0.0 THEN
            rRotorDriveCmd := 0.0;
        END_IF;

        (* Check if target speed reached *)
        IF ABS(rSpeedError) < 500.0 THEN
            tProcessTimer(IN := TRUE, PT := T#120S); (* Centrifuge for 2 minutes *)
            IF tProcessTimer.Q THEN
                tProcessTimer(IN := FALSE);
                iState := 20; (* OPTICAL DETECTION & ASPIRATION *)
            END_IF;
        END_IF;

    20: (* OPTICAL DETECTION & PNEUMATIC ASPIRATION *)
        (* Maintain speed *)
        rSpeedError := rTargetSpeed - rRotorSpeedMeas;
        rSpeedIntegral := rSpeedIntegral + rSpeedError;
        rRotorDriveCmd := (Kp_Rotor * rSpeedError) + (Ki_Rotor * rSpeedIntegral);

        IF rOpticalDensityPhase >= (BUFFY_COAT_THRESHOLD - 0.05) AND rOpticalDensityPhase <= (BUFFY_COAT_THRESHOLD + 0.05) THEN
            bOpticalLayerDetected := TRUE;

            (* Closed-loop sterile aspiration control *)
            IF rAspirationPressure < 150.0 THEN
                rPneumaticValveCmd := 75.0; (* Open proportional valve to 75% *)
            ELSE
                rPneumaticValveCmd := 40.0; (* Modulate to maintain aspiration rate *)
            END_IF;

            tExtractionTimer(IN := TRUE, PT := T#15S);
            IF tExtractionTimer.Q THEN
                tExtractionTimer(IN := FALSE);
                rPneumaticValveCmd := 0.0; (* Close valve *)
                iState := 30; (* DECELERATION *)
            END_IF;
        ELSE
            bOpticalLayerDetected := FALSE;
            rPneumaticValveCmd := 0.0;
        END_IF;

    30: (* DECELERATION TO STOP *)
        rTargetSpeed := 0.0;
        rSpeedIntegral := 0.0;
        rRotorDriveCmd := 0.0; (* Active braking handled by external VFD via 0.0 cmd *)

        IF rRotorSpeedMeas < 10.0 THEN
            iState := 0; (* COMPLETE, RETURN TO IDLE *)
        END_IF;

    999: (* FAULT HANDLING *)
        rTargetSpeed := 0.0;
        rRotorDriveCmd := 0.0;
        rPneumaticValveCmd := 0.0;
        bSystemReady := FALSE;
        IF NOT bEmergencyStop THEN
            bFaultAlarm := TRUE;
        ELSE
            IF bSystemEnable = FALSE AND bVacuumSealOK = TRUE AND rVibrationMagnitude < 1.0 THEN
                iState := 0; (* Reset fault if enable is cleared and conditions OK *)
            END_IF;
        END_IF;

END_CASE;

iOperationState := iState;

END_FUNCTION_BLOCK
