    // Security Check
    IF Primary_PN_Cmd.Auth_Token <> Expected_Auth_Token THEN
        Cyber_Incident := TRUE;
        SCADA_Status := 16#F000;
        Speed_Command := 0.0;
        RETURN;
    END_IF;

    // Adversarial Sensor Drift Detection (Redundant Encoders)
    IF ABS(Encoder_1_Angle - Encoder_2_Angle) > 2.0 THEN
        Sensor_Drift_Error := TRUE;
        SCADA_Status := SCADA_Status OR 16#0800;
        Validated_Angle := Encoder_1_Angle; // Fallback to primary
    ELSE
        Validated_Angle := (Encoder_1_Angle + Encoder_2_Angle) / 2.0;
    END_IF;

    // HIL Digital Twin Sync Check
    IF ABS(Actual_Speed - HIL_Twin_Speed_Est) > 10.0 THEN
        HIL_Mismatch_Error := TRUE;
        SCADA_Status := SCADA_Status OR 16#0400;
    END_IF;

    // Self-Test Routine Injection
    IF Self_Test_Trigger AND NOT Vessel_Underway THEN
        Self_Test_Active := TRUE;
        Test_Timer := Test_Timer + 1;
        IF Test_Timer < 100 THEN
            Angle_Command := 45.0; // Test Vector 1
            Speed_Command := 10.0;
        ELSIF Test_Timer < 200 THEN
            Angle_Command := -45.0; // Test Vector 2
            Speed_Command := 15.0;
        ELSE
            Test_Timer := 0;
            Self_Test_Active := FALSE;
        END_IF;
        RETURN;
    ELSIF Self_Test_Trigger AND Vessel_Underway THEN
        Self_Test_Active := FALSE; // Block test if underway
    END_IF;

    Enable := (Primary_PN_Cmd.Control_Word AND 16#0001) <> 0;
    IF NOT Enable THEN
        Speed_Command := 0.0;
        Angle_Command := Validated_Angle;
        SCADA_Status := 16#0000;
        RETURN;
    END_IF;

    SCADA_Status := 16#0001;

    // DP Logic
    Req_Thrust := SQRT(Primary_PN_Cmd.DP_Force_X**2 + Primary_PN_Cmd.DP_Force_Y**2);
    IF Primary_PN_Cmd.DP_Force_X <> 0.0 THEN
        Req_Angle := ATAN(Primary_PN_Cmd.DP_Force_Y / Primary_PN_Cmd.DP_Force_X) * 57.2958;
    ELSE
        Req_Angle := 0.0;
    END_IF;

    // Overload Protection
    Current_Filter := Current_Filter + 0.1 * (Motor_Current - Current_Filter);
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
        SCADA_Status := SCADA_Status OR 16#0002;
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    IF Overload_Active THEN
        Speed_Command := Req_Thrust * 0.5;
    ELSE
        Speed_Command := Req_Thrust;
    END_IF;
    Angle_Command := Req_Angle;
END_FUNCTION_BLOCK
