FUNCTION_BLOCK FB_ProtonGantryControl
TITLE = 'Advanced Proton Therapy Gantry Control'
VERSION : '2.4'

VAR_INPUT
    rGantryAngle_deg : REAL; // 0.0 to 360.0, Absolute rotation angle of the 100-ton gantry
    rBeamEnergy_MeV : REAL; // 70.0 to 250.0, Proton beam energy from cyclotron
    rTargetIsoX_mm : REAL; // Target isocenter X coordinate in millimeter
    rTargetIsoY_mm : REAL; // Target isocenter Y coordinate in millimeter
    rTargetIsoZ_mm : REAL; // Target isocenter Z coordinate in millimeter
    bBeamOnRequest : BOOL; // Request from treatment control system to initiate beam
    rTempMagnet_C : REAL; // Temperature of superconducting steering magnets
    rStrainGauge1_uV : REAL; // Structural deformation sensor 1 (Gantry arm)
    rStrainGauge2_uV : REAL; // Structural deformation sensor 2 (Nozzle mount)
END_VAR

VAR_OUTPUT
    rMagnetX_Current_A : REAL; // Output current setpoint for X-axis steering magnet
    rMagnetY_Current_A : REAL; // Output current setpoint for Y-axis steering magnet
    rGantryMotorDrive_Torque : REAL; // Holding torque for massive gantry structure
    bSafetyInterlockOK : BOOL; // Master safety interlock signal (Hardware tied)
    bBeamReady : BOOL; // Status signal indicating system is ready for beam delivery
    iErrorCode : INT; // Diagnostic error code (0 = OK)
END_VAR

VAR
    // Internal state variables for highly complex calculations
    rStructuralSagX_mm : REAL; // Calculated mechanical deformation in X
    rStructuralSagY_mm : REAL; // Calculated mechanical deformation in Y
    rCompensatedIsoX_mm : REAL; // Dynamically compensated X target
    rCompensatedIsoY_mm : REAL; // Dynamically compensated Y target
    rEnergyFactor : REAL; // Scaling factor based on relativistic proton mass
    rAngleRad : REAL; // Gantry angle converted to radians
    bTempLimit : BOOL; // Boolean flag for thermal safety
    bDeformationLimit : BOOL; // Boolean flag for structural safety
    bTargetReached : BOOL; // Logical condition for steering stabilization

    // System Constants for Deterministic Constraints
    MAX_TEMP : REAL := 45.0; // Maximum allowed magnet temp (Celsius)
    MAX_DEFORMATION : REAL := 1.5; // Maximum allowed physical sag (mm)
    PI : REAL := 3.14159265359;
    MAX_MAGNET_CURRENT : REAL := 500.0; // Amperes
END_VAR

// Implementation Logic: Advanced Iso-Center Beam Steering & Gantry Compensation
// -----------------------------------------------------------------------------

// 1. Calculate structural sag based on 100-ton gantry angle
rAngleRad := rGantryAngle_deg * (PI / 180.0);

// Complex harmonic compensation for mechanical deflection (multi-point structural model)
rStructuralSagX_mm := 0.45 * SIN(rAngleRad) + 0.12 * SIN(2.0 * rAngleRad) - 0.05 * COS(3.0 * rAngleRad);
rStructuralSagY_mm := 0.65 * COS(rAngleRad) - 0.08 * COS(2.0 * rAngleRad) + 0.03 * SIN(3.0 * rAngleRad);

// 2. Integrate dynamic strain gauge feedback for real-time micro-adjustments
// Gain scheduled structural model refinement
rStructuralSagX_mm := rStructuralSagX_mm + (rStrainGauge1_uV * 0.00012);
rStructuralSagY_mm := rStructuralSagY_mm + (rStrainGauge2_uV * 0.00015);

// 3. Compensate Target Iso-Center based on deformation matrices
rCompensatedIsoX_mm := rTargetIsoX_mm - rStructuralSagX_mm;
rCompensatedIsoY_mm := rTargetIsoY_mm - rStructuralSagY_mm;

// 4. Calculate Magnetic Steering Currents (Beam Energy Dependent)
// Relativistic mass scaling: Higher energy requires exponentially more flux
rEnergyFactor := SQRT(rBeamEnergy_MeV / 250.0);

rMagnetX_Current_A := (rCompensatedIsoX_mm * 2.345) * rEnergyFactor;
rMagnetY_Current_A := (rCompensatedIsoY_mm * 2.345) * rEnergyFactor;

// 5. Evaluate Sub-Millimeter Safety Interlocks & Operational Limits
bTempLimit := rTempMagnet_C <= MAX_TEMP;
bDeformationLimit := (ABS(rStructuralSagX_mm) <= MAX_DEFORMATION) AND (ABS(rStructuralSagY_mm) <= MAX_DEFORMATION);

IF rGantryAngle_deg < 0.0 OR rGantryAngle_deg >= 360.0 THEN
    iErrorCode := 101; // E_INVALID_ANGLE
    bSafetyInterlockOK := FALSE;
ELSIF NOT bTempLimit THEN
    iErrorCode := 201; // E_MAGNET_THERMAL_OVERLOAD
    bSafetyInterlockOK := FALSE;
ELSIF NOT bDeformationLimit THEN
    iErrorCode := 301; // E_STRUCTURAL_DEFORMATION_CRITICAL
    bSafetyInterlockOK := FALSE;
ELSE
    iErrorCode := 0; // SYSTEM_NOMINAL
    bSafetyInterlockOK := TRUE;
END_IF;

// 6. Evaluate Final Beam Ready Status
// Beam can only trigger if magnetic currents are within DAC limits
bTargetReached := (ABS(rMagnetX_Current_A) <= MAX_MAGNET_CURRENT) AND (ABS(rMagnetY_Current_A) <= MAX_MAGNET_CURRENT);

bBeamReady := bSafetyInterlockOK AND bTargetReached AND bBeamOnRequest;

// 7. Compute Gantry Motor Holding Torque to counteract gravitational moments
// Variable load based on cantilevered nozzle extension
rGantryMotorDrive_Torque := 15000.0 * COS(rAngleRad) + 500.0 * SIN(rAngleRad); // Nm

END_FUNCTION_BLOCK
