FUNCTION_BLOCK FB_EGS_Control_Core
VAR_INPUT
    bSystemEnable : BOOL;
    fInjectionPressure_Bar : REAL; // High-pressure stimulation injection well pressure
    fInjectionFlow_kg_s : REAL; // Injection flow rate
    fWellheadTemp_C : REAL; // Production wellhead temperature
    fWellheadPressure_Bar : REAL; // Production wellhead pressure
    fORCEvaporatorTemp_C : REAL; // ORC working fluid temperature entering evaporator
    fORCCondenserTemp_C : REAL; // ORC working fluid temperature entering condenser
    fGridDemand_MW : REAL; // Target power output
END_VAR

VAR_OUTPUT
    fInjectionValve_Pos : REAL; // 0-100% position of injection control valve
    fProductionThrottle_Pos : REAL; // 0-100% position of production wellhead throttle
    fORCTurbineBypass_Pos : REAL; // 0-100% bypass valve position for ORC turbine
    fORCPumpSpeed_RPM : REAL; // ORC working fluid feed pump speed
    bEmergShutdown : BOOL; // Emergency Shutdown active
    fActivePower_MW : REAL; // Estimated generated power
END_VAR

VAR
    fInjectionPressureSetpoint : REAL := 150.0;
    fInjectionPID_Kp : REAL := 1.5;
    fInjectionPID_Ki : REAL := 0.2;
    fInjectionPID_Kd : REAL := 0.05;
    fInjectionPID_Integral : REAL := 0.0;
    fInjectionPID_PrevError : REAL := 0.0;

    fProdTempSetpoint : REAL := 180.0; // Minimum production temp for ORC efficiency

    // ORC Loop controls
    fORCTurbineEff : REAL := 0.85;
    fORCWorkingFluidCp : REAL := 1.25; // kJ/kg.K approx for isopentane or R245fa

    // Timers
    tStimulationTimer : TIME := T#0S;
    tSafetyDelay : TIME := T#0S;

    // States
    nState : INT := 0; // 0: Off, 1: Startup, 2: Stimulation, 3: Generation, 4: Safe Shut

    fDeltaT : REAL := 0.1; // Cycle time 100ms
END_VAR

// Control Logic
IF NOT bSystemEnable THEN
    nState := 0;
    bEmergShutdown := FALSE;
    fInjectionValve_Pos := 0.0;
    fProductionThrottle_Pos := 0.0;
    fORCTurbineBypass_Pos := 100.0; // Fully bypass
    fORCPumpSpeed_RPM := 0.0;
    fInjectionPID_Integral := 0.0;
    RETURN;
END_IF;

// Safety Checks
IF fWellheadPressure_Bar > 250.0 OR fInjectionPressure_Bar > 300.0 THEN
    nState := 4; // Emergency Shutdown
    bEmergShutdown := TRUE;
END_IF;

CASE nState OF
    0: // Idle
        IF bSystemEnable AND NOT bEmergShutdown THEN
            nState := 1;
        END_IF;

    1: // Startup cascade
        // Ramp up injection pump gently
        fInjectionValve_Pos := fInjectionValve_Pos + 0.1;
        IF fInjectionValve_Pos > 20.0 THEN
            nState := 2;
        END_IF;

    2: // Stimulation / Pressurization
        // PID Control for Injection Pressure
        VAR
            fError : REAL;
            fDeriv : REAL;
            fOutput : REAL;
        END_VAR
        fError := fInjectionPressureSetpoint - fInjectionPressure_Bar;
        fInjectionPID_Integral := fInjectionPID_Integral + (fError * fDeltaT);
        fDeriv := (fError - fInjectionPID_PrevError) / fDeltaT;
        fOutput := (fInjectionPID_Kp * fError) + (fInjectionPID_Ki * fInjectionPID_Integral) + (fInjectionPID_Kd * fDeriv);

        // Anti-windup
        IF fOutput > 100.0 THEN
            fOutput := 100.0;
            fInjectionPID_Integral := fInjectionPID_Integral - (fError * fDeltaT);
        ELSIF fOutput < 0.0 THEN
            fOutput := 0.0;
            fInjectionPID_Integral := fInjectionPID_Integral - (fError * fDeltaT);
        END_IF;

        fInjectionValve_Pos := fOutput;
        fInjectionPID_PrevError := fError;

        // Wait for production temperature to rise
        IF fWellheadTemp_C > fProdTempSetpoint THEN
            nState := 3;
        END_IF;

    3: // Power Generation (ORC Loop)
        // Keep injection pressure stable (using same PID logic block as state 2, simplified here)
        fError := fInjectionPressureSetpoint - fInjectionPressure_Bar;
        fInjectionPID_Integral := fInjectionPID_Integral + (fError * fDeltaT);
        fOutput := (fInjectionPID_Kp * fError) + (fInjectionPID_Ki * fInjectionPID_Integral);
        IF fOutput > 100.0 THEN fOutput := 100.0; ELSIF fOutput < 0.0 THEN fOutput := 0.0; END_IF;
        fInjectionValve_Pos := fOutput;

        // Production wellhead thermal throttling
        // Adjust throttle to maintain temperature and pressure limits
        IF fWellheadTemp_C < fProdTempSetpoint THEN
            fProductionThrottle_Pos := MAX(0.0, fProductionThrottle_Pos - 0.5); // Choke back to let temp recover
        ELSE
            fProductionThrottle_Pos := MIN(100.0, fProductionThrottle_Pos + 0.5); // Open up to meet demand
        END_IF;

        // ORC Control
        // Close bypass to route fluid through turbine
        fORCTurbineBypass_Pos := MAX(0.0, fORCTurbineBypass_Pos - 1.0);

        // Calculate required pump speed for ORC working fluid based on grid demand
        // Rough estimation: Power = m_dot * Cp * (T_evap - T_cond) * eff
        // fGridDemand_MW * 1000 = m_dot_kW
        IF fORCEvaporatorTemp_C > fORCCondenserTemp_C + 10.0 THEN
            fORCPumpSpeed_RPM := (fGridDemand_MW * 1000.0) / (fORCWorkingFluidCp * (fORCEvaporatorTemp_C - fORCCondenserTemp_C) * fORCTurbineEff);
            fORCPumpSpeed_RPM := MIN(3600.0, MAX(500.0, fORCPumpSpeed_RPM)); // Clamp to valid pump RPM
            fActivePower_MW := (fORCPumpSpeed_RPM * fORCWorkingFluidCp * (fORCEvaporatorTemp_C - fORCCondenserTemp_C) * fORCTurbineEff) / 1000.0;
        ELSE
            fORCPumpSpeed_RPM := 0.0;
            fActivePower_MW := 0.0;
        END_IF;

    4: // Emergency Shutdown
        fInjectionValve_Pos := 0.0;
        fProductionThrottle_Pos := 0.0;
        fORCTurbineBypass_Pos := 100.0;
        fORCPumpSpeed_RPM := 0.0;
        fActivePower_MW := 0.0;
        // Require reset of bSystemEnable to restart
END_CASE;
END_FUNCTION_BLOCK
