    bHeaterPowerCmd : BOOL;
    bSchlierenTrigger : BOOL;
    bDataAcqTrigger : BOOL;
    iCurrentState : INT;
    bFaultActive : BOOL;
    sStatusMessage : STRING(50);
END_VAR
VAR
    TON_SettleTimer : TON;
    TON_TestDuration : TON;
    TON_ValveDelay : TON;
    TON_PostTestDelay : TON;
    rTargetSettlingPressure : REAL := 150.0; (* Bar *)
    rTargetVacuumPressure : REAL := 5.0; (* Torr *)
    rTargetHeaterTemp : REAL := 1500.0; (* K *)

    (* Internal state machine *)
    eState : INT := 0; (* 0=IDLE, 1=HEATING, 2=PUMP_DOWN, 3=PRE_BLOWDOWN, 4=BLOWDOWN_ACTIVE, 5=POST_TEST, 99=FAULT *)
END_VAR

(* Implementation *)
IF bAbortCondition OR NOT bSafetyInterlocksOK THEN
    eState := 99;
END_IF;

CASE eState OF
    0: (* IDLE *)
        bFastValveCommand := FALSE;
        bMainIsolationValveCmd := FALSE;
        bVacuumIsolationValveCmd := FALSE;
        bHeaterPowerCmd := FALSE;
        bSchlierenTrigger := FALSE;
        bDataAcqTrigger := FALSE;
        bFaultActive := FALSE;
        sStatusMessage := 'System Idle';

        IF bStartSequence AND bSafetyInterlocksOK THEN
            eState := 1;
        END_IF;

    1: (* HEATING *)
        sStatusMessage := 'Heating Stagnation Gas';
        bHeaterPowerCmd := TRUE;

        IF rHeaterTemp_K >= rTargetHeaterTemp THEN
            bHeaterPowerCmd := FALSE;
            eState := 2;
        END_IF;

    2: (* PUMP_DOWN *)
        sStatusMessage := 'Evacuating Vacuum Sphere';
        bVacuumIsolationValveCmd := TRUE; (* Open to pumps *)

        IF rVacuumSpherePressure_Torr <= rTargetVacuumPressure THEN
            eState := 3;
        END_IF;

    3: (* PRE_BLOWDOWN *)
        sStatusMessage := 'Pre-Blowdown Stabilization';
        bMainIsolationValveCmd := TRUE;
        TON_ValveDelay(IN:=TRUE, PT:=T#500MS);

        IF TON_ValveDelay.Q AND bHighSpeedCameraReady AND bDataAcqSystemReady THEN
            TON_ValveDelay(IN:=FALSE);
            bDataAcqTrigger := TRUE;
            eState := 4;
        END_IF;

    4: (* BLOWDOWN_ACTIVE *)
        sStatusMessage := 'Mach 10+ BLOWDOWN';
        bFastValveCommand := TRUE; (* Open fast acting valve *)
        bSchlierenTrigger := TRUE; (* Sync high speed cameras *)

        TON_TestDuration(IN:=TRUE, PT:=T#150MS); (* 150ms test time *)

        IF TON_TestDuration.Q THEN
            bFastValveCommand := FALSE;
            bSchlierenTrigger := FALSE;
            TON_TestDuration(IN:=FALSE);
            eState := 5;
        END_IF;

    5: (* POST_TEST *)
        sStatusMessage := 'Post-Test Shutdown';
        bMainIsolationValveCmd := FALSE;
        TON_PostTestDelay(IN:=TRUE, PT:=T#2S);

        IF TON_PostTestDelay.Q THEN
            bVacuumIsolationValveCmd := FALSE;
            bDataAcqTrigger := FALSE;
            TON_PostTestDelay(IN:=FALSE);
            eState := 0;
        END_IF;

    99: (* FAULT *)
        bFastValveCommand := FALSE;
        bMainIsolationValveCmd := FALSE;
        bVacuumIsolationValveCmd := FALSE;
        bHeaterPowerCmd := FALSE;
        bSchlierenTrigger := FALSE;
        bFaultActive := TRUE;
        sStatusMessage := 'FAULT ACTIVE';

        IF NOT bAbortCondition AND bSafetyInterlocksOK THEN
            eState := 0;
        END_IF;
END_CASE;

iCurrentState := eState;
``END_FUNCTION_BLOCK
