    rZone1TempSP : REAL; (* Feed zone setpoint *)
    rZone2TempSP : REAL; (* Mixing zone setpoint *)
    rZone3TempSP : REAL; (* Cooking zone setpoint *)
    rZone4TempSP : REAL; (* High shear zone setpoint *)
    rZone5TempSP : REAL; (* Die zone setpoint *)

    (* Temperature Control Zones - PV *)
    rZone1TempPV : REAL; 
    rZone2TempPV : REAL; 
    rZone3TempPV : REAL; 
    rZone4TempPV : REAL; 
    rZone5TempPV : REAL; 

    rDiePressureBar : REAL; (* Melt pressure at the die *)
    rCutterSpeedReq : REAL; (* Required cutter speed in RPM based on product length *)
    bEmergencyStop : BOOL; (* E-Stop signal *)
END_VAR

VAR_OUTPUT
    rCalculatedSME_kWhKg : REAL; (* Specific Mechanical Energy (kWh/kg) *)

    (* Heating/Cooling Jacket Control Valves (0.0 to 100.0%) *)
    rZone1SteamValve : REAL;
    rZone1WaterValve : REAL;
    rZone2SteamValve : REAL;
    rZone2WaterValve : REAL;
    rZone3SteamValve : REAL;
    rZone3WaterValve : REAL;
    rZone4SteamValve : REAL;
    rZone4WaterValve : REAL;
    rZone5SteamValve : REAL;
    rZone5WaterValve : REAL;

    rActualCutterSpeedOut : REAL; (* Speed reference sent to Cutter Servo Drive *)
    bExtruderRunning : BOOL; (* Status flag *)
    bAlarmHighPressure : BOOL;
    bAlarmLowSME : BOOL;
END_VAR

VAR
    (* Internal PID variables for brevity, conceptualized as array *)
    aTempError : ARRAY[1..5] OF REAL;
    aTempIntegral : ARRAY[1..5] OF REAL;
    aTempPrevError : ARRAY[1..5] OF REAL;
    aPIDOutput : ARRAY[1..5] OF REAL;

    i : INT;
    rKp : REAL := 2.5; (* Proportional Gain *)
    rKi : REAL := 0.1; (* Integral Gain *)
    rKd : REAL := 0.5; (* Derivative Gain *)

    rMotorPowerKW : REAL;
    rPowerConstant : REAL := 0.0001047; (* 2*PI/60000 conversion factor *)

    rMaxDiePressure : REAL := 150.0; (* Bar *)
    rMinSMEThreshold : REAL := 15.0; (* kWh/kg *)
END_VAR

(* 
    Extruder Control Logic 
    1. Safety & Enable
*)
IF bEmergencyStop THEN
    bExtruderRunning := FALSE;
    rZone1SteamValve := 0.0; rZone1WaterValve := 100.0;
    rZone2SteamValve := 0.0; rZone2WaterValve := 100.0;
    rZone3SteamValve := 0.0; rZone3WaterValve := 100.0;
    rZone4SteamValve := 0.0; rZone4WaterValve := 100.0;
    rZone5SteamValve := 0.0; rZone5WaterValve := 100.0;
    rActualCutterSpeedOut := 0.0;
    RETURN;
END_IF;

IF bEnable THEN
    bExtruderRunning := TRUE;
ELSE
    bExtruderRunning := FALSE;
    RETURN;
END_IF;

(* 
    2. Specific Mechanical Energy (SME) Calculation
    SME = (Drive Power (kW) / Mass Flow Rate (kg/h)) 
    Power = Torque(Nm) * Speed(RPM) * (2*pi/60) / 1000 
*)
rMotorPowerKW := rMotorTorqueNm * rMotorSpeedRPM * rPowerConstant;

IF rMassFlowRateKgH > 0.0 THEN
    rCalculatedSME_kWhKg := rMotorPowerKW / rMassFlowRateKgH;
ELSE
    rCalculatedSME_kWhKg := 0.0;
END_IF;

(* SME Alarms *)
IF rCalculatedSME_kWhKg < rMinSMEThreshold AND rMassFlowRateKgH > 10.0 THEN
    bAlarmLowSME := TRUE;
ELSE
    bAlarmLowSME := FALSE;
END_IF;

(* Die Pressure Alarm *)
IF rDiePressureBar > rMaxDiePressure THEN
    bAlarmHighPressure := TRUE;
ELSE
    bAlarmHighPressure := FALSE;
END_IF;

(*
    3. Multi-Zone Barrel Temperature Control
    Using simple discrete PID for each zone to control Split-Range valves (Steam/Water)
*)
aTempError[1] := rZone1TempSP - rZone1TempPV;
aTempError[2] := rZone2TempSP - rZone2TempPV;
aTempError[3] := rZone3TempSP - rZone3TempPV;
aTempError[4] := rZone4TempSP - rZone4TempPV;
aTempError[5] := rZone5TempSP - rZone5TempPV;

FOR i := 1 TO 5 DO
    (* Anti-windup integration *)
    IF aPIDOutput[i] > -100.0 AND aPIDOutput[i] < 100.0 THEN
        aTempIntegral[i] := aTempIntegral[i] + aTempError[i];
    END_IF;

    (* PID Equation *)
    aPIDOutput[i] := (rKp * aTempError[i]) + 
                     (rKi * aTempIntegral[i]) + 
                     (rKd * (aTempError[i] - aTempPrevError[i]));

    aTempPrevError[i] := aTempError[i];

    (* Limit output to -100 (Full Cooling) to +100 (Full Heating) *)
    IF aPIDOutput[i] > 100.0 THEN aPIDOutput[i] := 100.0; END_IF;
    IF aPIDOutput[i] < -100.0 THEN aPIDOutput[i] := -100.0; END_IF;
END_FOR;

(* Split-range output mapping *)
(* Zone 1 *)
IF aPIDOutput[1] > 0.0 THEN rZone1SteamValve := aPIDOutput[1]; rZone1WaterValve := 0.0;
ELSE rZone1SteamValve := 0.0; rZone1WaterValve := ABS(aPIDOutput[1]); END_IF;

(* Zone 2 *)
IF aPIDOutput[2] > 0.0 THEN rZone2SteamValve := aPIDOutput[2]; rZone2WaterValve := 0.0;
ELSE rZone2SteamValve := 0.0; rZone2WaterValve := ABS(aPIDOutput[2]); END_IF;

(* Zone 3 *)
IF aPIDOutput[3] > 0.0 THEN rZone3SteamValve := aPIDOutput[3]; rZone3WaterValve := 0.0;
ELSE rZone3SteamValve := 0.0; rZone3WaterValve := ABS(aPIDOutput[3]); END_IF;

(* Zone 4 *)
IF aPIDOutput[4] > 0.0 THEN rZone4SteamValve := aPIDOutput[4]; rZone4WaterValve := 0.0;
ELSE rZone4SteamValve := 0.0; rZone4WaterValve := ABS(aPIDOutput[4]); END_IF;

(* Zone 5 *)
IF aPIDOutput[5] > 0.0 THEN rZone5SteamValve := aPIDOutput[5]; rZone5WaterValve := 0.0;
ELSE rZone5SteamValve := 0.0; rZone5WaterValve := ABS(aPIDOutput[5]); END_IF;

(*
    4. Die Face Cutter Synchronization
    Feedforward synchronization based on mass flow and extruder speed.
*)
IF bExtruderRunning THEN
    rActualCutterSpeedOut := rCutterSpeedReq * (rMassFlowRateKgH / 1000.0);
ELSE
    rActualCutterSpeedOut := 0.0;
END_IF;

END_FUNCTION_BLOCK
