FUNCTION_BLOCK FB_BenthicNoduleHarvester
VAR_INPUT
    (* Core operational and safety commands *)
    bSystemEnable         : BOOL;  (* Master enable for the benthic harvester sled operations *)
    bEmergencyStop        : BOOL;  (* Safety relay OK signal (NC logic, TRUE = SAFE, FALSE = FAULT) *)

    (* Critical environmental and process telemetry *)
    rDepthMeter           : REAL;  (* Current depth in meters from precision pressure transducers *)
    rAcousticPlumeDensity : REAL;  (* Acoustic backscatter density for sediment plume tracking (mg/L) *)
    rHydraulicPressure    : REAL;  (* Main lift hydraulic manifold pressure in bar *)
    rTerrainGradientX     : REAL;  (* Forward pitch gradient of the benthic terrain via IMU (degrees) *)
    rTerrainGradientY     : REAL;  (* Transverse roll gradient of the benthic terrain via IMU (degrees) *)
    rCoandaFlowRate       : REAL;  (* Flow rate of the Coanda-effect suction nozzle (L/s) *)
    rNoduleMassFlow       : REAL;  (* In-situ estimated polymetallic nodule mass flow rate (kg/s) *)
END_VAR
VAR_OUTPUT
    (* Harvester sled control outputs and status *)
    bSystemReady          : BOOL;  (* Harvester sled is armed, localized, and ready for seabed operations *)
    rPumpSpeedTarget      : REAL;  (* Coanda lift pump variable frequency drive speed command (RPM) *)
    rSledPitchCmd         : REAL;  (* Articulated track pitch correction target (degrees) *)
    rSledRollCmd          : REAL;  (* Articulated track roll correction target (degrees) *)
    bPlumeAlarm           : BOOL;  (* Plume threshold exceeded, triggering environmental mitigation sequence *)
    iHarvesterState       : INT;   (* Current finite state machine (FSM) state of the harvester algorithm *)
END_VAR
VAR
    (* Internal State Tracking and Timers *)
    iState                : INT := 0; (* Internal state machine sequencer tracker *)
    tPlumeTimer           : TON;      (* Anti-bounce timer for acoustic plume density spikes *)
    tSettleTimer          : TON;      (* Settling timer for terrain contouring articulation phase *)
    tWatchdog             : TON;      (* Watchdog for pressure collapse monitoring *)

    (* Kinematic and PID Parameters *)
    rBasePumpSpeed        : REAL := 1250.0; (* Base nominal RPM for optimal hydraulic lift *)
    rMaxPlumeDensity      : REAL := 85.0;   (* Max acceptable suspended sediment limit (mg/L) *)
    rSuctionGainKp        : REAL := 2.5;    (* Proportional gain for Coanda flow rate compensation *)
    rSuctionGainKi        : REAL := 0.15;   (* Integral gain for Coanda flow rate compensation *)
    rPitchKp              : REAL := 0.85;   (* Proportional gain for terrain pitch active tracking *)
    rRollKp               : REAL := 0.78;   (* Proportional gain for terrain roll active tracking *)

    (* Internal Process Variables *)
    rFlowError            : REAL := 0.0;    (* Deviation from optimal Coanda mass flow *)
    rFlowIntegral         : REAL := 0.0;    (* Accumulated flow error for PI control loop *)
    rOptimalFlow          : REAL := 155.0;  (* Target optimal nozzle flow rate (L/s) *)
END_VAR

(* === MAIN CRITICAL SAFETY & INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady     := FALSE;
    rPumpSpeedTarget := 0.0;
    rSledPitchCmd    := 0.0;
    rSledRollCmd     := 0.0;
    bPlumeAlarm      := FALSE;
    iHarvesterState  := 99; (* 99 = EMERGENCY FAULT HALT *)
    (* Reset integrals to prevent windup upon restart *)
    rFlowIntegral    := 0.0;
    RETURN; (* Bypass all operational logic during active e-stop *)
END_IF;

(* === ENVIRONMENTAL ACOUSTIC PLUME MONITORING === *)
(* Implement an anti-bounce timer to avoid false positives on transient acoustic backscatter anomalies *)
tPlumeTimer(IN := (rAcousticPlumeDensity > rMaxPlumeDensity), PT := T#4S);
IF tPlumeTimer.Q THEN
    bPlumeAlarm := TRUE;
ELSE
    bPlumeAlarm := FALSE;
END_IF;

(* === BENTHIC HARVESTER FINITE STATE MACHINE (FSM) === *)
CASE iState OF
    0: (* STATE 0: IDLE & PRE-DIVE SYSTEM CHECKS *)
        bSystemReady := FALSE;
        rPumpSpeedTarget := 0.0;
        iHarvesterState := 0;
        (* Verify hydraulic pre-charge and command authorization before transitioning to calibration *)
        IF bSystemEnable AND (rHydraulicPressure > 100.0) THEN
            iState := 10;
        END_IF;

    10: (* STATE 10: TERRAIN ACQUISITION & SLED CALIBRATION *)
        iHarvesterState := 10;
        (* Pre-position sled articulation tracks based on initial multi-axis IMU gradient data *)
        rSledPitchCmd := rTerrainGradientX * rPitchKp;
        rSledRollCmd  := rTerrainGradientY * rRollKp;

        (* Allow 5 seconds for the high-torque hydraulic actuators to settle the harvester chassis *)
        tSettleTimer(IN := TRUE, PT := T#5S);
        IF tSettleTimer.Q THEN
            tSettleTimer(IN := FALSE); (* Reset timer *)
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* STATE 20: ACTIVE POLYMETALLIC NODULE HARVESTING (COANDA LIFT CONTROL) *)
        iHarvesterState := 20;

        (* 1. Dynamic Terrain Contouring (Continuous Multi-Axis Following) *)
        rSledPitchCmd := rTerrainGradientX * rPitchKp;
        rSledRollCmd  := rTerrainGradientY * rRollKp;

        (* 2. Plume Mitigation and Coanda Lift Optimization PI Loop *)
        IF bPlumeAlarm THEN
            (* Threshold exceeded: drastically throttle suction to mitigate catastrophic sediment plume blowout *)
            rPumpSpeedTarget := rBasePumpSpeed * 0.35;
            rFlowIntegral := 0.0; (* Reset windup *)
        ELSE
            (* Standard PI loop: maintain optimal Coanda-effect suction, dynamically compensate for flow resistance *)
            rFlowError := rOptimalFlow - rCoandaFlowRate;
            rFlowIntegral := rFlowIntegral + rFlowError;

            (* Anti-windup clamping for the integral term *)
            IF rFlowIntegral > 500.0 THEN rFlowIntegral := 500.0; END_IF;
            IF rFlowIntegral < -500.0 THEN rFlowIntegral := -500.0; END_IF;

            rPumpSpeedTarget := rBasePumpSpeed + (rFlowError * rSuctionGainKp) + (rFlowIntegral * rSuctionGainKi);
        END_IF;

        (* 3. Safety Monitoring: Prevent hydraulic cavitation or implosion loop *)
        tWatchdog(IN := (rHydraulicPressure < 120.0), PT := T#2S);
        IF tWatchdog.Q THEN
            tWatchdog(IN := FALSE);
            iState := 30; (* PAUSE / RECOVER *)
        END_IF;

        (* 4. Graceful Shutdown *)
        IF NOT bSystemEnable THEN
            rFlowIntegral := 0.0;
            iState := 0;
        END_IF;

    30: (* STATE 30: HYDRAULIC PRESSURE RECOVERY WAIT (ANTI-CAVITATION) *)
        iHarvesterState := 30;
        (* Maintain minimum idling flow to prevent nodule aggregate clogging in the vertical riser *)
        rPumpSpeedTarget := rBasePumpSpeed * 0.15; 

        IF rHydraulicPressure >= 165.0 THEN
            iState := 20; (* Resume active harvesting operations once manifold pressure normalizes *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
