FUNCTION_BLOCK FB_BenthicCrawler_ActiveLeveling
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal *)
    rPitchAngle             : REAL;     (* Benthic terrain pitch angle [deg] *)
    rRollAngle              : REAL;     (* Benthic terrain roll angle [deg] *)
    rUmbilicalTension       : REAL;     (* Tension on the 4000m umbilical [kN] *)
    rDepth                  : REAL;     (* Operating depth in meters [m] *)
    bSonarCollisionWarning  : BOOL;     (* Acoustic imaging obstacle detection *)
    rNoduleIntakeDensity    : REAL;     (* Collected nodule density [kg/m^3] *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* System ready status *)
    rTractionCmdLeft        : REAL;     (* Port track speed command [m/s] *)
    rTractionCmdRight       : REAL;     (* Starboard track speed command [m/s] *)
    rSuspensionPressureCmd  : REAL;     (* Active hydro-pneumatic suspension pressure [bar] *)
    rWinchTensionCmd        : REAL;     (* Dynamic tensioning command for winch [kN] *)
    bAlarm                  : BOOL;     (* Fault alarm output *)
    iOperationState         : INT;      (* Current operational state feedback *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tTimer                  : TON;
    rTargetTension          : REAL := 150.0; (* Nominal tension [kN] *)
    rMaxTension             : REAL := 300.0; (* Max allowable tension [kN] *)
    rLevelingKp             : REAL := 5.5;   (* Proportional gain for leveling *)
    rLevelingKi             : REAL := 0.2;   (* Integral gain for leveling *)
    rPitchErrorSum          : REAL := 0.0;
    rBasePressure           : REAL := 200.0; (* Base suspension pressure [bar] *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rTractionCmdLeft := 0.0;
    rTractionCmdRight := 0.0;
    rWinchTensionCmd := rTargetTension; (* Hold safe tension *)
    rSuspensionPressureCmd := rBasePressure;
    iState := 999; (* FAULT STATE *)
    iOperationState := iState;
    RETURN;
END_IF;

(* Continuous Tension Monitoring & Safety Interlock *)
IF rUmbilicalTension > rMaxTension THEN
    bAlarm := TRUE;
    rTractionCmdLeft := 0.0;
    rTractionCmdRight := 0.0;
    rWinchTensionCmd := rTargetTension * 0.8; (* Slacken slightly to relieve strain *)
    iState := 999;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rTractionCmdLeft := 0.0;
        rTractionCmdRight := 0.0;
        rWinchTensionCmd := rTargetTension;
        rSuspensionPressureCmd := rBasePressure;
        IF bEnable AND rDepth > 3000.0 THEN (* Only enable active collection at benthic depths *)
            iState := 10;
        END_IF;

    10: (* INITIALIZE ACTIVE LEVELING *)
        rSuspensionPressureCmd := rBasePressure + (rPitchAngle * rLevelingKp);
        tTimer(IN := TRUE, PT := T#10S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* DYNAMIC TRACTION & NODULE COLLECTION *)
        (* Acoustic Obstacle Avoidance Override *)
        IF bSonarCollisionWarning THEN
            rTractionCmdLeft := -0.5; (* Reverse port track *)
            rTractionCmdRight := 0.5; (* Forward starboard track to pivot immediately *)
        ELSE
            rTractionCmdLeft := 1.2;  (* Standard nodule collection speed *)
            rTractionCmdRight := 1.2;
        END_IF;

        (* Hydro-Pneumatic Leveling PI Control *)
        rPitchErrorSum := rPitchErrorSum + rPitchAngle;

        (* Clamp integral windup *)
        IF rPitchErrorSum > 100.0 THEN rPitchErrorSum := 100.0; END_IF;
        IF rPitchErrorSum < -100.0 THEN rPitchErrorSum := -100.0; END_IF;

        rSuspensionPressureCmd := rBasePressure + (rPitchAngle * rLevelingKp) + (rPitchErrorSum * rLevelingKi);

        (* 4000m Umbilical Dynamic Tensioning Algorithm *)
        (* Adjust winch command based on crawler movement to prevent snap loading *)
        IF rTractionCmdLeft > 0.0 OR rTractionCmdRight > 0.0 THEN
            rWinchTensionCmd := rTargetTension + 25.0; (* Pay out umbilical preemptively *)
        ELSE
            rWinchTensionCmd := rTargetTension;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        IF bEnable = FALSE AND bEmergencyStop = TRUE AND rUmbilicalTension < rTargetTension THEN
            iState := 0; (* Reset sequence when safely back below target tension and user toggles enable *)
        END_IF;

END_CASE;

iOperationState := iState;

END_FUNCTION_BLOCK
