FUNCTION_BLOCK FB_HighShearGranulator_Ctrl
TITLE = 'Pharmaceutical High Shear Granulator Control'
VERSION : '1.0'

VAR_INPUT
    bStartProcess : BOOL;           // Start Process signal
    bStopProcess : BOOL;            // Stop Process signal
    bEStop : BOOL;                  // Emergency Stop

    // Analog Inputs
    rImpellerTorque_Nm : REAL;      // Actual Impeller Torque in Nm
    rChopperTorque_Nm : REAL;       // Actual Chopper Torque in Nm
    rProductTemp_C : REAL;          // Product Temperature in Celsius
    rBinderFlowRate_Lpm : REAL;     // Binder flow rate in L/min
    rAtomizingAirPress_Bar : REAL;  // Atomizing Air Pressure in Bar

    // Setpoints
    rTargetImpellerSpeed_RPM : REAL;
    rTargetChopperSpeed_RPM : REAL;
    rTargetBinderFlow_Lpm : REAL;
    rTargetAtomizingAir_Bar : REAL;
    rEndpointTorque_Nm : REAL;      // Torque setpoint for granulation endpoint
    tBinderAdditionTime : TIME;     // Required duration for binder addition
    tWetMassingTime : TIME;         // Required duration for wet massing phase
END_VAR

VAR_OUTPUT
    bImpellerRun : BOOL;
    rImpellerSpeedCmd_RPM : REAL;

    bChopperRun : BOOL;
    rChopperSpeedCmd_RPM : REAL;

    bBinderPumpRun : BOOL;
    rBinderPumpCmd_Pct : REAL;

    bAtomizingAirValve : BOOL;

    bEndpointReached : BOOL;        // Granulation endpoint reached
    bProcessComplete : BOOL;        // Process completed successfully

    bAlarmActive : BOOL;
    iAlarmCode : INT;
END_VAR

VAR
    iState : INT;                   // State Machine Step
    tStateTimer : TON;              // State duration timer
    tEndpointDebounce : TON;        // Debounce timer for endpoint detection
    rTorqueDiff_Nm : REAL;
END_VAR

VAR CONSTANT
    ST_IDLE : INT := 0;
    ST_PRE_MIX : INT := 10;
    ST_BINDER_ADD : INT := 20;
    ST_WET_MASSING : INT := 30;
    ST_COMPLETE : INT := 40;
    ST_FAULT : INT := 99;
END_VAR

// Control Logic
IF bEStop THEN
    iState := ST_FAULT;
    iAlarmCode := 1000; // E-Stop pressed
END_IF;

CASE iState OF
    ST_IDLE:
        bImpellerRun := FALSE;
        bChopperRun := FALSE;
        bBinderPumpRun := FALSE;
        bAtomizingAirValve := FALSE;
        bEndpointReached := FALSE;
        bProcessComplete := FALSE;
        rImpellerSpeedCmd_RPM := 0.0;
        rChopperSpeedCmd_RPM := 0.0;

        IF bStartProcess AND NOT bEStop THEN
            iState := ST_PRE_MIX;
            iAlarmCode := 0;
            bAlarmActive := FALSE;
            tStateTimer(IN := FALSE);
        END_IF;

    ST_PRE_MIX:
        bImpellerRun := TRUE;
        bChopperRun := TRUE;
        rImpellerSpeedCmd_RPM := rTargetImpellerSpeed_RPM * 0.5; // Half speed for premix
        rChopperSpeedCmd_RPM := rTargetChopperSpeed_RPM * 0.5;

        tStateTimer(IN := TRUE, PT := T#30S); // 30 seconds dry mixing
        IF tStateTimer.Q THEN
            iState := ST_BINDER_ADD;
            tStateTimer(IN := FALSE);
        END_IF;

    ST_BINDER_ADD:
        bImpellerRun := TRUE;
        bChopperRun := TRUE;
        rImpellerSpeedCmd_RPM := rTargetImpellerSpeed_RPM;
        rChopperSpeedCmd_RPM := rTargetChopperSpeed_RPM;

        bAtomizingAirValve := TRUE; // Enable air
        IF rAtomizingAirPress_Bar >= (rTargetAtomizingAir_Bar * 0.9) THEN
            bBinderPumpRun := TRUE;
            rBinderPumpCmd_Pct := (rTargetBinderFlow_Lpm - rBinderFlowRate_Lpm) * 5.0;
            IF rBinderPumpCmd_Pct > 100.0 THEN rBinderPumpCmd_Pct := 100.0; END_IF;
            IF rBinderPumpCmd_Pct < 0.0 THEN rBinderPumpCmd_Pct := 0.0; END_IF;
        ELSE
            bBinderPumpRun := FALSE;
        END_IF;

        tStateTimer(IN := TRUE, PT := tBinderAdditionTime);
        IF tStateTimer.Q THEN
            bBinderPumpRun := FALSE;
            bAtomizingAirValve := FALSE;
            iState := ST_WET_MASSING;
            tStateTimer(IN := FALSE);
        END_IF;

    ST_WET_MASSING:
        bImpellerRun := TRUE;
        bChopperRun := TRUE;
        rImpellerSpeedCmd_RPM := rTargetImpellerSpeed_RPM;
        rChopperSpeedCmd_RPM := rTargetChopperSpeed_RPM;

        tEndpointDebounce(IN := (rImpellerTorque_Nm >= rEndpointTorque_Nm), PT := T#3S);

        IF tEndpointDebounce.Q THEN
            bEndpointReached := TRUE;
            iState := ST_COMPLETE;
            tStateTimer(IN := FALSE);
        END_IF;

        tStateTimer(IN := TRUE, PT := tWetMassingTime);
        IF tStateTimer.Q THEN
            iState := ST_FAULT;
            iAlarmCode := 2000; // Timeout before reaching endpoint
        END_IF;

    ST_COMPLETE:
        bImpellerRun := FALSE;
        bChopperRun := FALSE;
        rImpellerSpeedCmd_RPM := 0.0;
        rChopperSpeedCmd_RPM := 0.0;
        bProcessComplete := TRUE;

        IF bStopProcess THEN
            iState := ST_IDLE;
        END_IF;

    ST_FAULT:
        bImpellerRun := FALSE;
        bChopperRun := FALSE;
        bBinderPumpRun := FALSE;
        bAtomizingAirValve := FALSE;
        rImpellerSpeedCmd_RPM := 0.0;
        rChopperSpeedCmd_RPM := 0.0;
        bAlarmActive := TRUE;

        IF bStopProcess AND NOT bEStop THEN
            iState := ST_IDLE;
            bAlarmActive := FALSE;
            iAlarmCode := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
