VAR_OUTPUT
    // Control Outputs
    Jacket_Temp_SP : REAL; // Jacket temperature setpoint (degC)
    Antisolvent_Flow_SP : REAL; // Antisolvent addition flowrate (L/min)
    Feed_Flow_SP : REAL; // API Feed flowrate (L/min)
    Agitator_Speed_SP : REAL; // Agitator speed (RPM)

    // Status
    Supersaturation_Act : REAL; // Calculated supersaturation
    CSD_Health_Index : REAL; // Matrix-optimized CSD health score (0-100%)
    Sequence_Step : INT; // Current antisolvent sequence step
    Error_ID : DWORD; // Error code
END_VAR

VAR
    // PID for Supersaturation
    PID_Supersat : FB_PID_Advanced;
    Supersat_Error : REAL;
    Active_Supersat_SP : REAL;

    // Antisolvent sequencing
    Step_Timer : TON;
    Total_Antisolvent_Vol : REAL;
    Antisolvent_Phase : INT := 0; 

    // CSD Matrices
    State_Matrix : ARRAY[1..3, 1..3] OF REAL; // 1=Nucleation, 2=Growth, 3=Breakage
    Control_Matrix : ARRAY[1..3, 1..2] OF REAL; // T_cooling, Antisolvent_flow effects

    // Internal calculations
    Nucleation_Rate : REAL;
    Growth_Rate : REAL;

    // Tuning Parameters
    Kp_Supersat : REAL := 2.5;
    Ti_Supersat : REAL := 120.0;
    Td_Supersat : REAL := 15.0;

    Init_Done : BOOL := FALSE;
END_VAR

BEGIN
    // Initialization of Agitator and setpoints
    IF NOT Init_Done THEN
        Agitator_Speed_SP := 150.0;
        Active_Supersat_SP := Supersaturation_SP;
        Init_Done := TRUE;
    END_IF;

    // Calculate current supersaturation dynamically
    Supersaturation_Act := Concentration_Act - Solubility_Curve_T;

    IF NOT Enable THEN
        Jacket_Temp_SP := Crystallizer_Temp_Act;
        Antisolvent_Flow_SP := 0.0;
        Feed_Flow_SP := 0.0;
        Agitator_Speed_SP := 0.0;
        Antisolvent_Phase := 0;
        CSD_Health_Index := 0.0;
        RETURN;
    END_IF;

    // ==============================================================================
    // 1. Supersaturation closed-loop control based on FBRM chord length
    // ==============================================================================
    // Adjust supersaturation setpoint dynamically based on FBRM mean chord length
    IF FBRM_Chord_Length_Mean < (CSD_Target_Mean * 0.8) THEN
        // Particles too small, promote growth over nucleation by lowering supersaturation
        Active_Supersat_SP := Active_Supersat_SP * 0.995; 
    ELSIF FBRM_Chord_Length_Mean > (CSD_Target_Mean * 1.2) THEN
        // Particles too large, promote nucleation by raising supersaturation
        Active_Supersat_SP := Active_Supersat_SP * 1.005;
    END_IF;

    Supersat_Error := Active_Supersat_SP - Supersaturation_Act;

    // Call advanced PID to control Jacket Temp based on Supersaturation SP
    PID_Supersat(
        Enable := Enable,
        Setpoint := Active_Supersat_SP,
        ProcessValue := Supersaturation_Act,
        Kp := Kp_Supersat,
        Ti := Ti_Supersat,
        Td := Td_Supersat,
        Output => Jacket_Temp_SP
    );

    // Clamp Jacket Temperature for thermal stability
    IF Jacket_Temp_SP > 80.0 THEN Jacket_Temp_SP := 80.0; END_IF;
    IF Jacket_Temp_SP < -10.0 THEN Jacket_Temp_SP := -10.0; END_IF;

    // ==============================================================================
    // 2. Antisolvent addition sequencing
    // ==============================================================================
    CASE Antisolvent_Phase OF
        0: // Initialization & Primary Nucleation
            Antisolvent_Flow_SP := 0.5; // Low initial flow
            Step_Timer(IN := TRUE, PT := T#15M);
            IF Step_Timer.Q THEN
                Step_Timer(IN := FALSE);
                Antisolvent_Phase := 1;
            END_IF;

        1: // Growth Phase - Profiled Addition based on Chord Length
            // Antisolvent flow scales linearly with mean chord length to maintain growth
            Antisolvent_Flow_SP := 2.0 + (FBRM_Chord_Length_Mean * 0.015); 

            // Override: Pause addition if fine counts spike (indicating secondary nucleation)
            IF FBRM_Counts_Fine > 15000 THEN
                Antisolvent_Flow_SP := 0.0;
            END_IF;

            Step_Timer(IN := TRUE, PT := T#60M);
            IF Step_Timer.Q THEN
                Step_Timer(IN := FALSE);
                Antisolvent_Phase := 2;
            END_IF;

        2: // Maturation / De-supersaturation
            Antisolvent_Flow_SP := 0.2;
            IF Supersaturation_Act < 0.1 THEN
                Antisolvent_Phase := 3;
            END_IF;

        3: // Discharge / Continuous Steady-State Operation
            Antisolvent_Flow_SP := 1.5;
            Feed_Flow_SP := 5.0; // Steady continuous API feed
    END_CASE;

    Sequence_Step := Antisolvent_Phase;

    // ==============================================================================
    // 3. Crystal size distribution (CSD) optimization matrices
    // ==============================================================================
    // Matrix calculations to estimate continuous state of Crystallizer CSD parameters
    Nucleation_Rate := DINT_TO_REAL(FBRM_Counts_Fine) * 0.005;
    Growth_Rate := ABS(FBRM_Chord_Length_Mean - CSD_Target_Mean) * 0.1;

    // State Matrix Updating
    State_Matrix[1,1] := Nucleation_Rate;
    State_Matrix[2,2] := Growth_Rate;
    State_Matrix[3,3] := DINT_TO_REAL(FBRM_Counts_Coarse) * 0.02 * (Agitator_Speed_SP / 100.0); // Breakage rate

    // Control Matrix Optimization (Agitator Speed Adjustment)
    // Reduce shear force if breakage state dominates
    IF State_Matrix[3,3] > 50.0 THEN
        Agitator_Speed_SP := Agitator_Speed_SP * 0.95; 
    // Increase mixing if poor suspension but below breakage threshold
    ELSIF State_Matrix[3,3] < 10.0 AND Agitator_Speed_SP < 250.0 THEN
        Agitator_Speed_SP := Agitator_Speed_SP + 2.5; 
    END_IF;

    // Real-time CSD Health Index calculation (0 to 100%)
    IF CSD_Target_Mean > 0.0 THEN
        CSD_Health_Index := 100.0 - (ABS(FBRM_Chord_Length_Mean - CSD_Target_Mean) / CSD_Target_Mean * 100.0);
    ELSE
        CSD_Health_Index := 0.0;
    END_IF;

    // Floor Health Index to zero
    IF CSD_Health_Index < 0.0 THEN CSD_Health_Index := 0.0; END_IF;

END_FUNCTION_BLOCK
`
