FUNCTION_BLOCK FB_IonThrusterXenonFeed
VAR_INPUT
    (* Core Enable and Safety Interlocks *)
    bSystemEnable           : BOOL;     (* Main activation command from flight computer *)
    bEmergencyCutoff        : BOOL;     (* Hardware interrupt / emergency shutoff valve status *)

    (* Primary Telemetry (High-Pressure Side) *)
    rTankPressure_psi       : REAL;     (* Main Xenon tank pressure, nominal 3000 PSI down to 100 PSI *)
    rPlenumPressure_psi     : REAL;     (* Low-pressure plenum, nominal 20-40 PSI *)

    (* Mass Flow Controller (MFC) Telemetry *)
    rMFCFlowRate_mg_s       : REAL;     (* Measured flow rate from thermal MFC in mg/sec *)
    rMFCTemperature_C       : REAL;     (* MFC body temperature in deg C for zero-drift compensation *)

    (* Setpoints *)
    rTargetFlow_mg_s        : REAL;     (* Desired mass flow rate for current throttle level *)
END_VAR

VAR_OUTPUT
    (* System State & Diagnostics *)
    bSystemReady            : BOOL;     (* True when plenum is pressurized and MFC is stabilized *)
    bFaultActive            : BOOL;     (* High if any pressure or flow bounds are violated *)
    iCurrentState           : INT;      (* Internal state machine step for telemetry *)

    (* Actuator Commands *)
    bBangBangValveCmd       : BOOL;     (* High-pressure isolation & regulation bang-bang valve *)
    rProportionalValveCmd   : REAL;     (* Proportional command (0.0 to 100.0%) for MFC valve *)
END_VAR

VAR
    (* Internal State and Timers *)
    iState                  : INT := 0;
    tStabilizationTimer     : TON;
    tFaultTimer             : TON;
    tBangBangCycleTimer     : TON;

    (* Control Loop Variables (MFC PID) *)
    rError                  : REAL;
    rIntegral               : REAL := 0.0;
    rDerivative             : REAL;
    rLastError              : REAL := 0.0;
    rKp                     : REAL := 2.5;
    rKi                     : REAL := 0.15;
    rKd                     : REAL := 0.05;

    (* Thermal Drift Compensation *)
    rCompensatedFlow_mg_s   : REAL;
    rNominalTemp_C          : REAL := 25.0;
    rDriftCoefficient       : REAL := 0.0035; (* mg/s per deg C deviation *)

    (* Constants *)
    rPlenumTarget_psi       : REAL := 30.0;
    rPlenumHysteresis       : REAL := 2.0;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety & Interlock Check *)
IF bEmergencyCutoff THEN
    bSystemReady            := FALSE;
    bFaultActive            := TRUE;
    bBangBangValveCmd       := FALSE;
    rProportionalValveCmd   := 0.0;
    iState                  := 99; (* FAULT STATE *)
    iCurrentState           := iState;
    RETURN;
END_IF;

(* 2. Thermal Drift Compensation for MFC *)
(* The thermal MFC reading drifts slightly with ambient spacecraft temperature changes.
   We compensate by applying a linear correction factor. *)
rCompensatedFlow_mg_s := rMFCFlowRate_mg_s - ((rMFCTemperature_C - rNominalTemp_C) * rDriftCoefficient);

(* 3. Core State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bBangBangValveCmd := FALSE;
        rProportionalValveCmd := 0.0;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* PRESSURIZE PLENUM (Bang-Bang Regulation) *)
        (* Bring the low pressure plenum up to operating pressure before starting flow *)
        IF rPlenumPressure_psi < (rPlenumTarget_psi - rPlenumHysteresis) THEN
            bBangBangValveCmd := TRUE;
        ELSIF rPlenumPressure_psi > rPlenumTarget_psi THEN
            bBangBangValveCmd := FALSE;
            iState := 20; (* Moving to Thermal Stabilization *)
        END_IF;

        (* Fallback safety: Don't overpressurize *)
        IF rPlenumPressure_psi > (rPlenumTarget_psi + 10.0) THEN
            iState := 99;
        END_IF;

    20: (* THERMAL STABILIZATION *)
        (* Wait for gas temperature and pressure in the plenum to stabilize *)
        tStabilizationTimer(IN := TRUE, PT := T#3S);
        IF tStabilizationTimer.Q THEN
            tStabilizationTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* ACTIVE FLOW REGULATION (PID) *)
        bSystemReady := TRUE;

        (* Maintain Plenum Pressure concurrently via Bang-Bang *)
        IF rPlenumPressure_psi < (rPlenumTarget_psi - rPlenumHysteresis) THEN
            bBangBangValveCmd := TRUE;
        ELSIF rPlenumPressure_psi >= rPlenumTarget_psi THEN
            bBangBangValveCmd := FALSE;
        END_IF;

        (* Calculate PID for Proportional Micro-flow Valve *)
        rError := rTargetFlow_mg_s - rCompensatedFlow_mg_s;
        rIntegral := rIntegral + (rError * 0.1); (* Assuming 100ms cycle time *)

        (* Anti-windup clamping for integral term *)
        IF rIntegral > 100.0 THEN rIntegral := 100.0; END_IF;
        IF rIntegral < -100.0 THEN rIntegral := -100.0; END_IF;

        rDerivative := (rError - rLastError) / 0.1;
        rLastError := rError;

        rProportionalValveCmd := (rKp * rError) + (rKi * rIntegral) + (rKd * rDerivative);

        (* Clamp output to 0-100% range *)
        IF rProportionalValveCmd > 100.0 THEN
            rProportionalValveCmd := 100.0;
        ELSIF rProportionalValveCmd < 0.0 THEN
            rProportionalValveCmd := 0.0;
        END_IF;

        (* Flow Fault Detection *)
        tFaultTimer(IN := (ABS(rError) > 2.5), PT := T#5S);
        IF tFaultTimer.Q THEN
            iState := 99;
        END_IF;

        (* Graceful Shutdown *)
        IF NOT bSystemEnable THEN
            iState := 40;
        END_IF;

    40: (* SHUTDOWN SEQUENCE *)
        bSystemReady := FALSE;
        bBangBangValveCmd := FALSE;
        rProportionalValveCmd := 0.0;

        (* Let plenum pressure bleed down naturally if needed, then return to IDLE *)
        IF rCompensatedFlow_mg_s < 0.1 THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bFaultActive := TRUE;
        bBangBangValveCmd := FALSE;
        rProportionalValveCmd := 0.0;

        (* Latch fault until enable is cycled *)
        IF NOT bSystemEnable THEN
            bFaultActive := FALSE;
            iState := 0;
        END_IF;

END_CASE;

iCurrentState := iState;

END_FUNCTION_BLOCK
```

