FUNCTION_BLOCK FB_MarineEngineRoomController
VAR_INPUT
    Enable : BOOL;
    EngineSpeed_RPM : REAL;
    FuelPressure_Bar : REAL;
    ScrubberInletSOx_PPM : REAL;
    SeaWaterTemp_C : REAL;
    ShaftGenPowerTarget_kW : REAL;
    MainBusVoltage_V : REAL;
END_VAR
VAR_OUTPUT
    FuelInjectorPulseWidth_ms : REAL;
    ScrubberDosingPumpSpeed_Pct : REAL;
    ShaftGenExcitation_Pct : REAL;
    Alarm_FuelLowPressure : BOOL;
    Alarm_ScrubberHighSOx : BOOL;
    Alarm_ShaftGenOverload : BOOL;
END_VAR
VAR
    FuelMap_IndexX : INT;
    FuelMap_IndexY : INT;
    BaseInjection_ms : REAL;
    TempComp_Factor : REAL;

    // Scrubber PID
    Kp_Scrubber : REAL := 0.5;
    Ki_Scrubber : REAL := 0.05;
    Kd_Scrubber : REAL := 0.1;
    ScrubberError : REAL;
    ScrubberIntegral : REAL;
    ScrubberDerivative : REAL;
    ScrubberLastError : REAL;

    // Shaft Generator Control
    PowerError : REAL;
    ExcitationTarget : REAL;
END_VAR

// Electronic Fuel Injection Mapping
IF EngineSpeed_RPM > 10.0 THEN
    // Simulated 2D Lookup Table for Fuel Base Pulse
    BaseInjection_ms := (EngineSpeed_RPM * 0.015) + (FuelPressure_Bar * 0.02);

    // Temperature compensation
    IF SeaWaterTemp_C > 30.0 THEN
        TempComp_Factor := 0.95;
    ELSIF SeaWaterTemp_C < 10.0 THEN
        TempComp_Factor := 1.05;
    ELSE
        TempComp_Factor := 1.0;
    END_IF;

    FuelInjectorPulseWidth_ms := BaseInjection_ms * TempComp_Factor;

    IF FuelPressure_Bar < 250.0 THEN
        Alarm_FuelLowPressure := TRUE;
    ELSE
        Alarm_FuelLowPressure := FALSE;
    END_IF;
ELSE
    FuelInjectorPulseWidth_ms := 0.0;
    Alarm_FuelLowPressure := FALSE;
END_IF;

// Exhaust Gas Scrubber pH Dosing (SOx control)
ScrubberError := ScrubberInletSOx_PPM - 10.0; // Target is < 10 PPM
IF ScrubberError > 0.0 THEN
    ScrubberIntegral := ScrubberIntegral + ScrubberError * 0.1; // dt=0.1s
    IF ScrubberIntegral > 50.0 THEN ScrubberIntegral := 50.0; END_IF; // Anti-windup

    ScrubberDerivative := (ScrubberError - ScrubberLastError) / 0.1;
    ScrubberDosingPumpSpeed_Pct := (Kp_Scrubber * ScrubberError) + (Ki_Scrubber * ScrubberIntegral) + (Kd_Scrubber * ScrubberDerivative);

    IF ScrubberDosingPumpSpeed_Pct > 100.0 THEN ScrubberDosingPumpSpeed_Pct := 100.0; END_IF;
ELSE
    ScrubberDosingPumpSpeed_Pct := 5.0; // Minimum idling speed
    ScrubberIntegral := 0.0;
END_IF;
ScrubberLastError := ScrubberError;

IF ScrubberInletSOx_PPM > 50.0 THEN
    Alarm_ScrubberHighSOx := TRUE;
ELSE
    Alarm_ScrubberHighSOx := FALSE;
END_IF;

// Shaft Generator Power Take-Off
IF EngineSpeed_RPM > 50.0 AND MainBusVoltage_V > 400.0 THEN
    PowerError := ShaftGenPowerTarget_kW - (MainBusVoltage_V * 2.0); // Simplified current calc
    ExcitationTarget := ExcitationTarget + (PowerError * 0.01);

    IF ExcitationTarget > 100.0 THEN ExcitationTarget := 100.0; END_IF;
    IF ExcitationTarget < 0.0 THEN ExcitationTarget := 0.0; END_IF;

    ShaftGenExcitation_Pct := ExcitationTarget;

    IF ShaftGenPowerTarget_kW > 2000.0 THEN
        Alarm_ShaftGenOverload := TRUE;
    ELSE
        Alarm_ShaftGenOverload := FALSE;
    END_IF;
ELSE
    ShaftGenExcitation_Pct := 0.0;
    Alarm_ShaftGenOverload := FALSE;
END_IF;
END_FUNCTION_BLOCK
