FUNCTION_BLOCK FB_ColdStorageCoordinator
TITLE = 'Autonomous High-Bay Cold Storage Coordinator'
VERSION : '1.0'

(*
   Coordinates NH3 refrigeration cascade system, AGV traffic interlocks,
   and evaporator frost prevention in a high-bay sub-zero storage facility.
*)

VAR_INPUT
    bSystemEnable : BOOL; // Main system enable
    rTempZone1 : REAL; // Current temperature in Zone 1 (deg C)
    rTempZone2 : REAL; // Current temperature in Zone 2 (deg C)
    rNH3PressStage1 : REAL; // Ammonia pressure stage 1 (bar)
    rNH3PressStage2 : REAL; // Ammonia pressure stage 2 (bar)
    bAGV_Zone1_Occupied : BOOL; // AGV presence detected in Zone 1
    bAGV_Zone2_Occupied : BOOL; // AGV presence detected in Zone 2
    bEvapFrostSensor1 : BOOL; // Frost buildup detected on Evap 1
    bEvapFrostSensor2 : BOOL; // Frost buildup detected on Evap 2
    rTempSetpoint : REAL := -25.0; // Target temperature
END_VAR

VAR_OUTPUT
    bCompStage1_Run : BOOL; // Command for Compressor Stage 1
    bCompStage2_Run : BOOL; // Command for Compressor Stage 2
    bEvapFan1_Run : BOOL; // Command for Evaporator 1 Fan
    bEvapFan2_Run : BOOL; // Command for Evaporator 2 Fan
    bDefrostHeater1 : BOOL; // Command for Defrost Heater 1
    bDefrostHeater2 : BOOL; // Command for Defrost Heater 2
    bAGV_Gate1_Open : BOOL; // Allow AGV into Zone 1
    bAGV_Gate2_Open : BOOL; // Allow AGV into Zone 2
    bSystemAlarm : BOOL; // General fault alarm
    sAlarmMessage : STRING[50];
END_VAR

VAR
    TMR_Defrost1 : TON;
    TMR_Defrost2 : TON;
    TMR_CompressorDelay : TON;
    bDefrostActive1 : BOOL;
    bDefrostActive2 : BOOL;
    rTempHysteresis : REAL := 2.0;
    rNH3PressMax : REAL := 15.0; // Max allowed pressure
    rNH3PressMin : REAL := 1.5;  // Min allowed pressure
    iState : INT := 0; 
END_VAR

(* Implementation *)

// 1. Safety and Limits
IF NOT bSystemEnable OR (rNH3PressStage1 > rNH3PressMax) OR (rNH3PressStage2 > rNH3PressMax) THEN
    bCompStage1_Run := FALSE;
    bCompStage2_Run := FALSE;
    bEvapFan1_Run := FALSE;
    bEvapFan2_Run := FALSE;
    bDefrostHeater1 := FALSE;
    bDefrostHeater2 := FALSE;
    bAGV_Gate1_Open := FALSE;
    bAGV_Gate2_Open := FALSE;
    bSystemAlarm := TRUE;
    sAlarmMessage := 'SYSTEM DISABLED OR OVERPRESSURE';
    RETURN;
END_IF;

bSystemAlarm := FALSE;
sAlarmMessage := 'OK';

// 2. Defrost Logic (Evaporator Frost Prevention)
// Defrost overrides normal fan operation
TMR_Defrost1(IN := bEvapFrostSensor1, PT := T#5M);
IF TMR_Defrost1.Q AND NOT bAGV_Zone1_Occupied THEN
    bDefrostActive1 := TRUE;
ELSIF NOT bEvapFrostSensor1 THEN
    bDefrostActive1 := FALSE;
END_IF;

TMR_Defrost2(IN := bEvapFrostSensor2, PT := T#5M);
IF TMR_Defrost2.Q AND NOT bAGV_Zone2_Occupied THEN
    bDefrostActive2 := TRUE;
ELSIF NOT bEvapFrostSensor2 THEN
    bDefrostActive2 := FALSE;
END_IF;

bDefrostHeater1 := bDefrostActive1;
bDefrostHeater2 := bDefrostActive2;

// 3. Refrigeration Cascade (NH3)
// Stage 1 kicks in if temp is above setpoint + hysteresis
IF (rTempZone1 > rTempSetpoint + rTempHysteresis) OR (rTempZone2 > rTempSetpoint + rTempHysteresis) THEN
    bCompStage1_Run := TRUE;
ELSIF (rTempZone1 <= rTempSetpoint) AND (rTempZone2 <= rTempSetpoint) THEN
    bCompStage1_Run := FALSE;
END_IF;

// Stage 2 kicks in based on delay and Stage 1 pressure dropping
TMR_CompressorDelay(IN := bCompStage1_Run, PT := T#30S);
IF TMR_CompressorDelay.Q AND (rNH3PressStage1 < 5.0) THEN
    bCompStage2_Run := TRUE;
ELSE
    bCompStage2_Run := FALSE;
END_IF;

// 4. Evaporator Fans
// Fans run if cooling is needed and no defrost is active
bEvapFan1_Run := bCompStage1_Run AND NOT bDefrostActive1;
bEvapFan2_Run := bCompStage1_Run AND NOT bDefrostActive2;

// 5. AGV Traffic Interlocking
// AGVs are allowed into a zone only if there is no active defrost and doors are cleared
IF NOT bDefrostActive1 THEN
    bAGV_Gate1_Open := TRUE;
ELSE
    bAGV_Gate1_Open := FALSE;
END_IF;

IF NOT bDefrostActive2 THEN
    bAGV_Gate2_Open := TRUE;
ELSE
    bAGV_Gate2_Open := FALSE;
END_IF;

// Safety check for AGV during active defrost
IF (bDefrostActive1 AND bAGV_Zone1_Occupied) OR (bDefrostActive2 AND bAGV_Zone2_Occupied) THEN
    bSystemAlarm := TRUE;
    sAlarmMessage := 'AGV IN ACTIVE DEFROST ZONE';
END_IF;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_SUT_AeroTurbine_MasterControl
(* 
   ================================================================================
   Lumiana AI Cloud Swarm - Elite Synthetic Data Architect
   Domain: Next-Gen Utility-Scale Solar Updraft Tower (SUT) Aero-Turbine
   Description: Advanced 1000m chimney thermodynamic draft mapping, multi-megawatt 
                axial turbine variable pitch, and greenhouse canopy diurnal thermal 
                storage management system.
   ================================================================================
*)
VAR_INPUT
    bSystemEnable            : BOOL;     (* Main system enable interlock *)
    bEmergencyStop           : BOOL;     (* Safety relay OK signal - Active High = Safe *)
    rAmbientTemp             : REAL;     (* Ambient temperature (deg C) *)
    rCanopyTemp              : REAL;     (* Greenhouse canopy avg temp (deg C) *)
    rChimneyDraftVel         : REAL;     (* Measured draft velocity in chimney (m/s) *)
    rGridDemandMW            : REAL;     (* Power demand from the grid dispatcher (MW) *)
    rTurbineSpeedRPM         : REAL;     (* Actual turbine rotor speed (RPM) *)
    rVibrationLevel          : REAL;     (* Turbine bearing vibration (mm/s RMS) *)
END_VAR

VAR_OUTPUT
    bSystemReady             : BOOL;     (* System is primed and ready to generate power *)
    rTurbinePitchAngle       : REAL;     (* Blade pitch angle command to actuator (Degrees) *)
    rGeneratorTorqueSP       : REAL;     (* Generator torque setpoint to inverter (Nm) *)
    rActivePowerMW           : REAL;     (* Calculated active power output (MW) *)
    bAlarmVibration          : BOOL;     (* High vibration critical alarm *)
    bThermalOverload         : BOOL;     (* Canopy / draft temperature safety limit exceeded *)
    iOperatingState          : INT;      (* Current state machine step *)
END_VAR

VAR
    iState                   : INT := 0; 
    tDraftStabilizer         : TON;
    tVibrationDebounce       : TON;
    rCalculatedDeltaT        : REAL;
    rTargetDraftVel          : REAL;
    rPitchControllerKp       : REAL := 2.5;
    rPitchControllerKi       : REAL := 0.15;
    rPitchIntegralError      : REAL := 0.0;
    rSpeedError              : REAL;

    (* Constants for 1000m Thermodynamic Draft *)
    c_rMaxCanopyTemp         : REAL := 85.0;  (* Max allowable canopy temp deg C *)
    c_rMaxVibration          : REAL := 12.5;  (* Max vibration trip mm/s *)
    c_rNominalRPM            : REAL := 1500.0;
    c_rMinDraftVel           : REAL := 8.5;   (* Min draft for sync m/s *)
END_VAR

(* === MAIN SAFETY & INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady       := FALSE;
    rTurbinePitchAngle := 90.0; (* Feather blades completely *)
    rGeneratorTorqueSP := 0.0;
    iOperatingState    := 999;  (* Fault state *)
    RETURN;
END_IF;

(* Vibration Monitoring with Debounce *)
tVibrationDebounce(IN := (rVibrationLevel > c_rMaxVibration), PT := T#2S);
IF tVibrationDebounce.Q THEN
    bAlarmVibration    := TRUE;
    iState             := 999; (* Force fault trip *)
END_IF;

(* Thermal Overload Check *)
IF rCanopyTemp > c_rMaxCanopyTemp THEN
    bThermalOverload := TRUE;
    (* We don't trip immediately, but we might throttle pitch to reduce flow and thus draft heat transfer if needed, or open vents *)
ELSE
    bThermalOverload := FALSE;
END_IF;

(* Thermodynamic calculations *)
rCalculatedDeltaT := rCanopyTemp - rAmbientTemp;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE / STANDBY *)
        bSystemReady       := TRUE;
        rTurbinePitchAngle := 90.0;
        rGeneratorTorqueSP := 0.0;
        iOperatingState    := 0;

        IF bSystemEnable AND NOT bAlarmVibration THEN
            iState := 10;
        END_IF;

    10: (* PRIMING DRAFT - Waiting for aerodynamic stability *)
        iOperatingState := 10;
        (* Pitch blades to allow free-wheeling draft build-up *)
        rTurbinePitchAngle := 45.0; 

        tDraftStabilizer(IN := (rChimneyDraftVel >= c_rMinDraftVel), PT := T#30S);
        IF tDraftStabilizer.Q THEN
            tDraftStabilizer(IN := FALSE);
            iState := 20;
        END_IF;

        IF NOT bSystemEnable THEN
            tDraftStabilizer(IN := FALSE);
            iState := 0;
        END_IF;

    20: (* RAMP TO SYNCHRONOUS SPEED *)
        iOperatingState := 20;

        (* Simple PI control for RPM tracking *)
        rSpeedError := c_rNominalRPM - rTurbineSpeedRPM;
        rPitchIntegralError := rPitchIntegralError + (rSpeedError * 0.1); (* Assuming 100ms cycle *)

        (* Anti-windup *)
        IF rPitchIntegralError > 50.0 THEN rPitchIntegralError := 50.0; END_IF;
        IF rPitchIntegralError < -50.0 THEN rPitchIntegralError := -50.0; END_IF;

        (* Calculate pitch angle - less pitch = more torque from wind *)
        rTurbinePitchAngle := 45.0 - (rPitchControllerKp * rSpeedError + rPitchControllerKi * rPitchIntegralError);

        (* Bound pitch angle *)
        IF rTurbinePitchAngle < 0.0 THEN rTurbinePitchAngle := 0.0; END_IF;
        IF rTurbinePitchAngle > 90.0 THEN rTurbinePitchAngle := 90.0; END_IF;

        (* Check if synchronous speed reached *)
        IF ABS(rSpeedError) < 10.0 THEN
            iState := 30;
        END_IF;

    30: (* MPPT / ACTIVE POWER GENERATION *)
        iOperatingState := 30;

        (* Map grid demand to torque setpoint given current RPM and draft limit *)
        (* P(MW) = T(kNm) * w(rad/s) -> T = P / w *)
        IF rTurbineSpeedRPM > 0.0 THEN
            rGeneratorTorqueSP := (rGridDemandMW * 1000.0) / (rTurbineSpeedRPM * 0.104719755); 
        ELSE
            rGeneratorTorqueSP := 0.0;
        END_IF;

        (* Maintain optimum aerodynamic efficiency via pitch control *)
        (* Here pitch targets a specific tip-speed ratio, simplified for this block *)
        rTurbinePitchAngle := 15.0 + (rCalculatedDeltaT * 0.05); 

        rActivePowerMW := rGeneratorTorqueSP * (rTurbineSpeedRPM * 0.104719755) / 1000.0;

        IF NOT bSystemEnable THEN
            iState := 40; (* Go to normal stop *)
        END_IF;

    40: (* NORMAL STOP *)
        iOperatingState := 40;
        rGeneratorTorqueSP := 0.0;
        rTurbinePitchAngle := 90.0; (* Feather blades *)
        rActivePowerMW := 0.0;

        IF rTurbineSpeedRPM < 50.0 THEN
            iState := 0;
        END_IF;

    999: (* FAULT TRIPPED *)
        iOperatingState := 999;
        bSystemReady := FALSE;
        rTurbinePitchAngle := 90.0;
        rGeneratorTorqueSP := 0.0;

        IF bSystemEnable = FALSE AND bEmergencyStop = TRUE AND bAlarmVibration = FALSE THEN
            iState := 0; (* Reset fault if enable toggled and E-Stop OK *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

