FUNCTION_BLOCK FB_WindTunnelStorageHeater
VAR_INPUT
    (* Core Safety and Enable Signals *)
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay loop OK signal (Active HIGH) *)

    (* Process Variables - Temperatures (°C) *)
    rZone1Temp              : REAL;     (* Zirconia brick bed lower zone temperature *)
    rZone2Temp              : REAL;     (* Zirconia brick bed middle zone temperature *)
    rZone3Temp              : REAL;     (* Zirconia brick bed upper zone temperature *)

    (* Process Variables - Pressure and Flow *)
    rVesselPressure         : REAL;     (* Storage heater vessel internal pressure (Bar) *)
    rAirMassFlowAct         : REAL;     (* Actual air mass flow rate (kg/s) *)
    rAirMassFlowCmd         : REAL;     (* Commanded air mass flow rate (kg/s) *)

    (* Maintenance & Fatigue Tracking *)
    diVesselCycles          : DINT;     (* Accumulated thermal/pressure cycles *)
END_VAR
VAR_OUTPUT
    (* Status and Handshake *)
    bSystemReady            : BOOL;     (* System is at temperature and ready for blowdown *)
    bBlowdownActive         : BOOL;     (* Blowdown sequence is currently executing *)
    bAlarm                  : BOOL;     (* Critical fault alarm output *)
    bThermalFatigueWarn     : BOOL;     (* Warning: Vessel approaching cycle limit or thermal shock *)

    (* Control Signals *)
    rHeaterPowerOut         : REAL;     (* Commanded heater power to thyristor (0.0 - 100.0%) *)
    rFlowValveCmd           : REAL;     (* Commanded position for main flow regulation valve (0.0 - 100.0%) *)

    (* Diagnostics *)
    iCurrentState           : INT;      (* Current active step in the state machine *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState                  : INT := 0;
    tPurgeTimer             : TON;
    tSoakTimer              : TON;
    tCooldownTimer          : TON;

    (* Process Calculations *)
    rAverageTemp            : REAL;
    rMaxTempGrad            : REAL := 15.0; (* Max allowable temp gradient °C/min to prevent thermal shock *)
    rLastAverageTemp        : REAL;

    (* Internal Flags *)
    bPressureLimitExceeded  : BOOL;
    bTempSensorsValid       : BOOL;
END_VAR

(* === MAIN LOGIC START === *)

(* 1. Safety Interlocks & Fault Detection *)
bPressureLimitExceeded := (rVesselPressure > 150.0); (* 150 Bar Max Design Pressure *)
bTempSensorsValid := (rZone1Temp > -50.0) AND (rZone2Temp > -50.0) AND (rZone3Temp > -50.0);

IF NOT bEmergencyStop OR bPressureLimitExceeded OR NOT bTempSensorsValid THEN
    bSystemReady := FALSE;
    bBlowdownActive := FALSE;
    rHeaterPowerOut := 0.0;
    rFlowValveCmd := 0.0;
    bAlarm := TRUE;
    iState := 99; (* FAULT STATE *)
    iCurrentState := iState;
    RETURN;
END_IF;

(* 2. Vessel Fatigue & Life Cycle Monitoring *)
IF diVesselCycles > 10000 THEN
    bThermalFatigueWarn := TRUE;
ELSE
    bThermalFatigueWarn := FALSE;
END_IF;

(* 3. Process Calculations *)
rAverageTemp := (rZone1Temp + rZone2Temp + rZone3Temp) / 3.0;

(* 4. Main State Machine *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rHeaterPowerOut := 0.0;
        rFlowValveCmd := 0.0;

        IF bEnable THEN
            iState := 10; (* Transition to PURGE *)
        END_IF;

    10: (* PURGE - Clear combustible gases or moisture *)
        rFlowValveCmd := 5.0; (* 5% open for low-flow purge *)
        tPurgeTimer(IN := TRUE, PT := T#5M);

        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            rFlowValveCmd := 0.0;
            iState := 20; (* Transition to PREHEAT *)
        END_IF;

    20: (* PREHEAT & RAMP UP *)
        (* Slowly ramp up power to avoid zirconia brick thermal shock *)
        IF rAverageTemp < 1000.0 THEN
            rHeaterPowerOut := 25.0; (* 25% Power *)
        ELSIF rAverageTemp < 1800.0 THEN
            rHeaterPowerOut := 50.0; (* 50% Power *)
        ELSE
            rHeaterPowerOut := 10.0; (* Hold power *)
            iState := 30; (* Transition to SOAK *)
        END_IF;

    30: (* SOAK - Ensure thermal uniformity across all zones *)
        tSoakTimer(IN := TRUE, PT := T#2H);

        (* Modulate power to maintain 1850°C setpoint *)
        IF rAverageTemp < 1845.0 THEN
            rHeaterPowerOut := 15.0;
        ELSIF rAverageTemp > 1855.0 THEN
            rHeaterPowerOut := 0.0;
        END_IF;

        IF tSoakTimer.Q THEN
            tSoakTimer(IN := FALSE);
            bSystemReady := TRUE;
            iState := 40; (* BLOWDOWN READY *)
        END_IF;

    40: (* BLOWDOWN READY - Waiting for flow command *)
        IF rAirMassFlowCmd > 0.0 THEN
            bSystemReady := FALSE;
            bBlowdownActive := TRUE;
            iState := 50; (* BLOWDOWN ACTIVE *)
        END_IF;

        IF NOT bEnable THEN
            iState := 70; (* COOLDOWN *)
        END_IF;

    50: (* BLOWDOWN ACTIVE - High mass flow regulation *)
        (* Closed-loop feed-forward flow control *)
        rFlowValveCmd := (rAirMassFlowCmd / 150.0) * 100.0; (* Base estimation assuming 150kg/s max *)

        (* Fine trim based on actual flow feedback *)
        IF rAirMassFlowAct < rAirMassFlowCmd THEN
            rFlowValveCmd := rFlowValveCmd + 0.5;
        ELSIF rAirMassFlowAct > rAirMassFlowCmd THEN
            rFlowValveCmd := rFlowValveCmd - 0.5;
        END_IF;

        (* End of blowdown or pressure drop *)
        IF rAirMassFlowCmd <= 0.0 OR rVesselPressure < 10.0 THEN
            bBlowdownActive := FALSE;
            rFlowValveCmd := 0.0;
            iState := 70; (* Transition to COOLDOWN *)
        END_IF;

    70: (* COOLDOWN - Controlled thermal descent *)
        rHeaterPowerOut := 0.0;
        rFlowValveCmd := 2.0; (* Slight bleed for cooling *)
        tCooldownTimer(IN := TRUE, PT := T#4H);

        IF tCooldownTimer.Q OR (rAverageTemp < 50.0) THEN
            tCooldownTimer(IN := FALSE);
            rFlowValveCmd := 0.0;
            IF NOT bEnable THEN
                iState := 0; (* Return to IDLE *)
            END_IF;
        END_IF;

    99: (* FAULT HANDLING *)
        (* Requires E-Stop toggle and safe conditions to reset *)
        IF bEmergencyStop AND NOT bPressureLimitExceeded AND bTempSensorsValid AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* Update diagnostic output *)
iCurrentState := iState;

END_FUNCTION_BLOCK
