        // Zone 2 On/Off Control
        IF #Zone2_TempActual < (#Zone2_TempTarget - 2.0) THEN
            #Zone2_Heater := TRUE;
        ELSIF #Zone2_TempActual > (#Zone2_TempTarget + 2.0) THEN
            #Zone2_Heater := FALSE;
        END_IF;

        // Zone 3 On/Off Control
        IF #Zone3_TempActual < (#Zone3_TempTarget - 2.0) THEN
            #Zone3_Heater := TRUE;
        ELSIF #Zone3_TempActual > (#Zone3_TempTarget + 2.0) THEN
