        // Standby State - Ensure all outputs are safe
        #ConveyorRun := FALSE;
        #ConveyorSpeedOut := 0.0;
        #Zone1_Heater := FALSE;
        #Zone2_Heater := FALSE;
        #Zone3_Heater := FALSE;
    END_IF;
END_FUNCTION_BLOCK
