FUNCTION_BLOCK FB_TerminalOperationsMaster
// ==============================================================================
// Function Block: FB_TerminalOperationsMaster
// Description: Advanced Automated Container Terminal Operations controller.
// Handles AGV traffic routing, Automated Stacking Crane (ASC) optimization, 
// and Quay Crane (QC) anti-collision systems.
// ==============================================================================

VAR_INPUT
    bSystemEnable : BOOL; // Master enable for terminal operations
    nActiveAGVs : INT; // Number of currently active AGVs
    aAGV_Positions : ARRAY[1..50] OF REAL; // X-positions of AGVs (m)
    aAGV_Velocities : ARRAY[1..50] OF REAL; // Velocities of AGVs (m/s)
    aAGV_Destinations : ARRAY[1..50] OF REAL; // Target positions (m)

    nASC_PositionX : REAL; // Gantry X-position of ASC (m)
    nASC_PositionY : REAL; // Trolley Y-position of ASC (m)
    nASC_LoadWeight : REAL; // Current load weight (kg)
    bASC_LoadPresent : BOOL; // Spreader locked on container

    aQC_Positions : ARRAY[1..5] OF REAL; // Positions of Quay Cranes (m)
    aQC_BoomAngles : ARRAY[1..5] OF REAL; // Boom pitch angles (deg)
END_VAR

VAR_OUTPUT
    aAGV_SpeedCommands : ARRAY[1..50] OF REAL; // Speed setpoints for AGVs
    aAGV_StopCommands : ARRAY[1..50] OF BOOL; // Emergency stop flags for AGVs

    nASC_TargetSpeedX : REAL; // Speed setpoint for ASC Gantry
    nASC_TargetSpeedY : REAL; // Speed setpoint for ASC Trolley

    aQC_CollisionAlarms : ARRAY[1..5] OF BOOL; // Collision imminent alarms
    bTerminalEStop : BOOL; // Global E-Stop active
END_VAR

VAR
    i, j : INT;
    rDistance : REAL;
    rMinDistanceAGV : REAL := 5.0; // Minimum safe distance between AGVs (m)
    rCollisionZoneQC : REAL := 15.0; // Minimum clearance between QCs (m)
    rMaxSpeedAGV : REAL := 3.0; // Max AGV speed (m/s)
    rMaxSpeedASC : REAL := 4.0; // Max ASC speed (m/s)

    // Internal state tracking
    bRouteConflict : BOOL;
    rDynamicBrakingDist : REAL;
END_VAR

// ==============================================================================
// Implementation
// ==============================================================================

bTerminalEStop := FALSE;

IF NOT bSystemEnable THEN
    FOR i := 1 TO 50 DO
        aAGV_SpeedCommands[i] := 0.0;
        aAGV_StopCommands[i] := TRUE;
    END_FOR;
    nASC_TargetSpeedX := 0.0;
    nASC_TargetSpeedY := 0.0;
    RETURN;
END_IF;

// 1. AGV Multi-Agent Traffic Routing & Collision Avoidance
FOR i := 1 TO nActiveAGVs DO
    bRouteConflict := FALSE;
    aAGV_StopCommands[i] := FALSE;

    // Check distance to destination
    IF ABS(aAGV_Positions[i] - aAGV_Destinations[i]) < 0.5 THEN
        aAGV_SpeedCommands[i] := 0.0; // Reached target
    ELSE
        aAGV_SpeedCommands[i] := rMaxSpeedAGV;
    END_IF;

    // Check conflicts with other AGVs
    FOR j := 1 TO nActiveAGVs DO
        IF i <> j THEN
            rDistance := ABS(aAGV_Positions[i] - aAGV_Positions[j]);
            rDynamicBrakingDist := rMinDistanceAGV + (aAGV_Velocities[i] * 2.0); // 2s lookahead

            IF rDistance < rDynamicBrakingDist THEN
                bRouteConflict := TRUE;
                // Yield to lower index ID
                IF i > j AND (aAGV_Positions[i] < aAGV_Positions[j]) THEN
                    aAGV_SpeedCommands[i] := 0.0; // Stop and wait
                END_IF;
            END_IF;

            // Hard collision check
            IF rDistance < 1.0 THEN
                aAGV_StopCommands[i] := TRUE;
                bTerminalEStop := TRUE;
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// 2. Automated Stacking Crane (ASC) Optimization
// Simple logic: if loaded, move slower, else fast. Avoid oscillations.
IF bASC_LoadPresent THEN
    IF nASC_LoadWeight > 25000.0 THEN // Heavy container > 25t
        nASC_TargetSpeedX := rMaxSpeedASC * 0.5;
        nASC_TargetSpeedY := rMaxSpeedASC * 0.4;
    ELSE
        nASC_TargetSpeedX := rMaxSpeedASC * 0.75;
        nASC_TargetSpeedY := rMaxSpeedASC * 0.6;
    END_IF;
ELSE
    nASC_TargetSpeedX := rMaxSpeedASC;
    nASC_TargetSpeedY := rMaxSpeedASC;
END_IF;

// 3. Quay Crane (QC) Anti-Collision System
FOR i := 1 TO 4 DO
    // Check adjacent crane distances
    rDistance := ABS(aQC_Positions[i] - aQC_Positions[i+1]);

    IF rDistance < rCollisionZoneQC THEN
        aQC_CollisionAlarms[i] := TRUE;
        aQC_CollisionAlarms[i+1] := TRUE;
        bTerminalEStop := TRUE; // Halt all operations near QCs
    ELSE
        aQC_CollisionAlarms[i] := FALSE;
    END_IF;
END_FOR;
aQC_CollisionAlarms[5] := FALSE; // Reset last

// End of Function Block
END_FUNCTION_BLOCK
