```iec-st
FUNCTION_BLOCK FB_LAES_ExpansionTurbine_Control
VAR_INPUT
    bEnableSys                  : BOOL;     (* System master enable *)
    bGridSyncOK                 : BOOL;     (* Synchronous grid-tie phase matching OK *)
    rCryoAirInletTemp           : REAL;     (* Cryogenic liquid air inlet temperature [K] *)
    rCryoAirInletPressure       : REAL;     (* Expansion turbine inlet pressure [Bar] *)
    rVaporizationTargetRate     : REAL;     (* Target mass flow rate for vaporization cascade [kg/s] *)
    rTurbineSpeedAct            : REAL;     (* Active turbine shaft speed [RPM] *)
    bEmergencyTrip              : BOOL;     (* Turbine overspeed or vibration trip signal *)
    bActiveLoadSheddingReq      : BOOL;     (* Grid requested active load shedding *)
END_VAR

VAR_OUTPUT
    bTurbineReady               : BOOL;     (* Turbine is primed and ready to spin up *)
    bGridTied                   : BOOL;     (* Turbine generator is synchronous to the grid *)
    rGovernorValvePosition      : REAL;     (* Output to multi-stage expansion governor valve [0.0 - 100.0%] *)
    rBypassValvePosition        : REAL;     (* Output to high-pressure bypass valve [0.0 - 100.0%] *)
    rVaporizerHeaterPower       : REAL;     (* Command to trim heaters in the cascading vaporizer [kW] *)
    bSystemTripAlarm            : BOOL;     (* Latching emergency trip alarm *)
    iOperationState             : INT;      (* Current state machine step *)
END_VAR

VAR
    iState                      : INT := 0; (* Internal state machine *)
    rSpeedSetPoint              : REAL := 3000.0; (* Base synchronous speed [RPM] *)
    rSpeedError                 : REAL;
    rKp                         : REAL := 1.25;
    rKi                         : REAL := 0.15;
    rIntegral                   : REAL := 0.0;
    tGridSyncTimer              : TON;
    tSpinUpTimer                : TON;
    bShutdownSequence           : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety and Interlock Checks *)
IF bEmergencyTrip THEN
    iState := 999; (* Transition to trip state *)
END_IF;

CASE iState OF
    0: (* IDLE / OFF *)
        bTurbineReady := FALSE;
        bGridTied := FALSE;
        rGovernorValvePosition := 0.0;
        rBypassValvePosition := 100.0; (* Full bypass on idle to avoid pressure buildup *)
        rVaporizerHeaterPower := 0.0;
        bSystemTripAlarm := FALSE;
        bShutdownSequence := FALSE;

        IF bEnableSys AND NOT bEmergencyTrip THEN
            iState := 10; (* Transition to PRE-START / PRIMING *)
        END_IF;

    10: (* PRE-START / PRIMING *)
        (* Warm up the cascade vaporizers based on inlet temperature *)
        IF rCryoAirInletTemp < 80.0 THEN
            rVaporizerHeaterPower := 500.0; (* Max trim heat to prevent line freezing *)
        ELSE
            rVaporizerHeaterPower := (150.0 - rCryoAirInletTemp) * 2.5; 
        END_IF;

        (* Check if we have sufficient pressure to spin the turbine *)
        IF rCryoAirInletPressure > 45.0 THEN
            bTurbineReady := TRUE;
            iState := 20; (* Transition to SPIN-UP *)
        END_IF;

        IF NOT bEnableSys THEN
            iState := 0;
        END_IF;

    20: (* SPIN-UP *)
        (* Gradually close bypass and open governor to reach synchronous speed *)
        rBypassValvePosition := 50.0;

        rSpeedError := rSpeedSetPoint - rTurbineSpeedAct;
        rIntegral := rIntegral + (rSpeedError * 0.1); (* Assuming 100ms cycle *)

        (* Anti-windup *)
        IF rIntegral > 100.0 THEN rIntegral := 100.0; END_IF;
        IF rIntegral < -100.0 THEN rIntegral := -100.0; END_IF;

        rGovernorValvePosition := (rKp * rSpeedError) + (rKi * rIntegral);

        (* Saturate valve output *)
        IF rGovernorValvePosition > 100.0 THEN rGovernorValvePosition := 100.0; END_IF;
        IF rGovernorValvePosition < 0.0 THEN rGovernorValvePosition := 0.0; END_IF;

        (* Check for nominal speed reached within 5% band *)
        IF ABS(rSpeedError) < (rSpeedSetPoint * 0.05) THEN
            tSpinUpTimer(IN := TRUE, PT := T#10S);
            IF tSpinUpTimer.Q THEN
                tSpinUpTimer(IN := FALSE);
                iState := 30; (* Wait for grid sync *)
            END_IF;
        ELSE
            tSpinUpTimer(IN := FALSE);
        END_IF;

        IF NOT bEnableSys THEN
            bShutdownSequence := TRUE;
            iState := 100;
        END_IF;

    30: (* GRID SYNCHRONIZATION *)
        (* Hold speed steady and wait for phase matcher to approve *)
        rGovernorValvePosition := rGovernorValvePosition; (* Hold last PI output *)

        IF bGridSyncOK THEN
            tGridSyncTimer(IN := TRUE, PT := T#3S);
            IF tGridSyncTimer.Q THEN
                tGridSyncTimer(IN := FALSE);
                bGridTied := TRUE;
                iState := 40; (* ACTIVE GENERATION *)
            END_IF;
        ELSE
            tGridSyncTimer(IN := FALSE);
        END_IF;

        IF NOT bEnableSys THEN
            bShutdownSequence := TRUE;
            iState := 100;
        END_IF;

    40: (* ACTIVE GENERATION *)
        (* Control load based on vaporization target and grid shedding requests *)
        IF bActiveLoadSheddingReq THEN
            (* Rapidly reduce power output by bypassing high-pressure air *)
            rBypassValvePosition := 80.0;
            rGovernorValvePosition := rGovernorValvePosition * 0.2;
        ELSE
            (* Modulate governor based on target vaporization rate vs available pressure *)
            rBypassValvePosition := 0.0; (* No bypass during optimal generation *)
            rGovernorValvePosition := (rVaporizationTargetRate / 100.0) * 100.0; 
            IF rGovernorValvePosition > 100.0 THEN
                rGovernorValvePosition := 100.0;
            END_IF;
        END_IF;

        IF NOT bEnableSys THEN
            bShutdownSequence := TRUE;
            iState := 100;
        END_IF;

    100: (* SHUTDOWN SEQUENCE *)
        bGridTied := FALSE;
        rGovernorValvePosition := rGovernorValvePosition * 0.9; (* Ramp down *)
        rBypassValvePosition := 100.0; (* Full bypass *)

        IF rTurbineSpeedAct < 50.0 THEN
            iState := 0;
        END_IF;

    999: (* EMERGENCY TRIP *)
        bTurbineReady := FALSE;
        bGridTied := FALSE;
        bSystemTripAlarm := TRUE;
        rGovernorValvePosition := 0.0; (* Slam shut *)
        rBypassValvePosition := 100.0; (* Dump pressure *)
        rVaporizerHeaterPower := 0.0;

        (* Require manual reset via disabling system once trip clears *)
        IF NOT bEmergencyTrip AND NOT bEnableSys THEN
            iState := 0;
        END_IF;

END_CASE;

iOperationState := iState;

END_FUNCTION_BLOCK
