FUNCTION_BLOCK FB_BiomassFluidizedBedGasifier
VAR_INPUT
    bEnable : BOOL; // System enable command
    rBedTempTop : REAL; // Top bed temperature in Celsius
    rBedTempMid : REAL; // Middle bed temperature in Celsius
    rBedTempBot : REAL; // Bottom bed temperature in Celsius
    rFluidizingAirPress : REAL; // Fluidizing air pressure in bar
    rBiomassFeedRate : REAL; // Biomass feed rate in kg/h
    rSyngasScrubberTemp : REAL; // Syngas scrubber wet-bulb temperature in Celsius
    bAshAugerMotorOK : BOOL; // Ash auger motor status
END_VAR

VAR_OUTPUT
    bFluidizingAirValve : BOOL; // Main air valve control
    rAirValvePosition : REAL; // Analog air valve position (0-100%)
    bFeedMotorRun : BOOL; // Biomass feed motor control
    rFeedMotorSpeed : REAL; // Biomass feed motor speed (0-100%)
    bScrubberPumpRun : BOOL; // Scrubber recirculation pump control
    bAshAugerRun : BOOL; // Rotary ash auger control
    bAlarmHighTemp : BOOL; // High temperature alarm flag
    bAlarmLowPressure : BOOL; // Low air pressure alarm flag
    iSystemState : INT; // Current state of the gasifier
END_VAR

VAR
    // Internal state tracking
    rAvgBedTemp : REAL;
    tScrubberTimer : TON;
    tAshAugerTimer : TON;

    // PID Controllers for Temperature and Pressure
    fbTempPID : PID;
    fbPressPID : PID;

    // Limits
    rMaxBedTemp : REAL := 850.0;
    rMinBedTemp : REAL := 650.0;
    rMaxScrubberTemp : REAL := 80.0;
    rMinAirPress : REAL := 1.2;

    // Timers
    tStartupDelay : TON;
    bStartupComplete : BOOL := FALSE;
END_VAR

// Compute average bed temperature
rAvgBedTemp := (rBedTempTop + rBedTempMid + rBedTempBot) / 3.0;

// State Machine for Gasifier Control
IF NOT bEnable THEN
    iSystemState := 0; // Shutdown state
    bFluidizingAirValve := FALSE;
    rAirValvePosition := 0.0;
    bFeedMotorRun := FALSE;
    rFeedMotorSpeed := 0.0;
    bScrubberPumpRun := FALSE;
    bAshAugerRun := FALSE;
    bStartupComplete := FALSE;
ELSE
    CASE iSystemState OF
        0: // Initialization and Purge
            bFluidizingAirValve := TRUE;
            rAirValvePosition := 20.0; // 20% purge flow
            bFeedMotorRun := FALSE;
            bScrubberPumpRun := TRUE; // Start scrubber
            tStartupDelay(IN:= TRUE, PT:= T#5M);
            IF tStartupDelay.Q THEN
                iSystemState := 1; // Heating state
                tStartupDelay(IN:= FALSE);
            END_IF;

        1: // Heating and Bed Fluidization
            // Control air based on target pressure
            fbPressPID(
                ACTUAL := rFluidizingAirPress,
                SET_POINT := 2.5,
                KP := 1.5,
                KI := 0.5,
                KD := 0.1
            );
            rAirValvePosition := fbPressPID.OUT;

            IF rAvgBedTemp > rMinBedTemp THEN
                iSystemState := 2; // Normal Operation
            END_IF;

        2: // Normal Operation (Gasification)
            // Feed control based on temperature
            fbTempPID(
                ACTUAL := rAvgBedTemp,
                SET_POINT := 750.0,
                KP := 2.0,
                KI := 0.2,
                KD := 0.5
            );
            bFeedMotorRun := TRUE;
            rFeedMotorSpeed := fbTempPID.OUT;

            // Ash removal sequencing
            tAshAugerTimer(IN:= NOT tAshAugerTimer.Q, PT:= T#10M);
            IF tAshAugerTimer.Q AND bAshAugerMotorOK THEN
                bAshAugerRun := TRUE;
            ELSE
                bAshAugerRun := FALSE;
            END_IF;

            // Scrubber control
            IF rSyngasScrubberTemp > rMaxScrubberTemp THEN
                bScrubberPumpRun := TRUE;
            END_IF;

            // Safety checks
            IF rAvgBedTemp > rMaxBedTemp THEN
                bAlarmHighTemp := TRUE;
                iSystemState := 3; // Emergency Shutdown
            END_IF;
            IF rFluidizingAirPress < rMinAirPress THEN
                bAlarmLowPressure := TRUE;
                iSystemState := 3; // Emergency Shutdown
            END_IF;

        3: // Emergency Shutdown
            bFeedMotorRun := FALSE;
            rFeedMotorSpeed := 0.0;
            bFluidizingAirValve := TRUE;
            rAirValvePosition := 10.0; // Minimum cooling air
            bAshAugerRun := FALSE;
            // Wait for manual reset
    END_CASE;
END_IF;
END_FUNCTION_BLOCK
