FUNCTION_BLOCK FB_Subsea_Multiphase_Pump_Control
TITLE = 'Sub-sea Multiphase Pumping Station Control'
// Subsea Multiphase Pump control with dynamic GVF compensation, VFD cooling, and mechanical seal monitoring

VAR_INPUT
    rInletPressure      : REAL; // Pump inlet pressure (bar)
    rDischargePressure  : REAL; // Pump discharge pressure (bar)
    rInletTemp          : REAL; // Inlet temperature (C)
    rMeasuredFlow       : REAL; // Multiphase flow rate (m3/h)
    rGasVolumeFraction  : REAL; // Measured Gas Volume Fraction (0.0 to 1.0)
    rVFD_Current        : REAL; // VFD output current (A)
    rVFD_Frequency      : REAL; // VFD output frequency (Hz)
    rVFD_CoolantTempIn  : REAL; // Subsea VFD coolant inlet temperature (C)
    rSealBarrierPress   : REAL; // Mechanical seal barrier fluid pressure (bar)
    bStartCommand       : BOOL; // Operator start command
    bStopCommand        : BOOL; // Operator stop command
    bEmergencyStop      : BOOL; // Subsea Emergency Shutdown (ESD)
END_VAR

VAR_OUTPUT
    rTargetSpeedRPM     : REAL; // Speed reference to VFD (RPM)
    rChokeValvePos      : REAL; // Suction choke valve position (%)
    bPumpRunning        : BOOL; // Run feedback
    bTrip               : BOOL; // Protection trip active
    bWarningActive      : BOOL; // Warning alarm active
    rSealDiffPress      : REAL; // Seal differential pressure
    rEstCoolingLoad     : REAL; // Estimated VFD cooling load (kW)
END_VAR

VAR
    // Internal States and Timers
    eState              : INT := 0; // 0=Stop, 1=StartSeq, 2=Running, 3=StopSeq, 4=Trip
    tonStartDelay       : TON;
    tonSealStable       : TON;

    // Internal calculations
    rDifferentialPress  : REAL;
    rGVF_CorrectionFact : REAL;
    rMaxSpeedLimit      : REAL;
    rMinSpeedLimit      : REAL;
    rPID_Error          : REAL;
    rPID_Integral       : REAL;

    // Limits and Setpoints
    rMaxGVF_Limit       : REAL := 0.95; // 95% GVF trip
    rMinSealDiffPress   : REAL := 15.0; // Minimum 15 bar diff pressure across seal
    rMaxCoolantTemp     : REAL := 45.0; // Trip if coolant > 45 C
    rTargetDiffPress    : REAL := 30.0; // Target delta P across pump
END_VAR

// 1. Critical Safety and Interlocks
bTrip := FALSE;
bWarningActive := FALSE;

// Calculate Seal Differential Pressure (Barrier vs Inlet Process Pressure)
rSealDiffPress := rSealBarrierPress - rInletPressure;

IF rSealDiffPress < rMinSealDiffPress THEN
    bTrip := TRUE; // Loss of barrier fluid pressure overbalance
END_IF;

IF rVFD_CoolantTempIn > rMaxCoolantTemp THEN
    bTrip := TRUE; // VFD cooling failure
ELSIF rVFD_CoolantTempIn > (rMaxCoolantTemp - 5.0) THEN
    bWarningActive := TRUE;
END_IF;

IF rGasVolumeFraction > rMaxGVF_Limit THEN
    bTrip := TRUE; // Gas locking risk
ELSIF rGasVolumeFraction > 0.85 THEN
    bWarningActive := TRUE;
END_IF;

IF bEmergencyStop THEN
    bTrip := TRUE;
END_IF;

// 2. Dynamic GVF Compensation (Derating Pump Speed)
// Higher GVF requires higher speed to prevent gas accumulation, but torque drops.
// We apply a correction factor to the speed bounds.
IF rGasVolumeFraction < 0.2 THEN
    rGVF_CorrectionFact := 1.0;
ELSIF rGasVolumeFraction < 0.6 THEN
    rGVF_CorrectionFact := 1.0 + (rGasVolumeFraction - 0.2) * 0.5; // up to 1.2x speed boost
ELSE
    rGVF_CorrectionFact := 1.2 + (rGasVolumeFraction - 0.6) * 1.5; // Aggressive speed boost for high gas
END_IF;

rMinSpeedLimit := 1200.0 * rGVF_CorrectionFact;
rMaxSpeedLimit := 3600.0 * (1.0 - (rGasVolumeFraction * 0.1)); // Reduce max power limit at high GVF to save motor

// 3. VFD Cooling Load Estimation
// P = sqrt(3) * V * I * pf. Assume constant voltage/pf for cooling estimation.
rEstCoolingLoad := rVFD_Current * rVFD_Frequency * 0.05; // Simplified subsea thermal model

// 4. Main State Machine
CASE eState OF
    0: // STOPPED
        bPumpRunning := FALSE;
        rTargetSpeedRPM := 0.0;
        rChokeValvePos := 0.0;
        IF bStartCommand AND NOT bTrip THEN
            eState := 1;
        END_IF;

    1: // STARTING SEQUENCE
        // Pre-pressurize seal and open choke
        rChokeValvePos := 20.0; // Crack open choke
        tonStartDelay(IN:=TRUE, PT:=T#10s);
        IF tonStartDelay.Q THEN
            tonStartDelay(IN:=FALSE);
            rTargetSpeedRPM := rMinSpeedLimit;
            bPumpRunning := TRUE;
            eState := 2;
        END_IF;

    2: // RUNNING
        bPumpRunning := TRUE;
        rChokeValvePos := 100.0; // Fully open during normal run

        // Simple PI control for Delta P
        rDifferentialPress := rDischargePressure - rInletPressure;
        rPID_Error := rTargetDiffPress - rDifferentialPress;

        rPID_Integral := rPID_Integral + (rPID_Error * 0.1); // Ki
        rTargetSpeedRPM := rMinSpeedLimit + (rPID_Error * 5.0) + rPID_Integral; // Kp

        // Clamp speed
        IF rTargetSpeedRPM > rMaxSpeedLimit THEN
            rTargetSpeedRPM := rMaxSpeedLimit;
        ELSIF rTargetSpeedRPM < rMinSpeedLimit THEN
            rTargetSpeedRPM := rMinSpeedLimit;
        END_IF;

        IF bStopCommand THEN
            eState := 3;
        END_IF;

    3: // STOPPING SEQUENCE
        rTargetSpeedRPM := 0.0;
        rChokeValvePos := 0.0;
        bPumpRunning := FALSE;
        eState := 0;

    4: // TRIPPED
        rTargetSpeedRPM := 0.0;
        rChokeValvePos := 0.0;
        bPumpRunning := FALSE;
        IF NOT bTrip THEN
            eState := 0;
        END_IF;
END_CASE;

// Trip override
IF bTrip THEN
    eState := 4;
    tonStartDelay(IN:=FALSE);
    rPID_Integral := 0.0;
END_IF;

END_FUNCTION_BLOCK
