VERSION : 0.1
   VAR_INPUT
      scadaControlReq : Bool; scadaToken : DWord; // Basic IEC 62443 MAC
      doLevel_PV1 : Real; doLevel_PV2 : Real; // Redundant Sensors
      pH_PV1 : Real; pH_PV2 : Real;
