FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    // Physical I/O
    rMagBearingAxial_um    : REAL; // Axial clearance of magnetic bearing in micrometers
    rMagBearingRadialX_um  : REAL; // Radial X clearance in micrometers
    rMagBearingRadialY_um  : REAL; // Radial Y clearance in micrometers
    rVacuumPressure_mBar   : REAL; // Vacuum enclosure pressure in millibars
    rGridFrequency_Hz      : REAL; // Grid frequency in Hertz
    rGridVoltage_V         : REAL; // Grid voltage in Volts
    rActivePowerReq_kW     : REAL; // Requested active power (positive for discharge/generate, negative for charge/motor)
