VAR_OUTPUT
    rActivePowerOut_kW     : REAL; // Actual active power output/input
    rMagBearingCtrlZ_V     : REAL; // Axial bearing control signal (-10V to 10V)
    rMagBearingCtrlX_V     : REAL; // Radial X bearing control signal (-10V to 10V)
    rMagBearingCtrlY_V     : REAL; // Radial Y bearing control signal (-10V to 10V)
