VAR
    // Internal States and PID parameters
    rSpeed_RPM             : REAL := 0.0;
    rTargetSpeed_RPM       : REAL := 15000.0;
    rVacuumThreshold       : REAL := 1.0;   // Pump turns on above 1.0 mBar
    rVacuumHysteresis      : REAL := 0.2;   // Pump turns off below 0.8 mBar

    // Bearing nominal clearances
    rNominalClearanceAxial : REAL := 500.0;
    rNominalClearanceRadial: REAL := 400.0;

    // Bearing control errors
    rErrAxial              : REAL;
    rErrRadialX            : REAL;
    rErrRadialY            : REAL;

    // Control constants
    Kp_Axial               : REAL := 0.05;
    Kd_Axial               : REAL := 0.01;
    Kp_Radial              : REAL := 0.04;
    Kd_Radial              : REAL := 0.008;

    // Previous errors for derivative
    rPrevErrAxial          : REAL := 0.0;
    rPrevErrRadialX        : REAL := 0.0;
    rPrevErrRadialY        : REAL := 0.0;

    // Timers
    tSpinUpTimer           : TIME := T#0S;
END_VAR

// Control Logic Implementation
IF NOT bSystemEnable OR NOT bEmergencyStop THEN
    // Safe state shutdown
    bGridContactorCmd := FALSE;
    bVacuumPumpCmd := FALSE;
    rActivePowerOut_kW := 0.0;
    rMagBearingCtrlZ_V := 0.0;
    rMagBearingCtrlX_V := 0.0;
    rMagBearingCtrlY_V := 0.0;
    bFaultActive := TRUE;
    iFaultCode := 16#FFFF; // E-Stop or Disabled
    RETURN;
END_IF;

bFaultActive := FALSE;
iFaultCode := 0;

// 1. Vacuum Control Subsystem
// Maintain high vacuum to reduce aerodynamic drag on the flywheel rotor
IF rVacuumPressure_mBar > rVacuumThreshold THEN
    bVacuumPumpCmd := TRUE;
ELSIF rVacuumPressure_mBar < (rVacuumThreshold - rVacuumHysteresis) THEN
    bVacuumPumpCmd := FALSE;
END_IF;

IF rVacuumPressure_mBar > 10.0 THEN
    // Severe vacuum loss fault
    bFaultActive := TRUE;
    iFaultCode := 16#0001;
    bGridContactorCmd := FALSE;
    RETURN;
END_IF;

// 2. Magnetic Bearing Levitation Subsystem
// Calculate errors
rErrAxial := rNominalClearanceAxial - rMagBearingAxial_um;
rErrRadialX := rNominalClearanceRadial - rMagBearingRadialX_um;
rErrRadialY := rNominalClearanceRadial - rMagBearingRadialY_um;

// PD Control for bearings (simplified, assuming high-speed sampling in real application)
rMagBearingCtrlZ_V := (rErrAxial * Kp_Axial) + ((rErrAxial - rPrevErrAxial) * Kd_Axial);
rMagBearingCtrlX_V := (rErrRadialX * Kp_Radial) + ((rErrRadialX - rPrevErrRadialX) * Kd_Radial);
rMagBearingCtrlY_V := (rErrRadialY * Kp_Radial) + ((rErrRadialY - rPrevErrRadialY) * Kd_Radial);

// Saturate outputs (-10V to 10V)
IF rMagBearingCtrlZ_V > 10.0 THEN rMagBearingCtrlZ_V := 10.0; ELSIF rMagBearingCtrlZ_V < -10.0 THEN rMagBearingCtrlZ_V := -10.0; END_IF;
IF rMagBearingCtrlX_V > 10.0 THEN rMagBearingCtrlX_V := 10.0; ELSIF rMagBearingCtrlX_V < -10.0 THEN rMagBearingCtrlX_V := -10.0; END_IF;
IF rMagBearingCtrlY_V > 10.0 THEN rMagBearingCtrlY_V := 10.0; ELSIF rMagBearingCtrlY_V < -10.0 THEN rMagBearingCtrlY_V := -10.0; END_IF;

// Store previous errors
rPrevErrAxial := rErrAxial;
rPrevErrRadialX := rErrRadialX;
rPrevErrRadialY := rErrRadialY;

// Check for bearing clearance limits (imminent crash)
IF ABS(rErrAxial) > 400.0 OR ABS(rErrRadialX) > 300.0 OR ABS(rErrRadialY) > 300.0 THEN
    bFaultActive := TRUE;
    iFaultCode := 16#0002;
    // Engage mechanical backup bearings (handled external to this block)
    bGridContactorCmd := FALSE;
    RETURN;
END_IF;

// 3. Motor-Generator Active Power Inversion Subsystem
// Connect to grid if within synchronization bounds
IF rGridFrequency_Hz > 49.5 AND rGridFrequency_Hz < 50.5 AND rGridVoltage_V > 380.0 THEN
    bGridContactorCmd := TRUE;
ELSE
    bGridContactorCmd := FALSE;
    bFaultActive := TRUE;
    iFaultCode := 16#0003;
END_IF;

IF bGridContactorCmd THEN
    // Simple ramp to requested power
    IF rActivePowerOut_kW < rActivePowerReq_kW THEN
        rActivePowerOut_kW := rActivePowerOut_kW + 5.0; // Ramp rate
        IF rActivePowerOut_kW > rActivePowerReq_kW THEN
            rActivePowerOut_kW := rActivePowerReq_kW;
        END_IF;
    ELSIF rActivePowerOut_kW > rActivePowerReq_kW THEN
        rActivePowerOut_kW := rActivePowerOut_kW - 5.0;
        IF rActivePowerOut_kW < rActivePowerReq_kW THEN
            rActivePowerOut_kW := rActivePowerReq_kW;
        END_IF;
    END_IF;
ELSE
    rActivePowerOut_kW := 0.0;
END_IF;

END_FUNCTION_BLOCK
