VAR
    bSystem_Running : Bool;
    iState : Int;

    // PID Instance variables
    instPID_Temp : "PID_Compact";
    instPID_Humidity : "PID_Compact";
    rTemp_Setpoint : Real := 22.0; // Optimal 22C
    rHumidity_Setpoint : Real := 55.0; // Optimal 55% RH
END_VAR

BEGIN
    // System Start/Stop
    IF #bStop_PB THEN
        #bSystem_Running := FALSE;
    ELSIF #bStart_PB THEN
        #bSystem_Running := TRUE;
    END_IF;

    IF NOT #bSystem_Running THEN
        #iState := 0;
    ELSIF #bSystem_Running AND #iState = 0 THEN
        #iState := 1;
    END_IF;

    // Main State Machine
    CASE #iState OF
        0: // Stop
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := FALSE;

        1: // Index Conveyor
            #bRobot_Enable := FALSE;
            IF NOT #bCar_In_Position THEN
                #bConveyor_Motor := TRUE;
            ELSE
                #bConveyor_Motor := FALSE;
                #iState := 2;
            END_IF;

        2: // Painting
            #bConveyor_Motor := FALSE;
            // Only paint if HVAC conditions are within tolerance
            IF ABS(#rTemp_Actual - #rTemp_Setpoint) < 2.0 AND ABS(#rHumidity_Actual - #rHumidity_Setpoint) < 5.0 THEN
                #bRobot_Enable := TRUE;
            ELSE
                #bRobot_Enable := FALSE;
            END_IF;
    END_CASE;

    // HVAC PID Control
    #instPID_Temp(
        Setpoint := #rTemp_Setpoint,
        Input := #rTemp_Actual,
        Reset := NOT #bSystem_Running,
        Output => #rHeater_Valve
    );

    #instPID_Humidity(
        Setpoint := #rHumidity_Setpoint,
        Input := #rHumidity_Actual,
        Reset := NOT #bSystem_Running,
        Output => #rHumidifier_Valve
    );

    // Overspray Management
    IF #bSystem_Running AND (#rOverspray_Concentration > 20.0) THEN
        #bExhaust_Fan := TRUE;
    ELSE
        #bExhaust_Fan := FALSE;
    END_IF;

    IF #bSystem_Running AND (#rOverspray_Concentration > 60.0) THEN
        #bCapture_Pump := TRUE;
    ELSE
        #bCapture_Pump := FALSE;
    END_IF;
END_FUNCTION_BLOCK
