    fDerivative_StillTemp : REAL;
    fError_MixChamber : REAL;
    fDerivative_MixChamber : REAL;
END_VAR

IF bEmergencyStop THEN
    nState := 4;
    nErrorCode := 999;
END_IF;

CASE nState OF
    0:
        bSystemRunning := FALSE;
        bCirculationActive := FALSE;
        fStillHeaterPower_W := 0.0;
        fCondensingValve_pct := 0.0;
        bPump_He3Circulation_Run := FALSE;
        fPump_He3Circulation_Speed_Hz := 0.0;
        IF bEnable AND NOT bError THEN
            nState := 1;
        END_IF;
    1:
        bSystemRunning := TRUE;
        IF fTemp_Condensing_K < 4.2 AND fLevel_He4_Bath_pct > 50.0 THEN
            nState := 2;
        END_IF;
    2:
        bSystemRunning := TRUE;
        fCondensingValve_pct := 100.0;
        bPump_He3Circulation_Run := TRUE;
        fPump_He3Circulation_Speed_Hz := 20.0;
        IF fPressure_Condensing_mbar < fMinCondensingPressure_mbar THEN
            bCondensationComplete := TRUE;
        END_IF;
        IF bCondensationComplete AND fTemp_Still_K < 1.0 THEN
            nState := 3;
            fStillHeater_Integral := 0.0;
            fFlow_Integral := 0.0;
        END_IF;
    3:
        bSystemRunning := TRUE;
        bCirculationActive := TRUE;
        fError_StillTemp := fTargetStillTemp_K - fTemp_Still_K;
        fStillHeater_Integral := fStillHeater_Integral + fError_StillTemp;
        fDerivative_StillTemp := fError_StillTemp - fStillHeater_PrevError;
        fStillHeaterPower_W := (fStillHeater_Kp * fError_StillTemp) + (fStillHeater_Ki * fStillHeater_Integral) + (fStillHeater_Kd * fDerivative_StillTemp);
        IF fStillHeaterPower_W > fMaxStillPower_W THEN
            fStillHeaterPower_W := fMaxStillPower_W;
        ELSIF fStillHeaterPower_W < 0.0 THEN
            fStillHeaterPower_W := 0.0;
        END_IF;
        fStillHeater_PrevError := fError_StillTemp;
        fError_MixChamber := fSetPoint_MixingChamber_mK - fTemp_MixingChamber_mK;
        fFlow_Integral := fFlow_Integral + fError_MixChamber;
        fDerivative_MixChamber := fError_MixChamber - fFlow_PrevError;
        fPump_He3Circulation_Speed_Hz := 50.0 - ((fFlow_Kp * fError_MixChamber) + (fFlow_Ki * fFlow_Integral) + (fFlow_Kd * fDerivative_MixChamber));
        IF fPump_He3Circulation_Speed_Hz > 100.0 THEN
            fPump_He3Circulation_Speed_Hz := 100.0;
        ELSIF fPump_He3Circulation_Speed_Hz < 10.0 THEN
            fPump_He3Circulation_Speed_Hz := 10.0;
        END_IF;
        bPump_He3Circulation_Run := TRUE;
        fFlow_PrevError := fError_MixChamber;
        fCondensingValve_pct := 50.0;
        IF NOT bEnable THEN
            nState := 0;
        END_IF;
    4:
