FUNCTION_BLOCK "WaferSpinner_Mut1"
VERSION : 0.1
   VAR_INPUT
      execute : Bool;
      targetSpeed : Real;
      dispenseTime : Time;
      flowFeedback : Real; // Current flow rate
      targetFlow : Real;
   END_VAR
   VAR_OUTPUT
      busy : Bool;
      done : Bool;
      currentSpeed : Real;
      pumpControl : Real; // PID output
   END_VAR
   VAR
      state : Int;
      timer : TON_TIME;
      pidInst : PID_Compact;
      pidEnable : Bool;
   END_VAR

BEGIN
   // PID Call
   #pidInst(Setpoint := #targetFlow,
            Input := #flowFeedback,
            RunModeByStartup := FALSE,
            ManualEnable := FALSE,
            Reset := NOT #pidEnable);

   CASE #state OF
      0: // Idle
         #busy := FALSE;
         #done := FALSE;
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pumpControl := 0.0;
         IF #execute THEN
            #state := 10;
            #busy := TRUE;
         END_IF;

      10: // Spin Up
         #currentSpeed := #targetSpeed; 
         IF #currentSpeed >= #targetSpeed THEN
            #state := 20;
         END_IF;

      20: // Dispense with PID
         #pidEnable := TRUE;
         #pumpControl := #pidInst.Output;
         #timer(IN := TRUE, PT := #dispenseTime);
         IF #timer.Q THEN
            #pidEnable := FALSE;
            #pumpControl := 0.0;
            #timer(IN := FALSE, PT := #dispenseTime);
            #state := 30;
         END_IF;

      30: // Stop
         #currentSpeed := 0.0;
         #done := TRUE;
         #busy := FALSE;
         IF NOT #execute THEN
            #state := 0;
         END_IF;
   END_CASE;
END_FUNCTION_BLOCK
