FUNCTION_BLOCK FB_Geothermal_Flash_Control
TITLE = 'Geothermal Flash Steam Power Plant Advanced Control'
VERSION : '1.0'

VAR_INPUT
    // Physical I/O
    PT_Wellhead : REAL; // Wellhead Pressure (bar)
    TT_Wellhead : REAL; // Wellhead Temperature (°C)
    FT_TwoPhase : REAL; // Two-phase mass flow rate (kg/s)
    PT_FlashSep : REAL; // Flash Separator Pressure (bar)
    LT_FlashSep : REAL; // Flash Separator Level (%)
    QT_ScaleIdx : REAL; // Brine scaling index (ppm Silica)
    PT_Condenser : REAL; // Condenser Pressure (bar, vacuum)
    FT_NCG_Exhaust : REAL; // Non-Condensable Gas Flow (kg/s)

    // Setpoints
    SP_SepLevel : REAL := 50.0;
    SP_WellheadP : REAL := 15.0;
    SP_CondVacuum : REAL := 0.1;

    // System Status
    bEmergencyStop : BOOL;
    bAutoMode : BOOL;
END_VAR

VAR_OUTPUT
    // Actuators
    CV_WellheadThrottling : REAL; // Wellhead throttling valve position (0-100%)
    CV_BrineReject : REAL; // Brine reinjection valve position (0-100%)
    CV_SteamToTurbine : REAL; // Main steam control valve (0-100%)
    CV_ChemInject : REAL; // Anti-scaling chemical injection pump speed (0-100%)
    CV_NCG_Ejector : REAL; // Steam ejector motive valve for NCG removal (0-100%)

    // Alarms
    ALM_HighScalingRisk : BOOL;
    ALM_SepLevelDeviation : BOOL;
    ALM_VacuumLoss : BOOL;
END_VAR

VAR
    // Internal Variables
    PI_Level_Err : REAL;
    PI_Level_Int : REAL;
    PI_Level_Kp : REAL := 2.5;
    PI_Level_Ki : REAL := 0.1;

    PI_Press_Err : REAL;
    PI_Press_Int : REAL;
    PI_Press_Kp : REAL := 1.2;
    PI_Press_Ki : REAL := 0.05;

    // Scaling Logic
    ScalingThreshold : REAL := 450.0; // ppm
    ChemDoseRateBase : REAL := 15.0; // Base pump speed %

    // Timers
    TMR_VacuumLoss : TON;
    TMR_LevelAlarm : TON;
END_VAR

// Control Logic Implementation
IF bEmergencyStop THEN
    CV_WellheadThrottling := 0.0;
    CV_BrineReject := 100.0; // Dump brine
    CV_SteamToTurbine := 0.0;
    CV_ChemInject := 0.0;
    CV_NCG_Ejector := 100.0; // Maintain vacuum as long as possible

    ALM_HighScalingRisk := FALSE;
    ALM_SepLevelDeviation := FALSE;
    ALM_VacuumLoss := FALSE;
    RETURN;
END_IF;

IF bAutoMode THEN
    // 1. Separator Level Control (Brine Reject Valve)
    PI_Level_Err := LT_FlashSep - SP_SepLevel;
    PI_Level_Int := PI_Level_Int + (PI_Level_Err * 0.1); // Assuming 100ms cycle
    // Anti-windup
    IF PI_Level_Int > 100.0 THEN PI_Level_Int := 100.0; END_IF;
    IF PI_Level_Int < -100.0 THEN PI_Level_Int := -100.0; END_IF;

    CV_BrineReject := (PI_Level_Err * PI_Level_Kp) + (PI_Level_Int * PI_Level_Ki) + 50.0;

    IF CV_BrineReject > 100.0 THEN CV_BrineReject := 100.0; END_IF;
    IF CV_BrineReject < 0.0 THEN CV_BrineReject := 0.0; END_IF;

    // 2. Wellhead Throttling (Pressure Control)
    PI_Press_Err := PT_Wellhead - SP_WellheadP;
    PI_Press_Int := PI_Press_Int + (PI_Press_Err * 0.1);

    IF PI_Press_Int > 100.0 THEN PI_Press_Int := 100.0; END_IF;
    IF PI_Press_Int < -100.0 THEN PI_Press_Int := -100.0; END_IF;

    CV_WellheadThrottling := (PI_Press_Err * PI_Press_Kp) + (PI_Press_Int * PI_Press_Ki) + 50.0;

    IF CV_WellheadThrottling > 100.0 THEN CV_WellheadThrottling := 100.0; END_IF;
    IF CV_WellheadThrottling < 10.0 THEN CV_WellheadThrottling := 10.0; END_IF; // Minimum flow

    // 3. Anti-Scaling Chemical Injection
    IF QT_ScaleIdx > ScalingThreshold THEN
        CV_ChemInject := ChemDoseRateBase + ((QT_ScaleIdx - ScalingThreshold) * 0.5);
        ALM_HighScalingRisk := TRUE;
    ELSE
        CV_ChemInject := ChemDoseRateBase;
        ALM_HighScalingRisk := FALSE;
    END_IF;

    IF CV_ChemInject > 100.0 THEN CV_ChemInject := 100.0; END_IF;

    // 4. Non-Condensable Gas (NCG) Extraction
    // Modulate motive steam to ejectors based on condenser vacuum and NCG flow
    IF PT_Condenser > (SP_CondVacuum + 0.05) THEN
        CV_NCG_Ejector := CV_NCG_Ejector + 0.5; // Ramp up
    ELSIF PT_Condenser < SP_CondVacuum THEN
        CV_NCG_Ejector := CV_NCG_Ejector - 0.2; // Ramp down slowly to save steam
    END_IF;

    IF CV_NCG_Ejector > 100.0 THEN CV_NCG_Ejector := 100.0; END_IF;
    IF CV_NCG_Ejector < 20.0 THEN CV_NCG_Ejector := 20.0; END_IF;

    // 5. Steam to Turbine Base Load (Simplified)
    CV_SteamToTurbine := 85.0; // Fixed base load

END_IF;

// Alarm Generation
TMR_VacuumLoss(IN:= (PT_Condenser > 0.3), PT:= T#10s);
ALM_VacuumLoss := TMR_VacuumLoss.Q;

TMR_LevelAlarm(IN:= (ABS(LT_FlashSep - SP_SepLevel) > 15.0), PT:= T#5s);
ALM_SepLevelDeviation := TMR_LevelAlarm.Q;

END_FUNCTION_BLOCK
