FUNCTION_BLOCK FB_GypsumBoardManufacturingCore
TITLE = 'Advanced Gypsum Board Line Coordinator'

(*
  Complex Gypsum Board Manufacturing Line Coordinator
  Handles Stucco mixer water/foam ratio cascades, continuous paper web tension,
  and multi-deck drying kiln profiling.
*)

VAR_INPUT
    xEnableLine : BOOL;                 (* Master enable *)
    xEmergencyStop : BOOL;              (* E-Stop condition *)

    rStuccoFlowRate_kg_min : REAL;      (* Incoming stucco flow measurement *)
    rTargetWaterRatio : REAL;           (* Desired Water/Stucco ratio *)
    rTargetFoamRatio : REAL;            (* Desired Foam/Stucco ratio *)

    rActualWebTension : REAL;           (* Tension sensor feedback in N *)
    rTargetWebTension : REAL;           (* Setpoint for web tension in N *)

    rActualKilnTemp_Z1 : REAL;          (* Zone 1 Temperature *)
    rActualKilnTemp_Z2 : REAL;          (* Zone 2 Temperature *)
    rActualKilnTemp_Z3 : REAL;          (* Zone 3 Temperature *)
    rActualKilnTemp_Z4 : REAL;          (* Zone 4 Temperature *)
    rTargetKilnTemp_Z1 : REAL;
    rTargetKilnTemp_Z2 : REAL;
    rTargetKilnTemp_Z3 : REAL;
    rTargetKilnTemp_Z4 : REAL;
END_VAR

VAR_OUTPUT
    rWaterValveCmd_pct : REAL;          (* Command to water metering valve (0-100%) *)
    rFoamValveCmd_pct : REAL;           (* Command to foam metering valve (0-100%) *)
    rWebDriveSpeed_rpm : REAL;          (* Command to paper pull roll drive *)

    rKilnBurnerCmd_Z1 : REAL;           (* Kiln Zone 1 burner modulation (0-100%) *)
    rKilnBurnerCmd_Z2 : REAL;           (* Kiln Zone 2 burner modulation (0-100%) *)
    rKilnBurnerCmd_Z3 : REAL;           (* Kiln Zone 3 burner modulation (0-100%) *)
    rKilnBurnerCmd_Z4 : REAL;           (* Kiln Zone 4 burner modulation (0-100%) *)

    xLineFault : BOOL;                  (* Global fault indicator *)
    iState : INT;                       (* Current state machine step *)
END_VAR

VAR
    // Internal state and cascades
    rCalculatedWaterSP : REAL;
    rCalculatedFoamSP : REAL;

    // PID instances (simulated manual loops for determinism)
    TensionError : REAL;
    TensionIntegral : REAL;
    TensionDerivative : REAL;
    LastTensionError : REAL;

    // Kiln PIDs
    rZ1_Error, rZ1_Int : REAL;
    rZ2_Error, rZ2_Int : REAL;
    rZ3_Error, rZ3_Int : REAL;
    rZ4_Error, rZ4_Int : REAL;

    Kp_Tension : REAL := 0.65;
    Ki_Tension : REAL := 0.12;
    Kd_Tension : REAL := 0.05;

    Kp_Temp : REAL := 3.5;
    Ki_Temp : REAL := 0.45;

    CYCLE_TIME : REAL := 0.02; // 20ms PLC cycle
END_VAR

(* --- MAIN STATE MACHINE --- *)
IF xEmergencyStop THEN
    iState := 99; // FAULT
ELSIF NOT xEnableLine AND iState <> 99 THEN
    iState := 0;  // IDLE
ELSIF xEnableLine AND iState = 0 THEN
    iState := 10; // STARTUP
END_IF;

CASE iState OF
    0: (* IDLE *)
        rWaterValveCmd_pct := 0.0;
        rFoamValveCmd_pct := 0.0;
        rWebDriveSpeed_rpm := 0.0;
        rKilnBurnerCmd_Z1 := 0.0;
        rKilnBurnerCmd_Z2 := 0.0;
        rKilnBurnerCmd_Z3 := 0.0;
        rKilnBurnerCmd_Z4 := 0.0;
        xLineFault := FALSE;

    10: (* STARTUP / PRE-HEAT *)
        // Ignite burners, establish base web tension, dry mix initial
        iState := 20; // Proceed to run condition immediately for demo

    20: (* PRODUCTION RUN *)
        (* 1. Stucco Mixer Cascade Control *)
        // Feedforward calculation based on mass flows and target ratios
        rCalculatedWaterSP := rStuccoFlowRate_kg_min * rTargetWaterRatio;
        rCalculatedFoamSP := rStuccoFlowRate_kg_min * rTargetFoamRatio;

        // Map calculated mass flows to valve percentages (valve flow characteristic curves simplified)
        rWaterValveCmd_pct := rCalculatedWaterSP * 2.85;
        rFoamValveCmd_pct := rCalculatedFoamSP * 6.20;

        // Valve Saturation limiters
        IF rWaterValveCmd_pct > 100.0 THEN rWaterValveCmd_pct := 100.0; END_IF;
        IF rFoamValveCmd_pct > 100.0 THEN rFoamValveCmd_pct := 100.0; END_IF;

        (* 2. Continuous Paper Web Tension Control (PID + Derivative Filtering) *)
        TensionError := rTargetWebTension - rActualWebTension;
        TensionIntegral := TensionIntegral + (TensionError * CYCLE_TIME);

        // Anti-windup
        IF TensionIntegral > 5000.0 THEN TensionIntegral := 5000.0; ELSIF TensionIntegral < -5000.0 THEN TensionIntegral := -5000.0; END_IF;

        TensionDerivative := (TensionError - LastTensionError) / CYCLE_TIME;

        // Drive speed calculation with base speed feedforward
        rWebDriveSpeed_rpm := 1850.0 + (Kp_Tension * TensionError) + (Ki_Tension * TensionIntegral) + (Kd_Tension * TensionDerivative);
        LastTensionError := TensionError;

        // Output Limit Web Speed
        IF rWebDriveSpeed_rpm > 3500.0 THEN rWebDriveSpeed_rpm := 3500.0; END_IF;
        IF rWebDriveSpeed_rpm < 0.0 THEN rWebDriveSpeed_rpm := 0.0; END_IF;

        (* 3. Multi-Deck Drying Kiln Profiling *)
        // Zone 1 PID
        rZ1_Error := rTargetKilnTemp_Z1 - rActualKilnTemp_Z1;
        rZ1_Int := rZ1_Int + (rZ1_Error * CYCLE_TIME);
        rKilnBurnerCmd_Z1 := (Kp_Temp * rZ1_Error) + (Ki_Temp * rZ1_Int);
        IF rKilnBurnerCmd_Z1 > 100.0 THEN rKilnBurnerCmd_Z1 := 100.0; ELSIF rKilnBurnerCmd_Z1 < 0.0 THEN rKilnBurnerCmd_Z1 := 0.0; END_IF;

        // Zone 2 PID
        rZ2_Error := rTargetKilnTemp_Z2 - rActualKilnTemp_Z2;
        rZ2_Int := rZ2_Int + (rZ2_Error * CYCLE_TIME);
        rKilnBurnerCmd_Z2 := (Kp_Temp * rZ2_Error) + (Ki_Temp * rZ2_Int);
