FUNCTION_BLOCK "MilkPasteurizer_Adversarial"
VAR_INPUT
    Start : BOOL;
    TempSens1 : REAL;
    TempSens2 : REAL;
    HIL_Twin_Temp : REAL; // Digital twin expected temperature
    FDV_Pos_Fwd_Feedback : BOOL;
    FDV_Pos_Div_Feedback : BOOL;
END_VAR

VAR_OUTPUT
    Heater_Out : REAL;
    FDV_Fwd_Cmd : BOOL;
    FDV_Div_Cmd : BOOL;
    DriftAlarm : BOOL;
    TwinSyncAlarm : BOOL;
    SelfTestFailed : BOOL;
    SystemReady : BOOL;
END_VAR

VAR
    State : INT := 0; // 0=Init, 1=SelfTest_Divert, 2=SelfTest_Fwd, 3=Run
    ActiveTemp : REAL;
    TestTimer : TON;
    PID_Inst : "PID_Compact";
    HoldTimer : TON;
END_VAR

BEGIN
    // 1. Sensor Drift & HIL Sync Detection
    IF ABS(TempSens1 - TempSens2) > 1.5 THEN
        DriftAlarm := TRUE;
    ELSE
        DriftAlarm := FALSE;
    END_IF;

    ActiveTemp := (TempSens1 + TempSens2) / 2.0;

    IF ABS(ActiveTemp - HIL_Twin_Temp) > 3.0 THEN
        TwinSyncAlarm := TRUE; // Twin deviation indicates potential process anomaly
    ELSE
        TwinSyncAlarm := FALSE;
    END_IF;

    // 2. State Machine & Self-Test Routine
    CASE State OF
        0: // Init
            IF Start AND NOT DriftAlarm AND NOT TwinSyncAlarm THEN
                State := 1;
            END_IF;

        1: // Self-Test: Command Divert
            FDV_Fwd_Cmd := FALSE;
            FDV_Div_Cmd := TRUE;
            TestTimer(IN:=TRUE, PT:=T#3S);
            IF TestTimer.Q THEN
                IF FDV_Pos_Div_Feedback AND NOT FDV_Pos_Fwd_Feedback THEN
                    State := 2;
                    TestTimer(IN:=FALSE, PT:=T#3S);
                ELSE
                    SelfTestFailed := TRUE;
                    State := 99; // Fault
                END_IF;
            END_IF;

        2: // Self-Test: Command Forward
            FDV_Fwd_Cmd := TRUE;
            FDV_Div_Cmd := FALSE;
            TestTimer(IN:=TRUE, PT:=T#3S);
            IF TestTimer.Q THEN
                IF FDV_Pos_Fwd_Feedback AND NOT FDV_Pos_Div_Feedback THEN
                    State := 3;
                    SystemReady := TRUE;
                    FDV_Fwd_Cmd := FALSE;
                    FDV_Div_Cmd := TRUE; // Return to safe state
                ELSE
                    SelfTestFailed := TRUE;
                    State := 99;
                END_IF;
            END_IF;

        3: // Run Mode
            PID_Inst(
                sMode := 3,
                Setpoint := 72.0,
                Input := ActiveTemp,
                Output => Heater_Out
            );

            HoldTimer(IN := (ActiveTemp >= 72.0), PT := T#15S);

            IF HoldTimer.Q THEN
                FDV_Fwd_Cmd := TRUE;
                FDV_Div_Cmd := FALSE;
            ELSE
                FDV_Fwd_Cmd := FALSE;
                FDV_Div_Cmd := TRUE;
            END_IF;

        99: // Fault state
            FDV_Fwd_Cmd := FALSE;
            FDV_Div_Cmd := TRUE;
            SystemReady := FALSE;
            Heater_Out := 0.0;
    END_CASE;
END_FUNCTION_BLOCK
