FUNCTION_BLOCK FB_BenthicNoduleHarvester
VAR_INPUT
    (* Core Enable and Safety Interlocks *)
    bEnable                 : BOOL;     (* System master enable signal from surface vessel *)
    bEmergencyStop          : BOOL;     (* Critical safety loop status (TRUE = OK, FALSE = Tripped) *)

    (* Physical Telemetry and Sensors *)
    rAmbientDepth_m         : REAL;     (* Current crawler operating depth via hydrostatic pressure [m] *)
    rAcousticPlumeDensity   : REAL;     (* Backscatter turbidity measurement of sediment plume [mg/L] *)
    rSuctionHeadPressure    : REAL;     (* Coanda-effect suction head differential pressure [bar] *)
    rUmbilicalTension_kN    : REAL;     (* Axial load cell feedback on 6000m umbilical [kN] *)
    rNoduleMassFlow_kg_s    : REAL;     (* Corialis mass flow meter reading of harvested material [kg/s] *)
    rHydraulicTemp_C        : REAL;     (* Suction lift pump hydraulic fluid temperature [deg C] *)
END_VAR
VAR_OUTPUT
    (* Status and Alarms *)
    bSystemReady            : BOOL;     (* System ready for active harvesting sequence *)
    bActiveHarvesting       : BOOL;     (* Indicates active suction and lift operation *)
    bPlumeViolationAlarm    : BOOL;     (* Environmental alarm: plume density exceeded threshold *)
    bUmbilicalTensionAlarm  : BOOL;     (* Structural alarm: umbilical tension outside safe envelope *)

    (* Actuator Control Signals *)
    rLiftPumpSpeed_RPM      : REAL;     (* Command to variable frequency drive for lift pump [RPM] *)
    rSpoolWinchTorque_Nm    : REAL;     (* Active heave compensation winch torque command [Nm] *)
    rCoandaValvePosition    : REAL;     (* Suction head valve proportional position [0.0 - 100.0 %] *)
END_VAR
VAR
    (* State Machine *)
    iState                  : INT := 0; 

    (* Internal Timers *)
    tStartupDelay           : TON;
    tPlumeFilter            : TON;
    tHeaveCompFilter        : TON;

    (* Internal Variables for Math & Logic *)
    rTargetTension_kN       : REAL := 150.0; (* Nominal umbilical tension to maintain *)
    rTensionError           : REAL;
    rKp_Tension             : REAL := 25.5;  (* Proportional gain for AHC *)
    rKi_Tension             : REAL := 1.2;   (* Integral gain for AHC *)
    rTensionIntegral        : REAL := 0.0;

    (* Environmental Constraints *)
    MAX_PLUME_DENSITY       : REAL := 250.0; (* Maximum allowed sediment plume [mg/L] *)
    MAX_UMBILICAL_TENSION   : REAL := 450.0; (* Breaking limit safety threshold [kN] *)
    MIN_UMBILICAL_TENSION   : REAL := 25.0;  (* Slack prevention threshold [kN] *)

    bInitDone               : BOOL := FALSE;
END_VAR

(* === MAIN SAFETY INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    (* Immediate safe state on E-Stop *)
    bSystemReady            := FALSE;
    bActiveHarvesting       := FALSE;
    bUmbilicalTensionAlarm  := TRUE; (* Treat as alarm state *)
    rLiftPumpSpeed_RPM      := 0.0;
    rCoandaValvePosition    := 0.0;
    rTensionIntegral        := 0.0;

    (* Maintain constant safe torque on winch to prevent slack or snapping *)
    rSpoolWinchTorque_Nm    := 5000.0; 
    iState                  := 0;
    RETURN;
END_IF;

(* === UMBILICAL ACTIVE HEAVE COMPENSATION (AHC) PI CONTROLLER === *)
rTensionError := rTargetTension_kN - rUmbilicalTension_kN;
rTensionIntegral := rTensionIntegral + (rTensionError * 0.05); (* Assuming 50ms cycle *)

(* Anti-windup *)
IF rTensionIntegral > 10000.0 THEN
    rTensionIntegral := 10000.0;
ELSIF rTensionIntegral < -10000.0 THEN
    rTensionIntegral := -10000.0;
END_IF;

rSpoolWinchTorque_Nm := (rKp_Tension * rTensionError) + (rKi_Tension * rTensionIntegral);

(* Tension Alarming *)
IF rUmbilicalTension_kN > MAX_UMBILICAL_TENSION OR rUmbilicalTension_kN < MIN_UMBILICAL_TENSION THEN
    bUmbilicalTensionAlarm := TRUE;
ELSE
    bUmbilicalTensionAlarm := FALSE;
END_IF;

(* === ENVIRONMENTAL PLUME MONITORING === *)
IF rAcousticPlumeDensity > MAX_PLUME_DENSITY THEN
    tPlumeFilter(IN := TRUE, PT := T#3S);
    IF tPlumeFilter.Q THEN
        bPlumeViolationAlarm := TRUE;
    END_IF;
ELSE
    tPlumeFilter(IN := FALSE);
    bPlumeViolationAlarm := FALSE;
END_IF;

(* === HARVESTING STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & SELF-TEST *)
        bSystemReady := TRUE;
        bActiveHarvesting := FALSE;
        rLiftPumpSpeed_RPM := 0.0;
        rCoandaValvePosition := 0.0;

        IF bEnable AND NOT bPlumeViolationAlarm AND NOT bUmbilicalTensionAlarm THEN
            iState := 10;
        END_IF;

    10: (* HYDRAULIC STARTUP SEQUENCE *)
        bSystemReady := FALSE;
        tStartupDelay(IN := TRUE, PT := T#10S);

        (* Ramp up Coanda suction valve gradually *)
        IF rCoandaValvePosition < 50.0 THEN
            rCoandaValvePosition := rCoandaValvePosition + 0.1;
        END_IF;

        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 20;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    20: (* ACTIVE HARVESTING *)
        bActiveHarvesting := TRUE;

        (* Dynamic lift pump control based on depth and mass flow *)
        (* Deep water requires higher base RPM to overcome head *)
        IF rAmbientDepth_m > 5000.0 THEN
            rLiftPumpSpeed_RPM := 3500.0 + (rNoduleMassFlow_kg_s * 10.0);
        ELSE
            rLiftPumpSpeed_RPM := 2500.0 + (rNoduleMassFlow_kg_s * 12.0);
        END_IF;

        (* Fully open suction head *)
        rCoandaValvePosition := 100.0;

        (* Abort conditions *)
        IF NOT bEnable OR bPlumeViolationAlarm OR bUmbilicalTensionAlarm THEN
            iState := 30;
        END_IF;

    30: (* CONTROLLED SHUTDOWN / FLUSHING *)
        bActiveHarvesting := FALSE;

        (* Keep pump running briefly to flush lines of nodules *)
        tStartupDelay(IN := TRUE, PT := T#15S);
        rCoandaValvePosition := 0.0; (* Close intake *)

        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            iState := 0;
        END_IF;

    ELSE
        (* Failsafe default *)
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
```

