FUNCTION_BLOCK FB_Incinerator_Reasoning
VAR_INPUT
    SCADA_Write_Req : BOOL;
    SCADA_Role_ID : INT;
    Primary_PLC_Active : BOOL;
    Heartbeat_Partner : BOOL;
    Temp_Furnace : REAL;
    SO2_Emissions : REAL;
END_VAR
VAR_OUTPUT
    Grate_Speed : REAL;
    Scrubber_Lime_Dosing : REAL;
    Is_Active_PLC : BOOL;
    Security_Alarm : BOOL;
END_VAR
VAR
    Heartbeat_Timer : TON;
    Local_Grate_SP : REAL := 950.0;
END_VAR

// Redundancy Failover Logic (High Availability)
Heartbeat_Timer(IN := NOT Heartbeat_Partner, PT := T#2S);
IF Primary_PLC_Active OR Heartbeat_Timer.Q THEN
    Is_Active_PLC := TRUE;
ELSE
    Is_Active_PLC := FALSE;
END_IF;

// IEC 62443 Role-based Access for SCADA writes
IF SCADA_Write_Req THEN
    IF SCADA_Role_ID = 5 THEN // Role 5 = Authorized Operator
        Local_Grate_SP := 980.0; // SCADA override accepted
        Security_Alarm := FALSE;
    ELSE
        Security_Alarm := TRUE; // Unauthorized access attempt
    END_IF;
END_IF;

// Control execution only if this PLC is active
IF Is_Active_PLC THEN
    Grate_Speed := Local_Grate_SP / 10.0;
    Scrubber_Lime_Dosing := SO2_Emissions * 2.0;
ELSE
    Grate_Speed := 0.0;
    Scrubber_Lime_Dosing := 0.0;
END_IF;

END_FUNCTION_BLOCK
**Explanation:**
The state transition logic utilizes a `Heartbeat_Timer` from the partner PLC. If the primary PLC fails or the heartbeat is lost for 2 seconds, the secondary PLC transitions to the `Is_Active_PLC = TRUE` state, instantly taking over the control outputs without process interruption, ensuring high availability.
