FUNCTION_BLOCK FB_MoltenSaltTES_Manager
TITLE = 'Molten Salt Thermal Energy Storage Management System'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Architect'

VAR_INPUT
    bEnableSystem       : BOOL;   // System global enable
    rHotTankLevel       : REAL;   // Hot salt tank level (%)
    rHotTankTemp        : REAL;   // Hot salt tank temperature (C)
    rColdTankLevel      : REAL;   // Cold salt tank level (%)
    rColdTankTemp       : REAL;   // Cold salt tank temperature (C)
    rHeatExchOilTempIn  : REAL;   // Synthetic oil temp in from solar field (C)
    rHeatExchOilTempOut : REAL;   // Synthetic oil temp out to solar field (C)
    rHeatExchSaltTempIn : REAL;   // Salt temp in from cold tank (C)
    rHeatExchSaltTempOut: REAL;   // Salt temp out to hot tank (C)
    rTraceHeaterTemp    : REAL;   // Trace heating temperature along pipes (C)
    bGridDemandHigh     : BOOL;   // Signal from grid dispatcher for discharge
END_VAR

VAR_OUTPUT
    bPumpColdToHot      : BOOL;   // Start variable frequency drive for cold to hot transfer
    rPumpColdToHotSpeed : REAL;   // Speed reference for cold to hot pump (0-100%)
    bPumpHotToCold      : BOOL;   // Start variable frequency drive for hot to cold transfer (discharge)
    rPumpHotToColdSpeed : REAL;   // Speed reference for hot to cold pump (0-100%)
    bTraceHeatersOn     : BOOL;   // Activate trace heating to prevent salt freezing
    bEmergencyDrain     : BOOL;   // Open gravity drain valves in case of critical failure
    bSystemReady        : BOOL;   // System is nominal and ready for operation
    iAlarmCode          : INT;    // Alarm state code
END_VAR

VAR
    TmrTraceHeating     : TON;    // Timer to prevent rapid cycling of trace heaters
    TmrPumpSpinUp       : TON;    // Timer for pump spin up monitoring
    rTargetHotSaltTemp  : REAL := 565.0; // Nominal hot tank temp
    rFreezeThreshold    : REAL := 290.0; // Critical salt freeze point (Nitrate salts)
    rTraceTargetTemp    : REAL := 300.0; // Trace heating setpoint
    bChargeMode         : BOOL;
    bDischargeMode      : BOOL;
    rErrorOilTemp       : REAL;
END_VAR

// 1. Trace Heating (Freeze Protection)
// Nitrate salts freeze around 220-240C, keep trace heating well above.
IF (rTraceHeaterTemp < rFreezeThreshold) OR (rColdTankTemp < rFreezeThreshold) OR (rHotTankTemp < rFreezeThreshold) THEN
    TmrTraceHeating(IN:= TRUE, PT:= T#5S);
    IF TmrTraceHeating.Q THEN
        bTraceHeatersOn := TRUE;
    END_IF;
ELSIF (rTraceHeaterTemp > rTraceTargetTemp) AND (rColdTankTemp > rTraceTargetTemp) THEN
    TmrTraceHeating(IN:= FALSE);
    bTraceHeatersOn := FALSE;
END_IF;

// 2. Alarm and Emergency Management
iAlarmCode := 0;
IF rHotTankTemp > 580.0 THEN 
    iAlarmCode := 1; // High Temp Limit
END_IF;
IF rColdTankLevel < 5.0 AND bChargeMode THEN
    iAlarmCode := 2; // Cold Tank Low Level
END_IF;
IF (rHotTankTemp < rFreezeThreshold) OR (rColdTankTemp < rFreezeThreshold) THEN
    iAlarmCode := 3; // Impending freeze
    bEmergencyDrain := TRUE; // Gravity drain to sump to save pipes
ELSE
    bEmergencyDrain := FALSE;
END_IF;

// 3. Operational Modes
IF bEnableSystem AND (iAlarmCode = 0) AND NOT bEmergencyDrain THEN
    bSystemReady := TRUE;

    // Determine Modes
    bChargeMode := (rHeatExchOilTempIn > 500.0) AND (rHotTankLevel < 95.0) AND NOT bGridDemandHigh;
    bDischargeMode := bGridDemandHigh AND (rHotTankLevel > 10.0);

    // Charge Mode: Pump cold salt through heat exchanger to hot tank
    IF bChargeMode THEN
        bPumpColdToHot := TRUE;
        rErrorOilTemp := rHeatExchOilTempIn - rHeatExchSaltTempOut;
        // Simple Proportional control for pump speed
        rPumpColdToHotSpeed := 50.0 + (rErrorOilTemp * 0.5); 
        IF rPumpColdToHotSpeed > 100.0 THEN rPumpColdToHotSpeed := 100.0; END_IF;
        IF rPumpColdToHotSpeed < 20.0 THEN rPumpColdToHotSpeed := 20.0; END_IF; // Min flow
        bPumpHotToCold := FALSE;
        rPumpHotToColdSpeed := 0.0;

    // Discharge Mode: Pump hot salt through steam generator to cold tank
    ELSIF bDischargeMode THEN
        bPumpHotToCold := TRUE;
        rPumpHotToColdSpeed := 80.0; // Base load discharge rate
        bPumpColdToHot := FALSE;
        rPumpColdToHotSpeed := 0.0;
    ELSE
        // Standby
        bPumpColdToHot := FALSE;
        rPumpColdToHotSpeed := 0.0;
        bPumpHotToCold := FALSE;
        rPumpHotToColdSpeed := 0.0;
    END_IF;
ELSE
    bSystemReady := FALSE;
    bPumpColdToHot := FALSE;
    bPumpHotToCold := FALSE;
    rPumpColdToHotSpeed := 0.0;
    rPumpHotToColdSpeed := 0.0;
END_IF;

END_FUNCTION_BLOCK
