FUNCTION_BLOCK FB_DeepSpaceInterferometerDelayLine
VAR_INPUT
    (* Deep-Space Optical Interferometer Delay Line Inputs *)
    bSystemEnable           : BOOL;     (* Main enable signal for the delay line system *)
    bEmergencyStop          : BOOL;     (* Safety interlock / Emergency Stop (Active High OK) *)
    rLaserMetrologyPos      : LREAL;    (* Absolute position from HeNe laser metrology [meters] *)
    rThermalExpansionSensor : REAL;     (* Precision thermal sensor near the optical bench [deg C] *)
    rTargetDelayDistance    : LREAL;    (* Requested optical delay path length [meters] *)
    rPiezoTipTiltX_Error    : REAL;     (* X-axis wavefront tilt error from quad-cell [urad] *)
    rPiezoTipTiltY_Error    : REAL;     (* Y-axis wavefront tilt error from quad-cell [urad] *)
    bJitterCancelEnable     : BOOL;     (* Enable active vibration/jitter cancellation *)
END_VAR
VAR_OUTPUT
    (* Control outputs to actuators and system status *)
    bSystemReady            : BOOL;     (* Indicates control loops are locked and stable *)
    rVoiceCoilCommand       : REAL;     (* Macroscopic translation command [Volts or Amps] *)
    rPiezoTipTiltX_Cmd      : REAL;     (* High-bandwidth X-axis correction command [Volts] *)
    rPiezoTipTiltY_Cmd      : REAL;     (* High-bandwidth Y-axis correction command [Volts] *)
    bMetrologyAlarm         : BOOL;     (* Indicates loss of lock or metrology failure *)
    rCurrentDelayError      : LREAL;    (* Calculated residual error [meters] *)
END_VAR
VAR
    (* Internal state and control variables *)
    iState                  : INT := 0;
    tStabilizationTimer     : TON;
    rPosErrorPrevious       : LREAL := 0.0;
    rPosErrorIntegral       : LREAL := 0.0;

    (* PID Gains for Voice Coil *)
    kp_VC                   : REAL := 25000.0;
    ki_VC                   : REAL := 150.0;
    kd_VC                   : REAL := 8000.0;

    (* Environmental Constants *)
    rThermalCoeffInvar      : LREAL := 1.2e-6; (* Thermal expansion coefficient of Invar [1/K] *)
    rRefTemp                : REAL := 20.0;    (* Reference temperature [deg C] *)

    (* Intermediate calculations *)
    rThermalCorrection      : LREAL;
    rAdjustedTarget         : LREAL;
    rPosError               : LREAL;
    rDerivative             : LREAL;
END_VAR

(* === MAIN LOGIC === *)
(* Handle emergency and safety stops immediately *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bMetrologyAlarm := TRUE;
    rVoiceCoilCommand := 0.0;
    rPiezoTipTiltX_Cmd := 0.0;
    rPiezoTipTiltY_Cmd := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* Continuous calculation of thermal compensation *)
rThermalCorrection := (rThermalExpansionSensor - rRefTemp) * rThermalCoeffInvar * rTargetDelayDistance;
rAdjustedTarget := rTargetDelayDistance + rThermalCorrection;

(* Main State Machine *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        rVoiceCoilCommand := 0.0;
        rPiezoTipTiltX_Cmd := 0.0;
        rPiezoTipTiltY_Cmd := 0.0;
        bMetrologyAlarm := FALSE;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* COARSE POSITIONING (VOICE COIL) *)
        rPosError := rAdjustedTarget - rLaserMetrologyPos;
        rCurrentDelayError := rPosError;

        (* PID Control for macroscopic adjustment *)
        rPosErrorIntegral := rPosErrorIntegral + (rPosError * 0.001); (* Assuming 1ms cycle *)
        rDerivative := (rPosError - rPosErrorPrevious) / 0.001;
        rVoiceCoilCommand := (kp_VC * LREAL_TO_REAL(rPosError)) + 
                             (ki_VC * LREAL_TO_REAL(rPosErrorIntegral)) + 
                             (kd_VC * LREAL_TO_REAL(rDerivative));

        rPosErrorPrevious := rPosError;

        (* Check if coarse position is within 1 um *)
        IF ABS(rPosError) < 1.0e-6 THEN
            tStabilizationTimer(IN := TRUE, PT := T#2S);
            IF tStabilizationTimer.Q THEN
                tStabilizationTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tStabilizationTimer(IN := FALSE);
        END_IF;

    20: (* FINE LOCK & JITTER CANCELLATION (PIEZO) *)
        rPosError := rAdjustedTarget - rLaserMetrologyPos;
        rCurrentDelayError := rPosError;

        (* Maintain Voice Coil PID at lower gain or steady state here if needed, keeping simple *)
        rVoiceCoilCommand := (kp_VC * LREAL_TO_REAL(rPosError)); 

        IF bJitterCancelEnable THEN
            (* Fast Piezo Tip-Tilt correction *)
            rPiezoTipTiltX_Cmd := rPiezoTipTiltX_Error * 0.85; (* Proportional high-bandwidth gain *)
            rPiezoTipTiltY_Cmd := rPiezoTipTiltY_Error * 0.85;
        ELSE
            rPiezoTipTiltX_Cmd := 0.0;
            rPiezoTipTiltY_Cmd := 0.0;
        END_IF;

        (* System is fully ready and locked *)
        bSystemReady := TRUE;

        (* Loss of lock condition - error exceeds 5 um *)
        IF ABS(rPosError) > 5.0e-6 THEN
            bSystemReady := FALSE;
            bMetrologyAlarm := TRUE;
            iState := 10; (* Fall back to coarse positioning *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
