FUNCTION_BLOCK "FlotationCell_M2"
VERSION : 0.1
   VAR_INPUT 
      StartCmd : Bool;
      Level_SP : Real; 
      Dosing_SP : Real;
      Agitator_Speed_SP : Real;
      PN_Inputs : "UDT_Flotation_PN_In";
   END_VAR

   VAR_OUTPUT 
      Valve_CV : Real; 
      DosingPump_Cmd : Bool; 
      DosingPump_Speed : Real;
      PN_Outputs : "UDT_Flotation_PN_Out";
      Fault_SensorWireBreak : Bool;
      Fault_VFDComms : Bool;
      Alarm_LowLevel : Bool;
      Alarm_Overload : Bool;
   END_VAR

   VAR 
      instPID : "PID_Compact"; 
      Level_PV : Real;
      Torque_PV : Real;
      Running : Bool;
   END_VAR

   VAR_CONSTANT
      MIN_LEVEL_AGITATOR : Real := 15.0;
      MAX_TORQUE_LIMIT : Real := 90.0;
   END_VAR

BEGIN
    // Diagnostics & Signal Scaling
    #Fault_SensorWireBreak := (#PN_Inputs.Raw_Ultrasonic < 0) OR (#PN_Inputs.Raw_Ultrasonic > 27648);
    #Fault_VFDComms := NOT #PN_Inputs.PN_Comm_Status;

    // Scale Analog Input (0-27648 to 0-100%)
    IF NOT #Fault_SensorWireBreak THEN
        #Level_PV := INT_TO_REAL(#PN_Inputs.Raw_Ultrasonic) / 276.48;
    ELSE
        #Level_PV := 0.0; // Failsafe
    END_IF;

    // Scale Torque (assuming 0-16384 is 0-100%)
    #Torque_PV := INT_TO_REAL(#PN_Inputs.ActualTorque_VFD) / 163.84;

    // Safety Interlocks
    #Alarm_LowLevel := (#Level_PV < #MIN_LEVEL_AGITATOR);
    #Alarm_Overload := (#Torque_PV > #MAX_TORQUE_LIMIT);

    // Main state
    IF #StartCmd AND NOT #Alarm_LowLevel AND NOT #Alarm_Overload AND NOT #Fault_SensorWireBreak AND NOT #Fault_VFDComms THEN
        #Running := TRUE;
    ELSE
        #Running := FALSE;
    END_IF;

    // Froth Level PID
    #instPID(Setpoint := #Level_SP,
             Input := #Level_PV,
             ManualEnable := NOT #Running,
             ManualValue := 0.0,
             Output => #Valve_CV);

    // Reagent Dosing
    IF #Running THEN
        #DosingPump_Cmd := TRUE;
        #DosingPump_Speed := #Dosing_SP; 
    ELSE
        #DosingPump_Cmd := FALSE;
        #DosingPump_Speed := 0.0;
    END_IF;

    // Agitator PROFINET VFD Control
    IF #Running THEN
        #PN_Outputs.ControlWord_VFD := 16#047F; // Typical Siemens Drive ON command
        #PN_Outputs.SpeedSetpoint_VFD := REAL_TO_INT(#Agitator_Speed_SP * 163.84);
    ELSE
        #PN_Outputs.ControlWord_VFD := 16#047E; // OFF1
        #PN_Outputs.SpeedSetpoint_VFD := 0;
    END_IF;

END_FUNCTION_BLOCK
