FUNCTION_BLOCK "FlotationCell_M4"
VERSION : 0.1
   VAR_INPUT 
      PN_Raw_Ultrasonic_A : Int; 
      PN_Raw_Ultrasonic_B : Int; 
      SCADA_Role : Int;
      Cmd_SelfTest : Bool;
      HIL : "UDT_HIL_DigitalTwin";
