      Level_A_PV, Level_B_PV, Active_Level_PV : Real;
      Drift_Deviation : Real;
      SelfTest_Timer : TON_TIME;
      SelfTest_Step : Int;
   END_VAR
   VAR_CONSTANT
      MAX_DRIFT_TOLERANCE : Real := 5.0; // 5% drift tolerance
   END_VAR

BEGIN
    // 1. Process Raw Inputs
    #Level_A_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_A) / 276.48;
    #Level_B_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_B) / 276.48;

    // 2. Statistical Sensor Drift Detection
    #Drift_Deviation := ABS(#Level_A_PV - #Level_B_PV);
    IF (#Drift_Deviation > #MAX_DRIFT_TOLERANCE) THEN
        #Alm_SensorDrift := TRUE;
        // Degrade gracefully: Use lower value to prevent overflow spills
        #Active_Level_PV := MIN(IN1:=#Level_A_PV, IN2:=#Level_B_PV);
    ELSE
        #Alm_SensorDrift := FALSE;
        #Active_Level_PV := (#Level_A_PV + #Level_B_PV) / 2.0; // Average
    END_IF;

    // 3. HIL Digital Twin Synchronization & Adversarial Check
    IF #HIL.HIL_Mode_Active THEN
        IF ABS(#Active_Level_PV - #HIL.Sim_Level_PV) > #HIL.Max_Allowed_Deviation THEN
            // Edge Case: Physical sensor wildly contradicts Digital Twin
            // Trust physical sensors but flag critical mismatch
            #HIL.Alm_TwinMismatch := TRUE;
        ELSE
            #HIL.Alm_TwinMismatch := FALSE;
            // Optionally blend Twin data for noise rejection (Kalman filter style)
            #Active_Level_PV := (#Active_Level_PV * 0.7) + (#HIL.Sim_Level_PV * 0.3);
        END_IF;
    END_IF;

    // 4. Automated Startup Self-Test Routine
    IF #Cmd_SelfTest AND #SysState = 0 THEN
        #SysState := 1; // Enter Self-Test
        #SelfTest_Step := 1;
    END_IF;

    IF #SysState = 1 THEN
        #SelfTest_Timer(IN:=TRUE, PT:=T#5s);
        CASE #SelfTest_Step OF
            1: // Stroke Valve 0-100%
               #Valve_CV := 100.0;
               IF #SelfTest_Timer.Q THEN
                   #SelfTest_Timer(IN:=FALSE);
                   #SelfTest_Step := 2;
               END_IF;
            2: // Check VFD Comms (Mocked logic)
               IF #PN_Raw_Ultrasonic_A >= 0 THEN
                   #SysState := 2; // Transition to RUN
               ELSE
                   #SysState := 99; // Transition to FAULT
               END_IF;
        END_CASE;
    END_IF;

    // 5. Main Control Execution
    IF #SysState = 2 THEN
        #instPID(Setpoint := 50.0, // Hardcoded for snippet
                 Input := #Active_Level_PV,
                 ManualEnable := FALSE,
                 Output => #Valve_CV);
        #Dosing_Run := TRUE;
    ELSIF #SysState <> 1 THEN
        // If not running and not in self-test, safe state
        #Valve_CV := 0.0;
        #Dosing_Run := FALSE;
    END_IF;

END_FUNCTION_BLOCK
