\nFUNCTION_BLOCK FB_DeepSpaceAntennaControl
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    rTargetAzimuth       : REAL; // Target Azimuth in degrees (0.0 to 360.0)
    rTargetElevation     : REAL; // Target Elevation in degrees (0.0 to 90.0)
    rActualAzimuth       : REAL; // Current Azimuth feedback from encoders
    rActualElevation     : REAL; // Current Elevation feedback from encoders
    rWindSpeed           : REAL; // Anemometer reading in m/s
    rWindDirection       : REAL; // Wind direction in degrees
    rLNATemp             : REAL; // Cryogenic Low Noise Amplifier temperature in Kelvin
    bTrackingEnable      : BOOL; // Master enable for tracking
    bCryoCoolerEnable    : BOOL; // Enable cryogenic cooling system
END_VAR

VAR_OUTPUT
    rAzimuthCmdMotor1    : REAL; // Velocity command to Azimuth Motor 1
    rAzimuthCmdMotor2    : REAL; // Velocity command to Azimuth Motor 2 (Anti-backlash)
    rElevationCmdMotor1  : REAL; // Velocity command to Elevation Motor 1
    rElevationCmdMotor2  : REAL; // Velocity command to Elevation Motor 2 (Anti-backlash)
    rCryoCoolerPower     : REAL; // 0-100% cooling power command
    bTrackingInTolerance : BOOL; // True if within 0.005 degrees of target
    bLNA_TempAlarm       : BOOL; // True if LNA temp exceeds operational limit
    bWindStowAlarm       : BOOL; // True if wind speed requires immediate stow
END_VAR

VAR
    // PID States for Azimuth
    rAzError             : REAL;
    rAzErrorPrev         : REAL;
    rAzIntegral          : REAL;
    rAzDerivative        : REAL;

    // PID States for Elevation
    rElError             : REAL;
    rElErrorPrev         : REAL;
    rElIntegral          : REAL;
    rElDerivative        : REAL;

    // Constants
    Kp_Az                : REAL := 15.5;
    Ki_Az                : REAL := 2.1;
    Kd_Az                : REAL := 5.0;

    Kp_El                : REAL := 18.0;
    Ki_El                : REAL := 2.5;
    Kd_El                : REAL := 6.2;

    dt                   : REAL := 0.01; // 10ms cycle time

    // Feedforward and Anti-backlash
    rWindForceAz         : REAL;
    rWindForceEl         : REAL;
    rAntiBacklashBias    : REAL := 2.5; // Constant torque bias for backlash elimination

    // Limits
    rMaxSpeed            : REAL := 10.0; // Max motor speed
    rMaxIntegral         : REAL := 50.0;
END_VAR

// 1. Wind Gust Feedforward Calculation
// Approximate wind load based on speed squared and angle of attack
IF rWindSpeed > 25.0 THEN
    bWindStowAlarm := TRUE; // Critical limit exceeded, enter safe mode
ELSE
    bWindStowAlarm := FALSE;
END_IF;

// Feedforward torque compensation based on wind direction relative to antenna face
rWindForceAz := 0.015 * (rWindSpeed * rWindSpeed) * COS((rWindDirection - rActualAzimuth) * 3.14159 / 180.0);
rWindForceEl := 0.020 * (rWindSpeed * rWindSpeed) * SIN((rWindDirection - rActualAzimuth) * 3.14159 / 180.0) * COS(rActualElevation * 3.14159 / 180.0);

// 2. Cryogenic LNA Thermal Regulation
// Maintain LNA below 15K, optimum is 10K. Simple proportional band.
IF bCryoCoolerEnable THEN
    IF rLNATemp > 18.0 THEN
        bLNA_TempAlarm := TRUE;
        rCryoCoolerPower := 100.0;
    ELSE
        bLNA_TempAlarm := FALSE;
        rCryoCoolerPower := (rLNATemp - 5.0) * 10.0;
        IF rCryoCoolerPower > 100.0 THEN rCryoCoolerPower := 100.0; END_IF;
        IF rCryoCoolerPower < 0.0 THEN rCryoCoolerPower := 0.0; END_IF;
    END_IF;
ELSE
    rCryoCoolerPower := 0.0;
    bLNA_TempAlarm := rLNATemp > 18.0;
END_IF;

// 3. Precision Servo Tracking Logic
IF bTrackingEnable AND NOT bWindStowAlarm THEN
    // Azimuth PID
    rAzError := rTargetAzimuth - rActualAzimuth;
    // Shortest path logic for 360 wrap-around
    IF rAzError > 180.0 THEN rAzError := rAzError - 360.0; END_IF;
    IF rAzError < -180.0 THEN rAzError := rAzError + 360.0; END_IF;

    rAzIntegral := rAzIntegral + (rAzError * dt);
    IF rAzIntegral > rMaxIntegral THEN rAzIntegral := rMaxIntegral; END_IF;
    IF rAzIntegral < -rMaxIntegral THEN rAzIntegral := -rMaxIntegral; END_IF;

    rAzDerivative := (rAzError - rAzErrorPrev) / dt;
    rAzErrorPrev := rAzError;

    // Elevation PID
    rElError := rTargetElevation - rActualElevation;
    rElIntegral := rElIntegral + (rElError * dt);
    IF rElIntegral > rMaxIntegral THEN rElIntegral := rMaxIntegral; END_IF;
    IF rElIntegral < -rMaxIntegral THEN rElIntegral := -rMaxIntegral; END_IF;

    rElDerivative := (rElError - rElErrorPrev) / dt;
    rElErrorPrev := rElError;

    // Command Calculation with Wind Feedforward
    rAzimuthCmdMotor1 := (Kp_Az * rAzError) + (Ki_Az * rAzIntegral) + (Kd_Az * rAzDerivative) + rWindForceAz;
    rElevationCmdMotor1 := (Kp_El * rElError) + (Ki_El * rElIntegral) + (Kd_El * rElDerivative) + rWindForceEl;

    // Clamp Main Motor Commands
    IF rAzimuthCmdMotor1 > rMaxSpeed THEN rAzimuthCmdMotor1 := rMaxSpeed; END_IF;
    IF rAzimuthCmdMotor1 < -rMaxSpeed THEN rAzimuthCmdMotor1 := -rMaxSpeed; END_IF;
    IF rElevationCmdMotor1 > rMaxSpeed THEN rElevationCmdMotor1 := rMaxSpeed; END_IF;
    IF rElevationCmdMotor1 < -rMaxSpeed THEN rElevationCmdMotor1 := -rMaxSpeed; END_IF;

    // Anti-backlash opposing motor commands
    // Motor 2 applies opposing torque by receiving a biased velocity command
    IF rAzimuthCmdMotor1 > 0.0 THEN
        rAzimuthCmdMotor2 := rAzimuthCmdMotor1 - rAntiBacklashBias;
    ELSE
        rAzimuthCmdMotor2 := rAzimuthCmdMotor1 + rAntiBacklashBias;
    END_IF;

    IF rElevationCmdMotor1 > 0.0 THEN
        rElevationCmdMotor2 := rElevationCmdMotor1 - rAntiBacklashBias;
    ELSE
        rElevationCmdMotor2 := rElevationCmdMotor1 + rAntiBacklashBias;
    END_IF;

    // Tracking Tolerance Check
    bTrackingInTolerance := (ABS(rAzError) < 0.005) AND (ABS(rElError) < 0.005);
ELSE
    // Safe state or idle
    rAzimuthCmdMotor1 := 0.0;
    rAzimuthCmdMotor2 := 0.0;
    rElevationCmdMotor1 := 0.0;
    rElevationCmdMotor2 := 0.0;
    rAzIntegral := 0.0;
    rElIntegral := 0.0;
    bTrackingInTolerance := FALSE;
END_IF;
END_FUNCTION_BLOCK\n```
