FUNCTION_BLOCK FB_TandemMixer_BanburyExtruder
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (FALSE = ESTOP) *)
    rRotorSpeed_RPM         : REAL;     (* Feedback speed of the main Banbury rotors in RPM *)
    rRamPressure_Bar        : REAL;     (* Feedback pressure of the hydraulic ram in Bar *)
    rPolymerTemp_C          : REAL;     (* Real-time internal polymer temperature measurement in deg C *)
    rMotorPower_kW          : REAL;     (* Main drive motor power consumption in kW *)
    bDropDoorClosed         : BOOL;     (* Status switch indicating drop door is securely closed and locked *)
    bCarbonBlackBatchRdy    : BOOL;     (* Signal indicating upstream carbon black and silica batch is weighed and ready *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* System ready status for upstream handshaking *)
    rControlRotorSpeed_RPM  : REAL;     (* Control signal to VFD for main rotor speed in RPM *)
    rControlRamPressure_Bar : REAL;     (* Control signal to hydraulic proportional valve for ram pressure in Bar *)
    bAlarm                  : BOOL;     (* Global fault alarm output *)
    bOpenDropDoor           : BOOL;     (* Command to open drop door and drop batch to extruder *)
    rSpecificEnergy_kWh_kg  : REAL;     (* Calculated specific energy of current batch *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tMixTimer               : TON;
    tDropTimer              : TON;
    rAccumulatedEnergy      : REAL := 0.0;
    rBatchWeight_kg         : REAL := 250.0; (* Assumed batch weight for calculation *)
    rCycleTime_Sec          : REAL := 0.1;   (* Task cycle time (100ms) *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rControlRotorSpeed_RPM := 0.0;
    rControlRamPressure_Bar := 0.0;
    bOpenDropDoor := FALSE;
    iState := 0;
    RETURN;
END_IF;

(* Specific Energy Calculation integration continuously when mixing *)
IF iState >= 20 AND iState < 50 THEN
    (* Power integration logic to track specific energy input *)
    rAccumulatedEnergy := rAccumulatedEnergy + (rMotorPower_kW * (rCycleTime_Sec / 3600.0));
    rSpecificEnergy_kWh_kg := rAccumulatedEnergy / rBatchWeight_kg;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rControlRotorSpeed_RPM := 0.0;
        rControlRamPressure_Bar := 0.0;
        bOpenDropDoor := FALSE;
        rAccumulatedEnergy := 0.0;
        rSpecificEnergy_kWh_kg := 0.0;

        IF bEnable AND bDropDoorClosed AND bCarbonBlackBatchRdy THEN
            iState := 10;
        END_IF;

    10: (* LOAD INGREDIENTS *)
        bSystemReady := FALSE;
        rControlRotorSpeed_RPM := 10.0; (* Slow rotate for initial dry loading *)
        rControlRamPressure_Bar := 2.0; (* Light ram pressure to push down materials *)

        tMixTimer(IN := TRUE, PT := T#15S); (* Wait for ingredient loading *)
        IF tMixTimer.Q THEN
            tMixTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* MIXING - STAGE 1: DISPERSION *)
        rControlRotorSpeed_RPM := 45.0; (* High speed for silica/carbon black dispersion *)
        rControlRamPressure_Bar := 6.0; (* High ram pressure to force agglomerates down *)

        (* Transition based on critical specific energy threshold and temperature limits *)
        IF rSpecificEnergy_kWh_kg > 0.15 AND rPolymerTemp_C > 110.0 THEN
            iState := 30;
        END_IF;

    30: (* MIXING - STAGE 2: DISTRIBUTION *)
        rControlRotorSpeed_RPM := 30.0; (* Reduce speed to mitigate shear heating *)
        rControlRamPressure_Bar := 4.5;

        (* Transition when final specific energy is reached or if overheat imminent *)
        IF rSpecificEnergy_kWh_kg > 0.28 OR rPolymerTemp_C > 145.0 THEN
            iState := 40;
        END_IF;

    40: (* SWEEP AND COOL / RAM CYCLE *)
        rControlRotorSpeed_RPM := 15.0;
        rControlRamPressure_Bar := 0.5; (* Ram up sweep *)

        (* Ensure polymer temperature drops before dropping to the tandem extruder *)
        IF rPolymerTemp_C < 135.0 THEN
            iState := 50;
        END_IF;

    50: (* DROP BATCH TO TANDEM EXTRUDER *)
        rControlRotorSpeed_RPM := 5.0;
        bOpenDropDoor := TRUE;

        tDropTimer(IN := TRUE, PT := T#10S); (* Allow 10 seconds for complete drop *)
        IF tDropTimer.Q THEN
            tDropTimer(IN := FALSE);
            bOpenDropDoor := FALSE;
            iState := 60;
        END_IF;

    60: (* COMPLETE / RESET *)
        IF bDropDoorClosed THEN
            IF NOT bEnable THEN
                iState := 0;
            END_IF;
        END_IF;

    ELSE
        iState := 0;
        bAlarm := TRUE;
END_CASE;

END_FUNCTION_BLOCK
`
