\nFUNCTION_BLOCK FB_CapsuleFills_HighSpeed
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // Enable capsule filling process
    bEmergencyStop : BOOL; // E-Stop active low
    rMachineSpeed_Cpm : REAL; // Target machine speed in capsules per minute
    rTargetWeight_mg : REAL; // Target dose weight in milligrams
    bTampingPinHome : BOOL;
    bDosingDiskHome : BOOL;
    rActualWeight_mg : REAL; // Weight feedback from check weigher
    bCheckWeigherReady : BOOL;
END_VAR
VAR_OUTPUT
    bReadyToRun : BOOL;
    bRunning : BOOL;
    bFault : BOOL;
    rTampingPressure_bar : REAL; // Output to tamping pressure regulator
    rDosingDiskVelocity_rpm : REAL;
    bRejectCapsule : BOOL;
    nGoodCapsules : DINT;
    nRejectedCapsules : DINT;
    sStatusMessage : STRING(50);
END_VAR
VAR
    State : INT := 0;
    rWeightDeviation : REAL;
    rIntegralError : REAL := 0.0;
    rKp : REAL := 0.15;
    rKi : REAL := 0.05;
    rMaxTampingPressure : REAL := 10.0; // Bar
    rMinTampingPressure : REAL := 1.5; // Bar
    nCycleCounter : DINT := 0;
    rCalculatedPressure : REAL;
    rMovingAverageWeight : REAL;
    WeightBuffer : ARRAY[0..9] OF REAL;
    nBufferIndex : INT := 0;
    i : INT;
    rSumWeight : REAL;
END_VAR

// Main logic
IF bEmergencyStop THEN
    State := 99; // Fault state
END_IF;

CASE State OF
    0: // Init
        bReadyToRun := FALSE;
        bRunning := FALSE;
        bFault := FALSE;
        rTampingPressure_bar := 0.0;
        rDosingDiskVelocity_rpm := 0.0;
        nGoodCapsules := 0;
        nRejectedCapsules := 0;
        IF bEnable AND NOT bEmergencyStop THEN
            State := 10;
        END_IF;
        sStatusMessage := 'Initialization complete';

    10: // Homing
        bReadyToRun := FALSE;
        sStatusMessage := 'Homing axes...';
        // Homing sequence simulation
        IF bTampingPinHome AND bDosingDiskHome THEN
            State := 20;
        END_IF;

    20: // Ready
        bReadyToRun := TRUE;
        sStatusMessage := 'Ready to start production';
        IF bEnable AND rMachineSpeed_Cpm > 0.0 THEN
            State := 30;
        ELSIF NOT bEnable THEN
            State := 0;
        END_IF;

    30: // Running
        bReadyToRun := TRUE;
        bRunning := TRUE;
        sStatusMessage := 'Production active';

        // Calculate machine speed
        rDosingDiskVelocity_rpm := rMachineSpeed_Cpm / 12.0; // Assuming 12 stations per revolution

        // Process weight feedback
        IF bCheckWeigherReady AND rActualWeight_mg > 0.0 THEN
            // Store in circular buffer
            WeightBuffer[nBufferIndex] := rActualWeight_mg;
            nBufferIndex := (nBufferIndex + 1) MOD 10;

            // Calculate Moving Average
            rSumWeight := 0.0;
            FOR i := 0 TO 9 DO
                IF WeightBuffer[i] > 0.0 THEN
                    rSumWeight := rSumWeight + WeightBuffer[i];
                END_IF;
            END_FOR;
            rMovingAverageWeight := rSumWeight / 10.0;

            // PI Controller for Tamping Pressure
            rWeightDeviation := rTargetWeight_mg - rMovingAverageWeight;
            rIntegralError := rIntegralError + rWeightDeviation;

            // Anti-windup
            IF rIntegralError > 50.0 THEN rIntegralError := 50.0; END_IF;
            IF rIntegralError < -50.0 THEN rIntegralError := -50.0; END_IF;

            rCalculatedPressure := (rKp * rWeightDeviation) + (rKi * rIntegralError);

            // Offset logic - higher pressure means denser plug, higher weight
            rTampingPressure_bar := rTampingPressure_bar + rCalculatedPressure;

            // Limits
            IF rTampingPressure_bar > rMaxTampingPressure THEN
                rTampingPressure_bar := rMaxTampingPressure;
            ELSIF rTampingPressure_bar < rMinTampingPressure THEN
                rTampingPressure_bar := rMinTampingPressure;
            END_IF;

            // Reject logic
            IF ABS(rTargetWeight_mg - rActualWeight_mg) > (rTargetWeight_mg * 0.05) THEN // 5% tolerance
                bRejectCapsule := TRUE;
                nRejectedCapsules := nRejectedCapsules + 1;
            ELSE
                bRejectCapsule := FALSE;
                nGoodCapsules := nGoodCapsules + 1;
            END_IF;
        END_IF;

        IF NOT bEnable THEN
            State := 20;
            bRunning := FALSE;
            rDosingDiskVelocity_rpm := 0.0;
        END_IF;

    99: // Fault
        bReadyToRun := FALSE;
        bRunning := FALSE;
        bFault := TRUE;
        rTampingPressure_bar := 0.0;
        rDosingDiskVelocity_rpm := 0.0;
        sStatusMessage := 'EMERGENCY STOP ACTIVATED';

        IF NOT bEmergencyStop AND bEnable THEN // Reset condition
            State := 0;
        END_IF;

END_CASE;
