    Target_TCP_Y            : LREAL; // Commanded TCP Y
    Target_TCP_Z            : LREAL; // Commanded TCP Z
    Target_TCP_A            : LREAL; // Commanded TCP A
    Target_TCP_C            : LREAL; // Commanded TCP C
    Coolant_Pressure_SP     : LREAL; // Setpoint bar
END_VAR

VAR_OUTPUT
    Axis_X_Cmd_Pos          : LREAL; // Compensated X command
    Axis_Y_Cmd_Pos          : LREAL; // Compensated Y command
    Axis_Z_Cmd_Pos          : LREAL; // Compensated Z command
    Axis_A_Cmd_Pos          : LREAL; // A command
    Axis_C_Cmd_Pos          : LREAL; // C command
    Coolant_Pump_Speed      : LREAL; // 0-100%
    Coolant_Valve_Open      : BOOL;
    Thermal_Comp_Z          : LREAL; // Applied Z compensation
    TCP_Active              : BOOL;
    System_Ready            : BOOL;
    Error_ID                : DWORD;
END_VAR

VAR
    // Internal variables
    Pivot_Length            : LREAL := 150.0; // Distance from pivot to spindle nose
    Thermal_Coefficient     : LREAL := 0.012; // um/degC thermal growth
    Temp_Delta_Front        : LREAL;
    Temp_Delta_Rear         : LREAL;
    Avg_Temp_Delta          : LREAL;
    Thermal_Growth          : LREAL;
    Rad_A                   : LREAL;
    Rad_C                   : LREAL;
    Cos_A                   : LREAL;
    Sin_A                   : LREAL;
    Cos_C                   : LREAL;
    Sin_C                   : LREAL;
    Tool_Vector_X           : LREAL;
    Tool_Vector_Y           : LREAL;
    Tool_Vector_Z           : LREAL;
    PID_Error               : LREAL;
    PID_Integral            : LREAL;
    Kp                      : LREAL := 2.5;
    Ki                      : LREAL := 0.1;
END_VAR

// Implementation
IF NOT Enable_System THEN
    System_Ready := FALSE;
    TCP_Active := FALSE;
    Coolant_Pump_Speed := 0.0;
    Coolant_Valve_Open := FALSE;
    Error_ID := 16#0000;
    RETURN;
END_IF;

System_Ready := TRUE;

// 1. Spindle Thermal Expansion Mapping
// Assuming reference temperature is 20.0 C
Temp_Delta_Front := Spindle_Temp_Front - 20.0;
Temp_Delta_Rear  := Spindle_Temp_Rear - 20.0;

// Linear thermal gradient estimation
Avg_Temp_Delta := (Temp_Delta_Front * 0.7) + (Temp_Delta_Rear * 0.3);

// Calculate Z-axis growth (Thermal_Coefficient is um/degC, convert to mm)
Thermal_Growth := (Avg_Temp_Delta * Thermal_Coefficient * Pivot_Length) / 1000.0;
Thermal_Comp_Z := Thermal_Growth;

// 2. Tool Center Point (TCP) Kinematics Compensation
// Convert angles to radians
Rad_A := Target_TCP_A * 3.14159265359 / 180.0;
Rad_C := Target_TCP_C * 3.14159265359 / 180.0;

Cos_A := COS(Rad_A);
Sin_A := SIN(Rad_A);
Cos_C := COS(Rad_C);
Sin_C := SIN(Rad_C);

// Calculate effective tool length from pivot point
// Tool vector calculation for Head-Table or Table-Table kinematics
// Assuming standard Trunnion table (Table-Table A and C)
Tool_Vector_X := 0.0; // Simplified for pure Z tool axis initially
Tool_Vector_Y := (Tool_Length + Pivot_Length) * Sin_A;
Tool_Vector_Z := (Tool_Length + Pivot_Length) * Cos_A;

// Apply inverse kinematics to get physical axis commands
Axis_X_Cmd_Pos := Target_TCP_X * Cos_C - Target_TCP_Y * Sin_C;
Axis_Y_Cmd_Pos := Target_TCP_X * Sin_C + Target_TCP_Y * Cos_C - Tool_Vector_Y;

// Apply thermal compensation to Z
Axis_Z_Cmd_Pos := Target_TCP_Z - Tool_Vector_Z - Thermal_Comp_Z;

Axis_A_Cmd_Pos := Target_TCP_A;
Axis_C_Cmd_Pos := Target_TCP_C;

TCP_Active := TRUE;

// 3. Active Cutting Fluid Delivery (PID Control)
// High pressure coolant based on setpoint
IF Spindle_RPM_Actual > 500.0 AND Machine_Mode = 2 THEN
    PID_Error := Coolant_Pressure_SP - (Coolant_Pump_Speed * 0.5); // Mock feedback
    PID_Integral := PID_Integral + PID_Error * 0.01;

    // Anti-windup
    IF PID_Integral > 100.0 THEN PID_Integral := 100.0; END_IF;
    IF PID_Integral < 0.0 THEN PID_Integral := 0.0; END_IF;

    Coolant_Pump_Speed := (Kp * PID_Error) + (Ki * PID_Integral);

    IF Coolant_Pump_Speed > 100.0 THEN
        Coolant_Pump_Speed := 100.0;
    ELSIF Coolant_Pump_Speed < 0.0 THEN
        Coolant_Pump_Speed := 0.0;
    END_IF;

    Coolant_Valve_Open := TRUE;
ELSE
    Coolant_Pump_Speed := 0.0;
    Coolant_Valve_Open := FALSE;
    PID_Integral := 0.0;
END_IF;

// Error Handling
IF Spindle_Temp_Front > 90.0 THEN
    Error_ID := 16#F001; // Over-temperature fault
    System_Ready := FALSE;
END_IF;

END_FUNCTION_BLOCK
