FUNCTION_BLOCK FB_ContinuousChipFryer_AdvancedCtrl
TITLE = 'Advanced Control for Continuous Potato Chip Fryer'
VERSION : '1.1'

VAR_INPUT
    // Physical I/O - Sensors
    rTemp_Oil_Inlet         : REAL; (* Deg C *)
    rTemp_Oil_Zone1         : REAL; (* Deg C *)
    rTemp_Oil_Zone2         : REAL; (* Deg C *)
    rTemp_Oil_Zone3         : REAL; (* Deg C *)
    rThermalFluid_Temp      : REAL; (* Deg C *)
    rOil_Level              : REAL; (* mm *)
    rChipFeed_MassFlow      : REAL; (* kg/hr *)
    rPaddleWheel_ActSpeed   : REAL; (* RPM *)
    rCentrifuge_ActSpeed    : REAL; (* RPM *)
    bSystemEnable           : BOOL;
    bEmergencyStop          : BOOL;

    // Setpoints
    rTemp_SP_Zone1          : REAL := 185.0;
    rTemp_SP_Zone2          : REAL := 180.0;
    rTemp_SP_Zone3          : REAL := 175.0;
    rTransitTime_SP         : REAL := 180.0; (* seconds *)
    rCentrifugeSpeed_SP     : REAL := 1200.0; (* RPM *)
END_VAR

VAR_OUTPUT
    // Physical I/O - Actuators
    rThermalValve_Cmd       : REAL; (* 0-100% *)
    rPaddleWheel_SpdCmd     : REAL; (* 0-100% *)
    rCentrifuge_SpdCmd      : REAL; (* 0-100% *)
    bMakeupOil_Pump         : BOOL;
    bAlarm_TempHigh         : BOOL;
    bAlarm_TransitDeviation : BOOL;
    bSystemReady            : BOOL;
END_VAR

VAR
    // Internal Variables & Function Blocks
    fbPID_CascadeMaster     : PID_Compact;
    fbPID_CascadeSlave      : PID_Compact;
    fbPID_PaddleSpeed       : PID_Compact;
    fbPID_Centrifuge        : PID_Compact;

    rMaster_Output          : REAL;
    rCalculatedTransit      : REAL;
    tTransitTimer           : TON;
    tStartupDelay           : TON;
    iFryerState             : INT;

    // Constants
    cMaxTemp_Oil            : REAL := 205.0;
    cMinOilLevel            : REAL := 250.0;
    cVolumePerRev           : REAL := 0.55; // paddle wheel displacement
END_VAR

// Implementation
IF bEmergencyStop THEN
    rThermalValve_Cmd := 0.0;
    rPaddleWheel_SpdCmd := 0.0;
    rCentrifuge_SpdCmd := 0.0;
    bMakeupOil_Pump := FALSE;
    iFryerState := 0;
    bSystemReady := FALSE;
    RETURN;
END_IF;

// Thermal Fluid Heat Exchanger Cascading (Master/Slave PID)
// Master PID controls Zone 1 temperature, outputs setpoint for Thermal Fluid
fbPID_CascadeMaster(
    Enable := bSystemEnable AND (iFryerState > 10),
    Setpoint := rTemp_SP_Zone1,
    ProcessValue := rTemp_Oil_Zone1,
    Output => rMaster_Output
);

// Slave PID controls Thermal Fluid Valve based on Master's output
fbPID_CascadeSlave(
    Enable := bSystemEnable AND (iFryerState > 10),
    Setpoint := rMaster_Output, // Scaled setpoint from Master
    ProcessValue := rThermalFluid_Temp,
    Output => rThermalValve_Cmd
);

// Paddle Wheel Transit Time Profiling
// Ensure chips stay in the fryer for the required duration
IF rPaddleWheel_ActSpeed > 0.0 THEN
    rCalculatedTransit := (1.0 / rPaddleWheel_ActSpeed) * 60.0 * 12.0; // Assume 12 paddles
ELSE
    rCalculatedTransit := 9999.0;
END_IF;

fbPID_PaddleSpeed(
    Enable := bSystemEnable,
    Setpoint := rTransitTime_SP,
    ProcessValue := rCalculatedTransit,
    Output => rPaddleWheel_SpdCmd
);

// Transit Deviation Alarm
bAlarm_TransitDeviation := ABS(rCalculatedTransit - rTransitTime_SP) > 15.0;

// Centrifugal Oil Extraction Control
fbPID_Centrifuge(
    Enable := bSystemEnable,
    Setpoint := rCentrifugeSpeed_SP,
    ProcessValue := rCentrifuge_ActSpeed,
    Output => rCentrifuge_SpdCmd
);

// Oil Level Management
IF rOil_Level < cMinOilLevel THEN
    bMakeupOil_Pump := TRUE;
ELSIF rOil_Level > (cMinOilLevel + 50.0) THEN
    bMakeupOil_Pump := FALSE;
END_IF;

// Safety and Alarms
IF rTemp_Oil_Zone1 > cMaxTemp_Oil OR rTemp_Oil_Zone2 > cMaxTemp_Oil OR rTemp_Oil_Zone3 > cMaxTemp_Oil THEN
    bAlarm_TempHigh := TRUE;
    rThermalValve_Cmd := 0.0; // Hard interlock
ELSE
    bAlarm_TempHigh := FALSE;
END_IF;

// State Machine for Startup Sequence
CASE iFryerState OF
    0: // OFF
        IF bSystemEnable THEN
            iFryerState := 10;
        END_IF;

    10: // WARMUP
        IF rTemp_Oil_Zone1 >= (rTemp_SP_Zone1 - 5.0) THEN
            tStartupDelay(IN := TRUE, PT := T#5M);
            IF tStartupDelay.Q THEN
                iFryerState := 20;
            END_IF;
        END_IF;

    20: // RUNNING
        bSystemReady := TRUE;
        IF NOT bSystemEnable THEN
            iFryerState := 0;
            bSystemReady := FALSE;
            tStartupDelay(IN := FALSE);
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
