FUNCTION_BLOCK FB_DNASynth_MicroDispense_LIF
VAR_INPUT
    (* Primary Safety and Activation Signals *)
    bEnableSystem           : BOOL;     (* Main enable for DNA synthesis cascade *)
    bEStop_OK               : BOOL;     (* Emergency Stop Relay Status (TRUE = OK) *)

    (* Analog Process Variables *)
    rAcetonitrilePressure   : REAL;     (* Anhydrous Acetonitrile supply pressure [bar] *)
    rChamberTemp            : REAL;     (* Reaction chamber temperature [degC] *)
    rLIF_RawSignal          : REAL;     (* Laser-induced fluorescence raw detector input [mV] *)

    (* High-Speed Synchronization *)
    bPiezoSyncTrigger       : BOOL;     (* Synchronization trigger for piezo droplet dispensing *)
END_VAR
VAR_OUTPUT
    (* System Status Flags *)
    bSystemReady            : BOOL;     (* All safety and thermal conditions met *)
    bFaultAlarm             : BOOL;     (* Global fault flag *)

    (* Actuator Commands *)
    rPiezoVoltageCtrl       : REAL;     (* Piezo actuator drive voltage [V] *)
    bAcetonitrileValve      : BOOL;     (* Wash cascade manifold valve control *)

    (* Process Analytics *)
    rCouplingEfficiency     : REAL;     (* Computed coupling efficiency from LIF [%] *)
    iActiveState            : INT;      (* Current step in synthesis state machine *)
END_VAR
VAR
    (* State Management *)
    iState                  : INT := 0; (* Internal state machine tracker *)
    iFaultCode              : INT := 0; (* Detailed fault tracking index *)
    bInterlockOK            : BOOL;     (* Consolidated process interlock flag *)

    (* Timers *)
    tWashTimer              : TON;      (* Timer for acetonitrile wash duration *)
    tDispenseTimer          : TON;      (* Timer for micro-droplet sequence pulse width *)

    (* Signal Processing Filters *)
    rFilteredLIF            : REAL;     (* Exponential moving average of LIF signal for noise reduction *)
    rEMA_Alpha              : REAL := 0.15; (* Filter tuning coefficient *)

    (* PID Thermal / Viscosity Compensation Variables *)
    rTargetTemp             : REAL := 25.0; (* Optimal coupling temperature [degC] *)
    rTempError              : REAL;
    rTempIntegral           : REAL := 0.0;
    rPiezoDriveBase         : REAL := 45.0; (* Base drive voltage for piezo droplets [V] *)

END_VAR

(* === 1. SAFETY & CRITICAL INTERLOCKS === *)
IF NOT bEStop_OK THEN
    (* Instant hardware safing sequence *)
    bSystemReady := FALSE;
    bFaultAlarm := TRUE;
    bAcetonitrileValve := FALSE;
    rPiezoVoltageCtrl := 0.0;
    iState := 999; (* FAULT STATE *)
    iFaultCode := 1; (* 1: E-STOP TRIGGERED *)
    RETURN;
END_IF;

(* Evaluate process environmental bounds (Interlocks) *)
bInterlockOK := (rAcetonitrilePressure >= 2.5) AND (rAcetonitrilePressure <= 3.5) AND
                (rChamberTemp >= 24.0) AND (rChamberTemp <= 26.0);

(* Trap out-of-bounds conditions if actively running *)
IF NOT bInterlockOK AND (iState > 10) AND (iState < 900) THEN
    bFaultAlarm := TRUE;
    iState := 900; (* INITIATE SAFE SHUTDOWN *)
    iFaultCode := 2; (* 2: PROCESS INTERLOCK LOSS (Temp/Pressure) *)
END_IF;

(* === 2. SENSOR SIGNAL PROCESSING === *)
(* High-frequency noise filtration on the LIF diode readout via Exponential Moving Average (EMA) *)
rFilteredLIF := (rEMA_Alpha * rLIF_RawSignal) + ((1.0 - rEMA_Alpha) * rFilteredLIF);

(* === 3. SYNTHESIS CASCADE STATE MACHINE === *)
CASE iState OF
    0: (* STATE 0: IDLE AND DIAGNOSTICS *)
        bSystemReady := bInterlockOK;
        bFaultAlarm := FALSE;
        bAcetonitrileValve := FALSE;
        rPiezoVoltageCtrl := 0.0;

        IF bEnableSystem AND bSystemReady THEN
            iState := 10; (* BEGIN PRE-WASH CYCLE *)
        END_IF;

    10: (* STATE 10: PRE-WASH ANHYDROUS ACETONITRILE CASCADE *)
        bAcetonitrileValve := TRUE;
        tWashTimer(IN := TRUE, PT := T#2S);

        IF tWashTimer.Q THEN
            tWashTimer(IN := FALSE);
            bAcetonitrileValve := FALSE;
            iState := 20; (* ADVANCE TO DISPENSING *)
        END_IF;

    20: (* STATE 20: PIEZO DISPENSE & THERMAL/VISCOSITY PID COMPENSATION *)
        (* Adjust Piezo Drive Voltage based on fluid viscosity shifts from temperature variances *)
        rTempError := rTargetTemp - rChamberTemp;
        rTempIntegral := rTempIntegral + (rTempError * 0.01);

        (* Anti-windup for integral component *)
        IF rTempIntegral > 5.0 THEN rTempIntegral := 5.0; END_IF;
        IF rTempIntegral < -5.0 THEN rTempIntegral := -5.0; END_IF;

        rPiezoVoltageCtrl := rPiezoDriveBase + (rTempError * 1.2) + (rTempIntegral * 0.05);

        (* Await precise hardware optical trigger to fire piezo droplet manifold *)
        IF bPiezoSyncTrigger THEN
            tDispenseTimer(IN := TRUE, PT := T#50MS);

            IF tDispenseTimer.Q THEN
                tDispenseTimer(IN := FALSE);
                rPiezoVoltageCtrl := 0.0; (* De-energize actuator *)
                iState := 30; (* ADVANCE TO COUPLING WAIT / LIF *)
            END_IF;
        END_IF;

    30: (* STATE 30: COUPLING KINETICS & FLUORESCENCE MONITORING *)
        (* Transform raw LIF baseline shift into an inferred coupling efficiency metric *)
        rCouplingEfficiency := (rFilteredLIF / 5000.0) * 100.0;

        (* Verification logic *)
        IF rCouplingEfficiency > 98.5 THEN
            iState := 40; (* SUFFICIENT EFFICIENCY -> POST-WASH *)
        ELSIF rCouplingEfficiency < 50.0 THEN
            iState := 900; (* INSUFFICIENT YIELD FAULT *)
            iFaultCode := 3; (* 3: LIF COUPLING FAILURE *)
        END_IF;

    40: (* STATE 40: POST-WASH CAPPING PREPARATION *)
        bAcetonitrileValve := TRUE;
        tWashTimer(IN := TRUE, PT := T#3S);

        IF tWashTimer.Q THEN
            tWashTimer(IN := FALSE);
            bAcetonitrileValve := FALSE;

            IF NOT bEnableSystem THEN
                iState := 0; (* SYNTHESIS COMPLETE -> IDLE *)
            ELSE
                iState := 10; (* LOOP NEXT NUCLEOTIDE BASE ADDITION *)
            END_IF;
        END_IF;

    900: (* STATE 900: SAFE ABORT SHUTDOWN PROTOCOL *)
        bAcetonitrileValve := FALSE;
        rPiezoVoltageCtrl := 0.0;

        (* Hold in safe state until enable is dropped *)
        IF NOT bEnableSystem THEN
            iState := 999; (* LOCK OUT *)
        END_IF;

    999: (* STATE 999: FAULT LOCKED OUT *)
        bFaultAlarm := TRUE;
        bSystemReady := FALSE;
        bAcetonitrileValve := FALSE;
        rPiezoVoltageCtrl := 0.0;

        (* Self-clearing if E-Stop is physically restored and system is disabled *)
        IF bEStop_OK AND NOT bEnableSystem THEN
            iFaultCode := 0;
            iState := 0;
        END_IF;

END_CASE;

(* Output Assignment *)
iActiveState := iState;

END_FUNCTION_BLOCK
