FUNCTION_BLOCK FB_MSF_Desalination_Core_Controller
TITLE = 'Multi-Stage Flash Desalination Core Controller'
VERSION : 1.0

(* 
   This function block controls the core components of a Multi-Stage Flash (MSF) Desalination plant.
   It manages brine heater steam proportional throttling, maintains flash chamber vacuum levels, 
   and handles distillate recovery cascading sequences.
*)

VAR_INPUT
    (* Physical Inputs from Sensors *)
    rBrineHeaterTemp        : REAL; (* C, Brine Heater Outlet Temperature *)
    rBrineHeaterSteamPress  : REAL; (* bar, Steam Pressure to Brine Heater *)
    rFlashChamber1Vac       : REAL; (* mbar, Vacuum in Stage 1 *)
    rFlashChamberNVac       : REAL; (* mbar, Vacuum in Stage N *)
    rDistillateFlow         : REAL; (* m3/h, Flow rate of distillate product *)
    rSeawaterFeedFlow       : REAL; (* m3/h, Feed seawater flow rate *)
    rTopBrineTempSP         : REAL; (* C, Top Brine Temperature Setpoint *)

    bSystemStart            : BOOL; (* Start command *)
    bSystemStop             : BOOL; (* Stop command *)
    bEmergencyStop          : BOOL; (* Emergency stop *)

    (* Controller Parameters *)
    rKpSteamValv            : REAL := 2.5;
    rKiSteamValv            : REAL := 0.1;
    rKdSteamValv            : REAL := 0.05;
END_VAR

VAR_OUTPUT
    (* Physical Outputs to Actuators *)
    rSteamValvePos          : REAL; (* 0-100%, Brine Heater Steam Valve Position *)
    rEjectorSteamValvePos   : REAL; (* 0-100%, Vacuum Ejector Steam Valve Position *)
    rDistillatePumpSpeed    : REAL; (* 0-100%, Distillate Extraction Pump Speed VFD *)
    rBrineRecircPumpSpeed   : REAL; (* 0-100%, Brine Recirculation Pump Speed *)

    bSystemRunning          : BOOL;
    bAlarmActive            : BOOL;
    iAlarmCode              : INT; (* 0=OK, 1=High TBT, 2=Low Vacuum, 3=Pump Fault *)
END_VAR

VAR
    (* Internal State Variables *)
    eState                  : INT := 0; (* 0=STOPPED, 1=STARTING, 2=RUNNING, 3=STOPPING, 4=FAULT *)

    (* PID Variables for Steam Valve (Top Brine Temp Control) *)
    rErrorTemp              : REAL;
    rPrevErrorTemp          : REAL;
    rIntegralTemp           : REAL;
    rDerivativeTemp         : REAL;
    rOutputTempCtrl         : REAL;

    (* Vacuum Control Variables *)
    rTargetVacuum           : REAL := 50.0; (* mbar target *)
    rVacError               : REAL;

    (* Timers *)
    tStartupDelay           : TON;
    tShutdownDelay          : TON;

    bInitialized            : BOOL := FALSE;
END_VAR

(* Implementation Body *)
IF bEmergencyStop THEN
    eState := 4;
    iAlarmCode := 99;
END_VAR

CASE eState OF
    0: (* STOPPED *)
        rSteamValvePos := 0.0;
        rEjectorSteamValvePos := 0.0;
        rDistillatePumpSpeed := 0.0;
        rBrineRecircPumpSpeed := 0.0;
        bSystemRunning := FALSE;
        rIntegralTemp := 0.0;
        rPrevErrorTemp := 0.0;

        IF bSystemStart AND NOT bSystemStop AND NOT bAlarmActive THEN
            eState := 1;
        END_IF;

    1: (* STARTING *)
        bSystemRunning := TRUE;
        (* Start vacuum system first *)
        rEjectorSteamValvePos := 100.0;

        tStartupDelay(IN:= TRUE, PT:= T#60S);

        IF tStartupDelay.Q THEN
            IF rFlashChamberNVac < 100.0 THEN
                (* Vacuum established, start brine recirc *)
                rBrineRecircPumpSpeed := 50.0;
                eState := 2;
                tStartupDelay(IN:= FALSE);
            ELSE
                eState := 4;
                iAlarmCode := 2; (* Low Vacuum Alarm *)
            END_IF;
        END_IF;

        IF bSystemStop THEN
            eState := 3;
            tStartupDelay(IN:= FALSE);
        END_IF;

    2: (* RUNNING *)
        (* Top Brine Temperature (TBT) PID Control *)
        rErrorTemp := rTopBrineTempSP - rBrineHeaterTemp;
        rIntegralTemp := rIntegralTemp + rErrorTemp;

        (* Anti-windup *)
        IF rIntegralTemp > 1000.0 THEN rIntegralTemp := 1000.0; END_IF;
        IF rIntegralTemp < -1000.0 THEN rIntegralTemp := -1000.0; END_IF;

        rDerivativeTemp := rErrorTemp - rPrevErrorTemp;

        rOutputTempCtrl := (rKpSteamValv * rErrorTemp) + (rKiSteamValv * rIntegralTemp) + (rKdSteamValv * rDerivativeTemp);
        rPrevErrorTemp := rErrorTemp;

        (* Apply output bounds *)
        IF rOutputTempCtrl > 100.0 THEN
            rSteamValvePos := 100.0;
        ELSIF rOutputTempCtrl < 0.0 THEN
            rSteamValvePos := 0.0;
        ELSE
            rSteamValvePos := rOutputTempCtrl;
        END_IF;

        (* Flash Chamber Vacuum Maintenance *)
        rVacError := rTargetVacuum - rFlashChamber1Vac;
        IF rVacError > 10.0 THEN
            rEjectorSteamValvePos := 80.0;
        ELSE
            rEjectorSteamValvePos := 40.0; (* Maintenance level *)
        END_IF;

        (* Distillate Recovery Cascading Control *)
        (* Simple proportional control based on flow *)
        IF rDistillateFlow > 100.0 THEN
            rDistillatePumpSpeed := 80.0;
        ELSIF rDistillateFlow > 50.0 THEN
            rDistillatePumpSpeed := 50.0;
        ELSE
            rDistillatePumpSpeed := 20.0;
        END_IF;

        (* Alarm Monitoring *)
        IF rBrineHeaterTemp > 120.0 THEN
            eState := 4;
            iAlarmCode := 1;
        END_IF;

        IF bSystemStop THEN
            eState := 3;
        END_IF;

    3: (* STOPPING *)
        rSteamValvePos := 0.0; (* Cut heat immediately *)
        tShutdownDelay(IN:= TRUE, PT:= T#120S);

        (* Gradual pump shutdown *)
        rBrineRecircPumpSpeed := rBrineRecircPumpSpeed * 0.95;
        rDistillatePumpSpeed := rDistillatePumpSpeed * 0.90;

        IF tShutdownDelay.Q THEN
            eState := 0;
            tShutdownDelay(IN:= FALSE);
        END_IF;

    4: (* FAULT *)
        rSteamValvePos := 0.0;
        rEjectorSteamValvePos := 0.0;
        rBrineRecircPumpSpeed := 0.0;
        rDistillatePumpSpeed := 0.0;
        bSystemRunning := FALSE;
        bAlarmActive := TRUE;

        IF bSystemStop THEN
            (* Reset logic *)
            bAlarmActive := FALSE;
            iAlarmCode := 0;
            eState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_SubseaTidalTurbineNacelle
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main contactor / system master enable *)
    bEmergencyStop          : BOOL;     (* SIL-3 certified hardware safety relay loop status *)
    rBladeRootStrain1       : REAL;     (* Strain gauge reading on Blade 1 root (microstrain) *)
    rBladeRootStrain2       : REAL;     (* Strain gauge reading on Blade 2 root (microstrain) *)
    rBladeRootStrain3       : REAL;     (* Strain gauge reading on Blade 3 root (microstrain) *)
    rBearingPressureFront   : REAL;     (* Hydrodynamic film pressure front bearing (Bar) *)
    rBearingPressureRear    : REAL;     (* Hydrodynamic film pressure rear bearing (Bar) *)
    rNacelleVibrationX      : REAL;     (* Accelerometer X-axis vibration (mm/s RMS) *)
    rNacelleVibrationY      : REAL;     (* Accelerometer Y-axis vibration (mm/s RMS) *)
    rTidalFlowVelocity      : REAL;     (* Acoustic Doppler Current Profiler (ADCP) flow velocity (m/s) *)
    bSeawaterIngress        : BOOL;     (* Nacelle internal moisture / leak detection switch *)
END_VAR

VAR_OUTPUT
    bTurbineReady           : BOOL;     (* System synchronized, safety OK, ready for generation *)
    bGridConnected          : BOOL;     (* Contactor closed to export power to grid *)
    rPitchCommandDeg        : REAL;     (* Target collective pitch angle command (Degrees) *)
    rGeneratorTorqueRef     : REAL;     (* Active power / torque reference to power converter (Nm) *)
    bBiofoulingSonicActive  : BOOL;     (* Ultrasonic transducer array enable for antifouling *)
    bCriticalFaultAlarm     : BOOL;     (* Master critical trip flag - requires manual reset *)
    iFaultCode              : INT;      (* Diagnostics encoded fault ID *)
END_VAR

VAR
    iStateMachine           : INT := 0; (* Internal control state 0=Init, 10=Standby, 20=Ramp, 30=Gen, 99=Fault *)
    rAvgStrain              : REAL := 0.0;
    rFilteredVelocity       : REAL := 0.0;
    rVibrationVector        : REAL := 0.0;

    (* Timers & Filters *)
    tStandbyDelay           : TON;
    tBioFoulingCycle        : TON;
    rVelocityAlpha          : REAL := 0.1; (* EWMA filter coefficient *)

    (* Constants *)
    c_rMaxStrain            : REAL := 4500.0; (* Trip threshold microstrain *)
    c_rMaxVibration         : REAL := 12.5;   (* Trip threshold mm/s RMS *)
    c_rMinBearingPres       : REAL := 2.1;    (* Minimum film pressure required to start *)
    c_rCutInVelocity        : REAL := 1.5;    (* Cut-in speed m/s *)
    c_rRatedVelocity        : REAL := 3.2;    (* Rated speed m/s *)
END_VAR

(* === MAIN LOGIC === *)

(* 1. Safety & Interlock Evaluation (Highest Priority) *)
IF NOT bEmergencyStop OR bSeawaterIngress THEN
    bCriticalFaultAlarm := TRUE;
    bTurbineReady := FALSE;
    bGridConnected := FALSE;
    rPitchCommandDeg := 90.0; (* Feather blades immediately *)
    rGeneratorTorqueRef := 0.0;
    bBiofoulingSonicActive := FALSE;
    iStateMachine := 99;
    IF NOT bEmergencyStop THEN
        iFaultCode := 1001; (* E-STOP triggered *)
    ELSE
        iFaultCode := 1002; (* Flooding detected *)
    END_IF;
    RETURN;
END_IF;

(* 2. Signal Processing & Sensor Fusion *)
rAvgStrain := (rBladeRootStrain1 + rBladeRootStrain2 + rBladeRootStrain3) / 3.0;
rFilteredVelocity := (rVelocityAlpha * rTidalFlowVelocity) + ((1.0 - rVelocityAlpha) * rFilteredVelocity);

(* Pythagoras for total radial vibration magnitude *)
(* Approximation for root sum square without SQRT instruction overhead if standard math library isn't linked, but let's use pseudo SQRT *)
rVibrationVector := rNacelleVibrationX * rNacelleVibrationX + rNacelleVibrationY * rNacelleVibrationY;

(* 3. Operational Limits Monitoring *)
IF rAvgStrain > c_rMaxStrain OR rVibrationVector > (c_rMaxVibration * c_rMaxVibration) THEN
    bCriticalFaultAlarm := TRUE;
    iStateMachine := 99;
    iFaultCode := 2001; (* Structural limits exceeded *)
END_IF;

IF rBearingPressureFront < c_rMinBearingPres AND iStateMachine >= 20 THEN
    bCriticalFaultAlarm := TRUE;
    iStateMachine := 99;
    iFaultCode := 2002; (* Loss of hydrodynamic lubrication film *)
END_IF;

(* 4. Biofouling Mitigation Cyclic Control *)
tBioFoulingCycle(IN := NOT tBioFoulingCycle.Q, PT := T#4H);
IF tBioFoulingCycle.ET > T#3H30M THEN
    bBiofoulingSonicActive := TRUE;
ELSE
    bBiofoulingSonicActive := FALSE;
END_IF;


(* 5. Core State Machine *)
CASE iStateMachine OF
    0: (* INITIALIZATION & SELF-TEST *)
        bTurbineReady := FALSE;
        bGridConnected := FALSE;
        rPitchCommandDeg := 90.0; (* Fully feathered *)
        rGeneratorTorqueRef := 0.0;
        bCriticalFaultAlarm := FALSE;
        iFaultCode := 0;

        IF bSystemEnable THEN
            iStateMachine := 10;
        END_IF;

    10: (* STANDBY / IDLING *)
        bTurbineReady := TRUE;
        bGridConnected := FALSE;
        rPitchCommandDeg := 85.0; (* Slightly open to allow slow idling if flow exists *)
        rGeneratorTorqueRef := 0.0;

        tStandbyDelay(IN := (rFilteredVelocity >= c_rCutInVelocity), PT := T#30S);

        IF tStandbyDelay.Q AND (rBearingPressureFront > c_rMinBearingPres) THEN
            tStandbyDelay(IN := FALSE);
            iStateMachine := 20;
        ELSIF NOT bSystemEnable THEN
            iStateMachine := 0;
        END_IF;

    20: (* RAMP-UP TO GRID SYNC *)
        (* Slowly pitch to operational angles to accelerate rotor *)
        IF rPitchCommandDeg > 15.0 THEN
            rPitchCommandDeg := rPitchCommandDeg - 0.5;
        END_IF;

        (* Simulated synchronization condition based on rotational speed achieving nominal slip *)
        IF rPitchCommandDeg <= 15.0 THEN
            bGridConnected := TRUE;
            iStateMachine := 30;
        END_IF;

    30: (* POWER GENERATION (MPPT / RATED CONTROL) *)
        IF rFilteredVelocity < c_rCutInVelocity THEN
            iStateMachine := 10; (* Flow dropped, return to standby *)
        END_IF;

        IF rFilteredVelocity < c_rRatedVelocity THEN
            (* Region 2: MPPT tracking (constant tip-speed ratio) *)
            rPitchCommandDeg := 0.0; (* Fine pitch for max aerodynamic efficiency *)
            (* Quadratic torque law: Torque = K * v^2 *)
            rGeneratorTorqueRef := 5000.0 * (rFilteredVelocity * rFilteredVelocity);
        ELSE
            (* Region 3: Power limitation via active pitch *)
            (* Proportional pitch response to over-velocity to shed hydrodynamic load *)
            rPitchCommandDeg := (rFilteredVelocity - c_rRatedVelocity) * 12.5; 
            IF rPitchCommandDeg > 45.0 THEN
                rPitchCommandDeg := 45.0; (* Pitch limit saturation *)
            END_IF;
            rGeneratorTorqueRef := 50000.0; (* Rated torque ceiling *)
        END_IF;

        IF NOT bSystemEnable THEN
            iStateMachine := 10;
        END_IF;

    99: (* FAULT HANDLING / SHUTDOWN OVERRIDE *)
        bTurbineReady := FALSE;
        bGridConnected := FALSE;
        rPitchCommandDeg := 90.0;
        rGeneratorTorqueRef := 0.0;

        (* Fault reset logic (Requires manual system disable/enable cycle to clear) *)
        IF NOT bSystemEnable AND NOT bEmergencyStop AND NOT bSeawaterIngress THEN
            bCriticalFaultAlarm := FALSE;
            iFaultCode := 0;
            iStateMachine := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
