FUNCTION_BLOCK FB_EscalatorAdvancedControl
VAR_INPUT
    bEnable                 : BOOL;   (* Main enable for the escalator *)
    bStart                  : BOOL;   (* Start command *)
    bStop                   : BOOL;   (* Normal stop command *)
    bEmergencyStop          : BOOL;   (* Emergency stop circuit *)
    rStepSpeedActual        : REAL;   (* Actual speed of the steps (m/s) *)
    rHandrailSpeedActual    : REAL;   (* Actual speed of the handrail (m/s) *)
    bMissingStepSensor      : BOOL;   (* Optical sensor input for missing step detection (Normally Closed) *)
    rInverterDCBusVoltage   : REAL;   (* DC Bus voltage of the VFD for regenerative braking monitoring *)
    rLoadWeight             : REAL;   (* Total passenger load weight (kg) *)
    bMotorOvertemp          : BOOL;   (* Motor PTC/Over-temperature sensor *)
END_VAR

VAR_OUTPUT
    bMotorRun               : BOOL;   (* Command to run the main drive motor *)
    rSpeedSetpoint          : REAL;   (* Speed setpoint to the VFD *)
    bRegenBrakeActive       : BOOL;   (* Activate regenerative braking resistor/module *)
    bMechanicalBrakeRelease : BOOL;   (* Release the mechanical holding brake *)
    bFault                  : BOOL;   (* General fault indicator *)
    iFaultCode              : INT;    (* Specific fault code *)
    bWarningHandrailSync    : BOOL;   (* Handrail speed out of sync warning *)
END_VAR

VAR
    (* Internal State Machine *)
    eState                  : INT := 0; (* 0: OFF, 1: STARTING, 2: RUNNING, 3: BRAKING, 4: FAULT *)

    (* Timers *)
    tMissingStepTimer       : TON;
    tHandrailSyncTimer      : TON;
    tRegenTimer             : TOF;
    tStartDelay             : TON;

    (* Internal Variables *)
    rSpeedDiff              : REAL;
    bMissingStepFault       : BOOL;
    bHandrailFault          : BOOL;
    bOvervoltageFault       : BOOL;

    (* Constants *)
    NOMINAL_SPEED           : REAL := 0.65; (* m/s *)
    MAX_SPEED_DIFF          : REAL := 0.05; (* Max allowed diff between handrail and steps *)
    DC_BUS_MAX              : REAL := 750.0; (* VDC limit before regen braking *)
    DC_BUS_CRITICAL         : REAL := 800.0; (* VDC trip limit *)
END_VAR

(* Escalator Advanced Control Logic - IEC 61131-3 *)

(* 1. Safety and Fault Detection *)
(* Emergency Stop Check *)
IF NOT bEmergencyStop THEN
    bFault := TRUE;
    iFaultCode := 1; (* Emergency Stop Activated *)
    eState := 4;
END_IF;

(* Missing Step Detection *)
(* Sensor is NC, so FALSE means missing step detected. We debounce this with a timer. *)
tMissingStepTimer(IN := NOT bMissingStepSensor, PT := T#50MS);
IF tMissingStepTimer.Q THEN
    bMissingStepFault := TRUE;
    bFault := TRUE;
    iFaultCode := 2; (* Missing Step Detected *)
    eState := 4;
END_IF;

(* Motor Overtemperature *)
IF bMotorOvertemp THEN
    bFault := TRUE;
    iFaultCode := 3; (* Motor Overtemp *)
    eState := 4;
END_IF;

(* DC Bus Overvoltage Trip *)
IF rInverterDCBusVoltage > DC_BUS_CRITICAL THEN
    bOvervoltageFault := TRUE;
    bFault := TRUE;
    iFaultCode := 4; (* VFD DC Bus Critical Overvoltage *)
    eState := 4;
END_IF;

(* 2. Handrail Synchronization Profiling *)
rSpeedDiff := ABS(rStepSpeedActual - rHandrailSpeedActual);
tHandrailSyncTimer(IN := (rSpeedDiff > MAX_SPEED_DIFF) AND (eState = 2), PT := T#3S);

IF tHandrailSyncTimer.Q THEN
    bHandrailFault := TRUE;
    bFault := TRUE;
    iFaultCode := 5; (* Handrail Speed Deviation Exceeded *)
    eState := 4;
ELSIF rSpeedDiff > (MAX_SPEED_DIFF * 0.8) AND (eState = 2) THEN
    bWarningHandrailSync := TRUE;
ELSE
    bWarningHandrailSync := FALSE;
END_IF;

(* 3. Regenerative Braking Management *)
IF rInverterDCBusVoltage > DC_BUS_MAX AND eState = 3 THEN
    bRegenBrakeActive := TRUE;
ELSE
    bRegenBrakeActive := FALSE;
END_IF;

(* Maintain regen braking for a minimum time after activation to prevent chattering *)
tRegenTimer(IN := bRegenBrakeActive, PT := T#2S);
bRegenBrakeActive := tRegenTimer.Q;

(* 4. Main State Machine *)
CASE eState OF
    0: (* OFF *)
        bMotorRun := FALSE;
        rSpeedSetpoint := 0.0;
        bMechanicalBrakeRelease := FALSE;

        IF bEnable AND bStart AND NOT bFault THEN
            eState := 1;
        END_IF;

    1: (* STARTING *)
        bMechanicalBrakeRelease := TRUE;
        tStartDelay(IN := TRUE, PT := T#500MS);

        IF tStartDelay.Q THEN
            bMotorRun := TRUE;
            rSpeedSetpoint := NOMINAL_SPEED;
            IF rStepSpeedActual >= (NOMINAL_SPEED * 0.95) THEN
                eState := 2;
                tStartDelay(IN := FALSE);
            END_IF;
        END_IF;

        IF bStop OR NOT bEnable THEN
            eState := 3;
            tStartDelay(IN := FALSE);
        END_IF;

    2: (* RUNNING *)
        bMotorRun := TRUE;
        rSpeedSetpoint := NOMINAL_SPEED;
        bMechanicalBrakeRelease := TRUE;

        (* Dynamic Load Profiling for Speed / Energy Savings could be inserted here *)
        IF rLoadWeight = 0.0 THEN
            (* Slow down if no passengers - Eco mode *)
            rSpeedSetpoint := NOMINAL_SPEED * 0.5;
        END_IF;

        IF bStop OR NOT bEnable THEN
            eState := 3;
        END_IF;

    3: (* BRAKING *)
        bMotorRun := TRUE;
        rSpeedSetpoint := 0.0; (* Decelerate via VFD *)

        IF rStepSpeedActual < 0.05 THEN
            bMotorRun := FALSE;
            bMechanicalBrakeRelease := FALSE;
            eState := 0;
        END_IF;

        IF bFault THEN
            eState := 4;
        END_IF;

    4: (* FAULT *)
        bMotorRun := FALSE;
        rSpeedSetpoint := 0.0;
        bMechanicalBrakeRelease := FALSE;
        bRegenBrakeActive := TRUE; (* Dump any remaining energy *)

        (* Fault reset logic (not fully implemented here, requires manual intervention typically) *)
        IF bStart AND NOT bMissingStepFault AND NOT bHandrailFault AND NOT bOvervoltageFault AND NOT bEmergencyStop THEN
            bFault := FALSE;
            iFaultCode := 0;
            eState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

```iec-st
Here is the Base Siemens SCL program for Railway Tunnel Ventilation. It handles jet fan thrust reversal based on smoke detection and airflow direction, incorporating a coast-down timer to protect the fan motors during reversal.

FUNCTION_BLOCK "Tunnel_Vent_Base"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.0
   VAR_INPUT
      xAutoMode : Bool;
      xSmokeDetected : Bool;
      xFireLocationFwd : Bool; // True if fire is towards forward portal
      xFireLocationRev : Bool; // True if fire is towards reverse portal
   END_VAR

   VAR_OUTPUT
      xCmdStartFwd : Bool;
      xCmdStartRev : Bool;
      xCmdStop : Bool;
   END_VAR

   VAR
      tonCoastDown : TON_TIME;
      statState : Int; // 0=Stop, 1=Fwd, 2=Rev, 3=Coasting
      statCoastActive : Bool;
   END_VAR

   VAR_CONSTANT
      COAST_TIME : Time := T#30s;
   END_VAR

BEGIN
    // Coast Down Timer for Thrust Reversal
    tonCoastDown(IN := statCoastActive, PT := COAST_TIME);

    IF xAutoMode THEN
        IF xSmokeDetected THEN
            IF xFireLocationFwd AND NOT xFireLocationRev THEN
                // Blow smoke towards forward portal
                IF statState = 2 THEN
                    // Currently Reverse, need to coast down
                    xCmdStop := TRUE;
                    xCmdStartRev := FALSE;
                    statCoastActive := TRUE;
                    statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartFwd := TRUE;
                    xCmdStop := FALSE;
                    statCoastActive := FALSE;
                    statState := 1;
                END_IF;
            ELSIF xFireLocationRev AND NOT xFireLocationFwd THEN
                // Blow smoke towards reverse portal
                IF statState = 1 THEN
                    // Currently Forward, need to coast down
                    xCmdStop := TRUE;
                    xCmdStartFwd := FALSE;
                    statCoastActive := TRUE;
                    statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartRev := TRUE;
                    xCmdStop := FALSE;
                    statCoastActive := FALSE;
                    statState := 2;
                END_IF;
            END_IF;
        ELSE
            // Normal operation - stop fans
            xCmdStop := TRUE;
            xCmdStartFwd := FALSE;
            xCmdStartRev := FALSE;
            statState := 0;
            statCoastActive := FALSE;
        END_IF;
    ELSE
        // Manual or off mode - logic handled elsewhere
        statCoastActive := FALSE;
    END_IF;
END_FUNCTION_BLOCK
