    rCmd_LOXDosingValV  : REAL;
    rCmd_OzoneGenerator : REAL;
    bCmd_CircPumpRun    : BOOL;
    bCmd_BioFilterBlower: BOOL;

    bAlarm_LowDO        : BOOL;
    bAlarm_HighAmmonia  : BOOL;
    bAlarm_HighNitrite  : BOOL;
    bAlarm_OzoneTox     : BOOL;

    rEst_Nitrification  : REAL;
END_VAR

VAR
    fbPID_Oxygen        : PID_CONTROLLER;
    fbPID_Ozone         : PID_CONTROLLER;
    timerAmmoniaSpike   : TON;

    rTempFactor         : REAL;
    rUnionizedAmmonia   : REAL;
    rOxygenDemand       : REAL;
END_VAR

// 1. Safety
IF bEmergencyStop OR NOT bSystemEnable THEN
    rCmd_LOXDosingValV := 0.0;
    rCmd_OzoneGenerator := 0.0;
    bCmd_CircPumpRun := FALSE;
    bCmd_BioFilterBlower := FALSE;
    RETURN;
END_IF;

bCmd_CircPumpRun := TRUE;

