rTempFactor := LIMIT(0.0, (rSensor_Temp - 10.0) / 15.0, 1.0);
IF rSensor_DO > 2.0 THEN
    bCmd_BioFilterBlower := TRUE;
    rEst_Nitrification := (rSensor_Ammonia * 0.1) * rTempFactor;
ELSE
    bCmd_BioFilterBlower := FALSE;
    rEst_Nitrification := 0.0;
END_IF;

rUnionizedAmmonia := rSensor_Ammonia * (1.0 / (1.0 + EXP(0.4 * (27.27 - rSensor_Temp) + 0.09 * (273.15 + rSensor_Temp) * (8.5 - rSensor_pH))));

// 3. Liquid Oxygen (LOX) Dosing Control
rOxygenDemand := (rFeedRate * 0.25) + (rEst_Nitrification * rFlowRate * 4.57 / 1000.0);

fbPID_Oxygen(
    EN := TRUE,
    SP := rSP_DO,
    PV := rSensor_DO,
    Kp := 2.5,
    Ki := 0.1,
    Kd := 0.05,
    CV => rCmd_LOXDosingValV
);
rCmd_LOXDosingValV := LIMIT(0.0, rCmd_LOXDosingValV + (rOxygenDemand * 10.0), 100.0);

// 4. Ozone Injection (ORP Control)
fbPID_Ozone(
    EN := TRUE,
    SP := rSP_ORP,
    PV := rSensor_ORP,
    Kp := 1.0,
    Ki := 0.05,
    Kd := 0.0,
    CV => rCmd_OzoneGenerator
);
rCmd_OzoneGenerator := LIMIT(0.0, rCmd_OzoneGenerator, 100.0);

IF rSensor_ORP > 350.0 THEN
    rCmd_OzoneGenerator := 0.0;
END_IF;

// 5. Alarms
bAlarm_LowDO := (rSensor_DO < 4.0);
bAlarm_HighAmmonia := (rUnionizedAmmonia > 0.05) OR (rSensor_Ammonia > rSP_MaxAmmonia);
bAlarm_HighNitrite := (rSensor_Nitrite > 0.5);
bAlarm_OzoneTox := (rSensor_ORP > 380.0);

timerAmmoniaSpike(IN := bAlarm_HighAmmonia, PT := T#15m);
