FUNCTION_BLOCK FB_HallHeroult_Cell_Controller
TITLE = 'Advanced Hall-Héroult Reduction Cell Controller'
VERSION = '2.4'
//=================================================================================================
// This Function Block manages the complex electrochemical and physical dynamics 
// of an Aluminum Smelting Hall-Héroult Cell. It incorporates:
// 1. Pseudo-Resistance Calculation and derivative tracking.
// 2. Predictive Anode Effect (AE) detection based on dR/dt and Alumina concentration.
// 3. Automatic Voltage Suppression via anode beam kinematics to quench impending AEs.
// 4. Automated Crust Breaking and Alumina Point Feeding Cascade (Under/Over feed modes).
//=================================================================================================

VAR_INPUT
    rCellVoltage : REAL;             // Current cell voltage (V) typically 4.0 - 4.5V
    rLineCurrent : REAL;             // Current potline current (kA) typically 300 - 600kA
    rBathTemp : REAL;                // Bath temperature (deg C) typically 950 - 980C
    rAluminaConcentration : REAL;    // Estimated Alumina concentration (%) target 2.0 - 4.0%
    bManualOverride : BOOL;          // Operator manual override active
    rTargetVoltage : REAL;           // Target cell voltage setting (V)
    bEStop : BOOL;                   // Emergency Stop
END_VAR

VAR_OUTPUT
    bCrustBreakerActuate : BOOL;     // Trigger crust breaker pneumatic cylinder (chisel)
    bPointFeederActuate : BOOL;      // Trigger alumina point feeder volumetric dose
    rAnodePositionCmd : REAL;        // Command for anode beam position (mm)
    bAnodeEffectWarning : BOOL;      // Warning indicator for impending anode effect
    bVoltageSuppressionActive : BOOL;// Indicator that voltage suppression routine is active
    bSystemFault : BOOL;             // General fault indicator
    iActiveFeedMode : INT;           // 0 = Normal, 1 = Underfeed, 2 = Overfeed
END_VAR

VAR
    rResistance : REAL;              // Calculated pseudo-resistance (micro-ohms)
    rResistanceDeriv : REAL;         // Derivative of resistance over time (micro-ohms / s)
    rPrevResistance : REAL;          // Previous cycle resistance

    tUpdateTimer : TON;              // Timer for 1-second calculation loop
    tFeedCycleTimer : TON;           // Timer for alumina feeding cascade scheduling
    tCrustBreakerDuration : TP;      // Pulse duration for crust breaker pneumatic cylinder
    tFeederDuration : TP;            // Pulse duration for point feeder valve

    nFeedState : INT := 0;           // State machine variable for feeding cascade
    rAnodeEffectThreshold : REAL := 0.08; // dR/dt threshold for AE warning (micro-ohms/s)
    rBackEMF : REAL := 1.65;         // Estimated Back EMF of the cell (V)

    tStateResetTimer : TON;
END_VAR

//=================================================================================================
// 0. Safety and Fault Handling
//=================================================================================================
IF bEStop THEN
    bCrustBreakerActuate := FALSE;
    bPointFeederActuate := FALSE;
    bSystemFault := TRUE;
    RETURN;
END_IF;

//=================================================================================================
// 1. Calculate Pseudo-Resistance and Derivative
//=================================================================================================
tUpdateTimer(IN := NOT tUpdateTimer.Q, PT := T#1S);
IF tUpdateTimer.Q THEN
    IF rLineCurrent > 50.0 THEN // Avoid division by zero and low current noise
        rResistance := (rCellVoltage - rBackEMF) / rLineCurrent * 1000.0; 
    ELSE
        rResistance := 0.0;
    END_IF;

    rResistanceDeriv := rResistance - rPrevResistance;
    rPrevResistance := rResistance;
END_IF;

//=================================================================================================
// 2. Anode Effect Prediction and Voltage Suppression
//=================================================================================================
IF (rResistanceDeriv > rAnodeEffectThreshold) AND (rAluminaConcentration < 1.8) THEN
    bAnodeEffectWarning := TRUE;
ELSE
    bAnodeEffectWarning := FALSE;
END_IF;

IF bAnodeEffectWarning AND NOT bManualOverride THEN
    bVoltageSuppressionActive := TRUE;
    // Rapidly lower anode to suppress voltage and quench the anode effect
    rAnodePositionCmd := rAnodePositionCmd - 1.5; // Lower by 1.5mm per cycle
ELSE
    bVoltageSuppressionActive := FALSE;
    // Normal voltage regulation logic
    IF rCellVoltage > (rTargetVoltage + 0.05) THEN
        rAnodePositionCmd := rAnodePositionCmd - 0.1;
    ELSIF rCellVoltage < (rTargetVoltage - 0.05) THEN
        rAnodePositionCmd := rAnodePositionCmd + 0.1;
    END_IF;
END_IF;

//=================================================================================================
// 3. Alumina Feeding Strategy Determination (Under/Over Feed)
//=================================================================================================
IF rAluminaConcentration > 3.5 THEN
    iActiveFeedMode := 1; // Underfeed mode to deplete excess alumina
    tFeedCycleTimer.PT := T#8M; 
ELSIF rAluminaConcentration < 2.0 THEN
    iActiveFeedMode := 2; // Overfeed mode to prevent anode effect
    tFeedCycleTimer.PT := T#2M;
ELSE
    iActiveFeedMode := 0; // Normal tracking mode
    tFeedCycleTimer.PT := T#4M;
END_IF;

//=================================================================================================
// 4. Automated Crust Breaking and Point Feeding Cascade
//=================================================================================================
tFeedCycleTimer(IN := (nFeedState = 0));

IF tFeedCycleTimer.Q AND NOT bVoltageSuppressionActive THEN
    nFeedState := 10; // Initiate cascade
END_IF;

CASE nFeedState OF
    0:
        bCrustBreakerActuate := FALSE;
        bPointFeederActuate := FALSE;

    10: // Actuate Crust Breaker Pneumatics
        tCrustBreakerDuration(IN := TRUE, PT := T#2S500MS);
        bCrustBreakerActuate := tCrustBreakerDuration.Q;
        IF NOT tCrustBreakerDuration.Q THEN
            nFeedState := 20;
            tCrustBreakerDuration(IN := FALSE);
        END_IF;

    20: // Delay before feeding to allow crust to clear
        tStateResetTimer(IN := TRUE, PT := T#1S);
        IF tStateResetTimer.Q THEN
            nFeedState := 30;
            tStateResetTimer(IN := FALSE);
        END_IF;

    30: // Actuate Alumina Point Feeder
        tFeederDuration(IN := TRUE, PT := T#3S);
        bPointFeederActuate := tFeederDuration.Q;
        IF NOT tFeederDuration.Q THEN
            nFeedState := 0; // Cascade complete, return to idle
            tFeederDuration(IN := FALSE);
        END_IF;

    ELSE
        nFeedState := 0;
END_CASE;

END_FUNCTION_BLOCK
