FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL;
    rSetTempZone1 : REAL;
    rSetTempZone2 : REAL;
    rSetTempZone3 : REAL;
    rActTempZone1 : REAL;
    rActTempZone2 : REAL;
    rActTempZone3 : REAL;
    rBandSpeedSet : REAL;
    rBandSpeedAct : REAL;
    rBandTensionAct : REAL;
    bGasPressureOK : BOOL;
    bExhaustFanRun : BOOL;
END_VAR
VAR_OUTPUT
    rBurnerValveZ1 : REAL;
    rBurnerValveZ3 : REAL;
    rHeaterPowerZ2 : REAL;
    rCircFanSpdZ2  : REAL;
    rBandDriveRef  : REAL;
    bBandTensionAlarm : BOOL;
    bBurnerIgniteZ1 : BOOL;
    bBurnerIgniteZ3 : BOOL;
    bSystemReady : BOOL;
    bFault : BOOL;
    iFaultCode : INT;
END_VAR
VAR
    PID_Z1 : FB_PID;
    PID_Z2 : FB_PID;
    PID_Z3 : FB_PID;
    PID_Band : FB_PID;

    TMR_IgnitionZ1 : TON;
    TMR_IgnitionZ3 : TON;
    TMR_Purge : TON;

    iState : INT;
    rKpZ1 : REAL := 2.5; rKiZ1 : REAL := 0.1;
    rKpZ2 : REAL := 1.8; rKiZ2 : REAL := 0.05;
    rKpZ3 : REAL := 2.0; rKiZ3 : REAL := 0.1;
    rKpBand : REAL := 1.0; rKiBand : REAL := 0.2;

    bPurgeComplete : BOOL;
END_VAR

bFault := FALSE;
iFaultCode := 0;

IF NOT bGasPressureOK THEN
    bFault := TRUE;
    iFaultCode := 101;
END_IF

IF NOT bExhaustFanRun THEN
    bFault := TRUE;
    iFaultCode := 102;
END_IF

IF rBandTensionAct < 100.0 OR rBandTensionAct > 5000.0 THEN
    bBandTensionAlarm := TRUE;
    bFault := TRUE;
    iFaultCode := 103;
ELSE
    bBandTensionAlarm := FALSE;
END_IF

IF bFault OR NOT bEnable THEN
    iState := 0;
    rBurnerValveZ1 := 0.0;
    rBurnerValveZ3 := 0.0;
    rHeaterPowerZ2 := 0.0;
    rCircFanSpdZ2 := 0.0;
    rBandDriveRef := 0.0;
    bBurnerIgniteZ1 := FALSE;
    bBurnerIgniteZ3 := FALSE;
    bPurgeComplete := FALSE;
    bSystemReady := FALSE;
    RETURN;
END_IF

CASE iState OF
    0:
        TMR_Purge(IN:=FALSE);
        iState := 10;

    10:
        rCircFanSpdZ2 := 100.0;
        TMR_Purge(IN:=TRUE, PT:=T#30s);
        IF TMR_Purge.Q THEN
            bPurgeComplete := TRUE;
            iState := 20;
        END_IF

    20:
        bBurnerIgniteZ1 := TRUE;
        bBurnerIgniteZ3 := TRUE;
        TMR_IgnitionZ1(IN:=TRUE, PT:=T#5s);
        TMR_IgnitionZ3(IN:=TRUE, PT:=T#5s);

        IF TMR_IgnitionZ1.Q AND TMR_IgnitionZ3.Q THEN
            bBurnerIgniteZ1 := FALSE;
            bBurnerIgniteZ3 := FALSE;
            bSystemReady := TRUE;
            iState := 30;
        END_IF

    30:
        PID_Z1(bEnable:=TRUE, rSetpoint:=rSetTempZone1, rFeedback:=rActTempZone1, rKp:=rKpZ1, rKi:=rKiZ1, rOutput=>rBurnerValveZ1);
        PID_Z2(bEnable:=TRUE, rSetpoint:=rSetTempZone2, rFeedback:=rActTempZone2, rKp:=rKpZ2, rKi:=rKiZ2, rOutput=>rHeaterPowerZ2);
        rCircFanSpdZ2 := 50.0 + (rHeaterPowerZ2 * 0.5);
        PID_Z3(bEnable:=TRUE, rSetpoint:=rSetTempZone3, rFeedback:=rActTempZone3, rKp:=rKpZ3, rKi:=rKiZ3, rOutput=>rBurnerValveZ3);
        PID_Band(bEnable:=TRUE, rSetpoint:=rBandSpeedSet, rFeedback:=rBandSpeedAct, rKp:=rKpBand, rKi:=rKiBand, rOutput=>rBandDriveRef);

END_CASE
END_FUNCTION_BLOCK
