FUNCTION_BLOCK FB_RLV_CryoLoadingSequence
VAR_INPUT
    (* Required inputs *)
    bSystemEnable         : BOOL;  (* System enable signal from launch director *)
    bEmergencyStop        : BOOL;  (* Safety relay OK signal (E-Stop loop) *)
    rLoxTemp_K            : REAL;  (* LOX temperature in Kelvin (target 66K) *)
    rLch4Temp_K           : REAL;  (* LCH4 temperature in Kelvin (target 92K) *)
    rTankPressure_kPa     : REAL;  (* Vehicle tank ullage pressure in kPa *)
    bQdPlateMated         : BOOL;  (* Quick Disconnect plate securely mated *)
    bVentValvesOpen       : BOOL;  (* Vehicle vent valves position confirmation *)
    bHeliumSupplyOk       : BOOL;  (* Ground helium supply pressure nominal *)
END_VAR
VAR_OUTPUT
    (* Required outputs *)
    bSystemReady          : BOOL;  (* Densification system ready status *)
    rLoxFlowCommand       : REAL;  (* Commanded LOX flow rate (kg/s) *)
    rLch4FlowCommand      : REAL;  (* Commanded LCH4 flow rate (kg/s) *)
    bHeBubblerEnable      : BOOL;  (* Enable helium bubbling for geyser suppression *)
    bQdFlyawayTrigger     : BOOL;  (* Trigger signal for rapid QD disconnect *)
    bCriticalAlarm        : BOOL;  (* High priority fault alarm output *)
    iLoadingPhase         : INT;   (* Current sequence phase enum *)
END_VAR
VAR
    (* Internal state and timers *)
    iState                : INT := 0; (* State machine tracker *)
    tDensificationTimer   : TON;
    tGeyserTimer          : TON;
    tQdReleaseTimer       : TON;

    (* Internal calculations *)
    rDensificationRate    : REAL := 0.0;
    bLoxSubcooled         : BOOL := FALSE;
    bLch4Subcooled        : BOOL := FALSE;
    bOverpressureCondition: BOOL := FALSE;

    (* Constants *)
    c_LoxTargetTemp       : REAL := 66.5; (* Kelvin *)
    c_Lch4TargetTemp      : REAL := 92.0; (* Kelvin *)
    c_MaxUllagePress      : REAL := 450.0; (* kPa *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop OR NOT bQdPlateMated THEN
    bSystemReady := FALSE;
    rLoxFlowCommand := 0.0;
    rLch4FlowCommand := 0.0;
    bHeBubblerEnable := TRUE; (* Keep bubbling active on E-stop to prevent geysering while static *)
    bCriticalAlarm := TRUE;
    iState := 999; (* Transition to FAULT state *)
    RETURN;
END_IF;

bOverpressureCondition := (rTankPressure_kPa > c_MaxUllagePress);
IF bOverpressureCondition AND NOT bVentValvesOpen THEN
    bCriticalAlarm := TRUE;
    bHeBubblerEnable := FALSE;
    rLoxFlowCommand := 0.0;
    iState := 999;
    RETURN;
END_IF;

(* === MAIN SEQUENCE LOGIC === *)
CASE iState OF
    0: (* IDLE & PRE-CHECK *)
        bSystemReady := TRUE;
        bCriticalAlarm := FALSE;
        bHeBubblerEnable := FALSE;
        rLoxFlowCommand := 0.0;
        rLch4FlowCommand := 0.0;

        IF bSystemEnable AND bHeliumSupplyOk THEN
            iState := 10;
        END_IF;

    10: (* CHILLDOWN PHASE *)
        bHeBubblerEnable := TRUE; (* Initiate helium purge to suppress geysering during line chilldown *)
        rLoxFlowCommand := 2.5;   (* Low flow rate for chilldown *)
        rLch4FlowCommand := 1.8;  (* Low flow rate for chilldown *)

        tDensificationTimer(IN := TRUE, PT := T#120S);
        IF tDensificationTimer.Q THEN
            tDensificationTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RAPID FILL & DENSIFICATION PHASE *)
        rLoxFlowCommand := 25.0;  (* High flow rate for rapid fill *)
        rLch4FlowCommand := 15.0;

        bLoxSubcooled := (rLoxTemp_K <= c_LoxTargetTemp);
        bLch4Subcooled := (rLch4Temp_K <= c_Lch4TargetTemp);

        IF bLoxSubcooled AND bLch4Subcooled THEN
            iState := 30;
        END_IF;

    30: (* TOPPING & STABILIZATION PHASE *)
        rLoxFlowCommand := 1.0;   (* Trickle flow to maintain density *)
        rLch4FlowCommand := 0.8;
        bHeBubblerEnable := FALSE; (* Geysering risk minimal when fully subcooled *)

        IF NOT bSystemEnable THEN (* Launch sequence taking over, prepare for T-0 disconnect *)
            iState := 40;
        END_IF;

    40: (* T-0 RAPID DISCONNECT INITIATION *)
        rLoxFlowCommand := 0.0;
        rLch4FlowCommand := 0.0;
        bQdFlyawayTrigger := TRUE; (* Fire pyros/pneumatics for QD plate retract *)

        tQdReleaseTimer(IN := TRUE, PT := T#2S);
        IF tQdReleaseTimer.Q AND NOT bQdPlateMated THEN
            iState := 50; (* Fully disconnected *)
        END_IF;

    50: (* LIFTOFF COMPLETED *)
        bSystemReady := FALSE;
        bQdFlyawayTrigger := FALSE;

    999: (* FAULT HANDLER *)
        rLoxFlowCommand := 0.0;
        rLch4FlowCommand := 0.0;
        bQdFlyawayTrigger := FALSE;
        bSystemReady := FALSE;

        (* Require full reset of enable signal to clear fault *)
        IF NOT bSystemEnable AND bEmergencyStop THEN
            bCriticalAlarm := FALSE;
            iState := 0;
        END_IF;
END_CASE;

iLoadingPhase := iState;

END_FUNCTION_BLOCK
```

