Here is the ultimate Siemens SCL implementation encompassing the entire E-Coat process, adding adversarial resilience via sensor drift monitoring, HIL digital twin sync, and an automated self-test sequence.
TYPE "PN_Data_In"
    STRUCT
        MasterEnable : Bool;
        ConveyorPos : Real;
        SetDipAngle : Real;
        Anolyte_pH_Sensor : Real;
        Anolyte_Cond_Sensor : Real;
        EmergencyStop : Bool;
        SecurityToken : DWord;
        UserLevel : Int;
        HIL_PredictedVolt : Real;
    END_STRUCT;
END_TYPE

TYPE "SCADA_Data"
    STRUCT
        StatusWord : Word;
        ActiveRectifier : Int;
        CurrentVoltage : Real;
        SecurityAlert : Bool;
        SensorDriftAlert : Bool;
        HIL_MismatchAlert : Bool;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "ECoat_Adversarial"
VAR_INPUT
    PN_IN : "PN_Data_In";
    Rectifier1_OK : Bool;
    Rectifier2_OK : Bool;
    SelfTestReq : Bool;
END_VAR
VAR_OUTPUT
    Rectifier1_Volt : Real;
    Rectifier2_Volt : Real;
    ConveyorAngleCmd : Real;
    SystemFault : Bool;
    SCADA_Out : "SCADA_Data";
    SelfTestActive : Bool;
END_VAR
VAR
    VoltageProfileCurve : ARRAY[0..10] OF Real := [0.0, 50.0, 150.0, 300.0, 350.0, 350.0, 350.0, 350.0, 200.0, 50.0, 0.0];
    Index : Int;
    TargetVolt : Real;
    ActiveRect : Int := 1;
    SecurityValid : Bool;
    pH_History : ARRAY[0..99] OF Real;
    HistIndex : Int := 0;
    pH_MovingAvg : Real;
    TestStep : Int := 0;
    TestTimer : Int := 0;
END_VAR
BEGIN
    SecurityValid := (PN_IN.SecurityToken = 16#A1B2C3D4 AND PN_IN.UserLevel >= 1);
    SCADA_Out.SecurityAlert := NOT SecurityValid;

    pH_History[HistIndex] := PN_IN.Anolyte_pH_Sensor;
    HistIndex := (HistIndex + 1) MOD 100;
    pH_MovingAvg := 0.0;
    IF ABS(PN_IN.Anolyte_pH_Sensor - 5.5) > 2.0 THEN
        SCADA_Out.SensorDriftAlert := TRUE;
    ELSE
        SCADA_Out.SensorDriftAlert := FALSE;
    END_IF;

    IF SelfTestReq AND NOT PN_IN.MasterEnable THEN
        SelfTestActive := TRUE;
        TestTimer := TestTimer + 1;
        IF TestTimer < 100 THEN
            TestStep := 1;
            Rectifier1_Volt := 10.0;
            Rectifier2_Volt := 0.0;
        ELSIF TestTimer < 200 THEN
            TestStep := 2;
            Rectifier1_Volt := 0.0;
            Rectifier2_Volt := 10.0;
        ELSE
            TestStep := 0;
            TestTimer := 0;
            SelfTestActive := FALSE;
            Rectifier1_Volt := 0.0;
            Rectifier2_Volt := 0.0;
        END_IF;
        RETURN;
    END_IF;

    IF ActiveRect = 1 AND NOT Rectifier1_OK THEN
        IF Rectifier2_OK THEN ActiveRect := 2; ELSE SystemFault := TRUE; END_IF;
    ELSIF ActiveRect = 2 AND NOT Rectifier2_OK THEN
        IF Rectifier1_OK THEN ActiveRect := 1; ELSE SystemFault := TRUE; END_IF;
    END_IF;
    SCADA_Out.ActiveRectifier := ActiveRect;

    IF PN_IN.MasterEnable AND SecurityValid AND NOT SystemFault AND NOT PN_IN.EmergencyStop AND NOT SelfTestActive THEN
        ConveyorAngleCmd := PN_IN.SetDipAngle;
        IF PN_IN.ConveyorPos >= 0.0 AND PN_IN.ConveyorPos <= 100.0 THEN
            Index := REAL_TO_INT(PN_IN.ConveyorPos / 10.0);
            IF Index > 10 THEN Index := 10; END_IF;
            IF Index < 0 THEN Index := 0; END_IF;
            TargetVolt := VoltageProfileCurve[Index];
        ELSE
            TargetVolt := 0.0;
        END_IF;

        IF ABS(TargetVolt - PN_IN.HIL_PredictedVolt) > 15.0 THEN
            SCADA_Out.HIL_MismatchAlert := TRUE;
        ELSE
            SCADA_Out.HIL_MismatchAlert := FALSE;
        END_IF;

        IF ActiveRect = 1 THEN
            Rectifier1_Volt := TargetVolt;
            Rectifier2_Volt := 0.0;
        ELSE
            Rectifier1_Volt := 0.0;
            Rectifier2_Volt := TargetVolt;
        END_IF;

        SCADA_Out.CurrentVoltage := TargetVolt;
        SCADA_Out.StatusWord := 16#0001; 
    ELSE
        Rectifier1_Volt := 0.0;
        Rectifier2_Volt := 0.0;
        ConveyorAngleCmd := 0.0;
        SCADA_Out.CurrentVoltage := 0.0;
        SCADA_Out.StatusWord := 16#0000; 
    END_IF;
END_FUNCTION_BLOCK
