FUNCTION_BLOCK FB_DeepSeaHyperbaricMultiPhasePumping
VAR_INPUT
    bSystemEnable            : BOOL;     (* Master Subsea Control Module (SCM) Enable *)
    bESDKill                 : BOOL;     (* Emergency Shutdown SIL-3 Safety Loop Interlock *)
    rUmbilicalVoltage        : REAL;     (* Topside step-down voltage, feed-forward correction (kV) *)
    rSuctionPressure         : REAL;     (* Process suction manifold pressure (BarG) *)
    rDischargePressure       : REAL;     (* Process discharge pipeline pressure (BarG) *)
    rGasVolumeFraction       : REAL;     (* Optical multi-phase sensor GVF fraction (0.0 - 1.0) *)
    rMotorTemp               : REAL;     (* VFD Motor winding average temperature (degC) *)
    rImpellerVibration       : REAL;     (* Bearing proximity probe displacement (mm/s RMS) *)
END_VAR

VAR_OUTPUT
    bPumpRunning             : BOOL;     (* Station operational state confirmation *)
    rVFDCommandSpeed         : REAL;     (* Helico-axial motor requested speed (RPM) *)
    bBarrierFluidAlarm       : BOOL;     (* Mech seal barrier fluid anomaly warning *)
    bTripCommand             : BOOL;     (* Autonomous subsea trip command to SCM *)
    iOperatingState          : INT;      (* Internal state machine diagnostic broadcast *)
END_VAR

VAR
    iState                   : INT := 0; 
    tRunDelay                : TON;
    tTripTimer               : TON;
    rFilteredGVF             : REAL := 0.0;
    rGVFFilterAlpha          : REAL := 0.05; (* Low-pass filter constant for GVF noise *)
    rSlipCompensation        : REAL := 0.0;
    rVoltageDropCompensation : REAL := 0.0;
    rTargetRPM               : REAL := 0.0;

    (* Anti-Surge & Control Parameters *)
    MAX_VIBRATION            : REAL := 12.5; (* ISO-10816 class limit *)
    MAX_TEMP                 : REAL := 145.0;(* Winding insulation thermal limit *)
    MIN_SUCTION_PRESS        : REAL := 15.0;
    RATED_RPM                : REAL := 3600.0;
END_VAR

(* === MAIN LOGIC === *)
(* 1. CRITICAL SAFETY & INTERLOCKS *)
IF NOT bSystemEnable OR bESDKill THEN
    bPumpRunning := FALSE;
    rVFDCommandSpeed := 0.0;
    bTripCommand := bESDKill;
    iState := 0;
    iOperatingState := iState;
    RETURN;
END_IF;

(* 2. SENSOR CONDITIONING & NOISE FILTERING *)
(* Apply exponential moving average filter to chaotic multi-phase flow GVF readings *)
rFilteredGVF := (rGVFFilterAlpha * rGasVolumeFraction) + ((1.0 - rGVFFilterAlpha) * rFilteredGVF);

(* Process dynamic trip conditions *)
IF (rImpellerVibration > MAX_VIBRATION) OR (rMotorTemp > MAX_TEMP) OR (rSuctionPressure < MIN_SUCTION_PRESS) THEN
    tTripTimer(IN := TRUE, PT := T#2S);
ELSE
    tTripTimer(IN := FALSE);
END_IF;

IF tTripTimer.Q THEN
    bTripCommand := TRUE;
    iState := 99; (* FAULT STATE *)
END_IF;

(* 3. DYNAMIC STATE MACHINE *)
CASE iState OF
    0: (* STANDBY / IDLE *)
        bPumpRunning := FALSE;
        rVFDCommandSpeed := 0.0;
        bTripCommand := FALSE;
        IF bSystemEnable AND NOT bESDKill THEN
            iState := 10;
        END_IF;

    10: (* PRE-LUBE & UMBILICAL CHARGE *)
        (* Simulate 10-second barrier fluid & voltage stabilization *)
        tRunDelay(IN := TRUE, PT := T#10S);
        IF tRunDelay.Q THEN
            tRunDelay(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RAMP-UP & FLOW ESTABLISHMENT *)
        bPumpRunning := TRUE;
        (* Calculate umbilical voltage drop feed-forward:
           Compensates for long-tieback power transmission losses based on topside input *)
        rVoltageDropCompensation := (10.0 - rUmbilicalVoltage) * 50.0; 

        (* Calculate helico-axial slip flow compensation based on Gas Volume Fraction.
           Higher gas content creates impedance, requiring higher RPM to maintain delta-P *)
        rSlipCompensation := (rFilteredGVF * 500.0);

        rTargetRPM := (RATED_RPM * 0.5) + rSlipCompensation + rVoltageDropCompensation;

        (* Simple ramp generator (would be more complex in reality, but limits step changes) *)
        IF rVFDCommandSpeed < rTargetRPM THEN
            rVFDCommandSpeed := rVFDCommandSpeed + 5.0; 
        ELSE
            iState := 30;
        END_IF;

    30: (* STEADY-STATE MULTI-PHASE PRODUCTION *)
        bPumpRunning := TRUE;
        rVoltageDropCompensation := (10.0 - rUmbilicalVoltage) * 50.0; 
        rSlipCompensation := (rFilteredGVF * 800.0); (* Aggressive slip comp in steady state *)

        rTargetRPM := RATED_RPM + rSlipCompensation + rVoltageDropCompensation;

        (* Clamp speed to maximum safe operating limit *)
        IF rTargetRPM > 4200.0 THEN
            rTargetRPM := 4200.0;
        END_IF;

        rVFDCommandSpeed := rTargetRPM;

        (* Evaluate transition out of steady state if operator disables system *)
        IF NOT bSystemEnable THEN
            iState := 40;
        END_IF;

    40: (* RAMP-DOWN *)
        IF rVFDCommandSpeed > 0.0 THEN
            rVFDCommandSpeed := rVFDCommandSpeed - 10.0;
            IF rVFDCommandSpeed < 0.0 THEN
                rVFDCommandSpeed := 0.0;
            END_IF;
        ELSE
            bPumpRunning := FALSE;
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bPumpRunning := FALSE;
        rVFDCommandSpeed := 0.0;
        (* Requires full reset of bESDKill and bSystemEnable to exit fault state *)
        IF NOT bESDKill AND NOT bSystemEnable THEN
            bTripCommand := FALSE;
            iState := 0;
        END_IF;
END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
