FUNCTION_BLOCK FB_HTST_Pasteurization_Control
TITLE = 'HTST Milk Pasteurization Advanced Control and FDV Interlock'
VERSION : '1.0'

VAR_INPUT
    bEnable : BOOL;
    bReset : BOOL;
    rRawMilkTemp : REAL;
    rHeatedMilkTemp : REAL;
    rHoldingTubeTemp : REAL;
    rCoolingOutTemp : REAL;
    rTargetPasteurizeTemp : REAL := 72.0;
    rHoldingTimeTarget : REAL := 15.0;
    rFlowRate : REAL;
    rHomogenizerPress1 : REAL;
    rHomogenizerPress2 : REAL;
    rHomogenizerTargetPress1: REAL := 150.0;
    rHomogenizerTargetPress2: REAL := 30.0;
    bCIP_Mode : BOOL;
END_VAR

VAR_OUTPUT
    bFDV_ForwardFlow : BOOL;
    rSteamValveCmd : REAL;
    rChilledWaterValveCmd : REAL;
    bHomogenizerRunCmd : BOOL;
    bAlarmPasteurizeTempLow : BOOL;
    bAlarmFlowRateHigh : BOOL;
    bAlarmHomogenizerPress : BOOL;
    bProcessReady : BOOL;
    iState : INT;
END_VAR

VAR
    State_Idle : INT := 0;
    State_WaterCirculation : INT := 10;
    State_HeatingUp : INT := 20;
    State_Production : INT := 30;
    State_Diverted : INT := 40;
    State_CIP : INT := 50;
    State_Fault : INT := 99;
    rHeatError : REAL;
    rHeatIntegral : REAL;
    rHeatKp : REAL := 2.5;
    rHeatKi : REAL := 0.1;
    rCoolError : REAL;
    rCoolIntegral : REAL;
    rCoolKp : REAL := 3.0;
    rCoolKi : REAL := 0.15;
    rTargetCoolTemp : REAL := 4.0;
    tHoldingTimer : TON;
    tDivertDelay : TON;
    tHomogenizerAlarmDelay : TON;
    bLegalTempReached : BOOL;
    bHoldingTimeSatisfied : BOOL;
    rCalculatedHoldingTime : REAL;
    rHoldingTubeVolume : REAL := 25.0;
END_VAR

IF bReset THEN
    bAlarmPasteurizeTempLow := FALSE;
    bAlarmFlowRateHigh := FALSE;
    bAlarmHomogenizerPress := FALSE;
    iState := State_Idle;
END_IF;

IF bCIP_Mode THEN
    iState := State_CIP;
END_IF;

IF rFlowRate > 0.0 THEN
    rCalculatedHoldingTime := (rHoldingTubeVolume / (rFlowRate/3600.0));
ELSE
    rCalculatedHoldingTime := 999.0;
END_IF;

IF rCalculatedHoldingTime < rHoldingTimeTarget AND bEnable THEN
    bAlarmFlowRateHigh := TRUE;
ELSE
    bAlarmFlowRateHigh := FALSE;
END_IF;

IF ABS(rHomogenizerPress1 - rHomogenizerTargetPress1) > 20.0 OR ABS(rHomogenizerPress2 - rHomogenizerTargetPress2) > 10.0 THEN
    tHomogenizerAlarmDelay(IN := bEnable AND bHomogenizerRunCmd, PT := T#5S);
    IF tHomogenizerAlarmDelay.Q THEN
        bAlarmHomogenizerPress := TRUE;
    END_IF;
ELSE
    tHomogenizerAlarmDelay(IN := FALSE);
END_IF;

bLegalTempReached := (rHoldingTubeTemp >= rTargetPasteurizeTemp);

CASE iState OF
    State_Idle:
        bFDV_ForwardFlow := FALSE;
        rSteamValveCmd := 0.0;
        rChilledWaterValveCmd := 0.0;
        bHomogenizerRunCmd := FALSE;
        bProcessReady := FALSE;
        IF bEnable AND NOT bCIP_Mode THEN iState := State_WaterCirculation; END_IF;
    State_WaterCirculation:
        bFDV_ForwardFlow := FALSE;
        iState := State_HeatingUp;
    State_HeatingUp:
        IF bLegalTempReached THEN
            bProcessReady := TRUE;
            iState := State_Production;
        END_IF;
        IF NOT bEnable THEN iState := State_Idle; END_IF;
    State_Production:
        bProcessReady := TRUE;
        bHomogenizerRunCmd := TRUE;
        IF bLegalTempReached AND NOT bAlarmFlowRateHigh THEN
            bFDV_ForwardFlow := TRUE;
            bAlarmPasteurizeTempLow := FALSE;
        ELSE
            bFDV_ForwardFlow := FALSE;
            bAlarmPasteurizeTempLow := TRUE;
            iState := State_Diverted;
        END_IF;
        IF NOT bEnable THEN iState := State_Idle; END_IF;
    State_Diverted:
        bFDV_ForwardFlow := FALSE;
        bHomogenizerRunCmd := TRUE;
        IF bLegalTempReached AND NOT bAlarmFlowRateHigh THEN
            tDivertDelay(IN := TRUE, PT := T#20S);
            IF tDivertDelay.Q THEN
                tDivertDelay(IN := FALSE);
                iState := State_Production;
            END_IF;
        ELSE
            tDivertDelay(IN := FALSE);
        END_IF;
        IF NOT bEnable THEN iState := State_Idle; END_IF;
    State_CIP:
        bFDV_ForwardFlow := TRUE;
        bHomogenizerRunCmd := TRUE;
        rSteamValveCmd := 80.0;
        rChilledWaterValveCmd := 0.0;
        IF NOT bCIP_Mode THEN iState := State_Idle; END_IF;
    State_Fault:
        bFDV_ForwardFlow := FALSE;
        rSteamValveCmd := 0.0;
        rChilledWaterValveCmd := 0.0;
        bHomogenizerRunCmd := FALSE;
        IF bReset THEN iState := State_Idle; END_IF;
    ELSE
        iState := State_Fault;
END_CASE;

IF (iState = State_HeatingUp OR iState = State_Production OR iState = State_Diverted) THEN
    rHeatError := rTargetPasteurizeTemp + 1.0 - rHeatedMilkTemp;
    rHeatIntegral := rHeatIntegral + (rHeatError * 0.1);
    IF rHeatIntegral > 100.0 THEN rHeatIntegral := 100.0; END_IF;
    IF rHeatIntegral < 0.0 THEN rHeatIntegral := 0.0; END_IF;
    rSteamValveCmd := (rHeatKp * rHeatError) + (rHeatKi * rHeatIntegral);
    IF rSteamValveCmd > 100.0 THEN rSteamValveCmd := 100.0; END_IF;
    IF rSteamValveCmd < 0.0 THEN rSteamValveCmd := 0.0; END_IF;
END_IF;

IF iState = State_Production THEN
    rCoolError := rCoolingOutTemp - rTargetCoolTemp;
    rCoolIntegral := rCoolIntegral + (rCoolError * 0.1);
    IF rCoolIntegral > 100.0 THEN rCoolIntegral := 100.0; END_IF;
    IF rCoolIntegral < 0.0 THEN rCoolIntegral := 0.0; END_IF;
    rChilledWaterValveCmd := (rCoolKp * rCoolError) + (rCoolKi * rCoolIntegral);
    IF rChilledWaterValveCmd > 100.0 THEN rChilledWaterValveCmd := 100.0; END_IF;
    IF rChilledWaterValveCmd < 0.0 THEN rChilledWaterValveCmd := 0.0; END_IF;
ELSE
    rChilledWaterValveCmd := 0.0;
    rCoolIntegral := 0.0;
END_IF;
END_FUNCTION_BLOCK
