FUNCTION_BLOCK FB_HPHT_DiamondPressControl
TITLE = 'HPHT Synthetic Diamond Press Controller'
VERSION : '1.0'
AUTHOR : 'Lumina Swarm'
FAMILY : 'HPHT'

VAR_INPUT
    bStartCycle : BOOL; (* Start the pressing cycle *)
    bEmergencyStop : BOOL; (* Emergency stop trigger *)
    rTargetPressure : REAL; (* Target hydraulic pressure in GPa *)
    rTargetTemperature : REAL; (* Target temperature in Celsius *)
    rPressureRampRate : REAL; (* Pressure ramp rate in GPa/min *)
    rTemperatureRampRate : REAL; (* Temp ramp rate in Celsius/min *)
    rHoldTime : REAL; (* Hold time at target conditions in hours *)
    rCoolingRate : REAL; (* Cooling rate in Celsius/min for crystallization *)
    rCurrentPressure : REAL; (* Sensor feedback: Current pressure *)
    rCurrentTemperature : REAL; (* Sensor feedback: Current temperature *)
END_VAR

VAR_OUTPUT
    bHeatingElementOn : BOOL;
    rHeatingPowerCmd : REAL; (* 0.0 to 100.0% *)
    bHydraulicPumpOn : BOOL;
    rHydraulicValveCmd : REAL; (* 0.0 to 100.0% *)
    bCoolingSystemOn : BOOL;
    rCoolingValveCmd : REAL; (* 0.0 to 100.0% *)
    nCurrentState : INT; (* 0: Idle, 1: Pressurizing, 2: Heating, 3: Holding, 4: Cooling, 5: Depressurizing, 99: Fault *)
    bCycleComplete : BOOL;
    bFault : BOOL;
    sFaultMessage : STRING[50];
END_VAR

VAR
    tCycleTimer : TON;
    tStepTimer : TON;
    rInternalTargetPressure : REAL;
    rInternalTargetTemp : REAL;
    dtStartTime : DATE_AND_TIME;
    rPID_Press_Kp : REAL := 2.5;
    rPID_Press_Ki : REAL := 0.5;
    rPID_Press_Kd : REAL := 0.1;
    rPID_Temp_Kp : REAL := 5.0;
    rPID_Temp_Ki : REAL := 0.8;
    rPID_Temp_Kd : REAL := 0.2;
    rPressError : REAL;
    rTempError : REAL;
    rPressIntegral : REAL;
    rTempIntegral : REAL;
    rLastPressError : REAL;
    rLastTempError : REAL;
    bInitialize : BOOL := TRUE;
    rHoldTimerAccum : REAL;
END_VAR

(* Implementation *)
IF bEmergencyStop THEN
    nCurrentState := 99;
    bHeatingElementOn := FALSE;
    rHeatingPowerCmd := 0.0;
    bHydraulicPumpOn := FALSE;
    rHydraulicValveCmd := 0.0;
    bCoolingSystemOn := TRUE;
    rCoolingValveCmd := 100.0;
    bFault := TRUE;
    sFaultMessage := 'EMERGENCY STOP TRIGGERED';
    RETURN;
END_IF;

IF bInitialize THEN
    nCurrentState := 0;
    rInternalTargetPressure := 0.0;
    rInternalTargetTemp := 25.0;
    bCycleComplete := FALSE;
    bFault := FALSE;
    sFaultMessage := '';
    rPressIntegral := 0.0;
    rTempIntegral := 0.0;
    bInitialize := FALSE;
END_IF;

CASE nCurrentState OF
    0: (* Idle *)
        bHeatingElementOn := FALSE;
        rHeatingPowerCmd := 0.0;
        bHydraulicPumpOn := FALSE;
        rHydraulicValveCmd := 0.0;
        bCoolingSystemOn := FALSE;
        rCoolingValveCmd := 0.0;
        IF bStartCycle AND NOT bFault THEN
            nCurrentState := 1; (* Move to Pressurizing *)
            bCycleComplete := FALSE;
            rInternalTargetPressure := rCurrentPressure;
            bHydraulicPumpOn := TRUE;
        END_IF;

    1: (* Pressurizing: Anvil hydraulic pressure ramping *)
        rInternalTargetPressure := rInternalTargetPressure + (rPressureRampRate / 60.0); (* Assuming 1 sec execution cycle for simplicity, scaling ramp rate *)
        IF rInternalTargetPressure >= rTargetPressure THEN
            rInternalTargetPressure := rTargetPressure;
            IF ABS(rCurrentPressure - rTargetPressure) < 0.1 THEN
                nCurrentState := 2; (* Move to Heating *)
                rInternalTargetTemp := rCurrentTemperature;
                bHeatingElementOn := TRUE;
            END_IF;
        END_IF;

        (* Pressure PID Control *)
        rPressError := rInternalTargetPressure - rCurrentPressure;
        rPressIntegral := rPressIntegral + rPressError;
        rHydraulicValveCmd := (rPID_Press_Kp * rPressError) + (rPID_Press_Ki * rPressIntegral) + (rPID_Press_Kd * (rPressError - rLastPressError));
        rLastPressError := rPressError;

        IF rHydraulicValveCmd > 100.0 THEN rHydraulicValveCmd := 100.0; END_IF;
        IF rHydraulicValveCmd < 0.0 THEN rHydraulicValveCmd := 0.0; END_IF;

    2: (* Heating: Carbon source temperature profiling *)
        rInternalTargetTemp := rInternalTargetTemp + (rTemperatureRampRate / 60.0);
        IF rInternalTargetTemp >= rTargetTemperature THEN
            rInternalTargetTemp := rTargetTemperature;
            IF ABS(rCurrentTemperature - rTargetTemperature) < 5.0 THEN
                nCurrentState := 3; (* Move to Holding *)
                rHoldTimerAccum := 0.0;
            END_IF;
        END_IF;

        (* Temperature PID Control *)
        rTempError := rInternalTargetTemp - rCurrentTemperature;
        rTempIntegral := rTempIntegral + rTempError;
        rHeatingPowerCmd := (rPID_Temp_Kp * rTempError) + (rPID_Temp_Ki * rTempIntegral) + (rPID_Temp_Kd * (rTempError - rLastTempError));
        rLastTempError := rTempError;

        IF rHeatingPowerCmd > 100.0 THEN rHeatingPowerCmd := 100.0; END_IF;
        IF rHeatingPowerCmd < 0.0 THEN rHeatingPowerCmd := 0.0; END_IF;

        (* Maintain Pressure during heating *)
        rPressError := rTargetPressure - rCurrentPressure;
        rPressIntegral := rPressIntegral + rPressError;
        rHydraulicValveCmd := (rPID_Press_Kp * rPressError) + (rPID_Press_Ki * rPressIntegral) + (rPID_Press_Kd * (rPressError - rLastPressError));
        rLastPressError := rPressError;

    3: (* Holding: Maintain both pressure and temp *)
        rHoldTimerAccum := rHoldTimerAccum + (1.0 / 3600.0); (* Increment hours, assuming 1s execution loop *)

        IF rHoldTimerAccum >= rHoldTime THEN
            nCurrentState := 4; (* Move to Cooling *)
            bHeatingElementOn := FALSE;
            rHeatingPowerCmd := 0.0;
            bCoolingSystemOn := TRUE;
        END_IF;

        (* Continue PID Control for both to maintain steady state *)
        rTempError := rTargetTemperature - rCurrentTemperature;
        rTempIntegral := rTempIntegral + rTempError;
        rHeatingPowerCmd := (rPID_Temp_Kp * rTempError) + (rPID_Temp_Ki * rTempIntegral);

        rPressError := rTargetPressure - rCurrentPressure;
        rPressIntegral := rPressIntegral + rPressError;
        rHydraulicValveCmd := (rPID_Press_Kp * rPressError) + (rPID_Press_Ki * rPressIntegral);

    4: (* Cooling: Controlled cooling rate for crystallization *)
        rInternalTargetTemp := rInternalTargetTemp - (rCoolingRate / 60.0);
        IF rInternalTargetTemp <= 25.0 THEN (* Ambient target *)
            rInternalTargetTemp := 25.0;
            IF rCurrentTemperature <= 30.0 THEN
                nCurrentState := 5; (* Move to Depressurizing *)
                bCoolingSystemOn := FALSE;
                rCoolingValveCmd := 0.0;
            END_IF;
        END_IF;

        (* Cooling Valve Control *)
        rTempError := rCurrentTemperature - rInternalTargetTemp; (* Positive error means too hot *)
        rCoolingValveCmd := rTempError * 2.0; (* Simple P control for cooling valve *)
        IF rCoolingValveCmd > 100.0 THEN rCoolingValveCmd := 100.0; END_IF;
        IF rCoolingValveCmd < 0.0 THEN rCoolingValveCmd := 0.0; END_IF;

        (* Maintain Pressure during cooling *)
        rPressError := rTargetPressure - rCurrentPressure;
        rPressIntegral := rPressIntegral + rPressError;
        rHydraulicValveCmd := (rPID_Press_Kp * rPressError) + (rPID_Press_Ki * rPressIntegral);

    5: (* Depressurizing *)
        rInternalTargetPressure := rInternalTargetPressure - (rPressureRampRate / 60.0);
        IF rInternalTargetPressure <= 0.1 THEN
            rInternalTargetPressure := 0.0;
            IF rCurrentPressure <= 0.1 THEN
                nCurrentState := 0; (* Cycle Complete, return to Idle *)
                bCycleComplete := TRUE;
                bHydraulicPumpOn := FALSE;
                rHydraulicValveCmd := 0.0;
            END_IF;
        END_IF;

        (* Pressure Release Control *)
        rPressError := rInternalTargetPressure - rCurrentPressure;
        rHydraulicValveCmd := (rPID_Press_Kp * rPressError); (* Simple P control for depressurization *)
        IF rHydraulicValveCmd < 0.0 THEN rHydraulicValveCmd := 0.0; END_IF;

    99: (* Fault State *)
        bFault := TRUE;
        bHeatingElementOn := FALSE;
        rHeatingPowerCmd := 0.0;
        bHydraulicPumpOn := FALSE;
        rHydraulicValveCmd := 0.0;
        bCoolingSystemOn := TRUE;
        rCoolingValveCmd := 100.0; (* Max cooling during fault *)
END_CASE;
END_FUNCTION_BLOCK
```

