FUNCTION_BLOCK FB_AmmunitionPressControl
VAR_INPUT
    bEnable : BOOL; // System enable
    bEstop : BOOL; // Emergency stop active low
    bReset : BOOL; // Reset faults

    // Servo Encoders
    rRotaryIndexPos : REAL; // Degrees (0-360)

    // Sensors
    bPrimerPresent : BOOL;
    rPrimerSeatingDepth : REAL; // mm from laser sensor
    rPowderMassFeedback : REAL; // mg from load cell
    bBulletPresent : BOOL;

    // Setpoints
    rTargetPowderMass : REAL; // mg
    rPowderMassTolerance : REAL; // mg
    rPrimerDepthTarget : REAL; // mm
    rPrimerDepthTolerance : REAL; // mm
    rIndexSpeed : REAL; // Deg/s
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bFaultActive : BOOL;
    iFaultCode : INT;

    // Actuators
    bIndexMotorEnable : BOOL;
    rIndexMotorSpeedCmd : REAL;
    bPrimerInsertPneumatic : BOOL;
    rPowderValvePosition : REAL; // 0-100%
    bBulletSeatingPneumatic : BOOL;
    bEjectGood : BOOL;
    bEjectReject : BOOL;

    // Stats
    iTotalProduced : DINT;
    iTotalRejected : DINT;
END_VAR

VAR
    eState : (INIT, IDLE, INDEXING, DOSING_AND_SEATING, INSPECTION, EJECT, FAULT);
    iCurrentStation : INT := 0; // 0 to 7 for 8-station press
    tDosingTimer : TON;
    tSeatingTimer : TON;
    tEjectTimer : TON;

    rTargetIndexPos : REAL;
    bPrimerDepthOk : BOOL;
    bPowderMassOk : BOOL;
    bCurrentCycleFailed : BOOL;

    rPID_Kp : REAL := 0.5;
    rPID_Ki : REAL := 0.1;
    rPowderError : REAL;
    rPowderIntegral : REAL;
END_VAR

// Main State Machine
IF NOT bEstop THEN
    eState := FAULT;
    iFaultCode := 1; // E-Stop
END_IF

IF eState = FAULT AND bReset AND bEstop THEN
    eState := INIT;
    bFaultActive := FALSE;
    iFaultCode := 0;
END_IF

CASE eState OF
    INIT:
        bIndexMotorEnable := FALSE;
        rIndexMotorSpeedCmd := 0.0;
        bPrimerInsertPneumatic := FALSE;
        rPowderValvePosition := 0.0;
        bBulletSeatingPneumatic := FALSE;
        bEjectGood := FALSE;
        bEjectReject := FALSE;
        IF bEnable THEN
            eState := IDLE;
            bSystemReady := TRUE;
        END_IF

    IDLE:
        bSystemReady := TRUE;
        bCurrentCycleFailed := FALSE;
        IF bEnable THEN
            eState := INDEXING;
            rTargetIndexPos := rRotaryIndexPos + 45.0; // 8 stations
            IF rTargetIndexPos >= 360.0 THEN
                rTargetIndexPos := rTargetIndexPos - 360.0;
            END_IF
        END_IF

    INDEXING:
        bIndexMotorEnable := TRUE;
        rIndexMotorSpeedCmd := rIndexSpeed;
        // Simplified position control
        IF ABS(rRotaryIndexPos - rTargetIndexPos) < 0.5 THEN
            rIndexMotorSpeedCmd := 0.0;
            eState := DOSING_AND_SEATING;
            tDosingTimer(IN := FALSE);
            tSeatingTimer(IN := FALSE);
        END_IF

    DOSING_AND_SEATING:
        // Micro-dosing powder with PI control
        rPowderError := rTargetPowderMass - rPowderMassFeedback;
        rPowderIntegral := rPowderIntegral + rPowderError * 0.01; // Assuming 10ms cycle
        rPowderValvePosition := (rPowderError * rPID_Kp) + (rPowderIntegral * rPID_Ki);

        IF rPowderValvePosition > 100.0 THEN rPowderValvePosition := 100.0; END_IF
        IF rPowderValvePosition < 0.0 THEN rPowderValvePosition := 0.0; END_IF

        bPrimerInsertPneumatic := TRUE;
        bBulletSeatingPneumatic := TRUE;

        tDosingTimer(IN := TRUE, PT := T#500MS);
        tSeatingTimer(IN := TRUE, PT := T#400MS);

        IF tDosingTimer.Q AND tSeatingTimer.Q THEN
            rPowderValvePosition := 0.0;
            bPrimerInsertPneumatic := FALSE;
            bBulletSeatingPneumatic := FALSE;
            eState := INSPECTION;
        END_IF

    INSPECTION:
        // Laser primer seating inspection
        bPrimerDepthOk := ABS(rPrimerSeatingDepth - rPrimerDepthTarget) <= rPrimerDepthTolerance;
        bPowderMassOk := ABS(rPowderMassFeedback - rTargetPowderMass) <= rPowderMassTolerance;

        IF NOT bPrimerDepthOk OR NOT bPowderMassOk OR NOT bPrimerPresent OR NOT bBulletPresent THEN
            bCurrentCycleFailed := TRUE;
        END_IF

        eState := EJECT;
        tEjectTimer(IN := FALSE);

    EJECT:
        tEjectTimer(IN := TRUE, PT := T#200MS);
        IF bCurrentCycleFailed THEN
            bEjectReject := TRUE;
            bEjectGood := FALSE;
        ELSE
            bEjectGood := TRUE;
            bEjectReject := FALSE;
        END_IF

        IF tEjectTimer.Q THEN
            bEjectGood := FALSE;
            bEjectReject := FALSE;
            IF bCurrentCycleFailed THEN
                iTotalRejected := iTotalRejected + 1;
            ELSE
                iTotalProduced := iTotalProduced + 1;
            END_IF
            eState := IDLE;
        END_IF

    FAULT:
        bSystemReady := FALSE;
        bFaultActive := TRUE;
        bIndexMotorEnable := FALSE;
        rPowderValvePosition := 0.0;
        bPrimerInsertPneumatic := FALSE;
        bBulletSeatingPneumatic := FALSE;
END_CASE

END_FUNCTION_BLOCK
```

