FUNCTION_BLOCK "Ozone_FeedGas_Control"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
    Dew_Point : REAL;
    Compressor_1_Ok : BOOL;
    Compressor_2_Ok : BOOL;
END_VAR
VAR_OUTPUT
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    Compressor_1_Run : BOOL;
    Compressor_2_Run : BOOL;
    DewPoint_Alarm : BOOL;
    System_Fault : BOOL;
END_VAR
VAR
    Run_Cmd : BOOL;
    PID_Out : REAL;
    Duty_Cycle : BOOL;
END_VAR

BEGIN
    // Feed Gas Dew Point Monitoring (must be < -60 C)
    DewPoint_Alarm := Dew_Point > -60.0;

    // Start/Stop Logic
    IF Start AND NOT Stop AND NOT DewPoint_Alarm THEN
        Run_Cmd := TRUE;
    ELSIF Stop OR DewPoint_Alarm THEN
        Run_Cmd := FALSE;
    END_IF;

    // Compressor Sequencing (Lead/Lag)
    IF Run_Cmd THEN
        IF Compressor_1_Ok AND NOT Duty_Cycle THEN
            Compressor_1_Run := TRUE;
            Compressor_2_Run := FALSE;
        ELSIF Compressor_2_Ok AND Duty_Cycle THEN
            Compressor_2_Run := TRUE;
            Compressor_1_Run := FALSE;
        ELSE
            Compressor_1_Run := Compressor_1_Ok;
            Compressor_2_Run := Compressor_2_Ok;
        END_IF;
    ELSE
        Compressor_1_Run := FALSE;
        Compressor_2_Run := FALSE;
    END_IF;

    Generator_Enable := Run_Cmd AND (Compressor_1_Run OR Compressor_2_Run);

    // O3 Control Loop
    IF Generator_Enable THEN
        IF O3_Actual < O3_SetPoint THEN
            PID_Out := PID_Out + 0.5;
        ELSIF O3_Actual > O3_SetPoint THEN
            PID_Out := PID_Out - 0.5;
        END_IF;

        IF PID_Out > 100.0 THEN PID_Out := 100.0; END_IF;
        IF PID_Out < 0.0 THEN PID_Out := 0.0; END_IF;
        Power_Scale_Out := PID_Out;
    ELSE
        Power_Scale_Out := 0.0;
    END_IF;

    System_Fault := DewPoint_Alarm OR (NOT Compressor_1_Ok AND NOT Compressor_2_Ok);
END_FUNCTION_BLOCK
