FUNCTION_BLOCK FB_RoverSuspensionControl
VAR_INPUT
    bEnable : BOOL;                     (* Enable control system *)
    rRoverSpeed : REAL;                 (* Current rover speed (m/s) *)
    rTargetSpeed : REAL;                (* Target rover speed (m/s) *)
    arWheelRPM : ARRAY[1..6] OF REAL;   (* RPM of the 6 wheels *)
    arWheelTorque : ARRAY[1..6] OF REAL;(* Current torque of 6 wheels (Nm) *)
    arBogieAngle : ARRAY[1..2] OF REAL; (* Angle of port and starboard bogies (rad) *)
    arRockerAngle : ARRAY[1..2] OF REAL;(* Angle of port and starboard rockers (rad) *)
    rAmbientTemp : REAL;                (* Ambient temperature (K) *)
    rIMUPitch : REAL;                   (* Rover pitch (rad) *)
    rIMURoll : REAL;                    (* Rover roll (rad) *)
    arStrutForce : ARRAY[1..6] OF REAL; (* Force on active struts (N) *)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bThermalWarning : BOOL;
    bSlipWarning : BOOL;
    arTargetTorque : ARRAY[1..6] OF REAL;
    arStrutCommand : ARRAY[1..6] OF REAL; (* Displacement command for struts (m) *)
    nSystemState : INT;
END_VAR

VAR
    rWheelRadius : REAL := 0.25; (* m *)
    rMaxTorque : REAL := 500.0; (* Nm *)
    rMaxTemp : REAL := 220.0; (* Max nominal temp K *)
    rMinTemp : REAL := 120.0; (* Min nominal temp K *)
    rThermalDerating : REAL := 1.0;

    i : INT;
    rActualVel : REAL;
    arSlipRatio : ARRAY[1..6] OF REAL;
    rAverageSlip : REAL;
    rTargetSuspensionHeight : REAL := 0.5;
    rPitchCorrection : REAL;
    rRollCorrection : REAL;

    TMR_ThermalCheck : TON;
    TMR_SlipCheck : TON;
    bInit : BOOL := FALSE;
END_VAR

IF NOT bInit THEN
    nSystemState := 0;
    bSystemReady := FALSE;
    bInit := TRUE;
END_IF;

IF NOT bEnable THEN
    nSystemState := 0;
    bSystemReady := FALSE;
    FOR i := 1 TO 6 DO
        arTargetTorque[i] := 0.0;
        arStrutCommand[i] := 0.0;
    END_FOR;
    RETURN;
END_IF;

bSystemReady := TRUE;
nSystemState := 1;

(* Thermal Protection Logic *)
TMR_ThermalCheck(IN:=TRUE, PT:=T#1S);
IF TMR_ThermalCheck.Q THEN
    TMR_ThermalCheck(IN:=FALSE);
    IF rAmbientTemp < rMinTemp THEN
        rThermalDerating := 0.5; (* Limit power in extreme cold *)
        bThermalWarning := TRUE;
    ELSIF rAmbientTemp > rMaxTemp THEN
        rThermalDerating := 0.7; (* Limit power in extreme heat *)
        bThermalWarning := TRUE;
    ELSE
        rThermalDerating := 1.0;
        bThermalWarning := FALSE;
    END_IF;
END_IF;

(* Wheel Slip Calculation and Traction Control *)
rAverageSlip := 0.0;
FOR i := 1 TO 6 DO
    rActualVel := arWheelRPM[i] * 3.14159 / 30.0 * rWheelRadius;
    IF rRoverSpeed > 0.01 THEN
        arSlipRatio[i] := (rActualVel - rRoverSpeed) / rRoverSpeed;
    ELSE
        arSlipRatio[i] := 0.0;
    END_IF;

    rAverageSlip := rAverageSlip + arSlipRatio[i];

    (* Traction Control: Adjust torque based on slip and thermal derating *)
    IF arSlipRatio[i] > 0.2 THEN
        arTargetTorque[i] := rMaxTorque * rThermalDerating * 0.5; (* Reduce torque if slipping *)
    ELSE
        arTargetTorque[i] := rMaxTorque * rThermalDerating * (rTargetSpeed - rRoverSpeed) * 0.1; 
    END_IF;

    IF arTargetTorque[i] > rMaxTorque THEN
        arTargetTorque[i] := rMaxTorque;
    END_IF;
    IF arTargetTorque[i] < -rMaxTorque THEN
        arTargetTorque[i] := -rMaxTorque;
    END_IF;
END_FOR;
rAverageSlip := rAverageSlip / 6.0;

TMR_SlipCheck(IN:=(rAverageSlip > 0.15), PT:=T#2S);
IF TMR_SlipCheck.Q THEN
    bSlipWarning := TRUE;
ELSE
    bSlipWarning := FALSE;
END_IF;

(* Active Suspension / Rocker-Bogie Terrain Adaptation *)
(* Calculate pitch and roll compensations *)
rPitchCorrection := rIMUPitch * 0.5; (* Proportional gain for pitch *)
rRollCorrection := rIMURoll * 0.5;   (* Proportional gain for roll *)

FOR i := 1 TO 6 DO
    (* Base calculation based on IMU for leveling *)
    IF i <= 3 THEN (* Left side *)
        arStrutCommand[i] := rTargetSuspensionHeight + rRollCorrection;
    ELSE (* Right side *)
        arStrutCommand[i] := rTargetSuspensionHeight - rRollCorrection;
    END_IF;

    (* Pitch correction - front vs back *)
    IF i = 1 OR i = 4 THEN (* Front wheels *)
        arStrutCommand[i] := arStrutCommand[i] - rPitchCorrection;
    ELSIF i = 3 OR i = 6 THEN (* Rear wheels *)
        arStrutCommand[i] := arStrutCommand[i] + rPitchCorrection;
    END_IF;

    (* Individual wheel load balancing using strut forces *)
    IF arStrutForce[i] > 1000.0 THEN (* Excessive load *)
        arStrutCommand[i] := arStrutCommand[i] + 0.05; (* Retract strut slightly *)
    ELSIF arStrutForce[i] < 200.0 THEN (* Loss of ground contact *)
        arStrutCommand[i] := arStrutCommand[i] - 0.05; (* Extend strut *)
    END_IF;

    (* Apply limits to strut commands *)
    IF arStrutCommand[i] > 0.8 THEN
        arStrutCommand[i] := 0.8;
    ELSIF arStrutCommand[i] < 0.2 THEN
        arStrutCommand[i] := 0.2;
    END_IF;
END_FOR;

END_FUNCTION_BLOCK
