FUNCTION_BLOCK "AGV_Traffic_Controller"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      agv_Position : Int;
      agv_BatteryLvl : Real;
      agv_DestNode : Int;
      agv_PayloadWeight : Real;
      node_Occupied : Array[1..20] of Bool;
      pn_CommStatus : Bool;
   END_VAR

   VAR_OUTPUT 
      agv_GoToNode : Int;
      agv_SpeedCmd : Real;
      charge_Req : Bool;
      error_Sts : Bool;
      diag_Code : Word;
      pn_StatusWord : Word;
   END_VAR

   VAR 
      route_State : Int;
      next_Node : Int;
      diag_Active : Bool;
   END_VAR

   VAR_TEMP 
      max_Speed : Real;
      path_Found : Bool;
   END_VAR

BEGIN
    #diag_Code := 16#0000;

    // Profinet Communication & Diagnostics
    IF NOT #pn_CommStatus THEN
        #agv_SpeedCmd := 0.0;
        #diag_Code := 16#E001; // PN Comm Error
        #error_Sts := TRUE;
        RETURN;
    END_IF;

    // Dynamic Weight-Based Speed Limiting
    IF #agv_PayloadWeight > 1000.0 THEN
        #max_Speed := 0.5;
    ELSIF #agv_PayloadWeight > 500.0 THEN
        #max_Speed := 1.0;
    ELSE
        #max_Speed := 2.0;
    END_IF;

    // Battery Scheduling
    IF #agv_BatteryLvl < 20.0 THEN
        #charge_Req := TRUE;
        #agv_DestNode := 1; 
        #diag_Code := 16#I001; // Charging mode
    ELSIF #agv_BatteryLvl > 95.0 THEN
        #charge_Req := FALSE;
    END_IF;

    // Dynamic Path Routing & Collision Avoidance
    #path_Found := FALSE;
    #next_Node := #agv_Position + 1; 

    IF #next_Node <= 20 THEN
        IF NOT #node_Occupied[#next_Node] THEN
            #agv_GoToNode := #next_Node;
            #agv_SpeedCmd := #max_Speed; 
            #path_Found := TRUE;
        ELSE
            #agv_SpeedCmd := 0.0; 
            #path_Found := FALSE;
            #diag_Code := 16#W001; // Blocked path
        END_IF;
    END_IF;

    // Error handling
    #error_Sts := (NOT #path_Found AND #agv_Position <> #agv_DestNode);
    IF #error_Sts THEN #diag_Code := 16#E002; END_IF;

    // Profinet Status Mapping
    #pn_StatusWord.%X0 := #error_Sts;
    #pn_StatusWord.%X1 := #charge_Req;
    #pn_StatusWord.%X2 := #path_Found;
END_FUNCTION_BLOCK
