Here is the master-tier, production-ready IEC 61131-3 Structured Text (ST) implementation for the HDPCVD Void-Free Gap Fill & Sputter-Deposition Controller.

FUNCTION_BLOCK FB_HDPCVD_Controller
VAR_INPUT
    bEnable                 : BOOL; // Enable the FB
    bStart                  : BOOL; // Start process
    bStop                   : BOOL; // Stop process
    bAbort                  : BOOL; // Abort process

    // Process Setpoints
    lrSourceRF_Target_W     : LREAL := 3000.0; // 2.0 MHz Source RF Power (W)
    lrBiasRF_Target_W       : LREAL := 1500.0; // 13.56 MHz Bias RF Power (W)
    lrTargetDSRatio         : LREAL := 3.5;    // Deposition to Sputter Ratio
    lrTargetWaferTemp_C     : LREAL := 400.0;  // Target Wafer Temperature
    lrHePressureInner_Torr  : LREAL := 8.0;    // Inner Zone He Pressure
    lrHePressureOuter_Torr  : LREAL := 12.0;   // Outer Zone He Pressure

    // Process Feedback
    lrWaferTemp_C           : LREAL;
    lrSourceRF_Actual_W     : LREAL;
    lrBiasRF_Actual_W       : LREAL;
    lrHePressureInner_Act   : LREAL;
    lrHePressureOuter_Act   : LREAL;
    lrChamberPressure_mTorr : LREAL;
END_VAR

VAR_OUTPUT
    // State machine outputs
    eState                  : E_PackML_State; // e.g., IDLE, STARTING, EXECUTE, COMPLETING, ABORTING, ABORTED
    bReady                  : BOOL;
    bActive                 : BOOL;
    bDone                   : BOOL;
    bError                  : BOOL;
    nErrorID                : UDINT;

    // Control Outputs
    lrSourceRF_Cmd_W        : LREAL;
    lrBiasRF_Cmd_W          : LREAL;
    lrHePressureInner_Cmd   : LREAL;
    lrHePressureOuter_Cmd   : LREAL;
    bESHClampCmd            : BOOL;
    lrProcessGasFlow_sccm   : LREAL; // SiH4, O2, Ar mixture control abstract
END_VAR

VAR
    // Internal States
    tonStateTimer           : TON;
    tonStepTimer            : TON;

    // Internal Control Variables
    lrCurrentDSRatio        : LREAL;

    // He Pressure PID blocks (conceptual standard PID blocks)
    fbPID_HeInner           : FB_PID;
    fbPID_HeOuter           : FB_PID;
    fbPID_RFBias            : FB_PID;

    // Process steps during EXECUTE
    nProcessStep            : INT;

    // Safety Limits
    MAX_WAFER_TEMP          : LREAL := 450.0;
    MIN_CHAMBER_PRESS       : LREAL := 1.0;
END_VAR

// -----------------------------------------------------------------------------
// State Machine (PackML inspired)
// -----------------------------------------------------------------------------

// Timer for state transitions and steps
tonStateTimer(IN := NOT tonStateTimer.Q, PT := T#10MS);
tonStepTimer(IN := (eState = E_PackML_State.EXECUTE), PT := T#1S);

CASE eState OF
    E_PackML_State.IDLE:
        bReady := TRUE;
        bActive := FALSE;
        bDone := FALSE;
        bError := FALSE;

        lrSourceRF_Cmd_W := 0.0;
        lrBiasRF_Cmd_W := 0.0;
        bESHClampCmd := FALSE;
        lrHePressureInner_Cmd := 0.0;
        lrHePressureOuter_Cmd := 0.0;

        IF bStart AND bEnable THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        bReady := FALSE;
        bActive := TRUE;

        // Step 1: Clamp Wafer
        bESHClampCmd := TRUE;

        // Step 2: Establish He Backside cooling
        lrHePressureInner_Cmd := lrHePressureInner_Torr;
        lrHePressureOuter_Cmd := lrHePressureOuter_Torr;

        // Wait for pressure stabilization
        IF ABS(lrHePressureInner_Act - lrHePressureInner_Torr) < 0.5 AND 
           ABS(lrHePressureOuter_Act - lrHePressureOuter_Torr) < 0.5 THEN
            eState := E_PackML_State.EXECUTE;
            nProcessStep := 0;
        END_IF

    E_PackML_State.EXECUTE:
        // Closed-loop dual-zone Helium pressure control for temperature management
        fbPID_HeInner(
            rSetpoint := lrTargetWaferTemp_C,
            rActualValue := lrWaferTemp_C,
            bEnable := TRUE,
            rKp := 2.5, rTi := 1.0, rTd := 0.1,
            rOutput => lrHePressureInner_Cmd
        );

        fbPID_HeOuter(
            rSetpoint := lrTargetWaferTemp_C,
            rActualValue := lrWaferTemp_C,
            bEnable := TRUE,
            rKp := 2.8, rTi := 1.2, rTd := 0.1,
            rOutput => lrHePressureOuter_Cmd
        );

        // Real-time modulation of D/S Ratio
        // Source RF controls plasma density (deposition rate roughly)
        // Bias RF controls ion bombardment (sputter rate)

        // Simplified D/S ratio estimation model
        IF lrBiasRF_Actual_W > 10.0 THEN
            lrCurrentDSRatio := lrSourceRF_Actual_W / lrBiasRF_Actual_W;
        ELSE
            lrCurrentDSRatio := 999.0;
        END_IF

        fbPID_RFBias(
            rSetpoint := lrTargetDSRatio,
            rActualValue := lrCurrentDSRatio,
            bEnable := TRUE,
            rKp := 10.0, rTi := 0.5, rTd := 0.0,
            rOutput => lrBiasRF_Cmd_W
        );

        lrSourceRF_Cmd_W := lrSourceRF_Target_W;

        // Advance Process Steps
        IF tonStepTimer.Q THEN
            nProcessStep := nProcessStep + 1;
            tonStepTimer(IN := FALSE); // Reset timer
        END_IF

        // End condition: e.g., total process time or thickness reached (simulated by step count)
        IF nProcessStep >= 120 THEN // e.g. 120 seconds process
            eState := E_PackML_State.COMPLETING;
        END_IF

        // Interlocks
        IF lrWaferTemp_C > MAX_WAFER_TEMP THEN
            nErrorID := 1001; // Over temperature
            eState := E_PackML_State.ABORTING;
        END_IF

    E_PackML_State.COMPLETING:
        // Shutdown RF
        lrSourceRF_Cmd_W := 0.0;
        lrBiasRF_Cmd_W := 0.0;

        // De-clamping sequence: reduce He pressure gracefully to avoid popping
        lrHePressureInner_Cmd := lrHePressureInner_Cmd * 0.9;
        lrHePressureOuter_Cmd := lrHePressureOuter_Cmd * 0.9;

        IF lrHePressureInner_Act < 1.0 AND lrHePressureOuter_Act < 1.0 THEN
            bESHClampCmd := FALSE;
            bDone := TRUE;
            eState := E_PackML_State.IDLE;
        END_IF

    E_PackML_State.ABORTING:
        bError := TRUE;
        lrSourceRF_Cmd_W := 0.0;
        lrBiasRF_Cmd_W := 0.0;
        lrHePressureInner_Cmd := 0.0;
        lrHePressureOuter_Cmd := 0.0;
        bESHClampCmd := FALSE;
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF bStart AND bEnable THEN // Simple reset condition
            bError := FALSE;
            eState := E_PackML_State.IDLE;
        END_IF

    ELSE
        eState := E_PackML_State.IDLE;
END_CASE

// Global Stop / Abort overrides
IF bAbort THEN
    eState := E_PackML_State.ABORTING;
ELSIF bStop AND eState = E_PackML_State.EXECUTE THEN
    eState := E_PackML_State.COMPLETING;
END_IF

END_FUNCTION_BLOCK
