FUNCTION_BLOCK FB_CruiseShip_HVAC_Controller
TITLE = 'Commercial Cruise Ship HVAC Integrated Control'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Swarm'
(*
    This function block manages a complex integrated HVAC system for a commercial cruise ship.
    Sub-systems:
    1. Chilled Water Plant Compressor Staging
    2. Cabin Variable Air Volume (VAV) Duct Pressure Balancing
    3. Exhaust Gas Heat Recovery (EGHR)
*)

VAR_INPUT
    (* Chilled Water Plant Inputs *)
    rChilledWaterSupplyTemp : REAL; (* Actual CWS temperature in Celsius *)
    rChilledWaterReturnTemp : REAL; (* Actual CWR temperature in Celsius *)
    rChilledWaterSetpoint   : REAL; (* Desired CWS temperature *)
    rAmbientAirTemp         : REAL; (* Outside air temperature *)
    rSeaWaterTemp           : REAL; (* Sea water temperature for condenser cooling *)
    bPlantEnable            : BOOL; (* Master enable for Chiller Plant *)

    (* VAV Duct Pressure Balancing Inputs *)
    rMainDuctStaticPressure : REAL; (* Main supply duct pressure in Pa *)
    rDuctPressureSetpoint   : REAL; (* Target main duct pressure in Pa *)
    rTotalZoneAirflowDemand : REAL; (* Sum of all cabin air flow demands in m3/h *)
    bSupplyFanRunFeedback   : BOOL; (* Supply fan running status *)

    (* Exhaust Gas Heat Recovery Inputs *)
    rExhaustGasTempIn       : REAL; (* Temperature of exhaust gas entering recovery heat exchanger *)
    rExhaustGasTempOut      : REAL; (* Temperature of exhaust gas exiting *)
    rHeatingWaterReturnTemp : REAL; (* Hot water return temperature *)
    rHeatingWaterSetpoint   : REAL; (* Desired hot water supply temperature *)
    bEGHR_Enable            : BOOL; (* Enable exhaust gas heat recovery *)
END_VAR

VAR_OUTPUT
    (* Chiller Staging Outputs *)
    bCompressor1_Run        : BOOL;
    bCompressor2_Run        : BOOL;
    bCompressor3_Run        : BOOL;
    rPrimaryPumpSpeedCmd    : REAL; (* 0.0 to 100.0% *)
    rSeaWaterPumpSpeedCmd   : REAL; (* 0.0 to 100.0% *)

    (* VAV Duct Pressure Outputs *)
    rSupplyFanVFD_Cmd       : REAL; (* Variable frequency drive command 0-100% *)
    rBypassDamperPos        : REAL; (* Bypass damper position 0-100% *)

    (* EGHR Outputs *)
    rEGHR_DiverterValvePos  : REAL; (* 0 = Bypass, 100 = Full Recovery *)
    rHotWaterPumpSpeedCmd   : REAL; (* 0.0 to 100.0% *)

    (* General *)
    bSystemAlarm            : BOOL;
    wErrorCode              : WORD;
END_VAR

VAR
    (* Internal State and Timers *)
    tCompressorStageTimer   : TON;
    tDuctPressurePID        : TON;
    rPlantCoolingLoad       : REAL;
    rCoolingError           : REAL;
    rPressureError          : REAL;
    rPressureIntegral       : REAL;
    rHeatingError           : REAL;
    rHeatingIntegral        : REAL;
    iActiveCompressors      : INT;

    (* PID Constants *)
    Kp_Pressure : REAL := 0.2;
    Ki_Pressure : REAL := 0.05;
    Kp_Heating  : REAL := 1.5;
    Ki_Heating  : REAL := 0.1;
END_VAR

(* 1. CHILLED WATER PLANT COMPRESSOR STAGING *)
rCoolingError := rChilledWaterReturnTemp - rChilledWaterSetpoint;
rPlantCoolingLoad := rCoolingError * 15.0; (* Simplistic load calculation factor *)

IF NOT bPlantEnable THEN
    iActiveCompressors := 0;
    tCompressorStageTimer(IN := FALSE);
ELSE
    tCompressorStageTimer(IN := TRUE, PT := T#5M);
    IF tCompressorStageTimer.Q THEN
        IF rCoolingError > 2.0 AND iActiveCompressors < 3 THEN
            iActiveCompressors := iActiveCompressors + 1;
        ELSIF rCoolingError < -1.0 AND iActiveCompressors > 0 THEN
            iActiveCompressors := iActiveCompressors - 1;
        END_IF;
        tCompressorStageTimer(IN := FALSE); (* Reset timer *)
    END_IF;
END_IF;

bCompressor1_Run := (iActiveCompressors >= 1);
bCompressor2_Run := (iActiveCompressors >= 2);
bCompressor3_Run := (iActiveCompressors >= 3);

IF iActiveCompressors > 0 THEN
    rPrimaryPumpSpeedCmd := 60.0 + (INT_TO_REAL(iActiveCompressors) * 10.0);
    rSeaWaterPumpSpeedCmd := 50.0 + (rSeaWaterTemp * 0.5);
    IF rSeaWaterPumpSpeedCmd > 100.0 THEN rSeaWaterPumpSpeedCmd := 100.0; END_IF;
ELSE
    rPrimaryPumpSpeedCmd := 0.0;
    rSeaWaterPumpSpeedCmd := 0.0;
END_IF;

(* 2. CABIN VAV DUCT PRESSURE BALANCING *)
rPressureError := rDuctPressureSetpoint - rMainDuctStaticPressure;
IF bSupplyFanRunFeedback THEN
    rPressureIntegral := rPressureIntegral + (rPressureError * 0.1);
    (* Anti-windup limit *)
    IF rPressureIntegral > 50.0 THEN rPressureIntegral := 50.0; END_IF;
    IF rPressureIntegral < -50.0 THEN rPressureIntegral := -50.0; END_IF;

    rSupplyFanVFD_Cmd := (rPressureError * Kp_Pressure) + (rPressureIntegral * Ki_Pressure) + 40.0; (* Base speed 40% *)
    IF rSupplyFanVFD_Cmd > 100.0 THEN rSupplyFanVFD_Cmd := 100.0; END_IF;
    IF rSupplyFanVFD_Cmd < 20.0 THEN rSupplyFanVFD_Cmd := 20.0; END_IF;

    (* Duct Over-pressure protection *)
    IF rMainDuctStaticPressure > (rDuctPressureSetpoint + 150.0) THEN
        rBypassDamperPos := 100.0;
    ELSE
        rBypassDamperPos := 0.0;
    END_IF;
ELSE
    rSupplyFanVFD_Cmd := 0.0;
    rPressureIntegral := 0.0;
    rBypassDamperPos := 100.0; (* Failsafe bypass *)
END_IF;

(* 3. EXHAUST GAS HEAT RECOVERY (EGHR) *)
IF bEGHR_Enable AND rExhaustGasTempIn > 150.0 THEN
    rHeatingError := rHeatingWaterSetpoint - rHeatingWaterReturnTemp;
    rHeatingIntegral := rHeatingIntegral + (rHeatingError * 0.1);

    IF rHeatingIntegral > 100.0 THEN rHeatingIntegral := 100.0; END_IF;
    IF rHeatingIntegral < 0.0 THEN rHeatingIntegral := 0.0; END_IF;

    rEGHR_DiverterValvePos := (rHeatingError * Kp_Heating) + (rHeatingIntegral * Ki_Heating);
    IF rEGHR_DiverterValvePos > 100.0 THEN rEGHR_DiverterValvePos := 100.0; END_IF;
    IF rEGHR_DiverterValvePos < 0.0 THEN rEGHR_DiverterValvePos := 0.0; END_IF;

    rHotWaterPumpSpeedCmd := 50.0 + (rEGHR_DiverterValvePos * 0.5);
ELSE
    rEGHR_DiverterValvePos := 0.0;
    rHotWaterPumpSpeedCmd := 0.0;
    rHeatingIntegral := 0.0;
END_IF;

(* ALARM LOGIC *)
bSystemAlarm := FALSE;
wErrorCode := 16#0000;

IF bPlantEnable AND NOT bSupplyFanRunFeedback THEN
    bSystemAlarm := TRUE;
    wErrorCode := 16#0001; (* Fan failure while plant enabled *)
END_IF;

IF rMainDuctStaticPressure > 1000.0 THEN
    bSystemAlarm := TRUE;
    wErrorCode := wErrorCode OR 16#0002; (* Duct extreme overpressure *)
END_IF;

END_FUNCTION_BLOCK
