Here is the Base Code for a Lyophilizer in Siemens SCL:

FUNCTION_BLOCK "Lyophilizer_Control"
VERSION : 0.1
VAR_INPUT
    Start_Cycle : Bool;
    Stop_Cycle : Bool;
    Chamber_Pressure : Real; // mbar
    Shelf_Temp : Real; // deg C
    Target_Freeze_Temp : Real;
    Target_Primary_Dry_Temp : Real;
    Target_Secondary_Dry_Temp : Real;
    Target_Vacuum : Real;
END_VAR
VAR_OUTPUT
    Vacuum_Pump_Run : Bool;
    Compressor_Run : Bool;
    Heater_Run : Bool;
    Status : Int;
END_VAR
VAR
    State : Int;
END_VAR
BEGIN
    IF Stop_Cycle THEN
        State := 0;
    END_IF;

    CASE State OF
        0: // Idle
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
            IF Start_Cycle THEN
                State := 1;
            END_IF;
        1: // Freezing
            Compressor_Run := TRUE;
            Vacuum_Pump_Run := FALSE;
            Heater_Run := FALSE;
            IF Shelf_Temp <= Target_Freeze_Temp THEN
                State := 2;
            END_IF;
        2: // Primary Drying
            Compressor_Run := TRUE;
            Vacuum_Pump_Run := TRUE;
            IF Chamber_Pressure <= Target_Vacuum THEN
                IF Shelf_Temp < Target_Primary_Dry_Temp THEN
                    Heater_Run := TRUE;
                ELSE
                    Heater_Run := FALSE;
                END_IF;
                IF Shelf_Temp >= Target_Primary_Dry_Temp THEN
                    State := 3;
                END_IF;
            END_IF;
        3: // Secondary Drying
            Compressor_Run := TRUE;
            Vacuum_Pump_Run := TRUE;
            IF Shelf_Temp < Target_Secondary_Dry_Temp THEN
                Heater_Run := TRUE;
            ELSE
                Heater_Run := FALSE;
            END_IF;
            IF Shelf_Temp >= Target_Secondary_Dry_Temp THEN
                State := 4;
            END_IF;
        4: // Complete
            Vacuum_Pump_Run := FALSE;
            Compressor_Run := FALSE;
            Heater_Run := FALSE;
    END_CASE;
    Status := State;
END_FUNCTION_BLOCK
