    arSquidRawV : ARRAY[1..306] OF LREAL; // Raw voltage from SQUIDs (V)

    // Helium system status
    fHeliumTemp : LREAL; // Temperature in Kelvin
    fHeliumLevel : LREAL; // Percentage 0-100%
END_VAR

VAR_OUTPUT
    bActive : BOOL; // Controller is active
    bError : BOOL;  // Global error flag
    sErrorMsg : STRING(255);

    // Processed brain signals (fT)
    arBrainFlux_fT : ARRAY[1..306] OF LREAL;

    // Helmholtz coil compensation currents (Amperes)
    fCompCurrentX : LREAL;
    fCompCurrentY : LREAL;
    fCompCurrentZ : LREAL;

    // Status
    eState : E_PackML_State; // PackML state machine
END_VAR

VAR
    // FLL control variables
    arSquidIntegral : ARRAY[1..306] OF LREAL;
    fFLL_Kp : LREAL := 0.5; // FLL Proportional Gain
    fFLL_Ki : LREAL := 1000.0; // FLL Integral Gain
    fPhi0 : LREAL := 2.067833848E-15; // Magnetic flux quantum (Wb)
    fV_to_Phi_Gain : LREAL := 1.0E-5; // V to Phi transfer characteristic

    // Compensation constants (A/T)
    fCoilGainX : LREAL := 1.5E4;
    fCoilGainY : LREAL := 1.5E4;
    fCoilGainZ : LREAL := 1.8E4;

    // Loop indexing
    i : INT;

    // Cycle time calculation
    fbTimer : TON;
    fDeltaT : LREAL := 0.001; // 1 ms scan rate assumption
END_VAR

// PackML State Machine (Simplified)
CASE eState OF
    E_PackML_State.STOPPED:
        bActive := FALSE;
        IF bEnable AND NOT bError THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        // Initialization and calibrations
        FOR i := 1 TO 306 DO
            arSquidIntegral[i] := 0.0;
            arBrainFlux_fT[i] := 0.0;
        END_FOR
        fCompCurrentX := 0.0;
        fCompCurrentY := 0.0;
        fCompCurrentZ := 0.0;

        // Wait for temperature stabilization
        IF fHeliumTemp <= 4.22 THEN
            eState := E_PackML_State.EXECUTE;
        ELSE
            bError := TRUE;
            sErrorMsg := 'Helium temp too high. Must be <= 4.22K';
            eState := E_PackML_State.ABORTING;
        END_IF

    E_PackML_State.EXECUTE:
        bActive := TRUE;

        // Safety / Interlock monitoring
        IF fHeliumTemp > 4.5 OR fHeliumLevel < 10.0 THEN
            bError := TRUE;
            sErrorMsg := 'Cryogenic system failure.';
            eState := E_PackML_State.ABORTING;
        END_IF

        IF NOT bEnable THEN
            eState := E_PackML_State.STOPPING;
        END_IF

        IF NOT bError THEN
            // 1. Active Magnetic Shielding (MSR Compensation)
            // Feedforward cancellation of external magnetic noise
            // Reverse polarity to inject anti-phase currents
            fCompCurrentX := -fRefFluxX * fCoilGainX;
            fCompCurrentY := -fRefFluxY * fCoilGainY;
            fCompCurrentZ := -fRefFluxZ * fCoilGainZ;

            // 2. Flux-Locked Loop (FLL) SQUID Readout Processing
            // Linearizing the V-Phi curve via negative feedback model
            FOR i := 1 TO 306 DO
                // Integrate raw voltage
                arSquidIntegral[i] := arSquidIntegral[i] + (arSquidRawV[i] * fDeltaT);

                // PI Control for FLL (Feedback flux to lock SQUID)
                // Output is the measured environmental flux in Weber (Wb)
                // Assuming linear region around working point
                arBrainFlux_fT[i] := (fFLL_Kp * arSquidRawV[i] + fFLL_Ki * arSquidIntegral[i]) * fV_to_Phi_Gain * 1.0E15; // Convert Wb to fT
            END_FOR
        END_IF

    E_PackML_State.STOPPING:
        bActive := FALSE;
        eState := E_PackML_State.STOPPED;

    E_PackML_State.ABORTING:
        bActive := FALSE;
        // Zero all outputs safely
        fCompCurrentX := 0.0;
        fCompCurrentY := 0.0;
        fCompCurrentZ := 0.0;
        FOR i := 1 TO 306 DO
            arBrainFlux_fT[i] := 0.0;
        END_FOR
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF bReset THEN
            bError := FALSE;
            sErrorMsg := '';
            eState := E_PackML_State.STOPPED;
        END_IF
END_CASE

END_FUNCTION_BLOCK
