    Start_Cmd := SCADA_Data.Control_Word.%X0;
    Stop_Cmd := SCADA_Data.Control_Word.%X1;
    Ack_Fault := SCADA_Data.Control_Word.%X2;

    // Pump Failover Logic
    IF Active_Pump = 1 AND Pump1_Fault THEN
        Active_Pump := 2; // Failover to Pump 2
    ELSIF Active_Pump = 2 AND Pump2_Fault THEN
        Active_Pump := 1; // Failover back (if possible)
