        System_Fault := TRUE;
        SCADA_Data.Active_Fault_Code := 1;
    ELSIF Permeate_Conductivity > Conductivity_Limit THEN
        System_Fault := TRUE;
        SCADA_Data.Active_Fault_Code := 2;
    ELSIF Pump1_Fault AND Pump2_Fault THEN
