VAR
    // Internal States
    iState : INT;
    rPlungerTargetPos : REAL;
    rErrorWeight : REAL;

    // Timing setpoints (in degrees)
    rSettleBlowStart : REAL := 30.0;
    rSettleBlowEnd : REAL := 60.0;
    rCounterBlowStart : REAL := 80.0;
    rCounterBlowEnd : REAL := 120.0;
    rBlankOpenStart : REAL := 130.0;
    rNeckRingRevertStart : REAL := 150.0;
    rBlowMoldCloseStart : REAL := 170.0;
    rFinalBlowStart : REAL := 190.0;
    rFinalBlowEnd : REAL := 250.0;
    rBlowMoldOpenStart : REAL := 270.0;
    rTakeoutInStart : REAL := 280.0;

    // PID for Gob Weight control adjusting plunger depth
    Kp : REAL := 0.5;
    Ki : REAL := 0.1;
    Kd : REAL := 0.05;
    rIntegral : REAL;
    rPrevError : REAL;
    rDerivative : REAL;
    rPlungerDepthCorr : REAL;

    // Timers
    tLubeTimer : TON;
END_VAR

// -----------------------------------------------------------------------------
// Fault Handling
// -----------------------------------------------------------------------------
IF bEStop OR bAirPressureLow OR bLubeFault THEN
    bFaultActive := TRUE;
    bSectionActive := FALSE;
    bPlungerServoEnable := FALSE;
    rPlungerVelocityRef := 0.0;

    // Reset all valves to safe state
    bValveBaffle := FALSE;
    bValveSettleBlow := FALSE;
    bValveCounterBlow := FALSE;
    bValveBlankOpen := TRUE; // Open blank mold on fault
    bValveBlowMoldOpen := TRUE; // Open blow mold on fault
    bValveFinalBlow := FALSE;
    bValveTakeoutIn := FALSE;

    IF bEStop THEN iFaultCode := 1;
    ELSIF bAirPressureLow THEN iFaultCode := 2;
    ELSIF bLubeFault THEN iFaultCode := 3;
    END_IF;
