    bSectionActive := FALSE;
    bPlungerServoEnable := FALSE;
    RETURN;
END_IF;

bSectionActive := TRUE;

// -----------------------------------------------------------------------------
// Gob Weight Closed-Loop Control (PID)
// Adjusts the base plunger position to control gob weight.
// -----------------------------------------------------------------------------
rErrorWeight := rGobWeightTarget - rGobWeightActual;

// Out of tolerance reject logic
IF ABS(rErrorWeight) > 5.0 THEN
    bRejectBottle := TRUE;
ELSE
    bRejectBottle := FALSE;
END_IF;

// PID Calculation
rIntegral := rIntegral + (rErrorWeight * 0.01); // Assuming 10ms cycle time
// Anti-windup
IF rIntegral > 10.0 THEN rIntegral := 10.0; END_IF;
IF rIntegral < -10.0 THEN rIntegral := -10.0; END_IF;

rDerivative := (rErrorWeight - rPrevError) / 0.01;
rPlungerDepthCorr := (Kp * rErrorWeight) + (Ki * rIntegral) + (Kd * rDerivative);
rPrevError := rErrorWeight;

// -----------------------------------------------------------------------------
// Blank Mold Servo Plunger Kinematics
// -----------------------------------------------------------------------------
bPlungerServoEnable := TRUE;

// Simple cam profile based on machine angle for pressing phase
IF (rMachineAngle > 10.0) AND (rMachineAngle < 70.0) THEN
    // Pressing phase
    rPlungerTargetPos := 150.0 + rPlungerDepthCorr; // Base depth + PID correction
ELSE
    // Retract phase
    rPlungerTargetPos := 0.0; // Home position
END_IF;

