rPlungerVelocityRef := (rPlungerTargetPos - rPlungerPosition) * 10.0;

// Velocity limits
IF rPlungerVelocityRef > 1000.0 THEN rPlungerVelocityRef := 1000.0; END_IF;
IF rPlungerVelocityRef < -1000.0 THEN rPlungerVelocityRef := -1000.0; END_IF;

// -----------------------------------------------------------------------------
// IS Machine Pneumatic Valve Timing Control (Electronic Drum)
// -----------------------------------------------------------------------------

// Baffle & Settle Blow
IF (rMachineAngle >= rSettleBlowStart) AND (rMachineAngle <= rSettleBlowEnd) THEN
    bValveBaffle := TRUE;
    bValveSettleBlow := TRUE;
ELSE
    bValveBaffle := FALSE;
    bValveSettleBlow := FALSE;
END_IF;

// Counter Blow
IF (rMachineAngle >= rCounterBlowStart) AND (rMachineAngle <= rCounterBlowEnd) THEN
    bValveCounterBlow := TRUE;
ELSE
    bValveCounterBlow := FALSE;
END_IF;

// Blank Mold Open/Close
IF (rMachineAngle >= rBlankOpenStart) OR (rMachineAngle < 10.0) THEN
    bValveBlankOpen := TRUE;
ELSE
    bValveBlankOpen := FALSE;
END_IF;

