FUNCTION_BLOCK "TractionControl_Advanced"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      SysEnable : Bool;
      PreTripTestStart : Bool;
      TargetSpeed_kmh : Real;
      ActualSpeed1_kmh : Real;
      ActualSpeed2_kmh : Real;
      BrakeCommand : Real;
      HIL_TwinSpeed_kmh : Real;
      HIL_SyncPulse : Bool;
   END_VAR
   VAR_OUTPUT 
      TorqueCmd_Nm : Real;
      SysState : Int;
      FaultCode : DInt;
      SelfTestComplete : Bool;
      HIL_DivergenceAlert : Bool;
   END_VAR
   VAR 
      ActualSpeed_kmh : Real;
      DriftIntegrator : Real;
      HIL_SyncTimer : TON_TIME;
      TestStep : Int;
      TestTimer : TON_TIME;
   END_VAR
   CONST
      STATE_OFF := 0; STATE_TEST := 1; STATE_READY := 2; STATE_RUN := 3; STATE_DEGRADED := 4; STATE_FAULT := 5;
      HIL_MAX_ERROR := 15.0;
      DRIFT_THRESHOLD := 500.0;
   END_CONST
BEGIN
    IF #PreTripTestStart AND #SysState = #STATE_OFF THEN
        #SysState := #STATE_TEST;
        #TestStep := 1;
        #SelfTestComplete := FALSE;
    END_IF;
    IF #SysState = #STATE_TEST THEN
        CASE #TestStep OF
            1:
                IF #ActualSpeed1_kmh < 1.0 THEN
                    #TestStep := 2;
                ELSE
                    #SysState := #STATE_FAULT; #FaultCode := 301;
                END_IF;
            2:
                #TestTimer(IN:=TRUE, PT:=T#1S);
                IF #TestTimer.Q THEN
                    #TestTimer(IN:=FALSE, PT:=T#1S);
                    #TestStep := 3;
                END_IF;
            3:
                #SysState := #STATE_READY;
                #SelfTestComplete := TRUE;
        END_CASE;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    IF NOT #SysEnable THEN
        #SysState := #STATE_OFF;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    IF #SysState = #STATE_READY AND #SysEnable THEN
        #SysState := #STATE_RUN;
    END_IF;
    #DriftIntegrator := #DriftIntegrator + ABS(#ActualSpeed1_kmh - #ActualSpeed2_kmh);
    IF #DriftIntegrator > #DRIFT_THRESHOLD THEN
        #SysState := #STATE_FAULT;
        #FaultCode := 302;
    END_IF;
    #DriftIntegrator := #DriftIntegrator * 0.999; 
    #ActualSpeed_kmh := #ActualSpeed1_kmh;
    #HIL_SyncTimer(IN := NOT #HIL_SyncPulse, PT := T#5S);
    IF ABS(#ActualSpeed_kmh - #HIL_TwinSpeed_kmh) > #HIL_MAX_ERROR OR #HIL_SyncTimer.Q THEN
        #HIL_DivergenceAlert := TRUE;
        #SysState := #STATE_DEGRADED;
    ELSE
        #HIL_DivergenceAlert := FALSE;
        IF #SysState = #STATE_DEGRADED THEN #SysState := #STATE_RUN; END_IF;
    END_IF;
    IF #SysState = #STATE_FAULT THEN
        #TorqueCmd_Nm := 0.0;
        RETURN;
