        #TorqueCmd_Nm := (#TargetSpeed_kmh - #ActualSpeed_kmh) * 50.0;
        IF #SysState = #STATE_DEGRADED AND #TorqueCmd_Nm > 5000.0 THEN
            #TorqueCmd_Nm := 5000.0;
        ELSIF #TorqueCmd_Nm > 10000.0 THEN
            #TorqueCmd_Nm := 10000.0;
        END_IF;
    END_IF;
