FUNCTION_BLOCK FB_IonImplant_MassSpectrometer
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bSystemEnable         : BOOL;     (* System master enable signal *)
    bEmergencyStop        : BOOL;     (* E-Stop safety circuit status (TRUE = OK) *)
    rBeamCurrentTarget    : LREAL;    (* Target sub-nanoampere isotope beam current (nA) *)
    rMagneticFieldSetPt   : LREAL;    (* Target magnetic field for sector magnet (Tesla) *)
    rQuadrupoleVoltSetPt  : LREAL;    (* Target voltage for electrostatic quadrupole (kV) *)
    rActualBeamCurrent    : LREAL;    (* Measured beam current from Faraday cup (nA) *)
    rActualMagneticField  : LREAL;    (* Measured Hall probe magnetic field (Tesla) *)
    rActualQuadrupoleVolt : LREAL;    (* Measured electrostatic quadrupole voltage (kV) *)
    bPlasmaSourceReady    : BOOL;     (* Ion plasma source stable and ready *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady          : BOOL;     (* Mass spectrometer is tuned and ready for implant *)
    bBeamOnTarget         : BOOL;     (* Beam current is within tolerance of target *)
    rMagneticFieldCmd     : LREAL;    (* Control command to sector magnet power supply (0-100%) *)
    rQuadrupoleVoltCmd    : LREAL;    (* Control command to quadrupole power supply (0-100%) *)
    bMagnetInterlockTrip  : BOOL;     (* Safety interlock trip for sector magnet cooling *)
    bWarningAlarm         : BOOL;     (* Warning: parameter deviation detected *)
    iOperatingState       : INT;      (* Current state machine step *)
END_VAR
VAR
    (* Internal state variables *)
    iState                : INT := 0;
    tMagnetSettleTimer    : TON;
    tBeamStableTimer      : TON;
    rBeamCurrentError     : LREAL;
    rMagneticFieldError   : LREAL;
    rQuadrupoleError      : LREAL;

    (* PID internal states *)
    rMagnetIntegral       : LREAL := 0.0;
    rMagnetLastError      : LREAL := 0.0;

    rQuadIntegral         : LREAL := 0.0;
    rQuadLastError        : LREAL := 0.0;

    (* Constants *)
    Kp_Magnet             : LREAL := 12.5;
    Ki_Magnet             : LREAL := 0.8;
    Kd_Magnet             : LREAL := 0.1;

    Kp_Quad               : LREAL := 8.2;
    Ki_Quad               : LREAL := 0.45;
    Kd_Quad               : LREAL := 0.05;

    dT                    : LREAL := 0.01; (* 10ms cycle time *)
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Stop and Safety Interlocks *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bBeamOnTarget := FALSE;
    rMagneticFieldCmd := 0.0;
    rQuadrupoleVoltCmd := 0.0;
    bMagnetInterlockTrip := TRUE;
    bWarningAlarm := TRUE;
    iState := 99; (* Fault state *)
    iOperatingState := iState;
    RETURN;
END_IF;

IF iState = 99 AND bEmergencyStop THEN
    bMagnetInterlockTrip := FALSE;
    iState := 0; (* Reset to IDLE *)
END_IF;

CASE iState OF
    0: (* IDLE - Wait for System Enable and Plasma Source *)
        bSystemReady := FALSE;
        bBeamOnTarget := FALSE;
        rMagneticFieldCmd := 0.0;
        rQuadrupoleVoltCmd := 0.0;

        IF bSystemEnable AND bPlasmaSourceReady THEN
            iState := 10; (* Start Magnet Tuning *)
        END_IF;

    10: (* MAGNET TUNING - Sector Magnet PID Control *)
        rMagneticFieldError := rMagneticFieldSetPt - rActualMagneticField;

        (* PID calculations for Sector Magnet *)
        rMagnetIntegral := rMagnetIntegral + (rMagneticFieldError * dT);
        rMagneticFieldCmd := (Kp_Magnet * rMagneticFieldError) + (Ki_Magnet * rMagnetIntegral) + (Kd_Magnet * (rMagneticFieldError - rMagnetLastError) / dT);
        rMagnetLastError := rMagneticFieldError;

        (* Saturation Limits *)
        IF rMagneticFieldCmd > 100.0 THEN rMagneticFieldCmd := 100.0; END_IF;
        IF rMagneticFieldCmd < 0.0 THEN rMagneticFieldCmd := 0.0; END_IF;

        (* Settle condition *)
        tMagnetSettleTimer(IN := ABS(rMagneticFieldError) < 0.001, PT := T#2S);
        IF tMagnetSettleTimer.Q THEN
            tMagnetSettleTimer(IN := FALSE);
            iState := 20; (* Start Quadrupole Tuning *)
        END_IF;

        IF NOT bSystemEnable THEN iState := 0; END_IF;

    20: (* QUADRUPOLE TUNING - Electrostatic Lens PID Control *)
        rQuadrupoleError := rQuadrupoleVoltSetPt - rActualQuadrupoleVolt;

        (* PID calculations for Quadrupole *)
        rQuadIntegral := rQuadIntegral + (rQuadrupoleError * dT);
        rQuadrupoleVoltCmd := (Kp_Quad * rQuadrupoleError) + (Ki_Quad * rQuadIntegral) + (Kd_Quad * (rQuadrupoleError - rQuadLastError) / dT);
        rQuadLastError := rQuadrupoleError;

        (* Saturation Limits *)
        IF rQuadrupoleVoltCmd > 100.0 THEN rQuadrupoleVoltCmd := 100.0; END_IF;
        IF rQuadrupoleVoltCmd < 0.0 THEN rQuadrupoleVoltCmd := 0.0; END_IF;

        (* Sub-nanoampere Beam Profiling check *)
        rBeamCurrentError := rBeamCurrentTarget - rActualBeamCurrent;

        IF ABS(rQuadrupoleError) < 0.05 AND ABS(rBeamCurrentError) < 0.0001 THEN
            bSystemReady := TRUE;
            iState := 30; (* BEAM STABLE *)
        END_IF;

        IF NOT bSystemEnable THEN iState := 0; END_IF;

    30: (* BEAM STABLE & ON TARGET *)
        tBeamStableTimer(IN := TRUE, PT := T#5S);
        IF tBeamStableTimer.Q THEN
            bBeamOnTarget := TRUE;
        END_IF;

        (* Continuous closed-loop regulation *)
        rMagneticFieldError := rMagneticFieldSetPt - rActualMagneticField;
        rMagnetIntegral := rMagnetIntegral + (rMagneticFieldError * dT);
        rMagneticFieldCmd := (Kp_Magnet * rMagneticFieldError) + (Ki_Magnet * rMagnetIntegral) + (Kd_Magnet * (rMagneticFieldError - rMagnetLastError) / dT);
        rMagnetLastError := rMagneticFieldError;

        rQuadrupoleError := rQuadrupoleVoltSetPt - rActualQuadrupoleVolt;
        rQuadIntegral := rQuadIntegral + (rQuadrupoleError * dT);
        rQuadrupoleVoltCmd := (Kp_Quad * rQuadrupoleError) + (Ki_Quad * rQuadIntegral) + (Kd_Quad * (rQuadrupoleError - rQuadLastError) / dT);
        rQuadLastError := rQuadrupoleError;

        (* Tolerance Monitoring *)
        IF ABS(rBeamCurrentTarget - rActualBeamCurrent) > 0.0005 THEN
            bWarningAlarm := TRUE;
            bBeamOnTarget := FALSE;
            tBeamStableTimer(IN := FALSE);
        ELSE
            bWarningAlarm := FALSE;
        END_IF;

        IF NOT bSystemEnable THEN
            tBeamStableTimer(IN := FALSE);
            iState := 0;
        END_IF;

END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
