FUNCTION_BLOCK FB_IndustrialControl
// ==============================================================================
// Function Block: FB_DistrictHeatingHeatPumpControl
// Description: Advanced control algorithm for a district heating heat pump plant
// featuring ammonia compressor capacity staging, evaporator brine flow control,
// and condenser hot water supply reset cascades.
// ==============================================================================

VAR_INPUT
    bEnable                 : BOOL; // System enable command
    rOutdoorTemp            : REAL; // Outdoor air temperature (DegC)
    rDistrictHeatingReturnTemp : REAL; // Return temperature from district heating network (DegC)
    rEvaporatorBrineInletTemp  : REAL; // Brine inlet temperature to evaporator (DegC)
    rCondenserWaterFlow     : REAL; // Hot water flow rate through condenser (m3/h)
    bCompressorFault_1      : BOOL; // Fault status of compressor 1
    bCompressorFault_2      : BOOL; // Fault status of compressor 2
    bCompressorFault_3      : BOOL; // Fault status of compressor 3
END_VAR

VAR_OUTPUT
    bStartCompressor_1      : BOOL; // Start command for compressor 1
    bStartCompressor_2      : BOOL; // Start command for compressor 2
    bStartCompressor_3      : BOOL; // Start command for compressor 3
    rEvaporatorBrineValvePos: REAL; // Position command for brine control valve (0-100%)
    rCondenserWaterPumpSpd  : REAL; // Speed command for condenser water pump (0-100%)
    bSystemAlarm            : BOOL; // General system alarm flag
    iActiveCapacityLevel    : INT;  // Current active capacity stage (0-3)
END_VAR

VAR
    rTargetSupplyTemp       : REAL; // Calculated target hot water supply temperature
    rSupplyTempError        : REAL; // Error between target and actual supply temp
    rCapacityRequest        : REAL; // Total requested capacity (0-100%)

    // PI Controller Variables for Capacity
    rKp_Capacity            : REAL := 2.5;
    rKi_Capacity            : REAL := 0.1;
    rIntegralSum_Capacity   : REAL := 0.0;

    // Internal States
    iDesiredCapacityLevel   : INT;
    bInitialize             : BOOL := TRUE;
END_VAR

// Initialization
IF bInitialize THEN
    rIntegralSum_Capacity := 0.0;
    iActiveCapacityLevel := 0;
    bInitialize := FALSE;
END_IF

// ==============================================================================
// 1. Hot Water Supply Reset Cascade
// Calculate the target supply temperature based on outdoor temperature (Reset Curve)
// ==============================================================================
// Example Reset Curve:
// Outdoor Temp: -20 C -> Target Supply: 85 C
// Outdoor Temp:  10 C -> Target Supply: 65 C
IF rOutdoorTemp <= -20.0 THEN
    rTargetSupplyTemp := 85.0;
ELSIF rOutdoorTemp >= 10.0 THEN
    rTargetSupplyTemp := 65.0;
ELSE
    // Linear interpolation
    rTargetSupplyTemp := 85.0 - ((rOutdoorTemp + 20.0) * (20.0 / 30.0));
END_IF

// Calculate Temperature Error
rSupplyTempError := rTargetSupplyTemp - rDistrictHeatingReturnTemp;

// ==============================================================================
// 2. Capacity Control (PI Algorithm)
// ==============================================================================
IF bEnable AND NOT bSystemAlarm THEN
    // Proportional Term
    rCapacityRequest := (rSupplyTempError * rKp_Capacity) + rIntegralSum_Capacity;

    // Integral Term Update (Simple Euler integration, assuming 1s execution)
    rIntegralSum_Capacity := rIntegralSum_Capacity + (rSupplyTempError * rKi_Capacity);

    // Anti-windup
    IF rIntegralSum_Capacity > 100.0 THEN
        rIntegralSum_Capacity := 100.0;
    ELSIF rIntegralSum_Capacity < 0.0 THEN
        rIntegralSum_Capacity := 0.0;
    END_IF

    // Clamp total request
    IF rCapacityRequest > 100.0 THEN
        rCapacityRequest := 100.0;
    ELSIF rCapacityRequest < 0.0 THEN
        rCapacityRequest := 0.0;
    END_IF
ELSE
    rCapacityRequest := 0.0;
    rIntegralSum_Capacity := 0.0;
END_IF

// ==============================================================================
// 3. Ammonia Compressor Capacity Staging
// Determine desired capacity level based on capacity request (0-3 stages)
// ==============================================================================
IF rCapacityRequest > 80.0 THEN
    iDesiredCapacityLevel := 3;
ELSIF rCapacityRequest > 45.0 THEN
    iDesiredCapacityLevel := 2;
ELSIF rCapacityRequest > 15.0 THEN
    iDesiredCapacityLevel := 1;
ELSE
    iDesiredCapacityLevel := 0;
END_IF

// Set active level
iActiveCapacityLevel := iDesiredCapacityLevel;

// Output generation with fault interlocks
bStartCompressor_1 := (iActiveCapacityLevel >= 1) AND NOT bCompressorFault_1;
bStartCompressor_2 := (iActiveCapacityLevel >= 2) AND NOT bCompressorFault_2;
bStartCompressor_3 := (iActiveCapacityLevel >= 3) AND NOT bCompressorFault_3;

// Alarm Handling
bSystemAlarm := bCompressorFault_1 OR bCompressorFault_2 OR bCompressorFault_3;

// ==============================================================================
// 4. Evaporator Brine Flow Control
// Modulate brine valve to maintain optimal brine delta T or ensure minimum flow
// ==============================================================================
CASE iActiveCapacityLevel OF
    0: rEvaporatorBrineValvePos := 10.0; // Minimum circulation
    1: rEvaporatorBrineValvePos := 40.0;
    2: rEvaporatorBrineValvePos := 70.0;
    3: rEvaporatorBrineValvePos := 100.0;
ELSE
    rEvaporatorBrineValvePos := 10.0;
END_CASE

// ==============================================================================
// 5. Condenser Hot Water Supply Flow Cascade
// Modulate condenser pump speed based on actual flow feedback vs required flow
// ==============================================================================
IF bEnable THEN
    // Base speed on capacity, but trimmed by actual flow 
    rCondenserWaterPumpSpd := INT_TO_REAL(iActiveCapacityLevel) * 33.3;

    IF rCondenserWaterPumpSpd < 20.0 THEN
        rCondenserWaterPumpSpd := 20.0; // VFD minimum speed
    END_IF
ELSE
    rCondenserWaterPumpSpd := 0.0;
END_IF

END_FUNCTION_BLOCK\n```
