    bSystemEnable : BOOL; // System master enable
    rEngineLoad_pct : REAL; // Main engine load percentage (0.0 to 100.0)
    rExhaustGasTempIn_C : REAL; // Exhaust gas temperature at scrubber inlet
    rSOxEmission_ppm : REAL; // Measured SOx emission at stack
    rSeawaterPumpPressure_bar : REAL; // Seawater supply pressure
    rWashWaterpH_In : REAL; // Wash water pH before buffering
    rWashWaterTurbidity_NTU : REAL; // Wash water turbidity
    rCausticSodaLevel_pct : REAL; // NaOH tank level
    bSeparatorFault : BOOL; // Centrifugal separator fault
END_VAR

VAR_OUTPUT
    bSeawaterPumpCmd : BOOL; // Command to start seawater pump
    rSeawaterFlowValveCmd_pct : REAL; // Seawater flow control valve position
    bCausticSodaPumpCmd : BOOL; // Command to dose caustic soda
    rCausticSodaValveCmd_pct : REAL; // Caustic soda dosing valve position
    bSeparatorStartCmd : BOOL; // Command to start centrifugal separator
    bSeparatorDischargeCmd : BOOL; // Command to discharge sludge
    bSOxComplianceAlarm : BOOL; // Alarm for SOx non-compliance
    bSystemFault : BOOL; // General system fault
END_VAR

VAR
    // Internal States
    eState : (INIT, STANDBY, RAMP_UP, SCRUBBING, SLUDGE_DISCHARGE, FAULT);
    tScrubbingTimer : TON;
    tSeparatorTimer : TON;

    // PID Controllers
    fbSOxPID : PID;
    fbpHPID : PID;

    // Limits and thresholds
    rMaxSOx_ppm : REAL := 20.0; // IMO SOx compliance limit
    rTargetpH : REAL := 6.5; // Wash water discharge pH limit
    rMaxTurbidity : REAL := 25.0; // Max allowed turbidity in NTU

    // Internal Variables
    rSeawaterFlowDemand : REAL;
    rNaOHTargetDose : REAL;
END_VAR

// Main State Machine
CASE eState OF
    INIT:
        bSeawaterPumpCmd := FALSE;
        rSeawaterFlowValveCmd_pct := 0.0;
        bCausticSodaPumpCmd := FALSE;
        rCausticSodaValveCmd_pct := 0.0;
        bSeparatorStartCmd := FALSE;
        bSeparatorDischargeCmd := FALSE;
        bSOxComplianceAlarm := FALSE;
        bSystemFault := FALSE;

        IF bSystemEnable THEN
            eState := STANDBY;
        END_IF;

    STANDBY:
        IF NOT bSystemEnable THEN
            eState := INIT;
        ELSIF rEngineLoad_pct > 5.0 THEN
            eState := RAMP_UP;
        END_IF;

    RAMP_UP:
        bSeawaterPumpCmd := TRUE;
        rSeawaterFlowValveCmd_pct := 20.0; // Minimum flow
        bSeparatorStartCmd := TRUE;

        IF rSeawaterPumpPressure_bar > 3.0 THEN
            eState := SCRUBBING;
        ELSIF tScrubbingTimer.Q THEN
            bSystemFault := TRUE;
            eState := FAULT;
        END_IF;

    SCRUBBING:
        // SOx Compliance Control (Feedback loop for Seawater flow)
        fbSOxPID(
            ACT := rSOxEmission_ppm,
            SET := rMaxSOx_ppm * 0.8, // Target 80% of limit
            KP := 2.5,
            TN := T#10s,
            TV := T#0s,
            Y_MAN := 0.0,
            MAN_ON := FALSE
        );
        rSeawaterFlowDemand := fbSOxPID.Y;

        // Feedforward control based on engine load
        rSeawaterFlowValveCmd_pct := rSeawaterFlowDemand + (rEngineLoad_pct * 0.5);

        // Clamp Valve Command
        IF rSeawaterFlowValveCmd_pct > 100.0 THEN
            rSeawaterFlowValveCmd_pct := 100.0;
        ELSIF rSeawaterFlowValveCmd_pct < 20.0 THEN
            rSeawaterFlowValveCmd_pct := 20.0;
        END_IF;

        // pH Buffering Control
        fbpHPID(
            ACT := rWashWaterpH_In,
            SET := rTargetpH,
            KP := 1.2,
            TN := T#5s,
            TV := T#0s,
            Y_MAN := 0.0,
            MAN_ON := FALSE
        );

        IF rWashWaterpH_In < rTargetpH THEN
            bCausticSodaPumpCmd := TRUE;
            rCausticSodaValveCmd_pct := fbpHPID.Y;
        ELSE
            bCausticSodaPumpCmd := FALSE;
            rCausticSodaValveCmd_pct := 0.0;
        END_IF;

        // SOx Alarm
        IF rSOxEmission_ppm > rMaxSOx_ppm THEN
            bSOxComplianceAlarm := TRUE;
        ELSE
            bSOxComplianceAlarm := FALSE;
        END_IF;

        // Separator Sludge Discharge Logic
        IF rWashWaterTurbidity_NTU > rMaxTurbidity THEN
            eState := SLUDGE_DISCHARGE;
        END_IF;

        IF NOT bSystemEnable OR rEngineLoad_pct < 2.0 THEN
            eState := STANDBY;
        END_IF;

    SLUDGE_DISCHARGE:
        bSeparatorDischargeCmd := TRUE;
        tSeparatorTimer(IN := TRUE, PT := T#30s);

        IF tSeparatorTimer.Q THEN
            bSeparatorDischargeCmd := FALSE;
            tSeparatorTimer(IN := FALSE);
            eState := SCRUBBING;
        END_IF;

    FAULT:
        bSeawaterPumpCmd := FALSE;
        rSeawaterFlowValveCmd_pct := 0.0;
        bCausticSodaPumpCmd := FALSE;
        rCausticSodaValveCmd_pct := 0.0;
        bSeparatorStartCmd := FALSE;

        IF NOT bSeparatorFault AND NOT bSystemFault THEN
            eState := INIT;
        END_IF;

END_CASE;

// Timers
tScrubbingTimer(IN := (eState = RAMP_UP), PT := T#60s);
tSeparatorTimer(IN := (eState = SLUDGE_DISCHARGE), PT := T#30s);

// Fault handling
IF bSeparatorFault THEN
    bSystemFault := TRUE;
    eState := FAULT;
END_IF;

END_FUNCTION_BLOCK
