FUNCTION_BLOCK FB_EUV_PhotocathodeGun
TITLE = 'Photocathode RF Gun & Drive Laser Synchronization Controller'
VERSION : 1.0
AUTHOR : 'Chief Accelerator Physicist'

VAR_INPUT
    bEnable                 : BOOL;   // Enable the Photocathode RF Gun controller
    bStart                  : BOOL;   // Transition to STARTING
    bStop                   : BOOL;   // Transition to STOPPING
    bReset                  : BOOL;   // Transition from ABORTED to CLEARED
    bAbort                  : BOOL;   // Immediate transition to ABORTED

    // Feedback Signals
    fDriveLaserPhaseAct     : LREAL;  // Actual phase of Ti:Sapphire 266 nm laser (fs)
    fRFSbandPhaseAct        : LREAL;  // Actual phase of 2.856 GHz S-band RF (fs)
    fRFTemperatureAct       : LREAL;  // RF Cavity temperature (deg C)
    fResonantFreqAct        : LREAL;  // Actual RF gun resonant frequency (Hz)
    fDriveLaserIntensityAct : LREAL;  // Current laser intensity (mJ/pulse)

    // Setpoints
    fRFTempSetpoint         : LREAL := 30.0;     // Target cavity temp to maintain 2.856 GHz
    fPhaseOffsetSetpoint    : LREAL := 0.0;      // Desired fs phase offset between Laser & RF
END_VAR

VAR_OUTPUT
    // PackML Status
    nPackMLState            : INT;    // Current PackML State Enum (1: STOPPED, 2: STARTING, 3: IDLE, 4: RUNNING, 5: ABORTING, 6: ABORTED)
    bReady                  : BOOL;
    bActive                 : BOOL;
    bError                  : BOOL;

    // Control Outputs
    fLaserPhaseCmd          : LREAL;  // Phase control command to Laser PLL (V or steps)
    fWaterCoolingValveCmd   : LREAL;  // 0-100% command to chiller mixing valve
    fPulseShaperPockelsCmd  : LREAL;  // Voltage command for spatial/temporal pulse shaping

    fFreqError              : LREAL;  // Current resonant frequency error (Hz)
    fJitterAct              : LREAL;  // Estimated phase jitter (fs)
END_VAR

VAR
    // PackML State Machine
    State                   : INT := 1; // 1: STOPPED, 2: STARTING, 3: IDLE, 4: RUNNING, 5: ABORTING, 6: ABORTED

    // PLL Controller (Laser to RF Phase Lock)
    fPhaseError             : LREAL;
    fPhaseIntegral          : LREAL;
    fPhaseDerivative        : LREAL;
    fPhasePrevError         : LREAL;

    // PI Controller (Cavity Temperature)
    fTempError              : LREAL;
    fTempIntegral           : LREAL;

    // Tunings - Femtosecond Synchronization
    kp_PLL                  : LREAL := 0.85;
    ki_PLL                  : LREAL := 0.15;
    kd_PLL                  : LREAL := 0.05;

    // Tunings - Cavity Resonance Tuning via Temperature
    kp_Temp                 : LREAL := 12.5;
    ki_Temp                 : LREAL := 3.2;

    // System Constants
    fTargetFrequency        : LREAL := 2856000000.0; // 2.856 GHz S-band
    fMaxFreqDeviation       : LREAL := 10000.0;      // 10 kHz max tolerance
    fTempFreqCoupling       : LREAL := -48500.0;     // -48.5 kHz / degC drift coefficient
END_VAR

// =========================================================
// PackML State Machine Evaluation
// =========================================================
IF bAbort THEN
    State := 6; // Immediate transition to ABORTED
ELSIF State = 6 AND bReset THEN
    State := 1; // Transition to STOPPED upon reset
END_IF;

CASE State OF
    1: // STOPPED
        bReady := TRUE;
        bActive := FALSE;
        fWaterCoolingValveCmd := 0.0;
        fLaserPhaseCmd := 0.0;
        fPulseShaperPockelsCmd := 0.0;

        IF bStart AND bEnable THEN
            State := 2; // STARTING
            bReady := FALSE;
        END_IF;

    2: // STARTING
        // Pre-cool cavity and establish coarse thermal equilibrium
        fTempError := fRFTempSetpoint - fRFTemperatureAct;
        fWaterCoolingValveCmd := (fTempError * kp_Temp);

        // Valve Saturation
        IF fWaterCoolingValveCmd > 100.0 THEN fWaterCoolingValveCmd := 100.0; END_IF;
        IF fWaterCoolingValveCmd < 0.0 THEN fWaterCoolingValveCmd := 0.0; END_IF;

        // Thermal Lock Threshold (0.05 deg C)
        IF ABS(fTempError) < 0.05 THEN
            State := 3; // IDLE
        END_IF;

    3: // IDLE
        IF bStart THEN
            State := 4; // RUNNING
        END_IF;
        IF bStop THEN
            State := 1; // STOPPED
        END_IF;

    4: // RUNNING
        bActive := TRUE;

        // ---------------------------------------------------------
        // 1. Ultra-Low Jitter Phase-Locked Loop (Femtosecond Sync)
        // ---------------------------------------------------------
        fPhaseError := (fRFSbandPhaseAct + fPhaseOffsetSetpoint) - fDriveLaserPhaseAct;
        fPhaseIntegral := fPhaseIntegral + fPhaseError;
        fPhaseDerivative := fPhaseError - fPhasePrevError;
        fPhasePrevError := fPhaseError;

        // PLL Control Output to Drive Laser piezo/EOM
        fLaserPhaseCmd := (kp_PLL * fPhaseError) + (ki_PLL * fPhaseIntegral) + (kd_PLL * fPhaseDerivative);
        fJitterAct := ABS(fPhaseError); // Femtosecond jitter metric

        // Emittance Control via Spatial/Temporal Pulse Shaping
        // Feedforward logic to modulate Pockels cell preventing space-charge blowout at emission
        fPulseShaperPockelsCmd := fDriveLaserIntensityAct * 0.045 + (fJitterAct * 0.001);

        // ---------------------------------------------------------
        // 2. RF Cavity Tuning via Precision Temperature Control
        // ---------------------------------------------------------
        fFreqError := fTargetFrequency - fResonantFreqAct;

        // Cascade Control: Adjust temperature setpoint to compensate for RF drift
        // using the temperature-frequency coupling coefficient.
        fTempError := (fRFTempSetpoint - (fFreqError / fTempFreqCoupling)) - fRFTemperatureAct;
        fTempIntegral := fTempIntegral + fTempError;

        fWaterCoolingValveCmd := (kp_Temp * fTempError) + (ki_Temp * fTempIntegral);

        // Anti-Windup / Valve Saturation limits
        IF fWaterCoolingValveCmd > 100.0 THEN 
            fWaterCoolingValveCmd := 100.0; 
            fTempIntegral := fTempIntegral - fTempError; // Anti-windup
        END_IF;
        IF fWaterCoolingValveCmd < 0.0 THEN 
            fWaterCoolingValveCmd := 0.0; 
            fTempIntegral := fTempIntegral - fTempError; // Anti-windup
        END_IF;

        // Fault Detection: Cavity Detuned beyond tolerance
        IF ABS(fFreqError) > fMaxFreqDeviation THEN
            State := 5; // ABORTING
        END_IF;

        // Operational Stop
        IF bStop THEN
            State := 1; // STOPPED
        END_IF;

    5: // ABORTING
        bActive := FALSE;
        bError := TRUE;
        // Maximize cooling to protect copper cavity from extreme RF heating damage
        fWaterCoolingValveCmd := 100.0;
        fLaserPhaseCmd := 0.0;
        fPulseShaperPockelsCmd := 0.0;
        State := 6; // Move to ABORTED state

    6: // ABORTED
        bActive := FALSE;
        bReady := FALSE;
        // Requires manual Reset transition to STOPPED

END_CASE;

// Update PackML Output Status
nPackMLState := State;

END_FUNCTION_BLOCK
