FUNCTION_BLOCK FB_FloatGlassController
VAR_INPUT
    rTinBathTemp_C : REAL; // Tin bath temperature in Celsius
    rTinBathN2Flow_LPM : REAL; // Measured N2 flow rate
    rTinBathH2Flow_LPM : REAL; // Measured H2 flow rate
    rDrawSpeed_Mmin : REAL; // Current draw speed of the ribbon
    rTargetThickness_mm : REAL; // Desired glass thickness
    rMeasuredThickness_mm : REAL; // Actual measured thickness
    bLehrCoolingEnable : BOOL; // Enable annealing cooling zones
    rLehrZone1Temp_C : REAL; // Transverse cooling zone 1 temp
    rLehrZone2Temp_C : REAL; // Transverse cooling zone 2 temp
    rLehrZone3Temp_C : REAL; // Transverse cooling zone 3 temp
    rLehrTargetTempZone1_C : REAL; // Target temp for zone 1
    rLehrTargetTempZone2_C : REAL; // Target temp for zone 2
    rLehrTargetTempZone3_C : REAL; // Target temp for zone 3
    bSystemEnable : BOOL; // Master system enable
END_VAR

VAR_OUTPUT
    rN2ValveCommand_Pct : REAL; // N2 flow control valve command (0-100%)
    rH2ValveCommand_Pct : REAL; // H2 flow control valve command (0-100%)
    rDrawMotorSpeedCommand_RPM : REAL; // Output to variable frequency drive for draw speed
    rLehrFanSpeedZone1_Pct : REAL; // Cooling fan speed for lehr zone 1
    rLehrFanSpeedZone2_Pct : REAL; // Cooling fan speed for lehr zone 2
    rLehrFanSpeedZone3_Pct : REAL; // Cooling fan speed for lehr zone 3
    bAtmosphereAlarm : BOOL; // Alarm indicating improper N2/H2 reducing ratio
    bThicknessAlarm : BOOL; // Alarm indicating thickness out of spec
    bCoolingFault : BOOL; // Lehr cooling over-temperature fault
END_VAR

VAR
    rN2H2Ratio : REAL;
    rThicknessError : REAL;
    rDrawSpeedAdjust : REAL;
    tAtmosphereTimer : TON;
    tThicknessTimer : TON;

    // PI controller parameters for draw speed adjustment
    rKpDraw : REAL := 5.0;
    rKiDraw : REAL := 0.2;
    rDrawIntegral : REAL := 0.0;

    // Proportional cooling parameters
    rKpCooling : REAL := 2.5;

    // Hysteresis and tolerance constants
    rThickTol_mm : REAL := 0.05; // 50 microns tolerance
    rTempTol_C : REAL := 2.0; // 2 degrees deadband
END_VAR

// 1. Tin Bath Atmospheric Inerting (N2/H2 Mix Control)
IF bSystemEnable THEN
    // Target a specific reducing atmosphere, typically 90% N2, 10% H2 depending on temp
    IF rTinBathTemp_C > 600.0 THEN
        rN2ValveCommand_Pct := 85.0;
        rH2ValveCommand_Pct := 15.0;
    ELSE
        rN2ValveCommand_Pct := 95.0;
        rH2ValveCommand_Pct := 5.0;
    END_IF;

    IF (rTinBathN2Flow_LPM + rTinBathH2Flow_LPM) > 0.0 THEN
        rN2H2Ratio := rTinBathH2Flow_LPM / (rTinBathN2Flow_LPM + rTinBathH2Flow_LPM);
    ELSE
        rN2H2Ratio := 0.0;
    END_IF;

    // Ensure reducing atmosphere is maintained. Alarm if outside 5% - 15% range for 5 seconds.
    tAtmosphereTimer(IN:=(rN2H2Ratio > 0.15 OR rN2H2Ratio < 0.05), PT:=T#5S);
    bAtmosphereAlarm := tAtmosphereTimer.Q;

    // 2. Ribbon Thickness Draw Speed Tracking
    rThicknessError := rMeasuredThickness_mm - rTargetThickness_mm;

    // PI controller for correcting thickness variations via draw speed
    // If thickness is too high (error > 0), increase draw speed to stretch ribbon
    // If thickness is too low (error < 0), decrease draw speed
    IF ABS(rThicknessError) > rThickTol_mm THEN
        rDrawIntegral := rDrawIntegral + (rThicknessError * rKiDraw);
        // Anti-windup constraints on the integral term
        IF rDrawIntegral > 50.0 THEN rDrawIntegral := 50.0; END_IF;
        IF rDrawIntegral < -50.0 THEN rDrawIntegral := -50.0; END_IF;

        rDrawSpeedAdjust := (rThicknessError * rKpDraw) + rDrawIntegral;
    ELSE
        // Reset integral windup if error is within acceptable deadband
        rDrawSpeedAdjust := 0.0;
        rDrawIntegral := 0.0;
    END_IF;

    // Assuming base conversion 1 M/min -> 10 RPM
    rDrawMotorSpeedCommand_RPM := (rDrawSpeed_Mmin * 10.0) + rDrawSpeedAdjust;

    // Alarm if thickness is grossly out of specification for an extended duration
    tThicknessTimer(IN:=(ABS(rThicknessError) > 0.5), PT:=T#10S);
    bThicknessAlarm := tThicknessTimer.Q;

    // 3. Annealing Lehr Transverse Cooling
    IF bLehrCoolingEnable THEN
