FUNCTION_BLOCK FB_SubseaCCS_Injection
VAR_INPUT
    (* Subsea multi-phase pump and wellhead telemetry inputs *)
    bSystemEnable       : BOOL;     (* Main safety interlock system enable signal *)
    bEmergencyShutdown  : BOOL;     (* ESD (Emergency Shutdown) Ok signal from surface platform *)
    rInletPressure      : REAL;     (* Supercritical CO2 inlet pressure (bar), nominal 400 bar *)
    rWellheadTemp       : REAL;     (* Wellhead temperature (deg C) for hydrate monitoring *)
    rFlowRate           : REAL;     (* Multi-phase CO2 flow rate (kg/s) via acoustic telemetry *)
    rHydrateInhibitor   : REAL;     (* Chemical injection rate for MEG/Methanol (L/hr) *)
    bAcousticCommsOK    : BOOL;     (* Status of seabed acoustic telemetry flow-assurance link *)
END_VAR
VAR_OUTPUT
    (* Control and status outputs for surface monitoring *)
    bInjectionReady     : BOOL;     (* Wellhead ready to receive CO2 *)
    rPumpSpeedCmd       : REAL;     (* Speed command to subsea multiphase pump (RPM) *)
    rChokeValvePos      : REAL;     (* Choke valve position (0.0 to 100.0 %) *)
    bHydrateWarning     : BOOL;     (* Impending hydrate formation warning *)
    bCriticalAlarm      : BOOL;     (* General critical fault alarm *)
    bInhibitorPumpRun   : BOOL;     (* Command to run subsea chemical injection pump *)
END_VAR
VAR
    (* Internal State and Timers *)
    iSequenceState      : INT := 0;
    tAcousticTimeout    : TON;
    tHydrateDelay       : TON;
    rPressureError      : REAL;
    rPumpPID_P          : REAL := 2.5;
    rPumpPID_I          : REAL := 0.1;
    rPumpIntegral       : REAL := 0.0;
    rTargetPressure     : REAL := 420.0; (* Bar *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks & Emergency Shutdown *)
IF NOT bEmergencyShutdown OR NOT bSystemEnable THEN
    bInjectionReady := FALSE;
    bCriticalAlarm := TRUE;
    rPumpSpeedCmd := 0.0;
    rChokeValvePos := 0.0;
    bInhibitorPumpRun := FALSE;
    iSequenceState := 0;
    RETURN;
END_IF;

(* 2. Acoustic Telemetry Watchdog *)
tAcousticTimeout(IN := NOT bAcousticCommsOK, PT := T#10S);
IF tAcousticTimeout.Q THEN
    bCriticalAlarm := TRUE;
    iSequenceState := 999; (* Fault state *)
END_IF;

(* 3. Hydrate Formation Suppression Logic (Flow Assurance) *)
(* Supercritical CO2 hydrate curve approx: warning if Temp < 4.0 C at high pressures *)
IF rWellheadTemp < 4.0 AND rInletPressure > 200.0 THEN
    tHydrateDelay(IN := TRUE, PT := T#5S);
    IF tHydrateDelay.Q THEN
        bHydrateWarning := TRUE;
        bInhibitorPumpRun := TRUE; (* Inject MEG/Methanol *)
    END_IF;
ELSE
    tHydrateDelay(IN := FALSE);
    bHydrateWarning := FALSE;
    (* Keep inhibitor running for a minimum time or stop if flow rate is high enough and temp is safe *)
    IF rWellheadTemp > 8.0 THEN
        bInhibitorPumpRun := FALSE;
    END_IF;
END_IF;

(* 4. State Machine for Wellhead Injection Sequence *)
CASE iSequenceState OF
    0: (* IDLE & INITIALIZATION *)
        bInjectionReady := FALSE;
        rPumpSpeedCmd := 0.0;
        rChokeValvePos := 10.0; (* Crack open to equalize *)
        IF bSystemEnable AND bEmergencyShutdown AND NOT bCriticalAlarm THEN
            iSequenceState := 10;
        END_IF;

    10: (* PRESSURIZATION *)
        rChokeValvePos := 25.0;
        IF rInletPressure > 350.0 THEN
            iSequenceState := 20;
        END_IF;

    20: (* PUMP RAMP-UP (PI Control) *)
        rPressureError := rTargetPressure - rInletPressure;
        rPumpIntegral := rPumpIntegral + (rPressureError * 0.1); (* Assuming 100ms cycle for integral approx *)

        (* Anti-windup *)
        IF rPumpIntegral > 1000.0 THEN rPumpIntegral := 1000.0; END_IF;
        IF rPumpIntegral < 0.0 THEN rPumpIntegral := 0.0; END_IF;

        rPumpSpeedCmd := (rPumpPID_P * rPressureError) + (rPumpPID_I * rPumpIntegral);

        IF rPumpSpeedCmd > 3600.0 THEN rPumpSpeedCmd := 3600.0; END_IF;
        IF rPumpSpeedCmd < 1000.0 THEN rPumpSpeedCmd := 1000.0; END_IF;

        IF rInletPressure >= 400.0 THEN
            bInjectionReady := TRUE;
            rChokeValvePos := 100.0; (* Fully open for max injection *)
            iSequenceState := 30;
        END_IF;

    30: (* STEADY INJECTION *)
        (* Maintain steady state, adjust PI if needed *)
        rPressureError := rTargetPressure - rInletPressure;
        rPumpIntegral := rPumpIntegral + (rPressureError * 0.1);
        rPumpSpeedCmd := (rPumpPID_P * rPressureError) + (rPumpPID_I * rPumpIntegral);

        IF rPumpSpeedCmd > 3600.0 THEN rPumpSpeedCmd := 3600.0; END_IF;
        IF rPumpSpeedCmd < 500.0 THEN rPumpSpeedCmd := 500.0; END_IF;

        (* Fallback to pressurization if pressure drops significantly *)
        IF rInletPressure < 300.0 THEN
            bInjectionReady := FALSE;
            iSequenceState := 10;
        END_IF;

    999: (* FAULT HANDLING *)
        bInjectionReady := FALSE;
        rPumpSpeedCmd := 0.0;
        rChokeValvePos := 0.0;
        bInhibitorPumpRun := FALSE;
        (* Require manual reset via disabling bSystemEnable *)
        IF NOT bSystemEnable THEN
            bCriticalAlarm := FALSE;
            iSequenceState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
