FUNCTION_BLOCK FB_DeepSpaceCryoDensifier
(* 
   =============================================================================
   LUMINA ELITE AUTOMATION ARCHITECTURE - IEC 61131-3 STRUCTURED TEXT
   Module: Deep-Space Cryogenic Propellant Densifier (Slush H2/O2)
   Description: Manages sub-triple-point evaporative cooling, continuous 
                auger extrusion of slush hydrogen/oxygen, and ortho-para 
                catalytic conversion. Includes sensor noise filtering,
                multi-layered safety interlocks, and state-machine resilience.
   =============================================================================
*)
VAR_INPUT
    bSystemEnable           : BOOL;     (* System master enable interlock *)
    bEmergencyStop          : BOOL;     (* E-Stop safety relay OK signal *)
    rInletTempK             : REAL;     (* Inlet propellant temperature in Kelvin *)
    rChamberPressure        : REAL;     (* Evaporative cooling chamber pressure in Pa *)
    rAugerTorqueFeedback    : REAL;     (* Slush extrusion auger torque in Nm *)
    rVaporFlowRate          : REAL;     (* Boil-off vapor flow rate in kg/s *)
    bCatalystHeaterOK       : BOOL;     (* Ortho-para converter heater status OK *)
    rOrthoParaRatio         : REAL;     (* Spectroscopic feedback of O/P isomer ratio *)
END_VAR

VAR_OUTPUT
    bDensifierReady         : BOOL;     (* System ready for continuous extrusion *)
    rCoolingValveCmd        : REAL;     (* Evaporative cooling expansion valve command (0-100%) *)
    rAugerSpeedCmd          : REAL;     (* Auger motor speed reference in RPM *)
    bExtrusionActive        : BOOL;     (* Active slush extrusion status *)
    bCriticalAlarm          : BOOL;     (* Critical safety or process alarm *)
    iOperatingState         : INT;      (* Current internal state machine step *)
END_VAR

VAR
    (* Internal state and timers *)
    iState                  : INT := 0; 
    tStabilizationTimer     : TON;
    tFaultDelay             : TON;

    (* Filtered signals *)
    rFiltInletTemp          : REAL;
    rFiltChamberPress       : REAL;
    rFiltAugerTorque        : REAL;

    (* PID variables for cooling loop *)
    rTempSetpoint           : REAL := 13.8;  (* Target sub-triple point H2 temp K *)
    rTempError              : REAL;
    rTempIntegral           : REAL := 0.0;
    rKp                     : REAL := 2.5;
    rKi                     : REAL := 0.15;

    (* Constants *)
    MAX_TORQUE_NM           : REAL := 1500.0;
    MIN_PRESSURE_PA         : REAL := 7000.0; (* Vacuum pump target for H2 triple point *)
END_VAR

(* === MAIN LOGIC === *)

(* Multi-layered safety interlocks *)
IF NOT bEmergencyStop OR NOT bCatalystHeaterOK THEN
    bDensifierReady := FALSE;
    bExtrusionActive := FALSE;
    rCoolingValveCmd := 0.0;
    rAugerSpeedCmd := 0.0;
    bCriticalAlarm := TRUE;
    iState := 999; (* FAULT STATE *)
    iOperatingState := iState;
    RETURN;
END_IF;

(* First-order low-pass filtering for sensor noise mitigation *)
rFiltInletTemp := rFiltInletTemp + 0.1 * (rInletTempK - rFiltInletTemp);
rFiltChamberPress := rFiltChamberPress + 0.05 * (rChamberPressure - rFiltChamberPress);
rFiltAugerTorque := rFiltAugerTorque + 0.2 * (rAugerTorqueFeedback - rFiltAugerTorque);

(* Primary State Machine *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bDensifierReady := FALSE;
        bExtrusionActive := FALSE;
        bCriticalAlarm := FALSE;
        rCoolingValveCmd := 0.0;
        rAugerSpeedCmd := 0.0;

        IF bSystemEnable THEN
            iState := 10;
        END_IF;

    10: (* EVAPORATIVE COOLING PULLDOWN *)
        (* PI Control for Expansion Valve to achieve target vacuum/temperature *)
        rTempError := rFiltInletTemp - rTempSetpoint;
        rTempIntegral := rTempIntegral + rTempError;
        rCoolingValveCmd := (rKp * rTempError) + (rKi * rTempIntegral);

        (* Clamp valve command *)
        IF rCoolingValveCmd > 100.0 THEN
            rCoolingValveCmd := 100.0;
        ELSIF rCoolingValveCmd < 0.0 THEN
            rCoolingValveCmd := 0.0;
        END_IF;

        (* Transition when temp and pressure reach triple point conditions *)
        IF rFiltInletTemp <= (rTempSetpoint + 0.1) AND rFiltChamberPress <= MIN_PRESSURE_PA THEN
            tStabilizationTimer(IN := TRUE, PT := T#120S);
            IF tStabilizationTimer.Q THEN
                tStabilizationTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tStabilizationTimer(IN := FALSE);
        END_IF;

    20: (* SLUSH STABILIZATION AND AUGER STARTUP *)
        bDensifierReady := TRUE;
        rAugerSpeedCmd := 10.0; (* Initial slow rotation *)

        IF rFiltAugerTorque > 100.0 AND rFiltAugerTorque < MAX_TORQUE_NM THEN
            iState := 30;
        END_IF;

    30: (* CONTINUOUS EXTRUSION RUNNING *)
        bExtrusionActive := TRUE;

        (* Modulate auger speed based on ortho-para ratio and torque *)
        IF rOrthoParaRatio > 0.95 THEN
            rAugerSpeedCmd := 45.0; (* Optimal conversion rate *)
        ELSE
            rAugerSpeedCmd := 25.0; (* Slow down to increase residence time in catalyst *)
        END_IF;

        (* Torque protection overload limit *)
        IF rFiltAugerTorque >= MAX_TORQUE_NM THEN
            tFaultDelay(IN := TRUE, PT := T#2S);
            IF tFaultDelay.Q THEN
                iState := 999; (* Transition to fault *)
            END_IF;
        ELSE
            tFaultDelay(IN := FALSE);
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        bDensifierReady := FALSE;
        bExtrusionActive := FALSE;
        rCoolingValveCmd := 0.0;
        rAugerSpeedCmd := 0.0;
        bCriticalAlarm := TRUE;

        (* Requires reset of system enable to attempt recovery *)
        IF NOT bSystemEnable THEN
            iState := 0;
            bCriticalAlarm := FALSE;
        END_IF;

END_CASE;

(* Update external state monitor *)
iOperatingState := iState;

END_FUNCTION_BLOCK
```

