FUNCTION_BLOCK FB_DP3_AzimuthThruster
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main DP3 enable from bridge control *)
    bEmergencyStop          : BOOL;     (* Hardwired E-stop safety loop OK *)
    rAzimuthCmdDeg          : REAL;     (* Desired azimuth angle (0.0 - 360.0 deg) *)
    rThrustCmdPct           : REAL;     (* Desired thrust percentage (0.0 - 100.0%) *)
    rAzimuthFbkDeg          : REAL;     (* Feedback from absolute encoder *)
    rShaftTorque            : REAL;     (* Direct drive shaft torque measurement *)
    rVibrationRms           : REAL;     (* Accelerometer vibration level *)
    bAcousticValid          : BOOL;     (* Acoustic reference position valid (marine snow check) *)
END_VAR
VAR_OUTPUT
    bThrusterReady          : BOOL;     (* Drive online and healthy *)
    bFaultActive            : BOOL;     (* Critical fault present *)
    rAzimuthDriveSetpt      : REAL;     (* Vector drive azimuth setpoint *)
    rMotorTorqueSetpt       : REAL;     (* Thruster motor torque setpoint *)
    iOperatingState         : INT;      (* Internal state machine status *)
    rFilteredTorque         : REAL;     (* Diagnostics: wave-impact filtered torque *)
END_VAR
VAR
    (* Internal State and Timers *)
    iState                  : INT := 0; (* 0: INIT, 10: STANDBY, 20: RUN, 99: FAULT *)
    tEStopTimer             : TON;
    tAcousticLossTimer      : TON;
    tTransientFilter        : TON;

    (* Filtering and PID Variables *)
    rTorqueBuffer           : ARRAY[0..9] OF REAL;
    iBufferIdx              : INT := 0;
    rTorqueSum              : REAL := 0.0;
    rTorqueAvg              : REAL := 0.0;
    rPrevAzimuthCmd         : REAL := 0.0;
    rAzimuthError           : REAL := 0.0;
    rAzimuthIntegral        : REAL := 0.0;
    rAzimuthDerivative      : REAL := 0.0;
    rPrevAzimuthError       : REAL := 0.0;

    (* DP3 Limits and Constants *)
    Kp_Azimuth              : REAL := 1.25;
    Ki_Azimuth              : REAL := 0.05;
    Kd_Azimuth              : REAL := 0.10;
    rMaxTorqueOverride      : REAL := 95.0; (* Limit for wave transient impacts *)
    rMaxVibration           : REAL := 8.5;  (* mm/s RMS warning limit *)
END_VAR

(* === MAIN LOGIC: SAFETY AND INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bThrusterReady := FALSE;
    bFaultActive := TRUE;
    iOperatingState := 99;
    rMotorTorqueSetpt := 0.0;
    rAzimuthDriveSetpt := rAzimuthFbkDeg; (* Lock azimuth *)
    RETURN;
END_IF;

(* Continuous Moving Average Filter for Wave-Impact Torque Suppression *)
rTorqueSum := rTorqueSum - rTorqueBuffer[iBufferIdx];
rTorqueBuffer[iBufferIdx] := rShaftTorque;
rTorqueSum := rTorqueSum + rTorqueBuffer[iBufferIdx];
iBufferIdx := (iBufferIdx + 1) MOD 10;
rFilteredTorque := rTorqueSum / 10.0;

(* Acoustic Reference Marine Snow Reflection Reject Timer *)
tAcousticLossTimer(IN := NOT bAcousticValid, PT := T#2S500MS);
IF tAcousticLossTimer.Q THEN
    (* Fallback to inertial/dead reckoning assumed handled at DP central control, local thruster goes to hold *)
    bFaultActive := TRUE;
END_IF;

(* Shortest Path Azimuth Calculation (Continuous Slip-Ring Vectoring) *)
rAzimuthError := rAzimuthCmdDeg - rAzimuthFbkDeg;
IF rAzimuthError > 180.0 THEN
    rAzimuthError := rAzimuthError - 360.0;
ELSIF rAzimuthError < -180.0 THEN
    rAzimuthError := rAzimuthError + 360.0;
END_IF;

(* PID Calculation for Azimuth Vectoring *)
rAzimuthIntegral := rAzimuthIntegral + (rAzimuthError * 0.02); (* Assuming 20ms cycle *)
(* Anti-windup *)
IF rAzimuthIntegral > 50.0 THEN rAzimuthIntegral := 50.0; END_IF;
IF rAzimuthIntegral < -50.0 THEN rAzimuthIntegral := -50.0; END_IF;

rAzimuthDerivative := (rAzimuthError - rPrevAzimuthError) / 0.02;
rPrevAzimuthError := rAzimuthError;

(* State Machine Execution *)
CASE iState OF
    0: (* INIT - Power Up Checks *)
        bThrusterReady := FALSE;
        rMotorTorqueSetpt := 0.0;
        IF bSystemEnable AND (rVibrationRms < rMaxVibration) THEN
            iState := 10;
        END_IF;

    10: (* STANDBY - Ready for DP Control *)
        bThrusterReady := TRUE;
        rMotorTorqueSetpt := 0.0;
        rAzimuthDriveSetpt := rAzimuthFbkDeg;
        IF rThrustCmdPct > 1.0 THEN
            iState := 20;
        END_IF;
        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* RUN - Active Dynamic Positioning *)
        bThrusterReady := TRUE;

        (* Azimuth Output Apply *)
        rAzimuthDriveSetpt := rAzimuthFbkDeg + (Kp_Azimuth * rAzimuthError) + (Ki_Azimuth * rAzimuthIntegral) + (Kd_Azimuth * rAzimuthDerivative);

        (* Thrust Apply with Transient Wave Impact Limit *)
        IF rFilteredTorque > rMaxTorqueOverride THEN
            (* Throttle back if wave slam imparts extreme torque counter to drive *)
            rMotorTorqueSetpt := rThrustCmdPct * 0.5;
        ELSE
            rMotorTorqueSetpt := rThrustCmdPct;
        END_IF;

        IF rThrustCmdPct <= 1.0 THEN
            iState := 10;
        END_IF;

        IF bFaultActive OR (rVibrationRms >= rMaxVibration) THEN
            iState := 99;
        END_IF;

    99: (* FAULT - Safe Shutdown *)
        bThrusterReady := FALSE;
        rMotorTorqueSetpt := 0.0;
        (* Maintain position if acoustic loss but keep zero thrust *)
        rAzimuthDriveSetpt := rAzimuthFbkDeg; 
        IF NOT bFaultActive AND bSystemEnable THEN
            iState := 0; (* Reset sequence *)
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
```

