FUNCTION_BLOCK FB_WEC_Array_Controller
VAR_INPUT
    bEnable                 : BOOL;   (* Enable WEC controller *)
    fHeaveVelocity_ms       : REAL;   (* WEC buoy heave velocity in m/s *)
    fHeavePosition_m        : REAL;   (* WEC buoy heave position relative to mean sea level *)
    fWaveElevation_m        : REAL;   (* Preview wave elevation from upstream LiDAR/Radar *)
    fMooringTension_kN      : REAL;   (* Current tension on main mooring line *)
    fHydraulicPressure_bar  : REAL;   (* Accumulator pressure in bar *)
    fGridPowerDemand_kW     : REAL;   (* Power demand from onshore grid *)
END_VAR

VAR_OUTPUT
    fGeneratorDamping_N_s_m : REAL;   (* Commanded linear generator damping force coefficient *)
    fGeneratorForce_kN      : REAL;   (* Applied electromagnetic force by linear generator *)
    fWinchCommand_Speed     : REAL;   (* Commanded mooring winch payout/haul-in speed (-1.0 to 1.0) *)
    fHydraulicValvePos_pct  : REAL;   (* Commanded position of accumulator discharge valve 0-100% *)
    bFault_OverTension      : BOOL;   (* Fault: Mooring tension exceeds safety limit *)
    bFault_OverPressure     : BOOL;   (* Fault: Hydraulic pressure exceeds safety limit *)
END_VAR

VAR
    fDampingBase            : REAL := 50000.0;
    fOptimalDamping         : REAL;
    fMooringLimit_kN        : REAL := 2500.0;
    fMooringNominal_kN      : REAL := 1200.0;
    fPressureLimit_bar      : REAL := 350.0;
    fPressureTarget_bar     : REAL := 280.0;
    fErrorPressure          : REAL;
    fKp_Pressure            : REAL := 0.5;
    fKi_Pressure            : REAL := 0.01;
    fIntegral_Pressure      : REAL := 0.0;

    (* PTO Smoothing *)
    fPowerAvailable_kW      : REAL;
    fPowerError_kW          : REAL;

    (* Timers and state *)
    tFaultDelay             : TON;
    eState                  : INT := 0; (* 0=Init, 1=Active, 2=Fault *)
END_VAR

(* Implementation *)
IF NOT bEnable THEN
    fGeneratorDamping_N_s_m := 0.0;
    fGeneratorForce_kN := 0.0;
    fWinchCommand_Speed := 0.0;
    fHydraulicValvePos_pct := 0.0;
    eState := 0;
    RETURN;
END_IF;

(* Fault Monitoring *)
IF fMooringTension_kN > fMooringLimit_kN THEN
    bFault_OverTension := TRUE;
ELSE
    bFault_OverTension := FALSE;
END_IF;

IF fHydraulicPressure_bar > fPressureLimit_bar THEN
    bFault_OverPressure := TRUE;
ELSE
    bFault_OverPressure := FALSE;
END_IF;

IF bFault_OverTension OR bFault_OverPressure THEN
    eState := 2;
ELSE
    eState := 1;
END_IF;

IF eState = 2 THEN
    (* Fault State Actions: Freewheel generator, payout mooring to reduce tension *)
    fGeneratorDamping_N_s_m := 0.0;
    fGeneratorForce_kN := 0.0;
    IF bFault_OverTension THEN
        fWinchCommand_Speed := 1.0; (* Max payout *)
    END_IF;
    IF bFault_OverPressure THEN
        fHydraulicValvePos_pct := 100.0; (* Dump pressure *)
    END_IF;
    RETURN;
END_IF;

(* 1. Linear Generator Heave Damping Active Control *)
(* Implement reactive control: Optimal damping is proportional to wave frequency, but we approximate using velocity and preview *)
IF ABS(fHeaveVelocity_ms) > 0.1 THEN
    fOptimalDamping := fDampingBase * (1.0 + ABS(fWaveElevation_m) * 0.2);
    fGeneratorDamping_N_s_m := LIMIT(10000.0, fOptimalDamping, 150000.0);
ELSE
    fGeneratorDamping_N_s_m := 10000.0; (* Minimum damping *)
END_IF;
(* Generator force = Damping * Velocity *)
fGeneratorForce_kN := (fGeneratorDamping_N_s_m * fHeaveVelocity_ms) / 1000.0;

(* 2. Dynamic Mooring Tensioning *)
(* Keep mooring tension close to nominal, compensate for tide/heave position *)
IF fMooringTension_kN > (fMooringNominal_kN + 200.0) THEN
    fWinchCommand_Speed := 0.5; (* Payout *)
ELSIF fMooringTension_kN < (fMooringNominal_kN - 200.0) THEN
    fWinchCommand_Speed := -0.5; (* Haul-in *)
ELSE
    fWinchCommand_Speed := 0.0;
END_IF;

(* 3. Hydraulic Accumulator Power Smoothing *)
(* PI Controller for keeping hydraulic pressure at target while delivering grid power *)
fErrorPressure := fHydraulicPressure_bar - fPressureTarget_bar;
fIntegral_Pressure := fIntegral_Pressure + (fErrorPressure * 0.1); (* Assuming 100ms cycle *)
fIntegral_Pressure := LIMIT(-50.0, fIntegral_Pressure, 50.0);

(* Discharge valve responds to both grid demand and pressure regulation *)
fPowerAvailable_kW := fHydraulicPressure_bar * 5.0; (* rough conversion factor *)
fPowerError_kW := fGridPowerDemand_kW - fPowerAvailable_kW;

fHydraulicValvePos_pct := (fGridPowerDemand_kW / 5000.0) * 100.0 + (fErrorPressure * fKp_Pressure + fIntegral_Pressure * fKi_Pressure);
fHydraulicValvePos_pct := LIMIT(0.0, fHydraulicValvePos_pct, 100.0);

END_FUNCTION_BLOCK
```

```iec-st
### Reasoning for IEC 62443 and SCADA Integration
To align with IEC 62443 standards, the control system must segment the SCADA communication into a distinct zone with a well-defined conduit to the controller. Data originating from SCADA (like remote setpoints) must be sanitized and bounded to prevent malicious or accidental out-of-range inputs from jeopardizing the physical safety of the fume hood operators. Dual-redundant failover guarantees availability, ensuring that if the primary exhaust fan fails, the secondary fan immediately takes over without dropping the face velocity below lethal thresholds.

### Siemens SCL Code
FUNCTION_BLOCK "FB_FumeHood_Reasoning"
VAR_INPUT
    SCADA_Enable : Bool;
    SCADA_Velocity_SP : Real;
    FaceVelocity_PV : Real;
    FanA_Fault : Bool;
    FanB_Fault : Bool;
END_VAR
VAR_OUTPUT
    FanA_Command : Real;
    FanB_Command : Real;
    ActiveFan : Int; // 1 = Fan A, 2 = Fan B
    SecurityZone_Alarm : Bool;
END_VAR
VAR
    PID_Controller : "PID_Compact";
    Validated_SP : Real;
    Base_CV : Real;
END_VAR

BEGIN
    // IEC 62443 Conduit Sanitation (Limit setpoints to safe boundaries)
    IF #SCADA_Velocity_SP < 0.3 OR #SCADA_Velocity_SP > 1.0 THEN
        #SecurityZone_Alarm := TRUE;
        #Validated_SP := 0.5; // Fallback safe setpoint
    ELSE
        #SecurityZone_Alarm := FALSE;
        #Validated_SP := #SCADA_Velocity_SP;
    END_IF;

    // VAV PID
    #PID_Controller(
        Setpoint := #Validated_SP,
        Input := #FaceVelocity_PV,
        Reset := NOT #SCADA_Enable,
        Output => #Base_CV
    );

    // Dual-Redundant Failover Logic
    IF NOT #FanA_Fault THEN
        #ActiveFan := 1;
        #FanA_Command := #Base_CV;
        #FanB_Command := 0.0;
    ELSIF NOT #FanB_Fault THEN
        #ActiveFan := 2;
        #FanB_Command := #Base_CV;
        #FanA_Command := 0.0;
    ELSE
        #ActiveFan := 0;
        #FanA_Command := 0.0;
        #FanB_Command := 0.0;
    END_IF;
END_FUNCTION_BLOCK
