FUNCTION_BLOCK FB_StenterFrameControl
VAR_INPUT
    bEnable : BOOL; // System enable
    rFabricSpeed_SetPoint : REAL; // m/min
    rFabricWidth_SetPoint : REAL; // mm

    // Multi-zone convection drying (5 zones)
    arZoneTemp_SetPoints : ARRAY[1..5] OF REAL; // Degree C
    arZoneTemp_Actual : ARRAY[1..5] OF REAL; // Degree C

    // Selvedge overfeed tracking
    rLeftOverfeed_Actual : REAL; // %
    rRightOverfeed_Actual : REAL; // %
    rLeftTension_Actual : REAL; // N
    rRightTension_Actual : REAL; // N

    // Weft straightener skew correction
    rWeftSkewAngle_Actual : REAL; // Degrees
    rWeftBowDetection_Actual : REAL; // mm
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bAlarmActive : BOOL;

    // Zone heating control
    arZoneHeating_Output : ARRAY[1..5] OF REAL; // 0-100%
    arZoneFanSpeed_Output : ARRAY[1..5] OF REAL; // 0-100%

    // Overfeed control
    rLeftOverfeed_Output : REAL; // %
    rRightOverfeed_Output : REAL; // %

    // Weft correction control
    rSkewMotor_Speed : REAL; // %
    rBowRoller_Position : REAL; // mm
END_VAR

VAR
    i : INT;
    rTempError : REAL;
    rIntegral : ARRAY[1..5] OF REAL;
    rKp_Temp : REAL := 2.5;
    rKi_Temp : REAL := 0.1;

    rOverfeedSetPoint : REAL := 5.0; // 5% overfeed target
    rOverfeedErrorL : REAL;
    rOverfeedErrorR : REAL;

    rSkewKp : REAL := 1.5;
END_VAR

IF NOT bEnable THEN
    bSystemReady := FALSE;
    bAlarmActive := FALSE;
    FOR i := 1 TO 5 DO
        arZoneHeating_Output[i] := 0.0;
        arZoneFanSpeed_Output[i] := 0.0;
        rIntegral[i] := 0.0;
    END_FOR
    rLeftOverfeed_Output := 0.0;
    rRightOverfeed_Output := 0.0;
    rSkewMotor_Speed := 0.0;
    rBowRoller_Position := 0.0;
    RETURN;
END_IF;

bSystemReady := TRUE;

// 1. Multi-zone convection drying profiles
FOR i := 1 TO 5 DO
    rTempError := arZoneTemp_SetPoints[i] - arZoneTemp_Actual[i];
    rIntegral[i] := rIntegral[i] + (rTempError * 0.1); // Assuming 100ms cycle

    // Anti-windup
    IF rIntegral[i] > 100.0 THEN rIntegral[i] := 100.0; END_IF;
    IF rIntegral[i] < -100.0 THEN rIntegral[i] := -100.0; END_IF;

    arZoneHeating_Output[i] := (rKp_Temp * rTempError) + (rKi_Temp * rIntegral[i]);

    // Clamp output
    IF arZoneHeating_Output[i] > 100.0 THEN arZoneHeating_Output[i] := 100.0; END_IF;
    IF arZoneHeating_Output[i] < 0.0 THEN arZoneHeating_Output[i] := 0.0; END_IF;

    // Fan speed proportional to heating demand with a base speed
    arZoneFanSpeed_Output[i] := 30.0 + (arZoneHeating_Output[i] * 0.7);
END_FOR

// 2. Fabric selvedge overfeed optical tracking
// Simplified P-control for tension/overfeed balance
rOverfeedErrorL := rOverfeedSetPoint - rLeftOverfeed_Actual;
rOverfeedErrorR := rOverfeedSetPoint - rRightOverfeed_Actual;

rLeftOverfeed_Output := rOverfeedSetPoint + (rOverfeedErrorL * 0.5) - (rLeftTension_Actual * 0.01);
rRightOverfeed_Output := rOverfeedSetPoint + (rOverfeedErrorR * 0.5) - (rRightTension_Actual * 0.01);

// Limit overfeed outputs
IF rLeftOverfeed_Output > 20.0 THEN rLeftOverfeed_Output := 20.0; END_IF;
IF rRightOverfeed_Output > 20.0 THEN rRightOverfeed_Output := 20.0; END_IF;
IF rLeftOverfeed_Output < -10.0 THEN rLeftOverfeed_Output := -10.0; END_IF;
IF rRightOverfeed_Output < -10.0 THEN rRightOverfeed_Output := -10.0; END_IF;

// 3. Weft straightener skew correction
// Corrects diagonal distortion in the woven fabric
IF ABS(rWeftSkewAngle_Actual) > 0.5 THEN
    rSkewMotor_Speed := rWeftSkewAngle_Actual * rSkewKp;
ELSE
    rSkewMotor_Speed := 0.0;
END_IF;

IF rSkewMotor_Speed > 100.0 THEN rSkewMotor_Speed := 100.0; END_IF;
IF rSkewMotor_Speed < -100.0 THEN rSkewMotor_Speed := -100.0; END_IF;

// Bow correction based on physical bow detection
rBowRoller_Position := rWeftBowDetection_Actual * 1.2;
IF rBowRoller_Position > 50.0 THEN rBowRoller_Position := 50.0; END_IF;
IF rBowRoller_Position < -50.0 THEN rBowRoller_Position := -50.0; END_IF;

END_FUNCTION_BLOCK
