FUNCTION_BLOCK "AmineSweetening_Depth"
VAR_INPUT
    RichAmineFlow_PV : REAL;
    RichAmineFlow_SP : REAL;
    LeanAmineFlow_PV : REAL;
    LeanAmineFlow_SP : REAL;
    ReboilerTemp_PV : REAL;
    ReboilerTemp_SP : REAL;
    AbsorberLevel_PV : REAL;
    AbsorberLevel_SP : REAL;
    AbsorberPress_PV : REAL;
    CycleTime : REAL := 0.1;
END_VAR
VAR_OUTPUT
    RichAmineValve : REAL;
    LeanAmineValve : REAL;
    ReboilerSteamValve : REAL;
    GasOfftakeValve : REAL;
END_VAR
VAR
    RichFlowErrSum : REAL := 0.0;
    LeanFlowErrSum : REAL := 0.0;
    TempErrSum : REAL := 0.0;
    LevelErrSum : REAL := 0.0;
    Kp : REAL := 1.5;
    Ki : REAL := 0.5;
END_VAR
BEGIN
    VAR LevelErr := AbsorberLevel_SP - AbsorberLevel_PV;
    LevelErrSum := LevelErrSum + (LevelErr * CycleTime);
    VAR FlowCascadedSP := (Kp * LevelErr) + (Ki * LevelErrSum);

    VAR RichFlowErr := (RichAmineFlow_SP + FlowCascadedSP) - RichAmineFlow_PV;
    RichFlowErrSum := RichFlowErrSum + (RichFlowErr * CycleTime);
    RichAmineValve := (Kp * RichFlowErr) + (Ki * RichFlowErrSum);

    VAR LeanFlowErr := LeanAmineFlow_SP - LeanAmineFlow_PV;
    LeanFlowErrSum := LeanFlowErrSum + (LeanFlowErr * CycleTime);
    LeanAmineValve := (Kp * LeanFlowErr) + (Ki * LeanFlowErrSum);

    VAR TempErr := ReboilerTemp_SP - ReboilerTemp_PV;
    TempErrSum := TempErrSum + (TempErr * CycleTime);
    ReboilerSteamValve := (2.0 * TempErr) + (0.2 * TempErrSum);

    VAR PressErr := 50.0 - AbsorberPress_PV;
    GasOfftakeValve := 100.0 - (1.2 * PressErr);

    IF RichAmineValve > 100.0 THEN RichAmineValve := 100.0; ELSIF RichAmineValve < 0.0 THEN RichAmineValve := 0.0; END_IF;
    IF LeanAmineValve > 100.0 THEN LeanAmineValve := 100.0; ELSIF LeanAmineValve < 0.0 THEN LeanAmineValve := 0.0; END_IF;
    IF ReboilerSteamValve > 100.0 THEN ReboilerSteamValve := 100.0; ELSIF ReboilerSteamValve < 0.0 THEN ReboilerSteamValve := 0.0; END_IF;
    IF GasOfftakeValve > 100.0 THEN GasOfftakeValve := 100.0; ELSIF GasOfftakeValve < 0.0 THEN GasOfftakeValve := 0.0; END_IF;
END_FUNCTION_BLOCK
