FUNCTION_BLOCK FB_DryBulkShipUnloader
VAR_INPUT
    bEnable : BOOL; // Enable unloader operations
    fBoomLuffAngle : REAL; // Current boom luffing angle (degrees)
    fTrolleyPos : REAL; // Current trolley position (meters)
    fHoistPos : REAL; // Current hoist vertical position (meters)
    fGrabOpenAngle : REAL; // Grab open angle (degrees)
    fSwayAngleX : REAL; // Pendulum sway angle X (degrees)
    fSwayAngleY : REAL; // Pendulum sway angle Y (degrees)
    bHatchClearanceSensor : BOOL; // TRUE if grab is clear of hatch coaming
    bCollisionWarning : BOOL; // Anti-collision laser scanner input
    fWindSpeed : REAL; // Wind speed (m/s)
END_VAR
VAR_OUTPUT
    bBoomLuffUpCmd : BOOL;
    bBoomLuffDownCmd : BOOL;
    fTrolleySpeedCmd : REAL; // Trolley speed setpoint (m/s)
    fHoistSpeedCmd : REAL; // Hoist speed setpoint (m/s)
    bGrabOpenCmd : BOOL;
    bGrabCloseCmd : BOOL;
    bEmergencyStop : BOOL;
    fAntiSwayCompensation : REAL;
    bSystemReady : BOOL;
END_VAR
VAR
    state : INT := 0; // State machine state
    fTargetTrolleyPos : REAL := 0.0;
    fTargetHoistPos : REAL := 0.0;
    fLuffingTrajectory : ARRAY[0..10] OF REAL := [10.0, 15.0, 20.0, 25.0, 30.0, 35.0, 40.0, 45.0, 50.0, 55.0, 60.0];
    tSwayTimer : TON;
    fSwayDampingFactor : REAL := 0.05;
    fMaxWindSpeed : REAL := 20.0; // Max allowed wind speed (m/s)
END_VAR

// Initialization and Safety Checks
IF NOT bEnable OR bCollisionWarning OR (fWindSpeed > fMaxWindSpeed) THEN
    bBoomLuffUpCmd := FALSE;
    bBoomLuffDownCmd := FALSE;
    fTrolleySpeedCmd := 0.0;
    fHoistSpeedCmd := 0.0;
    bGrabOpenCmd := FALSE;
    bGrabCloseCmd := FALSE;
    bSystemReady := FALSE;
    IF bCollisionWarning OR (fWindSpeed > fMaxWindSpeed) THEN
        bEmergencyStop := TRUE;
    END_IF;
    RETURN;
ELSE
    bEmergencyStop := FALSE;
    bSystemReady := TRUE;
END_IF;

// Anti-Sway Damping Calculation
// Utilizes an inverted pendulum model with PD control to calculate damping effort
fAntiSwayCompensation := (fSwayAngleX * 2.5) + (fSwayAngleY * 1.5) * fSwayDampingFactor;

// If sway is critical, prioritize trolley speed adjustment to dampen
IF ABS(fSwayAngleX) > 5.0 OR ABS(fSwayAngleY) > 5.0 THEN
    fTrolleySpeedCmd := fTrolleySpeedCmd - fAntiSwayCompensation;
    // Cap trolley speed
    IF fTrolleySpeedCmd > 1.5 THEN fTrolleySpeedCmd := 1.5; END_IF;
    IF fTrolleySpeedCmd < -1.5 THEN fTrolleySpeedCmd := -1.5; END_IF;
END_IF;

// Main State Machine for Unloader Cycle
CASE state OF
    0: // Idle / Move to Hatch
        IF bHatchClearanceSensor THEN
            state := 1; // Hatch is clear, proceed to lower grab
            fTargetHoistPos := 20.0; // Target depth in hatch
        END_IF;

    1: // Lowering Grab
        IF fHoistPos < fTargetHoistPos THEN
            fHoistSpeedCmd := 1.0; // Lowering speed
        ELSE
            fHoistSpeedCmd := 0.0;
            state := 2; // Grab is positioned
        END_IF;

    2: // Closing Grab (Digging)
        bGrabCloseCmd := TRUE;
        bGrabOpenCmd := FALSE;
        IF fGrabOpenAngle < 5.0 THEN
            bGrabCloseCmd := FALSE;
            state := 3; // Grab is closed, begin hoist
        END_IF;

    3: // Hoisting Full Grab
        IF fHoistPos > 5.0 THEN
            fHoistSpeedCmd := -1.0; // Raising speed
        ELSE
            fHoistSpeedCmd := 0.0;
            IF bHatchClearanceSensor THEN
                state := 4; // Clear of hatch, trolley to hopper
                fTargetTrolleyPos := 50.0; // Hopper position
            END_IF;
        END_IF;

    4: // Trolley to Hopper
        IF fTrolleyPos < fTargetTrolleyPos THEN
            fTrolleySpeedCmd := 1.5 - ABS(fAntiSwayCompensation); // Move to hopper while damping sway
        ELSE
            fTrolleySpeedCmd := 0.0;
            state := 5; // Over hopper, open grab
        END_IF;

    5: // Open Grab (Discharge)
        bGrabOpenCmd := TRUE;
        bGrabCloseCmd := FALSE;
        IF fGrabOpenAngle > 85.0 THEN
            bGrabOpenCmd := FALSE;
            state := 6; // Grab is open, trolley back to hatch
            fTargetTrolleyPos := 10.0; // Hatch position
        END_IF;

    6: // Trolley to Hatch
        IF fTrolleyPos > fTargetTrolleyPos THEN
            fTrolleySpeedCmd := -1.5 + ABS(fAntiSwayCompensation);
        ELSE
            fTrolleySpeedCmd := 0.0;
            state := 0; // Cycle complete
        END_IF;

    ELSE
        state := 0;
END_CASE;
END_FUNCTION_BLOCK
