FUNCTION_BLOCK FB_GantryMilling_5AxisCNC
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStopOk        : BOOL;     (* Safety circuit OK *)
    rSpindleVibrationX      : REAL;     (* High-freq vibration X-axis (m/s^2) *)
    rSpindleVibrationY      : REAL;     (* High-freq vibration Y-axis (m/s^2) *)
    rSpindleVibrationZ      : REAL;     (* High-freq vibration Z-axis (m/s^2) *)
    rTempSpindleBearing     : REAL;     (* Spindle bearing temperature (deg C) *)
    rTempColumnLeft         : REAL;     (* Left gantry column temperature (deg C) *)
    rTempColumnRight        : REAL;     (* Right gantry column temperature (deg C) *)
    rHydrostaticPressure    : REAL;     (* Hydrostatic guideway pressure (bar) *)
    rTargetSpindleSpeed     : REAL;     (* Commanded spindle speed (RPM) *)
    rTargetFeedRate         : REAL;     (* Commanded tool feed rate (mm/min) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready for operation *)
    bChatterAlarm           : BOOL;     (* Chatter vibration limit exceeded *)
    bThermalAlarm           : BOOL;     (* Thermal limits exceeded *)
    bHydrostaticAlarm       : BOOL;     (* Guideway clearance pressure fault *)
    rActualSpindleSpeed     : REAL;     (* Compensated spindle speed output (RPM) *)
    rActualFeedRate         : REAL;     (* Compensated feed rate output (mm/min) *)
    rVolumetricCompX        : REAL;     (* Volumetric thermal compensation X (um) *)
    rVolumetricCompY        : REAL;     (* Volumetric thermal compensation Y (um) *)
    rVolumetricCompZ        : REAL;     (* Volumetric thermal compensation Z (um) *)
    rHydrostaticThrottle    : REAL;     (* Active throttle control valve (0-100%) *)
END_VAR
VAR
    iState                  : INT := 0; (* Main state machine variable *)
    tStartupDelay           : TON;      (* Delay for hydrostatic stabilization *)
    tChatterFilter          : TON;      (* Filter for transient vibration spikes *)
    rTotalVibration         : REAL;     (* Calculated vibration vector magnitude *)
    rThermalDelta           : REAL;     (* Temperature differential across columns *)
    rCompFactorX            : REAL := 1.25; (* Empirical thermal factor X *)
    rCompFactorY            : REAL := 0.85; (* Empirical thermal factor Y *)
    rCompFactorZ            : REAL := 2.10; (* Empirical thermal factor Z *)
    bFault                  : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and Fault Monitoring *)
IF NOT bEmergencyStopOk THEN
    bSystemReady := FALSE;
    bChatterAlarm := FALSE;
    bThermalAlarm := FALSE;
    bHydrostaticAlarm := FALSE;
    rActualSpindleSpeed := 0.0;
    rActualFeedRate := 0.0;
    rHydrostaticThrottle := 0.0;
    rVolumetricCompX := 0.0;
    rVolumetricCompY := 0.0;
    rVolumetricCompZ := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* 2. Process High-Frequency Vibration (Chatter Detection) *)
rTotalVibration := SQRT(rSpindleVibrationX * rSpindleVibrationX + rSpindleVibrationY * rSpindleVibrationY + rSpindleVibrationZ * rSpindleVibrationZ);

tChatterFilter(IN := (rTotalVibration > 15.0), PT := T#200MS);
IF tChatterFilter.Q THEN
    bChatterAlarm := TRUE;
    bFault := TRUE;
ELSE
    bChatterAlarm := FALSE;
END_IF;

(* 3. Thermal Monitoring & Volumetric Error Compensation Mapping *)
IF rTempSpindleBearing > 85.0 OR rTempColumnLeft > 45.0 OR rTempColumnRight > 45.0 THEN
    bThermalAlarm := TRUE;
    bFault := TRUE;
ELSE
    bThermalAlarm := FALSE;
    rThermalDelta := rTempColumnLeft - rTempColumnRight;

    (* Sophisticated thermal kinematic model calculation (simplified for PLC constraint) *)
    rVolumetricCompX := (rTempSpindleBearing - 20.0) * rCompFactorX;
    rVolumetricCompY := (rThermalDelta) * rCompFactorY;
    rVolumetricCompZ := (rTempSpindleBearing - 20.0) * rCompFactorZ + (rTempColumnLeft + rTempColumnRight)/2.0 * 0.5;
END_IF;

(* 4. Active Hydrostatic Guideway Clearance Throttling *)
IF rHydrostaticPressure < 40.0 THEN
    rHydrostaticThrottle := 100.0; (* Full open to build pressure *)
    bHydrostaticAlarm := TRUE;
ELSIF rHydrostaticPressure > 60.0 THEN
    rHydrostaticThrottle := 20.0; (* Restrict to prevent excess lift *)
    bHydrostaticAlarm := FALSE;
ELSE
    (* Closed loop PI-like throttle response *)
    rHydrostaticThrottle := 50.0 + (50.0 - rHydrostaticPressure) * 2.0;
    bHydrostaticAlarm := FALSE;
END_IF;

IF bHydrostaticAlarm AND iState >= 20 THEN
    bFault := TRUE;
END_IF;

(* 5. State Machine for Spindle and Feed Control *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bFault := FALSE;
        rActualSpindleSpeed := 0.0;
        rActualFeedRate := 0.0;
        IF bEnable AND NOT bFault THEN
            iState := 10;
        END_IF;

    10: (* HYDROSTATIC PRESSURE STABILIZATION *)
        tStartupDelay(IN := TRUE, PT := T#3S);
        IF tStartupDelay.Q THEN
            IF NOT bHydrostaticAlarm THEN
                tStartupDelay(IN := FALSE);
                iState := 20;
            ELSE
                bFault := TRUE;
            END_IF;
        END_IF;

    20: (* RUNNING WITH ACTIVE OVERRIDE & COMPENSATION *)
        bSystemReady := TRUE;

        (* Chatter suppression logic: Reduce feedrate and vary spindle speed if vibration is high but not critical *)
        IF rTotalVibration > 10.0 AND rTotalVibration <= 15.0 THEN
            rActualSpindleSpeed := rTargetSpindleSpeed * 0.90; (* 10% speed reduction *)
            rActualFeedRate := rTargetFeedRate * 0.70;         (* 30% feed reduction *)
        ELSE
            rActualSpindleSpeed := rTargetSpindleSpeed;
            rActualFeedRate := rTargetFeedRate;
        END_IF;

        IF NOT bEnable OR bFault THEN
            iState := 0;
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
