FUNCTION_BLOCK FB_ExtruderControl_Mut1
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    MeltPressure_SP : REAL;
    MeltPressure_PV : REAL;
    TempZone_SP : ARRAY[1..5] OF REAL;
    TempZone_PV : ARRAY[1..5] OF REAL;
    AutoMode : BOOL;
END_VAR
VAR_OUTPUT
    ScrewSpeed_CV : REAL;
    Heater_CV : ARRAY[1..5] OF REAL;
    Cooler_CV : ARRAY[1..5] OF REAL;
    Running : BOOL;
    ThermalInterlock : BOOL;
    Fault : BOOL;
END_VAR
VAR
    PID_Melt : PID_Compact;
    PID_Temp : ARRAY[1..5] OF PID_Compact;
    i : INT;
    TempOKCount : INT;
    State : INT := 0;
END_VAR

BEGIN
    TempOKCount := 0;
    FOR i := 1 TO 5 DO
        PID_Temp[i](
            Setpoint := TempZone_SP[i],
            Input := TempZone_PV[i],
            Reset := (State = 0)
        );
        IF PID_Temp[i].Output > 0.0 THEN
            Heater_CV[i] := PID_Temp[i].Output;
            Cooler_CV[i] := 0.0;
        ELSE
            Heater_CV[i] := 0.0;
            Cooler_CV[i] := ABS(PID_Temp[i].Output);
        END_IF;

        IF (TempZone_PV[i] > (TempZone_SP[i] - 10.0)) AND (TempZone_PV[i] < (TempZone_SP[i] + 10.0)) THEN
            TempOKCount := TempOKCount + 1;
        END_IF;
    END_FOR;

    ThermalInterlock := (TempOKCount = 5);

    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 AND ThermalInterlock THEN
        State := 1;
    END_IF;

    Running := (State = 1);

    IF State = 1 THEN
        PID_Melt(
            Setpoint := MeltPressure_SP,
            Input := MeltPressure_PV,
            Reset := FALSE
        );
        ScrewSpeed_CV := PID_Melt.Output;
    ELSE
        ScrewSpeed_CV := 0.0;
        PID_Melt(Reset := TRUE);
    END_IF;
END_FUNCTION_BLOCK
