FUNCTION_BLOCK FB_CARTCellTherapy_BioreactorControl
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable for bioreactor control *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (E-Stop circuit) *)
    rMeasuredDO             : REAL;     (* Measured Dissolved Oxygen (%) *)
    rMeasuredPH             : REAL;     (* Measured pH value (0.0-14.0) *)
    rMeasuredTemp           : REAL;     (* Measured Temperature in deg C *)
    rTargetDO               : REAL;     (* Target Dissolved Oxygen setpoint (%) *)
    rTargetPH               : REAL;     (* Target pH setpoint (0.0-14.0) *)
    rTargetTemp             : REAL;     (* Target Temperature setpoint (deg C) *)
    rRockingRateFeedback    : REAL;     (* Feedback from rocking platform (RPM) *)
    rRockingAngleFeedback   : REAL;     (* Feedback from rocking angle (Degrees) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System ready status for upstream/downstream handshakes *)
    bAlarm                  : BOOL;     (* General fault alarm output *)
    iErrorCode              : INT;      (* Specific error code for diagnostic tracing *)
    rO2ValveControl         : REAL;     (* Output to O2 proportional valve (0-100%) *)
    rCO2ValveControl        : REAL;     (* Output to CO2 proportional valve (0-100%) *)
    rBasePumpControl        : REAL;     (* Output to Base addition pump (0-100%) *)
    rHeaterControl          : REAL;     (* Output to heater SSR control (0-100%) *)
    rRockingRateSP          : REAL;     (* Setpoint for rocking platform rate (RPM) *)
    rRockingAngleSP         : REAL;     (* Setpoint for rocking platform angle (Degrees) *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state machine variable *)

    (* PID controllers for various loops *)
    pidDO                   : PID;      (* PID for Dissolved Oxygen control *)
    pidPH_CO2               : PID;      (* PID for pH control via CO2 (acidic) *)
    pidPH_Base              : PID;      (* PID for pH control via Base (alkaline) *)
    pidTemp                 : PID;      (* PID for Temperature control *)

    (* Timers for debouncing and sequencing *)
    tStartupDelay           : TON;
    tAlarmDelay             : TON;
    tSafetyInterlock        : TOF;

    (* Internal computed variables *)
    rPHError                : REAL;
    rDOError                : REAL;
    rTempError              : REAL;
    bTempInBand             : BOOL;
    bPHInBand               : BOOL;
    bDOInBand               : BOOL;

    (* Constants for alarms and limits *)
    MAX_TEMP_DEV            : REAL := 0.5;  (* Maximum temperature deviation *)
    MAX_PH_DEV              : REAL := 0.1;  (* Maximum pH deviation *)
    MAX_DO_DEV              : REAL := 5.0;  (* Maximum DO deviation *)
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety and Interlock Processing *)
IF NOT bEmergencyStop THEN
    (* Hard stop all outputs on safety circuit break *)
    bSystemReady := FALSE;
    bAlarm := TRUE;
    iErrorCode := 9999; (* 9999 = E-STOP ACTIVE *)
    rO2ValveControl := 0.0;
    rCO2ValveControl := 0.0;
    rBasePumpControl := 0.0;
    rHeaterControl := 0.0;
    rRockingRateSP := 0.0;
    rRockingAngleSP := 0.0;
    iState := 0; (* Force to IDLE *)
    RETURN;
END_IF;

(* 2. Process Variables and Errors Calculation *)
rPHError := rTargetPH - rMeasuredPH;
rDOError := rTargetDO - rMeasuredDO;
rTempError := rTargetTemp - rMeasuredTemp;

bTempInBand := ABS(rTempError) <= MAX_TEMP_DEV;
bPHInBand := ABS(rPHError) <= MAX_PH_DEV;
bDOInBand := ABS(rDOError) <= MAX_DO_DEV;

(* 3. State Machine for Bioreactor Operation *)
CASE iState OF
    0: (* IDLE / OFF STATE *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        iErrorCode := 0;

        rO2ValveControl := 0.0;
        rCO2ValveControl := 0.0;
        rBasePumpControl := 0.0;
        rHeaterControl := 0.0;
        rRockingRateSP := 0.0;
        rRockingAngleSP := 0.0;

        IF bEnable THEN
            tStartupDelay(IN := TRUE, PT := T#2S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 10; (* Transition to PREPARE *)
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

    10: (* PREPARE / HOMING / INITIAL CHECKS *)
        (* Engage minimal rocking to prevent settling before full cascade starts *)
        rRockingRateSP := 10.0; (* 10 RPM base rate *)
        rRockingAngleSP := 6.0; (* 6 degree base angle *)

        IF ABS(rRockingRateFeedback - rRockingRateSP) < 2.0 AND ABS(rRockingAngleFeedback - rRockingAngleSP) < 1.0 THEN
            iState := 20; (* Transition to HEATING *)
        END_IF;

    20: (* HEATING TO SETPOINT *)
        (* Temperature control is prioritized before gas exchange optimization *)
        pidTemp(ACT := rMeasuredTemp, SET := rTargetTemp, KP := 2.5, TN := T#60S, TV := T#10S, Y => rHeaterControl);

        IF bTempInBand THEN
            iState := 30; (* Transition to CASCADING CONTROL (DO/pH) *)
        END_IF;

    30: (* FULL RUNNING / CASCADING CONTROL *)
        bSystemReady := TRUE;

        (* Temperature Control loop continuous update *)
        pidTemp(ACT := rMeasuredTemp, SET := rTargetTemp, KP := 2.5, TN := T#60S, TV := T#10S, Y => rHeaterControl);

        (* DO Control: Increase O2 to raise DO *)
        pidDO(ACT := rMeasuredDO, SET := rTargetDO, KP := 1.2, TN := T#30S, TV := T#5S, Y => rO2ValveControl);

        (* pH Control: Split range control. If pH is too high, add CO2. If pH is too low, add Base *)
        IF rPHError < 0.0 THEN
            (* pH is higher than target, needs acid (CO2) *)
            pidPH_CO2(ACT := rMeasuredPH, SET := rTargetPH, KP := -1.5, TN := T#45S, TV := T#0S, Y => rCO2ValveControl);
            rBasePumpControl := 0.0;
        ELSE
            (* pH is lower than target, needs base *)
            pidPH_Base(ACT := rMeasuredPH, SET := rTargetPH, KP := 0.8, TN := T#120S, TV := T#0S, Y => rBasePumpControl);
            rCO2ValveControl := 0.0;
        END_IF;

        (* Rocking Profile Adjustments based on DO demands (KLa optimization) *)
        IF rO2ValveControl > 80.0 THEN
            (* If high O2 demand, increase rocking to improve gas transfer *)
            rRockingRateSP := MIN(25.0, rRockingRateSP + 0.1); 
            rRockingAngleSP := MIN(12.0, rRockingAngleSP + 0.1);
        ELSIF rO2ValveControl < 20.0 THEN
            (* Lower shearing forces if DO is easily maintained *)
            rRockingRateSP := MAX(10.0, rRockingRateSP - 0.1);
            rRockingAngleSP := MAX(6.0, rRockingAngleSP - 0.1);
        END_IF;

        (* Alarm Monitoring during run *)
        tAlarmDelay(IN := (NOT bTempInBand OR NOT bPHInBand OR NOT bDOInBand), PT := T#300S);
        IF tAlarmDelay.Q THEN
            bAlarm := TRUE;
            iErrorCode := 1001; (* 1001 = Process Out Of Control Band *)
            iState := 99; (* Transition to FAULT *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rHeaterControl := 0.0;
        rO2ValveControl := 0.0;
        rCO2ValveControl := 0.0;
        rBasePumpControl := 0.0;
        (* Maintain minimal rocking in fault to save cells if possible *)
        rRockingRateSP := 5.0; 
        rRockingAngleSP := 4.0;

        IF NOT bEnable THEN
            iState := 0; (* Acknowledge fault by dropping enable *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
