FUNCTION_BLOCK FB_ZeroGravityCryoTransfer
(* =====================================================================================
   Title:        Deep-Space Cryogenic Propellant Zero-Gravity Transfer Pump
   Author:       Senior Automation Architect
   Description:  Advanced zero-G propellant transfer system for superfluid helium.
                 Includes cavitation suppression, thermodynamic vent system (TVS)
                 ullage pressure tracking, and piezoelectric acoustic phase discrimination.
   Version:      1.0.0
   ===================================================================================== *)

VAR_INPUT
    bSystemEnable           : BOOL;     (* Main activation signal for the transfer system *)
    bEmergencyStop          : BOOL;     (* Redundant safety interlock (TRUE = OK, FALSE = STOP) *)
    rInletTempK             : REAL;     (* Cryogenic inlet temperature [Kelvin] (typically ~2K for superfluid He) *)
    rUllagePressure_Pa      : REAL;     (* Thermodynamic Vent System (TVS) ullage pressure [Pascals] *)
    rPiezoAcousticNoise     : REAL;     (* Piezoelectric sensor acoustic feedback [Vrms] for cavitation detection *)
    rMassFlowTarget_kg_s    : REAL;     (* Target mass flow rate for propellant transfer [kg/s] *)
END_VAR

VAR_OUTPUT
    bPumpRunning            : BOOL;     (* Status indicating the primary transfer pump is active *)
    rPumpSpeedCmd           : REAL;     (* Modulated pump speed command [%] (0.0 to 100.0) *)
    bCavitationWarning      : BOOL;     (* Cavitation suppression active warning *)
    rTVSSpargerDuty         : REAL;     (* Duty cycle for TVS ullage pressure regulation [%] *)
    bSystemFault            : BOOL;     (* Aggregate system fault flag *)
    iDiagnosticCode         : INT;      (* 0 = OK, 1xxx = Interlocks, 2xxx = Sensor, 3xxx = Cavitation, 4xxx = TVS *)
END_VAR

VAR
    iState                  : INT := 0; (* Internal state machine tracker *)
    tStartupDelay           : TON;      (* Delay timer to stabilize acoustic sensors during startup *)
    tPurgeTimer             : TON;      (* Purge cycle timer for gas venting *)
    rFilteredInletTemp      : REAL := 0.0;
    rFilteredAcousticNoise  : REAL := 0.0;
    rErrorPressure          : REAL;
    rSpeedIntegralTerm      : REAL := 0.0;
    rTVSThermalDerivative   : REAL := 0.0;
    rLastUllagePressure     : REAL := 0.0;
    bInitialize             : BOOL := TRUE;

    (* Filter Constants *)
    ALPHA_TEMP              : REAL := 0.05;
    ALPHA_ACOUSTIC          : REAL := 0.15;

    (* Cavitation Thresholds *)
    CAV_NOISE_THRESHOLD     : REAL := 1.25;  (* Vrms threshold indicating phase transition (gas pockets) *)
    CAV_NOISE_CRITICAL      : REAL := 3.50;  (* Critical Vrms requiring immediate shutdown *)
END_VAR

(* === MAIN SAFETY & FILTERING === *)
IF NOT bEmergencyStop THEN
    bPumpRunning := FALSE;
    rPumpSpeedCmd := 0.0;
    rTVSSpargerDuty := 0.0;
    bSystemFault := TRUE;
    iDiagnosticCode := 1001; (* E-Stop active *)
    iState := 0;
    RETURN;
END_IF;

(* Exponential Moving Average for noisy deep-space sensors *)
IF bInitialize THEN
    rFilteredInletTemp := rInletTempK;
    rFilteredAcousticNoise := rPiezoAcousticNoise;
    bInitialize := FALSE;
ELSE
    rFilteredInletTemp := (ALPHA_TEMP * rInletTempK) + ((1.0 - ALPHA_TEMP) * rFilteredInletTemp);
    rFilteredAcousticNoise := (ALPHA_ACOUSTIC * rPiezoAcousticNoise) + ((1.0 - ALPHA_ACOUSTIC) * rFilteredAcousticNoise);
END_IF;

(* Calculate Derivative of TVS Ullage Pressure *)
rTVSThermalDerivative := rUllagePressure_Pa - rLastUllagePressure;
rLastUllagePressure := rUllagePressure_Pa;

(* === MAIN ZERO-G PROP TRANSFER STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & SELF-CHECK *)
        bPumpRunning := FALSE;
        rPumpSpeedCmd := 0.0;
        rTVSSpargerDuty := 0.0;
        bSystemFault := FALSE;
        iDiagnosticCode := 0;
        bCavitationWarning := FALSE;

        IF bSystemEnable THEN
            IF rFilteredInletTemp > 4.2 THEN
                (* Inlet temperature too high for liquid He transfer *)
                bSystemFault := TRUE;
                iDiagnosticCode := 2010; 
            ELSE
                iState := 10; (* Transition to TVS Conditioning *)
            END_IF;
        END_IF;

    10: (* TVS ULLAGE CONDITIONING *)
        (* Regulate TVS sparger to stabilize pressure before main transfer *)
        rErrorPressure := 101325.0 - rUllagePressure_Pa; (* Target nominal 1 atm equivalent *)
        IF rErrorPressure > 5000.0 THEN
            rTVSSpargerDuty := 100.0;
        ELSIF rErrorPressure > 0.0 THEN
            rTVSSpargerDuty := rErrorPressure / 50.0;
        ELSE
            rTVSSpargerDuty := 0.0;
        END_IF;

        IF rErrorPressure < 1000.0 AND rErrorPressure > -1000.0 THEN
            tStartupDelay(IN := TRUE, PT := T#10S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 20; (* Transition to Pre-Chill & Spin-Up *)
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* PUMP SPIN-UP & PIEZOELECTRIC ACOUSTIC PHASE DISCRIMINATION *)
        bPumpRunning := TRUE;
        (* Gentle ramp up to prevent fluid hammering in zero-g lines *)
        rPumpSpeedCmd := rPumpSpeedCmd + 0.1;

        (* Cavitation Check *)
        IF rFilteredAcousticNoise > CAV_NOISE_THRESHOLD THEN
            bCavitationWarning := TRUE;
            (* Modulate pump speed down to collapse cavitation bubbles *)
            rPumpSpeedCmd := rPumpSpeedCmd - 0.5;
        ELSE
            bCavitationWarning := FALSE;
        END_IF;

        IF rFilteredAcousticNoise > CAV_NOISE_CRITICAL THEN
            (* Cavitation is uncontrollable, thermal vapor lock risk *)
            bSystemFault := TRUE;
            iDiagnosticCode := 3100;
            iState := 99; (* FAULT STATE *)
        END_IF;

        IF rPumpSpeedCmd >= 100.0 THEN
            rPumpSpeedCmd := 100.0;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bPumpRunning := FALSE;
        rPumpSpeedCmd := 0.0;
        rTVSSpargerDuty := 100.0; (* Full vent to prevent over-pressurization *)
        IF NOT bSystemEnable THEN
            iState := 0; (* Require manual toggle of Enable to clear fault *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
