(*
================================================================================
Function Block: FB_SupercriticalCO2_AllamCycle
Description: Master turbomachinery and combustion controller for a Supercritical 
             CO2 (sCO2) Allam-Fetvedt Cycle power plant.
             Handles high-pressure stoichiometric oxy-combustion (300 bar),
             combustor outlet temperature regulation (1150°C target),
             recuperator management, and highly nonlinear near-critical 
             compressor anti-surge control (31°C, 73 bar).
================================================================================
*)
FUNCTION_BLOCK FB_SupercriticalCO2_AllamCycle
VAR_INPUT
    // System Commands (PackML Inspired)
    bEnable                 : BOOL;       // Enable cycle control
    bStart                  : BOOL;       // Sequence start command
    bStop                   : BOOL;       // Sequence stop command
    bAbort                  : BOOL;       // Emergency abort

    // Combustion Inputs
    fLoadSetpoint_MW        : LREAL;      // Target electrical output (MW)
    fNatGasMassFlow_kg_s    : LREAL;      // Measured Natural Gas mass flow
    fOxygenMassFlow_kg_s    : LREAL;      // Measured O2 mass flow
    fCombustorPressure_bar  : LREAL;      // Measured Combustor Pressure (Target ~300 bar)
    fTurbineInletTemp_C     : LREAL;      // Measured Turbine Inlet Temperature (TIT)

    // Compressor & Fluid Inputs
    fCompressorInletTemp_C  : LREAL;      // Compressor inlet temperature
    fCompressorInletPres_bar: LREAL;      // Compressor inlet pressure
    fCompressorMassFlow_kg_s: LREAL;      // Main compressor sCO2 mass flow
    fCompressorSpeed_RPM    : LREAL;      // Compressor shaft speed

    // Tuning & Constraints
    fMaxTIT_C               : LREAL := 1150.0;  // Max Turbine Inlet Temp (°C)
    fCriticalTemp_CO2_C     : LREAL := 30.98;   // CO2 Critical Temp
    fCriticalPres_CO2_bar   : LREAL := 73.77;   // CO2 Critical Pressure
END_VAR

VAR_OUTPUT
    // Status
    nCurrentState           : INT;        // 0: STOPPED, 1: STARTING, 2: RUNNING, 3: STOPPING, 4: ABORTED
    bSystemReady            : BOOL;
    bTurbineTrip            : BOOL;       // Safety trip active

    // Actuator Commands
    fCmdNatGasValve_pct     : LREAL;      // 0-100% NG Control Valve
    fCmdOxygenValve_pct     : LREAL;      // 0-100% O2 Control Valve
    fCmdAntiSurgeValve_pct  : LREAL;      // 0-100% Compressor Bypass Valve
    fCmdRecuperatorByp_pct  : LREAL;      // 0-100% Recuperator Bypass for Temp Control
    fCmdCoolingWaterValve_pct: LREAL;     // 0-100% Pre-Cooler Water flow

    // Alarms
    bAlmSurgeApproaching    : BOOL;
    bAlmTITDeviation        : BOOL;
    bAlmStoichiometryErr    : BOOL;
    bAlmNearCriticalInstab  : BOOL;       // Approaching critical point instability
END_VAR

VAR
    // Internal States
    eState : (ST_STOPPED := 0, ST_STARTING := 1, ST_RUNNING := 2, ST_STOPPING := 3, ST_ABORTED := 4);

    // Stoichiometry & Combustion Controllers
    fIdealO2_to_NG_Ratio    : LREAL := 3.98; // Stoichiometric mass ratio for CH4 + 2O2 -> CO2 + 2H2O
    fCurrentO2_to_NG_Ratio  : LREAL;

    fErrTIT                 : LREAL;
    fKp_TIT                 : LREAL := 0.25;
    fKi_TIT                 : LREAL := 0.05;
    fIntegral_TIT           : LREAL;

    // Surge Control
    fReducedMassFlow        : LREAL;
    fPressureRatio          : LREAL;
    fSurgeMargin            : LREAL;
    fSurgeControlLine       : LREAL;

    fErrSurge               : LREAL;
    fKp_Surge               : LREAL := 2.5;
    fKi_Surge               : LREAL := 1.1;
    fIntegral_Surge         : LREAL;

    // Near-Critical Fluid Management
    fDensity_kg_m3          : LREAL;
    fCompressibility_Z      : LREAL;

    // Timers
    tStartupTimer           : TON;
    tTripDelay              : TON;

    // Helper function references (assumed internal or external to system)
    // fEOS_PengRobinson(T, P) -> Density, Z
END_VAR

(* 
================================================================================
State Machine & Mode Management
================================================================================
*)
IF bAbort THEN
    eState := ST_ABORTED;
ELSIF NOT bEnable AND eState <> ST_ABORTED THEN
    eState := ST_STOPPING;
END_IF;

CASE eState OF
    ST_STOPPED:
        fCmdNatGasValve_pct := 0.0;
        fCmdOxygenValve_pct := 0.0;
        fCmdAntiSurgeValve_pct := 100.0; // Fully open bypass
        fCmdRecuperatorByp_pct := 100.0;
        fCmdCoolingWaterValve_pct := 100.0;
        bSystemReady := TRUE;
        bTurbineTrip := FALSE;

        IF bEnable AND bStart THEN
            eState := ST_STARTING;
            bSystemReady := FALSE;
        END_IF;

    ST_STARTING:
        // Spool up compressor, establish sCO2 flow, ignite combustor
        fCmdAntiSurgeValve_pct := 80.0;
        fCmdCoolingWaterValve_pct := 50.0;

        // Simplified startup sequence timer
        tStartupTimer(IN:= TRUE, PT:= T#60S);
        IF tStartupTimer.Q THEN
            eState := ST_RUNNING;
            tStartupTimer(IN:= FALSE);
        END_IF;

    ST_RUNNING:
        // Normal Operation Logic handled below
        IF bStop THEN
            eState := ST_STOPPING;
        END_IF;

    ST_STOPPING:
        // Controlled shutdown
        fCmdNatGasValve_pct := fCmdNatGasValve_pct * 0.99;
        fCmdOxygenValve_pct := fCmdOxygenValve_pct * 0.99;
        IF (fCmdNatGasValve_pct < 1.0) THEN
            eState := ST_STOPPED;
        END_IF;

    ST_ABORTED:
        // Emergency Trip
        fCmdNatGasValve_pct := 0.0;
        fCmdOxygenValve_pct := 0.0;
        fCmdAntiSurgeValve_pct := 100.0;
        fCmdRecuperatorByp_pct := 100.0;
        fCmdCoolingWaterValve_pct := 100.0;
        bTurbineTrip := TRUE;

        IF NOT bAbort AND bStart THEN
            eState := ST_STOPPED;
        END_IF;
END_CASE;

nCurrentState := eState;

IF eState <> ST_RUNNING THEN
    RETURN; // Skip dynamic control if not running
END_IF;

(* 
================================================================================
1. Oxy-Combustion Stoichiometry & Turbine Inlet Temp (TIT) Control
================================================================================
*)
// Calculate current mixture ratio (avoid division by zero)
IF fNatGasMassFlow_kg_s > 0.01 THEN
    fCurrentO2_to_NG_Ratio := fOxygenMassFlow_kg_s / fNatGasMassFlow_kg_s;
ELSE
    fCurrentO2_to_NG_Ratio := fIdealO2_to_NG_Ratio;
END_IF;

bAlmStoichiometryErr := ABS(fCurrentO2_to_NG_Ratio - fIdealO2_to_NG_Ratio) > 0.15;

// PI Controller for Turbine Inlet Temperature
// Modulates base Natural Gas Flow based on load, trimmed by TIT error
fErrTIT := fMaxTIT_C - fTurbineInletTemp_C;

IF NOT bTurbineTrip THEN
    fIntegral_TIT := fIntegral_TIT + (fErrTIT * fKi_TIT * 0.01); // Assumes 10ms cycle
    // Anti-windup
    IF fIntegral_TIT > 50.0 THEN fIntegral_TIT := 50.0; END_IF;
    IF fIntegral_TIT < -50.0 THEN fIntegral_TIT := -50.0; END_IF;
END_IF;

// Feed-forward load mapping + PI Trim
fCmdNatGasValve_pct := (fLoadSetpoint_MW * 0.2) + (fErrTIT * fKp_TIT) + fIntegral_TIT;
fCmdNatGasValve_pct := LIMIT(0.0, fCmdNatGasValve_pct, 100.0);

// Oxygen Valve tracks NG Valve maintaining exact stoichiometry
fCmdOxygenValve_pct := fCmdNatGasValve_pct * (fIdealO2_to_NG_Ratio / fCurrentO2_to_NG_Ratio);
fCmdOxygenValve_pct := LIMIT(0.0, fCmdOxygenValve_pct, 100.0);

bAlmTITDeviation := ABS(fErrTIT) > 25.0;

// Trip Condition
IF fTurbineInletTemp_C > (fMaxTIT_C + 20.0) THEN
    bTurbineTrip := TRUE;
    eState := ST_ABORTED;
END_IF;

(* 
================================================================================
2. Near-Critical Fluid Management (Compressor Inlet)
================================================================================
*)
// Maintain compressor inlet temperature just above critical point to ensure dense phase 
// but avoid 2-phase fluid destruction of impeller blades. Target ~ 32°C.
// Modulation of pre-cooler cooling water valve.
VAR
    fErrInletTemp : LREAL;
    fTargetInletTemp : LREAL := 32.0;
END_VAR

fErrInletTemp := fCompressorInletTemp_C - fTargetInletTemp;
fCmdCoolingWaterValve_pct := fCmdCoolingWaterValve_pct + (fErrInletTemp * 1.5);
fCmdCoolingWaterValve_pct := LIMIT(10.0, fCmdCoolingWaterValve_pct, 100.0);

// Alert if drifting too close to the vapor dome
bAlmNearCriticalInstab := (fCompressorInletTemp_C < (fCriticalTemp_CO2_C + 0.5)) OR
                          (ABS(fCompressorInletPres_bar - fCriticalPres_CO2_bar) < 2.0);

(* 
================================================================================
3. Anti-Surge Control for sCO2 Compressor
================================================================================
*)
// Simplified aerodynamic map parameters
// Reduced Mass Flow = m * sqrt(T) / P
fReducedMassFlow := (fCompressorMassFlow_kg_s * SQRT(fCompressorInletTemp_C + 273.15)) / fCompressorInletPres_bar;
fPressureRatio := fCombustorPressure_bar / fCompressorInletPres_bar; // Discharge P is roughly combustor P

// Surge Control Line (SCL) mapping (polynomial fit for this specific compressor map)
fSurgeControlLine := 1.2 * fReducedMassFlow * fReducedMassFlow + 0.5 * fReducedMassFlow + 1.1;

// Control margin 10% right of the actual surge line
fSurgeMargin := fSurgeControlLine * 1.1;

fErrSurge := fPressureRatio - fSurgeMargin;

// Anti-Surge PI controller (Reverse acting - open valve if error is positive)
IF fErrSurge > 0.0 THEN
    fIntegral_Surge := fIntegral_Surge + (fErrSurge * fKi_Surge * 0.01);
    bAlmSurgeApproaching := TRUE;
ELSE
    // Decay integral if safe
    fIntegral_Surge := fIntegral_Surge * 0.95;
    bAlmSurgeApproaching := FALSE;
END_IF;
fIntegral_Surge := LIMIT(0.0, fIntegral_Surge, 100.0);

fCmdAntiSurgeValve_pct := (fErrSurge * fKp_Surge) + fIntegral_Surge;

// Asymmetrical fast-open / slow-close logic
IF fErrSurge > 0.2 THEN
    fCmdAntiSurgeValve_pct := fCmdAntiSurgeValve_pct + 15.0; // Fast step open
END_IF;

fCmdAntiSurgeValve_pct := LIMIT(0.0, fCmdAntiSurgeValve_pct, 100.0);

END_FUNCTION_BLOCK
