FUNCTION_BLOCK "FB_TempPID"
TITLE = 'Temperature PID Controller'
VERSION : '1.0'

VAR_INPUT
    Setpoint : REAL;
    ProcessValue : REAL;
    ManualMode : BOOL;
    ManualOutput : REAL;
    Kp : REAL;
    Ti : REAL;
    Td : REAL;
    Ts : REAL;
    OutMin : REAL;
    OutMax : REAL;
END_VAR

VAR_OUTPUT
    Output : REAL;
END_VAR

VAR
    IntTerm : REAL;
    PrevProcessValue : REAL;
END_VAR

VAR_TEMP
    Error : REAL;
    PropTerm : REAL;
    DerivTerm : REAL;
    RawOutput : REAL;
    DeltaPV : REAL;
END_VAR

BEGIN
    Error := Setpoint - ProcessValue;
    DeltaPV := ProcessValue - PrevProcessValue;

    IF ManualMode THEN
        Output := ManualOutput;
        IntTerm := Output;
        IF IntTerm > OutMax THEN IntTerm := OutMax;
        ELSIF IntTerm < OutMin THEN IntTerm := OutMin;
        END_IF;
    ELSE
        PropTerm := Kp * Error;

        IF Ti > 0.0 THEN
            IntTerm := IntTerm + ((Kp * Ts) / Ti) * Error;
        END_IF;

        IF IntTerm > OutMax THEN IntTerm := OutMax;
        ELSIF IntTerm < OutMin THEN IntTerm := OutMin;
        END_IF;

        IF Ts > 0.0 THEN
            DerivTerm := - (Kp * Td / Ts) * DeltaPV;
        ELSE
            DerivTerm := 0.0;
        END_IF;

        RawOutput := PropTerm + IntTerm + DerivTerm;

        IF RawOutput > OutMax THEN Output := OutMax;
        ELSIF RawOutput < OutMin THEN Output := OutMin;
        ELSE Output := RawOutput;
        END_IF;
    END_IF;

    PrevProcessValue := ProcessValue;
END_FUNCTION_BLOCK
