FUNCTION_BLOCK FB_GridFormingInverter
VAR_INPUT
    Enable : BOOL; (* Enable inverter operation *)
    GridFreq_Meas : REAL; (* Measured grid frequency in Hz *)
    GridVolts_Meas : REAL; (* Measured grid voltage in V *)
    P_SetPoint : REAL; (* Active power setpoint in kW *)
    Q_SetPoint : REAL; (* Reactive power setpoint in kVAR *)
    Freq_Nominal : REAL := 50.0; (* Nominal frequency in Hz *)
    Volts_Nominal : REAL := 400.0; (* Nominal voltage in V *)
    Droop_P : REAL := 0.05; (* Active power droop coefficient (Hz/kW) *)
    Droop_Q : REAL := 0.05; (* Reactive power droop coefficient (V/kVAR) *)
    Inertia_H : REAL := 5.0; (* Synthetic inertia constant in seconds *)
    Damping_D : REAL := 0.1; (* Damping coefficient *)
    SampleTime : REAL := 0.001; (* Execution cycle time in seconds *)
END_VAR

VAR_OUTPUT
    P_Output_Ref : REAL; (* Active power output reference kW *)
    Q_Output_Ref : REAL; (* Reactive power output reference kVAR *)
    Theta_Ref : REAL; (* Internal voltage angle reference rad *)
    E_Ref : REAL; (* Internal voltage magnitude reference V *)
    Status_Ready : BOOL;
    Fault_Active : BOOL;
END_VAR

VAR
    Omega_Nominal : REAL;
    Omega_Meas : REAL;
    Omega_Ref : REAL;
    Delta_P : REAL;
    Delta_Q : REAL;
    Integral_Freq : REAL := 0.0;
    Derivative_Freq : REAL := 0.0;
    Prev_GridFreq : REAL := 50.0;
    Virtual_Rotor_Speed : REAL := 1.0; (* Per unit *)
    Virtual_Angle : REAL := 0.0;
    P_Electromagnetic : REAL;
    P_Mechanical : REAL;
END_VAR

(* Implementation of Virtual Synchronous Generator (VSG) Control *)
IF NOT Enable THEN
    P_Output_Ref := 0.0;
    Q_Output_Ref := 0.0;
    Theta_Ref := 0.0;
    E_Ref := 0.0;
    Status_Ready := FALSE;
    Integral_Freq := 0.0;
    Virtual_Angle := 0.0;
    Virtual_Rotor_Speed := 1.0;
    RETURN;
END_IF;

Status_Ready := TRUE;
Fault_Active := FALSE;

(* Convert frequencies to angular velocities *)
Omega_Nominal := 2.0 * 3.14159265359 * Freq_Nominal;
Omega_Meas := 2.0 * 3.14159265359 * GridFreq_Meas;

(* Active Power Droop Control (P-f) *)
Delta_P := (Freq_Nominal - GridFreq_Meas) / Droop_P;
P_Mechanical := P_SetPoint + Delta_P;

(* Reactive Power Droop Control (Q-V) *)
Delta_Q := (Volts_Nominal - GridVolts_Meas) / Droop_Q;
Q_Output_Ref := Q_SetPoint + Delta_Q;

(* Internal Voltage Magnitude Reference (Droop based) *)
E_Ref := Volts_Nominal + (Q_Output_Ref * Droop_Q);

(* Synthetic Inertia (Swing Equation) *)
(* Virtual Rotor Speed Calculation *)
(* d(delta_omega) / dt = (P_mech - P_elec - D * delta_omega) / (2 * H * omega_nom) *)

P_Electromagnetic := P_Output_Ref; (* Assuming actual output tracks reference closely for the model *)

Derivative_Freq := (P_Mechanical - P_Electromagnetic - Damping_D * (Virtual_Rotor_Speed - 1.0)) / (2.0 * Inertia_H);

Virtual_Rotor_Speed := Virtual_Rotor_Speed + Derivative_Freq * SampleTime;

(* Internal Angle Reference calculation *)
Omega_Ref := Omega_Nominal * Virtual_Rotor_Speed;
Virtual_Angle := Virtual_Angle + (Omega_Ref * SampleTime);

(* Keep Virtual Angle between 0 and 2*PI *)
IF Virtual_Angle >= (2.0 * 3.14159265359) THEN
    Virtual_Angle := Virtual_Angle - (2.0 * 3.14159265359);
ELSIF Virtual_Angle < 0.0 THEN
    Virtual_Angle := Virtual_Angle + (2.0 * 3.14159265359);
END_IF;

Theta_Ref := Virtual_Angle;
P_Output_Ref := P_Mechanical; (* Simplified for setpoint propagation *)

Prev_GridFreq := GridFreq_Meas;
END_FUNCTION_BLOCK
