FUNCTION_BLOCK FB_RingSpinningControl
TITLE = 'High-Speed Textile Ring Spinning Frame Kinematics and Doffing Controller'
VERSION : '2.5'

VAR_INPUT
    bEnable            : BOOL; // Enable the control block
    bEmergencyStop     : BOOL; // Emergency stop signal
    rTargetSpindleRPM  : REAL; // Target spindle speed in RPM
    rYarnCount         : REAL; // Yarn count (tex or Ne)
    rTravelerMass      : REAL; // Traveler mass in mg
    bBrokenEndSensor   : ARRAY[0..119] OF BOOL; // Optical sensors for 120 spindles
    rCurrentCopDiameter: REAL; // Current cop diameter in mm
    rRingDiameter      : REAL; // Ring diameter in mm
    bDoffingRequest    : BOOL; // Request to initiate doffing sequence
END_VAR

VAR_OUTPUT
    rActualSpindleRPM  : REAL; // Commanded spindle speed to VFD
    rRingRailVelocity  : REAL; // Ring rail traverse velocity in mm/s
    bBrokenEndAlarm    : BOOL; // Global broken end alarm
    iBrokenSpindleID   : INT;  // ID of the first broken spindle found
    bDoffingActive     : BOOL; // Doffing sequence is active
    rTravelerSpeed     : REAL; // Calculated traveler speed in m/s
    iState             : INT;  // State machine status
END_VAR

VAR
    rRampRate          : REAL := 50.0; // RPM/s ramp rate
    rMaxTravelerSpeed  : REAL := 40.0; // Max allowable traveler speed (m/s)
    i                  : INT;
    bDoffingInProgress : BOOL := FALSE;
    tDoffTimer         : TON;
    rDoffTargetSpeed   : REAL := 500.0; // Low speed for doffing
    rKinematicFactor   : REAL := 0.0;
    rBaseRailVelocity  : REAL := 15.0; // Base mm/s
    rDiameterRatio     : REAL;
END_VAR

// Constants
VAR CONSTANT
    STATE_IDLE       : INT := 0;
    STATE_RAMP_UP    : INT := 1;
    STATE_RUN        : INT := 2;
    STATE_DOFFING    : INT := 3;
    STATE_FAULT      : INT := 99;
    PI               : REAL := 3.14159265359;
END_VAR

// State Machine
IF bEmergencyStop THEN
    iState := STATE_FAULT;
    rActualSpindleRPM := 0.0;
    rRingRailVelocity := 0.0;
    bDoffingActive := FALSE;
    bBrokenEndAlarm := FALSE;
    iBrokenSpindleID := -1;
ELSIF NOT bEnable AND iState <> STATE_FAULT THEN
    iState := STATE_IDLE;
    rActualSpindleRPM := 0.0;
    rRingRailVelocity := 0.0;
END_IF;

CASE iState OF
    STATE_IDLE:
        bDoffingInProgress := FALSE;
        bDoffingActive := FALSE;
        IF bEnable AND NOT bEmergencyStop THEN
            iState := STATE_RAMP_UP;
        END_IF;

    STATE_RAMP_UP:
        IF rActualSpindleRPM < rTargetSpindleRPM THEN
            rActualSpindleRPM := rActualSpindleRPM + rRampRate * 0.1; // Assuming 100ms cycle
            IF rActualSpindleRPM > rTargetSpindleRPM THEN
                rActualSpindleRPM := rTargetSpindleRPM;
            END_IF;
        ELSE
            iState := STATE_RUN;
        END_IF;

    STATE_RUN:
        // Normal Run operations
        rActualSpindleRPM := rTargetSpindleRPM;

        IF bDoffingRequest THEN
            iState := STATE_DOFFING;
            bDoffingInProgress := TRUE;
        END_IF;

    STATE_DOFFING:
        bDoffingActive := TRUE;
        // Decelerate to doffing speed
        IF rActualSpindleRPM > rDoffTargetSpeed THEN
            rActualSpindleRPM := rActualSpindleRPM - (rRampRate * 0.2);
        END_IF;
        // Doffing logic placeholder...
        IF NOT bDoffingRequest THEN
            bDoffingActive := FALSE;
            bDoffingInProgress := FALSE;
            iState := STATE_RAMP_UP;
        END_IF;

    STATE_FAULT:
        rActualSpindleRPM := 0.0;
        rRingRailVelocity := 0.0;
        IF NOT bEmergencyStop THEN
            iState := STATE_IDLE;
        END_IF;
END_CASE;

// Traveler Kinematics Calculation
// Traveler speed v_t = (pi * D_r * N_s) / 60000 where D_r in mm, N_s in RPM
rTravelerSpeed := (PI * rRingDiameter * rActualSpindleRPM) / 60000.0;

// Limit Spindle speed based on traveler mass and max speed
IF rTravelerSpeed > rMaxTravelerSpeed THEN
    rActualSpindleRPM := (rMaxTravelerSpeed * 60000.0) / (PI * rRingDiameter);
    // Recalculate
    rTravelerSpeed := (PI * rRingDiameter * rActualSpindleRPM) / 60000.0;
END_IF;

// Ring Rail Velocity Modulated by Cop Diameter (Chase traverse)
IF rCurrentCopDiameter > 0.0 THEN
    rDiameterRatio := rRingDiameter / rCurrentCopDiameter;
    rRingRailVelocity := rBaseRailVelocity * rDiameterRatio;
ELSE
    rRingRailVelocity := rBaseRailVelocity;
END_IF;

// Broken End Optical Detection
bBrokenEndAlarm := FALSE;
iBrokenSpindleID := -1;
FOR i := 0 TO 119 DO
    IF bBrokenEndSensor[i] THEN
        bBrokenEndAlarm := TRUE;
        iBrokenSpindleID := i;
        EXIT; // Found first broken end, trigger alarm
    END_IF;
END_FOR;

END_FUNCTION_BLOCK
```

