FUNCTION_BLOCK FB_PHES_PumpTurbine_Control
VAR_INPUT
    (* Physical Inputs: Interlocks & References *)
    bSystemEnable           : BOOL;     (* Main control system enable *)
    bEmergencyStop          : BOOL;     (* Safety relay OK (TRUE = Healthy) *)
    bModeSelectCondenser    : BOOL;     (* Request synchronous condenser mode *)
    rGridActivePowerRef     : REAL;     (* MW, Target active power exchange (-500 to 500) *)

    (* Physical Inputs: DFIM Machine & Grid Sensors *)
    rStatorVoltageRms       : REAL;     (* kV, Grid synchronization voltage feedback *)
    rRotorSpeed             : REAL;     (* RPM, Shaft rotational speed *)

    (* Physical Inputs: Hydraulic System *)
    rPenstockPressure       : REAL;     (* Bar, Main penstock pressure for water hammer detect *)
    rGuideVanePos           : REAL;     (* %, Actual guide vane opening (0.0-100.0) *)
    rTailwaterLevel         : REAL;     (* m, Draft tube / tailwater elevation *)
END_VAR
VAR_OUTPUT
    (* Actuator Controls & Diagnostics *)
    bReadyToSynchronize     : BOOL;     (* System state ready for grid sync breaker closure *)
    rGuideVaneSetPoint      : REAL;     (* %, Target guide vane opening command *)
    rRotorInverterPower     : REAL;     (* MW, Target active power to DFIM Rotor Converter *)

    (* Alarms & Status *)
    bSurgeProtectionActive  : BOOL;     (* Water hammer transient suppressed *)
    bMajorFault             : BOOL;     (* Non-recoverable fault triggered trip *)
    iOperatingState         : INT;      (* Current control state enum *)
END_VAR
VAR
    (* Internal Filtered States *)
    rFiltSpeed              : REAL := 0.0;
    rFiltPressure           : REAL := 0.0;
    rPressureDerivative     : REAL := 0.0;
    rPressureLast           : REAL := 0.0;

    (* Controllers & Timers *)
    tSurgeTimer             : TON;
    tTransitionTimer        : TON;
    tScanCycle              : REAL := 0.01; (* 10ms task cycle time assumed *)
    rGuideVaneRampRate      : REAL := 2.5;  (* %/s max rate of change *)
    rSpeedError             : REAL := 0.0;
    rSpeedKp                : REAL := 15.2;
    rSpeedKi                : REAL := 5.1;
    rSpeedIntegral          : REAL := 0.0;

    (* Internal State Machine *)
    iState                  : INT := 0;
END_VAR

(* === MAIN LOGIC EXECUTION === *)

(* 1. Safety Interlocks & Fallback Defaults *)
IF NOT bEmergencyStop THEN
    bReadyToSynchronize := FALSE;
    bSurgeProtectionActive := FALSE;
    bMajorFault := TRUE;
    rGuideVaneSetPoint := 0.0;
    rRotorInverterPower := 0.0;
    iOperatingState := 999; (* 999 = E-STOP STATE *)
    RETURN;
END_IF;

(* Clear faults if healthy *)
bMajorFault := FALSE;

(* 2. Signal Processing & Noise Filtering (Exponential Moving Average) *)
rFiltSpeed := rFiltSpeed + 0.1 * (rRotorSpeed - rFiltSpeed);
rFiltPressure := rFiltPressure + 0.05 * (rPenstockPressure - rFiltPressure);

(* Calculate Pressure Derivative for Water Hammer Detection *)
rPressureDerivative := (rFiltPressure - rPressureLast) / tScanCycle;
rPressureLast := rFiltPressure;

(* Surge Protection Override (Water Hammer Limit: 100 Bar/s) *)
IF ABS(rPressureDerivative) > 100.0 THEN
    bSurgeProtectionActive := TRUE;
    tSurgeTimer(IN := TRUE, PT := T#5S);
ELSE
    tSurgeTimer(IN := FALSE);
    IF NOT tSurgeTimer.Q THEN
        bSurgeProtectionActive := FALSE;
    END_IF;
END_IF;

(* 3. Main Operational State Machine *)
CASE iState OF
    0: (* IDLE & PRE-CHECKS *)
        rGuideVaneSetPoint := 0.0;
        rRotorInverterPower := 0.0;
        bReadyToSynchronize := FALSE;

        IF bSystemEnable AND NOT bSurgeProtectionActive THEN
            IF bModeSelectCondenser THEN
                iState := 50; (* Sync Condenser Path *)
            ELSE
                iState := 10; (* Normal Generation/Pump Path *)
            END_IF;
        END_IF;

    10: (* SPEED RAMPING (DFIM Synchronization Mode) *)
        rSpeedError := 300.0 - rFiltSpeed; (* Assuming 300 RPM Sync Speed *)

        (* PI Speed Governor (anti-windup limited) *)
        rSpeedIntegral := rSpeedIntegral + (rSpeedError * rSpeedKi * tScanCycle);
        IF rSpeedIntegral > 100.0 THEN rSpeedIntegral := 100.0; END_IF;
        IF rSpeedIntegral < 0.0 THEN rSpeedIntegral := 0.0; END_IF;

        rGuideVaneSetPoint := (rSpeedError * rSpeedKp) + rSpeedIntegral;

        (* Hydromechanical limit enforcement *)
        IF rGuideVaneSetPoint > 100.0 THEN rGuideVaneSetPoint := 100.0; END_IF;
        IF rGuideVaneSetPoint < 0.0 THEN rGuideVaneSetPoint := 0.0; END_IF;

        (* Speed match criteria for sync *)
        IF ABS(rSpeedError) < 1.5 AND rStatorVoltageRms > 15.0 THEN (* 15kV threshold *)
            tTransitionTimer(IN := TRUE, PT := T#2S);
            IF tTransitionTimer.Q THEN
                tTransitionTimer(IN := FALSE);
                bReadyToSynchronize := TRUE;
                iState := 20; (* Active Power Control *)
            END_IF;
        ELSE
            tTransitionTimer(IN := FALSE);
        END_IF;

    20: (* DFIM ACTIVE POWER CONTROL LOOP *)
        (* Override governor with Active Power Ref distributed to Rotor Inverter *)
        rRotorInverterPower := rGridActivePowerRef * 0.15; (* Up to 15% via rotor slip recovery *)

        (* If surge detected, slowly close guide vanes to prevent transient *)
        IF bSurgeProtectionActive THEN
            rGuideVaneSetPoint := rGuideVaneSetPoint - (rGuideVaneRampRate * tScanCycle * 0.5);
            IF rGuideVaneSetPoint < 0.0 THEN rGuideVaneSetPoint := 0.0; END_IF;
        ELSE
            (* Simplified grid loading response *)
            rGuideVaneSetPoint := rGridActivePowerRef / 5.0; (* 500MW -> 100% opening approx *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 90;
        END_IF;

    50: (* SYNCHRONOUS CONDENSER MODE (Blowdown phase) *)
        (* Water is blown down using compressed air, spinning in air to provide MVARs *)
        rGuideVaneSetPoint := 0.0;
        IF rTailwaterLevel < -5.0 THEN
            bReadyToSynchronize := TRUE;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 90;
        END_IF;

    90: (* NORMAL SHUTDOWN *)
        bReadyToSynchronize := FALSE;
        rGuideVaneSetPoint := rGuideVaneSetPoint - (rGuideVaneRampRate * tScanCycle);
        IF rGuideVaneSetPoint <= 0.0 AND rFiltSpeed < 5.0 THEN
            rGuideVaneSetPoint := 0.0;
            iState := 0;
        END_IF;

    ELSE
        (* Failsafe unknown state *)
        iState := 0;
        bMajorFault := TRUE;
END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
