TYPE "Profinet_Cmd_Data"
    STRUCT
        Control_Word : WORD;
        DP_Force_X : REAL;
        DP_Force_Y : REAL;
        DP_Moment_Z : REAL;
    END_STRUCT
END_TYPE

TYPE "Profinet_Stat_Data"
    STRUCT
        Status_Word : WORD;
        Actual_Speed : REAL;
        Actual_Angle : REAL;
        Error_Code : INT;
    END_STRUCT
END_TYPE

FUNCTION_BLOCK "Azipod_Control_Advanced"
VAR_INPUT
    PN_Cmd : "Profinet_Cmd_Data";
    Actual_Angle : REAL;
    Actual_Speed : REAL;
    Motor_Current : REAL;
    Max_Allowed_Current : REAL;
    Inverter_Fault : BOOL;
    Slip_Ring_Temp_High : BOOL;
    Comms_Loss : BOOL;
END_VAR

VAR_OUTPUT
    PN_Stat : "Profinet_Stat_Data";
    Angle_Command : REAL;
    Speed_Command : REAL;
END_VAR

VAR
    Enable : BOOL;
    Overload_Active : BOOL;
    Req_Thrust : REAL;
    Req_Angle : REAL;
    Current_Filter : REAL;
    Fault_Active : BOOL;
END_VAR

BEGIN
    Enable := (PN_Cmd.Control_Word AND 16#0001) <> 0;
    Fault_Active := FALSE;
    PN_Stat.Error_Code := 0;

    // Diagnostics
    IF Comms_Loss THEN
        PN_Stat.Error_Code := 1001; // PN Failure
        Fault_Active := TRUE;
    ELSIF Inverter_Fault THEN
        PN_Stat.Error_Code := 2001; // Drive Trip
        Fault_Active := TRUE;
    ELSIF Slip_Ring_Temp_High THEN
        PN_Stat.Error_Code := 3001; // Slip Ring Overheating
        Fault_Active := TRUE;
    END_IF;

    IF Fault_Active OR NOT Enable THEN
        Angle_Command := Actual_Angle;
        Speed_Command := 0.0;
        PN_Stat.Status_Word := 16#0000;
        RETURN;
    END_IF;

    PN_Stat.Status_Word := 16#0001; // Running

    // Thrust Allocation
    Req_Thrust := SQRT(PN_Cmd.DP_Force_X**2 + PN_Cmd.DP_Force_Y**2);
    IF PN_Cmd.DP_Force_X <> 0.0 THEN
        Req_Angle := ATAN(PN_Cmd.DP_Force_Y / PN_Cmd.DP_Force_X) * 57.2958;
    ELSE
        Req_Angle := 0.0;
    END_IF;

    Req_Angle := Req_Angle + (PN_Cmd.DP_Moment_Z * 0.1); 

    Current_Filter := Current_Filter + 0.1 * (Motor_Current - Current_Filter);
    IF Current_Filter > Max_Allowed_Current THEN
        Overload_Active := TRUE;
        PN_Stat.Error_Code := 4001; // Overload Warning
    ELSIF Current_Filter < (Max_Allowed_Current * 0.8) THEN
        Overload_Active := FALSE;
    END_IF;

    IF Overload_Active THEN
        Speed_Command := Req_Thrust * 0.5;
    ELSE
        Speed_Command := Req_Thrust;
    END_IF;

    Angle_Command := Req_Angle;

    // Update Feedback
    PN_Stat.Actual_Speed := Actual_Speed;
    PN_Stat.Actual_Angle := Actual_Angle;

END_FUNCTION_BLOCK
