FUNCTION_BLOCK FB_HydroRiverController
TITLE = 'Run-of-the-River Hydro Plant Master Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    rHeadwaterLevel : REAL; (* meters *)
    rTailwaterLevel : REAL; (* meters *)
    rTrashRackLevelUp : REAL; (* meters *)
    rTrashRackLevelDown : REAL; (* meters *)
    rGridFrequency : REAL; (* Hz *)
    rActivePowerSetp : REAL; (* MW *)
    bStartCommand : BOOL;
    bStopCommand : BOOL;
    bFishLadderFlowReq : BOOL; (* Fish migration season *)
END_VAR

VAR_OUTPUT
    rWicketGatePosCmd : REAL; (* 0-100% *)
    rKaplanBladePosCmd : REAL; (* 0-100% *)
    bTrashRackCleanerStart : BOOL;
    rFishLadderValvePos : REAL; (* 0-100% *)
    rActivePowerActual : REAL; (* MW *)
    bSystemAlarm : BOOL;
    iState : INT;
END_VAR

VAR
    rGrossHead : REAL;
    rNetHead : REAL;
    rTrashRackDiff : REAL;
    bCleanerActive : BOOL;
    tmrCleanerRun : TON;
    tmrCleanerWait : TON;
    rOptBladeAngle : REAL;
    rSpeedControlOut : REAL;
END_VAR

(* Constants *)
VAR CONSTANT
    TRASH_RACK_MAX_DIFF : REAL := 0.5; (* meters *)
    CLEANER_RUN_TIME : TIME := T#15M;
    ENV_FLOW_MIN : REAL := 5.0; (* m3/s equivalent valve pos *)
    HEAD_MIN : REAL := 3.0; (* meters *)
END_VAR

(* Logic *)
(* Calculate heads *)
rGrossHead := rHeadwaterLevel - rTailwaterLevel;
rTrashRackDiff := rTrashRackLevelUp - rTrashRackLevelDown;
rNetHead := rGrossHead - rTrashRackDiff;

(* Trash Rack Cleaning Logic *)
IF rTrashRackDiff > TRASH_RACK_MAX_DIFF AND NOT bCleanerActive THEN
    bCleanerActive := TRUE;
END_IF;

tmrCleanerRun(IN := bCleanerActive, PT := CLEANER_RUN_TIME);
IF tmrCleanerRun.Q THEN
    bCleanerActive := FALSE;
END_IF;
bTrashRackCleanerStart := bCleanerActive;

(* Fish Ladder Environmental Flow *)
IF bFishLadderFlowReq THEN
    rFishLadderValvePos := 45.0; (* 45% opening for required flow *)
ELSE
    rFishLadderValvePos := 10.0; (* Minimum maintenance flow *)
END_IF;

(* Main Turbine Control State Machine *)
CASE iState OF
    0: (* Standby *)
        rWicketGatePosCmd := 0.0;
        rKaplanBladePosCmd := 0.0;
        IF bStartCommand AND rGrossHead > HEAD_MIN THEN
            iState := 10;
        END_IF;

    10: (* Startup & Sync *)
        rWicketGatePosCmd := 15.0; (* Breakaway opening *)
        rKaplanBladePosCmd := 10.0; (* Startup pitch *)
        IF rGridFrequency > 49.9 AND rGridFrequency < 50.1 THEN
            iState := 20; (* Assuming external sync breaker closed *)
        END_IF;

    20: (* Power Production - 3D Cam Mapping *)
        (* Simplified PID simulation for power *)
        rSpeedControlOut := rActivePowerSetp * 1.2; 
        rWicketGatePosCmd := LIMIT(0.0, rSpeedControlOut, 100.0);

        (* 3D Cam mapping: Blade pitch = f(Wicket Gate, Net Head) *)
        (* Simplified polynomial representation for the 3D surface *)
        rOptBladeAngle := (rWicketGatePosCmd * 0.8) + (rNetHead * 1.5) - 10.0;
        rKaplanBladePosCmd := LIMIT(0.0, rOptBladeAngle, 100.0);

        IF bStopCommand OR rGrossHead < HEAD_MIN THEN
            iState := 30;
        END_IF;

    30: (* Shutdown sequence *)
        rWicketGatePosCmd := rWicketGatePosCmd - 0.5;
        rKaplanBladePosCmd := rKaplanBladePosCmd - 0.5;
        IF rWicketGatePosCmd <= 0.0 THEN
            iState := 0;
        END_IF;
END_CASE;

(* Protection *)
IF rGrossHead < 1.0 OR rTrashRackDiff > (TRASH_RACK_MAX_DIFF * 2.0) THEN
    bSystemAlarm := TRUE;
    iState := 30; (* Emergency shutdown *)
ELSE
    bSystemAlarm := FALSE;
END_IF;

END_FUNCTION_BLOCK
