//=============================================================================
// BLOCK: FB_Coronagraph_SpeckleNulling
// DESCRIPTION: Extreme Adaptive Optics (ExAO) Controller for Space Telescope
//              Creates a deep contrast "dark hole" via Electric Field Conjugation (EFC)
//              utilizing a 2,048-actuator Deformable Mirror (DM) to suppress starlight
//              by 1E10 for direct exoplanet imaging.
// STANDARDS: IEC 61131-3, PackML State Machine
//=============================================================================

TYPE E_PackML_State :
(
    ST_STOPPED := 0,
    ST_STARTING := 1,
    ST_IDLE := 2,
    ST_EXECUTE := 3,
    ST_HOLDING := 4,
    ST_HELD := 5,
    ST_UNHOLDING := 6,
    ST_SUSPENDING := 7,
    ST_SUSPENDED := 8,
    ST_UNSUSPENDING := 9,
    ST_ABORTING := 10,
    ST_ABORTED := 11,
    ST_COMPLETING := 12,
    ST_COMPLETE := 13
);
END_TYPE

TYPE ST_FocalPlane_EField :
STRUCT
    RealPart : ARRAY[1..1024] OF LREAL; // Re(E) in the dark hole region
    ImagPart : ARRAY[1..1024] OF LREAL; // Im(E) in the dark hole region
    Intensity : ARRAY[1..1024] OF LREAL; // E*E* (Contrast)
    AverageContrast : LREAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_Coronagraph_SpeckleNulling
VAR_INPUT
    bEnable          : BOOL;  // Hardware enable
    bStart           : BOOL;  // Start speckle nulling iteration
    bAbort           : BOOL;  // Emergency stop
    bHold            : BOOL;  // Pause iterations

    // Telemetry from Focal Plane Wavefront Sensor (FPWFS)
    stEField         : ST_FocalPlane_EField;

    // Target contrast limit
    lrTargetContrast : LREAL := 1.0E-10; 

    // EFC Loop Gain
    lrLoopGain       : LREAL := 0.5;
END_VAR

VAR_OUTPUT
    eState           : E_PackML_State := E_PackML_State.ST_IDLE;
    bDM_UpdateReady  : BOOL := FALSE; // High when DM commands are computed
    lrCurrentContrast: LREAL;
    bTargetReached   : BOOL := FALSE;
    bError           : BOOL := FALSE;
    nErrorID         : UDINT := 0;
END_VAR

VAR
    // Deformable Mirror (DM) Command Voltages/Strokes
    // 2048 actuators for high-order wavefront correction
    aDM_Commands     : ARRAY[1..2048] OF LREAL;
    aDM_Voltages     : ARRAY[1..2048] OF LREAL;

    // Pseudo-Inverse Jacobian (Control Matrix) - G_inv
    // Maps focal plane E-field pixels (1024) to DM Actuators (2048). 
    // Stored as flattened array for performance, Re and Im separated.
    aG_Inv_Real      : ARRAY[1..2097152] OF LREAL; // 2048 * 1024
    aG_Inv_Imag      : ARRAY[1..2097152] OF LREAL; // 2048 * 1024

    // Internal state variables
    nIterationCount  : UDINT := 0;
    i, j, nIndex     : DINT;
    lrStrokeDelta    : LREAL;

    // Stroke limits (nanometers)
    lrMaxStroke_nm   : LREAL := 400.0;
    lrMinStroke_nm   : LREAL := -400.0;

    // Gain scheduled EFC parameters
    lrRegularization : LREAL := 1.0E-3;
END_VAR

//=============================================================================
// METHOD: InitializeControlMatrix
// DESCRIPTION: Loads the pre-computed pseudo-inverse Jacobian from non-volatile
//              memory or generated calibration data.
//=============================================================================
METHOD InitializeControlMatrix : BOOL
VAR
    k: DINT;
END_VAR
    // In a real application, this reads from an ADS memory stream or file.
    // Here we simulate the initialization.
    FOR k := 1 TO 2097152 DO
        aG_Inv_Real[k] := 1.0E-6; // Nominal small mapping
        aG_Inv_Imag[k] := 1.0E-6;
    END_FOR
    InitializeControlMatrix := TRUE;
END_METHOD

//=============================================================================
// STATE MACHINE IMPLEMENTATION
//=============================================================================
IF bAbort THEN
    eState := E_PackML_State.ST_ABORTING;
END_IF

CASE eState OF

    E_PackML_State.ST_STOPPED:
        IF bEnable THEN
            eState := E_PackML_State.ST_STARTING;
        END_IF

    E_PackML_State.ST_STARTING:
        bError := FALSE;
        nErrorID := 0;
        bTargetReached := FALSE;
        nIterationCount := 0;

        // Zero out DM commands
        FOR i := 1 TO 2048 DO
            aDM_Commands[i] := 0.0;
            aDM_Voltages[i] := 0.0;
        END_FOR

        IF InitializeControlMatrix() THEN
            eState := E_PackML_State.ST_IDLE;
        ELSE
            eState := E_PackML_State.ST_ABORTING;
            nErrorID := 1001; // Calibration Load Error
        END_IF

    E_PackML_State.ST_IDLE:
        bDM_UpdateReady := FALSE;
        IF bStart THEN
            eState := E_PackML_State.ST_EXECUTE;
        END_IF

    E_PackML_State.ST_EXECUTE:
        IF bHold THEN
            eState := E_PackML_State.ST_HOLDING;
        ELSIF bStart THEN
            // Calculate Current Contrast
            lrCurrentContrast := 0.0;
            FOR i := 1 TO 1024 DO
                stEField.Intensity[i] := (stEField.RealPart[i] * stEField.RealPart[i]) + 
                                         (stEField.ImagPart[i] * stEField.ImagPart[i]);
                lrCurrentContrast := lrCurrentContrast + stEField.Intensity[i];
            END_FOR
            lrCurrentContrast := lrCurrentContrast / 1024.0;

            IF lrCurrentContrast <= lrTargetContrast THEN
                bTargetReached := TRUE;
                eState := E_PackML_State.ST_COMPLETING;
            ELSE
                // Electric Field Conjugation (EFC) algorithm
                // Delta_U = -Gain * (G_inv * E_field)
                // Matrix vector multiplication: [2048 x 1024] * [1024 x 1]
                FOR i := 1 TO 2048 DO
                    lrStrokeDelta := 0.0;
                    FOR j := 1 TO 1024 DO
                        nIndex := ((i - 1) * 1024) + j;
                        // Complex multiplication: (a+bi)(c+di) = (ac - bd) + (ad + bc)i
                        // EFC focuses on minimizing Re and Im components.
                        lrStrokeDelta := lrStrokeDelta + 
                                         (aG_Inv_Real[nIndex] * stEField.RealPart[j]) + 
                                         (aG_Inv_Imag[nIndex] * stEField.ImagPart[j]);
                    END_FOR

                    // Apply loop gain and update command
                    aDM_Commands[i] := aDM_Commands[i] - (lrLoopGain * lrStrokeDelta);

                    // Safety Clamping (Prevent DM Actuator Snap-in)
                    IF aDM_Commands[i] > lrMaxStroke_nm THEN
                        aDM_Commands[i] := lrMaxStroke_nm;
                    ELSIF aDM_Commands[i] < lrMinStroke_nm THEN
                        aDM_Commands[i] := lrMinStroke_nm;
                    END_IF

                    // Convert stroke (nm) to voltage (V) using quadratic response curve
                    // V = sqrt(Stroke / K), where K is a calibrated constant (e.g., 0.1 nm/V^2)
                    IF aDM_Commands[i] >= 0.0 THEN
                        aDM_Voltages[i] := SQRT(aDM_Commands[i] / 0.1);
                    ELSE
                        aDM_Voltages[i] := 0.0; // Unipolar driver assumption
                    END_IF
                END_FOR

                nIterationCount := nIterationCount + 1;
                bDM_UpdateReady := TRUE;

                // Adaptive Gain Scheduling (reduce gain as contrast deepens)
                IF lrCurrentContrast < 1.0E-8 THEN
                    lrLoopGain := 0.1;
                END_IF
            END_IF
        END_IF

    E_PackML_State.ST_HOLDING:
        eState := E_PackML_State.ST_HELD;

    E_PackML_State.ST_HELD:
        IF NOT bHold THEN
            eState := E_PackML_State.ST_UNHOLDING;
        END_IF

    E_PackML_State.ST_UNHOLDING:
        eState := E_PackML_State.ST_EXECUTE;

    E_PackML_State.ST_ABORTING:
        // Safely flat out the DM to prevent stress
        FOR i := 1 TO 2048 DO
            aDM_Commands[i] := 0.0;
            aDM_Voltages[i] := 0.0;
        END_FOR
        bDM_UpdateReady := TRUE;
        bError := TRUE;
        eState := E_PackML_State.ST_ABORTED;

    E_PackML_State.ST_ABORTED:
        IF NOT bAbort THEN
            eState := E_PackML_State.ST_STOPPED;
        END_IF

    E_PackML_State.ST_COMPLETING:
        bDM_UpdateReady := FALSE;
        eState := E_PackML_State.ST_COMPLETE;

    E_PackML_State.ST_COMPLETE:
        IF NOT bStart THEN
            eState := E_PackML_State.ST_IDLE;
        END_IF

END_CASE
END_FUNCTION_BLOCK
