// Siemens SCL - Rollercoaster Block Zone Safety System
// Features: Block zone interlocks, friction brake modulation, anti-rollback

FUNCTION_BLOCK FB_BlockZoneSafety
TITLE = 'Rollercoaster Block Zone Safety System'
VERSION : '1.0'

VAR_INPUT
    Zone1_Occupied : BOOL; // Train present in Zone 1
    Zone2_Occupied : BOOL; // Train present in Zone 2
    TrainSpeed : REAL; // Current train speed in m/s
    TrainDirection : INT; // 1 = Forward, -1 = Backward
    E_Stop : BOOL; // Emergency stop active (Active Low)
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL; // Brake pressure 0.0 - 100.0%
    AntiRollbackDeploy : BOOL; // Deploy anti-rollback dogs
    AllowProceedToZone2 : BOOL; // Interlock to allow train into Zone 2
    Zone1_Clear : BOOL; // Zone 1 is clear
    SystemFault : BOOL; // General fault indicator
END_VAR

VAR
    BrakeIntegral : REAL := 0.0;
    TargetSpeed : REAL := 5.0; // Target speed in brake zone
END_VAR

BEGIN
    // Emergency Stop Logic
    IF NOT E_Stop THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        RETURN;
    END_IF;

    // Zone Clearance Interlock
    Zone1_Clear := NOT Zone1_Occupied;

    // Train is allowed to proceed to Zone 2 ONLY if Zone 2 is unoccupied
    IF Zone1_Occupied AND NOT Zone2_Occupied THEN
        AllowProceedToZone2 := TRUE;
    ELSE
        AllowProceedToZone2 := FALSE;
    END_IF;

    // Friction Brake Modulation (Proportional Control)
    IF Zone1_Occupied AND NOT AllowProceedToZone2 THEN
        // Must stop train
        FrictionBrakeLevel := 100.0;
    ELSIF Zone1_Occupied AND AllowProceedToZone2 THEN
        // Modulate speed
        IF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 10.0; // P-Gain 10.0
            IF FrictionBrakeLevel > 100.0 THEN
                FrictionBrakeLevel := 100.0;
            END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback Logic
    // If train moves backward, immediately deploy anti-rollback
    IF TrainDirection = -1 AND TrainSpeed > 0.1 THEN
        AntiRollbackDeploy := TRUE;
    ELSE
        AntiRollbackDeploy := FALSE;
    END_IF;

    SystemFault := FALSE;

END_FUNCTION_BLOCK
