  Target Standard: IEC 61131-3 Structured Text

  Description:
  Master-tier controller managing sub-nanosecond clock synchronization (White Rabbit PTP)
  across 500km microwave/laser mesh networks. Implements ultra-fast Layer 1 failover 
  between 70 GHz E-band microwave and 1550 nm laser FSO based on real-time atmospheric 
  attenuation models (BER/RSSI). Integrates GPS/GNSS DO holdover with Rubidium atomic 
  clock fallbacks for nanosecond-grade timing during total signal loss.

  Compliance: PackML (ISA-TR88.00.02)
==========================================================================================
*)

TYPE E_PackML_State : 
(
    IDLE := 0,
    STARTING := 1,
    EXECUTE := 2,
    HOLDING := 3,
    HELD := 4,
    UNHOLDING := 5,
    SUSPENDING := 6,
    SUSPENDED := 7,
    UNSUSPENDING := 8,
    STOPPING := 9,
    STOPPED := 10,
    ABORTING := 11,
    ABORTED := 12,
    CLEARING := 13
);
END_TYPE

TYPE E_Link_Type : 
(
    LINK_NONE := 0,
    LINK_LASER_1550NM := 1,
    LINK_MICROWAVE_70GHZ := 2,
    LINK_FIBER_BACKUP := 3
);
END_TYPE

TYPE E_Clock_Source : 
(
    CLK_WR_PTP := 0,    (* White Rabbit PTP *)
    CLK_GPS_GNSS := 1,  (* GPS/GNSS DO *)
    CLK_RUBIDIUM := 2   (* Local Rubidium Atomic Clock Holdover *)
);
END_TYPE

TYPE ST_Link_Telemetry :
STRUCT
    RSSI_dBm             : LREAL;  (* Received Signal Strength Indicator *)
    BER                  : LREAL;  (* Bit Error Rate (e.g., 1E-12) *)
    Latency_ps           : LREAL;  (* Link latency in picoseconds *)
    Atmospheric_Atten_dB : LREAL;  (* Calculated atmospheric attenuation *)
    Is_Active            : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_HFT_MicrowaveMesh
VAR_INPUT
    bEnable              : BOOL;   (* Enable block *)
    bReset               : BOOL;   (* Reset faults/alarms *)

    (* Laser Link Telemetry (1550nm FSO) *)
    stLaserTelemetry     : ST_Link_Telemetry;

    (* Microwave Link Telemetry (70GHz E-band) *)
    stMicrowaveTelemetry : ST_Link_Telemetry;

    (* Timing & Synchronization *)
    fWRPTP_Offset_ps     : LREAL;  (* White Rabbit PTP measured offset *)
    bGPS_Lock            : BOOL;   (* GPS/GNSS fix status *)
    bRubidium_Stable     : BOOL;   (* Rubidium oscillator stability flag *)

    (* Environmental Data (for attenuation prediction) *)
    fRainIntensity_mm_h  : LREAL;  (* Rain rate *)
    fVisibility_km       : LREAL;  (* Fog/Visibility *)
END_VAR

VAR_OUTPUT
    ePackMLState         : E_PackML_State := E_PackML_State.IDLE;

    (* Active Path & Clock *)
    eActiveLink          : E_Link_Type;
    eActiveClock         : E_Clock_Source;

    (* Control Signals *)
    bSwitchToMicrowave   : BOOL;
    bSwitchToLaser       : BOOL;
    bSwitchToFiber       : BOOL;   (* Ultimate fallback *)

    (* Performance Metrics *)
    fCurrentLatency_ps   : LREAL;
    fClockSkew_ps        : LREAL;

    (* Status & Alarms *)
    bLinkDegraded        : BOOL;
    bHoldoverActive      : BOOL;
    bError               : BOOL;
    nErrorID             : DWORD;
END_VAR

VAR
    (* Internal Thresholds *)
    c_fLaser_BER_Limit   : LREAL := 1.0E-6;   (* FSO Laser BER failover threshold *)
    c_fMW_BER_Limit      : LREAL := 1.0E-4;   (* Microwave BER failover threshold *)
    c_fLaser_RSSI_Min    : LREAL := -28.0;    (* Minimum FSO RSSI in dBm *)
    c_fMW_RSSI_Min       : LREAL := -65.0;    (* Minimum MW RSSI in dBm *)
    c_fPTP_SkewLimit_ps  : LREAL := 100.0;    (* Maximum allowed skew (100ps) *)

    (* State Machine *)
    nFailoverDebounce    : INT := 0;
    c_nDebounceLimit     : INT := 3;          (* Microcycles to confirm link loss *)

    (* Internal Calculated *)
    fPredictedAttenuation: LREAL;
END_VAR

(* ========================================================================= *)
(*                        MAIN ALGORITHM EXECUTION                           *)
(* ========================================================================= *)

(* PackML State Machine Evaluation *)
CASE ePackMLState OF

    E_PackML_State.IDLE:
        IF bEnable THEN
            ePackMLState := E_PackML_State.STARTING;
        END_IF;

    E_PackML_State.STARTING:
        (* Initialize outputs and clear alarms *)
        bError := FALSE;
        nErrorID := 0;
        eActiveLink := E_Link_Type.LINK_LASER_1550NM; (* Prefer Laser for bandwidth *)
        eActiveClock := E_Clock_Source.CLK_WR_PTP;
        ePackMLState := E_PackML_State.EXECUTE;

    E_PackML_State.EXECUTE:
        IF NOT bEnable THEN
            ePackMLState := E_PackML_State.STOPPING;
        ELSIF bError THEN
            ePackMLState := E_PackML_State.ABORTING;
        ELSE
            (* 1. Atmospheric Attenuation Prediction Algorithm *)
            (* Predicts signal degradation based on rain fade (MW) and fog (Laser) *)
            fPredictedAttenuation := (fRainIntensity_mm_h * 0.45) + (1.2 / MAX(fVisibility_km, 0.01));

            (* 2. Link Layer 1 Failover Logic *)
            (* Check FSO Laser Health (Primary High-Bandwidth) *)
            IF (stLaserTelemetry.BER > c_fLaser_BER_Limit) OR (stLaserTelemetry.RSSI_dBm < c_fLaser_RSSI_Min) THEN
                (* Laser link degrading, check Microwave (Primary Low-Latency) *)
                IF (stMicrowaveTelemetry.BER <= c_fMW_BER_Limit) AND (stMicrowaveTelemetry.RSSI_dBm >= c_fMW_RSSI_Min) THEN
                    nFailoverDebounce := nFailoverDebounce + 1;
                    IF nFailoverDebounce >= c_nDebounceLimit THEN
                        eActiveLink := E_Link_Type.LINK_MICROWAVE_70GHZ;
                        bSwitchToMicrowave := TRUE;
                        bSwitchToLaser := FALSE;
                        bSwitchToFiber := FALSE;
                        bLinkDegraded := TRUE;
                    END_IF;
                ELSE
                    (* Both MW and Laser dead - failover to terrestrial fiber *)
                    eActiveLink := E_Link_Type.LINK_FIBER_BACKUP;
                    bSwitchToFiber := TRUE;
                    bSwitchToLaser := FALSE;
                    bSwitchToMicrowave := FALSE;
                    bLinkDegraded := TRUE;
                END_IF;
            ELSE
                (* Laser link is healthy *)
                nFailoverDebounce := 0;
                eActiveLink := E_Link_Type.LINK_LASER_1550NM;
                bSwitchToLaser := TRUE;
                bSwitchToMicrowave := FALSE;
                bSwitchToFiber := FALSE;
                bLinkDegraded := FALSE;
            END_IF;

            (* 3. Clock Synchronization & Holdover Logic *)
            (* Monitor White Rabbit PTP Skew *)
            fClockSkew_ps := ABS(fWRPTP_Offset_ps);

            IF fClockSkew_ps > c_fPTP_SkewLimit_ps OR NOT (stLaserTelemetry.Is_Active OR stMicrowaveTelemetry.Is_Active) THEN
                (* PTP is compromised or network link is down. Enter Holdover. *)
                bHoldoverActive := TRUE;

                IF bGPS_Lock THEN
                    eActiveClock := E_Clock_Source.CLK_GPS_GNSS;
                ELSIF bRubidium_Stable THEN
                    eActiveClock := E_Clock_Source.CLK_RUBIDIUM;
                ELSE
                    (* Total Timing Failure *)
                    bError := TRUE;
                    nErrorID := 16#F001; (* Error: Clock Synchronization Lost *)
                END_IF;
            ELSE
                bHoldoverActive := FALSE;
                eActiveClock := E_Clock_Source.CLK_WR_PTP;
            END_IF;

            (* Update current latency telemetry based on active link *)
            IF eActiveLink = E_Link_Type.LINK_LASER_1550NM THEN
                fCurrentLatency_ps := stLaserTelemetry.Latency_ps;
            ELSIF eActiveLink = E_Link_Type.LINK_MICROWAVE_70GHZ THEN
                fCurrentLatency_ps := stMicrowaveTelemetry.Latency_ps;
            ELSE
                fCurrentLatency_ps := 1500000.0; (* 1.5us penalty for fiber *)
            END_IF;

        END_IF;

    E_PackML_State.STOPPING:
        (* Safe shutdown sequence *)
        bSwitchToLaser := FALSE;
        bSwitchToMicrowave := FALSE;
        bSwitchToFiber := TRUE; (* Default to fiber on stop for safety *)
        ePackMLState := E_PackML_State.STOPPED;

    E_PackML_State.STOPPED:
        IF bReset THEN
            ePackMLState := E_PackML_State.IDLE;
        END_IF;

    E_PackML_State.ABORTING:
        (* Fault handling *)
        bSwitchToLaser := FALSE;
        bSwitchToMicrowave := FALSE;
        bSwitchToFiber := TRUE;
        eActiveClock := E_Clock_Source.CLK_RUBIDIUM; (* Ultimate timing holdover *)
        ePackMLState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF bReset THEN
            bError := FALSE;
            nErrorID := 0;
            ePackMLState := E_PackML_State.CLEARING;
        END_IF;

    E_PackML_State.CLEARING:
        ePackMLState := E_PackML_State.IDLE;

    ELSE
        ePackMLState := E_PackML_State.IDLE;
END_CASE;

END_FUNCTION_BLOCK
