FUNCTION_BLOCK FB_PerfusionCentrifuge

VAR_INPUT
    bEnableMaster       : BOOL;     (* Main system enable command, HW interlocked *)
    bEmergencyStop      : BOOL;     (* E-Stop safety relay OK signal (NC logic) *)
    rVibrationSensorX   : REAL;     (* Bowl vibration X-axis (mm/s RMS) *)
    rVibrationSensorY   : REAL;     (* Bowl vibration Y-axis (mm/s RMS) *)
    rBowlSpeedFeedback  : REAL;     (* Actual bowl speed (RPM) from encoder *)
    rFeedFlowRate       : REAL;     (* Feed mass flow rate (L/min) *)
    rViabilitySensor    : REAL;     (* Mammalian cell viability index (%) *)
    rShearStressEst     : REAL;     (* Estimated shear stress (Pa) at feed zone *)
END_VAR

VAR_OUTPUT
    bSystemReady        : BOOL;     (* System ready for perfusion sequence *)
    rSpeedSetpointOut   : REAL;     (* Speed command to VFD (RPM) *)
    rFeedPumpControl    : REAL;     (* Feed pump speed command (%) *)
    bResonanceAlarm     : BOOL;     (* Resonance zone avoidance active/fault *)
    bCellKillAlarm      : BOOL;     (* High shear / low viability critical alarm *)
    bCentrifugeFault    : BOOL;     (* General equipment fault (vibration/estop) *)
END_VAR

VAR
    iState              : INT := 0; 
    tRunTimer           : TON;
    tAccelTimer         : TON;
    tResonanceTimer     : TON;

    (* Filtered values *)
    rFiltVibX           : REAL := 0.0;
    rFiltVibY           : REAL := 0.0;

    (* Constants *)
    C_MAX_SPEED         : REAL := 20000.0; (* 20,000 RPM Max *)
    C_RES_ZONE_LOW      : REAL := 4500.0;
    C_RES_ZONE_HIGH     : REAL := 5500.0;
    C_MAX_VIB_ALLOW     : REAL := 4.5;
    C_MIN_VIABILITY     : REAL := 85.0;

    (* Internal State *)
    bResonanceSkip      : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Interlock Processing *)
IF NOT bEmergencyStop THEN
    bSystemReady        := FALSE;
    bCentrifugeFault    := TRUE;
    rSpeedSetpointOut   := 0.0;
    rFeedPumpControl    := 0.0;
    iState              := 99; (* FAULT STATE *)
    RETURN;
END_IF;

(* First-Order Low-Pass Filter for Vibration Sensors to reject electrical noise *)
rFiltVibX := rFiltVibX + 0.1 * (rVibrationSensorX - rFiltVibX);
rFiltVibY := rFiltVibY + 0.1 * (rVibrationSensorY - rFiltVibY);

(* High Vibration Fault *)
IF (rFiltVibX > C_MAX_VIB_ALLOW) OR (rFiltVibY > C_MAX_VIB_ALLOW) THEN
    bCentrifugeFault := TRUE;
    rSpeedSetpointOut := 0.0;
    iState := 99;
    RETURN;
END_IF;

(* Mammalian Cell Viability Protection Logic *)
IF rViabilitySensor < C_MIN_VIABILITY THEN
    bCellKillAlarm := TRUE;
    (* Automatically throttle feed to reduce shear *)
    rFeedPumpControl := rFeedPumpControl * 0.5;
ELSE
    bCellKillAlarm := FALSE;
END_IF;


(* Main State Machine *)
CASE iState OF
    0: (* IDLE AND CHECK INTERLOCKS *)
        rSpeedSetpointOut := 0.0;
        rFeedPumpControl := 0.0;
        bSystemReady := TRUE;
        bCentrifugeFault := FALSE;
        bResonanceAlarm := FALSE;

        IF bEnableMaster THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* ACCELERATE TO PRE-RESONANCE *)
        rSpeedSetpointOut := C_RES_ZONE_LOW - 100.0;

        (* Wait for speed to settle before jumping resonance *)
        IF rBowlSpeedFeedback > (C_RES_ZONE_LOW - 200.0) THEN
            tAccelTimer(IN := TRUE, PT := T#5S);
            IF tAccelTimer.Q THEN
                tAccelTimer(IN := FALSE);
                iState := 20;
            END_IF;
        END_IF;

    20: (* RESONANCE ZONE SKIP *)
        bResonanceAlarm := TRUE; (* Warning indication *)
        rSpeedSetpointOut := C_RES_ZONE_HIGH + 200.0;

        tResonanceTimer(IN := TRUE, PT := T#15S);

        (* Successfully cleared resonance zone *)
        IF rBowlSpeedFeedback > C_RES_ZONE_HIGH THEN
            bResonanceAlarm := FALSE;
            tResonanceTimer(IN := FALSE);
            iState := 30;
        END_IF;

        (* Failed to clear resonance in time - abort *)
        IF tResonanceTimer.Q THEN
            bCentrifugeFault := TRUE;
            iState := 99;
        END_IF;

    30: (* NORMAL OPERATION (CONTINUOUS PERFUSION) *)
        (* Ramp up to operating speed based on feed requirements, max out at 20000 RPM *)
        rSpeedSetpointOut := 15000.0; (* Nominal setpoint *)
        rFeedPumpControl := 80.0;     (* Nominal 80% feed pump *)

        (* Dynamic shear stress feedback loop - simple proportional rollback *)
        IF rShearStressEst > 100.0 THEN
            rSpeedSetpointOut := rSpeedSetpointOut - (rShearStressEst - 100.0) * 10.0;
        END_IF;

        (* Limit bounds *)
        IF rSpeedSetpointOut > C_MAX_SPEED THEN
            rSpeedSetpointOut := C_MAX_SPEED;
        END_IF;

        IF NOT bEnableMaster THEN
            iState := 40;
        END_IF;

    40: (* DECELERATE *)
        rFeedPumpControl := 0.0;
        rSpeedSetpointOut := 0.0;

        IF rBowlSpeedFeedback < 10.0 THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        rSpeedSetpointOut := 0.0;
        rFeedPumpControl := 0.0;

        (* Require full stop and disable to clear fault *)
        IF NOT bEnableMaster AND (rBowlSpeedFeedback < 5.0) THEN
            iState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
