    rBallastLevel_3 : REAL; // Ballast tank 3 level (%)
    rBallastLevel_4 : REAL; // Ballast tank 4 level (%)
    rGyroRPM_X : REAL; // Gyroscope X RPM
    rGyroRPM_Y : REAL; // Gyroscope Y RPM
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    rBallastPumpCmd_1 : REAL; // Command to ballast pump 1 (-100 to 100%)
    rBallastPumpCmd_2 : REAL; // Command to ballast pump 2 (-100 to 100%)
    rBallastPumpCmd_3 : REAL; // Command to ballast pump 3 (-100 to 100%)
    rBallastPumpCmd_4 : REAL; // Command to ballast pump 4 (-100 to 100%)
    rGyroTorqueCmd_X : REAL; // Gyroscope X torque command (Nm)
    rGyroTorqueCmd_Y : REAL; // Gyroscope Y torque command (Nm)
    rBladePitchCmd : REAL; // Blade pitch command (degrees)
    bHeaveCompActive : BOOL; // Heave compensation active flag
    bAlarmTension : BOOL; // Tendon tension alarm
    bAlarmStability : BOOL; // Platform stability alarm
END_VAR

VAR
    rAvgTension : REAL;
    rMaxTensionDiff : REAL;
    rPitchError : REAL;
    rRollError : REAL;
    rTargetPitch : REAL := 0.0;
    rTargetRoll : REAL := 0.0;

    // PID for Pitch Gyro
    rPitchKp : REAL := 5000.0;
    rPitchKi : REAL := 150.0;
    rPitchKd : REAL := 1200.0;
    rPitchIntegral : REAL := 0.0;
    rPitchPrevError : REAL := 0.0;

    // PID for Roll Gyro
    rRollKp : REAL := 5000.0;
    rRollKi : REAL := 150.0;
    rRollKd : REAL := 1200.0;
    rRollIntegral : REAL := 0.0;
    rRollPrevError : REAL := 0.0;

    // Timers
    tHeaveFilter : TON;
    tStabilizationTimer : TON;

    // Constants
    rMaxTensionLimit : REAL := 15000.0; // kN
    rMinTensionLimit : REAL := 2000.0; // kN
    rMaxPitchLimit : REAL := 5.0; // degrees
    rMaxRollLimit : REAL := 5.0; // degrees
END_VAR

// --- System Initialization ---
IF NOT bEnable THEN
    bSystemReady := FALSE;
    rBallastPumpCmd_1 := 0.0;
    rBallastPumpCmd_2 := 0.0;
    rBallastPumpCmd_3 := 0.0;
    rBallastPumpCmd_4 := 0.0;
    rGyroTorqueCmd_X := 0.0;
    rGyroTorqueCmd_Y := 0.0;
    rBladePitchCmd := 0.0;
    rPitchIntegral := 0.0;
    rRollIntegral := 0.0;
    RETURN;
END_IF;

bSystemReady := TRUE;

// --- 1. Tension Leg Platform (TLP) Active Ballast Trimming ---
rAvgTension := (rTendonTension_A + rTendonTension_B + rTendonTension_C + rTendonTension_D) / 4.0;

// Check for tension alarms
IF (rTendonTension_A > rMaxTensionLimit) OR (rTendonTension_A < rMinTensionLimit) OR
   (rTendonTension_B > rMaxTensionLimit) OR (rTendonTension_B < rMinTensionLimit) OR
   (rTendonTension_C > rMaxTensionLimit) OR (rTendonTension_C < rMinTensionLimit) OR
   (rTendonTension_D > rMaxTensionLimit) OR (rTendonTension_D < rMinTensionLimit) THEN
    bAlarmTension := TRUE;
ELSE
    bAlarmTension := FALSE;
END_IF;

// Ballast adjustment based on tension differential (simplified proportional control)
// Tank 1 and 3 are on pitch axis, Tank 2 and 4 are on roll axis
rBallastPumpCmd_1 := (rTendonTension_A - rAvgTension) * 0.05; 
rBallastPumpCmd_3 := (rTendonTension_C - rAvgTension) * 0.05;
rBallastPumpCmd_2 := (rTendonTension_B - rAvgTension) * 0.05;
rBallastPumpCmd_4 := (rTendonTension_D - rAvgTension) * 0.05;

// Limit ballast pump commands
rBallastPumpCmd_1 := LIMIT(-100.0, rBallastPumpCmd_1, 100.0);
rBallastPumpCmd_2 := LIMIT(-100.0, rBallastPumpCmd_2, 100.0);
rBallastPumpCmd_3 := LIMIT(-100.0, rBallastPumpCmd_3, 100.0);
rBallastPumpCmd_4 := LIMIT(-100.0, rBallastPumpCmd_4, 100.0);


// --- 2. Gyroscopic Nacelle Stabilization ---
rPitchError := rTargetPitch - rNacellePitch;
rRollError := rTargetRoll - rNacelleRoll;

IF ABS(rNacellePitch) > rMaxPitchLimit OR ABS(rNacelleRoll) > rMaxRollLimit THEN
    bAlarmStability := TRUE;
ELSE
    bAlarmStability := FALSE;
END_IF;

// PID for Pitch (Gyro X)
rPitchIntegral := rPitchIntegral + (rPitchError * 0.02); // Assuming 20ms cycle time
rPitchIntegral := LIMIT(-50000.0, rPitchIntegral, 50000.0); // Anti-windup
rGyroTorqueCmd_X := (rPitchKp * rPitchError) + (rPitchKi * rPitchIntegral) + (rPitchKd * (rPitchError - rPitchPrevError) / 0.02);
rPitchPrevError := rPitchError;

// PID for Roll (Gyro Y)
rRollIntegral := rRollIntegral + (rRollError * 0.02); // Assuming 20ms cycle time
rRollIntegral := LIMIT(-50000.0, rRollIntegral, 50000.0); // Anti-windup
rGyroTorqueCmd_Y := (rRollKp * rRollError) + (rRollKi * rRollIntegral) + (rRollKd * (rRollError - rRollPrevError) / 0.02);
rRollPrevError := rRollError;

// Limit gyro torque commands
rGyroTorqueCmd_X := LIMIT(-150000.0, rGyroTorqueCmd_X, 150000.0);
rGyroTorqueCmd_Y := LIMIT(-150000.0, rGyroTorqueCmd_Y, 150000.0);


// --- 3. Wave Heave Load Compensation ---
// Adjust blade pitch based on wave height and period to reduce thrust during crests
IF rWaveHeight > 3.0 AND rWindSpeed > 10.0 THEN
    bHeaveCompActive := TRUE;
    // Feedforward pitch compensation based on wave amplitude
    // Pitch out by up to 5 degrees during large waves
    rBladePitchCmd := (rWaveHeight - 3.0) * 1.5; 
    rBladePitchCmd := LIMIT(0.0, rBladePitchCmd, 15.0);
ELSE
    bHeaveCompActive := FALSE;
    rBladePitchCmd := 0.0;
END_IF;

END_FUNCTION_BLOCK
