FUNCTION_BLOCK fbSolarInverterControl
TITLE = 'Utility-Scale Solar Inverter Farm Control Matrix'
VERSION : '2.4'

VAR_INPUT
    rVdc_meas          : REAL; (* Measured DC link voltage [V] *)
    rIdc_meas          : REAL; (* Measured DC link current [A] *)
    rVgrid_a           : REAL; (* Grid Voltage Phase A [V] *)
    rVgrid_b           : REAL; (* Grid Voltage Phase B [V] *)
    rVgrid_c           : REAL; (* Grid Voltage Phase C [V] *)
    rGrid_Freq_Meas    : REAL; (* Measured Grid Frequency [Hz] *)
    bEnable            : BOOL; (* Enable Inverter Operations *)
    rTemp_IGBT         : REAL; (* Inverter IGBT Temperature [C] *)
    rIrradiance        : REAL; (* Solar Irradiance [W/m2] *)
END_VAR

VAR_OUTPUT
    rPwm_Duty_A        : REAL; (* PWM Duty Cycle Phase A [0.0 - 1.0] *)
    rPwm_Duty_B        : REAL; (* PWM Duty Cycle Phase B [0.0 - 1.0] *)
    rPwm_Duty_C        : REAL; (* PWM Duty Cycle Phase C [0.0 - 1.0] *)
    wInverterState     : WORD; (* Operational State Machine Status *)
    dwFaultCode        : DWORD;(* Active Fault Code Bitmask *)
    rActivePower       : REAL; (* Injected Active Power [kW] *)
    rReactivePower     : REAL; (* Injected Reactive Power [kVAR] *)
END_VAR

VAR
    // MPPT Variables (Perturb and Observe)
    rP_dc              : REAL;
    rP_dc_prev         : REAL := 0.0;
    rV_dc_prev         : REAL := 0.0;
    rV_ref_mppt        : REAL := 1000.0;
    rStepSize          : REAL := 2.5; // Voltage step size [V]

    // Phase Locked Loop (PLL) Variables
    rAlpha             : REAL;
    rBeta              : REAL;
    rV_d               : REAL;
    rV_q               : REAL;
    rTheta             : REAL := 0.0;
    rOmega             : REAL := 314.159; // 50 Hz nominal
    rKp_pll            : REAL := 0.5;
    rKi_pll            : REAL := 10.0;
    rIntegral_pll      : REAL := 0.0;
    rError_pll         : REAL;

    // Anti-Islanding (Active Frequency Drift)
    rAfd_Gain          : REAL := 0.02;
    rFreq_Error        : REAL;
    rNominal_Freq      : REAL := 50.0;

    // Current Control Loop
    rI_d_ref           : REAL;
    rI_q_ref           : REAL := 0.0; // Unity power factor
    rKp_i              : REAL := 1.2;
    rKi_i              : REAL := 25.0;

    // State Machine
    iState             : INT := 0; // 0: Init, 1: Standby, 2: Run, 3: Fault
END_VAR

// ==============================================================================
// UTILITY-SCALE INVERTER CONTROL LOGIC
// ==============================================================================

// 1. Fault Monitoring and State Management
IF rTemp_IGBT > 85.0 THEN
    dwFaultCode := dwFaultCode OR 16#00000001;
END_IF;

IF rVdc_meas > 1500.0 THEN
    dwFaultCode := dwFaultCode OR 16#00000002;
END_IF;

IF dwFaultCode <> 0 THEN
    iState := 3; // Fault
    bEnable := FALSE;
ELSIF NOT bEnable THEN
    iState := 1; // Standby
ELSIF iState = 1 AND bEnable THEN
    iState := 2; // Run
END_IF;

wInverterState := INT_TO_WORD(iState);

IF iState = 2 THEN
    // 2. Maximum Power Point Tracking (MPPT) - Perturb and Observe Algorithm
    rP_dc := rVdc_meas * rIdc_meas;

    IF rP_dc <> rP_dc_prev THEN
        IF rP_dc > rP_dc_prev THEN
            IF rVdc_meas > rV_dc_prev THEN
                rV_ref_mppt := rV_ref_mppt + rStepSize;
            ELSE
                rV_ref_mppt := rV_ref_mppt - rStepSize;
            END_IF;
        ELSE
            IF rVdc_meas > rV_dc_prev THEN
                rV_ref_mppt := rV_ref_mppt - rStepSize;
            ELSE
                rV_ref_mppt := rV_ref_mppt + rStepSize;
            END_IF;
        END_IF;
    END_IF;

    // Limits for MPPT Reference Voltage
    IF rV_ref_mppt > 1400.0 THEN rV_ref_mppt := 1400.0; END_IF;
    IF rV_ref_mppt < 800.0 THEN rV_ref_mppt := 800.0; END_IF;

    rP_dc_prev := rP_dc;
    rV_dc_prev := rVdc_meas;

    // 3. Grid-Following Phase-Locked Loop (PLL)
    // Clarke Transform
    rAlpha := (2.0/3.0) * (rVgrid_a - 0.5*rVgrid_b - 0.5*rVgrid_c);
    rBeta := (2.0/3.0) * (0.8660254*rVgrid_b - 0.8660254*rVgrid_c);

    // Park Transform
    rV_d := rAlpha * COS(rTheta) + rBeta * SIN(rTheta);
    rV_q := -rAlpha * SIN(rTheta) + rBeta * COS(rTheta);

    // PLL PI Controller
    rError_pll := rV_q; // Target V_q = 0
    rIntegral_pll := rIntegral_pll + (rKi_pll * rError_pll * 0.0001);
    rOmega := 314.159 + (rKp_pll * rError_pll) + rIntegral_pll;

    // Anti-Islanding: Active Frequency Drift (AFD)
    rFreq_Error := rGrid_Freq_Meas - rNominal_Freq;
    rOmega := rOmega + (rAfd_Gain * rFreq_Error);

    // Phase Angle Integration
    rTheta := rTheta + (rOmega * 0.0001);
    IF rTheta >= 6.2831853 THEN
        rTheta := rTheta - 6.2831853;
    END_IF;
    IF rTheta < 0.0 THEN
        rTheta := rTheta + 6.2831853;
    END_IF;

    // 4. Inner Current Control Loop
    rI_d_ref := (rVdc_meas - rV_ref_mppt) * 0.5;

    // PWM duty cycles (SPWM logic)
    rPwm_Duty_A := 0.5 + 0.45 * SIN(rTheta);
    rPwm_Duty_B := 0.5 + 0.45 * SIN(rTheta - 2.0943951);
    rPwm_Duty_C := 0.5 + 0.45 * SIN(rTheta + 2.0943951);

    rActivePower := rP_dc / 1000.0;
    rReactivePower := 0.0;
ELSE
    rPwm_Duty_A := 0.0;
    rPwm_Duty_B := 0.0;
    rPwm_Duty_C := 0.0;
    rActivePower := 0.0;
    rReactivePower := 0.0;
END_IF;
END_FUNCTION_BLOCK
