FUNCTION_BLOCK FB_AcousticTelemetryModemArray
VAR_INPUT
    bEnableModem            : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety interlock / hardware OK signal *)
    rAmbientPressure        : REAL;     (* Deep-sea ambient pressure in Bar for depth correction *)
    rWaterTemp              : REAL;     (* Water temperature in deg C for sound speed calculation *)
    rRawAcousticSignal      : REAL;     (* Raw signal voltage from piezoceramic transducer *)
    rPlatformVelocity       : REAL;     (* Platform relative velocity in m/s for Doppler correction *)
    bTransmitReq            : BOOL;     (* Request to transmit data packet *)
    rTargetImpedance        : REAL;     (* Dynamic target impedance for tuning circuit *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Array fully initialized and tuned *)
    rDemodulatedData        : REAL;     (* Recovered telemetry data post-DSP *)
    rTransducerDrive        : REAL;     (* Output drive voltage to transmission amplifier *)
    bImpedanceMatched       : BOOL;     (* True if tuning circuit successfully matched *)
    bError                  : BOOL;     (* Fault state active *)
    iErrorCode              : INT;      (* Diagnostics error code *)
END_VAR
VAR
    iState                  : INT := 0; 
    tInitTimer              : TON;
    tTuningTimer            : TON;
    rCalculatedSoundSpeed   : REAL;     (* Speed of sound in m/s *)
    rDopplerShiftFactor     : REAL;     (* Compensation multiplier *)
    rFilteredSignal         : REAL;     (* Low-pass filtered hydrophone signal *)
    rPreviousSignal         : REAL := 0.0;
    rIntegralError          : REAL := 0.0;
    rImpedanceError         : REAL;
    rCurrentImpedance       : REAL := 50.0; (* Base impedance estimate *)
    iMultipathCount         : INT := 0;
END_VAR

(* === MAIN SAFETY INTERLOCK LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bError := TRUE;
    iErrorCode := 9999; (* Critical Safety Stop *)
    rTransducerDrive := 0.0;
    rDemodulatedData := 0.0;
    RETURN;
END_IF;

(* Evaluate Sound Speed using simplified Medwin formula for deep-sea context *)
rCalculatedSoundSpeed := 1449.2 + 4.6 * rWaterTemp - 0.055 * (rWaterTemp * rWaterTemp) + 0.00029 * (rWaterTemp * rWaterTemp * rWaterTemp) + 0.016 * rAmbientPressure;

(* Doppler shift factor calculation based on relative platform velocity *)
IF rCalculatedSoundSpeed > 0.0 THEN
    rDopplerShiftFactor := 1.0 + (rPlatformVelocity / rCalculatedSoundSpeed);
ELSE
    rDopplerShiftFactor := 1.0;
END_IF;

(* First order IIR Low-pass filter for ambient noise reduction *)
rFilteredSignal := rPreviousSignal + 0.25 * (rRawAcousticSignal - rPreviousSignal);
rPreviousSignal := rFilteredSignal;

(* Multi-path reverberation mitigation approximation *)
IF rFilteredSignal > 0.8 * rPreviousSignal THEN
    iMultipathCount := iMultipathCount + 1;
ELSE
    iMultipathCount := 0;
END_IF;

CASE iState OF
    0: (* IDLE & OFF *)
        bSystemReady := FALSE;
        bError := FALSE;
        iErrorCode := 0;
        bImpedanceMatched := FALSE;
        rTransducerDrive := 0.0;
        IF bEnableModem THEN
            iState := 10;
        END_IF;

    10: (* INITIALIZING SENSORS & TIMERS *)
        tInitTimer(IN := TRUE, PT := T#2S);
        IF tInitTimer.Q THEN
            tInitTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* IMPEDANCE TUNING LOOP *)
        rImpedanceError := rTargetImpedance - rCurrentImpedance;
        rIntegralError := rIntegralError + rImpedanceError * 0.01;
        rCurrentImpedance := rCurrentImpedance + (0.5 * rImpedanceError) + (0.1 * rIntegralError);

        IF ABS(rImpedanceError) < 1.5 THEN
            bImpedanceMatched := TRUE;
            tTuningTimer(IN := TRUE, PT := T#1S);
            IF tTuningTimer.Q THEN
                 tTuningTimer(IN := FALSE);
                 iState := 30;
            END_IF;
        ELSE
            bImpedanceMatched := FALSE;
            tTuningTimer(IN := FALSE);
        END_IF;

        (* Timeout fallback for tuning *)
        IF rCurrentImpedance > 1000.0 OR rCurrentImpedance < 1.0 THEN
            bError := TRUE;
            iErrorCode := 101; (* Tuning failure *)
            iState := 99;
        END_IF;

    30: (* OPERATIONAL - RECEIVE / TRANSMIT *)
        bSystemReady := TRUE;

        (* Handle Demodulation (PSK Simulation) *)
        rDemodulatedData := rFilteredSignal * rDopplerShiftFactor;

        (* Handle Transmission Request *)
        IF bTransmitReq AND NOT bError THEN
            rTransducerDrive := 24.0 * rDopplerShiftFactor; (* Drive voltage adjusted for Doppler spread *)
        ELSE
            rTransducerDrive := 0.0;
        END_IF;

        IF NOT bEnableModem THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rTransducerDrive := 0.0;
        IF NOT bEnableModem THEN
            bError := FALSE;
            iErrorCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
