FUNCTION_BLOCK "HydroTurbine_M4"
VERSION : 0.1
   VAR_INPUT 
      pn_io_in : "Profinet_IO"; 
      scada_in : "SCADA_Data";
      peer_plc_alive : Bool; 
      is_primary : Bool;
      grid_voltage, grid_freq, gen_voltage, gen_freq : Real;
      vib_sensor_1, vib_sensor_2 : Real; // Dual redundant sensors
      speed_setpoint, actual_speed, penstock_pressure : Real;
      hil_sim_mode : Bool; // Hardware-in-the-Loop active
   END_VAR

   VAR_OUTPUT 
      pn_io_out : "Profinet_IO"; 
      scada_out : "SCADA_Data";
      wicket_gate_pos : Real;
      breaker_close_cmd : Bool;
      plc_heartbeat_out : Bool;
   END_VAR

   VAR 
      pid_wicket : "PID_Compact";
      active_control : Bool; 
      turbine_running : Bool;
      sync_ok, alarm_water_hammer, alarm_vibration : Bool;
      sensor_drift_fault : Bool;
      self_test_step : Int;
      self_test_timer : TON;
      vibration_level : Real;
      prev_pressure, roc_pressure : Real; 
      sample_timer : TON;
   END_VAR

BEGIN
    // HIL Digital Twin Sync
    IF #hil_sim_mode THEN
        // In simulation, bypass physical sensor checks or apply model overrides
        #sensor_drift_fault := FALSE;
        #vibration_level := #vib_sensor_1; // Trust primary model input
    ELSE
        // Physical operation: Dual Sensor Drift Detection
        IF ABS(#vib_sensor_1 - #vib_sensor_2) > 1.5 THEN
            #sensor_drift_fault := TRUE;
        ELSE
            #sensor_drift_fault := FALSE;
        END_IF;
        #vibration_level := (#vib_sensor_1 + #vib_sensor_2) / 2.0;
    END_IF;

    // Failover & RBAC 
    #active_control := #is_primary OR NOT #peer_plc_alive;
    VAR 
        has_control_rights : Bool; 
    END_VAR
    has_control_rights := (#scada_in.operator_level >= 1);

    IF #active_control THEN
        // Pre-startup Self-Test Routine
        IF NOT #turbine_running AND #pn_io_in.remote_start AND has_control_rights AND #self_test_step = 0 THEN
            #self_test_step := 1; // Initiate self-test
        END_IF;

        #self_test_timer(IN := (#self_test_step > 0 AND #self_test_step < 10), PT := T#1S);
        IF #self_test_step = 1 AND #self_test_timer.Q THEN
            // Step 1: Check sensors
            IF #sensor_drift_fault THEN #self_test_step := 99; ELSE #self_test_step := 2; END_IF;
        ELSIF #self_test_step = 2 AND #self_test_timer.Q THEN
            // Step 2: Check grid presence
            IF #grid_voltage < 0.8 * 400.0 THEN #self_test_step := 99; ELSE #self_test_step := 10; END_IF;
        END_IF;

        IF #self_test_step = 10 THEN
            #turbine_running := TRUE;
            #self_test_step := 0; // Reset
        ELSIF #self_test_step = 99 THEN
            #pn_io_out.diag_code := 3001; // Self-test failed
            #self_test_step := 0;
        END_IF;

        IF #turbine_running THEN
            #pid_wicket(Setpoint := #speed_setpoint, Input := #actual_speed, Output => #wicket_gate_pos);
        ELSE
            #wicket_gate_pos := 0.0;
        END_IF;

        // Protections
        #alarm_vibration := #vibration_level > 7.0 OR #sensor_drift_fault;
        #sample_timer(IN := NOT #sample_timer.Q, PT := T#100MS);
        IF #sample_timer.Q THEN
            #roc_pressure := (#penstock_pressure - #prev_pressure) / 0.1;
            #prev_pressure := #penstock_pressure;
        END_IF;
        #alarm_water_hammer := (#penstock_pressure > 15.0) OR (#roc_pressure > 5.0);

        IF #alarm_vibration OR #alarm_water_hammer THEN
            #turbine_running := FALSE;
        END_IF;

        #sync_ok := (ABS(#grid_voltage - #gen_voltage) < 5.0) AND (ABS(#grid_freq - #gen_freq) < 0.1);
        #breaker_close_cmd := #turbine_running AND #sync_ok;
    END_IF;
END_FUNCTION_BLOCK
