FUNCTION_BLOCK FB_BioSyntheticSpiderSilkExtrusion
VAR_INPUT
    bEnable                 : BOOL;       (* System enable signal for the entire extrusion train *)
    bEmergencyStop          : BOOL;       (* Safety relay OK signal; MUST be TRUE to operate *)
    rDopeFluidPressure      : REAL;       (* Non-Newtonian dope fluid pressure at spinneret inlet (Bar) *)
    rDopeFluidTemp          : REAL;       (* Dope fluid temperature (Deg C) *)
    rCoagulationBathPH      : REAL;       (* Coagulation bath pH for triggered protein folding *)
    rGodetRollerTension     : REAL;       (* Micro-tension measurement from drafting godet (cN) *)
    rTargetDrawRatio        : REAL;       (* Desired mechanical draw ratio for the fiber *)
    bStartDrafting          : BOOL;       (* Command to initiate multi-stage drafting sequence *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;       (* System ready status; interlocks cleared and parameters in range *)
    rSpinneretPumpSpeed     : REAL;       (* Control signal to dope fluid metering pump (RPM) *)
    rBathAcidDosingRate     : REAL;       (* Control signal to acid dosing pump for pH adjustment (mL/min) *)
    rGodetRollerSpeed       : REAL;       (* Command velocity to Godet roller servo (m/min) *)
    bAlarmDopePressure      : BOOL;       (* High pressure alarm in the dope delivery system *)
    bAlarmBathPH            : BOOL;       (* Alarm indicating coagulation bath pH is out of limits *)
    bAlarm                  : BOOL;       (* General fault alarm output *)
END_VAR
VAR
    iExtrusionState         : INT := 0;   (* State machine variable for extrusion control *)
    tStartupDelay           : TON;        (* Timer for stabilization before extrusion *)
    tDraftingRamp           : TON;        (* Timer for Godet speed ramping *)

    (* Internal setpoints and limits *)
    rMaxSafePressure        : REAL := 150.0;
    rMinSafePressure        : REAL := 20.0;
    rOptimalPH              : REAL := 4.5;
    rPHDeadband             : REAL := 0.2;
    rMaxPumpSpeed           : REAL := 500.0;
    rCurrentGodetSpeed      : REAL := 0.0;

    (* PI Control for Dope Pressure *)
    rPressureError          : REAL;
    rPressureIntegral       : REAL := 0.0;
    rKp_Press               : REAL := 2.5;
    rKi_Press               : REAL := 0.1;

    (* PI Control for Bath pH *)
    rPHError                : REAL;
    rPHIntegral             : REAL := 0.0;
    rKp_PH                  : REAL := -10.0; (* Inverse action: dosing acid lowers pH *)
    rKi_PH                  : REAL := -0.5;
END_VAR

(* === MAIN LOGIC === *)
(* Emergency Stop Interlock Check *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    iExtrusionState := 0;
    rSpinneretPumpSpeed := 0.0;
    rBathAcidDosingRate := 0.0;
    rGodetRollerSpeed := 0.0;
    rCurrentGodetSpeed := 0.0;
    RETURN;
END_IF;

(* Critical Process Alarms *)
bAlarmDopePressure := (rDopeFluidPressure > rMaxSafePressure) OR (rDopeFluidPressure < rMinSafePressure AND iExtrusionState > 10);
bAlarmBathPH := (rCoagulationBathPH > rOptimalPH + 1.0) OR (rCoagulationBathPH < rOptimalPH - 1.0);
bAlarm := bAlarmDopePressure OR bAlarmBathPH;

IF bAlarm THEN
    iExtrusionState := 999; (* Fault state *)
END_IF;

(* Main State Machine *)
CASE iExtrusionState OF
    0: (* IDLE - Waiting for Enable and parameter stabilization *)
        rSpinneretPumpSpeed := 0.0;
        rGodetRollerSpeed := 0.0;
        bSystemReady := FALSE;

        IF bEnable AND NOT bAlarm THEN
            iExtrusionState := 10;
        END_IF;

    10: (* PRE-START / STABILIZATION *)
        (* Regulate bath pH before starting extrusion *)
        rPHError := rOptimalPH - rCoagulationBathPH;
        IF ABS(rPHError) > rPHDeadband THEN
            rPHIntegral := rPHIntegral + (rPHError * 0.1); (* Assuming 100ms cycle *)
            rBathAcidDosingRate := (rKp_PH * rPHError) + (rKi_PH * rPHIntegral);

            IF rBathAcidDosingRate < 0.0 THEN
                rBathAcidDosingRate := 0.0;
            ELSIF rBathAcidDosingRate > 100.0 THEN
                rBathAcidDosingRate := 100.0;
            END_IF;
        ELSE
            rBathAcidDosingRate := 0.0;
        END_IF;

        tStartupDelay(IN := TRUE, PT := T#10S);
        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            bSystemReady := TRUE;
            IF bStartDrafting THEN
                iExtrusionState := 20;
            END_IF;
        END_IF;

    20: (* EXTRUSION & DRAFTING RAMP *)
        (* Non-Newtonian Dope Fluid Pressure Control *)
        rPressureError := 50.0 - rDopeFluidPressure; (* Target pressure 50 Bar *)
        rPressureIntegral := rPressureIntegral + (rPressureError * 0.1);
        rSpinneretPumpSpeed := (rKp_Press * rPressureError) + (rKi_Press * rPressureIntegral);

        IF rSpinneretPumpSpeed > rMaxPumpSpeed THEN
            rSpinneretPumpSpeed := rMaxPumpSpeed;
        ELSIF rSpinneretPumpSpeed < 0.0 THEN
            rSpinneretPumpSpeed := 0.0;
        END_IF;

        (* Ramping Godet Roller Speed for Micro-Tension Drafting *)
        tDraftingRamp(IN := TRUE, PT := T#5S);
        IF tDraftingRamp.Q THEN
            tDraftingRamp(IN := FALSE);
            rCurrentGodetSpeed := rCurrentGodetSpeed + 5.0;
        END_IF;

        (* Target speed calculation based on draw ratio and pump speed *)
        IF rCurrentGodetSpeed >= (rSpinneretPumpSpeed * rTargetDrawRatio * 0.1) THEN
            rCurrentGodetSpeed := (rSpinneretPumpSpeed * rTargetDrawRatio * 0.1);
            iExtrusionState := 30;
        END_IF;

        rGodetRollerSpeed := rCurrentGodetSpeed;

    30: (* STEADY STATE RUNNING *)
        (* Maintain pressure, tension, and pH dynamically *)
        rGodetRollerSpeed := (rSpinneretPumpSpeed * rTargetDrawRatio * 0.1);

        IF NOT bEnable THEN
            iExtrusionState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        rSpinneretPumpSpeed := 0.0;
        rGodetRollerSpeed := 0.0;
        rBathAcidDosingRate := 0.0;
        bSystemReady := FALSE;

        IF NOT bAlarm AND NOT bEnable THEN
            iExtrusionState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
