FUNCTION_BLOCK FB_FuelCellStackAssembly
VAR_INPUT
    bStartAssembly : BOOL; // Start the assembly process
    bEmergencyStop : BOOL; // Emergency stop active low

    // Hydraulic Compression Inputs
    rActualPressure_Bar : REAL; 
    rTargetPressure_Bar : REAL := 150.0;
    rTolerance_Bar : REAL := 2.5;

    // Laser Welding Kinematics
    bLaserReady : BOOL;
    rCurrentPosX_mm : REAL;
    rCurrentPosY_mm : REAL;

    // Mass Spec Leak Testing
    rHeliumConcentration_ppm : REAL;
    bLeakTestComplete : BOOL;

    // General parameters
    tHoldTime : TIME := T#30s;
END_VAR

VAR_OUTPUT
    bAssemblyActive : BOOL;
    bAssemblyComplete : BOOL;
    bError : BOOL;
    iErrorCode : INT; // 1=Stop, 2=Pressure, 3=Laser, 4=Leak

    // Actuators
    bHydraulicPumpRun : BOOL;
    rHydraulicValveCmd_Pct : REAL;

    bLaserEmit : BOOL;
    rTargetPosX_mm : REAL;
    rTargetPosY_mm : REAL;

    bStartLeakTest : BOOL;
END_VAR

VAR
    eState : (IDLE, COMPRESSION_START, COMPRESSION_HOLD, WELDING_INIT, WELDING_ACTIVE, LEAK_TEST_START, LEAK_TEST_ACTIVE, COMPLETE, ERROR_STATE);
    tTimer : TON;
    iWeldStep : INT;
END_VAR

// Control Logic
IF bEmergencyStop THEN
    eState := ERROR_STATE;
    iErrorCode := 1;
END_IF;

CASE eState OF
    IDLE:
        bAssemblyActive := FALSE;
        bAssemblyComplete := FALSE;
        bError := FALSE;
        bHydraulicPumpRun := FALSE;
        rHydraulicValveCmd_Pct := 0.0;
        bLaserEmit := FALSE;
        bStartLeakTest := FALSE;

        IF bStartAssembly THEN
            eState := COMPRESSION_START;
            bAssemblyActive := TRUE;
        END_IF;

    COMPRESSION_START:
        bHydraulicPumpRun := TRUE;
        IF rActualPressure_Bar < rTargetPressure_Bar - rTolerance_Bar THEN
            rHydraulicValveCmd_Pct := 100.0;
        ELSIF rActualPressure_Bar > rTargetPressure_Bar + rTolerance_Bar THEN
            rHydraulicValveCmd_Pct := 0.0;
        ELSE
            rHydraulicValveCmd_Pct := 50.0; // Holding pressure approximate
            eState := COMPRESSION_HOLD;
            tTimer(IN := FALSE); // Reset timer
        END_IF;

    COMPRESSION_HOLD:
        tTimer(IN := TRUE, PT := tHoldTime);
        // Regulate pressure
        IF rActualPressure_Bar < rTargetPressure_Bar THEN
            rHydraulicValveCmd_Pct := 55.0;
        ELSE
            rHydraulicValveCmd_Pct := 45.0;
        END_IF;

        IF tTimer.Q THEN
            eState := WELDING_INIT;
        END_IF;

    WELDING_INIT:
        IF bLaserReady THEN
            iWeldStep := 0;
            eState := WELDING_ACTIVE;
        END_IF;

    WELDING_ACTIVE:
        CASE iWeldStep OF
            0:
                rTargetPosX_mm := 10.0;
                rTargetPosY_mm := 10.0;
                IF (ABS(rCurrentPosX_mm - rTargetPosX_mm) < 0.1) AND (ABS(rCurrentPosY_mm - rTargetPosY_mm) < 0.1) THEN
                    bLaserEmit := TRUE;
                    iWeldStep := 1;
                END_IF;
            1:
                rTargetPosX_mm := 100.0; // Weld line
                IF (ABS(rCurrentPosX_mm - rTargetPosX_mm) < 0.1) THEN
                    bLaserEmit := FALSE;
                    eState := LEAK_TEST_START;
                END_IF;
        END_CASE;

    LEAK_TEST_START:
        bStartLeakTest := TRUE;
        IF NOT bLeakTestComplete THEN
            eState := LEAK_TEST_ACTIVE;
        END_IF;

    LEAK_TEST_ACTIVE:
        IF bLeakTestComplete THEN
            bStartLeakTest := FALSE;
            IF rHeliumConcentration_ppm < 5.0 THEN
                eState := COMPLETE;
            ELSE
                eState := ERROR_STATE;
                iErrorCode := 4; // Leak detected
            END_IF;
        END_IF;

    COMPLETE:
        bAssemblyActive := FALSE;
        bAssemblyComplete := TRUE;
        bHydraulicPumpRun := FALSE;
        rHydraulicValveCmd_Pct := 0.0;

    ERROR_STATE:
        bError := TRUE;
        bAssemblyActive := FALSE;
        bHydraulicPumpRun := FALSE;
        rHydraulicValveCmd_Pct := 0.0;
        bLaserEmit := FALSE;
        bStartLeakTest := FALSE;

END_CASE;
END_FUNCTION_BLOCK
```

