FUNCTION_BLOCK FB_XenonCryoDistillation
VAR_INPUT
    (* Core Process Physical Signals *)
    bSystemEnable           : BOOL;     (* Global process enable interlock from central command *)
    bEmergencyStop_CH1      : BOOL;     (* Safety relay channel 1 - Cryo containment OK *)
    bEmergencyStop_CH2      : BOOL;     (* Safety relay channel 2 - Cryo containment OK *)

    (* Distillation Column Sensors *)
    rColumnTempBottom       : REAL;     (* Boiler temperature, degrees Kelvin [K] *)
    rColumnTempTop          : REAL;     (* Condenser temperature, degrees Kelvin [K] *)
    rColumnPressure         : REAL;     (* Column internal pressure, bar [bar] *)

    (* Spectral Impurity Sensors (Trace Analysis) *)
    rKryptonImpurityPPM     : REAL;     (* Measured Krypton concentration in product stream [ppm] *)
    rArgonImpurityPPM       : REAL;     (* Measured Argon concentration in product stream [ppm] *)

    (* Zero-G Micro-acceleration environment *)
    rMicroGravityZ          : REAL;     (* Z-axis microgravity measurement [m/s^2] *)
    rBoilOffRate            : REAL;     (* Current vapor boil-off rate from storage [kg/h] *)
END_VAR

VAR_OUTPUT
    (* Process Status *)
    bSystemReady            : BOOL;     (* Indicates system is ready for propellant extraction *)
    bDistillationActive     : BOOL;     (* True when fractionation sequence is actively running *)

    (* Actuator Control Signals *)
    rRefluxRatioCmd         : REAL;     (* Calculated dynamic reflux ratio setpoint [0.0 - 10.0] *)
    rHeaterPowerCmd         : REAL;     (* Command to boiler resistive heater [kW] *)
    rCryocoolerDutyCycle    : REAL;     (* Duty cycle for active Stirling cryocooler [0.0 - 100.0 %] *)

    (* Alarm and Safety Interlocks *)
    bCriticalAlarm          : BOOL;     (* Immediate shutdown fault detected *)
    bWarningPurity          : BOOL;     (* Impurity levels approaching max allowable limits *)
END_VAR

VAR
    (* Internal State Machine and Timers *)
    iProcessState           : INT := 0; (* 0: IDLE, 10: PRE_COOL, 20: PURGE, 30: REFLUX_STAB, 40: PRODUCTION, 99: FAULT *)
    tStateTimer             : TON;
    tSafetyDelay            : TON;

    (* Filtering for Noisy Sensors *)
    rFilteredPressure       : REAL;
    rFilteredKrypton        : REAL;

    (* PID Controllers (Conceptual internal variables for tracking) *)
    rErrorPressure          : REAL;
    rIntegralPressure       : REAL;
    rDerivativePressure     : REAL;
    rLastErrorPressure      : REAL;

    (* Constants *)
    c_rTargetPressure       : REAL := 2.55; (* Nominal column pressure [bar] *)
    c_rMaxKryptonPPM        : REAL := 15.0; (* Max allowable Kr limit *)
    c_rMaxArgonPPM          : REAL := 25.0; (* Max allowable Ar limit *)
    c_rKp                   : REAL := 1.25;
    c_rKi                   : REAL := 0.05;
    c_rKd                   : REAL := 0.45;
END_VAR

(* === MAIN LOGIC EXECUTION === *)
(* 1. Safety Interlock Processing *)
IF NOT bEmergencyStop_CH1 OR NOT bEmergencyStop_CH2 THEN
    (* Immediate isolation and vent to safe state *)
    iProcessState := 99;
    bSystemReady := FALSE;
    bDistillationActive := FALSE;
    bCriticalAlarm := TRUE;
    rHeaterPowerCmd := 0.0;
    rCryocoolerDutyCycle := 100.0; (* Max cooling to prevent overpressure boil-off *)
    rRefluxRatioCmd := 10.0;       (* Total reflux, no product draw *)
    RETURN;
END_IF;

(* 2. Sensor Signal Filtering (First-Order Low Pass) *)
(* Time constant ~1s assuming 10ms cycle *)
rFilteredPressure := rFilteredPressure * 0.95 + rColumnPressure * 0.05;
rFilteredKrypton := rFilteredKrypton * 0.98 + rKryptonImpurityPPM * 0.02;

(* 3. Trace Impurity Monitoring *)
IF (rFilteredKrypton > c_rMaxKryptonPPM * 0.8) OR (rArgonImpurityPPM > c_rMaxArgonPPM * 0.8) THEN
    bWarningPurity := TRUE;
ELSE
    bWarningPurity := FALSE;
END_IF;

(* 4. Main Process State Machine *)
CASE iProcessState OF
    0: (* IDLE STATE *)
        bSystemReady := FALSE;
        bDistillationActive := FALSE;
        rHeaterPowerCmd := 0.0;
        rCryocoolerDutyCycle := 0.0;

        IF bSystemEnable THEN
            iProcessState := 10;
        END_IF;

    10: (* PRE-COOLING STATE *)
        bDistillationActive := TRUE;
        rCryocoolerDutyCycle := 85.0; (* Aggressive chilldown phase *)

        IF rColumnTempTop < 165.0 THEN
            (* Condenser reached operational Xenon liquid temperature *)
            iProcessState := 20;
            tStateTimer(IN := FALSE);
        END_IF;

    20: (* PURGE NON-CONDENSABLES *)
        (* Flush lighter elements (He, Ne, trace air from transfers) *)
        tStateTimer(IN := TRUE, PT := T#120S);
        rHeaterPowerCmd := 2.5; 

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iProcessState := 30;
        END_IF;

    30: (* REFLUX STABILIZATION *)
        (* Establish vapor-liquid equilibrium inside the column *)
        rRefluxRatioCmd := 10.0; (* Total reflux *)

        (* PID Pressure Control Update *)
        rErrorPressure := c_rTargetPressure - rFilteredPressure;
        rIntegralPressure := rIntegralPressure + rErrorPressure;
        rDerivativePressure := rErrorPressure - rLastErrorPressure;
        rLastErrorPressure := rErrorPressure;

        rHeaterPowerCmd := (rErrorPressure * c_rKp) + (rIntegralPressure * c_rKi) + (rDerivativePressure * c_rKd);

        (* Limit heater power to physical bounds *)
        IF rHeaterPowerCmd > 15.0 THEN rHeaterPowerCmd := 15.0; END_IF;
        IF rHeaterPowerCmd < 0.0 THEN rHeaterPowerCmd := 0.0; END_IF;

        IF ABS(rErrorPressure) < 0.05 THEN
            iProcessState := 40;
        END_IF;

    40: (* PRODUCTION - XENON PROPELLANT EXTRACTION *)
        bSystemReady := TRUE;

        (* Variable Reflux based on impurity tracking *)
        IF bWarningPurity THEN
            rRefluxRatioCmd := 8.5; (* Increase reflux to push impurities back down the column *)
        ELSE
            rRefluxRatioCmd := 3.0; (* Optimal draw rate for high-grade Deep-Space Xenon *)
        END_IF;

        (* Zero-G Boil-off Reliquefaction loop compensation *)
        IF rMicroGravityZ > 0.01 THEN 
            (* Micro-thruster firing detected, compensate for slosh-induced vaporization *)
            rCryocoolerDutyCycle := rCryocoolerDutyCycle + (rBoilOffRate * 1.5);
        END_IF;

        IF NOT bSystemEnable THEN
            iProcessState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        (* Latch until safe reset *)
        IF NOT bEmergencyStop_CH1 AND NOT bEmergencyStop_CH2 AND NOT bSystemEnable THEN
            bCriticalAlarm := FALSE;
            iProcessState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
