FUNCTION_BLOCK FB_InterstellarSailPropulsion
VAR_INPUT
    (* Physical system inputs from spacecraft telemetry and sensors *)
    bEnable                : BOOL;    (* Main propulsion system enable interlock *)
    bEmergencyStop          : BOOL;    (* Scram signal to abort sequence instantly *)
    rPenningTrapVacuum      : REAL;    (* Vacuum pressure in Penning trap (Torr) *)
    rAntiProtonContainment  : REAL;    (* Magnetic field strength of trap (Tesla) *)
    rUranium238FoilTemp     : REAL;    (* Temperature of the target foil (Kelvin) *)
    rNozzleFieldVectorX     : REAL;    (* X-axis magnetic nozzle vectoring target *)
    rNozzleFieldVectorY     : REAL;    (* Y-axis magnetic nozzle vectoring target *)
    rThrustCommand          : REAL;    (* Commanded thrust level (0.0 to 100.0 %) *)
END_VAR
VAR_OUTPUT
    (* Actuator controls and subsystem statuses *)
    bSystemReady            : BOOL;    (* All subsystems nominal, ready for ignition *)
    rAntiprotonBleedRate    : REAL;    (* Commanded bleed rate from trap (nanograms/sec) *)
    bFoilAblationTrigger    : BOOL;    (* High-speed trigger for U-238 foil ablation *)
    rActiveNozzleFieldX     : REAL;    (* Actual applied X-axis field vector (Tesla) *)
    rActiveNozzleFieldY     : REAL;    (* Actual applied Y-axis field vector (Tesla) *)
    bContainmentAlarm       : BOOL;    (* Critical alarm for magnetic containment loss *)
END_VAR
VAR
    (* Internal state tracking and timers *)
    iState                  : INT := 0; (* State machine index *)
    tAblationTimer          : TON;      (* Micro-timing for ablation synchronization *)
    tBleedRamp              : TON;      (* Ramp timer for antiproton bleed valving *)
    rTargetBleed            : REAL;    (* Calculated target bleed rate *)
    bSafeOperatingEnvelope  : BOOL;    (* Computed safety envelope flag *)
END_VAR

(* === MAIN LOGIC === *)
(* Continuous Safety Monitoring *)
bSafeOperatingEnvelope := (rPenningTrapVacuum < 1.0E-10) AND 
                          (rAntiProtonContainment > 4.5) AND 
                          (rUranium238FoilTemp < 500.0);

IF bEmergencyStop OR NOT bSafeOperatingEnvelope THEN
    bSystemReady := FALSE;
    bFoilAblationTrigger := FALSE;
    rAntiprotonBleedRate := 0.0;
    rActiveNozzleFieldX := 0.0;
    rActiveNozzleFieldY := 0.0;
    bContainmentAlarm := NOT bSafeOperatingEnvelope AND NOT bEmergencyStop;
    iState := 0;
    RETURN;
END_IF;

bContainmentAlarm := FALSE;

(* Main State Machine for Catalyzed Micro-Fission *)
CASE iState OF
    0: (* IDLE & CALIBRATION *)
        bSystemReady := TRUE;
        bFoilAblationTrigger := FALSE;
        rAntiprotonBleedRate := 0.0;
        IF bEnable AND (rThrustCommand > 0.0) THEN
            iState := 10;
            bSystemReady := FALSE;
        END_IF;

    10: (* MAGNETIC NOZZLE VECTORING *)
        (* Ramp up magnetic nozzle fields to target vectors *)
        rActiveNozzleFieldX := rNozzleFieldVectorX;
        rActiveNozzleFieldY := rNozzleFieldVectorY;

        (* Verify field establishment before proceeding *)
        ID (ABS(rActiveNozzleFieldX - rNozzleFieldVectorX) < 0.01) AND 
           (ABS(rActiveNozzleFieldY - rNozzleFieldVectorY) < 0.01) THEN
            iState := 20;
        END_IF;

    20: (* ANTIPROTON BLEED INITIATION *)
        (* Calculate required bleed rate based on thrust command *)
        rTargetBleed := rThrustCommand * 0.05; (* Scale to ng/sec *)

        tBleedRamp(IN := TRUE, PT := T#200MS);
        IF tBleedRamp.Q THEN
            rAntiprotonBleedRate := rTargetBleed;
            tBleedRamp(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* ABLATION SYNCHRONIZATION *)
        (* Trigger U-238 foil ablation exactly when antiprotons arrive *)
        tAblationTimer(IN := TRUE, PT := T#50MS);
        IF tAblationTimer.Q THEN
            bFoilAblationTrigger := TRUE;
            iState := 40;
        END_IF;

    40: (* SUSTAINED THRUST *)
        tAblationTimer(IN := FALSE);
        bFoilAblationTrigger := FALSE; (* Reset trigger for next cycle if needed *)

        (* Adjust bleed dynamically based on command changes *)
        rTargetBleed := rThrustCommand * 0.05;
        rAntiprotonBleedRate := rTargetBleed;

        IF NOT bEnable OR (rThrustCommand <= 0.0) THEN
            iState := 50;
        END_IF;

    50: (* SHUTDOWN SEQUENCE *)
        rAntiprotonBleedRate := 0.0;
        rActiveNozzleFieldX := 0.0;
        rActiveNozzleFieldY := 0.0;
        iState := 0;

END_CAE;

END_FUNCTION_BLOCK
```

