FUNCTION_BLOCK "AmineSweetening_Adversarial"
VAR_INPUT
    Temp_PV : REAL;
    StartupState : BOOL;
    HIL_Sync_Cmd : BOOL;
    HIL_Twin_Value : REAL;
    CycleTime : REAL := 0.1;
END_VAR
VAR_OUTPUT
    ReboilerSteamValve : REAL;
    SelfTestPassed : BOOL;
    DriftAlarm : BOOL;
END_VAR
VAR
    TempHistory : ARRAY[0..99] OF REAL;
    HistoryIndex : INT := 0;
    MovingAverage : REAL;
    SelfTestPhase : INT := 0;
    TempErrSum : REAL := 0.0;
END_VAR
BEGIN
    TempHistory[HistoryIndex] := Temp_PV;
    HistoryIndex := (HistoryIndex + 1) MOD 100;

    MovingAverage := 0.0;
    FOR VAR i := 0 TO 99 DO
        MovingAverage := MovingAverage + TempHistory[i];
    END_FOR;
    MovingAverage := MovingAverage / 100.0;

    DriftAlarm := ABS(Temp_PV - MovingAverage) > 5.0;

    VAR Effective_PV : REAL := Temp_PV;
    IF HIL_Sync_Cmd THEN
        Effective_PV := HIL_Twin_Value;
    END_IF;

    IF StartupState THEN
        CASE SelfTestPhase OF
            0:
                Effective_PV := 999.0;
                SelfTestPhase := 1;
            1:
                IF ReboilerSteamValve = 0.0 THEN
                    SelfTestPassed := TRUE;
                    SelfTestPhase := 2;
                ELSE
                    SelfTestPassed := FALSE;
                END_IF;
        END_CASE;
    END_IF;

    IF DriftAlarm OR (StartupState AND SelfTestPhase < 2) THEN
        ReboilerSteamValve := 0.0;
    ELSE
        VAR TempErr := 120.0 - Effective_PV;
        TempErrSum := TempErrSum + (TempErr * CycleTime);
        ReboilerSteamValve := (2.0 * TempErr) + (0.1 * TempErrSum);
        IF ReboilerSteamValve > 100.0 THEN ReboilerSteamValve := 100.0; ELSIF ReboilerSteamValve < 0.0 THEN ReboilerSteamValve := 0.0; END_IF;
    END_IF;
END_FUNCTION_BLOCK
