FUNCTION_BLOCK FB_MaglevControl
VAR_INPUT
    rAirGapFrontLeft : REAL; (* mm *)
    rAirGapFrontRight : REAL; (* mm *)
    rAirGapRearLeft : REAL; (* mm *)
    rAirGapRearRight : REAL; (* mm *)

    rTargetAirGap : REAL := 10.0; (* mm *)

    rTrainSpeed : REAL; (* m/s *)
    rTargetSpeed : REAL; (* m/s *)

    bEnableLevitation : BOOL;
    bEnablePropulsion : BOOL;

    rTrackPhaseAngle : REAL; (* rad *)

    aFluxSensors : ARRAY[1..4] OF REAL; (* T *)
END_VAR

VAR_OUTPUT
    rCurrentFrontLeft : REAL; (* A *)
    rCurrentFrontRight : REAL; (* A *)
    rCurrentRearLeft : REAL; (* A *)
    rCurrentRearRight : REAL; (* A *)

    rPropulsionCurrentU : REAL; (* A *)
    rPropulsionCurrentV : REAL; (* A *)
    rPropulsionCurrentW : REAL; (* A *)

    bLevitationFault : BOOL;
    bPropulsionFault : BOOL;
END_VAR

VAR
    rKpLevitation : REAL := 150.5;
    rKiLevitation : REAL := 50.2;
    rKdLevitation : REAL := 25.1;

    rErrorFrontLeft, rErrorFrontRight, rErrorRearLeft, rErrorRearRight : REAL;
    rIntegralFrontLeft, rIntegralFrontRight, rIntegralRearLeft, rIntegralRearRight : REAL;
    rPrevErrorFrontLeft, rPrevErrorFrontRight, rPrevErrorRearLeft, rPrevErrorRearRight : REAL;

    rKpPropulsion : REAL := 500.0;
    rKiPropulsion : REAL := 100.0;
    rErrorSpeed : REAL;
    rIntegralSpeed : REAL;
    rForceCommand : REAL;

    rMaxCurrent : REAL := 1000.0;
    rMaxPropulsionCurrent : REAL := 5000.0;

    tCycleTime : REAL := 0.001; (* 1ms cycle *)
    iState : INT := 0;
END_VAR

(* Levitation Control: PID controllers for air gap maintenance *)
IF bEnableLevitation THEN
    (* Front Left *)
    rErrorFrontLeft := rTargetAirGap - rAirGapFrontLeft;
    rIntegralFrontLeft := rIntegralFrontLeft + (rErrorFrontLeft * tCycleTime);
    rCurrentFrontLeft := (rKpLevitation * rErrorFrontLeft) + (rKiLevitation * rIntegralFrontLeft) + (rKdLevitation * (rErrorFrontLeft - rPrevErrorFrontLeft) / tCycleTime);
    rPrevErrorFrontLeft := rErrorFrontLeft;

    (* Front Right *)
    rErrorFrontRight := rTargetAirGap - rAirGapFrontRight;
    rIntegralFrontRight := rIntegralFrontRight + (rErrorFrontRight * tCycleTime);
    rCurrentFrontRight := (rKpLevitation * rErrorFrontRight) + (rKiLevitation * rIntegralFrontRight) + (rKdLevitation * (rErrorFrontRight - rPrevErrorFrontRight) / tCycleTime);
    rPrevErrorFrontRight := rErrorFrontRight;

    (* Rear Left *)
    rErrorRearLeft := rTargetAirGap - rAirGapRearLeft;
    rIntegralRearLeft := rIntegralRearLeft + (rErrorRearLeft * tCycleTime);
    rCurrentRearLeft := (rKpLevitation * rErrorRearLeft) + (rKiLevitation * rIntegralRearLeft) + (rKdLevitation * (rErrorRearLeft - rPrevErrorRearLeft) / tCycleTime);
    rPrevErrorRearLeft := rErrorRearLeft;

    (* Rear Right *)
    rErrorRearRight := rTargetAirGap - rAirGapRearRight;
    rIntegralRearRight := rIntegralRearRight + (rErrorRearRight * tCycleTime);
    rCurrentRearRight := (rKpLevitation * rErrorRearRight) + (rKiLevitation * rIntegralRearRight) + (rKdLevitation * (rErrorRearRight - rPrevErrorRearRight) / tCycleTime);
    rPrevErrorRearRight := rErrorRearRight;

    (* Saturation limits *)
    IF rCurrentFrontLeft > rMaxCurrent THEN rCurrentFrontLeft := rMaxCurrent; ELSIF rCurrentFrontLeft < 0.0 THEN rCurrentFrontLeft := 0.0; END_IF;
    IF rCurrentFrontRight > rMaxCurrent THEN rCurrentFrontRight := rMaxCurrent; ELSIF rCurrentFrontRight < 0.0 THEN rCurrentFrontRight := 0.0; END_IF;
    IF rCurrentRearLeft > rMaxCurrent THEN rCurrentRearLeft := rMaxCurrent; ELSIF rCurrentRearLeft < 0.0 THEN rCurrentRearLeft := 0.0; END_IF;
    IF rCurrentRearRight > rMaxCurrent THEN rCurrentRearRight := rMaxCurrent; ELSIF rCurrentRearRight < 0.0 THEN rCurrentRearRight := 0.0; END_IF;

    (* Fault Detection *)
    bLevitationFault := (rAirGapFrontLeft < 2.0) OR (rAirGapFrontRight < 2.0) OR (rAirGapRearLeft < 2.0) OR (rAirGapRearRight < 2.0);
ELSE
    rCurrentFrontLeft := 0.0;
    rCurrentFrontRight := 0.0;
    rCurrentRearLeft := 0.0;
    rCurrentRearRight := 0.0;
    rIntegralFrontLeft := 0.0;
    rIntegralFrontRight := 0.0;
    rIntegralRearLeft := 0.0;
    rIntegralRearRight := 0.0;
END_IF;

(* Propulsion Control: Linear Synchronous Motor Phasing *)
IF bEnablePropulsion AND NOT bLevitationFault THEN
    rErrorSpeed := rTargetSpeed - rTrainSpeed;
    rIntegralSpeed := rIntegralSpeed + (rErrorSpeed * tCycleTime);
    rForceCommand := (rKpPropulsion * rErrorSpeed) + (rKiPropulsion * rIntegralSpeed);

    (* 3-Phase Commutation using Park/Clarke inverse transform equivalents *)
    (* Simplifying assumption: Direct force command modulated by spatial phase *)
    rPropulsionCurrentU := rForceCommand * SIN(rTrackPhaseAngle);
    rPropulsionCurrentV := rForceCommand * SIN(rTrackPhaseAngle - 2.0943951); (* -120 degrees *)
    rPropulsionCurrentW := rForceCommand * SIN(rTrackPhaseAngle + 2.0943951); (* +120 degrees *)

    (* Saturation limits *)
    IF rPropulsionCurrentU > rMaxPropulsionCurrent THEN rPropulsionCurrentU := rMaxPropulsionCurrent; ELSIF rPropulsionCurrentU < -rMaxPropulsionCurrent THEN rPropulsionCurrentU := -rMaxPropulsionCurrent; END_IF;
    IF rPropulsionCurrentV > rMaxPropulsionCurrent THEN rPropulsionCurrentV := rMaxPropulsionCurrent; ELSIF rPropulsionCurrentV < -rMaxPropulsionCurrent THEN rPropulsionCurrentV := -rMaxPropulsionCurrent; END_IF;
    IF rPropulsionCurrentW > rMaxPropulsionCurrent THEN rPropulsionCurrentW := rMaxPropulsionCurrent; ELSIF rPropulsionCurrentW < -rMaxPropulsionCurrent THEN rPropulsionCurrentW := -rMaxPropulsionCurrent; END_IF;
ELSE
    rPropulsionCurrentU := 0.0;
    rPropulsionCurrentV := 0.0;
    rPropulsionCurrentW := 0.0;
    rIntegralSpeed := 0.0;
END_IF;
END_FUNCTION_BLOCK
