\nFUNCTION_BLOCK FB_SingleUseBioreactor_Control
FUNCTION_BLOCK FB_IndustrialControl
// ==============================================================================
// Function Block: FB_SingleUseBioreactor_Control
// Description: Advanced control of a Single-Use Bioreactor (SUB).
//              Includes disposable DO/pH sensor calibration curves,
//              rocking/agitation shear stress limits, and sterile
//              overlay gas sparging logic.
// ==============================================================================
VAR_INPUT
    bEnable                 : BOOL; // Enable FB
    rRawpH_mV               : REAL; // Raw pH sensor voltage (mV) from disposable sensor
    rRawDO_nA               : REAL; // Raw DO sensor current (nA) from optical disposable patch
    rAgitationSetpt_RPM     : REAL; // Desired agitation speed
    rGasOverlaySetpt_SLPM   : REAL; // Desired overlay gas flow rate
    rVesselVolume_L         : REAL; // Current working volume

    // Calibration parameters for single-use sensors
    st_pHOpticalCalib       : ST_SensorCalibration; // Includes Offset, Slope, TempCoeff
    st_DOOpticalCalib       : ST_SensorCalibration; // Includes Stern-Volmer constants
    rCurrentTemp_C          : REAL; // Media temperature for compensation

    // Process Limits
    rMaxShearStress_Pa      : REAL; // Maximum allowable shear stress for cell line
    rMinOverlayFlow_SLPM    : REAL; // Minimum sterile overlay flow
    rMaxOverlayFlow_SLPM    : REAL; // Maximum sterile overlay flow
END_VAR

VAR_OUTPUT
    rCalibratedpH           : REAL; // Calibrated pH value
    rCalibratedDO_Pct       : REAL; // Calibrated DO (% air sat)
    rAgitationCmd_RPM       : REAL; // Output command to agitation motor
    rGasOverlayCmd_SLPM     : REAL; // Output command to Mass Flow Controller
    bShearStressWarning     : BOOL; // Active if requested RPM exceeds shear limit
    bSensorFault            : BOOL; // Sensor out of bounds
END_VAR

VAR
    // Internal States
    rCalculatedShear_Pa     : REAL;
    rImpellerDiameter_m     : REAL := 0.15; // Specific to SUB bag design
    rFluidDensity_kg_m3     : REAL := 1005.0; // Media density
    rFluidViscosity_Pa_s    : REAL := 0.0011; // Media viscosity
    rPowerNumber            : REAL := 2.1; // Dimensionless power number for impeller

    // State machine
    eState                  : INT := 0; 
END_VAR

// ------------------------------------------------------------------------------
// Implementation
// ------------------------------------------------------------------------------
IF NOT bEnable THEN
    rAgitationCmd_RPM   := 0.0;
    rGasOverlayCmd_SLPM := 0.0;
    bShearStressWarning := FALSE;
    bSensorFault        := FALSE;
    RETURN;
END_IF;

// 1. Disposable Sensor Calibration & Compensation
// pH Calculation: Nernst equation modified for optical patches
// pH = pH0 - (mV - Offset) / (Slope * (T + 273.15))
IF (st_pHOpticalCalib.Slope <> 0.0) THEN
    rCalibratedpH := 7.0 - (rRawpH_mV - st_pHOpticalCalib.Offset) / 
                     (st_pHOpticalCalib.Slope * (1.0 + st_pHOpticalCalib.TempCoeff * (rCurrentTemp_C - 25.0)));
ELSE
    bSensorFault := TRUE;
END_IF;

// DO Calculation: Stern-Volmer formulation for optical luminescence phase shift
// DO% = (1 / kSV) * ((Tau0 / Tau) - 1) 
// Simplified for raw current mapping:
IF (st_DOOpticalCalib.Slope <> 0.0) THEN
    rCalibratedDO_Pct := st_DOOpticalCalib.Offset + (rRawDO_nA * st_DOOpticalCalib.Slope) + 
                         (rCurrentTemp_C * st_DOOpticalCalib.TempCoeff);
    IF rCalibratedDO_Pct < 0.0 THEN rCalibratedDO_Pct := 0.0; END_IF;
    IF rCalibratedDO_Pct > 200.0 THEN rCalibratedDO_Pct := 200.0; END_IF;
ELSE
    bSensorFault := TRUE;
END_IF;

// 2. Agitation Control & Shear Stress Limiting
// Calculate Power input: P = Np * rho * N^3 * D^5
// Average Shear Rate roughly scales with (P/V)^0.5
// Simplified shear stress estimation (Pa)
rCalculatedShear_Pa := 0.0;
IF rVesselVolume_L > 0.0 THEN
    rCalculatedShear_Pa := rFluidViscosity_Pa_s * SQRT((rPowerNumber * rFluidDensity_kg_m3 * EXPT(rAgitationSetpt_RPM / 60.0, 3.0) * EXPT(rImpellerDiameter_m, 5.0)) / (rFluidViscosity_Pa_s * (rVesselVolume_L / 1000.0)));
END_IF;

IF rCalculatedShear_Pa > rMaxShearStress_Pa THEN
    bShearStressWarning := TRUE;
    // Cap the agitation speed to prevent cell damage (back-calculate max RPM)
    // For safety, reduce by 10% from setpoint iteratively or use algebraic cap
    rAgitationCmd_RPM := rAgitationSetpt_RPM * (rMaxShearStress_Pa / rCalculatedShear_Pa); 
ELSE
    bShearStressWarning := FALSE;
    rAgitationCmd_RPM := rAgitationSetpt_RPM;
END_IF;

// 3. Sterile Overlay Gas Sparging
// Ensures headspace sweeping and prevents bag collapse or overpressure
IF rGasOverlaySetpt_SLPM < rMinOverlayFlow_SLPM THEN
    rGasOverlayCmd_SLPM := rMinOverlayFlow_SLPM;
ELSIF rGasOverlaySetpt_SLPM > rMaxOverlayFlow_SLPM THEN
    rGasOverlayCmd_SLPM := rMaxOverlayFlow_SLPM;
ELSE
    rGasOverlayCmd_SLPM := rGasOverlaySetpt_SLPM;
END_IF;

// Integrity Check
IF rRawpH_mV < -500.0 OR rRawpH_mV > 500.0 THEN bSensorFault := TRUE; END_IF;
IF rRawDO_nA < 0.0 OR rRawDO_nA > 1000.0 THEN bSensorFault := TRUE; END_IF;

END_FUNCTION_BLOCK
