FUNCTION_BLOCK FB_SOFC_Plant_MasterControl
TITLE = 'Utility-Scale SOFC Plant Master Control'
VERSION : '1.0'
AUTHOR : 'Lumina AI Cloud Swarm'

VAR_INPUT
    // Physical I/O - Temperatures
    rStackInletTemp : REAL;   // Stack inlet temperature (C)
    rStackOutletTemp : REAL;  // Stack outlet temperature (C)
    rATO_Temperature : REAL;  // Anode Tail-gas Oxidizer temperature (C)
    rReformerTemp : REAL;     // Pre-reformer temperature (C)

    // Physical I/O - Flows
    rSteamFlow_kg_h : REAL;   // Actual steam flow rate (kg/h)
    rNaturalGasFlow_kg_h : REAL; // Actual natural gas flow (kg/h)
    rAirFlow_kg_h : REAL;     // Cathode air flow rate (kg/h)

    // Physical I/O - Pressures
    rDesulfurizationBed1_dP : REAL; // Differential pressure bed 1 (mbar)
    rDesulfurizationBed2_dP : REAL; // Differential pressure bed 2 (mbar)
    rSystemPressure : REAL;         // Main system pressure (bar)

    // Status
    bDesulfurizationBed1_Active : BOOL;
    bEmergencyStop : BOOL;
    bGridLoadRequest : REAL;  // Power demand from grid (MW)
END_VAR

VAR_OUTPUT
    // Valve Commands
    rSteamValveCmd : REAL;    // 0-100%
    rFuelValveCmd : REAL;     // 0-100%
    rAirBlowerCmd : REAL;     // 0-100%

    // Bed Switching
    bSwitchToBed1 : BOOL;
    bSwitchToBed2 : BOOL;

    // ATO Control
    rATO_FuelSupplementCmd : REAL; // 0-100%

    // Alarms
    bCriticalAlarm : BOOL;
    wAlarmWord : WORD;
END_VAR

VAR
    // Internal States
    rSteamToCarbonRatio : REAL;
    rTargetSCRatio : REAL := 2.5; 
    rMinSCRatio : REAL := 2.2;
    rMaxSCRatio : REAL := 3.0;

    // ATO Thermal Tracking
    rATO_TempTarget : REAL := 850.0;
    rKp_ATO : REAL := 2.5;
    rKi_ATO : REAL := 0.15;
    rKd_ATO : REAL := 0.05;
    rATO_Error : REAL;
    rATO_ErrorPrev : REAL;
    rATO_Integral : REAL;
    rATO_Derivative : REAL;

    // Bed Switching Logic
    rMaxBed_dP : REAL := 45.0; // Max allowed dP in mbar
    tBedSwitchDelay : TON;
    bSwitchInProgress : BOOL;

    // Cycle times
    rCycleTime_s : REAL := 0.1; // 100ms task
END_VAR

(* =========================================================================
   Utility-Scale SOFC Control Algorithm
   ========================================================================= *)

// 1. Emergency Handling
IF bEmergencyStop THEN
    rSteamValveCmd := 100.0; // Purge with steam
    rFuelValveCmd := 0.0;
    rAirBlowerCmd := 50.0;   // Maintain some cooling
    rATO_FuelSupplementCmd := 0.0;
    bCriticalAlarm := TRUE;
    wAlarmWord := wAlarmWord OR 16#0001; // Set emergency bit
    RETURN;
END_IF;

// 2. Steam-to-Carbon Ratio Profiling
// The S/C ratio must be strictly maintained to prevent carbon deposition (coking)
IF rNaturalGasFlow_kg_h > 1.0 THEN
    // Approximation: 1 kg NG ~ roughly 0.75 kg Carbon, requires scaling
    // For simplicity, using mass flow ratio scaled by molar masses
    rSteamToCarbonRatio := (rSteamFlow_kg_h / 18.0) / (rNaturalGasFlow_kg_h / 16.0);
ELSE
    rSteamToCarbonRatio := rTargetSCRatio;
END_IF;

// Feed-forward + feedback control for Steam Valve
IF rSteamToCarbonRatio < rMinSCRatio THEN
    wAlarmWord := wAlarmWord OR 16#0002; // S/C ratio too low
    rSteamValveCmd := rSteamValveCmd + 5.0; // Aggressive recovery
ELSIF rSteamToCarbonRatio < rTargetSCRatio THEN
    rSteamValveCmd := rSteamValveCmd + 0.5;
ELSIF rSteamToCarbonRatio > rMaxSCRatio THEN
    rSteamValveCmd := rSteamValveCmd - 0.5;
END_IF;

// Bound the steam valve command
IF rSteamValveCmd > 100.0 THEN rSteamValveCmd := 100.0; END_IF;
IF rSteamValveCmd < 0.0 THEN rSteamValveCmd := 0.0; END_IF;

// 3. Anode Tail-gas Oxidation (ATO) Thermal Tracking
// PID Controller to maintain ATO temperature for optimal thermal integration
rATO_Error := rATO_TempTarget - rATO_Temperature;
rATO_Integral := rATO_Integral + (rATO_Error * rCycleTime_s);
rATO_Derivative := (rATO_Error - rATO_ErrorPrev) / rCycleTime_s;
rATO_ErrorPrev := rATO_Error;

// Anti-windup
IF rATO_Integral > 500.0 THEN rATO_Integral := 500.0; END_IF;
IF rATO_Integral < -500.0 THEN rATO_Integral := -500.0; END_IF;

rATO_FuelSupplementCmd := (rKp_ATO * rATO_Error) + (rKi_ATO * rATO_Integral) + (rKd_ATO * rATO_Derivative);

// Bound ATO command
IF rATO_FuelSupplementCmd > 100.0 THEN rATO_FuelSupplementCmd := 100.0; END_IF;
IF rATO_FuelSupplementCmd < 0.0 THEN rATO_FuelSupplementCmd := 0.0; END_IF;

// 4. Desulfurization Bed Switching Logic
// Continuous monitoring of bed health via pressure drop
IF NOT bSwitchInProgress THEN
    IF bDesulfurizationBed1_Active THEN
        IF rDesulfurizationBed1_dP > rMaxBed_dP THEN
            bSwitchToBed2 := TRUE;
            bSwitchToBed1 := FALSE;
            bSwitchInProgress := TRUE;
        END_IF;
    ELSE
        IF rDesulfurizationBed2_dP > rMaxBed_dP THEN
            bSwitchToBed1 := TRUE;
            bSwitchToBed2 := FALSE;
            bSwitchInProgress := TRUE;
        END_IF;
    END_IF;
END_IF;

// Timer to reset switch-in-progress lock
tBedSwitchDelay(IN := bSwitchInProgress, PT := T#30s);
IF tBedSwitchDelay.Q THEN
    bSwitchInProgress := FALSE;
    bSwitchToBed1 := FALSE;
    bSwitchToBed2 := FALSE;
END_IF;

// 5. System Health & Critical Alarms
IF rDesulfurizationBed1_dP > (rMaxBed_dP * 1.5) OR rDesulfurizationBed2_dP > (rMaxBed_dP * 1.5) THEN
    bCriticalAlarm := TRUE;
    wAlarmWord := wAlarmWord OR 16#0004; // Bed blockage
END_IF;

IF rStackInletTemp > 800.0 THEN
    bCriticalAlarm := TRUE;
    wAlarmWord := wAlarmWord OR 16#0008; // Stack over-temp
END_IF;

END_FUNCTION_BLOCK
