(*
================================================================================
FB_CryoEM_Vitrification
--------------------------------------------------------------------------------
Description:
Master-tier controller for Cryogenic Electron Microscopy (Cryo-EM) Plunge 
Vitrification and Robotic Grid Transfer (Autoloader) operations.
Ensures amorphous vitreous ice formation via rapid plunge freezing in liquid 
ethane and frost-free cryogenic transfer into high-vacuum columns.

Standards: IEC 61131-3, PackML State Machine
Version: 3.0.0 (Enterprise Production Grade)
================================================================================
*)

FUNCTION_BLOCK FB_CryoEM_Vitrification
VAR_INPUT
    bEnable                  : BOOL;         (* Enable controller *)
    bStart                   : BOOL;         (* Trigger plunge cycle *)
    bAbort                   : BOOL;         (* Emergency abort *)
    bReset                   : BOOL;         (* Reset fault state *)

    // Plunge Vitrification Parameters
    lrTargetPlungeVelocity   : LREAL := 2.0; (* m/s, target actuation speed *)
    lrEthaneTempSetpoint     : LREAL := -180.0; (* deg C, liquid ethane setpoint *)
    lrGridThickness          : LREAL := 3.0; (* mm, sample copper grid *)
    lrMinCoolingRate         : LREAL := 100000.0; (* deg C/s, threshold for vitreous ice *)

    // Autoloader Vacuum & Env Parameters
    lrVacuumSetpoint         : LREAL := 1.0E-9; (* Torr, column vacuum *)
    lrLN2VaporTemp           : LREAL := -190.0; (* deg C, LN2 environment *)

    // Sensor Feedback
    lrActLinearPosition      : LREAL; (* m, Plunge actuator position *)
    lrActLinearVelocity      : LREAL; (* m/s, Plunge actuator velocity *)
    lrEthaneBathTemp         : LREAL; (* deg C, Actual bath temp *)
    lrSampleTemp             : LREAL; (* deg C, Sample temp from fast thermocouple *)
    lrVacuumLevel            : LREAL; (* Torr, Column vacuum level *)
    lrChamberDewPoint        : LREAL; (* deg C, Frost monitor *)

    // Robotic Arm Feedback (6-DOF)
    aArmJointPositions       : ARRAY[1..6] OF LREAL; (* deg *)
    bGridSecured             : BOOL;  (* Gripper interlock *)
    bInLoadlock              : BOOL;  (* Arm inside vacuum loadlock *)
END_VAR

VAR_OUTPUT
    // PackML State Variables
    iState                   : INT;          (* 1: STOPPED, 2: IDLE, 3: STARTING, 4: EXECUTE, 5: COMPLETED, 6: ABORTING, 7: ABORTED, 8: CLEARING *)
    sStateString             : STRING(32);
    bReady                   : BOOL;
    bPlungeSuccess           : BOOL;
    bTransferSuccess         : BOOL;
    bError                   : BOOL;
    iErrorID                 : INT;

    // Actuator Control
    lrCmdLinearVelocity      : LREAL; (* m/s *)
    lrCmdEthaneHeater        : LREAL; (* %, PID output to regulate -180C precisely *)
    lrCmdCryoPump            : LREAL; (* % *)
    aArmJointCmd             : ARRAY[1..6] OF LREAL; (* deg *)
    bGripperClose            : BOOL;
    bOpenLoadlockValve       : BOOL;

    // Metrology & Process Data
    lrCalculatedCoolingRate  : LREAL; (* deg C/s *)
    bVitreousIceConfirmed    : BOOL;  (* Cooling rate condition met *)
END_VAR

VAR
    // Internal State
    iStep                    : INT := 0;
    lrSampleTempPrevious     : LREAL;
    tTimePrevious            : TIME;
    tTimeCurrent             : TIME;
    fbTimer                  : TON;

    // Process Timers
    tPlungeDwell             : TON;
    tTransferTimeout         : TON;

    // Data Logging
    lrDeltaTemp              : LREAL;
    lrDeltaTime              : LREAL;
END_VAR

VAR CONSTANT
    STATE_STOPPED   : INT := 1;
    STATE_IDLE      : INT := 2;
    STATE_STARTING  : INT := 3;
    STATE_EXECUTE   : INT := 4;
    STATE_COMPLETED : INT := 5;
    STATE_ABORTING  : INT := 6;
    STATE_ABORTED   : INT := 7;
    STATE_CLEARING  : INT := 8;

    // Trajectory positions
    POS_HOME        : LREAL := 0.0;
    POS_PLUNGE      : LREAL := 0.15; (* 150mm plunge depth *)
END_VAR

// -----------------------------------------------------------------------------
// State Machine (PackML inspired)
// -----------------------------------------------------------------------------

IF bAbort THEN
    iState := STATE_ABORTING;
END_IF

CASE iState OF

    0, STATE_STOPPED:
        sStateString := 'STOPPED';
        bReady := FALSE;
        lrCmdLinearVelocity := 0.0;
        bGripperClose := FALSE;
        bOpenLoadlockValve := FALSE;

        IF bEnable THEN
            iState := STATE_CLEARING;
        END_IF

    STATE_CLEARING:
        sStateString := 'CLEARING';
        bError := FALSE;
        iErrorID := 0;
        iStep := 0;
        bPlungeSuccess := FALSE;
        bTransferSuccess := FALSE;
        bVitreousIceConfirmed := FALSE;

        IF NOT bAbort THEN
            iState := STATE_IDLE;
        END_IF

    STATE_IDLE:
        sStateString := 'IDLE';
        bReady := TRUE;

        // Regulate Bath Temperature
        IF lrEthaneBathTemp < (lrEthaneTempSetpoint - 0.5) THEN
            lrCmdEthaneHeater := 10.0; (* Gentle heat to maintain exact liquid state, avoid solid ethane *)
        ELSIF lrEthaneBathTemp > (lrEthaneTempSetpoint + 0.5) THEN
            lrCmdEthaneHeater := 0.0;
        END_IF

        IF bStart THEN
            iState := STATE_STARTING;
        END_IF

    STATE_STARTING:
        sStateString := 'STARTING';
        bReady := FALSE;

        // Safety Pre-checks
        IF (lrEthaneBathTemp > -175.0) OR (lrVacuumLevel > 1.0E-8) THEN
            iErrorID := 101; (* Environmental conditions not met *)
            iState := STATE_ABORTING;
        ELSE
            iStep := 10;
            iState := STATE_EXECUTE;
        END_IF

    STATE_EXECUTE:
        sStateString := 'EXECUTE';

        CASE iStep OF
            10: (* Plunge Actuation Phase *)
                // Command ultra-fast linear motor
                lrCmdLinearVelocity := lrTargetPlungeVelocity;

                // Real-time Cooling Rate Calculation (dT/dt)
                // Assuming cycle time of 1ms
                lrDeltaTemp := lrSampleTempPrevious - lrSampleTemp;
                lrDeltaTime := 0.001; (* 1 ms task cycle assumed *)
                lrCalculatedCoolingRate := lrDeltaTemp / lrDeltaTime;

                // Store historical
                lrSampleTempPrevious := lrSampleTemp;

                // Latch success if threshold breached during plunge
                IF lrCalculatedCoolingRate > lrMinCoolingRate THEN
                    bVitreousIceConfirmed := TRUE;
                END_IF

                // Plunge complete check
                IF lrActLinearPosition >= POS_PLUNGE THEN
                    lrCmdLinearVelocity := 0.0;
                    bPlungeSuccess := TRUE;
                    iStep := 20;
                END_IF

            20: (* Cryogenic Transfer: Engage Gripper in LN2 Vapor *)
                // Move 6-DOF robotic arm to cassette pos
                aArmJointCmd[1] := 45.0;  // Base
                aArmJointCmd[2] := -30.0; // Shoulder
                aArmJointCmd[3] := 90.0;  // Elbow
                aArmJointCmd[4] := 0.0;   // Wrist Pitch
                aArmJointCmd[5] := 90.0;  // Wrist Yaw
                aArmJointCmd[6] := 180.0; // Wrist Roll

                bGripperClose := TRUE;

                IF bGridSecured THEN
                    iStep := 30;
                END_IF

            30: (* Cryogenic Transfer: Align to Loadlock *)
                // Maintain LN2 vapor shroud constraints
                IF lrChamberDewPoint > -100.0 THEN
                    iErrorID := 201; (* Frost contamination risk detected *)
                    iState := STATE_ABORTING;
                END_IF

                aArmJointCmd[1] := -90.0; // Rotate to Microscope Loadlock

                // Allow loadlock vacuum pumpdown before valve opens
                IF lrVacuumLevel <= lrVacuumSetpoint THEN
                    bOpenLoadlockValve := TRUE;
                    tTransferTimeout(IN:=TRUE, PT:=T#5S);

                    IF bInLoadlock THEN
                        iStep := 40;
                    END_IF
                END_IF

            40: (* Loadlock Entry and Hand-off *)
                // Place into microscope column
                bGripperClose := FALSE; (* Release *)
                bTransferSuccess := TRUE;
                bOpenLoadlockValve := FALSE;

                iState := STATE_COMPLETED;

        END_CASE

    STATE_COMPLETED:
        sStateString := 'COMPLETED';
        IF bReset THEN
            iState := STATE_CLEARING;
        END_IF

    STATE_ABORTING:
        sStateString := 'ABORTING';
        bError := TRUE;
        lrCmdLinearVelocity := 0.0;
        bOpenLoadlockValve := FALSE;

        // Move arm to safe park
        aArmJointCmd[1] := 0.0;

        iState := STATE_ABORTED;

    STATE_ABORTED:
        sStateString := 'ABORTED';
        IF bReset AND NOT bAbort THEN
            iState := STATE_CLEARING;
        END_IF

END_CASE

END_FUNCTION_BLOCK
