    // Hardware Status
    bPumpHealthy        : BOOL;     // Ceramic-piston positive displacement pump status
    bIronShotAvailable  : BOOL;     // True if iron shot weights remain
    fAvailableFoamVol_m3: LREAL;    // Base syntactic foam volume
END_VAR

VAR_OUTPUT
    // PackML State Outputs
    nCurrentState       : INT;      // Current PackML State (0=Undefined, 1=Clearing, 2=Stopped, 3=Starting, 4=Idle, 5=Suspended, 6=Execute, 7=Stopping, 8=Aborting, 9=Aborted, 10=Holding, 11=Held)
    bStateComplete      : BOOL;     // State completion flag
    bError              : BOOL;     // General Error Flag
    nErrorID            : DINT;     // Error Code

    // Variable Ballast Actuators
    bPumpRun            : BOOL;     // Command ceramic-piston pump
    fPumpSpeed_pct      : LREAL;    // 0-100% pump speed
