    // Life Support Actuators
    bEnableLiOH_Fan     : BOOL;     // CO2 scrubber fan command
    bInjectKO2_Oxygen   : BOOL;     // Oxygen generator trigger

    // Alarms & Emergency
    bEmergencySurface   : BOOL;     // Drop all weights, max positive buoyancy
    bRapidDecompWarning : BOOL;     // Cabin pressure dropping alarm
    fVotedO2_pp_atm     : LREAL;    // Voted result of O2 sensors
END_VAR

VAR
    // PackML State Machine
    ePackMLState        : INT := 2; // Default to STOPPED (2)

    // Voting Logic Variables
    fO2_Diff_1_2        : LREAL;
    fO2_Diff_2_3        : LREAL;
    fO2_Diff_1_3        : LREAL;
    bO2_S1_Valid        : BOOL;
    bO2_S2_Valid        : BOOL;
    bO2_S3_Valid        : BOOL;
    fO2_DeviationLimit  : LREAL := 0.05; // 5% deviation tolerance

    // Buoyancy Math
    fSeawaterDensity    : LREAL := 1023.6; // Base density kg/m3 (increases with depth/pressure)
    fFoamBulkModulus    : LREAL := 2.5E9; // Pascals (approx for syntactic foam)
    fDeltaVolume        : LREAL;
    fLostBuoyancy_kg    : LREAL;

    // Timers
    tonDropShot         : TON;
    tonDropCooldown     : TON;
    tonLifeSupportLoop  : TON;
    tonErrorTimer       : TON;

    // Internal States
    bShotDropInProgress : BOOL;
    fAccumulatedLostBuoyancy : LREAL := 0.0;
    fCompensatedBuoyancy: LREAL := 0.0;

    // Constants
    cMaxDepth_m         : LREAL := 11500.0;
    cO2_SetPoint        : LREAL := 1.0;  // 1.0 atm O2 partial pressure
    cCO2_Max_ppm        : LREAL := 5000.0; // Max acceptable CO2 limit
    cIronShotMass_kg    : LREAL := 10.0; // Mass of one micro-batch of iron shot
END_VAR

// ======================================================================================
// ENUMERATION (PackML States as INT constants)
// 0=UNDEFINED, 1=CLEARING, 2=STOPPED, 3=STARTING, 4=IDLE, 5=SUSPENDED, 
// 6=EXECUTE, 7=STOPPING, 8=ABORTING, 9=ABORTED, 10=HOLDING, 11=HELD
// ======================================================================================

// ======================================================================================
// MAIN LOGIC
// ======================================================================================

// 1. PackML State Machine Evaluation
CASE ePackMLState OF

    2: // STOPPED
        bPumpRun := FALSE;
        fPumpSpeed_pct := 0.0;
        bEnableLiOH_Fan := FALSE;
        bInjectKO2_Oxygen := FALSE;
        bDropIronShot := FALSE;
        bEmergencySurface := FALSE;

        IF bExecute THEN
            ePackMLState := 4; // IDLE
        END_IF
        IF bAbort THEN ePackMLState := 8; END_IF;

    4: // IDLE
        IF bExecute THEN
            ePackMLState := 3; // STARTING
        END_IF
        IF bAbort THEN ePackMLState := 8; END_IF;

    3: // STARTING
        // Initialize pumps, warmup sensors
        bStateComplete := TRUE;
        IF bStateComplete THEN ePackMLState := 6; END_IF; // EXECUTE
        IF bAbort THEN ePackMLState := 8; END_IF;

    6: // EXECUTE
        // Main operational state

        // --- 1. Life Support: O2 Sensor 2oo3 Voting ---
        fO2_Diff_1_2 := ABS(fO2_Sensor1_pp - fO2_Sensor2_pp);
        fO2_Diff_2_3 := ABS(fO2_Sensor2_pp - fO2_Sensor3_pp);
        fO2_Diff_1_3 := ABS(fO2_Sensor1_pp - fO2_Sensor3_pp);

        bO2_S1_Valid := (fO2_Diff_1_2 <= fO2_DeviationLimit) OR (fO2_Diff_1_3 <= fO2_DeviationLimit);
        bO2_S2_Valid := (fO2_Diff_1_2 <= fO2_DeviationLimit) OR (fO2_Diff_2_3 <= fO2_DeviationLimit);
        bO2_S3_Valid := (fO2_Diff_1_3 <= fO2_DeviationLimit) OR (fO2_Diff_2_3 <= fO2_DeviationLimit);

        IF bO2_S1_Valid AND bO2_S2_Valid AND bO2_S3_Valid THEN
            fVotedO2_pp_atm := (fO2_Sensor1_pp + fO2_Sensor2_pp + fO2_Sensor3_pp) / 3.0;
        ELSIF bO2_S1_Valid AND bO2_S2_Valid THEN
            fVotedO2_pp_atm := (fO2_Sensor1_pp + fO2_Sensor2_pp) / 2.0;
        ELSIF bO2_S2_Valid AND bO2_S3_Valid THEN
            fVotedO2_pp_atm := (fO2_Sensor2_pp + fO2_Sensor3_pp) / 2.0;
        ELSIF bO2_S1_Valid AND bO2_S3_Valid THEN
            fVotedO2_pp_atm := (fO2_Sensor1_pp + fO2_Sensor3_pp) / 2.0;
        ELSE
            // Critical Sensor Failure
            bError := TRUE;
            nErrorID := 1001; // O2 Sensor Disagreement
            ePackMLState := 8; // ABORTING
            fVotedO2_pp_atm := fO2_Sensor1_pp; // Fallback
        END_IF

        // --- 2. Life Support: Control Actions ---
        // Maintain exact 1.0 atm O2 partial pressure
        IF fVotedO2_pp_atm < (cO2_SetPoint - 0.02) THEN
            bInjectKO2_Oxygen := TRUE;
        ELSIF fVotedO2_pp_atm >= cO2_SetPoint THEN
            bInjectKO2_Oxygen := FALSE;
        END_IF

        // Maintain CO2 Levels
        IF fCO2_Level_ppm > 2000.0 THEN
            bEnableLiOH_Fan := TRUE;
        ELSIF fCO2_Level_ppm < 500.0 THEN
            bEnableLiOH_Fan := FALSE;
        END_IF

        // Rapid Decompression Check
        IF fCabinPress_atm < 0.90 THEN // Dropping below safe nominal 1 atm
            bRapidDecompWarning := TRUE;
            ePackMLState := 8; // ABORTING
        ELSE
            bRapidDecompWarning := FALSE;
        END_IF

        // --- 3. Buoyancy: Variable Ballast & Foam Compressibility ---
        // Calculate dynamic seawater density at pressure (Simplified Tait equation approx)
        // Density = Base / (1 - (Pressure/BulkModulus))
        // Pressure in Pascals: fAmbientPress_bar * 100,000
        fSeawaterDensity := 1023.6 * (1.0 + (fAmbientPress_bar * 100000.0) / 2.2E9);

        // Calculate foam volume reduction
        // dV = V * dP / BulkModulus
        fDeltaVolume := fAvailableFoamVol_m3 * (fAmbientPress_bar * 100000.0) / fFoamBulkModulus;

        // Total lost buoyancy force in kg
        fLostBuoyancy_kg := fDeltaVolume * fSeawaterDensity;

        // Iron Shot Dropping Logic
        // If uncompensated lost buoyancy exceeds iron shot batch mass, drop a batch
        IF (fLostBuoyancy_kg - fCompensatedBuoyancy) >= cIronShotMass_kg AND bIronShotAvailable AND NOT bShotDropInProgress THEN
            bShotDropInProgress := TRUE;
            bDropIronShot := TRUE; // Trigger coil
        END_IF

        // Timer to reset drop pulse
        tonDropShot(IN := bShotDropInProgress, PT := T#2S);
        IF tonDropShot.Q THEN
            bDropIronShot := FALSE;
            fCompensatedBuoyancy := fCompensatedBuoyancy + cIronShotMass_kg;
            bShotDropInProgress := FALSE;
        END_IF

        // Ceramic-Piston Ballast Pump Control
        // Used to adjust trim/buoyancy finely. 
        // If we want to ascend, we pump water OUT against 1,100 bar.
        IF fTargetDepth_m < fDepth_m AND bPumpHealthy THEN
            bPumpRun := TRUE;
            fPumpSpeed_pct := 100.0; // Max effort against abyssal pressure
        ELSE
            bPumpRun := FALSE;
            fPumpSpeed_pct := 0.0;
        END_IF

        // Depth limit safety
        IF fDepth_m > cMaxDepth_m THEN
            ePackMLState := 8; // ABORTING
            nErrorID := 9999; // CRITICAL DEPTH EXCEEDED
        END_IF

        IF bStop THEN ePackMLState := 7; END_IF; // STOPPING
        IF bHold THEN ePackMLState := 10; END_IF; // HOLDING
        IF bAbort THEN ePackMLState := 8; END_IF; // ABORTING

    10: // HOLDING
        bPumpRun := FALSE;
        IF bExecute THEN ePackMLState := 6; END_IF; // EXECUTE
        IF bAbort THEN ePackMLState := 8; END_IF;

    7: // STOPPING
        bPumpRun := FALSE;
        bDropIronShot := FALSE;
        bStateComplete := TRUE;
        IF bStateComplete THEN ePackMLState := 2; END_IF; // STOPPED
        IF bAbort THEN ePackMLState := 8; END_IF;

    8: // ABORTING
        // EMERGENCY SURFACE PROTOCOL
        bEmergencySurface := TRUE;
        bPumpRun := TRUE;
        fPumpSpeed_pct := 100.0;
        bDropIronShot := TRUE; // Continuous signal to dump all shot

        bStateComplete := (fDepth_m < 1.0); // Abort complete when on surface

        IF bStateComplete THEN
            bEmergencySurface := FALSE;
            bDropIronShot := FALSE;
            bPumpRun := FALSE;
            ePackMLState := 9; // ABORTED
        END_IF;

    9: // ABORTED
        IF bClear THEN
            bError := FALSE;
            nErrorID := 0;
            ePackMLState := 1; // CLEARING
        END_IF

    1: // CLEARING
        bStateComplete := TRUE;
        IF bStateComplete THEN ePackMLState := 2; END_IF; // STOPPED

END_CASE

// Update PackML Output
nCurrentState := ePackMLState;

END_FUNCTION_BLOCK
