FUNCTION_BLOCK FB_WAAM_12Axis_Controller
TITLE = '12-Axis WAAM Robot Controller for Aerospace Additive Manufacturing'
{ S7_Optimized_Access := 'TRUE' }
AUTHOR : 'Lumina Elite Data Architect'
VERSION : '3.0'

VAR_INPUT 
    bEnableSystem : BOOL;   // Master system enable
    bStartPrint : BOOL;     // Initiate print sequence

    // 1. Melt-Pool Monitoring
    rMeltPoolTempC : REAL;  // Current melt pool temp from optical pyrometer (Celsius)
    rTargetMeltPoolTempC : REAL := 1250.0; // Target optimal temp for aerospace Aluminum Alloy

    // 2. Laser Triangulation (Z-Height)
    rScannedPrevLayerHeightMM : REAL; // Actual scanned height of the previous layer
    rExpectedLayerHeightMM : REAL := 2.5; // Nominal expected layer height

    // 3. Argon Shielding Gas
    rCurrentArgonFlowLPM : REAL; // Current argon flow in Liters Per Minute
    rTargetArgonFlowLPM : REAL := 15.0; // Target flow for ideal laminar coverage

    // Axis Feedback
    aAxisPositions : ARRAY[1..12] OF LREAL; // 6-Axis Robot + 2-Axis Positioner + 3-Axis Gantry + 1-Axis Wire Feeder
END_VAR

VAR_OUTPUT 
    rArcVoltageV : REAL; // Dynamically scaled arc voltage
    rArgonValveControlVolt : REAL; // 0-10V control signal for Argon proportional valve
    rZHeightCorrectionMM : REAL; // Calculated Z-offset for next pass
    aCommandedPositions : ARRAY[1..12] OF LREAL; // Commanded kinematics

    bSystemReady : BOOL;
    bWeldingActive : BOOL;
    bAlarm : BOOL;
END_VAR

VAR 
    // Temperature Control Parameters
    rTempError : REAL;
    rKp_Voltage : REAL := -0.015; // Inverted gain: too hot -> lower voltage
    rNominalArcVoltage : REAL := 22.5;
    rMaxVoltage : REAL := 28.0;
    rMinVoltage : REAL := 18.0;

    // Z-Height Compensation Parameters
    rLayerHeightError : REAL;
    rZCorrectionGain : REAL := 0.65; // Correct 65% of deviation per layer to prevent oscillation

    // Argon PID Controller (Simulated block instance)
    instArgonPID : "PID_Compact"; 

    // Inherited PWM/Clock components for high-speed sensor sampling sync
    instTofTimePulse : TOF_TIME;
    instTofTimePause : TOF_TIME;
    statTimePulse : TIME := T#2ms;
    statTimePause : TIME := T#2ms;
    bSensorSyncClock : BOOL;
END_VAR

BEGIN
    // ==========================================
    // SYSTEM ENABLE & SYNCHRONIZATION
    // ==========================================
    IF NOT #bEnableSystem THEN
        #bSystemReady := FALSE;
        #bWeldingActive := FALSE;
        #rArcVoltageV := 0.0;
        #rArgonValveControlVolt := 0.0;
        RETURN;
    ELSE
        #bSystemReady := TRUE;
    END_IF;

    // Evolved Clock Generator: 2ms pulse/pause for high-freq Pyrometer & Laser sync
    #instTofTimePulse(IN := NOT #instTofTimePause.Q, PT := #statTimePulse);
    #instTofTimePause(IN := #instTofTimePulse.Q, PT := #statTimePause);
    #bSensorSyncClock := #instTofTimePulse.Q;

    // ==========================================
    // 1. MELT-POOL TEMPERATURE MONITORING
    // ==========================================
    // Synchronized calculation of arc voltage scaling to prevent alloy collapse
    IF #bSensorSyncClock AND #bWeldingActive THEN
        #rTempError := #rTargetMeltPoolTempC - #rMeltPoolTempC;

        // Dynamic scaling: If temp > target, error is negative, reduce voltage (heat input)
        #rArcVoltageV := #rNominalArcVoltage + (#rTempError * #rKp_Voltage);

        // Clamping
        IF #rArcVoltageV > #rMaxVoltage THEN
            #rArcVoltageV := #rMaxVoltage;
        ELSIF #rArcVoltageV < #rMinVoltage THEN
            #rArcVoltageV := #rMinVoltage;
        END_IF;
    ELSIF NOT #bWeldingActive THEN
        #rArcVoltageV := 0.0;
    END_IF;

    // ==========================================
    // 2. DYNAMIC Z-HEIGHT COMPENSATION
    // ==========================================
    // Real-time laser triangulation delta calculation
    #rLayerHeightError := #rExpectedLayerHeightMM - #rScannedPrevLayerHeightMM;
    #rZHeightCorrectionMM := #rLayerHeightError * #rZCorrectionGain;

    // Assuming Axis 3 is the primary Z-axis of the global gantry system
    #aCommandedPositions[3] := #aAxisPositions[3] + #rExpectedLayerHeightMM + #rZHeightCorrectionMM;

    // ==========================================
    // 3. ARGON SHIELDING GAS PID CONTROL
    // ==========================================
    // Maintain strict laminar flow to avoid atmospheric oxidation of the titanium/aluminum weld pool
    #instArgonPID(
        Setpoint := #rTargetArgonFlowLPM,
        Input := #rCurrentArgonFlowLPM,
        Kp := 3.2,
        Ti := T#150ms,
        Td := T#20ms,
        Output => #rArgonValveControlVolt
    );

    // Valve scaling (0 - 10V)
    IF #rArgonValveControlVolt < 0.0 THEN 
        #rArgonValveControlVolt := 0.0; 
    ELSIF #rArgonValveControlVolt > 10.0 THEN 
        #rArgonValveControlVolt := 10.0; 
    END_IF;

    // ==========================================
    // SEQUENCE CONTROL
    // ==========================================
    IF #bStartPrint AND #bSystemReady THEN
        #bWeldingActive := TRUE;
    ELSE
        #bWeldingActive := FALSE;
    END_IF;

END_FUNCTION_BLOCK
