FUNCTION_BLOCK FB_TunnelOvenControl
VAR_INPUT
    bEnable : BOOL; // Enable oven operation
    rSetpointZone1 : REAL; // Temperature setpoint for Zone 1 (C)
    rSetpointZone2 : REAL; // Temperature setpoint for Zone 2 (C)
    rSetpointZone3 : REAL; // Temperature setpoint for Zone 3 (C)
    rActualTempZone1 : REAL; // Actual temperature in Zone 1 (C)
    rActualTempZone2 : REAL; // Actual temperature in Zone 2 (C)
    rActualTempZone3 : REAL; // Actual temperature in Zone 3 (C)
    rConveyorSpeedSet : REAL; // Desired conveyor speed (m/min)
    rConveyorSpeedAct : REAL; // Actual conveyor speed (m/min)
    bEmergencyStop : BOOL; // Emergency stop active (NC)
    bBurner1FlameStatus : BOOL;
    bBurner2FlameStatus : BOOL;
    bBurner3FlameStatus : BOOL;
END_VAR

VAR_OUTPUT
    rBurner1Modulation : REAL; // 0-100% modulation for Zone 1
    rBurner2Modulation : REAL; // 0-100% modulation for Zone 2
    rBurner3Modulation : REAL; // 0-100% modulation for Zone 3
    rExhaustDamperPos : REAL; // 0-100% position for exhaust damper
    rConveyorMotorCmd : REAL; // 0-100% speed reference for conveyor
    bBurner1Ignite : BOOL;
    bBurner2Ignite : BOOL;
    bBurner3Ignite : BOOL;
    bAlarmOvertemp : BOOL;
    bAlarmUndertemp : BOOL;
    bAlarmConveyorSlip : BOOL;
    bSystemReady : BOOL;
END_VAR

VAR
    // PID parameters for Zone 1
    rKp1 : REAL := 2.5;
    rKi1 : REAL := 0.1;
    rKd1 : REAL := 0.5;
    rError1 : REAL;
    rIntegral1 : REAL;
    rPrevError1 : REAL;

    // PID parameters for Zone 2
    rKp2 : REAL := 2.2;
    rKi2 : REAL := 0.15;
    rKd2 : REAL := 0.4;
    rError2 : REAL;
    rIntegral2 : REAL;
    rPrevError2 : REAL;

    // PID parameters for Zone 3
    rKp3 : REAL := 2.0;
    rKi3 : REAL := 0.1;
    rKd3 : REAL := 0.3;
    rError3 : REAL;
    rIntegral3 : REAL;
    rPrevError3 : REAL;

    // Limits
    rMaxTempLimit : REAL := 300.0; // Max allowed temperature
    rMinTempLimit : REAL := 20.0;

    tUpdateCycle : TIME := T#100ms;
    TimerUpdate : TON;

    // State machine
    iState : INT := 0; 
END_VAR

// Implementation
TimerUpdate(IN:= TRUE, PT:= tUpdateCycle);
IF TimerUpdate.Q THEN
    TimerUpdate(IN:= FALSE); // Reset timer
    TimerUpdate(IN:= TRUE);

    IF bEmergencyStop THEN
        rBurner1Modulation := 0.0;
        rBurner2Modulation := 0.0;
        rBurner3Modulation := 0.0;
        rExhaustDamperPos := 100.0; // Fully open on E-Stop
        rConveyorMotorCmd := 0.0;
        bBurner1Ignite := FALSE;
        bBurner2Ignite := FALSE;
        bBurner3Ignite := FALSE;
        iState := 0;
        bSystemReady := FALSE;
    ELSIF bEnable THEN
        bSystemReady := TRUE;

        // PID Zone 1
        rError1 := rSetpointZone1 - rActualTempZone1;
        rIntegral1 := rIntegral1 + (rError1 * 0.1); // Assuming 0.1s dt
        rBurner1Modulation := (rKp1 * rError1) + (rKi1 * rIntegral1) + (rKd1 * (rError1 - rPrevError1) / 0.1);
        IF rBurner1Modulation > 100.0 THEN rBurner1Modulation := 100.0; END_IF;
        IF rBurner1Modulation < 0.0 THEN rBurner1Modulation := 0.0; END_IF;
        rPrevError1 := rError1;

        // PID Zone 2
        rError2 := rSetpointZone2 - rActualTempZone2;
        rIntegral2 := rIntegral2 + (rError2 * 0.1);
        rBurner2Modulation := (rKp2 * rError2) + (rKi2 * rIntegral2) + (rKd2 * (rError2 - rPrevError2) / 0.1);
        IF rBurner2Modulation > 100.0 THEN rBurner2Modulation := 100.0; END_IF;
        IF rBurner2Modulation < 0.0 THEN rBurner2Modulation := 0.0; END_IF;
        rPrevError2 := rError2;

        // PID Zone 3
        rError3 := rSetpointZone3 - rActualTempZone3;
        rIntegral3 := rIntegral3 + (rError3 * 0.1);
        rBurner3Modulation := (rKp3 * rError3) + (rKi3 * rIntegral3) + (rKd3 * (rError3 - rPrevError3) / 0.1);
        IF rBurner3Modulation > 100.0 THEN rBurner3Modulation := 100.0; END_IF;
        IF rBurner3Modulation < 0.0 THEN rBurner3Modulation := 0.0; END_IF;
        rPrevError3 := rError3;

        // Burner Ignition Logic
        bBurner1Ignite := (rBurner1Modulation > 5.0) AND NOT bBurner1FlameStatus;
        bBurner2Ignite := (rBurner2Modulation > 5.0) AND NOT bBurner2FlameStatus;
        bBurner3Ignite := (rBurner3Modulation > 5.0) AND NOT bBurner3FlameStatus;

        // Conveyor Speed Control
        rConveyorMotorCmd := (rConveyorSpeedSet / 20.0) * 100.0; // Assuming 20m/min is max speed
        IF rConveyorMotorCmd > 100.0 THEN rConveyorMotorCmd := 100.0; END_IF;
        IF rConveyorMotorCmd < 0.0 THEN rConveyorMotorCmd := 0.0; END_IF;

        // Slip Detection
        IF (rConveyorSpeedSet > 2.0) AND (rConveyorSpeedAct < (rConveyorSpeedSet * 0.8)) THEN
            bAlarmConveyorSlip := TRUE;
        ELSE
            bAlarmConveyorSlip := FALSE;
        END_IF;

        // Exhaust Damper Tracking (Track highest demand zone)
        rExhaustDamperPos := rBurner1Modulation;
        IF rBurner2Modulation > rExhaustDamperPos THEN rExhaustDamperPos := rBurner2Modulation; END_IF;
        IF rBurner3Modulation > rExhaustDamperPos THEN rExhaustDamperPos := rBurner3Modulation; END_IF;

        // Overtemp Alarm
        IF (rActualTempZone1 > rMaxTempLimit) OR (rActualTempZone2 > rMaxTempLimit) OR (rActualTempZone3 > rMaxTempLimit) THEN
            bAlarmOvertemp := TRUE;
        ELSE
            bAlarmOvertemp := FALSE;
        END_IF;

    ELSE
        rBurner1Modulation := 0.0;
        rBurner2Modulation := 0.0;
        rBurner3Modulation := 0.0;
        rExhaustDamperPos := 20.0; // Minimal exhaust when disabled
        rConveyorMotorCmd := 0.0;
        bBurner1Ignite := FALSE;
        bBurner2Ignite := FALSE;
        bBurner3Ignite := FALSE;
        bSystemReady := TRUE;
    END_IF;
END_IF;
END_FUNCTION_BLOCK
