FUNCTION_BLOCK FB_CZ_Puller_AdvancedControl
VAR_INPUT
    (* System & Safety Signals *)
    bEnable           : BOOL;     (* System enable signal *)
    bEmergencyStop    : BOOL;     (* Safety relay OK signal *)

    (* Process Measurements *)
    rMeltTemp         : REAL;     (* Molten polysilicon temperature [deg C] *)
    rCrystalDia       : REAL;     (* Optical meniscus diameter [mm] *)
    rCrucibleWeight   : REAL;     (* Mass of crucible and remaining melt [kg] *)
    rArgonFlowRate    : REAL;     (* Argon purge flow rate [sccm] *)
    rTargetDia        : REAL;     (* Target crystal diameter [mm] *)
END_VAR

VAR_OUTPUT
    (* System Status *)
    bSystemReady      : BOOL;     (* System ready status *)
    bAlarm            : BOOL;     (* Fault alarm output *)

    (* Control Actuators *)
    rHeaterPower      : REAL;     (* Main heater power control [kW] *)
    rPullSpeed        : REAL;     (* Crystal pull rate [mm/min] *)
    rCrucibleRotation : REAL;     (* Crucible counter-rotation speed [RPM] *)
    rArgonValveCmd    : REAL;     (* Argon purge valve command [%] *)
END_VAR

VAR
    (* Internal state variables *)
    iState            : INT := 0;
    tStateTimer       : TON;

    (* Control Loop Variables *)
    rErrorDia         : REAL := 0.0;
    rIntegralDia      : REAL := 0.0;
    rDerivativeDia    : REAL := 0.0;
    rPrevErrorDia     : REAL := 0.0;

    (* PID Tuning Parameters *)
    rKp_Dia           : REAL := 0.25;
    rKi_Dia           : REAL := 0.015;
    rKd_Dia           : REAL := 0.12;

    (* Mass balance constants *)
    rMeltDensity      : REAL := 2.53; (* kg/L *)
    rBaseRotation     : REAL := 12.0; (* RPM *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rHeaterPower := 0.0;
    rPullSpeed := 0.0;
    rCrucibleRotation := 0.0;
    rArgonValveCmd := 0.0;
    bAlarm := TRUE;
    iState := 0;
    RETURN;
END_IF;

bAlarm := FALSE;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        rHeaterPower := 10.0; (* Idle holding heat *)
        rPullSpeed := 0.0;
        rCrucibleRotation := 2.0; (* Slow idle rotation *)

        IF bEnable THEN
            bSystemReady := FALSE;
            rIntegralDia := 0.0;
            rPrevErrorDia := 0.0;
            iState := 10;
        END_IF;

    10: (* MELT STABILIZATION & ARGON PURGE *)
        (* Implement multi-zone argon purge flow dynamics *)
        rArgonValveCmd := 85.0; (* High initial purge to clear SiO vapor *)
        rHeaterPower := 120.5; (* High power to maintain stable melt phase *)

        tStateTimer(IN := TRUE, PT := T#60S);
        IF tStateTimer.Q AND rMeltTemp > 1414.0 THEN (* Silicon melting point *)
            tStateTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* NECKING & CROWN GROWTH *)
        (* Meniscus optical diameter feed-forward control *)
        rErrorDia := rTargetDia - rCrystalDia;
        rIntegralDia := rIntegralDia + rErrorDia;
        rDerivativeDia := rErrorDia - rPrevErrorDia;
        rPrevErrorDia := rErrorDia;

        (* PID computation for Pull Speed to maintain consistent diameter *)
        rPullSpeed := (rKp_Dia * rErrorDia) + (rKi_Dia * rIntegralDia) + (rKd_Dia * rDerivativeDia);

        (* Clamp pull speed for safety and mechanical limits *)
        IF rPullSpeed > 15.0 THEN
            rPullSpeed := 15.0;
        ELSIF rPullSpeed < 0.1 THEN
            rPullSpeed := 0.1;
        END_IF;

        (* Crucible counter-rotation precision mass balancing *)
        (* As mass decreases, rotation must scale to maintain convective flow boundaries *)
        rCrucibleRotation := rBaseRotation + ((100.0 - rCrucibleWeight) * 0.05);

        (* Heater power feed-forward coupled with pull speed *)
        (* Maintains the latent heat of fusion exactly at the crystal-melt interface *)
        rHeaterPower := 115.0 - (rPullSpeed * 1.2);

        (* Steady purge to remove evolving impurities without disturbing the melt *)
        rArgonValveCmd := 40.0;

        IF NOT bEnable THEN
            iState := 30; (* Initiate safe shutdown sequence *)
        END_IF;

    30: (* SHUTDOWN SEQUENCE *)
        (* Carefully ramp down thermal gradients to prevent crystal dislocation or cracking *)
        rHeaterPower := rHeaterPower * 0.99; (* Gentle cool down *)
        rPullSpeed := 0.0;
        rCrucibleRotation := rCrucibleRotation * 0.95;

        IF rHeaterPower < 5.0 THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
