FUNCTION_BLOCK FB_SeparatorFilmLineControl
VAR_INPUT
    bEnable : BOOL; // Enable control
    rLineSpeedSetpoint_mmin : REAL; // Line speed setpoint
    rMDOTempSetpoint_C : ARRAY[1..5] OF REAL; // Machine Direction Orientation zones temps
    rTDOTempSetpoint_C : ARRAY[1..8] OF REAL; // Transverse Direction Orientation zones temps
    rBetaGaugePorositySetpoint : REAL; // Target porosity
    rCurrentPorosity_PV : REAL; // Actual porosity from beta gauge
    rStaticCharge_kV : REAL; // Current electrostatic charge
    bWebBreakSensor : BOOL; // True if web break detected
END_VAR
VAR_OUTPUT
    bSystemReady : BOOL;
    rMDOTempCommand_C : ARRAY[1..5] OF REAL; // Outputs to MDO zone heaters
    rTDOTempCommand_C : ARRAY[1..8] OF REAL; // Outputs to TDO zone heaters
    rMDOSpeed_mmin : REAL; // Speed of MDO section
    rTDOSpeed_mmin : REAL; // Speed of TDO section
    bESDBarActive : BOOL; // Electrostatic discharge bar control
    bAlarmWebBreak : BOOL;
    bAlarmPorosityDev : BOOL;
    bAlarmHighStatic : BOOL;
END_VAR
VAR
    iZone : INT;
    rPorosityError : REAL;
    PID_Porosity : FB_PID; // Internal PID for porosity -> TDO stretch ratio
    rTDOStretchRatio : REAL := 1.0;
    rBaseSpeed : REAL;

    // ESD Suppression Timer
    tonESD : TON;

    // Thermal Profile Arrays
    rMDO_PID_Output : ARRAY[1..5] OF REAL;
    rTDO_PID_Output : ARRAY[1..8] OF REAL;
END_VAR

// Implementation
IF NOT bEnable THEN
    bSystemReady := FALSE;
    bESDBarActive := FALSE;
    rMDOSpeed_mmin := 0.0;
    rTDOSpeed_mmin := 0.0;
    FOR iZone := 1 TO 5 DO
        rMDOTempCommand_C[iZone] := 0.0;
    END_FOR;
    FOR iZone := 1 TO 8 DO
        rTDOTempCommand_C[iZone] := 0.0;
    END_FOR;
    RETURN;
END_IF;

bSystemReady := TRUE;

// 1. Web Break Detection
IF bWebBreakSensor THEN
    bAlarmWebBreak := TRUE;
    rMDOSpeed_mmin := 0.0;
    rTDOSpeed_mmin := 0.0;
ELSE
    bAlarmWebBreak := FALSE;
END_IF;

// 2. Porosity Control via Beta-Gauge Tracking
// Porosity in separator film is heavily dependent on the stretch ratio in TDO.
// Calculate error and adjust TDO stretch ratio
rPorosityError := rBetaGaugePorositySetpoint - rCurrentPorosity_PV;

// Assuming FB_PID evaluates the error and provides a corrective stretch ratio
PID_Porosity(
    Enable := bSystemReady,
    Setpoint := rBetaGaugePorositySetpoint,
    ProcessVariable := rCurrentPorosity_PV,
    Kp := 1.2,
    Ki := 0.05,
    Kd := 0.1,
    Output => rTDOStretchRatio
);

// Limit stretch ratio for safety
IF rTDOStretchRatio > 3.5 THEN
    rTDOStretchRatio := 3.5;
ELSIF rTDOStretchRatio < 1.0 THEN
    rTDOStretchRatio := 1.0;
END_IF;

// Alarm if deviation is too high (e.g. > 5%)
IF ABS(rPorosityError) > (rBetaGaugePorositySetpoint * 0.05) THEN
    bAlarmPorosityDev := TRUE;
ELSE
    bAlarmPorosityDev := FALSE;
END_IF;

// 3. Line Speed and Orientation Profiling
// MDO (Machine Direction Orientation) runs at base line speed
rMDOSpeed_mmin := rLineSpeedSetpoint_mmin;

// TDO (Transverse Direction Orientation) speed is base speed * stretch ratio
IF NOT bAlarmWebBreak THEN
    rTDOSpeed_mmin := rMDOSpeed_mmin * rTDOStretchRatio;
END_IF;

// 4. Thermal Profiling (TDO/MDO Ovens)
// In a real system, there would be PID blocks for each zone.
// Here we apply a feed-forward compensation based on line speed.
// Higher speeds require slightly higher temperature command to maintain heat transfer.
FOR iZone := 1 TO 5 DO
    rMDOTempCommand_C[iZone] := rMDOTempSetpoint_C[iZone] + (rLineSpeedSetpoint_mmin * 0.1);
END_FOR;

FOR iZone := 1 TO 8 DO
    rTDOTempCommand_C[iZone] := rTDOTempSetpoint_C[iZone] + (rLineSpeedSetpoint_mmin * 0.15 * rTDOStretchRatio);
END_FOR;

// 5. Electrostatic Discharge (ESD) Suppression
// Separator films accumulate immense static charge during stretching.
IF rStaticCharge_kV > 15.0 THEN
    bAlarmHighStatic := TRUE;
    bESDBarActive := TRUE;
ELSIF rStaticCharge_kV > 5.0 THEN
    bAlarmHighStatic := FALSE;
    bESDBarActive := TRUE;
ELSE
    bAlarmHighStatic := FALSE;
    // Turn off ESD bar after a delay if charge is low
    tonESD(IN := (rStaticCharge_kV < 2.0), PT := T#5S);
    IF tonESD.Q THEN
        bESDBarActive := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
