FUNCTION_BLOCK "BakeryOvenControl_M4"
VERSION : 0.1
   VAR_INPUT 
      Start : Bool;
      Stop : Bool;
      TargetSpeed : Real;
      Zone1_TempTarget : Real;
      Zone1_TempActual_A : Real; // Sensor 1
      Zone1_TempActual_B : Real; // Sensor 2
      Zone1_TempActual_C : Real; // Sensor 3 for 2oo3 voting
      DigitalTwin_SyncCmd : Bool; // HIL Sync pulse
      SelfTest_Req : Bool; // Pre-startup test request
   END_VAR

   VAR_OUTPUT 
      ConveyorRun : Bool;
      ConveyorSpeedOut : Real;
      Zone1_Heater : Bool;
      Running : Bool;
      AlarmCode : Int;
      DigitalTwin_Ack : Bool; // HIL Handshake
      SelfTest_Passed : Bool;
   END_VAR

   VAR 
      StateRunning : Bool;
      SelfTestActive : Bool;
      DriftDetected : Bool;
      Zone1_TempUsed : Real;
   END_VAR

BEGIN
    // 1. Digital Twin HIL Synchronization Handshake
    IF #DigitalTwin_SyncCmd THEN
        #DigitalTwin_Ack := TRUE;
    ELSE
        #DigitalTwin_Ack := FALSE;
    END_IF;

    // 2. Advanced Sensor Drift Detection (2oo3 Voting logic)
    // Detect if any sensor deviates significantly from others
    IF (ABS(#Zone1_TempActual_A - #Zone1_TempActual_B) > 5.0) AND 
       (ABS(#Zone1_TempActual_B - #Zone1_TempActual_C) > 5.0) THEN
        #DriftDetected := TRUE;
        #AlarmCode := 301; // Critical Drift Alarm
        #Zone1_TempUsed := #Zone1_TempActual_A; // Fallback to A
    ELSE
        #DriftDetected := FALSE;
        // Median logic simplified for compilation
        #Zone1_TempUsed := (#Zone1_TempActual_A + #Zone1_TempActual_B + #Zone1_TempActual_C) / 3.0;
    END_IF;

    // 3. Pre-startup Self-Test Routine
    // Triggers physical actuators briefly before entering ready state
    IF #SelfTest_Req AND NOT #StateRunning THEN
        #SelfTestActive := TRUE;
        #Zone1_Heater := TRUE; // Pulse heater to verify contactor
        // ... evaluate contactor feedback here ...
        #SelfTest_Passed := TRUE; 
        #SelfTestActive := FALSE;
    END_IF;

    // 4. Master Control Logic
    IF #Stop OR #DriftDetected THEN
        #StateRunning := FALSE;
    ELSIF #Start AND NOT #SelfTestActive AND #SelfTest_Passed THEN
        #StateRunning := TRUE;
        #AlarmCode := 0;
    END_IF;

    #Running := #StateRunning;

    // 5. Output Mapping
    IF #StateRunning THEN
        #ConveyorRun := TRUE;
        #ConveyorSpeedOut := #TargetSpeed;
        #Zone1_Heater := #Zone1_TempUsed < (#Zone1_TempTarget - 2.0);
    ELSE
        #ConveyorRun := FALSE;
        #ConveyorSpeedOut := 0.0;
        IF NOT #SelfTestActive THEN
            #Zone1_Heater := FALSE;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
