FUNCTION_BLOCK FB_EUV_WaferStageControl
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal for magnetic levitation stage *)
    bVacuumInterlockOk      : BOOL;     (* High vacuum environment OK interlock *)
    rLaserInterferometerX   : REAL;     (* Nanometer-precision X position feedback [nm] *)
    rLaserInterferometerY   : REAL;     (* Nanometer-precision Y position feedback [nm] *)
    rLaserInterferometerZ   : REAL;     (* Nanometer-precision Z position feedback [nm] *)
    rTargetPosX             : REAL;     (* Commanded target X position [nm] *)
    rTargetPosY             : REAL;     (* Commanded target Y position [nm] *)
    rTargetPosZ             : REAL;     (* Commanded target Z position [nm] *)
    rVibrationSensor        : REAL;     (* Feed-forward vibration sensor input for active cancellation [Hz/nm] *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* Stage is levitated, stabilized, and ready for exposure *)
    rCoilCurrentX           : REAL;     (* X-axis Lorentz actuator control signal [A] *)
    rCoilCurrentY           : REAL;     (* Y-axis Lorentz actuator control signal [A] *)
    rCoilCurrentZ           : REAL;     (* Z-axis Lorentz actuator control signal [A] *)
    bPositionSettled        : BOOL;     (* TRUE when error < 0.1 nm for 5ms *)
    bAlarm                  : BOOL;     (* Critical fault alarm output (e.g., loss of levitation) *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tSettleTimer            : TON;
    rErrorX                 : REAL;
    rErrorY                 : REAL;
    rErrorZ                 : REAL;
    rKp                     : REAL := 15.5;   (* Proportional gain for magnetic levitation *)
    rKd                     : REAL := 8.2;    (* Derivative gain for stabilization *)
    rLastErrorX             : REAL;
    rLastErrorY             : REAL;
    rLastErrorZ             : REAL;
    rFeedForwardAmp         : REAL := 0.85;   (* Gain for vibration active cancellation *)
    bIsLevitated            : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)

(* Safety and Environment Interlock Processing *)
IF NOT bVacuumInterlockOk THEN
    bSystemReady := FALSE;
    bPositionSettled := FALSE;
    bIsLevitated := FALSE;
    rCoilCurrentX := 0.0;
    rCoilCurrentY := 0.0;
    rCoilCurrentZ := 0.0;
    bAlarm := TRUE;
    iState := 99; (* Fault state *)
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE & GROUNDED *)
        bSystemReady := FALSE;
        bPositionSettled := FALSE;
        bAlarm := FALSE;
        rCoilCurrentX := 0.0;
        rCoilCurrentY := 0.0;
        rCoilCurrentZ := 0.0;

        IF bEnable AND bVacuumInterlockOk THEN
            iState := 10;
        END_IF;

    10: (* LEVITATION STARTUP & CALIBRATION *)
        (* Apply initial lift current to Z-axis coils *)
        rCoilCurrentZ := rCoilCurrentZ + 0.1; 
        IF rLaserInterferometerZ > -100.0 THEN
            (* Stage has lifted off the mechanical hard stops *)
            bIsLevitated := TRUE;
            iState := 20;
        END_IF;

    20: (* ACTIVE STABILIZATION & POSITIONING *)
        (* Calculate Position Errors *)
        rErrorX := rTargetPosX - rLaserInterferometerX;
        rErrorY := rTargetPosY - rLaserInterferometerY;
        rErrorZ := rTargetPosZ - rLaserInterferometerZ;

        (* PID + Feed-Forward Control for X Axis *)
        rCoilCurrentX := (rErrorX * rKp) + ((rErrorX - rLastErrorX) * rKd) - (rVibrationSensor * rFeedForwardAmp);

        (* PID + Feed-Forward Control for Y Axis *)
        rCoilCurrentY := (rErrorY * rKp) + ((rErrorY - rLastErrorY) * rKd) - (rVibrationSensor * rFeedForwardAmp);

        (* PID Control for Z Axis (Levitation Maintenance) *)
        rCoilCurrentZ := 20.0 + (rErrorZ * rKp) + ((rErrorZ - rLastErrorZ) * rKd); (* 20.0A bias for gravity compensation *)

        (* Store previous errors for derivative term *)
        rLastErrorX := rErrorX;
        rLastErrorY := rErrorY;
        rLastErrorZ := rErrorZ;

        (* Settle Check (Error < 0.5 nm) *)
        IF (ABS(rErrorX) < 0.5) AND (ABS(rErrorY) < 0.5) AND (ABS(rErrorZ) < 0.5) THEN
            tSettleTimer(IN := TRUE, PT := T#5MS);
        ELSE
            tSettleTimer(IN := FALSE);
            bPositionSettled := FALSE;
        END_IF;

        IF tSettleTimer.Q THEN
            bPositionSettled := TRUE;
            bSystemReady := TRUE;
        END_IF;

        (* Disable logic *)
        IF NOT bEnable THEN
            bIsLevitated := FALSE;
            iState := 30;
        END_IF;

    30: (* CONTROLLED DESCENT *)
        rCoilCurrentX := 0.0;
        rCoilCurrentY := 0.0;
        rCoilCurrentZ := rCoilCurrentZ - 0.5;
        bSystemReady := FALSE;
        bPositionSettled := FALSE;

        IF rLaserInterferometerZ <= -150.0 OR rCoilCurrentZ <= 0.0 THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        (* Wait for vacuum or safety clearance before resetting *)
        IF bVacuumInterlockOk AND NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

