```iec-st
FUNCTION_BLOCK FB_SyncCondenser_MasterControl
TITLE = 'Utility-Scale Synchronous Condenser Master Control'
// -----------------------------------------------------------------------------
// Description: Advanced master control for a utility-scale synchronous condenser,
// including hydrogen cooling gas cascades, Automatic Voltage Regulator (AVR) 
// over-excitation limits (OEL), and grid inertia/frequency derivative feedback.
// -----------------------------------------------------------------------------

VAR_INPUT
    // Grid Measurements
    rGridVoltage_kV      : REAL; // Grid voltage at point of interconnection
    rGridFrequency_Hz    : REAL; // Grid frequency
    rROCOF_Hz_s          : REAL; // Rate of change of frequency (Hz/s)

    // Condenser State
    rRotorSpeed_RPM      : REAL;
    rFieldCurrent_A      : REAL;
    rStatorVoltage_kV    : REAL;
    rStatorCurrent_A     : REAL;
    rReactivePower_MVAR  : REAL;

    // Cooling System (Hydrogen)
    rH2Purity_Pct        : REAL; // Hydrogen purity percentage (must be > 95%)
    rH2Pressure_kPa      : REAL; // Hydrogen casing pressure
    rColdGasTemp_C       : REAL; // Cold gas temperature entering machine
    rHotGasTemp_C        : REAL; // Hot gas temperature exiting machine

    // Setpoints
    rVoltageSetpoint_kV  : REAL;
    rReactiveSetpoint_MV : REAL;
    bEnableInertiaBoost  : BOOL; // Enable synthetic inertia response

    bEmergencyStop       : BOOL;
    bSystemReset         : BOOL;
END_VAR

VAR_OUTPUT
    // Exciter Control
    rExciterDemand_PU    : REAL; // Per unit excitation demand to AVR
    bOEL_Active          : BOOL; // Over-excitation limiter active flag

    // Cooling Control
    rCoolingValve_Pct    : REAL; // Hydrogen cooler water valve position
    bH2PurgeCommand      : BOOL; // Command to purge and refill H2
    bCoolingAlarm        : BOOL; // Cooling system alarm

    // System Status
    bReadyToSynchronize  : BOOL;
    bGridFaultDetected   : BOOL;
    bTripCommand         : BOOL;
    iStateCode           : INT;
END_VAR

VAR
    // Internal State
    rAVR_Error           : REAL;
    rAVR_Integral        : REAL;
    rAVR_Output          : REAL;

    rOEL_ThermalState    : REAL;
    rOEL_Limit_PU        : REAL;

    rInertiaContribution : REAL;

    // Constants & Limits
    c_rNominalFreq       : REAL := 60.0;
    c_rOEL_MaxTime_s     : REAL := 10.0;
    c_rOEL_MaxField_A    : REAL := 2500.0;
    c_rOEL_ContField_A   : REAL := 1800.0;

    c_rH2PurityLimit     : REAL := 95.0; // %
    c_rMaxColdGasTemp    : REAL := 45.0; // Deg C
    c_rMaxHotGasTemp     : REAL := 85.0; // Deg C

    // Timers
    tOEL_Timer           : TON;
    tH2AlarmTimer        : TON;
END_VAR

// =============================================================================
// MAIN ALGORITHM
// =============================================================================

// 1. Emergency and Trip Handling
IF bEmergencyStop THEN
    bTripCommand := TRUE;
    rExciterDemand_PU := 0.0;
    iStateCode := 999; // Emergency tripped
    RETURN;
END_IF;

IF bSystemReset THEN
    bTripCommand := FALSE;
    bGridFaultDetected := FALSE;
    iStateCode := 0; // Standby
    rOEL_ThermalState := 0.0;
END_IF;

// 2. Hydrogen Cooling Cascade Control
// Control the cooling water valve based on cold gas temperature
IF rColdGasTemp_C > 30.0 THEN
    // Proportional control for cooling valve
    rCoolingValve_Pct := (rColdGasTemp_C - 30.0) * 5.0; 
    IF rCoolingValve_Pct > 100.0 THEN
        rCoolingValve_Pct := 100.0;
    END_IF;
ELSE
    rCoolingValve_Pct := 0.0;
END_IF;

// Hydrogen Purity and Temperature Protection
IF (rH2Purity_Pct < c_rH2PurityLimit) OR (rColdGasTemp_C > c_rMaxColdGasTemp) OR (rHotGasTemp_C > c_rMaxHotGasTemp) THEN
    tH2AlarmTimer(IN := TRUE, PT := T#5S);
    IF tH2AlarmTimer.Q THEN
        bCoolingAlarm := TRUE;
        bH2PurgeCommand := (rH2Purity_Pct < 90.0); // Severe loss of purity
        IF rHotGasTemp_C > 95.0 THEN
            bTripCommand := TRUE; // Thermal trip
            iStateCode := 801;
        END_IF;
    END_IF;
ELSE
    tH2AlarmTimer(IN := FALSE);
    bCoolingAlarm := FALSE;
    bH2PurgeCommand := FALSE;
END_IF;

// 3. Grid Inertia Feedback (Synthetic Inertia)
// Utilize ROCOF (Rate of Change of Frequency) to provide fast reactive support
IF bEnableInertiaBoost AND ABS(rROCOF_Hz_s) > 0.1 THEN
    // Negative ROCOF (frequency dropping) implies need for voltage support
    // Positive ROCOF (frequency rising) implies generation excess
    rInertiaContribution := -1.0 * rROCOF_Hz_s * 2.5; // Gain factor

    // Limit inertia contribution
    IF rInertiaContribution > 0.5 THEN
        rInertiaContribution := 0.5;
    ELSIF rInertiaContribution < -0.5 THEN
        rInertiaContribution := -0.5;
    END_IF;
ELSE
    rInertiaContribution := 0.0;
END_IF;

// 4. Automatic Voltage Regulator (AVR) Calculation
rAVR_Error := rVoltageSetpoint_kV - rGridVoltage_kV;

// PI Controller (Simplified)
rAVR_Integral := rAVR_Integral + (rAVR_Error * 0.01); 
IF rAVR_Integral > 2.0 THEN
    rAVR_Integral := 2.0;
ELSIF rAVR_Integral < -1.0 THEN
    rAVR_Integral := -1.0;
END_IF;

rAVR_Output := (rAVR_Error * 5.0) + rAVR_Integral + rInertiaContribution;

// 5. Over-Excitation Limiter (OEL)
// Model inverse-time characteristic of rotor thermal limit
IF rFieldCurrent_A > c_rOEL_ContField_A THEN
    rOEL_ThermalState := rOEL_ThermalState + ((rFieldCurrent_A - c_rOEL_ContField_A) * 0.1);
ELSE
    rOEL_ThermalState := rOEL_ThermalState - 0.5; // Cooling
    IF rOEL_ThermalState < 0.0 THEN
        rOEL_ThermalState := 0.0;
    END_IF;
END_IF;

// Activate OEL if thermal state exceeds threshold
IF rOEL_ThermalState > 100.0 THEN
    bOEL_Active := TRUE;
    rOEL_Limit_PU := 1.0; // Limit to 1.0 PU (nominal continuous)
ELSE
    bOEL_Active := FALSE;
    rOEL_Limit_PU := 2.5; // Ceiling limit
END_IF;

// Apply Limiter to AVR Output
IF rAVR_Output > rOEL_Limit_PU THEN
    rExciterDemand_PU := rOEL_Limit_PU;
ELSIF rAVR_Output < 0.0 THEN
    rExciterDemand_PU := 0.0; // Prevent negative excitation
ELSE
    rExciterDemand_PU := rAVR_Output;
END_IF;

// 6. Synchronization Check
IF (ABS(rGridVoltage_kV - rStatorVoltage_kV) < 0.5) AND (ABS(rGridFrequency_Hz - c_rNominalFreq) < 0.1) AND NOT bTripCommand THEN
    bReadyToSynchronize := TRUE;
    iStateCode := 100; // Ready
ELSE
    bReadyToSynchronize := FALSE;
END_IF;

END_FUNCTION_BLOCK
```

```iec-st
Here is the code with added breadth. It introduces Profinet status monitoring, extracting specific VFD fault codes, and diagnostic flags to ensure safe operation during communication failures.

FUNCTION_BLOCK "Tunnel_Vent_Breadth"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 1.2
   VAR_INPUT
      xAutoMode : Bool;
      xSmokeDetected : Bool;
      iFireZone : Int;
      xDamperOpened : Bool;
      wProfinetStatusVFD : Word; // Status word from VFD
      wVFDFaultCode : Word;      // Fault code from VFD
   END_VAR

   VAR_OUTPUT
      xCmdStartFwd : Bool;
      xCmdStartRev : Bool;
      xCmdDelugeActive : Bool;
      xCommError : Bool;
      xVFDError : Bool;
      iAlarmCode : Int;
   END_VAR

   VAR
      tonCoastDown : TON_TIME;
      statState : Int; 
      statCoastActive : Bool;
   END_VAR

BEGIN
    // Diagnostics & Profinet Monitoring
    xCommError := (wProfinetStatusVFD AND 16#8000) = 0; // Bit 15: Comm OK
    xVFDError := (wProfinetStatusVFD AND 16#0008) <> 0; // Bit 3: Fault Active

    IF xCommError THEN
        iAlarmCode := 101; // Comm failure
    ELSIF xVFDError THEN
        iAlarmCode := WORD_TO_INT(wVFDFaultCode);
    ELSE
        iAlarmCode := 0;
    END_IF;

    tonCoastDown(IN := statCoastActive, PT := T#30s);

    IF xAutoMode AND NOT xCommError AND NOT xVFDError THEN
        IF xSmokeDetected AND xDamperOpened THEN
            xCmdDelugeActive := TRUE;
            IF iFireZone = 1 THEN 
                IF statState = 2 THEN
                    xCmdStartRev := FALSE; statCoastActive := TRUE; statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartFwd := TRUE; statCoastActive := FALSE; statState := 1;
                END_IF;
            ELSIF iFireZone = 3 THEN 
                IF statState = 1 THEN
                    xCmdStartFwd := FALSE; statCoastActive := TRUE; statState := 3;
                ELSIF statState = 0 OR (statState = 3 AND tonCoastDown.Q) THEN
                    xCmdStartRev := TRUE; statCoastActive := FALSE; statState := 2;
                END_IF;
            END_IF;
        ELSE
            xCmdStartFwd := FALSE; xCmdStartRev := FALSE; xCmdDelugeActive := FALSE;
            statState := 0; statCoastActive := FALSE;
        END_IF;
    ELSE
        // Safe state on error or manual mode
        xCmdStartFwd := FALSE; xCmdStartRev := FALSE;
    END_IF;
END_FUNCTION_BLOCK
