FUNCTION_BLOCK FB_DirectedEnergyLaserControl
VAR_INPUT
    bEnableSystem : BOOL; (* Master enable *)
    fTargetAzimuth : LREAL;
    fTargetElevation : LREAL;
    fTargetDistance : LREAL;
    fAtmosphericDensity : LREAL;
    fWindSpeed : LREAL;
    fWindDirection : LREAL;
    arrWavefrontSensorError : ARRAY[1..64] OF LREAL;
    fLaserPowerSetpoint : LREAL;
    bFireCommand : BOOL;
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bLaserFiring : BOOL;
    arrDeformableMirrorActuators : ARRAY[1..256] OF LREAL;
    fFastSteeringAzimuthOut : LREAL;
    fFastSteeringElevationOut : LREAL;
    fLaserPowerActual : LREAL;
    bThermalBloomingWarning : BOOL;
    nSystemState : INT;
END_VAR

VAR
    nState : INT := 0; 
    fThermalBloomingFactor : LREAL;
    nIdx : INT;
    fCorrectionSum : LREAL;
    fAzimuthError : LREAL;
    fAzimuthIntegral : LREAL;
    fElevationError : LREAL;
    fElevationIntegral : LREAL;
    Kp_FSM : LREAL := 12.5;
    Ki_FSM : LREAL := 2.1;
    MAX_STROKE : LREAL := 5.0;
    MAX_POWER : LREAL := 150.0;
END_VAR

CASE nState OF
    0:
        bSystemReady := FALSE;
        bLaserFiring := FALSE;
        fLaserPowerActual := 0.0;
        IF bEnableSystem THEN
            nState := 10;
        END_IF

    10:
        FOR nIdx := 1 TO 256 DO
            arrDeformableMirrorActuators[nIdx] := 0.0;
        END_FOR
        IF NOT bEnableSystem THEN
            nState := 0;
        ELSE
            nState := 20;
        END_IF

    20:
        fAzimuthError := fTargetAzimuth - fFastSteeringAzimuthOut;
        fAzimuthIntegral := fAzimuthIntegral + fAzimuthError * 0.001;
        fFastSteeringAzimuthOut := (Kp_FSM * fAzimuthError) + (Ki_FSM * fAzimuthIntegral);

        fElevationError := fTargetElevation - fFastSteeringElevationOut;
        fElevationIntegral := fElevationIntegral + fElevationError * 0.001;
        fFastSteeringElevationOut := (Kp_FSM * fElevationError) + (Ki_FSM * fElevationIntegral);

        fThermalBloomingFactor := (fLaserPowerSetpoint * fTargetDistance * fAtmosphericDensity) / (fWindSpeed + 0.1);

        IF fThermalBloomingFactor > 50000.0 THEN
            bThermalBloomingWarning := TRUE;
            fLaserPowerActual := LIMIT(0.0, fLaserPowerSetpoint * 0.5, MAX_POWER);
        ELSE
            bThermalBloomingWarning := FALSE;
            fLaserPowerActual := LIMIT(0.0, fLaserPowerSetpoint, MAX_POWER);
        END_IF

        FOR nIdx := 1 TO 256 DO
            fCorrectionSum := 0.0;
            fCorrectionSum := fCorrectionSum + (arrWavefrontSensorError[(nIdx MOD 64) + 1] * -0.85);

            IF bThermalBloomingWarning THEN
                fCorrectionSum := fCorrectionSum + 1.2;
            END_IF

            arrDeformableMirrorActuators[nIdx] := LIMIT(-MAX_STROKE, fCorrectionSum, MAX_STROKE);
        END_FOR

        bSystemReady := TRUE;

        IF bFireCommand AND bEnableSystem THEN
            bLaserFiring := TRUE;
        ELSE
            bLaserFiring := FALSE;
        END_IF

        IF NOT bEnableSystem THEN
            nState := 0;
        END_IF

    ELSE
        nState := 0;
END_CASE

nSystemState := nState;
END_FUNCTION_BLOCK
