FUNCTION_BLOCK FB_SiC_InverterDyno
VAR_INPUT
    (* Main hardware signals and parameters for SiC operation *)
    bEnableDyno           : BOOL;      (* Main system enable for the SiC dynamometer *)
    bEmergencyStop        : BOOL;      (* Hardware safety loop OK signal (True = Safe) *)
    bDesaturationFault    : BOOL;      (* Ultra-fast hardware desaturation detection from SiC gate drivers *)
    rDCLinkVoltage        : REAL;      (* High voltage DC link measurement in Volts (e.g. 800V) *)
    rMotorSpeedRPM        : REAL;      (* High precision resolver/encoder feedback in RPM *)
    rTorqueCommand        : REAL;      (* Desired load torque from test cell controller (Nm) *)
    rIGBTTempPhaseU       : REAL;      (* Phase U SiC module temperature in deg C *)
    rIGBTTempPhaseV       : REAL;      (* Phase V SiC module temperature in deg C *)
    rIGBTTempPhaseW       : REAL;      (* Phase W SiC module temperature in deg C *)
END_VAR

VAR_OUTPUT
    (* Hardware control outputs and system statuses *)
    bSystemReady          : BOOL;      (* Dynamometer inverter ready to receive PWM signals *)
    bPWMEnable            : BOOL;      (* Output signal to enable DSP for 20kHz SVPWM firing *)
    rActiveTorqueLimit    : REAL;      (* Derated torque limit passed to FOC algorithm (Nm) *)
    bFaultActive          : BOOL;      (* General fault flag active *)
    iFaultCode            : INT;       (* Encoded fault ID for SCADA/HMI diagnostics *)
    bSafeTorqueOff        : BOOL;      (* STO trigger for physical hardware isolation *)
END_VAR

VAR
    (* Internal state variables, timers and algorithmic memory *)
    iStateMachine         : INT := 0;  (* Internal State Machine for operation sequence *)
    tPrechargeTimer       : TON;       (* DC Link pre-charge timeout monitor *)
    tFaultResetPulse      : TON;       (* Debounce for fault reset *)
    rMaxTempAllowed       : REAL := 150.0; (* Thermal limit for SiC MOSFET junction *)
    rMaxVoltageAllowed    : REAL := 950.0; (* Overvoltage threshold for DC Link *)
    bOvertemp             : BOOL;      (* Internal flag for overtemperature *)
    bOvervoltage          : BOOL;      (* Internal flag for overvoltage on DC link *)
    rFilteredSpeed        : REAL := 0.0; (* Filtered resolver output *)
    rPrevSpeed            : REAL := 0.0; (* Previous sample for filter *)
    rAlpha                : REAL := 0.1; (* Low-pass filter coefficient for speed feedback *)
END_VAR

(* ========================================================================= *)
(* MAIN CONTROL LOGIC - NEXT-GEN SiC INVERTER DYNAMOMETER *)
(* ========================================================================= *)

(* --- 1. Critical Hardware Safety Layer --- *)
(* Immediate reaction to physical faults, overriding all state logic. *)
IF NOT bEmergencyStop OR bDesaturationFault THEN
    bSystemReady       := FALSE;
    bPWMEnable         := FALSE;
    bSafeTorqueOff     := TRUE;
    bFaultActive       := TRUE;

    IF NOT bEmergencyStop THEN
        iFaultCode := 1001; (* E-Stop Pressed or Safety Loop Open *)
    ELSIF bDesaturationFault THEN
        iFaultCode := 1002; (* SiC Short Circuit / Desaturation Detected - Microsecond Response *)
    END_IF;

    iStateMachine := 999; (* Force to fault state *)
    RETURN; (* Bypass all further control processing *)
END_IF;

(* --- 2. Advanced Sensor Filtering & Diagnostics --- *)
(* Low-pass filter for resolver noise common in high-frequency PWM environments *)
rFilteredSpeed := (rAlpha * rMotorSpeedRPM) + ((1.0 - rAlpha) * rPrevSpeed);
rPrevSpeed := rFilteredSpeed;

(* Thermal monitoring across all phases *)
bOvertemp := (rIGBTTempPhaseU > rMaxTempAllowed) OR 
             (rIGBTTempPhaseV > rMaxTempAllowed) OR 
             (rIGBTTempPhaseW > rMaxTempAllowed);

(* DC Link Overvoltage monitoring *)
bOvervoltage := (rDCLinkVoltage > rMaxVoltageAllowed);

IF bOvertemp OR bOvervoltage THEN
    bSystemReady       := FALSE;
    bPWMEnable         := FALSE;
    bFaultActive       := TRUE;
    bSafeTorqueOff     := FALSE; (* Soft fault, STO not immediately required unless catastrophic *)

    IF bOvertemp THEN
        iFaultCode := 2001; (* Thermal Derating Exceeded *)
    ELSE
        iFaultCode := 2002; (* DC Link Overvoltage Trip *)
    END_IF;

    iStateMachine := 999;
END_IF;

(* --- 3. Dynamometer Inverter State Machine --- *)
CASE iStateMachine OF

    0: (* STATE: OFF / IDLE *)
        bSystemReady       := FALSE;
        bPWMEnable         := FALSE;
        bSafeTorqueOff     := FALSE;
        bFaultActive       := FALSE;
        iFaultCode         := 0;
        rActiveTorqueLimit := 0.0;

        IF bEnableDyno THEN
            iStateMachine := 10; (* Transition to Pre-charge phase *)
        END_IF;

    10: (* STATE: DC LINK PRE-CHARGE *)
        (* Wait for DC link to stabilize at nominal 800V level *)
        tPrechargeTimer(IN := TRUE, PT := T#3S);

        IF rDCLinkVoltage >= 780.0 THEN
            tPrechargeTimer(IN := FALSE);
            iStateMachine := 20; (* Ready to close main contactors and run *)
        ELSIF tPrechargeTimer.Q THEN
            (* Timeout waiting for DC Link *)
            tPrechargeTimer(IN := FALSE);
            iFaultCode := 3001; (* Pre-charge Timeout Fault *)
            bFaultActive := TRUE;
            iStateMachine := 999;
        END_IF;

    20: (* STATE: RUNNING / ACTIVE FOC CONTROL *)
        bSystemReady := TRUE;
        bPWMEnable   := TRUE;

        (* Thermal Derating Profile implementation *)
        (* If temperatures are approaching limit, scale back torque limit dynamically *)
        IF (rIGBTTempPhaseU > 130.0) OR (rIGBTTempPhaseV > 130.0) OR (rIGBTTempPhaseW > 130.0) THEN
            rActiveTorqueLimit := rTorqueCommand * 0.5; (* 50% Derate to preserve silicon *)
        ELSE
            rActiveTorqueLimit := rTorqueCommand; (* Full performance allowed *)
        END_IF;

        IF NOT bEnableDyno THEN
            iStateMachine := 30; (* Normal Ramp-Down Sequence *)
        END_IF;

    30: (* STATE: SHUTDOWN SEQUENCE *)
        bPWMEnable := FALSE; (* Stop SVPWM firing *)
        rActiveTorqueLimit := 0.0;

        (* Wait for zero speed before dropping ready state *)
        IF ABS(rFilteredSpeed) < 5.0 THEN
            bSystemReady := FALSE;
            iStateMachine := 0;
        END_IF;

    999: (* STATE: FAULTED *)
        bSystemReady := FALSE;
        bPWMEnable   := FALSE;
        rActiveTorqueLimit := 0.0;

        (* Wait for operator fault reset (toggle enable off then on while safe) *)
        IF NOT bEnableDyno AND NOT bOvertemp AND NOT bOvervoltage AND bEmergencyStop AND NOT bDesaturationFault THEN
            iStateMachine := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
