FUNCTION_BLOCK FB_EUV_DropletGenerator
(* 
   Advanced Semiconductor Extreme Ultraviolet (EUV) Droplet Generator
   Controls high-frequency (50kHz) liquid tin droplet piezo-dispensing, 
   sub-micron spatial phase lock loop targeting, and tin catch/recycle 
   thermal capillary control.
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System enable signal from master controller *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (TRUE = Safe) *)
    rTinVesselTemp          : REAL;     (* Measured tin vessel temperature in deg C *)
    rDropletPhaseError      : REAL;     (* Phase error in nm from optical sensor target *)
    rPiezoTargetFreq        : REAL;     (* Target piezo drive frequency in kHz (nominally 50.0) *)
    rCatchVesselLevel       : REAL;     (* Tin level in catch vessel (%) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Droplet generator ready for laser pulse synchronization *)
    rPiezoDriveVoltage      : REAL;     (* Control signal to piezo actuator (0-10V -> 0-200V amp) *)
    bLaserTriggerSync       : BOOL;     (* Precision trigger out to CO2 drive laser *)
    bThermalAlarm           : BOOL;     (* Tin temperature out of safe operating bounds *)
    iOperatingState         : INT;      (* Current state machine step (0: Idle, 10: Warmup, 20: Run) *)
    rDropletDispenseRate    : REAL;     (* Calculated actual droplets per second *)
END_VAR
VAR
    iState                  : INT := 0; 
    tWarmupTimer            : TON;
    tDropletSyncTimer       : TON;

    (* Phase Lock Loop Variables *)
    rIntegralError          : REAL := 0.0;
    rDerivativeError        : REAL := 0.0;
    rLastError              : REAL := 0.0;
    rKp                     : REAL := 0.045;
    rKi                     : REAL := 0.001;
    rKd                     : REAL := 0.005;

    (* Temperature Constants *)
    rTinMeltingPoint        : REAL := 231.9; (* Celsius *)
    rTinOperatingTemp       : REAL := 280.0; (* Celsius *)
    rTempTolerance          : REAL := 2.5;   (* Celsius *)

    (* Output bounds *)
    rMaxDriveVoltage        : REAL := 8.5;   (* V *)
    rMinDriveVoltage        : REAL := 1.2;   (* V *)
END_VAR

(* === MAIN LOGIC === *)

(* Safety and interlock monitoring *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bLaserTriggerSync := FALSE;
    rPiezoDriveVoltage := 0.0;
    bThermalAlarm := TRUE;
    iState := 999; (* Fault state *)
    iOperatingState := iState;
    RETURN;
END_IF;

(* Temperature bound checking *)
IF (rTinVesselTemp > (rTinOperatingTemp + 20.0)) OR (rTinVesselTemp < 50.0 AND iState > 0) THEN
    bThermalAlarm := TRUE;
ELSE
    bThermalAlarm := FALSE;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rPiezoDriveVoltage := 0.0;
        bLaserTriggerSync := FALSE;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* WARMUP - MELTING TIN *)
        (* Wait for tin to reach operating temperature *)
        tWarmupTimer(IN := (rTinVesselTemp >= rTinOperatingTemp - rTempTolerance), PT := T#30S);
        IF tWarmupTimer.Q THEN
            tWarmupTimer(IN := FALSE);
            iState := 20;
        END_IF;
        IF NOT bEnable THEN
            iState := 0;
            tWarmupTimer(IN := FALSE);
        END_IF;

    20: (* START DISPENSING / RAMP UP *)
        (* Initial feed-forward voltage for droplet ejection based on target frequency *)
        rPiezoDriveVoltage := 3.5 + (rPiezoTargetFreq - 50.0) * 0.1;

        tDropletSyncTimer(IN := TRUE, PT := T#2S);
        IF tDropletSyncTimer.Q THEN
            tDropletSyncTimer(IN := FALSE);
            rIntegralError := 0.0;
            rLastError := rDropletPhaseError;
            iState := 30;
        END_IF;
        IF NOT bEnable THEN iState := 0; END_IF;

    30: (* CLOSED LOOP PHASE-LOCKED OPERATION *)
        bSystemReady := TRUE;

        (* Spatial Phase Lock Loop (PLL) targeting logic - PID formulation *)
        rIntegralError := rIntegralError + rDropletPhaseError;

        (* Anti-windup for integral component *)
        IF rIntegralError > 100.0 THEN rIntegralError := 100.0; END_IF;
        IF rIntegralError < -100.0 THEN rIntegralError := -100.0; END_IF;

        rDerivativeError := rDropletPhaseError - rLastError;

        (* Control Output Calculation (Voltage adjustment) *)
        rPiezoDriveVoltage := rPiezoDriveVoltage + 
                              (rKp * rDropletPhaseError) + 
                              (rKi * rIntegralError) + 
                              (rKd * rDerivativeError);

        (* Clamp output bounds *)
        IF rPiezoDriveVoltage > rMaxDriveVoltage THEN
            rPiezoDriveVoltage := rMaxDriveVoltage;
        ELSIF rPiezoDriveVoltage < rMinDriveVoltage THEN
            rPiezoDriveVoltage := rMinDriveVoltage;
        END_IF;

        rLastError := rDropletPhaseError;
        rDropletDispenseRate := rPiezoTargetFreq * 1000.0; (* Synthesized monitor value *)

        (* Synchronize laser trigger if phase error is within sub-micron acceptable window (< 0.5nm) *)
        IF ABS(rDropletPhaseError) < 0.5 THEN
            bLaserTriggerSync := TRUE;
        ELSE
            bLaserTriggerSync := FALSE;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
            bSystemReady := FALSE;
            bLaserTriggerSync := FALSE;
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bLaserTriggerSync := FALSE;
        rPiezoDriveVoltage := 0.0;
        IF bEmergencyStop AND bEnable = FALSE THEN
            (* Reset fault if safely disabled and estop cleared *)
            iState := 0;
        END_IF;

END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
