FUNCTION_BLOCK FB_PaintBooth_Ultimate
TITLE = 'Ultimate Paint Booth with HIL and Self-Test'
VERSION : 1.4

VAR_INPUT
    rExhaustFlow : REAL;
    rExhaustFlowRef : REAL; // Reference for drift
    rPaintTemp : REAL;
    rPaintTempRef : REAL;
    bHIL_SyncReq : BOOL;
    bStartSelfTest : BOOL;
