    rFlowDrift := ABS(rExhaustFlow - rExhaustFlowRef);
    rTempDrift := ABS(rPaintTemp - rPaintTempRef);
    IF (rFlowDrift > 5.0) OR (rTempDrift > 2.0) THEN
        bSensorDriftAlarm := TRUE;
