FUNCTION_BLOCK FB_HPDC_Advanced_Control
VAR_INPUT
    bStartCycle : BOOL; // Initiate casting cycle
    bEmergencyStop : BOOL; // E-Stop condition
    bAckFault : BOOL; // Acknowledge fault
    rMoltenMetalTemp : REAL; // Molten Aluminum Temperature (deg C)
    rDieCavityTempZone1 : REAL; // Die cavity temperature zone 1 (deg C)
    rDieCavityTempZone2 : REAL; // Die cavity temperature zone 2 (deg C)
    rBiscuitTemp : REAL; // Biscuit area temperature (deg C)
    rVacuumLevel : REAL; // Current vacuum pressure (mbar)
    rPlungerPosition : REAL; // Current position of the shot plunger (mm)
    rPlungerVelocity_Actual : REAL; // Current plunger velocity (m/s)
    rPlungerPressure_Actual : REAL; // Current plunger pressure (bar)
END_VAR

VAR_OUTPUT
    bVacuumValve : BOOL; // Open vacuum valve
    bShotValveFast : BOOL; // Fast shot valve control
    bShotValveIntensification : BOOL; // Intensifier valve control
    rPlungerVelocity_Ref : REAL; // Plunger velocity reference (m/s)
    rPlungerPressure_Ref : REAL; // Plunger pressure reference (bar)
    bCoolingWaterBiscuit_V1 : BOOL; // Biscuit cooling water cascade valve 1
    bCoolingWaterBiscuit_V2 : BOOL; // Biscuit cooling water cascade valve 2
    bCoolingWaterDieZone1 : BOOL; // Die cooling water cascade zone 1
    bCoolingWaterDieZone2 : BOOL; // Die cooling water cascade zone 2
    eState : INT; // Current state of the machine
    bCycleComplete : BOOL; // Casting cycle finished
    bFaultActive : BOOL; // Fault active
    sFaultMessage : STRING[80]; // Fault description
END_VAR

VAR
    iStep : INT := 0; // State machine step
    tTimerVacuum : TON; // Timer for vacuum phase timeout
    tTimerIntensify : TON; // Timer for intensification hold
    tTimerCooling : TON; // Timer for cooling phase

    // Process parameters
    rTargetVacuum : REAL := 45.0; // Target vacuum in mbar
    rVacuumTimeout : TIME := T#5S;

    // Plunger profiling positions
    rPosPhase1_End : REAL := 220.0; // mm (End of slow shot)
    rPosPhase2_End : REAL := 460.0; // mm (End of fast shot / filling)
    rPosPhase3_End : REAL := 485.0; // mm (End of squeeze / biscuit thickness)

    // Plunger profiling velocities
    rVelPhase1 : REAL := 0.25; // Slow shot m/s (minimize air entrapment)
    rVelPhase2 : REAL := 5.2; // Fast shot m/s (rapid cavity fill before freezing)
    rPressIntensify : REAL := 950.0; // bar (Squeeze pressure to feed shrinkage porosity)

    // PID / Temperature limits
    rMaxDieTemp : REAL := 250.0; // Maximum allowed die temperature before cooling
    rBiscuitCoolingTarget : REAL := 150.0; // Target temperature for biscuit ejection
END_VAR

// ---------------------------------------------------------
// E-Stop and Fault Handling
// ---------------------------------------------------------
IF bEmergencyStop THEN
    bVacuumValve := FALSE;
    bShotValveFast := FALSE;
    bShotValveIntensification := FALSE;
    bCoolingWaterBiscuit_V1 := FALSE;
    bCoolingWaterBiscuit_V2 := FALSE;
    bCoolingWaterDieZone1 := FALSE;
    bCoolingWaterDieZone2 := FALSE;
    rPlungerVelocity_Ref := 0.0;
    rPlungerPressure_Ref := 0.0;
    iStep := 999;
    bFaultActive := TRUE;
    sFaultMessage := 'CRITICAL FAULT: Emergency Stop Activated';
    RETURN;
END_IF;

// ---------------------------------------------------------
// Main State Machine
// ---------------------------------------------------------
CASE iStep OF
    0: // Idle / Ready to start
        bCycleComplete := FALSE;
        eState := 0;
        IF bStartCycle AND NOT bFaultActive THEN
            IF rMoltenMetalTemp < 640.0 THEN
                bFaultActive := TRUE;
                sFaultMessage := 'FAULT: Molten metal temperature too low';
                iStep := 999;
            ELSIF rDieCavityTempZone1 < 120.0 OR rDieCavityTempZone2 < 120.0 THEN
                bFaultActive := TRUE;
                sFaultMessage := 'FAULT: Die temperature below operating threshold';
                iStep := 999;
            ELSE
                iStep := 10;
            END_IF;
        END_IF;

    10: // Vacuum Evacuation
        eState := 10;
        bVacuumValve := TRUE;
        tTimerVacuum(IN:=TRUE, PT:=rVacuumTimeout);

        IF rVacuumLevel <= rTargetVacuum THEN
            tTimerVacuum(IN:=FALSE);
            iStep := 20; // Vacuum achieved, proceed to slow shot
        ELSIF tTimerVacuum.Q THEN
            tTimerVacuum(IN:=FALSE);
            bVacuumValve := FALSE;
            bFaultActive := TRUE;
            sFaultMessage := 'FAULT: Vacuum timeout - target not reached';
            iStep := 999;
        END_IF;

    20: // Phase 1: Slow Shot (Push metal past pour hole, minimize turbulence)
        eState := 20;
        rPlungerVelocity_Ref := rVelPhase1;

        IF rPlungerPosition >= rPosPhase1_End THEN
            iStep := 30; // Proceed to fast shot
        END_IF;

    30: // Phase 2: Fast Shot (Cavity filling)
        eState := 30;
        bShotValveFast := TRUE;
        rPlungerVelocity_Ref := rVelPhase2;

        // Critical: Close vacuum just before metal reaches the chill vent
        IF rPlungerPosition >= (rPosPhase2_End - 20.0) THEN
            bVacuumValve := FALSE; 
        END_IF;

        IF rPlungerPosition >= rPosPhase2_End THEN
            iStep := 40; // Cavity filled, proceed to intensification
        END_IF;

    40: // Phase 3: Intensification (Squeeze out porosity)
        eState := 40;
        bShotValveFast := FALSE;
        bShotValveIntensification := TRUE;

        // Switch control mode from velocity to pressure
        rPlungerVelocity_Ref := 0.0;
        rPlungerPressure_Ref := rPressIntensify;

        tTimerIntensify(IN:=TRUE, PT:=T#3S); // Hold intensification pressure
        IF tTimerIntensify.Q THEN
            tTimerIntensify(IN:=FALSE);
            iStep := 50;
        END_IF;

    50: // Cooling cascades (Solidification)
        eState := 50;
        bShotValveIntensification := FALSE;
        rPlungerPressure_Ref := 0.0; // Relief pressure

        // Dynamic die cooling based on zone temperatures
        bCoolingWaterDieZone1 := (rDieCavityTempZone1 > rMaxDieTemp);
        bCoolingWaterDieZone2 := (rDieCavityTempZone2 > rMaxDieTemp);

        // Biscuit cooling cascade (Stage 1 and 2)
        bCoolingWaterBiscuit_V1 := TRUE;
        IF rBiscuitTemp > (rBiscuitCoolingTarget + 50.0) THEN
            bCoolingWaterBiscuit_V2 := TRUE; // Maximum cooling
        ELSE
            bCoolingWaterBiscuit_V2 := FALSE; // Modulated cooling
        END_IF;

        tTimerCooling(IN:=TRUE, PT:=T#12S); // Minimum cooling duration
        IF tTimerCooling.Q AND rBiscuitTemp <= rBiscuitCoolingTarget THEN
            tTimerCooling(IN:=FALSE);
            bCoolingWaterBiscuit_V1 := FALSE;
            bCoolingWaterBiscuit_V2 := FALSE;
            bCoolingWaterDieZone1 := FALSE;
            bCoolingWaterDieZone2 := FALSE;
            iStep := 60;
        END_IF;

    60: // Cycle Complete
        eState := 60;
        bCycleComplete := TRUE;
        IF NOT bStartCycle THEN
            iStep := 0; // Wait for next cycle
        END_IF;

    999: // Fault state
        eState := 999;
        bVacuumValve := FALSE;
        bShotValveFast := FALSE;
        bShotValveIntensification := FALSE;
        bCoolingWaterBiscuit_V1 := FALSE;
        bCoolingWaterBiscuit_V2 := FALSE;
        bCoolingWaterDieZone1 := FALSE;
        bCoolingWaterDieZone2 := FALSE;
        rPlungerVelocity_Ref := 0.0;
        rPlungerPressure_Ref := 0.0;

        IF bAckFault AND NOT bEmergencyStop THEN
            bFaultActive := FALSE;
            sFaultMessage := '';
            iStep := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
