FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable                 : BOOL;   (* Enable coating line process *)
    bEmergencyStop          : BOOL;   (* E-Stop active low *)
    rSetSlurryViscosity     : REAL;   (* Target slurry viscosity [cP] *)
    rSetCoatingThickness    : REAL;   (* Target wet coating thickness [um] *)
    rSetOvenTempZ1          : REAL;   (* Target oven zone 1 temp [C] *)
    rSetOvenTempZ2          : REAL;   (* Target oven zone 2 temp [C] *)
    rSetOvenTempZ3          : REAL;   (* Target oven zone 3 temp [C] *)
    rSetLineSpeed           : REAL;   (* Target line speed [m/min] *)

    rActSlurryViscosity     : REAL;   (* Actual measured viscosity [cP] *)
    rActCoatingThickness    : REAL;   (* Actual thickness via beta gauge [um] *)
    rActOvenTempZ1          : REAL;   (* Actual oven zone 1 temp [C] *)
    rActOvenTempZ2          : REAL;   (* Actual oven zone 2 temp [C] *)
    rActOvenTempZ3          : REAL;   (* Actual oven zone 3 temp [C] *)
    rActLineSpeed           : REAL;   (* Actual measured web speed [m/min] *)

    rSlurryTankLevel        : REAL;   (* Slurry tank fill level [%] *)
    bBetaGaugeHealthy       : BOOL;   (* Beta gauge status OK *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;   (* All subsystems primed and ready *)
    bCoatingActive          : BOOL;   (* Active coating process running *)
    bAlarmActive            : BOOL;   (* Critical alarm condition *)

    rPumpSpeedCmd           : REAL;   (* Output to slurry feed pump [%] *)
    rDieGapCmd              : REAL;   (* Output to slot die gap actuator [um] *)
    rHeaterPowerZ1          : REAL;   (* Output to Zone 1 SSR [%] *)
    rHeaterPowerZ2          : REAL;   (* Output to Zone 2 SSR [%] *)
    rHeaterPowerZ3          : REAL;   (* Output to Zone 3 SSR [%] *)
    rNipRollerSpeedCmd      : REAL;   (* Output to main web drive [m/min] *)

    iErrorCode              : INT;    (* Specific fault code *)
END_VAR

VAR
    (* Internal PID variables for Viscosity Control (Pump Speed) *)
    rViscError              : REAL;
    rViscIntegral           : REAL;
    rViscDerivative         : REAL;
    rViscLastErr            : REAL;
    rKpVisc                 : REAL := 1.5;
    rKiVisc                 : REAL := 0.2;
    rKdVisc                 : REAL := 0.05;

    (* Internal PID variables for Thickness Control (Die Gap) *)
    rThickError             : REAL;
    rThickIntegral          : REAL;
    rThickDerivative        : REAL;
    rThickLastErr           : REAL;
    rKpThick                : REAL := 2.0;
    rKiThick                : REAL := 0.5;
    rKdThick                : REAL := 0.1;

    (* Internal PID variables for Oven Zone 1 *)
    rZ1Error                : REAL;
    rZ1Integral             : REAL;
    rZ1Derivative           : REAL;
    rZ1LastErr              : REAL;
    rKpZ1                   : REAL := 5.0;
    rKiZ1                   : REAL := 0.1;
    rKdZ1                   : REAL := 0.5;

    (* State Machine *)
    iState                  : INT := 0; 
    (* 0: INIT, 1: WARMUP, 2: READY, 3: COATING, 4: FAULT *)
END_VAR

(* E-Stop and Safety Check *)
IF NOT bEmergencyStop THEN
    iState := 4;
    iErrorCode := 999; (* E-STOP TRIGGERED *)
END_IF

(* State Machine Execution *)
CASE iState OF
    0: (* INIT *)
        bSystemReady := FALSE;
        bCoatingActive := FALSE;
        bAlarmActive := FALSE;
        rPumpSpeedCmd := 0.0;
        rDieGapCmd := rSetCoatingThickness; 
        rHeaterPowerZ1 := 0.0;
        rHeaterPowerZ2 := 0.0;
        rHeaterPowerZ3 := 0.0;
        rNipRollerSpeedCmd := 0.0;

        IF bEnable AND bEmergencyStop THEN
            iState := 1;
        END_IF

    1: (* WARMUP - Heat Ovens *)
        (* Simple P-control for warm-up phase to avoid integral windup *)
        rZ1Error := rSetOvenTempZ1 - rActOvenTempZ1;
        rHeaterPowerZ1 := rZ1Error * rKpZ1;

        IF rHeaterPowerZ1 > 100.0 THEN rHeaterPowerZ1 := 100.0; END_IF
        IF rHeaterPowerZ1 < 0.0 THEN rHeaterPowerZ1 := 0.0; END_IF

        (* Evaluate readiness *)
        IF (ABS(rZ1Error) < 2.0) AND (rSlurryTankLevel > 20.0) THEN
            iState := 2;
        END_IF

    2: (* READY *)
        bSystemReady := TRUE;
        bCoatingActive := FALSE;

        IF bEnable AND bBetaGaugeHealthy AND rActLineSpeed > 0.1 THEN
            iState := 3;
            (* Initialize PID histories *)
            rViscIntegral := 0.0;
            rThickIntegral := 0.0;
            rZ1Integral := 0.0;
        END_IF

    3: (* COATING ACTIVE *)
        bSystemReady := TRUE;
        bCoatingActive := TRUE;

        (* 1. Viscosity Control via Pump Speed *)
        rViscError := rSetSlurryViscosity - rActSlurryViscosity;
        rViscIntegral := rViscIntegral + rViscError;
        rViscDerivative := rViscError - rViscLastErr;
        rPumpSpeedCmd := (rKpVisc * rViscError) + (rKiVisc * rViscIntegral) + (rKdVisc * rViscDerivative);
        rViscLastErr := rViscError;

        (* Clamp Pump Speed *)
        IF rPumpSpeedCmd > 100.0 THEN rPumpSpeedCmd := 100.0; END_IF
        IF rPumpSpeedCmd < 0.0 THEN rPumpSpeedCmd := 0.0; END_IF

        (* 2. Thickness Control via Die Gap Adjust *)
        rThickError := rSetCoatingThickness - rActCoatingThickness;
        rThickIntegral := rThickIntegral + rThickError;
        rThickDerivative := rThickError - rThickLastErr;
        rDieGapCmd := rSetCoatingThickness + ((rKpThick * rThickError) + (rKiThick * rThickIntegral) + (rKdThick * rThickDerivative));
        rThickLastErr := rThickError;

        (* Clamp Die Gap *)
        IF rDieGapCmd > (rSetCoatingThickness * 1.5) THEN rDieGapCmd := rSetCoatingThickness * 1.5; END_IF
        IF rDieGapCmd < (rSetCoatingThickness * 0.5) THEN rDieGapCmd := rSetCoatingThickness * 0.5; END_IF

        (* 3. Oven Zone 1 PID Control *)
        rZ1Error := rSetOvenTempZ1 - rActOvenTempZ1;
        rZ1Integral := rZ1Integral + rZ1Error;
        rZ1Derivative := rZ1Error - rZ1LastErr;
        rHeaterPowerZ1 := (rKpZ1 * rZ1Error) + (rKiZ1 * rZ1Integral) + (rKdZ1 * rZ1Derivative);
        rZ1LastErr := rZ1Error;

        IF rHeaterPowerZ1 > 100.0 THEN rHeaterPowerZ1 := 100.0; END_IF
        IF rHeaterPowerZ1 < 0.0 THEN rHeaterPowerZ1 := 0.0; END_IF

        (* Safety check during coating *)
        IF NOT bBetaGaugeHealthy THEN
            iErrorCode := 101; (* Sensor failure *)
            iState := 4;
        END_IF

    4: (* FAULT STATE *)
        bSystemReady := FALSE;
        bCoatingActive := FALSE;
        bAlarmActive := TRUE;
        rPumpSpeedCmd := 0.0;
        rHeaterPowerZ1 := 0.0;
        rHeaterPowerZ2 := 0.0;
        rHeaterPowerZ3 := 0.0;
        rNipRollerSpeedCmd := 0.0;

        IF bEmergencyStop AND bEnable = FALSE THEN
            (* Reset Fault if E-Stop clear and Enable dropped *)
            iErrorCode := 0;
            bAlarmActive := FALSE;
            iState := 0;
        END_IF
END_CASE
END_FUNCTION_BLOCK\n```
