FUNCTION_BLOCK FB_LNA_Cryocooler_Controller
(*
    Deep-Space Antenna Array Cryogenic Low-Noise Amplifier (LNA)
    4-Kelvin Gifford-McMahon cryocooler staging, RF insertion loss thermal calibration,
    and vacuum chamber getter-pump outgassing tracking.
*)
VAR_INPUT
    bSystemEnable           : BOOL;     (* Main system enable interlock *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (True = OK) *)
    rTempStage1_K           : REAL;     (* 1st stage temp measurement in Kelvin *)
    rTempStage2_K           : REAL;     (* 2nd stage temp measurement in Kelvin *)
    rVacuumPressure_Torr    : REAL;     (* Vacuum chamber pressure in Torr *)
    rRF_InsertionLoss_dB    : REAL;     (* RF insertion loss tracking in dB *)
    bGetterPumpStatus       : BOOL;     (* Getter pump operational status *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Cryocooler at nominal 4K operating temp *)
    rCompressorDrive_Hz     : REAL;     (* Helium compressor drive frequency (Hz) *)
    rHeaterPower_W          : REAL;     (* Trim heater power for thermal stability *)
    bOutgassingAlarm        : BOOL;     (* High vacuum pressure indicating outgassing *)
    bThermalFault           : BOOL;     (* Critical thermal deviation alarm *)
END_VAR
VAR
    iOpState                : INT := 0; (* Internal state machine *)
    tStagingTimer           : TON;      (* Delay timer for thermal staging *)
    rTargetTempStage2_K     : REAL := 4.2; (* Target LNA operating temperature *)
    rMaxVacuum_Torr         : REAL := 1.0E-6; (* Maximum allowable pressure *)
    rErrorStage2            : REAL;
    rIntegralTerm           : REAL := 0.0;
    rKp                     : REAL := 5.5;
    rKi                     : REAL := 0.2;
END_VAR

(* === SAFETY & INTERLOCK LOGIC === *)
IF NOT bEmergencyStop OR NOT bSystemEnable THEN
    bSystemReady := FALSE;
    bOutgassingAlarm := FALSE;
    bThermalFault := TRUE;
    rCompressorDrive_Hz := 0.0;
    rHeaterPower_W := 0.0;
    iOpState := 0;
    RETURN;
END_IF;

(* === VACUUM MONITORING === *)
IF rVacuumPressure_Torr > rMaxVacuum_Torr THEN
    bOutgassingAlarm := TRUE;
ELSE
    bOutgassingAlarm := FALSE;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iOpState OF
    0: (* INIT - Wait for rough vacuum *)
        bSystemReady := FALSE;
        rCompressorDrive_Hz := 0.0;
        IF rVacuumPressure_Torr < 1.0E-3 AND bGetterPumpStatus THEN
            iOpState := 10;
        END_IF;

    10: (* COOLDOWN PHASE 1 - Stage 1 to 50K *)
        rCompressorDrive_Hz := 60.0; (* Max cooling power *)
        IF rTempStage1_K < 50.0 THEN
            iOpState := 20;
        END_IF;

    20: (* COOLDOWN PHASE 2 - Stage 2 to 4K *)
        rCompressorDrive_Hz := 50.0; 
        IF rTempStage2_K < 4.5 THEN
            tStagingTimer(IN := TRUE, PT := T#10M);
            IF tStagingTimer.Q THEN
                tStagingTimer(IN := FALSE);
                iOpState := 30;
            END_IF;
        ELSE
            tStagingTimer(IN := FALSE);
        END_IF;

    30: (* STEADY STATE PI CONTROL *)
        bSystemReady := TRUE;
        rErrorStage2 := rTargetTempStage2_K - rTempStage2_K;

        (* Anti-windup for integral term *)
        rIntegralTerm := rIntegralTerm + (rErrorStage2 * rKi);
        IF rIntegralTerm > 10.0 THEN rIntegralTerm := 10.0; END_IF;
        IF rIntegralTerm < 0.0 THEN rIntegralTerm := 0.0; END_IF;

        (* Heater control for fine stabilization *)
        rHeaterPower_W := (rErrorStage2 * rKp) + rIntegralTerm;
        IF rHeaterPower_W < 0.0 THEN rHeaterPower_W := 0.0; END_IF;
        IF rHeaterPower_W > 15.0 THEN rHeaterPower_W := 15.0; END_IF;

        (* Maintain steady compressor drive *)
        rCompressorDrive_Hz := 40.0;

        (* Monitor for severe thermal deviations *)
        IF rTempStage2_K > 5.5 THEN
            bThermalFault := TRUE;
            iOpState := 40;
        ELSE
            bThermalFault := FALSE;
        END_IF;

    40: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rCompressorDrive_Hz := 60.0; (* Attempt to recover cooling *)
        IF rTempStage2_K < 4.5 THEN
            iOpState := 30;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
