FUNCTION_BLOCK FB_ContinuousMiner_Profinet
TITLE = 'Continuous Miner with Profinet Diagnostics'
VERSION : '1.2'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    rShearerTargetElevation : REAL;
    rConveyorTargetSpeed : REAL;
    rShearerActualElevation : REAL;
    rConveyorActualSpeed : REAL;
    rHydraulicPressure : REAL;
    bProfinetOK : BOOL; // Profinet network health
    bDriveFault : BOOL; // Drive hardware fault
END_VAR

VAR_OUTPUT
    rShearerLiftCmd : REAL;
    rConveyorSpeedCmd : REAL;
    bSystemRunning : BOOL;
    iErrorCode : INT; // Diagnostic error code (0 = OK)
END_VAR

VAR
    bActive : BOOL := FALSE;
    rMaxSafePressure : REAL := 250.0;
    rElevationError : REAL;
    Kp_Elev : REAL := 0.5;
END_VAR

BEGIN
    // Diagnostic Evaluation
    IF NOT bProfinetOK THEN
        iErrorCode := 1001; // Profinet communication loss
        bActive := FALSE;
    ELSIF rHydraulicPressure > rMaxSafePressure THEN
        iErrorCode := 2001; // Hydraulic overpressure
        bActive := FALSE;
    ELSIF bDriveFault THEN
        iErrorCode := 3001; // Conveyor drive fault
        bActive := FALSE;
    ELSE
        iErrorCode := 0; // System healthy
    END_IF;

    // Start/Stop Logic
    IF iErrorCode = 0 THEN
        IF bStart AND NOT bStop THEN
            bActive := TRUE;
        ELSIF bStop THEN
            bActive := FALSE;
        END_IF;
    END_IF;

    bSystemRunning := bActive;

    IF bActive THEN
        rElevationError := rShearerTargetElevation - rShearerActualElevation;
        rShearerLiftCmd := rElevationError * Kp_Elev;

        IF rShearerLiftCmd > 100.0 THEN rShearerLiftCmd := 100.0; END_IF;
        IF rShearerLiftCmd < -100.0 THEN rShearerLiftCmd := -100.0; END_IF;

        rConveyorSpeedCmd := rConveyorTargetSpeed;
    ELSE
        rShearerLiftCmd := 0.0;
        rConveyorSpeedCmd := 0.0;
    END_IF;

END_FUNCTION_BLOCK
