// ==============================================================================
Fault_Code := 0;
Sys_Fault := FALSE;

// Check E-Stop
IF NOT E_Stop THEN
    Fault_Code.0 := TRUE;
    Sys_Fault := TRUE;
END_IF;

// Check Pump Faults
IF Turbo_Fault THEN
    Fault_Code.1 := TRUE;
    Sys_Fault := TRUE;
END_IF;

IF Forepump_Fault THEN
    Fault_Code.2 := TRUE;
    Sys_Fault := TRUE;
