FUNCTION_BLOCK FB_mRNA_LNP_Encapsulation
VAR_INPUT
    (* Core Process Enable & Safety Commands *)
    bSystemEnable            : BOOL;     (* Main sequence enable command *)
    bAsepticSafetyInterlock  : BOOL;     (* Overall isolator and manifold safety status (TRUE = OK) *)
    bEStop                   : BOOL;     (* Hardwired Emergency Stop input (TRUE = OK) *)
    bFilterIntegrityOK       : BOOL;     (* Pre-use post-sterilization filter integrity status *)

    (* Microfluidic Jet Mixing - Flow Rate Setpoints & Feedbacks *)
    rSetpointAqueous_mLpm    : REAL;     (* mRNA aqueous phase setpoint [mL/min] *)
    rSetpointLipid_mLpm      : REAL;     (* Lipid ethanol phase setpoint [mL/min] *)
    rActFlowAqueous_mLpm     : REAL;     (* Measured flow rate - aqueous [mL/min] *)
    rActFlowLipid_mLpm       : REAL;     (* Measured flow rate - lipid [mL/min] *)

    (* Tangential Flow Filtration (TFF) & System Pressures *)
    rTransmembranePress_psi  : REAL;     (* Actual TMP calculated across TFF [psi] *)
    rManifoldPressure_psi    : REAL;     (* Manifold pressure post-mixing [psi] *)
END_VAR

VAR_OUTPUT
    (* Actuator Control Signals *)
    rPumpCmdAqueous_pct      : REAL;     (* Command to Aqueous syringe/gear pump [0-100%] *)
    rPumpCmdLipid_pct        : REAL;     (* Command to Lipid syringe/gear pump [0-100%] *)
    rTFF_RetentateValve_pct  : REAL;     (* Command to proportional retentate backpressure valve [0-100%] *)

    (* System Status & Alarms *)
    bProcessReady            : BOOL;     (* Sequence initialized and ready for production *)
    bProductionActive        : BOOL;     (* Continuous mixing and TFF encapsulation is active *)
    bCriticalAlarm           : BOOL;     (* Any critical out-of-spec or safety condition *)
    iAlarmCode               : INT;      (* Diagnostics: 0=OK, 1=EStop, 2=FlowDev, 3=Overpress, 4=Integrity *)
END_VAR

VAR
    (* Internal State and Sequential Control *)
    iState                   : INT := 0; 

    (* Timers & Filters for noise rejection and step-timing *)
    tStartupDelay            : TON;
    tAqueousFlowStable       : TON;
    tLipidFlowStable         : TON;

    rFiltAqueousFlow         : REAL := 0.0;
    rFiltLipidFlow           : REAL := 0.0;

    (* Constants & Limits *)
    rFlowTolerance           : REAL := 2.5;  (* +/- 2.5 mL/min tolerance for stable flow *)
    rMaxTMP_psi              : REAL := 30.0; (* Max allowable transmembrane pressure *)
    rMaxManifold_psi         : REAL := 45.0; (* Max allowable mixing manifold pressure *)

    (* PID Error States *)
    rErrorAqueous            : REAL := 0.0;
    rErrorLipid              : REAL := 0.0;
    rIntegralAqueous         : REAL := 0.0;

    (* State Machine Constants *)
    STATE_IDLE               : INT := 0;
    STATE_INIT               : INT := 10;
    STATE_PRIME              : INT := 20;
    STATE_PRODUCTION         : INT := 30;
    STATE_SHUTDOWN           : INT := 99;
END_VAR

(* === ADVANCED mRNA LNP ENCAPSULATION CONTINUOUS MIXING CONTROL LOGIC === *)

(* 1. Safety & Interlock Processing *)
IF NOT bEStop OR NOT bAsepticSafetyInterlock THEN
    (* Immediate hard shutdown on safety compromise *)
    rPumpCmdAqueous_pct := 0.0;
    rPumpCmdLipid_pct := 0.0;
    rTFF_RetentateValve_pct := 100.0; (* Open fully to relieve pressure *)
    bProductionActive := FALSE;
    bProcessReady := FALSE;
    bCriticalAlarm := TRUE;

    IF NOT bEStop THEN
        iAlarmCode := 1;
    ELSE
        iAlarmCode := 9; (* Containment/Aseptic breach *)
    END_IF;

    iState := STATE_IDLE;
    RETURN;
END_IF;

(* 2. Analog Signal Processing & Filtering *)
(* Exponential Moving Average (EMA) filter for flow feedbacks to reject sensor noise *)
rFiltAqueousFlow := rFiltAqueousFlow + 0.1 * (rActFlowAqueous_mLpm - rFiltAqueousFlow);
rFiltLipidFlow := rFiltLipidFlow + 0.1 * (rActFlowLipid_mLpm - rFiltLipidFlow);

(* 3. Process Protection Limit Checks *)
IF rTransmembranePress_psi > rMaxTMP_psi OR rManifoldPressure_psi > rMaxManifold_psi THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 3; (* Overpressure anomaly *)
    iState := STATE_SHUTDOWN;
END_IF;

IF NOT bFilterIntegrityOK AND (iState >= STATE_PRIME) THEN
    bCriticalAlarm := TRUE;
    iAlarmCode := 4; (* Pre-use filter compromised during run *)
    iState := STATE_SHUTDOWN;
END_IF;

(* 4. Main State Machine Sequence *)
CASE iState OF

    0: (* STATE_IDLE *)
        bProcessReady := FALSE;
        bProductionActive := FALSE;
        rPumpCmdAqueous_pct := 0.0;
        rPumpCmdLipid_pct := 0.0;

        IF bSystemEnable AND NOT bCriticalAlarm THEN
            iAlarmCode := 0;
            iState := STATE_INIT;
        END_IF;

    10: (* STATE_INIT *)
        (* Perform system diagnostic checks, establish initial backpressure *)
        rTFF_RetentateValve_pct := 50.0; 
        tStartupDelay(IN := TRUE, PT := T#5S);

        IF tStartupDelay.Q THEN
            tStartupDelay(IN := FALSE);
            bProcessReady := TRUE;
            iState := STATE_PRIME;
        END_IF;

    20: (* STATE_PRIME *)
        (* Prime lines with buffer before introducing API (mRNA) and Lipid *)
        (* Simplified logic: wait for steady state flow setpoints *)
        rPumpCmdAqueous_pct := rSetpointAqueous_mLpm * 0.5; (* Pre-computed feedforward *)
        rPumpCmdLipid_pct := rSetpointLipid_mLpm * 0.5;

        (* Verify flows are within tolerance *)
        rErrorAqueous := ABS(rSetpointAqueous_mLpm - rFiltAqueousFlow);
        rErrorLipid := ABS(rSetpointLipid_mLpm - rFiltLipidFlow);

        tAqueousFlowStable(IN := (rErrorAqueous <= rFlowTolerance), PT := T#3S);
        tLipidFlowStable(IN := (rErrorLipid <= rFlowTolerance), PT := T#3S);

        IF tAqueousFlowStable.Q AND tLipidFlowStable.Q THEN
            tAqueousFlowStable(IN := FALSE);
            tLipidFlowStable(IN := FALSE);
            bProductionActive := TRUE;
            iState := STATE_PRODUCTION;
        END_IF;

    30: (* STATE_PRODUCTION *)
        (* Active LNP continuous microfluidic turbulent mixing *)
        (* Employing simple PI control for pump adjustments (simplified for ST) *)
        rErrorAqueous := rSetpointAqueous_mLpm - rFiltAqueousFlow;
        rIntegralAqueous := rIntegralAqueous + rErrorAqueous * 0.05;

        (* Calculate Control Action: Feedforward + Proportional + Integral *)
        rPumpCmdAqueous_pct := (rSetpointAqueous_mLpm * 0.5) + (rErrorAqueous * 1.2) + rIntegralAqueous;

        (* Ensure pump commands remain clamped 0-100% *)
        IF rPumpCmdAqueous_pct > 100.0 THEN rPumpCmdAqueous_pct := 100.0; END_IF;
        IF rPumpCmdAqueous_pct < 0.0 THEN rPumpCmdAqueous_pct := 0.0; END_IF;

        (* If system disable is requested, initiate shutdown *)
        IF NOT bSystemEnable THEN
            bProductionActive := FALSE;
            iState := STATE_SHUTDOWN;
        END_IF;

    99: (* STATE_SHUTDOWN *)
        (* Controlled ramp-down and system flush sequence *)
        rPumpCmdAqueous_pct := 0.0;
        rPumpCmdLipid_pct := 0.0;
        rTFF_RetentateValve_pct := 100.0; 

        IF (rFiltAqueousFlow < 1.0) AND (rFiltLipidFlow < 1.0) AND (rManifoldPressure_psi < 5.0) THEN
            bProcessReady := FALSE;
            iState := STATE_IDLE;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
