FUNCTION_BLOCK FB_TBM_CoreController
TITLE = 'Tire Building Machine Core Logic'
VERSION : '1.1'

VAR_INPUT
    bEnable                 : BOOL; // System enable
    bStartCycle             : BOOL; // Start automatic cycle
    bEstop                  : BOOL; // Emergency stop active low

    // Inner Liner Let-Off
    rLoadCellTension        : REAL; // Actual web tension (N)
    rLetOffDiameter         : REAL; // Current roll diameter (mm)
    rLineSpeed              : REAL; // Machine line speed (mm/s)

    // Bead Setter
    rBeadLeftPosition       : REAL; // Left bead setter actual position (mm)
    rBeadRightPosition      : REAL; // Right bead setter actual position (mm)
    bBeadLeftReady          : BOOL;
    bBeadRightReady         : BOOL;

    // Turn-Up Bladder
    rLeftBladderPressure    : REAL; // Actual pressure (Bar)
    rRightBladderPressure   : REAL; // Actual pressure (Bar)
    rLeftBladderVacuum      : REAL; // Actual vacuum (mBar)
    rRightBladderVacuum     : REAL; // Actual vacuum (mBar)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL; // System is ready for operation
    iCurrentState           : INT;  // Current step in state machine

    // Inner Liner Let-Off
    rLetOffBrakeTorque      : REAL; // Output to brake/servo (Nm)

    // Bead Setter
    rBeadLeftTargetPos      : REAL; // Left bead setter target pos (mm)
    rBeadRightTargetPos     : REAL; // Right bead setter target pos (mm)
    bBeadLeftEngage         : BOOL; // Command to engage left bead
    bBeadRightEngage        : BOOL; // Command to engage right bead

    // Turn-Up Bladder
    bLeftBladderInflate     : BOOL; // Valve command
    bRightBladderInflate    : BOOL; // Valve command
    bLeftBladderVacuumOn    : BOOL; // Vacuum command
    bRightBladderVacuumOn   : BOOL; // Vacuum command

    // Faults
    bFaultActive            : BOOL;
    iFaultCode              : INT;
END_VAR

VAR
    // State Machine Constants
    STATE_IDLE              : INT := 0;
    STATE_LET_OFF           : INT := 10;
    STATE_BEAD_SETTING      : INT := 20;
    STATE_TURN_UP           : INT := 30;
    STATE_COMPLETE          : INT := 40;
    STATE_FAULT             : INT := 99;

    // Internal Variables
    rTargetTension          : REAL := 150.0; // Target tension in N
    rTensionError           : REAL;
    rTensionIntegral        : REAL;
    rKpTension              : REAL := 0.5;
    rKiTension              : REAL := 0.01;

    rTargetBeadPosition     : REAL := 450.5; // mm from center

    rTargetTurnupPressure   : REAL := 6.5; // Bar
    rTargetTurnupVacuum     : REAL := -800.0; // mBar

    // Timers
    tStateTimer             : TON;
    tTurnUpDuration         : TIME := T#5S;
END_VAR

// Logic Implementation
IF NOT bEstop THEN
    iCurrentState := STATE_FAULT;
    iFaultCode := 1001; // E-Stop Fault
ELSIF NOT bEnable THEN
    iCurrentState := STATE_IDLE;
    bSystemReady := FALSE;
END_IF;

CASE iCurrentState OF
    STATE_IDLE:
        bSystemReady := TRUE;
        bFaultActive := FALSE;
        iFaultCode := 0;

        // Reset Outputs
        rLetOffBrakeTorque := 0.0;
        bBeadLeftEngage := FALSE;
        bBeadRightEngage := FALSE;
        bLeftBladderInflate := FALSE;
        bRightBladderInflate := FALSE;
        bLeftBladderVacuumOn := TRUE; // Hold vacuum when idle
        bRightBladderVacuumOn := TRUE;

        IF bStartCycle AND bSystemReady THEN
            iCurrentState := STATE_LET_OFF;
        END_IF;

    STATE_LET_OFF:
        // PID Tension Control for Let-Off
        rTensionError := rTargetTension - rLoadCellTension;
        rTensionIntegral := rTensionIntegral + (rTensionError * 0.1); // Assuming 100ms task cycle

        // Anti-windup
        IF rTensionIntegral > 100.0 THEN rTensionIntegral := 100.0; END_IF;
        IF rTensionIntegral < -100.0 THEN rTensionIntegral := -100.0; END_IF;

        // Calculate Brake Torque based on Tension PID and Roll Diameter compensation
        rLetOffBrakeTorque := (rTensionError * rKpTension) + (rTensionIntegral * rKiTension);
        rLetOffBrakeTorque := rLetOffBrakeTorque * (rLetOffDiameter / 1000.0);

        // Prevent negative torque
        IF rLetOffBrakeTorque < 0.0 THEN rLetOffBrakeTorque := 0.0; END_IF;

        // Transition to next state if tension is stable and line speed reached
        IF ABS(rTensionError) < 5.0 AND rLineSpeed > 100.0 THEN
            iCurrentState := STATE_BEAD_SETTING;
        END_IF;

    STATE_BEAD_SETTING:
        // Move bead setters into position
        rBeadLeftTargetPos := rTargetBeadPosition;
        rBeadRightTargetPos := rTargetBeadPosition;

        IF bBeadLeftReady AND bBeadRightReady AND 
           ABS(rBeadLeftPosition - rTargetBeadPosition) < 0.5 AND 
           ABS(rBeadRightPosition - rTargetBeadPosition) < 0.5 THEN

            bBeadLeftEngage := TRUE;
            bBeadRightEngage := TRUE;
            iCurrentState := STATE_TURN_UP;
            tStateTimer(IN := FALSE); // Reset timer
        END_IF;

    STATE_TURN_UP:
        // Turn-up Bladder Sequence
        bLeftBladderVacuumOn := FALSE;
        bRightBladderVacuumOn := FALSE;

        IF rLeftBladderVacuum > -100.0 AND rRightBladderVacuum > -100.0 THEN
            bLeftBladderInflate := TRUE;
            bRightBladderInflate := TRUE;
        END_IF;

        tStateTimer(IN := TRUE, PT := tTurnUpDuration);

        // Check if target pressure reached and duration complete
        IF tStateTimer.Q AND rLeftBladderPressure >= rTargetTurnupPressure AND rRightBladderPressure >= rTargetTurnupPressure THEN
            bLeftBladderInflate := FALSE;
            bRightBladderInflate := FALSE;
            bLeftBladderVacuumOn := TRUE;
            bRightBladderVacuumOn := TRUE;
            iCurrentState := STATE_COMPLETE;
        END_IF;

    STATE_COMPLETE:
        // Reset cycle and wait for next start command
        bBeadLeftEngage := FALSE;
        bBeadRightEngage := FALSE;

        IF NOT bStartCycle THEN
            iCurrentState := STATE_IDLE;
        END_IF;

    STATE_FAULT:
        bFaultActive := TRUE;
        bSystemReady := FALSE;

        // Safe state outputs
        rLetOffBrakeTorque := 0.0;
        bBeadLeftEngage := FALSE;
        bBeadRightEngage := FALSE;
        bLeftBladderInflate := FALSE;
        bRightBladderInflate := FALSE;
        bLeftBladderVacuumOn := TRUE;
        bRightBladderVacuumOn := TRUE;

        // Reset fault if E-stop cleared and enable toggled
        IF bEstop AND NOT bEnable THEN
            iCurrentState := STATE_IDLE;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
```

