FUNCTION_BLOCK FB_JetDyeingControl
VAR_INPUT
    rFabricWeight : REAL; (* Weight of the fabric batch in kg *)
    rTargetLiquorRatio : REAL; (* Desired liquor ratio, typically 1:4 to 1:10 *)
    rMainPumpFlowFeedback : REAL; (* Current flow rate of the main circulation pump in L/min *)
    rVesselTempFeedback : REAL; (* Current temperature in the main dyeing vessel in °C *)
    rNozzlePressureFeedback : REAL; (* Current pressure at the jet nozzle in Bar *)
    rWinchSpeedFeedback : REAL; (* Current speed of the fabric winch in m/min *)
    rDoseTankLevel : REAL; (* Level of the dosing tank in % *)
    bDosingProfileStart : BOOL; (* Command to start thermal dosing profile *)
    rTargetDosingTemp : REAL; (* Target temperature for dosing completion °C *)
    rDosingRateCurve : ARRAY[0..10] OF REAL; (* Non-linear dosing profile curve points *)
END_VAR

VAR_OUTPUT
    rMainPumpSpeedCmd : REAL; (* Command to main pump VFD 0-100% *)
    rWinchSpeedCmd : REAL; (* Command to winch VFD 0-100% *)
    rHeatingValveCmd : REAL; (* Steam heating valve command 0-100% *)
    rCoolingValveCmd : REAL; (* Cooling water valve command 0-100% *)
    rDosingPumpSpeedCmd : REAL; (* Command to dyestuff dosing pump 0-100% *)
    bTangleAlarm : BOOL; (* Fabric tangle detected *)
    bLiquorRatioWarning : BOOL; (* Liquor ratio out of tolerance *)
    rCalculatedLiquorVol : REAL; (* Calculated ideal liquor volume *)
END_VAR

VAR
    rCurrentLiquorVol : REAL; (* Estimated current liquor volume in vessel *)
    rFlowError : REAL;
    rFlowIntegral : REAL;
    rFlowKp : REAL := 0.5;
    rFlowKi : REAL := 0.05;

    rTempError : REAL;
    rTempIntegral : REAL;
    rTempKp : REAL := 2.0;
    rTempKi : REAL := 0.1;

    rExpectedWinchTorque : REAL;
    rActualWinchTorque : REAL; (* Derived from VFD load via comms *)
    iTangleCounter : INT;

    iDosingStep : INT := 0;
    rDosingProgress : REAL := 0.0;

    (* Timers and Triggers *)
    TON_TangleDetect : TON;
    TON_DosingInterval : TON;
END_VAR

(* 1. Liquor Ratio Flow Balancing *)
rCalculatedLiquorVol := rFabricWeight * rTargetLiquorRatio;
(* Assuming we have a sensor or calculation for rCurrentLiquorVol *)
rCurrentLiquorVol := 1500.0; (* Placeholder for actual volume measurement *)

IF ABS(rCurrentLiquorVol - rCalculatedLiquorVol) > (rCalculatedLiquorVol * 0.05) THEN
    bLiquorRatioWarning := TRUE;
ELSE
    bLiquorRatioWarning := FALSE;
END_IF;

(* Flow PI Control for Main Pump based on Nozzle Pressure requirements *)
rFlowError := (rFabricWeight * 1.2) - rMainPumpFlowFeedback; (* Target flow scales with fabric weight *)
rFlowIntegral := rFlowIntegral + (rFlowError * 0.1); (* 100ms cycle assumption *)

IF rFlowIntegral > 50.0 THEN rFlowIntegral := 50.0; END_IF;
IF rFlowIntegral < -50.0 THEN rFlowIntegral := -50.0; END_IF;

rMainPumpSpeedCmd := (rFlowError * rFlowKp) + (rFlowIntegral * rFlowKi);
IF rMainPumpSpeedCmd > 100.0 THEN rMainPumpSpeedCmd := 100.0; END_IF;
IF rMainPumpSpeedCmd < 20.0 THEN rMainPumpSpeedCmd := 20.0; (* Min safe speed *) END_IF;


(* 2. Dynamic Fabric Rope Tangling Detection *)
(* A tangle usually manifests as a sudden drop in winch speed while nozzle pressure spikes *)
IF (rWinchSpeedFeedback < (rWinchSpeedCmd * 0.5)) AND (rNozzlePressureFeedback > 3.0) THEN
    TON_TangleDetect(IN:=TRUE, PT:=T#2S);
ELSE
    TON_TangleDetect(IN:=FALSE, PT:=T#2S);
END_IF;

IF TON_TangleDetect.Q THEN
    bTangleAlarm := TRUE;
    rWinchSpeedCmd := 0.0;
    rMainPumpSpeedCmd := 0.0; (* Stop pump to prevent damage *)
ELSE
    bTangleAlarm := FALSE;
    rWinchSpeedCmd := 80.0; (* Base running speed *)
END_IF;


(* 3. Dyestuff Thermal Dosing Profile *)
(* Dosing rate depends on the temperature curve to ensure even dye exhaustion *)
IF bDosingProfileStart AND NOT bTangleAlarm THEN
    TON_DosingInterval(IN:=NOT TON_DosingInterval.Q, PT:=T#10S);

    IF TON_DosingInterval.Q THEN
        rDosingProgress := (rVesselTempFeedback / rTargetDosingTemp) * 10.0;
        iDosingStep := REAL_TO_INT(rDosingProgress);

        IF iDosingStep >= 0 AND iDosingStep <= 10 THEN
            rDosingPumpSpeedCmd := rDosingRateCurve[iDosingStep];
        ELSE
            rDosingPumpSpeedCmd := 0.0;
        END_IF;
    END_IF;

    (* Temperature Control *)
    rTempError := rTargetDosingTemp - rVesselTempFeedback;
    rTempIntegral := rTempIntegral + (rTempError * 0.1);

    IF rTempError > 0.0 THEN
        rHeatingValveCmd := (rTempError * rTempKp) + (rTempIntegral * rTempKi);
        rCoolingValveCmd := 0.0;
    ELSE
        rCoolingValveCmd := ABS(rTempError) * rTempKp;
        rHeatingValveCmd := 0.0;
    END_IF;
ELSE
    rDosingPumpSpeedCmd := 0.0;
    rHeatingValveCmd := 0.0;
    rCoolingValveCmd := 0.0;
END_IF;

END_FUNCTION_BLOCK
