FUNCTION_BLOCK FB_HVSC_Control
TITLE = 'High-Voltage Synchronous Condenser Controller'
// -----------------------------------------------------------------------------
// Description:
// Comprehensive control for a High-Voltage Synchronous Condenser.
// Includes Grid Reactive Power (MVAR) control, Automatic Voltage Regulation (AVR),
// and Pressurized Hydrogen Cooling System management.
// -----------------------------------------------------------------------------

VAR_INPUT
    bEnable                 : BOOL;   // System Master Enable
    bGridConnected          : BOOL;   // Breaker status (TRUE = Connected)

    // Grid & Electrical Variables
    rGridVoltage_kV         : REAL;   // Measured Grid Voltage [kV]
    rGridVoltageRef_kV      : REAL;   // Reference Grid Voltage [kV]
    rReactivePowerActual_MVAr : REAL; // Measured Reactive Power [MVAr]
    rReactivePowerRef_MVAr  : REAL;   // Reference Reactive Power [MVAr]

    // Hydrogen Cooling Loop Sensors
    rH2Pressure_kPa         : REAL;   // Hydrogen gas pressure [kPa]
    rH2Purity_Pct           : REAL;   // Hydrogen purity percentage [%]
    rStatorCoreTemp_C       : REAL;   // Stator core temperature [deg C]
    rColdGasTemp_C          : REAL;   // Cooling gas inlet temperature [deg C]

    // Limits
    rMaxExcitation_V        : REAL := 250.0; // Max excitation voltage
    rMinExcitation_V        : REAL := 10.0;  // Min excitation voltage
    rH2PressureMin_kPa      : REAL := 300.0; // Minimum safe H2 pressure
    rStatorTempMax_C        : REAL := 120.0; // Max safe stator temp
END_VAR

VAR_OUTPUT
    // Actuators & Setpoints
    rExcitationSetpoint_V   : REAL;   // Command to Exciter [V]
    bStartH2MakeUpValve     : BOOL;   // Open H2 makeup valve
    bStartSealOilPump       : BOOL;   // Start seal oil system
    rCoolingWaterValve_Pct  : REAL;   // Cooling water valve position [0-100%]

    // Alarms & Status
    bSystemReady            : BOOL;
    bAlarmH2PressureLow     : BOOL;
    bAlarmStatorTempHigh    : BOOL;
    bAlarmH2PurityLow       : BOOL;
    bTripCommand            : BOOL;   // Emergency trip to breaker
    iState                  : INT;    // State machine status
END_VAR

VAR
    // Internal state variables
    rVoltageError           : REAL;
    rMVARError              : REAL;
    rAVR_PI_Integral        : REAL;
    rAVR_PI_Prop            : REAL;

    // Constants for PI controller (AVR)
    Kp_AVR                  : REAL := 2.5;
    Ki_AVR                  : REAL := 0.8;
    dt                      : REAL := 0.01; // 10ms cycle

    // Cooling control
    rTempError              : REAL;
    Kp_Cooling              : REAL := 5.0;

    bInit                   : BOOL := FALSE;
END_VAR

// --- Initialization ---
IF NOT bInit THEN
    rExcitationSetpoint_V := 0.0;
    rAVR_PI_Integral := 0.0;
    bTripCommand := FALSE;
    bInit := TRUE;
END_IF;

// --- Safety & Protection Logic ---
bAlarmH2PressureLow := (rH2Pressure_kPa < rH2PressureMin_kPa);
bAlarmH2PurityLow := (rH2Purity_Pct < 95.0);
bAlarmStatorTempHigh := (rStatorCoreTemp_C > rStatorTempMax_C);

IF bAlarmH2PurityLow OR bAlarmStatorTempHigh THEN
    bTripCommand := TRUE;
END_IF;

// Maintain H2 Pressure
IF bAlarmH2PressureLow AND NOT bTripCommand THEN
    bStartH2MakeUpValve := TRUE;
ELSE
    bStartH2MakeUpValve := FALSE;
END_IF;

// Seal Oil Pump must run if H2 pressure is > 50 kPa
bStartSealOilPump := (rH2Pressure_kPa > 50.0);

// --- Cooling Water Valve Control (Proportional) ---
rTempError := rStatorCoreTemp_C - 80.0; // Target temp 80C
IF rTempError > 0.0 THEN
    rCoolingWaterValve_Pct := rTempError * Kp_Cooling;
    IF rCoolingWaterValve_Pct > 100.0 THEN
        rCoolingWaterValve_Pct := 100.0;
    END_IF;
ELSE
    rCoolingWaterValve_Pct := 0.0;
END_IF;

// --- State Machine & AVR Control ---
IF NOT bEnable OR bTripCommand THEN
    iState := 0; // Stopped/Tripped
    rExcitationSetpoint_V := 0.0;
    bSystemReady := FALSE;
    rAVR_PI_Integral := 0.0;
ELSE
    iState := 1; // Running
    bSystemReady := TRUE;

    IF bGridConnected THEN
        iState := 2; // Grid Connected, active regulation

        // Simple PI Controller for Voltage/Reactive Power
        // Outer loop: Reactive Power, Inner loop: Voltage
        rMVARError := rReactivePowerRef_MVAr - rReactivePowerActual_MVAr;

        // Calculate voltage reference offset based on MVAR error (droop/comp)
        rVoltageError := (rGridVoltageRef_kV + (rMVARError * 0.05)) - rGridVoltage_kV;

        rAVR_PI_Prop := Kp_AVR * rVoltageError;
        rAVR_PI_Integral := rAVR_PI_Integral + (Ki_AVR * rVoltageError * dt);

        // Anti-windup
        IF rAVR_PI_Integral > rMaxExcitation_V THEN rAVR_PI_Integral := rMaxExcitation_V; END_IF;
        IF rAVR_PI_Integral < rMinExcitation_V THEN rAVR_PI_Integral := rMinExcitation_V; END_IF;

        rExcitationSetpoint_V := rAVR_PI_Prop + rAVR_PI_Integral;

        // Clamp output
        IF rExcitationSetpoint_V > rMaxExcitation_V THEN rExcitationSetpoint_V := rMaxExcitation_V; END_IF;
        IF rExcitationSetpoint_V < rMinExcitation_V THEN rExcitationSetpoint_V := rMinExcitation_V; END_IF;
    ELSE
        // Idle excitation when disconnected
        rExcitationSetpoint_V := rMinExcitation_V;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
