FUNCTION_BLOCK FB_InkMixingStation
VAR_INPUT
    bStartProcess : BOOL;             (* Command to start the mixing process *)
    bEmergencyStop : BOOL;            (* Emergency stop signal *)
    rTargetViscosity : REAL;          (* Target viscosity in mPa.s *)
    rPigmentWeightTarget : REAL;      (* Target weight of pigment to dose in kg *)
    rSolventWeightTarget : REAL;      (* Target weight of solvent to dose in kg *)
    rBaseInkWeightTarget : REAL;      (* Target weight of base ink in kg *)
    rCurrentViscosity : REAL;         (* Viscosity sensor feedback *)
    rLoadCellWeight : REAL;           (* Main mixing tank load cell reading *)
    rHomogenizerSpeedFeedback : REAL; (* Feedback from homogenizer RPM *)
    rTemperature : REAL;              (* Tank temperature in Celsius *)
END_VAR

VAR_OUTPUT
    bProcessRunning : BOOL;           (* Process is active *)
    bProcessComplete : BOOL;          (* Batch is complete *)
    bError : BOOL;                    (* Fault state *)
    iErrorCode : INT;                 (* Fault code *)
    rPigmentDosingValveCmd : REAL;    (* 0-100% command to pigment valve *)
    rSolventDosingValveCmd : REAL;    (* 0-100% command to solvent valve *)
    rBaseInkPumpCmd : REAL;           (* 0-100% command to base ink pump *)
    rHomogenizerSpeedCmd : REAL;      (* Command to homogenizer drive (RPM) *)
    bAgitatorStart : BOOL;            (* Start command for main agitator *)
END_VAR

VAR
    iState : INT := 0;                (* State machine step *)
    rInitialWeight : REAL;
    rCurrentDosedWeight : REAL;
    tonMixingTimer : TON;
    tonViscosityStable : TON;
    pidViscosityControl : FB_PID;     (* PID controller for viscosity trim *)
    rDosingRate : REAL;
END_VAR

(* 
    Complex control scenario for gravimetric high-viscosity pigment dosing,
    homogenizer shear rates, and solvent viscosity dilution cascades.
*)

IF bEmergencyStop THEN
    iState := 999;
END_IF;

CASE iState OF
    0: (* IDLE *)
        bProcessRunning := FALSE;
        bProcessComplete := FALSE;
        bError := FALSE;
        iErrorCode := 0;
        rPigmentDosingValveCmd := 0.0;
        rSolventDosingValveCmd := 0.0;
        rBaseInkPumpCmd := 0.0;
        rHomogenizerSpeedCmd := 0.0;
        bAgitatorStart := FALSE;

        IF bStartProcess THEN
            rInitialWeight := rLoadCellWeight;
            iState := 10;
            bProcessRunning := TRUE;
        END_IF;

    10: (* DOSE BASE INK *)
        rCurrentDosedWeight := rLoadCellWeight - rInitialWeight;
        IF rCurrentDosedWeight < rBaseInkWeightTarget THEN
            rBaseInkPumpCmd := 80.0; (* Fast fill *)
            IF (rBaseInkWeightTarget - rCurrentDosedWeight) < 5.0 THEN
                rBaseInkPumpCmd := 20.0; (* Dribble feed *)
            END_IF;
        ELSE
            rBaseInkPumpCmd := 0.0;
            rInitialWeight := rLoadCellWeight;
            bAgitatorStart := TRUE;
            iState := 20;
        END_IF;

    20: (* DOSE PIGMENT - High Viscosity Gravimetric *)
        rCurrentDosedWeight := rLoadCellWeight - rInitialWeight;
        IF rCurrentDosedWeight < rPigmentWeightTarget THEN
            (* Non-linear dosing profile based on remaining amount *)
            rDosingRate := (rPigmentWeightTarget - rCurrentDosedWeight) * 10.0;
            IF rDosingRate > 100.0 THEN rDosingRate := 100.0; END_IF;
            IF rDosingRate < 5.0 THEN rDosingRate := 5.0; END_IF;
            rPigmentDosingValveCmd := rDosingRate;
            rHomogenizerSpeedCmd := 1500.0; (* Start high shear during pigment addition *)
        ELSE
            rPigmentDosingValveCmd := 0.0;
            rInitialWeight := rLoadCellWeight;
            iState := 30;
        END_IF;

    30: (* HOMOGENIZATION & SHEAR PHASE *)
        tonMixingTimer(IN := TRUE, PT := T#5M);
        rHomogenizerSpeedCmd := 3000.0; (* Maximum shear *)
        IF tonMixingTimer.Q THEN
            tonMixingTimer(IN := FALSE);
            iState := 40;
        END_IF;

    40: (* SOLVENT DILUTION CASCADE & VISCOSITY CONTROL *)
        rCurrentDosedWeight := rLoadCellWeight - rInitialWeight;

        (* Coarse dilution via gravimetric solvent addition *)
        IF rCurrentDosedWeight < (rSolventWeightTarget * 0.8) THEN
            rSolventDosingValveCmd := 50.0;
        ELSE
            (* Fine viscosity trim using PID loop and in-line viscometer *)
            pidViscosityControl(
                EN := TRUE,
                SP := rTargetViscosity,
                PV := rCurrentViscosity,
                KP := 0.5,
                KI := 0.1,
                KD := 0.0
            );

            (* Only add solvent if viscosity is higher than target *)
            IF rCurrentViscosity > (rTargetViscosity + 50.0) THEN
                rSolventDosingValveCmd := pidViscosityControl.CV;
            ELSE
                rSolventDosingValveCmd := 0.0;
            END_IF;

            tonViscosityStable(IN := (ABS(rCurrentViscosity - rTargetViscosity) < 20.0), PT := T#30S);

            IF tonViscosityStable.Q THEN
                rSolventDosingValveCmd := 0.0;
                iState := 50;
            END_IF;
        END_IF;

        (* Reduce shear to prevent thermal degradation *)
        IF rTemperature > 45.0 THEN
            rHomogenizerSpeedCmd := 1000.0;
        ELSE
            rHomogenizerSpeedCmd := 2000.0;
        END_IF;

    50: (* FINALIZATION *)
        rHomogenizerSpeedCmd := 0.0;
        bAgitatorStart := FALSE;
        bProcessRunning := FALSE;
        bProcessComplete := TRUE;

        IF NOT bStartProcess THEN
            iState := 0;
        END_IF;

    999: (* FAULT STATE *)
        bProcessRunning := FALSE;
        bError := TRUE;
        iErrorCode := 1;
        rPigmentDosingValveCmd := 0.0;
        rSolventDosingValveCmd := 0.0;
        rBaseInkPumpCmd := 0.0;
        rHomogenizerSpeedCmd := 0.0;
        bAgitatorStart := FALSE;

        IF NOT bEmergencyStop THEN
            iState := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
