FUNCTION_BLOCK FB_H2_Liquefaction
VAR_INPUT
    rFeedTemp : REAL; // Hydrogen feed temperature (K)
    rFeedPress : REAL; // Hydrogen feed pressure (bar)
    rMRFlowRate : REAL; // Mixed refrigerant flow rate (kg/s)
    rOrthoParaRatio : REAL; // Initial Ortho/Para ratio (0.0 - 1.0)
    bStartLiquefaction : BOOL; // Start liquefaction process command
    bEStop : BOOL; // Emergency stop
    rCatBedTempTop : REAL; // Catalyst bed top temperature (K)
    rCatBedTempBot : REAL; // Catalyst bed bottom temperature (K)
END_VAR

VAR_OUTPUT
    rJTValvePos : REAL; // Joule-Thomson valve position (0-100%)
    rMRCompSpeed : REAL; // Mixed refrigerant compressor speed (RPM)
    bOrthoParaAlarm : BOOL; // High thermal gradient alarm in bed
    rLiquidH2Level : REAL; // Final product level (%)
    bSystemReady : BOOL; // Liquefaction system ready
    bFault : BOOL; // General fault indicator
    iState : INT; // Current state of the state machine
END_VAR

VAR
    rTargetParaFrac : REAL := 0.99; // Target para-hydrogen fraction
    rMaxTempGradient : REAL := 15.0; // Max allowed bed thermal gradient
    rTempGradient : REAL;
    rCurrentParaFrac : REAL;

    // Internal PID state for JT valve
    rJTPidError : REAL;
    rJTPidIntegral : REAL;
    rJTPidDerivative : REAL;
    rJTPidPrevError : REAL;
    rJTPidKp : REAL := 2.5;
    rJTPidKi : REAL := 0.1;
    rJTPidKd : REAL := 0.05;

    // Internal PID state for MR Compressor
    rMRPidError : REAL;
    rMRPidIntegral : REAL;
    rMRPidPrevError : REAL;
    rMRPidKp : REAL := 5.0;
    rMRPidKi : REAL := 0.2;

    // Timers
    tStartupDelay : TON;
    tCoolingTimer : TON;

    // Constants
    rMinFeedPress : REAL := 20.0; // Minimum required pressure
    rMaxTemp : REAL := 300.0; // Max feed temp
END_VAR

// Initialization and Safety Checks
IF bEStop THEN
    rJTValvePos := 0.0;
    rMRCompSpeed := 0.0;
    bSystemReady := FALSE;
    bFault := TRUE;
    iState := 0;
    RETURN;
END_IF;

bFault := FALSE;
rTempGradient := ABS(rCatBedTempTop - rCatBedTempBot);

IF rTempGradient > rMaxTempGradient THEN
    bOrthoParaAlarm := TRUE;
    // Reduce JT expansion to lower flow through catalyst
    rJTValvePos := rJTValvePos * 0.8;
ELSE
    bOrthoParaAlarm := FALSE;
END_IF;

// Simple state machine for liquefaction process
CASE iState OF
    0: // IDLE
        rJTValvePos := 0.0;
        rMRCompSpeed := 0.0;
        bSystemReady := (rFeedPress >= rMinFeedPress) AND (rFeedTemp <= rMaxTemp);

        IF bSystemReady AND bStartLiquefaction THEN
            iState := 10;
        END_IF;

    10: // PRE-COOLING (Mixed Refrigerant)
        // MR Compressor PI control to target 80K at top of bed
        rMRPidError := rCatBedTempTop - 80.0; // Target pre-cool temp
        rMRPidIntegral := rMRPidIntegral + rMRPidError;
        rMRCompSpeed := (rMRPidKp * rMRPidError) + (rMRPidKi * rMRPidIntegral);

        // Clamp speed
        IF rMRCompSpeed > 3600.0 THEN rMRCompSpeed := 3600.0; END_IF;
        IF rMRCompSpeed < 1000.0 THEN rMRCompSpeed := 1000.0; END_IF;

        IF rCatBedTempTop < 85.0 THEN
            iState := 20; // Move to catalyst bed / ortho-para conversion
        END_IF;

    20: // ORTHO-PARA CONVERSION & JT EXPANSION
        // Maintain temperature gradient during exothermic conversion
        // Simulate conversion progress
        rCurrentParaFrac := rCurrentParaFrac + 0.001; // Fake incremental conversion

        // JT Valve PID control to reach 20K (liquid H2 range) at bottom
        rJTPidError := rCatBedTempBot - 20.5;
        rJTPidIntegral := rJTPidIntegral + rJTPidError;
        rJTPidDerivative := rJTPidError - rJTPidPrevError;
        rJTPidPrevError := rJTPidError;

        rJTValvePos := (rJTPidKp * rJTPidError) + (rJTPidKi * rJTPidIntegral) + (rJTPidKd * rJTPidDerivative);

        // Clamp valve
        IF rJTValvePos > 100.0 THEN rJTValvePos := 100.0; END_IF;
        IF rJTValvePos < 0.0 THEN rJTValvePos := 0.0; END_IF;

        IF (rCatBedTempBot <= 22.0) AND (rCurrentParaFrac >= rTargetParaFrac) THEN
            iState := 30; // Production
        END_IF;

    30: // STEADY-STATE LIQUEFACTION
        // Produce liquid H2
        rLiquidH2Level := rLiquidH2Level + 0.1;
        IF rLiquidH2Level > 100.0 THEN rLiquidH2Level := 100.0; END_IF;

        // Hold MR and JT constants or slow PID update
        rMRCompSpeed := 2500.0;

        IF NOT bStartLiquefaction THEN
            iState := 0; // Stop production
        END_IF;

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
