FUNCTION_BLOCK "WaferSpinner_Mut4"
VERSION : 0.1
   VAR_INPUT
      execute : Bool;
      targetSpeed : Real;
      dispenseTime : Time;
      flowFeedback : Real; 
      targetFlow : Real;
      pnStatusWord : Word; 
      userRole : Int; 
      pump1Fault : Bool;
      hilModeActive : Bool; // Hardware-in-the-loop bypass
      hilFlowFeedback : Real;
   END_VAR
   VAR_OUTPUT
      busy : Bool;
      done : Bool;
      error : Bool;
      errorID : Int; 
      currentSpeed : Real;
      pump1Control : Real; 
      pump2Control : Real; 
      scadaTags : Struct
         stateDesc : String;
         activePump : Int;
         authValid : Bool;
         driftWarning : Bool;
      End_Struct;
   END_VAR
   VAR
      state : Int;
      timer : TON_TIME;
      pidInst : PID_Compact;
      pidEnable : Bool;
      activePumpIdx : Int := 1;
      flowFilterArr : Array[0..9] of Real;
      filterIdx : Int;
      flowMovingAvg : Real;
      actualFlow : Real;
      sumFlow : Real;
      i : Int;
   END_VAR

BEGIN
   // HIL Bypass
   IF #hilModeActive THEN
      #actualFlow := #hilFlowFeedback;
   ELSE
      #actualFlow := #flowFeedback;
   END_IF;

   // Sensor Drift Detection (Moving Average)
   #flowFilterArr[#filterIdx] := #actualFlow;
   #filterIdx := (#filterIdx + 1) MOD 10;
   #sumFlow := 0.0;
   FOR #i := 0 TO 9 DO
      #sumFlow := #sumFlow + #flowFilterArr[#i];
   END_FOR;
   #flowMovingAvg := #sumFlow / 10.0;

   IF ABS(#flowMovingAvg - #actualFlow) > 5.0 THEN
      #scadaTags.driftWarning := TRUE;
   ELSE
      #scadaTags.driftWarning := FALSE;
   END_IF;

   #scadaTags.authValid := (#userRole >= 1);
   IF NOT #scadaTags.authValid AND #execute THEN
      #error := TRUE;
      #errorID := 100; 
      #state := 99;
   END_IF;

   IF #pump1Fault AND #activePumpIdx = 1 THEN
      #activePumpIdx := 2; 
      #scadaTags.activePump := 2;
   END_IF;

   #pidInst(Setpoint := #targetFlow, Input := #actualFlow, Reset := NOT #pidEnable);

   CASE #state OF
      0: // Init/Self-Test
         #scadaTags.stateDesc := 'SELF_TEST';
         #pump1Control := 0.1; // Test pulse
         #timer(IN := TRUE, PT := T#1s);
         IF #timer.Q THEN
            #pump1Control := 0.0;
            #timer(IN := FALSE, PT := T#1s);
            #state := 5; // Ready Idle
         END_IF;

      5: // Ready Idle
         #scadaTags.stateDesc := 'IDLE';
         #error := FALSE;
         #errorID := 0;
         #busy := FALSE;
         #done := FALSE;
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pump1Control := 0.0;
         #pump2Control := 0.0;
         IF #execute AND NOT #error THEN
            #state := 10;
            #busy := TRUE;
         END_IF;

      10: 
         #scadaTags.stateDesc := 'SPIN_UP';
         #currentSpeed := #targetSpeed; 
         IF #currentSpeed >= #targetSpeed THEN
            #state := 20;
         END_IF;

      20: 
         #scadaTags.stateDesc := 'DISPENSE';
         #pidEnable := TRUE;
         IF #activePumpIdx = 1 THEN
            #pump1Control := #pidInst.Output;
            #pump2Control := 0.0;
         ELSE
            #pump2Control := #pidInst.Output;
            #pump1Control := 0.0;
         END_IF;

         #timer(IN := TRUE, PT := #dispenseTime);
         IF #timer.Q THEN
            #pidEnable := FALSE;
            #pump1Control := 0.0;
            #pump2Control := 0.0;
            #timer(IN := FALSE, PT := #dispenseTime);
            #state := 30;
         END_IF;

      30: 
         #scadaTags.stateDesc := 'STOP';
         #currentSpeed := 0.0;
         #done := TRUE;
         #busy := FALSE;
         IF NOT #execute THEN
            #state := 5;
         END_IF;

      99: 
         #scadaTags.stateDesc := 'FAULT';
         #currentSpeed := 0.0;
         #pidEnable := FALSE;
         #pump1Control := 0.0;
         #pump2Control := 0.0;
         #busy := FALSE;
         IF NOT #execute THEN 
            #state := 5;
         END_IF;
   END_CASE;
END_FUNCTION_BLOCK
