FUNCTION_BLOCK FB_MDF_ContinuousHotPress
VAR_INPUT
    bEnable : BOOL; (* Enable the continuous hot press control *)
    rMatThicknessSP : REAL; (* Setpoint for resin mat thickness (mm) *)
    rActualMatThickness : REAL; (* Optical tracking feedback for mat thickness (mm) *)
    arZoneTempSP : ARRAY[1..5] OF REAL; (* Multi-zone platen thermal setpoints (C) *)
    arZoneTempAct : ARRAY[1..5] OF REAL; (* Multi-zone platen actual temperatures (C) *)
    rPressPressureAct : REAL; (* Actual pressing pressure (bar) *)
    rBlisterThreshold : REAL; (* Threshold for blister detection pressure drop (bar) *)
    rLineSpeedSP : REAL; (* Setpoint for line speed (m/min) *)
    bEStop : BOOL; (* Emergency stop active high *)
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL; (* System is ready for operation *)
    rPressPressureCmd : REAL; (* Commanded pressing pressure (bar) *)
    arZoneHeaterCmd : ARRAY[1..5] OF REAL; (* Heater command (0-100%) *)
    rLineSpeedCmd : REAL; (* Commanded line speed (m/min) *)
    bBlisterDetected : BOOL; (* Blister detection alarm *)
    bThicknessAlarm : BOOL; (* Mat thickness out of bounds *)
END_VAR

VAR
    i : INT;
    rThicknessError : REAL;
    rPressureIntegral : REAL := 0.0;
    rLastPressure : REAL := 0.0;
    rPressureDerivative : REAL := 0.0;
    tCycleTime : TIME := T#50MS;
    rKp_Thickness : REAL := 5.0;
    rKi_Thickness : REAL := 0.1;
    rKp_Temp : ARRAY[1..5] OF REAL := [5(2.5)];
    rTempError : ARRAY[1..5] OF REAL;
END_VAR

(* Implementation *)
IF bEStop OR NOT bEnable THEN
    bSystemReady := FALSE;
    rPressPressureCmd := 0.0;
    rLineSpeedCmd := 0.0;
    bBlisterDetected := FALSE;
    bThicknessAlarm := FALSE;
    FOR i := 1 TO 5 DO
        arZoneHeaterCmd[i] := 0.0;
    END_FOR;
    rPressureIntegral := 0.0;
    RETURN;
END_IF;

bSystemReady := TRUE;

(* Mat Thickness Control (PI Control) *)
rThicknessError := rMatThicknessSP - rActualMatThickness;
IF ABS(rThicknessError) > 2.5 THEN
    bThicknessAlarm := TRUE;
ELSE
    bThicknessAlarm := FALSE;
END_IF;

rPressureIntegral := rPressureIntegral + (rThicknessError * rKi_Thickness);

(* Anti-windup for integral *)
IF rPressureIntegral > 150.0 THEN
    rPressureIntegral := 150.0;
ELSIF rPressureIntegral < -50.0 THEN
    rPressureIntegral := -50.0;
END_IF;

rPressPressureCmd := (rThicknessError * rKp_Thickness) + rPressureIntegral;

(* Base pressure offset *)
rPressPressureCmd := rPressPressureCmd + 120.0; (* Base operating pressure *)

IF rPressPressureCmd > 200.0 THEN
    rPressPressureCmd := 200.0;
ELSIF rPressPressureCmd < 0.0 THEN
    rPressPressureCmd := 0.0;
END_IF;

(* Multi-Zone Platen Thermal Profiling *)
FOR i := 1 TO 5 DO
    rTempError[i] := arZoneTempSP[i] - arZoneTempAct[i];
    IF rTempError[i] > 0.0 THEN
        arZoneHeaterCmd[i] := rTempError[i] * rKp_Temp[i];
        IF arZoneHeaterCmd[i] > 100.0 THEN
            arZoneHeaterCmd[i] := 100.0;
        END_IF;
    ELSE
        arZoneHeaterCmd[i] := 0.0;
    END_IF;
END_FOR;

(* Blister Detection Pressure Loops (Derivative analysis) *)
rPressureDerivative := rLastPressure - rPressPressureAct;
IF (rPressureDerivative > rBlisterThreshold) AND (rPressPressureAct > 50.0) THEN
    bBlisterDetected := TRUE;
    (* Automatically slow down line speed to prevent further blowout *)
    rLineSpeedCmd := rLineSpeedSP * 0.5;
ELSE
    bBlisterDetected := FALSE;
    rLineSpeedCmd := rLineSpeedSP;
END_IF;

rLastPressure := rPressPressureAct;

END_FUNCTION_BLOCK
