FUNCTION_BLOCK FB_SubseaWellheadMasterControl
TITLE = 'Subsea Wellhead Master Control'
VERSION : '2.0'

VAR_INPUT
    bEnableControl      : BOOL;             // Enable automatic control
    bEmergencyShutdown  : BOOL;             // ESD Command
    rSubseaAccumPress   : REAL;             // Subsea Accumulator Pressure (bar)
    rWellheadPress      : REAL;             // Wellhead Production Pressure (bar)
    rWellheadTemp       : REAL;             // Wellhead Temperature (C)
    rChokeValvePosFb    : REAL;             // Choke Valve Position Feedback (0-100%)
    rChokeSetpoint      : REAL;             // Target Production Pressure (bar)
    xAcousticRxReady    : BOOL;             // Acoustic Telemetry Receive Buffer Ready
    dwAcousticRxData    : DWORD;            // Incoming Acoustic Telemetry Data
END_VAR

VAR_OUTPUT
    bHPU_Pump1_Cmd      : BOOL;             // Command to Start HPU Pump 1
    bHPU_Pump2_Cmd      : BOOL;             // Command to Start HPU Pump 2 (Standby)
    rChokeValveCmd      : REAL;             // Choke Valve Position Command (0-100%)
    bAcousticTxTrigger  : BOOL;             // Trigger Acoustic Transmission
    dwAcousticTxData    : DWORD;            // Outgoing Acoustic Telemetry Data
    bSystemFault        : BOOL;             // General System Fault Alarm
    bESD_Active         : BOOL;             // ESD State Active
END_VAR

VAR
    // HPU Sequencing
    rAccumLowerLimit    : REAL := 150.0;    // Low pressure limit for accumulators
    rAccumUpperLimit    : REAL := 205.0;    // High pressure limit for accumulators
    rAccumCritical      : REAL := 120.0;    // Critical low pressure
    tmrPump1Runtime     : TON;              // Pump 1 Runtime timer
    tmrPump2Runtime     : TON;              // Pump 2 Runtime timer

    // Choke Valve Stepping
    rDeadband           : REAL := 2.5;      // Pressure deadband
    rStepSize           : REAL := 1.0;      // Valve step size %
    tmrStepDelay        : TON;              // Delay between valve steps
    bStepWait           : BOOL;             // Step execution flag

    // Telemetry Handshake
    iAcousticState      : INT := 0;         // State machine for acoustic comms
    tmrAcousticTimeout  : TON;              // Timeout for acoustic handshake
    dwSyncPattern       : DWORD := 16#A5A5; // Sync word

    // General
    bInit               : BOOL := FALSE;
END_VAR

// Initializations
IF NOT bInit THEN
    bHPU_Pump1_Cmd := FALSE;
    bHPU_Pump2_Cmd := FALSE;
    rChokeValveCmd := 0.0;
    iAcousticState := 0;
    bInit := TRUE;
END_IF;

// Emergency Shutdown Processing
IF bEmergencyShutdown THEN
    bESD_Active := TRUE;
    bHPU_Pump1_Cmd := FALSE;
    bHPU_Pump2_Cmd := FALSE;
    rChokeValveCmd := 0.0;  // Fail-safe close
    bAcousticTxTrigger := TRUE;
    dwAcousticTxData := 16#DEAD; // Broadcast ESD state
    RETURN;
END_IF;

bESD_Active := FALSE;
bSystemFault := FALSE;

// ---------------------------------------------------------
// 1. Hydraulic Power Unit (HPU) Subsea Accumulator Sequencing
// ---------------------------------------------------------
IF bEnableControl THEN
    // Primary Pump Logic
    IF rSubseaAccumPress < rAccumLowerLimit THEN
        bHPU_Pump1_Cmd := TRUE;
    ELSIF rSubseaAccumPress > rAccumUpperLimit THEN
        bHPU_Pump1_Cmd := FALSE;
    END_IF;

    // Standby Pump Logic (If critical or primary pump fails to build pressure quickly)
    tmrPump1Runtime(IN := bHPU_Pump1_Cmd, PT := T#30S);
    IF (rSubseaAccumPress < rAccumCritical) OR tmrPump1Runtime.Q THEN
        bHPU_Pump2_Cmd := TRUE;
    ELSIF rSubseaAccumPress > (rAccumUpperLimit - 10.0) THEN
        bHPU_Pump2_Cmd := FALSE;
    END_IF;
ELSE
    bHPU_Pump1_Cmd := FALSE;
    bHPU_Pump2_Cmd := FALSE;
END_IF;

// ---------------------------------------------------------
// 2. Production Choke Valve Stepping Profile
// ---------------------------------------------------------
tmrStepDelay(IN := bStepWait, PT := T#5S);

IF bEnableControl AND NOT bStepWait THEN
    IF rWellheadPress > (rChokeSetpoint + rDeadband) THEN
        // Pressure too high, open choke slightly
        rChokeValveCmd := rChokeValvePosFb + rStepSize;
        IF rChokeValveCmd > 100.0 THEN
            rChokeValveCmd := 100.0;
        END_IF;
        bStepWait := TRUE;
    ELSIF rWellheadPress < (rChokeSetpoint - rDeadband) THEN
        // Pressure too low, close choke slightly
        rChokeValveCmd := rChokeValvePosFb - rStepSize;
        IF rChokeValveCmd < 0.0 THEN
            rChokeValveCmd := 0.0;
        END_IF;
        bStepWait := TRUE;
    END_IF;
END_IF;

IF tmrStepDelay.Q THEN
    bStepWait := FALSE;
END_IF;

// ---------------------------------------------------------
// 3. Acoustic Telemetry Handshakes
// ---------------------------------------------------------
tmrAcousticTimeout(IN := (iAcousticState > 0), PT := T#10S);

CASE iAcousticState OF
    0:  // IDLE - Waiting for Sync
        IF xAcousticRxReady AND (dwAcousticRxData = dwSyncPattern) THEN
            iAcousticState := 1;
            bAcousticTxTrigger := TRUE;
            dwAcousticTxData := 16#5A5A; // Send ACK
        ELSE
            bAcousticTxTrigger := FALSE;
        END_IF;

    1:  // WAIT FOR COMMAND
        bAcousticTxTrigger := FALSE;
        IF xAcousticRxReady THEN
            // Process Data Command (dummy logic for example)
            iAcousticState := 2;
        ELSIF tmrAcousticTimeout.Q THEN
            iAcousticState := 0; // Timeout, return to idle
            bSystemFault := TRUE;
        END_IF;

    2:  // TRANSMIT RESPONSE
        bAcousticTxTrigger := TRUE;
        // Pack status into payload: byte 1 = HPU state, byte 2 = Choke pos
        dwAcousticTxData := REAL_TO_DWORD(rChokeValvePosFb);
        iAcousticState := 0;

    ELSE
        iAcousticState := 0;
END_CASE;

END_FUNCTION_BLOCK
