FUNCTION_BLOCK FB_QuantumCryoController
TITLE = 'Quantum Cryogenics Dilution Refrigerator Controller'
// -----------------------------------------------------------------------------
// This function block handles the complex thermodynamic cycle of a 
// He3/He4 dilution refrigerator used for quantum computer cooling.
// It manages pulse tube cryocooler sequencing, mixture condensation, 
// still heating, and precise milli-Kelvin stage temperature regulation.
// -----------------------------------------------------------------------------

VAR_INPUT
    bEnable                 : BOOL;   // System Master Enable
    bEmergencyStop          : BOOL;   // Fast dump and system halt
    rTargetMixingTemp_mK    : REAL;   // Target temperature for the mixing chamber (mK)
    rCurrentMixingTemp_mK   : REAL;   // Feedback from RuO2 thermometer (mK)
    rCurrentStillTemp_K     : REAL;   // Feedback from Still thermometer (K)
    rCurrentPTC1Temp_K      : REAL;   // Pulse Tube Stage 1 Temp (K)
    rCurrentPTC2Temp_K      : REAL;   // Pulse Tube Stage 2 Temp (K)
    rHe3He4MixturePressure  : REAL;   // Mixture tank pressure (bar)
    rCondensingPressure     : REAL;   // Condensing line pressure (bar)
    rStillHeaterPowerLimit  : REAL;   // Maximum allowed still heater power (W)
END_VAR

VAR_OUTPUT
    bPulseTubeCompressorRun : BOOL;   // Command to PTC compressor
    bRotaryValveRun         : BOOL;   // Command to PTC rotary valve
    bTurboPumpRun           : BOOL;   // Command to Roots/Turbo pumping station
    rStillHeaterOutput_W    : REAL;   // Commanded Still Heater Power (W)
    rMixingChamberHeater_uW : REAL;   // Fine control heater for mixing chamber (uW)
    nStateCode              : INT;    // Current state machine step
    bSystemReady            : BOOL;   // True when target mK temp is stable
    bAlarm                  : BOOL;   // System fault
END_VAR

VAR
    // State Machine
    eState : (INIT, PRECOOLING, CONDENSING, CIRCULATING, STABLE_MK, SHUTDOWN, FAULT);

    // PID Controller for Mixing Chamber
    rError_mK               : REAL;
    rIntegral_mK            : REAL;
    rDerivative_mK          : REAL;
    rLastError_mK           : REAL;
    rKp_mK                  : REAL := 1.5;
    rKi_mK                  : REAL := 0.05;
    rKd_mK                  : REAL := 0.2;

    // PID Controller for Still
    rStillError_K           : REAL;
    rStillTarget_K          : REAL := 0.85; // Optimal still temp for He3 distillation
    rStillIntegral_K        : REAL;
    rStillLastError_K       : REAL;
    rKp_Still               : REAL := 12.0;
    rKi_Still               : REAL := 0.5;

    // Timers
    tPrecoolTimer           : TON;
    tCondenseTimer          : TON;
    tStableTimer            : TON;

    bInitDone               : BOOL := FALSE;
END_VAR

// --- EMERGENCY STOP HANDLING ---
IF bEmergencyStop THEN
    eState := FAULT;
    bPulseTubeCompressorRun := FALSE;
    bRotaryValveRun := FALSE;
    bTurboPumpRun := FALSE;
    rStillHeaterOutput_W := 0.0;
    rMixingChamberHeater_uW := 0.0;
    bSystemReady := FALSE;
    bAlarm := TRUE;
    nStateCode := 999;
    RETURN;
END_IF

// --- STATE MACHINE ---
CASE eState OF

    INIT:
        bAlarm := FALSE;
        bSystemReady := FALSE;
        rStillHeaterOutput_W := 0.0;
        rMixingChamberHeater_uW := 0.0;
        nStateCode := 0;

        IF bEnable THEN
            eState := PRECOOLING;
        END_IF

    PRECOOLING:
        nStateCode := 10;
        // Start Pulse Tube Cryocooler
        bPulseTubeCompressorRun := TRUE;
        bRotaryValveRun := TRUE;

        // Wait for PTC Stage 2 to reach ~3K
        IF rCurrentPTC2Temp_K < 3.2 THEN
            tPrecoolTimer(IN := TRUE, PT := T#5m);
            IF tPrecoolTimer.Q THEN
                eState := CONDENSING;
                tPrecoolTimer(IN := FALSE);
            END_IF
        ELSE
            tPrecoolTimer(IN := FALSE);
        END_IF

    CONDENSING:
        nStateCode := 20;
        // Introduce He3/He4 mixture
        IF rCondensingPressure > 0.5 AND rCurrentPTC2Temp_K < 3.5 THEN
            tCondenseTimer(IN := TRUE, PT := T#30m); // Wait for mixture to condense
            IF tCondenseTimer.Q THEN
                bTurboPumpRun := TRUE; // Start circulating
                eState := CIRCULATING;
                tCondenseTimer(IN := FALSE);
            END_IF
        ELSE
            tCondenseTimer(IN := FALSE);
        END_IF

    CIRCULATING:
        nStateCode := 30;
        // Regulate Still Temperature to promote He3 evaporation
        rStillError_K := rStillTarget_K - rCurrentStillTemp_K;
        rStillIntegral_K := rStillIntegral_K + (rStillError_K * 0.1); // Assuming 100ms cycle

        // Anti-windup
        IF rStillIntegral_K > rStillHeaterPowerLimit THEN rStillIntegral_K := rStillHeaterPowerLimit; END_IF
        IF rStillIntegral_K < 0.0 THEN rStillIntegral_K := 0.0; END_IF

        rStillHeaterOutput_W := (rKp_Still * rStillError_K) + (rKi_Still * rStillIntegral_K);
        IF rStillHeaterOutput_W > rStillHeaterPowerLimit THEN rStillHeaterOutput_W := rStillHeaterPowerLimit; END_IF
        IF rStillHeaterOutput_W < 0.0 THEN rStillHeaterOutput_W := 0.0; END_IF

        // Check if mixing chamber is approaching target
        IF rCurrentMixingTemp_mK < (rTargetMixingTemp_mK + 50.0) THEN
            eState := STABLE_MK;
        END_IF

    STABLE_MK:
        nStateCode := 40;

        // Continue Still regulation
        rStillError_K := rStillTarget_K - rCurrentStillTemp_K;
        rStillIntegral_K := rStillIntegral_K + (rStillError_K * 0.1);
        rStillHeaterOutput_W := (rKp_Still * rStillError_K) + (rKi_Still * rStillIntegral_K);
        IF rStillHeaterOutput_W > rStillHeaterPowerLimit THEN rStillHeaterOutput_W := rStillHeaterPowerLimit; END_IF
        IF rStillHeaterOutput_W < 0.0 THEN rStillHeaterOutput_W := 0.0; END_IF

        // Precision PID for Mixing Chamber Heater
        rError_mK := rTargetMixingTemp_mK - rCurrentMixingTemp_mK;
        rIntegral_mK := rIntegral_mK + (rError_mK * 0.1);
        rDerivative_mK := (rError_mK - rLastError_mK) / 0.1;
        rLastError_mK := rError_mK;

        // Calculate heater power (uW) - heating only, cannot actively cool beyond circulation
        rMixingChamberHeater_uW := (rKp_mK * rError_mK) + (rKi_mK * rIntegral_mK) + (rKd_mK * rDerivative_mK);

        IF rMixingChamberHeater_uW < 0.0 THEN 
            rMixingChamberHeater_uW := 0.0; 
            // If we are overcooling, integral windup needs to be prevented
            IF rIntegral_mK < 0.0 THEN rIntegral_mK := 0.0; END_IF
        END_IF

        // Cap fine control heater at 1000 uW (1 mW)
        IF rMixingChamberHeater_uW > 1000.0 THEN
            rMixingChamberHeater_uW := 1000.0;
        END_IF

        // Stability check
        IF ABS(rError_mK) < 0.5 THEN
            tStableTimer(IN := TRUE, PT := T#1m);
            IF tStableTimer.Q THEN
                bSystemReady := TRUE;
            END_IF
        ELSE
            tStableTimer(IN := FALSE);
            bSystemReady := FALSE;
        END_IF

    SHUTDOWN:
        nStateCode := 90;
        bSystemReady := FALSE;
        rStillHeaterOutput_W := 0.0;
        rMixingChamberHeater_uW := 0.0;
        bTurboPumpRun := FALSE;
        // Wait for pressure to equalize before stopping PTC
        IF rCondensingPressure < 1.0 THEN
            bPulseTubeCompressorRun := FALSE;
            bRotaryValveRun := FALSE;
            eState := INIT;
        END_IF

    FAULT:
        // Handled at the top, requires manual reset by toggling bEnable
        IF NOT bEnable THEN
            eState := INIT;
        END_IF

END_CASE

// Shutdown trigger
IF NOT bEnable AND eState <> INIT AND eState <> FAULT THEN
    eState := SHUTDOWN;
END_IF

END_FUNCTION_BLOCK
```

```iec-st
FUNCTION_BLOCK FB_SupersonicInletControl
(*
    ================================================================================
    Commercial Aviation Supersonic Jet Variable Geometry Engine Inlet Controller
    ================================================================================
    Purpose: 
    Stabilizes the mixed-compression supersonic diffuser shockwave at Mach 2.2+.
    Actively predicts unstart conditions and dynamically tracks bleed air bypass.
    ================================================================================
*)
VAR_INPUT
    bSystemEnable           : BOOL;     (* System master enable signal *)
    bEmergencyOverride      : BOOL;     (* FADEC override for safety interlocks *)
    rMachNumber             : REAL;     (* Current freestream Mach number *)
    rShockPosition          : REAL;     (* Normal shock position sensor (mm from throat) *)
    rDiffuserPressure       : REAL;     (* Diffuser exit static pressure (kPa) *)
    rInletTemp              : REAL;     (* Total temperature at inlet face (K) *)
    rSpikePositionFdbk      : REAL;     (* Center spike translation feedback (mm) *)
    rBypassDoorFdbk         : REAL;     (* Bleed air bypass door position feedback (%) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* Inlet control system ready for supersonic envelope *)
    rSpikePositionCmd       : REAL;     (* Command signal for center spike translation (mm) *)
    rBypassDoorCmd          : REAL;     (* Command signal for bypass door opening (%) *)
    bUnstartWarning         : BOOL;     (* Active unstart prediction warning flag *)
    bShockExpulsionFault    : BOOL;     (* Critical fault: normal shock expelled *)
    rCalculatedMargin       : REAL;     (* Unstart stability margin (0.0 - 1.0) *)
END_VAR

VAR
    (* Internal State and Timers *)
    iControlState           : INT := 0; 
    tStabilityTimer         : TON;
    tUnstartPredictTimer    : TON;

    (* Internal Control Variables *)
    rTargetShockPos         : REAL;
    rShockError             : REAL;
    rIntegralError          : REAL;
    rDerivativeError        : REAL;
    rLastError              : REAL;
    rPIDOutput              : REAL;

    (* Constants *)
    Kp                      : REAL := 2.45;
    Ki                      : REAL := 0.15;
    Kd                      : REAL := 0.85;
    MACH_THRESHOLD          : REAL := 1.2;
    NOMINAL_SHOCK_POS       : REAL := 45.0; (* mm downstream of throat *)
    CRITICAL_SHOCK_POS      : REAL := 10.0; (* mm, danger of expulsion *)
END_VAR

(* === MAIN LOGIC === *)
(* Handle Emergency Override or System Disable *)
IF bEmergencyOverride OR NOT bSystemEnable THEN
    bSystemReady         := FALSE;
    bUnstartWarning      := FALSE;
    bShockExpulsionFault := FALSE;
    rSpikePositionCmd    := 0.0; (* Fully retracted *)
    rBypassDoorCmd       := 100.0; (* Fully open for safe flow spillage *)
    iControlState        := 0;
    rIntegralError       := 0.0;
    RETURN;
END_IF;

(* Active Unstart Prediction *)
rCalculatedMargin := (rShockPosition - CRITICAL_SHOCK_POS) / (NOMINAL_SHOCK_POS - CRITICAL_SHOCK_POS);
IF rCalculatedMargin < 0.0 THEN
    rCalculatedMargin := 0.0;
END_IF;
IF rCalculatedMargin > 1.0 THEN
    rCalculatedMargin := 1.0;
END_IF;

tUnstartPredictTimer(IN := (rCalculatedMargin < 0.2 AND rMachNumber > 1.8), PT := T#50MS);
bUnstartWarning := tUnstartPredictTimer.Q;

(* Shock Expulsion Fault Detection *)
IF rShockPosition < 0.0 THEN
    bShockExpulsionFault := TRUE;
    iControlState := 99; (* Transition to fault state *)
END_IF;

(* State Machine for Variable Geometry Inlet Control *)
CASE iControlState OF
    0: (* INIT / SUBSONIC *)
        bSystemReady := TRUE;
        rSpikePositionCmd := 0.0;
        rBypassDoorCmd := 10.0; (* Minimum cooling flow *)

        IF rMachNumber >= MACH_THRESHOLD THEN
            iControlState := 10;
        END_IF;

    10: (* TRANSONIC ACCELERATION *)
        (* Gradually extend spike based on Mach number *)
        rSpikePositionCmd := (rMachNumber - MACH_THRESHOLD) * 50.0;
        rBypassDoorCmd := 30.0;

        IF rMachNumber >= 2.0 THEN
            iControlState := 20;
            tStabilityTimer(IN := FALSE);
        END_IF;
        IF rMachNumber < MACH_THRESHOLD THEN
            iControlState := 0;
        END_IF;

    20: (* SUPERSONIC CRUISE - SHOCK STABILIZATION *)
        rTargetShockPos := NOMINAL_SHOCK_POS;
        rShockError := rTargetShockPos - rShockPosition;

        (* PID Computation for Bypass Door Control to stabilize shock *)
        rIntegralError := rIntegralError + rShockError;
        (* Clamp Integral *)
        IF rIntegralError > 1000.0 THEN rIntegralError := 1000.0; END_IF;
        IF rIntegralError < -1000.0 THEN rIntegralError := -1000.0; END_IF;

        rDerivativeError := rShockError - rLastError;
        rPIDOutput := (Kp * rShockError) + (Ki * rIntegralError) + (Kd * rDerivativeError);
        rLastError := rShockError;

        (* Calculate Bypass Door Command based on PID *)
        rBypassDoorCmd := 50.0 + rPIDOutput;

        (* Saturate Door Command *)
        IF rBypassDoorCmd > 100.0 THEN rBypassDoorCmd := 100.0; END_IF;
        IF rBypassDoorCmd < 5.0 THEN rBypassDoorCmd := 5.0; END_IF;

        (* Spike Command follows scheduled Mach profile *)
        rSpikePositionCmd := 100.0 + (rMachNumber - 2.0) * 80.0;

        IF bUnstartWarning THEN
            (* Rapidly open bypass door to prevent unstart *)
            rBypassDoorCmd := 100.0;
        END_IF;

        IF rMachNumber < 1.9 THEN
            iControlState := 10;
        END_IF;

    99: (* FAULT / UNSTART RECOVERY *)
        (* Retract spike and open bypass door completely to re-swallow shock *)
        rSpikePositionCmd := 0.0;
        rBypassDoorCmd := 100.0;
        bSystemReady := FALSE;

        (* Auto-recovery attempt after conditions stabilize *)
        tStabilityTimer(IN := TRUE, PT := T#3S);
        IF tStabilityTimer.Q THEN
            bShockExpulsionFault := FALSE;
            tStabilityTimer(IN := FALSE);
            iControlState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
