FUNCTION_BLOCK FB_CSP_Tower_Flux_Controller
VAR_INPUT
    SystemEnable : BOOL;
    DirectNormalIrradiance : REAL; // W/m^2
    WindVelocity : REAL; // m/s
    WindDirection : REAL; // degrees
    SaltInletTemperature : REAL; // C
    SaltOutletTemperature : REAL; // C
    SaltOutletTempSetpoint : REAL := 565.0; // C
    ColdSaltTankLevel : REAL; // %
    HotSaltTankLevel : REAL; // %
    ReceiverPanels : ARRAY[1..24] OF Receiver_Panel_Data;
    GridDispatchDemand : REAL; // MWth
    TimeOfDay : DT;
END_VAR

VAR_OUTPUT
    PrimarySaltPumpSpeedCmd : REAL; // 0.0 - 100.0 %
    SecondarySaltPumpSpeedCmd : REAL; // 0.0 - 100.0 %
    HeliostatArrayCmd : ARRAY[1..1024] OF Heliostat_Cmd_Type;
    EmergencyDefocusAll : BOOL;
    ThermalFatigueAlarm : BOOL;
    CurrentState : INT; // 0: Off, 1: Pre-heating, 2: Solar Tracking, 3: Cloud Transit, 4: Defocusing
    CalculatedThermalPower : REAL; // MWth
END_VAR

VAR
    i, j : INT;
    MaxAllowableTempGradient : REAL := 65.0; // Max temp diff limit
    AveragePanelTemp : REAL;
    TotalFlux : REAL;
    PID_Kp : REAL := 2.25;
    PID_Ki : REAL := 0.45;
    PID_Kd : REAL := 0.12;
    ErrorTemp : REAL;
    PrevErrorTemp : REAL;
    IntegralTerm : REAL;
    DerivativeTerm : REAL;
    ControlOutput : REAL;
    WindLimitTracking : REAL := 16.5;
    WindLimitStow : REAL := 22.0;
    MinDNIOperating : REAL := 250.0;
    PanelHotSpotThreshold : REAL := 610.0; // C
    CriticalFatigueLimit : REAL := 0.95;
    ActiveHeliostats : DINT;
END_VAR

// 1. SYSTEM SUPERVISION & SAFETY INTERLOCKS
IF NOT SystemEnable THEN
    PrimarySaltPumpSpeedCmd := 0.0;
    EmergencyDefocusAll := TRUE;
    CurrentState := 0;
    RETURN;
END_IF;

IF WindVelocity > WindLimitStow THEN
    EmergencyDefocusAll := TRUE;
    PrimarySaltPumpSpeedCmd := 25.0; // Anti-freeze circulation
    CurrentState := 4; // Defocusing / Stowing

    // Command all heliostats to stow
    FOR i := 1 TO 1024 DO
        HeliostatArrayCmd[i].StowPosition := TRUE;
        HeliostatArrayCmd[i].TrackingEnabled := FALSE;
    END_FOR;
    RETURN;
ELSIF WindVelocity > WindLimitTracking OR DirectNormalIrradiance < MinDNIOperating THEN
    // Move to standby ring during cloud transits or high winds
    EmergencyDefocusAll := FALSE;
    CurrentState := 3;
    FOR i := 1 TO 1024 DO
        HeliostatArrayCmd[i].StandbyRingPos := TRUE;
        HeliostatArrayCmd[i].TrackingEnabled := FALSE;
    END_FOR;
ELSE
    EmergencyDefocusAll := FALSE;
    CurrentState := 2; // Tracking
END_IF;

// 2. RECEIVER THERMAL FATIGUE & FLUX MAPPING EVALUATION
AveragePanelTemp := 0.0;
TotalFlux := 0.0;
ThermalFatigueAlarm := FALSE;

FOR i := 1 TO 24 DO
    // Aggregate statistics
    AveragePanelTemp := AveragePanelTemp + ReceiverPanels[i].SurfaceTempMax;
    TotalFlux := TotalFlux + ReceiverPanels[i].AbsorbedFluxAvg;

    // Calculate gradients to mitigate thermal fatigue
    ReceiverPanels[i].ThermalGradient := ReceiverPanels[i].SurfaceTempMax - ReceiverPanels[i].InletHeaderTemp;

    // Estimate fatigue accumulation based on Coffin-Manson relationship logic
    IF ReceiverPanels[i].ThermalGradient > MaxAllowableTempGradient THEN
        ReceiverPanels[i].FatigueIndex := ReceiverPanels[i].FatigueIndex + (ReceiverPanels[i].ThermalGradient * 0.0001);
    END_IF;

    IF ReceiverPanels[i].FatigueIndex > CriticalFatigueLimit THEN
        ThermalFatigueAlarm := TRUE;
    END_IF;
END_FOR;
AveragePanelTemp := AveragePanelTemp / 24.0;
CalculatedThermalPower := TotalFlux * 0.001; // Approximate conversion to MWth

// 3. HELIOSTAT FIELD AIMING VECTOR COORDINATION
// Disperse flux if localized hotspots are detected on specific panels
ActiveHeliostats := 0;
FOR j := 1 TO 1024 DO
    // Assign heliostat groupings to receiver panels (1024 / 24 approx 42 per panel)
    // In a real system, an optimization algorithm defines the flux map.
    // Here we simulate reactive defocusing based on panel limits.
    i := (j MOD 24) + 1; // Corresponding panel ID

    IF ReceiverPanels[i].SurfaceTempMax > PanelHotSpotThreshold THEN
        // If the panel is overheating, defocus some of its assigned heliostats to the standby ring
        IF (j MOD 3) = 0 THEN // Defocus 1/3 of the field targeting this panel
            HeliostatArrayCmd[j].TrackingEnabled := FALSE;
            HeliostatArrayCmd[j].StandbyRingPos := TRUE;
            HeliostatArrayCmd[j].TargetAimZ := HeliostatArrayCmd[j].TargetAimZ + 15.0; // Aim above receiver
        ELSE
            HeliostatArrayCmd[j].TrackingEnabled := TRUE;
            HeliostatArrayCmd[j].StandbyRingPos := FALSE;
        END_IF;
    ELSE
        // Normal tracking aiming strategy
        HeliostatArrayCmd[j].TrackingEnabled := TRUE;
        HeliostatArrayCmd[j].StandbyRingPos := FALSE;
        HeliostatArrayCmd[j].StowPosition := FALSE;
        ActiveHeliostats := ActiveHeliostats + 1;
    END_IF;
END_FOR;

// 4. MOLTEN SALT PUMP SPEED - PID FLOW CONTROL
// Maintain precise salt outlet temperature (e.g. 565C) by modulating flow rate
ErrorTemp := SaltOutletTempSetpoint - SaltOutletTemperature;
IntegralTerm := IntegralTerm + (ErrorTemp * 0.1);

// Anti-windup clamping
IF IntegralTerm > 150.0 THEN IntegralTerm := 150.0; END_IF;
IF IntegralTerm < -150.0 THEN IntegralTerm := -150.0; END_IF;

DerivativeTerm := (ErrorTemp - PrevErrorTemp) / 0.1;

// Base load flow scales with active heliostats and DNI
ControlOutput := (ActiveHeliostats / 1024.0) * (DirectNormalIrradiance / 1000.0) * 50.0; 
ControlOutput := ControlOutput + (PID_Kp * ErrorTemp) + (PID_Ki * IntegralTerm) + (PID_Kd * DerivativeTerm);

// Constrain pump speeds
PrimarySaltPumpSpeedCmd := ControlOutput;
IF PrimarySaltPumpSpeedCmd > 100.0 THEN PrimarySaltPumpSpeedCmd := 100.0; END_IF;
IF PrimarySaltPumpSpeedCmd < 20.0 THEN PrimarySaltPumpSpeedCmd := 20.0; END_IF; // Maintain minimal flow

PrevErrorTemp := ErrorTemp;

END_FUNCTION_BLOCK
