    // Failover Logic
    IF NOT "Is_Primary" AND "Partner_PLC_Alive" THEN
        "Failover_Active" := FALSE;
        RETURN; // Let primary control
    ELSE
        "Failover_Active" := TRUE;
    END_IF;

    IF "E_Stop" OR "System_Fault" OR "Security_Fault" THEN
        "Motor_Fwd" := FALSE; "Brake_Release" := FALSE; "VFD_Speed_Ref" := 0.0; "State" := 0;
        RETURN;
    END_IF;

    "Step_Timer"(IN := "Motor_Fwd" AND NOT "Step_Sensor_1", PT := T#1s);
    IF "Step_Timer".Q THEN "System_Fault" := TRUE; END_IF;

    "Speed_Timer"(IN := "Motor_Fwd" AND ("Motor_Speed_RPM" < 80.0) AND ("VFD_Speed_Ref" > 20.0), PT := T#2s);
    IF "Speed_Timer".Q THEN "System_Fault" := TRUE; END_IF;

    "Passenger_Timer"(IN := NOT "Passenger_Radar", PT := T#60s);

    CASE "State" OF
        0: 
            "Motor_Fwd" := FALSE; "Brake_Release" := FALSE; "VFD_Speed_Ref" := 0.0;
            IF NOT "Stop" AND "Start_Up" THEN "State" := 10; END_IF;
        10: 
            IF "Stop" THEN "State" := 0; 
            ELSE 
                "Brake_Release" := TRUE; "Motor_Fwd" := TRUE;
                IF "Passenger_Timer".Q THEN "VFD_Speed_Ref" := 20.0; ELSE "VFD_Speed_Ref" := 100.0; END_IF;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
