    xCompressorTrip : BOOL; // Emergency compressor trip

    // Crude Heating
    rHeaterValveCmd : REAL; // Steam valve command for crude heater (0-100%)
    xStabilizationReady : BOOL; // Crude is on-spec for storage
END_VAR

VAR
    // Internal State & Timers
    rOperatingPoint : REAL;
    rErrorTurret : REAL;
    rErrorSurge : REAL;
    rErrorTemp : REAL;
    rIntegralSurge : REAL := 0.0;
    rIntegralTemp : REAL := 0.0;

    tSurgeDelay : TON;
    tSwivelTimeout : TON;

    // Tuning Parameters
    Kp_Surge : REAL := 2.5;
    Ki_Surge : REAL := 0.5;
    Kp_Temp : REAL := 1.2;
    Ki_Temp : REAL := 0.1;

    rSafeOperatingLine : REAL;
END_VAR

// -----------------------------------------------------------------------------
// 1. EMERGENCY SHUTDOWN EVALUATION
// -----------------------------------------------------------------------------
IF xEmergencyShutdown THEN
    rThrusterSetpoint := 0.0;
    rAntiSurgeValveCmd := 100.0; // Fail open
    xCompressorTrip := TRUE;
    rHeaterValveCmd := 0.0; // Fail closed
    xTurretLockout := TRUE;
    RETURN; // Halt further processing
END_IF;

// -----------------------------------------------------------------------------
// 2. TURRET MOORING & SWIVEL KINEMATICS
// -----------------------------------------------------------------------------
// Calculate optimal heading based on wind, wave, and current (Weathervaning)
rErrorTurret := ((rWindDirection * 0.5) + (rWaveDirection * 0.3) + (rCurrentDirection * 0.2)) - rVesselHeading;

// Normalize error between -180 and +180
IF rErrorTurret > 180.0 THEN
    rErrorTurret := rErrorTurret - 360.0;
ELSIF rErrorTurret < -180.0 THEN
    rErrorTurret := rErrorTurret + 360.0;
END_IF;

// Simple proportional heading correction
rThrusterSetpoint := rErrorTurret * 2.0; 

// Check Swivel Alignment Limits
xSwivelWarning := ABS(rSwivelAngle - rVesselHeading) > 15.0;
tSwivelTimeout(IN := xSwivelWarning AND NOT xSwivelLock, PT := T#10s);

IF tSwivelTimeout.Q THEN
    xTurretLockout := TRUE; // Force lockout if misalignment persists
ELSE
    xTurretLockout := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// 3. TOPSIDE GAS COMPRESSION ANTI-SURGE
// -----------------------------------------------------------------------------
// Determine operating point and distance to Surge Limit Line
rOperatingPoint := rCompressorFlow / SQRT(ABS(rSuctionPressure + 1.0)); // Simplified polytropic flow param
rSafeOperatingLine := rSurgeLimitLine * (1.0 + (rSurgeMargin / 100.0));

rErrorSurge := rSafeOperatingLine - rOperatingPoint;

// PI Controller for Anti-Surge Valve (ASV)
IF rErrorSurge > 0.0 THEN
    xSurgeAlarm := TRUE;
    rIntegralSurge := rIntegralSurge + (rErrorSurge * Ki_Surge); // Accumulate integral

    // Anti-windup
    IF rIntegralSurge > 100.0 THEN rIntegralSurge := 100.0; END_IF;

    rAntiSurgeValveCmd := (rErrorSurge * Kp_Surge) + rIntegralSurge;
ELSE
    xSurgeAlarm := FALSE;
    rAntiSurgeValveCmd := 0.0; // Close valve if safely operating
    rIntegralSurge := 0.0; // Reset integral
END_IF;

// Clamp valve command
IF rAntiSurgeValveCmd > 100.0 THEN
    rAntiSurgeValveCmd := 100.0;
END_IF;

// Trip logic if deeply in surge
tSurgeDelay(IN := (rOperatingPoint < rSurgeLimitLine), PT := T#2s);
xCompressorTrip := tSurgeDelay.Q;

// -----------------------------------------------------------------------------
// 4. CRUDE OIL STABILIZATION HEATING
// -----------------------------------------------------------------------------
rErrorTemp := rTargetTemp - rCrudeInletTemp;

IF rErrorTemp > 0.0 THEN
    rIntegralTemp := rIntegralTemp + (rErrorTemp * Ki_Temp);
    IF rIntegralTemp > 100.0 THEN rIntegralTemp := 100.0; END_IF; // Anti-windup

    rHeaterValveCmd := (rErrorTemp * Kp_Temp) + rIntegralTemp;
ELSE
    rHeaterValveCmd := 0.0;
    rIntegralTemp := 0.0;
END_IF;

IF rHeaterValveCmd > 100.0 THEN
    rHeaterValveCmd := 100.0;
END_IF;

// Check if stabilization conditions are met (Temperature within +/- 2C of target)
xStabilizationReady := (ABS(rTargetTemp - rCrudeInletTemp) <= 2.0);

END_FUNCTION_BLOCK
