\nFUNCTION_BLOCK FB_ASRS_StackerCraneControl
FUNCTION_BLOCK FB_IndustrialControl
VAR_INPUT
    bEnable : BOOL; // Enable the stacker crane control
    bExecuteMove : BOOL; // Command to start movement
    rTargetPos_X : REAL; // Target horizontal position in mm
    rTargetPos_Y : REAL; // Target vertical position in mm
    rLoadMass : REAL; // Mass of the current load in kg
    rMaxAccel : REAL; // Maximum allowable acceleration in mm/s^2
    rMaxVel : REAL; // Maximum allowable velocity in mm/s
    bEstop : BOOL; // Emergency stop active low
END_VAR
VAR_OUTPUT
    bReady : BOOL; // System is ready
    bMoving : BOOL; // System is currently moving
    bInPosition : BOOL; // System has reached target position
    rCmdAccel_X : REAL; // Commanded horizontal acceleration
    rCmdVel_X : REAL; // Commanded horizontal velocity
    rCmdPos_X : REAL; // Commanded horizontal position
    rCmdAccel_Y : REAL; // Commanded vertical acceleration
    rCmdVel_Y : REAL; // Commanded vertical velocity
    rCmdPos_Y : REAL; // Commanded vertical position
    rSwayCorrection_X : REAL; // Calculated sway correction
    bError : BOOL; // Error flag
    nErrorID : INT; // Error code
END_VAR
VAR
    // State machine
    nState : INT := 0; 

    // Kinematics and Sway Control Parameters
    rEffectiveAccel : REAL;
    rNaturalFreq : REAL;
    rDampingRatio : REAL := 0.05;
    rCableLength : REAL := 15000.0; // Max height of mast in mm

    // Trajectory generation internal variables
    rCurrentPos_X : REAL := 0.0;
    rCurrentVel_X : REAL := 0.0;
    rCurrentPos_Y : REAL := 0.0;
    rCurrentVel_Y : REAL := 0.0;

    // Dynamic Bin Slotting
    aBinArray : ARRAY[0..99, 0..49] OF STRUCT
        bOccupied : BOOL;
        rWeightLimits : REAL;
        nPriority : INT;
    END_STRUCT;

    // Timers
    tCycleTime : TIME := T#10ms;
    rCycleTimeS : REAL := 0.01;
END_VAR

// Implementation
IF NOT bEstop THEN
    bError := TRUE;
    nErrorID := 999;
    bMoving := FALSE;
    bReady := FALSE;
    rCmdAccel_X := 0.0;
    rCmdVel_X := 0.0;
    rCmdAccel_Y := 0.0;
    rCmdVel_Y := 0.0;
    nState := 0;
    RETURN;
END_IF;

CASE nState OF
    0: // Idle / Init
        bReady := TRUE;
        bMoving := FALSE;
        bInPosition := FALSE;
        IF bEnable AND bExecuteMove THEN
            bReady := FALSE;
            nState := 10;
        END_IF;

    10: // Calculate Load-Dependent Kinematics
        // Reduce acceleration based on load mass
        IF rLoadMass > 1000.0 THEN
            rEffectiveAccel := rMaxAccel * 0.5;
        ELSIF rLoadMass > 500.0 THEN
            rEffectiveAccel := rMaxAccel * 0.75;
        ELSE
            rEffectiveAccel := rMaxAccel;
        END_IF;

        // Calculate natural frequency for sway control (pendulum approximation)
        // w = sqrt(g / L), g = 9810 mm/s^2
        IF rCurrentPos_Y < rCableLength THEN
            rNaturalFreq := SQRT(9810.0 / (rCableLength - rCurrentPos_Y + 100.0));
        ELSE
            rNaturalFreq := SQRT(9810.0 / 100.0);
        END_IF;
        nState := 20;

    20: // Profile Generation & Sway Compensation (X Axis)
        bMoving := TRUE;

        // Simple P-Control for position with velocity feedforward
        rCmdVel_X := (rTargetPos_X - rCurrentPos_X) * 2.0; 

        // Clamp velocity
        IF rCmdVel_X > rMaxVel THEN
            rCmdVel_X := rMaxVel;
        ELSIF rCmdVel_X < -rMaxVel THEN
            rCmdVel_X := -rMaxVel;
        END_IF;

        // Calculate required acceleration
        rCmdAccel_X := (rCmdVel_X - rCurrentVel_X) / rCycleTimeS;

        // Clamp acceleration based on load
        IF rCmdAccel_X > rEffectiveAccel THEN
            rCmdAccel_X := rEffectiveAccel;
        ELSIF rCmdAccel_X < -rEffectiveAccel THEN
            rCmdAccel_X := -rEffectiveAccel;
        END_IF;

        // Sway Compensation shaping (Input Shaping approximation)
        // Adjust acceleration to cancel out pendulum swing
        rSwayCorrection_X := rCmdAccel_X * SIN(rNaturalFreq * rCycleTimeS) * EXP(-rDampingRatio * rNaturalFreq * rCycleTimeS);
        rCmdAccel_X := rCmdAccel_X - rSwayCorrection_X;

        // Integrate to get final commanded values
        rCmdVel_X := rCurrentVel_X + rCmdAccel_X * rCycleTimeS;
        rCmdPos_X := rCurrentPos_X + rCmdVel_X * rCycleTimeS;

        rCurrentVel_X := rCmdVel_X;
        rCurrentPos_X := rCmdPos_X;

        // Y Axis (Vertical) movement - simpler profile, no sway
        rCmdVel_Y := (rTargetPos_Y - rCurrentPos_Y) * 2.0;
        IF rCmdVel_Y > rMaxVel THEN rCmdVel_Y := rMaxVel; END_IF;
        IF rCmdVel_Y < -rMaxVel THEN rCmdVel_Y := -rMaxVel; END_IF;

        rCmdAccel_Y := (rCmdVel_Y - rCurrentVel_Y) / rCycleTimeS;
        IF rCmdAccel_Y > rEffectiveAccel THEN rCmdAccel_Y := rEffectiveAccel; END_IF;
        IF rCmdAccel_Y < -rEffectiveAccel THEN rCmdAccel_Y := -rEffectiveAccel; END_IF;

        rCmdVel_Y := rCurrentVel_Y + rCmdAccel_Y * rCycleTimeS;
        rCmdPos_Y := rCurrentPos_Y + rCmdVel_Y * rCycleTimeS;

        rCurrentVel_Y := rCmdVel_Y;
        rCurrentPos_Y := rCmdPos_Y;

        // Check In-Position
        IF ABS(rTargetPos_X - rCurrentPos_X) < 1.0 AND ABS(rTargetPos_Y - rCurrentPos_Y) < 1.0 AND ABS(rCurrentVel_X) < 0.1 AND ABS(rCurrentVel_Y) < 0.1 THEN
            bInPosition := TRUE;
            bMoving := FALSE;
            IF NOT bExecuteMove THEN
                nState := 0;
            END_IF;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK\n```
