```iec-st
FUNCTION_BLOCK FB_Marine_H2_Ferry_PMS
VAR_INPUT
    bEnableSystem          : BOOL;     (* System master enable *)
    bEmergencyStop         : BOOL;     (* Safety loop OK signal, False = Estop *)
    rVesselLoadkW          : REAL;     (* Current dynamic vessel load demand in kW *)
    rFCStack1Volt          : REAL;     (* Fuel Cell Stack 1 Output Voltage (V) *)
    rFCStack2Volt          : REAL;     (* Fuel Cell Stack 2 Output Voltage (V) *)
    rSupercapSOC           : REAL;     (* Supercapacitor Bank State of Charge (0.0-100.0%) *)
    bShorePowerConn        : BOOL;     (* Cold-ironing shore power connected signal *)
    rShorePowerPhaseDiff   : REAL;     (* Phase difference for shore synchronization (deg) *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;     (* PMS is operational and ready *)
    bFaultAlarm            : BOOL;     (* Critical fault alarm *)
    rFC1SetPointkW         : REAL;     (* Load setpoint sent to Fuel Cell Stack 1 (kW) *)
    rFC2SetPointkW         : REAL;     (* Load setpoint sent to Fuel Cell Stack 2 (kW) *)
    rSupercapCmdkW         : REAL;     (* Charge/Discharge command to Supercapacitor (kW, + is discharge) *)
    bShoreSyncEnable       : BOOL;     (* Enable shore power synchronization contactor *)
END_VAR
VAR
    iMainState             : INT := 0; (* Main State Machine Step *)
    rFilteredLoad          : REAL;     (* Low-pass filtered load demand *)
    rSupercapCapacity      : REAL := 2000.0; (* Max kW of Supercapacitor bank *)
    rFCMaxCapacity         : REAL := 5000.0; (* Max kW per Fuel Cell stack *)
    rLoadDelta             : REAL;
    tSyncTimer             : TON;
    tEstopDelay            : TON;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks & Emergency Stop *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bFaultAlarm := TRUE;
    rFC1SetPointkW := 0.0;
    rFC2SetPointkW := 0.0;
    rSupercapCmdkW := 0.0;
    bShoreSyncEnable := FALSE;
    iMainState := 99; (* Fault State *)
    RETURN;
END_IF;

(* 2. Sensor Noise Filtering - First Order Low Pass Filter for Vessel Load *)
rFilteredLoad := rFilteredLoad + 0.1 * (rVesselLoadkW - rFilteredLoad);

(* 3. State Machine for Power Management *)
CASE iMainState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := FALSE;
        bFaultAlarm := FALSE;
        rFC1SetPointkW := 0.0;
        rFC2SetPointkW := 0.0;
        rSupercapCmdkW := 0.0;
        bShoreSyncEnable := FALSE;
        IF bEnableSystem THEN
            iMainState := 10;
        END_IF;

    10: (* PRE-CHARGE SUPERCAPACITORS *)
        bSystemReady := FALSE;
        (* Keep FCs at minimum load to charge caps if low *)
        IF rSupercapSOC < 80.0 THEN
            rFC1SetPointkW := 500.0;
            rFC2SetPointkW := 500.0;
            rSupercapCmdkW := -900.0; (* Charging *)
        ELSE
            iMainState := 20;
        END_IF;

    20: (* NORMAL OPERATION (AT SEA) *)
        bSystemReady := TRUE;

        (* Load Sharing Algorithm (Symmetric split) *)
        rFC1SetPointkW := LIMIT(0.0, rFilteredLoad / 2.0, rFCMaxCapacity);
        rFC2SetPointkW := LIMIT(0.0, rFilteredLoad / 2.0, rFCMaxCapacity);

        (* Supercapacitor Transient Buffering *)
        rLoadDelta := rVesselLoadkW - rFilteredLoad;
        IF rLoadDelta > 500.0 AND rSupercapSOC > 20.0 THEN
            (* Rapid load increase, use caps to buffer *)
            rSupercapCmdkW := LIMIT(0.0, rLoadDelta, rSupercapCapacity);
        ELSIF rLoadDelta < -500.0 AND rSupercapSOC < 95.0 THEN
            (* Rapid load drop, absorb energy into caps *)
            rSupercapCmdkW := LIMIT(-rSupercapCapacity, rLoadDelta, 0.0);
        ELSE
            (* Slowly regulate SOC back to 80% *)
            rSupercapCmdkW := (80.0 - rSupercapSOC) * -10.0; 
        END_IF;

        (* Check for Shore Connection *)
        IF bShorePowerConn THEN
            iMainState := 30;
        END_IF;

    30: (* COLD IRONING SYNCHRONIZATION *)
        bSystemReady := TRUE;

        (* Phase Matching Logic *)
        IF ABS(rShorePowerPhaseDiff) < 2.5 THEN
            tSyncTimer(IN := TRUE, PT := T#2S);
            IF tSyncTimer.Q THEN
                bShoreSyncEnable := TRUE;
                iMainState := 40;
            END_IF;
        ELSE
            tSyncTimer(IN := FALSE, PT := T#2S);
            bShoreSyncEnable := FALSE;
        END_IF;

        (* Maintain base load while syncing *)
        rFC1SetPointkW := 200.0;
        rFC2SetPointkW := 200.0;

    40: (* SHORE POWER ACTIVE (IN PORT) *)
        bSystemReady := TRUE;
        bShoreSyncEnable := TRUE;
        rFC1SetPointkW := 0.0;
        rFC2SetPointkW := 0.0;
        rSupercapCmdkW := 0.0;

        IF NOT bShorePowerConn THEN
            bShoreSyncEnable := FALSE;
            iMainState := 20;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bShoreSyncEnable := FALSE;
        IF bEmergencyStop AND bEnableSystem THEN
            iMainState := 0; (* Reset sequence *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
