TYPE E_HydroMode :
(
    HM_STOP := 0,
    HM_TURBINE := 1,
    HM_PUMP := 2,
    HM_SYNC_CONDENSER := 3
);
END_TYPE

TYPE E_HydroState :
(
    HS_OFF := 0,
    HS_PRE_START_CHECKS := 10,
    HS_SPHERICAL_VALVE_OPENING := 20,
    HS_PRIMING_PUMP := 30,
    HS_ACCELERATING := 40,
    HS_SYNCHRONIZING := 50,
    HS_ON_GRID := 60,
    HS_SHUTDOWN_SEQ := 70,
    HS_EMERGENCY_STOP := 99
);
END_TYPE

FUNCTION_BLOCK FB_HydroPumpedStorageControl
VAR_INPUT
    bEnableSystem : BOOL;
    bEmergencyStop : BOOL;
    eCmdMode : E_HydroMode;
    rGridFrequency_Hz : REAL;
    rGridVoltage_kV : REAL;
    rUpperResLevel_m : REAL;
    rLowerResLevel_m : REAL;
    rPenstockPressure_bar : REAL;
    rSpiralCasePressure_bar : REAL;
    rGuideVanePos_pct : REAL;
    rRotorSpeed_rpm : REAL;
    bSyncRelayOk : BOOL;
    rTargetPower_MW : REAL;
END_VAR
VAR_OUTPUT
    eActiveState : E_HydroState;
    bSphericalValveCmd : BOOL;
    bGuideVaneCmd : BOOL;
    rGuideVaneTarget_pct : REAL;
    bMainBreakerCmd : BOOL;
    bPonyMotorCmd : BOOL;
    bCoolingWaterCmd : BOOL;
    bBrakeApplyCmd : BOOL;
    rActivePowerSet_MW : REAL;
    bSystemFault : BOOL;
    sFaultCode : STRING[32];
END_VAR
VAR
    FSM_Timer : TON;
    Valve_Timer : TON;
    Sync_Timer : TON;
    rNominalFreq : REAL := 50.0;
    rFreqDeadband : REAL := 0.05;
    rDroopFactor : REAL := 0.04; // 4% droop
    rPowerMax_MW : REAL := 300.0;
    bValveOpened : BOOL;
    bGridSyncComplete : BOOL;
END_VAR

// Logic implementation
IF bEmergencyStop THEN
    eActiveState := HS_EMERGENCY_STOP;
ELSIF NOT bEnableSystem THEN
    eActiveState := HS_OFF;
END_IF;

// Grid Frequency Containment Reserves (FCR) calculation
IF (eActiveState = HS_ON_GRID AND eCmdMode = HM_TURBINE) THEN
    IF rGridFrequency_Hz > (rNominalFreq + rFreqDeadband) THEN
        // Overspeed, reduce power
        rActivePowerSet_MW := rTargetPower_MW - ((rGridFrequency_Hz - rNominalFreq - rFreqDeadband) / (rNominalFreq * rDroopFactor)) * rPowerMax_MW;
    ELSIF rGridFrequency_Hz < (rNominalFreq - rFreqDeadband) THEN
        // Underspeed, increase power
        rActivePowerSet_MW := rTargetPower_MW + ((rNominalFreq - rFreqDeadband - rGridFrequency_Hz) / (rNominalFreq * rDroopFactor)) * rPowerMax_MW;
    ELSE
        rActivePowerSet_MW := rTargetPower_MW;
    END_IF;

    // Clamping limits
    IF rActivePowerSet_MW > rPowerMax_MW THEN rActivePowerSet_MW := rPowerMax_MW; END_IF;
    IF rActivePowerSet_MW < 0.0 THEN rActivePowerSet_MW := 0.0; END_IF;
END_IF;

// Main State Machine
CASE eActiveState OF
    HS_OFF:
        bSphericalValveCmd := FALSE;
        bGuideVaneCmd := FALSE;
        bMainBreakerCmd := FALSE;
        bPonyMotorCmd := FALSE;
        bCoolingWaterCmd := FALSE;
        bBrakeApplyCmd := rRotorSpeed_rpm < 10.0;
        IF bEnableSystem AND eCmdMode <> HM_STOP THEN
            eActiveState := HS_PRE_START_CHECKS;
        END_IF;

    HS_PRE_START_CHECKS:
        bBrakeApplyCmd := FALSE;
        bCoolingWaterCmd := TRUE;
        IF rPenstockPressure_bar > 40.0 AND rUpperResLevel_m > 300.0 THEN
            eActiveState := HS_SPHERICAL_VALVE_OPENING;
            Valve_Timer(IN:=FALSE);
        ELSE
            bSystemFault := TRUE;
            sFaultCode := 'ERR_PRECHECK_FAIL';
            eActiveState := HS_OFF;
        END_IF;

    HS_SPHERICAL_VALVE_OPENING:
        bSphericalValveCmd := TRUE;
        Valve_Timer(IN:=TRUE, PT:=T#60S);
        IF rSpiralCasePressure_bar >= (rPenstockPressure_bar * 0.95) THEN
            IF eCmdMode = HM_TURBINE THEN
                eActiveState := HS_ACCELERATING;
            ELSIF eCmdMode = HM_PUMP THEN
                eActiveState := HS_PRIMING_PUMP;
            END_IF;
        ELSIF Valve_Timer.Q THEN
            bSystemFault := TRUE;
            sFaultCode := 'ERR_VALVE_TIMEOUT';
            eActiveState := HS_SHUTDOWN_SEQ;
        END_IF;

    HS_PRIMING_PUMP:
        // Use pony motor for pump mode start
        bPonyMotorCmd := TRUE;
        IF rRotorSpeed_rpm >= 500.0 THEN // synchronous speed 500 rpm
            eActiveState := HS_SYNCHRONIZING;
        END_IF;

    HS_ACCELERATING:
        // Open guide vanes to accelerate turbine
        bGuideVaneCmd := TRUE;
        rGuideVaneTarget_pct := 15.0; // speed-no-load position
        IF rRotorSpeed_rpm >= 495.0 AND rRotorSpeed_rpm <= 505.0 THEN
            eActiveState := HS_SYNCHRONIZING;
            Sync_Timer(IN:=FALSE);
        END_IF;

    HS_SYNCHRONIZING:
        Sync_Timer(IN:=TRUE, PT:=T#120S);
        // Automatic Voltage Regulator and Auto-Synchronizer take over here
        IF bSyncRelayOk THEN
            bMainBreakerCmd := TRUE;
            bPonyMotorCmd := FALSE;
            eActiveState := HS_ON_GRID;
        ELSIF Sync_Timer.Q THEN
            bSystemFault := TRUE;
            sFaultCode := 'ERR_SYNC_TIMEOUT';
            eActiveState := HS_SHUTDOWN_SEQ;
        END_IF;

    HS_ON_GRID:
        IF eCmdMode = HM_STOP THEN
            eActiveState := HS_SHUTDOWN_SEQ;
        END_IF;
        IF eCmdMode = HM_TURBINE THEN
            rGuideVaneTarget_pct := (rActivePowerSet_MW / rPowerMax_MW) * 100.0;
        END_IF;

    HS_SHUTDOWN_SEQ:
        bMainBreakerCmd := FALSE;
        rGuideVaneTarget_pct := 0.0;
        IF rGuideVanePos_pct < 2.0 THEN
            bSphericalValveCmd := FALSE;
        END_IF;
        IF rRotorSpeed_rpm < 50.0 THEN
            bBrakeApplyCmd := TRUE;
        END_IF;
        IF rRotorSpeed_rpm < 1.0 THEN
            bCoolingWaterCmd := FALSE;
            eActiveState := HS_OFF;
        END_IF;

    HS_EMERGENCY_STOP:
        bMainBreakerCmd := FALSE;
        bSphericalValveCmd := FALSE;
        rGuideVaneTarget_pct := 0.0;
        bSystemFault := TRUE;
        IF rRotorSpeed_rpm < 50.0 THEN
            bBrakeApplyCmd := TRUE;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
