FUNCTION_BLOCK "RO_Skid_Control"
VERSION : 0.1
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      Feed_Pressure : Real;
      Permeate_Pressure : Real;
      Permeate_Flow : Real;
      Pressure_Setpoint : Real;
      Backwash_Req : Bool;
   END_VAR

   VAR_OUTPUT
      High_Pressure_Pump : Bool;
      Permeate_Valve : Real;
      Backwash_Pump : Bool;
      Backwash_Valve : Bool;
      Status : Int;
   END_VAR

   VAR
      State : Int;
      PID_Ctrl : "PID_Compact";
      Tmr_Backwash : TON;
   END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    ELSIF Backwash_Req AND State = 1 THEN
        State := 2;
    END_IF;

    #PID_Ctrl(Setpoint := Pressure_Setpoint, Input := Permeate_Pressure, Reset := (State <> 1));

    CASE State OF
        0:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Status := 0;
        1:
            High_Pressure_Pump := TRUE;
            Permeate_Valve := #PID_Ctrl.Output;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Status := 1;
        2:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Valve := TRUE;
            Tmr_Backwash(IN:=TRUE, PT:=T#5m);
            IF Tmr_Backwash.Q THEN
                Backwash_Pump := FALSE;
                Backwash_Valve := FALSE;
                Tmr_Backwash(IN:=FALSE, PT:=T#5m);
                State := 0;
            ELSE
                Backwash_Pump := TRUE;
            END_IF;
            Status := 2;
    END_CASE;
END_FUNCTION_BLOCK
