FUNCTION_BLOCK FB_HTS_Payload_Assembly
VAR_INPUT
    bStartAssemblySequence : BOOL; // Initiate the HTS payload assembly sequence
    bEStop : BOOL; // Emergency stop
    rIsoKineticFlowRate : REAL; // Airflow rate for cleanroom iso-kinetic sampling (m3/s)
    rVacuumChamberPressure : REAL; // Current pressure in bake-out chamber (Torr)
    rChamberTemp : REAL; // Current temperature in bake-out chamber (DegC)
    rTargetBakeOutTemp : REAL; // Target temperature for bake-out (DegC)
    rSolarArrayAngle : REAL; // Current deployment angle of solar arrays (Degrees)
END_VAR
VAR_OUTPUT
    bCleanroomStatusOk : BOOL; // True if iso-kinetic sampling is within bounds
    bVacuumBakeOutComplete : BOOL; // True when bake-out process finishes
    bSolarArrayDeployed : BOOL; // True when kinematics test confirms deployment
    rHeaterControlSignal : REAL; // PID output for vacuum bake-out heater (0-100%)
    rDeploymentMotorTorque : REAL; // Kinematics output torque for solar array (Nm)
    iAssemblyState : INT; // Current state of the assembly state machine
END_VAR
VAR
    // PID variables for Vacuum Bake-out
    rKp_Heater : REAL := 2.5;
    rKi_Heater : REAL := 0.1;
    rKd_Heater : REAL := 0.5;
    rError : REAL;
    rLastError : REAL;
    rIntegral : REAL;
    rDerivative : REAL;

    // Kinematics parameters
    rTargetAngle : REAL := 90.0;
    rAngleTolerance : REAL := 0.5;
    rMaxTorque : REAL := 50.0;

    // Iso-kinetic sampling parameters
    rMinFlowRate : REAL := 1.2;
    rMaxFlowRate : REAL := 1.8;

    // Timers
    tBakeOutTimer : TON;
    tDeploymentTimer : TON;

    bInitDone : BOOL := FALSE;
END_VAR

// Initialization
IF NOT bInitDone THEN
    iAssemblyState := 0;
    bCleanroomStatusOk := FALSE;
    bVacuumBakeOutComplete := FALSE;
    bSolarArrayDeployed := FALSE;
    rHeaterControlSignal := 0.0;
    rDeploymentMotorTorque := 0.0;
    bInitDone := TRUE;
END_IF;

// Emergency Stop override
IF bEStop THEN
    iAssemblyState := 999;
    rHeaterControlSignal := 0.0;
    rDeploymentMotorTorque := 0.0;
END_IF;

// State Machine
CASE iAssemblyState OF
    0: // Idle
        IF bStartAssemblySequence AND NOT bEStop THEN
            iAssemblyState := 10;
        END_IF;

    10: // Cleanroom Iso-Kinetic Sampling Verification
        IF rIsoKineticFlowRate >= rMinFlowRate AND rIsoKineticFlowRate <= rMaxFlowRate THEN
            bCleanroomStatusOk := TRUE;
            iAssemblyState := 20; // Proceed to bake-out
        ELSE
            bCleanroomStatusOk := FALSE;
            // Stay in this state or trigger alarm
        END_IF;

    20: // Vacuum Bake-Out PID Cascade
        // Simple PID implementation for heater
        rError := rTargetBakeOutTemp - rChamberTemp;
        rIntegral := rIntegral + rError;
        rDerivative := rError - rLastError;
        rHeaterControlSignal := (rKp_Heater * rError) + (rKi_Heater * rIntegral) + (rKd_Heater * rDerivative);
        rLastError := rError;

        // Clamp output
        IF rHeaterControlSignal > 100.0 THEN
            rHeaterControlSignal := 100.0;
        ELSIF rHeaterControlSignal < 0.0 THEN
            rHeaterControlSignal := 0.0;
        END_IF;

        // Check if temperature reached and vacuum is sufficient
        IF (rError < 2.0 AND rError > -2.0) AND (rVacuumChamberPressure < 0.001) THEN
            tBakeOutTimer(IN := TRUE, PT := T#24H);
            IF tBakeOutTimer.Q THEN
                bVacuumBakeOutComplete := TRUE;
                rHeaterControlSignal := 0.0;
                tBakeOutTimer(IN := FALSE);
                iAssemblyState := 30; // Proceed to kinematics
            END_IF;
        ELSE
            tBakeOutTimer(IN := FALSE);
        END_IF;

    30: // Solar Array Deployment Testing Kinematics
        IF ABS(rTargetAngle - rSolarArrayAngle) > rAngleTolerance THEN
            // Proportional torque control based on angular distance
            rDeploymentMotorTorque := (rTargetAngle - rSolarArrayAngle) * 1.5;
            // Torque limit
            IF rDeploymentMotorTorque > rMaxTorque THEN
                rDeploymentMotorTorque := rMaxTorque;
            ELSIF rDeploymentMotorTorque < -rMaxTorque THEN
                rDeploymentMotorTorque := -rMaxTorque;
            END_IF;
            tDeploymentTimer(IN := FALSE);
        ELSE
            // Stop motor
            rDeploymentMotorTorque := 0.0;
            tDeploymentTimer(IN := TRUE, PT := T#5S); // Wait for stabilization
            IF tDeploymentTimer.Q THEN
                bSolarArrayDeployed := TRUE;
                iAssemblyState := 100; // Success
            END_IF;
        END_IF;

    100: // Assembly Complete
        // End of sequence

    999: // E-Stop / Fault State
        bCleanroomStatusOk := FALSE;
        rHeaterControlSignal := 0.0;
        rDeploymentMotorTorque := 0.0;

END_CASE;
END_FUNCTION_BLOCK
```

