// X-Ray FEL Undulator Magnetic Gap & Electron Bunch Compressor Controller
// Standard: IEC 61131-3 Structured Text (ST)
// Application: Hard X-Ray Free-Electron Laser (XFEL)
// Focus: Sub-micron gap tapering and femtosecond bunch compression (Chicane)

TYPE E_PackML_State :
(
    eSTATE_UNDEFINED := 0,
    eSTATE_CLEARING := 1,
    eSTATE_STOPPED := 2,
    eSTATE_STARTING := 3,
    eSTATE_IDLE := 4,
    eSTATE_SUSPENDED := 5,
    eSTATE_EXECUTE := 6,
    eSTATE_STOPPING := 7,
    eSTATE_ABORTING := 8,
    eSTATE_ABORTED := 9,
    eSTATE_HOLDING := 10,
    eSTATE_HELD := 11
);
END_TYPE

TYPE ST_TwissParameters :
STRUCT
    BetaX  : LREAL; // Horizontal betatron function (m)
    AlphaX : LREAL; // Horizontal phase space tilt
    GammaX : LREAL; // Horizontal beam distribution parameter (m^-1)
    BetaY  : LREAL; // Vertical betatron function (m)
    AlphaY : LREAL; // Vertical phase space tilt
    GammaY : LREAL; // Vertical beam distribution parameter (m^-1)
    EmittanceX : LREAL; // Normalized horizontal emittance (m-rad)
    EmittanceY : LREAL; // Normalized vertical emittance (m-rad)
END_STRUCT
END_TYPE

TYPE ST_ChicaneConfig :
STRUCT
    BendingAngle     : LREAL; // Dipole bending angle (rad)
    DispersionMax    : LREAL; // Maximum dispersion Dx (m)
    MomentumComp_R56 : LREAL; // Longitudinal momentum compaction R56 (m)
    ChirpPhase       : LREAL; // RF chirp phase (degrees, nominal +90 for off-crest)
    ChirpAmplitude   : LREAL; // RF chirp gradient (MV/m)
    TargetCurrent    : LREAL; // Target peak current (kA)
END_STRUCT
END_TYPE

TYPE ST_UndulatorSegment :
STRUCT
    K_Parameter      : LREAL; // Undulator deflection parameter
    PeriodLength     : LREAL; // Magnetic period length (m)
    GapInitial       : LREAL; // Nominal magnetic gap (mm)
    GapTaper         : LREAL; // Applied taper (mm)
    ActualGap        : LREAL; // Encoder feedback (mm)
    MotorPos_Top     : LREAL; // Top girder stepper position (mm)
    MotorPos_Bottom  : LREAL; // Bottom girder stepper position (mm)
    StatusWord       : DWORD;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_XFEL_UndulatorController
VAR_INPUT
    bEnable          : BOOL;
    bAbort           : BOOL;
    bReset           : BOOL;
    BeamEnergy_GeV   : LREAL := 14.0; // Nominal 14 GeV
    Charge_pC        : LREAL := 250.0;
    XRayWavelength   : LREAL := 0.1; // Target wavelength in nm
    TwissCurrent     : ST_TwissParameters;
    ChicaneParams    : ST_ChicaneConfig;
END_VAR

VAR_OUTPUT
    CurrentState     : E_PackML_State;
    CompressionRatio : LREAL;
    PeakCurrent_kA   : LREAL;
    SasePower_GW     : LREAL;
    bResonanceLocked : BOOL;
    bError           : BOOL;
    nErrorID         : UDINT;
END_VAR

VAR
    // PackML State Machine
    StateTimer       : TON;

    // Arrays for 50-meter long undulator (e.g., 35 segments)
    UndulatorSegments : ARRAY[1..35] OF ST_UndulatorSegment;

    // Physics constants
    c_SpeedOfLight   : LREAL := 299792458.0;
    e_ElectronCharge : LREAL := 1.602176634E-19;
    m_ElectronMass   : LREAL := 0.510998950; // MeV/c^2

    // Internal Variables
    GammaRelativistic : LREAL;
    EnergyLossRate   : LREAL; // Energy loss due to SASE per segment
    i                : INT;
    TaperDeltaK      : LREAL;

    // Chicane control
    DipoleField_B    : LREAL; // Tesla
    PhaseError       : LREAL;

    // Filters & PIDs
    RFCavityPID_Kp   : LREAL := 1.5;
    RFCavityPID_Ki   : LREAL := 0.05;
    RFCavityErrorInt : LREAL;
END_VAR

// -----------------------------------------------------------------------------
// MAIN EXECUTION
// -----------------------------------------------------------------------------

// 1. PackML State Machine Evaluation
IF bAbort THEN
    CurrentState := eSTATE_ABORTING;
ELSIF CurrentState = eSTATE_UNDEFINED THEN
    CurrentState := eSTATE_STOPPED;
END_IF;

CASE CurrentState OF
    eSTATE_STOPPED:
        IF bEnable THEN
            CurrentState := eSTATE_STARTING;
        END_IF

    eSTATE_STARTING:
        // Initialize physics parameters
        GammaRelativistic := (BeamEnergy_GeV * 1000.0) / m_ElectronMass;
        bResonanceLocked := FALSE;
        CurrentState := eSTATE_EXECUTE;

    eSTATE_EXECUTE:
        IF NOT bEnable THEN
            CurrentState := eSTATE_STOPPING;
        ELSE
            // Continuously evaluate XFEL dynamics
            ExecuteBunchCompression();
            ExecuteGapTapering();
            CalculateSasePower();

            // Fault detection
            IF bError THEN
                CurrentState := eSTATE_HOLDING;
            END_IF
        END_IF

    eSTATE_STOPPING:
        // Safe ramp down of magnetic fields
        DipoleField_B := DipoleField_B * 0.95; 
        IF DipoleField_B < 0.001 THEN
            CurrentState := eSTATE_STOPPED;
        END_IF

    eSTATE_HOLDING:
        IF bReset THEN
            bError := FALSE;
            CurrentState := eSTATE_STARTING;
        END_IF

    eSTATE_ABORTING:
        DipoleField_B := 0.0;
        bResonanceLocked := FALSE;
        CurrentState := eSTATE_ABORTED;

    eSTATE_ABORTED:
        IF bReset THEN
            bError := FALSE;
            CurrentState := eSTATE_STOPPED;
        END_IF
END_CASE

// -----------------------------------------------------------------------------
// METHODS / INTERNAL ACTIONS
// -----------------------------------------------------------------------------

ACTION ExecuteBunchCompression:
    // Electron Bunch Compression (Chicane)
    // Regulate RF cavity chirp phase to exactly +90 off-crest (zero-crossing)
    PhaseError := 90.0 - ChicaneParams.ChirpPhase;

    // PI Controller for RF Chirp
    RFCavityErrorInt := RFCavityErrorInt + (PhaseError * 0.001); // 1ms cycle time
    ChicaneParams.ChirpAmplitude := ChicaneParams.ChirpAmplitude + (RFCavityPID_Kp * PhaseError) + (RFCavityPID_Ki * RFCavityErrorInt);

    // Calculate required Chicane Dipole Field based on R56 and Energy
    // R56 ~ 2 * theta^2 * L_drift
    // B = p / (e * rho)
    DipoleField_B := (BeamEnergy_GeV * 1E9) / (c_SpeedOfLight * ChicaneParams.DispersionMax);

    // Idealized Compression Ratio calculation
    // R56 * h (chirp) ~ 1 for maximum compression
    CompressionRatio := 1.0 / (1.0 - (ChicaneParams.MomentumComp_R56 * ChicaneParams.ChirpAmplitude / BeamEnergy_GeV));

    // Prevent singularity
    IF CompressionRatio > 1000.0 THEN
        CompressionRatio := 1000.0;
    END_IF;

    PeakCurrent_kA := (Charge_pC * 1E-12) / (1E-12 / CompressionRatio) * 1E-3; // roughly estimated
END_ACTION

ACTION ExecuteGapTapering:
    // Undulator Magnetic Gap Tapering
    // Resonance condition: Lambda_X = (Lambda_U / 2*Gamma^2) * (1 + K^2/2)
    // As beam loses energy to X-rays, Gamma decreases, so K must decrease (gap opens).

    // Initial uniform energy
    GammaRelativistic := (BeamEnergy_GeV * 1000.0) / m_ElectronMass;

    bResonanceLocked := TRUE;

    FOR i := 1 TO 35 DO
        // SASE Energy loss cumulative per segment (simplified empirical model)
        EnergyLossRate := 0.0005 * PeakCurrent_kA * (i * i); 

        // Local Gamma for segment i
        GammaRelativistic := GammaRelativistic - EnergyLossRate;

        // Target K parameter for resonance at target wavelength
        // K = sqrt(2 * (Lambda_X * 2 * Gamma^2 / Lambda_U - 1))
        TaperDeltaK := 2.0 * ((XRayWavelength * 1E-9) * 2.0 * (GammaRelativistic * GammaRelativistic) / UndulatorSegments[i].PeriodLength) - 1.0;

        IF TaperDeltaK > 0 THEN
            UndulatorSegments[i].K_Parameter := SQRT(TaperDeltaK);
        ELSE
            bResonanceLocked := FALSE; // Lost resonance
        END_IF

        // Convert K to Gap (mm) - empirical Halbach array exponential fit
        // K = a * exp(-b * Gap / Period)
        // Gap = -(Period / b) * ln(K / a)
        // For simplicity, using a generalized linear taper approach:
        UndulatorSegments[i].GapTaper := 0.0125 * i * EnergyLossRate; // Taper proportional to energy loss

        // Output to stepper motors (micron level)
        UndulatorSegments[i].MotorPos_Top := (UndulatorSegments[i].GapInitial + UndulatorSegments[i].GapTaper) / 2.0;
        UndulatorSegments[i].MotorPos_Bottom := -(UndulatorSegments[i].GapInitial + UndulatorSegments[i].GapTaper) / 2.0;

        // Sub-micron error checking
        IF ABS(UndulatorSegments[i].ActualGap - (UndulatorSegments[i].GapInitial + UndulatorSegments[i].GapTaper)) > 0.005 THEN // 5 microns tolerance
            bError := TRUE;
            nErrorID := 100 + INT_TO_UDINT(i); // Segment error
        END_IF
    END_FOR
END_ACTION

ACTION CalculateSasePower:
    // Estimate SASE Peak Power generated
    // P ~ rho * P_beam
    // Pierce parameter rho ~ 1e-3
    IF bResonanceLocked THEN
        SasePower_GW := (0.001) * BeamEnergy_GeV * PeakCurrent_kA;
    ELSE
        SasePower_GW := 0.0;
    END_IF
END_ACTION

END_FUNCTION_BLOCK
```

