FUNCTION_BLOCK "CIP_System_Mut4"
VERSION : 0.1
VAR_INPUT
    Conductivity_Raw : Real;
    HIL_Heartbeat : Bool;
    Start_CIP : Bool;
END_VAR
VAR_OUTPUT
    System_Halted : Bool;
    Self_Test_Pass : Bool;
    Drift_Alarm : Bool;
END_VAR
VAR
    CIP_State : Int := -1;
    Cond_History : ARRAY[0..99] OF Real;
    Cond_Index : Int := 0;
    Cond_Sum : Real;
    Cond_Avg : Real;
    HIL_Watchdog : TON_TIME;
END_VAR

BEGIN
    HIL_Watchdog(IN := NOT HIL_Heartbeat, PT := T#2S);
    IF HIL_Watchdog.Q THEN
        System_Halted := TRUE;
        RETURN;
    ELSE
        System_Halted := FALSE;
    END_IF;

    Cond_Sum := Cond_Sum - Cond_History[Cond_Index] + Conductivity_Raw;
    Cond_History[Cond_Index] := Conductivity_Raw;
    Cond_Index := (Cond_Index + 1) MOD 100;
    Cond_Avg := Cond_Sum / 100.0;
    IF ABS(Conductivity_Raw - Cond_Avg) > 15.0 THEN
        Drift_Alarm := TRUE;
    END_IF;

    CASE CIP_State OF
        -1:
            IF Start_CIP THEN
                Self_Test_Pass := TRUE;
                CIP_State := 0;
            END_IF;
        0: 
            IF Start_CIP AND Self_Test_Pass THEN CIP_State := 1; END_IF;
        1: 
            IF Conductivity_Raw < 0.5 THEN CIP_State := 2; END_IF;
        2:
            IF Conductivity_Raw > 50.0 THEN CIP_State := 3; END_IF;
        3:
            IF Conductivity_Raw > 30.0 THEN CIP_State := 4; END_IF;
        4:
            CIP_State := 5;
        5:
            IF NOT Start_CIP THEN CIP_State := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
