END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Ready to charge/discharge energy *)
    rVacuumPumpControl_Pct  : REAL;     (* Vacuum turbomolecular pump speed command in percentage (0.0 to 100.0%) *)
