FUNCTION_BLOCK FB_MeatSlicingAndMAP
VAR_INPUT
    bEnable                 : BOOL;   (* Master enable for the line *)
    bStart                  : BOOL;   (* Start slicing and packaging *)
    bStop                   : BOOL;   (* Stop operation smoothly *)
    bEStop                  : BOOL;   (* Emergency stop *)
    rTargetSliceThickness   : REAL;   (* Desired slice thickness in mm *)
    rTargetPortionWeight    : REAL;   (* Desired weight per portion in grams *)
    rBladeSpeedSetpoint     : REAL;   (* Desired blade RPM *)
    rConveyorSpeed          : REAL;   (* Conveyor speed in m/s *)
    rActualPortionWeight    : REAL;   (* Real-time weight from load cell in grams *)
    bWeightReady            : BOOL;   (* Trigger when weight is captured *)
    rTargetO2Level          : REAL;   (* Target Oxygen level % *)
    rTargetCO2Level         : REAL;   (* Target Carbon Dioxide level % *)
    rActualO2Level          : REAL;   (* Measured O2 level % *)
    rActualCO2Level         : REAL;   (* Measured CO2 level % *)
    rChamberPressure        : REAL;   (* Vacuum chamber pressure in mbar *)
    bPackagePresent         : BOOL;   (* Proximity sensor for tray in chamber *)
    bSealBarTempReached     : BOOL;   (* Seal bar temperature OK *)
END_VAR

VAR_OUTPUT
    bSystemRunning          : BOOL;   (* Overall system running status *)
    bFaultActive            : BOOL;   (* Active fault indication *)
    iFaultCode              : INT;    (* Diagnostic fault code *)
    rDriveBladeSpeed        : REAL;   (* Command to blade VFD *)
    rDriveConveyorSpeed     : REAL;   (* Command to conveyor VFD *)
    bRejectPortion          : BOOL;   (* Command to reject pneumatic cylinder *)
    bVacuumValve            : BOOL;   (* Open vacuum pump valve *)
    bGasFlushValve          : BOOL;   (* Open mixed gas flush valve *)
    bSealBarCylinder        : BOOL;   (* Actuate seal bar *)
    bDischargeConveyor      : BOOL;   (* Run outfeed conveyor *)
    rActualSlicesPerMin     : REAL;   (* KPI output *)
END_VAR

VAR
    iSlicerState            : INT := 0; 
    iMAPState               : INT := 0;
    rDynamicSliceAdjustment : REAL := 0.0;
    rWeightError            : REAL := 0.0;
    rTotalWeightRunning     : REAL := 0.0;
    iSliceCount             : INT := 0;
    tSlicerRampUp           : TON;
    tGasFlushDuration       : TON;
    tSealDuration           : TON;
    tRejectPulse            : TON;
    tCycleTimer             : TON;
    cWeightTolerance        : REAL := 5.0;
    cMaxBladeRPM            : REAL := 1500.0;
    cVacuumTarget           : REAL := 15.0;
END_VAR

(* EMERGENCY STOP & FAULT HANDLING *)
IF bEStop OR bFaultActive THEN
    bSystemRunning := FALSE;
    rDriveBladeSpeed := 0.0;
    rDriveConveyorSpeed := 0.0;
    bVacuumValve := FALSE;
    bGasFlushValve := FALSE;
    bSealBarCylinder := FALSE;
    bDischargeConveyor := FALSE;
    iSlicerState := 0;
    iMAPState := 0;
    IF bEStop THEN
        iFaultCode := 9999;
    END_IF;
    RETURN;
END_IF;

(* Master Enable *)
IF NOT bEnable THEN
    bSystemRunning := FALSE;
    RETURN;
END_IF;

IF bStart AND NOT bStop THEN
    bSystemRunning := TRUE;
ELSIF bStop THEN
    bSystemRunning := FALSE;
END_IF;

(* SLICER CONTROL *)
IF bSystemRunning THEN
    CASE iSlicerState OF
        0:
            rDriveBladeSpeed := 0.0;
            rDriveConveyorSpeed := 0.0;
            IF bStart THEN iSlicerState := 10; END_IF;
        10:
            rDriveBladeSpeed := rBladeSpeedSetpoint;
            tSlicerRampUp(IN := TRUE, PT := T#2S);
            IF tSlicerRampUp.Q THEN iSlicerState := 20; END_IF;
        20:
            rDriveConveyorSpeed := rConveyorSpeed;
            IF bWeightReady THEN
                rWeightError := rTargetPortionWeight - rActualPortionWeight;
                IF ABS(rWeightError) > cWeightTolerance THEN bRejectPortion := TRUE; ELSE bRejectPortion := FALSE; END_IF;
                rDynamicSliceAdjustment := rWeightError * 0.05;
                IF rDynamicSliceAdjustment > 2.0 THEN rDynamicSliceAdjustment := 2.0; END_IF;
                IF rDynamicSliceAdjustment < -2.0 THEN rDynamicSliceAdjustment := -2.0; END_IF;
                rDriveConveyorSpeed := rConveyorSpeed + rDynamicSliceAdjustment;
            END_IF;
            tRejectPulse(IN := bRejectPortion, PT := T#500MS);
            IF tRejectPulse.Q THEN bRejectPortion := FALSE; END_IF;
    END_CASE;
ELSE
    tSlicerRampUp(IN := FALSE);
    iSlicerState := 0;
END_IF;

(* MAP SEQUENCE *)
IF bSystemRunning THEN
    CASE iMAPState OF
        0:
            bVacuumValve := FALSE; bGasFlushValve := FALSE; bSealBarCylinder := FALSE; bDischargeConveyor := FALSE;
            IF bPackagePresent THEN iMAPState := 10; END_IF;
        10:
            bVacuumValve := TRUE;
            IF rChamberPressure <= cVacuumTarget THEN
                bVacuumValve := FALSE; iMAPState := 20;
            END_IF;
        20:
            bGasFlushValve := TRUE;
            tGasFlushDuration(IN := TRUE, PT := T#3S);
            IF tGasFlushDuration.Q OR (rActualO2Level <= rTargetO2Level AND rActualCO2Level >= rTargetCO2Level) THEN
                bGasFlushValve := FALSE; tGasFlushDuration(IN := FALSE);
                IF bSealBarTempReached THEN iMAPState := 30; ELSE bFaultActive := TRUE; iFaultCode := 2001; END_IF;
            END_IF;
        30:
            bSealBarCylinder := TRUE;
            tSealDuration(IN := TRUE, PT := T#1500MS);
            IF tSealDuration.Q THEN
                bSealBarCylinder := FALSE; tSealDuration(IN := FALSE); iMAPState := 40;
            END_IF;
        40:
            bDischargeConveyor := TRUE;
            IF NOT bPackagePresent THEN bDischargeConveyor := FALSE; iMAPState := 0; END_IF;
    END_CASE;
ELSE
    tGasFlushDuration(IN := FALSE); tSealDuration(IN := FALSE); iMAPState := 0;
END_IF;
END_FUNCTION_BLOCK
