FUNCTION_BLOCK FB_SynBioFermentor
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal - active high *)
    rDissolvedOxygen        : REAL;     (* Multi-phasic dissolved oxygen mass transfer (DO) in % *)
    rAgitationSpeed         : REAL;     (* Current agitator speed in RPM *)
    rVesselPressure         : REAL;     (* Rapid aseptic sampling loop pressure in bar *)
    rMetaboliteConcentration: REAL;     (* Continuous perfusion metabolite concentration in g/L *)
    rTemperature            : REAL;     (* Process temperature in deg C *)
    rTargetDO               : REAL;     (* Target Dissolved Oxygen % *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* SynBio Fermentor system ready status *)
    rAgitationControl       : REAL;     (* Control signal to agitator VFD (0-100%) *)
    rAirflowControl         : REAL;     (* Control signal to sparger mass flow controller *)
    bSamplingValveOpen      : BOOL;     (* Aseptic sampling loop valve control *)
    bPerfusionPumpEnable    : BOOL;     (* Continuous perfusion pump control *)
    bAlarm                  : BOOL;     (* System critical fault alarm *)
    iCurrentState           : INT;      (* Current state machine step *)
END_VAR
VAR
    iState                  : INT := 0; (* Internal state tracking *)
    tSamplingTimer          : TON;      (* Timer for aseptic sampling duration *)
    tPerfusionTimer         : TON;      (* Timer for perfusion cycle *)
    rDOError                : REAL;     (* Dissolved Oxygen Error *)
    rDOIntegral             : REAL := 0.0;
    rDODerivative           : REAL := 0.0;
    rLastDOError            : REAL := 0.0;
    rKp                     : REAL := 2.5; (* PID Proportional Gain *)
    rKi                     : REAL := 0.1; (* PID Integral Gain *)
    rKd                     : REAL := 0.5; (* PID Derivative Gain *)
    bFilterInit             : BOOL := FALSE;
    rFilteredDO             : REAL;     (* Noise filtered DO signal *)
    rAlpha                  : REAL := 0.2; (* Low pass filter coefficient *)
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rAgitationControl := 0.0;
    rAirflowControl := 0.0;
    bSamplingValveOpen := FALSE;
    bPerfusionPumpEnable := FALSE;
    iState := 999; (* FAULT STATE *)
    iCurrentState := iState;
    RETURN;
END_IF;

(* === SENSOR NOISE FILTERING (First Order Low-Pass) === *)
IF NOT bFilterInit THEN
    rFilteredDO := rDissolvedOxygen;
    bFilterInit := TRUE;
ELSE
    rFilteredDO := rFilteredDO + rAlpha * (rDissolvedOxygen - rFilteredDO);
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rAgitationControl := 10.0; (* Base minimal agitation *)
        rAirflowControl := 5.0;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* FERMENTATION RUNNING - DO CASCADE CONTROL *)
        (* Calculate PID for DO Control *)
        rDOError := rTargetDO - rFilteredDO;
        rDOIntegral := rDOIntegral + rDOError;

        (* Anti-windup limit for integral *)
        IF rDOIntegral > 100.0 THEN rDOIntegral := 100.0; END_IF;
        IF rDOIntegral < -100.0 THEN rDOIntegral := -100.0; END_IF;

        rDODerivative := rDOError - rLastDOError;
        rLastDOError := rDOError;

        (* Cascade Output mapping to Agitation and Airflow *)
        rAgitationControl := (rKp * rDOError) + (rKi * rDOIntegral) + (rKd * rDODerivative);

        IF rAgitationControl > 100.0 THEN
            rAgitationControl := 100.0;
        ELSIF rAgitationControl < 20.0 THEN
            rAgitationControl := 20.0;
        END_IF;

        rAirflowControl := rAgitationControl * 0.5; (* Coupled airflow constraint *)

        (* Aseptic Sampling Trigger Logic based on pressure profiles *)
        IF rVesselPressure > 1.2 AND rMetaboliteConcentration > 5.0 THEN
            iState := 20;
        END_IF;

    20: (* RAPID ASEPTIC SAMPLING *)
        bSamplingValveOpen := TRUE;
        tSamplingTimer(IN := TRUE, PT := T#2S);

        IF tSamplingTimer.Q THEN
            bSamplingValveOpen := FALSE;
            tSamplingTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* CONTINUOUS PERFUSION MAPPING *)
        bPerfusionPumpEnable := TRUE;
        tPerfusionTimer(IN := TRUE, PT := T#10S);

        IF tPerfusionTimer.Q AND rMetaboliteConcentration < 2.0 THEN
            bPerfusionPumpEnable := FALSE;
            tPerfusionTimer(IN := FALSE);
            iState := 10; (* Return to main fermentation loop *)
        END_IF;

    999: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bAlarm := TRUE;
        IF bEmergencyStop AND NOT bEnable THEN
            iState := 0; (* Reset only if e-stop cleared and enable toggled *)
        END_IF;

END_CASE;

iCurrentState := iState;

END_FUNCTION_BLOCK
```

