FUNCTION_BLOCK FB_ElectrodeCalendering
VAR_INPUT
    (* System Enables & Safety *)
    bEnable                 : BOOL;       (* Master enable signal for calendering unit *)
    bEmergencyStop          : BOOL;       (* Fast stop safety interlock (TRUE = OK to run, FALSE = STOP) *)

    (* Calendering Physical Parameters *)
    rGapGaugeSetPt          : REAL;       (* Target thickness of the electrode web (micrometers) *)
    rActualGapGauge         : REAL;       (* X-ray inline thickness gauge feedback (micrometers) *)
    rWebTensionSetPt        : REAL;       (* Target web tension for unwinder/rewinder synchronization (N) *)
    rActualWebTension       : REAL;       (* Load cell tension feedback (N) *)

    (* Thermal and Speed Characteristics *)
    rRollerTempSetPt        : REAL;       (* Target induction heated roller temperature (Deg C) *)
    rActualRollerTemp       : REAL;       (* Infrared pyrometer roller surface temperature feedback (Deg C) *)
    rLineSpeed              : REAL;       (* Master machine web speed reference (m/min) *)
END_VAR
VAR_OUTPUT
    (* System Status Flags *)
    bSystemReady            : BOOL;       (* Indicates all parameters within acceptable start tolerances *)
    bAlarm                  : BOOL;       (* Critical fault detected, aborting sequence *)
    bWarningLvl1            : BOOL;       (* Non-critical warning (e.g. tracking deviation) *)

    (* Primary Actuator Control Signals *)
    rNipHydraulicValveCmd   : REAL;       (* 0-100% command to hydraulic proportional valve for gap pressure (100-ton max) *)
    rTensionMotorTorqueCmd  : REAL;       (* 0-100% torque limit command for web tension cascading drive *)
    rInductionHeaterCmd     : REAL;       (* 0-100% PWM power command to induction heating coils *)
END_VAR
VAR
    (* Internal State & Timers *)
    iState                  : INT := 0;   (* Active state machine state *)
    tHydraulicDelay         : TON;        (* Delay timer for hydraulic pump pressure build-up *)
    tThermalSoakTimer       : TON;        (* Timer to ensure core roller thermal soaking before operation *)

    (* Control Variables: Gap Control (Hydraulic Nip) *)
    rGapError               : REAL;
    rGapIntegral            : REAL := 0.0;
    rGapKp                  : REAL := 2.50; (* Proportional gain for nip roll *)
    rGapKi                  : REAL := 0.05; (* Integral gain for nip roll *)

    (* Control Variables: Tension Control *)
    rTensionError           : REAL;
    rTensionIntegral        : REAL := 0.0;
    rTensionKp              : REAL := 1.25;
    rTensionKi              : REAL := 0.10;

    (* Control Variables: Thermal Crowning Compensation *)
    rThermalCrowningOffset  : REAL;       (* Expansion offset due to thermal gradients *)
    rTempError              : REAL;
END_VAR

(* === MAIN LOGIC === *)

(* Emergency Safety Interlock Evaluation *)
IF NOT bEmergencyStop THEN
    (* Instantly dump hydraulic pressure, kill motors and heating *)
    bSystemReady := FALSE;
    bAlarm := TRUE;
    bWarningLvl1 := FALSE;
    rNipHydraulicValveCmd := 0.0;
    rTensionMotorTorqueCmd := 0.0;
    rInductionHeaterCmd := 0.0;
    iState := 0; (* Force reset to IDLE *)
    RETURN; (* Abort further processing safely *)
END_IF;

(* Core State Machine for 100-ton Nip Roll Calendering *)
CASE iState OF
    0: (* IDLE & SAFETY CHECKS *)
        bSystemReady := FALSE;
        bAlarm := FALSE;
        rNipHydraulicValveCmd := 0.0;
        rTensionMotorTorqueCmd := 0.0;
        rInductionHeaterCmd := 0.0;

        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* THERMAL RAMPING AND SOAKING *)
        (* Calculate temperature error and naive P-control for induction heater *)
        rTempError := rRollerTempSetPt - rActualRollerTemp;
        rInductionHeaterCmd := rTempError * 5.0; 

        (* Limit Heater Command to 0-100% *)
        IF rInductionHeaterCmd > 100.0 THEN
            rInductionHeaterCmd := 100.0;
        ELSIF rInductionHeaterCmd < 0.0 THEN
            rInductionHeaterCmd := 0.0;
        END_IF;

        (* Check if we have reached thermal equilibrium (+/- 2.0 Deg C) *)
        IF ABS(rTempError) < 2.0 THEN
            tThermalSoakTimer(IN := TRUE, PT := T#30S);
            IF tThermalSoakTimer.Q THEN
                tThermalSoakTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tThermalSoakTimer(IN := FALSE);
        END_IF;

    20: (* HYDRAULIC PRESSURE BUILD & WEB TENSION SYNCHRONIZATION *)
        (* Apply baseline web tension before engaging the heavy nip *)
        rTensionError := rWebTensionSetPt - rActualWebTension;
        rTensionIntegral := rTensionIntegral + (rTensionError * 0.01); (* Assume 10ms task rate *)
        rTensionMotorTorqueCmd := (rTensionError * rTensionKp) + (rTensionIntegral * rTensionKi);

        (* Clamp Tension Motor Torque Command *)
        IF rTensionMotorTorqueCmd > 100.0 THEN
            rTensionMotorTorqueCmd := 100.0;
        ELSIF rTensionMotorTorqueCmd < 0.0 THEN
            rTensionMotorTorqueCmd := 0.0;
        END_IF;

        (* Delay to allow mechanical settling of the web *)
        tHydraulicDelay(IN := TRUE, PT := T#5S);
        IF tHydraulicDelay.Q AND ABS(rTensionError) < 5.0 THEN
            tHydraulicDelay(IN := FALSE);
            iState := 30;
            bSystemReady := TRUE;
        END_IF;

    30: (* ACTIVE RUNNING: GAUGE CONTROL WITH THERMAL CROWNING COMPENSATION *)
        (* A world-class calender compensates for the thermal expansion of the steel roll (crowning).
           As the roll heats up, its diameter increases, shrinking the gap in the center. *)
        rThermalCrowningOffset := (rActualRollerTemp - 25.0) * 0.015; (* 0.015 um/degC thermal expansion approximation *)

        (* Calculate the precise hydraulic nip valve position based on gauge error + thermal offset *)
        rGapError := rGapGaugeSetPt - (rActualGapGauge - rThermalCrowningOffset);
        rGapIntegral := rGapIntegral + (rGapError * 0.01);

        rNipHydraulicValveCmd := (rGapError * rGapKp) + (rGapIntegral * rGapKi);

        (* Feedforward speed coupling: increase hydraulic pressure slightly if line speed is high due to hydrodynamic lift *)
        rNipHydraulicValveCmd := rNipHydraulicValveCmd + (rLineSpeed * 0.12);

        (* Clamp Hydraulic Valve Command *)
        IF rNipHydraulicValveCmd > 100.0 THEN
            rNipHydraulicValveCmd := 100.0;
        ELSIF rNipHydraulicValveCmd < 0.0 THEN
            rNipHydraulicValveCmd := 0.0;
        END_IF;

        (* Sub-loop tension control must remain active *)
        rTensionError := rWebTensionSetPt - rActualWebTension;
        rTensionIntegral := rTensionIntegral + (rTensionError * 0.01);
        rTensionMotorTorqueCmd := (rTensionError * rTensionKp) + (rTensionIntegral * rTensionKi);

        (* Check warnings: e.g., line speed mismatched or high integral windup *)
        IF rGapIntegral > 50.0 THEN
            bWarningLvl1 := TRUE;
        ELSE
            bWarningLvl1 := FALSE;
        END_IF;

        (* Disable transition checks *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
