\nFUNCTION_BLOCK FB_WindTurbineDrivetrainController
FUNCTION_BLOCK FB_IndustrialControl
TITLE = 'Wind Turbine Drivetrain Subsystem Controller'
// -----------------------------------------------------------------------------
// This block manages planetary gear lube oil thermal conditioning,
// mechanical brake hydraulic caliper clamping, and generator coupling alignment.
// -----------------------------------------------------------------------------

VAR_INPUT
    bEnableSys : BOOL;                  // System enable command
    bEmergencyStop : BOOL;              // E-Stop active low

    // Planetary Gear Lube Oil System
    rOilTempCurrent : REAL;             // Current oil temperature (degC)
    rOilTempSetpoint : REAL;            // Desired oil temperature (degC)
    rOilPressureCurrent : REAL;         // Current oil pressure (bar)
    rAmbientTemp : REAL;                // Ambient temperature (degC)
    bOilFilterClogged : BOOL;           // Filter DP switch status

    // Mechanical Brake System
    bRotorSpeed : REAL;                 // Main rotor speed (RPM)
    bBrakeCommand : BOOL;               // Request to apply mechanical brakes
    rBrakeHydPressure : REAL;           // Hydraulic accumulator pressure (bar)
    rBrakePadWear : REAL;               // Brake pad wear measurement (mm)

    // Generator Coupling Alignment
    rVibrationAxial : REAL;             // Axial vibration (mm/s)
    rVibrationRadial : REAL;            // Radial vibration (mm/s)
    rCouplingTemp : REAL;               // Coupling temperature (degC)
END_VAR

VAR_OUTPUT
    // Gearbox Lube System
    bLubePumpCmd : BOOL;                // Lube oil pump command
    bCoolingFanCmd : BOOL;              // Cooling fan command
    bHeaterCmd : BOOL;                  // Oil heater command

    // Mechanical Brakes
    bBrakeValveCmd : BOOL;              // Solenoid valve to apply brakes
    bHydraulicPumpCmd : BOOL;           // Hydraulic pump command for brake pressure

    // Alarms and Status
    bSysReady : BOOL;
    bAlarmGearboxLube : BOOL;
    bAlarmBrakeHydraulic : BOOL;
    bAlarmVibration : BOOL;
    wFaultCode : WORD;
END_VAR

VAR
    // Timers
    tonHeaterDelay : TON;
    tonCoolingDelay : TON;
    tonBrakeHold : TON;
    tonLubePumpStart : TON;

    // Internal States
    rTempDeadband : REAL := 2.0;        // Temperature control deadband
    rMinHydPressure : REAL := 150.0;    // Minimum hydraulic pressure (bar)
    rMaxVibration : REAL := 7.5;        // Maximum allowable vibration (mm/s)

    bOilHeatingActive : BOOL;
    bOilCoolingActive : BOOL;
    bBrakeApplied : BOOL;
    bLubeFault : BOOL;
    bBrakeFault : BOOL;
    bVibFault : BOOL;
END_VAR

// =============================================================================
// Implementation
// =============================================================================

// 1. Safety and Enable Interlocks
IF NOT bEnableSys OR NOT bEmergencyStop THEN
    bLubePumpCmd := FALSE;
    bCoolingFanCmd := FALSE;
    bHeaterCmd := FALSE;
    bBrakeValveCmd := TRUE; // Fail-safe: apply brakes
    bHydraulicPumpCmd := FALSE;
    bSysReady := FALSE;
    wFaultCode := 16#FFFF; // System E-Stop or disabled
    RETURN;
END_IF;

// 2. Planetary Gear Lube Oil Thermal Conditioning
// Lube pump runs if oil pressure is low or if system is enabled. 
// Starting delay to prevent short cycling.
tonLubePumpStart(IN:= bEnableSys AND (rOilPressureCurrent < 1.5), PT:= T#5S);
IF tonLubePumpStart.Q OR (rOilPressureCurrent < 1.0) THEN
    bLubePumpCmd := TRUE;
END_IF;
// Stop pump if overpressured
IF rOilPressureCurrent > 5.0 THEN
    bLubePumpCmd := FALSE;
END_IF;

// Temperature Control
tonHeaterDelay(IN:= (rOilTempCurrent < (rOilTempSetpoint - rTempDeadband)), PT:= T#10S);
tonCoolingDelay(IN:= (rOilTempCurrent > (rOilTempSetpoint + rTempDeadband)), PT:= T#10S);

IF tonHeaterDelay.Q AND bLubePumpCmd THEN
    bHeaterCmd := TRUE;
    bCoolingFanCmd := FALSE;
ELSIF rOilTempCurrent >= rOilTempSetpoint THEN
    bHeaterCmd := FALSE;
END_IF;

IF tonCoolingDelay.Q AND bLubePumpCmd THEN
    bCoolingFanCmd := TRUE;
    bHeaterCmd := FALSE;
ELSIF rOilTempCurrent <= rOilTempSetpoint THEN
    bCoolingFanCmd := FALSE;
END_IF;

// Lube Faults
bLubeFault := bOilFilterClogged OR (rOilTempCurrent > 85.0);
bAlarmGearboxLube := bLubeFault;

// 3. Mechanical Brake Hydraulic Caliper Clamping
// Maintain hydraulic pressure
IF rBrakeHydPressure < rMinHydPressure THEN
    bHydraulicPumpCmd := TRUE;
ELSIF rBrakeHydPressure > (rMinHydPressure + 20.0) THEN
    bHydraulicPumpCmd := FALSE;
END_IF;

// Apply brake logic based on rotor speed and command
tonBrakeHold(IN:= bBrakeCommand AND (bRotorSpeed < 100.0), PT:= T#2S);
IF tonBrakeHold.Q THEN
    bBrakeValveCmd := TRUE;
    bBrakeApplied := TRUE;
ELSE
    bBrakeValveCmd := FALSE;
    bBrakeApplied := FALSE;
END_IF;

bBrakeFault := (rBrakeHydPressure < (rMinHydPressure - 30.0)) OR (rBrakePadWear > 10.0);
bAlarmBrakeHydraulic := bBrakeFault;

// 4. Generator Coupling Alignment / Vibration Monitoring
bVibFault := (rVibrationAxial > rMaxVibration) OR (rVibrationRadial > rMaxVibration) OR (rCouplingTemp > 90.0);
bAlarmVibration := bVibFault;

// 5. System Status Aggregation
IF bLubeFault THEN
    wFaultCode := wFaultCode OR 16#0001;
END_IF;
IF bBrakeFault THEN
    wFaultCode := wFaultCode OR 16#0002;
END_IF;
IF bVibFault THEN
    wFaultCode := wFaultCode OR 16#0004;
END_IF;

bSysReady := NOT (bLubeFault OR bBrakeFault OR bVibFault);

END_FUNCTION_BLOCK
