FUNCTION_BLOCK FB_FlightSimulatorHexapod
VAR_INPUT
    bEnableSystem          : BOOL;  (* System enable from instructor operating station (IOS) *)
    bEmergencyStop         : BOOL;  (* Hardwired E-Stop safety relay OK signal *)
    rTargetRoll            : REAL;  (* Commanded roll angle from aero model (radians) *)
    rTargetPitch           : REAL;  (* Commanded pitch angle from aero model (radians) *)
    rTargetYaw             : REAL;  (* Commanded yaw angle from aero model (radians) *)
    rTargetHeave           : REAL;  (* Commanded heave displacement (meters) *)
    rTargetSway            : REAL;  (* Commanded sway displacement (meters) *)
    rTargetSurge           : REAL;  (* Commanded surge displacement (meters) *)
    rHydraulicSupplyPrs    : REAL;  (* Main supply pressure from HPU (bar) *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;  (* Motion base ready for cueing *)
    bWarning               : BOOL;  (* Non-critical warning (e.g. following error) *)
    bCriticalFault         : BOOL;  (* Critical fault causing motion freeze/shutdown *)
    rLeg1CommandLength     : REAL;  (* Commanded extension for Actuator 1 (m) *)
    rLeg2CommandLength     : REAL;  (* Commanded extension for Actuator 2 (m) *)
    rLeg3CommandLength     : REAL;  (* Commanded extension for Actuator 3 (m) *)
    rLeg4CommandLength     : REAL;  (* Commanded extension for Actuator 4 (m) *)
    rLeg5CommandLength     : REAL;  (* Commanded extension for Actuator 5 (m) *)
    rLeg6CommandLength     : REAL;  (* Commanded extension for Actuator 6 (m) *)
END_VAR
VAR
    iState                 : INT := 0; 
    tSettlingTimer         : TON;
    rCurrentLengths        : ARRAY[1..6] OF REAL;
    rBaseRadius            : REAL := 2.5; (* Base joint radius in meters *)
    rPlatformRadius        : REAL := 2.0; (* Platform joint radius in meters *)
    rMaxLegStroke          : REAL := 1.8; (* Maximum stroke length of actuators *)
    rMinLegStroke          : REAL := 0.2;
    rFilterCoeff           : REAL := 0.05;
    bInternalFault         : BOOL := FALSE;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bCriticalFault := TRUE;
    iState := 99; (* FAULT STATE *)
    rLeg1CommandLength := 0.0;
    rLeg2CommandLength := 0.0;
    rLeg3CommandLength := 0.0;
    rLeg4CommandLength := 0.0;
    rLeg5CommandLength := 0.0;
    rLeg6CommandLength := 0.0;
    RETURN;
END_IF;

(* Check Hydraulic Pressure *)
IF rHydraulicSupplyPrs < 120.0 THEN
    bCriticalFault := TRUE;
    bSystemReady := FALSE;
    iState := 99;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE / INITIALIZATION *)
        bSystemReady := FALSE;
        bWarning := FALSE;
        IF bEnableSystem AND (rHydraulicSupplyPrs >= 140.0) THEN
            iState := 10;
        END_IF;

    10: (* SETTLING AND NEUTRAL POSITIONING *)
        tSettlingTimer(IN := TRUE, PT := T#3S);
        rLeg1CommandLength := 1.0; 
        rLeg2CommandLength := 1.0; 
        rLeg3CommandLength := 1.0;
        rLeg4CommandLength := 1.0; 
        rLeg5CommandLength := 1.0; 
        rLeg6CommandLength := 1.0;

        IF tSettlingTimer.Q THEN
            tSettlingTimer(IN := FALSE);
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* ACTIVE KINEMATICS MODE *)
        IF NOT bEnableSystem THEN
            iState := 0;
        END_IF;

        (* Simplified inverse kinematics approximation for hexapod length calculation. 
           In reality, this involves 4x4 homogenous transformation matrices (HTMs). *)
        rLeg1CommandLength := 1.0 + rTargetHeave + (rTargetRoll * 0.5) - (rTargetPitch * 0.5);
        rLeg2CommandLength := 1.0 + rTargetHeave + (rTargetRoll * 0.5) + (rTargetPitch * 0.5);
        rLeg3CommandLength := 1.0 + rTargetHeave - (rTargetRoll * 0.5) + (rTargetPitch * 0.5);
        rLeg4CommandLength := 1.0 + rTargetHeave - (rTargetRoll * 0.5) - (rTargetPitch * 0.5);
        rLeg5CommandLength := 1.0 + rTargetHeave + rTargetSway + (rTargetYaw * 0.2);
        rLeg6CommandLength := 1.0 + rTargetHeave - rTargetSway - (rTargetYaw * 0.2);

        (* Stroke Limiting Interlocks *)
        IF (rLeg1CommandLength > rMaxLegStroke) OR (rLeg1CommandLength < rMinLegStroke) THEN
            bWarning := TRUE;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        IF bEmergencyStop AND (rHydraulicSupplyPrs >= 120.0) THEN
            iState := 0;
            bCriticalFault := FALSE;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
