    rPlatenRot      : REAL;    (* Wafer platen rotation speed in RPM *)
    rSIMSSignal     : REAL;    (* Secondary Ion Mass Spectrometry endpoint signal *)
END_VAR
VAR_OUTPUT
    (* Required outputs for IBE system *)
    bSystemReady    : BOOL;    (* System is ready for etching *)
    bPlasmaStriking : BOOL;    (* Plasma strike in progress *)
    bEtchActive     : BOOL;    (* Main etching sequence active *)
    rArgonValveCtrl : REAL;    (* Argon mass flow controller setpoint 0-100% *)
    rGridVSetpt     : REAL;    (* Beam grid voltage setpoint *)
    bEndpointReached: BOOL;    (* SIMS endpoint detected *)
    bAlarm          : BOOL;    (* Critical fault alarm *)
    iFaultCode      : INT;     (* Detailed fault code *)
END_VAR
VAR
    (* Internal State and Filtering *)
    iState          : INT := 0;
    rFiltPress      : REAL;
    rFiltSIMS       : REAL;

    (* Timers *)
    tStrikeTimer    : TON;
    tEtchTimer      : TON;
    tStabilizeTimer : TON;

    (* Constants *)
    MAX_PRESS       : REAL := 1.5; (* max mTorr *)
    MIN_PRESS       : REAL := 0.2; (* min mTorr *)
    SIMS_THRESHOLD  : REAL := 8.5; (* arbitrary units for endpoint *)

    (* Filter Constants *)
    ALPHA           : REAL := 0.1;
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEStopOK THEN
    bSystemReady := FALSE;
    bPlasmaStriking := FALSE;
    bEtchActive := FALSE;
    bEndpointReached := FALSE;
    rArgonValveCtrl := 0.0;
    rGridVSetpt := 0.0;
    bAlarm := TRUE;
    iFaultCode := 99; (* E-Stop active *)
    iState := 0;
    RETURN;
END_IF;

(* Exponential Moving Average for noisy sensors *)
rFiltPress := (ALPHA * rChamberPress) + ((1.0 - ALPHA) * rFiltPress);
rFiltSIMS := (ALPHA * rSIMSSignal) + ((1.0 - ALPHA) * rFiltSIMS);

CASE iState OF
    0: (* IDLE & CHECK INTERLOCKS *)
        bSystemReady := FALSE;
        bPlasmaStriking := FALSE;
        bEtchActive := FALSE;
        bEndpointReached := FALSE;
        bAlarm := FALSE;
        iFaultCode := 0;
        rArgonValveCtrl := 0.0;
        rGridVSetpt := 0.0;

        IF bEnableSys AND (rFiltPress < 0.1) THEN
            iState := 10; (* Move to pump down and stabilize *)
        END_IF;

    10: (* GAS STABILIZATION *)
        rArgonValveCtrl := 50.0; (* Set 50% flow for strike *)
        tStabilizeTimer(IN := TRUE, PT := T#10S);

        IF tStabilizeTimer.Q THEN
            tStabilizeTimer(IN := FALSE);
            IF (rFiltPress >= MIN_PRESS) AND (rFiltPress <= MAX_PRESS) THEN
                iState := 20;
            ELSE
                bAlarm := TRUE;
                iFaultCode := 10; (* Pressure out of bounds *)
                iState := 999;
            END_IF;
        END_IF;

    20: (* PLASMA STRIKE *)
        bSystemReady := TRUE;
        bPlasmaStriking := TRUE;
        rGridVSetpt := 300.0; (* 300V for strike *)
        tStrikeTimer(IN := TRUE, PT := T#5S);

        IF rBeamCurrent > 50.0 THEN (* Plasma established *)
            tStrikeTimer(IN := FALSE);
            bPlasmaStriking := FALSE;
            iState := 30;
        ELSIF tStrikeTimer.Q THEN
            tStrikeTimer(IN := FALSE);
            bPlasmaStriking := FALSE;
            bAlarm := TRUE;
            iFaultCode := 20; (* Failed to strike *)
            iState := 999;
        END_IF;

    30: (* ETCHING & ENDPOINT DETECTION *)
        bEtchActive := TRUE;
        rGridVSetpt := 1200.0; (* 1200V main etch *)

        (* Monitor Platen Params - simplified interlock *)
        IF (rPlatenRot < 10.0) OR (rPlatenTilt > 45.0) THEN
            bAlarm := TRUE;
            iFaultCode := 30; (* Platen fault *)
            iState := 999;
        END_IF;

        (* SIMS Endpoint Detection *)
        IF rFiltSIMS > SIMS_THRESHOLD THEN
            bEndpointReached := TRUE;
            bEtchActive := FALSE;
            iState := 40;
        END_IF;

        (* Failsafe timeout *)
        tEtchTimer(IN := TRUE, PT := T#300S);
        IF tEtchTimer.Q THEN
            tEtchTimer(IN := FALSE);
            bAlarm := TRUE;
            iFaultCode := 31; (* Etch timeout *)
            iState := 999;
        END_IF;

    40: (* POST-ETCH PURGE / COMPLETION *)
        rGridVSetpt := 0.0;
        rArgonValveCtrl := 0.0;
        bSystemReady := FALSE;
        IF NOT bEnableSys THEN
            bEndpointReached := FALSE;
            iState := 0;
        END_IF;

    999: (* FAULT HANDLING *)
        rGridVSetpt := 0.0;
        rArgonValveCtrl := 0.0;
        bPlasmaStriking := FALSE;
        bEtchActive := FALSE;
        bSystemReady := FALSE;

        IF NOT bEnableSys THEN
            bAlarm := FALSE;
            iFaultCode := 0;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
