FUNCTION_BLOCK FB_Exosome_TFF_Control
(*
    =========================================================================
    Advanced Biomanufacturing Extracellular Vesicle (Exosome) TFF Controller
    =========================================================================
    This highly complex function block manages the Tangential Flow Filtration
    (TFF) process specifically designed for ultra-low shear, high-yield 
    isolation of exosomes (extracellular vesicles).
    It regulates Transmembrane Pressure (TMP), manages permeate mass balancing,
    and controls the retentate concentration factor using cascaded PID loops.
*)
VAR_INPUT
    bEnable                 : BOOL;     (* System global enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK (True = Safe) *)
    rFeedPressure_mbar      : REAL;     (* P1: Feed pressure transducer [mbar] *)
    rRetentatePressure_mbar : REAL;     (* P2: Retentate pressure transducer [mbar] *)
    rPermeatePressure_mbar  : REAL;     (* P3: Permeate pressure transducer [mbar] *)
    rFeedFlowRate_Lpm       : REAL;     (* F1: Feed flow rate [L/min] *)
    rPermeateFlowRate_Lpm   : REAL;     (* F2: Permeate flow rate [L/min] *)
    rTargetTMP_mbar         : REAL;     (* Setpoint for Transmembrane Pressure [mbar] *)
    rTargetConcentration    : REAL;     (* Desired Concentration Factor (V_initial / V_retentate) *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is initialized and ready for process *)
    rFeedPumpSpeed_Pct      : REAL;     (* Feed pump speed command [%] *)
    rRetentateValve_Pct     : REAL;     (* Retentate control valve position [%] *)
    rPermeatePumpSpeed_Pct  : REAL;     (* Permeate pump speed command [%] *)
    rCurrentTMP_mbar        : REAL;     (* Calculated actual TMP [mbar] *)
    bHighShearAlarm         : BOOL;     (* Alarm: Detected shear rate exceeds exosome damage threshold *)
    bProcessComplete        : BOOL;     (* Process reached target concentration *)
END_VAR

VAR
    iState                  : INT := 0; (* State machine index *)
    tProcessTimer           : TON;      (* General process step timer *)
    tFilterFoulingTimer     : TON;      (* Timer to detect filter fouling / flux decline *)
    rCalculatedFlux_LMH     : REAL;     (* Permeate flux [L/m2/h] *)
    rTotalPermeateVol_L     : REAL;     (* Integrated permeate volume *)
    rInitialVolume_L        : REAL := 100.0; (* Simulated batch initial volume *)
    rCurrentConcentration   : REAL;     (* Actual concentration factor *)

    (* Cascaded PID State Variables *)
    rTMP_Error              : REAL;
    rTMP_Integral           : REAL;
    rTMP_Derivative         : REAL;
    rTMP_LastError          : REAL;

    rFlux_Error             : REAL;
    rFlux_Integral          : REAL;
    rFlux_LastError         : REAL;

    (* Tuning Parameters *)
    Kp_TMP                  : REAL := 2.5;
    Ki_TMP                  : REAL := 0.8;
    Kd_TMP                  : REAL := 0.1;

    Kp_Flux                 : REAL := 1.2;
    Ki_Flux                 : REAL := 0.3;

    CYCLE_TIME_S            : REAL := 0.1; (* 100ms task cycle *)
    FILTER_AREA_M2          : REAL := 2.5; (* Hollow fiber module area *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bProcessComplete := FALSE;
    rFeedPumpSpeed_Pct := 0.0;
    rRetentateValve_Pct := 100.0; (* Fail-open for safety *)
    rPermeatePumpSpeed_Pct := 0.0;
    bHighShearAlarm := TRUE;
    iState := 0;
    RETURN;
END_IF;

(* TMP Calculation: TMP = (P_feed + P_retentate)/2 - P_permeate *)
rCurrentTMP_mbar := ((rFeedPressure_mbar + rRetentatePressure_mbar) / 2.0) - rPermeatePressure_mbar;

(* Flux Calculation: LMH = Flow_Lpm * 60 / Area *)
rCalculatedFlux_LMH := (rPermeateFlowRate_Lpm * 60.0) / FILTER_AREA_M2;

(* Simple Integration for Permeate Volume (Euler) *)
rTotalPermeateVol_L := rTotalPermeateVol_L + (rPermeateFlowRate_Lpm * (CYCLE_TIME_S / 60.0));
IF (rInitialVolume_L - rTotalPermeateVol_L) > 0.0 THEN
    rCurrentConcentration := rInitialVolume_L / (rInitialVolume_L - rTotalPermeateVol_L);
ELSE
    rCurrentConcentration := 999.0;
END_IF;

CASE iState OF
    0: (* IDLE & INITIALIZATION *)
        rFeedPumpSpeed_Pct := 0.0;
        rRetentateValve_Pct := 100.0;
        rPermeatePumpSpeed_Pct := 0.0;
        rTMP_Integral := 0.0;
        rTMP_LastError := 0.0;
        rTotalPermeateVol_L := 0.0;
        bSystemReady := TRUE;
        bProcessComplete := FALSE;
        bHighShearAlarm := FALSE;

        IF bEnable THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PRIMING & SHEAR CONDITIONING *)
        (* Ramp up feed pump slowly to prevent shear damage to exosomes *)
        IF rFeedPumpSpeed_Pct < 30.0 THEN
            rFeedPumpSpeed_Pct := rFeedPumpSpeed_Pct + 0.5;
        ELSE
            iState := 20;
        END_IF;
        rRetentateValve_Pct := 100.0;

    20: (* STEADY STATE TFF CASCADED CONTROL *)
        (* Inner Loop: TMP Control via Retentate Valve *)
        rTMP_Error := rTargetTMP_mbar - rCurrentTMP_mbar;
        rTMP_Integral := rTMP_Integral + (rTMP_Error * CYCLE_TIME_S);
        rTMP_Derivative := (rTMP_Error - rTMP_LastError) / CYCLE_TIME_S;

        (* Anti-windup for TMP *)
        IF rTMP_Integral > 100.0 THEN rTMP_Integral := 100.0; END_IF;
        IF rTMP_Integral < -100.0 THEN rTMP_Integral := -100.0; END_IF;

        rRetentateValve_Pct := 100.0 - (Kp_TMP * rTMP_Error + Ki_TMP * rTMP_Integral + Kd_TMP * rTMP_Derivative);
        rTMP_LastError := rTMP_Error;

        (* Valve Saturation Check *)
        IF rRetentateValve_Pct > 100.0 THEN rRetentateValve_Pct := 100.0; END_IF;
        IF rRetentateValve_Pct < 10.0 THEN rRetentateValve_Pct := 10.0; END_IF; (* Avoid full dead-head *)

        (* Outer Loop: Flux/Shear Control via Feed Pump *)
        rFlux_Error := 50.0 - rCalculatedFlux_LMH; (* Target nominal flux 50 LMH *)
        rFlux_Integral := rFlux_Integral + (rFlux_Error * CYCLE_TIME_S);
        rFeedPumpSpeed_Pct := 30.0 + (Kp_Flux * rFlux_Error + Ki_Flux * rFlux_Integral);

        IF rFeedPumpSpeed_Pct > 80.0 THEN
            rFeedPumpSpeed_Pct := 80.0;
            bHighShearAlarm := TRUE; (* Risk of exosome deformation *)
        ELSE
            bHighShearAlarm := FALSE;
        END_IF;

        (* Permeate Extraction *)
        rPermeatePumpSpeed_Pct := 20.0; 

        (* Check Concentration Factor Target *)
        IF rCurrentConcentration >= rTargetConcentration THEN
            iState := 30;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* DIAFILTRATION / HARVEST READY *)
        rFeedPumpSpeed_Pct := 10.0;
        rRetentateValve_Pct := 100.0;
        rPermeatePumpSpeed_Pct := 0.0;
        bProcessComplete := TRUE;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
