    rSetTempZone2 : REAL; (* Setpoint temperature for pre-heating zone 2 (C) *)
    rSetTempZone3 : REAL; (* Setpoint temperature for pre-heating zone 3 (C) *)
    rActualTempZone1 : REAL; (* Actual temperature from zone 1 thermocouple *)
    rActualTempZone2 : REAL; (* Actual temperature from zone 2 thermocouple *)
    rActualTempZone3 : REAL; (* Actual temperature from zone 3 thermocouple *)
    bIndexTrigger : BOOL; (* Trigger for indexing the film *)
    bVisionFail : BOOL; (* Vision system reject signal for current blister *)
    diEncoderPos : DINT; (* Current machine encoder position in degrees (0-360) *)
END_VAR
VAR_OUTPUT
    bHeaterOutZone1 : BOOL; (* PWM output for heater zone 1 *)
    bHeaterOutZone2 : BOOL; (* PWM output for heater zone 2 *)
    bHeaterOutZone3 : BOOL; (* PWM output for heater zone 3 *)
    bPlugAssistCylExtend : BOOL; (* Solenoid control for plug-assist cylinder extend *)
    bFormAirValve : BOOL; (* Solenoid control for forming air pressure *)
    bRejectActuator : BOOL; (* High-speed reject blow-off solenoid *)
    bMachineReady : BOOL; (* Machine ready status *)
    bAlarmActive : BOOL; (* General alarm active status *)
    iState : INT; (* Current machine state *)
END_VAR
VAR
    (* PID Controllers for Heating Zones *)
    fbPIDZone1 : PID;
    fbPIDZone2 : PID;
    fbPIDZone3 : PID;

    (* Timers *)
    tonFormTime : TON;
    tonRejectDelay : TON;
    tonRejectDuration : TON;

    (* Internal State *)
    bHeatersAtTemp : BOOL;
    rTempTolerance : REAL := 2.5; (* Tolerance in Celsius *)

    (* Shift register for rejects *)
    arRejectFIFO : ARRAY[0..15] OF BOOL;
    iRejectIndex : INT := 0;
    bRejectPending : BOOL;

    (* Constants *)
    diFormStartDeg : DINT := 45;
    diFormEndDeg : DINT := 135;
    diPlugAssistStartDeg : DINT := 40;
    diPlugAssistEndDeg : DINT := 140;
    diRejectDeg : DINT := 270;
END_VAR

(* 1. Emergency Stop and Basic States *)
IF NOT bEStop THEN
    bMachineReady := FALSE;
    bAlarmActive := TRUE;
    bHeaterOutZone1 := FALSE;
    bHeaterOutZone2 := FALSE;
    bHeaterOutZone3 := FALSE;
    bPlugAssistCylExtend := FALSE;
    bFormAirValve := FALSE;
    bRejectActuator := FALSE;
    iState := 0;
    RETURN;
END_IF;

(* 2. Temperature Control (Simplified Bang-Bang for demonstration, ideally PID) *)
IF bEnable THEN
    (* Zone 1 *)
    IF rActualTempZone1 < (rSetTempZone1 - 0.5) THEN
        bHeaterOutZone1 := TRUE;
    ELSIF rActualTempZone1 > (rSetTempZone1 + 0.5) THEN
        bHeaterOutZone1 := FALSE;
    END_IF;

    (* Zone 2 *)
    IF rActualTempZone2 < (rSetTempZone2 - 0.5) THEN
        bHeaterOutZone2 := TRUE;
    ELSIF rActualTempZone2 > (rSetTempZone2 + 0.5) THEN
        bHeaterOutZone2 := FALSE;
    END_IF;

    (* Zone 3 *)
    IF rActualTempZone3 < (rSetTempZone3 - 0.5) THEN
        bHeaterOutZone3 := TRUE;
    ELSIF rActualTempZone3 > (rSetTempZone3 + 0.5) THEN
        bHeaterOutZone3 := FALSE;
    END_IF;

    bHeatersAtTemp := (ABS(rActualTempZone1 - rSetTempZone1) < rTempTolerance) AND
                      (ABS(rActualTempZone2 - rSetTempZone2) < rTempTolerance) AND
                      (ABS(rActualTempZone3 - rSetTempZone3) < rTempTolerance);
ELSE
    bHeaterOutZone1 := FALSE;
    bHeaterOutZone2 := FALSE;
    bHeaterOutZone3 := FALSE;
    bHeatersAtTemp := FALSE;
END_IF;

bMachineReady := bEnable AND bHeatersAtTemp;

(* 3. Thermoforming Process based on Machine Degrees *)
IF bMachineReady THEN
    (* Plug assist moves slightly before and stays slightly after forming air *)
    IF (diEncoderPos >= diPlugAssistStartDeg) AND (diEncoderPos <= diPlugAssistEndDeg) THEN
        bPlugAssistCylExtend := TRUE;
    ELSE
        bPlugAssistCylExtend := FALSE;
    END_IF;

    (* Forming air application *)
    IF (diEncoderPos >= diFormStartDeg) AND (diEncoderPos <= diFormEndDeg) THEN
        bFormAirValve := TRUE;
    ELSE
        bFormAirValve := FALSE;
    END_IF;
ELSE
    bPlugAssistCylExtend := FALSE;
    bFormAirValve := FALSE;
END_IF;

(* 4. Vision Reject Shift Register and High-Speed Sorting *)
(* Trigger on indexing edge to shift the FIFO *)
IF bIndexTrigger THEN
    FOR iRejectIndex := 15 TO 1 BY -1 DO
        arRejectFIFO[iRejectIndex] := arRejectFIFO[iRejectIndex - 1];
    END_FOR;
    arRejectFIFO[0] := bVisionFail;
END_IF;

(* Assume rejection happens 5 index steps downstream *)
bRejectPending := arRejectFIFO[5];

(* Actuate reject at specific machine degree *)
IF bMachineReady AND bRejectPending AND (diEncoderPos >= diRejectDeg) AND (diEncoderPos <= diRejectDeg + 15) THEN
    bRejectActuator := TRUE;
ELSE
    bRejectActuator := FALSE;
END_IF;

END_FUNCTION_BLOCK
