FUNCTION_BLOCK FB_Cyclotron_PET_Isotope
TITLE = 'Medical Cyclotron Proton Beamline & Fluorine-18 Target Synthesis Controller'
VERSION : '1.0'

(* 
   =============================================================================
   Block: FB_Cyclotron_PET_Isotope
   Description: Controls the 18 MeV cyclotron beam extraction and F-18 synthesis
   Author: Principal Accelerator Physicist
   Date: 2026-08-22
   =============================================================================
*)

VAR_INPUT
    bEnable                 : BOOL;   (* Enable cyclotron control system *)
    bStartBombardment       : BOOL;   (* Command to start irradiation *)
    bStartDelivery          : BOOL;   (* Command to push F-18 to hot-cell *)
    bReset                  : BOOL;   (* Reset faults and interlocks *)
    fBeamCurrentTarget      : LREAL;  (* Target beam current [uA], e.g., 50 uA *)
    fIrradiationTimeSec     : LREAL;  (* Target irradiation time [s] *)

    (* Sensors *)
    fActualBeamCurrent_uA   : LREAL;  (* Measured beam current on target [uA] *)
    fFoilPosition_mm        : LREAL;  (* Carbon stripper foil position [mm] *)
    fQuadrupoleMag1_A       : LREAL;  (* Q1 magnet current [A] *)
    fQuadrupoleMag2_A       : LREAL;  (* Q2 magnet current [A] *)
    fTargetPressure_bar     : LREAL;  (* O-18 water target pressure [bar] *)
    fTargetTemp_C           : LREAL;  (* Target window temperature [C] *)

    (* Interlocks & Safety *)
    bVaultDoorClosed        : BOOL;   (* Cyclotron vault door closed & sealed *)
    bHotCellReady           : BOOL;   (* Hot-cell synthesis module ready *)
    bCoolingWaterFlowOk     : BOOL;   (* Chilled water flow to target ok *)
    bVacuumOk               : BOOL;   (* Beamline vacuum < 1e-6 mbar *)
END_VAR

VAR_OUTPUT
    (* PackML States *)
    eState                  : INT;    (* 0=Idle, 1=Prep, 2=Irradiating, 3=Cooling, 4=Delivery, 5=Fault *)

    (* Actuators *)
    fCmdFoilPosition_mm     : LREAL;  (* Commanded foil position [mm] *)
    fCmdQuadrupoleMag1_A    : LREAL;  (* Commanded Q1 magnet current [A] *)
    fCmdQuadrupoleMag2_A    : LREAL;  (* Commanded Q2 magnet current [A] *)
    bTargetValveO18Open     : BOOL;   (* Valve to load O-18 water *)
    bTargetValveHeliumOpen  : BOOL;   (* Helium overpressure valve for delivery *)
    bTargetValveDeliveryOpen: BOOL;   (* Valve to push F-18 to hot-cell *)
    bIonSourceRFEnable      : BOOL;   (* Enable RF and Ion Source *)

    (* Status & Diagnostics *)
    fRemainingTimeSec       : LREAL;  (* Remaining irradiation time [s] *)
    fTotalCharge_uAh        : LREAL;  (* Accumulated charge [uA*h] *)
    bInterlockActive        : BOOL;   (* System interlocked/faulted *)
    bReadyToDeliver         : BOOL;   (* Bombardment complete, ready for delivery *)
END_VAR

VAR
    (* Internal State *)
    nStep                   : INT;
    fElapsedTimeSec         : LREAL;
    fIntegratedCharge_uAs   : LREAL;
    tCycleTimer             : TON;
    tDeliveryTimer          : TON;

    (* PID Controllers *)
    fKp_Foil                : LREAL := 0.05;
    fKi_Foil                : LREAL := 0.01;
    fErrorSum               : LREAL;

    (* Constants *)
    STATE_IDLE              : INT := 0;
    STATE_PREP              : INT := 1;
    STATE_IRRADIATING       : INT := 2;
    STATE_COOLING           : INT := 3;
    STATE_DELIVERY          : INT := 4;
    STATE_FAULT             : INT := 5;

    TARGET_PRESSURE_MAX     : LREAL := 35.0; (* bar *)
    TARGET_TEMP_MAX         : LREAL := 90.0; (* C *)
    BEAM_CURRENT_MAX        : LREAL := 60.0; (* uA *)

    Q1_NOMINAL              : LREAL := 45.2; (* A *)
    Q2_NOMINAL              : LREAL := 48.7; (* A *)
END_VAR

(* Safety Interlock Evaluation *)
bInterlockActive := NOT bVaultDoorClosed OR 
                    NOT bCoolingWaterFlowOk OR 
                    NOT bVacuumOk OR 
                    (fTargetPressure_bar > TARGET_PRESSURE_MAX) OR 
                    (fTargetTemp_C > TARGET_TEMP_MAX) OR
                    (fActualBeamCurrent_uA > BEAM_CURRENT_MAX);

IF bInterlockActive OR NOT bEnable THEN
    eState := STATE_FAULT;
END_IF

IF bReset AND NOT bInterlockActive THEN
    eState := STATE_IDLE;
    nStep := 0;
END_IF

(* PackML State Machine *)
CASE eState OF
    STATE_IDLE:
        bIonSourceRFEnable := FALSE;
        fCmdFoilPosition_mm := 0.0;
        fCmdQuadrupoleMag1_A := 0.0;
        fCmdQuadrupoleMag2_A := 0.0;
        bTargetValveO18Open := FALSE;
        bTargetValveHeliumOpen := FALSE;
        bTargetValveDeliveryOpen := FALSE;
        fTotalCharge_uAh := 0.0;
        fIntegratedCharge_uAs := 0.0;
        fElapsedTimeSec := 0.0;
        bReadyToDeliver := FALSE;

        IF bStartBombardment AND NOT bInterlockActive THEN
            eState := STATE_PREP;
            nStep := 0;
        END_IF

    STATE_PREP:
        (* Sequence to load O-18 water and tune magnets *)
        CASE nStep OF
            0: (* Load O-18 Water *)
                bTargetValveO18Open := TRUE;
                tCycleTimer(IN:=TRUE, PT:=T#5S);
                IF tCycleTimer.Q THEN
                    tCycleTimer(IN:=FALSE);
                    bTargetValveO18Open := FALSE;
                    nStep := 1;
                END_IF
            1: (* Power Quadrupoles *)
                fCmdQuadrupoleMag1_A := Q1_NOMINAL;
                fCmdQuadrupoleMag2_A := Q2_NOMINAL;
                tCycleTimer(IN:=TRUE, PT:=T#3S);
                IF tCycleTimer.Q THEN
                    tCycleTimer(IN:=FALSE);
                    nStep := 2;
                END_IF
            2: (* Enable RF and Ion Source, Position Foil *)
                bIonSourceRFEnable := TRUE;
                fCmdFoilPosition_mm := 5.0; (* Initial shallow position *)
                eState := STATE_IRRADIATING;
        END_CASE

    STATE_IRRADIATING:
        (* Active Beam Extraction & Current Modulation via Foil Position PI Control *)
        IF bIonSourceRFEnable THEN
            fElapsedTimeSec := fElapsedTimeSec + 0.01; (* Assuming 10ms task rate *)
            fRemainingTimeSec := fIrradiationTimeSec - fElapsedTimeSec;

            (* PI Control for foil position to maintain target beam current *)
            fErrorSum := fErrorSum + (fBeamCurrentTarget - fActualBeamCurrent_uA) * 0.01;

            (* Anti-windup *)
            IF fErrorSum > 500.0 THEN fErrorSum := 500.0; END_IF
            IF fErrorSum < -500.0 THEN fErrorSum := -500.0; END_IF

            fCmdFoilPosition_mm := 5.0 + (fKp_Foil * (fBeamCurrentTarget - fActualBeamCurrent_uA)) + (fKi_Foil * fErrorSum);

            (* Foil limits *)
            IF fCmdFoilPosition_mm > 25.0 THEN fCmdFoilPosition_mm := 25.0; END_IF
            IF fCmdFoilPosition_mm < 0.0 THEN fCmdFoilPosition_mm := 0.0; END_IF

            (* Charge integration *)
            fIntegratedCharge_uAs := fIntegratedCharge_uAs + (fActualBeamCurrent_uA * 0.01);
            fTotalCharge_uAh := fIntegratedCharge_uAs / 3600.0;

            IF fElapsedTimeSec >= fIrradiationTimeSec THEN
                eState := STATE_COOLING;
                nStep := 0;
            END_IF
        END_IF

    STATE_COOLING:
        (* Stop bombardment, allow target to cool to reduce pressure before delivery *)
        bIonSourceRFEnable := FALSE;
        fCmdFoilPosition_mm := 0.0;
        fCmdQuadrupoleMag1_A := 0.0;
        fCmdQuadrupoleMag2_A := 0.0;

        tCycleTimer(IN:=TRUE, PT:=T#60S); (* 60s Cooling time *)
        IF tCycleTimer.Q THEN
            tCycleTimer(IN:=FALSE);
            bReadyToDeliver := TRUE;
            IF bStartDelivery AND bHotCellReady THEN
                eState := STATE_DELIVERY;
                nStep := 0;
            END_IF
        END_IF

    STATE_DELIVERY:
        (* Cavitation-free helium push to hot-cell *)
        bReadyToDeliver := FALSE;
        CASE nStep OF
            0: (* Pressurize with Helium *)
                bTargetValveHeliumOpen := TRUE;
                tDeliveryTimer(IN:=TRUE, PT:=T#2S);
                IF tDeliveryTimer.Q THEN
                    tDeliveryTimer(IN:=FALSE);
                    nStep := 1;
                END_IF
            1: (* Open Delivery Valve *)
                bTargetValveDeliveryOpen := TRUE;
                tDeliveryTimer(IN:=TRUE, PT:=T#10S); (* Push duration *)
                IF tDeliveryTimer.Q THEN
                    tDeliveryTimer(IN:=FALSE);
                    nStep := 2;
                END_IF
            2: (* Close Valves *)
                bTargetValveHeliumOpen := FALSE;
                bTargetValveDeliveryOpen := FALSE;
                eState := STATE_IDLE;
        END_CASE

    STATE_FAULT:
        (* Safe shutdown state *)
        bIonSourceRFEnable := FALSE;
        fCmdFoilPosition_mm := 0.0;
        fCmdQuadrupoleMag1_A := 0.0;
        fCmdQuadrupoleMag2_A := 0.0;
        bTargetValveO18Open := FALSE;
        bTargetValveHeliumOpen := FALSE;
        bTargetValveDeliveryOpen := FALSE;
        bReadyToDeliver := FALSE;
        tCycleTimer(IN:=FALSE);
        tDeliveryTimer(IN:=FALSE);

END_CASE

END_FUNCTION_BLOCK
```

```iec-st
(*
version 1.3	13. nov. 2009
programmer 	hugo
tested by		tobias

FT_PIDWL is a PID controller with dynamic wind_up reset.
The PID controller works according to the fomula Y = KP *(IN + KI * INTEG(e) + DERIV(e) ).
a rst will reset the integrator to 0
lim_h and Lim_l set the possible output range of the internal integrator.
the output flags lim will signal that the output limits are active.

default values for KP = 1, KI = 1, ILIM_L = -1E37, iLIM_H = +1E38.
*)
FUNCTION_BLOCK FT_PIDWL
VAR_INPUT
	IN : REAL;
	KP : REAL := 1.0;
	TN : REAL := 1.0;
	TV : REAL := 1.0;
	LIM_L : REAL := -1.0E38;
	LIM_H : REAL := 1.0E38;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Y : REAL;
	LIM : BOOL;
END_VAR
VAR
	piwl : FT_PIWL;
	diff : FT_DERIV;
END_VAR
(* if rst then *)
IF rst THEN
	piwl(rst := TRUE);
	piwl.RST := FALSE;
ELSE
	(* run PIWL controller first *)
	(* we need to check if TN = 0 and do alternative calls *)
	IF TN = 0.0 THEN
		piwl(in := IN * KP, KP := 1.0, KI := 0.0, LIM_L := LIM_L, LIM_H := LIM_H);
	ELSE
		piwl(in := IN * KP, KP := 1.0, KI := 1.0 / TN, LIM_L := LIM_L, LIM_H := LIM_H);
	END_IF;

	(* run differentiator and add_to_output *)
	diff(IN := IN, K := KP * TV);
	Y := piwl.Y + diff.out;

	(* limit the output *)
	IF Y < LIM_L THEN
		LIM := TRUE;
		Y := LIM_L;
	ELSIF Y > LIM_H THEN
		LIM := TRUE;
		Y := LIM_H;
	ELSE
		LIM := FALSE;
	END_IF;
END_IF;



(* revision history
hm 13. jun. 2008 	rev 1.0
	original version

hm	25. jan 2008	rev 1.1
	multiply differential part with KP

hm	11. mar. 2009	rev 1.2
	real constants updated to new systax using dot

hm	13. nov. 2009	rev 1.3
	fixed code for negative KP

*)
END_FUNCTION_BLOCK
