FUNCTION_BLOCK FB_CerebralOrganoid_BNN
VAR_INPUT
    bEnable                 : BOOL;
    bStart                  : BOOL;
    bStop                   : BOOL;
    bAbort                  : BOOL;
    bReset                  : BOOL;

    (* Environmental Feedback *)
    fCsfFlowRateSens_uLmin  : LREAL;
    stNeuroSensors          : ST_Neurochemicals;

    (* LTP Protocol Parameters *)
    fTargetLTPWeight        : LREAL := 0.85; (* Target synaptic weight [0.0 - 1.0] *)
    fMaxStimulusCurrent_uA  : LREAL := 9.5;  (* Safety limit: must be < 10 uA *)
END_VAR

VAR_OUTPUT
    ePackMLState            : E_PackML_State := E_PackML_State.eSTATE_IDLE;
    bOrganoidViable         : BOOL := FALSE;
    bExcitotoxicityWarn     : BOOL := FALSE;

    (* Actuation Outputs *)
    fCsfPumpCmd_uLmin       : LREAL;
    fGluDosingCmd_uLsec     : LREAL;
    fGABADosingCmd_uLsec    : LREAL;
    fDADosingCmd_uLsec      : LREAL;
    f5HTDosingCmd_uLsec     : LREAL;
END_VAR

VAR_IN_OUT
    (* 1024 Channel MEA Data *)
    aMEAChannels            : ARRAY[1..1024] OF ST_MeaChannel;
END_VAR

VAR
    i                       : INT;
    fAverageSpikeRate       : LREAL;
    fTotalLFP               : LREAL;
    fPeakStimCurrent        : LREAL;

    (* Perfusion PI Controller *)
    fCsfError               : LREAL;
    fCsfIntegral            : LREAL;
    fKp_Csf                 : LREAL := 0.5;
    fKi_Csf                 : LREAL := 0.05;

    (* Safety Timers *)
    tExcitotoxicityTimer    : TON;
END_VAR

(* 1. PACKML STATE MACHINE *)
CASE ePackMLState OF
    E_PackML_State.eSTATE_IDLE:
        fCsfPumpCmd_uLmin := 0.1; (* Maintenance flow *)
        bOrganoidViable := TRUE;
        IF bStart THEN
            ePackMLState := E_PackML_State.eSTATE_STARTING;
        END_IF

    E_PackML_State.eSTATE_STARTING:
        (* Ramp up perfusion to nominal 1.0 uL/min *)
        IF fCsfFlowRateSens_uLmin >= 0.95 THEN
            ePackMLState := E_PackML_State.eSTATE_EXECUTE;
        ELSE
            fCsfPumpCmd_uLmin := 1.0; 
        END_IF

    E_PackML_State.eSTATE_EXECUTE:
        (* Main Closed-Loop Cultivation & Stimulation *)
        IF bStop THEN
            ePackMLState := E_PackML_State.eSTATE_STOPPING;
        ELSIF bAbort THEN
            ePackMLState := E_PackML_State.eSTATE_ABORTING;
        END_IF

    E_PackML_State.eSTATE_STOPPING:
        fCsfPumpCmd_uLmin := 0.1;
        ePackMLState := E_PackML_State.eSTATE_STOPPED;

    E_PackML_State.eSTATE_STOPPED:
        IF bReset THEN
            ePackMLState := E_PackML_State.eSTATE_IDLE;
        END_IF

    E_PackML_State.eSTATE_ABORTING:
        fCsfPumpCmd_uLmin := 0.0; (* Immediate halt of perfusion/stimulation *)
        fGluDosingCmd_uLsec := 0.0;
        fGABADosingCmd_uLsec := 0.0;
        ePackMLState := E_PackML_State.eSTATE_ABORTED;

    E_PackML_State.eSTATE_ABORTED:
        bOrganoidViable := FALSE;
        IF bReset THEN
            ePackMLState := E_PackML_State.eSTATE_CLEARED;
        END_IF

    E_PackML_State.eSTATE_CLEARED:
        ePackMLState := E_PackML_State.eSTATE_IDLE;
END_CASE

(* 2. EXECUTE STATE: ORGANOID METABOLIC & STIMULUS CONTROL *)
IF ePackMLState = E_PackML_State.eSTATE_EXECUTE THEN

    (* 2.1 Microfluidic Perfusion (CSF Analogue PI Control) *)
    (* Target flow rate: 1.0 uL/min for optimal O2/Glucose delivery *)
    fCsfError := 1.0 - fCsfFlowRateSens_uLmin;
    fCsfIntegral := fCsfIntegral + fCsfError;
    fCsfPumpCmd_uLmin := (fKp_Csf * fCsfError) + (fKi_Csf * fCsfIntegral);

    (* Pump Saturation Limits *)
    IF fCsfPumpCmd_uLmin > 5.0 THEN fCsfPumpCmd_uLmin := 5.0; END_IF;
    IF fCsfPumpCmd_uLmin < 0.1 THEN fCsfPumpCmd_uLmin := 0.1; END_IF;

    (* 2.2 MEA Bi-Directional Spike Sorting & Closed-Loop LTP *)
    fAverageSpikeRate := 0.0;

    FOR i := 1 TO 1024 DO
        fAverageSpikeRate := fAverageSpikeRate + aMEAChannels[i].fSpikeRateHz;

        (* Hebbian LTP Induction Logic *)
        IF aMEAChannels[i].fSynapticWeight < fTargetLTPWeight THEN
            (* Administer biphasic micro-current pulse *)
            aMEAChannels[i].bStimulusActive := TRUE;

            (* Proportional current up to safety limit *)
            aMEAChannels[i].fStimulusCurrent := (fTargetLTPWeight - aMEAChannels[i].fSynapticWeight) * 20.0;

            (* Enforce strictly < 10 uA threshold to prevent excitotoxicity *)
            IF aMEAChannels[i].fStimulusCurrent > fMaxStimulusCurrent_uA THEN
                aMEAChannels[i].fStimulusCurrent := fMaxStimulusCurrent_uA;
            END_IF
        ELSE
            aMEAChannels[i].bStimulusActive := FALSE;
            aMEAChannels[i].fStimulusCurrent := 0.0;
        END_IF
    END_FOR

    fAverageSpikeRate := fAverageSpikeRate / 1024.0;

    (* 2.3 Excitotoxicity Monitoring & Neurochemical Dosing *)
    (* High global spike rate > 120 Hz indicates hyperexcitability/seizure state *)
    tExcitotoxicityTimer(IN := (fAverageSpikeRate > 120.0), PT := T#500MS);

    IF tExcitotoxicityTimer.Q THEN
        bExcitotoxicityWarn := TRUE;

        (* Rapidly dose GABA (inhibitory) and halt Glutamate (excitatory) *)
        fGABADosingCmd_uLsec := 0.5;
