        (* Homeostatic Neurochemical Regulation based on Fast-Scan Cyclic Voltammetry *)
        (* Glutamate target: ~10 nM *)
        IF stNeuroSensors.fGlutamate_nM < 8.0 THEN
            fGluDosingCmd_uLsec := 0.05;
