            fDADosingCmd_uLsec := 0.0;
            f5HTDosingCmd_uLsec := 0.0;
        END_IF
    END_IF

ELSE
    (* Ensure zero stimulation if not in EXECUTE *)
    FOR i := 1 TO 1024 DO
        aMEAChannels[i].bStimulusActive := FALSE;
        aMEAChannels[i].fStimulusCurrent := 0.0;
