FUNCTION_BLOCK FB_WaferStepper_SecureSCADA
TITLE = 'Wafer Stepper - Secure, Redundant, SCADA'
VERSION : '1.3'

VAR_INPUT
    Enable : BOOL; 
    // SCADA Security & Integration (IEC 62443 simulation)
    SCADA_AuthToken : DWORD; 
    SCADA_CommandID : INT; 
    // Redundant Inputs
    PN_InterferometerFb_A : REAL; 
    PN_InterferometerFb_B : REAL; 
