FUNCTION_BLOCK FB_DAF_System_Controller
TITLE = 'Dissolved Air Flotation (DAF) Advanced Control'
VERSION : '2.1'
AUTHOR : 'Lumina Elite Synthetic Data Architect'

VAR_INPUT
    bEnable : BOOL; // System master enable
    rInletFlow : REAL; // Raw water inlet flow rate (m3/h)
    rInletTurbidity : REAL; // Raw water turbidity (NTU)
    rSatTankPressure_Actual : REAL; // Saturation tank pressure (bar)
    rSatTankLevel_Actual : REAL; // Saturation tank level (%)
    rRecycleFlow_Actual : REAL; // Recycle pump flow (m3/h)
    rSkimmerSpeed_Actual : REAL; // Skimmer actual speed (m/min)
    bSkimmerHomePos : BOOL; // Skimmer flight home position sensor
    bSkimmerEndPos : BOOL; // Skimmer flight end position sensor
    rAirCompressorPressure : REAL; // Air compressor delivery pressure (bar)
    rEffluentTurbidity : REAL; // Effluent turbidity (NTU)
END_VAR

VAR_OUTPUT
    bRecyclePumpRun : BOOL; // Command to start recycle pump
    rRecyclePumpSpeedCmd : REAL; // Recycle pump speed reference (0-100%)
    bAirCompressorRun : BOOL; // Command to start air compressor
    rAirDosingValveCmd : REAL; // Air dosing valve position (0-100%)
    bSkimmerRun : BOOL; // Command to run skimmer
    bSkimmerReverse : BOOL; // Command to reverse skimmer direction
    rSkimmerSpeedCmd : REAL; // Skimmer speed reference (m/min)
    bSatTankLevelValveCmd : BOOL; // Saturation tank level control valve
    bSystemAlarm : BOOL; // General system alarm
    iAlarmCode : INT; // Alarm code for HMI
    rCalculatedAirToSolidRatio : REAL; // Calculated A/S ratio
END_VAR

VAR
    // PID Controllers for cascades
    fbPressurePID : FB_PID_Advanced;
    fbLevelPID : FB_PID_Advanced;
    fbRecycleFlowPID : FB_PID_Advanced;

    // Internal States and Timers
    tSkimmerDelay : TON;
    tSystemStartDelay : TON;
    rTargetRecycleFlow : REAL;
    rTargetSatPressure : REAL;

    // Kinematics states
    iSkimmerState : INT; // 0=Stop, 1=Fwd, 2=Rev, 3=Wait
    rSkimmerBaseSpeed : REAL := 0.5; // Base skimmer speed m/min

    // Configuration parameters
    rAS_RatioSetpoint : REAL := 0.025; // Target Air to Solid ratio
    rMaxRecycleRatio : REAL := 0.20; // Max 20% recycle
    rSatPressureSetpt : REAL := 5.5; // Target 5.5 bar

    bInit : BOOL := TRUE;
END_VAR

// -----------------------------------------------------------------------------
// DAF SYSTEM COMPLEX CONTROL LOGIC
// -----------------------------------------------------------------------------
IF bInit THEN
    iSkimmerState := 0;
    bSystemAlarm := FALSE;
    iAlarmCode := 0;
    bInit := FALSE;
END_IF;

IF NOT bEnable THEN
    bRecyclePumpRun := FALSE;
    bAirCompressorRun := FALSE;
    bSkimmerRun := FALSE;
    rRecyclePumpSpeedCmd := 0.0;
    rAirDosingValveCmd := 0.0;
    rSkimmerSpeedCmd := 0.0;
    bSatTankLevelValveCmd := FALSE;
    iSkimmerState := 0;
    RETURN;
END_IF;

// 1. Calculate Air-to-Solid (A/S) Ratio based on inlet flow and turbidity
// Assuming nominal solids concentration is directly proportional to turbidity for this model
rCalculatedAirToSolidRatio := (rRecycleFlow_Actual * rSatTankPressure_Actual * 0.015) / (rInletFlow * rInletTurbidity * 0.001 + 0.0001);

// 2. Cascade Control: Recycle Flow Setpoint based on Inlet Flow and Turbidity
// Dynamic recycle ratio adjustment to maintain A/S ratio
rTargetRecycleFlow := rInletFlow * rMaxRecycleRatio * (rInletTurbidity / 100.0);
IF rTargetRecycleFlow > (rInletFlow * rMaxRecycleRatio) THEN
    rTargetRecycleFlow := rInletFlow * rMaxRecycleRatio;
END_IF;

// Recycle Pump Flow PID
fbRecycleFlowPID(
    bEnable := TRUE,
    rSetpoint := rTargetRecycleFlow,
    rProcessValue := rRecycleFlow_Actual,
    rKp := 1.2,
    rKi := 0.5,
    rKd := 0.1,
    rOutput => rRecyclePumpSpeedCmd
);
bRecyclePumpRun := rRecyclePumpSpeedCmd > 5.0;

// 3. Saturation Tank Pressure Control
// Air dosing valve is modulated to maintain saturation pressure
fbPressurePID(
    bEnable := bRecyclePumpRun,
    rSetpoint := rSatPressureSetpt,
    rProcessValue := rSatTankPressure_Actual,
    rKp := 2.5,
    rKi := 1.0,
    rKd := 0.0,
    rOutput => rAirDosingValveCmd
);
bAirCompressorRun := bRecyclePumpRun AND (rSatTankPressure_Actual < (rSatPressureSetpt - 0.5));

// 4. Saturation Tank Level Control
// On/Off or discrete modulation of level valve to prevent air breakthrough or water carryover
IF rSatTankLevel_Actual > 65.0 THEN
    bSatTankLevelValveCmd := TRUE; // Open bleed
ELSIF rSatTankLevel_Actual < 45.0 THEN
    bSatTankLevelValveCmd := FALSE; // Close bleed
END_IF;

// 5. Surface Skimmer Flight Kinematics
// Skimmer speed is dynamically adjusted based on effluent turbidity
tSkimmerDelay(IN:= (iSkimmerState = 3), PT:= T#2M);

CASE iSkimmerState OF
    0: // Stop/Ready
        bSkimmerRun := FALSE;
        bSkimmerReverse := FALSE;
        rSkimmerSpeedCmd := 0.0;
        IF bRecyclePumpRun AND rEffluentTurbidity > 5.0 THEN
            iSkimmerState := 1; // Start Skimming
        END_IF;

    1: // Forward motion
        bSkimmerRun := TRUE;
        bSkimmerReverse := FALSE;
        // Dynamic speed based on sludge loading (approximated by inlet turbidity)
        rSkimmerSpeedCmd := rSkimmerBaseSpeed + (rInletTurbidity * 0.01);
        IF rSkimmerSpeedCmd > 2.5 THEN rSkimmerSpeedCmd := 2.5; END_IF;

        IF bSkimmerEndPos THEN
            iSkimmerState := 2; // Reverse to home or clear
        END_IF;

    2: // Reverse motion
        bSkimmerRun := TRUE;
        bSkimmerReverse := TRUE;
        rSkimmerSpeedCmd := 3.0; // Fast return

        IF bSkimmerHomePos THEN
            iSkimmerState := 3; // Wait state
        END_IF;

    3: // Wait delay before next cycle
        bSkimmerRun := FALSE;
        rSkimmerSpeedCmd := 0.0;
        IF tSkimmerDelay.Q THEN
            iSkimmerState := 0; // Return to ready
        END_IF;
END_CASE;

// 6. Alarms and Interlocks
IF rSatTankPressure_Actual > 8.0 THEN
    bSystemAlarm := TRUE;
    iAlarmCode := 101; // Overpressure
ELSIF rSatTankLevel_Actual < 10.0 THEN
    bSystemAlarm := TRUE;
    iAlarmCode := 102; // Loss of level
ELSIF rRecyclePumpSpeedCmd > 90.0 AND rRecycleFlow_Actual < (rTargetRecycleFlow * 0.5) THEN
    bSystemAlarm := TRUE;
    iAlarmCode := 103; // Recycle pump failure / cavitation
ELSE
    bSystemAlarm := FALSE;
    iAlarmCode := 0;
END_IF;

END_FUNCTION_BLOCK
