FUNCTION_BLOCK FB_TissueLogRewinder_MasterControl
// Highly complex ST control block for Tissue Paper Log Rewinder
// Features: Dancer Roll PID, Core Glue Tracking, Log Saw Synchronous Orbital Motion

VAR_INPUT
    bEnable             : BOOL;     // System master enable
    bEStop              : BOOL;     // Emergency stop (Active LOW)
    rMasterLineSpeed    : REAL;     // Line speed reference (m/min)
    rDancerActualPos    : REAL;     // Actual dancer roll position (0.0 - 100.0%)
    rDancerTargetPos    : REAL;     // Setpoint for dancer roll position (0.0 - 100.0%)
    bCoreDetected       : BOOL;     // Core presence sensor in gluing station
    rLogDiameterActual  : REAL;     // Current diameter of the winding log (mm)
    rLogDiameterTarget  : REAL;     // Target log diameter before cut (mm)
    rSawOrbitalAngle    : REAL;     // Current angle of the orbital saw (Degrees)
    bGlueSystemReady    : BOOL;     // Glue pump and heaters ready
END_VAR

VAR_OUTPUT
    rUnwindSpeedRef     : REAL;     // Speed reference to unwind drive (m/min)
    bGlueValveEnable    : BOOL;     // Trigger for core glue applicator
    rSawMotorSpeedRef   : REAL;     // Speed reference to log saw orbital motor (RPM)
    bSawCutCommand      : BOOL;     // Trigger to extend the saw blade
    bSystemFault        : BOOL;     // General fault flag
    nFaultCode          : INT;      // Specific fault code
    rWebTensionOut      : REAL;     // Estimated web tension (N)
END_VAR

VAR
    // Dancer PID Variables
    fbDancerPID         : PID;      // Standard PID block instance
    rDancerError        : REAL;
    rKp                 : REAL := 2.5;
    rKi                 : REAL := 1.2;
    rKd                 : REAL := 0.05;

    // Gluing Tracking Variables
    tmrGlueDelay        : TON;
    tmrGlueDuration     : TON;
    nCoreTrackingIdx    : INT := 0;
    rCorePosition       : REAL;

    // Saw Synchronous Motion Variables
    bCutCycleActive     : BOOL;
    rSawSyncSpeed       : REAL;
    rCutPhaseError      : REAL;
    rCutDiameterOffset  : REAL := 5.0; // Trigger cut slightly before target

    // State Machine
    nState              : INT := 0;

    // Constants
    C_MAX_UNWIND_SPEED  : REAL := 1500.0; // Max unwind speed m/min
    C_SAW_ORBIT_RADIUS  : REAL := 300.0;  // Radius of orbital saw path (mm)
    C_PI                : REAL := 3.14159265359;
END_VAR

// --- Safety and Enable Logic ---
IF NOT bEStop THEN
    nState := 99; // Fault state
    nFaultCode := 1; // E-Stop pressed
    bSystemFault := TRUE;
    rUnwindSpeedRef := 0.0;
    bGlueValveEnable := FALSE;
    rSawMotorSpeedRef := 0.0;
    RETURN;
END_IF;

IF NOT bEnable THEN
    nState := 0; // Stopped state
    bSystemFault := FALSE;
    nFaultCode := 0;
    rUnwindSpeedRef := 0.0;
    bGlueValveEnable := FALSE;
    rSawMotorSpeedRef := 0.0;
    bCutCycleActive := FALSE;
    RETURN;
END_IF;

// --- Dancer Roll PID for Tension Control ---
// Calculate error between actual dancer position and target position
rDancerError := rDancerTargetPos - rDancerActualPos;

// Execute PID (Assuming external standard PID function block)
fbDancerPID(
    EN := TRUE,
    ACT := rDancerActualPos,
    SET := rDancerTargetPos,
    KP := rKp,
    KI := rKi,
    KD := rKd,
    OUT => rWebTensionOut
);

// Trim unwind speed based on dancer PID output to maintain constant tension
rUnwindSpeedRef := rMasterLineSpeed + rWebTensionOut;

// Clamp unwind speed
IF rUnwindSpeedRef > C_MAX_UNWIND_SPEED THEN
    rUnwindSpeedRef := C_MAX_UNWIND_SPEED;
ELSIF rUnwindSpeedRef < 0.0 THEN
    rUnwindSpeedRef := 0.0;
END_IF;

// --- Core Gluing Tracking ---
// When a core is detected, initiate tracking for precise glue application
IF bCoreDetected AND bGlueSystemReady THEN
    // Start tracking delay timer based on line speed to align glue valve with core
    tmrGlueDelay(IN := TRUE, PT := T#500MS); // Dynamic delay based on speed in real app
ELSE
    tmrGlueDelay(IN := FALSE);
END_IF;

// Trigger glue application for a specific duration
IF tmrGlueDelay.Q THEN
    bGlueValveEnable := TRUE;
    tmrGlueDuration(IN := TRUE, PT := T#150MS);
END_IF;

IF tmrGlueDuration.Q THEN
    bGlueValveEnable := FALSE;
    tmrGlueDuration(IN := FALSE);
    tmrGlueDelay(IN := FALSE); // Reset sequence
END_IF;

// --- Log Saw Synchronous Orbital Motion ---
// The saw must match the web speed at the exact moment of the cut
IF (rLogDiameterActual >= (rLogDiameterTarget - rCutDiameterOffset)) AND NOT bCutCycleActive THEN
    bCutCycleActive := TRUE;
END_IF;

IF bCutCycleActive THEN
    // Calculate the required orbital speed to synchronize the blade linear speed with web speed
    // v = w * r -> w = v / r. Convert m/min to RPM for the saw orbit motor.
    rSawSyncSpeed := (rMasterLineSpeed * 1000.0) / (2.0 * C_PI * C_SAW_ORBIT_RADIUS);

    // Apply a cam profile phase correction to ensure blade enters at 180 degrees (bottom dead center)
    IF rSawOrbitalAngle < 170.0 THEN
        // Accelerate to catch up
        rSawMotorSpeedRef := rSawSyncSpeed * 1.1;
    ELSIF rSawOrbitalAngle > 190.0 AND rSawOrbitalAngle < 270.0 THEN
        // Decelerate after cut
        rSawMotorSpeedRef := rSawSyncSpeed * 0.5;
    ELSE
        // Synchronized speed through the cut zone
        rSawMotorSpeedRef := rSawSyncSpeed;
    END_IF;

    // Execute cut when perfectly aligned
    IF rSawOrbitalAngle >= 178.0 AND rSawOrbitalAngle <= 182.0 THEN
        bSawCutCommand := TRUE;
    ELSE
        bSawCutCommand := FALSE;
    END_IF;

    // Reset cycle when orbit is complete (360 degrees)
    IF rSawOrbitalAngle >= 355.0 THEN
        bCutCycleActive := FALSE;
        bSawCutCommand := FALSE;
        rSawMotorSpeedRef := 0.0;
    END_IF;
ELSE
    rSawMotorSpeedRef := 0.0;
    bSawCutCommand := FALSE;
END_IF;

END_FUNCTION_BLOCK
