FUNCTION_BLOCK FB_HighSpeedSausagePeeler
VAR_INPUT
    bEnable : BOOL; // Enable peeling process
    rTrackSpeed_mm_s : REAL; // Current track speed in mm/s
    rProductLength_mm : REAL; // Length of the sausage
    rProductDiameter_mm : REAL; // Diameter of the sausage
    bProductDetected : BOOL; // Optical sensor for product entry
    rSteamPressureSetpoint_bar : REAL; // Target steam pressure
    rVacuumLevelSetpoint_mbar : REAL; // Target vacuum level
END_VAR

VAR_OUTPUT
    bSystemReady : BOOL;
    bSteamValveOpen : BOOL;
    rSteamValvePosition_pct : REAL;
    bVacuumValveOpen : BOOL;
    rVacuumPumpSpeed_rpm : REAL;
    bAirKnifeActive : BOOL;
    rAirKnifePressure_bar : REAL;
    bFault : BOOL;
    iFaultCode : INT;
END_VAR

VAR
    iState : INT := 0; // State machine step
    fbTimerDelay : TON; // Timer for process delays
    fbSteamPID : PID; // PID for steam pressure
    fbVacuumPID : PID; // PID for vacuum level
    rCurrentSteamPressure_bar : REAL; // Feedback from sensor
    rCurrentVacuumLevel_mbar : REAL; // Feedback from sensor
    rCalculatedDwellTime_ms : REAL; // Calculated dwell time based on track speed
    rKinematicOffset_mm : REAL; // Kinematic tracking offset

    // Internal flags
    bProductInZone1 : BOOL;
    bProductInZone2 : BOOL;
    bProcessActive : BOOL;
END_VAR

// State Machine for High-Speed Peeling Process
CASE iState OF
    0: // IDLE and Initialization
        bSystemReady := TRUE;
        bSteamValveOpen := FALSE;
        bVacuumValveOpen := FALSE;
        bAirKnifeActive := FALSE;
        bFault := FALSE;

        IF bEnable AND bProductDetected THEN
            iState := 10;
            bSystemReady := FALSE;
            bProcessActive := TRUE;
        END_IF

    10: // Kinematics Tracking and Synchronization
        // Calculate dynamic offset based on track speed
        rCalculatedDwellTime_ms := (rProductLength_mm / MAX(rTrackSpeed_mm_s, 1.0)) * 1000.0;
        rKinematicOffset_mm := rTrackSpeed_mm_s * 0.05; // 50ms transport delay compensation

        IF rTrackSpeed_mm_s > 1500.0 THEN // High-speed profile
            iState := 20;
        ELSIF rTrackSpeed_mm_s > 500.0 THEN // Standard profile
            iState := 30;
        ELSE
            iState := 999; // Fault: Speed too low
            iFaultCode := 1;
        END_IF

    20: // Steam Treatment (High-Speed)
        bSteamValveOpen := TRUE;
        // PID loop for steam pressure
        fbSteamPID(
            ENABLE := TRUE,
            SP := rSteamPressureSetpoint_bar,
            PV := rCurrentSteamPressure_bar,
            KP := 2.5,
            KI := 0.5,
            KD := 0.1,
            OUT => rSteamValvePosition_pct
        );

        fbTimerDelay(IN := TRUE, PT := DINT_TO_TIME(REAL_TO_DINT(rCalculatedDwellTime_ms / 2.0)));
        IF fbTimerDelay.Q THEN
            fbTimerDelay(IN := FALSE);
            iState := 40;
        END_IF

    30: // Steam Treatment (Standard)
        bSteamValveOpen := TRUE;
        fbSteamPID(
            ENABLE := TRUE,
            SP := rSteamPressureSetpoint_bar * 0.8, // Reduced pressure for standard speed
            PV := rCurrentSteamPressure_bar,
            KP := 2.0,
            KI := 0.4,
            KD := 0.1,
            OUT => rSteamValvePosition_pct
        );

        fbTimerDelay(IN := TRUE, PT := DINT_TO_TIME(REAL_TO_DINT(rCalculatedDwellTime_ms)));
        IF fbTimerDelay.Q THEN
            fbTimerDelay(IN := FALSE);
            iState := 40;
        END_IF

    40: // Vacuum Separation
        bSteamValveOpen := FALSE;
        rSteamValvePosition_pct := 0.0;
        bVacuumValveOpen := TRUE;

        // Regulate vacuum pump speed
        fbVacuumPID(
            ENABLE := TRUE,
            SP := rVacuumLevelSetpoint_mbar,
            PV := rCurrentVacuumLevel_mbar,
            KP := 1.5,
            KI := 0.2,
            KD := 0.05,
            OUT => rVacuumPumpSpeed_rpm
        );

        // Time based on product dimensions
        fbTimerDelay(IN := TRUE, PT := DINT_TO_TIME(REAL_TO_DINT(rProductDiameter_mm * 10.0)));
        IF fbTimerDelay.Q THEN
            fbTimerDelay(IN := FALSE);
            iState := 50;
        END_IF

    50: // Air Knife Blow-off Profiling
        bVacuumValveOpen := FALSE;
        rVacuumPumpSpeed_rpm := 0.0;
        bAirKnifeActive := TRUE;

        // Profile air pressure dynamically based on length
        rAirKnifePressure_bar := (rProductLength_mm / 100.0) * 1.5;
        IF rAirKnifePressure_bar > 6.0 THEN
            rAirKnifePressure_bar := 6.0; // Max limit
        END_IF

        fbTimerDelay(IN := TRUE, PT := T#200MS);
        IF fbTimerDelay.Q THEN
            fbTimerDelay(IN := FALSE);
            bAirKnifeActive := FALSE;
            rAirKnifePressure_bar := 0.0;
            bProcessActive := FALSE;
            iState := 0; // Return to IDLE
        END_IF

    999: // FAULT STATE
        bSteamValveOpen := FALSE;
        bVacuumValveOpen := FALSE;
        bAirKnifeActive := FALSE;
        rSteamValvePosition_pct := 0.0;
        rVacuumPumpSpeed_rpm := 0.0;
        rAirKnifePressure_bar := 0.0;
        bFault := TRUE;
        bProcessActive := FALSE;

        IF NOT bEnable THEN // Reset fault by dropping enable
            iState := 0;
            bFault := FALSE;
            iFaultCode := 0;
        END_IF

END_CASE
END_FUNCTION_BLOCK
