FUNCTION_BLOCK FB_EBL_ColumnControl
VAR_INPUT
    bSystemEnable       : BOOL;     (* System master enable for EBL column *)
    bSafetyInterlock    : BOOL;     (* Vacuum and High Voltage safety interlocks OK *)
    rAccelVoltage_kV    : REAL;     (* Target acceleration voltage (e.g., 100.0 kV) *)
    rEmissionCurrent_uA : REAL;     (* Target emission current for thermionic gun (uA) *)
    rDeflectionX_nm     : REAL;     (* Target X-axis deflection vector (nm) *)
    rDeflectionY_nm     : REAL;     (* Target Y-axis deflection vector (nm) *)
    rBSE_SignalLevel    : REAL;     (* Backscattered electron detector raw signal (V) *)
END_VAR
VAR_OUTPUT
    bReadyForWriting    : BOOL;     (* Beam is stable and positioned, ready to write *)
    rActualEmission_uA  : REAL;     (* Measured emission current feedback (uA) *)
    rLens1Current_mA    : REAL;     (* Condenser lens 1 excitation current (mA) *)
    rLens2Current_mA    : REAL;     (* Condenser lens 2 excitation current (mA) *)
    rDeflectionXOut_V   : REAL;     (* X-axis deflection coil drive voltage (V) *)
    rDeflectionYOut_V   : REAL;     (* Y-axis deflection coil drive voltage (V) *)
    bBeamBlanked        : BOOL;     (* Beam blanking status (TRUE = blanked) *)
    iErrorCode          : INT;      (* 0 = OK, >0 = Fault Code *)
END_VAR
VAR
    iState              : INT := 0; (* State machine state *)
    tStabilizationTimer : TON;      (* Timer for thermal and magnetic stabilization *)

    rEmissionError      : REAL;
    rEmissionInteg      : REAL;
    KP_EMISSION         : REAL := 0.05;
    KI_EMISSION         : REAL := 0.01;

    rTargetX_V          : REAL;
    rTargetY_V          : REAL;
    DEFLECTION_SENS     : REAL := 0.001; (* V/nm calibration *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bSafetyInterlock THEN
    bReadyForWriting := FALSE;
    bBeamBlanked := TRUE;
    rActualEmission_uA := 0.0;
    rLens1Current_mA := 0.0;
    rLens2Current_mA := 0.0;
    rDeflectionXOut_V := 0.0;
    rDeflectionYOut_V := 0.0;
    iErrorCode := 1001; (* Interlock broken *)
    iState := 0;
    RETURN;
END_IF;

CASE iState OF
    0: (* IDLE & SAFE *)
        bReadyForWriting := FALSE;
        bBeamBlanked := TRUE;
        rActualEmission_uA := 0.0;
        iErrorCode := 0;
        IF bSystemEnable THEN
            iState := 10; (* Start HV & Emission *)
        END_IF;

    10: (* RAMPING EMISSION & HV *)
        (* Closed-loop PI control for thermionic emission *)
        rEmissionError := rEmissionCurrent_uA - rActualEmission_uA;
        rEmissionInteg := rEmissionInteg + (rEmissionError * 0.1);
        rActualEmission_uA := rActualEmission_uA + (KP_EMISSION * rEmissionError) + (KI_EMISSION * rEmissionInteg);

        (* Ramp magnetic lenses based on acceleration voltage *)
        rLens1Current_mA := rAccelVoltage_kV * 2.5; 
        rLens2Current_mA := rAccelVoltage_kV * 3.8;

        IF ABS(rEmissionError) < 0.5 THEN
            tStabilizationTimer(IN := TRUE, PT := T#10S);
            IF tStabilizationTimer.Q THEN
                tStabilizationTimer(IN := FALSE);
                iState := 20; (* Vector Positioning *)
            END_IF;
        ELSE
            tStabilizationTimer(IN := FALSE);
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    20: (* VECTOR POSITIONING & DEFLECTION SETTLING *)
        (* Calculate deflection voltages with extremely fine resolution *)
        rTargetX_V := rDeflectionX_nm * DEFLECTION_SENS;
        rTargetY_V := rDeflectionY_nm * DEFLECTION_SENS;

        (* Simulate nanometer precision coil driving with slew rate limits *)
        IF rDeflectionXOut_V < rTargetX_V THEN
            rDeflectionXOut_V := rDeflectionXOut_V + 0.005;
        ELSIF rDeflectionXOut_V > rTargetX_V THEN
            rDeflectionXOut_V := rDeflectionXOut_V - 0.005;
        END_IF;

        IF rDeflectionYOut_V < rTargetY_V THEN
            rDeflectionYOut_V := rDeflectionYOut_V + 0.005;
        ELSIF rDeflectionYOut_V > rTargetY_V THEN
            rDeflectionYOut_V := rDeflectionYOut_V - 0.005;
        END_IF;

        IF ABS(rDeflectionXOut_V - rTargetX_V) < 0.001 AND ABS(rDeflectionYOut_V - rTargetY_V) < 0.001 THEN
            iState := 30; (* Ready to Write *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    30: (* READY TO WRITE / WRITING *)
        bReadyForWriting := TRUE;
        bBeamBlanked := FALSE; (* Unblank beam for lithography exposure *)

        (* Topographic focus compensation via BSE feedback *)
        IF rBSE_SignalLevel > 5.0 THEN
            rLens2Current_mA := rLens2Current_mA + 0.01; (* Fine focus adjustment *)
        ELSIF rBSE_SignalLevel < 2.0 THEN
            rLens2Current_mA := rLens2Current_mA - 0.01;
        END_IF;

        IF ABS(rDeflectionXOut_V - (rDeflectionX_nm * DEFLECTION_SENS)) > 0.01 OR 
           ABS(rDeflectionYOut_V - (rDeflectionY_nm * DEFLECTION_SENS)) > 0.01 THEN
            bReadyForWriting := FALSE;
            bBeamBlanked := TRUE;
            iState := 20; (* Reposition *)
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;

    ELSE
        iErrorCode := 9999; (* Invalid State *)
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
```

