FUNCTION_BLOCK "Lyophilizer_Mut1"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    StartDefrost : Bool;
    VacuumSetPoint : Real;
    TempSetPoint : Real;
    ActualVacuum : Real;
    ActualTemp : Real;
    CondenserTemp : Real;
END_VAR
VAR_OUTPUT
    VacuumValveControl : Real;
    HeaterControl : Real;
    CoolingControl : Real;
    DefrostHeater : Bool;
    DrainValve : Bool;
END_VAR
VAR
    PID_Vacuum : "PID_Compact";
    PID_Temp : "PID_Compact";
    State : Int;
    DefrostTimer : TON;
END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    ELSIF StartDefrost AND State = 0 THEN
        State := 2;
    END_IF;

    CASE State OF
        0: 
            VacuumValveControl := 0.0;
            HeaterControl := 0.0;
            CoolingControl := 0.0;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        1: 
            PID_Vacuum(Setpoint:=VacuumSetPoint, Input:=ActualVacuum, Output=>VacuumValveControl);
            PID_Temp(Setpoint:=TempSetPoint, Input:=ActualTemp, Output=>HeaterControl);
            CoolingControl := 100.0 - HeaterControl;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        2: 
            DefrostHeater := TRUE;
            DrainValve := TRUE;
            DefrostTimer(IN:=TRUE, PT:=T#30M);
            IF DefrostTimer.Q OR CondenserTemp > 20.0 THEN
                DefrostHeater := FALSE;
                DrainValve := FALSE;
                DefrostTimer(IN:=FALSE, PT:=T#30M);
                State := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
