FUNCTION_BLOCK FB_CSP_sCO2_Brayton_Controller
VAR_INPUT
    bSystemEnable       : BOOL;     (* Master enable for sCO2 Brayton cycle *)
    bEStop              : BOOL;     (* Emergency Stop signal, active LOW *)
    rTurbineInletTemp   : REAL;     (* Turbine inlet temperature in deg C (target ~700C) *)
    rRecuperatorTemp    : REAL;     (* High temp recuperator stress mapping temp in deg C *)
    rCompressorSpeed    : REAL;     (* Main compressor speed in RPM (target ~100k) *)
    rCoolingWaterTemp   : REAL;     (* Dry cooling tower return water temp in deg C *)
    rMagBearingGapX     : REAL;     (* Active magnetic bearing X-axis gap in micrometers *)
    rMagBearingGapY     : REAL;     (* Active magnetic bearing Y-axis gap in micrometers *)
END_VAR
VAR_OUTPUT
    bTurbineTrip        : BOOL;     (* Turbine trip command due to overspeed or thermal stress *)
    rBearingControlX    : REAL;     (* PWM or analog control signal to X-axis magnetic bearing coil *)
    rBearingControlY    : REAL;     (* PWM or analog control signal to Y-axis magnetic bearing coil *)
    rBypassValveCmd     : REAL;     (* sCO2 bypass valve command 0-100% for capacity control *)
    rCoolingFanSpeed    : REAL;     (* Cascaded dry cooling tower fan speed command 0-100% *)
    bSystemReady        : BOOL;     (* Controller ready and operating nominally *)
END_VAR
VAR
    iState              : INT := 0; (* Internal state machine *)
    tRecuperatorTimer   : TON;      (* Timer for recuperator thermal soak *)
    rThermalStress      : REAL;     (* Calculated thermal stress index for recuperator *)
    rBearingErrX        : REAL;     (* Magnetic bearing X error *)
    rBearingErrY        : REAL;     (* Magnetic bearing Y error *)
    rBearingIntegralX   : REAL;
    rBearingIntegralY   : REAL;
    rKp                 : REAL := 2.5;
    rKi                 : REAL := 0.05;
    rKd                 : REAL := 1.2;
    rPrevErrX           : REAL;
    rPrevErrY           : REAL;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEStop THEN
    bTurbineTrip := TRUE;
    rBypassValveCmd := 100.0; (* Full bypass on E-Stop *)
    rCoolingFanSpeed := 100.0; (* Max cooling *)
    bSystemReady := FALSE;
    iState := 0;
    RETURN;
END_IF;

(* === MAGNETIC BEARING LEVITATION CONTROL (100k RPM) === *)
(* Ultra high-speed PID loops for magnetic levitation (simplified for this ST block) *)
rBearingErrX := 50.0 - rMagBearingGapX; (* Target gap 50um *)
rBearingIntegralX := rBearingIntegralX + rBearingErrX;
rBearingControlX := (rKp * rBearingErrX) + (rKi * rBearingIntegralX) + (rKd * (rBearingErrX - rPrevErrX));
rPrevErrX := rBearingErrX;

rBearingErrY := 50.0 - rMagBearingGapY;
rBearingIntegralY := rBearingIntegralY + rBearingErrY;
rBearingControlY := (rKp * rBearingErrY) + (rKi * rBearingIntegralY) + (rKd * (rBearingErrY - rPrevErrY));
rPrevErrY := rBearingErrY;

(* === THERMAL STRESS MAPPING === *)
(* High Temp Recuperator delta T monitoring to prevent low-cycle fatigue *)
rThermalStress := ABS(rTurbineInletTemp - rRecuperatorTemp) * 0.15;
IF rThermalStress > 85.0 THEN
    bTurbineTrip := TRUE;
    iState := 99; (* Trip state *)
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & LEVITATION CHECK *)
        bSystemReady := FALSE;
        rBypassValveCmd := 100.0;
        IF bSystemEnable AND (ABS(rBearingErrX) < 5.0) AND (ABS(rBearingErrY) < 5.0) THEN
            iState := 10;
        END_IF;

    10: (* THERMAL SOAKING *)
        tRecuperatorTimer(IN := TRUE, PT := T#120S);
        IF tRecuperatorTimer.Q THEN
            tRecuperatorTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* RAMP TO FULL SPEED *)
        rBypassValveCmd := rBypassValveCmd - 0.1;
        IF rBypassValveCmd <= 0.0 THEN
            rBypassValveCmd := 0.0;
            IF rCompressorSpeed >= 98000.0 THEN
                iState := 30;
            END_IF;
        END_IF;

    30: (* NOMINAL OPERATION *)
        bSystemReady := TRUE;
        bTurbineTrip := FALSE;
        (* Cascade cooling control *)
        IF rCoolingWaterTemp > 40.0 THEN
            rCoolingFanSpeed := 100.0;
        ELSIF rCoolingWaterTemp > 35.0 THEN
            rCoolingFanSpeed := 75.0;
        ELSE
            rCoolingFanSpeed := 50.0;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 40;
        END_IF;

    40: (* SHUTDOWN SEQUENCE *)
        bSystemReady := FALSE;
        rBypassValveCmd := rBypassValveCmd + 0.5;
        IF rBypassValveCmd >= 100.0 THEN
            iState := 0;
        END_IF;

    99: (* THERMAL/OVERSPEED TRIP *)
        bSystemReady := FALSE;
        bTurbineTrip := TRUE;
        rBypassValveCmd := 100.0;
        rCoolingFanSpeed := 100.0;
        IF NOT bSystemEnable THEN
            iState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
