FUNCTION_BLOCK FB_Benthic_CarbonInjection
VAR_INPUT
    bEnable                 : BOOL;   (* System enable *)
    bStart                  : BOOL;   (* Start injection process *)
    bAbort                  : BOOL;   (* Emergency abort *)

    // Process Variables
    fCO2_Liquid_Temp        : LREAL;  (* deg C, target > 31.1 C for supercritical *)
    fCO2_Liquid_Press       : LREAL;  (* bar, target > 73.9 bar for supercritical *)
