    bSupercritical          : BOOL;
    bInjectionActive        : BOOL;
    bAlarm                  : BOOL;
END_VAR

VAR
    // Internal Control Logic
    PID_Press               : FB_PID; // Assuming standard PID implementation exists
    PID_Temp                : FB_PID;

    fTarget_CO2_Press       : LREAL := 85.0; (* bar, safe margin above 73.9 *)
    fTarget_CO2_Temp        : LREAL := 40.0; (* deg C, safe margin above 31.1 *)

    // Thermodynamics & Kinetics Constants
    c_fGasConstant          : LREAL := 8.314462618; (* J / (mol K) *)
    c_fBasalt_Reactivity    : LREAL := 1.5E-6; (* mol / (m^2 s) *)

    i                       : INT;
    fSeismic_Avg            : LREAL;
    fPressure_Delta         : LREAL;

    // Timers
    tonInjection            : TON;
END_VAR

(* 
  =============================================================================
  Benthic Carbon Mineralization & Supercritical CO2 Basalt Injection Controller
  =============================================================================
*)

// 1. PackML State Machine
CASE ePackML OF
    eSTATE_STOPPED:
        fCO2_Pump_Speed := 0.0;
        fCO2_Heater_Output := 0.0;
        fCoInjection_Valve := 0.0;
        bInjectionActive := FALSE;

        IF bAbort THEN
            ePackML := eSTATE_ABORTING;
        ELSIF bEnable THEN
            ePackML := eSTATE_IDLE;
        END_IF

    eSTATE_IDLE:
        IF bAbort THEN
            ePackML := eSTATE_ABORTING;
        ELSIF NOT bEnable THEN
            ePackML := eSTATE_STOPPED;
        ELSIF bStart THEN
            ePackML := eSTATE_STARTING;
        END_IF

    eSTATE_STARTING:
        // Ramp up heaters and establish supercritical conditions before injection
        PID_Temp(
            bEnable := TRUE,
            fSetpoint := fTarget_CO2_Temp,
            fActualValue := fCO2_Liquid_Temp,
            fKp := 2.5, fTi := 10.0, fTd := 0.0,
            fOutput => fCO2_Heater_Output
        );

        PID_Press(
            bEnable := TRUE,
            fSetpoint := fTarget_CO2_Press,
            fActualValue := fCO2_Liquid_Press,
            fKp := 1.8, fTi := 5.0, fTd := 0.5,
            fOutput => fCO2_Pump_Speed
        );

        // Check Phase State
        bSupercritical := (fCO2_Liquid_Temp > 31.1) AND (fCO2_Liquid_Press > 73.9);

        IF bSupercritical THEN
            ePackML := eSTATE_EXECUTE;
        END_IF

        IF bAbort THEN ePackML := eSTATE_ABORTING; END_IF

    eSTATE_EXECUTE:
        bInjectionActive := TRUE;

        // Maintain Supercritical State
        PID_Temp(bEnable:=TRUE, fSetpoint:=fTarget_CO2_Temp, fActualValue:=fCO2_Liquid_Temp, fOutput=>fCO2_Heater_Output);
        PID_Press(bEnable:=TRUE, fSetpoint:=fTarget_CO2_Press, fActualValue:=fCO2_Liquid_Press, fOutput=>fCO2_Pump_Speed);
        bSupercritical := (fCO2_Liquid_Temp > 31.1) AND (fCO2_Liquid_Press > 73.9);

        // 2. Downhole Co-Injection Mixer Control
        // Modulate injection valve to maintain proper CO2-Seawater dissolution ratio
        // Downhole hydrostatic pressure must be overcome by CO2 pressure
        fPressure_Delta := fCO2_Liquid_Press - fSeawater_Press;

        IF fPressure_Delta > 10.0 AND bSupercritical THEN
            fCoInjection_Valve := 100.0; // Fully open co-injection
        ELSE
            // Throttle to maintain minimum overpressure
            fCoInjection_Valve := 50.0;
        END_IF

        // 3. Basaltic Mineralization Tracking
        // Process micro-seismic array to estimate plume front
        fSeismic_Avg := 0.0;
        FOR i := 1 TO 16 DO
            fSeismic_Avg := fSeismic_Avg + aMicroSeismic_Array[i];
        END_FOR
        fSeismic_Avg := fSeismic_Avg / 16.0;

        // Plume radius empirical estimation based on acoustic emissions (AE)
        fPlume_Radius := fPlume_Radius + (fSeismic_Avg * 0.01);

        // Estimate Geochemical Kinetics (Calcite / Magnesite precipitation)
        // High temp + low pH initially, dissolving silicates
        stMineralizationStatus.fFluid_pH := 3.5 + (fPlume_Radius * 0.05); // Approaches 7.0 as neutralization occurs

        // Saturation index calculation (simplified model)
        stMineralizationStatus.fCalcite_Sat_Index := LOG((stMineralizationStatus.fFluid_pH * fDownhole_Temp) / c_fGasConstant);
        stMineralizationStatus.fMagnesite_Sat_Index := stMineralizationStatus.fCalcite_Sat_Index * 0.92;

        // Pressure modulation for chemical weathering optimization
        // If saturation index is too low, pulse the pressure to induce micro-fractures
        IF stMineralizationStatus.fCalcite_Sat_Index < 0.0 THEN
            fTarget_CO2_Press := 95.0; // Pressure pulse
        ELSE
            fTarget_CO2_Press := 85.0; // Baseline
        END_IF

        IF bAbort THEN
            ePackML := eSTATE_ABORTING;
        ELSIF NOT bEnable THEN
            ePackML := eSTATE_STOPPED;
        END_IF

        // Loss of supercritical condition drops back to holding or fault
        IF NOT bSupercritical THEN
            ePackML := eSTATE_HOLDING;
        END_IF

    eSTATE_HOLDING:
        bInjectionActive := FALSE;
        fCoInjection_Valve := 0.0; // Isolate well

        // Attempt to recover temperature/pressure
        PID_Temp(bEnable:=TRUE, fSetpoint:=fTarget_CO2_Temp, fActualValue:=fCO2_Liquid_Temp, fOutput=>fCO2_Heater_Output);
        PID_Press(bEnable:=TRUE, fSetpoint:=fTarget_CO2_Press, fActualValue:=fCO2_Liquid_Press, fOutput=>fCO2_Pump_Speed);

        bSupercritical := (fCO2_Liquid_Temp > 31.1) AND (fCO2_Liquid_Press > 73.9);
        IF bSupercritical THEN
            ePackML := eSTATE_EXECUTE;
        END_IF

        IF bAbort THEN ePackML := eSTATE_ABORTING; END_IF

    eSTATE_ABORTING:
        // Emergency shutdown sequence
        bInjectionActive := FALSE;
        fCO2_Pump_Speed := 0.0;
        fCO2_Heater_Output := 0.0;
        fCoInjection_Valve := 0.0;
        bSupercritical := FALSE;
        bAlarm := TRUE;

        ePackML := eSTATE_ABORTED;

    eSTATE_ABORTED:
        IF NOT bAbort AND bEnable THEN
            bAlarm := FALSE;
            ePackML := eSTATE_STOPPED;
        END_IF

END_CASE

END_FUNCTION_BLOCK
