FUNCTION_BLOCK FB_FischerTropsch_SlurryColumn
VAR_INPUT
    bEnableSys                  : BOOL;     (* Main system enable command *)
    bEmergencyStopSafetyRelay   : BOOL;     (* Hardware safety interlock (TRUE = Safe) *)
    rSyngasInletFlow_kg_h       : REAL;     (* H2/CO Syngas mass flow into sparger [kg/h] *)
    rH2toCO_StoichRatio         : REAL;     (* Measured H2:CO stoichiometric ratio from GC *)
    rReactorTemp_C              : REAL;     (* Primary RTD temperature reading [°C] *)
    rReactorPressure_bar        : REAL;     (* Primary PT pressure reading [bar] *)
    rSlurryDensity_kg_m3        : REAL;     (* Coriolis meter reading for slurry density [kg/m³] *)
    rCoolingWaterFlowIn         : REAL;     (* Tube-side cooling water flow [m³/h] *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* System is stable and ready for continuous operation *)
    rSyngasFlowValveCmd         : REAL;     (* 4-20mA command to inlet syngas control valve (0-100%) *)
    rCoolingWaterValveCmd       : REAL;     (* 4-20mA command to cooling water valve (0-100%) *)
    rProductDecantValveCmd      : REAL;     (* Wax product take-off valve command (0-100%) *)
    bSafetyTrip                 : BOOL;     (* Emergency shutdown active (FALSE = Safe) *)
    bCatalystSettlingAlarm      : BOOL;     (* High-priority alarm indicating poor fluidization *)
    iOperatingState             : INT;      (* Current state machine step *)
END_VAR

VAR
    (* Internal State and Timers *)
    iState                      : INT := 0; (* 0=Init, 10=Purge, 20=HeatUp, 30=Reaction, 40=Decanting, 99=Fault *)
    tPurgeTimer                 : TON;
    tSettleTimer                : TON;
    tSafetyTimer                : TON;

    (* Filtered process variables *)
    rFiltTemp                   : REAL := 25.0;
    rFiltPress                  : REAL := 1.0;

    (* PID Controllers parameters *)
    rTempSetpoint               : REAL := 240.0; (* Optimal FT synthesis temperature *)
    rTempKp                     : REAL := 2.5;
    rTempKi                     : REAL := 0.05;
    rTempIntegral               : REAL := 0.0;
    rTempError                  : REAL := 0.0;

    (* Constants *)
    rMaxTempLimit               : REAL := 280.0; (* Exothermic runaway threshold *)
    rMinDensityLimit            : REAL := 650.0; (* Indicates potential wax overflow or light products *)
    rMaxDensityLimit            : REAL := 950.0; (* Indicates severe catalyst sedimentation *)
    rIdealStoichRatio           : REAL := 2.05;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStopSafetyRelay THEN
    bSafetyTrip := TRUE;
    bSystemReady := FALSE;
    rSyngasFlowValveCmd := 0.0;
    rCoolingWaterValveCmd := 100.0; (* Fail open to provide max cooling *)
    rProductDecantValveCmd := 0.0;
    iOperatingState := 99;
    RETURN;
END_IF;

(* === SENSOR NOISE FILTERING (EWMA) === *)
rFiltTemp := (0.9 * rFiltTemp) + (0.1 * rReactorTemp_C);
rFiltPress := (0.9 * rFiltPress) + (0.1 * rReactorPressure_bar);

(* === RUNAWAY PROTECTION === *)
IF rFiltTemp > rMaxTempLimit OR rFiltPress > 45.0 THEN
    bSafetyTrip := TRUE;
    iState := 99;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* INIT / OFF *)
        bSystemReady := FALSE;
        rSyngasFlowValveCmd := 0.0;
        rCoolingWaterValveCmd := 100.0;
        rProductDecantValveCmd := 0.0;
        bSafetyTrip := FALSE;
        bCatalystSettlingAlarm := FALSE;

        IF bEnableSys AND bEmergencyStopSafetyRelay THEN
            iState := 10;
        END_IF;

    10: (* PURGE / FLUIDIZATION START *)
        (* Establish initial flow to fluidize catalyst bed before reaction *)
        rSyngasFlowValveCmd := 15.0; (* Minimum fluidization velocity *)
        tPurgeTimer(IN := TRUE, PT := T#30M);

        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* HEAT UP TO REACTION TEMP *)
        (* Gradually bring temperature to synthesis range while avoiding thermal shock *)
        IF rFiltTemp < rTempSetpoint - 10.0 THEN
            rCoolingWaterValveCmd := 10.0; (* Minimal cooling *)
            rSyngasFlowValveCmd := 30.0;   (* Increased flow *)
        ELSE
            iState := 30;
        END_IF;

    30: (* STEADY STATE REACTION *)
        bSystemReady := TRUE;

        (* Cascade PI Control for Reactor Temperature via Cooling Water *)
        rTempError := rFiltTemp - rTempSetpoint;
        rTempIntegral := rTempIntegral + (rTempError * 0.1);

        (* Anti-windup *)
        IF rTempIntegral > 50.0 THEN rTempIntegral := 50.0; END_IF;
        IF rTempIntegral < -50.0 THEN rTempIntegral := -50.0; END_IF;

        rCoolingWaterValveCmd := (rTempError * rTempKp) + (rTempIntegral * rTempKi) + 50.0;

        (* Clamp Output *)
        IF rCoolingWaterValveCmd > 100.0 THEN rCoolingWaterValveCmd := 100.0; END_IF;
        IF rCoolingWaterValveCmd < 0.0 THEN rCoolingWaterValveCmd := 0.0; END_IF;

        (* Syngas Stoichiometry adjustments *)
        IF rH2toCO_StoichRatio < 1.9 THEN
            rSyngasFlowValveCmd := 50.0; (* Adjust flow to modify residence time and conversion *)
        ELSE
            rSyngasFlowValveCmd := 65.0;
        END_IF;

        (* Catalyst Fluidization Monitoring *)
        IF rSlurryDensity_kg_m3 > rMaxDensityLimit THEN
            tSettleTimer(IN := TRUE, PT := T#10S);
        ELSE
            tSettleTimer(IN := FALSE);
        END_IF;

        IF tSettleTimer.Q THEN
            bCatalystSettlingAlarm := TRUE;
            rSyngasFlowValveCmd := 80.0; (* Bump flow to re-suspend catalyst *)
        END_IF;

        (* Move to continuous decanting if wax accumulation is indicated *)
        IF rSlurryDensity_kg_m3 < rMinDensityLimit THEN
            iState := 40;
        END_IF;

    40: (* WAX DECANTING / HYDRODYNAMICS *)
        (* Continuous removal of heavy Fischer-Tropsch wax products *)
        rProductDecantValveCmd := 40.0; (* Modulate take-off valve *)

        IF rSlurryDensity_kg_m3 > rMinDensityLimit + 50.0 THEN
            rProductDecantValveCmd := 0.0;
            iState := 30; (* Return to steady state *)
        END_IF;

    99: (* FAULT / TRIP *)
        bSystemReady := FALSE;
        rSyngasFlowValveCmd := 0.0;
        rCoolingWaterValveCmd := 100.0; (* Max Cooling *)
        rProductDecantValveCmd := 0.0;

        IF NOT bSafetyTrip AND bEnableSys = FALSE THEN
            iState := 0;
        END_IF;

END_CASE;

iOperatingState := iState;

END_FUNCTION_BLOCK
