FUNCTION_BLOCK FB_TidalTurbineController
VAR_INPUT
    rTideVelocity        : REAL;  (* Current tide velocity m/s *)
    rTideDirection       : REAL;  (* Current tide direction in degrees 0-360 *)
    rNacelleYawAngle     : REAL;  (* Current nacelle yaw angle 0-360 *)
    rRotorSpeed          : REAL;  (* Rotor speed in RPM *)
    rGridPower           : REAL;  (* Delivered grid power in kW *)
    rGenTemp1            : REAL;  (* Generator stator temp sensor 1 (C) *)
    rGenTemp2            : REAL;  (* Generator stator temp sensor 2 (C) *)
    bGridConnected       : BOOL;  (* Grid connection status *)
    bEStop               : BOOL;  (* Emergency stop activated *)
END_VAR
VAR_OUTPUT
    rYawCommand          : REAL;  (* Commanded yaw angle *)
    bYawMotorEnable      : BOOL;  (* Enable yaw drive *)
    rBladePitchCommand   : REAL;  (* Commanded blade pitch angle (deg) *)
    bGeneratorBrake      : BOOL;  (* Engage mechanical brake *)
    bSubseaCoolingPump   : BOOL;  (* Enable cooling pump *)
    wAlarmWord           : WORD;  (* System alarms *)
    bTurbineReady        : BOOL;  (* Ready to operate *)
END_VAR
VAR
    eState               : INT := 0; (* 0=STOP, 1=YAW_ALIGN, 2=STARTUP, 3=GENERATE, 4=FAULT *)
    rYawError            : REAL;
    rTargetPitch         : REAL;
    rMaxTemp             : REAL;
    tCoolingTimer        : TIME;
    rRatedPower          : REAL := 1500.0; (* 1.5MW *)
    rRatedSpeed          : REAL := 22.5; 
END_VAR
VAR CONSTANT
    YAW_DEADBAND         : REAL := 2.5;
    PITCH_MAX            : REAL := 90.0;
    PITCH_MIN            : REAL := 0.0;
    TEMP_ALARM_LIMIT     : REAL := 95.0;
    TEMP_TRIP_LIMIT      : REAL := 115.0;
    CUT_IN_SPEED         : REAL := 1.2;
    CUT_OUT_SPEED        : REAL := 3.5;
END_VAR

(* Fault Detection *)
rMaxTemp := MAX(rGenTemp1, rGenTemp2);
IF bEStop OR (rMaxTemp > TEMP_TRIP_LIMIT) THEN
    eState := 4; 
    wAlarmWord.0 := bEStop;
    wAlarmWord.1 := (rMaxTemp > TEMP_TRIP_LIMIT);
END_IF;

(* Thermal Tracking and Cooling Control *)
IF rMaxTemp > 85.0 THEN
    bSubseaCoolingPump := TRUE;
ELSIF rMaxTemp < 70.0 THEN
    bSubseaCoolingPump := FALSE;
END_IF;

(* State Machine *)
CASE eState OF
    0: (* STOP / IDLE *)
        bGeneratorBrake := TRUE;
        rTargetPitch := PITCH_MAX; (* Feather blades *)
        bYawMotorEnable := FALSE;
        bTurbineReady := FALSE;

        IF NOT bEStop AND NOT (rMaxTemp > TEMP_TRIP_LIMIT) AND (rTideVelocity >= CUT_IN_SPEED) AND (rTideVelocity <= CUT_OUT_SPEED) THEN
            eState := 1;
        END_IF;

    1: (* YAW_ALIGN *)
        bGeneratorBrake := TRUE;
        rTargetPitch := PITCH_MAX;
        rYawError := rTideDirection - rNacelleYawAngle;

        (* Normalize error to -180 to +180 *)
        IF rYawError > 180.0 THEN rYawError := rYawError - 360.0; END_IF;
        IF rYawError < -180.0 THEN rYawError := rYawError + 360.0; END_IF;

        IF ABS(rYawError) > YAW_DEADBAND THEN
            bYawMotorEnable := TRUE;
            rYawCommand := rTideDirection;
        ELSE
            bYawMotorEnable := FALSE;
            eState := 2;
        END_IF;

    2: (* STARTUP *)
        bGeneratorBrake := FALSE;
        bYawMotorEnable := FALSE;

        (* Ramp pitch to operating position *)
        rTargetPitch := rTargetPitch - 0.5;
        IF rTargetPitch <= PITCH_MIN THEN
            rTargetPitch := PITCH_MIN;
        END_IF;

        IF rRotorSpeed > (rRatedSpeed * 0.8) THEN
            eState := 3;
            bTurbineReady := TRUE;
        END_IF;

    3: (* GENERATE *)
        IF rTideVelocity > CUT_OUT_SPEED OR rTideVelocity < CUT_IN_SPEED THEN
            eState := 0;
        END_IF;

        (* Active Blade Pitch Stall Regulation *)
        IF rRotorSpeed > rRatedSpeed OR rGridPower > rRatedPower THEN
            rTargetPitch := rTargetPitch + 0.1; (* Stall regulation towards feather *)
        ELSIF rRotorSpeed < rRatedSpeed AND rTargetPitch > PITCH_MIN THEN
            rTargetPitch := rTargetPitch - 0.1;
        END_IF;

        (* Check yaw alignment periodically *)
        rYawError := rTideDirection - rNacelleYawAngle;
        IF rYawError > 180.0 THEN rYawError := rYawError - 360.0; END_IF;
        IF rYawError < -180.0 THEN rYawError := rYawError + 360.0; END_IF;
        IF ABS(rYawError) > (YAW_DEADBAND * 2.0) THEN
            bYawMotorEnable := TRUE;
            rYawCommand := rTideDirection;
        ELSE
            bYawMotorEnable := FALSE;
        END_IF;

    4: (* FAULT *)
        bGeneratorBrake := TRUE;
        rTargetPitch := PITCH_MAX;
        bYawMotorEnable := FALSE;
        bTurbineReady := FALSE;

        (* Wait for manual reset - logic not fully shown *)
        IF NOT bEStop AND (rMaxTemp < TEMP_ALARM_LIMIT) THEN
            wAlarmWord := 0;
            eState := 0;
        END_IF;
END_CASE;

rBladePitchCommand := rTargetPitch;
END_FUNCTION_BLOCK
