        #DustVal := (#DustLevel_A + #DustLevel_B) / 2.0;
    END_IF;

    // Automated Startup Self-Test Routine
    IF #SelfTestCmd AND NOT #SelfTestActive AND (#SystemState = 0) THEN
        #SelfTestActive := TRUE;
        #TestStep := 1;
    END_IF;

    IF #SelfTestActive THEN
        #SystemState := 3;
        #TestTimer(IN:=TRUE, PT:=T#2S);
        IF #TestTimer.Q THEN
            #TestTimer(IN:=FALSE, PT:=T#2S); // Reset
            #TestStep := #TestStep + 1;
        END_IF;

        CASE #TestStep OF
            1: #MistValve:=TRUE; #AerationFan:=FALSE; #AugerFwd:=FALSE; #AugerRev:=FALSE;
            2: #MistValve:=FALSE; #AerationFan:=TRUE; #AugerFwd:=FALSE; #AugerRev:=FALSE;
            3: #MistValve:=FALSE; #AerationFan:=FALSE; #AugerFwd:=TRUE; #AugerRev:=FALSE;
            4: #MistValve:=FALSE; #AerationFan:=FALSE; #AugerFwd:=FALSE; #AugerRev:=TRUE;
            ELSE 
                #SelfTestActive := FALSE; #MistValve:=FALSE; #AerationFan:=FALSE; #AugerFwd:=FALSE; #AugerRev:=FALSE;
        END_CASE;
        RETURN;
    END_IF;

    // SCADA & Cyber RBAC
    #ScadaTimer(IN := NOT #ScadaHeartbeat, PT := T#5S);
    #ScadaCommLoss := #ScadaTimer.Q;
    IF #ScadaCommLoss THEN #DiagErrorWord := #DiagErrorWord OR 16#0008; END_IF;

    #ManualModeActive := #ManualOverrideCmd AND (#UserRoleLevel >= 2);
    IF #ManualOverrideCmd AND (#UserRoleLevel < 2) THEN #DiagErrorWord := #DiagErrorWord OR 16#0020; END_IF;

    // Temperature Monitoring
    #MaxTemp := 0.0;
    FOR #i := 1 TO 4 DO
        IF #ZoneTemps[#i] > #MaxTemp THEN #MaxTemp := #ZoneTemps[#i]; END_IF;
    END_FOR;
    #AlarmFireHazard := (#MaxTemp > 65.0);
    IF #AlarmFireHazard THEN #DiagErrorWord := #DiagErrorWord OR 16#0002; END_IF;

    // Mode Logic
    IF #ManualModeActive THEN
        #SystemState := 2;
        #AugerFwd := #ManualFwdCmd AND NOT #AlarmFireHazard;
        #AugerRev := #ManualRevCmd AND NOT #AlarmFireHazard;
        #MistValve := FALSE; #AerationFan := FALSE;
    ELSE
        #SystemState := 1;
        IF NOT #SystemEnable THEN #SystemState := 0; END_IF;

        #AerationFan := #SystemEnable AND (#MaxTemp > 40.0) AND NOT #AlarmFireHazard;
        #MistValve := #SystemEnable AND (#DustVal > 50.0) AND NOT #AlarmFireHazard;

        #JamTimer(IN := #SystemEnable AND (#AugerTorque > 150.0) AND NOT #AntiJamActive, PT := T#2S);
        IF #JamTimer.Q THEN #AntiJamActive := TRUE; END_IF;

        #RevTimer(IN := #AntiJamActive, PT := T#3S);
        IF #RevTimer.Q THEN
            #AntiJamActive := FALSE;
            IF #AugerTorque > 150.0 THEN #AlarmJam := TRUE; END_IF;
        END_IF;

        IF #AlarmJam THEN #DiagErrorWord := #DiagErrorWord OR 16#0004; END_IF;

        IF #SystemEnable AND NOT #AlarmJam AND NOT #AlarmFireHazard AND NOT #ScadaCommLoss THEN
            #AugerFwd := NOT #AntiJamActive;
            #AugerRev := #AntiJamActive;
        ELSE
            #AugerFwd := FALSE; #AugerRev := FALSE;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
