FUNCTION_BLOCK FB_CigaretteMakerCoordination
TITLE = 'High-Speed Cigarette Maker Control'
// Description: Orchestrates tobacco rod vacuum, splice tracking, and optical loose-end
// rejection at speeds up to 10,000 to 20,000 cigarettes per minute (CPM).
// Domain: Cigarette Making and Filter Assembling Machine
// This FB guarantees deterministic behavior within a hard real-time cycle (e.g., 1ms).

VAR_INPUT
    xEnable                 : BOOL; // Master machine enable
    rMachineSpeedCPM        : REAL; // Current machine speed in Cigarettes Per Minute (CPM)
    rVacuumActual_mbar      : REAL; // Measured vacuum on the suction band (mbar)
    xTippingSpliceTrigger   : BOOL; // Rising edge trigger when a bobbin splice occurs
    xOpticalSensorLooseEnd  : BOOL; // TRUE when optical sensor detects loose end on current rod
    xEncoderPulse           : BOOL; // Machine phase encoder pulse (1 pulse per cigarette phase)
    rTargetWeightMg         : REAL; // Target tobacco weight setpoint in milligrams
END_VAR

VAR_OUTPUT
    rVacuumSetpoint_mbar    : REAL; // Commanded vacuum setpoint to the proportional servo valve
    xRejectActuator         : BOOL; // High speed pneumatic air valve to reject defective cigarette
    xSplicerActive          : BOOL; // Indication that splicing sequence is currently active
    wTotalProduced          : DINT; // Total cigarettes produced counter
    wTotalRejected          : DINT; // Total rejected cigarettes counter
    wSpliceRejects          : DINT; // Total splice rejected counter
    xAlarmVacuumDev         : BOOL; // Alarm flag for vacuum deviation outside tolerance
END_VAR

VAR
    // Shift Registers for tracking defects from sensor to reject station
    // Distance from loose-end sensor to reject drum is precisely 15 cigarettes
    arrLooseEndTracking     : ARRAY[0..31] OF BOOL;
    // Distance from tipping paper splice sensor to reject drum is 120 cigarettes
    arrSpliceTracking       : ARRAY[0..127] OF BOOL;

    // Edge detection instances
    fbEncoderEdge           : R_TRIG;
    fbSpliceEdge            : R_TRIG;

    // Internal State
    i                       : INT;
    iSpliceRejectWindow     : INT := 0; // Number of cigarettes to reject around a splice joint
    rSpeedFactor            : REAL;
    rBaseVacuum             : REAL := -120.0; // Base mbar required at low speeds
    rVacuumGain             : REAL := 0.5;    // Dynamic gain based on speed scaling
END_VAR

// --- LOGIC IMPLEMENTATION ---
fbEncoderEdge(CLK := xEncoderPulse);
fbSpliceEdge(CLK := xTippingSpliceTrigger);

// 1. Vacuum Profiling based on Machine Speed
// The suction band holds the loose tobacco rod. At higher speeds, stronger vacuum is required
// to maintain the rod density and prevent scattering before paper wrapping.
IF xEnable THEN
    rSpeedFactor := rMachineSpeedCPM / 10000.0; // Normalized around 10k CPM
    rVacuumSetpoint_mbar := rBaseVacuum * (1.0 + (rSpeedFactor * rVacuumGain));

    // Basic vacuum deviation check (Deadband of 20 mbar)
    IF ABS(rVacuumActual_mbar - rVacuumSetpoint_mbar) > 20.0 THEN
        xAlarmVacuumDev := TRUE;
    ELSE
        xAlarmVacuumDev := FALSE;
    END_IF;
ELSE
    rVacuumSetpoint_mbar := 0.0;
    xAlarmVacuumDev := FALSE;
END_IF;

// 2. Tipping Paper Splice Tracking
// When a splice occurs in the tipping paper bobbin, we must reject the cigarettes
// that contain the glued splice joint. We reject 5 cigarettes total.
IF fbSpliceEdge.Q THEN
    iSpliceRejectWindow := 5;
    xSplicerActive := TRUE;
END_IF;

// 3. Shift Registers and Reject Coordination (Triggered deterministically per machine cycle)
xRejectActuator := FALSE; // Default state

IF fbEncoderEdge.Q THEN
    wTotalProduced := wTotalProduced + 1;

    // Shift arrays right (FIFO) to track cigarette progress across drums
    FOR i := 31 TO 1 BY -1 DO
        arrLooseEndTracking[i] := arrLooseEndTracking[i-1];
    END_FOR;

    FOR i := 127 TO 1 BY -1 DO
        arrSpliceTracking[i] := arrSpliceTracking[i-1];
    END_FOR;

    // Insert new defects at index 0 (sensor positions)
    arrLooseEndTracking[0] := xOpticalSensorLooseEnd;

    // Handle active splice window
    IF iSpliceRejectWindow > 0 THEN
        arrSpliceTracking[0] := TRUE;
        iSpliceRejectWindow := iSpliceRejectWindow - 1;
    ELSE
        arrSpliceTracking[0] := FALSE;
        IF iSpliceRejectWindow = 0 THEN
            xSplicerActive := FALSE; // Splicing window complete
        END_IF;
    END_IF;

    // Evaluate Reject Station conditions
    // Actuate reject if loose end defect reaches index 15 OR splice defect reaches index 120
    IF arrLooseEndTracking[15] THEN
        xRejectActuator := TRUE;
        wTotalRejected := wTotalRejected + 1;
        arrLooseEndTracking[15] := FALSE; // Clear defect after rejection
    END_IF;

    IF arrSpliceTracking[120] THEN
        xRejectActuator := TRUE;
        wTotalRejected := wTotalRejected + 1;
        wSpliceRejects := wSpliceRejects + 1;
        arrSpliceTracking[120] := FALSE; // Clear defect after rejection
    END_IF;
END_IF;
END_FUNCTION_BLOCK
```

