FUNCTION_BLOCK FB_MOVPE_Reactor_Control
VAR_INPUT
    (* Essential Safety and System Enable *)
    bSystemEnable           : BOOL;     (* Global permissive for MOVPE reactor operation *)
    bEmergencyStopOk        : BOOL;     (* Master E-stop chain status (TRUE = OK) *)
    bToxicGasAbatementOk    : BOOL;     (* Toxic gas scrubber/abatement system healthy *)

    (* Pyrometry & Reflectometry (In-Situ Monitoring) *)
    rSusceptorTemp_W1       : REAL;     (* Dual-wavelength pyrometer reading 1 (e.g. 950nm) [deg C] *)
    rSusceptorTemp_W2       : REAL;     (* Dual-wavelength pyrometer reading 2 (e.g. 850nm) [deg C] *)
    rUVReflectometrySignal  : REAL;     (* In-situ UV reflectometry for growth rate mapping [a.u.] *)

    (* Mass Flow Controllers (MFC) PVs *)
    rTMGa_Flow_PV           : REAL;     (* Tri-methyl gallium mass flow actual [sccm] *)
    rNH3_Flow_PV            : REAL;     (* Ammonia mass flow actual [slm] *)
    rH2_Carrier_Flow_PV     : REAL;     (* Hydrogen carrier gas flow actual [slm] *)

    (* Reactor Pressure & Vacuum *)
    rChamberPressure_PV     : REAL;     (* Reactor chamber pressure actual [Torr] *)
END_VAR

VAR_OUTPUT
    (* Status and Safety Outputs *)
    bReactorReady           : BOOL;     (* Reactor ready for recipe execution *)
    bCriticalAlarm          : BOOL;     (* Critical fault requiring immediate safe shutdown *)
    bGrowthInProgress       : BOOL;     (* Epitaxial growth actively occurring *)

    (* Actuator Control Signals *)
    rTMGa_Flow_SP           : REAL;     (* Tri-methyl gallium flow setpoint [sccm] *)
    rNH3_Flow_SP            : REAL;     (* Ammonia flow setpoint [slm] *)
    rHeaterPower_SP         : REAL;     (* RF/Resistive heater power setpoint [%] *)
    rThrottleValve_SP       : REAL;     (* Chamber pressure control throttle valve [% open] *)
END_VAR

VAR
    (* Internal States and Registers *)
    iSeqState               : INT := 0;             (* Main sequencer state machine *)
    rFilteredTemp           : REAL := 0.0;          (* Kalman-filtered susceptor temperature *)
    rTempError              : REAL := 0.0;          (* Temperature control error *)
    rTempIntegral           : REAL := 0.0;          (* Temperature PID integral accumulator *)
    rVIn_ReflectometryHist  : ARRAY[0..99] OF REAL; (* Reflectometry history buffer for derivative *)
    iReflectIdx             : INT := 0;             (* Ring buffer index *)

    (* Constants for V/III Ratio & Tuning *)
    c_rTargetVIII_Ratio     : REAL := 2500.0;       (* Target V/III molar ratio (NH3 / TMGa) *)
    c_rTempKp               : REAL := 2.5;          (* Proportional gain for heater *)
    c_rTempKi               : REAL := 0.05;         (* Integral gain for heater *)

    (* Timers and Triggers *)
    tPurgeTimer             : TON;
    tGrowthTimer            : TON;
    tFaultDelay             : TON;

    bInitDone               : BOOL := FALSE;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Master Safety Interlocks *)
IF NOT bEmergencyStopOk OR NOT bToxicGasAbatementOk THEN
    (* Execute Immediate Safe Shutdown Sequence (ISSS) *)
    bCriticalAlarm      := TRUE;
    bReactorReady       := FALSE;
    bGrowthInProgress   := FALSE;

    (* Isolate toxic organics and hydrides, max carrier flow to purge *)
    rTMGa_Flow_SP       := 0.0;
    rNH3_Flow_SP        := 0.0;

    (* Kill heater power *)
    rHeaterPower_SP     := 0.0;

    (* Open throttle valve to base pressure *)
    rThrottleValve_SP   := 100.0;

    iSeqState           := 999; (* Fault state *)
    RETURN;
END_IF;

(* Clear critical alarm if safe (latching handled externally in this block model) *)
bCriticalAlarm := FALSE;

(* 2. Signal Processing: Dual-Wavelength Pyrometry Consensus & Noise Filtering *)
(* Simple robust averaging of dual pyrometer to discard outlier if delta > 15 deg *)
IF ABS(rSusceptorTemp_W1 - rSusceptorTemp_W2) > 15.0 THEN
    (* Fallback to historically more stable long-wavelength *)
    rFilteredTemp := (rFilteredTemp * 0.9) + (rSusceptorTemp_W1 * 0.1); 
ELSE
    rFilteredTemp := (rFilteredTemp * 0.9) + (((rSusceptorTemp_W1 + rSusceptorTemp_W2) / 2.0) * 0.1);
END_IF;

(* 3. In-situ Reflectometry Buffer (Growth rate estimation analog) *)
rVIn_ReflectometryHist[iReflectIdx] := rUVReflectometrySignal;
iReflectIdx := (iReflectIdx + 1) MOD 100;

(* 4. Main Sequence State Machine *)
CASE iSeqState OF
    0: (* IDLE & STANDBY *)
        bReactorReady := TRUE;
        bGrowthInProgress := FALSE;
        rHeaterPower_SP := 0.0;
        rTMGa_Flow_SP := 0.0;
        rNH3_Flow_SP := 0.0;

        IF bSystemEnable THEN
            bReactorReady := FALSE;
            iSeqState := 10;
        END_IF;

    10: (* PURGE & PRESSURE STABILIZATION *)
        rThrottleValve_SP := 45.0; (* Pre-position *)
        tPurgeTimer(IN := TRUE, PT := T#60S);

        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iSeqState := 20;
        END_IF;

    20: (* RAMP TEMPERATURE (PID Control) *)
        rTempError := 1050.0 - rFilteredTemp; (* Target 1050 C for GaN buffer layer *)
        rTempIntegral := rTempIntegral + (rTempError * 0.1); (* 100ms cycle assumed *)

        (* Anti-windup clamping *)
        IF rTempIntegral > 100.0 THEN rTempIntegral := 100.0; END_IF;
        IF rTempIntegral < 0.0 THEN rTempIntegral := 0.0; END_IF;

        rHeaterPower_SP := (rTempError * c_rTempKp) + (rTempIntegral * c_rTempKi);

        IF rHeaterPower_SP > 100.0 THEN rHeaterPower_SP := 100.0; END_IF;
        IF rHeaterPower_SP < 0.0 THEN rHeaterPower_SP := 0.0; END_IF;

        (* Check if temperature is stabilized within deadband *)
        IF ABS(rTempError) < 2.0 THEN
            iSeqState := 30;
        END_IF;

    30: (* EPITAXIAL GROWTH *)
        bGrowthInProgress := TRUE;

        (* Stoichiometric Flow Control based on V/III ratio target *)
        rTMGa_Flow_SP := 15.0; (* 15 sccm base flow *)
        rNH3_Flow_SP := (rTMGa_Flow_SP * c_rTargetVIII_Ratio) / 1000.0; (* Conversion factor *)

        tGrowthTimer(IN := TRUE, PT := T#3600S); (* 1 hour growth cycle *)

        IF tGrowthTimer.Q OR NOT bSystemEnable THEN
            tGrowthTimer(IN := FALSE);
            bGrowthInProgress := FALSE;
            iSeqState := 40;
        END_IF;

    40: (* COOLDOWN & POST-PURGE *)
        rTMGa_Flow_SP := 0.0;
        rNH3_Flow_SP := 0.0;
        rHeaterPower_SP := 0.0;

        IF rFilteredTemp < 200.0 THEN
            iSeqState := 0;
        END_IF;

    999: (* FAULT RECOVERY LOCKOUT *)
        (* Require manual system disable to clear fault state *)
        IF NOT bSystemEnable AND bEmergencyStopOk AND bToxicGasAbatementOk THEN
            iSeqState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
