FUNCTION_BLOCK FB_Electroplating_Line_Control
TITLE = 'Advanced Electroplating Line Controller with OHT Anti-Sway, Rectifier Ramping, and Rinse Cascading'
VERSION : '2.1'

VAR_INPUT
    // OHT Transporter Inputs
    bOHT_Enable : BOOL; // Enable overhead hoist transporter
    rOHT_TargetPos : REAL; // Target position in meters
    rOHT_CurrentPos : REAL; // Current position in meters
    rOHT_LoadMass : REAL; // Mass of the load (kg)
    rOHT_CableLength : REAL; // Length of hoisting cable (m)
    rOHT_Velocity : REAL; // Current velocity (m/s)

    // Rectifier Inputs
    bRectifier_Enable : BOOL;
    rTargetCurrentDensity : REAL; // A/dm^2
    rSurfaceArea : REAL; // dm^2
    rRampRate : REAL; // A/s

    // Rinse Cascading Inputs
    bRinse_Enable : BOOL;
    rConductivity_Tank1 : REAL; // uS/cm (Dirty)
    rConductivity_Tank2 : REAL; // uS/cm (Intermediate)
    rConductivity_Tank3 : REAL; // uS/cm (Clean)

    // General
    bEmergencyStop : BOOL;
    bReset : BOOL;
END_VAR

VAR_OUTPUT
    // OHT Outputs
    rOHT_DriveCommand : REAL; // Output velocity command (m/s) with sway compensation
    bOHT_InPosition : BOOL;

    // Rectifier Outputs
    rRectifier_OutputCurrent : REAL; // Calculated Output Current (A)
    bRectifier_Ready : BOOL;

    // Rinse Outputs
    bValve_FreshWater : BOOL; // Open fresh water into Tank 3
    bValve_Transfer3to2 : BOOL; // Transfer Tank 3 to Tank 2
    bValve_Transfer2to1 : BOOL; // Transfer Tank 2 to Tank 1
    bValve_DrainTank1 : BOOL; // Drain Tank 1 to waste treatment

    // Status
    bError : BOOL;
    nErrorCode : INT;
END_VAR

VAR
    // Anti-Sway Internal Variables
    rSwayFrequency : REAL;
    rDampingRatio : REAL := 0.15;
    rGravity : REAL := 9.81;
    rPositionError : REAL;
    rVelocityCommand_Raw : REAL;
    rAntiSway_Correction : REAL;

    // Rectifier Internal Variables
    rTargetCurrentTotal : REAL;
    tLastCycleTime : TIME;
    rtCurrentTimer : TON;
    rDeltaTime : REAL; // seconds

    // Rinse Internal Variables
    rLimit_Tank1 : REAL := 5000.0;
    rLimit_Tank2 : REAL := 1500.0;
    rLimit_Tank3 : REAL := 200.0;
END_VAR

// --- CONTROL LOGIC START ---

IF bEmergencyStop THEN
    rOHT_DriveCommand := 0.0;
    rRectifier_OutputCurrent := 0.0;
    bValve_FreshWater := FALSE;
    bValve_Transfer3to2 := FALSE;
    bValve_Transfer2to1 := FALSE;
    bValve_DrainTank1 := FALSE;
    bError := TRUE;
    nErrorCode := 999;
    RETURN;
END_IF;

IF bReset THEN
    bError := FALSE;
    nErrorCode := 0;
END_IF;

// 1. OHT Anti-Sway Position Control
IF bOHT_Enable THEN
    rPositionError := rOHT_TargetPos - rOHT_CurrentPos;

    // Natural frequency of pendulum (w = sqrt(g/L))
    IF rOHT_CableLength > 0.05 THEN
        rSwayFrequency := SQRT(rGravity / rOHT_CableLength);
    ELSE
        rSwayFrequency := 14.0; // Default high frequency for short cable
    END_IF;

    // Proportional position control
    rVelocityCommand_Raw := rPositionError * 0.5;

    // Limit max velocity
    IF rVelocityCommand_Raw > 2.0 THEN rVelocityCommand_Raw := 2.0; END_IF;
    IF rVelocityCommand_Raw < -2.0 THEN rVelocityCommand_Raw := -2.0; END_IF;

    // Simplified anti-sway correction based on state feedback
    rAntiSway_Correction := (rOHT_Velocity - rVelocityCommand_Raw) * rDampingRatio * rSwayFrequency;

    rOHT_DriveCommand := rVelocityCommand_Raw - rAntiSway_Correction;

    IF ABS(rPositionError) < 0.02 THEN
        bOHT_InPosition := TRUE;
        rOHT_DriveCommand := 0.0;
    ELSE
        bOHT_InPosition := FALSE;
    END_IF;
ELSE
    rOHT_DriveCommand := 0.0;
    bOHT_InPosition := FALSE;
END_IF;

// 2. DC Rectifier Current Density Ramping
IF bRectifier_Enable AND NOT bError THEN
    rTargetCurrentTotal := rTargetCurrentDensity * rSurfaceArea;

    // Assume 100ms task cycle for simplicity of delta time
    rDeltaTime := 0.1; 

    IF rRectifier_OutputCurrent < (rTargetCurrentTotal - 0.5) THEN
        rRectifier_OutputCurrent := rRectifier_OutputCurrent + (rRampRate * rDeltaTime);
        bRectifier_Ready := FALSE;
    ELSIF rRectifier_OutputCurrent > (rTargetCurrentTotal + 0.5) THEN
        rRectifier_OutputCurrent := rRectifier_OutputCurrent - (rRampRate * rDeltaTime);
        bRectifier_Ready := FALSE;
    ELSE
        rRectifier_OutputCurrent := rTargetCurrentTotal;
        bRectifier_Ready := TRUE;
    END_IF;
ELSE
    rRectifier_OutputCurrent := 0.0;
    bRectifier_Ready := FALSE;
END_IF;

// 3. Rinse Water Conductivity Cascading Control
IF bRinse_Enable AND NOT bError THEN
    // If the cleanest tank is getting dirty, turn on fresh water
    IF rConductivity_Tank3 > rLimit_Tank3 THEN
        bValve_FreshWater := TRUE;
        bValve_Transfer3to2 := TRUE;
    ELSE
        bValve_FreshWater := FALSE;
        bValve_Transfer3to2 := FALSE;
    END_IF;

    // Cascade to Tank 2
    IF rConductivity_Tank2 > rLimit_Tank2 OR bValve_Transfer3to2 THEN
        bValve_Transfer2to1 := TRUE;
    ELSE
        bValve_Transfer2to1 := FALSE;
    END_IF;

    // Cascade to Tank 1 and drain
    IF rConductivity_Tank1 > rLimit_Tank1 OR bValve_Transfer2to1 THEN
        bValve_DrainTank1 := TRUE;
    ELSE
        bValve_DrainTank1 := FALSE;
    END_IF;
ELSE
    bValve_FreshWater := FALSE;
    bValve_Transfer3to2 := FALSE;
    bValve_Transfer2to1 := FALSE;
    bValve_DrainTank1 := FALSE;
END_IF;

END_FUNCTION_BLOCK
