Here is a basic Siemens SCL program for a Milk Pasteurizer covering the PID loop for the heat exchanger, the holding tube timer, and the flow-divert valve (FDV) safety logic:

FUNCTION_BLOCK "MilkPasteurizer_Base"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempPasteurizer : REAL; // Actual temperature at holding tube inlet
    FlowRate : REAL;        // Actual flow rate
    SP_Temp : REAL := 72.0; // Setpoint for pasteurization
    HoldingTime : TIME := T#15S; // Legal holding time
END_VAR

VAR_OUTPUT
    HeaterValveControl : REAL; // PID output 0.0 - 100.0%
    PumpRun : BOOL;            // Main pump control
    FDV_Forward : BOOL;        // Flow divert valve to forward flow
    FDV_Divert : BOOL;         // Flow divert valve to divert (reject) flow
    Alarm : BOOL;              // General alarm
END_VAR

VAR
    ProcessActive : BOOL;
    PID_Inst : "PID_Compact";
    HoldingTimer : TON;
    TempOk : BOOL;
END_VAR

BEGIN
    // Process Start/Stop
    IF Start AND NOT Stop THEN
        ProcessActive := TRUE;
    ELSIF Stop THEN
        ProcessActive := FALSE;
    END_IF;

    // Main Pump Control
    PumpRun := ProcessActive;

    // PID Control for Heat Exchanger
    PID_Inst(
        sMode := 3, // Automatic mode
        Setpoint := SP_Temp,
        Input := TempPasteurizer,
        ManualEnable := FALSE,
        Output => HeaterValveControl
    );

    // Temperature Safety Check
    TempOk := (TempPasteurizer >= SP_Temp);

    // Holding Tube Timer
    HoldingTimer(
        IN := TempOk AND ProcessActive,
        PT := HoldingTime
    );

    // Flow Divert Valve Logic (Fail-Safe: Default Divert)
    IF ProcessActive AND HoldingTimer.Q THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;

    // Alarm Logic
    Alarm := ProcessActive AND NOT TempOk;
END_FUNCTION_BLOCK
