TYPE "UDT_Profinet_Data"
    STRUCT
        Status_Word : WORD;
        Control_Word : WORD;
        Current_State : INT;
        Active_Fault_Code : INT;
        Fault_Timestamp : DTL;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "RO_Control_Breadth"
TITLE = 'RO Control System with Profinet'
VERSION : 0.3

VAR_INPUT
    Feed_Pressure : REAL;
    Feed_Flow_Rate : REAL;
    Permeate_Conductivity : REAL;
    High_Pressure_Setpoint : REAL;
    Conductivity_Limit : REAL;
    Dosing_Ratio : REAL; 
    Tank_Level_High : BOOL;
END_VAR

VAR_IN_OUT
    PN_Data : "UDT_Profinet_Data"; // Profinet Communication Data Block
END_VAR

VAR_OUTPUT
    HP_Pump_Run : BOOL;
    HP_Pump_Speed : REAL;
    Dosing_Pump_Run : BOOL;
    Dosing_Pump_Speed : REAL;
    Inlet_Valve : BOOL;
    Flush_Valve : BOOL;
    System_Fault : BOOL;
END_VAR

VAR
    State : INT; 
    Flush_Timer : TON;
    PID_Inst : "PID_Compact";
    Conductivity_Alarm : BOOL;
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;
    Ack_Fault : BOOL;
    Fault_Triggered : R_TRIG;
END_VAR

BEGIN
    // Map Profinet Control Word
    Start_Cmd := PN_Data.Control_Word.%X0;
    Stop_Cmd := PN_Data.Control_Word.%X1;
    Ack_Fault := PN_Data.Control_Word.%X2;

    // Conductivity Monitoring
    Conductivity_Alarm := Permeate_Conductivity > Conductivity_Limit;

    // Fault Management
    IF Feed_Pressure < 1.5 THEN
        System_Fault := TRUE;
        PN_Data.Active_Fault_Code := 1;
    ELSIF Conductivity_Alarm THEN
        System_Fault := TRUE;
        PN_Data.Active_Fault_Code := 2;
    END_IF;

    // Timestamping Diagnostics
    Fault_Triggered(CLK := System_Fault);
    IF Fault_Triggered.Q THEN
        RD_SYS_T(OUT => PN_Data.Fault_Timestamp); // Get system time
    END_IF;

    IF Ack_Fault THEN
        System_Fault := FALSE;
        PN_Data.Active_Fault_Code := 0;
    END_IF;

    // Dosing Logic
    IF State = 2 THEN
        Dosing_Pump_Run := TRUE;
        Dosing_Pump_Speed := Feed_Flow_Rate * Dosing_Ratio;
    ELSE
        Dosing_Pump_Run := FALSE;
        Dosing_Pump_Speed := 0.0;
    END_IF;

    // State Machine
    IF System_Fault THEN
        State := 4;
    ELSIF Stop_Cmd OR Tank_Level_High THEN
        IF State = 2 THEN
            State := 3; 
        ELSE
            State := 0;
        END_IF;
    ELSIF Start_Cmd AND NOT System_Fault AND State = 0 THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Off
            HP_Pump_Run := FALSE;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
            Flush_Timer(IN:=FALSE, PT:=T#0S);
        1: // Startup
            Inlet_Valve := TRUE;
            HP_Pump_Run := TRUE;
            State := 2;
        2: // Running
            Inlet_Valve := TRUE;
            Flush_Valve := FALSE;
            HP_Pump_Run := TRUE;
            PID_Inst(Setpoint := High_Pressure_Setpoint,
                     Feedback := Feed_Pressure,
                     Output => HP_Pump_Speed);
        3: // Flushing
            Inlet_Valve := TRUE;
            Flush_Valve := TRUE;
            HP_Pump_Run := TRUE;
            HP_Pump_Speed := 50.0;
            Flush_Timer(IN:=TRUE, PT:=T#30S);
            IF Flush_Timer.Q THEN
                State := 0;
            END_IF;
        4: // Fault
            HP_Pump_Run := FALSE;
            HP_Pump_Speed := 0.0;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
    END_CASE;

    // Update Profinet Status
    PN_Data.Current_State := State;
    PN_Data.Status_Word.%X0 := HP_Pump_Run;
    PN_Data.Status_Word.%X1 := System_Fault;
    PN_Data.Status_Word.%X2 := Flush_Valve;
END_FUNCTION_BLOCK
