FUNCTION_BLOCK FB_Desalination_BrineMining
VAR_INPUT
    // PackML State Control
    bExecute : BOOL;
    bStop : BOOL;
    bAbort : BOOL;
    bReset : BOOL;

    // Process Variables - RO & ERD
    lrSeawaterFeedFlow_m3h : LREAL; 
    lrROFeedPressure_bar : LREAL;     // Target 1000 bar
    lrBrineRejectPressure_bar : LREAL; // Source for ERD

