    iPackMLState : INT := 3; // Stopped

    // ERD Control
    lrERDPhaseAngle_rad : LREAL;
    lrERDTargetSpeed_rpm : LREAL;
    lrERDPressureDelta : LREAL;

    // PID Controllers for VFD Cascade
    lrTargetCascadePressure : LREAL := 1000.0;
    lrPressureError : LREAL;
    lrPressureIntegral : LREAL;

