    iPackMLState := 1; // Aborted
ELSIF bStop THEN
    iPackMLState := 3; // Stopped
ELSIF iPackMLState = 3 AND bReset THEN
    iPackMLState := 5; // Idle
ELSIF iPackMLState = 5 AND bExecute THEN
    iPackMLState := 4; // Starting
ELSIF iPackMLState = 4 THEN
