    iPackMLState := 7; // Execute
END_IF;

iCurrentState := iPackMLState;

CASE iPackMLState OF
    1: // Aborted
        lrERDRotaryValveSpeed_rpm := 0.0;
        lrVFDBoosterPump1_Hz := 0.0;
        lrVFDBoosterPump2_Hz := 0.0;
        lrVFDBoosterPump3_Hz := 0.0;
        lrMDHeaterPower_kW := 0.0;
        lrEDVoltageLevel_V := 0.0;
        bValveColumnA_Feed := FALSE;
        bValveColumnB_Feed := FALSE;
        bValveColumnA_Elution := FALSE;
        bValveColumnB_Elution := FALSE;

    7: // Execute
        // 1. High-Pressure Energy Recovery Device (ERD) Rotary Valve Synchronization
        // Transfer 1000 bar hydraulic pressure directly from reject brine to incoming seawater
        lrERDPressureDelta := lrBrineRejectPressure_bar - lrROFeedPressure_bar;

        // Speed synchronization to match volumetric flow with >98% efficiency
        lrERDTargetSpeed_rpm := (lrSeawaterFeedFlow_m3h * 0.985) / 2.5; // Assuming 2.5m3 per revolution
        lrERDRotaryValveSpeed_rpm := lrERDTargetSpeed_rpm;

        IF ABS(lrERDPressureDelta) > 50.0 THEN
            bERDDeSyncAlarm := TRUE;
        ELSE
            bERDDeSyncAlarm := FALSE;
        END_IF;

        // 2. VFD Booster Pump Cascade (Eliminate Pressure Pulsation)
        // Maintain exact 1000 bar feed pressure 
        lrPressureError := lrTargetCascadePressure - lrROFeedPressure_bar;
        lrPressureIntegral := lrPressureIntegral + (lrPressureError * 0.1); // Simple PI integral

        // Anti-windup
        IF lrPressureIntegral > 150.0 THEN lrPressureIntegral := 150.0; END_IF;
        IF lrPressureIntegral < 0.0 THEN lrPressureIntegral := 0.0; END_IF;

        // Cascade distribution for zero pulsation (120-degree phase equivalent shift in flow delivery)
        lrVFDBoosterPump1_Hz := 40.0 + (lrPressureError * 0.5) + (lrPressureIntegral * 0.1);
        lrVFDBoosterPump2_Hz := lrVFDBoosterPump1_Hz * 0.95; // Staggered operating points
        lrVFDBoosterPump3_Hz := lrVFDBoosterPump1_Hz * 1.05;

        // Clamp VFD frequencies
        IF lrVFDBoosterPump1_Hz > 60.0 THEN lrVFDBoosterPump1_Hz := 60.0; END_IF;
        IF lrVFDBoosterPump2_Hz > 60.0 THEN lrVFDBoosterPump2_Hz := 60.0; END_IF;
        IF lrVFDBoosterPump3_Hz > 60.0 THEN lrVFDBoosterPump3_Hz := 60.0; END_IF;
        IF lrVFDBoosterPump1_Hz < 20.0 THEN lrVFDBoosterPump1_Hz := 20.0; END_IF;
        IF lrVFDBoosterPump2_Hz < 20.0 THEN lrVFDBoosterPump2_Hz := 20.0; END_IF;
        IF lrVFDBoosterPump3_Hz < 20.0 THEN lrVFDBoosterPump3_Hz := 20.0; END_IF;

        // Pulsation Detection Alarm
        bPressurePulsationAlarm := ABS(lrPressureError) > 15.0;

        // 3. Brine Mineral Concentration (Lithium/Uranium)
        // Membrane Distillation (MD) Heater Regulation
        IF lrMDTemperature_C < 85.0 THEN
            lrMDHeaterPower_kW := 500.0; // Max power to reach hypersalinity
        ELSE
            lrMDHeaterPower_kW := 150.0; // Sustain power
        END_IF;

        // Electrodialysis Flow Cell Regulation
        // Boost voltage based on target current density to separate Lithium ions
        lrEDVoltageLevel_V := lrEDCurrentDensity_Am2 * 1.25; 
        IF lrEDVoltageLevel_V > 400.0 THEN lrEDVoltageLevel_V := 400.0; END_IF;

        // 4. Adsorption Column Switching Valves (Amidoxime-functionalized polymers for Uranium)
        tColumnSwitchTimer(IN := TRUE, PT := T#4H); // 4-hour cycle

        IF tColumnSwitchTimer.Q THEN
            bColumnActive := NOT bColumnActive;
            tColumnSwitchTimer(IN := FALSE); // Reset timer
        END_IF;

        IF NOT bColumnActive THEN
            // Column A Adsorption, Column B Elution
            bValveColumnA_Feed := TRUE;
            bValveColumnA_Elution := FALSE;
            bValveColumnB_Feed := FALSE;
            bValveColumnB_Elution := TRUE;
        ELSE
            // Column B Adsorption, Column A Elution
            bValveColumnA_Feed := FALSE;
            bValveColumnA_Elution := TRUE;
            bValveColumnB_Feed := TRUE;
            bValveColumnB_Elution := FALSE;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
