FUNCTION_BLOCK FB_QKD_EntanglementSwapping
VAR_INPUT
    bExecute : BOOL;
    bAbort : BOOL;

    // Laser and PPLN Crystal parameters
    fLaserPumpPower_mW : LREAL := 10.0; // 405 nm pump
    fTargetTempPPLN_C : LREAL := 50.0;
    fActualTempPPLN_C : LREAL;

    // SNSPD parameters
    fCoincidenceWindow_ps : LREAL := 10.0;
    bDetector1_Trigger : BOOL;
    bDetector2_Trigger : BOOL;
    bDetector3_Trigger : BOOL;
    bDetector4_Trigger : BOOL;
    fPhotonArrival_t1_ps : LREAL;
    fPhotonArrival_t2_ps : LREAL;

    // Polarization & EOM (Pockels Cell)
    fGroundStation1_Phase_rad : LREAL;
    fGroundStation2_Phase_rad : LREAL;
END_VAR

VAR_OUTPUT
    // PackML State
    eState : E_PackML_State := E_PackML_State.STOPPED;

    bPPLN_TempStable : BOOL;
    fHeaterOutput_pct : LREAL;

    bEntanglementSwapped : BOOL;
    nBellStateDetected : USINT; // 1: Phi+, 2: Phi-, 3: Psi+, 4: Psi-
    nCoincidenceCounts : ULINT;

    fQBER_Estimate : LREAL;

    bError : BOOL;
    nErrorID : UDINT;
END_VAR

VAR
    // Internal state
    fbPPLN_PID : FB_PID_Controller;
    fbCoincidenceTimer : FB_HighResTimer;

    fDeltaT_ps : LREAL;

    // Matrices for BSM (Hong-Ou-Mandel)
    aHOM_Matrix : ARRAY[0..1, 0..1] OF LREAL := [0.707106, 0.707106, 0.707106, -0.707106];

    nStateTransitionDelay : TIME := T#10MS;
END_VAR

// PID Execution for PPLN Thermal Stabilization (0.001 C precision required)
fbPPLN_PID(
    fSetpoint := fTargetTempPPLN_C,
    fActualValue := fActualTempPPLN_C,
    fKp := 150.0,
    fKi := 5.0,
    fKd := 10.0,
    bEnable := (eState = E_PackML_State.EXECUTE) OR (eState = E_PackML_State.STARTING),
    fOutput => fHeaterOutput_pct
);

bPPLN_TempStable := ABS(fTargetTempPPLN_C - fActualTempPPLN_C) <= 0.001;

// State Machine
CASE eState OF
    E_PackML_State.STOPPED:
        bEntanglementSwapped := FALSE;
        IF bExecute THEN
            eState := E_PackML_State.STARTING;
        END_IF

    E_PackML_State.STARTING:
        IF bPPLN_TempStable THEN
            eState := E_PackML_State.EXECUTE;
        END_IF
        IF bAbort THEN
            eState := E_PackML_State.ABORTING;
        END_IF

    E_PackML_State.EXECUTE:
        // 1. Spontaneous Parametric Down-Conversion (SPDC) Logic
        // Handled by PPLN PID continuously. Ensure pump is stable.

        // 2. Bell State Measurement (BSM) & Swapping
        IF bDetector1_Trigger OR bDetector2_Trigger OR bDetector3_Trigger OR bDetector4_Trigger THEN
            fDeltaT_ps := ABS(fPhotonArrival_t1_ps - fPhotonArrival_t2_ps);

            // Picosecond coincidence window tracking using SNSPDs
            IF fDeltaT_ps <= fCoincidenceWindow_ps THEN
                nCoincidenceCounts := nCoincidenceCounts + 1;

                // Real-time electro-optic modulation (Pockels cells) routing
                // Evaluate HOM interference
                // BSM Logic (Simplified for ST):
                // Phi+ / Phi- are indistinguishable with linear optics without additional hyper-entanglement,
                // but Psi+ and Psi- can be distinguished by coincidence patterns.
                IF bDetector1_Trigger AND bDetector4_Trigger THEN
                    nBellStateDetected := 3; // Psi+
                    bEntanglementSwapped := TRUE;
                ELSIF bDetector1_Trigger AND bDetector3_Trigger THEN
                    nBellStateDetected := 4; // Psi-
                    bEntanglementSwapped := TRUE;
                ELSE
                    bEntanglementSwapped := FALSE;
                END_IF

                // Update QBER (Quantum Bit Error Rate) estimation
                // Very simplified heuristic for demo
                fQBER_Estimate := 0.01 + (fDeltaT_ps / fCoincidenceWindow_ps) * 0.02;
            ELSE
                bEntanglementSwapped := FALSE;
            END_IF
        ELSE
             bEntanglementSwapped := FALSE;
        END_IF

        IF NOT bExecute THEN
            eState := E_PackML_State.STOPPING;
        END_IF
        IF bAbort THEN
            eState := E_PackML_State.ABORTING;
        END_IF

    E_PackML_State.STOPPING:
        fHeaterOutput_pct := 0.0;
        eState := E_PackML_State.STOPPED;

    E_PackML_State.ABORTING:
        fHeaterOutput_pct := 0.0;
        bEntanglementSwapped := FALSE;
        eState := E_PackML_State.ABORTED;

    E_PackML_State.ABORTED:
        IF NOT bAbort AND NOT bExecute THEN
            eState := E_PackML_State.STOPPED;
        END_IF

END_CASE
END_FUNCTION_BLOCK
