FUNCTION_BLOCK FB_EAF_MasterControl
TITLE = 'EAF Master Control: Electrode, CEMS, and Slag Door'
VERSION : '1.0'
AUTHOR : 'Lumina AI'

VAR_INPUT
    bAutoMode : BOOL; // Auto mode active
    bStartHeat : BOOL; // Start EAF heating cycle
    bStopHeat : BOOL; // Stop heating cycle

    // Electrode Gap Control
    rTargetArcVoltage : REAL := 300.0; // Target arc voltage in Volts
    rActualArcVoltage1 : REAL; // Phase 1 actual voltage
    rActualArcVoltage2 : REAL; // Phase 2 actual voltage
    rActualArcVoltage3 : REAL; // Phase 3 actual voltage
    rElectrodePosFdbk1 : REAL; // Phase 1 position feedback (mm)
    rElectrodePosFdbk2 : REAL; // Phase 2 position feedback (mm)
    rElectrodePosFdbk3 : REAL; // Phase 3 position feedback (mm)

    // CEMS (Continuous Emission Monitoring System)
    rCOLevel_ppm : REAL; // CO concentration in ppm
    rO2Level_pct : REAL; // O2 concentration in %
    rNOxLevel_ppm : REAL; // NOx concentration in ppm
    rOffGasTemp_C : REAL; // Off-gas temperature in Celsius

    // Slag Door Hydraulics
    bOpenSlagDoorCmd : BOOL; // Command to open slag door
    bCloseSlagDoorCmd : BOOL; // Command to close slag door
    rHydraulicSystemPress : REAL; // Hydraulic system pressure (bar)
END_VAR

VAR_OUTPUT
    // Electrode Control
    rElectrodeSpeedRef1 : REAL; // Phase 1 speed reference (mm/s)
    rElectrodeSpeedRef2 : REAL; // Phase 2 speed reference (mm/s)
    rElectrodeSpeedRef3 : REAL; // Phase 3 speed reference (mm/s)

    // CEMS Alarms
    bCEMSFault : BOOL; // CEMS general fault
    bHighCOAlarm : BOOL; // CO > threshold
    bHighNOxAlarm : BOOL; // NOx > threshold
    bBurnerRampDownCmd : BOOL; // Command to ramp down burners due to high emissions

    // Slag Door
    bSlagDoorOpenValve : BOOL; // Open solenoid valve
    bSlagDoorCloseValve : BOOL; // Close solenoid valve
    bSlagDoorHydraulicFault : BOOL; // Low pressure fault

    // System Status
    iSystemState : INT; // Current state of the EAF master control
END_VAR

VAR
    // PID Parameters for Electrode Control (Deadband + P Control)
    rDeadbandVolts : REAL := 15.0;
    rProportionalGain : REAL := 0.5;
    rMaxElectrodeSpeed : REAL := 50.0; // max mm/s

    // Timers
    tonCOAlarmDelay : TON;
    tonNOxAlarmDelay : TON;
    tonSlagDoorTimeout : TON;

    // Internal state
    bHeatActive : BOOL;
    rErrorV1, rErrorV2, rErrorV3 : REAL;
END_VAR

// -----------------------------------------------------------------------------
// SYSTEM STATE LOGIC
// -----------------------------------------------------------------------------
IF bStartHeat AND bAutoMode AND NOT bStopHeat THEN
    bHeatActive := TRUE;
    iSystemState := 10; // Heating state
ELSIF bStopHeat OR NOT bAutoMode THEN
    bHeatActive := FALSE;
    iSystemState := 0; // Idle state
END_IF;

// -----------------------------------------------------------------------------
// ELECTRODE REGULATION (GAP VOLTAGE TRACKING)
// -----------------------------------------------------------------------------
rErrorV1 := rTargetArcVoltage - rActualArcVoltage1;
rErrorV2 := rTargetArcVoltage - rActualArcVoltage2;
rErrorV3 := rTargetArcVoltage - rActualArcVoltage3;

IF bHeatActive THEN
    // Phase 1 Regulation
    IF ABS(rErrorV1) > rDeadbandVolts THEN
        rElectrodeSpeedRef1 := rErrorV1 * rProportionalGain;
    ELSE
        rElectrodeSpeedRef1 := 0.0;
    END_IF;

    // Phase 2 Regulation
    IF ABS(rErrorV2) > rDeadbandVolts THEN
        rElectrodeSpeedRef2 := rErrorV2 * rProportionalGain;
    ELSE
        rElectrodeSpeedRef2 := 0.0;
    END_IF;

    // Phase 3 Regulation
    IF ABS(rErrorV3) > rDeadbandVolts THEN
        rElectrodeSpeedRef3 := rErrorV3 * rProportionalGain;
    ELSE
        rElectrodeSpeedRef3 := 0.0;
    END_IF;

    // Limit speeds
    IF rElectrodeSpeedRef1 > rMaxElectrodeSpeed THEN rElectrodeSpeedRef1 := rMaxElectrodeSpeed; END_IF;
    IF rElectrodeSpeedRef1 < -rMaxElectrodeSpeed THEN rElectrodeSpeedRef1 := -rMaxElectrodeSpeed; END_IF;
    IF rElectrodeSpeedRef2 > rMaxElectrodeSpeed THEN rElectrodeSpeedRef2 := rMaxElectrodeSpeed; END_IF;
    IF rElectrodeSpeedRef2 < -rMaxElectrodeSpeed THEN rElectrodeSpeedRef2 := -rMaxElectrodeSpeed; END_IF;
    IF rElectrodeSpeedRef3 > rMaxElectrodeSpeed THEN rElectrodeSpeedRef3 := rMaxElectrodeSpeed; END_IF;
    IF rElectrodeSpeedRef3 < -rMaxElectrodeSpeed THEN rElectrodeSpeedRef3 := -rMaxElectrodeSpeed; END_IF;
ELSE
    // Retract electrodes slowly if not heating
    rElectrodeSpeedRef1 := 10.0;
    rElectrodeSpeedRef2 := 10.0;
    rElectrodeSpeedRef3 := 10.0;
END_IF;

// -----------------------------------------------------------------------------
// OFF-GAS CONTINUOUS EMISSION MONITORING (CEMS)
// -----------------------------------------------------------------------------
// CO Alarm Timer (Delay 5 seconds to prevent nuisance trips)
tonCOAlarmDelay(IN := (rCOLevel_ppm > 5000.0), PT := T#5S);
bHighCOAlarm := tonCOAlarmDelay.Q;

// NOx Alarm Timer (Delay 10 seconds)
tonNOxAlarmDelay(IN := (rNOxLevel_ppm > 300.0), PT := T#10S);
bHighNOxAlarm := tonNOxAlarmDelay.Q;

bCEMSFault := (rOffGasTemp_C > 1800.0) OR (rO2Level_pct < 1.0);

// Intervention logic
IF bHighCOAlarm OR bHighNOxAlarm OR bCEMSFault THEN
    bBurnerRampDownCmd := TRUE;
ELSE
    bBurnerRampDownCmd := FALSE;
END_IF;

// -----------------------------------------------------------------------------
// SLAG Door HYDRAULICS CONTROL
// -----------------------------------------------------------------------------
IF rHydraulicSystemPress < 150.0 THEN
    bSlagDoorHydraulicFault := TRUE;
    bSlagDoorOpenValve := FALSE;
    bSlagDoorCloseValve := FALSE;
ELSE
    bSlagDoorHydraulicFault := FALSE;

    IF bOpenSlagDoorCmd AND NOT bCloseSlagDoorCmd THEN
        bSlagDoorOpenValve := TRUE;
        bSlagDoorCloseValve := FALSE;
    ELSIF bCloseSlagDoorCmd AND NOT bOpenSlagDoorCmd THEN
        bSlagDoorOpenValve := FALSE;
        bSlagDoorCloseValve := TRUE;
    ELSE
        // Default to holding position
        bSlagDoorOpenValve := FALSE;
        bSlagDoorCloseValve := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
