FUNCTION_BLOCK FB_Marine_MHD_Propulsion
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bSystemEnable : BOOL; (* Overall system enable signal from bridge *)
    bEmergencyStop : BOOL; (* Safety interlock - True = OK, False = E-Stop active *)
    rCryoTemp1 : REAL; (* Superconducting coil array A temperature (K) - Port *)
    rCryoTemp2 : REAL; (* Superconducting coil array B temperature (K) - Starboard *)
    rSeawaterConductivity : REAL; (* Measured seawater conductivity in S/m *)
    rDesiredThrust : REAL; (* Commanded thrust percentage from 0.0 to 100.0 *)
    bAcousticStealthMode : BOOL; (* Cavitation suppression active (Silent Drive) *)
    rIonizationVoltageFeedbk : REAL; (* Actual applied voltage across MHD electrodes (kV) *)
    rVibrationSensor : REAL; (* Hull vibration acoustic sensor (mm/s) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady : BOOL; (* MHD Drive ready for thrust application *)
    rTargetIonizationVoltage : REAL; (* Command voltage to seawater electrodes (kV) *)
    rCoilCurrentSetpt : REAL; (* Command current to superconducting electromagnets (kA) *)
    bQuenchAlarm : BOOL; (* Cryogenic quench imminent alarm - critical fault *)
    bCavitationWarning : BOOL; (* Acoustic signature threshold exceeded warning *)
    bDriveFault : BOOL; (* Critical fault, system shutdown and safe state active *)
END_VAR
VAR
    (* Internal state variables *)
    iState : INT := 0;
    tStartDelay : TON;
    tQuenchFilter : TON;
    tCavitationCheck : TON;
    rFilteredCryoTemp : REAL := 4.2;
    rAlpha : REAL := 0.15; (* Low pass filter coefficient for temperature noise *)
    rVoltageMax : REAL := 80.0; (* Maximum allowable electrode voltage in kV *)
    rCurrentMax : REAL := 25.0; (* Nominal superconducting coil current in kA *)
    rCalculatedThrustReq : REAL := 0.0;
    rPrevVoltage : REAL := 0.0;
    rVoltageRampRate : REAL := 2.5; (* kV per cycle ramp rate limit *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    iState := 99; (* FAULT STATE *)
    bSystemReady := FALSE;
    bDriveFault := TRUE;
END_IF;

(* First-order low pass filter for cryogenic temperatures to prevent spurious quench alarms *)
rFilteredCryoTemp := rFilteredCryoTemp + rAlpha * (MAX(rCryoTemp1, rCryoTemp2) - rFilteredCryoTemp);

(* Cryogenic Quench Protection Logic *)
tQuenchFilter(IN := (rFilteredCryoTemp > 5.8), PT := T#500MS);
IF tQuenchFilter.Q THEN
    bQuenchAlarm := TRUE;
    iState := 99; (* Transition to fault state to dump magnetic energy *)
ELSE
    bQuenchAlarm := FALSE;
END_IF;

CASE iState OF
    0: (* IDLE / OFF STATE *)
        bSystemReady := FALSE;
        rTargetIonizationVoltage := 0.0;
        rCoilCurrentSetpt := 0.0;
        bDriveFault := FALSE;
        bCavitationWarning := FALSE;
        rPrevVoltage := 0.0;

        IF bSystemEnable AND NOT bQuenchAlarm THEN
            iState := 10;
        END_IF;

    10: (* MAGNETIZING SEQUENCE *)
        (* Slowly ramp the superconducting coil current to prevent flux jumps *)
        IF rCoilCurrentSetpt < rCurrentMax THEN
            rCoilCurrentSetpt := rCoilCurrentSetpt + 0.1;
        END_IF;

        tStartDelay(IN := (rCoilCurrentSetpt >= rCurrentMax), PT := T#15S);
        IF tStartDelay.Q THEN
            tStartDelay(IN := FALSE);
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* RUNNING / ACTIVE DRIVE *)
        IF bSystemEnable THEN
            (* Calculate required ionization voltage based on commanded thrust and water conductivity *)
            rCalculatedThrustReq := (rDesiredThrust / 100.0) * rVoltageMax;

            (* Conductivity compensation: lower conductivity requires higher voltage for same current/thrust *)
            IF rSeawaterConductivity > 0.5 THEN
                rCalculatedThrustReq := rCalculatedThrustReq * (4.0 / rSeawaterConductivity);
            ELSE
                rCalculatedThrustReq := rCalculatedThrustReq * 8.0; (* Limit extreme scaling *)
            END_IF;

            (* Acoustic stealth mode: cap maximum voltage and monitor vibration *)
            IF bAcousticStealthMode THEN
                IF rCalculatedThrustReq > 30.0 THEN
                    rCalculatedThrustReq := 30.0;
                END_IF;

                tCavitationCheck(IN := (rVibrationSensor > 12.5), PT := T#2S);
                IF tCavitationCheck.Q THEN
                    bCavitationWarning := TRUE;
                    rCalculatedThrustReq := rCalculatedThrustReq * 0.8; (* Back off voltage on cavitation *)
                ELSE
                    bCavitationWarning := FALSE;
                END_IF;
            ELSE
                bCavitationWarning := FALSE;
            END_IF;

            (* Voltage ramp rate limiter *)
            IF rCalculatedThrustReq > (rPrevVoltage + rVoltageRampRate) THEN
                rTargetIonizationVoltage := rPrevVoltage + rVoltageRampRate;
            ELSIF rCalculatedThrustReq < (rPrevVoltage - rVoltageRampRate) THEN
                rTargetIonizationVoltage := rPrevVoltage - rVoltageRampRate;
            ELSE
                rTargetIonizationVoltage := rCalculatedThrustReq;
            END_IF;

            rPrevVoltage := rTargetIonizationVoltage;

        ELSE
            iState := 0;
        END_IF;

    99: (* FAULT / SAFE SHUTDOWN STATE *)
        bSystemReady := FALSE;
        bDriveFault := TRUE;

        (* Immediate zeroing of electrode voltage *)
        rTargetIonizationVoltage := 0.0;
        rPrevVoltage := 0.0;

        (* Active controlled discharge of superconducting coils to prevent catastrophic quench overpressure *)
        IF rCoilCurrentSetpt > 0.0 THEN
            rCoilCurrentSetpt := rCoilCurrentSetpt - 0.5;
            IF rCoilCurrentSetpt < 0.0 THEN
                rCoilCurrentSetpt := 0.0;
            END_IF;
        END_IF;

        (* Reset mechanism: E-Stop restored, alarms clear, and bridge enable dropped *)
        IF bEmergencyStop AND NOT bQuenchAlarm AND NOT bSystemEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
