    rSlaveAugerTorque   : REAL; // %
    bCarriageForward    : BOOL; // Carriage travel direction
    bCarriageReverse    : BOOL; // Carriage travel direction

    // System Control
    bStartSequence      : BOOL;
    bStopSequence       : BOOL;
    iActivePhase        : INT; // 1=Withering, 2=Curing, 3=Cooling
END_VAR

VAR_OUTPUT
    // Airflow & Conditioning
    rMainFanSpeedRef    : REAL; // 0-100%
    rRecircDamperPos    : REAL; // 0% (Full Fresh) to 100% (Full Recirc)
    rExhaustDamperPos   : REAL; // 0-100%
    rBurnerPowerRef     : REAL; // 0-100%

    // Turning Machine
    rMasterAugerCmd     : REAL; // RPM Reference
    rSlaveAugerCmd      : REAL; // RPM Reference
    bCarriageEnable     : BOOL;

    // Alarms & Status
    bAlarmActive        : BOOL;
    iAlarmCode          : INT;
    bSequenceRunning    : BOOL;
END_VAR

VAR
    // Internal State & Timers
    tPhaseTimer         : TON;
    tAugerSyncTimer     : TON;
    rDeltaPressure      : REAL;
    rAvgBedTemp         : REAL;
    rTargetHumidity     : REAL;
    rHumidityError      : REAL;
    rHumidityIntegral   : REAL;
    rHumidityKp         : REAL := 1.5;
    rHumidityKi         : REAL := 0.05;

    rAugerSlip          : REAL;
    rMaxTorqueAllowed   : REAL := 85.0;
    i                   : INT;
END_VAR

// 1. Calculate Average Grain Bed Temperature
rAvgBedTemp := 0.0;
FOR i := 1 TO 8 DO
    rAvgBedTemp := rAvgBedTemp + rGrainBedTemp[i];
END_FOR;
rAvgBedTemp := rAvgBedTemp / 8.0;

// 2. Grain Bed Pressure Drop Monitoring
rDeltaPressure := rPlenumPressure - rSurfacePressure;
IF rDeltaPressure > 1500.0 THEN
    // Bed is too compact or airflow is blocked
    bAlarmActive := TRUE;
    iAlarmCode := 101; // High DP Alarm
    rMainFanSpeedRef := rMainFanSpeedRef * 0.9; // Automatically step down fan speed
ELSIF rDeltaPressure < 200.0 AND rMainFanSpeedRef > 20.0 THEN
    // Channeling occurring in the bed
    bAlarmActive := TRUE;
    iAlarmCode := 102; // Low DP Alarm (Channeling)
END_IF;

// 3. Airflow Recirculation Humidity Cascades (PI Controller)
// Depending on the phase, we target different exhaust humidities
CASE iActivePhase OF
    1: rTargetHumidity := 18.0; // Withering (high moisture removal)
    2: rTargetHumidity := 8.0;  // Curing (low moisture)
    3: rTargetHumidity := 12.0; // Cooling (ambient dependent)
ELSE
    rTargetHumidity := 10.0;
END_CASE;

rHumidityError := rTargetHumidity - rExhaustHumidity;
rHumidityIntegral := rHumidityIntegral + (rHumidityError * 0.1); // Assuming 100ms task
// Anti-windup
IF rHumidityIntegral > 100.0 THEN rHumidityIntegral := 100.0; END_IF;
IF rHumidityIntegral < 0.0 THEN rHumidityIntegral := 0.0; END_IF;

rRecircDamperPos := (rHumidityError * rHumidityKp) + rHumidityKi * rHumidityIntegral;

// Clamp Damper Position
IF rRecircDamperPos > 100.0 THEN 
    rRecircDamperPos := 100.0; 
ELSIF rRecircDamperPos < 0.0 THEN 
    rRecircDamperPos := 0.0; 
END_IF;

rExhaustDamperPos := 100.0 - rRecircDamperPos;

// 4. Grain Turning Machine Spiral Auger Synchronization
// The slave auger must strictly follow the master, adjusting for load slip
rMasterAugerCmd := 15.0; // Base turning speed
rAugerSlip := rMasterAugerSpeed - rSlaveAugerSpeed;

// If slave falls behind by more than 1.5 RPM, increase slave command slightly to catch up
IF rAugerSlip > 1.5 THEN
    rSlaveAugerCmd := rMasterAugerCmd + 0.5;
ELSIF rAugerSlip < -1.5 THEN
    rSlaveAugerCmd := rMasterAugerCmd - 0.5;
ELSE
    rSlaveAugerCmd := rMasterAugerCmd;
END_IF;

// Torque Protection Interlock
tAugerSyncTimer(IN := (rMasterAugerTorque > rMaxTorqueAllowed) OR (rSlaveAugerTorque > rMaxTorqueAllowed), PT := T#5s);
IF tAugerSyncTimer.Q THEN
    bCarriageEnable := FALSE;
    rMasterAugerCmd := 0.0;
    rSlaveAugerCmd := 0.0;
    bAlarmActive := TRUE;
    iAlarmCode := 201; // Auger Torque Overload
ELSE
    bCarriageEnable := bSequenceRunning;
END_IF;

// Start/Stop Logic
IF bStartSequence AND NOT bAlarmActive THEN
    bSequenceRunning := TRUE;
END_IF;

IF bStopSequence THEN
    bSequenceRunning := FALSE;
    rMainFanSpeedRef := 0.0;
    rBurnerPowerRef := 0.0;
    bCarriageEnable := FALSE;
END_IF;

END_FUNCTION_BLOCK
