FUNCTION_BLOCK FB_mRNALNPMicrofluidicMixer
VAR_INPUT
    (* Required physical inputs *)
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (active high = safe) *)
    rAqueousFlowRate        : REAL;     (* Flow rate of mRNA aqueous phase in mL/min *)
    rLipidFlowRate          : REAL;     (* Flow rate of lipid organic phase in mL/min *)
    rDLS_ParticleSize       : REAL;     (* Z-average particle size from DLS in nm *)
    rTFF_RetentatePressure  : REAL;     (* Pressure at TFF retentate in bar *)
END_VAR
VAR_OUTPUT
    (* Required physical outputs *)
    bSystemReady            : BOOL;     (* System ready status for upstream automation *)
    rAqueousPumpControl     : REAL;     (* Control signal 0-100% to aqueous pump VFD *)
    rLipidPumpControl       : REAL;     (* Control signal 0-100% to lipid pump VFD *)
    rTFF_TransMemPressure   : REAL;     (* Calculated Trans-Membrane Pressure (TMP) *)
    bAlarm                  : BOOL;     (* General fault alarm output *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tTimer                  : TON;
    rFlowRatio              : REAL := 3.0; (* Aqueous to Lipid volumetric ratio (typical 3:1) *)
    rTotalFlowTarget        : REAL := 100.0; (* 100 mL/min target total flow *)
    rKp                     : REAL := 1.25; (* Proportional gain for size control *)
    rKi                     : REAL := 0.45; (* Integral gain *)
    rSizeError              : REAL := 0.0;
    rSizeErrorSum           : REAL := 0.0;
    rTargetSize             : REAL := 80.0; (* 80 nm target particle size *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    rAqueousPumpControl := 0.0;
    rLipidPumpControl := 0.0;
    iState := 0;
    RETURN;
END_IF;

(* Continuous monitoring and calculations *)
rTFF_TransMemPressure := (rTFF_RetentatePressure + 0.5) / 2.0; (* Simplified TMP approx *)

CASE iState OF
    0: (* IDLE State *)
        bSystemReady := TRUE;
        bAlarm := FALSE;
        rAqueousPumpControl := 0.0;
        rLipidPumpControl := 0.0;

        IF bEnable THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PRIMING AND RAMP-UP *)
        (* Ramp up pumps to target total flow while maintaining exact 3:1 ratio *)
        rAqueousPumpControl := (rTotalFlowTarget * 0.75) * 0.1; (* 10% step *)
        rLipidPumpControl := (rTotalFlowTarget * 0.25) * 0.1; 

        tTimer(IN := TRUE, PT := T#5S);
        IF tTimer.Q THEN
            tTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* STEADY STATE MIXING & DLS CASCADE CONTROL *)
        (* Cascade PI control to fine-tune ratio based on particle size feedback *)
        rSizeError := rTargetSize - rDLS_ParticleSize;
        rSizeErrorSum := rSizeErrorSum + rSizeError;

        (* Prevent windup *)
        IF rSizeErrorSum > 50.0 THEN rSizeErrorSum := 50.0; END_IF;
        IF rSizeErrorSum < -50.0 THEN rSizeErrorSum := -50.0; END_IF;

        (* Adjust flow ratio slightly to hit size target (smaller ratio = larger particles usually) *)
        rFlowRatio := 3.0 + (rSizeError * rKp + rSizeErrorSum * rKi) * 0.01;

        (* Recalculate pump commands based on modified ratio but constant total flow *)
        rAqueousPumpControl := rTotalFlowTarget * (rFlowRatio / (rFlowRatio + 1.0));
        rLipidPumpControl := rTotalFlowTarget * (1.0 / (rFlowRatio + 1.0));

        IF rTFF_TransMemPressure > 2.5 THEN
            (* High TMP alarm *)
            bAlarm := TRUE;
            iState := 99;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        rAqueousPumpControl := 0.0;
        rLipidPumpControl := 0.0;
        bSystemReady := FALSE;

        IF NOT bEnable THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
