    rSnoutPump_Cmd := 0.0;
    rKnifeDist_Cmd := 150.0; (* Fully retract knives *)
    rKnifePress_Cmd := 0.0;
    RETURN;
END_IF;

(* 1. Furnace Atmosphere Control (H2/N2) *)
(* Dynamic H2 target based on strip dimensions and speed *)
IF rLineSpeed_mpm > 50.0 AND rStripThickness_mm > 1.5 THEN
    rH2_Target_pct := 7.0; (* Higher reducing atmosphere needed *)
ELSE
    rH2_Target_pct := 5.0;
END_IF;

rMaxH2_Error := rH2_Target_pct - rH2_Concentration_pct;

(* Simple proportional control for H2 *)
IF rMaxH2_Error > 0.5 THEN
    rH2_Valve_Cmd := LIMIT(MN := 0.0, IN := rH2_Valve_Cmd + (rMaxH2_Error * rKp_Atmosphere), MX := 100.0);
ELSIF rMaxH2_Error < -0.5 THEN
    rH2_Valve_Cmd := LIMIT(MN := 0.0, IN := rH2_Valve_Cmd + (rMaxH2_Error * rKp_Atmosphere), MX := 100.0);
END_IF;

(* Maintain pressure with N2 *)
rN2_Valve_Cmd := 100.0 - rH2_Valve_Cmd;

(* Dew point monitoring *)
IF rDewPoint_C > -30.0 THEN
    bFurnaceAlarm := TRUE;
    (* Initiate purge *)
    rN2_Valve_Cmd := 100.0;
    rH2_Valve_Cmd := 0.0;
ELSE
    bFurnaceAlarm := FALSE;
END_IF;

(* 2. Zinc Pot Snout Level Control *)
(* Maintain snout level to prevent dross suction *)
IF bLineRunning THEN
    rSnoutPump_Cmd := LIMIT(MN := 0.0, IN := (rSnoutLevel_SP - rSnoutLevel_mm) * rKp_Snout, MX := 100.0);

    IF ABS(rSnoutLevel_SP - rSnoutLevel_mm) > 50.0 THEN
        bSnoutAlarm := TRUE;
    ELSE
        bSnoutAlarm := FALSE;
    END_IF;
ELSE
    rSnoutPump_Cmd := 0.0;
END_IF;

(* 3. Air Knife Coating Thickness Control *)
(* Mathematical model for air knife stripping *)
IF bLineRunning AND rLineSpeed_mpm > 10.0 THEN
    rCoatingFactor := rLineSpeed_mpm / (rTargetCoating_gsm + 1.0);

    (* Target pressure increases with speed and desired thinner coating *)
    rCalculatedPressure := 10.0 + (rLineSpeed_mpm * 0.5) - (rTargetCoating_gsm * 0.1);
    rKnifePress_Cmd := LIMIT(MN := 10.0, IN := rCalculatedPressure, MX := 80.0);

    (* Target distance adjustment *)
    IF rTargetCoating_gsm < 60.0 THEN
        rKnifeDist_Cmd := 8.0; (* Closer for thinner coating *)
    ELSIF rTargetCoating_gsm < 120.0 THEN
        rKnifeDist_Cmd := 12.0;
    ELSE
        rKnifeDist_Cmd := 16.0;
    END_IF;

    bCoatingAlarm := FALSE;
ELSE
    (* Open knives and drop pressure when line is stopped *)
    rKnifeDist_Cmd := 150.0;
    rKnifePress_Cmd := 0.0;
    IF NOT bLineRunning THEN
        bCoatingAlarm := FALSE;
    ELSE
        bCoatingAlarm := TRUE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
