FUNCTION_BLOCK FB_H2_Liquefaction_Plant
VAR_INPUT
    bStartSequence : BOOL;
    bEmergencyStop : BOOL;
    rFeedH2Temp_K : REAL; (* Inlet Hydrogen Temperature *)
    rFeedH2Press_Bar : REAL; (* Inlet Hydrogen Pressure *)
    rCatalystBed1Temp_K : REAL;
    rCatalystBed2Temp_K : REAL;
    rCatalystBed3Temp_K : REAL;
    rTurbine1Speed_RPM : REAL;
    rTurbine2Speed_RPM : REAL;
    rBOGPress_Bar : REAL; (* Boil-Off Gas Pressure *)
END_VAR
VAR_OUTPUT
    bComp1Run : BOOL;
    bComp2Run : BOOL;
    rTurbine1GuideVane_Pct : REAL;
    rTurbine2GuideVane_Pct : REAL;
    bCatalystHeater1Run : BOOL;
    bCatalystHeater2Run : BOOL;
    bCatalystHeater3Run : BOOL;
    rCoolingValve1_Pct : REAL;
    rCoolingValve2_Pct : REAL;
    bBOGCompressorRun : BOOL;
    iState : INT;
    bAlarmOrthoParaConv : BOOL;
    bAlarmTurbineOverspeed : BOOL;
END_VAR
VAR
    TON_StartDelay : TON;
    TON_Stabilize : TON;
    rTargetOrtho_Pct : REAL := 25.0; (* Natural H2 *)
    rTargetPara_Pct : REAL := 99.0; (* Liquid H2 target *)
    rTurbine1SetSpeed : REAL := 45000.0;
    rTurbine2SetSpeed : REAL := 60000.0;
    rTurbine1Kp : REAL := 0.5;
    rTurbine2Kp : REAL := 0.6;
END_VAR

(* Implementation *)
IF bEmergencyStop THEN
    bComp1Run := FALSE;
    bComp2Run := FALSE;
    rTurbine1GuideVane_Pct := 0.0;
    rTurbine2GuideVane_Pct := 0.0;
    bCatalystHeater1Run := FALSE;
    bCatalystHeater2Run := FALSE;
    bCatalystHeater3Run := FALSE;
    rCoolingValve1_Pct := 0.0;
    rCoolingValve2_Pct := 0.0;
    bBOGCompressorRun := FALSE;
    iState := 0;
    RETURN;
END_IF;

CASE iState OF
    0: (* Standby *)
        IF bStartSequence THEN
            TON_StartDelay(IN := TRUE, PT := T#5S);
            IF TON_StartDelay.Q THEN
                iState := 10;
                TON_StartDelay(IN := FALSE);
            END_IF;
        END_IF;

    10: (* Pre-cooling and Compressor Start *)
        bComp1Run := TRUE;
        bComp2Run := TRUE;
        IF rFeedH2Press_Bar > 20.0 THEN
            iState := 20;
        END_IF;

    20: (* Ortho-to-Para Conversion Stages *)
        (* Stage 1 LN2 pre-cooling *)
        IF rCatalystBed1Temp_K > 80.0 THEN
            rCoolingValve1_Pct := 100.0;
            bCatalystHeater1Run := FALSE;
        ELSE
            rCoolingValve1_Pct := 50.0;
            bCatalystHeater1Run := TRUE;
        END_IF;

        (* Stage 2 Expansion cooling *)
        IF rCatalystBed2Temp_K > 30.0 THEN
            rCoolingValve2_Pct := 100.0;
        ELSE
            rCoolingValve2_Pct := 60.0;
        END_IF;

        IF (rCatalystBed1Temp_K < 85.0) AND (rCatalystBed2Temp_K < 35.0) THEN
            iState := 30;
        END_IF;

    30: (* Turbine Cascade Expansion *)
        (* Proportional Control for Turbines *)
        rTurbine1GuideVane_Pct := (rTurbine1SetSpeed - rTurbine1Speed_RPM) * rTurbine1Kp;
        rTurbine2GuideVane_Pct := (rTurbine2SetSpeed - rTurbine2Speed_RPM) * rTurbine2Kp;

        (* Clamp outputs *)
        IF rTurbine1GuideVane_Pct > 100.0 THEN rTurbine1GuideVane_Pct := 100.0; END_IF;
        IF rTurbine1GuideVane_Pct < 0.0 THEN rTurbine1GuideVane_Pct := 0.0; END_IF;
        IF rTurbine2GuideVane_Pct > 100.0 THEN rTurbine2GuideVane_Pct := 100.0; END_IF;
        IF rTurbine2GuideVane_Pct < 0.0 THEN rTurbine2GuideVane_Pct := 0.0; END_IF;

        IF (rTurbine1Speed_RPM > rTurbine1SetSpeed * 1.1) OR (rTurbine2Speed_RPM > rTurbine2SetSpeed * 1.1) THEN
            bAlarmTurbineOverspeed := TRUE;
            iState := 99; (* Fault *)
        END_IF;

        iState := 40;

    40: (* BOG Recovery *)
        IF rBOGPress_Bar > 1.5 THEN
            bBOGCompressorRun := TRUE;
        ELSIF rBOGPress_Bar < 1.1 THEN
            bBOGCompressorRun := FALSE;
        END_IF;

    99: (* Fault State *)
        bComp1Run := FALSE;
        bComp2Run := FALSE;
        rTurbine1GuideVane_Pct := 0.0;
        rTurbine2GuideVane_Pct := 0.0;

END_CASE;

(* Conversion logic alarm *)
IF rCatalystBed3Temp_K > 25.0 AND iState >= 30 THEN
    bAlarmOrthoParaConv := TRUE;
ELSE
    bAlarmOrthoParaConv := FALSE;
END_IF;

END_FUNCTION_BLOCK
