FUNCTION_BLOCK FB_SlotDieCoatingControl
VAR_INPUT
    bEnable                 : BOOL;   (* Enable coating line control *)
    bEmergencyStop          : BOOL;   (* Emergency stop active low *)
    rLineSpeedCmd           : REAL;   (* Desired line speed [m/min] *)
    rTargetThickness        : REAL;   (* Target coating thickness [um] *)
    rThicknessPV_Left       : REAL;   (* Actual thickness left side [um] *)
    rThicknessPV_Right      : REAL;   (* Actual thickness right side [um] *)
    rSlurryFlowCmd          : REAL;   (* Target slurry flow rate [L/min] *)
    rSlurryFlowPV           : REAL;   (* Actual slurry flow rate [L/min] *)
    rOven1TempCmd           : REAL;   (* Target temperature Zone 1 [°C] *)
    rOven1TempPV            : REAL;   (* Actual temperature Zone 1 [°C] *)
    rOven2TempCmd           : REAL;   (* Target temperature Zone 2 [°C] *)
    rOven2TempPV            : REAL;   (* Actual temperature Zone 2 [°C] *)
    rWebTensionCmd          : REAL;   (* Target web tension [N] *)
    rWebTensionPV           : REAL;   (* Actual web tension [N] *)
    rEdgeSensor             : REAL;   (* Web edge position error [mm] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;   (* System is ready for operation *)
    bCoatingActive          : BOOL;   (* Coating process is active *)
    bAlarm                  : BOOL;   (* General alarm flag *)
    iAlarmCode              : INT;    (* Specific alarm code *)

    rPumpSpeedOut           : REAL;   (* Output to slurry pump [0-100%] *)
    rDieGapActuatorLeftOut  : REAL;   (* Output to left die gap actuator [0-100%] *)
    rDieGapActuatorRightOut : REAL;   (* Output to right die gap actuator [0-100%] *)

    rOven1HeaterOut         : REAL;   (* Output to Oven 1 heater [0-100%] *)
    rOven2HeaterOut         : REAL;   (* Output to Oven 2 heater [0-100%] *)

    rRewinderTorqueOut      : REAL;   (* Output to rewinder drive [Nm] *)
    rWebGuideActuatorOut    : REAL;   (* Output to web edge guide [mm] *)
END_VAR

VAR
    (* PID Controllers State Variables *)
    stThicknessPID_Left     : PID_STRUCT;
    stThicknessPID_Right    : PID_STRUCT;
    stSlurryFlowPID         : PID_STRUCT;
    stOven1PID              : PID_STRUCT;
    stOven2PID              : PID_STRUCT;
    stTensionPID            : PID_STRUCT;

    (* Internal State *)
    eState                  : E_COATING_STATE;
    rAverageThickness       : REAL;
    tCoatingTimer           : TON;
    rDieGapMaxLimit         : REAL := 100.0;
    rDieGapMinLimit         : REAL := 10.0;
END_VAR

(* 
    ================================================================================
    BATTERY ELECTRODE SLOT-DIE COATING CONTROL LOGIC
    ================================================================================
*)

IF NOT bEmergencyStop THEN
    eState := E_COATING_STATE.ESTOP;
    bSystemReady := FALSE;
    bCoatingActive := FALSE;
    bAlarm := TRUE;
    iAlarmCode := 999;

    (* Safe state outputs *)
    rPumpSpeedOut := 0.0;
    rDieGapActuatorLeftOut := 100.0; (* Fully open *)
    rDieGapActuatorRightOut := 100.0;
    rOven1HeaterOut := 0.0;
    rOven2HeaterOut := 0.0;
    rRewinderTorqueOut := 0.0;
    rWebGuideActuatorOut := 0.0;
    RETURN;
END_IF;

CASE eState OF
    E_COATING_STATE.INIT:
        IF bEnable THEN
            eState := E_COATING_STATE.READY;
            bSystemReady := TRUE;
            bAlarm := FALSE;
            iAlarmCode := 0;
        END_IF;

    E_COATING_STATE.READY:
        IF bEnable AND rLineSpeedCmd > 0.0 THEN
            eState := E_COATING_STATE.RUNNING;
            bCoatingActive := TRUE;
        ELSIF NOT bEnable THEN
            eState := E_COATING_STATE.INIT;
            bSystemReady := FALSE;
        END_IF;

    E_COATING_STATE.RUNNING:
        IF NOT bEnable THEN
            eState := E_COATING_STATE.STOPPING;
        END_IF;

        (* 1. Slurry Flow Control *)
        stSlurryFlowPID.SetPoint := rSlurryFlowCmd;
        stSlurryFlowPID.ProcessVariable := rSlurryFlowPV;
        stSlurryFlowPID.Kp := 2.5;
        stSlurryFlowPID.Ki := 1.1;
        stSlurryFlowPID.Kd := 0.05;
        CALL_PID(stPID := stSlurryFlowPID);
        rPumpSpeedOut := stSlurryFlowPID.Output;

        (* 2. Slot-Die Gap Thickness Control (Dual Zone) *)
        rAverageThickness := (rThicknessPV_Left + rThicknessPV_Right) / 2.0;

        stThicknessPID_Left.SetPoint := rTargetThickness;
        stThicknessPID_Left.ProcessVariable := rThicknessPV_Left;
        stThicknessPID_Left.Kp := 5.0;
        stThicknessPID_Left.Ki := 0.2;
        CALL_PID(stPID := stThicknessPID_Left);
        rDieGapActuatorLeftOut := LIMIT(rDieGapMinLimit, stThicknessPID_Left.Output, rDieGapMaxLimit);

        stThicknessPID_Right.SetPoint := rTargetThickness;
        stThicknessPID_Right.ProcessVariable := rThicknessPV_Right;
        stThicknessPID_Right.Kp := 5.0;
        stThicknessPID_Right.Ki := 0.2;
        CALL_PID(stPID := stThicknessPID_Right);
        rDieGapActuatorRightOut := LIMIT(rDieGapMinLimit, stThicknessPID_Right.Output, rDieGapMaxLimit);

        (* 3. Dual-Zone Flotation Drying Oven Control *)
        stOven1PID.SetPoint := rOven1TempCmd;
        stOven1PID.ProcessVariable := rOven1TempPV;
        CALL_PID(stPID := stOven1PID);
        rOven1HeaterOut := stOven1PID.Output;

        stOven2PID.SetPoint := rOven2TempCmd;
        stOven2PID.ProcessVariable := rOven2TempPV;
        CALL_PID(stPID := stOven2PID);
        rOven2HeaterOut := stOven2PID.Output;

        (* 4. Rewinder Web Edge Guiding and Tension *)
        stTensionPID.SetPoint := rWebTensionCmd;
        stTensionPID.ProcessVariable := rWebTensionPV;
        CALL_PID(stPID := stTensionPID);
        rRewinderTorqueOut := stTensionPID.Output;

        (* Proportional web edge control with deadband *)
        IF ABS(rEdgeSensor) > 1.5 THEN
            rWebGuideActuatorOut := rWebGuideActuatorOut + (rEdgeSensor * 0.1);
        END_IF;
        rWebGuideActuatorOut := LIMIT(-50.0, rWebGuideActuatorOut, 50.0);

        (* Fault Detection *)
        IF ABS(rAverageThickness - rTargetThickness) > 10.0 THEN
            bAlarm := TRUE;
            iAlarmCode := 101; (* Thickness deviation fault *)
        END_IF;

    E_COATING_STATE.STOPPING:
        bCoatingActive := FALSE;
        rPumpSpeedOut := 0.0;
        IF rLineSpeedCmd <= 0.0 THEN
            eState := E_COATING_STATE.READY;
        END_IF;

    E_COATING_STATE.ESTOP:
        (* Require manual reset *)
        IF bEmergencyStop AND bEnable THEN
            eState := E_COATING_STATE.INIT;
            bAlarm := FALSE;
            iAlarmCode := 0;
        END_IF;
END_CASE;
END_FUNCTION_BLOCK
