FUNCTION_BLOCK FB_PlasmaPulse_GeothermalDrill
TITLE = 'Supercritical Geothermal Plasma Pulse Drill & Wellbore Stability Controller'
VERSION : '1.0'

(* 
   This function block controls the High-Voltage Plasma Pulse Excavation and 
   Supercritical Water Quench for Ultra-Deep Geothermal Drilling. 
   Designed for PackML state logic and strict IEC 61131-3 compliance.
*)

VAR_INPUT
    // PackML State Commands
    bExecute            : BOOL;     // Start drilling operations
    bAbort              : BOOL;     // Emergency Stop / Abort
    bHold               : BOOL;     // Hold operations
    bReset              : BOOL;     // Reset faults

    // Process Inputs
    fDepth_m            : LREAL;    // Current depth in meters
    fHydroPress_bar     : LREAL;    // Hydrostatic pressure at bottom hole (bar)
    fTempBottomHole_C   : LREAL;    // Bottom hole temperature (Celsius)
    fRockAcousticImp    : LREAL;    // Rock acoustic impedance (kg/m2s)
    fMudDielectricStr   : LREAL;    // Mud dielectric strength (kV/mm)

    // Equipment Status
    bPFN_Charged        : BOOL;     // Pulse Forming Network charged status
    fPFN_Voltage_kV     : LREAL;    // Current PFN voltage (kV)
    fMudFlowRate_Lpm    : LREAL;    // Mud flow rate (Liters per minute)
    fMudDensity_kg_m3   : LREAL;    // Mud density (kg/m3)
END_VAR

VAR_OUTPUT
    // PackML Status
    iState              : INT;      // Current PackML State (e.g., 1=IDLE, 2=STARTING, 3=EXECUTE, 4=HOLDING, etc.)
    bReady              : BOOL;     // Ready to drill
    bActive             : BOOL;     // Actively pulsing
    bFault              : BOOL;     // System Fault
    iFaultCode          : INT;      // Specific fault code

    // Control Outputs
    fCmd_PFN_Voltage_kV : LREAL;    // Commanded PFN Voltage target
    fCmd_PulseFreq_Hz   : LREAL;    // Commanded plasma pulse frequency
    bCmd_FirePulse      : BOOL;     // Trigger plasma pulse

    // Mud Circulation Outputs
    fCmd_MudFlow_Lpm    : LREAL;    // Target mud flow rate for quenching
    fCmd_MudDensity     : LREAL;    // Target mud density for stability
    bCmd_ChokeValveOpen : BOOL;     // Annulus choke valve control
END_VAR

VAR
    // Internal States
    rTrigExecute        : R_TRIG;
    rTrigReset          : R_TRIG;
    rTrigTimerFire      : R_TRIG;

    // Timers
    tPulseTimer         : TON;      // Controls pulse frequency

    // Internal calculations
    fBreakdownVoltage   : LREAL;    // Required voltage for dielectric breakdown
    fAcousticMatchCoef  : LREAL;    // Tuning coefficient for impedance
    fQuenchFlowReq      : LREAL;    // Required flow for quenching

    // Constants
    c_MaxVoltage_kV     : LREAL := 500.0;
    c_MaxPulseFreq_Hz   : LREAL := 10.0;
    c_SupercriticalTemp : LREAL := 374.0; // Water critical temp
    c_SupercriticalPres : LREAL := 221.0; // Water critical pressure
END_VAR

// -----------------------------------------------------------------------------
// PackML State Machine Implementation
// -----------------------------------------------------------------------------
rTrigExecute(CLK := bExecute);
rTrigReset(CLK := bReset);

// Fault handling overriding all states
IF bAbort THEN
    iState := 99; // ABORTED
    bFault := TRUE;
    iFaultCode := 1000; // Emergency abort
END_IF;

IF rTrigReset.Q AND iState = 99 THEN
    iState := 1; // IDLE
    bFault := FALSE;
    iFaultCode := 0;
END_IF;

CASE iState OF
    0: // INIT
        bReady := FALSE;
        bActive := FALSE;
        bCmd_FirePulse := FALSE;
        fCmd_PFN_Voltage_kV := 0.0;
        fCmd_PulseFreq_Hz := 0.0;
        iState := 1; // Transition to IDLE

    1: // IDLE
        bReady := TRUE;
        bActive := FALSE;
        bCmd_FirePulse := FALSE;
        IF rTrigExecute.Q THEN
            iState := 2; // STARTING
            bReady := FALSE;
        END_IF;

    2: // STARTING
        // Establish preliminary mud flow for hydrostatic balance
        fCmd_MudDensity := 1200.0 + (fDepth_m * 0.05); // Density gradient
        fCmd_MudFlow_Lpm := 2500.0; // Base flow

        IF (fMudDensity_kg_m3 >= (fCmd_MudDensity * 0.95)) AND 
           (fMudFlowRate_Lpm >= (fCmd_MudFlow_Lpm * 0.95)) THEN
            iState := 3; // EXECUTE
        END_IF;

    3: // EXECUTE (Drilling operations)
        bActive := TRUE;

        IF bHold THEN
            iState := 4; // HOLDING
        END_IF;

        // ---------------------------------------------------------------------
        // 1. Plasma Pulse Calculation (Acoustic Match & Dielectric Breakdown)
        // ---------------------------------------------------------------------
        // Acoustic matching: adjust voltage based on impedance gap
        fAcousticMatchCoef := fRockAcousticImp / 10000.0; // Normalized
        IF fAcousticMatchCoef > 1.0 THEN fAcousticMatchCoef := 1.0; END_IF;
        IF fAcousticMatchCoef < 0.1 THEN fAcousticMatchCoef := 0.1; END_IF;

        // Calculate Required Breakdown Voltage based on mud properties and depth pressure
        // V = E * d, compensating for hydrostatic squeeze on gap distance
        fBreakdownVoltage := fMudDielectricStr * (10.0 - (fHydroPress_bar * 0.001)) * fAcousticMatchCoef;

        IF fBreakdownVoltage > c_MaxVoltage_kV THEN
            fCmd_PFN_Voltage_kV := c_MaxVoltage_kV;
        ELSE
            fCmd_PFN_Voltage_kV := fBreakdownVoltage;
        END_IF;

        // Set Pulse Frequency based on required energy
        fCmd_PulseFreq_Hz := c_MaxPulseFreq_Hz; // 10 Hz nominal

        // Timer for pulse generation
        tPulseTimer(IN := NOT tPulseTimer.Q, PT := REAL_TO_TIME(1000.0 / fCmd_PulseFreq_Hz));
        rTrigTimerFire(CLK := tPulseTimer.Q);

        IF rTrigTimerFire.Q AND bPFN_Charged AND (fPFN_Voltage_kV >= (fCmd_PFN_Voltage_kV * 0.95)) THEN
            bCmd_FirePulse := TRUE;
        ELSE
            bCmd_FirePulse := FALSE;
        END_IF;

        // ---------------------------------------------------------------------
        // 2. Supercritical Water Quench & Mud Circulation
        // ---------------------------------------------------------------------
        // If bottom hole reaches supercritical conditions, trigger quench protocol
        IF (fTempBottomHole_C > c_SupercriticalTemp) AND (fHydroPress_bar > c_SupercriticalPres) THEN
            // Supercritical influx detected: Increase flow rate aggressively to quench
            fQuenchFlowReq := 2500.0 + ((fTempBottomHole_C - c_SupercriticalTemp) * 20.0);
            fCmd_MudFlow_Lpm := fQuenchFlowReq;

            // Adjust density to maintain wellbore stability against supercritical expansion
            fCmd_MudDensity := 1500.0 + ((fHydroPress_bar - c_SupercriticalPres) * 1.5);

            // Manage annulus choke to maintain bottom hole pressure (BHP)
            bCmd_ChokeValveOpen := TRUE; // Modulate choke (simplified as binary here)
        ELSE
            // Normal operating mud parameters
            fCmd_MudFlow_Lpm := 2500.0;
            fCmd_MudDensity := 1200.0 + (fDepth_m * 0.05);
            bCmd_ChokeValveOpen := FALSE;
        END_IF;

    4: // HOLDING
        bActive := FALSE;
        bCmd_FirePulse := FALSE;
        fCmd_PFN_Voltage_kV := 0.0;

        // Maintain mud circulation for stability
        fCmd_MudFlow_Lpm := 1500.0; 

        IF NOT bHold THEN
            iState := 3; // Return to EXECUTE
        END_IF;

    99: // ABORTED (Fault State)
        bActive := FALSE;
        bReady := FALSE;
        bCmd_FirePulse := FALSE;
        fCmd_PFN_Voltage_kV := 0.0;
        fCmd_PulseFreq_Hz := 0.0;
        // Maximize mud weight and flow to kill the well and prevent blowout
        fCmd_MudDensity := 1800.0; 
        fCmd_MudFlow_Lpm := 4000.0;
        bCmd_ChokeValveOpen := FALSE; // Close choke to hold pressure

    ELSE
        iState := 0;
END_CASE;

END_FUNCTION_BLOCK
