FUNCTION_BLOCK FB_MultiSpectralOreEjector
VAR_INPUT
    (* System Signals *)
    bEnable           : BOOL;  (* System enable signal *)
    bEmergencyStop    : BOOL;  (* Safety relay OK signal (True = Safe, False = Tripped) *)
    rBeltVelocity     : REAL;  (* Main conveyor belt speed in m/s from high-speed encoder *)

    (* Sensor Arrays *)
    arNirSpectrum     : ARRAY[0..255] OF REAL; (* Near-Infrared absorption intensities *)
    rXrtDensity       : REAL;  (* X-ray transmission calculated density in g/cm^3 *)
    rParticleSize     : REAL;  (* Estimated particle diameter in mm from optical light curtain *)

    (* Process Parameters *)
    rThresholdDensity : REAL;  (* Minimum density threshold for accept/reject classification *)
    rEjectorPressure  : REAL;  (* Pneumatic manifold pressure in Bar *)
END_VAR
VAR_OUTPUT
    bSystemReady      : BOOL;  (* System ready and calibrated flag *)
    arEjectorValves   : ARRAY[0..63] OF BOOL; (* Micro-second high-speed solenoid valve bank outputs *)
    rSortingEfficiency: REAL;  (* Calculated sorting efficiency metric based on successful ejections *)
    bAlarm            : BOOL;  (* System fault or safety interlock triggered *)
    rDelayTimeMs      : REAL;  (* Computed kinematic delay before ejection in ms *)
END_VAR
VAR
    (* Internal State & Timers *)
    iState            : INT := 0; (* Internal state machine tracker *)
    tHeartbeat        : TON;      (* Health monitoring timer *)
    i                 : INT;      (* Generic loop index *)

    (* Physics & Trajectory Engine *)
    rNirScore         : REAL := 0.0; (* Computed mineralogical score from NIR spectra *)
    rParticleMass     : REAL;        (* Estimated particle mass in grams for inertial compensations *)
    rJetDuration      : REAL;        (* Calculated air jet duration in ms required to deflect mass *)
    rDistanceToJet    : REAL := 1.25;(* Physical distance from multi-sensor array to ejector manifold (meters) *)
    rTimeOfFlight     : REAL;        (* Kinematic time-of-flight from sensor to ejectors in seconds *)
    iValveTarget      : INT;         (* Calculated center-of-mass valve index to fire *)

    (* Diagnostics *)
    rTotalMassSorted  : REAL := 0.0;
    iParticlesRejected: DINT := 0;
END_VAR

(* === SAFETY AND CRITICAL INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bAlarm := TRUE;
    (* Immediately dump all air-jet firing commands for safety *)
    FOR i := 0 TO 63 DO
        arEjectorValves[i] := FALSE;
    END_FOR;
    iState := 0;
    RETURN;
END_IF;

(* Minimum operational requirements check *)
IF rEjectorPressure < 5.5 THEN
    (* Air pressure too low to guarantee inertial deflection *)
    bSystemReady := FALSE;
    bAlarm := TRUE;
    iState := 0;
ELSE
    bAlarm := FALSE;
END_IF;

(* === MAIN SORTING ENGINE LOGIC === *)
CASE iState OF
    0: (* IDLE & INITIALIZATION STATE *)
        bSystemReady := FALSE;
        FOR i := 0 TO 63 DO
            arEjectorValves[i] := FALSE;
        END_FOR;

        IF bEnable AND NOT bAlarm THEN
            iState := 10;
        END_IF;

    10: (* CALIBRATION & BELT SPEED VERIFICATION *)
        (* Ensure belt velocity is stable before proceeding to high-speed mode *)
        IF rBeltVelocity > 1.5 AND rBeltVelocity < 4.0 THEN
            bSystemReady := TRUE;
            iState := 20;
        END_IF;

    20: (* RUNNING - HIGH FREQUENCY SENSOR FUSION & KINEMATICS *)
        (* 1. Mineralogical NIR Score calculation - integrate spectral response *)
        rNirScore := 0.0;
        FOR i := 0 TO 255 DO
            rNirScore := rNirScore + arNirSpectrum[i];
        END_FOR;
        rNirScore := rNirScore / 256.0;

        (* 2. Dynamic Mass Estimation *)
        (* Particle Volume roughly proportional to Size^3, derived mass in grams *)
        rParticleMass := rParticleSize * rParticleSize * rParticleSize * rXrtDensity * 0.001;
        rTotalMassSorted := rTotalMassSorted + rParticleMass;

        (* 3. Refuse Classification Logic: Combine multi-spectral NIR and XRT density profiles *)
        IF (rXrtDensity < rThresholdDensity) AND (rNirScore > 0.45) THEN
            (* Sub-optimal gangue mineral detected -> initiate ejection sequence *)

            (* Kinematic trajectory calculation: t = d / v *)
            rTimeOfFlight := rDistanceToJet / rBeltVelocity;

            (* Convert time-of-flight to milliseconds for downstream PLC timing hardware *)
            rDelayTimeMs := rTimeOfFlight * 1000.0;

            (* Modulate jet duration based on particle mass to ensure complete deflection *)
            rJetDuration := rParticleMass * 0.125;
            IF rJetDuration > 45.0 THEN
                rJetDuration := 45.0; (* Cap pneumatic duration to prevent pressure drop *)
            ELSIF rJetDuration < 5.0 THEN
                rJetDuration := 5.0;  (* Minimum viable firing time *)
            END_IF;

            (* Centroid mapping based on optical bounds (mocked routing logic) *)
            iValveTarget := REAL_TO_INT(rParticleSize * 1.5) MOD 64;
            arEjectorValves[iValveTarget] := TRUE;

            iParticlesRejected := iParticlesRejected + 1;
        ELSE
            (* Clean ore detected, allow to pass unperturbed *)
            FOR i := 0 TO 63 DO
                arEjectorValves[i] := FALSE;
            END_FOR;
        END_IF;

        (* Compute basic real-time efficiency metrics *)
        IF rTotalMassSorted > 0.0 THEN
            rSortingEfficiency := (DINT_TO_REAL(iParticlesRejected) / rTotalMassSorted) * 100.0;
        END_IF;

        (* Safe shutdown transition check *)
        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    ELSE
        (* Fallback fault state *)
        iState := 0;

END_CASE;

END_FUNCTION_BLOCK
