Here is the Base Siemens SCL program for a Hydroelectric Dam turbine generator.

FUNCTION_BLOCK "HydroTurbine_Base"
VERSION : 0.1
   VAR_INPUT 
      start_cmd : Bool;
      stop_cmd : Bool;
      grid_voltage : Real;
      grid_freq : Real;
      gen_voltage : Real;
      gen_freq : Real;
      vibration_level : Real; // mm/s
      vibration_limit : Real := 7.0; // mm/s
      speed_setpoint : Real;
      actual_speed : Real;
   END_VAR

   VAR_OUTPUT 
      wicket_gate_pos : Real;
      breaker_close_cmd : Bool;
      alarm_vibration : Bool;
      turbine_running : Bool;
   END_VAR

   VAR 
      pid_wicket : "PID_Compact";
      sync_ok : Bool;
      vibration_timer : TON;
   END_VAR

BEGIN
    // Wicket Gate PID Control (Simplified)
    #pid_wicket(Setpoint := #speed_setpoint,
                Input := #actual_speed,
                Output => #wicket_gate_pos);

    // Bearing Vibration Monitoring
    #vibration_timer(IN := (#vibration_level > #vibration_limit), PT := T#2S);
    #alarm_vibration := #vibration_timer.Q;

    // Grid Synchronization
    IF ABS(#grid_voltage - #gen_voltage) < 5.0 AND ABS(#grid_freq - #gen_freq) < 0.1 THEN
        #sync_ok := TRUE;
    ELSE
        #sync_ok := FALSE;
    END_IF;

    // Start/Stop Logic
    IF #start_cmd AND NOT #alarm_vibration THEN
        #turbine_running := TRUE;
    ELSIF #stop_cmd OR #alarm_vibration THEN
        #turbine_running := FALSE;
    END_IF;

    // Breaker Control
    #breaker_close_cmd := #turbine_running AND #sync_ok;
END_FUNCTION_BLOCK
