FUNCTION_BLOCK FB_FlywheelEnergyStorage_MaglevControl
VAR_INPUT
    bEnableSystem          : BOOL;     (* System overall enable signal from EMS *)
    bEmergencyStop         : BOOL;     (* Safety loop status (TRUE = OK) *)
    rRotorSpeed_RPM        : REAL;     (* Flywheel rotor speed in RPM (0 to 60000) *)
    rMaglevGap_Z1          : REAL;     (* Upper magnetic bearing axial gap in mm *)
    rMaglevGap_Z2          : REAL;     (* Lower magnetic bearing axial gap in mm *)
    rChamberTemp_C         : REAL;     (* Vacuum chamber temperature in deg C *)
    rChamberPressure_mBar  : REAL;     (* Vacuum chamber pressure in mBar *)
    rGridFreq_Hz           : REAL;     (* Grid frequency for droop control reference *)
END_VAR
VAR_OUTPUT
    bSystemReady           : BOOL;     (* System is levitated, vacuum OK, ready to charge/discharge *)
    rMaglevPWM_Z1          : REAL;     (* PWM duty cycle for upper bearing coil (0-100%) *)
    rMaglevPWM_Z2          : REAL;     (* PWM duty cycle for lower bearing coil (0-100%) *)
    rMotorInverter_Cmd     : REAL;     (* Active power command to inverter (kW) *)
    bVacuumPumpCmd         : BOOL;     (* Command to engage turbomolecular vacuum pump *)
    bThermalAlarm          : BOOL;     (* Temperature or vacuum loss warning *)
    bCriticalFault         : BOOL;     (* Critical failure: drop to catcher bearings initiated *)
END_VAR
VAR
    iState                 : INT := 0; (* FSM state *)
    tLevitationTimer       : TON;
    tFaultTimer            : TON;

    (* Internal PID variables for Z1 *)
    rErrorZ1               : REAL;
    rIntZ1                 : REAL := 0.0;
    rPrevErrorZ1           : REAL := 0.0;
    rDerivZ1               : REAL;

    (* Internal PID variables for Z2 *)
    rErrorZ2               : REAL;
    rIntZ2                 : REAL := 0.0;
    rPrevErrorZ2           : REAL := 0.0;
    rDerivZ2               : REAL;

    (* Constants *)
    rTargetGapZ            : REAL := 2.5; (* Nominal gap 2.5 mm *)
    rKp_Mag                : REAL := 45.0;
    rKi_Mag                : REAL := 12.5;
    rKd_Mag                : REAL := 5.0;
    rDt                    : REAL := 0.001; (* 1ms scan cycle assumed *)

    rMaxTemp_C             : REAL := 85.0;
    rMaxPressure           : REAL := 1.0E-3; (* 0.001 mBar limit *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    iState := 999; (* FAULT STATE *)
END_IF;

(* Continuous Vacuum & Thermal Monitoring *)
IF rChamberTemp_C > rMaxTemp_C OR rChamberPressure_mBar > (rMaxPressure * 10.0) THEN
    bThermalAlarm := TRUE;
ELSE
    bThermalAlarm := FALSE;
END_IF;

IF rChamberPressure_mBar > rMaxPressure THEN
    bVacuumPumpCmd := TRUE;
ELSE
    bVacuumPumpCmd := FALSE;
END_IF;

CASE iState OF
    0: (* IDLE & SAFE *)
        bSystemReady := FALSE;
        rMaglevPWM_Z1 := 0.0;
        rMaglevPWM_Z2 := 0.0;
        rMotorInverter_Cmd := 0.0;
        bCriticalFault := FALSE;

        IF bEnableSystem AND bEmergencyStop AND NOT bThermalAlarm THEN
            iState := 10;
        END_IF;

    10: (* LEVITATION INITIATION *)
        (* Run PID for Z1 *)
        rErrorZ1 := rTargetGapZ - rMaglevGap_Z1;
        rIntZ1 := rIntZ1 + (rErrorZ1 * rDt);
        rDerivZ1 := (rErrorZ1 - rPrevErrorZ1) / rDt;
        rMaglevPWM_Z1 := (rKp_Mag * rErrorZ1) + (rKi_Mag * rIntZ1) + (rKd_Mag * rDerivZ1);
        rPrevErrorZ1 := rErrorZ1;

        (* Run PID for Z2 *)
        rErrorZ2 := rTargetGapZ - rMaglevGap_Z2;
        rIntZ2 := rIntZ2 + (rErrorZ2 * rDt);
        rDerivZ2 := (rErrorZ2 - rPrevErrorZ2) / rDt;
        rMaglevPWM_Z2 := (rKp_Mag * rErrorZ2) + (rKi_Mag * rIntZ2) + (rKd_Mag * rDerivZ2);
        rPrevErrorZ2 := rErrorZ2;

        (* Clamp PWM limits *)
        IF rMaglevPWM_Z1 > 100.0 THEN rMaglevPWM_Z1 := 100.0; END_IF;
        IF rMaglevPWM_Z1 < 0.0 THEN rMaglevPWM_Z1 := 0.0; END_IF;
        IF rMaglevPWM_Z2 > 100.0 THEN rMaglevPWM_Z2 := 100.0; END_IF;
        IF rMaglevPWM_Z2 < 0.0 THEN rMaglevPWM_Z2 := 0.0; END_IF;

        (* Check if levitation is stable *)
        IF ABS(rErrorZ1) < 0.1 AND ABS(rErrorZ2) < 0.1 THEN
            tLevitationTimer(IN := TRUE, PT := T#2S);
            IF tLevitationTimer.Q THEN
                tLevitationTimer(IN := FALSE);
                iState := 20;
            END_IF;
        ELSE
            tLevitationTimer(IN := FALSE, PT := T#2S);
        END_IF;

    20: (* RUNNING & READY TO CHARGE/DISCHARGE *)
        bSystemReady := TRUE;

        (* Continuous Levitation PID *)
        rErrorZ1 := rTargetGapZ - rMaglevGap_Z1;
        rIntZ1 := rIntZ1 + (rErrorZ1 * rDt);
        rDerivZ1 := (rErrorZ1 - rPrevErrorZ1) / rDt;
        rMaglevPWM_Z1 := (rKp_Mag * rErrorZ1) + (rKi_Mag * rIntZ1) + (rKd_Mag * rDerivZ1);
        rPrevErrorZ1 := rErrorZ1;

        rErrorZ2 := rTargetGapZ - rMaglevGap_Z2;
        rIntZ2 := rIntZ2 + (rErrorZ2 * rDt);
        rDerivZ2 := (rErrorZ2 - rPrevErrorZ2) / rDt;
        rMaglevPWM_Z2 := (rKp_Mag * rErrorZ2) + (rKi_Mag * rIntZ2) + (rKd_Mag * rDerivZ2);
        rPrevErrorZ2 := rErrorZ2;

        (* Droop control for grid frequency stabilization *)
        IF rGridFreq_Hz < 49.8 THEN
            (* Discharge / supply power *)
            rMotorInverter_Cmd := -500.0 * (49.8 - rGridFreq_Hz); 
        ELSIF rGridFreq_Hz > 50.2 THEN
            (* Charge / absorb power *)
            rMotorInverter_Cmd := 500.0 * (rGridFreq_Hz - 50.2);
        ELSE
            (* Floating, overcome friction / windage *)
            rMotorInverter_Cmd := 2.5; 
        END_IF;

        IF NOT bEnableSystem THEN
            iState := 30; (* SPINDOWN *)
        END_IF;

        (* Fault Detection *)
        IF ABS(rErrorZ1) > 0.8 OR ABS(rErrorZ2) > 0.8 THEN
            iState := 999;
        END_IF;

    30: (* SPINDOWN *)
        bSystemReady := FALSE;
        rMotorInverter_Cmd := -100.0; (* Active braking *)

        (* Keep levitation running *)
        rErrorZ1 := rTargetGapZ - rMaglevGap_Z1;
        rIntZ1 := rIntZ1 + (rErrorZ1 * rDt);
        rDerivZ1 := (rErrorZ1 - rPrevErrorZ1) / rDt;
        rMaglevPWM_Z1 := (rKp_Mag * rErrorZ1) + (rKi_Mag * rIntZ1) + (rKd_Mag * rDerivZ1);
        rPrevErrorZ1 := rErrorZ1;

        rErrorZ2 := rTargetGapZ - rMaglevGap_Z2;
        rIntZ2 := rIntZ2 + (rErrorZ2 * rDt);
        rDerivZ2 := (rErrorZ2 - rPrevErrorZ2) / rDt;
        rMaglevPWM_Z2 := (rKp_Mag * rErrorZ2) + (rKi_Mag * rIntZ2) + (rKd_Mag * rDerivZ2);
        rPrevErrorZ2 := rErrorZ2;

        IF rRotorSpeed_RPM < 10.0 THEN
            iState := 0; (* De-levitate safely *)
        END_IF;

    999: (* CRITICAL FAULT - DROP TO CATCHER BEARINGS *)
        bSystemReady := FALSE;
        bCriticalFault := TRUE;
        rMaglevPWM_Z1 := 0.0;
        rMaglevPWM_Z2 := 0.0;

        (* Emergency Eddy current braking by shorting stator if required *)
        rMotorInverter_Cmd := -1000.0; 

        tFaultTimer(IN := TRUE, PT := T#10S);
        IF tFaultTimer.Q AND bEmergencyStop AND bEnableSystem = FALSE THEN
            tFaultTimer(IN := FALSE);
            iState := 0; (* Acknowledge fault only after full stop and reset *)
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
