FUNCTION_BLOCK FB_SugarCentrifuge
VAR_INPUT
    bStartCycle : BOOL; (* Initiate automatic cycle *)
    bEmergencyStop : BOOL; (* Immediate halt *)
    rMassecuiteBrix : REAL; (* Measured Brix of massecuite *)
    rBasketSpeed_RPM : REAL; (* Actual RPM from encoder *)
    rVibrationLevel : REAL; (* Current vibration sensor reading in mm/s *)
    rWashWaterTemp : REAL; (* Wash water temperature in Celsius *)
    rPloughPos_mm : REAL; (* Plough position feedback *)
END_VAR

VAR_OUTPUT
    bSpinMotorRun : BOOL;
    rSpinMotorFreq_Hz : REAL;
    bWashValveOpen : BOOL;
    bPloughExtend : BOOL;
    bPloughRetract : BOOL;
    bDischargeGateOpen : BOOL;
    bCycleActive : BOOL;
    bFault : BOOL;
    iFaultCode : INT;
    sStateDesc : STRING(50);
END_VAR

VAR
    eState : INT; (* 0: IDLE, 1: ACCEL, 2: SPIN_WASH, 3: DECEL, 4: PLOUGH, 5: DISCHARGE, 6: FAULTED *)
    tStateTimer : TON;
    rTargetRPM : REAL;
    rDecelRampRate : REAL; (* RPM per second *)
    tWashDuration : TIME;
END_VAR

(* Implementation *)
IF bEmergencyStop THEN
    eState := 6;
    iFaultCode := 99;
END_IF;

IF rVibrationLevel > 15.0 THEN
    eState := 6;
    iFaultCode := 10;
END_IF;

CASE eState OF
    0: (* IDLE *)
        sStateDesc := 'Idle - Waiting for Start';
        bSpinMotorRun := FALSE;
        rSpinMotorFreq_Hz := 0.0;
        bWashValveOpen := FALSE;
        bPloughExtend := FALSE;
        bPloughRetract := TRUE;
        bDischargeGateOpen := FALSE;
        bCycleActive := FALSE;

        IF bStartCycle AND NOT bFault THEN
            eState := 1;
            tStateTimer(IN:=FALSE, PT:=T#0S);
        END_IF;

    1: (* ACCELERATION *)
        sStateDesc := 'Accelerating to Spin Speed';
        bCycleActive := TRUE;
        bSpinMotorRun := TRUE;

        (* Target speed depends on Massecuite Brix - heavier requires higher speed *)
        IF rMassecuiteBrix > 85.0 THEN
            rTargetRPM := 1200.0;
        ELSE
            rTargetRPM := 1050.0;
        END_IF;

        rSpinMotorFreq_Hz := (rTargetRPM / 60.0) * 1.5;

        IF rBasketSpeed_RPM >= (rTargetRPM * 0.98) THEN
            eState := 2;
            tStateTimer(IN:=FALSE, PT:=T#0S);
        END_IF;

    2: (* SPIN_WASH *)
        sStateDesc := 'Spinning and Washing';
        tStateTimer(IN:=TRUE, PT:=T#45S);

        IF rWashWaterTemp < 60.0 THEN
            tWashDuration := T#30S;
        ELSE
            tWashDuration := T#20S;
        END_IF;

        IF tStateTimer.ET >= T#5S AND tStateTimer.ET <= (T#5S + tWashDuration) THEN
            bWashValveOpen := TRUE;
        ELSE
            bWashValveOpen := FALSE;
        END_IF;

        IF tStateTimer.Q THEN
            eState := 3;
        END_IF;

    3: (* DECELERATION *)
        sStateDesc := 'Decelerating to Plough Speed';
        bWashValveOpen := FALSE;

        IF rMassecuiteBrix > 85.0 THEN
            rDecelRampRate := 10.0; 
        ELSE
            rDecelRampRate := 15.0;
        END_IF;

        rTargetRPM := 50.0;
        rSpinMotorFreq_Hz := (rTargetRPM / 60.0) * 1.5;

        IF rBasketSpeed_RPM <= 55.0 THEN
            eState := 4;
            tStateTimer(IN:=FALSE, PT:=T#0S);
        END_IF;

    4: (* PLOUGHING *)
        sStateDesc := 'Ploughing Sugar Cake';
        tStateTimer(IN:=TRUE, PT:=T#60S);

        bDischargeGateOpen := TRUE;
        bPloughRetract := FALSE;

        IF tStateTimer.ET > T#2S AND tStateTimer.ET < T#55S THEN
            bPloughExtend := TRUE;
        ELSE
            bPloughExtend := FALSE;
        END_IF;

        IF tStateTimer.Q THEN
            bPloughExtend := FALSE;
            bPloughRetract := TRUE;
            eState := 5;
            tStateTimer(IN:=FALSE, PT:=T#0S);
        END_IF;

    5: (* DISCHARGE *)
        sStateDesc := 'Final Discharge Cleanup';
        tStateTimer(IN:=TRUE, PT:=T#10S);

        IF tStateTimer.Q AND rPloughPos_mm < 5.0 THEN
            bDischargeGateOpen := FALSE;
            bSpinMotorRun := FALSE;
            bCycleActive := FALSE;
            eState := 0;
        END_IF;

    6: (* FAULTED *)
        sStateDesc := 'FAULTED - Requires Reset';
        bSpinMotorRun := FALSE;
        rSpinMotorFreq_Hz := 0.0;
        bWashValveOpen := FALSE;
        bPloughExtend := FALSE;
        bPloughRetract := TRUE;
        bDischargeGateOpen := FALSE;
        bFault := TRUE;

END_CASE;
END_FUNCTION_BLOCK
