FUNCTION_BLOCK "EAF_Control_Reasoning"
VERSION : 0.1
   VAR_INPUT 
      User_Role : Int; // 1=Operator, 2=Admin for IEC 62443
      Partner_PLC_Alive : Bool;
      Arc_Voltage : Real;
      Arc_Current : Real;
      Setpoint_Voltage : Real;
      Setpoint_Current : Real;
      Water_Temp_In : Real;
      Water_Temp_Out : Real;
      Drive_Status_Word : Word;
   END_VAR
   VAR_OUTPUT 
      Electrode_Position : Real;
      Arc_Stable : Bool;
      Cooling_Valve_Pos : Real;
      Cooling_Alarm : Bool;
      Profinet_Status : Word;
      Fault_Code : Int;
      Access_Denied : Bool;
      Active_PLC : Bool;
   END_VAR
   VAR_IN_OUT
      SCADA_Data : "SCADA_Archive_Type";
   END_VAR
   VAR 
      Kp : Real := 1.5;
      Ki : Real := 0.5;
      Error_V : Real;
      Integral_V : Real;
      Delta_T : Real;
      Heartbeat_Counter : Int;
   END_VAR

BEGIN
   // IEC 62443 Role-based Access
   IF #User_Role < 1 THEN
       #Access_Denied := TRUE;
       RETURN;
   ELSE
       #Access_Denied := FALSE;
   END_IF;

   // Failover Mechanism
   IF NOT #Partner_PLC_Alive THEN
       #Active_PLC := TRUE; // Take over
   ELSE
       #Active_PLC := FALSE; // Standby
       RETURN;
   END_IF;

   // Diagnostics
   IF (#Drive_Status_Word AND 16#0008) <> 0 THEN
