FUNCTION_BLOCK FB_DAC_Contactor_Regeneration
TITLE = 'Direct Air Capture (DAC) Plant - Complex Control Scenario'
VERSION : '1.0'
AUTHOR : 'Lumina Elite Architect'

VAR_INPUT
    bEnableSystem         : BOOL; // Master enable for the DAC train
    rInletAirVelocity     : REAL; // Measured inlet air velocity (m/s)
    rAmineFlowRate        : REAL; // Sorbent flow rate (L/min)
    rSteamTemperature     : REAL; // Stripping steam temperature (Deg C)
    rSteamPressure        : REAL; // Stripping steam pressure (Bar)
    rContactorDeltaP      : REAL; // Differential pressure across contactor (mBar)
    rCO2ConcentrationOut  : REAL; // Outlet CO2 concentration (ppm)
    rLiquefactionStage1T  : REAL; // Stage 1 Liquefaction Temp (Deg C)
    rLiquefactionStage2T  : REAL; // Stage 2 Liquefaction Temp (Deg C)
    arrAirVelocityProfile : ARRAY[1..10] OF REAL; // Velocity profile across the contactor array
END_VAR

VAR_OUTPUT
    bFanVFDEnable         : BOOL; // Enable signal for main blower VFD
    rFanVFDSpeedCmd       : REAL; // Speed command for main blower VFD (0-100%)
    bAminePumpEnable      : BOOL; // Enable signal for amine circulating pump
    rAminePumpSpeedCmd    : REAL; // Speed command for amine pump (0-100%)
    rSteamValveCmd        : REAL; // Steam flow control valve (0-100%)
    bLiquefactionEnable   : BOOL; // Enable signal for cascading liquefaction system
    rCascadingCompressorCmd: REAL; // Compressor load command (0-100%)
    bSystemFault          : BOOL; // Critical system fault active
    iFaultCode            : INT;  // Specific fault identifier
END_VAR

VAR
    // Internal States
    iState                : INT := 0; // State machine step
    rAvgVelocity          : REAL := 0.0;
    rTargetAmineFlow      : REAL := 0.0;
    rPID_Error            : REAL := 0.0;
    rPID_Integral         : REAL := 0.0;

    // Tuning Parameters
    Kp_Fan                : REAL := 2.5;
    Ki_Fan                : REAL := 0.1;

    // Limits
    rMaxVelocity          : REAL := 12.0; // m/s
    rMaxDeltaP            : REAL := 500.0; // mBar
    rMinSteamTemp         : REAL := 115.0; // Deg C
    rMaxCO2ppm            : REAL := 50.0; // ppm target

    // Iterators and timers
    i                     : INT;
    tonRegenerationTimer  : TON;
    tonLiquefactionDelay  : TON;
END_VAR

// Implementation
IF NOT bEnableSystem THEN
    iState := 0;
    bFanVFDEnable := FALSE;
    rFanVFDSpeedCmd := 0.0;
    bAminePumpEnable := FALSE;
    rAminePumpSpeedCmd := 0.0;
    rSteamValveCmd := 0.0;
    bLiquefactionEnable := FALSE;
    rCascadingCompressorCmd := 0.0;
    bSystemFault := FALSE;
    iFaultCode := 0;
    RETURN;
END_IF;

// Calculate average air velocity from array
rAvgVelocity := 0.0;
FOR i := 1 TO 10 DO
    rAvgVelocity := rAvgVelocity + arrAirVelocityProfile[i];
END_FOR;
rAvgVelocity := rAvgVelocity / 10.0;

// Safety Checks
IF rContactorDeltaP > rMaxDeltaP THEN
    bSystemFault := TRUE;
    iFaultCode := 101; // Contactor fouled or blocked
    iState := 999;
ELSIF rAvgVelocity > (rMaxVelocity * 1.1) THEN
    bSystemFault := TRUE;
    iFaultCode := 102; // Velocity over range
    iState := 999;
END_IF;

CASE iState OF
    0: // Initialization
        IF bEnableSystem AND NOT bSystemFault THEN
            iState := 10;
        END_IF;

    10: // Start Fan and Amine Circulation (Absorption Phase)
        bFanVFDEnable := TRUE;
        bAminePumpEnable := TRUE;

        // PI Control for Fan Speed based on Outlet CO2
        rPID_Error := rMaxCO2ppm - rCO2ConcentrationOut;
        rPID_Integral := rPID_Integral + (rPID_Error * 0.1); 

        IF rPID_Integral > 100.0 THEN rPID_Integral := 100.0; END_IF;
        IF rPID_Integral < -100.0 THEN rPID_Integral := -100.0; END_IF;

        rFanVFDSpeedCmd := (Kp_Fan * rPID_Error) + (Ki_Fan * rPID_Integral);

        IF rFanVFDSpeedCmd > 100.0 THEN rFanVFDSpeedCmd := 100.0; END_IF;
        IF rFanVFDSpeedCmd < 20.0 THEN rFanVFDSpeedCmd := 20.0; END_IF; 

        // Match amine flow to air volume (stoichiometric proxy)
        rTargetAmineFlow := rAvgVelocity * 15.0; 
        rAminePumpSpeedCmd := rTargetAmineFlow;

        tonRegenerationTimer(IN := TRUE, PT := T#2H);
        IF tonRegenerationTimer.Q THEN
            tonRegenerationTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: // Regeneration Phase - Steam Stripping
        bFanVFDEnable := FALSE;
        rFanVFDSpeedCmd := 0.0;

        IF rSteamTemperature < rMinSteamTemp THEN
            rSteamValveCmd := rSteamValveCmd + 1.0;
        ELSE
            rSteamValveCmd := rSteamValveCmd - 0.5;
        END_IF;

        IF rSteamValveCmd > 100.0 THEN rSteamValveCmd := 100.0; END_IF;
        IF rSteamValveCmd < 0.0 THEN rSteamValveCmd := 0.0; END_IF;

        tonRegenerationTimer(IN := TRUE, PT := T#30M);
        IF tonRegenerationTimer.Q THEN
            tonRegenerationTimer(IN := FALSE);
            rSteamValveCmd := 0.0;
            iState := 30;
        END_IF;

    30: // Liquefaction Cascading
        bLiquefactionEnable := TRUE;

        IF rLiquefactionStage1T > -20.0 THEN
            rCascadingCompressorCmd := 80.0;
        ELSIF rLiquefactionStage2T > -50.0 THEN
            rCascadingCompressorCmd := 100.0;
        ELSE
            rCascadingCompressorCmd := 40.0; 
            tonLiquefactionDelay(IN := TRUE, PT := T#10M);
            IF tonLiquefactionDelay.Q THEN
                 tonLiquefactionDelay(IN := FALSE);
                 bLiquefactionEnable := FALSE;
                 rCascadingCompressorCmd := 0.0;
                 iState := 10; 
            END_IF;
        END_IF;

    999: // Fault State
        bFanVFDEnable := FALSE;
        rFanVFDSpeedCmd := 0.0;
        bAminePumpEnable := FALSE;
        rAminePumpSpeedCmd := 0.0;
        rSteamValveCmd := 0.0;
        bLiquefactionEnable := FALSE;
        rCascadingCompressorCmd := 0.0;

        IF NOT bEnableSystem THEN
            bSystemFault := FALSE;
            iFaultCode := 0;
            iState := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
