    MAX_IMPEDANCE_OHM       : REAL := 150000.0; (* 150 kOhm max safe impedance limit *)
    MIN_IMPEDANCE_OHM       : REAL := 500.0; (* 500 Ohm min limit (indicates short circuit) *)

