    Speed_Setpoint : Real;
    PN_Status_Word : Word;
    User_Role : Int; // IEC 62443 RBAC (0: None, 1: Operator, 2: Maintenance, 3: Admin)
    Primary_Pump_OK : Bool;
END_VAR
VAR_OUTPUT
    Filler_Running : Bool;
    CIP_Active : Bool;
    Valve_Open : Bool;
    Pump1_Speed : Real;
    Pump2_Speed : Real;
    Cap_Sorter_Running : Bool;
    Cap_Sorter_Speed : Real;
    Fault_Active : Bool;
    Fault_Code : Int;
    // SCADA Interface tags
    SCADA_State : Int;
    SCADA_Diag : String[32];
END_VAR
VAR
    State : Int;
    CIP_Step : Int;
    Timer : TON;
    Drive_Fault : Bool;
    Active_Pump : Int := 1;
END_VAR

BEGIN
    // Security Check (IEC 62443)
    IF User_Role < 1 THEN
        Start := FALSE;
        CIP_Start := FALSE;
        SCADA_Diag := 'UNAUTHORIZED ACCESS';
