        Active_Pump := 2; // Automatic Failover
        SCADA_Diag := 'PUMP FAILOVER TRIGGERED';
    END_IF;

    IF Drive_Fault THEN
        State := 99; Fault_Code := 101;
    ELSIF Stop THEN
        State := 0;
    ELSIF CIP_Start AND State = 0 THEN
        State := 2;
    ELSIF Start AND State = 0 THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Idle
            Filler_Running := FALSE; CIP_Active := FALSE; Valve_Open := FALSE;
            Pump1_Speed := 0.0; Pump2_Speed := 0.0;
            Cap_Sorter_Running := FALSE; Cap_Sorter_Speed := 0.0;
            Fault_Active := FALSE; Fault_Code := 0;
            SCADA_Diag := 'IDLE';
        1: // Filling
            Filler_Running := TRUE; CIP_Active := FALSE;
            IF Active_Pump = 1 THEN Pump1_Speed := Speed_Setpoint; Pump2_Speed := 0.0;
            ELSE Pump2_Speed := Speed_Setpoint; Pump1_Speed := 0.0; END_IF;
            Valve_Open := Bottle_Present;
            IF NOT Cap_Level_Low THEN
                Cap_Sorter_Running := TRUE; Cap_Sorter_Speed := Speed_Setpoint * 1.1;
            ELSE
                State := 99; Fault_Code := 201;
            END_IF;
            SCADA_Diag := 'FILLING ACTIVE';
        2: // CIP Sequence
            Filler_Running := FALSE; CIP_Active := TRUE;
            Pump1_Speed := 50.0; Pump2_Speed := 50.0; // Both pumps run for CIP
            CASE CIP_Step OF
                0: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#5m); IF Timer.Q THEN CIP_Step:=1; Timer(IN:=FALSE, PT:=T#5m); END_IF; SCADA_Diag := 'CIP: PRE-RINSE';
                1: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#10m); IF Timer.Q THEN CIP_Step:=2; Timer(IN:=FALSE, PT:=T#10m); END_IF; SCADA_Diag := 'CIP: CAUSTIC';
                2: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#5m); IF Timer.Q THEN CIP_Step:=0; State:=0; Timer(IN:=FALSE, PT:=T#5m); END_IF; SCADA_Diag := 'CIP: FINAL RINSE';
            END_CASE;
        99: // Fault
            Filler_Running := FALSE; CIP_Active := FALSE; Valve_Open := FALSE;
            Pump1_Speed := 0.0; Pump2_Speed := 0.0;
            Cap_Sorter_Running := FALSE; Cap_Sorter_Speed := 0.0;
            Fault_Active := TRUE;
            IF NOT Drive_Fault AND Stop THEN State := 0; END_IF;
    END_CASE;
    SCADA_State := State;
END_FUNCTION_BLOCK
