FUNCTION_BLOCK FB_HVDC_Subsea_Converter_Control
TITLE = 'HVDC Subsea MMC Control and Fault Management'
VERSION : '2.1'

VAR_INPUT
    Enable_Converter : BOOL; // Master enable
    AC_Grid_Voltage_Phase_A : REAL; // kV
    AC_Grid_Voltage_Phase_B : REAL; // kV
    AC_Grid_Voltage_Phase_C : REAL; // kV
    DC_Link_Voltage : REAL; // kV
    Active_Power_Setpoint : REAL; // MW
    Reactive_Power_Setpoint : REAL; // MVAr
    SSTI_Sensor_Feedback : REAL; // Sub-synchronous oscillation frequency input (Hz)
    Line_Fault_Detected : BOOL; // DC Line fault external trigger
    Max_Arm_Current : REAL; // kA
END_VAR

VAR_OUTPUT
    IGBT_Firing_Matrix : ARRAY[0..5, 0..399] OF BOOL; // 6 arms, 400 submodules per arm
    Breaker_Trip_Cmd : BOOL;
    SSTI_Damping_Active : BOOL;
    Converter_Status_Code : INT;
    DC_Fault_Cleared : BOOL;
    Active_Power_Output : REAL;
    Reactive_Power_Output : REAL;
END_VAR

VAR
    Arm_Voltages : ARRAY[0..5] OF REAL; // Upper/Lower arm voltages A, B, C
    Submodule_Cap_Volts : ARRAY[0..5, 0..399] OF REAL; // Capacitor voltages for balancing
    i : INT;
    j : INT;
    Modulation_Index : REAL;
    SSTI_Damping_Gain : REAL := 12.5;
    Phase_Shift_Angle : REAL;
    Fault_Timer : TIME;
    State_Machine : INT := 0; 
    // 0: Standby, 1: Pre-charge, 2: Active, 3: SSTI Damping, 4: Fault Clearing, 5: Blocked
    Sort_Index : ARRAY[0..399] OF INT;
    Temp_Swap : INT;
END_VAR

// State Machine and Fault Handling
IF Line_Fault_Detected THEN
    State_Machine := 4; // Fault Clearing
    Breaker_Trip_Cmd := TRUE;
    DC_Fault_Cleared := FALSE;
    // Block all IGBTs immediately
    FOR i := 0 TO 5 DO
        FOR j := 0 TO 399 DO
            IGBT_Firing_Matrix[i, j] := FALSE;
        END_FOR;
    END_FOR;
    Converter_Status_Code := 99; // Fault Code
    RETURN;
END_IF;

CASE State_Machine OF
    0: // Standby
        Breaker_Trip_Cmd := FALSE;
        IF Enable_Converter AND (DC_Link_Voltage > 0.0) THEN
            State_Machine := 1;
        END_IF;

    1: // Pre-charge
        // Simulate pre-charging of submodules
        Converter_Status_Code := 10;
        IF DC_Link_Voltage > 300.0 THEN // Assume 300kV is threshold
            State_Machine := 2;
        END_IF;

    2: // Active Operation
        Converter_Status_Code := 20;
        Modulation_Index := Active_Power_Setpoint / (DC_Link_Voltage * 1.5);

        // SSTI Damping Check
        IF (SSTI_Sensor_Feedback > 5.0) AND (SSTI_Sensor_Feedback < 45.0) THEN
            State_Machine := 3;
        END_IF;

        // Nearest Level Control (NLC) combined with Capacitor Voltage Balancing
        // Simplified representation for the firing matrix generation
        FOR i := 0 TO 5 DO
            // Determine required inserted submodules
            Arm_Voltages[i] := (DC_Link_Voltage / 2.0) - (Modulation_Index * DC_Link_Voltage / 2.0); 

            // Dummy capacitor sorting mechanism for balancing
            FOR j := 0 TO 399 DO
                IF Submodule_Cap_Volts[i, j] < 2.0 THEN
                    IGBT_Firing_Matrix[i, j] := TRUE; // Insert
                ELSE
                    IGBT_Firing_Matrix[i, j] := FALSE; // Bypass
                END_IF;
            END_FOR;
        END_FOR;

    3: // SSTI Damping Injection
        Converter_Status_Code := 30;
        SSTI_Damping_Active := TRUE;
        // Inject counter-torque frequency modulation
        Modulation_Index := Modulation_Index + (SSTI_Damping_Gain * SSTI_Sensor_Feedback * 0.01);

        // Return to active if oscillations decay
        IF SSTI_Sensor_Feedback < 1.0 THEN
            SSTI_Damping_Active := FALSE;
            State_Machine := 2;
        END_IF;

    4: // Fault Clearing
        // Wait for line discharge, then attempt auto-reclose
        Converter_Status_Code := 40;
        IF DC_Link_Voltage < 50.0 THEN
            Breaker_Trip_Cmd := FALSE; // Reset trip
            DC_Fault_Cleared := TRUE;
            State_Machine := 0; // Go to standby
        END_IF;

    5: // Blocked
        Converter_Status_Code := 999;
        // All pulses blocked
END_CASE;

// Output assignments
Active_Power_Output := Modulation_Index * DC_Link_Voltage * 0.95; // Rough estimation
Reactive_Power_Output := Reactive_Power_Setpoint * 0.98; // Simulated loss

END_FUNCTION_BLOCK
