FUNCTION_BLOCK FB_EpiWaferReactor
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable for the epitaxial growth cycle *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (E-STOP NC contacts) *)
    rChamberPressure        : REAL;     (* Chamber vacuum pressure [Torr] *)
    rSusceptorTempZone1     : REAL;     (* Susceptor center temperature [deg C] *)
    rSusceptorTempZone2     : REAL;     (* Susceptor middle temperature [deg C] *)
    rSusceptorTempZone3     : REAL;     (* Susceptor outer temperature [deg C] *)
    rTCS_MassFlow           : REAL;     (* Trichlorosilane (TCS) mass flow rate [slm] *)
    rH2_CarrierFlow         : REAL;     (* Hydrogen carrier gas flow rate [slm] *)
    bPurgeGasValve          : BOOL;     (* N2 Purge gas valve status *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* System is initialized and ready for processing *)
    bGrowthActive           : BOOL;     (* Active epitaxial growth in progress *)
    bSafeToOpen             : BOOL;     (* Vacuum chamber safe to open (purged and at atmospheric pressure) *)
    rRFCtrlSignalZone1      : REAL;     (* RF induction coil control output for Zone 1 (0-100%) *)
    rRFCtrlSignalZone2      : REAL;     (* RF induction coil control output for Zone 2 (0-100%) *)
    rRFCtrlSignalZone3      : REAL;     (* RF induction coil control output for Zone 3 (0-100%) *)
    rTCS_ValveCommand       : REAL;     (* TCS valve control command (0-100%) *)
    bAlarm                  : BOOL;     (* Fault / alarm indicator *)
    iAlarmCode              : INT;      (* Diagnostics code *)
END_VAR
VAR
    iState                  : INT := 0; 
    tPurgeTimer             : TON;
    tGrowthTimer            : TON;

    (* Internal PID variables for susceptor zones *)
    rErrorZ1, rErrorZ2, rErrorZ3 : REAL;
    rIntegralZ1, rIntegralZ2, rIntegralZ3 : REAL;

    (* Constants *)
    rTargetTemp             : REAL := 1150.0; (* Standard epi growth temperature *)
    rTempTolerance          : REAL := 2.5;
    rKp                     : REAL := 0.45;
    rKi                     : REAL := 0.05;

    bTempStable             : BOOL;
END_VAR

(* === MAIN LOGIC === *)
(* 1. Safety Interlocks and E-Stop Evaluation *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bGrowthActive := FALSE;
    bSafeToOpen := FALSE;
    rRFCtrlSignalZone1 := 0.0;
    rRFCtrlSignalZone2 := 0.0;
    rRFCtrlSignalZone3 := 0.0;
    rTCS_ValveCommand := 0.0;
    bAlarm := TRUE;
    iAlarmCode := 999; (* Critical E-Stop / Safety Trip *)
    iState := 0;
    RETURN;
END_IF;

(* Evaluate safety for opening chamber *)
IF rChamberPressure > 750.0 AND rSusceptorTempZone1 < 60.0 AND NOT bGrowthActive AND iState = 0 THEN
    bSafeToOpen := TRUE;
ELSE
    bSafeToOpen := FALSE;
END_IF;

(* State Machine for Epitaxial Growth Process *)
CASE iState OF
    0: (* IDLE / STANDBY *)
        bSystemReady := TRUE;
        bGrowthActive := FALSE;
        rRFCtrlSignalZone1 := 0.0;
        rRFCtrlSignalZone2 := 0.0;
        rRFCtrlSignalZone3 := 0.0;
        rTCS_ValveCommand := 0.0;
        bAlarm := FALSE;
        iAlarmCode := 0;

        IF bEnable AND rChamberPressure < 10.0 THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* PRE-PURGE (N2 or H2) *)
        (* Simulating N2 purge sequence *)
        tPurgeTimer(IN := TRUE, PT := T#120S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* SUSCEPTOR HEATING & TEMPERATURE STABILIZATION *)
        (* Simple PID loop simulation for three zones *)
        rErrorZ1 := rTargetTemp - rSusceptorTempZone1;
        rIntegralZ1 := rIntegralZ1 + rErrorZ1 * 0.1; (* Simulated scan time dt = 0.1s *)
        rRFCtrlSignalZone1 := (rKp * rErrorZ1) + (rKi * rIntegralZ1);

        rErrorZ2 := rTargetTemp - rSusceptorTempZone2;
        rIntegralZ2 := rIntegralZ2 + rErrorZ2 * 0.1;
        rRFCtrlSignalZone2 := (rKp * rErrorZ2) + (rKi * rIntegralZ2);

        rErrorZ3 := rTargetTemp - rSusceptorTempZone3;
        rIntegralZ3 := rIntegralZ3 + rErrorZ3 * 0.1;
        rRFCtrlSignalZone3 := (rKp * rErrorZ3) + (rKi * rIntegralZ3);

        (* Clamp outputs *)
        IF rRFCtrlSignalZone1 > 100.0 THEN rRFCtrlSignalZone1 := 100.0; END_IF;
        IF rRFCtrlSignalZone1 < 0.0 THEN rRFCtrlSignalZone1 := 0.0; END_IF;
        IF rRFCtrlSignalZone2 > 100.0 THEN rRFCtrlSignalZone2 := 100.0; END_IF;
        IF rRFCtrlSignalZone2 < 0.0 THEN rRFCtrlSignalZone2 := 0.0; END_IF;
        IF rRFCtrlSignalZone3 > 100.0 THEN rRFCtrlSignalZone3 := 100.0; END_IF;
        IF rRFCtrlSignalZone3 < 0.0 THEN rRFCtrlSignalZone3 := 0.0; END_IF;

        bTempStable := (ABS(rErrorZ1) < rTempTolerance) AND (ABS(rErrorZ2) < rTempTolerance) AND (ABS(rErrorZ3) < rTempTolerance);

        IF bTempStable THEN
            iState := 30;
        END_IF;

    30: (* EPITAXIAL GROWTH *)
        bGrowthActive := TRUE;
        (* Temperature regulation continues *)
        rErrorZ1 := rTargetTemp - rSusceptorTempZone1;
        rIntegralZ1 := rIntegralZ1 + rErrorZ1 * 0.1; 
        rRFCtrlSignalZone1 := (rKp * rErrorZ1) + (rKi * rIntegralZ1);

        (* Cascade control loop to maintain TCS mass flow ratio to H2 *)
        rTCS_ValveCommand := rH2_CarrierFlow * 0.05; (* Ratio setpoint *)
        IF rTCS_ValveCommand > 100.0 THEN rTCS_ValveCommand := 100.0; END_IF;

        tGrowthTimer(IN := TRUE, PT := T#3600S); (* 1 hour growth cycle *)

        IF tGrowthTimer.Q OR NOT bEnable THEN
            tGrowthTimer(IN := FALSE);
            bGrowthActive := FALSE;
            rTCS_ValveCommand := 0.0; (* Shut off TCS immediately *)
            iState := 40;
        END_IF;

    40: (* POST-PURGE & COOL DOWN *)
        rRFCtrlSignalZone1 := 0.0;
        rRFCtrlSignalZone2 := 0.0;
        rRFCtrlSignalZone3 := 0.0;

        tPurgeTimer(IN := TRUE, PT := T#300S);
        IF tPurgeTimer.Q AND rSusceptorTempZone1 < 100.0 THEN
            tPurgeTimer(IN := FALSE);
            iState := 0;
        END_IF;

    ELSE
        (* Fault State *)
        bAlarm := TRUE;
        iAlarmCode := iState;
        rRFCtrlSignalZone1 := 0.0;
        rRFCtrlSignalZone2 := 0.0;
        rRFCtrlSignalZone3 := 0.0;
        rTCS_ValveCommand := 0.0;
        IF NOT bEnable THEN
            iState := 0;
        END_IF;
END_CASE;

END_FUNCTION_BLOCK
