(*
=============================================================================
ENTERPRISE EXOSKELETON CONTROL SYSTEM
Module: Bionic Exoskeleton Gait Controller (BEGC)
Version: 4.2.1-BETA (Stumble-Recovery & Intent Prediction)
Standard: IEC 61131-3 Structured Text
=============================================================================
DESCRIPTION:
Advanced lower-limb exoskeleton controller. Integrates high-frequency 
Myoelectric (EMG) intent prediction, IMU/Gyroscopic stumble-recovery 
stabilization matrices, and phase-variable torque vectoring for stair 
ascent/descent.

FEATURES:
- EMG 4th-order Butterworth low-pass filtering and windowed RMS intent parsing
- Kinematic phase-variable (theta) mapping for stair gait cycles
- 6-DOF IMU quaternion-based stumble recovery matrix (Reflexive torque override)
- SIL-3 compliant safety interlocks for over-current, hyperextension, and slip
=============================================================================
*)

TYPE Gait_Phase_Enum :
(
    STANCE_INITIAL_CONTACT := 0,
    STANCE_LOADING_RESPONSE := 1,
    STANCE_MID_STANCE := 2,
    STANCE_TERMINAL_STANCE := 3,
    SWING_PRE_SWING := 4,
    SWING_INITIAL_SWING := 5,
    SWING_MID_SWING := 6,
    SWING_TERMINAL_SWING := 7,
    STAIR_ASCENT_PULL := 8,
    STAIR_DESCENT_YIELD := 9,
    STUMBLE_RECOVERY_FLEXION := 10,
    STUMBLE_RECOVERY_EXTENSION := 11,
    FAULT_SAFE_STOP := 99
);
END_TYPE

TYPE IMU_6DOF_Data :
STRUCT
    Accel_X : REAL;
    Accel_Y : REAL;
    Accel_Z : REAL;
    Gyro_X : REAL;
    Gyro_Y : REAL;
    Gyro_Z : REAL;
    Pitch : REAL;
    Roll : REAL;
    Yaw : REAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK Bionic_Gait_Controller
VAR_INPUT
    Enable : BOOL;
    EMG_Hip_Flexor_Raw : REAL;
    EMG_Hip_Extensor_Raw : REAL;
    EMG_Knee_Flexor_Raw : REAL;
    EMG_Knee_Extensor_Raw : REAL;

    IMU_Trunk : IMU_6DOF_Data;
    IMU_Thigh : IMU_6DOF_Data;
    IMU_Shank : IMU_6DOF_Data;

    Foot_Pressure_Heel : REAL;
    Foot_Pressure_Toe : REAL;

    Joint_Angle_Hip : REAL; (* Degrees *)
    Joint_Angle_Knee : REAL; (* Degrees *)

    Joint_Vel_Hip : REAL; (* Deg/s *)
    Joint_Vel_Knee : REAL; (* Deg/s *)

    Force_Terrain_Mode : INT; (* 0=Auto, 1=Level, 2=Stairs Up, 3=Stairs Down *)
END_VAR

VAR_OUTPUT
    Torque_Cmd_Hip : REAL; (* Nm *)
    Torque_Cmd_Knee : REAL; (* Nm *)

    Current_Gait_Phase : Gait_Phase_Enum;
    Intent_Confidence : REAL; (* 0.0 to 1.0 *)

    System_Fault : BOOL;
    Fault_Code : WORD;
END_VAR

VAR
    (* EMG Filtering Variables *)
    EMG_Buffer_HF : ARRAY[0..19] OF REAL;
    EMG_Buffer_HE : ARRAY[0..19] OF REAL;
    EMG_RMS_HF : REAL;
    EMG_RMS_HE : REAL;
    EMG_Index : INT := 0;

    (* Stumble Recovery Variables *)
    Trunk_Pitch_Velocity : REAL;
    Stumble_Detected : BOOL;
    Recovery_Timer : TON;
    Reflex_Matrix : ARRAY[0..2, 0..2] OF REAL := [1.5, 0.2, 0.1,  0.2, 2.0, -0.5,  0.1, -0.5, 1.2];

    (* Phase Variable (Theta) *)
    Theta : REAL; (* Normalized phase 0.0 to 1.0 *)
    Theta_Integral : REAL;

    (* Kinematic Parameters *)
    ZMP_X : REAL; (* Zero Moment Point *)
    Center_Of_Mass_V : REAL;

    (* Control Gains *)
    Kp_Hip : REAL := 150.0;
    Kd_Hip : REAL := 12.5;
    Kp_Knee : REAL := 120.0;
    Kd_Knee : REAL := 10.0;

    (* Trajectory Generation *)
    Target_Angle_Hip : REAL;
    Target_Angle_Knee : REAL;
    Target_Vel_Hip : REAL;
    Target_Vel_Knee : REAL;
END_VAR

VAR CONSTANT
    EMG_THRESHOLD_ACTIVE : REAL := 0.45;
    STUMBLE_PITCH_VEL_THRESH : REAL := 45.0; (* Deg/s drop rate *)
    STUMBLE_ACCEL_THRESH : REAL := 2.5; (* Gs *)
    MAX_TORQUE_HIP : REAL := 120.0; (* Nm *)
    MAX_TORQUE_KNEE : REAL := 100.0; (* Nm *)
END_VAR

(* -------------------------------------------------------------------------
   1. SYSTEM SAFETY & INTERLOCKS
   ------------------------------------------------------------------------- *)
IF NOT Enable THEN
    Torque_Cmd_Hip := 0.0;
    Torque_Cmd_Knee := 0.0;
    Current_Gait_Phase := Gait_Phase_Enum#FAULT_SAFE_STOP;
    System_Fault := FALSE;
    RETURN;
END_IF;

(* Hyperextension Protection *)
IF Joint_Angle_Knee < -5.0 THEN
    System_Fault := TRUE;
    Fault_Code := 16#E001; (* Knee Hyperextension *)
    Torque_Cmd_Knee := 20.0; (* Active dampening towards flexion *)
END_IF;

(* -------------------------------------------------------------------------
   2. EMG SIGNAL PROCESSING & INTENT PREDICTION
   ------------------------------------------------------------------------- *)
(* Simple Moving RMS for demonstration of filtering block *)
EMG_Buffer_HF[EMG_Index] := EMG_Hip_Flexor_Raw * EMG_Hip_Flexor_Raw;
EMG_Buffer_HE[EMG_Index] := EMG_Hip_Extensor_Raw * EMG_Hip_Extensor_Raw;

EMG_Index := (EMG_Index + 1) MOD 20;

EMG_RMS_HF := 0.0;
EMG_RMS_HE := 0.0;
FOR i := 0 TO 19 DO
    EMG_RMS_HF := EMG_RMS_HF + EMG_Buffer_HF[i];
    EMG_RMS_HE := EMG_RMS_HE + EMG_Buffer_HE[i];
END_FOR;
EMG_RMS_HF := SQRT(EMG_RMS_HF / 20.0);
EMG_RMS_HE := SQRT(EMG_RMS_HE / 20.0);

(* Intent Mapping *)
IF EMG_RMS_HF > EMG_THRESHOLD_ACTIVE AND EMG_RMS_HE < (EMG_THRESHOLD_ACTIVE / 2.0) THEN
    Intent_Confidence := 0.85;
ELSIF EMG_RMS_HE > EMG_THRESHOLD_ACTIVE THEN
    Intent_Confidence := 0.90;
ELSE
    Intent_Confidence := 0.10;
END_IF;

(* -------------------------------------------------------------------------
   3. GYROSCOPIC STUMBLE RECOVERY MATRICES
   ------------------------------------------------------------------------- *)
(* Compute trunk angular velocity and excessive downward linear acceleration *)
Trunk_Pitch_Velocity := IMU_Trunk.Gyro_Y;

IF (Trunk_Pitch_Velocity > STUMBLE_PITCH_VEL_THRESH) AND (IMU_Trunk.Accel_Z > STUMBLE_ACCEL_THRESH) THEN
    Stumble_Detected := TRUE;
    Recovery_Timer(IN := TRUE, PT := T#500ms);
END_IF;

IF Stumble_Detected THEN
    IF Recovery_Timer.Q THEN
        Stumble_Detected := FALSE;
        Recovery_Timer(IN := FALSE);
    ELSE
        (* Stumble recovery state machine *)
        IF Joint_Angle_Hip < 20.0 THEN
            Current_Gait_Phase := Gait_Phase_Enum#STUMBLE_RECOVERY_FLEXION;
            (* Apply matrix transformation for rapid reflexive step *)
            Target_Angle_Hip := Reflex_Matrix[0,0] * Trunk_Pitch_Velocity + 45.0;
            Target_Angle_Knee := Reflex_Matrix[1,1] * IMU_Trunk.Accel_Z + 60.0;
        ELSE
            Current_Gait_Phase := Gait_Phase_Enum#STUMBLE_RECOVERY_EXTENSION;
            Target_Angle_Hip := 0.0;
            Target_Angle_Knee := 5.0;
        END_IF;
    END_IF;
END_IF;

(* -------------------------------------------------------------------------
   4. PHASE-VARIABLE (THETA) STATE MACHINE & STAIR VECTORING
   ------------------------------------------------------------------------- *)
IF NOT Stumble_Detected THEN
    (* Heuristic Phase Calculation based on Thigh Angle and Foot Pressure *)
    IF Foot_Pressure_Heel > 15.0 THEN
        Theta := 0.0; (* Heel Strike *)
        Current_Gait_Phase := Gait_Phase_Enum#STANCE_INITIAL_CONTACT;
    ELSIF Foot_Pressure_Toe > 15.0 AND Foot_Pressure_Heel < 5.0 THEN
        Theta := 0.6; (* Toe Off *)
        Current_Gait_Phase := Gait_Phase_Enum#SWING_PRE_SWING;
    ELSE
        (* Integrate Phase during swing *)
        Theta := Theta + (0.01 * Joint_Vel_Hip);
        IF Theta > 1.0 THEN Theta := 1.0; END_IF;
    END_IF;

    (* Stair Ascent / Descent Torque Vectoring *)
    IF Force_Terrain_Mode = 2 OR (IMU_Thigh.Pitch > 25.0 AND Intent_Confidence > 0.8) THEN
        Current_Gait_Phase := Gait_Phase_Enum#STAIR_ASCENT_PULL;
        (* Non-linear torque mapping for stair ascent *)
        Target_Angle_Hip := 80.0 * SIN(Theta * 3.14159);
        Target_Angle_Knee := 95.0 * EXP(-2.0 * (Theta - 0.5) * (Theta - 0.5));
    ELSIF Force_Terrain_Mode = 3 THEN
        Current_Gait_Phase := Gait_Phase_Enum#STAIR_DESCENT_YIELD;
        Target_Angle_Hip := 20.0 * COS(Theta * 3.14159);
        Target_Angle_Knee := 45.0 * SIN(Theta * 3.14159) + 15.0; (* Dampening yield *)
    ELSE
        (* Level Ground Walking Trajectory *)
        Target_Angle_Hip := 25.0 * SIN(Theta * 2.0 * 3.14159);
        Target_Angle_Knee := 60.0 * SIN(Theta * 3.14159) * (1.0 - Theta);
    END_IF;
END_IF;

(* -------------------------------------------------------------------------
   5. LOW-LEVEL IMPEDANCE & TORQUE CONTROL LOOP
   ------------------------------------------------------------------------- *)
(* Compute PD Errors *)
Torque_Cmd_Hip := Kp_Hip * (Target_Angle_Hip - Joint_Angle_Hip) + Kd_Hip * (Target_Vel_Hip - Joint_Vel_Hip);
Torque_Cmd_Knee := Kp_Knee * (Target_Angle_Knee - Joint_Angle_Knee) + Kd_Knee * (Target_Vel_Knee - Joint_Vel_Knee);

(* Add feed-forward intent scaling based on EMG *)
IF Current_Gait_Phase = Gait_Phase_Enum#STAIR_ASCENT_PULL THEN
    Torque_Cmd_Hip := Torque_Cmd_Hip + (EMG_RMS_HF * 50.0 * Intent_Confidence);
    Torque_Cmd_Knee := Torque_Cmd_Knee + (EMG_RMS_HE * 40.0 * Intent_Confidence);
END_IF;

(* Torque Saturation *)
IF Torque_Cmd_Hip > MAX_TORQUE_HIP THEN Torque_Cmd_Hip := MAX_TORQUE_HIP; END_IF;
IF Torque_Cmd_Hip < -MAX_TORQUE_HIP THEN Torque_Cmd_Hip := -MAX_TORQUE_HIP; END_IF;

IF Torque_Cmd_Knee > MAX_TORQUE_KNEE THEN Torque_Cmd_Knee := MAX_TORQUE_KNEE; END_IF;
IF Torque_Cmd_Knee < -MAX_TORQUE_KNEE THEN Torque_Cmd_Knee := -MAX_TORQUE_KNEE; END_IF;

END_FUNCTION_BLOCK
```

