FUNCTION_BLOCK FB_WEC_PointAbsorber_PTO_Control
VAR_INPUT
    (* System & Safety Interlocks *)
    bEnable                : BOOL;     (* System master enable signal from SCADA *)
    bEmergencyStop         : BOOL;     (* Hardware safety loop OK (Active High) *)
    bGridConnected         : BOOL;     (* Main AC Grid synchronization status *)

    (* Metocean & Hydrodynamic Telemetry *)
    rHeavePosition         : REAL;     (* Buoy heave position relative to mean sea level [m] *)
    rHeaveVelocity         : REAL;     (* Buoy vertical velocity [m/s] *)
    rWaveSwellPeriod       : REAL;     (* Estimated peak swell period from wave radar/FFT [s] *)
    rSignificantWaveHeight : REAL;     (* Significant wave height (Hs) [m] *)

    (* Structural & Mooring Feedback *)
    rMooringTensionFwd     : REAL;     (* Forward structural mooring line tension [kN] *)
    rMooringTensionAft     : REAL;     (* Aft structural mooring line tension [kN] *)
END_VAR

VAR_OUTPUT
    (* System Status & Alarms *)
    bSystemReady           : BOOL;     (* System ready for PTO engagement *)
    bAlarm                 : BOOL;     (* Critical fault active, requires reset *)
    bStormSurvivalMode     : BOOL;     (* Active when Hs exceeds survival threshold - buoy submerged *)

    (* Control Actuation *)
    rPTODampingCmd         : REAL;     (* Hydraulic PTO damping coefficient command [N.s/m] *)
    bLatchEngage           : BOOL;     (* Engage mechanical latch/brake for resonance tuning *)
    rMooringTensionCmd     : REAL;     (* Active multi-point mooring winch tensioning bias [kN] *)
END_VAR

VAR
    (* Internal State & Timers *)
    iState                 : INT := 0; 
    tSurvivalTimer         : TON;
    tLatchHoldTimer        : TON;
    tStartupDelay          : TON;

    (* Internal Calculation Variables *)
    rNaturalPeriod         : REAL := 6.5; (* Buoy hydrodynamic natural period [s] *)
    rLatchDuration         : REAL;        (* Calculated latch time to achieve phase matching [s] *)
    rVelocityThreshold     : REAL := 0.1; (* Deadband for zero-velocity detection [m/s] *)
    rMaxTensionLimit       : REAL := 1500.0; (* Ultimate limit state for mooring tension [kN] *)
    rSurvivalHsLimit       : REAL := 8.5; (* Wave height limit to trigger survival mode [m] *)

    (* Flags *)
    bVelocityZeroCross     : BOOL;
    bPhaseMatchRequired    : BOOL;
END_VAR

(* === MAIN CRITICAL SAFETY & INTERLOCK LOGIC === *)
(* Evaluate safety chains before processing standard hydrodynamics *)
IF NOT bEmergencyStop THEN
    bSystemReady       := FALSE;
    bAlarm             := TRUE;
    bLatchEngage       := TRUE;   (* Fail-safe: brake engaged during E-Stop *)
    rPTODampingCmd     := 100000.0; (* Max damping to prevent catastrophic over-stroking *)
    rMooringTensionCmd := 500.0;  (* Nominal holding tension *)
    iState             := 99;     (* Fault state *)
    RETURN;
END_IF;

(* Evaluate ultimate structural limits - Mooring line overload detection *)
IF (rMooringTensionFwd > rMaxTensionLimit) OR (rMooringTensionAft > rMaxTensionLimit) THEN
    bAlarm := TRUE;
    iState := 99; (* Enter fault state to protect structural integrity *)
END_IF;

(* === PRIMARY CONTROL STATE MACHINE === *)
CASE iState OF
    0: (* IDLE & SYSTEM CHECKS *)
        bSystemReady       := FALSE;
        bAlarm             := FALSE;
        bStormSurvivalMode := FALSE;
        rPTODampingCmd     := 50000.0; (* Idle damping *)
        bLatchEngage       := TRUE;    (* Hold position *)

        IF bEnable AND bEmergencyStop AND bGridConnected THEN
            tStartupDelay(IN := TRUE, PT := T#3S);
            IF tStartupDelay.Q THEN
                tStartupDelay(IN := FALSE);
                iState := 10;
            END_IF;
        ELSE
            tStartupDelay(IN := FALSE);
        END_IF;

    10: (* ACTIVE WAVE ENERGY CONVERSION - RUNNING *)
        bSystemReady := TRUE;

        (* Check for extreme weather transition *)
        IF rSignificantWaveHeight >= rSurvivalHsLimit THEN
            iState := 30; (* Go to Storm Survival Mode *)
        END_IF;

        (* Phase Latching Control - Discrete Latching for Resonance Tuning *)
        (* If swell period is significantly larger than buoy natural period, 
           latch at extreme amplitudes to phase-match excitation force. *)
        bPhaseMatchRequired := (rWaveSwellPeriod > (rNaturalPeriod * 1.2));

        (* Zero-crossing detection on velocity indicates extrema (peak/trough) *)
        bVelocityZeroCross := (ABS(rHeaveVelocity) < rVelocityThreshold);

        IF bPhaseMatchRequired AND bVelocityZeroCross THEN
            (* Calculate latch duration: (Tw - Tn) / 2 *)
            rLatchDuration := (rWaveSwellPeriod - rNaturalPeriod) / 2.0;

            (* Convert calculated REAL seconds to TIME format for timer *)
            tLatchHoldTimer(IN := TRUE, PT := REAL_TO_TIME(rLatchDuration * 1000.0));

            bLatchEngage := TRUE;
            rPTODampingCmd := 0.0; (* Unload PTO while latched *)

            IF tLatchHoldTimer.Q THEN
                (* Release latch to catch the wave velocity peak *)
                tLatchHoldTimer(IN := FALSE);
                bLatchEngage := FALSE;
            END_IF;
        ELSE
            (* Continuous damping mode for Coulomb/Viscous energy extraction *)
            bLatchEngage := FALSE;
            tLatchHoldTimer(IN := FALSE);
            (* Dynamic PTO damping scaled by wave height for optimal efficiency *)
            rPTODampingCmd := 25000.0 * rSignificantWaveHeight;
        END_IF;

        (* Active multi-point mooring bias to counteract drift forces *)
        rMooringTensionCmd := 750.0 + (rSignificantWaveHeight * 50.0);

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* STORM SURVIVAL MODE *)
        bStormSurvivalMode := TRUE;
        bLatchEngage       := FALSE;  (* Do not lock mechanically, let hydraulic PTO damp *)
        rPTODampingCmd     := 90000.0; (* Extreme damping to act as hydraulic lock / heavy viscous drag *)

        (* Winch down moorings to submerge point absorber beneath violent surface waves *)
        rMooringTensionCmd := 1200.0; 

        (* Timer to debounce return to normal operation when seas calm down *)
        tSurvivalTimer(IN := (rSignificantWaveHeight < (rSurvivalHsLimit - 1.5)), PT := T#600S);

        IF tSurvivalTimer.Q THEN
            tSurvivalTimer(IN := FALSE);
            bStormSurvivalMode := FALSE;
            iState := 10;
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        bLatchEngage := TRUE;
        rPTODampingCmd := 100000.0;

        (* Requires explicit disable and re-enable to clear fault *)
        IF NOT bEnable AND NOT bEmergencyStop THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
```

