FUNCTION_BLOCK FB_WaferStepper_UV
TITLE = 'Wafer Stepper Control with UV Dose'
VERSION : '1.1'

VAR_INPUT
    Enable : BOOL; 
    StagePosRef : REAL; 
    FocusPitchRef : REAL; 
    InterferometerFb : REAL; 
    FocusPitchFb : REAL; 
    TargetUVDose : REAL; // Target UV Dose (mJ/cm2)
    UVIntensityFb : REAL; // Current UV Intensity (mW/cm2)
    Kp_Stage, Ki_Stage : REAL;
    Kp_Focus, Ki_Focus : REAL;
    Clock_1ms : BOOL; // 1ms pulse for integration
END_VAR

VAR_OUTPUT
    StageDriveCmd : REAL; 
    FocusActuatorCmd : REAL; 
    UvShutterOpenCmd : BOOL;
    ExposureComplete : BOOL;
    InPosition : BOOL;
    InFocus : BOOL;
END_VAR

VAR
    StageError, StageErrorInt : REAL;
    FocusError, FocusErrorInt : REAL;
    AccumulatedDose : REAL;
    ExposureActive : BOOL;
    ClockPulse_R_TRIG : BOOL;
    ClockPulse_M : BOOL;
END_VAR

CONST
    TOLERANCE_POS : REAL := 5.0; 
    TOLERANCE_FOCUS : REAL := 1.0; 
END_CONST

BEGIN
    // Edge detection for 1ms clock
    ClockPulse_R_TRIG := Clock_1ms AND NOT ClockPulse_M;
    ClockPulse_M := Clock_1ms;

    IF NOT Enable THEN
        StageDriveCmd := 0.0;
        FocusActuatorCmd := 0.0;
        UvShutterOpenCmd := FALSE;
        ExposureComplete := FALSE;
        ExposureActive := FALSE;
        AccumulatedDose := 0.0;
        StageErrorInt := 0.0;
        FocusErrorInt := 0.0;
        RETURN;
    END_IF;

    // Stage & Focus Control
    StageError := StagePosRef - InterferometerFb;
    StageErrorInt := StageErrorInt + StageError;
    StageDriveCmd := (Kp_Stage * StageError) + (Ki_Stage * StageErrorInt);

    FocusError := FocusPitchRef - FocusPitchFb;
    FocusErrorInt := FocusErrorInt + FocusError;
    FocusActuatorCmd := (Kp_Focus * FocusError) + (Ki_Focus * FocusErrorInt);

    InPosition := ABS(StageError) <= TOLERANCE_POS;
    InFocus := ABS(FocusError) <= TOLERANCE_FOCUS;

    // UV Dose and Exposure Control
    IF InPosition AND InFocus AND NOT ExposureComplete THEN
        ExposureActive := TRUE;
        UvShutterOpenCmd := TRUE;
    ELSE
        ExposureActive := FALSE;
        UvShutterOpenCmd := FALSE;
    END_IF;

    IF ExposureActive AND ClockPulse_R_TRIG THEN
        // Accumulate dose (Intensity in mW/cm2 * 1ms = mJ/cm2 / 1000)
        AccumulatedDose := AccumulatedDose + (UVIntensityFb * 0.001);
        IF AccumulatedDose >= TargetUVDose THEN
            ExposureComplete := TRUE;
            UvShutterOpenCmd := FALSE;
            ExposureActive := FALSE;
        END_IF;
    END_IF;

    IF NOT (InPosition AND InFocus) THEN
        // Reset exposure logic if alignment is lost
        AccumulatedDose := 0.0;
        ExposureComplete := FALSE;
    END_IF;

END_FUNCTION_BLOCK
