VAR
    // Internal State Machine
    eState               : INT; // 0: IDLE, 10: INIT, 20: HEATING, 30: DIGESTING, 40: FLASHING, 50: SETTLING, 99: FAULT

    // NaOH Calculation Variables
    rReqNaOH_Mass        : REAL;
    rSilicaPenalty       : REAL; // Extra NaOH required due to DSP (Desilication Product) formation

    // PID Controllers
    fbTempPID            : PID_CONTROLLER;
    fbPressPID           : PID_CONTROLLER;
    fbFlocculantPID      : PID_CONTROLLER;

    // Heat Recovery Sequencing
    tFlashStageTimer     : TON;
    iFlashStageIndex     : INT;

    // Filters & Rates
    rFilteredDensity     : REAL;
    rDensityAlpha        : REAL := 0.2; 
END_VAR

//=============================================================================
// Constants & Defines
//=============================================================================
CONST
    MAX_PRESSURE      : REAL := 45.0; // MAWP for Digester
    NOMINAL_TEMP      : REAL := 250.0; // Target temperature for Gibbsitic/Boehmitic bauxite mix
    SILICA_DSP_FACTOR : REAL := 1.25; // kg of NaOH lost per kg of reactive silica
END_CONST

//=============================================================================
// Main Logic
//=============================================================================
IF bEmergencyStop THEN
    eState := 99;
    wErrorCode := 16#FFFF;
END_IF;

CASE eState OF
    0: // IDLE
        rNaOH_ValveCmd := 0.0;
        rSteamValveCmd := 0.0;
        rBlowOffValveCmd := 0.0;
        rFlocculantPumpSpeed := 0.0;
        bFlashTank1_Valve := FALSE;
        bFlashTank2_Valve := FALSE;
        bFlashTank3_Valve := FALSE;
        bHeatRecoveryActive := FALSE;

        IF bEnableSys AND NOT bEmergencyStop THEN
            eState := 10;
        END_IF;

    10: // INIT & NaOH DOSING CALCULATION
        // Matrix: High-pressure caustic soda concentration based on silica
        // For every 1% of silica, extra NaOH is consumed to form DSP.
        IF rSilicaContent > 5.0 THEN
            bHighSilicaAlarm := TRUE;
            rSilicaPenalty := rSilicaContent * SILICA_DSP_FACTOR * 1.5; // Non-linear penalty at high silica
        ELSE
            bHighSilicaAlarm := FALSE;
            rSilicaPenalty := rSilicaContent * SILICA_DSP_FACTOR;
        END_IF;

        // Feedforward calculation for Caustic Addition
        // Base Requirement + DSP Penalty
        rReqNaOH_Mass := (rBauxiteFeedRate * rTargetAO_Ratio) + rSilicaPenalty;

        // Simple PI control for dosing valve (Simulated via feedforward mapping)
        IF rCausticFlowRate < rReqNaOH_Mass THEN
            rNaOH_ValveCmd := MIN(rNaOH_ValveCmd + 0.5, 100.0);
        ELSE
            rNaOH_ValveCmd := MAX(rNaOH_ValveCmd - 0.5, 0.0);
        END_IF;

        IF rDigesterPress < 5.0 THEN // Pre-pressurized
            eState := 20;
        END_IF;

    20: // HEATING & PRESSURIZATION
        fbTempPID(
            ACT := rDigesterTemp,
            SET := NOMINAL_TEMP,
            KP := 2.5,
            KI := 0.05,
            KD := 0.1,
            EN := TRUE,
            OUT => rSteamValveCmd
        );

        IF (rDigesterTemp >= (NOMINAL_TEMP - 5.0)) AND (rDigesterPress >= 35.0) THEN
            eState := 30;
        END_IF;

    30: // DIGESTING (40 BAR MAINTAIN)
        bDigesterReady := TRUE;

        // Digester Pressure Override Control
        fbPressPID(
            ACT := rDigesterPress,
            SET := rTargetPressure,
            KP := 5.0,
            KI := 0.1,
            KD := 0.0,
            EN := TRUE,
            OUT => rBlowOffValveCmd
        );

        IF rDigesterPress > MAX_PRESSURE THEN
            bHighPressAlarm := TRUE;
            eState := 99; // Trip
            wErrorCode := 16#P001; // Overpressure Trip
        ELSE
            bHighPressAlarm := FALSE;
        END_IF;

        // Transition to Heat Recovery when batch/continuous plug flows down
        IF rDigesterTemp >= NOMINAL_TEMP THEN 
            eState := 40;
        END_IF;

    40: // FLASH TANK CASCADE HEAT RECOVERY SEQUENCING
        bHeatRecoveryActive := TRUE;
        tFlashStageTimer(IN := TRUE, PT := T#30S);

        // Sequencer for sequential cascading pressure let-down
        CASE iFlashStageIndex OF
            0: 
                bFlashTank1_Valve := TRUE; // Highest pressure flash
                IF tFlashStageTimer.Q AND rHeater1_VaporPress > 20.0 THEN
                    tFlashStageTimer(IN := FALSE);
                    iFlashStageIndex := 1;
                END_IF;
            1:
                bFlashTank2_Valve := TRUE; // Medium pressure flash
                IF tFlashStageTimer.Q AND rHeater2_VaporPress > 10.0 THEN
                    tFlashStageTimer(IN := FALSE);
                    iFlashStageIndex := 2;
                END_IF;
            2:
                bFlashTank3_Valve := TRUE; // Low pressure flash (Atmospheric)
                IF tFlashStageTimer.Q AND rHeater3_VaporPress > 1.5 THEN
                    tFlashStageTimer(IN := FALSE);
                    iFlashStageIndex := 3;
                END_IF;
            3:
                eState := 50; // Proceed to Settling
        END_CASE;

    50: // RED MUD SETTLING FLOCCULANT DOSING
        // Low-pass filter for mud density
        rFilteredDensity := (rDensityAlpha * rMudDensity) + ((1.0 - rDensityAlpha) * rFilteredDensity);

        // Cascade control: Maintain clear liquor interface by dosing flocculant
        // Higher density or rising interface needs more flocculant to increase settling rate
        fbFlocculantPID(
            ACT := rSettlingInterface,
            SET := 2.5, // Target interface level (m)
            KP := 1.2,
            KI := 0.02,
            KD := 0.0,
            EN := TRUE,
            OUT => rFlocculantPumpSpeed
        );

        // Density Override: If mud is too dense, rake might trip; reduce flocculant temporarily
        IF rFilteredDensity > 1400.0 THEN 
            rFlocculantPumpSpeed := rFlocculantPumpSpeed * 0.5;
        END_IF;

    99: // FAULT
        rSteamValveCmd := 0.0;
        rNaOH_ValveCmd := 0.0;
        rFlocculantPumpSpeed := 0.0;
        bFlashTank1_Valve := FALSE;
        bFlashTank2_Valve := FALSE;
        bFlashTank3_Valve := FALSE;

        IF NOT bEmergencyStop AND NOT bHighPressAlarm THEN // Reset condition
            eState := 0;
            wErrorCode := 0;
            iFlashStageIndex := 0;
        END_IF;

END_CASE;
END_FUNCTION_BLOCK
```

