FUNCTION_BLOCK FB_IonThruster_GridAlignment
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable            : BOOL;     (* System enable signal for alignment sequence *)
    bEmergencyStop     : BOOL;     (* Safety relay OK signal (FALSE = STOP) *)
    rScreenGridTemp    : REAL;     (* Screen grid measured temperature in Kelvin *)
    rAccelGridTemp     : REAL;     (* Accelerator grid measured temperature in Kelvin *)
    rGapDistanceUm     : REAL;     (* Measured gap distance via laser interferometer (um) *)
    rBeamDivergence    : REAL;     (* Measured beam divergence angle focal vector (mrad) *)
    bHighVoltageActive : BOOL;     (* Status of High-Voltage power supply (Screen/Accel) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady       : BOOL;     (* System ready status for HV ignition *)
    rControlOutput     : REAL;     (* Control signal to piezoelectric actuator (um) *)
    bAlarm             : BOOL;     (* Fault alarm output (thermal, out-of-bounds, etc.) *)
    rThermalDelta      : REAL;     (* Calculated differential thermal expansion (um) *)
    iActiveState       : INT;      (* Current alignment state machine active step *)
END_VAR
VAR
    (* Internal state variables and function blocks *)
    iState             : INT := 0;
    tAlignTimer        : TON;
    tSettleTimer       : TON;

    (* Filtering and PID variables *)
    rFilteredGap       : REAL := 0.0;
    rAlphaEMA          : REAL := 0.15; (* Exponential Moving Average weight *)
    rTargetGapUm       : REAL := 850.0; (* Nominal gap target 850 micrometers *)

    (* Control loop variables *)
    rError             : REAL := 0.0;
    rIntegral          : REAL := 0.0;
    rDerivative        : REAL := 0.0;
    rLastError         : REAL := 0.0;
    rKp                : REAL := 0.45;
    rKi                : REAL := 0.02;
    rKd                : REAL := 0.10;

    (* Thermal expansion constants (Molybdenum grids) *)
    rMo_CTE            : REAL := 4.8E-6; (* Coeff of thermal expansion 1/K *)
    rGridRadius        : REAL := 150.0; (* Grid radius in mm *)
END_VAR

(* === MULTI-LAYERED SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    rControlOutput := 0.0;
    bAlarm := TRUE;
    iState := 99; (* Force fault state *)
    RETURN;
END_IF;

IF rScreenGridTemp > 1200.0 OR rAccelGridTemp > 1200.0 THEN
    bAlarm := TRUE;
    bSystemReady := FALSE;
    iState := 99;
    RETURN;
END_IF;

(* === SENSOR NOISE FILTERING === *)
(* Implement Exponential Moving Average (EMA) to smooth laser interferometer readings *)
rFilteredGap := (rAlphaEMA * rGapDistanceUm) + ((1.0 - rAlphaEMA) * rFilteredGap);

(* === DIFFERENTIAL THERMAL EXPANSION COMPENSATION === *)
(* Calculate thermal growth delta between screen and accelerator grids *)
rThermalDelta := (rScreenGridTemp - rAccelGridTemp) * rMo_CTE * rGridRadius * 1000.0; (* Result in um *)

(* Adjust target gap dynamically based on thermal deflection to maintain beam divergence *)
rTargetGapUm := 850.0 + rThermalDelta - (rBeamDivergence * 2.5);

(* === MAIN LOGIC STATE MACHINE === *)
CASE iState OF
    0: (* IDLE *)
        bSystemReady := FALSE;
        rControlOutput := 0.0;
        bAlarm := FALSE;
        IF bEnable THEN
            iState := 10;
        END_IF;

    10: (* INITIAL CALIBRATION AND THERMAL SOAK *)
        tAlignTimer(IN := TRUE, PT := T#15S);
        IF tAlignTimer.Q THEN
            tAlignTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* ACTIVE SPACING & BEAM FOCAL VECTORING (PID CONTROL) *)
        rError := rTargetGapUm - rFilteredGap;
        rIntegral := rIntegral + rError;

        (* Anti-windup limit for integral term *)
        IF rIntegral > 500.0 THEN rIntegral := 500.0; END_IF;
        IF rIntegral < -500.0 THEN rIntegral := -500.0; END_IF;

        rDerivative := rError - rLastError;
        rLastError := rError;

        (* Compute final piezo actuator command *)
        rControlOutput := (rKp * rError) + (rKi * rIntegral) + (rKd * rDerivative);

        (* Bound actuator signal to safe mechanical limits (0 to 1200 um) *)
        IF rControlOutput > 1200.0 THEN
            rControlOutput := 1200.0;
        ELSIF rControlOutput < 0.0 THEN
            rControlOutput := 0.0;
        END_IF;

        (* Transition to stable state if error is within tolerance for settling time *)
        IF ABS(rError) < 2.5 THEN
            tSettleTimer(IN := TRUE, PT := T#3S);
            IF tSettleTimer.Q THEN
                iState := 30;
            END_IF;
        ELSE
            tSettleTimer(IN := FALSE);
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    30: (* SYSTEM READY - ALIGNED *)
        bSystemReady := TRUE;
        tSettleTimer(IN := FALSE);

        (* Continue tracking slow thermal drifts *)
        rError := rTargetGapUm - rFilteredGap;
        IF ABS(rError) > 5.0 THEN
            bSystemReady := FALSE;
            iState := 20; (* Drop back to active tracking if drift exceeds 5um *)
        END_IF;

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

    99: (* FAULT HANDLING *)
        bSystemReady := FALSE;
        rControlOutput := 0.0;
        tAlignTimer(IN := FALSE);
        tSettleTimer(IN := FALSE);

        (* Reset requires Enable toggle and cleared faults *)
        IF NOT bEnable AND bEmergencyStop AND rScreenGridTemp < 1000.0 AND rAccelGridTemp < 1000.0 THEN
            bAlarm := FALSE;
            iState := 0;
        END_IF;

END_CASE;

(* Output current state to interface *)
iActiveState := iState;

END_FUNCTION_BLOCK
