TYPE "SCADA_Interface"
STRUCT
    Cmd_Start : BOOL;
    Cmd_Stop : BOOL;
    Sp_Temp : REAL;
    Act_Temp : REAL;
    Sys_Status : WORD;
    OperatorLevel : INT; // IEC 62443 Role-based access (1=Op, 2=Eng, 3=Admin)
END_STRUCT;
END_TYPE

FUNCTION_BLOCK "MilkPasteurizer_Secure"
VAR_INPUT
    SCADA_Data : "SCADA_Interface";
    IsPrimaryPLC : BOOL; // Redundancy status
    PartnerAlive : BOOL;
    TempSens1 : REAL;
    TempSens2 : REAL;
END_VAR

VAR_OUTPUT
    Heater_CV : REAL;
    FDV_Fwd : BOOL;
    FDV_Div : BOOL;
END_VAR

VAR
    ProcessActive : BOOL;
    ActiveTemp : REAL;
    PID_Inst : "PID_Compact";
    TMR_Hold : TON;
    SecurityFault : BOOL;
END_VAR

BEGIN
    // Redundancy Failover
    IF NOT IsPrimaryPLC AND PartnerAlive THEN
        // Standby mode, skip logic
        RETURN;
    END_IF;

    // IEC 62443 Access Control
    IF SCADA_Data.OperatorLevel < 1 THEN
        SecurityFault := TRUE;
        ProcessActive := FALSE;
    ELSE
        SecurityFault := FALSE;
    END_IF;

    // Sensor Redundancy / Averaging
    IF ABS(TempSens1 - TempSens2) > 2.0 THEN
        // Sensor deviation fault
        ActiveTemp := TempSens1; // Fallback
    ELSE
        ActiveTemp := (TempSens1 + TempSens2) / 2.0;
    END_IF;
    SCADA_Data.Act_Temp := ActiveTemp;

    // Process Control
    IF SCADA_Data.Cmd_Start AND NOT SCADA_Data.Cmd_Stop AND NOT SecurityFault THEN
        ProcessActive := TRUE;
    ELSIF SCADA_Data.Cmd_Stop OR SecurityFault THEN
        ProcessActive := FALSE;
    END_IF;

    // PID Control
    PID_Inst(
        sMode := 3,
        Setpoint := SCADA_Data.Sp_Temp,
        Input := ActiveTemp,
        Output => Heater_CV
    );

    // Holding and FDV
    TMR_Hold(IN := (ActiveTemp >= SCADA_Data.Sp_Temp) AND ProcessActive, PT := T#15S);

    IF ProcessActive AND TMR_Hold.Q THEN
        FDV_Fwd := TRUE;
        FDV_Div := FALSE;
        SCADA_Data.Sys_Status := 16#0001; // Forward Flow
    ELSE
        FDV_Fwd := FALSE;
        FDV_Div := TRUE;
        SCADA_Data.Sys_Status := 16#0002; // Divert
    END_IF;
END_FUNCTION_BLOCK
