`pascal
(*
===================================================================================================
MODULE: Kraft Recovery Boiler Controller
AUTHOR: Lumina Elite Synthetic Data Architect
VERSION: 2.1 (Production-Ready / Enterprise Grade)
STANDARD: IEC 61131-3 (Structured Text)
PROCESS: Pulp and Paper Mill - Kraft Recovery Boiler
===================================================================================================
DESCRIPTION:
This highly complex controller manages the critical operations of a Kraft Recovery Boiler:
1. Black Liquor Droplet Size Optimization: 
   Dynamically adjusts steam atomization pressure based on liquor viscosity and flow rate to 
   maintain an optimal droplet size (approx. 2-3 mm) for optimal drying and combustion.
2. Multi-Zonal Combustion Air Control (NOx Reduction): 
   Manages primary, secondary, and tertiary air zoning ratios and dampers to ensure a reducing 
   lower furnace and oxidizing upper furnace, thereby minimizing NOx formation while maximizing 
   reduction efficiency.
3. Smelt Dissolving Tank Acoustic Monitoring:
   Monitors acoustic signatures from the dissolving tank to detect localized micro-explosions 
   (smelt-water interactions). Triggers emergency shatter steam overrides and alarms before 
   catastrophic tank failure.

SAFETY INTERLOCKS:
- Boiler trip on acoustic anomaly (High amplitude + High frequency variance)
- Low shatter steam flow trip
- Air-to-Fuel ratio hard limits
- Black liquor dry solids < 65% trip (prevents water explosion in the hearth)

===================================================================================================
*)

TYPE
    // Acoustic monitoring data struct for the smelt dissolving tank
    SmeltAcousticData : STRUCT
        RMS_Amplitude       : REAL; // RMS amplitude of acoustic signal (dB)
        Peak_Frequency      : REAL; // Dominant frequency (Hz)
        Variance_Band       : REAL; // Variance in the 500Hz-2kHz band
        MicroExplosion_Cnt  : INT;  // Micro-explosion count over 10s rolling window
    END_STRUCT;

    // Combustion air distribution targets
    AirZoningTargets : STRUCT
        Primary_Ratio       : REAL; // Typically 35-40%
        Secondary_Ratio     : REAL; // Typically 40-45%
        Tertiary_Ratio      : REAL; // Typically 15-20%
        Total_Air_Flow      : REAL; // kg/s
    END_STRUCT;

    // Black liquor properties
    LiquorProperties : STRUCT
        Flow_Rate           : REAL; // kg/s
        Viscosity           : REAL; // cP
        Dry_Solids_Pct      : REAL; // %
        Temperature         : REAL; // degC
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_Kraft_Recovery_Boiler_Control
VAR_INPUT
    Enable                  : BOOL;             // Master enable
    System_Reset            : BOOL;             // Safety reset

    // Process Inputs
    Liquor_In               : LiquorProperties; // Black liquor data
    Smelt_Acoustics         : SmeltAcousticData;// Acoustic sensor data from dissolving tank

    // Environmental / Boiler state
    Furnace_Temp_Lower      : REAL; // degC
    Furnace_Temp_Upper      : REAL; // degC
    O2_Stack                : REAL; // % O2 at stack
    NOx_Stack               : REAL; // ppm

    // Setpoints
    SP_Excess_O2            : REAL := 2.5;      // Target Excess O2 %
    SP_Liquor_Droplet_Size  : REAL := 2.5;      // Target droplet size (mm)
END_VAR

VAR_OUTPUT
    // Actuators
    CV_Steam_Atomization    : REAL; // 0-100% control valve for atomizing steam
    CV_Primary_Air          : REAL; // 0-100% damper position
    CV_Secondary_Air        : REAL; // 0-100% damper position
    CV_Tertiary_Air         : REAL; // 0-100% damper position
    CV_Shatter_Steam        : REAL; // 0-100% shatter steam flow to dissolving tank

    // System States & Safety
    Boiler_Trip_Active      : BOOL; // TRUE if critical safety interlock is triggered
    Emergency_Shatter_Mode  : BOOL; // TRUE if acoustic anomalies detected
    Alarm_Low_Dry_Solids    : BOOL; // TRUE if dry solids < 65%
    Alarm_NOx_High          : BOOL; // TRUE if NOx > threshold
    Current_Droplet_Est     : REAL; // Estimated current droplet size (mm)
END_VAR

VAR
    // PID Controllers
    PID_Atomization         : FB_PID_Advanced;
    PID_Total_Air           : FB_PID_Advanced;

    // Timers
    TMR_Acoustic_Fault      : TON;
    TMR_Dry_Solids_Fault    : TON;

    // Internal Variables
    Air_Targets             : AirZoningTargets;
    Total_Combustion_Air    : REAL;
    Calculated_Viscosity_K  : REAL;

    // Constants
    CONST_VISC_REF          : REAL := 100.0;
    CONST_ACOUSTIC_DB_MAX   : REAL := 85.0;
    CONST_ACOUSTIC_VAR_MAX  : REAL := 15.0;
END_VAR

// ==============================================================================
// 1. SAFETY INTERLOCKS & FAULT MONITORING
// ==============================================================================
IF NOT Enable THEN
    Boiler_Trip_Active := TRUE;
    CV_Steam_Atomization := 0.0;
    CV_Primary_Air := 0.0;
    CV_Secondary_Air := 0.0;
    CV_Tertiary_Air := 0.0;
    CV_Shatter_Steam := 100.0; // Fail-safe: full shatter steam
    RETURN;
END_IF;

// Reset Logic
IF System_Reset THEN
    Boiler_Trip_Active := FALSE;
    Emergency_Shatter_Mode := FALSE;
END_IF;

// A. Dry Solids Interlock (Prevents water-smelt explosion in furnace hearth)
Alarm_Low_Dry_Solids := (Liquor_In.Dry_Solids_Pct < 65.0);
TMR_Dry_Solids_Fault(IN := Alarm_Low_Dry_Solids, PT := T#5S);
IF TMR_Dry_Solids_Fault.Q THEN
    Boiler_Trip_Active := TRUE;
END_IF;

// B. Smelt Dissolving Tank Acoustic Monitoring (Micro-explosion prevention)
// Detects heavy rumbling and high frequency variance indicating poor smelt shattering
IF (Smelt_Acoustics.RMS_Amplitude > CONST_ACOUSTIC_DB_MAX) AND 
   (Smelt_Acoustics.Variance_Band > CONST_ACOUSTIC_VAR_MAX) OR 
   (Smelt_Acoustics.MicroExplosion_Cnt >= 3) THEN

    TMR_Acoustic_Fault(IN := TRUE, PT := T#2S);
ELSE
    TMR_Acoustic_Fault(IN := FALSE, PT := T#2S);
END_IF;

IF TMR_Acoustic_Fault.Q THEN
    Emergency_Shatter_Mode := TRUE;
END_IF;

// Execute Trip State
IF Boiler_Trip_Active THEN
    CV_Steam_Atomization := 0.0;    // Shut off black liquor firing
    CV_Primary_Air := 10.0;         // Minimum purge air
    CV_Secondary_Air := 10.0;
    CV_Tertiary_Air := 10.0;
    CV_Shatter_Steam := 100.0;      // Maximize shattering
    RETURN;
END_IF;

// ==============================================================================
// 2. BLACK LIQUOR DROPLET SIZE OPTIMIZATION
// ==============================================================================
// Droplet size is a function of viscosity, flow rate, and atomizing steam pressure.
// We estimate droplet size using a simplified empirical correlation:
Calculated_Viscosity_K := Liquor_In.Viscosity / CONST_VISC_REF;
Current_Droplet_Est := 1.5 * Calculated_Viscosity_K * (Liquor_In.Flow_Rate / 10.0) / 
                       MAX(0.1, (CV_Steam_Atomization / 10.0));

// Control atomizing steam pressure to maintain SP_Liquor_Droplet_Size
PID_Atomization(
    Enable := TRUE,
    SP := SP_Liquor_Droplet_Size,
    PV := Current_Droplet_Est,
    Kp := 2.5,
    Ki := 0.5,
    Kd := 0.1,
    Direct_Action := FALSE, // Increase steam -> Decrease droplet size
    CV => CV_Steam_Atomization
);

// Limit steam valve to prevent total loss of atomization
IF CV_Steam_Atomization < 15.0 THEN
    CV_Steam_Atomization := 15.0;
END_IF;

// ==============================================================================
// 3. COMBUSTION AIR ZONING (NOx REDUCTION)
// ==============================================================================
// Total air demand based on liquor flow and dry solids (Stochiometric + Excess O2)
Total_Combustion_Air := (Liquor_In.Flow_Rate * (Liquor_In.Dry_Solids_Pct / 100.0) * 4.2) * (1.0 + SP_Excess_O2 / 100.0);

// NOx reduction strategy: 
// 1. Maintain a reducing environment in the lower furnace (low primary/secondary air)
// 2. Complete combustion in the upper furnace with tertiary air
// 3. Adjust tertiary air based on stack NOx levels

Air_Targets.Primary_Ratio := 0.35;
Air_Targets.Secondary_Ratio := 0.45;
Air_Targets.Tertiary_Ratio := 0.20;

// Dynamic NOx Trim
Alarm_NOx_High := (NOx_Stack > 150.0);
IF Alarm_NOx_High THEN
    // Shift air higher up the furnace to enhance staged combustion
    Air_Targets.Primary_Ratio := Air_Targets.Primary_Ratio - 0.05;
    Air_Targets.Secondary_Ratio := Air_Targets.Secondary_Ratio - 0.05;
    Air_Targets.Tertiary_Ratio := Air_Targets.Tertiary_Ratio + 0.10;
END_IF;

// Calculate final damper positions based on required flow (simplified linear mapping)
CV_Primary_Air := (Total_Combustion_Air * Air_Targets.Primary_Ratio) / 0.8; 
CV_Secondary_Air := (Total_Combustion_Air * Air_Targets.Secondary_Ratio) / 0.8;
CV_Tertiary_Air := (Total_Combustion_Air * Air_Targets.Tertiary_Ratio) / 0.8;

// Clamp Dampers
CV_Primary_Air := MIN(100.0, MAX(10.0, CV_Primary_Air));
CV_Secondary_Air := MIN(100.0, MAX(10.0, CV_Secondary_Air));
CV_Tertiary_Air := MIN(100.0, MAX(10.0, CV_Tertiary_Air));

// ==============================================================================
// 4. SMELT DISSOLVING TANK SHATTER STEAM CONTROL
// ==============================================================================
IF Emergency_Shatter_Mode THEN
    CV_Shatter_Steam := 100.0; // Blast max steam to break up large smelt streams
ELSE
    // Base shatter steam proportional to liquor flow (approximate smelt production)
    CV_Shatter_Steam := MAX(30.0, Liquor_In.Flow_Rate * 5.0);
    CV_Shatter_Steam := MIN(100.0, CV_Shatter_Steam);
END_IF;

END_FUNCTION_BLOCK
