FUNCTION_BLOCK "Crane_Breadth_Mutation"
TITLE = 'Crane Control with Profinet and Diagnostics'
VERSION : 1.0

VAR_INPUT
    Enable : Bool;
    HoistPos : Real;
    SwayAngle : Real;
    TwistLocked : Bool;
    TwistUnlocked : Bool;
    PayloadWeight : Real;
    Cmd_Lower : Bool;
    PN_DriveStatusWord : Word; // Profinet Status
END_VAR

VAR_OUTPUT
    HoistRef : Real;
    TrolleyRef : Real;
    SafetyFault : Bool;
    RegenActive : Bool;
    BrakeChopperPWM : Real;
    Diag_DriveReady : Bool;
    Diag_DriveFault : Bool;
END_VAR

VAR
    PID_AntiSway : "PID_Compact";
    SwayCorr : Real;
END_VAR

BEGIN
    // Profinet Diagnostics
    Diag_DriveReady := (PN_DriveStatusWord AND 16#0001) <> 0;
    Diag_DriveFault := (PN_DriveStatusWord AND 16#0008) <> 0;

    // Twist-lock Safety Interlock
    IF TwistLocked AND TwistUnlocked OR Diag_DriveFault THEN SafetyFault := TRUE; END_IF;

    // Hoist Kinematics
    IF HoistPos > 30.0 THEN HoistRef := 0.0; ELSE HoistRef := 1.0; END_IF;

    // Regenerative Braking
    IF Cmd_Lower AND PayloadWeight > 1000.0 AND Diag_DriveReady THEN
        RegenActive := TRUE;
        BrakeChopperPWM := PayloadWeight * 0.001;
    ELSE
        RegenActive := FALSE;
        BrakeChopperPWM := 0.0;
    END_IF;

    // Anti-Sway
    PID_AntiSway(Setpoint := 0.0, Input := SwayAngle, Output => SwayCorr);
    TrolleyRef := 1.0 - SwayCorr;
END_FUNCTION_BLOCK
