FUNCTION_BLOCK FB_SOEC_MasterControl
VAR_INPUT
    bEnable                 : BOOL;     (* System master enable signal *)
    bEmergencyStop          : BOOL;     (* Safety instrumented system OK (TRUE = OK) *)
    rStackTempCore          : REAL;     (* YSZ Core temperature feedback (Deg C) *)
    rSteamInletFlow         : REAL;     (* Steam inlet mass flow rate (kg/h) *)
    rHydrogenOutFlow        : REAL;     (* Hydrogen outlet mass flow rate (kg/h) *)
    rDCPowerBusVoltage      : REAL;     (* DC rectification bus voltage (V) *)
    rDCPowerBusCurrent      : REAL;     (* DC bus current draw (A) *)
    rThermalGradient        : REAL;     (* Calculated thermal gradient (Deg C/min) *)
END_VAR
VAR_OUTPUT
    bSystemReady            : BOOL;     (* Plant is pre-heated and ready for electrolysis *)
    bPurgeActive            : BOOL;     (* Nitrogen/Steam purge sequence active *)
    rDCVoltageSetpoint      : REAL;     (* Commanded DC bus voltage for rectifiers (V) *)
    rSteamValveCmd          : REAL;     (* 0-100% command to main steam inlet valve *)
    bThermalAlarm           : BOOL;     (* Thermal shock or over-temp limit exceeded *)
    bStackFault             : BOOL;     (* Stack degradation or electrical fault detected *)
END_VAR
VAR
    iState                  : INT := 0; (* Plant operational state machine *)
    tPreheatTimer           : TON;      (* Pre-heating phase timer *)
    tPurgeTimer             : TON;      (* Post-fault or startup purge timer *)
    rTempSetpoint           : REAL := 800.0; (* Optimal SOEC operational temperature *)
    rMaxGradient            : REAL := 5.0;   (* Max allowable thermal gradient DegC/min *)
    rPowerCalculated        : REAL;
    rEfficiencyH2           : REAL;
END_VAR

(* === MAIN SAFETY INTERLOCKS === *)
IF NOT bEmergencyStop THEN
    (* Immediate shed of all power and initiate safe shutdown *)
    bSystemReady := FALSE;
    rDCVoltageSetpoint := 0.0;
    rSteamValveCmd := 0.0;
    bPurgeActive := TRUE;
    iState := 99; (* E-STOP STATE *)
    RETURN;
END_IF;

(* === THERMAL GRADIENT PROTECTION === *)
IF ABS(rThermalGradient) > rMaxGradient THEN
    bThermalAlarm := TRUE;
    (* Throttle power to reduce gradient stress on YSZ ceramics *)
    rDCVoltageSetpoint := rDCVoltageSetpoint * 0.5;
END_IF;

(* === MAIN STATE MACHINE === *)
CASE iState OF
    0: (* SYSTEM OFF & STANDBY *)
        bSystemReady := FALSE;
        rDCVoltageSetpoint := 0.0;
        rSteamValveCmd := 0.0;
        bPurgeActive := FALSE;
        IF bEnable THEN
            iState := 10; (* Transition to Pre-heat *)
        END_IF;

    10: (* PRE-HEATING PHASE *)
        (* Steam is introduced slowly to raise temp to 800C *)
        rSteamValveCmd := 25.0;
        tPreheatTimer(IN := TRUE, PT := T#120S);
        IF rStackTempCore >= (rTempSetpoint - 50.0) AND tPreheatTimer.Q THEN
            tPreheatTimer(IN := FALSE);
            iState := 20; (* Ready for electrolysis *)
        END_IF;

    20: (* ELECTROLYSIS READY *)
        bSystemReady := TRUE;
        rSteamValveCmd := 50.0; (* Nominal flow *)
        (* Cascaded control: Base DC voltage on steam availability and desired H2 out *)
        rDCVoltageSetpoint := 1200.0; (* Base megawatt initialization *)

        IF bEnable THEN
            iState := 30; (* Full Production *)
        END_IF;

    30: (* FULL PRODUCTION CONTROL LOOP *)
        (* Calculate real-time plant efficiency *)
        rPowerCalculated := (rDCPowerBusVoltage * rDCPowerBusCurrent) / 1000.0; (* kW *)
        IF rPowerCalculated > 0.0 THEN
            rEfficiencyH2 := (rHydrogenOutFlow * 39.4) / rPowerCalculated; (* Approx kWh/kg check *)
        END_IF;

        (* Adjust steam based on H2 output to maintain optimal ratio *)
        IF rHydrogenOutFlow < 100.0 THEN
            rSteamValveCmd := rSteamValveCmd + 0.1;
        ELSIF rHydrogenOutFlow > 1000.0 THEN
            rSteamValveCmd := rSteamValveCmd - 0.1;
        END_IF;

        (* Check for stack degradation *)
        IF rDCPowerBusVoltage > 1500.0 AND rHydrogenOutFlow < 50.0 THEN
            bStackFault := TRUE;
            iState := 40; (* Safe Shutdown *)
        END_IF;

        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    40: (* CONTROLLED SHUTDOWN *)
        bSystemReady := FALSE;
        rDCVoltageSetpoint := 0.0;
        bPurgeActive := TRUE;
        tPurgeTimer(IN := TRUE, PT := T#300S);
        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE);
            bPurgeActive := FALSE;
            rSteamValveCmd := 0.0;
            iState := 0;
        END_IF;

    99: (* EMERGENCY STOP HANDLER *)
        (* E-Stop state locked until reset external *)
        IF bEmergencyStop AND NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
